window.__STUDY4_LISTEN_CHUNK = window.__STUDY4_LISTEN_CHUNK || {}; window.__STUDY4_LISTEN_CHUNK['u_5'] = {"unitId":"u_5","unitName":"Tổng hợp từ vựng theo chủ đề (Flashcards & SRS)","items":[{"id":"listening_u5_all","title":"🌟 Tất cả 10 Chủ đề (Trọn bộ 2,176 từ)","actTitle":"Tổng hợp toàn bộ 10 chủ đề Listening (2176 từ)","problem":{"pType":"topic_flashcards","topic":"All 10 Listening Topics","count":2176,"words":[{"id":"lv_0_0","topic":"Daily Life and Social Activities","word":"accompany","pos":"(v)","ipa":"/əˈkʌm.pə.ni/","defVi":"đi cùng, hộ tống, đồng hành","defEn":"to go somewhere with someone as a companion or guide","examples":["Children must be [accompanied] by an adult at the swimming pool. (=Dịch: Trẻ em phải có người lớn đi kèm khi ở hồ bơi.)","He offered to [accompany] her to the train station. (=Dịch: Anh ấy đã đề nghị đi cùng cô ấy ra ga tàu.)","A mild fever often [accompanies] the common cold. (=Dịch: Sốt nhẹ thường đi kèm với bệnh cảm lạnh thông thường.)"],"ukAudio":"/ai_services/tts3/?q=accompany&lang=en-GB&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=accompany&lang=en-US&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F"},{"id":"lv_0_1","topic":"Daily Life and Social Activities","word":"advanced","pos":"(adj)","ipa":"/ədˈvænst/","defVi":"nâng cao, tiên tiến","defEn":"at a higher, more difficult, or modern level","examples":["This course is designed for [advanced] learners of English. (=Dịch: Khóa học này được thiết kế dành cho người học tiếng Anh ở trình độ nâng cao.)","Scientists are using [advanced] technology to predict weather patterns. (=Dịch: Các nhà khoa học đang sử dụng công nghệ tiên tiến để dự đoán các hình thái thời tiết.)","The country has an [advanced] public healthcare system. (=Dịch: Quốc gia này có một hệ thống y tế công cộng tiên tiến.)"],"ukAudio":"/ai_services/tts3/?q=advanced&lang=en-GB&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F","usAudio":"/ai_services/tts3/?q=advanced&lang=en-US&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F"},{"id":"lv_0_2","topic":"Daily Life and Social Activities","word":"amazed","pos":"(adj)","ipa":"/əˈmeɪzd/","defVi":"kinh ngạc, vô cùng ngạc nhiên","defEn":"extremely surprised or impressed by something","examples":["I was [amazed] at how quickly the children learned the new language. (=Dịch: Tôi đã rất kinh ngạc trước việc lũ trẻ học ngôn ngữ mới nhanh đến thế.)","Visitors were [amazed] by the beauty of the ancient temple. (=Dịch: Du khách đã vô cùng kinh ngạc trước vẻ đẹp của ngôi đền cổ.)","She was [amazed] to discover that she had won first prize. (=Dịch: Cô ấy đã rất ngạc nhiên khi biết mình đạt giải nhất.)"],"ukAudio":"/ai_services/tts3/?q=amazed&lang=en-GB&ipa=%2F%C9%99%CB%88me%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=amazed&lang=en-US&ipa=%2F%C9%99%CB%88me%C9%AAzd%2F"},{"id":"lv_0_3","topic":"Daily Life and Social Activities","word":"ambition","pos":"(n)","ipa":"/æmˈbɪʃ.ən/","defVi":"tham vọng, hoài bão","defEn":"a strong desire to achieve success, power, or a specific goal","examples":["Her lifelong [ambition] is to become a successful doctor. (=Dịch: Hoài bão cả đời của cô ấy là trở thành một bác sĩ thành đạt.)","He lacks the [ambition] needed to reach the top of his profession. (=Dịch: Anh ấy thiếu tham vọng cần thiết để vươn tới đỉnh cao trong nghề nghiệp của mình.)","The company has clear [ambitions] to expand into international markets. (=Dịch: Công ty có những tham vọng rõ ràng nhằm mở rộng ra các thị trường quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=ambition&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=ambition&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_0_4","topic":"Daily Life and Social Activities","word":"antique","pos":"(n)","ipa":"/ænˈtiːk/","defVi":"đồ cổ","defEn":"an object that is old and often valuable because of its age or quality","examples":["This wooden table is a valuable [antique] from the nineteenth century. (=Dịch: Chiếc bàn gỗ này là một món đồ cổ có giá trị từ thế kỷ 19.)","She loves spending her weekends browsing [antique] shops. (=Dịch: Cô ấy thích dành những ngày cuối tuần để dạo xem các cửa hàng đồ cổ.)","The museum displays rare [antiques] collected from all over the world. (=Dịch: Bảo tàng trưng bày các cổ vật quý hiếm được sưu tầm từ khắp nơi trên thế giới.)"],"ukAudio":"/ai_services/tts3/?q=antique&lang=en-GB&ipa=%2F%C3%A6n%CB%88ti%CB%90k%2F","usAudio":"/ai_services/tts3/?q=antique&lang=en-US&ipa=%2F%C3%A6n%CB%88ti%CB%90k%2F"},{"id":"lv_0_5","topic":"Daily Life and Social Activities","word":"anymore","pos":"(adv)","ipa":"/ˌen.iˈmɔːr/","defVi":"nữa, không còn nữa","defEn":"any longer; used in negative statements to show that a situation has ended","examples":["He does not live in that city [anymore]. (=Dịch: Anh ấy không còn sống ở thành phố đó nữa.)","They rarely talk to each other [anymore]. (=Dịch: Họ hiếm khi nói chuyện với nhau nữa.)","I don't think we need this old equipment [anymore]. (=Dịch: Tôi không nghĩ chúng ta còn cần thiết bị cũ này nữa.)"],"ukAudio":"/ai_services/tts3/?q=anymore&lang=en-GB&ipa=%2F%CB%8Cen.i%CB%88m%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=anymore&lang=en-US&ipa=%2F%CB%8Cen.i%CB%88m%C9%94%CB%90r%2F"},{"id":"lv_0_6","topic":"Daily Life and Social Activities","word":"applicant","pos":"(n)","ipa":"/ˈæp.lɪ.kənt/","defVi":"người nộp đơn, ứng viên","defEn":"a person who formally applies for something, especially a job or a place at a university","examples":["There were more than fifty [applicants] for the marketing position. (=Dịch: Đã có hơn 50 ứng viên ứng tuyển vào vị trí tiếp thị.)","Successful [applicants] will be contacted within two weeks. (=Dịch: Những ứng viên trúng tuyển sẽ được liên hệ trong vòng hai tuần.)","Each [applicant] must submit a resume and two letters of recommendation. (=Dịch: Mỗi ứng viên phải nộp một sơ yếu lý lịch và hai thư giới thiệu.)"],"ukAudio":"/ai_services/tts3/?q=applicant&lang=en-GB&ipa=%2F%CB%88%C3%A6p.l%C9%AA.k%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=applicant&lang=en-US&ipa=%2F%CB%88%C3%A6p.l%C9%AA.k%C9%99nt%2F"},{"id":"lv_0_7","topic":"Daily Life and Social Activities","word":"appointment","pos":"(n)","ipa":"/əˈpɔɪnt.mənt/","defVi":"cuộc hẹn, lịch hẹn","defEn":"an arrangement to see someone at a specific time and place","examples":["I made an [appointment] with my doctor for tomorrow morning. (=Dịch: Tôi đã đặt lịch hẹn với bác sĩ vào sáng mai.)","She had to cancel her dental [appointment] due to a meeting. (=Dịch: Cô ấy đã phải hủy cuộc hẹn khám răng vì một cuộc họp.)","Please arrive on time for your visa [appointment]. (=Dịch: Vui lòng đến đúng giờ cho cuộc hẹn xin thị thực của bạn.)"],"ukAudio":"/ai_services/tts3/?q=appointment&lang=en-GB&ipa=%2F%C9%99%CB%88p%C9%94%C9%AAnt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=appointment&lang=en-US&ipa=%2F%C9%99%CB%88p%C9%94%C9%AAnt.m%C9%99nt%2F"},{"id":"lv_0_8","topic":"Daily Life and Social Activities","word":"aquarium","pos":"(n)","ipa":"/əˈkwer.i.əm/","defVi":"bể nuôi cá, thủy cung","defEn":"a glass tank or a building where fish and other water animals are kept for study or display","examples":["We took the children to the city [aquarium] to see the sharks. (=Dịch: Chúng tôi đã đưa lũ trẻ đến thủy cung thành phố để ngắm cá mập.)","He keeps several colorful tropical fish in his home [aquarium]. (=Dịch: Anh ấy nuôi vài chú cá nhiệt đới sặc sỡ trong bể cá tại nhà.)","The new [aquarium] features marine life from coral reefs around the world. (=Dịch: Thủy cung mới trưng bày các loài sinh vật biển từ các rạn san hô trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=aquarium&lang=en-GB&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=aquarium&lang=en-US&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F"},{"id":"lv_0_9","topic":"Daily Life and Social Activities","word":"asthma","pos":"(n)","ipa":"/ˈæz.mə/","defVi":"bệnh hen suyễn","defEn":"a chronic medical condition that causes difficulty in breathing","examples":["Cold weather can often trigger a severe [asthma] attack. (=Dịch: Thời tiết lạnh thường có thể gây ra một cơn hen suyễn nghiêm trọng.)","He always carries an inhaler because he suffers from [asthma]. (=Dịch: Anh ấy luôn mang theo ống hít vì bị bệnh hen suyễn.)","Air pollution is known to worsen symptoms of childhood [asthma]. (=Dịch: Ô nhiễm không khí được biết là làm trầm trọng thêm các triệu chứng hen suyễn ở trẻ em.)"],"ukAudio":"/ai_services/tts3/?q=asthma&lang=en-GB&ipa=%2F%CB%88%C3%A6z.m%C9%99%2F","usAudio":"/ai_services/tts3/?q=asthma&lang=en-US&ipa=%2F%CB%88%C3%A6z.m%C9%99%2F"},{"id":"lv_0_10","topic":"Daily Life and Social Activities","word":"attic","pos":"(n)","ipa":"/ˈæt̬.ɪk/","defVi":"gác xép, tầng áp mái","defEn":"a room or space just below the roof of a house","examples":["We found a box of old photographs stored in the [attic]. (=Dịch: Chúng tôi tìm thấy một hộp ảnh cũ được cất trên gác mái.)","She decided to convert the dusty [attic] into a quiet study room. (=Dịch: Cô ấy quyết định cải tạo căn gác mái đầy bụi thành một phòng học yên tĩnh.)","During the storm, we could hear the rain pounding above the [attic]. (=Dịch: Trong suốt cơn bão, chúng tôi có thể nghe thấy tiếng mưa trút xuống ngay trên gác mái.)"],"ukAudio":"/ai_services/tts3/?q=attic&lang=en-GB&ipa=%2F%CB%88%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=attic&lang=en-US&ipa=%2F%CB%88%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_0_11","topic":"Daily Life and Social Activities","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"điểm thu hút, điểm tham quan; sức hấp dẫn","defEn":"an interesting or lively place to visit, or a feature that makes something appealing","examples":["The Eiffel Tower is a major tourist [attraction] in Paris. (=Dịch: Tháp Eiffel là một điểm thu hút khách du lịch lớn ở Paris.)","Low cost of living is one of the main [attraction]s of moving to this city. (=Dịch: Chi phí sinh hoạt thấp là một trong những điểm hấp dẫn chính khi chuyển đến thành phố này.)","The museum added a new interactive [attraction] for young children. (=Dịch: Bảo tàng đã bổ sung một điểm trải nghiệm tương tác mới dành cho trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_0_12","topic":"Daily Life and Social Activities","word":"avenue","pos":"(n)","ipa":"/ˈæv.ə.nuː/","defVi":"đại lộ; con đường, hướng tiếp cận","defEn":"a wide street in a town or city, or a possible way of achieving something","examples":["Trees were planted on both sides of the broad [avenue]. (=Dịch: Cây xanh được trồng ở cả hai bên của đại lộ rộng lớn.)","Scientists are exploring every possible [avenue] of research to find a cure. (=Dịch: Các nhà khoa học đang khám phá mọi hướng nghiên cứu có thể để tìm ra phương pháp chữa trị.)","The luxury hotel is located on Fifth [Avenue]. (=Dịch: Khách sạn sang trọng này tọa lạc trên Đại lộ số 5.)"],"ukAudio":"/ai_services/tts3/?q=avenue&lang=en-GB&ipa=%2F%CB%88%C3%A6v.%C9%99.nu%CB%90%2F","usAudio":"/ai_services/tts3/?q=avenue&lang=en-US&ipa=%2F%CB%88%C3%A6v.%C9%99.nu%CB%90%2F"},{"id":"lv_0_13","topic":"Daily Life and Social Activities","word":"backpack","pos":"(n)","ipa":"/ˈbæk.pæk/","defVi":"ba lô","defEn":"a bag with shoulder straps that allows it to be carried on one's back","examples":["He packed a few clothes and a water bottle into his [backpack]. (=Dịch: Anh ấy xếp vài bộ quần áo và một chai nước vào ba lô của mình.)","Carrying a heavy [backpack] every day can cause back pain for students. (=Dịch: Đeo ba lô nặng mỗi ngày có thể gây đau lưng cho học sinh.)","She zipped up her [backpack] and headed for the train station. (=Dịch: Cô ấy kéo khóa ba lô lại rồi hướng về phía nhà ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=backpack&lang=en-GB&ipa=%2F%CB%88b%C3%A6k.p%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=backpack&lang=en-US&ipa=%2F%CB%88b%C3%A6k.p%C3%A6k%2F"},{"id":"lv_0_14","topic":"Daily Life and Social Activities","word":"backpacker","pos":"(n)","ipa":"/ˈbækˌpæk.ɚ/","defVi":"khách du lịch bụi, dân phượt","defEn":"a person who travels cheaply carrying their belongings in a backpack","examples":["The hostel is extremely popular among young [backpacker]s from Europe. (=Dịch: Nhà nghỉ giá rẻ này cực kỳ phổ biến đối với những bạn trẻ đi du lịch bụi đến từ châu Âu.)","As a budget [backpacker], he prefers cooking his own meals to save money. (=Dịch: Là một người đi du lịch bụi tiết kiệm, anh ấy thích tự nấu ăn để tiết kiệm chi phí.)","Many [backpacker]s visit Southeast Asia for its rich culture and low costs. (=Dịch: Nhiều khách du lịch bụi ghé thăm Đông Nam Á vì nền văn hóa phong phú và chi phí rẻ.)"],"ukAudio":"/ai_services/tts3/?q=backpacker&lang=en-GB&ipa=%2F%CB%88b%C3%A6k%CB%8Cp%C3%A6k.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=backpacker&lang=en-US&ipa=%2F%CB%88b%C3%A6k%CB%8Cp%C3%A6k.%C9%9A%2F"},{"id":"lv_0_15","topic":"Daily Life and Social Activities","word":"badminton","pos":"(n)","ipa":"/ˈbæd.mɪn.tən/","defVi":"môn cầu lông","defEn":"a racquet sport played using shuttles across a net","examples":["They usually play [badminton] in the park on weekend mornings. (=Dịch: Họ thường chơi cầu lông trong công viên vào các buổi sáng cuối tuần.)","You need quick reflexes and good agility to excel at [badminton]. (=Dịch: Bạn cần có phản xạ nhanh và sự nhanh nhẹn tốt để chơi xuất sắc môn cầu lông.)","She bought a new pair of shoes designed specifically for [badminton]. (=Dịch: Cô ấy đã mua một đôi giày mới được thiết kế dành riêng cho môn cầu lông.)"],"ukAudio":"/ai_services/tts3/?q=badminton&lang=en-GB&ipa=%2F%CB%88b%C3%A6d.m%C9%AAn.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=badminton&lang=en-US&ipa=%2F%CB%88b%C3%A6d.m%C9%AAn.t%C9%99n%2F"},{"id":"lv_0_16","topic":"Daily Life and Social Activities","word":"balcony","pos":"(n)","ipa":"/ˈbæl.kə.ni/","defVi":"ban công","defEn":"a platform enclosed by a railing projecting from the wall of a building","examples":["We enjoyed having our morning coffee on the hotel [balcony]. (=Dịch: Chúng tôi rất thích thưởng thức cà phê buổi sáng ngoài ban công khách sạn.)","She filled her small apartment [balcony] with colorful flowers and potted plants. (=Dịch: Cô ấy lấp đầy ban công căn hộ nhỏ của mình bằng những bông hoa rực rỡ và các chậu cây cảnh.)","From the [balcony], you can see a breathtaking view of the ocean. (=Dịch: Từ ban công, bạn có thể chiêm ngưỡng khung cảnh tuyệt đẹp của đại dương.)"],"ukAudio":"/ai_services/tts3/?q=balcony&lang=en-GB&ipa=%2F%CB%88b%C3%A6l.k%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=balcony&lang=en-US&ipa=%2F%CB%88b%C3%A6l.k%C9%99.ni%2F"},{"id":"lv_0_17","topic":"Daily Life and Social Activities","word":"ballet","pos":"(n)","ipa":"/bæˈleɪ/","defVi":"múa ba lê","defEn":"a classical artistic dance form characterized by precise and graceful movements","examples":["She has been taking [ballet] lessons since she was five years old. (=Dịch: Cô ấy đã học múa ba lê từ khi mới năm tuổi.)","The theater is hosting a famous Russian [ballet] performance tonight. (=Dịch: Tối nay nhà hát tổ chức một buổi biểu diễn múa ba lê Nga nổi tiếng.)","Professional [ballet] dancers require tremendous discipline and physical strength. (=Dịch: Các vũ công ba lê chuyên nghiệp đòi hỏi tính kỷ luật cao và thể lực phi thường.)"],"ukAudio":"/ai_services/tts3/?q=ballet&lang=en-GB&ipa=%2Fb%C3%A6%CB%88le%C9%AA%2F","usAudio":"/ai_services/tts3/?q=ballet&lang=en-US&ipa=%2Fb%C3%A6%CB%88le%C9%AA%2F"},{"id":"lv_0_18","topic":"Daily Life and Social Activities","word":"balloon","pos":"(n)","ipa":"/bəˈluːn/","defVi":"bóng bay, khinh khí cầu","defEn":"a flexible bag inflated with air or gas, used as a toy or decoration","examples":["They decorated the party room with colorful [balloon]s and streamers. (=Dịch: Họ trang trí phòng tiệc bằng những quả bóng bay rực rỡ sắc màu và dây kim tuyến.)","The child cried when his helium [balloon] floated up into the sky. (=Dịch: Đứa trẻ òa khóc khi quả bóng bay khí heli của mình bay vút lên bầu trời.)","Taking a hot-air [balloon] ride over the valley was an unforgettable experience. (=Dịch: Đi khinh khí cầu ngắm nhìn thung lũng là một trải nghiệm khó quên.)"],"ukAudio":"/ai_services/tts3/?q=balloon&lang=en-GB&ipa=%2Fb%C9%99%CB%88lu%CB%90n%2F","usAudio":"/ai_services/tts3/?q=balloon&lang=en-US&ipa=%2Fb%C9%99%CB%88lu%CB%90n%2F"},{"id":"lv_0_19","topic":"Daily Life and Social Activities","word":"bamboo","pos":"(n)","ipa":"/bæmˈbu/","defVi":"cây tre, nứa","defEn":"a tall tropical grass with hard, hollow stems used for building or making things","examples":["Pandas feed almost entirely on [bamboo]. (=Dịch: Gấu trúc gần như chỉ ăn [tre].)","The local builders used [bamboo] to construct the scaffolding. (=Dịch: Những người thợ xây địa phương đã sử dụng [tre] để dựng giàn giáo.)","This cutting board is made from eco-friendly [bamboo]. (=Dịch: Chiếc thớt này được làm từ [tre] thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=bamboo&lang=en-GB&ipa=%2Fb%C3%A6m%CB%88bu%2F","usAudio":"/ai_services/tts3/?q=bamboo&lang=en-US&ipa=%2Fb%C3%A6m%CB%88bu%2F"},{"id":"lv_0_20","topic":"Daily Life and Social Activities","word":"barbecue","pos":"(n)","ipa":"/ˈbɑr.bə.kju/","defVi":"tiệc nướng ngoài trời, món thịt nướng","defEn":"an outdoor meal or party where food is cooked over an open fire or grill","examples":["We are having a [barbecue] in the backyard this Saturday. (=Dịch: Chúng tôi sẽ tổ chức một bữa tiệc [thịt nướng] ở sân sau vào thứ Bảy này.)","He grilled some chicken and sausages on the [barbecue]. (=Dịch: Anh ấy đã nướng một ít thịt gà và xúc xích trên [bếp nướng].)","They served delicious pork ribs with homemade [barbecue] sauce. (=Dịch: Họ phục vụ món sườn heo thơm ngon với sốt [thịt nướng] tự làm.)"],"ukAudio":"/ai_services/tts3/?q=barbecue&lang=en-GB&ipa=%2F%CB%88b%C9%91r.b%C9%99.kju%2F","usAudio":"/ai_services/tts3/?q=barbecue&lang=en-US&ipa=%2F%CB%88b%C9%91r.b%C9%99.kju%2F"},{"id":"lv_0_21","topic":"Daily Life and Social Activities","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a part of the coast where the land curves inward to form a wide opening","examples":["The hotel room has a magnificent view of the [bay]. (=Dịch: Phòng khách sạn có tầm nhìn tuyệt đẹp ra [vịnh].)","Several fishing boats were anchored safely in the [bay]. (=Dịch: Một vài chiếc thuyền đánh cá đã neo đậu an toàn trong [vịnh].)","Ha Long [Bay] is one of the most famous tourist attractions in Vietnam. (=Dịch: [Vịnh] Hạ Long là một trong những điểm du lịch nổi tiếng nhất ở Việt Nam.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_0_22","topic":"Daily Life and Social Activities","word":"bedsit","pos":"(n)","ipa":"/ˈbed.sɪt/","defVi":"phòng trọ khép kín (vừa làm phòng khách, phòng ngủ)","defEn":"a rented room used for both living and sleeping, usually with shared bathroom facilities","examples":["As a university student, he lived in a small [bedsit] near the campus. (=Dịch: Khi còn là sinh viên đại học, anh ấy sống trong một [căn phòng trọ khép kín] nhỏ gần khuôn viên trường.)","Renting a [bedsit] is a budget-friendly option for young professionals. (=Dịch: Thuê một [căn phòng trọ nhỏ] là một lựa chọn tiết kiệm chi phí cho những người trẻ mới đi làm.)","Her tiny [bedsit] only had space for a single bed and a desk. (=Dịch: [Căn phòng trọ] nhỏ bé của cô chỉ có đủ chỗ cho một chiếc giường đơn và một chiếc bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=bedsit&lang=en-GB&ipa=%2F%CB%88bed.s%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bedsit&lang=en-US&ipa=%2F%CB%88bed.s%C9%AAt%2F"},{"id":"lv_0_23","topic":"Daily Life and Social Activities","word":"behalf","pos":"(n)","ipa":"/bɪˈhæf/","defVi":"sự thay mặt, đại diện","defEn":"as a representative of someone, or in the interest of someone","examples":["I am writing this email on [behalf] of the marketing department. (=Dịch: Tôi viết email này thay [mặt] bộ phận tiếp thị.)","The lawyer spoke on [behalf] of his client in court. (=Dịch: Luật sư đã thay [mặt] thân chủ của mình phát biểu trước tòa.)","She accepted the award on [behalf] of the entire research team. (=Dịch: Cô ấy đã nhận giải thưởng thay [mặt] toàn bộ nhóm nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=behalf&lang=en-GB&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=behalf&lang=en-US&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F"},{"id":"lv_0_24","topic":"Daily Life and Social Activities","word":"belonging","pos":"(n)","ipa":"/bɪˈlɔŋ.ɪŋ/","defVi":"đồ dùng cá nhân; cảm giác thuộc về","defEn":"a person's movable possession; the state of being part of a group or place","examples":["Please check your seat to make sure you have left no personal [belonging] behind. (=Dịch: Vui lòng kiểm tra chỗ ngồi để đảm bảo bạn không để quên bất kỳ [đồ dùng] cá nhân nào.)","Schools should foster a strong sense of [belonging] among students. (=Dịch: Các trường học nên bồi đắp [cảm giác thuộc về] mạnh mẽ cho học sinh.)","Every single [belonging] was packed carefully into cardboard boxes. (=Dịch: Từng món [đồ đạc] đều được đóng gói cẩn thận vào các thùng carton.)"],"ukAudio":"/ai_services/tts3/?q=belonging&lang=en-GB&ipa=%2Fb%C9%AA%CB%88l%C9%94%C5%8B.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=belonging&lang=en-US&ipa=%2Fb%C9%AA%CB%88l%C9%94%C5%8B.%C9%AA%C5%8B%2F"},{"id":"lv_0_25","topic":"Daily Life and Social Activities","word":"bent","pos":"(adj)","ipa":"/bent/","defVi":"bị cong, gập lại; kiên quyết làm gì","defEn":"curved or no longer straight; having an inclination toward something","examples":["The bicycle wheel was badly [bent] after the collision. (=Dịch: Bánh xe đạp bị [cong] nặng sau vụ va chạm.)","He sat for hours with a [bent] back, working on his computer. (=Dịch: Anh ấy ngồi hàng giờ với chiếc lưng [còng] để làm việc trên máy tính.)","She seems [bent] on finishing the project before the weekend. (=Dịch: Cô ấy có vẻ [quyết tâm] hoàn thành dự án trước cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=bent&lang=en-GB&ipa=%2Fbent%2F","usAudio":"/ai_services/tts3/?q=bent&lang=en-US&ipa=%2Fbent%2F"},{"id":"lv_0_26","topic":"Daily Life and Social Activities","word":"bet","pos":"(v)","ipa":"/bet/","defVi":"đánh cược, cá cược; dám chắc","defEn":"to risk money on the result of an event or competition; to feel sure about something","examples":["He lost a lot of money when he decided to [bet] on horse racing. (=Dịch: Anh ấy đã mất rất nhiều tiền khi quyết định [cá cược] vào môn đua ngựa.)","I [bet] that it will rain before the afternoon is over. (=Dịch: Tôi [cá] rằng trời sẽ mưa trước khi buổi chiều kết thúc.)","Never [bet] more than you can afford to lose. (=Dịch: Đừng bao giờ [đặt cược] nhiều hơn số tiền bạn có thể chấp nhận mất.)"],"ukAudio":"/ai_services/tts3/?q=bet&lang=en-GB&ipa=%2Fbet%2F","usAudio":"/ai_services/tts3/?q=bet&lang=en-US&ipa=%2Fbet%2F"},{"id":"lv_0_27","topic":"Daily Life and Social Activities","word":"blanket","pos":"(n)","ipa":"/ˈblæŋ.kɪt/","defVi":"chiếc chăn, mền","defEn":"a thick, warm cover made of wool or cloth used on a bed","examples":["She pulled the wool [blanket] over her shoulders to stay warm. (=Dịch: Cô kéo chiếc [chăn] len qua vai để giữ ấm.)","A thick [blanket] of snow covered the entire village overnight. (=Dịch: Một [lớp] tuyết dày đã bao phủ toàn bộ ngôi làng chỉ sau một đêm.)","The flight attendant gave each passenger a pillow and a [blanket]. (=Dịch: Tiếp viên hàng không đã phát cho mỗi hành khách một chiếc gối và một chiếc [chăn].)"],"ukAudio":"/ai_services/tts3/?q=blanket&lang=en-GB&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=blanket&lang=en-US&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F"},{"id":"lv_0_28","topic":"Daily Life and Social Activities","word":"blind","pos":"(adj)","ipa":"/blaɪnd/","defVi":"mù, khiếm thị; mù quáng","defEn":"unable to see; not noticing or realizing something clearly","examples":["Guide dogs are specially trained to assist [blind] people. (=Dịch: Chó dẫn đường được huấn luyện đặc biệt để hỗ trợ người [khiếm thị].)","He was completely [blind] to the risks involved in the investment. (=Dịch: Anh ấy hoàn toàn [mù quáng] trước những rủi ro đi kèm với khoản đầu tư.)","The sudden flash of bright light made her momentarily [blind]. (=Dịch: Ánh sáng chói lóa đột ngột khiến cô ấy tạm thời bị [lóa mắt/mù tạm thời].)"],"ukAudio":"/ai_services/tts3/?q=blind&lang=en-GB&ipa=%2Fbla%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=blind&lang=en-US&ipa=%2Fbla%C9%AAnd%2F"},{"id":"lv_0_29","topic":"Daily Life and Social Activities","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, nhà sách","defEn":"a shop that sells books","examples":["I spent the entire afternoon browsing in a small second-hand [bookshop]. (=Dịch: Tôi đã dành cả buổi chiều để dạo xem sách trong một hiệu sách cũ nhỏ.)","The local [bookshop] is hosting a signing event with a famous author this weekend. (=Dịch: Hiệu sách địa phương sẽ tổ chức một buổi ký tặng sách với một tác giả nổi tiếng vào cuối tuần này.)","You can order academic textbooks directly from the university [bookshop]. (=Dịch: Bạn có thể đặt mua giáo trình học thuật trực tiếp từ hiệu sách của trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_0_30","topic":"Daily Life and Social Activities","word":"botanical","pos":"(adj)","ipa":"/bəˈtæn.ɪ.kəl/","defVi":"(thuộc) thực vật học","defEn":"connected with the scientific study of plants","examples":["The city is famous for its extensive [botanical] gardens filled with rare flowers. (=Dịch: Thành phố này nổi tiếng với các vườn bách thảo rộng lớn tràn ngập các loài hoa quý hiếm.)","Researchers collected various [botanical] specimens during their expedition in the rainforest. (=Dịch: Các nhà nghiên cứu đã thu thập nhiều mẫu thực vật khác nhau trong chuyến thám hiểm rừng nhiệt đới.)","This skincare cream contains natural [botanical] extracts that soothe the skin. (=Dịch: Loại kem dưỡng da này chứa các chiết xuất thực vật tự nhiên giúp làm dịu da.)"],"ukAudio":"/ai_services/tts3/?q=botanical&lang=en-GB&ipa=%2Fb%C9%99%CB%88t%C3%A6n.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=botanical&lang=en-US&ipa=%2Fb%C9%99%CB%88t%C3%A6n.%C9%AA.k%C9%99l%2F"},{"id":"lv_0_31","topic":"Daily Life and Social Activities","word":"bother","pos":"(v)","ipa":"/ˈbɑː.ðɚ/","defVi":"làm phiền, bận tâm, quấy rầy","defEn":"to annoy, worry, or cause trouble to someone","examples":["I am sorry to [bother] you, but could you help me carry these heavy boxes? (=Dịch: Xin lỗi vì đã làm phiền bạn, nhưng bạn có thể giúp tôi khiêng những chiếc hộp nặng này được không?)","Loud traffic noises from the street do not seem to [bother] him at all. (=Dịch: Tiếng ồn giao thông lớn từ đường phố dường như không làm phiền anh ấy chút nào.)","She did not even [bother] to reply to my email after I sent it twice. (=Dịch: Cô ấy thậm chí còn chẳng buồn trả lời email sau khi tôi đã gửi tới hai lần.)"],"ukAudio":"/ai_services/tts3/?q=bother&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F","usAudio":"/ai_services/tts3/?q=bother&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F"},{"id":"lv_0_32","topic":"Daily Life and Social Activities","word":"bow","pos":"(v)","ipa":"/baʊ/","defVi":"cúi đầu, cúi chào","defEn":"to bend your head or body forward as a sign of respect or greeting","examples":["In Japan, it is customary to [bow] politely when greeting someone for the first time. (=Dịch: Ở Nhật Bản, cúi chào một cách lịch sự khi chào hỏi ai đó lần đầu tiên là một phong tục.)","The actors came onto the stage together to [bow] to the applauding audience. (=Dịch: Các diễn viên cùng nhau bước lên sân khấu để cúi chào khán giả đang vỗ tay tán thưởng.)","He had to [bow] his head slightly to avoid hitting the low ceiling doorway. (=Dịch: Anh ấy phải hơi cúi đầu xuống để tránh va vào khung cửa trần thấp.)"],"ukAudio":"/ai_services/tts3/?q=bow&lang=en-GB&ipa=%2Fba%CA%8A%2F","usAudio":"/ai_services/tts3/?q=bow&lang=en-US&ipa=%2Fba%CA%8A%2F"},{"id":"lv_0_33","topic":"Daily Life and Social Activities","word":"brochure","pos":"(n)","ipa":"/broʊˈʃʊr/","defVi":"sách/tờ rơi quảng cáo, tài liệu giới thiệu","defEn":"a small booklet containing pictures and information about a product or service","examples":["We picked up a travel [brochure] at the tourism office to plan our holiday itinerary. (=Dịch: Chúng tôi đã lấy một cuốn cẩm nang du lịch tại văn phòng du lịch để lên lịch trình cho kỳ nghỉ.)","The company published a detailed [brochure] highlighting its latest line of software. (=Dịch: Công ty đã phát hành một cuốn tài liệu quảng cáo chi tiết nêu bật dòng phần mềm mới nhất của mình.)","Prospective students can read the college [brochure] to learn more about available courses. (=Dịch: Các sinh viên tương lai có thể đọc tài liệu giới thiệu của trường đại học để tìm hiểu thêm về các khóa học hiện có.)"],"ukAudio":"/ai_services/tts3/?q=brochure&lang=en-GB&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=brochure&lang=en-US&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_0_34","topic":"Daily Life and Social Activities","word":"buffet","pos":"(n)","ipa":"/bəˈfeɪ/","defVi":"tiệc buffet, bữa ăn tự chọn","defEn":"a meal where people serve themselves from a table containing different dishes","examples":["The hotel offers a complimentary breakfast [buffet] with a wide selection of hot dishes. (=Dịch: Khách sạn phục vụ bữa sáng tự chọn miễn phí với nhiều lựa chọn món nóng phong phú.)","Guests enjoyed the seafood [buffet] at the wedding reception last night. (=Dịch: Khách mời đã thưởng thức tiệc tự chọn hải sản tại tiệc cưới tối qua.)","We decided to eat at an all-you-can-eat barbecue [buffet] for our celebration dinner. (=Dịch: Chúng tôi quyết định ăn tại một bữa tiệc nướng tự chọn không giới hạn cho bữa tối liên hoan.)"],"ukAudio":"/ai_services/tts3/?q=buffet&lang=en-GB&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=buffet&lang=en-US&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F"},{"id":"lv_0_35","topic":"Daily Life and Social Activities","word":"bulb","pos":"(n)","ipa":"/bʌlb/","defVi":"bóng đèn","defEn":"a glass object that produces light when electricity passes through it","examples":["The light [bulb] in the kitchen burned out and needs to be replaced immediately. (=Dịch: Bóng đèn trong bếp đã bị cháy và cần được thay thế ngay lập tức.)","Switching to energy-efficient LED [bulb] options can significantly reduce your electricity bill. (=Dịch: Chuyển sang các lựa chọn bóng đèn LED tiết kiệm năng lượng có thể giúp giảm đáng kể hóa đơn tiền điện của bạn.)","She adjusted the desk lamp and screwed in a softer, warmer [bulb] for reading. (=Dịch: Cô ấy đã điều chỉnh đèn bàn và vặn vào một bóng đèn có ánh sáng dịu hơn, ấm áp hơn để đọc sách.)"],"ukAudio":"/ai_services/tts3/?q=bulb&lang=en-GB&ipa=%2Fb%CA%8Clb%2F","usAudio":"/ai_services/tts3/?q=bulb&lang=en-US&ipa=%2Fb%CA%8Clb%2F"},{"id":"lv_0_36","topic":"Daily Life and Social Activities","word":"bush","pos":"(n)","ipa":"/bʊʃ/","defVi":"bụi cây, bụi rậm","defEn":"a plant with many woody stems growing from near the ground; a shrub","examples":["A small rabbit quickly darted into the thick green [bush] to hide from the dog. (=Dịch: Một con thỏ nhỏ nhanh chóng lao vào bụi cây xanh rậm rạp để trốn con chó.)","My father spent the whole morning pruning the rose [bush] in the front yard. (=Dịch: Bố tôi đã dành cả buổi sáng để cắt tỉa bụi hoa hồng ở sân trước.)","They planted a row of flowering [bush] varieties along the garden fence. (=Dịch: Họ đã trồng một hàng các loại cây bụi có hoa dọc theo hàng rào khu vườn.)"],"ukAudio":"/ai_services/tts3/?q=bush&lang=en-GB&ipa=%2Fb%CA%8A%CA%83%2F","usAudio":"/ai_services/tts3/?q=bush&lang=en-US&ipa=%2Fb%CA%8A%CA%83%2F"},{"id":"lv_0_37","topic":"Daily Life and Social Activities","word":"cabinet","pos":"(n)","ipa":"/ˈkæb.ə.nət/","defVi":"tủ đựng đồ; nội các chính phủ","defEn":"a piece of furniture with shelves or drawers, or a group of senior government ministers","examples":["Please put the clean plates back into the kitchen [cabinet] above the sink. (=Dịch: Vui lòng xếp đĩa sạch trở lại vào tủ bếp phía trên bồn rửa.)","The Prime Minister met with his [cabinet] to discuss urgent economic reforms. (=Dịch: Thủ tướng đã họp với nội các của mình để thảo luận về các cải cách kinh tế cấp bách.)","We store all our medical supplies and first-aid kits inside the bathroom [cabinet]. (=Dịch: Chúng tôi cất giữ toàn bộ vật tư y tế và bộ sơ cứu bên trong tủ phòng tắm.)"],"ukAudio":"/ai_services/tts3/?q=cabinet&lang=en-GB&ipa=%2F%CB%88k%C3%A6b.%C9%99.n%C9%99t%2F","usAudio":"/ai_services/tts3/?q=cabinet&lang=en-US&ipa=%2F%CB%88k%C3%A6b.%C9%99.n%C9%99t%2F"},{"id":"lv_0_38","topic":"Daily Life and Social Activities","word":"calendar","pos":"(n)","ipa":"/ˈkæl.ən.dɚ/","defVi":"lịch, cuốn lịch","defEn":"a chart or system showing the days, weeks, and months of a particular year","examples":["I marked the exam date on my wall [calendar] so I would not forget it. (=Dịch: Tôi đã đánh dấu ngày thi trên lịch treo tường để không bị quên.)","You can sync your digital [calendar] across your phone, tablet, and laptop. (=Dịch: Bạn có thể đồng bộ hóa lịch kỹ thuật số trên điện thoại, máy tính bảng và máy tính xách tay của mình.)","The academic [calendar] indicates that the spring semester starts in early February. (=Dịch: Lịch học cho biết học kỳ mùa xuân sẽ bắt đầu vào đầu tháng Hai.)"],"ukAudio":"/ai_services/tts3/?q=calendar&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=calendar&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F"},{"id":"lv_0_39","topic":"Daily Life and Social Activities","word":"caller","pos":"(n)","ipa":"/ˈkɑː.lɚ/","defVi":"người gọi điện thoại","defEn":"a person who makes a telephone call","examples":["The receptionist asked the [caller] to hold the line for a moment. (=Dịch: Nhân viên lễ tân đã yêu cầu người gọi giữ máy một lát.)","An anonymous [caller] reported the traffic accident to the police. (=Dịch: Một người gọi nặc danh đã trình báo vụ tai nạn giao thông cho cảnh sát.)","The radio host answered questions from the first [caller] of the morning. (=Dịch: Người dẫn chương trình phát thanh đã trả lời các câu hỏi từ người gọi đầu tiên trong buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=caller&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=caller&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%9A%2F"},{"id":"lv_0_40","topic":"Daily Life and Social Activities","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"nước Canada","defEn":"a large country located in the northern part of North America","examples":["Many international students choose to study in [Canada] each year. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Canada mỗi năm.)","Winter in [Canada] can be extremely cold with heavy snowfall. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá với tuyết rơi dày.)","She traveled across [Canada] by train to admire the natural scenery. (=Dịch: Cô ấy đã đi du lịch xuyên Canada bằng tàu hỏa để chiêm ngưỡng phong cảnh thiên nhiên.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_0_41","topic":"Daily Life and Social Activities","word":"cancel","pos":"(v)","ipa":"/ˈkæn.səl/","defVi":"hủy bỏ","defEn":"to decide that an organized event or activity will not happen","examples":["The airline had to [cancel] all flights due to the severe storm. (=Dịch: Hãng hàng không đã phải hủy tất cả các chuyến bay do cơn bão nghiêm trọng.)","They decided to [cancel] the outdoor concert because of heavy rain. (=Dịch: Họ quyết định hủy buổi hòa nhạc ngoài trời vì trời mưa lớn.)","You can [cancel] your subscription anytime without extra fees. (=Dịch: Bạn có thể hủy gói đăng ký của mình bất cứ lúc nào mà không phải trả thêm phí.)"],"ukAudio":"/ai_services/tts3/?q=cancel&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cancel&lang=en-US&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F"},{"id":"lv_0_42","topic":"Daily Life and Social Activities","word":"cancellation","pos":"(n)","ipa":"/ˌkæn.səˈleɪ.ʃən/","defVi":"sự hủy bỏ","defEn":"a decision or statement that an event or service will not take place","examples":["The sudden [cancellation] of the meeting surprised everyone in the office. (=Dịch: Việc hủy cuộc họp đột ngột khiến mọi người trong văn phòng đều bất ngờ.)","Hotel guests may incur a fee for a late [cancellation]. (=Dịch: Khách lưu trú tại khách sạn có thể phải chịu phí nếu hủy phòng muộn.)","Flight [cancellation] rates increased dramatically during the winter blizzard. (=Dịch: Tỷ lệ hủy chuyến bay đã tăng mạnh trong trận bão tuyết mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=cancellation&lang=en-GB&ipa=%2F%CB%8Ck%C3%A6n.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cancellation&lang=en-US&ipa=%2F%CB%8Ck%C3%A6n.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_43","topic":"Daily Life and Social Activities","word":"cardboard","pos":"(n)","ipa":"/ˈkɑːrd.bɔːrd/","defVi":"bìa các-tông","defEn":"thick, stiff paper used especially for making boxes","examples":["We packed all the heavy books into large [cardboard] boxes. (=Dịch: Chúng tôi đã đóng gói tất cả sách nặng vào các thùng bìa các tông lớn.)","The children built a toy castle out of recycled [cardboard]. (=Dịch: Những đứa trẻ đã dựng một lâu đài đồ chơi từ bìa các tông tái chế.)","You should flatten the [cardboard] before putting it in the recycling bin. (=Dịch: Bạn nên làm phẳng bìa các tông trước khi bỏ vào thùng rác tái chế.)"],"ukAudio":"/ai_services/tts3/?q=cardboard&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90rd.b%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=cardboard&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90rd.b%C9%94%CB%90rd%2F"},{"id":"lv_0_44","topic":"Daily Life and Social Activities","word":"carer","pos":"(n)","ipa":"/ˈker.ɚ/","defVi":"người chăm sóc","defEn":"someone who looks after a person who is young, old, or sick","examples":["She works as a full-time [carer] for her elderly grandmother. (=Dịch: Cô ấy làm người chăm sóc toàn thời gian cho người bà cao tuổi của mình.)","The local council offers support programs for every unpaid [carer]. (=Dịch: Hội đồng địa phương cung cấp các chương trình hỗ trợ cho mọi người chăm sóc không nhận thù lao.)","Being a primary [carer] can be physically and emotionally demanding. (=Dịch: Làm người chăm sóc chính có thể rất vất vả cả về thể chất lẫn tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=carer&lang=en-GB&ipa=%2F%CB%88ker.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=carer&lang=en-US&ipa=%2F%CB%88ker.%C9%9A%2F"},{"id":"lv_0_45","topic":"Daily Life and Social Activities","word":"caretaker","pos":"(n)","ipa":"/ˈkerˌteɪ.kɚ/","defVi":"người trông nom, người quản gia","defEn":"a person employed to take care of a building or piece of land","examples":["The school [caretaker] arrived early in the morning to unlock the gates. (=Dịch: Bác bảo vệ trường đã đến từ sáng sớm để mở cổng.)","They hired a [caretaker] to look after the holiday villa during the winter. (=Dịch: Họ đã thuê một người trông nom để chăm sóc căn biệt thự nghỉ dưỡng trong suốt mùa đông.)","The [caretaker] is responsible for routine maintenance and minor repairs. (=Dịch: Người quản lý chịu trách nhiệm bảo trì định kỳ và sửa chữa nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=caretaker&lang=en-GB&ipa=%2F%CB%88ker%CB%8Cte%C9%AA.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=caretaker&lang=en-US&ipa=%2F%CB%88ker%CB%8Cte%C9%AA.k%C9%9A%2F"},{"id":"lv_0_46","topic":"Daily Life and Social Activities","word":"caring","pos":"(adj)","ipa":"/ˈker.ɪŋ/","defVi":"chu đáo, giàu lòng quan tâm","defEn":"displaying kindness, concern, and empathy for others","examples":["He is a deeply [caring] person who always helps those in need. (=Dịch: Anh ấy là một người rất giàu lòng quan tâm, luôn giúp đỡ những ai gặp khó khăn.)","The nurses provided a [caring] environment for all the patients. (=Dịch: Các y tá đã mang lại một môi trường chăm sóc chu đáo cho tất cả bệnh nhân.)","Children thrive best in a supportive and [caring] family atmosphere. (=Dịch: Trẻ em phát triển tốt nhất trong bầu không khí gia đình tràn đầy yêu thương và luôn hỗ trợ lẫn nhau.)"],"ukAudio":"/ai_services/tts3/?q=caring&lang=en-GB&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=caring&lang=en-US&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F"},{"id":"lv_0_47","topic":"Daily Life and Social Activities","word":"carve","pos":"(v)","ipa":"/kɑːrv/","defVi":"khắc, chạm, tạc","defEn":"to make objects or designs by cutting wood, stone, or other hard materials","examples":["The artist used a sharp chisel to [carve] a wooden statue. (=Dịch: Nghệ sĩ đã sử dụng một chiếc đục sắc bén để chạm khắc bức tượng gỗ.)","They decided to [carve] their initials onto the old tree trunk. (=Dịch: Họ quyết định khắc tên viết tắt của mình lên thân cây già.)","He learned how to [carve] a roasted turkey for the holiday dinner. (=Dịch: Anh ấy đã học cách xẻ thịt gà tây nướng cho bữa tối ngày lễ.)"],"ukAudio":"/ai_services/tts3/?q=carve&lang=en-GB&ipa=%2Fk%C9%91%CB%90rv%2F","usAudio":"/ai_services/tts3/?q=carve&lang=en-US&ipa=%2Fk%C9%91%CB%90rv%2F"},{"id":"lv_0_48","topic":"Daily Life and Social Activities","word":"cathedral","pos":"(n)","ipa":"/kəˈθiː.drəl/","defVi":"nhà thờ lớn, thánh đường","defEn":"the principal Christian church of a diocese, associated with a bishop","examples":["The ancient [cathedral] attracts thousands of tourists every summer. (=Dịch: Nhà thờ chính tòa cổ kính thu hút hàng ngàn du khách vào mỗi mùa hè.)","Beautiful stained glass windows adorn the walls of the Gothic [cathedral]. (=Dịch: Những ô cửa kính màu tuyệt đẹp tô điểm cho các bức tường của nhà thờ chính tòa phong cách Gothic.)","We climbed to the top of the [cathedral] tower for a panoramic view of the city. (=Dịch: Chúng tôi đã leo lên đỉnh tháp nhà thờ chính tòa để ngắm nhìn toàn cảnh thành phố.)"],"ukAudio":"/ai_services/tts3/?q=cathedral&lang=en-GB&ipa=%2Fk%C9%99%CB%88%CE%B8i%CB%90.dr%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cathedral&lang=en-US&ipa=%2Fk%C9%99%CB%88%CE%B8i%CB%90.dr%C9%99l%2F"},{"id":"lv_0_49","topic":"Daily Life and Social Activities","word":"centimetre","pos":"(n)","ipa":"/ˈsɛn.tɪˌmi.t̬ɚ/","defVi":"xăng-ti-mét (cm)","defEn":"a metric unit of length equal to one hundredth of a meter","examples":["The plant grew about one [centimetre] every week. (=Dịch: Cái cây đã phát triển thêm khoảng một centimet mỗi tuần.)","You should leave a margin of two [centimetres] on each side of the page. (=Dịch: Bạn nên chừa lề hai centimet ở mỗi bên của trang giấy.)","The rainfall measured only a few [centimetres] during the dry season. (=Dịch: Lượng mưa chỉ đo được vài centimet trong suốt mùa khô.)"],"ukAudio":"/ai_services/tts3/?q=centimetre&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.t%C9%AA%CB%8Cmi.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=centimetre&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.t%C9%AA%CB%8Cmi.t%CC%AC%C9%9A%2F"},{"id":"lv_0_50","topic":"Daily Life and Social Activities","word":"ceremony","pos":"(n)","ipa":"/ˈsɛr.əˌmoʊ.ni/","defVi":"nghi thức, nghi lễ, buổi lễ","defEn":"a formal event held on a special occasion, often with traditional rituals","examples":["The opening [ceremony] of the Olympic Games was truly magnificent. (=Dịch: Lễ khai mạc Thế vận hội Olympic thực sự rất tráng lệ.)","They decided to have a simple wedding [ceremony] with close friends. (=Dịch: Họ quyết định tổ chức một lễ cưới đơn giản cùng với những người bạn thân thiết.)","The graduation [ceremony] will take place in the main auditorium tomorrow. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại khán phòng chính vào ngày mai.)"],"ukAudio":"/ai_services/tts3/?q=ceremony&lang=en-GB&ipa=%2F%CB%88s%C9%9Br.%C9%99%CB%8Cmo%CA%8A.ni%2F","usAudio":"/ai_services/tts3/?q=ceremony&lang=en-US&ipa=%2F%CB%88s%C9%9Br.%C9%99%CB%8Cmo%CA%8A.ni%2F"},{"id":"lv_0_51","topic":"Daily Life and Social Activities","word":"certificate","pos":"(n)","ipa":"/sɚˈtɪf.ə.kət/","defVi":"chứng chỉ, giấy chứng nhận","defEn":"an official document that proves a fact, qualification, or achievement","examples":["She received a [certificate] of completion after finishing the language course. (=Dịch: Cô ấy đã nhận được chứng chỉ hoàn thành sau khi kết thúc khóa học ngôn ngữ.)","You must present your birth [certificate] when applying for a passport. (=Dịch: Bạn phải xuất trình giấy khai sinh khi nộp đơn xin cấp hộ chiếu.)","He framed his teaching [certificate] and hung it in his office. (=Dịch: Anh ấy đã đóng khung chứng chỉ giảng dạy của mình và treo nó trong văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=certificate&lang=en-GB&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F","usAudio":"/ai_services/tts3/?q=certificate&lang=en-US&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F"},{"id":"lv_0_52","topic":"Daily Life and Social Activities","word":"champion","pos":"(n)","ipa":"/ˈtʃæm.pi.ən/","defVi":"nhà vô địch, quán quân","defEn":"a person, animal, or team that has won a competition","examples":["She became the youngest world chess [champion] in history. (=Dịch: Cô ấy đã trở thành nhà vô địch cờ vua thế giới trẻ tuổi nhất trong lịch sử.)","The defending [champion] was defeated in the final round of the tournament. (=Dịch: Nhà đương kim vô địch đã bị đánh bại ở vòng chung kết của giải đấu.)","Our local basketball team aims to be the league [champion] this season. (=Dịch: Đội bóng rổ địa phương của chúng tôi đặt mục tiêu trở thành nhà vô địch giải đấu mùa này.)"],"ukAudio":"/ai_services/tts3/?q=champion&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6m.pi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=champion&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6m.pi.%C9%99n%2F"},{"id":"lv_0_53","topic":"Daily Life and Social Activities","word":"cheque","pos":"(n)","ipa":"/tʃɛk/","defVi":"tấm séc, chi phiếu","defEn":"a printed document that orders a bank to pay a specific amount of money from someone's account","examples":["He wrote a [cheque] to pay for the monthly rent. (=Dịch: Anh ấy đã viết một tấm séc để trả tiền thuê nhà hàng tháng.)","The store does not accept payment by [cheque] anymore. (=Dịch: Cửa hàng không còn chấp nhận thanh toán bằng séc nữa.)","She deposited the salary [cheque] into her savings account this morning. (=Dịch: Cô ấy đã gửi tấm séc tiền lương vào tài khoản tiết kiệm của mình sáng nay.)"],"ukAudio":"/ai_services/tts3/?q=cheque&lang=en-GB&ipa=%2Ft%CA%83%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=cheque&lang=en-US&ipa=%2Ft%CA%83%C9%9Bk%2F"},{"id":"lv_0_54","topic":"Daily Life and Social Activities","word":"chervil","pos":"(n)","ipa":"/ˈtʃɝ.vɪl/","defVi":"ngò tây Pháp, rau mùi tây Pháp (chervil)","defEn":"an herb with delicate leaves similar to parsley, used in cooking for its mild flavor","examples":["The chef sprinkled freshly chopped [chervil] over the fish dish. (=Dịch: Đầu bếp đã rắc rau mùi tây Pháp băm nhỏ tươi lên món cá.)","You can substitute parsley if you cannot find [chervil] at the grocery store. (=Dịch: Bạn có thể dùng ngò tây thay thế nếu không tìm thấy rau mùi tây Pháp ở cửa hàng tạp hóa.)","This traditional French soup is flavored with tarragon and [chervil]. (=Dịch: Món súp truyền thống của Pháp này được tăng hương vị với ngải thơm và rau mùi tây Pháp.)"],"ukAudio":"/ai_services/tts3/?q=chervil&lang=en-GB&ipa=%2F%CB%88t%CA%83%C9%9D.v%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=chervil&lang=en-US&ipa=%2F%CB%88t%CA%83%C9%9D.v%C9%AAl%2F"},{"id":"lv_0_55","topic":"Daily Life and Social Activities","word":"chest","pos":"(n)","ipa":"/tʃɛst/","defVi":"ngực (cơ thể); rương, hòm (đựng đồ)","defEn":"the front part of the body between the neck and the stomach; or a large, strong box for storage","examples":["He experienced a sudden pain in his [chest] after running up the stairs. (=Dịch: Anh ấy cảm thấy đau ngực đột ngột sau khi chạy lên cầu thang.)","The old wooden [chest] in the attic was filled with vintage photographs. (=Dịch: Chiếc rương gỗ cũ trên gác mái chứa đầy những bức ảnh cổ điển.)","Divers discovered a treasure [chest] lying on the seabed. (=Dịch: Các thợ lặn đã phát hiện một rương kho báu nằm dưới đáy biển.)"],"ukAudio":"/ai_services/tts3/?q=chest&lang=en-GB&ipa=%2Ft%CA%83%C9%9Bst%2F","usAudio":"/ai_services/tts3/?q=chest&lang=en-US&ipa=%2Ft%CA%83%C9%9Bst%2F"},{"id":"lv_0_56","topic":"Daily Life and Social Activities","word":"childcare","pos":"(n)","ipa":"/ˈtʃaɪld.kɛr/","defVi":"việc chăm sóc trẻ em, dịch vụ trông trẻ","defEn":"the care and supervision of young children, especially while parents are working","examples":["High costs of [childcare] make it difficult for many mothers to return to work. (=Dịch: Chi phí chăm sóc trẻ cao khiến nhiều người mẹ gặp khó khăn khi quay trở lại làm việc.)","The company offers on-site [childcare] facilities for its employees. (=Dịch: Công ty cung cấp các cơ sở trông giữ trẻ tại chỗ cho nhân viên của mình.)","Finding reliable [childcare] is a major challenge for working parents. (=Dịch: Tìm kiếm dịch vụ chăm sóc trẻ đáng tin cậy là một thách thức lớn đối với các bậc cha mẹ đi làm.)"],"ukAudio":"/ai_services/tts3/?q=childcare&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.k%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=childcare&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.k%C9%9Br%2F"},{"id":"lv_0_57","topic":"Daily Life and Social Activities","word":"china","pos":"(n)","ipa":"/ˈtʃaɪ.nə/","defVi":"đồ sứ, bát đĩa bằng sứ","defEn":"delicate cups, plates, and dishes made of high-quality white clay (porcelain)","examples":["She only uses the fine [china] when hosting formal dinner parties. (=Dịch: Cô ấy chỉ sử dụng đồ sứ cao cấp khi tổ chức các bữa tiệc tối trang trọng.)","Be very careful not to drop that antique [china] tea cup. (=Dịch: Hãy thật cẩn thận để không làm rơi chiếc tách trà bằng sứ cổ đó.)","The museum displays a rare collection of imperial [china] from centuries ago. (=Dịch: Bảo tàng trưng bày một bộ sưu tập đồ sứ hoàng gia quý hiếm từ nhiều thế kỷ trước.)"],"ukAudio":"/ai_services/tts3/?q=china&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=china&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F"},{"id":"lv_0_58","topic":"Daily Life and Social Activities","word":"chord","pos":"(n)","ipa":"/kɔːrd/","defVi":"hợp âm","defEn":"a combination of three or more musical notes played at the same time","examples":["He learned how to play a basic guitar [chord] during his first music lesson. (=Dịch: Anh ấy đã học cách chơi một hợp âm guitar cơ bản trong buổi học nhạc đầu tiên của mình.)","The song ends with a resonant minor [chord] on the piano. (=Dịch: Bài hát kết thúc bằng một hợp âm thứ vang vọng trên đàn piano.)","Practicing [chord] transitions will improve your rhythm and speed on the keyboard. (=Dịch: Việc luyện tập chuyển hợp âm sẽ cải thiện nhịp điệu và tốc độ của bạn trên phím đàn.)"],"ukAudio":"/ai_services/tts3/?q=chord&lang=en-GB&ipa=%2Fk%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=chord&lang=en-US&ipa=%2Fk%C9%94%CB%90rd%2F"},{"id":"lv_0_59","topic":"Daily Life and Social Activities","word":"circular","pos":"(adj)","ipa":"/ˈsɝ.kjə.lɚ/","defVi":"có hình tròn; vòng tròn, luẩn quẩn","defEn":"having the form of a circle; round, or moving in a circle","examples":["The guests gathered around a large [circular] table for dinner. (=Dịch: Các vị khách quây quần quanh một chiếc bàn tròn lớn để dùng bữa tối.)","The bus follows a [circular] route around the city center. (=Dịch: Xe buýt chạy theo một tuyến đường vòng quanh trung tâm thành phố.)","His argument was [circular] and failed to prove any real point. (=Dịch: Lập luận của anh ấy luẩn quẩn và không chứng minh được quan điểm thực sự nào.)"],"ukAudio":"/ai_services/tts3/?q=circular&lang=en-GB&ipa=%2F%CB%88s%C9%9D.kj%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=circular&lang=en-US&ipa=%2F%CB%88s%C9%9D.kj%C9%99.l%C9%9A%2F"},{"id":"lv_0_60","topic":"Daily Life and Social Activities","word":"cleaner","pos":"(n)","ipa":"/ˈkli.nɚ/","defVi":"người quét dọn; chất tẩy rửa","defEn":"a person whose job is to clean rooms or buildings, or a substance used for cleaning","examples":["The office [cleaner] empties the bins every evening. (=Dịch: Nhân viên vệ sinh văn phòng đổ các thùng rác vào mỗi buổi tối.)","You should use a special glass [cleaner] to remove those smudges. (=Dịch: Bạn nên sử dụng nước lau kính chuyên dụng để làm sạch những vết mờ đó.)","She works as a part-time [cleaner] at the local hospital. (=Dịch: Cô ấy làm công việc dọn dẹp bán thời gian tại bệnh viện địa phương.)"],"ukAudio":"/ai_services/tts3/?q=cleaner&lang=en-GB&ipa=%2F%CB%88kli.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cleaner&lang=en-US&ipa=%2F%CB%88kli.n%C9%9A%2F"},{"id":"lv_0_61","topic":"Daily Life and Social Activities","word":"clinic","pos":"(n)","ipa":"/ˈklɪn.ɪk/","defVi":"phòng khám","defEn":"a place where people receive medical treatment or advice","examples":["She made an appointment at the local dental [clinic]. (=Dịch: Cô ấy đã đặt lịch hẹn tại phòng khám nha khoa địa phương.)","The health [clinic] offers free vaccinations for young children. (=Dịch: Phòng khám y tế cung cấp vắc-xin miễn phí cho trẻ nhỏ.)","He had to visit the [clinic] for a routine check-up. (=Dịch: Anh ấy phải đến phòng khám để kiểm tra sức khỏe định kỳ.)"],"ukAudio":"/ai_services/tts3/?q=clinic&lang=en-GB&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=clinic&lang=en-US&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F"},{"id":"lv_0_62","topic":"Daily Life and Social Activities","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng giữ đồ (áo khoác, túi xách)","defEn":"a room where coats, bags, and hats can be left temporarily","examples":["Please leave your heavy winter coat in the [cloakroom] before entering the theater. (=Dịch: Vui lòng để lại áo khoác mùa đông dày của bạn ở phòng giữ đồ trước khi vào nhà hát.)","The attendant in the [cloakroom] gave me a numbered ticket. (=Dịch: Người phục vụ ở phòng giữ đồ đã đưa cho tôi một chiếc vé có đánh số.)","They set up a temporary [cloakroom] near the entrance of the exhibition hall. (=Dịch: Họ đã dựng một phòng giữ đồ tạm thời gần lối vào của sảnh triển lãm.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_0_63","topic":"Daily Life and Social Activities","word":"clubhouse","pos":"(n)","ipa":"/ˈklʌb.haʊs/","defVi":"nhà câu lạc bộ (nơi sinh hoạt chung)","defEn":"a building used by members of a club for meetings or social activities","examples":["The golfers met in the [clubhouse] for lunch after their match. (=Dịch: Các tay gôn đã gặp nhau tại nhà sinh hoạt câu lạc bộ để ăn trưa sau trận đấu.)","Members can relax and enjoy drinks on the [clubhouse] terrace. (=Dịch: Các hội viên có thể thư giãn và thưởng thức đồ uống trên sân thượng của nhà câu lạc bộ.)","The team celebrated their championship victory at the sports [clubhouse]. (=Dịch: Đội đã ăn mừng chiến thắng chức vô địch tại nhà câu lạc bộ thể thao.)"],"ukAudio":"/ai_services/tts3/?q=clubhouse&lang=en-GB&ipa=%2F%CB%88kl%CA%8Cb.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=clubhouse&lang=en-US&ipa=%2F%CB%88kl%CA%8Cb.ha%CA%8As%2F"},{"id":"lv_0_64","topic":"Daily Life and Social Activities","word":"collector","pos":"(n)","ipa":"/kəˈlek.tɚ/","defVi":"nhà sưu tầm; người thu (tiền, vé)","defEn":"a person who collects particular objects as a hobby or for an organization","examples":["He is a passionate stamp [collector] who owns rare specimens from all over the world. (=Dịch: Ông là một người đam mê sưu tập tem, sở hữu những mẫu tem quý hiếm từ khắp nơi trên thế giới.)","An antique [collector] bought the old painting at an auction. (=Dịch: Một nhà sưu tập đồ cổ đã mua bức tranh cũ trong một buổi đấu giá.)","The tax [collector] visited the shop to check their financial records. (=Dịch: Nhân viên thu thuế đã đến cửa hàng để kiểm tra sổ sách tài chính của họ.)"],"ukAudio":"/ai_services/tts3/?q=collector&lang=en-GB&ipa=%2Fk%C9%99%CB%88lek.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=collector&lang=en-US&ipa=%2Fk%C9%99%CB%88lek.t%C9%9A%2F"},{"id":"lv_0_65","topic":"Daily Life and Social Activities","word":"commitment","pos":"(n)","ipa":"/kəˈmɪt.mənt/","defVi":"sự cam kết, sự tận tụy","defEn":"a promise or firm decision to do something, or devotion to a cause","examples":["He showed great [commitment] to his studies and passed with high marks. (=Dịch: Anh ấy đã thể hiện sự tận tâm to lớn cho việc học và đỗ đạt với điểm số cao.)","The company made a long-term [commitment] to reduce carbon emissions. (=Dịch: Công ty đã đưa ra một cam kết dài hạn nhằm giảm lượng khí thải carbon.)","A successful relationship requires mutual trust and strong [commitment]. (=Dịch: Một mối quan hệ thành công đòi hỏi sự tin tưởng lẫn nhau và sự gắn kết bền chặt.)"],"ukAudio":"/ai_services/tts3/?q=commitment&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=commitment&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F"},{"id":"lv_0_66","topic":"Daily Life and Social Activities","word":"committee","pos":"(n)","ipa":"/kəˈmɪt.i/","defVi":"ủy ban, ban tổ chức","defEn":"a group of people chosen to make decisions or deal with a particular task","examples":["The planning [committee] will meet next Monday to discuss the budget. (=Dịch: Ủy ban kế hoạch sẽ họp vào thứ Hai tới để thảo luận về ngân sách.)","She was elected as the chairperson of the organizing [committee]. (=Dịch: Cô ấy đã được bầu làm chủ tịch của ban tổ chức.)","The government formed a special [committee] to investigate environmental pollution. (=Dịch: Chính phủ đã thành lập một ủy ban đặc biệt để điều tra về tình trạng ô nhiễm môi trường.)"],"ukAudio":"/ai_services/tts3/?q=committee&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=committee&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F"},{"id":"lv_0_67","topic":"Daily Life and Social Activities","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"lời phàn nàn, sự khiếu nại","defEn":"a statement that something is wrong or not satisfactory","examples":["The hotel received a formal [complaint] about the noisy air conditioning. (=Dịch: Khách sạn đã nhận được một lời khiếu nại chính thức về chiếc máy điều hòa gây ồn.)","She filed an official [complaint] with the airline regarding her damaged luggage. (=Dịch: Cô ấy đã nộp đơn khiếu nại chính thức tới hãng hàng không liên quan đến hành lý bị hư hại của mình.)","Our team has resolved every customer [complaint] within twenty-four hours. (=Dịch: Đội ngũ của chúng tôi đã giải quyết mọi khiếu nại của khách hàng trong vòng hai mươi tư giờ.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_0_68","topic":"Daily Life and Social Activities","word":"composition","pos":"(n)","ipa":"/ˌkɑːm.pəˈzɪʃ.ən/","defVi":"thành phần cấu tạo; bài văn; bản nhạc","defEn":"the parts or elements that make up something, a piece of writing, or a musical work","examples":["Scientists analyzed the chemical [composition] of the soil sample. (=Dịch: Các nhà khoa học đã phân tích thành phần hóa học của mẫu đất.)","The students were asked to write a short [composition] about their hometown. (=Dịch: Các học sinh được yêu cầu viết một bài luận ngắn về quê hương của mình.)","The pianist performed an original [composition] during the concert. (=Dịch: Nghệ sĩ dương cầm đã biểu diễn một bản nhạc tự sáng tác trong buổi hòa nhạc.)"],"ukAudio":"/ai_services/tts3/?q=composition&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=composition&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_0_69","topic":"Daily Life and Social Activities","word":"conditioning","pos":"(n)","ipa":"/kənˈdɪʃ.ən.ɪŋ/","defVi":"sự rèn luyện thể lực; sự điều hòa (không khí)","defEn":"the process of training or modifying behavior, or the act of keeping something in a good state","examples":["Physical [conditioning] is an essential part of an athlete's daily routine. (=Dịch: Rèn luyện thể lực là một phần thiết yếu trong lịch trình hàng ngày của vận động viên.)","Air [conditioning] makes the hot summer days much more bearable. (=Dịch: Hệ thống điều hòa không khí giúp những ngày hè nóng nực trở nên dễ chịu hơn nhiều.)","Psychologists study how social [conditioning] influences human behavior. (=Dịch: Các nhà tâm lý học nghiên cứu cách mà sự định hình của xã hội ảnh hưởng đến hành vi của con người.)"],"ukAudio":"/ai_services/tts3/?q=conditioning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=conditioning&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_0_70","topic":"Daily Life and Social Activities","word":"congratulation","pos":"(n)","ipa":"/kənˌɡrætʃ.əˈleɪ.ʃən/","defVi":"lời chúc mừng","defEn":"an expression of praise or good wishes for someone's success or achievement","examples":["I sent her a message of [congratulation] after she passed her driving test. (=Dịch: Tôi đã gửi cho cô ấy một tin nhắn chúc mừng sau khi cô ấy vượt qua kỳ thi sát hạch lái xe.)","The headmaster offered his warmest [congratulation] to the graduating students. (=Dịch: Hiệu trưởng đã gửi lời chúc mừng nồng nhiệt nhất tới các học sinh tốt nghiệp.)","They received many cards of [congratulation] on their wedding day. (=Dịch: Họ đã nhận được rất nhiều thiệp chúc mừng vào ngày cưới của mình.)"],"ukAudio":"/ai_services/tts3/?q=congratulation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congratulation&lang=en-US&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_71","topic":"Daily Life and Social Activities","word":"continuous","pos":"(adj)","ipa":"/kənˈtɪn.ju.əs/","defVi":"liên tục, không ngừng nghỉ","defEn":"happening or existing without any interruption or pause","examples":["The brain needs a [continuous] supply of blood and oxygen to function properly. (=Dịch: Não bộ cần được cung cấp máu và oxy liên tục để hoạt động bình thường.)","She suffered from [continuous] back pain throughout the flight. (=Dịch: Cô ấy đã phải chịu đựng cơn đau lưng liên tục trong suốt chuyến bay.)","The factory operates on a [continuous] production cycle without stopping at night. (=Dịch: Nhà máy hoạt động theo một chu kỳ sản xuất liên tục mà không dừng lại vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=continuous&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=continuous&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F"},{"id":"lv_0_72","topic":"Daily Life and Social Activities","word":"contract","pos":"(n)","ipa":"/ˈkɑːn.trækt/","defVi":"hợp đồng","defEn":"an official, legal agreement between two or more people or organizations","examples":["Please read the terms carefully before you sign the employment [contract]. (=Dịch: Vui lòng đọc kỹ các điều khoản trước khi bạn ký hợp đồng lao động.)","The company decided to renew the rental [contract] for another year. (=Dịch: Công ty đã quyết định gia hạn hợp đồng thuê thêm một năm.)","He breached the [contract] by sharing confidential information with competitors. (=Dịch: Anh ấy đã vi phạm hợp đồng khi chia sẻ thông tin mật với các đối thủ cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=contract&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=contract&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F"},{"id":"lv_0_73","topic":"Daily Life and Social Activities","word":"convenient","pos":"(adj)","ipa":"/kənˈviːn.jənt/","defVi":"tiện lợi, thuận tiện","defEn":"useful, easy, or suitable for a particular purpose without causing problems","examples":["The new apartment is in a very [convenient] location near the subway station. (=Dịch: Căn hộ mới nằm ở một vị trí rất thuận tiện gần ga tàu điện ngầm.)","Online banking makes it [convenient] to pay bills from home. (=Dịch: Ngân hàng trực tuyến giúp việc thanh toán các hóa đơn tại nhà trở nên thuận tiện.)","Is Friday afternoon [convenient] for our team meeting? (=Dịch: Chiều thứ Sáu có thuận tiện cho cuộc họp nhóm của chúng ta không?)"],"ukAudio":"/ai_services/tts3/?q=convenient&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=convenient&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F"},{"id":"lv_0_74","topic":"Daily Life and Social Activities","word":"cookery","pos":"(n)","ipa":"/ˈkʊk.ɚ.i/","defVi":"nghệ thuật nấu nướng, việc làm bếp","defEn":"the art, skill, or practice of preparing and cooking food","examples":["She enrolled in an Italian [cookery] course to learn how to make fresh pasta. (=Dịch: Cô ấy đã đăng ký một khóa học nấu ăn Ý để học cách làm mì ống tươi.)","His passion for [cookery] began when he helped his grandmother in the kitchen. (=Dịch: Niềm đam mê nấu nướng của anh ấy bắt đầu khi anh giúp bà của mình trong bếp.)","The bookstore has a large section dedicated to books on healthy [cookery]. (=Dịch: Hiệu sách có một khu vực lớn dành riêng cho những cuốn sách về nấu ăn lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=cookery&lang=en-GB&ipa=%2F%CB%88k%CA%8Ak.%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=cookery&lang=en-US&ipa=%2F%CB%88k%CA%8Ak.%C9%9A.i%2F"},{"id":"lv_0_75","topic":"Daily Life and Social Activities","word":"coordinator","pos":"(n)","ipa":"/koʊˈɔːr.dən.eɪ.t̬ɚ/","defVi":"người điều phối","defEn":"someone whose job is to organize the various parts of an activity or event","examples":["She works as a project [coordinator] for an international charity organization. (=Dịch: Cô ấy làm việc với tư cách là người điều phối dự án cho một tổ chức từ thiện quốc tế.)","If you have any questions about the schedule, please contact the event [coordinator]. (=Dịch: Nếu bạn có bất kỳ câu hỏi nào về lịch trình, vui lòng liên hệ với người điều phối sự kiện.)","The volunteer [coordinator] assigned tasks to each newcomer on the team. (=Dịch: Người điều phối tình nguyện viên đã phân công nhiệm vụ cho từng người mới gia nhập nhóm.)"],"ukAudio":"/ai_services/tts3/?q=coordinator&lang=en-GB&ipa=%2Fko%CA%8A%CB%88%C9%94%CB%90r.d%C9%99n.e%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=coordinator&lang=en-US&ipa=%2Fko%CA%8A%CB%88%C9%94%CB%90r.d%C9%99n.e%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_0_76","topic":"Daily Life and Social Activities","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục (biểu diễn, hóa trang)","defEn":"a set of clothes worn by someone in a play, film, or for a particular occasion","examples":["The actors wore traditional Victorian [costume] during the historical drama. (=Dịch: Các diễn viên đã mặc trang phục thời Victoria truyền thống trong suốt vở kịch lịch sử.)","He won first prize at the Halloween party for his scary monster [costume]. (=Dịch: Anh ấy đã giành giải nhất tại bữa tiệc Halloween nhờ bộ trang phục quái vật đáng sợ của mình.)","The museum displays dancers in colorful folk [costume] from different regions. (=Dịch: Bảo tàng trưng bày các vũ công trong trang phục dân gian rực rỡ sắc màu từ các vùng miền khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_0_77","topic":"Daily Life and Social Activities","word":"cot","pos":"(n)","ipa":"/kɑːt/","defVi":"cũi (cho em bé), giường gấp di động","defEn":"a small bed with high barred sides for a baby or young child, or a narrow portable bed","examples":["The baby fell asleep peacefully in his [cot] after drinking milk. (=Dịch: Em bé đã ngủ thiếp đi một cách ngoan ngoãn trong cũi sau khi uống sữa.)","We set up a folding [cot] in the living room for our weekend guest. (=Dịch: Chúng tôi đã dựng một chiếc giường xếp trong phòng khách cho vị khách ở lại vào cuối tuần.)","Make sure the sides of the [cot] are raised to prevent the baby from falling out. (=Dịch: Hãy đảm bảo các thành cũi đã được nâng lên để tránh em bé bị ngã ra ngoài.)"],"ukAudio":"/ai_services/tts3/?q=cot&lang=en-GB&ipa=%2Fk%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=cot&lang=en-US&ipa=%2Fk%C9%91%CB%90t%2F"},{"id":"lv_0_78","topic":"Daily Life and Social Activities","word":"court","pos":"(n)","ipa":"/kɔːrt/","defVi":"tòa án; sân bóng (quần vợt, bóng rổ)","defEn":"a place where legal cases are heard, or an area marked out for ball games","examples":["The witness was asked to appear in [court] to give evidence tomorrow. (=Dịch: Nhân chứng đã được yêu cầu có mặt tại tòa án để cung cấp lời khai vào ngày mai.)","They booked a tennis [court] for two hours on Saturday morning. (=Dịch: Họ đã đặt một sân tennis trong hai giờ vào sáng thứ Bảy.)","The judge entered the [court] and everyone stood up respectfully. (=Dịch: Thẩm phán bước vào phòng xử án và mọi người đều đứng dậy một cách tôn kính.)"],"ukAudio":"/ai_services/tts3/?q=court&lang=en-GB&ipa=%2Fk%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=court&lang=en-US&ipa=%2Fk%C9%94%CB%90rt%2F"},{"id":"lv_0_79","topic":"Daily Life and Social Activities","word":"crack","pos":"(n)","ipa":"/kræk/","defVi":"vết nứt, khe hở","defEn":"a narrow line or space on the surface of something where it has broken","examples":["There is a visible [crack] across the windshield that needs to be repaired. (=Dịch: Có một vết nứt rõ thấy trên kính chắn gió cần phải được sửa chữa.)","Water started seeping into the basement through a tiny [crack] in the foundation. (=Dịch: Nước bắt đầu thấm vào tầng hầm qua một vết nứt nhỏ trên nền móng.)","The earthquake caused a large [crack] to appear down the middle of the road. (=Dịch: Trận động đất đã khiến một vết nứt lớn xuất hiện dọc giữa lòng đường.)"],"ukAudio":"/ai_services/tts3/?q=crack&lang=en-GB&ipa=%2Fkr%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=crack&lang=en-US&ipa=%2Fkr%C3%A6k%2F"},{"id":"lv_0_80","topic":"Daily Life and Social Activities","word":"crew","pos":"(n)","ipa":"/kruː/","defVi":"phi hành đoàn, thủy thủ đoàn, đội ngũ nhân viên","defEn":"a group of people who work together, especially all the people working on a ship or aircraft","examples":["The captain ordered the [crew] to prepare the ship for departure. (=Dịch: Thuyền trưởng đã ra lệnh cho thủy thủ đoàn chuẩn bị để tàu khởi hành.)","The flight [crew] demonstrated the safety procedures before takeoff. (=Dịch: Phi hành đoàn đã hướng dẫn các quy trình an toàn trước khi máy bay cất cánh.)","A film [crew] arrived in the town to shoot a new television series. (=Dịch: Một đoàn làm phim đã đến thị trấn để quay một bộ phim truyền hình nhiều tập mới.)"],"ukAudio":"/ai_services/tts3/?q=crew&lang=en-GB&ipa=%2Fkru%CB%90%2F","usAudio":"/ai_services/tts3/?q=crew&lang=en-US&ipa=%2Fkru%CB%90%2F"},{"id":"lv_0_81","topic":"Daily Life and Social Activities","word":"curry","pos":"(n)","ipa":"/ˈkɜːr.i/","defVi":"món cà ri","defEn":"a dish of meat, vegetables, etc., cooked in an Indian-style sauce of strong spices","examples":["We decided to have chicken [curry] with rice for dinner. (=Dịch: Chúng tôi quyết định ăn cà ri gà với cơm cho bữa tối.)","This Indian restaurant is famous for its spicy lamb [curry]. (=Dịch: Nhà hàng Ấn Độ này nổi tiếng với món cà ri cừu cay.)","She added a spoonful of [curry] powder to flavor the soup. (=Dịch: Cô ấy đã thêm một thìa bột cà ri để tạo hương vị cho món súp.)"],"ukAudio":"/ai_services/tts3/?q=curry&lang=en-GB&ipa=%2F%CB%88k%C9%9C%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=curry&lang=en-US&ipa=%2F%CB%88k%C9%9C%CB%90r.i%2F"},{"id":"lv_0_82","topic":"Daily Life and Social Activities","word":"curtain","pos":"(n)","ipa":"/ˈkɜːr.tn/","defVi":"rèm cửa, màn cửa","defEn":"a piece of cloth hung to cover a window","examples":["She drew the [curtain] to block out the morning sunlight. (=Dịch: Cô ấy kéo rèm lại để ngăn ánh nắng buổi sáng.)","The living room looks much brighter with the new lace [curtains]. (=Dịch: Phòng khách trông sáng sủa hơn nhiều với những tấm rèm ren mới.)","A heavy velvet [curtain] separated the dining area from the kitchen. (=Dịch: Một tấm rèm nhung dày đã ngăn cách khu vực ăn uống với nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=curtain&lang=en-GB&ipa=%2F%CB%88k%C9%9C%CB%90r.tn%2F","usAudio":"/ai_services/tts3/?q=curtain&lang=en-US&ipa=%2F%CB%88k%C9%9C%CB%90r.tn%2F"},{"id":"lv_0_83","topic":"Daily Life and Social Activities","word":"decorate","pos":"(v)","ipa":"/ˈdek.ə.reɪt/","defVi":"trang trí, trang hoàng","defEn":"to make something look more attractive by adding items or paint to it","examples":["The family gathered together to [decorate] the Christmas tree. (=Dịch: Cả gia đình quây quần bên nhau để trang trí cây thông Noel.)","They plan to [decorate] the bedroom with light blue wallpaper. (=Dịch: Họ dự định trang trí phòng ngủ bằng giấy dán tường màu xanh nhạt.)","Fresh flowers were used to [decorate] the tables for the wedding. (=Dịch: Hoa tươi đã được sử dụng để trang trí các bàn tiệc cho đám cưới.)"],"ukAudio":"/ai_services/tts3/?q=decorate&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=decorate&lang=en-US&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F"},{"id":"lv_0_84","topic":"Daily Life and Social Activities","word":"decoration","pos":"(n)","ipa":"/ˌdek.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang trí","defEn":"an object or pattern used to make something look more attractive","examples":["We took down the party [decorations] the day after the celebration. (=Dịch: Chúng tôi đã tháo dỡ đồ trang trí bữa tiệc vào ngày hôm sau lễ kỷ niệm.)","Handmade paper lanterns served as beautiful wall [decorations]. (=Dịch: Những chiếc đèn lồng giấy thủ công được dùng làm đồ trang trí tường rất đẹp.)","The cake was topped with sugar flowers for [decoration]. (=Dịch: Chiếc bánh được phủ những bông hoa đường để trang trí.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_85","topic":"Daily Life and Social Activities","word":"deliver","pos":"(v)","ipa":"/dɪˈlɪv.ɚ/","defVi":"giao hàng, vận chuyển, phân phát","defEn":"to take goods, letters, or packages to people's houses or workplaces","examples":["The courier promised to [deliver] the parcel by noon. (=Dịch: Người chuyển phát nhanh đã hứa sẽ giao bưu kiện trước buổi trưa.)","Many local restaurants now [deliver] hot meals straight to your door. (=Dịch: Nhiều nhà hàng địa phương hiện nay giao những bữa ăn nóng hổi đến tận cửa nhà bạn.)","The mail carrier visits our neighborhood daily to [deliver] letters. (=Dịch: Người đưa thư ghé qua khu phố của chúng tôi hàng ngày để phát thư.)"],"ukAudio":"/ai_services/tts3/?q=deliver&lang=en-GB&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=deliver&lang=en-US&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F"},{"id":"lv_0_86","topic":"Daily Life and Social Activities","word":"depart","pos":"(v)","ipa":"/dɪˈpɑːrt/","defVi":"khởi hành, rời đi","defEn":"to leave a place, especially at the start of a journey","examples":["The train is scheduled to [depart] from platform three at 10:00 AM. (=Dịch: Chuyến tàu dự kiến sẽ khởi hành từ sân ga số ba lúc 10:00 sáng.)","Tourists usually [depart] early in the morning to avoid the heat. (=Dịch: Khách du lịch thường khởi hành vào sáng sớm để tránh cái nóng.)","The flight will [depart] as soon as all passengers are boarded. (=Dịch: Chuyến bay sẽ khởi hành ngay khi tất cả hành khách đã lên máy bay.)"],"ukAudio":"/ai_services/tts3/?q=depart&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=depart&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90rt%2F"},{"id":"lv_0_87","topic":"Daily Life and Social Activities","word":"departure","pos":"(n)","ipa":"/dɪˈpɑːr.tʃɚ/","defVi":"sự khởi hành, sự rời đi","defEn":"the act of leaving a place, especially to begin a trip","examples":["Please check the screen for your flight's estimated time of [departure]. (=Dịch: Vui lòng kiểm tra màn hình để biết giờ khởi hành dự kiến của chuyến bay.)","Passengers gathered in the [departure] lounge waiting to board the plane. (=Dịch: Hành khách tập trung tại phòng chờ khởi hành để đợi lên máy bay.)","Her sudden [departure] from the company surprised all of her colleagues. (=Dịch: Sự rời đi đột ngột của cô ấy khỏi công ty đã làm tất cả các đồng nghiệp ngạc nhiên.)"],"ukAudio":"/ai_services/tts3/?q=departure&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90r.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=departure&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90r.t%CA%83%C9%9A%2F"},{"id":"lv_0_88","topic":"Daily Life and Social Activities","word":"dependent","pos":"(adj)","ipa":"/dɪˈpen.dənt/","defVi":"phụ thuộc, dựa dẫm","defEn":"needing the support or help of someone or something else to survive or succeed","examples":["Young children are completely [dependent] on their parents for care. (=Dịch: Trẻ nhỏ hoàn toàn phụ thuộc vào cha mẹ để được chăm sóc.)","The country's economy is heavily [dependent] on oil exports. (=Dịch: Nền kinh tế của quốc gia này phụ thuộc rất nhiều vào xuất khẩu dầu mỏ.)","Success in this project is [dependent] upon everyone's cooperation. (=Dịch: Sự thành công của dự án này phụ thuộc vào sự hợp tác của tất cả mọi người.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F"},{"id":"lv_0_89","topic":"Daily Life and Social Activities","word":"dessert","pos":"(n)","ipa":"/dɪˈzɜːrt/","defVi":"món tráng miệng","defEn":"sweet food eaten at the end of a meal","examples":["We ordered chocolate cake and vanilla ice cream for [dessert]. (=Dịch: Chúng tôi đã gọi bánh sô-cô-la và kem vani làm món tráng miệng.)","Fresh fruit is a healthy option for [dessert] after a heavy dinner. (=Dịch: Trái cây tươi là một lựa chọn lành mạnh cho món tráng miệng sau một bữa tối no nê.)","The chef prepared a special strawberry tart for the evening [dessert]. (=Dịch: Bếp trưởng đã chuẩn bị một chiếc bánh tart dâu tây đặc biệt cho món tráng miệng buổi tối.)"],"ukAudio":"/ai_services/tts3/?q=dessert&lang=en-GB&ipa=%2Fd%C9%AA%CB%88z%C9%9C%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=dessert&lang=en-US&ipa=%2Fd%C9%AA%CB%88z%C9%9C%CB%90rt%2F"},{"id":"lv_0_90","topic":"Daily Life and Social Activities","word":"devote","pos":"(v)","ipa":"/dɪˈvoʊt/","defVi":"cống hiến, dành hết tâm huyết","defEn":"to give an amount of time, attention, or effort to a particular purpose or person","examples":["She decided to [devote] her career to helping underprivileged children. (=Dịch: Cô ấy quyết định cống hiến sự nghiệp của mình để giúp đỡ trẻ em có hoàn cảnh khó khăn.)","He wants to [devote] more time to his family after retirement. (=Dịch: Ông ấy muốn dành nhiều thời gian hơn cho gia đình sau khi nghỉ hưu.)","The scientist will [devote] the next few years to cancer research. (=Dịch: Nhà khoa học sẽ dành vài năm tới để cống hiến cho việc nghiên cứu ung thư.)"],"ukAudio":"/ai_services/tts3/?q=devote&lang=en-GB&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=devote&lang=en-US&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F"},{"id":"lv_0_91","topic":"Daily Life and Social Activities","word":"dining","pos":"(n)","ipa":"/ˈdaɪ.nɪŋ/","defVi":"Việc ăn uống, dùng bữa","defEn":"The activity of eating a meal, especially in a formal or restaurant setting.","examples":["Fine [dining] restaurants usually require customers to reserve a table in advance. (=Dịch: Các nhà hàng cao cấp thường yêu cầu thực khách phải đặt bàn trước.)","The hotel features an outdoor [dining] area with a beautiful ocean view. (=Dịch: Khách sạn có khu vực ăn uống ngoài trời với tầm nhìn tuyệt đẹp ra biển.)","They gathered in the formal [dining] room to celebrate their anniversary. (=Dịch: Họ quây quần trong phòng ăn trang trọng để kỷ niệm ngày cưới của mình.)"],"ukAudio":"/ai_services/tts3/?q=dining&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dining&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_0_92","topic":"Daily Life and Social Activities","word":"disabled","pos":"(adj)","ipa":"/dɪsˈeɪ.bəld/","defVi":"Khuyết tật, tàn tật","defEn":"Having a physical or mental condition that limits movements, senses, or activities.","examples":["The building was renovated to provide better access for [disabled] visitors. (=Dịch: Tòa nhà đã được cải tạo để người khuyết tật có thể tiếp cận thuận tiện hơn.)","Special parking spaces are reserved near the entrance for [disabled] drivers. (=Dịch: Các vị trí đỗ xe đặc biệt gần lối vào được dành riêng cho các tài xế khuyết tật.)","Charities work hard to create equal job opportunities for [disabled] people. (=Dịch: Các tổ chức từ thiện nỗ lực hết mình để tạo ra cơ hội việc làm bình đẳng cho người khuyết tật.)"],"ukAudio":"/ai_services/tts3/?q=disabled&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88e%C9%AA.b%C9%99ld%2F","usAudio":"/ai_services/tts3/?q=disabled&lang=en-US&ipa=%2Fd%C9%AAs%CB%88e%C9%AA.b%C9%99ld%2F"},{"id":"lv_0_93","topic":"Daily Life and Social Activities","word":"disco","pos":"(n)","ipa":"/ˈdɪs.koʊ/","defVi":"Vũ trường, sàn nhảy disco","defEn":"A club or event where people dance to recorded pop or dance music.","examples":["The local youth club hosts a [disco] every Friday evening. (=Dịch: Câu lạc bộ thanh niên địa phương tổ chức một đêm nhạc disco vào mỗi tối thứ Sáu.)","She wore a shiny retro outfit to the 1980s themed [disco]. (=Dịch: Cô ấy đã mặc một bộ trang phục cổ điển lấp lánh đến vũ hội disco mang phong cách thập niên 1980.)","The loud music from the hotel [disco] kept some guests awake at night. (=Dịch: Âm nhạc ồn ào từ sàn nhảy disco của khách sạn đã khiến một số du khách mất ngủ vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=disco&lang=en-GB&ipa=%2F%CB%88d%C9%AAs.ko%CA%8A%2F","usAudio":"/ai_services/tts3/?q=disco&lang=en-US&ipa=%2F%CB%88d%C9%AAs.ko%CA%8A%2F"},{"id":"lv_0_94","topic":"Daily Life and Social Activities","word":"disk","pos":"(n)","ipa":"/dɪsk/","defVi":"Đĩa từ, đĩa máy tính, vật hình đĩa","defEn":"A flat, thin circular object, especially one used for storing computer data.","examples":["Make sure you save a backup copy of your project onto an external [disk]. (=Dịch: Hãy đảm bảo bạn đã lưu một bản sao lưu dự án của mình vào ổ đĩa ngoài.)","The computer cannot read the data because the hard [disk] is corrupted. (=Dịch: Máy tính không thể đọc dữ liệu vì ổ đĩa cứng đã bị hỏng.)","He threw the plastic [disk] across the park for his dog to catch. (=Dịch: Anh ấy ném chiếc đĩa nhựa qua công viên để chú chó của mình bắt lấy.)"],"ukAudio":"/ai_services/tts3/?q=disk&lang=en-GB&ipa=%2Fd%C9%AAsk%2F","usAudio":"/ai_services/tts3/?q=disk&lang=en-US&ipa=%2Fd%C9%AAsk%2F"},{"id":"lv_0_95","topic":"Daily Life and Social Activities","word":"dissatisfied","pos":"(adj)","ipa":"/dɪsˈsæt̬.əs.faɪd/","defVi":"Không hài lòng, bất mãn","defEn":"Not pleased, content, or happy with something.","examples":["Many customers were [dissatisfied] with the poor quality of customer service. (=Dịch: Nhiều khách hàng đã không hài lòng với chất lượng dịch vụ chăm sóc khách hàng kém.)","If you are [dissatisfied] with your purchase, you can request a full refund. (=Dịch: Nếu không hài lòng với sản phẩm đã mua, bạn có thể yêu cầu hoàn tiền toàn bộ.)","The manager held a meeting to address concerns raised by [dissatisfied] employees. (=Dịch: Người quản lý đã tổ chức một cuộc họp để giải quyết những mối bận tâm từ các nhân viên không hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=dissatisfied&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=dissatisfied&lang=en-US&ipa=%2Fd%C9%AAs%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F"},{"id":"lv_0_96","topic":"Daily Life and Social Activities","word":"dock","pos":"(n)","ipa":"/dɑːk/","defVi":"Bến tàu, bến cảng","defEn":"An area of water in a port where ships load, unload, or are repaired.","examples":["The cargo ship remained at the [dock] while workers unloaded the containers. (=Dịch: Tàu chở hàng vẫn neo tại bến tàu trong khi các công nhân dỡ các thùng công-ten-nơ.)","We walked down to the wooden [dock] to watch the sunrise over the bay. (=Dịch: Chúng tôi đi bộ xuống bến tàu bằng gỗ để ngắm bình minh trên vịnh.)","The damaged vessel was towed into the dry [dock] for urgent repairs. (=Dịch: Con tàu bị hư hỏng đã được lai dắt vào ụ cạn để sửa chữa khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=dock&lang=en-GB&ipa=%2Fd%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=dock&lang=en-US&ipa=%2Fd%C9%91%CB%90k%2F"},{"id":"lv_0_97","topic":"Daily Life and Social Activities","word":"dolphin","pos":"(n)","ipa":"/ˈdɑːl.fɪn/","defVi":"Cá heo","defEn":"An intelligent sea mammal that has a sleek body and a curved snout.","examples":["A friendly [dolphin] swam alongside our tour boat for several minutes. (=Dịch: Một chú cá heo thân thiện đã bơi dọc theo thuyền tham quan của chúng tôi trong vài phút.)","Marine biologists are studying how each [dolphin] communicates using distinct clicks. (=Dịch: Các nhà sinh vật biển đang nghiên cứu cách mỗi con cá heo giao tiếp bằng những tiếng lách cách riêng biệt.)","Watching a [dolphin] leap out of the ocean was the highlight of the trip. (=Dịch: Được ngắm nhìn một chú cá heo nhảy vọt lên khỏi mặt biển là điểm nhấn đáng nhớ nhất của chuyến đi.)"],"ukAudio":"/ai_services/tts3/?q=dolphin&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=dolphin&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F"},{"id":"lv_0_98","topic":"Daily Life and Social Activities","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"Quyên góp, hiến tặng","defEn":"To give money, goods, or time to help a person, charity, or organization.","examples":["Local businesses decided to [donate] funds to rebuild the community playground. (=Dịch: Các doanh nghiệp địa phương đã quyết định quyên góp kinh phí để xây dựng lại sân chơi cộng đồng.)","Many citizens regularly [donate] blood at the neighborhood medical clinic. (=Dịch: Nhiều người dân thường xuyên hiến máu tại trạm y tế khu phố.)","She decided to [donate] her old winter coats to a local homeless shelter. (=Dịch: Cô ấy quyết định quyên góp những chiếc áo khoác mùa đông cũ của mình cho một mái ấm người vô gia cư tại địa phương.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_0_99","topic":"Daily Life and Social Activities","word":"dormitory","pos":"(n)","ipa":"/ˈdɔːr.mə.tɔːr.i/","defVi":"Ký túc xá","defEn":"A large building at a college or university where students live.","examples":["Living in a university [dormitory] helps first-year students make new friends quickly. (=Dịch: Sống trong ký túc xá đại học giúp các sinh viên năm nhất nhanh chóng kết bạn mới.)","The campus [dormitory] offers shared kitchens and quiet study lounges on every floor. (=Dịch: Ký túc xá trong khuôn viên trường cung cấp bếp dùng chung và các phòng tự học yên tĩnh ở mỗi tầng.)","She moved out of the [dormitory] into a private apartment during her senior year. (=Dịch: Cô ấy đã chuyển ra khỏi ký túc xá đến sống tại một căn hộ riêng trong năm cuối đại học.)"],"ukAudio":"/ai_services/tts3/?q=dormitory&lang=en-GB&ipa=%2F%CB%88d%C9%94%CB%90r.m%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=dormitory&lang=en-US&ipa=%2F%CB%88d%C9%94%CB%90r.m%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_0_100","topic":"Daily Life and Social Activities","word":"downtown","pos":"(n)","ipa":"/ˌdaʊnˈtaʊn/","defVi":"Khu trung tâm thành phố","defEn":"The central commercial and business district of a city.","examples":["Traffic in [downtown] becomes extremely heavy during weekday rush hours. (=Dịch: Giao thông ở khu trung tâm thành phố trở nên cực kỳ đông đúc vào các giờ cao điểm ngày trong tuần.)","They spent the afternoon exploring art galleries and boutique shops in [downtown]. (=Dịch: Họ đã dành cả buổi chiều để khám phá các phòng trưng bày nghệ thuật và các cửa hàng thời trang ở trung tâm thành phố.)","The new subway line makes traveling between the suburbs and [downtown] much faster. (=Dịch: Tuyến tàu điện ngầm mới giúp việc đi lại giữa vùng ngoại ô và khu trung tâm thành phố nhanh hơn rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=downtown&lang=en-GB&ipa=%2F%CB%8Cda%CA%8An%CB%88ta%CA%8An%2F","usAudio":"/ai_services/tts3/?q=downtown&lang=en-US&ipa=%2F%CB%8Cda%CA%8An%CB%88ta%CA%8An%2F"},{"id":"lv_0_101","topic":"Daily Life and Social Activities","word":"duck","pos":"(n)","ipa":"/dʌk/","defVi":"con vịt","defEn":"a common water bird with short legs, webbed feet, and a broad flat beak","examples":["A mother [duck] was swimming across the pond with her ducklings. (=Dịch: Một con vịt mẹ đang bơi qua ao cùng đàn vịt con.)","The children enjoyed feeding the [duck] near the lake. (=Dịch: Lũ trẻ thích thú cho vịt ăn ở gần hồ.)","Roasted [duck] is a very popular dish in many Asian countries. (=Dịch: Vịt quay là một món ăn rất phổ biến ở nhiều quốc gia châu Á.)"],"ukAudio":"/ai_services/tts3/?q=duck&lang=en-GB&ipa=%2Fd%CA%8Ck%2F","usAudio":"/ai_services/tts3/?q=duck&lang=en-US&ipa=%2Fd%CA%8Ck%2F"},{"id":"lv_0_102","topic":"Daily Life and Social Activities","word":"duty","pos":"(n)","ipa":"/ˈdu.ti/","defVi":"bổn phận, trách nhiệm, nhiệm vụ","defEn":"a moral or legal obligation, or a task that is part of a person's job","examples":["It is every citizen's [duty] to vote in the national elections. (=Dịch: Bỏ phiếu trong các cuộc bầu cử quốc gia là nghĩa vụ của mỗi công dân.)","His main [duty] at the hotel was welcoming international guests. (=Dịch: Nhiệm vụ chính của anh ấy tại khách sạn là chào đón các vị khách quốc tế.)","Doctors feel a strong sense of [duty] toward their patients. (=Dịch: Các bác sĩ luôn có tinh thần trách nhiệm cao đối với bệnh nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=duty&lang=en-GB&ipa=%2F%CB%88du.ti%2F","usAudio":"/ai_services/tts3/?q=duty&lang=en-US&ipa=%2F%CB%88du.ti%2F"},{"id":"lv_0_103","topic":"Daily Life and Social Activities","word":"elderly","pos":"(adj)","ipa":"/ˈɛl.dɚ.li/","defVi":"cao tuổi, lớn tuổi","defEn":"a polite word used to describe someone who is old","examples":["The young boy offered his seat on the bus to an [elderly] woman. (=Dịch: Cậu bé đã nhường chỗ trên xe buýt cho một cụ bà.)","The government is improving healthcare services for [elderly] citizens. (=Dịch: Chính phủ đang cải thiện các dịch vụ chăm sóc sức khỏe cho người cao tuổi.)","Many [elderly] people enjoy gardening as a relaxing hobby. (=Dịch: Nhiều người cao tuổi thích làm vườn như một sở thích giúp thư giãn.)"],"ukAudio":"/ai_services/tts3/?q=elderly&lang=en-GB&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F","usAudio":"/ai_services/tts3/?q=elderly&lang=en-US&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F"},{"id":"lv_0_104","topic":"Daily Life and Social Activities","word":"emergency","pos":"(n)","ipa":"/ɪˈmɝː.dʒən.si/","defVi":"tình trạng khẩn cấp, trường hợp khẩn cấp","defEn":"a sudden, unexpected situation requiring immediate action","examples":["Dial 911 immediately in case of a medical [emergency]. (=Dịch: Hãy gọi 911 ngay lập tức trong trường hợp khẩn cấp về y tế.)","The pilot declared an [emergency] and landed the plane safely. (=Dịch: Phi công đã thông báo tình trạng khẩn cấp và hạ cánh máy bay an toàn.)","Every public building must have clearly marked exits for an [emergency]. (=Dịch: Mọi tòa nhà công cộng đều phải có lối thoát hiểm được đánh dấu rõ ràng phòng khi khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=emergency&lang=en-GB&ipa=%2F%C9%AA%CB%88m%C9%9D%CB%90.d%CA%92%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=emergency&lang=en-US&ipa=%2F%C9%AA%CB%88m%C9%9D%CB%90.d%CA%92%C9%99n.si%2F"},{"id":"lv_0_105","topic":"Daily Life and Social Activities","word":"enquiry","pos":"(n)","ipa":"/ɪnˈkwaɪ.ri/","defVi":"sự hỏi thăm, câu hỏi thắc mắc, cuộc điều tra","defEn":"an act of asking for information, or an official investigation","examples":["We received an [enquiry] from a client about our new software. (=Dịch: Chúng tôi đã nhận được yêu cầu giải đáp thông tin từ một khách hàng về phần mềm mới của mình.)","Please make your [enquiry] at the front desk upon arrival. (=Dịch: Vui lòng hỏi thông tin tại quầy lễ tân ngay khi bạn đến.)","The committee launched a formal [enquiry] into the cause of the accident. (=Dịch: Ủy ban đã tiến hành một cuộc điều tra chính thức về nguyên nhân của vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=enquiry&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.ri%2F","usAudio":"/ai_services/tts3/?q=enquiry&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.ri%2F"},{"id":"lv_0_106","topic":"Daily Life and Social Activities","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký tham gia","defEn":"to officially register as a member or student in a course or organization","examples":["She decided to [enroll] in an intensive English preparation course. (=Dịch: Cô ấy quyết định đăng ký một khóa học luyện thi tiếng Anh cấp tốc.)","You must [enroll] before Friday if you want a guaranteed spot. (=Dịch: Bạn phải đăng ký trước thứ Sáu nếu muốn đảm bảo giữ được một chỗ.)","Thousands of students [enroll] at this university every autumn. (=Dịch: Hàng ngàn sinh viên nhập học vào trường đại học này vào mỗi mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_0_107","topic":"Daily Life and Social Activities","word":"entitle","pos":"(v)","ipa":"/ɪnˈtaɪ.t̬əl/","defVi":"trao quyền, cho phép, cho hưởng quyền lợi","defEn":"to give someone the official right to have or do something","examples":["This discount coupon does not [entitle] you to free delivery. (=Dịch: Phiếu giảm giá này không cho phép bạn nhận giao hàng miễn phí.)","Full-time employees are [entitle]d to four weeks of paid leave. (=Dịch: Nhân viên toàn thời gian được quyền hưởng bốn tuần nghỉ phép có lương.)","Holding this membership will [entitle] you to special VIP lounge access. (=Dịch: Việc sở hữu thẻ thành viên này sẽ cho phép bạn sử dụng phòng chờ VIP đặc biệt.)"],"ukAudio":"/ai_services/tts3/?q=entitle&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=entitle&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.t%CC%AC%C9%99l%2F"},{"id":"lv_0_108","topic":"Daily Life and Social Activities","word":"equip","pos":"(v)","ipa":"/ɪˈkwɪp/","defVi":"trang bị, cung cấp đồ dùng/kỹ năng cần thiết","defEn":"to provide someone or something with the necessary tools, skills, or features","examples":["The school aims to [equip] every science classroom with new microscopes. (=Dịch: Nhà trường đặt mục tiêu trang bị kính hiển vi mới cho mọi phòng học khoa học.)","Higher education should [equip] students for future career challenges. (=Dịch: Giáo dục bậc cao nên trang bị cho sinh viên hành trang trước những thử thách nghề nghiệp trong tương lai.)","Hikers need to [equip] themselves with suitable gear before climbing the mountain. (=Dịch: Người đi bộ đường dài cần tự trang bị đồ dùng thích hợp trước khi leo núi.)"],"ukAudio":"/ai_services/tts3/?q=equip&lang=en-GB&ipa=%2F%C9%AA%CB%88kw%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=equip&lang=en-US&ipa=%2F%C9%AA%CB%88kw%C9%AAp%2F"},{"id":"lv_0_109","topic":"Daily Life and Social Activities","word":"estate","pos":"(n)","ipa":"/ɪˈsteɪt/","defVi":"khu đất lớn, bất động sản, di sản","defEn":"a large area of land, or all the money and property owned by a person","examples":["The wealthy family owns a vast country [estate] surrounded by forests. (=Dịch: Gia đình giàu có này sở hữu một khu dinh cơ rộng lớn ở vùng quê được bao quanh bởi rừng cây.)","He decided to leave his entire [estate] to a local charity. (=Dịch: Ông quyết định để lại toàn bộ gia tài của mình cho một tổ chức từ thiện địa phương.)","A new housing [estate] is being built on the edge of the city. (=Dịch: Một khu dân cư mới đang được xây dựng ở vùng ven thành phố.)"],"ukAudio":"/ai_services/tts3/?q=estate&lang=en-GB&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=estate&lang=en-US&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F"},{"id":"lv_0_110","topic":"Daily Life and Social Activities","word":"exchange","pos":"(n)","ipa":"/ɪksˈtʃeɪndʒ/","defVi":"sự trao đổi, giao dịch, chuyến giao lưu","defEn":"an act of giving something and receiving something else in return, or a short conversation","examples":["The two universities agreed on a student [exchange] program. (=Dịch: Hai trường đại học đã nhất trí về một chương trình trao đổi sinh viên.)","There was a brief [exchange] of ideas during the team meeting. (=Dịch: Đã có một cuộc trao đổi ý kiến ngắn gọn trong suốt buổi họp nhóm.)","Always check the currency [exchange] rate before converting your money. (=Dịch: Hãy luôn kiểm tra tỷ giá hối đoái trước khi đổi tiền.)"],"ukAudio":"/ai_services/tts3/?q=exchange&lang=en-GB&ipa=%2F%C9%AAks%CB%88t%CA%83e%C9%AAnd%CA%92%2F","usAudio":"/ai_services/tts3/?q=exchange&lang=en-US&ipa=%2F%C9%AAks%CB%88t%CA%83e%C9%AAnd%CA%92%2F"},{"id":"lv_0_111","topic":"Daily Life and Social Activities","word":"excursion","pos":"(n)","ipa":"/ɪkˈskɝː.ʒən/","defVi":"chuyến đi chơi ngắn, chuyến dã ngoại","defEn":"a short trip or journey made for pleasure or study","examples":["The class went on an all-day [excursion] to the natural history museum. (=Dịch: Cả lớp đã có một chuyến tham quan kéo dài cả ngày đến bảo tàng lịch sử tự nhiên.)","The resort arranges a boat [excursion] to nearby coral reefs every morning. (=Dịch: Khu nghỉ dưỡng tổ chức một chuyến du ngoạn bằng thuyền đến các rạn san hô gần đó vào mỗi buổi sáng.)","We planned a weekend [excursion] to the mountains to escape the heat. (=Dịch: Chúng tôi đã lên kế hoạch cho một chuyến dã ngoại cuối tuần lên vùng núi để tránh nóng.)"],"ukAudio":"/ai_services/tts3/?q=excursion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sk%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excursion&lang=en-US&ipa=%2F%C9%AAk%CB%88sk%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_0_112","topic":"Daily Life and Social Activities","word":"excuse","pos":"(n)","ipa":"/ɪkˈskjus/","defVi":"lý do, cớ, lời biện hộ","defEn":"a reason given to explain or justify a fault, mistake, or absence","examples":["He made up an [excuse] for arriving late to the lecture. (=Dịch: Anh ấy đã bịa ra một cái cớ vì đến buổi giảng muộn.)","Tiredness is no [excuse] for being careless with your work. (=Dịch: Sự mệt mỏi không phải là lý do để bất cẩn trong công việc.)","She offered a polite [excuse] and left the dinner party early. (=Dịch: Cô ấy đã đưa ra một lời cáo lỗi lịch sự và rời bữa tiệc tối sớm.)"],"ukAudio":"/ai_services/tts3/?q=excuse&lang=en-GB&ipa=%2F%C9%AAk%CB%88skjus%2F","usAudio":"/ai_services/tts3/?q=excuse&lang=en-US&ipa=%2F%C9%AAk%CB%88skjus%2F"},{"id":"lv_0_113","topic":"Daily Life and Social Activities","word":"fare","pos":"(n)","ipa":"/fɛr/","defVi":"tiền xe, tiền vé (tàu, xe, máy bay)","defEn":"the money that you pay to travel by bus, train, taxi, or plane","examples":["The bus [fare] has increased significantly over the past year. (=Dịch: Giá vé xe buýt đã tăng đáng kể trong năm qua.)","Children under five can travel at half [fare] on local trains. (=Dịch: Trẻ em dưới năm tuổi có thể đi các tuyến tàu địa phương với nửa giá vé.)","She did not have enough cash to pay the taxi [fare]. (=Dịch: Cô ấy không có đủ tiền mặt để trả cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ff%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ff%C9%9Br%2F"},{"id":"lv_0_114","topic":"Daily Life and Social Activities","word":"fence","pos":"(n)","ipa":"/fɛns/","defVi":"hàng rào","defEn":"a structure made of wood or wire that surrounds an area of land","examples":["The neighbors built a tall wooden [fence] between their gardens. (=Dịch: Những người hàng xóm đã dựng một hàng rào gỗ cao giữa các khu vườn của họ.)","The dog easily jumped over the low [fence] to chase the ball. (=Dịch: Con chó dễ dàng nhảy qua hàng rào thấp để đuổi theo quả bóng.)","Security guards patrol along the perimeter [fence] every night. (=Dịch: Các nhân viên an ninh tuần tra dọc theo hàng rào bao quanh mỗi đêm.)"],"ukAudio":"/ai_services/tts3/?q=fence&lang=en-GB&ipa=%2Ff%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=fence&lang=en-US&ipa=%2Ff%C9%9Bns%2F"},{"id":"lv_0_115","topic":"Daily Life and Social Activities","word":"finishing","pos":"(n)","ipa":"/ˈfɪn.ɪ.ʃɪŋ/","defVi":"sự hoàn thiện, giai đoạn hoàn tất","defEn":"the act of completing something, or a final treatment applied to a surface","examples":["The painters are putting the [finishing] touches on the new gallery. (=Dịch: Những người thợ sơn đang hoàn thiện các chi tiết cuối cùng cho phòng trưng bày mới.)","Good wood [finishing] protects the furniture from moisture damage. (=Dịch: Lớp phủ hoàn thiện gỗ tốt giúp bảo vệ đồ nội thất khỏi hư hại do ẩm mốc.)","She took pride in [finishing] the difficult assignment on time. (=Dịch: Cô ấy tự hào vì đã hoàn thành bài tập khó đúng hạn.)"],"ukAudio":"/ai_services/tts3/?q=finishing&lang=en-GB&ipa=%2F%CB%88f%C9%AAn.%C9%AA.%CA%83%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=finishing&lang=en-US&ipa=%2F%CB%88f%C9%AAn.%C9%AA.%CA%83%C9%AA%C5%8B%2F"},{"id":"lv_0_116","topic":"Daily Life and Social Activities","word":"firework","pos":"(n)","ipa":"/ˈfaɪr.wɜrk/","defVi":"pháo hoa","defEn":"a small device containing chemicals that explodes with bright lights and loud noises for entertainment","examples":["Crowds gathered along the riverbank to watch the spectacular [firework] display. (=Dịch: Đám đông tụ tập dọc bờ sông để xem màn trình diễn pháo hoa ngoạn mục.)","A single [firework] lit up the dark night sky. (=Dịch: Một quả pháo hoa duy nhất đã thắp sáng bầu trời đêm tăm tối.)","Setting off a [firework] without a permit is illegal in the city. (=Dịch: Bắn pháo hoa không có giấy phép là hành vi bất hợp pháp trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=firework&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%C9%9Crk%2F","usAudio":"/ai_services/tts3/?q=firework&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%C9%9Crk%2F"},{"id":"lv_0_117","topic":"Daily Life and Social Activities","word":"flute","pos":"(n)","ipa":"/flut/","defVi":"cây sáo, ống sáo","defEn":"a high-pitched musical instrument played by blowing across a hole near one end","examples":["She has been playing the [flute] in the school orchestra for three years. (=Dịch: Cô ấy đã chơi sáo trong dàn nhạc của trường được ba năm.)","The gentle melody of the [flute] created a peaceful atmosphere. (=Dịch: Giai điệu êm dịu của tiếng sáo đã tạo nên một bầu không khí yên bình.)","He bought a silver [flute] to replace his old student model. (=Dịch: Anh ấy đã mua một cây sáo bạc để thay thế cho cây sáo tập cũ của mình.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflut%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflut%2F"},{"id":"lv_0_118","topic":"Daily Life and Social Activities","word":"folder","pos":"(n)","ipa":"/ˈfoʊl.dɚ/","defVi":"thư mục, bìa kẹp hồ sơ","defEn":"a cardboard or plastic cover used for keeping loose papers together, or a digital directory","examples":["Please place the signed contract into the blue [folder]. (=Dịch: Vui lòng đặt hợp đồng đã ký vào bìa hồ sơ màu xanh dương.)","You should create a separate [folder] on your computer for each subject. (=Dịch: Bạn nên tạo một thư mục riêng trên máy tính cho từng môn học.)","She handed the interviewer a [folder] containing her certificates. (=Dịch: Cô ấy đã đưa cho người phỏng vấn một tập hồ sơ chứa các chứng chỉ của mình.)"],"ukAudio":"/ai_services/tts3/?q=folder&lang=en-GB&ipa=%2F%CB%88fo%CA%8Al.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=folder&lang=en-US&ipa=%2F%CB%88fo%CA%8Al.d%C9%9A%2F"},{"id":"lv_0_119","topic":"Daily Life and Social Activities","word":"foothill","pos":"(n)","ipa":"/ˈfʊt.hɪl/","defVi":"đồi thấp chân núi, vùng chân núi","defEn":"a low hill at the base of a mountain or mountain range","examples":["The small village is nestled in the [foothill] area near the Alps. (=Dịch: Ngôi làng nhỏ nằm nép mình ở khu vực chân đồi gần dãy Alps.)","Hikers often camp on a gentle [foothill] before attempting the main peak. (=Dịch: Những người đi bộ đường dài thường cắm trại trên một sườn đồi thoai thoải ở chân núi trước khi thử sức với đỉnh núi chính.)","Vineyards thrive on the sunny slopes of the [foothill]. (=Dịch: Các vườn nho phát triển mạnh trên những sườn đồi đầy nắng ở chân núi.)"],"ukAudio":"/ai_services/tts3/?q=foothill&lang=en-GB&ipa=%2F%CB%88f%CA%8At.h%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=foothill&lang=en-US&ipa=%2F%CB%88f%CA%8At.h%C9%AAl%2F"},{"id":"lv_0_120","topic":"Daily Life and Social Activities","word":"footpath","pos":"(n)","ipa":"/ˈfʊt.pæθ/","defVi":"đường mòn đi bộ, lối đi bộ","defEn":"a narrow path designed for people to walk on, especially in the countryside","examples":["Follow this [footpath] through the woods to reach the lake. (=Dịch: Hãy đi theo lối đi bộ này xuyên qua khu rừng để đến bờ hồ.)","The council decided to pave the muddy [footpath] near the school. (=Dịch: Hội đồng đã quyết định lát đường cho lối đi bộ lầy lội gần trường học.)","We enjoyed a quiet stroll along the coastal [footpath]. (=Dịch: Chúng tôi đã có một buổi đi dạo yên bình dọc theo con đường mòn ven biển.)"],"ukAudio":"/ai_services/tts3/?q=footpath&lang=en-GB&ipa=%2F%CB%88f%CA%8At.p%C3%A6%CE%B8%2F","usAudio":"/ai_services/tts3/?q=footpath&lang=en-US&ipa=%2F%CB%88f%CA%8At.p%C3%A6%CE%B8%2F"},{"id":"lv_0_121","topic":"Daily Life and Social Activities","word":"format","pos":"(n)","ipa":"/ˈfɔr.mæt/","defVi":"định dạng, khuôn dạng, cấu trúc","defEn":"the general way in which something is arranged, organized, or produced","examples":["The exam [format] has changed to include more multiple-choice questions. (=Dịch: Định dạng bài thi đã thay đổi để bao gồm nhiều câu hỏi trắc nghiệm hơn.)","Please submit your final report in PDF [format]. (=Dịch: Vui lòng nộp báo cáo cuối cùng của bạn dưới định dạng PDF.)","The new TV show follows an interactive [format] that engages the audience. (=Dịch: Chương trình truyền hình mới áp dụng định dạng tương tác nhằm thu hút khán giả.)"],"ukAudio":"/ai_services/tts3/?q=format&lang=en-GB&ipa=%2F%CB%88f%C9%94r.m%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=format&lang=en-US&ipa=%2F%CB%88f%C9%94r.m%C3%A6t%2F"},{"id":"lv_0_122","topic":"Daily Life and Social Activities","word":"forth","pos":"(adv)","ipa":"/fɔrθ/","defVi":"về phía trước, ra phía trước","defEn":"out into notice or view; forwards in time, place, or order","examples":["The committee decided to bring [forth] several new proposals during the meeting. (=Dịch: Ủy ban đã quyết định đưa ra một số đề xuất mới trong cuộc họp.)","He paced back and [forth] across the room while waiting for the test results. (=Dịch: Anh ấy đi đi lại lại khắp căn phòng trong khi chờ đợi kết quả xét nghiệm.)","From that day [forth], she promised to practice English for an hour each morning. (=Dịch: Kể từ ngày đó trở đi, cô ấy đã hứa sẽ luyện tập tiếng Anh một tiếng vào mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=forth&lang=en-GB&ipa=%2Ff%C9%94r%CE%B8%2F","usAudio":"/ai_services/tts3/?q=forth&lang=en-US&ipa=%2Ff%C9%94r%CE%B8%2F"},{"id":"lv_0_123","topic":"Daily Life and Social Activities","word":"fragile","pos":"(adj)","ipa":"/ˈfræ.dʒəl/","defVi":"dễ vỡ, mỏng manh","defEn":"easily broken, damaged, or destroyed","examples":["Please handle the package carefully because it contains [fragile] glassware. (=Dịch: Xin hãy xử lý gói hàng cẩn thận vì bên trong chứa đồ thủy tinh dễ vỡ.)","The country's economic recovery remains very [fragile] after the crisis. (=Dịch: Sự phục hồi kinh tế của đất nước vẫn còn rất mong manh sau cuộc khủng hoảng.)","Pollution poses a serious threat to this [fragile] marine ecosystem. (=Dịch: Ô nhiễm đặt ra một mối đe dọa nghiêm trọng đối với hệ sinh thái biển mong manh này.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6.d%CA%92%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6.d%CA%92%C9%99l%2F"},{"id":"lv_0_124","topic":"Daily Life and Social Activities","word":"frame","pos":"(n)","ipa":"/freɪm/","defVi":"khung, sườn","defEn":"a rigid structure that surrounds or supports something","examples":["He placed the family photograph inside a simple wooden [frame]. (=Dịch: Anh ấy đặt bức ảnh gia đình vào bên trong một khung gỗ đơn giản.)","The bicycle has a lightweight steel [frame] that makes it easy to carry. (=Dịch: Chiếc xe đạp có khung thép nhẹ giúp dễ dàng mang vác.)","Regular exercise helps build a strong muscular [frame]. (=Dịch: Tập thể dục thường xuyên giúp xây dựng một vóc dáng cơ bắp khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=frame&lang=en-GB&ipa=%2Ffre%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=frame&lang=en-US&ipa=%2Ffre%C9%AAm%2F"},{"id":"lv_0_125","topic":"Daily Life and Social Activities","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ, nguồn tiền","defEn":"an amount of money saved or made available for a particular purpose","examples":["The university established a scholarship [fund] for disadvantaged students. (=Dịch: Trường đại học đã thành lập một quỹ học bổng dành cho các sinh viên có hoàn cảnh khó khăn.)","They ran out of money because their travel [fund] was depleted. (=Dịch: Họ đã hết tiền vì quỹ du lịch của họ bị cạn kiệt.)","The local government allocated a special [fund] to improve road safety. (=Dịch: Chính quyền địa phương đã phân bổ một quỹ đặc biệt để cải thiện an toàn đường bộ.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_0_126","topic":"Daily Life and Social Activities","word":"fundraise","pos":"(v)","ipa":"/ˈfʌndˌreɪz/","defVi":"gây quỹ","defEn":"to collect money for a particular cause, project, or charity","examples":["The students organized a bake sale to [fundraise] for the local animal shelter. (=Dịch: Các học sinh đã tổ chức một buổi bán bánh để gây quỹ cho trạm cứu hộ động vật địa phương.)","Non-profit organizations often [fundraise] through online donation campaigns. (=Dịch: Các tổ chức phi lợi nhuận thường gây quỹ thông qua các chiến dịch quyên góp trực tuyến.)","The charity plans to [fundraise] for clean water projects in rural villages. (=Dịch: Tổ chức từ thiện lên kế hoạch gây quỹ cho các dự án nước sạch ở các làng quê nông thôn.)"],"ukAudio":"/ai_services/tts3/?q=fundraise&lang=en-GB&ipa=%2F%CB%88f%CA%8Cnd%CB%8Cre%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=fundraise&lang=en-US&ipa=%2F%CB%88f%CA%8Cnd%CB%8Cre%C9%AAz%2F"},{"id":"lv_0_127","topic":"Daily Life and Social Activities","word":"garage","pos":"(n)","ipa":"/ɡəˈrɑːʒ/","defVi":"nhà để xe, gara sửa xe","defEn":"a building or indoor space used for keeping or repairing motor vehicles","examples":["He parked his car in the [garage] to protect it from the heavy rain. (=Dịch: Anh ấy đã đỗ xe trong nhà để xe để bảo vệ nó khỏi cơn mưa lớn.)","I need to take my car to the local [garage] for an oil change. (=Dịch: Tôi cần mang xe đến xưởng sửa xe địa phương để thay dầu.)","They converted their old [garage] into a cozy home office. (=Dịch: Họ đã cải tạo nhà để xe cũ của mình thành một văn phòng làm việc ấm cúng tại nhà.)"],"ukAudio":"/ai_services/tts3/?q=garage&lang=en-GB&ipa=%2F%C9%A1%C9%99%CB%88r%C9%91%CB%90%CA%92%2F","usAudio":"/ai_services/tts3/?q=garage&lang=en-US&ipa=%2F%C9%A1%C9%99%CB%88r%C9%91%CB%90%CA%92%2F"},{"id":"lv_0_128","topic":"Daily Life and Social Activities","word":"gardening","pos":"(n)","ipa":"/ˈɡɑːr.dən.ɪŋ/","defVi":"việc làm vườn","defEn":"the activity of growing and taking care of plants in a garden","examples":["Many retirees take up [gardening] as a relaxing outdoor hobby. (=Dịch: Nhiều người về hưu bắt đầu làm vườn như một sở thích thư giãn ngoài trời.)","She bought some new tools to help with the weekend [gardening]. (=Dịch: Cô ấy đã mua một số dụng cụ mới để phục vụ việc làm vườn vào cuối tuần.)","Community [gardening] helps neighbors connect while growing fresh vegetables. (=Dịch: Việc làm vườn cộng đồng giúp những người hàng xóm gắn kết trong khi cùng trồng rau sạch.)"],"ukAudio":"/ai_services/tts3/?q=gardening&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=gardening&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_0_129","topic":"Daily Life and Social Activities","word":"gear","pos":"(n)","ipa":"/ɡɪr/","defVi":"bánh răng; đồ dùng, dụng cụ","defEn":"a toothed wheel in a machine, or equipment used for a specific activity","examples":["Make sure you shift into the correct [gear] when driving uphill. (=Dịch: Hãy chắc chắn rằng bạn chuyển sang đúng số khi lái xe lên dốc.)","Don't forget to pack all your camping [gear] before we leave tomorrow. (=Dịch: Đừng quên đóng gói toàn bộ đồ dùng cắm trại của bạn trước khi chúng ta khởi hành vào ngày mai.)","A broken [gear] caused the entire clock mechanism to stop working. (=Dịch: Một bánh răng bị gãy đã khiến toàn bộ cơ chế đồng hồ ngừng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=gear&lang=en-GB&ipa=%2F%C9%A1%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=gear&lang=en-US&ipa=%2F%C9%A1%C9%AAr%2F"},{"id":"lv_0_130","topic":"Daily Life and Social Activities","word":"generous","pos":"(adj)","ipa":"/ˈdʒen.ər.əs/","defVi":"hào phóng, rộng lượng","defEn":"willing to give money, help, or kindness freely to others","examples":["It was very [generous] of him to pay for everyone's dinner. (=Dịch: Anh ấy thật hào phóng khi trả tiền cho bữa tối của mọi người.)","The museum received a [generous] donation from an anonymous sponsor. (=Dịch: Bảo tàng đã nhận được một khoản quyên góp hậu hĩnh từ một nhà tài trợ ẩn danh.)","The restaurant is famous for serving unusually [generous] portions of food. (=Dịch: Nhà hàng này nổi tiếng với việc phục vụ những phần ăn nhiều khác thường.)"],"ukAudio":"/ai_services/tts3/?q=generous&lang=en-GB&ipa=%2F%CB%88d%CA%92en.%C9%99r.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=generous&lang=en-US&ipa=%2F%CB%88d%CA%92en.%C9%99r.%C9%99s%2F"},{"id":"lv_0_131","topic":"Daily Life and Social Activities","word":"glove","pos":"(n)","ipa":"/ɡlʌv/","defVi":"găng tay, bao tay","defEn":"a piece of clothing worn on the hand with separate parts for each finger","examples":["She wore a thick woolen [glove] on each hand to stay warm in the snow. (=Dịch: Cô ấy đeo một chiếc găng tay len dày trên mỗi bàn tay để giữ ấm trong tuyết.)","The surgeon put on a sterile rubber [glove] before starting the operation. (=Dịch: Bác sĩ phẫu thuật đã đeo găng tay cao su vô trùng trước khi bắt đầu ca mổ.)","He dropped his baseball [glove] on the grass after the practice match. (=Dịch: Anh ấy đã làm rơi găng tay bóng chày của mình trên bãi cỏ sau trận đấu tập.)"],"ukAudio":"/ai_services/tts3/?q=glove&lang=en-GB&ipa=%2F%C9%A1l%CA%8Cv%2F","usAudio":"/ai_services/tts3/?q=glove&lang=en-US&ipa=%2F%C9%A1l%CA%8Cv%2F"},{"id":"lv_0_132","topic":"Daily Life and Social Activities","word":"goodness","pos":"(n)","ipa":"/ˈɡʊd.nəs/","defVi":"lòng tốt, sự nhân từ","defEn":"the quality of being good, kind, or honest","examples":["She always believes in the basic [goodness] of human nature. (=Dịch: Cô luôn tin vào bản tính lương thiện vốn có của con người.)","He showed immense [goodness] by helping the homeless family find shelter. (=Dịch: Anh ấy đã thể hiện lòng tốt bao la khi giúp đỡ gia đình vô gia cư tìm nơi trú ẩn.)","We appreciated the [goodness] and generosity of our neighbors. (=Dịch: Chúng tôi rất trân trọng lòng tốt và sự hào phóng của những người hàng xóm.)"],"ukAudio":"/ai_services/tts3/?q=goodness&lang=en-GB&ipa=%2F%CB%88%C9%A1%CA%8Ad.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=goodness&lang=en-US&ipa=%2F%CB%88%C9%A1%CA%8Ad.n%C9%99s%2F"},{"id":"lv_0_133","topic":"Daily Life and Social Activities","word":"granary","pos":"(n)","ipa":"/ˈɡræn.ə.ri/","defVi":"kho thóc, vựa lúa","defEn":"a building used for storing harvested grain","examples":["The farm has a large wooden [granary] to store wheat for the winter. (=Dịch: Trang trại có một kho thóc lớn bằng gỗ để tích trữ lúa mì cho mùa đông.)","Rats were found nesting inside the old [granary]. (=Dịch: Chuột được phát hiện đang làm tổ bên trong vựa lúa cũ.)","This fertile region is considered the primary [granary] of the country. (=Dịch: Vùng đất màu mỡ này được coi là vựa lúa chính của cả nước.)"],"ukAudio":"/ai_services/tts3/?q=granary&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6n.%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=granary&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6n.%C9%99.ri%2F"},{"id":"lv_0_134","topic":"Daily Life and Social Activities","word":"grand","pos":"(adj)","ipa":"/ɡrænd/","defVi":"hoành tráng, hùng vĩ, vĩ đại","defEn":"large, impressive, and magnificent in appearance or scale","examples":["The hotel features a [grand] entrance with crystal chandeliers. (=Dịch: Khách sạn có lối vào tráng lệ với những chùm đèn pha lê.)","They have [grand] plans to expand their business globally. (=Dịch: Họ có những kế hoạch to lớn nhằm mở rộng hoạt động kinh doanh trên toàn cầu.)","We were amazed by the [grand] view of the snow-capped mountains. (=Dịch: Chúng tôi đã vô cùng kinh ngạc trước khung cảnh hùng vĩ của những ngọn núi phủ đầy tuyết.)"],"ukAudio":"/ai_services/tts3/?q=grand&lang=en-GB&ipa=%2F%C9%A1r%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=grand&lang=en-US&ipa=%2F%C9%A1r%C3%A6nd%2F"},{"id":"lv_0_135","topic":"Daily Life and Social Activities","word":"grateful","pos":"(adj)","ipa":"/ˈɡreɪt.fəl/","defVi":"biết ơn, cảm kích","defEn":"feeling or showing thanks for something pleasing or helpful","examples":["I am deeply [grateful] for all the support you gave me during the exam. (=Dịch: Tôi vô cùng biết ơn tất cả sự hỗ trợ mà bạn đã dành cho tôi trong suốt kỳ thi.)","She was [grateful] to have a warm place to stay during the blizzard. (=Dịch: Cô ấy rất biết ơn vì có một nơi ấm áp để ở trong suốt trận bão tuyết.)","The rescue team received many [grateful] letters from the survivors. (=Dịch: Đội cứu hộ đã nhận được nhiều lá thư bày tỏ lòng biết ơn từ những người sống sót.)"],"ukAudio":"/ai_services/tts3/?q=grateful&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=grateful&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F"},{"id":"lv_0_136","topic":"Daily Life and Social Activities","word":"greek","pos":"(n)","ipa":"/ɡrik/","defVi":"tiếng Hy Lạp, người Hy Lạp","defEn":"the language of Greece, or a person born in Greece","examples":["He is studying ancient [Greek] literature at university. (=Dịch: Anh ấy đang theo học văn học Hy Lạp cổ đại tại trường đại học.)","Many medical terms are derived from ancient [Greek]. (=Dịch: Nhiều thuật ngữ y khoa có nguồn gốc từ tiếng Hy Lạp cổ.)","She met a friendly [Greek] while traveling in Athens. (=Dịch: Cô ấy đã gặp một người Hy Lạp thân thiện khi đi du lịch ở Athens.)"],"ukAudio":"/ai_services/tts3/?q=greek&lang=en-GB&ipa=%2F%C9%A1rik%2F","usAudio":"/ai_services/tts3/?q=greek&lang=en-US&ipa=%2F%C9%A1rik%2F"},{"id":"lv_0_137","topic":"Daily Life and Social Activities","word":"guarantee","pos":"(n)","ipa":"/ˌɡær.ənˈti/","defVi":"sự bảo hành, cam kết, bảo đảm","defEn":"a formal promise that certain conditions will be fulfilled or a product will be repaired","examples":["The television comes with a two-year [guarantee] against defects. (=Dịch: Chiếc ti vi đi kèm với chế độ bảo hành hai năm đối với các lỗi kỹ thuật.)","There is no [guarantee] that the weather will be sunny tomorrow. (=Dịch: Không có gì đảm bảo rằng ngày mai thời tiết sẽ nắng ráo.)","The shop offers a money-back [guarantee] if customers are not satisfied. (=Dịch: Cửa hàng đưa ra cam kết hoàn tiền nếu khách hàng không hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=guarantee&lang=en-GB&ipa=%2F%CB%8C%C9%A1%C3%A6r.%C9%99n%CB%88ti%2F","usAudio":"/ai_services/tts3/?q=guarantee&lang=en-US&ipa=%2F%CB%8C%C9%A1%C3%A6r.%C9%99n%CB%88ti%2F"},{"id":"lv_0_138","topic":"Daily Life and Social Activities","word":"guidebook","pos":"(n)","ipa":"/ˈɡaɪd.bʊk/","defVi":"sách hướng dẫn du lịch","defEn":"a book of information about a place, designed for tourists","examples":["I bought a travel [guidebook] before my trip to Japan. (=Dịch: Tôi đã mua một cuốn sách hướng dẫn du lịch trước chuyến đi Nhật Bản.)","The [guidebook] recommends several affordable restaurants in the old town. (=Dịch: Cuốn sách hướng dẫn gợi ý một số nhà hàng giá cả phải chăng trong khu phố cổ.)","You can find a detailed map of the museum inside this [guidebook]. (=Dịch: Bạn có thể tìm thấy bản đồ chi tiết của bảo tàng bên trong cuốn sách hướng dẫn này.)"],"ukAudio":"/ai_services/tts3/?q=guidebook&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AAd.b%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=guidebook&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AAd.b%CA%8Ak%2F"},{"id":"lv_0_139","topic":"Daily Life and Social Activities","word":"gum","pos":"(n)","ipa":"/ɡʌm/","defVi":"kẹo cao su, chất gôm, nướu răng","defEn":"a sticky substance from trees, or chewing gum, or the tissue around teeth","examples":["He chewed a piece of mint [gum] to freshen his breath. (=Dịch: Anh ấy đã nhai một thanh kẹo cao su bạc hà để thơm miệng.)","Please do not stick your used [gum] under the classroom desks. (=Dịch: Xin vui lòng không dán bã kẹo cao su đã dùng xuống dưới gầm bàn học.)","Her dentist noticed mild bleeding along her [gum] line. (=Dịch: Nha sĩ của cô ấy nhận thấy có hiện tượng chảy máu nhẹ dọc theo viền nướu.)"],"ukAudio":"/ai_services/tts3/?q=gum&lang=en-GB&ipa=%2F%C9%A1%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=gum&lang=en-US&ipa=%2F%C9%A1%CA%8Cm%2F"},{"id":"lv_0_140","topic":"Daily Life and Social Activities","word":"hairdresser","pos":"(n)","ipa":"/ˈherˌdres.ɚ/","defVi":"thợ làm tóc, thợ cắt tóc","defEn":"a person whose job is to cut and style people's hair","examples":["She booked an appointment with her favorite [hairdresser] before the wedding. (=Dịch: Cô ấy đã đặt lịch hẹn với người thợ làm tóc yêu thích của mình trước đám cưới.)","The [hairdresser] suggested a modern hairstyle that suited his face. (=Dịch: Người thợ làm tóc đã gợi ý một kiểu tóc hiện đại phù hợp với khuôn mặt của anh ấy.)","He worked as an apprentice [hairdresser] for three years before opening a salon. (=Dịch: Anh ấy đã làm thợ làm tóc học việc trong ba năm trước khi mở tiệm riêng.)"],"ukAudio":"/ai_services/tts3/?q=hairdresser&lang=en-GB&ipa=%2F%CB%88her%CB%8Cdres.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hairdresser&lang=en-US&ipa=%2F%CB%88her%CB%8Cdres.%C9%9A%2F"},{"id":"lv_0_141","topic":"Daily Life and Social Activities","word":"halfway","pos":"(adv)","ipa":"/ˌhæfˈweɪ/","defVi":"nửa đường, được một nửa, giữa chừng","defEn":"at or to a point midway between two places, points, or times","examples":["We stopped to rest when we were [halfway] up the mountain. (=Dịch: Chúng tôi dừng lại nghỉ ngơi khi đã đi được nửa đường lên núi.)","The battery died when the movie was only [halfway] finished. (=Dịch: Pin đã hết khi bộ phim mới chỉ chiếu được một nửa.)","She agreed to meet me [halfway] in negotiating the final price. (=Dịch: Cô ấy đã đồng ý nhượng bộ để đi đến thỏa hiệp với tôi khi đàm phán mức giá cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=halfway&lang=en-GB&ipa=%2F%CB%8Ch%C3%A6f%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=halfway&lang=en-US&ipa=%2F%CB%8Ch%C3%A6f%CB%88we%C9%AA%2F"},{"id":"lv_0_142","topic":"Daily Life and Social Activities","word":"handbag","pos":"(n)","ipa":"/ˈhænd.bæɡ/","defVi":"túi xách tay","defEn":"a small bag used especially by women to carry personal items like money and keys","examples":["She realized she had left her [handbag] on the bus. (=Dịch: Cô ấy nhận ra mình đã để quên túi xách trên xe buýt.)","He bought a leather [handbag] as a birthday present for his mother. (=Dịch: Anh ấy đã mua một chiếc túi xách da làm quà sinh nhật cho mẹ mình.)","Please do not leave your [handbag] unattended in the waiting area. (=Dịch: Xin vui lòng không để túi xách của bạn ở khu vực chờ mà không có người trông coi.)"],"ukAudio":"/ai_services/tts3/?q=handbag&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=handbag&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F"},{"id":"lv_0_143","topic":"Daily Life and Social Activities","word":"hang","pos":"(v)","ipa":"/hæŋ/","defVi":"treo, móc","defEn":"to fasten or attach something at the top so that the lower part is free","examples":["You can [hang] your coat behind the door. (=Dịch: Bạn có thể treo áo khoác của mình ở phía sau cánh cửa.)","They decided to [hang] several family photographs in the hallway. (=Dịch: Họ quyết định treo vài bức ảnh gia đình ở hành lang.)","The curtains [hang] loosely from the metal rod. (=Dịch: Rèm cửa rủ xuống nhẹ nhàng từ thanh treo kim loại.)"],"ukAudio":"/ai_services/tts3/?q=hang&lang=en-GB&ipa=%2Fh%C3%A6%C5%8B%2F","usAudio":"/ai_services/tts3/?q=hang&lang=en-US&ipa=%2Fh%C3%A6%C5%8B%2F"},{"id":"lv_0_144","topic":"Daily Life and Social Activities","word":"hardback","pos":"(n)","ipa":"/ˈhɑːrd.bæk/","defVi":"sách bìa cứng","defEn":"a book that has a stiff, solid cover rather than a flexible paper one","examples":["The novel was initially released only in [hardback]. (=Dịch: Cuốn tiểu thuyết ban đầu chỉ được phát hành dưới dạng sách bìa cứng.)","I prefer to buy a [hardback] because it lasts much longer. (=Dịch: Tôi thích mua sách bìa cứng hơn vì nó dùng được lâu hơn nhiều.)","The library keeps a rare [hardback] edition of the encyclopedia. (=Dịch: Thư viện lưu giữ một ấn bản bìa cứng hiếm có của bộ bách khoa toàn thư.)"],"ukAudio":"/ai_services/tts3/?q=hardback&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90rd.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=hardback&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90rd.b%C3%A6k%2F"},{"id":"lv_0_145","topic":"Daily Life and Social Activities","word":"heading","pos":"(n)","ipa":"/ˈhed.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a line of text serving to indicate what a passage or section is about","examples":["Each chapter in the textbook starts with a clear [heading]. (=Dịch: Mỗi chương trong sách giáo khoa đều bắt đầu bằng một tiêu đề rõ ràng.)","You should match each paragraph with the correct [heading] in the reading test. (=Dịch: Bạn nên nối từng đoạn văn với tiêu đề chính xác trong bài thi đọc.)","Make sure to write your name under the main [heading] of the form. (=Dịch: Hãy chắc chắn rằng bạn đã viết tên của mình dưới tiêu đề chính của biểu mẫu.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F"},{"id":"lv_0_146","topic":"Daily Life and Social Activities","word":"heater","pos":"(n)","ipa":"/ˈhiː.t̬ɚ/","defVi":"máy sưởi, lò sưởi","defEn":"an apparatus or machine used to supply heat or warm a room","examples":["We turned on the electric [heater] because the bedroom was freezing. (=Dịch: Chúng tôi đã bật máy sưởi điện vì phòng ngủ lạnh cóng.)","The water [heater] broke down, so we had to take cold showers. (=Dịch: Bình nóng lạnh bị hỏng nên chúng tôi phải tắm nước lạnh.)","Do not place any clothes directly on top of the portable [heater]. (=Dịch: Không đặt bất kỳ quần áo nào trực tiếp lên trên máy sưởi di động.)"],"ukAudio":"/ai_services/tts3/?q=heater&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=heater&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_0_147","topic":"Daily Life and Social Activities","word":"heating","pos":"(n)","ipa":"/ˈhiː.t̬ɪŋ/","defVi":"hệ thống sưởi, sự sưởi ấm","defEn":"a system or method used for keeping a building or room warm","examples":["Central [heating] keeps the entire apartment warm throughout the winter. (=Dịch: Hệ thống sưởi trung tâm giữ cho toàn bộ căn hộ ấm áp suốt mùa đông.)","The cost of [heating] has increased significantly this year. (=Dịch: Chi phí sưởi ấm đã tăng lên đáng kể trong năm nay.)","Our office [heating] was turned off during the weekend maintenance. (=Dịch: Hệ thống sưởi của văn phòng chúng tôi đã bị tắt trong đợt bảo trì cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=heating&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heating&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_148","topic":"Daily Life and Social Activities","word":"highlight","pos":"(n)","ipa":"/ˈhaɪ.laɪt/","defVi":"điểm nổi bật, nét đặc sắc","defEn":"the best, most exciting, or most important part of an event or period","examples":["The fireworks display was the [highlight] of the festival. (=Dịch: Màn trình diễn pháo hoa là điểm nhấn nổi bật của lễ hội.)","Visiting the ancient castle was the [highlight] of our European trip. (=Dịch: Chuyến tham quan lâu đài cổ kính là điểm nhấn đáng nhớ trong chuyến đi châu Âu của chúng tôi.)","The coach showed a video [highlight] of the team's best goals. (=Dịch: Huấn luyện viên đã cho xem một video tổng hợp những bàn thắng đẹp nhất của toàn đội.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F"},{"id":"lv_0_149","topic":"Daily Life and Social Activities","word":"hive","pos":"(n)","ipa":"/haɪv/","defVi":"tổ ong, thùng nuôi ong","defEn":"a structure in which bees live and make honey","examples":["Thousands of worker bees returned to the [hive] before sunset. (=Dịch: Hàng ngàn chú ong thợ đã quay trở về tổ trước khi mặt trời lặn.)","The beekeeper carefully inspected each wooden [hive] in the yard. (=Dịch: Người nuôi ong cẩn thận kiểm tra từng tổ ong bằng gỗ trong sân.)","During peak hours, the busy kitchen was a [hive] of activity. (=Dịch: Vào những giờ cao điểm, căn bếp bận rộn là một nơi vô cùng tấp nập và nhộn nhịp.)"],"ukAudio":"/ai_services/tts3/?q=hive&lang=en-GB&ipa=%2Fha%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=hive&lang=en-US&ipa=%2Fha%C9%AAv%2F"},{"id":"lv_0_150","topic":"Daily Life and Social Activities","word":"holland","pos":"(n)","ipa":"/ˈhɑː.lənd/","defVi":"Hà Lan","defEn":"a common informal name for the Netherlands, a country in northwestern Europe","examples":["Tulips and windmills are famous symbols of [Holland]. (=Dịch: Hoa tulip và cối xay gió là những biểu tượng nổi tiếng của Hà Lan.)","She spent a semester studying international law in [Holland]. (=Dịch: Cô ấy đã dành một học kỳ để theo học ngành luật quốc tế tại Hà Lan.)","Cycling is one of the most popular forms of transport in [Holland]. (=Dịch: Đi xe đạp là một trong những phương tiện di chuyển phổ biến nhất ở Hà Lan.)"],"ukAudio":"/ai_services/tts3/?q=holland&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=holland&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90.l%C9%99nd%2F"},{"id":"lv_0_151","topic":"Daily Life and Social Activities","word":"homestay","pos":"(n)","ipa":"/ˈhoʊm.steɪ/","defVi":"hình thức ở trọ cùng gia đình bản xứ (homestay)","defEn":"an arrangement where a student or tourist stays with a local family","examples":["Living in a [homestay] helped him improve his English speaking skills rapidly. (=Dịch: Việc sống cùng gia đình bản xứ đã giúp anh ấy cải thiện kỹ năng nói tiếng Anh một cách nhanh chóng.)","The agency arranged a cozy [homestay] near the university campus. (=Dịch: Công ty đã sắp xếp một nơi ở cùng gia đình bản xứ ấm cúng gần khuôn viên trường đại học.)","Many international students prefer a [homestay] to learn about the local culture. (=Dịch: Nhiều du học sinh thích ở cùng gia đình bản xứ để tìm hiểu về văn hóa địa phương.)"],"ukAudio":"/ai_services/tts3/?q=homestay&lang=en-GB&ipa=%2F%CB%88ho%CA%8Am.ste%C9%AA%2F","usAudio":"/ai_services/tts3/?q=homestay&lang=en-US&ipa=%2F%CB%88ho%CA%8Am.ste%C9%AA%2F"},{"id":"lv_0_152","topic":"Daily Life and Social Activities","word":"honest","pos":"(adj)","ipa":"/ˈɑː.nɪst/","defVi":"trung thực, thành thật","defEn":"telling the truth and not lying, cheating, or stealing","examples":["To be completely [honest], I did not really enjoy the movie. (=Dịch: Thành thật mà nói, tôi thực sự không thích bộ phim cho lắm.)","She is known as an [honest] and hardworking employee. (=Dịch: Cô ấy được biết đến là một nhân viên trung thực và chăm chỉ.)","He gave an [honest] answer when the teacher questioned him. (=Dịch: Cậu ấy đã đưa ra câu trả lời thành thật khi giáo viên gặng hỏi.)"],"ukAudio":"/ai_services/tts3/?q=honest&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=honest&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F"},{"id":"lv_0_153","topic":"Daily Life and Social Activities","word":"hostel","pos":"(n)","ipa":"/ˈhɑː.stəl/","defVi":"nhà trọ du lịch, ký túc xá giá rẻ","defEn":"an inexpensive lodging facility, especially for young travelers and backpackers","examples":["We stayed at a youth [hostel] near the train station to save money. (=Dịch: Chúng tôi đã ở tại một nhà nghỉ thanh niên gần nhà ga để tiết kiệm chi phí.)","The [hostel] provides clean shared dorms and a communal kitchen. (=Dịch: Nhà nghỉ cung cấp các phòng ngủ tập thể sạch sẽ và một gian bếp chung.)","Solo backpackers often choose a [hostel] to meet other travelers. (=Dịch: Những người du lịch bụi một mình thường chọn nhà nghỉ giá rẻ để gặp gỡ các du khách khác.)"],"ukAudio":"/ai_services/tts3/?q=hostel&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=hostel&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90.st%C9%99l%2F"},{"id":"lv_0_154","topic":"Daily Life and Social Activities","word":"hugely","pos":"(adv)","ipa":"/ˈhjuːdʒ.li/","defVi":"vô cùng, cực kỳ","defEn":"to a very great degree; extremely","examples":["The new smartphone model has become [hugely] popular among teenagers. (=Dịch: Mẫu điện thoại thông minh mới đã trở nên cực kỳ phổ biến trong giới thanh thiếu niên.)","Her first novel was [hugely] successful around the world. (=Dịch: Cuốn tiểu thuyết đầu tay của cô đã thành công vang dội trên toàn thế giới.)","Renewable energy is a [hugely] important topic in modern science. (=Dịch: Năng lượng tái tạo là một chủ đề vô cùng quan trọng trong khoa học hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=hugely&lang=en-GB&ipa=%2F%CB%88hju%CB%90d%CA%92.li%2F","usAudio":"/ai_services/tts3/?q=hugely&lang=en-US&ipa=%2F%CB%88hju%CB%90d%CA%92.li%2F"},{"id":"lv_0_155","topic":"Daily Life and Social Activities","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.t̬ɚ/","defVi":"thợ săn, kẻ săn mồi","defEn":"a person or animal that searches for and kills wild animals for food or sport","examples":["The ancient [hunter] used a bow and arrow to catch food. (=Dịch: Người thợ săn cổ đại đã sử dụng cung tên để săn bắt thức ăn.)","Owls are skilled nocturnal [hunter] species that search for mice at night. (=Dịch: Cú mèo là loài săn mồi ban đêm điêu luyện chuyên tìm kiếm chuột vào ban đêm.)","A local [hunter] guided the research team through the dense forest. (=Dịch: Một thợ săn địa phương đã dẫn đường cho nhóm nghiên cứu băng qua khu rừng rậm rạp.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%CC%AC%C9%9A%2F"},{"id":"lv_0_156","topic":"Daily Life and Social Activities","word":"hut","pos":"(n)","ipa":"/hʌt/","defVi":"túp lều, nhà gỗ nhỏ","defEn":"a small, simple building, usually consisting of only one room","examples":["The fishermen built a wooden [hut] near the shore to store their nets. (=Dịch: Các ngư dân đã dựng một túp lều gỗ gần bờ để cất giữ lưới.)","We took shelter from the sudden storm inside an old mountain [hut]. (=Dịch: Chúng tôi đã trú cơn bão bất ngờ bên trong một túp lều cũ trên núi.)","The isolated [hut] had no electricity or running water. (=Dịch: Túp lều biệt lập không có điện hay nước máy.)"],"ukAudio":"/ai_services/tts3/?q=hut&lang=en-GB&ipa=%2Fh%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=hut&lang=en-US&ipa=%2Fh%CA%8Ct%2F"},{"id":"lv_0_157","topic":"Daily Life and Social Activities","word":"identity","pos":"(n)","ipa":"/aɪˈden.t̬ə.t̬i/","defVi":"danh tính, bản sắc","defEn":"who a person is, or the qualities of a person or group that make them different from others","examples":["You must show proof of your [identity] before boarding the flight. (=Dịch: Bạn phải xuất trình giấy tờ chứng minh danh tính trước khi lên chuyến bay.)","Language plays a vital role in preserving cultural [identity]. (=Dịch: Ngôn ngữ đóng vai trò thiết yếu trong việc bảo tồn bản sắc văn hóa.)","The criminal used a fake name to conceal his real [identity]. (=Dịch: Tên tội phạm đã sử dụng một cái tên giả để che giấu danh tính thực sự của mình.)"],"ukAudio":"/ai_services/tts3/?q=identity&lang=en-GB&ipa=%2Fa%C9%AA%CB%88den.t%CC%AC%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=identity&lang=en-US&ipa=%2Fa%C9%AA%CB%88den.t%CC%AC%C9%99.t%CC%ACi%2F"},{"id":"lv_0_158","topic":"Daily Life and Social Activities","word":"incident","pos":"(n)","ipa":"/ˈɪn.sə.dənt/","defVi":"sự cố, biến cố, vụ việc","defEn":"an event, especially one that is unusual, important, or violent","examples":["The police are investigating a serious [incident] that occurred downtown. (=Dịch: Cảnh sát đang điều tra một vụ việc nghiêm trọng xảy ra ở trung tâm thành phố.)","Fortunately, the flight landed safely without any [incident]. (=Dịch: May mắn thay, chuyến bay đã hạ cánh an toàn mà không xảy ra bất kỳ sự cố nào.)","She described the minor traffic [incident] to her insurance company. (=Dịch: Cô ấy đã miêu tả sự cố giao thông nhỏ với công ty bảo hiểm của mình.)"],"ukAudio":"/ai_services/tts3/?q=incident&lang=en-GB&ipa=%2F%CB%88%C9%AAn.s%C9%99.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=incident&lang=en-US&ipa=%2F%CB%88%C9%AAn.s%C9%99.d%C9%99nt%2F"},{"id":"lv_0_159","topic":"Daily Life and Social Activities","word":"indicator","pos":"(n)","ipa":"/ˈɪn.də.keɪ.t̬ɚ/","defVi":"chỉ số, dấu hiệu, thiết bị báo hiệu","defEn":"a sign, fact, or measure that shows the state or level of something","examples":["Consumer spending is an important [indicator] of economic health. (=Dịch: Chi tiêu của người tiêu dùng là một chỉ số quan trọng về sức khỏe của nền kinh tế.)","High employee turnover can be a clear [indicator] of poor management. (=Dịch: Tỷ lệ luân chuyển nhân viên cao có thể là một dấu hiệu rõ ràng của việc quản lý kém cỏi.)","The battery [indicator] on my laptop started flashing red. (=Dịch: Đèn báo pin trên máy tính xách tay của tôi bắt đầu nhấp nháy đỏ.)"],"ukAudio":"/ai_services/tts3/?q=indicator&lang=en-GB&ipa=%2F%CB%88%C9%AAn.d%C9%99.ke%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=indicator&lang=en-US&ipa=%2F%CB%88%C9%AAn.d%C9%99.ke%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_0_160","topic":"Daily Life and Social Activities","word":"ingredient","pos":"(n)","ipa":"/ɪnˈɡriː.di.ənt/","defVi":"nguyên liệu, thành phần","defEn":"one of the foods or substances that are combined to make a particular dish or product","examples":["Fresh garlic is an essential [ingredient] in Italian cuisine. (=Dịch: Tỏi tươi là một nguyên liệu thiết yếu trong ẩm thực Ý.)","Always check the [ingredient] list on skincare products for allergens. (=Dịch: Hãy luôn kiểm tra danh sách thành phần trên các sản phẩm chăm sóc da để xem có chất gây dị ứng hay không.)","Trust is the key [ingredient] for a lasting friendship. (=Dịch: Sự tin tưởng là yếu tố then chốt cho một tình bạn lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=ingredient&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=ingredient&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F"},{"id":"lv_0_161","topic":"Daily Life and Social Activities","word":"institution","pos":"(n)","ipa":"/ˌɪn.stəˈtuː.ʃən/","defVi":"tổ chức, cơ quan, thể chế","defEn":"a large and important organization, such as a university or bank","examples":["Harvard University is a world-renowned educational [institution]. (=Dịch: Đại học Harvard là một tổ chức giáo dục nổi tiếng thế giới.)","The central bank is an independent financial [institution]. (=Dịch: Ngân hàng trung ương là một định chế tài chính độc lập.)","Marriage is viewed as a sacred social [institution] in many cultures. (=Dịch: Hôn nhân được coi là một thể chế xã hội thiêng liêng trong nhiều nền văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=institution&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88tu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=institution&lang=en-US&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88tu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_0_162","topic":"Daily Life and Social Activities","word":"interior","pos":"(adj)","ipa":"/ɪnˈtɪr.i.ɚ/","defVi":"bên trong, nội thất","defEn":"inside or situated on the inside; inner","examples":["The [interior] walls of the house were painted soft white. (=Dịch: Các bức tường bên trong ngôi nhà được sơn màu trắng dịu nhẹ.)","She hired an [interior] designer to decorate her new apartment. (=Dịch: Cô ấy đã thuê một nhà thiết kế nội thất để trang trí căn hộ mới của mình.)","The car has a luxurious leather [interior] finish. (=Dịch: Chiếc xe có phần hoàn thiện nội thất bọc da sang trọng.)"],"ukAudio":"/ai_services/tts3/?q=interior&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%AAr.i.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=interior&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%AAr.i.%C9%9A%2F"},{"id":"lv_0_163","topic":"Daily Life and Social Activities","word":"jar","pos":"(n)","ipa":"/dʒɑːr/","defVi":"hũ, lọ (thường bằng thủy tinh, miệng rộng)","defEn":"a glass container with a wide opening, used for storing food or liquids","examples":["She opened a [jar] of strawberry jam to spread on her toast. (=Dịch: Cô ấy đã mở một lọ mứt dâu tây để phết lên bánh mì nướng của mình.)","He keeps all his spare coins in a large glass [jar]. (=Dịch: Anh ấy giữ tất cả tiền xu lẻ của mình trong một chiếc hũ thủy tinh lớn.)","The pickles are preserved tightly in a sealed [jar]. (=Dịch: Dưa muối được bảo quản cẩn thận trong một chiếc lọ đậy kín.)"],"ukAudio":"/ai_services/tts3/?q=jar&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=jar&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90r%2F"},{"id":"lv_0_164","topic":"Daily Life and Social Activities","word":"joint","pos":"(adj)","ipa":"/dʒɔɪnt/","defVi":"chung, cùng nhau, liên kết","defEn":"shared, held, or made by two or more people together","examples":["The two countries launched a [joint] effort to protect the rainforest. (=Dịch: Hai quốc gia đã phát động một nỗ lực chung nhằm bảo vệ rừng nhiệt đới.)","They opened a [joint] bank account after getting married. (=Dịch: Họ đã mở một tài khoản ngân hàng chung sau khi kết hôn.)","The report was a [joint] publication by several leading universities. (=Dịch: Báo cáo này là một ấn phẩm chung của một số trường đại học hàng đầu.)"],"ukAudio":"/ai_services/tts3/?q=joint&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=joint&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AAnt%2F"},{"id":"lv_0_165","topic":"Daily Life and Social Activities","word":"jot","pos":"(v)","ipa":"/dʒɑːt/","defVi":"ghi chép nhanh, ghi vội","defEn":"to write something down quickly and briefly","examples":["Let me [jot] down your phone number before I forget it. (=Dịch: Để tôi ghi nhanh số điện thoại của bạn lại trước khi tôi quên mất.)","The reporter paused to [jot] a few notes in his pad. (=Dịch: Người phóng viên dừng lại để ghi vội vài dòng ghi chú vào cuốn sổ của mình.)","She managed to [jot] down the license plate number of the car. (=Dịch: Cô ấy đã kịp ghi lại biển số của chiếc xe ô tô.)"],"ukAudio":"/ai_services/tts3/?q=jot&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=jot&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90t%2F"},{"id":"lv_0_166","topic":"Daily Life and Social Activities","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba/ngã tư, điểm nối","defEn":"a place where two or more roads, railway lines, or rivers meet","examples":["Turn left at the next [junction] to reach the highway. (=Dịch: Hãy rẽ trái ở nút giao tiếp theo để đi vào đường cao tốc.)","The town developed rapidly because it was located at a major railway [junction]. (=Dịch: Thị trấn phát triển nhanh chóng vì nằm tại một nút giao đường sắt lớn.)","Traffic was held up due to an accident at the busy [junction]. (=Dịch: Giao thông bị đình trệ do một vụ tai nạn tại nút giao thông đông đúc.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_0_167","topic":"Daily Life and Social Activities","word":"junior","pos":"(adj)","ipa":"/ˈdʒuːn.jɚ/","defVi":"cấp dưới, ít kinh nghiệm hơn, sơ cấp","defEn":"having a lower rank or less experience than others in an organization","examples":["She started her career as a [junior] designer at a local firm. (=Dịch: Cô ấy bắt đầu sự nghiệp với tư cách là một nhà thiết kế sơ cấp tại một công ty địa phương.)","The company offers special training programs for [junior] staff members. (=Dịch: Công ty cung cấp các chương trình đào tạo đặc biệt dành cho các nhân viên mới vào nghề.)","He was promoted to project manager after working as a [junior] developer for two years. (=Dịch: Anh ấy đã được thăng chức lên quản lý dự án sau hai năm làm việc ở vị trí lập trình viên sơ cấp.)"],"ukAudio":"/ai_services/tts3/?q=junior&lang=en-GB&ipa=%2F%CB%88d%CA%92u%CB%90n.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=junior&lang=en-US&ipa=%2F%CB%88d%CA%92u%CB%90n.j%C9%9A%2F"},{"id":"lv_0_168","topic":"Daily Life and Social Activities","word":"kangaroo","pos":"(n)","ipa":"/ˌkæŋ.ɡəˈruː/","defVi":"con chuột túi (chuột túi Úc)","defEn":"a large Australian animal that moves by jumping on its strong back legs and carries its young in a pouch","examples":["A [kangaroo] can leap great distances with its powerful hind legs. (=Dịch: Chuột túi có thể nhảy những khoảng cách rất xa nhờ đôi chân sau khỏe mạnh.)","The mother [kangaroo] carried her baby in her warm pouch. (=Dịch: Chuột túi mẹ mang con của mình trong chiếc túi ấm áp.)","Tourists often visit the national park hoping to see a wild [kangaroo]. (=Dịch: Khách du lịch thường ghé thăm vườn quốc gia với hy vọng nhìn thấy một con chuột túi hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=kangaroo&lang=en-GB&ipa=%2F%CB%8Ck%C3%A6%C5%8B.%C9%A1%C9%99%CB%88ru%CB%90%2F","usAudio":"/ai_services/tts3/?q=kangaroo&lang=en-US&ipa=%2F%CB%8Ck%C3%A6%C5%8B.%C9%A1%C9%99%CB%88ru%CB%90%2F"},{"id":"lv_0_169","topic":"Daily Life and Social Activities","word":"keyboard","pos":"(n)","ipa":"/ˈkiː.bɔːrd/","defVi":"bàn phím (máy tính, nhạc cụ)","defEn":"a set of keys on a computer, typewriter, or musical instrument","examples":["He spilled coffee on his computer [keyboard] and broke several keys. (=Dịch: Anh ấy đã làm đổ cà phê lên bàn phím máy tính và làm hỏng một vài phím bấm.)","She practiced playing chords on the electronic [keyboard] every evening. (=Dịch: Cô ấy luyện tập đánh các hợp âm trên đàn phím điện tử vào mỗi buổi tối.)","A wireless [keyboard] makes it easier to work comfortably at a desk. (=Dịch: Một chiếc bàn phím không dây giúp làm việc thoải mái hơn tại bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki%CB%90.b%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki%CB%90.b%C9%94%CB%90rd%2F"},{"id":"lv_0_170","topic":"Daily Life and Social Activities","word":"kick","pos":"(v)","ipa":"/kɪk/","defVi":"đá (bằng chân)","defEn":"to hit someone or something with your foot","examples":["The striker managed to [kick] the ball past the goalkeeper into the net. (=Dịch: Tiền đạo đã sút được bóng qua người thủ môn vào lưới.)","She tried to [kick] the door open because her hands were full. (=Dịch: Cô ấy đã cố đá mở cửa vì hai tay đang mang đầy đồ.)","Children love to splash and [kick] their legs while swimming. (=Dịch: Trẻ em rất thích vỗ nước và đập chân khi bơi.)"],"ukAudio":"/ai_services/tts3/?q=kick&lang=en-GB&ipa=%2Fk%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=kick&lang=en-US&ipa=%2Fk%C9%AAk%2F"},{"id":"lv_0_171","topic":"Daily Life and Social Activities","word":"kit","pos":"(n)","ipa":"/kɪt/","defVi":"bộ dụng cụ, bộ đồ nghề, trang bị","defEn":"a set of tools, clothes, or equipment needed for a particular activity","examples":["Every driver should carry a first-aid [kit] in their vehicle. (=Dịch: Mỗi tài xế nên mang theo một bộ dụng cụ sơ cứu trên xe của mình.)","He bought a tool [kit] to help assemble the new furniture. (=Dịch: Anh ấy đã mua một bộ dụng cụ để giúp lắp ráp đồ nội thất mới.)","The emergency survival [kit] contains water, rations, and a flashlight. (=Dịch: Bộ dụng cụ sinh tồn khẩn cấp bao gồm nước uống, khẩu phần ăn và đèn pin.)"],"ukAudio":"/ai_services/tts3/?q=kit&lang=en-GB&ipa=%2Fk%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=kit&lang=en-US&ipa=%2Fk%C9%AAt%2F"},{"id":"lv_0_172","topic":"Daily Life and Social Activities","word":"latin","pos":"(adj)","ipa":"/ˈlæt.n̩/","defVi":"(thuộc) tiếng La-tinh; (thuộc) vùng/văn hóa Mỹ La-tinh","defEn":"relating to the ancient language of Rome, or to people and cultures influenced by romance languages","examples":["Many modern medical terms are derived from [Latin] words. (=Dịch: Nhiều thuật ngữ y khoa hiện đại có nguồn gốc từ các từ tiếng Latinh.)","The festival celebrates the rich traditions of [Latin] music and dance. (=Dịch: Lễ hội tôn vinh những truyền thống phong phú của âm nhạc và vũ điệu Latinh.)","Most European languages are written using the [Latin] alphabet. (=Dịch: Hầu hết các ngôn ngữ châu Âu đều được viết bằng bảng chữ cái Latinh.)"],"ukAudio":"/ai_services/tts3/?q=latin&lang=en-GB&ipa=%2F%CB%88l%C3%A6t.n%CC%A9%2F","usAudio":"/ai_services/tts3/?q=latin&lang=en-US&ipa=%2F%CB%88l%C3%A6t.n%CC%A9%2F"},{"id":"lv_0_173","topic":"Daily Life and Social Activities","word":"leaflet","pos":"(n)","ipa":"/ˈlif.lət/","defVi":"tờ rơi, tờ quảng cáo gấp","defEn":"a printed sheet of paper containing information or advertising, usually distributed free","examples":["Volunteers handed out an informational [leaflet] to pedestrians on the street. (=Dịch: Các tình nguyện viên đã phát tờ rơi thông tin cho người đi bộ trên đường phố.)","I picked up a [leaflet] about local tourist attractions at the hotel lobby. (=Dịch: Tôi đã lấy một tờ rơi về các điểm du lịch địa phương tại sảnh khách sạn.)","The health clinic designed a colorful [leaflet] to promote healthy eating habits. (=Dịch: Phòng khám y tế đã thiết kế một tờ rơi nhiều màu sắc để quảng bá thói quen ăn uống lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=leaflet&lang=en-GB&ipa=%2F%CB%88lif.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=leaflet&lang=en-US&ipa=%2F%CB%88lif.l%C9%99t%2F"},{"id":"lv_0_174","topic":"Daily Life and Social Activities","word":"lifeboat","pos":"(n)","ipa":"/ˈlaɪf.boʊt/","defVi":"thuyền cứu sinh","defEn":"a specially constructed boat used for rescuing people in danger at sea","examples":["The ship's crew lowered the [lifeboat] into the water during the safety drill. (=Dịch: Thủy thủ đoàn đã hạ xuồng cứu sinh xuống nước trong buổi diễn tập an toàn.)","Everyone on the sinking vessel managed to get into a [lifeboat] safely. (=Dịch: Mọi người trên con tàu đang chìm đều đã lên được xuồng cứu sinh một cách an toàn.)","Modern cruise ships are equipped with more than enough [lifeboat] capacity for all passengers. (=Dịch: Các tàu du lịch hiện đại được trang bị sức chứa xuồng cứu sinh nhiều hơn mức cần thiết cho toàn bộ hành khách.)"],"ukAudio":"/ai_services/tts3/?q=lifeboat&lang=en-GB&ipa=%2F%CB%88la%C9%AAf.bo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=lifeboat&lang=en-US&ipa=%2F%CB%88la%C9%AAf.bo%CA%8At%2F"},{"id":"lv_0_175","topic":"Daily Life and Social Activities","word":"litre","pos":"(n)","ipa":"/ˈli.t̬ɚ/","defVi":"lít (đơn vị đo thể tích)","defEn":"a metric unit of volume equal to 1,000 cubic centimeters or about 1.76 pints","examples":["Adults are generally advised to drink around two [litre] measures of water every day. (=Dịch: Người lớn thường được khuyên nên uống khoảng hai lít nước mỗi ngày.)","She bought a one [litre] bottle of olive oil from the supermarket. (=Dịch: Cô ấy đã mua một chai dầu ô liu một lít từ siêu thị.)","The car's fuel tank can hold up to fifty [litre] units of gasoline. (=Dịch: Bình xăng của chiếc ô tô có thể chứa tới năm mươi lít xăng.)"],"ukAudio":"/ai_services/tts3/?q=litre&lang=en-GB&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litre&lang=en-US&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F"},{"id":"lv_0_176","topic":"Daily Life and Social Activities","word":"litter","pos":"(v)","ipa":"/ˈlɪt̬.ɚ/","defVi":"xả rác bừa bãi","defEn":"to leave pieces of trash lying around in a public place","examples":["Signs in the national park warn visitors not to [litter] on the trails. (=Dịch: Các biển báo trong công viên quốc gia cảnh báo du khách không được xả rác trên các con đường mòn.)","People who [litter] in public areas may face heavy monetary fines. (=Dịch: Những người xả rác ở các khu vực công cộng có thể phải đối mặt với mức phạt tiền nặng.)","Students were reminded not to [litter] the school playground with snack wrappers. (=Dịch: Học sinh được nhắc nhở không vứt rác vỏ đồ ăn vặt bừa bãi ra sân trường.)"],"ukAudio":"/ai_services/tts3/?q=litter&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litter&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F"},{"id":"lv_0_177","topic":"Daily Life and Social Activities","word":"locker","pos":"(n)","ipa":"/ˈlɑ.kɚ/","defVi":"tủ có khóa, tủ để đồ cá nhân","defEn":"a small lockable cupboard or compartment used for storing personal belongings","examples":["Students keep their heavy textbooks in a personal [locker] at school. (=Dịch: Học sinh cất những cuốn sách giáo khoa nặng trong tủ đồ cá nhân ở trường.)","Please put your valuables inside the gym [locker] before entering the pool. (=Dịch: Vui lòng cất đồ có giá trị vào tủ khóa của phòng tập trước khi vào hồ bơi.)","He forgot the combination code to open his metal [locker]. (=Dịch: Anh ấy đã quên mã số kết hợp để mở tủ khóa kim loại của mình.)"],"ukAudio":"/ai_services/tts3/?q=locker&lang=en-GB&ipa=%2F%CB%88l%C9%91.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=locker&lang=en-US&ipa=%2F%CB%88l%C9%91.k%C9%9A%2F"},{"id":"lv_0_178","topic":"Daily Life and Social Activities","word":"lodge","pos":"(v)","ipa":"/lɑdʒ/","defVi":"ở trọ, trọ lại","defEn":"to stay somewhere temporarily, especially by paying for rent or accommodation","examples":["During his internship abroad, he had to [lodge] with a local host family. (=Dịch: Trong thời gian thực tập ở nước ngoài, anh ấy phải ở trọ cùng một gia đình người bản xứ.)","Many university students prefer to [lodge] near campus to save commute time. (=Dịch: Nhiều sinh viên đại học thích trọ gần khuôn viên trường để tiết kiệm thời gian đi lại.)","The traveling researchers will [lodge] at a small guesthouse in the village. (=Dịch: Các nhà nghiên cứu đi công tác sẽ lưu trú tại một nhà khách nhỏ trong làng.)"],"ukAudio":"/ai_services/tts3/?q=lodge&lang=en-GB&ipa=%2Fl%C9%91d%CA%92%2F","usAudio":"/ai_services/tts3/?q=lodge&lang=en-US&ipa=%2Fl%C9%91d%CA%92%2F"},{"id":"lv_0_179","topic":"Daily Life and Social Activities","word":"loss","pos":"(n)","ipa":"/lɔs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state or fact of no longer having something, or a financial deficit","examples":["The company suffered a major financial [loss] during the economic crisis. (=Dịch: Công ty đã phải chịu tổn thất tài chính lớn trong cuộc khủng hoảng kinh tế.)","Regular exercise can help prevent the [loss] of muscle mass as you age. (=Dịch: Tập thể dục thường xuyên có thể giúp ngăn ngừa sự suy giảm khối lượng cơ bắp khi bạn già đi.)","She felt a deep sense of [loss] when her childhood pet passed away. (=Dịch: Cô cảm thấy một sự mất mát sâu sắc khi con thú cưng gắn bó từ thời thơ ấu qua đời.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94s%2F"},{"id":"lv_0_180","topic":"Daily Life and Social Activities","word":"lunchtime","pos":"(n)","ipa":"/ˈlʌntʃ.taɪm/","defVi":"giờ ăn trưa, buổi trưa","defEn":"the time in the middle of the day when people usually eat lunch","examples":["The office cafeteria is always crowded around [lunchtime]. (=Dịch: Căng tin văn phòng luôn đông đúc vào khoảng giờ ăn trưa.)","I usually take a brisk twenty-minute walk during my [lunchtime] break. (=Dịch: Tôi thường đi bộ nhanh hai mươi phút trong giờ nghỉ trưa.)","Let us discuss the new project over [lunchtime] today. (=Dịch: Chúng ta hãy cùng thảo luận về dự án mới trong bữa trưa hôm nay.)"],"ukAudio":"/ai_services/tts3/?q=lunchtime&lang=en-GB&ipa=%2F%CB%88l%CA%8Cnt%CA%83.ta%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=lunchtime&lang=en-US&ipa=%2F%CB%88l%CA%8Cnt%CA%83.ta%C9%AAm%2F"},{"id":"lv_0_181","topic":"Daily Life and Social Activities","word":"magic","pos":"(adj)","ipa":"/ˈmædʒ.ɪk/","defVi":"kỳ diệu, ma thuật, huyền bí","defEn":"having special mysterious powers, or producing delightful and wonderful effects","examples":["The children listened eagerly to the fairy tale about a [magic] carpet. (=Dịch: Lũ trẻ háo hức lắng nghe câu chuyện cổ tích về một tấm thảm thần kỳ.)","Watching the sunset over the quiet ocean was a truly [magic] experience. (=Dịch: Ngắm hoàng hôn trên đại dương tĩnh lặng là một trải nghiệm thực sự kỳ diệu.)","There is no [magic] solution to learning a foreign language overnight. (=Dịch: Không có giải pháp thần kỳ nào để học một ngoại ngữ chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_0_182","topic":"Daily Life and Social Activities","word":"maker","pos":"(n)","ipa":"/ˈmeɪ.kɚ/","defVi":"người sản xuất, nhà chế tạo","defEn":"a person, company, or thing that produces or creates something","examples":["The smartphone [maker] announced its latest model at the tech conference. (=Dịch: Nhà sản xuất điện thoại thông minh đã công bố mẫu mới nhất của mình tại hội nghị công nghệ.)","He is a skilled violin [maker] known for exceptional craftsmanship. (=Dịch: Ông là một thợ làm đàn vĩ cầm lành nghề, nổi tiếng với tay nghề thủ công xuất sắc.)","The car [maker] recalled thousands of vehicles due to a software defect. (=Dịch: Hãng sản xuất ô tô đã triệu hồi hàng nghìn phương tiện do lỗi phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=maker&lang=en-GB&ipa=%2F%CB%88me%C9%AA.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=maker&lang=en-US&ipa=%2F%CB%88me%C9%AA.k%C9%9A%2F"},{"id":"lv_0_183","topic":"Daily Life and Social Activities","word":"manual","pos":"(adj)","ipa":"/ˈmæn.ju.əl/","defVi":"thủ công, bằng tay","defEn":"done with the hands rather than by a machine","examples":["Many farmers in the region still rely on [manual] labor to harvest crops. (=Dịch: Nhiều nông dân trong khu vực vẫn dựa vào lao động chân tay để thu hoạch mùa màng.)","The car has a [manual] transmission instead of an automatic one. (=Dịch: Chiếc xe này có hộp số sàn thay vì hộp số tự động.)","Sorting these documents requires careful [manual] checking. (=Dịch: Việc phân loại các tài liệu này đòi hỏi phải kiểm tra thủ công cẩn thận.)"],"ukAudio":"/ai_services/tts3/?q=manual&lang=en-GB&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=manual&lang=en-US&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F"},{"id":"lv_0_184","topic":"Daily Life and Social Activities","word":"marathon","pos":"(n)","ipa":"/ˈmær.ə.θɑːn/","defVi":"cuộc chạy ma-ra-tông, cuộc đua việt dã","defEn":"a long-distance running race of 42.195 kilometers (26.2 miles)","examples":["She trained diligently for six months to finish her first [marathon]. (=Dịch: Cô ấy đã chăm chỉ luyện tập trong sáu tháng để hoàn thành cuộc chạy marathon đầu tiên của mình.)","Thousands of international runners participate in the annual city [marathon]. (=Dịch: Hàng ngàn chân chạy quốc tế tham gia vào giải marathon thường niên của thành phố.)","Running a full [marathon] requires tremendous mental and physical stamina. (=Dịch: Chạy trọn vẹn một cự ly marathon đòi hỏi sức bền to lớn cả về thể chất lẫn tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=marathon&lang=en-GB&ipa=%2F%CB%88m%C3%A6r.%C9%99.%CE%B8%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=marathon&lang=en-US&ipa=%2F%CB%88m%C3%A6r.%C9%99.%CE%B8%C9%91%CB%90n%2F"},{"id":"lv_0_185","topic":"Daily Life and Social Activities","word":"marvellous","pos":"(adj)","ipa":"/ˈmɑːr.vəl.əs/","defVi":"tuyệt vời, kỳ diệu","defEn":"extremely good, wonderful, or extraordinary","examples":["We had a [marvellous] time exploring the ancient ruins during our vacation. (=Dịch: Chúng tôi đã có một khoảng thời gian tuyệt vời để khám phá những tàn tích cổ xưa trong kỳ nghỉ của mình.)","The violinist gave a [marvellous] performance that captivated the audience. (=Dịch: Nghệ sĩ vĩ cầm đã có một màn trình diễn tuyệt vời làm say đắm khán giả.)","She made a [marvellous] recovery after the major surgery. (=Dịch: Cô ấy đã hồi phục một cách kỳ diệu sau ca đại phẫu.)"],"ukAudio":"/ai_services/tts3/?q=marvellous&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90r.v%C9%99l.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=marvellous&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90r.v%C9%99l.%C9%99s%2F"},{"id":"lv_0_186","topic":"Daily Life and Social Activities","word":"mature","pos":"(adj)","ipa":"/məˈtʃʊr/","defVi":"trưởng trưởng, chín chắn","defEn":"fully developed physically or behaving in a sensible, adult way","examples":["He is very [mature] for his age and handles responsibility well. (=Dịch: Cậu ấy rất chín chắn so với tuổi của mình và đảm đương tốt trách nhiệm.)","The cheese needs to be stored in a cool place until it becomes [mature]. (=Dịch: Phô mai cần được bảo quản ở nơi thoáng mát cho đến khi đạt độ chín muồi.)","After a [mature] consideration, they decided to invest in the project. (=Dịch: Sau khi cân nhắc kỹ lưỡng, họ đã quyết định đầu tư vào dự án.)"],"ukAudio":"/ai_services/tts3/?q=mature&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=mature&lang=en-US&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F"},{"id":"lv_0_187","topic":"Daily Life and Social Activities","word":"mayor","pos":"(n)","ipa":"/ˈmeɪ.ər/","defVi":"thị trưởng","defEn":"the elected head of a city or town government","examples":["The newly elected [mayor] promised to improve public transportation. (=Dịch: Thị trưởng mới đắc cử đã hứa sẽ cải thiện giao thông công cộng.)","Citizens gathered at the town hall to voice their concerns to the [mayor]. (=Dịch: Người dân đã tập hợp tại tòa thị chính để bày tỏ những mối quan ngại của họ với thị trưởng.)","The [mayor] attended the opening ceremony of the new community center. (=Dịch: Thị trưởng đã tham dự lễ khánh thành trung tâm cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=mayor&lang=en-GB&ipa=%2F%CB%88me%C9%AA.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=mayor&lang=en-US&ipa=%2F%CB%88me%C9%AA.%C9%99r%2F"},{"id":"lv_0_188","topic":"Daily Life and Social Activities","word":"medal","pos":"(n)","ipa":"/ˈmed.əl/","defVi":"huy chương","defEn":"a small metal disc given as a reward for a brave action or sports achievement","examples":["The athlete won a gold [medal] in the 100-meter sprint. (=Dịch: Vận động viên đã giành được huy chương vàng ở nội dung chạy nước rút 100 mét.)","He was awarded a [medal] of honor for his bravery during the rescue operation. (=Dịch: Anh ấy đã được trao tặng huy chương danh dự vì sự dũng cảm trong chiến dịch cứu hộ.)","She proudly displayed each [medal] she had earned on the wall. (=Dịch: Cô tự hào trưng bày từng tấm huy chương mình đã đạt được lên tường.)"],"ukAudio":"/ai_services/tts3/?q=medal&lang=en-GB&ipa=%2F%CB%88med.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=medal&lang=en-US&ipa=%2F%CB%88med.%C9%99l%2F"},{"id":"lv_0_189","topic":"Daily Life and Social Activities","word":"medication","pos":"(n)","ipa":"/ˌmed.əˈkeɪ.ʃən/","defVi":"thuốc men, dược phẩm","defEn":"a substance used to treat an illness or medical condition","examples":["The doctor prescribed a new [medication] to lower his blood pressure. (=Dịch: Bác sĩ đã kê một loại thuốc mới để hạ huyết áp cho ông ấy.)","You should always check the side effects before taking any [medication]. (=Dịch: Bạn nên luôn kiểm tra các tác dụng phụ trước khi dùng bất kỳ loại thuốc nào.)","She is currently on daily [medication] for her allergies. (=Dịch: Hiện tại cô ấy đang phải uống thuốc hàng ngày để trị dị ứng.)"],"ukAudio":"/ai_services/tts3/?q=medication&lang=en-GB&ipa=%2F%CB%8Cmed.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=medication&lang=en-US&ipa=%2F%CB%8Cmed.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_190","topic":"Daily Life and Social Activities","word":"metallic","pos":"(adj)","ipa":"/məˈtæl.ɪk/","defVi":"bằng kim loại, có ánh kim","defEn":"made of metal, or having the appearance or sound of metal","examples":["The sports car was painted in a shiny [metallic] blue finish. (=Dịch: Chiếc xe thể thao được sơn lớp màu xanh dương ánh kim bóng bẩy.)","There was a loud [metallic] sound when the gate slammed shut. (=Dịch: Có một tiếng kim loại lớn vang lên khi cánh cổng đóng sầm lại.)","The robot had a cold, [metallic] frame designed for heavy lifting. (=Dịch: Con robot có bộ khung kim loại lạnh lẽo được thiết kế để nâng vật nặng.)"],"ukAudio":"/ai_services/tts3/?q=metallic&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%C3%A6l.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=metallic&lang=en-US&ipa=%2Fm%C9%99%CB%88t%C3%A6l.%C9%AAk%2F"},{"id":"lv_0_191","topic":"Daily Life and Social Activities","word":"microphone","pos":"(n)","ipa":"/ˈmaɪ.krə.foʊn/","defVi":"micrô","defEn":"an electronic device used to record or amplify sound","examples":["Please speak directly into the [microphone] so everyone can hear you clearly. (=Dịch: Xin vui lòng nói trực tiếp vào micrô để mọi người có thể nghe rõ bạn.)","The singer adjusted the [microphone] stand before starting her song. (=Dịch: Nữ ca sĩ đã điều chỉnh chân đế micrô trước khi bắt đầu bài hát của mình.)","A wireless [microphone] gives the presenter more freedom to move around. (=Dịch: Micrô không dây giúp người thuyết trình thoải mái di chuyển hơn.)"],"ukAudio":"/ai_services/tts3/?q=microphone&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kr%C9%99.fo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=microphone&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kr%C9%99.fo%CA%8An%2F"},{"id":"lv_0_192","topic":"Daily Life and Social Activities","word":"mid","pos":"(adj)","ipa":"/mɪd/","defVi":"ở giữa, trung kỳ","defEn":"located in the middle or middle part of something","examples":["The team experienced a sudden slump in [mid] season. (=Dịch: Đội bóng đã trải qua một đợt sa sút phong độ bất ngờ vào giữa mùa giải.)","She was born in the [mid] 1990s and grew up with modern technology. (=Dịch: Cô sinh vào giữa những năm 1990 và lớn lên cùng với công nghệ hiện đại.)","We planned a trip for [mid] July when the weather is warmest. (=Dịch: Chúng tôi đã lên kế hoạch cho một chuyến đi vào giữa tháng Bảy khi thời tiết ấm áp nhất.)"],"ukAudio":"/ai_services/tts3/?q=mid&lang=en-GB&ipa=%2Fm%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=mid&lang=en-US&ipa=%2Fm%C9%AAd%2F"},{"id":"lv_0_193","topic":"Daily Life and Social Activities","word":"midday","pos":"(n)","ipa":"/ˌmɪdˈdeɪ/","defVi":"buổi trưa, giữa trưa","defEn":"the middle of the day; twelve o'clock or noon","examples":["The sun is at its highest point in the sky at [midday]. (=Dịch: Mặt trời ở vị trí cao nhất trên bầu trời vào lúc giữa trưa.)","Workers usually take a short break around [midday] for lunch. (=Dịch: Các công nhân thường nghỉ giải lao một chút vào khoảng giữa trưa để ăn trưa.)","It is best to avoid outdoor exercise during the intense [midday] heat. (=Dịch: Tốt nhất là nên tránh tập thể dục ngoài trời dưới cái nóng gay gắt lúc giữa trưa.)"],"ukAudio":"/ai_services/tts3/?q=midday&lang=en-GB&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=midday&lang=en-US&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F"},{"id":"lv_0_194","topic":"Daily Life and Social Activities","word":"minibus","pos":"(n)","ipa":"/ˈmɪn.i.bʌs/","defVi":"xe buýt nhỏ","defEn":"a small bus that usually carries about 8 to 30 people","examples":["We rented a [minibus] to take the whole family to the beach. (=Dịch: Chúng tôi đã thuê một chiếc xe buýt nhỏ để đưa cả gia đình đi biển.)","The hotel provides a free [minibus] service to the airport. (=Dịch: Khách sạn cung cấp dịch vụ xe buýt nhỏ miễn phí đến sân bay.)","The local sports team traveled to the match in a [minibus]. (=Dịch: Đội thể thao địa phương đã di chuyển đến trận đấu bằng xe buýt nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=minibus&lang=en-GB&ipa=%2F%CB%88m%C9%AAn.i.b%CA%8Cs%2F","usAudio":"/ai_services/tts3/?q=minibus&lang=en-US&ipa=%2F%CB%88m%C9%AAn.i.b%CA%8Cs%2F"},{"id":"lv_0_195","topic":"Daily Life and Social Activities","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai mỏ, sự khai thác khoáng sản","defEn":"the process or industry of obtaining coal or other minerals from a mine","examples":["The local economy relies heavily on coal [mining]. (=Dịch: Nền kinh tế địa phương phụ thuộc rất nhiều vào ngành khai thác than.)","Environmental groups are concerned about the effects of gold [mining]. (=Dịch: Các nhóm môi trường đang lo ngại về những tác động của việc khai thác vàng.)","New safety regulations were introduced to reduce [mining] accidents. (=Dịch: Các quy định an toàn mới đã được ban hành nhằm giảm thiểu các vụ tai nạn khai thác mỏ.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_0_196","topic":"Daily Life and Social Activities","word":"mode","pos":"(n)","ipa":"/moʊd/","defVi":"chế độ, phương thức","defEn":"a particular way or manner in which something is done or happens","examples":["Cycling is an eco-friendly [mode] of transport in the city. (=Dịch: Đi xe đạp là một phương thức di chuyển thân thiện với môi trường trong thành phố.)","You should switch your mobile phone to silent [mode] during the lecture. (=Dịch: Bạn nên chuyển điện thoại di động sang chế độ im lặng trong suốt bài giảng.)","The company changed its [mode] of operation after the pandemic. (=Dịch: Công ty đã thay đổi phương thức hoạt động sau đại dịch.)"],"ukAudio":"/ai_services/tts3/?q=mode&lang=en-GB&ipa=%2Fmo%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=mode&lang=en-US&ipa=%2Fmo%CA%8Ad%2F"},{"id":"lv_0_197","topic":"Daily Life and Social Activities","word":"monthly","pos":"(adj)","ipa":"/ˈmʌnθ.li/","defVi":"hàng tháng","defEn":"happening, produced, or paid once every month","examples":["The team holds a [monthly] meeting to discuss their progress. (=Dịch: Nhóm tổ chức một cuộc họp hàng tháng để thảo luận về tiến độ của họ.)","She pays a [monthly] subscription fee for the music app. (=Dịch: Cô ấy trả phí thuê bao hàng tháng cho ứng dụng nghe nhạc.)","The magazine is published as a [monthly] issue. (=Dịch: Tạp chí này được xuất bản dưới dạng ấn bản hàng tháng.)"],"ukAudio":"/ai_services/tts3/?q=monthly&lang=en-GB&ipa=%2F%CB%88m%CA%8Cn%CE%B8.li%2F","usAudio":"/ai_services/tts3/?q=monthly&lang=en-US&ipa=%2F%CB%88m%CA%8Cn%CE%B8.li%2F"},{"id":"lv_0_198","topic":"Daily Life and Social Activities","word":"monument","pos":"(n)","ipa":"/ˈmɑːn.jə.mənt/","defVi":"đài tưởng niệm, tượng đài, di tích","defEn":"a structure erected to commemorate a person or important event","examples":["A large stone [monument] was built in honor of the soldiers. (=Dịch: Một đài tưởng niệm lớn bằng đá đã được xây dựng để vinh danh những người lính.)","The ancient temple is protected as a national [monument]. (=Dịch: Ngôi đền cổ này được bảo tồn như một di tích quốc gia.)","Tourists gathered around the historic [monument] to take photos. (=Dịch: Khách du lịch tụ tập quanh di tích lịch sử để chụp ảnh.)"],"ukAudio":"/ai_services/tts3/?q=monument&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90n.j%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=monument&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90n.j%C9%99.m%C9%99nt%2F"},{"id":"lv_0_199","topic":"Daily Life and Social Activities","word":"motivating","pos":"(adj)","ipa":"/ˈmoʊ.t̬ə.veɪ.t̬ɪŋ/","defVi":"có tính khích lệ, tạo động lực","defEn":"making you feel enthusiastic and eager to do something","examples":["Her speech was incredibly [motivating] for all the new students. (=Dịch: Bài phát biểu của cô ấy đã truyền rất nhiều động lực cho tất cả các tân sinh viên.)","A supportive teacher creates a [motivating] learning environment. (=Dịch: Một giáo viên luôn hỗ trợ sẽ tạo ra một môi trường học tập giàu động lực.)","Setting small goals can be very [motivating] during a difficult project. (=Dịch: Việc đặt ra những mục tiêu nhỏ có thể tạo động lực rất lớn trong suốt một dự án khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=motivating&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.t%CC%AC%C9%99.ve%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=motivating&lang=en-US&ipa=%2F%CB%88mo%CA%8A.t%CC%AC%C9%99.ve%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_200","topic":"Daily Life and Social Activities","word":"mount","pos":"(n)","ipa":"/maʊnt/","defVi":"ngọn núi, đỉnh núi","defEn":"a mountain or hill, often used as part of a proper name","examples":["[Mount] Everest is the highest mountain above sea level in the world. (=Dịch: Đỉnh Everest là ngọn núi cao nhất thế giới so với mực nước biển.)","They decided to climb [Mount] Fuji during their trip to Japan. (=Dịch: Họ quyết định leo Núi Phú Sĩ trong chuyến đi đến Nhật Bản.)","The summit of the [mount] was covered with thick snow. (=Dịch: Đỉnh núi bị bao phủ bởi tuyết dày.)"],"ukAudio":"/ai_services/tts3/?q=mount&lang=en-GB&ipa=%2Fma%CA%8Ant%2F","usAudio":"/ai_services/tts3/?q=mount&lang=en-US&ipa=%2Fma%CA%8Ant%2F"},{"id":"lv_0_201","topic":"Daily Life and Social Activities","word":"mountainside","pos":"(n)","ipa":"/ˈmaʊn.tən.saɪd/","defVi":"sườn núi","defEn":"the side or slope of a mountain","examples":["Small villages are scattered across the green [mountainside]. (=Dịch: Những ngôi làng nhỏ nằm rải rác khắp sườn núi xanh tươi.)","Heavy rain caused a landslide on the steep [mountainside]. (=Dịch: Mưa lớn đã gây ra lở đất trên sườn núi dốc.)","They built a cozy wooden cabin high up on the [mountainside]. (=Dịch: Họ đã xây một căn nhà gỗ ấm cúng ở tít trên sườn núi.)"],"ukAudio":"/ai_services/tts3/?q=mountainside&lang=en-GB&ipa=%2F%CB%88ma%CA%8An.t%C9%99n.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=mountainside&lang=en-US&ipa=%2F%CB%88ma%CA%8An.t%C9%99n.sa%C9%AAd%2F"},{"id":"lv_0_202","topic":"Daily Life and Social Activities","word":"mr.","pos":"(n)","ipa":"/ˈmɪs.tɚ/","defVi":"ông, ngài (danh xưng cho nam giới)","defEn":"a title used before the surname or full name of a man","examples":["[Mr.] Johnson will lead the meeting this afternoon. (=Dịch: Ông Johnson sẽ chủ trì cuộc họp chiều nay.)","Please address your letter to [Mr.] Davis in the marketing department. (=Dịch: Vui lòng ghi người nhận thư là ông Davis ở phòng tiếp thị.)","The receptionist asked [Mr.] Brown to sign his name in the guest book. (=Dịch: Nhân viên lễ tân đã đề nghị ông Brown ký tên vào sổ khách lưu trú.)"],"ukAudio":"/ai_services/tts3/?q=mr.&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mr.&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A%2F"},{"id":"lv_0_203","topic":"Daily Life and Social Activities","word":"ms.","pos":"(n)","ipa":"/mɪz/","defVi":"cô, bà (danh xưng cho nữ giới, không phân biệt đã kết hôn hay chưa)","defEn":"a title used before the surname or full name of a woman, regardless of marital status","examples":["[Ms.] Lee was recently promoted to head of the department. (=Dịch: Cô Lee gần đây đã được thăng chức lên vị trí trưởng phòng.)","Can I leave a message for [Ms.] Taylor while she is away? (=Dịch: Tôi có thể để lại lời nhắn cho cô Taylor trong lúc cô ấy đi vắng được không?)","The award was presented to [Ms.] Green for her outstanding research. (=Dịch: Giải thưởng đã được trao tặng cho cô Green vì công trình nghiên cứu xuất sắc của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=ms.&lang=en-GB&ipa=%2Fm%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=ms.&lang=en-US&ipa=%2Fm%C9%AAz%2F"},{"id":"lv_0_204","topic":"Daily Life and Social Activities","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tə.ri/","defVi":"điều bí ẩn, điều huyền bí","defEn":"something strange or not known that cannot be explained or understood","examples":["The exact cause of the plane crash remains a [mystery]. (=Dịch: Nguyên nhân chính xác của vụ tai nạn máy bay vẫn còn là một bí ẩn.)","He loves reading detective novels and solving a good [mystery]. (=Dịch: Anh ấy thích đọc tiểu thuyết trinh thám và giải mã những bí ẩn thú vị.)","How the ancient monument was constructed is still shrouded in [mystery]. (=Dịch: Cách thức xây dựng tượng đài cổ kính này vẫn còn bị bao phủ trong bức màn bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%99.ri%2F"},{"id":"lv_0_205","topic":"Daily Life and Social Activities","word":"nationality","pos":"(n)","ipa":"/ˌnæʃ.əˈnæl.ə.t̬i/","defVi":"quốc tịch","defEn":"the state of belonging to a particular nation by origin, birth, or naturalization","examples":["Please state your name, date of birth, and [nationality] on the visa form. (=Dịch: Vui lòng ghi rõ họ tên, ngày sinh và quốc tịch của bạn trên mẫu đơn xin thị thực.)","The international school welcomes students of many different [nationalities]. (=Dịch: Trường quốc tế này chào đón học sinh thuộc nhiều quốc tịch khác nhau.)","She holds dual [nationality] because her parents come from two different countries. (=Dịch: Cô ấy mang hai quốc tịch vì bố mẹ cô đến từ hai quốc gia khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=nationality&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=nationality&lang=en-US&ipa=%2F%CB%8Cn%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_0_206","topic":"Daily Life and Social Activities","word":"nineteen","pos":"(n)","ipa":"/ˌnaɪnˈtiːn/","defVi":"số mười chín","defEn":"the number 19","examples":["She will celebrate her [nineteen]th birthday next week. (=Dịch: Cô ấy sẽ tổ chức sinh nhật lần thứ mười chín vào tuần tới.)","There are [nineteen] students enrolled in the advanced English class. (=Dịch: Có mười chín học viên đăng ký vào lớp tiếng Anh nâng cao.)","The bus route number [nineteen] goes directly to the university campus. (=Dịch: Tuyến xe buýt số mười chín đi thẳng đến khuôn viên trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=nineteen&lang=en-GB&ipa=%2F%CB%8Cna%C9%AAn%CB%88ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=nineteen&lang=en-US&ipa=%2F%CB%8Cna%C9%AAn%CB%88ti%CB%90n%2F"},{"id":"lv_0_207","topic":"Daily Life and Social Activities","word":"ninety","pos":"(n)","ipa":"/ˈnaɪn.ti/","defVi":"số chín mươi","defEn":"the number 90","examples":["My grandfather lived an active life until he was almost [ninety]. (=Dịch: Ông tôi đã sống một cuộc sống năng động cho đến khi gần chín mươi tuổi.)","Over [ninety] percent of the surveyed applicants passed the test. (=Dịch: Hơn chín mươi phần trăm các ứng viên được khảo sát đã vượt qua bài kiểm tra.)","The speed limit on this highway is [ninety] kilometers per hour. (=Dịch: Tốc độ giới hạn trên đường cao tốc này là chín mươi kilomet một giờ.)"],"ukAudio":"/ai_services/tts3/?q=ninety&lang=en-GB&ipa=%2F%CB%88na%C9%AAn.ti%2F","usAudio":"/ai_services/tts3/?q=ninety&lang=en-US&ipa=%2F%CB%88na%C9%AAn.ti%2F"},{"id":"lv_0_208","topic":"Daily Life and Social Activities","word":"occupation","pos":"(n)","ipa":"/ˌɑː.kjəˈpeɪ.ʃən/","defVi":"nghề nghiệp, công việc","defEn":"a person's regular work, profession, or job","examples":["Please write down your current [occupation] and employer on the application form. (=Dịch: Vui lòng ghi nghề nghiệp hiện tại và tên người sử dụng lao động vào mẫu đơn đăng ký.)","Teaching is a demanding [occupation] that requires patience and dedication. (=Dịch: Dạy học là một nghề nghiệp đòi hỏi nhiều nỗ lực, cần có sự kiên nhẫn và lòng tận tụy.)","He decided to change his [occupation] after working in finance for a decade. (=Dịch: Anh ấy quyết định thay đổi nghề nghiệp sau khi làm việc trong lĩnh vực tài chính suốt một thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=occupation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.kj%C9%99%CB%88pe%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=occupation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.kj%C9%99%CB%88pe%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_209","topic":"Daily Life and Social Activities","word":"opt","pos":"(v)","ipa":"/ɑːpt/","defVi":"lựa chọn, quyết định chọn","defEn":"to make a choice or decision from a range of possibilities","examples":["Many young professionals [opt] to rent rather than buy an apartment. (=Dịch: Nhiều chuyên gia trẻ tuổi chọn thuê nhà hơn là mua một căn hộ.)","Instead of flying, they decided to [opt] for a scenic train journey. (=Dịch: Thay vì đi máy bay, họ quyết định chọn một chuyến đi bằng tàu hỏa ngắm cảnh.)","Students can [opt] out of the sports program if they have medical reasons. (=Dịch: Học sinh có thể chọn không tham gia chương trình thể thao nếu có lý do y tế.)"],"ukAudio":"/ai_services/tts3/?q=opt&lang=en-GB&ipa=%2F%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=opt&lang=en-US&ipa=%2F%C9%91%CB%90pt%2F"},{"id":"lv_0_210","topic":"Daily Life and Social Activities","word":"optional","pos":"(adj)","ipa":"/ˈɑːp.ʃən.əl/","defVi":"tùy chọn, không bắt buộc","defEn":"available to be chosen but not mandatory or compulsory","examples":["Attendance at the introductory workshop is purely [optional]. (=Dịch: Việc tham dự hội thảo giới thiệu là hoàn toàn tùy chọn.)","The software includes several [optional] features that you can install later. (=Dịch: Phần mềm này bao gồm một số tính năng tùy chọn mà bạn có thể cài đặt sau.)","Foreign language study was [optional] for science students at the university. (=Dịch: Việc học ngoại ngữ là tự chọn đối với các sinh viên ngành khoa học tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=optional&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90p.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=optional&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90p.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_0_211","topic":"Daily Life and Social Activities","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians who play various instruments together, usually led by a conductor","examples":["She plays the violin in the city's youth [orchestra]. (=Dịch: Cô ấy chơi violin trong dàn nhạc thanh thiếu niên của thành phố.)","The [orchestra] gave a magnificent performance of Beethoven's Fifth Symphony. (=Dịch: Dàn nhạc đã có một buổi biểu diễn tuyệt vời bản Giao hưởng số 5 của Beethoven.)","Conducting a world-class [orchestra] requires immense skill and musicality. (=Dịch: Việc chỉ huy một dàn nhạc đẳng cấp thế giới đòi hỏi kỹ năng và cảm thụ âm nhạc vô cùng to lớn.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_0_212","topic":"Daily Life and Social Activities","word":"organiser","pos":"(n)","ipa":"/ˈɔːr.ɡə.naɪ.zɚ/","defVi":"người tổ chức, ban tổ chức","defEn":"a person or organization responsible for planning and coordinating an event or activity","examples":["The event [organiser] announced changes to the schedule due to heavy rain. (=Dịch: Ban tổ chức sự kiện đã thông báo những thay đổi về lịch trình do mưa lớn.)","She is a skilled conference [organiser] who manages large international gatherings. (=Dịch: Cô ấy là một nhà tổ chức hội nghị lành nghề, chuyên điều hành các cuộc họp quốc tế lớn.)","Please contact the festival [organiser] if you wish to set up a food stall. (=Dịch: Vui lòng liên hệ với nhà tổ chức lễ hội nếu bạn muốn mở một quầy bán đồ ăn.)"],"ukAudio":"/ai_services/tts3/?q=organiser&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99.na%C9%AA.z%C9%9A%2F","usAudio":"/ai_services/tts3/?q=organiser&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99.na%C9%AA.z%C9%9A%2F"},{"id":"lv_0_213","topic":"Daily Life and Social Activities","word":"origin","pos":"(n)","ipa":"/ˈɔːr.ə.dʒɪn/","defVi":"nguồn gốc, căn nguyên","defEn":"the point, place, or source where something begins or comes from","examples":["Scientists are still investigating the evolutionary [origin] of the species. (=Dịch: Các nhà khoa học vẫn đang nghiên cứu nguồn gốc tiến hóa của loài này.)","The customs official asked about the country of [origin] of the imported goods. (=Dịch: Viên chức hải quan đã hỏi về quốc gia xuất xứ của hàng hóa nhập khẩu.)","The phrase has its [origin] in an ancient Greek fable. (=Dịch: Cụm từ này có nguồn gốc từ một câu chuyện ngụ ngôn Hy Lạp cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=origin&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=origin&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F"},{"id":"lv_0_214","topic":"Daily Life and Social Activities","word":"outdoor","pos":"(adj)","ipa":"/ˈaʊt.dɔr/","defVi":"ngoài trời","defEn":"happening, located, or used outside rather than in a building","examples":["They enjoy [outdoor] activities like hiking and camping during the summer. (=Dịch: Họ thích các hoạt động ngoài trời như đi bộ đường dài và cắm trại vào mùa hè.)","The hotel features a large [outdoor] swimming pool for guests. (=Dịch: Khách sạn có một hồ bơi lớn ngoài trời dành cho du khách.)","Wearing sunscreen is essential when doing [outdoor] sports. (=Dịch: Bôi kem chống nắng là điều cần thiết khi chơi các môn thể thao ngoài trời.)"],"ukAudio":"/ai_services/tts3/?q=outdoor&lang=en-GB&ipa=%2F%CB%88a%CA%8At.d%C9%94r%2F","usAudio":"/ai_services/tts3/?q=outdoor&lang=en-US&ipa=%2F%CB%88a%CA%8At.d%C9%94r%2F"},{"id":"lv_0_215","topic":"Daily Life and Social Activities","word":"package","pos":"(n)","ipa":"/ˈpæk.ɪdʒ/","defVi":"gói dịch vụ, gói ưu đãi","defEn":"a set of related services or products offered together as a single unit","examples":["The travel agency offers an attractive holiday [package] with flights included. (=Dịch: Công ty lữ hành cung cấp một gói kỳ nghỉ hấp dẫn đã bao gồm vé máy bay.)","We selected an internet [package] that provides unlimited high-speed data. (=Dịch: Chúng tôi đã chọn một gói cước internet cung cấp dữ liệu tốc độ cao không giới hạn.)","The hotel created a special wedding [package] for couples on a budget. (=Dịch: Khách sạn đã thiết kế một gói tiệc cưới đặc biệt dành cho các cặp đôi có ngân sách hạn hẹp.)"],"ukAudio":"/ai_services/tts3/?q=package&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=package&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F"},{"id":"lv_0_216","topic":"Daily Life and Social Activities","word":"pathway","pos":"(n)","ipa":"/ˈpæθ.weɪ/","defVi":"lối đi, đường mòn","defEn":"a track or path that people can walk along","examples":["A stone [pathway] leads from the garden gate to the front door. (=Dịch: Một lối đi bằng đá dẫn từ cổng vườn vào đến cửa trước.)","Education is often seen as a [pathway] to success and financial stability. (=Dịch: Giáo dục thường được xem là con đường dẫn đến thành công và sự ổn định tài chính.)","We walked along the coastal [pathway] to admire the sunset. (=Dịch: Chúng tôi đã đi dạo dọc theo con đường ven biển để ngắm hoàng hôn.)"],"ukAudio":"/ai_services/tts3/?q=pathway&lang=en-GB&ipa=%2F%CB%88p%C3%A6%CE%B8.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=pathway&lang=en-US&ipa=%2F%CB%88p%C3%A6%CE%B8.we%C9%AA%2F"},{"id":"lv_0_217","topic":"Daily Life and Social Activities","word":"payment","pos":"(n)","ipa":"/ˈpeɪ.mənt/","defVi":"khoản thanh toán, sự chi trả","defEn":"an amount of money paid, or the act of paying","examples":["You can make your [payment] by credit card or cash. (=Dịch: Bạn có thể thanh toán bằng thẻ tín dụng hoặc tiền mặt.)","The company demands immediate [payment] for the delivered goods. (=Dịch: Công ty yêu cầu thanh toán ngay lập tức cho số hàng đã giao.)","She set up automatic monthly [payment] for her electricity bill. (=Dịch: Cô ấy đã thiết lập thanh toán tự động hàng tháng cho hóa đơn tiền điện.)"],"ukAudio":"/ai_services/tts3/?q=payment&lang=en-GB&ipa=%2F%CB%88pe%C9%AA.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=payment&lang=en-US&ipa=%2F%CB%88pe%C9%AA.m%C9%99nt%2F"},{"id":"lv_0_218","topic":"Daily Life and Social Activities","word":"peak","pos":"(n)","ipa":"/pik/","defVi":"đỉnh núi, thời điểm đỉnh cao","defEn":"the pointed top of a mountain, or the highest point of something","examples":["The climbers finally reached the snow-covered [peak] at noon. (=Dịch: Những người leo núi cuối cùng đã lên tới đỉnh núi phủ tuyết trắng vào buổi trưa.)","Traffic congestion usually reaches its [peak] around five in the afternoon. (=Dịch: Tình trạng tắc nghẽn giao thông thường đạt đỉnh điểm vào khoảng năm giờ chiều.)","The artist created his best paintings during the [peak] of his career. (=Dịch: Họa sĩ đã sáng tác những bức tranh đẹp nhất của mình trong thời kỳ đỉnh cao của sự nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=peak&lang=en-GB&ipa=%2Fpik%2F","usAudio":"/ai_services/tts3/?q=peak&lang=en-US&ipa=%2Fpik%2F"},{"id":"lv_0_219","topic":"Daily Life and Social Activities","word":"permit","pos":"(v)","ipa":"/pɚˈmɪt/","defVi":"cho phép","defEn":"to allow something to happen or allow someone to do something","examples":["The museum does not [permit] visitors to take photos inside. (=Dịch: Bảo tàng không cho phép khách tham quan chụp ảnh bên trong.)","We will have a picnic tomorrow if the weather will [permit]. (=Dịch: Chúng tôi sẽ đi dã ngoại vào ngày mai nếu thời tiết cho phép.)","Her busy schedule did not [permit] her to attend the workshop. (=Dịch: Lịch trình bận rộn không cho phép cô ấy tham dự buổi hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=permit&lang=en-GB&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=permit&lang=en-US&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F"},{"id":"lv_0_220","topic":"Daily Life and Social Activities","word":"photography","pos":"(n)","ipa":"/fəˈtɑː.ɡrə.fi/","defVi":"nhiếp ảnh, nghề chụp ảnh","defEn":"the activity or job of taking photographs or filming","examples":["She took a course in digital [photography] to improve her camera skills. (=Dịch: Cô ấy đã tham gia một khóa học nhiếp ảnh kỹ thuật số để nâng cao kỹ năng chụp ảnh.)","Wildlife [photography] requires a great deal of patience and specialized equipment. (=Dịch: Nhiếp ảnh động vật hoang dã đòi hỏi rất nhiều sự kiên nhẫn và thiết bị chuyên dụng.)","His passion for landscape [photography] inspired him to travel around the world. (=Dịch: Niềm đam mê nhiếp ảnh phong cảnh đã thôi thúc anh ấy đi du lịch vòng quanh thế giới.)"],"ukAudio":"/ai_services/tts3/?q=photography&lang=en-GB&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=photography&lang=en-US&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_0_221","topic":"Daily Life and Social Activities","word":"picnic","pos":"(n)","ipa":"/ˈpɪk.nɪk/","defVi":"chuyến dã ngoại, bữa ăn ngoài trời","defEn":"an occasion when a packed meal is eaten outdoors","examples":["We decided to have a [picnic] by the lake on Sunday afternoon. (=Dịch: Chúng tôi quyết định tổ chức một buổi dã ngoại bên hồ vào chiều Chủ nhật.)","She packed sandwiches, fruit, and lemonade into the [picnic] basket. (=Dịch: Cô ấy xếp bánh mì kẹp, trái cây và nước chanh vào giỏ dã ngoại.)","Families often gather in the central park for an enjoyable weekend [picnic]. (=Dịch: Các gia đình thường tụ họp tại công viên trung tâm để có một buổi dã ngoại cuối tuần thú vị.)"],"ukAudio":"/ai_services/tts3/?q=picnic&lang=en-GB&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=picnic&lang=en-US&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F"},{"id":"lv_0_222","topic":"Daily Life and Social Activities","word":"pile","pos":"(n)","ipa":"/paɪl/","defVi":"chồng, đống","defEn":"a mass of things lying one on top of another","examples":["There is a tall [pile] of dirty dishes in the kitchen sink. (=Dịch: Có một chồng bát đĩa bẩn chất cao trong bồn rửa chén.)","He sorted through a [pile] of old documents looking for his passport. (=Dịch: Anh ấy đã lục tìm trong một đống tài liệu cũ để tìm hộ chiếu của mình.)","The gardener raked the dry leaves into a neat [pile]. (=Dịch: Người làm vườn đã cào lá khô lại thành một đống gọn gàng.)"],"ukAudio":"/ai_services/tts3/?q=pile&lang=en-GB&ipa=%2Fpa%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=pile&lang=en-US&ipa=%2Fpa%C9%AAl%2F"},{"id":"lv_0_223","topic":"Daily Life and Social Activities","word":"pleasure","pos":"(n)","ipa":"/ˈpleʒ.ɚ/","defVi":"niềm vui thích, sự hân hạnh","defEn":"a feeling of happy satisfaction and enjoyment","examples":["Reading historical novels gives her a great deal of [pleasure]. (=Dịch: Đọc tiểu thuyết lịch sử mang lại cho cô ấy rất nhiều niềm vui.)","It was a true [pleasure] to meet your family last night. (=Dịch: Thật là một niềm vui lớn khi được gặp gia đình bạn vào tối qua.)","He travels abroad for both business and [pleasure]. (=Dịch: Anh ấy đi nước ngoài cho cả mục đích công việc lẫn giải trí.)"],"ukAudio":"/ai_services/tts3/?q=pleasure&lang=en-GB&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=pleasure&lang=en-US&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F"},{"id":"lv_0_224","topic":"Daily Life and Social Activities","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, thận trọng","defEn":"wise, sensible, and showing good judgment in a particular situation","examples":["It was not considered [politic] to bring up the sensitive topic during the meeting. (=Dịch: Việc đề cập đến chủ đề nhạy cảm trong cuộc họp được cho là không khôn ngoan.)","He thought it [politic] to remain silent while his manager was speaking. (=Dịch: Anh ấy nghĩ rằng giữ im lặng trong khi người quản lý đang nói là điều khôn khéo.)","Adopting a calm tone was a [politic] move to prevent further argument. (=Dịch: Dùng giọng điệu bình tĩnh là một bước đi khôn khéo để ngăn chặn những tranh cãi tiếp theo.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_0_225","topic":"Daily Life and Social Activities","word":"portion","pos":"(n)","ipa":"/ˈpɔːr.ʃən/","defVi":"phần, khẩu phần","defEn":"a part of something larger, especially an amount of food served for one person","examples":["A large [portion] of the budget was allocated to scientific research. (=Dịch: Một phần lớn ngân sách đã được phân bổ cho nghiên cứu khoa học.)","The restaurant serves very generous [portions] of pasta. (=Dịch: Nhà hàng phục vụ các phần mì Ý rất đầy đặn.)","Only a small [portion] of the students passed the advanced test. (=Dịch: Chỉ một phần nhỏ học sinh vượt qua bài kiểm tra nâng cao.)"],"ukAudio":"/ai_services/tts3/?q=portion&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=portion&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F"},{"id":"lv_0_226","topic":"Daily Life and Social Activities","word":"postcode","pos":"(n)","ipa":"/ˈpoʊst.koʊd/","defVi":"mã bưu điện, mã bưu chính","defEn":"a group of letters and numbers added to a postal address to help sort mail","examples":["Please remember to write your [postcode] clearly on the envelope. (=Dịch: Xin hãy nhớ ghi mã bưu chính của bạn thật rõ ràng trên phong bì.)","I could not complete the checkout form without entering a valid [postcode]. (=Dịch: Tôi không thể hoàn tất biểu mẫu thanh toán nếu không nhập mã bưu chính hợp lệ.)","The courier used the [postcode] to locate our building quickly. (=Dịch: Người giao hàng đã sử dụng mã bưu chính để xác định vị trí tòa nhà của chúng tôi một cách nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=postcode&lang=en-GB&ipa=%2F%CB%88po%CA%8Ast.ko%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=postcode&lang=en-US&ipa=%2F%CB%88po%CA%8Ast.ko%CA%8Ad%2F"},{"id":"lv_0_227","topic":"Daily Life and Social Activities","word":"powder","pos":"(n)","ipa":"/ˈpaʊ.dər/","defVi":"bột, phấn","defEn":"a dry substance made of very fine, small particles","examples":["Mix the cocoa [powder] with warm milk until smooth. (=Dịch: Trộn bột ca cao với sữa ấm cho đến khi mịn.)","She applied a light layer of [powder] to her face. (=Dịch: Cô ấy thoa một lớp phấn nhẹ lên mặt.)","The medicine is available in both tablet and [powder] form. (=Dịch: Thuốc này có sẵn ở cả dạng viên nén và dạng bột.)"],"ukAudio":"/ai_services/tts3/?q=powder&lang=en-GB&ipa=%2F%CB%88pa%CA%8A.d%C9%99r%2F","usAudio":"/ai_services/tts3/?q=powder&lang=en-US&ipa=%2F%CB%88pa%CA%8A.d%C9%99r%2F"},{"id":"lv_0_228","topic":"Daily Life and Social Activities","word":"preferable","pos":"(adj)","ipa":"/ˈpref.ər.ə.bəl/","defVi":"thích hợp hơn, đáng chuộng hơn","defEn":"more suitable, desirable, or acceptable","examples":["Taking the train is [preferable] to driving in heavy traffic. (=Dịch: Đi tàu hỏa thích hợp hơn so với việc lái xe khi giao thông đông đúc.)","A quiet study environment is [preferable] for deep concentration. (=Dịch: Một môi trường học tập yên tĩnh sẽ tốt hơn cho việc tập trung sâu.)","Having some work experience is [preferable] but not essential for this job. (=Dịch: Có một chút kinh nghiệm làm việc là điều đáng mong muốn nhưng không bắt buộc đối với công việc này.)"],"ukAudio":"/ai_services/tts3/?q=preferable&lang=en-GB&ipa=%2F%CB%88pref.%C9%99r.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=preferable&lang=en-US&ipa=%2F%CB%88pref.%C9%99r.%C9%99.b%C9%99l%2F"},{"id":"lv_0_229","topic":"Daily Life and Social Activities","word":"preference","pos":"(n)","ipa":"/ˈpref.ər.əns/","defVi":"sở thích, sự ưa chuộng, sự ưu tiên","defEn":"a greater liking for one alternative over another","examples":["Do you have any dietary [preference], such as vegetarian food? (=Dịch: Bạn có yêu cầu ăn uống đặc biệt nào không, chẳng hạn như đồ ăn chay?)","Parents often have a strong [preference] for smaller class sizes. (=Dịch: Các bậc phụ huynh thường có xu hướng ưa chuộng các lớp học có quy mô nhỏ hơn.)","Candidates with previous teaching experience will be given [preference]. (=Dịch: Các ứng viên có kinh nghiệm giảng dạy trước đó sẽ được ưu tiên.)"],"ukAudio":"/ai_services/tts3/?q=preference&lang=en-GB&ipa=%2F%CB%88pref.%C9%99r.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=preference&lang=en-US&ipa=%2F%CB%88pref.%C9%99r.%C9%99ns%2F"},{"id":"lv_0_230","topic":"Daily Life and Social Activities","word":"preferred","pos":"(adj)","ipa":"/prɪˈfɜːrd/","defVi":"được ưa chuộng hơn, ưu tiên","defEn":"liked better or chosen over others","examples":["Online banking has become the [preferred] method of payment for many people. (=Dịch: Ngân hàng trực tuyến đã trở thành phương thức thanh toán được ưa chuộng của nhiều người.)","Please state your [preferred] date of arrival on the application form. (=Dịch: Vui lòng ghi rõ ngày đến mong muốn của bạn trên mẫu đơn đăng ký.)","Tea is his [preferred] morning beverage instead of coffee. (=Dịch: Trà là thức uống buổi sáng ưa thích của anh ấy thay vì cà phê.)"],"ukAudio":"/ai_services/tts3/?q=preferred&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88f%C9%9C%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=preferred&lang=en-US&ipa=%2Fpr%C9%AA%CB%88f%C9%9C%CB%90rd%2F"},{"id":"lv_0_231","topic":"Daily Life and Social Activities","word":"premier","pos":"(adj)","ipa":"/prɪˈmɪr/","defVi":"hàng đầu, quan trọng nhất","defEn":"best, most important, or first in position","examples":["The university is regarded as the country's [premier] research institution. (=Dịch: Trường đại học này được coi là viện nghiên cứu hàng đầu của đất nước.)","The hotel offers [premier] services to its VIP guests. (=Dịch: Khách sạn cung cấp các dịch vụ cao cấp nhất cho các khách hàng VIP.)","The city is hosting the [premier] cultural event of the year. (=Dịch: Thành phố đang đăng cai tổ chức sự kiện văn hóa hàng đầu trong năm.)"],"ukAudio":"/ai_services/tts3/?q=premier&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88m%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=premier&lang=en-US&ipa=%2Fpr%C9%AA%CB%88m%C9%AAr%2F"},{"id":"lv_0_232","topic":"Daily Life and Social Activities","word":"presume","pos":"(v)","ipa":"/prɪˈzuːm/","defVi":"cho là, coi như là, đoán chừng","defEn":"to believe something to be true based on probability rather than proof","examples":["I [presume] that you have already completed the reading assignment. (=Dịch: Tôi cho rằng bạn đã hoàn thành bài tập đọc rồi.)","In law, a person is [presumed] innocent until proven guilty. (=Dịch: Theo luật, một người được coi là vô tội cho đến khi bị chứng minh là có tội.)","Since he was absent, we [presumed] he was sick. (=Dịch: Vì anh ấy vắng mặt, chúng tôi đoán là anh ấy bị ốm.)"],"ukAudio":"/ai_services/tts3/?q=presume&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88zu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=presume&lang=en-US&ipa=%2Fpr%C9%AA%CB%88zu%CB%90m%2F"},{"id":"lv_0_233","topic":"Daily Life and Social Activities","word":"projector","pos":"(n)","ipa":"/prəˈdʒek.tər/","defVi":"máy chiếu","defEn":"a device that projects rays of light or images onto a screen","examples":["The teacher turned on the [projector] to display the slides. (=Dịch: Giáo viên đã bật máy chiếu để hiển thị các trang trình chiếu.)","We need a high-resolution [projector] for the conference room. (=Dịch: Chúng tôi cần một máy chiếu có độ phân giải cao cho phòng hội nghị.)","The presentation was delayed because the [projector] stopped working. (=Dịch: Buổi thuyết trình bị trì hoãn vì máy chiếu ngừng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=projector&lang=en-GB&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=projector&lang=en-US&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F"},{"id":"lv_0_234","topic":"Daily Life and Social Activities","word":"purchase","pos":"(v)","ipa":"/ˈpɝː.tʃəs/","defVi":"mua sắm, mua vào","defEn":"to buy something","examples":["You can [purchase] museum tickets online to avoid long queues. (=Dịch: Bạn có thể mua vé bảo tàng trực tuyến để tránh phải xếp hàng dài.)","She decided to [purchase] a new laptop for her university courses. (=Dịch: Cô ấy quyết định mua một chiếc máy tính xách tay mới cho các khóa học đại học của mình.)","The school plans to [purchase] new laboratory equipment next term. (=Dịch: Nhà trường dự định mua sắm các thiết bị phòng thí nghiệm mới vào học kỳ tới.)"],"ukAudio":"/ai_services/tts3/?q=purchase&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.t%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=purchase&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.t%CA%83%C9%99s%2F"},{"id":"lv_0_235","topic":"Daily Life and Social Activities","word":"qualified","pos":"(adj)","ipa":"/ˈkwɑː.lə.faɪd/","defVi":"đủ điều kiện, có đủ trình độ chuyên môn","defEn":"having the necessary skills, knowledge, or experience to do a particular job or activity","examples":["She is fully [qualified] to teach English to international students. (=Dịch: Cô ấy có đầy đủ trình độ chuyên môn để dạy tiếng Anh cho sinh viên quốc tế.)","Only [qualified] candidates will be invited for an interview. (=Dịch: Chỉ những ứng viên đủ điều kiện mới được mời tham gia phỏng vấn.)","He is well [qualified] for the position of project manager. (=Dịch: Anh ấy hoàn toàn đủ năng lực cho vị trí quản lý dự án.)"],"ukAudio":"/ai_services/tts3/?q=qualified&lang=en-GB&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=qualified&lang=en-US&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F"},{"id":"lv_0_236","topic":"Daily Life and Social Activities","word":"quiz","pos":"(n)","ipa":"/kwɪz/","defVi":"bài kiểm tra ngắn, câu đố","defEn":"a short or informal test of knowledge","examples":["We have a short vocabulary [quiz] at the beginning of each class. (=Dịch: Chúng tôi có một bài kiểm tra ngắn về từ vựng vào đầu mỗi buổi học.)","The team won first place in the pub [quiz] last night. (=Dịch: Đội đã giành giải nhất trong trò chơi đố vui tại quán rượu tối qua.)","She took an online [quiz] to determine her learning style. (=Dịch: Cô ấy đã làm một bài trắc nghiệm trực tuyến để xác định phong cách học tập của mình.)"],"ukAudio":"/ai_services/tts3/?q=quiz&lang=en-GB&ipa=%2Fkw%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=quiz&lang=en-US&ipa=%2Fkw%C9%AAz%2F"},{"id":"lv_0_237","topic":"Daily Life and Social Activities","word":"quote","pos":"(n)","ipa":"/kwoʊt/","defVi":"báo giá, lời trích dẫn","defEn":"a statement of how much a job or service will cost, or a repetition of someone's words","examples":["We asked several contractors for a [quote] before renovating the kitchen. (=Dịch: Chúng tôi đã xin bảng báo giá từ vài nhà thầu trước khi sửa sang lại nhà bếp.)","The article opened with a famous [quote] from Shakespeare. (=Dịch: Bài viết mở đầu bằng một câu trích dẫn nổi tiếng của Shakespeare.)","She requested a free [quote] for her car insurance policy. (=Dịch: Cô ấy đã yêu cầu một bảng báo giá miễn phí cho hợp đồng bảo hiểm xe hơi của mình.)"],"ukAudio":"/ai_services/tts3/?q=quote&lang=en-GB&ipa=%2Fkwo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=quote&lang=en-US&ipa=%2Fkwo%CA%8At%2F"},{"id":"lv_0_238","topic":"Daily Life and Social Activities","word":"radiator","pos":"(n)","ipa":"/ˈreɪ.di.eɪ.tər/","defVi":"bộ tản nhiệt, lò sưởi","defEn":"a device used for heating a room or for cooling an engine","examples":["He placed his wet gloves on the [radiator] to dry. (=Dịch: Anh ấy đặt đôi găng tay ướt lên bộ tản nhiệt để sấy khô.)","The car broke down because the [radiator] was leaking coolant. (=Dịch: Chiếc xe bị hỏng vì két làm mát bị rò rỉ dung dịch tản nhiệt.)","Make sure to bleed the [radiator] if the room feels cold. (=Dịch: Hãy nhớ xả khí lò sưởi nếu cảm thấy phòng bị lạnh.)"],"ukAudio":"/ai_services/tts3/?q=radiator&lang=en-GB&ipa=%2F%CB%88re%C9%AA.di.e%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=radiator&lang=en-US&ipa=%2F%CB%88re%C9%AA.di.e%C9%AA.t%C9%99r%2F"},{"id":"lv_0_239","topic":"Daily Life and Social Activities","word":"reasonable","pos":"(adj)","ipa":"/ˈriː.zən.ə.bəl/","defVi":"hợp lý, phải chăng","defEn":"fair, practical, and sensible; not too expensive","examples":["The hotel offers quality service at a very [reasonable] price. (=Dịch: Khách sạn cung cấp dịch vụ chất lượng với mức giá rất hợp lý.)","It is [reasonable] to assume that the project will take several months to finish. (=Dịch: Thật hợp lý khi cho rằng dự án sẽ mất vài tháng để hoàn thành.)","She made a [reasonable] suggestion that everyone quickly agreed with. (=Dịch: Cô ấy đã đưa ra một đề xuất hợp lý mà mọi người nhanh chóng đồng ý.)"],"ukAudio":"/ai_services/tts3/?q=reasonable&lang=en-GB&ipa=%2F%CB%88ri%CB%90.z%C9%99n.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=reasonable&lang=en-US&ipa=%2F%CB%88ri%CB%90.z%C9%99n.%C9%99.b%C9%99l%2F"},{"id":"lv_0_240","topic":"Daily Life and Social Activities","word":"reassure","pos":"(v)","ipa":"/ˌriː.əˈʃʊr/","defVi":"trấn an, làm yên lòng","defEn":"to say or do something to remove someone's doubts or fears","examples":["The doctor tried to [reassure] the worried parents about their child's recovery. (=Dịch: Bác sĩ đã cố gắng trấn an các bậc phụ huynh đang lo lắng về sự hồi phục của con họ.)","She called home to [reassure] her family that she had arrived safely. (=Dịch: Cô ấy gọi điện về nhà để trấn an gia đình rằng mình đã đến nơi an toàn.)","The manager spoke to the team to [reassure] them about job security. (=Dịch: Người quản lý đã nói chuyện với cả nhóm để trấn an họ về sự ổn định của công việc.)"],"ukAudio":"/ai_services/tts3/?q=reassure&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.%C9%99%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=reassure&lang=en-US&ipa=%2F%CB%8Cri%CB%90.%C9%99%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_0_241","topic":"Daily Life and Social Activities","word":"recreational","pos":"(adj)","ipa":"/ˌrek.riˈeɪ.ʃən.əl/","defVi":"thuộc về giải trí, tiêu khiển","defEn":"connected with ways of enjoying yourself when you are not working","examples":["The city has invested heavily in creating new [recreational] areas for families. (=Dịch: Thành phố đã đầu tư mạnh mẽ vào việc tạo ra các khu vực giải trí mới cho các gia đình.)","Cycling in the park is one of his favorite [recreational] activities. (=Dịch: Đạp xe trong công viên là một trong những hoạt động giải trí yêu thích của anh ấy.)","The local community center provides various [recreational] facilities for teenagers. (=Dịch: Trung tâm cộng đồng địa phương cung cấp nhiều cơ sở vật chất giải trí khác nhau cho thanh thiếu niên.)"],"ukAudio":"/ai_services/tts3/?q=recreational&lang=en-GB&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=recreational&lang=en-US&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_0_242","topic":"Daily Life and Social Activities","word":"register","pos":"(n)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"sổ đăng ký, sổ ghi danh","defEn":"an official list or book for keeping records","examples":["The teacher checked the attendance [register] at the start of the lesson. (=Dịch: Giáo viên đã kiểm tra sổ điểm danh vào đầu buổi học.)","Guests are required to sign the [register] upon arriving at the hotel. (=Dịch: Khách được yêu cầu ký vào sổ đăng ký khi đến khách sạn.)","The company keeps an updated [register] of all its shareholders. (=Dịch: Công ty lưu giữ một sổ danh sách cập nhật của tất cả các cổ đông.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_0_243","topic":"Daily Life and Social Activities","word":"relative","pos":"(n)","ipa":"/ˈrel.ə.t̬ɪv/","defVi":"người thân, họ hàng","defEn":"a member of your family","examples":["She went to spend the summer holiday with a close [relative] in Canada. (=Dịch: Cô ấy đã đến trải qua kỳ nghỉ hè với một người họ hàng thân thiết ở Canada.)","Almost every [relative] gathered together for the family reunion. (=Dịch: Hầu như mọi người họ hàng đều tụ họp lại trong buổi sum họp gia đình.)","He invited both friends and [relatives] to his graduation ceremony. (=Dịch: Anh ấy đã mời cả bạn bè và người thân đến dự lễ tốt nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=relative&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=relative&lang=en-US&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_0_244","topic":"Daily Life and Social Activities","word":"relay","pos":"(v)","ipa":"/ˈriː.leɪ/","defVi":"chuyển tiếp, truyền đạt lại","defEn":"to receive and pass on information, news, or a message to someone else","examples":["I will [relay] your message to the director as soon as he returns. (=Dịch: Tôi sẽ chuyển lời nhắn của bạn đến giám đốc ngay khi ông ấy quay lại.)","Satellites are used to [relay] television signals around the world. (=Dịch: Các vệ tinh được sử dụng để truyền phát tín hiệu truyền hình đi khắp thế giới.)","The assistant was asked to [relay] the meeting notes to the rest of the team. (=Dịch: Trợ lý được yêu cầu chuyển các ghi chép cuộc họp cho những người còn lại trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=relay&lang=en-GB&ipa=%2F%CB%88ri%CB%90.le%C9%AA%2F","usAudio":"/ai_services/tts3/?q=relay&lang=en-US&ipa=%2F%CB%88ri%CB%90.le%C9%AA%2F"},{"id":"lv_0_245","topic":"Daily Life and Social Activities","word":"remind","pos":"(v)","ipa":"/rɪˈmaɪnd/","defVi":"nhắc nhở","defEn":"to make someone remember somebody or something","examples":["Please [remind] me to submit the assignment before midnight. (=Dịch: Làm ơn nhắc tôi nộp bài tập trước nửa đêm nhé.)","His laugh always seems to [remind] me of his grandfather. (=Dịch: Điệu cười của anh ấy dường như luôn gợi cho tôi nhớ đến ông của anh ấy.)","The alarm on her phone was set to [remind] her of the doctor's appointment. (=Dịch: Chuông báo trên điện thoại của cô ấy được đặt để nhắc cô về cuộc hẹn với bác sĩ.)"],"ukAudio":"/ai_services/tts3/?q=remind&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=remind&lang=en-US&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F"},{"id":"lv_0_246","topic":"Daily Life and Social Activities","word":"rental","pos":"(adj)","ipa":"/ˈren.t̬əl/","defVi":"cho thuê, thuê","defEn":"relating to the act of paying money to use something temporarily","examples":["We picked up our [rental] car directly outside the airport terminal. (=Dịch: Chúng tôi đã nhận chiếc xe thuê ngay bên ngoài nhà ga sân bay.)","The rising prices in the [rental] market make it hard for students to find housing. (=Dịch: Giá cả leo thang trên thị trường cho thuê khiến sinh viên khó tìm được nhà ở.)","They decided to stay in a cozy [rental] cabin in the mountains. (=Dịch: Họ quyết định ở trong một căn cabin thuê ấm cúng trên núi.)"],"ukAudio":"/ai_services/tts3/?q=rental&lang=en-GB&ipa=%2F%CB%88ren.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rental&lang=en-US&ipa=%2F%CB%88ren.t%CC%AC%C9%99l%2F"},{"id":"lv_0_247","topic":"Daily Life and Social Activities","word":"representative","pos":"(n)","ipa":"/ˌrep.rɪˈzen.t̬ə.t̬ɪv/","defVi":"người đại diện","defEn":"a person who is chosen to speak or act on behalf of an organization or group","examples":["A company [representative] will meet you at the entrance to guide you. (=Dịch: Một đại diện của công ty sẽ đón bạn ở lối vào để hướng dẫn bạn.)","She was elected as the student [representative] on the university council. (=Dịch: Cô ấy được bầu làm đại diện sinh viên trong hội đồng trường đại học.)","Please contact our customer service [representative] if you have any questions. (=Dịch: Vui lòng liên hệ với đại diện dịch vụ khách hàng của chúng tôi nếu bạn có bất kỳ câu hỏi nào.)"],"ukAudio":"/ai_services/tts3/?q=representative&lang=en-GB&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=representative&lang=en-US&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_0_248","topic":"Daily Life and Social Activities","word":"reservation","pos":"(n)","ipa":"/ˌrez.ɚˈveɪ.ʃən/","defVi":"sự đặt chỗ trước, sự giữ chỗ","defEn":"an arrangement to have something, such as a table or a room, kept for your use","examples":["I would like to make a dinner [reservation] for four people at seven o'clock. (=Dịch: Tôi muốn đặt bàn ăn tối cho bốn người lúc bảy giờ.)","We could not find a table because we forgot to make a [reservation] in advance. (=Dịch: Chúng tôi không tìm được bàn vì đã quên đặt chỗ trước.)","The hotel sent an email to confirm our room [reservation] for next weekend. (=Dịch: Khách sạn đã gửi email xác nhận việc đặt phòng của chúng tôi cho cuối tuần tới.)"],"ukAudio":"/ai_services/tts3/?q=reservation&lang=en-GB&ipa=%2F%CB%8Crez.%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reservation&lang=en-US&ipa=%2F%CB%8Crez.%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_249","topic":"Daily Life and Social Activities","word":"reset","pos":"(v)","ipa":"/ˌriːˈsɛt/","defVi":"đặt lại, cài đặt lại","defEn":"to set something again or change it back to its original state","examples":["You need to [reset] your password after logging in for the first time. (=Dịch: Bạn cần đặt lại mật khẩu sau khi đăng nhập lần đầu tiên.)","If the router stops working, try to [reset] it by pressing the small button on the back. (=Dịch: Nếu bộ định tuyến ngừng hoạt động, hãy thử đặt lại bằng cách nhấn nút nhỏ ở phía sau.)","He decided to take a short vacation to [reset] his mind after months of hard work. (=Dịch: Anh ấy quyết định đi nghỉ ngắn ngày để làm mới lại tâm trí sau nhiều tháng làm việc chăm chỉ.)"],"ukAudio":"/ai_services/tts3/?q=reset&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=reset&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88s%C9%9Bt%2F"},{"id":"lv_0_250","topic":"Daily Life and Social Activities","word":"residential","pos":"(adj)","ipa":"/ˌrɛz.əˈdɛn.ʃəl/","defVi":"thuộc khu dân cư, dùng để ở","defEn":"relating to an area where people live rather than where businesses or factories are located","examples":["The city council plans to build a new park in the [residential] area. (=Dịch: Hội đồng thành phố có kế hoạch xây dựng một công viên mới trong khu dân cư.)","Strict speed limits are enforced on [residential] streets to protect children. (=Dịch: Các giới hạn tốc độ nghiêm ngặt được thực thi trên các con đường khu dân cư để bảo vệ trẻ em.)","The university provides [residential] accommodation for all first-year students. (=Dịch: Trường đại học cung cấp chỗ ở nội trú cho tất cả sinh viên năm nhất.)"],"ukAudio":"/ai_services/tts3/?q=residential&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bz.%C9%99%CB%88d%C9%9Bn.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=residential&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bz.%C9%99%CB%88d%C9%9Bn.%CA%83%C9%99l%2F"},{"id":"lv_0_251","topic":"Daily Life and Social Activities","word":"restricted","pos":"(adj)","ipa":"/rɪˈstrɪk.tɪd/","defVi":"bị hạn chế, giới hạn","defEn":"limited, controlled, or allowed only to certain people","examples":["Access to the server room is strictly [restricted] to authorized personnel only. (=Dịch: Quyền truy cập vào phòng máy chủ bị hạn chế nghiêm ngặt, chỉ dành riêng cho nhân viên được ủy quyền.)","She has to follow a [restricted] diet due to her food allergies. (=Dịch: Cô ấy phải tuân theo một chế độ ăn kiêng hạn chế do bị dị ứng thực phẩm.)","They were operating in a [restricted] space, which made the construction work difficult. (=Dịch: Họ phải làm việc trong một không gian hạn chế, điều này khiến công việc xây dựng gặp nhiều khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=restricted&lang=en-GB&ipa=%2Fr%C9%AA%CB%88str%C9%AAk.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=restricted&lang=en-US&ipa=%2Fr%C9%AA%CB%88str%C9%AAk.t%C9%AAd%2F"},{"id":"lv_0_252","topic":"Daily Life and Social Activities","word":"retire","pos":"(v)","ipa":"/rɪˈtaɪ.ɚ/","defVi":"nghỉ hưu, về hưu","defEn":"to stop working permanently, usually because of reaching a certain age","examples":["He plans to [retire] at the age of sixty-five and travel around the world. (=Dịch: Ông dự định nghỉ hưu ở tuổi sáu mươi lăm và đi du lịch vòng quanh thế giới.)","Many professional athletes [retire] in their early thirties due to physical injuries. (=Dịch: Nhiều vận động viên chuyên nghiệp giải nghệ ở độ tuổi đầu ba mươi do chấn thương thể chất.)","After teaching for forty years, Professor Davis decided it was time to [retire]. (=Dịch: Sau bốn mươi năm giảng dạy, Giáo sư Davis quyết định đã đến lúc phải nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retire&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=retire&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_0_253","topic":"Daily Life and Social Activities","word":"retirement","pos":"(n)","ipa":"/rɪˈtaɪ.ɚ.mənt/","defVi":"sự nghỉ hưu, thời kỳ nghỉ hưu","defEn":"the period in someone's life after they have stopped working, or the act of stopping work","examples":["She has been saving money for her [retirement] since she started her first job. (=Dịch: Cô ấy đã tiết kiệm tiền cho việc nghỉ hưu của mình kể từ khi bắt đầu công việc đầu tiên.)","His colleagues threw a big farewell party to celebrate his [retirement]. (=Dịch: Các đồng nghiệp của ông đã tổ chức một bữa tiệc chia tay lớn để chúc mừng ngày ông nghỉ hưu.)","Many people take up new hobbies such as gardening during [retirement]. (=Dịch: Nhiều người bắt đầu những sở thích mới như làm vườn trong thời gian nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retirement&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=retirement&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A.m%C9%99nt%2F"},{"id":"lv_0_254","topic":"Daily Life and Social Activities","word":"rid","pos":"(adj)","ipa":"/rɪd/","defVi":"thoát khỏi, tống khứ được, giải thoát khỏi","defEn":"free from an unwanted person, thing, or situation (commonly used in 'get rid of' or 'be rid of')","examples":["We need to get [rid] of these old newspapers to clear some space. (=Dịch: Chúng ta cần loại bỏ những tờ báo cũ này để dọn chỗ trống.)","She was finally [rid] of her bad cold after taking the prescribed medicine. (=Dịch: Cô ấy cuối cùng cũng khỏi hẳn trận cảm lạnh nặng sau khi uống thuốc theo đơn.)","The government is introducing new policies to be [rid] of corruption in public services. (=Dịch: Chính phủ đang ban hành các chính sách mới để xóa bỏ nạn tham nhũng trong các dịch vụ công.)"],"ukAudio":"/ai_services/tts3/?q=rid&lang=en-GB&ipa=%2Fr%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rid&lang=en-US&ipa=%2Fr%C9%AAd%2F"},{"id":"lv_0_255","topic":"Daily Life and Social Activities","word":"robot","pos":"(n)","ipa":"/ˈroʊ.bɑːt/","defVi":"người máy, rô-bốt","defEn":"a machine that can perform complex tasks automatically or through programmed instructions","examples":["The factory uses an advanced [robot] to assemble car parts quickly and accurately. (=Dịch: Nhà máy sử dụng một robot tiên tiến để lắp ráp các bộ phận xe hơi một cách nhanh chóng và chính xác.)","Scientists are developing a humanoid [robot] capable of assisting elderly people at home. (=Dịch: Các nhà khoa học đang phát triển một robot hình người có khả năng hỗ trợ người cao tuổi tại nhà.)","A cleaning [robot] vacuumed the entire living room floor while we were away. (=Dịch: Một robot hút bụi đã dọn dẹp toàn bộ sàn phòng khách trong khi chúng tôi đi vắng.)"],"ukAudio":"/ai_services/tts3/?q=robot&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=robot&lang=en-US&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F"},{"id":"lv_0_256","topic":"Daily Life and Social Activities","word":"rope","pos":"(n)","ipa":"/roʊp/","defVi":"dây thừng, dây cáp","defEn":"a strong, thick cord made by twisting together strands of hemp, nylon, or other materials","examples":["The climber secured the heavy [rope] to the rock before descending. (=Dịch: Người leo núi đã buộc chặt sợi dây thừng nặng vào tảng đá trước khi xuống núi.)","They tied the boat to the dock with a thick [rope]. (=Dịch: Họ đã buộc con thuyền vào bến tàu bằng một sợi dây thừng dày.)","Skipping [rope] is an effective exercise to improve cardiovascular health. (=Dịch: Nhảy dây là một bài tập hiệu quả để cải thiện sức khỏe tim mạch.)"],"ukAudio":"/ai_services/tts3/?q=rope&lang=en-GB&ipa=%2Fro%CA%8Ap%2F","usAudio":"/ai_services/tts3/?q=rope&lang=en-US&ipa=%2Fro%CA%8Ap%2F"},{"id":"lv_0_257","topic":"Daily Life and Social Activities","word":"roughly","pos":"(adv)","ipa":"/ˈrʌf.li/","defVi":"xấp xỉ, khoảng chừng, đại khái","defEn":"approximately; not completely accurately or precisely","examples":["The journey from the airport to the city center takes [roughly] forty-five minutes. (=Dịch: Hành trình từ sân bay đến trung tâm thành phố mất khoảng bốn mươi lăm phút.)","He earns [roughly] two thousand dollars a month from his freelance design work. (=Dịch: Anh ấy kiếm được khoảng hai nghìn đô la mỗi tháng từ công việc thiết kế tự do của mình.)","The total cost of the project was [roughly] estimated before the final budget was approved. (=Dịch: Tổng chi phí của dự án đã được ước tính sơ bộ trước khi ngân sách cuối cùng được phê duyệt.)"],"ukAudio":"/ai_services/tts3/?q=roughly&lang=en-GB&ipa=%2F%CB%88r%CA%8Cf.li%2F","usAudio":"/ai_services/tts3/?q=roughly&lang=en-US&ipa=%2F%CB%88r%CA%8Cf.li%2F"},{"id":"lv_0_258","topic":"Daily Life and Social Activities","word":"rush","pos":"(n)","ipa":"/rʌʃ/","defVi":"sự vội vã, sự gấp rút; dòng người/xe đổ xô","defEn":"a situation in which you must hurry, or a sudden rapid movement","examples":["I am in a huge [rush] this morning because my alarm clock did not go off. (=Dịch: Sáng nay tôi đang rất vội vì đồng hồ báo thức không reo.)","Avoid traveling during the morning [rush] hour if you want to prevent delays. (=Dịch: Hãy tránh đi lại vào giờ cao điểm buổi sáng nếu bạn muốn tránh bị chậm trễ.)","There was an unexpected [rush] for concert tickets as soon as the website opened. (=Dịch: Đã có một làn sóng đổ xô mua vé hòa nhạc bất ngờ ngay khi trang web mở bán.)"],"ukAudio":"/ai_services/tts3/?q=rush&lang=en-GB&ipa=%2Fr%CA%8C%CA%83%2F","usAudio":"/ai_services/tts3/?q=rush&lang=en-US&ipa=%2Fr%CA%8C%CA%83%2F"},{"id":"lv_0_259","topic":"Daily Life and Social Activities","word":"rust","pos":"(v)","ipa":"/rʌst/","defVi":"bị gỉ, gỉ sét","defEn":"to become covered with a reddish-brown substance because of moisture and air","examples":["Metal tools will [rust] if you leave them outside in the rain. (=Dịch: Dụng cụ bằng kim loại sẽ bị rỉ sét nếu bạn để chúng ngoài trời mưa.)","The old iron gate began to [rust] after years of neglect. (=Dịch: Cánh cổng sắt cũ bắt đầu rỉ sét sau nhiều năm không được bảo dưỡng.)","Apply a protective coating to prevent the bicycle frame from [rusting]. (=Dịch: Hãy phủ một lớp bảo vệ để tránh cho khung xe đạp bị rỉ sét.)"],"ukAudio":"/ai_services/tts3/?q=rust&lang=en-GB&ipa=%2Fr%CA%8Cst%2F","usAudio":"/ai_services/tts3/?q=rust&lang=en-US&ipa=%2Fr%CA%8Cst%2F"},{"id":"lv_0_260","topic":"Daily Life and Social Activities","word":"sailor","pos":"(n)","ipa":"/ˈseɪ.lɚ/","defVi":"thủy thủ","defEn":"a person who works on a ship as a member of the crew","examples":["The experienced [sailor] steered the ship safely through the storm. (=Dịch: Người thủy thủ giàu kinh nghiệm đã điều khiển con tàu vượt qua cơn bão một cách an toàn.)","He spent five years working as a [sailor] on a cargo vessel. (=Dịch: Anh ấy đã dành năm năm làm thủy thủ trên một con tàu chở hàng.)","Many young [sailors] joined the navy to travel the world. (=Dịch: Nhiều thủy thủ trẻ đã gia nhập hải quân để được chu du khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=sailor&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sailor&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9A%2F"},{"id":"lv_0_261","topic":"Daily Life and Social Activities","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance made of very small pieces of crushed rock found on beaches and in deserts","examples":["Children love building castles out of wet [sand] on the beach. (=Dịch: Trẻ em rất thích xây lâu đài bằng cát ướt trên bãi biển.)","The strong wind blew fine [sand] across the desert road. (=Dịch: Cơn gió mạnh đã thổi cát mịn bay qua con đường trên sa mạc.)","We shook the [sand] out of our shoes before entering the hotel. (=Dịch: Chúng tôi đã giũ sạch cát khỏi giày trước khi bước vào khách sạn.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_0_262","topic":"Daily Life and Social Activities","word":"sandal","pos":"(n)","ipa":"/ˈsæn.dl/","defVi":"dép quai hậu, xăng-đan","defEn":"a light shoe consisting of a bottom sole held onto the foot by straps","examples":["She bought a new pair of leather [sandals] for her summer vacation. (=Dịch: Cô ấy đã mua một đôi dép xăng đan bằng da mới cho kỳ nghỉ hè của mình.)","Wearing [sandals] is ideal for walking along the sunny beach. (=Dịch: Đi dép xăng đan rất lý tưởng để dạo bước dọc bãi biển đầy nắng.)","He took off his [sandals] before entering the traditional Japanese house. (=Dịch: Anh ấy đã cởi dép xăng đan ra trước khi bước vào ngôi nhà truyền thống của Nhật Bản.)"],"ukAudio":"/ai_services/tts3/?q=sandal&lang=en-GB&ipa=%2F%CB%88s%C3%A6n.dl%2F","usAudio":"/ai_services/tts3/?q=sandal&lang=en-US&ipa=%2F%CB%88s%C3%A6n.dl%2F"},{"id":"lv_0_263","topic":"Daily Life and Social Activities","word":"satisfaction","pos":"(n)","ipa":"/ˌsæt̬.ɪsˈfæk.ʃən/","defVi":"sự hài lòng, sự thỏa mãn","defEn":"a pleasant feeling of fulfillment when your desires or needs are met","examples":["Customer [satisfaction] is the top priority for our support team. (=Dịch: Sự hài lòng của khách hàng là ưu tiên hàng đầu của đội ngũ hỗ trợ chúng tôi.)","She gained deep personal [satisfaction] from volunteering at the shelter. (=Dịch: Cô ấy cảm nhận được sự thỏa nguyện sâu sắc khi làm tình nguyện viên tại khu tạm trú.)","We asked guests to complete a short [satisfaction] survey after their stay. (=Dịch: Chúng tôi đã nhờ du khách hoàn thành một khảo sát ngắn về mức độ hài lòng sau kỳ lưu trú của họ.)"],"ukAudio":"/ai_services/tts3/?q=satisfaction&lang=en-GB&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%AAs%CB%88f%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=satisfaction&lang=en-US&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%AAs%CB%88f%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_0_264","topic":"Daily Life and Social Activities","word":"satisfied","pos":"(adj)","ipa":"/ˈsæt̬.əs.faɪd/","defVi":"hài lòng, thỏa mãn","defEn":"pleased because you have got what you wanted or needed","examples":["The manager was highly [satisfied] with the team's project results. (=Dịch: Người quản lý rất hài lòng với kết quả dự án của cả nhóm.)","Customer service aims to ensure every client leaves [satisfied]. (=Dịch: Dịch vụ khách hàng hướng tới mục tiêu đảm bảo mọi khách hàng đều rời đi trong sự hài lòng.)","She felt [satisfied] after finishing a delicious home-cooked meal. (=Dịch: Cô ấy cảm thấy thỏa mãn sau khi thưởng thức xong một bữa cơm nhà nấu ngon miệng.)"],"ukAudio":"/ai_services/tts3/?q=satisfied&lang=en-GB&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=satisfied&lang=en-US&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F"},{"id":"lv_0_265","topic":"Daily Life and Social Activities","word":"scan","pos":"(v)","ipa":"/skæn/","defVi":"quét, rà soát (dữ liệu hoặc tài liệu)","defEn":"to look at all parts of something carefully, or to pass light over something to create a digital image","examples":["Please [scan] the document and email the PDF file to me. (=Dịch: Vui lòng quét tài liệu và gửi tệp PDF qua email cho tôi.)","The security guard [scanned] the crowd to spot any suspicious activity. (=Dịch: Nhân viên an ninh đã quan sát kỹ đám đông để phát hiện bất kỳ hoạt động đáng ngờ nào.)","You can [scan] the QR code with your smartphone to view the menu. (=Dịch: Bạn có thể quét mã QR bằng điện thoại thông minh để xem thực đơn.)"],"ukAudio":"/ai_services/tts3/?q=scan&lang=en-GB&ipa=%2Fsk%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=scan&lang=en-US&ipa=%2Fsk%C3%A6n%2F"},{"id":"lv_0_266","topic":"Daily Life and Social Activities","word":"scenery","pos":"(n)","ipa":"/ˈsiː.nɚ.i/","defVi":"phong cảnh, cảnh quan thiên nhiên","defEn":"the natural features of a landscape, such as mountains, forests, or rivers","examples":["We stopped our car at the mountain peak to admire the stunning [scenery]. (=Dịch: Chúng tôi dừng xe tại đỉnh núi để chiêm ngưỡng phong cảnh tuyệt đẹp.)","The train journey offers picturesque [scenery] throughout the countryside. (=Dịch: Chuyến đi bằng tàu hỏa mang đến khung cảnh miền quê đẹp như tranh vẽ.)","Tourists love visiting this national park because of its untouched [scenery]. (=Dịch: Khách du lịch thích ghé thăm công viên quốc gia này nhờ phong cảnh hoang sơ của nó.)"],"ukAudio":"/ai_services/tts3/?q=scenery&lang=en-GB&ipa=%2F%CB%88si%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=scenery&lang=en-US&ipa=%2F%CB%88si%CB%90.n%C9%9A.i%2F"},{"id":"lv_0_267","topic":"Daily Life and Social Activities","word":"seafood","pos":"(n)","ipa":"/ˈsiː.fuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, especially fish and shellfish","examples":["This coastal city is famous for its fresh and delicious [seafood]. (=Dịch: Thành phố ven biển này nổi tiếng với nguồn hải sản tươi ngon.)","He cannot eat [seafood] because he is allergic to shrimp and crab. (=Dịch: Anh ấy không thể ăn hải sản vì bị dị ứng với tôm và cua.)","We ordered a large platter of grilled [seafood] at the restaurant. (=Dịch: Chúng tôi đã gọi một đĩa hải sản nướng lớn tại nhà hàng.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F"},{"id":"lv_0_268","topic":"Daily Life and Social Activities","word":"seasonal","pos":"(adj)","ipa":"/ˈsiː.zən.əl/","defVi":"theo mùa, có tính thời vụ","defEn":"happening only during a particular season of the year","examples":["Eating [seasonal] fruit is often cheaper and better for the environment. (=Dịch: Ăn trái cây theo mùa thường rẻ hơn và tốt hơn cho môi trường.)","The hotel hires extra [seasonal] workers during the summer peak. (=Dịch: Khách sạn thuê thêm lao động thời vụ trong mùa hè cao điểm.)","Many people suffer from [seasonal] allergies when flowers bloom in spring. (=Dịch: Nhiều người bị dị ứng thời tiết theo mùa khi hoa nở vào mùa xuân.)"],"ukAudio":"/ai_services/tts3/?q=seasonal&lang=en-GB&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=seasonal&lang=en-US&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99l%2F"},{"id":"lv_0_269","topic":"Daily Life and Social Activities","word":"seating","pos":"(n)","ipa":"/ˈsiː.t̬ɪŋ/","defVi":"chỗ ngồi, sự sắp xếp chỗ ngồi","defEn":"the seats provided in a particular place, or the arrangement of seats","examples":["The new stadium provides comfortable [seating] for over fifty thousand fans. (=Dịch: Sân vận động mới có chỗ ngồi thoải mái cho hơn năm mươi nghìn người hâm mộ.)","Please check the [seating] chart to find your assigned table. (=Dịch: Vui lòng kiểm tra sơ đồ chỗ ngồi để tìm đúng bàn đã được chỉ định của bạn.)","The cafe has both indoor and outdoor [seating] areas for customers. (=Dịch: Quán cà phê có cả khu vực chỗ ngồi trong nhà và ngoài trời cho khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=seating&lang=en-GB&ipa=%2F%CB%88si%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=seating&lang=en-US&ipa=%2F%CB%88si%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_270","topic":"Daily Life and Social Activities","word":"seaweed","pos":"(n)","ipa":"/ˈsiː.wiːd/","defVi":"rong biển, tảo biển","defEn":"a plant that grows in the sea or on rocks at the edge of the sea","examples":["The beach was covered with dried [seaweed] after the storm. (=Dịch: Bãi biển phủ đầy [rong biển] khô sau cơn bão.)","Many Asian cuisines use [seaweed] as a nutritious ingredient in soups and salads. (=Dịch: Nhiều nền ẩm thực châu Á sử dụng [rong biển] như một nguyên liệu bổ dưỡng trong các món súp và salad.)","Scientists are exploring how [seaweed] can be used as an eco-friendly biofuel. (=Dịch: Các nhà khoa học đang nghiên cứu cách [rong biển] có thể được sử dụng làm nhiên liệu sinh học thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=seaweed&lang=en-GB&ipa=%2F%CB%88si%CB%90.wi%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seaweed&lang=en-US&ipa=%2F%CB%88si%CB%90.wi%CB%90d%2F"},{"id":"lv_0_271","topic":"Daily Life and Social Activities","word":"secondary","pos":"(adj)","ipa":"/ˈsek.ən.der.i/","defVi":"thứ yếu, phụ","defEn":"less important than something else; coming after what is primary","examples":["Cost is a [secondary] consideration compared to passenger safety. (=Dịch: Chi phí là một yếu tố [phụ] cần cân nhắc so với sự an toàn của hành khách.)","The medication was effective, but it caused some minor [secondary] effects. (=Dịch: Thuốc có hiệu quả, nhưng nó gây ra một số tác dụng [phụ] nhỏ.)","His main goal was to gain experience, while earning money was only a [secondary] motive. (=Dịch: Mục tiêu chính của anh ấy là tích lũy kinh nghiệm, trong khi kiếm tiền chỉ là động cơ [thứ yếu].)"],"ukAudio":"/ai_services/tts3/?q=secondary&lang=en-GB&ipa=%2F%CB%88sek.%C9%99n.der.i%2F","usAudio":"/ai_services/tts3/?q=secondary&lang=en-US&ipa=%2F%CB%88sek.%C9%99n.der.i%2F"},{"id":"lv_0_272","topic":"Daily Life and Social Activities","word":"separately","pos":"(adv)","ipa":"/ˈsep.rət.li/","defVi":"riêng rẽ, tách biệt, riêng biệt","defEn":"as a separate unit; not together with other people or things","examples":["The two topics will be discussed [separately] during the seminar. (=Dịch: Hai chủ đề sẽ được thảo luận [riêng biệt] trong buổi hội thảo.)","Please pack the fragile glassware [separately] from the heavy books. (=Dịch: Vui lòng đóng gói đồ thủy tinh dễ vỡ [riêng biệt] với những cuốn sách nặng.)","Although they work at the same company, they travel to the office [separately]. (=Dịch: Mặc dù làm việc cùng một công ty, họ đi đến văn phòng [riêng lẻ].)"],"ukAudio":"/ai_services/tts3/?q=separately&lang=en-GB&ipa=%2F%CB%88sep.r%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=separately&lang=en-US&ipa=%2F%CB%88sep.r%C9%99t.li%2F"},{"id":"lv_0_273","topic":"Daily Life and Social Activities","word":"seventh","pos":"(adj)","ipa":"/ˈsev.ənθ/","defVi":"thứ bảy","defEn":"constituting number seven in a sequence","examples":["She celebrated her [seventh] birthday with a small family party. (=Dịch: Cô bé đã tổ chức sinh nhật [thứ bảy] của mình bằng một bữa tiệc gia đình nhỏ.)","He lives on the [seventh] floor of a modern apartment building. (=Dịch: Anh ấy sống ở tầng [bảy] của một tòa nhà chung cư hiện đại.)","This marks the [seventh] time the team has won the national championship. (=Dịch: Điều này đánh dấu lần [thứ bảy] đội tuyển giành chức vô địch quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=seventh&lang=en-GB&ipa=%2F%CB%88sev.%C9%99n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=seventh&lang=en-US&ipa=%2F%CB%88sev.%C9%99n%CE%B8%2F"},{"id":"lv_0_274","topic":"Daily Life and Social Activities","word":"shipping","pos":"(n)","ipa":"/ˈʃɪp.ɪŋ/","defVi":"việc vận chuyển hàng hóa, giao hàng","defEn":"the act or business of transporting goods from one place to another","examples":["The company offers free [shipping] on all orders over fifty dollars. (=Dịch: Công ty cung cấp dịch vụ [vận chuyển] miễn phí cho tất cả các đơn hàng trên 50 đô la.)","Severe weather conditions caused major delays in international [shipping]. (=Dịch: Điều kiện thời tiết khắc nghiệt đã gây ra sự chậm trễ lớn trong hoạt động [vận chuyển] quốc tế.)","The city's port is a vital hub for global maritime [shipping]. (=Dịch: Cảng của thành phố là một trung tâm quan trọng cho hoạt động [vận tải biển] toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=shipping&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=shipping&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F"},{"id":"lv_0_275","topic":"Daily Life and Social Activities","word":"shore","pos":"(n)","ipa":"/ʃɔːr/","defVi":"bờ biển, bờ hồ","defEn":"the land along the edge of a sea, lake, or wide river","examples":["They took a peaceful walk along the [shore] at sunset. (=Dịch: Họ đã đi dạo yên bình dọc theo [bờ biển] lúc hoàng hôn.)","The boat drifted away from the [shore] into deeper water. (=Dịch: Chiếc thuyền trôi dạt ra xa khỏi [bờ] vào vùng nước sâu hơn.)","Many rare seabirds build their nests along the rocky [shore]. (=Dịch: Nhiều loài chim biển quý hiếm xây tổ dọc theo [bờ] đá.)"],"ukAudio":"/ai_services/tts3/?q=shore&lang=en-GB&ipa=%2F%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=shore&lang=en-US&ipa=%2F%CA%83%C9%94%CB%90r%2F"},{"id":"lv_0_276","topic":"Daily Life and Social Activities","word":"shuttle","pos":"(n)","ipa":"/ˈʃʌt̬.əl/","defVi":"xe buýt/tàu trung chuyển tuyến ngắn","defEn":"a vehicle that travels regularly between two places","examples":["A complimentary [shuttle] runs between the hotel and the airport every thirty minutes. (=Dịch: Một chuyến [xe đưa đón] miễn phí chạy giữa khách sạn và sân bay cứ ba mươi phút một chuyến.)","We took the campus [shuttle] to get to the science building on time. (=Dịch: Chúng tôi đã đi [xe đưa đón] của khuôn viên trường để đến tòa nhà khoa học đúng giờ.)","The city introduced an electric [shuttle] to reduce traffic in the downtown area. (=Dịch: Thành phố đã giới thiệu một tuyến [xe buýt đưa đón] chạy bằng điện để giảm bớt lưu lượng giao thông ở khu vực trung tâm thành phố.)"],"ukAudio":"/ai_services/tts3/?q=shuttle&lang=en-GB&ipa=%2F%CB%88%CA%83%CA%8Ct%CC%AC.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=shuttle&lang=en-US&ipa=%2F%CB%88%CA%83%CA%8Ct%CC%AC.%C9%99l%2F"},{"id":"lv_0_277","topic":"Daily Life and Social Activities","word":"sighted","pos":"(adj)","ipa":"/ˈsaɪ.t̬ɪd/","defVi":"sáng mắt, có thị lực","defEn":"having the ability to see; not blind","examples":["The museum offers guided tours tailored for both blind and [sighted] visitors. (=Dịch: Bảo tàng cung cấp các chuyến tham quan có hướng dẫn viên được thiết kế riêng cho cả khách khiếm thị và khách [sáng mắt].)","A [sighted] volunteer assisted the visually impaired athlete during the race. (=Dịch: Một tình nguyện viên [sáng mắt] đã hỗ trợ vận động viên khiếm thị trong suốt cuộc đua.)","Software designers must consider how [sighted] users interact differently with screen layouts. (=Dịch: Các nhà thiết kế phần mềm phải xem xét cách người dùng [sáng mắt] tương tác khác nhau với bố cục màn hình.)"],"ukAudio":"/ai_services/tts3/?q=sighted&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=sighted&lang=en-US&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AAd%2F"},{"id":"lv_0_278","topic":"Daily Life and Social Activities","word":"smoothly","pos":"(adv)","ipa":"/ˈsmuːð.li/","defVi":"một cách trôi chảy, suôn sẻ, êm ả","defEn":"without any sudden changes, interruption, or difficulty","examples":["The transition to the new software system went very [smoothly]. (=Dịch: Quá trình chuyển đổi sang hệ thống phần mềm mới diễn ra rất [suôn sẻ].)","The train accelerated [smoothly] as it departed from the station. (=Dịch: Đoàn tàu tăng tốc [êm ả] khi rời khỏi nhà ga.)","If everything runs [smoothly], the renovation project will be finished by Friday. (=Dịch: Nếu mọi việc diễn ra [thuận lợi], dự án cải tạo sẽ hoàn thành trước thứ Sáu.)"],"ukAudio":"/ai_services/tts3/?q=smoothly&lang=en-GB&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F","usAudio":"/ai_services/tts3/?q=smoothly&lang=en-US&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F"},{"id":"lv_0_279","topic":"Daily Life and Social Activities","word":"socialise","pos":"(v)","ipa":"/ˈsoʊ.ʃə.laɪz/","defVi":"giao lưu, hòa nhập xã hội, kết bạn","defEn":"to spend time with other people for pleasure in a friendly way","examples":["University provides plenty of opportunities to [socialise] with people from diverse backgrounds. (=Dịch: Trường đại học mang lại nhiều cơ hội để [giao lưu] với những người đến từ các nền văn hóa khác nhau.)","He prefers to stay home on weekends rather than [socialise] with large groups. (=Dịch: Anh ấy thích ở nhà vào cuối tuần hơn là [giao lưu] với những nhóm đông người.)","Joining a sports club is a great way for newcomers to [socialise] and make friends. (=Dịch: Tham gia một câu lạc bộ thể thao là một cách tuyệt vời để những người mới đến có thể [giao lưu] và kết bạn.)"],"ukAudio":"/ai_services/tts3/?q=socialise&lang=en-GB&ipa=%2F%CB%88so%CA%8A.%CA%83%C9%99.la%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=socialise&lang=en-US&ipa=%2F%CB%88so%CA%8A.%CA%83%C9%99.la%C9%AAz%2F"},{"id":"lv_0_280","topic":"Daily Life and Social Activities","word":"spa","pos":"(n)","ipa":"/spɑː/","defVi":"khu nghỉ dưỡng suối khoáng, trung tâm chăm sóc sức khỏe và làm đẹp (spa)","defEn":"a place where people go to relax, improve their health, or receive beauty treatments","examples":["She spent the entire weekend relaxing at a luxury [spa]. (=Dịch: Cô ấy đã dành trọn cả cuối tuần để thư giãn tại một khu spa sang trọng.)","The hotel features a heated indoor pool and a modern [spa] center. (=Dịch: Khách sạn có hồ bơi nước nóng trong nhà và một trung tâm spa hiện đại.)","Many people visit this town for its natural [spa] waters. (=Dịch: Nhiều người ghé thăm thị trấn này vì nguồn nước khoáng tự nhiên của nó.)"],"ukAudio":"/ai_services/tts3/?q=spa&lang=en-GB&ipa=%2Fsp%C9%91%CB%90%2F","usAudio":"/ai_services/tts3/?q=spa&lang=en-US&ipa=%2Fsp%C9%91%CB%90%2F"},{"id":"lv_0_281","topic":"Daily Life and Social Activities","word":"spain","pos":"(n)","ipa":"/speɪn/","defVi":"nước Tây Ban Nha","defEn":"a country in southwestern Europe on the Iberian Peninsula","examples":["They are planning a two-week holiday in [Spain] this summer. (=Dịch: Họ đang lên kế hoạch cho một kỳ nghỉ kéo dài hai tuần tại Tây Ban Nha vào mùa hè này.)","[Spain] is famous for its rich history, delicious food, and sunny beaches. (=Dịch: Tây Ban Nha nổi tiếng với lịch sử phong phú, ẩm thực thơm ngon và những bãi biển đầy nắng.)","Many international students choose to study abroad in [Spain]. (=Dịch: Nhiều du học sinh quốc tế chọn đi du học ở Tây Ban Nha.)"],"ukAudio":"/ai_services/tts3/?q=spain&lang=en-GB&ipa=%2Fspe%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spain&lang=en-US&ipa=%2Fspe%C9%AAn%2F"},{"id":"lv_0_282","topic":"Daily Life and Social Activities","word":"spanish","pos":"(adj)","ipa":"/ˈspæn.ɪʃ/","defVi":"(thuộc) Tây Ban Nha, tiếng Tây Ban Nha","defEn":"connected with Spain, its people, or its language","examples":["She enjoys listening to traditional [Spanish] guitar music. (=Dịch: Cô ấy thích nghe nhạc guitar truyền thống của Tây Ban Nha.)","Tapas is a widely known [Spanish] style of serving small savory dishes. (=Dịch: Tapas là một phong cách phục vụ các món mặn nhỏ nổi tiếng rộng rãi của Tây Ban Nha.)","He is currently enrolled in a beginner [Spanish] language course. (=Dịch: Anh ấy hiện đang theo học một khóa học tiếng Tây Ban Nha dành cho người mới bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=spanish&lang=en-GB&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=spanish&lang=en-US&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F"},{"id":"lv_0_283","topic":"Daily Life and Social Activities","word":"spare","pos":"(adj)","ipa":"/sper/","defVi":"dự phòng, thừa, rảnh rỗi","defEn":"kept in addition to what is normally needed, available for use if needed","examples":["Always keep a [spare] key in case you lock yourself out. (=Dịch: Hãy luôn giữ một chiếc chìa khóa dự phòng phòng trường hợp bạn tự nhốt mình ở bên ngoài.)","He likes to read historical novels in his [spare] time. (=Dịch: Anh ấy thích đọc tiểu thuyết lịch sử vào thời gian rảnh rỗi.)","We have a [spare] bedroom upstairs for visiting guests. (=Dịch: Chúng tôi có một phòng ngủ dự phòng ở tầng trên dành cho khách đến thăm.)"],"ukAudio":"/ai_services/tts3/?q=spare&lang=en-GB&ipa=%2Fsper%2F","usAudio":"/ai_services/tts3/?q=spare&lang=en-US&ipa=%2Fsper%2F"},{"id":"lv_0_284","topic":"Daily Life and Social Activities","word":"spectacular","pos":"(adj)","ipa":"/spekˈtæk.jə.lɚ/","defVi":"ngoạn mục, hùng vĩ, đẹp mắt","defEn":"very impressive, beautiful, or striking to see","examples":["The mountaintop offers a [spectacular] view of the entire valley. (=Dịch: Đỉnh núi mang lại tầm nhìn ngoạn mục ra toàn bộ thung lũng.)","The opening ceremony ended with a [spectacular] fireworks display. (=Dịch: Lễ khai mạc đã kết thúc bằng một màn trình diễn pháo hoa ngoạn mục.)","The team achieved a [spectacular] victory in the final minutes of the match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_0_285","topic":"Daily Life and Social Activities","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị, hương liệu","defEn":"a substance made from plants used to give special flavor and aroma to food","examples":["Cinnamon is a popular [spice] used in both sweet and savory dishes. (=Dịch: Quế là một loại gia vị phổ biến được sử dụng trong cả các món ngọt lẫn món mặn.)","The chef added a pinch of exotic [spice] to enhance the flavor of the soup. (=Dịch: Đầu bếp đã thêm một nhúm gia vị ngoại lai để làm tăng hương vị của món súp.)","The historic trade of silk and [spice] connected Asia with Europe. (=Dịch: Con đường thương mại tơ lụa và gia vị trong lịch sử đã kết nối châu Á với châu Âu.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_0_286","topic":"Daily Life and Social Activities","word":"split","pos":"(v)","ipa":"/splɪt/","defVi":"chia ra, tách rời, phân chia","defEn":"to divide or break into two or more parts","examples":["The teacher asked the students to [split] into small discussion groups. (=Dịch: Giáo viên đã yêu cầu học sinh chia thành các nhóm thảo luận nhỏ.)","They decided to [split] the dinner bill evenly between them. (=Dịch: Họ quyết định chia đều hóa đơn bữa tối cho nhau.)","A deep disagreement threatened to [split] the political party apart. (=Dịch: Một sự bất đồng sâu sắc đã đe dọa chia rẽ đảng chính trị này.)"],"ukAudio":"/ai_services/tts3/?q=split&lang=en-GB&ipa=%2Fspl%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=split&lang=en-US&ipa=%2Fspl%C9%AAt%2F"},{"id":"lv_0_287","topic":"Daily Life and Social Activities","word":"sponsor","pos":"(v)","ipa":"/ˈspɑːn.sɚ/","defVi":"tài trợ, bảo trợ","defEn":"to support an event, person, or organization financially, often for advertising","examples":["Several local businesses agreed to [sponsor] the charity marathon. (=Dịch: Một số doanh nghiệp địa phương đã đồng ý tài trợ cho cuộc thi chạy marathon từ thiện.)","The tech company will [sponsor] the annual scientific conference. (=Dịch: Công ty công nghệ sẽ tài trợ cho hội nghị khoa học thường niên.)","Her company offered to [sponsor] her postgraduate degree in business. (=Dịch: Công ty của cô ấy đã đề nghị tài trợ cho bằng sau đại học về kinh doanh của cô.)"],"ukAudio":"/ai_services/tts3/?q=sponsor&lang=en-GB&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sponsor&lang=en-US&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A%2F"},{"id":"lv_0_288","topic":"Daily Life and Social Activities","word":"sponsorship","pos":"(n)","ipa":"/ˈspɑːn.sɚ.ʃɪp/","defVi":"sự tài trợ, tiền tài trợ","defEn":"financial support given by an organization or person for an activity or event","examples":["The sports event could not take place without corporate [sponsorship]. (=Dịch: Sự kiện thể thao không thể diễn ra nếu không có sự tài trợ của doanh nghiệp.)","The athlete signed a lucrative [sponsorship] deal with a major sportswear brand. (=Dịch: Vận động viên này đã ký một hợp đồng tài trợ béo bở với một thương hiệu đồ thể thao lớn.)","The exhibition relies heavily on government [sponsorship] and private donations. (=Dịch: Triển lãm phụ thuộc rất nhiều vào sự tài trợ của chính phủ và các khoản quyên góp tư nhân.)"],"ukAudio":"/ai_services/tts3/?q=sponsorship&lang=en-GB&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=sponsorship&lang=en-US&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A.%CA%83%C9%AAp%2F"},{"id":"lv_0_289","topic":"Daily Life and Social Activities","word":"steep","pos":"(adj)","ipa":"/stiːp/","defVi":"dốc, đứng; (giá cả) tăng vọt","defEn":"rising or falling sharply, not gradually","examples":["It was difficult to climb the [steep] hill in the hot weather. (=Dịch: Thật khó để leo lên ngọn đồi dốc đứng trong thời tiết nóng bức.)","The company faced a [steep] decline in sales during the crisis. (=Dịch: Công ty phải đối mặt với sự sụt giảm mạnh về doanh số trong suốt cuộc khủng hoảng.)","Consumers complained about the [steep] increase in electricity prices. (=Dịch: Người tiêu dùng đã phàn nàn về mức tăng quá cao của giá điện.)"],"ukAudio":"/ai_services/tts3/?q=steep&lang=en-GB&ipa=%2Fsti%CB%90p%2F","usAudio":"/ai_services/tts3/?q=steep&lang=en-US&ipa=%2Fsti%CB%90p%2F"},{"id":"lv_0_290","topic":"Daily Life and Social Activities","word":"stove","pos":"(n)","ipa":"/stoʊv/","defVi":"bếp nấu (thường có lò nướng đi kèm)","defEn":"a large piece of kitchen equipment used for cooking food, with burners on top and an oven underneath","examples":["She placed a kettle of water on the [stove] to make tea. (=Dịch: Cô ấy đặt một ấm nước lên bếp để pha trà.)","Don't forget to turn off the [stove] before leaving the kitchen. (=Dịch: Đừng quên tắt bếp trước khi rời khỏi nhà bếp.)","They bought a modern gas [stove] for their newly renovated apartment. (=Dịch: Họ đã mua một chiếc bếp gas hiện đại cho căn hộ mới cải tạo của mình.)"],"ukAudio":"/ai_services/tts3/?q=stove&lang=en-GB&ipa=%2Fsto%CA%8Av%2F","usAudio":"/ai_services/tts3/?q=stove&lang=en-US&ipa=%2Fsto%CA%8Av%2F"},{"id":"lv_0_291","topic":"Daily Life and Social Activities","word":"straightaway","pos":"(adv)","ipa":"/ˌstreɪt.əˈweɪ/","defVi":"ngay lập tức, không chậm trễ","defEn":"without delay; immediately","examples":["When the alarm sounded, the students evacuated the building [straightaway]. (=Dịch: Khi chuông báo động vang lên, các học sinh đã sơ tán khỏi tòa nhà ngay lập tức.)","I knew [straightaway] that something was wrong with the computer. (=Dịch: Tôi nhận ra ngay lập tức rằng có điều gì đó không ổn với chiếc máy tính.)","If you feel unwell, you should see a doctor [straightaway]. (=Dịch: Nếu bạn cảm thấy không khỏe, bạn nên đi khám bác sĩ ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=straightaway&lang=en-GB&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=straightaway&lang=en-US&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F"},{"id":"lv_0_292","topic":"Daily Life and Social Activities","word":"strength","pos":"(n)","ipa":"/strɛŋkθ/","defVi":"sức mạnh, thể lực, độ bền","defEn":"the state or quality of being physically strong, powerful, or durable","examples":["He exercises every morning to build his muscle [strength]. (=Dịch: Anh ấy tập thể dục mỗi sáng để tăng cường sức mạnh cơ bắp.)","Her inner [strength] helped her overcome the difficult times. (=Dịch: Sức mạnh nội tâm đã giúp cô ấy vượt qua những khoảng thời gian khó khăn.)","Engineers tested the [strength] of the bridge before opening it to traffic. (=Dịch: Các kỹ sư đã kiểm tra độ chịu lực của cây cầu trước khi cho phép lưu thông.)"],"ukAudio":"/ai_services/tts3/?q=strength&lang=en-GB&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F","usAudio":"/ai_services/tts3/?q=strength&lang=en-US&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F"},{"id":"lv_0_293","topic":"Daily Life and Social Activities","word":"strip","pos":"(v)","ipa":"/strɪp/","defVi":"lột bỏ, cởi bỏ, tước đi","defEn":"to remove a layer, covering, or clothes from someone or something","examples":["The painters will [strip] the old wallpaper before painting the room. (=Dịch: Những người thợ sơn sẽ bóc lớp giấy dán tường cũ trước khi sơn căn phòng.)","Strong winds can [strip] leaves off the trees during autumn. (=Dịch: Những cơn gió mạnh có thể cuốn sạch lá trên cây vào mùa thu.)","The athlete was [stripped] of his medal after failing the drug test. (=Dịch: Vận động viên đã bị tước huy chương sau khi không vượt qua buổi kiểm tra chất kích thích.)"],"ukAudio":"/ai_services/tts3/?q=strip&lang=en-GB&ipa=%2Fstr%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=strip&lang=en-US&ipa=%2Fstr%C9%AAp%2F"},{"id":"lv_0_294","topic":"Daily Life and Social Activities","word":"studio","pos":"(n)","ipa":"/ˈstuː.diˌoʊ/","defVi":"phòng thu, xưởng vẽ, studio","defEn":"a room or building where an artist, photographer, or musician works","examples":["The band spent three months recording their new album in the [studio]. (=Dịch: Ban nhạc đã dành ba tháng để thu âm album mới của họ trong phòng thu.)","She rented a small [studio] in the city to practice her painting. (=Dịch: Cô ấy đã thuê một xưởng vẽ nhỏ trong thành phố để luyện tập vẽ tranh.)","The photographer set up bright lights across the photography [studio]. (=Dịch: Nhiếp ảnh gia đã lắp đặt đèn sáng khắp studio chụp ảnh.)"],"ukAudio":"/ai_services/tts3/?q=studio&lang=en-GB&ipa=%2F%CB%88stu%CB%90.di%CB%8Co%CA%8A%2F","usAudio":"/ai_services/tts3/?q=studio&lang=en-US&ipa=%2F%CB%88stu%CB%90.di%CB%8Co%CA%8A%2F"},{"id":"lv_0_295","topic":"Daily Life and Social Activities","word":"suburb","pos":"(n)","ipa":"/ˈsʌb.ɜːrb/","defVi":"khu vực ngoại ô, vùng ven đô","defEn":"an area where people live outside the center of a city","examples":["Many families prefer to live in a quiet [suburb] with good schools. (=Dịch: Nhiều gia đình thích sống ở một vùng ngoại ô yên tĩnh với các trường học tốt.)","He commutes daily from the [suburb] to his office downtown. (=Dịch: Hàng ngày anh ấy đi lại từ vùng ngoại ô đến văn phòng ở trung tâm thành phố.)","The peaceful [suburb] has developed rapidly over the past decade. (=Dịch: Vùng ngoại ô yên bình đã phát triển nhanh chóng trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=suburb&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.%C9%9C%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=suburb&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.%C9%9C%CB%90rb%2F"},{"id":"lv_0_296","topic":"Daily Life and Social Activities","word":"suitcase","pos":"(n)","ipa":"/ˈsuːt.keɪs/","defVi":"vali du lịch","defEn":"a rectangular case with a handle, used for carrying clothes and personal items when traveling","examples":["She packed her [suitcase] the night before the flight. (=Dịch: Cô ấy đã thu dọn vali vào đêm trước chuyến bay.)","The airline lost his [suitcase] during his trip to Paris. (=Dịch: Hãng hàng không đã làm mất vali của anh ấy trong chuyến đi đến Paris.)","He struggled to lift the heavy [suitcase] into the overhead bin. (=Dịch: Anh ấy đã chật vật nhấc chiếc vali nặng lên ngăn hành lý phía trên.)"],"ukAudio":"/ai_services/tts3/?q=suitcase&lang=en-GB&ipa=%2F%CB%88su%CB%90t.ke%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=suitcase&lang=en-US&ipa=%2F%CB%88su%CB%90t.ke%C9%AAs%2F"},{"id":"lv_0_297","topic":"Daily Life and Social Activities","word":"suite","pos":"(n)","ipa":"/swiːt/","defVi":"phòng dãy, phòng cao cấp khép kín (trong khách sạn)","defEn":"a set of connected rooms, especially in a hotel","examples":["They booked the bridal [suite] for their honeymoon. (=Dịch: Họ đã đặt phòng tân hôn cho tuần trăng mật của mình.)","The luxury hotel features an executive [suite] with a sea view. (=Dịch: Khách sạn sang trọng có một phòng suite cao cấp hướng biển.)","The company rented an office [suite] on the top floor of the skyscraper. (=Dịch: Công ty đã thuê một dãy văn phòng ở tầng cao nhất của tòa nhà chọc trời.)"],"ukAudio":"/ai_services/tts3/?q=suite&lang=en-GB&ipa=%2Fswi%CB%90t%2F","usAudio":"/ai_services/tts3/?q=suite&lang=en-US&ipa=%2Fswi%CB%90t%2F"},{"id":"lv_0_298","topic":"Daily Life and Social Activities","word":"sum","pos":"(n)","ipa":"/sʌm/","defVi":"tổng số, khoản tiền","defEn":"an amount of money, or the total number resulting from adding two or more numbers together","examples":["She donated a large [sum] of money to the local charity. (=Dịch: Cô ấy đã quyên góp một khoản tiền lớn cho tổ chức từ thiện địa phương.)","The [sum] of five and seven is twelve. (=Dịch: Tổng của năm và bảy là mười hai.)","The final [sum] of damages caused by the storm was enormous. (=Dịch: Tổng thiệt hại cuối cùng do cơn bão gây ra là rất lớn.)"],"ukAudio":"/ai_services/tts3/?q=sum&lang=en-GB&ipa=%2Fs%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=sum&lang=en-US&ipa=%2Fs%CA%8Cm%2F"},{"id":"lv_0_299","topic":"Daily Life and Social Activities","word":"sunset","pos":"(n)","ipa":"/ˈsʌn.sɛt/","defVi":"hoàng hôn, cảnh mặt trời lặn","defEn":"the time in the evening when the sun disappears below the horizon, or the colors in the sky at this time","examples":["We walked along the beach to watch the beautiful [sunset]. (=Dịch: Chúng tôi đi dạo dọc bãi biển để ngắm cảnh hoàng hôn tuyệt đẹp.)","The sky turned deep orange and purple during the [sunset]. (=Dịch: Bầu trời chuyển sang màu cam đậm và tím lúc hoàng hôn.)","The fishermen returned to the harbor just before [sunset]. (=Dịch: Các ngư dân đã trở về bến cảng ngay trước lúc hoàng hôn.)"],"ukAudio":"/ai_services/tts3/?q=sunset&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=sunset&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.s%C9%9Bt%2F"},{"id":"lv_0_300","topic":"Daily Life and Social Activities","word":"supervise","pos":"(v)","ipa":"/ˈsu·pərˌvaɪz/","defVi":"giám sát, quản lý","defEn":"to watch over and direct someone or something to ensure tasks are done correctly","examples":["A senior manager will [supervise] the new interns during their training period. (=Dịch: Một quản lý cấp cao sẽ giám sát các thực tập sinh mới trong suốt thời gian đào tạo của họ.)","Teachers need to [supervise] children closely when they play near the swimming pool. (=Dịch: Giáo viên cần giám sát trẻ em chặt chẽ khi các em chơi gần hồ bơi.)","He was hired to [supervise] the construction of the new office building. (=Dịch: Anh ấy được thuê để giám sát việc xây dựng tòa nhà văn phòng mới.)"],"ukAudio":"/ai_services/tts3/?q=supervise&lang=en-GB&ipa=%2F%CB%88su%C2%B7p%C9%99r%CB%8Cva%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=supervise&lang=en-US&ipa=%2F%CB%88su%C2%B7p%C9%99r%CB%8Cva%C9%AAz%2F"},{"id":"lv_0_301","topic":"Daily Life and Social Activities","word":"surname","pos":"(n)","ipa":"/ˈsɜrˌneɪm/","defVi":"họ (tên họ)","defEn":"the name that a person shares with other members of their family; a last name","examples":["Please write your first name followed by your [surname] on the application form. (=Dịch: Vui lòng viết tên rồi đến họ của bạn vào đơn đăng ký.)","Nguyen is the most common [surname] in Vietnam. (=Dịch: Nguyễn là họ phổ biến nhất ở Việt Nam.)","She decided to keep her maiden [surname] even after getting married. (=Dịch: Cô ấy quyết định giữ lại họ thời con gái của mình ngay cả sau khi kết hôn.)"],"ukAudio":"/ai_services/tts3/?q=surname&lang=en-GB&ipa=%2F%CB%88s%C9%9Cr%CB%8Cne%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=surname&lang=en-US&ipa=%2F%CB%88s%C9%9Cr%CB%8Cne%C9%AAm%2F"},{"id":"lv_0_302","topic":"Daily Life and Social Activities","word":"suspicious","pos":"(adj)","ipa":"/səˈspɪʃ.əs/","defVi":"khả nghi, đáng ngờ; hoài nghi","defEn":"feeling or causing a feeling that something is wrong, dishonest, or illegal","examples":["The security guard noticed a [suspicious] man walking around the parking lot. (=Dịch: Nhân viên bảo vệ nhận thấy một người đàn ông khả nghi đang đi quanh bãi đỗ xe.)","The police became [suspicious] when the suspect changed his story several times. (=Dịch: Cảnh sát bắt đầu nghi ngờ khi nghi phạm thay đổi lời khai nhiều lần.)","Do not click on any [suspicious] links in emails from unknown senders. (=Dịch: Đừng nhấp vào bất kỳ liên kết đáng ngờ nào trong các email gửi từ người lạ.)"],"ukAudio":"/ai_services/tts3/?q=suspicious&lang=en-GB&ipa=%2Fs%C9%99%CB%88sp%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=suspicious&lang=en-US&ipa=%2Fs%C9%99%CB%88sp%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_0_303","topic":"Daily Life and Social Activities","word":"swimmer","pos":"(n)","ipa":"/ˈswɪm.ər/","defVi":"người bơi lội, vận động viên bơi lội","defEn":"a person who swims, especially for sport or recreation","examples":["She is a talented [swimmer] who has won several national medals. (=Dịch: Cô ấy là một vận động viên bơi lội tài năng đã giành được nhiều huy chương cấp quốc gia.)","Even a strong [swimmer] can get into trouble in rough ocean waves. (=Dịch: Ngay cả một người bơi giỏi cũng có thể gặp rắc rối giữa những con sóng biển dữ dội.)","The lifeguard warned the [swimmer] not to go too far from the shore. (=Dịch: Nhân viên cứu hộ đã cảnh báo người bơi không nên ra quá xa bờ.)"],"ukAudio":"/ai_services/tts3/?q=swimmer&lang=en-GB&ipa=%2F%CB%88sw%C9%AAm.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=swimmer&lang=en-US&ipa=%2F%CB%88sw%C9%AAm.%C9%99r%2F"},{"id":"lv_0_304","topic":"Daily Life and Social Activities","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.əˌweɪ/","defVi":"đồ ăn mang về; quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else, or the shop that sells it","examples":["We were too tired to cook dinner, so we ordered a Chinese [takeaway]. (=Dịch: Chúng tôi quá mệt để nấu bữa tối, vì vậy chúng tôi đã gọi đồ ăn Trung Quốc mang về.)","There is a great pizza [takeaway] just around the corner from our apartment. (=Dịch: Có một quán pizza mang về rất ngon ngay góc phố cạnh căn hộ của chúng tôi.)","She picked up a coffee [takeaway] on her way to the morning lecture. (=Dịch: Cô ấy đã mua một ly cà phê mang đi trên đường đến buổi giảng sáng.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F"},{"id":"lv_0_305","topic":"Daily Life and Social Activities","word":"tank","pos":"(n)","ipa":"/tæŋk/","defVi":"xe tăng","defEn":"a heavy armored military vehicle that moves on tracks and carries large guns","examples":["The military deployed a [tank] to guard the entrance of the army base. (=Dịch: Quân đội đã triển khai một chiếc xe tăng để canh gác lối vào căn cứ quân sự.)","Several museums display a restored [tank] from the Second World War. (=Dịch: Một số viện bảo tàng trưng bày một chiếc xe tăng được phục chế từ Chiến tranh Thế giới thứ hai.)","The soldiers were trained to operate the modern [tank] in harsh desert conditions. (=Dịch: Các binh sĩ đã được huấn luyện để vận hành chiếc xe tăng hiện đại trong điều kiện sa mạc khắc nghiệt.)"],"ukAudio":"/ai_services/tts3/?q=tank&lang=en-GB&ipa=%2Ft%C3%A6%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=tank&lang=en-US&ipa=%2Ft%C3%A6%C5%8Bk%2F"},{"id":"lv_0_306","topic":"Daily Life and Social Activities","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, van khóa","defEn":"a device that controls the flow of liquid or gas from a pipe or container","examples":["Remember to turn off the [tap] while brushing your teeth to save water. (=Dịch: Hãy nhớ khóa vòi nước trong khi đánh răng để tiết kiệm nước.)","Water was dripping slowly from the leaky kitchen [tap]. (=Dịch: Nước nhỏ từng giọt chầm chậm từ chiếc vòi bếp bị rò rỉ.)","You should not drink water straight from the [tap] in this region. (=Dịch: Bạn không nên uống nước trực tiếp từ vòi ở khu vực này.)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_0_307","topic":"Daily Life and Social Activities","word":"temple","pos":"(n)","ipa":"/ˈtɛm.pəl/","defVi":"ngôi đền, ngôi chùa, miếu","defEn":"a building used for the worship of a god or gods in some religions","examples":["Thousands of tourists visit the ancient Buddhist [temple] every year. (=Dịch: Hàng nghìn du khách ghé thăm ngôi chùa Phật giáo cổ kính này mỗi năm.)","Visitors are asked to remove their shoes before entering the sacred [temple]. (=Dịch: Du khách được yêu cầu cởi giày trước khi bước vào ngôi đền linh thiêng.)","The stone carvings on the [temple] walls date back to the tenth century. (=Dịch: Những hình chạm khắc bằng đá trên tường đền có từ thế kỷ thứ mười.)"],"ukAudio":"/ai_services/tts3/?q=temple&lang=en-GB&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=temple&lang=en-US&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F"},{"id":"lv_0_308","topic":"Daily Life and Social Activities","word":"terrace","pos":"(n)","ipa":"/ˈtɛr.əs/","defVi":"sân hiên, sân thượng","defEn":"a flat outdoor area next to a building or on a roof, used for relaxing or dining","examples":["We enjoyed having our breakfast out on the sunny hotel [terrace]. (=Dịch: Chúng tôi rất thích dùng bữa sáng ngoài sân hiên đầy nắng của khách sạn.)","The rooftop [terrace] offers a panoramic view of the entire city skyline. (=Dịch: Sân thượng mang lại tầm nhìn toàn cảnh ra đường chân trời của toàn thành phố.)","They placed several potted plants and comfortable chairs on their apartment [terrace]. (=Dịch: Họ đặt vài chậu cây và những chiếc ghế êm ái trên sân hiên căn hộ của mình.)"],"ukAudio":"/ai_services/tts3/?q=terrace&lang=en-GB&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=terrace&lang=en-US&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F"},{"id":"lv_0_309","topic":"Daily Life and Social Activities","word":"tester","pos":"(n)","ipa":"/ˈtɛs.tər/","defVi":"người kiểm thử, người thử nghiệm","defEn":"a person whose job is to check whether a product, software, or system works properly","examples":["The software [tester] discovered a serious bug before the game was released. (=Dịch: Người kiểm thử phần mềm đã phát hiện ra một lỗi nghiêm trọng trước khi trò chơi được phát hành.)","Companies often hire a cosmetic [tester] to evaluate the safety of new beauty products. (=Dịch: Các công ty thường thuê người thử nghiệm mỹ phẩm để đánh giá độ an toàn của các sản phẩm làm đẹp mới.)","As a beta [tester], his role is to give detailed feedback on the app user experience. (=Dịch: Với tư cách là người thử nghiệm bản beta, vai trò của anh ấy là đưa ra phản hồi chi tiết về trải nghiệm người dùng của ứng dụng.)"],"ukAudio":"/ai_services/tts3/?q=tester&lang=en-GB&ipa=%2F%CB%88t%C9%9Bs.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tester&lang=en-US&ipa=%2F%CB%88t%C9%9Bs.t%C9%99r%2F"},{"id":"lv_0_310","topic":"Daily Life and Social Activities","word":"theft","pos":"(n)","ipa":"/θɛft/","defVi":"hành vi trộm cắp, tội trộm cắp","defEn":"the act or crime of stealing someone's property","examples":["The store installed security cameras to prevent [theft]. (=Dịch: Cửa hàng đã lắp đặt các camera an ninh để ngăn chặn nạn trộm cắp.)","He reported the [theft] of his car to the police immediately. (=Dịch: Anh ấy đã báo cáo vụ mất trộm xe ô tô của mình cho cảnh sát ngay lập tức.)","Identity [theft] has become a major problem in the digital age. (=Dịch: Đánh cắp danh tính đã trở thành một vấn đề lớn trong thời đại kỹ thuật số.)"],"ukAudio":"/ai_services/tts3/?q=theft&lang=en-GB&ipa=%2F%CE%B8%C9%9Bft%2F","usAudio":"/ai_services/tts3/?q=theft&lang=en-US&ipa=%2F%CE%B8%C9%9Bft%2F"},{"id":"lv_0_311","topic":"Daily Life and Social Activities","word":"thorough","pos":"(adj)","ipa":"/ˈθɜːr.oʊ/","defVi":"kỹ lưỡng, cẩn thận, toàn diện","defEn":"complete and with great attention to every detail","examples":["The police conducted a [thorough] investigation into the accident. (=Dịch: Cảnh sát đã tiến hành một cuộc điều tra kỹ lưỡng về vụ tai nạn.)","You should do a [thorough] check of your essay before submitting it. (=Dịch: Bạn nên kiểm tra cẩn thận bài luận của mình trước khi nộp.)","She has a [thorough] understanding of the local market. (=Dịch: Cô ấy có sự hiểu biết sâu sắc về thị trường địa phương.)"],"ukAudio":"/ai_services/tts3/?q=thorough&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9C%CB%90r.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=thorough&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9C%CB%90r.o%CA%8A%2F"},{"id":"lv_0_312","topic":"Daily Life and Social Activities","word":"thumb","pos":"(n)","ipa":"/θʌm/","defVi":"ngón tay cái","defEn":"the short, thick finger on the side of each human hand","examples":["She accidentally hit her [thumb] with a hammer. (=Dịch: Cô ấy vô tình đập búa vào ngón tay cái của mình.)","He gave me a [thumb] up to show his approval. (=Dịch: Anh ấy đã giơ ngón tay cái lên để thể hiện sự đồng thuận của mình.)","Babies often soothe themselves by sucking their [thumb]. (=Dịch: Trẻ sơ sinh thường tự trấn an bằng cách mút ngón tay cái.)"],"ukAudio":"/ai_services/tts3/?q=thumb&lang=en-GB&ipa=%2F%CE%B8%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=thumb&lang=en-US&ipa=%2F%CE%B8%CA%8Cm%2F"},{"id":"lv_0_313","topic":"Daily Life and Social Activities","word":"tiger","pos":"(n)","ipa":"/ˈtaɪ.ɡɚ/","defVi":"con hổ","defEn":"a large wild cat that has yellow-orange fur with black stripes","examples":["The Bengal [tiger] is an endangered species in Asia. (=Dịch: Hổ Bengal là một loài có nguy cơ tuyệt chủng ở châu Á.)","We saw a majestic [tiger] resting under the shade of a tree. (=Dịch: Chúng tôi đã nhìn thấy một con hổ oai vệ đang nghỉ ngơi dưới bóng cây.)","Poaching poses a severe threat to wild [tiger] populations. (=Dịch: Nạn săn trộm gây ra mối đe dọa nghiêm trọng đối với các quần thể hổ hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=tiger&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tiger&lang=en-US&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%9A%2F"},{"id":"lv_0_314","topic":"Daily Life and Social Activities","word":"toddler","pos":"(n)","ipa":"/ˈtɑːd.lɚ/","defVi":"trẻ tập đi (từ 1 đến 3 tuổi)","defEn":"a young child who has only recently learned to walk, typically between one and three years old","examples":["The [toddler] took his first steps across the living room. (=Dịch: Đứa trẻ mới biết đi đã chập chững những bước đầu tiên qua phòng khách.)","Parents need to childproof their home once their baby becomes a [toddler]. (=Dịch: Các bậc cha mẹ cần tạo môi trường an toàn cho trẻ trong nhà khi con mình bước vào độ tuổi biết đi.)","She works at a daycare center taking care of active [toddler] groups. (=Dịch: Cô ấy làm việc tại một trung tâm giữ trẻ, chăm sóc các nhóm trẻ mới biết đi hiếu động.)"],"ukAudio":"/ai_services/tts3/?q=toddler&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90d.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=toddler&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90d.l%C9%9A%2F"},{"id":"lv_0_315","topic":"Daily Life and Social Activities","word":"trail","pos":"(n)","ipa":"/treɪl/","defVi":"đường mòn, dấu vết","defEn":"a path through the countryside or a forest, or a series of marks left behind","examples":["They followed a narrow [trail] through the dense forest. (=Dịch: Họ đi theo một con đường mòn hẹp xuyên qua khu rừng rậm rạp.)","The storm left a [trail] of destruction across the coastal town. (=Dịch: Cơn bão đã để lại một vệt tàn phá dài khắp thị trấn ven biển.)","The dog easily tracked the scent [trail] of the missing child. (=Dịch: Chú chó đã dễ dàng lần theo dấu vết mùi hương của đứa trẻ mất tích.)"],"ukAudio":"/ai_services/tts3/?q=trail&lang=en-GB&ipa=%2Ftre%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=trail&lang=en-US&ipa=%2Ftre%C9%AAl%2F"},{"id":"lv_0_316","topic":"Daily Life and Social Activities","word":"trap","pos":"(n)","ipa":"/træp/","defVi":"cái bẫy, cạm bẫy","defEn":"a device or clever plan designed to catch or trick animals or people","examples":["The hunters set a [trap] in the woods to catch rabbits. (=Dịch: Những người thợ săn đã đặt một cái bẫy trong rừng để bắt thỏ.)","He realized too late that he had fallen into a clever [trap]. (=Dịch: Anh ấy nhận ra quá muộn rằng mình đã rơi vào một cái bẫy tinh vi.)","Many consumers fall into the debt [trap] due to high credit card interest. (=Dịch: Nhiều người tiêu dùng rơi vào bẫy nợ nần do lãi suất thẻ tín dụng cao.)"],"ukAudio":"/ai_services/tts3/?q=trap&lang=en-GB&ipa=%2Ftr%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=trap&lang=en-US&ipa=%2Ftr%C3%A6p%2F"},{"id":"lv_0_317","topic":"Daily Life and Social Activities","word":"treasure","pos":"(n)","ipa":"/ˈtreʒ.ɚ/","defVi":"kho báu, của quý, vật quý giá","defEn":"a collection of valuable things such as gold, silver, or jewels, or a highly valued object","examples":["Divers discovered sunken [treasure] in the ancient shipwreck. (=Dịch: Các thợ lặn đã phát hiện ra kho báu bị chìm trong xác con tàu cổ.)","The national museum houses many priceless art [treasure] items. (=Dịch: Bảo tàng quốc gia lưu giữ nhiều hiện vật kho báu nghệ thuật vô giá.)","Historical documents are considered a national [treasure] by historians. (=Dịch: Các tài liệu lịch sử được các nhà sử học coi là báu vật quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=treasure&lang=en-GB&ipa=%2F%CB%88tre%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=treasure&lang=en-US&ipa=%2F%CB%88tre%CA%92.%C9%9A%2F"},{"id":"lv_0_318","topic":"Daily Life and Social Activities","word":"trek","pos":"(n)","ipa":"/trɛk/","defVi":"chuyến đi bộ đường dài vất vả, hành trình gian nan","defEn":"a long, difficult journey, especially one made on foot across rough terrain","examples":["They organized a week-long [trek] through the Himalayan mountains. (=Dịch: Họ đã tổ chức một chuyến đi bộ đường dài kéo dài một tuần qua dãy núi Himalaya.)","Walking to the remote village was an exhausting [trek] in the heat. (=Dịch: Đi bộ đến ngôi làng hẻo lánh là một chuyến đi dài kiệt sức dưới trời nắng nóng.)","He prepared for the difficult [trek] by doing regular endurance training. (=Dịch: Anh ấy đã chuẩn bị cho chuyến đi bộ dài đầy gian nan bằng cách thường xuyên rèn luyện sức bền.)"],"ukAudio":"/ai_services/tts3/?q=trek&lang=en-GB&ipa=%2Ftr%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=trek&lang=en-US&ipa=%2Ftr%C9%9Bk%2F"},{"id":"lv_0_319","topic":"Daily Life and Social Activities","word":"trial","pos":"(n)","ipa":"/ˈtraɪ.əl/","defVi":"phiên tòa xét xử, sự thử nghiệm","defEn":"a formal examination of evidence in court, or a test of performance or quality","examples":["The murder suspect will face [trial] next month. (=Dịch: Nghi phạm giết người sẽ phải hầu tòa vào tháng tới.)","The new cancer drug is currently undergoing clinical [trial] phases. (=Dịch: Loại thuốc điều trị ung thư mới hiện đang trải qua các giai đoạn thử nghiệm lâm sàng.)","The company offered a 30-day free [trial] for its new software. (=Dịch: Công ty đã cung cấp bản dùng thử miễn phí trong 30 ngày cho phần mềm mới của họ.)"],"ukAudio":"/ai_services/tts3/?q=trial&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=trial&lang=en-US&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F"},{"id":"lv_0_320","topic":"Daily Life and Social Activities","word":"tune","pos":"(v)","ipa":"/tuːn/","defVi":"lên dây (đàn), chỉnh âm, điều chỉnh","defEn":"to adjust a musical instrument so that it produces the correct notes, or to adjust a device for better reception or performance","examples":["He spent ten minutes trying to [tune] his acoustic guitar before the concert. (=Dịch: Anh ấy đã dành mười phút để cố gắng chỉnh dây cây đàn guitar acoustic của mình trước buổi hòa nhạc.)","The mechanic will [tune] the engine to improve fuel efficiency. (=Dịch: Người thợ máy sẽ tinh chỉnh động cơ để cải thiện hiệu quả sử dụng nhiên liệu.)","Make sure to [tune] the radio to the local news station. (=Dịch: Hãy chắc chắn rằng bạn đã dò đài radio sang kênh tin tức địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tune&lang=en-GB&ipa=%2Ftu%CB%90n%2F","usAudio":"/ai_services/tts3/?q=tune&lang=en-US&ipa=%2Ftu%CB%90n%2F"},{"id":"lv_0_321","topic":"Daily Life and Social Activities","word":"twelfth","pos":"(adj)","ipa":"/twɛlfθ/","defVi":"thứ mười hai","defEn":"coming next after the eleventh; being number twelve in a sequence","examples":["She celebrated her [twelfth] birthday with a family picnic in the park. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ mười hai của mình bằng một buổi dã ngoại cùng gia đình trong công viên.)","Our office is located on the [twelfth] floor of the commercial building. (=Dịch: Văn phòng của chúng tôi nằm ở tầng mười hai của tòa nhà thương mại.)","December is the [twelfth] and final month of the calendar year. (=Dịch: Tháng Mười Hai là tháng thứ mười hai và cũng là tháng cuối cùng của năm dương lịch.)"],"ukAudio":"/ai_services/tts3/?q=twelfth&lang=en-GB&ipa=%2Ftw%C9%9Blf%CE%B8%2F","usAudio":"/ai_services/tts3/?q=twelfth&lang=en-US&ipa=%2Ftw%C9%9Blf%CE%B8%2F"},{"id":"lv_0_322","topic":"Daily Life and Social Activities","word":"ultimate","pos":"(adj)","ipa":"/ˈʌl.tə.mət/","defVi":"tối hậu, cuối cùng, đỉnh cao","defEn":"happening or coming at the end of a process; final or greatest","examples":["His [ultimate] goal is to start his own software development company. (=Dịch: Mục tiêu cuối cùng của anh ấy là thành lập công ty phát triển phần mềm của riêng mình.)","Climbing Mount Everest remains the [ultimate] challenge for many mountaineers. (=Dịch: Leo đỉnh Everest vẫn là thử thách tột cùng đối với nhiều nhà leo núi.)","The [ultimate] decision rests with the board of directors. (=Dịch: Quyết định cuối cùng thuộc về hội đồng quản trị.)"],"ukAudio":"/ai_services/tts3/?q=ultimate&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=ultimate&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F"},{"id":"lv_0_323","topic":"Daily Life and Social Activities","word":"undergo","pos":"(v)","ipa":"/ˌʌn.dɚˈɡoʊ/","defVi":"trải qua, chịu đựng","defEn":"to experience or suffer something, especially a change, process, or medical procedure","examples":["The historic building will [undergo] extensive renovations next spring. (=Dịch: Tòa nhà lịch sử này sẽ trải qua những đợt trùng tu toàn diện vào mùa xuân tới.)","Patients must [undergo] several medical tests before receiving the surgery. (=Dịch: Bệnh nhân phải trải qua một số xét nghiệm y tế trước khi tiến hành phẫu thuật.)","The company had to [undergo] major restructuring to avoid bankruptcy. (=Dịch: Công ty đã phải trải qua một cuộc tái cấu trúc lớn để tránh phá sản.)"],"ukAudio":"/ai_services/tts3/?q=undergo&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=undergo&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88%C9%A1o%CA%8A%2F"},{"id":"lv_0_324","topic":"Daily Life and Social Activities","word":"unwanted","pos":"(adj)","ipa":"/ʌnˈwɑːn.tɪd/","defVi":"không mong muốn, thừa thãi","defEn":"not desired, needed, or requested","examples":["You can donate [unwanted] clothes to local charity organizations. (=Dịch: Bạn có thể quyên góp quần áo không dùng đến cho các tổ chức từ thiện địa phương.)","The email filter helps block [unwanted] advertisements and spam. (=Dịch: Bộ lọc email giúp chặn các quảng cáo và thư rác không mong muốn.)","She tried to ignore the [unwanted] advice from her distant relatives. (=Dịch: Cô ấy đã cố gắng phớt lờ những lời khuyên không mong muốn từ những người họ hàng xa.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_0_325","topic":"Daily Life and Social Activities","word":"vacancy","pos":"(n)","ipa":"/ˈveɪ.kən.si/","defVi":"vị trí tuyển dụng, chỗ trống","defEn":"a job or position that is available, or an unoccupied room in a hotel","examples":["The company advertised a [vacancy] for an experienced marketing manager. (=Dịch: Công ty đã đăng thông báo tuyển dụng cho một vị trí trống là trưởng phòng tiếp thị giàu kinh nghiệm.)","The motel had a 'No [vacancy]' sign hanging outside the front desk. (=Dịch: Nhà nghỉ treo biển 'Hết phòng' bên ngoài quầy lễ tân.)","We hope to fill the job [vacancy] before the start of next month. (=Dịch: Chúng tôi hy vọng sẽ tuyển được người cho vị trí việc làm còn trống trước đầu tháng tới.)"],"ukAudio":"/ai_services/tts3/?q=vacancy&lang=en-GB&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=vacancy&lang=en-US&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F"},{"id":"lv_0_326","topic":"Daily Life and Social Activities","word":"valid","pos":"(adj)","ipa":"/ˈvæl.ɪd/","defVi":"hợp lệ, có hiệu lực, có cơ sở","defEn":"based on truth, logic, or fact; legally or officially acceptable","examples":["You must present a [valid] passport before boarding the international flight. (=Dịch: Bạn phải xuất trình hộ chiếu hợp lệ trước khi lên chuyến bay quốc tế.)","She raised a [valid] point during the debate about public transport costs. (=Dịch: Cô ấy đã đưa ra một quan điểm xác đáng trong cuộc tranh luận về chi phí giao thông công cộng.)","This discount coupon is only [valid] until the end of the week. (=Dịch: Phiếu giảm giá này chỉ có hiệu lực cho đến cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=valid&lang=en-GB&ipa=%2F%CB%88v%C3%A6l.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=valid&lang=en-US&ipa=%2F%CB%88v%C3%A6l.%C9%AAd%2F"},{"id":"lv_0_327","topic":"Daily Life and Social Activities","word":"vegetarian","pos":"(adj)","ipa":"/ˌvɛdʒ.əˈtɛr.i.ən/","defVi":"chay, ăn chay","defEn":"consisting entirely of plant-based foods, containing no meat or fish","examples":["The restaurant provides a rich [vegetarian] menu for non-meat eaters. (=Dịch: Nhà hàng cung cấp một thực đơn chay phong phú cho những người không ăn thịt.)","She decided to follow a strict [vegetarian] diet for health reasons. (=Dịch: Cô ấy quyết định theo đuổi chế độ ăn chay nghiêm ngặt vì lý do sức khỏe.)","We ordered a delicious [vegetarian] pizza topped with mushrooms and olives. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza chay thơm ngon phủ nấm và ô liu.)"],"ukAudio":"/ai_services/tts3/?q=vegetarian&lang=en-GB&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetarian&lang=en-US&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F"},{"id":"lv_0_328","topic":"Daily Life and Social Activities","word":"venue","pos":"(n)","ipa":"/ˈvɛn.juː/","defVi":"địa điểm tổ chức (sự kiện, hội nghị, biểu diễn)","defEn":"the place where a public event, meeting, or concert takes place","examples":["The new convention center is an ideal [venue] for international conferences. (=Dịch: Trung tâm hội nghị mới là một địa điểm lý tưởng cho các hội nghị quốc tế.)","They are still searching for a suitable wedding [venue] with a nice garden. (=Dịch: Họ vẫn đang tìm kiếm một địa điểm tổ chức đám cưới thích hợp có khu vườn đẹp.)","The stadium was chosen as the [venue] for the upcoming championship match. (=Dịch: Sân vận động đã được chọn làm địa điểm tổ chức trận chung kết sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=venue&lang=en-GB&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F","usAudio":"/ai_services/tts3/?q=venue&lang=en-US&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F"},{"id":"lv_0_329","topic":"Daily Life and Social Activities","word":"verdict","pos":"(n)","ipa":"/ˈvɝː.dɪkt/","defVi":"phán quyết, lời tuyên án, kết luận","defEn":"an official decision made by a jury in court, or an opinion formed after careful consideration","examples":["The jury reached a unanimous [verdict] of guilty after four hours of deliberation. (=Dịch: Bồi thẩm đoàn đã đưa ra phán quyết nhất trí có tội sau bốn giờ nghị án.)","Critics delivered a favorable [verdict] on the director's latest film. (=Dịch: Các nhà phê bình đã đưa ra nhận định ưu ái cho bộ phim mới nhất của đạo diễn.)","The public eagerly awaited the court's final [verdict] on the corruption case. (=Dịch: Công chúng háo hức chờ đợi phán quyết cuối cùng của tòa án về vụ án tham nhũng.)"],"ukAudio":"/ai_services/tts3/?q=verdict&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.d%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=verdict&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.d%C9%AAkt%2F"},{"id":"lv_0_330","topic":"Daily Life and Social Activities","word":"visible","pos":"(adj)","ipa":"/ˈvɪz.ə.bəl/","defVi":"có thể nhìn thấy được, rõ ràng","defEn":"able to be seen or easily noticed","examples":["The stars were clearly [visible] in the night sky. (=Dịch: Những ngôi sao có thể nhìn thấy rõ ràng trên bầu trời đêm.)","There has been a [visible] improvement in her spoken English. (=Dịch: Đã có một sự tiến bộ rõ rệt trong khả năng nói tiếng Anh của cô ấy.)","He wore a brightly colored jacket so he would be [visible] to drivers. (=Dịch: Anh ấy mặc một chiếc áo khoác có màu sắc rực rỡ để các tài xế có thể nhìn thấy mình.)"],"ukAudio":"/ai_services/tts3/?q=visible&lang=en-GB&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=visible&lang=en-US&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F"},{"id":"lv_0_331","topic":"Daily Life and Social Activities","word":"vote","pos":"(n)","ipa":"/voʊt/","defVi":"lá phiếu, sự bỏ phiếu","defEn":"a formal choice made by an individual in an election or meeting","examples":["Every citizen has the right to cast a [vote] in the election. (=Dịch: Mọi công dân đều có quyền bỏ phiếu trong cuộc bầu cử.)","The proposal was passed by a majority [vote]. (=Dịch: Đề xuất đã được thông qua nhờ đa số phiếu bầu.)","The committee decided to take a [vote] on the new policy. (=Dịch: Ủy ban đã quyết định tiến hành bỏ phiếu về chính sách mới.)"],"ukAudio":"/ai_services/tts3/?q=vote&lang=en-GB&ipa=%2Fvo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=vote&lang=en-US&ipa=%2Fvo%CA%8At%2F"},{"id":"lv_0_332","topic":"Daily Life and Social Activities","word":"waitress","pos":"(n)","ipa":"/ˈweɪ.trəs/","defVi":"nữ bồi bàn, nữ phục vụ","defEn":"a woman whose job is to serve food and drinks to customers in a restaurant","examples":["The [waitress] brought us our drinks and took our food order. (=Dịch: Người phục vụ nữ đã mang đồ uống cho chúng tôi và ghi lại các món ăn được gọi.)","She worked as a [waitress] during college to pay for tuition. (=Dịch: Cô ấy đã làm phục vụ bàn trong thời gian học đại học để chi trả học phí.)","We left a generous tip for our friendly [waitress]. (=Dịch: Chúng tôi đã để lại một khoản tiền boa hậu hĩnh cho cô phục vụ thân thiện.)"],"ukAudio":"/ai_services/tts3/?q=waitress&lang=en-GB&ipa=%2F%CB%88we%C9%AA.tr%C9%99s%2F","usAudio":"/ai_services/tts3/?q=waitress&lang=en-US&ipa=%2F%CB%88we%C9%AA.tr%C9%99s%2F"},{"id":"lv_0_333","topic":"Daily Life and Social Activities","word":"walker","pos":"(n)","ipa":"/ˈwɑː.kɚ/","defVi":"người đi bộ; khung tập đi","defEn":"a person who walks, or a frame designed to assist someone in walking","examples":["The national park is very popular with every keen [walker]. (=Dịch: Công viên quốc gia này rất được những người đam mê đi bộ yêu thích.)","After his hip surgery, he needed a [walker] to move around. (=Dịch: Sau ca phẫu thuật khớp hông, ông ấy cần một khung tập đi để di chuyển.)","Drivers must always remain alert and yield to any [walker] at the crosswalk. (=Dịch: Người lái xe phải luôn tỉnh táo và nhường đường cho bất kỳ người đi bộ nào tại vạch qua đường.)"],"ukAudio":"/ai_services/tts3/?q=walker&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=walker&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.k%C9%9A%2F"},{"id":"lv_0_334","topic":"Daily Life and Social Activities","word":"wallet","pos":"(n)","ipa":"/ˈwɑː.lɪt/","defVi":"ví tiền (thường là ví nam, ví gập)","defEn":"a small, flat folding case used for carrying money and plastic cards","examples":["He realized that he had left his [wallet] at home. (=Dịch: Anh ấy nhận ra rằng mình đã để quên ví ở nhà.)","She kept a family photo inside her leather [wallet]. (=Dịch: Cô ấy giữ một bức ảnh gia đình bên trong chiếc ví da của mình.)","A kind stranger found my lost [wallet] and returned it. (=Dịch: Một người lạ tốt bụng đã tìm thấy chiếc ví bị mất của tôi và trả lại.)"],"ukAudio":"/ai_services/tts3/?q=wallet&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.l%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=wallet&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.l%C9%AAt%2F"},{"id":"lv_0_335","topic":"Daily Life and Social Activities","word":"warden","pos":"(n)","ipa":"/ˈwɔːr.dən/","defVi":"người giám sát, người coi sóc, quản lý","defEn":"an official who is responsible for supervising a particular place or enforcing regulations","examples":["The park [warden] warned the hikers about recent bear sightings. (=Dịch: Người quản lý công viên đã cảnh báo những người đi bộ đường dài về việc gần đây có người nhìn thấy gấu.)","The traffic [warden] issued a ticket for illegal parking. (=Dịch: Nhân viên kiểm soát giao thông đã phạt một vé vì lỗi đỗ xe trái phép.)","Each residential hall has a [warden] to look after the students' safety. (=Dịch: Mỗi khu ký túc xá đều có một người quản lý để đảm bảo an toàn cho sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=warden&lang=en-GB&ipa=%2F%CB%88w%C9%94%CB%90r.d%C9%99n%2F","usAudio":"/ai_services/tts3/?q=warden&lang=en-US&ipa=%2F%CB%88w%C9%94%CB%90r.d%C9%99n%2F"},{"id":"lv_0_336","topic":"Daily Life and Social Activities","word":"watercolour","pos":"(n)","ipa":"/ˈwɑː.t̬ɚˌkʌl.ɚ/","defVi":"tranh màu nước, màu nước","defEn":"a type of paint mixed with water, or a picture painted with this medium","examples":["She created a delicate landscape painting using [watercolour]. (=Dịch: Cô ấy đã tạo ra một bức tranh phong cảnh tinh tế bằng màu nước.)","The museum exhibited a rare collection of Victorian [watercolour] paintings. (=Dịch: Bảo tàng đã trưng bày một bộ sưu tập tranh màu nước thời Victoria quý hiếm.)","Learning how to paint in [watercolour] requires a great deal of patience. (=Dịch: Học cách vẽ bằng màu nước đòi hỏi sự kiên nhẫn rất lớn.)"],"ukAudio":"/ai_services/tts3/?q=watercolour&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A%CB%8Ck%CA%8Cl.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=watercolour&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A%CB%8Ck%CA%8Cl.%C9%9A%2F"},{"id":"lv_0_337","topic":"Daily Life and Social Activities","word":"waterfall","pos":"(n)","ipa":"/ˈwɑː.t̬ɚ.fɑːl/","defVi":"thác nước","defEn":"a cascade of water falling from a height, formed when a stream flows over a precipice","examples":["The tourists gathered to take photos of the majestic [waterfall]. (=Dịch: Các du khách tụ tập để chụp ảnh thác nước hùng vĩ.)","You can hear the roaring sound of the [waterfall] from a mile away. (=Dịch: Bạn có thể nghe thấy tiếng gầm vang của thác nước từ cách xa một dặm.)","A small wooden bridge was built right above the natural [waterfall]. (=Dịch: Một cây cầu gỗ nhỏ đã được xây dựng ngay phía trên thác nước tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=waterfall&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.f%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=waterfall&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.f%C9%91%CB%90l%2F"},{"id":"lv_0_338","topic":"Daily Life and Social Activities","word":"waterproof","pos":"(adj)","ipa":"/ˈwɑː.t̬ɚ.pruːf/","defVi":"chống thấm nước","defEn":"not allowing water to pass through","examples":["Make sure to pack a [waterproof] jacket in case it rains during the hike. (=Dịch: Hãy chắc chắn mang theo một chiếc áo khoác chống nước phòng trường hợp trời mưa trong chuyến đi bộ đường dài.)","This modern smartwatch is completely [waterproof] up to fifty meters. (=Dịch: Chiếc đồng hồ thông minh hiện đại này có khả năng chống nước hoàn toàn ở độ sâu lên đến 50 mét.)","We used a heavy [waterproof] tarp to protect our camping gear. (=Dịch: Chúng tôi đã dùng một tấm bạt chống nước dày để bảo vệ đồ cắm trại của mình.)"],"ukAudio":"/ai_services/tts3/?q=waterproof&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.pru%CB%90f%2F","usAudio":"/ai_services/tts3/?q=waterproof&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.pru%CB%90f%2F"},{"id":"lv_0_339","topic":"Daily Life and Social Activities","word":"weekday","pos":"(n)","ipa":"/ˈwiːk.deɪ/","defVi":"ngày trong tuần (từ thứ Hai đến thứ Sáu)","defEn":"any day of the week except Saturday and Sunday","examples":["The library is much less crowded on a [weekday] morning. (=Dịch: Thư viện vắng người hơn nhiều vào buổi sáng các ngày trong tuần.)","She usually commutes to the office by train every [weekday]. (=Dịch: Cô ấy thường đi làm bằng tàu hỏa vào mỗi ngày trong tuần.)","The hotel charges lower room rates during the [weekday] than on weekends. (=Dịch: Khách sạn tính giá phòng vào ngày trong tuần thấp hơn so với cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=weekday&lang=en-GB&ipa=%2F%CB%88wi%CB%90k.de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weekday&lang=en-US&ipa=%2F%CB%88wi%CB%90k.de%C9%AA%2F"},{"id":"lv_0_340","topic":"Daily Life and Social Activities","word":"weekly","pos":"(adj)","ipa":"/ˈwik.li/","defVi":"hàng tuần","defEn":"happening, done, or published once every week","examples":["We hold a [weekly] staff meeting every Monday morning. (=Dịch: Chúng tôi tổ chức một cuộc họp nhân viên hàng tuần vào mỗi sáng thứ Hai.)","He writes a column for a [weekly] magazine. (=Dịch: Anh ấy viết một chuyên mục cho một tạp chí hàng tuần.)","The school charges a [weekly] fee for after-school activities. (=Dịch: Trường thu một khoản phí hàng tuần cho các hoạt động sau giờ học.)"],"ukAudio":"/ai_services/tts3/?q=weekly&lang=en-GB&ipa=%2F%CB%88wik.li%2F","usAudio":"/ai_services/tts3/?q=weekly&lang=en-US&ipa=%2F%CB%88wik.li%2F"},{"id":"lv_0_341","topic":"Daily Life and Social Activities","word":"willow","pos":"(n)","ipa":"/ˈwɪl.oʊ/","defVi":"cây liễu","defEn":"a tree with long, thin branches and narrow leaves that often grows near water","examples":["A weeping [willow] stood gracefully near the edge of the pond. (=Dịch: Một cây liễu rủ đứng duyên dáng gần bờ ao.)","The birds built their nest among the branches of an old [willow]. (=Dịch: Những chú chim đã làm tổ giữa các cành của một cây liễu già.)","We sat in the cool shade of a [willow] to escape the midday heat. (=Dịch: Chúng tôi ngồi dưới bóng râm mát rượi của một cây liễu để tránh cái nóng ban trưa.)"],"ukAudio":"/ai_services/tts3/?q=willow&lang=en-GB&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=willow&lang=en-US&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F"},{"id":"lv_0_342","topic":"Daily Life and Social Activities","word":"yoga","pos":"(n)","ipa":"/ˈjoʊ.ɡə/","defVi":"bộ môn yoga","defEn":"a set of physical exercises and breathing techniques used for relaxation and health","examples":["She practices [yoga] every morning to reduce stress and stay flexible. (=Dịch: Cô ấy tập yoga mỗi sáng để giảm căng thẳng và duy trì sự dẻo dai.)","The community center offers [yoga] classes for beginners. (=Dịch: Trung tâm cộng đồng mở các lớp học yoga dành cho người mới bắt đầu.)","Many doctors recommend [yoga] as a gentle form of exercise. (=Dịch: Nhiều bác sĩ khuyên nên tập yoga như một hình thức thể dục nhẹ nhàng.)"],"ukAudio":"/ai_services/tts3/?q=yoga&lang=en-GB&ipa=%2F%CB%88jo%CA%8A.%C9%A1%C9%99%2F","usAudio":"/ai_services/tts3/?q=yoga&lang=en-US&ipa=%2F%CB%88jo%CA%8A.%C9%A1%C9%99%2F"},{"id":"lv_0_343","topic":"Daily Life and Social Activities","word":"youth","pos":"(n)","ipa":"/juθ/","defVi":"tuổi trẻ, thời thanh xuân; giới trẻ","defEn":"the time of life when a person is young, especially the period between childhood and adulthood","examples":["He spent most of his [youth] traveling around the world. (=Dịch: Anh ấy đã dành phần lớn thời tuổi trẻ của mình để đi du lịch khắp thế giới.)","The program aims to inspire local [youth] to pursue higher education. (=Dịch: Chương trình nhằm truyền cảm hứng cho giới trẻ địa phương theo đuổi con đường học vấn cao hơn.)","She maintained her energy and optimism well beyond her [youth]. (=Dịch: Bà vẫn duy trì được năng lượng và sự lạc quan của mình ngay cả khi thời tuổi trẻ đã qua đi rất lâu.)"],"ukAudio":"/ai_services/tts3/?q=youth&lang=en-GB&ipa=%2Fju%CE%B8%2F","usAudio":"/ai_services/tts3/?q=youth&lang=en-US&ipa=%2Fju%CE%B8%2F"},{"id":"lv_1_0","topic":"Job Seeking and Work","word":"acquisition","pos":"(n)","ipa":"/ˌæk.wəˈzɪʃ.ən/","defVi":"sự mua lại (công ty), sự tiếp thu hoặc tích lũy","defEn":"the act of getting something, or buying another company","examples":["Language [acquisition] is much easier for young children than for adults. (=Dịch: Việc tiếp thu ngôn ngữ đối với trẻ nhỏ dễ dàng hơn nhiều so với người lớn.)","The tech giant announced the [acquisition] of a smaller startup yesterday. (=Dịch: Gã khổng lồ công nghệ đã công bố thương vụ mua lại một công ty khởi nghiệp nhỏ hơn vào ngày hôm qua.)","The museum's latest [acquisition] is a rare painting from the nineteenth century. (=Dịch: Hiện vật mới nhất mà bảo tàng mua lại được là một bức tranh hiếm từ thế kỷ mười chín.)"],"ukAudio":"/ai_services/tts3/?q=acquisition&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.w%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=acquisition&lang=en-US&ipa=%2F%CB%8C%C3%A6k.w%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_1","topic":"Job Seeking and Work","word":"admin","pos":"(n)","ipa":"/ˈæd.mɪn/","defVi":"công việc hành chính, ban quản trị/nhân viên hành chính","defEn":"administrative work, or the person or department responsible for managing it","examples":["I spent the entire morning dealing with paperwork and routine [admin]. (=Dịch: Tôi đã dành cả buổi sáng để giải quyết giấy tờ và công việc hành chính thường ngày.)","If you cannot log into your account, please contact the system [admin]. (=Dịch: Nếu bạn không thể đăng nhập vào tài khoản của mình, vui lòng liên hệ với quản trị viên hệ thống.)","The company hired a new assistant to help reduce the heavy [admin] workload. (=Dịch: Công ty đã thuê một trợ lý mới để giúp giảm bớt khối lượng công việc hành chính nặng nề.)"],"ukAudio":"/ai_services/tts3/?q=admin&lang=en-GB&ipa=%2F%CB%88%C3%A6d.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=admin&lang=en-US&ipa=%2F%CB%88%C3%A6d.m%C9%AAn%2F"},{"id":"lv_1_2","topic":"Job Seeking and Work","word":"administration","pos":"(n)","ipa":"/ədˌmɪn.əˈstreɪ.ʃən/","defVi":"sự quản lý, bộ máy hành chính","defEn":"the management and organization of a business, institution, or government","examples":["She has spent many years working in university [administration]. (=Dịch: Cô ấy đã dành nhiều năm làm việc trong bộ phận quản trị của trường đại học.)","The new [administration] announced major tax reforms today. (=Dịch: Chính quyền mới đã công bố các cải cách thuế quan trọng vào ngày hôm nay.)","Inefficient [administration] led to massive delays in processing applications. (=Dịch: Công tác quản lý kém hiệu quả đã dẫn đến sự chậm trễ nghiêm trọng trong việc xử lý hồ sơ.)"],"ukAudio":"/ai_services/tts3/?q=administration&lang=en-GB&ipa=%2F%C9%99d%CB%8Cm%C9%AAn.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=administration&lang=en-US&ipa=%2F%C9%99d%CB%8Cm%C9%AAn.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_3","topic":"Job Seeking and Work","word":"administrative","pos":"(adj)","ipa":"/ədˈmɪn.ə.strə.tɪv/","defVi":"thuộc về hành chính, quản trị","defEn":"relating to the arrangement and management of an organization or business","examples":["The university is cutting down on its [administrative] costs. (=Dịch: Trường đại học đang cắt giảm các chi phí hành chính.)","She manages all the [administrative] duties for the department. (=Dịch: Cô ấy quản lý tất cả các nhiệm vụ hành chính cho bộ phận.)","He spent the morning dealing with routine [administrative] paperwork. (=Dịch: Anh ấy đã dành cả buổi sáng để xử lý các thủ tục giấy tờ hành chính thường nhật.)"],"ukAudio":"/ai_services/tts3/?q=administrative&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.str%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=administrative&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.str%C9%99.t%C9%AAv%2F"},{"id":"lv_1_4","topic":"Job Seeking and Work","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"tham vọng, giàu hoài bão","defEn":"having a strong desire to be successful, powerful, or rich","examples":["The firm announced an [ambitious] plan to cut carbon emissions by half within five years. (=Dịch: Công ty đã công bố một kế hoạch đầy tham vọng nhằm cắt giảm một nửa lượng khí thải carbon trong vòng 5 năm.)","He is an [ambitious] young lawyer who hopes to become a partner at the firm soon. (=Dịch: Anh ấy là một luật sư trẻ đầy tham vọng, người hy vọng sẽ sớm trở thành thành viên góp vốn của công ty luật.)","Setting [ambitious] goals can inspire team members to push beyond their ordinary limits. (=Dịch: Việc đặt ra những mục tiêu đầy tham vọng có thể truyền cảm hứng cho các thành viên trong nhóm vượt qua những giới hạn thông thường.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_1_5","topic":"Job Seeking and Work","word":"applicant","pos":"(n)","ipa":"/ˈæp.lə.kənt/","defVi":"ứng viên, người nộp đơn","defEn":"a person who officially applies for a job, place at university, or legal status","examples":["Each [applicant] must submit a detailed CV and two reference letters. (=Dịch: Mỗi ứng viên phải nộp một bản CV chi tiết và hai thư giới thiệu.)","The company chose the best [applicant] after several rounds of interviews. (=Dịch: Công ty đã chọn ứng viên xuất sắc nhất sau nhiều vòng phỏng vấn.)","The scholarship is open to any [applicant] with excellent academic records. (=Dịch: Học bổng này dành cho bất kỳ ứng viên nào có thành tích học tập xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=applicant&lang=en-GB&ipa=%2F%CB%88%C3%A6p.l%C9%99.k%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=applicant&lang=en-US&ipa=%2F%CB%88%C3%A6p.l%C9%99.k%C9%99nt%2F"},{"id":"lv_1_6","topic":"Job Seeking and Work","word":"apprentice","pos":"(n)","ipa":"/əˈpren.tɪs/","defVi":"người học việc, thực tập sinh nghề","defEn":"a person who learns a job or skill by working under a skilled employer for a fixed period","examples":["He started working as an [apprentice] electrician at the age of eighteen. (=Dịch: Anh ấy bắt đầu làm thợ điện học việc vào năm mười tám tuổi.)","The master craftsman shared his traditional techniques with each [apprentice]. (=Dịch: Người thợ thủ công bậc thầy đã chia sẻ các kỹ thuật truyền thống của mình với từng người học việc.)","She joined the company through a modern [apprentice] scheme. (=Dịch: Cô ấy gia nhập công ty thông qua một chương trình học nghề hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=apprentice&lang=en-GB&ipa=%2F%C9%99%CB%88pren.t%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=apprentice&lang=en-US&ipa=%2F%C9%99%CB%88pren.t%C9%AAs%2F"},{"id":"lv_1_7","topic":"Job Seeking and Work","word":"apprenticeship","pos":"(n)","ipa":"/əˈpren.tɪs.ʃɪp/","defVi":"thời gian học nghề, sự học việc","defEn":"a period of time working for an employer to learn a practical skill or trade","examples":["He completed a three-year [apprenticeship] with an experienced master electrician. (=Dịch: Anh ấy đã hoàn thành chương trình học nghề kéo dài ba năm với một thợ điện bậc thầy giàu kinh nghiệm.)","Many young people choose an [apprenticeship] rather than attending university. (=Dịch: Nhiều người trẻ chọn học nghề thay vì vào đại học.)","The vocational program offers paid [apprenticeship] opportunities in the culinary industry. (=Dịch: Chương trình dạy nghề mang lại các cơ hội học việc có hưởng lương trong ngành ẩm thực.)"],"ukAudio":"/ai_services/tts3/?q=apprenticeship&lang=en-GB&ipa=%2F%C9%99%CB%88pren.t%C9%AAs.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=apprenticeship&lang=en-US&ipa=%2F%C9%99%CB%88pren.t%C9%AAs.%CA%83%C9%AAp%2F"},{"id":"lv_1_8","topic":"Job Seeking and Work","word":"artistic","pos":"(adj)","ipa":"/ɑːrˈtɪs.tɪk/","defVi":"thuộc nghệ thuật, có khiếu nghệ thuật","defEn":"relating to art or having natural skill in creating art","examples":["She showed great [artistic] talent from a very young age. (=Dịch: Cô ấy đã bộc lộ tài năng nghệ thuật tuyệt vời từ khi còn rất nhỏ.)","The director has a distinct [artistic] vision that makes his movies unique. (=Dịch: Đạo diễn có một tầm nhìn nghệ thuật khác biệt khiến các bộ phim của ông trở nên độc đáo.)","Students are encouraged to express their [artistic] creativity through painting and sculpture. (=Dịch: Học sinh được khuyến khích thể hiện sự sáng tạo nghệ thuật của mình thông qua hội họa và điêu khắc.)"],"ukAudio":"/ai_services/tts3/?q=artistic&lang=en-GB&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=artistic&lang=en-US&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F"},{"id":"lv_1_9","topic":"Job Seeking and Work","word":"assign","pos":"(v)","ipa":"/əˈsaɪn/","defVi":"phân công, giao phó, chỉ định","defEn":"to give someone a particular job, task, or duty","examples":["The teacher will [assign] a different reading project to each group. (=Dịch: Giáo viên sẽ giao một dự án đọc khác nhau cho mỗi nhóm.)","Management decided to [assign] the new project to their most experienced engineer. (=Dịch: Ban quản lý đã quyết định giao dự án mới cho kỹ sư giàu kinh nghiệm nhất của họ.)","Each volunteer was [assign]ed a specific role during the community event. (=Dịch: Mỗi tình nguyện viên được phân công một vai trò cụ thể trong suốt sự kiện cộng đồng.)"],"ukAudio":"/ai_services/tts3/?q=assign&lang=en-GB&ipa=%2F%C9%99%CB%88sa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=assign&lang=en-US&ipa=%2F%C9%99%CB%88sa%C9%AAn%2F"},{"id":"lv_1_10","topic":"Job Seeking and Work","word":"auditorium","pos":"(n)","ipa":"/ˌɑː.dəˈtɔːr.i.əm/","defVi":"khán phòng, hội trường","defEn":"a large room or building used for meetings, concerts, or lectures","examples":["The university [auditorium] was packed with students for the guest lecture. (=Dịch: Hội trường của trường đại học chật kín sinh viên đến nghe bài giảng của khách mời.)","The school musical will be performed in the main [auditorium] tonight. (=Dịch: Vở nhạc kịch của trường sẽ được biểu diễn tại khán phòng chính vào tối nay.)","Please proceed to the [auditorium] for the opening ceremony. (=Dịch: Xin vui lòng di chuyển đến khán phòng để tham dự lễ khai mạc.)"],"ukAudio":"/ai_services/tts3/?q=auditorium&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=auditorium&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F"},{"id":"lv_1_11","topic":"Job Seeking and Work","word":"backstage","pos":"(adv)","ipa":"/ˌbækˈsteɪdʒ/","defVi":"ở hậu trường, ở phía sau sân khấu","defEn":"in the area behind the stage in a theater, not visible to the audience","examples":["The actors waited nervously [backstage] before their cues to enter. (=Dịch: Các diễn viên hồi hộp chờ đợi ở hậu trường trước khi đến lượt bước ra sân khấu.)","Only authorized crew members are allowed to go [backstage]. (=Dịch: Chỉ những thành viên có thẩm quyền trong đoàn mới được phép vào hậu trường.)","She worked [backstage] managing the lighting and sound equipment during the show. (=Dịch: Cô ấy làm việc ở hậu trường để quản lý thiết bị âm thanh và ánh sáng trong suốt buổi biểu diễn.)"],"ukAudio":"/ai_services/tts3/?q=backstage&lang=en-GB&ipa=%2F%CB%8Cb%C3%A6k%CB%88ste%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=backstage&lang=en-US&ipa=%2F%CB%8Cb%C3%A6k%CB%88ste%C9%AAd%CA%92%2F"},{"id":"lv_1_12","topic":"Job Seeking and Work","word":"bakery","pos":"(n)","ipa":"/ˈbeɪ.kə.ri/","defVi":"tiệm bánh, lò bánh mì","defEn":"a place where bread, cakes, and other baked goods are made or sold","examples":["The sweet smell of fresh bread led us straight to the local [bakery]. (=Dịch: Mùi thơm ngọt ngào của bánh mì mới nướng đã dẫn chúng tôi đến thẳng tiệm bánh địa phương.)","She works early morning shifts at a family-owned [bakery]. (=Dịch: Cô ấy làm ca sáng sớm tại một tiệm bánh của gia đình.)","They bought a box of chocolate pastries from the corner [bakery]. (=Dịch: Họ đã mua một hộp bánh ngọt sô-cô-la từ tiệm bánh ở góc phố.)"],"ukAudio":"/ai_services/tts3/?q=bakery&lang=en-GB&ipa=%2F%CB%88be%C9%AA.k%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=bakery&lang=en-US&ipa=%2F%CB%88be%C9%AA.k%C9%99.ri%2F"},{"id":"lv_1_13","topic":"Job Seeking and Work","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh, gian/khoang riêng biệt","defEn":"a body of water partially enclosed by land, or a designated alcove/compartment","examples":["The fishing boats returned safely to the quiet [bay] before the storm hit. (=Dịch: Các thuyền đánh cá đã quay trở lại vịnh yên tĩnh an toàn trước khi cơn bão đổ bộ.)","Our hotel room offered a stunning view over the entire [bay]. (=Dịch: Phòng khách sạn của chúng tôi có tầm nhìn tuyệt đẹp ra toàn bộ vịnh.)","The mechanic drove the car into the service [bay] for an oil change. (=Dịch: Người thợ máy đã lái xe vào khoang bảo dưỡng để thay dầu.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_1_14","topic":"Job Seeking and Work","word":"boardroom","pos":"(n)","ipa":"/ˈbɔːrd.ruːm/","defVi":"phòng họp ban giám đốc, phòng họp hội đồng quản trị","defEn":"a room where the directors of a company hold their official meetings","examples":["The executives met in the [boardroom] to discuss the annual financial report. (=Dịch: Các giám đốc điều hành đã họp trong phòng họp hội đồng quản trị để thảo luận về báo cáo tài chính hàng năm.)","He gave a convincing presentation to the investors inside the [boardroom]. (=Dịch: Anh ấy đã có một bài thuyết trình đầy thuyết phục trước các nhà đầu tư bên trong phòng họp ban giám đốc.)","Important strategic decisions are usually made behind the closed doors of the [boardroom]. (=Dịch: Những quyết định chiến lược quan trọng thường được đưa ra sau những cánh cửa đóng kín của phòng họp hội đồng quản trị.)"],"ukAudio":"/ai_services/tts3/?q=boardroom&lang=en-GB&ipa=%2F%CB%88b%C9%94%CB%90rd.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=boardroom&lang=en-US&ipa=%2F%CB%88b%C9%94%CB%90rd.ru%CB%90m%2F"},{"id":"lv_1_15","topic":"Job Seeking and Work","word":"booklet","pos":"(n)","ipa":"/ˈbʊk.lət/","defVi":"cuốn sách nhỏ, tập tài liệu mỏng","defEn":"a small, thin book with paper covers that contains information about a specific topic","examples":["The tourist center distributes a free [booklet] featuring local attractions. (=Dịch: Trung tâm du lịch phát miễn phí một cuốn sách nhỏ giới thiệu các điểm tham quan địa phương.)","Read the instruction [booklet] carefully before operating the device. (=Dịch: Hãy đọc kỹ cuốn sách hướng dẫn nhỏ trước khi vận hành thiết bị.)","The university prepared an informative [booklet] for incoming students. (=Dịch: Trường đại học đã chuẩn bị một cuốn sổ tay nhiều thông tin bổ ích cho tân sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=booklet&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=booklet&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.l%C9%99t%2F"},{"id":"lv_1_16","topic":"Job Seeking and Work","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, nhà sách","defEn":"a shop that sells books","examples":["He spent hours browsing through old novels in the secondhand [bookshop]. (=Dịch: Anh ấy đã dành hàng giờ lướt xem những cuốn tiểu thuyết cũ trong hiệu sách cũ.)","A new independent [bookshop] just opened near the university campus. (=Dịch: Một hiệu sách độc lập mới vừa mở gần khuôn viên trường đại học.)","You can purchase the recommended course material at the campus [bookshop]. (=Dịch: Bạn có thể mua tài liệu học tập được khuyến nghị tại hiệu sách của trường.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_1_17","topic":"Job Seeking and Work","word":"brochure","pos":"(n)","ipa":"/broʊˈʃʊr/","defVi":"tờ gấp giới thiệu, tập tài liệu quảng cáo","defEn":"a small booklet containing pictures and information about a product or service","examples":["The travel agency handed out a colorful [brochure] about tours in Europe. (=Dịch: Công ty du lịch đã phát một cuốn tài liệu quảng cáo đầy màu sắc về các chuyến du lịch ở châu Âu.)","You can find full details of the university courses in this [brochure]. (=Dịch: Bạn có thể tìm thấy thông tin chi tiết đầy đủ về các khóa học đại học trong cuốn tài liệu giới thiệu này.)","We picked up a museum [brochure] at the entrance desk. (=Dịch: Chúng tôi đã lấy một cuốn tài liệu giới thiệu bảo tàng ở quầy lối vào.)"],"ukAudio":"/ai_services/tts3/?q=brochure&lang=en-GB&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=brochure&lang=en-US&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_1_18","topic":"Job Seeking and Work","word":"buffet","pos":"(n)","ipa":"/bəˈfeɪ/","defVi":"bữa ăn tự chọn, tiệc đứng (buffet)","defEn":"a meal where people serve themselves from a table containing various dishes","examples":["The hotel offers a breakfast [buffet] with both hot and cold options. (=Dịch: Khách sạn phục vụ tiệc buffet bữa sáng với cả các món nóng và lạnh.)","We decided to have a seafood [buffet] for our anniversary dinner. (=Dịch: Chúng tôi quyết định ăn tiệc buffet hải sản cho bữa tối kỷ niệm ngày cưới.)","Guests can choose whatever they like from the dessert [buffet]. (=Dịch: Khách có thể chọn bất kỳ món nào họ thích từ quầy buffet tráng miệng.)"],"ukAudio":"/ai_services/tts3/?q=buffet&lang=en-GB&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=buffet&lang=en-US&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F"},{"id":"lv_1_19","topic":"Job Seeking and Work","word":"buyer","pos":"(n)","ipa":"/ˈbaɪ.ər/","defVi":"người mua hàng, nhân viên thu mua","defEn":"a person who buys goods or services, or someone employed by a company to choose and purchase stock","examples":["The real estate agent finally found a serious [buyer] for the luxury villa. (=Dịch: Môi giới bất động sản cuối cùng đã tìm được một người mua nghiêm túc cho căn biệt thự sang trọng.)","She works as a fashion [buyer] for a major department store chain. (=Dịch: Cô ấy làm nhân viên thu mua thời trang cho một chuỗi cửa hàng bách hóa lớn.)","Potential [buyer] interest increased significantly after the price was reduced. (=Dịch: Sự quan tâm của người mua tiềm năng đã tăng lên đáng kể sau khi giá được giảm.)"],"ukAudio":"/ai_services/tts3/?q=buyer&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=buyer&lang=en-US&ipa=%2F%CB%88ba%C9%AA.%C9%99r%2F"},{"id":"lv_1_20","topic":"Job Seeking and Work","word":"cancel","pos":"(v)","ipa":"/ˈkæn.səl/","defVi":"hủy bỏ","defEn":"to decide that an organized event or agreement will not happen","examples":["They had to [cancel] the flight due to severe weather conditions. (=Dịch: Họ đã phải hủy chuyến bay do điều kiện thời tiết khắc nghiệt.)","You can [cancel] your subscription at any time without extra fees. (=Dịch: Bạn có thể hủy gói đăng ký bất cứ lúc nào mà không mất thêm phí.)","The school decided to [cancel] all outdoor sports events for the day. (=Dịch: Nhà trường quyết định hủy toàn bộ các sự kiện thể thao ngoài trời trong ngày.)"],"ukAudio":"/ai_services/tts3/?q=cancel&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cancel&lang=en-US&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F"},{"id":"lv_1_21","topic":"Job Seeking and Work","word":"candidate","pos":"(n)","ipa":"/ˈkæn.də.dət/","defVi":"ứng viên, người dự tuyển","defEn":"a person who applies for a job or competes in an election","examples":["She was considered the most qualified [candidate] for the marketing manager position. (=Dịch: Cô ấy được xem là ứng viên có đủ năng lực nhất cho vị trí trưởng phòng tiếp thị.)","Each [candidate] must undergo two rounds of interviews before being hired. (=Dịch: Mỗi ứng viên phải trải qua hai vòng phỏng vấn trước khi được tuyển dụng.)","The political [candidate] gave a compelling speech to win over undecided voters. (=Dịch: Ứng cử viên chính trị đã có một bài phát biểu thuyết phục để thu hút những cử tri còn chưa quyết định.)"],"ukAudio":"/ai_services/tts3/?q=candidate&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.d%C9%99.d%C9%99t%2F","usAudio":"/ai_services/tts3/?q=candidate&lang=en-US&ipa=%2F%CB%88k%C3%A6n.d%C9%99.d%C9%99t%2F"},{"id":"lv_1_22","topic":"Job Seeking and Work","word":"casual","pos":"(adj)","ipa":"/ˈkæʒ.u.əl/","defVi":"bình thường, thoải mái, không trang trọng","defEn":"relaxed, informal, or not planned in advance","examples":["Employees are permitted to wear [casual] clothes on Fridays. (=Dịch: Nhân viên được phép mặc trang phục thường ngày vào các ngày thứ Sáu.)","We had a [casual] conversation over coffee about our weekend plans. (=Dịch: Chúng tôi đã có một cuộc trò chuyện thoải mái bên tách cà phê về các kế hoạch cuối tuần.)","He made a [casual] remark that unexpectedly inspired a whole new project. (=Dịch: Anh ấy đã đưa ra một lời nhận xét bâng quơ nhưng lại bất ngờ truyền cảm hứng cho cả một dự án hoàn toàn mới.)"],"ukAudio":"/ai_services/tts3/?q=casual&lang=en-GB&ipa=%2F%CB%88k%C3%A6%CA%92.u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=casual&lang=en-US&ipa=%2F%CB%88k%C3%A6%CA%92.u.%C9%99l%2F"},{"id":"lv_1_23","topic":"Job Seeking and Work","word":"cautious","pos":"(adj)","ipa":"/ˈkɑː.ʃəs/","defVi":"thận trọng, cẩn trọng","defEn":"careful to avoid potential problems or dangers","examples":["Investors are advised to be [cautious] when trading in volatile stock markets. (=Dịch: Các nhà đầu tư được khuyên nên thận trọng khi giao dịch trên các thị trường chứng khoán nhiều biến động.)","He took a [cautious] approach and verified every single piece of data before publishing. (=Dịch: Anh ấy đã áp dụng một cách tiếp cận thận trọng và xác minh từng dữ liệu một trước khi công bố.)","The driver was extremely [cautious] on the icy mountain roads. (=Dịch: Người tài xế đã cực kỳ cẩn thận khi lái xe trên những con đường núi đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=cautious&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=cautious&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.%CA%83%C9%99s%2F"},{"id":"lv_1_24","topic":"Job Seeking and Work","word":"certificate","pos":"(n)","ipa":"/sɚˈtɪf.ə.kət/","defVi":"chứng chỉ, giấy chứng nhận","defEn":"an official document that states facts or achievements","examples":["She received a [certificate] in project management after completing the course. (=Dịch: Cô ấy đã nhận được chứng chỉ quản lý dự án sau khi hoàn thành khóa học.)","You must present a medical [certificate] to explain your absence. (=Dịch: Bạn phải xuất trình giấy chứng nhận y tế để giải thích cho sự vắng mặt của mình.)","The school issues a graduation [certificate] to all qualifying students. (=Dịch: Nhà trường cấp giấy chứng nhận tốt nghiệp cho tất cả học sinh đủ điều kiện.)"],"ukAudio":"/ai_services/tts3/?q=certificate&lang=en-GB&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F","usAudio":"/ai_services/tts3/?q=certificate&lang=en-US&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F"},{"id":"lv_1_25","topic":"Job Seeking and Work","word":"checking","pos":"(n)","ipa":"/ˈtʃek.ɪŋ/","defVi":"việc kiểm tra, sự rà soát, đối chiếu","defEn":"the act of inspecting, examining, or verifying something","examples":["Careful [checking] of the financial documents helped reveal the error. (=Dịch: Việc kiểm tra cẩn thận các tài liệu tài chính đã giúp phát hiện ra sai sót.)","The airport instituted stricter security [checking] during the holiday season. (=Dịch: Sân bay đã áp dụng quy trình kiểm tra an ninh nghiêm ngặt hơn trong mùa nghỉ lễ.)","Routine [checking] of the machinery prevents unexpected breakdowns. (=Dịch: Việc kiểm tra máy móc định kỳ giúp ngăn ngừa những sự cố hỏng hóc bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=checking&lang=en-GB&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=checking&lang=en-US&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F"},{"id":"lv_1_26","topic":"Job Seeking and Work","word":"clerical","pos":"(adj)","ipa":"/ˈkler.ɪ.kəl/","defVi":"thuộc công việc văn phòng, hành chính","defEn":"relating to office work such as typing, filing, and record-keeping","examples":["She applied for a [clerical] position at a local law firm. (=Dịch: Cô ấy đã nộp đơn ứng tuyển vào một vị trí văn phòng tại một công ty luật địa phương.)","A minor [clerical] error caused a significant delay in the shipment. (=Dịch: Một lỗi hành chính nhỏ đã gây ra sự chậm trễ đáng kể cho chuyến hàng.)","He spent his first year doing routine [clerical] tasks. (=Dịch: Anh ấy đã dành năm đầu tiên để làm những công việc văn phòng thường nhật.)"],"ukAudio":"/ai_services/tts3/?q=clerical&lang=en-GB&ipa=%2F%CB%88kler.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=clerical&lang=en-US&ipa=%2F%CB%88kler.%C9%AA.k%C9%99l%2F"},{"id":"lv_1_27","topic":"Job Seeking and Work","word":"commitment","pos":"(n)","ipa":"/kəˈmɪt.mənt/","defVi":"sự cam kết, sự tận tụy, trách nhiệm","defEn":"a promise or firm decision to do something, or loyalty and dedication to a cause","examples":["The company demonstrated its [commitment] to quality by improving safety standards. (=Dịch: Công ty đã thể hiện cam kết về chất lượng bằng cách cải thiện các tiêu chuẩn an toàn.)","Balancing family life and work [commitment] can be challenging for many parents. (=Dịch: Cân bằng giữa cuộc sống gia đình và trách nhiệm công việc có thể là một thử thách đối với nhiều bậc cha mẹ.)","Learning a musical instrument requires a serious long-term [commitment]. (=Dịch: Học một nhạc cụ đòi hỏi sự gắn bó và nỗ lực nghiêm túc lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=commitment&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=commitment&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F"},{"id":"lv_1_28","topic":"Job Seeking and Work","word":"confusion","pos":"(n)","ipa":"/kənˈfjuː.ʒən/","defVi":"sự bối rối, sự nhầm lẫn, tình trạng hỗn loạn","defEn":"a state of not understanding something clearly or a situation that is disorderly","examples":["There was some [confusion] about the exact time of the meeting. (=Dịch: Đã có một sự nhầm lẫn về thời gian chính xác của cuộc họp.)","His instructions caused great [confusion] among the new workers. (=Dịch: Các hướng dẫn của anh ấy đã gây ra sự bối rối lớn cho những công nhân mới.)","The sudden power outage led to [confusion] in the shopping mall. (=Dịch: Sự cố mất điện đột ngột đã dẫn đến tình trạng hỗn loạn trong trung tâm thương mại.)"],"ukAudio":"/ai_services/tts3/?q=confusion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=confusion&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_1_29","topic":"Job Seeking and Work","word":"contract","pos":"(n)","ipa":"/ˈkɑːn.trækt/","defVi":"hợp đồng, giao kèo","defEn":"a legal written agreement between two or more people or organizations","examples":["Please read the terms carefully before signing the employment [contract]. (=Dịch: Vui lòng đọc kỹ các điều khoản trước khi ký hợp đồng lao động.)","The company won a major [contract] to build a new bridge. (=Dịch: Công ty đã giành được một hợp đồng lớn để xây dựng một cây cầu mới.)","Breaking the [contract] early will result in financial penalties. (=Dịch: Việc phá vỡ hợp đồng sớm sẽ dẫn đến các khoản phạt tài chính.)"],"ukAudio":"/ai_services/tts3/?q=contract&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=contract&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F"},{"id":"lv_1_30","topic":"Job Seeking and Work","word":"cooler","pos":"(n)","ipa":"/ˈkuː.lɚ/","defVi":"thùng giữ lạnh, thiết bị làm mát","defEn":"an insulated container or device used to keep things, especially food or drinks, cold","examples":["We packed several bottles of water and sandwiches in the [cooler] for our picnic. (=Dịch: Chúng tôi đã đóng gói vài chai nước và bánh mì kẹp vào thùng giữ nhiệt cho chuyến dã ngoại.)","Don't forget to put fresh ice in the [cooler] before we head to the beach. (=Dịch: Đừng quên cho thêm đá mới vào thùng giữ nhiệt trước khi chúng ta ra bãi biển.)","The workers gathered around the water [cooler] to chat during their break. (=Dịch: Các công nhân tụ tập quanh bình nước nóng lạnh để trò chuyện trong giờ giải lao.)"],"ukAudio":"/ai_services/tts3/?q=cooler&lang=en-GB&ipa=%2F%CB%88ku%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cooler&lang=en-US&ipa=%2F%CB%88ku%CB%90.l%C9%9A%2F"},{"id":"lv_1_31","topic":"Job Seeking and Work","word":"corridor","pos":"(n)","ipa":"/ˈkɔːr.ə.dɚ/","defVi":"hành lang","defEn":"a long narrow passage in a building with doors leading into rooms","examples":["His office is located at the very end of the second-floor [corridor]. (=Dịch: Văn phòng của ông ấy nằm ở tận cuối hành lang tầng hai.)","Students are reminded not to run in the school [corridor]. (=Dịch: Học sinh được nhắc nhở không chạy nhảy trong hành lang trường học.)","The hotel [corridor] was quiet and lined with soft carpeting. (=Dịch: Hành lang khách sạn rất yên tĩnh và được trải thảm mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=corridor&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=corridor&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F"},{"id":"lv_1_32","topic":"Job Seeking and Work","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục, đồ hóa trang","defEn":"a set of clothes worn by an actor or for a special occasion or party","examples":["The actors wore elaborate period [costumes] for the historical drama. (=Dịch: Các diễn viên đã mặc những bộ trang phục cổ trang công phu cho bộ phim lịch sử.)","He won the first prize for the best Halloween [costume] at the party. (=Dịch: Anh ấy đã giành giải nhất cho bộ trang phục Halloween đẹp nhất tại bữa tiệc.)","The designer spent months researching traditional [costumes] for the dance performance. (=Dịch: Nhà thiết kế đã dành nhiều tháng nghiên cứu các trang phục truyền thống cho buổi biểu diễn múa.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_1_33","topic":"Job Seeking and Work","word":"counter","pos":"(n)","ipa":"/ˈkaʊn.tər/","defVi":"quầy thu ngân, quầy phục vụ, mặt bàn bếp","defEn":"a flat surface over which business is conducted, such as in a bank, shop, or kitchen","examples":["Please leave your keys on the reception [counter] when you check out. (=Dịch: Vui lòng để lại chìa khóa trên quầy lễ tân khi bạn trả phòng.)","The bakery displayed fresh bread behind the glass [counter]. (=Dịch: Tiệm bánh trưng bày bánh mì tươi phía sau quầy kính.)","Wipe down the kitchen [counter] thoroughly after preparing food. (=Dịch: Hãy lau chùi kỹ mặt bàn bếp sau khi chuẩn bị thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=counter&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=counter&lang=en-US&ipa=%2F%CB%88ka%CA%8An.t%C9%99r%2F"},{"id":"lv_1_34","topic":"Job Seeking and Work","word":"courtyard","pos":"(n)","ipa":"/ˈkɔːrt.jɑːrd/","defVi":"sân trong, khoảng sân có tường hoặc nhà bao quanh","defEn":"an open area of ground surrounded by walls or buildings","examples":["The hotel has a charming central [courtyard] filled with flowers and fountains. (=Dịch: Khách sạn có một khoảng sân trung tâm quyến rũ ngập tràn hoa và đài phun nước.)","Students often sit in the [courtyard] to study and enjoy the fresh air. (=Dịch: Sinh viên thường ngồi ở sân trong để học bài và tận hưởng không khí trong lành.)","The ancient palace was built around a spacious stone [courtyard]. (=Dịch: Cung điện cổ kính được xây dựng xung quanh một khoảng sân đá rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=courtyard&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=courtyard&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F"},{"id":"lv_1_35","topic":"Job Seeking and Work","word":"disposal","pos":"(n)","ipa":"/dɪˈspoʊ.zəl/","defVi":"sự vứt bỏ, sự xử lý","defEn":"the act of getting rid of something","examples":["The safe [disposal] of chemical waste is crucial for the environment. (=Dịch: Việc xử lý an toàn chất thải hóa học là vô cùng quan trọng đối với môi trường.)","A car was put at our [disposal] during the business trip. (=Dịch: Một chiếc xe hơi đã được bố trí sẵn cho chúng tôi sử dụng trong suốt chuyến công tác.)","The city introduced new rules for domestic rubbish [disposal]. (=Dịch: Thành phố đã ban hành các quy định mới về việc xử lý rác thải sinh hoạt.)"],"ukAudio":"/ai_services/tts3/?q=disposal&lang=en-GB&ipa=%2Fd%C9%AA%CB%88spo%CA%8A.z%C9%99l%2F","usAudio":"/ai_services/tts3/?q=disposal&lang=en-US&ipa=%2Fd%C9%AA%CB%88spo%CA%8A.z%C9%99l%2F"},{"id":"lv_1_36","topic":"Job Seeking and Work","word":"diversity","pos":"(n)","ipa":"/daɪˈvɝː.sə.t̬i/","defVi":"sự đa dạng, sự phong phú","defEn":"the state of having many different types, ideas, or people included","examples":["Cultural [diversity] enriches society by introducing new perspectives and traditions. (=Dịch: Sự đa dạng văn hóa làm phong phú xã hội bằng cách mang lại những góc nhìn và truyền thống mới.)","The university promotes [diversity] by admitting students from various backgrounds. (=Dịch: Trường đại học thúc đẩy sự đa dạng bằng cách tiếp nhận sinh viên từ nhiều hoàn cảnh khác nhau.)","The rainforest is famous for its rich biological [diversity]. (=Dịch: Rừng mưa nhiệt đới nổi tiếng với sự đa dạng sinh học phong phú.)"],"ukAudio":"/ai_services/tts3/?q=diversity&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=diversity&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_1_37","topic":"Job Seeking and Work","word":"dramatic","pos":"(adj)","ipa":"/drəˈmæt̬.ɪk/","defVi":"đột ngột, đáng kể, kịch tính","defEn":"sudden, very great, and often surprising","examples":["There was a [dramatic] increase in sales last month. (=Dịch: Doanh số tháng trước đã tăng lên một cách đáng kể.)","The new policy brought about a [dramatic] change in the company's culture. (=Dịch: Chính sách mới đã mang lại một sự thay đổi sâu sắc trong văn hóa của công ty.)","She gave a [dramatic] sigh to show her disappointment. (=Dịch: Cô ấy thở dài một cách đầy kịch tính để thể hiện sự thất vọng của mình.)"],"ukAudio":"/ai_services/tts3/?q=dramatic&lang=en-GB&ipa=%2Fdr%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dramatic&lang=en-US&ipa=%2Fdr%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_1_38","topic":"Job Seeking and Work","word":"duty","pos":"(n)","ipa":"/ˈduː.t̬i/","defVi":"bổn phận, trách nhiệm, nhiệm vụ","defEn":"a moral or legal obligation; a task that is part of a person's job","examples":["Every citizen has a civic [duty] to vote in the national elections. (=Dịch: Mỗi công dân đều có nghĩa vụ công dân là đi bỏ phiếu trong các cuộc bầu cử quốc gia.)","Taking care of customer complaints is part of his daily [duty]. (=Dịch: Giải quyết các khiếu nại của khách hàng là một phần trong nhiệm vụ hằng ngày của anh ấy.)","Doctors feel a strong sense of [duty] toward their patients. (=Dịch: Các bác sĩ cảm nhận được tinh thần trách nhiệm sâu sắc đối với bệnh nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=duty&lang=en-GB&ipa=%2F%CB%88du%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=duty&lang=en-US&ipa=%2F%CB%88du%CB%90.t%CC%ACi%2F"},{"id":"lv_1_39","topic":"Job Seeking and Work","word":"enquire","pos":"(v)","ipa":"/ɪnˈkwaɪ.ɚ/","defVi":"hỏi thăm, dò hỏi","defEn":"to ask for information about something","examples":["I called the hotel to [enquire] about room availability for the weekend. (=Dịch: Tôi đã gọi điện đến khách sạn để hỏi về tình trạng phòng trống vào cuối tuần.)","She stopped at the reception desk to [enquire] the way to the conference hall. (=Dịch: Cô ấy dừng lại ở quầy lễ tân để hỏi đường đến hội trường.)","Prospective students often [enquire] about tuition fees and scholarship options. (=Dịch: Các sinh viên tương lai thường hỏi về học phí và các chương trình học bổng.)"],"ukAudio":"/ai_services/tts3/?q=enquire&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=enquire&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%9A%2F"},{"id":"lv_1_40","topic":"Job Seeking and Work","word":"enquiry","pos":"(n)","ipa":"/ɪnˈkwaɪ.ə.ri/","defVi":"sự yêu cầu thông tin, câu hỏi thắc mắc hoặc cuộc điều tra","defEn":"an act of asking for information or an official investigation","examples":["I sent an email [enquiry] to the hotel regarding their room rates. (=Dịch: Tôi đã gửi một email thắc mắc đến khách sạn để hỏi về giá phòng của họ.)","The customer service desk handles every [enquiry] quickly and politely. (=Dịch: Bàn dịch vụ khách hàng giải quyết mọi thắc mắc một cách nhanh chóng và lịch sự.)","The government launched a formal [enquiry] into the causes of the train crash. (=Dịch: Chính phủ đã mở một cuộc điều tra chính thức về nguyên nhân của vụ tai nạn tàu hỏa.)"],"ukAudio":"/ai_services/tts3/?q=enquiry&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=enquiry&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%99.ri%2F"},{"id":"lv_1_41","topic":"Job Seeking and Work","word":"exit","pos":"(v)","ipa":"/ˈɛɡ.zɪt/","defVi":"rời khỏi, đi ra khỏi","defEn":"to go out of or leave a place or situation","examples":["Passengers should [exit] the bus through the rear door. (=Dịch: Hành khách nên xuống xe buýt bằng cửa sau.)","Please do not [exit] the building until the fire drill is over. (=Dịch: Vui lòng không rời khỏi tòa nhà cho đến khi buổi diễn tập phòng cháy chữa cháy kết thúc.)","The speaker chose to [exit] the stage immediately after answering the final question. (=Dịch: Diễn giả đã quyết định rời khỏi sân khấu ngay sau khi trả lời câu hỏi cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=exit&lang=en-GB&ipa=%2F%CB%88%C9%9B%C9%A1.z%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exit&lang=en-US&ipa=%2F%CB%88%C9%9B%C9%A1.z%C9%AAt%2F"},{"id":"lv_1_42","topic":"Job Seeking and Work","word":"foyer","pos":"(n)","ipa":"/ˈfɔɪ.ɚ/","defVi":"tiền sảnh, sảnh chờ","defEn":"a large open area near the entrance inside a building, such as a hotel or theater","examples":["We arranged to meet our friends in the theater [foyer] before the show. (=Dịch: Chúng tôi đã hẹn gặp bạn bè ở sảnh nhà hát trước giờ biểu diễn.)","The hotel [foyer] was decorated with modern art and large plants. (=Dịch: Sảnh khách sạn được trang trí bằng các tác phẩm nghệ thuật hiện đại và những chậu cây lớn.)","Guests waited in the spacious [foyer] until the conference hall doors opened. (=Dịch: Các vị khách đã chờ ở sảnh lớn rộng rãi cho đến khi cửa phòng hội nghị mở ra.)"],"ukAudio":"/ai_services/tts3/?q=foyer&lang=en-GB&ipa=%2F%CB%88f%C9%94%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=foyer&lang=en-US&ipa=%2F%CB%88f%C9%94%C9%AA.%C9%9A%2F"},{"id":"lv_1_43","topic":"Job Seeking and Work","word":"gender","pos":"(n)","ipa":"/ˈdʒen.dɚ/","defVi":"giới tính","defEn":"the state of being male or female, especially when considered in relation to social and cultural factors","examples":["The survey includes questions about age, [gender], and occupation. (=Dịch: Cuộc khảo sát bao gồm các câu hỏi về độ tuổi, giới tính và nghề nghiệp.)","Efforts are being made to eliminate the [gender] pay gap. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm xóa bỏ khoảng cách chênh lệch tiền lương theo giới tính.)","She conducts research on [gender] equality in the workplace. (=Dịch: Cô ấy tiến hành nghiên cứu về bình đẳng giới tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=gender&lang=en-GB&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gender&lang=en-US&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F"},{"id":"lv_1_44","topic":"Job Seeking and Work","word":"heavily","pos":"(adv)","ipa":"/ˈhev.ə.li/","defVi":"nặng nề, một cách nghiêm trọng hoặc với số lượng lớn","defEn":"to a great degree; in large amounts or with a lot of weight/force","examples":["It was raining [heavily], so we decided to stay indoors. (=Dịch: Trời mưa rất to, vì vậy chúng tôi quyết định ở trong nhà.)","The company relies [heavily] on digital marketing to attract new clients. (=Dịch: Công ty phụ thuộc rất nhiều vào tiếp thị kỹ thuật số để thu hút khách hàng mới.)","She sighed [heavily] before delivering the disappointing news. (=Dịch: Cô ấy thở dài nặng nề trước khi thông báo tin tức đáng thất vọng.)"],"ukAudio":"/ai_services/tts3/?q=heavily&lang=en-GB&ipa=%2F%CB%88hev.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=heavily&lang=en-US&ipa=%2F%CB%88hev.%C9%99.li%2F"},{"id":"lv_1_45","topic":"Job Seeking and Work","word":"hr","pos":"(n)","ipa":"/ˌeɪtʃˈɑːr/","defVi":"bộ phận nhân sự, ngành nhân sự","defEn":"the department in an organization dealing with hiring, training, and employee welfare","examples":["You need to submit your leave request to [HR] by the end of the week. (=Dịch: Bạn cần gửi đơn xin nghỉ phép đến phòng nhân sự trước cuối tuần này.)","The [HR] manager will conduct the first round of job interviews tomorrow. (=Dịch: Trưởng phòng nhân sự sẽ tiến hành vòng phỏng vấn xin việc đầu tiên vào ngày mai.)","She decided to pursue a career in [HR] because she enjoys working with people. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp trong ngành nhân sự vì thích làm việc với con người.)"],"ukAudio":"/ai_services/tts3/?q=hr&lang=en-GB&ipa=%2F%CB%8Ce%C9%AAt%CA%83%CB%88%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=hr&lang=en-US&ipa=%2F%CB%8Ce%C9%AAt%CA%83%CB%88%C9%91%CB%90r%2F"},{"id":"lv_1_46","topic":"Job Seeking and Work","word":"immediate","pos":"(adj)","ipa":"/ɪˈmiː.di.ət/","defVi":"ngay lập tức, trực tiếp, trước mắt","defEn":"happening or done without delay; nearest in time, relationship, or space","examples":["The patient requires [immediate] medical attention after the accident. (=Dịch: Bệnh nhân cần được chăm sóc y tế ngay lập tức sau vụ tai nạn.)","Our [immediate] goal is to finish the project before the deadline. (=Dịch: Mục tiêu trước mắt của chúng tôi là hoàn thành dự án trước thời hạn.)","The decision had an [immediate] effect on the stock market. (=Dịch: Quyết định này đã có tác động ngay lập tức lên thị trường chứng khoán.)"],"ukAudio":"/ai_services/tts3/?q=immediate&lang=en-GB&ipa=%2F%C9%AA%CB%88mi%CB%90.di.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=immediate&lang=en-US&ipa=%2F%C9%AA%CB%88mi%CB%90.di.%C9%99t%2F"},{"id":"lv_1_47","topic":"Job Seeking and Work","word":"incentive","pos":"(n)","ipa":"/ɪnˈsɛn.tɪv/","defVi":"sự khích lệ, động lực, phần thưởng khuyến khích","defEn":"something that encourages a person to do something or work harder","examples":["The company offers a cash [incentive] for employees who reach their sales targets. (=Dịch: Công ty đưa ra một khoản tiền thưởng khích lệ cho những nhân viên đạt chỉ tiêu doanh số.)","Tax cuts provide an [incentive] for local businesses to invest in new equipment. (=Dịch: Việc cắt giảm thuế tạo động lực cho các doanh nghiệp địa phương đầu tư vào trang thiết bị mới.)","There is little [incentive] for students to study hard if the tests are too easy. (=Dịch: Học sinh có rất ít động lực để học chăm chỉ nếu các bài kiểm tra quá dễ.)"],"ukAudio":"/ai_services/tts3/?q=incentive&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%9Bn.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=incentive&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%9Bn.t%C9%AAv%2F"},{"id":"lv_1_48","topic":"Job Seeking and Work","word":"inclusion","pos":"(n)","ipa":"/ɪnˈkluː.ʒən/","defVi":"sự hòa nhập, sự bao gồm, sự tính cả vào","defEn":"the practice of including people from all backgrounds, or the act of adding something into a group","examples":["The school promotes social [inclusion] for children with special needs. (=Dịch: Nhà trường thúc đẩy sự hòa nhập xã hội cho trẻ em có nhu cầu đặc biệt.)","His [inclusion] in the national football squad surprised many fans. (=Dịch: Việc anh ấy có tên trong danh sách đội tuyển bóng đá quốc gia đã khiến nhiều người hâm mộ bất ngờ.)","Diversity and [inclusion] policies have become essential in modern workplaces. (=Dịch: Các chính sách về đa dạng và hòa nhập đã trở nên thiết yếu tại các nơi làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=inclusion&lang=en-GB&ipa=%2F%C9%AAn%CB%88klu%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=inclusion&lang=en-US&ipa=%2F%C9%AAn%CB%88klu%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_1_49","topic":"Job Seeking and Work","word":"indigenous","pos":"(adj)","ipa":"/ɪnˈdɪdʒ.ə.nəs/","defVi":"bản địa, bản xứ","defEn":"originating or occurring naturally in a particular place; native","examples":["The kangaroo is [indigenous] to Australia. (=Dịch: Chuột túi là loài bản địa của Úc.)","Researchers are working to preserve [indigenous] languages and traditions. (=Dịch: Các nhà nghiên cứu đang nỗ lực bảo tồn các ngôn ngữ và truyền thống bản địa.)","This plant is [indigenous] to tropical rainforests and cannot survive cold winters. (=Dịch: Loài cây này có nguồn gốc bản địa từ các khu rừng mưa nhiệt đới và không thể sống sót qua mùa đông lạnh giá.)"],"ukAudio":"/ai_services/tts3/?q=indigenous&lang=en-GB&ipa=%2F%C9%AAn%CB%88d%C9%AAd%CA%92.%C9%99.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=indigenous&lang=en-US&ipa=%2F%C9%AAn%CB%88d%C9%AAd%CA%92.%C9%99.n%C9%99s%2F"},{"id":"lv_1_50","topic":"Job Seeking and Work","word":"install","pos":"(v)","ipa":"/ɪnˈstɑːl/","defVi":"lắp đặt, cài đặt","defEn":"to put a piece of equipment or software in place so that it is ready for use","examples":["A technician came to [install] the new air conditioner yesterday. (=Dịch: Hôm qua một kỹ thuật viên đã đến để lắp đặt chiếc máy điều hòa mới.)","You need to [install] the latest software updates to keep your phone secure. (=Dịch: Bạn cần cài đặt các bản cập nhật phần mềm mới nhất để giữ an toàn cho điện thoại của mình.)","The city plans to [install] more solar-powered streetlights this year. (=Dịch: Thành phố có kế hoạch lắp đặt thêm đèn đường chạy bằng năng lượng mặt trời trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=install&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=install&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_1_51","topic":"Job Seeking and Work","word":"interfere","pos":"(v)","ipa":"/ˌɪn.t̬ɚˈfɪr/","defVi":"can thiệp, can dự, làm phiền","defEn":"to get involved in a situation where you are not wanted or needed","examples":["Noise from the construction site began to [interfere] with our studies. (=Dịch: Tiếng ồn từ công trường xây dựng bắt đầu gây ảnh hưởng đến việc học của chúng tôi.)","Parents should support their children but not [interfere] in all their choices. (=Dịch: Cha mẹ nên hỗ trợ con cái nhưng không nên can thiệp vào mọi lựa chọn của chúng.)","Strong emotions can sometimes [interfere] with rational decision-making. (=Dịch: Những cảm xúc mãnh liệt đôi khi có thể cản trở việc đưa ra quyết định hợp lý.)"],"ukAudio":"/ai_services/tts3/?q=interfere&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=interfere&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F"},{"id":"lv_1_52","topic":"Job Seeking and Work","word":"internal","pos":"(adj)","ipa":"/ɪnˈtɜːr.nəl/","defVi":"nội bộ, bên trong","defEn":"located inside something, or happening within an organization or country","examples":["The company conducted an [internal] audit to evaluate its accounting practices. (=Dịch: Công ty đã tiến hành một cuộc kiểm toán nội bộ để đánh giá các hoạt động kế toán của mình.)","Regular exercise helps protect your [internal] organs from various diseases. (=Dịch: Tập thể dục thường xuyên giúp bảo vệ các cơ quan nội tạng của bạn khỏi nhiều bệnh tật.)","Management resolved the dispute through an [internal] discussion. (=Dịch: Ban quản lý đã giải quyết tranh chấp thông qua một cuộc thảo luận nội bộ.)"],"ukAudio":"/ai_services/tts3/?q=internal&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9C%CB%90r.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=internal&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9C%CB%90r.n%C9%99l%2F"},{"id":"lv_1_53","topic":"Job Seeking and Work","word":"interpersonal","pos":"(adj)","ipa":"/ˌɪn.t̬ɚˈpɝː.sən.əl/","defVi":"giữa các cá nhân, giao tiếp ứng xử","defEn":"connected with relationships between people","examples":["Strong [interpersonal] skills are essential for effective team leaders. (=Dịch: Kỹ năng giao tiếp ứng xử tốt là điều cần thiết đối với những người lãnh đạo nhóm hiệu quả.)","The course helps students improve their [interpersonal] communication. (=Dịch: Khóa học giúp sinh viên cải thiện khả năng giao tiếp giữa các cá nhân.)","Workplace conflicts often stem from poor [interpersonal] dynamics. (=Dịch: Các mâu thuẫn tại nơi làm việc thường bắt nguồn từ mối quan hệ tương tác kém giữa các cá nhân.)"],"ukAudio":"/ai_services/tts3/?q=interpersonal&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88p%C9%9D%CB%90.s%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=interpersonal&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88p%C9%9D%CB%90.s%C9%99n.%C9%99l%2F"},{"id":"lv_1_54","topic":"Job Seeking and Work","word":"investment","pos":"(n)","ipa":"/ɪnˈvest.mənt/","defVi":"sự đầu tư, khoản đầu tư","defEn":"the act of putting money, effort, or time into something to gain a profit or benefit","examples":["Buying a home is often the largest financial [investment] a family will make. (=Dịch: Mua nhà thường là khoản đầu tư tài chính lớn nhất mà một gia đình thực hiện.)","The government announced a major [investment] in renewable energy infrastructure. (=Dịch: Chính phủ đã công bố một khoản đầu tư lớn vào cơ sở hạ tầng năng lượng tái tạo.)","Learning a foreign language requires a substantial [investment] of time and effort. (=Dịch: Học một ngoại ngữ đòi hỏi sự đầu tư đáng kể về thời gian và công sức.)"],"ukAudio":"/ai_services/tts3/?q=investment&lang=en-GB&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=investment&lang=en-US&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F"},{"id":"lv_1_55","topic":"Job Seeking and Work","word":"joy","pos":"(n)","ipa":"/dʒɔɪ/","defVi":"niềm vui, sự vui mừng","defEn":"a feeling of great happiness or pleasure","examples":["The children jumped for [joy] when they heard the good news. (=Dịch: Lũ trẻ nhảy cẫng lên vì vui sướng khi nghe được tin tốt lành.)","Gardening brings immense [joy] and relaxation to many retirees. (=Dịch: Làm vườn mang lại niềm vui vô bờ bến và sự thư giãn cho nhiều người về hưu.)","His success was a source of great [joy] to his entire family. (=Dịch: Thành công của anh ấy là nguồn vui lớn cho cả gia đình.)"],"ukAudio":"/ai_services/tts3/?q=joy&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AA%2F","usAudio":"/ai_services/tts3/?q=joy&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AA%2F"},{"id":"lv_1_56","topic":"Job Seeking and Work","word":"latin","pos":"(adj)","ipa":"/ˈlæt.n/","defVi":"thuộc tiếng La-tinh, thuộc văn hóa La-tinh","defEn":"relating to the ancient Latin language, ancient Rome, or Latin America","examples":["Many scientific names for animals and plants are derived from [Latin] roots. (=Dịch: Nhiều tên khoa học của động thực vật bắt nguồn từ các gốc từ tiếng La-tinh.)","The festival celebrates the vibrant traditions of [Latin] music and dance. (=Dịch: Lễ hội tôn vinh những truyền thống sôi động của âm nhạc và vũ điệu Mỹ La-tinh.)","Students of law often encounter [Latin] phrases in legal documents. (=Dịch: Sinh viên ngành luật thường bắt gặp các cụm từ tiếng La-tinh trong các văn bản pháp lý.)"],"ukAudio":"/ai_services/tts3/?q=latin&lang=en-GB&ipa=%2F%CB%88l%C3%A6t.n%2F","usAudio":"/ai_services/tts3/?q=latin&lang=en-US&ipa=%2F%CB%88l%C3%A6t.n%2F"},{"id":"lv_1_57","topic":"Job Seeking and Work","word":"layout","pos":"(n)","ipa":"/ˈleɪ.aʊt/","defVi":"bố cục, sơ đồ mặt bằng, sự sắp xếp","defEn":"the way in which the parts of something are arranged or organized","examples":["The store changed its [layout] to encourage customers to browse more items. (=Dịch: Cửa hàng đã thay đổi cách bố trí để khuyến khích khách hàng xem nhiều mặt hàng hơn.)","I like the clear [layout] of this website because it is easy to navigate. (=Dịch: Tôi thích bố cục rõ ràng của trang web này vì nó rất dễ điều hướng.)","The architect presented the new office [layout] to the management team. (=Dịch: Kiến trúc sư đã trình bày bản bố trí văn phòng mới cho ban quản lý.)"],"ukAudio":"/ai_services/tts3/?q=layout&lang=en-GB&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=layout&lang=en-US&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F"},{"id":"lv_1_58","topic":"Job Seeking and Work","word":"leaflet","pos":"(n)","ipa":"/ˈliːf.lət/","defVi":"tờ rơi, tờ gấp quảng cáo","defEn":"a printed sheet of paper containing information or advertising, usually distributed free","examples":["Volunteers handed out a [leaflet] about environmental protection to passersby. (=Dịch: Các tình nguyện viên đã phát tờ rơi về bảo vệ môi trường cho người qua đường.)","I picked up a travel [leaflet] at the tourist information center. (=Dịch: Tôi đã lấy một tờ rơi du lịch tại trung tâm thông tin du khách.)","The medical [leaflet] explains the possible side effects of the drug. (=Dịch: Tờ hướng dẫn y tế giải thích các tác dụng phụ có thể xảy ra của thuốc.)"],"ukAudio":"/ai_services/tts3/?q=leaflet&lang=en-GB&ipa=%2F%CB%88li%CB%90f.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=leaflet&lang=en-US&ipa=%2F%CB%88li%CB%90f.l%C9%99t%2F"},{"id":"lv_1_59","topic":"Job Seeking and Work","word":"licence","pos":"(n)","ipa":"/ˈlaɪ.səns/","defVi":"giấy phép, bằng lái","defEn":"an official document giving permission to do, use, or own something","examples":["You need a valid [licence] to drive a car in this country. (=Dịch: Bạn cần có giấy phép lái xe hợp lệ để lái ô tô ở quốc gia này.)","The restaurant lost its [licence] to serve alcohol after breaking the rules. (=Dịch: Nhà hàng đã bị tước giấy phép phục vụ đồ uống có cồn sau khi vi phạm các quy định.)","He applied for a software [licence] to use the program legally. (=Dịch: Anh ấy đã đăng ký mua bản quyền phần mềm để sử dụng chương trình một cách hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=licence&lang=en-GB&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=licence&lang=en-US&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F"},{"id":"lv_1_60","topic":"Job Seeking and Work","word":"lounge","pos":"(n)","ipa":"/laʊndʒ/","defVi":"phòng chờ, phòng sinh hoạt chung","defEn":"a comfortable room in a house, hotel, or airport used for sitting and relaxing","examples":["Business-class passengers can relax and enjoy free snacks in the airport [lounge]. (=Dịch: Hành khách hạng thương gia có thể thư giãn và thưởng thức đồ ăn nhẹ miễn phí trong phòng chờ sân bay.)","The family gathered in the cozy [lounge] to watch television after dinner. (=Dịch: Gia đình quây quần trong phòng khách ấm cúng để xem tivi sau bữa tối.)","The hotel has a quiet cocktail [lounge] on the top floor. (=Dịch: Khách sạn có một quầy bar phục vụ cocktail yên tĩnh trên tầng cao nhất.)"],"ukAudio":"/ai_services/tts3/?q=lounge&lang=en-GB&ipa=%2Fla%CA%8And%CA%92%2F","usAudio":"/ai_services/tts3/?q=lounge&lang=en-US&ipa=%2Fla%CA%8And%CA%92%2F"},{"id":"lv_1_61","topic":"Job Seeking and Work","word":"machinery","pos":"(n)","ipa":"/məˈʃiː.nɚ.i/","defVi":"máy móc, thiết bị cơ khí","defEn":"machines as a whole, especially large machines used in industry or agriculture","examples":["The factory invested in modern [machinery] to increase production speed. (=Dịch: Nhà máy đã đầu tư vào máy móc hiện đại để tăng tốc độ sản xuất.)","Workers must wear protective helmets when operating heavy [machinery]. (=Dịch: Công nhân phải đội mũ bảo hộ khi vận hành máy móc hạng nặng.)","Regular maintenance prevents the farm [machinery] from breaking down unexpectedly. (=Dịch: Bảo trì định kỳ giúp máy móc nông nghiệp không bị hỏng hóc bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=machinery&lang=en-GB&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=machinery&lang=en-US&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F"},{"id":"lv_1_62","topic":"Job Seeking and Work","word":"magician","pos":"(n)","ipa":"/məˈdʒɪʃ.ən/","defVi":"ảo thuật gia","defEn":"a person who performs magic tricks for entertainment","examples":["The [magician] pulled a white rabbit out of his empty hat. (=Dịch: Ảo thuật gia đã kéo một con thỏ trắng ra khỏi chiếc mũ trống rỗng của mình.)","They hired a talented [magician] to entertain the children at the birthday party. (=Dịch: Họ đã thuê một ảo thuật gia tài năng để biểu diễn giúp vui cho các bạn nhỏ trong bữa tiệc sinh nhật.)","The audience watched in awe as the [magician] seemed to disappear into thin air. (=Dịch: Khán giả kinh ngạc theo dõi khi ảo thuật gia dường như biến mất vào hư không.)"],"ukAudio":"/ai_services/tts3/?q=magician&lang=en-GB&ipa=%2Fm%C9%99%CB%88d%CA%92%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=magician&lang=en-US&ipa=%2Fm%C9%99%CB%88d%CA%92%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_63","topic":"Job Seeking and Work","word":"mentor","pos":"(n)","ipa":"/ˈmen.tɔːr/","defVi":"người cố vấn, người hướng dẫn","defEn":"an experienced and trusted person who advises and guides someone younger or less experienced","examples":["My former professor acted as a valuable [mentor] throughout my early academic career. (=Dịch: Giáo sư cũ của tôi đã đóng vai trò là một người cố vấn quý báu trong suốt giai đoạn đầu sự nghiệp học thuật của tôi.)","The company established a scheme to pair every new graduate with a senior [mentor]. (=Dịch: Công ty đã thiết lập một chương trình ghép đôi mỗi sinh viên mới tốt nghiệp với một người hướng dẫn giàu kinh nghiệm.)","She credits her [mentor] with teaching her how to negotiate contracts effectively. (=Dịch: Cô ấy biết ơn người cố vấn vì đã dạy cô cách đàm phán hợp đồng một cách hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=mentor&lang=en-GB&ipa=%2F%CB%88men.t%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=mentor&lang=en-US&ipa=%2F%CB%88men.t%C9%94%CB%90r%2F"},{"id":"lv_1_64","topic":"Job Seeking and Work","word":"midday","pos":"(n)","ipa":"/ˌmɪdˈdeɪ/","defVi":"buổi trưa, giữa trưa","defEn":"the middle of the day; twelve o'clock in the afternoon","examples":["The sun is usually at its hottest around [midday]. (=Dịch: Mặt trời thường gay gắt nhất vào khoảng giữa trưa.)","We decided to take a break and have our lunch at [midday]. (=Dịch: Chúng tôi quyết định nghỉ ngơi và ăn trưa vào buổi trưa.)","The delivery is scheduled to arrive before [midday] tomorrow. (=Dịch: Hàng dự kiến sẽ được giao đến trước buổi trưa ngày mai.)"],"ukAudio":"/ai_services/tts3/?q=midday&lang=en-GB&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=midday&lang=en-US&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F"},{"id":"lv_1_65","topic":"Job Seeking and Work","word":"orientation","pos":"(n)","ipa":"/ˌɔːr.i.enˈteɪ.ʃən/","defVi":"buổi định hướng, chương trình tập huấn ban đầu","defEn":"a training or introduction session for new employees or students","examples":["All new recruits are required to attend the company [orientation] on Monday morning. (=Dịch: Tất cả nhân viên mới được yêu cầu tham gia buổi định hướng của công ty vào sáng thứ Hai.)","The university organised a campus tour as part of the student [orientation] week. (=Dịch: Trường đại học đã tổ chức một chuyến tham quan khuôn viên trường như một phần của tuần lễ định hướng sinh viên.)","The [orientation] helped her understand the workplace culture and safety procedures. (=Dịch: Buổi định hướng đã giúp cô ấy hiểu rõ văn hóa nơi làm việc và các quy trình an toàn.)"],"ukAudio":"/ai_services/tts3/?q=orientation&lang=en-GB&ipa=%2F%CB%8C%C9%94%CB%90r.i.en%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=orientation&lang=en-US&ipa=%2F%CB%8C%C9%94%CB%90r.i.en%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_66","topic":"Job Seeking and Work","word":"outcome","pos":"(n)","ipa":"/ˈaʊt.kʌm/","defVi":"kết quả, hậu quả","defEn":"the final result or effect of an action, process, or situation","examples":["We are still waiting for the final [outcome] of the election. (=Dịch: Chúng tôi vẫn đang chờ kết quả cuối cùng của cuộc bầu cử.)","Regular exercise and a balanced diet will produce a positive health [outcome]. (=Dịch: Tập thể dục thường xuyên và chế độ ăn uống cân bằng sẽ mang lại kết quả sức khỏe tích cực.)","The negotiations ended with a successful [outcome] for both companies. (=Dịch: Các cuộc đàm phán đã kết thúc với kết quả thành công cho cả hai công ty.)"],"ukAudio":"/ai_services/tts3/?q=outcome&lang=en-GB&ipa=%2F%CB%88a%CA%8At.k%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=outcome&lang=en-US&ipa=%2F%CB%88a%CA%8At.k%CA%8Cm%2F"},{"id":"lv_1_67","topic":"Job Seeking and Work","word":"outdated","pos":"(adj)","ipa":"/ˌaʊtˈdeɪ.t̬ɪd/","defVi":"lỗi thời, lạc hậu","defEn":"no longer fashionable, useful, or modern","examples":["These computer systems are [outdated] and need to be replaced soon. (=Dịch: Những hệ thống máy tính này đã lỗi thời và cần sớm được thay thế.)","The company's marketing strategy relies on [outdated] information. (=Dịch: Chiến lược tiếp thị của công ty đang dựa trên những thông tin lỗi thời.)","His views on gender roles are completely [outdated]. (=Dịch: Quan điểm của ông ấy về vai trò giới tính hoàn toàn cổ hủ.)"],"ukAudio":"/ai_services/tts3/?q=outdated&lang=en-GB&ipa=%2F%CB%8Ca%CA%8At%CB%88de%C9%AA.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=outdated&lang=en-US&ipa=%2F%CB%8Ca%CA%8At%CB%88de%C9%AA.t%CC%AC%C9%AAd%2F"},{"id":"lv_1_68","topic":"Job Seeking and Work","word":"overtime","pos":"(n)","ipa":"/ˈoʊ.vɚ.taɪm/","defVi":"sự làm thêm giờ, tiền làm thêm giờ","defEn":"time that you spend working beyond your normal working hours","examples":["Employees receive extra pay for working [overtime] on weekends. (=Dịch: Nhân viên nhận được thêm tiền lương khi làm thêm giờ vào các ngày cuối tuần.)","He put in many hours of [overtime] to finish the project before the deadline. (=Dịch: Anh ấy đã làm thêm nhiều giờ để hoàn thành dự án trước thời hạn.)","The factory ban on [overtime] reduced workers' monthly earnings. (=Dịch: Lệnh cấm làm thêm giờ của nhà máy đã làm giảm thu nhập hằng tháng của công nhân.)"],"ukAudio":"/ai_services/tts3/?q=overtime&lang=en-GB&ipa=%2F%CB%88o%CA%8A.v%C9%9A.ta%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=overtime&lang=en-US&ipa=%2F%CB%88o%CA%8A.v%C9%9A.ta%C9%AAm%2F"},{"id":"lv_1_69","topic":"Job Seeking and Work","word":"permit","pos":"(v)","ipa":"/pɚˈmɪt/","defVi":"cho phép","defEn":"to allow something to happen or give permission for something","examples":["The park does not [permit] visitors to bring dogs onto the beach. (=Dịch: Công viên không cho phép du khách dắt chó vào bãi biển.)","If weather conditions [permit], the outdoor concert will start at seven o'clock. (=Dịch: Nếu điều kiện thời tiết cho phép, buổi hòa nhạc ngoài trời sẽ bắt đầu lúc bảy giờ.)","The museum rules do not [permit] flash photography inside the galleries. (=Dịch: Quy định của bảo tàng không cho phép chụp ảnh có đèn flash bên trong các phòng trưng bày.)"],"ukAudio":"/ai_services/tts3/?q=permit&lang=en-GB&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=permit&lang=en-US&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F"},{"id":"lv_1_70","topic":"Job Seeking and Work","word":"personnel","pos":"(n)","ipa":"/ˌpɜːr.səˈnel/","defVi":"nhân sự, đội ngũ nhân viên","defEn":"the people who work for an organization, business, or the armed forces","examples":["All sales [personnel] are required to attend the customer service workshop. (=Dịch: Tất cả nhân viên bán hàng đều phải tham gia buổi hội thảo về dịch vụ khách hàng.)","The director contacted the [personnel] department to post a new job vacancy. (=Dịch: Giám đốc đã liên hệ với phòng nhân sự để đăng tin tuyển dụng vị trí mới.)","Only authorized military [personnel] may enter this secure area. (=Dịch: Chỉ những quân nhân được ủy quyền mới có thể đi vào khu vực an ninh này.)"],"ukAudio":"/ai_services/tts3/?q=personnel&lang=en-GB&ipa=%2F%CB%8Cp%C9%9C%CB%90r.s%C9%99%CB%88nel%2F","usAudio":"/ai_services/tts3/?q=personnel&lang=en-US&ipa=%2F%CB%8Cp%C9%9C%CB%90r.s%C9%99%CB%88nel%2F"},{"id":"lv_1_71","topic":"Job Seeking and Work","word":"physically","pos":"(adv)","ipa":"/ˈfɪz.ɪ.kli/","defVi":"về mặt thể chất, theo cách hữu hình","defEn":"in a way that relates to the body or real, concrete objects","examples":["Regular exercise helps students stay [physically] healthy and energetic. (=Dịch: Tập thể dục thường xuyên giúp học sinh giữ được sức khỏe thể chất tốt và tràn đầy năng lượng.)","He was [physically] exhausted after running the full marathon. (=Dịch: Anh ấy đã kiệt sức về mặt thể lực sau khi chạy hết quãng đường marathon.)","The store does not [physically] stock the item, but it can be ordered online. (=Dịch: Cửa hàng không có sẵn mặt hàng này tại chỗ, nhưng bạn có thể đặt mua trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=physically&lang=en-GB&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=physically&lang=en-US&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F"},{"id":"lv_1_72","topic":"Job Seeking and Work","word":"portion","pos":"(n)","ipa":"/ˈpɔːr.ʃən/","defVi":"phần, khẩu phần","defEn":"a part or share of a whole amount","examples":["A large [portion] of the budget is spent on public health. (=Dịch: Một phần lớn ngân sách được chi cho y tế công cộng.)","The restaurant serves a generous [portion] of pasta with every meal. (=Dịch: Nhà hàng phục vụ một khẩu phần mì Ý rất hào phóng trong mỗi bữa ăn.)","Only a small [portion] of applicants were invited to the interview. (=Dịch: Chỉ một phần nhỏ các ứng viên được mời tham gia phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=portion&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=portion&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F"},{"id":"lv_1_73","topic":"Job Seeking and Work","word":"portuguese","pos":"(adj)","ipa":"/ˌpɔːr.tʃəˈɡiːz/","defVi":"thuộc về Bồ Đào Nha, tiếng Bồ Đào Nha hoặc người Bồ Đào Nha","defEn":"relating to Portugal, its people, or its language","examples":["We enjoyed traditional [Portuguese] cuisine during our vacation in Lisbon. (=Dịch: Chúng tôi đã thưởng thức ẩm thực Bồ Đào Nha truyền thống trong kỳ nghỉ ở Lisbon.)","Many historical documents from the colonial era were written in the [Portuguese] language. (=Dịch: Nhiều tài liệu lịch sử từ thời thuộc địa được viết bằng tiếng Bồ Đào Nha.)","He is studying the impact of [Portuguese] architecture on coastal cities in Asia. (=Dịch: Anh ấy đang nghiên cứu tác động của kiến trúc Bồ Đào Nha đối với các thành phố ven biển ở châu Á.)"],"ukAudio":"/ai_services/tts3/?q=portuguese&lang=en-GB&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1i%CB%90z%2F","usAudio":"/ai_services/tts3/?q=portuguese&lang=en-US&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1i%CB%90z%2F"},{"id":"lv_1_74","topic":"Job Seeking and Work","word":"premise","pos":"(n)","ipa":"/ˈprem.ɪs/","defVi":"tiền đề, giả định cơ sở","defEn":"a statement or idea that is accepted as true and forms the basis for an argument","examples":["The entire scientific theory is built on a false [premise]. (=Dịch: Toàn bộ lý thuyết khoa học này được xây dựng trên một tiền đề sai lầm.)","His argument starts from the basic [premise] that education should be free for all. (=Dịch: Lập luận của anh ấy bắt đầu từ tiền đề cơ bản rằng giáo dục nên miễn phí cho tất cả mọi người.)","If we accept your [premise], then the logical conclusion is undeniable. (=Dịch: Nếu chúng ta chấp nhận tiền đề của bạn, thì kết luận hợp logic là không thể chối cãi.)"],"ukAudio":"/ai_services/tts3/?q=premise&lang=en-GB&ipa=%2F%CB%88prem.%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=premise&lang=en-US&ipa=%2F%CB%88prem.%C9%AAs%2F"},{"id":"lv_1_75","topic":"Job Seeking and Work","word":"profit","pos":"(n)","ipa":"/ˈprɑː.fɪt/","defVi":"lợi nhuận, tiền lãi","defEn":"money gained in business activities after paying all costs and expenses","examples":["The startup turned a modest [profit] during its second year of operation. (=Dịch: Công ty khởi nghiệp đã đạt được một khoản lợi nhuận khiêm tốn trong năm hoạt động thứ hai.)","They sold the renovated property at a significant [profit]. (=Dịch: Họ đã bán bất động sản sau khi cải tạo với một khoản lợi nhuận đáng kể.)","A portion of the annual [profit] is reinvested into research and development. (=Dịch: Một phần lợi nhuận hàng năm được tái đầu tư vào nghiên cứu và phát triển.)"],"ukAudio":"/ai_services/tts3/?q=profit&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=profit&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F"},{"id":"lv_1_76","topic":"Job Seeking and Work","word":"psychology","pos":"(n)","ipa":"/saɪˈkɑː.lə.dʒi/","defVi":"tâm lý học","defEn":"the scientific study of the human mind and behavior","examples":["She decided to major in [psychology] to better understand human behavior. (=Dịch: Cô ấy quyết định học chuyên ngành tâm lý học để hiểu rõ hơn về hành vi của con người.)","Educational [psychology] plays a crucial role in designing effective teaching methods. (=Dịch: Tâm lý học giáo dục đóng vai trò quan trọng trong việc thiết kế các phương pháp giảng dạy hiệu quả.)","Understanding consumer [psychology] helps companies create more persuasive advertisements. (=Dịch: Hiểu được tâm lý người tiêu dùng giúp các công ty tạo ra những quảng cáo có sức thuyết phục hơn.)"],"ukAudio":"/ai_services/tts3/?q=psychology&lang=en-GB&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=psychology&lang=en-US&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_1_77","topic":"Job Seeking and Work","word":"receptionist","pos":"(n)","ipa":"/rɪˈsep.ʃən.ɪst/","defVi":"nhân viên lễ tân","defEn":"a person whose job is to greet visitors and answer phone calls in an office or hotel","examples":["The [receptionist] greeted the guests warmly and asked them to sign the visitor log. (=Dịch: Nhân viên lễ tân niềm nở chào đón khách và đề nghị họ ký vào sổ khách đến thăm.)","Please leave your room key with the hotel [receptionist] before checking out. (=Dịch: Vui lòng gửi lại chìa khóa phòng cho lễ tân khách sạn trước khi làm thủ tục trả phòng.)","The clinic is looking for a bilingual [receptionist] to manage patient appointments. (=Dịch: Phòng khám đang tìm kiếm một nhân viên tiếp tân song ngữ để quản lý lịch hẹn của bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=receptionist&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sep.%CA%83%C9%99n.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=receptionist&lang=en-US&ipa=%2Fr%C9%AA%CB%88sep.%CA%83%C9%99n.%C9%AAst%2F"},{"id":"lv_1_78","topic":"Job Seeking and Work","word":"recover","pos":"(v)","ipa":"/rɪˈkʌv.ɚ/","defVi":"hồi phục, bình phục","defEn":"to get well again after being sick, hurt, or experiencing a difficult situation","examples":["It took her several weeks to [recover] from the flu. (=Dịch: Cô ấy đã mất vài tuần để hồi phục sau trận cảm cúm.)","The economy is beginning to [recover] after the recession. (=Dịch: Nền kinh tế đang bắt đầu phục hồi sau cuộc suy thoái.)","He needs time to [recover] his strength after the surgery. (=Dịch: Anh ấy cần thời gian để phục hồi thể lực sau ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=recover&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=recover&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%9A%2F"},{"id":"lv_1_79","topic":"Job Seeking and Work","word":"recruitment","pos":"(n)","ipa":"/rɪˈkrut.mənt/","defVi":"sự tuyển dụng, quá trình tuyển dụng","defEn":"the process of finding and hiring new people to join a company or organization","examples":["The company launched a new [recruitment] drive to attract young graduates. (=Dịch: Công ty đã phát động một đợt tuyển dụng mới nhằm thu hút các sinh viên mới tốt nghiệp.)","She works as a consultant in a large [recruitment] agency. (=Dịch: Cô ấy làm việc với vai trò là chuyên viên tư vấn tại một công ty tuyển dụng lớn.)","The military is facing difficulties with staff [recruitment] this year. (=Dịch: Quân đội đang đối mặt với nhiều khó khăn trong việc tuyển dụng nhân sự trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=recruitment&lang=en-GB&ipa=%2Fr%C9%AA%CB%88krut.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=recruitment&lang=en-US&ipa=%2Fr%C9%AA%CB%88krut.m%C9%99nt%2F"},{"id":"lv_1_80","topic":"Job Seeking and Work","word":"referee","pos":"(n)","ipa":"/ˌref.əˈriː/","defVi":"người giới thiệu, người bảo lãnh (trong hồ sơ xin việc)","defEn":"a person who provides information about your character or abilities for a job or course application","examples":["You need to provide the names and contact details of two academic [referees]. (=Dịch: Bạn cần cung cấp tên và thông tin liên lạc của hai người tham chiếu học thuật.)","My former manager agreed to act as a [referee] for my job application. (=Dịch: Người quản lý cũ của tôi đã đồng ý làm người tham chiếu cho hồ sơ xin việc của tôi.)","The company contacted each [referee] to verify the candidate's work history. (=Dịch: Công ty đã liên hệ với từng người tham chiếu để xác minh lịch sử làm việc của ứng viên.)"],"ukAudio":"/ai_services/tts3/?q=referee&lang=en-GB&ipa=%2F%CB%8Cref.%C9%99%CB%88ri%CB%90%2F","usAudio":"/ai_services/tts3/?q=referee&lang=en-US&ipa=%2F%CB%8Cref.%C9%99%CB%88ri%CB%90%2F"},{"id":"lv_1_81","topic":"Job Seeking and Work","word":"refurbishment","pos":"(n)","ipa":"/riːˈfɝː.bɪʃ.mənt/","defVi":"sự tân trang, sự nâng cấp cải tạo","defEn":"the act of renovating, redecorating, or restoring a building or room","examples":["The library will remain closed for two weeks during the [refurbishment]. (=Dịch: Thư viện sẽ tiếp tục đóng cửa trong hai tuần trong thời gian tân trang.)","The hotel underwent a major [refurbishment] to attract more international tourists. (=Dịch: Khách sạn đã trải qua một đợt nâng cấp lớn để thu hút thêm khách du lịch quốc tế.)","After months of [refurbishment], the old theater reopened with modern facilities. (=Dịch: Sau nhiều tháng tu sửa, nhà hát cũ đã mở cửa trở lại với các cơ sở vật chất hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=refurbishment&lang=en-GB&ipa=%2Fri%CB%90%CB%88f%C9%9D%CB%90.b%C9%AA%CA%83.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=refurbishment&lang=en-US&ipa=%2Fri%CB%90%CB%88f%C9%9D%CB%90.b%C9%AA%CA%83.m%C9%99nt%2F"},{"id":"lv_1_82","topic":"Job Seeking and Work","word":"register","pos":"(v)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"đăng ký, ghi danh","defEn":"to officially record a name or information on a list","examples":["Students must [register] for their exams before the end of the week. (=Dịch: Học sinh phải đăng ký dự thi trước cuối tuần này.)","You can [register] a new business online in just a few minutes. (=Dịch: Bạn có thể đăng ký doanh nghiệp mới trực tuyến chỉ trong vài phút.)","Don't forget to [register] your luggage at the check-in desk. (=Dịch: Đừng quên gửi ký gửi hành lý của bạn tại quầy làm thủ tục.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_1_83","topic":"Job Seeking and Work","word":"registration","pos":"(n)","ipa":"/ˌredʒ.əˈstreɪ.ʃən/","defVi":"sự đăng ký, việc vào sổ","defEn":"the act of recording a name or information on an official list","examples":["Course [registration] must be completed before the end of the week. (=Dịch: Việc đăng ký khóa học phải được hoàn thành trước cuối tuần này.)","Please show your vehicle [registration] documents to the officer. (=Dịch: Vui lòng xuất trình giấy tờ đăng ký xe của bạn cho viên chức kiểm tra.)","Online [registration] for the marathon opens tomorrow morning. (=Dịch: Cổng đăng ký trực tuyến cho giải chạy marathon sẽ mở vào sáng mai.)"],"ukAudio":"/ai_services/tts3/?q=registration&lang=en-GB&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=registration&lang=en-US&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_84","topic":"Job Seeking and Work","word":"satisfaction","pos":"(n)","ipa":"/ˌsæt̬.əsˈfæk.ʃən/","defVi":"sự hài lòng, sự thỏa mãn","defEn":"a pleasant feeling of contentment when you have achieved or received what you wanted","examples":["Customer [satisfaction] is the main priority of our company. (=Dịch: Sự hài lòng của khách hàng là ưu tiên hàng đầu của công ty chúng tôi.)","She gets immense job [satisfaction] from helping people in need. (=Dịch: Cô ấy cảm nhận được sự thỏa mãn to lớn trong công việc từ việc giúp đỡ những người gặp khó khăn.)","He looked at his completed painting with a sense of [satisfaction]. (=Dịch: Anh ấy nhìn vào bức tranh đã hoàn thành của mình với một cảm giác hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=satisfaction&lang=en-GB&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%99s%CB%88f%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=satisfaction&lang=en-US&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%99s%CB%88f%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_1_85","topic":"Job Seeking and Work","word":"shortly","pos":"(adv)","ipa":"/ˈʃɔːrt.li/","defVi":"chẳng bao lâu, sớm, ngay sau đó","defEn":"in a short time; soon","examples":["The train for Manchester will be arriving [shortly]. (=Dịch: Chuyến tàu đi Manchester sẽ đến trong chốc lát nữa.)","He graduated from university and [shortly] afterward landed his dream job. (=Dịch: Anh ấy tốt nghiệp đại học và không lâu sau đó đã có được công việc mơ ước.)","The doctor will be with you [shortly], so please take a seat in the waiting room. (=Dịch: Bác sĩ sẽ đến khám cho bạn ngay, vì vậy xin vui lòng ngồi chờ ở phòng đợi.)"],"ukAudio":"/ai_services/tts3/?q=shortly&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%94%CB%90rt.li%2F","usAudio":"/ai_services/tts3/?q=shortly&lang=en-US&ipa=%2F%CB%88%CA%83%C9%94%CB%90rt.li%2F"},{"id":"lv_1_86","topic":"Job Seeking and Work","word":"slicer","pos":"(n)","ipa":"/ˈslaɪ.sɚ/","defVi":"máy cắt lát, dụng cụ thái lát","defEn":"a machine or tool used for cutting food into thin pieces","examples":["The butcher used an electric meat [slicer] to prepare the ham. (=Dịch: Người bán thịt đã sử dụng máy thái thịt chạy điện để chuẩn bị phần giăm bông.)","Be careful when cleaning the blade of the vegetable [slicer]. (=Dịch: Hãy cẩn thận khi vệ sinh lưỡi dao của dụng cụ cắt gọt rau củ.)","A high-quality bread [slicer] will give you perfectly even pieces. (=Dịch: Một chiếc máy cắt bánh mì chất lượng cao sẽ giúp bạn có được những lát bánh đều đẹp hoàn hảo.)"],"ukAudio":"/ai_services/tts3/?q=slicer&lang=en-GB&ipa=%2F%CB%88sla%C9%AA.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=slicer&lang=en-US&ipa=%2F%CB%88sla%C9%AA.s%C9%9A%2F"},{"id":"lv_1_87","topic":"Job Seeking and Work","word":"spanish","pos":"(adj)","ipa":"/ˈspæn.ɪʃ/","defVi":"(thuộc) Tây Ban Nha, tiếng Tây Ban Nha","defEn":"relating to Spain, its people, or its language","examples":["We had dinner at a traditional [Spanish] restaurant last night. (=Dịch: Chúng tôi đã ăn tối tại một nhà hàng Tây Ban Nha truyền thống vào tối qua.)","He is fluent in both English and [Spanish]. (=Dịch: Anh ấy thông thạo cả tiếng Anh lẫn tiếng Tây Ban Nha.)","The gallery features many famous [Spanish] paintings. (=Dịch: Phòng trưng bày giới thiệu nhiều bức tranh Tây Ban Nha nổi tiếng.)"],"ukAudio":"/ai_services/tts3/?q=spanish&lang=en-GB&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=spanish&lang=en-US&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F"},{"id":"lv_1_88","topic":"Job Seeking and Work","word":"spreadsheet","pos":"(n)","ipa":"/ˈsprɛd.ʃiːt/","defVi":"bảng tính điện tử","defEn":"a computer program or document arranged in a grid of rows and columns, used for calculations","examples":["She entered all the monthly expenses into an Excel [spreadsheet]. (=Dịch: Cô ấy đã nhập tất cả các khoản chi tiêu hàng tháng vào một bảng tính Excel.)","The accountant used a complex [spreadsheet] to calculate company profits. (=Dịch: Kế toán đã sử dụng một bảng tính phức tạp để tính toán lợi nhuận của công ty.)","You can organize customer contact information neatly using a simple [spreadsheet]. (=Dịch: Bạn có thể sắp xếp thông tin liên hệ của khách hàng một cách ngăn nắp bằng một bảng tính đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=spreadsheet&lang=en-GB&ipa=%2F%CB%88spr%C9%9Bd.%CA%83i%CB%90t%2F","usAudio":"/ai_services/tts3/?q=spreadsheet&lang=en-US&ipa=%2F%CB%88spr%C9%9Bd.%CA%83i%CB%90t%2F"},{"id":"lv_1_89","topic":"Job Seeking and Work","word":"staffroom","pos":"(n)","ipa":"/ˈstæf.rum/","defVi":"phòng nghỉ của nhân viên, phòng giáo viên","defEn":"a room in a school or office where employees can relax or work","examples":["Teachers usually gather in the [staffroom] during break times. (=Dịch: Các giáo viên thường tụ họp trong phòng nghỉ giáo viên vào giờ giải lao.)","The memo was pinned on the noticeboard in the [staffroom]. (=Dịch: Bản thông báo đã được ghim trên bảng tin trong phòng giáo viên.)","There is a coffee machine and a microwave in the [staffroom]. (=Dịch: Có một máy pha cà phê và một lò vi sóng trong phòng giáo viên.)"],"ukAudio":"/ai_services/tts3/?q=staffroom&lang=en-GB&ipa=%2F%CB%88st%C3%A6f.rum%2F","usAudio":"/ai_services/tts3/?q=staffroom&lang=en-US&ipa=%2F%CB%88st%C3%A6f.rum%2F"},{"id":"lv_1_90","topic":"Job Seeking and Work","word":"storeroom","pos":"(n)","ipa":"/ˈstɔːr.ruːm/","defVi":"phòng chứa đồ, kho chứa","defEn":"a room used for storing items, supplies, or goods","examples":["Extra chairs and tables are kept in the basement [storeroom]. (=Dịch: Bàn và ghế dự phòng được cất giữ trong phòng kho dưới tầng hầm.)","The manager went into the [storeroom] to check the inventory. (=Dịch: Người quản lý đã vào nhà kho để kiểm tra hàng tồn kho.)","We cleaned out the [storeroom] to make space for new equipment. (=Dịch: Chúng tôi đã dọn sạch nhà kho để lấy chỗ chứa thiết bị mới.)"],"ukAudio":"/ai_services/tts3/?q=storeroom&lang=en-GB&ipa=%2F%CB%88st%C9%94%CB%90r.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=storeroom&lang=en-US&ipa=%2F%CB%88st%C9%94%CB%90r.ru%CB%90m%2F"},{"id":"lv_1_91","topic":"Job Seeking and Work","word":"straightaway","pos":"(adv)","ipa":"/ˌstreɪt.əˈweɪ/","defVi":"ngay lập tức, lập tức","defEn":"without delay; immediately","examples":["When she heard the alarm, she called the police [straightaway]. (=Dịch: Khi nghe thấy tiếng chuông báo động, cô ấy đã gọi cảnh sát ngay lập tức.)","If you notice any symptoms, consult a doctor [straightaway]. (=Dịch: Nếu bạn nhận thấy bất kỳ triệu chứng nào, hãy đến khám bác sĩ ngay lập tức.)","I will send you the confirmation email [straightaway]. (=Dịch: Tôi sẽ gửi cho bạn email xác nhận ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=straightaway&lang=en-GB&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=straightaway&lang=en-US&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F"},{"id":"lv_1_92","topic":"Job Seeking and Work","word":"strike","pos":"(n)","ipa":"/straɪk/","defVi":"cuộc đình công, bãi công","defEn":"a refusal to work organized by a body of employees as a form of protest","examples":["Train drivers have voted to go on [strike] next Monday. (=Dịch: Các lái tàu đã bỏ phiếu quyết định đình công vào thứ Hai tới.)","The factory workers called a [strike] over unfair pay. (=Dịch: Các công nhân nhà máy đã kêu gọi một cuộc đình công vì vấn đề trả lương không công bằng.)","The national transport [strike] caused massive traffic disruptions. (=Dịch: Cuộc đình công ngành giao thông vận tải toàn quốc đã gây ra tình trạng gián đoạn giao thông nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=strike&lang=en-GB&ipa=%2Fstra%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=strike&lang=en-US&ipa=%2Fstra%C9%AAk%2F"},{"id":"lv_1_93","topic":"Job Seeking and Work","word":"supervisor","pos":"(n)","ipa":"/ˈsuː.pər.vaɪ.zər/","defVi":"người giám sát, cấp trên trực tiếp","defEn":"a person who manages or oversees other people or activities in a workplace","examples":["If you encounter any technical issues, please notify your [supervisor] immediately. (=Dịch: Nếu bạn gặp bất kỳ sự cố kỹ thuật nào, vui lòng thông báo ngay cho người giám sát của bạn.)","Her [supervisor] provided helpful feedback on the draft report. (=Dịch: Người giám sát của cô ấy đã đưa ra những nhận xét hữu ích về bản dự thảo báo cáo.)","He meets with his research [supervisor] once a week to discuss his progress. (=Dịch: Anh ấy gặp người hướng dẫn nghiên cứu của mình mỗi tuần một lần để thảo luận về tiến độ.)"],"ukAudio":"/ai_services/tts3/?q=supervisor&lang=en-GB&ipa=%2F%CB%88su%CB%90.p%C9%99r.va%C9%AA.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=supervisor&lang=en-US&ipa=%2F%CB%88su%CB%90.p%C9%99r.va%C9%AA.z%C9%99r%2F"},{"id":"lv_1_94","topic":"Job Seeking and Work","word":"sushi","pos":"(n)","ipa":"/ˈsuː.ʃi/","defVi":"món sushi","defEn":"a Japanese dish of cold cooked rice flavored with vinegar, typically garnished with raw seafood and vegetables","examples":["We decided to order fresh [sushi] for dinner tonight. (=Dịch: Chúng tôi quyết định gọi món sushi tươi ngon cho bữa tối nay.)","Learning how to roll [sushi] properly requires patience and practice. (=Dịch: Học cách cuộn sushi đúng chuẩn đòi hỏi sự kiên nhẫn và luyện tập.)","The restaurant is famous for its authentic Japanese [sushi] and sashimi. (=Dịch: Nhà hàng này nổi tiếng với các món sushi và sashimi Nhật Bản chuẩn vị.)"],"ukAudio":"/ai_services/tts3/?q=sushi&lang=en-GB&ipa=%2F%CB%88su%CB%90.%CA%83i%2F","usAudio":"/ai_services/tts3/?q=sushi&lang=en-US&ipa=%2F%CB%88su%CB%90.%CA%83i%2F"},{"id":"lv_1_95","topic":"Job Seeking and Work","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.ə.weɪ/","defVi":"đồ ăn mang về, quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else; a shop that sells such food","examples":["We were too tired to cook, so we picked up a Chinese [takeaway]. (=Dịch: Chúng tôi quá mệt để nấu nướng, vì vậy chúng tôi đã mua đồ ăn Trung Quốc mang về.)","The street is lined with pizza parlors and burger [takeaway] shops. (=Dịch: Con phố có rất nhiều tiệm bánh pizza và cửa hàng bán burger mang về.)","Ordering a [takeaway] on Friday nights has become a family tradition. (=Dịch: Gọi đồ ăn mang về vào tối thứ Sáu đã trở thành một truyền thống của gia đình.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99.we%C9%AA%2F"},{"id":"lv_1_96","topic":"Job Seeking and Work","word":"tax","pos":"(n)","ipa":"/tæks/","defVi":"thuế","defEn":"money paid to the government based on your income or the cost of goods","examples":["The government plans to increase the [tax] on sugary drinks. (=Dịch: Chính phủ có kế hoạch tăng thuế đối với đồ uống có đường.)","Citizens are required by law to pay their income [tax] on time. (=Dịch: Công dân theo luật định phải nộp thuế thu nhập đúng hạn.)","The price of the item includes all local sales [tax]. (=Dịch: Giá của mặt hàng đã bao gồm tất cả các khoản thuế bán hàng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tax&lang=en-GB&ipa=%2Ft%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=tax&lang=en-US&ipa=%2Ft%C3%A6ks%2F"},{"id":"lv_1_97","topic":"Job Seeking and Work","word":"teamwork","pos":"(n)","ipa":"/ˈtiːm.wɝːk/","defVi":"làm việc nhóm, sự phối hợp đồng đội","defEn":"the activity of working together effectively in a group to achieve a goal","examples":["Successful project completion requires effective communication and strong [teamwork]. (=Dịch: Việc hoàn thành dự án thành công đòi hỏi khả năng giao tiếp hiệu quả và tinh thần làm việc nhóm vững chắc.)","The coach praised the players for their outstanding [teamwork] during the final match. (=Dịch: Huấn luyện viên đã khen ngợi các cầu thủ vì tinh thần đồng đội xuất sắc trong trận chung kết.)","Employers often look for candidates with excellent [teamwork] skills. (=Dịch: Các nhà tuyển dụng thường tìm kiếm những ứng viên có kỹ năng làm việc nhóm xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=teamwork&lang=en-GB&ipa=%2F%CB%88ti%CB%90m.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=teamwork&lang=en-US&ipa=%2F%CB%88ti%CB%90m.w%C9%9D%CB%90k%2F"},{"id":"lv_1_98","topic":"Job Seeking and Work","word":"technician","pos":"(n)","ipa":"/tekˈnɪʃ.ən/","defVi":"kỹ thuật viên","defEn":"a worker trained with special skills or knowledge in practical arts or sciences","examples":["A laboratory [technician] analyzed the blood samples carefully. (=Dịch: Một kỹ thuật viên phòng thí nghiệm đã phân tích các mẫu máu một cách cẩn thận.)","We called a [technician] to fix the heating system. (=Dịch: Chúng tôi đã gọi một kỹ thuật viên đến để sửa hệ thống sưởi.)","The IT [technician] helped recover all the deleted files. (=Dịch: Kỹ thuật viên công nghệ thông tin đã giúp khôi phục tất cả các tệp tin bị xóa.)"],"ukAudio":"/ai_services/tts3/?q=technician&lang=en-GB&ipa=%2Ftek%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=technician&lang=en-US&ipa=%2Ftek%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_99","topic":"Job Seeking and Work","word":"telecom","pos":"(n)","ipa":"/ˈtel.ə.kɑːm/","defVi":"viễn thông, ngành viễn thông","defEn":"the industry or technology of communicating over a distance by phone, cable, or satellite","examples":["She has invested in several leading [telecom] companies. (=Dịch: Cô ấy đã đầu tư vào một số công ty viễn thông hàng đầu.)","The government is upgrading the national [telecom] infrastructure. (=Dịch: Chính phủ đang nâng cấp cơ sở hạ tầng viễn thông quốc gia.)","Competition in the mobile [telecom] market has driven prices down. (=Dịch: Sự cạnh tranh trên thị trường viễn thông di động đã kéo giá cước giảm xuống.)"],"ukAudio":"/ai_services/tts3/?q=telecom&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.k%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=telecom&lang=en-US&ipa=%2F%CB%88tel.%C9%99.k%C9%91%CB%90m%2F"},{"id":"lv_1_100","topic":"Job Seeking and Work","word":"temporary","pos":"(adj)","ipa":"/ˈtem.pə.rer.i/","defVi":"tạm thời, nhất thời","defEn":"lasting or intended to last for only a limited period of time","examples":["The museum was closed for [temporary] repairs. (=Dịch: Bảo tàng đã đóng cửa để sửa chữa tạm thời.)","They hired [temporary] staff to cope with the holiday rush. (=Dịch: Họ đã thuê nhân viên tạm thời để giải quyết đợt cao điểm trong kỳ nghỉ lễ.)","This solution is only [temporary] until we find a permanent fix. (=Dịch: Giải pháp này chỉ mang tính tạm thời cho đến khi chúng tôi tìm ra cách khắc phục lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=temporary&lang=en-GB&ipa=%2F%CB%88tem.p%C9%99.rer.i%2F","usAudio":"/ai_services/tts3/?q=temporary&lang=en-US&ipa=%2F%CB%88tem.p%C9%99.rer.i%2F"},{"id":"lv_1_101","topic":"Job Seeking and Work","word":"trousers","pos":"(n)","ipa":"/ˈtraʊ.zɚz/","defVi":"quần dài","defEn":"a piece of clothing worn on the lower part of the body, covering each leg separately","examples":["He wore a pair of dark [trousers] and a white shirt to the interview. (=Dịch: Anh ấy mặc một chiếc quần tây tối màu và áo sơ mi trắng đến buổi phỏng vấn.)","These wool [trousers] are perfect for cold winter days. (=Dịch: Chiếc quần tây bằng len này rất hoàn hảo cho những ngày mùa đông lạnh giá.)","She asked the tailor to shorten her new [trousers]. (=Dịch: Cô ấy đã nhờ thợ may cắt ngắn chiếc quần dài mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=trousers&lang=en-GB&ipa=%2F%CB%88tra%CA%8A.z%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=trousers&lang=en-US&ipa=%2F%CB%88tra%CA%8A.z%C9%9Az%2F"},{"id":"lv_1_102","topic":"Job Seeking and Work","word":"unemployed","pos":"(adj)","ipa":"/ˌʌn.ɪmˈplɔɪd/","defVi":"thất nghiệp","defEn":"without a paid job but available to work","examples":["Many recent graduates find themselves [unemployed] due to a competitive job market. (=Dịch: Nhiều sinh viên mới tốt nghiệp rơi vào cảnh thất nghiệp do thị trường việc làm đầy tính cạnh tranh.)","The government provides financial support to [unemployed] citizens while they seek work. (=Dịch: Chính phủ hỗ trợ tài chính cho các công dân thất nghiệp trong thời gian họ tìm việc làm.)","He has been [unemployed] for six months after the factory closed down. (=Dịch: Anh ấy đã thất nghiệp suốt sáu tháng sau khi nhà máy đóng cửa.)"],"ukAudio":"/ai_services/tts3/?q=unemployed&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unemployed&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AAd%2F"},{"id":"lv_1_103","topic":"Job Seeking and Work","word":"update","pos":"(n)","ipa":"/ˈʌp.deɪt/","defVi":"bản cập nhật, thông tin mới nhất","defEn":"the latest information or a new version of something","examples":["The manager gave us a brief [update] on the progress of the project. (=Dịch: Người quản lý đã cung cấp cho chúng tôi thông tin cập nhật ngắn gọn về tiến độ của dự án.)","Make sure you install the latest software [update] to protect your computer. (=Dịch: Hãy chắc chắn rằng bạn đã cài đặt bản cập nhật phần mềm mới nhất để bảo vệ máy tính của mình.)","We are waiting for an official [update] from the local authorities about the weather. (=Dịch: Chúng tôi đang chờ thông tin cập nhật chính thức từ chính quyền địa phương về tình hình thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=update&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=update&lang=en-US&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F"},{"id":"lv_1_104","topic":"Job Seeking and Work","word":"vacancy","pos":"(n)","ipa":"/ˈveɪ.kən.si/","defVi":"vị trí tuyển dụng, chỗ trống (trong công việc hoặc phòng ở)","defEn":"a job or position that is currently available to be filled","examples":["The company recently posted a job [vacancy] for an experienced accountant. (=Dịch: Công ty gần đây đã đăng tuyển một vị trí còn trống cho một kế toán viên giàu kinh nghiệm.)","Due to rapid business expansion, there is a new [vacancy] in our sales department. (=Dịch: Do sự mở rộng kinh doanh nhanh chóng, phòng kinh doanh của chúng tôi đang có một vị trí tuyển dụng mới.)","The hotel had no [vacancy] left during the peak summer holiday. (=Dịch: Khách sạn không còn phòng trống nào trong kỳ nghỉ hè cao điểm.)"],"ukAudio":"/ai_services/tts3/?q=vacancy&lang=en-GB&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=vacancy&lang=en-US&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F"},{"id":"lv_1_105","topic":"Job Seeking and Work","word":"weekly","pos":"(adj)","ipa":"/ˈwiːk.li/","defVi":"hàng tuần, mỗi tuần một lần","defEn":"happening, done, or published once a week","examples":["Our team holds a [weekly] meeting every Monday morning. (=Dịch: Nhóm chúng tôi tổ chức một cuộc họp hàng tuần vào mỗi sáng thứ Hai.)","The local newspaper publishes a [weekly] sports report. (=Dịch: Tờ báo địa phương xuất bản một bản tin thể thao hàng tuần.)","She receives a [weekly] allowance from her parents for food and travel. (=Dịch: Cô ấy nhận được tiền tiêu vặt hàng tuần từ bố mẹ để chi trả cho ăn uống và đi lại.)"],"ukAudio":"/ai_services/tts3/?q=weekly&lang=en-GB&ipa=%2F%CB%88wi%CB%90k.li%2F","usAudio":"/ai_services/tts3/?q=weekly&lang=en-US&ipa=%2F%CB%88wi%CB%90k.li%2F"},{"id":"lv_1_106","topic":"Job Seeking and Work","word":"wipe","pos":"(v)","ipa":"/waɪp/","defVi":"lau, chùi, xóa sạch","defEn":"to clean or dry something by rubbing a cloth or towel over its surface","examples":["Please [wipe] the kitchen table after finishing your dinner. (=Dịch: Vui lòng lau bàn bếp sau khi ăn tối xong.)","He used a soft cloth to [wipe] the dust off the computer screen. (=Dịch: Anh ấy đã dùng một chiếc khăn mềm để lau sạch bụi trên màn hình máy tính.)","She had to [wipe] away her tears before walking into the interview room. (=Dịch: Cô ấy phải gạt đi những giọt nước mắt trước khi bước vào phòng phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=wipe&lang=en-GB&ipa=%2Fwa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=wipe&lang=en-US&ipa=%2Fwa%C9%AAp%2F"},{"id":"lv_1_107","topic":"Job Seeking and Work","word":"workplace","pos":"(n)","ipa":"/ˈwɜːrk.pleɪs/","defVi":"nơi làm việc, môi trường công sở","defEn":"a building or place where people work","examples":["Modern technology enables employees to collaborate without being in the same physical [workplace]. (=Dịch: Công nghệ hiện đại cho phép nhân viên cộng tác mà không cần phải ở cùng một nơi làm việc cụ thể.)","Companies must establish strict safety standards to prevent accidents in the [workplace]. (=Dịch: Các công ty phải thiết lập các tiêu chuẩn an toàn nghiêm ngặt để ngăn ngừa tai nạn tại nơi làm việc.)","A supportive [workplace] environment can significantly boost staff morale and productivity. (=Dịch: Một môi trường làm việc mang tính hỗ trợ có thể nâng cao đáng kể tinh thần và năng suất của nhân viên.)"],"ukAudio":"/ai_services/tts3/?q=workplace&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90rk.ple%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=workplace&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90rk.ple%C9%AAs%2F"},{"id":"lv_2_0","topic":"Tourism and Visits","word":"alley","pos":"(n)","ipa":"/ˈæl.i/","defVi":"con hẻm, ngõ nhỏ","defEn":"a narrow passageway between buildings","examples":["The cat slipped into a dark [alley] behind the restaurant. (=Dịch: Con mèo lẻn vào một con hẻm tối phía sau nhà hàng.)","There is a charming little coffee shop hidden in this [alley]. (=Dịch: Có một quán cà phê nhỏ xinh xắn ẩn mình trong con hẻm này.)","Tourists were advised not to walk down the deserted [alley] at night. (=Dịch: Khách du lịch được khuyên không nên đi vào con hẻm vắng vẻ vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=alley&lang=en-GB&ipa=%2F%CB%88%C3%A6l.i%2F","usAudio":"/ai_services/tts3/?q=alley&lang=en-US&ipa=%2F%CB%88%C3%A6l.i%2F"},{"id":"lv_2_1","topic":"Tourism and Visits","word":"approx","pos":"(adj)","ipa":"/əˈprɑːks/","defVi":"xấp xỉ, khoảng chừng (viết tắt của approximate)","defEn":"short form for approximate; roughly correct or close to the actual number","examples":["The [approx] cost of the flight is around three hundred dollars. (=Dịch: Chi phí xấp xỉ của chuyến bay là khoảng ba trăm đô la.)","Please write down the [approx] arrival time on the registration form. (=Dịch: Vui lòng ghi lại thời gian đến ước tính vào mẫu đăng ký.)","The table shows the [approx] number of visitors each month. (=Dịch: Bảng hiển thị số lượng khách tham quan ước tính mỗi tháng.)"],"ukAudio":"/ai_services/tts3/?q=approx&lang=en-GB&ipa=%2F%C9%99%CB%88pr%C9%91%CB%90ks%2F","usAudio":"/ai_services/tts3/?q=approx&lang=en-US&ipa=%2F%C9%99%CB%88pr%C9%91%CB%90ks%2F"},{"id":"lv_2_2","topic":"Tourism and Visits","word":"aquarium","pos":"(n)","ipa":"/əˈkwer.i.əm/","defVi":"thủy cung, bể cá","defEn":"a building or large glass container where fish and other water creatures are kept and displayed","examples":["The children were excited to visit the city [aquarium] to see sharks. (=Dịch: Những đứa trẻ rất hào hứng khi được đến thăm thủy cung thành phố để ngắm cá mập.)","He keeps several colorful tropical fish in a small [aquarium] in his living room. (=Dịch: Anh ấy nuôi vài con cá nhiệt đới sặc sỡ trong một bể cá nhỏ ở phòng khách.)","The public [aquarium] plays a vital role in marine education and conservation. (=Dịch: Thủy cung công cộng đóng vai trò thiết yếu trong việc giáo dục và bảo tồn sinh vật biển.)"],"ukAudio":"/ai_services/tts3/?q=aquarium&lang=en-GB&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=aquarium&lang=en-US&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F"},{"id":"lv_2_3","topic":"Tourism and Visits","word":"arrow","pos":"(n)","ipa":"/ˈer.oʊ/","defVi":"mũi tên","defEn":"a thin straight weapon shot from a bow, or a symbol used to show direction","examples":["Follow the green [arrow] on the floor to find the exit. (=Dịch: Hãy đi theo mũi tên màu xanh lá cây trên sàn để tìm lối ra.)","The archer placed an [arrow] on the bowstring and aimed carefully. (=Dịch: Người bắn cung đặt một mũi tên lên dây cung và nhắm cẩn thận.)","A red [arrow] indicated that traffic was not allowed to turn right. (=Dịch: Mũi tên màu đỏ chỉ ra rằng các phương tiện giao thông không được phép rẽ phải.)"],"ukAudio":"/ai_services/tts3/?q=arrow&lang=en-GB&ipa=%2F%CB%88er.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=arrow&lang=en-US&ipa=%2F%CB%88er.o%CA%8A%2F"},{"id":"lv_2_4","topic":"Tourism and Visits","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"điểm thu hút, điểm tham quan hấp dẫn","defEn":"an interesting or enjoyable place or feature that draws people to visit","examples":["The ancient temple is the main tourist [attraction] in this town. (=Dịch: Ngôi đền cổ kính là điểm thu hút khách du lịch chính tại thị trấn này.)","Theme parks offer a wide variety of rides and [attractions] for families. (=Dịch: Các công viên giải trí cung cấp nhiều trò chơi và điểm tham quan đa dạng cho các gia đình.)","The historical museum has become a popular [attraction] for students. (=Dịch: Bảo tàng lịch sử đã trở thành một điểm đến phổ biến đối với học sinh, sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_2_5","topic":"Tourism and Visits","word":"audio","pos":"(adj)","ipa":"/ˈɑː.di.oʊ/","defVi":"(thuộc) âm thanh","defEn":"connected with recorded sound or the transmission of sound","examples":["Students can listen to the [audio] recording to practice their listening skills. (=Dịch: Học sinh có thể nghe đoạn ghi âm để luyện tập kỹ năng nghe của mình.)","The museum provides a free [audio] tour in several languages. (=Dịch: Bảo tàng cung cấp tour thuyết minh bằng âm thanh miễn phí bằng nhiều thứ tiếng.)","The video had clear pictures, but the [audio] quality was quite poor. (=Dịch: Video có hình ảnh rõ nét, nhưng chất lượng âm thanh lại khá kém.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F"},{"id":"lv_2_6","topic":"Tourism and Visits","word":"barn","pos":"(n)","ipa":"/bɑːrn/","defVi":"chuồng trại, kho thóc","defEn":"a large farm building used for storing crops or keeping animals","examples":["The farmer gathered the cows and led them into the [barn] for the night. (=Dịch: Người nông dân lùa đàn bò lại và dẫn chúng vào chuồng để qua đêm.)","They converted the old wooden [barn] into a modern event venue. (=Dịch: Họ đã cải tạo nhà kho bằng gỗ cũ thành một địa điểm tổ chức sự kiện hiện đại.)","Piles of dry hay were neatly stacked inside the [barn]. (=Dịch: Những đống cỏ khô được xếp ngay ngắn bên trong nhà kho.)"],"ukAudio":"/ai_services/tts3/?q=barn&lang=en-GB&ipa=%2Fb%C9%91%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=barn&lang=en-US&ipa=%2Fb%C9%91%CB%90rn%2F"},{"id":"lv_2_7","topic":"Tourism and Visits","word":"basket","pos":"(n)","ipa":"/ˈbæs.kɪt/","defVi":"cái rổ, cái giỏ","defEn":"a container made of woven strips of cane, wire, or plastic, often used for carrying things","examples":["She filled her woven [basket] with fresh apples picked from the orchard. (=Dịch: Cô chất đầy chiếc giỏ đan bằng những quả táo tươi hái từ vườn cây ăn quả.)","Don't forget to put dirty clothes into the laundry [basket]. (=Dịch: Đừng quên cho quần áo bẩn vào giỏ đựng đồ giặt.)","The delivery cyclist carried a metal [basket] attached to the front handlebars. (=Dịch: Người đi xe đạp giao hàng mang theo một chiếc giỏ kim loại gắn vào ghi-đông phía trước.)"],"ukAudio":"/ai_services/tts3/?q=basket&lang=en-GB&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=basket&lang=en-US&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F"},{"id":"lv_2_8","topic":"Tourism and Visits","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a part of the coast where the land curves inward to form an open body of water","examples":["Several fishing boats were anchored peacefully in the sheltered [bay]. (=Dịch: Vài chiếc thuyền đánh cá đang neo đậu yên bình trong vùng vịnh kín gió.)","The resort hotel offers stunning panoramic views across the [bay]. (=Dịch: Khách sạn nghỉ dưỡng có tầm nhìn toàn cảnh tuyệt đẹp ra khắp vịnh.)","We went sailing around the [bay] on a sunny afternoon. (=Dịch: Chúng tôi đã đi chèo thuyền buồm quanh vịnh vào một buổi chiều đầy nắng.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_2_9","topic":"Tourism and Visits","word":"bc","pos":"(adv)","ipa":"/ˌbiː ˈsiː/","defVi":"trước Công nguyên (TCN)","defEn":"used after a date to refer to the years before the birth of Jesus Christ (Before Christ)","examples":["The great pyramid was built around 2560 [BC]. (=Dịch: Đại kim tự tháp được xây dựng vào khoảng năm 2560 trước Công nguyên.)","The ancient civilization flourished during the fifth century [BC]. (=Dịch: Nền văn minh cổ đại đã phát triển rực rỡ trong thế kỷ thứ năm trước Công nguyên.)","Historians believe the city was founded in 753 [BC]. (=Dịch: Các nhà sử học tin rằng thành phố được thành lập vào năm 753 trước Công nguyên.)"],"ukAudio":"/ai_services/tts3/?q=bc&lang=en-GB&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F","usAudio":"/ai_services/tts3/?q=bc&lang=en-US&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F"},{"id":"lv_2_10","topic":"Tourism and Visits","word":"biking","pos":"(n)","ipa":"/ˈbaɪ.kɪŋ/","defVi":"hoạt động đi xe đạp","defEn":"the activity of riding a bicycle for pleasure, sport, or transport","examples":["Mountain [biking] has become a very popular outdoor sport among teenagers. (=Dịch: Đạp xe leo núi đã trở thành một môn thể thao ngoài trời rất phổ biến trong giới thanh thiếu niên.)","She goes [biking] along the river every weekend to stay in shape. (=Dịch: Cô ấy đạp xe dọc bờ sông vào mỗi cuối tuần để giữ gìn vóc dáng.)","The city added more lanes to encourage [biking] instead of driving cars. (=Dịch: Thành phố đã bổ sung thêm nhiều làn đường để khuyến khích việc đi xe đạp thay vì lái xe ô tô.)"],"ukAudio":"/ai_services/tts3/?q=biking&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.k%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=biking&lang=en-US&ipa=%2F%CB%88ba%C9%AA.k%C9%AA%C5%8B%2F"},{"id":"lv_2_11","topic":"Tourism and Visits","word":"bow","pos":"(n)","ipa":"/boʊ/","defVi":"cung tên hoặc nơ (trang trí)","defEn":"a weapon for shooting arrows, or a knot tied with loops used for decoration","examples":["He pulled the string of the [bow] and aimed carefully at the target. (=Dịch: Anh ấy kéo dây cung và nhắm cẩn thận vào mục tiêu.)","She wore a bright red [bow] in her hair for the birthday party. (=Dịch: Cô ấy cài một chiếc nơ màu đỏ tươi trên tóc để dự tiệc sinh nhật.)","The gift box was decorated with a large golden [bow]. (=Dịch: Hộp quà được trang trí bằng một chiếc nơ lớn màu vàng kim.)"],"ukAudio":"/ai_services/tts3/?q=bow&lang=en-GB&ipa=%2Fbo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=bow&lang=en-US&ipa=%2Fbo%CA%8A%2F"},{"id":"lv_2_12","topic":"Tourism and Visits","word":"campsite","pos":"(n)","ipa":"/ˈkæmp.saɪt/","defVi":"địa điểm cắm trại, khu cắm trại","defEn":"a piece of land where people can set up tents or park caravans for camping","examples":["We arrived at the [campsite] just before the sun began to set. (=Dịch: Chúng tôi đến khu cắm trại ngay trước khi mặt trời bắt đầu lặn.)","The [campsite] provides clean running water and basic cooking facilities. (=Dịch: Khu cắm trại cung cấp nước máy sạch và các tiện nghi nấu nướng cơ bản.)","You need to book your spot at the [campsite] weeks in advance during summer. (=Dịch: Bạn cần phải đặt chỗ tại khu cắm trại trước nhiều tuần vào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=campsite&lang=en-GB&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=campsite&lang=en-US&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F"},{"id":"lv_2_13","topic":"Tourism and Visits","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"Canada (quốc gia ở Bắc Mỹ)","defEn":"a large country located in the northern part of North America","examples":["Many international students choose to study in [Canada] for its high-quality education. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Canada vì nền giáo dục chất lượng cao của đất nước này.)","Winters in [Canada] can be extremely cold and snowy. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá và nhiều tuyết.)","He decided to immigrate to [Canada] with his family last year. (=Dịch: Anh ấy đã quyết định cùng gia đình nhập cư sang Canada vào năm ngoái.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_2_14","topic":"Tourism and Visits","word":"cart","pos":"(n)","ipa":"/kɑːrt/","defVi":"xe đẩy hàng, xe kéo","defEn":"a small vehicle with wheels that is pulled or pushed by a person, animal, or machine","examples":["She filled her shopping [cart] with fresh fruits and vegetables. (=Dịch: Cô ấy chất đầy trái cây và rau củ tươi vào xe đẩy mua sắm của mình.)","The farmer used a wooden [cart] pulled by a horse to transport hay. (=Dịch: Người nông dân đã dùng một chiếc xe kéo bằng gỗ do ngựa kéo để vận chuyển cỏ khô.)","Hotel staff loaded our luggage onto a luggage [cart] and brought it to our room. (=Dịch: Nhân viên khách sạn đã xếp hành lý của chúng tôi lên xe đẩy hành lý và mang lên phòng cho chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=cart&lang=en-GB&ipa=%2Fk%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=cart&lang=en-US&ipa=%2Fk%C9%91%CB%90rt%2F"},{"id":"lv_2_15","topic":"Tourism and Visits","word":"cave","pos":"(n)","ipa":"/keɪv/","defVi":"hang, hang động","defEn":"a large natural hole in the side of a cliff, hill, or under the ground","examples":["The hikers found shelter in a dry [cave] when the heavy rain started. (=Dịch: Những người đi bộ đường dài đã tìm nơi trú ẩn trong một hang động khô ráo khi cơn mưa lớn bắt đầu đổ xuống.)","Scientists discovered ancient paintings on the walls of the [cave]. (=Dịch: Các nhà khoa học đã phát hiện ra những bức tranh cổ trên vách hang động.)","Bears often hibernate inside a dark [cave] during the cold winter months. (=Dịch: Gấu thường ngủ đông bên trong một hang động tối tăm suốt những tháng mùa đông lạnh giá.)"],"ukAudio":"/ai_services/tts3/?q=cave&lang=en-GB&ipa=%2Fke%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cave&lang=en-US&ipa=%2Fke%C9%AAv%2F"},{"id":"lv_2_16","topic":"Tourism and Visits","word":"cliff","pos":"(n)","ipa":"/klɪf/","defVi":"vách đá dốc, vách núi","defEn":"a high area of rock with a very steep side, often near the sea","examples":["They stood on the edge of the high [cliff] looking out over the ocean. (=Dịch: Họ đứng trên mép của vách đá cao và phóng tầm mắt nhìn ra đại dương.)","Warning signs were placed near the [cliff] to prevent tourists from falling. (=Dịch: Các biển cảnh báo đã được đặt gần vách đá để ngăn du khách bị trượt chân ngã.)","Seabirds build their nests safely on the narrow ledges of the [cliff]. (=Dịch: Các loài chim biển làm tổ an toàn trên những gờ hẹp của vách đá.)"],"ukAudio":"/ai_services/tts3/?q=cliff&lang=en-GB&ipa=%2Fkl%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=cliff&lang=en-US&ipa=%2Fkl%C9%AAf%2F"},{"id":"lv_2_17","topic":"Tourism and Visits","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng gửi áo khoác và hành lý","defEn":"a room in a public building where people can leave their coats and bags","examples":["Please leave your heavy coats and backpacks in the [cloakroom] before entering the gallery. (=Dịch: Vui lòng để lại áo khoác dày và ba lô trong phòng giữ đồ trước khi vào phòng trưng bày.)","The theater attendant gave her a ticket after taking her coat at the [cloakroom]. (=Dịch: Nhân viên nhà hát đã đưa cho cô ấy một chiếc vé sau khi nhận áo khoác của cô ở phòng giữ đồ.)","There was a long line at the [cloakroom] after the concert ended. (=Dịch: Có một hàng dài người chờ ở phòng giữ đồ sau khi buổi hòa nhạc kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_2_18","topic":"Tourism and Visits","word":"cloth","pos":"(n)","ipa":"/klɔːθ/","defVi":"vải, mảnh vải (để lau chùi hoặc may mặc)","defEn":"material made by weaving cotton, wool, or other fibers, used for making clothes or covers","examples":["She used a damp [cloth] to wipe the dust off the wooden table. (=Dịch: Cô ấy dùng một chiếc khăn ẩm để lau sạch bụi bám trên bàn gỗ.)","This expensive [cloth] is made from pure natural silk. (=Dịch: Loại vải đắt tiền này được làm từ lụa tự nhiên nguyên chất.)","He wrapped the fragile glass vase in a soft piece of [cloth]. (=Dịch: Anh ấy đã bọc chiếc bình thủy tinh dễ vỡ trong một mảnh vải mềm.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F"},{"id":"lv_2_19","topic":"Tourism and Visits","word":"coastline","pos":"(n)","ipa":"/ˈkoʊst.laɪn/","defVi":"đường bờ biển","defEn":"the boundary where the land meets the sea or ocean","examples":["Vietnam has a long [coastline] with many beautiful sandy beaches. (=Dịch: Việt Nam có đường bờ biển dài với nhiều bãi biển cát trắng tuyệt đẹp.)","Severe storms have caused significant erosion along the southern [coastline]. (=Dịch: Những cơn bão dữ dội đã gây ra sự xói mòn nghiêm trọng dọc theo đường bờ biển phía nam.)","We drove along the scenic [coastline] and enjoyed the stunning ocean views. (=Dịch: Chúng tôi đã lái xe dọc theo đường bờ biển tuyệt đẹp và thưởng ngoạn khung cảnh đại dương tuyệt trần.)"],"ukAudio":"/ai_services/tts3/?q=coastline&lang=en-GB&ipa=%2F%CB%88ko%CA%8Ast.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coastline&lang=en-US&ipa=%2F%CB%88ko%CA%8Ast.la%C9%AAn%2F"},{"id":"lv_2_20","topic":"Tourism and Visits","word":"commentary","pos":"(n)","ipa":"/ˈkɑː.mən.ter.i/","defVi":"lời bình luận, tường thuật trực tiếp","defEn":"a spoken or written description and analysis of an event or topic as it happens","examples":["The sports journalist provided live [commentary] during the final match. (=Dịch: Nhà báo thể thao đã bình luận trực tiếp trong suốt trận chung kết.)","Her political [commentary] is published weekly in the local newspaper. (=Dịch: Bài bình luận chính trị của bà được xuất bản hàng tuần trên tờ báo địa phương.)","The museum audio guide offers detailed [commentary] on each art piece. (=Dịch: Thiết bị thuyết minh tự động của bảo tàng cung cấp lời bình giải chi tiết về từng tác phẩm nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=commentary&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F","usAudio":"/ai_services/tts3/?q=commentary&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F"},{"id":"lv_2_21","topic":"Tourism and Visits","word":"compass","pos":"(n)","ipa":"/ˈkʌm.pəs/","defVi":"la bàn","defEn":"an instrument containing a magnetized pointer that shows the direction of magnetic north","examples":["Hikers should always carry a map and a [compass] when exploring remote trails. (=Dịch: Người đi bộ đường dài nên luôn mang theo bản đồ và la bàn khi khám phá những con đường mòn hẻo lánh.)","The sailor checked the ship's [compass] to make sure they were heading north. (=Dịch: Người thủy thủ đã kiểm tra la bàn của tàu để đảm bảo họ đang đi về hướng bắc.)","He used a [compass] to navigate through the dense forest. (=Dịch: Anh ấy đã dùng la bàn để định hướng băng qua khu rừng rậm rạp.)"],"ukAudio":"/ai_services/tts3/?q=compass&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=compass&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F"},{"id":"lv_2_22","topic":"Tourism and Visits","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or company that competes against others","examples":["Each [competitor] in the marathon trained hard for several months. (=Dịch: Mỗi vận động viên trong cuộc chạy marathon đều đã tập luyện chăm chỉ trong nhiều tháng.)","The tech firm lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty công nghệ đã hạ giá để duy trì vị thế dẫn trước đối thủ cạnh tranh chính của mình.)","Judges evaluated every [competitor] based on creativity and technique. (=Dịch: Ban giám khảo đã đánh giá từng thí sinh dựa trên tính sáng tạo và kỹ thuật.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_2_23","topic":"Tourism and Visits","word":"conservatory","pos":"(n)","ipa":"/kənˈsɝː.və.tɔːr.i/","defVi":"nhà kính trồng cây; nhạc viện","defEn":"a glass room used to grow plants, or a school specializing in music and the arts","examples":["They enjoyed their morning coffee sitting in the sunny [conservatory]. (=Dịch: Họ thưởng thức cà phê buổi sáng khi ngồi trong nhà kính ngập tràn ánh nắng.)","She studied classical violin at a prestigious music [conservatory]. (=Dịch: Cô ấy đã theo học vĩ cầm cổ điển tại một nhạc viện danh tiếng.)","The botanical garden built a large [conservatory] to protect tropical plants. (=Dịch: Vườn bách thảo đã xây dựng một nhà kính lớn để bảo vệ các loài thực vật nhiệt đới.)"],"ukAudio":"/ai_services/tts3/?q=conservatory&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%9D%CB%90.v%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=conservatory&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%9D%CB%90.v%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_2_24","topic":"Tourism and Visits","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục (biểu diễn, hóa trang hoặc truyền thống)","defEn":"a set of clothes worn by an actor or for a particular occasion or historical period","examples":["The actors spent hours putting on their makeup and [costume] before the play began. (=Dịch: Các diễn viên đã dành hàng giờ để trang điểm và mặc trang phục trước khi vở kịch bắt đầu.)","Children wore a colorful [costume] for the annual Halloween parade. (=Dịch: Trẻ em đã mặc trang phục rực rỡ sắc màu cho buổi diễu hành Halloween thường niên.)","The museum displays traditional folk [costume] from various regions. (=Dịch: Bảo tàng trưng bày trang phục dân gian truyền thống từ nhiều vùng miền khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_2_25","topic":"Tourism and Visits","word":"county","pos":"(n)","ipa":"/ˈkaʊn.t̬i/","defVi":"quận, hạt, tỉnh (đơn vị hành chính)","defEn":"a territorial division of a country or state for administrative purposes","examples":["He was elected as the sheriff of the entire [county]. (=Dịch: Ông được bầu làm cảnh sát trưởng của toàn bộ hạt.)","The [county] council decided to fund the construction of a new library. (=Dịch: Hội đồng hạt đã quyết định cấp kinh phí xây dựng một thư viện mới.)","Many rural schools in this [county] share resources to save money. (=Dịch: Nhiều trường học nông thôn ở hạt này chia sẻ tài nguyên để tiết kiệm chi phí.)"],"ukAudio":"/ai_services/tts3/?q=county&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=county&lang=en-US&ipa=%2F%CB%88ka%CA%8An.t%CC%ACi%2F"},{"id":"lv_2_26","topic":"Tourism and Visits","word":"creature","pos":"(n)","ipa":"/ˈkriː.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"a living being, especially an animal rather than a human or plant","examples":["Deep-sea divers discovered a strange [creature] near the ocean floor. (=Dịch: Những thợ lặn biển sâu đã phát hiện ra một sinh vật kỳ lạ gần đáy đại dương.)","The rainforest is home to many rare [creature] species. (=Dịch: Rừng mưa nhiệt đới là nơi sinh sống của nhiều loài sinh vật quý hiếm.)","Nighttime brings out every nocturnal [creature] in the forest. (=Dịch: Màn đêm đánh thức mọi sinh vật sống về đêm trong khu rừng.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_2_27","topic":"Tourism and Visits","word":"crocodile","pos":"(n)","ipa":"/ˈkrɑː.kə.daɪl/","defVi":"cá sấu","defEn":"a large predatory reptile with a long snout and powerful jaws that lives in tropical wetlands","examples":["A large [crocodile] basked silently in the sun beside the riverbank. (=Dịch: Một con cá sấu lớn lặng lẽ sưởi nắng bên bờ sông.)","Tourists took a boat trip to watch the wild [crocodile] hunt in the marsh. (=Dịch: Khách du lịch đã đi thuyền để quan sát cá sấu hoang dã săn mồi trong đầm lầy.)","Warning signs were placed near the lake to keep people away from any [crocodile]. (=Dịch: Các biển cảnh báo đã được đặt gần hồ để nhắc nhở mọi người tránh xa cá sấu.)"],"ukAudio":"/ai_services/tts3/?q=crocodile&lang=en-GB&ipa=%2F%CB%88kr%C9%91%CB%90.k%C9%99.da%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=crocodile&lang=en-US&ipa=%2F%CB%88kr%C9%91%CB%90.k%C9%99.da%C9%AAl%2F"},{"id":"lv_2_28","topic":"Tourism and Visits","word":"cruise","pos":"(n)","ipa":"/kruːz/","defVi":"chuyến du ngoạn bằng tàu thủy, chuyến du thuyền","defEn":"a vacation trip on a ship or boat that visits several places","examples":["They booked a two-week Caribbean [cruise] to celebrate their anniversary. (=Dịch: Họ đã đặt một chuyến du ngoạn Caribe bằng du thuyền kéo dài hai tuần để kỷ niệm ngày cưới.)","The evening river [cruise] offered beautiful views of the illuminated city skyline. (=Dịch: Chuyến du ngoạn trên sông vào buổi tối mang lại tầm nhìn tuyệt đẹp ngắm toàn cảnh thành phố rực rỡ ánh đèn.)","Passengers enjoyed gourmet meals and live entertainment during the luxury [cruise]. (=Dịch: Hành khách đã thưởng thức những bữa ăn hảo hạng và các chương trình giải trí trực tiếp trong suốt chuyến hải trình sang trọng.)"],"ukAudio":"/ai_services/tts3/?q=cruise&lang=en-GB&ipa=%2Fkru%CB%90z%2F","usAudio":"/ai_services/tts3/?q=cruise&lang=en-US&ipa=%2Fkru%CB%90z%2F"},{"id":"lv_2_29","topic":"Tourism and Visits","word":"dairy","pos":"(n)","ipa":"/ˈder.i/","defVi":"sản phẩm từ sữa; nông trại chế biến sữa","defEn":"food made from milk, or a farm and building where milk and milk products are produced","examples":["People with lactose intolerance must avoid consuming too much [dairy]. (=Dịch: Những người không dung nạp lactose phải tránh tiêu thụ quá nhiều sản phẩm từ sữa.)","The local [dairy] delivers fresh milk and butter to grocery stores every morning. (=Dịch: Cơ sở sản xuất sữa địa phương giao sữa tươi và bơ đến các cửa hàng tạp hóa vào mỗi buổi sáng.)","Cheese and yogurt are rich sources of calcium found in the [dairy] aisle. (=Dịch: Phô mai và sữa chua là những nguồn giàu canxi có thể tìm thấy ở quầy hàng bơ sữa.)"],"ukAudio":"/ai_services/tts3/?q=dairy&lang=en-GB&ipa=%2F%CB%88der.i%2F","usAudio":"/ai_services/tts3/?q=dairy&lang=en-US&ipa=%2F%CB%88der.i%2F"},{"id":"lv_2_30","topic":"Tourism and Visits","word":"daylight","pos":"(n)","ipa":"/ˈdeɪ.laɪt/","defVi":"ánh sáng ban ngày, ban ngày","defEn":"the natural light that comes from the sun during the daytime","examples":["We should try to finish the hike while there is still [daylight]. (=Dịch: Chúng ta nên cố gắng hoàn thành chuyến đi bộ đường dài khi trời vẫn còn ánh sáng ban ngày.)","The artist prefers painting in natural [daylight] rather than under lamps. (=Dịch: Họa sĩ thích vẽ tranh dưới ánh sáng tự nhiên ban ngày hơn là dưới ánh đèn.)","The thieves committed the robbery in broad [daylight]. (=Dịch: Những tên trộm đã thực hiện vụ cướp ngay giữa ban ngày.)"],"ukAudio":"/ai_services/tts3/?q=daylight&lang=en-GB&ipa=%2F%CB%88de%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=daylight&lang=en-US&ipa=%2F%CB%88de%C9%AA.la%C9%AAt%2F"},{"id":"lv_2_31","topic":"Tourism and Visits","word":"destination","pos":"(n)","ipa":"/ˌdes.təˈneɪ.ʃən/","defVi":"điểm đến, đích đến","defEn":"the place where someone or something is going","examples":["Paris is one of the most popular tourist [destination]s in the world. (=Dịch: Paris là một trong những điểm đến du lịch nổi tiếng nhất trên thế giới.)","After six hours of driving, we finally reached our [destination]. (=Dịch: Sau sáu giờ lái xe, cuối cùng chúng tôi cũng đã đến được điểm đến của mình.)","The package took over a week to arrive at its final [destination]. (=Dịch: Gói hàng đã mất hơn một tuần để tới được điểm đến cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=destination&lang=en-GB&ipa=%2F%CB%8Cdes.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destination&lang=en-US&ipa=%2F%CB%8Cdes.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_2_32","topic":"Tourism and Visits","word":"dining","pos":"(n)","ipa":"/ˈdaɪ.nɪŋ/","defVi":"việc ăn uống, dùng bữa","defEn":"the act of eating a meal, especially dinner in a restaurant or formal setting","examples":["The resort offers a variety of fine [dining] options for its guests. (=Dịch: Khu nghỉ dưỡng cung cấp nhiều lựa chọn ẩm thực cao cấp cho du khách.)","We gathered around the large [dining] table for Sunday lunch. (=Dịch: Chúng tôi quây quần quanh bàn ăn lớn cho bữa trưa Chủ nhật.)","Outdoor [dining] has become very popular during the summer months. (=Dịch: Ăn uống ngoài trời đã trở nên rất phổ biến trong những tháng mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=dining&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dining&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_2_33","topic":"Tourism and Visits","word":"dinosaur","pos":"(n)","ipa":"/ˈdaɪ.nə.sɔːr/","defVi":"khủng long","defEn":"a large reptile that lived millions of years ago and is now extinct","examples":["Children love visiting the museum to see the giant [dinosaur] fossils. (=Dịch: Trẻ em rất thích đến bảo tàng để ngắm nhìn những hóa thạch khủng long khổng lồ.)","Scientists believe a huge asteroid caused the extinction of the [dinosaur]s. (=Dịch: Các nhà khoa học tin rằng một tiểu hành tinh khổng lồ đã khiến loài khủng long bị tuyệt chủng.)","He is reading a fascinating book about carnivorous [dinosaur] species. (=Dịch: Cậu ấy đang đọc một cuốn sách hấp dẫn về các loài khủng long ăn thịt.)"],"ukAudio":"/ai_services/tts3/?q=dinosaur&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%99.s%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=dinosaur&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%99.s%C9%94%CB%90r%2F"},{"id":"lv_2_34","topic":"Tourism and Visits","word":"eagle","pos":"(n)","ipa":"/ˈiː.ɡəl/","defVi":"chim đại bàng","defEn":"a large bird of prey with a sharp beak and powerful eyesight","examples":["A golden [eagle] soared gracefully high above the mountain peaks. (=Dịch: Một con đại bàng vàng bay lượn duyên dáng trên đỉnh núi cao.)","The bald [eagle] is an official national symbol of the United States. (=Dịch: Đại bàng đầu trắng là biểu tượng quốc gia chính thức của Hoa Kỳ.)","Using its keen vision, the [eagle] spotted a fish swimming near the surface. (=Dịch: Nhờ thị lực nhạy bén, con đại bàng đã phát hiện ra một con cá đang bơi gần mặt nước.)"],"ukAudio":"/ai_services/tts3/?q=eagle&lang=en-GB&ipa=%2F%CB%88i%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=eagle&lang=en-US&ipa=%2F%CB%88i%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_2_35","topic":"Tourism and Visits","word":"educational","pos":"(adj)","ipa":"/ˌedʒ.əˈkeɪ.ʃən.əl/","defVi":"mang tính giáo dục, thuộc về giáo dục","defEn":"providing useful knowledge or connected with the process of teaching and learning","examples":["Documentaries can be both entertaining and highly [educational]. (=Dịch: Phim tài liệu có thể vừa mang tính giải trí vừa có tính giáo dục cao.)","The school organized an [educational] trip to the science centre. (=Dịch: Trường học đã tổ chức một chuyến đi học tập trải nghiệm tới trung tâm khoa học.)","Many mobile apps are designed to support early [educational] development in children. (=Dịch: Nhiều ứng dụng di động được thiết kế nhằm hỗ trợ sự phát triển giáo dục sớm ở trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=educational&lang=en-GB&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=educational&lang=en-US&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_2_36","topic":"Tourism and Visits","word":"enlarge","pos":"(v)","ipa":"/ɪnˈlɑːrdʒ/","defVi":"mở rộng, phóng to","defEn":"to make something bigger or to become bigger","examples":["The company plans to [enlarge] its headquarters to accommodate new employees. (=Dịch: Công ty có kế hoạch mở rộng trụ sở chính để tiếp nhận thêm nhân viên mới.)","Can you [enlarge] this photograph so we can frame it on the wall? (=Dịch: Bạn có thể phóng to bức ảnh này để chúng tôi đóng khung treo lên tường không?)","Reading widely helps to [enlarge] your vocabulary significantly. (=Dịch: Đọc sách nhiều giúp mở rộng vốn từ vựng của bạn một cách đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=enlarge&lang=en-GB&ipa=%2F%C9%AAn%CB%88l%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=enlarge&lang=en-US&ipa=%2F%C9%AAn%CB%88l%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_2_37","topic":"Tourism and Visits","word":"estate","pos":"(n)","ipa":"/ɪˈsteɪt/","defVi":"bất động sản, khu đất rộng, di sản","defEn":"a large area of land in the country, usually with a large house, or all the property owned by someone","examples":["The wealthy family owns a massive country [estate] in England. (=Dịch: Gia đình giàu có này sở hữu một điền trang rộng lớn ở vùng nông thôn nước Anh.)","After his grandfather passed away, he inherited a substantial real [estate] portfolio. (=Dịch: Sau khi ông qua đời, anh ấy đã thừa kế một danh mục bất động sản đáng kể.)","The city is developing a new industrial [estate] on the outskirts. (=Dịch: Thành phố đang phát triển một khu công nghiệp mới ở vùng ngoại ô.)"],"ukAudio":"/ai_services/tts3/?q=estate&lang=en-GB&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=estate&lang=en-US&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F"},{"id":"lv_2_38","topic":"Tourism and Visits","word":"excursion","pos":"(n)","ipa":"/ɪkˈskɜːr.ʒən/","defVi":"chuyến du ngoạn, chuyến đi chơi ngắn ngày","defEn":"a short journey or trip made for pleasure or leisure","examples":["We went on an all-day boat [excursion] to explore the nearby islands. (=Dịch: Chúng tôi đã tham gia một chuyến du ngoạn bằng thuyền cả ngày để khám phá các hòn đảo lân cận.)","The hotel concierge helped us book a guided [excursion] into the rainforest. (=Dịch: Nhân viên hỗ trợ khách hàng của khách sạn đã giúp chúng tôi đặt một chuyến tham quan có hướng dẫn viên vào rừng nhiệt đới.)","The students enjoyed a weekend [excursion] to the historical museum. (=Dịch: Các học sinh rất hào hứng với chuyến dã ngoại cuối tuần đến bảo tàng lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=excursion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sk%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excursion&lang=en-US&ipa=%2F%C9%AAk%CB%88sk%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_2_39","topic":"Tourism and Visits","word":"exhibit","pos":"(n)","ipa":"/ɪɡˈzɪb.ɪt/","defVi":"vật trưng bày, hiện vật triển lãm","defEn":"an object or a collection of items shown publicly in an exhibition or museum","examples":["The ancient gold crown is the most valuable [exhibit] in the gallery. (=Dịch: Chiếc vương miện vàng cổ là hiện vật có giá trị nhất trong phòng trưng bày.)","Visitors are not allowed to touch any delicate [exhibit] inside the museum. (=Dịch: Khách tham quan không được phép chạm vào bất kỳ hiện vật dễ vỡ nào bên trong bảo tàng.)","The new science [exhibit] features several interactive computer stations. (=Dịch: Khu trưng bày khoa học mới có một số trạm máy tính tương tác.)"],"ukAudio":"/ai_services/tts3/?q=exhibit&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exhibit&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F"},{"id":"lv_2_40","topic":"Tourism and Visits","word":"experimental","pos":"(adj)","ipa":"/ɪkˌsper.əˈmen.t̬əl/","defVi":"mang tính thử nghiệm, thực nghiệm","defEn":"based on new ideas or methods and not yet proven or tested","examples":["The scientists are testing an [experimental] drug to cure the disease. (=Dịch: Các nhà khoa học đang thử nghiệm một loại thuốc thử nghiệm để chữa căn bệnh này.)","The school introduced an [experimental] teaching method to improve student engagement. (=Dịch: Nhà trường đã giới thiệu một phương pháp giảng dạy mang tính thử nghiệm để nâng cao mức độ gắn kết của học sinh.)","His latest album features a lot of [experimental] music. (=Dịch: Album mới nhất của anh ấy có rất nhiều bản nhạc mang tính thể nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=experimental&lang=en-GB&ipa=%2F%C9%AAk%CB%8Csper.%C9%99%CB%88men.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=experimental&lang=en-US&ipa=%2F%C9%AAk%CB%8Csper.%C9%99%CB%88men.t%CC%AC%C9%99l%2F"},{"id":"lv_2_41","topic":"Tourism and Visits","word":"fare","pos":"(n)","ipa":"/fer/","defVi":"tiền vé, giá cước (xe buýt, tàu hỏa, taxi, máy bay)","defEn":"the money that you pay to travel by bus, plane, taxi, or train","examples":["Bus [fare] in the city has increased significantly this year. (=Dịch: Giá vé xe buýt trong thành phố đã tăng đáng kể trong năm nay.)","Passengers must pay the exact [fare] when boarding the tram. (=Dịch: Hành khách phải trả đúng số tiền vé khi lên xe điện.)","She didn't have enough cash on her to pay the taxi [fare]. (=Dịch: Cô ấy không mang theo đủ tiền mặt để trả tiền cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ffer%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ffer%2F"},{"id":"lv_2_42","topic":"Tourism and Visits","word":"farmland","pos":"(n)","ipa":"/ˈfɑːrm.lænd/","defVi":"đất nông nghiệp, đất canh tác","defEn":"land that is used for farming or suitable for growing crops","examples":["Much of the fertile [farmland] was destroyed by the severe flood. (=Dịch: Phần lớn diện tích đất nông nghiệp màu mỡ đã bị tàn phá bởi trận lũ lụt nghiêm trọng.)","Urban expansion is rapidly turning [farmland] into housing estates. (=Dịch: Sự mở rộng đô thị đang nhanh chóng biến đất nông nghiệp thành các khu dân cư.)","The government introduced policies to protect valuable [farmland] from pollution. (=Dịch: Chính phủ đã ban hành các chính sách nhằm bảo vệ đất nông nghiệp có giá trị khỏi tình trạng ô nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=farmland&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90rm.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=farmland&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90rm.l%C3%A6nd%2F"},{"id":"lv_2_43","topic":"Tourism and Visits","word":"farmyard","pos":"(n)","ipa":"/ˈfɑːrm.jɑːrd/","defVi":"sân nông trại, khu đất quanh các chuồng trại","defEn":"an area of land surrounded by farm buildings","examples":["Chickens and ducks were roaming freely around the [farmyard]. (=Dịch: Gà và vịt đang đi lại tự do xung quanh sân nông trại.)","The old tractor was parked near the shed in the [farmyard]. (=Dịch: Chiếc máy kéo cũ được đỗ gần nhà kho trong sân nông trại.)","Children enjoyed feeding the animals in the open [farmyard]. (=Dịch: Trẻ em rất thích thú khi được cho động vật ăn ở khu sân nông trại ngoài trời.)"],"ukAudio":"/ai_services/tts3/?q=farmyard&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90rm.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=farmyard&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90rm.j%C9%91%CB%90rd%2F"},{"id":"lv_2_44","topic":"Tourism and Visits","word":"ferry","pos":"(n)","ipa":"/ˈfer.i/","defVi":"phà, tàu chở khách qua sông/biển","defEn":"a boat or ship that carries people, vehicles, or goods across an area of water","examples":["We took a [ferry] across the river to reach the island. (=Dịch: Chúng tôi đã đi phà qua sông để đến hòn đảo.)","The car [ferry] operates every thirty minutes during peak hours. (=Dịch: Phà chở ô tô hoạt động cứ ba mươi phút một chuyến trong giờ cao điểm.)","Due to stormy weather, all [ferry] services have been cancelled today. (=Dịch: Do thời tiết giông bão, tất cả các dịch vụ phà đều bị hủy vào ngày hôm nay.)"],"ukAudio":"/ai_services/tts3/?q=ferry&lang=en-GB&ipa=%2F%CB%88fer.i%2F","usAudio":"/ai_services/tts3/?q=ferry&lang=en-US&ipa=%2F%CB%88fer.i%2F"},{"id":"lv_2_45","topic":"Tourism and Visits","word":"firewood","pos":"(n)","ipa":"/ˈfaɪr.wʊd/","defVi":"củi (để đun nấu, sưởi ấm)","defEn":"wood that has been prepared or gathered to be burned for heat or cooking","examples":["They went into the forest to gather dry [firewood] for the campfire. (=Dịch: Họ đã vào rừng để lượm củi khô cho lửa trại.)","The cabin was heated entirely by a stove burning [firewood]. (=Dịch: Căn nhà gỗ được sưởi ấm hoàn toàn bằng một chiếc lò đốt củi.)","We need to store enough [firewood] before the cold winter begins. (=Dịch: Chúng ta cần tích trữ đủ củi trước khi mùa đông giá lạnh bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=firewood&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=firewood&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%CA%8Ad%2F"},{"id":"lv_2_46","topic":"Tourism and Visits","word":"fort","pos":"(n)","ipa":"/fɔːrt/","defVi":"pháo đài, công sự phòng thủ","defEn":"a strong building or group of buildings used by military forces for defence","examples":["The ancient [fort] was built on top of a hill to guard against invaders. (=Dịch: Pháo đài cổ kính được xây dựng trên đỉnh đồi để canh phòng những kẻ xâm lược.)","Tourists can explore the historical ruins of the seaside [fort]. (=Dịch: Du khách có thể khám phá những tàn tích lịch sử của pháo đài ven biển.)","Soldiers defended the stone [fort] during the long siege. (=Dịch: Các binh sĩ đã bảo vệ pháo đài bằng đá trong suốt cuộc bao vây kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=fort&lang=en-GB&ipa=%2Ff%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=fort&lang=en-US&ipa=%2Ff%C9%94%CB%90rt%2F"},{"id":"lv_2_47","topic":"Tourism and Visits","word":"found","pos":"(v)","ipa":"/faʊnd/","defVi":"thành lập, sáng lập, xây dựng","defEn":"to establish, start, or set up an organization, company, or institution","examples":["She decided to [found] a charity to support homeless children. (=Dịch: Cô ấy quyết định thành lập một tổ chức từ thiện để hỗ trợ trẻ em vô gia cư.)","The university was [found]ed more than two hundred years ago. (=Dịch: Trường đại học đã được thành lập cách đây hơn hai trăm năm.)","Two young entrepreneurs [found]ed the technology startup in a small garage. (=Dịch: Hai doanh nhân trẻ đã sáng lập công ty khởi nghiệp công nghệ này trong một ga-ra nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=found&lang=en-GB&ipa=%2Ffa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=found&lang=en-US&ipa=%2Ffa%CA%8And%2F"},{"id":"lv_2_48","topic":"Tourism and Visits","word":"fountain","pos":"(n)","ipa":"/ˈfaʊn.tən/","defVi":"đài phun nước, vòi nước uống","defEn":"a structure that sends a stream of water into the air, often decorative or used for drinking","examples":["People like to sit near the decorative [fountain] in the town square. (=Dịch: Mọi người thích ngồi gần đài phun nước trang trí ở quảng trường thị trấn.)","He drank cold water from the drinking [fountain] after running. (=Dịch: Anh ấy đã uống nước mát từ vòi nước uống công cộng sau khi chạy bộ.)","Coins are often tossed into the park [fountain] for good luck. (=Dịch: Mọi người thường ném đồng xu vào đài phun nước trong công viên để cầu may.)"],"ukAudio":"/ai_services/tts3/?q=fountain&lang=en-GB&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fountain&lang=en-US&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F"},{"id":"lv_2_49","topic":"Tourism and Visits","word":"fragile","pos":"(adj)","ipa":"/ˈfrædʒ.əl/","defVi":"dễ vỡ, mỏng manh, yếu ớt","defEn":"easily broken, damaged, or harmed; delicate","examples":["Please be careful with that box because it contains [fragile] glassware. (=Dịch: Xin hãy cẩn thận với chiếc hộp đó vì nó chứa đồ thủy tinh dễ vỡ.)","The region's [fragile] ecosystem is threatened by climate change. (=Dịch: Hệ sinh thái mong manh của khu vực đang bị đe dọa bởi biến đổi khí hậu.)","The patient is still in a [fragile] condition after the surgery. (=Dịch: Bệnh nhân vẫn đang trong tình trạng yếu ớt sau ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F"},{"id":"lv_2_50","topic":"Tourism and Visits","word":"lighthouse","pos":"(n)","ipa":"/ˈlaɪt.haʊs/","defVi":"ngọn hải đăng","defEn":"a tower with a bright light at the top to guide ships at sea","examples":["The old [lighthouse] warns ships of dangerous rocks near the shore. (=Dịch: Ngọn hải đăng cũ cảnh báo các tàu thuyền về những bãi đá nguy hiểm gần bờ.)","We climbed to the top of the [lighthouse] to enjoy the panoramic ocean view. (=Dịch: Chúng tôi đã leo lên đỉnh ngọn hải đăng để ngắm nhìn toàn cảnh đại dương.)","Historically, [lighthouse] keepers lived in isolated conditions for months. (=Dịch: Trong lịch sử, những người gác hải đăng từng sống trong điều kiện cô lập suốt nhiều tháng.)"],"ukAudio":"/ai_services/tts3/?q=lighthouse&lang=en-GB&ipa=%2F%CB%88la%C9%AAt.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=lighthouse&lang=en-US&ipa=%2F%CB%88la%C9%AAt.ha%CA%8As%2F"},{"id":"lv_2_51","topic":"Tourism and Visits","word":"litter","pos":"(n)","ipa":"/ˈlɪt̬.ɚ/","defVi":"rác rưởi (vứt bừa bãi nơi công cộng)","defEn":"small pieces of rubbish left scattered in a public place","examples":["Volunteers gathered on the beach to pick up plastic [litter]. (=Dịch: Các tình nguyện viên đã tập trung trên bãi biển để nhặt rác thải nhựa.)","There are heavy fines for dropping [litter] in the national park. (=Dịch: Có các mức phạt nặng đối với hành vi vứt rác bừa bãi trong vườn quốc gia.)","The streets were filled with [litter] after the music festival ended. (=Dịch: Đường phố ngập tràn rác sau khi lễ hội âm nhạc kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=litter&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litter&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F"},{"id":"lv_2_52","topic":"Tourism and Visits","word":"lunchbox","pos":"(n)","ipa":"/ˈlʌntʃ.bɑːks/","defVi":"hộp đựng cơm trưa","defEn":"a container used for carrying a meal, typically to school or work","examples":["She packed a sandwich and some fresh fruit into her [lunchbox]. (=Dịch: Cô ấy đã xếp một chiếc bánh sandwich và một ít trái cây tươi vào hộp cơm trưa của mình.)","The boy accidentally left his colorful [lunchbox] on the school bus. (=Dịch: Cậu bé đã vô tình để quên chiếc hộp đựng cơm trưa sặc sỡ trên xe buýt trường học.)","Using a reusable [lunchbox] helps reduce daily plastic waste. (=Dịch: Sử dụng hộp cơm trưa tái sử dụng giúp giảm thiểu lượng rác thải nhựa hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=lunchbox&lang=en-GB&ipa=%2F%CB%88l%CA%8Cnt%CA%83.b%C9%91%CB%90ks%2F","usAudio":"/ai_services/tts3/?q=lunchbox&lang=en-US&ipa=%2F%CB%88l%CA%8Cnt%CA%83.b%C9%91%CB%90ks%2F"},{"id":"lv_2_53","topic":"Tourism and Visits","word":"magic","pos":"(adj)","ipa":"/ˈmædʒ.ɪk/","defVi":"kỳ diệu, ma thuật, huyền diệu","defEn":"having special or supernatural powers, or producing surprising results","examples":["The children believed that the old forest had [magic] powers. (=Dịch: Lũ trẻ tin rằng khu rừng già có sức mạnh ma thuật.)","He touched the door with a [magic] wand in the story. (=Dịch: Trong câu chuyện, anh ấy đã chạm vào cánh cửa bằng một chiếc đũa thần.)","Watching the sunset over the mountains was a truly [magic] moment. (=Dịch: Ngắm hoàng hôn buông xuống trên những ngọn núi thực sự là một khoảnh khắc kỳ diệu.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_2_54","topic":"Tourism and Visits","word":"magnificent","pos":"(adj)","ipa":"/mæɡˈnɪf.ə.sənt/","defVi":"tráng lệ, nguy nga, tuyệt mỹ","defEn":"extremely attractive, impressive, and grand","examples":["The palace has a [magnificent] ballroom decorated with gold. (=Dịch: Cung điện có một phòng khiêu vũ tráng lệ được trang trí bằng vàng.)","We had a [magnificent] view of the city from the rooftop terrace. (=Dịch: Chúng tôi có một tầm nhìn tuyệt đẹp bao quát thành phố từ sân thượng.)","The orchestra gave a [magnificent] performance that earned a standing ovation. (=Dịch: Dàn nhạc đã mang đến một buổi biểu diễn tuyệt vời và nhận được sự hoan nghênh nhiệt liệt từ khán giả.)"],"ukAudio":"/ai_services/tts3/?q=magnificent&lang=en-GB&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.s%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=magnificent&lang=en-US&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.s%C9%99nt%2F"},{"id":"lv_2_55","topic":"Tourism and Visits","word":"marsh","pos":"(n)","ipa":"/mɑːrʃ/","defVi":"đầm lầy","defEn":"an area of low, wet land that is often flooded","examples":["Many species of rare birds build their nests in the salt [marsh]. (=Dịch: Nhiều loài chim quý hiếm làm tổ ở vùng đầm lầy nước mặn.)","They built a wooden boardwalk to allow visitors to cross the [marsh] safely. (=Dịch: Họ đã xây một lối đi lót ván gỗ để du khách có thể băng qua đầm lầy một cách an toàn.)","The [marsh] plays a crucial role in filtering water and preventing floods. (=Dịch: Vùng đầm lầy đóng vai trò quan trọng trong việc lọc nước và ngăn ngừa lũ lụt.)"],"ukAudio":"/ai_services/tts3/?q=marsh&lang=en-GB&ipa=%2Fm%C9%91%CB%90r%CA%83%2F","usAudio":"/ai_services/tts3/?q=marsh&lang=en-US&ipa=%2Fm%C9%91%CB%90r%CA%83%2F"},{"id":"lv_2_56","topic":"Tourism and Visits","word":"mayor","pos":"(n)","ipa":"/ˈmeɪ.ɚ/","defVi":"thị trưởng","defEn":"the elected leader of the government in a town or city","examples":["The [mayor] announced a new plan to improve public transportation. (=Dịch: Thị trưởng đã công bố một kế hoạch mới nhằm cải thiện hệ thống giao thông công cộng.)","Citizens gathered at the town hall to voice their concerns to the [mayor]. (=Dịch: Người dân đã tập trung tại tòa thị chính để bày tỏ những mối bận tâm của họ với thị trưởng.)","She served as the city's first female [mayor] for two terms. (=Dịch: Bà đã giữ chức nữ thị trưởng đầu tiên của thành phố trong hai nhiệm kỳ.)"],"ukAudio":"/ai_services/tts3/?q=mayor&lang=en-GB&ipa=%2F%CB%88me%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mayor&lang=en-US&ipa=%2F%CB%88me%C9%AA.%C9%9A%2F"},{"id":"lv_2_57","topic":"Tourism and Visits","word":"maze","pos":"(n)","ipa":"/meɪz/","defVi":"mê cung","defEn":"a complicated system of paths in which it is difficult to find the way out","examples":["The tourists got lost in the [maze] of narrow streets in the old town. (=Dịch: Các du khách đã bị lạc trong mê cung của những con phố hẹp ở khu phố cổ.)","Children love running through the hedge [maze] in the royal garden. (=Dịch: Trẻ em rất thích chạy nhảy qua mê cung hàng rào cây trong khu vườn hoàng gia.)","Navigating the legal system felt like trying to solve a complicated [maze]. (=Dịch: Tìm hiểu và xoay xở trong hệ thống pháp lý mang lại cảm giác như đang cố giải một mê cung phức tạp.)"],"ukAudio":"/ai_services/tts3/?q=maze&lang=en-GB&ipa=%2Fme%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=maze&lang=en-US&ipa=%2Fme%C9%AAz%2F"},{"id":"lv_2_58","topic":"Tourism and Visits","word":"mill","pos":"(n)","ipa":"/mɪl/","defVi":"nhà máy, cối xay, xưởng nghiền","defEn":"a building equipped with machinery for grinding grain into flour or for manufacturing goods","examples":["The traditional water [mill] was used to grind wheat into flour. (=Dịch: Cối xay nước truyền thống từng được sử dụng để xay lúa mì thành bột.)","Many local workers found employment at the nearby textile [mill]. (=Dịch: Nhiều lao động địa phương đã tìm được việc làm tại nhà máy dệt gần đó.)","The old paper [mill] by the river has been converted into a museum. (=Dịch: Nhà máy giấy cũ bên bờ sông đã được cải tạo thành một bảo tàng.)"],"ukAudio":"/ai_services/tts3/?q=mill&lang=en-GB&ipa=%2Fm%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=mill&lang=en-US&ipa=%2Fm%C9%AAl%2F"},{"id":"lv_2_59","topic":"Tourism and Visits","word":"mulberry","pos":"(n)","ipa":"/ˈmʌl.ber.i/","defVi":"cây dâu tằm, quả dâu tằm","defEn":"a small, sweet dark purple or white fruit, or the tree on which it grows","examples":["Silkworms feed exclusively on the fresh leaves of the [mulberry] tree. (=Dịch: Tằm chỉ ăn duy nhất lá tươi của cây dâu tằm.)","She made delicious homemade jam from ripe [mulberry] fruits. (=Dịch: Cô ấy đã làm món mứt tự làm thơm ngon từ những quả dâu tằm chín.)","We sat in the shade of a large [mulberry] tree in the backyard. (=Dịch: Chúng tôi ngồi dưới bóng râm của một cây dâu tằm lớn ở sân sau.)"],"ukAudio":"/ai_services/tts3/?q=mulberry&lang=en-GB&ipa=%2F%CB%88m%CA%8Cl.ber.i%2F","usAudio":"/ai_services/tts3/?q=mulberry&lang=en-US&ipa=%2F%CB%88m%CA%8Cl.ber.i%2F"},{"id":"lv_2_60","topic":"Tourism and Visits","word":"operator","pos":"(n)","ipa":"/ˈɑː.pəˌreɪ.t̬ɚ/","defVi":"người vận hành, nhân viên trực tổng đài, hoặc nhà mạng/nhà điều hành","defEn":"a person who operates equipment or a machine, or a company that runs a business","examples":["Please hold the line while I connect you to the switchboard [operator]. (=Dịch: Xin vui lòng giữ máy trong khi tôi kết nối bạn với nhân viên tổng đài.)","A skilled crane [operator] is needed for this high-rise construction project. (=Dịch: Cần một người vận hành cần cẩu lành nghề cho dự án xây dựng nhà cao tầng này.)","The local tour [operator] organized a wonderful hiking trip in the mountains. (=Dịch: Công ty lữ hành địa phương đã tổ chức một chuyến đi bộ đường dài tuyệt vời trên núi.)"],"ukAudio":"/ai_services/tts3/?q=operator&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99%CB%8Cre%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=operator&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99%CB%8Cre%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_2_61","topic":"Tourism and Visits","word":"organic","pos":"(adj)","ipa":"/ɔːrˈɡæn.ɪk/","defVi":"hữu cơ","defEn":"produced or grown without using artificial chemicals or pesticides","examples":["Many consumers are willing to pay extra for fresh [organic] vegetables. (=Dịch: Nhiều người tiêu dùng sẵn sàng trả thêm tiền cho các loại rau hữu cơ tươi ngon.)","The farm transitioned to [organic] methods to protect the surrounding soil. (=Dịch: Trang trại đã chuyển đổi sang các phương pháp hữu cơ để bảo vệ đất đai xung quanh.)","Her bakery specializes in making bread from [organic] grains. (=Dịch: Tiệm bánh của cô ấy chuyên làm bánh mì từ các loại ngũ cốc hữu cơ.)"],"ukAudio":"/ai_services/tts3/?q=organic&lang=en-GB&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=organic&lang=en-US&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F"},{"id":"lv_2_62","topic":"Tourism and Visits","word":"outdoor","pos":"(adj)","ipa":"/ˈaʊtˌdɔːr/","defVi":"ngoài trời","defEn":"used, happening, or existing in the open air rather than inside a building","examples":["Camping and kayaking are popular [outdoor] activities during the summer. (=Dịch: Cắm trại và chèo thuyền kayak là những hoạt động ngoài trời phổ biến trong mùa hè.)","The restaurant has a lovely [outdoor] patio where guests can dine in nice weather. (=Dịch: Nhà hàng có một khoảng sân ngoài trời xinh xắn, nơi thực khách có thể dùng bữa khi thời tiết đẹp.)","She bought sturdy [outdoor] furniture for her backyard garden. (=Dịch: Cô ấy đã mua đồ nội thất ngoài trời chắc chắn cho khu vườn sau nhà của mình.)"],"ukAudio":"/ai_services/tts3/?q=outdoor&lang=en-GB&ipa=%2F%CB%88a%CA%8At%CB%8Cd%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=outdoor&lang=en-US&ipa=%2F%CB%88a%CA%8At%CB%8Cd%C9%94%CB%90r%2F"},{"id":"lv_2_63","topic":"Tourism and Visits","word":"parkland","pos":"(n)","ipa":"/ˈpɑːrk.lænd/","defVi":"vùng đất công viên, đất cây xanh","defEn":"open land with grass and trees, often surrounding a large house or reserved for recreation","examples":["The city preserved acres of green [parkland] for public recreation. (=Dịch: Thành phố đã bảo tồn nhiều mẫu đất công viên xanh cho mục đích giải trí công cộng.)","Ancient trees scatter across the rolling [parkland] behind the estate. (=Dịch: Những cây cổ thụ nằm rải rác trên vùng đất công viên thoai thoải phía sau khu dinh thự.)","Residents often jog through the scenic [parkland] in the early morning. (=Dịch: Cư dân thường chạy bộ qua khu công viên tuyệt đẹp vào sáng sớm.)"],"ukAudio":"/ai_services/tts3/?q=parkland&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90rk.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=parkland&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90rk.l%C3%A6nd%2F"},{"id":"lv_2_64","topic":"Tourism and Visits","word":"parliament","pos":"(n)","ipa":"/ˈpɑːr.lə.mənt/","defVi":"nghị viện, quốc hội","defEn":"the group of elected politicians who make the laws for a country","examples":["The government passed a new healthcare bill in [parliament] yesterday. (=Dịch: Hôm qua chính phủ đã thông qua một dự luật chăm sóc sức khỏe mới tại nghị viện.)","Members of [parliament] debated the economic policy for several hours. (=Dịch: Các thành viên nghị viện đã tranh luận về chính sách kinh tế trong nhiều giờ liền.)","The prime minister dissolved [parliament] to call for an early election. (=Dịch: Thủ tướng đã giải tán nghị viện để kêu gọi một cuộc bầu cử sớm.)"],"ukAudio":"/ai_services/tts3/?q=parliament&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=parliament&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.l%C9%99.m%C9%99nt%2F"},{"id":"lv_2_65","topic":"Tourism and Visits","word":"pear","pos":"(n)","ipa":"/per/","defVi":"quả lê","defEn":"a sweet, juicy fruit with a narrow top and rounded bottom","examples":["He picked a ripe [pear] straight from the tree in the orchard. (=Dịch: Anh ấy đã hái một quả lê chín mọng ngay từ trên cây trong vườn.)","She added sliced [pear] and walnuts to the autumn salad. (=Dịch: Cô ấy đã thêm lê cắt lát và quả óc chó vào món salad mùa thu.)","The dessert featured a poached [pear] served with vanilla cream. (=Dịch: Món tráng miệng nổi bật với món lê hầm ăn kèm cùng kem vani.)"],"ukAudio":"/ai_services/tts3/?q=pear&lang=en-GB&ipa=%2Fper%2F","usAudio":"/ai_services/tts3/?q=pear&lang=en-US&ipa=%2Fper%2F"},{"id":"lv_2_66","topic":"Tourism and Visits","word":"penguin","pos":"(n)","ipa":"/ˈpeŋ.ɡwɪn/","defVi":"chim cánh cụt","defEn":"a black and white flightless sea bird living mainly in cold southern regions","examples":["The emperor [penguin] can survive in the freezing temperatures of Antarctica. (=Dịch: Chim cánh cụt hoàng đế có thể sống sót trong nhiệt độ băng giá ở Nam Cực.)","Children loved watching the [penguin] colony swim and dive at the aquarium. (=Dịch: Trẻ em rất thích ngắm nhìn đàn chim cánh cụt bơi và lặn tại thủy cung.)","A baby [penguin] is covered in soft gray down feathers when it hatches. (=Dịch: Một chú chim cánh cụt non được bao phủ bởi lớp lông tơ màu xám mềm mại khi mới nở.)"],"ukAudio":"/ai_services/tts3/?q=penguin&lang=en-GB&ipa=%2F%CB%88pe%C5%8B.%C9%A1w%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=penguin&lang=en-US&ipa=%2F%CB%88pe%C5%8B.%C9%A1w%C9%AAn%2F"},{"id":"lv_2_67","topic":"Tourism and Visits","word":"perfectly","pos":"(adv)","ipa":"/ˈpɝː.fɪkt.li/","defVi":"hoàn hảo, hoàn toàn","defEn":"in a way that is completely without mistakes, or entirely and fully","examples":["The new suit fits him [perfectly] without needing any alterations. (=Dịch: Bộ vest mới vừa vặn với anh ấy một cách hoàn hảo mà không cần phải chỉnh sửa gì.)","It is [perfectly] normal to feel nervous before a major exam. (=Dịch: Cảm thấy lo lắng trước một kỳ thi quan trọng là điều hoàn toàn bình thường.)","She executed the complex gymnastics routine [perfectly] and won the gold medal. (=Dịch: Cô ấy đã thực hiện bài thi thể dục dụng cụ phức tạp một cách hoàn hảo và giành được huy chương vàng.)"],"ukAudio":"/ai_services/tts3/?q=perfectly&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.f%C9%AAkt.li%2F","usAudio":"/ai_services/tts3/?q=perfectly&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.f%C9%AAkt.li%2F"},{"id":"lv_2_68","topic":"Tourism and Visits","word":"petition","pos":"(n)","ipa":"/pəˈtɪʃ.ən/","defVi":"đơn kiến nghị, thỉnh nguyện thư","defEn":"a formal written request signed by many people asking an authority to take action","examples":["Neighbors started a [petition] demanding a new traffic light at the intersection. (=Dịch: Những người hàng xóm đã bắt đầu một bản kiến nghị yêu cầu lắp đèn giao thông mới tại ngã tư.)","Over ten thousand citizens signed the online [petition] to ban single-use plastics. (=Dịch: Hơn mười nghìn công dân đã ký vào bản kiến nghị trực tuyến để cấm đồ nhựa dùng một lần.)","The environmental group submitted the [petition] to the city council. (=Dịch: Nhóm bảo vệ môi trường đã đệ trình bản kiến nghị lên hội đồng thành phố.)"],"ukAudio":"/ai_services/tts3/?q=petition&lang=en-GB&ipa=%2Fp%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=petition&lang=en-US&ipa=%2Fp%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_2_69","topic":"Tourism and Visits","word":"photography","pos":"(n)","ipa":"/fəˈtɑː.ɡrə.fi/","defVi":"nhiếp ảnh, nghề chụp ảnh","defEn":"the art, process, or activity of taking and producing photographs","examples":["Landscape [photography] requires both patience and a good eye for lighting. (=Dịch: Nhiếp ảnh phong cảnh đòi hỏi cả sự kiên nhẫn lẫn con mắt tinh tường về ánh sáng.)","She decided to pursue a professional career in fashion [photography]. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp chuyên nghiệp trong ngành nhiếp ảnh thời trang.)","He took up wildlife [photography] as a relaxing weekend hobby. (=Dịch: Anh ấy bắt đầu chụp ảnh động vật hoang dã như một sở thích thư giãn vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=photography&lang=en-GB&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=photography&lang=en-US&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_2_70","topic":"Tourism and Visits","word":"picnic","pos":"(n)","ipa":"/ˈpɪk.nɪk/","defVi":"chuyến dã ngoại, buổi cắm trại ăn ngoài trời","defEn":"an occasion when you eat a meal outside, especially in the countryside or a park","examples":["We decided to have a [picnic] by the lake on Sunday. (=Dịch: Chúng tôi đã quyết định đi dã ngoại bên bờ hồ vào Chủ nhật.)","Don't forget to pack some sandwiches for the family [picnic]. (=Dịch: Đừng quên mang theo vài chiếc bánh mì kẹp cho chuyến dã ngoại của gia đình.)","The sunny weather was perfect for an afternoon [picnic] in the park. (=Dịch: Thời tiết nắng ráo rất hoàn hảo cho một buổi dã ngoại buổi chiều trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=picnic&lang=en-GB&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=picnic&lang=en-US&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F"},{"id":"lv_2_71","topic":"Tourism and Visits","word":"pine","pos":"(n)","ipa":"/paɪn/","defVi":"cây thông","defEn":"an evergreen tree that produces cones and has thin, needle-shaped leaves","examples":["The mountain slopes were covered with tall [pine] trees. (=Dịch: Các sườn núi được bao phủ bởi những cây thông cao vút.)","The air smelled fresh with the scent of [pine] needles. (=Dịch: Không khí thật trong lành với mùi hương của lá thông.)","They built a rustic cabin out of solid [pine] wood. (=Dịch: Họ đã xây dựng một căn cabin mộc mạc từ gỗ thông nguyên khối.)"],"ukAudio":"/ai_services/tts3/?q=pine&lang=en-GB&ipa=%2Fpa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=pine&lang=en-US&ipa=%2Fpa%C9%AAn%2F"},{"id":"lv_2_72","topic":"Tourism and Visits","word":"pitch","pos":"(n)","ipa":"/pɪtʃ/","defVi":"sân thi đấu thể thao (bóng đá, bóng bầu dục, v.v.)","defEn":"an outdoor marked area of ground used for playing a sports game","examples":["The players ran onto the football [pitch] with high spirits. (=Dịch: Các cầu thủ chạy ra sân bóng đá với tinh thần dâng cao.)","Heavy rain made the rugby [pitch] too muddy to play on. (=Dịch: Mưa lớn đã làm cho sân bóng bầu dục trở nên quá lầy lội để có thể thi đấu.)","The school invested money to upgrade its artificial turf [pitch]. (=Dịch: Trường học đã đầu tư tiền để nâng cấp sân cỏ nhân tạo.)"],"ukAudio":"/ai_services/tts3/?q=pitch&lang=en-GB&ipa=%2Fp%C9%AAt%CA%83%2F","usAudio":"/ai_services/tts3/?q=pitch&lang=en-US&ipa=%2Fp%C9%AAt%CA%83%2F"},{"id":"lv_2_73","topic":"Tourism and Visits","word":"playwright","pos":"(n)","ipa":"/ˈpleɪ.raɪt/","defVi":"nhà soạn kịch, nhà viết kịch","defEn":"a person who writes plays for the theater","examples":["William Shakespeare is arguably the most famous [playwright] in history. (=Dịch: William Shakespeare có thể coi là nhà viết kịch nổi tiếng nhất trong lịch sử.)","The young [playwright] won an award for her debut production. (=Dịch: Nữ nhà soạn kịch trẻ tuổi đã giành được một giải thưởng cho tác phẩm đầu tay của mình.)","The local theater company is looking for works by emerging [playwright]s. (=Dịch: Đoàn kịch địa phương đang tìm kiếm các tác phẩm của những nhà viết kịch mới nổi.)"],"ukAudio":"/ai_services/tts3/?q=playwright&lang=en-GB&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=playwright&lang=en-US&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F"},{"id":"lv_2_74","topic":"Tourism and Visits","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, thận trọng, thức thời","defEn":"wise and showing good judgment, especially in political or business matters","examples":["It seemed [politic] to keep his opinions to himself during the heated meeting. (=Dịch: Việc giữ kín ý kiến của mình trong suốt cuộc họp gay gắt dường như là điều khôn ngoan.)","She thought it would not be [politic] to ask for a pay raise right now. (=Dịch: Cô ấy nghĩ rằng việc yêu cầu tăng lương vào lúc này sẽ không phải là một quyết định khôn ngoan.)","The company made a [politic] decision to delay the product launch. (=Dịch: Công ty đã đưa ra một quyết định thận trọng là trì hoãn việc ra mắt sản phẩm.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_2_75","topic":"Tourism and Visits","word":"popularity","pos":"(n)","ipa":"/ˌpɑː.pjəˈler.ə.t̬i/","defVi":"sự phổ biến, sự ưa chuộng, tính đại chúng","defEn":"the state of being liked, enjoyed, or supported by a lot of people","examples":["The singer enjoyed immense [popularity] throughout the 1990s. (=Dịch: Người ca sĩ này đã có được sự yêu mến nồng nhiệt trong suốt những năm 1990.)","The [popularity] of cycling has increased significantly in urban areas. (=Dịch: Sự phổ biến của việc đi xe đạp đã gia tăng đáng kể ở các khu vực thành thị.)","Social media played a crucial role in boosting the brand's [popularity]. (=Dịch: Mạng xã hội đã đóng một vai trò quan trọng trong việc thúc đẩy mức độ phổ biến của thương hiệu.)"],"ukAudio":"/ai_services/tts3/?q=popularity&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=popularity&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F"},{"id":"lv_2_76","topic":"Tourism and Visits","word":"queue","pos":"(v)","ipa":"/kjuː/","defVi":"xếp hàng chờ đợi","defEn":"to wait in a line of people, vehicles, or items","examples":["Hundreds of fans [queue] outside the stadium to buy tickets. (=Dịch: Hàng trăm người hâm mộ xếp hàng bên ngoài sân vận động để mua vé.)","Passengers had to [queue] patiently at the airport security check. (=Dịch: Các hành khách đã phải kiên nhẫn xếp hàng tại khu vực kiểm tra an ninh sân bay.)","We had to [queue] for over an hour just to get into the exhibition. (=Dịch: Chúng tôi đã phải xếp hàng hơn một tiếng đồng hồ chỉ để vào được buổi triển lãm.)"],"ukAudio":"/ai_services/tts3/?q=queue&lang=en-GB&ipa=%2Fkju%CB%90%2F","usAudio":"/ai_services/tts3/?q=queue&lang=en-US&ipa=%2Fkju%CB%90%2F"},{"id":"lv_2_77","topic":"Tourism and Visits","word":"quiz","pos":"(n)","ipa":"/kwɪz/","defVi":"bài kiểm tra ngắn, câu đố kiểm tra kiến thức","defEn":"a short or informal test of knowledge or a game based on answering questions","examples":["The teacher gave us a surprise vocabulary [quiz] this morning. (=Dịch: Giáo viên đã cho chúng tôi một bài kiểm tra nhanh từ vựng bất ngờ vào sáng nay.)","We joined the weekly pub [quiz] with some university friends. (=Dịch: Chúng tôi đã tham gia buổi đố vui hàng tuần ở quán rượu cùng một vài người bạn đại học.)","Take this online [quiz] to find out your learning style. (=Dịch: Hãy làm bài trắc nghiệm trực tuyến này để tìm ra phong cách học tập của bạn.)"],"ukAudio":"/ai_services/tts3/?q=quiz&lang=en-GB&ipa=%2Fkw%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=quiz&lang=en-US&ipa=%2Fkw%C9%AAz%2F"},{"id":"lv_2_78","topic":"Tourism and Visits","word":"rabbit","pos":"(n)","ipa":"/ˈræb.ɪt/","defVi":"con thỏ","defEn":"a small furry animal with long ears and a short tail that lives in burrows","examples":["A wild [rabbit] hopped across the grass and disappeared into the bushes. (=Dịch: Một con thỏ hoang nhảy qua bãi cỏ rồi biến mất vào bụi rậm.)","She keeps a pet [rabbit] in a large wooden hutch in the garden. (=Dịch: Cô ấy nuôi một chú thỏ cưng trong một chiếc chuồng gỗ lớn ở ngoài vườn.)","Carrots and leafy greens are healthy food options for a [rabbit]. (=Dịch: Cà rốt và các loại rau xanh là những lựa chọn thức ăn lành mạnh cho thỏ.)"],"ukAudio":"/ai_services/tts3/?q=rabbit&lang=en-GB&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rabbit&lang=en-US&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F"},{"id":"lv_2_79","topic":"Tourism and Visits","word":"ranger","pos":"(n)","ipa":"/ˈreɪn.dʒɚ/","defVi":"kiểm lâm, nhân viên quản lý vườn quốc gia","defEn":"a person whose job is to protect and manage a forest, park, or wildlife area","examples":["The park [ranger] guided tourists through the nature trail safely. (=Dịch: Nhân viên kiểm lâm công viên đã hướng dẫn du khách đi qua đường mòn thiên nhiên một cách an toàn.)","A dedicated forest [ranger] works hard to prevent illegal logging. (=Dịch: Một kiểm lâm viên tận tụy luôn nỗ lực hết mình để ngăn chặn việc khai thác gỗ trái phép.)","The [ranger] warned visitors not to feed the wild animals. (=Dịch: Người kiểm lâm đã cảnh báo du khách không được cho động vật hoang dã ăn.)"],"ukAudio":"/ai_services/tts3/?q=ranger&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ranger&lang=en-US&ipa=%2F%CB%88re%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_2_80","topic":"Tourism and Visits","word":"raw","pos":"(adj)","ipa":"/rɑː/","defVi":"sống (chưa nấu chín), thô (chưa qua chế biến)","defEn":"not cooked, or in a natural state without being processed","examples":["Some people prefer to eat [raw] vegetables to preserve their nutrients. (=Dịch: Một số người thích ăn rau sống để giữ lại các chất dinh dưỡng của chúng.)","The factory imports [raw] materials from several neighboring countries. (=Dịch: Nhà máy nhập khẩu nguyên liệu thô từ một số quốc gia láng giềng.)","The cold, [raw] wind made everyone shiver as they waited for the bus. (=Dịch: Cơn gió lạnh buốt khiến mọi người run rẩy trong lúc đứng chờ xe buýt.)"],"ukAudio":"/ai_services/tts3/?q=raw&lang=en-GB&ipa=%2Fr%C9%91%CB%90%2F","usAudio":"/ai_services/tts3/?q=raw&lang=en-US&ipa=%2Fr%C9%91%CB%90%2F"},{"id":"lv_2_81","topic":"Tourism and Visits","word":"referee","pos":"(n)","ipa":"/ˌrɛf.əˈri/","defVi":"trọng tài","defEn":"an official who controls a sports match and ensures players follow the rules","examples":["The [referee] blew his whistle and awarded a penalty to the home team. (=Dịch: Trọng tài đã thổi còi và cho đội chủ nhà hưởng một quả phạt đền.)","Players must respect the decision made by the [referee] during the game. (=Dịch: Các cầu thủ phải tôn trọng quyết định của trọng tài trong suốt trận đấu.)","She is training hard to become a certified football [referee]. (=Dịch: Cô ấy đang nỗ lực tập luyện để trở thành một trọng tài bóng đá được cấp chứng chỉ.)"],"ukAudio":"/ai_services/tts3/?q=referee&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bf.%C9%99%CB%88ri%2F","usAudio":"/ai_services/tts3/?q=referee&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bf.%C9%99%CB%88ri%2F"},{"id":"lv_2_82","topic":"Tourism and Visits","word":"reptile","pos":"(n)","ipa":"/ˈrɛp.taɪl/","defVi":"loài bò sát","defEn":"a cold-blooded animal with scaly skin that lays eggs, such as a snake or lizard","examples":["A crocodile is a large [reptile] that lives in rivers and swamps. (=Dịch: Cá sấu là một loài bò sát lớn sống ở các con sông và đầm lầy.)","Unlike mammals, almost every [reptile] lays eggs with tough shells. (=Dịch: Không giống như động vật có vú, hầu hết các loài bò sát đều đẻ trứng có vỏ cứng.)","The zoo has a dedicated section for each rare [reptile] species. (=Dịch: Sở thú có một khu vực riêng biệt dành cho từng loài bò sát quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=reptile&lang=en-GB&ipa=%2F%CB%88r%C9%9Bp.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=reptile&lang=en-US&ipa=%2F%CB%88r%C9%9Bp.ta%C9%AAl%2F"},{"id":"lv_2_83","topic":"Tourism and Visits","word":"rhythm","pos":"(n)","ipa":"/ˈrɪð.əm/","defVi":"nhịp điệu, tiết tấu","defEn":"a strong, regular, repeated pattern of movement or sound","examples":["She tapped her foot to the lively [rhythm] of the music. (=Dịch: Cô ấy nhịp chân theo giai điệu sống động của bản nhạc.)","It took a few weeks to adjust to the daily [rhythm] of university life. (=Dịch: Phải mất vài tuần để thích nghi với nhịp sống hằng ngày của đời sinh viên.)","The steady [rhythm] of rainfall helped him fall asleep quickly. (=Dịch: Tiếng mưa rơi đều đặn đã giúp anh nhanh chóng chìm vào giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=rhythm&lang=en-GB&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=rhythm&lang=en-US&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F"},{"id":"lv_2_84","topic":"Tourism and Visits","word":"ridge","pos":"(n)","ipa":"/rɪdʒ/","defVi":"sống núi, chỏm núi, gờ nổi","defEn":"a long, narrow raised part along a mountain, hill, or surface","examples":["The hikers walked along the narrow [ridge] of the mountain. (=Dịch: Những người đi bộ đường dài bước dọc theo sống núi hẹp.)","We could see the entire valley clearly from the top of the [ridge]. (=Dịch: Chúng tôi có thể nhìn thấy rõ toàn bộ thung lũng từ trên đỉnh sống núi.)","A high-pressure [ridge] brought dry and sunny weather to the region. (=Dịch: Một dải áp cao đã mang lại thời tiết khô ráo và đầy nắng cho khu vực.)"],"ukAudio":"/ai_services/tts3/?q=ridge&lang=en-GB&ipa=%2Fr%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=ridge&lang=en-US&ipa=%2Fr%C9%AAd%CA%92%2F"},{"id":"lv_2_85","topic":"Tourism and Visits","word":"riverside","pos":"(n)","ipa":"/ˈrɪv.ɚˌsaɪd/","defVi":"bờ sông, ven sông","defEn":"the ground along the edge of a river","examples":["They decided to have a picnic on the grassy [riverside]. (=Dịch: Họ quyết định tổ chức một buổi dã ngoại trên bờ sông đầy cỏ.)","Many tourists enjoy walking along the scenic [riverside] in the evening. (=Dịch: Nhiều du khách thích đi dạo dọc bờ sông thơ mộng vào buổi tối.)","The city built a new promenade along the [riverside] to attract visitors. (=Dịch: Thành phố đã xây dựng một lối đi dạo mới dọc bờ sông để thu hút du khách.)"],"ukAudio":"/ai_services/tts3/?q=riverside&lang=en-GB&ipa=%2F%CB%88r%C9%AAv.%C9%9A%CB%8Csa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=riverside&lang=en-US&ipa=%2F%CB%88r%C9%AAv.%C9%9A%CB%8Csa%C9%AAd%2F"},{"id":"lv_2_86","topic":"Tourism and Visits","word":"roll","pos":"(v)","ipa":"/roʊl/","defVi":"lăn, cuộn lại","defEn":"to move by turning over and over, or to form into a tube or ball","examples":["The children laughed as they watched the ball [roll] down the hill. (=Dịch: Lũ trẻ bật cười khi nhìn quả bóng lăn xuống đồi.)","You should [roll] the dough into a smooth circle before baking. (=Dịch: Bạn nên cán bột thành một hình tròn mịn trước khi nướng.)","Tears began to [roll] down her cheeks when she heard the good news. (=Dịch: Nước mắt bắt đầu lăn dài trên má khi cô nghe được tin vui.)"],"ukAudio":"/ai_services/tts3/?q=roll&lang=en-GB&ipa=%2Fro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=roll&lang=en-US&ipa=%2Fro%CA%8Al%2F"},{"id":"lv_2_87","topic":"Tourism and Visits","word":"romantic","pos":"(adj)","ipa":"/roʊˈmæn.tɪk/","defVi":"lãng mạn","defEn":"connected with or expressive of love, idealized beauty, or passion","examples":["They celebrated their anniversary with a [romantic] dinner by candlelight. (=Dịch: Họ đã kỷ niệm ngày cưới bằng một bữa tối lãng mạn dưới ánh nến.)","Paris is often considered one of the most [romantic] cities in the world. (=Dịch: Paris thường được coi là một trong những thành phố lãng mạn nhất thế giới.)","He wrote a [romantic] poem to express his deep feelings for her. (=Dịch: Anh ấy đã viết một bài thơ lãng mạn để bày tỏ tình cảm sâu sắc của mình dành cho cô.)"],"ukAudio":"/ai_services/tts3/?q=romantic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=romantic&lang=en-US&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_2_88","topic":"Tourism and Visits","word":"rome","pos":"(n)","ipa":"/roʊm/","defVi":"thành phố Rome, thủ đô nước Ý","defEn":"the capital city of Italy, famous for its ancient history and architecture","examples":["Millions of travelers visit [Rome] each year to explore its ancient ruins. (=Dịch: Hàng triệu du khách đến thăm Rome mỗi năm để khám phá những tàn tích cổ xưa nơi đây.)","The Colosseum is one of the most famous landmarks in [Rome]. (=Dịch: Đấu trường Colosseum là một trong những địa danh nổi tiếng nhất ở Rome.)","Her dream has always been to study classical architecture in [Rome]. (=Dịch: Ước mơ của cô luôn là được theo học ngành kiến trúc cổ điển tại Rome.)"],"ukAudio":"/ai_services/tts3/?q=rome&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=rome&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_2_89","topic":"Tourism and Visits","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, thô ráp, dữ dội","defEn":"having an uneven or irregular surface; not smooth or gentle","examples":["His hands were [rough] and calloused from years of manual labor. (=Dịch: Đôi bàn tay ông thô ráp và chai sạn sau nhiều năm lao động chân tay.)","The boat struggled to navigate through the [rough] sea during the storm. (=Dịch: Con thuyền chật vật di chuyển qua vùng biển động dữ dội trong cơn bão.)","She made a [rough] sketch of the landscape before starting the painting. (=Dịch: Cô ấy đã phác thảo sơ bộ phong cảnh trước khi bắt đầu vẽ tranh.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_2_90","topic":"Tourism and Visits","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a line of people or things placed side by side","examples":["We had great seats in the front [row] of the cinema. (=Dịch: Chúng tôi đã có những chỗ ngồi tuyệt vời ở hàng ghế đầu của rạp chiếu phim.)","A [row] of trees was planted along the road to provide shade. (=Dịch: Một hàng cây đã được trồng dọc theo con đường để tạo bóng mát.)","The teacher asked the students to stand in a straight [row]. (=Dịch: Giáo viên yêu cầu các học sinh đứng thành một hàng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_2_91","topic":"Tourism and Visits","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"hoàng gia, thuộc về hoàng gia","defEn":"connected with or belonging to a king, queen, or their family","examples":["The [royal] family attended the annual charity event together. (=Dịch: Gia đình hoàng gia đã cùng nhau tham dự sự kiện từ thiện thường niên.)","They received a [royal] welcome when they arrived in the historic city. (=Dịch: Họ đã nhận được sự đón tiếp nồng hậu như bậc vương giả khi đặt chân đến thành phố lịch sử này.)","The museum displays many treasures from the ancient [royal] palace. (=Dịch: Bảo tàng trưng bày nhiều báu vật từ cung điện hoàng gia cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_2_92","topic":"Tourism and Visits","word":"ruler","pos":"(n)","ipa":"/ˈru.lɚ/","defVi":"người cai trị, nhà lãnh đạo","defEn":"a person who has the official power to govern a country or area","examples":["The ancient [ruler] was known for his wisdom and fairness. (=Dịch: Vị quân chủ thời cổ đại được biết đến nhờ sự thông thái và tính công bằng của mình.)","Many laws were changed during the reign of the new [ruler]. (=Dịch: Nhiều đạo luật đã bị thay đổi dưới triều đại của nhà cai trị mới.)","The military [ruler] faced strong opposition from the citizens. (=Dịch: Nhà cai trị quân sự vấp phải sự phản đối gay gắt từ người dân.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru.l%C9%9A%2F"},{"id":"lv_2_93","topic":"Tourism and Visits","word":"russia","pos":"(n)","ipa":"/ˈrʌʃ.ə/","defVi":"nước Nga","defEn":"a large country spanning Eastern Europe and Northern Asia","examples":["[Russia] is the largest country in the world by land area. (=Dịch: Nước Nga là quốc gia có diện tích đất liền lớn nhất trên thế giới.)","She spent two years studying literature in [Russia]. (=Dịch: Cô ấy đã dành hai năm học văn học tại Nga.)","The climate in northern [Russia] is extremely cold during winter. (=Dịch: Khí hậu ở miền bắc nước Nga vô cùng lạnh giá vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=russia&lang=en-GB&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F","usAudio":"/ai_services/tts3/?q=russia&lang=en-US&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F"},{"id":"lv_2_94","topic":"Tourism and Visits","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ","defEn":"people who work as members of the crew on a ship or boat","examples":["The [sailors] worked hard to navigate the ship through the stormy sea. (=Dịch: Các thủy thủ đã làm việc cật lực để điều khiển con tàu vượt qua vùng biển giông bão.)","A group of experienced [sailors] repaired the sails before departure. (=Dịch: Một nhóm thủy thủ giàu kinh nghiệm đã sửa chữa các cánh buồm trước khi khởi hành.)","Ancient [sailors] used the stars in the night sky to guide their journeys. (=Dịch: Các thủy thủ thời cổ đại từng dùng các vì sao trên bầu trời đêm để dẫn đường cho những chuyến hành trình của họ.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_2_95","topic":"Tourism and Visits","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance consisting of very small grains of rock found on beaches and in deserts","examples":["Children love playing in the warm [sand] on the beach. (=Dịch: Trẻ em rất thích chơi trên bãi cát ấm áp ở bờ biển.)","The wind blew [sand] into our eyes as we walked across the desert. (=Dịch: Gió đã thổi cát vào mắt chúng tôi khi chúng tôi đi bộ qua sa mạc.)","He shook the loose [sand] out of his shoes before entering the house. (=Dịch: Anh ấy đã giũ sạch cát bám trong giày trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_2_96","topic":"Tourism and Visits","word":"scarecrow","pos":"(n)","ipa":"/ˈsker.kroʊ/","defVi":"bù nhìn (đuổi chim)","defEn":"a figure made of clothes stuffed with straw, set up in a field to frighten birds away","examples":["The farmer placed a [scarecrow] in the middle of the cornfield. (=Dịch: Người nông dân đặt một con bù nhìn ở giữa cánh đồng ngô.)","Birds quickly realized that the old [scarecrow] could not harm them. (=Dịch: Loài chim nhanh chóng nhận ra rằng con bù nhìn rơm cũ kỹ đó không thể làm hại chúng.)","The children dressed up an old coat and hat to make a [scarecrow]. (=Dịch: Lũ trẻ đã mặc một chiếc áo khoác cũ và đội mũ lên để làm thành một con bù nhìn.)"],"ukAudio":"/ai_services/tts3/?q=scarecrow&lang=en-GB&ipa=%2F%CB%88sker.kro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=scarecrow&lang=en-US&ipa=%2F%CB%88sker.kro%CA%8A%2F"},{"id":"lv_2_97","topic":"Tourism and Visits","word":"scenery","pos":"(n)","ipa":"/ˈsi.nə.ri/","defVi":"phong cảnh, cảnh quan","defEn":"the natural features of a landscape, especially when attractive to look at","examples":["The train journey offers breathtaking views of the mountain [scenery]. (=Dịch: Hành trình bằng tàu hỏa mang lại tầm nhìn tuyệt đẹp ra phong cảnh núi non.)","Many tourists visit this island to enjoy its peaceful coastal [scenery]. (=Dịch: Nhiều du khách ghé thăm hòn đảo này để tận hưởng cảnh quan miền duyên hải yên bình.)","We stopped the car several times to take photos of the stunning [scenery]. (=Dịch: Chúng tôi đã dừng xe lại nhiều lần để chụp ảnh phong cảnh tuyệt đẹp này.)"],"ukAudio":"/ai_services/tts3/?q=scenery&lang=en-GB&ipa=%2F%CB%88si.n%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=scenery&lang=en-US&ipa=%2F%CB%88si.n%C9%99.ri%2F"},{"id":"lv_2_98","topic":"Tourism and Visits","word":"scholar","pos":"(n)","ipa":"/ˈskɑ.lɚ/","defVi":"học giả","defEn":"a person who has studied a subject in great depth and knows a lot about it","examples":["The distinguished [scholar] published several books on ancient history. (=Dịch: Học giả lỗi lạc đã xuất bản một vài cuốn sách về lịch sử cổ đại.)","She is widely respected as a leading [scholar] in modern linguistics. (=Dịch: Bà ấy được tôn trọng rộng rãi như một học giả hàng đầu về ngôn ngữ học hiện đại.)","The library holds many rare manuscripts that attract research [scholar]s from abroad. (=Dịch: Thư viện lưu giữ nhiều bản thảo quý hiếm thu hút các học giả nghiên cứu từ nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=scholar&lang=en-GB&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=scholar&lang=en-US&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F"},{"id":"lv_2_99","topic":"Tourism and Visits","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"khoa học, mang tính khoa học","defEn":"relating to science or based on the methods used in science","examples":["Researchers need solid [scientific] evidence to support their theory. (=Dịch: Các nhà nghiên cứu cần những bằng chứng khoa học vững chắc để chứng minh cho giả thuyết của mình.)","The discovery was considered a major [scientific] breakthrough. (=Dịch: Phát hiện này được coi là một bước đột phá khoa học lớn.)","The experiment was carried out under strict [scientific] conditions. (=Dịch: Thí nghiệm đã được tiến hành dưới những điều kiện khoa học nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_2_100","topic":"Tourism and Visits","word":"script","pos":"(n)","ipa":"/skrɪpt/","defVi":"kịch bản","defEn":"the written text of a play, movie, or broadcast","examples":["The director made several changes to the original [script]. (=Dịch: Đạo diễn đã thực hiện một số thay đổi đối với kịch bản gốc.)","Actors must spend hours memorizing their lines from the [script]. (=Dịch: Các diễn viên phải dành hàng giờ để ghi nhớ lời thoại từ kịch bản.)","She submitted her film [script] to several production companies. (=Dịch: Cô ấy đã gửi kịch bản phim của mình tới một vài công ty sản xuất.)"],"ukAudio":"/ai_services/tts3/?q=script&lang=en-GB&ipa=%2Fskr%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=script&lang=en-US&ipa=%2Fskr%C9%AApt%2F"},{"id":"lv_2_101","topic":"Tourism and Visits","word":"seal","pos":"(n)","ipa":"/siːl/","defVi":"hải cẩu, chó biển","defEn":"a sea animal with smooth fur and flippers that lives in cold regions","examples":["We watched a [seal] basking in the sun on the rocky shore. (=Dịch: Chúng tôi đã ngắm nhìn một con hải cẩu đang phơi nắng trên bờ đá.)","The polar bear relies on the [seal] as its primary source of food. (=Dịch: Gấu bắc cực dựa vào hải cẩu như nguồn thức ăn chính của chúng.)","A baby [seal] has a thick white coat to keep warm in freezing temperatures. (=Dịch: Một con hải cẩu con có một lớp lông dày màu trắng để giữ ấm trong nhiệt độ đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=seal&lang=en-GB&ipa=%2Fsi%CB%90l%2F","usAudio":"/ai_services/tts3/?q=seal&lang=en-US&ipa=%2Fsi%CB%90l%2F"},{"id":"lv_2_102","topic":"Tourism and Visits","word":"seating","pos":"(n)","ipa":"/ˈsiː.tɪŋ/","defVi":"chỗ ngồi, sự sắp xếp chỗ ngồi","defEn":"the seats provided in a place, or the arrangement of seats","examples":["The new auditorium offers comfortable [seating] for over a thousand people. (=Dịch: Khán phòng mới mang lại chỗ ngồi thoải mái cho hơn một nghìn người.)","Outdoor [seating] is available during the warm summer months. (=Dịch: Chỗ ngồi ngoài trời luôn sẵn có trong suốt những tháng mùa hè ấm áp.)","The wedding planner carefully organized the [seating] plan for the reception. (=Dịch: Người lên kế hoạch đám cưới đã cẩn thận sắp xếp sơ đồ chỗ ngồi cho buổi tiệc chiêu đãi.)"],"ukAudio":"/ai_services/tts3/?q=seating&lang=en-GB&ipa=%2F%CB%88si%CB%90.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=seating&lang=en-US&ipa=%2F%CB%88si%CB%90.t%C9%AA%C5%8B%2F"},{"id":"lv_2_103","topic":"Tourism and Visits","word":"seek","pos":"(v)","ipa":"/siːk/","defVi":"tìm kiếm, mưu cầu","defEn":"to look for or try to obtain something","examples":["Graduates often [seek] advice from career counselors before applying for jobs. (=Dịch: Sinh viên mới tốt nghiệp thường tìm kiếm lời khuyên từ các chuyên gia tư vấn nghề nghiệp trước khi nộp đơn xin việc.)","The government is trying to [seek] new solutions to reduce traffic congestion. (=Dịch: Chính phủ đang nỗ lực tìm kiếm các giải pháp mới nhằm giảm thiểu tình trạng ùn tắc giao thông.)","Many immigrants [seek] better economic opportunities in foreign countries. (=Dịch: Nhiều người nhập cư tìm kiếm những cơ hội kinh tế tốt hơn ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsi%CB%90k%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsi%CB%90k%2F"},{"id":"lv_2_104","topic":"Tourism and Visits","word":"seminar","pos":"(n)","ipa":"/ˈsem.əˌnɑːr/","defVi":"hội thảo chuyên đề, buổi hội thảo","defEn":"a meeting or class for discussion and learning on a particular topic","examples":["I attended an informative [seminar] on modern business leadership. (=Dịch: Tôi đã tham dự một buổi hội thảo hữu ích về khả năng lãnh đạo doanh nghiệp hiện đại.)","The professor required all graduate students to participate in the weekly [seminar]. (=Dịch: Giáo sư yêu cầu tất cả học viên cao học phải tham gia buổi hội thảo chuyên đề hằng tuần.)","The university is hosting a three-day [seminar] on climate change. (=Dịch: Trường đại học đang tổ chức một hội thảo kéo dài ba ngày về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88sem.%C9%99%CB%8Cn%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88sem.%C9%99%CB%8Cn%C9%91%CB%90r%2F"},{"id":"lv_2_105","topic":"Tourism and Visits","word":"serpent","pos":"(n)","ipa":"/ˈsɜːr.pənt/","defVi":"con rắn (thường dùng trong văn học hoặc thần thoại)","defEn":"a snake, especially a large or poisonous one, often used in literary contexts","examples":["In ancient mythology, the [serpent] is often a symbol of wisdom and danger. (=Dịch: Trong thần thoại cổ đại, mãng xà thường là biểu tượng của sự thông thái và hiểm nguy.)","The statue depicted a warrior wrestling with a giant [serpent]. (=Dịch: Bức tượng miêu tả một chiến binh đang vật lộn với một con mãng xà khổng lồ.)","The fairy tale warned travelers about a venomous [serpent] guarding the treasure. (=Dịch: Câu chuyện cổ tích đã cảnh báo những người lữ hành về một con rắn độc đang canh giữ kho báu.)"],"ukAudio":"/ai_services/tts3/?q=serpent&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.p%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=serpent&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.p%C9%99nt%2F"},{"id":"lv_2_106","topic":"Tourism and Visits","word":"servant","pos":"(n)","ipa":"/ˈsɜːr.vənt/","defVi":"người hầu, người giúp việc","defEn":"a person employed in another person's house, doing domestic work","examples":["In the nineteenth century, wealthy families often employed a domestic [servant]. (=Dịch: Vào thế kỷ XIX, các gia đình giàu có thường thuê người hầu trong nhà.)","The loyal [servant] worked for the same household for more than thirty years. (=Dịch: Người đầy tớ trung thành đã phục vụ cho cùng một gia đình trong hơn ba mươi năm.)","He dedicated his life to politics and saw himself as a public [servant]. (=Dịch: Ông đã cống hiến cả cuộc đời cho chính trị và coi mình là một công bộc của nhân dân.)"],"ukAudio":"/ai_services/tts3/?q=servant&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.v%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=servant&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.v%C9%99nt%2F"},{"id":"lv_2_107","topic":"Tourism and Visits","word":"setback","pos":"(n)","ipa":"/ˈset.bæk/","defVi":"trở ngại, bước lùi","defEn":"a problem that delays or prevents progress","examples":["The unexpected injury was a major [setback] to her athletic career. (=Dịch: Chấn thương bất ngờ là một trở ngại lớn đối với sự nghiệp thể thao của cô ấy.)","Despite the financial [setback], the company managed to launch the product on time. (=Dịch: Bất chấp khó khăn tài chính, công ty vẫn xoay xở để ra mắt sản phẩm đúng hạn.)","Losing the contract was only a temporary [setback] for the startup. (=Dịch: Việc mất hợp đồng chỉ là một trở ngại tạm thời đối với công ty khởi nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=setback&lang=en-GB&ipa=%2F%CB%88set.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=setback&lang=en-US&ipa=%2F%CB%88set.b%C3%A6k%2F"},{"id":"lv_2_108","topic":"Tourism and Visits","word":"settler","pos":"(n)","ipa":"/ˈset.lər/","defVi":"người định cư, người khai hoang","defEn":"a person who moves with a group of others to live in a new country or area","examples":["The early [settler] community faced harsh winters and scarce resources. (=Dịch: Cộng đồng người đi khai hoang thời kỳ đầu đã phải đối mặt với những mùa đông khắc nghiệt và nguồn tài nguyên khan hiếm.)","Each [settler] was granted a piece of land to build a home and farm. (=Dịch: Mỗi người định cư đều được cấp một mảnh đất để xây nhà và làm trang trại.)","Historians study how the first European [settler] groups interacted with indigenous tribes. (=Dịch: Các nhà sử học nghiên cứu cách các nhóm người châu Âu đầu tiên đến định cư đã tương tác với các bộ lạc bản địa.)"],"ukAudio":"/ai_services/tts3/?q=settler&lang=en-GB&ipa=%2F%CB%88set.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=settler&lang=en-US&ipa=%2F%CB%88set.l%C9%99r%2F"},{"id":"lv_2_109","topic":"Tourism and Visits","word":"sew","pos":"(v)","ipa":"/soʊ/","defVi":"may, khâu","defEn":"to join or attach things together using a needle and thread","examples":["My grandmother taught me how to [sew] a button onto a shirt. (=Dịch: Bà tôi đã dạy tôi cách khâu một chiếc cúc vào áo sơ mi.)","She loves to [sew] her own clothes instead of buying them from stores. (=Dịch: Cô ấy thích tự may quần áo cho mình thay vì mua từ các cửa hàng.)","The tailor used durable thread to [sew] the torn seams of the jacket. (=Dịch: Người thợ may đã dùng chỉ bền để khâu lại các đường may bị rách của chiếc áo khoác.)"],"ukAudio":"/ai_services/tts3/?q=sew&lang=en-GB&ipa=%2Fso%CA%8A%2F","usAudio":"/ai_services/tts3/?q=sew&lang=en-US&ipa=%2Fso%CA%8A%2F"},{"id":"lv_2_110","topic":"Tourism and Visits","word":"sex","pos":"(n)","ipa":"/sɛks/","defVi":"giới tính (về mặt sinh học)","defEn":"the biological state of being male or female","examples":["Please indicate your [sex] and date of birth on the application form. (=Dịch: Vui lòng ghi rõ giới tính và ngày sinh của bạn trên mẫu đơn đăng ký.)","Discrimination on the basis of [sex] is strictly prohibited in the workplace. (=Dịch: Phân biệt đối xử dựa trên giới tính bị nghiêm cấm tại nơi làm việc.)","The research studied differences in behavior related to [sex] and age. (=Dịch: Nghiên cứu đã xem xét những khác biệt trong hành vi liên quan đến giới tính và độ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=sex&lang=en-GB&ipa=%2Fs%C9%9Bks%2F","usAudio":"/ai_services/tts3/?q=sex&lang=en-US&ipa=%2Fs%C9%9Bks%2F"},{"id":"lv_2_111","topic":"Tourism and Visits","word":"shed","pos":"(n)","ipa":"/ʃɛd/","defVi":"nhà kho nhỏ, lán để đồ","defEn":"a small, simple building used for storing tools or sheltering animals","examples":["He keeps all of his gardening equipment in a wooden [shed] behind the house. (=Dịch: Anh ấy cất giữ toàn bộ dụng cụ làm vườn của mình trong một cái lán bằng gỗ phía sau nhà.)","They converted the old tool [shed] into a cozy outdoor workshop. (=Dịch: Họ đã cải tạo nhà kho chứa dụng cụ cũ thành một xưởng làm việc ngoài trời ấm cúng.)","The bicycle was stored safely in the backyard [shed] during the winter. (=Dịch: Chiếc xe đạp đã được cất giữ an toàn trong nhà kho sau vườn suốt mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=shed&lang=en-GB&ipa=%2F%CA%83%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=shed&lang=en-US&ipa=%2F%CA%83%C9%9Bd%2F"},{"id":"lv_2_112","topic":"Tourism and Visits","word":"situate","pos":"(v)","ipa":"/ˈsɪtʃ.u.eɪt/","defVi":"đặt ở vị trí, định vị","defEn":"to place or locate something in a specific position or context","examples":["The developers decided to [situate] the new hotel near the coast. (=Dịch: Các nhà phát triển đã quyết định đặt khách sạn mới ở gần bờ biển.)","The author tries to [situate] the historical events within their social background. (=Dịch: Tác giả cố gắng đặt các sự kiện lịch sử vào trong bối cảnh xã hội của chúng.)","It is important to [situate] the school within easy reach of public transport. (=Dịch: Việc đặt trường học ở nơi thuận tiện tiếp cận các phương tiện giao thông công cộng là rất quan trọng.)"],"ukAudio":"/ai_services/tts3/?q=situate&lang=en-GB&ipa=%2F%CB%88s%C9%AAt%CA%83.u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=situate&lang=en-US&ipa=%2F%CB%88s%C9%AAt%CA%83.u.e%C9%AAt%2F"},{"id":"lv_2_113","topic":"Tourism and Visits","word":"solar","pos":"(adj)","ipa":"/ˈsoʊ.lɚ/","defVi":"thuộc về năng lượng mặt trời, thái dương","defEn":"connected with or using the energy of the sun","examples":["Many homeowners are installing [solar] panels to reduce electricity costs. (=Dịch: Nhiều chủ nhà đang lắp đặt các tấm pin mặt trời để giảm chi phí tiền điện.)","Investing in [solar] energy is crucial for a sustainable future. (=Dịch: Đầu tư vào năng lượng mặt trời là rất quan trọng cho một tương lai bền vững.)","The planet Earth is the third planet from the sun in our [solar] system. (=Dịch: Trái đất là hành tinh thứ ba tính từ mặt trời trong hệ mặt trời của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=solar&lang=en-GB&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=solar&lang=en-US&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F"},{"id":"lv_2_114","topic":"Tourism and Visits","word":"souvenir","pos":"(n)","ipa":"/ˌsuː.vəˈnɪr/","defVi":"quà lưu niệm, vật kỷ niệm","defEn":"something kept or bought as a reminder of a place, person, or event","examples":["She bought a handmade postcard as a [souvenir] of her trip to Paris. (=Dịch: Cô ấy đã mua một tấm bưu thiếp thủ công làm quà lưu niệm cho chuyến đi Paris của mình.)","The small gift shop sells a variety of local [souvenir] items. (=Dịch: Cửa hàng quà tặng nhỏ bán nhiều món đồ lưu niệm địa phương đa dạng.)","I kept the concert ticket stub as a [souvenir] of that wonderful night. (=Dịch: Tôi đã giữ lại cuống vé buổi hòa nhạc làm kỷ niệm cho đêm tuyệt vời đó.)"],"ukAudio":"/ai_services/tts3/?q=souvenir&lang=en-GB&ipa=%2F%CB%8Csu%CB%90.v%C9%99%CB%88n%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=souvenir&lang=en-US&ipa=%2F%CB%8Csu%CB%90.v%C9%99%CB%88n%C9%AAr%2F"},{"id":"lv_2_115","topic":"Tourism and Visits","word":"specialised","pos":"(adj)","ipa":"/ˈspɛʃ.ə.laɪzd/","defVi":"chuyên dụng, chuyên môn hóa","defEn":"trained, designed, or developed for a particular purpose or area of knowledge","examples":["Performing this complex surgery requires [specialised] medical equipment. (=Dịch: Việc thực hiện ca phẫu thuật phức tạp này đòi hỏi các thiết bị y tế chuyên dụng.)","She sought advice from a lawyer with [specialised] knowledge in intellectual property. (=Dịch: Cô ấy đã tìm kiếm lời khuyên từ một luật sư có kiến thức chuyên môn sâu về sở hữu trí tuệ.)","The company offers [specialised] training programs for new engineers. (=Dịch: Công ty cung cấp các chương trình đào tạo chuyên biệt cho các kỹ sư mới.)"],"ukAudio":"/ai_services/tts3/?q=specialised&lang=en-GB&ipa=%2F%CB%88sp%C9%9B%CA%83.%C9%99.la%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=specialised&lang=en-US&ipa=%2F%CB%88sp%C9%9B%CA%83.%C9%99.la%C9%AAzd%2F"},{"id":"lv_2_116","topic":"Tourism and Visits","word":"spectacular","pos":"(adj)","ipa":"/spɛkˈtæk.jə.lɚ/","defVi":"hùng vĩ, ngoạn mục, ấn tượng","defEn":"extremely impressive, grand, or striking to see","examples":["The mountaintop offers a [spectacular] view of the entire valley. (=Dịch: Đỉnh núi mang lại một khung cảnh ngoạn mục của toàn bộ thung lũng.)","The festival ended with a [spectacular] fireworks display over the lake. (=Dịch: Lễ hội đã kết thúc với một màn trình diễn pháo hoa ngoạn mục trên hồ.)","The team achieved a [spectacular] victory in the final minutes of the match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fsp%C9%9Bk%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fsp%C9%9Bk%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_2_117","topic":"Tourism and Visits","word":"splash","pos":"(n)","ipa":"/splæʃ/","defVi":"tiếng nước bắn, vết bắn nước","defEn":"the sound or movement of liquid scattering when hit by an object","examples":["We heard a loud [splash] when the children jumped into the pool. (=Dịch: Chúng tôi nghe thấy một tiếng nước bắn lớn khi lũ trẻ nhảy xuống hồ bơi.)","The passing car made a large [splash] of muddy water on the sidewalk. (=Dịch: Chiếc xe chạy qua đã làm bắn một vệt nước bùn lớn lên vỉa hè.)","A [splash] of lemon juice will enhance the fresh flavor of the salad. (=Dịch: Một vài giọt nước cốt chanh sẽ làm tăng hương vị tươi ngon của món salad.)"],"ukAudio":"/ai_services/tts3/?q=splash&lang=en-GB&ipa=%2Fspl%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=splash&lang=en-US&ipa=%2Fspl%C3%A6%CA%83%2F"},{"id":"lv_2_118","topic":"Tourism and Visits","word":"stable","pos":"(n)","ipa":"/ˈsteɪ.bəl/","defVi":"chuồng ngựa","defEn":"a building where domestic animals, especially horses, are kept and fed","examples":["The farmer led the racehorses into the [stable] before the storm began. (=Dịch: Người nông dân đã dẫn những con ngựa đua vào chuồng trước khi cơn bão bắt đầu.)","She spent the morning cleaning out each [stable] at the equestrian center. (=Dịch: Cô ấy đã dành cả buổi sáng để dọn dẹp từng ô chuồng tại trung tâm cưỡi ngựa.)","There were ten horses resting quietly inside the wooden [stable]. (=Dịch: Có mười con ngựa đang nghỉ ngơi yên tĩnh bên trong chuồng ngựa bằng gỗ.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_2_119","topic":"Tourism and Visits","word":"stadium","pos":"(n)","ipa":"/ˈsteɪ.di.əm/","defVi":"sân vận động","defEn":"a large sports ground surrounded by tiers of seats for spectators","examples":["Thousands of excited fans gathered inside the [stadium] for the championship match. (=Dịch: Hàng ngàn người hâm mộ cuồng nhiệt đã tụ tập bên trong sân vận động để theo dõi trận chung kết.)","The rock band will perform live at the national [stadium] next month. (=Dịch: Ban nhạc rock sẽ biểu diễn trực tiếp tại sân vận động quốc gia vào tháng tới.)","The city invested millions of dollars to build a modern sports [stadium]. (=Dịch: Thành phố đã đầu tư hàng triệu đô la để xây dựng một sân vận động thể thao hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=stadium&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stadium&lang=en-US&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F"},{"id":"lv_2_120","topic":"Tourism and Visits","word":"staircase","pos":"(n)","ipa":"/ˈster.keɪs/","defVi":"cầu thang","defEn":"a set of stairs inside a building, including its supporting structure","examples":["We walked up the spiral [staircase] to reach the top floor. (=Dịch: Chúng tôi bước lên chiếc cầu thang xoắn ốc để lên tầng trên cùng.)","The grand [staircase] in the hotel lobby impressed all the guests. (=Dịch: Chiếc cầu thang tráng lệ ở sảnh khách sạn đã gây ấn tượng với tất cả các vị khách.)","She carefully descended the wooden [staircase] in the dark. (=Dịch: Cô ấy cẩn thận bước xuống chiếc cầu thang gỗ trong bóng tối.)"],"ukAudio":"/ai_services/tts3/?q=staircase&lang=en-GB&ipa=%2F%CB%88ster.ke%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=staircase&lang=en-US&ipa=%2F%CB%88ster.ke%C9%AAs%2F"},{"id":"lv_2_121","topic":"Tourism and Visits","word":"stall","pos":"(n)","ipa":"/stɔːl/","defVi":"quầy hàng, sạp hàng","defEn":"a large table or small open-fronted shop from which goods are sold in a market","examples":["She bought fresh fruits from a market [stall]. (=Dịch: Cô ấy đã mua trái cây tươi từ một quầy hàng ở chợ.)","The street food [stall] attracts hundreds of customers every evening. (=Dịch: Quầy ẩm thực đường phố thu hút hàng trăm thực khách mỗi tối.)","He decided to set up a book [stall] near the university. (=Dịch: Anh ấy quyết định dựng một quầy sách gần trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=stall&lang=en-GB&ipa=%2Fst%C9%94%CB%90l%2F","usAudio":"/ai_services/tts3/?q=stall&lang=en-US&ipa=%2Fst%C9%94%CB%90l%2F"},{"id":"lv_2_122","topic":"Tourism and Visits","word":"steam","pos":"(n)","ipa":"/stiːm/","defVi":"hơi nước","defEn":"the hot gas that is produced when water boils","examples":["White [steam] rose from the boiling kettle. (=Dịch: Hơi nước trắng bốc lên từ chiếc ấm đang sôi.)","The bathroom mirror was covered in thick [steam]. (=Dịch: Gương trong phòng tắm bị bao phủ bởi một lớp hơi nước dày đặc.)","The factory uses [steam] power to generate electricity. (=Dịch: Nhà máy sử dụng năng lượng hơi nước để phát điện.)"],"ukAudio":"/ai_services/tts3/?q=steam&lang=en-GB&ipa=%2Fsti%CB%90m%2F","usAudio":"/ai_services/tts3/?q=steam&lang=en-US&ipa=%2Fsti%CB%90m%2F"},{"id":"lv_2_123","topic":"Tourism and Visits","word":"stunning","pos":"(adj)","ipa":"/ˈstʌn.ɪŋ/","defVi":"tuyệt đẹp, lộng lẫy, ấn tượng sâu sắc","defEn":"extremely impressive, beautiful, or attractive","examples":["The hotel room offers a [stunning] view of the ocean. (=Dịch: Phòng khách sạn có tầm nhìn tuyệt đẹp hướng ra đại dương.)","She looked absolutely [stunning] in her wedding dress. (=Dịch: Cô ấy trông vô cùng lộng lẫy trong chiếc váy cưới.)","The team achieved a [stunning] victory in the final match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong trận chung kết.)"],"ukAudio":"/ai_services/tts3/?q=stunning&lang=en-GB&ipa=%2F%CB%88st%CA%8Cn.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=stunning&lang=en-US&ipa=%2F%CB%88st%CA%8Cn.%C9%AA%C5%8B%2F"},{"id":"lv_2_124","topic":"Tourism and Visits","word":"summit","pos":"(n)","ipa":"/ˈsʌm.ɪt/","defVi":"đỉnh núi; hội nghị thượng đỉnh","defEn":"the highest point of a mountain; or an official meeting between heads of government","examples":["The climbers finally reached the [summit] after hours of hiking. (=Dịch: Những người leo núi cuối cùng đã lên tới đỉnh núi sau nhiều giờ đi bộ đường dài.)","World leaders gathered in Geneva for an economic [summit]. (=Dịch: Các nhà lãnh đạo thế giới đã tập trung tại Geneva để tham dự một hội nghị thượng đỉnh về kinh tế.)","Thick clouds hid the mountain [summit] from view. (=Dịch: Những đám mây dày đặc đã che khuất đỉnh núi khỏi tầm nhìn.)"],"ukAudio":"/ai_services/tts3/?q=summit&lang=en-GB&ipa=%2F%CB%88s%CA%8Cm.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=summit&lang=en-US&ipa=%2F%CB%88s%CA%8Cm.%C9%AAt%2F"},{"id":"lv_2_125","topic":"Tourism and Visits","word":"sunny","pos":"(adj)","ipa":"/ˈsʌn.i/","defVi":"có nắng, ngập tràn ánh nắng","defEn":"bright with sunlight; receiving a lot of direct light from the sun","examples":["We enjoyed a picnic in the park on a warm, [sunny] day. (=Dịch: Chúng tôi đã tận hưởng một buổi dã ngoại trong công viên vào một ngày ấm áp và đầy nắng.)","The living room is very bright and [sunny] in the morning. (=Dịch: Phòng khách rất sáng sủa và ngập tràn ánh nắng vào buổi sáng.)","They planned their holiday to a [sunny] coastal town. (=Dịch: Họ đã lên kế hoạch cho kỳ nghỉ của mình đến một thị trấn ven biển đầy nắng.)"],"ukAudio":"/ai_services/tts3/?q=sunny&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.i%2F","usAudio":"/ai_services/tts3/?q=sunny&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.i%2F"},{"id":"lv_2_126","topic":"Tourism and Visits","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng bổ sung","defEn":"something added to complete a thing, make up for a deficiency, or extend an existing item","examples":["He takes a daily vitamin [supplement] to boost his immune system. (=Dịch: Anh ấy uống thực phẩm bổ sung vitamin hằng ngày để tăng cường hệ miễn dịch.)","The weekend newspaper includes a colorful travel [supplement]. (=Dịch: Tờ báo cuối tuần bao gồm một phụ trương du lịch đầy màu sắc.)","Calcium is an important nutritional [supplement] for older adults. (=Dịch: Canxi là một chất bổ sung dinh dưỡng quan trọng cho người lớn tuổi.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_2_127","topic":"Tourism and Visits","word":"surf","pos":"(v)","ipa":"/sɜːrf/","defVi":"lướt sóng; lướt web","defEn":"to ride on waves while standing on a special board; or to look through information on the internet","examples":["Many tourists visit this beach to [surf] the giant waves. (=Dịch: Nhiều du khách ghé thăm bãi biển này để lướt những con sóng khổng lồ.)","He often spends his free time [surfing] the internet for news. (=Dịch: Anh ấy thường dành thời gian rảnh để lướt mạng xem tin tức.)","She learned how to [surf] during her summer vacation in Hawaii. (=Dịch: Cô ấy đã học lướt sóng trong kỳ nghỉ hè ở Hawaii.)"],"ukAudio":"/ai_services/tts3/?q=surf&lang=en-GB&ipa=%2Fs%C9%9C%CB%90rf%2F","usAudio":"/ai_services/tts3/?q=surf&lang=en-US&ipa=%2Fs%C9%9C%CB%90rf%2F"},{"id":"lv_2_128","topic":"Tourism and Visits","word":"tape","pos":"(n)","ipa":"/teɪp/","defVi":"băng dính; băng từ (ghi âm, ghi hình)","defEn":"a long, narrow strip of sticky material used to hold things together, or a magnetic strip used for recording","examples":["She used adhesive [tape] to seal the cardboard box. (=Dịch: Cô ấy đã dùng băng dính để dán kín chiếc hộp các-tông.)","My grandfather still listens to music on an old cassette [tape]. (=Dịch: Ông tôi vẫn nghe nhạc bằng một cuộn băng cát-xét cũ.)","The police marked the crime scene with yellow warning [tape]. (=Dịch: Cảnh sát đã khoanh vùng hiện trường vụ án bằng băng cảnh báo màu vàng.)"],"ukAudio":"/ai_services/tts3/?q=tape&lang=en-GB&ipa=%2Fte%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=tape&lang=en-US&ipa=%2Fte%C9%AAp%2F"},{"id":"lv_2_129","topic":"Tourism and Visits","word":"telegraph","pos":"(n)","ipa":"/ˈtel.ə.ɡræf/","defVi":"điện báo, máy điện báo","defEn":"an early system or device used for sending messages along wires over long distances","examples":["The invention of the [telegraph] revolutionized long-distance communication. (=Dịch: Phát minh ra máy điện báo đã cách mạng hóa phương thức liên lạc đường dài.)","Before telephones were common, urgent news was sent by [telegraph]. (=Dịch: Trước khi điện thoại trở nên phổ biến, tin tức khẩn cấp được gửi bằng điện báo.)","The operator decoded the incoming message from the electric [telegraph]. (=Dịch: Người điện báo viên đã giải mã tin nhắn nhận được từ máy điện báo.)"],"ukAudio":"/ai_services/tts3/?q=telegraph&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=telegraph&lang=en-US&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F"},{"id":"lv_2_130","topic":"Tourism and Visits","word":"temporarily","pos":"(adv)","ipa":"/ˌtɛm.pəˈrɛr.ə.li/","defVi":"tạm thời","defEn":"for a limited time only and not permanently","examples":["The library will be [temporarily] closed for renovations next week. (=Dịch: Thư viện sẽ tạm thời đóng cửa để cải tạo vào tuần tới.)","She is [temporarily] staying with her aunt until she finds an apartment. (=Dịch: Cô ấy đang tạm thời ở cùng dì của mình cho đến khi tìm được một căn hộ.)","The website is [temporarily] unavailable due to technical issues. (=Dịch: Trang web tạm thời không thể truy cập do các sự cố kỹ thuật.)"],"ukAudio":"/ai_services/tts3/?q=temporarily&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Bm.p%C9%99%CB%88r%C9%9Br.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=temporarily&lang=en-US&ipa=%2F%CB%8Ct%C9%9Bm.p%C9%99%CB%88r%C9%9Br.%C9%99.li%2F"},{"id":"lv_2_131","topic":"Tourism and Visits","word":"terrace","pos":"(n)","ipa":"/ˈtɛr.əs/","defVi":"sân thượng, sân hiên","defEn":"a flat outdoor area next to a building or on a roof, used for relaxing","examples":["We had breakfast outside on the hotel [terrace] overlooking the ocean. (=Dịch: Chúng tôi đã ăn sáng ngoài trời trên sân hiên khách sạn nhìn ra đại dương.)","The restaurant has a rooftop [terrace] with a wonderful view of the city. (=Dịch: Nhà hàng có sân thượng với tầm nhìn tuyệt đẹp ra thành phố.)","Potted plants and comfortable chairs decorated the spacious [terrace]. (=Dịch: Những chậu cây và những chiếc ghế thoải mái tô điểm cho khoảng sân hiên rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=terrace&lang=en-GB&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=terrace&lang=en-US&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F"},{"id":"lv_2_132","topic":"Tourism and Visits","word":"tractor","pos":"(n)","ipa":"/ˈtræk.tɚ/","defVi":"máy kéo","defEn":"a powerful vehicle with large tires used on farms to pull heavy equipment","examples":["The farmer used a [tractor] to plow the vast cornfields. (=Dịch: Người nông dân đã dùng một chiếc máy kéo để cày những cánh đồng ngô rộng lớn.)","A broken [tractor] was parked near the entrance of the barn. (=Dịch: Một chiếc máy kéo bị hỏng đỗ gần lối vào của nhà kho.)","Modern [tractor] models are equipped with GPS technology for precise farming. (=Dịch: Các mẫu máy kéo hiện đại được trang bị công nghệ GPS để canh tác chuẩn xác.)"],"ukAudio":"/ai_services/tts3/?q=tractor&lang=en-GB&ipa=%2F%CB%88tr%C3%A6k.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tractor&lang=en-US&ipa=%2F%CB%88tr%C3%A6k.t%C9%9A%2F"},{"id":"lv_2_133","topic":"Tourism and Visits","word":"tram","pos":"(n)","ipa":"/træm/","defVi":"xe điện (chạy trên đường ray)","defEn":"an electric vehicle that moves along rails in the streets of a city","examples":["Taking the [tram] is the fastest way to get across the downtown area. (=Dịch: Đi xe điện là cách nhanh nhất để di chuyển qua khu vực trung tâm thành phố.)","She waited at the stop for the next [tram] to arrive. (=Dịch: Cô ấy đã đợi ở trạm chờ chuyến xe điện tiếp theo đến.)","Many European cities still rely heavily on the [tram] for public transport. (=Dịch: Nhiều thành phố châu Âu vẫn phụ thuộc rất nhiều vào xe điện cho giao thông công cộng.)"],"ukAudio":"/ai_services/tts3/?q=tram&lang=en-GB&ipa=%2Ftr%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=tram&lang=en-US&ipa=%2Ftr%C3%A6m%2F"},{"id":"lv_2_134","topic":"Tourism and Visits","word":"trek","pos":"(n)","ipa":"/trɛk/","defVi":"chuyến đi bộ đường dài, hành trình vất vả","defEn":"a long, difficult journey, usually made on foot","examples":["They organized a week-long [trek] through the Himalayan mountains. (=Dịch: Họ đã tổ chức một chuyến đi bộ đường dài kéo dài một tuần qua dãy núi Himalaya.)","The walk back home in the heavy snow felt like a difficult [trek]. (=Dịch: Quãng đường đi bộ về nhà trong tuyết dày cảm giác như một chuyến đi đầy gian nan.)","Proper footwear is essential for a safe [trek] across rugged terrain. (=Dịch: Giày dép phù hợp là điều thiết yếu cho một chuyến đi bộ an toàn qua địa hình gồ ghề.)"],"ukAudio":"/ai_services/tts3/?q=trek&lang=en-GB&ipa=%2Ftr%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=trek&lang=en-US&ipa=%2Ftr%C9%9Bk%2F"},{"id":"lv_2_135","topic":"Tourism and Visits","word":"tuition","pos":"(n)","ipa":"/tuˈɪʃ.ən/","defVi":"học phí","defEn":"money that you pay for being taught, especially at a college or university","examples":["The university announced an increase in [tuition] for the upcoming academic year. (=Dịch: Trường đại học đã thông báo tăng học phí cho năm học sắp tới.)","She received a full scholarship that covered all of her college [tuition]. (=Dịch: Cô ấy đã nhận được học bổng toàn phần chi trả toàn bộ học phí đại học.)","Many students work part-time jobs to help pay for their [tuition] and living expenses. (=Dịch: Nhiều sinh viên làm công việc bán thời gian để trang trải học phí và chi phí sinh hoạt.)"],"ukAudio":"/ai_services/tts3/?q=tuition&lang=en-GB&ipa=%2Ftu%CB%88%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=tuition&lang=en-US&ipa=%2Ftu%CB%88%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_2_136","topic":"Tourism and Visits","word":"turtle","pos":"(n)","ipa":"/ˈtɝ.t̬əl/","defVi":"con rùa","defEn":"a reptile with a hard, round shell that moves slowly and lives on land or in water","examples":["We saw a sea [turtle] swimming gracefully near the coral reef. (=Dịch: Chúng tôi đã nhìn thấy một con rùa biển bơi lội duyên dáng gần rạn san hô.)","The baby [turtle] crawled across the sand toward the ocean waves. (=Dịch: Con rùa con bò qua bãi cát về phía những con sóng biển.)","A [turtle] can retract its head and legs into its shell when threatened. (=Dịch: Một con rùa có thể rụt đầu và chân vào mai khi bị đe dọa.)"],"ukAudio":"/ai_services/tts3/?q=turtle&lang=en-GB&ipa=%2F%CB%88t%C9%9D.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=turtle&lang=en-US&ipa=%2F%CB%88t%C9%9D.t%CC%AC%C9%99l%2F"},{"id":"lv_2_137","topic":"Tourism and Visits","word":"unsure","pos":"(adj)","ipa":"/ʌnˈʃʊr/","defVi":"không chắc chắn, lưỡng lự","defEn":"not feeling certain, confident, or definite about something","examples":["I am still [unsure] about which university course to choose. (=Dịch: Tôi vẫn chưa chắc chắn về việc nên chọn khóa học đại học nào.)","He gave an [unsure] smile because he did not understand the joke. (=Dịch: Anh ấy nở một nụ cười ngập ngừng vì không hiểu câu chuyện đùa.)","If you are [unsure] of the instructions, please ask the teacher for help. (=Dịch: Nếu bạn chưa rõ các chỉ dẫn, hãy nhờ giáo viên giúp đỡ.)"],"ukAudio":"/ai_services/tts3/?q=unsure&lang=en-GB&ipa=%2F%CA%8Cn%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=unsure&lang=en-US&ipa=%2F%CA%8Cn%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_2_138","topic":"Tourism and Visits","word":"upper","pos":"(adj)","ipa":"/ˈʌp.ɚ/","defVi":"ở phía trên, tầng trên","defEn":"located higher up or in a top position","examples":["The bedrooms are located on the [upper] floor of the house. (=Dịch: Các phòng ngủ nằm ở tầng trên của ngôi nhà.)","He had an injury to his [upper] arm during the tennis match. (=Dịch: Anh ấy đã bị chấn thương ở phần bắp tay trên trong trận đấu quần vợt.)","The [upper] levels of management attended the annual business summit. (=Dịch: Các cấp quản lý cấp cao đã tham dự hội nghị thượng đỉnh kinh doanh thường niên.)"],"ukAudio":"/ai_services/tts3/?q=upper&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=upper&lang=en-US&ipa=%2F%CB%88%CA%8Cp.%C9%9A%2F"},{"id":"lv_2_139","topic":"Tourism and Visits","word":"vegetarian","pos":"(adj)","ipa":"/ˌvɛdʒ.əˈtɛr.i.ən/","defVi":"ăn chay, (món) chay","defEn":"relating to a diet or meals that do not contain any meat or fish","examples":["The café offers a wide variety of delicious [vegetarian] options. (=Dịch: Quán cà phê có nhiều lựa chọn món chay ngon miệng.)","She follows a strict [vegetarian] lifestyle for ethical and environmental reasons. (=Dịch: Cô ấy theo đuổi lối sống ăn chay nghiêm ngặt vì các lý do đạo đức và môi trường.)","We ordered a [vegetarian] pizza topped with mushrooms, peppers, and olives. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza chay phủ nấm, ớt chuông và ô liu.)"],"ukAudio":"/ai_services/tts3/?q=vegetarian&lang=en-GB&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetarian&lang=en-US&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F"},{"id":"lv_2_140","topic":"Tourism and Visits","word":"vip","pos":"(n)","ipa":"/ˌviː.aɪˈpiː/","defVi":"khách VIP, nhân vật rất quan trọng","defEn":"a very important person who receives special treatment and privileges","examples":["The hotel provides a private lounge for each [VIP] guest. (=Dịch: Khách sạn cung cấp một phòng chờ riêng cho mỗi khách VIP.)","Security was tightened around the concert hall before the [VIP] arrived. (=Dịch: An ninh đã được thắt chặt quanh hội trường hòa nhạc trước khi khách VIP đến.)","Ticket holders for the [VIP] section had access to backstage passes. (=Dịch: Những người sở hữu vé khu vực VIP được cấp thẻ vào khu vực hậu trường.)"],"ukAudio":"/ai_services/tts3/?q=vip&lang=en-GB&ipa=%2F%CB%8Cvi%CB%90.a%C9%AA%CB%88pi%CB%90%2F","usAudio":"/ai_services/tts3/?q=vip&lang=en-US&ipa=%2F%CB%8Cvi%CB%90.a%C9%AA%CB%88pi%CB%90%2F"},{"id":"lv_2_141","topic":"Tourism and Visits","word":"wagon","pos":"(n)","ipa":"/ˈwæɡ.ən/","defVi":"xe ngựa kéo, xe goòng, xe bò","defEn":"a heavy four-wheeled vehicle pulled by horses or oxen, used for carrying heavy loads","examples":["The pioneers crossed the plains in a wooden [wagon]. (=Dịch: Những người khai hoang đã băng qua các đồng bằng trên một chiếc xe ngựa kéo bằng gỗ.)","Farmers used a [wagon] to transport sacks of grain to the local mill. (=Dịch: Nông dân đã dùng xe kéo để vận chuyển các bao ngũ cốc đến cối xay địa phương.)","A broken wheel brought the heavy [wagon] to a sudden halt. (=Dịch: Một chiếc bánh xe bị gãy đã khiến chiếc xe kéo nặng nề đột ngột dừng lại.)"],"ukAudio":"/ai_services/tts3/?q=wagon&lang=en-GB&ipa=%2F%CB%88w%C3%A6%C9%A1.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=wagon&lang=en-US&ipa=%2F%CB%88w%C3%A6%C9%A1.%C9%99n%2F"},{"id":"lv_2_142","topic":"Tourism and Visits","word":"wander","pos":"(v)","ipa":"/ˈwɑːn.dɚ/","defVi":"đi lang thang, tản bộ","defEn":"to walk or move around without a clear purpose or direction","examples":["Tourists often [wander] through the narrow streets of the old quarter. (=Dịch: Khách du lịch thường đi lang thang qua những con phố hẹp của khu phố cổ.)","The lost child began to [wander] aimlessly across the park. (=Dịch: Đứa trẻ bị lạc bắt đầu đi lang thang không mục đích khắp công viên.)","He likes to [wander] into the bookstore during his lunch break. (=Dịch: Anh ấy thích tản bộ vào hiệu sách trong giờ nghỉ trưa.)"],"ukAudio":"/ai_services/tts3/?q=wander&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=wander&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90n.d%C9%9A%2F"},{"id":"lv_2_143","topic":"Tourism and Visits","word":"wetland","pos":"(n)","ipa":"/ˈwet.lənd/","defVi":"vùng đất ngập nước","defEn":"an area of land that is naturally saturated with water, such as a swamp or marsh","examples":["The coastal [wetland] provides a safe breeding ground for many rare birds. (=Dịch: Vùng đất ngập nước ven biển cung cấp nơi sinh sản an toàn cho nhiều loài chim quý hiếm.)","Environmentalists campaigned hard to protect the local [wetland] from commercial development. (=Dịch: Các nhà môi trường học đã vận động mạnh mẽ để bảo vệ vùng đất ngập nước địa phương khỏi sự phát triển thương mại.)","A guided boat tour took us deep into the mysterious [wetland]. (=Dịch: Một chuyến tham quan bằng thuyền có hướng dẫn viên đã đưa chúng tôi vào sâu bên trong vùng đất ngập nước đầy bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=wetland&lang=en-GB&ipa=%2F%CB%88wet.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=wetland&lang=en-US&ipa=%2F%CB%88wet.l%C9%99nd%2F"},{"id":"lv_2_144","topic":"Tourism and Visits","word":"wetsuit","pos":"(n)","ipa":"/ˈwet.suːt/","defVi":"bộ đồ lặn (giữ nhiệt)","defEn":"a tight-fitting rubber suit worn by divers and surfers to keep warm in cold water","examples":["He put on a thick [wetsuit] before diving into the chilly ocean. (=Dịch: Anh ấy mặc một bộ đồ lặn dày trước khi lặn xuống đại dương lạnh giá.)","Surfers hang their [wetsuit] gear to dry immediately after leaving the beach. (=Dịch: Những người lướt sóng treo bộ đồ lặn của họ lên cho khô ngay sau khi rời bãi biển.)","A properly fitted [wetsuit] prevents body heat from escaping in cold water. (=Dịch: Một bộ đồ lặn vừa vặn sẽ ngăn nhiệt lượng cơ thể thoát ra ngoài khi ở trong nước lạnh.)"],"ukAudio":"/ai_services/tts3/?q=wetsuit&lang=en-GB&ipa=%2F%CB%88wet.su%CB%90t%2F","usAudio":"/ai_services/tts3/?q=wetsuit&lang=en-US&ipa=%2F%CB%88wet.su%CB%90t%2F"},{"id":"lv_2_145","topic":"Tourism and Visits","word":"whale","pos":"(n)","ipa":"/ˈweɪl/","defVi":"cá voi","defEn":"a very large marine mammal that breathes air through a blowhole on top of its head","examples":["We were lucky enough to see a blue [whale] breach the surface of the sea. (=Dịch: Chúng tôi đã đủ may mắn khi nhìn thấy một con cá voi xanh nhô lên khỏi mặt biển.)","Many international treaties were signed to protect the endangered [whale] species. (=Dịch: Nhiều hiệp ước quốc tế đã được ký kết để bảo vệ các loài cá voi có nguy cơ tuyệt chủng.)","The guide pointed out a migrating [whale] swimming near our boat. (=Dịch: Người hướng dẫn viên đã chỉ cho chúng tôi một con cá voi đang di cư bơi gần thuyền.)"],"ukAudio":"/ai_services/tts3/?q=whale&lang=en-GB&ipa=%2F%CB%88we%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=whale&lang=en-US&ipa=%2F%CB%88we%C9%AAl%2F"},{"id":"lv_2_146","topic":"Tourism and Visits","word":"willow","pos":"(n)","ipa":"/ˈwɪl.oʊ/","defVi":"cây liễu","defEn":"a tree with long, flexible branches and narrow leaves that often grows near water","examples":["A weeping [willow] swayed gently over the edge of the riverbank. (=Dịch: Một cây liễu rủ đung đưa nhẹ nhàng bên mép bờ sông.)","The artist sketched the graceful shape of a [willow] in his notebook. (=Dịch: Người họa sĩ đã phác thảo hình dáng duyên dáng của một cây liễu vào cuốn sổ tay của mình.)","We sat under the shade of a large [willow] to escape the summer heat. (=Dịch: Chúng tôi ngồi dưới bóng mát của một cây liễu lớn để tránh cái nóng mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=willow&lang=en-GB&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=willow&lang=en-US&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F"},{"id":"lv_2_147","topic":"Tourism and Visits","word":"wooded","pos":"(adj)","ipa":"/ˈwʊd.ɪd/","defVi":"rậm rạp cây cối, có nhiều cây cối","defEn":"covered with growing trees or woods","examples":["The cabin was hidden deep in a dense, [wooded] valley. (=Dịch: Ngôi nhà gỗ nhỏ nằm ẩn sâu trong một thung lũng rậm rạp nhiều cây cối.)","Hikers followed a narrow trail that led up the [wooded] hillside. (=Dịch: Những người đi bộ đường dài đi theo một con đường mòn hẹp dẫn lên sườn đồi phủ đầy cây cối.)","Wildlife thrives in the vast [wooded] areas surrounding the mountain range. (=Dịch: Động vật hoang dã phát triển mạnh mẽ tại các khu vực nhiều cây cối rộng lớn bao quanh dãy núi.)"],"ukAudio":"/ai_services/tts3/?q=wooded&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=wooded&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F"},{"id":"lv_2_148","topic":"Tourism and Visits","word":"woodland","pos":"(n)","ipa":"/ˈwʊd.lənd/","defVi":"vùng đất rừng, vùng rừng cây","defEn":"land covered with trees, usually smaller in extent than a forest","examples":["A pleasant trail winds through the ancient [woodland]. (=Dịch: Một con đường mòn êm đềm uốn lượn qua khu rừng cổ thụ.)","Conservationists work tirelessly to preserve the native [woodland] habitat. (=Dịch: Các nhà bảo tồn làm việc không biết mệt mỏi để bảo vệ môi trường sống của vùng rừng cây bản địa.)","Deer and wild foxes often seek shelter in the nearby [woodland]. (=Dịch: Hươu và cáo hoang thường tìm nơi trú ẩn trong khu rừng gần đó.)"],"ukAudio":"/ai_services/tts3/?q=woodland&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=woodland&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.l%C9%99nd%2F"},{"id":"lv_2_149","topic":"Tourism and Visits","word":"yard","pos":"(n)","ipa":"/ˈjɑːrd/","defVi":"sân, bãi đất","defEn":"an area of land adjacent to a building, often grassy and enclosed","examples":["The children spent the afternoon playing soccer in the front [yard]. (=Dịch: Lũ trẻ đã dành cả buổi chiều để chơi bóng đá ở sân trước.)","She planted colorful flowers and fresh herbs in her back [yard]. (=Dịch: Cô ấy trồng những bông hoa rực rỡ sắc màu và các loại rau thơm tươi tốt ở sân sau.)","A tall wooden fence surrounds the entire [yard] for privacy. (=Dịch: Một hàng rào gỗ cao bao quanh toàn bộ sân để đảm bảo sự riêng tư.)"],"ukAudio":"/ai_services/tts3/?q=yard&lang=en-GB&ipa=%2F%CB%88j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=yard&lang=en-US&ipa=%2F%CB%88j%C9%91%CB%90rd%2F"},{"id":"lv_2_150","topic":"Tourism and Visits","word":"zoo","pos":"(n)","ipa":"/zu/","defVi":"sở thú, vườn bách thú","defEn":"a place where wild animals are kept in enclosures for public display, conservation, and study","examples":["The children were excited to visit the city [zoo] to see the pandas. (=Dịch: Những đứa trẻ rất hào hứng khi đến thăm sở thú thành phố để xem gấu trúc.)","Modern [zoos] play a vital role in the conservation of endangered species. (=Dịch: Các sở thú hiện đại đóng một vai trò quan trọng trong việc bảo tồn các loài có nguy cơ tuyệt chủng.)","Many people argue that keeping wild animals in a [zoo] limits their natural behavior. (=Dịch: Nhiều người cho rằng việc nuôi nhốt động vật hoang dã trong sở thú làm hạn chế tập tính tự nhiên của chúng.)"],"ukAudio":"/ai_services/tts3/?q=zoo&lang=en-GB&ipa=%2Fzu%2F","usAudio":"/ai_services/tts3/?q=zoo&lang=en-US&ipa=%2Fzu%2F"},{"id":"lv_3_0","topic":"Urban Planning and Infrastructure Construction","word":"acoustic","pos":"(adj)","ipa":"/əˈkuː.stɪk/","defVi":"(thuộc) âm học, cách âm, âm thanh mộc","defEn":"relating to sound or the sense of hearing; designed to control sound","examples":["The concert hall was praised for its excellent [acoustic] qualities. (=Dịch: Phòng hòa nhạc được ca ngợi vì chất lượng âm học tuyệt vời.)","He prefers playing an [acoustic] guitar rather than an electric one. (=Dịch: Anh ấy thích chơi đàn ghi-ta mộc hơn là ghi-ta điện.)","They installed special [acoustic] panels on the walls to block outside noise. (=Dịch: Họ đã lắp đặt các tấm cách âm đặc biệt trên tường để ngăn tiếng ồn bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=acoustic&lang=en-GB&ipa=%2F%C9%99%CB%88ku%CB%90.st%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=acoustic&lang=en-US&ipa=%2F%C9%99%CB%88ku%CB%90.st%C9%AAk%2F"},{"id":"lv_3_1","topic":"Urban Planning and Infrastructure Construction","word":"agenda","pos":"(n)","ipa":"/əˈdʒen.də/","defVi":"chương trình nghị sự, lịch trình làm việc","defEn":"a list of matters or topics to be discussed at a meeting","examples":["Environmental protection is top on the committee's [agenda]. (=Dịch: Bảo vệ môi trường là ưu tiên hàng đầu trong chương trình nghị sự của ủy ban.)","We have several important points on our [agenda] today. (=Dịch: Chúng ta có một vài nội dung quan trọng trong chương trình nghị sự hôm nay.)","What is the next item on the meeting [agenda]? (=Dịch: Mục tiếp theo trong chương trình nghị sự của cuộc họp là gì?)"],"ukAudio":"/ai_services/tts3/?q=agenda&lang=en-GB&ipa=%2F%C9%99%CB%88d%CA%92en.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=agenda&lang=en-US&ipa=%2F%C9%99%CB%88d%CA%92en.d%C9%99%2F"},{"id":"lv_3_2","topic":"Urban Planning and Infrastructure Construction","word":"agreement","pos":"(n)","ipa":"/əˈɡriː.mənt/","defVi":"sự đồng ý, thỏa thuận, hợp đồng","defEn":"a decision or arrangement that is shared and accepted by two or more people or groups","examples":["Both companies finally signed a trade [agreement] yesterday. (=Dịch: Cả hai công ty cuối cùng đã ký một thỏa thuận thương mại vào ngày hôm qua.)","They reached an [agreement] on how to divide the project tasks. (=Dịch: Họ đã đạt được thỏa thuận về cách phân chia các nhiệm vụ trong dự án.)","We are all in [agreement] that further research is required. (=Dịch: Tất cả chúng tôi đều đồng tình rằng cần phải nghiên cứu thêm.)"],"ukAudio":"/ai_services/tts3/?q=agreement&lang=en-GB&ipa=%2F%C9%99%CB%88%C9%A1ri%CB%90.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=agreement&lang=en-US&ipa=%2F%C9%99%CB%88%C9%A1ri%CB%90.m%C9%99nt%2F"},{"id":"lv_3_3","topic":"Urban Planning and Infrastructure Construction","word":"asia","pos":"(n)","ipa":"/ˈeɪ.ʒə/","defVi":"Châu Á","defEn":"the largest continent in the world, located mainly in the eastern and northern hemispheres","examples":["Many fast-growing economies are located in [Asia]. (=Dịch: Nhiều nền kinh tế tăng trưởng nhanh nằm ở châu Á.)","He spent two years traveling across Southeast [Asia]. (=Dịch: Anh ấy đã dành hai năm đi du lịch khắp Đông Nam Á.)","The cultural diversity in [Asia] attracts millions of tourists each year. (=Dịch: Sự đa dạng văn hóa ở châu Á thu hút hàng triệu khách du lịch mỗi năm.)"],"ukAudio":"/ai_services/tts3/?q=asia&lang=en-GB&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99%2F","usAudio":"/ai_services/tts3/?q=asia&lang=en-US&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99%2F"},{"id":"lv_3_4","topic":"Urban Planning and Infrastructure Construction","word":"auditorium","pos":"(n)","ipa":"/ˌɑː.dəˈtɔːr.i.əm/","defVi":"hội trường, thính phòng","defEn":"a large room or building used for public gatherings, speeches, or stage performances","examples":["The graduation ceremony will take place in the school [auditorium]. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại hội trường của trường.)","Hundreds of spectators gathered in the [auditorium] for the concert. (=Dịch: Hàng trăm khán giả đã tập trung tại khán phòng để tham dự buổi hòa nhạc.)","The university renovated its main [auditorium] to improve acoustics. (=Dịch: Trường đại học đã cải tạo hội trường chính để cải thiện chất lượng âm học.)"],"ukAudio":"/ai_services/tts3/?q=auditorium&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=auditorium&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F"},{"id":"lv_3_5","topic":"Urban Planning and Infrastructure Construction","word":"barge","pos":"(n)","ipa":"/bɑːrdʒ/","defVi":"sà lan, thuyền đáy bằng chở hàng","defEn":"a large flat-bottomed boat used for carrying heavy freight on canals and rivers","examples":["A heavy [barge] slowly transported coal down the river. (=Dịch: Một chiếc sà lan nặng nề từ từ chở than xuôi dòng sông.)","They converted an old canal [barge] into a floating cafe. (=Dịch: Họ đã cải tạo một chiếc sà lan cũ trên kênh đào thành một quán cà phê nổi.)","The cargo [barge] was loaded with building materials for the project. (=Dịch: Chiếc sà lan chở hàng đã được chất đầy vật liệu xây dựng cho dự án.)"],"ukAudio":"/ai_services/tts3/?q=barge&lang=en-GB&ipa=%2Fb%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=barge&lang=en-US&ipa=%2Fb%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_3_6","topic":"Urban Planning and Infrastructure Construction","word":"billion","pos":"(n)","ipa":"/ˈbɪl.jən/","defVi":"tỷ (1.000.000.000)","defEn":"the number 1,000,000,000 (one thousand million)","examples":["The company invested over one [billion] dollars in renewable energy. (=Dịch: Công ty đã đầu tư hơn một tỷ đô la vào năng lượng tái tạo.)","The world's population has now surpassed eight [billion] people. (=Dịch: Dân số thế giới hiện đã vượt qua mức tám tỷ người.)","Scientists estimate that the galaxy contains [billions] of stars. (=Dịch: Các nhà khoa học ước tính rằng thiên hà chứa hàng tỷ ngôi sao.)"],"ukAudio":"/ai_services/tts3/?q=billion&lang=en-GB&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=billion&lang=en-US&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F"},{"id":"lv_3_7","topic":"Urban Planning and Infrastructure Construction","word":"briefly","pos":"(adv)","ipa":"/ˈbriːf.li/","defVi":"ngắn gọn, thoáng qua, trong thời gian ngắn","defEn":"for a short time; using only a few words","examples":["The director spoke [briefly] about the future goals of the organization. (=Dịch: Giám đốc đã nói ngắn gọn về các mục tiêu tương lai của tổ chức.)","They stopped [briefly] in Paris before continuing their journey to Rome. (=Dịch: Họ đã dừng lại một lát ở Paris trước khi tiếp tục hành trình đến Rome.)","Please explain [briefly] why you are suitable for this position. (=Dịch: Xin vui lòng giải thích ngắn gọn lý do tại sao bạn phù hợp với vị trí này.)"],"ukAudio":"/ai_services/tts3/?q=briefly&lang=en-GB&ipa=%2F%CB%88bri%CB%90f.li%2F","usAudio":"/ai_services/tts3/?q=briefly&lang=en-US&ipa=%2F%CB%88bri%CB%90f.li%2F"},{"id":"lv_3_8","topic":"Urban Planning and Infrastructure Construction","word":"canal","pos":"(n)","ipa":"/kəˈnæl/","defVi":"kênh, kênh đào (nhân tạo)","defEn":"an artificial waterway built for boats to travel along or for irrigation","examples":["The Panama [Canal] is a vital route for international maritime trade. (=Dịch: Kênh đào Panama là tuyến đường huyết mạch cho thương mại hàng hải quốc tế.)","Tourists enjoy taking boat trips along the city's historic [canals]. (=Dịch: Khách du lịch thích đi thuyền dọc theo các con kênh lịch sử của thành phố.)","The farmers built an irrigation [canal] to supply water to their fields. (=Dịch: Các nông dân đã xây dựng một kênh thủy lợi để cung cấp nước cho đồng ruộng của họ.)"],"ukAudio":"/ai_services/tts3/?q=canal&lang=en-GB&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=canal&lang=en-US&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_3_9","topic":"Urban Planning and Infrastructure Construction","word":"canteen","pos":"(n)","ipa":"/kænˈtiːn/","defVi":"căng tin, nhà ăn tập thể","defEn":"a place in a school, office, or factory where meals are served to people","examples":["Students usually gather in the school [canteen] during lunch break. (=Dịch: Học sinh thường tụ tập ở căng tin trường học trong giờ nghỉ trưa.)","The factory [canteen] provides free hot meals for all workers. (=Dịch: Căng tin của nhà máy cung cấp các bữa ăn nóng sốt miễn phí cho tất cả công nhân.)","We bought sandwiches and drinks from the office [canteen]. (=Dịch: Chúng tôi đã mua bánh mì kẹp và đồ uống từ căng tin văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=canteen&lang=en-GB&ipa=%2Fk%C3%A6n%CB%88ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=canteen&lang=en-US&ipa=%2Fk%C3%A6n%CB%88ti%CB%90n%2F"},{"id":"lv_3_10","topic":"Urban Planning and Infrastructure Construction","word":"capacity","pos":"(n)","ipa":"/kəˈpæs.ə.t̬i/","defVi":"sức chứa, dung tích, năng lực","defEn":"the total amount that something can contain or produce","examples":["The new stadium has a seating [capacity] of over fifty thousand fans. (=Dịch: Sân vận động mới có sức chứa hơn năm mươi nghìn người hâm mộ.)","The factory is currently operating at full [capacity]. (=Dịch: Nhà máy hiện đang hoạt động hết công suất.)","She has an extraordinary [capacity] for remembering names and faces. (=Dịch: Cô ấy có một khả năng phi thường trong việc ghi nhớ tên và khuôn mặt.)"],"ukAudio":"/ai_services/tts3/?q=capacity&lang=en-GB&ipa=%2Fk%C9%99%CB%88p%C3%A6s.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=capacity&lang=en-US&ipa=%2Fk%C9%99%CB%88p%C3%A6s.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_11","topic":"Urban Planning and Infrastructure Construction","word":"channel","pos":"(n)","ipa":"/ˈtʃæn.əl/","defVi":"kênh truyền hình, phát thanh hoặc kênh thông tin/phân phối","defEn":"a television or radio station, or a method or system used for communication or distribution","examples":["He switched the [channel] to watch the evening news. (=Dịch: Anh ấy đã chuyển kênh để xem bản tin thời sự buổi tối.)","Social media has become an effective marketing [channel] for small businesses. (=Dịch: Mạng xã hội đã trở thành một kênh tiếp thị hiệu quả cho các doanh nghiệp nhỏ.)","The complaint should be submitted through the official [channel]. (=Dịch: Đơn khiếu nại nên được gửi thông qua kênh chính thức.)"],"ukAudio":"/ai_services/tts3/?q=channel&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=channel&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6n.%C9%99l%2F"},{"id":"lv_3_12","topic":"Urban Planning and Infrastructure Construction","word":"clinic","pos":"(n)","ipa":"/ˈklɪn.ɪk/","defVi":"phòng khám, trạm y tế","defEn":"a building or part of a hospital where people go for medical treatment or advice","examples":["She went to a local [clinic] to get her blood pressure checked. (=Dịch: Cô ấy đã đến một phòng khám địa phương để kiểm tra huyết áp.)","The dental [clinic] is open six days a week. (=Dịch: Phòng khám nha khoa mở cửa sáu ngày một tuần.)","Voluntary doctors opened a free health [clinic] for low-income families. (=Dịch: Các bác sĩ tình nguyện đã mở một phòng khám sức khỏe miễn phí cho các gia đình có thu nhập thấp.)"],"ukAudio":"/ai_services/tts3/?q=clinic&lang=en-GB&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=clinic&lang=en-US&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F"},{"id":"lv_3_13","topic":"Urban Planning and Infrastructure Construction","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stl/","defVi":"thuộc vùng biển, duyên hải, ven biển","defEn":"located on or near a coast","examples":["Global warming poses a severe threat to many [coastal] cities. (=Dịch: Hiện tượng nóng lên toàn cầu đặt ra mối đe dọa nghiêm trọng đối với nhiều thành phố ven biển.)","They decided to take a scenic drive along the [coastal] road. (=Dịch: Họ quyết định lái xe ngắm cảnh dọc theo con đường ven biển.)","Fishing is the primary source of income for this small [coastal] community. (=Dịch: Đánh bắt cá là nguồn thu nhập chính của cộng đồng ven biển nhỏ bé này.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.stl%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.stl%2F"},{"id":"lv_3_14","topic":"Urban Planning and Infrastructure Construction","word":"collate","pos":"(v)","ipa":"/kəˈleɪt/","defVi":"thu thập và đối chiếu, sắp xếp dữ liệu","defEn":"to collect and arrange information in a careful and logical order","examples":["The team spent weeks to [collate] data from various global surveys. (=Dịch: Nhóm đã dành nhiều tuần để đối chiếu và tổng hợp dữ liệu từ các cuộc khảo sát toàn cầu khác nhau.)","She needs to [collate] all the student reports before the meeting. (=Dịch: Cô ấy cần đối chiếu và sắp xếp tất cả các báo cáo của học sinh trước cuộc họp.)","Software tools make it much easier to [collate] research findings. (=Dịch: Các công cụ phần mềm giúp việc tổng hợp và đối chiếu các kết quả nghiên cứu trở nên dễ dàng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=collate&lang=en-GB&ipa=%2Fk%C9%99%CB%88le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=collate&lang=en-US&ipa=%2Fk%C9%99%CB%88le%C9%AAt%2F"},{"id":"lv_3_15","topic":"Urban Planning and Infrastructure Construction","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"ủy ban; tiền hoa hồng","defEn":"a formal group of people entrusted by a government to do a particular task; an amount of money paid for a sale","examples":["The government set up an independent [commission] to investigate the safety issue. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vấn đề an toàn.)","Sales agents earn a generous [commission] on every property they sell. (=Dịch: Các đại lý bán hàng kiếm được một khoản hoa hồng hậu hĩnh trên mỗi bất động sản mà họ bán được.)","The cultural [commission] approved funding for the new community art project. (=Dịch: Ủy ban văn hóa đã phê duyệt kinh phí cho dự án nghệ thuật cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_3_16","topic":"Urban Planning and Infrastructure Construction","word":"committee","pos":"(n)","ipa":"/kəˈmɪt.i/","defVi":"ủy ban, hội đồng","defEn":"a group of people chosen to represent a larger group or make decisions","examples":["The school formed a [committee] to organize the annual charity event. (=Dịch: Trường học đã thành lập một ủy ban để tổ chức sự kiện từ thiện thường niên.)","She was appointed as the head of the finance [committee]. (=Dịch: Cô ấy đã được bổ nhiệm làm người đứng đầu ủy ban tài chính.)","The government [committee] will submit its report next month. (=Dịch: Ủy ban của chính phủ sẽ đệ trình báo cáo vào tháng tới.)"],"ukAudio":"/ai_services/tts3/?q=committee&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=committee&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F"},{"id":"lv_3_17","topic":"Urban Planning and Infrastructure Construction","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"lời phàn nàn, sự khiếu nại","defEn":"a statement that something is unsatisfactory or unacceptable","examples":["The hotel manager received a formal [complaint] about the noisy air conditioner. (=Dịch: Quản lý khách sạn đã nhận được một lời khiếu nại chính thức về chiếc máy điều hòa gây ồn.)","She made a [complaint] to customer service regarding the late delivery. (=Dịch: Cô ấy đã gửi khiếu nại đến bộ phận chăm sóc khách hàng về việc giao hàng chậm trễ.)","The company took steps to resolve the [complaint] as quickly as possible. (=Dịch: Công ty đã thực hiện các biện pháp để giải quyết khiếu nại nhanh nhất có thể.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_3_18","topic":"Urban Planning and Infrastructure Construction","word":"concrete","pos":"(adj)","ipa":"/ˈkɑːn.kriːt/","defVi":"cụ thể, rõ ràng, xác thực","defEn":"based on facts or actual things, rather than thoughts or ideas","examples":["We need [concrete] evidence before we can make any formal accusation. (=Dịch: Chúng ta cần bằng chứng cụ thể trước khi có thể đưa ra bất kỳ lời cáo buộc chính thức nào.)","The manager asked the team for [concrete] proposals to improve sales. (=Dịch: Người quản lý đã yêu cầu toàn đội đưa ra những đề xuất cụ thể để cải thiện doanh số bán hàng.)","The research lacks [concrete] data to support its main hypothesis. (=Dịch: Nghiên cứu còn thiếu dữ liệu cụ thể để chứng minh cho giả thuyết chính của mình.)"],"ukAudio":"/ai_services/tts3/?q=concrete&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F","usAudio":"/ai_services/tts3/?q=concrete&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F"},{"id":"lv_3_19","topic":"Urban Planning and Infrastructure Construction","word":"congestion","pos":"(n)","ipa":"/kənˈdʒes.tʃən/","defVi":"sự tắc nghẽn, sự ùn tắc","defEn":"the state of being extremely crowded or blocked, especially with traffic","examples":["The new bypass road was built to reduce traffic [congestion] in the city center. (=Dịch: Tuyến đường tránh mới được xây dựng nhằm giảm ùn tắc giao thông ở trung tâm thành phố.)","Heavy [congestion] during rush hours often leads to long delays for commuters. (=Dịch: Tình trạng tắc nghẽn nghiêm trọng trong giờ cao điểm thường dẫn đến sự chậm trễ kéo dài cho người đi làm.)","Improving public transport networks is essential to alleviate urban road [congestion]. (=Dịch: Cải thiện mạng lưới giao thông công cộng là điều cần thiết để giảm bớt tình trạng ùn tắc giao thông đường bộ đô thị.)"],"ukAudio":"/ai_services/tts3/?q=congestion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%CA%92es.t%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congestion&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%CA%92es.t%CA%83%C9%99n%2F"},{"id":"lv_3_20","topic":"Urban Planning and Infrastructure Construction","word":"consultation","pos":"(n)","ipa":"/ˌkɑːn.səlˈteɪ.ʃən/","defVi":"sự hội đàm, sự tham vấn, cuộc tư vấn","defEn":"a meeting to discuss something, or the process of discussing something with someone to get advice","examples":["The doctor charges a high fee for a private [consultation]. (=Dịch: Bác sĩ thu phí cao cho một buổi tư vấn riêng.)","The decision was made after thorough [consultation] with local residents. (=Dịch: Quyết định được đưa ra sau khi tham vấn kỹ lưỡng với cư dân địa phương.)","We need to hold a [consultation] with legal experts before signing the contract. (=Dịch: Chúng tôi cần tiến hành tham vấn với các chuyên gia pháp lý trước khi ký hợp đồng.)"],"ukAudio":"/ai_services/tts3/?q=consultation&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90n.s%C9%99l%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consultation&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90n.s%C9%99l%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_21","topic":"Urban Planning and Infrastructure Construction","word":"convert","pos":"(v)","ipa":"/kənˈvɜrt/","defVi":"chuyển đổi, biến đổi","defEn":"to change something from one form, state, or use into another","examples":["The old warehouse was [convert]ed into modern residential apartments. (=Dịch: Nhà kho cũ đã được chuyển đổi thành các căn hộ dân cư hiện đại.)","Solar panels [convert] sunlight directly into usable electrical energy. (=Dịch: Các tấm pin mặt trời chuyển đổi trực tiếp ánh sáng mặt trời thành điện năng có thể sử dụng.)","They plan to [convert] the spare bedroom into a quiet study area. (=Dịch: Họ dự định cải tạo phòng ngủ phụ thành một khu vực học tập yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=convert&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9Crt%2F","usAudio":"/ai_services/tts3/?q=convert&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9Crt%2F"},{"id":"lv_3_22","topic":"Urban Planning and Infrastructure Construction","word":"councillor","pos":"(n)","ipa":"/ˈkaʊn.sə.lɚ/","defVi":"ủy viên hội đồng, nghị viên địa phương","defEn":"an elected member of a local government council","examples":["The local [councillor] promised to address the problem of traffic congestion. (=Dịch: Ủy viên hội đồng địa phương đã hứa sẽ giải quyết vấn đề ùn tắc giao thông.)","Residents met with their city [councillor] to voice concerns about the new development. (=Dịch: Các cư dân đã gặp ủy viên hội đồng thành phố của họ để bày tỏ mối lo ngại về dự án phát triển mới.)","She has served as a parish [councillor] for more than ten years. (=Dịch: Bà ấy đã phục vụ với tư cách là ủy viên hội đồng giáo xứ trong hơn mười năm.)"],"ukAudio":"/ai_services/tts3/?q=councillor&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.s%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=councillor&lang=en-US&ipa=%2F%CB%88ka%CA%8An.s%C9%99.l%C9%9A%2F"},{"id":"lv_3_23","topic":"Urban Planning and Infrastructure Construction","word":"cricket","pos":"(n)","ipa":"/ˈkrɪk.ɪt/","defVi":"môn bóng gậy (cricket)","defEn":"an open-air game played on grass with bats, a ball, and wickets by two teams of eleven players","examples":["He has been playing [cricket] for the local club since he was ten. (=Dịch: Anh ấy đã chơi môn cricket cho câu lạc bộ địa phương từ khi mười tuổi.)","The national team won the international [cricket] tournament. (=Dịch: Đội tuyển quốc gia đã giành chiến thắng tại giải đấu cricket quốc tế.)","Many people in England enjoy watching a match of [cricket] on weekends. (=Dịch: Nhiều người ở Anh thích xem một trận đấu cricket vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=cricket&lang=en-GB&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=cricket&lang=en-US&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F"},{"id":"lv_3_24","topic":"Urban Planning and Infrastructure Construction","word":"critic","pos":"(n)","ipa":"/ˈkrɪt̬.ɪk/","defVi":"nhà phê bình, người chỉ trích","defEn":"a person who expresses opinions or judgments about art, literature, or people's actions","examples":["The movie received rave reviews from almost every film [critic]. (=Dịch: Bộ phim đã nhận được nhiều lời khen ngợi nhiệt liệt từ hầu hết các nhà phê bình điện ảnh.)","He has always been an outspoken [critic] of the current political policy. (=Dịch: Ông ấy luôn là một người thẳng thắn chỉ trích chính sách chính trị hiện tại.)","The food [critic] wrote a detailed evaluation of the new restaurant. (=Dịch: Nhà phê bình ẩm thực đã viết một bài đánh giá chi tiết về nhà hàng mới.)"],"ukAudio":"/ai_services/tts3/?q=critic&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=critic&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AAk%2F"},{"id":"lv_3_25","topic":"Urban Planning and Infrastructure Construction","word":"croft","pos":"(n)","ipa":"/krɑːft/","defVi":"trang trại nhỏ (thường ở vùng nông thôn Scotland)","defEn":"a very small farm, especially one in Scotland, typically with a rented house and land","examples":["His grandparents lived on a remote [croft] in the Scottish Highlands. (=Dịch: Ông bà của anh ấy sống tại một trang trại nhỏ hẻo lánh ở vùng Cao nguyên Scotland.)","Traditional life on a [croft] involves raising a few sheep and growing vegetables. (=Dịch: Cuộc sống truyền thống tại một trang trại nhỏ bao gồm việc nuôi vài con cừu và trồng rau củ.)","The government provided grants to modernize the old [croft]. (=Dịch: Chính phủ đã cung cấp các khoản trợ cấp để hiện đại hóa trang trại nhỏ cũ kỹ.)"],"ukAudio":"/ai_services/tts3/?q=croft&lang=en-GB&ipa=%2Fkr%C9%91%CB%90ft%2F","usAudio":"/ai_services/tts3/?q=croft&lang=en-US&ipa=%2Fkr%C9%91%CB%90ft%2F"},{"id":"lv_3_26","topic":"Urban Planning and Infrastructure Construction","word":"curve","pos":"(n)","ipa":"/kɝːv/","defVi":"đường cong, khúc cua","defEn":"a line or surface that bends continuously without forming angles","examples":["Drivers must slow down before entering the sharp [curve] in the road. (=Dịch: Người lái xe phải giảm tốc độ trước khi đi vào khúc cua gấp trên đường.)","The modern building is famous for the sweeping [curve] of its glass roof. (=Dịch: Tòa nhà hiện đại này nổi tiếng với đường cong uốn lượn mềm mại của mái kính.)","The graph shows an upward [curve] in renewable energy production over the decade. (=Dịch: Biểu đồ cho thấy một đường cong đi lên về sản lượng năng lượng tái tạo trong suốt thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=curve&lang=en-GB&ipa=%2Fk%C9%9D%CB%90v%2F","usAudio":"/ai_services/tts3/?q=curve&lang=en-US&ipa=%2Fk%C9%9D%CB%90v%2F"},{"id":"lv_3_27","topic":"Urban Planning and Infrastructure Construction","word":"damaging","pos":"(adj)","ipa":"/ˈdæm.ɪ.dʒɪŋ/","defVi":"gây tổn hại, có hại, tai hại","defEn":"causing harm, injury, or impairment","examples":["Smoking cigarettes has a extremely [damaging] effect on your lungs. (=Dịch: Hút thuốc lá gây ra tác hại cực kỳ nghiêm trọng đối với phổi của bạn.)","The scandal had a very [damaging] impact on the politician's career. (=Dịch: Vụ bê bối đã gây ra ảnh hưởng vô cùng tai hại đến sự nghiệp của vị chính trị gia.)","Air pollution produces [damaging] consequences for the ecosystem. (=Dịch: Ô nhiễm không khí tạo ra những hậu quả gây hại cho hệ sinh thái.)"],"ukAudio":"/ai_services/tts3/?q=damaging&lang=en-GB&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=damaging&lang=en-US&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_3_28","topic":"Urban Planning and Infrastructure Construction","word":"decibel","pos":"(n)","ipa":"/ˈdes.ə.bəl/","defVi":"đề-xi-ben (đơn vị đo độ lớn âm thanh)","defEn":"a unit used to measure the intensity or loudness of sound","examples":["The sound of normal human conversation is usually around sixty [decibel]s. (=Dịch: Âm thanh của một cuộc trò chuyện bình thường của con người thường vào khoảng sáu mươi đề-xi-ben.)","City regulations prohibit construction noise exceeding eighty [decibel]s at night. (=Dịch: Các quy định của thành phố cấm tiếng ồn xây dựng vượt quá tám mươi đề-xi-ben vào ban đêm.)","Exposure to sounds over eighty-five [decibel]s for prolonged periods can cause hearing loss. (=Dịch: Việc tiếp xúc với âm thanh trên tám mươi lăm đề-xi-ben trong thời gian dài có thể gây suy giảm thính lực.)"],"ukAudio":"/ai_services/tts3/?q=decibel&lang=en-GB&ipa=%2F%CB%88des.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=decibel&lang=en-US&ipa=%2F%CB%88des.%C9%99.b%C9%99l%2F"},{"id":"lv_3_29","topic":"Urban Planning and Infrastructure Construction","word":"declare","pos":"(v)","ipa":"/dɪˈkler/","defVi":"tuyên bố, công bố, khai báo","defEn":"to announce something clearly, firmly, or officially","examples":["The government decided to [declare] a state of emergency. (=Dịch: Chính phủ đã quyết định ban bố tình trạng khẩn cấp.)","You must [declare] any taxable goods at the customs counter. (=Dịch: Bạn phải khai báo bất kỳ hàng hóa chịu thuế nào tại quầy hải quan.)","The referee will [declare] the official winner after the match. (=Dịch: Trọng tài sẽ tuyên bố người chiến thắng chính thức sau trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=declare&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kler%2F","usAudio":"/ai_services/tts3/?q=declare&lang=en-US&ipa=%2Fd%C9%AA%CB%88kler%2F"},{"id":"lv_3_30","topic":"Urban Planning and Infrastructure Construction","word":"discharge","pos":"(v)","ipa":"/dɪsˈtʃɑːrdʒ/","defVi":"xả ra, thải ra, phóng thích","defEn":"to release or send out a liquid, gas, or other substance","examples":["Factories should not [discharge] toxic chemicals into the river. (=Dịch: Các nhà máy không được xả hóa chất độc hại ra sông.)","The patient was well enough to be [discharge]d from the hospital today. (=Dịch: Bệnh nhân đã đủ khỏe để được xuất viện vào ngày hôm nay.)","The volcano continued to [discharge] huge clouds of ash and smoke. (=Dịch: Ngọn núi lửa tiếp tục phun ra những đám mây tro bụi và khói khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=discharge&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88t%CA%83%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=discharge&lang=en-US&ipa=%2Fd%C9%AAs%CB%88t%CA%83%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_3_31","topic":"Urban Planning and Infrastructure Construction","word":"dispose","pos":"(v)","ipa":"/dɪˈspoʊz/","defVi":"xử lý, vứt bỏ","defEn":"to get rid of something that is no longer wanted or needed","examples":["Factories must properly [dispose] of toxic waste to prevent river pollution. (=Dịch: Các nhà máy phải xử lý chất thải độc hại đúng cách để ngăn ngừa ô nhiễm sông ngòi.)","Please [dispose] of your litter in the bins provided. (=Dịch: Vui lòng bỏ rác của bạn vào các thùng rác được cung cấp sẵn.)","The company is looking for a safe way to [dispose] of old electronic equipment. (=Dịch: Công ty đang tìm kiếm một phương pháp an toàn để thải bỏ các thiết bị điện tử cũ.)"],"ukAudio":"/ai_services/tts3/?q=dispose&lang=en-GB&ipa=%2Fd%C9%AA%CB%88spo%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=dispose&lang=en-US&ipa=%2Fd%C9%AA%CB%88spo%CA%8Az%2F"},{"id":"lv_3_32","topic":"Urban Planning and Infrastructure Construction","word":"disuse","pos":"(n)","ipa":"/dɪsˈjuːs/","defVi":"sự không còn được sử dụng, tình trạng bỏ hoang/ngưng dùng","defEn":"the state of no longer being used","examples":["The old railway track has fallen into [disuse] over the past decade. (=Dịch: Tuyến đường sắt cũ đã bị bỏ hoang không còn sử dụng trong suốt một thập kỷ qua.)","Many traditional crafts are in danger of falling into [disuse]. (=Dịch: Nhiều nghề thủ công truyền thống đang đứng trước nguy cơ bị mai một.)","The factory machinery was sold after years of [disuse]. (=Dịch: Máy móc trong nhà máy đã được bán sau nhiều năm không sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=disuse&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88ju%CB%90s%2F","usAudio":"/ai_services/tts3/?q=disuse&lang=en-US&ipa=%2Fd%C9%AAs%CB%88ju%CB%90s%2F"},{"id":"lv_3_33","topic":"Urban Planning and Infrastructure Construction","word":"drainage","pos":"(n)","ipa":"/ˈdreɪ.nɪdʒ/","defVi":"hệ thống thoát nước, sự thoát nước","defEn":"the system or process by which water or other liquids are drained from a place","examples":["Poor [drainage] in the city center often leads to severe flooding during heavy rain. (=Dịch: Hệ thống thoát nước kém ở trung tâm thành phố thường dẫn đến ngập lụt nghiêm trọng khi trời mưa to.)","The farmer improved the [drainage] of his fields to prevent crop damage. (=Dịch: Người nông dân đã cải thiện hệ thống thoát nước cho các cánh đồng của mình để ngăn ngừa thiệt hại cho cây trồng.)","The local council invested millions of dollars in modernizing the town's [drainage] network. (=Dịch: Hội đồng địa phương đã đầu tư hàng triệu đô la vào việc hiện đại hóa mạng lưới thoát nước của thị trấn.)"],"ukAudio":"/ai_services/tts3/?q=drainage&lang=en-GB&ipa=%2F%CB%88dre%C9%AA.n%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=drainage&lang=en-US&ipa=%2F%CB%88dre%C9%AA.n%C9%AAd%CA%92%2F"},{"id":"lv_3_34","topic":"Urban Planning and Infrastructure Construction","word":"dweller","pos":"(n)","ipa":"/ˈdwel.ər/","defVi":"cư dân, người cư ngụ","defEn":"a person or animal that lives in a particular place","examples":["An urban [dweller] often experiences higher levels of noise and pollution than someone living in the countryside. (=Dịch: Một cư dân đô thị thường phải chịu mức độ tiếng ồn và ô nhiễm cao hơn so với người sống ở vùng nông thôn.)","The traditional cave [dweller]s adapted remarkably well to the harsh desert environment. (=Dịch: Những người sống trong hang động truyền thống đã thích nghi rất tốt với môi trường sa mạc khắc nghiệt.)","Local authorities are consulting city [dweller]s about the new green park project. (=Dịch: Chính quyền địa phương đang tham vấn ý kiến của cư dân thành phố về dự án công viên xanh mới.)"],"ukAudio":"/ai_services/tts3/?q=dweller&lang=en-GB&ipa=%2F%CB%88dwel.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=dweller&lang=en-US&ipa=%2F%CB%88dwel.%C9%99r%2F"},{"id":"lv_3_35","topic":"Urban Planning and Infrastructure Construction","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, tạo điều kiện, giúp có thể","defEn":"to make it possible for someone to do something or for something to happen","examples":["Modern technology will [enable] remote workers to collaborate more effectively across borders. (=Dịch: Công nghệ hiện đại sẽ cho phép những người làm việc từ xa cộng tác hiệu quả hơn xuyên biên giới.)","The scholarship helped [enable] her to pursue higher education abroad without financial stress. (=Dịch: Học bổng đã giúp cô có điều kiện theo học bậc đại học ở nước ngoài mà không phải chịu áp lực tài chính.)","Regular exercise and a balanced diet [enable] individuals to maintain high energy levels. (=Dịch: Tập thể dục thường xuyên và một chế độ ăn uống cân bằng giúp các cá nhân duy trì mức năng lượng cao.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_3_36","topic":"Urban Planning and Infrastructure Construction","word":"enlarge","pos":"(v)","ipa":"/ɪnˈlɑrdʒ/","defVi":"mở rộng, phóng to","defEn":"to make something bigger or to become bigger","examples":["The city council plans to [enlarge] the local playground. (=Dịch: Hội đồng thành phố có kế hoạch mở rộng sân chơi địa phương.)","Could you please [enlarge] this photograph for the exhibition? (=Dịch: Bạn có thể vui lòng phóng to bức ảnh này cho buổi triển lãm không?)","The company decided to [enlarge] its product range to attract more customers. (=Dịch: Công ty đã quyết định mở rộng danh mục sản phẩm để thu hút thêm nhiều khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=enlarge&lang=en-GB&ipa=%2F%C9%AAn%CB%88l%C9%91rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=enlarge&lang=en-US&ipa=%2F%C9%AAn%CB%88l%C9%91rd%CA%92%2F"},{"id":"lv_3_37","topic":"Urban Planning and Infrastructure Construction","word":"environmentally","pos":"(adv)","ipa":"/ɪnˌvaɪ.rənˈmen.t̬əl.i/","defVi":"về mặt môi trường","defEn":"in a way that relates to the natural world or the environment","examples":["The company is trying to produce more [environmentally] friendly packaging. (=Dịch: Công ty đang cố gắng sản xuất bao bì thân thiện hơn với môi trường.)","Using public transport is [environmentally] better than driving a personal car. (=Dịch: Sử dụng phương tiện giao thông công cộng tốt hơn cho môi trường so với việc lái xe ô tô cá nhân.)","We need to find [environmentally] sustainable ways to generate energy. (=Dịch: Chúng ta cần tìm ra những phương pháp tạo ra năng lượng bền vững về mặt môi trường.)"],"ukAudio":"/ai_services/tts3/?q=environmentally&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cva%C9%AA.r%C9%99n%CB%88men.t%CC%AC%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=environmentally&lang=en-US&ipa=%2F%C9%AAn%CB%8Cva%C9%AA.r%C9%99n%CB%88men.t%CC%AC%C9%99l.i%2F"},{"id":"lv_3_38","topic":"Urban Planning and Infrastructure Construction","word":"essentially","pos":"(adv)","ipa":"/ɪˈsen.ʃəl.i/","defVi":"về cơ bản, cốt yếu","defEn":"used when stating the most basic and important facts about something","examples":["The two proposals are [essentially] the same in terms of cost. (=Dịch: Hai đề xuất về cơ bản là giống nhau về mặt chi phí.)","What he said was [essentially] true, despite a few minor mistakes. (=Dịch: Những gì anh ấy nói về cơ bản là đúng, dù có một vài lỗi nhỏ.)","The internet is [essentially] a vast network connecting computers worldwide. (=Dịch: Internet về cơ bản là một mạng lưới rộng lớn kết nối các máy tính trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=essentially&lang=en-GB&ipa=%2F%C9%AA%CB%88sen.%CA%83%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=essentially&lang=en-US&ipa=%2F%C9%AA%CB%88sen.%CA%83%C9%99l.i%2F"},{"id":"lv_3_39","topic":"Urban Planning and Infrastructure Construction","word":"evaluation","pos":"(n)","ipa":"/ɪˌvæl.juˈeɪ.ʃən/","defVi":"sự đánh giá, sự thẩm định","defEn":"the process of judging or calculating the quality, importance, or value of something","examples":["The company conducts a performance [evaluation] for every employee once a year. (=Dịch: Công ty tiến hành đánh giá hiệu suất cho mỗi nhân viên một năm một lần.)","A careful [evaluation] of the risks is necessary before investing. (=Dịch: Việc đánh giá cẩn thận các rủi ro là cần thiết trước khi đầu tư.)","The teacher's final [evaluation] will determine whether students pass the course. (=Dịch: Đánh giá cuối cùng của giáo viên sẽ quyết định xem học sinh có vượt qua khóa học hay không.)"],"ukAudio":"/ai_services/tts3/?q=evaluation&lang=en-GB&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evaluation&lang=en-US&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_40","topic":"Urban Planning and Infrastructure Construction","word":"extend","pos":"(v)","ipa":"/ɪkˈstend/","defVi":"mở rộng, kéo dài","defEn":"to make something larger, longer, or to stretch out","examples":["The school agreed to [extend] the deadline for the final project. (=Dịch: Nhà trường đã đồng ý gia hạn thời hạn cho dự án cuối khóa.)","The railway line will soon [extend] to the neighboring town. (=Dịch: Tuyến đường sắt sẽ sớm được mở rộng đến thị trấn lân cận.)","They decided to [extend] their kitchen to create more dining space. (=Dịch: Họ quyết định mở rộng phòng bếp để có thêm không gian ăn uống.)"],"ukAudio":"/ai_services/tts3/?q=extend&lang=en-GB&ipa=%2F%C9%AAk%CB%88stend%2F","usAudio":"/ai_services/tts3/?q=extend&lang=en-US&ipa=%2F%C9%AAk%CB%88stend%2F"},{"id":"lv_3_41","topic":"Urban Planning and Infrastructure Construction","word":"faculty","pos":"(n)","ipa":"/ˈfæk.əl.ti/","defVi":"giảng viên (toàn thể cán bộ giảng dạy); khoa (đại học); khả năng","defEn":"all the teachers or academic staff in a university or college; an inherent mental or physical ability","examples":["She joined the university's law [faculty] as a senior lecturer. (=Dịch: Cô ấy đã gia nhập khoa luật của trường đại học với tư cách là giảng viên cao cấp.)","The [faculty] voted unanimously in favor of the new curriculum. (=Dịch: Toàn thể giảng viên đã bỏ phiếu nhất trí ủng hộ chương trình giảng dạy mới.)","Even in his nineties, he maintained full use of his mental [faculty] skills. (=Dịch: Ngay cả khi đã ngoài chín mươi tuổi, ông ấy vẫn duy trì trọn vẹn năng lực trí tuệ của mình.)"],"ukAudio":"/ai_services/tts3/?q=faculty&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.%C9%99l.ti%2F","usAudio":"/ai_services/tts3/?q=faculty&lang=en-US&ipa=%2F%CB%88f%C3%A6k.%C9%99l.ti%2F"},{"id":"lv_3_42","topic":"Urban Planning and Infrastructure Construction","word":"fare","pos":"(n)","ipa":"/fer/","defVi":"tiền vé, tiền cước (xe buýt, taxi, máy bay)","defEn":"the money that you pay to travel by bus, plane, taxi, etc.","examples":["Bus [fare] has increased significantly over the past two years. (=Dịch: Giá vé xe buýt đã tăng đáng kể trong hai năm qua.)","Children under five can travel at half [fare]. (=Dịch: Trẻ em dưới năm tuổi có thể đi lại với giá nửa vé.)","She did not have enough cash to pay the taxi [fare]. (=Dịch: Cô ấy không có đủ tiền mặt để trả tiền cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ffer%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ffer%2F"},{"id":"lv_3_43","topic":"Urban Planning and Infrastructure Construction","word":"flooding","pos":"(n)","ipa":"/ˈflʌd.ɪŋ/","defVi":"tình trạng ngập lụt, lũ lụt","defEn":"an overflow of a large amount of water beyond its normal limits","examples":["Heavy rainfall caused severe [flooding] across the low-lying parts of town. (=Dịch: Mưa lớn đã gây ra ngập lụt nghiêm trọng trên khắp các khu vực trũng thấp của thị trấn.)","The new drainage system was designed to reduce the risk of flash [flooding]. (=Dịch: Hệ thống thoát nước mới được thiết kế để giảm thiểu nguy cơ lũ quét.)","Many homes suffered significant structural damage due to seasonal [flooding]. (=Dịch: Nhiều ngôi nhà đã phải chịu thiệt hại nghiêm trọng về cấu trúc do tình trạng ngập lụt theo mùa.)"],"ukAudio":"/ai_services/tts3/?q=flooding&lang=en-GB&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=flooding&lang=en-US&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F"},{"id":"lv_3_44","topic":"Urban Planning and Infrastructure Construction","word":"fountain","pos":"(n)","ipa":"/ˈfaʊn.tən/","defVi":"đài phun nước","defEn":"a structure that sends water up into the air, often used as a decoration in a park or square","examples":["Tourists often gather around the ancient stone [fountain] in the central square to take photos. (=Dịch: Khách du lịch thường tụ tập quanh đài phun nước bằng đá cổ kính ở quảng trường trung tâm để chụp ảnh.)","The hotel lobby features an impressive water [fountain] that creates a relaxing atmosphere. (=Dịch: Sảnh khách sạn có một đài phun nước ấn tượng tạo nên một bầu không khí thư thái.)","Children enjoyed tossing coins into the park's [fountain] to make wishes. (=Dịch: Trẻ em rất thích ném những đồng xu vào đài phun nước của công viên để ước nguyện.)"],"ukAudio":"/ai_services/tts3/?q=fountain&lang=en-GB&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fountain&lang=en-US&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F"},{"id":"lv_3_45","topic":"Urban Planning and Infrastructure Construction","word":"foyer","pos":"(n)","ipa":"/ˈfɔɪ.eɪ/","defVi":"tiền sảnh, sảnh chờ","defEn":"a large open area just inside the entrance of a public building such as a theatre or hotel","examples":["Guests gathered in the hotel [foyer] before the conference began. (=Dịch: Khách mời đã tập trung tại tiền sảnh khách sạn trước khi hội nghị bắt đầu.)","We arranged to meet our friends in the theatre [foyer]. (=Dịch: Chúng tôi hẹn gặp bạn bè ở tiền sảnh nhà hát.)","The modern building features a spacious glass [foyer]. (=Dịch: Tòa nhà hiện đại có một tiền sảnh bằng kính rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=foyer&lang=en-GB&ipa=%2F%CB%88f%C9%94%C9%AA.e%C9%AA%2F","usAudio":"/ai_services/tts3/?q=foyer&lang=en-US&ipa=%2F%CB%88f%C9%94%C9%AA.e%C9%AA%2F"},{"id":"lv_3_46","topic":"Urban Planning and Infrastructure Construction","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ tiền tệ, nguồn tài chính","defEn":"an amount of money collected or saved for a particular purpose","examples":["The school established a special [fund] to help low-income students. (=Dịch: Nhà trường đã thành lập một quỹ đặc biệt để giúp đỡ các học sinh có thu nhập thấp.)","We do not have enough [funds] to complete the construction project. (=Dịch: Chúng tôi không có đủ kinh phí để hoàn thành dự án xây dựng.)","He decided to invest his savings into an index [fund]. (=Dịch: Anh ấy quyết định đầu tư tiền tiết kiệm của mình vào một quỹ chỉ số.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_3_47","topic":"Urban Planning and Infrastructure Construction","word":"gps","pos":"(n)","ipa":"/ˌdʒiː.piːˈes/","defVi":"hệ thống định vị toàn cầu (GPS)","defEn":"a system that uses radio signals from satellites to show the exact position of something on Earth","examples":["Modern smartphones come equipped with built-in [GPS] technology. (=Dịch: Điện thoại thông minh hiện đại được trang bị công nghệ GPS tích hợp.)","We used our car's [GPS] to find the quickest route to the hotel. (=Dịch: Chúng tôi đã sử dụng định vị GPS trên xe ô tô để tìm tuyến đường nhanh nhất đến khách sạn.)","The delivery driver lost his way because the [GPS] signal was weak in the mountains. (=Dịch: Người tài xế giao hàng đã bị lạc đường vì tín hiệu GPS yếu ở vùng núi.)"],"ukAudio":"/ai_services/tts3/?q=gps&lang=en-GB&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88es%2F","usAudio":"/ai_services/tts3/?q=gps&lang=en-US&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88es%2F"},{"id":"lv_3_48","topic":"Urban Planning and Infrastructure Construction","word":"grand","pos":"(adj)","ipa":"/ɡrænd/","defVi":"hoành tráng, uy nghi, tráng lệ","defEn":"impressive and large or important","examples":["They held the wedding reception in a [grand] ballroom. (=Dịch: Họ đã tổ chức tiệc cưới trong một phòng khiêu vũ nguy nga tráng lệ.)","The architect unveiled a [grand] plan for the city's new waterfront. (=Dịch: Kiến trúc sư đã công bố một kế hoạch quy mô lớn cho khu bờ sông mới của thành phố.)","She had a [grand] view of the mountains from her hotel balcony. (=Dịch: Cô ấy có một tầm nhìn tuyệt đẹp hướng ra những ngọn núi từ ban công khách sạn của mình.)"],"ukAudio":"/ai_services/tts3/?q=grand&lang=en-GB&ipa=%2F%C9%A1r%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=grand&lang=en-US&ipa=%2F%C9%A1r%C3%A6nd%2F"},{"id":"lv_3_49","topic":"Urban Planning and Infrastructure Construction","word":"grateful","pos":"(adj)","ipa":"/ˈɡreɪt.fəl/","defVi":"biết ơn, cảm kích","defEn":"feeling or showing appreciation for kindness or help received","examples":["I am deeply [grateful] for all the support you have given me. (=Dịch: Tôi vô cùng biết ơn tất cả sự hỗ trợ mà bạn đã dành cho tôi.)","She was [grateful] that everyone arrived safely after the storm. (=Dịch: Cô ấy rất biết ơn vì mọi người đều đến nơi an toàn sau cơn bão.)","He sent a [grateful] letter of thanks to the rescue team. (=Dịch: Anh ấy đã gửi một lá thư tri ân đến đội cứu hộ.)"],"ukAudio":"/ai_services/tts3/?q=grateful&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=grateful&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F"},{"id":"lv_3_50","topic":"Urban Planning and Infrastructure Construction","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay, tờ rơi tài liệu","defEn":"a printed piece of paper containing information, given free to people attending a class, meeting, or event","examples":["The lecturer distributed a two-page [handout] at the beginning of the seminar. (=Dịch: Giảng viên đã phát một tài liệu dài hai trang vào đầu buổi hội thảo.)","Please refer to the [handout] for detailed instructions on the assignment. (=Dịch: Vui lòng tham khảo tài liệu phát tay để biết hướng dẫn chi tiết về bài tập.)","She made copies of the presentation slides to use as [handouts] for the audience. (=Dịch: Cô ấy đã in các slide thuyết trình để làm tài liệu phát cho người tham dự.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_3_51","topic":"Urban Planning and Infrastructure Construction","word":"highway","pos":"(n)","ipa":"/ˈhaɪ.weɪ/","defVi":"xa lộ, đường cao tốc","defEn":"a main public road that connects major towns or cities","examples":["The government is building a new [highway] to reduce travel time between the two major cities. (=Dịch: Chính phủ đang xây dựng một đường cao tốc mới nhằm giảm thời gian di chuyển giữa hai thành phố lớn.)","Heavy traffic was reported on the [highway] due to a minor collision this morning. (=Dịch: Tình trạng giao thông đông đúc đã được ghi nhận trên đường cao tốc do một vụ va chạm nhỏ vào sáng nay.)","Speed limits are strictly enforced along this section of the [highway]. (=Dịch: Giới hạn tốc độ được thực thi nghiêm ngặt dọc theo đoạn đường cao tốc này.)"],"ukAudio":"/ai_services/tts3/?q=highway&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=highway&lang=en-US&ipa=%2F%CB%88ha%C9%AA.we%C9%AA%2F"},{"id":"lv_3_52","topic":"Urban Planning and Infrastructure Construction","word":"housing","pos":"(n)","ipa":"/ˈhaʊ.zɪŋ/","defVi":"nhà ở, nơi cư trú","defEn":"buildings or structures in which people live","examples":["The government is investing heavily in affordable [housing] for low-income families. (=Dịch: Chính phủ đang đầu tư mạnh vào nhà ở vừa túi tiền cho các gia đình có thu nhập thấp.)","A serious shortage of [housing] has driven up rent prices across the capital. (=Dịch: Tình trạng thiếu hụt nhà ở nghiêm trọng đã đẩy giá thuê nhà lên cao trên khắp thủ đô.)","The university provides student [housing] near the main campus. (=Dịch: Trường đại học cung cấp chỗ ở cho sinh viên gần khuôn viên chính.)"],"ukAudio":"/ai_services/tts3/?q=housing&lang=en-GB&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=housing&lang=en-US&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F"},{"id":"lv_3_53","topic":"Urban Planning and Infrastructure Construction","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"cuộc tìm kiếm, sự lùng sục","defEn":"an organized search or pursuit for something or someone","examples":["The police launched an intensive [hunt] for the missing artifacts. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm gắt gao các cổ vật bị mất tích.)","Finding affordable housing has become a difficult [hunt] for young graduates. (=Dịch: Tìm kiếm nhà ở giá cả phải chăng đã trở thành một cuộc săn lùng khó khăn đối với những sinh viên mới tốt nghiệp.)","The company is currently on the [hunt] for a creative marketing manager. (=Dịch: Công ty hiện đang ráo riết tìm kiếm một trưởng phòng tiếp thị sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_3_54","topic":"Urban Planning and Infrastructure Construction","word":"impression","pos":"(n)","ipa":"/ɪmˈpreʃ.ən/","defVi":"ấn tượng, cảm giác","defEn":"an idea, feeling, or opinion about someone or something formed without much thought or on little evidence","examples":["Dressing professionally helps you make a positive first [impression] at an interview. (=Dịch: Ăn mặc chuyên nghiệp giúp bạn tạo được ấn tượng đầu tiên tích cực tại buổi phỏng vấn.)","Her performance left a lasting [impression] on the judges. (=Dịch: Màn trình diễn của cô ấy đã để lại ấn tượng sâu đậm trong lòng ban giám khảo.)","I got the [impression] that he was not really interested in the project. (=Dịch: Tôi có cảm tưởng rằng anh ấy không thực sự hứng thú với dự án.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pre%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pre%CA%83.%C9%99n%2F"},{"id":"lv_3_55","topic":"Urban Planning and Infrastructure Construction","word":"inhabitant","pos":"(n)","ipa":"/ɪnˈhæb.ə.tənt/","defVi":"cư dân, người cư ngụ","defEn":"a person or animal that lives in a particular place","examples":["The small island has fewer than five thousand [inhabitants]. (=Dịch: Hòn đảo nhỏ này có chưa đến năm nghìn cư dân.)","Local [inhabitants] expressed serious concerns about the new highway project. (=Dịch: Cư dân địa phương đã bày tỏ những mối quan ngại sâu sắc về dự án đường cao tốc mới.)","The ancient cave once provided shelter to prehistoric [inhabitants]. (=Dịch: Hang động cổ xưa từng là nơi trú ẩn của những cư dân thời tiền sử.)"],"ukAudio":"/ai_services/tts3/?q=inhabitant&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=inhabitant&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F"},{"id":"lv_3_56","topic":"Urban Planning and Infrastructure Construction","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, sâu trong đất liền","defEn":"situated in the interior of a country or region, rather than on the coast","examples":["The storm weakened as it moved toward [inland] areas. (=Dịch: Cơn bão đã suy yếu khi di chuyển vào các khu vực sâu trong đất liền.)","They prefer living in [inland] towns rather than crowded coastal cities. (=Dịch: Họ thích sống ở các thị trấn trong đất liền hơn là các thành phố ven biển đông đúc.)","The government is investing heavily in [inland] water transport. (=Dịch: Chính phủ đang đầu tư mạnh mẽ vào giao thông đường thủy nội địa.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_3_57","topic":"Urban Planning and Infrastructure Construction","word":"instal","pos":"(v)","ipa":"/ɪnˈstɔl/","defVi":"lắp đặt, cài đặt","defEn":"to put equipment or software in place so that it is ready for use","examples":["Technicians will [instal] a modern air conditioning unit tomorrow. (=Dịch: Các kỹ thuật viên sẽ lắp đặt một dàn máy điều hòa hiện đại vào ngày mai.)","The local council plans to [instal] more surveillance cameras to enhance public safety. (=Dịch: Hội đồng địa phương dự định lắp đặt thêm các camera giám sát để nâng cao an toàn công cộng.)","You need to [instal] the latest security patch to protect your computer from malware. (=Dịch: Bạn cần cài đặt bản vá bảo mật mới nhất để bảo vệ máy tính khỏi phần mềm độc hại.)"],"ukAudio":"/ai_services/tts3/?q=instal&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%94l%2F","usAudio":"/ai_services/tts3/?q=instal&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%94l%2F"},{"id":"lv_3_58","topic":"Urban Planning and Infrastructure Construction","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba, ngã tư, chỗ giao nhau","defEn":"a place where things, especially roads or railways, meet and cross","examples":["Turn left when you reach the next major highway [junction]. (=Dịch: Hãy rẽ trái khi bạn đến nút giao đường cao tốc lớn tiếp theo.)","Heavy traffic frequently causes delays at this busy road [junction]. (=Dịch: Giao thông đông đúc thường xuyên gây ra tình trạng ùn tắc tại nút giao thông đông đúc này.)","The town developed rapidly around a vital railway [junction]. (=Dịch: Thị trấn đã phát triển nhanh chóng xung quanh một nút giao đường sắt trọng yếu.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_3_59","topic":"Urban Planning and Infrastructure Construction","word":"lane","pos":"(n)","ipa":"/leɪn/","defVi":"làn đường, con hẻm, đường nhỏ","defEn":"a narrow road in the countryside, or a marked strip of road for a single line of vehicles","examples":["The local government created a dedicated bus [lane] to reduce traffic congestion. (=Dịch: Chính quyền địa phương đã tạo một làn đường dành riêng cho xe buýt để giảm ùn tắc giao thông.)","We walked down a quiet country [lane] surrounded by green trees. (=Dịch: Chúng tôi đi dạo trên một con đường quê yên tĩnh rợp bóng cây xanh.)","Stay in your [lane] when driving through the highway tunnel. (=Dịch: Hãy đi đúng làn đường của bạn khi lái xe qua hầm đường cao tốc.)"],"ukAudio":"/ai_services/tts3/?q=lane&lang=en-GB&ipa=%2Fle%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=lane&lang=en-US&ipa=%2Fle%C9%AAn%2F"},{"id":"lv_3_60","topic":"Urban Planning and Infrastructure Construction","word":"layout","pos":"(n)","ipa":"/ˈleɪ.aʊt/","defVi":"bố cục, cách trình bày, sơ đồ mặt bằng","defEn":"the way in which the parts of something are arranged or designed","examples":["The designer improved the page [layout] to make the article easier to read. (=Dịch: Nhà thiết kế đã cải thiện bố cục trang để giúp bài viết dễ đọc hơn.)","We are planning to change the [layout] of our office to create more open space. (=Dịch: Chúng tôi đang lên kế hoạch thay đổi cách bố trí văn phòng để tạo ra nhiều không gian mở hơn.)","The map shows the general [layout] of the university campus. (=Dịch: Bản đồ hiển thị bố cục chung của khuôn viên trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=layout&lang=en-GB&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=layout&lang=en-US&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F"},{"id":"lv_3_61","topic":"Urban Planning and Infrastructure Construction","word":"magnificent","pos":"(adj)","ipa":"/mæɡˈnɪf.ə.snt/","defVi":"tráng lệ, lộng lẫy, nguy nga","defEn":"extremely beautiful, elaborate, or impressive","examples":["The view from the top of the mountain was [magnificent]. (=Dịch: Khung cảnh nhìn từ đỉnh núi thật tráng lệ.)","She wore a [magnificent] dress to the annual gala. (=Dịch: Cô ấy đã mặc một chiếc váy lộng lẫy đến buổi dạ tiệc thường niên.)","The ancient palace is famous for its [magnificent] architecture. (=Dịch: Cung điện cổ kính này nổi tiếng với kiến trúc tráng lệ.)"],"ukAudio":"/ai_services/tts3/?q=magnificent&lang=en-GB&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.snt%2F","usAudio":"/ai_services/tts3/?q=magnificent&lang=en-US&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.snt%2F"},{"id":"lv_3_62","topic":"Urban Planning and Infrastructure Construction","word":"minority","pos":"(n)","ipa":"/maɪˈnɔːr.ə.t̬i/","defVi":"thiểu số, phần ít; dân tộc thiểu số","defEn":"a smaller part of a group, especially a number that is less than half of the whole","examples":["Only a small [minority] of students disagreed with the new policy. (=Dịch: Chỉ một thiểu số nhỏ học sinh không đồng ý với chính sách mới.)","The government introduced special programs to support ethnic [minority] groups. (=Dịch: Chính phủ đã đưa ra các chương trình đặc biệt để hỗ trợ các nhóm dân tộc thiểu số.)","His opinion was held by only a [minority] in the committee. (=Dịch: Ý kiến của ông ấy chỉ được một số ít người trong ủy ban tán thành.)"],"ukAudio":"/ai_services/tts3/?q=minority&lang=en-GB&ipa=%2Fma%C9%AA%CB%88n%C9%94%CB%90r.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=minority&lang=en-US&ipa=%2Fma%C9%AA%CB%88n%C9%94%CB%90r.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_63","topic":"Urban Planning and Infrastructure Construction","word":"minster","pos":"(n)","ipa":"/ˈmɪn.stɚ/","defVi":"nhà thờ lớn, tu viện giáo đường","defEn":"a large or important church, often historically attached to a monastery","examples":["York [Minster] is renowned for its magnificent stained glass windows and Gothic architecture. (=Dịch: Nhà thờ lớn York Minster nổi tiếng với những ô cửa kính màu tuyệt mỹ và kiến trúc Gothic.)","Thousands of worshippers gathered at the historic [minster] for the special holiday service. (=Dịch: Hàng ngàn tín đồ đã tập trung tại nhà thờ lớn lịch sử để tham dự buổi lễ đặc biệt nhân dịp ngày lễ.)","The ancient stone walls of the [minster] have stood for more than eight centuries. (=Dịch: Những bức tường đá cổ kính của nhà thờ lớn đã đứng vững qua hơn tám thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=minster&lang=en-GB&ipa=%2F%CB%88m%C9%AAn.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=minster&lang=en-US&ipa=%2F%CB%88m%C9%AAn.st%C9%9A%2F"},{"id":"lv_3_64","topic":"Urban Planning and Infrastructure Construction","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tɚ.i/","defVi":"điều bí ẩn, sự huyền bí","defEn":"something that is difficult or impossible to understand or explain","examples":["The exact origin of the ancient monument remains a [mystery]. (=Dịch: Nguồn gốc chính xác của tượng đài cổ xưa này vẫn còn là một điều bí ẩn.)","Detectives are trying to solve the [mystery] behind the missing jewels. (=Dịch: Các thám tử đang cố gắng giải mã bí ẩn đằng sau số trang sức bị mất tích.)","She loves reading [mystery] novels in her spare time. (=Dịch: Cô ấy rất thích đọc tiểu thuyết trinh thám ly kỳ vào thời gian rảnh rỗi.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F"},{"id":"lv_3_65","topic":"Urban Planning and Infrastructure Construction","word":"neighbouring","pos":"(adj)","ipa":"/ˈneɪ.bər.ɪŋ/","defVi":"lân cận, láng giềng","defEn":"located near or next to something","examples":["Many students commute from [neighbouring] towns to attend the university. (=Dịch: Nhiều sinh viên đi lại từ các thị trấn lân cận để theo học tại trường đại học.)","Smoke from the wildfire spread across [neighbouring] countries. (=Dịch: Khói từ trận cháy rừng đã lan sang các quốc gia láng giềng.)","We visited a [neighbouring] village during our trip to the countryside. (=Dịch: Chúng tôi đã đến thăm một ngôi làng lân cận trong chuyến đi về vùng nông thôn.)"],"ukAudio":"/ai_services/tts3/?q=neighbouring&lang=en-GB&ipa=%2F%CB%88ne%C9%AA.b%C9%99r.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=neighbouring&lang=en-US&ipa=%2F%CB%88ne%C9%AA.b%C9%99r.%C9%AA%C5%8B%2F"},{"id":"lv_3_66","topic":"Urban Planning and Infrastructure Construction","word":"opt","pos":"(v)","ipa":"/ɑːpt/","defVi":"lựa chọn, quyết định chọn","defEn":"to make a choice or decision from a range of possibilities","examples":["Many young professionals [opt] to rent apartments rather than buy houses. (=Dịch: Nhiều người trẻ có chuyên môn chọn thuê căn hộ thay vì mua nhà.)","She decided to [opt] for an online course due to her busy schedule. (=Dịch: Cô ấy quyết định chọn một khóa học trực tuyến do lịch trình bận rộn.)","Customers can [opt] out of receiving promotional emails at any time. (=Dịch: Khách hàng có thể từ chối nhận email quảng cáo bất cứ lúc nào.)"],"ukAudio":"/ai_services/tts3/?q=opt&lang=en-GB&ipa=%2F%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=opt&lang=en-US&ipa=%2F%C9%91%CB%90pt%2F"},{"id":"lv_3_67","topic":"Urban Planning and Infrastructure Construction","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians playing different instruments together, usually led by a conductor","examples":["The symphony [orchestra] delivered a mesmerizing performance of Beethoven's Ninth Symphony. (=Dịch: Dàn nhạc giao hưởng đã mang đến một màn trình diễn đầy mê hoặc bản Giao hưởng số 9 của Beethoven.)","She has been playing the violin in a youth [orchestra] since she was ten years old. (=Dịch: Cô ấy đã chơi vĩ cầm trong một dàn nhạc trẻ từ khi mới mười tuổi.)","The conductor guided the [orchestra] through the complex musical passages with remarkable precision. (=Dịch: Nhạc trưởng đã dẫn dắt dàn nhạc vượt qua các đoạn nhạc phức tạp với độ chính xác đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_3_68","topic":"Urban Planning and Infrastructure Construction","word":"outskirts","pos":"(n)","ipa":"/ˈaʊt.skɜːrts/","defVi":"vùng ngoại ô, rìa thành phố","defEn":"the outer parts of a town or city, furthest from the center","examples":["They bought a quiet house on the [outskirts] of the city. (=Dịch: Họ đã mua một ngôi nhà yên tĩnh ở ngoại ô thành phố.)","A new shopping mall is being built on the [outskirts] of town. (=Dịch: Một trung tâm mua sắm mới đang được xây dựng ở vùng ven thị trấn.)","Commuting from the [outskirts] to downtown takes about forty minutes by train. (=Dịch: Đi lại từ vùng ngoại ô vào trung tâm thành phố mất khoảng bốn mươi phút bằng tàu hỏa.)"],"ukAudio":"/ai_services/tts3/?q=outskirts&lang=en-GB&ipa=%2F%CB%88a%CA%8At.sk%C9%9C%CB%90rts%2F","usAudio":"/ai_services/tts3/?q=outskirts&lang=en-US&ipa=%2F%CB%88a%CA%8At.sk%C9%9C%CB%90rts%2F"},{"id":"lv_3_69","topic":"Urban Planning and Infrastructure Construction","word":"overhead","pos":"(adj)","ipa":"/ˌoʊ.vɚˈhed/","defVi":"ở trên cao, trên đầu","defEn":"located, operating, or passing above one's head or high above the ground","examples":["Passengers were requested to stow their carry-on bags in the [overhead] compartments. (=Dịch: Hành khách được yêu cầu cất hành lý xách tay vào các ngăn để đồ phía trên đầu.)","Strong winds caused damage to [overhead] power lines, leaving parts of the neighborhood in darkness. (=Dịch: Gió mạnh đã gây hư hại cho các đường dây điện trên cao, khiến nhiều khu vực trong khu dân cư chìm trong bóng tối.)","The city plans to construct an [overhead] railway to alleviate ground-level traffic congestion. (=Dịch: Thành phố lên kế hoạch xây dựng một tuyến đường sắt trên cao nhằm giảm bớt tình trạng ùn tắc giao thông mặt đất.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%9A%CB%88hed%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%9A%CB%88hed%2F"},{"id":"lv_3_70","topic":"Urban Planning and Infrastructure Construction","word":"pad","pos":"(n)","ipa":"/pæd/","defVi":"miếng đệm, tấm lót","defEn":"a piece of soft or thick material used to protect something or give comfort","examples":["He wore a knee [pad] to prevent injuries while skateboarding. (=Dịch: Cậu ấy đã đeo miếng đệm bảo vệ đầu gối để tránh bị thương khi trượt ván.)","She wrote down the phone number on a small memo [pad]. (=Dịch: Cô ấy đã ghi số điện thoại vào một cuốn sổ ghi chú nhỏ.)","Place a protective [pad] under the hot pot to protect the table. (=Dịch: Hãy đặt một miếng lót bên dưới nồi nóng để bảo vệ mặt bàn.)"],"ukAudio":"/ai_services/tts3/?q=pad&lang=en-GB&ipa=%2Fp%C3%A6d%2F","usAudio":"/ai_services/tts3/?q=pad&lang=en-US&ipa=%2Fp%C3%A6d%2F"},{"id":"lv_3_71","topic":"Urban Planning and Infrastructure Construction","word":"palm","pos":"(n)","ipa":"/pɑːm/","defVi":"cây cọ, cây dừa","defEn":"a tall tropical tree with large leaves at the top and no branches","examples":["We rested under the shade of a tall [palm] tree. (=Dịch: Chúng tôi nghỉ ngơi dưới bóng râm của một cây cọ cao lớn.)","The tropical island is lined with beautiful coconut [palm] trees. (=Dịch: Hòn đảo nhiệt đới rợp bóng những hàng dừa tuyệt đẹp.)","She collected fallen leaves from the [palm] to make a roof. (=Dịch: Cô ấy nhặt những chiếc lá cọ rụng để lợp mái nhà.)"],"ukAudio":"/ai_services/tts3/?q=palm&lang=en-GB&ipa=%2Fp%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=palm&lang=en-US&ipa=%2Fp%C9%91%CB%90m%2F"},{"id":"lv_3_72","topic":"Urban Planning and Infrastructure Construction","word":"panel","pos":"(n)","ipa":"/ˈpæn.əl/","defVi":"ban chuyên gia, hội đồng giám khảo / bảng điều khiển","defEn":"a small group of people chosen to give advice, make decisions, or discuss something","examples":["A [panel] of experts was invited to discuss the impact of climate change. (=Dịch: Một hội đồng chuyên gia đã được mời để thảo luận về tác động của biến đổi khí hậu.)","The interview [panel] asked several challenging questions. (=Dịch: Hội đồng phỏng vấn đã đặt ra một số câu hỏi đầy thử thách.)","He pressed a red button on the control [panel] to stop the machine. (=Dịch: Anh ấy đã nhấn một nút màu đỏ trên bảng điều khiển để dừng máy.)"],"ukAudio":"/ai_services/tts3/?q=panel&lang=en-GB&ipa=%2F%CB%88p%C3%A6n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=panel&lang=en-US&ipa=%2F%CB%88p%C3%A6n.%C9%99l%2F"},{"id":"lv_3_73","topic":"Urban Planning and Infrastructure Construction","word":"parcel","pos":"(n)","ipa":"/ˈpɑːr.səl/","defVi":"bưu kiện, gói hàng","defEn":"an object or collection of objects wrapped in paper, especially so that it can be sent by post","examples":["The delivery driver left a large [parcel] at the front door. (=Dịch: Người giao hàng đã để lại một bưu kiện lớn ở cửa trước.)","She went to the post office to collect an international [parcel]. (=Dịch: Cô ấy đã đến bưu điện để nhận một bưu kiện quốc tế.)","Make sure you wrap the [parcel] securely before sending it. (=Dịch: Hãy chắc chắn rằng bạn gói bưu kiện cẩn thận trước khi gửi.)"],"ukAudio":"/ai_services/tts3/?q=parcel&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=parcel&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.s%C9%99l%2F"},{"id":"lv_3_74","topic":"Urban Planning and Infrastructure Construction","word":"pavement","pos":"(n)","ipa":"/ˈpeɪv.mənt/","defVi":"vỉa hè, lề đường đi bộ","defEn":"a paved path for pedestrians at the side of a road; a sidewalk","examples":["Pedestrians should walk on the [pavement] to stay safe from traffic. (=Dịch: Người đi bộ nên đi trên vỉa hè để giữ an toàn khỏi các phương tiện giao thông.)","The cafe placed several small tables and chairs outside on the [pavement]. (=Dịch: Quán cà phê đã đặt vài bộ bàn ghế nhỏ bên ngoài trên vỉa hè.)","He tripped over an uneven section of the [pavement] and dropped his keys. (=Dịch: Anh ấy vấp phải một đoạn vỉa hè không bằng phẳng và làm rơi chìa khóa.)"],"ukAudio":"/ai_services/tts3/?q=pavement&lang=en-GB&ipa=%2F%CB%88pe%C9%AAv.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=pavement&lang=en-US&ipa=%2F%CB%88pe%C9%AAv.m%C9%99nt%2F"},{"id":"lv_3_75","topic":"Urban Planning and Infrastructure Construction","word":"pedestrian","pos":"(n)","ipa":"/pəˈdɛs.tri.ən/","defVi":"người đi bộ","defEn":"a person who is walking rather than traveling in a vehicle","examples":["Drivers must slow down and yield to any [pedestrian] at the crossing. (=Dịch: Người lái xe phải giảm tốc độ và nhường đường cho bất kỳ người đi bộ nào tại vạch sang đường.)","The city center has been turned into a safe [pedestrian] zone. (=Dịch: Trung tâm thành phố đã được chuyển đổi thành khu phố đi bộ an toàn.)","A [pedestrian] was injured in the traffic accident yesterday. (=Dịch: Một người đi bộ đã bị thương trong vụ tai nạn giao thông ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=pedestrian&lang=en-GB&ipa=%2Fp%C9%99%CB%88d%C9%9Bs.tri.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=pedestrian&lang=en-US&ipa=%2Fp%C9%99%CB%88d%C9%9Bs.tri.%C9%99n%2F"},{"id":"lv_3_76","topic":"Urban Planning and Infrastructure Construction","word":"periodical","pos":"(n)","ipa":"/ˌpɪr.iˈɑː.dɪ.kəl/","defVi":"tạp chí xuất bản định kỳ","defEn":"a magazine or journal that is published at regular intervals, such as weekly or monthly","examples":["The university library subscribes to a wide range of academic [periodicals]. (=Dịch: Thư viện trường đại học đặt mua dài hạn rất nhiều ấn phẩm định kỳ học thuật.)","She found an insightful article about climate change in a scientific [periodical]. (=Dịch: Cô ấy đã tìm thấy một bài viết sâu sắc về biến đổi khí hậu trên một ấn phẩm khoa học định kỳ.)","His research was cited in several leading medical [periodicals]. (=Dịch: Nghiên cứu của ông đã được trích dẫn trên một số tập san y khoa định kỳ hàng đầu.)"],"ukAudio":"/ai_services/tts3/?q=periodical&lang=en-GB&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91%CB%90.d%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=periodical&lang=en-US&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91%CB%90.d%C9%AA.k%C9%99l%2F"},{"id":"lv_3_77","topic":"Urban Planning and Infrastructure Construction","word":"photocopier","pos":"(n)","ipa":"/ˈfoʊ.t̬oʊˌkɑː.pi.ɚ/","defVi":"máy photocopy, máy sao chụp tài liệu","defEn":"a machine that makes photographic copies of documents","examples":["The office [photocopier] ran out of paper right before the meeting. (=Dịch: Máy photocopy của văn phòng đã hết giấy ngay trước cuộc họp.)","She used the [photocopier] to print out thirty copies of the study guide. (=Dịch: Cô ấy đã sử dụng máy photocopy để in ra ba mươi bản tài liệu học tập.)","The technician was called in to fix the jammed [photocopier]. (=Dịch: Kỹ thuật viên đã được gọi đến để sửa chiếc máy photocopy bị kẹt giấy.)"],"ukAudio":"/ai_services/tts3/?q=photocopier&lang=en-GB&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=photocopier&lang=en-US&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi.%C9%9A%2F"},{"id":"lv_3_78","topic":"Urban Planning and Infrastructure Construction","word":"pitch","pos":"(n)","ipa":"/pɪtʃ/","defVi":"sân thể thao; cao độ âm thanh","defEn":"an area of ground marked out for playing a sports game, or the highness or lowness of a sound","examples":["The players ran onto the football [pitch] with high spirits. (=Dịch: Các cầu thủ chạy ra sân bóng đá với tinh thần phấn khởi.)","She has perfect [pitch] and can identify any musical note instantly. (=Dịch: Cô ấy có khả năng cảm âm hoàn hảo và có thể nhận biết bất kỳ nốt nhạc nào ngay lập tức.)","The heavy rain turned the cricket [pitch] into mud. (=Dịch: Cơn mưa lớn đã biến sân criket thành một bãi bùn lầy.)"],"ukAudio":"/ai_services/tts3/?q=pitch&lang=en-GB&ipa=%2Fp%C9%AAt%CA%83%2F","usAudio":"/ai_services/tts3/?q=pitch&lang=en-US&ipa=%2Fp%C9%AAt%CA%83%2F"},{"id":"lv_3_79","topic":"Urban Planning and Infrastructure Construction","word":"planner","pos":"(n)","ipa":"/ˈplæn.ɚ/","defVi":"người lập kế hoạch, nhà quy hoạch","defEn":"a person who makes plans, especially regarding urban development or events","examples":["The urban [planner] proposed building more green spaces around the city center. (=Dịch: Nhà quy hoạch đô thị đã đề xuất xây dựng thêm nhiều không gian xanh xung quanh trung tâm thành phố.)","Hiring an experienced wedding [planner] helped them avoid a lot of stress. (=Dịch: Việc thuê một người lập kế hoạch đám cưới giàu kinh nghiệm đã giúp họ tránh được rất nhiều căng thẳng.)","City [planner]s are trying to find effective solutions to ease daily traffic congestion. (=Dịch: Các nhà quy hoạch thành phố đang cố gắng tìm ra những giải pháp hiệu quả để giảm bớt tình trạng ùn tắc giao thông hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=planner&lang=en-GB&ipa=%2F%CB%88pl%C3%A6n.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=planner&lang=en-US&ipa=%2F%CB%88pl%C3%A6n.%C9%9A%2F"},{"id":"lv_3_80","topic":"Urban Planning and Infrastructure Construction","word":"poverty","pos":"(n)","ipa":"/ˈpɑː.vɚ.t̬i/","defVi":"sự nghèo đói, cảnh bần cùng","defEn":"the state of being extremely poor and lacking the means for basic needs","examples":["Education is widely seen as the key to escaping [poverty]. (=Dịch: Giáo dục được xem rộng rãi là chìa khóa để thoát nghèo.)","Many families in the region are living in extreme [poverty]. (=Dịch: Nhiều gia đình trong khu vực đang sống trong cảnh nghèo đói cùng cực.)","The charity aims to reduce urban [poverty] through job training. (=Dịch: Tổ chức từ thiện nhằm mục đích giảm nghèo đô thị thông qua việc đào tạo nghề.)"],"ukAudio":"/ai_services/tts3/?q=poverty&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=poverty&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F"},{"id":"lv_3_81","topic":"Urban Planning and Infrastructure Construction","word":"premise","pos":"(n)","ipa":"/ˈprem.ɪs/","defVi":"tiền đề, giả thuyết cơ sở","defEn":"an underlying assumption or idea on which an argument or theory is based","examples":["The entire theory is based on a false [premise]. (=Dịch: Toàn bộ lý thuyết đều dựa trên một tiền đề sai lầm.)","His argument relies on the [premise] that people always act rationally. (=Dịch: Lập luận của anh ấy dựa trên tiền đề rằng con người luôn hành động có lý trí.)","The experiment was designed to test the basic [premise] of the study. (=Dịch: Thí nghiệm được thiết kế để kiểm chứng tiền đề cơ bản của nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=premise&lang=en-GB&ipa=%2F%CB%88prem.%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=premise&lang=en-US&ipa=%2F%CB%88prem.%C9%AAs%2F"},{"id":"lv_3_82","topic":"Urban Planning and Infrastructure Construction","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a basic idea, rule, or moral belief that influences the way you behave or how things work","examples":["He refused to lie because it was against his personal [principle]. (=Dịch: Anh ấy từ chối nói dối vì điều đó đi ngược lại nguyên tắc cá nhân của mình.)","Students learn the basic [principle] of physics in high school. (=Dịch: Học sinh học các nguyên lý cơ bản của vật lý ở trường trung học phổ thông.)","Our organization is built upon the [principle] of equality for all. (=Dịch: Tổ chức của chúng tôi được xây dựng dựa trên nguyên tắc bình đẳng cho tất cả mọi người.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_3_83","topic":"Urban Planning and Infrastructure Construction","word":"pupil","pos":"(n)","ipa":"/ˈpjuː.pəl/","defVi":"học sinh (tiểu học/trung học); đồng tử (con ngươi)","defEn":"a student in school, especially a young child; also the round black opening in the center of the eye","examples":["The primary school has around four hundred [pupils]. (=Dịch: Trường tiểu học này có khoảng bốn trăm học sinh.)","The teacher encouraged every [pupil] to participate in the classroom discussion. (=Dịch: Giáo viên đã khuyến khích từng học sinh tham gia vào cuộc thảo luận trong lớp.)","His [pupils] dilated when the room suddenly went dark. (=Dịch: Đồng tử của anh ấy giãn ra khi căn phòng đột ngột tối sầm lại.)"],"ukAudio":"/ai_services/tts3/?q=pupil&lang=en-GB&ipa=%2F%CB%88pju%CB%90.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=pupil&lang=en-US&ipa=%2F%CB%88pju%CB%90.p%C9%99l%2F"},{"id":"lv_3_84","topic":"Urban Planning and Infrastructure Construction","word":"purchase","pos":"(v)","ipa":"/ˈpɜr.tʃəs/","defVi":"mua, sắm","defEn":"to buy something","examples":["She decided to [purchase] a new laptop for her university studies. (=Dịch: Cô ấy quyết định mua một chiếc máy tính xách tay mới để phục vụ cho việc học đại học.)","Tickets must be [purchased] at least two weeks in advance. (=Dịch: Vé phải được mua trước ít nhất hai tuần.)","He wants to [purchase] a property near the coast. (=Dịch: Anh ấy muốn mua một bất động sản gần bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=purchase&lang=en-GB&ipa=%2F%CB%88p%C9%9Cr.t%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=purchase&lang=en-US&ipa=%2F%CB%88p%C9%9Cr.t%CA%83%C9%99s%2F"},{"id":"lv_3_85","topic":"Urban Planning and Infrastructure Construction","word":"quarry","pos":"(n)","ipa":"/ˈkwɔːr.i/","defVi":"mỏ đá, nơi khai thác đá","defEn":"a large open pit from which stone, slate, or other materials are extracted","examples":["Limestone from the local [quarry] was used to construct many historic buildings in the area. (=Dịch: Đá vôi từ mỏ đá địa phương đã được sử dụng để xây dựng nhiều công trình lịch sử trong khu vực.)","Safety regulations were tightened at the slate [quarry] following an accidental rockslide. (=Dịch: Các quy định an toàn đã được thắt chặt tại mỏ khai thác đá phiến sau một vụ sạt lở đá tình cờ xảy ra.)","The abandoned [quarry] was transformed into a nature reserve with a deep artificial lake. (=Dịch: Mỏ đá bị bỏ hoang đã được chuyển đổi thành một khu bảo tồn thiên nhiên với một hồ nước nhân tạo sâu.)"],"ukAudio":"/ai_services/tts3/?q=quarry&lang=en-GB&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=quarry&lang=en-US&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F"},{"id":"lv_3_86","topic":"Urban Planning and Infrastructure Construction","word":"ramp","pos":"(n)","ipa":"/ræmp/","defVi":"đường dốc, lối dốc thoai thoải","defEn":"a slope or inclined surface joining two different levels","examples":["The building has a wheelchair [ramp] at the main entrance. (=Dịch: Tòa nhà có lối đi dốc dành cho xe lăn ở cổng chính.)","Cars slowed down as they approached the exit [ramp] of the highway. (=Dịch: Ô tô đã giảm tốc độ khi tiến lại gần đường dốc lối ra của đường cao tốc.)","Skaters love performing tricks on the wooden [ramp] in the park. (=Dịch: Những người trượt ván rất thích biểu diễn kỹ xảo trên đường dốc bằng gỗ trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=ramp&lang=en-GB&ipa=%2Fr%C3%A6mp%2F","usAudio":"/ai_services/tts3/?q=ramp&lang=en-US&ipa=%2Fr%C3%A6mp%2F"},{"id":"lv_3_87","topic":"Urban Planning and Infrastructure Construction","word":"reality","pos":"(n)","ipa":"/riˈæl.ə.t̬i/","defVi":"thực tế, hiện thực","defEn":"the state of things as they actually exist, rather than as they may be imagined","examples":["The harsh [reality] is that we do not have enough funds to finish the project. (=Dịch: Thực tế phũ phàng là chúng tôi không có đủ kinh phí để hoàn thành dự án.)","His childhood dream of becoming an astronaut finally became a [reality]. (=Dịch: Ước mơ thời thơ ấu trở thành phi hành gia của anh ấy cuối cùng đã trở thành hiện thực.)","Virtual reality allows users to experience situations that feel close to [reality]. (=Dịch: Thực tế ảo cho phép người dùng trải nghiệm những tình huống mang lại cảm giác chân thực như đời thực.)"],"ukAudio":"/ai_services/tts3/?q=reality&lang=en-GB&ipa=%2Fri%CB%88%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=reality&lang=en-US&ipa=%2Fri%CB%88%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_88","topic":"Urban Planning and Infrastructure Construction","word":"reclaim","pos":"(v)","ipa":"/rɪˈkleɪm/","defVi":"khai hoang, cải tạo, tái chế","defEn":"to recover or make usable land or materials that were previously unused, degraded, or waste","examples":["The government initiated a project to [reclaim] degraded marshland for agriculture. (=Dịch: Chính phủ đã khởi xướng một dự án cải tạo vùng đất ngập nước bị suy thoái để phục vụ nông nghiệp.)","The factory uses modern methods to [reclaim] valuable metals from industrial waste. (=Dịch: Nhà máy sử dụng các phương pháp hiện đại để thu hồi các kim loại quý từ chất thải công nghiệp.)","Efforts were made to [reclaim] the abandoned quarry and transform it into a public park. (=Dịch: Nhiều nỗ lực đã được thực hiện nhằm phục hồi mỏ đá bị bỏ hoang và biến nó thành một công viên công cộng.)"],"ukAudio":"/ai_services/tts3/?q=reclaim&lang=en-GB&ipa=%2Fr%C9%AA%CB%88kle%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=reclaim&lang=en-US&ipa=%2Fr%C9%AA%CB%88kle%C9%AAm%2F"},{"id":"lv_3_89","topic":"Urban Planning and Infrastructure Construction","word":"recreation","pos":"(n)","ipa":"/ˌrek.riˈeɪ.ʃən/","defVi":"sự giải trí, trò tiêu khiển","defEn":"activity done for enjoyment when one is not working","examples":["Swimming and cycling are popular forms of [recreation] for families. (=Dịch: Bơi lội và đạp xe là những hình thức giải trí phổ biến của các gia đình.)","The community center offers a variety of sports facilities for [recreation]. (=Dịch: Trung tâm cộng đồng cung cấp nhiều cơ sở vật chất thể thao phục vụ cho việc giải trí.)","He enjoys outdoor [recreation] such as hiking and camping on weekends. (=Dịch: Anh ấy thích các hoạt động giải trí ngoài trời như đi bộ đường dài và cắm trại vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=recreation&lang=en-GB&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=recreation&lang=en-US&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_90","topic":"Urban Planning and Infrastructure Construction","word":"redevelopment","pos":"(n)","ipa":"/ˌriː.dɪˈvel.əp.mənt/","defVi":"sự tái quy hoạch, việc cải tạo và xây dựng lại","defEn":"the process of improving or rebuilding an area, often with new buildings","examples":["The city announced an ambitious [redevelopment] plan for the old industrial zone. (=Dịch: Thành phố đã công bố một kế hoạch tái phát triển đầy tham vọng cho khu công nghiệp cũ.)","Urban [redevelopment] has transformed this rundown neighborhood into a popular tourist spot. (=Dịch: Tái phát triển đô thị đã biến khu phố xuống cấp này thành một điểm thu hút khách du lịch nổi tiếng.)","Residents expressed concerns about rising housing costs following the [redevelopment] of the district. (=Dịch: Cư dân bày tỏ lo ngại về chi phí nhà ở tăng cao sau khi tái phát triển quận.)"],"ukAudio":"/ai_services/tts3/?q=redevelopment&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.d%C9%AA%CB%88vel.%C9%99p.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=redevelopment&lang=en-US&ipa=%2F%CB%8Cri%CB%90.d%C9%AA%CB%88vel.%C9%99p.m%C9%99nt%2F"},{"id":"lv_3_91","topic":"Urban Planning and Infrastructure Construction","word":"reed","pos":"(n)","ipa":"/riːd/","defVi":"cây sậy, lau sậy","defEn":"a tall, slender plant that grows in or near water, having hollow stalks","examples":["Water birds often build their nests among the dense [reeds] along the riverbank. (=Dịch: Các loài chim nước thường làm tổ giữa những bụi sậy rậm rạp dọc theo bờ sông.)","In ancient times, paper was made from papyrus [reeds]. (=Dịch: Thời cổ đại, giấy được làm từ cây sậy papyrus.)","The wind gently rustled through the dry [reeds] by the lake. (=Dịch: Gió thổi xào xạc nhẹ qua những rặng sậy khô bên hồ.)"],"ukAudio":"/ai_services/tts3/?q=reed&lang=en-GB&ipa=%2Fri%CB%90d%2F","usAudio":"/ai_services/tts3/?q=reed&lang=en-US&ipa=%2Fri%CB%90d%2F"},{"id":"lv_3_92","topic":"Urban Planning and Infrastructure Construction","word":"relaxing","pos":"(adj)","ipa":"/rɪˈlæk.sɪŋ/","defVi":"thư giãn, mang lại cảm giác thoải mái","defEn":"making someone feel calm, peaceful, and free from stress","examples":["Listening to soft instrumental music is a very [relaxing] way to end a busy day. (=Dịch: Nghe nhạc không lời nhẹ nhàng là một cách rất thư giãn để kết thúc một ngày bận rộn.)","They spent a [relaxing] weekend at a quiet cabin near the lake. (=Dịch: Họ đã trải qua một ngày cuối tuần thư thái tại một căn nhà gỗ yên tĩnh gần hồ.)","The hotel spa provides a [relaxing] atmosphere with warm lighting and gentle scents. (=Dịch: Khu spa của khách sạn mang lại một không gian thư thái với ánh sáng ấm áp và hương thơm dịu nhẹ.)"],"ukAudio":"/ai_services/tts3/?q=relaxing&lang=en-GB&ipa=%2Fr%C9%AA%CB%88l%C3%A6k.s%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=relaxing&lang=en-US&ipa=%2Fr%C9%AA%CB%88l%C3%A6k.s%C9%AA%C5%8B%2F"},{"id":"lv_3_93","topic":"Urban Planning and Infrastructure Construction","word":"reopen","pos":"(v)","ipa":"/riˈoʊ.pən/","defVi":"mở cửa lại, tái hoạt động","defEn":"to open again after being closed for a period of time","examples":["The museum plans to [reopen] to the public next month. (=Dịch: Bảo tàng có kế hoạch mở cửa trở lại cho công chúng vào tháng tới.)","The police decided to [reopen] the investigation after finding new clues. (=Dịch: Cảnh sát đã quyết định mở lại cuộc điều tra sau khi tìm thấy những manh mối mới.)","Local shops are preparing to [reopen] following the renovation. (=Dịch: Các cửa hàng địa phương đang chuẩn bị mở cửa trở lại sau khi tu sửa.)"],"ukAudio":"/ai_services/tts3/?q=reopen&lang=en-GB&ipa=%2Fri%CB%88o%CA%8A.p%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reopen&lang=en-US&ipa=%2Fri%CB%88o%CA%8A.p%C9%99n%2F"},{"id":"lv_3_94","topic":"Urban Planning and Infrastructure Construction","word":"representative","pos":"(n)","ipa":"/ˌrep.rɪˈzen.t̬ə.t̬ɪv/","defVi":"người đại diện, đại biểu","defEn":"a person chosen or elected to speak or act on behalf of others","examples":["A customer service [representative] will answer your call shortly. (=Dịch: Đại diện dịch vụ khách hàng sẽ trả lời cuộc gọi của bạn trong giây lát.)","Each student group elected a [representative] to attend the council meeting. (=Dịch: Mỗi nhóm sinh viên đã bầu ra một đại diện để tham dự cuộc họp hội đồng.)","She spoke to the company [representative] to negotiate the terms of the contract. (=Dịch: Cô ấy đã nói chuyện với đại diện công ty để đàm phán các điều khoản của hợp đồng.)"],"ukAudio":"/ai_services/tts3/?q=representative&lang=en-GB&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=representative&lang=en-US&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_3_95","topic":"Urban Planning and Infrastructure Construction","word":"residential","pos":"(adj)","ipa":"/ˌrez.əˈden.ʃəl/","defVi":"(thuộc) khu dân cư, để ở","defEn":"suitable for or containing homes rather than businesses or industries","examples":["The speed limit is lower in [residential] areas to protect pedestrians. (=Dịch: Giới hạn tốc độ thấp hơn ở các khu dân cư để bảo vệ người đi bộ.)","They moved away from the noisy commercial center to a quiet [residential] suburb. (=Dịch: Họ đã chuyển từ khu trung tâm thương mại ồn ào đến một vùng ngoại ô dân cư yên tĩnh.)","Many [residential] buildings were constructed during the recent economic boom. (=Dịch: Nhiều tòa nhà dân cư đã được xây dựng trong thời kỳ bùng nổ kinh tế gần đây.)"],"ukAudio":"/ai_services/tts3/?q=residential&lang=en-GB&ipa=%2F%CB%8Crez.%C9%99%CB%88den.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=residential&lang=en-US&ipa=%2F%CB%8Crez.%C9%99%CB%88den.%CA%83%C9%99l%2F"},{"id":"lv_3_96","topic":"Urban Planning and Infrastructure Construction","word":"respondent","pos":"(n)","ipa":"/rɪˈspɑːn.dənt/","defVi":"người trả lời (khảo sát, phỏng vấn)","defEn":"a person who answers questions, especially in a survey or study","examples":["Over sixty percent of [respondents] agreed with the proposed changes. (=Dịch: Hơn sáu mươi phần trăm số người được khảo sát đồng ý với những thay đổi được đề xuất.)","Each [respondent] was asked to complete a brief questionnaire online. (=Dịch: Mỗi người tham gia khảo sát được yêu cầu hoàn thành một bảng câu hỏi ngắn trực tuyến.)","The researchers interviewed more than one thousand [respondents] across the country. (=Dịch: Các nhà nghiên cứu đã phỏng vấn hơn một nghìn người tham gia khảo sát trên khắp cả nước.)"],"ukAudio":"/ai_services/tts3/?q=respondent&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=respondent&lang=en-US&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F"},{"id":"lv_3_97","topic":"Urban Planning and Infrastructure Construction","word":"riverside","pos":"(n)","ipa":"/ˈrɪv.ɚ.saɪd/","defVi":"bờ sông, ven sông","defEn":"the area of land situated along the edge of a river","examples":["We enjoyed a long evening walk along the peaceful [riverside]. (=Dịch: Chúng tôi rất thích đi dạo vào buổi tối dọc theo bờ sông yên bình.)","The city constructed a scenic cycling track on the northern [riverside]. (=Dịch: Thành phố đã xây dựng một đường đạp xe ngắm cảnh ở bờ sông phía bắc.)","Many popular restaurants are located on the [riverside], offering beautiful water views. (=Dịch: Nhiều nhà hàng nổi tiếng tọa lạc bên bờ sông, mang đến tầm nhìn tuyệt đẹp ra mặt nước.)"],"ukAudio":"/ai_services/tts3/?q=riverside&lang=en-GB&ipa=%2F%CB%88r%C9%AAv.%C9%9A.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=riverside&lang=en-US&ipa=%2F%CB%88r%C9%AAv.%C9%9A.sa%C9%AAd%2F"},{"id":"lv_3_98","topic":"Urban Planning and Infrastructure Construction","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a neat line of people, objects, or seats arranged side by side or one behind another","examples":["The students were asked to sit quietly in a single [row]. (=Dịch: Các học sinh được yêu cầu ngồi trật tự thành một hàng duy nhất.)","A long [row] of solar panels was installed along the edge of the farm. (=Dịch: Một dãy dài các tấm pin mặt trời đã được lắp đặt dọc theo rìa trang trại.)","She planted a [row] of rose bushes in front of her house. (=Dịch: Cô ấy đã trồng một hàng bụi hoa hồng trước nhà.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_3_99","topic":"Urban Planning and Infrastructure Construction","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"thuộc hoàng gia, hoàng tộc","defEn":"relating to a king or queen","examples":["The [royal] family attended the annual charity event together. (=Dịch: Hoàng gia đã cùng nhau tham dự sự kiện từ thiện thường niên.)","Visitors are allowed to explore parts of the historic [royal] palace. (=Dịch: Du khách được phép khám phá một số khu vực của cung điện hoàng gia mang tính lịch sử.)","The museum displays a rare collection of ancient [royal] jewels. (=Dịch: Bảo tàng trưng bày một bộ sưu tập trang sức hoàng gia cổ đại quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_3_100","topic":"Urban Planning and Infrastructure Construction","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ɚ/","defVi":"cao su","defEn":"an elastic substance made from the juice of tropical trees or synthesized chemically","examples":["Car tires are made of durable synthetic [rubber]. (=Dịch: Lốp ô tô được làm từ cao su tổng hợp có độ bền cao.)","The boots are waterproof because they are lined with [rubber]. (=Dịch: Đôi ủng có khả năng chống nước vì chúng được lót bằng cao su.)","She used a soft [rubber] ball to exercise her hand muscles. (=Dịch: Cô ấy đã dùng một quả bóng cao su mềm để luyện tập cơ tay.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F"},{"id":"lv_3_101","topic":"Urban Planning and Infrastructure Construction","word":"secure","pos":"(adj)","ipa":"/səˈkjʊr/","defVi":"an toàn, chắc chắn, kiên cố","defEn":"safe from danger, harm, or the risk of failure","examples":["Online shoppers must ensure they are using a [secure] connection before entering payment details. (=Dịch: Người mua sắm trực tuyến phải đảm bảo họ đang sử dụng một kết nối an toàn trước khi nhập thông tin thanh toán.)","The documents were kept in a [secure] safe in the manager's private office. (=Dịch: Các tài liệu được lưu giữ trong một chiếc két sắt an toàn tại văn phòng riêng của người quản lý.)","She finally found a [secure] job that provided stable income and health benefits. (=Dịch: Cuối cùng cô ấy cũng tìm được một công việc ổn định mang lại thu nhập vững chắc và các chế độ bảo hiểm y tế.)"],"ukAudio":"/ai_services/tts3/?q=secure&lang=en-GB&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=secure&lang=en-US&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F"},{"id":"lv_3_102","topic":"Urban Planning and Infrastructure Construction","word":"silent","pos":"(adj)","ipa":"/ˈsaɪ.lənt/","defVi":"yên lặng, im lặng","defEn":"making no sound or completely quiet","examples":["The library remained completely [silent] throughout the morning. (=Dịch: Thư viện hoàn toàn yên tĩnh trong suốt cả buổi sáng.)","He decided to keep [silent] during the intense debate. (=Dịch: Anh ấy quyết định giữ im lặng trong suốt cuộc tranh luận căng thẳng.)","Students were asked to observe a minute of [silent] reflection. (=Dịch: Các học sinh được yêu cầu dành một phút mặc niệm trong tĩnh lặng.)"],"ukAudio":"/ai_services/tts3/?q=silent&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.l%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=silent&lang=en-US&ipa=%2F%CB%88sa%C9%AA.l%C9%99nt%2F"},{"id":"lv_3_103","topic":"Urban Planning and Infrastructure Construction","word":"skateboard","pos":"(n)","ipa":"/ˈskeɪt.bɔrd/","defVi":"ván trượt","defEn":"a short narrow board with small wheels attached underneath, used for riding on","examples":["He rode his [skateboard] to school every morning. (=Dịch: Cậu ấy trượt ván đến trường mỗi sáng.)","The city recently built a new park for teenagers who ride a [skateboard]. (=Dịch: Thành phố gần đây đã xây dựng một công viên mới dành cho thanh thiếu niên chơi ván trượt.)","She bought a colorful [skateboard] as a birthday gift for her brother. (=Dịch: Cô ấy đã mua một chiếc ván trượt đầy màu sắc làm quà sinh nhật cho anh trai mình.)"],"ukAudio":"/ai_services/tts3/?q=skateboard&lang=en-GB&ipa=%2F%CB%88ske%C9%AAt.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=skateboard&lang=en-US&ipa=%2F%CB%88ske%C9%AAt.b%C9%94rd%2F"},{"id":"lv_3_104","topic":"Urban Planning and Infrastructure Construction","word":"statue","pos":"(n)","ipa":"/ˈstæ.tʃu/","defVi":"tượng, bức tượng","defEn":"a three-dimensional work of art sculpted or cast in stone, metal, or wood, representing a person or animal","examples":["A bronze [statue] of the famous poet was erected in the central square. (=Dịch: Một bức tượng đồng của nhà thơ nổi tiếng đã được dựng lên ở quảng trường trung tâm.)","Tourists gathered around the ancient marble [statue] to take photographs. (=Dịch: Khách du lịch tập trung quanh bức tượng cẩm thạch cổ kính để chụp ảnh.)","The city unveiled a new [statue] honoring frontline healthcare workers. (=Dịch: Thành phố đã khánh thành một bức tượng mới nhằm tôn vinh các nhân viên y tế tuyến đầu.)"],"ukAudio":"/ai_services/tts3/?q=statue&lang=en-GB&ipa=%2F%CB%88st%C3%A6.t%CA%83u%2F","usAudio":"/ai_services/tts3/?q=statue&lang=en-US&ipa=%2F%CB%88st%C3%A6.t%CA%83u%2F"},{"id":"lv_3_105","topic":"Urban Planning and Infrastructure Construction","word":"storey","pos":"(n)","ipa":"/ˈstɔːr.i/","defVi":"tầng (của tòa nhà)","defEn":"a level or floor of a building","examples":["They live in a modern apartment on the twentieth [storey]. (=Dịch: Họ sống trong một căn hộ hiện đại ở tầng hai mươi.)","The developer plans to construct a multi-[storey] car park near the station. (=Dịch: Chủ đầu tư có kế hoạch xây dựng một bãi đỗ xe nhiều tầng gần nhà ga.)","The traditional house only has one [storey]. (=Dịch: Ngôi nhà truyền thống này chỉ có một tầng.)"],"ukAudio":"/ai_services/tts3/?q=storey&lang=en-GB&ipa=%2F%CB%88st%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=storey&lang=en-US&ipa=%2F%CB%88st%C9%94%CB%90r.i%2F"},{"id":"lv_3_106","topic":"Urban Planning and Infrastructure Construction","word":"suburb","pos":"(n)","ipa":"/ˈsʌb.ɜrb/","defVi":"vùng ngoại ô, vùng ngoại thành","defEn":"a residential area located outside the center of a large city","examples":["Many families move to a peaceful [suburb] to enjoy more open space and cleaner air. (=Dịch: Nhiều gia đình chuyển đến một vùng ngoại ô yên bình để tận hưởng không gian thoáng đãng hơn và không khí trong lành hơn.)","The newly built railway line connects the quiet [suburb] directly to downtown. (=Dịch: Tuyến đường sắt mới xây kết nối trực tiếp khu ngoại ô yên tĩnh với khu trung tâm thành phố.)","Property prices in this northern [suburb] have risen sharply over the past decade. (=Dịch: Giá bất động sản ở vùng ngoại ô phía bắc này đã tăng mạnh trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=suburb&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.%C9%9Crb%2F","usAudio":"/ai_services/tts3/?q=suburb&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.%C9%9Crb%2F"},{"id":"lv_3_107","topic":"Urban Planning and Infrastructure Construction","word":"symbolic","pos":"(adj)","ipa":"/sɪmˈbɑː.lɪk/","defVi":"mang tính biểu tượng, tượng trưng","defEn":"serving as a symbol; representing something deeper or meaningful","examples":["The dove is widely recognized as a [symbolic] figure of peace. (=Dịch: Chim bồ câu được công nhận rộng rãi là một hình tượng tượng trưng cho hòa bình.)","Giving flowers on Valentine's Day has a strong [symbolic] meaning. (=Dịch: Việc tặng hoa vào ngày lễ Tình nhân mang một ý nghĩa biểu tượng sâu sắc.)","The lighting of the Olympic flame is a purely [symbolic] gesture. (=Dịch: Việc thắp sáng ngọn đuốc Olympic hoàn toàn là một cử chỉ mang tính biểu tượng.)"],"ukAudio":"/ai_services/tts3/?q=symbolic&lang=en-GB&ipa=%2Fs%C9%AAm%CB%88b%C9%91%CB%90.l%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=symbolic&lang=en-US&ipa=%2Fs%C9%AAm%CB%88b%C9%91%CB%90.l%C9%AAk%2F"},{"id":"lv_3_108","topic":"Urban Planning and Infrastructure Construction","word":"tile","pos":"(n)","ipa":"/taɪl/","defVi":"gạch lát, gạch ốp, ngói","defEn":"a flat piece of baked clay, stone, or ceramic used for covering roofs, floors, or walls","examples":["They decided to replace the old bathroom [tiles] with modern ceramic ones. (=Dịch: Họ quyết định thay thế gạch phòng tắm cũ bằng loại gạch gốm hiện đại.)","Strong winds blew several roof [tiles] off during the storm. (=Dịch: Gió mạnh đã thổi bay vài viên ngói lợp mái trong cơn bão.)","The kitchen floor is covered with polished white [tiles]. (=Dịch: Sàn nhà bếp được lát bằng những viên gạch trắng sáng bóng.)"],"ukAudio":"/ai_services/tts3/?q=tile&lang=en-GB&ipa=%2Fta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=tile&lang=en-US&ipa=%2Fta%C9%AAl%2F"},{"id":"lv_3_109","topic":"Urban Planning and Infrastructure Construction","word":"transform","pos":"(v)","ipa":"/trænsˈfɔrm/","defVi":"biến đổi, thay đổi diện mạo","defEn":"to change the form, appearance, or character of something completely","examples":["The new park has [transformed] the abandoned industrial zone into a vibrant public area. (=Dịch: Công viên mới đã biến khu công nghiệp bị bỏ hoang thành một khu vực công cộng sôi động.)","Online learning has the potential to [transform] modern education. (=Dịch: Học trực tuyến có tiềm năng làm thay đổi nền giáo dục hiện đại.)","A fresh coat of paint will [transform] the look of the old living room. (=Dịch: Một lớp sơn mới sẽ làm thay đổi hoàn toàn diện mạo của phòng khách cũ.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F"},{"id":"lv_3_110","topic":"Urban Planning and Infrastructure Construction","word":"transformation","pos":"(n)","ipa":"/ˌtræns.fɚˈmeɪ.ʃən/","defVi":"sự biến đổi, sự chuyển đổi hoàn toàn","defEn":"a complete change in the appearance or character of something","examples":["The city underwent a dramatic [transformation] over the last decade. (=Dịch: Thành phố đã trải qua một sự chuyển mình mạnh mẽ trong thập kỷ qua.)","Digital technology has led to a rapid [transformation] in education. (=Dịch: Công nghệ số đã dẫn đến một sự chuyển biến nhanh chóng trong giáo dục.)","Her fitness journey resulted in an impressive physical [transformation]. (=Dịch: Hành trình tập luyện rèn luyện thể chất của cô ấy đã mang lại một sự thay đổi ngoạn mục về vóc dáng.)"],"ukAudio":"/ai_services/tts3/?q=transformation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=transformation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_111","topic":"Urban Planning and Infrastructure Construction","word":"tropical","pos":"(adj)","ipa":"/ˈtrɑː.pɪ.kəl/","defVi":"nhiệt đới","defEn":"connected with the warmest areas of the world near the equator","examples":["The island is famous for its lush [tropical] rainforests. (=Dịch: Hòn đảo này nổi tiếng với những khu rừng mưa nhiệt đới tươi tốt.)","They enjoy eating sweet [tropical] fruits such as mangoes and papayas. (=Dịch: Họ thích ăn các loại trái cây nhiệt đới ngọt ngào như xoài và đu đủ.)","A sudden [tropical] storm caused minor flooding along the coast. (=Dịch: Một cơn bão nhiệt đới bất ngờ đã gây ra ngập lụt nhẹ dọc bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=tropical&lang=en-GB&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tropical&lang=en-US&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F"},{"id":"lv_3_112","topic":"Urban Planning and Infrastructure Construction","word":"uncomfortable","pos":"(adj)","ipa":"/ʌnˈkʌmf.tə.bəl/","defVi":"không thoải mái, khó chịu, ngượng ngùng","defEn":"causing or feeling a lack of physical comfort, ease, or relaxation","examples":["The old wooden chair was extremely [uncomfortable] to sit on. (=Dịch: Chiếc ghế gỗ cũ ngồi cực kỳ khó chịu.)","There was an [uncomfortable] silence when she asked the sensitive question. (=Dịch: Bầu không khí im lặng đầy gượng gạo bao trùm khi cô ấy đặt ra câu hỏi nhạy cảm.)","Wearing wet shoes all day made him feel very [uncomfortable]. (=Dịch: Việc đi giày ướt cả ngày khiến anh ấy cảm thấy rất khó chịu.)"],"ukAudio":"/ai_services/tts3/?q=uncomfortable&lang=en-GB&ipa=%2F%CA%8Cn%CB%88k%CA%8Cmf.t%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=uncomfortable&lang=en-US&ipa=%2F%CA%8Cn%CB%88k%CA%8Cmf.t%C9%99.b%C9%99l%2F"},{"id":"lv_3_113","topic":"Urban Planning and Infrastructure Construction","word":"union","pos":"(n)","ipa":"/ˈjuːn.jən/","defVi":"công đoàn, liên đoàn, sự kết hợp","defEn":"an organization of workers formed to protect their rights and interests","examples":["The trade [union] negotiated better working hours for the factory staff. (=Dịch: Công đoàn thương mại đã đàm phán để có giờ làm việc tốt hơn cho các nhân viên nhà máy.)","Joining a labor [union] gives employees a stronger collective voice. (=Dịch: Tham gia một công đoàn lao động mang lại cho nhân viên tiếng nói tập thể mạnh mẽ hơn.)","Several European countries formed a political and economic [union]. (=Dịch: Một số quốc gia châu Âu đã thành lập một liên minh chính trị và kinh tế.)"],"ukAudio":"/ai_services/tts3/?q=union&lang=en-GB&ipa=%2F%CB%88ju%CB%90n.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=union&lang=en-US&ipa=%2F%CB%88ju%CB%90n.j%C9%99n%2F"},{"id":"lv_3_114","topic":"Urban Planning and Infrastructure Construction","word":"unsafe","pos":"(adj)","ipa":"/ʌnˈseɪf/","defVi":"không an toàn, nguy hiểm","defEn":"likely to cause harm or danger","examples":["It is completely [unsafe] to walk on the frozen lake in spring. (=Dịch: Đi bộ trên mặt hồ đóng băng vào mùa xuân là hoàn toàn không an toàn.)","The building was declared [unsafe] after the earthquake. (=Dịch: Tòa nhà bị tuyên bố là không an toàn sau trận động đất.)","Driving in extreme weather conditions is extremely [unsafe]. (=Dịch: Lái xe trong điều kiện thời tiết khắc nghiệt là cực kỳ mất an toàn.)"],"ukAudio":"/ai_services/tts3/?q=unsafe&lang=en-GB&ipa=%2F%CA%8Cn%CB%88se%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=unsafe&lang=en-US&ipa=%2F%CA%8Cn%CB%88se%C9%AAf%2F"},{"id":"lv_3_115","topic":"Urban Planning and Infrastructure Construction","word":"virtual","pos":"(adj)","ipa":"/ˈvɝː.tʃu.əl/","defVi":"ảo, thực tế ảo","defEn":"created by computer software and appearing to exist in real life","examples":["The company held a [virtual] meeting with clients from across the globe. (=Dịch: Công ty đã tổ chức một cuộc họp trực tuyến với các khách hàng từ khắp nơi trên thế giới.)","Students wore headsets to enter a [virtual] science laboratory. (=Dịch: Học sinh đã đeo tai nghe thực tế ảo để bước vào một phòng thí nghiệm khoa học ảo.)","Many museums now offer engaging [virtual] tours on their websites. (=Dịch: Nhiều bảo tàng hiện cung cấp các chuyến tham quan ảo hấp dẫn trên trang web của họ.)"],"ukAudio":"/ai_services/tts3/?q=virtual&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=virtual&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.t%CA%83u.%C9%99l%2F"},{"id":"lv_3_116","topic":"Urban Planning and Infrastructure Construction","word":"visibility","pos":"(n)","ipa":"/ˌvɪz.əˈbɪl.ə.t̬i/","defVi":"tầm nhìn, độ nhìn rõ","defEn":"the distance that can be seen clearly in particular weather conditions","examples":["Thick fog reduced [visibility] to less than fifty meters. (=Dịch: Sương mù dày đặc làm giảm tầm nhìn xuống dưới năm mươi mét.)","Poor [visibility] caused several flights to be delayed this morning. (=Dịch: Tầm nhìn kém đã khiến một số chuyến bay bị hoãn vào sáng nay.)","Cyclists should wear bright clothing to improve their [visibility] at night. (=Dịch: Người đi xe đạp nên mặc quần áo sáng màu để tăng khả năng nhận diện vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=visibility&lang=en-GB&ipa=%2F%CB%8Cv%C9%AAz.%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=visibility&lang=en-US&ipa=%2F%CB%8Cv%C9%AAz.%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_117","topic":"Urban Planning and Infrastructure Construction","word":"wheelchair","pos":"(n)","ipa":"/ˈwiːl.tʃer/","defVi":"xe lăn","defEn":"a chair with wheels, used by people who cannot walk due to illness or injury","examples":["The museum recently installed ramps to ensure easy access for visitors in a [wheelchair]. (=Dịch: Bảo tàng gần đây đã lắp đặt các đường dốc nhằm đảm bảo lối đi lại dễ dàng cho khách tham quan ngồi xe lăn.)","After his sports injury, he had to use a [wheelchair] for several months. (=Dịch: Sau chấn thương thể thao, anh ấy đã phải sử dụng xe lăn trong vài tháng.)","Electric [wheelchair] models offer greater independence for individuals with mobility challenges. (=Dịch: Các mẫu xe lăn điện mang lại sự độc lập hơn cho những người gặp khó khăn trong việc vận động.)"],"ukAudio":"/ai_services/tts3/?q=wheelchair&lang=en-GB&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F","usAudio":"/ai_services/tts3/?q=wheelchair&lang=en-US&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F"},{"id":"lv_3_118","topic":"Urban Planning and Infrastructure Construction","word":"widen","pos":"(v)","ipa":"/ˈwaɪ.dən/","defVi":"mở rộng, nới rộng","defEn":"to become wider, or to make something wider or broader","examples":["The local council plans to [widen] the main road to reduce traffic jams. (=Dịch: Hội đồng địa phương có kế hoạch mở rộng con đường chính để giảm thiểu ùn tắc giao thông.)","Reading books regularly can help you [widen] your general knowledge. (=Dịch: Đọc sách thường xuyên có thể giúp bạn mở rộng kiến thức chung của mình.)","The gap between rich and poor continues to [widen] in many countries. (=Dịch: Khoảng cách giàu nghèo tiếp tục nới rộng ở nhiều quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=widen&lang=en-GB&ipa=%2F%CB%88wa%C9%AA.d%C9%99n%2F","usAudio":"/ai_services/tts3/?q=widen&lang=en-US&ipa=%2F%CB%88wa%C9%AA.d%C9%99n%2F"},{"id":"lv_4_0","topic":"Cultural and Historical Exchange","word":"aboriginal","pos":"(adj)","ipa":"/ˌæb.əˈrɪdʒ.ən.əl/","defVi":"thuộc về thổ dân, bản địa nguyên thủy","defEn":"relating to the original people or things that have existed in a place from the earliest known times","examples":["The museum exhibits ancient tools and pottery made by [aboriginal] tribes. (=Dịch: Bảo tàng trưng bày các công cụ và đồ gốm cổ xưa do các bộ lạc thổ dân tạo ra.)","They are working to preserve [aboriginal] languages before they disappear completely. (=Dịch: Họ đang nỗ lực bảo tồn các ngôn ngữ thổ dân trước khi chúng biến mất hoàn toàn.)","Traditional [aboriginal] rock art provides valuable insights into ancient history. (=Dịch: Nghệ thuật trên đá truyền thống của thổ dân cung cấp những hiểu biết quý giá về lịch sử cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=aboriginal&lang=en-GB&ipa=%2F%CB%8C%C3%A6b.%C9%99%CB%88r%C9%AAd%CA%92.%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aboriginal&lang=en-US&ipa=%2F%CB%8C%C3%A6b.%C9%99%CB%88r%C9%AAd%CA%92.%C9%99n.%C9%99l%2F"},{"id":"lv_4_1","topic":"Cultural and Historical Exchange","word":"academy","pos":"(n)","ipa":"/əˈkæd.ə.mi/","defVi":"học viện, viện hàn lâm","defEn":"an institution or school designed for specialized training, education, or research","examples":["He applied for admission to the prestigious military [academy] after finishing high school. (=Dịch: Anh ấy đã nộp đơn xin nhập học vào học viện quân sự danh giá sau khi học xong trung học.)","The national science [academy] recently published a major report on climate change. (=Dịch: Viện hàn lâm khoa học quốc gia gần đây đã công bố một báo cáo quan trọng về biến đổi khí hậu.)","She improved her tennis skills after joining a specialized sports [academy]. (=Dịch: Cô ấy đã nâng cao kỹ năng quần vợt của mình sau khi gia nhập một học viện thể thao chuyên biệt.)"],"ukAudio":"/ai_services/tts3/?q=academy&lang=en-GB&ipa=%2F%C9%99%CB%88k%C3%A6d.%C9%99.mi%2F","usAudio":"/ai_services/tts3/?q=academy&lang=en-US&ipa=%2F%C9%99%CB%88k%C3%A6d.%C9%99.mi%2F"},{"id":"lv_4_2","topic":"Cultural and Historical Exchange","word":"accountants","pos":"(n)","ipa":"/əˈkaʊn.tənts/","defVi":"kế toán viên","defEn":"professionals whose job is to keep and inspect financial records","examples":["Many large companies hire external [accountants] to audit their finances. (=Dịch: Nhiều công ty lớn thuê kế toán viên bên ngoài để kiểm toán tài chính của họ.)","The firm employs five certified [accountants] to manage corporate tax filings. (=Dịch: Công ty tuyển dụng năm kế toán viên có chứng chỉ để quản lý việc kê khai thuế doanh nghiệp.)","Experienced [accountants] are always in high demand across various industries. (=Dịch: Những kế toán viên giàu kinh nghiệm luôn được săn đón nhiều ở các ngành nghề khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=accountants&lang=en-GB&ipa=%2F%C9%99%CB%88ka%CA%8An.t%C9%99nts%2F","usAudio":"/ai_services/tts3/?q=accountants&lang=en-US&ipa=%2F%C9%99%CB%88ka%CA%8An.t%C9%99nts%2F"},{"id":"lv_4_3","topic":"Cultural and Historical Exchange","word":"adaptation","pos":"(n)","ipa":"/ˌæd.æpˈteɪ.ʃən/","defVi":"sự thích nghi; tác phẩm chuyển thể","defEn":"the process of changing to suit a new situation, or a film or book that has been changed from another work","examples":["The film is a faithful [adaptation] of the famous novel. (=Dịch: Bộ phim là một tác phẩm chuyển thể trung thành với cuốn tiểu thuyết nổi tiếng.)","Living in a colder climate requires some physical [adaptation]. (=Dịch: Sống ở nơi có khí hậu lạnh hơn đòi hỏi sự thích nghi nhất định về mặt thể chất.)","The species survived thanks to its rapid [adaptation] to environmental changes. (=Dịch: Loài này đã sống sót nhờ khả năng thích nghi nhanh chóng với những thay đổi của môi trường.)"],"ukAudio":"/ai_services/tts3/?q=adaptation&lang=en-GB&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=adaptation&lang=en-US&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_4","topic":"Cultural and Historical Exchange","word":"advanced","pos":"(adj)","ipa":"/ədˈvænst/","defVi":"tiên tiến, cao cấp, nâng cao","defEn":"highly developed, complex, or at a high level of progress","examples":["The hospital is equipped with [advanced] medical technology. (=Dịch: Bệnh viện được trang bị công nghệ y tế tiên tiến.)","Students need to pass a test before joining the [advanced] English class. (=Dịch: Học sinh cần phải vượt qua một bài kiểm tra trước khi tham gia lớp tiếng Anh nâng cao.)","Scientists are exploring [advanced] materials to make batteries last longer. (=Dịch: Các nhà khoa học đang nghiên cứu các vật liệu tiên tiến để giúp pin có tuổi thọ lâu hơn.)"],"ukAudio":"/ai_services/tts3/?q=advanced&lang=en-GB&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F","usAudio":"/ai_services/tts3/?q=advanced&lang=en-US&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F"},{"id":"lv_4_5","topic":"Cultural and Historical Exchange","word":"aerial","pos":"(adj)","ipa":"/ˈer.i.əl/","defVi":"trên không, từ trên cao","defEn":"existing, happening, or operating in the air; seen from above","examples":["The documentary showed breathtaking [aerial] views of the Amazon rainforest. (=Dịch: Bộ phim tài liệu đã cho thấy những khung cảnh ngoạn mục chụp từ trên không của rừng mưa nhiệt đới Amazon.)","Drones are increasingly used for [aerial] photography and mapping. (=Dịch: Máy bay không người lái ngày càng được sử dụng nhiều cho việc chụp ảnh và lập bản đồ từ trên cao.)","The army launched an [aerial] attack on the enemy stronghold. (=Dịch: Quân đội đã mở một cuộc không kích vào thành trì của đối phương.)"],"ukAudio":"/ai_services/tts3/?q=aerial&lang=en-GB&ipa=%2F%CB%88er.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aerial&lang=en-US&ipa=%2F%CB%88er.i.%C9%99l%2F"},{"id":"lv_4_6","topic":"Cultural and Historical Exchange","word":"alike","pos":"(adj)","ipa":"/əˈlaɪk/","defVi":"giống nhau, tương tự nhau","defEn":"similar to each other in appearance, character, or nature","examples":["The two sisters look so [alike] that people often confuse them. (=Dịch: Hai chị em trông giống nhau đến mức mọi người thường nhầm lẫn họ.)","Although they grew up together, their opinions on politics are not [alike]. (=Dịch: Mặc dù lớn lên cùng nhau, quan điểm của họ về chính trị lại không giống nhau.)","The houses on this street are built almost completely [alike]. (=Dịch: Những ngôi nhà trên con phố này được xây dựng gần như hoàn toàn giống nhau.)"],"ukAudio":"/ai_services/tts3/?q=alike&lang=en-GB&ipa=%2F%C9%99%CB%88la%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=alike&lang=en-US&ipa=%2F%C9%99%CB%88la%C9%AAk%2F"},{"id":"lv_4_7","topic":"Cultural and Historical Exchange","word":"alley","pos":"(n)","ipa":"/ˈæl.i/","defVi":"con hẻm, ngõ nhỏ","defEn":"a narrow road or path between buildings","examples":["The children were playing football in the narrow [alley]. (=Dịch: Lũ trẻ đang chơi bóng đá trong con hẻm nhỏ hẹp.)","He parked his bicycle in a dark [alley] behind the restaurant. (=Dịch: Anh ấy đã đỗ xe đạp trong một con ngõ tối phía sau nhà hàng.)","A small [alley] connects the two main shopping streets. (=Dịch: Một con hẻm nhỏ nối liền hai con phố mua sắm chính.)"],"ukAudio":"/ai_services/tts3/?q=alley&lang=en-GB&ipa=%2F%CB%88%C3%A6l.i%2F","usAudio":"/ai_services/tts3/?q=alley&lang=en-US&ipa=%2F%CB%88%C3%A6l.i%2F"},{"id":"lv_4_8","topic":"Cultural and Historical Exchange","word":"aloud","pos":"(adv)","ipa":"/əˈlaʊd/","defVi":"thành tiếng, to","defEn":"in a voice that other people can hear","examples":["The teacher asked the student to read the passage [aloud]. (=Dịch: Giáo viên đã yêu cầu học sinh đọc to đoạn văn.)","He laughed [aloud] when he heard the unexpected joke. (=Dịch: Anh ấy đã cười thành tiếng khi nghe câu chuyện đùa bất ngờ.)","She wondered [aloud] whether it would rain later in the afternoon. (=Dịch: Cô ấy thắc mắc thành lời rằng liệu chiều nay trời có mưa không.)"],"ukAudio":"/ai_services/tts3/?q=aloud&lang=en-GB&ipa=%2F%C9%99%CB%88la%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=aloud&lang=en-US&ipa=%2F%C9%99%CB%88la%CA%8Ad%2F"},{"id":"lv_4_9","topic":"Cultural and Historical Exchange","word":"altitude","pos":"(n)","ipa":"/ˈæl.tə.tuːd/","defVi":"độ cao so với mực nước biển","defEn":"the height of an object or point in relation to sea level or ground level","examples":["The plane was flying at an [altitude] of 10,000 meters. (=Dịch: Chiếc máy bay đang bay ở độ cao 10.000 mét.)","Some climbers suffer from breathing problems at high [altitude]. (=Dịch: Một số người leo núi gặp vấn đề về hô hấp ở độ cao lớn.)","Vegetation becomes sparse as the [altitude] increases. (=Dịch: Thảm thực vật trở nên thưa thớt khi độ cao tăng lên.)"],"ukAudio":"/ai_services/tts3/?q=altitude&lang=en-GB&ipa=%2F%CB%88%C3%A6l.t%C9%99.tu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=altitude&lang=en-US&ipa=%2F%CB%88%C3%A6l.t%C9%99.tu%CB%90d%2F"},{"id":"lv_4_10","topic":"Cultural and Historical Exchange","word":"alzheimer's disease","pos":"(n)","ipa":"/ˈɑːlts.haɪ.mɚz dɪˌziz/","defVi":"bệnh Alzheimer (chứng sa sút trí tuệ)","defEn":"a progressive brain disorder that slowly destroys memory and thinking skills","examples":["Early diagnosis of [Alzheimer's disease] can help patients manage symptoms more effectively. (=Dịch: Chẩn đoán sớm bệnh Alzheimer có thể giúp người bệnh kiểm soát các triệu chứng hiệu quả hơn.)","Scientists are conducting extensive research to find a cure for [Alzheimer's disease]. (=Dịch: Các nhà khoa học đang tiến hành nghiên cứu sâu rộng để tìm ra phương pháp chữa trị bệnh Alzheimer.)","Caring for a relative with [Alzheimer's disease] requires immense patience and emotional support. (=Dịch: Việc chăm sóc một người thân mắc bệnh Alzheimer đòi hỏi sự kiên nhẫn vô cùng lớn và sự hỗ trợ về mặt tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=alzheimer%27s+disease&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90lts.ha%C9%AA.m%C9%9Az+d%C9%AA%CB%8Cziz%2F","usAudio":"/ai_services/tts3/?q=alzheimer%27s+disease&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90lts.ha%C9%AA.m%C9%9Az+d%C9%AA%CB%8Cziz%2F"},{"id":"lv_4_11","topic":"Cultural and Historical Exchange","word":"ancestor","pos":"(n)","ipa":"/ˈæn.ses.tɚ/","defVi":"tổ tiên","defEn":"a person related to you who lived a long time ago","examples":["Her [ancestor] came to America from Ireland in the nineteenth century. (=Dịch: Tổ tiên của cô ấy đã đến Mỹ từ Ireland vào thế kỷ 19.)","Many ancient cultures held ceremonies to honor every [ancestor] in their family line. (=Dịch: Nhiều nền văn hóa cổ đại đã tổ chức các nghi lễ để tôn vinh từng tổ tiên trong dòng dõi gia đình của họ.)","Scientists can trace the common [ancestor] of modern birds back to dinosaurs. (=Dịch: Các nhà khoa học có thể lần theo tổ tiên chung của các loài chim hiện đại bắt nguồn từ khủng long.)"],"ukAudio":"/ai_services/tts3/?q=ancestor&lang=en-GB&ipa=%2F%CB%88%C3%A6n.ses.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ancestor&lang=en-US&ipa=%2F%CB%88%C3%A6n.ses.t%C9%9A%2F"},{"id":"lv_4_12","topic":"Cultural and Historical Exchange","word":"angle","pos":"(n)","ipa":"/ˈæŋ.ɡəl/","defVi":"góc, góc độ","defEn":"the space between two intersecting lines, or a particular way of looking at something","examples":["The photographer took the picture from a low [angle]. (=Dịch: Nhiếp ảnh gia đã chụp bức ảnh từ một góc máy thấp.)","A square has four corners that meet at a right [angle]. (=Dịch: Hình vuông có bốn góc gặp nhau tạo thành góc vuông.)","Let's consider the problem from a different [angle]. (=Dịch: Chúng ta hãy xem xét vấn đề này từ một góc độ khác.)"],"ukAudio":"/ai_services/tts3/?q=angle&lang=en-GB&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=angle&lang=en-US&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F"},{"id":"lv_4_13","topic":"Cultural and Historical Exchange","word":"anxiety","pos":"(n)","ipa":"/æŋˈzaɪ.ə.ti/","defVi":"sự lo âu, mối lo ngại","defEn":"an uncomfortable feeling of nervousness or worry about something that might happen","examples":["Waiting for the exam results caused her a lot of [anxiety]. (=Dịch: Việc chờ đợi kết quả thi đã khiến cô ấy vô cùng lo lắng.)","Deep breathing exercises can help reduce stress and [anxiety]. (=Dịch: Các bài tập hít thở sâu có thể giúp giảm căng thẳng và lo âu.)","There is growing public [anxiety] over rising fuel prices. (=Dịch: Dư luận ngày càng lo ngại về tình trạng giá nhiên liệu tăng cao.)"],"ukAudio":"/ai_services/tts3/?q=anxiety&lang=en-GB&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.ti%2F","usAudio":"/ai_services/tts3/?q=anxiety&lang=en-US&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.ti%2F"},{"id":"lv_4_14","topic":"Cultural and Historical Exchange","word":"apron","pos":"(n)","ipa":"/ˈeɪ.prən/","defVi":"tạp dề","defEn":"a piece of clothing worn over the front of the body to keep clothes clean while cooking or working","examples":["She tied a cotton [apron] around her waist before preparing dinner. (=Dịch: Cô ấy buộc một chiếc tạp dề cotton quanh eo trước khi chuẩn bị bữa tối.)","The chef wore a clean white [apron] in the kitchen. (=Dịch: Người đầu bếp đeo một chiếc tạp dề trắng sạch sẽ trong bếp.)","He wiped his floury hands on his [apron] while baking bread. (=Dịch: Anh ấy lau đôi tay dính đầy bột vào tạp dề trong khi nướng bánh mì.)"],"ukAudio":"/ai_services/tts3/?q=apron&lang=en-GB&ipa=%2F%CB%88e%C9%AA.pr%C9%99n%2F","usAudio":"/ai_services/tts3/?q=apron&lang=en-US&ipa=%2F%CB%88e%C9%AA.pr%C9%99n%2F"},{"id":"lv_4_15","topic":"Cultural and Historical Exchange","word":"arab","pos":"(adj)","ipa":"/ˈær.əb/","defVi":"(thuộc) người Ả Rập hoặc các nước Ả Rập","defEn":"relating to the Arabic-speaking people or countries of the Middle East and North Africa","examples":["They are studying the history of the [Arab] world in the medieval era. (=Dịch: Họ đang nghiên cứu lịch sử của thế giới Ả Rập trong thời kỳ trung cổ.)","Traditional [Arab] hospitality is well known around the world. (=Dịch: Lòng hiếu khách truyền thống của người Ả Rập rất nổi tiếng trên toàn thế giới.)","Several [Arab] nations participated in the international trade conference. (=Dịch: Một số quốc gia Ả Rập đã tham gia hội nghị thương mại quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=arab&lang=en-GB&ipa=%2F%CB%88%C3%A6r.%C9%99b%2F","usAudio":"/ai_services/tts3/?q=arab&lang=en-US&ipa=%2F%CB%88%C3%A6r.%C9%99b%2F"},{"id":"lv_4_16","topic":"Cultural and Historical Exchange","word":"archaeologist","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒɪst/","defVi":"nhà khảo cổ học","defEn":"a scientist who studies human history by digging up old buildings and objects","examples":["The [archaeologist] discovered ancient pottery during the excavation. (=Dịch: Nhà khảo cổ học đã phát hiện ra đồ gốm cổ trong quá trình khai quật.)","A team of [archaeologist] specialists is exploring the lost city. (=Dịch: Một nhóm chuyên gia khảo cổ học đang khám phá thành phố bị lãng quên.)","The [archaeologist] carefully brushed dirt away from the fragile bone. (=Dịch: Nhà khảo cổ học cẩn thận quét sạch bụi đất khỏi khúc xương mỏng manh.)"],"ukAudio":"/ai_services/tts3/?q=archaeologist&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=archaeologist&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F"},{"id":"lv_4_17","topic":"Cultural and Historical Exchange","word":"archaeology","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒi/","defVi":"khảo cổ học","defEn":"the study of human history and prehistory through the excavation of sites and artifacts","examples":["She decided to study [archaeology] at university to uncover ancient civilizations. (=Dịch: Cô quyết định theo học ngành khảo cổ học tại trường đại học để khám phá các nền văn minh cổ đại.)","Recent advances in technology have revolutionized modern [archaeology]. (=Dịch: Những tiến bộ gần đây trong công nghệ đã tạo ra một cuộc cách mạng cho ngành khảo cổ học hiện đại.)","The team used aerial photography to assist their work in [archaeology]. (=Dịch: Nhóm nghiên cứu đã sử dụng kỹ thuật chụp ảnh từ trên không để hỗ trợ công việc khảo cổ học của họ.)"],"ukAudio":"/ai_services/tts3/?q=archaeology&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=archaeology&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_4_18","topic":"Cultural and Historical Exchange","word":"arena","pos":"(n)","ipa":"/əˈriː.nə/","defVi":"đấu trường, nhà thi đấu; vũ đài/lĩnh vực hoạt động","defEn":"a large enclosed area used for sports, concerts, or other public events; an area of activity","examples":["Thousands of fans gathered in the sports [arena] to watch the game. (=Dịch: Hàng nghìn người hâm mộ đã tụ tập tại nhà thi đấu thể thao để theo dõi trận đấu.)","The rock band will perform at a famous indoor [arena] tonight. (=Dịch: Ban nhạc rock sẽ biểu diễn tại một nhà thi đấu trong nhà nổi tiếng vào tối nay.)","He decided to enter the political [arena] after years in business. (=Dịch: Ông ấy quyết định bước vào chính trường sau nhiều năm làm kinh doanh.)"],"ukAudio":"/ai_services/tts3/?q=arena&lang=en-GB&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=arena&lang=en-US&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F"},{"id":"lv_4_19","topic":"Cultural and Historical Exchange","word":"artefact","pos":"(n)","ipa":"/ˈɑːr.t̬ə.fækt/","defVi":"cổ vật, đồ tạo tác","defEn":"an object made by a human being, typically of historical or cultural interest","examples":["The museum displays an ancient Egyptian [artefact] discovered in a tomb. (=Dịch: Bảo tàng trưng bày một cổ vật Ai Cập cổ đại được phát hiện trong một lăng mộ.)","Archaeologists carefully cleaned the ceramic [artefact] found at the dig site. (=Dịch: Các nhà khảo cổ học đã cẩn thận làm sạch món đồ tạo tác bằng gốm được tìm thấy tại địa điểm khai quật.)","Each bronze [artefact] provides valuable clues about how early humans lived. (=Dịch: Mỗi hiện vật bằng đồng đều cung cấp những manh mối quý giá về cách người tiền sử sinh sống.)"],"ukAudio":"/ai_services/tts3/?q=artefact&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90r.t%CC%AC%C9%99.f%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=artefact&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90r.t%CC%AC%C9%99.f%C3%A6kt%2F"},{"id":"lv_4_20","topic":"Cultural and Historical Exchange","word":"artistic","pos":"(adj)","ipa":"/ɑːrˈtɪs.tɪk/","defVi":"(thuộc) nghệ thuật; có khiếu thẩm mỹ","defEn":"connected with art or showing skill in creating art","examples":["She has exceptional [artistic] talent and loves painting landscapes. (=Dịch: Cô ấy có tài năng nghệ thuật đặc biệt và rất thích vẽ tranh phong cảnh.)","The movie was praised more for its [artistic] value than its commercial success. (=Dịch: Bộ phim được ca ngợi nhiều hơn về giá trị nghệ thuật hơn là thành công về mặt thương mại.)","He made an [artistic] decision to shoot the entire film in black and white. (=Dịch: Anh ấy đã đưa ra một quyết định mang tính nghệ thuật khi quay toàn bộ bộ phim bằng hai màu đen trắng.)"],"ukAudio":"/ai_services/tts3/?q=artistic&lang=en-GB&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=artistic&lang=en-US&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_21","topic":"Cultural and Historical Exchange","word":"artwork","pos":"(n)","ipa":"/ˈɑːrt.wɜːrk/","defVi":"tác phẩm nghệ thuật","defEn":"paintings, sculptures, or other artistic objects created for exhibition or appreciation","examples":["The gallery exhibits original [artwork] by local contemporary artists. (=Dịch: Phòng trưng bày triển lãm các tác phẩm nghệ thuật nguyên bản của các nghệ sĩ đương đại địa phương.)","Direct sunlight can cause severe damage to delicate [artwork]. (=Dịch: Ánh nắng trực tiếp có thể gây hư hại nghiêm trọng cho các tác phẩm nghệ thuật tinh xảo.)","The school cafeteria was decorated with colorful student [artwork]. (=Dịch: Nhà ăn của trường được trang trí bằng các tác phẩm nghệ thuật đầy màu sắc của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=artwork&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90rt.w%C9%9C%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=artwork&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90rt.w%C9%9C%CB%90rk%2F"},{"id":"lv_4_22","topic":"Cultural and Historical Exchange","word":"ash","pos":"(n)","ipa":"/æʃ/","defVi":"tro, tàn tro","defEn":"the grey or black powder that remains after something has burned","examples":["The volcano erupted, covering the surrounding towns in thick [ash]. (=Dịch: Núi lửa phun trào, phủ một lớp tro dày đặc lên các thị trấn xung quanh.)","He cleared the cold [ash] from the fireplace before lighting a new fire. (=Dịch: Anh ấy đã dọn sạch tàn tro nguội khỏi lò sưởi trước khi nhóm ngọn lửa mới.)","The forest fire reduced hundreds of ancient trees to [ash]. (=Dịch: Vụ cháy rừng đã thiêu rụi hàng trăm cây cổ thụ thành tro bụi.)"],"ukAudio":"/ai_services/tts3/?q=ash&lang=en-GB&ipa=%2F%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=ash&lang=en-US&ipa=%2F%C3%A6%CA%83%2F"},{"id":"lv_4_23","topic":"Cultural and Historical Exchange","word":"association","pos":"(n)","ipa":"/əˌsoʊ.siˈeɪ.ʃən/","defVi":"hiệp hội, tổ chức; sự liên kết, mối liên tưởng","defEn":"an official group of people organized for a particular purpose; a connection between ideas","examples":["He joined the local football [association] to improve his refereeing skills. (=Dịch: Anh ấy đã tham gia hiệp hội bóng đá địa phương để nâng cao kỹ năng trọng tài của mình.)","The research showed a clear [association] between poor diet and heart disease. (=Dịch: Nghiên cứu đã chỉ ra mối liên hệ rõ ràng giữa chế độ ăn uống kém và bệnh tim.)","The medical [association] published new safety guidelines for hospitals. (=Dịch: Hiệp hội y khoa đã công bố các hướng dẫn an toàn mới cho các bệnh viện.)"],"ukAudio":"/ai_services/tts3/?q=association&lang=en-GB&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=association&lang=en-US&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_24","topic":"Cultural and Historical Exchange","word":"atmospheric","pos":"(adj)","ipa":"/ˌæt.məsˈfer.ɪk/","defVi":"mang lại bầu không khí đặc biệt (huyền ảo, ấm cúng); thuộc về khí quyển","defEn":"creating an exciting, mysterious, or pleasant mood; relating to the earth's atmosphere","examples":["The dimly lit restaurant created a very [atmospheric] dining experience. (=Dịch: Nhà hàng với ánh sáng mờ ảo đã tạo nên một trải nghiệm dùng bữa vô cùng giàu bầu không khí và ấn tượng.)","Scientists are studying [atmospheric] pollution to understand climate change better. (=Dịch: Các nhà khoa học đang nghiên cứu về ô nhiễm khí quyển để hiểu rõ hơn về biến đổi khí hậu.)","The old castle looked particularly [atmospheric] on a foggy autumn morning. (=Dịch: Tòa lâu đài cổ kính trông đặc biệt huyền ảo và lôi cuốn vào một buổi sáng mùa thu nhiều sương mù.)"],"ukAudio":"/ai_services/tts3/?q=atmospheric&lang=en-GB&ipa=%2F%CB%8C%C3%A6t.m%C9%99s%CB%88fer.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=atmospheric&lang=en-US&ipa=%2F%CB%8C%C3%A6t.m%C9%99s%CB%88fer.%C9%AAk%2F"},{"id":"lv_4_25","topic":"Cultural and Historical Exchange","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"sức hút, sự hấp dẫn; điểm tham quan","defEn":"a feature or quality that makes something interesting or enjoyable, or a place people visit for pleasure","examples":["The ancient castle is the main tourist [attraction] in the region. (=Dịch: Tòa lâu đài cổ kính là điểm thu hút khách du lịch chính trong khu vực.)","The city offers many cultural [attractions] such as museums and art galleries. (=Dịch: Thành phố mang đến nhiều điểm đến văn hóa hấp dẫn như các viện bảo tàng và phòng trưng bày nghệ thuật.)","Part of the [attraction] of living in a small town is the peaceful atmosphere. (=Dịch: Một phần sức hút của việc sống ở một thị trấn nhỏ là bầu không khí yên bình.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_4_26","topic":"Cultural and Historical Exchange","word":"audio","pos":"(n)","ipa":"/ˈɔ.di.oʊ/","defVi":"âm thanh, bản ghi âm","defEn":"sound that is recorded, transmitted, or reproduced","examples":["The video quality is excellent, but the [audio] is hard to hear. (=Dịch: Chất lượng video rất tuyệt vời, nhưng âm thanh thì khó nghe.)","Students can download the [audio] files to practice their listening skills. (=Dịch: Học sinh có thể tải xuống các tệp âm thanh để luyện tập kỹ năng nghe của mình.)","The podcast offers clear [audio] and engaging discussions on science. (=Dịch: Tập podcast này mang đến âm thanh rõ ràng và các cuộc thảo luận hấp dẫn về khoa học.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%94.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%94.di.o%CA%8A%2F"},{"id":"lv_4_27","topic":"Cultural and Historical Exchange","word":"axe","pos":"(n)","ipa":"/æks/","defVi":"cây rìu","defEn":"a heavy tool with a sharp metal blade used for chopping wood","examples":["He used a sharp [axe] to chop firewood for the cold winter night. (=Dịch: Anh ấy dùng một chiếc rìu sắc bén để bổ củi cho đêm mùa đông lạnh giá.)","The lumberjack carried a heavy [axe] on his shoulder into the forest. (=Dịch: Người tiều phu vác một chiếc rìu nặng trên vai bước vào rừng.)","The firefighter broke down the locked door using a sturdy [axe]. (=Dịch: Người lính cứu hỏa đã phá cánh cửa bị khóa bằng một chiếc rìu chắc chắn.)"],"ukAudio":"/ai_services/tts3/?q=axe&lang=en-GB&ipa=%2F%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=axe&lang=en-US&ipa=%2F%C3%A6ks%2F"},{"id":"lv_4_28","topic":"Cultural and Historical Exchange","word":"basement","pos":"(n)","ipa":"/ˈbeɪs.mənt/","defVi":"tầng hầm","defEn":"a room or floor of a building partly or entirely below ground level","examples":["We converted the [basement] into a home gym. (=Dịch: Chúng tôi đã cải tạo tầng hầm thành một phòng tập thể dục tại nhà.)","Heavy rain caused water to seep into the [basement]. (=Dịch: Mưa lớn đã khiến nước rò rỉ vào tầng hầm.)","The old books are stored in boxes down in the [basement]. (=Dịch: Những cuốn sách cũ được cất trong các thùng dưới tầng hầm.)"],"ukAudio":"/ai_services/tts3/?q=basement&lang=en-GB&ipa=%2F%CB%88be%C9%AAs.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=basement&lang=en-US&ipa=%2F%CB%88be%C9%AAs.m%C9%99nt%2F"},{"id":"lv_4_29","topic":"Cultural and Historical Exchange","word":"basket","pos":"(n)","ipa":"/ˈbæs.kɪt/","defVi":"cái giỏ, cái rổ","defEn":"a container made of woven material, plastic, or wire, used for carrying things","examples":["She placed freshly picked strawberries into a small wicker [basket]. (=Dịch: Cô ấy đặt những quả dâu tây mới hái vào một chiếc giỏ đan bằng liễu gai nhỏ.)","He put his dirty laundry into the [basket] in the bathroom. (=Dịch: Anh ấy cho quần áo bẩn vào giỏ trong phòng tắm.)","You can add items to your online shopping [basket] before checking out. (=Dịch: Bạn có thể thêm các món đồ vào giỏ mua hàng trực tuyến trước khi thanh toán.)"],"ukAudio":"/ai_services/tts3/?q=basket&lang=en-GB&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=basket&lang=en-US&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F"},{"id":"lv_4_30","topic":"Cultural and Historical Exchange","word":"bathing","pos":"(n)","ipa":"/ˈbeɪ.ðɪŋ/","defVi":"việc tắm rửa, sự bơi lội","defEn":"the act of washing the body or swimming in a body of water for pleasure","examples":["In ancient Rome, public [bathing] was an important social activity. (=Dịch: Ở La Mã cổ đại, việc tắm rửa công cộng là một hoạt động xã hội quan trọng.)","The lake is not safe for [bathing] because of strong underwater currents. (=Dịch: Hồ nước này không an toàn để tắm do có các dòng chảy ngầm mạnh.)","A warm [bathing] ritual before bedtime can help improve sleep quality. (=Dịch: Thói quen tắm nước ấm trước khi đi ngủ có thể giúp cải thiện chất lượng giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=bathing&lang=en-GB&ipa=%2F%CB%88be%C9%AA.%C3%B0%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=bathing&lang=en-US&ipa=%2F%CB%88be%C9%AA.%C3%B0%C9%AA%C5%8B%2F"},{"id":"lv_4_31","topic":"Cultural and Historical Exchange","word":"bc","pos":"(adv)","ipa":"/ˌbiː ˈsiː/","defVi":"trước Công nguyên (TCN)","defEn":"abbreviation for 'Before Christ', used to refer to dates before the approximate birth of Jesus Christ","examples":["The ancient temple was constructed around the fifth century [BC]. (=Dịch: Ngôi đền cổ được xây dựng vào khoảng thế kỷ thứ năm trước Công nguyên.)","Historians estimate that the city was founded in 753 [BC]. (=Dịch: Các nhà sử học ước tính rằng thành phố được thành lập vào năm 753 trước Công nguyên.)","Trade routes between the civilizations were already active by 2000 [BC]. (=Dịch: Các tuyến đường thương mại giữa các nền văn minh đã hoạt động tích cực vào năm 2000 trước Công nguyên.)"],"ukAudio":"/ai_services/tts3/?q=bc&lang=en-GB&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F","usAudio":"/ai_services/tts3/?q=bc&lang=en-US&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F"},{"id":"lv_4_32","topic":"Cultural and Historical Exchange","word":"belief","pos":"(n)","ipa":"/bɪˈlif/","defVi":"niềm tin, tín ngưỡng","defEn":"an acceptance that a statement is true or that something exists","examples":["His strong [belief] in justice motivated him to pursue a career in law. (=Dịch: Niềm tin mãnh liệt vào công lý đã thúc đẩy anh ấy theo đuổi sự nghiệp trong ngành luật.)","It is a widely held [belief] that a balanced diet leads to a healthier life. (=Dịch: Nhiều người tin rằng một chế độ ăn uống cân bằng sẽ mang lại một cuộc sống khỏe mạnh hơn.)","Different cultures have their own set of moral values and religious [belief]. (=Dịch: Các nền văn hóa khác nhau có những hệ giá trị đạo đức và đức tin tôn giáo riêng.)"],"ukAudio":"/ai_services/tts3/?q=belief&lang=en-GB&ipa=%2Fb%C9%AA%CB%88lif%2F","usAudio":"/ai_services/tts3/?q=belief&lang=en-US&ipa=%2Fb%C9%AA%CB%88lif%2F"},{"id":"lv_4_33","topic":"Cultural and Historical Exchange","word":"beneath","pos":"(prep)","ipa":"/bɪˈniːθ/","defVi":"ở bên dưới, dưới","defEn":"in or to a lower position than; directly under","examples":["The cat curled up and fell asleep [beneath] the kitchen table. (=Dịch: Con mèo cuộn tròn và ngủ thiếp đi bên dưới gầm bàn bếp.)","A vast network of tunnels lies [beneath] the bustling streets of the city. (=Dịch: Một mạng lưới đường hầm rộng lớn nằm bên dưới những con phố nhộn nhịp của thành phố.)","She hid the secret letter [beneath] a thick stack of old books. (=Dịch: Cô ấy đã giấu bức thư bí mật bên dưới một chồng sách cũ dày cộm.)"],"ukAudio":"/ai_services/tts3/?q=beneath&lang=en-GB&ipa=%2Fb%C9%AA%CB%88ni%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=beneath&lang=en-US&ipa=%2Fb%C9%AA%CB%88ni%CB%90%CE%B8%2F"},{"id":"lv_4_34","topic":"Cultural and Historical Exchange","word":"bet","pos":"(n)","ipa":"/bɛt/","defVi":"tiền cược, vụ cá cược","defEn":"an agreement to risk money on the unknown result of an event","examples":["He placed a ten-dollar [bet] on his favorite football team. (=Dịch: Anh ấy đã đặt cược mười đô la vào đội bóng đá yêu thích của mình.)","Winning the [bet] gave him enough money to pay for dinner. (=Dịch: Thắng cược đã giúp anh ấy có đủ tiền để trả cho bữa tối.)","They made a friendly [bet] on who could finish the race first. (=Dịch: Họ đã cá cược vui xem ai có thể về đích trước.)"],"ukAudio":"/ai_services/tts3/?q=bet&lang=en-GB&ipa=%2Fb%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=bet&lang=en-US&ipa=%2Fb%C9%9Bt%2F"},{"id":"lv_4_35","topic":"Cultural and Historical Exchange","word":"bicentennial","pos":"(n)","ipa":"/ˌbaɪ.sɛnˈtɛn.i.əl/","defVi":"lễ kỷ niệm hai trăm năm","defEn":"the two-hundredth anniversary of a significant event, or its celebration","examples":["The city planned a massive parade to mark its [bicentennial] celebration. (=Dịch: Thành phố đã lên kế hoạch cho một cuộc diễu hành lớn để đánh dấu lễ kỷ niệm 200 năm thành lập.)","A commemorative coin was issued for the nation's [bicentennial]. (=Dịch: Một đồng xu kỷ niệm đã được phát hành nhân dịp lễ kỷ niệm 200 năm của quốc gia.)","Historians gathered to discuss the historical milestones leading up to the [bicentennial]. (=Dịch: Các nhà sử học đã tập hợp để thảo luận về những cột mốc lịch sử dẫn đến lễ kỷ niệm 200 năm.)"],"ukAudio":"/ai_services/tts3/?q=bicentennial&lang=en-GB&ipa=%2F%CB%8Cba%C9%AA.s%C9%9Bn%CB%88t%C9%9Bn.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=bicentennial&lang=en-US&ipa=%2F%CB%8Cba%C9%AA.s%C9%9Bn%CB%88t%C9%9Bn.i.%C9%99l%2F"},{"id":"lv_4_36","topic":"Cultural and Historical Exchange","word":"bizarre","pos":"(adj)","ipa":"/bɪˈzɑːr/","defVi":"kỳ quái, kỳ lạ","defEn":"very strange or unusual","examples":["She wore a [bizarre] outfit to the party that made everyone stare. (=Dịch: Cô ấy đã mặc một bộ trang phục kỳ quặc đến bữa tiệc khiến mọi người phải nhìn chằm chằm.)","He had a [bizarre] dream about flying fish last night. (=Dịch: Đêm qua anh ấy đã có một giấc mơ kỳ lạ về những con cá biết bay.)","The police were baffled by the suspect's [bizarre] behavior during questioning. (=Dịch: Cảnh sát đã bối rối trước hành vi kỳ quặc của nghi phạm trong suốt quá trình thẩm vấn.)"],"ukAudio":"/ai_services/tts3/?q=bizarre&lang=en-GB&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=bizarre&lang=en-US&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F"},{"id":"lv_4_37","topic":"Cultural and Historical Exchange","word":"bleak","pos":"(adj)","ipa":"/bliːk/","defVi":"ảm đạm, hoang vắng, u ám","defEn":"cold, empty, and not welcoming; offering little or no hope","examples":["The winter landscape looked [bleak] and deserted under the grey clouds. (=Dịch: Khung cảnh mùa đông trông ảm đạm và hoang vắng dưới những đám mây xám xịt.)","The economic outlook for the upcoming year remains rather [bleak]. (=Dịch: Triển vọng kinh tế cho năm sắp tới vẫn còn khá ảm đạm.)","Without proper qualifications, his chances of finding a job are [bleak]. (=Dịch: Nếu không có trình độ chuyên môn phù hợp, cơ hội tìm việc của anh ấy là vô cùng mờ mịt.)"],"ukAudio":"/ai_services/tts3/?q=bleak&lang=en-GB&ipa=%2Fbli%CB%90k%2F","usAudio":"/ai_services/tts3/?q=bleak&lang=en-US&ipa=%2Fbli%CB%90k%2F"},{"id":"lv_4_38","topic":"Cultural and Historical Exchange","word":"bog","pos":"(n)","ipa":"/bɑːɡ/","defVi":"đầm lầy, bãi than bùn","defEn":"an area of soft, wet, muddy ground that is difficult to walk on","examples":["The rare bird species builds its nests in the remote wetlands of the peat [bog]. (=Dịch: Loài chim quý hiếm làm tổ ở những vùng đất ngập nước hẻo lánh của đầm lầy than bùn.)","Heavy machinery sank into the muddy [bog] and had to be pulled out with cables. (=Dịch: Máy móc hạng nặng bị chìm vào đầm lầy bùn lầy và phải được kéo ra bằng dây cáp.)","Scientists analyze ancient plant remains preserved in the acidic layers of the [bog]. (=Dịch: Các nhà khoa học phân tích tàn tích thực vật cổ đại được bảo tồn trong các lớp đất có tính axit của đầm lầy.)"],"ukAudio":"/ai_services/tts3/?q=bog&lang=en-GB&ipa=%2Fb%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=bog&lang=en-US&ipa=%2Fb%C9%91%CB%90%C9%A1%2F"},{"id":"lv_4_39","topic":"Cultural and Historical Exchange","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, tiệm sách","defEn":"a shop that sells books","examples":["I spent hours browsing through old novels in the local [bookshop]. (=Dịch: Tôi đã dành hàng giờ để tìm đọc những cuốn tiểu thuyết cũ trong hiệu sách địa phương.)","The university [bookshop] offers a discount on required textbooks. (=Dịch: Hiệu sách của trường đại học giảm giá cho các sách giáo trình bắt buộc.)","A cozy [bookshop] recently opened around the corner from our school. (=Dịch: Một hiệu sách ấm cúng vừa mới mở ngay góc phố gần trường học của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_4_40","topic":"Cultural and Historical Exchange","word":"brazil","pos":"(n)","ipa":"/brəˈzɪl/","defVi":"nước Bra-xin (quốc gia ở Nam Mỹ)","defEn":"the largest country in South America, known for the Amazon Rainforest and vibrant culture","examples":["[Brazil] is the world's largest producer and exporter of coffee. (=Dịch: Brazil là quốc gia sản xuất và xuất khẩu cà phê lớn nhất thế giới.)","Thousands of tourists travel to [Brazil] every year to experience the Rio Carnival. (=Dịch: Hàng ngàn du khách đến Brazil mỗi năm để trải nghiệm Lễ hội hóa trang Rio Carnival.)","A large portion of the Amazon rainforest is located within [Brazil]. (=Dịch: Phần lớn rừng nhiệt đới Amazon nằm trong lãnh thổ Brazil.)"],"ukAudio":"/ai_services/tts3/?q=brazil&lang=en-GB&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=brazil&lang=en-US&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F"},{"id":"lv_4_41","topic":"Cultural and Historical Exchange","word":"breathe","pos":"(v)","ipa":"/brið/","defVi":"thở, hít thở","defEn":"to take air into the lungs and expel it again","examples":["It is important to [breathe] deeply when you feel stressed or anxious. (=Dịch: Điều quan trọng là phải hít thở sâu khi bạn cảm thấy căng thẳng hoặc lo âu.)","He could hardly [breathe] after running up five flights of stairs. (=Dịch: Anh ấy gần như không thể thở nổi sau khi chạy lên năm tầng cầu thang.)","The doctor told the patient to [breathe] normally during the examination. (=Dịch: Bác sĩ bảo bệnh nhân thở bình thường trong quá trình thăm khám.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2Fbri%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2Fbri%C3%B0%2F"},{"id":"lv_4_42","topic":"Cultural and Historical Exchange","word":"broadcaster","pos":"(n)","ipa":"/ˈbrɔd.kæs.tɚ/","defVi":"phát thanh viên, đài truyền hình/phát thanh","defEn":"a person or company that transmits radio or television programs","examples":["The national [broadcaster] announced changes to its evening schedule. (=Dịch: Đài truyền hình quốc gia đã thông báo những thay đổi đối với lịch phát sóng buổi tối.)","She started her career as a sports [broadcaster] for a local radio station. (=Dịch: Cô bắt đầu sự nghiệp của mình với tư cách là một phát thanh viên thể thao cho một đài phát thanh địa phương.)","Several international [broadcaster] organizations covered the global summit. (=Dịch: Một số tổ chức phát thanh truyền hình quốc tế đã đưa tin về hội nghị thượng đỉnh toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=broadcaster&lang=en-GB&ipa=%2F%CB%88br%C9%94d.k%C3%A6s.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=broadcaster&lang=en-US&ipa=%2F%CB%88br%C9%94d.k%C3%A6s.t%C9%9A%2F"},{"id":"lv_4_43","topic":"Cultural and Historical Exchange","word":"bury","pos":"(v)","ipa":"/ˈber.i/","defVi":"chôn cất, vùi lấp","defEn":"to place something in the ground and cover it with earth","examples":["Pirates used to [bury] their stolen treasure on remote islands. (=Dịch: Những tên cướp biển từng chôn giấu kho báu đánh cắp được trên các hòn đảo xa xôi.)","The winter storm managed to [bury] the entire town under two feet of snow. (=Dịch: Cơn bão mùa đông đã vùi lấp cả thị trấn dưới hai foot tuyết.)","When feeling stressed, she prefers to [bury] herself in work to stay focused. (=Dịch: Khi cảm thấy căng thẳng, cô ấy muốn vùi mình vào công việc để giữ sự tập trung.)"],"ukAudio":"/ai_services/tts3/?q=bury&lang=en-GB&ipa=%2F%CB%88ber.i%2F","usAudio":"/ai_services/tts3/?q=bury&lang=en-US&ipa=%2F%CB%88ber.i%2F"},{"id":"lv_4_44","topic":"Cultural and Historical Exchange","word":"bush","pos":"(n)","ipa":"/bʊʃ/","defVi":"bụi cây, bụi rậm","defEn":"a low, woody plant with many branches, smaller than a tree","examples":["The children were hiding behind a large rose [bush] in the backyard. (=Dịch: Lũ trẻ đang trốn sau một bụi hoa hồng lớn ở sân sau.)","He planted a flowering [bush] near the front gate to brighten the house. (=Dịch: Anh ấy đã trồng một bụi cây có hoa gần cổng trước để làm rạng rỡ ngôi nhà.)","A small bird suddenly flew out from the thorny [bush]. (=Dịch: Một chú chim nhỏ bất ngờ bay ra từ bụi cây đầy gai.)"],"ukAudio":"/ai_services/tts3/?q=bush&lang=en-GB&ipa=%2Fb%CA%8A%CA%83%2F","usAudio":"/ai_services/tts3/?q=bush&lang=en-US&ipa=%2Fb%CA%8A%CA%83%2F"},{"id":"lv_4_45","topic":"Cultural and Historical Exchange","word":"calendar","pos":"(n)","ipa":"/ˈkæl.ən.dɚ/","defVi":"lịch, cuốn lịch","defEn":"a chart or page showing the days, weeks, and months of a particular year","examples":["I marked the date of the interview on my [calendar]. (=Dịch: Tôi đã đánh dấu ngày phỏng vấn trên lịch của mình.)","The academic [calendar] lists all term dates and exam periods. (=Dịch: Lịch học tập liệt kê tất cả các ngày trong học kỳ và các kỳ thi.)","She hung a new wall [calendar] in her office. (=Dịch: Cô ấy đã treo một cuốn lịch tường mới trong văn phòng của mình.)"],"ukAudio":"/ai_services/tts3/?q=calendar&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=calendar&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F"},{"id":"lv_4_46","topic":"Cultural and Historical Exchange","word":"calm","pos":"(adj)","ipa":"/kɑːm/","defVi":"bình tĩnh, êm đềm","defEn":"peaceful, quiet, and not worried or excited","examples":["Try to stay [calm] during an emergency situation. (=Dịch: Hãy cố gắng giữ bình tĩnh trong các tình huống khẩn cấp.)","The sea was completely [calm] without a single wave. (=Dịch: Biển hoàn toàn êm ả, không có lấy một gợn sóng.)","Her [calm] voice helped reassure the frightened child. (=Dịch: Giọng nói điềm tĩnh của cô đã giúp trấn an đứa trẻ đang sợ hãi.)"],"ukAudio":"/ai_services/tts3/?q=calm&lang=en-GB&ipa=%2Fk%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=calm&lang=en-US&ipa=%2Fk%C9%91%CB%90m%2F"},{"id":"lv_4_47","topic":"Cultural and Historical Exchange","word":"canal","pos":"(n)","ipa":"/kəˈnæl/","defVi":"kênh đào, con kênh","defEn":"an artificial waterway constructed for navigation or irrigation","examples":["The Panama [Canal] significantly reduces the travel time for international cargo ships. (=Dịch: Kênh đào Panama giúp giảm đáng kể thời gian di chuyển của các tàu chở hàng quốc tế.)","Tourists enjoy taking boat tours along the narrow [canals] of the historic city. (=Dịch: Khách du lịch thích thú tham gia các chuyến tham quan bằng thuyền dọc theo những con kênh hẹp của thành phố lịch sử.)","The government built an irrigation [canal] to supply water to dry farmland. (=Dịch: Chính phủ đã xây dựng một con kênh tưới tiêu để cung cấp nước cho vùng đất nông nghiệp khô cằn.)"],"ukAudio":"/ai_services/tts3/?q=canal&lang=en-GB&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=canal&lang=en-US&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_4_48","topic":"Cultural and Historical Exchange","word":"capitalism","pos":"(n)","ipa":"/ˈkæp.ə.t̬əl.ɪ.zəm/","defVi":"chủ nghĩa tư bản","defEn":"an economic system in which businesses and property are owned by private individuals rather than the state","examples":["Free market [capitalism] encourages competition among private enterprises. (=Dịch: Chủ nghĩa tư bản thị trường tự do khuyến khích sự cạnh tranh giữa các doanh nghiệp tư nhân.)","Critics argue that unchecked [capitalism] can widen the gap between rich and poor. (=Dịch: Các nhà phê bình lập luận rằng chủ nghĩa tư bản không được kiểm soát có thể nới rộng khoảng cách giàu nghèo.)","The Industrial Revolution accelerated the development of global [capitalism]. (=Dịch: Cách mạng Công nghiệp đã đẩy nhanh sự phát triển của chủ nghĩa tư bản toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=capitalism&lang=en-GB&ipa=%2F%CB%88k%C3%A6p.%C9%99.t%CC%AC%C9%99l.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=capitalism&lang=en-US&ipa=%2F%CB%88k%C3%A6p.%C9%99.t%CC%AC%C9%99l.%C9%AA.z%C9%99m%2F"},{"id":"lv_4_49","topic":"Cultural and Historical Exchange","word":"cargo","pos":"(n)","ipa":"/ˈkɑr.ɡoʊ/","defVi":"hàng hóa (chở bằng tàu thủy, máy bay hoặc xe tải)","defEn":"goods carried on a ship, aircraft, or motor vehicle","examples":["The plane was carrying tons of medical [cargo] to the disaster zone. (=Dịch: Chiếc máy bay đang chở hàng tấn hàng hóa y tế đến vùng xảy ra thảm họa.)","Dockworkers worked overnight to unload the container [cargo] from the ship. (=Dịch: Các công nhân cảng đã làm việc xuyên đêm để dỡ các công-ten-nơ hàng hóa khỏi tàu.)","Inspectors checked the ship’s [cargo] for illegal wildlife products. (=Dịch: Các thanh tra đã kiểm tra hàng hóa trên tàu để truy tìm các sản phẩm động vật hoang dã bất hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=cargo&lang=en-GB&ipa=%2F%CB%88k%C9%91r.%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=cargo&lang=en-US&ipa=%2F%CB%88k%C9%91r.%C9%A1o%CA%8A%2F"},{"id":"lv_4_50","topic":"Cultural and Historical Exchange","word":"caribbean","pos":"(n)","ipa":"/ˌkɛr.əˈbi.ən/","defVi":"vùng biển Ca-ri-bê","defEn":"a region consisting of the Caribbean Sea and its surrounding islands","examples":["Many tourists travel to the [Caribbean] for its warm climate and beaches. (=Dịch: Nhiều du khách đến vùng Caribe vì khí hậu ấm áp và các bãi biển đẹp.)","The cultural heritage of the [Caribbean] blends African, European, and Indigenous traditions. (=Dịch: Di sản văn hóa của vùng Caribe pha trộn giữa các truyền thống châu Phi, châu Âu và bản địa.)","Severe hurricanes often threaten island communities across the [Caribbean] each autumn. (=Dịch: Những cơn bão dữ dội thường đe dọa các cộng đồng trên đảo khắp vùng Caribe vào mỗi mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=caribbean&lang=en-GB&ipa=%2F%CB%8Ck%C9%9Br.%C9%99%CB%88bi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=caribbean&lang=en-US&ipa=%2F%CB%8Ck%C9%9Br.%C9%99%CB%88bi.%C9%99n%2F"},{"id":"lv_4_51","topic":"Cultural and Historical Exchange","word":"carnival","pos":"(n)","ipa":"/ˈkɑːr.nə.vəl/","defVi":"lễ hội hóa trang, ngày hội","defEn":"a public festival featuring music, dancing, and colorful costumes","examples":["Rio de Janeiro is world-famous for its annual vibrant [carnival]. (=Dịch: Rio de Janeiro nổi tiếng thế giới với lễ hội hóa trang rực rỡ thường niên.)","Children enjoyed dressing up in costumes for the school [carnival]. (=Dịch: Trẻ em thích thú mặc trang phục hóa trang cho ngày hội hóa trang của trường.)","Dancers practiced for months to prepare their routines for the street [carnival]. (=Dịch: Các vũ công đã luyện tập trong nhiều tháng để chuẩn bị cho các tiết mục biểu diễn tại lễ hội đường phố.)"],"ukAudio":"/ai_services/tts3/?q=carnival&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.n%C9%99.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=carnival&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.n%C9%99.v%C9%99l%2F"},{"id":"lv_4_52","topic":"Cultural and Historical Exchange","word":"carve","pos":"(v)","ipa":"/kɑːrv/","defVi":"khắc, chạm khắc, tạc","defEn":"to cut a hard material such as wood or stone into a specific shape","examples":["Local artisans [carve] beautiful statues from solid blocks of wood. (=Dịch: Các nghệ nhân địa phương chạm khắc những bức tượng tuyệt đẹp từ các khối gỗ nguyên khối.)","Tourists often [carve] their initials onto the historic wooden benches. (=Dịch: Khách du lịch thường khắc tên viết tắt của họ lên những chiếc ghế gỗ lịch sử.)","The chef will carefully [carve] the roasted turkey for dinner. (=Dịch: Bếp trưởng sẽ cẩn thận cắt thịt gà tây quay cho bữa tối.)"],"ukAudio":"/ai_services/tts3/?q=carve&lang=en-GB&ipa=%2Fk%C9%91%CB%90rv%2F","usAudio":"/ai_services/tts3/?q=carve&lang=en-US&ipa=%2Fk%C9%91%CB%90rv%2F"},{"id":"lv_4_53","topic":"Cultural and Historical Exchange","word":"carving","pos":"(n)","ipa":"/ˈkɑːr.vɪŋ/","defVi":"tác phẩm điêu khắc, họa tiết chạm khắc","defEn":"an object or design made by cutting away material from wood or stone","examples":["The museum displays an intricate wooden [carving] from the nineteenth century. (=Dịch: Bảo tàng trưng bày một tác phẩm chạm khắc gỗ tinh xảo từ thế kỷ thứ mười chín.)","Ancient stone [carvings] were discovered on the walls of the cave. (=Dịch: Những bức chạm khắc đá cổ đại đã được phát hiện trên các vách hang động.)","He bought a small jade [carving] as a souvenir during his trip. (=Dịch: Anh ấy đã mua một bức tượng ngọc điêu khắc nhỏ làm quà lưu niệm trong chuyến đi của mình.)"],"ukAudio":"/ai_services/tts3/?q=carving&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=carving&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.v%C9%AA%C5%8B%2F"},{"id":"lv_4_54","topic":"Cultural and Historical Exchange","word":"category","pos":"(n)","ipa":"/ˈkæt̬.ə.ɡɔːr.i/","defVi":"hạng, loại, danh mục","defEn":"a group of people or things that share similar characteristics","examples":["The books in the library are divided into different [category] sections. (=Dịch: Sách trong thư viện được chia thành các khu vực theo thể loại khác nhau.)","Her movie won the best picture [category] at the annual film awards. (=Dịch: Bộ phim của cô đã chiến thắng ở hạng mục phim hay nhất tại lễ trao giải điện ảnh thường niên.)","Applicants are placed into a specific [category] based on their work experience. (=Dịch: Các ứng viên được xếp vào một nhóm cụ thể dựa trên kinh nghiệm làm việc của họ.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_4_55","topic":"Cultural and Historical Exchange","word":"cattle","pos":"(n)","ipa":"/ˈkæt.əl/","defVi":"gia súc (bò, trâu)","defEn":"cows and bulls kept on a farm for their meat or milk","examples":["The farmer herds his [cattle] into the barn every evening. (=Dịch: Người nông dân lùa đàn gia súc của mình vào chuồng vào mỗi buổi tối.)","Dairy [cattle] require nutritious food to produce high quality milk. (=Dịch: Bò sữa đòi hỏi thức ăn giàu dinh dưỡng để sản xuất ra sữa chất lượng cao.)","A large herd of [cattle] was grazing quietly on the green hill. (=Dịch: Một đàn gia súc lớn đang gặm cỏ yên bình trên ngọn đồi xanh mướt.)"],"ukAudio":"/ai_services/tts3/?q=cattle&lang=en-GB&ipa=%2F%CB%88k%C3%A6t.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cattle&lang=en-US&ipa=%2F%CB%88k%C3%A6t.%C9%99l%2F"},{"id":"lv_4_56","topic":"Cultural and Historical Exchange","word":"cave","pos":"(n)","ipa":"/keɪv/","defVi":"hang động","defEn":"a large natural underground hole or hollow space in the side of a hill or cliff","examples":["The explorers discovered fascinating prehistoric wall paintings deep inside the dark [cave]. (=Dịch: Các nhà thám hiểm đã phát hiện ra những bức tranh tường tiền sử hấp dẫn nằm sâu bên trong hang động tối tăm.)","Hikers sought shelter inside a nearby [cave] when the heavy rainstorm suddenly began. (=Dịch: Những người đi bộ đường dài đã tìm nơi trú ẩn bên trong một hang động gần đó khi cơn bão mưa lớn bất ngờ ập đến.)","This coastal [cave] is only accessible by small boats during low tide. (=Dịch: Hang động ven biển này chỉ có thể tiếp cận bằng thuyền nhỏ khi thủy triều xuống.)"],"ukAudio":"/ai_services/tts3/?q=cave&lang=en-GB&ipa=%2Fke%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cave&lang=en-US&ipa=%2Fke%C9%AAv%2F"},{"id":"lv_4_57","topic":"Cultural and Historical Exchange","word":"celebration","pos":"(n)","ipa":"/ˌsɛl.əˈbreɪ.ʃən/","defVi":"sự kỷ niệm, lễ kỷ niệm, buổi tiệc mừng","defEn":"a special social event or gathering organized to mark an important occasion","examples":["The whole city joined in the [celebration] of the national holiday. (=Dịch: Cả thành phố đã cùng tham gia vào [lễ kỷ niệm] ngày quốc lễ.)","They held a big [celebration] for their parents' wedding anniversary. (=Dịch: Họ đã tổ chức một [bữa tiệc kỷ niệm] lớn nhân dịp kỷ niệm ngày cưới của cha mẹ.)","The football team organized a victory [celebration] after winning the cup. (=Dịch: Đội bóng đá đã tổ chức một [lễ ăn mừng] chiến thắng sau khi giành được cúp vô địch.)"],"ukAudio":"/ai_services/tts3/?q=celebration&lang=en-GB&ipa=%2F%CB%8Cs%C9%9Bl.%C9%99%CB%88bre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=celebration&lang=en-US&ipa=%2F%CB%8Cs%C9%9Bl.%C9%99%CB%88bre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_58","topic":"Cultural and Historical Exchange","word":"ceramic","pos":"(n)","ipa":"/səˈræm.ɪk/","defVi":"gốm sứ, đồ gốm","defEn":"a hard material made by shaping and baking clay at high temperatures","examples":["The museum exhibits a rare collection of ancient [ceramic] vases. (=Dịch: Bảo tàng trưng bày một bộ sưu tập bình gốm cổ quý hiếm.)","She bought a handmade [ceramic] mug at the local craft fair. (=Dịch: Cô ấy đã mua một chiếc cốc gốm thủ công tại hội chợ thủ công mỹ nghệ địa phương.)","Modern engineering uses [ceramic] materials because of their heat resistance. (=Dịch: Kỹ thuật hiện đại sử dụng vật liệu gốm vì khả năng chịu nhiệt của chúng.)"],"ukAudio":"/ai_services/tts3/?q=ceramic&lang=en-GB&ipa=%2Fs%C9%99%CB%88r%C3%A6m.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=ceramic&lang=en-US&ipa=%2Fs%C9%99%CB%88r%C3%A6m.%C9%AAk%2F"},{"id":"lv_4_59","topic":"Cultural and Historical Exchange","word":"cereal","pos":"(n)","ipa":"/ˈsɪr.i.əl/","defVi":"ngũ cốc","defEn":"a grain used for food, such as wheat, oats, or corn, or a breakfast food made from it","examples":["Many people eat a bowl of [cereal] with cold milk for breakfast. (=Dịch: Nhiều người ăn một bát ngũ cốc với sữa lạnh vào bữa sáng.)","Wheat and rice are the most widely grown [cereal] crops in the world. (=Dịch: Lúa mì và lúa gạo là những cây ngũ cốc được trồng rộng rãi nhất trên thế giới.)","He chose a whole-grain [cereal] to maintain a healthier diet. (=Dịch: Anh ấy đã chọn ngũ cốc nguyên hạt để duy trì một chế độ ăn uống lành mạnh hơn.)"],"ukAudio":"/ai_services/tts3/?q=cereal&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cereal&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F"},{"id":"lv_4_60","topic":"Cultural and Historical Exchange","word":"ceremony","pos":"(n)","ipa":"/ˈser.ə.moʊ.ni/","defVi":"nghi lễ, buổi lễ","defEn":"a formal public or religious event with traditional actions","examples":["The graduation [ceremony] will take place in the main hall. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại hội trường chính.)","They held a traditional wedding [ceremony] in the village. (=Dịch: Họ đã tổ chức một lễ cưới truyền thống ở trong làng.)","The opening [ceremony] of the Olympic Games was breathtaking. (=Dịch: Lễ khai mạc Thế vận hội Olympic thật ngoạn mục.)"],"ukAudio":"/ai_services/tts3/?q=ceremony&lang=en-GB&ipa=%2F%CB%88ser.%C9%99.mo%CA%8A.ni%2F","usAudio":"/ai_services/tts3/?q=ceremony&lang=en-US&ipa=%2F%CB%88ser.%C9%99.mo%CA%8A.ni%2F"},{"id":"lv_4_61","topic":"Cultural and Historical Exchange","word":"characteristic","pos":"(n)","ipa":"/ˌker.ək.təˈrɪs.tɪk/","defVi":"đặc điểm, đặc tính","defEn":"a feature or quality belonging typically to a person, place, or thing and serving to identify it","examples":["Curiosity is an important [characteristic] of a good researcher. (=Dịch: Sự tò mò là một đặc tính quan trọng của một nhà nghiên cứu giỏi.)","Large ears are a distinctive physical [characteristic] of African elephants. (=Dịch: Đôi tai lớn là một đặc điểm thể chất nổi bật của loài voi châu Phi.)","Adaptability is a key [characteristic] needed to thrive in modern workplaces. (=Dịch: Khả năng thích ứng là một đặc điểm then chốt cần có để phát triển trong môi trường làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=characteristic&lang=en-GB&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=characteristic&lang=en-US&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_62","topic":"Cultural and Historical Exchange","word":"chemist","pos":"(n)","ipa":"/ˈkɛm.ɪst/","defVi":"nhà hóa học","defEn":"a scientist who specializes in the study of chemistry","examples":["The research [chemist] developed a new compound to treat infections. (=Dịch: Nhà hóa học nghiên cứu đã phát triển một hợp chất mới để điều trị các bệnh nhiễm trùng.)","Marie Curie was a pioneering [chemist] and physicist who won two Nobel Prizes. (=Dịch: Marie Curie là một nhà hóa học và nhà vật lý tiên phong từng giành hai giải Nobel.)","Every [chemist] in the laboratory must follow strict safety procedures. (=Dịch: Mỗi nhà hóa học trong phòng thí nghiệm đều phải tuân thủ các quy trình an toàn nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=chemist&lang=en-GB&ipa=%2F%CB%88k%C9%9Bm.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=chemist&lang=en-US&ipa=%2F%CB%88k%C9%9Bm.%C9%AAst%2F"},{"id":"lv_4_63","topic":"Cultural and Historical Exchange","word":"chief","pos":"(adj)","ipa":"/tʃiːf/","defVi":"chính, chủ yếu","defEn":"most important; main","examples":["The [chief] reason for his success was his relentless hard work. (=Dịch: Lý do chính cho sự thành công của anh ấy là sự chăm chỉ không ngừng nghỉ.)","Safety is our [chief] concern during this outdoor expedition. (=Dịch: An toàn là mối quan tâm hàng đầu của chúng tôi trong suốt chuyến thám hiểm ngoài trời này.)","Pollution is one of the [chief] threats to marine life today. (=Dịch: Ô nhiễm là một trong những mối đe dọa chính đối với sinh vật biển hiện nay.)"],"ukAudio":"/ai_services/tts3/?q=chief&lang=en-GB&ipa=%2Ft%CA%83i%CB%90f%2F","usAudio":"/ai_services/tts3/?q=chief&lang=en-US&ipa=%2Ft%CA%83i%CB%90f%2F"},{"id":"lv_4_64","topic":"Cultural and Historical Exchange","word":"childhood","pos":"(n)","ipa":"/ˈtʃaɪld.hʊd/","defVi":"thời thơ ấu, tuổi thơ","defEn":"the time or period of being a child","examples":["She spent most of her [childhood] living in a peaceful coastal village. (=Dịch: Cô ấy đã dành phần lớn tuổi thơ của mình sống ở một ngôi làng ven biển yên bình.)","Playing board games with family is one of my fondest [childhood] memories. (=Dịch: Chơi trò chơi bàn cờ cùng gia đình là một trong những kỷ niệm thời thơ ấu đẹp nhất của tôi.)","Poor nutrition during early [childhood] can affect physical growth. (=Dịch: Dinh dưỡng kém trong thời thơ ấu có thể ảnh hưởng đến sự phát triển thể chất.)"],"ukAudio":"/ai_services/tts3/?q=childhood&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.h%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=childhood&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.h%CA%8Ad%2F"},{"id":"lv_4_65","topic":"Cultural and Historical Exchange","word":"china","pos":"(n)","ipa":"/ˈtʃaɪ.nə/","defVi":"Trung Quốc; đồ sứ","defEn":"a large country located in East Asia; (lowercase) cups, plates, and dishes made of porcelain","examples":["Export trade between Vietnam and [China] has grown significantly in recent years. (=Dịch: Hoạt động thương mại xuất khẩu giữa Việt Nam và Trung Quốc đã tăng trưởng đáng kể trong những năm gần đây.)","They decided to travel across [China] by high-speed train. (=Dịch: Họ quyết định đi du lịch xuyên Trung Quốc bằng tàu cao tốc.)","Many international students choose to study Mandarin in [China]. (=Dịch: Nhiều du học sinh quốc tế chọn học tiếng Quan Thoại tại Trung Quốc.)"],"ukAudio":"/ai_services/tts3/?q=china&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=china&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F"},{"id":"lv_4_66","topic":"Cultural and Historical Exchange","word":"chinese","pos":"(adj)","ipa":"/ˌtʃaɪˈniːz/","defVi":"thuộc về Trung Quốc, người Trung Quốc hoặc tiếng Trung","defEn":"relating to China, its people, or its language","examples":["She has a deep interest in traditional [Chinese] painting and calligraphy. (=Dịch: Cô ấy có niềm đam mê sâu sắc với hội họa và thư pháp truyền thống Trung Quốc.)","Many students are learning the [Chinese] language for career opportunities. (=Dịch: Nhiều sinh viên đang học tiếng Trung Quốc để tìm kiếm cơ hội nghề nghiệp.)","We enjoyed a delicious meal at a local [Chinese] restaurant. (=Dịch: Chúng tôi đã thưởng thức một bữa ăn ngon miệng tại một nhà hàng Trung Hoa ở địa phương.)"],"ukAudio":"/ai_services/tts3/?q=chinese&lang=en-GB&ipa=%2F%CB%8Ct%CA%83a%C9%AA%CB%88ni%CB%90z%2F","usAudio":"/ai_services/tts3/?q=chinese&lang=en-US&ipa=%2F%CB%8Ct%CA%83a%C9%AA%CB%88ni%CB%90z%2F"},{"id":"lv_4_67","topic":"Cultural and Historical Exchange","word":"circular","pos":"(adj)","ipa":"/ˈsɜːr.kjə.lɚ/","defVi":"hình tròn, vòng quanh","defEn":"having the shape of a circle; round","examples":["The students sat in a [circular] arrangement around the teacher. (=Dịch: Các học sinh đã ngồi theo sự sắp xếp hình tròn xung quanh giáo viên.)","We took a [circular] route through the park and ended up where we started. (=Dịch: Chúng tôi đã đi theo một lộ trình vòng tròn qua công viên và kết thúc tại chính nơi chúng tôi đã bắt đầu.)","The room was illuminated by a large [circular] window on the ceiling. (=Dịch: Căn phòng được chiếu sáng bởi một cửa sổ tròn lớn trên trần nhà.)"],"ukAudio":"/ai_services/tts3/?q=circular&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.kj%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=circular&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.kj%C9%99.l%C9%9A%2F"},{"id":"lv_4_68","topic":"Cultural and Historical Exchange","word":"circus","pos":"(n)","ipa":"/ˈsɜːr.kəs/","defVi":"gánh xiếc, rạp xiếc","defEn":"a traveling show consisting of acrobats, clowns, and trained animals performing in an arena","examples":["The family bought tickets to see the [circus] during the weekend. (=Dịch: Gia đình đã mua vé đi xem xiếc vào cuối tuần.)","Acrobats performed daring stunts at the center of the [circus] tent. (=Dịch: Các nghệ sĩ nhào lộn đã biểu diễn những màn mạo hiểm ở trung tâm rạp xiếc.)","Many modern [circus] shows no longer use wild animals in their acts. (=Dịch: Nhiều chương trình xiếc hiện đại không còn sử dụng động vật hoang dã trong các tiết mục của họ.)"],"ukAudio":"/ai_services/tts3/?q=circus&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.k%C9%99s%2F","usAudio":"/ai_services/tts3/?q=circus&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.k%C9%99s%2F"},{"id":"lv_4_69","topic":"Cultural and Historical Exchange","word":"civilisation","pos":"(n)","ipa":"/ˌsɪv.ə.ləˈzeɪ.ʃən/","defVi":"nền văn minh","defEn":"a human society with its own developed culture, government, and way of life","examples":["Ancient Egyptian [civilisation] flourished along the banks of the Nile River. (=Dịch: Nền văn minh Ai Cập cổ đại đã phát triển hưng thịnh dọc theo hai bờ sông Nile.)","Many historians believe that writing is a cornerstone of modern [civilisation]. (=Dịch: Nhiều nhà sử học tin rằng chữ viết là nền tảng của nền văn minh hiện đại.)","The museum exhibits artifacts from the ancient Maya [civilisation]. (=Dịch: Bảo tàng trưng bày các hiện vật từ nền văn minh Maya cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=civilisation&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAv.%C9%99.l%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=civilisation&lang=en-US&ipa=%2F%CB%8Cs%C9%AAv.%C9%99.l%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_70","topic":"Cultural and Historical Exchange","word":"clay","pos":"(n)","ipa":"/kleɪ/","defVi":"đất sét","defEn":"a heavy, sticky earth that can be moulded when wet and baked hard","examples":["The children enjoyed shaping figures out of soft [clay]. (=Dịch: Lũ trẻ rất thích thú nặn các hình thù từ đất sét mềm.)","Bricks are typically made from dried and baked [clay]. (=Dịch: Gạch thường được làm từ đất sét phơi khô và nung nóng.)","The soil in this garden has too much [clay] for vegetables to grow easily. (=Dịch: Đất trong khu vườn này có quá nhiều đất sét khiến rau củ khó phát triển dễ dàng.)"],"ukAudio":"/ai_services/tts3/?q=clay&lang=en-GB&ipa=%2Fkle%C9%AA%2F","usAudio":"/ai_services/tts3/?q=clay&lang=en-US&ipa=%2Fkle%C9%AA%2F"},{"id":"lv_4_71","topic":"Cultural and Historical Exchange","word":"cleanliness","pos":"(n)","ipa":"/ˈklɛn.li.nəs/","defVi":"sự sạch sẽ, tính sạch sẽ","defEn":"the state or habit of keeping oneself and one's surroundings clean","examples":["The hospital places great importance on strict standards of [cleanliness]. (=Dịch: Bệnh viện rất coi trọng các tiêu chuẩn nghiêm ngặt về sự sạch sẽ.)","Regular hand washing is essential for personal [cleanliness] and hygiene. (=Dịch: Rửa tay thường xuyên là điều cần thiết để giữ gìn vệ sinh và sự sạch sẽ của cá nhân.)","The restaurant received a high rating for the [cleanliness] of its kitchen. (=Dịch: Nhà hàng đã nhận được đánh giá cao về độ sạch sẽ của nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=cleanliness&lang=en-GB&ipa=%2F%CB%88kl%C9%9Bn.li.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=cleanliness&lang=en-US&ipa=%2F%CB%88kl%C9%9Bn.li.n%C9%99s%2F"},{"id":"lv_4_72","topic":"Cultural and Historical Exchange","word":"cleansing","pos":"(n)","ipa":"/ˈklɛn.zɪŋ/","defVi":"sự làm sạch, tẩy rửa","defEn":"the process of making something thoroughly clean or pure","examples":["Daily facial [cleansing] is essential for maintaining healthy and clear skin. (=Dịch: Làm sạch da mặt hàng ngày là điều cần thiết để duy trì làn da khỏe mạnh và sáng mịn.)","The retreat focuses on the spiritual [cleansing] of the mind and body. (=Dịch: Khóa tu tập trung vào việc thanh lọc tâm trí và cơ thể về mặt tâm linh.)","Use a gentle lotion for the deep [cleansing] of sensitive skin. (=Dịch: Hãy sử dụng một loại sữa dưỡng dịu nhẹ để làm sạch sâu cho da nhạy cảm.)"],"ukAudio":"/ai_services/tts3/?q=cleansing&lang=en-GB&ipa=%2F%CB%88kl%C9%9Bn.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=cleansing&lang=en-US&ipa=%2F%CB%88kl%C9%9Bn.z%C9%AA%C5%8B%2F"},{"id":"lv_4_73","topic":"Cultural and Historical Exchange","word":"clip","pos":"(n)","ipa":"/klɪp/","defVi":"cái kẹp; đoạn phim ngắn","defEn":"a small device used to hold things together; a short extract from a film or recording","examples":["Use a paper [clip] to keep these printed documents together. (=Dịch: Hãy dùng kẹp giấy để giữ những tài liệu in này lại với nhau.)","The teacher showed a short video [clip] to illustrate the historical event. (=Dịch: Giáo viên đã chiếu một đoạn video ngắn để minh họa cho sự kiện lịch sử.)","She secured her loose hair with a plastic [clip] before washing her face. (=Dịch: Cô ấy dùng một chiếc kẹp nhựa để cố định phần tóc xõa trước khi rửa mặt.)"],"ukAudio":"/ai_services/tts3/?q=clip&lang=en-GB&ipa=%2Fkl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=clip&lang=en-US&ipa=%2Fkl%C9%AAp%2F"},{"id":"lv_4_74","topic":"Cultural and Historical Exchange","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng gửi áo mũ, phòng giữ đồ","defEn":"a room where coats, hats, and luggage can be left temporarily","examples":["Please leave your heavy coats in the [cloakroom] near the main entrance. (=Dịch: Vui lòng để áo khoác dày của bạn ở phòng gửi đồ gần lối vào chính.)","I collected my umbrella and jacket from the theatre [cloakroom] after the show. (=Dịch: Tôi đã lấy lại ô và áo khoác từ phòng gửi đồ của nhà hát sau buổi biểu diễn.)","The attendant at the [cloakroom] handed each guest a numbered ticket. (=Dịch: Nhân viên tại phòng giữ đồ đã trao cho mỗi vị khách một chiếc vé có đánh số.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_4_75","topic":"Cultural and Historical Exchange","word":"cloth","pos":"(n)","ipa":"/klɔːθ/","defVi":"vải, mảnh vải lau","defEn":"woven fabric made from cotton, wool, or other fibres, used for making clothes or covering things","examples":["She bought several metres of cotton [cloth] to make curtains. (=Dịch: Cô ấy đã mua vài mét vải cotton để may rèm cửa.)","Use a damp [cloth] to wipe the dust off the wooden table. (=Dịch: Hãy dùng một chiếc khăn ẩm để lau sạch bụi trên bàn gỗ.)","Wool is a natural [cloth] suitable for winter garments. (=Dịch: Len là một loại vải tự nhiên thích hợp cho các trang phục mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F"},{"id":"lv_4_76","topic":"Cultural and Historical Exchange","word":"coal","pos":"(n)","ipa":"/ˈkoʊl/","defVi":"than đá","defEn":"a hard black rock that is dug from the earth and burned to produce heat or electricity","examples":["The power station burns [coal] to generate electricity for the region. (=Dịch: Nhà máy điện đốt than đá để sản xuất điện cho khu vực.)","Miners worked deep underground to extract [coal]. (=Dịch: Các thợ mỏ đã làm việc sâu dưới lòng đất để khai thác than đá.)","Many countries are trying to reduce their reliance on [coal] because of pollution. (=Dịch: Nhiều quốc gia đang cố gắng giảm bớt sự phụ thuộc vào than đá do vấn đề ô nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=coal&lang=en-GB&ipa=%2F%CB%88ko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=coal&lang=en-US&ipa=%2F%CB%88ko%CA%8Al%2F"},{"id":"lv_4_77","topic":"Cultural and Historical Exchange","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stəl/","defVi":"thuộc vùng ven biển, duyên hải","defEn":"located on or near a coast","examples":["Many [coastal] towns depend heavily on fishing and tourism for income. (=Dịch: Nhiều thị trấn ven biển phụ thuộc rất nhiều vào nghề đánh cá và du lịch để kiếm thu nhập.)","The [coastal] road offers breathtaking views of the ocean. (=Dịch: Tuyến đường ven biển mang lại tầm nhìn tuyệt đẹp ra đại dương.)","Rising sea levels pose a serious threat to low-lying [coastal] areas. (=Dịch: Mực nước biển dâng cao đặt ra mối đe dọa nghiêm trọng đối với các khu vực ven biển trũng thấp.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F"},{"id":"lv_4_78","topic":"Cultural and Historical Exchange","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑːɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with mental processes of understanding, learning, and remembering","examples":["Regular physical exercise helps improve [cognitive] function in older adults. (=Dịch: Tập thể dục thường xuyên giúp cải thiện chức năng nhận thức ở người cao tuổi.)","Puzzles and memory games can stimulate children's [cognitive] development. (=Dịch: Các câu đố và trò chơi rèn luyện trí nhớ có thể kích thích sự phát triển nhận thức của trẻ em.)","The researchers studied the [cognitive] processes involved in learning a foreign language. (=Dịch: Các nhà nghiên cứu đã tìm hiểu các quá trình nhận thức liên quan đến việc học một ngoại ngữ.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_4_79","topic":"Cultural and Historical Exchange","word":"coin","pos":"(n)","ipa":"/kɔɪn/","defVi":"đồng xu, tiền kim loại","defEn":"a small, flat, usually round piece of metal used as money","examples":["He inserted a gold [coin] into the vending machine to buy a drink. (=Dịch: Anh ấy đã nhét một đồng xu vàng vào máy bán hàng tự động để mua đồ uống.)","She flipped a [coin] to decide who would start the game first. (=Dịch: Cô ấy đã tung một đồng xu để quyết định ai sẽ bắt đầu trò chơi trước.)","The metal detector found an ancient Roman [coin] buried in the field. (=Dịch: Máy dò kim loại đã tìm thấy một đồng xu La Mã cổ đại bị chôn vùi trên cánh đồng.)"],"ukAudio":"/ai_services/tts3/?q=coin&lang=en-GB&ipa=%2Fk%C9%94%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coin&lang=en-US&ipa=%2Fk%C9%94%C9%AAn%2F"},{"id":"lv_4_80","topic":"Cultural and Historical Exchange","word":"coincide","pos":"(v)","ipa":"/ˌkoʊ.ɪnˈsaɪd/","defVi":"trùng hợp, diễn ra đồng thời","defEn":"to happen at the same time as something else","examples":["The festival is planned to [coincide] with the city's annual holiday. (=Dịch: Lễ hội được lên kế hoạch trùng với ngày nghỉ lễ hàng năm của thành phố.)","Unfortunately, my business trip will [coincide] with my sister's wedding. (=Dịch: Thật không may, chuyến công tác của tôi sẽ trùng với đám cưới của em gái tôi.)","Her research findings [coincide] closely with results from previous studies. (=Dịch: Các kết quả nghiên cứu của cô ấy rất trùng khớp với kết quả từ các nghiên cứu trước đây.)"],"ukAudio":"/ai_services/tts3/?q=coincide&lang=en-GB&ipa=%2F%CB%8Cko%CA%8A.%C9%AAn%CB%88sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=coincide&lang=en-US&ipa=%2F%CB%8Cko%CA%8A.%C9%AAn%CB%88sa%C9%AAd%2F"},{"id":"lv_4_81","topic":"Cultural and Historical Exchange","word":"colonisation","pos":"(n)","ipa":"/ˌkɑː.lə.nəˈzeɪ.ʃən/","defVi":"sự thuộc địa hóa, sự khai phá thuộc địa","defEn":"the act or process of establishing control over a foreign territory and settling people there","examples":["The [colonisation] of the region caused dramatic changes to the indigenous population. (=Dịch: Sự xâm chiếm thuộc địa của khu vực này đã gây ra những thay đổi sâu sắc đối với người dân bản địa.)","Scientists are researching the possibilities and challenges of space [colonisation]. (=Dịch: Các nhà khoa học đang nghiên cứu các khả năng và thách thức của việc định cư ngoài không gian.)","Many African nations gained independence after decades of European [colonisation]. (=Dịch: Nhiều quốc gia châu Phi đã giành được độc lập sau nhiều thập kỷ bị châu Âu đô hộ.)"],"ukAudio":"/ai_services/tts3/?q=colonisation&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90.l%C9%99.n%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=colonisation&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90.l%C9%99.n%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_82","topic":"Cultural and Historical Exchange","word":"colony","pos":"(n)","ipa":"/ˈkɑː.lə.ni/","defVi":"thuộc địa","defEn":"a country or area controlled by another, more powerful country","examples":["The nation was once a British [colony] before gaining independence. (=Dịch: Quốc gia này từng là thuộc địa của Anh trước khi giành được độc lập.)","European powers established more than one [colony] across the continent. (=Dịch: Các cường quốc châu Âu đã thành lập nhiều thuộc địa trên khắp lục địa.)","Life in the newly formed [colony] was harsh and demanding. (=Dịch: Cuộc sống ở vùng thuộc địa mới thành lập rất khắc nghiệt và gian khổ.)"],"ukAudio":"/ai_services/tts3/?q=colony&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=colony&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F"},{"id":"lv_4_83","topic":"Cultural and Historical Exchange","word":"colourful","pos":"(adj)","ipa":"/ˈkʌl.ɚ.fəl/","defVi":"sặc sỡ, nhiều màu sắc, đa dạng sinh động","defEn":"having bright colors or a lot of different colors; interesting and lively","examples":["The garden was filled with [colourful] flowers blooming under the warm sun. (=Dịch: Khu vườn tràn ngập những bông hoa rực rỡ sắc màu nở rộ dưới ánh nắng ấm áp.)","The traditional festival featured a lively parade with [colourful] costumes. (=Dịch: Lễ hội truyền thống có một cuộc diễu hành sôi động với những bộ trang phục đầy màu sắc.)","The author led a [colourful] life full of exciting adventures around the world. (=Dịch: Tác giả đã có một cuộc đời muôn màu muôn vẻ với đầy những chuyến phiêu lưu kỳ thú khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=colourful&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.%C9%9A.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=colourful&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.%C9%9A.f%C9%99l%2F"},{"id":"lv_4_84","topic":"Cultural and Historical Exchange","word":"commentary","pos":"(n)","ipa":"/ˈkɑː.mən.ter.i/","defVi":"bài bình luận, lời tường thuật","defEn":"a spoken or written description and analysis of an event or topic","examples":["The live sports [commentary] made the football match much more exciting to watch. (=Dịch: Lời bình luận thể thao trực tiếp đã làm cho trận bóng đá trở nên hào hứng hơn nhiều khi theo dõi.)","The book provides an insightful [commentary] on contemporary social issues. (=Dịch: Cuốn sách đưa ra lời bình luận sâu sắc về các vấn đề xã hội đương đại.)","He gave a running [commentary] on the political developments during the news broadcast. (=Dịch: Anh ấy đã đưa ra lời bình luận liên tục về các diễn biến chính trị trong suốt buổi phát sóng tin tức.)"],"ukAudio":"/ai_services/tts3/?q=commentary&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F","usAudio":"/ai_services/tts3/?q=commentary&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F"},{"id":"lv_4_85","topic":"Cultural and Historical Exchange","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"ủy ban, hội đồng; khoản tiền hoa hồng","defEn":"a formal group of people entrusted by an authority to perform a specific duty or investigation","examples":["The government set up an independent [commission] to investigate the railway accident. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vụ tai nạn đường sắt.)","The real estate agent earned a five percent [commission] on the property sale. (=Dịch: Người môi giới bất động sản đã kiếm được khoản hoa hồng 5% từ việc bán bất động sản.)","A special [commission] was appointed to review the national education curriculum. (=Dịch: Một ủy ban đặc biệt đã được chỉ định để xem xét lại chương trình giáo dục quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_86","topic":"Cultural and Historical Exchange","word":"compose","pos":"(v)","ipa":"/kəmˈpoʊz/","defVi":"sáng tác, soạn thảo","defEn":"to create a piece of music, art, or written work","examples":["The musician took several months to [compose] his first symphony. (=Dịch: Nhạc sĩ đã mất vài tháng để sáng tác bản giao hưởng đầu tiên của mình.)","She sat quietly by the window to [compose] a heartfelt apology letter. (=Dịch: Cô ngồi lặng lẽ bên cửa sổ để viết một bức thư xin lỗi chân thành.)","Different ethnic groups [compose] the rich cultural fabric of the nation. (=Dịch: Các nhóm dân tộc khác nhau cấu thành nên bức tranh văn hóa phong phú của quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=compose&lang=en-GB&ipa=%2Fk%C9%99m%CB%88po%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=compose&lang=en-US&ipa=%2Fk%C9%99m%CB%88po%CA%8Az%2F"},{"id":"lv_4_87","topic":"Cultural and Historical Exchange","word":"composer","pos":"(n)","ipa":"/kəmˈpoʊ.zər/","defVi":"nhà soạn nhạc, nhạc sĩ","defEn":"a person who writes music, especially as a professional","examples":["Mozart is widely regarded as one of the greatest [composer] figures in classical music. (=Dịch: Mozart được nhiều người coi là một trong những nhà soạn nhạc vĩ đại nhất trong nền âm nhạc cổ điển.)","The film [composer] created a dramatic soundtrack that enhanced every scene. (=Dịch: Nhà soạn nhạc phim đã tạo ra một bản nhạc nền đầy kịch tính làm nổi bật từng phân cảnh.)","She aspires to become a successful [composer] of orchestral symphonies. (=Dịch: Cô ấy khao khát trở thành một nhà soạn nhạc thành công cho các bản giao hưởng của dàn nhạc.)"],"ukAudio":"/ai_services/tts3/?q=composer&lang=en-GB&ipa=%2Fk%C9%99m%CB%88po%CA%8A.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=composer&lang=en-US&ipa=%2Fk%C9%99m%CB%88po%CA%8A.z%C9%99r%2F"},{"id":"lv_4_88","topic":"Cultural and Historical Exchange","word":"composition","pos":"(n)","ipa":"/ˌkɑːm.pəˈzɪʃ.ən/","defVi":"tác phẩm nghệ thuật hoặc âm nhạc; sự cấu thành","defEn":"a work of music, art, or literature, or the way in which something is made up","examples":["Mozart wrote this musical [composition] when he was only ten years old. (=Dịch: Mozart đã sáng tác tác phẩm âm nhạc này khi ông mới chỉ mười tuổi.)","The chemical [composition] of the soil determines which crops will grow best. (=Dịch: Thành phần hóa học của đất quyết định loại cây trồng nào sẽ phát triển tốt nhất.)","The teacher praised her for the well-structured [composition] she submitted. (=Dịch: Giáo viên đã khen ngợi cô ấy vì bài luận có cấu trúc chặt chẽ mà cô đã nộp.)"],"ukAudio":"/ai_services/tts3/?q=composition&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=composition&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_89","topic":"Cultural and Historical Exchange","word":"concrete","pos":"(adj)","ipa":"/ˈkɑːn.kriːt/","defVi":"cụ thể, thực tế","defEn":"clear, real, and based on facts rather than general ideas","examples":["The committee asked for [concrete] proposals instead of vague ideas. (=Dịch: Ủy ban đã yêu cầu các đề xuất cụ thể thay vì những ý tưởng mơ hồ.)","Scientists need [concrete] proof to support their hypothesis. (=Dịch: Các nhà khoa học cần bằng chứng cụ thể để chứng minh cho giả thuyết của họ.)","They have not yet established any [concrete] plans for the holiday. (=Dịch: Họ vẫn chưa lập bất kỳ kế hoạch cụ thể nào cho kỳ nghỉ.)"],"ukAudio":"/ai_services/tts3/?q=concrete&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F","usAudio":"/ai_services/tts3/?q=concrete&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F"},{"id":"lv_4_90","topic":"Cultural and Historical Exchange","word":"conscious","pos":"(adj)","ipa":"/ˈkɑːn.ʃəs/","defVi":"tỉnh táo, có ý thức, nhận biết được","defEn":"awake and aware of one's surroundings and thoughts; intentional","examples":["The patient remained fully [conscious] throughout the entire medical procedure. (=Dịch: Bệnh nhân vẫn hoàn toàn tỉnh táo trong suốt toàn bộ quá trình phẫu thuật.)","Many consumers are making a [conscious] effort to reduce plastic waste. (=Dịch: Nhiều người tiêu dùng đang có ý thức nỗ lực giảm thiểu rác thải nhựa.)","He is very [conscious] of how his decisions might affect the team. (=Dịch: Anh ấy rất ý thức được việc các quyết định của mình có thể ảnh hưởng như thế nào đến cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=conscious&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=conscious&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.%CA%83%C9%99s%2F"},{"id":"lv_4_91","topic":"Cultural and Historical Exchange","word":"consumerism","pos":"(n)","ipa":"/kənˈsuː.mɚ.ɪ.zəm/","defVi":"chủ nghĩa tiêu dùng","defEn":"the belief that buying and using a lot of goods is desirable and good for the economy","examples":["Modern [consumerism] often encourages people to purchase items they do not really need. (=Dịch: Chủ nghĩa tiêu dùng hiện đại thường khuyến khích mọi người mua những món đồ mà họ không thực sự cần.)","Environmentalists warn that excessive [consumerism] is depleting natural resources. (=Dịch: Các nhà bảo vệ môi trường cảnh báo rằng chủ nghĩa tiêu dùng quá mức đang làm cạn kiệt tài nguyên thiên nhiên.)","The rise of online shopping has fueled global [consumerism] significantly. (=Dịch: Sự phát triển của mua sắm trực tuyến đã thúc đẩy đáng kể chủ nghĩa tiêu dùng toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=consumerism&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=consumerism&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A.%C9%AA.z%C9%99m%2F"},{"id":"lv_4_92","topic":"Cultural and Historical Exchange","word":"consumption","pos":"(n)","ipa":"/kənˈsʌmp.ʃən/","defVi":"sự tiêu thụ, lượng tiêu dùng","defEn":"the act of using up resources, energy, food, or materials","examples":["Reducing fuel [consumption] is essential for cutting down carbon emissions. (=Dịch: Việc giảm lượng tiêu thụ nhiên liệu là rất cần thiết để cắt giảm lượng khí thải carbon.)","The doctor advised him to limit his daily sugar [consumption]. (=Dịch: Bác sĩ khuyên anh ấy nên hạn chế lượng đường tiêu thụ hàng ngày.)","Industrial [consumption] of water has increased significantly over the past decade. (=Dịch: Mức tiêu thụ nước trong công nghiệp đã tăng đáng kể trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=consumption&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consumption&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_4_93","topic":"Cultural and Historical Exchange","word":"convenient","pos":"(adj)","ipa":"/kənˈviːn.jənt/","defVi":"tiện lợi, thuận tiện","defEn":"fitting in well with a person's needs, activities, and plans; easy to use or access","examples":["Online shopping is extremely [convenient] for people with busy work schedules. (=Dịch: Mua sắm trực tuyến cực kỳ tiện lợi cho những người có lịch làm việc bận rộn.)","The hotel is located in a very [convenient] place near the central station. (=Dịch: Khách sạn nằm ở một vị trí rất thuận tiện gần nhà ga trung tâm.)","Please let me know a [convenient] time for our next meeting. (=Dịch: Vui lòng cho tôi biết thời gian thuận tiện cho cuộc họp tiếp theo của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=convenient&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=convenient&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F"},{"id":"lv_4_94","topic":"Cultural and Historical Exchange","word":"copper","pos":"(n)","ipa":"/ˈkɑ.pər/","defVi":"đồng (kim loại)","defEn":"a soft, reddish-brown metallic chemical element that conducts heat and electricity well","examples":["Electrical wires are commonly made of [copper] because it conducts electricity well. (=Dịch: Dây điện thường được làm bằng [đồng] vì nó dẫn điện tốt.)","The ancient statue was crafted from pure [copper]. (=Dịch: Bức tượng cổ được chế tác từ [đồng] nguyên chất.)","Prices of [copper] rose sharply due to high industrial demand. (=Dịch: Giá [đồng] tăng mạnh do nhu cầu công nghiệp cao.)"],"ukAudio":"/ai_services/tts3/?q=copper&lang=en-GB&ipa=%2F%CB%88k%C9%91.p%C9%99r%2F","usAudio":"/ai_services/tts3/?q=copper&lang=en-US&ipa=%2F%CB%88k%C9%91.p%C9%99r%2F"},{"id":"lv_4_95","topic":"Cultural and Historical Exchange","word":"corridor","pos":"(n)","ipa":"/ˈkɔːr.ə.dɚ/","defVi":"hành lang","defEn":"a long narrow passage in a building, with doors leading into rooms","examples":["His office is right at the end of the [corridor]. (=Dịch: Văn phòng của anh ấy nằm ngay ở cuối hành lang.)","Students are not allowed to run in the school [corridor]. (=Dịch: Học sinh không được phép chạy ở hành lang trường học.)","The hotel has a dimly lit [corridor] on the fifth floor. (=Dịch: Khách sạn có một hành lang ánh sáng lờ mờ ở tầng năm.)"],"ukAudio":"/ai_services/tts3/?q=corridor&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=corridor&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F"},{"id":"lv_4_96","topic":"Cultural and Historical Exchange","word":"costume","pos":"(n)","ipa":"/ˈkɑ.stum/","defVi":"trang phục hóa trang, y phục","defEn":"a set of clothes worn by an actor or someone dressing up for a special occasion","examples":["The children spent weeks designing their own [costume] for Halloween. (=Dịch: Lũ trẻ đã dành nhiều tuần để tự thiết kế trang phục hóa trang cho lễ Halloween.)","Each actor wore a traditional [costume] suited to the historical drama. (=Dịch: Mỗi diễn viên đều mặc một bộ trang phục truyền thống phù hợp với vở kịch lịch sử.)","She won first prize at the party for wearing the most creative [costume]. (=Dịch: Cô ấy đã giành giải nhất tại bữa tiệc nhờ mặc bộ trang phục sáng tạo nhất.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91.stum%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91.stum%2F"},{"id":"lv_4_97","topic":"Cultural and Historical Exchange","word":"court","pos":"(n)","ipa":"/kɔːrt/","defVi":"tòa án, phiên tòa","defEn":"a place where legal trials take place and justice is administered","examples":["The witness was asked to appear in [court] to give evidence. (=Dịch: Nhân chứng được yêu cầu xuất hiện tại tòa án để cung cấp bằng chứng.)","The supreme [court] delivered its final decision on the case yesterday. (=Dịch: Tòa án tối cao đã đưa ra phán quyết cuối cùng về vụ án vào ngày hôm qua.)","Lawyers presented their arguments before the judge in open [court]. (=Dịch: Các luật sư đã trình bày lập luận của mình trước thẩm phán tại phiên tòa công khai.)"],"ukAudio":"/ai_services/tts3/?q=court&lang=en-GB&ipa=%2Fk%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=court&lang=en-US&ipa=%2Fk%C9%94%CB%90rt%2F"},{"id":"lv_4_98","topic":"Cultural and Historical Exchange","word":"creation","pos":"(n)","ipa":"/kriˈeɪ.ʃən/","defVi":"sự sáng tạo, tác phẩm sáng tạo, sự tạo ra","defEn":"the act of making something new, or something that has been made","examples":["The chef proudly presented his latest culinary [creation] to the guests. (=Dịch: Bếp trưởng tự hào giới thiệu sáng tạo ẩm thực mới nhất của mình tới các thực khách.)","The government announced the [creation] of thousands of new jobs in the tech sector. (=Dịch: Chính phủ đã công bố việc tạo ra hàng nghìn việc làm mới trong lĩnh vực công nghệ.)","Art encourages the [creation] of original ideas and self-expression. (=Dịch: Nghệ thuật khuyến khích việc tạo ra những ý tưởng độc đáo và thể hiện bản thân.)"],"ukAudio":"/ai_services/tts3/?q=creation&lang=en-GB&ipa=%2Fkri%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=creation&lang=en-US&ipa=%2Fkri%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_99","topic":"Cultural and Historical Exchange","word":"creature","pos":"(n)","ipa":"/ˈkriː.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"any living thing that is not a plant, especially an animal","examples":["The ocean depths are home to many bizarre and undiscovered [creature] types. (=Dịch: Độ sâu của đại dương là nơi cư trú của nhiều loài sinh vật kỳ lạ và chưa từng được khám phá.)","A nocturnal [creature] hunts for food during the night and sleeps by day. (=Dịch: Một sinh vật sống về đêm thường săn mồi vào ban đêm và ngủ vào ban ngày.)","Every living [creature] plays an essential role in maintaining the ecosystem. (=Dịch: Mọi sinh vật sống đều đóng một vai trò thiết yếu trong việc duy trì hệ sinh thái.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_4_100","topic":"Cultural and Historical Exchange","word":"criticism","pos":"(n)","ipa":"/ˈkrɪt̬.ə.sɪz.əm/","defVi":"sự chỉ trích, lời phê bình","defEn":"the expression of disapproval of someone or something based on perceived faults or mistakes","examples":["The government faced severe [criticism] for its handling of the economic crisis. (=Dịch: Chính phủ đã phải đối mặt với sự chỉ trích gay gắt vì cách xử lý cuộc khủng hoảng kinh tế.)","Constructive [criticism] can help students improve their writing skills. (=Dịch: Sự phê bình mang tính xây dựng có thể giúp học sinh cải thiện kỹ năng viết của mình.)","She found it difficult to accept any [criticism] of her artwork. (=Dịch: Cô cảm thấy khó chấp nhận bất kỳ lời chỉ trích nào về tác phẩm nghệ thuật của mình.)"],"ukAudio":"/ai_services/tts3/?q=criticism&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%99.s%C9%AAz.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=criticism&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%99.s%C9%AAz.%C9%99m%2F"},{"id":"lv_4_101","topic":"Cultural and Historical Exchange","word":"cultivation","pos":"(n)","ipa":"/ˌkʌl.təˈveɪ.ʃən/","defVi":"sự canh tác, trồng trọt; sự trau dồi, bồi dưỡng","defEn":"the preparation and use of land for growing crops, or the development of a skill or quality","examples":["The fertile valley is ideal for the [cultivation] of rice and vegetables. (=Dịch: Thung lũng màu mỡ này rất lý tưởng cho việc canh tác lúa và rau màu.)","Successful leadership requires the continuous [cultivation] of communication skills. (=Dịch: Sự lãnh đạo thành công đòi hỏi việc không ngừng trau dồi các kỹ năng giao tiếp.)","Intensive land [cultivation] can lead to severe soil erosion over time. (=Dịch: Việc canh tác đất đai quá mức có thể dẫn đến xói mòn đất nghiêm trọng theo thời gian.)"],"ukAudio":"/ai_services/tts3/?q=cultivation&lang=en-GB&ipa=%2F%CB%8Ck%CA%8Cl.t%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cultivation&lang=en-US&ipa=%2F%CB%8Ck%CA%8Cl.t%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_102","topic":"Cultural and Historical Exchange","word":"cultural","pos":"(adj)","ipa":"/ˈkʌl.tʃɚ.əl/","defVi":"thuộc về văn hóa","defEn":"relating to the habits, traditions, and beliefs of a society","examples":["The festival is a celebration of our rich [cultural] heritage. (=Dịch: Lễ hội là một sự tôn vinh di sản văn hóa phong phú của chúng tôi.)","Students should learn to respect [cultural] differences. (=Dịch: Học sinh nên học cách tôn trọng những khác biệt về văn hóa.)","The city offers a wide variety of [cultural] activities for tourists. (=Dịch: Thành phố mang đến nhiều hoạt động văn hóa phong phú cho du khách.)"],"ukAudio":"/ai_services/tts3/?q=cultural&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cultural&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F"},{"id":"lv_4_103","topic":"Cultural and Historical Exchange","word":"cutlery","pos":"(n)","ipa":"/ˈkʌt.lə.ri/","defVi":"bộ dao dĩa, đồ dùng ăn uống (dao, nĩa, thìa)","defEn":"knives, forks, and spoons used for eating or serving food","examples":["She placed polished silver [cutlery] on the dining table. (=Dịch: Cô ấy đặt [dao nĩa] bằng bạc đã được đánh bóng lên bàn ăn.)","The restaurant provides wooden [cutlery] for takeout meals. (=Dịch: Nhà hàng cung cấp [dao muỗng nĩa] bằng gỗ cho các bữa ăn mang đi.)","Don't forget to pack some disposable [cutlery] for our picnic. (=Dịch: Đừng quên mang theo một ít [dao muỗng nĩa] dùng một lần cho chuyến dã ngoại của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=cutlery&lang=en-GB&ipa=%2F%CB%88k%CA%8Ct.l%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=cutlery&lang=en-US&ipa=%2F%CB%88k%CA%8Ct.l%C9%99.ri%2F"},{"id":"lv_4_104","topic":"Cultural and Historical Exchange","word":"cylinder","pos":"(n)","ipa":"/ˈsɪl.ɪn.dɚ/","defVi":"hình trụ; bình khí hình trụ, xi-lanh","defEn":"a solid geometric shape or container with straight parallel sides and a circular top and base","examples":["The gas was stored safely inside a pressurized steel [cylinder]. (=Dịch: Khí gas được lưu trữ an toàn bên trong một bình trụ bằng thép chịu áp suất.)","In geometry class, students learned how to calculate the volume of a [cylinder]. (=Dịch: Trong giờ học hình học, học sinh đã học cách tính thể tích của một hình trụ.)","The engine is powered by four pistons moving smoothly inside each [cylinder]. (=Dịch: Động cơ vận hành nhờ bốn pít-tông chuyển động êm ái bên trong mỗi xi-lanh.)"],"ukAudio":"/ai_services/tts3/?q=cylinder&lang=en-GB&ipa=%2F%CB%88s%C9%AAl.%C9%AAn.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cylinder&lang=en-US&ipa=%2F%CB%88s%C9%AAl.%C9%AAn.d%C9%9A%2F"},{"id":"lv_4_105","topic":"Cultural and Historical Exchange","word":"decade","pos":"(n)","ipa":"/ˈdɛk.eɪd/","defVi":"thập kỷ (10 năm)","defEn":"a period of ten consecutive years","examples":["Economic growth slowed down considerably over the past [decade]. (=Dịch: Tăng trưởng kinh tế đã chậm lại đáng kể trong thập kỷ qua.)","Technology has transformed our daily lives over the last [decade]. (=Dịch: Công nghệ đã làm thay đổi cuộc sống hàng ngày của chúng ta trong thập kỷ vừa qua.)","She spent more than a [decade] working as a primary school teacher. (=Dịch: Cô ấy đã dành hơn một thập kỷ làm giáo viên tiểu học.)"],"ukAudio":"/ai_services/tts3/?q=decade&lang=en-GB&ipa=%2F%CB%88d%C9%9Bk.e%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=decade&lang=en-US&ipa=%2F%CB%88d%C9%9Bk.e%C9%AAd%2F"},{"id":"lv_4_106","topic":"Cultural and Historical Exchange","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"suy giảm; từ chối","defEn":"to gradually become smaller, fewer, or less; to politely refuse an offer","examples":["Tourist numbers began to [decline] during the rainy season. (=Dịch: Lượng khách du lịch bắt đầu suy giảm trong suốt mùa mưa.)","He decided to [decline] the job offer because the commute was too long. (=Dịch: Anh ấy đã quyết định từ chối lời mời làm việc vì quãng đường đi làm quá xa.)","Air quality can [decline] rapidly if factories do not follow environmental regulations. (=Dịch: Chất lượng không khí có thể suy giảm nhanh chóng nếu các nhà máy không tuân thủ các quy định về môi trường.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_4_107","topic":"Cultural and Historical Exchange","word":"decorate","pos":"(v)","ipa":"/ˈdek.ə.reɪt/","defVi":"trang trí, tô điểm","defEn":"to add things to an object or place to make it look more attractive","examples":["They decided to [decorate] the living room with fresh flowers. (=Dịch: Họ quyết định trang trí phòng khách bằng hoa tươi.)","Children love to [decorate] the Christmas tree every December. (=Dịch: Trẻ em thích trang trí cây thông Giáng sinh vào mỗi tháng Mười Hai.)","The bakery allows customers to [decorate] their own cakes. (=Dịch: Tiệm bánh cho phép khách hàng tự trang trí bánh ngọt của riêng mình.)"],"ukAudio":"/ai_services/tts3/?q=decorate&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=decorate&lang=en-US&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F"},{"id":"lv_4_108","topic":"Cultural and Historical Exchange","word":"decoration","pos":"(n)","ipa":"/ˌdɛk.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang hoàng","defEn":"an object or detail added to something to make it look more attractive","examples":["They put up colorful lighting as part of the party [decoration]. (=Dịch: Họ đã giăng đèn nhiều màu sắc như một phần của việc trang trí bữa tiệc.)","Handmade wooden crafts serve as elegant [decoration] in modern homes. (=Dịch: Đồ thủ công bằng gỗ tự làm đóng vai trò là vật trang trí trang nhã trong những ngôi nhà hiện đại.)","The cake [decoration] took the baker several hours to complete. (=Dịch: Việc trang trí chiếc bánh đã khiến người thợ làm bánh mất vài giờ để hoàn thành.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bk.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bk.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_109","topic":"Cultural and Historical Exchange","word":"decorative","pos":"(adj)","ipa":"/ˈdek.ə.rə.t̬ɪv/","defVi":"mang tính trang trí, dùng để làm đẹp","defEn":"made to look attractive rather than for practical use","examples":["The mirror has an elaborate [decorative] frame made of carved wood. (=Dịch: Chiếc gương có phần khung trang trí tinh xảo làm bằng gỗ chạm khắc.)","Plants are often used for [decorative] purposes in modern offices. (=Dịch: Cây xanh thường được dùng cho mục đích trang trí trong các văn phòng hiện đại.)","She placed several [decorative] cushions on the sofa to brighten up the room. (=Dịch: Cô ấy đặt vài chiếc gối trang trí trên ghế sofa để làm bừng sáng căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=decorative&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.r%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=decorative&lang=en-US&ipa=%2F%CB%88dek.%C9%99.r%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_4_110","topic":"Cultural and Historical Exchange","word":"definition","pos":"(n)","ipa":"/ˌdɛf.əˈnɪʃ.ən/","defVi":"định nghĩa, lời giải thích ý nghĩa","defEn":"an explanation of the exact meaning of a word, phrase, or concept","examples":["You can look up the exact [definition] of the word in a dictionary. (=Dịch: Bạn có thể tra cứu [định nghĩa] chính xác của từ này trong từ điển.)","The legal [definition] of fraud can vary from country to country. (=Dịch: [Định nghĩa] pháp lý về tội lừa đảo có thể khác nhau tùy theo từng quốc gia.)","His clear [definition] of the problem helped the team find a solution. (=Dịch: [Sự xác định] rõ ràng của anh ấy về vấn đề đã giúp cả nhóm tìm ra giải pháp.)"],"ukAudio":"/ai_services/tts3/?q=definition&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=definition&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_111","topic":"Cultural and Historical Exchange","word":"deliver","pos":"(v)","ipa":"/dɪˈlɪv.ɚ/","defVi":"giao hàng; phát biểu","defEn":"to take goods, letters, or packages to a person or place; to give a speech","examples":["The courier will [deliver] your parcel before five o'clock. (=Dịch: Nhân viên chuyển phát sẽ giao bưu kiện của bạn trước năm giờ.)","The professor is scheduled to [deliver] a lecture on climate change tomorrow. (=Dịch: Giáo sư dự kiến sẽ có một bài giảng về biến đổi khí hậu vào ngày mai.)","Our company strives to [deliver] exceptional service to all clients. (=Dịch: Công ty chúng tôi luôn nỗ lực mang lại dịch vụ xuất sắc cho tất cả khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=deliver&lang=en-GB&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=deliver&lang=en-US&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F"},{"id":"lv_4_112","topic":"Cultural and Historical Exchange","word":"demonstration","pos":"(n)","ipa":"/ˌdɛm.ənˈstreɪ.ʃən/","defVi":"sự trình diễn, sự thị phạm","defEn":"an act of showing how something works, is done, or is used","examples":["The chef gave a practical [demonstration] of how to prepare the traditional dish. (=Dịch: Bếp trưởng đã thực hiện một buổi trình diễn thực tế về cách chế biến món ăn truyền thống.)","We watched an interesting [demonstration] of the new software in the workshop. (=Dịch: Chúng tôi đã xem một buổi minh họa thú vị về phần mềm mới trong hội thảo.)","The teacher used a simple laboratory [demonstration] to explain chemical reactions. (=Dịch: Giáo viên đã sử dụng một thí nghiệm biểu diễn đơn giản trong phòng thí nghiệm để giải thích các phản ứng hóa học.)"],"ukAudio":"/ai_services/tts3/?q=demonstration&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99n%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=demonstration&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99n%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_113","topic":"Cultural and Historical Exchange","word":"depict","pos":"(v)","ipa":"/dɪˈpɪkt/","defVi":"miêu tả, khắc họa","defEn":"to represent or show something in a picture, painting, or story","examples":["The murals on the wall [depict] the daily life of ancient citizens. (=Dịch: Các bức tranh tường miêu tả cuộc sống hàng ngày của những cư dân thời cổ đại.)","Documentaries often [depict] the harsh realities of wildlife survival. (=Dịch: Phim tài liệu thường khắc họa những thực tế khắc nghiệt về sự sinh tồn của động vật hoang dã.)","The novel manages to [depict] the complex emotions of the main character accurately. (=Dịch: Cuốn tiểu thuyết đã khắc họa thành công và chính xác những cảm xúc phức tạp của nhân vật chính.)"],"ukAudio":"/ai_services/tts3/?q=depict&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=depict&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%AAkt%2F"},{"id":"lv_4_114","topic":"Cultural and Historical Exchange","word":"depression","pos":"(n)","ipa":"/dɪˈprɛʃ.ən/","defVi":"chứng trầm cảm","defEn":"a mental health condition characterized by severe, persistent feelings of sadness and hopelessness","examples":["Regular exercise and therapy can help alleviate symptoms of clinical [depression]. (=Dịch: Tập thể dục đều đặn và trị liệu có thể giúp làm giảm các triệu chứng của bệnh trầm cảm lâm sàng.)","She fell into a deep [depression] after losing her long-term job. (=Dịch: Cô ấy rơi vào trạng thái trầm cảm sâu sắc sau khi mất công việc gắn bó lâu năm.)","Public awareness campaigns aim to reduce the stigma surrounding teenage [depression]. (=Dịch: Các chiến dịch nâng cao nhận thức cộng đồng nhằm giảm bớt sự kỳ thị xung quanh chứng trầm cảm ở tuổi vị thành niên.)"],"ukAudio":"/ai_services/tts3/?q=depression&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=depression&lang=en-US&ipa=%2Fd%C9%AA%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_4_115","topic":"Cultural and Historical Exchange","word":"destruction","pos":"(n)","ipa":"/dɪˈstrʌk.ʃən/","defVi":"sự phá hủy, sự tàn phá","defEn":"the act or process of destroying something, or the state of being destroyed","examples":["The storm caused widespread [destruction] across the coastal villages. (=Dịch: Cơn bão đã gây ra sự [tàn phá] trên diện rộng khắp các ngôi làng ven biển.)","The [destruction] of rainforests threatens many endangered species. (=Dịch: Sự [phá hủy] các khu rừng nhiệt đới đe dọa nhiều loài có nguy cơ tuyệt chủng.)","Weapons of mass [destruction] pose a serious threat to world peace. (=Dịch: Vũ khí [hủy diệt] hàng loạt là mối đe dọa nghiêm trọng đối với hòa bình thế giới.)"],"ukAudio":"/ai_services/tts3/?q=destruction&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destruction&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_4_116","topic":"Cultural and Historical Exchange","word":"digitalise","pos":"(v)","ipa":"/ˈdɪdʒ.ə.t̬əl.aɪz/","defVi":"số hóa","defEn":"to convert information or documents into a format that computers can process","examples":["The national library aims to [digitalise] all historical manuscripts for public access. (=Dịch: Thư viện quốc gia đặt mục tiêu số hóa tất cả các bản thảo lịch sử để công chúng có thể tiếp cận.)","Many hospitals are trying to [digitalise] patient records to improve efficiency. (=Dịch: Nhiều bệnh viện đang cố gắng số hóa hồ sơ bệnh nhân để nâng cao hiệu quả.)","Small businesses must [digitalise] their payment systems to stay competitive. (=Dịch: Các doanh nghiệp nhỏ phải số hóa hệ thống thanh toán của mình để duy trì tính cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=digitalise&lang=en-GB&ipa=%2F%CB%88d%C9%AAd%CA%92.%C9%99.t%CC%AC%C9%99l.a%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=digitalise&lang=en-US&ipa=%2F%CB%88d%C9%AAd%CA%92.%C9%99.t%CC%AC%C9%99l.a%C9%AAz%2F"},{"id":"lv_4_117","topic":"Cultural and Historical Exchange","word":"disappoint","pos":"(v)","ipa":"/ˌdɪs.əˈpɔɪnt/","defVi":"làm thất vọng","defEn":"to fail to satisfy someone's hopes or expectations","examples":["I am sorry to [disappoint] you, but the tickets are already sold out. (=Dịch: Tôi rất tiếc phải làm bạn thất vọng, nhưng vé đã được bán hết rồi.)","The team worked hard because they did not want to [disappoint] their coach. (=Dịch: Cả đội đã nỗ lực hết mình vì không muốn làm huấn luyện viên của họ thất vọng.)","The final results of the experiment may [disappoint] some researchers. (=Dịch: Kết quả cuối cùng của thí nghiệm có thể khiến một số nhà nghiên cứu thất vọng.)"],"ukAudio":"/ai_services/tts3/?q=disappoint&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%94%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=disappoint&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%94%C9%AAnt%2F"},{"id":"lv_4_118","topic":"Cultural and Historical Exchange","word":"distribution","pos":"(n)","ipa":"/ˌdɪs.trəˈbjuː.ʃən/","defVi":"sự phân phối, sự phân bố","defEn":"the way in which something is spread over an area, or the delivery of goods to various places","examples":["The unequal [distribution] of wealth remains a major global challenge. (=Dịch: Sự phân bổ của cải không đồng đều vẫn là một thách thức lớn trên toàn cầu.)","The company improved its supply chain to ensure faster [distribution] of medical supplies. (=Dịch: Công ty đã cải thiện chuỗi cung ứng của mình để đảm bảo việc phân phối vật tư y tế nhanh hơn.)","Scientists are studying the geographic [distribution] of endangered plant species. (=Dịch: Các nhà khoa học đang nghiên cứu sự phân bố địa lý của các loài thực vật có nguy cơ tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=distribution&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%99%CB%88bju%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=distribution&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%99%CB%88bju%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_119","topic":"Cultural and Historical Exchange","word":"disturbing","pos":"(adj)","ipa":"/dɪˈstɝː.bɪŋ/","defVi":"gây lo ngại, làm phiền lòng","defEn":"making you feel worried, upset, or shocked","examples":["The news report contained some very [disturbing] images. (=Dịch: Bản tin chứa một số hình ảnh rất đáng lo ngại.)","There has been a [disturbing] increase in youth crime recently. (=Dịch: Gần đây có sự gia tăng đáng lo ngại về tội phạm vị thành niên.)","She found the quiet atmosphere in the empty house quite [disturbing]. (=Dịch: Cô cảm thấy bầu không khí tĩnh mịch trong ngôi nhà trống trải khá bất an.)"],"ukAudio":"/ai_services/tts3/?q=disturbing&lang=en-GB&ipa=%2Fd%C9%AA%CB%88st%C9%9D%CB%90.b%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=disturbing&lang=en-US&ipa=%2Fd%C9%AA%CB%88st%C9%9D%CB%90.b%C9%AA%C5%8B%2F"},{"id":"lv_4_120","topic":"Cultural and Historical Exchange","word":"diver","pos":"(n)","ipa":"/ˈdaɪ.vɚ/","defVi":"thợ lặn, người lặn","defEn":"a person who swims underwater using special breathing equipment","examples":["An experienced [diver] explored the deep coral reefs off the coast. (=Dịch: Một thợ lặn giàu kinh nghiệm đã khám phá những rạn san hô sâu ngoài khơi bờ biển.)","The rescue team sent a [diver] to search for the submerged vehicle. (=Dịch: Đội cứu hộ đã cử một thợ lặn đến để tìm kiếm chiếc xe bị chìm.)","Each [diver] must check their oxygen tank carefully before going underwater. (=Dịch: Mỗi thợ lặn phải kiểm tra kỹ bình dưỡng khí của mình trước khi lặn xuống nước.)"],"ukAudio":"/ai_services/tts3/?q=diver&lang=en-GB&ipa=%2F%CB%88da%C9%AA.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=diver&lang=en-US&ipa=%2F%CB%88da%C9%AA.v%C9%9A%2F"},{"id":"lv_4_121","topic":"Cultural and Historical Exchange","word":"diverse","pos":"(adj)","ipa":"/daɪˈvɝːs/","defVi":"đa dạng, phong phú","defEn":"including many different types of people or things","examples":["The university has a culturally [diverse] student body. (=Dịch: Trường đại học có một cộng đồng sinh viên đa dạng về văn hóa.)","She has very [diverse] interests, ranging from music to astronomy. (=Dịch: Cô có những sở thích rất đa dạng, từ âm nhạc cho đến thiên văn học.)","The rainforest is home to an extraordinarily [diverse] range of wildlife. (=Dịch: Rừng nhiệt đới là nơi sinh sống của một hệ động thực vật hoang dã vô cùng phong phú và đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=diverse&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90s%2F","usAudio":"/ai_services/tts3/?q=diverse&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90s%2F"},{"id":"lv_4_122","topic":"Cultural and Historical Exchange","word":"documentary","pos":"(adj)","ipa":"/ˌdɑː.kjəˈmen.tər.i/","defVi":"mang tính tài liệu, dựa trên tư liệu thực tế","defEn":"consisting of or based on official documents and factual records","examples":["The lawyer presented strong [documentary] evidence to support his client's claim. (=Dịch: Luật sư đã đưa ra bằng chứng bằng văn bản thuyết phục để chứng minh cho khiếu nại của thân chủ mình.)","Historians rely on [documentary] records to reconstruct past events accurately. (=Dịch: Các nhà sử học dựa vào các tư liệu thành văn để tái hiện chính xác các sự kiện trong quá khứ.)","She is preparing a [documentary] report on the impacts of climate change. (=Dịch: Cô ấy đang chuẩn bị một bản báo cáo tư liệu về những tác động của biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=documentary&lang=en-GB&ipa=%2F%CB%8Cd%C9%91%CB%90.kj%C9%99%CB%88men.t%C9%99r.i%2F","usAudio":"/ai_services/tts3/?q=documentary&lang=en-US&ipa=%2F%CB%8Cd%C9%91%CB%90.kj%C9%99%CB%88men.t%C9%99r.i%2F"},{"id":"lv_4_123","topic":"Cultural and Historical Exchange","word":"dominate","pos":"(v)","ipa":"/ˈdɑː.məˌneɪt/","defVi":"thống trị, chi phối","defEn":"to have control, power, or a very strong influence over someone or something","examples":["A few large corporations [dominate] the global smartphone market. (=Dịch: Một vài tập đoàn lớn đang thống trị thị trường điện thoại thông minh toàn cầu.)","Discussions about the economy tended to [dominate] the annual meeting. (=Dịch: Các cuộc thảo luận về kinh tế có xu hướng chiếm ưu thế trong cuộc họp thường niên.)","The mountain peak continues to [dominate] the surrounding landscape. (=Dịch: Đỉnh núi vẫn sừng sững bao quát cảnh quan xung quanh.)"],"ukAudio":"/ai_services/tts3/?q=dominate&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99%CB%8Cne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=dominate&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99%CB%8Cne%C9%AAt%2F"},{"id":"lv_4_124","topic":"Cultural and Historical Exchange","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"quyên góp, ủng hộ, hiến tặng","defEn":"to give money, goods, or services to help a person or organization","examples":["Wealthy individuals frequently [donate] large sums to charitable foundations. (=Dịch: Những người giàu có thường xuyên quyên góp những khoản tiền lớn cho các quỹ từ thiện.)","Citizens gathered at the clinic to [donate] blood for disaster victims. (=Dịch: Người dân đã tập trung tại phòng khám để hiến máu cho các nạn nhân của thảm họa.)","She plans to [donate] her old textbooks to the local community library. (=Dịch: Cô ấy dự định tặng các sách giáo khoa cũ của mình cho thư viện cộng đồng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_4_125","topic":"Cultural and Historical Exchange","word":"drain","pos":"(v)","ipa":"/dreɪn/","defVi":"thoát nước, rút cạn, làm kiệt quệ","defEn":"to remove liquid from something, or to use up resources gradually until empty","examples":["You need to [drain] the cooked pasta thoroughly before adding the tomato sauce. (=Dịch: Bạn cần để ráo nước món mì ống đã nấu chín trước khi thêm sốt cà chua.)","Huge medical expenses can quickly [drain] a family's savings. (=Dịch: Chi phí y tế khổng lồ có thể nhanh chóng làm cạn kiệt tiền tiết kiệm của một gia đình.)","Workers dug a series of trenches to [drain] floodwaters from the residential area. (=Dịch: Các công nhân đã đào một loạt mương để thoát nước lũ khỏi khu dân cư.)"],"ukAudio":"/ai_services/tts3/?q=drain&lang=en-GB&ipa=%2Fdre%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=drain&lang=en-US&ipa=%2Fdre%C9%AAn%2F"},{"id":"lv_4_126","topic":"Cultural and Historical Exchange","word":"drum","pos":"(n)","ipa":"/drʌm/","defVi":"cái trống; thùng phuy","defEn":"a musical instrument played by hitting with sticks or hands, or a large cylindrical container","examples":["The steady beat of the [drum] echoed across the entire stadium. (=Dịch: Tiếng trống đập đều đặn vang vọng khắp cả sân vận động.)","The factory stored hazardous chemicals in a large metal [drum]. (=Dịch: Nhà máy đã chứa các hóa chất nguy hiểm trong một chiếc thùng phuy kim loại lớn.)","She learned to play the traditional African [drum] during her cultural trip. (=Dịch: Cô ấy đã học chơi chiếc trống truyền thống của châu Phi trong chuyến đi trải nghiệm văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=drum&lang=en-GB&ipa=%2Fdr%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=drum&lang=en-US&ipa=%2Fdr%CA%8Cm%2F"},{"id":"lv_4_127","topic":"Cultural and Historical Exchange","word":"drunk","pos":"(n)","ipa":"/drʌŋk/","defVi":"kẻ say rượu, người nghiện rượu","defEn":"a person who is intoxicated or who frequently drinks too much alcohol","examples":["The police officer helped the harmless [drunk] find his way home. (=Dịch: Viên cảnh sát đã giúp người say rượu vô hại tìm đường về nhà.)","A noisy [drunk] was causing a disturbance outside the restaurant. (=Dịch: Một kẻ say rượu ồn ào đã gây mất trật tự bên ngoài nhà hàng.)","The shelter provides warm beds for homeless [drunks] during winter nights. (=Dịch: Nhà tạm trú cung cấp giường ấm cho những người say xỉn vô gia cư trong những đêm mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=drunk&lang=en-GB&ipa=%2Fdr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=drunk&lang=en-US&ipa=%2Fdr%CA%8C%C5%8Bk%2F"},{"id":"lv_4_128","topic":"Cultural and Historical Exchange","word":"dutch","pos":"(adj)","ipa":"/dʌtʃ/","defVi":"(thuộc) Hà Lan, người Hà Lan hoặc tiếng Hà Lan","defEn":"relating to the Netherlands, its people, or its language","examples":["We rented bicycles to explore the traditional [Dutch] countryside. (=Dịch: Chúng tôi đã thuê xe đạp để khám phá vùng nông thôn truyền thống của Hà Lan.)","She is currently learning [Dutch] before moving to Amsterdam for work. (=Dịch: Cô ấy hiện đang học tiếng Hà Lan trước khi chuyển đến Amsterdam để làm việc.)","The museum features a rare collection of seventeenth-century [Dutch] paintings. (=Dịch: Bảo tàng trưng bày một bộ sưu tập tranh Hà Lan thế kỷ XVII quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=dutch&lang=en-GB&ipa=%2Fd%CA%8Ct%CA%83%2F","usAudio":"/ai_services/tts3/?q=dutch&lang=en-US&ipa=%2Fd%CA%8Ct%CA%83%2F"},{"id":"lv_4_129","topic":"Cultural and Historical Exchange","word":"dwelling","pos":"(n)","ipa":"/ˈdwel.ɪŋ/","defVi":"chỗ ở, nơi cư ngụ, nhà ở","defEn":"a house, flat, or other place of residence","examples":["Archaeologists discovered the remains of an ancient cave [dwelling]. (=Dịch: Các nhà khảo cổ học đã phát hiện ra tàn tích của một nơi cư trú trong hang động cổ xưa.)","The city council plans to build more affordable [dwelling] units for low-income families. (=Dịch: Hội đồng thành phố lên kế hoạch xây dựng thêm nhiều căn nhà ở giá cả phải chăng cho các gia đình có thu nhập thấp.)","Many traditional wooden [dwelling] structures were damaged during the severe storm. (=Dịch: Nhiều công trình nhà ở bằng gỗ truyền thống đã bị hư hại trong cơn bão dữ dội.)"],"ukAudio":"/ai_services/tts3/?q=dwelling&lang=en-GB&ipa=%2F%CB%88dwel.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dwelling&lang=en-US&ipa=%2F%CB%88dwel.%C9%AA%C5%8B%2F"},{"id":"lv_4_130","topic":"Cultural and Historical Exchange","word":"dynamic","pos":"(adj)","ipa":"/daɪˈnæm.ɪk/","defVi":"năng động, sôi nổi, biến đổi liên tục","defEn":"full of energy, enthusiasm, and new ideas; constantly changing","examples":["She is a [dynamic] speaker who easily captivates the entire audience. (=Dịch: Cô ấy là một diễn giả đầy năng động, người dễ dàng lôi cuốn toàn bộ khán giả.)","The technology sector is a fast-paced and [dynamic] industry. (=Dịch: Lĩnh vực công nghệ là một ngành công nghiệp có nhịp độ nhanh và đầy năng động.)","We need to adapt our strategy to survive in this [dynamic] market. (=Dịch: Chúng ta cần phải điều chỉnh chiến lược của mình để tồn tại trong thị trường biến động không ngừng này.)"],"ukAudio":"/ai_services/tts3/?q=dynamic&lang=en-GB&ipa=%2Fda%C9%AA%CB%88n%C3%A6m.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dynamic&lang=en-US&ipa=%2Fda%C9%AA%CB%88n%C3%A6m.%C9%AAk%2F"},{"id":"lv_4_131","topic":"Cultural and Historical Exchange","word":"edit","pos":"(v)","ipa":"/ˈɛd.ɪt/","defVi":"chỉnh sửa, biên tập","defEn":"to make changes to a text, film, or audio recording to correct mistakes or prepare it for publication","examples":["You should carefully [edit] your essay before submitting it to the professor. (=Dịch: Bạn nên cẩn thận chỉnh sửa bài luận của mình trước khi nộp cho giáo sư.)","It took them several weeks to [edit] the documentary film. (=Dịch: Họ đã mất vài tuần để biên tập bộ phim tài liệu.)","The publisher asked the author to [edit] the final chapter to improve its flow. (=Dịch: Nhà xuất bản đã yêu cầu tác giả chỉnh sửa chương cuối để bài viết được liền mạch hơn.)"],"ukAudio":"/ai_services/tts3/?q=edit&lang=en-GB&ipa=%2F%CB%88%C9%9Bd.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=edit&lang=en-US&ipa=%2F%CB%88%C9%9Bd.%C9%AAt%2F"},{"id":"lv_4_132","topic":"Cultural and Historical Exchange","word":"edition","pos":"(n)","ipa":"/ɪˈdɪʃ.ən/","defVi":"ấn bản, phiên bản","defEn":"a particular form or version of a published text or broadcast","examples":["I bought the latest [edition] of the English dictionary. (=Dịch: Tôi đã mua ấn bản mới nhất của cuốn từ điển tiếng Anh.)","The author signed a limited [edition] of her new novel. (=Dịch: Tác giả đã ký tặng một ấn bản giới hạn cho cuốn tiểu thuyết mới của cô ấy.)","This morning's [edition] of the newspaper featured an article on climate change. (=Dịch: Ấn bản sáng nay của tờ báo có một bài viết về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=edition&lang=en-GB&ipa=%2F%C9%AA%CB%88d%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=edition&lang=en-US&ipa=%2F%C9%AA%CB%88d%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_133","topic":"Cultural and Historical Exchange","word":"egypt","pos":"(n)","ipa":"/ˈiː.dʒɪpt/","defVi":"Ai Cập","defEn":"a country in northeastern Africa famous for its ancient pyramids and long history","examples":["Many tourists visit [Egypt] each year to see the Great Pyramids of Giza. (=Dịch: Nhiều du khách đến thăm Ai Cập mỗi năm để chiêm ngưỡng Đại kim tự tháp Giza.)","The Suez Canal in [Egypt] is one of the most vital shipping routes in the world. (=Dịch: Kênh đào Suez ở Ai Cập là một trong những tuyến đường vận tải biển quan trọng nhất trên thế giới.)","Archaeologists recently uncovered a new tomb in southern [Egypt]. (=Dịch: Các nhà khảo cổ học gần đây đã khai quật được một ngôi mộ mới ở miền nam Ai Cập.)"],"ukAudio":"/ai_services/tts3/?q=egypt&lang=en-GB&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=egypt&lang=en-US&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F"},{"id":"lv_4_134","topic":"Cultural and Historical Exchange","word":"eighteenth","pos":"(adj)","ipa":"/ˌeɪˈtiːnθ/","defVi":"thứ mười tám","defEn":"constituting number eighteen in a sequence; 18th","examples":["He celebrated his [eighteenth] birthday with a big gathering of friends. (=Dịch: Anh ấy đã kỷ niệm sinh nhật lần thứ mười tám của mình bằng một buổi tụ tập bạn bè lớn.)","The museum houses many rare paintings from the [eighteenth] century. (=Dịch: Bảo tàng lưu giữ nhiều bức tranh quý hiếm từ thế kỷ thứ mười tám.)","Our office is located on the [eighteenth] floor of the tower. (=Dịch: Văn phòng của chúng tôi nằm ở tầng thứ mười tám của tòa tháp.)"],"ukAudio":"/ai_services/tts3/?q=eighteenth&lang=en-GB&ipa=%2F%CB%8Ce%C9%AA%CB%88ti%CB%90n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=eighteenth&lang=en-US&ipa=%2F%CB%8Ce%C9%AA%CB%88ti%CB%90n%CE%B8%2F"},{"id":"lv_4_135","topic":"Cultural and Historical Exchange","word":"emotion","pos":"(n)","ipa":"/ɪˈmoʊ.ʃən/","defVi":"cảm xúc, sự xúc động","defEn":"a strong feeling deriving from one's circumstances, mood, or relationships","examples":["Music has the power to evoke deep [emotion] in the listener. (=Dịch: Âm nhạc có sức mạnh gợi lên cảm xúc sâu sắc nơi người nghe.)","He tried to hide his [emotion] during the farewell ceremony. (=Dịch: Anh ấy đã cố gắng che giấu cảm xúc của mình trong buổi lễ chia tay.)","Fear is a natural [emotion] that helps humans respond to danger. (=Dịch: Sợ hãi là một cảm xúc tự nhiên giúp con người phản ứng trước sự nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=emotion&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emotion&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_4_136","topic":"Cultural and Historical Exchange","word":"emotional","pos":"(adj)","ipa":"/ɪˈmoʊ.ʃən.əl/","defVi":"thuộc về cảm xúc, dễ xúc động","defEn":"relating to or showing strong feelings","examples":["Listening to music often provides good [emotional] support during difficult times. (=Dịch: Nghe nhạc thường mang lại sự hỗ trợ tinh thần tốt trong những thời điểm khó khăn.)","She gave an [emotional] speech when accepting the prestigious award. (=Dịch: Cô đã có một bài phát biểu đầy cảm xúc khi nhận giải thưởng danh giá.)","Children need a stable [emotional] environment to grow up healthy. (=Dịch: Trẻ em cần một môi trường cảm xúc ổn định để lớn lên khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=emotional&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=emotional&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_4_137","topic":"Cultural and Historical Exchange","word":"empire","pos":"(n)","ipa":"/ˈɛm.paɪ.ɚ/","defVi":"đế chế, đế quốc","defEn":"a large group of countries or regions ruled by a single leader or government","examples":["The Roman [empire] once stretched across much of Europe and North Africa. (=Dịch: Đế chế La Mã từng trải dài khắp phần lớn châu Âu và Bắc Phi.)","Historians study the factors that led to the collapse of the ancient [empire]. (=Dịch: Các nhà sử học nghiên cứu những yếu tố dẫn đến sự sụp đổ của đế chế cổ đại.)","He built a global business [empire] starting from a small family shop. (=Dịch: Ông đã xây dựng một đế chế kinh doanh toàn cầu bắt đầu từ một cửa hàng nhỏ của gia đình.)"],"ukAudio":"/ai_services/tts3/?q=empire&lang=en-GB&ipa=%2F%CB%88%C9%9Bm.pa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=empire&lang=en-US&ipa=%2F%CB%88%C9%9Bm.pa%C9%AA.%C9%9A%2F"},{"id":"lv_4_138","topic":"Cultural and Historical Exchange","word":"enemy","pos":"(n)","ipa":"/ˈɛn.ə.mi/","defVi":"kẻ thù, quân địch","defEn":"a person, group, or country that is hostile to another and opposes them actively","examples":["The two nations stopped fighting and agreed not to view each other as an [enemy]. (=Dịch: Hai quốc gia đã ngừng giao tranh và đồng ý không coi nhau là kẻ thù.)","Lack of sleep can be the greatest [enemy] of good academic performance. (=Dịch: Thiếu ngủ có thể là kẻ thù lớn nhất đối với kết quả học tập tốt.)","Soldiers defended their base against the approaching [enemy]. (=Dịch: Các binh sĩ đã bảo vệ căn cứ của họ trước kẻ thù đang tiến đến gần.)"],"ukAudio":"/ai_services/tts3/?q=enemy&lang=en-GB&ipa=%2F%CB%88%C9%9Bn.%C9%99.mi%2F","usAudio":"/ai_services/tts3/?q=enemy&lang=en-US&ipa=%2F%CB%88%C9%9Bn.%C9%99.mi%2F"},{"id":"lv_4_139","topic":"Cultural and Historical Exchange","word":"engraving","pos":"(n)","ipa":"/ɪnˈɡreɪ.vɪŋ/","defVi":"bản khắc, nghệ thuật chạm khắc","defEn":"a design or picture cut onto a hard surface, or the process of making such designs","examples":["The delicate [engraving] on the silver ring depicted two flying birds. (=Dịch: Hình chạm khắc tinh xảo trên chiếc nhẫn bạc mô tả hai chú chim đang bay.)","He collected 19th-century [engraving] prints depicting historical events. (=Dịch: Ông đã sưu tầm các bản in tranh khắc thế kỷ 19 mô tả các sự kiện lịch sử.)","Archaeologists found a prehistoric [engraving] on the cave wall. (=Dịch: Các nhà khảo cổ học đã tìm thấy một hình khắc thời tiền sử trên vách hang động.)"],"ukAudio":"/ai_services/tts3/?q=engraving&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1re%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=engraving&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1re%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_4_140","topic":"Cultural and Historical Exchange","word":"enormously","pos":"(adv)","ipa":"/ɪˈnɔːr.məs.li/","defVi":"vô cùng, cực kỳ, rất nhiều","defEn":"extremely; to a very large extent or degree","examples":["The new marketing campaign has [enormously] increased our sales. (=Dịch: Chiến dịch tiếp thị mới đã làm tăng doanh số bán hàng của chúng tôi một cách vô cùng to lớn.)","She enjoyed the international exchange program [enormously]. (=Dịch: Cô ấy đã vô cùng thích thú với chương trình trao đổi quốc tế.)","Technology has made communication [enormously] easier than before. (=Dịch: Công nghệ đã làm cho việc giao tiếp trở nên dễ dàng hơn trước rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=enormously&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=enormously&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F"},{"id":"lv_4_141","topic":"Cultural and Historical Exchange","word":"entire","pos":"(adj)","ipa":"/ɪnˈtaɪ.ɚ/","defVi":"toàn bộ, toàn thể, trọn vẹn","defEn":"including everything or everyone; whole and complete","examples":["He spent the [entire] afternoon cleaning and organizing his room. (=Dịch: Anh ấy đã dành toàn bộ buổi chiều để dọn dẹp và sắp xếp phòng của mình.)","The [entire] staff attended the annual safety training workshop. (=Dịch: Toàn bộ nhân viên đã tham dự hội thảo đào tạo an toàn thường niên.)","Severe storms knocked out power for the [entire] city. (=Dịch: Những cơn bão dữ dội đã làm mất điện toàn bộ thành phố.)"],"ukAudio":"/ai_services/tts3/?q=entire&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=entire&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_4_142","topic":"Cultural and Historical Exchange","word":"entrepreneur","pos":"(n)","ipa":"/ˌɑːn.trə.prəˈnʊr/","defVi":"doanh nhân, người khởi nghiệp","defEn":"a person who sets up a business, taking on financial risks in the hope of profit","examples":["The young [entrepreneur] secured funding for her innovative educational technology startup. (=Dịch: Nữ doanh nhân trẻ đã đảm bảo được nguồn vốn cho công ty khởi nghiệp công nghệ giáo dục đổi mới sáng tạo của mình.)","Every successful [entrepreneur] must be willing to learn from repeated failures. (=Dịch: Mọi doanh nhân thành đạt đều phải sẵn sàng học hỏi từ những thất bại lặp đi lặp lại.)","The university provides specialized workshops to help each aspiring [entrepreneur] develop practical skills. (=Dịch: Trường đại học cung cấp các buổi hội thảo chuyên đề để giúp mỗi doanh nhân đầy tham vọng phát triển các kỹ năng thực tế.)"],"ukAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%CA%8Ar%2F"},{"id":"lv_4_143","topic":"Cultural and Historical Exchange","word":"european","pos":"(adj)","ipa":"/ˌjʊr.əˈpiː.ən/","defVi":"thuộc về châu Âu","defEn":"belonging to or relating to the continent of Europe or its people","examples":["She decided to study [european] history during her semester abroad. (=Dịch: Cô ấy quyết định theo học lịch sử châu Âu trong học kỳ du học của mình.)","Many [european] countries have adopted strong environmental protection policies. (=Dịch: Nhiều quốc gia châu Âu đã áp dụng các chính sách bảo vệ môi trường nghiêm ngặt.)","The museum houses a remarkable collection of classical [european] paintings. (=Dịch: Bảo tàng lưu giữ một bộ sưu tập tranh cổ điển châu Âu đáng chú ý.)"],"ukAudio":"/ai_services/tts3/?q=european&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=european&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F"},{"id":"lv_4_144","topic":"Cultural and Historical Exchange","word":"europeans","pos":"(n)","ipa":"/ˌjʊr.əˈpiː.ənz/","defVi":"người châu Âu","defEn":"people who are native to or inhabitants of Europe","examples":["Many [europeans] speak more than two languages fluently. (=Dịch: Nhiều người châu Âu nói trôi chảy hơn hai ngôn ngữ.)","Early [europeans] traded goods such as silk and spices along ancient routes. (=Dịch: Những người châu Âu thời kỳ đầu đã buôn bán các hàng hóa như lụa và gia vị dọc theo các tuyến đường cổ đại.)","The survey compared dietary habits among Asians and [europeans]. (=Dịch: Cuộc khảo sát đã so sánh thói quen ăn uống giữa người châu Á và người châu Âu.)"],"ukAudio":"/ai_services/tts3/?q=europeans&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F","usAudio":"/ai_services/tts3/?q=europeans&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F"},{"id":"lv_4_145","topic":"Cultural and Historical Exchange","word":"evolution","pos":"(n)","ipa":"/ˌɛv.əˈluː.ʃən/","defVi":"sự tiến hóa, sự phát triển dần dần","defEn":"the gradual process of change and development over time, especially in living organisms","examples":["Darwin is best known for his theory of biological [evolution]. (=Dịch: Darwin nổi tiếng nhất với thuyết [tiến hóa] sinh học.)","The museum exhibits the [evolution] of mobile phones over the past decades. (=Dịch: Bảo tàng trưng bày [sự phát triển] của điện thoại di động qua các thập kỷ qua.)","Language undergoes a continuous [evolution] as new words emerge. (=Dịch: Ngôn ngữ trải qua một [quá trình biến đổi] liên tục khi các từ mới xuất hiện.)"],"ukAudio":"/ai_services/tts3/?q=evolution&lang=en-GB&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evolution&lang=en-US&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_146","topic":"Cultural and Historical Exchange","word":"evolve","pos":"(v)","ipa":"/ɪˈvɑːlv/","defVi":"tiến hóa, phát triển dần","defEn":"to develop gradually, especially from a simple to a more complex form","examples":["Scientists study how modern animals [evolve] over millions of years. (=Dịch: Các nhà khoa học nghiên cứu cách các loài động vật hiện đại tiến hóa qua hàng triệu năm.)","The company must [evolve] its business model to survive in the digital age. (=Dịch: Công ty phải phát triển mô hình kinh doanh của mình để tồn tại trong thời đại kỹ thuật số.)","Her initial idea began to [evolve] into a full-scale research project. (=Dịch: Ý tưởng ban đầu của cô ấy đã bắt đầu phát triển thành một dự án nghiên cứu toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=evolve&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F","usAudio":"/ai_services/tts3/?q=evolve&lang=en-US&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F"},{"id":"lv_4_147","topic":"Cultural and Historical Exchange","word":"excavation","pos":"(n)","ipa":"/ˌɛk.skəˈveɪ.ʃən/","defVi":"sự khai quật, hoạt động đào bới khảo cổ","defEn":"the process of digging in the ground to look for old objects or buildings","examples":["The archaeological [excavation] uncovered the ruins of an ancient temple. (=Dịch: Cuộc khai quật khảo cổ học đã phát hiện ra tàn tích của một ngôi đền cổ.)","Workers began the [excavation] for the new building's foundation yesterday. (=Dịch: Các công nhân đã bắt đầu việc đào móng cho tòa nhà mới vào ngày hôm qua.)","Several rare coins were found during the recent [excavation] near the river. (=Dịch: Một số đồng xu hiếm đã được tìm thấy trong cuộc khai quật gần đây ở cạnh bờ sông.)"],"ukAudio":"/ai_services/tts3/?q=excavation&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sk%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excavation&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sk%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_148","topic":"Cultural and Historical Exchange","word":"exhibit","pos":"(n)","ipa":"/ɪɡˈzɪb.ɪt/","defVi":"hiện vật, vật trưng bày, cuộc triển lãm","defEn":"an object or collection of objects shown publicly in a museum or trade fair","examples":["The interactive science [exhibit] attracted thousands of curious visitors. (=Dịch: Khu triển lãm khoa học tương tác đã thu hút hàng ngàn du khách hiếu kỳ.)","Please do not touch any [exhibit] inside the historical hall. (=Dịch: Vui lòng không chạm vào bất kỳ hiện vật trưng bày nào bên trong sảnh lịch sử.)","The museum opened a new permanent [exhibit] dedicated to dinosaur fossils. (=Dịch: Bảo tàng đã mở một khu trưng bày thường trực mới dành riêng cho các hóa thạch khủng long.)"],"ukAudio":"/ai_services/tts3/?q=exhibit&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exhibit&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F"},{"id":"lv_4_149","topic":"Cultural and Historical Exchange","word":"exile","pos":"(n)","ipa":"/ˈɛɡ.zaɪl/","defVi":"sự lưu đày, tình trạng sống lưu vong","defEn":"a situation in which someone is forced to leave their country, often for political reasons","examples":["The political leader spent over ten years in [exile] before returning home safely. (=Dịch: Nhà lãnh đạo chính trị đã trải qua hơn mười năm sống lưu vong trước khi trở về quê hương an toàn.)","Many famous writers produced their greatest masterpieces while living in [exile]. (=Dịch: Nhiều nhà văn nổi tiếng đã sáng tác những kiệt tác vĩ đại nhất của mình khi sống lưu vong.)","He was forced into [exile] after opposing the policies of the government. (=Dịch: Ông buộc phải đi lưu vong sau khi phản đối các chính sách của chính phủ.)"],"ukAudio":"/ai_services/tts3/?q=exile&lang=en-GB&ipa=%2F%CB%88%C9%9B%C9%A1.za%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=exile&lang=en-US&ipa=%2F%CB%88%C9%9B%C9%A1.za%C9%AAl%2F"},{"id":"lv_4_150","topic":"Cultural and Historical Exchange","word":"exploit","pos":"(v)","ipa":"/ɪkˈsplɔɪt/","defVi":"khai thác; bóc lột","defEn":"to make use of something effectively, or to treat someone unfairly for one's own benefit","examples":["The company seeks to [exploit] renewable energy sources to reduce costs. (=Dịch: Công ty tìm cách khai thác các nguồn năng lượng tái tạo để giảm thiểu chi phí.)","Strict laws are needed to prevent employers from attempting to [exploit] workers. (=Dịch: Cần có các luật lệ nghiêm ngặt để ngăn chặn người sử dụng lao động có ý định bóc lột người lao động.)","Smart investors know how to [exploit] new market opportunities quickly. (=Dịch: Các nhà đầu tư thông minh biết cách tận dụng nhanh chóng các cơ hội thị trường mới.)"],"ukAudio":"/ai_services/tts3/?q=exploit&lang=en-GB&ipa=%2F%C9%AAk%CB%88spl%C9%94%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exploit&lang=en-US&ipa=%2F%C9%AAk%CB%88spl%C9%94%C9%AAt%2F"},{"id":"lv_4_151","topic":"Cultural and Historical Exchange","word":"external","pos":"(adj)","ipa":"/ɪkˈstɜr.nəl/","defVi":"ở bên ngoài, ngoại cảnh hoặc đối ngoại","defEn":"connected with or located on the outside of something","examples":["The [external] walls of the building need a fresh coat of paint. (=Dịch: Các bức tường bên ngoài của tòa nhà cần một lớp sơn mới.)","A company may hire an [external] consultant to evaluate its performance. (=Dịch: Một công ty có thể thuê một chuyên gia tư vấn bên ngoài để đánh giá hiệu quả hoạt động của mình.)","Students are sometimes evaluated by an [external] examiner. (=Dịch: Học sinh đôi khi được đánh giá bởi một giám khảo bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9Cr.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9Cr.n%C9%99l%2F"},{"id":"lv_4_152","topic":"Cultural and Historical Exchange","word":"fashionable","pos":"(adj)","ipa":"/ˈfæʃ.nə.bəl/","defVi":"hợp thời trang, sành điệu, theo xu hướng","defEn":"popular, stylish, and currently in fashion","examples":["She always wears [fashionable] clothes that catch everyone's attention. (=Dịch: Cô ấy luôn mặc những bộ quần áo thời thượng thu hút sự chú ý của mọi người.)","The downtown district is famous for its [fashionable] cafes and boutiques. (=Dịch: Khu vực trung tâm thành phố nổi tiếng với các quán cà phê và cửa hàng thời trang sành điệu.)","Eating organic food has become increasingly [fashionable] among young urbanites. (=Dịch: Ăn thực phẩm hữu cơ đang ngày càng trở thành xu hướng phổ biến trong giới trẻ thành thị.)"],"ukAudio":"/ai_services/tts3/?q=fashionable&lang=en-GB&ipa=%2F%CB%88f%C3%A6%CA%83.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fashionable&lang=en-US&ipa=%2F%CB%88f%C3%A6%CA%83.n%C9%99.b%C9%99l%2F"},{"id":"lv_4_153","topic":"Cultural and Historical Exchange","word":"feather","pos":"(n)","ipa":"/ˈfɛð.ɚ/","defVi":"lông vũ","defEn":"one of the soft, light things that grow from and cover a bird's skin","examples":["She found a beautiful blue [feather] on the forest path. (=Dịch: Cô ấy tìm thấy một chiếc lông vũ màu xanh tuyệt đẹp trên con đường trong rừng.)","Penguins have dense [feather] layers that keep them warm in freezing water. (=Dịch: Chim cánh cụt có các lớp lông vũ dày giúp giữ ấm cho chúng trong làn nước băng giá.)","The traditional pillow was filled with soft duck [feather] stuffing. (=Dịch: Chiếc gối truyền thống được nhồi bằng lông vịt mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=feather&lang=en-GB&ipa=%2F%CB%88f%C9%9B%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=feather&lang=en-US&ipa=%2F%CB%88f%C9%9B%C3%B0.%C9%9A%2F"},{"id":"lv_4_154","topic":"Cultural and Historical Exchange","word":"fieldwork","pos":"(n)","ipa":"/ˈfild.wɝk/","defVi":"công tác điền dã, nghiên cứu thực địa","defEn":"research or study done in the real world rather than in a classroom or laboratory","examples":["The biology students spent two weeks doing [fieldwork] in the rainforest. (=Dịch: Các sinh viên ngành sinh học đã dành hai tuần thực hiện nghiên cứu thực địa trong rừng nhiệt đới.)","Conducting [fieldwork] helped the researchers collect primary data directly from residents. (=Dịch: Việc tiến hành nghiên cứu thực địa đã giúp các nhà nghiên cứu thu thập dữ liệu sơ cấp trực tiếp từ người dân.)","Her doctoral dissertation relied heavily on anthropological [fieldwork]. (=Dịch: Luận án tiến sĩ của cô dựa nhiều vào nghiên cứu thực địa nhân chủng học.)"],"ukAudio":"/ai_services/tts3/?q=fieldwork&lang=en-GB&ipa=%2F%CB%88fild.w%C9%9Dk%2F","usAudio":"/ai_services/tts3/?q=fieldwork&lang=en-US&ipa=%2F%CB%88fild.w%C9%9Dk%2F"},{"id":"lv_4_155","topic":"Cultural and Historical Exchange","word":"fifteenth","pos":"(adj)","ipa":"/ˌfɪfˈtinθ/","defVi":"thứ mười lăm","defEn":"positioned in the place that corresponds to number fifteen","examples":["Today marks the [fifteenth] anniversary of the company's founding. (=Dịch: Hôm nay đánh dấu kỷ niệm lần thứ mười lăm ngày thành lập công ty.)","Her office is located on the [fifteenth] floor of the commercial tower. (=Dịch: Văn phòng của cô nằm ở tầng mười lăm của tòa tháp thương mại.)","He finished in [fifteenth] place out of hundreds of marathon runners. (=Dịch: Anh đã về đích ở vị trí thứ mười lăm trong số hàng trăm vận động viên chạy marathon.)"],"ukAudio":"/ai_services/tts3/?q=fifteenth&lang=en-GB&ipa=%2F%CB%8Cf%C9%AAf%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fifteenth&lang=en-US&ipa=%2F%CB%8Cf%C9%AAf%CB%88tin%CE%B8%2F"},{"id":"lv_4_156","topic":"Cultural and Historical Exchange","word":"firework","pos":"(n)","ipa":"/ˈfaɪr.wɝːk/","defVi":"pháo hoa","defEn":"a small device containing chemicals that burns or explodes to make loud noises and bright colorful lights in the sky","examples":["A spectacular [firework] lit up the night sky during the festival. (=Dịch: Một chùm pháo hoa ngoạn mục đã thắp sáng bầu trời đêm trong suốt lễ hội.)","Setting off a [firework] indoors is extremely dangerous and strictly prohibited. (=Dịch: Đốt pháo hoa trong nhà là cực kỳ nguy hiểm và bị nghiêm cấm hoàn toàn.)","The grand finale featured a massive [firework] that amazed the entire crowd. (=Dịch: Màn kết thúc hoành tráng nổi bật với chùm pháo hoa khổng lồ khiến toàn bộ đám đông kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=firework&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=firework&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%C9%9D%CB%90k%2F"},{"id":"lv_4_157","topic":"Cultural and Historical Exchange","word":"flock","pos":"(v)","ipa":"/flɑːk/","defVi":"đổ xô, tụ tập đông đúc","defEn":"to gather or move together in large numbers","examples":["Thousands of tourists [flock] to the coastal town every summer. (=Dịch: Hàng ngàn du khách đổ xô về thị trấn ven biển vào mỗi mùa hè.)","Shoppers will [flock] to the mall during the annual clearance sale. (=Dịch: Người mua sắm sẽ đổ xô đến trung tâm thương mại trong đợt giảm giá xả kho hàng năm.)","Fans began to [flock] outside the stadium hours before the concert started. (=Dịch: Người hâm mộ bắt đầu tụ tập đông đảo bên ngoài sân vận động vài giờ trước khi buổi hòa nhạc bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=flock&lang=en-GB&ipa=%2Ffl%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=flock&lang=en-US&ipa=%2Ffl%C9%91%CB%90k%2F"},{"id":"lv_4_158","topic":"Cultural and Historical Exchange","word":"flute","pos":"(n)","ipa":"/fluːt/","defVi":"cây sáo, ống sáo","defEn":"a musical wind instrument played by blowing across a hole near one end","examples":["She has been practicing the [flute] since she was eight years old. (=Dịch: Cô ấy đã luyện tập thổi sáo từ khi mới tám tuổi.)","The orchestra features a solo performance by the principal [flute] player. (=Dịch: Dàn nhạc có một màn độc tấu của nghệ sĩ sáo chính.)","He carefully packed his silver [flute] into its velvet-lined case. (=Dịch: Anh ấy cẩn thận cất cây sáo bạc của mình vào chiếc hộp lót nhung.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflu%CB%90t%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflu%CB%90t%2F"},{"id":"lv_4_159","topic":"Cultural and Historical Exchange","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập lại","defEn":"to bend something flexible over on itself so that one part covers another","examples":["Please [fold] your clothes neatly before putting them into the suitcase. (=Dịch: Vui lòng gấp quần áo gọn gàng trước khi cho vào vali.)","He decided to [fold] the map and put it in his pocket. (=Dịch: Anh ấy quyết định gấp tấm bản đồ lại và cho vào túi.)","The young boy learned how to [fold] paper into complex origami shapes. (=Dịch: Cậu bé đã học cách gấp giấy thành các hình origami phức tạp.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_4_160","topic":"Cultural and Historical Exchange","word":"footbridge","pos":"(n)","ipa":"/ˈfʊt.brɪdʒ/","defVi":"cầu đi bộ","defEn":"a narrow bridge designed only for pedestrians","examples":["Pedestrians can safely cross the busy highway using the new [footbridge]. (=Dịch: Người đi bộ có thể băng qua đường cao tốc đông đúc một cách an toàn bằng cách sử dụng cầu đi bộ mới.)","A charming wooden [footbridge] spans the small stream in the park. (=Dịch: Một cây cầu đi bộ bằng gỗ duyên dáng bắc ngang qua con suối nhỏ trong công viên.)","The city plans to construct a covered [footbridge] near the train station. (=Dịch: Thành phố có kế hoạch xây dựng một cây cầu đi bộ có mái che gần nhà ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=footbridge&lang=en-GB&ipa=%2F%CB%88f%CA%8At.br%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=footbridge&lang=en-US&ipa=%2F%CB%88f%CA%8At.br%C9%AAd%CA%92%2F"},{"id":"lv_4_161","topic":"Cultural and Historical Exchange","word":"footprint","pos":"(n)","ipa":"/ˈfʊt.prɪnt/","defVi":"dấu chân; dấu ấn tác động môi trường","defEn":"a mark left by a foot or shoe, or the amount of impact something has on the environment","examples":["We followed a trail of fresh [footprints] in the snow until we reached the cabin. (=Dịch: Chúng tôi đã lần theo dấu vết của những dấu chân mới trên tuyết cho đến khi tới được căn nhà gỗ.)","Many companies are striving to reduce their environmental [footprint] by using renewable energy. (=Dịch: Nhiều công ty đang nỗ lực giảm thiểu tác động đến môi trường bằng cách sử dụng năng lượng tái tạo.)","The giant dinosaur left a deep [footprint] that fossilized over millions of years. (=Dịch: Con khủng long khổng lồ đã để lại một dấu chân sâu và hóa thạch qua hàng triệu năm.)"],"ukAudio":"/ai_services/tts3/?q=footprint&lang=en-GB&ipa=%2F%CB%88f%CA%8At.pr%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=footprint&lang=en-US&ipa=%2F%CB%88f%CA%8At.pr%C9%AAnt%2F"},{"id":"lv_4_162","topic":"Cultural and Historical Exchange","word":"forecast","pos":"(v)","ipa":"/ˈfɔrˌkæst/","defVi":"dự báo, dự đoán","defEn":"to predict what will happen in the future, especially regarding weather or business","examples":["Meteorologists [forecast] heavy snow for the northern regions this weekend. (=Dịch: Các nhà khí tượng học dự báo tuyết rơi dày ở các khu vực phía bắc vào cuối tuần này.)","Economists [forecast] a moderate growth rate for the coming quarter. (=Dịch: Các nhà kinh tế dự báo tốc độ tăng trưởng vừa phải cho quý tới.)","It is difficult to [forecast] how consumers will react to the new tax policy. (=Dịch: Rất khó để dự báo người tiêu dùng sẽ phản ứng như thế nào trước chính sách thuế mới.)"],"ukAudio":"/ai_services/tts3/?q=forecast&lang=en-GB&ipa=%2F%CB%88f%C9%94r%CB%8Ck%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=forecast&lang=en-US&ipa=%2F%CB%88f%C9%94r%CB%8Ck%C3%A6st%2F"},{"id":"lv_4_163","topic":"Cultural and Historical Exchange","word":"formation","pos":"(n)","ipa":"/fɔːrˈmeɪ.ʃən/","defVi":"sự hình thành, cấu trúc, đội hình","defEn":"the process of creating or developing something, or the way something is arranged","examples":["Geologists study the [formation] of mountain ranges over millions of years. (=Dịch: Các nhà địa chất nghiên cứu sự hình thành của các dãy núi qua hàng triệu năm.)","The aircraft flew in a triangular [formation] during the military airshow. (=Dịch: Những chiếc máy bay đã bay theo đội hình tam giác trong suốt buổi trình diễn hàng không quân sự.)","Good parenting plays a vital role in the [formation] of a child's character. (=Dịch: Cách nuôi dạy con tốt đóng vai trò quan trọng trong sự hình thành nhân cách của một đứa trẻ.)"],"ukAudio":"/ai_services/tts3/?q=formation&lang=en-GB&ipa=%2Ff%C9%94%CB%90r%CB%88me%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=formation&lang=en-US&ipa=%2Ff%C9%94%CB%90r%CB%88me%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_164","topic":"Cultural and Historical Exchange","word":"fortune","pos":"(n)","ipa":"/ˈfɔr.tʃən/","defVi":"tài sản lớn, gia tài","defEn":"a large amount of money or valuable possessions","examples":["He made a vast [fortune] by investing early in technology companies. (=Dịch: Anh ấy đã kiếm được một gia tài khổng lồ nhờ đầu tư sớm vào các công ty công nghệ.)","Buying a house in the city center costs a small [fortune] nowadays. (=Dịch: Mua một ngôi nhà ở trung tâm thành phố ngày nay tốn cả một gia tài.)","She inherited a massive [fortune] from her late grandfather. (=Dịch: Cô ấy đã thừa kế một khối tài sản khổng lồ từ người ông quá cố của mình.)"],"ukAudio":"/ai_services/tts3/?q=fortune&lang=en-GB&ipa=%2F%CB%88f%C9%94r.t%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fortune&lang=en-US&ipa=%2F%CB%88f%C9%94r.t%CA%83%C9%99n%2F"},{"id":"lv_4_165","topic":"Cultural and Historical Exchange","word":"found","pos":"(v)","ipa":"/faʊnd/","defVi":"thành lập, sáng lập","defEn":"to establish an organization, institution, or company","examples":["The university was [found]ed by a group of local scholars in 1850. (=Dịch: Trường đại học được thành lập bởi một nhóm học giả địa phương vào năm 1850.)","They hope to [found] a non-profit organization to support underprivileged children. (=Dịch: Họ hy vọng sẽ thành lập một tổ chức phi lợi nhuận để hỗ trợ trẻ em có hoàn cảnh khó khăn.)","The settlers arrived in the valley and decided to [found] a new town. (=Dịch: Những người khai hoang đã đến thung lũng và quyết định thành lập một thị trấn mới.)"],"ukAudio":"/ai_services/tts3/?q=found&lang=en-GB&ipa=%2Ffa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=found&lang=en-US&ipa=%2Ffa%CA%8And%2F"},{"id":"lv_4_166","topic":"Cultural and Historical Exchange","word":"foundation","pos":"(n)","ipa":"/faʊnˈdeɪ.ʃən/","defVi":"nền tảng, móng nhà, quỹ tài trợ","defEn":"the basic structure, idea, or principle on which something is built or developed","examples":["Trust and communication are the [foundation] of any healthy relationship. (=Dịch: Sự tin tưởng và giao tiếp là nền tảng của bất kỳ mối quan hệ lành mạnh nào.)","The builders laid a solid concrete [foundation] for the new skyscraper. (=Dịch: Những người thợ xây đã đổ một nền móng bê tông vững chắc cho tòa nhà chọc trời mới.)","She established a charitable [foundation] to help underprivileged children. (=Dịch: Cô ấy đã thành lập một quỹ từ thiện để giúp đỡ những trẻ em có hoàn cảnh khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=foundation&lang=en-GB&ipa=%2Ffa%CA%8An%CB%88de%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=foundation&lang=en-US&ipa=%2Ffa%CA%8An%CB%88de%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_167","topic":"Cultural and Historical Exchange","word":"fourth","pos":"(adj)","ipa":"/fɔːrθ/","defVi":"thứ tư (trong chuỗi thứ tự)","defEn":"constituting number four in a sequence; 4th","examples":["This is the [fourth] time this month that the train has been delayed. (=Dịch: Đây là lần thứ tư trong tháng này chuyến tàu bị hoãn.)","She finished in [fourth] place in the international swimming competition. (=Dịch: Cô ấy về đích ở vị trí thứ tư trong cuộc thi bơi lội quốc tế.)","Our office is located on the [fourth] floor of the commercial building. (=Dịch: Văn phòng của chúng tôi nằm ở tầng bốn của tòa nhà thương mại.)"],"ukAudio":"/ai_services/tts3/?q=fourth&lang=en-GB&ipa=%2Ff%C9%94%CB%90r%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fourth&lang=en-US&ipa=%2Ff%C9%94%CB%90r%CE%B8%2F"},{"id":"lv_4_168","topic":"Cultural and Historical Exchange","word":"fragile","pos":"(adj)","ipa":"/ˈfrædʒ.əl/","defVi":"dễ vỡ, mỏng manh, yếu ớt","defEn":"easily broken, damaged, or harmed","examples":["Please handle the box with care because it contains [fragile] glassware. (=Dịch: Xin vui lòng nhẹ tay với chiếc hộp này vì bên trong chứa đồ thủy tinh dễ vỡ.)","The region's [fragile] ecosystem is under severe threat from pollution. (=Dịch: Hệ sinh thái mỏng manh của khu vực đang bị đe dọa nghiêm trọng bởi tình trạng ô nhiễm.)","The two countries signed a [fragile] peace agreement after months of talks. (=Dịch: Hai quốc gia đã ký một thỏa thuận hòa bình mong manh sau nhiều tháng đàm phán.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F"},{"id":"lv_4_169","topic":"Cultural and Historical Exchange","word":"frame","pos":"(n)","ipa":"/freɪm/","defVi":"khung (tranh, ảnh, cửa, nhà), sườn kết cấu","defEn":"a rigid structure that surrounds or supports something such as a picture, window, or building","examples":["She chose an elegant wooden [frame] for her family portrait. (=Dịch: Cô ấy đã chọn một chiếc khung gỗ trang nhã cho bức ảnh chân dung gia đình mình.)","The steel [frame] of the skyscraper was erected in just three months. (=Dịch: Khung thép của tòa nhà chọc trời đã được dựng lên chỉ trong vòng ba tháng.)","A broken bicycle [frame] made it impossible for him to continue the race. (=Dịch: Khung xe đạp bị gãy khiến anh ấy không thể tiếp tục cuộc đua.)"],"ukAudio":"/ai_services/tts3/?q=frame&lang=en-GB&ipa=%2Ffre%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=frame&lang=en-US&ipa=%2Ffre%C9%AAm%2F"},{"id":"lv_4_170","topic":"Cultural and Historical Exchange","word":"france","pos":"(n)","ipa":"/fræns/","defVi":"nước Pháp","defEn":"a country in Western Europe known for its art, cuisine, and history","examples":["Paris, the capital of [France], attracts millions of international travelers. (=Dịch: Paris, thủ đô của nước Pháp, thu hút hàng triệu du khách quốc tế.)","[France] is internationally renowned for its fashion, wine, and culinary culture. (=Dịch: Nước Pháp nổi tiếng quốc tế về thời trang, rượu vang và văn hóa ẩm thực.)","She spent a semester studying literature in [France]. (=Dịch: Cô ấy đã dành một học kỳ để theo học ngành văn học ở Pháp.)"],"ukAudio":"/ai_services/tts3/?q=france&lang=en-GB&ipa=%2Ffr%C3%A6ns%2F","usAudio":"/ai_services/tts3/?q=france&lang=en-US&ipa=%2Ffr%C3%A6ns%2F"},{"id":"lv_4_171","topic":"Cultural and Historical Exchange","word":"friendship","pos":"(n)","ipa":"/ˈfrɛnd.ʃɪp/","defVi":"tình bạn, tình hữu nghị","defEn":"a close and supportive relationship between friends","examples":["Their strong [friendship] developed during their first year of studying abroad. (=Dịch: Tình bạn bền chặt của họ đã phát triển trong suốt năm đầu tiên đi du học.)","True [friendship] requires mutual trust, open communication, and emotional support. (=Dịch: Tình bạn đích thực đòi hỏi sự tin tưởng lẫn nhau, giao tiếp cởi mở và hỗ trợ về mặt cảm xúc.)","The international exchange program aims to build lasting [friendship] between students of both nations. (=Dịch: Chương trình trao đổi quốc tế nhằm mục đích xây dựng tình bạn lâu dài giữa học sinh, sinh viên của cả hai quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=friendship&lang=en-GB&ipa=%2F%CB%88fr%C9%9Bnd.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=friendship&lang=en-US&ipa=%2F%CB%88fr%C9%9Bnd.%CA%83%C9%AAp%2F"},{"id":"lv_4_172","topic":"Cultural and Historical Exchange","word":"furnish","pos":"(v)","ipa":"/ˈfɜr.nɪʃ/","defVi":"trang bị nội thất, cung cấp","defEn":"to put furniture into a room or building, or to supply something needed","examples":["It will cost a lot of money to [furnish] the new apartment. (=Dịch: Sẽ tốn rất nhiều tiền để trang bị nội thất cho căn hộ mới.)","The company agreed to [furnish] all the necessary equipment for the project. (=Dịch: Công ty đã đồng ý cung cấp mọi thiết bị cần thiết cho dự án.)","They decided to [furnish] the guest room with modern wooden pieces. (=Dịch: Họ quyết định bài trí phòng khách bằng những món đồ gỗ hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=furnish&lang=en-GB&ipa=%2F%CB%88f%C9%9Cr.n%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=furnish&lang=en-US&ipa=%2F%CB%88f%C9%9Cr.n%C9%AA%CA%83%2F"},{"id":"lv_4_173","topic":"Cultural and Historical Exchange","word":"garment","pos":"(n)","ipa":"/ˈɡɑːr.mənt/","defVi":"quần áo, trang phục","defEn":"an item of clothing","examples":["The boutique specializes in silk [garment] designs for formal events. (=Dịch: Cửa hàng thời trang này chuyên về các thiết kế trang phục lụa cho các sự kiện trang trọng.)","Workers in the [garment] industry are demanding better working conditions. (=Dịch: Các công nhân trong ngành may mặc đang yêu cầu những điều kiện làm việc tốt hơn.)","Please handle this delicate [garment] with care to prevent any damage. (=Dịch: Xin vui lòng nhẹ tay với bộ quần áo mỏng manh này để tránh làm hỏng.)"],"ukAudio":"/ai_services/tts3/?q=garment&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=garment&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.m%C9%99nt%2F"},{"id":"lv_4_174","topic":"Cultural and Historical Exchange","word":"gatherer","pos":"(n)","ipa":"/ˈɡæð.ɚ.ɚ/","defVi":"người hái lượm, người thu gom","defEn":"a person who collects food, herbs, or other materials from the wild","examples":["Ancient humans lived as hunter-[gatherer] tribes before farming was developed. (=Dịch: Con người thời cổ đại sống thành các bộ lạc săn bắt - hái lượm trước khi nông nghiệp phát triển.)","The traditional [gatherer] knows exactly which wild mushrooms are safe to eat. (=Dịch: Người hái lượm truyền thống biết chính xác loại nấm dại nào an toàn để ăn.)","As a data [gatherer], his job was to collect feedback from consumers across the city. (=Dịch: Với vai trò là một người thu thập dữ liệu, công việc của anh ấy là thu thập phản hồi từ người tiêu dùng trên toàn thành phố.)"],"ukAudio":"/ai_services/tts3/?q=gatherer&lang=en-GB&ipa=%2F%CB%88%C9%A1%C3%A6%C3%B0.%C9%9A.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gatherer&lang=en-US&ipa=%2F%CB%88%C9%A1%C3%A6%C3%B0.%C9%9A.%C9%9A%2F"},{"id":"lv_4_175","topic":"Cultural and Historical Exchange","word":"generation","pos":"(n)","ipa":"/ˌdʒɛn.əˈreɪ.ʃən/","defVi":"thế hệ","defEn":"all of the people born and living at about the same time","examples":["The younger [generation] is very comfortable using modern digital devices. (=Dịch: Thế hệ trẻ rất thành thạo và thoải mái trong việc sử dụng các thiết bị kỹ thuật số hiện đại.)","Stories and traditions have been passed down from [generation] to generation. (=Dịch: Những câu chuyện và truyền thống đã được truyền từ thế hệ này sang thế hệ khác.)","This breakthrough will benefit future [generation]s for decades to come. (=Dịch: Bước đột phá này sẽ mang lại lợi ích cho các thế hệ tương lai trong nhiều thập kỷ tới.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_176","topic":"Cultural and Historical Exchange","word":"genre","pos":"(n)","ipa":"/ˈʒɑːn.rə/","defVi":"thể loại (nghệ thuật, âm nhạc, văn học)","defEn":"a particular style or category of art, music, or literature","examples":["Science fiction has always been my favorite literary [genre]. (=Dịch: Khoa học viễn tưởng luôn là thể loại văn học yêu thích của tôi.)","The director decided to experiment with a new film [genre] for his latest project. (=Dịch: Đạo diễn đã quyết định thử nghiệm một thể loại phim mới cho dự án mới nhất của mình.)","Jazz is a complex musical [genre] that originated in the United States. (=Dịch: Jazz là một thể loại âm nhạc phức tạp có nguồn gốc từ Hoa Kỳ.)"],"ukAudio":"/ai_services/tts3/?q=genre&lang=en-GB&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F","usAudio":"/ai_services/tts3/?q=genre&lang=en-US&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F"},{"id":"lv_4_177","topic":"Cultural and Historical Exchange","word":"german","pos":"(adj)","ipa":"/ˈdʒɝː.mən/","defVi":"(thuộc) nước Đức, người Đức hoặc tiếng Đức","defEn":"relating to Germany, its people, or its language","examples":["She has been studying the [German] language for two years. (=Dịch: Cô ấy đã học tiếng Đức được hai năm.)","Many consumers trust [German] engineering for its precision and durability. (=Dịch: Nhiều người tiêu dùng tin tưởng kỹ thuật của Đức nhờ độ chính xác và độ bền.)","We tried traditional [German] sausages during our trip to Berlin. (=Dịch: Chúng tôi đã thưởng thức món xúc xích Đức truyền thống trong chuyến đi đến Berlin.)"],"ukAudio":"/ai_services/tts3/?q=german&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=german&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99n%2F"},{"id":"lv_4_178","topic":"Cultural and Historical Exchange","word":"germany","pos":"(n)","ipa":"/ˈdʒɝː.mə.ni/","defVi":"nước Đức","defEn":"a country in Central Europe","examples":["Many international students choose to pursue engineering degrees in [Germany]. (=Dịch: Nhiều sinh viên quốc tế lựa chọn theo học các ngành kỹ thuật tại Đức.)","[Germany] is well known for its strong automotive industry and rich history. (=Dịch: Nước Đức rất nổi tiếng với ngành công nghiệp ô tô hùng mạnh và lịch sử phong phú.)","They traveled across [Germany] by train during their summer vacation. (=Dịch: Họ đã đi du lịch khắp nước Đức bằng tàu hỏa trong kỳ nghỉ hè của mình.)"],"ukAudio":"/ai_services/tts3/?q=germany&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=germany&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F"},{"id":"lv_4_179","topic":"Cultural and Historical Exchange","word":"gradually","pos":"(adv)","ipa":"/ˈɡrædʒ.u.ə.li/","defVi":"dần dần, từ từ","defEn":"slowly, over a period of time","examples":["The weather is [gradually] getting warmer as spring approaches. (=Dịch: Thời tiết đang dần ấm lên khi mùa xuân đến gần.)","His health [gradually] improved after following the doctor's advice. (=Dịch: Sức khỏe của anh ấy đã dần cải thiện sau khi làm theo lời khuyên của bác sĩ.)","She [gradually] adapted to the fast-paced lifestyle of the city. (=Dịch: Cô ấy đã dần thích nghi với nhịp sống hối hả của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=gradually&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=gradually&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F"},{"id":"lv_4_180","topic":"Cultural and Historical Exchange","word":"graduate","pos":"(v)","ipa":"/ˈɡræ.dʒu.eɪt/","defVi":"tốt nghiệp","defEn":"to complete a degree or course of study at a school, college, or university","examples":["She hopes to [graduate] from university with high honors next summer. (=Dịch: Cô ấy hy vọng sẽ tốt nghiệp đại học với tấm bằng loại ưu vào mùa hè tới.)","After they [graduate], many students choose to travel abroad. (=Dịch: Sau khi tốt nghiệp, nhiều sinh viên lựa chọn đi du lịch nước ngoài.)","He will [graduate] from medical school at the end of this year. (=Dịch: Anh ấy sẽ tốt nghiệp trường y vào cuối năm nay.)"],"ukAudio":"/ai_services/tts3/?q=graduate&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6.d%CA%92u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=graduate&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6.d%CA%92u.e%C9%AAt%2F"},{"id":"lv_4_181","topic":"Cultural and Historical Exchange","word":"grain","pos":"(n)","ipa":"/ɡreɪn/","defVi":"ngũ cốc, hạt thóc/gạo","defEn":"the seeds of crops such as wheat, rice, and corn used as food","examples":["Whole [grain] foods are an essential part of a balanced and healthy diet. (=Dịch: Thực phẩm từ ngũ cốc nguyên hạt là một phần thiết yếu của một chế độ ăn uống cân bằng và lành mạnh.)","The country exports large quantities of [grain] to international markets every year. (=Dịch: Đất nước này xuất khẩu một lượng lớn ngũ cốc sang các thị trường quốc tế mỗi năm.)","Poor weather conditions caused serious damage to the annual [grain] harvest. (=Dịch: Điều kiện thời tiết xấu đã gây thiệt hại nghiêm trọng cho vụ thu hoạch ngũ cốc hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=grain&lang=en-GB&ipa=%2F%C9%A1re%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=grain&lang=en-US&ipa=%2F%C9%A1re%C9%AAn%2F"},{"id":"lv_4_182","topic":"Cultural and Historical Exchange","word":"grazing","pos":"(v)","ipa":"/ˈɡreɪ.zɪŋ/","defVi":"gặm cỏ, chăn thả","defEn":"eating grass or other plants growing in a field (present participle of graze)","examples":["A herd of cows was peacefully [grazing] on the green hillside. (=Dịch: Một đàn bò đang gặm cỏ yên bình trên sườn đồi xanh ngát.)","Farmers restrict livestock from [grazing] too long in one meadow. (=Dịch: Nông dân hạn chế không cho gia súc gặm cỏ quá lâu trên một đồng cỏ.)","We saw several deer [grazing] near the edge of the forest. (=Dịch: Chúng tôi đã thấy vài con hươu đang gặm cỏ gần bìa rừng.)"],"ukAudio":"/ai_services/tts3/?q=grazing&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AA.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=grazing&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AA.z%C9%AA%C5%8B%2F"},{"id":"lv_4_183","topic":"Cultural and Historical Exchange","word":"greatly","pos":"(adv)","ipa":"/ˈɡreɪt.li/","defVi":"rất nhiều, vô cùng","defEn":"very much or to a large extent","examples":["His generous support [greatly] contributed to our team's victory. (=Dịch: Sự hỗ trợ hào phóng của anh ấy đã đóng góp rất lớn vào chiến thắng của đội chúng tôi.)","I [greatly] appreciate your assistance with this difficult task. (=Dịch: Tôi vô cùng trân trọng sự giúp đỡ của bạn đối với nhiệm vụ khó khăn này.)","The new regulations will [greatly] affect small businesses. (=Dịch: Các quy định mới sẽ ảnh hưởng rất lớn đến các doanh nghiệp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=greatly&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.li%2F","usAudio":"/ai_services/tts3/?q=greatly&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.li%2F"},{"id":"lv_4_184","topic":"Cultural and Historical Exchange","word":"greece","pos":"(n)","ipa":"/ɡris/","defVi":"nước Hy Lạp","defEn":"a country in southeastern Europe known for its ancient history and islands","examples":["Millions of tourists visit [Greece] every year to see ancient monuments like the Parthenon. (=Dịch: Hàng triệu du khách ghé thăm Hy Lạp mỗi năm để chiêm ngưỡng các di tích cổ xưa như đền Parthenon.)","Philosophy and democracy have deep roots in ancient [Greece]. (=Dịch: Triết học và nền dân chủ có nguồn gốc sâu xa từ Hy Lạp cổ đại.)","They spent their honeymoon relaxing on the sunny islands of [Greece]. (=Dịch: Họ đã trải qua tuần trăng mật thư giãn trên những hòn đảo đầy nắng của Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greece&lang=en-GB&ipa=%2F%C9%A1ris%2F","usAudio":"/ai_services/tts3/?q=greece&lang=en-US&ipa=%2F%C9%A1ris%2F"},{"id":"lv_4_185","topic":"Cultural and Historical Exchange","word":"greek","pos":"(n)","ipa":"/ɡriːk/","defVi":"người Hy Lạp, tiếng Hy Lạp","defEn":"a person from Greece or the language spoken there","examples":["He is studying ancient [Greek] to better understand classical philosophy. (=Dịch: Anh ấy đang học tiếng Hy Lạp cổ đại để hiểu rõ hơn về triết học cổ điển.)","The restaurant is run by a native [Greek] who prepares authentic Mediterranean dishes. (=Dịch: Nhà hàng được điều hành bởi một người Hy Lạp bản xứ, người chuyên chuẩn bị các món ăn Địa Trung Hải đích thực.)","Many modern English scientific terms are derived from [Greek]. (=Dịch: Nhiều thuật ngữ khoa học tiếng Anh hiện đại có nguồn gốc từ tiếng Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greek&lang=en-GB&ipa=%2F%C9%A1ri%CB%90k%2F","usAudio":"/ai_services/tts3/?q=greek&lang=en-US&ipa=%2F%C9%A1ri%CB%90k%2F"},{"id":"lv_4_186","topic":"Cultural and Historical Exchange","word":"grind","pos":"(v)","ipa":"/ɡraɪnd/","defVi":"xay, nghiền nhỏ","defEn":"to break something into tiny pieces or powder by crushing it","examples":["She likes to [grind] fresh coffee beans every morning. (=Dịch: Cô ấy thích xay hạt cà phê tươi mỗi sáng.)","The machine is used to [grind] wheat into flour. (=Dịch: Cỗ máy này được sử dụng để nghiền lúa mì thành bột mì.)","People under severe stress often [grind] their teeth during sleep. (=Dịch: Những người bị căng thẳng nghiêm trọng thường nghiến răng khi ngủ.)"],"ukAudio":"/ai_services/tts3/?q=grind&lang=en-GB&ipa=%2F%C9%A1ra%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=grind&lang=en-US&ipa=%2F%C9%A1ra%C9%AAnd%2F"},{"id":"lv_4_187","topic":"Cultural and Historical Exchange","word":"guardian","pos":"(n)","ipa":"/ˈɡɑːr.di.ən/","defVi":"người giám hộ, người bảo hộ","defEn":"a person who protects someone or something, or has legal responsibility for a child","examples":["After the parents passed away, the aunt was appointed as legal [guardian]. (=Dịch: Sau khi cha mẹ qua đời, người dì đã được chỉ định làm người giám hộ hợp pháp.)","Lighthouses serve as a [guardian] for ships navigating dangerous coasts. (=Dịch: Những ngọn hải đăng đóng vai trò như người bảo vệ cho các con tàu định hướng qua các bờ biển nguy hiểm.)","The museum acts as a [guardian] of national cultural heritage. (=Dịch: Bảo tàng đóng vai trò là nơi gìn giữ di sản văn hóa quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=guardian&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.di.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=guardian&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.di.%C9%99n%2F"},{"id":"lv_4_188","topic":"Cultural and Historical Exchange","word":"handbag","pos":"(n)","ipa":"/ˈhænd.bæɡ/","defVi":"túi xách tay","defEn":"a small bag used especially by women for carrying personal items","examples":["She left her leather [handbag] on the back of the chair. (=Dịch: Cô ấy đã để chiếc túi xách da ở lưng ghế.)","He searched through his [handbag] to find his keys and wallet. (=Dịch: Anh ấy lục tìm trong túi xách của mình để tìm chìa khóa và ví tiền.)","She bought a designer [handbag] as a gift to celebrate her promotion. (=Dịch: Cô ấy đã mua một chiếc túi xách hàng hiệu làm quà để ăn mừng việc mình được thăng chức.)"],"ukAudio":"/ai_services/tts3/?q=handbag&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=handbag&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F"},{"id":"lv_4_189","topic":"Cultural and Historical Exchange","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay","defEn":"a document distributed to people, especially to students or meeting attendees","examples":["The teacher distributed a [handout] summarizing the main points of the lesson. (=Dịch: Giáo viên đã phát một tài liệu phát tay tóm tắt các điểm chính của bài học.)","Please refer to the [handout] for further details about the project. (=Dịch: Vui lòng tham khảo tài liệu phát tay để biết thêm chi tiết về dự án.)","He forgot to bring his [handout] to the presentation. (=Dịch: Anh ấy đã quên mang tài liệu phát tay của mình đến buổi thuyết trình.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_4_190","topic":"Cultural and Historical Exchange","word":"hang","pos":"(v)","ipa":"/hæŋ/","defVi":"treo, móc lên","defEn":"to fasten or attach something from above so that the lower part is free","examples":["They decided to [hang] family portraits along the hallway wall. (=Dịch: Họ quyết định treo những bức chân dung gia đình dọc theo bức tường hành lang.)","Please [hang] your coat on the rack near the entrance. (=Dịch: Vui lòng treo áo khoác của bạn lên giá gần lối vào.)","Heavy curtains [hang] across the large windows to block the sunlight. (=Dịch: Những tấm rèm dày rủ xuống qua các cửa sổ lớn để cản ánh nắng mặt trời.)"],"ukAudio":"/ai_services/tts3/?q=hang&lang=en-GB&ipa=%2Fh%C3%A6%C5%8B%2F","usAudio":"/ai_services/tts3/?q=hang&lang=en-US&ipa=%2Fh%C3%A6%C5%8B%2F"},{"id":"lv_4_191","topic":"Cultural and Historical Exchange","word":"happiness","pos":"(n)","ipa":"/ˈhæp.i.nəs/","defVi":"hạnh phúc, sự sung sướng","defEn":"the state of feeling satisfied, joyful, and content","examples":["True [happiness] often comes from meaningful relationships rather than material possessions. (=Dịch: Hạnh phúc thực sự thường đến từ những mối quan hệ ý nghĩa hơn là của cải vật chất.)","She found lasting [happiness] in helping underprivileged children in her community. (=Dịch: Cô đã tìm thấy niềm hạnh phúc lâu bền trong việc giúp đỡ những trẻ em có hoàn cảnh khó khăn trong cộng đồng của mình.)","The report measures national well-being based on health, education, and overall [happiness]. (=Dịch: Báo cáo đo lường mức độ thịnh vượng quốc gia dựa trên sức khỏe, giáo dục và mức độ hạnh phúc tổng thể.)"],"ukAudio":"/ai_services/tts3/?q=happiness&lang=en-GB&ipa=%2F%CB%88h%C3%A6p.i.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=happiness&lang=en-US&ipa=%2F%CB%88h%C3%A6p.i.n%C9%99s%2F"},{"id":"lv_4_192","topic":"Cultural and Historical Exchange","word":"harbour","pos":"(v)","ipa":"/ˈhɑr.bɚ/","defVi":"nuôi dưỡng (ý nghĩ, cảm xúc), che giấu, chứa chấp","defEn":"to keep a thought or feeling secretly, or to give shelter and protection to someone","examples":["It is unhealthy to [harbour] resentment against your colleagues. (=Dịch: Thật không tốt cho sức khỏe khi nuôi dưỡng sự oán hận đối với đồng nghiệp của bạn.)","The country was accused of trying to [harbour] known criminals. (=Dịch: Đất nước này bị cáo buộc cố tình chứa chấp những tên tội phạm khét tiếng.)","She continues to [harbour] doubts about the success of the new plan. (=Dịch: Cô ấy vẫn tiếp tục ôm ấp những mối nghi ngờ về sự thành công của kế hoạch mới.)"],"ukAudio":"/ai_services/tts3/?q=harbour&lang=en-GB&ipa=%2F%CB%88h%C9%91r.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=harbour&lang=en-US&ipa=%2F%CB%88h%C9%91r.b%C9%9A%2F"},{"id":"lv_4_193","topic":"Cultural and Historical Exchange","word":"heating","pos":"(n)","ipa":"/ˈhiː.t̬ɪŋ/","defVi":"hệ thống sưởi, việc sưởi ấm","defEn":"a system or equipment used to keep a building warm","examples":["They turned on the central [heating] as soon as the winter weather set in. (=Dịch: Họ đã bật hệ thống sưởi trung tâm ngay khi thời tiết mùa đông bắt đầu.)","Old buildings often lose energy because their [heating] systems are inefficient. (=Dịch: Các tòa nhà cũ thường bị thất thoát năng lượng do hệ thống sưởi hoạt động kém hiệu quả.)","The landlord promised to repair the broken [heating] unit before next week. (=Dịch: Chủ nhà đã hứa sẽ sửa chữa thiết bị sưởi bị hỏng trước tuần sau.)"],"ukAudio":"/ai_services/tts3/?q=heating&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heating&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_4_194","topic":"Cultural and Historical Exchange","word":"highlight","pos":"(n)","ipa":"/ˈhaɪ.laɪt/","defVi":"điểm nổi bật, nét đặc sắc nhất","defEn":"the best, most interesting, or most important part of something","examples":["Visiting the ancient castle was definitely the [highlight] of our summer trip. (=Dịch: Tham quan lâu đài cổ kính chắc chắn là điểm nhấn nổi bật trong chuyến đi mùa hè của chúng tôi.)","The keynote speech by the guest professor was the [highlight] of the academic conference. (=Dịch: Bài phát biểu quan trọng của giáo sư khách mời là điểm nổi bật nhất của hội nghị học thuật.)","The sports news showed a short video of the game's [highlight] moments. (=Dịch: Bản tin thể thao đã phát một đoạn video ngắn về những khoảnh khắc nổi bật nhất của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F"},{"id":"lv_4_195","topic":"Cultural and Historical Exchange","word":"housing","pos":"(n)","ipa":"/ˈhaʊ.zɪŋ/","defVi":"nhà ở, việc cung cấp chỗ ở","defEn":"buildings such as flats and houses that people live in","examples":["The government is investing heavily in affordable [housing] for low-income families. (=Dịch: Chính phủ đang đầu tư mạnh vào nhà ở giá phải chăng cho các gia đình có thu nhập thấp.)","Rapid urban growth has created a severe shortage of quality [housing] in the city. (=Dịch: Sự phát triển đô thị nhanh chóng đã tạo ra sự thiếu hụt nghiêm trọng về nhà ở chất lượng tại thành phố.)","University students often struggle to find safe and affordable [housing] near campus. (=Dịch: Sinh viên đại học thường chật vật tìm kiếm chỗ ở an toàn và giá cả phải chăng gần khuôn viên trường.)"],"ukAudio":"/ai_services/tts3/?q=housing&lang=en-GB&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=housing&lang=en-US&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F"},{"id":"lv_4_196","topic":"Cultural and Historical Exchange","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"cuộc săn bắt, cuộc tìm kiếm","defEn":"an act of chasing wild animals for food or sport, or a search for someone or something","examples":["The police launched a massive [hunt] for the missing child. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm quy mô lớn đứa trẻ mất tích.)","Lions often coordinate during a [hunt] to catch fast prey. (=Dịch: Sư tử thường phối hợp trong cuộc săn để bắt những con mồi nhanh nhẹn.)","His apartment [hunt] in the city center took several weeks. (=Dịch: Công cuộc tìm kiếm căn hộ của anh ấy ở trung tâm thành phố đã mất vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_4_197","topic":"Cultural and Historical Exchange","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.tɚ/","defVi":"thợ săn, kẻ săn mồi","defEn":"a person or animal that chases and catches wild animals for food or sport","examples":["The ancient tribe relied on every [hunter] to provide meat for the village. (=Dịch: Bộ lạc cổ đại dựa vào từng thợ săn để cung cấp thịt cho cả làng.)","The snowy owl is a skilled [hunter] that can spot prey from great distances. (=Dịch: Cú tuyết là một kẻ săn mồi điêu luyện có thể phát hiện con mồi từ khoảng cách rất xa.)","A treasure [hunter] discovered ancient gold coins near the coast. (=Dịch: Một thợ săn kho báu đã phát hiện ra những đồng tiền vàng cổ gần bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F"},{"id":"lv_4_198","topic":"Cultural and Historical Exchange","word":"hut","pos":"(n)","ipa":"/hʌt/","defVi":"túp lều, chòi tạm","defEn":"a small, simple building, usually consisting of only one room","examples":["The fishermen built a small wooden [hut] by the river. (=Dịch: Những người ngư dân đã dựng một túp lều gỗ nhỏ bên bờ sông.)","They took shelter in a mountain [hut] during the heavy storm. (=Dịch: Họ đã trú ẩn trong một căn lều trên núi suốt cơn bão lớn.)","The beach is lined with simple straw [hut] structures for tourists. (=Dịch: Dọc bãi biển là những chòi lợp rơm đơn sơ dành cho khách du lịch.)"],"ukAudio":"/ai_services/tts3/?q=hut&lang=en-GB&ipa=%2Fh%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=hut&lang=en-US&ipa=%2Fh%CA%8Ct%2F"},{"id":"lv_4_199","topic":"Cultural and Historical Exchange","word":"illustration","pos":"(n)","ipa":"/ˌɪl.əˈstreɪ.ʃən/","defVi":"hình minh họa, tranh minh họa","defEn":"a picture, drawing, or diagram in a book or magazine used to explain or decorate text","examples":["The children's book contains a colorful [illustration] on every page. (=Dịch: Cuốn sách thiếu nhi có một hình minh họa đầy màu sắc trên mỗi trang.)","She provided a clear [illustration] to explain the complex concept. (=Dịch: Cô ấy đã đưa ra một ví dụ minh họa rõ ràng để giải thích khái niệm phức tạp đó.)","His digital [illustration] won first prize in the national art competition. (=Dịch: Tác phẩm minh họa kỹ thuật số của anh ấy đã giành giải nhất trong cuộc thi nghệ thuật quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=illustration&lang=en-GB&ipa=%2F%CB%8C%C9%AAl.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=illustration&lang=en-US&ipa=%2F%CB%8C%C9%AAl.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_200","topic":"Cultural and Historical Exchange","word":"imagination","pos":"(n)","ipa":"/ɪˌmædʒ.əˈneɪ.ʃən/","defVi":"trí tưởng tượng, sức tưởng tượng","defEn":"the ability to form new ideas, pictures, or concepts in your mind that are not real or present","examples":["Children often have a vivid [imagination] that helps them create wonderful stories. (=Dịch: Trẻ em thường có trí tưởng tượng phong phú giúp các em sáng tạo nên những câu chuyện tuyệt vời.)","Writing a fantasy novel requires a great deal of creativity and [imagination]. (=Dịch: Viết một cuốn tiểu thuyết giả tưởng đòi hỏi rất nhiều sự sáng tạo và trí tưởng tượng.)","The sound was so faint that she thought it was just a product of her [imagination]. (=Dịch: Âm thanh nhỏ đến mức cô ấy nghĩ đó chỉ là sản phẩm từ trí tưởng tượng của mình.)"],"ukAudio":"/ai_services/tts3/?q=imagination&lang=en-GB&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=imagination&lang=en-US&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_201","topic":"Cultural and Historical Exchange","word":"impression","pos":"(n)","ipa":"/ɪmˈprɛʃ.ən/","defVi":"ấn tượng, cảm tưởng","defEn":"an idea, feeling, or opinion formed about someone or something","examples":["Dressing professionally helps you make a positive first [impression] at a job interview. (=Dịch: Ăn mặc chuyên nghiệp giúp bạn tạo ấn tượng đầu tiên tích cực trong buổi phỏng vấn xin việc.)","I was under the [impression] that the submission deadline had been extended. (=Dịch: Tôi cứ có cảm giác rằng thời hạn nộp bài đã được gia hạn.)","The scenic beauty of the mountains left a lasting [impression] on all the travelers. (=Dịch: Vẻ đẹp tuyệt mỹ của núi non đã để lại ấn tượng sâu sắc trong lòng tất cả du khách.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_4_202","topic":"Cultural and Historical Exchange","word":"incredibly","pos":"(adv)","ipa":"/ɪnˈkrɛd.ə.bli/","defVi":"vô cùng, cực kỳ","defEn":"extremely; to a great degree","examples":["The exam was [incredibly] difficult, even for well-prepared students. (=Dịch: Bài thi cực kỳ khó, ngay cả đối với những học sinh đã chuẩn bị kỹ lưỡng.)","She performed [incredibly] well during her job interview. (=Dịch: Cô ấy đã thể hiện vô cùng xuất sắc trong buổi phỏng vấn xin việc.)","It is [incredibly] important to get enough sleep each night. (=Dịch: Việc ngủ đủ giấc mỗi đêm là vô cùng quan trọng.)"],"ukAudio":"/ai_services/tts3/?q=incredibly&lang=en-GB&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=incredibly&lang=en-US&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F"},{"id":"lv_4_203","topic":"Cultural and Historical Exchange","word":"influential","pos":"(adj)","ipa":"/ˌɪn.fluˈen.ʃəl/","defVi":"có tầm ảnh hưởng lớn","defEn":"having a lot of influence on people or events","examples":["She is one of the most [influential] writers of this century. (=Dịch: Bà là một trong những nhà văn có tầm ảnh hưởng nhất của thế kỷ này.)","His father played an [influential] role in his career choice. (=Dịch: Cha anh ấy đã đóng một vai trò có ảnh hưởng lớn trong việc lựa chọn nghề nghiệp của anh.)","Social media has become highly [influential] in modern politics. (=Dịch: Mạng xã hội đã trở nên có tầm ảnh hưởng sâu rộng trong nền chính trị hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=influential&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.flu%CB%88en.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=influential&lang=en-US&ipa=%2F%CB%8C%C9%AAn.flu%CB%88en.%CA%83%C9%99l%2F"},{"id":"lv_4_204","topic":"Cultural and Historical Exchange","word":"inhabitant","pos":"(n)","ipa":"/ɪnˈhæb.ə.tənt/","defVi":"cư dân, người cư trú","defEn":"a person or animal that lives permanently in a particular place","examples":["Every [inhabitant] of the small island knows their neighbors well. (=Dịch: Mỗi cư dân trên hòn đảo nhỏ đều biết rất rõ những người hàng xóm của mình.)","The city has over two million [inhabitant]s from diverse backgrounds. (=Dịch: Thành phố có hơn hai triệu cư dân đến từ nhiều nguồn gốc khác nhau.)","Deforestation threatens the survival of each forest [inhabitant]. (=Dịch: Nạn phá rừng đe dọa sự sống còn của từng sinh vật cư trú trong rừng.)"],"ukAudio":"/ai_services/tts3/?q=inhabitant&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=inhabitant&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F"},{"id":"lv_4_205","topic":"Cultural and Historical Exchange","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, sâu trong đất liền","defEn":"situated in or relating to the interior part of a country, away from the coast","examples":["Many [inland] areas suffer from extreme temperature differences between day and night. (=Dịch: Nhiều khu vực sâu trong nội địa phải chịu sự chênh lệch nhiệt độ khắc nghiệt giữa ngày và đêm.)","The river provides an important [inland] waterway for transporting trade goods. (=Dịch: Con sông tạo nên một tuyến đường thủy nội địa quan trọng để vận chuyển hàng hóa thương mại.)","They moved to an [inland] town to escape coastal storms. (=Dịch: Họ đã chuyển đến một thị trấn trong đất liền để tránh các cơn bão vùng duyên hải.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_4_206","topic":"Cultural and Historical Exchange","word":"innovation","pos":"(n)","ipa":"/ˌɪn.əˈveɪ.ʃən/","defVi":"sự đổi mới, sáng kiến cải tiến","defEn":"the introduction of new ideas, methods, or things","examples":["Technological [innovation] continues to transform how people communicate. (=Dịch: Sự đổi mới công nghệ tiếp tục thay đổi cách con người giao tiếp.)","The company encourages [innovation] by giving employees time to work on personal projects. (=Dịch: Công ty khuyến khích sự đổi mới sáng tạo bằng cách cho nhân viên thời gian làm việc trên các dự án cá nhân.)","Recent [innovation] in solar energy has made renewable power much more affordable. (=Dịch: Những đổi mới gần đây trong lĩnh vực năng lượng mặt trời đã giúp năng lượng tái tạo có giá cả phải chăng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=innovation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=innovation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_207","topic":"Cultural and Historical Exchange","word":"innovative","pos":"(adj)","ipa":"/ˈɪn.ə.veɪ.tɪv/","defVi":"mang tính đổi mới, sáng tạo, tân tiến","defEn":"introducing new ideas, methods, or original ways of thinking","examples":["The company is famous for its [innovative] designs in consumer electronics. (=Dịch: Công ty nổi tiếng với các thiết kế mang tính đổi mới sáng tạo trong lĩnh vực điện tử tiêu dùng.)","Teachers are encouraged to use [innovative] methods in the classroom. (=Dịch: Các giáo viên được khuyến khích sử dụng các phương pháp đổi mới trong lớp học.)","She proposed an [innovative] solution to reduce plastic waste in the city. (=Dịch: Cô ấy đã đề xuất một giải pháp mang tính sáng tạo để giảm thiểu rác thải nhựa trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=innovative&lang=en-GB&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=innovative&lang=en-US&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%C9%AAv%2F"},{"id":"lv_4_208","topic":"Cultural and Historical Exchange","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự thấu hiểu sâu sắc, cái nhìn sâu sắc","defEn":"a clear, deep, and sometimes sudden understanding of a complicated problem or situation","examples":["The research provides valuable [insight] into consumer behavior. (=Dịch: Nghiên cứu cung cấp cái nhìn sâu sắc có giá trị về hành vi của người tiêu dùng.)","His personal experiences gave him a unique [insight] into the struggles of immigrants. (=Dịch: Những trải nghiệm cá nhân mang lại cho anh ấy sự thấu hiểu độc đáo về những khó khăn của người nhập cư.)","The book offers an interesting [insight] into traditional Japanese culture. (=Dịch: Cuốn sách đem đến một góc nhìn thú vị về văn hóa truyền thống Nhật Bản.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_4_209","topic":"Cultural and Historical Exchange","word":"inspiration","pos":"(n)","ipa":"/ˌɪn.spəˈreɪ.ʃən/","defVi":"nguồn cảm hứng, sự truyền cảm hứng","defEn":"a person, thing, or sudden feeling that gives you ideas to do or create something","examples":["Nature is always a great source of [inspiration] for artists. (=Dịch: Thiên nhiên luôn là nguồn cảm hứng tuyệt vời cho các nghệ sĩ.)","Her speech provided the [inspiration] needed to complete the project. (=Dịch: Bài phát biểu của cô ấy đã mang lại nguồn cảm hứng cần thiết để hoàn thành dự án.)","He looked around the room in search of [inspiration] for his next painting. (=Dịch: Anh ấy nhìn quanh phòng để tìm kiếm nguồn cảm hứng cho bức tranh tiếp theo của mình.)"],"ukAudio":"/ai_services/tts3/?q=inspiration&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.sp%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=inspiration&lang=en-US&ipa=%2F%CB%8C%C9%AAn.sp%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_210","topic":"Cultural and Historical Exchange","word":"inspire","pos":"(v)","ipa":"/ɪnˈspaɪr/","defVi":"truyền cảm hứng, khích lệ","defEn":"to fill someone with the urge or ability to do something creative or worthwhile","examples":["Her courage helped [inspire] many young women to pursue science careers. (=Dịch: Lòng dũng cảm của cô ấy đã giúp truyền cảm hứng cho nhiều phụ nữ trẻ theo đuổi sự nghiệp khoa học.)","A walk in the mountains can often [inspire] painters and poets. (=Dịch: Một chuyến đi dạo trên núi thường có thể khơi nguồn cảm hứng cho các họa sĩ và nhà thơ.)","The coach gave a powerful speech to [inspire] the team before the final match. (=Dịch: Huấn luyện viên đã có một bài phát biểu đầy nội lực để truyền cảm hứng cho toàn đội trước trận chung kết.)"],"ukAudio":"/ai_services/tts3/?q=inspire&lang=en-GB&ipa=%2F%C9%AAn%CB%88spa%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=inspire&lang=en-US&ipa=%2F%C9%AAn%CB%88spa%C9%AAr%2F"},{"id":"lv_4_211","topic":"Cultural and Historical Exchange","word":"installation","pos":"(n)","ipa":"/ˌɪn.stəˈleɪ.ʃən/","defVi":"sự lắp đặt; tác phẩm nghệ thuật sắp đặt","defEn":"the act of putting something in place so that it is ready for use, or a modern work of art","examples":["The technician completed the [installation] of the new air conditioning system. (=Dịch: Kỹ thuật viên đã hoàn thành việc lắp đặt hệ thống điều hòa không khí mới.)","The museum opened a fascinating interactive art [installation] yesterday. (=Dịch: Hôm qua, bảo tàng đã khai mạc một tác phẩm nghệ thuật sắp đặt tương tác đầy hấp dẫn.)","Please follow the on-screen instructions during software [installation]. (=Dịch: Vui lòng làm theo hướng dẫn trên màn hình trong quá trình cài đặt phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=installation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=installation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_212","topic":"Cultural and Historical Exchange","word":"intact","pos":"(adj)","ipa":"/ɪnˈtækt/","defVi":"nguyên vẹn, không bị hư hại","defEn":"complete and not damaged or changed","examples":["Remarkably, the ancient vase remained [intact] after the earthquake. (=Dịch: Thật đáng kinh ngạc, chiếc bình cổ vẫn còn nguyên vẹn sau trận động đất.)","Despite the heavy criticism, his reputation stayed [intact]. (=Dịch: Bất chấp những lời chỉ trích nặng nề, danh tiếng của ông vẫn không hề bị suy suyển.)","The package arrived with its original seal still [intact]. (=Dịch: Kiện hàng đã đến nơi với phần niêm phong ban đầu vẫn còn nguyên vẹn.)"],"ukAudio":"/ai_services/tts3/?q=intact&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=intact&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C3%A6kt%2F"},{"id":"lv_4_213","topic":"Cultural and Historical Exchange","word":"interpretation","pos":"(n)","ipa":"/ɪnˌtɝː.prəˈteɪ.ʃən/","defVi":"sự giải thích, sự diễn giải, cách hiểu","defEn":"an explanation or opinion of what something means","examples":["His [interpretation] of the poem differed greatly from the teacher's view. (=Dịch: Cách giải thích bài thơ của anh ấy khác xa với quan điểm của giáo viên.)","The ambiguous contract left too much room for [interpretation]. (=Dịch: Hợp đồng mơ hồ đã để lại quá nhiều chỗ cho những cách diễn giải khác nhau.)","Her unique [interpretation] of the musical piece earned a standing ovation. (=Dịch: Cách thể hiện độc đáo của cô ấy đối với tác phẩm âm nhạc đã nhận được sự tán thưởng nhiệt liệt từ khán phòng.)"],"ukAudio":"/ai_services/tts3/?q=interpretation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Ct%C9%9D%CB%90.pr%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interpretation&lang=en-US&ipa=%2F%C9%AAn%CB%8Ct%C9%9D%CB%90.pr%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_214","topic":"Cultural and Historical Exchange","word":"interviewee","pos":"(n)","ipa":"/ˌɪn.tɚ.vjuːˈiː/","defVi":"người được phỏng vấn, ứng viên phỏng vấn","defEn":"a person who answers questions in an interview","examples":["The [interviewee] answered all the technical questions with great confidence. (=Dịch: Người được phỏng vấn đã trả lời tất cả các câu hỏi chuyên môn với sự tự tin lớn.)","The researcher asked each [interviewee] about their daily commuting habits. (=Dịch: Nhà nghiên cứu đã hỏi từng người được phỏng vấn về thói quen đi lại hàng ngày của họ.)","A well-prepared [interviewee] usually asks thoughtful questions at the end of the meeting. (=Dịch: Một người được phỏng vấn chuẩn bị kỹ lưỡng thường đặt ra những câu hỏi sâu sắc ở cuối buổi gặp.)"],"ukAudio":"/ai_services/tts3/?q=interviewee&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%9A.vju%CB%90%CB%88i%CB%90%2F","usAudio":"/ai_services/tts3/?q=interviewee&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%9A.vju%CB%90%CB%88i%CB%90%2F"},{"id":"lv_4_215","topic":"Cultural and Historical Exchange","word":"introductory","pos":"(adj)","ipa":"/ˌɪn.trəˈdʌk.tə.ri/","defVi":"mở đầu, giới thiệu, sơ bộ","defEn":"serving as an introduction; basic or opening","examples":["Students must complete the [introductory] course before taking advanced seminars. (=Dịch: Sinh viên phải hoàn thành khóa học nhập môn trước khi tham gia các buổi hội thảo chuyên sâu.)","The speaker gave brief [introductory] remarks before starting the presentation. (=Dịch: Diễn giả đã có đôi lời phát biểu mở đầu ngắn gọn trước khi bắt đầu bài thuyết trình.)","The company offered an [introductory] discount for new subscribers. (=Dịch: Công ty đã đưa ra mức giảm giá ưu đãi ban đầu cho những người đăng ký mới.)"],"ukAudio":"/ai_services/tts3/?q=introductory&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.tr%C9%99%CB%88d%CA%8Ck.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=introductory&lang=en-US&ipa=%2F%CB%8C%C9%AAn.tr%C9%99%CB%88d%CA%8Ck.t%C9%99.ri%2F"},{"id":"lv_4_216","topic":"Cultural and Historical Exchange","word":"inventor","pos":"(n)","ipa":"/ɪnˈven.tɚ/","defVi":"nhà phát minh, người sáng chế","defEn":"a person who creates or designs something that has never existed before","examples":["Thomas Edison is widely known as a prolific [inventor]. (=Dịch: Thomas Edison được biết đến rộng rãi như một nhà phát minh năng suất.)","The young [inventor] received an award for designing an affordable water filter. (=Dịch: Nhà phát minh trẻ đã nhận được giải thưởng vì thiết kế một bộ lọc nước có giá cả phải chăng.)","Every successful [inventor] must be willing to learn from repeated failures. (=Dịch: Mọi nhà phát minh thành công đều phải sẵn sàng học hỏi từ những thất bại lặp đi lặp lại.)"],"ukAudio":"/ai_services/tts3/?q=inventor&lang=en-GB&ipa=%2F%C9%AAn%CB%88ven.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=inventor&lang=en-US&ipa=%2F%C9%AAn%CB%88ven.t%C9%9A%2F"},{"id":"lv_4_217","topic":"Cultural and Historical Exchange","word":"investment","pos":"(n)","ipa":"/ɪnˈvest.mənt/","defVi":"khoản đầu tư, sự đầu tư","defEn":"the act of putting money, effort, or time into something to get a profit or advantage","examples":["Buying a home is often the largest financial [investment] people make. (=Dịch: Mua nhà thường là khoản đầu tư tài chính lớn nhất mà mọi người thực hiện.)","The government increased its [investment] in renewable energy projects. (=Dịch: Chính phủ đã tăng cường đầu tư vào các dự án năng lượng tái tạo.)","Reading books regularly is a valuable [investment] in your personal growth. (=Dịch: Đọc sách thường xuyên là một sự đầu tư quý giá cho sự phát triển cá nhân của bạn.)"],"ukAudio":"/ai_services/tts3/?q=investment&lang=en-GB&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=investment&lang=en-US&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F"},{"id":"lv_4_218","topic":"Cultural and Historical Exchange","word":"ireland","pos":"(n)","ipa":"/ˈaɪr.lənd/","defVi":"nước Ai-len, Ireland","defEn":"an island country in northwestern Europe known for its rich history and green landscapes","examples":["Many tourists travel to [Ireland] to experience its lively folk music and scenic countryside. (=Dịch: Nhiều du khách đến Ireland để trải nghiệm nền âm nhạc dân gian sôi động và vùng nông thôn tuyệt đẹp nơi đây.)","He decided to study computer science at a university in [Ireland]. (=Dịch: Anh ấy quyết định theo học ngành khoa học máy tính tại một trường đại học ở Ireland.)","The software company opened its European headquarters in [Ireland]. (=Dịch: Công ty phần mềm đã mở trụ sở châu Âu tại Ireland.)"],"ukAudio":"/ai_services/tts3/?q=ireland&lang=en-GB&ipa=%2F%CB%88a%C9%AAr.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=ireland&lang=en-US&ipa=%2F%CB%88a%C9%AAr.l%C9%99nd%2F"},{"id":"lv_4_219","topic":"Cultural and Historical Exchange","word":"irish","pos":"(adj)","ipa":"/ˈaɪ.rɪʃ/","defVi":"thuộc về Ai-len, người Ai-len hoặc tiếng Ai-len","defEn":"relating to Ireland, its people, language, or culture","examples":["We enjoyed listening to traditional [Irish] music at the pub. (=Dịch: Chúng tôi rất thích nghe nhạc truyền thống Ireland tại quán rượu.)","She is proud of her [Irish] heritage and family roots. (=Dịch: Cô ấy tự hào về di sản Ireland và cội nguồn gia đình của mình.)","The festival celebrates [Irish] literature and folklore every spring. (=Dịch: Lễ hội tôn vinh văn học và văn hóa dân gian Ireland vào mỗi mùa xuân.)"],"ukAudio":"/ai_services/tts3/?q=irish&lang=en-GB&ipa=%2F%CB%88a%C9%AA.r%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=irish&lang=en-US&ipa=%2F%CB%88a%C9%AA.r%C9%AA%CA%83%2F"},{"id":"lv_4_220","topic":"Cultural and Historical Exchange","word":"italy","pos":"(n)","ipa":"/ˈɪt̬.əl.i/","defVi":"nước Ý, Italy","defEn":"a country in southern Europe known for its history, art, and cuisine","examples":["Millions of visitors travel to [Italy] each year to explore historic monuments like the Colosseum. (=Dịch: Hàng triệu du khách đến Ý mỗi năm để khám phá các di tích lịch sử như Đấu trường La Mã.)","She developed a passion for cooking while living in [Italy]. (=Dịch: Cô ấy hình thành niềm đam mê nấu nướng khi sống ở Ý.)","Automakers in [Italy] are famous for producing world-class luxury sports cars. (=Dịch: Các nhà sản xuất ô tô ở Ý nổi tiếng với việc sản xuất ra những chiếc xe thể thao hạng sang đẳng cấp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=italy&lang=en-GB&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=italy&lang=en-US&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F"},{"id":"lv_4_221","topic":"Cultural and Historical Exchange","word":"jean","pos":"(n)","ipa":"/dʒiːn/","defVi":"vải bò, vải gin","defEn":"a durable twilled cotton cloth, commonly used to make casual trousers","examples":["A sturdy [jean] jacket is a timeless wardrobe staple for autumn. (=Dịch: Một chiếc áo khoác jean bền chắc là món đồ không bao giờ lỗi thời trong tủ đồ mùa thu.)","The factory specializes in producing high-quality [jean] fabric for export. (=Dịch: Nhà máy chuyên sản xuất vải jean chất lượng cao để xuất khẩu.)","He bought a stylish [jean] cap at the local street market. (=Dịch: Anh ấy đã mua một chiếc mũ jean sành điệu tại chợ đêm địa phương.)"],"ukAudio":"/ai_services/tts3/?q=jean&lang=en-GB&ipa=%2Fd%CA%92i%CB%90n%2F","usAudio":"/ai_services/tts3/?q=jean&lang=en-US&ipa=%2Fd%CA%92i%CB%90n%2F"},{"id":"lv_4_222","topic":"Cultural and Historical Exchange","word":"joy","pos":"(n)","ipa":"/dʒɔɪ/","defVi":"niềm vui, sự hân hoan","defEn":"a feeling of great happiness and pleasure","examples":["The birth of their first child brought immense [joy] to the entire family. (=Dịch: Sự ra đời của đứa con đầu lòng đã mang lại niềm vui vô bờ bến cho cả gia đình.)","She could not hide her [joy] when she received the scholarship offer. (=Dịch: Cô ấy không thể giấu được niềm vui sướng khi nhận được thông báo cấp học bổng.)","Gardening is a simple activity that brings him a lot of [joy]. (=Dịch: Làm vườn là một hoạt động đơn giản mang lại cho anh ấy rất nhiều niềm vui.)"],"ukAudio":"/ai_services/tts3/?q=joy&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AA%2F","usAudio":"/ai_services/tts3/?q=joy&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AA%2F"},{"id":"lv_4_223","topic":"Cultural and Historical Exchange","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba, ngã tư","defEn":"a point where two or more roads, railway lines, or rivers meet","examples":["Drivers should slow down when approaching a busy road [junction]. (=Dịch: Các tài xế nên giảm tốc độ khi đến gần một nút giao thông đông đúc.)","The train stopped at the railway [junction] to switch tracks. (=Dịch: Đoàn tàu đã dừng lại ở nút giao đường sắt để chuyển đường ray.)","The new traffic lights at the dangerous [junction] helped reduce accidents significantly. (=Dịch: Hệ thống đèn giao thông mới tại nút giao nguy hiểm đã giúp giảm đáng kể tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_4_224","topic":"Cultural and Historical Exchange","word":"kiln","pos":"(n)","ipa":"/kɪln/","defVi":"lò nung","defEn":"a large oven used for baking bricks or clay to make pottery","examples":["The clay pots must dry completely before they go into the [kiln]. (=Dịch: Những chiếc nồi đất sét phải khô hoàn toàn trước khi được đưa vào lò nung.)","The traditional brick [kiln] produces thousands of bricks each day. (=Dịch: Lò gạch truyền thống sản xuất hàng nghìn viên gạch mỗi ngày.)","She carefully monitored the temperature of the pottery [kiln]. (=Dịch: Cô ấy cẩn thận theo dõi nhiệt độ của lò nung gốm.)"],"ukAudio":"/ai_services/tts3/?q=kiln&lang=en-GB&ipa=%2Fk%C9%AAln%2F","usAudio":"/ai_services/tts3/?q=kiln&lang=en-US&ipa=%2Fk%C9%AAln%2F"},{"id":"lv_4_225","topic":"Cultural and Historical Exchange","word":"kite","pos":"(n)","ipa":"/kaɪt/","defVi":"con diều","defEn":"a light frame covered with paper or cloth, flown in the wind at the end of a long string","examples":["Children love to fly a colorful [kite] in the park on breezy afternoons. (=Dịch: Trẻ em rất thích thả những cánh diều rực rỡ sắc màu trong công viên vào những buổi chiều lộng gió.)","He spent the weekend teaching his young daughter how to build a handmade [kite]. (=Dịch: Anh ấy đã dành cả cuối tuần để dạy cô con gái nhỏ cách tự làm một con diều thủ công.)","The strong gust of wind snapped the string of her [kite]. (=Dịch: Cơn gió giật mạnh đã làm đứt dây con diều của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=kite&lang=en-GB&ipa=%2Fka%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=kite&lang=en-US&ipa=%2Fka%C9%AAt%2F"},{"id":"lv_4_226","topic":"Cultural and Historical Exchange","word":"knit","pos":"(v)","ipa":"/nɪt/","defVi":"đan (len), dệt","defEn":"to make clothes or other items by interlocking loops of wool or yarn with needles","examples":["Her grandmother taught her how to [knit] a warm wool scarf. (=Dịch: Bà của cô đã dạy cô cách đan một chiếc khăn quàng len ấm áp.)","She likes to [knit] sweaters for her grandchildren during the winter. (=Dịch: Bà thích đan áo len cho các cháu của mình vào mùa đông.)","The club members gather every weekend to [knit] blankets for charity. (=Dịch: Các thành viên câu lạc bộ tụ họp vào mỗi cuối tuần để đan chăn làm từ thiện.)"],"ukAudio":"/ai_services/tts3/?q=knit&lang=en-GB&ipa=%2Fn%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=knit&lang=en-US&ipa=%2Fn%C9%AAt%2F"},{"id":"lv_4_227","topic":"Cultural and Historical Exchange","word":"knitting","pos":"(n)","ipa":"/ˈnɪt̬.ɪŋ/","defVi":"việc đan lát, đồ đan bằng len","defEn":"the craft or activity of making garments from yarn with needles, or the fabric produced","examples":["She finds that [knitting] scarves in the evening helps relieve daily stress. (=Dịch: Cô ấy thấy rằng việc đan khăn len vào buổi tối giúp giải tỏa căng thẳng hàng ngày.)","My grandmother always brings her [knitting] whenever she travels by train. (=Dịch: Bà tôi luôn mang theo đồ đan len mỗi khi bà đi tàu hỏa.)","The craft store sells many different tools and colorful yarns for [knitting]. (=Dịch: Cửa hàng thủ công bán nhiều dụng cụ khác nhau và các loại sợi rực rỡ để đan len.)"],"ukAudio":"/ai_services/tts3/?q=knitting&lang=en-GB&ipa=%2F%CB%88n%C9%AAt%CC%AC.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=knitting&lang=en-US&ipa=%2F%CB%88n%C9%AAt%CC%AC.%C9%AA%C5%8B%2F"},{"id":"lv_4_228","topic":"Cultural and Historical Exchange","word":"labyrinth","pos":"(n)","ipa":"/ˈlæb.ə.rɪnθ/","defVi":"mê cung","defEn":"a complicated network of winding passages or paths","examples":["We got lost in a [labyrinth] of narrow streets in the old town. (=Dịch: Chúng tôi bị lạc trong một mê cung các con phố hẹp ở khu phố cổ.)","According to legend, a monster lived at the center of the [labyrinth]. (=Dịch: Theo truyền thuyết, một con quái vật đã sống ở trung tâm của mê cung.)","The new regulations created a [labyrinth] of confusing paperwork. (=Dịch: Các quy định mới đã tạo ra một mê cung các thủ tục giấy tờ rắc rối.)"],"ukAudio":"/ai_services/tts3/?q=labyrinth&lang=en-GB&ipa=%2F%CB%88l%C3%A6b.%C9%99.r%C9%AAn%CE%B8%2F","usAudio":"/ai_services/tts3/?q=labyrinth&lang=en-US&ipa=%2F%CB%88l%C3%A6b.%C9%99.r%C9%AAn%CE%B8%2F"},{"id":"lv_4_229","topic":"Cultural and Historical Exchange","word":"ladder","pos":"(n)","ipa":"/ˈlæd.ɚ/","defVi":"cái thang","defEn":"a piece of equipment consisting of two upright bars connected by rungs, used for climbing","examples":["He climbed up the [ladder] to clean the leaves out of the roof gutter. (=Dịch: Anh ấy đã trèo lên thang để dọn sạch lá cây trong máng xối trên mái nhà.)","She worked hard for years to climb the corporate [ladder]. (=Dịch: Cô ấy đã làm việc chăm chỉ trong nhiều năm để thăng tiến trên nấc thang danh vọng của công ty.)","Please hold the base of the [ladder] firmly while I paint the ceiling. (=Dịch: Vui lòng giữ chắc chân thang trong khi tôi sơn trần nhà.)"],"ukAudio":"/ai_services/tts3/?q=ladder&lang=en-GB&ipa=%2F%CB%88l%C3%A6d.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ladder&lang=en-US&ipa=%2F%CB%88l%C3%A6d.%C9%9A%2F"},{"id":"lv_4_230","topic":"Cultural and Historical Exchange","word":"landing","pos":"(n)","ipa":"/ˈlæn.dɪŋ/","defVi":"sự hạ cánh; chiếu nghỉ (cầu thang)","defEn":"the act of bringing an aircraft or spacecraft down to the ground, or a level area at the top of a staircase","examples":["The pilot made a smooth [landing] despite the strong crosswinds. (=Dịch: Phi công đã hạ cánh êm ái bất chấp gió tạt ngang mạnh.)","She stood on the second-floor [landing] and called down to her brother. (=Dịch: Cô đứng trên chiếu nghỉ tầng hai và gọi với xuống cho em trai mình.)","The emergency [landing] on the river saved the lives of all passengers. (=Dịch: Vụ hạ cánh khẩn cấp xuống dòng sông đã cứu sống toàn bộ hành khách.)"],"ukAudio":"/ai_services/tts3/?q=landing&lang=en-GB&ipa=%2F%CB%88l%C3%A6n.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=landing&lang=en-US&ipa=%2F%CB%88l%C3%A6n.d%C9%AA%C5%8B%2F"},{"id":"lv_4_231","topic":"Cultural and Historical Exchange","word":"landlord","pos":"(n)","ipa":"/ˈlænd.lɔːrd/","defVi":"chủ nhà trọ; chủ đất","defEn":"a person who owns a building or land and rents it to other people","examples":["The tenant contacted the [landlord] to request urgent repairs on the roof. (=Dịch: Người thuê nhà đã liên hệ với chủ nhà để yêu cầu sửa chữa mái nhà khẩn cấp.)","Our [landlord] agreed not to increase the rent for the upcoming year. (=Dịch: Chủ nhà của chúng tôi đã đồng ý không tăng tiền thuê nhà trong năm tới.)","She has been a responsible [landlord] managing several rental properties. (=Dịch: Bà ấy là một chủ nhà có trách nhiệm trong việc quản lý nhiều bất động sản cho thuê.)"],"ukAudio":"/ai_services/tts3/?q=landlord&lang=en-GB&ipa=%2F%CB%88l%C3%A6nd.l%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=landlord&lang=en-US&ipa=%2F%CB%88l%C3%A6nd.l%C9%94%CB%90rd%2F"},{"id":"lv_4_232","topic":"Cultural and Historical Exchange","word":"largely","pos":"(adv)","ipa":"/ˈlɑːrdʒ.li/","defVi":"chủ yếu, phần lớn","defEn":"mostly, primarily, or to a great extent","examples":["The success of the campaign was [largely] due to good planning. (=Dịch: Thành công của chiến dịch phần lớn là nhờ vào việc lập kế hoạch tốt.)","His explanation was [largely] ignored by the audience. (=Dịch: Lời giải thích của anh ấy phần lớn đã bị khán giả phớt lờ.)","The town is [largely] inhabited by retired people. (=Dịch: Thị trấn này phần lớn là nơi sinh sống của những người đã nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=largely&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90rd%CA%92.li%2F","usAudio":"/ai_services/tts3/?q=largely&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90rd%CA%92.li%2F"},{"id":"lv_4_233","topic":"Cultural and Historical Exchange","word":"lasting","pos":"(adj)","ipa":"/ˈlæs.tɪŋ/","defVi":"bền vững, lâu dài, trường tồn","defEn":"continuing to exist for a very long time","examples":["The mentor's advice had a [lasting] impact on her career choices. (=Dịch: Lời khuyên của người cố vấn đã có tác động lâu dài đến những lựa chọn nghề nghiệp của cô ấy.)","They built a [lasting] friendship during their university years. (=Dịch: Họ đã xây dựng một tình bạn bền chặt lâu dài trong những năm tháng đại học.)","The treaty established a [lasting] peace between the two neighboring countries. (=Dịch: Hiệp ước đã thiết lập một nền hòa bình lâu dài giữa hai quốc gia láng giềng.)"],"ukAudio":"/ai_services/tts3/?q=lasting&lang=en-GB&ipa=%2F%CB%88l%C3%A6s.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lasting&lang=en-US&ipa=%2F%CB%88l%C3%A6s.t%C9%AA%C5%8B%2F"},{"id":"lv_4_234","topic":"Cultural and Historical Exchange","word":"leather","pos":"(n)","ipa":"/ˈleð.ɚ/","defVi":"da thuộc, chất liệu da","defEn":"material made from animal skin by tanning or a similar process","examples":["She bought a durable jacket made of genuine [leather]. (=Dịch: Cô ấy đã mua một chiếc áo khoác bền được làm từ da thật.)","The luxury car features comfortable seats upholstered in black [leather]. (=Dịch: Chiếc xe sang trọng có những chiếc ghế êm ái được bọc bằng da màu đen.)","Traditional shoemakers still prefer using natural [leather] for handmade boots. (=Dịch: Những người thợ đóng giày truyền thống vẫn thích sử dụng da tự nhiên cho những đôi bốt thủ công.)"],"ukAudio":"/ai_services/tts3/?q=leather&lang=en-GB&ipa=%2F%CB%88le%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=leather&lang=en-US&ipa=%2F%CB%88le%C3%B0.%C9%9A%2F"},{"id":"lv_4_235","topic":"Cultural and Historical Exchange","word":"librarian","pos":"(n)","ipa":"/laɪˈbrer.i.ən/","defVi":"thủ thư, người quản lý thư viện","defEn":"a person who works in or is in charge of a library","examples":["The [librarian] helped the student find academic journals for his research paper. (=Dịch: Người thủ thư đã giúp sinh viên tìm các tạp chí học thuật cho bài nghiên cứu của mình.)","You can ask the [librarian] to reserve the book if it is currently checked out. (=Dịch: Bạn có thể nhờ thủ thư giữ sách giúp nếu cuốn sách hiện đã được mượn.)","She decided to train as a [librarian] because of her deep passion for reading. (=Dịch: Cô quyết định theo học để trở thành thủ thư vì niềm đam mê đọc sách sâu sắc của mình.)"],"ukAudio":"/ai_services/tts3/?q=librarian&lang=en-GB&ipa=%2Fla%C9%AA%CB%88brer.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=librarian&lang=en-US&ipa=%2Fla%C9%AA%CB%88brer.i.%C9%99n%2F"},{"id":"lv_4_236","topic":"Cultural and Historical Exchange","word":"linen","pos":"(n)","ipa":"/ˈlɪn.ɪn/","defVi":"vải lanh","defEn":"a strong, light cloth made from the fibers of the flax plant","examples":["He wore a light [linen] shirt to keep cool in the humid tropical climate. (=Dịch: Anh ấy mặc một chiếc áo sơ mi vải lanh nhẹ để giữ mát trong khí hậu nhiệt đới ẩm ướt.)","The hotel is known for using high-quality [linen] on all of its beds. (=Dịch: Khách sạn nổi tiếng với việc sử dụng đồ vải lanh chất lượng cao trên tất cả các giường ngủ của mình.)","Pure [linen] tends to wrinkle easily, but it remains a popular choice for summer fashion. (=Dịch: Vải lanh nguyên chất có xu hướng dễ bị nhăn, nhưng nó vẫn là một lựa chọn phổ biến cho thời trang mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=linen&lang=en-GB&ipa=%2F%CB%88l%C9%AAn.%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=linen&lang=en-US&ipa=%2F%CB%88l%C9%AAn.%C9%AAn%2F"},{"id":"lv_4_237","topic":"Cultural and Historical Exchange","word":"lining","pos":"(n)","ipa":"/ˈlaɪ.nɪŋ/","defVi":"lớp lót, vải lót","defEn":"a layer of material covering the inside surface of clothing, bags, or other items","examples":["The winter coat has a warm silk [lining] that keeps out the cold. (=Dịch: Chiếc áo khoác mùa đông có lớp lót lụa ấm áp giúp cản cái lạnh.)","She tore the [lining] of her handbag when looking for her keys. (=Dịch: Cô ấy đã làm rách lớp lót bên trong túi xách khi tìm chìa khóa.)","The stomach [lining] protects the body from strong digestive acids. (=Dịch: Lớp niêm mạc dạ dày bảo vệ cơ thể khỏi các axit tiêu hóa mạnh.)"],"ukAudio":"/ai_services/tts3/?q=lining&lang=en-GB&ipa=%2F%CB%88la%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lining&lang=en-US&ipa=%2F%CB%88la%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_4_238","topic":"Cultural and Historical Exchange","word":"literature","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.tʃɚ/","defVi":"văn học, tác phẩm văn chương","defEn":"written artistic works such as novels, plays, and poetry","examples":["Reading classical [literature] helps improve your vocabulary and critical thinking skills. (=Dịch: Đọc văn học cổ điển giúp nâng cao vốn từ vựng và kỹ năng tư duy phản biện của bạn.)","She has a profound passion for nineteenth-century French [literature]. (=Dịch: Cô có niềm đam mê sâu sắc với văn học Pháp thế kỷ XIX.)","The academic conference focused on contemporary post-war [literature]. (=Dịch: Hội nghị học thuật tập trung vào nền văn học hậu chiến đương đại.)"],"ukAudio":"/ai_services/tts3/?q=literature&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=literature&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F"},{"id":"lv_4_239","topic":"Cultural and Historical Exchange","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"gia súc","defEn":"animals such as cows, sheep, and pigs kept on a farm","examples":["The farmer raises [livestock] to produce milk and meat for the local market. (=Dịch: Người nông dân nuôi gia súc để sản xuất sữa và thịt cho thị trường địa phương.)","Severe drought has made it difficult to find enough water and food for the [livestock]. (=Dịch: Hạn hán nghiêm trọng đã khiến việc tìm đủ nước và thức ăn cho gia súc trở nên khó khăn.)","Vaccinating [livestock] regularly helps prevent the spread of infectious diseases. (=Dịch: Tiêm phòng cho gia súc thường xuyên giúp ngăn ngừa sự lây lan của các bệnh truyền nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_4_240","topic":"Cultural and Historical Exchange","word":"logic","pos":"(n)","ipa":"/ˈlɑː.dʒɪk/","defVi":"sự hợp lý, tính logic, lý lẽ","defEn":"a sensible way of thinking or explaining based on good judgment","examples":["There is no clear [logic] behind the company's decision to cut the training budget. (=Dịch: Không có lập luận hợp lý rõ ràng nào đằng sau quyết định cắt giảm ngân sách đào tạo của công ty.)","Her argument was structured with remarkable clarity and [logic]. (=Dịch: Lập luận của cô được xây dựng với sự rõ ràng và tính logic đáng kinh ngạc.)","Computer programming requires a strong grasp of mathematical [logic]. (=Dịch: Lập trình máy tính đòi hỏi sự nắm vững về logic toán học.)"],"ukAudio":"/ai_services/tts3/?q=logic&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=logic&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AAk%2F"},{"id":"lv_4_241","topic":"Cultural and Historical Exchange","word":"lord","pos":"(n)","ipa":"/lɔːrd/","defVi":"lãnh chúa, quý tộc","defEn":"a man of noble rank or high authority in a traditional society","examples":["In medieval times, the local [lord] ruled over vast areas of agricultural land. (=Dịch: Vào thời trung cổ, lãnh chúa địa phương cai trị những vùng đất nông nghiệp rộng lớn.)","The villagers paid taxes directly to the feudal [lord]. (=Dịch: Dân làng nộp thuế trực tiếp cho lãnh chúa phong kiến.)","The castle served as the official residence of the powerful [lord]. (=Dịch: Lâu đài từng là nơi ở chính thức của vị lãnh chúa quyền lực.)"],"ukAudio":"/ai_services/tts3/?q=lord&lang=en-GB&ipa=%2Fl%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=lord&lang=en-US&ipa=%2Fl%C9%94%CB%90rd%2F"},{"id":"lv_4_242","topic":"Cultural and Historical Exchange","word":"lounge","pos":"(n)","ipa":"/laʊndʒ/","defVi":"phòng chờ, sảnh nghỉ ngơi","defEn":"a public room in a hotel, airport, or club equipped with comfortable seating for waiting or relaxing","examples":["We decided to wait for our flight in the airport [lounge]. (=Dịch: Chúng tôi quyết định ngồi chờ chuyến bay của mình trong phòng chờ sân bay.)","Guests can enjoy afternoon tea in the hotel's spacious [lounge]. (=Dịch: Du khách có thể thưởng thức trà chiều trong phòng chờ rộng rãi của khách sạn.)","The departure [lounge] was crowded with holiday travelers. (=Dịch: Phòng chờ khởi hành đông nghịt những du khách đi nghỉ dưỡng.)"],"ukAudio":"/ai_services/tts3/?q=lounge&lang=en-GB&ipa=%2Fla%CA%8And%CA%92%2F","usAudio":"/ai_services/tts3/?q=lounge&lang=en-US&ipa=%2Fla%CA%8And%CA%92%2F"},{"id":"lv_4_243","topic":"Cultural and Historical Exchange","word":"luxury","pos":"(n)","ipa":"/ˈlʌk.ʃɚ.i/","defVi":"sự xa xỉ, đồ xa xỉ","defEn":"great comfort, expensive quality, or something enjoyable that is not essential","examples":["Living in a five-star hotel for a month was an unaffordable [luxury] for the student. (=Dịch: Sống trong một khách sạn năm sao suốt một tháng là một điều xa xỉ không thể chi trả nổi đối với cậu sinh viên.)","They spent the weekend relaxing in absolute [luxury] at a secluded mountain resort. (=Dịch: Họ đã dành cả cuối tuần để thư giãn trong sự xa hoa tuyệt đối tại một khu nghỉ dưỡng hẻo lánh trên núi.)","Clean drinking water should be a basic human right rather than a rare [luxury]. (=Dịch: Nước uống sạch phải là một quyền cơ bản của con người hơn là một thứ xa xỉ hiếm có.)"],"ukAudio":"/ai_services/tts3/?q=luxury&lang=en-GB&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=luxury&lang=en-US&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%9A.i%2F"},{"id":"lv_4_244","topic":"Cultural and Historical Exchange","word":"magic","pos":"(n)","ipa":"/ˈmædʒ.ɪk/","defVi":"phép thuật, ảo thuật","defEn":"the use of supernatural powers to create illusions or make impossible things happen","examples":["The children watched in wonder as the entertainer performed [magic] tricks. (=Dịch: Những đứa trẻ ngắm nhìn trong sự kinh ngạc khi người biểu diễn thực hiện các màn ảo thuật.)","In fairy tales, heroes often defeat villains with ancient [magic]. (=Dịch: Trong truyện cổ tích, các anh hùng thường đánh bại nhân vật phản diện bằng ma thuật cổ xưa.)","The sunset over the ocean had a special kind of [magic]. (=Dịch: Hoàng hôn trên đại dương mang một vẻ ma mị và kỳ diệu rất đặc biệt.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_4_245","topic":"Cultural and Historical Exchange","word":"magical","pos":"(adj)","ipa":"/ˈmædʒ.ɪ.kəl/","defVi":"kỳ diệu, huyền diệu, thuộc ma thuật","defEn":"produced by or relating to magic; wonderfully special or enchanting","examples":["Watching the northern lights was a truly [magical] experience. (=Dịch: Ngắm nhìn cực quang là một trải nghiệm thực sự kỳ diệu.)","The fairy tale describes a [magical] kingdom hidden deep in the forest. (=Dịch: Câu chuyện cổ tích miêu tả một vương quốc kỳ diệu ẩn sâu trong rừng.)","There is no [magical] solution to solving global poverty overnight. (=Dịch: Không có giải pháp thần kỳ nào để xóa bỏ nghèo đói toàn cầu chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=magical&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=magical&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AA.k%C9%99l%2F"},{"id":"lv_4_246","topic":"Cultural and Historical Exchange","word":"mangroves","pos":"(n)","ipa":"/ˈmæŋ.ɡroʊvz/","defVi":"rừng ngập mặn; cây đước","defEn":"tropical trees or shrubs that grow in coastal saline or brackish water","examples":["Coastal [mangroves] act as natural barriers that protect shores from storm surges. (=Dịch: Rừng ngập mặn ven biển đóng vai trò như những rào cản tự nhiên bảo vệ bờ biển khỏi nước dâng do bão.)","Many species of fish rely on [mangroves] as a safe breeding ground. (=Dịch: Nhiều loài cá dựa vào rừng ngập mặn như một nơi sinh sản an toàn.)","The conservation group works to restore degraded [mangroves] in the delta. (=Dịch: Nhóm bảo tồn nỗ lực phục hồi các khu rừng ngập mặn bị suy thoái ở vùng đồng bằng châu thổ.)"],"ukAudio":"/ai_services/tts3/?q=mangroves&lang=en-GB&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Avz%2F","usAudio":"/ai_services/tts3/?q=mangroves&lang=en-US&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Avz%2F"},{"id":"lv_4_247","topic":"Cultural and Historical Exchange","word":"mask","pos":"(n)","ipa":"/mæsk/","defVi":"mặt nạ, khẩu trang","defEn":"a covering worn over all or part of the face for protection, disguise, or performance","examples":["The surgeon wore a protective [mask] throughout the entire operation. (=Dịch: Bác sĩ phẫu thuật đã đeo khẩu trang bảo hộ trong suốt toàn bộ ca mổ.)","Children painted their own colorful [mask] for the Halloween parade. (=Dịch: Trẻ em đã tự vẽ những chiếc mặt nạ đầy màu sắc cho cuộc diễu hành Halloween.)","He tried to hide his true feelings behind a [mask] of polite indifference. (=Dịch: Anh ta cố gắng che giấu cảm xúc thật của mình đằng sau vỏ bọc của sự thờ ơ lịch sự.)"],"ukAudio":"/ai_services/tts3/?q=mask&lang=en-GB&ipa=%2Fm%C3%A6sk%2F","usAudio":"/ai_services/tts3/?q=mask&lang=en-US&ipa=%2Fm%C3%A6sk%2F"},{"id":"lv_4_248","topic":"Cultural and Historical Exchange","word":"maze","pos":"(n)","ipa":"/meɪz/","defVi":"mê cung","defEn":"a complicated network of paths or passages in which it is difficult to find the way","examples":["We got lost in the garden [maze] for almost an hour. (=Dịch: Chúng tôi đã bị lạc trong mê cung cây trong vườn suốt gần một tiếng đồng hồ.)","The old town is a [maze] of narrow cobbled streets. (=Dịch: Khu phố cổ là một mê cung gồm những con đường lát đá cuội chật hẹp.)","Navigating the legal system felt like walking through an endless [maze]. (=Dịch: Việc tìm hiểu và làm việc với hệ thống pháp lý mang lại cảm giác như đang đi qua một mê cung bất tận.)"],"ukAudio":"/ai_services/tts3/?q=maze&lang=en-GB&ipa=%2Fme%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=maze&lang=en-US&ipa=%2Fme%C9%AAz%2F"},{"id":"lv_4_249","topic":"Cultural and Historical Exchange","word":"memorable","pos":"(adj)","ipa":"/ˈmɛm.ər.ə.bəl/","defVi":"đáng nhớ, khó quên","defEn":"worth remembering or easily remembered because of being special or unusual","examples":["Our trip to the mountains was a truly [memorable] experience. (=Dịch: Chuyến đi lên núi của chúng tôi thực sự là một trải nghiệm đáng nhớ.)","The actor gave a [memorable] performance in his final stage play. (=Dịch: Nam diễn viên đã có một màn trình diễn đáng nhớ trong vở kịch sân khấu cuối cùng của mình.)","She shared some [memorable] stories from her years working abroad. (=Dịch: Cô ấy đã chia sẻ một số câu chuyện đáng nhớ từ những năm tháng làm việc ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=memorable&lang=en-GB&ipa=%2F%CB%88m%C9%9Bm.%C9%99r.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=memorable&lang=en-US&ipa=%2F%CB%88m%C9%9Bm.%C9%99r.%C9%99.b%C9%99l%2F"},{"id":"lv_4_250","topic":"Cultural and Historical Exchange","word":"messy","pos":"(adj)","ipa":"/ˈmɛs.i/","defVi":"bừa bộn, lộn xộn","defEn":"dirty, untidy, or disordered","examples":["His desk was [messy], covered with piles of old documents. (=Dịch: Bàn làm việc của anh ấy rất bừa bộn, phủ đầy những chồng tài liệu cũ.)","Cooking with young children can be a fun but [messy] activity. (=Dịch: Nấu ăn cùng trẻ nhỏ có thể là một hoạt động vui vẻ nhưng lại khá lộn xộn.)","The divorce turned into a long and [messy] legal battle. (=Dịch: Vụ ly hôn đã biến thành một cuộc chiến pháp lý kéo dài và đầy rắc rối.)"],"ukAudio":"/ai_services/tts3/?q=messy&lang=en-GB&ipa=%2F%CB%88m%C9%9Bs.i%2F","usAudio":"/ai_services/tts3/?q=messy&lang=en-US&ipa=%2F%CB%88m%C9%9Bs.i%2F"},{"id":"lv_4_251","topic":"Cultural and Historical Exchange","word":"methodology","pos":"(n)","ipa":"/ˌmeθ.əˈdɑː.lə.dʒi/","defVi":"phương pháp luận, hệ phương pháp nghiên cứu","defEn":"a system of methods and principles used in a particular area of study or activity","examples":["The researchers explained their [methodology] in the introductory chapter. (=Dịch: Các nhà nghiên cứu đã giải thích phương pháp luận của họ trong chương mở đầu.)","Using an appropriate [methodology] is essential for gathering accurate scientific data. (=Dịch: Việc sử dụng phương pháp luận phù hợp là điều cần thiết để thu thập dữ liệu khoa học chính xác.)","She adjusted her research [methodology] after receiving feedback from her supervisor. (=Dịch: Cô ấy đã điều chỉnh phương pháp nghiên cứu của mình sau khi nhận được phản hồi từ người hướng dẫn.)"],"ukAudio":"/ai_services/tts3/?q=methodology&lang=en-GB&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=methodology&lang=en-US&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_4_252","topic":"Cultural and Historical Exchange","word":"migrate","pos":"(v)","ipa":"/ˈmaɪ.ɡreɪt/","defVi":"di cư, di trú","defEn":"to move from one region or habitat to another, especially according to the seasons","examples":["Thousands of swallows [migrate] south every autumn to escape the cold weather. (=Dịch: Hàng ngàn con chim én di cư về phương nam mỗi độ thu về để tránh thời tiết lạnh giá.)","Many young people [migrate] to metropolitan areas in search of employment opportunities. (=Dịch: Nhiều người trẻ di cư đến các vùng đô thị lớn để tìm kiếm cơ hội việc làm.)","Certain fish species [migrate] upstream to lay their eggs in freshwater rivers. (=Dịch: Một số loài cá nhất định di cư ngược dòng để đẻ trứng trong các con sông nước ngọt.)"],"ukAudio":"/ai_services/tts3/?q=migrate&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=migrate&lang=en-US&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F"},{"id":"lv_4_253","topic":"Cultural and Historical Exchange","word":"migration","pos":"(n)","ipa":"/maɪˈɡreɪ.ʃən/","defVi":"sự di cư, sự chuyển dịch","defEn":"the seasonal movement of animals or the relocation of people from one place to another","examples":["The annual [migration] of wildebeests across the savannah attracts many tourists. (=Dịch: Cuộc di cư hàng năm của linh dương đầu bò qua thảo nguyên thu hút rất nhiều khách du lịch.)","Economic hardship led to a mass [migration] from rural areas to urban centers. (=Dịch: Khó khăn kinh tế đã dẫn đến một cuộc di cư hàng loạt từ các vùng nông thôn đến các trung tâm thành thị.)","Scientists track bird [migration] patterns using satellite transmitters. (=Dịch: Các nhà khoa học theo dõi các mô hình di cư của loài chim bằng máy phát tín hiệu vệ tinh.)"],"ukAudio":"/ai_services/tts3/?q=migration&lang=en-GB&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=migration&lang=en-US&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_254","topic":"Cultural and Historical Exchange","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai khoáng, sự khai thác mỏ","defEn":"the industry or activity of digging coal or other valuable minerals out of the ground","examples":["The local economy heavily depends on coal [mining] for employment. (=Dịch: Nền kinh tế địa phương phụ thuộc rất lớn vào ngành khai thác than để tạo việc làm.)","Strict environmental regulations have been introduced to reduce pollution caused by [mining]. (=Dịch: Các quy định nghiêm ngặt về môi trường đã được ban hành nhằm giảm thiểu ô nhiễm do hoạt động khai mỏ gây ra.)","Advancements in technology have improved worker safety in deep-sea [mining]. (=Dịch: Những tiến bộ trong công nghệ đã cải thiện độ an toàn cho người lao động trong hoạt động khai thác dưới biển sâu.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_4_255","topic":"Cultural and Historical Exchange","word":"mixture","pos":"(n)","ipa":"/ˈmɪks.tʃɚ/","defVi":"hỗn hợp, sự pha trộn","defEn":"a combination of different things, substances, or qualities","examples":["Pour the cake [mixture] into a greased baking tin. (=Dịch: Đổ hỗn hợp làm bánh vào khuôn nướng đã được thoa dầu.)","The city has an interesting [mixture] of old and modern architecture. (=Dịch: Thành phố có sự pha trộn thú vị giữa kiến trúc cổ kính và hiện đại.)","She felt a [mixture] of excitement and nervousness before the interview. (=Dịch: Cô cảm thấy vừa phấn khích vừa hồi hộp trước buổi phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=mixture&lang=en-GB&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mixture&lang=en-US&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F"},{"id":"lv_4_256","topic":"Cultural and Historical Exchange","word":"motion","pos":"(n)","ipa":"/ˈmoʊ.ʃən/","defVi":"sự chuyển động; kiến nghị (trong cuộc họp)","defEn":"the act or process of moving, or a formal proposal made in a meeting","examples":["The sensor detects any sudden [motion] inside the secure room. (=Dịch: Cảm biến phát hiện bất kỳ chuyển động đột ngột nào bên trong căn phòng an ninh.)","The gentle rocking [motion] of the boat made the passengers feel sleepy. (=Dịch: Sự đong đưa nhẹ nhàng của con thuyền khiến các hành khách cảm thấy buồn ngủ.)","The board members voted unanimously in favor of the proposed [motion]. (=Dịch: Các thành viên hội đồng quản trị đã bỏ phiếu nhất trí ủng hộ kiến nghị được đề xuất.)"],"ukAudio":"/ai_services/tts3/?q=motion&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motion&lang=en-US&ipa=%2F%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_4_257","topic":"Cultural and Historical Exchange","word":"mould","pos":"(v)","ipa":"/moʊld/","defVi":"đúc, nặn, nhào nặn, định hình","defEn":"to shape a soft material into a specific form, or to influence someone's character","examples":["The artist used warm clay to [mould] a delicate vase. (=Dịch: Người nghệ sĩ đã dùng đất sét ấm để nặn một chiếc bình tinh xảo.)","Good teachers help [mould] the minds and values of young children. (=Dịch: Những người thầy giỏi giúp uốn nắn tâm trí và những giá trị của trẻ nhỏ.)","Chocolatiers pour melted chocolate into trays to [mould] different shapes. (=Dịch: Những người làm sô-cô-la đổ sô-cô-la tan chảy vào khay để tạo thành các hình dạng khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=mould&lang=en-GB&ipa=%2Fmo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=mould&lang=en-US&ipa=%2Fmo%CA%8Ald%2F"},{"id":"lv_4_258","topic":"Cultural and Historical Exchange","word":"mud","pos":"(n)","ipa":"/mʌd/","defVi":"bùn, bùn đất","defEn":"wet, soft, and sticky earth or soil","examples":["The car wheels got stuck in the thick [mud] on the dirt road. (=Dịch: Bánh xe ô tô bị mắc kẹt trong lớp bùn đặc trên con đường đất.)","Children love playing in the [mud] after heavy rainfall. (=Dịch: Trẻ em rất thích chơi đùa trong bùn sau cơn mưa lớn.)","He wiped the [mud] off his boots before entering the house. (=Dịch: Anh ấy lau sạch bùn khỏi đôi ủng trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=mud&lang=en-GB&ipa=%2Fm%CA%8Cd%2F","usAudio":"/ai_services/tts3/?q=mud&lang=en-US&ipa=%2Fm%CA%8Cd%2F"},{"id":"lv_4_259","topic":"Cultural and Historical Exchange","word":"multiple","pos":"(adj)","ipa":"/ˈmʌl.tə.pəl/","defVi":"nhiều, đa dạng","defEn":"involving or consisting of many parts, elements, or individuals","examples":["The victim suffered [multiple] injuries and was rushed to the hospital. (=Dịch: Nạn nhân phải chịu nhiều chấn thương và đã được đưa đi cấp cứu ngay lập tức.)","The test consists of [multiple] choice questions and a short essay. (=Dịch: Bài kiểm tra bao gồm các câu hỏi trắc nghiệm và một bài luận ngắn.)","She cited [multiple] reasons for leaving her previous job. (=Dịch: Cô ấy đã nêu ra nhiều lý do cho việc rời bỏ công việc trước đây.)"],"ukAudio":"/ai_services/tts3/?q=multiple&lang=en-GB&ipa=%2F%CB%88m%CA%8Cl.t%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=multiple&lang=en-US&ipa=%2F%CB%88m%CA%8Cl.t%C9%99.p%C9%99l%2F"},{"id":"lv_4_260","topic":"Cultural and Historical Exchange","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tɚ.i/","defVi":"điều bí ẩn, sự bí ẩn","defEn":"something that is difficult or impossible to understand or explain","examples":["The disappearance of the ancient civilization remains a total [mystery]. (=Dịch: Sự biến mất của nền văn minh cổ đại vẫn là một bí ẩn hoàn toàn.)","Detectives are trying to unravel the [mystery] behind the missing artwork. (=Dịch: Các thám tử đang cố gắng làm sáng tỏ bí ẩn đằng sau tác phẩm nghệ thuật bị mất tích.)","His sudden decision to resign was a complete [mystery] to all his colleagues. (=Dịch: Quyết định từ chức đột ngột của anh ấy là một điều hoàn toàn khó hiểu đối với tất cả đồng nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F"},{"id":"lv_4_261","topic":"Cultural and Historical Exchange","word":"needle","pos":"(v)","ipa":"/ˈni.dəl/","defVi":"chọc ghẹo, khích bác, chọc tức","defEn":"to deliberately annoy or tease someone to provoke a reaction","examples":["His older brother likes to [needle] him about his messy room. (=Dịch: Anh trai cậu ấy rất thích chọc ghẹo cậu về căn phòng bừa bộn.)","Reporters continued to [needle] the politician until he lost his temper. (=Dịch: Các phóng viên liên tục châm chọc chính trị gia cho đến khi ông mất bình tĩnh.)","Try not to let your classmates [needle] you into making a poor decision. (=Dịch: Cố gắng đừng để bạn cùng lớp khiêu khích khiến bạn đưa ra quyết định sai lầm.)"],"ukAudio":"/ai_services/tts3/?q=needle&lang=en-GB&ipa=%2F%CB%88ni.d%C9%99l%2F","usAudio":"/ai_services/tts3/?q=needle&lang=en-US&ipa=%2F%CB%88ni.d%C9%99l%2F"},{"id":"lv_4_262","topic":"Cultural and Historical Exchange","word":"new zealand","pos":"(n)","ipa":"/ˌnuː ˈziː.lənd/","defVi":"nước Niu Di-lân, New Zealand","defEn":"an island country in the southwestern Pacific Ocean known for its natural beauty and wildlife","examples":["Many outdoor enthusiasts travel to [New Zealand] to hike through its majestic mountains. (=Dịch: Nhiều người đam mê các hoạt động ngoài trời đến New Zealand để đi bộ leo núi qua những dãy núi hùng vĩ.)","Dairy farming is one of the most vital export industries in [New Zealand]. (=Dịch: Chăn nuôi bò sữa là một trong những ngành xuất khẩu quan trọng nhất ở New Zealand.)","Famous fantasy films were shot entirely on location across [New Zealand]. (=Dịch: Những bộ phim giả tưởng nổi tiếng đã được quay hoàn toàn tại các địa điểm thực tế trên khắp New Zealand.)"],"ukAudio":"/ai_services/tts3/?q=new+zealand&lang=en-GB&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=new+zealand&lang=en-US&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F"},{"id":"lv_4_263","topic":"Cultural and Historical Exchange","word":"nineteenth","pos":"(adj)","ipa":"/ˌnaɪn.ˈtinθ/","defVi":"thứ mười chín","defEn":"constituting number nineteen in a sequence; coming after the eighteenth","examples":["Many social changes took place during the [nineteenth] century. (=Dịch: Nhiều thay đổi xã hội đã diễn ra trong suốt thế kỷ thứ mười chín.)","Today is her [nineteenth] birthday, and she is having a small party. (=Dịch: Hôm nay là sinh nhật lần thứ mười chín của cô ấy, và cô ấy đang tổ chức một bữa tiệc nhỏ.)","He finished in [nineteenth] place out of more than fifty runners. (=Dịch: Anh ấy về đích ở vị trí thứ mười chín trong tổng số hơn năm mươi người chạy.)"],"ukAudio":"/ai_services/tts3/?q=nineteenth&lang=en-GB&ipa=%2F%CB%8Cna%C9%AAn.%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=nineteenth&lang=en-US&ipa=%2F%CB%8Cna%C9%AAn.%CB%88tin%CE%B8%2F"},{"id":"lv_4_264","topic":"Cultural and Historical Exchange","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, lời nhận xét","defEn":"the act of watching somebody or something carefully, or a remark based on what is noticed","examples":["The scientist spent years making detailed [observation] of bird migration patterns. (=Dịch: Nhà khoa học đã dành nhiều năm thực hiện việc quan sát chi tiết về các mô hình di cư của loài chim.)","She made an insightful [observation] about the current economic situation. (=Dịch: Cô ấy đã đưa ra một nhận xét sâu sắc về tình hình kinh tế hiện nay.)","The patient was kept in the hospital overnight for close [observation]. (=Dịch: Bệnh nhân được giữ lại bệnh viện qua đêm để theo dõi chặt chẽ.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_265","topic":"Cultural and Historical Exchange","word":"obstacle","pos":"(n)","ipa":"/ˈɑːb.stə.kəl/","defVi":"trở ngại, chướng ngại vật","defEn":"something that makes it difficult for you to achieve something","examples":["Lack of funding proved to be a major [obstacle] to completing the project. (=Dịch: Sự thiếu hụt kinh phí hóa ra là một trở ngại lớn đối với việc hoàn thành dự án.)","She had to overcome many an [obstacle] before reaching her career goals. (=Dịch: Cô ấy đã phải vượt qua muôn vàn trở ngại trước khi đạt được các mục tiêu nghề nghiệp của mình.)","Language differences can sometimes act as an [obstacle] to effective communication. (=Dịch: Sự khác biệt về ngôn ngữ đôi khi có thể trở thành rào cản đối với việc giao tiếp hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=obstacle&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90b.st%C9%99.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=obstacle&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90b.st%C9%99.k%C9%99l%2F"},{"id":"lv_4_266","topic":"Cultural and Historical Exchange","word":"olympic","pos":"(adj)","ipa":"/oʊˈlɪm.pɪk/","defVi":"thuộc về Thế vận hội Olympic","defEn":"relating to the ancient or modern Olympic Games","examples":["Winning an [Olympic] gold medal was the dream of her life. (=Dịch: Giành được huy chương vàng Olympic là ước mơ cả đời của cô ấy.)","The city built a new [Olympic] stadium for the upcoming games. (=Dịch: Thành phố đã xây dựng một sân vận động Olympic mới cho kỳ thế vận hội sắp tới.)","He trained rigorously to meet the strict [Olympic] qualifying standards. (=Dịch: Anh ấy đã tập luyện nghiêm ngặt để đáp ứng các tiêu chuẩn vòng loại Olympic khắt khe.)"],"ukAudio":"/ai_services/tts3/?q=olympic&lang=en-GB&ipa=%2Fo%CA%8A%CB%88l%C9%AAm.p%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=olympic&lang=en-US&ipa=%2Fo%CA%8A%CB%88l%C9%AAm.p%C9%AAk%2F"},{"id":"lv_4_267","topic":"Cultural and Historical Exchange","word":"onwards","pos":"(adv)","ipa":"/ˈɑːn.wɚdz/","defVi":"trở đi, về phía trước","defEn":"continuing forward in space or time from a particular point","examples":["From the age of eighteen [onwards], she lived independently. (=Dịch: Kể từ năm mười tám tuổi trở đi, cô ấy đã sống tự lập.)","The project moved [onwards] despite several technical difficulties. (=Dịch: Dự án vẫn tiếp tục tiến triển bất chấp một số khó khăn về mặt kỹ thuật.)","The exhibition is open daily from ten in the morning [onwards]. (=Dịch: Triển lãm mở cửa hàng ngày từ mười giờ sáng trở đi.)"],"ukAudio":"/ai_services/tts3/?q=onwards&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90n.w%C9%9Adz%2F","usAudio":"/ai_services/tts3/?q=onwards&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90n.w%C9%9Adz%2F"},{"id":"lv_4_268","topic":"Cultural and Historical Exchange","word":"opera","pos":"(n)","ipa":"/ˈɑː.prə/","defVi":"vở nhạc kịch opera, ca kịch","defEn":"a musical play in which most of the words are sung rather than spoken","examples":["We bought front-row tickets to watch a famous Italian [opera]. (=Dịch: Chúng tôi đã mua vé hàng ghế đầu để xem một vở opera nổi tiếng của Ý.)","She has trained for years to become a professional [opera] singer. (=Dịch: Cô ấy đã rèn luyện nhiều năm để trở thành một ca sĩ opera chuyên nghiệp.)","The city's grand [opera] house was built more than a century ago. (=Dịch: Nhà hát opera tráng lệ của thành phố được xây dựng cách đây hơn một thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=opera&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.pr%C9%99%2F","usAudio":"/ai_services/tts3/?q=opera&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.pr%C9%99%2F"},{"id":"lv_4_269","topic":"Cultural and Historical Exchange","word":"optimistic","pos":"(adj)","ipa":"/ˌɑːp.təˈmɪs.tɪk/","defVi":"lạc quan","defEn":"expecting good things to happen or something to be successful","examples":["He remains [optimistic] about the future of the company. (=Dịch: Anh ấy vẫn lạc quan về tương lai của công ty.)","Despite the difficulties, she maintains an [optimistic] attitude. (=Dịch: Bất chấp những khó khăn, cô ấy vẫn duy trì một thái độ lạc quan.)","Experts are [optimistic] that the economy will recover next year. (=Dịch: Các chuyên gia rất lạc quan rằng nền kinh tế sẽ phục hồi vào năm tới.)"],"ukAudio":"/ai_services/tts3/?q=optimistic&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90p.t%C9%99%CB%88m%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=optimistic&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90p.t%C9%99%CB%88m%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_270","topic":"Cultural and Historical Exchange","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians playing many different instruments together and led by a conductor","examples":["The symphony [orchestra] performed a masterpiece by Beethoven last night. (=Dịch: Dàn nhạc giao hưởng đã biểu diễn một kiệt tác của Beethoven vào tối qua.)","He plays the violin in a prestigious youth [orchestra]. (=Dịch: Cậu ấy chơi vĩ cầm trong một dàn nhạc trẻ danh tiếng.)","The conductor raised his baton and the entire [orchestra] went silent. (=Dịch: Nhạc trưởng giơ đũa chỉ huy lên và toàn bộ dàn nhạc liền im lặng.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_4_271","topic":"Cultural and Historical Exchange","word":"orchestral","pos":"(adj)","ipa":"/ɔrˈkɛs.trəl/","defVi":"thuộc về dàn nhạc giao hưởng","defEn":"composed for, performed by, or relating to an orchestra","examples":["The concert featured a magnificent [orchestral] performance by local musicians. (=Dịch: Buổi hòa nhạc có một màn trình diễn dàn nhạc tuyệt vời của các nhạc sĩ địa phương.)","She has composed several [orchestral] pieces for film soundtracks. (=Dịch: Cô ấy đã sáng tác một số tác phẩm cho dàn nhạc phục vụ nhạc phim.)","The conductor is rehearsing the new [orchestral] score with the team. (=Dịch: Nhạc trưởng đang tập dượt tổng phổ dàn nhạc mới cùng với cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=orchestral&lang=en-GB&ipa=%2F%C9%94r%CB%88k%C9%9Bs.tr%C9%99l%2F","usAudio":"/ai_services/tts3/?q=orchestral&lang=en-US&ipa=%2F%C9%94r%CB%88k%C9%9Bs.tr%C9%99l%2F"},{"id":"lv_4_272","topic":"Cultural and Historical Exchange","word":"origin","pos":"(n)","ipa":"/ˈɔːr.ə.dʒɪn/","defVi":"nguồn gốc, căn nguyên","defEn":"the point or place where something begins or comes from","examples":["Scientists are studying the [origin] of the universe. (=Dịch: Các nhà khoa học đang nghiên cứu nguồn gốc của vũ trụ.)","The word has its [origin] in ancient Latin. (=Dịch: Từ này có nguồn gốc từ tiếng Latinh cổ.)","She never forgot the humble [origin] of her family. (=Dịch: Cô ấy chưa bao giờ quên xuất thân khiêm tốn của gia đình mình.)"],"ukAudio":"/ai_services/tts3/?q=origin&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=origin&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F"},{"id":"lv_4_273","topic":"Cultural and Historical Exchange","word":"outcome","pos":"(n)","ipa":"/ˈaʊtˌkʌm/","defVi":"kết quả, hậu quả","defEn":"the final result of an activity, process, or meeting","examples":["The [outcome] of the election will shape the country's economic policies. (=Dịch: Kết quả của cuộc bầu cử sẽ định hình các chính sách kinh tế của đất nước.)","Doctors are cautiously optimistic about the [outcome] of the surgery. (=Dịch: Các bác sĩ tỏ ra lạc quan một cách thận trọng về kết quả của ca phẫu thuật.)","Several factors can influence the final [outcome] of this research project. (=Dịch: Một số yếu tố có thể ảnh hưởng đến kết quả cuối cùng của dự án nghiên cứu này.)"],"ukAudio":"/ai_services/tts3/?q=outcome&lang=en-GB&ipa=%2F%CB%88a%CA%8At%CB%8Ck%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=outcome&lang=en-US&ipa=%2F%CB%88a%CA%8At%CB%8Ck%CA%8Cm%2F"},{"id":"lv_4_274","topic":"Cultural and Historical Exchange","word":"pacific","pos":"(n)","ipa":"/pəˈsɪf.ɪk/","defVi":"Thái Bình Dương","defEn":"the largest of the world's oceans, lying between America to the east and Asia and Australia to the west","examples":["Several island nations are scattered across the vast [Pacific] Ocean. (=Dịch: Một số quốc đảo nằm rải rác trên khắp Thái Bình Dương rộng lớn.)","They embarked on a cruise across the South [Pacific]. (=Dịch: Họ đã bắt đầu chuyến du ngoạn trên biển băng qua vùng Nam Thái Bình Dương.)","Marine biologists are studying rare deep-sea species found in the North [Pacific]. (=Dịch: Các nhà sinh vật biển đang nghiên cứu các loài sinh vật biển sâu quý hiếm được tìm thấy ở Bắc Thái Bình Dương.)"],"ukAudio":"/ai_services/tts3/?q=pacific&lang=en-GB&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=pacific&lang=en-US&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F"},{"id":"lv_4_275","topic":"Cultural and Historical Exchange","word":"perfume","pos":"(n)","ipa":"/ˈpɝː.fjuːm/","defVi":"nước hoa, hương thơm","defEn":"a liquid with a pleasant smell that people spray on their skin or clothes","examples":["She sprayed a floral [perfume] onto her wrists before heading out to the party. (=Dịch: Cô ấy đã xịt một chút nước hoa hương hoa cỏ lên cổ tay trước khi ra ngoài dự tiệc.)","The delicate [perfume] of blooming roses filled the entire garden. (=Dịch: Hương thơm thoang thoảng của hoa hồng nở rộ tràn ngập khắp cả khu vườn.)","France is world-renowned for producing some of the most expensive [perfume] brands. (=Dịch: Nước Pháp nổi tiếng thế giới về việc sản xuất một số thương hiệu nước hoa đắt đỏ nhất.)"],"ukAudio":"/ai_services/tts3/?q=perfume&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.fju%CB%90m%2F","usAudio":"/ai_services/tts3/?q=perfume&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.fju%CB%90m%2F"},{"id":"lv_4_276","topic":"Cultural and Historical Exchange","word":"phenomenon","pos":"(n)","ipa":"/fəˈnɑː.məˌnɑːn/","defVi":"hiện tượng","defEn":"a fact or event in nature or society, especially one that is not fully understood","examples":["Global warming is a complex environmental [phenomenon] that affects the entire planet. (=Dịch: Sự nóng lên toàn cầu là một hiện tượng môi trường phức tạp ảnh hưởng đến toàn bộ hành tinh.)","Scientists gathered to observe the rare celestial [phenomenon]. (=Dịch: Các nhà khoa học đã tập hợp lại để quan sát hiện tượng thiên văn hiếm gặp này.)","The rapid growth of online learning has become a global [phenomenon]. (=Dịch: Sự phát triển nhanh chóng của hình thức học trực tuyến đã trở thành một hiện tượng toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=phenomenon&lang=en-GB&ipa=%2Ff%C9%99%CB%88n%C9%91%CB%90.m%C9%99%CB%8Cn%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=phenomenon&lang=en-US&ipa=%2Ff%C9%99%CB%88n%C9%91%CB%90.m%C9%99%CB%8Cn%C9%91%CB%90n%2F"},{"id":"lv_4_277","topic":"Cultural and Historical Exchange","word":"philosopher","pos":"(n)","ipa":"/fəˈlɑː.sə.fɚ/","defVi":"nhà triết học, triết gia","defEn":"a person who studies or writes about the fundamental questions of life and existence","examples":["Socrates was an influential Greek [philosopher] whose teachings shaped Western thought. (=Dịch: Socrates là một triết gia Hy Lạp có tầm ảnh hưởng lớn, người mà những lời dạy của ông đã định hình nên tư tưởng phương Tây.)","A modern [philosopher] often analyzes the moral implications of artificial intelligence. (=Dịch: Một triết gia hiện đại thường phân tích các tác động về mặt đạo đức của trí tuệ nhân tạo.)","He is widely regarded as a brilliant [philosopher] of science and ethics. (=Dịch: Ông được nhiều người coi là một nhà triết học lỗi lạc về khoa học và đạo đức học.)"],"ukAudio":"/ai_services/tts3/?q=philosopher&lang=en-GB&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.f%C9%9A%2F","usAudio":"/ai_services/tts3/?q=philosopher&lang=en-US&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.f%C9%9A%2F"},{"id":"lv_4_278","topic":"Cultural and Historical Exchange","word":"philosophy","pos":"(n)","ipa":"/fəˈlɑː.sə.fi/","defVi":"triết học, triết lý","defEn":"the study of the fundamental nature of knowledge, reality, and existence","examples":["She decided to major in [philosophy] because she loved debating ethical questions. (=Dịch: Cô ấy quyết định theo học chuyên ngành triết học vì cô ấy thích tranh luận về các câu hỏi đạo đức.)","The company's [philosophy] focuses on sustainability and customer satisfaction. (=Dịch: Triết lý của công ty tập trung vào tính bền vững và sự hài lòng của khách hàng.)","Eastern [philosophy] often emphasizes harmony between human beings and the natural world. (=Dịch: Triết học phương Đông thường nhấn mạnh sự hòa hợp giữa con người và thế giới tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=philosophy&lang=en-GB&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=philosophy&lang=en-US&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.fi%2F"},{"id":"lv_4_279","topic":"Cultural and Historical Exchange","word":"physician","pos":"(n)","ipa":"/fɪˈzɪʃ.ən/","defVi":"bác sĩ (thường là bác sĩ nội khoa hoặc điều trị y tế)","defEn":"a medical doctor, especially one who specializes in diagnosis and medical treatment rather than surgery","examples":["She consulted a [physician] after experiencing persistent headaches. (=Dịch: Cô ấy đã đến khám bác sĩ sau khi bị đau đầu dai dẳng.)","The hospital employs several experienced [physicians] in its cardiology department. (=Dịch: Bệnh viện tuyển dụng nhiều bác sĩ giàu kinh nghiệm trong khoa tim mạch.)","Always follow the advice of a qualified [physician] before taking new medication. (=Dịch: Hãy luôn làm theo lời khuyên của bác sĩ có chuyên môn trước khi dùng thuốc mới.)"],"ukAudio":"/ai_services/tts3/?q=physician&lang=en-GB&ipa=%2Ff%C9%AA%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=physician&lang=en-US&ipa=%2Ff%C9%AA%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_280","topic":"Cultural and Historical Exchange","word":"pianist","pos":"(n)","ipa":"/ˈpiː.ə.nɪst/","defVi":"nghệ sĩ dương cầm, người chơi đàn piano","defEn":"a person who plays the piano, especially skillfully or professionally","examples":["The talented [pianist] received a standing ovation after performing the concerto. (=Dịch: Nghệ sĩ dương cầm tài năng đã nhận được tràng pháo tay nhiệt liệt sau khi biểu diễn bản hòa tấu.)","She hopes to become a concert [pianist] after graduating from the music academy. (=Dịch: Cô ấy hy vọng trở thành một nghệ sĩ dương cầm biểu diễn hòa nhạc sau khi tốt nghiệp học viện âm nhạc.)","A jazz [pianist] was hired to entertain guests during the dinner party. (=Dịch: Một nghệ sĩ dương cầm nhạc jazz đã được thuê để biểu diễn phục vụ khách trong bữa tiệc tối.)"],"ukAudio":"/ai_services/tts3/?q=pianist&lang=en-GB&ipa=%2F%CB%88pi%CB%90.%C9%99.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=pianist&lang=en-US&ipa=%2F%CB%88pi%CB%90.%C9%99.n%C9%AAst%2F"},{"id":"lv_4_281","topic":"Cultural and Historical Exchange","word":"pit","pos":"(n)","ipa":"/pɪt/","defVi":"hố sâu, hầm than hoặc mỏ khoáng sản","defEn":"a large deep hole in the ground, or a place where minerals are mined","examples":["The workers dug a deep [pit] to lay the foundation for the new building. (=Dịch: Các công nhân đã đào một cái hố sâu để đặt móng cho tòa nhà mới.)","Many men in the town used to work down in the coal [pit]. (=Dịch: Nhiều người đàn ông trong thị trấn từng làm việc dưới hầm mỏ than.)","Be careful not to fall into the gravel [pit] near the construction site. (=Dịch: Hãy cẩn thận kẻo ngã vào hố sỏi gần công trường xây dựng.)"],"ukAudio":"/ai_services/tts3/?q=pit&lang=en-GB&ipa=%2Fp%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pit&lang=en-US&ipa=%2Fp%C9%AAt%2F"},{"id":"lv_4_282","topic":"Cultural and Historical Exchange","word":"plantation","pos":"(n)","ipa":"/plænˈteɪ.ʃən/","defVi":"đồn điền, trang trại lớn","defEn":"a large area of land on which crops such as tea, coffee, or rubber are grown","examples":["Many local workers are employed on the vast tea [plantation]. (=Dịch: Nhiều lao động địa phương được thuê làm việc tại đồn điền chè rộng lớn.)","The company owns a large rubber [plantation] in the southern region. (=Dịch: Công ty sở hữu một đồn điền cao su lớn ở khu vực phía nam.)","They took a guided tour through an old coffee [plantation] during their vacation. (=Dịch: Họ đã tham gia một chuyến tham quan có hướng dẫn viên qua một đồn điền cà phê lâu đời trong kỳ nghỉ của mình.)"],"ukAudio":"/ai_services/tts3/?q=plantation&lang=en-GB&ipa=%2Fpl%C3%A6n%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=plantation&lang=en-US&ipa=%2Fpl%C3%A6n%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_283","topic":"Cultural and Historical Exchange","word":"plot","pos":"(n)","ipa":"/plɑːt/","defVi":"cốt truyện; mảnh đất","defEn":"the series of events forming the main story of a book, film, or play","examples":["The novel has an intricate [plot] filled with unexpected twists. (=Dịch: Cuốn tiểu thuyết có một cốt truyện phức tạp với đầy những nút thắt bất ngờ.)","They purchased a small [plot] of land to build their dream house. (=Dịch: Họ đã mua một mảnh đất nhỏ để xây dựng ngôi nhà mơ ước của mình.)","Critics praised the movie for its engaging characters and solid [plot]. (=Dịch: Các nhà phê bình đã khen ngợi bộ phim vì các nhân vật lôi cuốn và cốt truyện chặt chẽ.)"],"ukAudio":"/ai_services/tts3/?q=plot&lang=en-GB&ipa=%2Fpl%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=plot&lang=en-US&ipa=%2Fpl%C9%91%CB%90t%2F"},{"id":"lv_4_284","topic":"Cultural and Historical Exchange","word":"plough","pos":"(v)","ipa":"/plaʊ/","defVi":"cày xới, cày ruộng","defEn":"to dig and turn over soil with a large farming tool before planting seeds","examples":["Farmers usually [plough] their fields in early spring before planting crops. (=Dịch: Nông dân thường cày ruộng vào đầu mùa xuân trước khi gieo trồng mùa màng.)","The tractor was used to [plough] the rocky hillside efficiently. (=Dịch: Máy kéo được sử dụng để cày xới sườn đồi nhiều đá một cách hiệu quả.)","They had to [plough] through the thick snow to clear the main road. (=Dịch: Họ đã phải ủi qua lớp tuyết dày để khai thông con đường chính.)"],"ukAudio":"/ai_services/tts3/?q=plough&lang=en-GB&ipa=%2Fpla%CA%8A%2F","usAudio":"/ai_services/tts3/?q=plough&lang=en-US&ipa=%2Fpla%CA%8A%2F"},{"id":"lv_4_285","topic":"Cultural and Historical Exchange","word":"polish","pos":"(v)","ipa":"/ˈpɑ.lɪʃ/","defVi":"đánh bóng, trau chuốt, hoàn thiện","defEn":"to make something smooth and shiny, or to improve and refine it","examples":["You should [polish] your leather shoes before going to the interview. (=Dịch: Bạn nên đánh bóng giày da trước khi đi phỏng vấn.)","The student spent the weekend trying to [polish] her essay. (=Dịch: Nữ sinh đã dành cả cuối tuần để cố gắng trau chuốt bài luận của mình.)","He practiced speaking every day to [polish] his presentation skills. (=Dịch: Anh ấy luyện nói mỗi ngày để mài giũa kỹ năng thuyết trình của mình.)"],"ukAudio":"/ai_services/tts3/?q=polish&lang=en-GB&ipa=%2F%CB%88p%C9%91.l%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=polish&lang=en-US&ipa=%2F%CB%88p%C9%91.l%C9%AA%CA%83%2F"},{"id":"lv_4_286","topic":"Cultural and Historical Exchange","word":"polished","pos":"(adj)","ipa":"/ˈpɑː.lɪʃt/","defVi":"sáng bóng, trau chuốt, điêu luyện","defEn":"having a smooth, shiny surface from rubbing; refined and well-rehearsed","examples":["She wore elegant shoes that walked across the [polished] wooden floor. (=Dịch: Cô ấy đi đôi giày thanh lịch bước qua sàn gỗ sáng bóng.)","The candidate delivered a very [polished] and confident speech. (=Dịch: Ứng viên đã có một bài phát biểu rất trau chuốt và đầy tự tin.)","His [polished] manners made a great impression on the guests. (=Dịch: Cách cư xử lịch thiệp của anh ấy đã để lại ấn tượng tuyệt vời cho các vị khách.)"],"ukAudio":"/ai_services/tts3/?q=polished&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%AA%CA%83t%2F","usAudio":"/ai_services/tts3/?q=polished&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%AA%CA%83t%2F"},{"id":"lv_4_287","topic":"Cultural and Historical Exchange","word":"politician","pos":"(n)","ipa":"/ˌpɑː.ləˈtɪʃ.ən/","defVi":"chính trị gia","defEn":"a person who is professionally involved in politics, especially as an elected official","examples":["The local [politician] promised to improve public transport during her campaign. (=Dịch: Chính trị gia địa phương đã hứa sẽ cải thiện giao thông công cộng trong chiến dịch tranh cử của bà.)","Many young people feel that [politicians] do not represent their interests. (=Dịch: Nhiều người trẻ cảm thấy rằng các chính trị gia không đại diện cho lợi ích của họ.)","The [politician] gave an inspiring speech about environmental conservation. (=Dịch: Chính trị gia đã có một bài phát biểu đầy cảm hứng về việc bảo tồn môi trường.)"],"ukAudio":"/ai_services/tts3/?q=politician&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.l%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=politician&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.l%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_288","topic":"Cultural and Historical Exchange","word":"porcelain","pos":"(n)","ipa":"/ˈpɔːr.sə.lɪn/","defVi":"đồ sứ, chất liệu sứ","defEn":"a hard, white, translucent ceramic material made by heating clay at high temperatures","examples":["The museum displays an exquisite collection of ancient Chinese [porcelain]. (=Dịch: Bảo tàng trưng bày một bộ sưu tập đồ sứ Trung Quốc cổ đại tuyệt đẹp.)","She carefully handled the delicate [porcelain] teacup to avoid chipping it. (=Dịch: Cô cẩn thận cầm tách trà bằng sứ mỏng manh để tránh làm sứt mẻ.)","High-quality [porcelain] is known for its durability and smooth finish. (=Dịch: Đồ sứ chất lượng cao nổi tiếng về độ bền và bề mặt nhẵn mịn.)"],"ukAudio":"/ai_services/tts3/?q=porcelain&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.s%C9%99.l%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=porcelain&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.s%C9%99.l%C9%AAn%2F"},{"id":"lv_4_289","topic":"Cultural and Historical Exchange","word":"port","pos":"(n)","ipa":"/pɔːrt/","defVi":"cảng, thành phố cảng","defEn":"a town or city with a harbor where ships load and unload goods or passengers","examples":["The cargo vessel finally arrived at the busy commercial [port] after a long voyage. (=Dịch: Tàu chở hàng cuối cùng đã cập cảng thương mại sầm uất sau một chuyến hải trình dài.)","Exporting goods through the international [port] helps boost the regional economy. (=Dịch: Việc xuất khẩu hàng hóa qua cảng quốc tế giúp thúc đẩy nền kinh tế khu vực.)","Fishermen returned to the safe [port] before the heavy storm hit the coast. (=Dịch: Các ngư dân đã quay trở lại cảng an toàn trước khi cơn bão lớn đổ bộ vào bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=port&lang=en-GB&ipa=%2Fp%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=port&lang=en-US&ipa=%2Fp%C9%94%CB%90rt%2F"},{"id":"lv_4_290","topic":"Cultural and Historical Exchange","word":"portrait","pos":"(n)","ipa":"/ˈpɔːr.trət/","defVi":"bức chân dung","defEn":"a painting, drawing, or photograph of a person, especially showing the face","examples":["The gallery displayed a famous [portrait] of the queen. (=Dịch: Phòng trưng bày đã trưng bày một bức chân dung nổi tiếng của nữ hoàng.)","He commissioned an artist to paint a family [portrait]. (=Dịch: Anh ấy đã thuê một họa sĩ vẽ một bức chân dung gia đình.)","The biography provides an accurate [portrait] of the president's life. (=Dịch: Cuốn tiểu sử khắc họa một bức chân dung chính xác về cuộc đời của tổng thống.)"],"ukAudio":"/ai_services/tts3/?q=portrait&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.tr%C9%99t%2F","usAudio":"/ai_services/tts3/?q=portrait&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.tr%C9%99t%2F"},{"id":"lv_4_291","topic":"Cultural and Historical Exchange","word":"pot","pos":"(n)","ipa":"/pɑːt/","defVi":"nồi, xoong, chậu (cây)","defEn":"a deep, round container used for cooking, holding liquids, or growing plants","examples":["She put a large [pot] of soup on the stove to simmer for dinner. (=Dịch: Cô ấy đặt một nồi súp lớn lên bếp để ninh nhỏ lửa cho bữa tối.)","He transplanted the small herb into a ceramic [pot] on the windowsill. (=Dịch: Anh ấy đã chuyển cây thảo mộc nhỏ vào một chiếc chậu gốm trên bậu cửa sổ.)","Archaeologists discovered an ancient clay [pot] buried deep beneath the ruins. (=Dịch: Các nhà khảo cổ học đã phát hiện ra một chiếc bình đất sét cổ được chôn sâu bên dưới đống tàn tích.)"],"ukAudio":"/ai_services/tts3/?q=pot&lang=en-GB&ipa=%2Fp%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=pot&lang=en-US&ipa=%2Fp%C9%91%CB%90t%2F"},{"id":"lv_4_292","topic":"Cultural and Historical Exchange","word":"potter","pos":"(n)","ipa":"/ˈpɑː.t̬ɚ/","defVi":"thợ làm gốm","defEn":"a person who makes pottery dishes, pots, and other objects out of clay","examples":["The skilled [potter] shaped the wet clay into an elegant vase. (=Dịch: Người thợ gốm lành nghề đã nặn đất sét ướt thành một chiếc bình thanh lịch.)","Visitors can watch the local [potter] at work in the artisan village. (=Dịch: Du khách có thể xem người thợ gốm địa phương làm việc trong làng nghề thủ công.)","She bought a handmade ceramic mug directly from the [potter]. (=Dịch: Cô ấy đã mua một chiếc cốc gốm thủ công trực tiếp từ người thợ gốm.)"],"ukAudio":"/ai_services/tts3/?q=potter&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=potter&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_4_293","topic":"Cultural and Historical Exchange","word":"pottery","pos":"(n)","ipa":"/ˈpɑː.t̬ɚ.i/","defVi":"đồ gốm, nghề gốm","defEn":"objects such as plates and cups made out of clay and baked in an oven","examples":["Archaeologists discovered pieces of ancient [pottery] at the site. (=Dịch: Các nhà khảo cổ học đã phát hiện ra những mảnh đồ gốm cổ tại địa điểm này.)","She enjoys making handmade [pottery] in her spare time. (=Dịch: Cô ấy thích làm đồ gốm thủ công vào thời gian rảnh.)","The museum has a magnificent collection of Greek [pottery]. (=Dịch: Bảo tàng có một bộ sưu tập đồ gốm Hy Lạp tuyệt đẹp.)"],"ukAudio":"/ai_services/tts3/?q=pottery&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=pottery&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A.i%2F"},{"id":"lv_4_294","topic":"Cultural and Historical Exchange","word":"pour","pos":"(v)","ipa":"/pɔr/","defVi":"rót, đổ, trút nước","defEn":"to cause liquid to flow continuously out of a container","examples":["Please [pour] some fresh water into my glass. (=Dịch: Xin vui lòng rót một ít nước sạch vào ly của tôi.)","Dark clouds gathered overhead and rain began to [pour] down heavily. (=Dịch: Mây đen kéo đến trên đầu và mưa bắt đầu trút xuống xối xả.)","Carefully [pour] the mixture into the baking dish and put it in the oven. (=Dịch: Hãy cẩn thận đổ hỗn hợp vào khuôn nướng rồi cho vào lò.)"],"ukAudio":"/ai_services/tts3/?q=pour&lang=en-GB&ipa=%2Fp%C9%94r%2F","usAudio":"/ai_services/tts3/?q=pour&lang=en-US&ipa=%2Fp%C9%94r%2F"},{"id":"lv_4_295","topic":"Cultural and Historical Exchange","word":"poverty","pos":"(n)","ipa":"/ˈpɑː.vɚ.t̬i/","defVi":"sự nghèo khó, cảnh bần cùng","defEn":"the state of being extremely poor and lacking basic necessities","examples":["Many families in the region are living in extreme [poverty]. (=Dịch: Nhiều gia đình trong khu vực đang sống trong cảnh nghèo đói cùng cực.)","Education is widely considered a key tool to escape [poverty]. (=Dịch: Giáo dục được coi rộng rãi là công cụ then chốt để thoát nghèo.)","The government launched several programs to reduce child [poverty]. (=Dịch: Chính phủ đã khởi xướng một số chương trình nhằm giảm tỷ lệ nghèo ở trẻ em.)"],"ukAudio":"/ai_services/tts3/?q=poverty&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=poverty&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F"},{"id":"lv_4_296","topic":"Cultural and Historical Exchange","word":"precise","pos":"(adj)","ipa":"/prɪˈsaɪs/","defVi":"chính xác, tỉ mỉ","defEn":"exact, accurate, and clear in every detail","examples":["The scientist recorded the [precise] measurements of the chemical solution. (=Dịch: Nhà khoa học đã ghi lại các phép đo chính xác của dung dịch hóa chất.)","Please give me [precise] instructions so that I do not make any mistakes. (=Dịch: Xin hãy cho tôi hướng dẫn chính xác để tôi không mắc phải bất kỳ sai sót nào.)","The satellite is capable of determining a vehicle's [precise] location. (=Dịch: Vệ tinh có khả năng xác định vị trí chính xác của một phương tiện.)"],"ukAudio":"/ai_services/tts3/?q=precise&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=precise&lang=en-US&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F"},{"id":"lv_4_297","topic":"Cultural and Historical Exchange","word":"prehistoric","pos":"(adj)","ipa":"/ˌpriː.hɪˈstɔːr.ɪk/","defVi":"tiền sử","defEn":"relating to the period of time before written records existed","examples":["Archaeologists found ancient tools in the [prehistoric] cave. (=Dịch: Các nhà khảo cổ học đã tìm thấy các công cụ cổ xưa trong hang động tiền sử.)","Dinosaurs are among the most famous [prehistoric] creatures. (=Dịch: Khủng long nằm trong số những sinh vật tiền sử nổi tiếng nhất.)","The museum exhibits several [prehistoric] rock paintings. (=Dịch: Bảo tàng trưng bày một số bức tranh đá thời tiền sử.)"],"ukAudio":"/ai_services/tts3/?q=prehistoric&lang=en-GB&ipa=%2F%CB%8Cpri%CB%90.h%C9%AA%CB%88st%C9%94%CB%90r.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=prehistoric&lang=en-US&ipa=%2F%CB%8Cpri%CB%90.h%C9%AA%CB%88st%C9%94%CB%90r.%C9%AAk%2F"},{"id":"lv_4_298","topic":"Cultural and Historical Exchange","word":"preparation","pos":"(n)","ipa":"/ˌprep.əˈreɪ.ʃən/","defVi":"sự chuẩn bị, công tác chuẩn bị","defEn":"the act or process of getting ready for something that will happen","examples":["Thorough [preparation] is essential for achieving a high score on the IELTS exam. (=Dịch: Sự chuẩn bị kỹ lưỡng là điều cần thiết để đạt điểm cao trong kỳ thi IELTS.)","They spent several months in [preparation] for the international conference. (=Dịch: Họ đã dành vài tháng để chuẩn bị cho hội nghị quốc tế.)","Careful food [preparation] helps prevent serious health risks. (=Dịch: Việc chuẩn bị thực phẩm cẩn thận giúp ngăn ngừa các rủi ro sức khỏe nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=preparation&lang=en-GB&ipa=%2F%CB%8Cprep.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=preparation&lang=en-US&ipa=%2F%CB%8Cprep.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_299","topic":"Cultural and Historical Exchange","word":"preserve","pos":"(v)","ipa":"/prɪˈzɜrv/","defVi":"bảo tồn, gìn giữ","defEn":"to keep something in its original state or in good condition","examples":["We must take urgent action to [preserve] historic architecture in the city center. (=Dịch: Chúng ta phải hành động khẩn cấp để bảo tồn kiến trúc lịch sử ở trung tâm thành phố.)","The government introduced strict laws to [preserve] endangered wildlife habitats. (=Dịch: Chính phủ đã ban hành các luật lệ nghiêm ngặt để bảo tồn môi trường sống của động vật hoang dã có nguy cơ tuyệt chủng.)","Traditional methods are still used to [preserve] fish during the winter months. (=Dịch: Các phương pháp truyền thống vẫn được sử dụng để bảo quản cá trong những tháng mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=preserve&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88z%C9%9Crv%2F","usAudio":"/ai_services/tts3/?q=preserve&lang=en-US&ipa=%2Fpr%C9%AA%CB%88z%C9%9Crv%2F"},{"id":"lv_4_300","topic":"Cultural and Historical Exchange","word":"priest","pos":"(n)","ipa":"/priːst/","defVi":"linh mục, thầy tế, giáo sĩ","defEn":"a person authorized to perform religious sacred rites, especially in Christian traditions","examples":["The parish [priest] delivered an inspiring sermon to the congregation. (=Dịch: Linh mục giáo xứ đã thuyết giảng một bài giảng đầy cảm hứng cho các giáo dân.)","The couple asked the local [priest] to bless their marriage. (=Dịch: Cặp đôi đã nhờ vị linh mục địa phương ban phước cho cuộc hôn nhân của họ.)","In ancient civilizations, a high [priest] held immense political power. (=Dịch: Trong các nền văn minh cổ đại, một vị thượng tế nắm giữ quyền lực chính trị to lớn.)"],"ukAudio":"/ai_services/tts3/?q=priest&lang=en-GB&ipa=%2Fpri%CB%90st%2F","usAudio":"/ai_services/tts3/?q=priest&lang=en-US&ipa=%2Fpri%CB%90st%2F"},{"id":"lv_4_301","topic":"Cultural and Historical Exchange","word":"primarily","pos":"(adv)","ipa":"/praɪˈmer.ə.li/","defVi":"chủ yếu, phần lớn","defEn":"mainly; for the most part","examples":["The charity organization focuses [primarily] on helping disadvantaged children. (=Dịch: Tổ chức từ thiện này chủ yếu tập trung vào việc giúp đỡ trẻ em có hoàn cảnh khó khăn.)","This course is designed [primarily] for beginners with no prior knowledge. (=Dịch: Khóa học này được thiết kế chủ yếu dành cho người mới bắt đầu chưa có kiến thức trước đó.)","The company's success is [primarily] due to its innovative products. (=Dịch: Thành công của công ty phần lớn nhờ vào các sản phẩm mang tính đổi mới sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=primarily&lang=en-GB&ipa=%2Fpra%C9%AA%CB%88mer.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=primarily&lang=en-US&ipa=%2Fpra%C9%AA%CB%88mer.%C9%99.li%2F"},{"id":"lv_4_302","topic":"Cultural and Historical Exchange","word":"prince","pos":"(n)","ipa":"/prɪns/","defVi":"hoàng tử","defEn":"a male member of a royal family, especially the son or grandson of a king or queen","examples":["The young [prince] was educated to prepare him for his future royal duties. (=Dịch: Vị hoàng tử trẻ đã được giáo dục để chuẩn bị cho những trọng trách hoàng gia trong tương lai.)","In the fairy tale, the [prince] searched the kingdom for the owner of the glass slipper. (=Dịch: Trong câu chuyện cổ tích, hoàng tử đã tìm kiếm khắp vương quốc chủ nhân của chiếc giày thủy tinh.)","The crown [prince] attended the international summit on behalf of the monarch. (=Dịch: Thái tử đã tham dự hội nghị thượng đỉnh quốc tế thay mặt cho quốc vương.)"],"ukAudio":"/ai_services/tts3/?q=prince&lang=en-GB&ipa=%2Fpr%C9%AAns%2F","usAudio":"/ai_services/tts3/?q=prince&lang=en-US&ipa=%2Fpr%C9%AAns%2F"},{"id":"lv_4_303","topic":"Cultural and Historical Exchange","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a fundamental truth, moral rule, or belief that guides behavior and decision-making","examples":["Refusing to accept bribes was a core [principle] that he upheld throughout his career. (=Dịch: Từ chối nhận hối lộ là nguyên tắc cốt lõi mà ông luôn giữ vững trong suốt sự nghiệp của mình.)","The machine operates on the same basic [principle] as an internal combustion engine. (=Dịch: Cỗ máy này hoạt động dựa trên cùng nguyên lý cơ bản như động cơ đốt trong.)","She made a decision based on [principle] rather than financial gain. (=Dịch: Cô ấy đã đưa ra quyết định dựa trên nguyên tắc đạo đức thay vì lợi ích tài chính.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_4_304","topic":"Cultural and Historical Exchange","word":"profession","pos":"(n)","ipa":"/prəˈfeʃ.ən/","defVi":"nghề nghiệp, chuyên môn","defEn":"a type of job that requires special training or a high level of education","examples":["Teaching is a challenging but very rewarding [profession]. (=Dịch: Dạy học là một nghề đầy thử thách nhưng rất đáng tự hào và ý nghĩa.)","He entered the legal [profession] after graduating from law school. (=Dịch: Anh ấy bước chân vào ngành luật sau khi tốt nghiệp trường luật.)","Members of the medical [profession] often work long and irregular hours. (=Dịch: Những người làm trong ngành y thường làm việc nhiều giờ và không cố định.)"],"ukAudio":"/ai_services/tts3/?q=profession&lang=en-GB&ipa=%2Fpr%C9%99%CB%88fe%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=profession&lang=en-US&ipa=%2Fpr%C9%99%CB%88fe%CA%83.%C9%99n%2F"},{"id":"lv_4_305","topic":"Cultural and Historical Exchange","word":"prominent","pos":"(adj)","ipa":"/ˈprɑː.mə.nənt/","defVi":"nổi bật, lỗi lạc, xuất chúng","defEn":"very well known, important, or easily noticed","examples":["He played a [prominent] role in negotiating the peace agreement. (=Dịch: Ông đã đóng một vai trò nổi bật trong việc đàm phán thỏa thuận hòa bình.)","The company hired a [prominent] scientist to lead the research. (=Dịch: Công ty đã thuê một nhà khoa học lỗi lạc để dẫn dắt công trình nghiên cứu.)","Her name was displayed in a [prominent] position on the poster. (=Dịch: Tên của cô được hiển thị ở một vị trí nổi bật trên tấm áp phích.)"],"ukAudio":"/ai_services/tts3/?q=prominent&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.m%C9%99.n%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=prominent&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.m%C9%99.n%C9%99nt%2F"},{"id":"lv_4_306","topic":"Cultural and Historical Exchange","word":"proud","pos":"(adj)","ipa":"/praʊd/","defVi":"tự hào, hãnh diện","defEn":"feeling deep pleasure or satisfaction as a result of one's own or someone else's achievements","examples":["Her parents were extremely [proud] of her academic achievements at university. (=Dịch: Cha mẹ cô vô cùng tự hào về những thành tích học tập của cô ở trường đại học.)","He felt [proud] to represent his country at the global environmental summit. (=Dịch: Anh cảm thấy tự hào khi được đại diện cho đất nước mình tại hội nghị thượng đỉnh về môi trường toàn cầu.)","The city is [proud] of its rich cultural history and diverse traditions. (=Dịch: Thành phố này tự hào về lịch sử văn hóa phong phú và các truyền thống đa dạng của mình.)"],"ukAudio":"/ai_services/tts3/?q=proud&lang=en-GB&ipa=%2Fpra%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=proud&lang=en-US&ipa=%2Fpra%CA%8Ad%2F"},{"id":"lv_4_307","topic":"Cultural and Historical Exchange","word":"publication","pos":"(n)","ipa":"/ˌpʌb.ləˈkeɪ.ʃən/","defVi":"ấn phẩm, sự xuất bản","defEn":"the act of making information, books, or magazines available to the public, or the printed item itself","examples":["Her latest [publication] discusses the long-term impact of climate change on agriculture. (=Dịch: Ấn phẩm mới nhất của bà thảo luận về tác động lâu dài của biến đổi khí hậu đối với nông nghiệp.)","The novel quickly became a bestseller within a month of its [publication]. (=Dịch: Cuốn tiểu thuyết đã nhanh chóng trở thành sách bán chạy nhất trong vòng một tháng kể từ ngày xuất bản.)","Academic journals often require peer review before approving an article for [publication]. (=Dịch: Các tạp chí học thuật thường yêu cầu phản biện đồng cấp trước khi phê duyệt bài viết để xuất bản.)"],"ukAudio":"/ai_services/tts3/?q=publication&lang=en-GB&ipa=%2F%CB%8Cp%CA%8Cb.l%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=publication&lang=en-US&ipa=%2F%CB%8Cp%CA%8Cb.l%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_308","topic":"Cultural and Historical Exchange","word":"publicise","pos":"(v)","ipa":"/ˈpʌb.ləˌsaɪz/","defVi":"quảng bá, công khai","defEn":"to make information about something generally known to the public","examples":["The university used social media to [publicise] the upcoming science fair. (=Dịch: Trường đại học đã sử dụng mạng xã hội để quảng bá cho hội chợ khoa học sắp tới.)","Authors often travel to different cities to [publicise] their new books. (=Dịch: Các tác giả thường đi đến các thành phố khác nhau để quảng bá cho cuốn sách mới của họ.)","The charity campaign was heavily [publicised] on local television. (=Dịch: Chiến dịch từ thiện đã được quảng bá rầm rộ trên truyền hình địa phương.)"],"ukAudio":"/ai_services/tts3/?q=publicise&lang=en-GB&ipa=%2F%CB%88p%CA%8Cb.l%C9%99%CB%8Csa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=publicise&lang=en-US&ipa=%2F%CB%88p%CA%8Cb.l%C9%99%CB%8Csa%C9%AAz%2F"},{"id":"lv_4_309","topic":"Cultural and Historical Exchange","word":"puppeteer","pos":"(n)","ipa":"/ˌpʌp.əˈtɪr/","defVi":"nghệ sĩ múa rối, người điều khiển con rối","defEn":"a person who operates puppets in theatrical performances or shows","examples":["The talented [puppeteer] used hidden strings to bring the wooden figures to life. (=Dịch: Nghệ sĩ múa rối tài ba đã dùng những sợi dây ẩn để thổi hồn vào các hình nhân bằng gỗ.)","After years of training, he became a master [puppeteer] at the traditional theater. (=Dịch: Sau nhiều năm rèn luyện, anh đã trở thành một nghệ nhân múa rối bậc thầy tại nhà hát truyền thống.)","Children watched in amazement as the [puppeteer] changed voices for different characters. (=Dịch: Bọn trẻ kinh ngạc dõi theo khi người điều khiển con rối thay đổi giọng nói cho các nhân vật khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=puppeteer&lang=en-GB&ipa=%2F%CB%8Cp%CA%8Cp.%C9%99%CB%88t%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=puppeteer&lang=en-US&ipa=%2F%CB%8Cp%CA%8Cp.%C9%99%CB%88t%C9%AAr%2F"},{"id":"lv_4_310","topic":"Cultural and Historical Exchange","word":"puppets","pos":"(n)","ipa":"/ˈpʌp.ɪts/","defVi":"những con rối","defEn":"models of people or animals manipulated by hands, rods, or strings to entertain an audience","examples":["The museum exhibits traditional shadow [puppets] collected from various Asian countries. (=Dịch: Bảo tàng trưng bày những con rối bóng truyền thống được sưu tầm từ nhiều quốc gia châu Á.)","Hand [puppets] are often used by teachers to make storytelling more engaging for children. (=Dịch: Rối tay thường được các giáo viên sử dụng để làm cho việc kể chuyện trở nên hấp dẫn hơn đối với trẻ em.)","Intricate wooden [puppets] performed an ancient folklore story on the stage. (=Dịch: Những con rối gỗ tinh xảo đã biểu diễn một câu chuyện dân gian cổ xưa trên sân khấu.)"],"ukAudio":"/ai_services/tts3/?q=puppets&lang=en-GB&ipa=%2F%CB%88p%CA%8Cp.%C9%AAts%2F","usAudio":"/ai_services/tts3/?q=puppets&lang=en-US&ipa=%2F%CB%88p%CA%8Cp.%C9%AAts%2F"},{"id":"lv_4_311","topic":"Cultural and Historical Exchange","word":"puzzle","pos":"(n)","ipa":"/ˈpʌz.əl/","defVi":"câu đố, trò chơi giải đố, điều bí ẩn","defEn":"a game, toy, or problem designed to test ingenuity or knowledge","examples":["Completing a crossword [puzzle] is a good way to improve your vocabulary. (=Dịch: Giải một câu đố ô chữ là một cách tốt để cải thiện vốn từ vựng của bạn.)","The disappearance of the ancient civilization remains an unsolved [puzzle]. (=Dịch: Sự biến mất của nền văn minh cổ đại vẫn là một bí ẩn chưa có lời giải.)","The children spent the rainy afternoon putting together a 500-piece jigsaw [puzzle]. (=Dịch: Lũ trẻ đã dành buổi chiều mưa để ghép một bức tranh xếp hình 500 mảnh.)"],"ukAudio":"/ai_services/tts3/?q=puzzle&lang=en-GB&ipa=%2F%CB%88p%CA%8Cz.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=puzzle&lang=en-US&ipa=%2F%CB%88p%CA%8Cz.%C9%99l%2F"},{"id":"lv_4_312","topic":"Cultural and Historical Exchange","word":"qualification","pos":"(n)","ipa":"/ˌkwɑː.lə.fəˈkeɪ.ʃən/","defVi":"bằng cấp, chứng chỉ, trình độ chuyên môn","defEn":"an official record showing that you have finished a training course or have the necessary skills","examples":["An academic [qualification] is essential for applying to this research position. (=Dịch: Bằng cấp học thuật là điều kiện thiết yếu để ứng tuyển vào vị trí nghiên cứu này.)","She gained a teaching [qualification] after two years of study. (=Dịch: Cô ấy đã đạt được chứng chỉ giảng dạy sau hai năm học tập.)","Practical experience is often valued just as much as a formal [qualification]. (=Dịch: Kinh nghiệm thực tế thường được coi trọng không kém gì một bằng cấp chính quy.)"],"ukAudio":"/ai_services/tts3/?q=qualification&lang=en-GB&ipa=%2F%CB%8Ckw%C9%91%CB%90.l%C9%99.f%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=qualification&lang=en-US&ipa=%2F%CB%8Ckw%C9%91%CB%90.l%C9%99.f%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_313","topic":"Cultural and Historical Exchange","word":"quarry","pos":"(n)","ipa":"/ˈkwɔːr.i/","defVi":"mỏ đá, nơi khai thác đá","defEn":"a large deep pit from which stone, slate, or other materials are extracted","examples":["The granite used to build the cathedral was sourced from a local [quarry]. (=Dịch: Đá granit dùng để xây dựng nhà thờ chính tòa được lấy từ một mỏ đá địa phương.)","Heavy machinery operated continuously at the limestone [quarry]. (=Dịch: Máy móc hạng nặng hoạt động liên tục tại mỏ đá vôi.)","The abandoned marble [quarry] has now turned into a deep lake. (=Dịch: Mỏ đá cẩm thạch bị bỏ hoang giờ đã biến thành một cái hồ sâu.)"],"ukAudio":"/ai_services/tts3/?q=quarry&lang=en-GB&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=quarry&lang=en-US&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F"},{"id":"lv_4_314","topic":"Cultural and Historical Exchange","word":"rabbit","pos":"(n)","ipa":"/ˈræb.ɪt/","defVi":"con thỏ","defEn":"a small burrowing mammal with long ears, long hind legs, and a short fluffy tail","examples":["A wild [rabbit] darted across the open meadow into the safety of the bushes. (=Dịch: Một con thỏ rừng phóng vụt qua đồng cỏ rộng mở vào nơi an toàn trong bụi rậm.)","She keeps a pet [rabbit] in a spacious cage in her backyard. (=Dịch: Cô ấy nuôi một con thỏ cưng trong chiếc lồng rộng rãi ở sân sau.)","The farmer built a sturdy fence to protect his vegetable garden from [rabbit] damage. (=Dịch: Người nông dân đã dựng một hàng rào chắc chắn để bảo vệ vườn rau của mình khỏi sự phá hoại của thỏ.)"],"ukAudio":"/ai_services/tts3/?q=rabbit&lang=en-GB&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rabbit&lang=en-US&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F"},{"id":"lv_4_315","topic":"Cultural and Historical Exchange","word":"raft","pos":"(n)","ipa":"/ræft/","defVi":"chiếc bè, phao bè","defEn":"a flat floating structure used for transportation on water","examples":["They built a wooden [raft] to cross the river. (=Dịch: Họ đã đóng một chiếc bè gỗ để qua sông.)","The survivors drifted on a life [raft] for several days. (=Dịch: Những người sống sót đã trôi dạt trên một chiếc bè cứu sinh suốt vài ngày.)","We went on an exciting [raft] trip down the rapids. (=Dịch: Chúng tôi đã có một chuyến đi bè vượt ghềnh thác đầy hào hứng.)"],"ukAudio":"/ai_services/tts3/?q=raft&lang=en-GB&ipa=%2Fr%C3%A6ft%2F","usAudio":"/ai_services/tts3/?q=raft&lang=en-US&ipa=%2Fr%C3%A6ft%2F"},{"id":"lv_4_316","topic":"Cultural and Historical Exchange","word":"rainbow","pos":"(n)","ipa":"/ˈreɪn.boʊ/","defVi":"cầu vồng","defEn":"a curved band of different colors that appears in the sky when the sun shines through rain","examples":["A beautiful [rainbow] appeared across the sky after the storm passed. (=Dịch: Một chiếc cầu vồng tuyệt đẹp xuất hiện trên bầu trời sau khi cơn bão đi qua.)","She wore a bright dress with all the colors of the [rainbow]. (=Dịch: Cô ấy mặc một chiếc váy rực rỡ với đủ mọi sắc màu của cầu vồng.)","Sunlight refracted through the prism created an artificial [rainbow] on the wall. (=Dịch: Ánh nắng mặt trời khúc xạ qua lăng kính đã tạo nên một chiếc cầu vồng nhân tạo trên tường.)"],"ukAudio":"/ai_services/tts3/?q=rainbow&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=rainbow&lang=en-US&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F"},{"id":"lv_4_317","topic":"Cultural and Historical Exchange","word":"rationale","pos":"(n)","ipa":"/ˌræʃ.əˈnæl/","defVi":"lý do căn bản, cơ sở lý luận","defEn":"the underlying reasons or explanation for a particular action, belief, or decision","examples":["The director explained the economic [rationale] behind the company restructuring. (=Dịch: Giám đốc đã giải thích cơ sở lý luận kinh tế đằng sau việc tái cơ cấu công ty.)","What is the [rationale] for changing the school curriculum this year? (=Dịch: Lý do căn bản cho việc thay đổi chương trình giảng dạy của trường trong năm nay là gì?)","Students must provide a clear [rationale] for their choice of dissertation topic. (=Dịch: Sinh viên phải đưa ra lý do xác đáng cho sự lựa chọn đề tài luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=rationale&lang=en-GB&ipa=%2F%CB%8Cr%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=rationale&lang=en-US&ipa=%2F%CB%8Cr%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_4_318","topic":"Cultural and Historical Exchange","word":"readily","pos":"(adv)","ipa":"/ˈrɛd.əl.i/","defVi":"sẵn sàng, dễ dàng","defEn":"willingly, quickly, or without difficulty","examples":["Fresh drinking water is [readily] available in all hotel rooms. (=Dịch: Nước uống sạch luôn có sẵn trong tất cả các phòng khách sạn.)","She [readily] agreed to help organize the charity event. (=Dịch: Cô ấy đã sẵn lòng đồng ý giúp tổ chức sự kiện từ thiện.)","The software is [readily] adaptable to different business needs. (=Dịch: Phần mềm này dễ dàng thích ứng với các nhu cầu kinh doanh khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=readily&lang=en-GB&ipa=%2F%CB%88r%C9%9Bd.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=readily&lang=en-US&ipa=%2F%CB%88r%C9%9Bd.%C9%99l.i%2F"},{"id":"lv_4_319","topic":"Cultural and Historical Exchange","word":"rectangular","pos":"(adj)","ipa":"/rɛkˈtæŋ.ɡjə.lɚ/","defVi":"có hình chữ nhật","defEn":"having the shape of a rectangle with four straight sides and four right angles","examples":["The dining room features a large [rectangular] wooden table. (=Dịch: Phòng ăn có một chiếc bàn gỗ lớn hình chữ nhật.)","They placed a [rectangular] rug in the center of the living room. (=Dịch: Họ đã đặt một tấm thảm hình chữ nhật ở giữa phòng khách.)","The swimming pool is [rectangular] and measures twenty-five meters in length. (=Dịch: Hồ bơi có hình chữ nhật và có chiều dài hai mươi lăm mét.)"],"ukAudio":"/ai_services/tts3/?q=rectangular&lang=en-GB&ipa=%2Fr%C9%9Bk%CB%88t%C3%A6%C5%8B.%C9%A1j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rectangular&lang=en-US&ipa=%2Fr%C9%9Bk%CB%88t%C3%A6%C5%8B.%C9%A1j%C9%99.l%C9%9A%2F"},{"id":"lv_4_320","topic":"Cultural and Historical Exchange","word":"reed","pos":"(n)","ipa":"/riːd/","defVi":"cây sậy","defEn":"a tall, slender plant with hollow stems that grows in wet ground or near water","examples":["Frogs hid among the tall [reed] plants along the edge of the pond. (=Dịch: Những con ếch ẩn nấp giữa các bụi cây sậy cao dọc theo bờ ao.)","Traditional weavers used dried [reed] fibers to make durable baskets. (=Dịch: Những người thợ dệt truyền thống đã sử dụng sợi sậy khô để làm ra những chiếc giỏ bền chắc.)","The wind made a soft whistling sound as it blew through the [reed] bed. (=Dịch: Gió tạo ra âm thanh vi vu êm dịu khi thổi qua rặng sậy.)"],"ukAudio":"/ai_services/tts3/?q=reed&lang=en-GB&ipa=%2Fri%CB%90d%2F","usAudio":"/ai_services/tts3/?q=reed&lang=en-US&ipa=%2Fri%CB%90d%2F"},{"id":"lv_4_321","topic":"Cultural and Historical Exchange","word":"reel","pos":"(n)","ipa":"/ril/","defVi":"cuộn, ống cuộn, guồng quay","defEn":"a round object around which wire, thread, or film is wound","examples":["He attached a new line to the fishing [reel] before heading to the lake. (=Dịch: Anh ấy đã gắn một sợi dây cước mới vào cuộn dây câu trước khi đi ra hồ.)","The museum preserved an old [reel] of film showing city life in the 1920s. (=Dịch: Bảo tàng đã lưu giữ một cuộn phim cũ ghi lại cuộc sống thành thị vào những năm 1920.)","She wound the remaining yarn neatly back onto the [reel]. (=Dịch: Cô ấy đã quấn gọn gàng phần len còn lại trở lại vào ống cuộn.)"],"ukAudio":"/ai_services/tts3/?q=reel&lang=en-GB&ipa=%2Fril%2F","usAudio":"/ai_services/tts3/?q=reel&lang=en-US&ipa=%2Fril%2F"},{"id":"lv_4_322","topic":"Cultural and Historical Exchange","word":"relative","pos":"(n)","ipa":"/ˈrel.ə.t̬ɪv/","defVi":"người thân, họ hàng","defEn":"a person who is related to another by blood or marriage","examples":["She traveled across the country to visit an elderly [relative] in the hospital. (=Dịch: Cô ấy đã đi dọc khắp đất nước để đến thăm một người họ hàng lớn tuổi đang nằm viện.)","The holiday season is a great time to gather and celebrate with every close [relative]. (=Dịch: Mùa lễ hội là khoảng thời gian tuyệt vời để sum họp và ăn mừng cùng tất cả những người họ hàng thân thiết.)","He found an old photograph of a distant [relative] who served in the war. (=Dịch: Anh ấy tìm thấy một bức ảnh cũ của một người họ hàng xa từng phục vụ trong quân ngũ thời chiến.)"],"ukAudio":"/ai_services/tts3/?q=relative&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=relative&lang=en-US&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_4_323","topic":"Cultural and Historical Exchange","word":"remoteness","pos":"(n)","ipa":"/rɪˈmoʊt.nəs/","defVi":"sự xa xôi, hẻo lánh","defEn":"the state of being far away in distance or isolated from other places and people","examples":["The [remoteness] of the mountain village made it difficult to access basic healthcare. (=Dịch: Sự hẻo lánh của ngôi làng miền núi khiến việc tiếp cận dịch vụ chăm sóc sức khỏe cơ bản trở nên khó khăn.)","He enjoyed the [remoteness] of the cabin because it offered complete peace and quiet. (=Dịch: Anh ấy thích sự biệt lập của căn cabin vì nó mang lại sự yên tĩnh và thanh bình tuyệt đối.)","Due to the island's [remoteness], supplies are delivered only once a month. (=Dịch: Do sự xa xôi hẻo lánh của hòn đảo, nhu yếu phẩm chỉ được giao mỗi tháng một lần.)"],"ukAudio":"/ai_services/tts3/?q=remoteness&lang=en-GB&ipa=%2Fr%C9%AA%CB%88mo%CA%8At.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=remoteness&lang=en-US&ipa=%2Fr%C9%AA%CB%88mo%CA%8At.n%C9%99s%2F"},{"id":"lv_4_324","topic":"Cultural and Historical Exchange","word":"resemble","pos":"(v)","ipa":"/rɪˈzɛm.bəl/","defVi":"giống, tương tự","defEn":"to look like or be similar to someone or something else","examples":["She [resembles] her mother in both appearance and character. (=Dịch: Cô ấy giống mẹ cả về ngoại hình lẫn tính cách.)","The modern building does not [resemble] the traditional architecture around it. (=Dịch: Tòa nhà hiện đại không hề giống với kiến trúc truyền thống xung quanh nó.)","Some extinct reptiles closely [resemble] modern birds. (=Dịch: Một số loài bò sát đã tuyệt chủng có nét rất giống với các loài chim hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=resemble&lang=en-GB&ipa=%2Fr%C9%AA%CB%88z%C9%9Bm.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=resemble&lang=en-US&ipa=%2Fr%C9%AA%CB%88z%C9%9Bm.b%C9%99l%2F"},{"id":"lv_4_325","topic":"Cultural and Historical Exchange","word":"restore","pos":"(v)","ipa":"/rɪˈstɔr/","defVi":"phục hồi, khôi phục, trùng tu","defEn":"to return something to its earlier good condition, or to bring something back","examples":["The museum hired experts to [restore] the damaged antique painting. (=Dịch: Bảo tàng đã thuê các chuyên gia để phục chế bức tranh cổ bị hư hại.)","The government aims to [restore] public trust through open communication. (=Dịch: Chính phủ đặt mục tiêu khôi phục niềm tin của công chúng thông qua giao tiếp cởi mở.)","Engineers worked overnight to [restore] electricity to the city. (=Dịch: Các kỹ sư đã làm việc thấu đêm để khôi phục nguồn điện cho thành phố.)"],"ukAudio":"/ai_services/tts3/?q=restore&lang=en-GB&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F","usAudio":"/ai_services/tts3/?q=restore&lang=en-US&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F"},{"id":"lv_4_326","topic":"Cultural and Historical Exchange","word":"retailing","pos":"(n)","ipa":"/ˈriː.teɪ.lɪŋ/","defVi":"ngành bán lẻ, hoạt động bán lẻ","defEn":"the business of selling goods directly to the public in stores or online","examples":["The rise of e-commerce has dramatically transformed the world of [retailing]. (=Dịch: Sự trỗi dậy của thương mại điện tử đã biến đổi sâu sắc thế giới bán lẻ.)","She gained valuable experience in [retailing] after managing a clothing boutique for three years. (=Dịch: Cô ấy đã tích lũy được kinh nghiệm quý báu trong ngành bán lẻ sau khi quản lý một cửa hàng thời trang trong ba năm.)","Technological innovations in [retailing] allow customers to pay without waiting in line. (=Dịch: Những đổi mới công nghệ trong ngành bán lẻ cho phép khách hàng thanh toán mà không cần phải xếp hàng chờ đợi.)"],"ukAudio":"/ai_services/tts3/?q=retailing&lang=en-GB&ipa=%2F%CB%88ri%CB%90.te%C9%AA.l%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=retailing&lang=en-US&ipa=%2F%CB%88ri%CB%90.te%C9%AA.l%C9%AA%C5%8B%2F"},{"id":"lv_4_327","topic":"Cultural and Historical Exchange","word":"retire","pos":"(v)","ipa":"/rɪˈtaɪər/","defVi":"nghỉ hưu, về hưu","defEn":"to leave one's job and stop working, usually because of having reached a particular age","examples":["He plans to [retire] next year after forty years of teaching. (=Dịch: Ông dự định sẽ nghỉ hưu vào năm tới sau 40 năm giảng dạy.)","Many workers worry that they will not have enough savings when they [retire]. (=Dịch: Nhiều người lao động lo lắng rằng họ sẽ không có đủ tiền tiết kiệm khi về hưu.)","She chose to [retire] early to spend more time traveling with her family. (=Dịch: Bà đã chọn nghỉ hưu sớm để dành nhiều thời gian hơn đi du lịch cùng gia đình.)"],"ukAudio":"/ai_services/tts3/?q=retire&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA%C9%99r%2F","usAudio":"/ai_services/tts3/?q=retire&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA%C9%99r%2F"},{"id":"lv_4_328","topic":"Cultural and Historical Exchange","word":"revival","pos":"(n)","ipa":"/rɪˈvaɪ.vəl/","defVi":"sự hồi sinh, sự phục hưng","defEn":"an improvement in the condition, strength, or popularity of something","examples":["The city has experienced a cultural [revival] with the opening of several art galleries. (=Dịch: Thành phố đã trải qua sự hồi sinh văn hóa với việc mở cửa một vài phòng trưng bày nghệ thuật.)","Traditional handicrafts are enjoying a remarkable [revival] among young people. (=Dịch: Các nghề thủ công truyền thống đang đón nhận sự hồi sinh đáng kể trong giới trẻ.)","Economic reforms led to the [revival] of the local tourism industry. (=Dịch: Những cải cách kinh tế đã dẫn đến sự phục hồi của ngành du lịch địa phương.)"],"ukAudio":"/ai_services/tts3/?q=revival&lang=en-GB&ipa=%2Fr%C9%AA%CB%88va%C9%AA.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=revival&lang=en-US&ipa=%2Fr%C9%AA%CB%88va%C9%AA.v%C9%99l%2F"},{"id":"lv_4_329","topic":"Cultural and Historical Exchange","word":"revolution","pos":"(n)","ipa":"/ˌrev.əˈluː.ʃən/","defVi":"cuộc cách mạng, sự thay đổi bước ngoặt","defEn":"a forcible overthrow of a government or a major, sudden change in ideas or methods","examples":["The industrial [revolution] transformed manufacturing and everyday life. (=Dịch: Cuộc cách mạng công nghiệp đã làm thay đổi nền sản xuất và đời sống hàng ngày.)","The digital [revolution] has changed the way people communicate globally. (=Dịch: Cuộc cách mạng kỹ thuật số đã thay đổi cách mọi người giao tiếp trên toàn cầu.)","The country underwent a political [revolution] that ended decades of authoritarian rule. (=Dịch: Đất nước đã trải qua một cuộc cách mạng chính trị chấm dứt nhiều thập kỷ cai trị độc tài.)"],"ukAudio":"/ai_services/tts3/?q=revolution&lang=en-GB&ipa=%2F%CB%8Crev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=revolution&lang=en-US&ipa=%2F%CB%8Crev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_330","topic":"Cultural and Historical Exchange","word":"rewarding","pos":"(adj)","ipa":"/rɪˈwɔːr.dɪŋ/","defVi":"bổ ích, đáng giá, đem lại cảm giác thỏa mãn","defEn":"providing satisfaction, pleasure, or a feeling of worth","examples":["Teaching underprivileged children is a challenging but deeply [rewarding] job. (=Dịch: Dạy học cho trẻ em có hoàn cảnh khó khăn là một công việc đầy thử thách nhưng mang lại nhiều ý nghĩa sâu sắc.)","Volunteering at the animal shelter proved to be a [rewarding] experience for him. (=Dịch: Tham gia tình nguyện tại trạm cứu hộ động vật hóa ra lại là một trải nghiệm rất bổ ích đối với anh ấy.)","She found it [rewarding] to see her project come to life. (=Dịch: Cô cảm thấy thật xứng đáng khi được nhìn thấy dự án của mình đi vào đời thực.)"],"ukAudio":"/ai_services/tts3/?q=rewarding&lang=en-GB&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90r.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=rewarding&lang=en-US&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90r.d%C9%AA%C5%8B%2F"},{"id":"lv_4_331","topic":"Cultural and Historical Exchange","word":"rival","pos":"(n)","ipa":"/ˈraɪ.vəl/","defVi":"đối thủ, đối thủ cạnh tranh","defEn":"a person, team, or organization competing with another for the same objective","examples":["The two companies have been fierce [rival]s in the smartphone market for years. (=Dịch: Hai công ty này đã là những đối thủ khốc liệt trên thị trường điện thoại thông minh trong nhiều năm.)","He defeated his main [rival] in the final round of the tennis tournament. (=Dịch: Anh ấy đã đánh bại đối thủ chính của mình trong trận chung kết của giải đấu quần vợt.)","The new restaurant quickly became a serious [rival] to existing local diners. (=Dịch: Nhà hàng mới nhanh chóng trở thành một đối thủ đáng gờm đối với các quán ăn địa phương hiện có.)"],"ukAudio":"/ai_services/tts3/?q=rival&lang=en-GB&ipa=%2F%CB%88ra%C9%AA.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rival&lang=en-US&ipa=%2F%CB%88ra%C9%AA.v%C9%99l%2F"},{"id":"lv_4_332","topic":"Cultural and Historical Exchange","word":"rocket","pos":"(n)","ipa":"/ˈrɑː.kɪt/","defVi":"tên lửa, phi thuyền","defEn":"a vehicle or device propelled into space or through the air by the thrust of burning gases","examples":["The space agency launched a powerful [rocket] into orbit yesterday morning. (=Dịch: Cơ quan vũ trụ đã phóng một tên lửa mạnh mẽ vào quỹ đạo sáng hôm qua.)","Engineers are designing a reusable [rocket] to reduce the cost of space exploration. (=Dịch: Các kỹ sư đang thiết kế một tên lửa có thể tái sử dụng để giảm chi phí thám hiểm không gian.)","The [rocket] carried communication satellites into outer space. (=Dịch: Tên lửa đã mang các vệ tinh liên lạc vào không gian vũ trụ.)"],"ukAudio":"/ai_services/tts3/?q=rocket&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rocket&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.k%C9%AAt%2F"},{"id":"lv_4_333","topic":"Cultural and Historical Exchange","word":"roman","pos":"(n)","ipa":"/ˈroʊ.mən/","defVi":"người La Mã (hoặc người thành Roma)","defEn":"a person born or living in ancient Rome or modern Rome","examples":["The ancient [Romans] built extensive networks of roads and aqueducts across Europe. (=Dịch: Người La Mã cổ đại đã xây dựng mạng lưới đường sá và cầu dẫn nước rộng khắp châu Âu.)","She is studying the daily life and laws of the [Romans] in her history class. (=Dịch: Cô ấy đang nghiên cứu về đời sống hàng ngày và luật pháp của người La Mã trong lớp học lịch sử.)","Many modern legal systems were heavily influenced by the early [Romans]. (=Dịch: Nhiều hệ thống pháp luật hiện đại chịu ảnh hưởng sâu sắc từ người La Mã thời kỳ đầu.)"],"ukAudio":"/ai_services/tts3/?q=roman&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=roman&lang=en-US&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F"},{"id":"lv_4_334","topic":"Cultural and Historical Exchange","word":"romantic","pos":"(adj)","ipa":"/roʊˈmæn.tɪk/","defVi":"lãng mạn, nên thơ","defEn":"relating to love, passion, or an idealized view of life","examples":["They had a [romantic] dinner at an elegant restaurant by the river. (=Dịch: Họ đã có một bữa tối lãng mạn tại một nhà hàng thanh lịch bên bờ sông.)","He often writes [romantic] poetry to express his deep feelings. (=Dịch: Anh ấy thường làm thơ lãng mạn để bày tỏ những cảm xúc sâu sắc của mình.)","She had a [romantic] notion of what living on a farm would be like. (=Dịch: Cô ấy từng có một suy nghĩ lãng mạn về cuộc sống ở một trang trại.)"],"ukAudio":"/ai_services/tts3/?q=romantic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=romantic&lang=en-US&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_4_335","topic":"Cultural and Historical Exchange","word":"rome","pos":"(n)","ipa":"/roʊm/","defVi":"thành phố Rome (thủ đô nước Ý)","defEn":"the capital city of Italy, famous for its ancient history and architecture","examples":["Millions of tourists travel to [Rome] every year to see the Colosseum. (=Dịch: Hàng triệu du khách đến Rome mỗi năm để chiêm ngưỡng đấu trường La Mã Colosseum.)","She studied art history for a semester in [Rome]. (=Dịch: Cô ấy đã học lịch sử nghệ thuật trong một học kỳ tại Rome.)","There is an old proverb saying that all roads lead to [Rome]. (=Dịch: Có một câu tục ngữ cổ nói rằng mọi con đường đều dẫn đến thành Rome.)"],"ukAudio":"/ai_services/tts3/?q=rome&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=rome&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_4_336","topic":"Cultural and Historical Exchange","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, thô ráp; dữ dội, gian nan","defEn":"not smooth, even, or gentle","examples":["The wooden table had a [rough] surface that needed sanding. (=Dịch: Chiếc bàn gỗ có bề mặt thô ráp cần phải được chà nhám.)","The ferry ride was delayed because the sea was extremely [rough]. (=Dịch: Chuyến phà bị hoãn vì biển động dữ dội.)","He wrote a [rough] draft of the essay before submitting the final version. (=Dịch: Anh ấy đã viết một bản thảo sơ bộ của bài luận trước khi nộp bản chính thức.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_4_337","topic":"Cultural and Historical Exchange","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a line of people, animals, or things arranged side by side","examples":["We had great seats in the front [row] of the cinema. (=Dịch: Chúng tôi đã có những chỗ ngồi tuyệt vời ở hàng ghế đầu của rạp chiếu phim.)","A [row] of blooming rose bushes stood along the fence. (=Dịch: Một hàng bụi hoa hồng đang nở rộ nằm dọc theo hàng rào.)","The teacher asked the children to stand in a straight [row]. (=Dịch: Giáo viên yêu cầu lũ trẻ đứng thành một hàng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_4_338","topic":"Cultural and Historical Exchange","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"thuộc hoàng gia, hoàng tộc","defEn":"connected with or belonging to a king or queen","examples":["The [royal] family attended the annual charity ceremony. (=Dịch: Hoàng gia đã tham dự buổi lễ từ thiện thường niên.)","Thousands of visitors come to tour the [royal] palace every year. (=Dịch: Hàng nghìn du khách đến tham quan cung điện hoàng gia mỗi năm.)","She received a [royal] invitation to the banquet in London. (=Dịch: Cô đã nhận được một lời mời từ hoàng gia đến dự buổi yến tiệc ở Luân Đôn.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_4_339","topic":"Cultural and Historical Exchange","word":"ruler","pos":"(n)","ipa":"/ˈruː.lɚ/","defVi":"người cai trị, bậc quân vương","defEn":"a person who holds supreme power and governs a country or empire","examples":["The wise [ruler] instituted legal reforms that benefited both merchants and peasants. (=Dịch: Nhà cai trị anh minh đã ban hành các cải cách pháp lý mang lại lợi ích cho cả thương nhân lẫn nông dân.)","Many historical monuments were erected to celebrate the victories of the ancient [ruler]. (=Dịch: Nhiều di tích lịch sử đã được dựng lên để tôn vinh những chiến thắng của vị quân vương cổ đại.)","Public discontent grew after the tyrannical [ruler] imposed exorbitant new taxes. (=Dịch: Sự bất mãn trong dân chúng ngày càng gia tăng sau khi kẻ cai trị bạo ngược áp đặt những mức thuế mới cắt cổ.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F"},{"id":"lv_4_340","topic":"Cultural and Historical Exchange","word":"russia","pos":"(n)","ipa":"/ˈrʌʃ.ə/","defVi":"nước Nga","defEn":"the largest country in the world, spanning Eastern Europe and Northern Asia","examples":["Winter temperatures in [Russia] can drop well below freezing. (=Dịch: Nhiệt độ mùa đông ở Nga có thể giảm xuống dưới mức đóng băng rất nhiều.)","He is planning a journey across [Russia] on the Trans-Siberian Railway. (=Dịch: Anh ấy đang lên kế hoạch cho một chuyến hành trình xuyên nước Nga trên tuyến Đường sắt xuyên Sibir.)","Natural gas and oil are major export products of [Russia]. (=Dịch: Khí tự nhiên và dầu mỏ là các mặt hàng xuất khẩu chính của Nga.)"],"ukAudio":"/ai_services/tts3/?q=russia&lang=en-GB&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F","usAudio":"/ai_services/tts3/?q=russia&lang=en-US&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F"},{"id":"lv_4_341","topic":"Cultural and Historical Exchange","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ, những người đi biển","defEn":"people who work as members of the crew of a ship or boat","examples":["The experienced [sailors] secured the ship's cargo before the severe storm hit. (=Dịch: Những thủy thủ giàu kinh nghiệm đã chằng buộc hàng hóa của con tàu cẩn thận trước khi cơn bão dữ dội ập đến.)","Ancient [sailors] relied heavily on the stars and ocean currents to navigate long voyages. (=Dịch: Các thủy thủ thời cổ đại dựa rất nhiều vào các vì sao và hải lưu để định hướng cho những hải trình dài.)","After months at sea, the weary [sailors] rejoiced at the sight of the coastline. (=Dịch: Sau nhiều tháng lênh đênh trên biển, những người thủy thủ mệt mỏi đã vui mừng khôn xiết khi nhìn thấy đường bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_4_342","topic":"Cultural and Historical Exchange","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a loose granular substance formed from eroded rocks, commonly found on beaches and deserts","examples":["We walked barefoot on the warm [sand] along the shore. (=Dịch: Chúng tôi đi chân trần trên bãi cát ấm dọc bờ biển.)","Strong winds blew the fine [sand] into our eyes and faces. (=Dịch: Gió mạnh thổi cát mịn vào mắt và mặt chúng tôi.)","The children built a large castle out of wet [sand]. (=Dịch: Những đứa trẻ đã xây một lâu đài lớn bằng cát ướt.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_4_343","topic":"Cultural and Historical Exchange","word":"scholar","pos":"(n)","ipa":"/ˈskɑ.lɚ/","defVi":"học giả, nhà nghiên cứu","defEn":"a person who is highly educated and has studied a subject in depth","examples":["She is a respected [scholar] in the field of ancient history. (=Dịch: Bà là một học giả được kính trọng trong lĩnh vực lịch sử cổ đại.)","The university invited a visiting [scholar] to give a lecture series. (=Dịch: Trường đại học đã mời một học giả thỉnh giảng đến thuyết giảng một chuỗi bài giảng.)","Many [scholars] have debated the true meaning of the manuscript. (=Dịch: Nhiều học giả đã tranh luận về ý nghĩa thực sự của bản thảo này.)"],"ukAudio":"/ai_services/tts3/?q=scholar&lang=en-GB&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=scholar&lang=en-US&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F"},{"id":"lv_4_344","topic":"Cultural and Historical Exchange","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"thuộc về khoa học, có tính khoa học","defEn":"relating to science or using the methods of science","examples":["There is no [scientific] evidence to support this claim. (=Dịch: Không có bằng chứng khoa học nào để chứng minh cho lời khẳng định này.)","The team published their findings in a prestigious [scientific] journal. (=Dịch: Nhóm đã công bố các phát hiện của họ trên một tạp chí khoa học uy tín.)","We must adopt a strictly [scientific] approach to solve this problem. (=Dịch: Chúng ta phải áp dụng một phương pháp tiếp cận hoàn toàn khoa học để giải quyết vấn đề này.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_4_345","topic":"Cultural and Historical Exchange","word":"script","pos":"(n)","ipa":"/skrɪpt/","defVi":"kịch bản","defEn":"the written text of a play, film, or broadcast","examples":["The actors spent several weeks memorizing their lines from the [script]. (=Dịch: Các diễn viên đã dành vài tuần để học thuộc lời thoại từ kịch bản.)","The director decided to make a few changes to the original [script]. (=Dịch: Đạo diễn đã quyết định thực hiện một vài thay đổi đối với kịch bản gốc.)","She wrote an impressive [script] for her first short film. (=Dịch: Cô ấy đã viết một kịch bản ấn tượng cho bộ phim ngắn đầu tay của mình.)"],"ukAudio":"/ai_services/tts3/?q=script&lang=en-GB&ipa=%2Fskr%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=script&lang=en-US&ipa=%2Fskr%C9%AApt%2F"},{"id":"lv_4_346","topic":"Cultural and Historical Exchange","word":"seek","pos":"(v)","ipa":"/siːk/","defVi":"tìm kiếm, mưu cầu","defEn":"to attempt to find, obtain, or achieve something","examples":["Many young graduates move abroad to [seek] better career opportunities. (=Dịch: Nhiều sinh viên mới tốt nghiệp ra nước ngoài để tìm kiếm những cơ hội nghề nghiệp tốt hơn.)","Patients are advised to [seek] medical advice as soon as symptoms appear. (=Dịch: Bệnh nhân được khuyên nên tìm kiếm lời khuyên y tế ngay khi các triệu chứng xuất hiện.)","Scientists continue to [seek] sustainable alternatives to fossil fuels. (=Dịch: Các nhà khoa học tiếp tục tìm kiếm những giải pháp thay thế bền vững cho nhiên liệu hóa thạch.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsi%CB%90k%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsi%CB%90k%2F"},{"id":"lv_4_347","topic":"Cultural and Historical Exchange","word":"seminar","pos":"(n)","ipa":"/ˈsɛm.ə.nɑr/","defVi":"hội thảo, buổi chuyên đề","defEn":"a meeting or class for discussion or training on a particular topic","examples":["I attended a useful [seminar] on digital marketing strategies yesterday. (=Dịch: Hôm qua tôi đã tham dự một buổi hội thảo hữu ích về các chiến lược tiếp thị kỹ thuật số.)","Students are required to participate actively during each weekly [seminar]. (=Dịch: Sinh viên được yêu cầu tham gia tích cực trong mỗi buổi hội thảo chuyên đề hàng tuần.)","The company organized a safety [seminar] for all its new employees. (=Dịch: Công ty đã tổ chức một buổi hội thảo về an toàn cho tất cả nhân viên mới.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88s%C9%9Bm.%C9%99.n%C9%91r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88s%C9%9Bm.%C9%99.n%C9%91r%2F"},{"id":"lv_4_348","topic":"Cultural and Historical Exchange","word":"serpent","pos":"(n)","ipa":"/ˈsɝ.pənt/","defVi":"con rắn (thường dùng trong văn học hoặc thần thoại)","defEn":"a snake, especially a large or dangerous one, often used in literary or mythological contexts","examples":["In ancient myths, the [serpent] is often a symbol of wisdom and deception. (=Dịch: Trong các câu chuyện thần thoại cổ xưa, loài rắn thường là biểu tượng của sự khôn ngoan và lừa dối.)","A giant sea [serpent] was said to guard the entrance to the underwater cave. (=Dịch: Một con rắn biển khổng lồ được cho là đã canh giữ lối vào của hang động dưới nước.)","The warrior skillfully defended himself against the venomous [serpent]. (=Dịch: Người chiến binh đã khéo léo tự vệ trước con mãng xà có độc.)"],"ukAudio":"/ai_services/tts3/?q=serpent&lang=en-GB&ipa=%2F%CB%88s%C9%9D.p%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=serpent&lang=en-US&ipa=%2F%CB%88s%C9%9D.p%C9%99nt%2F"},{"id":"lv_4_349","topic":"Cultural and Historical Exchange","word":"setback","pos":"(n)","ipa":"/ˈset.bæk/","defVi":"sự trở ngại, bước lùi, khó khăn bất ngờ","defEn":"a problem or difficulty that delays progress or stops a plan from succeeding","examples":["The unexpected supply chain disruption was a major [setback] for the construction project. (=Dịch: Sự gián đoạn chuỗi cung ứng bất ngờ là một trở ngại lớn đối với dự án xây dựng.)","Despite an initial [setback], the research team managed to finish the report on time. (=Dịch: Bất chấp trở ngại ban đầu, nhóm nghiên cứu đã xoay xở hoàn thành báo cáo đúng hạn.)","A shoulder injury proved to be a serious [setback] to her athletic career. (=Dịch: Một chấn thương vai đã trở thành bước thụt lùi nghiêm trọng đối với sự nghiệp thể thao của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=setback&lang=en-GB&ipa=%2F%CB%88set.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=setback&lang=en-US&ipa=%2F%CB%88set.b%C3%A6k%2F"},{"id":"lv_4_350","topic":"Cultural and Historical Exchange","word":"settlement","pos":"(n)","ipa":"/ˈset̬.əl.mənt/","defVi":"khu định cư, điểm định cư","defEn":"a place where people come to live and build homes","examples":["The small [settlement] eventually grew into a thriving city. (=Dịch: Khu định cư nhỏ bé cuối cùng đã phát triển thành một thành phố phồn vinh.)","Explorers discovered the ruins of an ancient [settlement] near the river. (=Dịch: Các nhà thám hiểm đã phát hiện ra tàn tích của một khu định cư cổ xưa gần con sông.)","The government provided basic infrastructure for the new [settlement]. (=Dịch: Chính phủ đã cung cấp cơ sở hạ tầng cơ bản cho khu định cư mới.)"],"ukAudio":"/ai_services/tts3/?q=settlement&lang=en-GB&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=settlement&lang=en-US&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F"},{"id":"lv_4_351","topic":"Cultural and Historical Exchange","word":"settler","pos":"(n)","ipa":"/ˈsɛt.lɚ/","defVi":"người khai hoang, người định cư","defEn":"a person who moves with a group to live in a new country or area","examples":["Early [settlers] faced harsh winters and food shortages in the new territory. (=Dịch: Những người đi khai hoang thời kỳ đầu đã phải đối mặt với mùa đông khắc nghiệt và tình trạng thiếu thốn lương thực ở vùng đất mới.)","The museum showcases tools used by European [settlers] in the 18th century. (=Dịch: Bảo tàng trưng bày các công cụ được những người định cư châu Âu sử dụng vào thế kỷ 18.)","Each [settler] was granted a piece of land to farm and build a home. (=Dịch: Mỗi người định cư được cấp một mảnh đất để canh tác và xây dựng nhà cửa.)"],"ukAudio":"/ai_services/tts3/?q=settler&lang=en-GB&ipa=%2F%CB%88s%C9%9Bt.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=settler&lang=en-US&ipa=%2F%CB%88s%C9%9Bt.l%C9%9A%2F"},{"id":"lv_4_352","topic":"Cultural and Historical Exchange","word":"seventeenth","pos":"(adj)","ipa":"/ˌsev.ənˈtiːnθ/","defVi":"thứ mười bảy","defEn":"coming next after the sixteenth in order or time","examples":["The museum exhibits paintings from the [seventeenth] century. (=Dịch: Bảo tàng trưng bày các bức tranh từ thế kỷ thứ mười bảy.)","Today is her [seventeenth] birthday, and she is having a party. (=Dịch: Hôm nay là sinh nhật thứ mười bảy của cô ấy, và cô ấy đang tổ chức một bữa tiệc.)","He finished in [seventeenth] place out of fifty runners. (=Dịch: Anh ấy về đích ở vị trí thứ mười bảy trong tổng số năm mươi vận động viên chạy.)"],"ukAudio":"/ai_services/tts3/?q=seventeenth&lang=en-GB&ipa=%2F%CB%8Csev.%C9%99n%CB%88ti%CB%90n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=seventeenth&lang=en-US&ipa=%2F%CB%8Csev.%C9%99n%CB%88ti%CB%90n%CE%B8%2F"},{"id":"lv_4_353","topic":"Cultural and Historical Exchange","word":"sew","pos":"(v)","ipa":"/soʊ/","defVi":"may, khâu","defEn":"to join or attach things together using a needle and thread","examples":["My grandmother taught me how to [sew] buttons onto shirts. (=Dịch: Bà tôi đã dạy tôi cách khâu cúc vào áo sơ mi.)","She plans to [sew] her own dress for the graduation ceremony. (=Dịch: Cô ấy dự định tự may váy cho buổi lễ tốt nghiệp của mình.)","He used thick thread to [sew] the torn leather strap of his backpack. (=Dịch: Anh ấy đã dùng chỉ dày để khâu lại dây đeo bằng da bị rách của chiếc ba lô.)"],"ukAudio":"/ai_services/tts3/?q=sew&lang=en-GB&ipa=%2Fso%CA%8A%2F","usAudio":"/ai_services/tts3/?q=sew&lang=en-US&ipa=%2Fso%CA%8A%2F"},{"id":"lv_4_354","topic":"Cultural and Historical Exchange","word":"sex","pos":"(n)","ipa":"/sɛks/","defVi":"giới tính (sinh học)","defEn":"the state of being either male or female, typically based on biological characteristics","examples":["Please state your age and [sex] on the application form. (=Dịch: Vui lòng ghi rõ độ tuổi và [giới tính] của bạn trên mẫu đơn đăng ký.)","The study analyzes how educational outcomes vary by [sex]. (=Dịch: Nghiên cứu phân tích kết quả giáo dục khác nhau như thế nào theo [giới tính].)","Discrimination based on [sex] is strictly prohibited in the workplace. (=Dịch: Phân biệt đối xử dựa trên [giới tính] bị nghiêm cấm tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=sex&lang=en-GB&ipa=%2Fs%C9%9Bks%2F","usAudio":"/ai_services/tts3/?q=sex&lang=en-US&ipa=%2Fs%C9%9Bks%2F"},{"id":"lv_4_355","topic":"Cultural and Historical Exchange","word":"sheepmarket","pos":"(n)","ipa":"/ˈʃipˌmɑr.kɪt/","defVi":"chợ cừu","defEn":"a marketplace where sheep are bought and sold","examples":["Farmers gathered at the local [sheepmarket] early in the morning to trade livestock. (=Dịch: Những người nông dân đã tập trung tại chợ cừu địa phương từ sáng sớm để buôn bán gia súc.)","The town's old [sheepmarket] has been transformed into a bustling tourist square. (=Dịch: Chợ cừu cũ của thị trấn đã được chuyển đổi thành một quảng trường du lịch nhộn nhịp.)","Prices at the annual [sheepmarket] fluctuated due to changes in wool demand. (=Dịch: Giá cả tại phiên chợ cừu thường niên đã biến động do những thay đổi về nhu cầu đối với len.)"],"ukAudio":"/ai_services/tts3/?q=sheepmarket&lang=en-GB&ipa=%2F%CB%88%CA%83ip%CB%8Cm%C9%91r.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=sheepmarket&lang=en-US&ipa=%2F%CB%88%CA%83ip%CB%8Cm%C9%91r.k%C9%AAt%2F"},{"id":"lv_4_356","topic":"Cultural and Historical Exchange","word":"shell","pos":"(n)","ipa":"/ʃel/","defVi":"vỏ (vỏ ốc, vỏ trứng, vỏ sò...)","defEn":"the hard outer covering of an animal, egg, or nut","examples":["Children love collecting every colorful [shell] they find on the beach. (=Dịch: Trẻ em rất thích nhặt từng vỏ sò nhiều màu sắc mà chúng tìm thấy trên bãi biển.)","A turtle can pull its head and legs inside its protective [shell]. (=Dịch: Rùa có thể rụt đầu và chân vào bên trong chiếc mai bảo vệ của nó.)","Crack the egg [shell] gently against the side of the bowl. (=Dịch: Hãy đập nhẹ vỏ trứng vào thành bát.)"],"ukAudio":"/ai_services/tts3/?q=shell&lang=en-GB&ipa=%2F%CA%83el%2F","usAudio":"/ai_services/tts3/?q=shell&lang=en-US&ipa=%2F%CA%83el%2F"},{"id":"lv_4_357","topic":"Cultural and Historical Exchange","word":"shepherd","pos":"(n)","ipa":"/ˈʃɛp.ɚd/","defVi":"người chăn cừu","defEn":"a person whose job is to take care of sheep","examples":["The [shepherd] used trained dogs to guide the flock across the hills. (=Dịch: Người chăn cừu đã sử dụng những chú chó được huấn luyện để dẫn đàn cừu băng qua các ngọn đồi.)","During the storm, the lonely [shepherd] sheltered his animals inside a barn. (=Dịch: Trong suốt cơn bão, người chăn cừu cô độc đã che chở cho đàn gia súc của mình bên trong một chuồng trại.)","Life as a traditional [shepherd] requires endurance and patience in remote landscapes. (=Dịch: Cuộc sống của một người chăn cừu truyền thống đòi hỏi sự bền bỉ và lòng kiên nhẫn giữa những vùng đất xa xôi hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=shepherd&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%9Bp.%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=shepherd&lang=en-US&ipa=%2F%CB%88%CA%83%C9%9Bp.%C9%9Ad%2F"},{"id":"lv_4_358","topic":"Cultural and Historical Exchange","word":"shortage","pos":"(n)","ipa":"/ˈʃɔːr.t̬ɪdʒ/","defVi":"sự thiếu hụt, tình trạng khan hiếm","defEn":"a state in which there is not enough of something that is needed","examples":["The prolonged drought caused a severe [shortage] of drinking water across the region. (=Dịch: Đợt hạn hán kéo dài đã gây ra tình trạng thiếu hụt nước uống trầm trọng trên toàn khu vực.)","Hospitals are currently facing an acute [shortage] of qualified nursing staff. (=Dịch: Các bệnh viện hiện đang đối mặt với tình trạng thiếu hụt cấp tính đội ngũ điều dưỡng viên có trình độ chuyên môn.)","Disruptions in global supply chains have led to a worldwide [shortage] of electronic components. (=Dịch: Sự gián đoạn trong chuỗi cung ứng toàn cầu đã dẫn đến tình trạng thiếu hụt linh kiện điện tử trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=shortage&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%94%CB%90r.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=shortage&lang=en-US&ipa=%2F%CB%88%CA%83%C9%94%CB%90r.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_4_359","topic":"Cultural and Historical Exchange","word":"sightseeing","pos":"(n)","ipa":"/ˈsaɪt.siː.ɪŋ/","defVi":"sự tham quan, ngắm cảnh","defEn":"the activity of visiting interesting and famous places as a tourist","examples":["We did a lot of [sightseeing] during our trip to Paris. (=Dịch: Chúng tôi đã đi ngắm cảnh rất nhiều trong chuyến du lịch tới Paris.)","They booked a guided bus tour for a full day of [sightseeing]. (=Dịch: Họ đã đặt một chuyến tham quan bằng xe buýt có hướng dẫn viên để ngắm cảnh trọn vẹn cả ngày.)","Local markets are great spots to combine shopping with [sightseeing]. (=Dịch: Các khu chợ địa phương là những địa điểm tuyệt vời để kết hợp mua sắm với ngắm cảnh.)"],"ukAudio":"/ai_services/tts3/?q=sightseeing&lang=en-GB&ipa=%2F%CB%88sa%C9%AAt.si%CB%90.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sightseeing&lang=en-US&ipa=%2F%CB%88sa%C9%AAt.si%CB%90.%C9%AA%C5%8B%2F"},{"id":"lv_4_360","topic":"Cultural and Historical Exchange","word":"sixteenth","pos":"(adj)","ipa":"/ˌsɪksˈtinθ/","defVi":"thứ mười sáu","defEn":"coming next after the fifteenth in order or position","examples":["She celebrated her [sixteenth] birthday with a small gathering of close friends. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ mười sáu cùng một buổi tụ họp nhỏ với những người bạn thân.)","This historic church was originally built in the [sixteenth] century. (=Dịch: Nhà thờ lịch sử này ban đầu được xây dựng vào thế kỷ thứ mười sáu.)","He finished in [sixteenth] place in the international marathon competition. (=Dịch: Anh ấy về đích ở vị trí thứ mười sáu trong cuộc thi marathon quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=sixteenth&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAks%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=sixteenth&lang=en-US&ipa=%2F%CB%8Cs%C9%AAks%CB%88tin%CE%B8%2F"},{"id":"lv_4_361","topic":"Cultural and Historical Exchange","word":"skating","pos":"(n)","ipa":"/ˈskeɪ.tɪŋ/","defVi":"môn trượt băng, trượt patin","defEn":"the sport or activity of moving on ice or hard surfaces using special footwear with blades or wheels","examples":["Ice [skating] is a popular winter pastime in cold countries. (=Dịch: Trượt băng là một trò tiêu khiển mùa đông phổ biến ở các nước xứ lạnh.)","She took up roller [skating] to improve her balance and fitness. (=Dịch: Cô ấy bắt đầu chơi trượt patin để cải thiện khả năng giữ thăng bằng và thể lực.)","The frozen lake provided a natural rink for afternoon [skating]. (=Dịch: Mặt hồ đóng băng đã trở thành một sân trượt tự nhiên cho hoạt động trượt băng vào buổi chiều.)"],"ukAudio":"/ai_services/tts3/?q=skating&lang=en-GB&ipa=%2F%CB%88ske%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=skating&lang=en-US&ipa=%2F%CB%88ske%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_4_362","topic":"Cultural and Historical Exchange","word":"skilled","pos":"(adj)","ipa":"/skɪld/","defVi":"lành nghề, có kỹ năng chuyên môn","defEn":"having the knowledge, training, or ability to do something well","examples":["The factory is looking to recruit more [skilled] workers for the production line. (=Dịch: Nhà máy đang tìm cách tuyển dụng thêm nhiều công nhân lành nghề cho dây chuyền sản xuất.)","A [skilled] negotiator can resolve disputes peacefully and efficiently. (=Dịch: Một nhà đàm phán lành nghề có thể giải quyết các tranh chấp một cách hòa bình và hiệu quả.)","Creating handmade pottery requires a very [skilled] touch. (=Dịch: Làm đồ gốm thủ công đòi hỏi một bàn tay rất khéo léo.)"],"ukAudio":"/ai_services/tts3/?q=skilled&lang=en-GB&ipa=%2Fsk%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=skilled&lang=en-US&ipa=%2Fsk%C9%AAld%2F"},{"id":"lv_4_363","topic":"Cultural and Historical Exchange","word":"soda","pos":"(n)","ipa":"/ˈsoʊ.də/","defVi":"nước ngọt có ga","defEn":"a sweet carbonated soft drink","examples":["Drinking too much sugary [soda] can lead to dental problems. (=Dịch: Uống quá nhiều nước ngọt có ga chứa đường có thể dẫn đến các vấn đề về răng miệng.)","He ordered a slice of pizza and a can of [soda]. (=Dịch: Anh ấy đã gọi một miếng bánh pizza và một lon nước ngọt có ga.)","The restaurant replaced regular [soda] with fresh juice options. (=Dịch: Nhà hàng đã thay thế nước ngọt có ga thông thường bằng các lựa chọn nước ép tươi.)"],"ukAudio":"/ai_services/tts3/?q=soda&lang=en-GB&ipa=%2F%CB%88so%CA%8A.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=soda&lang=en-US&ipa=%2F%CB%88so%CA%8A.d%C9%99%2F"},{"id":"lv_4_364","topic":"Cultural and Historical Exchange","word":"somewhat","pos":"(adv)","ipa":"/ˈsʌm.wʌt/","defVi":"hơi, có phần, một chút","defEn":"to some degree; a little","examples":["The test results were [somewhat] surprising to the researchers. (=Dịch: Kết quả kiểm tra có phần bất ngờ đối với các nhà nghiên cứu.)","Her condition has improved [somewhat] since yesterday. (=Dịch: Tình trạng của cô ấy đã cải thiện đôi chút kể từ hôm qua.)","I felt [somewhat] tired after walking around the museum all morning. (=Dịch: Tôi cảm thấy hơi mệt sau khi đi bộ quanh bảo tàng suốt cả buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=somewhat&lang=en-GB&ipa=%2F%CB%88s%CA%8Cm.w%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=somewhat&lang=en-US&ipa=%2F%CB%88s%CA%8Cm.w%CA%8Ct%2F"},{"id":"lv_4_365","topic":"Cultural and Historical Exchange","word":"southern","pos":"(adj)","ipa":"/ˈsʌð.ərn/","defVi":"thuộc về phương nam, ở phía nam","defEn":"located in or connected with the south","examples":["The [southern] part of the country enjoys a much warmer climate. (=Dịch: Khu vực phía nam của đất nước có khí hậu ấm áp hơn nhiều.)","Many migratory birds travel to the [southern] hemisphere during winter. (=Dịch: Nhiều loài chim di cư bay đến bán cầu nam trong suốt mùa đông.)","They spent their summer vacation exploring charming [southern] coastal towns. (=Dịch: Họ đã dành kỳ nghỉ hè để khám phá các thị trấn ven biển phía nam đầy quyến rũ.)"],"ukAudio":"/ai_services/tts3/?q=southern&lang=en-GB&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%99rn%2F","usAudio":"/ai_services/tts3/?q=southern&lang=en-US&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%99rn%2F"},{"id":"lv_4_366","topic":"Cultural and Historical Exchange","word":"spectacular","pos":"(adj)","ipa":"/spekˈtæk.jə.lɚ/","defVi":"ngoạn mục, hùng vĩ, đẹp mắt","defEn":"very impressive, exciting, or visually striking","examples":["The resort offers a [spectacular] view of the snow-capped mountains. (=Dịch: Khu nghỉ dưỡng mang lại một khung cảnh ngoạn mục của những ngọn núi phủ đầy tuyết.)","The opening ceremony ended with a [spectacular] fireworks display. (=Dịch: Lễ khai mạc đã kết thúc bằng một màn trình diễn pháo hoa ngoạn mục.)","The team made a [spectacular] comeback in the final minutes of the match. (=Dịch: Đội bóng đã có một cuộc lội ngược dòng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_4_367","topic":"Cultural and Historical Exchange","word":"spin","pos":"(v)","ipa":"/spɪn/","defVi":"xoay tròn, quay, kéo sợi","defEn":"to turn round and round quickly, or to make thread by twisting fibers","examples":["The ice skater began to [spin] rapidly on one foot during her routine. (=Dịch: Vận động viên trượt băng bắt đầu xoay tròn nhanh chóng trên một chân trong bài biểu diễn của mình.)","In ancient times, people used simple wheels to [spin] wool into yarn. (=Dịch: Thời cổ đại, con người dùng những bánh xe đơn giản để kéo len thành sợi.)","The washing machine will [spin] the clothes dry before the cycle ends. (=Dịch: Máy giặt sẽ vắt khô quần áo trước khi chu trình kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=spin&lang=en-GB&ipa=%2Fsp%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spin&lang=en-US&ipa=%2Fsp%C9%AAn%2F"},{"id":"lv_4_368","topic":"Cultural and Historical Exchange","word":"spiral","pos":"(n)","ipa":"/ˈspaɪ.rəl/","defVi":"hình xoắn ốc, đường xoắn ốc","defEn":"a winding shape or curve that curves around a central point while moving further away or closer","examples":["The architect designed a stunning [spiral] staircase in the center of the lobby. (=Dịch: Kiến trúc sư đã thiết kế một cầu thang xoắn ốc tuyệt đẹp ở vị trí trung tâm sảnh chờ.)","A snail's shell features a distinctive geometric [spiral] pattern. (=Dịch: Vỏ của ốc sên có họa tiết hình xoắn ốc hình học rất đặc trưng.)","The rising smoke formed a slow [spiral] in the quiet air of the room. (=Dịch: Làn khói bốc lên tạo thành một vòng xoắn ốc chậm rãi trong bầu không khí tĩnh lặng của căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=spiral&lang=en-GB&ipa=%2F%CB%88spa%C9%AA.r%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spiral&lang=en-US&ipa=%2F%CB%88spa%C9%AA.r%C9%99l%2F"},{"id":"lv_4_369","topic":"Cultural and Historical Exchange","word":"spiritual","pos":"(adj)","ipa":"/ˈspɪr.ɪ.tʃu.əl/","defVi":"thuộc về tâm linh, tinh thần","defEn":"relating to deep feelings and beliefs, especially religious or inner personal values","examples":["Yoga helps people improve both their physical and [spiritual] well-being. (=Dịch: Yoga giúp con người cải thiện cả sức khỏe thể chất lẫn tinh thần.)","The ancient temple is regarded as an important [spiritual] center for the community. (=Dịch: Ngôi đền cổ kính được coi là một trung tâm tâm linh quan trọng đối với cộng đồng.)","Music often provides a deep [spiritual] connection for many listeners. (=Dịch: Âm nhạc thường mang lại sự kết nối tâm linh sâu sắc cho nhiều người nghe.)"],"ukAudio":"/ai_services/tts3/?q=spiritual&lang=en-GB&ipa=%2F%CB%88sp%C9%AAr.%C9%AA.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spiritual&lang=en-US&ipa=%2F%CB%88sp%C9%AAr.%C9%AA.t%CA%83u.%C9%99l%2F"},{"id":"lv_4_370","topic":"Cultural and Historical Exchange","word":"spy","pos":"(n)","ipa":"/spaɪ/","defVi":"điệp viên, gián điệp","defEn":"a person employed to obtain secret information about an enemy or competitor","examples":["The government arrested a foreign [spy] who was collecting military secrets. (=Dịch: Chính phủ đã bắt giữ một điệp viên nước ngoài đang thu thập các bí mật quân sự.)","He worked as a double [spy] during the war, passing false information to both sides. (=Dịch: Ông từng làm gián điệp hai mang trong thời chiến, tuồn thông tin giả cho cả hai phía.)","The novelist wrote a gripping story about a secret [spy] mission in Berlin. (=Dịch: Tiểu thuyết gia đã viết một câu chuyện hấp dẫn về một nhiệm vụ gián điệp bí mật tại Berlin.)"],"ukAudio":"/ai_services/tts3/?q=spy&lang=en-GB&ipa=%2Fspa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=spy&lang=en-US&ipa=%2Fspa%C9%AA%2F"},{"id":"lv_4_371","topic":"Cultural and Historical Exchange","word":"stable","pos":"(n)","ipa":"/ˈsteɪ.bəl/","defVi":"chuồng ngựa","defEn":"a building in which horses or other domestic animals are kept and fed","examples":["The farmer led the tired horse back into the [stable] after a long day. (=Dịch: Người nông dân dắt con ngựa mệt mỏi trở lại chuồng ngựa sau một ngày dài.)","They cleaned out the [stable] and put down fresh straw for the animals. (=Dịch: Họ dọn sạch chuồng ngựa và rải rơm mới cho đàn vật nuôi.)","The riding school has a large [stable] that can house over twenty horses. (=Dịch: Trường dạy cưỡi ngựa có một chuồng ngựa lớn có thể chứa hơn hai mươi con ngựa.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_4_372","topic":"Cultural and Historical Exchange","word":"stadium","pos":"(n)","ipa":"/ˈsteɪ.di.əm/","defVi":"sân vận động","defEn":"a large closed area of land with rows of seats around it, used for sports events and concerts","examples":["Thousands of excited fans gathered inside the [stadium] for the match. (=Dịch: Hàng ngàn người hâm mộ hào hứng đã tập trung bên trong sân vận động để theo dõi trận đấu.)","The city invested millions of dollars to build a modern [stadium]. (=Dịch: Thành phố đã đầu tư hàng triệu đô la để xây dựng một sân vận động hiện đại.)","Famous musicians often choose a large [stadium] for their world tours. (=Dịch: Các nghệ sĩ âm nhạc nổi tiếng thường chọn sân vận động lớn cho các chuyến lưu diễn vòng quanh thế giới của họ.)"],"ukAudio":"/ai_services/tts3/?q=stadium&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stadium&lang=en-US&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F"},{"id":"lv_4_373","topic":"Cultural and Historical Exchange","word":"statue","pos":"(n)","ipa":"/ˈstæ.tʃuː/","defVi":"bức tượng, pho tượng","defEn":"a three-dimensional figure of a person, animal, or object made of stone, metal, or other materials","examples":["A large bronze [statue] was erected in the city center to honor the national hero. (=Dịch: Một bức tượng đồng lớn đã được dựng lên ở trung tâm thành phố để vinh danh vị anh hùng dân tộc.)","Tourists gathered in the square to take pictures of the historic marble [statue]. (=Dịch: Khách du lịch tụ tập tại quảng trường để chụp ảnh bức tượng đá cẩm thạch lịch sử.)","The museum displays a remarkable ancient [statue] that dates back over two thousand years. (=Dịch: Bảo tàng trưng bày một bức tượng cổ đáng chú ý có niên đại hơn hai nghìn năm trước.)"],"ukAudio":"/ai_services/tts3/?q=statue&lang=en-GB&ipa=%2F%CB%88st%C3%A6.t%CA%83u%CB%90%2F","usAudio":"/ai_services/tts3/?q=statue&lang=en-US&ipa=%2F%CB%88st%C3%A6.t%CA%83u%CB%90%2F"},{"id":"lv_4_374","topic":"Cultural and Historical Exchange","word":"steel","pos":"(n)","ipa":"/stil/","defVi":"thép","defEn":"a strong, hard metal made of iron and carbon","examples":["The bridge is supported by massive [steel] beams. (=Dịch: Cây cầu được nâng đỡ bởi những thanh dầm thép khổng lồ.)","Demand for [steel] increased rapidly during the construction boom. (=Dịch: Nhu cầu về thép đã tăng nhanh chóng trong thời kỳ bùng nổ xây dựng.)","Modern skyscrapers are constructed using reinforced [steel]. (=Dịch: Các tòa nhà chọc trời hiện đại được xây dựng bằng thép gia cường.)"],"ukAudio":"/ai_services/tts3/?q=steel&lang=en-GB&ipa=%2Fstil%2F","usAudio":"/ai_services/tts3/?q=steel&lang=en-US&ipa=%2Fstil%2F"},{"id":"lv_4_375","topic":"Cultural and Historical Exchange","word":"stoic","pos":"(n)","ipa":"/ˈstoʊ.ɪk/","defVi":"người kiên cường, người khắc kỷ","defEn":"a person who can endure pain or hardship without showing their feelings or complaining","examples":["Even during the medical crisis, he remained a true [stoic] and never complained. (=Dịch: Ngay cả trong cơn khủng hoảng sức khỏe, anh ấy vẫn là một người khắc kỷ thực thụ và không bao giờ than phiền.)","She acted like a [stoic] despite hearing the terrible news about her business. (=Dịch: Cô ấy vẫn giữ vẻ bình thản dù nghe tin khủng khiếp về công việc kinh doanh của mình.)","As a devoted [stoic], the soldier bore his physical injuries in silence. (=Dịch: Là một người kiên cường theo chủ nghĩa khắc kỷ, người lính đã âm thầm chịu đựng những vết thương thể xác.)"],"ukAudio":"/ai_services/tts3/?q=stoic&lang=en-GB&ipa=%2F%CB%88sto%CA%8A.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=stoic&lang=en-US&ipa=%2F%CB%88sto%CA%8A.%C9%AAk%2F"},{"id":"lv_4_376","topic":"Cultural and Historical Exchange","word":"stoicism","pos":"(n)","ipa":"/ˈstoʊ.ə.sɪ.zəm/","defVi":"chủ nghĩa khắc kỷ, sự kiên nhẫn chịu đựng","defEn":"the endurance of pain or hardship without a display of feelings and without complaint","examples":["Ancient Greek [stoicism] teaches people to focus only on what they can control. (=Dịch: Chủ nghĩa khắc kỷ Hy Lạp cổ đại dạy con người chỉ nên tập trung vào những gì họ có thể kiểm soát.)","She faced every family misfortune with remarkable calm and [stoicism]. (=Dịch: Cô ấy đối mặt với mọi bất hạnh của gia đình với sự bình tĩnh và lòng kiên định đáng kinh ngạc.)","Many modern leaders study [stoicism] to manage stress in high-pressure situations. (=Dịch: Nhiều nhà lãnh đạo hiện đại học tập chủ nghĩa khắc kỷ để quản lý sự căng thẳng trong các tình huống chịu nhiều áp lực.)"],"ukAudio":"/ai_services/tts3/?q=stoicism&lang=en-GB&ipa=%2F%CB%88sto%CA%8A.%C9%99.s%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stoicism&lang=en-US&ipa=%2F%CB%88sto%CA%8A.%C9%99.s%C9%AA.z%C9%99m%2F"},{"id":"lv_4_377","topic":"Cultural and Historical Exchange","word":"stream","pos":"(n)","ipa":"/strim/","defVi":"con suối, dòng suối","defEn":"a small, narrow river of continuous flowing water","examples":["A clear [stream] flows through the middle of the village. (=Dịch: Một con suối trong vắt chảy qua giữa ngôi làng.)","We sat by the [stream] and listened to the gentle sound of water. (=Dịch: Chúng tôi ngồi bên dòng suối và lắng nghe tiếng nước chảy êm đềm.)","The mountain [stream] provides fresh drinking water for local residents. (=Dịch: Con suối trên núi cung cấp nước uống sạch cho người dân địa phương.)"],"ukAudio":"/ai_services/tts3/?q=stream&lang=en-GB&ipa=%2Fstrim%2F","usAudio":"/ai_services/tts3/?q=stream&lang=en-US&ipa=%2Fstrim%2F"},{"id":"lv_4_378","topic":"Cultural and Historical Exchange","word":"strength","pos":"(n)","ipa":"/strɛŋkθ/","defVi":"sức mạnh, thể lực","defEn":"the physical power and energy that makes someone strong","examples":["Weight training is an effective method to build overall physical [strength]. (=Dịch: Tập tạ là một phương pháp hiệu quả để xây dựng sức mạnh thể chất toàn diện.)","She barely had the [strength] to get out of bed after running the marathon. (=Dịch: Cô ấy gần như không còn sức lực để rời khỏi giường sau khi chạy marathon.)","The team drew [strength] from the loud support of their home crowd. (=Dịch: Đội tuyển đã được tiếp thêm sức mạnh từ sự cổ vũ cuồng nhiệt của khán giả nhà.)"],"ukAudio":"/ai_services/tts3/?q=strength&lang=en-GB&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F","usAudio":"/ai_services/tts3/?q=strength&lang=en-US&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F"},{"id":"lv_4_379","topic":"Cultural and Historical Exchange","word":"substance","pos":"(n)","ipa":"/ˈsʌb.stəns/","defVi":"chất, vật chất","defEn":"a particular kind of matter with uniform properties","examples":["The laboratory test revealed a dangerous chemical [substance] in the water. (=Dịch: Xét nghiệm trong phòng thí nghiệm đã phát hiện ra một chất hóa học nguy hiểm trong nước.)","Rubber is a flexible [substance] used in making tires. (=Dịch: Cao su là một chất có tính đàn hồi được sử dụng để sản xuất lốp xe.)","Scientists discovered an unknown [substance] on the surface of the meteorite. (=Dịch: Các nhà khoa học đã phát hiện ra một chất chưa xác định trên bề mặt của thiên thạch.)"],"ukAudio":"/ai_services/tts3/?q=substance&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=substance&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F"},{"id":"lv_4_380","topic":"Cultural and Historical Exchange","word":"sufficient","pos":"(adj)","ipa":"/səˈfɪʃ.ənt/","defVi":"đủ, đầy đủ","defEn":"enough for a particular purpose; as much as is needed","examples":["We need [sufficient] evidence before we can make a final decision. (=Dịch: Chúng tôi cần đầy đủ bằng chứng trước khi có thể đưa ra quyết định cuối cùng.)","Make sure you get [sufficient] sleep before the exam. (=Dịch: Hãy đảm bảo rằng bạn ngủ đủ giấc trước kỳ thi.)","The salary is [sufficient] to cover all her living expenses. (=Dịch: Mức lương này đủ để chi trả mọi chi phí sinh hoạt của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=sufficient&lang=en-GB&ipa=%2Fs%C9%99%CB%88f%C9%AA%CA%83.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=sufficient&lang=en-US&ipa=%2Fs%C9%99%CB%88f%C9%AA%CA%83.%C9%99nt%2F"},{"id":"lv_4_381","topic":"Cultural and Historical Exchange","word":"superior","pos":"(adj)","ipa":"/suːˈpɪr.i.ɚ/","defVi":"vượt trội, cao cấp hơn; cấp trên","defEn":"better in quality than someone or something else; higher in rank","examples":["This model is [superior] to the older version in terms of battery life. (=Dịch: Mẫu này vượt trội hơn phiên bản cũ về thời lượng pin.)","He always behaves as if he has a [superior] knowledge of the subject. (=Dịch: Anh ấy luôn cư xử như thể mình có hiểu biết siêu việt về chủ đề này.)","She reported the incident directly to her [superior] officer. (=Dịch: Cô ấy đã báo cáo sự việc trực tiếp cho cấp trên của mình.)"],"ukAudio":"/ai_services/tts3/?q=superior&lang=en-GB&ipa=%2Fsu%CB%90%CB%88p%C9%AAr.i.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=superior&lang=en-US&ipa=%2Fsu%CB%90%CB%88p%C9%AAr.i.%C9%9A%2F"},{"id":"lv_4_382","topic":"Cultural and Historical Exchange","word":"survive","pos":"(v)","ipa":"/sərˈvaɪv/","defVi":"sống sót, tồn tại qua khó khăn","defEn":"to continue to live or exist, especially through hardship or danger","examples":["Few plants can [survive] in the extreme cold of the Arctic desert. (=Dịch: Rất ít loài thực vật có thể sống sót trong cái lạnh khắc nghiệt của hoang mạc Bắc Cực.)","Miraculously, all passengers managed to [survive] the severe train crash. (=Dịch: Thật kỳ diệu, tất cả các hành khách đều sống sót sau vụ tai nạn tàu hỏa nghiêm trọng.)","Small businesses struggle to [survive] during unexpected economic downturns. (=Dịch: Các doanh nghiệp nhỏ phải vật lộn để tồn tại trong những giai đoạn suy thoái kinh tế bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=survive&lang=en-GB&ipa=%2Fs%C9%99r%CB%88va%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=survive&lang=en-US&ipa=%2Fs%C9%99r%CB%88va%C9%AAv%2F"},{"id":"lv_4_383","topic":"Cultural and Historical Exchange","word":"surviving","pos":"(adj)","ipa":"/sərˈvaɪ.vɪŋ/","defVi":"sống sót, còn tồn tại","defEn":"continuing to live or exist after a dangerous event or long period","examples":["The [surviving] passengers were quickly taken to the nearest hospital. (=Dịch: Những hành khách sống sót đã nhanh chóng được đưa đến bệnh viện gần nhất.)","It is one of the few [surviving] examples of medieval architecture in the city. (=Dịch: Đây là một trong số ít những công trình kiến trúc thời trung cổ còn sót lại trong thành phố.)","The museum displays artifacts from the only [surviving] manuscript of the epic poem. (=Dịch: Bảo tàng trưng bày các hiện vật từ bản thảo duy nhất còn sót lại của thiên sử thi.)"],"ukAudio":"/ai_services/tts3/?q=surviving&lang=en-GB&ipa=%2Fs%C9%99r%CB%88va%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=surviving&lang=en-US&ipa=%2Fs%C9%99r%CB%88va%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_4_384","topic":"Cultural and Historical Exchange","word":"sustain","pos":"(v)","ipa":"/səˈsteɪn/","defVi":"duy trì, chống đỡ, nuôi dưỡng","defEn":"to cause or allow something to continue for a period of time","examples":["The company struggled to [sustain] its rapid growth during the economic crisis. (=Dịch: Công ty đã phải vật lộn để duy trì sự tăng trưởng nhanh chóng trong cuộc khủng hoảng kinh tế.)","The earth produces enough food to [sustain] the entire global population. (=Dịch: Trái Đất sản xuất đủ lương thực để nuôi sống toàn bộ dân số toàn cầu.)","These ancient stone pillars cannot [sustain] the heavy weight of the new roof. (=Dịch: Những cây cột đá cổ này không thể chống đỡ được sức nặng của phần mái mới.)"],"ukAudio":"/ai_services/tts3/?q=sustain&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=sustain&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AAn%2F"},{"id":"lv_4_385","topic":"Cultural and Historical Exchange","word":"swiss","pos":"(adj)","ipa":"/swɪs/","defVi":"thuộc về Thụy Sĩ, người Thụy Sĩ","defEn":"relating to Switzerland or its people","examples":["She bought a high-quality [Swiss] watch during her vacation in Geneva. (=Dịch: Cô ấy đã mua một chiếc đồng hồ Thụy Sĩ chất lượng cao trong kỳ nghỉ ở Geneva.)","The recipe calls for authentic [Swiss] cheese to give it a rich flavor. (=Dịch: Công thức yêu cầu phô mai Thụy Sĩ chính hiệu để tạo nên hương vị béo ngậy đậm đà.)","We spent a week hiking through the breathtaking [Swiss] Alps. (=Dịch: Chúng tôi đã dành một tuần đi bộ đường dài qua dãy Alps hùng vĩ của Thụy Sĩ.)"],"ukAudio":"/ai_services/tts3/?q=swiss&lang=en-GB&ipa=%2Fsw%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=swiss&lang=en-US&ipa=%2Fsw%C9%AAs%2F"},{"id":"lv_4_386","topic":"Cultural and Historical Exchange","word":"sydney","pos":"(n)","ipa":"/ˈsɪd.ni/","defVi":"thành phố Sydney (Úc)","defEn":"the largest city in Australia, famous for its Opera House and harbor","examples":["She decided to move to [Sydney] to pursue her university studies. (=Dịch: Cô ấy quyết định chuyển đến Sydney để theo đuổi việc học đại học.)","The flight from Tokyo to [Sydney] takes around nine hours. (=Dịch: Chuyến bay từ Tokyo đến Sydney mất khoảng chín tiếng.)","Many tourists visit [Sydney] every year to see the famous Opera House. (=Dịch: Nhiều du khách đến thăm Sydney hàng năm để chiêm ngưỡng Nhà hát Opera nổi tiếng.)"],"ukAudio":"/ai_services/tts3/?q=sydney&lang=en-GB&ipa=%2F%CB%88s%C9%AAd.ni%2F","usAudio":"/ai_services/tts3/?q=sydney&lang=en-US&ipa=%2F%CB%88s%C9%AAd.ni%2F"},{"id":"lv_4_387","topic":"Cultural and Historical Exchange","word":"symphony","pos":"(n)","ipa":"/ˈsɪm.fə.ni/","defVi":"bản nhạc giao hưởng","defEn":"a long, elaborate musical composition usually in four movements for a full orchestra","examples":["The orchestra performed Beethoven's Ninth [symphony] with tremendous energy. (=Dịch: Dàn nhạc đã biểu diễn bản giao hưởng số 9 của Beethoven với nguồn năng lượng vô cùng mạnh mẽ.)","Attending a live [symphony] concert is an unforgettable experience for music lovers. (=Dịch: Tham dự một buổi hòa nhạc giao hưởng trực tiếp là một trải nghiệm khó quên đối với những người yêu âm nhạc.)","He spent years composing a grand [symphony] dedicated to his homeland. (=Dịch: Ông đã dành nhiều năm để sáng tác một bản giao hưởng hoành tráng dành tặng cho quê hương mình.)"],"ukAudio":"/ai_services/tts3/?q=symphony&lang=en-GB&ipa=%2F%CB%88s%C9%AAm.f%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=symphony&lang=en-US&ipa=%2F%CB%88s%C9%AAm.f%C9%99.ni%2F"},{"id":"lv_4_388","topic":"Cultural and Historical Exchange","word":"tailor","pos":"(n)","ipa":"/ˈteɪ.lər/","defVi":"thợ may (đặc biệt là may âu phục)","defEn":"a person whose job is making, repairing, or altering clothes, especially suits and coats","examples":["He went to a local [tailor] to get his wedding suit made. (=Dịch: Anh ấy đã đến một [thợ may] địa phương để may bộ âu phục cưới của mình.)","The [tailor] carefully measured my waist and shoulders. (=Dịch: Người [thợ may] cẩn thận đo vòng eo và vai của tôi.)","If these trousers are too long, a [tailor] can easily shorten them. (=Dịch: Nếu chiếc quần này quá dài, một người [thợ may] có thể dễ dàng cắt ngắn nó.)"],"ukAudio":"/ai_services/tts3/?q=tailor&lang=en-GB&ipa=%2F%CB%88te%C9%AA.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tailor&lang=en-US&ipa=%2F%CB%88te%C9%AA.l%C9%99r%2F"},{"id":"lv_4_389","topic":"Cultural and Historical Exchange","word":"tax","pos":"(n)","ipa":"/tæks/","defVi":"thuế, tiền thuế","defEn":"money that you have to pay to the government based on your income or cost of goods","examples":["The government decided to raise the [tax] on sugary drinks. (=Dịch: Chính phủ đã quyết định tăng thuế đối với đồ uống có đường.)","Citizens must file their income [tax] returns before the deadline. (=Dịch: Công dân phải nộp tờ khai thuế thu nhập trước thời hạn.)","The price displayed on the menu includes all local [tax] charges. (=Dịch: Giá niêm yết trên thực đơn đã bao gồm tất cả các khoản thuế địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tax&lang=en-GB&ipa=%2Ft%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=tax&lang=en-US&ipa=%2Ft%C3%A6ks%2F"},{"id":"lv_4_390","topic":"Cultural and Historical Exchange","word":"technician","pos":"(n)","ipa":"/tɛkˈnɪʃ.ən/","defVi":"kỹ thuật viên, thợ kỹ thuật","defEn":"a person skilled in the practical techniques of a specific science, trade, or craft","examples":["A laboratory [technician] analyzed the blood samples. (=Dịch: Một [kỹ thuật viên] phòng thí nghiệm đã phân tích các mẫu máu.)","We called an IT [technician] to fix the server issue. (=Dịch: Chúng tôi đã gọi một [kỹ thuật viên] công nghệ thông tin đến để khắc phục sự cố máy chủ.)","The aircraft was thoroughly inspected by a certified [technician]. (=Dịch: Chiếc máy bay đã được kiểm tra kỹ lưỡng bởi một [kỹ thuật viên] có chứng chỉ.)"],"ukAudio":"/ai_services/tts3/?q=technician&lang=en-GB&ipa=%2Ft%C9%9Bk%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=technician&lang=en-US&ipa=%2Ft%C9%9Bk%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_391","topic":"Cultural and Historical Exchange","word":"technological","pos":"(adj)","ipa":"/ˌtek.nəˈlɑː.dʒɪ.kəl/","defVi":"thuộc về công nghệ, kỹ thuật","defEn":"relating to or using scientific knowledge and machinery in industry or daily life","examples":["Recent [technological] advancements have transformed the way people communicate. (=Dịch: Những tiến bộ công nghệ gần đây đã làm thay đổi cách thức con người giao tiếp.)","The company invested heavily in [technological] innovations to improve productivity. (=Dịch: Công ty đã đầu tư mạnh mẽ vào các đổi mới công nghệ nhằm nâng cao năng suất.)","Automation is one of the biggest [technological] changes in modern manufacturing. (=Dịch: Tự động hóa là một trong những thay đổi công nghệ lớn nhất trong ngành sản xuất hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=technological&lang=en-GB&ipa=%2F%CB%8Ctek.n%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=technological&lang=en-US&ipa=%2F%CB%8Ctek.n%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_4_392","topic":"Cultural and Historical Exchange","word":"telegraph","pos":"(n)","ipa":"/ˈtel.ə.ɡræf/","defVi":"điện báo, máy điện báo","defEn":"an early communication system that transmitted electrical signals over wires","examples":["The invention of the [telegraph] revolutionized long-distance communication in the 19th century. (=Dịch: Phát minh ra máy điện báo đã cách mạng hóa việc liên lạc đường dài vào thế kỷ 19.)","News of the victory was sent quickly across the country by [telegraph]. (=Dịch: Tin tức về chiến thắng đã được truyền đi nhanh chóng khắp cả nước bằng điện báo.)","Before the telephone became common, people relied heavily on the [telegraph]. (=Dịch: Trước khi điện thoại trở nên phổ biến, mọi người phụ thuộc rất nhiều vào điện báo.)"],"ukAudio":"/ai_services/tts3/?q=telegraph&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=telegraph&lang=en-US&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F"},{"id":"lv_4_393","topic":"Cultural and Historical Exchange","word":"temple","pos":"(n)","ipa":"/ˈtɛm.pəl/","defVi":"ngôi đền, ngôi chùa","defEn":"a building used for religious worship, especially in religions other than Christianity","examples":["Many pilgrims travel to the ancient [temple] to pray every spring. (=Dịch: Nhiều người hành hương đến ngôi đền cổ để cầu nguyện vào mỗi mùa xuân.)","The Buddhist [temple] is situated high on a misty mountain. (=Dịch: Ngôi chùa Phật giáo nằm ở vị trí cao trên một ngọn núi mù sương.)","Tourists must remove their shoes before entering the sacred [temple]. (=Dịch: Du khách phải cởi giày trước khi bước vào ngôi đền linh thiêng.)"],"ukAudio":"/ai_services/tts3/?q=temple&lang=en-GB&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=temple&lang=en-US&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F"},{"id":"lv_4_394","topic":"Cultural and Historical Exchange","word":"tension","pos":"(n)","ipa":"/ˈtɛn.ʃən/","defVi":"sự căng thẳng, tình trạng đối đầu","defEn":"a feeling of nervousness, lack of trust, or strain between people or groups","examples":["Diplomatic talks helped reduce political [tension] between the two neighboring countries. (=Dịch: Các cuộc đàm phán ngoại giao đã giúp giảm bớt căng thẳng chính trị giữa hai quốc gia láng giềng.)","You could feel the growing [tension] in the room as the deadline approached. (=Dịch: Bạn có thể cảm nhận được sự căng thẳng ngày càng tăng trong phòng khi thời hạn chót đang đến gần.)","Regular exercise and meditation can effectively relieve physical [tension] caused by daily stress. (=Dịch: Tập thể dục thường xuyên và thiền định có thể giải tỏa hiệu quả sự căng cơ do căng thẳng hàng ngày gây ra.)"],"ukAudio":"/ai_services/tts3/?q=tension&lang=en-GB&ipa=%2F%CB%88t%C9%9Bn.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=tension&lang=en-US&ipa=%2F%CB%88t%C9%9Bn.%CA%83%C9%99n%2F"},{"id":"lv_4_395","topic":"Cultural and Historical Exchange","word":"textile","pos":"(n)","ipa":"/ˈtek.staɪl/","defVi":"vải dệt, hàng dệt may","defEn":"any type of cloth or woven fabric","examples":["The region is famous for its traditional [textile] industry. (=Dịch: Khu vực này nổi tiếng với ngành dệt may truyền thống.)","Natural fibres are commonly used to produce high-quality [textile] goods. (=Dịch: Sợi tự nhiên thường được sử dụng để sản xuất các mặt hàng dệt may chất lượng cao.)","The museum exhibits ancient [textile] patterns from different cultures. (=Dịch: Bảo tàng trưng bày các hoa văn dệt may cổ xưa từ nhiều nền văn hóa khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=textile&lang=en-GB&ipa=%2F%CB%88tek.sta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=textile&lang=en-US&ipa=%2F%CB%88tek.sta%C9%AAl%2F"},{"id":"lv_4_396","topic":"Cultural and Historical Exchange","word":"therapy","pos":"(n)","ipa":"/ˈθer.ə.pi/","defVi":"liệu pháp, sự điều trị","defEn":"treatment intended to relieve or heal a disorder or illness","examples":["Physical [therapy] helped the athlete recover from a severe knee injury. (=Dịch: Vật lý trị liệu đã giúp vận động viên hồi phục sau chấn thương đầu gối nghiêm trọng.)","She attends weekly cognitive behavioral [therapy] sessions to manage stress. (=Dịch: Cô ấy tham gia các buổi trị liệu hành vi nhận thức hàng tuần để kiểm soát sự căng thẳng.)","Art [therapy] is often used to help children express their feelings. (=Dịch: Trị liệu nghệ thuật thường được sử dụng để giúp trẻ em bộc lộ cảm xúc của mình.)"],"ukAudio":"/ai_services/tts3/?q=therapy&lang=en-GB&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F","usAudio":"/ai_services/tts3/?q=therapy&lang=en-US&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F"},{"id":"lv_4_397","topic":"Cultural and Historical Exchange","word":"thermometer","pos":"(n)","ipa":"/θərˈmɑː.mə.t̬ɚ/","defVi":"nhiệt kế","defEn":"an instrument used for measuring temperature","examples":["The nurse used a digital [thermometer] to check the child's fever. (=Dịch: Y tá đã dùng một chiếc nhiệt kế điện tử để kiểm tra cơn sốt của đứa trẻ.)","Check the outdoor [thermometer] before deciding what clothes to wear. (=Dịch: Hãy kiểm tra nhiệt kế ngoài trời trước khi quyết định nên mặc quần áo gì.)","The laboratory [thermometer] showed a sudden rise in temperature. (=Dịch: Nhiệt kế trong phòng thí nghiệm cho thấy nhiệt độ tăng đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=thermometer&lang=en-GB&ipa=%2F%CE%B8%C9%99r%CB%88m%C9%91%CB%90.m%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=thermometer&lang=en-US&ipa=%2F%CE%B8%C9%99r%CB%88m%C9%91%CB%90.m%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_4_398","topic":"Cultural and Historical Exchange","word":"thumb","pos":"(n)","ipa":"/θʌm/","defVi":"ngón tay cái","defEn":"the short, thick first digit of the human hand, set apart from the other four fingers","examples":["He accidentally hit his [thumb] with the hammer while fixing the shelf. (=Dịch: Anh ấy vô tình đập búa vào ngón tay cái khi đang sửa cái kệ.)","She gave me a [thumb] up to signal that everything was going well. (=Dịch: Cô ấy giơ ngón tay cái lên với tôi để ra hiệu rằng mọi chuyện đang diễn ra tốt đẹp.)","The baby fell asleep while sucking its [thumb]. (=Dịch: Đứa bé ngủ thiếp đi trong khi đang mút ngón tay cái.)"],"ukAudio":"/ai_services/tts3/?q=thumb&lang=en-GB&ipa=%2F%CE%B8%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=thumb&lang=en-US&ipa=%2F%CE%B8%CA%8Cm%2F"},{"id":"lv_4_399","topic":"Cultural and Historical Exchange","word":"tiger","pos":"(n)","ipa":"/ˈtaɪ.ɡər/","defVi":"con hổ","defEn":"a large wild cat that has yellow-orange fur with black stripes","examples":["The Bengal [tiger] is one of the most magnificent wild animals. (=Dịch: [Hổ] Bengal là một trong những loài động vật hoang dã tráng lệ nhất.)","Conservationists are working hard to protect the endangered Siberian [tiger]. (=Dịch: Các nhà bảo tồn đang nỗ lực hết mình để bảo vệ loài [hổ] Siberia có nguy cơ tuyệt chủng.)","We saw a [tiger] resting in the shade at the wildlife park. (=Dịch: Chúng tôi đã nhìn thấy một con [hổ] đang nghỉ ngơi dưới bóng râm tại công viên động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=tiger&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tiger&lang=en-US&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%99r%2F"},{"id":"lv_4_400","topic":"Cultural and Historical Exchange","word":"timeline","pos":"(n)","ipa":"/ˈtaɪm.laɪn/","defVi":"mốc thời gian, dòng thời gian, tiến độ","defEn":"a graphical representation of a period of time on which important events are marked","examples":["The textbook includes a historical [timeline] of the major wars. (=Dịch: Sách giáo khoa bao gồm một dòng thời gian lịch sử về các cuộc chiến tranh lớn.)","The project manager established a strict [timeline] for completing the tasks. (=Dịch: Người quản lý dự án đã thiết lập một mốc thời gian nghiêm ngặt để hoàn thành các nhiệm vụ.)","We need to review the [timeline] to ensure we do not miss the launch date. (=Dịch: Chúng ta cần xem lại tiến độ thời gian để đảm bảo không bỏ lỡ ngày ra mắt.)"],"ukAudio":"/ai_services/tts3/?q=timeline&lang=en-GB&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=timeline&lang=en-US&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F"},{"id":"lv_4_401","topic":"Cultural and Historical Exchange","word":"tin","pos":"(n)","ipa":"/tɪn/","defVi":"thiếc; hộp thiếc, lon","defEn":"a soft, silvery metal, or a metal container used for storing food","examples":["He opened a [tin] of baked beans for a quick dinner. (=Dịch: Anh ấy đã mở một hộp đậu nướng cho bữa tối nhanh gọn.)","Bronze is an alloy mainly composed of copper and [tin]. (=Dịch: Đồng điếu là một hợp kim chủ yếu bao gồm đồng và thiếc.)","Keep the biscuits in an airtight [tin] to keep them crisp. (=Dịch: Hãy giữ bánh quy trong hộp thiếc kín khí để giữ cho bánh luôn giòn.)"],"ukAudio":"/ai_services/tts3/?q=tin&lang=en-GB&ipa=%2Ft%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=tin&lang=en-US&ipa=%2Ft%C9%AAn%2F"},{"id":"lv_4_402","topic":"Cultural and Historical Exchange","word":"trace","pos":"(v)","ipa":"/treɪs/","defVi":"dò tìm, truy vết, lần theo dấu vết","defEn":"to find or discover someone or something by investigation or following clues","examples":["Detectives managed to [trace] the origin of the mysterious phone call. (=Dịch: Các thám tử đã lần ra được nguồn gốc của cuộc gọi bí ẩn.)","Historians can [trace] the tradition back to ancient civilizations. (=Dịch: Các nhà sử học có thể truy nguyên truyền thống này về tận các nền văn minh cổ đại.)","Health officials worked quickly to [trace] anyone who had been in contact with the patient. (=Dịch: Các quan chức y tế đã nhanh chóng làm việc để truy vết bất kỳ ai từng tiếp xúc với bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=trace&lang=en-GB&ipa=%2Ftre%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=trace&lang=en-US&ipa=%2Ftre%C9%AAs%2F"},{"id":"lv_4_403","topic":"Cultural and Historical Exchange","word":"trade","pos":"(v)","ipa":"/treɪd/","defVi":"buôn bán, giao thương, trao đổi","defEn":"to buy and sell goods or services","examples":["The two countries agreed to [trade] agricultural products with each other. (=Dịch: Hai quốc gia đã đồng ý buôn bán các sản phẩm nông nghiệp với nhau.)","Many merchants gathered at the port to [trade] spices and silk. (=Dịch: Nhiều thương nhân đã tụ tập tại cảng để buôn bán gia vị và lụa.)","Investors [trade] shares on the stock exchange every weekday. (=Dịch: Các nhà đầu tư giao dịch cổ phiếu trên sàn chứng khoán vào tất cả các ngày trong tuần.)"],"ukAudio":"/ai_services/tts3/?q=trade&lang=en-GB&ipa=%2Ftre%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=trade&lang=en-US&ipa=%2Ftre%C9%AAd%2F"},{"id":"lv_4_404","topic":"Cultural and Historical Exchange","word":"tragedy","pos":"(n)","ipa":"/ˈtrædʒ.ə.di/","defVi":"bi kịch, thảm kịch","defEn":"an event causing great sadness, suffering, or loss of life","examples":["The sudden collapse of the bridge was a terrible human [tragedy]. (=Dịch: Sự sụp đổ đột ngột của cây cầu là một thảm kịch kinh hoàng đối với con người.)","Emergency services responded quickly to prevent further [tragedy] after the fire. (=Dịch: Các dịch vụ cứu hộ khẩn cấp đã phản ứng nhanh chóng để ngăn ngừa thêm thảm kịch sau vụ hỏa hoạn.)","Shakespeare's play Romeo and Juliet is one of the most famous examples of a [tragedy]. (=Dịch: Vở kịch Romeo và Juliet của Shakespeare là một trong những ví dụ nổi tiếng nhất về một vở bi kịch.)"],"ukAudio":"/ai_services/tts3/?q=tragedy&lang=en-GB&ipa=%2F%CB%88tr%C3%A6d%CA%92.%C9%99.di%2F","usAudio":"/ai_services/tts3/?q=tragedy&lang=en-US&ipa=%2F%CB%88tr%C3%A6d%CA%92.%C9%99.di%2F"},{"id":"lv_4_405","topic":"Cultural and Historical Exchange","word":"transform","pos":"(v)","ipa":"/trænsˈfɔrm/","defVi":"biến đổi, thay đổi hoàn toàn","defEn":"to change the form, appearance, or character of something completely","examples":["Online education has the power to [transform] traditional learning methods. (=Dịch: Giáo dục trực tuyến có khả năng làm thay đổi các phương pháp học tập truyền thống.)","A fresh coat of paint can easily [transform] a dull room into a lively space. (=Dịch: Một lớp sơn mới có thể dễ dàng biến một căn phòng ảm đạm thành một không gian tràn đầy sức sống.)","The new mayor plans to [transform] the abandoned warehouse into a public park. (=Dịch: Thị trưởng mới dự định biến nhà kho bỏ hoang thành một công viên công cộng.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F"},{"id":"lv_4_406","topic":"Cultural and Historical Exchange","word":"translate","pos":"(v)","ipa":"/trænzˈleɪt/","defVi":"dịch, phiên dịch","defEn":"to express words or text in a different language","examples":["She helped [translate] the official documents into Vietnamese. (=Dịch: Cô ấy đã giúp dịch các tài liệu chính thức sang tiếng Việt.)","A good application can [translate] spoken sentences in real time. (=Dịch: Một ứng dụng tốt có thể dịch các câu nói theo thời gian thực.)","His academic success did not [translate] into practical career achievements. (=Dịch: Thành công trong học tập của anh ấy đã không chuyển hóa thành những thành tựu sự nghiệp thực tế.)"],"ukAudio":"/ai_services/tts3/?q=translate&lang=en-GB&ipa=%2Ftr%C3%A6nz%CB%88le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=translate&lang=en-US&ipa=%2Ftr%C3%A6nz%CB%88le%C9%AAt%2F"},{"id":"lv_4_407","topic":"Cultural and Historical Exchange","word":"translation","pos":"(n)","ipa":"/trænsˈleɪ.ʃən/","defVi":"sự dịch thuật; bản dịch","defEn":"the process of changing written or spoken words into another language, or the text produced","examples":["The English [translation] of the French novel became an international bestseller. (=Dịch: Bản dịch tiếng Anh của cuốn tiểu thuyết tiếng Pháp đã trở thành một tác phẩm bán chạy trên toàn thế giới.)","Literal [translation] does not always capture the true meaning of an idiom. (=Dịch: Việc dịch theo nghĩa đen không phải lúc nào cũng truyền tải được ý nghĩa thực sự của một thành ngữ.)","She works in machine [translation] to improve automated language tools. (=Dịch: Cô ấy làm việc trong lĩnh vực dịch máy để cải thiện các công cụ ngôn ngữ tự động.)"],"ukAudio":"/ai_services/tts3/?q=translation&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=translation&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_408","topic":"Cultural and Historical Exchange","word":"transportation","pos":"(n)","ipa":"/ˌtræn.spɚˈteɪ.ʃən/","defVi":"giao thông, phương tiện vận tải, sự vận chuyển","defEn":"a system or method for carrying passengers or goods from one place to another","examples":["Public [transportation] in this city is cheap and reliable. (=Dịch: Phương tiện giao thông công cộng ở thành phố này vừa rẻ lại vừa đáng tin cậy.)","The company arranged the [transportation] of the heavy machinery by train. (=Dịch: Công ty đã sắp xếp việc vận chuyển máy móc hạng nặng bằng tàu hỏa.)","Cycling is an eco-friendly mode of [transportation]. (=Dịch: Đi xe đạp là một phương thức di chuyển thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=transportation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6n.sp%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=transportation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6n.sp%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_409","topic":"Cultural and Historical Exchange","word":"tremendous","pos":"(adj)","ipa":"/trəˈmen.dəs/","defVi":"to lớn, ghê gớm, phi thường","defEn":"extremely large in amount, scale, or intensity","examples":["The project has made [tremendous] progress over the last two weeks. (=Dịch: Dự án đã đạt được tiến bộ to lớn trong hai tuần qua.)","She felt a [tremendous] sense of relief after passing all her final exams. (=Dịch: Cô cảm thấy nhẹ nhõm vô cùng sau khi vượt qua tất cả các kỳ thi cuối kỳ.)","The charity event was a [tremendous] success, raising thousands of dollars. (=Dịch: Sự kiện từ thiện đã thành công rực rỡ, quyên góp được hàng ngàn đô la.)"],"ukAudio":"/ai_services/tts3/?q=tremendous&lang=en-GB&ipa=%2Ftr%C9%99%CB%88men.d%C9%99s%2F","usAudio":"/ai_services/tts3/?q=tremendous&lang=en-US&ipa=%2Ftr%C9%99%CB%88men.d%C9%99s%2F"},{"id":"lv_4_410","topic":"Cultural and Historical Exchange","word":"tribe","pos":"(n)","ipa":"/traɪb/","defVi":"bộ tộc, bộ lạc","defEn":"a group of people of the same race with the same language and customs","examples":["The remote [tribe] has lived in the rainforest for centuries. (=Dịch: Bộ lạc xa xôi này đã sống trong rừng nhiệt đới qua nhiều thế kỷ.)","Anthropologists visited the island to study the local [tribe]. (=Dịch: Các nhà nhân chủng học đã đến thăm hòn đảo để nghiên cứu bộ lạc địa phương.)","Members of the [tribe] gathered to celebrate the annual festival. (=Dịch: Các thành viên của bộ lạc đã tụ họp để ăn mừng lễ hội thường niên.)"],"ukAudio":"/ai_services/tts3/?q=tribe&lang=en-GB&ipa=%2Ftra%C9%AAb%2F","usAudio":"/ai_services/tts3/?q=tribe&lang=en-US&ipa=%2Ftra%C9%AAb%2F"},{"id":"lv_4_411","topic":"Cultural and Historical Exchange","word":"trunk","pos":"(n)","ipa":"/trʌŋk/","defVi":"thân cây; cốp xe ô tô; vòi voi","defEn":"the main thick stem of a tree, or the luggage compartment of a car, or an elephant's long nose","examples":["The thick [trunk] of the ancient oak tree provided shade for the entire garden. (=Dịch: Thân cây to lớn của cây sồi cổ thụ tỏa bóng mát cho toàn bộ khu vườn.)","We packed all the camping gear into the [trunk] of the car before setting off. (=Dịch: Chúng tôi xếp toàn bộ dụng cụ cắm trại vào cốp xe ô tô trước khi khởi hành.)","An elephant uses its powerful [trunk] to drink water and pick up objects. (=Dịch: Con voi sử dụng chiếc vòi đầy sức mạnh của mình để uống nước và nhặt đồ vật.)"],"ukAudio":"/ai_services/tts3/?q=trunk&lang=en-GB&ipa=%2Ftr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=trunk&lang=en-US&ipa=%2Ftr%CA%8C%C5%8Bk%2F"},{"id":"lv_4_412","topic":"Cultural and Historical Exchange","word":"turf","pos":"(n)","ipa":"/tɝːf/","defVi":"lớp đất có cỏ, thảm cỏ tự nhiên/nhân tạo; địa bàn","defEn":"a surface layer of soil with grass growing on it, or an area considered as someone's territory","examples":["The stadium groundskeeper laid new [turf] on the football pitch. (=Dịch: Người chăm sóc sân cỏ của sân vận động đã trải thảm cỏ mới trên sân bóng đá.)","Local street gangs fought fiercely to protect their [turf]. (=Dịch: Các băng đảng đường phố địa phương đã ẩu đả dữ dội để bảo vệ địa bàn của mình.)","Children love running barefoot on the soft green [turf]. (=Dịch: Trẻ em rất thích chạy chân trần trên thảm cỏ xanh mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=turf&lang=en-GB&ipa=%2Ft%C9%9D%CB%90f%2F","usAudio":"/ai_services/tts3/?q=turf&lang=en-US&ipa=%2Ft%C9%9D%CB%90f%2F"},{"id":"lv_4_413","topic":"Cultural and Historical Exchange","word":"twist","pos":"(v)","ipa":"/twɪst/","defVi":"xoắn, vặn, làm méo mó","defEn":"to turn or bend something out of its normal shape or direction","examples":["Be careful not to [twist] your ankle when running on uneven ground. (=Dịch: Hãy cẩn thận kẻo bị trẹo mắt cá chân khi chạy trên địa hình gồ ghề.)","You need to [twist] the bottle cap clockwise to close it securely. (=Dịch: Bạn cần vặn nắp chai theo chiều kim đồng hồ để đóng chặt nó.)","Critics claimed the reporter tried to [twist] the truth to create controversy. (=Dịch: Các nhà phê bình cho rằng phóng viên đã cố tình bóp méo sự thật để tạo tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=twist&lang=en-GB&ipa=%2Ftw%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=twist&lang=en-US&ipa=%2Ftw%C9%AAst%2F"},{"id":"lv_4_414","topic":"Cultural and Historical Exchange","word":"uncover","pos":"(v)","ipa":"/ʌnˈkʌv.ɚ/","defVi":"khám phá, hé lộ, phanh phui","defEn":"to discover or make known something that was previously hidden or secret","examples":["Journalists worked hard to [uncover] the truth behind the political scandal. (=Dịch: Các nhà báo đã nỗ lực làm việc để vạch trần sự thật đằng sau vụ bê bối chính trị.)","Archaeologists managed to [uncover] ancient pottery at the dig site. (=Dịch: Các nhà khảo cổ học đã tìm thấy đồ gốm cổ tại địa điểm khai quật.)","The audit helped the company [uncover] significant financial irregularities. (=Dịch: Cuộc kiểm toán đã giúp công ty phát hiện ra những sai phạm tài chính nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=uncover&lang=en-GB&ipa=%2F%CA%8Cn%CB%88k%CA%8Cv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=uncover&lang=en-US&ipa=%2F%CA%8Cn%CB%88k%CA%8Cv.%C9%9A%2F"},{"id":"lv_4_415","topic":"Cultural and Historical Exchange","word":"understandable","pos":"(adj)","ipa":"/ˌʌn.dɚˈstæn.də.bəl/","defVi":"có thể hiểu được, hợp lý, dễ cảm thông","defEn":"easy to understand or natural and acceptable under the circumstances","examples":["Her anxiety before the job interview was completely [understandable]. (=Dịch: Sự lo lắng của cô ấy trước buổi phỏng vấn xin việc là hoàn toàn có thể hiểu được.)","It is [understandable] that parents worry about the safety of their children online. (=Dịch: Việc các bậc phụ huynh lo lắng về sự an toàn của con cái trên mạng là điều dễ hiểu.)","He made an [understandable] mistake given the lack of clear instructions. (=Dịch: Anh ấy đã mắc phải một sai lầm có thể thông cảm được do thiếu những hướng dẫn rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=understandable&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=understandable&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F"},{"id":"lv_4_416","topic":"Cultural and Historical Exchange","word":"undertake","pos":"(v)","ipa":"/ˌʌn.dərˈteɪk/","defVi":"đảm nhận, thực hiện","defEn":"to commit oneself to and begin a task, project, or responsibility","examples":["The university will [undertake] a comprehensive study on renewable energy. (=Dịch: Trường đại học sẽ tiến hành một nghiên cứu toàn diện về năng lượng tái tạo.)","No one was willing to [undertake] such a risky financial assignment. (=Dịch: Không ai sẵn lòng đảm nhận một nhiệm vụ tài chính đầy rủi ro như vậy.)","The company agreed to [undertake] full responsibility for the construction delays. (=Dịch: Công ty đã đồng ý nhận toàn bộ trách nhiệm về sự chậm trễ trong việc thi công.)"],"ukAudio":"/ai_services/tts3/?q=undertake&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=undertake&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88te%C9%AAk%2F"},{"id":"lv_4_417","topic":"Cultural and Historical Exchange","word":"unemployment","pos":"(n)","ipa":"/ˌʌn.ɪmˈplɔɪ.mənt/","defVi":"sự thất nghiệp, nạn thất nghiệp","defEn":"the state of not having a job, or the number of people without work","examples":["The government is trying to reduce [unemployment] by creating new job programs. (=Dịch: Chính phủ đang cố gắng giảm tình trạng thất nghiệp bằng cách tạo ra các chương trình việc làm mới.)","High [unemployment] among young graduates is a major economic issue. (=Dịch: Tỷ lệ thất nghiệp cao ở những sinh viên trẻ mới tốt nghiệp là một vấn đề kinh tế lớn.)","Many workers struggled to pay their bills during periods of prolonged [unemployment]. (=Dịch: Nhiều người lao động đã phải chật vật chi trả các hóa đơn trong những giai đoạn thất nghiệp kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=unemployment&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AA.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=unemployment&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AA.m%C9%99nt%2F"},{"id":"lv_4_418","topic":"Cultural and Historical Exchange","word":"universal","pos":"(adj)","ipa":"/ˌjuː.nəˈvɝː.səl/","defVi":"phổ quát, toàn cầu, phổ biến","defEn":"existing everywhere or involving everyone in the world","examples":["Music is often described as a [universal] language that connects all cultures. (=Dịch: Âm nhạc thường được mô tả là một ngôn ngữ phổ quát kết nối mọi nền văn hóa.)","Access to clean water should be recognized as a [universal] human right. (=Dịch: Việc tiếp cận nước sạch nên được công nhận là một quyền phổ quát của con người.)","The new policy received [universal] approval from the entire committee. (=Dịch: Chính sách mới đã nhận được sự đồng thuận tuyệt đối từ toàn bộ ủy ban.)"],"ukAudio":"/ai_services/tts3/?q=universal&lang=en-GB&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=universal&lang=en-US&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F"},{"id":"lv_4_419","topic":"Cultural and Historical Exchange","word":"unrealistic","pos":"(adj)","ipa":"/ˌʌn.ri.əˈlɪs.tɪk/","defVi":"phi thực tế, không thực tế","defEn":"not sensible or based on reality; impossible to achieve","examples":["Setting an [unrealistic] deadline will only cause unnecessary stress for the team. (=Dịch: Việc đặt ra một thời hạn không thực tế sẽ chỉ gây ra căng thẳng không cần thiết cho cả nhóm.)","Expecting to master a new language in a month is totally [unrealistic]. (=Dịch: Kỳ vọng thành thạo một ngôn ngữ mới trong một tháng là hoàn toàn phi thực tế.)","The movie was criticized for its [unrealistic] plot and weak characters. (=Dịch: Bộ phim bị chỉ trích vì cốt truyện phi thực tế và các nhân vật mờ nhạt.)"],"ukAudio":"/ai_services/tts3/?q=unrealistic&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.ri.%C9%99%CB%88l%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=unrealistic&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.ri.%C9%99%CB%88l%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_420","topic":"Cultural and Historical Exchange","word":"vast","pos":"(adj)","ipa":"/væst/","defVi":"rộng lớn, bao la","defEn":"extremely big in size, amount, or extent","examples":["The Sahara is a [vast] desert stretching across northern Africa. (=Dịch: Sahara là một sa mạc rộng lớn trải dài khắp Bắc Phi.)","A [vast] majority of employees supported the new policy. (=Dịch: Phần lớn đại đa số nhân viên đều ủng hộ chính sách mới.)","The project will require a [vast] amount of financial resources. (=Dịch: Dự án sẽ đòi hỏi một lượng tài chính khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=vast&lang=en-GB&ipa=%2Fv%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=vast&lang=en-US&ipa=%2Fv%C3%A6st%2F"},{"id":"lv_4_421","topic":"Cultural and Historical Exchange","word":"venue","pos":"(n)","ipa":"/ˈvɛn.juː/","defVi":"địa điểm tổ chức (sự kiện, hội nghị, biểu diễn)","defEn":"the place where an event or activity takes place","examples":["The hotel is an ideal [venue] for international conferences and business meetings. (=Dịch: Khách sạn là một địa điểm lý tưởng cho các hội nghị quốc tế và các cuộc họp kinh doanh.)","Organizers had to change the concert [venue] due to unexpected weather conditions. (=Dịch: Ban tổ chức đã phải thay đổi địa điểm tổ chức buổi hòa nhạc do điều kiện thời tiết bất ngờ.)","The stadium was chosen as the main [venue] for the upcoming sports tournament. (=Dịch: Sân vận động đã được chọn làm địa điểm chính cho giải đấu thể thao sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=venue&lang=en-GB&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F","usAudio":"/ai_services/tts3/?q=venue&lang=en-US&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F"},{"id":"lv_4_422","topic":"Cultural and Historical Exchange","word":"version","pos":"(n)","ipa":"/ˈvɝː.ʒən/","defVi":"phiên bản, bản phát hành, lời kể","defEn":"a particular form of something that differs slightly from other forms of it","examples":["The developers released an updated [version] of the software to fix minor security bugs. (=Dịch: Các nhà phát triển đã phát hành một phiên bản cập nhật của phần mềm để sửa các lỗi bảo mật nhỏ.)","Her [version] of the incident differed completely from what the other witnesses reported. (=Dịch: Lời kể của cô ấy về vụ việc hoàn toàn khác so với những gì các nhân chứng khác đã báo cáo.)","I prefer reading the original [version] of the novel rather than its translated adaptation. (=Dịch: Tôi thích đọc phiên bản gốc của cuốn tiểu thuyết hơn là bản chuyển thể đã được dịch thuật.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_4_423","topic":"Cultural and Historical Exchange","word":"visible","pos":"(adj)","ipa":"/ˈvɪz.ə.bəl/","defVi":"có thể nhìn thấy được, rõ ràng","defEn":"able to be seen or easily noticed","examples":["The stars were clearly [visible] in the clear night sky. (=Dịch: Những ngôi sao có thể nhìn thấy rõ ràng trên bầu trời đêm quang đãng.)","There has been a [visible] improvement in her spoken English skills. (=Dịch: Đã có sự tiến bộ rõ rệt trong kỹ năng nói tiếng Anh của cô ấy.)","Keep the emergency exit sign [visible] at all times for safety. (=Dịch: Hãy luôn giữ cho biển báo lối thoát hiểm dễ nhìn thấy để đảm bảo an toàn.)"],"ukAudio":"/ai_services/tts3/?q=visible&lang=en-GB&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=visible&lang=en-US&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F"},{"id":"lv_4_424","topic":"Cultural and Historical Exchange","word":"vocabulary","pos":"(n)","ipa":"/vəˈkæb.jəˌlɛr.i/","defVi":"từ vựng, vốn từ","defEn":"all the words known and used by a particular person or in a specific language","examples":["Reading English novels regularly helps expand your active [vocabulary]. (=Dịch: Đọc tiểu thuyết tiếng Anh thường xuyên giúp mở rộng vốn từ vựng chủ động của bạn.)","The exam tests both grammar and advanced academic [vocabulary]. (=Dịch: Kỳ thi kiểm tra cả ngữ pháp và vốn từ vựng học thuật nâng cao.)","Children rapidly acquire new [vocabulary] by listening to stories and conversations. (=Dịch: Trẻ em tiếp thu từ vựng mới rất nhanh bằng cách lắng nghe các câu chuyện và cuộc trò chuyện.)"],"ukAudio":"/ai_services/tts3/?q=vocabulary&lang=en-GB&ipa=%2Fv%C9%99%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=vocabulary&lang=en-US&ipa=%2Fv%C9%99%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F"},{"id":"lv_4_425","topic":"Cultural and Historical Exchange","word":"volcanic","pos":"(adj)","ipa":"/vɑːlˈkæn.ɪk/","defVi":"thuộc về núi lửa, do núi lửa tạo ra","defEn":"caused by, connected with, or produced by a volcano","examples":["The island is covered in fertile [volcanic] soil that is great for farming. (=Dịch: Hòn đảo được bao phủ bởi lớp đất núi lửa màu mỡ rất thích hợp cho việc trồng trọt.)","Scientists observed increased [volcanic] activity in the mountain range. (=Dịch: Các nhà khoa học đã quan sát thấy hoạt động núi lửa gia tăng ở dãy núi này.)","The beach is famous for its unique [volcanic] black sand. (=Dịch: Bãi biển này nổi tiếng với bãi cát đen núi lửa độc đáo.)"],"ukAudio":"/ai_services/tts3/?q=volcanic&lang=en-GB&ipa=%2Fv%C9%91%CB%90l%CB%88k%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=volcanic&lang=en-US&ipa=%2Fv%C9%91%CB%90l%CB%88k%C3%A6n.%C9%AAk%2F"},{"id":"lv_4_426","topic":"Cultural and Historical Exchange","word":"voyage","pos":"(n)","ipa":"/ˈvɔɪ.ɪdʒ/","defVi":"chuyến đi dài (thường bằng đường biển hoặc vũ trụ)","defEn":"a long journey, especially by sea or in space","examples":["The Titanic sank on its maiden [voyage] across the Atlantic. (=Dịch: Tàu Titanic đã bị chìm trong chuyến hải trình đầu tiên băng qua Đại Tây Dương.)","Scientists are planning a historic [voyage] to Mars. (=Dịch: Các nhà khoa học đang lên kế hoạch cho một chuyến du hành mang tính lịch sử tới Sao Hỏa.)","The ancient sailors kept a detailed diary during their long [voyage]. (=Dịch: Các thủy thủ thời xưa đã ghi chép nhật ký chi tiết trong suốt chuyến hải trình dài ngày của họ.)"],"ukAudio":"/ai_services/tts3/?q=voyage&lang=en-GB&ipa=%2F%CB%88v%C9%94%C9%AA.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=voyage&lang=en-US&ipa=%2F%CB%88v%C9%94%C9%AA.%C9%AAd%CA%92%2F"},{"id":"lv_4_427","topic":"Cultural and Historical Exchange","word":"wealth","pos":"(n)","ipa":"/welθ/","defVi":"sự giàu có, của cải; sự phong phú","defEn":"a large amount of money, property, or valuable possessions; a large quantity of something","examples":["He used his considerable [wealth] to establish educational charities worldwide. (=Dịch: Ông đã sử dụng khối tài sản đáng kể của mình để thành lập các tổ chức từ thiện giáo dục trên toàn thế giới.)","The internet provides a [wealth] of information on virtually every topic. (=Dịch: Internet cung cấp một lượng thông tin vô cùng phong phú về hầu như mọi chủ đề.)","Good health is considered greater than material [wealth] by many cultures. (=Dịch: Sức khỏe tốt được nhiều nền văn hóa coi trọng hơn của cải vật chất.)"],"ukAudio":"/ai_services/tts3/?q=wealth&lang=en-GB&ipa=%2Fwel%CE%B8%2F","usAudio":"/ai_services/tts3/?q=wealth&lang=en-US&ipa=%2Fwel%CE%B8%2F"},{"id":"lv_4_428","topic":"Cultural and Historical Exchange","word":"wearer","pos":"(n)","ipa":"/ˈwɛr.ɚ/","defVi":"người mặc, người mang, người đeo (trang phục, phụ kiện)","defEn":"a person who wears a particular piece of clothing, accessory, or device","examples":["The helmet is designed to protect the [wearer] from head injuries. (=Dịch: Mũ bảo hiểm được thiết kế để bảo vệ người đội khỏi các chấn thương đầu.)","Smart watches can track the vital health signs of the [wearer] in real time. (=Dịch: Đồng hồ thông minh có thể theo dõi các chỉ số sinh tồn của người đeo theo thời gian thực.)","This lightweight jacket keeps the [wearer] warm without adding bulky weight. (=Dịch: Chiếc áo khoác nhẹ này giữ ấm cho người mặc mà không gây nặng nề hay cồng kềnh.)"],"ukAudio":"/ai_services/tts3/?q=wearer&lang=en-GB&ipa=%2F%CB%88w%C9%9Br.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=wearer&lang=en-US&ipa=%2F%CB%88w%C9%9Br.%C9%9A%2F"},{"id":"lv_4_429","topic":"Cultural and Historical Exchange","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪd.spred/","defVi":"lan rộng, phổ biến, diện rộng","defEn":"existing or happening in many places or among many people","examples":["The government is trying to stop the [widespread] use of illegal chemicals. (=Dịch: Chính phủ đang nỗ lực ngăn chặn việc sử dụng rộng rãi các hóa chất bất hợp pháp.)","Heavy storms caused [widespread] damage across the northern provinces. (=Dịch: Những trận bão lớn đã gây ra thiệt hại trên diện rộng khắp các tỉnh phía bắc.)","There is [widespread] agreement that renewable energy should be expanded. (=Dịch: Có sự đồng thuận rộng rãi rằng năng lượng tái tạo nên được mở rộng.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd.spred%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd.spred%2F"},{"id":"lv_4_430","topic":"Cultural and Historical Exchange","word":"winding","pos":"(adj)","ipa":"/ˈwaɪn.dɪŋ/","defVi":"uốn khúc, quanh co, ngoằn ngoèo","defEn":"having a lot of curves, bends, or turns rather than being straight","examples":["They drove slowly along the narrow, [winding] mountain road. (=Dịch: Họ lái xe chầm chậm dọc theo con đường núi hẹp và quanh co.)","The river follows a [winding] path through the valley. (=Dịch: Dòng sông uốn lượn theo một lộ trình quanh co qua thung lũng.)","A [winding] staircase led up to the top of the tower. (=Dịch: Một cầu thang xoắn ốc dẫn lên đỉnh tháp.)"],"ukAudio":"/ai_services/tts3/?q=winding&lang=en-GB&ipa=%2F%CB%88wa%C9%AAn.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=winding&lang=en-US&ipa=%2F%CB%88wa%C9%AAn.d%C9%AA%C5%8B%2F"},{"id":"lv_4_431","topic":"Cultural and Historical Exchange","word":"wing","pos":"(n)","ipa":"/wɪŋ/","defVi":"cánh (chim, máy bay)","defEn":"one of the parts of a bird, insect, or airplane used for flying","examples":["The injured bird could not fly because of a broken [wing]. (=Dịch: Con chim bị thương không thể bay vì bị gãy cánh.)","Passengers sitting near the plane's [wing] had an obstructed view. (=Dịch: Hành khách ngồi gần cánh máy bay bị hạn chế tầm nhìn.)","Butterflies use their colorful [wing] patterns to frighten predators. (=Dịch: Bướm sử dụng các hoa văn rực rỡ trên cánh để đe dọa những kẻ săn mồi.)"],"ukAudio":"/ai_services/tts3/?q=wing&lang=en-GB&ipa=%2Fw%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=wing&lang=en-US&ipa=%2Fw%C9%AA%C5%8B%2F"},{"id":"lv_4_432","topic":"Cultural and Historical Exchange","word":"wise","pos":"(adj)","ipa":"/waɪz/","defVi":"khôn ngoan, sáng suốt, thông thái","defEn":"having or showing good judgment, experience, and knowledge","examples":["It is always [wise] to save some money for unexpected emergencies. (=Dịch: Tiết kiệm một khoản tiền cho những trường hợp khẩn cấp bất ngờ luôn là điều khôn ngoan.)","She sought advice from a [wise] mentor before making a career change. (=Dịch: Cô đã tìm kiếm lời khuyên từ một người cố vấn thông thái trước khi chuyển đổi nghề nghiệp.)","Investing early in education is a very [wise] long-term decision. (=Dịch: Đầu tư sớm vào giáo dục là một quyết định dài hạn rất sáng suốt.)"],"ukAudio":"/ai_services/tts3/?q=wise&lang=en-GB&ipa=%2Fwa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=wise&lang=en-US&ipa=%2Fwa%C9%AAz%2F"},{"id":"lv_4_433","topic":"Cultural and Historical Exchange","word":"wool","pos":"(n)","ipa":"/wʊl/","defVi":"len, lông cừu","defEn":"the soft, thick hair that grows on the bodies of sheep and some other animals","examples":["This sweater is knitted from pure merino [wool]. (=Dịch: Chiếc áo len này được đan từ len merino nguyên chất.)","Australia is one of the world's leading exporters of raw [wool]. (=Dịch: Úc là một trong những quốc gia xuất khẩu len thô hàng đầu thế giới.)","She prefers wearing [wool] socks to keep her feet warm in winter. (=Dịch: Cô ấy thích đi tất len để giữ ấm chân vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=wool&lang=en-GB&ipa=%2Fw%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=wool&lang=en-US&ipa=%2Fw%CA%8Al%2F"},{"id":"lv_4_434","topic":"Cultural and Historical Exchange","word":"yarn","pos":"(n)","ipa":"/jɑːrn/","defVi":"sợi len, sợi dệt; câu chuyện dài","defEn":"spun thread used for knitting, weaving, or sewing; or a long, entertaining story","examples":["She bought several balls of soft wool [yarn] to knit a winter scarf. (=Dịch: Cô ấy đã mua vài cuộn len mềm để đan một chiếc khăn quàng cổ mùa đông.)","The old sailor loved to spin a fascinating [yarn] about his sea adventures. (=Dịch: Người thủy thủ già rất thích kể một câu chuyện ly kỳ về những chuyến phiêu lưu trên biển của mình.)","Traditional weavers dye the cotton [yarn] using natural plant extracts. (=Dịch: Những người thợ dệt truyền thống nhuộm sợi bông bằng chiết xuất thực vật tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=yarn&lang=en-GB&ipa=%2Fj%C9%91%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=yarn&lang=en-US&ipa=%2Fj%C9%91%CB%90rn%2F"},{"id":"lv_5_0","topic":"Nature and Environmental Protection","word":"absorb","pos":"(v)","ipa":"/əbˈzɔːrb/","defVi":"hấp thụ, thấm hút","defEn":"to take in liquid, gas, heat, or energy gradually from the space around","examples":["Plants [absorb] carbon dioxide and release oxygen during photosynthesis. (=Dịch: Thực vật hấp thụ khí cacbonic và giải phóng khí oxy trong quá trình quang hợp.)","A dry sponge will quickly [absorb] any spilled water on the table. (=Dịch: Một miếng bọt biển khô sẽ nhanh chóng hút sạch nước tràn trên bàn.)","Dark surfaces tend to [absorb] more heat from sunlight than light-colored ones. (=Dịch: Các bề mặt sẫm màu có xu hướng hấp thụ nhiều nhiệt từ ánh nắng mặt trời hơn các bề mặt sáng màu.)"],"ukAudio":"/ai_services/tts3/?q=absorb&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=absorb&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F"},{"id":"lv_5_1","topic":"Nature and Environmental Protection","word":"accidental","pos":"(adj)","ipa":"/ˌæk.səˈden.t̬əl/","defVi":"tình cờ, ngẫu nhiên, bất ngờ","defEn":"happening by chance rather than by intention or design","examples":["The fire was determined to be purely [accidental] and caused by an electrical fault. (=Dịch: Vụ hỏa hoạn được xác định là hoàn toàn do ngẫu nhiên và bắt nguồn từ sự cố điện.)","The discovery of penicillin was an [accidental] breakthrough in modern medicine. (=Dịch: Việc phát hiện ra penicillin là một bước đột phá tình cờ trong y học hiện đại.)","Please forgive my [accidental] deletion of your important computer files. (=Dịch: Xin hãy tha thứ cho việc tôi vô tình xóa các tệp máy tính quan trọng của bạn.)"],"ukAudio":"/ai_services/tts3/?q=accidental&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88den.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=accidental&lang=en-US&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88den.t%CC%AC%C9%99l%2F"},{"id":"lv_5_2","topic":"Nature and Environmental Protection","word":"accidentally","pos":"(adv)","ipa":"/ˌæk.səˈdɛn.t̬ə.li/","defVi":"tình cờ, vô tình","defEn":"by chance or without intention","examples":["I [accidentally] deleted the file from my laptop. (=Dịch: Tôi đã vô tình xóa tập tin đó khỏi máy tính xách tay của mình.)","She [accidentally] bumped into an old friend at the supermarket. (=Dịch: Cô ấy tình cờ chạm mặt một người bạn cũ tại siêu thị.)","The glass fell and broke when he [accidentally] knocked the table. (=Dịch: Chiếc ly rơi và vỡ khi anh ấy vô tình va vào bàn.)"],"ukAudio":"/ai_services/tts3/?q=accidentally&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88d%C9%9Bn.t%CC%AC%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=accidentally&lang=en-US&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88d%C9%9Bn.t%CC%AC%C9%99.li%2F"},{"id":"lv_5_3","topic":"Nature and Environmental Protection","word":"accurately","pos":"(adv)","ipa":"/ˈæk.jɚ.ət.li/","defVi":"một cách chính xác","defEn":"in a way that is correct, exact, and without any mistakes","examples":["The weather forecast [accurately] predicted the heavy rainfall. (=Dịch: Dự báo thời tiết đã dự đoán chính xác lượng mưa lớn.)","It is difficult to [accurately] calculate the total cost of the project. (=Dịch: Rất khó để tính toán chính xác tổng chi phí của dự án.)","Sensors were installed to [accurately] measure temperature changes. (=Dịch: Các cảm biến đã được lắp đặt để đo lường chính xác sự thay đổi nhiệt độ.)"],"ukAudio":"/ai_services/tts3/?q=accurately&lang=en-GB&ipa=%2F%CB%88%C3%A6k.j%C9%9A.%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=accurately&lang=en-US&ipa=%2F%CB%88%C3%A6k.j%C9%9A.%C9%99t.li%2F"},{"id":"lv_5_4","topic":"Nature and Environmental Protection","word":"adaptation","pos":"(n)","ipa":"/ˌæd.æpˈteɪ.ʃən/","defVi":"Sự thích nghi; tác phẩm chuyển thể.","defEn":"A change that helps an organism survive, or a modified version of a book or play.","examples":["Thick fur is an evolutionary [adaptation] that helps polar bears survive the cold. (=Dịch: Bộ lông dày là một sự thích nghi tiến hóa giúp gấu bắc cực sống sót qua giá lạnh.)","The movie is a modern [adaptation] of a classic novel. (=Dịch: Bộ phim là một tác phẩm chuyển thể hiện đại từ một cuốn tiểu thuyết kinh điển.)","Successful business [adaptation] is essential in a changing market. (=Dịch: Sự thích nghi kinh doanh thành công là điều cần thiết trong một thị trường đang thay đổi.)"],"ukAudio":"/ai_services/tts3/?q=adaptation&lang=en-GB&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=adaptation&lang=en-US&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_5","topic":"Nature and Environmental Protection","word":"additive","pos":"(n)","ipa":"/ˈæd.ə.tɪv/","defVi":"Chất phụ gia.","defEn":"A substance added to something in small amounts to improve or preserve it.","examples":["Some people try to avoid buying foods that contain any artificial [additive]. (=Dịch: Một số người cố gắng tránh mua các loại thực phẩm có chứa bất kỳ chất phụ gia nhân tạo nào.)","The mechanic put a special [additive] into the engine oil to improve performance. (=Dịch: Người thợ máy đã cho một chất phụ gia đặc biệt vào dầu động cơ để cải thiện hiệu suất.)","Salt has been used as a natural food [additive] for centuries. (=Dịch: Muối đã được sử dụng như một chất phụ gia thực phẩm tự nhiên trong nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=additive&lang=en-GB&ipa=%2F%CB%88%C3%A6d.%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=additive&lang=en-US&ipa=%2F%CB%88%C3%A6d.%C9%99.t%C9%AAv%2F"},{"id":"lv_5_6","topic":"Nature and Environmental Protection","word":"administrative","pos":"(adj)","ipa":"/ədˈmɪn.ə.streɪ.tɪv/","defVi":"Thuộc về hành chính, quản trị.","defEn":"Relating to the management and organization of an institution or business.","examples":["She handles all the [administrative] tasks in the school office. (=Dịch: Cô ấy xử lý tất cả các công việc hành chính trong văn phòng trường học.)","The company reorganized its [administrative] structure to reduce costs. (=Dịch: Công ty đã tái cấu trúc bộ máy hành chính để cắt giảm chi phí.)","He spent hours completing the necessary [administrative] paperwork. (=Dịch: Anh ấy đã dành hàng giờ để hoàn thành các thủ tục giấy tờ hành chính cần thiết.)"],"ukAudio":"/ai_services/tts3/?q=administrative&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=administrative&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%C9%AAv%2F"},{"id":"lv_5_7","topic":"Nature and Environmental Protection","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"nhận nuôi hoặc áp dụng, tiếp nhận","defEn":"to legally take another person's child into your own family, or to start using a particular idea or method","examples":["The local council decided to [adopt] a new policy on recycling. (=Dịch: Hội đồng địa phương đã quyết định áp dụng một chính sách mới về tái chế.)","After years of waiting, the couple was finally able to [adopt] a child. (=Dịch: Sau nhiều năm chờ đợi, cặp vợ chồng cuối cùng cũng có thể nhận nuôi một đứa trẻ.)","Many schools now [adopt] modern technology in daily teaching. (=Dịch: Nhiều trường học hiện nay áp dụng công nghệ hiện đại vào việc giảng dạy hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_5_8","topic":"Nature and Environmental Protection","word":"african","pos":"(adj)","ipa":"/ˈæf.rɪ.kən/","defVi":"Thuộc về châu Phi, người châu Phi.","defEn":"Belonging or relating to Africa, its people, or its culture.","examples":["She enjoys listening to traditional [african] music and drumming. (=Dịch: Cô ấy thích nghe nhạc truyền thống và tiếng trống của châu Phi.)","The safari tour offered a rare chance to see [african] wildlife up close. (=Dịch: Chuyến tham quan dã ngoại mang lại cơ hội hiếm có để ngắm nhìn động vật hoang dã châu Phi ở cự ly gần.)","Many [african] nations are investing heavily in renewable energy. (=Dịch: Nhiều quốc gia châu Phi đang đầu tư mạnh mẽ vào năng lượng tái tạo.)"],"ukAudio":"/ai_services/tts3/?q=african&lang=en-GB&ipa=%2F%CB%88%C3%A6f.r%C9%AA.k%C9%99n%2F","usAudio":"/ai_services/tts3/?q=african&lang=en-US&ipa=%2F%CB%88%C3%A6f.r%C9%AA.k%C9%99n%2F"},{"id":"lv_5_9","topic":"Nature and Environmental Protection","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"tham vọng, đầy hoài bão","defEn":"having a strong desire for success, power, or achievement","examples":["The government launched an [ambitious] project to improve public transport. (=Dịch: Chính phủ đã phát động một dự án đầy tham vọng nhằm cải thiện giao thông công cộng.)","She is an [ambitious] young lawyer who hopes to make partner soon. (=Dịch: Cô ấy là một luật sư trẻ đầy tham vọng và hy vọng sớm trở thành thành viên góp vốn.)","His plans for the new business seemed overly [ambitious] given the budget. (=Dịch: Kế hoạch kinh doanh mới của anh ấy có vẻ quá tham vọng xét về ngân sách hiện có.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_5_10","topic":"Nature and Environmental Protection","word":"angle","pos":"(n)","ipa":"/ˈæŋ.ɡəl/","defVi":"góc, góc độ, quan điểm","defEn":"the space between two intersecting lines, or a particular way of looking at something","examples":["The photographer took the picture from a low [angle] to make the building look taller. (=Dịch: Nhiếp ảnh gia chụp bức ảnh từ góc thấp để làm cho tòa nhà trông cao hơn.)","We need to consider this problem from every possible [angle]. (=Dịch: Chúng ta cần xem xét vấn đề này từ mọi góc độ có thể.)","The journalist tried to find a fresh [angle] for her news story. (=Dịch: Nữ nhà báo đã cố gắng tìm một góc nhìn mới cho bài báo của mình.)"],"ukAudio":"/ai_services/tts3/?q=angle&lang=en-GB&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=angle&lang=en-US&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F"},{"id":"lv_5_11","topic":"Nature and Environmental Protection","word":"antarctic","pos":"(adj)","ipa":"/ænˈtɑːrk.tɪk/","defVi":"thuộc Nam Cực","defEn":"relating to the region around the South Pole","examples":["Scientists are studying climate change through [antarctic] ice cores. (=Dịch: Các nhà khoa học đang nghiên cứu biến đổi khí hậu thông qua các lõi băng Nam Cực.)","Penguins have adapted well to the harsh [antarctic] environment. (=Dịch: Chim cánh cụt đã thích nghi tốt với môi trường Nam Cực khắc nghiệt.)","The research team organized an [antarctic] expedition last summer. (=Dịch: Đội nghiên cứu đã tổ chức một chuyến thám hiểm Nam Cực vào mùa hè năm ngoái.)"],"ukAudio":"/ai_services/tts3/?q=antarctic&lang=en-GB&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=antarctic&lang=en-US&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AAk%2F"},{"id":"lv_5_12","topic":"Nature and Environmental Protection","word":"antarctica","pos":"(n)","ipa":"/ænˈtɑːrk.tɪ.kə/","defVi":"Châu Nam Cực","defEn":"the continent surrounding the South Pole, almost entirely covered with ice","examples":["Scientific research teams travel to [antarctica] to study climate change. (=Dịch: Các đội nghiên cứu khoa học tới Châu Nam Cực để nghiên cứu về biến đổi khí hậu.)","Extreme weather conditions make [antarctica] one of the most inhospitable places on Earth. (=Dịch: Điều kiện thời tiết khắc nghiệt khiến Châu Nam Cực trở thành một trong những nơi khó sống nhất trên Trái Đất.)","Emperor penguins are well adapted to survive the freezing winters of [antarctica]. (=Dịch: Chim cánh cụt hoàng đế thích nghi rất tốt để sống sót qua mùa đông băng giá ở Châu Nam Cực.)"],"ukAudio":"/ai_services/tts3/?q=antarctica&lang=en-GB&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AA.k%C9%99%2F","usAudio":"/ai_services/tts3/?q=antarctica&lang=en-US&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AA.k%C9%99%2F"},{"id":"lv_5_13","topic":"Nature and Environmental Protection","word":"archaeology","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒi/","defVi":"Khảo cổ học","defEn":"The study of human history and prehistory through the excavation of sites and the analysis of artifacts","examples":["She decided to study [archaeology] because of her fascination with ancient Egypt. (=Dịch: Cô ấy quyết định học khảo cổ học vì niềm đam mê với Ai Cập cổ đại.)","Recent advances in [archaeology] have helped discover hidden ruins beneath the jungle. (=Dịch: Những tiến bộ gần đây trong khảo cổ học đã giúp phát hiện ra các tàn tích ẩn sâu dưới rừng rậm.)","The museum has an extensive collection of artifacts related to biblical [archaeology]. (=Dịch: Bảo tàng có một bộ sưu tập phong phú các hiện vật liên quan đến khảo cổ học kinh thánh.)"],"ukAudio":"/ai_services/tts3/?q=archaeology&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=archaeology&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_5_14","topic":"Nature and Environmental Protection","word":"arctic","pos":"(adj)","ipa":"/ˈɑːrk.tɪk/","defVi":"(thuộc) Bắc Cực; giá rét, cực lạnh","defEn":"relating to the regions around the North Pole; extremely cold","examples":["Many species have adapted uniquely to the harsh conditions of the [arctic] environment. (=Dịch: Nhiều loài đã thích nghi độc đáo với các điều kiện khắc nghiệt của môi trường Bắc Cực.)","The expedition team had to endure fierce [arctic] winds and freezing temperatures. (=Dịch: Đội thám hiểm đã phải chịu đựng những cơn gió Bắc Cực dữ dội và nhiệt độ đóng băng.)","Melting [arctic] ice is one of the most alarming indicators of climate change. (=Dịch: Băng Bắc Cực tan chảy là một trong những chỉ báo đáng báo động nhất về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=arctic&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90rk.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=arctic&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90rk.t%C9%AAk%2F"},{"id":"lv_5_15","topic":"Nature and Environmental Protection","word":"ash","pos":"(n)","ipa":"/æʃ/","defVi":"tro, tàn tro","defEn":"the soft grey powder that remains after something has burned","examples":["Volcanic [ash] covered the surrounding villages after the eruption. (=Dịch: Tro núi lửa đã bao phủ các ngôi làng xung quanh sau vụ phun trào.)","He tapped the cigarette [ash] into the tray on the table. (=Dịch: Anh ấy gõ tàn thuốc lá vào chiếc gạt tàn trên bàn.)","The forest fire left behind nothing but piles of black [ash]. (=Dịch: Vụ cháy rừng không để lại gì ngoài những đống tro đen.)"],"ukAudio":"/ai_services/tts3/?q=ash&lang=en-GB&ipa=%2F%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=ash&lang=en-US&ipa=%2F%C3%A6%CA%83%2F"},{"id":"lv_5_16","topic":"Nature and Environmental Protection","word":"ashore","pos":"(adv)","ipa":"/əˈʃɔːr/","defVi":"lên bờ, vào bờ","defEn":"towards or onto the land from an area of water","examples":["The rescued sailors finally stepped [ashore] after three days lost at sea. (=Dịch: Những thủy thủ được giải cứu cuối cùng đã bước lên bờ sau ba ngày lạc trên biển.)","Strong waves washed several unusual sea creatures [ashore] overnight. (=Dịch: Những con sóng mạnh đã cuốn trôi vài sinh vật biển kỳ lạ vào bờ qua đêm.)","The shipwreck survivors managed to swim [ashore] before darkness fell. (=Dịch: Những người sống sót sau vụ đắm tàu đã cố gắng bơi vào bờ trước khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=ashore&lang=en-GB&ipa=%2F%C9%99%CB%88%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=ashore&lang=en-US&ipa=%2F%C9%99%CB%88%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_17","topic":"Nature and Environmental Protection","word":"asian","pos":"(adj)","ipa":"/ˈeɪ.ʒən/","defVi":"thuộc châu Á, người châu Á","defEn":"belonging to or relating to Asia or its people","examples":["Many [asian] countries have experienced rapid economic growth in recent decades. (=Dịch: Nhiều quốc gia châu Á đã trải qua sự tăng trưởng kinh tế nhanh chóng trong những thập kỷ gần đây.)","She enjoys cooking various types of traditional [asian] cuisine. (=Dịch: Cô ấy thích nấu nhiều loại ẩm thực truyền thống châu Á.)","The university offers courses on modern [asian] history and literature. (=Dịch: Trường đại học cung cấp các khóa học về lịch sử và văn học châu Á hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=asian&lang=en-GB&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=asian&lang=en-US&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99n%2F"},{"id":"lv_5_18","topic":"Nature and Environmental Protection","word":"asiatic","pos":"(adj)","ipa":"/ˌeɪ.ʒiˈæt̬.ɪk/","defVi":"thuộc châu Á (thường dùng trong sinh học, lịch sử)","defEn":"of or relating to Asia, especially used in biological or historical contexts","examples":["The [asiatic] black bear is native to the forests of East Asia. (=Dịch: Gấu đen châu Á có nguồn gốc từ các khu rừng ở Đông Á.)","Several rare [asiatic] plant species are preserved in the botanical garden. (=Dịch: Một số loài thực vật châu Á quý hiếm được bảo tồn trong vườn thực vật.)","Scholars discussed the ancient [asiatic] trade routes during the symposium. (=Dịch: Các học giả đã thảo luận về các tuyến đường thương mại cổ đại ở châu Á trong buổi hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=asiatic&lang=en-GB&ipa=%2F%CB%8Ce%C9%AA.%CA%92i%CB%88%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=asiatic&lang=en-US&ipa=%2F%CB%8Ce%C9%AA.%CA%92i%CB%88%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_5_19","topic":"Nature and Environmental Protection","word":"assess","pos":"(v)","ipa":"/əˈsɛs/","defVi":"đánh giá, thẩm định","defEn":"to judge or evaluate the quality, value, or importance of something","examples":["The teacher will [assess] the students based on their final presentations. (=Dịch: Giáo viên sẽ đánh giá học sinh dựa trên bài thuyết trình cuối kỳ của họ.)","Insurance agents arrived to [assess] the flood damage to the property. (=Dịch: Các nhân viên bảo hiểm đã đến để đánh giá thiệt hại do lũ lụt gây ra cho tài sản.)","We need to carefully [assess] the potential risks before launching the product. (=Dịch: Chúng ta cần đánh giá cẩn thận các rủi ro tiềm ẩn trước khi tung sản phẩm ra thị trường.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F"},{"id":"lv_5_20","topic":"Nature and Environmental Protection","word":"assumption","pos":"(n)","ipa":"/əˈsʌmp.ʃən/","defVi":"giả định, sự cho là đúng","defEn":"something that you accept as true without having proof","examples":["His conclusion was based on the false [assumption] that prices would drop. (=Dịch: Kết luận của anh ấy dựa trên giả định sai lầm rằng giá cả sẽ giảm.)","It is a common [assumption] that older people are less adaptable to technology. (=Dịch: Có một giả định phổ biến rằng người lớn tuổi ít thích nghi với công nghệ hơn.)","We are working on the [assumption] that the project will receive funding. (=Dịch: Chúng tôi đang làm việc dựa trên giả định rằng dự án sẽ nhận được tài trợ.)"],"ukAudio":"/ai_services/tts3/?q=assumption&lang=en-GB&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=assumption&lang=en-US&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_5_21","topic":"Nature and Environmental Protection","word":"athlete","pos":"(n)","ipa":"/ˈæθ.liːt/","defVi":"vận động viên","defEn":"a person who is trained in or good at sports and physical exercise","examples":["The young [athlete] trained for years to qualify for the Olympic Games. (=Dịch: Vận động viên trẻ đã luyện tập nhiều năm để đủ điều kiện tham dự Thế vận hội.)","Good nutrition and sufficient rest are essential for every professional [athlete]. (=Dịch: Dinh dưỡng tốt và nghỉ ngơi đầy đủ là điều cần thiết đối với mọi vận động viên chuyên nghiệp.)","She was named the top student [athlete] of her university. (=Dịch: Cô ấy được vinh danh là sinh viên vận động viên xuất sắc nhất của trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=athlete&lang=en-GB&ipa=%2F%CB%88%C3%A6%CE%B8.li%CB%90t%2F","usAudio":"/ai_services/tts3/?q=athlete&lang=en-US&ipa=%2F%CB%88%C3%A6%CE%B8.li%CB%90t%2F"},{"id":"lv_5_22","topic":"Nature and Environmental Protection","word":"atlas","pos":"(n)","ipa":"/ˈæt.ləs/","defVi":"tập bản đồ","defEn":"a book of maps","examples":["The teacher asked the students to find the capital on the world [atlas]. (=Dịch: Giáo viên yêu cầu học sinh tìm thủ đô trên tập bản đồ thế giới.)","She bought an updated road [atlas] before embarking on her cross-country trip. (=Dịch: Cô ấy đã mua một tập bản đồ đường bộ cập nhật trước khi bắt đầu chuyến đi xuyên quốc gia.)","This historical [atlas] illustrates the border changes throughout the centuries. (=Dịch: Tập bản đồ lịch sử này minh họa những thay đổi biên giới qua nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=atlas&lang=en-GB&ipa=%2F%CB%88%C3%A6t.l%C9%99s%2F","usAudio":"/ai_services/tts3/?q=atlas&lang=en-US&ipa=%2F%CB%88%C3%A6t.l%C9%99s%2F"},{"id":"lv_5_23","topic":"Nature and Environmental Protection","word":"attach","pos":"(v)","ipa":"/əˈtætʃ/","defVi":"đính kèm, gắn vào, dán vào","defEn":"to join, fasten, or connect one thing to another","examples":["Please [attach] your resume to the email before sending it. (=Dịch: Vui lòng đính kèm sơ yếu lý lịch của bạn vào email trước khi gửi.)","You need to [attach] a label to each piece of luggage. (=Dịch: Bạn cần dán một chiếc nhãn vào từng kiện hành lý.)","They decided to [attach] the solar panel securely to the roof. (=Dịch: Họ quyết định gắn tấm pin năng lượng mặt trời một cách chắc chắn lên mái nhà.)"],"ukAudio":"/ai_services/tts3/?q=attach&lang=en-GB&ipa=%2F%C9%99%CB%88t%C3%A6t%CA%83%2F","usAudio":"/ai_services/tts3/?q=attach&lang=en-US&ipa=%2F%C9%99%CB%88t%C3%A6t%CA%83%2F"},{"id":"lv_5_24","topic":"Nature and Environmental Protection","word":"autonomous","pos":"(adj)","ipa":"/ɔːˈtɑː.nə.məs/","defVi":"tự trị, tự chủ","defEn":"able to govern itself or act independently","examples":["The region became an [autonomous] province with its own legal system. (=Dịch: Khu vực này đã trở thành một tỉnh tự trị với hệ thống pháp luật riêng.)","Many tech companies are investing heavily in [autonomous] vehicles. (=Dịch: Nhiều công ty công nghệ đang đầu tư mạnh mẽ vào các phương tiện tự hành.)","Students are encouraged to become more [autonomous] in their learning. (=Dịch: Học sinh được khuyến khích trở nên chủ động và tự lập hơn trong học tập.)"],"ukAudio":"/ai_services/tts3/?q=autonomous&lang=en-GB&ipa=%2F%C9%94%CB%90%CB%88t%C9%91%CB%90.n%C9%99.m%C9%99s%2F","usAudio":"/ai_services/tts3/?q=autonomous&lang=en-US&ipa=%2F%C9%94%CB%90%CB%88t%C9%91%CB%90.n%C9%99.m%C9%99s%2F"},{"id":"lv_5_25","topic":"Nature and Environmental Protection","word":"ban","pos":"(v)","ipa":"/bæn/","defVi":"cấm, ngăn cấm","defEn":"to officially forbid or prohibit something","examples":["Many countries have decided to [ban] single-use plastic bags. (=Dịch: Nhiều quốc gia đã quyết định cấm túi ni lông sử dụng một lần.)","The school decided to [ban] smartphones during class hours. (=Dịch: Nhà trường quyết định cấm điện thoại thông minh trong giờ học.)","The athlete was [banned] from competing for two years due to doping. (=Dịch: Vận động viên bị cấm thi đấu hai năm do sử dụng chất kích thích.)"],"ukAudio":"/ai_services/tts3/?q=ban&lang=en-GB&ipa=%2Fb%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=ban&lang=en-US&ipa=%2Fb%C3%A6n%2F"},{"id":"lv_5_26","topic":"Nature and Environmental Protection","word":"bark","pos":"(n)","ipa":"/bɑːrk/","defVi":"vỏ cây","defEn":"the tough outer covering of the trunk and branches of a tree","examples":["The rough [bark] of the oak tree protected it from harsh weather. (=Dịch: Lớp vỏ sần sùi của cây sồi đã bảo vệ nó khỏi thời tiết khắc nghiệt.)","Ancient people used tree [bark] to make paper and medicine. (=Dịch: Người cổ đại đã sử dụng vỏ cây để làm giấy và thuốc.)","Insects can often be found hiding beneath the [bark]. (=Dịch: Côn trùng thường được tìm thấy ẩn nấp dưới lớp vỏ cây.)"],"ukAudio":"/ai_services/tts3/?q=bark&lang=en-GB&ipa=%2Fb%C9%91%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=bark&lang=en-US&ipa=%2Fb%C9%91%CB%90rk%2F"},{"id":"lv_5_27","topic":"Nature and Environmental Protection","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a large area of water that is partially surrounded by land","examples":["Several fishing boats were anchored safely inside the [bay]. (=Dịch: Một vài chiếc thuyền đánh cá đã neo đậu an toàn bên trong vịnh.)","The hotel offers a stunning view of the blue [bay]. (=Dịch: Khách sạn mang đến tầm nhìn tuyệt đẹp ra vịnh biển trong xanh.)","Many species of marine birds breed around the quiet [bay]. (=Dịch: Nhiều loài chim biển sinh sản quanh vùng vịnh yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_5_28","topic":"Nature and Environmental Protection","word":"beauty","pos":"(n)","ipa":"/ˈbjuː.t̬i/","defVi":"vẻ đẹp, nét đẹp","defEn":"the quality of being pleasing, especially to look at","examples":["The natural [beauty] of the mountains attracted many tourists. (=Dịch: Vẻ đẹp tự nhiên của những ngọn núi đã thu hút rất nhiều khách du lịch.)","She appreciated the [beauty] of classical music from a young age. (=Dịch: Cô ấy đã biết thưởng thức vẻ đẹp của âm nhạc cổ điển từ khi còn nhỏ.)","The [beauty] of this plan is its absolute simplicity. (=Dịch: Điểm hay của kế hoạch này chính là sự đơn giản tuyệt đối của nó.)"],"ukAudio":"/ai_services/tts3/?q=beauty&lang=en-GB&ipa=%2F%CB%88bju%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=beauty&lang=en-US&ipa=%2F%CB%88bju%CB%90.t%CC%ACi%2F"},{"id":"lv_5_29","topic":"Nature and Environmental Protection","word":"beetle","pos":"(n)","ipa":"/ˈbi.t̬əl/","defVi":"bọ cánh cứng","defEn":"an insect with hard front wings that cover and protect its soft flying wings","examples":["The bright green [beetle] crawled slowly across the fallen oak leaves. (=Dịch: Con bọ cánh cứng màu xanh lá sáng bò chầm chậm qua những chiếc lá sồi rụng.)","Certain species of [beetle] can cause severe damage to commercial pine forests. (=Dịch: Một số loài bọ cánh cứng nhất định có thể gây ra thiệt hại nghiêm trọng cho các cánh rừng thông thương mại.)","The young boy kept a harmless stag [beetle] in a glass jar to observe it. (=Dịch: Cậu bé nuôi một con bọ kẹp kìm vô hại trong lọ thủy tinh để quan sát.)"],"ukAudio":"/ai_services/tts3/?q=beetle&lang=en-GB&ipa=%2F%CB%88bi.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=beetle&lang=en-US&ipa=%2F%CB%88bi.t%CC%AC%C9%99l%2F"},{"id":"lv_5_30","topic":"Nature and Environmental Protection","word":"bell","pos":"(n)","ipa":"/bel/","defVi":"cái chuông","defEn":"a hollow metal object that makes a ringing sound when struck","examples":["The church [bell] rang across the quiet village every Sunday morning. (=Dịch: Tiếng chuông nhà thờ vang vọng khắp ngôi làng yên tĩnh vào mỗi sáng Chủ nhật.)","Students packed their bags as soon as they heard the school [bell]. (=Dịch: Học sinh thu dọn cặp sách ngay khi nghe thấy tiếng chuông trường học reo.)","He pressed the front door [bell] and waited for someone to answer. (=Dịch: Anh ấy bấm chuông cửa trước và đợi người ra mở.)"],"ukAudio":"/ai_services/tts3/?q=bell&lang=en-GB&ipa=%2Fbel%2F","usAudio":"/ai_services/tts3/?q=bell&lang=en-US&ipa=%2Fbel%2F"},{"id":"lv_5_31","topic":"Nature and Environmental Protection","word":"billion","pos":"(n)","ipa":"/ˈbɪl.jən/","defVi":"tỷ (1.000.000.000)","defEn":"the number 1,000,000,000","examples":["The world population has exceeded eight [billion] people. (=Dịch: Dân số thế giới đã vượt quá tám tỷ người.)","The government plans to spend a [billion] dollars on infrastructure. (=Dịch: Chính phủ dự kiến chi một tỷ đô la cho cơ sở hạ tầng.)","Scientists estimate that the galaxy contains over one hundred [billion] stars. (=Dịch: Các nhà khoa học ước tính rằng thiên hà chứa hơn một trăm tỷ ngôi sao.)"],"ukAudio":"/ai_services/tts3/?q=billion&lang=en-GB&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=billion&lang=en-US&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F"},{"id":"lv_5_32","topic":"Nature and Environmental Protection","word":"biodiversity","pos":"(n)","ipa":"/ˌbaɪ.oʊ.daɪˈvɜr.sə.t̬i/","defVi":"sự đa dạng sinh học","defEn":"the variety of plant and animal life in a particular habitat or in the world","examples":["Deforestation in the Amazon poses a serious threat to global [biodiversity]. (=Dịch: Nạn phá rừng ở Amazon đặt ra mối đe dọa nghiêm trọng đối với sự đa dạng sinh học toàn cầu.)","National parks are established to preserve the rich [biodiversity] of the region. (=Dịch: Các vườn quốc gia được thành lập để bảo tồn sự đa dạng sinh học phong phú của khu vực.)","The loss of marine [biodiversity] directly affects the livelihood of coastal communities. (=Dịch: Sự suy giảm đa dạng sinh học biển ảnh hưởng trực tiếp đến sinh kế của các cộng đồng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=biodiversity&lang=en-GB&ipa=%2F%CB%8Cba%C9%AA.o%CA%8A.da%C9%AA%CB%88v%C9%9Cr.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=biodiversity&lang=en-US&ipa=%2F%CB%8Cba%C9%AA.o%CA%8A.da%C9%AA%CB%88v%C9%9Cr.s%C9%99.t%CC%ACi%2F"},{"id":"lv_5_33","topic":"Nature and Environmental Protection","word":"biofuel","pos":"(n)","ipa":"/ˈbaɪ.oʊˌfjuː.əl/","defVi":"Nhiên liệu sinh học","defEn":"Fuel produced directly or indirectly from organic material such as plants and animal waste","examples":["Many countries are investing in [biofuel] to reduce their dependence on fossil fuels. (=Dịch: Nhiều quốc gia đang đầu tư vào nhiên liệu sinh học để giảm sự phụ thuộc vào nhiên liệu hóa thạch.)","Using [biofuel] can significantly lower greenhouse gas emissions from vehicles. (=Dịch: Sử dụng nhiên liệu sinh học có thể làm giảm đáng kể lượng khí thải nhà kính từ các phương tiện giao thông.)","The factory uses corn-based [biofuel] to power some of its heavy machinery. (=Dịch: Nhà máy sử dụng nhiên liệu sinh học làm từ ngô để vận hành một số máy móc hạng nặng.)"],"ukAudio":"/ai_services/tts3/?q=biofuel&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.o%CA%8A%CB%8Cfju%CB%90.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=biofuel&lang=en-US&ipa=%2F%CB%88ba%C9%AA.o%CA%8A%CB%8Cfju%CB%90.%C9%99l%2F"},{"id":"lv_5_34","topic":"Nature and Environmental Protection","word":"biologist","pos":"(n)","ipa":"/baɪˈɑː.lə.dʒɪst/","defVi":"nhà sinh học","defEn":"a scientist who studies living organisms and life processes","examples":["The marine [biologist] studied the behavior of coral reefs in warm waters. (=Dịch: Nhà sinh học biển đã nghiên cứu tập tính của các rạn san hô ở vùng nước ấm.)","A team of [biologists] discovered a new species of frog in the rainforest. (=Dịch: Một nhóm các nhà sinh học đã phát hiện ra một loài ếch mới trong rừng nhiệt đới.)","As a [biologist], she is passionate about wildlife conservation. (=Dịch: Là một nhà sinh học, cô ấy rất tâm huyết với việc bảo tồn động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=biologist&lang=en-GB&ipa=%2Fba%C9%AA%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=biologist&lang=en-US&ipa=%2Fba%C9%AA%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F"},{"id":"lv_5_35","topic":"Nature and Environmental Protection","word":"bizarre","pos":"(adj)","ipa":"/bɪˈzɑːr/","defVi":"kỳ quái, kỳ lạ","defEn":"very strange or unusual","examples":["The movie had a [bizarre] plot that confused most of the audience. (=Dịch: Bộ phim có một cốt truyện kỳ quái khiến hầu hết khán giả bối rối.)","She had a [bizarre] dream about flying fish last night. (=Dịch: Đêm qua cô ấy đã có một giấc mơ kỳ lạ về những con cá bay.)","He showed up to the formal party wearing [bizarre] clothes. (=Dịch: Anh ấy xuất hiện tại bữa tiệc trang trọng với bộ trang phục kỳ quặc.)"],"ukAudio":"/ai_services/tts3/?q=bizarre&lang=en-GB&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=bizarre&lang=en-US&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F"},{"id":"lv_5_36","topic":"Nature and Environmental Protection","word":"blackbird","pos":"(n)","ipa":"/ˈblæk.bɝːd/","defVi":"chim hoét đen (chim sáo đá đen)","defEn":"a common bird, of which the male has black feathers and a bright yellow beak","examples":["A male [blackbird] was singing sweetly from the top of the oak tree. (=Dịch: Một chú chim hoét đen trống đang hót véo von trên ngọn cây sồi.)","We watched a [blackbird] search for worms on the damp lawn. (=Dịch: Chúng tôi nhìn một con chim hoét đen đang tìm giun trên bãi cỏ ẩm ướt.)","The [blackbird] built its nest in the thick bushes near the garden wall. (=Dịch: Con chim hoét đen đã làm tổ trong bụi rậm gần bức tường vườn.)"],"ukAudio":"/ai_services/tts3/?q=blackbird&lang=en-GB&ipa=%2F%CB%88bl%C3%A6k.b%C9%9D%CB%90d%2F","usAudio":"/ai_services/tts3/?q=blackbird&lang=en-US&ipa=%2F%CB%88bl%C3%A6k.b%C9%9D%CB%90d%2F"},{"id":"lv_5_37","topic":"Nature and Environmental Protection","word":"boost","pos":"(n)","ipa":"/bust/","defVi":"Sự gia tăng, sự thúc đẩy, sự nâng cao.","defEn":"An increase or improvement, or an act that helps something improve.","examples":["The tax cuts provided a significant [boost] to the economy. (=Dịch: Việc cắt giảm thuế đã đem lại sự thúc đẩy đáng kể cho nền kinh tế.)","Winning the competition gave her confidence a huge [boost]. (=Dịch: Chiến thắng trong cuộc thi đã gia tăng sự tự tin cho cô ấy rất nhiều.)","A warm cup of coffee gives me the morning [boost] I need. (=Dịch: Một tách cà phê nóng cho tôi nguồn năng lượng cần thiết vào buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=boost&lang=en-GB&ipa=%2Fbust%2F","usAudio":"/ai_services/tts3/?q=boost&lang=en-US&ipa=%2Fbust%2F"},{"id":"lv_5_38","topic":"Nature and Environmental Protection","word":"bottled","pos":"(adj)","ipa":"/ˈbɑː.təld/","defVi":"được đóng chai","defEn":"stored and sold in bottles","examples":["Tourists are advised to drink [bottled] water to avoid stomach illnesses. (=Dịch: Khách du lịch được khuyên nên uống nước đóng chai để tránh các bệnh về đường tiêu hóa.)","The company produces high-quality [bottled] olive oil for export. (=Dịch: Công ty sản xuất dầu ô liu đóng chai chất lượng cao để xuất khẩu.)","Reducing the consumption of [bottled] beverages helps cut down on plastic waste. (=Dịch: Giảm tiêu thụ đồ uống đóng chai giúp cắt giảm rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=bottled&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.t%C9%99ld%2F","usAudio":"/ai_services/tts3/?q=bottled&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.t%C9%99ld%2F"},{"id":"lv_5_39","topic":"Nature and Environmental Protection","word":"brazil","pos":"(n)","ipa":"/brəˈzɪl/","defVi":"Nước Brasil (Bra-xin)","defEn":"A large country in South America, officially known as the Federative Republic of Brazil","examples":["The Amazon rainforest covers a substantial part of [brazil]. (=Dịch: Rừng mưa Amazon bao phủ một phần đáng kể của nước Brasil.)","Coffee production is a major contributor to the economy of [brazil]. (=Dịch: Sản xuất cà phê là một ngành đóng góp lớn cho nền kinh tế Brasil.)","Many tourists travel to [brazil] every year to experience the vibrant Carnival festival. (=Dịch: Nhiều du khách đến Brasil hàng năm để trải nghiệm lễ hội Carnival sôi động.)"],"ukAudio":"/ai_services/tts3/?q=brazil&lang=en-GB&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=brazil&lang=en-US&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F"},{"id":"lv_5_40","topic":"Nature and Environmental Protection","word":"breakwater","pos":"(n)","ipa":"/ˈbreɪkˌwɔː.t̬ɚ/","defVi":"đê chắn sóng","defEn":"a strong barrier built into the sea to protect a coast or harbor from the force of waves","examples":["The harbor is protected from rough seas by a concrete [breakwater]. (=Dịch: Bến cảng được bảo vệ khỏi biển động nhờ một con đê chắn sóng bằng bê tông.)","Fishermen often stand along the [breakwater] to catch fish. (=Dịch: Các ngư dân thường đứng dọc theo đê chắn sóng để câu cá.)","The city council decided to repair the damaged [breakwater] before the storm season. (=Dịch: Hội đồng thành phố đã quyết định sửa chữa đoạn đê chắn sóng bị hư hỏng trước mùa bão.)"],"ukAudio":"/ai_services/tts3/?q=breakwater&lang=en-GB&ipa=%2F%CB%88bre%C9%AAk%CB%8Cw%C9%94%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=breakwater&lang=en-US&ipa=%2F%CB%88bre%C9%AAk%CB%8Cw%C9%94%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_5_41","topic":"Nature and Environmental Protection","word":"breathe","pos":"(v)","ipa":"/briːð/","defVi":"thở, hít thở","defEn":"to take air into the lungs and expel it","examples":["Take a deep breath and try to [breathe] slowly to stay calm. (=Dịch: Hãy hít một hơi thật sâu và cố gắng thở chậm lại để giữ bình tĩnh.)","It was difficult to [breathe] at high altitudes due to the thin air. (=Dịch: Rất khó để thở ở độ cao lớn do không khí loãng.)","The doctor listened carefully as the patient began to [breathe] in and out. (=Dịch: Bác sĩ lắng nghe chăm chú khi bệnh nhân bắt đầu hít vào và thở ra.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2Fbri%CB%90%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2Fbri%CB%90%C3%B0%2F"},{"id":"lv_5_42","topic":"Nature and Environmental Protection","word":"bucket","pos":"(n)","ipa":"/ˈbʌk.ɪt/","defVi":"cái xô, thùng","defEn":"an open container with a handle, used for carrying liquids or other materials","examples":["He filled the plastic [bucket] with warm water to wash the car. (=Dịch: Anh ấy đổ đầy nước ấm vào chiếc xô nhựa để rửa xe.)","Children were playing on the beach with a [bucket] and spade. (=Dịch: Lũ trẻ đang chơi đùa trên bãi biển với một chiếc xô và cái xẻng.)","We placed a large [bucket] under the leaking pipe to catch the drips. (=Dịch: Chúng tôi đặt một chiếc xô lớn dưới đường ống bị rò rỉ để hứng nước nhỏ giọt.)"],"ukAudio":"/ai_services/tts3/?q=bucket&lang=en-GB&ipa=%2F%CB%88b%CA%8Ck.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bucket&lang=en-US&ipa=%2F%CB%88b%CA%8Ck.%C9%AAt%2F"},{"id":"lv_5_43","topic":"Nature and Environmental Protection","word":"bury","pos":"(v)","ipa":"/ˈber.i/","defVi":"Chôn cất, chôn vùi, che giấu","defEn":"To place a dead body or an object in the ground and cover it with earth.","examples":["Pirates used to [bury] their gold treasure on remote islands. (=Dịch: Những tên cướp biển từng chôn giấu kho báu vàng của chúng trên các hòn đảo xa xôi.)","The family gathered to [bury] their beloved grandfather. (=Dịch: Gia đình đã tụ họp để chôn cất người ông kính yêu của họ.)","A heavy avalanche threatened to [bury] the small mountain village. (=Dịch: Một trận lở tuyết dữ dội đe dọa chôn vùi ngôi làng nhỏ trên núi.)"],"ukAudio":"/ai_services/tts3/?q=bury&lang=en-GB&ipa=%2F%CB%88ber.i%2F","usAudio":"/ai_services/tts3/?q=bury&lang=en-US&ipa=%2F%CB%88ber.i%2F"},{"id":"lv_5_44","topic":"Nature and Environmental Protection","word":"butterfly","pos":"(n)","ipa":"/ˈbʌt̬.ɚ.flaɪ/","defVi":"Con bướm","defEn":"An insect with four large, typically brightly colored wings that develops from a caterpillar","examples":["A colorful [butterfly] landed gently on the blooming rose. (=Dịch: Một con bướm rực rỡ sắc màu nhẹ nhàng đậu lên bông hoa hồng đang nở.)","Children in the garden enjoyed watching the [butterfly] flutter from flower to flower. (=Dịch: Những đứa trẻ trong vườn thích thú ngắm nhìn chú bướm dập dờn từ bông hoa này sang bông hoa khác.)","The caterpillar undergoes a complete transformation before emerging as a [butterfly]. (=Dịch: Sâu bướm trải qua một quá trình biến thái hoàn toàn trước khi trở thành một con bướm.)"],"ukAudio":"/ai_services/tts3/?q=butterfly&lang=en-GB&ipa=%2F%CB%88b%CA%8Ct%CC%AC.%C9%9A.fla%C9%AA%2F","usAudio":"/ai_services/tts3/?q=butterfly&lang=en-US&ipa=%2F%CB%88b%CA%8Ct%CC%AC.%C9%9A.fla%C9%AA%2F"},{"id":"lv_5_45","topic":"Nature and Environmental Protection","word":"cage","pos":"(n)","ipa":"/keɪdʒ/","defVi":"lồng, chuồng","defEn":"a structure of bars or wires in which birds or other animals are kept","examples":["The parrot flew around inside its large [cage]. (=Dịch: Con vẹt bay lượn xung quanh bên trong chiếc lồng lớn của nó.)","Zookeepers cleaned the lion's [cage] early in the morning. (=Dịch: Các nhân viên vườn thú đã dọn dẹp chuồng sư tử từ sáng sớm.)","He felt trapped in his office cubicle, like a bird in a [cage]. (=Dịch: Anh cảm thấy bị mắc kẹt trong góc làm việc của mình, như một chú chim trong lồng.)"],"ukAudio":"/ai_services/tts3/?q=cage&lang=en-GB&ipa=%2Fke%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=cage&lang=en-US&ipa=%2Fke%C9%AAd%CA%92%2F"},{"id":"lv_5_46","topic":"Nature and Environmental Protection","word":"cane","pos":"(n)","ipa":"/keɪn/","defVi":"cây mía, cây gậy chống","defEn":"the hollow stem of tall grasses like sugar cane, or a stick used to assist walking","examples":["Sugar [cane] is grown extensively in tropical climates for sugar production. (=Dịch: Cây mía được trồng rộng rãi ở các vùng khí hậu nhiệt đới để sản xuất đường.)","The elderly gentleman walked slowly down the street with the help of a wooden [cane]. (=Dịch: Cụ ông bước đi chậm rãi trên phố với sự trợ giúp của một chiếc gậy chống bằng gỗ.)","Furniture made from woven [cane] has become very popular again. (=Dịch: Đồ nội thất làm từ mây tre đan đã trở nên rất phổ biến trở lại.)"],"ukAudio":"/ai_services/tts3/?q=cane&lang=en-GB&ipa=%2Fke%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=cane&lang=en-US&ipa=%2Fke%C9%AAn%2F"},{"id":"lv_5_47","topic":"Nature and Environmental Protection","word":"canola","pos":"(n)","ipa":"/kəˈnoʊ.lə/","defVi":"Cây hạt cải dầu (dùng ép dầu)","defEn":"A type of oilseed rape plant grown for its edible oil and animal feed","examples":["The golden fields of [canola] look breathtaking during early summer. (=Dịch: Những cánh đồng hạt cải dầu vàng rực trông đẹp ngoạn mục vào đầu mùa hè.)","She prefers to cook with [canola] oil because it is low in saturated fat. (=Dịch: Cô ấy thích nấu ăn bằng dầu hạt cải vì nó chứa ít chất béo bão hòa.)","Canada is one of the world's largest producers and exporters of [canola]. (=Dịch: Canada là một trong những quốc gia sản xuất và xuất khẩu hạt cải dầu lớn nhất thế giới.)"],"ukAudio":"/ai_services/tts3/?q=canola&lang=en-GB&ipa=%2Fk%C9%99%CB%88no%CA%8A.l%C9%99%2F","usAudio":"/ai_services/tts3/?q=canola&lang=en-US&ipa=%2Fk%C9%99%CB%88no%CA%8A.l%C9%99%2F"},{"id":"lv_5_48","topic":"Nature and Environmental Protection","word":"cap","pos":"(n)","ipa":"/kæp/","defVi":"mũ lưỡi trai; nắp đậy","defEn":"a soft, flat hat with a curved peak at the front, or a protective lid/cover","examples":["He wore a baseball [cap] to shield his eyes from the strong sunlight. (=Dịch: Anh ấy đội một chiếc mũ lưỡi trai để che mắt khỏi ánh nắng gắt.)","Make sure you screw the [cap] tightly back onto the bottle. (=Dịch: Hãy chắc chắn rằng bạn đã vặn chặt nắp trở lại chai.)","The government introduced a [cap] on university tuition fees this year. (=Dịch: Chính phủ đã đưa ra mức trần giới hạn về học phí đại học trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=cap&lang=en-GB&ipa=%2Fk%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=cap&lang=en-US&ipa=%2Fk%C3%A6p%2F"},{"id":"lv_5_49","topic":"Nature and Environmental Protection","word":"cargo","pos":"(n)","ipa":"/ˈkɑːr.ɡoʊ/","defVi":"hàng hóa (chở trên tàu bè, máy bay, xe tải)","defEn":"goods carried on a ship, aircraft, or motor vehicle","examples":["The container ship was carrying valuable [cargo] across the Pacific Ocean. (=Dịch: Tàu container đang chở hàng hóa có giá trị băng qua Thái Bình Dương.)","Workers carefully unloaded the fragile [cargo] from the plane. (=Dịch: Các công nhân đã cẩn thận dỡ kiện hàng dễ vỡ khỏi máy bay.)","The truck lost its [cargo] of timber during the accident. (=Dịch: Chiếc xe tải bị rơi toàn bộ số hàng gỗ trong vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=cargo&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=cargo&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.%C9%A1o%CA%8A%2F"},{"id":"lv_5_50","topic":"Nature and Environmental Protection","word":"category","pos":"(n)","ipa":"/ˈkæt̬.ə.ɡɔːr.i/","defVi":"Hạng mục, loại, danh mục","defEn":"A group of people or things that are similar and have the same features.","examples":["The books in the library are organized by [category]. (=Dịch: Sách trong thư viện được sắp xếp theo từng thể loại.)","She won an award in the best young artist [category]. (=Dịch: Cô ấy đã giành được giải thưởng ở hạng mục nghệ sĩ trẻ xuất sắc nhất.)","These expenses fall under the general [category] of travel costs. (=Dịch: Những khoản chi này thuộc danh mục chi phí đi lại nói chung.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_5_51","topic":"Nature and Environmental Protection","word":"cattle","pos":"(n)","ipa":"/ˈkæt̬.əl/","defVi":"gia súc, đàn bò","defEn":"large domesticated animals with horns and hoofs, kept for meat or milk (cows and bulls)","examples":["The farmer raises dairy [cattle] to supply fresh milk to the local town. (=Dịch: Người nông dân nuôi bò sữa để cung cấp sữa tươi cho thị trấn địa phương.)","Large herds of [cattle] graze peacefully in the open pasture. (=Dịch: Những đàn gia súc lớn thong thả gặm cỏ trên đồng cỏ rộng mở.)","Deforestation in the area is mainly driven by the need for [cattle] ranches. (=Dịch: Nạn phá rừng ở khu vực này chủ yếu do nhu cầu mở rộng các trang trại chăn nuôi gia súc.)"],"ukAudio":"/ai_services/tts3/?q=cattle&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cattle&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99l%2F"},{"id":"lv_5_52","topic":"Nature and Environmental Protection","word":"census","pos":"(n)","ipa":"/ˈsen.səs/","defVi":"cuộc điều tra dân số","defEn":"an official count or survey of a population, typically recording various details of individuals","examples":["The government conducts a national [census] every ten years. (=Dịch: Chính phủ tiến hành một cuộc điều tra dân số toàn quốc mười năm một lần.)","According to the latest [census], the city's population has doubled. (=Dịch: Theo cuộc điều tra dân số mới nhất, dân số thành phố đã tăng gấp đôi.)","The [census] data helps urban planners allocate public resources effectively. (=Dịch: Dữ liệu điều tra dân số giúp các nhà quy hoạch đô thị phân bổ nguồn lực công hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=census&lang=en-GB&ipa=%2F%CB%88sen.s%C9%99s%2F","usAudio":"/ai_services/tts3/?q=census&lang=en-US&ipa=%2F%CB%88sen.s%C9%99s%2F"},{"id":"lv_5_53","topic":"Nature and Environmental Protection","word":"centimetre","pos":"(n)","ipa":"/ˈsɛn.təˌmi.tər/","defVi":"xăng-ti-mét (đơn vị đo chiều dài)","defEn":"a metric unit of length equal to one hundredth of a metre","examples":["The seedling grew nearly one [centimetre] overnight. (=Dịch: Cây con đã phát triển thêm gần một xăng-ti-mét chỉ sau một đêm.)","Please cut the fabric five [centimetres] longer than the measurement. (=Dịch: Vui lòng cắt mảnh vải dài hơn kích thước đo năm xăng-ti-mét.)","The water level rose by several [centimetres] after the heavy downpour. (=Dịch: Mực nước đã dâng lên vài xăng-ti-mét sau trận mưa rào lớn.)"],"ukAudio":"/ai_services/tts3/?q=centimetre&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.t%C9%99%CB%8Cmi.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=centimetre&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.t%C9%99%CB%8Cmi.t%C9%99r%2F"},{"id":"lv_5_54","topic":"Nature and Environmental Protection","word":"classify","pos":"(v)","ipa":"/ˈklæs.ə.faɪ/","defVi":"phân loại, xếp loại","defEn":"to arrange people or things into groups based on shared qualities or characteristics","examples":["Biologists [classify] living organisms into different species and kingdoms. (=Dịch: Các nhà sinh học phân loại các sinh vật sống thành các loài và giới khác nhau.)","Librarians use a specialized system to [classify] thousands of new books. (=Dịch: Các thủ thư sử dụng một hệ thống chuyên dụng để phân loại hàng nghìn cuốn sách mới.)","The government decided to [classify] the official report as top secret. (=Dịch: Chính phủ đã quyết định phân loại báo cáo chính thức này là tuyệt mật.)"],"ukAudio":"/ai_services/tts3/?q=classify&lang=en-GB&ipa=%2F%CB%88kl%C3%A6s.%C9%99.fa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=classify&lang=en-US&ipa=%2F%CB%88kl%C3%A6s.%C9%99.fa%C9%AA%2F"},{"id":"lv_5_55","topic":"Nature and Environmental Protection","word":"claw","pos":"(n)","ipa":"/klɔː/","defVi":"móng vuốt (của động vật, chim), càng (cua, tôm)","defEn":"a sharp curved pointed nail on the foot of an animal or bird","examples":["The eagle used its sharp [claw] to catch a fish from the river. (=Dịch: Con đại bàng đã sử dụng chiếc móng vuốt sắc nhọn của mình để bắt một con cá dưới sông.)","The cat sharpened every [claw] against the wooden furniture in the living room. (=Dịch: Con mèo cào từng chiếc móng vuốt sắc lẹm vào đồ nội thất bằng gỗ trong phòng khách.)","Crabs can defend themselves against predators by pinching with a powerful [claw]. (=Dịch: Cua có thể tự vệ trước những kẻ săn mồi bằng cách kẹp bằng chiếc càng khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=claw&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%2F","usAudio":"/ai_services/tts3/?q=claw&lang=en-US&ipa=%2Fkl%C9%94%CB%90%2F"},{"id":"lv_5_56","topic":"Nature and Environmental Protection","word":"cliff","pos":"(n)","ipa":"/klɪf/","defVi":"vách đá dốc","defEn":"a high, steep area of rock or earth, especially at the edge of the sea","examples":["The lighthouse stands on the edge of a dangerous [cliff]. (=Dịch: Ngọn hải đăng đứng trên rìa của một vách đá nguy hiểm.)","They stood on the [cliff] and watched the waves crash below. (=Dịch: Họ đứng trên vách đá và ngắm những con sóng vỗ bên dưới.)","Nesting seabirds often build their homes on steep [cliff] faces. (=Dịch: Những loài chim biển làm tổ thường xây tổ trên các mặt vách đá dốc.)"],"ukAudio":"/ai_services/tts3/?q=cliff&lang=en-GB&ipa=%2Fkl%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=cliff&lang=en-US&ipa=%2Fkl%C9%AAf%2F"},{"id":"lv_5_57","topic":"Nature and Environmental Protection","word":"clip","pos":"(n)","ipa":"/klɪp/","defVi":"cái kẹp; đoạn phim/ghi âm ngắn","defEn":"a small device used to hold things together, or a short extract from a film or recording","examples":["She used a paper [clip] to keep the receipts organized. (=Dịch: Cô ấy đã dùng một chiếc kẹp giấy để sắp xếp các hóa đơn gọn gàng.)","The teacher showed a short video [clip] about marine life. (=Dịch: Giáo viên đã chiếu một đoạn video ngắn về sinh vật biển.)","He secured the microphone to his shirt with a small [clip]. (=Dịch: Anh ấy cố định chiếc micrô vào áo bằng một chiếc kẹp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=clip&lang=en-GB&ipa=%2Fkl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=clip&lang=en-US&ipa=%2Fkl%C9%AAp%2F"},{"id":"lv_5_58","topic":"Nature and Environmental Protection","word":"cloth","pos":"(n)","ipa":"/klɔθ/","defVi":"vải, khăn lau","defEn":"material made by weaving cotton, wool, or other fibres, used for making clothes or cleaning","examples":["He grabbed a damp [cloth] to clean the kitchen counter. (=Dịch: Anh ấy lấy một miếng vải ẩm để lau quầy bếp.)","The shirt is made from high-quality cotton [cloth]. (=Dịch: Chiếc áo sơ mi này được làm từ vải cotton chất lượng cao.)","Wrap the delicate vase in a soft [cloth] before packing it. (=Dịch: Hãy bọc chiếc bình hoa dễ vỡ trong một tấm vải mềm trước khi đóng gói.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CE%B8%2F"},{"id":"lv_5_59","topic":"Nature and Environmental Protection","word":"coal","pos":"(n)","ipa":"/koʊl/","defVi":"Than đá","defEn":"A hard, black mineral extracted from the earth and burned as fuel to generate heat or electricity","examples":["The power station burns tonnes of [coal] every day to generate electricity. (=Dịch: Nhà máy điện đốt hàng tấn than đá mỗi ngày để phát điện.)","Miners spend long hours underground extracting [coal] from deep seams. (=Dịch: Các công nhân mỏ dành nhiều giờ dưới lòng đất để khai thác than đá từ các vỉa sâu.)","Renewable energy sources are gradually replacing [coal] around the world. (=Dịch: Các nguồn năng lượng tái tạo đang dần thay thế than đá trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=coal&lang=en-GB&ipa=%2Fko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=coal&lang=en-US&ipa=%2Fko%CA%8Al%2F"},{"id":"lv_5_60","topic":"Nature and Environmental Protection","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stəl/","defVi":"thuộc miền ven biển, duyên hải","defEn":"located on or near a coast","examples":["Rising sea levels pose a severe danger to [coastal] communities. (=Dịch: Mực nước biển dâng cao gây ra mối nguy hiểm nghiêm trọng cho các cộng đồng ven biển.)","We enjoyed driving along the scenic [coastal] road. (=Dịch: Chúng tôi rất thích lái xe dọc theo con đường ven biển tuyệt đẹp.)","Fishing is the primary source of income for many [coastal] villages. (=Dịch: Đánh bắt cá là nguồn thu nhập chính của nhiều làng chài ven biển.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F"},{"id":"lv_5_61","topic":"Nature and Environmental Protection","word":"cod","pos":"(n)","ipa":"/kɑːd/","defVi":"cá tuyết","defEn":"a large sea fish that is commonly eaten as food","examples":["Traditional fish and chips are often made with Atlantic [cod]. (=Dịch: Món cá và khoai tây chiên truyền thống thường được làm từ cá tuyết Đại Tây Dương.)","Strict quotas were introduced to protect the declining [cod] population. (=Dịch: Các hạn ngạch nghiêm ngặt đã được áp dụng nhằm bảo vệ quần thể cá tuyết đang suy giảm.)","The local fishermen caught several large [cod] during their trip. (=Dịch: Các ngư dân địa phương đã bắt được một vài con cá tuyết lớn trong chuyến đi của họ.)"],"ukAudio":"/ai_services/tts3/?q=cod&lang=en-GB&ipa=%2Fk%C9%91%CB%90d%2F","usAudio":"/ai_services/tts3/?q=cod&lang=en-US&ipa=%2Fk%C9%91%CB%90d%2F"},{"id":"lv_5_62","topic":"Nature and Environmental Protection","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑːɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with mental processes of understanding, learning, and remembering","examples":["Reading regularly helps to enhance children's [cognitive] development. (=Dịch: Đọc sách thường xuyên giúp tăng cường sự phát triển nhận thức của trẻ em.)","Scientists study how sleep deprivation affects [cognitive] functions. (=Dịch: Các nhà khoa học nghiên cứu xem việc thiếu ngủ ảnh hưởng như thế nào đến các chức năng nhận thức.)","Puzzles and memory games are great for maintaining [cognitive] abilities in old age. (=Dịch: Trò chơi giải đố và ghi nhớ rất tuyệt vời để duy trì khả năng nhận thức ở tuổi già.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_5_63","topic":"Nature and Environmental Protection","word":"coin","pos":"(n)","ipa":"/kɔɪn/","defVi":"đồng xu, tiền kim loại","defEn":"a small, flat, usually round piece of metal used as money","examples":["She inserted a shiny [coin] into the vending machine to buy a drink. (=Dịch: Cô ấy nhét một đồng xu sáng bóng vào máy bán hàng tự động để mua nước uống.)","He flipped a [coin] to decide who would start the game. (=Dịch: Anh ấy đã tung một đồng xu để quyết định xem ai sẽ bắt đầu trò chơi.)","My grandfather gave me a rare silver [coin] for my collection. (=Dịch: Ông tôi đã tặng tôi một đồng xu bạc hiếm cho bộ sưu tập của tôi.)"],"ukAudio":"/ai_services/tts3/?q=coin&lang=en-GB&ipa=%2Fk%C9%94%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coin&lang=en-US&ipa=%2Fk%C9%94%C9%AAn%2F"},{"id":"lv_5_64","topic":"Nature and Environmental Protection","word":"colony","pos":"(n)","ipa":"/ˈkɑː.lə.ni/","defVi":"thuộc địa; bầy đàn (động vật sống thành đàn)","defEn":"a country controlled by another country, or a group of animals living together","examples":["Hong Kong used to be a British [colony] before 1997. (=Dịch: Hồng Kông từng là một thuộc địa của Anh trước năm 1997.)","Scientists observed a large [colony] of penguins on the icy shore. (=Dịch: Các nhà khoa học đã quan sát một bầy chim cánh cụt lớn trên bờ biển phủ băng.)","Ants live together in an organized underground [colony]. (=Dịch: Kiến sống cùng nhau trong một tổ kiến có tổ chức dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=colony&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=colony&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F"},{"id":"lv_5_65","topic":"Nature and Environmental Protection","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"hội đồng/ủy ban; tiền hoa hồng","defEn":"an official group appointed to perform a task, or a payment given to an agent for a service","examples":["The government formed an independent [commission] to investigate the transportation accident. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vụ tai nạn giao thông.)","Real estate agents typically earn a percentage-based [commission] on every property sold. (=Dịch: Các đại lý bất động sản thường kiếm được tiền hoa hồng dựa trên tỷ lệ phần trăm của mỗi bất động sản bán được.)","The artist received a prestigious [commission] to paint a portrait for the city hall. (=Dịch: Người nghệ sĩ đã nhận được một đơn đặt hàng danh giá để vẽ một bức chân dung cho tòa thị chính.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_66","topic":"Nature and Environmental Protection","word":"commonly","pos":"(adv)","ipa":"/ˈkɑː.mən.li/","defVi":"thường thường, phổ biến","defEn":"very often, frequently, or by most people","examples":["This type of mushroom is [commonly] found in damp forests. (=Dịch: Loại nấm này thường được tìm thấy trong các khu rừng ẩm ướt.)","The disease is [commonly] known as the flu. (=Dịch: Căn bệnh này thường được gọi phổ biến là bệnh cúm.)","Plastic bottles are [commonly] used for packaging soft drinks. (=Dịch: Chai nhựa thường được sử dụng rộng rãi để đóng gói nước giải khát.)"],"ukAudio":"/ai_services/tts3/?q=commonly&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.li%2F","usAudio":"/ai_services/tts3/?q=commonly&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.li%2F"},{"id":"lv_5_67","topic":"Nature and Environmental Protection","word":"compass","pos":"(n)","ipa":"/ˈkʌm.pəs/","defVi":"la bàn","defEn":"an instrument that shows direction, having a needle that always points north","examples":["Hikers should always carry a map and a [compass] in the wilderness. (=Dịch: Những người đi bộ đường dài nên luôn mang theo bản đồ và la bàn khi vào nơi hoang dã.)","The needle of the [compass] points directly toward magnetic north. (=Dịch: Kim la bàn luôn chỉ thẳng về phía bắc từ trường.)","Without a reliable [compass], it is easy to get lost in the dense forest. (=Dịch: Nếu không có một chiếc la bàn đáng tin cậy, bạn rất dễ bị lạc trong khu rừng rậm.)"],"ukAudio":"/ai_services/tts3/?q=compass&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=compass&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F"},{"id":"lv_5_68","topic":"Nature and Environmental Protection","word":"compost","pos":"(n)","ipa":"/ˈkɑːm.poʊst/","defVi":"phân ủ hữu cơ","defEn":"decayed organic material used as a fertilizer for growing plants","examples":["Adding [compost] to sandy soil helps it retain moisture and essential nutrients. (=Dịch: Thêm phân ủ hữu cơ vào đất cát giúp đất giữ ẩm và các chất dinh dưỡng thiết yếu.)","She collects fruit peels and coffee grounds in her garden to make organic [compost]. (=Dịch: Cô ấy thu gom vỏ trái cây và bã cà phê trong vườn để làm phân ủ hữu cơ.)","Using rich [compost] reduces the need for synthetic chemical fertilizers on farms. (=Dịch: Sử dụng phân ủ giàu dưỡng chất giúp giảm nhu cầu dùng phân bón hóa học tổng hợp trong các trang trại.)"],"ukAudio":"/ai_services/tts3/?q=compost&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90m.po%CA%8Ast%2F","usAudio":"/ai_services/tts3/?q=compost&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90m.po%CA%8Ast%2F"},{"id":"lv_5_69","topic":"Nature and Environmental Protection","word":"comprehensive","pos":"(adj)","ipa":"/ˌkɑːm.prɪ.ˈhen.sɪv/","defVi":"toàn diện, bao quát","defEn":"including all, or almost all, the items or details that are involved","examples":["The school offers a [comprehensive] course covering all four language skills. (=Dịch: Ngôi trường cung cấp một khóa học toàn diện bao gồm cả bốn kỹ năng ngôn ngữ.)","The government conducted a [comprehensive] study on climate change. (=Dịch: Chính phủ đã tiến hành một nghiên cứu toàn diện về biến đổi khí hậu.)","We need a [comprehensive] plan to solve the city's traffic congestion. (=Dịch: Chúng ta cần một kế hoạch toàn diện để giải quyết tình trạng ùn tắc giao thông của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=comprehensive&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.pr%C9%AA.%CB%88hen.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=comprehensive&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.pr%C9%AA.%CB%88hen.s%C9%AAv%2F"},{"id":"lv_5_70","topic":"Nature and Environmental Protection","word":"comprise","pos":"(v)","ipa":"/kəmˈpraɪz/","defVi":"bao gồm, gồm có","defEn":"to have things or people as parts or members; to consist of","examples":["The advisory panel will [comprise] experts from diverse academic backgrounds. (=Dịch: Hội đồng cố vấn sẽ bao gồm các chuyên gia từ nhiều nền tảng học thuật khác nhau.)","Older adults and young children [comprise] the majority of the population in this village. (=Dịch: Người lớn tuổi và trẻ nhỏ chiếm phần lớn dân số ở ngôi làng này.)","The newly developed syllabus will [comprise] ten comprehensive study modules. (=Dịch: Giáo trình mới được xây dựng sẽ bao gồm mười học phần nghiên cứu toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=comprise&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pra%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=comprise&lang=en-US&ipa=%2Fk%C9%99m%CB%88pra%C9%AAz%2F"},{"id":"lv_5_71","topic":"Nature and Environmental Protection","word":"conclude","pos":"(v)","ipa":"/kənˈkluːd/","defVi":"kết luận; kết thúc","defEn":"to reach a decision or opinion after considering all the facts; to bring something to an end","examples":["Based on the survey data, we can [conclude] that public support has risen. (=Dịch: Dựa vào dữ liệu khảo sát, chúng ta có thể kết luận rằng sự ủng hộ của công chúng đã tăng lên.)","The keynote speaker will [conclude] his presentation with a short question session. (=Dịch: Diễn giả chính sẽ kết thúc bài thuyết trình của mình bằng một phần hỏi đáp ngắn.)","Investigators were able to [conclude] the inquiry after discovering new evidence. (=Dịch: Các điều tra viên đã có thể kết thúc cuộc điều tra sau khi phát hiện ra bằng chứng mới.)"],"ukAudio":"/ai_services/tts3/?q=conclude&lang=en-GB&ipa=%2Fk%C9%99n%CB%88klu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=conclude&lang=en-US&ipa=%2Fk%C9%99n%CB%88klu%CB%90d%2F"},{"id":"lv_5_72","topic":"Nature and Environmental Protection","word":"confused","pos":"(adj)","ipa":"/kənˈfjuzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to understand something clearly or think sensibly","examples":["I was deeply [confused] by the complicated instructions. (=Dịch: Tôi đã rất bối rối trước những lời hướng dẫn phức tạp.)","The student looked [confused] during the difficult lecture. (=Dịch: Người sinh viên trông có vẻ lúng túng trong suốt bài giảng khó.)","If you feel [confused] about the new rules, please ask your supervisor. (=Dịch: Nếu bạn cảm thấy hoang mang về các quy định mới, hãy hỏi người giám sát của bạn.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fjuzd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fjuzd%2F"},{"id":"lv_5_73","topic":"Nature and Environmental Protection","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwəns/","defVi":"hậu quả, kết quả","defEn":"a result or effect of an action or situation, typically one that is unwelcome or unpleasant","examples":["Global warming is a direct [consequence] of excessive greenhouse gas emissions. (=Dịch: Sự nóng lên toàn cầu là hậu quả trực tiếp của việc phát thải khí nhà kính quá mức.)","He had to face the [consequence] of making such a hasty decision. (=Dịch: Anh ấy phải đối mặt với hậu quả của việc đưa ra một quyết định vội vàng như vậy.)","Failing to study properly will have a serious [consequence] on your grades. (=Dịch: Không học hành đàng hoàng sẽ gây ra hậu quả nghiêm trọng đến điểm số của bạn.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F"},{"id":"lv_5_74","topic":"Nature and Environmental Protection","word":"consistent","pos":"(adj)","ipa":"/kənˈsɪs.tənt/","defVi":"nhất quán, kiên định, đồng đều","defEn":"always behaving or happening in a similar, especially positive, way","examples":["She has shown a [consistent] improvement in her English test scores. (=Dịch: Cô ấy đã thể hiện sự tiến bộ đều đặn trong điểm số bài thi tiếng Anh.)","His statements were not [consistent] with the facts. (=Dịch: Những lời tuyên bố của anh ấy không nhất quán với sự thật.)","To achieve success, you need to put in [consistent] effort every day. (=Dịch: Để đạt được thành công, bạn cần nỗ lực bền bỉ mỗi ngày.)"],"ukAudio":"/ai_services/tts3/?q=consistent&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%AAs.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=consistent&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%AAs.t%C9%99nt%2F"},{"id":"lv_5_75","topic":"Nature and Environmental Protection","word":"consume","pos":"(v)","ipa":"/kənˈsuːm/","defVi":"tiêu thụ, sử dụng","defEn":"to eat, drink, or use up resources, energy, or time","examples":["Electric vehicles [consume] far less energy compared to traditional petrol cars. (=Dịch: Xe điện tiêu thụ ít năng lượng hơn nhiều so với xe chạy xăng truyền thống.)","Athletes should [consume] plenty of water and carbohydrates before a marathon. (=Dịch: Vận động viên nên tiêu thụ nhiều nước và tinh bột trước khi chạy marathon.)","The enormous forest fire threatened to [consume] several mountain villages. (=Dịch: Trận cháy rừng khủng khiếp đe dọa thiêu rụi vài ngôi làng miền núi.)"],"ukAudio":"/ai_services/tts3/?q=consume&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F","usAudio":"/ai_services/tts3/?q=consume&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F"},{"id":"lv_5_76","topic":"Nature and Environmental Protection","word":"consumption","pos":"(n)","ipa":"/kənˈsʌmp.ʃən/","defVi":"sự tiêu thụ, mức tiêu dùng","defEn":"the act of using up resources, goods, or energy","examples":["The doctor advised him to reduce his daily sugar [consumption]. (=Dịch: Bác sĩ khuyên anh ấy nên giảm lượng tiêu thụ đường hàng ngày.)","Rapid economic growth usually leads to higher energy [consumption]. (=Dịch: Tăng trưởng kinh tế nhanh chóng thường dẫn đến mức tiêu thụ năng lượng cao hơn.)","Public campaigns aim to minimize the excessive [consumption] of single-use plastics. (=Dịch: Các chiến dịch cộng đồng nhằm giảm thiểu việc tiêu thụ quá mức các sản phẩm nhựa dùng một lần.)"],"ukAudio":"/ai_services/tts3/?q=consumption&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consumption&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_5_77","topic":"Nature and Environmental Protection","word":"contaminate","pos":"(v)","ipa":"/kənˈtæm.ə.neɪt/","defVi":"làm bẩn, làm ô nhiễm","defEn":"to make something less pure or poisonous by adding a substance to it","examples":["Industrial waste can easily [contaminate] local drinking water supplies. (=Dịch: Chất thải công nghiệp có thể dễ dàng làm ô nhiễm nguồn nước sinh hoạt của địa phương.)","Pesticides run off into rivers and [contaminate] the natural habitats of fish. (=Dịch: Thuốc trừ sâu trôi xuống các dòng sông và làm ô nhiễm môi trường sống tự nhiên của cá.)","Be careful not to [contaminate] the sterile instruments before the operation. (=Dịch: Hãy cẩn thận để không làm nhiễm khuẩn các dụng cụ vô trùng trước ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=contaminate&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C3%A6m.%C9%99.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=contaminate&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C3%A6m.%C9%99.ne%C9%AAt%2F"},{"id":"lv_5_78","topic":"Nature and Environmental Protection","word":"conversion","pos":"(n)","ipa":"/kənˈvɜːr.ʒən/","defVi":"sự chuyển đổi","defEn":"the process of changing from one system, use, or method to another","examples":["The [conversion] of solar energy into electricity is becoming more efficient. (=Dịch: Sự chuyển đổi năng lượng mặt trời thành điện năng đang ngày càng trở nên hiệu quả hơn.)","The company managed the [conversion] from paper records to digital files smoothly. (=Dịch: Công ty đã xử lý việc chuyển đổi từ hồ sơ giấy sang tệp kỹ thuật số một cách suôn sẻ.)","Urban planners approved the [conversion] of the warehouse into modern apartments. (=Dịch: Các nhà quy hoạch đô thị đã chấp thuận việc chuyển đổi nhà kho thành các căn hộ hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=conversion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=conversion&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_5_79","topic":"Nature and Environmental Protection","word":"convinced","pos":"(adj)","ipa":"/kənˈvɪnst/","defVi":"Bị thuyết phục; tin chắc; chắc chắn.","defEn":"Completely certain about something or believing that something is true.","examples":["Scientists are [convinced] that human activity contributes to global warming. (=Dịch: Các nhà khoa học tin chắc rằng hoạt động của con người góp phần gây ra sự nóng lên toàn cầu.)","She remained [convinced] that she had made the right decision for her career. (=Dịch: Cô ấy vẫn tin chắc rằng mình đã đưa ra quyết định đúng đắn cho sự nghiệp của mình.)","The jury was not entirely [convinced] by the witness's testimony. (=Dịch: Bồi thẩm đoàn không hoàn toàn bị thuyết phục bởi lời khai của nhân chứng.)"],"ukAudio":"/ai_services/tts3/?q=convinced&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%AAnst%2F","usAudio":"/ai_services/tts3/?q=convinced&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%AAnst%2F"},{"id":"lv_5_80","topic":"Nature and Environmental Protection","word":"cooler","pos":"(n)","ipa":"/ˈku.lər/","defVi":"thùng giữ nhiệt, thùng đá","defEn":"an insulated container used for keeping food or drinks cold","examples":["We packed some cold drinks and sandwiches in the [cooler] before heading to the beach. (=Dịch: Chúng tôi đã xếp một số đồ uống lạnh và bánh mì kẹp vào thùng đá trước khi đi biển.)","Please put the remaining ice cream back into the [cooler] so it will not melt. (=Dịch: Làm ơn cất chỗ kem còn lại vào thùng giữ nhiệt để kem không bị chảy.)","The portable [cooler] kept the medical supplies at a safe temperature during transport. (=Dịch: Thùng giữ nhiệt di động đã bảo quản các vật tư y tế ở nhiệt độ an toàn trong suốt quá trình vận chuyển.)"],"ukAudio":"/ai_services/tts3/?q=cooler&lang=en-GB&ipa=%2F%CB%88ku.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=cooler&lang=en-US&ipa=%2F%CB%88ku.l%C9%99r%2F"},{"id":"lv_5_81","topic":"Nature and Environmental Protection","word":"corn","pos":"(n)","ipa":"/kɔːrn/","defVi":"ngô, bắp","defEn":"a tall plant that produces large yellow grains on a cob, used as food","examples":["Farmers harvested tons of sweet [corn] this autumn. (=Dịch: Những người nông dân đã thu hoạch hàng tấn ngô ngọt vào mùa thu này.)","Popcorn is made by heating dried kernels of [corn]. (=Dịch: Bắp rang bơ được làm bằng cách đun nóng các hạt ngô khô.)","Many processed foods contain syrup derived from [corn]. (=Dịch: Nhiều thực phẩm chế biến sẵn chứa si-rô chiết xuất từ ngô.)"],"ukAudio":"/ai_services/tts3/?q=corn&lang=en-GB&ipa=%2Fk%C9%94%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=corn&lang=en-US&ipa=%2Fk%C9%94%CB%90rn%2F"},{"id":"lv_5_82","topic":"Nature and Environmental Protection","word":"courtyard","pos":"(n)","ipa":"/ˈkɔːrt.jɑːrd/","defVi":"sân trong, khuôn viên","defEn":"an open area surrounded by buildings or walls","examples":["The hotel features a peaceful [courtyard] with a small fountain in the center. (=Dịch: Khách sạn có một khoảng sân trong yên tĩnh với một đài phun nước nhỏ ở trung tâm.)","Students often gather in the central [courtyard] during lunch breaks. (=Dịch: Học sinh thường tụ tập ở sân trong trung tâm trong giờ nghỉ trưa.)","Tall walls sheltered the private [courtyard] from strong winds. (=Dịch: Những bức tường cao đã che chắn cho sân trong riêng tư khỏi những cơn gió mạnh.)"],"ukAudio":"/ai_services/tts3/?q=courtyard&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=courtyard&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F"},{"id":"lv_5_83","topic":"Nature and Environmental Protection","word":"creature","pos":"(n)","ipa":"/ˈkri.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"any living thing that can move independently, especially an animal","examples":["The ocean depths are home to many bizarre [creatures]. (=Dịch: Đáy đại dương sâu thẳm là nơi cư ngụ của nhiều sinh vật kỳ dị.)","Every living [creature] plays an important role in the ecosystem. (=Dịch: Mỗi sinh vật sống đều đóng một vai trò quan trọng trong hệ sinh thái.)","Scientists discovered a nocturnal [creature] that only hunts at night. (=Dịch: Các nhà khoa học đã phát hiện ra một sinh vật sống về đêm chỉ đi săn khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri.t%CA%83%C9%9A%2F"},{"id":"lv_5_84","topic":"Nature and Environmental Protection","word":"crisis","pos":"(n)","ipa":"/ˈkraɪ.sɪs/","defVi":"cuộc khủng hoảng","defEn":"a time of intense difficulty, trouble, or danger requiring urgent action","examples":["The government introduced emergency measures to deal with the worsening energy [crisis]. (=Dịch: Chính phủ đã đưa ra các biện pháp khẩn cấp để đối phó với cuộc khủng hoảng năng lượng ngày càng trầm trọng.)","Effective leadership is vital when guiding an organization through an unexpected financial [crisis]. (=Dịch: Sự lãnh đạo hiệu quả là điều tối quan trọng khi dẫn dắt một tổ chức vượt qua cuộc khủng hoảng tài chính bất ngờ.)","The sudden flood created a severe humanitarian [crisis] across the coastal region. (=Dịch: Trận lũ lụt đột ngột đã tạo ra một cuộc khủng hoảng nhân đạo nghiêm trọng trên khắp vùng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=crisis&lang=en-GB&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=crisis&lang=en-US&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F"},{"id":"lv_5_85","topic":"Nature and Environmental Protection","word":"crow","pos":"(n)","ipa":"/kroʊ/","defVi":"con quạ","defEn":"a large, shiny black bird with a harsh cry","examples":["A black [crow] landed on the fence and looked around. (=Dịch: Một con quạ đen đậu trên hàng rào và nhìn quanh.)","Researchers found that the [crow] is capable of solving complex puzzles. (=Dịch: Các nhà nghiên cứu phát hiện ra rằng loài quạ có khả năng giải các câu đố phức tạp.)","The loud call of a [crow] echoed through the quiet forest. (=Dịch: Tiếng kêu lớn của một con quạ vang vọng khắp khu rừng yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=crow&lang=en-GB&ipa=%2Fkro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=crow&lang=en-US&ipa=%2Fkro%CA%8A%2F"},{"id":"lv_5_86","topic":"Nature and Environmental Protection","word":"crucial","pos":"(adj)","ipa":"/ˈkru.ʃəl/","defVi":"mang tính quyết định, cực kỳ quan trọng","defEn":"extremely important or necessary","examples":["Regular exercise plays a [crucial] role in maintaining overall physical health. (=Dịch: Tập thể dục thường xuyên đóng một vai trò cực kỳ quan trọng trong việc duy trì sức khỏe thể chất toàn diện.)","Effective communication is [crucial] for resolving workplace conflicts peacefully. (=Dịch: Giao tiếp hiệu quả là điều cốt yếu để giải quyết các mâu thuẫn nơi làm việc một cách hòa bình.)","The government made a [crucial] decision to cut carbon emissions this year. (=Dịch: Chính phủ đã đưa ra một quyết định mang tính quyết định nhằm cắt giảm lượng khí thải carbon trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=crucial&lang=en-GB&ipa=%2F%CB%88kru.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=crucial&lang=en-US&ipa=%2F%CB%88kru.%CA%83%C9%99l%2F"},{"id":"lv_5_87","topic":"Nature and Environmental Protection","word":"crush","pos":"(v)","ipa":"/krʌʃ/","defVi":"Nghiền nát, đè bẹp, ép vụn","defEn":"To press something so hard that it gets broken, damaged, or flat.","examples":["You need to [crush] the garlic cloves before adding them to the sauce. (=Dịch: Bạn cần đập dập các tép tỏi trước khi cho vào nước sốt.)","The heavy falling branch managed to [crush] the parked car. (=Dịch: Cành cây lớn rơi xuống đã đè bẹp chiếc xe hơi đang đỗ.)","Machines are used to [crush] rocks into fine gravel for road construction. (=Dịch: Máy móc được sử dụng để nghiền đá thành sỏi mịn phục vụ cho việc làm đường.)"],"ukAudio":"/ai_services/tts3/?q=crush&lang=en-GB&ipa=%2Fkr%CA%8C%CA%83%2F","usAudio":"/ai_services/tts3/?q=crush&lang=en-US&ipa=%2Fkr%CA%8C%CA%83%2F"},{"id":"lv_5_88","topic":"Nature and Environmental Protection","word":"cryptobiosis","pos":"(n)","ipa":"/ˌkrɪp.toʊ.baɪˈoʊ.sɪs/","defVi":"hiện tượng tiềm sinh (trạng thái đình chỉ hoạt động sống ở sinh vật)","defEn":"a state of extreme inactivity in an organism in response to adverse environmental conditions","examples":["Tardigrades can enter a state of [cryptobiosis] to survive extreme cold and radiation. (=Dịch: Gấu nước có thể bước vào trạng thái tiềm sinh để sống sót qua cái lạnh khắc nghiệt và bức xạ.)","During [cryptobiosis], an organism's metabolic activity slows down almost completely. (=Dịch: Trong trạng thái tiềm sinh, hoạt động trao đổi chất của sinh vật chậm lại gần như hoàn toàn.)","Scientists study [cryptobiosis] to understand how life might endure in outer space. (=Dịch: Các nhà khoa học nghiên cứu hiện tượng tiềm sinh để hiểu cách sự sống có thể tồn tại ngoài không gian.)"],"ukAudio":"/ai_services/tts3/?q=cryptobiosis&lang=en-GB&ipa=%2F%CB%8Ckr%C9%AAp.to%CA%8A.ba%C9%AA%CB%88o%CA%8A.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=cryptobiosis&lang=en-US&ipa=%2F%CB%8Ckr%C9%AAp.to%CA%8A.ba%C9%AA%CB%88o%CA%8A.s%C9%AAs%2F"},{"id":"lv_5_89","topic":"Nature and Environmental Protection","word":"damaging","pos":"(adj)","ipa":"/ˈdæm.ɪ.dʒɪŋ/","defVi":"Gây hại, gây tổn hại, có hại.","defEn":"Causing harm, injury, or loss of value.","examples":["Smoking has many [damaging] effects on human health. (=Dịch: Hút thuốc gây ra nhiều ảnh hưởng có hại đối với sức khỏe con người.)","The scandal had a very [damaging] impact on his political career. (=Dịch: Vụ bê bối đã để lại tác động rất tai hại đến sự nghiệp chính trị của ông ấy.)","UV radiation can be extremely [damaging] to uncovered skin. (=Dịch: Bức xạ tia cực tím có thể gây tổn hại nghiêm trọng cho da không được che chắn.)"],"ukAudio":"/ai_services/tts3/?q=damaging&lang=en-GB&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=damaging&lang=en-US&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_5_90","topic":"Nature and Environmental Protection","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"Giảm sút, suy giảm; từ chối khéo.","defEn":"To decrease in number, amount, or quality; or to politely refuse.","examples":["Profits began to [decline] sharply during the economic crisis. (=Dịch: Lợi nhuận bắt đầu suy giảm mạnh trong thời kỳ khủng hoảng kinh tế.)","I had to politely [decline] their kind invitation to dinner. (=Dịch: Tôi đã phải lịch sự từ chối lời mời ăn tối tử tế của họ.)","Air quality can [decline] when industrial emissions increase. (=Dịch: Chất lượng không khí có thể giảm sút khi lượng khí thải công nghiệp gia tăng.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_5_91","topic":"Nature and Environmental Protection","word":"deer","pos":"(n)","ipa":"/dɪr/","defVi":"con hươu, con nai","defEn":"a hoofed grazing animal with long legs, the males of which usually have branched horns (antlers)","examples":["A herd of [deer] was seen grazing peacefully in the meadow. (=Dịch: Một đàn hươu được nhìn thấy đang gặm cỏ yên bình trên đồng cỏ.)","Drivers should be cautious because a [deer] might suddenly jump onto the road. (=Dịch: Tài xế nên cẩn thận vì hươu có thể bất ngờ nhảy ra đường.)","The young [deer] quickly hid behind the bushes when it sensed danger. (=Dịch: Chú nai con nhanh chóng trốn sau bụi cây khi cảm nhận được nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=deer&lang=en-GB&ipa=%2Fd%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=deer&lang=en-US&ipa=%2Fd%C9%AAr%2F"},{"id":"lv_5_92","topic":"Nature and Environmental Protection","word":"dependent","pos":"(adj)","ipa":"/dɪˈpen.dənt/","defVi":"phụ thuộc, lệ thuộc","defEn":"needing someone or something for support, help, or survival; determined by something else","examples":["Newborn babies are completely [dependent] on their parents for care. (=Dịch: Trẻ sơ sinh hoàn toàn phụ thuộc vào cha mẹ để được chăm sóc.)","The success of the crops is heavily [dependent] on the weather. (=Dịch: Sự thành công của mùa màng phụ thuộc rất nhiều vào thời tiết.)","Many developing nations are still [dependent] on foreign aid. (=Dịch: Nhiều quốc gia đang phát triển vẫn còn phụ thuộc vào viện trợ nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F"},{"id":"lv_5_93","topic":"Nature and Environmental Protection","word":"derive","pos":"(v)","ipa":"/dɪˈraɪv/","defVi":"bắt nguồn từ, nhận được từ","defEn":"to get something from a particular source, or to originate from it","examples":["Many English words [derive] from Latin and ancient Greek. (=Dịch: Nhiều từ tiếng Anh bắt nguồn từ tiếng La-tinh và tiếng Hy Lạp cổ đại.)","She hopes to [derive] great satisfaction from her new career in teaching. (=Dịch: Cô ấy hy vọng sẽ nhận được sự hài lòng lớn từ sự nghiệp giảng dạy mới của mình.)","The company can [derive] valuable insights from customer feedback data. (=Dịch: Công ty có thể thu thập được những hiểu biết giá trị từ dữ liệu phản hồi của khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=derive&lang=en-GB&ipa=%2Fd%C9%AA%CB%88ra%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=derive&lang=en-US&ipa=%2Fd%C9%AA%CB%88ra%C9%AAv%2F"},{"id":"lv_5_94","topic":"Nature and Environmental Protection","word":"destination","pos":"(n)","ipa":"/ˌdɛs.təˈneɪ.ʃən/","defVi":"Điểm đến, nơi đến.","defEn":"The place to which someone or something is going or being sent.","examples":["Paris is one of the most popular tourist [destination]s in the world. (=Dịch: Paris là một trong những điểm đến du lịch nổi tiếng nhất trên thế giới.)","We finally arrived at our [destination] after a long flight. (=Dịch: Cuối cùng chúng tôi cũng đến được nơi sau một chuyến bay dài.)","The package will reach its final [destination] by tomorrow morning. (=Dịch: Kiện hàng sẽ đến điểm giao cuối cùng trước sáng mai.)"],"ukAudio":"/ai_services/tts3/?q=destination&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bs.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destination&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bs.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_95","topic":"Nature and Environmental Protection","word":"destruction","pos":"(n)","ipa":"/dɪˈstrʌk.ʃən/","defVi":"sự tàn phá, sự phá hủy","defEn":"the act or process of damaging something so badly that it no longer exists or cannot be repaired","examples":["The earthquake caused widespread [destruction] throughout the city. (=Dịch: Trận động đất đã gây ra sự tàn phá trên diện rộng khắp thành phố.)","Deforestation leads to the rapid [destruction] of natural wildlife habitats. (=Dịch: Nạn phá rừng dẫn đến sự phá hủy nhanh chóng môi trường sống tự nhiên của động vật hoang dã.)","Many historical buildings were saved from total [destruction] during the war. (=Dịch: Nhiều tòa nhà lịch sử đã được cứu khỏi sự phá hủy hoàn toàn trong chiến tranh.)"],"ukAudio":"/ai_services/tts3/?q=destruction&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destruction&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_5_96","topic":"Nature and Environmental Protection","word":"detailed","pos":"(adj)","ipa":"/dɪˈteɪld/","defVi":"chi tiết, tỉ mỉ","defEn":"giving a lot of information with many specific facts or aspects","examples":["The architect presented a [detailed] plan for the new library. (=Dịch: Kiến trúc sư đã trình bày một bản kế hoạch chi tiết cho thư viện mới.)","She gave a [detailed] account of what happened during the meeting. (=Dịch: Cô ấy đã kể lại chi tiết những gì đã xảy ra trong cuộc họp.)","Students need to follow the [detailed] instructions on the exam paper. (=Dịch: Học sinh cần tuân theo các hướng dẫn chi tiết trên đề thi.)"],"ukAudio":"/ai_services/tts3/?q=detailed&lang=en-GB&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=detailed&lang=en-US&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F"},{"id":"lv_5_97","topic":"Nature and Environmental Protection","word":"detect","pos":"(v)","ipa":"/dɪˈtekt/","defVi":"phát hiện, dò tìm ra","defEn":"to notice, discover, or identify the presence of something","examples":["Trained rescue dogs can [detect] survivors trapped beneath collapsed buildings. (=Dịch: Chó cứu hộ được huấn luyện có thể phát hiện những người sống sót bị mắc kẹt dưới các tòa nhà sụp đổ.)","Regular medical screenings help doctors [detect] serious diseases early. (=Dịch: Khám sức khỏe định kỳ giúp các bác sĩ phát hiện sớm các bệnh hiểm nghèo.)","The sensitive sensor failed to [detect] any smoke in the corridor. (=Dịch: Cảm biến nhạy bén đã không phát hiện thấy bất kỳ dấu hiệu khói nào trong hành lang.)"],"ukAudio":"/ai_services/tts3/?q=detect&lang=en-GB&ipa=%2Fd%C9%AA%CB%88tekt%2F","usAudio":"/ai_services/tts3/?q=detect&lang=en-US&ipa=%2Fd%C9%AA%CB%88tekt%2F"},{"id":"lv_5_98","topic":"Nature and Environmental Protection","word":"devastating","pos":"(adj)","ipa":"/ˈdɛv.əˌsteɪ.tɪŋ/","defVi":"tàn phá, hủy diệt, gây sốc nặng nề","defEn":"causing severe shock, distress, or immense damage","examples":["The earthquake had a [devastating] impact on the local infrastructure. (=Dịch: Trận động đất đã gây ra tác động tàn phá nặng nề đối với cơ sở hạ tầng địa phương.)","Losing his job was a [devastating] blow to his family's finances. (=Dịch: Mất việc là một cú sốc tàn khốc đối với tài chính của gia đình anh ấy.)","The flood had [devastating] effects on the agricultural sector. (=Dịch: Trận lũ lụt đã gây ra những hậu quả mang tính hủy diệt đối với ngành nông nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=devastating&lang=en-GB&ipa=%2F%CB%88d%C9%9Bv.%C9%99%CB%8Cste%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=devastating&lang=en-US&ipa=%2F%CB%88d%C9%9Bv.%C9%99%CB%8Cste%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_5_99","topic":"Nature and Environmental Protection","word":"diagram","pos":"(n)","ipa":"/ˈdaɪ.ə.ɡræm/","defVi":"sơ đồ, biểu đồ minh họa","defEn":"a simple drawing that explains how something works or shows the relationship between parts","examples":["The teacher drew a [diagram] on the board to explain the water cycle. (=Dịch: Giáo viên đã vẽ một sơ đồ lên bảng để giải thích vòng tuần hoàn của nước.)","Please refer to the [diagram] on page 12 for assembly instructions. (=Dịch: Vui lòng tham khảo sơ đồ ở trang 12 để biết hướng dẫn lắp ráp.)","This simple [diagram] illustrates how blood flows through the heart. (=Dịch: Sơ đồ đơn giản này minh họa cách máu lưu thông qua tim.)"],"ukAudio":"/ai_services/tts3/?q=diagram&lang=en-GB&ipa=%2F%CB%88da%C9%AA.%C9%99.%C9%A1r%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=diagram&lang=en-US&ipa=%2F%CB%88da%C9%AA.%C9%99.%C9%A1r%C3%A6m%2F"},{"id":"lv_5_100","topic":"Nature and Environmental Protection","word":"digestive","pos":"(adj)","ipa":"/daɪˈdʒes.tɪv/","defVi":"(thuộc) tiêu hóa","defEn":"relating to the digestion of food","examples":["Eating plenty of fiber supports a healthy [digestive] system. (=Dịch: Ăn nhiều chất xơ giúp hỗ trợ một hệ tiêu hóa khỏe mạnh.)","Certain spices can ease mild [digestive] problems after heavy meals. (=Dịch: Một số loại gia vị có thể làm giảm các vấn đề tiêu hóa nhẹ sau những bữa ăn nhiều dầu mỡ.)","Stomach acid plays a vital role in the human [digestive] process. (=Dịch: Axit dạ dày đóng một vai trò thiết yếu trong quá trình tiêu hóa của con người.)"],"ukAudio":"/ai_services/tts3/?q=digestive&lang=en-GB&ipa=%2Fda%C9%AA%CB%88d%CA%92es.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=digestive&lang=en-US&ipa=%2Fda%C9%AA%CB%88d%CA%92es.t%C9%AAv%2F"},{"id":"lv_5_101","topic":"Nature and Environmental Protection","word":"dioxide","pos":"(n)","ipa":"/daɪˈɑːk.saɪd/","defVi":"Điôxít (hợp chất oxit chứa hai nguyên tử oxy)","defEn":"An oxide containing two atoms of oxygen in each molecule","examples":["Plants absorb carbon [dioxide] from the atmosphere to perform photosynthesis. (=Dịch: Thực vật hấp thụ khí carbon điôxít từ khí quyển để tiến hành quang hợp.)","Sulfur [dioxide] emitted from industrial factories is a primary cause of acid rain. (=Dịch: Lưu huỳnh điôxít thải ra từ các nhà máy công nghiệp là nguyên nhân chính gây ra mưa axit.)","High levels of nitrogen [dioxide] can worsen respiratory problems in city residents. (=Dịch: Nồng độ nitơ điôxít cao có thể làm trầm trọng thêm các vấn đề về hô hấp ở cư dân thành phố.)"],"ukAudio":"/ai_services/tts3/?q=dioxide&lang=en-GB&ipa=%2Fda%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=dioxide&lang=en-US&ipa=%2Fda%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F"},{"id":"lv_5_102","topic":"Nature and Environmental Protection","word":"disappearance","pos":"(n)","ipa":"/ˌdɪs.əˈpɪr.əns/","defVi":"sự biến mất, sự mất tích","defEn":"the act or state of someone or something stopping being visible or existing","examples":["The sudden [disappearance] of the rare bird species puzzled local scientists. (=Dịch: Sự biến mất đột ngột của loài chim quý hiếm đã làm bối rối các nhà khoa học địa phương.)","Police are investigating the mysterious [disappearance] of a valuable painting from the gallery. (=Dịch: Cảnh sát đang điều tra sự biến mất bí ẩn của một bức tranh có giá trị khỏi phòng trưng bày.)","Deforestation has led to the [disappearance] of vast areas of natural habitat. (=Dịch: Nạn phá rừng đã dẫn đến sự biến mất của những vùng môi trường sống tự nhiên rộng lớn.)"],"ukAudio":"/ai_services/tts3/?q=disappearance&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%AAr.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=disappearance&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%AAr.%C9%99ns%2F"},{"id":"lv_5_103","topic":"Nature and Environmental Protection","word":"distribute","pos":"(v)","ipa":"/dɪˈstrɪb.jut/","defVi":"phân phát, phân phối, rải rác","defEn":"to give something out to several people, or to spread something over an area","examples":["Volunteers helped [distribute] food and water to the flood victims. (=Dịch: Các tình nguyện viên đã giúp phân phát thức ăn và nước uống cho các nạn nhân lũ lụt.)","The company plans to [distribute] its products to international markets next year. (=Dịch: Công ty dự định phân phối sản phẩm của mình sang các thị trường quốc tế vào năm tới.)","The teacher will [distribute] the test papers once everyone is seated. (=Dịch: Giáo viên sẽ phát đề thi khi mọi người đã ổn định chỗ ngồi.)"],"ukAudio":"/ai_services/tts3/?q=distribute&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%C9%AAb.jut%2F","usAudio":"/ai_services/tts3/?q=distribute&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%C9%AAb.jut%2F"},{"id":"lv_5_104","topic":"Nature and Environmental Protection","word":"distribution","pos":"(n)","ipa":"/ˌdɪs.trɪˈbju.ʃən/","defVi":"sự phân phối, sự phân bổ","defEn":"the way in which something is spread or shared over an area or among a group of people","examples":["The unequal [distribution] of wealth remains a major issue in many developing nations. (=Dịch: Sự phân bổ của cải không đồng đều vẫn là một vấn đề lớn ở nhiều quốc gia đang phát triển.)","The company established an efficient network for the [distribution] of medical supplies. (=Dịch: Công ty đã thiết lập một mạng lưới hiệu quả để phân phối các vật tư y tế.)","Scientists mapped the geographic [distribution] of native plant species across the region. (=Dịch: Các nhà khoa học đã lập bản đồ phân bố địa lý của các loài thực vật bản địa trên khắp khu vực.)"],"ukAudio":"/ai_services/tts3/?q=distribution&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%AA%CB%88bju.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=distribution&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%AA%CB%88bju.%CA%83%C9%99n%2F"},{"id":"lv_5_105","topic":"Nature and Environmental Protection","word":"diversity","pos":"(n)","ipa":"/daɪˈvɜːr.sə.t̬i/","defVi":"sự đa dạng, tính phong phú","defEn":"the state of having many different types, people, or things","examples":["Cultural [diversity] enriches society by introducing new perspectives and traditions. (=Dịch: Sự đa dạng văn hóa làm phong phú xã hội bằng cách mang lại những góc nhìn và truyền thống mới.)","The national park is famous for its rich biological [diversity]. (=Dịch: Vườn quốc gia này nổi tiếng với sự đa dạng sinh học phong phú.)","The company is committed to promoting [diversity] and inclusion in the workplace. (=Dịch: Công ty cam kết thúc đẩy sự đa dạng và hòa nhập tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=diversity&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9C%CB%90r.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=diversity&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9C%CB%90r.s%C9%99.t%CC%ACi%2F"},{"id":"lv_5_106","topic":"Nature and Environmental Protection","word":"dna","pos":"(n)","ipa":"/ˌdiː.enˈeɪ/","defVi":"ADN (axit đêôxiribônucleic, vật chất di truyền)","defEn":"the chemical at the center of cells that carries genetic information","examples":["Police collected [DNA] samples from the crime scene to identify the suspect. (=Dịch: Cảnh sát đã thu thập các mẫu ADN từ hiện trường vụ án để nhận diện nghi phạm.)","Modern tests can analyze your [DNA] to reveal your family origins. (=Dịch: Các xét nghiệm hiện đại có thể phân tích ADN của bạn để tiết lộ nguồn gốc dòng dõi gia đình.)","Scientists are studying how damage to [DNA] can lead to various diseases. (=Dịch: Các nhà khoa học đang nghiên cứu xem sự tổn thương của ADN có thể dẫn đến các bệnh khác nhau như thế nào.)"],"ukAudio":"/ai_services/tts3/?q=dna&lang=en-GB&ipa=%2F%CB%8Cdi%CB%90.en%CB%88e%C9%AA%2F","usAudio":"/ai_services/tts3/?q=dna&lang=en-US&ipa=%2F%CB%8Cdi%CB%90.en%CB%88e%C9%AA%2F"},{"id":"lv_5_107","topic":"Nature and Environmental Protection","word":"dolphin","pos":"(n)","ipa":"/ˈdɑːl.fɪn/","defVi":"cá heo","defEn":"a highly intelligent marine mammal that has a curved beak and a dorsal fin","examples":["We saw a playful [dolphin] jumping out of the water alongside our boat. (=Dịch: Chúng tôi nhìn thấy một chú cá heo tinh nghịch nhảy khỏi mặt nước bên cạnh thuyền của mình.)","The [dolphin] communicates with other members of its pod using complex whistle sounds. (=Dịch: Cá heo giao tiếp với các thành viên khác trong đàn bằng những âm thanh huýt sáo phức tạp.)","Scientists consider the [dolphin] to be one of the smartest creatures on Earth. (=Dịch: Các nhà khoa học coi cá heo là một trong những sinh vật thông minh nhất trên Trái Đất.)"],"ukAudio":"/ai_services/tts3/?q=dolphin&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=dolphin&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F"},{"id":"lv_5_108","topic":"Nature and Environmental Protection","word":"dramatic","pos":"(adj)","ipa":"/drə.ˈmæt̬.ɪk/","defVi":"Đột ngột, kịch tính, ấn tượng hoặc rõ rệt","defEn":"Sudden, very great, and often surprising; related to drama or theater.","examples":["There has been a [dramatic] increase in the price of fuel this year. (=Dịch: Đã có một sự gia tăng rõ rệt về giá nhiên liệu trong năm nay.)","Her speech had a [dramatic] effect on the entire audience. (=Dịch: Bài phát biểu của cô ấy đã tạo ra một hiệu ứng đầy ấn tượng đối với toàn bộ khán giả.)","The movie ended with a [dramatic] confrontation on the rooftop. (=Dịch: Bộ phim kết thúc bằng một cuộc đối đầu đầy kịch tính trên sân thượng.)"],"ukAudio":"/ai_services/tts3/?q=dramatic&lang=en-GB&ipa=%2Fdr%C9%99.%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dramatic&lang=en-US&ipa=%2Fdr%C9%99.%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_5_109","topic":"Nature and Environmental Protection","word":"drone","pos":"(n)","ipa":"/droʊn/","defVi":"máy bay không người lái","defEn":"an aircraft without a pilot that is controlled remotely or by onboard computers","examples":["The photographer used a [drone] to capture aerial views of the coastline. (=Dịch: Nhiếp ảnh gia đã sử dụng một chiếc máy bay không người lái để chụp quang cảnh bờ biển từ trên cao.)","Farmers are now deploying [drone] technology to monitor crop health efficiently. (=Dịch: Nông dân hiện đang triển khai công nghệ máy bay không người lái để theo dõi sức khỏe cây trồng một cách hiệu quả.)","The military deployed a [drone] for surveillance in remote areas. (=Dịch: Quân đội đã triển khai một máy bay không người lái để do thám ở các khu vực hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=drone&lang=en-GB&ipa=%2Fdro%CA%8An%2F","usAudio":"/ai_services/tts3/?q=drone&lang=en-US&ipa=%2Fdro%CA%8An%2F"},{"id":"lv_5_110","topic":"Nature and Environmental Protection","word":"drought","pos":"(n)","ipa":"/draʊt/","defVi":"hạn hán, tình trạng khô hạn kéo dài","defEn":"a long period of time when there is little or no rain, causing shortages of water","examples":["The prolonged [drought] caused rivers and reservoirs to completely dry up. (=Dịch: Đợt hạn hán kéo dài khiến các dòng sông và hồ chứa nước khô cạn hoàn toàn.)","Crops failed across the region due to an unprecedented summer [drought]. (=Dịch: Mùa màng thất bát trên toàn khu vực do một đợt hạn hán mùa hè chưa từng có.)","Residents were urged to conserve water as the severe [drought] showed no sign of ending. (=Dịch: Người dân được khuyến cáo tiết kiệm nước vì đợt hạn hán gay gắt chưa có dấu hiệu chấm dứt.)"],"ukAudio":"/ai_services/tts3/?q=drought&lang=en-GB&ipa=%2Fdra%CA%8At%2F","usAudio":"/ai_services/tts3/?q=drought&lang=en-US&ipa=%2Fdra%CA%8At%2F"},{"id":"lv_5_111","topic":"Nature and Environmental Protection","word":"dutch","pos":"(adj)","ipa":"/dʌtʃ/","defVi":"(thuộc) Hà Lan, người Hà Lan hoặc tiếng Hà Lan","defEn":"relating to the Netherlands, its people, or its language","examples":["Many tourists admire the classic [Dutch] architecture and picturesque canals of Amsterdam. (=Dịch: Nhiều du khách chiêm ngưỡng kiến trúc Hà Lan cổ điển và những con kênh đẹp như tranh vẽ của Amsterdam.)","The museum holds an impressive collection of seventeenth-century [Dutch] paintings. (=Dịch: Bảo tàng lưu giữ một bộ sưu tập ấn tượng gồm các bức tranh Hà Lan từ thế kỷ XVII.)","She studied [Dutch] engineering techniques for managing flood risks and building dikes. (=Dịch: Cô ấy đã nghiên cứu các kỹ thuật kỹ thuật của Hà Lan để quản lý rủi ro lũ lụt và xây dựng đê điều.)"],"ukAudio":"/ai_services/tts3/?q=dutch&lang=en-GB&ipa=%2Fd%CA%8Ct%CA%83%2F","usAudio":"/ai_services/tts3/?q=dutch&lang=en-US&ipa=%2Fd%CA%8Ct%CA%83%2F"},{"id":"lv_5_112","topic":"Nature and Environmental Protection","word":"earthworm","pos":"(n)","ipa":"/ˈɜːrθ.wɜːrm/","defVi":"con giun đất","defEn":"a long, thin creature with no bones that lives in the soil and helps improve it","examples":["The gardener noticed that the soil was rich because it was full of [earthworm] activity. (=Dịch: Người làm vườn nhận thấy đất rất màu mỡ vì có rất nhiều hoạt động của giun đất.)","An [earthworm] helps aerate the ground by burrowing through the soil. (=Dịch: Giun đất giúp làm tơi xốp đất bằng cách đào hang dưới lòng đất.)","After the heavy rain, many an [earthworm] crawled onto the wet pavement. (=Dịch: Sau cơn mưa lớn, nhiều con giun đất đã bò lên vỉa hè ẩm ướt.)"],"ukAudio":"/ai_services/tts3/?q=earthworm&lang=en-GB&ipa=%2F%CB%88%C9%9C%CB%90r%CE%B8.w%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=earthworm&lang=en-US&ipa=%2F%CB%88%C9%9C%CB%90r%CE%B8.w%C9%9C%CB%90rm%2F"},{"id":"lv_5_113","topic":"Nature and Environmental Protection","word":"eastern","pos":"(adj)","ipa":"/ˈis.tɚn/","defVi":"phía đông, thuộc về phương đông","defEn":"located in or facing toward the east, or characteristic of the east","examples":["The storm caused severe flooding along the [eastern] coast of the country. (=Dịch: Cơn bão đã gây ra lũ lụt nghiêm trọng dọc bờ biển phía đông của đất nước.)","Traditional [eastern] medicine often emphasizes a holistic approach to overall wellness. (=Dịch: Y học phương đông truyền thống thường nhấn mạnh phương pháp tiếp cận toàn diện đối với sức khỏe tổng thể.)","They decided to spend their summer vacation exploring ancient ruins in the [eastern] province. (=Dịch: Họ quyết định dành kỳ nghỉ hè để khám phá các tàn tích cổ xưa ở tỉnh phía đông.)"],"ukAudio":"/ai_services/tts3/?q=eastern&lang=en-GB&ipa=%2F%CB%88is.t%C9%9An%2F","usAudio":"/ai_services/tts3/?q=eastern&lang=en-US&ipa=%2F%CB%88is.t%C9%9An%2F"},{"id":"lv_5_114","topic":"Nature and Environmental Protection","word":"echo","pos":"(n)","ipa":"/ˈɛk.oʊ/","defVi":"tiếng vang, âm vang","defEn":"a sound that is heard again when sound waves bounce back from a surface","examples":["Her footsteps created a distinct [echo] in the vast, empty corridor. (=Dịch: Tiếng bước chân của cô ấy tạo ra âm vang rõ rệt trong hành lang rộng lớn và trống trải.)","The cavern was so large that every shout produced a long, haunting [echo]. (=Dịch: Hang động lớn đến mức mỗi tiếng hét đều tạo ra một tiếng vang dài và ám ảnh.)","The speaker's passionate words found a strong [echo] among the younger audience. (=Dịch: Những lời nói đầy nhiệt huyết của diễn giả đã tạo được sự đồng cảm mạnh mẽ trong lòng các khán giả trẻ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=echo&lang=en-GB&ipa=%2F%CB%88%C9%9Bk.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=echo&lang=en-US&ipa=%2F%CB%88%C9%9Bk.o%CA%8A%2F"},{"id":"lv_5_115","topic":"Nature and Environmental Protection","word":"ecosystem","pos":"(n)","ipa":"/ˈi.koʊˌsɪs.təm/","defVi":"hệ sinh thái","defEn":"all the living organisms in an area and the physical environment with which they interact","examples":["Pollution has caused severe damage to the delicate marine [ecosystem]. (=Dịch: Ô nhiễm đã gây ra thiệt hại nghiêm trọng cho hệ sinh thái biển mong manh.)","Every single species has a specific function within its natural [ecosystem]. (=Dịch: Mỗi loài sinh vật đều có một chức năng nhất định trong hệ sinh thái tự nhiên của nó.)","Deforestation poses an enormous threat to the local forest [ecosystem]. (=Dịch: Nạn phá rừng gây ra mối đe dọa to lớn đối với hệ sinh thái rừng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=ecosystem&lang=en-GB&ipa=%2F%CB%88i.ko%CA%8A%CB%8Cs%C9%AAs.t%C9%99m%2F","usAudio":"/ai_services/tts3/?q=ecosystem&lang=en-US&ipa=%2F%CB%88i.ko%CA%8A%CB%8Cs%C9%AAs.t%C9%99m%2F"},{"id":"lv_5_116","topic":"Nature and Environmental Protection","word":"edible","pos":"(adj)","ipa":"/ˈed.ə.bəl/","defVi":"có thể ăn được (không độc)","defEn":"suitable or safe for people to eat","examples":["Some wild mushrooms are [edible], but many others are extremely toxic. (=Dịch: Một số loại nấm dại có thể ăn được, nhưng nhiều loại khác lại vô cùng độc hại.)","The pastry chef decorated the wedding cake with delicate [edible] flowers. (=Dịch: Đầu bếp bánh ngọt đã trang trí chiếc bánh cưới bằng những bông hoa ăn được tinh tế.)","Researchers are developing [edible] packaging to reduce plastic waste. (=Dịch: Các nhà nghiên cứu đang phát triển bao bì ăn được để giảm thiểu rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=edible&lang=en-GB&ipa=%2F%CB%88ed.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=edible&lang=en-US&ipa=%2F%CB%88ed.%C9%99.b%C9%99l%2F"},{"id":"lv_5_117","topic":"Nature and Environmental Protection","word":"egypt","pos":"(n)","ipa":"/ˈiː.dʒɪpt/","defVi":"Ai Cập","defEn":"a country in northeastern Africa famous for its ancient civilization and monuments","examples":["Millions of tourists visit [Egypt] every year to see the ancient pyramids. (=Dịch: Hàng triệu du khách đến thăm Ai Cập mỗi năm để chiêm ngưỡng các kim tự tháp cổ đại.)","The Nile River has supported agriculture in [Egypt] for thousands of years. (=Dịch: Sông Nile đã nuôi dưỡng nền nông nghiệp ở Ai Cập suốt hàng ngàn năm qua.)","Historians study [Egypt] to understand the origins of early writing and engineering. (=Dịch: Các nhà sử học nghiên cứu Ai Cập để hiểu về nguồn gốc của chữ viết và kỹ thuật thời kỳ đầu.)"],"ukAudio":"/ai_services/tts3/?q=egypt&lang=en-GB&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=egypt&lang=en-US&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F"},{"id":"lv_5_118","topic":"Nature and Environmental Protection","word":"emission","pos":"(n)","ipa":"/ɪˈmɪʃ.ən/","defVi":"sự phát thải, khí thải","defEn":"the production and discharge of something, especially gas or radiation","examples":["The rapid increase in carbon [emission] contributes heavily to global warming. (=Dịch: Sự gia tăng nhanh chóng của lượng phát thải carbon góp phần lớn vào sự nóng lên toàn cầu.)","Strict laws were introduced to regulate vehicle exhaust [emission] in big cities. (=Dịch: Các luật lệ nghiêm ngặt đã được ban hành để kiểm soát khí thải từ phương tiện giao thông ở các thành phố lớn.)","Industrial [emission] must be treated properly before being released into the atmosphere. (=Dịch: Khí thải công nghiệp phải được xử lý đúng cách trước khi thải ra ngoài khí quyển.)"],"ukAudio":"/ai_services/tts3/?q=emission&lang=en-GB&ipa=%2F%C9%AA%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emission&lang=en-US&ipa=%2F%C9%AA%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_119","topic":"Nature and Environmental Protection","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, giúp cho, tạo điều kiện","defEn":"to give someone or something the ability, authority, or means to do something","examples":["Scholarships [enable] talented students from low-income families to attend university. (=Dịch: Học bổng giúp các sinh viên tài năng có hoàn cảnh khó khăn có thể theo học đại học.)","Technological advances [enable] scientists to collect data more efficiently. (=Dịch: Những tiến bộ công nghệ cho phép các nhà khoa học thu thập dữ liệu hiệu quả hơn.)","The new highway will [enable] faster travel between the two cities. (=Dịch: Tuyến đường cao tốc mới sẽ tạo điều kiện cho việc di chuyển nhanh hơn giữa hai thành phố.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_5_120","topic":"Nature and Environmental Protection","word":"endangered","pos":"(adj)","ipa":"/ɪnˈdeɪn.dʒərd/","defVi":"có nguy cơ tuyệt chủng, bị đe dọa","defEn":"in danger of being harmed, lost, or becoming extinct","examples":["The giant panda was once classified as an [endangered] species. (=Dịch: Gấu trúc khổng lồ từng bị xếp vào nhóm loài có nguy cơ tuyệt chủng.)","Deforestation has put many native animals on the [endangered] list. (=Dịch: Nạn phá rừng đã khiến nhiều loài động vật bản địa bị đưa vào danh sách nguy cấp.)","Conservationists work tirelessly to protect [endangered] habitats worldwide. (=Dịch: Các nhà bảo tồn làm việc không mệt mỏi để bảo vệ các môi trường sống bị đe dọa trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=endangered&lang=en-GB&ipa=%2F%C9%AAn%CB%88de%C9%AAn.d%CA%92%C9%99rd%2F","usAudio":"/ai_services/tts3/?q=endangered&lang=en-US&ipa=%2F%C9%AAn%CB%88de%C9%AAn.d%CA%92%C9%99rd%2F"},{"id":"lv_5_121","topic":"Nature and Environmental Protection","word":"enormously","pos":"(adv)","ipa":"/ɪˈnɔːr.məs.li/","defVi":"vô cùng, hết sức","defEn":"to a very great degree; extremely","examples":["Online learning has helped students [enormously] during the pandemic. (=Dịch: Học trực tuyến đã giúp ích vô cùng nhiều cho học sinh trong thời gian đại dịch.)","The cost of living has increased [enormously] in the capital city. (=Dịch: Chi phí sinh hoạt đã tăng lên rất nhiều ở thành phố thủ đô.)","Her public speaking skills improved [enormously] after the workshop. (=Dịch: Kỹ năng nói trước công chúng của cô ấy đã tiến bộ vượt bậc sau hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=enormously&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=enormously&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F"},{"id":"lv_5_122","topic":"Nature and Environmental Protection","word":"erosion","pos":"(n)","ipa":"/ɪˈroʊ.ʒən/","defVi":"sự xói mòn, sự bào mòn","defEn":"the gradual wearing away of rock or soil by the action of water, wind, or ice","examples":["Planting trees along riverbanks helps prevent soil [erosion]. (=Dịch: Trồng cây dọc theo bờ sông giúp ngăn ngừa xói mòn đất.)","Coastal [erosion] threatens many homes along the cliff edge. (=Dịch: Xói mòn bờ biển đang đe dọa nhiều ngôi nhà dọc theo mép vách đá.)","Wind and rain caused severe [erosion] to the ancient stone monument. (=Dịch: Gió và mưa đã gây ra sự bào mòn nghiêm trọng cho đài tưởng niệm bằng đá cổ kính.)"],"ukAudio":"/ai_services/tts3/?q=erosion&lang=en-GB&ipa=%2F%C9%AA%CB%88ro%CA%8A.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=erosion&lang=en-US&ipa=%2F%C9%AA%CB%88ro%CA%8A.%CA%92%C9%99n%2F"},{"id":"lv_5_123","topic":"Nature and Environmental Protection","word":"eruption","pos":"(n)","ipa":"/ɪˈrʌp.ʃən/","defVi":"sự phun trào (núi lửa), sự bùng nổ","defEn":"an act or instance of bursting forth, especially of a volcano","examples":["The sudden volcanic [eruption] forced thousands of residents to evacuate. (=Dịch: Vụ phun trào núi lửa bất ngờ đã buộc hàng ngàn cư dân phải sơ tán.)","Scientists monitor seismic activity to predict the next [eruption]. (=Dịch: Các nhà khoa học theo dõi hoạt động địa chấn để dự đoán đợt phun trào tiếp theo.)","The match ended with an [eruption] of cheers from the excited crowd. (=Dịch: Trận đấu kết thúc trong sự bùng nổ tiếng reo hò từ đám đông phấn khích.)"],"ukAudio":"/ai_services/tts3/?q=eruption&lang=en-GB&ipa=%2F%C9%AA%CB%88r%CA%8Cp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=eruption&lang=en-US&ipa=%2F%C9%AA%CB%88r%CA%8Cp.%CA%83%C9%99n%2F"},{"id":"lv_5_124","topic":"Nature and Environmental Protection","word":"ethanol","pos":"(n)","ipa":"/ˈeθ.ə.nɑːl/","defVi":"cồn ethanol, cồn etylic","defEn":"a type of alcohol often used as a biofuel or solvent","examples":["Many countries blend [ethanol] with gasoline to reduce greenhouse gas emissions. (=Dịch: Nhiều quốc gia pha trộn ethanol với xăng để giảm lượng khí thải nhà kính.)","The fuel contains ten percent [ethanol] derived from fermented corn. (=Dịch: Nhiên liệu này chứa mười phần trăm ethanol có nguồn gốc từ ngô lên men.)","Scientists are researching more sustainable ways to produce [ethanol] from agricultural waste. (=Dịch: Các nhà khoa học đang nghiên cứu những phương pháp bền vững hơn để sản xuất ethanol từ chất thải nông nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=ethanol&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%99.n%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=ethanol&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%99.n%C9%91%CB%90l%2F"},{"id":"lv_5_125","topic":"Nature and Environmental Protection","word":"european","pos":"(adj)","ipa":"/ˌjʊr.əˈpiː.ən/","defVi":"thuộc về châu Âu","defEn":"relating to the continent of Europe or its people","examples":["She has a strong interest in studying [European] history and art. (=Dịch: Cô ấy rất quan tâm đến việc nghiên cứu lịch sử và nghệ thuật châu Âu.)","Several [European] cities have introduced strict emission regulations for cars. (=Dịch: Một số thành phố châu Âu đã đưa ra các quy định nghiêm ngặt về khí thải đối với ô tô.)","The treaty aimed to strengthen cooperation among different [European] nations. (=Dịch: Hiệp ước nhằm tăng cường sự hợp tác giữa các quốc gia châu Âu khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=european&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=european&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F"},{"id":"lv_5_126","topic":"Nature and Environmental Protection","word":"europeans","pos":"(n)","ipa":"/ˌjʊr.əˈpiː.ənz/","defVi":"người châu Âu","defEn":"people who come from or live in Europe","examples":["Many [Europeans] travel to warmer countries during the winter months. (=Dịch: Nhiều người châu Âu đi du lịch đến các quốc gia ấm áp hơn trong những tháng mùa đông.)","Historically, [Europeans] established extensive trade networks across the globe. (=Dịch: Trong lịch sử, người châu Âu đã thiết lập các mạng lưới thương mại rộng lớn trên toàn cầu.)","Surveys show that [Europeans] place a high value on public healthcare systems. (=Dịch: Các cuộc khảo sát cho thấy người châu Âu rất coi trọng hệ thống chăm sóc sức khỏe cộng đồng.)"],"ukAudio":"/ai_services/tts3/?q=europeans&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F","usAudio":"/ai_services/tts3/?q=europeans&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F"},{"id":"lv_5_127","topic":"Nature and Environmental Protection","word":"evaporate","pos":"(v)","ipa":"/ɪˈvæp.ə.reɪt/","defVi":"bốc hơi, bay hơi","defEn":"to change from a liquid into gas or vapor; to disappear gradually","examples":["Puddles on the road begin to [evaporate] quickly once the sun comes out. (=Dịch: Những vũng nước trên đường bắt đầu bốc hơi nhanh chóng khi mặt trời ló rạng.)","Heat will cause the water in the pan to [evaporate] completely. (=Dịch: Nhiệt độ sẽ làm cho nước trong chảo bay hơi hoàn toàn.)","All his fears seemed to [evaporate] when he saw his family waiting for him. (=Dịch: Mọi nỗi sợ hãi của anh dường như tan biến khi anh thấy gia đình đang đợi mình.)"],"ukAudio":"/ai_services/tts3/?q=evaporate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaporate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F"},{"id":"lv_5_128","topic":"Nature and Environmental Protection","word":"evolutionary","pos":"(adj)","ipa":"/ˌev.əˈluː.ʃəˌner.i/","defVi":"thuộc về tiến hóa, mang tính tiến hóa","defEn":"relating to the gradual development of plants, animals, or ideas over time","examples":["Scientists study fossils to understand the [evolutionary] history of birds. (=Dịch: Các nhà khoa học nghiên cứu hóa thạch để hiểu rõ lịch sử tiến hóa của loài chim.)","The species developed sharp claws as an [evolutionary] adaptation for hunting. (=Dịch: Loài này đã phát triển móng vuốt sắc nhọn như một sự thích nghi tiến hóa để săn mồi.)","His theory explains the [evolutionary] changes in human behavior over centuries. (=Dịch: Lý thuyết của ông giải thích những thay đổi tiến hóa trong hành vi con người qua nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=evolutionary&lang=en-GB&ipa=%2F%CB%8Cev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99%CB%8Cner.i%2F","usAudio":"/ai_services/tts3/?q=evolutionary&lang=en-US&ipa=%2F%CB%8Cev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99%CB%8Cner.i%2F"},{"id":"lv_5_129","topic":"Nature and Environmental Protection","word":"examination","pos":"(n)","ipa":"/ɪɡˌzæm.əˈneɪ.ʃən/","defVi":"sự kiểm tra, sự xem xét kỹ lưỡng; kỳ thi","defEn":"a detailed inspection, study, or test of knowledge or ability","examples":["A thorough medical [examination] revealed no serious underlying health problems. (=Dịch: Một cuộc kiểm tra y tế kỹ lưỡng cho thấy không có vấn đề sức khỏe tiềm ẩn nghiêm trọng nào.)","Candidates must prepare thoroughly before taking the final entrance [examination]. (=Dịch: Các thí sinh phải chuẩn bị kỹ lưỡng trước khi tham gia kỳ thi tuyển sinh cuối cùng.)","Close [examination] of the forensic evidence provided vital clues for the detectives. (=Dịch: Sự xem xét kỹ lưỡng bằng chứng pháp y đã cung cấp những manh mối quan trọng cho các thám tử.)"],"ukAudio":"/ai_services/tts3/?q=examination&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%8Cz%C3%A6m.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=examination&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%8Cz%C3%A6m.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_130","topic":"Nature and Environmental Protection","word":"existence","pos":"(n)","ipa":"/ɪɡˈzɪs.təns/","defVi":"sự tồn tại, sự hiện diện","defEn":"the state or fact of living or being real","examples":["Many scientists believe in the [existence] of water on other planets. (=Dịch: Nhiều nhà khoa học tin vào sự tồn tại của nước trên các hành tinh khác.)","Pollution poses a serious threat to the continued [existence] of marine wildlife. (=Dịch: Ô nhiễm đe dọa nghiêm trọng đến sự tồn tại lâu dài của động vật hoang dã biển.)","The ancient monument has been in [existence] for more than two thousand years. (=Dịch: Di tích cổ này đã tồn tại hơn hai nghìn năm.)"],"ukAudio":"/ai_services/tts3/?q=existence&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAs.t%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=existence&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAs.t%C9%99ns%2F"},{"id":"lv_5_131","topic":"Nature and Environmental Protection","word":"expansion","pos":"(n)","ipa":"/ɪkˈspæn.ʃən/","defVi":"sự mở rộng, sự bành trướng, sự phát triển","defEn":"the act of becoming larger or spreading out in size, area, or volume","examples":["The company announced the [expansion] of its retail network into Asia. (=Dịch: Công ty đã công bố việc mở rộng mạng lưới bán lẻ sang châu Á.)","Rapid urban [expansion] can lead to severe environmental problems. (=Dịch: Sự mở rộng đô thị nhanh chóng có thể dẫn đến các vấn đề môi trường nghiêm trọng.)","Thermal [expansion] causes metal rails to lengthen in hot weather. (=Dịch: Sự giãn nở vì nhiệt làm cho đường ray kim loại dài ra trong thời tiết nóng.)"],"ukAudio":"/ai_services/tts3/?q=expansion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sp%C3%A6n.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expansion&lang=en-US&ipa=%2F%C9%AAk%CB%88sp%C3%A6n.%CA%83%C9%99n%2F"},{"id":"lv_5_132","topic":"Nature and Environmental Protection","word":"expedition","pos":"(n)","ipa":"/ˌɛk.spəˈdɪʃ.ən/","defVi":"cuộc thám hiểm, chuyến khảo sát","defEn":"an organized journey made for a particular purpose, especially exploration or scientific research","examples":["The scientists launched an [expedition] to explore the uncharted rainforest. (=Dịch: Các nhà khoa học đã phát động một cuộc thám hiểm để khám phá khu rừng nhiệt đới chưa được lập bản đồ.)","He documented his Arctic [expedition] through a series of photographs. (=Dịch: Anh ấy đã ghi lại chuyến thám hiểm Bắc Cực của mình qua một loạt các bức ảnh.)","The team packed specialized gear for their upcoming climbing [expedition]. (=Dịch: Cả đội đã đóng gói các thiết bị chuyên dụng cho chuyến thám hiểm leo núi sắp tới của họ.)"],"ukAudio":"/ai_services/tts3/?q=expedition&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%99%CB%88d%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expedition&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%99%CB%88d%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_133","topic":"Nature and Environmental Protection","word":"exploit","pos":"(v)","ipa":"/ɪk.ˈsplɔɪt/","defVi":"khai thác, tận dụng","defEn":"to use something fully in order to get an advantage or profit","examples":["The company aims to [exploit] renewable energy sources like wind and solar power. (=Dịch: Công ty đặt mục tiêu khai thác các nguồn năng lượng tái tạo như năng lượng gió và mặt trời.)","It is unethical to [exploit] vulnerable workers for cheap labor. (=Dịch: Bóc lột những người lao động yếu thế để có nhân công giá rẻ là hành vi phi đạo đức.)","The software developer found a way to [exploit] the system's security loophole. (=Dịch: Nhà phát triển phần mềm đã tìm ra cách khai thác lỗ hổng bảo mật của hệ thống.)"],"ukAudio":"/ai_services/tts3/?q=exploit&lang=en-GB&ipa=%2F%C9%AAk.%CB%88spl%C9%94%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exploit&lang=en-US&ipa=%2F%C9%AAk.%CB%88spl%C9%94%C9%AAt%2F"},{"id":"lv_5_134","topic":"Nature and Environmental Protection","word":"exploration","pos":"(n)","ipa":"/ˌek.spləˈreɪ.ʃən/","defVi":"sự thám hiểm, sự thăm dò, sự khám phá","defEn":"the action of traveling through an unfamiliar area in order to learn about it","examples":["Space [exploration] requires significant financial investment and advanced technology. (=Dịch: Thám hiểm không gian đòi hỏi sự đầu tư tài chính lớn cùng công nghệ tiên tiến.)","The deep-sea [exploration] team discovered several new marine species. (=Dịch: Đội thám hiểm biển sâu đã phát hiện ra một số loài sinh vật biển mới.)","Oil [exploration] in the arctic region remains highly controversial. (=Dịch: Hoạt động thăm dò dầu khí ở vùng Bắc Cực vẫn còn gây nhiều tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=exploration&lang=en-GB&ipa=%2F%CB%8Cek.spl%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=exploration&lang=en-US&ipa=%2F%CB%8Cek.spl%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_135","topic":"Nature and Environmental Protection","word":"explorer","pos":"(n)","ipa":"/ɪkˈsplɔːr.ɚ/","defVi":"nhà thám hiểm","defEn":"a person who travels to unfamiliar places in order to discover new things","examples":["The brave [explorer] ventured deep into the uncharted regions of the Amazon rainforest. (=Dịch: Nhà thám hiểm dũng cảm đã dấn thân sâu vào những vùng chưa được khám phá của rừng nhiệt đới Amazon.)","Every modern [explorer] relies on advanced satellite navigation and survival gear. (=Dịch: Mỗi nhà thám hiểm hiện đại đều dựa vào hệ thống định vị vệ tinh tiên tiến và thiết bị sinh tồn.)","The museum displays journals written by an Arctic [explorer] during his expeditions. (=Dịch: Bảo tàng trưng bày các cuốn nhật ký được viết bởi một nhà thám hiểm Bắc Cực trong các chuyến hành trình của ông.)"],"ukAudio":"/ai_services/tts3/?q=explorer&lang=en-GB&ipa=%2F%C9%AAk%CB%88spl%C9%94%CB%90r.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=explorer&lang=en-US&ipa=%2F%C9%AAk%CB%88spl%C9%94%CB%90r.%C9%9A%2F"},{"id":"lv_5_136","topic":"Nature and Environmental Protection","word":"expose","pos":"(v)","ipa":"/ɪkˈspoʊz/","defVi":"phơi bày, để lộ, tiếp xúc với","defEn":"to leave something uncovered or unprotected, especially to something harmful","examples":["Do not [expose] your skin to direct sunlight for extended periods. (=Dịch: Đừng phơi da dưới ánh nắng trực tiếp trong thời gian dài.)","The documentary aimed to [expose] corruption within the local government. (=Dịch: Bộ phim tài liệu nhằm mục đích vạch trần nạn tham nhũng trong chính quyền địa phương.)","Living abroad will [expose] students to diverse cultures and traditions. (=Dịch: Sống ở nước ngoài sẽ giúp sinh viên tiếp xúc với các nền văn hóa và truyền thống đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=expose&lang=en-GB&ipa=%2F%C9%AAk%CB%88spo%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=expose&lang=en-US&ipa=%2F%C9%AAk%CB%88spo%CA%8Az%2F"},{"id":"lv_5_137","topic":"Nature and Environmental Protection","word":"extensive","pos":"(adj)","ipa":"/ɪkˈsten.sɪv/","defVi":"sâu rộng, quy mô lớn, bao quát","defEn":"covering a large area; having a wide scope or range","examples":["The storm caused [extensive] damage to the coastal town. (=Dịch: Cơn bão đã gây ra thiệt hại trên diện rộng cho thị trấn ven biển.)","She has [extensive] knowledge of international copyright law. (=Dịch: Cô ấy có kiến thức sâu rộng về luật bản quyền quốc tế.)","The building underwent [extensive] renovations before reopening. (=Dịch: Tòa nhà đã trải qua quá trình cải tạo quy mô lớn trước khi mở cửa trở lại.)"],"ukAudio":"/ai_services/tts3/?q=extensive&lang=en-GB&ipa=%2F%C9%AAk%CB%88sten.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=extensive&lang=en-US&ipa=%2F%C9%AAk%CB%88sten.s%C9%AAv%2F"},{"id":"lv_5_138","topic":"Nature and Environmental Protection","word":"extinct","pos":"(adj)","ipa":"/ɪkˈstɪŋkt/","defVi":"tuyệt chủng","defEn":"no longer existing or living anywhere in the world","examples":["Dinosaurs became [extinct] millions of years ago. (=Dịch: Khủng long đã tuyệt chủng hàng triệu năm trước.)","Deforestation threatens to drive several rare amphibians [extinct]. (=Dịch: Nạn phá rừng đe dọa đẩy một số loài lưỡng cư quý hiếm vào cảnh tuyệt chủng.)","Conservationists are working tirelessly to prevent the tiger from becoming [extinct]. (=Dịch: Các nhà bảo tồn đang nỗ lực không ngừng nghỉ để ngăn loài hổ khỏi bị tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=extinct&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bkt%2F","usAudio":"/ai_services/tts3/?q=extinct&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bkt%2F"},{"id":"lv_5_139","topic":"Nature and Environmental Protection","word":"extinction","pos":"(n)","ipa":"/ɪkˈstɪŋk.ʃən/","defVi":"sự tuyệt chủng","defEn":"the state or situation that results when a species no longer has any living members","examples":["Poaching and habitat loss have driven several rhino species close to [extinction]. (=Dịch: Nạn săn trộm và mất môi trường sống đã đẩy một số loài tê giác đến bờ vực tuyệt chủng.)","Scientists fear that climate change could trigger a mass [extinction] event. (=Dịch: Các nhà khoa học lo ngại rằng biến đổi khí hậu có thể châm ngòi cho một sự kiện tuyệt chủng hàng loạt.)","Conservation programs aim to save endangered sea turtles from total [extinction]. (=Dịch: Các chương trình bảo tồn nhằm cứu các loài rùa biển có nguy cơ tuyệt chủng khỏi sự tuyệt chủng hoàn toàn.)"],"ukAudio":"/ai_services/tts3/?q=extinction&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=extinction&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_5_140","topic":"Nature and Environmental Protection","word":"extract","pos":"(v)","ipa":"/ɪkˈstrækt/","defVi":"chiết xuất, rút ra, khai thác","defEn":"to remove or obtain a substance from something by a special method","examples":["Specialists use modern techniques to [extract] essential oils from fresh flowers. (=Dịch: Các chuyên gia sử dụng các kỹ thuật hiện đại để chiết xuất tinh dầu từ hoa tươi.)","The mining corporation plans to [extract] valuable minerals from the mountain range. (=Dịch: Tập đoàn khai thác mỏ có kế hoạch khai thác các khoáng sản quý giá từ dãy núi.)","Researchers hope to [extract] useful data from the completed survey responses. (=Dịch: Các nhà nghiên cứu hy vọng sẽ trích xuất được dữ liệu hữu ích từ các câu trả lời khảo sát đã hoàn thành.)"],"ukAudio":"/ai_services/tts3/?q=extract&lang=en-GB&ipa=%2F%C9%AAk%CB%88str%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=extract&lang=en-US&ipa=%2F%C9%AAk%CB%88str%C3%A6kt%2F"},{"id":"lv_5_141","topic":"Nature and Environmental Protection","word":"facial","pos":"(adj)","ipa":"/ˈfeɪ.ʃəl/","defVi":"thuộc về khuôn mặt","defEn":"connected with or located on a person's face","examples":["Modern smartphones use [facial] recognition to unlock the screen. (=Dịch: Điện thoại thông minh hiện đại sử dụng tính năng nhận diện khuôn mặt để mở khóa màn hình.)","His subtle [facial] expressions showed that he was not fully convinced. (=Dịch: Những biểu cảm khuôn mặt tinh tế của anh ấy cho thấy anh chưa hoàn toàn bị thuyết phục.)","She visited the spa yesterday for a relaxing [facial] treatment. (=Dịch: Hôm qua cô ấy đã đến spa để thực hiện một liệu trình chăm sóc da mặt thư giãn.)"],"ukAudio":"/ai_services/tts3/?q=facial&lang=en-GB&ipa=%2F%CB%88fe%C9%AA.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=facial&lang=en-US&ipa=%2F%CB%88fe%C9%AA.%CA%83%C9%99l%2F"},{"id":"lv_5_142","topic":"Nature and Environmental Protection","word":"feather","pos":"(n)","ipa":"/ˈfeð.ɚ/","defVi":"lông vũ, lông chim","defEn":"one of the soft, light structures that grow from a bird's skin and form its plumage","examples":["She picked up a beautiful peacock [feather] from the forest floor. (=Dịch: Cô ấy nhặt được một chiếc lông công xinh đẹp từ nền rừng.)","Each [feather] helps keep the bird warm and enables it to fly smoothly. (=Dịch: Mỗi chiếc lông vũ giúp giữ ấm cho chim và giúp nó bay lượn êm ái.)","The pillow was stuffed with soft duck [feather] down. (=Dịch: Chiếc gối được nhồi bằng lông tơ vịt mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=feather&lang=en-GB&ipa=%2F%CB%88fe%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=feather&lang=en-US&ipa=%2F%CB%88fe%C3%B0.%C9%9A%2F"},{"id":"lv_5_143","topic":"Nature and Environmental Protection","word":"fertile","pos":"(adj)","ipa":"/ˈfɜːr.təl/","defVi":"màu mỡ, phì nhiêu; có khả năng sinh sản","defEn":"able to produce good crops or plants, or capable of producing offspring","examples":["The river valley has extremely [fertile] soil that supports agriculture. (=Dịch: Thung lũng ven sông có đất đai vô cùng màu mỡ hỗ trợ canh tác nông nghiệp.)","A warm climate and [fertile] ground allow farmers to harvest multiple crops a year. (=Dịch: Khí hậu ấm áp và đất đai màu mỡ cho phép nông dân thu hoạch nhiều vụ mùa mỗi năm.)","Scientists are researching how to keep farmland [fertile] without excessive chemical use. (=Dịch: Các nhà khoa học đang nghiên cứu cách giữ cho đất trồng trọt luôn màu mỡ mà không cần lạm dụng hóa chất.)"],"ukAudio":"/ai_services/tts3/?q=fertile&lang=en-GB&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fertile&lang=en-US&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l%2F"},{"id":"lv_5_144","topic":"Nature and Environmental Protection","word":"fertiliser","pos":"(n)","ipa":"/ˈfɜːr.təl.aɪ.zər/","defVi":"phân bón","defEn":"a natural or chemical substance added to soil to help plants grow","examples":["Farmers use chemical [fertiliser] to increase their crop yields. (=Dịch: Nông dân sử dụng phân bón hóa học để tăng năng suất cây trồng.)","Excessive use of [fertiliser] can contaminate local water sources. (=Dịch: Việc sử dụng phân bón quá mức có thể làm ô nhiễm các nguồn nước địa phương.)","Organic compost serves as an excellent natural [fertiliser]. (=Dịch: Phân hữu cơ ủ mục đóng vai trò như một loại phân bón tự nhiên tuyệt vời.)"],"ukAudio":"/ai_services/tts3/?q=fertiliser&lang=en-GB&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l.a%C9%AA.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=fertiliser&lang=en-US&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l.a%C9%AA.z%C9%99r%2F"},{"id":"lv_5_145","topic":"Nature and Environmental Protection","word":"fig","pos":"(n)","ipa":"/fɪɡ/","defVi":"quả sung ngọt, quả vả","defEn":"a soft, sweet fruit with many small seeds, often eaten fresh or dried","examples":["Fresh [fig] pairs exceptionally well with goat cheese and honey. (=Dịch: Quả sung ngọt tươi kết hợp rất tuyệt vời với phô mai dê và mật ong.)","They planted a [fig] tree in the sunniest corner of their backyard. (=Dịch: Họ đã trồng một cây sung ngọt ở góc nhiều nắng nhất trong sân sau.)","Dried [fig] slices make a healthy and convenient snack during long hikes. (=Dịch: Những lát sung ngọt sấy khô là món ăn nhẹ lành mạnh và tiện lợi trong các chuyến đi bộ dài.)"],"ukAudio":"/ai_services/tts3/?q=fig&lang=en-GB&ipa=%2Ff%C9%AA%C9%A1%2F","usAudio":"/ai_services/tts3/?q=fig&lang=en-US&ipa=%2Ff%C9%AA%C9%A1%2F"},{"id":"lv_5_146","topic":"Nature and Environmental Protection","word":"fin","pos":"(n)","ipa":"/fɪn/","defVi":"vây cá","defEn":"a thin, flat part that sticks out from the body of a fish, used for swimming and balance","examples":["The shark cut through the water with its dorsal [fin] clearly visible above the surface. (=Dịch: Con cá mập rẽ nước bơi với vây lưng lộ rõ trên mặt nước.)","A fish uses its [fin] to steer and maintain balance while swimming. (=Dịch: Cá sử dụng vây để chuyển hướng và giữ thăng bằng khi bơi.)","Scuba divers wear a swim [fin] on each foot to move through the water more easily. (=Dịch: Thợ lặn đeo vây bơi ở mỗi bàn chân để di chuyển dưới nước dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=fin&lang=en-GB&ipa=%2Ff%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=fin&lang=en-US&ipa=%2Ff%C9%AAn%2F"},{"id":"lv_5_147","topic":"Nature and Environmental Protection","word":"firm","pos":"(n)","ipa":"/fɜːrm/","defVi":"công ty, hãng","defEn":"a business organization or company, especially one providing professional services","examples":["She recently joined a prestigious law [firm] in downtown Chicago. (=Dịch: Gần đây cô ấy đã gia nhập một công ty luật danh tiếng ở trung tâm thành phố Chicago.)","The architectural [firm] designed several award-winning public libraries. (=Dịch: Công ty kiến trúc đã thiết kế một số thư viện công cộng từng đạt giải thưởng.)","He spent ten years working for an international accounting [firm]. (=Dịch: Anh ấy đã dành mười năm làm việc cho một công ty kiểm toán quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=firm&lang=en-GB&ipa=%2Ff%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=firm&lang=en-US&ipa=%2Ff%C9%9C%CB%90rm%2F"},{"id":"lv_5_148","topic":"Nature and Environmental Protection","word":"flooding","pos":"(n)","ipa":"/ˈflʌd.ɪŋ/","defVi":"nạn ngập lụt, tình trạng ngập úng","defEn":"a situation in which an area becomes covered with water, usually after heavy rain","examples":["Poor drainage systems often cause severe [flooding] in the city during storms. (=Dịch: Hệ thống thoát nước kém thường gây ngập lụt nghiêm trọng trong thành phố vào mùa bão.)","The low-lying coastal areas are extremely vulnerable to seasonal [flooding]. (=Dịch: Các vùng ven biển trũng thấp rất dễ bị tổn thương trước tình trạng ngập lụt theo mùa.)","Authorities issued warnings about flash [flooding] after continuous torrential rain. (=Dịch: Chính quyền đã phát đi cảnh báo về lũ quét sau những đợt mưa xối xả kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=flooding&lang=en-GB&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=flooding&lang=en-US&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F"},{"id":"lv_5_149","topic":"Nature and Environmental Protection","word":"fluid","pos":"(adj)","ipa":"/ˈflu.ɪd/","defVi":"linh hoạt, uyển chuyển; dễ thay đổi","defEn":"smooth, continuous, and easy; or likely to change easily","examples":["The dancer's movements were remarkably [fluid] and graceful. (=Dịch: Những động tác của vũ công vô cùng uyển chuyển và duyên dáng.)","The political situation in the region remains highly [fluid]. (=Dịch: Tình hình chính trị trong khu vực vẫn còn biến động rất nhiều.)","He switched between languages with [fluid] ease during the meeting. (=Dịch: Anh ấy chuyển đổi giữa các ngôn ngữ một cách trôi chảy và dễ dàng trong cuộc họp.)"],"ukAudio":"/ai_services/tts3/?q=fluid&lang=en-GB&ipa=%2F%CB%88flu.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=fluid&lang=en-US&ipa=%2F%CB%88flu.%C9%AAd%2F"},{"id":"lv_5_150","topic":"Nature and Environmental Protection","word":"fog","pos":"(n)","ipa":"/fɑːɡ/","defVi":"sương mù","defEn":"a thick cloud of tiny water droplets suspended in the air near the earth's surface that reduces visibility","examples":["The morning [fog] made it difficult for drivers to see more than a few meters ahead. (=Dịch: Lớp sương mù buổi sáng khiến các tài xế khó nhìn xa hơn vài mét.)","Flights were delayed because dense [fog] covered the airport runway. (=Dịch: Các chuyến bay bị hoãn vì sương mù dày đặc bao phủ đường băng sân bay.)","By midday, the sun came out and the [fog] began to clear. (=Dịch: Đến trưa, mặt trời ló dạng và sương mù bắt đầu tan dần.)"],"ukAudio":"/ai_services/tts3/?q=fog&lang=en-GB&ipa=%2Ff%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=fog&lang=en-US&ipa=%2Ff%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_151","topic":"Nature and Environmental Protection","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập lại","defEn":"to bend one part of something over another part so that it becomes smaller or neater","examples":["Please help me [fold] the clean laundry and put it into the drawer. (=Dịch: Làm ơn giúp tôi gấp quần áo sạch và cất vào ngăn kéo nhé.)","She took a piece of paper and began to [fold] it into an origami bird. (=Dịch: Cô ấy lấy một mảnh giấy và bắt đầu gấp nó thành một con chim origami.)","You should [fold] the map carefully before putting it back into your bag. (=Dịch: Bạn nên gấp tấm bản đồ lại cẩn thận trước khi cất nó vào túi.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_5_152","topic":"Nature and Environmental Protection","word":"footwear","pos":"(n)","ipa":"/ˈfʊt.wɛr/","defVi":"Giày dép, đồ đi chân.","defEn":"Things that people wear on their feet, such as shoes, boots, and sandals.","examples":["You should wear appropriate [footwear] when hiking in the mountains. (=Dịch: Bạn nên mang giày dép phù hợp khi đi bộ đường dài trên núi.)","The store offers a wide selection of sports [footwear]. (=Dịch: Cửa hàng cung cấp nhiều lựa chọn về các loại giày dép thể thao.)","Comfortable [footwear] is essential for people who stand all day. (=Dịch: Giày dép thoải mái là điều thiết yếu đối với những người phải đứng cả ngày.)"],"ukAudio":"/ai_services/tts3/?q=footwear&lang=en-GB&ipa=%2F%CB%88f%CA%8At.w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=footwear&lang=en-US&ipa=%2F%CB%88f%CA%8At.w%C9%9Br%2F"},{"id":"lv_5_153","topic":"Nature and Environmental Protection","word":"fossil","pos":"(n)","ipa":"/ˈfɑː.səl/","defVi":"hóa thạch","defEn":"the preserved remains or traces of an ancient plant or animal embedded in rock","examples":["The museum display featured a remarkably intact dinosaur [fossil]. (=Dịch: Khu trưng bày của bảo tàng có một mẫu hóa thạch khủng long còn nguyên vẹn đáng kinh ngạc.)","Geologists discovered a marine [fossil] high up in the mountain range. (=Dịch: Các nhà địa chất đã phát hiện ra một hóa thạch sinh vật biển ở tít trên dãy núi cao.)","Burning [fossil] fuels contributes significantly to global greenhouse gas emissions. (=Dịch: Việc đốt nhiên liệu hóa thạch đóng góp đáng kể vào lượng khí thải nhà kính toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=fossil&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fossil&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90.s%C9%99l%2F"},{"id":"lv_5_154","topic":"Nature and Environmental Protection","word":"freeze","pos":"(v)","ipa":"/friːz/","defVi":"Đóng băng; làm đông lạnh.","defEn":"To turn into ice or a solid state as a result of extreme cold.","examples":["Water will [freeze] and expand when the temperature drops to zero degrees Celsius. (=Dịch: Nước sẽ đóng băng và giãn nở khi nhiệt độ giảm xuống không độ C.)","You can [freeze] leftover soup to enjoy at a later date. (=Dịch: Bạn có thể đông lạnh phần súp còn thừa để thưởng thức sau này.)","The lake began to [freeze] as soon as the severe cold snap arrived. (=Dịch: Mặt hồ bắt đầu đóng băng ngay khi đợt rét đậm ập đến.)"],"ukAudio":"/ai_services/tts3/?q=freeze&lang=en-GB&ipa=%2Ffri%CB%90z%2F","usAudio":"/ai_services/tts3/?q=freeze&lang=en-US&ipa=%2Ffri%CB%90z%2F"},{"id":"lv_5_155","topic":"Nature and Environmental Protection","word":"frequency","pos":"(n)","ipa":"/ˈfri.kwən.si/","defVi":"tần suất, tần số","defEn":"the rate at which something happens or is repeated over a particular period","examples":["The [frequency] of natural disasters has increased in recent years. (=Dịch: Tần suất xảy ra các thảm họa thiên nhiên đã gia tăng trong những năm gần đây.)","You should adjust the [frequency] of your workouts based on your fitness level. (=Dịch: Bạn nên điều chỉnh tần suất tập luyện dựa trên thể lực của mình.)","The radio station operates on a very high [frequency]. (=Dịch: Trạm phát thanh hoạt động ở một tần số rất cao.)"],"ukAudio":"/ai_services/tts3/?q=frequency&lang=en-GB&ipa=%2F%CB%88fri.kw%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=frequency&lang=en-US&ipa=%2F%CB%88fri.kw%C9%99n.si%2F"},{"id":"lv_5_156","topic":"Nature and Environmental Protection","word":"frequent","pos":"(adj)","ipa":"/ˈfriː.kwənt/","defVi":"thường xuyên, hay xảy ra","defEn":"happening often or repeating at short intervals","examples":["He is a [frequent] traveler on international flights for business. (=Dịch: Anh ấy là hành khách thường xuyên trên các chuyến bay quốc tế phục vụ công việc.)","The coastal region experiences [frequent] storms during the autumn months. (=Dịch: Khu vực ven biển thường xuyên hứng chịu bão trong những tháng mùa thu.)","Making [frequent] mistakes is a completely normal part of learning a new skill. (=Dịch: Mắc lỗi thường xuyên là một phần hoàn toàn bình thường khi học một kỹ năng mới.)"],"ukAudio":"/ai_services/tts3/?q=frequent&lang=en-GB&ipa=%2F%CB%88fri%CB%90.kw%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=frequent&lang=en-US&ipa=%2F%CB%88fri%CB%90.kw%C9%99nt%2F"},{"id":"lv_5_157","topic":"Nature and Environmental Protection","word":"frighten","pos":"(v)","ipa":"/ˈfraɪ.tən/","defVi":"làm hoảng sợ, dọa dẫm","defEn":"to make someone feel afraid or shocked","examples":["Sudden loud noises can easily [frighten] young children. (=Dịch: Những tiếng động lớn bất ngờ có thể dễ dàng làm trẻ nhỏ hoảng sợ.)","The dark forest did not [frighten] the brave explorer. (=Dịch: Khu rừng tăm tối không hề làm nhà thám hiểm dũng cảm sợ hãi.)","They tried to [frighten] away the birds with a scarecrow. (=Dịch: Họ đã cố gắng xua đuổi lũ chim bằng một con bù nhìn.)"],"ukAudio":"/ai_services/tts3/?q=frighten&lang=en-GB&ipa=%2F%CB%88fra%C9%AA.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=frighten&lang=en-US&ipa=%2F%CB%88fra%C9%AA.t%C9%99n%2F"},{"id":"lv_5_158","topic":"Nature and Environmental Protection","word":"gardener","pos":"(n)","ipa":"/ˈɡɑːr.dən.ɚ/","defVi":"người làm vườn","defEn":"a person who tends, cultivates, and cares for a garden","examples":["The [gardener] pruned the rose bushes to encourage new spring blooms. (=Dịch: Người làm vườn đã cắt tỉa các bụi hoa hồng để kích thích hoa nở vào mùa xuân.)","She hired a skilled [gardener] to design a sustainable landscape. (=Dịch: Cô ấy đã thuê một người làm vườn có tay nghề để thiết kế cảnh quan bền vững.)","An experienced [gardener] knows exactly when to plant each type of vegetable. (=Dịch: Một người làm vườn giàu kinh nghiệm biết chính xác khi nào nên gieo trồng từng loại rau củ.)"],"ukAudio":"/ai_services/tts3/?q=gardener&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gardener&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%9A%2F"},{"id":"lv_5_159","topic":"Nature and Environmental Protection","word":"gene","pos":"(n)","ipa":"/dʒiːn/","defVi":"gen (đơn vị di truyền)","defEn":"a basic unit of heredity made of DNA that determines particular traits","examples":["Scientists identified the specific [gene] responsible for drought resistance in crops. (=Dịch: Các nhà khoa học đã xác định được gen cụ thể quy định khả năng chịu hạn ở cây trồng.)","Children inherit each [gene] from a combination of both biological parents. (=Dịch: Trẻ em thừa hưởng mỗi gen từ sự kết hợp của cả cha lẫn mẹ ruột.)","Advances in [gene] editing offer new possibilities for curing inherited disorders. (=Dịch: Những tiến bộ trong chỉnh sửa gen mở ra những tiềm năng mới để chữa các rối loạn di truyền.)"],"ukAudio":"/ai_services/tts3/?q=gene&lang=en-GB&ipa=%2Fd%CA%92i%CB%90n%2F","usAudio":"/ai_services/tts3/?q=gene&lang=en-US&ipa=%2Fd%CA%92i%CB%90n%2F"},{"id":"lv_5_160","topic":"Nature and Environmental Protection","word":"genetic","pos":"(adj)","ipa":"/dʒəˈnet̬.ɪk/","defVi":"(thuộc) di truyền, gen","defEn":"connected with genes or genetics, the study of heredity","examples":["Scientists are studying the [genetic] factors that influence human longevity. (=Dịch: Các nhà khoa học đang nghiên cứu các yếu tố di truyền ảnh hưởng đến tuổi thọ của con người.)","Some diseases are caused by a [genetic] defect passed down through generations. (=Dịch: Một số bệnh tật bị gây ra bởi khiếm khuyết di truyền truyền qua nhiều thế hệ.)","The crops have undergone [genetic] modification to resist pests. (=Dịch: Cây trồng đã được biến đổi di truyền để kháng sâu bệnh.)"],"ukAudio":"/ai_services/tts3/?q=genetic&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=genetic&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F"},{"id":"lv_5_161","topic":"Nature and Environmental Protection","word":"germany","pos":"(n)","ipa":"/ˈdʒɝː.mə.ni/","defVi":"nước Đức, Cộng hòa Liên bang Đức","defEn":"a major country in Central Europe known for its engineering and culture","examples":["Many international students choose to study engineering in [germany]. (=Dịch: Nhiều sinh viên quốc tế chọn học ngành kỹ thuật tại nước Đức.)","Renewable energy adoption has expanded rapidly across [germany] over the last decade. (=Dịch: Việc áp dụng năng lượng tái tạo đã mở rộng nhanh chóng trên khắp nước Đức trong thập kỷ qua.)","The automotive sector plays a vital role in the national economy of [germany]. (=Dịch: Ngành công nghiệp ô tô đóng vai trò sống còn trong nền kinh tế quốc dân của Đức.)"],"ukAudio":"/ai_services/tts3/?q=germany&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=germany&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F"},{"id":"lv_5_162","topic":"Nature and Environmental Protection","word":"germinate","pos":"(v)","ipa":"/ˈdʒɜːr.mə.neɪt/","defVi":"nảy mầm, nảy sinh","defEn":"to start growing or to develop into a plant from a seed","examples":["Seeds require adequate moisture and warmth in order to [germinate] properly. (=Dịch: Hạt giống cần đủ độ ẩm và độ ấm để có thể nảy mầm một cách thuận lợi.)","The tomato seeds took nearly two weeks to [germinate] in the greenhouse. (=Dịch: Hạt giống cà chua mất gần hai tuần để nảy mầm trong nhà kính.)","An innovative idea can [germinate] in the mind during a casual discussion. (=Dịch: Một ý tưởng sáng tạo có thể nảy sinh trong tâm trí khi đang trò chuyện bình thường.)"],"ukAudio":"/ai_services/tts3/?q=germinate&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=germinate&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99.ne%C9%AAt%2F"},{"id":"lv_5_163","topic":"Nature and Environmental Protection","word":"germination","pos":"(n)","ipa":"/ˌdʒɜːr.məˈneɪ.ʃən/","defVi":"sự nảy mầm","defEn":"the development of a plant from a seed or spore after a period of dormancy","examples":["Moisture and warmth are two essential factors for seed [germination]. (=Dịch: Độ ẩm và hơi ấm là hai yếu tố thiết yếu cho sự nảy mầm của hạt giống.)","The scientist observed the rate of [germination] under different light conditions. (=Dịch: Nhà khoa học đã quan sát tỷ lệ nảy mầm dưới các điều kiện ánh sáng khác nhau.)","Cold temperatures can significantly delay the [germination] of crops. (=Dịch: Nhiệt độ lạnh có thể làm chậm đáng kể quá trình nảy mầm của cây trồng.)"],"ukAudio":"/ai_services/tts3/?q=germination&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9C%CB%90r.m%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=germination&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9C%CB%90r.m%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_164","topic":"Nature and Environmental Protection","word":"gps","pos":"(n)","ipa":"/ˌdʒiː.piːˈɛs/","defVi":"hệ thống định vị toàn cầu (GPS)","defEn":"a satellite-based navigation system used to determine geographic location","examples":["The delivery driver relied on [gps] to navigate the unfamiliar city streets. (=Dịch: Người tài xế giao hàng đã dựa vào GPS để tìm đường qua những con phố xa lạ.)","Most modern smartphones come equipped with a built-in [gps] receiver. (=Dịch: Hầu hết các điện thoại thông minh hiện đại đều được trang bị bộ thu GPS tích hợp.)","Hikers should carry a printed map in case their [gps] runs out of battery. (=Dịch: Những người đi bộ đường dài nên mang theo bản đồ in đề phòng thiết bị GPS hết pin.)"],"ukAudio":"/ai_services/tts3/?q=gps&lang=en-GB&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=gps&lang=en-US&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88%C9%9Bs%2F"},{"id":"lv_5_165","topic":"Nature and Environmental Protection","word":"gradually","pos":"(adv)","ipa":"/ˈɡrædʒ.u.ə.li/","defVi":"dần dần, từ từ","defEn":"slowly over a period of time or in small stages","examples":["His English speaking skills [gradually] improved after months of practice. (=Dịch: Kỹ năng nói tiếng Anh của anh ấy dần dần tiến bộ sau nhiều tháng luyện tập.)","The weather [gradually] became warmer as spring approached. (=Dịch: Thời tiết dần ấm lên khi mùa xuân đến gần.)","Patients are advised to [gradually] return to their normal daily routines. (=Dịch: Bệnh nhân được khuyên nên dần dần quay trở lại thói quen sinh hoạt hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=gradually&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=gradually&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F"},{"id":"lv_5_166","topic":"Nature and Environmental Protection","word":"greece","pos":"(n)","ipa":"/ɡriːs/","defVi":"nước Hy Lạp","defEn":"a country in southeastern Europe renowned for its ancient civilization and islands","examples":["Millions of tourists visit [greece] each summer to explore ancient historical ruins. (=Dịch: Hàng triệu du khách đến thăm Hy Lạp mỗi mùa hè để khám phá các tàn tích lịch sử cổ đại.)","Olive oil is a staple agricultural export of [greece]. (=Dịch: Dầu ô liu là một mặt hàng nông sản xuất khẩu chủ lực của Hy Lạp.)","Classical philosophy and early democratic ideas trace their origins to [greece]. (=Dịch: Triết học cổ điển và những tư tưởng dân chủ sơ khai bắt nguồn từ Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greece&lang=en-GB&ipa=%2F%C9%A1ri%CB%90s%2F","usAudio":"/ai_services/tts3/?q=greece&lang=en-US&ipa=%2F%C9%A1ri%CB%90s%2F"},{"id":"lv_5_167","topic":"Nature and Environmental Protection","word":"greenhouse","pos":"(n)","ipa":"/ˈɡrin.haʊs/","defVi":"nhà kính (trồng cây)","defEn":"a glass or transparent plastic building used for growing plants that need warmth and protection","examples":["They grow tomatoes and cucumbers in a large [greenhouse] behind the house. (=Dịch: Họ trồng cà chua và dưa chuột trong một nhà kính lớn phía sau nhà.)","The botanic garden features a tropical [greenhouse] filled with rare orchids. (=Dịch: Vườn bách thảo có một nhà kính nhiệt đới chứa đầy những loài lan quý hiếm.)","Scientists use a temperature-controlled [greenhouse] for their agricultural experiments. (=Dịch: Các nhà khoa học sử dụng một nhà kính kiểm soát nhiệt độ cho các thí nghiệm nông nghiệp của họ.)"],"ukAudio":"/ai_services/tts3/?q=greenhouse&lang=en-GB&ipa=%2F%CB%88%C9%A1rin.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=greenhouse&lang=en-US&ipa=%2F%CB%88%C9%A1rin.ha%CA%8As%2F"},{"id":"lv_5_168","topic":"Nature and Environmental Protection","word":"grip","pos":"(v)","ipa":"/ɡrɪp/","defVi":"nắm chặt, bám chặt, thu hút","defEn":"to hold something tightly; to hold someone's attention completely","examples":["She had to [grip] the handrail firmly as the train accelerated suddenly. (=Dịch: Cô ấy phải bám chặt vào tay vịn khi đoàn tàu đột ngột tăng tốc.)","The thrilling mystery novel managed to [grip] readers from the very first page. (=Dịch: Cuốn tiểu thuyết trinh thám ly kỳ đã thu hút độc giả ngay từ trang đầu tiên.)","Fear seemed to [grip] the entire town during the mysterious outbreak. (=Dịch: Nỗi sợ hãi dường như bao trùm cả thị trấn trong đợt bùng phát bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=grip&lang=en-GB&ipa=%2F%C9%A1r%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=grip&lang=en-US&ipa=%2F%C9%A1r%C9%AAp%2F"},{"id":"lv_5_169","topic":"Nature and Environmental Protection","word":"habitat","pos":"(n)","ipa":"/ˈhæb.ə.tæt/","defVi":"môi trường sống tự nhiên","defEn":"the natural home or environment of an animal, plant, or organism","examples":["Urban expansion is rapidly destroying the natural [habitat] of many wildlife species. (=Dịch: Sự mở rộng đô thị đang nhanh chóng phá hủy môi trường sống tự nhiên của nhiều loài động vật hoang dã.)","Polar bears depend on sea ice as their primary hunting [habitat]. (=Dịch: Gấu bắc cực phụ thuộc vào băng biển như môi trường săn mồi chính của chúng.)","The wetland provides a critical breeding [habitat] for migratory birds. (=Dịch: Vùng đất ngập nước cung cấp môi trường sinh sản quan trọng cho các loài chim di cư.)"],"ukAudio":"/ai_services/tts3/?q=habitat&lang=en-GB&ipa=%2F%CB%88h%C3%A6b.%C9%99.t%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=habitat&lang=en-US&ipa=%2F%CB%88h%C3%A6b.%C9%99.t%C3%A6t%2F"},{"id":"lv_5_170","topic":"Nature and Environmental Protection","word":"harvest","pos":"(n)","ipa":"/ˈhɑːr.vɪst/","defVi":"mùa thu hoạch, vụ mùa, sản lượng thu hoạch","defEn":"the season or process of gathering crops, or the quantity of crops collected","examples":["Farmers are celebrating a bumper [harvest] of wheat this year. (=Dịch: Những người nông dân đang ăn mừng một vụ mùa lúa mì bội thu trong năm nay.)","The olive [harvest] typically takes place in late autumn. (=Dịch: Mùa thu hoạch ô liu thường diễn ra vào cuối mùa thu.)","Drought caused severe damage to the annual rice [harvest]. (=Dịch: Hạn hán đã gây thiệt hại nghiêm trọng cho sản lượng lúa hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=harvest&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90r.v%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=harvest&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90r.v%C9%AAst%2F"},{"id":"lv_5_171","topic":"Nature and Environmental Protection","word":"hawk","pos":"(n)","ipa":"/hɔːk/","defVi":"chim ưng, chim diều hâu","defEn":"a bird of prey with broad rounded wings and a long tail, known for keen eyesight","examples":["A [hawk] circled high in the sky, searching for prey. (=Dịch: Một con chim ưng lượn vòng trên trời cao để tìm kiếm con mồi.)","The [hawk] swooped down swiftly to catch a small mouse in the field. (=Dịch: Con diều hâu lao vút xuống để bắt một con chuột nhỏ trên cánh đồng.)","With vision like a [hawk], the guard noticed the intrusion immediately. (=Dịch: Với tầm nhìn sắc bén như chim ưng, người bảo vệ đã phát hiện ra sự xâm nhập ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=hawk&lang=en-GB&ipa=%2Fh%C9%94%CB%90k%2F","usAudio":"/ai_services/tts3/?q=hawk&lang=en-US&ipa=%2Fh%C9%94%CB%90k%2F"},{"id":"lv_5_172","topic":"Nature and Environmental Protection","word":"haze","pos":"(n)","ipa":"/heɪz/","defVi":"màn sương mờ, bụi mù, khói mù","defEn":"a thin mist or smoke in the air that makes it hard to see clearly","examples":["The morning sun slowly emerged through the thick [haze]. (=Dịch: Mặt trời buổi sáng từ từ hiện ra qua màn sương mù dày đặc.)","A [haze] of pollution hung over the city during the summer. (=Dịch: Một màn khói bụi ô nhiễm bao trùm lấy thành phố trong suốt mùa hè.)","He looked at the distant mountains veiled in blue [haze]. (=Dịch: Anh ấy nhìn về phía những ngọn núi xa xa bị che phủ bởi làn sương lam.)"],"ukAudio":"/ai_services/tts3/?q=haze&lang=en-GB&ipa=%2Fhe%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=haze&lang=en-US&ipa=%2Fhe%C9%AAz%2F"},{"id":"lv_5_173","topic":"Nature and Environmental Protection","word":"hedgehog","pos":"(n)","ipa":"/ˈhedʒ.hɑːɡ/","defVi":"con nhím (nhím gai nhỏ)","defEn":"a small nocturnal mammal covered with stiff, sharp spines","examples":["A small [hedgehog] curled into a prickly ball when the dog approached. (=Dịch: Một con nhím nhỏ cuộn tròn thành một quả cầu đầy gai khi con chó đến gần.)","The wildlife rescue center released a healthy [hedgehog] back into the woods. (=Dịch: Trung tâm cứu hộ động vật hoang dã đã thả một con nhím khỏe mạnh trở lại khu rừng.)","We often see a [hedgehog] foraging for insects in our garden at dusk. (=Dịch: Chúng tôi thường thấy một con nhím tìm kiếm côn trùng trong vườn nhà vào lúc chập tối.)"],"ukAudio":"/ai_services/tts3/?q=hedgehog&lang=en-GB&ipa=%2F%CB%88hed%CA%92.h%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=hedgehog&lang=en-US&ipa=%2F%CB%88hed%CA%92.h%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_174","topic":"Nature and Environmental Protection","word":"heel","pos":"(n)","ipa":"/hil/","defVi":"gót chân, gót giày","defEn":"the back part of the human foot below the ankle, or the back part of a shoe","examples":["She rubbed her sore [heel] after walking in new shoes all day. (=Dịch: Cô ấy xoa gót chân đau nhức sau khi đi lại cả ngày bằng đôi giày mới.)","The [heel] of her boot broke as she stepped off the curb. (=Dịch: Gót chiếc ủng của cô ấy bị gãy khi bước xuống lề đường.)","Apply gentle pressure to the [heel] to help relieve muscle tension. (=Dịch: Ấn nhẹ vào phần gót chân để giúp giảm căng cơ.)"],"ukAudio":"/ai_services/tts3/?q=heel&lang=en-GB&ipa=%2Fhil%2F","usAudio":"/ai_services/tts3/?q=heel&lang=en-US&ipa=%2Fhil%2F"},{"id":"lv_5_175","topic":"Nature and Environmental Protection","word":"hibernate","pos":"(v)","ipa":"/ˈhaɪ.bɚ.neɪt/","defVi":"ngủ đông","defEn":"to spend the winter in a dormant, sleep-like state to conserve energy","examples":["Bears eat heavily during the autumn so they can safely [hibernate] through the harsh winter. (=Dịch: Gấu ăn rất nhiều vào mùa thu để chúng có thể ngủ đông an toàn qua mùa đông khắc nghiệt.)","Some species of frogs [hibernate] by burying themselves deep in the mud under frozen lakes. (=Dịch: Một số loài ếch ngủ đông bằng cách tự vùi mình sâu trong bùn dưới các hồ nước đóng băng.)","Animals that [hibernate] experience a drastic drop in body temperature and metabolic rate. (=Dịch: Những động vật ngủ đông sẽ trải qua sự sụt giảm mạnh về thân nhiệt và tốc độ trao đổi chất.)"],"ukAudio":"/ai_services/tts3/?q=hibernate&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.b%C9%9A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=hibernate&lang=en-US&ipa=%2F%CB%88ha%C9%AA.b%C9%9A.ne%C9%AAt%2F"},{"id":"lv_5_176","topic":"Nature and Environmental Protection","word":"hibernation","pos":"(n)","ipa":"/ˌhaɪ.bɚˈneɪ.ʃən/","defVi":"sự ngủ đông, giấc ngủ đông","defEn":"a state of deep sleep that some animals enter during the winter to save energy","examples":["Bears store up fat before entering their winter [hibernation]. (=Dịch: Gấu tích tụ mỡ trước khi bước vào kỳ ngủ đông.)","During [hibernation], an animal's body temperature and heart rate drop significantly. (=Dịch: Trong suốt thời gian ngủ đông, thân nhiệt và nhịp tim của động vật giảm đi đáng kể.)","The hedgehog wakes up from [hibernation] when spring arrives. (=Dịch: Con nhím thức dậy sau giấc ngủ đông khi mùa xuân đến.)"],"ukAudio":"/ai_services/tts3/?q=hibernation&lang=en-GB&ipa=%2F%CB%8Cha%C9%AA.b%C9%9A%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=hibernation&lang=en-US&ipa=%2F%CB%8Cha%C9%AA.b%C9%9A%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_177","topic":"Nature and Environmental Protection","word":"hook","pos":"(n)","ipa":"/hʊk/","defVi":"móc, cái móc; lưỡi câu","defEn":"a curved piece of metal, plastic, or other material used for catching, holding, or hanging things","examples":["Hang your coat on the [hook] behind the door. (=Dịch: Treo áo khoác của bạn lên chiếc móc đằng sau cánh cửa.)","He baited the [hook] with a small worm to catch fish. (=Dịch: Anh ấy gắn mồi là một con giun nhỏ vào lưỡi câu để bắt cá.)","The picture frame fell off the wall because the [hook] was loose. (=Dịch: Khung tranh bị rơi khỏi tường vì chiếc móc bị lỏng.)"],"ukAudio":"/ai_services/tts3/?q=hook&lang=en-GB&ipa=%2Fh%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=hook&lang=en-US&ipa=%2Fh%CA%8Ak%2F"},{"id":"lv_5_178","topic":"Nature and Environmental Protection","word":"hormone","pos":"(n)","ipa":"/ˈhɔːr.moʊn/","defVi":"hoóc-môn, nội tiết tố","defEn":"a chemical substance produced in the body that controls the activity of certain cells or organs","examples":["Insulin is an essential [hormone] that regulates blood sugar levels. (=Dịch: Insulin là một hoóc-môn thiết yếu giúp điều hòa lượng đường trong máu.)","Adrenaline is a [hormone] released by the body during times of extreme stress. (=Dịch: Adrenaline là một hoóc-môn được cơ thể giải phóng trong những thời điểm cực kỳ căng thẳng.)","Changes in [hormone] levels can greatly affect a person's mood and sleep patterns. (=Dịch: Sự thay đổi về nồng độ hoóc-môn có thể ảnh hưởng lớn đến tâm trạng và giấc ngủ của một người.)"],"ukAudio":"/ai_services/tts3/?q=hormone&lang=en-GB&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=hormone&lang=en-US&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F"},{"id":"lv_5_179","topic":"Nature and Environmental Protection","word":"hotspot","pos":"(n)","ipa":"/ˈhɑːt.spɑːt/","defVi":"điểm nóng; điểm phát sóng Wi-Fi","defEn":"a place with a lot of activity, danger, or biodiversity, or a public location with Wi-Fi access","examples":["The tropical rainforest is a global [hotspot] for biodiversity. (=Dịch: Rừng mưa nhiệt đới là một điểm nóng toàn cầu về đa dạng sinh học.)","The cafe offers a free Wi-Fi [hotspot] for all customers. (=Dịch: Quán cà phê cung cấp điểm phát Wi-Fi miễn phí cho tất cả khách hàng.)","Police increased patrols around the crime [hotspot] in the downtown area. (=Dịch: Cảnh sát đã tăng cường tuần tra quanh điểm nóng tội phạm ở khu trung tâm.)"],"ukAudio":"/ai_services/tts3/?q=hotspot&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90t.sp%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=hotspot&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90t.sp%C9%91%CB%90t%2F"},{"id":"lv_5_180","topic":"Nature and Environmental Protection","word":"household","pos":"(n)","ipa":"/ˈhaʊs.hoʊld/","defVi":"hộ gia đình","defEn":"a group of people, often a family, who live together in the same home","examples":["Many families try to reduce their monthly [household] expenses during difficult times. (=Dịch: Nhiều gia đình cố gắng cắt giảm chi tiêu hộ gia đình hàng tháng trong thời kỳ khó khăn.)","The government census collects data from every [household] across the country. (=Dịch: Cuộc điều tra dân số của chính phủ thu thập dữ liệu từ mọi hộ gia đình trên toàn quốc.)","Sharing [household] chores fairly can prevent arguments among roommates. (=Dịch: Chia sẻ việc nhà một cách công bằng có thể ngăn ngừa các cuộc tranh cãi giữa những người bạn cùng phòng.)"],"ukAudio":"/ai_services/tts3/?q=household&lang=en-GB&ipa=%2F%CB%88ha%CA%8As.ho%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=household&lang=en-US&ipa=%2F%CB%88ha%CA%8As.ho%CA%8Ald%2F"},{"id":"lv_5_181","topic":"Nature and Environmental Protection","word":"humid","pos":"(adj)","ipa":"/ˈhju.mɪd/","defVi":"ẩm ướt, ẩm thấp","defEn":"having a high level of moisture or water vapor in the air","examples":["Tropical rainforests are typically hot and [humid] throughout the year. (=Dịch: Các khu rừng mưa nhiệt đới thường nóng và ẩm ướt quanh năm.)","The weather became uncomfortably [humid] right before the storm. (=Dịch: Thời tiết trở nên ẩm thấp khó chịu ngay trước cơn bão.)","She found it hard to breathe in such a [humid] climate. (=Dịch: Cô thấy khó thở trong một khí hậu ẩm ướt đến như vậy.)"],"ukAudio":"/ai_services/tts3/?q=humid&lang=en-GB&ipa=%2F%CB%88hju.m%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=humid&lang=en-US&ipa=%2F%CB%88hju.m%C9%AAd%2F"},{"id":"lv_5_182","topic":"Nature and Environmental Protection","word":"hunger","pos":"(n)","ipa":"/ˈhʌŋ.ɡɚ/","defVi":"cơn đói, nạn đói; sự khao khát","defEn":"the feeling of needing food, or the state of not having enough food to eat","examples":["International aid organizations are working tirelessly to eliminate [hunger] in poor regions. (=Dịch: Các tổ chức viện trợ quốc tế đang nỗ lực không ngừng nghỉ để xóa bỏ nạn đói ở các vùng nghèo khó.)","After hiking for five hours, we were overcome by intense [hunger]. (=Dịch: Sau năm giờ đi bộ đường dài, chúng tôi bị lấn át bởi cơn đói cồn cào.)","The young scientist had a relentless [hunger] for new knowledge and discovery. (=Dịch: Nhà khoa học trẻ tuổi luôn có một sự khao khát không ngừng đối với kiến thức và khám phá mới.)"],"ukAudio":"/ai_services/tts3/?q=hunger&lang=en-GB&ipa=%2F%CB%88h%CA%8C%C5%8B.%C9%A1%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunger&lang=en-US&ipa=%2F%CB%88h%CA%8C%C5%8B.%C9%A1%C9%9A%2F"},{"id":"lv_5_183","topic":"Nature and Environmental Protection","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"Cuộc đi săn; sự tìm kiếm ráo riết.","defEn":"An act of chasing wild animals for food or sport, or an intensive search for something.","examples":["The lion returned empty-handed after a long and exhausting [hunt]. (=Dịch: Con sư tử trở về trắng tay sau một cuộc đi săn dài và mệt mỏi.)","The police have launched a massive [hunt] for the escaped criminal. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm quy mô lớn đối với tên tội phạm vượt ngục.)","Her [hunt] for an affordable apartment in the city took several weeks. (=Dịch: Cuộc tìm kiếm một căn hộ giá cả phải chăng trong thành phố của cô ấy đã mất vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_5_184","topic":"Nature and Environmental Protection","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.tɚ/","defVi":"Người thợ săn; kẻ săn mồi.","defEn":"A person or animal that searches for and kills wild animals for food or sport.","examples":["The experienced [hunter] tracked the deer through the dense forest. (=Dịch: Người thợ săn giàu kinh nghiệm đã lần theo dấu con hươu qua khu rừng rậm rạp.)","Owls are efficient nocturnal [hunter] species that feed on small rodents. (=Dịch: Cú là loài động vật săn mồi ban đêm rất hiệu quả, ăn các loài gặm nhấm nhỏ.)","Local laws require every [hunter] to carry a valid hunting permit. (=Dịch: Luật pháp địa phương yêu cầu mọi thợ săn phải mang theo giấy phép săn bắn hợp lệ.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F"},{"id":"lv_5_185","topic":"Nature and Environmental Protection","word":"iceland","pos":"(n)","ipa":"/ˈaɪs.lənd/","defVi":"Băng Đảo (Iceland - một đảo quốc ở Bắc Đại Tây Dương).","defEn":"An island country in the North Atlantic Ocean known for its volcanic landscape and glaciers.","examples":["Tourism in [iceland] has grown rapidly due to its breathtaking natural wonders. (=Dịch: Du lịch ở Iceland đã phát triển nhanh chóng nhờ vào các kỳ quan thiên nhiên ngoạn mục.)","Many researchers visit [iceland] to study geothermal energy and active volcanoes. (=Dịch: Nhiều nhà nghiên cứu đến Iceland để nghiên cứu về năng lượng địa nhiệt và các núi lửa đang hoạt động.)","We were lucky enough to see the Northern Lights during our winter trip to [iceland]. (=Dịch: Chúng tôi đã đủ may mắn để nhìn thấy hiện tượng cực quang trong chuyến đi mùa đông tới Iceland.)"],"ukAudio":"/ai_services/tts3/?q=iceland&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=iceland&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F"},{"id":"lv_5_186","topic":"Nature and Environmental Protection","word":"ideally","pos":"(adv)","ipa":"/aɪˈdiː.ə.li/","defVi":"Lý tưởng nhất là; một cách hoàn hảo.","defEn":"In an ideal or perfect way; according to what is best.","examples":["[ideally], students should spend at least two hours reviewing their lessons each day. (=Dịch: Lý tưởng nhất là học sinh nên dành ít nhất hai giờ để ôn bài mỗi ngày.)","The new apartment is [ideally] located near the city center and public transport. (=Dịch: Căn hộ mới có vị trí vô cùng lý tưởng gần trung tâm thành phố và phương tiện công cộng.)","[ideally], the project should be completed before the end of this quarter. (=Dịch: Về mặt lý tưởng, dự án này nên được hoàn thành trước khi quý này kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=ideally&lang=en-GB&ipa=%2Fa%C9%AA%CB%88di%CB%90.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=ideally&lang=en-US&ipa=%2Fa%C9%AA%CB%88di%CB%90.%C9%99.li%2F"},{"id":"lv_5_187","topic":"Nature and Environmental Protection","word":"illegal","pos":"(adj)","ipa":"/ɪˈliː.ɡəl/","defVi":"Bất hợp pháp; phạm pháp.","defEn":"Not allowed by the law; against official rules.","examples":["It is [illegal] to drive a motor vehicle without a valid license. (=Dịch: Lái xe cơ giới mà không có bằng lái hợp lệ là phạm pháp.)","The government is cracking down on the [illegal] trade of wild animals. (=Dịch: Chính phủ đang trấn áp hoạt động buôn bán động vật hoang dã bất hợp pháp.)","Downloading copyrighted content without permission is considered [illegal]. (=Dịch: Tải nội dung có bản quyền mà không xin phép bị coi là bất hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=illegal&lang=en-GB&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=illegal&lang=en-US&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_5_188","topic":"Nature and Environmental Protection","word":"import","pos":"(v)","ipa":"/ɪmˈpɔːrt/","defVi":"Nhập khẩu; nhập hàng.","defEn":"To bring goods or services into a country from abroad to sell.","examples":["The country has to [import] a large amount of crude oil every year. (=Dịch: Quốc gia này phải nhập khẩu một lượng lớn dầu thô mỗi năm.)","They plan to [import] high-tech agricultural machinery from Germany. (=Dịch: Họ dự định nhập khẩu máy móc nông nghiệp công nghệ cao từ Đức.)","Supermarkets frequently [import] tropical fruits during the winter season. (=Dịch: Các siêu thị thường xuyên nhập khẩu trái cây nhiệt đới vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=import&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=import&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90rt%2F"},{"id":"lv_5_189","topic":"Nature and Environmental Protection","word":"incorrect","pos":"(adj)","ipa":"/ˌɪn.kəˈrɛkt/","defVi":"sai, không chính xác","defEn":"not right or accurate; containing errors","examples":["Several answers on his exam were marked as [incorrect]. (=Dịch: Một số câu trả lời trong bài kiểm tra của anh ấy bị đánh dấu là không chính xác.)","The article provided [incorrect] information about the total cost of the project. (=Dịch: Bài báo đã cung cấp thông tin không đúng về tổng chi phí của dự án.)","It is [incorrect] to assume that all students learn at the same pace. (=Dịch: Thật sai lầm khi cho rằng tất cả học sinh đều tiếp thu với tốc độ như nhau.)"],"ukAudio":"/ai_services/tts3/?q=incorrect&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=incorrect&lang=en-US&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F"},{"id":"lv_5_190","topic":"Nature and Environmental Protection","word":"incredibly","pos":"(adv)","ipa":"/ɪnˈkrɛd.ə.bli/","defVi":"Vô cùng, cực kỳ, không thể tin được.","defEn":"Extremely; to a very great degree.","examples":["The final exam was [incredibly] difficult for most students. (=Dịch: Bài thi cuối kỳ cực kỳ khó đối với hầu hết học sinh.)","She solved the complicated puzzle [incredibly] fast. (=Dịch: Cô ấy đã giải câu đố phức tạp nhanh một cách khó tin.)","The team worked [incredibly] hard to finish the project on time. (=Dịch: Cả nhóm đã làm việc vô cùng chăm chỉ để hoàn thành dự án đúng hạn.)"],"ukAudio":"/ai_services/tts3/?q=incredibly&lang=en-GB&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=incredibly&lang=en-US&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F"},{"id":"lv_5_191","topic":"Nature and Environmental Protection","word":"ingest","pos":"(v)","ipa":"/ɪnˈdʒɛst/","defVi":"ăn vào, nuốt vào, tiêu thụ","defEn":"to take food, drink, or another substance into your body by swallowing it","examples":["Marine animals often [ingest] plastic waste by mistake. (=Dịch: Động vật biển thường vô tình nuốt phải rác thải nhựa.)","You should not [ingest] this medicine on an empty stomach. (=Dịch: Bạn không nên uống loại thuốc này khi bụng đói.)","Some plants produce toxins that are dangerous to [ingest]. (=Dịch: Một số loài thực vật sản sinh độc tố nguy hiểm nếu ăn phải.)"],"ukAudio":"/ai_services/tts3/?q=ingest&lang=en-GB&ipa=%2F%C9%AAn%CB%88d%CA%92%C9%9Bst%2F","usAudio":"/ai_services/tts3/?q=ingest&lang=en-US&ipa=%2F%C9%AAn%CB%88d%CA%92%C9%9Bst%2F"},{"id":"lv_5_192","topic":"Nature and Environmental Protection","word":"inhabit","pos":"(v)","ipa":"/ɪnˈhæb.ɪt/","defVi":"sinh sống, cư trú tại một nơi","defEn":"to live in or occupy a particular place","examples":["Many rare bird species [inhabit] this remote rainforest. (=Dịch: Nhiều loài chim quý hiếm sinh sống trong khu rừng mưa hẻo lánh này.)","Polar bears [inhabit] the freezing regions of the Arctic. (=Dịch: Gấu bắc cực cư trú tại những vùng băng giá của Bắc Cực.)","Humans have managed to [inhabit] almost every corner of the earth. (=Dịch: Con người đã cố gắng sinh sống ở hầu hết mọi ngóc ngách trên Trái Đất.)"],"ukAudio":"/ai_services/tts3/?q=inhabit&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=inhabit&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%AAt%2F"},{"id":"lv_5_193","topic":"Nature and Environmental Protection","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, nằm sâu trong đất liền","defEn":"situated in or relating to the interior part of a country rather than the coast","examples":["The town is located in an [inland] region far from the ocean. (=Dịch: Thị trấn nằm ở một vùng nội địa cách xa đại dương.)","Many [inland] lakes suffer from water shortages during the dry summer months. (=Dịch: Nhiều hồ nội địa bị thiếu nước trong những tháng hè khô hạn.)","The government is improving [inland] transport networks to boost trade. (=Dịch: Chính phủ đang cải thiện mạng lưới giao thông nội địa để thúc đẩy thương mại.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_5_194","topic":"Nature and Environmental Protection","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự hiểu biết sâu sắc, cái nhìn thấu suốt","defEn":"a clear, deep, and sometimes sudden understanding of a complicated problem or situation","examples":["The study provides valuable [insight] into customer behavior. (=Dịch: Nghiên cứu này cung cấp cái nhìn sâu sắc có giá trị về hành vi của khách hàng.)","Her experiences abroad gave her a unique [insight] into different cultures. (=Dịch: Những trải nghiệm ở nước ngoài đã mang lại cho cô ấy một góc nhìn sâu sắc độc đáo về các nền văn hóa khác nhau.)","The documentary offers an interesting [insight] into the life of wild animals. (=Dịch: Bộ phim tài liệu mang lại một góc nhìn thú vị về đời sống của các loài động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_5_195","topic":"Nature and Environmental Protection","word":"instal","pos":"(v)","ipa":"/ɪn.ˈstɑːl/","defVi":"Cài đặt, lắp đặt","defEn":"To put a piece of equipment, system, or software into place and make it ready to use.","examples":["The technician arrived early to [instal] the new air conditioning unit. (=Dịch: Kỹ thuật viên đã đến sớm để lắp đặt thiết bị điều hòa mới.)","You must [instal] the latest security update to protect your computer. (=Dịch: Bạn phải cài đặt bản cập nhật bảo mật mới nhất để bảo vệ máy tính của mình.)","The school decided to [instal] solar panels on the roof to save energy. (=Dịch: Nhà trường quyết định lắp đặt các tấm pin năng lượng mặt trời trên mái nhà để tiết kiệm điện năng.)"],"ukAudio":"/ai_services/tts3/?q=instal&lang=en-GB&ipa=%2F%C9%AAn.%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=instal&lang=en-US&ipa=%2F%C9%AAn.%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_5_196","topic":"Nature and Environmental Protection","word":"institute","pos":"(n)","ipa":"/ˈɪn.stə.tut/","defVi":"viện, học viện, tổ chức nghiên cứu","defEn":"an organization founded for a specific purpose, such as education, research, or science","examples":["She works as a senior researcher at the scientific [institute]. (=Dịch: Cô ấy làm việc với tư cách là nhà nghiên cứu cao cấp tại viện khoa học.)","The [institute] offers various specialized training courses for engineers. (=Dịch: Viện này cung cấp nhiều khóa đào tạo chuyên sâu cho các kỹ sư.)","Funding for the research [institute] was increased this year. (=Dịch: Kinh phí dành cho viện nghiên cứu đã được tăng lên trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=institute&lang=en-GB&ipa=%2F%CB%88%C9%AAn.st%C9%99.tut%2F","usAudio":"/ai_services/tts3/?q=institute&lang=en-US&ipa=%2F%CB%88%C9%AAn.st%C9%99.tut%2F"},{"id":"lv_5_197","topic":"Nature and Environmental Protection","word":"integrate","pos":"(v)","ipa":"/ˈɪn.tə.ɡreɪt/","defVi":"tích hợp, hòa nhập","defEn":"to combine two or more things so that they work together effectively","examples":["It can take time for new immigrants to [integrate] into a different culture. (=Dịch: Có thể mất thời gian để những người nhập cư mới hòa nhập vào một nền văn hóa khác.)","Teachers try to [integrate] modern technology into their daily lessons. (=Dịch: Giáo viên cố gắng tích hợp công nghệ hiện đại vào các bài học hàng ngày của họ.)","The new software will [integrate] smoothly with our existing database. (=Dịch: Phần mềm mới sẽ tích hợp mượt mà với cơ sở dữ liệu hiện có của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=integrate&lang=en-GB&ipa=%2F%CB%88%C9%AAn.t%C9%99.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=integrate&lang=en-US&ipa=%2F%CB%88%C9%AAn.t%C9%99.%C9%A1re%C9%AAt%2F"},{"id":"lv_5_198","topic":"Nature and Environmental Protection","word":"intelligence","pos":"(n)","ipa":"/ɪnˈtɛl.ə.dʒəns/","defVi":"trí thông minh, trí tuệ; tin tức tình báo","defEn":"the ability to learn, understand, and think logically, or secret information gathered about an enemy","examples":["Dolphins are well known for their high level of [intelligence]. (=Dịch: Cá heo nổi tiếng vì mức độ thông minh cao.)","The government gathered secret [intelligence] before making a move. (=Dịch: Chính phủ đã thu thập tin tức tình báo bí mật trước khi hành động.)","Advances in artificial [intelligence] are transforming many industries. (=Dịch: Những tiến bộ trong trí tuệ nhân tạo đang làm thay đổi nhiều ngành công nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=intelligence&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=intelligence&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F"},{"id":"lv_5_199","topic":"Nature and Environmental Protection","word":"invasive","pos":"(adj)","ipa":"/ɪnˈveɪ.sɪv/","defVi":"xâm lấn, có tính xâm hại","defEn":"tending to spread aggressively, especially of non-native species causing ecological damage","examples":["The [invasive] weed spread rapidly and threatened native plant species. (=Dịch: Loài cỏ dại xâm lấn lan rộng nhanh chóng và đe dọa các loài thực vật bản địa.)","Scientists are studying ways to control [invasive] carp in local rivers. (=Dịch: Các nhà khoa học đang nghiên cứu các cách để kiểm soát loài cá chép xâm lấn ở các con sông địa phương.)","Doctors recommended a non-[invasive] treatment instead of surgery. (=Dịch: Các bác sĩ đã khuyến nghị một phương pháp điều trị không xâm lấn thay vì phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=invasive&lang=en-GB&ipa=%2F%C9%AAn%CB%88ve%C9%AA.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=invasive&lang=en-US&ipa=%2F%C9%AAn%CB%88ve%C9%AA.s%C9%AAv%2F"},{"id":"lv_5_200","topic":"Nature and Environmental Protection","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, sự nghiên cứu làm rõ","defEn":"an official examination or inquiry into a crime, problem, or statement","examples":["The police launched a thorough [investigation] into the robbery. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về vụ trộm.)","A formal [investigation] revealed several safety violations at the factory. (=Dịch: Một cuộc điều tra chính thức đã chỉ ra một số vi phạm an toàn tại nhà máy.)","The committee is carrying out an [investigation] to find the cause of the accident. (=Dịch: Ủy ban đang tiến hành một cuộc điều tra để tìm ra nguyên nhân của tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_201","topic":"Nature and Environmental Protection","word":"laboratory","pos":"(n)","ipa":"/ˈlæb.rə.tɔːr.i/","defVi":"phòng thí nghiệm","defEn":"a room or building equipped for scientific experiments, research, or testing","examples":["Students must wear protective goggles whenever they work inside the chemistry [laboratory]. (=Dịch: Học sinh phải đeo kính bảo hộ bất cứ khi nào làm việc trong phòng thí nghiệm hóa học.)","The medical [laboratory] is processing hundreds of blood tests every day. (=Dịch: Phòng xét nghiệm y tế đang xử lý hàng trăm mẫu xét nghiệm máu mỗi ngày.)","Cutting-edge vaccines are developed inside this high-security research [laboratory]. (=Dịch: Các loại vắc-xin tiên tiến được phát triển bên trong phòng thí nghiệm nghiên cứu có độ bảo mật cao này.)"],"ukAudio":"/ai_services/tts3/?q=laboratory&lang=en-GB&ipa=%2F%CB%88l%C3%A6b.r%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=laboratory&lang=en-US&ipa=%2F%CB%88l%C3%A6b.r%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_5_202","topic":"Nature and Environmental Protection","word":"lagoon","pos":"(n)","ipa":"/ləˈɡuːn/","defVi":"đầm phá, vùng nước nông ven biển","defEn":"a body of shallow water separated from the sea by a reef or sandbar","examples":["Tourists love swimming in the calm, clear waters of the tropical [lagoon]. (=Dịch: Khách du lịch thích bơi trong làn nước trong vắt và êm đềm của đầm phá nhiệt đới.)","A coral reef protects the shallow [lagoon] from powerful ocean waves. (=Dịch: Một rạn san hô bảo vệ vùng đầm phá nông khỏi những con sóng biển dữ dội.)","Rare bird species nest along the shores of the coastal [lagoon]. (=Dịch: Các loài chim quý hiếm làm tổ dọc theo bờ của đầm phá ven biển.)"],"ukAudio":"/ai_services/tts3/?q=lagoon&lang=en-GB&ipa=%2Fl%C9%99%CB%88%C9%A1u%CB%90n%2F","usAudio":"/ai_services/tts3/?q=lagoon&lang=en-US&ipa=%2Fl%C9%99%CB%88%C9%A1u%CB%90n%2F"},{"id":"lv_5_203","topic":"Nature and Environmental Protection","word":"landfill","pos":"(n)","ipa":"/ˈlænd.fɪl/","defVi":"bãi chôn lấp rác","defEn":"a designated site for the disposal of waste materials by burial","examples":["Tons of plastic waste end up in the city [landfill] every single day. (=Dịch: Hàng tấn rác thải nhựa bị đưa vào bãi chôn lấp rác của thành phố mỗi ngày.)","Decomposing organic matter in a [landfill] produces large amounts of methane gas. (=Dịch: Chất hữu cơ phân hủy trong bãi chôn lấp tạo ra một lượng lớn khí mê-tan.)","Local authorities are trying to divert household waste away from the overflowing [landfill]. (=Dịch: Chính quyền địa phương đang cố gắng chuyển hướng rác thải sinh hoạt khỏi bãi chôn lấp đang quá tải.)"],"ukAudio":"/ai_services/tts3/?q=landfill&lang=en-GB&ipa=%2F%CB%88l%C3%A6nd.f%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=landfill&lang=en-US&ipa=%2F%CB%88l%C3%A6nd.f%C9%AAl%2F"},{"id":"lv_5_204","topic":"Nature and Environmental Protection","word":"larvae","pos":"(n)","ipa":"/ˈlɑr.vi/","defVi":"ấu trùng (số nhiều)","defEn":"the active immature forms of insects, especially before pupating into adults","examples":["Mosquito [larvae] thrive in stagnant water such as ponds and puddles. (=Dịch: Ấu trùng muỗi sinh sôi phát triển mạnh trong nước tù đọng như ao và vũng nước.)","Scientists studied how these [larvae] transform into adult beetles. (=Dịch: Các nhà khoa học đã nghiên cứu cách những ấu trùng này biến đổi thành bọ cánh cứng trưởng thành.)","The fish feed primarily on aquatic [larvae] and small insects. (=Dịch: Loài cá này chủ yếu ăn ấu trùng sống dưới nước và côn trùng nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=larvae&lang=en-GB&ipa=%2F%CB%88l%C9%91r.vi%2F","usAudio":"/ai_services/tts3/?q=larvae&lang=en-US&ipa=%2F%CB%88l%C9%91r.vi%2F"},{"id":"lv_5_205","topic":"Nature and Environmental Protection","word":"leather","pos":"(n)","ipa":"/ˈleð.ər/","defVi":"da thuộc (chất liệu làm đồ dùng)","defEn":"animal skin that has been treated to make shoes, bags, or clothes","examples":["He bought a jacket made of genuine [leather]. (=Dịch: Anh ấy đã mua một chiếc áo khoác làm bằng da thật.)","The car seats are covered in soft black [leather]. (=Dịch: Những chiếc ghế ô tô được bọc bằng da mềm màu đen.)","Many companies now use synthetic materials instead of real [leather]. (=Dịch: Nhiều công ty hiện nay sử dụng vật liệu tổng hợp thay vì da thật.)"],"ukAudio":"/ai_services/tts3/?q=leather&lang=en-GB&ipa=%2F%CB%88le%C3%B0.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=leather&lang=en-US&ipa=%2F%CB%88le%C3%B0.%C9%99r%2F"},{"id":"lv_5_206","topic":"Nature and Environmental Protection","word":"lime","pos":"(n)","ipa":"/laɪm/","defVi":"quả chanh ta (vỏ xanh); vôi sống","defEn":"a small, sour, green citrus fruit, or a white chemical substance derived from limestone","examples":["She squeezed fresh [lime] juice over the grilled fish to add flavor. (=Dịch: Cô ấy vắt nước cốt chanh tươi lên món cá nướng để tăng thêm hương vị.)","Farmers often add [lime] to acidic soil to improve crop growth. (=Dịch: Nông dân thường bón thêm vôi vào đất chua để cải thiện sự phát triển của cây trồng.)","A slice of [lime] was served on the rim of the glass. (=Dịch: Một lát chanh đã được gắn trên miệng ly nước.)"],"ukAudio":"/ai_services/tts3/?q=lime&lang=en-GB&ipa=%2Fla%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=lime&lang=en-US&ipa=%2Fla%C9%AAm%2F"},{"id":"lv_5_207","topic":"Nature and Environmental Protection","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water is the most common [liquid] on Earth. (=Dịch: Nước là chất lỏng phổ biến nhất trên Trái Đất.)","Be careful not to spill that hot [liquid] on yourself. (=Dịch: Hãy cẩn thận kẻo làm đổ chất lỏng nóng đó lên người.)","You should drink plenty of [liquids] when you have a fever. (=Dịch: Bạn nên uống nhiều nước khi bị sốt.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_5_208","topic":"Nature and Environmental Protection","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"gia súc, vật nuôi nông trại","defEn":"animals such as cows, sheep, and pigs that are kept on a farm","examples":["Raising [livestock] requires a tremendous amount of freshwater and feed grain. (=Dịch: Chăn nuôi gia súc đòi hỏi một lượng lớn nước ngọt và ngũ cốc làm thức ăn.)","The sudden snowstorm posed a great danger to the grazing [livestock]. (=Dịch: Trận bão tuyết bất ngờ đã gây nguy hiểm lớn cho đàn gia súc đang gặm cỏ.)","Local farmers depend entirely on their [livestock] for meat, milk, and income. (=Dịch: Những người nông dân địa phương phụ thuộc hoàn toàn vào đàn gia súc của họ để lấy thịt, sữa và thu nhập.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_5_209","topic":"Nature and Environmental Protection","word":"lizard","pos":"(n)","ipa":"/ˈlɪz.ɚd/","defVi":"con thằn lằn","defEn":"a reptile with a long body and tail, four legs, and rough skin","examples":["A small [lizard] was sunbathing on the warm rock. (=Dịch: Một con thằn lằn nhỏ đang phơi nắng trên tảng đá ấm.)","Some types of [lizards] can change color to hide from predators. (=Dịch: Một số loài thằn lằn có thể đổi màu để ẩn nấp khỏi kẻ săn mồi.)","The desert [lizard] is well adapted to survive without much water. (=Dịch: Loài thằn lằn sa mạc thích nghi rất tốt để sống sót mà không cần nhiều nước.)"],"ukAudio":"/ai_services/tts3/?q=lizard&lang=en-GB&ipa=%2F%CB%88l%C9%AAz.%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=lizard&lang=en-US&ipa=%2F%CB%88l%C9%AAz.%C9%9Ad%2F"},{"id":"lv_5_210","topic":"Nature and Environmental Protection","word":"log","pos":"(v)","ipa":"/lɑːɡ/","defVi":"ghi chép lại; khai thác gỗ","defEn":"to record information officially, or to cut down trees for wood","examples":["Scientists carefully [log] all temperature changes during the experiment. (=Dịch: Các nhà khoa học cẩn thận ghi chép lại mọi sự thay đổi nhiệt độ trong quá trình thí nghiệm.)","Companies are not allowed to [log] trees in this protected forest. (=Dịch: Các công ty không được phép khai thác gỗ trong khu rừng được bảo vệ này.)","Users need to [log] their daily activities in the fitness app. (=Dịch: Người dùng cần ghi lại các hoạt động hằng ngày của mình vào ứng dụng rèn luyện sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=log&lang=en-GB&ipa=%2Fl%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=log&lang=en-US&ipa=%2Fl%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_211","topic":"Nature and Environmental Protection","word":"logical","pos":"(adj)","ipa":"/ˈlɑː.dʒɪ.kəl/","defVi":"hợp lý, lô-gích","defEn":"reasonable and based on clear, sound thinking","examples":["It seems [logical] to save money for emergencies rather than spending it all. (=Dịch: Có vẻ hợp lý khi tiết kiệm tiền cho những trường hợp khẩn cấp hơn là tiêu hết.)","She organized her essay in a clear and [logical] structure. (=Dịch: Cô ấy đã sắp xếp bài luận của mình theo một cấu trúc rõ ràng và hợp lý.)","The next [logical] step in his career was to apply for a managerial position. (=Dịch: Bước đi hợp lý tiếp theo trong sự nghiệp của anh ấy là ứng tuyển vào một vị trí quản lý.)"],"ukAudio":"/ai_services/tts3/?q=logical&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=logical&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_5_212","topic":"Nature and Environmental Protection","word":"loss","pos":"(n)","ipa":"/lɔs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state of no longer having something, or a disadvantage caused by losing it","examples":["The company suffered a significant financial [loss] this quarter. (=Dịch: Công ty đã phải chịu một khoản tổn thất tài chính đáng kể trong quý này.)","Regular exercise helps prevent muscle [loss] as you age. (=Dịch: Tập thể dục thường xuyên giúp ngăn ngừa tình trạng mất cơ khi bạn già đi.)","He expressed deep sympathy for their [loss] after the tragedy. (=Dịch: Anh ấy đã bày tỏ sự cảm thông sâu sắc trước sự mất mát của họ sau thảm kịch.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94s%2F"},{"id":"lv_5_213","topic":"Nature and Environmental Protection","word":"lung","pos":"(n)","ipa":"/lʌŋ/","defVi":"phổi","defEn":"either of the two organs in the chest with which people and some animals breathe","examples":["Smoking can cause severe and irreversible damage to the [lung] tissue. (=Dịch: Hút thuốc có thể gây tổn thương nghiêm trọng và không thể hồi phục đối với mô phổi.)","She took a deep breath, filling her [lung] capacity completely before diving. (=Dịch: Cô ấy hít một hơi thật sâu, nạp đầy dung tích phổi trước khi lặn.)","Doctors monitored the patient's [lung] function after the infection. (=Dịch: Các bác sĩ đã theo dõi chức năng phổi của bệnh nhân sau đợt nhiễm trùng.)"],"ukAudio":"/ai_services/tts3/?q=lung&lang=en-GB&ipa=%2Fl%CA%8C%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lung&lang=en-US&ipa=%2Fl%CA%8C%C5%8B%2F"},{"id":"lv_5_214","topic":"Nature and Environmental Protection","word":"machinery","pos":"(n)","ipa":"/məˈʃiː.nɚ.i/","defVi":"máy móc, thiết bị","defEn":"machines as a whole, or the working parts of a machine","examples":["The factory invested heavily in modern agricultural [machinery]. (=Dịch: Nhà máy đã đầu tư mạnh mẽ vào máy móc nông nghiệp hiện đại.)","Workers must wear safety gear when operating heavy [machinery]. (=Dịch: Công nhân phải mặc đồ bảo hộ khi vận hành máy móc hạng nặng.)","A technician was called to repair the broken [machinery]. (=Dịch: Một kỹ thuật viên đã được gọi đến để sửa chữa hệ thống máy móc bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=machinery&lang=en-GB&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=machinery&lang=en-US&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F"},{"id":"lv_5_215","topic":"Nature and Environmental Protection","word":"mainland","pos":"(n)","ipa":"/ˈmeɪn.lænd/","defVi":"đất liền, lục địa","defEn":"the primary landmass of a country or continent, as distinguished from nearby islands","examples":["Ferries carry tourists from the small island to the [mainland] every hour. (=Dịch: Phà chở khách du lịch từ hòn đảo nhỏ vào đất liền mỗi giờ một chuyến.)","Prices for goods are usually cheaper on the [mainland] than on remote islands. (=Dịch: Giá hàng hóa ở đất liền thường rẻ hơn so với trên các hòn đảo xa xôi.)","The bridge connects the offshore community directly to the [mainland]. (=Dịch: Cây cầu kết nối cộng đồng ngoài đảo trực tiếp với đất liền.)"],"ukAudio":"/ai_services/tts3/?q=mainland&lang=en-GB&ipa=%2F%CB%88me%C9%AAn.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=mainland&lang=en-US&ipa=%2F%CB%88me%C9%AAn.l%C3%A6nd%2F"},{"id":"lv_5_216","topic":"Nature and Environmental Protection","word":"mammal","pos":"(n)","ipa":"/ˈmæm.əl/","defVi":"động vật có vú, thú","defEn":"any animal of which the female feeds her young on milk from her own body","examples":["The blue whale is recognized as the largest [mammal] on Earth. (=Dịch: Cá voi xanh được công nhận là loài động vật có vú lớn nhất trên Trái Đất.)","Unlike reptiles, every [mammal] is warm-blooded and typically gives birth to live young. (=Dịch: Không giống như bò sát, mọi loài động vật có vú đều là động vật máu nóng và thường đẻ con non.)","Bats are unique because they are the only [mammal] capable of true flight. (=Dịch: Loài dơi rất độc đáo vì chúng là loài động vật có vú duy nhất có khả năng bay thực sự.)"],"ukAudio":"/ai_services/tts3/?q=mammal&lang=en-GB&ipa=%2F%CB%88m%C3%A6m.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=mammal&lang=en-US&ipa=%2F%CB%88m%C3%A6m.%C9%99l%2F"},{"id":"lv_5_217","topic":"Nature and Environmental Protection","word":"mammoth","pos":"(n)","ipa":"/ˈmæm.əθ/","defVi":"voi ma mút","defEn":"a large, extinct elephant-like mammal with long curved tusks and hairy coat","examples":["The woolly [mammoth] lived during the Ice Age and roamed the northern plains. (=Dịch: Voi ma mút lông xoăn đã sống vào Kỷ Băng hà và lang thang khắp các đồng bằng phía bắc.)","Researchers discovered a well-preserved [mammoth] tusk buried in the permafrost. (=Dịch: Các nhà nghiên cứu đã phát hiện một chiếc ngà voi ma mút được bảo quản tốt bị vùi trong tầng đất đóng băng vĩnh cửu.)","Early humans hunted the [mammoth] for food, fur, and bones. (=Dịch: Người tiền sử đã săn bắt voi ma mút để lấy thức ăn, lông và xương.)"],"ukAudio":"/ai_services/tts3/?q=mammoth&lang=en-GB&ipa=%2F%CB%88m%C3%A6m.%C9%99%CE%B8%2F","usAudio":"/ai_services/tts3/?q=mammoth&lang=en-US&ipa=%2F%CB%88m%C3%A6m.%C9%99%CE%B8%2F"},{"id":"lv_5_218","topic":"Nature and Environmental Protection","word":"mane","pos":"(n)","ipa":"/meɪn/","defVi":"bờm (ngựa, sư tử), mái tóc dày","defEn":"the long, thick hair growing on the neck of a horse, lion, or other animal","examples":["The male lion has a magnificent dark [mane] around its neck. (=Dịch: Con sư tử đực có một chiếc bờm sẫm màu tuyệt đẹp quanh cổ.)","She brushed the horse's tangled [mane] until it was smooth. (=Dịch: Cô ấy đã chải chiếc bờm rối của con ngựa cho đến khi nó suôn mượt.)","The wind blew her thick [mane] of hair across her face. (=Dịch: Gió thổi mái tóc dày bồng bềnh của cô che ngang khuôn mặt.)"],"ukAudio":"/ai_services/tts3/?q=mane&lang=en-GB&ipa=%2Fme%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=mane&lang=en-US&ipa=%2Fme%C9%AAn%2F"},{"id":"lv_5_219","topic":"Nature and Environmental Protection","word":"mangrove","pos":"(n)","ipa":"/ˈmæŋ.ɡroʊv/","defVi":"cây đước; rừng ngập mặn","defEn":"a tropical tree or forest growing in wet mud near coasts or along tidal rivers","examples":["The [mangrove] forest acts as a natural barrier against sea storms. (=Dịch: Rừng ngập mặn đóng vai trò như một bức tường chắn tự nhiên chống lại bão biển.)","Many rare bird species nest in the thick [mangrove] swamps. (=Dịch: Nhiều loài chim quý hiếm làm tổ trong những đầm lầy ngập mặn rậm rạp.)","Conserving [mangroves] is vital for maintaining coastal biodiversity. (=Dịch: Bảo tồn rừng ngập mặn là điều sống còn để duy trì đa dạng sinh học ven biển.)"],"ukAudio":"/ai_services/tts3/?q=mangrove&lang=en-GB&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Av%2F","usAudio":"/ai_services/tts3/?q=mangrove&lang=en-US&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Av%2F"},{"id":"lv_5_220","topic":"Nature and Environmental Protection","word":"marine","pos":"(adj)","ipa":"/məˈriːn/","defVi":"thuộc về biển, đại dương hoặc sinh vật biển","defEn":"connected with the sea and the creatures that live there","examples":["Plastic pollution poses a serious threat to [marine] life. (=Dịch: Ô nhiễm rác thải nhựa gây ra mối đe dọa nghiêm trọng đối với sinh vật biển.)","She decided to study [marine] biology at university to explore coral reefs. (=Dịch: Cô quyết định học ngành sinh học biển tại trường đại học để khám phá các rạn san hô.)","Governments are creating [marine] reserves to protect endangered ocean species. (=Dịch: Các chính phủ đang thành lập các khu bảo tồn biển để bảo vệ các loài sinh vật biển có nguy cơ tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=marine&lang=en-GB&ipa=%2Fm%C9%99%CB%88ri%CB%90n%2F","usAudio":"/ai_services/tts3/?q=marine&lang=en-US&ipa=%2Fm%C9%99%CB%88ri%CB%90n%2F"},{"id":"lv_5_221","topic":"Nature and Environmental Protection","word":"massive","pos":"(adj)","ipa":"/ˈmæs.ɪv/","defVi":"to lớn, khổng lồ, trên diện rộng","defEn":"exceptionally large, heavy, or severe in scale","examples":["The earthquake caused [massive] destruction across the coastal region. (=Dịch: Trận động đất đã gây ra sự tàn phá khủng khiếp trên khắp vùng ven biển.)","The team undertook a [massive] research project that lasted five years. (=Dịch: Nhóm nghiên cứu đã đảm nhận một dự án nghiên cứu quy mô lớn kéo dài suốt 5 năm.)","A [massive] boulder blocked the entrance to the mountain pass. (=Dịch: Một tảng đá khổng lồ đã chặn mất lối vào đèo núi.)"],"ukAudio":"/ai_services/tts3/?q=massive&lang=en-GB&ipa=%2F%CB%88m%C3%A6s.%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=massive&lang=en-US&ipa=%2F%CB%88m%C3%A6s.%C9%AAv%2F"},{"id":"lv_5_222","topic":"Nature and Environmental Protection","word":"mediterranean","pos":"(n)","ipa":"/ˌmɛd.ə.təˈreɪ.ni.ən/","defVi":"Địa Trung Hải, vùng Địa Trung Hải","defEn":"the large sea between southern Europe and northern Africa, or its surrounding region","examples":["They spent their summer vacation sailing across the [mediterranean]. (=Dịch: Họ đã dành kỳ nghỉ hè để đi thuyền buồm dọc theo Địa Trung Hải.)","The climate of the [mediterranean] is characterized by hot, dry summers and mild winters. (=Dịch: Khí hậu của vùng Địa Trung Hải có đặc trưng là mùa hè nóng, khô và mùa đông ôn hòa.)","Many ancient civilizations flourished around the shores of the [mediterranean]. (=Dịch: Nhiều nền văn minh cổ đại đã phát triển hưng thịnh quanh bờ Địa Trung Hải.)"],"ukAudio":"/ai_services/tts3/?q=mediterranean&lang=en-GB&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99.t%C9%99%CB%88re%C9%AA.ni.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=mediterranean&lang=en-US&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99.t%C9%99%CB%88re%C9%AA.ni.%C9%99n%2F"},{"id":"lv_5_223","topic":"Nature and Environmental Protection","word":"mercury","pos":"(n)","ipa":"/ˈmɝː.kjə.ri/","defVi":"thủy ngân","defEn":"a toxic, heavy, silvery-white metallic element that is liquid at room temperature","examples":["Old thermometers often contain liquid [mercury] inside glass tubes. (=Dịch: Nhiệt kế kiểu cũ thường chứa thủy ngân dạng lỏng bên trong ống thủy tinh.)","High levels of [mercury] in seafood can pose serious health risks. (=Dịch: Hàm lượng thủy ngân cao trong hải sản có thể gây ra những nguy cơ sức khỏe nghiêm trọng.)","Industrial waste must be treated to prevent [mercury] from contaminating rivers. (=Dịch: Chất thải công nghiệp cần được xử lý để ngăn chặn thủy ngân làm ô nhiễm các dòng sông.)"],"ukAudio":"/ai_services/tts3/?q=mercury&lang=en-GB&ipa=%2F%CB%88m%C9%9D%CB%90.kj%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=mercury&lang=en-US&ipa=%2F%CB%88m%C9%9D%CB%90.kj%C9%99.ri%2F"},{"id":"lv_5_224","topic":"Nature and Environmental Protection","word":"meshing","pos":"(v)","ipa":"/ˈmɛʃ.ɪŋ/","defVi":"ăn khớp, kết hợp hài hòa","defEn":"engaging or fitting together closely and smoothly","examples":["The gears are smoothly [meshing] together to keep the machine running. (=Dịch: Các bánh răng đang ăn khớp nhịp nhàng với nhau để giữ cho cỗ máy hoạt động.)","She excels at [meshing] creative ideas with practical business strategies. (=Dịch: Cô ấy rất giỏi trong việc kết hợp hài hòa các ý tưởng sáng tạo với chiến lược kinh doanh thực tế.)","The two departments are successfully [meshing] their resources for the new project. (=Dịch: Hai phòng ban đang kết hợp thành công các nguồn lực cho dự án mới.)"],"ukAudio":"/ai_services/tts3/?q=meshing&lang=en-GB&ipa=%2F%CB%88m%C9%9B%CA%83.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=meshing&lang=en-US&ipa=%2F%CB%88m%C9%9B%CA%83.%C9%AA%C5%8B%2F"},{"id":"lv_5_225","topic":"Nature and Environmental Protection","word":"microbe","pos":"(n)","ipa":"/ˈmaɪ.kroʊb/","defVi":"vi trùng, vi sinh vật","defEn":"an extremely small living thing that can only be seen with a microscope, especially one causing disease","examples":["Soil contains millions of [microbe] species that help plants absorb nutrients. (=Dịch: Đất chứa hàng triệu loài vi sinh vật giúp cây cối hấp thụ chất dinh dưỡng.)","The new disinfectant is highly effective at killing every harmful [microbe]. (=Dịch: Chất khử trùng mới rất hiệu quả trong việc tiêu diệt mọi loại vi trùng có hại.)","Researchers discovered a novel [microbe] living deep beneath the ocean floor. (=Dịch: Các nhà nghiên cứu đã phát hiện một loại vi sinh vật mới sống sâu dưới đáy đại dương.)"],"ukAudio":"/ai_services/tts3/?q=microbe&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kro%CA%8Ab%2F","usAudio":"/ai_services/tts3/?q=microbe&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kro%CA%8Ab%2F"},{"id":"lv_5_226","topic":"Nature and Environmental Protection","word":"microplastic","pos":"(n)","ipa":"/ˈmaɪ.kroʊˌplæs.tɪk/","defVi":"hạt vi nhựa","defEn":"an extremely small piece of plastic debris found in the environment","examples":["Scientists found [microplastic] particles in the stomach of marine animals. (=Dịch: Các nhà khoa học đã tìm thấy các hạt vi nhựa trong dạ dày của các loài sinh vật biển.)","Synthetic clothing releases thousands of [microplastic] fibers during each wash. (=Dịch: Quần áo từ sợi tổng hợp thải ra hàng nghìn sợi vi nhựa sau mỗi lần giặt.)","Reducing plastic consumption is crucial to limiting [microplastic] pollution. (=Dịch: Cắt giảm tiêu thụ nhựa là điều quan trọng để hạn chế ô nhiễm vi nhựa.)"],"ukAudio":"/ai_services/tts3/?q=microplastic&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kro%CA%8A%CB%8Cpl%C3%A6s.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=microplastic&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kro%CA%8A%CB%8Cpl%C3%A6s.t%C9%AAk%2F"},{"id":"lv_5_227","topic":"Nature and Environmental Protection","word":"microscopic","pos":"(adj)","ipa":"/ˌmaɪ.krəˈskɑː.pɪk/","defVi":"kính hiển vi mới thấy được, siêu nhỏ","defEn":"so small that it can only be seen with a microscope","examples":["Bacteria are [microscopic] organisms that live on nearly every surface. (=Dịch: Vi khuẩn là những sinh vật siêu nhỏ sống trên hầu như mọi bề mặt.)","The engineer detected a [microscopic] crack in the metal turbine. (=Dịch: Kỹ sư đã phát hiện ra một vết nứt siêu nhỏ trong tuabin kim loại.)","Phytoplankton are [microscopic] plants floating in ocean waters. (=Dịch: Thực vật phù du là những loài thực vật kích thước hiển vi trôi nổi trong nước biển.)"],"ukAudio":"/ai_services/tts3/?q=microscopic&lang=en-GB&ipa=%2F%CB%8Cma%C9%AA.kr%C9%99%CB%88sk%C9%91%CB%90.p%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=microscopic&lang=en-US&ipa=%2F%CB%8Cma%C9%AA.kr%C9%99%CB%88sk%C9%91%CB%90.p%C9%AAk%2F"},{"id":"lv_5_228","topic":"Nature and Environmental Protection","word":"migrate","pos":"(v)","ipa":"/ˈmaɪ.ɡreɪt/","defVi":"Di cư, di trú","defEn":"To move from one region or habitat to another, especially according to the seasons","examples":["Many birds [migrate] south to warmer climates during the winter. (=Dịch: Nhiều loài chim di cư về phía nam đến những vùng khí hậu ấm hơn trong suốt mùa đông.)","Thousands of farm workers [migrate] to cities in search of seasonal employment. (=Dịch: Hàng nghìn lao động nông nghiệp di cư đến các thành phố để tìm kiếm việc làm thời vụ.)","Whales [migrate] great distances across the ocean to reach their feeding grounds. (=Dịch: Cá voi di cư qua những quãng đường rất dài trên đại dương để đến các bãi kiếm ăn.)"],"ukAudio":"/ai_services/tts3/?q=migrate&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=migrate&lang=en-US&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F"},{"id":"lv_5_229","topic":"Nature and Environmental Protection","word":"migration","pos":"(n)","ipa":"/maɪˈɡreɪ.ʃən/","defVi":"sự di cư, tập tính di trú","defEn":"the seasonal movement of animals or birds from one region to another","examples":["The annual [migration] of wildebeests across the Serengeti is a breathtaking spectacle. (=Dịch: Cuộc di cư hàng năm của linh dương đầu bò qua Serengeti là một cảnh tượng ngoạn mục.)","Rising temperatures are altering the timing of bird [migration] across North America. (=Dịch: Nhiệt độ tăng cao đang làm thay đổi thời gian di cư của các loài chim trên khắp Bắc Mỹ.)","Whales travel thousands of miles during their seasonal [migration] to warmer waters. (=Dịch: Cá voi di chuyển hàng nghìn dặm trong chuyến di cư theo mùa đến những vùng nước ấm hơn.)"],"ukAudio":"/ai_services/tts3/?q=migration&lang=en-GB&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=migration&lang=en-US&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_230","topic":"Nature and Environmental Protection","word":"military","pos":"(adj)","ipa":"/ˈmɪl.əˌter.i/","defVi":"thuộc về quân đội, quân sự","defEn":"relating to the armed forces or soldiers of a country","examples":["The country increased its [military] spending to strengthen border defense. (=Dịch: Quốc gia này đã tăng chi tiêu quân sự để củng cố phòng thủ biên giới.)","He completed two years of mandatory [military] service after university. (=Dịch: Anh ấy đã hoàn thành hai năm nghĩa vụ quân sự bắt buộc sau khi tốt nghiệp đại học.)","Drones are increasingly used for reconnaissance in modern [military] operations. (=Dịch: Máy bay không người lái ngày càng được sử dụng nhiều cho hoạt động do thám trong các chiến dịch quân sự hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=military&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Cter.i%2F","usAudio":"/ai_services/tts3/?q=military&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Cter.i%2F"},{"id":"lv_5_231","topic":"Nature and Environmental Protection","word":"millimetre","pos":"(n)","ipa":"/ˈmɪl.ə.ˌmi.t̬ər/","defVi":"mi-li-mét (mm)","defEn":"a unit of length equal to one thousandth of a meter","examples":["The metal component was manufactured with an error margin of less than one [millimetre]. (=Dịch: Linh kiện kim loại được sản xuất với mức dung sai nhỏ hơn một mi-li-mét.)","The tiny ant measured only three [millimetre]s in total body length. (=Dịch: Con kiến bé xíu chỉ có chiều dài cơ thể tổng cộng là ba mi-li-mét.)","The heavy rainfall added twenty [millimetre]s of water to the reservoir overnight. (=Dịch: Trận mưa lớn đã làm mực nước hồ chứa tăng thêm hai mươi mi-li-mét chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=millimetre&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99.%CB%8Cmi.t%CC%AC%C9%99r%2F","usAudio":"/ai_services/tts3/?q=millimetre&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99.%CB%8Cmi.t%CC%AC%C9%99r%2F"},{"id":"lv_5_232","topic":"Nature and Environmental Protection","word":"miner","pos":"(n)","ipa":"/ˈmaɪ.nɚ/","defVi":"thợ mỏ","defEn":"a person who works underground extracting coal, minerals, or precious metals","examples":["The rescue team worked tirelessly to save the trapped [miner] after the cave-in. (=Dịch: Đội cứu hộ đã làm việc không mệt mỏi để cứu người thợ mỏ bị mắc kẹt sau vụ sập hầm.)","A gold [miner] must endure harsh physical conditions every day. (=Dịch: Một người thợ mỏ vàng phải chịu đựng những điều kiện thể chất khắc nghiệt mỗi ngày.)","His grandfather was a coal [miner] who spent forty years underground. (=Dịch: Ông của anh ấy từng là một thợ mỏ than đã dành bốn mươi năm làm việc dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=miner&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=miner&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%9A%2F"},{"id":"lv_5_233","topic":"Nature and Environmental Protection","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai khoáng, hoạt động khai thác mỏ","defEn":"the process or industry of extracting coal or other minerals from the earth","examples":["The economy of the region depends heavily on copper [mining]. (=Dịch: Nền kinh tế của khu vực này phụ thuộc nhiều vào việc khai thác đồng.)","Environmentalists are concerned about the impact of deep-sea [mining] on marine life. (=Dịch: Các nhà bảo vệ môi trường lo ngại về tác động của việc khai thác mỏ dưới biển sâu đối với sinh vật biển.)","New regulations were introduced to make the [mining] industry safer for workers. (=Dịch: Các quy định mới đã được ban hành nhằm giúp ngành khai khoáng an toàn hơn cho người lao động.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_5_234","topic":"Nature and Environmental Protection","word":"mixture","pos":"(n)","ipa":"/ˈmɪks.tʃɚ/","defVi":"Hỗn hợp, sự pha trộn.","defEn":"A substance made by combining two or more different things together.","examples":["Add the eggs to the flour [mixture] and stir gently until smooth. (=Dịch: Cho trứng vào hỗn hợp bột mì và khuấy nhẹ cho đến khi mịn.)","Her feelings about leaving her hometown were a complex [mixture] of excitement and fear. (=Dịch: Cảm xúc của cô khi rời quê hương là một sự pha trộn phức tạp giữa phấn khích và sợ hãi.)","Air is a [mixture] of gases including nitrogen and oxygen. (=Dịch: Không khí là một hỗn hợp các chất khí bao gồm nitơ và oxy.)"],"ukAudio":"/ai_services/tts3/?q=mixture&lang=en-GB&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mixture&lang=en-US&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F"},{"id":"lv_5_235","topic":"Nature and Environmental Protection","word":"moist","pos":"(adj)","ipa":"/mɔɪst/","defVi":"Ẩm ướt, ẩm nhẹ.","defEn":"Slightly wet, often in a pleasant or desirable way.","examples":["The cake was delicious and delightfully [moist]. (=Dịch: Chiếc bánh rất ngon và có độ ẩm xốp vừa phải.)","Keep the soil [moist] but not completely soaked. (=Dịch: Hãy giữ cho đất ẩm nhưng không bị sũng nước hoàn toàn.)","She used a cream to keep her skin soft and [moist]. (=Dịch: Cô ấy đã sử dụng kem dưỡng để giữ cho làn da mềm mại và đủ ẩm.)"],"ukAudio":"/ai_services/tts3/?q=moist&lang=en-GB&ipa=%2Fm%C9%94%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=moist&lang=en-US&ipa=%2Fm%C9%94%C9%AAst%2F"},{"id":"lv_5_236","topic":"Nature and Environmental Protection","word":"monitor","pos":"(v)","ipa":"/ˈmɑː.nɪ.tər/","defVi":"giám sát, theo dõi","defEn":"to watch and check something carefully over a period of time","examples":["Doctors will [monitor] the patient's heart rate throughout the surgery. (=Dịch: Các bác sĩ sẽ theo dõi nhịp tim của bệnh nhân trong suốt ca phẫu thuật.)","Environmental agencies [monitor] air quality in major cities daily. (=Dịch: Các cơ quan môi trường giám sát chất lượng không khí ở các thành phố lớn hàng ngày.)","Teachers use regular quizzes to [monitor] their students' progress. (=Dịch: Giáo viên sử dụng các bài kiểm tra thường xuyên để theo dõi tiến độ của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=monitor&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=monitor&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%AA.t%C9%99r%2F"},{"id":"lv_5_237","topic":"Nature and Environmental Protection","word":"moss","pos":"(n)","ipa":"/mɔːs/","defVi":"rêu","defEn":"a very small, soft green plant that grows on damp soil, rocks, or trees","examples":["Green [moss] covered the northern side of the ancient stone wall. (=Dịch: Rêu xanh bao phủ mặt phía bắc của bức tường đá cổ kính.)","The damp forest floor was carpeted with thick, soft [moss]. (=Dịch: Mặt đất rừng ẩm ướt được trải một lớp thảm rêu dày và mềm mại.)","Certain types of [moss] are useful indicators of air pollution levels. (=Dịch: Một số loại rêu là chỉ dấu hữu ích về mức độ ô nhiễm không khí.)"],"ukAudio":"/ai_services/tts3/?q=moss&lang=en-GB&ipa=%2Fm%C9%94%CB%90s%2F","usAudio":"/ai_services/tts3/?q=moss&lang=en-US&ipa=%2Fm%C9%94%CB%90s%2F"},{"id":"lv_5_238","topic":"Nature and Environmental Protection","word":"mud","pos":"(n)","ipa":"/mʌd/","defVi":"bùn, sình lầy","defEn":"wet, soft, and sticky earth or soil","examples":["The heavy rain turned the dirt path into thick [mud]. (=Dịch: Cơn mưa lớn đã biến con đường đất thành bùn lầy đặc quánh.)","Her boots were caked with [mud] after hiking through the swamp. (=Dịch: Đôi ủng của cô ấy bị đóng đầy bùn sau khi đi bộ qua đầm lầy.)","Children love playing in the [mud] after a summer shower. (=Dịch: Trẻ em rất thích chơi trong bùn sau cơn mưa rào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=mud&lang=en-GB&ipa=%2Fm%CA%8Cd%2F","usAudio":"/ai_services/tts3/?q=mud&lang=en-US&ipa=%2Fm%CA%8Cd%2F"},{"id":"lv_5_239","topic":"Nature and Environmental Protection","word":"naturalist","pos":"(n)","ipa":"/ˈnætʃ.ɚ.ə.lɪst/","defVi":"nhà tự nhiên học","defEn":"an expert in or student of natural history, especially plants and animals","examples":["Charles Darwin was a famous [naturalist] who developed the theory of evolution. (=Dịch: Charles Darwin là một nhà tự nhiên học nổi tiếng, người đã phát triển thuyết tiến hóa.)","The [naturalist] documented several rare bird species in the rainforest. (=Dịch: Nhà tự nhiên học đã ghi chép lại một số loài chim quý hiếm trong rừng nhiệt đới.)","As a passionate [naturalist], she spent years studying local insect behaviors. (=Dịch: Là một nhà tự nhiên học đầy nhiệt huyết, cô đã dành nhiều năm để nghiên cứu tập tính của côn trùng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=naturalist&lang=en-GB&ipa=%2F%CB%88n%C3%A6t%CA%83.%C9%9A.%C9%99.l%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=naturalist&lang=en-US&ipa=%2F%CB%88n%C3%A6t%CA%83.%C9%9A.%C9%99.l%C9%AAst%2F"},{"id":"lv_5_240","topic":"Nature and Environmental Protection","word":"navigation","pos":"(n)","ipa":"/ˌnæv.əˈɡeɪ.ʃən/","defVi":"sự định hướng, điều hướng, hàng hải","defEn":"the act or science of finding the way to a destination","examples":["Modern cars are often equipped with satellite [navigation] systems. (=Dịch: Xe ô tô hiện đại thường được trang bị hệ thống định vị vệ tinh.)","Early sailors relied on the stars for [navigation] across the open sea. (=Dịch: Các thủy thủ thời xưa dựa vào các vì sao để định hướng trên biển rộng.)","Clear [navigation] makes a website much easier for users to explore. (=Dịch: Hệ thống điều hướng rõ ràng giúp người dùng khám phá trang web dễ dàng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=navigation&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6v.%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=navigation&lang=en-US&ipa=%2F%CB%8Cn%C3%A6v.%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_241","topic":"Nature and Environmental Protection","word":"nesting","pos":"(n)","ipa":"/ˈnɛs.tɪŋ/","defVi":"Sự làm tổ, sự đẻ trứng tại tổ","defEn":"The activity of building or occupying a nest, especially by birds or sea turtles, to lay eggs","examples":["Spring is the main [nesting] season for most local bird species. (=Dịch: Mùa xuân là mùa làm tổ chính của hầu hết các loài chim địa phương.)","The coastal area was closed to tourists to protect the sea turtles' [nesting] sites. (=Dịch: Khu vực ven biển đã bị đóng cửa đối với du khách để bảo vệ các địa điểm làm tổ của rùa biển.)","Researchers monitored the [nesting] habits of eagles using hidden cameras. (=Dịch: Các nhà nghiên cứu đã theo dõi tập tính làm tổ của đại bàng bằng máy quay giấu kín.)"],"ukAudio":"/ai_services/tts3/?q=nesting&lang=en-GB&ipa=%2F%CB%88n%C9%9Bs.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=nesting&lang=en-US&ipa=%2F%CB%88n%C9%9Bs.t%C9%AA%C5%8B%2F"},{"id":"lv_5_242","topic":"Nature and Environmental Protection","word":"net","pos":"(n)","ipa":"/nɛt/","defVi":"lưới, mạng lưới","defEn":"a material made of crossed threads or wires with evenly spaced openings","examples":["The fisherman cast his [net] into the calm morning waters. (=Dịch: Người đánh cá quăng tấm lưới của mình xuống làn nước êm ả buổi sáng.)","The tennis ball hit the top of the [net] and bounced back onto our side. (=Dịch: Quả bóng tennis đập vào mép trên của lưới rồi nảy ngược lại phần sân của chúng tôi.)","Gardeners use protective [net] to keep birds away from ripening berries. (=Dịch: Những người làm vườn sử dụng lưới bảo vệ để ngăn chim chóc tiếp cận quả mọng đang chín.)"],"ukAudio":"/ai_services/tts3/?q=net&lang=en-GB&ipa=%2Fn%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=net&lang=en-US&ipa=%2Fn%C9%9Bt%2F"},{"id":"lv_5_243","topic":"Nature and Environmental Protection","word":"new zealand","pos":"(n)","ipa":"/ˌnuː ˈziː.lənd/","defVi":"nước New Zealand (Tân Tây Lan)","defEn":"an island country in the southwestern Pacific Ocean","examples":["Many tourists visit [New zealand] to explore its stunning fjords and mountains. (=Dịch: Nhiều du khách đến thăm New Zealand để khám phá những vịnh hẹp và dãy núi tuyệt đẹp.)","Agriculture and tourism are key sectors of the economy in [New zealand]. (=Dịch: Nông nghiệp và du lịch là những ngành kinh tế then chốt ở New Zealand.)","The indigenous Maori culture plays a vital role in modern [New zealand]. (=Dịch: Văn hóa bản địa Maori đóng một vai trò quan trọng ở New Zealand ngày nay.)"],"ukAudio":"/ai_services/tts3/?q=new+zealand&lang=en-GB&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=new+zealand&lang=en-US&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F"},{"id":"lv_5_244","topic":"Nature and Environmental Protection","word":"nuclear","pos":"(adj)","ipa":"/ˈnuː.kli.ɚ/","defVi":"(thuộc) hạt nhân, nguyên tử","defEn":"relating to the nucleus of an atom, or using energy produced by splitting atoms","examples":["Several countries rely on [nuclear] power to generate electricity without carbon emissions. (=Dịch: Một số quốc gia dựa vào năng lượng hạt nhân để sản xuất điện mà không phát thải carbon.)","The government signed a treaty aimed at preventing the proliferation of [nuclear] weapons. (=Dịch: Chính phủ đã ký một hiệp ước nhằm ngăn chặn sự phổ biến vũ khí hạt nhân.)","Scientists are researching safer methods for disposing of [nuclear] waste. (=Dịch: Các nhà khoa học đang nghiên cứu các phương pháp an toàn hơn để xử lý chất thải hạt nhân.)"],"ukAudio":"/ai_services/tts3/?q=nuclear&lang=en-GB&ipa=%2F%CB%88nu%CB%90.kli.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=nuclear&lang=en-US&ipa=%2F%CB%88nu%CB%90.kli.%C9%9A%2F"},{"id":"lv_5_245","topic":"Nature and Environmental Protection","word":"nutrient","pos":"(n)","ipa":"/ˈnuː.tri.ənt/","defVi":"chất dinh dưỡng, dưỡng chất","defEn":"a substance that plants or animals need in order to live, grow, and stay healthy","examples":["Vegetables are rich in vitamins, minerals, and other essential [nutrient] sources. (=Dịch: Rau củ rất giàu vitamin, khoáng chất và các nguồn dưỡng chất thiết yếu khác.)","Fertile soil provides every necessary [nutrient] for crop cultivation. (=Dịch: Đất màu mỡ cung cấp mọi chất dinh dưỡng cần thiết cho việc trồng trọt.)","A deficiency in a single vital [nutrient] can cause significant health problems. (=Dịch: Sự thiếu hụt một dưỡng chất quan trọng duy nhất cũng có thể gây ra những vấn đề sức khỏe đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=nutrient&lang=en-GB&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=nutrient&lang=en-US&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F"},{"id":"lv_5_246","topic":"Nature and Environmental Protection","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, theo dõi","defEn":"the act of watching somebody or something carefully to gain information","examples":["The researcher spent months in the jungle doing field [observation]. (=Dịch: Nhà nghiên cứu đã dành nhiều tháng trong rừng sâu để thực hiện việc quan sát thực địa.)","The doctor kept the patient under close [observation] overnight. (=Dịch: Bác sĩ đã giữ bệnh nhân lại để theo dõi sát sao qua đêm.)","Her keen [observation] helped solve the mystery quickly. (=Dịch: Khả năng quan sát nhạy bén của cô ấy đã giúp giải quyết điều bí ẩn một cách nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_247","topic":"Nature and Environmental Protection","word":"observer","pos":"(n)","ipa":"/əbˈzɝː.vɚ/","defVi":"người quan sát, quan sát viên","defEn":"a person who watches or notices something, especially for an official or scientific purpose","examples":["An independent [observer] was invited to monitor the national election. (=Dịch: Một quan sát viên độc lập đã được mời đến để giám sát cuộc bầu cử quốc gia.)","To a casual [observer], the two paintings might look identical. (=Dịch: Đối với một người quan sát bình thường, hai bức tranh có thể trông giống hệt nhau.)","The trained [observer] noted subtle changes in the animal's behavior. (=Dịch: Người quan sát có chuyên môn đã ghi nhận những thay đổi tinh tế trong hành vi của con vật.)"],"ukAudio":"/ai_services/tts3/?q=observer&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%9D%CB%90.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=observer&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%9D%CB%90.v%C9%9A%2F"},{"id":"lv_5_248","topic":"Nature and Environmental Protection","word":"onshore","pos":"(adj)","ipa":"/ˈɑːn.ʃɔːr/","defVi":"trên bờ, trên đất liền; hướng vào bờ","defEn":"located, occurring, or moving on land rather than at sea","examples":["The government is investing heavily in [onshore] wind farms. (=Dịch: Chính phủ đang đầu tư mạnh vào các trang trại điện gió trên bờ liền.)","An [onshore] breeze brought cool air to the coastal town. (=Dịch: Một làn gió thổi vào bờ mang lại không khí mát mẻ cho thị trấn ven biển.)","The company decided to shift to [onshore] oil drilling operations. (=Dịch: Công ty đã quyết định chuyển sang các hoạt động khoan dầu trên đất liền.)"],"ukAudio":"/ai_services/tts3/?q=onshore&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90n.%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=onshore&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90n.%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_249","topic":"Nature and Environmental Protection","word":"organ","pos":"(n)","ipa":"/ˈɔr.ɡən/","defVi":"cơ quan, bộ phận cơ thể","defEn":"a part of the body that performs a specific vital function","examples":["The heart is a vital [organ] that pumps blood throughout the body. (=Dịch: Tim là một cơ quan quan trọng bơm máu đi khắp cơ thể.)","Excessive alcohol consumption can damage your internal [organ] systems. (=Dịch: Uống quá nhiều rượu bia có thể gây tổn hại cho các hệ cơ quan nội tạng của bạn.)","The skin is actually the largest [organ] of the human body. (=Dịch: Da thực chất là cơ quan lớn nhất của cơ thể con người.)"],"ukAudio":"/ai_services/tts3/?q=organ&lang=en-GB&ipa=%2F%CB%88%C9%94r.%C9%A1%C9%99n%2F","usAudio":"/ai_services/tts3/?q=organ&lang=en-US&ipa=%2F%CB%88%C9%94r.%C9%A1%C9%99n%2F"},{"id":"lv_5_250","topic":"Nature and Environmental Protection","word":"organic","pos":"(adj)","ipa":"/ɔːrˈɡæn.ɪk/","defVi":"hữu cơ, không dùng phân bón hóa học","defEn":"produced without using artificial chemicals or pesticides","examples":["Many supermarkets now offer a wide range of [organic] vegetables. (=Dịch: Nhiều siêu thị hiện nay cung cấp đa dạng các loại rau hữu cơ.)","The farm transitioned to [organic] agriculture five years ago. (=Dịch: Trang trại đã chuyển đổi sang nền nông nghiệp hữu cơ cách đây 5 năm.)","Consumers are often willing to pay more for certified [organic] food. (=Dịch: Người tiêu dùng thường sẵn sàng trả nhiều tiền hơn cho thực phẩm hữu cơ đã được chứng nhận.)"],"ukAudio":"/ai_services/tts3/?q=organic&lang=en-GB&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=organic&lang=en-US&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F"},{"id":"lv_5_251","topic":"Nature and Environmental Protection","word":"organism","pos":"(n)","ipa":"/ˈɔːr.ɡən.ɪ.zəm/","defVi":"sinh vật, cơ thể sống","defEn":"an individual animal, plant, or single-celled life form","examples":["A coral reef is home to thousands of different [organism] species. (=Dịch: Rạn san hô là nơi sinh sống của hàng ngàn loài sinh vật khác nhau.)","Bacteria are tiny [organism] forms that can survive in extreme environments. (=Dịch: Vi khuẩn là các dạng sinh vật nhỏ bé có thể sống sót trong những môi trường khắc nghiệt.)","Every living [organism] requires water to survive and function properly. (=Dịch: Mọi sinh vật sống đều cần nước để tồn tại và hoạt động bình thường.)"],"ukAudio":"/ai_services/tts3/?q=organism&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99n.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=organism&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99n.%C9%AA.z%C9%99m%2F"},{"id":"lv_5_252","topic":"Nature and Environmental Protection","word":"overpopulation","pos":"(n)","ipa":"/ˌoʊ.vərˌpɑː.pjəˈleɪ.ʃən/","defVi":"tình trạng bùng nổ dân số, quá tải dân số","defEn":"a situation where too many people or animals live in a place with insufficient resources","examples":["Many urban planners believe that [overpopulation] is the root cause of traffic congestion. (=Dịch: Nhiều nhà quy hoạch đô thị tin rằng quá tải dân số là nguyên nhân gốc rễ của tình trạng ùn tắc giao thông.)","The government is trying to tackle [overpopulation] by encouraging families to move to smaller towns. (=Dịch: Chính phủ đang cố gắng giải quyết tình trạng quá tải dân số bằng cách khuyến khích các gia đình chuyển đến các thị trấn nhỏ hơn.)","Severe [overpopulation] puts immense pressure on natural resources such as water and arable land. (=Dịch: Sự bùng nổ dân số nghiêm trọng tạo áp lực to lớn lên các tài nguyên thiên nhiên như nước và đất canh tác.)"],"ukAudio":"/ai_services/tts3/?q=overpopulation&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=overpopulation&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_253","topic":"Nature and Environmental Protection","word":"oxford","pos":"(n)","ipa":"/ˈɑːks.fərd/","defVi":"thành phố Oxford (Anh); kiểu giày Oxford buộc dây","defEn":"a city in England famous for its prestigious university, or a type of leather shoe","examples":["She was accepted to study history at [Oxford] University. (=Dịch: Cô ấy đã được nhận vào học ngành lịch sử tại Đại học Oxford.)","He wore polished [oxford] shoes to his job interview. (=Dịch: Anh ấy đã mang một đôi giày oxford bóng loáng đến buổi phỏng vấn xin việc.)","Many historic buildings attract tourists to the city of [Oxford]. (=Dịch: Nhiều công trình lịch sử thu hút khách du lịch đến thành phố Oxford.)"],"ukAudio":"/ai_services/tts3/?q=oxford&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%99rd%2F","usAudio":"/ai_services/tts3/?q=oxford&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%99rd%2F"},{"id":"lv_5_254","topic":"Nature and Environmental Protection","word":"oxygen","pos":"(n)","ipa":"/ˈɑːk.sə.dʒən/","defVi":"khí ô-xy","defEn":"a chemical element that is a colorless, odorless gas essential for most living organisms","examples":["Trees absorb carbon dioxide and release [oxygen] into the atmosphere. (=Dịch: Cây cối hấp thụ khí carbon dioxide và giải phóng khí ô-xy vào khí quyển.)","Divers must monitor their [oxygen] tanks closely while exploring deep waters. (=Dịch: Thợ lặn phải theo dõi sát sao bình dưỡng khí ô-xy của họ khi khám phá các vùng nước sâu.)","A decrease in [oxygen] levels in lakes can lead to massive fish deaths. (=Dịch: Sự suy giảm nồng độ ô-xy trong các hồ nước có thể dẫn đến việc cá chết hàng loạt.)"],"ukAudio":"/ai_services/tts3/?q=oxygen&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90k.s%C9%99.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=oxygen&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90k.s%C9%99.d%CA%92%C9%99n%2F"},{"id":"lv_5_255","topic":"Nature and Environmental Protection","word":"ozone","pos":"(n)","ipa":"/ˈoʊ.zoʊn/","defVi":"khí ô-dôn (tầng ô-dôn)","defEn":"a form of oxygen that forms a layer in the atmosphere protecting the Earth from ultraviolet radiation","examples":["The [ozone] layer shields living organisms from harmful ultraviolet radiation. (=Dịch: Tầng ô-dôn che chắn cho các sinh vật sống khỏi bức xạ cực tím độc hại.)","Damage to the [ozone] layer has led to an increase in skin cancer rates. (=Dịch: Sự suy giảm tầng ô-dôn đã dẫn đến sự gia tăng tỷ lệ mắc bệnh ung thư da.)","International agreements have helped reduce emissions that destroy [ozone]. (=Dịch: Các hiệp định quốc tế đã giúp giảm lượng khí thải phá hủy tầng ô-dôn.)"],"ukAudio":"/ai_services/tts3/?q=ozone&lang=en-GB&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=ozone&lang=en-US&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F"},{"id":"lv_5_256","topic":"Nature and Environmental Protection","word":"pacific","pos":"(adj)","ipa":"/pəˈsɪf.ɪk/","defVi":"Hòa bình, thanh bình, yên ổn.","defEn":"Peaceful in character or intent.","examples":["The two nations reached a [pacific] solution to the border conflict. (=Dịch: Hai quốc gia đã đạt được một giải pháp hòa bình cho cuộc xung đột biên giới.)","He was praised for his [pacific] temperament during tense debates. (=Dịch: Ông ấy được khen ngợi vì thái độ điềm đạm, chuộng hòa bình trong các cuộc tranh luận căng thẳng.)","They sought to establish [pacific] relations with their neighboring countries. (=Dịch: Họ tìm cách thiết lập mối quan hệ hòa bình với các nước láng giềng.)"],"ukAudio":"/ai_services/tts3/?q=pacific&lang=en-GB&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=pacific&lang=en-US&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F"},{"id":"lv_5_257","topic":"Nature and Environmental Protection","word":"packaging","pos":"(n)","ipa":"/ˈpæk.ɪ.dʒɪŋ/","defVi":"bao bì, sự đóng gói","defEn":"the materials used to wrap and protect goods sold in stores","examples":["The company switched to eco-friendly [packaging] to minimize plastic waste. (=Dịch: Công ty đã chuyển sang bao bì thân thiện với môi trường để giảm thiểu rác thải nhựa.)","Attractive [packaging] often plays a key role in influencing consumer choices. (=Dịch: Bao bì bắt mắt thường đóng vai trò quan trọng trong việc tác động đến lựa chọn của người tiêu dùng.)","All product details and nutritional facts are printed clearly on the [packaging]. (=Dịch: Tất cả thông tin chi tiết về sản phẩm và thành phần dinh dưỡng đều được in rõ ràng trên bao bì.)"],"ukAudio":"/ai_services/tts3/?q=packaging&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=packaging&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_5_258","topic":"Nature and Environmental Protection","word":"parasite","pos":"(n)","ipa":"/ˈper.ə.saɪt/","defVi":"ký sinh trùng, sinh vật ký sinh","defEn":"an organism that lives on or in a host and gets its food from or at the expense of its host","examples":["Fleas and ticks are common [parasite] species that live on mammals. (=Dịch: Bọ chét và ve là những loài ký sinh trùng phổ biến sống trên động vật có vú.)","The internal [parasite] caused severe abdominal pain in the host animal. (=Dịch: Loài ký sinh trùng đường ruột đã gây ra đau bụng dữ dội ở vật chủ.)","Clean drinking water prevents the spread of waterborne [parasite] infections. (=Dịch: Nguồn nước uống sạch giúp ngăn chặn sự lây lan của các bệnh nhiễm trùng do ký sinh trùng truyền qua nước.)"],"ukAudio":"/ai_services/tts3/?q=parasite&lang=en-GB&ipa=%2F%CB%88per.%C9%99.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=parasite&lang=en-US&ipa=%2F%CB%88per.%C9%99.sa%C9%AAt%2F"},{"id":"lv_5_259","topic":"Nature and Environmental Protection","word":"particle","pos":"(n)","ipa":"/ˈpɑːr.t̬ɪ.kəl/","defVi":"hạt, vi hạt","defEn":"a minute portion of matter","examples":["Air filters are designed to remove dust [particle] from indoor environments. (=Dịch: Máy lọc không khí được thiết kế để loại bỏ các hạt bụi khỏi môi trường trong nhà.)","Scientists study subatomic [particle] interactions in massive accelerators. (=Dịch: Các nhà khoa học nghiên cứu sự tương tác của các hạt hạ nguyên tử trong những máy gia tốc khổng lồ.)","There was not a single [particle] of evidence to support his wild theory. (=Dịch: Không hề có một mảy may bằng chứng nào hỗ trợ cho giả thuyết kỳ quặc của anh ta.)"],"ukAudio":"/ai_services/tts3/?q=particle&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=particle&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F"},{"id":"lv_5_260","topic":"Nature and Environmental Protection","word":"patch","pos":"(n)","ipa":"/pætʃ/","defVi":"mảnh đất nhỏ, miếng vá","defEn":"a small piece of land differing from the area around it, or material used to cover a hole","examples":["He grows organic vegetables in a small [patch] behind his cottage. (=Dịch: Anh ấy trồng rau hữu cơ trên một mảnh đất nhỏ phía sau ngôi nhà tranh của mình.)","The jacket had a leather [patch] sewn over the worn elbow area. (=Dịch: Chiếc áo khoác có một miếng vá bằng da được may đè lên phần khuỷu tay đã sờn.)","Drivers must slow down when approaching this icy [patch] on the mountain road. (=Dịch: Các tài xế phải giảm tốc độ khi đi đến đoạn đường đóng băng này trên đèo núi.)"],"ukAudio":"/ai_services/tts3/?q=patch&lang=en-GB&ipa=%2Fp%C3%A6t%CA%83%2F","usAudio":"/ai_services/tts3/?q=patch&lang=en-US&ipa=%2Fp%C3%A6t%CA%83%2F"},{"id":"lv_5_261","topic":"Nature and Environmental Protection","word":"peanut","pos":"(n)","ipa":"/ˈpi.nʌt/","defVi":"củ lạc, đậu phộng","defEn":"an oval nut with a thin shell that grows underground and can be eaten","examples":["He has a severe allergy to [peanut] butter. (=Dịch: Anh ấy bị dị ứng nghiêm trọng với bơ đậu phộng.)","A small [peanut] dropped from the table onto the floor. (=Dịch: Một hạt đậu phộng nhỏ đã rơi từ trên bàn xuống sàn nhà.)","She bought a bag of roasted [peanut] snacks at the market. (=Dịch: Cô ấy đã mua một túi đồ ăn vặt từ hạt lạc rang ở chợ.)"],"ukAudio":"/ai_services/tts3/?q=peanut&lang=en-GB&ipa=%2F%CB%88pi.n%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=peanut&lang=en-US&ipa=%2F%CB%88pi.n%CA%8Ct%2F"},{"id":"lv_5_262","topic":"Nature and Environmental Protection","word":"pellet","pos":"(n)","ipa":"/ˈpel.ɪt/","defVi":"viên nhỏ, viên nén","defEn":"a small, rounded, compressed mass of a substance","examples":["Farmers feed their livestock with nutritious food [pellet] every morning. (=Dịch: Nông dân cho gia súc ăn những viên thức ăn bổ dưỡng vào mỗi buổi sáng.)","Wood [pellet] fuel is becoming a popular alternative for home heating. (=Dịch: Nhiên liệu viên nén gỗ đang trở thành một giải pháp thay thế phổ biến cho việc sưởi ấm gia đình.)","The plastic [pellet] must be melted down before being molded into new products. (=Dịch: Hạt nhựa cần được nấu chảy trước khi đúc thành các sản phẩm mới.)"],"ukAudio":"/ai_services/tts3/?q=pellet&lang=en-GB&ipa=%2F%CB%88pel.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pellet&lang=en-US&ipa=%2F%CB%88pel.%C9%AAt%2F"},{"id":"lv_5_263","topic":"Nature and Environmental Protection","word":"percentage","pos":"(n)","ipa":"/pər.ˈsɛn.t̬ɪdʒ/","defVi":"tỷ lệ phần trăm","defEn":"an amount expressed as a fraction of 100, or a proportion of a whole","examples":["A high [percentage] of students passed the final examination with excellent grades. (=Dịch: Một tỷ lệ phần trăm cao các sinh viên đã vượt qua kỳ thi cuối khóa với điểm số xuất sắc.)","The [percentage] of renewable energy used in the country has increased dramatically. (=Dịch: Tỷ lệ phần trăm năng lượng tái tạo được sử dụng ở quốc gia này đã tăng lên đáng kể.)","Only a small [percentage] of the surveyed customers reported issues with the product. (=Dịch: Chỉ một tỷ lệ phần trăm nhỏ khách hàng được khảo sát phản ánh về vấn đề của sản phẩm.)"],"ukAudio":"/ai_services/tts3/?q=percentage&lang=en-GB&ipa=%2Fp%C9%99r.%CB%88s%C9%9Bn.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=percentage&lang=en-US&ipa=%2Fp%C9%99r.%CB%88s%C9%9Bn.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_5_264","topic":"Nature and Environmental Protection","word":"perch","pos":"(n)","ipa":"/pɜrtʃ/","defVi":"chỗ đậu (của chim), cá peca (cá vược nước ngọt)","defEn":"a high place or branch where a bird rests, or a type of freshwater fish","examples":["The eagle scanned the valley from its high [perch] on the cliff edge. (=Dịch: Con đại bàng quan sát thung lũng từ chỗ đậu cao trên mép vách đá.)","He spent the quiet afternoon by the lake fishing for [perch] and trout. (=Dịch: Anh ấy đã dành cả buổi chiều yên ả bên hồ để câu cá peca và cá hồi.)","A small songbird flew down from its [perch] to catch a flying insect. (=Dịch: Một con chim hót nhỏ sà xuống từ cành đậu để bắt một con côn trùng đang bay.)"],"ukAudio":"/ai_services/tts3/?q=perch&lang=en-GB&ipa=%2Fp%C9%9Crt%CA%83%2F","usAudio":"/ai_services/tts3/?q=perch&lang=en-US&ipa=%2Fp%C9%9Crt%CA%83%2F"},{"id":"lv_5_265","topic":"Nature and Environmental Protection","word":"pigeon","pos":"(n)","ipa":"/ˈpɪ.dʒən/","defVi":"chim bồ câu","defEn":"a grey bird that is common in cities and often feeds in public squares","examples":["A wild [pigeon] landed on the windowsill this morning. (=Dịch: Một con chim bồ câu hoang dã đã đậu trên bậu cửa sổ sáng nay.)","Feeding a city [pigeon] in the square is prohibited by local laws. (=Dịch: Việc cho chim bồ câu thành phố ăn ở quảng trường bị luật pháp địa phương nghiêm cấm.)","She took a photograph of a white [pigeon] resting in the park. (=Dịch: Cô ấy đã chụp ảnh một con chim bồ câu trắng đang nghỉ ngơi trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=pigeon&lang=en-GB&ipa=%2F%CB%88p%C9%AA.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=pigeon&lang=en-US&ipa=%2F%CB%88p%C9%AA.d%CA%92%C9%99n%2F"},{"id":"lv_5_266","topic":"Nature and Environmental Protection","word":"pipe","pos":"(n)","ipa":"/paɪp/","defVi":"Ống dẫn (nước, khí...), đường ống.","defEn":"A tube through which liquids or gases can flow.","examples":["Water leaked from a broken [pipe] in the basement. (=Dịch: Nước rò rỉ từ một đường ống vỡ trong tầng hầm.)","Workers are installing a new gas [pipe] along the street. (=Dịch: Công nhân đang lắp đặt một đường ống dẫn khí mới dọc theo con phố.)","Cold weather caused the water [pipe] to freeze and burst. (=Dịch: Thời tiết lạnh giá làm đường ống nước bị đóng băng và vỡ tung.)"],"ukAudio":"/ai_services/tts3/?q=pipe&lang=en-GB&ipa=%2Fpa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=pipe&lang=en-US&ipa=%2Fpa%C9%AAp%2F"},{"id":"lv_5_267","topic":"Nature and Environmental Protection","word":"poacher","pos":"(n)","ipa":"/ˈpoʊ.tʃər/","defVi":"kẻ săn trộm động vật hoang dã","defEn":"a person who illegally catches or kills wild animals, birds, or fish","examples":["Park rangers managed to catch the dangerous [poacher] at midnight. (=Dịch: Các nhân viên kiểm lâm đã bắt được kẻ săn trộm nguy hiểm vào lúc nửa đêm.)","A heavily armed [poacher] was spotted near the nature reserve. (=Dịch: Một kẻ săn trộm vũ trang hạng nặng đã bị phát hiện gần khu bảo tồn thiên nhiên.)","Strict penalties are enforced to deter every [poacher] in the national park. (=Dịch: Các hình phạt nghiêm khắc được thực thi nhằm ngăn chặn mọi kẻ săn trộm trong công viên quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=poacher&lang=en-GB&ipa=%2F%CB%88po%CA%8A.t%CA%83%C9%99r%2F","usAudio":"/ai_services/tts3/?q=poacher&lang=en-US&ipa=%2F%CB%88po%CA%8A.t%CA%83%C9%99r%2F"},{"id":"lv_5_268","topic":"Nature and Environmental Protection","word":"poison","pos":"(n)","ipa":"/ˈpɔɪ.zən/","defVi":"chất độc, thuốc độc","defEn":"a substance that can cause illness or death if swallowed or absorbed","examples":["The dart frog produces a deadly [poison] on the surface of its skin. (=Dịch: Loài ếch phi tiêu tiết ra một chất độc chết người trên bề mặt da của nó.)","Always keep household chemicals and rat [poison] out of reach of children. (=Dịch: Luôn để hóa chất gia dụng và thuốc chuột xa tầm tay trẻ em.)","Rumors and jealousy acted like slow [poison] on their friendship. (=Dịch: Những lời đồn đại và sự đố kỵ đã tác động như chất độc ngấm dần vào tình bạn của họ.)"],"ukAudio":"/ai_services/tts3/?q=poison&lang=en-GB&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99n%2F","usAudio":"/ai_services/tts3/?q=poison&lang=en-US&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99n%2F"},{"id":"lv_5_269","topic":"Nature and Environmental Protection","word":"poisonous","pos":"(adj)","ipa":"/ˈpɔɪ.zə.nəs/","defVi":"có độc, độc hại","defEn":"capable of causing death or illness if taken into the body","examples":["Never eat wild mushrooms because some kinds are extremely [poisonous]. (=Dịch: Đừng bao giờ ăn nấm dại vì một số loại cực kỳ độc.)","The hikers were warned about a [poisonous] snake living in the grass. (=Dịch: Những người đi bộ đường dài đã được cảnh báo về một loài rắn độc sống trong bụi cỏ.)","The factory accidentally released [poisonous] gas into the local atmosphere. (=Dịch: Nhà máy đã vô tình thải khí độc vào bầu không khí địa phương.)"],"ukAudio":"/ai_services/tts3/?q=poisonous&lang=en-GB&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=poisonous&lang=en-US&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99.n%C9%99s%2F"},{"id":"lv_5_270","topic":"Nature and Environmental Protection","word":"polar","pos":"(adj)","ipa":"/ˈpoʊ.lər/","defVi":"(thuộc) vùng cực, địa cực","defEn":"relating to the North or South Pole and the cold regions around them","examples":["Rising temperatures threaten the natural habitat of the [polar] bear. (=Dịch: Nhiệt độ tăng đe dọa môi trường sống tự nhiên của loài gấu bắc cực.)","Explorers faced harsh blizzards during their dangerous [polar] expedition. (=Dịch: Các nhà thám hiểm đã đối mặt với những trận bão tuyết khắc nghiệt trong chuyến thám hiểm vùng cực đầy nguy hiểm.)","Melting ice caps are a major concern in the fragile [polar] ecosystem. (=Dịch: Băng tan ở các chỏm băng là mối lo ngại lớn đối với hệ sinh thái vùng cực mỏng manh.)"],"ukAudio":"/ai_services/tts3/?q=polar&lang=en-GB&ipa=%2F%CB%88po%CA%8A.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=polar&lang=en-US&ipa=%2F%CB%88po%CA%8A.l%C9%99r%2F"},{"id":"lv_5_271","topic":"Nature and Environmental Protection","word":"pole","pos":"(n)","ipa":"/poʊl/","defVi":"cực (Bắc cực hoặc Nam cực của Trái Đất)","defEn":"either of the two points at the northern and southern ends of the Earth's axis of rotation","examples":["Explorers faced extreme dangers while racing to reach the South [pole]. (=Dịch: Các nhà thám hiểm đã phải đối mặt với những hiểm nguy tột cùng khi chạy đua để tới được Nam Cực.)","The magnetic [pole] of the Earth slowly shifts position over long periods of time. (=Dịch: Cực từ của Trái Đất từ từ dịch chuyển vị trí qua những khoảng thời gian dài.)","Temperatures near either [pole] rarely rise above freezing even during the summer. (=Dịch: Nhiệt độ gần hai cực hiếm khi tăng lên trên mức đóng băng ngay cả vào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=pole&lang=en-GB&ipa=%2Fpo%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=pole&lang=en-US&ipa=%2Fpo%CA%8Al%2F"},{"id":"lv_5_272","topic":"Nature and Environmental Protection","word":"portuguese","pos":"(adj)","ipa":"/ˌpɔːr.tʃəˈɡiz/","defVi":"(thuộc) Bồ Đào Nha, người Bồ Đào Nha hoặc tiếng Bồ Đào Nha","defEn":"relating to Portugal, its people, or its language","examples":["We enjoyed traditional [portuguese] custard tarts at the bakery. (=Dịch: Chúng tôi đã thưởng thức món bánh trứng nướng truyền thống của Bồ Đào Nha tại tiệm bánh.)","He is studying the [portuguese] language before moving to Lisbon. (=Dịch: Anh ấy đang học tiếng Bồ Đào Nha trước khi chuyển đến Lisbon.)","Many historic buildings in the city reflect ancient [portuguese] architecture. (=Dịch: Nhiều tòa nhà lịch sử trong thành phố phản ánh kiến trúc Bồ Đào Nha cổ kính.)"],"ukAudio":"/ai_services/tts3/?q=portuguese&lang=en-GB&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1iz%2F","usAudio":"/ai_services/tts3/?q=portuguese&lang=en-US&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1iz%2F"},{"id":"lv_5_273","topic":"Nature and Environmental Protection","word":"precise","pos":"(adj)","ipa":"/prɪˈsaɪs/","defVi":"chính xác, rõ ràng","defEn":"exact, accurate, and careful about details","examples":["The scientist recorded the [precise] measurements of the chemical reaction. (=Dịch: Nhà khoa học đã ghi lại các phép đo chính xác của phản ứng hóa học.)","Can you tell me the [precise] location of the hotel? (=Dịch: Bạn có thể cho tôi biết vị trí chính xác của khách sạn không?)","He gave [precise] directions on how to reach the remote village. (=Dịch: Anh ấy đã chỉ đường một cách chính xác để đến ngôi làng hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=precise&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=precise&lang=en-US&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F"},{"id":"lv_5_274","topic":"Nature and Environmental Protection","word":"predator","pos":"(n)","ipa":"/ˈpred.ə.t̬ɚ/","defVi":"động vật ăn thịt, loài săn mồi","defEn":"an animal that hunts, kills, and eats other animals for food","examples":["The lion is an apex [predator] with no natural enemies in its ecosystem. (=Dịch: Sư tử là một loài săn mồi đầu bảng không có kẻ thù tự nhiên trong hệ sinh thái của nó.)","Hawks use their sharp vision to spot small rodents from high above, acting as an effective [predator]. (=Dịch: Chim ưng sử dụng thị lực sắc bén để phát hiện các loài gặm nhấm nhỏ từ trên cao, đóng vai trò như một kẻ săn mồi hiệu quả.)","Removing a top [predator] from an environment can cause prey populations to explode. (=Dịch: Việc loại bỏ một loài săn mồi đỉnh cao khỏi môi trường có thể khiến số lượng con mồi bùng nổ.)"],"ukAudio":"/ai_services/tts3/?q=predator&lang=en-GB&ipa=%2F%CB%88pred.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=predator&lang=en-US&ipa=%2F%CB%88pred.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_5_275","topic":"Nature and Environmental Protection","word":"prehistoric","pos":"(adj)","ipa":"/ˌpri.hɪˈstɔr.ɪk/","defVi":"thuộc về thời tiền sử","defEn":"belonging to the period before written records existed","examples":["Archaeologists discovered several [prehistoric] tools inside the ancient cave. (=Dịch: Các nhà khảo cổ học đã phát hiện một số công cụ thời tiền sử bên trong hang động cổ xưa.)","Many [prehistoric] creatures became extinct long before humans appeared. (=Dịch: Nhiều sinh vật thời tiền sử đã tuyệt chủng từ rất lâu trước khi loài người xuất hiện.)","The museum exhibits remarkable paintings made by [prehistoric] humans. (=Dịch: Bảo tàng trưng bày những bức tranh đáng kinh ngạc do con người thời tiền sử vẽ.)"],"ukAudio":"/ai_services/tts3/?q=prehistoric&lang=en-GB&ipa=%2F%CB%8Cpri.h%C9%AA%CB%88st%C9%94r.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=prehistoric&lang=en-US&ipa=%2F%CB%8Cpri.h%C9%AA%CB%88st%C9%94r.%C9%AAk%2F"},{"id":"lv_5_276","topic":"Nature and Environmental Protection","word":"preserve","pos":"(v)","ipa":"/prɪ.ˈzɝːv/","defVi":"bảo tồn, giữ gìn","defEn":"to keep something in its original state or in good condition","examples":["Efforts are being made to [preserve] ancient monuments for future generations. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm bảo tồn các di tích cổ cho các thế hệ tương lai.)","We must protect rainforests to [preserve] biological diversity. (=Dịch: Chúng ta phải bảo vệ rừng nhiệt đới để bảo tồn sự đa dạng sinh học.)","Adding salt is a traditional method used to [preserve] meat and fish. (=Dịch: Thêm muối là một phương pháp truyền thống được sử dụng để bảo quản thịt và cá.)"],"ukAudio":"/ai_services/tts3/?q=preserve&lang=en-GB&ipa=%2Fpr%C9%AA.%CB%88z%C9%9D%CB%90v%2F","usAudio":"/ai_services/tts3/?q=preserve&lang=en-US&ipa=%2Fpr%C9%AA.%CB%88z%C9%9D%CB%90v%2F"},{"id":"lv_5_277","topic":"Nature and Environmental Protection","word":"prey","pos":"(n)","ipa":"/preɪ/","defVi":"con mồi","defEn":"an animal that is hunted and killed by another animal for food","examples":["The zebra used camouflage and speed to escape from the lion, avoiding becoming easy [prey]. (=Dịch: Ngựa vằn đã sử dụng khả năng ngụy trang và tốc độ để thoát khỏi sư tử, tránh trở thành con mồi dễ dãi.)","Owls hunt small mammals such as mice and voles as their primary [prey]. (=Dịch: Cú săn các loài thú nhỏ như chuột nhắt và chuột đồng làm con mồi chính của chúng.)","In cold winters, food shortages make it harder for carnivores to find sufficient [prey]. (=Dịch: Vào những mùa đông lạnh giá, tình trạng khan hiếm thức ăn khiến các loài ăn thịt khó tìm đủ con mồi hơn.)"],"ukAudio":"/ai_services/tts3/?q=prey&lang=en-GB&ipa=%2Fpre%C9%AA%2F","usAudio":"/ai_services/tts3/?q=prey&lang=en-US&ipa=%2Fpre%C9%AA%2F"},{"id":"lv_5_278","topic":"Nature and Environmental Protection","word":"profound","pos":"(adj)","ipa":"/prəˈfaʊnd/","defVi":"sâu sắc, uyên thâm, sâu rộng","defEn":"having deep insight, or having an extremely great and lasting effect","examples":["The invention of the internet has had a [profound] impact on modern communication. (=Dịch: Phát minh về mạng internet đã có một tác động sâu sắc đến giao tiếp hiện đại.)","The philosopher offered a [profound] insight into the nature of human happiness. (=Dịch: Nhà triết học đã đưa ra một góc nhìn sâu sắc về bản chất của hạnh phúc con người.)","Her mother's passing caused her a sense of [profound] sadness that lasted for months. (=Dịch: Sự ra đi của mẹ cô đã mang lại cho cô một nỗi buồn sâu sắc kéo dài suốt nhiều tháng.)"],"ukAudio":"/ai_services/tts3/?q=profound&lang=en-GB&ipa=%2Fpr%C9%99%CB%88fa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=profound&lang=en-US&ipa=%2Fpr%C9%99%CB%88fa%CA%8And%2F"},{"id":"lv_5_279","topic":"Nature and Environmental Protection","word":"province","pos":"(n)","ipa":"/ˈprɑ.vəns/","defVi":"tỉnh, đơn vị hành chính cấp tỉnh","defEn":"a principal administrative division of a country or territory","examples":["He grew up in a rural [province] in the northern part of the country. (=Dịch: Anh ấy lớn lên ở một tỉnh nông thôn phía bắc đất nước.)","The government allocated extra funding to build schools in that [province]. (=Dịch: Chính phủ đã phân bổ thêm kinh phí để xây dựng trường học tại tỉnh đó.)","Tourism has become the main source of income for this coastal [province]. (=Dịch: Du lịch đã trở thành nguồn thu nhập chính cho tỉnh ven biển này.)"],"ukAudio":"/ai_services/tts3/?q=province&lang=en-GB&ipa=%2F%CB%88pr%C9%91.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=province&lang=en-US&ipa=%2F%CB%88pr%C9%91.v%C9%99ns%2F"},{"id":"lv_5_280","topic":"Nature and Environmental Protection","word":"pulp","pos":"(n)","ipa":"/pʌlp/","defVi":"bột giấy; thịt quả/phần thịt mềm","defEn":"a soft, wet mass of crushed material, especially wood used to make paper or the soft part of fruit","examples":["Wood [pulp] is the primary raw material used in paper manufacturing. (=Dịch: Bột gỗ là nguyên liệu thô chủ yếu được dùng trong sản xuất giấy.)","She prefers orange juice without any [pulp]. (=Dịch: Cô ấy thích nước cam không có tép/thịt quả.)","Recycled paper is soaked in water to turn it back into [pulp]. (=Dịch: Giấy tái chế được ngâm trong nước để biến trở lại thành bột giấy.)"],"ukAudio":"/ai_services/tts3/?q=pulp&lang=en-GB&ipa=%2Fp%CA%8Clp%2F","usAudio":"/ai_services/tts3/?q=pulp&lang=en-US&ipa=%2Fp%CA%8Clp%2F"},{"id":"lv_5_281","topic":"Nature and Environmental Protection","word":"rainbow","pos":"(n)","ipa":"/ˈreɪn.boʊ/","defVi":"cầu vồng","defEn":"a curved band of different colors that appears in the sky when sun shines through rain","examples":["A stunning [rainbow] appeared in the sky right after the rain stopped. (=Dịch: Một chiếc cầu vồng tuyệt đẹp đã xuất hiện trên bầu trời ngay sau khi tạnh mưa.)","Children love drawing a colorful [rainbow] with crayons. (=Dịch: Trẻ em rất thích vẽ cầu vồng rực rỡ sắc màu bằng bút sáp.)","The waterfall created a misty spray that formed a faint [rainbow]. (=Dịch: Thác nước tạo ra một làn sương mù hình thành nên một chiếc cầu vồng mờ ảo.)"],"ukAudio":"/ai_services/tts3/?q=rainbow&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=rainbow&lang=en-US&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F"},{"id":"lv_5_282","topic":"Nature and Environmental Protection","word":"rainforest","pos":"(n)","ipa":"/ˈreɪn.fɔːr.ɪst/","defVi":"rừng mưa nhiệt đới","defEn":"a thick forest in a tropical region with heavy annual rainfall","examples":["The Amazon [rainforest] produces a significant portion of the world's oxygen. (=Dịch: Rừng mưa nhiệt đới Amazon sản xuất một phần đáng kể lượng oxy của thế giới.)","Many rare medicinal plants can only be found in the dense [rainforest]. (=Dịch: Nhiều loại cây dược liệu quý hiếm chỉ có thể được tìm thấy trong rừng mưa nhiệt đới rậm rạp.)","Efforts are being made to protect the tropical [rainforest] from illegal logging. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm bảo vệ rừng mưa nhiệt đới khỏi nạn khai thác gỗ trái phép.)"],"ukAudio":"/ai_services/tts3/?q=rainforest&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.f%C9%94%CB%90r.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=rainforest&lang=en-US&ipa=%2F%CB%88re%C9%AAn.f%C9%94%CB%90r.%C9%AAst%2F"},{"id":"lv_5_283","topic":"Nature and Environmental Protection","word":"rapid","pos":"(adj)","ipa":"/ˈræp.ɪd/","defVi":"nhanh chóng, mau lẹ","defEn":"happening very quickly or moving at great speed","examples":["The country experienced [rapid] economic growth over the last decade. (=Dịch: Đất nước đã trải qua sự tăng trưởng kinh tế nhanh chóng trong thập kỷ qua.)","Scientists are concerned about the [rapid] melting of polar ice caps. (=Dịch: Các nhà khoa học lo ngại về sự tan chảy nhanh chóng của các chỏm băng ở cực.)","She made a [rapid] recovery after receiving the new medication. (=Dịch: Cô ấy đã hồi phục nhanh chóng sau khi dùng loại thuốc mới.)"],"ukAudio":"/ai_services/tts3/?q=rapid&lang=en-GB&ipa=%2F%CB%88r%C3%A6p.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rapid&lang=en-US&ipa=%2F%CB%88r%C3%A6p.%C9%AAd%2F"},{"id":"lv_5_284","topic":"Nature and Environmental Protection","word":"rat","pos":"(n)","ipa":"/ræt/","defVi":"chuột cống, chuột lớn","defEn":"a rodent that resembles a large mouse with a long tail","examples":["The health inspector warned that the dirty basement might attract a [rat]. (=Dịch: Thanh tra y tế đã cảnh báo rằng tầng hầm bẩn thỉu có thể thu hút chuột.)","Scientists used a laboratory [rat] to conduct research on the new medicine. (=Dịch: Các nhà khoa học đã sử dụng chuột thí nghiệm để tiến hành nghiên cứu về loại thuốc mới.)","The old warehouse was infested with more than one giant [rat]. (=Dịch: Nhà kho cũ bị quấy phá bởi nhiều con chuột cống khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=rat&lang=en-GB&ipa=%2Fr%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=rat&lang=en-US&ipa=%2Fr%C3%A6t%2F"},{"id":"lv_5_285","topic":"Nature and Environmental Protection","word":"rattan","pos":"(n)","ipa":"/ræˈtæn/","defVi":"cây mây, mây tre đan","defEn":"the thin, pliable stems of a palm used to make furniture and baskets","examples":["She bought a set of stylish [rattan] chairs for her garden patio. (=Dịch: Cô ấy đã mua một bộ ghế mây rất phong cách cho hiên vườn của mình.)","Local artisans weave durable baskets out of natural [rattan]. (=Dịch: Các nghệ nhân địa phương đan những chiếc giỏ bền chắc từ sợi mây tự nhiên.)","The eco-friendly cafe is decorated with beautiful handmade [rattan] lamps. (=Dịch: Quán cà phê thân thiện với môi trường được trang trí bằng những chiếc đèn mây thủ công tuyệt đẹp.)"],"ukAudio":"/ai_services/tts3/?q=rattan&lang=en-GB&ipa=%2Fr%C3%A6%CB%88t%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=rattan&lang=en-US&ipa=%2Fr%C3%A6%CB%88t%C3%A6n%2F"},{"id":"lv_5_286","topic":"Nature and Environmental Protection","word":"raw","pos":"(adj)","ipa":"/rɔ/","defVi":"sống (chưa nấu chín), thô (chưa qua chế biến)","defEn":"not cooked or not processed into finished goods","examples":["Eating [raw] seafood can sometimes increase the risk of food poisoning. (=Dịch: Ăn hải sản sống đôi khi có thể làm tăng nguy cơ ngộ độc thực phẩm.)","The factory imports [raw] materials such as timber and cotton from abroad. (=Dịch: Nhà máy nhập khẩu các nguyên liệu thô như gỗ và bông từ nước ngoài.)","The researcher analyzed the [raw] data before compiling the final report. (=Dịch: Nhà nghiên cứu đã phân tích dữ liệu thô trước khi biên soạn báo cáo cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=raw&lang=en-GB&ipa=%2Fr%C9%94%2F","usAudio":"/ai_services/tts3/?q=raw&lang=en-US&ipa=%2Fr%C9%94%2F"},{"id":"lv_5_287","topic":"Nature and Environmental Protection","word":"rear","pos":"(v)","ipa":"/rɪr/","defVi":"nuôi dưỡng, chăm sóc, chăn nuôi","defEn":"to care for young animals or children until they are fully grown","examples":["Many local farmers [rear] sheep and cattle for meat and wool. (=Dịch: Nhiều nông dân địa phương nuôi cừu và gia súc để lấy thịt và len.)","It takes great dedication and patience to [rear] children in a busy modern city. (=Dịch: Cần có sự tận tâm và kiên nhẫn to lớn để nuôi dạy con cái trong một thành phố hiện đại bận rộn.)","Both parent birds work tirelessly together to [rear] their chicks until they can fly. (=Dịch: Cả chim bố và chim mẹ đều làm việc không biết mệt mỏi cùng nhau để nuôi nấng những chú chim non cho đến khi chúng biết bay.)"],"ukAudio":"/ai_services/tts3/?q=rear&lang=en-GB&ipa=%2Fr%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=rear&lang=en-US&ipa=%2Fr%C9%AAr%2F"},{"id":"lv_5_288","topic":"Nature and Environmental Protection","word":"recovery","pos":"(n)","ipa":"/rɪˈkʌv.ər.i/","defVi":"sự hồi phục, sự phục hồi","defEn":"the process of returning to normal health, strength, or economic condition","examples":["Doctors were pleased with his steady [recovery] after surgery. (=Dịch: Các bác sĩ hài lòng với sự hồi phục ổn định của anh ấy sau ca phẫu thuật.)","The government launched new policies to support economic [recovery]. (=Dịch: Chính phủ đã đưa ra các chính sách mới nhằm hỗ trợ phục hồi kinh tế.)","The [recovery] of stolen artwork took several years of investigation. (=Dịch: Việc tìm lại các tác phẩm nghệ thuật bị đánh cắp đã mất nhiều năm điều tra.)"],"ukAudio":"/ai_services/tts3/?q=recovery&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%99r.i%2F","usAudio":"/ai_services/tts3/?q=recovery&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%99r.i%2F"},{"id":"lv_5_289","topic":"Nature and Environmental Protection","word":"recycling","pos":"(n)","ipa":"/ˌriːˈsaɪ.klɪŋ/","defVi":"hoạt động tái chế, việc tái chế","defEn":"the process of collecting and converting waste materials into new reusable objects","examples":["Effective [recycling] programs can significantly reduce the amount of industrial waste. (=Dịch: Các chương trình tái chế hiệu quả có thể làm giảm đáng kể lượng rác thải công nghiệp.)","Many schools encourage students to participate in paper and bottle [recycling]. (=Dịch: Nhiều trường học khuyến khích học sinh tham gia tái chế giấy và chai lọ.)","Advancements in [recycling] technology make it easier to process complex electronic waste. (=Dịch: Những tiến bộ trong công nghệ tái chế giúp việc xử lý rác thải điện tử phức tạp trở nên dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=recycling&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88sa%C9%AA.kl%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=recycling&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88sa%C9%AA.kl%C9%AA%C5%8B%2F"},{"id":"lv_5_290","topic":"Nature and Environmental Protection","word":"redstart","pos":"(n)","ipa":"/ˈred.stɑːrt/","defVi":"chim đuôi đỏ","defEn":"a small songbird with a reddish-brown tail","examples":["Birdwatchers were excited to spot a common [redstart] in the garden. (=Dịch: Những người ngắm chim rất hào hứng khi phát hiện một con chim đuôi đỏ thông thường trong vườn.)","The male [redstart] has distinctive bright plumage compared to the female. (=Dịch: Chim đuôi đỏ đực có bộ lông sặc sỡ đặc trưng so với con cái.)","A [redstart] often twitches its tail while searching for insects. (=Dịch: Một con chim đuôi đỏ thường giật giật chiếc đuôi trong khi tìm kiếm côn trùng.)"],"ukAudio":"/ai_services/tts3/?q=redstart&lang=en-GB&ipa=%2F%CB%88red.st%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=redstart&lang=en-US&ipa=%2F%CB%88red.st%C9%91%CB%90rt%2F"},{"id":"lv_5_291","topic":"Nature and Environmental Protection","word":"reforest","pos":"(v)","ipa":"/riː.ˈfɔːr.ɪst/","defVi":"tái trồng rừng, trồng rừng lại","defEn":"to plant new trees in an area where there used to be a forest","examples":["The charity launched a campaign to [reforest] the barren hillsides. (=Dịch: Tổ chức từ thiện đã phát động một chiến dịch tái trồng rừng trên các sườn đồi cằn cỗi.)","Volunteers gathered on weekends to [reforest] land damaged by wildfires. (=Dịch: Các tình nguyện viên tập trung vào cuối tuần để trồng lại rừng trên vùng đất bị tàn phá bởi cháy rừng.)","The government provides financial incentives for farmers who [reforest] unused land. (=Dịch: Chính phủ cung cấp các ưu đãi tài chính cho những người nông dân tái trồng rừng trên đất không sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=reforest&lang=en-GB&ipa=%2Fri%CB%90.%CB%88f%C9%94%CB%90r.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=reforest&lang=en-US&ipa=%2Fri%CB%90.%CB%88f%C9%94%CB%90r.%C9%AAst%2F"},{"id":"lv_5_292","topic":"Nature and Environmental Protection","word":"reforestation","pos":"(n)","ipa":"/ˌriː.fɔːr.əˈsteɪ.ʃən/","defVi":"hoạt động tái trồng rừng, phủ xanh đất trống","defEn":"the act of planting new trees in an area where a forest used to exist","examples":["Large-scale [reforestation] projects can help slow down the rate of global warming. (=Dịch: Các dự án tái trồng rừng quy mô lớn có thể giúp làm chậm tốc độ nóng lên toàn cầu.)","The local community organized a [reforestation] campaign after the devastating wildfire. (=Dịch: Cộng đồng địa phương đã tổ chức một chiến dịch trồng rừng sau vụ cháy rừng tàn khốc.)","Through [reforestation], many endangered animal species have regained their natural habitats. (=Dịch: Thông qua việc tái trồng rừng, nhiều loài động vật có nguy cơ tuyệt chủng đã lấy lại được môi trường sống tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=reforestation&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.f%C9%94%CB%90r.%C9%99%CB%88ste%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reforestation&lang=en-US&ipa=%2F%CB%8Cri%CB%90.f%C9%94%CB%90r.%C9%99%CB%88ste%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_293","topic":"Nature and Environmental Protection","word":"regulate","pos":"(v)","ipa":"/ˈreɡ.jə.leɪt/","defVi":"điều hòa, kiểm soát, quy định","defEn":"to control or maintain the rate, speed, or quality of a process; to control by rules","examples":["The thermostat is used to [regulate] the room temperature. (=Dịch: Bộ điều nhiệt được sử dụng để điều hòa nhiệt độ trong phòng.)","Strict laws are needed to [regulate] the financial market. (=Dịch: Cần có các điều luật nghiêm ngặt để kiểm soát thị trường tài chính.)","Hormones help [regulate] appetite and sleep patterns in the human body. (=Dịch: Nội tiết tố giúp điều hòa cảm giác thèm ăn và giấc ngủ trong cơ thể con người.)"],"ukAudio":"/ai_services/tts3/?q=regulate&lang=en-GB&ipa=%2F%CB%88re%C9%A1.j%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=regulate&lang=en-US&ipa=%2F%CB%88re%C9%A1.j%C9%99.le%C9%AAt%2F"},{"id":"lv_5_294","topic":"Nature and Environmental Protection","word":"relevance","pos":"(n)","ipa":"/ˈrel.ə.vəns/","defVi":"sự liên quan, tính thích đáng","defEn":"the degree to which something is related or useful to what is happening or being discussed","examples":["The essay lost marks because some paragraphs lacked [relevance] to the topic. (=Dịch: Bài luận bị mất điểm vì một số đoạn văn thiếu sự liên quan đến chủ đề.)","Her practical experience has direct [relevance] to this new project. (=Dịch: Kinh nghiệm thực tế của cô ấy có liên quan trực tiếp đến dự án mới này.)","Scholars continue to debate the [relevance] of ancient philosophy today. (=Dịch: Các học giả vẫn tiếp tục tranh luận về tính thích đáng của triết học cổ đại ngày nay.)"],"ukAudio":"/ai_services/tts3/?q=relevance&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=relevance&lang=en-US&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F"},{"id":"lv_5_295","topic":"Nature and Environmental Protection","word":"remarkable","pos":"(adj)","ipa":"/rɪ.ˈmɑːr.kə.bəl/","defVi":"Đáng chú ý, xuất sắc, phi thường","defEn":"Unusual or special and therefore surprising and worth mentioning.","examples":["The young pianist showed [remarkable] talent at an early age. (=Dịch: Nghệ sĩ dương cầm trẻ tuổi đã thể hiện tài năng xuất chúng ngay từ khi còn nhỏ.)","The city made a [remarkable] recovery after the natural disaster. (=Dịch: Thành phố đã phục hồi một cách đáng kinh ngạc sau thảm họa thiên nhiên.)","It is [remarkable] how much progress she made in just two months. (=Dịch: Thật đáng kinh ngạc về sự tiến bộ mà cô ấy đạt được chỉ trong hai tháng.)"],"ukAudio":"/ai_services/tts3/?q=remarkable&lang=en-GB&ipa=%2Fr%C9%AA.%CB%88m%C9%91%CB%90r.k%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=remarkable&lang=en-US&ipa=%2Fr%C9%AA.%CB%88m%C9%91%CB%90r.k%C9%99.b%C9%99l%2F"},{"id":"lv_5_296","topic":"Nature and Environmental Protection","word":"renewable","pos":"(adj)","ipa":"/rɪˈnu.ə.bəl/","defVi":"tái tạo được, có thể tái tạo","defEn":"capable of being naturally replaced or replenished and not depleted by use","examples":["The country is investing heavily in [renewable] energy such as wind and solar power. (=Dịch: Quốc gia này đang đầu tư mạnh mẽ vào năng lượng tái tạo như năng lượng gió và mặt trời.)","Switching to [renewable] resources helps reduce our dependence on fossil fuels. (=Dịch: Chuyển sang các nguồn tài nguyên tái tạo giúp giảm sự phụ thuộc của chúng ta vào nhiên liệu hóa thạch.)","Wood is considered a [renewable] material if forests are managed sustainably. (=Dịch: Gỗ được coi là vật liệu có thể tái tạo nếu các khu rừng được quản lý một cách bền vững.)"],"ukAudio":"/ai_services/tts3/?q=renewable&lang=en-GB&ipa=%2Fr%C9%AA%CB%88nu.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=renewable&lang=en-US&ipa=%2Fr%C9%AA%CB%88nu.%C9%99.b%C9%99l%2F"},{"id":"lv_5_297","topic":"Nature and Environmental Protection","word":"reproduction","pos":"(n)","ipa":"/ˌriː.prəˈdʌk.ʃən/","defVi":"sự sinh sản; sự sao chép, bản sao","defEn":"the process by which animals and plants produce offspring, or a copy of something","examples":["Temperature plays an important role in the [reproduction] of many fish species. (=Dịch: Nhiệt độ đóng vai trò quan trọng trong quá trình sinh sản của nhiều loài cá.)","This painting is not the original artwork but a high-quality [reproduction]. (=Dịch: Bức tranh này không phải là bản gốc mà là một bản sao chép chất lượng cao.)","The museum prohibited the [reproduction] of ancient manuscripts without permission. (=Dịch: Bảo tàng cấm việc sao chép các bản thảo cổ mà không có sự cho phép.)"],"ukAudio":"/ai_services/tts3/?q=reproduction&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.pr%C9%99%CB%88d%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reproduction&lang=en-US&ipa=%2F%CB%8Cri%CB%90.pr%C9%99%CB%88d%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_5_298","topic":"Nature and Environmental Protection","word":"reptile","pos":"(n)","ipa":"/ˈrep.taɪl/","defVi":"loài bò sát","defEn":"a cold-blooded animal with scaly skin that lays eggs, such as a snake or lizard","examples":["A snake is a typical [reptile] that relies on the sun to regulate its body temperature. (=Dịch: Rắn là một loài bò sát điển hình phụ thuộc vào ánh nắng mặt trời để điều hòa thân nhiệt.)","The zoo has an impressive indoor exhibit dedicated to [reptile] species from the rainforest. (=Dịch: Sở thú có một khu trưng bày trong nhà rất ấn tượng dành riêng cho các loài bò sát đến từ rừng nhiệt đới.)","Crocodiles are among the oldest surviving [reptile] groups on the planet. (=Dịch: Cá sấu là một trong những nhóm bò sát cổ xưa nhất còn tồn tại trên hành tinh.)"],"ukAudio":"/ai_services/tts3/?q=reptile&lang=en-GB&ipa=%2F%CB%88rep.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=reptile&lang=en-US&ipa=%2F%CB%88rep.ta%C9%AAl%2F"},{"id":"lv_5_299","topic":"Nature and Environmental Protection","word":"reservoir","pos":"(n)","ipa":"/ˈrɛz.ər.vwɑːr/","defVi":"hồ chứa nước","defEn":"a natural or artificial lake used as a source of water supply","examples":["The city's main [reservoir] is running low due to the prolonged drought. (=Dịch: Hồ chứa nước chính của thành phố đang cạn kiệt do hạn hán kéo dài.)","They built a massive [reservoir] to provide drinking water for local communities. (=Dịch: Họ đã xây dựng một hồ chứa nước lớn để cung cấp nước uống cho các cộng đồng địa phương.)","Water is pumped from the [reservoir] directly to the treatment plant. (=Dịch: Nước được bơm từ hồ chứa trực tiếp đến nhà máy xử lý.)"],"ukAudio":"/ai_services/tts3/?q=reservoir&lang=en-GB&ipa=%2F%CB%88r%C9%9Bz.%C9%99r.vw%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=reservoir&lang=en-US&ipa=%2F%CB%88r%C9%9Bz.%C9%99r.vw%C9%91%CB%90r%2F"},{"id":"lv_5_300","topic":"Nature and Environmental Protection","word":"resilience","pos":"(n)","ipa":"/rɪˈzɪl.jəns/","defVi":"khả năng phục hồi, sự kiên cường","defEn":"the capacity to recover quickly from difficulties or adapt to tough conditions","examples":["The local community demonstrated incredible [resilience] following the catastrophic earthquake. (=Dịch: Cộng đồng địa phương đã thể hiện khả năng phục hồi đáng kinh ngạc sau trận động đất thảm khốc.)","Psychologists study how emotional [resilience] helps individuals manage workplace stress effectively. (=Dịch: Các nhà tâm lý học nghiên cứu cách sự kiên cường về mặt cảm xúc giúp các cá nhân kiểm soát căng thẳng tại nơi làm việc một cách hiệu quả.)","Developing economic [resilience] is essential for nations vulnerable to global market fluctuations. (=Dịch: Xây dựng khả năng phục hồi kinh tế là điều cần thiết đối với các quốc gia dễ bị ảnh hưởng bởi những biến động của thị trường toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=resilience&lang=en-GB&ipa=%2Fr%C9%AA%CB%88z%C9%AAl.j%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=resilience&lang=en-US&ipa=%2Fr%C9%AA%CB%88z%C9%AAl.j%C9%99ns%2F"},{"id":"lv_5_301","topic":"Nature and Environmental Protection","word":"respiratory","pos":"(adj)","ipa":"/ˈres.pər.əˌtɔr.i/","defVi":"thuộc về hệ hô hấp, hô hấp","defEn":"relating to the act or process of breathing","examples":["Air pollution can trigger severe [respiratory] problems in young children and the elderly. (=Dịch: Ô nhiễm không khí có thể gây ra các vấn đề hô hấp nghiêm trọng ở trẻ nhỏ và người cao tuổi.)","The lungs are the most vital organs in the human [respiratory] system. (=Dịch: Phổi là cơ quan quan trọng nhất trong hệ hô hấp của con người.)","He wore a protective mask to prevent contracting any infectious [respiratory] illness. (=Dịch: Anh ấy đã đeo khẩu trang bảo hộ để tránh mắc bất kỳ bệnh hô hấp truyền nhiễm nào.)"],"ukAudio":"/ai_services/tts3/?q=respiratory&lang=en-GB&ipa=%2F%CB%88res.p%C9%99r.%C9%99%CB%8Ct%C9%94r.i%2F","usAudio":"/ai_services/tts3/?q=respiratory&lang=en-US&ipa=%2F%CB%88res.p%C9%99r.%C9%99%CB%8Ct%C9%94r.i%2F"},{"id":"lv_5_302","topic":"Nature and Environmental Protection","word":"restoration","pos":"(n)","ipa":"/ˌrɛs.təˈreɪ.ʃən/","defVi":"sự phục hồi, trùng tu","defEn":"the process of returning something to its former owner, place, or condition","examples":["The historic building underwent an extensive [restoration] last year. (=Dịch: Tòa nhà lịch sử đã trải qua một đợt trùng tu quy mô lớn vào năm ngoái.)","Environmentalists are working on the [restoration] of native wetlands. (=Dịch: Các nhà bảo vệ môi trường đang nỗ lực phục hồi các vùng đất ngập nước bản địa.)","The museum celebrated the successful [restoration] of the ancient painting. (=Dịch: Bảo tàng đã ăn mừng sự phục chế thành công của bức tranh cổ.)"],"ukAudio":"/ai_services/tts3/?q=restoration&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bs.t%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=restoration&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bs.t%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_303","topic":"Nature and Environmental Protection","word":"restore","pos":"(v)","ipa":"/rɪˈstɔr/","defVi":"khôi phục, phục hồi","defEn":"to bring something back to an earlier good condition or position","examples":["The government is trying to [restore] public confidence in the economy. (=Dịch: Chính phủ đang cố gắng khôi phục niềm tin của công chúng vào nền kinh tế.)","Experts worked for months to [restore] the ancient painting. (=Dịch: Các chuyên gia đã làm việc nhiều tháng để phục chế bức tranh cổ.)","A good night's sleep will help [restore] your energy. (=Dịch: Một giấc ngủ ngon sẽ giúp bạn phục hồi năng lượng.)"],"ukAudio":"/ai_services/tts3/?q=restore&lang=en-GB&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F","usAudio":"/ai_services/tts3/?q=restore&lang=en-US&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F"},{"id":"lv_5_304","topic":"Nature and Environmental Protection","word":"ripe","pos":"(adj)","ipa":"/raɪp/","defVi":"chín (trái cây, hoa màu)","defEn":"(of fruit or crops) fully grown and ready to be eaten or harvested","examples":["These bananas are not [ripe] yet, so they taste quite bitter. (=Dịch: Những quả chuối này vẫn chưa chín nên có vị khá chát.)","The sweet aroma of [ripe] peaches filled the entire kitchen. (=Dịch: Mùi thơm ngọt ngào của những quả đào chín lan tỏa khắp căn bếp.)","Farmers wait until the wheat is [ripe] before starting the harvest. (=Dịch: Người nông dân đợi cho đến khi lúa mì chín trước khi bắt đầu thu hoạch.)"],"ukAudio":"/ai_services/tts3/?q=ripe&lang=en-GB&ipa=%2Fra%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=ripe&lang=en-US&ipa=%2Fra%C9%AAp%2F"},{"id":"lv_5_305","topic":"Nature and Environmental Protection","word":"roam","pos":"(v)","ipa":"/roʊm/","defVi":"đi lang thang, đi rông","defEn":"to move about or travel with no clear purpose or direction","examples":["Wild animals [roam] freely in the national park. (=Dịch: Động vật hoang dã tự do đi lại trong công viên quốc gia.)","We spent the afternoon simply wanting to [roam] the streets of the old town. (=Dịch: Chúng tôi dành cả buổi chiều chỉ để đi lang thang trên các con phố của khu phố cổ.)","His mind began to [roam] during the long and boring lecture. (=Dịch: Tâm trí anh ấy bắt đầu lơ đễnh trong suốt bài giảng dài và nhàm chán.)"],"ukAudio":"/ai_services/tts3/?q=roam&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=roam&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_5_306","topic":"Nature and Environmental Protection","word":"rocky","pos":"(adj)","ipa":"/ˈrɑː.ki/","defVi":"nhiều đá, gập ghềnh, bấp bênh","defEn":"consisting of or covered with rocks; difficult and full of problems","examples":["They hiked up a steep and [rocky] path to reach the mountain peak. (=Dịch: Họ đi bộ men theo một con đường dốc và nhiều sỏi đá để lên tới đỉnh núi.)","The ship navigated carefully around the [rocky] coastline. (=Dịch: Con tàu cẩn thận điều hướng quanh bờ biển nhiều đá ngầm.)","The peace negotiations got off to a [rocky] start due to disagreements. (=Dịch: Các cuộc đàm phán hòa bình đã có một khởi đầu gập ghềnh do những bất đồng.)"],"ukAudio":"/ai_services/tts3/?q=rocky&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.ki%2F","usAudio":"/ai_services/tts3/?q=rocky&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.ki%2F"},{"id":"lv_5_307","topic":"Nature and Environmental Protection","word":"roll","pos":"(n)","ipa":"/roʊl/","defVi":"cuộn, ổ bánh mì nhỏ","defEn":"a cylinder formed by winding flexible material, or a small portion of baked bread","examples":["She bought a [roll] of wrapping paper to prepare gifts for the holiday. (=Dịch: Cô ấy đã mua một cuộn giấy gói để chuẩn bị quà cho kỳ nghỉ lễ.)","He ordered a warm buttered [roll] to accompany his bowl of soup. (=Dịch: Anh ấy đã gọi một ổ bánh mì nhỏ phết bơ nóng hổi để ăn kèm với bát súp của mình.)","The worker unpacked a heavy [roll] of carpet to install in the living room. (=Dịch: Người thợ mở một cuộn thảm trải sàn nặng để lắp đặt trong phòng khách.)"],"ukAudio":"/ai_services/tts3/?q=roll&lang=en-GB&ipa=%2Fro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=roll&lang=en-US&ipa=%2Fro%CA%8Al%2F"},{"id":"lv_5_308","topic":"Nature and Environmental Protection","word":"roman","pos":"(adj)","ipa":"/ˈroʊ.mən/","defVi":"(thuộc) La Mã cổ đại","defEn":"relating to ancient Rome, its people, or its empire","examples":["The museum displays many ancient [roman] coins found across Europe. (=Dịch: Bảo tàng trưng bày nhiều đồng tiền La Mã cổ đại được tìm thấy khắp châu Âu.)","Tourists love visiting the ruins of the old [roman] amphitheater. (=Dịch: Khách du lịch rất thích tham quan tàn tích của giảng đường La Mã cổ kính.)","Historians study the rise and fall of the [roman] Empire in great detail. (=Dịch: Các nhà sử học nghiên cứu rất chi tiết về sự hưng thịnh và suy tàn của Đế chế La Mã.)"],"ukAudio":"/ai_services/tts3/?q=roman&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=roman&lang=en-US&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F"},{"id":"lv_5_309","topic":"Nature and Environmental Protection","word":"rood","pos":"(n)","ipa":"/rud/","defVi":"Cây thánh giá lớn; đơn vị đo diện tích đất cũ (khoảng 1/4 mẫu Anh).","defEn":"A crucifix, especially a large one placed above the entrance to the chancel of a medieval church; also an old unit of land area.","examples":["An ancient stone [rood] stood prominently inside the old cathedral. (=Dịch: Một cây thánh giá bằng đá cổ đứng sừng sững bên trong nhà thờ lớn cũ.)","The historic church retains a beautifully carved wooden [rood]. (=Dịch: Ngôi nhà thờ lịch sử vẫn giữ lại một cây thánh giá bằng gỗ được chạm khắc tinh xảo.)","The farmer sold half a [rood] of his family property to pay debts. (=Dịch: Người nông dân đã bán nửa rood đất của gia đình để trả nợ.)"],"ukAudio":"/ai_services/tts3/?q=rood&lang=en-GB&ipa=%2Frud%2F","usAudio":"/ai_services/tts3/?q=rood&lang=en-US&ipa=%2Frud%2F"},{"id":"lv_5_310","topic":"Nature and Environmental Protection","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, ráp, thô ráp, sơ bộ","defEn":"not smooth, level, or polished; not exact or detailed","examples":["His hands were [rough] and calloused from years of manual labor. (=Dịch: Đôi bàn tay anh ấy thô ráp và chai sạn vì nhiều năm lao động chân tay.)","She quickly sketched a [rough] draft of the proposed architecture. (=Dịch: Cô ấy nhanh chóng phác thảo một bản vẽ sơ bộ về công trình được đề xuất.)","The small fishing boat struggled in the [rough] open seas. (=Dịch: Chiếc thuyền đánh cá nhỏ phải vật lộn giữa vùng biển động sóng lớn.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_5_311","topic":"Nature and Environmental Protection","word":"rounded","pos":"(adj)","ipa":"/ˈraʊn.dɪd/","defVi":"tròn trịa, toàn diện","defEn":"curving and smooth; well-balanced and complete","examples":["The river stones had smooth, [rounded] edges shaped by rushing water. (=Dịch: Những viên đá dưới sông có các cạnh nhẵn bóng, tròn trịa do dòng nước chảy siết tạo nên.)","A well-[rounded] education includes both academic study and practical skills. (=Dịch: Một nền giáo dục toàn diện bao gồm cả việc học lý thuyết lẫn các kỹ năng thực tế.)","The modern building features elegant, [rounded] corners on every floor. (=Dịch: Tòa nhà hiện đại có các góc bo tròn thanh lịch ở mọi tầng.)"],"ukAudio":"/ai_services/tts3/?q=rounded&lang=en-GB&ipa=%2F%CB%88ra%CA%8An.d%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rounded&lang=en-US&ipa=%2F%CB%88ra%CA%8An.d%C9%AAd%2F"},{"id":"lv_5_312","topic":"Nature and Environmental Protection","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ər/","defVi":"cao su","defEn":"a tough, elastic substance made from the juice of certain tropical trees or synthetically","examples":["Car tires are primarily manufactured from natural and synthetic [rubber]. (=Dịch: Lốp xe ô tô chủ yếu được sản xuất từ cao su tự nhiên và cao su tổng hợp.)","The boots are made of waterproof [rubber] to keep your feet dry in the rain. (=Dịch: Đôi ủng được làm từ cao su chống thấm nước để giữ cho chân bạn luôn khô ráo trong mưa.)","The soles of these sports shoes provide good traction on slippery [rubber] mats. (=Dịch: Đế của những đôi giày thể thao này tạo độ bám tốt trên các tấm thảm cao su trơn trượt.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%99r%2F"},{"id":"lv_5_313","topic":"Nature and Environmental Protection","word":"ruler","pos":"(n)","ipa":"/ˈruː.lɚ/","defVi":"Người cai trị; cây thước kẻ.","defEn":"A person who governs a country; or a straight strip used to measure distance or draw straight lines.","examples":["The ancient kingdom flourished under the guidance of a wise [ruler]. (=Dịch: Vương quốc cổ đại đã hưng thịnh dưới sự dẫn dắt của một vị quân vương sáng suốt.)","Please use a [ruler] and a sharp pencil to draw straight lines. (=Dịch: Làm ơn hãy dùng một chiếc thước kẻ và một cây bút chì sắc để kẻ các đường thẳng.)","Historians describe him as a cruel [ruler] who showed no mercy to his subjects. (=Dịch: Các nhà sử học miêu tả ông ta là một kẻ cai trị tàn bạo, không hề thương xót thần dân của mình.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F"},{"id":"lv_5_314","topic":"Nature and Environmental Protection","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ, người đi biển","defEn":"people who work as members of the crew of a ship or boat","examples":["The brave [sailors] guided the ship safely through the violent storm. (=Dịch: Những thủy thủ dũng cảm đã điều khiển con tàu vượt qua cơn bão dữ dội một cách an toàn.)","In the past, [sailors] used the positions of the stars to navigate at night. (=Dịch: Trong quá khứ, các thủy thủ đã sử dụng vị trí của các vì sao để định hướng vào ban đêm.)","Many young [sailors] spend months away from their families while at sea. (=Dịch: Nhiều thủy thủ trẻ phải xa gia đình nhiều tháng liền khi đi biển.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_5_315","topic":"Nature and Environmental Protection","word":"salmon","pos":"(n)","ipa":"/ˈsæm.ən/","defVi":"cá hồi","defEn":"a large fish with pinkish flesh that lives in the ocean but swims up rivers to reproduce","examples":["Grilled [salmon] served with vegetables is a very nutritious meal. (=Dịch: Cá hồi nướng ăn kèm với rau củ là một bữa ăn rất bổ dưỡng.)","During the breeding season, wild [salmon] swim upstream against strong currents. (=Dịch: Vào mùa sinh sản, cá hồi hoang dã bơi ngược dòng nước chảy xiết.)","Bears rely heavily on [salmon] as their primary food source in autumn. (=Dịch: Gấu phụ thuộc rất nhiều vào cá hồi như một nguồn thức ăn chính vào mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=salmon&lang=en-GB&ipa=%2F%CB%88s%C3%A6m.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=salmon&lang=en-US&ipa=%2F%CB%88s%C3%A6m.%C9%99n%2F"},{"id":"lv_5_316","topic":"Nature and Environmental Protection","word":"sanctuary","pos":"(n)","ipa":"/ˈsæŋk.tʃuˌɛr.i/","defVi":"khu bảo tồn thiên nhiên; nơi trú ẩn an toàn","defEn":"a protected area where animals or birds can live safely","examples":["The island was declared a wildlife [sanctuary] to protect endangered sea turtles. (=Dịch: Hòn đảo đã được công nhận là một khu bảo tồn động vật hoang dã để bảo vệ loài rùa biển có nguy cơ tuyệt chủng.)","Injured birds are nursed back to health at this local [sanctuary]. (=Dịch: Những con chim bị thương được chăm sóc hồi phục sức khỏe tại khu bảo tồn địa phương này.)","The library provided a quiet [sanctuary] away from the noisy city streets. (=Dịch: Thư viện mang lại một nơi trú ẩn yên tĩnh tách biệt khỏi những con phố ồn ào của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=sanctuary&lang=en-GB&ipa=%2F%CB%88s%C3%A6%C5%8Bk.t%CA%83u%CB%8C%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=sanctuary&lang=en-US&ipa=%2F%CB%88s%C3%A6%C5%8Bk.t%CA%83u%CB%8C%C9%9Br.i%2F"},{"id":"lv_5_317","topic":"Nature and Environmental Protection","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance consisting of very small grains of rock found on beaches and in deserts","examples":["The children enjoyed building tall castles in the soft [sand]. (=Dịch: Bọn trẻ rất thích xây những tòa lâu đài cao trên bãi cát mềm.)","Strong winds blew fine desert [sand] directly across the highway. (=Dịch: Gió mạnh đã thổi cát mịn từ sa mạc bay ngang qua đường cao tốc.)","Walking barefoot on the warm [sand] helps you relax your mind. (=Dịch: Đi chân trần trên cát ấm giúp bạn thư giãn tâm trí.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_5_318","topic":"Nature and Environmental Protection","word":"scan","pos":"(v)","ipa":"/skæn/","defVi":"đọc lướt tìm thông tin, quét (bằng máy móc)","defEn":"to look through text quickly to find specific information, or to examine something with a machine","examples":["You should [scan] the text to find the answers to the questions. (=Dịch: Bạn nên đọc lướt văn bản để tìm câu trả lời cho các câu hỏi.)","The doctor used an ultrasound machine to [scan] the patient's abdomen. (=Dịch: Bác sĩ đã dùng máy siêu âm để quét vùng bụng của bệnh nhân.)","Security officers [scan] all luggage before passengers board the plane. (=Dịch: Nhân viên an ninh quét toàn bộ hành lý trước khi hành khách lên máy bay.)"],"ukAudio":"/ai_services/tts3/?q=scan&lang=en-GB&ipa=%2Fsk%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=scan&lang=en-US&ipa=%2Fsk%C3%A6n%2F"},{"id":"lv_5_319","topic":"Nature and Environmental Protection","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"(thuộc) khoa học, mang tính khoa học","defEn":"relating to science, or using the organized methods and principles of science","examples":["Researchers need solid [scientific] evidence before publishing their results. (=Dịch: Các nhà nghiên cứu cần có bằng chứng khoa học vững chắc trước khi công bố kết quả của họ.)","The discovery of penicillin was a major [scientific] breakthrough in medicine. (=Dịch: Việc phát hiện ra penicillin là một bước đột phá khoa học lớn trong y học.)","We should apply a strict [scientific] approach to solving environmental problems. (=Dịch: Chúng ta nên áp dụng một phương pháp khoa học nghiêm ngặt để giải quyết các vấn đề môi trường.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_5_320","topic":"Nature and Environmental Protection","word":"seabed","pos":"(n)","ipa":"/ˈsiː.bed/","defVi":"đáy biển","defEn":"the solid ground at the bottom of the ocean or sea","examples":["Divers explored the [seabed] in search of ancient shipwrecks. (=Dịch: Các thợ lặn đã khám phá đáy biển để tìm kiếm những xác tàu đắm cổ xưa.)","The pipeline lies deep beneath the [seabed] to prevent damage. (=Dịch: Đường ống nằm sâu dưới đáy biển để tránh hư hỏng.)","Many unique marine species live on the rocky [seabed]. (=Dịch: Nhiều loài sinh vật biển độc đáo sống trên đáy biển đầy đá.)"],"ukAudio":"/ai_services/tts3/?q=seabed&lang=en-GB&ipa=%2F%CB%88si%CB%90.bed%2F","usAudio":"/ai_services/tts3/?q=seabed&lang=en-US&ipa=%2F%CB%88si%CB%90.bed%2F"},{"id":"lv_5_321","topic":"Nature and Environmental Protection","word":"seafood","pos":"(n)","ipa":"/ˈsiː.fuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, such as fish and shellfish","examples":["The coastal restaurant is famous for serving fresh [seafood]. (=Dịch: Nhà hàng ven biển nổi tiếng với việc phục vụ hải sản tươi sống.)","Overfishing poses a serious threat to global [seafood] supplies. (=Dịch: Đánh bắt quá mức đặt ra mối đe dọa nghiêm trọng đối với nguồn cung hải sản toàn cầu.)","Some people are allergic to different varieties of [seafood]. (=Dịch: Một số người bị dị ứng với các loại hải sản khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F"},{"id":"lv_5_322","topic":"Nature and Environmental Protection","word":"seasonally","pos":"(adv)","ipa":"/ˈsiː.zən.ə.li/","defVi":"theo mùa, theo thời vụ","defEn":"in a way that relates to, depends on, or varies with a particular season","examples":["Prices of fresh fruits fluctuate [seasonally] depending on harvests. (=Dịch: Giá trái cây tươi biến động theo mùa tùy thuộc vào các vụ thu hoạch.)","Many birds migrate [seasonally] to avoid harsh winter climates. (=Dịch: Nhiều loài chim di cư theo mùa để tránh thời tiết mùa đông khắc nghiệt.)","The hotel only hires [seasonally] during the peak summer period. (=Dịch: Khách sạn chỉ tuyển dụng nhân viên thời vụ trong suốt đợt cao điểm mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=seasonally&lang=en-GB&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=seasonally&lang=en-US&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99.li%2F"},{"id":"lv_5_323","topic":"Nature and Environmental Protection","word":"segment","pos":"(n)","ipa":"/ˈsɛɡ.mənt/","defVi":"phân đoạn, mảng, phần","defEn":"one of the distinct parts into which something is divided or can be separated","examples":["The final [segment] of the documentary focuses on wildlife conservation efforts. (=Dịch: Phần cuối của bộ phim tài liệu tập trung vào các nỗ lực bảo tồn động vật hoang dã.)","This technology firm dominates a large [segment] of the domestic smartphone market. (=Dịch: Công ty công nghệ này thống trị một phân khúc lớn của thị trường điện thoại thông minh nội địa.)","She carefully peeled an orange and shared each juicy [segment] with her child. (=Dịch: Cô ấy cẩn thận bóc một quả cam và chia từng múi mọng nước cho con mình.)"],"ukAudio":"/ai_services/tts3/?q=segment&lang=en-GB&ipa=%2F%CB%88s%C9%9B%C9%A1.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=segment&lang=en-US&ipa=%2F%CB%88s%C9%9B%C9%A1.m%C9%99nt%2F"},{"id":"lv_5_324","topic":"Nature and Environmental Protection","word":"sensor","pos":"(n)","ipa":"/ˈsen.sər/","defVi":"cảm biến, thiết bị cảm ứng","defEn":"a device that discovers and reacts to changes in light, heat, or movement","examples":["The automatic doors open when a motion [sensor] detects someone approaching. (=Dịch: Cửa tự động mở ra khi cảm biến chuyển động phát hiện có người đang tiến lại gần.)","The smoke [sensor] triggered the fire alarm in the building. (=Dịch: Cảm biến khói đã kích hoạt chuông báo cháy trong tòa nhà.)","Modern smartphones use a light [sensor] to adjust screen brightness automatically. (=Dịch: Điện thoại thông minh hiện đại sử dụng cảm biến ánh sáng để tự động điều chỉnh độ sáng màn hình.)"],"ukAudio":"/ai_services/tts3/?q=sensor&lang=en-GB&ipa=%2F%CB%88sen.s%C9%99r%2F","usAudio":"/ai_services/tts3/?q=sensor&lang=en-US&ipa=%2F%CB%88sen.s%C9%99r%2F"},{"id":"lv_5_325","topic":"Nature and Environmental Protection","word":"seriously","pos":"(adv)","ipa":"/ˈsɪr.i.əs.li/","defVi":"nghiêm túc, trầm trọng, nghiêm trọng","defEn":"in a severe manner, or in a way that is not joking","examples":["The driver was [seriously] injured in the car accident. (=Dịch: Người tài xế đã bị thương nặng trong vụ tai nạn xe hơi.)","You should take your studies more [seriously] if you want to pass. (=Dịch: Bạn nên nghiêm túc hơn với việc học nếu muốn thi đỗ.)","Are you [seriously] thinking about quitting your job? (=Dịch: Có thật sự là bạn đang nghĩ đến việc nghỉ việc không?)"],"ukAudio":"/ai_services/tts3/?q=seriously&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=seriously&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F"},{"id":"lv_5_326","topic":"Nature and Environmental Protection","word":"settlement","pos":"(n)","ipa":"/ˈset̬.əl.mənt/","defVi":"sự dàn xếp, thỏa thuận; khu định cư","defEn":"an official agreement that finishes an argument, or a place where people live","examples":["The union reached a wage [settlement] with the company management. (=Dịch: Công đoàn đã đạt được thỏa thuận tiền lương với ban quản lý công ty.)","Archaeologists discovered an ancient [settlement] near the riverbank. (=Dịch: Các nhà khảo cổ học đã phát hiện một khu định cư cổ gần bờ sông.)","The dispute was resolved through an out-of-court [settlement]. (=Dịch: Tranh chấp đã được giải quyết thông qua thỏa thuận ngoài tòa án.)"],"ukAudio":"/ai_services/tts3/?q=settlement&lang=en-GB&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=settlement&lang=en-US&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F"},{"id":"lv_5_327","topic":"Nature and Environmental Protection","word":"severe","pos":"(adj)","ipa":"/sɪˈvɪr/","defVi":"nghiêm trọng, khốc liệt, dữ dội","defEn":"causing very great pain, difficulty, or damage; extremely bad or serious","examples":["The region suffered from a [severe] drought that lasted for months. (=Dịch: Khu vực này đã phải hứng chịu một đợt hạn hán nghiêm trọng kéo dài nhiều tháng.)","He was rushed to the hospital with [severe] chest pains. (=Dịch: Anh ấy đã được đưa gấp tới bệnh viện vì những cơn đau ngực dữ dội.)","The storm caused [severe] damage to coastal buildings and infrastructure. (=Dịch: Cơn bão đã gây ra thiệt hại nghiêm trọng cho các công trình và cơ sở hạ tầng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=severe&lang=en-GB&ipa=%2Fs%C9%AA%CB%88v%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=severe&lang=en-US&ipa=%2Fs%C9%AA%CB%88v%C9%AAr%2F"},{"id":"lv_5_328","topic":"Nature and Environmental Protection","word":"shark","pos":"(n)","ipa":"/ʃɑːrk/","defVi":"cá mập","defEn":"a large fish with sharp teeth and a fin on its back that lives in the ocean","examples":["The great white [shark] is one of the most feared predators in the ocean. (=Dịch: Cá mập trắng lớn là một trong những kẻ săn mồi đáng sợ nhất ở đại dương.)","Swimmers were warned to leave the water after a [shark] was spotted near the shore. (=Dịch: Những người đi bơi được cảnh báo rời khỏi mặt nước sau khi một con cá mập bị phát hiện gần bờ.)","Many species of [shark] are currently threatened by overfishing. (=Dịch: Nhiều loài cá mập hiện đang bị đe dọa bởi nạn đánh bắt quá mức.)"],"ukAudio":"/ai_services/tts3/?q=shark&lang=en-GB&ipa=%2F%CA%83%C9%91%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=shark&lang=en-US&ipa=%2F%CA%83%C9%91%CB%90rk%2F"},{"id":"lv_5_329","topic":"Nature and Environmental Protection","word":"shell","pos":"(n)","ipa":"/ʃel/","defVi":"vỏ (ốc, sò, trứng, hạt)","defEn":"the hard outer covering of an animal, an egg, or a nut","examples":["The crab hides inside its hard [shell] to protect itself from predators. (=Dịch: Con cua ẩn nấp bên trong lớp vỏ cứng của mình để tự bảo vệ khỏi những kẻ săn mồi.)","Children love collecting colorful [shell] pieces along the seashore. (=Dịch: Trẻ em rất thích nhặt những mảnh vỏ sò nhiều màu sắc dọc theo bờ biển.)","Be careful not to drop bits of egg [shell] into the mixing bowl. (=Dịch: Hãy cẩn thận đừng để các mảnh vỏ trứng rơi vào tô trộn.)"],"ukAudio":"/ai_services/tts3/?q=shell&lang=en-GB&ipa=%2F%CA%83el%2F","usAudio":"/ai_services/tts3/?q=shell&lang=en-US&ipa=%2F%CA%83el%2F"},{"id":"lv_5_330","topic":"Nature and Environmental Protection","word":"shipping","pos":"(n)","ipa":"/ˈʃɪp.ɪŋ/","defVi":"việc vận chuyển hàng hóa, ngành hàng hải","defEn":"the activity of transporting goods by sea or other transport methods","examples":["The website offers free [shipping] on orders over fifty dollars. (=Dịch: Trang web miễn phí vận chuyển cho các đơn hàng trên năm mươi đô la.)","International [shipping] may take up to three weeks due to customs. (=Dịch: Vận chuyển quốc tế có thể mất tới ba tuần do thủ tục hải quan.)","The country relies heavily on maritime [shipping] for its exports. (=Dịch: Quốc gia này phụ thuộc rất nhiều vào ngành vận tải biển đối với hàng xuất khẩu.)"],"ukAudio":"/ai_services/tts3/?q=shipping&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=shipping&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F"},{"id":"lv_5_331","topic":"Nature and Environmental Protection","word":"shipwreck","pos":"(n)","ipa":"/ˈʃɪp.rek/","defVi":"vụ đắm tàu; xác tàu đắm","defEn":"the destruction of a ship at sea by sinking or breaking up, or the remains of a destroyed ship","examples":["Archaeologists discovered an ancient [shipwreck] off the coast of Greece. (=Dịch: Các nhà khảo cổ học đã phát hiện ra một xác tàu đắm cổ ngoài khơi Hy Lạp.)","Only three sailors survived the tragic [shipwreck]. (=Dịch: Chỉ có ba thủy thủ sống sót sau vụ đắm tàu bi thảm.)","Coral now covers the rusted metal of the old [shipwreck]. (=Dịch: San hô hiện bao phủ phần kim loại rỉ sét của xác tàu đắm cũ.)"],"ukAudio":"/ai_services/tts3/?q=shipwreck&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.rek%2F","usAudio":"/ai_services/tts3/?q=shipwreck&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.rek%2F"},{"id":"lv_5_332","topic":"Nature and Environmental Protection","word":"shore","pos":"(n)","ipa":"/ʃɔːr/","defVi":"bờ (biển, hồ lớn)","defEn":"the land along the edge of a sea, lake, or wide river","examples":["We walked along the sandy [shore] collecting shells at sunset. (=Dịch: Chúng tôi đi dạo dọc theo bờ biển đầy cát để nhặt vỏ sò lúc hoàng hôn.)","The fishing boat safely returned to the [shore] before the storm hit. (=Dịch: Chiếc thuyền đánh cá đã an toàn trở về bờ trước khi cơn bão ập đến.)","Waves were gently crashing against the rocky [shore]. (=Dịch: Những con sóng vỗ nhẹ vào bờ đá.)"],"ukAudio":"/ai_services/tts3/?q=shore&lang=en-GB&ipa=%2F%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=shore&lang=en-US&ipa=%2F%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_333","topic":"Nature and Environmental Protection","word":"sighting","pos":"(n)","ipa":"/ˈsaɪ.t̬ɪŋ/","defVi":"sự trông thấy, sự phát hiện (vật hiếm hoặc lạ)","defEn":"an occasion on which someone sees something rare, unusual, or elusive","examples":["The rare bird [sighting] attracted hundreds of birdwatchers to the nature reserve. (=Dịch: Sự phát hiện loài chim quý hiếm đã thu hút hàng trăm người ngắm chim đến khu bảo tồn thiên nhiên.)","There has been another [sighting] of a leopard near the rural village. (=Dịch: Lại có thêm một lần người ta nhìn thấy báo đốm xuất hiện gần ngôi làng nông thôn.)","Scientists confirmed the first official [sighting] of the deep-sea squid in these waters. (=Dịch: Các nhà khoa học đã xác nhận lần đầu tiên chính thức nhìn thấy loài mực biển sâu ở vùng biển này.)"],"ukAudio":"/ai_services/tts3/?q=sighting&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sighting&lang=en-US&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_5_334","topic":"Nature and Environmental Protection","word":"silt","pos":"(n)","ipa":"/sɪlt/","defVi":"phù sa, bùn cát mịn","defEn":"fine sand, clay, or other material carried by running water and deposited as a sediment","examples":["The river mouth was blocked by a large accumulation of [silt]. (=Dịch: Cửa sông đã bị tắc nghẽn bởi một lượng lớn phù sa tích tụ.)","Floods leave behind rich [silt] that makes the farmland fertile. (=Dịch: Lũ lụt để lại lớp phù sa màu mỡ giúp đất canh tác tươi tốt.)","The harbor needs regular dredging to clear out the [silt]. (=Dịch: Cảng cần được nạo vét thường xuyên để dọn sạch bùn cát.)"],"ukAudio":"/ai_services/tts3/?q=silt&lang=en-GB&ipa=%2Fs%C9%AAlt%2F","usAudio":"/ai_services/tts3/?q=silt&lang=en-US&ipa=%2Fs%C9%AAlt%2F"},{"id":"lv_5_335","topic":"Nature and Environmental Protection","word":"sixteen","pos":"(n)","ipa":"/ˌsɪks.ˈtin/","defVi":"Số mười sáu","defEn":"The number equivalent to the sum of ten and six; 16.","examples":["A group of [sixteen] students participated in the science competition. (=Dịch: Một nhóm gồm mười sáu học sinh đã tham gia cuộc thi khoa học.)","She will celebrate her [sixteen]th birthday next week. (=Dịch: Cô ấy sẽ tổ chức sinh nhật lần thứ mười sáu vào tuần tới.)","The recipe requires [sixteen] ounces of fresh milk. (=Dịch: Công thức nấu ăn này yêu cầu mười sáu ounce sữa tươi.)"],"ukAudio":"/ai_services/tts3/?q=sixteen&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAks.%CB%88tin%2F","usAudio":"/ai_services/tts3/?q=sixteen&lang=en-US&ipa=%2F%CB%8Cs%C9%AAks.%CB%88tin%2F"},{"id":"lv_5_336","topic":"Nature and Environmental Protection","word":"sleepy","pos":"(adj)","ipa":"/ˈsliː.pi/","defVi":"buồn ngủ, ngái ngủ; (nơi chốn) yên tĩnh, vắng lặng","defEn":"feeling tired and ready to go to sleep; quiet and not active","examples":["I always feel warm and [sleepy] after a large meal. (=Dịch: Tôi luôn cảm thấy ấm áp và buồn ngủ sau một bữa ăn no.)","They decided to spend their holiday in a [sleepy] fishing village. (=Dịch: Họ quyết định dành kỳ nghỉ của mình tại một ngôi làng chài thanh bình, yên ả.)","The baby rubbed her [sleepy] eyes and began to yawn. (=Dịch: Đứa bé dụi đôi mắt ngái ngủ và bắt đầu ngáp.)"],"ukAudio":"/ai_services/tts3/?q=sleepy&lang=en-GB&ipa=%2F%CB%88sli%CB%90.pi%2F","usAudio":"/ai_services/tts3/?q=sleepy&lang=en-US&ipa=%2F%CB%88sli%CB%90.pi%2F"},{"id":"lv_5_337","topic":"Nature and Environmental Protection","word":"slope","pos":"(n)","ipa":"/sloʊp/","defVi":"dốc, sườn dốc","defEn":"a surface that lies at an angle to the horizontal so that some points on it are higher than others","examples":["Skiers enjoyed racing down the snowy [slope]. (=Dịch: Những người trượt tuyết thích thú lao xuống sườn dốc phủ đầy tuyết.)","The house was built on a steep [slope] overlooking the valley. (=Dịch: Ngôi nhà được xây dựng trên một sườn dốc đứng nhìn ra thung lũng.)","Heavy rain caused soil to slide down the mountain [slope]. (=Dịch: Mưa lớn khiến đất sạt lở xuống sườn núi.)"],"ukAudio":"/ai_services/tts3/?q=slope&lang=en-GB&ipa=%2Fslo%CA%8Ap%2F","usAudio":"/ai_services/tts3/?q=slope&lang=en-US&ipa=%2Fslo%CA%8Ap%2F"},{"id":"lv_5_338","topic":"Nature and Environmental Protection","word":"smoothly","pos":"(adv)","ipa":"/ˈsmuːð.li/","defVi":"một cách suôn sẻ, êm ả, trôi chảy","defEn":"without problems, interruptions, or sudden changes","examples":["The transition to the new system went very [smoothly]. (=Dịch: Quá trình chuyển đổi sang hệ thống mới diễn ra rất suôn sẻ.)","The ship sailed [smoothly] across the calm sea. (=Dịch: Con tàu lướt êm ả trên mặt biển tĩnh lặng.)","The meeting ran [smoothly] and finished ahead of schedule. (=Dịch: Cuộc họp diễn ra thuận lợi và kết thúc sớm hơn dự kiến.)"],"ukAudio":"/ai_services/tts3/?q=smoothly&lang=en-GB&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F","usAudio":"/ai_services/tts3/?q=smoothly&lang=en-US&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F"},{"id":"lv_5_339","topic":"Nature and Environmental Protection","word":"sourced","pos":"(adj)","ipa":"/sɔːrst/","defVi":"có nguồn gốc từ, được lấy từ (nguồn cụ thể)","defEn":"obtained or supplied from a particular place, provider, or method","examples":["The restaurant is proud of using only locally [sourced] ingredients in its dishes. (=Dịch: Nhà hàng tự hào về việc chỉ sử dụng các nguyên liệu có nguồn gốc địa phương trong các món ăn của mình.)","Ethically [sourced] coffee has become increasingly popular among conscious consumers. (=Dịch: Cà phê có nguồn gốc hợp đạo đức ngày càng trở nên phổ biến đối với những người tiêu dùng có ý thức.)","All timber used in the building was sustainably [sourced] from managed forests. (=Dịch: Tất cả gỗ được sử dụng trong tòa nhà đều được lấy từ nguồn rừng được quản lý bền vững.)"],"ukAudio":"/ai_services/tts3/?q=sourced&lang=en-GB&ipa=%2Fs%C9%94%CB%90rst%2F","usAudio":"/ai_services/tts3/?q=sourced&lang=en-US&ipa=%2Fs%C9%94%CB%90rst%2F"},{"id":"lv_5_340","topic":"Nature and Environmental Protection","word":"southern","pos":"(adj)","ipa":"/ˈsʌð.ɚn/","defVi":"(thuộc) phương nam, ở phía nam","defEn":"located in, coming from, or characteristic of the south","examples":["Many birds migrate to the [southern] regions during the winter. (=Dịch: Nhiều loài chim di cư đến các vùng phía nam vào mùa đông.)","We spent two weeks traveling along the [southern] coast of Italy. (=Dịch: Chúng tôi đã dành hai tuần du lịch dọc theo bờ biển phía nam nước Ý.)","She speaks with a distinct [southern] accent. (=Dịch: Cô ấy nói bằng chất giọng miền nam rất đặc trưng.)"],"ukAudio":"/ai_services/tts3/?q=southern&lang=en-GB&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%9An%2F","usAudio":"/ai_services/tts3/?q=southern&lang=en-US&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%9An%2F"},{"id":"lv_5_341","topic":"Nature and Environmental Protection","word":"spear","pos":"(n)","ipa":"/spɪr/","defVi":"ngọn giáo, cây thương","defEn":"a weapon with a long shaft and a pointed tip, used for thrusting or throwing","examples":["Ancient hunters used a sharpened [spear] to catch large animals. (=Dịch: Những người thợ săn cổ đại đã sử dụng một ngọn giáo sắc nhọn để bắt các loài thú lớn.)","The museum displays an iron [spear] dating back to the Bronze Age. (=Dịch: Bảo tàng trưng bày một ngọn giáo sắt có từ thời kỳ đồ đồng.)","He threw the [spear] with great precision during the athletics competition. (=Dịch: Anh ấy đã ném ngọn giáo với độ chính xác cao trong cuộc thi điền kinh.)"],"ukAudio":"/ai_services/tts3/?q=spear&lang=en-GB&ipa=%2Fsp%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=spear&lang=en-US&ipa=%2Fsp%C9%AAr%2F"},{"id":"lv_5_342","topic":"Nature and Environmental Protection","word":"specimen","pos":"(n)","ipa":"/ˈspes.ə.mən/","defVi":"mẫu vật, mẫu thử","defEn":"a single example of something, especially an animal or plant, collected for scientific study","examples":["The museum displays a well-preserved [specimen] of a prehistoric bird. (=Dịch: Bảo tàng trưng bày một mẫu vật được bảo quản tốt của một loài chim tiền sử.)","The doctor asked the patient to provide a urine [specimen] for analysis. (=Dịch: Bác sĩ đã yêu cầu bệnh nhân cung cấp một mẫu nước tiểu để phân tích.)","Botanists collected a rare flower [specimen] during their rainforest expedition. (=Dịch: Các nhà thực vật học đã thu thập một mẫu hoa hiếm trong chuyến thám hiểm rừng nhiệt đới của họ.)"],"ukAudio":"/ai_services/tts3/?q=specimen&lang=en-GB&ipa=%2F%CB%88spes.%C9%99.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=specimen&lang=en-US&ipa=%2F%CB%88spes.%C9%99.m%C9%99n%2F"},{"id":"lv_5_343","topic":"Nature and Environmental Protection","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị (có nguồn gốc thực vật)","defEn":"a substance made from plants used to flavor food, such as cinnamon or pepper","examples":["Cinnamon is a fragrant [spice] commonly added to warm autumn drinks. (=Dịch: Quế là một loại gia vị thơm thường được thêm vào các loại đồ uống ấm áp mùa thu.)","Indian cuisine is celebrated worldwide for its rich blend of each traditional [spice]. (=Dịch: Ẩm thực Ấn Độ nổi tiếng trên toàn thế giới nhờ sự kết hợp phong phú của từng loại gia vị truyền thống.)","Adding fresh herbs and [spice] can elevate a simple vegetable soup. (=Dịch: Thêm thảo mộc tươi và gia vị có thể nâng tầm một món súp rau củ đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_5_344","topic":"Nature and Environmental Protection","word":"spirit","pos":"(n)","ipa":"/ˈspɪr.ɪt/","defVi":"tinh thần, tâm hồn, linh hồn","defEn":"the attitude, mood, or general character of a person or group; also the non-physical part of a person","examples":["Despite the difficulties, the team showed great fighting [spirit]. (=Dịch: Bất chấp những khó khăn, toàn đội đã thể hiện tinh thần thi đấu tuyệt vời.)","Volunteers worked together in a true [spirit] of cooperation. (=Dịch: Các tình nguyện viên đã cùng nhau làm việc trên tinh thần hợp tác thực sự.)","The festival captured the vibrant cultural [spirit] of the city. (=Dịch: Lễ hội đã thể hiện được nét tinh thần văn hóa sôi động của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=spirit&lang=en-GB&ipa=%2F%CB%88sp%C9%AAr.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=spirit&lang=en-US&ipa=%2F%CB%88sp%C9%AAr.%C9%AAt%2F"},{"id":"lv_5_345","topic":"Nature and Environmental Protection","word":"splash","pos":"(n)","ipa":"/splæʃ/","defVi":"tiếng nước bắn; giọt nước bắn, tia nước","defEn":"the sound made by something hitting liquid, or a small amount of liquid that falls on something","examples":["We heard a loud [splash] as the boy jumped into the swimming pool. (=Dịch: Chúng tôi nghe thấy một tiếng tõm lớn khi cậu bé nhảy xuống hồ bơi.)","A [splash] of mud stained her clean white trousers. (=Dịch: Một vệt bùn bắn đã làm bẩn chiếc quần trắng sạch sẽ của cô ấy.)","He added a [splash] of milk to his morning coffee. (=Dịch: Anh ấy thêm một chút sữa vào tách cà phê buổi sáng của mình.)"],"ukAudio":"/ai_services/tts3/?q=splash&lang=en-GB&ipa=%2Fspl%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=splash&lang=en-US&ipa=%2Fspl%C3%A6%CA%83%2F"},{"id":"lv_5_346","topic":"Nature and Environmental Protection","word":"split","pos":"(v)","ipa":"/splɪt/","defVi":"chia nhỏ, tách ra, chẻ ra","defEn":"to divide or break into parts, especially along a line","examples":["The teacher decided to [split] the class into small study groups. (=Dịch: Giáo viên quyết định chia lớp thành các nhóm học tập nhỏ.)","The heavy branch began to [split] under the weight of the snow. (=Dịch: Cành cây nặng trĩu bắt đầu nứt toác dưới sức nặng của tuyết.)","We agreed to [split] the restaurant bill equally among all four of us. (=Dịch: Chúng tôi đồng ý chia đều hóa đơn nhà hàng cho cả bốn người.)"],"ukAudio":"/ai_services/tts3/?q=split&lang=en-GB&ipa=%2Fspl%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=split&lang=en-US&ipa=%2Fspl%C9%AAt%2F"},{"id":"lv_5_347","topic":"Nature and Environmental Protection","word":"squirrel","pos":"(n)","ipa":"/ˈskwɜːr.əl/","defVi":"con sóc","defEn":"a small animal with a bushy tail that climbs trees and eats nuts","examples":["A gray [squirrel] buried acorns beneath the oak tree for winter. (=Dịch: Một con sóc xám đã chôn những quả sồi dưới gốc cây sồi để chuẩn bị cho mùa đông.)","We watched a tiny [squirrel] leap effortlessly between the high branches. (=Dịch: Chúng tôi quan sát một chú sóc nhỏ nhảy thoăn thoắt giữa các cành cây cao.)","The curious [squirrel] approached our park bench in search of food. (=Dịch: Chú sóc tò mò tiến lại gần băng ghế công viên của chúng tôi để tìm kiếm thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=squirrel&lang=en-GB&ipa=%2F%CB%88skw%C9%9C%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=squirrel&lang=en-US&ipa=%2F%CB%88skw%C9%9C%CB%90r.%C9%99l%2F"},{"id":"lv_5_348","topic":"Nature and Environmental Protection","word":"stability","pos":"(n)","ipa":"/stəˈbɪl.ə.t̬i/","defVi":"sự ổn định, tính bền vững","defEn":"the state of being steady and not likely to change or fail","examples":["Political [stability] is crucial for encouraging foreign investment. (=Dịch: Sự ổn định chính trị là yếu tố then chốt để khuyến khích đầu tư nước ngoài.)","The doctor confirmed that the patient's condition had reached [stability]. (=Dịch: Bác sĩ xác nhận rằng tình trạng của bệnh nhân đã đạt mức ổn định.)","This exercise helps improve core strength and overall body [stability]. (=Dịch: Bài tập này giúp tăng cường sức mạnh cốt lõi và sự ổn định tổng thể của cơ thể.)"],"ukAudio":"/ai_services/tts3/?q=stability&lang=en-GB&ipa=%2Fst%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=stability&lang=en-US&ipa=%2Fst%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_5_349","topic":"Nature and Environmental Protection","word":"stable","pos":"(adj)","ipa":"/ˈsteɪ.bəl/","defVi":"ổn định, vững chắc","defEn":"not likely to change, fail, or move suddenly; firmly fixed","examples":["The patient remains in a [stable] condition following the emergency surgery. (=Dịch: Bệnh nhân vẫn duy trì tình trạng ổn định sau ca phẫu thuật khẩn cấp.)","A [stable] economy is essential for attracting long-term foreign direct investment. (=Dịch: Một nền kinh tế ổn định là điều cốt yếu để thu hút vốn đầu tư trực tiếp nước ngoài dài hạn.)","Make sure the ladder is placed on a [stable] surface before climbing up. (=Dịch: Hãy chắc chắn rằng chiếc thang được đặt trên một bề mặt vững chắc trước khi trèo lên.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_5_350","topic":"Nature and Environmental Protection","word":"status","pos":"(n)","ipa":"/ˈsteɪ.t̬əs/","defVi":"địa vị, vị thế; tình trạng","defEn":"an official position, social rank, or current condition of a situation","examples":["The committee checked the current [status] of the construction project. (=Dịch: Ủy ban đã kiểm tra tình trạng hiện tại của dự án xây dựng.)","She gained higher social [status] after receiving the prestigious award. (=Dịch: Cô ấy đã đạt được vị thế xã hội cao hơn sau khi nhận giải thưởng danh giá.)","You can track the delivery [status] of your package online. (=Dịch: Bạn có thể theo dõi tình trạng giao kiện hàng của mình trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=status&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.t%CC%AC%C9%99s%2F","usAudio":"/ai_services/tts3/?q=status&lang=en-US&ipa=%2F%CB%88ste%C9%AA.t%CC%AC%C9%99s%2F"},{"id":"lv_5_351","topic":"Nature and Environmental Protection","word":"stork","pos":"(n)","ipa":"/stɔːrk/","defVi":"con cò, con hạc","defEn":"a large bird with long legs, a long neck, and a long beak, often living near water","examples":["A white [stork] built its large nest on top of the old chimney. (=Dịch: Một con cò trắng đã xây chiếc tổ lớn trên đỉnh ống khói cũ.)","In European folklore, the [stork] is believed to bring newborn babies to parents. (=Dịch: Trong văn hóa dân gian châu Âu, loài cò được tin là mang những đứa trẻ sơ sinh đến cho cha mẹ.)","We observed a majestic [stork] wading patiently through the shallow wetland. (=Dịch: Chúng tôi quan sát một con cò uy nghi đang kiên nhẫn lội qua vùng đất ngập nước nông.)"],"ukAudio":"/ai_services/tts3/?q=stork&lang=en-GB&ipa=%2Fst%C9%94%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=stork&lang=en-US&ipa=%2Fst%C9%94%CB%90rk%2F"},{"id":"lv_5_352","topic":"Nature and Environmental Protection","word":"strand","pos":"(v)","ipa":"/strænd/","defVi":"làm mắc cạn, làm cho mắc kẹt","defEn":"to leave someone or something in a difficult situation without the means to move or leave","examples":["A sudden snowstorm can [strand] travelers at the airport for days. (=Dịch: Một trận bão tuyết bất ngờ có thể làm du khách mắc kẹt tại sân bay nhiều ngày.)","Low tide may [strand] boats on the mudflats until morning. (=Dịch: Thủy triều xuống có thể làm các con thuyền mắc cạn trên bãi bùn cho đến sáng.)","The cancellation of trains [stranded] thousands of daily commuters. (=Dịch: Việc hủy các chuyến tàu đã khiến hàng ngàn người đi làm hàng ngày bị mắc kẹt.)"],"ukAudio":"/ai_services/tts3/?q=strand&lang=en-GB&ipa=%2Fstr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=strand&lang=en-US&ipa=%2Fstr%C3%A6nd%2F"},{"id":"lv_5_353","topic":"Nature and Environmental Protection","word":"stranding","pos":"(n)","ipa":"/ˈstræn.dɪŋ/","defVi":"sự mắc cạn, sự trôi dạt vào bờ","defEn":"an event in which marine animals or boats become stuck on land and unable to move","examples":["Scientists are investigating the mass [stranding] of whales along the coast. (=Dịch: Các nhà khoa học đang điều tra vụ mắc cạn hàng loạt của cá voi dọc theo bờ biển.)","The sudden snowstorm caused the [stranding] of hundreds of travelers at the airport. (=Dịch: Cơn bão tuyết bất ngờ đã khiến hàng trăm du khách bị mắc kẹt tại sân bay.)","Volunteers worked quickly to prevent the [stranding] of injured sea turtles. (=Dịch: Các tình nguyện viên đã làm việc nhanh chóng để ngăn chặn những chú rùa biển bị thương khỏi mắc cạn.)"],"ukAudio":"/ai_services/tts3/?q=stranding&lang=en-GB&ipa=%2F%CB%88str%C3%A6n.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=stranding&lang=en-US&ipa=%2F%CB%88str%C3%A6n.d%C9%AA%C5%8B%2F"},{"id":"lv_5_354","topic":"Nature and Environmental Protection","word":"stranger","pos":"(n)","ipa":"/ˈstreɪn.dʒɚ/","defVi":"người lạ","defEn":"a person whom one does not know or with whom one is not familiar","examples":["Children are often taught not to talk to a [stranger] in public places. (=Dịch: Trẻ em thường được dạy không nên nói chuyện với người lạ ở nơi công cộng.)","When she moved to the new city, she felt like a complete [stranger]. (=Dịch: Khi chuyển đến thành phố mới, cô cảm thấy mình như một người hoàn toàn xa lạ.)","A kind [stranger] helped me find my way back to the train station. (=Dịch: Một người lạ tốt bụng đã giúp tôi tìm đường trở lại ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=stranger&lang=en-GB&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=stranger&lang=en-US&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_5_355","topic":"Nature and Environmental Protection","word":"stream","pos":"(n)","ipa":"/striːm/","defVi":"dòng suối, con suối","defEn":"a small, narrow river of water","examples":["We sat by a clear mountain [stream] to have our picnic lunch. (=Dịch: Chúng tôi ngồi bên một dòng suối núi trong vắt để ăn bữa trưa dã ngoại.)","The children enjoyed catching small fish in the shallow [stream]. (=Dịch: Lũ trẻ rất thích bắt những con cá nhỏ trong con suối nông.)","A gentle [stream] flows through the middle of the quiet village. (=Dịch: Một dòng suối êm đềm chảy qua giữa ngôi làng yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=stream&lang=en-GB&ipa=%2Fstri%CB%90m%2F","usAudio":"/ai_services/tts3/?q=stream&lang=en-US&ipa=%2Fstri%CB%90m%2F"},{"id":"lv_5_356","topic":"Nature and Environmental Protection","word":"string","pos":"(n)","ipa":"/strɪŋ/","defVi":"sợi dây, sợi chỉ mảnh","defEn":"thin cord or thread used for tying, hanging, or fastening things","examples":["He tied the parcel securely with a long piece of durable [string]. (=Dịch: Anh ấy buộc chặt bưu kiện bằng một đoạn dây dù bền và dài.)","The musician replaced a broken [string] on his classical guitar. (=Dịch: Người nhạc sĩ đã thay một sợi dây bị đứt trên cây đàn guitar cổ điển của mình.)","She used colorful [string] to hang the party decorations along the wall. (=Dịch: Cô ấy dùng dây nhiều màu sắc để treo đồ trang trí tiệc dọc theo bức tường.)"],"ukAudio":"/ai_services/tts3/?q=string&lang=en-GB&ipa=%2Fstr%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=string&lang=en-US&ipa=%2Fstr%C9%AA%C5%8B%2F"},{"id":"lv_5_357","topic":"Nature and Environmental Protection","word":"strip","pos":"(v)","ipa":"/strɪp/","defVi":"lột, bóc bỏ; tước đoạt","defEn":"to remove the outer layer or covering from something, or to take something away","examples":["In autumn, the strong winds [strip] the leaves from the trees. (=Dịch: Vào mùa thu, những cơn gió mạnh cuốn sạch lá khỏi cây cối.)","The athlete was [stripped] of his medal after failing the drug test. (=Dịch: Vận động viên đã bị tước huy chương sau khi không qua được buổi kiểm tra chất kích thích.)","Volunteers helped [strip] the old wallpaper before repainting the room. (=Dịch: Các tình nguyện viên đã giúp bóc lớp giấy dán tường cũ trước khi sơn lại căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=strip&lang=en-GB&ipa=%2Fstr%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=strip&lang=en-US&ipa=%2Fstr%C9%AAp%2F"},{"id":"lv_5_358","topic":"Nature and Environmental Protection","word":"sub","pos":"(n)","ipa":"/sʌb/","defVi":"Tàu ngầm hoặc cầu thủ dự bị.","defEn":"A submarine or a substitute player in a sports team.","examples":["The coach decided to bring on a [sub] in the second half of the match. (=Dịch: Huấn luyện viên quyết định tung một cầu thủ dự bị vào sân ở hiệp hai của trận đấu.)","The military operates a nuclear-powered [sub] for deep-sea defense. (=Dịch: Quân đội vận hành một chiếc tàu ngầm chạy bằng năng lượng hạt nhân để phòng thủ dưới biển sâu.)","He worked as a [sub] teacher when the regular instructor fell ill. (=Dịch: Anh ấy đã làm giáo viên dạy thay khi người hướng dẫn chính bị ốm.)"],"ukAudio":"/ai_services/tts3/?q=sub&lang=en-GB&ipa=%2Fs%CA%8Cb%2F","usAudio":"/ai_services/tts3/?q=sub&lang=en-US&ipa=%2Fs%CA%8Cb%2F"},{"id":"lv_5_359","topic":"Nature and Environmental Protection","word":"substance","pos":"(n)","ipa":"/ˈsʌb.stəns/","defVi":"chất, vật chất","defEn":"a particular type of solid, liquid, or gas that has specific physical properties","examples":["The laboratory is analyzing an unknown chemical [substance] found in the river. (=Dịch: Phòng thí nghiệm đang phân tích một chất hóa học lạ được tìm thấy dưới sông.)","Rubber is an elastic [substance] used to manufacture car tires. (=Dịch: Cao su là một chất có tính đàn hồi được dùng để sản xuất lốp xe ô tô.)","The spilled [substance] quickly dissolved when water was added. (=Dịch: Chất bị đổ ra đã nhanh chóng hòa tan khi nước được thêm vào.)"],"ukAudio":"/ai_services/tts3/?q=substance&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=substance&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F"},{"id":"lv_5_360","topic":"Nature and Environmental Protection","word":"sufficient","pos":"(adj)","ipa":"/sə.ˈfɪʃ.ənt/","defVi":"Đủ, đáp ứng đủ yêu cầu","defEn":"Enough for a particular purpose; as much as is needed.","examples":["Make sure you drink [sufficient] water during the long marathon. (=Dịch: Hãy đảm bảo rằng bạn uống đủ nước trong suốt cuộc chạy marathon dài.)","There was not [sufficient] evidence to prove the suspect's guilt. (=Dịch: Không có đủ bằng chứng để chứng minh tội trạng của nghi phạm.)","One bowl of soup is [sufficient] for a light lunch. (=Dịch: Một bát súp là đủ cho một bữa trưa nhẹ nhàng.)"],"ukAudio":"/ai_services/tts3/?q=sufficient&lang=en-GB&ipa=%2Fs%C9%99.%CB%88f%C9%AA%CA%83.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=sufficient&lang=en-US&ipa=%2Fs%C9%99.%CB%88f%C9%AA%CA%83.%C9%99nt%2F"},{"id":"lv_5_361","topic":"Nature and Environmental Protection","word":"sunlight","pos":"(n)","ipa":"/ˈsʌn.laɪt/","defVi":"ánh sáng mặt trời, ánh nắng","defEn":"the light that comes from the sun","examples":["Plants need plenty of [sunlight] and water to grow properly. (=Dịch: Cây cối cần nhiều ánh nắng mặt trời và nước để phát triển tốt.)","The room was flooded with warm [sunlight] early in the morning. (=Dịch: Căn phòng tràn ngập ánh nắng ấm áp vào sáng sớm.)","You should wear sunscreen to protect your skin from intense [sunlight]. (=Dịch: Bạn nên thoa kem chống nắng để bảo vệ da khỏi ánh nắng gay gắt.)"],"ukAudio":"/ai_services/tts3/?q=sunlight&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=sunlight&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.la%C9%AAt%2F"},{"id":"lv_5_362","topic":"Nature and Environmental Protection","word":"survive","pos":"(v)","ipa":"/sɚˈvaɪv/","defVi":"sống sót, tồn tại qua nghịch cảnh","defEn":"to continue to live or exist, especially through difficult conditions","examples":["Desert plants have special adaptations that help them [survive] without rain. (=Dịch: Cây sa mạc có những đặc tính thích nghi đặc biệt giúp chúng sinh tồn mà không cần mưa.)","Only a few passengers managed to [survive] the severe shipwreck. (=Dịch: Chỉ có một vài hành khách may mắn sống sót sau vụ đắm tàu kinh hoàng.)","Local businesses must adapt quickly to [survive] in a competitive market. (=Dịch: Các doanh nghiệp địa phương phải nhanh chóng thích ứng để tồn tại trong thị trường cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=survive&lang=en-GB&ipa=%2Fs%C9%9A%CB%88va%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=survive&lang=en-US&ipa=%2Fs%C9%9A%CB%88va%C9%AAv%2F"},{"id":"lv_5_363","topic":"Nature and Environmental Protection","word":"sustainable","pos":"(adj)","ipa":"/səˈsteɪ.nə.bəl/","defVi":"bền vững (không gây hại đến môi trường hoặc tài nguyên)","defEn":"able to continue over a period of time without causing damage to the environment","examples":["The company is investing heavily in [sustainable] energy solutions like solar and wind power. (=Dịch: Công ty đang đầu tư mạnh vào các giải pháp năng lượng bền vững như điện mặt trời và năng lượng gió.)","Farmers are encouraged to adopt more [sustainable] practices to protect the soil quality. (=Dịch: Nông dân được khuyến khích áp dụng các phương pháp bền vững hơn để bảo vệ chất lượng đất.)","Tourism needs to be [sustainable] so that local ecosystems are not permanently damaged. (=Dịch: Du lịch cần phải bền vững để hệ sinh thái địa phương không bị hủy hoại lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=sustainable&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sustainable&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F"},{"id":"lv_5_364","topic":"Nature and Environmental Protection","word":"swimmer","pos":"(n)","ipa":"/ˈswɪm.ɚ/","defVi":"Người bơi lội, kình ngư.","defEn":"A person who swims, especially as a sport or recreation.","examples":["She is a talented [swimmer] who has won several national championships. (=Dịch: Cô ấy là một kình ngư tài năng từng giành được nhiều chức vô địch quốc gia.)","Lifeguards warned every [swimmer] to stay close to the shore. (=Dịch: Các nhân viên cứu hộ đã cảnh báo mọi người bơi phải ở gần bờ.)","Regular practice helped him become a much faster [swimmer]. (=Dịch: Luyện tập đều đặn đã giúp anh ấy trở thành một người bơi nhanh hơn rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=swimmer&lang=en-GB&ipa=%2F%CB%88sw%C9%AAm.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=swimmer&lang=en-US&ipa=%2F%CB%88sw%C9%AAm.%C9%9A%2F"},{"id":"lv_5_365","topic":"Nature and Environmental Protection","word":"sydney","pos":"(n)","ipa":"/ˈsɪd.ni/","defVi":"Sydney (thành phố lớn nhất của Úc).","defEn":"The largest city in Australia, famous for its Opera House and harbor.","examples":["Many tourists visit [sydney] to see the iconic Opera House. (=Dịch: Nhiều khách du lịch đến thăm Sydney để chiêm ngưỡng nhà hát Opera mang tính biểu tượng.)","She decided to study abroad at a university located in [sydney]. (=Dịch: Cô quyết định đi du học tại một trường đại học nằm ở Sydney.)","The international flight landed safely at the airport in [sydney]. (=Dịch: Chuyến bay quốc tế đã hạ cánh an toàn tại sân bay ở Sydney.)"],"ukAudio":"/ai_services/tts3/?q=sydney&lang=en-GB&ipa=%2F%CB%88s%C9%AAd.ni%2F","usAudio":"/ai_services/tts3/?q=sydney&lang=en-US&ipa=%2F%CB%88s%C9%AAd.ni%2F"},{"id":"lv_5_366","topic":"Nature and Environmental Protection","word":"tail","pos":"(n)","ipa":"/teɪl/","defVi":"đuôi (động vật, đồ vật)","defEn":"the part that sticks out at the back end of an animal's body","examples":["The dog wagged its [tail] happily when its owner came home. (=Dịch: Con chó vẫy đuôi vui mừng khi chủ của nó về nhà.)","The airplane's [tail] was damaged during the emergency landing. (=Dịch: Phần đuôi của máy bay đã bị hư hại trong quá trình hạ cánh khẩn cấp.)","A long [tail] of traffic formed behind the broken-down truck. (=Dịch: Một hàng dài xe cộ nối đuôi nhau đã hình thành phía sau chiếc xe tải bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=tail&lang=en-GB&ipa=%2Fte%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=tail&lang=en-US&ipa=%2Fte%C9%AAl%2F"},{"id":"lv_5_367","topic":"Nature and Environmental Protection","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, khóa van","defEn":"a device used to control the flow of liquid or gas from a pipe","examples":["Don't forget to turn off the [tap] while brushing your teeth to save water. (=Dịch: Đừng quên tắt vòi nước trong khi đánh răng để tiết kiệm nước.)","The kitchen [tap] has been leaking continuously since yesterday morning. (=Dịch: Vòi nước trong bếp đã bị rò rỉ liên tục từ sáng hôm qua.)","Filtered drinking water is available directly from this special [tap]. (=Dịch: Nước uống đã qua lọc có sẵn trực tiếp từ chiếc vòi nước đặc biệt này.)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_5_368","topic":"Nature and Environmental Protection","word":"tardigrade","pos":"(n)","ipa":"/ˈtɑːr.də.ɡreɪd/","defVi":"Bọ gấu nước (sinh vật vi mô có khả năng sống sót phi thường).","defEn":"A microscopic animal capable of surviving extreme conditions, also called a water bear.","examples":["Scientists study the [tardigrade] because it can survive in extreme temperatures. (=Dịch: Các nhà khoa học nghiên cứu bọ gấu nước vì nó có thể sống sót trong nhiệt độ khắc nghiệt.)","A [tardigrade] can withstand the vacuum and radiation of outer space. (=Dịch: Một con bọ gấu nước có thể chịu được môi trường chân không và bức xạ ngoài không gian.)","Under a microscope, the tiny [tardigrade] looks like an eight-legged bear. (=Dịch: Dưới kính hiển vi, sinh vật bọ gấu nước nhỏ bé trông giống như một con gấu tám chân.)"],"ukAudio":"/ai_services/tts3/?q=tardigrade&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90r.d%C9%99.%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=tardigrade&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90r.d%C9%99.%C9%A1re%C9%AAd%2F"},{"id":"lv_5_369","topic":"Nature and Environmental Protection","word":"territory","pos":"(n)","ipa":"/ˈter.ə.tɔːr.i/","defVi":"lãnh thổ, địa bàn","defEn":"an area of land under the jurisdiction of a ruler or state, or defended by an animal","examples":["The pack of wolves defended its hunting [territory] against rival packs. (=Dịch: Đàn sói đã bảo vệ lãnh thổ săn mồi của mình trước các đàn đối thủ.)","The company expanded its business into foreign [territory] last year. (=Dịch: Công ty đã mở rộng hoạt động kinh doanh sang thị trường nước ngoài vào năm ngoái.)","The disputed [territory] has been a source of conflict for decades. (=Dịch: Vùng lãnh thổ tranh chấp đã là nguồn cơn xung đột trong nhiều thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=territory&lang=en-GB&ipa=%2F%CB%88ter.%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=territory&lang=en-US&ipa=%2F%CB%88ter.%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_5_370","topic":"Nature and Environmental Protection","word":"testing","pos":"(n)","ipa":"/ˈtes.tɪŋ/","defVi":"sự thử nghiệm, kiểm tra","defEn":"the process of checking the quality, performance, or reliability of something","examples":["The new software underwent rigorous [testing] before its official launch. (=Dịch: Phần mềm mới đã trải qua quá trình kiểm tra nghiêm ngặt trước khi ra mắt chính thức.)","Medical [testing] is crucial to ensure that the new vaccine is safe for public use. (=Dịch: Việc thử nghiệm y tế là rất quan trọng để đảm bảo rằng loại vắc-xin mới an toàn cho cộng đồng.)","Laboratory [testing] confirmed the presence of minerals in the water sample. (=Dịch: Việc kiểm nghiệm trong phòng thí nghiệm đã xác nhận sự hiện diện của các khoáng chất trong mẫu nước.)"],"ukAudio":"/ai_services/tts3/?q=testing&lang=en-GB&ipa=%2F%CB%88tes.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=testing&lang=en-US&ipa=%2F%CB%88tes.t%C9%AA%C5%8B%2F"},{"id":"lv_5_371","topic":"Nature and Environmental Protection","word":"texture","pos":"(n)","ipa":"/ˈtɛks.tʃɚ/","defVi":"kết cấu, cảm giác bề mặt (của vật liệu, thức ăn)","defEn":"the feel, appearance, or consistency of a surface or a substance","examples":["The smooth [texture] of the silk fabric feels very comfortable against the skin. (=Dịch: Kết cấu mịn màng của vải lụa tạo cảm giác rất thoải mái trên da.)","Adding nuts gives this homemade bread a crunchy [texture]. (=Dịch: Việc thêm các loại hạt mang lại cho chiếc bánh mì tự làm này một kết cấu giòn rụm.)","The artist used heavy brushstrokes to create a rough [texture] on the canvas. (=Dịch: Họa sĩ đã sử dụng những nét cọ đậm để tạo nên kết cấu gồ ghề trên tấm toan.)"],"ukAudio":"/ai_services/tts3/?q=texture&lang=en-GB&ipa=%2F%CB%88t%C9%9Bks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=texture&lang=en-US&ipa=%2F%CB%88t%C9%9Bks.t%CA%83%C9%9A%2F"},{"id":"lv_5_372","topic":"Nature and Environmental Protection","word":"thailand","pos":"(n)","ipa":"/ˈtaɪ.lænd/","defVi":"Thái Lan (quốc gia ở Đông Nam Á).","defEn":"A country in Southeast Asia known for its tropical beaches, temples, and cuisine.","examples":["Millions of travelers visit [thailand] every year for its rich culture and beaches. (=Dịch: Hàng triệu du khách đến thăm Thái Lan mỗi năm vì nền văn hóa phong phú và các bãi biển đẹp.)","Street food is an essential part of daily life across [thailand]. (=Dịch: Ẩm thực đường phố là một phần thiết yếu trong đời sống thường nhật trên khắp Thái Lan.)","Her family planned a summer vacation to the northern mountains of [thailand]. (=Dịch: Gia đình cô đã lên kế hoạch cho kỳ nghỉ hè tới vùng núi phía bắc Thái Lan.)"],"ukAudio":"/ai_services/tts3/?q=thailand&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=thailand&lang=en-US&ipa=%2F%CB%88ta%C9%AA.l%C3%A6nd%2F"},{"id":"lv_5_373","topic":"Nature and Environmental Protection","word":"thermal","pos":"(adj)","ipa":"/ˈθɝː.məl/","defVi":"Thuộc về nhiệt, giữ nhiệt","defEn":"Connected with heat or designed to retain heat.","examples":["The hikers wore [thermal] underwear to protect themselves from the freezing cold. (=Dịch: Những người đi bộ đường dài đã mặc đồ lót giữ nhiệt để bảo vệ mình khỏi cái lạnh cóng.)","Iceland is famous for its natural [thermal] springs. (=Dịch: Iceland nổi tiếng với các suối nước nóng tự nhiên.)","Engineers are developing new ways to capture [thermal] energy. (=Dịch: Các kỹ sư đang phát triển những phương pháp mới để thu giữ nhiệt năng.)"],"ukAudio":"/ai_services/tts3/?q=thermal&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9D%CB%90.m%C9%99l%2F","usAudio":"/ai_services/tts3/?q=thermal&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9D%CB%90.m%C9%99l%2F"},{"id":"lv_5_374","topic":"Nature and Environmental Protection","word":"thirdly","pos":"(adv)","ipa":"/ˈθɜrd.li/","defVi":"thứ ba là, điểm thứ ba là","defEn":"used to introduce the third point in a list or argument","examples":["First, we need more staff; secondly, better equipment; and [thirdly], a larger budget. (=Dịch: Thứ nhất, chúng ta cần thêm nhân lực; thứ hai, trang thiết bị tốt hơn; và thứ ba là một ngân sách lớn hơn.)","[Thirdly], the report highlights the growing environmental impact of urban expansion. (=Dịch: Thứ ba là báo cáo nhấn mạnh tác động môi trường ngày càng tăng của việc mở rộng đô thị.)","And [thirdly], we must ensure that all safety regulations are strictly followed. (=Dịch: Và thứ ba là chúng ta phải đảm bảo rằng mọi quy định an toàn đều được tuân thủ nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=thirdly&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9Crd.li%2F","usAudio":"/ai_services/tts3/?q=thirdly&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9Crd.li%2F"},{"id":"lv_5_375","topic":"Nature and Environmental Protection","word":"threaten","pos":"(v)","ipa":"/ˈθrɛ.tən/","defVi":"đe dọa, uy hiếp","defEn":"to state an intention to harm someone or to be likely to cause damage to something","examples":["Pollution continues to [threaten] the survival of marine life. (=Dịch: Ô nhiễm tiếp tục đe dọa sự sống còn của sinh vật biển.)","Dark clouds gathered overhead and began to [threaten] rain. (=Dịch: Mây đen kéo đến vần vũ và đe dọa sẽ đổ mưa.)","The robber attempted to [threaten] the cashier with a weapon. (=Dịch: Kẻ cướp đã cố gắng đe dọa nhân viên thu ngân bằng vũ khí.)"],"ukAudio":"/ai_services/tts3/?q=threaten&lang=en-GB&ipa=%2F%CB%88%CE%B8r%C9%9B.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=threaten&lang=en-US&ipa=%2F%CB%88%CE%B8r%C9%9B.t%C9%99n%2F"},{"id":"lv_5_376","topic":"Nature and Environmental Protection","word":"thrive","pos":"(v)","ipa":"/θraɪv/","defVi":"phát triển mạnh, thịnh vượng, lớn nhanh","defEn":"to grow, develop, or be successful","examples":["Many species of plants [thrive] in tropical climates. (=Dịch: Nhiều loài thực vật phát triển mạnh ở vùng khí hậu nhiệt đới.)","The local tourism industry began to [thrive] after the new airport opened. (=Dịch: Ngành du lịch địa phương bắt đầu phát triển hưng thịnh sau khi sân bay mới mở cửa.)","Children [thrive] when they receive love and support from their families. (=Dịch: Trẻ em lớn khôn và phát triển tốt khi nhận được tình yêu thương và sự ủng hộ từ gia đình.)"],"ukAudio":"/ai_services/tts3/?q=thrive&lang=en-GB&ipa=%2F%CE%B8ra%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=thrive&lang=en-US&ipa=%2F%CE%B8ra%C9%AAv%2F"},{"id":"lv_5_377","topic":"Nature and Environmental Protection","word":"tidal","pos":"(adj)","ipa":"/ˈtaɪ.dəl/","defVi":"thuộc về thủy triều, chịu ảnh hưởng của triều cường","defEn":"relating to or affected by the regular rise and fall of the sea level","examples":["The coastal road was temporarily closed due to high [tidal] waves. (=Dịch: Tuyến đường ven biển đã tạm thời bị đóng do sóng thủy triều dâng cao.)","Engineers are exploring renewable energy generated by [tidal] currents. (=Dịch: Các kỹ sư đang nghiên cứu năng lượng tái tạo được tạo ra từ các dòng thủy triều.)","The estuary contains vast [tidal] mudflats that attract migratory birds. (=Dịch: Vùng cửa sông có những bãi bồi ven triều rộng lớn thu hút các loài chim di cư.)"],"ukAudio":"/ai_services/tts3/?q=tidal&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.d%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tidal&lang=en-US&ipa=%2F%CB%88ta%C9%AA.d%C9%99l%2F"},{"id":"lv_5_378","topic":"Nature and Environmental Protection","word":"tide","pos":"(n)","ipa":"/taɪd/","defVi":"thủy triều, con nước","defEn":"the regular rise and fall in the level of the sea caused by the gravitational pull of the moon and sun","examples":["We had to wait for high [tide] before sailing our boat out of the bay. (=Dịch: Chúng tôi phải đợi thủy triều lên trước khi chèo thuyền ra khỏi vịnh.)","At low [tide], children enjoy exploring the rock pools along the beach. (=Dịch: Khi thủy triều xuống, trẻ em thích thú khám phá các vũng nước quanh bãi đá ven biển.)","The rising [tide] quickly washed away their sandcastles. (=Dịch: Thủy triều dâng cao nhanh chóng cuốn trôi những lâu đài cát của họ.)"],"ukAudio":"/ai_services/tts3/?q=tide&lang=en-GB&ipa=%2Fta%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=tide&lang=en-US&ipa=%2Fta%C9%AAd%2F"},{"id":"lv_5_379","topic":"Nature and Environmental Protection","word":"timeline","pos":"(n)","ipa":"/ˈtaɪm.laɪn/","defVi":"dòng thời gian, tiến độ thời gian","defEn":"a visual representation or schedule showing the order in which events happen","examples":["The project manager created a clear [timeline] to track our daily progress. (=Dịch: Quản lý dự án đã tạo ra một tiến độ thời gian rõ ràng để theo dõi tiến độ hàng ngày của chúng tôi.)","The history textbook includes a detailed [timeline] of World War II. (=Dịch: Sách giáo khoa lịch sử bao gồm một dòng thời gian chi tiết về Thế chiến thứ hai.)","We need to adjust the construction [timeline] due to unexpected weather delays. (=Dịch: Chúng tôi cần điều chỉnh tiến độ thi công do sự chậm trễ ngoài dự kiến bởi thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=timeline&lang=en-GB&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=timeline&lang=en-US&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F"},{"id":"lv_5_380","topic":"Nature and Environmental Protection","word":"tongue","pos":"(n)","ipa":"/tʌŋ/","defVi":"lưỡi; ngôn ngữ","defEn":"the soft, moveable organ in the mouth used for tasting and speaking, or a language","examples":["He burned his [tongue] because the soup was too hot. (=Dịch: Anh ấy bị bỏng lưỡi vì món súp quá nóng.)","Spanish is her native [tongue], but she also speaks fluent English. (=Dịch: Tiếng Tây Ban Nha là tiếng mẹ đẻ của cô ấy, nhưng cô ấy cũng nói tiếng Anh rất lưu loát.)","The doctor asked the patient to stick out his [tongue]. (=Dịch: Bác sĩ đã yêu cầu bệnh nhân thè lưỡi ra.)"],"ukAudio":"/ai_services/tts3/?q=tongue&lang=en-GB&ipa=%2Ft%CA%8C%C5%8B%2F","usAudio":"/ai_services/tts3/?q=tongue&lang=en-US&ipa=%2Ft%CA%8C%C5%8B%2F"},{"id":"lv_5_381","topic":"Nature and Environmental Protection","word":"topsoil","pos":"(n)","ipa":"/ˈtɑːp.sɔɪl/","defVi":"lớp đất mặt, tầng đất canh tác","defEn":"the upper, outermost layer of soil, usually containing organic matter and nutrients","examples":["Heavy rainfall washed away the fertile [topsoil] on the hillside farms. (=Dịch: Mưa lớn đã cuốn trôi lớp đất mặt màu mỡ trên các nông trại sườn đồi.)","It takes hundreds of years for nature to form a single inch of rich [topsoil]. (=Dịch: Tự nhiên phải mất hàng trăm năm để tạo ra một inch lớp đất mặt giàu dinh dưỡng.)","Farmers use cover crops to prevent [topsoil] erosion during windy seasons. (=Dịch: Người nông dân trồng cây che phủ đất để ngăn chặn xói mòn lớp đất mặt trong mùa gió.)"],"ukAudio":"/ai_services/tts3/?q=topsoil&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90p.s%C9%94%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=topsoil&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90p.s%C9%94%C9%AAl%2F"},{"id":"lv_5_382","topic":"Nature and Environmental Protection","word":"toxic","pos":"(adj)","ipa":"/ˈtɑk.sɪk/","defVi":"độc hại, có chứa chất độc","defEn":"containing poisonous substances that can cause harm or death","examples":["The factory was fined for dumping [toxic] chemical waste into the river. (=Dịch: Nhà máy đã bị phạt vì xả chất thải hóa học độc hại xuống sông.)","Wearing protective masks prevents workers from inhaling [toxic] fumes. (=Dịch: Đeo khẩu trang bảo hộ giúp công nhân tránh hít phải khói độc.)","Certain household cleaning products can be [toxic] if swallowed by pets. (=Dịch: Một số sản phẩm tẩy rửa gia dụng có thể gây độc nếu vật nuôi nuốt phải.)"],"ukAudio":"/ai_services/tts3/?q=toxic&lang=en-GB&ipa=%2F%CB%88t%C9%91k.s%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=toxic&lang=en-US&ipa=%2F%CB%88t%C9%91k.s%C9%AAk%2F"},{"id":"lv_5_383","topic":"Nature and Environmental Protection","word":"toxin","pos":"(n)","ipa":"/ˈtɑːk.sɪn/","defVi":"độc tố, chất độc sinh học","defEn":"a poisonous substance, especially one produced by bacteria or living organisms","examples":["Certain species of snake produce a powerful [toxin] to paralyze their prey. (=Dịch: Một số loài rắn sản sinh ra một loại độc tố mạnh để làm tê liệt con mồi.)","Drinking plenty of water helps the body flush out harmful [toxin] substances. (=Dịch: Uống nhiều nước giúp cơ thể đào thải các chất độc tố có hại.)","The biological [toxin] found in the contaminated food caused severe illness. (=Dịch: Độc tố sinh học được tìm thấy trong thực phẩm ôi thiu đã gây ra bệnh nặng.)"],"ukAudio":"/ai_services/tts3/?q=toxin&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=toxin&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F"},{"id":"lv_5_384","topic":"Nature and Environmental Protection","word":"transform","pos":"(v)","ipa":"/trænsˈfɔːrm/","defVi":"biến đổi, thay đổi hoàn toàn","defEn":"to completely change the appearance, form, or character of something","examples":["New public transport systems can [transform] the entire city. (=Dịch: Các hệ thống giao thông công cộng mới có thể biến đổi toàn bộ thành phố.)","The internet continues to [transform] the way people communicate. (=Dịch: Internet tiếp tục làm thay đổi hoàn toàn cách mọi người giao tiếp.)","A coat of fresh paint will [transform] this old bedroom completely. (=Dịch: Một lớp sơn mới sẽ làm thay đổi hoàn toàn căn phòng ngủ cũ kỹ này.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94%CB%90rm%2F"},{"id":"lv_5_385","topic":"Nature and Environmental Protection","word":"translocation","pos":"(n)","ipa":"/ˌtrænz.loʊˈkeɪ.ʃən/","defVi":"sự di dời, sự chuyển vị (đặc biệt là động thực vật)","defEn":"the process of moving something, especially wild animals or plants, to a new location","examples":["The conservation team organised the [translocation] of ten rhinos to a safer habitat. (=Dịch: Nhóm bảo tồn đã tổ chức việc di dời mười cá thể tê giác đến một môi trường sống an toàn hơn.)","Successful [translocation] depends heavily on whether the new area has sufficient food sources. (=Dịch: Sự di dời thành công phụ thuộc rất nhiều vào việc khu vực mới có đủ nguồn thức ăn hay không.)","Biologists monitored the species closely after its [translocation] to the national park. (=Dịch: Các nhà sinh vật học đã theo dõi chặt chẽ loài này sau khi nó được chuyển vị vào vườn quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=translocation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6nz.lo%CA%8A%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=translocation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6nz.lo%CA%8A%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_386","topic":"Nature and Environmental Protection","word":"treaty","pos":"(n)","ipa":"/ˈtriː.t̬i/","defVi":"hiệp ước, hiệp định","defEn":"a formal, legally binding agreement concluded between countries","examples":["The two nations signed a peace [treaty] to end the decade-long conflict. (=Dịch: Hai quốc gia đã ký một hiệp ước hòa bình để chấm dứt cuộc xung đột kéo dài cả thập kỷ.)","Environmental groups urged leaders to ratify the international climate [treaty]. (=Dịch: Các nhóm môi trường đã thúc giục các nhà lãnh đạo phê chuẩn hiệp ước khí hậu quốc tế.)","Under the terms of the [treaty], trade barriers between the countries were reduced. (=Dịch: Theo các điều khoản của hiệp ước, các rào cản thương mại giữa các nước đã được giảm bớt.)"],"ukAudio":"/ai_services/tts3/?q=treaty&lang=en-GB&ipa=%2F%CB%88tri%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=treaty&lang=en-US&ipa=%2F%CB%88tri%CB%90.t%CC%ACi%2F"},{"id":"lv_5_387","topic":"Nature and Environmental Protection","word":"trial","pos":"(n)","ipa":"/ˈtraɪ.əl/","defVi":"sự thử nghiệm, cuộc thử nghiệm","defEn":"a test of the performance, qualities, or suitability of someone or something","examples":["The new drug is currently undergoing a clinical [trial] to ensure its safety. (=Dịch: Loại thuốc mới hiện đang trải qua một cuộc thử nghiệm lâm sàng để đảm bảo tính an toàn.)","Customers can download software for a free thirty-day [trial]. (=Dịch: Khách hàng có thể tải phần mềm để dùng thử miễn phí trong ba mươi ngày.)","They learned the most effective technique through a process of [trial] and error. (=Dịch: Họ đã học được kỹ thuật hiệu quả nhất thông qua quá trình thử và sai.)"],"ukAudio":"/ai_services/tts3/?q=trial&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=trial&lang=en-US&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F"},{"id":"lv_5_388","topic":"Nature and Environmental Protection","word":"tropical","pos":"(adj)","ipa":"/ˈtrɑː.pɪ.kəl/","defVi":"thuộc nhiệt đới","defEn":"relating to or typical of the warm and humid regions near the equator","examples":["Many exotic fruits thrive in a warm [tropical] climate. (=Dịch: Nhiều loại trái cây độc lạ phát triển mạnh ở vùng khí hậu nhiệt đới ấm áp.)","They spent their holiday relaxing on a beautiful [tropical] island. (=Dịch: Họ đã dành kỳ nghỉ để thư giãn trên một hòn đảo nhiệt đới xinh đẹp.)","The region is frequently hit by destructive [tropical] storms. (=Dịch: Khu vực này thường xuyên bị tấn công bởi những cơn bão nhiệt đới có sức tàn phá lớn.)"],"ukAudio":"/ai_services/tts3/?q=tropical&lang=en-GB&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tropical&lang=en-US&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F"},{"id":"lv_5_389","topic":"Nature and Environmental Protection","word":"trucks","pos":"(n)","ipa":"/trʌks/","defVi":"xe tải (dạng số nhiều)","defEn":"large, heavy motor vehicles used for transporting goods","examples":["Heavy [trucks] are prohibited from entering the city centre during peak hours. (=Dịch: Xe tải hạng nặng bị cấm đi vào trung tâm thành phố trong giờ cao điểm.)","A fleet of [trucks] delivered the construction materials to the building site. (=Dịch: Một đội xe tải đã vận chuyển các vật liệu xây dựng đến công trường.)","Many transport companies are switching to electric [trucks] to reduce emissions. (=Dịch: Nhiều công ty vận tải đang chuyển sang dùng xe tải điện để giảm thiểu lượng khí thải.)"],"ukAudio":"/ai_services/tts3/?q=trucks&lang=en-GB&ipa=%2Ftr%CA%8Cks%2F","usAudio":"/ai_services/tts3/?q=trucks&lang=en-US&ipa=%2Ftr%CA%8Cks%2F"},{"id":"lv_5_390","topic":"Nature and Environmental Protection","word":"tun","pos":"(n)","ipa":"/tʌn/","defVi":"Thùng lớn (thường dùng để ủ bia hoặc chứa rượu).","defEn":"A large cask or barrel used especially for holding beer, wine, or other liquids.","examples":["The traditional brewery stored hundreds of gallons of ale in a massive wooden [tun]. (=Dịch: Nhà máy bia truyền thống đã lưu trữ hàng trăm gallon bia trong một chiếc thùng gỗ khổng lồ.)","Workers carefully cleaned the mash [tun] before starting the next brewing cycle. (=Dịch: Các công nhân đã cẩn thận vệ sinh thùng ngâm mạch nha trước khi bắt đầu chu kỳ nấu bia tiếp theo.)","The historical cellar still contains an ancient oak [tun] from the eighteenth century. (=Dịch: Hầm rượu lịch sử vẫn còn chứa một thùng gỗ sồi cổ từ thế kỷ thứ mười tám.)"],"ukAudio":"/ai_services/tts3/?q=tun&lang=en-GB&ipa=%2Ft%CA%8Cn%2F","usAudio":"/ai_services/tts3/?q=tun&lang=en-US&ipa=%2Ft%CA%8Cn%2F"},{"id":"lv_5_391","topic":"Nature and Environmental Protection","word":"turbine","pos":"(n)","ipa":"/ˈtɜr.baɪn/","defVi":"tuabin","defEn":"a machine with rotating blades that produces power from the movement of air, water, or steam","examples":["A modern wind [turbine] can generate enough electricity for hundreds of homes. (=Dịch: Một tuabin gió hiện đại có thể tạo ra đủ điện cho hàng trăm hộ gia đình.)","Water rushes through the dam to turn the massive [turbine]. (=Dịch: Nước chảy xiết qua đập để làm quay tuabin khổng lồ.)","Engineers are developing a more efficient gas [turbine] for aircraft. (=Dịch: Các kỹ sư đang phát triển một loại tuabin khí hiệu quả hơn cho máy bay.)"],"ukAudio":"/ai_services/tts3/?q=turbine&lang=en-GB&ipa=%2F%CB%88t%C9%9Cr.ba%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=turbine&lang=en-US&ipa=%2F%CB%88t%C9%9Cr.ba%C9%AAn%2F"},{"id":"lv_5_392","topic":"Nature and Environmental Protection","word":"turtle","pos":"(n)","ipa":"/ˈtɜːr.t̬əl/","defVi":"con rùa, rùa biển","defEn":"a reptile with a hard round shell that lives mostly in water","examples":["A sea [turtle] laid her eggs on the sandy beach at night. (=Dịch: Một con rùa biển đã đẻ trứng trên bãi cát vào ban đêm.)","The plastic waste in the ocean poses a serious threat to every [turtle]. (=Dịch: Rác thải nhựa trong đại dương là mối đe dọa nghiêm trọng đối với mọi loài rùa.)","We watched a giant [turtle] swimming slowly near the coral reef. (=Dịch: Chúng tôi đã ngắm nhìn một con rùa khổng lồ bơi chậm rãi gần rạn san hô.)"],"ukAudio":"/ai_services/tts3/?q=turtle&lang=en-GB&ipa=%2F%CB%88t%C9%9C%CB%90r.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=turtle&lang=en-US&ipa=%2F%CB%88t%C9%9C%CB%90r.t%CC%AC%C9%99l%2F"},{"id":"lv_5_393","topic":"Nature and Environmental Protection","word":"tusk","pos":"(n)","ipa":"/tʌsk/","defVi":"ngà voi, răng nanh dài của động vật","defEn":"a very long, pointed tooth that sticks out of the mouth of animals like elephants or walruses","examples":["The elephant used its massive [tusk] to dig for roots. (=Dịch: Con voi đã dùng chiếc ngà to lớn của nó để đào rễ cây.)","An old walrus broke its left [tusk] against the sharp ice. (=Dịch: Một con hải mã già đã làm gãy chiếc ngà bên trái vào tảng băng sắc nhọn.)","Scientists examined a prehistoric mammoth [tusk] discovered in the frozen mud. (=Dịch: Các nhà khoa học đã kiểm tra một chiếc ngà voi ma mút tiền sử được phát hiện trong bùn đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=tusk&lang=en-GB&ipa=%2Ft%CA%8Csk%2F","usAudio":"/ai_services/tts3/?q=tusk&lang=en-US&ipa=%2Ft%CA%8Csk%2F"},{"id":"lv_5_394","topic":"Nature and Environmental Protection","word":"twentieth","pos":"(adj)","ipa":"/ˈtwɛn.ti.əθ/","defVi":"thứ hai mươi","defEn":"constituting number twenty in a sequence; coming after nineteenth","examples":["She celebrated her [twentieth] birthday with close family and friends. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ hai mươi cùng gia đình và bạn bè thân thiết.)","The museum features art from the early [twentieth] century. (=Dịch: Bảo tàng trưng bày nghệ thuật từ đầu thế kỷ hai mươi.)","He finished in [twentieth] place out of more than one hundred runners. (=Dịch: Anh ấy về đích ở vị trí thứ hai mươi trong số hơn một trăm vận động viên chạy bộ.)"],"ukAudio":"/ai_services/tts3/?q=twentieth&lang=en-GB&ipa=%2F%CB%88tw%C9%9Bn.ti.%C9%99%CE%B8%2F","usAudio":"/ai_services/tts3/?q=twentieth&lang=en-US&ipa=%2F%CB%88tw%C9%9Bn.ti.%C9%99%CE%B8%2F"},{"id":"lv_5_395","topic":"Nature and Environmental Protection","word":"ultimately","pos":"(adv)","ipa":"/ˈʌl.tə.mət.li/","defVi":"cuối cùng, xét cho cùng","defEn":"in the end, after a process or series of events","examples":["The long and difficult negotiations [ultimately] led to a historic trade agreement. (=Dịch: Các cuộc đàm phán kéo dài và khó khăn cuối cùng đã dẫn đến một hiệp định thương mại lịch sử.)","Parents are [ultimately] responsible for their children's safety and well-being. (=Dịch: Xét cho cùng, cha mẹ là những người chịu trách nhiệm cho sự an toàn và hạnh phúc của con cái họ.)","The success of any business [ultimately] depends on customer satisfaction. (=Dịch: Sự thành công của bất kỳ doanh nghiệp nào cuối cùng cũng phụ thuộc vào sự hài lòng của khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=ultimately&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=ultimately&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t.li%2F"},{"id":"lv_5_396","topic":"Nature and Environmental Protection","word":"understandable","pos":"(adj)","ipa":"/ˌʌn.dɚˈstæn.də.bəl/","defVi":"dễ hiểu, có thể thông cảm được","defEn":"easy to comprehend or reasonable under the circumstances","examples":["His anger was completely [understandable] given the unfair treatment he received. (=Dịch: Sự tức giận của anh ấy là hoàn toàn có thể hiểu được nếu xét đến sự đối xử bất công mà anh ấy phải nhận.)","The professor presented complex theories in simple, [understandable] language. (=Dịch: Giáo sư đã trình bày các lý thuyết phức tạp bằng ngôn ngữ đơn giản, dễ hiểu.)","It is [understandable] that you feel nervous before a major presentation. (=Dịch: Việc bạn cảm thấy lo lắng trước một buổi thuyết trình quan trọng là điều dễ hiểu.)"],"ukAudio":"/ai_services/tts3/?q=understandable&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=understandable&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F"},{"id":"lv_5_397","topic":"Nature and Environmental Protection","word":"undertake","pos":"(v)","ipa":"/ˌʌn.dɚˈteɪk/","defVi":"đảm nhận, thực hiện, cam kết","defEn":"to commit oneself to and begin an enterprise or responsibility","examples":["The company will [undertake] a major research project next month. (=Dịch: Công ty sẽ thực hiện một dự án nghiên cứu lớn vào tháng tới.)","She was willing to [undertake] the responsibility of leading the team. (=Dịch: Cô ấy sẵn sàng đảm nhận trách nhiệm lãnh đạo đội ngũ.)","Doctors had to [undertake] a complex surgical procedure to save the patient. (=Dịch: Các bác sĩ đã phải thực hiện một ca phẫu thuật phức tạp để cứu bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=undertake&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=undertake&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88te%C9%AAk%2F"},{"id":"lv_5_398","topic":"Nature and Environmental Protection","word":"unknown","pos":"(adj)","ipa":"/ˌʌn.ˈnoʊn/","defVi":"Không rõ, chưa được biết đến, vô danh","defEn":"Not known, familiar, or identified.","examples":["The author of the mysterious manuscript remains [unknown]. (=Dịch: Tác giả của bản thảo bí ẩn vẫn chưa được biết đến.)","They decided to explore an [unknown] island in the Pacific. (=Dịch: Họ quyết định khám phá một hòn đảo chưa ai biết tới ở Thái Bình Dương.)","For reasons [unknown], the flight was delayed for three hours. (=Dịch: Vì những lý do không rõ, chuyến bay đã bị hoãn ba tiếng đồng hồ.)"],"ukAudio":"/ai_services/tts3/?q=unknown&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%CB%88no%CA%8An%2F","usAudio":"/ai_services/tts3/?q=unknown&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%CB%88no%CA%8An%2F"},{"id":"lv_5_399","topic":"Nature and Environmental Protection","word":"unpleasant","pos":"(adj)","ipa":"/ʌnˈplɛz.ənt/","defVi":"khó chịu, không vừa ý","defEn":"not enjoyable, attractive, or friendly; causing discomfort","examples":["An [unpleasant] smell was coming from the old refrigerator in the basement. (=Dịch: Một mùi khó chịu bốc ra từ chiếc tủ lạnh cũ dưới tầng hầm.)","He had an [unpleasant] argument with his colleague during the staff meeting. (=Dịch: Anh ấy đã có một cuộc tranh cãi khó chịu với đồng nghiệp trong cuộc họp nhân viên.)","Cold rain made the outdoor walking tour a rather [unpleasant] experience. (=Dịch: Cơn mưa lạnh đã khiến chuyến tham quan đi bộ ngoài trời trở thành một trải nghiệm khá khó chịu.)"],"ukAudio":"/ai_services/tts3/?q=unpleasant&lang=en-GB&ipa=%2F%CA%8Cn%CB%88pl%C9%9Bz.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=unpleasant&lang=en-US&ipa=%2F%CA%8Cn%CB%88pl%C9%9Bz.%C9%99nt%2F"},{"id":"lv_5_400","topic":"Nature and Environmental Protection","word":"unwanted","pos":"(adj)","ipa":"/ʌn.ˈwɑːn.tɪd/","defVi":"không mong muốn, thừa thãi","defEn":"not desired or needed","examples":["You can donate [unwanted] clothes to local charities. (=Dịch: Bạn có thể quyên góp quần áo không dùng đến cho các tổ chức từ thiện địa phương.)","The new filter helps block [unwanted] emails and spam. (=Dịch: Bộ lọc mới giúp chặn các email không mong muốn và thư rác.)","Noise pollution is an [unwanted] side effect of rapid urbanization. (=Dịch: Ô nhiễm tiếng ồn là một tác dụng phụ không mong muốn của quá trình đô thị hóa nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn.%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn.%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_5_401","topic":"Nature and Environmental Protection","word":"vast","pos":"(adj)","ipa":"/væst/","defVi":"rộng lớn, bao la, khổng lồ","defEn":"extremely large in area, size, or amount","examples":["The Sahara Desert covers a [vast] area of northern Africa. (=Dịch: Sa mạc Sahara bao phủ một vùng diện tích rộng lớn ở Bắc Phi.)","A [vast] majority of students supported the new university policy. (=Dịch: Đại đa số sinh viên đã ủng hộ chính sách mới của trường đại học.)","He accumulated a [vast] amount of knowledge through years of reading. (=Dịch: Anh ấy đã tích lũy một lượng kiến thức khổng lồ qua nhiều năm đọc sách.)"],"ukAudio":"/ai_services/tts3/?q=vast&lang=en-GB&ipa=%2Fv%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=vast&lang=en-US&ipa=%2Fv%C3%A6st%2F"},{"id":"lv_5_402","topic":"Nature and Environmental Protection","word":"vegetation","pos":"(n)","ipa":"/ˌvedʒ.əˈteɪ.ʃən/","defVi":"thảm thực vật, cây cỏ","defEn":"plants in general, or the plants found in a particular area","examples":["Dense tropical [vegetation] covers the lower slopes of the mountain. (=Dịch: Thảm thực vật nhiệt đới rậm rạp bao phủ sườn dưới của ngọn núi.)","The desert has very little [vegetation] because of the severe lack of water. (=Dịch: Sa mạc có rất ít thực vật do tình trạng thiếu nước trầm trọng.)","Fires destroyed large areas of native [vegetation] across the national park. (=Dịch: Các vụ cháy đã phá hủy những vùng thảm thực vật bản địa rộng lớn trên khắp vườn quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=vegetation&lang=en-GB&ipa=%2F%CB%8Cved%CA%92.%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetation&lang=en-US&ipa=%2F%CB%8Cved%CA%92.%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_403","topic":"Nature and Environmental Protection","word":"vessel","pos":"(n)","ipa":"/ˈves.əl/","defVi":"tàu thuyền lớn; bình đựng chất lỏng","defEn":"a large boat or ship; or a container designed to hold liquids","examples":["A large cargo [vessel] entered the harbor this morning. (=Dịch: Một chiếc tàu chở hàng lớn đã tiến vào cảng sáng nay.)","Blood [vessels] transport oxygen throughout the human body. (=Dịch: Các mạch máu vận chuyển oxy đi khắp cơ thể con người.)","The ancient ceramic [vessel] was displayed in the museum. (=Dịch: Bình gốm cổ đã được trưng bày trong viện bảo tàng.)"],"ukAudio":"/ai_services/tts3/?q=vessel&lang=en-GB&ipa=%2F%CB%88ves.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vessel&lang=en-US&ipa=%2F%CB%88ves.%C9%99l%2F"},{"id":"lv_5_404","topic":"Nature and Environmental Protection","word":"vet","pos":"(n)","ipa":"/vɛt/","defVi":"bác sĩ thú y","defEn":"a person qualified to treat diseased or injured animals; veterinarian","examples":["We took our sick dog to the [vet] for a checkup. (=Dịch: Chúng tôi đã đưa chú chó bị ốm đến bác sĩ thú y để kiểm tra.)","The [vet] prescribed antibiotics to treat the cat's infection. (=Dịch: Bác sĩ thú y đã kê đơn thuốc kháng sinh để điều trị nhiễm trùng cho con mèo.)","She has wanted to become a [vet] since she was a little girl. (=Dịch: Cô ấy đã muốn trở thành bác sĩ thú y từ khi còn là một cô bé.)"],"ukAudio":"/ai_services/tts3/?q=vet&lang=en-GB&ipa=%2Fv%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=vet&lang=en-US&ipa=%2Fv%C9%9Bt%2F"},{"id":"lv_5_405","topic":"Nature and Environmental Protection","word":"vital","pos":"(adj)","ipa":"/ˈvaɪ.təl/","defVi":"tối quan trọng, có tính sống còn","defEn":"necessary for success, life, or continued existence; extremely important","examples":["Regular exercise plays a [vital] role in maintaining good health. (=Dịch: Tập thể dục đều đặn đóng một vai trò tối quan trọng trong việc duy trì sức khỏe tốt.)","The paramedics checked the patient's [vital] signs immediately. (=Dịch: Các nhân viên y tế đã kiểm tra các dấu hiệu sinh tồn của bệnh nhân ngay lập tức.)","International cooperation is [vital] for tackling climate change. (=Dịch: Hợp tác quốc tế là yếu tố then chốt để giải quyết vấn đề biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=vital&lang=en-GB&ipa=%2F%CB%88va%C9%AA.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vital&lang=en-US&ipa=%2F%CB%88va%C9%AA.t%C9%99l%2F"},{"id":"lv_5_406","topic":"Nature and Environmental Protection","word":"volcanic","pos":"(adj)","ipa":"/vɑːl.ˈkæn.ɪk/","defVi":"thuộc về núi lửa","defEn":"caused by, connected with, or produced by a volcano","examples":["The island was formed millions of years ago by [volcanic] activity. (=Dịch: Hòn đảo này được hình thành hàng triệu năm trước bởi hoạt động của núi lửa.)","Farmers benefit from the rich [volcanic] soil around the mountain. (=Dịch: Nông dân được hưởng lợi từ đất núi lửa màu mỡ xung quanh ngọn núi.)","Scientists closely monitor the [volcanic] crater for any signs of eruption. (=Dịch: Các nhà khoa học theo dõi chặt chẽ miệng núi lửa để phát hiện bất kỳ dấu hiệu phun trào nào.)"],"ukAudio":"/ai_services/tts3/?q=volcanic&lang=en-GB&ipa=%2Fv%C9%91%CB%90l.%CB%88k%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=volcanic&lang=en-US&ipa=%2Fv%C9%91%CB%90l.%CB%88k%C3%A6n.%C9%AAk%2F"},{"id":"lv_5_407","topic":"Nature and Environmental Protection","word":"volcano","pos":"(n)","ipa":"/vɑlˈkeɪ.noʊ/","defVi":"núi lửa","defEn":"a mountain or hill with an opening through which lava, rock fragments, and gas erupt","examples":["The dormant [volcano] has not erupted for hundreds of years. (=Dịch: Ngọn núi lửa không hoạt động này đã không phun trào suốt hàng trăm năm qua.)","Tourists gathered safely to watch the active [volcano] emit smoke. (=Dịch: Du khách đã tụ tập an toàn để ngắm ngọn núi lửa đang hoạt động nhả khói.)","Ash from the [volcano] forced several international airports to close. (=Dịch: Tro bụi từ ngọn núi lửa đã buộc một số sân bay quốc tế phải đóng cửa.)"],"ukAudio":"/ai_services/tts3/?q=volcano&lang=en-GB&ipa=%2Fv%C9%91l%CB%88ke%C9%AA.no%CA%8A%2F","usAudio":"/ai_services/tts3/?q=volcano&lang=en-US&ipa=%2Fv%C9%91l%CB%88ke%C9%AA.no%CA%8A%2F"},{"id":"lv_5_408","topic":"Nature and Environmental Protection","word":"vulnerable","pos":"(adj)","ipa":"/ˈvʌl.nɚ.ə.bəl/","defVi":"dễ bị tổn thương, dễ gặp nguy hiểm","defEn":"susceptible to physical or emotional attack or harm","examples":["Young children and the elderly are particularly [vulnerable] to the flu virus. (=Dịch: Trẻ nhỏ và người cao tuổi đặc biệt dễ bị tổn thương bởi virus cúm.)","Coastal communities are increasingly [vulnerable] to rising sea levels. (=Dịch: Các cộng đồng ven biển ngày càng dễ bị ảnh hưởng trước tình trạng mực nước biển dâng cao.)","The company's computer network was [vulnerable] to cyberattacks. (=Dịch: Mạng máy tính của công ty rất dễ bị tấn công mạng.)"],"ukAudio":"/ai_services/tts3/?q=vulnerable&lang=en-GB&ipa=%2F%CB%88v%CA%8Cl.n%C9%9A.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vulnerable&lang=en-US&ipa=%2F%CB%88v%CA%8Cl.n%C9%9A.%C9%99.b%C9%99l%2F"},{"id":"lv_5_409","topic":"Nature and Environmental Protection","word":"weigh","pos":"(v)","ipa":"/weɪ/","defVi":"cân (trọng lượng), cân nhắc","defEn":"to measure how heavy someone or something is, or to carefully consider something","examples":["The nurse will [weigh] the baby at each check-up. (=Dịch: Y tá sẽ cân em bé vào mỗi lần khám sức khỏe.)","You need to [weigh] the pros and cons before making a career change. (=Dịch: Bạn cần cân nhắc những mặt lợi và hại trước khi chuyển đổi nghề nghiệp.)","The packed suitcase cannot [weigh] more than twenty kilograms. (=Dịch: Chiếc vali đã đóng gói không được nặng quá hai mươi kilôgam.)"],"ukAudio":"/ai_services/tts3/?q=weigh&lang=en-GB&ipa=%2Fwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weigh&lang=en-US&ipa=%2Fwe%C9%AA%2F"},{"id":"lv_5_410","topic":"Nature and Environmental Protection","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪdˌsprɛd/","defVi":"lan rộng, phổ biến","defEn":"existing or happening over a large area or among many people","examples":["The new tax policy caused [widespread] public protest across the country. (=Dịch: Chính sách thuế mới đã gây ra sự phản đối rộng khắp của công chúng trên cả nước.)","Mobile phones have gained [widespread] acceptance as essential daily tools. (=Dịch: Điện thoại di động đã được chấp nhận rộng rãi như những công cụ thiết yếu hàng ngày.)","Deforestation leads to [widespread] loss of biodiversity. (=Dịch: Nạn phá rừng dẫn đến sự mất mát đa dạng sinh học trên diện rộng.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F"},{"id":"lv_5_411","topic":"Nature and Environmental Protection","word":"windy","pos":"(adj)","ipa":"/ˈwɪn.di/","defVi":"lộng gió, nhiều gió","defEn":"marked by strong or high winds","examples":["It was a cold and [windy] afternoon by the seaside. (=Dịch: Đó là một buổi chiều lạnh và nhiều gió bên bờ biển.)","Don't forget to wear a jacket because the weather forecast says it will be [windy]. (=Dịch: Đừng quên mặc áo khoác vì dự báo thời tiết nói trời sẽ nhiều gió.)","The plane landed safely despite the extremely [windy] conditions. (=Dịch: Chiếc máy bay đã hạ cánh an toàn bất chấp điều kiện gió thổi cực mạnh.)"],"ukAudio":"/ai_services/tts3/?q=windy&lang=en-GB&ipa=%2F%CB%88w%C9%AAn.di%2F","usAudio":"/ai_services/tts3/?q=windy&lang=en-US&ipa=%2F%CB%88w%C9%AAn.di%2F"},{"id":"lv_5_412","topic":"Nature and Environmental Protection","word":"wing","pos":"(n)","ipa":"/wɪŋ/","defVi":"Cánh (loài vật hoặc máy bay)","defEn":"One of the parts of the body that a bird, insect, or bat uses for flying, or a similar structure on an aircraft","examples":["The injured bird could not fly because its left [wing] was broken. (=Dịch: Con chim bị thương không thể bay vì cánh trái của nó bị gãy.)","The airplane tipped slightly to the right, dipping one [wing] toward the sea. (=Dịch: Chiếc máy bay hơi nghiêng sang phải, chúi một bên cánh về phía biển.)","A butterfly's [wing] is covered in microscopic scales that create vibrant colors. (=Dịch: Cánh bướm được bao phủ bởi những chiếc vảy siêu nhỏ tạo nên màu sắc rực rỡ.)"],"ukAudio":"/ai_services/tts3/?q=wing&lang=en-GB&ipa=%2Fw%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=wing&lang=en-US&ipa=%2Fw%C9%AA%C5%8B%2F"},{"id":"lv_5_413","topic":"Nature and Environmental Protection","word":"wipe","pos":"(v)","ipa":"/waɪp/","defVi":"lau, chùi","defEn":"to clean or dry something by moving a cloth or hand over it","examples":["Please [wipe] the table after you finish eating. (=Dịch: Làm ơn lau bàn sau khi bạn ăn xong.)","She used a handkerchief to [wipe] her tears. (=Dịch: Cô ấy dùng khăn tay để lau nước mắt.)","Don't forget to [wipe] your feet before entering the house. (=Dịch: Đừng quên chùi chân trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=wipe&lang=en-GB&ipa=%2Fwa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=wipe&lang=en-US&ipa=%2Fwa%C9%AAp%2F"},{"id":"lv_5_414","topic":"Nature and Environmental Protection","word":"wire","pos":"(n)","ipa":"/waɪər/","defVi":"dây kim loại, dây điện","defEn":"a thin, flexible thread of metal used to carry electricity or fasten things","examples":["Be careful not to touch that exposed electrical [wire]. (=Dịch: Hãy cẩn thận đừng chạm vào sợi dây điện bị hở đó.)","The fence was made of strong steel [wire]. (=Dịch: Hàng rào được làm bằng dây thép chắc chắn.)","He used a piece of [wire] to hang the picture on the wall. (=Dịch: Anh ấy đã dùng một đoạn dây kim loại để treo bức tranh lên tường.)"],"ukAudio":"/ai_services/tts3/?q=wire&lang=en-GB&ipa=%2Fwa%C9%AA%C9%99r%2F","usAudio":"/ai_services/tts3/?q=wire&lang=en-US&ipa=%2Fwa%C9%AA%C9%99r%2F"},{"id":"lv_5_415","topic":"Nature and Environmental Protection","word":"wooded","pos":"(adj)","ipa":"/ˈwʊd.ɪd/","defVi":"có nhiều cây cối, rậm rạp cây rừng","defEn":"covered with growing trees or woods","examples":["They decided to go for a peaceful hike along the [wooded] trail. (=Dịch: Họ quyết định đi bộ đường dài yên tĩnh dọc theo con đường mòn rợp bóng cây rừng.)","The cabin was hidden deep in a [wooded] valley. (=Dịch: Túp lều được ẩn sâu trong một thung lũng rậm rạp cây cối.)","Many rare bird species find shelter in these [wooded] hills. (=Dịch: Nhiều loài chim quý hiếm tìm nơi trú ẩn trong những ngọn đồi nhiều cây cối này.)"],"ukAudio":"/ai_services/tts3/?q=wooded&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=wooded&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F"},{"id":"lv_5_416","topic":"Nature and Environmental Protection","word":"woodwork","pos":"(n)","ipa":"/ˈwʊd.wɜrk/","defVi":"đồ gỗ, công việc mộc","defEn":"the parts of a building or room made of wood, or the activity of making items from wood","examples":["The old house features beautiful handcrafted [woodwork]. (=Dịch: Ngôi nhà cổ có các chi tiết đồ gỗ thủ công tuyệt đẹp.)","He decided to take an evening class to learn [woodwork]. (=Dịch: Anh ấy quyết định tham gia một lớp học buổi tối để học làm mộc.)","We need to repaint the [woodwork] around the window frames. (=Dịch: Chúng tôi cần sơn lại phần khung gỗ quanh các cửa sổ.)"],"ukAudio":"/ai_services/tts3/?q=woodwork&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.w%C9%9Crk%2F","usAudio":"/ai_services/tts3/?q=woodwork&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.w%C9%9Crk%2F"},{"id":"lv_5_417","topic":"Nature and Environmental Protection","word":"woolly","pos":"(adj)","ipa":"/ˈwʊl.i/","defVi":"làm bằng len, có lông như len; mơ hồ (ý nghĩ)","defEn":"made of or resembling wool; vague or unclear in thinking","examples":["She wore a warm [woolly] scarf to protect herself from the winter cold. (=Dịch: Cô ấy đã quàng một chiếc khăn len ấm áp để bảo vệ mình khỏi cái lạnh mùa đông.)","The sheep had thick, [woolly] coats after a season on the pasture. (=Dịch: Những con cừu có bộ lông len dày sau một mùa trên đồng cỏ.)","His argument was too [woolly] to convince the examination panel. (=Dịch: Lập luận của anh ấy quá mơ hồ để có thể thuyết phục được hội đồng chấm thi.)"],"ukAudio":"/ai_services/tts3/?q=woolly&lang=en-GB&ipa=%2F%CB%88w%CA%8Al.i%2F","usAudio":"/ai_services/tts3/?q=woolly&lang=en-US&ipa=%2F%CB%88w%CA%8Al.i%2F"},{"id":"lv_5_418","topic":"Nature and Environmental Protection","word":"worm","pos":"(n)","ipa":"/wɜːrm/","defVi":"con giun, sâu","defEn":"a small animal with a long, soft body and no legs, often living underground","examples":["Birds often look for a [worm] in the grass after the rain. (=Dịch: Chim thường tìm giun trong bãi cỏ sau cơn mưa.)","The gardener noticed a [worm] wriggling through the rich soil. (=Dịch: Người làm vườn nhận thấy một con giun đang ngoe nguẩy trong lớp đất màu mỡ.)","Fishermen frequently use a [worm] as bait to catch freshwater fish. (=Dịch: Những người câu cá thường dùng giun làm mồi để bắt cá nước ngọt.)"],"ukAudio":"/ai_services/tts3/?q=worm&lang=en-GB&ipa=%2Fw%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=worm&lang=en-US&ipa=%2Fw%C9%9C%CB%90rm%2F"},{"id":"lv_5_419","topic":"Nature and Environmental Protection","word":"yam","pos":"(n)","ipa":"/jæm/","defVi":"củ khoai mỡ, củ từ hoặc khoai lang","defEn":"an edible starchy root of a climbing plant, often similar to a sweet potato","examples":["Roasted [yam] is a popular side dish in many traditional autumn meals. (=Dịch: Khoai mỡ nướng là một món ăn kèm phổ biến trong nhiều bữa ăn mùa thu truyền thống.)","The farmer harvested a large crop of [yam] before the rainy season began. (=Dịch: Người nông dân đã thu hoạch một vụ mùa củ từ lớn trước khi mùa mưa bắt đầu.)","She made a delicious dessert using mashed [yam] and coconut milk. (=Dịch: Cô ấy đã làm một món tráng miệng thơm ngon bằng khoai mỡ nghiền và nước cốt dừa.)"],"ukAudio":"/ai_services/tts3/?q=yam&lang=en-GB&ipa=%2Fj%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=yam&lang=en-US&ipa=%2Fj%C3%A6m%2F"},{"id":"lv_5_420","topic":"Nature and Environmental Protection","word":"zero","pos":"(n)","ipa":"/ˈzɪr.oʊ/","defVi":"số không, không có gì","defEn":"the number 0, or an amount that is none at all","examples":["The temperature dropped to [zero] degrees last night. (=Dịch: Nhiệt độ đã giảm xuống mức không độ vào đêm qua.)","He started the business with [zero] experience in sales. (=Dịch: Anh ấy bắt đầu công việc kinh doanh với con số không về kinh nghiệm bán hàng.)","Our chances of winning the game are close to [zero]. (=Dịch: Cơ hội chiến thắng trận đấu của chúng tôi gần như bằng không.)"],"ukAudio":"/ai_services/tts3/?q=zero&lang=en-GB&ipa=%2F%CB%88z%C9%AAr.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=zero&lang=en-US&ipa=%2F%CB%88z%C9%AAr.o%CA%8A%2F"},{"id":"lv_5_421","topic":"Nature and Environmental Protection","word":"zone","pos":"(n)","ipa":"/zoʊn/","defVi":"khu vực, vành đai, vùng","defEn":"an area with particular characteristics or purpose","examples":["Drivers must slow down when entering a school [zone]. (=Dịch: Các tài xế phải giảm tốc độ khi đi vào khu vực trường học.)","The city created a pedestrian [zone] in the historic center. (=Dịch: Thành phố đã tạo ra một phố đi bộ ở trung tâm lịch sử.)","Plants grow differently depending on their climate [zone]. (=Dịch: Cây cối phát triển khác nhau tùy thuộc vào đới khí hậu của chúng.)"],"ukAudio":"/ai_services/tts3/?q=zone&lang=en-GB&ipa=%2Fzo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=zone&lang=en-US&ipa=%2Fzo%CA%8An%2F"},{"id":"lv_6_0","topic":"Business and Humanities Studies","word":"absence","pos":"(n)","ipa":"/ˈæb.səns/","defVi":"sự vắng mặt, sự thiếu vắng","defEn":"the state of being away from a place or not existing","examples":["Repeated [absence] from classes will negatively affect your final grade. (=Dịch: Việc vắng mặt nhiều lần trong các buổi học sẽ ảnh hưởng xấu đến điểm số cuối kỳ của bạn.)","In the [absence] of more evidence, the police could not proceed with the case. (=Dịch: Do thiếu bằng chứng, cảnh sát đã không thể tiếp tục vụ án.)","Her long [absence] made her realize how much she missed her family. (=Dịch: Sự xa cách lâu ngày khiến cô nhận ra mình nhớ gia đình đến nhường nào.)"],"ukAudio":"/ai_services/tts3/?q=absence&lang=en-GB&ipa=%2F%CB%88%C3%A6b.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=absence&lang=en-US&ipa=%2F%CB%88%C3%A6b.s%C9%99ns%2F"},{"id":"lv_6_1","topic":"Business and Humanities Studies","word":"acquire","pos":"(v)","ipa":"/əˈkwaɪ.ɚ/","defVi":"đạt được, thu được, mua lại","defEn":"to gain, get, or obtain something through effort or purchase","examples":["Living abroad helped her [acquire] fluent English skills. (=Dịch: Sống ở nước ngoài đã giúp cô ấy tiếp thu được khả năng tiếng Anh lưu loát.)","The tech giant plans to [acquire] a promising startup. (=Dịch: Tập đoàn công nghệ lớn dự định mua lại một công ty khởi nghiệp đầy triển vọng.)","It takes patience to [acquire] in-depth knowledge of finance. (=Dịch: Cần có sự kiên nhẫn để tích lũy kiến thức sâu rộng về tài chính.)"],"ukAudio":"/ai_services/tts3/?q=acquire&lang=en-GB&ipa=%2F%C9%99%CB%88kwa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=acquire&lang=en-US&ipa=%2F%C9%99%CB%88kwa%C9%AA.%C9%9A%2F"},{"id":"lv_6_2","topic":"Business and Humanities Studies","word":"administrator","pos":"(n)","ipa":"/ədˈmɪn.ə.streɪ.t̬ɚ/","defVi":"quản trị viên, người quản lý","defEn":"a person whose job is to manage and organize the work of a company or organization","examples":["The school [administrator] introduced several new policies this semester. (=Dịch: Người quản lý trường học đã đưa ra một số chính sách mới trong học kỳ này.)","Please contact the system [administrator] if you cannot log into your account. (=Dịch: Vui lòng liên hệ với quản trị viên hệ thống nếu bạn không thể đăng nhập vào tài khoản của mình.)","She has worked as a hospital [administrator] for over a decade. (=Dịch: Cô ấy đã làm việc với tư cách là người quản lý bệnh viện trong hơn một thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=administrator&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=administrator&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_6_3","topic":"Business and Humanities Studies","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"chấp nhận, áp dụng, thông qua (kế hoạch/phương pháp)","defEn":"to choose to follow or use a particular idea, method, or policy","examples":["Many schools plan to [adopt] modern technology in their classrooms next year. (=Dịch: Nhiều trường học dự định áp dụng công nghệ hiện đại vào lớp học vào năm tới.)","The government decided to [adopt] stricter environmental regulations. (=Dịch: Chính phủ đã quyết định thông qua các quy định môi trường nghiêm ngặt hơn.)","You should [adopt] a healthier diet to improve your overall wellbeing. (=Dịch: Bạn nên áp dụng một chế độ ăn uống lành mạnh hơn để nâng cao sức khỏe toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_6_4","topic":"Business and Humanities Studies","word":"affair","pos":"(n)","ipa":"/əˈfer/","defVi":"sự việc, công việc, vấn đề","defEn":"an event, situation, or matter of public or personal concern","examples":["The Ministry of Foreign Affairs deals with international diplomatic relations. (=Dịch: Bộ Ngoại giao xử lý các mối quan hệ ngoại giao quốc tế.)","The wedding was a lavish [affair] attended by hundreds of guests. (=Dịch: Lễ cưới là một sự kiện xa hoa với sự tham dự của hàng trăm khách mời.)","She prefers to keep her private life a personal [affair]. (=Dịch: Cô ấy thích giữ đời sống riêng tư là chuyện cá nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=affair&lang=en-GB&ipa=%2F%C9%99%CB%88fer%2F","usAudio":"/ai_services/tts3/?q=affair&lang=en-US&ipa=%2F%C9%99%CB%88fer%2F"},{"id":"lv_6_5","topic":"Business and Humanities Studies","word":"allocate","pos":"(v)","ipa":"/ˈæl.ə.keɪt/","defVi":"phân bổ, phân chia (ngân sách, nguồn lực)","defEn":"to officially give something to someone, or to decide that something will be used for a specific purpose","examples":["The local government decided to [allocate] more funds to public healthcare. (=Dịch: Chính quyền địa phương đã quyết định phân bổ thêm kinh phí cho y tế công cộng.)","Project managers must carefully [allocate] resources to ensure deadlines are met. (=Dịch: Các nhà quản lý dự án phải phân bổ nguồn lực một cách cẩn thận để đảm bảo đúng tiến độ.)","We need to [allocate] specific duties to each team member before starting the campaign. (=Dịch: Chúng ta cần phân công nhiệm vụ cụ thể cho từng thành viên trong nhóm trước khi bắt đầu chiến dịch.)"],"ukAudio":"/ai_services/tts3/?q=allocate&lang=en-GB&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=allocate&lang=en-US&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F"},{"id":"lv_6_6","topic":"Business and Humanities Studies","word":"ant","pos":"(n)","ipa":"/ænt/","defVi":"con kiến","defEn":"a small insect that lives in highly organized social colonies","examples":["A tiny [ant] can carry objects many times heavier than its own body. (=Dịch: Một con kiến nhỏ bé có thể vác những vật nặng gấp nhiều lần cơ thể nó.)","We noticed a trail of [ant]s marching toward the spilled sugar on the table. (=Dịch: Chúng tôi nhận thấy một hàng kiến đang bò về phía chỗ đường bị đổ trên bàn.)","The behavior of an [ant] colony is often studied by biologists to understand teamwork. (=Dịch: Hành vi của một đàn kiến thường được các nhà sinh vật học nghiên cứu để hiểu về sự làm việc nhóm.)"],"ukAudio":"/ai_services/tts3/?q=ant&lang=en-GB&ipa=%2F%C3%A6nt%2F","usAudio":"/ai_services/tts3/?q=ant&lang=en-US&ipa=%2F%C3%A6nt%2F"},{"id":"lv_6_7","topic":"Business and Humanities Studies","word":"anxiety","pos":"(n)","ipa":"/æŋˈzaɪ.ə.t̬i/","defVi":"sự lo âu, nỗi lo lắng","defEn":"a feeling of worry, nervousness, or unease about something","examples":["Many students suffer from acute [anxiety] before taking major exams. (=Dịch: Nhiều học sinh phải chịu đựng nỗi lo âu tột độ trước khi bước vào các kỳ thi lớn.)","Regular exercise is an effective way to reduce stress and [anxiety]. (=Dịch: Tập thể dục thường xuyên là một cách hiệu quả để giảm bớt căng thẳng và lo lắng.)","Her [anxiety] grew as the deadline for the final project approached. (=Dịch: Nỗi lo của cô ấy ngày càng tăng khi hạn chót nộp dự án cuối kỳ đến gần.)"],"ukAudio":"/ai_services/tts3/?q=anxiety&lang=en-GB&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=anxiety&lang=en-US&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.t%CC%ACi%2F"},{"id":"lv_6_8","topic":"Business and Humanities Studies","word":"ape","pos":"(n)","ipa":"/eɪp/","defVi":"loài vượn, loài linh trưởng không đuôi","defEn":"a large primate without a tail, such as a chimpanzee, gorilla, or orangutan","examples":["The chimpanzee is considered one of the most intelligent species of [ape]. (=Dịch: Tinh tinh được coi là một trong những loài vượn thông minh nhất.)","Scientists study the behavior of the [ape] to learn more about human evolution. (=Dịch: Các nhà khoa học nghiên cứu hành vi của loài vượn để tìm hiểu thêm về sự tiến hóa của loài người.)","The sanctuary provides a safe natural habitat for rescued [ape]s. (=Dịch: Khu bảo tồn cung cấp một môi trường sống tự nhiên an toàn cho những cá thể vượn được giải cứu.)"],"ukAudio":"/ai_services/tts3/?q=ape&lang=en-GB&ipa=%2Fe%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=ape&lang=en-US&ipa=%2Fe%C9%AAp%2F"},{"id":"lv_6_9","topic":"Business and Humanities Studies","word":"arena","pos":"(n)","ipa":"/əˈriː.nə/","defVi":"đấu trường, vũ đài","defEn":"a level area surrounded by seating, used for sports or entertainment, or a sphere of activity","examples":["Thousands of fans gathered at the sports [arena] to watch the final match. (=Dịch: Hàng ngàn người hâm mộ đã tập trung tại nhà thi đấu thể thao để xem trận chung kết.)","She is preparing to enter the political [arena] in the upcoming election. (=Dịch: Cô ấy đang chuẩn bị bước vào vũ đài chính trị trong cuộc bầu cử sắp tới.)","The new indoor [arena] will host international music concerts. (=Dịch: Nhà thi đấu trong nhà mới sẽ là nơi tổ chức các buổi hòa nhạc quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=arena&lang=en-GB&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=arena&lang=en-US&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F"},{"id":"lv_6_10","topic":"Business and Humanities Studies","word":"arise","pos":"(v)","ipa":"/əˈraɪz/","defVi":"nảy sinh, phát sinh","defEn":"to happen or begin to exist, especially a problem or situation","examples":["Unexpected problems can [arise] during the early stages of a project. (=Dịch: Những vấn đề bất ngờ có thể phát sinh trong các giai đoạn đầu của một dự án.)","New opportunities often [arise] when you step outside your comfort zone. (=Dịch: Những cơ hội mới thường xuất hiện khi bạn bước ra khỏi vùng an toàn của mình.)","Disputes may [arise] if the terms of the contract are not clear. (=Dịch: Tranh chấp có thể nảy sinh nếu các điều khoản của hợp đồng không rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=arise&lang=en-GB&ipa=%2F%C9%99%CB%88ra%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=arise&lang=en-US&ipa=%2F%C9%99%CB%88ra%C9%AAz%2F"},{"id":"lv_6_11","topic":"Business and Humanities Studies","word":"assess","pos":"(v)","ipa":"/əˈsɛs/","defVi":"đánh giá, định mức","defEn":"to judge or decide the amount, value, quality, or importance of something","examples":["The committee will [assess] the environmental impact of the new highway project. (=Dịch: Ủy ban sẽ đánh giá tác động môi trường của dự án đường cao tốc mới.)","Teachers use regular tests to [assess] students' progress throughout the semester. (=Dịch: Giáo viên sử dụng các bài kiểm tra định kỳ để đánh giá sự tiến bộ của học sinh trong suốt học kỳ.)","It is difficult to [assess] the true cost of the damage caused by the flood. (=Dịch: Rất khó để đánh giá thiệt hại thực tế do trận lũ lụt gây ra.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F"},{"id":"lv_6_12","topic":"Business and Humanities Studies","word":"assist","pos":"(v)","ipa":"/əˈsɪst/","defVi":"giúp đỡ, hỗ trợ","defEn":"to help someone to do something","examples":["The teacher will [assist] students who are struggling with math. (=Dịch: Giáo viên sẽ giúp đỡ những học sinh đang gặp khó khăn với môn toán.)","Smart software can [assist] doctors in diagnosing rare diseases. (=Dịch: Phần mềm thông minh có thể hỗ trợ các bác sĩ trong việc chẩn đoán các căn bệnh hiếm gặp.)","Volunteers arrived at the scene to [assist] with the rescue operation. (=Dịch: Các tình nguyện viên đã đến hiện trường để hỗ trợ công tác cứu hộ.)"],"ukAudio":"/ai_services/tts3/?q=assist&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=assist&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%AAst%2F"},{"id":"lv_6_13","topic":"Business and Humanities Studies","word":"assumption","pos":"(n)","ipa":"/əˈsʌmp.ʃən/","defVi":"giả định, sự suy đoán","defEn":"something that you accept as true without having proof","examples":["His business plan was based on the false [assumption] that prices would stay low. (=Dịch: Kế hoạch kinh doanh của anh ấy dựa trên giả định sai lầm rằng giá cả sẽ duy trì ở mức thấp.)","We should not make any [assumptions] before reviewing all the evidence. (=Dịch: Chúng ta không nên đưa ra bất kỳ giả định nào trước khi xem xét mọi bằng chứng.)","The research challenges the traditional [assumption] about how memory works. (=Dịch: Nghiên cứu này thách thức giả định truyền thống về cách hoạt động của trí nhớ.)"],"ukAudio":"/ai_services/tts3/?q=assumption&lang=en-GB&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=assumption&lang=en-US&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_6_14","topic":"Business and Humanities Studies","word":"autism","pos":"(n)","ipa":"/ˈɔˌtɪz.əm/","defVi":"chứng tự kỷ","defEn":"a brain condition that affects how a person communicates and interacts with others","examples":["Children with [autism] often find social interaction challenging. (=Dịch: Trẻ mắc chứng tự kỷ thường cảm thấy việc tương tác xã hội là một thử thách.)","Early diagnosis of [autism] can significantly improve a child's development. (=Dịch: Việc chẩn đoán sớm chứng tự kỷ có thể cải thiện đáng kể sự phát triển của trẻ.)","The charity aims to raise awareness about [autism] in schools. (=Dịch: Tổ chức từ thiện nhằm nâng cao nhận thức về chứng tự kỷ trong các trường học.)"],"ukAudio":"/ai_services/tts3/?q=autism&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%8Ct%C9%AAz.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=autism&lang=en-US&ipa=%2F%CB%88%C9%94%CB%8Ct%C9%AAz.%C9%99m%2F"},{"id":"lv_6_15","topic":"Business and Humanities Studies","word":"belief","pos":"(n)","ipa":"/bɪˈlif/","defVi":"niềm tin, tín ngưỡng","defEn":"an acceptance that something exists or is true, especially without proof","examples":["It is a common [belief] that eating healthy food improves mental health. (=Dịch: Mọi người thường có niềm tin rằng ăn uống lành mạnh sẽ cải thiện sức khỏe tinh thần.)","His religious [belief] guides all his moral decisions in life. (=Dịch: Tín ngưỡng tôn giáo dẫn đường cho mọi quyết định đạo đức của anh ấy trong cuộc sống.)","She has a firm [belief] in her ability to succeed despite the odds. (=Dịch: Cô ấy có niềm tin vững chắc vào khả năng thành công của mình bất chấp mọi khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=belief&lang=en-GB&ipa=%2Fb%C9%AA%CB%88lif%2F","usAudio":"/ai_services/tts3/?q=belief&lang=en-US&ipa=%2Fb%C9%AA%CB%88lif%2F"},{"id":"lv_6_16","topic":"Business and Humanities Studies","word":"beneficial","pos":"(adj)","ipa":"/ˌben.əˈfɪʃ.əl/","defVi":"có lợi, hữu ích","defEn":"having a good or helpful effect on someone or something","examples":["Regular physical activity is highly [beneficial] for cardiovascular health. (=Dịch: Hoạt động thể chất thường xuyên rất có lợi cho sức khỏe tim mạch.)","The trade agreement proved [beneficial] to both participating nations. (=Dịch: Hiệp định thương mại đã chứng minh là có lợi cho cả hai quốc gia tham gia.)","Learning a second language is [beneficial] for cognitive development. (=Dịch: Học ngôn ngữ thứ hai rất hữu ích cho sự phát triển nhận thức.)"],"ukAudio":"/ai_services/tts3/?q=beneficial&lang=en-GB&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=beneficial&lang=en-US&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_6_17","topic":"Business and Humanities Studies","word":"blame","pos":"(v)","ipa":"/bleɪm/","defVi":"đổ lỗi, khiển trách, quy trách nhiệm","defEn":"to hold someone or something responsible for a fault or wrong action","examples":["Don't [blame] him for a mistake he did not make. (=Dịch: Đừng đổ lỗi cho anh ấy về một sai lầm mà anh ấy không phạm phải.)","Many scientists [blame] human activity for the rapid climate change. (=Dịch: Nhiều nhà khoa học quy trách nhiệm cho hoạt động của con người về sự biến đổi khí hậu nhanh chóng.)","She refused to [blame] others when the project failed. (=Dịch: Cô ấy từ chối đổ lỗi cho người khác khi dự án thất bại.)"],"ukAudio":"/ai_services/tts3/?q=blame&lang=en-GB&ipa=%2Fble%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=blame&lang=en-US&ipa=%2Fble%C9%AAm%2F"},{"id":"lv_6_18","topic":"Business and Humanities Studies","word":"blanket","pos":"(n)","ipa":"/ˈblæŋ.kɪt/","defVi":"chăn, mền","defEn":"a large piece of warm fabric used as a covering on a bed","examples":["She wrapped a warm [blanket] around her shoulders because the room was cold. (=Dịch: Cô ấy quàng một chiếc chăn ấm qua vai vì căn phòng rất lạnh.)","A thick [blanket] of snow covered the entire village overnight. (=Dịch: Một lớp tuyết dày đã bao phủ toàn bộ ngôi làng qua đêm.)","We spread a picnic [blanket] on the grass and enjoyed our lunch. (=Dịch: Chúng tôi trải một tấm thảm dã ngoại trên bãi cỏ và thưởng thức bữa trưa.)"],"ukAudio":"/ai_services/tts3/?q=blanket&lang=en-GB&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=blanket&lang=en-US&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F"},{"id":"lv_6_19","topic":"Business and Humanities Studies","word":"brand","pos":"(n)","ipa":"/brænd/","defVi":"thương hiệu, nhãn hàng","defEn":"a type of product made by a particular company under a particular name","examples":["Apple is one of the most recognizable [brand] names in the world. (=Dịch: Apple là một trong những tên thương hiệu dễ nhận biết nhất trên thế giới.)","Consumers often stay loyal to a trusted [brand] despite price increases. (=Dịch: Người tiêu dùng thường trung thành với một thương hiệu đáng tin cậy dù giá có tăng.)","The company is launching a new [brand] of organic skincare products. (=Dịch: Công ty đang ra mắt một dòng nhãn hàng mỹ phẩm hữu cơ mới.)"],"ukAudio":"/ai_services/tts3/?q=brand&lang=en-GB&ipa=%2Fbr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=brand&lang=en-US&ipa=%2Fbr%C3%A6nd%2F"},{"id":"lv_6_20","topic":"Business and Humanities Studies","word":"calculate","pos":"(v)","ipa":"/ˈkæl.kjə.leɪt/","defVi":"tính toán, dự liệu","defEn":"to determine something mathematically or evaluate an outcome carefully","examples":["You can use this online tool to [calculate] your monthly mortgage payments. (=Dịch: Bạn có thể sử dụng công cụ trực tuyến này để tính toán các khoản thanh toán thế chấp hàng tháng của mình.)","Scientists are trying to [calculate] the exact trajectory of the asteroid. (=Dịch: Các nhà khoa học đang cố gắng tính toán quỹ đạo chính xác của tiểu hành tinh.)","The manager took time to [calculate] the potential risks before approving the project. (=Dịch: Người quản lý đã dành thời gian để tính toán những rủi ro tiềm ẩn trước khi phê duyệt dự án.)"],"ukAudio":"/ai_services/tts3/?q=calculate&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.kj%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=calculate&lang=en-US&ipa=%2F%CB%88k%C3%A6l.kj%C9%99.le%C9%AAt%2F"},{"id":"lv_6_21","topic":"Business and Humanities Studies","word":"campsite","pos":"(n)","ipa":"/ˈkæmp.saɪt/","defVi":"khu cắm trại, địa điểm cắm trại","defEn":"a piece of land where people on holiday can pitch a tent or park a camper","examples":["We found a peaceful [campsite] near the edge of the lake. (=Dịch: Chúng tôi tìm thấy một địa điểm cắm trại yên bình gần bờ hồ.)","The [campsite] offers basic facilities such as running water and showers. (=Dịch: Khu cắm trại cung cấp các tiện nghi cơ bản như nước máy và phòng tắm vòi sen.)","You need to book your spot at the [campsite] several months in advance. (=Dịch: Bạn cần phải đặt chỗ tại khu cắm trại trước vài tháng.)"],"ukAudio":"/ai_services/tts3/?q=campsite&lang=en-GB&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=campsite&lang=en-US&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F"},{"id":"lv_6_22","topic":"Business and Humanities Studies","word":"caring","pos":"(adj)","ipa":"/ˈker.ɪŋ/","defVi":"chu đáo, giàu lòng quan tâm chăm sóc","defEn":"kind, affectionate, and showing concern for the needs of others","examples":["She is a [caring] teacher who always pays attention to her students' feelings. (=Dịch: Cô ấy là một giáo viên chu đáo, luôn để ý đến cảm xúc của học sinh.)","The elderly woman was grateful for her [caring] neighbors. (=Dịch: Bà cụ rất biết ơn những người hàng xóm biết quan tâm giúp đỡ của mình.)","Working in healthcare requires a patient and [caring] attitude. (=Dịch: Làm việc trong ngành y tế đòi hỏi một thái độ kiên nhẫn và giàu tình thương.)"],"ukAudio":"/ai_services/tts3/?q=caring&lang=en-GB&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=caring&lang=en-US&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F"},{"id":"lv_6_23","topic":"Business and Humanities Studies","word":"category","pos":"(n)","ipa":"/ˈkæ.t̬ə.ɡɔːr.i/","defVi":"hạng, loại, nhóm","defEn":"a class or division of people or things having particular shared characteristics","examples":["The competition is divided into three age [category] groups. (=Dịch: Cuộc thi được chia thành ba nhóm theo hạng tuổi.)","Books in the library are arranged neatly by [category]. (=Dịch: Sách trong thư viện được sắp xếp ngăn nắp theo từng thể loại.)","This documentary falls into the [category] of environmental science. (=Dịch: Bộ phim tài liệu này thuộc thể loại khoa học môi trường.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6.t%CC%AC%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6.t%CC%AC%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_6_24","topic":"Business and Humanities Studies","word":"cell","pos":"(n)","ipa":"/sɛl/","defVi":"tế bào","defEn":"the smallest basic unit of a plant or animal","examples":["The microscope allowed the students to see a single plant [cell] clearly. (=Dịch: Kính hiển vi đã cho phép học sinh nhìn thấy rõ một tế bào thực vật đơn lẻ.)","Cancer occurs when an abnormal [cell] begins to divide uncontrollably. (=Dịch: Ung thư xảy ra khi một tế bào bất thường bắt đầu phân chia mất kiểm soát.)","Red blood [cell] production takes place mainly inside the bone marrow. (=Dịch: Quá trình sản sinh tế bào hồng cầu diễn ra chủ yếu bên trong tủy xương.)"],"ukAudio":"/ai_services/tts3/?q=cell&lang=en-GB&ipa=%2Fs%C9%9Bl%2F","usAudio":"/ai_services/tts3/?q=cell&lang=en-US&ipa=%2Fs%C9%9Bl%2F"},{"id":"lv_6_25","topic":"Business and Humanities Studies","word":"ceo","pos":"(n)","ipa":"/ˌsiː.iːˈoʊ/","defVi":"tổng giám đốc điều hành","defEn":"the highest-ranking person in a company or other institution","examples":["The [CEO] announced a major restructuring plan during the annual meeting. (=Dịch: Tổng giám đốc điều hành đã công bố kế hoạch tái cấu trúc lớn trong cuộc họp thường niên.)","She worked her way up through the ranks to become the company's first female [CEO]. (=Dịch: Cô đã nỗ lực thăng tiến qua nhiều vị trí để trở thành nữ tổng giám đốc điều hành đầu tiên của công ty.)","Investors questioned the [CEO] about falling profits in the latest quarter. (=Dịch: Các nhà đầu tư đã chất vấn tổng giám đốc điều hành về sự sụt giảm lợi nhuận trong quý gần nhất.)"],"ukAudio":"/ai_services/tts3/?q=ceo&lang=en-GB&ipa=%2F%CB%8Csi%CB%90.i%CB%90%CB%88o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=ceo&lang=en-US&ipa=%2F%CB%8Csi%CB%90.i%CB%90%CB%88o%CA%8A%2F"},{"id":"lv_6_26","topic":"Business and Humanities Studies","word":"characteristic","pos":"(n)","ipa":"/ˌker.ək.təˈrɪs.tɪk/","defVi":"đặc điểm, nét đặc trưng","defEn":"a typical feature or quality that someone or something has","examples":["Patience is an essential [characteristic] of a good teacher. (=Dịch: Kiên nhẫn là một đặc điểm thiết yếu của một giáo viên giỏi.)","A common [characteristic] of this disease is extreme fatigue. (=Dịch: Một đặc điểm chung của căn bệnh này là tình trạng mệt mỏi cùng cực.)","Each region has its own architectural [characteristic] that reflects its heritage. (=Dịch: Mỗi vùng miền đều có nét đặc trưng kiến trúc riêng phản ánh di sản của nơi đó.)"],"ukAudio":"/ai_services/tts3/?q=characteristic&lang=en-GB&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=characteristic&lang=en-US&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F"},{"id":"lv_6_27","topic":"Business and Humanities Studies","word":"chief","pos":"(adj)","ipa":"/tʃiːf/","defVi":"chính, chủ yếu, quan trọng nhất","defEn":"most important or main","examples":["Unemployment was the [chief] topic of discussion at the economic summit. (=Dịch: Thất nghiệp là chủ đề thảo luận chính tại hội nghị thượng đỉnh kinh tế.)","The [chief] cause of air pollution in the city is heavy traffic. (=Dịch: Nguyên nhân chủ yếu gây ô nhiễm không khí trong thành phố là lưu lượng giao thông đông đúc.)","Her [chief] responsibility is to oversee daily operations in the factory. (=Dịch: Trách nhiệm chính của cô ấy là giám sát các hoạt động hàng ngày trong nhà máy.)"],"ukAudio":"/ai_services/tts3/?q=chief&lang=en-GB&ipa=%2Ft%CA%83i%CB%90f%2F","usAudio":"/ai_services/tts3/?q=chief&lang=en-US&ipa=%2Ft%CA%83i%CB%90f%2F"},{"id":"lv_6_28","topic":"Business and Humanities Studies","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with thinking, understanding, and mental processes","examples":["Puzzles and games can help maintain good [cognitive] function in older adults. (=Dịch: Các câu đố và trò chơi có thể giúp duy trì chức năng nhận thức tốt ở người lớn tuổi.)","Reading regularly contributes significantly to a child's [cognitive] development. (=Dịch: Đọc sách thường xuyên đóng góp đáng kể vào sự phát triển nhận thức của trẻ.)","The test measures various [cognitive] skills such as memory and attention. (=Dịch: Bài kiểm tra đo lường các kỹ năng nhận thức khác nhau như trí nhớ và sự chú ý.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_6_29","topic":"Business and Humanities Studies","word":"collaboration","pos":"(n)","ipa":"/kəˌlæb.əˈreɪ.ʃən/","defVi":"sự cộng tác, sự hợp tác","defEn":"the act of working together with other people or organizations to produce something","examples":["The project was successful thanks to close [collaboration] between both teams. (=Dịch: Dự án đã thành công nhờ vào sự hợp tác chặt chẽ giữa hai đội ngũ.)","The new song is a creative [collaboration] between two famous musicians. (=Dịch: Bài hát mới là một sự cộng tác sáng tạo giữa hai nhạc sĩ nổi tiếng.)","International [collaboration] is essential to solve global environmental issues. (=Dịch: Sự hợp tác quốc tế là rất cần thiết để giải quyết các vấn đề môi trường toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=collaboration&lang=en-GB&ipa=%2Fk%C9%99%CB%8Cl%C3%A6b.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=collaboration&lang=en-US&ipa=%2Fk%C9%99%CB%8Cl%C3%A6b.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_30","topic":"Business and Humanities Studies","word":"combination","pos":"(n)","ipa":"/ˌkɑːm.bəˈneɪ.ʃən/","defVi":"sự kết hợp, sự phối hợp","defEn":"the result of joining two or more things together","examples":["The dish is a delightful [combination] of sweet and spicy flavours. (=Dịch: Món ăn này là một sự kết hợp thú vị giữa hương vị ngọt và cay.)","Success in learning requires a [combination] of hard work and good strategies. (=Dịch: Thành công trong học tập đòi hỏi sự kết hợp giữa nỗ lực chăm chỉ và chiến lược tốt.)","He forgot the secret [combination] needed to open the safe. (=Dịch: Anh ấy đã quên mất mã số kết hợp bí mật để mở chiếc két sắt.)"],"ukAudio":"/ai_services/tts3/?q=combination&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.b%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=combination&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.b%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_31","topic":"Business and Humanities Studies","word":"comfort","pos":"(n)","ipa":"/ˈkʌm.fɚt/","defVi":"sự thoải mái, sự an ủi, tiện nghi","defEn":"a state of physical ease and freedom from pain or anxiety","examples":["The modern hotel offers both luxury and [comfort] to its guests. (=Dịch: Khách sạn hiện đại này mang lại cả sự sang trọng lẫn thoải mái cho du khách.)","She found great [comfort] in talking to her closest friend during hard times. (=Dịch: Cô ấy tìm thấy sự an ủi lớn khi tâm sự với người bạn thân nhất trong những lúc khó khăn.)","Traveling in first class provides a much higher level of [comfort]. (=Dịch: Đi du lịch ở khoang hạng nhất mang lại mức độ tiện nghi cao hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=comfort&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.f%C9%9At%2F","usAudio":"/ai_services/tts3/?q=comfort&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.f%C9%9At%2F"},{"id":"lv_6_32","topic":"Business and Humanities Studies","word":"command","pos":"(n)","ipa":"/kəˈmænd/","defVi":"mệnh lệnh, chỉ thị","defEn":"an authoritative order or directive given to someone","examples":["The soldiers waited patiently for the general's next [command]. (=Dịch: Các binh sĩ kiên nhẫn chờ đợi mệnh lệnh tiếp theo của vị tướng.)","He gave a clear [command] to stop all construction work immediately. (=Dịch: Ông ấy đã đưa ra một mệnh lệnh rõ ràng yêu cầu dừng ngay lập tức mọi công việc xây dựng.)","The dog obeys every [command] given by its trainer. (=Dịch: Chú chó tuân theo mọi mệnh lệnh do người huấn luyện đưa ra.)"],"ukAudio":"/ai_services/tts3/?q=command&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=command&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C3%A6nd%2F"},{"id":"lv_6_33","topic":"Business and Humanities Studies","word":"commit","pos":"(v)","ipa":"/kəˈmɪt/","defVi":"cam kết, gắn bó hoặc cống hiến","defEn":"to promise or dedicate oneself to a particular course of action or relationship","examples":["The company decided to [commit] more resources to scientific research. (=Dịch: Công ty đã quyết định cam kết dành nhiều nguồn lực hơn cho nghiên cứu khoa học.)","He was not ready to [commit] to a long-term contract. (=Dịch: Anh ấy chưa sẵn sàng cam kết với một hợp đồng dài hạn.)","Both countries agreed to [commit] to reducing carbon emissions. (=Dịch: Cả hai quốc gia đã đồng ý cam kết cắt giảm lượng khí thải carbon.)"],"ukAudio":"/ai_services/tts3/?q=commit&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=commit&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt%2F"},{"id":"lv_6_34","topic":"Business and Humanities Studies","word":"comparison","pos":"(n)","ipa":"/kəmˈpær.ə.sən/","defVi":"sự so sánh","defEn":"the act of considering the similarities and differences between two or more things","examples":["A [comparison] between the two smartphones shows only minor differences. (=Dịch: Một sự so sánh giữa hai chiếc điện thoại thông minh cho thấy chỉ có những khác biệt nhỏ.)","In [comparison] with last year, this semester's test scores have improved. (=Dịch: So với năm ngoái, điểm kiểm tra của học kỳ này đã được cải thiện.)","The report makes a detailed [comparison] of healthcare systems worldwide. (=Dịch: Báo cáo đưa ra một sự so sánh chi tiết về các hệ thống y tế trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=comparison&lang=en-GB&ipa=%2Fk%C9%99m%CB%88p%C3%A6r.%C9%99.s%C9%99n%2F","usAudio":"/ai_services/tts3/?q=comparison&lang=en-US&ipa=%2Fk%C9%99m%CB%88p%C3%A6r.%C9%99.s%C9%99n%2F"},{"id":"lv_6_35","topic":"Business and Humanities Studies","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"Lời phàn nàn, sự khiếu nại","defEn":"A statement that something is wrong or not satisfactory.","examples":["The customer filed a formal [complaint] about the poor service. (=Dịch: Khách hàng đã nộp đơn khiếu nại chính thức về chất lượng dịch vụ kém.)","Noise from nearby construction is a common [complaint] among residents. (=Dịch: Tiếng ồn từ công trình xây dựng gần đó là một lời phàn nàn phổ biến của các cư dân.)","Our goal is to resolve every client [complaint] within twenty-four hours. (=Dịch: Mục tiêu của chúng tôi là giải quyết mọi khiếu nại của khách hàng trong vòng hai mươi bốn giờ.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_6_36","topic":"Business and Humanities Studies","word":"concerning","pos":"(prep)","ipa":"/kənˈsɜr.nɪŋ/","defVi":"về, liên quan đến","defEn":"about or related to a particular subject","examples":["I received an email [concerning] the new company policy. (=Dịch: Tôi đã nhận được một email liên quan đến chính sách mới của công ty.)","He asked several questions [concerning] the safety of the medication. (=Dịch: Anh ấy đã hỏi vài câu hỏi liên quan đến độ an toàn của loại thuốc này.)","The committee held a meeting [concerning] the rising cost of living. (=Dịch: Ủy ban đã tổ chức một cuộc họp về vấn đề chi phí sinh hoạt ngày càng tăng.)"],"ukAudio":"/ai_services/tts3/?q=concerning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%9Cr.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=concerning&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%9Cr.n%C9%AA%C5%8B%2F"},{"id":"lv_6_37","topic":"Business and Humanities Studies","word":"conclude","pos":"(v)","ipa":"/kənˈklud/","defVi":"kết luận, suy ra","defEn":"to decide or believe something after considering all the facts","examples":["Researchers [conclude] that regular exercise can improve mental health. (=Dịch: Các nhà nghiên cứu kết luận rằng tập thể dục thường xuyên có thể cải thiện sức khỏe tinh thần.)","The meeting will [conclude] with a speech by the director. (=Dịch: Cuộc họp sẽ kết thúc bằng một bài phát biểu của giám đốc.)","From the evidence presented, we can [conclude] that the project was a success. (=Dịch: Từ những bằng chứng được đưa ra, chúng ta có thể kết luận rằng dự án đã thành công.)"],"ukAudio":"/ai_services/tts3/?q=conclude&lang=en-GB&ipa=%2Fk%C9%99n%CB%88klud%2F","usAudio":"/ai_services/tts3/?q=conclude&lang=en-US&ipa=%2Fk%C9%99n%CB%88klud%2F"},{"id":"lv_6_38","topic":"Business and Humanities Studies","word":"conditioning","pos":"(n)","ipa":"/kənˈdɪʃ.ən.ɪŋ/","defVi":"sự rèn luyện, sự điều hòa, sự tạo phản xạ","defEn":"the process of training or adapting someone or something to behave in a certain way or be in a certain state","examples":["Physical [conditioning] is an essential part of an athlete's daily routine. (=Dịch: Rèn luyện thể lực là một phần thiết yếu trong thói quen hàng ngày của một vận động viên.)","Social [conditioning] often influences our preferences and choices. (=Dịch: Khuôn mẫu từ xã hội thường ảnh hưởng đến sở thích và lựa chọn của chúng ta.)","The team improved its stamina through rigorous aerobic [conditioning]. (=Dịch: Đội đã nâng cao thể lực bền bỉ thông qua quá trình rèn luyện hiếu khí nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=conditioning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=conditioning&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_6_39","topic":"Business and Humanities Studies","word":"conflict","pos":"(n)","ipa":"/ˈkɑːn.flɪkt/","defVi":"sự xung đột, mâu thuẫn","defEn":"an active disagreement, struggle, or clash between people with opposing ideas or interests","examples":["The manager resolved the internal [conflict] between the two departments. (=Dịch: Người quản lý đã giải quyết mâu thuẫn nội bộ giữa hai phòng ban.)","Armed [conflict] has forced thousands of families to leave their homes. (=Dịch: Xung đột vũ trang đã buộc hàng ngàn gia đình phải rời bỏ nhà cửa.)","There is an obvious [conflict] of interest in this business transaction. (=Dịch: Có một sự xung đột lợi ích rõ ràng trong giao dịch kinh doanh này.)"],"ukAudio":"/ai_services/tts3/?q=conflict&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.fl%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=conflict&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.fl%C9%AAkt%2F"},{"id":"lv_6_40","topic":"Business and Humanities Studies","word":"confused","pos":"(adj)","ipa":"/kənˈfjuːzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to think clearly or understand something properly","examples":["I got [confused] by the complex instructions on the exam paper. (=Dịch: Tôi cảm thấy bối rối trước những chỉ dẫn phức tạp trên đề thi.)","The tourist looked [confused] while trying to read the city map. (=Dịch: Người khách du lịch trông có vẻ hoang mang khi cố gắng đọc tấm bản đồ thành phố.)","Her sudden change of plans left everyone feeling [confused]. (=Dịch: Việc cô ấy đột ngột thay đổi kế hoạch đã khiến mọi người cảm thấy bối rối.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90zd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90zd%2F"},{"id":"lv_6_41","topic":"Business and Humanities Studies","word":"confusion","pos":"(n)","ipa":"/kənˈfjuː.ʒən/","defVi":"sự bối rối, sự hoang mang, sự hỗn loạn","defEn":"a state of not being clear, or a situation where things are disorganized and bewildering","examples":["There was some [confusion] about the exact time of the meeting. (=Dịch: Đã có một chút nhầm lẫn về thời gian chính xác của cuộc họp.)","The sudden change in policy caused widespread [confusion] among employees. (=Dịch: Sự thay đổi chính sách đột ngột đã gây ra sự hoang mang trên diện rộng trong nhân viên.)","His vague explanation only added to the passenger's [confusion]. (=Dịch: Lời giải thích mơ hồ của anh ấy chỉ làm tăng thêm sự bối rối của hành khách.)"],"ukAudio":"/ai_services/tts3/?q=confusion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=confusion&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_6_42","topic":"Business and Humanities Studies","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwəns/","defVi":"hậu quả, hệ quả","defEn":"a result or effect of an action or condition","examples":["Global warming is a direct [consequence] of excessive carbon emissions. (=Dịch: Sự nóng lên toàn cầu là một hệ quả trực tiếp của việc phát thải carbon quá mức.)","He had to face the [consequence] of his careless driving. (=Dịch: Anh ấy đã phải đối mặt với hậu quả từ việc lái xe bất cẩn của mình.)","Failing to prepare adequately may have a serious [consequence] for your exam. (=Dịch: Việc không chuẩn bị chu đáo có thể mang lại hậu quả nghiêm trọng cho kỳ thi của bạn.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F"},{"id":"lv_6_43","topic":"Business and Humanities Studies","word":"consolidation","pos":"(n)","ipa":"/kənˌsɑː.lɪˈdeɪ.ʃən/","defVi":"sự củng cố, sự hợp nhất","defEn":"the process of combining several things into a single, more effective or stronger whole","examples":["The merger led to the [consolidation] of several smaller regional offices. (=Dịch: Vụ sáp nhập đã dẫn đến sự hợp nhất của nhiều văn phòng nhỏ trong khu vực.)","The company focuses on the [consolidation] of its market position. (=Dịch: Công ty tập trung vào việc củng cố vị thế của mình trên thị trường.)","Debt [consolidation] can help individuals manage multiple loans more easily. (=Dịch: Hợp nhất nợ có thể giúp các cá nhân quản lý nhiều khoản vay dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=consolidation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8Cs%C9%91%CB%90.l%C9%AA%CB%88de%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consolidation&lang=en-US&ipa=%2Fk%C9%99n%CB%8Cs%C9%91%CB%90.l%C9%AA%CB%88de%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_44","topic":"Business and Humanities Studies","word":"consume","pos":"(v)","ipa":"/kənˈsuːm/","defVi":"tiêu thụ, tiêu dùng, ăn uống","defEn":"to use up a resource, or to eat or drink something","examples":["Modern vehicles [consume] less fuel compared to older models. (=Dịch: Các phương tiện hiện đại tiêu thụ ít nhiên liệu hơn so với các mẫu cũ.)","People are advised not to [consume] too much sugary food. (=Dịch: Mọi người được khuyên không nên tiêu thụ quá nhiều đồ ăn ngọt.)","The fire threatened to [consume] the entire forest within hours. (=Dịch: Ngọn lửa đe dọa sẽ thiêu rụi toàn bộ khu rừng trong vòng vài giờ.)"],"ukAudio":"/ai_services/tts3/?q=consume&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F","usAudio":"/ai_services/tts3/?q=consume&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F"},{"id":"lv_6_45","topic":"Business and Humanities Studies","word":"consumer","pos":"(n)","ipa":"/kənˈsu.mɚ/","defVi":"Người tiêu dùng","defEn":"A person who buys goods or uses services.","examples":["Advertising has a powerful influence on [consumer] behavior. (=Dịch: Quảng cáo có ảnh hưởng mạnh mẽ đến hành vi của người tiêu dùng.)","Many [consumer] groups are demanding safer and healthier food products. (=Dịch: Nhiều nhóm người tiêu dùng đang yêu cầu các sản phẩm thực phẩm an toàn và lành mạnh hơn.)","The company tries to satisfy the modern [consumer] by offering online support. (=Dịch: Công ty cố gắng làm hài lòng người tiêu dùng hiện đại bằng cách cung cấp hỗ trợ trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=consumer&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su.m%C9%9A%2F","usAudio":"/ai_services/tts3/?q=consumer&lang=en-US&ipa=%2Fk%C9%99n%CB%88su.m%C9%9A%2F"},{"id":"lv_6_46","topic":"Business and Humanities Studies","word":"continuous","pos":"(adj)","ipa":"/kənˈtɪn.ju.əs/","defVi":"Liên tục, không ngừng","defEn":"Happening or existing without stopping or being interrupted.","examples":["The brain needs a [continuous] supply of blood and oxygen. (=Dịch: Bộ não cần được cung cấp máu và oxy liên tục.)","After three days of [continuous] rain, the river began to overflow. (=Dịch: Sau ba ngày mưa liên tục, con sông bắt đầu tràn bờ.)","Lifelong learning requires [continuous] effort and curiosity. (=Dịch: Học tập suốt đời đòi hỏi sự nỗ lực và tò mò không ngừng.)"],"ukAudio":"/ai_services/tts3/?q=continuous&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=continuous&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F"},{"id":"lv_6_47","topic":"Business and Humanities Studies","word":"conventional","pos":"(adj)","ipa":"/kənˈvɛn.ʃən.əl/","defVi":"Truyền thống, thông thường theo tập quán","defEn":"Following accepted customs, traditions, or standard practices.","examples":["Organic farming uses fewer chemicals than [conventional] agriculture. (=Dịch: Nông nghiệp hữu cơ sử dụng ít hóa chất hơn so với nông nghiệp truyền thống.)","She preferred alternative medicine to [conventional] treatments. (=Dịch: Cô ấy thích các phương pháp y học thay thế hơn là các phương pháp điều trị thông thường.)","His [conventional] views on education often clashed with modern teaching methods. (=Dịch: Quan điểm truyền thống của ông về giáo dục thường xung đột với các phương pháp giảng dạy hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=conventional&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9Bn.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=conventional&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9Bn.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_48","topic":"Business and Humanities Studies","word":"corporate","pos":"(adj)","ipa":"/ˈkɔr.pɚ.ət/","defVi":"Thuộc về doanh nghiệp, công ty","defEn":"Relating to a large company or business organization.","examples":["She has spent over a decade working in the [corporate] world. (=Dịch: Cô ấy đã dành hơn một thập kỷ làm việc trong giới doanh nghiệp.)","The airline introduced a new [corporate] logo to attract younger clients. (=Dịch: Hãng hàng không đã giới thiệu một logo công ty mới để thu hút khách hàng trẻ tuổi hơn.)","Many businesses are trying to improve their [corporate] social responsibility. (=Dịch: Nhiều doanh nghiệp đang cố gắng cải thiện trách nhiệm xã hội của doanh nghiệp mình.)"],"ukAudio":"/ai_services/tts3/?q=corporate&lang=en-GB&ipa=%2F%CB%88k%C9%94r.p%C9%9A.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=corporate&lang=en-US&ipa=%2F%CB%88k%C9%94r.p%C9%9A.%C9%99t%2F"},{"id":"lv_6_49","topic":"Business and Humanities Studies","word":"craftsman","pos":"(n)","ipa":"/ˈkræfts.mən/","defVi":"Thợ thủ công, nghệ nhân","defEn":"A person who is skilled in a particular craft or manual art.","examples":["The wooden table was hand-carved by a local [craftsman]. (=Dịch: Chiếc bàn gỗ được chạm khắc thủ công bởi một nghệ nhân địa phương.)","Every master [craftsman] spends years perfecting their delicate techniques. (=Dịch: Mỗi người thợ thủ công bậc thầy đều dành nhiều năm để hoàn thiện các kỹ thuật tinh xảo của mình.)","He admired the dedication that the [craftsman] showed in repairing antique watches. (=Dịch: Anh ngưỡng mộ sự tận tụy mà người thợ thủ công thể hiện khi sửa chữa những chiếc đồng hồ cổ.)"],"ukAudio":"/ai_services/tts3/?q=craftsman&lang=en-GB&ipa=%2F%CB%88kr%C3%A6fts.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=craftsman&lang=en-US&ipa=%2F%CB%88kr%C3%A6fts.m%C9%99n%2F"},{"id":"lv_6_50","topic":"Business and Humanities Studies","word":"criterion","pos":"(n)","ipa":"/kraɪˈtɪr.i.ən/","defVi":"tiêu chí, chuẩn mực","defEn":"a standard by which something may be judged or decided","examples":["Academic achievement is not the sole [criterion] for college admission. (=Dịch: Thành tích học tập không phải là tiêu chí duy nhất để xét tuyển đại học.)","Cost-effectiveness was the primary [criterion] used to select the vendor. (=Dịch: Hiệu quả chi phí là tiêu chí chính được sử dụng để lựa chọn nhà cung cấp.)","Safety should be the most important [criterion] when designing vehicles. (=Dịch: An toàn phải là tiêu chuẩn quan trọng nhất khi thiết kế các phương tiện giao thông.)"],"ukAudio":"/ai_services/tts3/?q=criterion&lang=en-GB&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=criterion&lang=en-US&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F"},{"id":"lv_6_51","topic":"Business and Humanities Studies","word":"critical","pos":"(adj)","ipa":"/ˈkrɪt̬.ɪ.kəl/","defVi":"quan trọng, then chốt; chỉ trích","defEn":"extremely important or expressing serious disapproval","examples":["Water conservation plays a [critical] role in protecting the environment. (=Dịch: Bảo tồn nguồn nước đóng một vai trò then chốt trong việc bảo vệ môi trường.)","The director was highly [critical] of the actor's performance. (=Dịch: Đạo diễn đã chỉ trích rất gay gắt màn trình diễn của diễn viên.)","University students are encouraged to develop strong [critical] thinking skills. (=Dịch: Sinh viên đại học được khuyến khích phát triển kỹ năng tư duy phản biện tốt.)"],"ukAudio":"/ai_services/tts3/?q=critical&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=critical&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F"},{"id":"lv_6_52","topic":"Business and Humanities Studies","word":"cultural","pos":"(adj)","ipa":"/ˈkʌl.tʃɚ.əl/","defVi":"thuộc về văn hóa","defEn":"relating to the habits, traditions, and beliefs of a society","examples":["Traveling abroad exposes people to different [cultural] traditions. (=Dịch: Du lịch nước ngoài giúp mọi người tiếp cận với những truyền thống văn hóa khác nhau.)","The city hosts an annual [cultural] festival celebrating local arts and music. (=Dịch: Thành phố tổ chức một lễ hội văn hóa thường niên tôn vinh nghệ thuật và âm nhạc địa phương.)","Language plays a vital role in preserving a nation's [cultural] identity. (=Dịch: Ngôn ngữ đóng một vai trò quan trọng trong việc gìn giữ bản sắc văn hóa của một quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=cultural&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cultural&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F"},{"id":"lv_6_53","topic":"Business and Humanities Studies","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"suy giảm; từ chối","defEn":"to become smaller, fewer, or less; or to politely refuse an offer or invitation","examples":["Car sales began to [decline] sharply during the economic downturn. (=Dịch: Doanh số bán ô tô bắt đầu sụt giảm mạnh trong thời kỳ suy thoái kinh tế.)","I had to [decline] the job offer because the commute was too long. (=Dịch: Tôi đã phải từ chối lời mời làm việc vì quãng đường đi làm quá xa.)","Her health started to [decline] as she grew older. (=Dịch: Sức khỏe của bà ấy bắt đầu suy giảm khi tuổi tác ngày càng cao.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_6_54","topic":"Business and Humanities Studies","word":"define","pos":"(v)","ipa":"/dɪˈfaɪn/","defVi":"định nghĩa, xác định","defEn":"to explain the exact meaning of a word or idea","examples":["It is difficult to [define] the concept of happiness simply. (=Dịch: Rất khó để định nghĩa khái niệm hạnh phúc một cách đơn giản.)","Dictionaries [define] words and provide examples of how they are used. (=Dịch: Từ điển định nghĩa các từ và cung cấp các ví dụ về cách sử dụng chúng.)","The contract will clearly [define] the responsibilities of each team member. (=Dịch: Hợp đồng sẽ xác định rõ ràng trách nhiệm của từng thành viên trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=define&lang=en-GB&ipa=%2Fd%C9%AA%CB%88fa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=define&lang=en-US&ipa=%2Fd%C9%AA%CB%88fa%C9%AAn%2F"},{"id":"lv_6_55","topic":"Business and Humanities Studies","word":"definition","pos":"(n)","ipa":"/ˌdɛf.əˈnɪʃ.ən/","defVi":"Định nghĩa, sự giải thích rõ ràng","defEn":"An explanation of the exact meaning of a word or phrase.","examples":["You can look up the exact [definition] of unfamiliar words in a dictionary. (=Dịch: Bạn có thể tra cứu định nghĩa chính xác của những từ xa lạ trong từ điển.)","The legal [definition] of property varies from country to country. (=Dịch: Định nghĩa pháp lý về tài sản có sự khác nhau giữa các quốc gia.)","His [definition] of success focuses on happiness rather than wealth. (=Dịch: Định nghĩa về thành công của anh ấy tập trung vào hạnh phúc hơn là sự giàu có.)"],"ukAudio":"/ai_services/tts3/?q=definition&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=definition&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_6_56","topic":"Business and Humanities Studies","word":"dementia","pos":"(n)","ipa":"/dɪˈmen.ʃə/","defVi":"chứng suy giảm trí nhớ, bệnh sa sút trí tuệ","defEn":"a progressive mental disorder characterized by memory loss, confusion, and impaired reasoning","examples":["The hospital provides specialized care for elderly patients suffering from [dementia]. (=Dịch: Bệnh viện cung cấp dịch vụ chăm sóc chuyên biệt cho những bệnh nhân cao tuổi mắc chứng sa sút trí tuệ.)","Regular mental exercises may help lower the risk of developing [dementia] in later life. (=Dịch: Các bài tập trí não thường xuyên có thể giúp giảm nguy cơ mắc chứng suy giảm trí nhớ khi về già.)","Caring for a family member with advanced [dementia] can be emotionally exhausting. (=Dịch: Chăm sóc một thành viên trong gia đình mắc chứng sa sút trí tuệ giai đoạn nặng có thể gây kiệt quệ về mặt cảm xúc.)"],"ukAudio":"/ai_services/tts3/?q=dementia&lang=en-GB&ipa=%2Fd%C9%AA%CB%88men.%CA%83%C9%99%2F","usAudio":"/ai_services/tts3/?q=dementia&lang=en-US&ipa=%2Fd%C9%AA%CB%88men.%CA%83%C9%99%2F"},{"id":"lv_6_57","topic":"Business and Humanities Studies","word":"democratic","pos":"(adj)","ipa":"/ˌdɛm.əˈkræt̬.ɪk/","defVi":"Dân chủ","defEn":"Based on the principle that all people have equal rights to participate in governance.","examples":["Free and fair elections are the foundation of any [democratic] society. (=Dịch: Các cuộc bầu cử tự do và công bằng là nền tảng của bất kỳ xã hội dân chủ nào.)","The manager adopted a [democratic] leadership style by consulting his team. (=Dịch: Người quản lý đã áp dụng phong cách lãnh đạo dân chủ bằng cách tham khảo ý kiến của nhóm mình.)","Citizens should actively engage in the [democratic] process to make their voices heard. (=Dịch: Công dân nên tích cực tham gia vào tiến trình dân chủ để tiếng nói của họ được lắng nghe.)"],"ukAudio":"/ai_services/tts3/?q=democratic&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99%CB%88kr%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=democratic&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99%CB%88kr%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_6_58","topic":"Business and Humanities Studies","word":"dependent","pos":"(adj)","ipa":"/dɪˈpɛn.dənt/","defVi":"phụ thuộc, lệ thuộc","defEn":"needing the support of something or someone else to survive or succeed","examples":["Many young adults are still financially [dependent] on their parents. (=Dịch: Nhiều người trẻ tuổi vẫn phụ thuộc tài chính vào cha mẹ của họ.)","The economy of this coastal town is largely [dependent] on tourism. (=Dịch: Nền kinh tế của thị trấn ven biển này phần lớn phụ thuộc vào du lịch.)","The success of the crops is [dependent] on the weather conditions. (=Dịch: Sự thành công của mùa màng phụ thuộc vào điều kiện thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%9Bn.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%9Bn.d%C9%99nt%2F"},{"id":"lv_6_59","topic":"Business and Humanities Studies","word":"depression","pos":"(n)","ipa":"/dɪˈpreʃ.ən/","defVi":"chứng trầm cảm; sự suy thoái kinh tế","defEn":"a mental health condition marked by severe sadness, or a period of severe economic decline","examples":["Regular physical exercise can help reduce symptoms of [depression]. (=Dịch: Tập thể dục thường xuyên có thể giúp giảm các triệu chứng trầm cảm.)","The global economy suffered a major [depression] in the 1930s. (=Dịch: Nền kinh tế toàn cầu đã trải qua một cuộc đại suy thoái lớn vào những năm 1930.)","Talking openly with a therapist can provide relief from clinical [depression]. (=Dịch: Trò chuyện cởi mở với chuyên gia trị liệu có thể giúp thuyên giảm chứng trầm cảm lâm sàng.)"],"ukAudio":"/ai_services/tts3/?q=depression&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pre%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=depression&lang=en-US&ipa=%2Fd%C9%AA%CB%88pre%CA%83.%C9%99n%2F"},{"id":"lv_6_60","topic":"Business and Humanities Studies","word":"determine","pos":"(v)","ipa":"/dɪˈtɜːr.mɪn/","defVi":"xác định, quyết định","defEn":"to discover the facts about something or to decide something firmly","examples":["Scientists are conducting experiments to [determine] the exact age of the fossil. (=Dịch: Các nhà khoa học đang tiến hành các thí nghiệm để xác định tuổi chính xác của hóa thạch.)","Your exam results will largely [determine] which university you can attend. (=Dịch: Kết quả thi của bạn sẽ quyết định phần lớn trường đại học mà bạn có thể theo học.)","Officials are trying to [determine] the cause of the sudden power outage. (=Dịch: Các giới chức đang nỗ lực xác định nguyên nhân gây ra sự cố mất điện đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=determine&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9C%CB%90r.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=determine&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9C%CB%90r.m%C9%AAn%2F"},{"id":"lv_6_61","topic":"Business and Humanities Studies","word":"devote","pos":"(v)","ipa":"/dɪˈvoʊt/","defVi":"cống hiến, dành hết (thời gian, tâm huyết) cho","defEn":"to give all or a large part of one's time or resources to a person, activity, or cause","examples":["She decided to [devote] her entire career to cancer research. (=Dịch: Cô ấy quyết định cống hiến toàn bộ sự nghiệp của mình cho việc nghiên cứu bệnh ung thư.)","Parents often [devote] a tremendous amount of energy to raising their children. (=Dịch: Cha mẹ thường dành rất nhiều năng lượng cho việc nuôi dạy con cái.)","He plans to [devote] more time to community service after retirement. (=Dịch: Ông dự định dành nhiều thời gian hơn cho công tác phục vụ cộng đồng sau khi nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=devote&lang=en-GB&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=devote&lang=en-US&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F"},{"id":"lv_6_62","topic":"Business and Humanities Studies","word":"disadvantage","pos":"(n)","ipa":"/ˌdɪs.ədˈvæn.t̬ɪdʒ/","defVi":"nhược điểm, bất lợi","defEn":"an unfavorable condition or circumstance that reduces the chances of success","examples":["One major [disadvantage] of remote work is the lack of face-to-face interaction. (=Dịch: Một bất lợi lớn của việc làm việc từ xa là thiếu sự tương tác trực tiếp.)","Candidates without relevant experience are at a serious [disadvantage]. (=Dịch: Những ứng viên không có kinh nghiệm liên quan sẽ chịu bất lợi nghiêm trọng.)","We must weigh the benefits against every potential [disadvantage] before investing. (=Dịch: Chúng ta phải cân nhắc các lợi ích so với mọi nhược điểm tiềm ẩn trước khi đầu tư.)"],"ukAudio":"/ai_services/tts3/?q=disadvantage&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=disadvantage&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_6_63","topic":"Business and Humanities Studies","word":"dominant","pos":"(adj)","ipa":"/ˈdɑː.mə.nənt/","defVi":"Thống trị, chiếm ưu thế vượt trội","defEn":"More important, strong, or noticeable than anything else of the same type.","examples":["English has become the [dominant] language in global business. (=Dịch: Tiếng Anh đã trở thành ngôn ngữ thống trị trong kinh doanh toàn cầu.)","The tech giant maintains a [dominant] position in the smartphone market. (=Dịch: Gã khổng lồ công nghệ duy trì vị thế thống trị trên thị trường điện thoại thông minh.)","Geneticists study how [dominant] genes are inherited by offspring. (=Dịch: Các nhà di truyền học nghiên cứu cách các gen trội được di truyền sang thế hệ sau.)"],"ukAudio":"/ai_services/tts3/?q=dominant&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99.n%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dominant&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99.n%C9%99nt%2F"},{"id":"lv_6_64","topic":"Business and Humanities Studies","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"quyên góp, hiến tặng, ủng hộ","defEn":"to give money, goods, or time to help a person or organization","examples":["Many wealthy individuals [donate] large sums of money to medical research. (=Dịch: Nhiều cá nhân giàu có quyên góp số tiền lớn cho nghiên cứu y học.)","Local residents decided to [donate] warm clothes to earthquake victims. (=Dịch: Cư dân địa phương đã quyết định ủng hộ quần áo ấm cho các nạn nhân động đất.)","He volunteered to [donate] blood during the national health campaign. (=Dịch: Anh ấy đã tình nguyện hiến máu trong chiến dịch y tế quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_6_65","topic":"Business and Humanities Studies","word":"duplicate","pos":"(v)","ipa":"/ˈduː.plɪ.keɪt/","defVi":"sao chép, nhân bản, lặp lại","defEn":"to make an exact copy of something, or repeat something","examples":["Researchers tried to [duplicate] the original experiment to confirm the findings. (=Dịch: Các nhà nghiên cứu đã cố gắng lặp lại thí nghiệm ban đầu để xác nhận các phát hiện.)","You can easily [duplicate] this document by scanning it onto your computer. (=Dịch: Bạn có thể dễ dàng sao chép tài liệu này bằng cách quét nó vào máy tính.)","The software allows users to [duplicate] project files with a single click. (=Dịch: Phần mềm cho phép người dùng nhân bản các tệp dự án chỉ với một cú nhấp chuột.)"],"ukAudio":"/ai_services/tts3/?q=duplicate&lang=en-GB&ipa=%2F%CB%88du%CB%90.pl%C9%AA.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=duplicate&lang=en-US&ipa=%2F%CB%88du%CB%90.pl%C9%AA.ke%C9%AAt%2F"},{"id":"lv_6_66","topic":"Business and Humanities Studies","word":"eager","pos":"(adj)","ipa":"/ˈi.ɡər/","defVi":"háo hức, tha thiết, hăm hở","defEn":"strongly wanting to do or have something","examples":["The students were [eager] to start their summer vacation. (=Dịch: Các học sinh rất háo hức bắt đầu kỳ nghỉ hè.)","He is always [eager] to learn new professional skills. (=Dịch: Anh ấy luôn hăm hở học hỏi những kỹ năng chuyên môn mới.)","The crowd was [eager] for the concert to begin. (=Dịch: Đám đông vô cùng sốt ruột mong buổi hòa nhạc bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=eager&lang=en-GB&ipa=%2F%CB%88i.%C9%A1%C9%99r%2F","usAudio":"/ai_services/tts3/?q=eager&lang=en-US&ipa=%2F%CB%88i.%C9%A1%C9%99r%2F"},{"id":"lv_6_67","topic":"Business and Humanities Studies","word":"elderly","pos":"(adj)","ipa":"/ˈɛl.dɚ.li/","defVi":"cao tuổi, lớn tuổi","defEn":"used as a polite word for old, usually describing people","examples":["The government is improving healthcare services for [elderly] citizens. (=Dịch: Chính phủ đang cải thiện các dịch vụ chăm sóc sức khỏe cho những công dân cao tuổi.)","A kind volunteer helped the [elderly] woman carry her groceries. (=Dịch: Một tình nguyện viên tốt bụng đã giúp người phụ nữ lớn tuổi xách đồ mua sắm.)","Many [elderly] residents enjoy walking in the park every morning. (=Dịch: Nhiều cư dân lớn tuổi thích đi dạo trong công viên mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=elderly&lang=en-GB&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F","usAudio":"/ai_services/tts3/?q=elderly&lang=en-US&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F"},{"id":"lv_6_68","topic":"Business and Humanities Studies","word":"emotion","pos":"(n)","ipa":"/ɪˈmoʊ.ʃən/","defVi":"cảm xúc","defEn":"a strong feeling such as love, fear, or anger","examples":["He struggled to control his [emotion] during the farewell speech. (=Dịch: Anh ấy đã rất cố gắng kìm nén cảm xúc trong bài phát biểu chia tay.)","Music can evoke a wide range of human [emotion]. (=Dịch: Âm nhạc có thể gợi lên rất nhiều cung bậc cảm xúc của con người.)","Making important decisions based purely on [emotion] can lead to regrets. (=Dịch: Đưa ra các quyết định quan trọng chỉ dựa vào cảm xúc có thể dẫn đến hối tiếc.)"],"ukAudio":"/ai_services/tts3/?q=emotion&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emotion&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_6_69","topic":"Business and Humanities Studies","word":"emphasis","pos":"(n)","ipa":"/ˈem.fə.sɪs/","defVi":"sự nhấn mạnh, tầm quan trọng","defEn":"special importance, value, or attention given to something","examples":["The school puts a strong [emphasis] on science and mathematics. (=Dịch: Ngôi trường đặt sự nhấn mạnh lớn vào khoa học và toán học.)","He spoke with great [emphasis] on the need for immediate action. (=Dịch: Ông ấy đã nói với sự nhấn mạnh lớn về sự cần thiết của hành động ngay lập tức.)","There is an increasing [emphasis] on renewable energy in government policy. (=Dịch: Ngày càng có sự chú trọng nhiều hơn vào năng lượng tái tạo trong chính sách của chính phủ.)"],"ukAudio":"/ai_services/tts3/?q=emphasis&lang=en-GB&ipa=%2F%CB%88em.f%C9%99.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=emphasis&lang=en-US&ipa=%2F%CB%88em.f%C9%99.s%C9%AAs%2F"},{"id":"lv_6_70","topic":"Business and Humanities Studies","word":"emphasise","pos":"(v)","ipa":"/ˈɛm.fə.saɪz/","defVi":"nhấn mạnh, làm nổi bật","defEn":"to give special importance or attention to something","examples":["The lecturer wanted to [emphasise] the importance of original research. (=Dịch: Giảng viên muốn nhấn mạnh tầm quan trọng của việc nghiên cứu độc lập.)","You should [emphasise] your practical experience during the job interview. (=Dịch: Bạn nên nhấn mạnh kinh nghiệm thực tế của mình trong buổi phỏng vấn xin việc.)","Nutritionists repeatedly [emphasise] that breakfast is the most vital meal of the day. (=Dịch: Các chuyên gia dinh dưỡng liên tục nhấn mạnh rằng bữa sáng là bữa ăn quan trọng nhất trong ngày.)"],"ukAudio":"/ai_services/tts3/?q=emphasise&lang=en-GB&ipa=%2F%CB%88%C9%9Bm.f%C9%99.sa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=emphasise&lang=en-US&ipa=%2F%CB%88%C9%9Bm.f%C9%99.sa%C9%AAz%2F"},{"id":"lv_6_71","topic":"Business and Humanities Studies","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, tạo điều kiện thuận lợi, giúp có thể","defEn":"to make it possible for someone to do something, or for something to happen","examples":["Online courses [enable] people to study flexible hours from home. (=Dịch: Các khóa học trực tuyến cho phép mọi người học theo thời gian linh hoạt tại nhà.)","The new scholarship will [enable] talented students to attend university. (=Dịch: Học bổng mới sẽ tạo điều kiện cho các sinh viên tài năng theo học đại học.)","Smart technology can [enable] homes to use energy much more efficiently. (=Dịch: Công nghệ thông minh có thể giúp các ngôi nhà sử dụng năng lượng hiệu quả hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_6_72","topic":"Business and Humanities Studies","word":"encode","pos":"(v)","ipa":"/ɪnˈkoʊd/","defVi":"mã hóa","defEn":"to convert information into a particular code or digital format","examples":["Scientists found a way to [encode] large amounts of data onto DNA strands. (=Dịch: Các nhà khoa học đã tìm ra cách mã hóa lượng dữ liệu lớn vào các chuỗi DNA.)","The software is designed to [encode] video files into a smaller size. (=Dịch: Phần mềm được thiết kế để mã hóa các tệp video sang kích thước nhỏ hơn.)","Our brains automatically [encode] sensory memories during daily experiences. (=Dịch: Bộ não của chúng ta tự động mã hóa ký ức giác quan trong các trải nghiệm hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=encode&lang=en-GB&ipa=%2F%C9%AAn%CB%88ko%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=encode&lang=en-US&ipa=%2F%C9%AAn%CB%88ko%CA%8Ad%2F"},{"id":"lv_6_73","topic":"Business and Humanities Studies","word":"encoding","pos":"(n)","ipa":"/ɪnˈkoʊ.dɪŋ/","defVi":"sự mã hóa","defEn":"the process of putting information into a special code or format","examples":["Data [encoding] ensures that sensitive information remains secure during transmission. (=Dịch: Việc mã hóa dữ liệu đảm bảo thông tin nhạy cảm vẫn an toàn trong quá trình truyền tải.)","The software supports the [encoding] of high-definition video files. (=Dịch: Phần mềm này hỗ trợ việc mã hóa các tệp video độ nét cao.)","Memory formation begins with the [encoding] of sensory information in the brain. (=Dịch: Sự hình thành trí nhớ bắt đầu bằng quá trình mã hóa thông tin cảm giác trong não bộ.)"],"ukAudio":"/ai_services/tts3/?q=encoding&lang=en-GB&ipa=%2F%C9%AAn%CB%88ko%CA%8A.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=encoding&lang=en-US&ipa=%2F%C9%AAn%CB%88ko%CA%8A.d%C9%AA%C5%8B%2F"},{"id":"lv_6_74","topic":"Business and Humanities Studies","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký nhập học","defEn":"to officially register or join a school, course, or group","examples":["She decided to [enroll] in an online coding course to boost her career. (=Dịch: Cô ấy quyết định đăng ký một khóa học lập trình trực tuyến để phát triển sự nghiệp.)","Parents must [enroll] their children before the end of this month. (=Dịch: Phụ huynh phải ghi danh cho con em mình trước cuối tháng này.)","Over five hundred students [enroll] at this university every semester. (=Dịch: Hơn năm trăm sinh viên nhập học tại trường đại học này mỗi học kỳ.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_6_75","topic":"Business and Humanities Studies","word":"entrepreneur","pos":"(n)","ipa":"/ˌɑːn.trə.prəˈnɝ/","defVi":"doanh nhân, người khởi nghiệp","defEn":"a person who starts a business and takes financial risks in the hope of profit","examples":["The young [entrepreneur] secured funding for her innovative tech startup. (=Dịch: Nữ doanh nhân trẻ đã nhận được vốn đầu tư cho công ty khởi nghiệp công nghệ sáng tạo của mình.)","Being a successful [entrepreneur] requires persistence and creativity. (=Dịch: Trở thành một doanh nhân thành công đòi hỏi sự kiên trì và sáng tạo.)","Many an [entrepreneur] faces significant challenges during the first year of business. (=Dịch: Nhiều doanh nhân phải đối mặt với những thử thách lớn trong năm đầu kinh doanh.)"],"ukAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%C9%9D%2F","usAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%C9%9D%2F"},{"id":"lv_6_76","topic":"Business and Humanities Studies","word":"episodic","pos":"(adj)","ipa":"/ˌɛp.əˈsɑː.dɪk/","defVi":"từng hồi, gián đoạn, xảy ra theo đợt","defEn":"happening only sometimes and not regularly; or composed of separate episodes","examples":["His interest in foreign languages was rather [episodic] and rarely lasted long. (=Dịch: Sự quan tâm của anh ấy đối với ngoại ngữ khá gián đoạn và hiếm khi kéo dài lâu.)","The patient suffered from [episodic] bouts of severe chest pain. (=Dịch: Bệnh nhân đã phải chịu đựng những cơn đau ngực dữ dội xảy ra theo từng đợt.)","The novel has an [episodic] structure where each chapter tells a distinct tale. (=Dịch: Cuốn tiểu thuyết có cấu trúc từng phần, trong đó mỗi chương kể một câu chuyện riêng biệt.)"],"ukAudio":"/ai_services/tts3/?q=episodic&lang=en-GB&ipa=%2F%CB%8C%C9%9Bp.%C9%99%CB%88s%C9%91%CB%90.d%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=episodic&lang=en-US&ipa=%2F%CB%8C%C9%9Bp.%C9%99%CB%88s%C9%91%CB%90.d%C9%AAk%2F"},{"id":"lv_6_77","topic":"Business and Humanities Studies","word":"equal","pos":"(adj)","ipa":"/ˈi.kwəl/","defVi":"bình đẳng, ngang bằng","defEn":"the same in size, amount, degree, or value","examples":["All citizens should have [equal] rights and opportunities. (=Dịch: Mọi công dân đều nên có quyền lợi và cơ hội bình đẳng.)","Divide the cake into six [equal] parts so everyone gets a slice. (=Dịch: Hãy chia chiếc bánh thành sáu phần bằng nhau để ai cũng có một phần.)","Both candidates are of [equal] ability and experience. (=Dịch: Cả hai ứng viên đều có năng lực và kinh nghiệm ngang nhau.)"],"ukAudio":"/ai_services/tts3/?q=equal&lang=en-GB&ipa=%2F%CB%88i.kw%C9%99l%2F","usAudio":"/ai_services/tts3/?q=equal&lang=en-US&ipa=%2F%CB%88i.kw%C9%99l%2F"},{"id":"lv_6_78","topic":"Business and Humanities Studies","word":"esteem","pos":"(n)","ipa":"/ɪˈstim/","defVi":"sự kính trọng, lòng quý trọng","defEn":"respect and admiration for someone or something","examples":["She is held in high [esteem] by her colleagues. (=Dịch: Cô ấy được các đồng nghiệp vô cùng kính trọng.)","Building self-[esteem] is crucial for personal development. (=Dịch: Xây dựng lòng tự trọng là điều rất quan trọng cho sự phát triển cá nhân.)","The professor won the [esteem] of all his students. (=Dịch: Vị giáo sư đã nhận được sự kính phục của tất cả sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=esteem&lang=en-GB&ipa=%2F%C9%AA%CB%88stim%2F","usAudio":"/ai_services/tts3/?q=esteem&lang=en-US&ipa=%2F%C9%AA%CB%88stim%2F"},{"id":"lv_6_79","topic":"Business and Humanities Studies","word":"ethical","pos":"(adj)","ipa":"/ˈeθ.ɪ.kəl/","defVi":"thuộc về đạo đức, hợp luân thường đạo lý","defEn":"relating to beliefs about what is morally right and wrong","examples":["Consumers are increasingly demanding products made through [ethical] practices. (=Dịch: Người tiêu dùng ngày càng đòi hỏi các sản phẩm được sản xuất bằng các phương thức hợp đạo đức.)","The doctor was praised for his high [ethical] standards. (=Dịch: Vị bác sĩ đã được ca ngợi vì những tiêu chuẩn đạo đức cao của mình.)","Is it [ethical] to test cosmetic products on animals? (=Dịch: Liệu việc thử nghiệm mỹ phẩm trên động vật có hợp đạo đức hay không?)"],"ukAudio":"/ai_services/tts3/?q=ethical&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=ethical&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F"},{"id":"lv_6_80","topic":"Business and Humanities Studies","word":"ethnographic","pos":"(adj)","ipa":"/ˌeθ.nəˈɡræf.ɪk/","defVi":"thuộc dân tộc học","defEn":"relating to the scientific study and description of people and cultures","examples":["The anthropologist conducted extensive [ethnographic] fieldwork in rural villages. (=Dịch: Nhà nhân chủng học đã tiến hành nghiên cứu thực địa dân tộc học sâu rộng tại các ngôi làng nông thôn.)","This museum houses a vast collection of [ethnographic] artifacts. (=Dịch: Bảo tàng này lưu giữ một bộ sưu tập phong phú các hiện vật dân tộc học.)","Her dissertation used an [ethnographic] approach to explore local traditions. (=Dịch: Luận án của cô ấy đã sử dụng phương pháp tiếp cận dân tộc học để tìm hiểu các truyền thống địa phương.)"],"ukAudio":"/ai_services/tts3/?q=ethnographic&lang=en-GB&ipa=%2F%CB%8Ce%CE%B8.n%C9%99%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=ethnographic&lang=en-US&ipa=%2F%CB%8Ce%CE%B8.n%C9%99%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F"},{"id":"lv_6_81","topic":"Business and Humanities Studies","word":"ethnography","pos":"(n)","ipa":"/ɛθˈnɑː.ɡrə.fi/","defVi":"dân tộc học, phương pháp nghiên cứu dân tộc ký","defEn":"the scientific study and detailed description of individual human cultures","examples":["The researcher spent two years doing [ethnography] in a remote mountain village. (=Dịch: Nhà nghiên cứu đã dành hai năm để thực hiện nghiên cứu dân tộc ký tại một ngôi làng miền núi xa xôi.)","Her course in [ethnography] taught students how to conduct field interviews. (=Dịch: Khóa học dân tộc học của cô đã dạy sinh viên cách tiến hành phỏng vấn thực địa.)","Visual [ethnography] uses photography and video to document daily cultural practices. (=Dịch: Dân tộc ký thị giác sử dụng nhiếp ảnh và video để ghi lại các tập quán văn hóa hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=ethnography&lang=en-GB&ipa=%2F%C9%9B%CE%B8%CB%88n%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=ethnography&lang=en-US&ipa=%2F%C9%9B%CE%B8%CB%88n%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_6_82","topic":"Business and Humanities Studies","word":"evaluate","pos":"(v)","ipa":"/ɪˈvæl.ju.eɪt/","defVi":"đánh giá, định giá","defEn":"to form an opinion of the amount, value, or quality of something after careful thought","examples":["The doctor needs to [evaluate] the patient's condition before recommending surgery. (=Dịch: Bác sĩ cần đánh giá tình trạng của bệnh nhân trước khi đề xuất phẫu thuật.)","Companies often [evaluate] candidate performance during probation periods. (=Dịch: Các công ty thường đánh giá năng lực làm việc của ứng viên trong thời gian thử việc.)","We must carefully [evaluate] all available options before making a final decision. (=Dịch: Chúng ta phải đánh giá cẩn thận mọi lựa chọn sẵn có trước khi đưa ra quyết định cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=evaluate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6l.ju.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaluate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6l.ju.e%C9%AAt%2F"},{"id":"lv_6_83","topic":"Business and Humanities Studies","word":"evolutionary","pos":"(adj)","ipa":"/ˌɛv.əˈluː.ʃə.ner.i/","defVi":"mang tính tiến hóa, thuộc về tiến hóa","defEn":"relating to the gradual development and change of living things or ideas","examples":["Scientists study fossils to understand the [evolutionary] history of birds. (=Dịch: Các nhà khoa học nghiên cứu hóa thạch để hiểu được lịch sử tiến hóa của loài chim.)","The human brain has undergone significant [evolutionary] changes over millions of years. (=Dịch: Bộ não con người đã trải qua những thay đổi tiến hóa đáng kể qua hàng triệu năm.)","Technology undergoes an [evolutionary] process similar to biological adaptation. (=Dịch: Công nghệ trải qua một quá trình mang tính tiến hóa tương tự như sự thích nghi sinh học.)"],"ukAudio":"/ai_services/tts3/?q=evolutionary&lang=en-GB&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99.ner.i%2F","usAudio":"/ai_services/tts3/?q=evolutionary&lang=en-US&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99.ner.i%2F"},{"id":"lv_6_84","topic":"Business and Humanities Studies","word":"evolve","pos":"(v)","ipa":"/ɪˈvɑːlv/","defVi":"tiến hóa, phát triển dần dần","defEn":"to develop gradually, especially from a simple to a more complex form","examples":["The company needs to [evolve] its marketing strategy to attract younger customers. (=Dịch: Công ty cần phát triển chiến lược tiếp thị để thu hút khách hàng trẻ tuổi hơn.)","Scientists believe that birds did [evolve] from dinosaurs over millions of years. (=Dịch: Các nhà khoa học tin rằng loài chim đã tiến hóa từ khủng long qua hàng triệu năm.)","Online learning tools continue to [evolve] rapidly alongside technological advancements. (=Dịch: Các công cụ học tập trực tuyến tiếp tục phát triển nhanh chóng cùng với những tiến bộ công nghệ.)"],"ukAudio":"/ai_services/tts3/?q=evolve&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F","usAudio":"/ai_services/tts3/?q=evolve&lang=en-US&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F"},{"id":"lv_6_85","topic":"Business and Humanities Studies","word":"excellence","pos":"(n)","ipa":"/ˈek.sə.ləns/","defVi":"sự xuất sắc, sự ưu tú","defEn":"the quality of being outstanding or extremely good","examples":["The university is widely recognized for its academic [excellence]. (=Dịch: Trường đại học được công nhận rộng rãi nhờ sự xuất sắc trong học thuật.)","She was given an award for [excellence] in customer service. (=Dịch: Cô ấy đã được trao giải thưởng vì sự xuất sắc trong dịch vụ khách hàng.)","Our team always strives for [excellence] in every project. (=Dịch: Đội ngũ của chúng tôi luôn nỗ lực hướng tới sự hoàn hảo trong mọi dự án.)"],"ukAudio":"/ai_services/tts3/?q=excellence&lang=en-GB&ipa=%2F%CB%88ek.s%C9%99.l%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=excellence&lang=en-US&ipa=%2F%CB%88ek.s%C9%99.l%C9%99ns%2F"},{"id":"lv_6_86","topic":"Business and Humanities Studies","word":"executive","pos":"(n)","ipa":"/ɪɡˈzɛk.jə.tɪv/","defVi":"nhà điều hành, ủy viên ban quản trị","defEn":"a person who has a senior management position in a business or organization","examples":["The chief [executive] announced a new strategy to expand into international markets. (=Dịch: Vị giám đốc điều hành đã công bố một chiến lược mới để mở rộng sang các thị trường quốc tế.)","She worked hard for years before becoming a senior [executive] at the firm. (=Dịch: Cô ấy đã làm việc chăm chỉ nhiều năm trước khi trở thành một nhà điều hành cấp cao tại công ty.)","Company [executive] members met yesterday to discuss the annual budget. (=Dịch: Các thành viên ban điều hành công ty đã họp ngày hôm qua để thảo luận về ngân sách hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=executive&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%9Bk.j%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=executive&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%9Bk.j%C9%99.t%C9%AAv%2F"},{"id":"lv_6_87","topic":"Business and Humanities Studies","word":"expectation","pos":"(n)","ipa":"/ˌɛk.spɛkˈteɪ.ʃən/","defVi":"kỳ vọng, sự mong đợi","defEn":"a belief that something will happen or that someone should achieve something","examples":["The final product completely exceeded our [expectations]. (=Dịch: Sản phẩm cuối cùng đã hoàn toàn vượt qua kỳ vọng của chúng tôi.)","Parents often place high academic [expectations] on their children. (=Dịch: Các bậc cha mẹ thường đặt nhiều kỳ vọng học tập cao vào con cái.)","There is widespread public [expectation] that inflation will drop soon. (=Dịch: Công chúng đang có sự kỳ vọng rộng rãi rằng lạm phát sẽ sớm giảm.)"],"ukAudio":"/ai_services/tts3/?q=expectation&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9Bk%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expectation&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9Bk%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_88","topic":"Business and Humanities Studies","word":"expertise","pos":"(n)","ipa":"/ˌɛk.spɚˈtiz/","defVi":"chuyên môn, kiến thức chuyên sâu","defEn":"expert skill or knowledge in a particular field","examples":["We need to hire an external consultant with technical [expertise]. (=Dịch: Chúng ta cần thuê một chuyên gia tư vấn bên ngoài có chuyên môn kỹ thuật.)","She shared her [expertise] in digital marketing with the new interns. (=Dịch: Cô đã chia sẻ kiến thức chuyên môn về tiếp thị kỹ thuật số của mình cho các thực tập sinh mới.)","His [expertise] in financial management helped the company avoid bankruptcy. (=Dịch: Chuyên môn quản lý tài chính của anh ấy đã giúp công ty tránh khỏi bờ vực phá sản.)"],"ukAudio":"/ai_services/tts3/?q=expertise&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9A%CB%88tiz%2F","usAudio":"/ai_services/tts3/?q=expertise&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9A%CB%88tiz%2F"},{"id":"lv_6_89","topic":"Business and Humanities Studies","word":"explosion","pos":"(n)","ipa":"/ɪkˈsploʊ.ʒən/","defVi":"vụ nổ, sự bùng nổ","defEn":"a violent burst with a loud noise, or a sudden, rapid increase","examples":["The gas [explosion] caused severe damage to several nearby buildings. (=Dịch: Vụ nổ khí gas đã gây thiệt hại nghiêm trọng cho nhiều tòa nhà lân cận.)","The last decade saw an [explosion] in the use of smartphones worldwide. (=Dịch: Thập kỷ vừa qua đã chứng kiến một sự bùng nổ trong việc sử dụng điện thoại thông minh trên toàn thế giới.)","Firefighters responded quickly to contain the fire following the [explosion]. (=Dịch: Lực lượng cứu hỏa đã phản ứng nhanh chóng để khống chế đám cháy sau vụ nổ.)"],"ukAudio":"/ai_services/tts3/?q=explosion&lang=en-GB&ipa=%2F%C9%AAk%CB%88splo%CA%8A.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=explosion&lang=en-US&ipa=%2F%C9%AAk%CB%88splo%CA%8A.%CA%92%C9%99n%2F"},{"id":"lv_6_90","topic":"Business and Humanities Studies","word":"extend","pos":"(v)","ipa":"/ɪkˈstend/","defVi":"kéo dài, mở rộng, gia hạn","defEn":"to make something longer, larger, or last for a greater period of time","examples":["The teacher agreed to [extend] the deadline for the final essay by three days. (=Dịch: Giáo viên đã đồng ý gia hạn thời hạn nộp bài luận cuối kỳ thêm ba ngày.)","The company plans to [extend] its railway network to rural areas. (=Dịch: Công ty dự định mở rộng mạng lưới đường sắt đến các vùng nông thôn.)","She decided to [extend] her holiday in Paris for another week. (=Dịch: Cô ấy quyết định kéo dài kỳ nghỉ tại Paris thêm một tuần nữa.)"],"ukAudio":"/ai_services/tts3/?q=extend&lang=en-GB&ipa=%2F%C9%AAk%CB%88stend%2F","usAudio":"/ai_services/tts3/?q=extend&lang=en-US&ipa=%2F%C9%AAk%CB%88stend%2F"},{"id":"lv_6_91","topic":"Business and Humanities Studies","word":"external","pos":"(adj)","ipa":"/ɪkˈstɝː.nəl/","defVi":"bên ngoài, ngoại lai","defEn":"connected with or situated on the outside of something","examples":["The company hired an [external] consultant to evaluate its marketing strategy. (=Dịch: Công ty đã thuê một chuyên gia tư vấn bên ngoài để đánh giá chiến lược tiếp thị của mình.)","The [external] walls of the museum were painted bright white. (=Dịch: Những bức tường bên ngoài của bảo tàng đã được sơn màu trắng sáng.)","Students are evaluated by an [external] examiner at the end of the semester. (=Dịch: Sinh viên được đánh giá bởi một giám khảo bên ngoài vào cuối học kỳ.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_6_92","topic":"Business and Humanities Studies","word":"factual","pos":"(adj)","ipa":"/ˈfæk.tʃu.əl/","defVi":"dựa trên sự thật, thực tế","defEn":"using or consisting of real facts and information rather than opinions","examples":["The documentary provides a [factual] account of the historic event. (=Dịch: Bộ phim tài liệu cung cấp một lời tường thuật dựa trên sự thật về sự kiện lịch sử.)","Please ensure that your essay contains only [factual] information. (=Dịch: Vui lòng đảm bảo rằng bài luận của bạn chỉ chứa thông tin thực tế.)","The report was criticized for several [factual] errors. (=Dịch: Báo cáo bị chỉ trích vì có một số lỗi sai về mặt sự thật.)"],"ukAudio":"/ai_services/tts3/?q=factual&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=factual&lang=en-US&ipa=%2F%CB%88f%C3%A6k.t%CA%83u.%C9%99l%2F"},{"id":"lv_6_93","topic":"Business and Humanities Studies","word":"fluent","pos":"(adj)","ipa":"/ˈflu.ənt/","defVi":"trôi chảy, lưu loát","defEn":"able to speak or write a language easily and accurately","examples":["She is [fluent] in English and Spanish. (=Dịch: Cô ấy nói tiếng Anh và tiếng Tây Ban Nha rất trôi chảy.)","He wants to become a [fluent] speaker before studying abroad. (=Dịch: Anh ấy muốn nói năng lưu loát trước khi đi du học.)","With regular practice, you will develop [fluent] conversation skills. (=Dịch: Nhờ luyện tập thường xuyên, bạn sẽ phát triển được kỹ năng giao tiếp trôi chảy.)"],"ukAudio":"/ai_services/tts3/?q=fluent&lang=en-GB&ipa=%2F%CB%88flu.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=fluent&lang=en-US&ipa=%2F%CB%88flu.%C9%99nt%2F"},{"id":"lv_6_94","topic":"Business and Humanities Studies","word":"flute","pos":"(n)","ipa":"/fluːt/","defVi":"cây sáo","defEn":"a musical wind instrument played by blowing across a hole near one end","examples":["She has been playing the [flute] in the school orchestra for three years. (=Dịch: Cô ấy đã chơi sáo trong dàn nhạc của trường được ba năm.)","The gentle melody of the [flute] filled the concert hall. (=Dịch: Giai điệu nhẹ nhàng của cây sáo vang vọng khắp khán phòng hòa nhạc.)","He bought a silver [flute] as a birthday present for his daughter. (=Dịch: Ông ấy đã mua một cây sáo bằng bạc làm quà sinh nhật cho con gái mình.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflu%CB%90t%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflu%CB%90t%2F"},{"id":"lv_6_95","topic":"Business and Humanities Studies","word":"follower","pos":"(n)","ipa":"/ˈfɑː.loʊ.ər/","defVi":"người theo dõi, tín đồ","defEn":"a person who supports, admires, or subscribes to someone or something","examples":["She gained more than one million [follower] accounts within a single week. (=Dịch: Cô ấy đã có thêm hơn một triệu tài khoản người theo dõi chỉ trong vòng một tuần.)","A great leader inspires trust and dedication in every [follower]. (=Dịch: Một nhà lãnh đạo tuyệt vời khơi dậy sự tin tưởng và cống hiến ở mỗi người đi theo.)","He has been a loyal [follower] of this philosophical school for decades. (=Dịch: Ông ấy đã là một môn đồ trung thành của trường phái triết học này suốt nhiều thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=follower&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90.lo%CA%8A.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=follower&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90.lo%CA%8A.%C9%99r%2F"},{"id":"lv_6_96","topic":"Business and Humanities Studies","word":"fraud","pos":"(n)","ipa":"/frɑːd/","defVi":"sự lừa đảo, hành vi gian lận","defEn":"the crime of deceiving someone to gain money or other benefits illegally","examples":["He was arrested and convicted of credit card [fraud]. (=Dịch: Anh ta đã bị bắt và kết án vì hành vi gian lận thẻ tín dụng.)","Banks invest heavily in security systems to prevent online [fraud]. (=Dịch: Các ngân hàng đầu tư mạnh vào các hệ thống bảo mật để ngăn chặn lừa đảo trực tuyến.)","The audit uncovered widespread financial [fraud] within the organization. (=Dịch: Cuộc kiểm toán đã phát hiện ra hành vi gian lận tài chính lan rộng trong tổ chức.)"],"ukAudio":"/ai_services/tts3/?q=fraud&lang=en-GB&ipa=%2Ffr%C9%91%CB%90d%2F","usAudio":"/ai_services/tts3/?q=fraud&lang=en-US&ipa=%2Ffr%C9%91%CB%90d%2F"},{"id":"lv_6_97","topic":"Business and Humanities Studies","word":"freedom","pos":"(n)","ipa":"/ˈfriː.dəm/","defVi":"sự tự do, quyền tự do","defEn":"the power or right to act, speak, or think without restraint or control","examples":["Every citizen deserves the basic [freedom] to express their opinions. (=Dịch: Mọi công dân đều xứng đáng có được quyền tự do cơ bản để bày tỏ ý kiến của mình.)","Working as a freelancer gives him greater creative [freedom]. (=Dịch: Làm việc tự do mang lại cho anh ấy nhiều sự tự do sáng tạo hơn.)","The treaty ensured political [freedom] and stability for the smaller nation. (=Dịch: Hiệp ước đã đảm bảo sự tự do chính trị và ổn định cho quốc gia nhỏ hơn.)"],"ukAudio":"/ai_services/tts3/?q=freedom&lang=en-GB&ipa=%2F%CB%88fri%CB%90.d%C9%99m%2F","usAudio":"/ai_services/tts3/?q=freedom&lang=en-US&ipa=%2F%CB%88fri%CB%90.d%C9%99m%2F"},{"id":"lv_6_98","topic":"Business and Humanities Studies","word":"frequency","pos":"(n)","ipa":"/ˈfriː.kwən.si/","defVi":"tần suất, tần số","defEn":"the rate at which something happens or is repeated over a particular period","examples":["The [frequency] of extreme weather events has increased in recent years. (=Dịch: Tần suất xảy ra các hiện tượng thời tiết cực đoan đã tăng lên trong những năm gần đây.)","Bus services run with greater [frequency] during morning rush hours. (=Dịch: Các tuyến xe buýt chạy với tần suất dày hơn vào giờ cao điểm buổi sáng.)","Scientists adjusted the radio [frequency] to improve signal reception. (=Dịch: Các nhà khoa học đã điều chỉnh tần số vô tuyến để cải thiện khả năng thu tín hiệu.)"],"ukAudio":"/ai_services/tts3/?q=frequency&lang=en-GB&ipa=%2F%CB%88fri%CB%90.kw%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=frequency&lang=en-US&ipa=%2F%CB%88fri%CB%90.kw%C9%99n.si%2F"},{"id":"lv_6_99","topic":"Business and Humanities Studies","word":"friendship","pos":"(n)","ipa":"/ˈfrend.ʃɪp/","defVi":"tình bạn, tình hữu nghị","defEn":"a relationship between people who are friends","examples":["Their [friendship] has lasted for more than twenty years despite the long distance. (=Dịch: Tình bạn của họ đã kéo dài hơn hai mươi năm bất chấp khoảng cách xa xôi.)","Trust and mutual respect are essential foundations of a lasting [friendship]. (=Dịch: Sự tin tưởng và tôn trọng lẫn nhau là những nền tảng thiết yếu của một tình bạn bền lâu.)","The two countries signed an agreement to strengthen their bilateral [friendship]. (=Dịch: Hai quốc gia đã ký một hiệp định nhằm thắt chặt mối quan hệ hữu nghị song phương.)"],"ukAudio":"/ai_services/tts3/?q=friendship&lang=en-GB&ipa=%2F%CB%88frend.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=friendship&lang=en-US&ipa=%2F%CB%88frend.%CA%83%C9%AAp%2F"},{"id":"lv_6_100","topic":"Business and Humanities Studies","word":"fulfil","pos":"(v)","ipa":"/fʊlˈfɪl/","defVi":"hoàn thành, đáp ứng hoặc thực hiện","defEn":"to achieve, satisfy, or do something that is promised, expected, or required","examples":["He worked tirelessly to [fulfil] his childhood dream of becoming a pilot. (=Dịch: Anh ấy đã làm việc không mệt mỏi để thực hiện ước mơ thuở nhỏ là trở thành phi công.)","The company must [fulfil] all legal requirements before launching the product. (=Dịch: Công ty phải đáp ứng mọi yêu cầu pháp lý trước khi tung sản phẩm ra thị trường.)","She failed to [fulfil] the expectations of her demanding supervisor. (=Dịch: Cô ấy đã không đáp ứng được kỳ vọng của người giám sát khó tính của mình.)"],"ukAudio":"/ai_services/tts3/?q=fulfil&lang=en-GB&ipa=%2Ff%CA%8Al%CB%88f%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=fulfil&lang=en-US&ipa=%2Ff%CA%8Al%CB%88f%C9%AAl%2F"},{"id":"lv_6_101","topic":"Business and Humanities Studies","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ, nguồn tiền","defEn":"an amount of money collected or saved for a particular purpose","examples":["The charity set up a special [fund] to help disaster victims. (=Dịch: Tổ chức từ thiện đã thành lập một quỹ đặc biệt để giúp đỡ các nạn nhân thiên tai.)","They are organizing an event to raise money for the research [fund]. (=Dịch: Họ đang tổ chức một sự kiện để gây quỹ cho hoạt động nghiên cứu.)","The university has an emergency [fund] for students facing financial hardship. (=Dịch: Trường đại học có một quỹ khẩn cấp dành cho những sinh viên gặp khó khăn về tài chính.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_6_102","topic":"Business and Humanities Studies","word":"gender","pos":"(n)","ipa":"/ˈdʒen.dɚ/","defVi":"giới tính","defEn":"the state of being male, female, or another identity, typically used with reference to social and cultural differences","examples":["The organization aims to promote [gender] equality in the workplace. (=Dịch: Tổ chức nhằm mục đích thúc đẩy bình đẳng giới tại nơi làm việc.)","Many companies are working to close the [gender] pay gap. (=Dịch: Nhiều công ty đang nỗ lực thu hẹp khoảng cách thu nhập theo giới tính.)","Applicants are asked to fill in their name, age, and [gender]. (=Dịch: Các ứng viên được yêu cầu điền tên, tuổi và giới tính của họ.)"],"ukAudio":"/ai_services/tts3/?q=gender&lang=en-GB&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gender&lang=en-US&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F"},{"id":"lv_6_103","topic":"Business and Humanities Studies","word":"generation","pos":"(n)","ipa":"/ˌdʒen.əˈreɪ.ʃən/","defVi":"thế hệ, thế hệ con người","defEn":"all of the people born and living at about the same time","examples":["The younger [generation] is generally much more comfortable with digital technology. (=Dịch: Thế hệ trẻ nhìn chung quen thuộc và thoải mái hơn nhiều với công nghệ số.)","Stories and traditions have been passed down from one [generation] to the next. (=Dịch: Những câu chuyện và truyền thống đã được truyền từ thế hệ này sang thế hệ khác.)","We must protect the environment to ensure a viable future for the next [generation]. (=Dịch: Chúng ta phải bảo vệ môi trường để đảm bảo một tương lai bền vững cho thế hệ sau.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92en.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92en.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_104","topic":"Business and Humanities Studies","word":"geology","pos":"(n)","ipa":"/dʒiˈɑ.lə.dʒi/","defVi":"địa chất học","defEn":"the scientific study of the earth's structure, rocks, and history","examples":["The students went on a field trip to study the local [geology]. (=Dịch: Các sinh viên đã có một chuyến đi thực tế để nghiên cứu địa chất địa phương.)","Her interest in rocks led her to study [geology] at university. (=Dịch: Sự yêu thích các loại đá đã dẫn dắt cô theo học ngành địa chất học tại trường đại học.)","The [geology] of the region indicates ancient volcanic activity. (=Dịch: Địa chất của khu vực này cho thấy hoạt động núi lửa thời cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=geology&lang=en-GB&ipa=%2Fd%CA%92i%CB%88%C9%91.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=geology&lang=en-US&ipa=%2Fd%CA%92i%CB%88%C9%91.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_105","topic":"Business and Humanities Studies","word":"german","pos":"(adj)","ipa":"/ˈdʒɜːr.mən/","defVi":"(thuộc) nước Đức, người Đức, tiếng Đức","defEn":"relating to Germany, its people, or its language","examples":["The museum is hosting an exhibition of modern [German] art this month. (=Dịch: Bảo tàng đang tổ chức một triển lãm nghệ thuật Đức hiện đại trong tháng này.)","Many international students choose to enroll in a [German] university. (=Dịch: Nhiều sinh viên quốc tế lựa chọn đăng ký học tại một trường đại học của Đức.)","She has been studying the [German] language for more than three years. (=Dịch: Cô ấy đã học tiếng Đức được hơn ba năm.)"],"ukAudio":"/ai_services/tts3/?q=german&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=german&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99n%2F"},{"id":"lv_6_106","topic":"Business and Humanities Studies","word":"grade","pos":"(n)","ipa":"/ɡreɪd/","defVi":"điểm số, cấp lớp hoặc thứ bậc","defEn":"a score showing the quality of a student's work, or a school year level","examples":["She worked very hard to get a good [grade] on her final exam. (=Dịch: Cô ấy đã học tập rất chăm chỉ để đạt điểm cao trong kỳ thi cuối kỳ.)","My younger brother is currently in the fifth [grade]. (=Dịch: Em trai tôi hiện đang học lớp năm.)","This store sells meat of the highest [grade]. (=Dịch: Cửa hàng này bán loại thịt có phẩm cấp cao nhất.)"],"ukAudio":"/ai_services/tts3/?q=grade&lang=en-GB&ipa=%2F%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=grade&lang=en-US&ipa=%2F%C9%A1re%C9%AAd%2F"},{"id":"lv_6_107","topic":"Business and Humanities Studies","word":"graph","pos":"(n)","ipa":"/ɡræf/","defVi":"biểu đồ, đồ thị","defEn":"a diagram that shows the relationship between two or more sets of numbers or measurements","examples":["The line [graph] clearly illustrates the rise in global temperatures over the last century. (=Dịch: Biểu đồ đường thể hiện rõ sự gia tăng nhiệt độ toàn cầu trong thế kỷ qua.)","Candidates in the IELTS exam are often asked to describe a [graph]. (=Dịch: Thí sinh trong kỳ thi IELTS thường được yêu cầu miêu tả một biểu đồ.)","According to the [graph], sales peaked in the fourth quarter. (=Dịch: Theo biểu đồ, doanh số đạt đỉnh vào quý bốn.)"],"ukAudio":"/ai_services/tts3/?q=graph&lang=en-GB&ipa=%2F%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=graph&lang=en-US&ipa=%2F%C9%A1r%C3%A6f%2F"},{"id":"lv_6_108","topic":"Business and Humanities Studies","word":"guideline","pos":"(n)","ipa":"/ˈɡaɪd.laɪn/","defVi":"hướng dẫn, nguyên tắc chỉ đạo","defEn":"a general rule, principle, or piece of advice","examples":["The government issued a new [guideline] on healthy eating. (=Dịch: Chính phủ đã ban hành một hướng dẫn mới về việc ăn uống lành mạnh.)","Make sure you follow the formatting [guideline] when writing your essay. (=Dịch: Hãy chắc chắn rằng bạn tuân theo hướng dẫn định dạng khi viết bài luận.)","The safety [guideline] helps reduce workplace accidents. (=Dịch: Nguyên tắc an toàn giúp giảm thiểu tai nạn tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=guideline&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AAd.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=guideline&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AAd.la%C9%AAn%2F"},{"id":"lv_6_109","topic":"Business and Humanities Studies","word":"gymnastics","pos":"(n)","ipa":"/dʒɪmˈnæs.tɪks/","defVi":"môn thể dục dụng cụ","defEn":"a sport involving exercises that require balance, strength, and flexibility","examples":["She has been practicing [gymnastics] since she was five years old. (=Dịch: Cô ấy đã tập luyện thể dục dụng cụ từ khi mới năm tuổi.)","The [gymnastics] competition attracted athletes from all over the world. (=Dịch: Cuộc thi thể dục dụng cụ đã thu hút các vận động viên từ khắp nơi trên thế giới.)","Doing [gymnastics] helps improve core strength and body coordination. (=Dịch: Tập thể dục dụng cụ giúp cải thiện sức mạnh cơ lõi và sự phối hợp của cơ thể.)"],"ukAudio":"/ai_services/tts3/?q=gymnastics&lang=en-GB&ipa=%2Fd%CA%92%C9%AAm%CB%88n%C3%A6s.t%C9%AAks%2F","usAudio":"/ai_services/tts3/?q=gymnastics&lang=en-US&ipa=%2Fd%CA%92%C9%AAm%CB%88n%C3%A6s.t%C9%AAks%2F"},{"id":"lv_6_110","topic":"Business and Humanities Studies","word":"handed","pos":"(adj)","ipa":"/ˈhæn.dɪd/","defVi":"thuận tay (kết hợp trong từ ghép như left-handed)","defEn":"having or using hands of a particular kind, especially using one hand more naturally than the other","examples":["He is left-[handed] and finds some scissors difficult to use. (=Dịch: Cậu ấy thuận tay trái và thấy một số loại kéo khá khó dùng.)","A two-[handed] backhand can give tennis players more power. (=Dịch: Cú đánh trái tay bằng hai tay có thể mang lại nhiều lực hơn cho các vận động viên quần vợt.)","The tool is designed for right-[handed] workers only. (=Dịch: Dụng cụ này chỉ được thiết kế dành riêng cho những người lao động thuận tay phải.)"],"ukAudio":"/ai_services/tts3/?q=handed&lang=en-GB&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=handed&lang=en-US&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd%2F"},{"id":"lv_6_111","topic":"Business and Humanities Studies","word":"handedness","pos":"(n)","ipa":"/ˈhæn.dɪd.nəs/","defVi":"thuận tay (tay phải hoặc tay trái)","defEn":"the tendency to use one hand rather than the other more naturally and skillfully","examples":["Genetic factors play a major role in determining a person's [handedness]. (=Dịch: Các yếu tố di truyền đóng vai trò quan trọng trong việc xác định độ thuận tay của một người.)","Researchers observed the [handedness] of chimpanzees during tool use experiments. (=Dịch: Các nhà nghiên cứu đã quan sát sự thuận tay của tinh tinh trong các thí nghiệm sử dụng công cụ.)","The school provides special scissors for students regardless of their [handedness]. (=Dịch: Trường cung cấp kéo đặc biệt cho học sinh bất kể các em thuận tay nào.)"],"ukAudio":"/ai_services/tts3/?q=handedness&lang=en-GB&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=handedness&lang=en-US&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd.n%C9%99s%2F"},{"id":"lv_6_112","topic":"Business and Humanities Studies","word":"highlight","pos":"(n)","ipa":"/ˈhaɪˌlaɪt/","defVi":"điểm nổi bật, phần đặc sắc nhất","defEn":"the most interesting, memorable, or important part of something","examples":["The boat tour along the coast was the [highlight] of our summer trip. (=Dịch: Chuyến tham quan bằng thuyền dọc bờ biển là điểm nổi bật nhất trong chuyến du lịch mùa hè của chúng tôi.)","The final goal was the main [highlight] of the entire football match. (=Dịch: Bàn thắng cuối cùng là khoảnh khắc ấn tượng nhất của toàn bộ trận bóng đá.)","Meeting the author was an unexpected [highlight] of the book fair. (=Dịch: Gặp gỡ tác giả là một điểm nhấn bất ngờ tại hội chợ sách.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA%CB%8Cla%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA%CB%8Cla%C9%AAt%2F"},{"id":"lv_6_113","topic":"Business and Humanities Studies","word":"hypothesis","pos":"(n)","ipa":"/haɪˈpɑː.θə.sɪs/","defVi":"giả thuyết","defEn":"an idea or explanation that is suggested and tested through study and experimentation","examples":["The results of the test supported their initial [hypothesis]. (=Dịch: Kết quả của cuộc thử nghiệm đã ủng hộ giả thuyết ban đầu của họ.)","A good scientist always seeks evidence to prove or disprove a [hypothesis]. (=Dịch: Một nhà khoa học giỏi luôn tìm kiếm bằng chứng để chứng minh hoặc bác bỏ một giả thuyết.)","She formulated a 새로운 [hypothesis] based on the unexpected findings. (=Dịch: Cô ấy đã đưa ra một giả thuyết mới dựa trên những phát hiện bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=hypothesis&lang=en-GB&ipa=%2Fha%C9%AA%CB%88p%C9%91%CB%90.%CE%B8%C9%99.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=hypothesis&lang=en-US&ipa=%2Fha%C9%AA%CB%88p%C9%91%CB%90.%CE%B8%C9%99.s%C9%AAs%2F"},{"id":"lv_6_114","topic":"Business and Humanities Studies","word":"iceland","pos":"(n)","ipa":"/ˈaɪs.lənd/","defVi":"nước Băng Đảo, quốc gia Ai-xơ-len","defEn":"an island country in the North Atlantic Ocean known for its natural landscapes","examples":["Many tourists visit [iceland] to see the stunning northern lights. (=Dịch: Nhiều du khách đến thăm Băng Đảo để ngắm hiện tượng cực quang tuyệt đẹp.)","Volcanoes and glaciers are common geological features of [iceland]. (=Dịch: Núi lửa và sông băng là những đặc điểm địa chất phổ biến của Băng Đảo.)","She booked a trip to explore the natural hot springs in [iceland]. (=Dịch: Cô ấy đã đặt một chuyến đi để khám phá các suối nước nóng tự nhiên ở Băng Đảo.)"],"ukAudio":"/ai_services/tts3/?q=iceland&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=iceland&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F"},{"id":"lv_6_115","topic":"Business and Humanities Studies","word":"icelanders","pos":"(n)","ipa":"/ˈaɪs.lən.dɚz/","defVi":"người Băng Đảo, người Ai-xơ-len","defEn":"the people who are native to or live in Iceland","examples":["Most [icelanders] speak fluent English in addition to their native language. (=Dịch: Hầu hết người Băng Đảo nói tiếng Anh trôi chảy bên cạnh tiếng mẹ đẻ của họ.)","Fishing has always played a vital role in the daily life of [icelanders]. (=Dịch: Đánh bắt cá luôn đóng một vai trò quan trọng trong đời sống hàng ngày của người Băng Đảo.)","Many [icelanders] enjoy reading books during the long winter nights. (=Dịch: Nhiều người Băng Đảo thích đọc sách trong những đêm mùa đông dài.)"],"ukAudio":"/ai_services/tts3/?q=icelanders&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99n.d%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=icelanders&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99n.d%C9%9Az%2F"},{"id":"lv_6_116","topic":"Business and Humanities Studies","word":"icelandic","pos":"(adj)","ipa":"/aɪsˈlæn.dɪk/","defVi":"thuộc về Ai-xơ-len (Băng Đảo)","defEn":"connected with Iceland, its people, or its language","examples":["We enjoyed traditional [icelandic] food during our holiday. (=Dịch: Chúng tôi đã thưởng thức các món ăn truyền thống của Ai-xơ-len trong suốt kỳ nghỉ.)","The [icelandic] landscape is famous for its volcanoes and glaciers. (=Dịch: Cảnh quan Ai-xơ-len nổi tiếng với những ngọn núi lửa và sông băng.)","Learning the [icelandic] language can be quite challenging for beginners. (=Dịch: Học tiếng Ai-xơ-len có thể khá thử thách đối với người mới bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=icelandic&lang=en-GB&ipa=%2Fa%C9%AAs%CB%88l%C3%A6n.d%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=icelandic&lang=en-US&ipa=%2Fa%C9%AAs%CB%88l%C3%A6n.d%C9%AAk%2F"},{"id":"lv_6_117","topic":"Business and Humanities Studies","word":"illegal","pos":"(adj)","ipa":"/ɪˈliː.ɡəl/","defVi":"bất hợp pháp, phạm pháp","defEn":"forbidden by law or against established rules","examples":["It is [illegal] to drive a car without a valid license. (=Dịch: Lái xe ô tô mà không có bằng lái hợp lệ là hành vi bất hợp pháp.)","The government took strict measures against [illegal] logging. (=Dịch: Chính phủ đã thực hiện các biện pháp nghiêm ngặt để chống lại nạn khai thác gỗ trái phép.)","Downloading copyrighted material without permission is [illegal]. (=Dịch: Tải xuống các tài liệu có bản quyền khi chưa được phép là phạm pháp.)"],"ukAudio":"/ai_services/tts3/?q=illegal&lang=en-GB&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=illegal&lang=en-US&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_6_118","topic":"Business and Humanities Studies","word":"impair","pos":"(v)","ipa":"/ɪmˈper/","defVi":"làm suy giảm, làm tổn hại, làm yếu đi","defEn":"to weaken, damage, or reduce the quality or strength of something","examples":["Lack of adequate sleep can severely [impair] your ability to concentrate. (=Dịch: Thiếu ngủ đủ giấc có thể làm suy giảm nghiêm trọng khả năng tập trung của bạn.)","Loud noises over prolonged periods may [impair] hearing permanently. (=Dịch: Tiếng ồn lớn trong thời gian dài có thể làm tổn hại thính giác vĩnh viễn.)","Alcohol consumption can [impair] a driver's reflexes and judgment. (=Dịch: Uống rượu bia có thể làm suy giảm phản xạ và khả năng phán đoán của người lái xe.)"],"ukAudio":"/ai_services/tts3/?q=impair&lang=en-GB&ipa=%2F%C9%AAm%CB%88per%2F","usAudio":"/ai_services/tts3/?q=impair&lang=en-US&ipa=%2F%C9%AAm%CB%88per%2F"},{"id":"lv_6_119","topic":"Business and Humanities Studies","word":"impose","pos":"(v)","ipa":"/ɪmˈpoʊz/","defVi":"áp đặt, đánh thuế, áp dụng","defEn":"to officially force a rule, tax, or punishment to be obeyed or accepted","examples":["The city council decided to [impose] a fine on illegal parking. (=Dịch: Hội đồng thành phố đã quyết định áp dụng mức phạt đối với hành vi đỗ xe trái phép.)","Parents should not [impose] their own career choices on their children. (=Dịch: Cha mẹ không nên áp đặt lựa chọn nghề nghiệp của mình lên con cái.)","The government may [impose] higher tariffs on imported goods. (=Dịch: Chính phủ có thể sẽ áp mức thuế quan cao hơn đối với hàng hóa nhập khẩu.)"],"ukAudio":"/ai_services/tts3/?q=impose&lang=en-GB&ipa=%2F%C9%AAm%CB%88po%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=impose&lang=en-US&ipa=%2F%C9%AAm%CB%88po%CA%8Az%2F"},{"id":"lv_6_120","topic":"Business and Humanities Studies","word":"inaccurate","pos":"(adj)","ipa":"/ɪnˈæk.jər.ət/","defVi":"không chính xác, sai lệch","defEn":"not correct or not completely exact","examples":["The initial weather forecast turned out to be completely [inaccurate]. (=Dịch: Dự báo thời tiết ban đầu hóa ra hoàn toàn không chính xác.)","Using outdated data led to an [inaccurate] conclusion. (=Dịch: Việc sử dụng dữ liệu lỗi thời đã dẫn đến một kết luận thiếu chính xác.)","The article was retracted because it contained [inaccurate] statistics. (=Dịch: Bài báo đã bị rút lại vì nó chứa các số liệu thống kê sai lệch.)"],"ukAudio":"/ai_services/tts3/?q=inaccurate&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C3%A6k.j%C9%99r.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=inaccurate&lang=en-US&ipa=%2F%C9%AAn%CB%88%C3%A6k.j%C9%99r.%C9%99t%2F"},{"id":"lv_6_121","topic":"Business and Humanities Studies","word":"inclusive","pos":"(adj)","ipa":"/ɪnˈkluː.sɪv/","defVi":"bao quát, mang tính hòa nhập, bao hàm toàn diện","defEn":"deliberately including all types of people, things, or opinions","examples":["The school strives to create an [inclusive] environment for students with disabilities. (=Dịch: Nhà trường nỗ lực tạo ra một môi trường hòa nhập cho học sinh khuyết tật.)","The resort offers an [inclusive] package that covers all meals and activities. (=Dịch: Khu nghỉ dưỡng cung cấp gói trọn gói bao gồm tất cả các bữa ăn và hoạt động.)","We need more [inclusive] policies that consider the needs of minority groups. (=Dịch: Chúng ta cần nhiều chính sách mang tính bao hàm hơn để tính đến nhu cầu của các nhóm thiểu số.)"],"ukAudio":"/ai_services/tts3/?q=inclusive&lang=en-GB&ipa=%2F%C9%AAn%CB%88klu%CB%90.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=inclusive&lang=en-US&ipa=%2F%C9%AAn%CB%88klu%CB%90.s%C9%AAv%2F"},{"id":"lv_6_122","topic":"Business and Humanities Studies","word":"independence","pos":"(n)","ipa":"/ˌɪn.dɪˈpɛn.dəns/","defVi":"Sự độc lập, tự chủ","defEn":"The state of being free from outside control or influence.","examples":["The nation celebrated fifty years of [independence] with grand parades. (=Dịch: Quốc gia này đã kỷ niệm 50 năm ngày giành độc lập bằng các cuộc diễu hành lớn.)","Going to university teaches young adults financial and personal [independence]. (=Dịch: Vào đại học dạy cho những người trẻ tuổi sự độc lập về tài chính và cá nhân.)","She values her professional [independence] and prefers working as a freelancer. (=Dịch: Cô ấy coi trọng sự độc lập trong công việc và thích làm nghề tự do hơn.)"],"ukAudio":"/ai_services/tts3/?q=independence&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.d%C9%AA%CB%88p%C9%9Bn.d%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=independence&lang=en-US&ipa=%2F%CB%8C%C9%AAn.d%C9%AA%CB%88p%C9%9Bn.d%C9%99ns%2F"},{"id":"lv_6_123","topic":"Business and Humanities Studies","word":"initial","pos":"(adj)","ipa":"/ɪˈnɪʃ.əl/","defVi":"ban đầu, đầu tiên","defEn":"happening at the beginning; first","examples":["Our [initial] plan was to travel by train, but we decided to fly instead. (=Dịch: Kế hoạch ban đầu của chúng tôi là đi bằng tàu hỏa, nhưng sau đó chúng tôi quyết định đi máy bay.)","The company's [initial] investment proved to be highly profitable. (=Dịch: Khoản đầu tư ban đầu của công ty đã chứng minh là mang lại lợi nhuận rất cao.)","After overcoming the [initial] difficulties, she began to enjoy her new job. (=Dịch: Sau khi vượt qua những khó khăn ban đầu, cô ấy bắt đầu thấy yêu thích công việc mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=initial&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=initial&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_6_124","topic":"Business and Humanities Studies","word":"initiative","pos":"(n)","ipa":"/ɪˈnɪʃ.ə.tɪv/","defVi":"sáng kiến, chương trình hành động mới","defEn":"a new plan or process designed to solve a problem or achieve a goal","examples":["The government launched an educational [initiative] to promote digital literacy. (=Dịch: Chính phủ đã đưa ra một sáng kiến giáo dục nhằm nâng cao hiểu biết về công nghệ số.)","Employees are encouraged to take the [initiative] and suggest improvements. (=Dịch: Nhân viên được khuyến khích chủ động đưa ra các đề xuất cải tiến.)","This recycling [initiative] has helped reduce neighborhood waste significantly. (=Dịch: Sáng kiến tái chế này đã giúp giảm lượng rác thải trong khu dân cư một cách đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=initiative&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=initiative&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.t%C9%AAv%2F"},{"id":"lv_6_125","topic":"Business and Humanities Studies","word":"innovation","pos":"(n)","ipa":"/ˌɪn.əˈveɪ.ʃən/","defVi":"sự đổi mới, sáng kiến mới","defEn":"a new idea, method, or product; the introduction of something new","examples":["Technological [innovation] has transformed the way we communicate. (=Dịch: Sự đổi mới công nghệ đã thay đổi cách chúng ta giao tiếp.)","The company encourages employee [innovation] through monthly brainstorming sessions. (=Dịch: Công ty khuyến khích sự đổi mới của nhân viên thông qua các buổi họp lên ý tưởng hàng tháng.)","This smart device is the latest [innovation] in healthcare monitoring. (=Dịch: Thiết bị thông minh này là sáng kiến mới nhất trong việc theo dõi sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=innovation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=innovation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_126","topic":"Business and Humanities Studies","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự hiểu biết sâu sắc, cái nhìn sâu sắc","defEn":"a deep and clear understanding of a complicated problem or situation","examples":["The study provides valuable [insight] into the causes of climate change. (=Dịch: Nghiên cứu này cung cấp cái nhìn sâu sắc và có giá trị về nguyên nhân của biến đổi khí hậu.)","Her extensive experience gave her unique [insight] into customer behavior. (=Dịch: Kinh nghiệm dày dặn đã mang lại cho cô cái nhìn sâu sắc độc đáo về hành vi của khách hàng.)","The lecture offered fresh [insight] on modern economic challenges. (=Dịch: Bài giảng đã mang đến những góc nhìn mới mẻ về các thách thức kinh tế hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_6_127","topic":"Business and Humanities Studies","word":"insist","pos":"(v)","ipa":"/ɪnˈsɪst/","defVi":"khăng khăng, nằng nặc đòi hoặc khẳng định chắc chắn","defEn":"to demand something forcefully or maintain a statement firmly","examples":["My parents [insist] that I finish my homework before watching TV. (=Dịch: Bố mẹ tôi khăng khăng bắt tôi phải làm xong bài tập trước khi xem tivi.)","He continued to [insist] on his innocence despite the evidence. (=Dịch: Anh ta tiếp tục khẳng định mình vô tội bất chấp các bằng chứng.)","They [insist] that all visitors must wear a security badge. (=Dịch: Họ nhất quyết yêu cầu mọi khách tham quan phải đeo thẻ an ninh.)"],"ukAudio":"/ai_services/tts3/?q=insist&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=insist&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%AAst%2F"},{"id":"lv_6_128","topic":"Business and Humanities Studies","word":"inspire","pos":"(v)","ipa":"/ɪnˈspaɪ.ɚ/","defVi":"truyền cảm hứng, khuyến khích","defEn":"to give someone the motivation or enthusiasm to do something","examples":["Her speech will [inspire] many young students to study science. (=Dịch: Bài phát biểu của cô ấy sẽ truyền cảm hứng cho nhiều học sinh trẻ theo đuổi ngành khoa học.)","The beauty of the mountains can [inspire] great art. (=Dịch: Vẻ đẹp của những ngọn núi có thể truyền cảm hứng cho các tác phẩm nghệ thuật tuyệt vời.)","His success continues to [inspire] people around the world. (=Dịch: Thành công của anh ấy tiếp tục truyền cảm hứng cho mọi người trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=inspire&lang=en-GB&ipa=%2F%C9%AAn%CB%88spa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=inspire&lang=en-US&ipa=%2F%C9%AAn%CB%88spa%C9%AA.%C9%9A%2F"},{"id":"lv_6_129","topic":"Business and Humanities Studies","word":"instant","pos":"(adj)","ipa":"/ˈɪn.stənt/","defVi":"tức thì, ngay lập tức","defEn":"happening immediately or made quickly","examples":["The new social media campaign became an [instant] success. (=Dịch: Chiến dịch truyền thông mạng xã hội mới đã trở thành một thành công ngay lập tức.)","Many busy workers rely on [instant] coffee to start their mornings. (=Dịch: Nhiều nhân viên bận rộn dựa vào cà phê hòa tan để bắt đầu buổi sáng của họ.)","Mobile apps provide users with [instant] access to news updates. (=Dịch: Các ứng dụng di động cung cấp cho người dùng quyền truy cập tin tức cập nhật tức thì.)"],"ukAudio":"/ai_services/tts3/?q=instant&lang=en-GB&ipa=%2F%CB%88%C9%AAn.st%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=instant&lang=en-US&ipa=%2F%CB%88%C9%AAn.st%C9%99nt%2F"},{"id":"lv_6_130","topic":"Business and Humanities Studies","word":"intellectual","pos":"(adj)","ipa":"/ˌɪn.təˈlɛk.tʃu.əl/","defVi":"thuộc về trí tuệ, có tri thức","defEn":"relating to the ability to think logically and understand complex ideas","examples":["Chess is a game that requires significant [intellectual] effort and focus. (=Dịch: Cờ vua là một trò chơi đòi hỏi sự nỗ lực trí tuệ và mức độ tập trung đáng kể.)","University provides a stimulating [intellectual] environment for research. (=Dịch: Trường đại học mang lại một môi trường học thuật trí tuệ đầy tính kích thích cho việc nghiên cứu.)","She enjoys engaging in deep [intellectual] discussions with her colleagues. (=Dịch: Cô ấy thích tham gia vào các cuộc thảo luận học thuật mang tính trí tuệ sâu sắc với đồng nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=intellectual&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88l%C9%9Bk.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=intellectual&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88l%C9%9Bk.t%CA%83u.%C9%99l%2F"},{"id":"lv_6_131","topic":"Business and Humanities Studies","word":"intelligence","pos":"(n)","ipa":"/ɪnˈtɛl.ə.dʒəns/","defVi":"trí thông minh, sự thông minh","defEn":"the ability to learn, understand, and make judgments or have opinions","examples":["Emotional [intelligence] is just as important as academic ability in the workplace. (=Dịch: Trí tuệ cảm xúc cũng quan trọng không kém gì năng lực học thuật tại nơi làm việc.)","Scientists are studying whether certain animals possess high [intelligence]. (=Dịch: Các nhà khoa học đang nghiên cứu xem liệu một số loài động vật có sở hữu trí thông minh cao hay không.)","The rapid development of artificial [intelligence] is reshaping modern industries. (=Dịch: Sự phát triển nhanh chóng của trí tuệ nhân tạo đang tái định hình các ngành công nghiệp hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=intelligence&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=intelligence&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F"},{"id":"lv_6_132","topic":"Business and Humanities Studies","word":"interaction","pos":"(n)","ipa":"/ˌɪn.tərˈæk.ʃən/","defVi":"sự tương tác, sự giao tiếp","defEn":"communication or direct involvement with someone or something","examples":["Social [interaction] is essential for a child's psychological development. (=Dịch: Tương tác xã hội rất cần thiết cho sự phát triển tâm lý của trẻ em.)","The classroom activities encourage active [interaction] between students. (=Dịch: Các hoạt động trong lớp học khuyến khích sự tương tác tích cực giữa các học sinh.)","Scientists study the complex [interaction] between humans and the environment. (=Dịch: Các nhà khoa học nghiên cứu sự tương tác phức tạp giữa con người và môi trường.)"],"ukAudio":"/ai_services/tts3/?q=interaction&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99r%CB%88%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interaction&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99r%CB%88%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_6_133","topic":"Business and Humanities Studies","word":"interviewee","pos":"(n)","ipa":"/ˌɪn.tər.vjuːˈiː/","defVi":"người được phỏng vấn","defEn":"a person who answers questions in an interview","examples":["The [interviewee] answered every question with confidence and clarity. (=Dịch: Người được phỏng vấn đã trả lời mọi câu hỏi một cách tự tin và rõ ràng.)","Each [interviewee] was given fifteen minutes to present their portfolio. (=Dịch: Mỗi ứng viên phỏng vấn được dành 15 phút để trình bày hồ sơ năng lực của mình.)","The researcher recorded the audio of each [interviewee] with their permission. (=Dịch: Nhà nghiên cứu đã ghi âm từng người được phỏng vấn với sự cho phép của họ.)"],"ukAudio":"/ai_services/tts3/?q=interviewee&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99r.vju%CB%90%CB%88i%CB%90%2F","usAudio":"/ai_services/tts3/?q=interviewee&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99r.vju%CB%90%CB%88i%CB%90%2F"},{"id":"lv_6_134","topic":"Business and Humanities Studies","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, sự khảo sát kỹ lưỡng","defEn":"an official examination of the facts about a situation, crime, etc.","examples":["The police launched a thorough [investigation] into the cause of the fire. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về nguyên nhân của vụ hỏa hoạn.)","An internal [investigation] revealed widespread financial misconduct. (=Dịch: Một cuộc điều tra nội bộ đã vạch trần sai phạm tài chính trên diện rộng.)","The incident is currently under [investigation] by federal authorities. (=Dịch: Sự việc hiện đang được các cơ quan chức năng liên bang điều tra.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_135","topic":"Business and Humanities Studies","word":"isolate","pos":"(v)","ipa":"/ˈaɪ.sə.leɪt/","defVi":"cô lập, cách ly, tách rời","defEn":"to separate someone or something from other people or things","examples":["Doctors decided to [isolate] the patient to prevent the disease from spreading. (=Dịch: Các bác sĩ quyết định cách ly bệnh nhân để ngăn căn bệnh lây lan.)","Scientists managed to [isolate] the specific gene responsible for the condition. (=Dịch: Các nhà khoa học đã tách riêng được loại gen chịu trách nhiệm gây ra tình trạng này.)","Heavy snowfall can easily [isolate] mountain villages from the rest of the country. (=Dịch: Tuyết rơi dày có thể dễ dàng cô lập các ngôi làng trên núi khỏi phần còn lại của đất nước.)"],"ukAudio":"/ai_services/tts3/?q=isolate&lang=en-GB&ipa=%2F%CB%88a%C9%AA.s%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=isolate&lang=en-US&ipa=%2F%CB%88a%C9%AA.s%C9%99.le%C9%AAt%2F"},{"id":"lv_6_136","topic":"Business and Humanities Studies","word":"italy","pos":"(n)","ipa":"/ˈɪt̬.əl.i/","defVi":"nước Ý, nước I-ta-li-a","defEn":"a country in southern Europe known for its rich history, culture, and cuisine","examples":["Many tourists visit [Italy] every year to see ancient Roman architecture. (=Dịch: Nhiều du khách đến thăm nước Ý hàng năm để chiêm ngưỡng kiến trúc La Mã cổ đại.)","She spent her summer studying art history in [Italy]. (=Dịch: Cô ấy đã dành mùa hè của mình để học lịch sử nghệ thuật ở Ý.)","[Italy] is famous worldwide for its delicious food, fashion, and art. (=Dịch: Ý nổi tiếng trên toàn thế giới về ẩm thực ngon, thời trang và nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=italy&lang=en-GB&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=italy&lang=en-US&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F"},{"id":"lv_6_137","topic":"Business and Humanities Studies","word":"justify","pos":"(v)","ipa":"/ˈdʒʌs.tə.faɪ/","defVi":"biện minh, chứng minh là hợp lý hoặc đúng đắn","defEn":"to show or prove that something is reasonable, necessary, or right","examples":["The manager had to [justify] the extra expenses to the director. (=Dịch: Người quản lý đã phải giải trình các khoản chi phí phát sinh trước giám đốc.)","Nothing can [justify] such rude behavior toward customers. (=Dịch: Không gì có thể biện minh cho hành vi thô lỗ như vậy đối với khách hàng.)","You must [justify] your conclusions with concrete data in your essay. (=Dịch: Bạn phải chứng minh các kết luận của mình bằng dữ liệu cụ thể trong bài luận.)"],"ukAudio":"/ai_services/tts3/?q=justify&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8Cs.t%C9%99.fa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=justify&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8Cs.t%C9%99.fa%C9%AA%2F"},{"id":"lv_6_138","topic":"Business and Humanities Studies","word":"kart","pos":"(n)","ipa":"/kɑːrt/","defVi":"xe đua mini (xe go-kart)","defEn":"a small, open motor vehicle with four wheels, used mainly for racing","examples":["He spent his weekend driving a go-[kart] with his friends at the track. (=Dịch: Anh ấy đã dành kỳ nghỉ cuối tuần lái xe đua mini cùng bạn bè trên đường đua.)","Many professional Formula One drivers started their racing careers in a [kart]. (=Dịch: Nhiều tay đua Công thức 1 chuyên nghiệp đã bắt đầu sự nghiệp đua xe của mình bằng xe đua mini.)","Safety helmets and gloves are required before you get into the [kart]. (=Dịch: Mũ bảo hiểm và găng tay an toàn là bắt buộc trước khi bạn bước vào xe đua mini.)"],"ukAudio":"/ai_services/tts3/?q=kart&lang=en-GB&ipa=%2Fk%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=kart&lang=en-US&ipa=%2Fk%C9%91%CB%90rt%2F"},{"id":"lv_6_139","topic":"Business and Humanities Studies","word":"keyboard","pos":"(n)","ipa":"/ˈki.bɔrd/","defVi":"bàn phím (máy tính hoặc nhạc cụ)","defEn":"a set of keys on a computer or musical instrument used for typing or playing music","examples":["She wiped the dust off her computer [keyboard] before starting work. (=Dịch: Cô ấy lau sạch bụi trên bàn phím máy tính trước khi bắt đầu làm việc.)","He learned to play the electric [keyboard] when he was ten years old. (=Dịch: Anh ấy đã học chơi đàn phím điện tử khi mới mười tuổi.)","A mechanical [keyboard] can improve typing speed and comfort. (=Dịch: Một chiếc bàn phím cơ có thể cải thiện tốc độ và sự thoải mái khi gõ phím.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki.b%C9%94rd%2F"},{"id":"lv_6_140","topic":"Business and Humanities Studies","word":"laterality","pos":"(n)","ipa":"/ˌlæt̬.əˈræl.ə.t̬i/","defVi":"tính thuận một bên (như thuận tay phải hoặc trái)","defEn":"the preference for using one side of the body, such as being right- or left-handed","examples":["Handedness is the most common form of human [laterality]. (=Dịch: Sự thuận tay là hình thức phổ biến nhất của tính thuận một bên ở con người.)","The study investigated brain [laterality] and language processing. (=Dịch: Nghiên cứu đã điều tra tính chuyên biệt bán cầu não và quá trình xử lý ngôn ngữ.)","Researchers measured [laterality] in animals to understand brain development. (=Dịch: Các nhà nghiên cứu đã đo lường tính thuận một bên ở động vật để hiểu về sự phát triển của não bộ.)"],"ukAudio":"/ai_services/tts3/?q=laterality&lang=en-GB&ipa=%2F%CB%8Cl%C3%A6t%CC%AC.%C9%99%CB%88r%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=laterality&lang=en-US&ipa=%2F%CB%8Cl%C3%A6t%CC%AC.%C9%99%CB%88r%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_6_141","topic":"Business and Humanities Studies","word":"lifespan","pos":"(n)","ipa":"/ˈlaɪf.spæn/","defVi":"tuổi thọ, vòng đời","defEn":"the length of time for which a person or animal lives or a thing functions","examples":["Medical advances have significantly increased the human [lifespan]. (=Dịch: Những tiến bộ y học đã làm tăng đáng kể tuổi thọ của con người.)","Proper maintenance can extend the [lifespan] of your car engine. (=Dịch: Bảo dưỡng đúng cách có thể kéo dài tuổi thọ động cơ ô tô của bạn.)","Some species of tortoises have an average [lifespan] of over a century. (=Dịch: Một số loài rùa cạn có tuổi thọ trung bình trên một thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=lifespan&lang=en-GB&ipa=%2F%CB%88la%C9%AAf.sp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=lifespan&lang=en-US&ipa=%2F%CB%88la%C9%AAf.sp%C3%A6n%2F"},{"id":"lv_6_142","topic":"Business and Humanities Studies","word":"loneliness","pos":"(n)","ipa":"/ˈloʊn.li.nəs/","defVi":"sự cô đơn, nỗi cô quạnh","defEn":"a feeling of sadness because one has no friends or company","examples":["Elderly people who live alone often suffer from severe [loneliness]. (=Dịch: Người cao tuổi sống một mình thường phải chịu đựng sự cô đơn sâu sắc.)","Moving to a new city can trigger feelings of isolation and [loneliness]. (=Dịch: Chuyển đến một thành phố mới có thể gây ra cảm giác bị cô lập và cô đơn.)","She took up painting as a creative way to cope with [loneliness]. (=Dịch: Cô ấy bắt đầu vẽ tranh như một cách sáng tạo để đối phó với nỗi cô đơn.)"],"ukAudio":"/ai_services/tts3/?q=loneliness&lang=en-GB&ipa=%2F%CB%88lo%CA%8An.li.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=loneliness&lang=en-US&ipa=%2F%CB%88lo%CA%8An.li.n%C9%99s%2F"},{"id":"lv_6_143","topic":"Business and Humanities Studies","word":"lonely","pos":"(adj)","ipa":"/ˈloʊn.li/","defVi":"cô đơn, lẻ loi, quạnh quẽ","defEn":"sad because one has no friends or company","examples":["Moving to a foreign city made him feel isolated and [lonely] at first. (=Dịch: Việc chuyển đến một thành phố xa lạ ban đầu khiến anh cảm thấy bị cô lập và cô đơn.)","Volunteers visit [lonely] seniors in nursing homes to offer companionship. (=Dịch: Các tình nguyện viên đến thăm những người già cô đơn trong viện dưỡng lão để bầu bạn cùng họ.)","The lighthouse stood on a [lonely] stretch of the rocky coastline. (=Dịch: Ngọn hải đăng đứng sừng sững trên một dải bờ biển đá quạnh quẽ.)"],"ukAudio":"/ai_services/tts3/?q=lonely&lang=en-GB&ipa=%2F%CB%88lo%CA%8An.li%2F","usAudio":"/ai_services/tts3/?q=lonely&lang=en-US&ipa=%2F%CB%88lo%CA%8An.li%2F"},{"id":"lv_6_144","topic":"Business and Humanities Studies","word":"loss","pos":"(n)","ipa":"/lɔːs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state of no longer having something or having less of it","examples":["The company reported a massive financial [loss] in the final quarter. (=Dịch: Công ty đã báo cáo một khoản thua lỗ tài chính khổng lồ trong quý cuối cùng.)","Diet and exercise are effective strategies for sustainable weight [loss]. (=Dịch: Chế độ ăn uống và tập thể dục là những chiến lược hiệu quả để giảm cân bền vững.)","Deforestation leads to an irreversible [loss] of biodiversity. (=Dịch: Nạn phá rừng dẫn đến sự mất mát không thể khắc phục của đa dạng sinh học.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94%CB%90s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94%CB%90s%2F"},{"id":"lv_6_145","topic":"Business and Humanities Studies","word":"luxury","pos":"(n)","ipa":"/ˈlʌk.ʃə.ri/","defVi":"sự xa xỉ, sang trọng hoặc hàng xa xỉ phẩm","defEn":"great comfort and extravagant living, or something expensive and not essential","examples":["They stayed in a five-star hotel and enjoyed the ultimate [luxury]. (=Dịch: Họ đã ở tại một khách sạn năm sao và tận hưởng sự xa hoa bậc nhất.)","During the economic crisis, dining out became an unaffordable [luxury] for many. (=Dịch: Trong cuộc khủng hoảng kinh tế, đi ăn ngoài đã trở thành một sự xa xỉ khó với tới đối với nhiều người.)","The brand is internationally known for designing high-end [luxury] goods. (=Dịch: Thương hiệu này nổi tiếng quốc tế với việc thiết kế các mặt hàng xa xỉ cao cấp.)"],"ukAudio":"/ai_services/tts3/?q=luxury&lang=en-GB&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=luxury&lang=en-US&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%99.ri%2F"},{"id":"lv_6_146","topic":"Business and Humanities Studies","word":"mentally","pos":"(adv)","ipa":"/ˈmɛn.tə.li/","defVi":"về mặt tinh thần, về mặt tâm trí","defEn":"in a way that relates to the mind or mental processes","examples":["Athletes must prepare [mentally] as well as physically for the race. (=Dịch: Các vận động viên phải chuẩn bị cả về tinh thần lẫn thể chất cho cuộc đua.)","Solving complex puzzles helps keep people [mentally] sharp. (=Dịch: Giải các câu đố phức tạp giúp giữ cho đầu óc con người luôn minh mẫn.)","She felt [mentally] exhausted after a long day of negotiations. (=Dịch: Cô ấy cảm thấy kiệt sức về mặt tinh thần sau một ngày dài đàm phán.)"],"ukAudio":"/ai_services/tts3/?q=mentally&lang=en-GB&ipa=%2F%CB%88m%C9%9Bn.t%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=mentally&lang=en-US&ipa=%2F%CB%88m%C9%9Bn.t%C9%99.li%2F"},{"id":"lv_6_147","topic":"Business and Humanities Studies","word":"methodology","pos":"(n)","ipa":"/ˌmeθ.əˈdɑː.lə.dʒi/","defVi":"phương pháp luận, phương pháp nghiên cứu","defEn":"a system of methods and principles used in a particular discipline or study","examples":["The research paper clearly outlines the [methodology] used to gather data. (=Dịch: Bài báo nghiên cứu trình bày rõ ràng phương pháp luận được dùng để thu thập dữ liệu.)","We adopted a new [methodology] to improve the efficiency of our project. (=Dịch: Chúng tôi đã áp dụng một phương pháp nghiên cứu mới để nâng cao hiệu quả của dự án.)","Critics questioned the [methodology] behind the controversial survey. (=Dịch: Các nhà phê bình đã đặt câu hỏi về phương pháp luận đằng sau cuộc khảo sát gây tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=methodology&lang=en-GB&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=methodology&lang=en-US&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_148","topic":"Business and Humanities Studies","word":"motivation","pos":"(n)","ipa":"/ˌmoʊ.t̬əˈveɪ.ʃən/","defVi":"động lực","defEn":"the reason or desire that drives someone to act or achieve a goal","examples":["Financial reward is not the only [motivation] for employees to work hard. (=Dịch: Phần thưởng tài chính không phải là động lực duy nhất để nhân viên làm việc chăm chỉ.)","She lost the [motivation] to study after failing the midterm exam. (=Dịch: Cô ấy đã mất động lực học tập sau khi thi trượt kỳ thi giữa kỳ.)","Setting clear goals can boost your daily [motivation] and productivity. (=Dịch: Đặt ra các mục tiêu rõ ràng có thể thúc đẩy động lực và năng suất hàng ngày của bạn.)"],"ukAudio":"/ai_services/tts3/?q=motivation&lang=en-GB&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motivation&lang=en-US&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_149","topic":"Business and Humanities Studies","word":"networking","pos":"(n)","ipa":"/ˈnet.wɜːr.kɪŋ/","defVi":"hoạt động kết nối, xây dựng mạng lưới quan hệ","defEn":"the activity of meeting people who might be useful to know for your career or business","examples":["Attending industry conferences is a great way to improve your [networking] skills. (=Dịch: Tham dự các hội nghị ngành là một cách tuyệt vời để cải thiện kỹ năng kết nối quan hệ của bạn.)","Professional [networking] helped him secure a high-paying job abroad. (=Dịch: Việc mở rộng mạng lưới quan hệ nghề nghiệp đã giúp anh ấy có được một công việc lương cao ở nước ngoài.)","Social media platforms have revolutionized business [networking] in recent years. (=Dịch: Các nền tảng mạng xã hội đã cách mạng hóa việc xây dựng mạng lưới kinh doanh trong những năm gần đây.)"],"ukAudio":"/ai_services/tts3/?q=networking&lang=en-GB&ipa=%2F%CB%88net.w%C9%9C%CB%90r.k%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=networking&lang=en-US&ipa=%2F%CB%88net.w%C9%9C%CB%90r.k%C9%AA%C5%8B%2F"},{"id":"lv_6_150","topic":"Business and Humanities Studies","word":"nursing","pos":"(n)","ipa":"/ˈnɜr.sɪŋ/","defVi":"ngành điều dưỡng, nghề y tá","defEn":"the profession or practice of caring for sick or injured people","examples":["She decided to pursue a career in [nursing] after volunteering at a hospital. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp trong ngành điều dưỡng sau khi làm tình nguyện tại một bệnh viện.)","The university offers a four-year degree in [nursing]. (=Dịch: Trường đại học cung cấp chương trình cấp bằng bốn năm về ngành điều dưỡng.)","Good [nursing] care is essential for a patient's quick recovery. (=Dịch: Sự chăm sóc điều dưỡng tốt là rất cần thiết cho sự hồi phục nhanh chóng của bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=nursing&lang=en-GB&ipa=%2F%CB%88n%C9%9Cr.s%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=nursing&lang=en-US&ipa=%2F%CB%88n%C9%9Cr.s%C9%AA%C5%8B%2F"},{"id":"lv_6_151","topic":"Business and Humanities Studies","word":"nurture","pos":"(v)","ipa":"/ˈnɝː.tʃɚ/","defVi":"nuôi dưỡng, bồi dưỡng","defEn":"to care for and encourage the growth or development of someone or something","examples":["Parents strive to [nurture] a love of reading in their young children. (=Dịch: Các bậc cha mẹ nỗ lực nuôi dưỡng niềm yêu thích đọc sách ở con nhỏ.)","The program was designed to [nurture] new musical talent across the nation. (=Dịch: Chương trình được thiết kế để bồi dưỡng những tài năng âm nhạc mới trên toàn quốc.)","Good managers know how to [nurture] positive relationships among team members. (=Dịch: Những người quản lý giỏi biết cách nuôi dưỡng các mối quan hệ tích cực giữa các thành viên trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=nurture&lang=en-GB&ipa=%2F%CB%88n%C9%9D%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=nurture&lang=en-US&ipa=%2F%CB%88n%C9%9D%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_6_152","topic":"Business and Humanities Studies","word":"obesity","pos":"(n)","ipa":"/oʊˈbiː.sə.t̬i/","defVi":"bệnh béo phì, tình trạng béo phì","defEn":"the state of being extremely overweight in a way that is dangerous for health","examples":["Childhood [obesity] has become a major public health concern globally. (=Dịch: Béo phì ở trẻ em đã trở thành một mối lo ngại lớn về sức khỏe cộng đồng trên toàn cầu.)","A balanced diet and daily exercise can help prevent [obesity]. (=Dịch: Chế độ ăn uống cân bằng và tập thể dục hàng ngày có thể giúp ngăn ngừa béo phì.)","The government launched a campaign to raise awareness about the risks of [obesity]. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao nhận thức về những nguy cơ của bệnh béo phì.)"],"ukAudio":"/ai_services/tts3/?q=obesity&lang=en-GB&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=obesity&lang=en-US&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_6_153","topic":"Business and Humanities Studies","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, theo dõi","defEn":"the act of watching something carefully, especially to learn more about it","examples":["The doctor kept the patient under close [observation] overnight. (=Dịch: Bác sĩ đã giữ bệnh nhân lại để theo dõi chặt chẽ qua đêm.)","Scientific discoveries often begin with a simple [observation] in the natural world. (=Dịch: Các phát hiện khoa học thường bắt đầu bằng một quan sát đơn giản trong thế giới tự nhiên.)","Her keen powers of [observation] helped her notice subtle clues at the scene. (=Dịch: Khả năng quan sát nhạy bén đã giúp cô nhận ra những manh mối tinh tế tại hiện trường.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_154","topic":"Business and Humanities Studies","word":"opener","pos":"(n)","ipa":"/ˈoʊ.pən.ər/","defVi":"dụng cụ mở (chai, hộp); trận/vở diễn mở màn","defEn":"a device used for opening tins, bottles, or other containers; an initial event","examples":["Could you please pass me the bottle [opener] from the kitchen counter? (=Dịch: Bạn có thể làm ơn đưa giúp tôi cái mở nắp chai từ kệ bếp được không?)","The team won their season [opener] by two goals. (=Dịch: Đội bóng đã giành chiến thắng trong trận đấu mở màn mùa giải với cách biệt hai bàn.)","She used a can [opener] to prepare the soup for dinner. (=Dịch: Cô ấy đã dùng đồ khui đồ hộp để chuẩn bị món súp cho bữa tối.)"],"ukAudio":"/ai_services/tts3/?q=opener&lang=en-GB&ipa=%2F%CB%88o%CA%8A.p%C9%99n.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=opener&lang=en-US&ipa=%2F%CB%88o%CA%8A.p%C9%99n.%C9%99r%2F"},{"id":"lv_6_155","topic":"Business and Humanities Studies","word":"operational","pos":"(adj)","ipa":"/ˌɑː.pəˈreɪ.ʃən.əl/","defVi":"sẵn sàng hoạt động, đang vận hành; thuộc về vận hành","defEn":"ready to be used, working properly, or relating to the functioning of an organization","examples":["The new airport terminal will become fully [operational] next month. (=Dịch: Nhà ga sân bay mới sẽ đi vào hoạt động đầy đủ vào tháng tới.)","The company managed to reduce its [operational] costs by adopting new software. (=Dịch: Công ty đã cắt giảm được chi phí vận hành bằng cách áp dụng phần mềm mới.)","All emergency systems are currently tested and fully [operational]. (=Dịch: Tất cả các hệ thống khẩn cấp hiện đã được kiểm tra và hoàn toàn sẵn sàng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=operational&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=operational&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_156","topic":"Business and Humanities Studies","word":"oral","pos":"(adj)","ipa":"/ˈɔːr.əl/","defVi":"bằng lời nói, truyền miệng; thuộc về miệng","defEn":"spoken rather than written; relating to the mouth","examples":["Students must pass an [oral] examination in French before graduating. (=Dịch: Sinh viên phải vượt qua kỳ thi vấn đáp tiếng Pháp trước khi tốt nghiệp.)","Good [oral] hygiene helps prevent tooth decay and gum disease. (=Dịch: Vệ sinh răng miệng tốt giúp ngăn ngừa sâu răng và bệnh về nướu.)","The story was preserved through [oral] tradition for centuries. (=Dịch: Câu chuyện đã được lưu truyền qua truyền thống truyền miệng suốt nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=oral&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=oral&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F"},{"id":"lv_6_157","topic":"Business and Humanities Studies","word":"orient","pos":"(v)","ipa":"/ˈɔr.iˌɛnt/","defVi":"định hướng, hướng dẫn làm quen","defEn":"to direct someone or something toward a particular goal, idea, or direction","examples":["The training program aims to [orient] new employees to the company's work culture. (=Dịch: Chương trình đào tạo nhằm mục đích định hướng cho các nhân viên mới về văn hóa làm việc của công ty.)","It took him a few minutes to [orient] himself after stepping out of the subway station. (=Dịch: Anh ấy mất vài phút để định hướng phương hướng sau khi bước ra khỏi ga tàu điện ngầm.)","The course is designed to [orient] students toward practical career skills. (=Dịch: Khóa học được thiết kế để hướng sinh viên tới các kỹ năng nghề nghiệp thực tế.)"],"ukAudio":"/ai_services/tts3/?q=orient&lang=en-GB&ipa=%2F%CB%88%C9%94r.i%CB%8C%C9%9Bnt%2F","usAudio":"/ai_services/tts3/?q=orient&lang=en-US&ipa=%2F%CB%88%C9%94r.i%CB%8C%C9%9Bnt%2F"},{"id":"lv_6_158","topic":"Business and Humanities Studies","word":"overhead","pos":"(adj)","ipa":"/ˌoʊ.vərˈhed/","defVi":"ở trên đầu, trên cao","defEn":"located, positioned, or operating above one's head","examples":["Passengers placed their luggage in the [overhead] compartment. (=Dịch: Hành khách đã đặt hành lý của họ vào khoang chứa đồ phía trên đầu.)","A flock of birds flew across the [overhead] sky. (=Dịch: Một đàn chim bay ngang qua bầu trời phía trên cao.)","The city plans to replace [overhead] power cables with underground systems. (=Dịch: Thành phố có kế hoạch thay thế hệ thống cáp điện trên cao bằng mạng lưới ngầm.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%88hed%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%88hed%2F"},{"id":"lv_6_159","topic":"Business and Humanities Studies","word":"pedal","pos":"(n)","ipa":"/ˈpɛd.əl/","defVi":"bàn đạp (xe đạp, xe hơi, đàn piano)","defEn":"a foot-operated lever used to control or propel a vehicle or machine","examples":["Press the brake [pedal] firmly to stop the car safely. (=Dịch: Hãy đạp mạnh bàn đạp phanh để dừng xe an toàn.)","His foot slipped off the bicycle [pedal] while riding uphill. (=Dịch: Chân của cậu ấy bị trượt khỏi bàn đạp xe đạp khi đang lên dốc.)","The pianist skillfully used the sustain [pedal] during the performance. (=Dịch: Nghệ sĩ dương cầm đã sử dụng bàn đạp vang một cách điêu luyện trong suốt buổi biểu diễn.)"],"ukAudio":"/ai_services/tts3/?q=pedal&lang=en-GB&ipa=%2F%CB%88p%C9%9Bd.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=pedal&lang=en-US&ipa=%2F%CB%88p%C9%9Bd.%C9%99l%2F"},{"id":"lv_6_160","topic":"Business and Humanities Studies","word":"pioneer","pos":"(n)","ipa":"/ˌpaɪ.əˈnɪr/","defVi":"người tiên phong, người mở đường","defEn":"a person who is one of the first to develop an area, idea, or activity","examples":["Marie Curie was a [pioneer] in the field of radioactivity research. (=Dịch: Marie Curie là người tiên phong trong lĩnh vực nghiên cứu phóng xạ.)","The company is considered a [pioneer] of renewable energy solutions. (=Dịch: Công ty được coi là đơn vị tiên phong về các giải pháp năng lượng tái tạo.)","Early aviation [pioneer] figures paved the way for modern travel. (=Dịch: Những nhân vật tiên phong trong ngành hàng không thời kỳ đầu đã mở đường cho ngành du lịch hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=pioneer&lang=en-GB&ipa=%2F%CB%8Cpa%C9%AA.%C9%99%CB%88n%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=pioneer&lang=en-US&ipa=%2F%CB%8Cpa%C9%AA.%C9%99%CB%88n%C9%AAr%2F"},{"id":"lv_6_161","topic":"Business and Humanities Studies","word":"pleasure","pos":"(n)","ipa":"/ˈpleʒ.ɚ/","defVi":"sự thích thú, niềm vui thích, hân hạnh","defEn":"a feeling of happy satisfaction and enjoyment","examples":["Reading fiction books gives her a great deal of [pleasure]. (=Dịch: Đọc tiểu thuyết mang lại cho cô ấy rất nhiều niềm vui thích.)","It was an absolute [pleasure] to meet your family today. (=Dịch: Thật là một niềm vinh hạnh tuyệt đối khi được gặp gia đình bạn hôm nay.)","He plays the guitar purely for his own [pleasure]. (=Dịch: Anh ấy chơi đàn ghi-ta hoàn toàn chỉ để thỏa mãn niềm vui của riêng mình.)"],"ukAudio":"/ai_services/tts3/?q=pleasure&lang=en-GB&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=pleasure&lang=en-US&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F"},{"id":"lv_6_162","topic":"Business and Humanities Studies","word":"podcast","pos":"(n)","ipa":"/ˈpɑːd.kæst/","defVi":"tập tin âm thanh kỹ thuật số, chương trình phát thanh số","defEn":"a digital audio recording made available on the internet for downloading or streaming","examples":["I usually listen to an educational [podcast] on my way to work. (=Dịch: Tôi thường nghe một chương trình phát thanh giáo dục trên đường đi làm.)","She decided to start her own [podcast] about modern literature. (=Dịch: Cô ấy quyết định bắt đầu chương trình podcast của riêng mình về văn học hiện đại.)","This weekly [podcast] covers the latest scientific discoveries. (=Dịch: Chương trình phát thanh hàng tuần này đưa tin về những phát hiện khoa học mới nhất.)"],"ukAudio":"/ai_services/tts3/?q=podcast&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90d.k%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=podcast&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90d.k%C3%A6st%2F"},{"id":"lv_6_163","topic":"Business and Humanities Studies","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, sáng suốt, thận trọng","defEn":"showing good judgment, wise, and prudent in practical matters","examples":["It seemed [politic] to remain silent during the heated debate. (=Dịch: Giữ im lặng trong cuộc tranh luận gay gắt dường như là điều khôn ngoan.)","She decided that a [politic] apology would resolve the conflict quickly. (=Dịch: Cô ấy quyết định rằng một lời xin lỗi khôn khéo sẽ nhanh chóng giải quyết xung đột.)","In business negotiations, a [politic] response is often better than a blunt refusal. (=Dịch: Trong các cuộc đàm phán kinh doanh, một phản hồi thận trọng thường tốt hơn là lời từ chối thẳng thừng.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_6_164","topic":"Business and Humanities Studies","word":"poorly","pos":"(adv)","ipa":"/ˈpʊr.li/","defVi":"kém cỏi, tồi tàn, không tốt","defEn":"badly, inadequately, or to an unsatisfactory standard","examples":["The old bridge was [poorly] maintained and needed urgent repairs. (=Dịch: Cây cầu cũ được bảo trì kém và cần được sửa chữa khẩn cấp.)","She performed [poorly] on the exam due to lack of sleep. (=Dịch: Cô ấy làm bài thi kém do bị thiếu ngủ.)","The room was [poorly] lit, making it hard to read anything. (=Dịch: Căn phòng thiếu ánh sáng, khiến việc đọc sách trở nên khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=poorly&lang=en-GB&ipa=%2F%CB%88p%CA%8Ar.li%2F","usAudio":"/ai_services/tts3/?q=poorly&lang=en-US&ipa=%2F%CB%88p%CA%8Ar.li%2F"},{"id":"lv_6_165","topic":"Business and Humanities Studies","word":"preference","pos":"(n)","ipa":"/ˈprɛf.ɚ.əns/","defVi":"sở thích, sự ưu tiên","defEn":"a greater liking for one alternative over another","examples":["Consumers have a strong [preference] for organic and eco-friendly products. (=Dịch: Người tiêu dùng có sự ưu tiên mạnh mẽ đối với các sản phẩm hữu cơ và thân thiện với môi trường.)","Please state your dietary [preference] when registering for the conference. (=Dịch: Vui lòng nêu rõ sở thích ăn uống của bạn khi đăng ký tham dự hội nghị.)","He expressed a [preference] for working remotely rather than in the office. (=Dịch: Anh ấy bày tỏ sự thích làm việc từ xa hơn là làm tại văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=preference&lang=en-GB&ipa=%2F%CB%88pr%C9%9Bf.%C9%9A.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=preference&lang=en-US&ipa=%2F%CB%88pr%C9%9Bf.%C9%9A.%C9%99ns%2F"},{"id":"lv_6_166","topic":"Business and Humanities Studies","word":"prevention","pos":"(n)","ipa":"/prɪˈven.ʃən/","defVi":"sự phòng ngừa, sự ngăn chặn","defEn":"the act of stopping something bad or dangerous from happening","examples":["Crime [prevention] is one of the main responsibilities of the local police. (=Dịch: Phòng chống tội phạm là một trong những trách nhiệm chính của cảnh sát địa phương.)","The government launched a public campaign on fire [prevention] during the dry season. (=Dịch: Chính phủ đã phát động một chiến dịch tuyên truyền về phòng cháy trong mùa khô.)","Proper diet and exercise are key elements in disease [prevention]. (=Dịch: Chế độ ăn uống hợp lý và tập thể dục là những yếu tố then chốt trong việc phòng ngừa bệnh tật.)"],"ukAudio":"/ai_services/tts3/?q=prevention&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88ven.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=prevention&lang=en-US&ipa=%2Fpr%C9%AA%CB%88ven.%CA%83%C9%99n%2F"},{"id":"lv_6_167","topic":"Business and Humanities Studies","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a fundamental truth, law, or moral rule that guides behavior","examples":["She refused to lie because it went against her moral [principle]. (=Dịch: Cô ấy từ chối nói dối vì điều đó đi ngược lại nguyên tắc đạo đức của mình.)","The machine operates on a very simple physical [principle]. (=Dịch: Cỗ máy hoạt động dựa trên một nguyên lý vật lý rất đơn giản.)","Equality is a core [principle] of any democratic society. (=Dịch: Bình đẳng là nguyên tắc cốt lõi của bất kỳ xã hội dân chủ nào.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_6_168","topic":"Business and Humanities Studies","word":"problematic","pos":"(adj)","ipa":"/ˌprɑː.bləˈmæt̬.ɪk/","defVi":"nan giải, phức tạp, nhiều vấn đề","defEn":"full of difficulties, problems, or uncertainties","examples":["Implementing the new tax policy turned out to be extremely [problematic]. (=Dịch: Việc thực thi chính sách thuế mới hóa ra lại cực kỳ nan giải.)","The lack of reliable public transport makes commuting [problematic] for residents. (=Dịch: Việc thiếu phương tiện giao thông công cộng đáng tin cậy khiến việc đi lại của cư dân gặp nhiều khó khăn.)","His aggressive behavior during meetings became increasingly [problematic]. (=Dịch: Hành vi gây hấn của anh ta trong các cuộc họp ngày càng trở nên có vấn đề.)"],"ukAudio":"/ai_services/tts3/?q=problematic&lang=en-GB&ipa=%2F%CB%8Cpr%C9%91%CB%90.bl%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=problematic&lang=en-US&ipa=%2F%CB%8Cpr%C9%91%CB%90.bl%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_6_169","topic":"Business and Humanities Studies","word":"profit","pos":"(n)","ipa":"/ˈprɑː.fɪt/","defVi":"lợi nhuận","defEn":"money that is earned in business after paying the costs of producing and selling goods and services","examples":["The company made a healthy [profit] in its first year of operation. (=Dịch: Công ty đã đạt mức lợi nhuận khả quan trong năm đầu hoạt động.)","They decided to sell the property for a substantial [profit]. (=Dịch: Họ quyết định bán bất động sản đó để kiếm một khoản lợi nhuận đáng kể.)","A drop in sales led to a sharp decrease in net [profit]. (=Dịch: Sự sụt giảm doanh số đã dẫn đến việc lợi nhuận ròng giảm mạnh. Giang)"],"ukAudio":"/ai_services/tts3/?q=profit&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=profit&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F"},{"id":"lv_6_170","topic":"Business and Humanities Studies","word":"profitable","pos":"(adj)","ipa":"/ˈprɑː.fɪ.t̬ə.bəl/","defVi":"có lãi, sinh lời, có lợi","defEn":"yielding financial gain or beneficial results","examples":["The company developed a new and highly [profitable] product line. (=Dịch: Công ty đã phát triển một dòng sản phẩm mới và mang lại lợi nhuận rất cao.)","Online advertising proved to be a [profitable] strategy for small businesses. (=Dịch: Quảng cáo trực tuyến đã được chứng minh là một chiến lược sinh lời cho các doanh nghiệp nhỏ.)","They had a [profitable] discussion about improving workplace efficiency. (=Dịch: Họ đã có một cuộc thảo luận hữu ích về việc cải thiện hiệu quả làm việc.)"],"ukAudio":"/ai_services/tts3/?q=profitable&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AA.t%CC%AC%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=profitable&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AA.t%CC%AC%C9%99.b%C9%99l%2F"},{"id":"lv_6_171","topic":"Business and Humanities Studies","word":"promotion","pos":"(n)","ipa":"/prəˈmoʊ.ʃən/","defVi":"sự thăng tiến, sự xúc tiến / khuyến mãi","defEn":"a move to a higher position or rank; an activity to boost sales","examples":["Her hard work earned her a well-deserved [promotion] at work. (=Dịch: Sự chăm chỉ đã mang lại cho cô ấy một đợt thăng chức rất xứng đáng tại nơi làm việc.)","The supermarket is running a special [promotion] on dairy products. (=Dịch: Siêu thị đang có chương trình khuyến mãi đặc biệt cho các sản phẩm từ sữa.)","The campaign aims at the [promotion] of healthy eating habits. (=Dịch: Chiến dịch nhằm mục đích thúc đẩy thói quen ăn uống lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=promotion&lang=en-GB&ipa=%2Fpr%C9%99%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=promotion&lang=en-US&ipa=%2Fpr%C9%99%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_6_172","topic":"Business and Humanities Studies","word":"prompt","pos":"(adj)","ipa":"/prɑːmpt/","defVi":"nhanh chóng, kịp thời","defEn":"done quickly and without delay","examples":["Thank you for your [prompt] reply to my email. (=Dịch: Cảm ơn bạn đã phản hồi thư điện tử của tôi một cách nhanh chóng.)","A [prompt] action is required to solve the water shortage. (=Dịch: Cần có hành động kịp thời để giải quyết tình trạng thiếu nước.)","The staff provided [prompt] service to all the guests. (=Dịch: Nhân viên đã phục vụ nhanh chóng cho tất cả các vị khách.)"],"ukAudio":"/ai_services/tts3/?q=prompt&lang=en-GB&ipa=%2Fpr%C9%91%CB%90mpt%2F","usAudio":"/ai_services/tts3/?q=prompt&lang=en-US&ipa=%2Fpr%C9%91%CB%90mpt%2F"},{"id":"lv_6_173","topic":"Business and Humanities Studies","word":"prospect","pos":"(n)","ipa":"/ˈprɑː.spekt/","defVi":"triển vọng, khả năng trong tương lai","defEn":"the possibility or likelihood of some future event occurring","examples":["Graduating with honors will improve your job [prospect]s significantly. (=Dịch: Tốt nghiệp loại giỏi sẽ cải thiện đáng kể triển vọng việc làm của bạn.)","The [prospect] of a long holiday excited all the employees. (=Dịch: Viễn cảnh về một kỳ nghỉ dài khiến tất cả nhân viên vô cùng hào hứng.)","There is little [prospect] of the weather improving before the weekend. (=Dịch: Có rất ít khả năng thời tiết sẽ cải thiện trước cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=prospect&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.spekt%2F","usAudio":"/ai_services/tts3/?q=prospect&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.spekt%2F"},{"id":"lv_6_174","topic":"Business and Humanities Studies","word":"psychology","pos":"(n)","ipa":"/saɪˈkɑː.lə.dʒi/","defVi":"tâm lý học, tâm lý","defEn":"the scientific study of the human mind and behavior","examples":["She decided to study [psychology] to better understand why people make certain choices. (=Dịch: Cô ấy quyết định học tâm lý học để hiểu rõ hơn lý do tại sao mọi người đưa ra những lựa chọn nhất định.)","Advertisers often use consumer [psychology] to design effective marketing campaigns. (=Dịch: Các nhà quảng cáo thường vận dụng tâm lý người tiêu dùng để thiết kế các chiến dịch tiếp thị hiệu quả.)","Educational [psychology] helps teachers adapt their methods to different student needs. (=Dịch: Tâm lý học giáo dục giúp giáo viên điều chỉnh phương pháp phù hợp với các nhu cầu khác nhau của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=psychology&lang=en-GB&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=psychology&lang=en-US&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_175","topic":"Business and Humanities Studies","word":"punishment","pos":"(n)","ipa":"/ˈpʌn.ɪʃ.mənt/","defVi":"sự trừng phạt, hình phạt","defEn":"a penalty imposed on someone for committing an offense or crime","examples":["The judge handed down a strict [punishment] for the serious offense. (=Dịch: Vị thẩm phán đã đưa ra hình phạt nghiêm khắc cho hành vi phạm tội nghiêm trọng.)","Corporal [punishment] is banned in modern educational institutions. (=Dịch: Hình phạt thể xác đã bị cấm trong các cơ sở giáo dục hiện đại.)","He had to clean the classroom as a [punishment] for being late. (=Dịch: Cậu bé phải dọn dẹp phòng học như một hình phạt cho việc đi muộn.)"],"ukAudio":"/ai_services/tts3/?q=punishment&lang=en-GB&ipa=%2F%CB%88p%CA%8Cn.%C9%AA%CA%83.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=punishment&lang=en-US&ipa=%2F%CB%88p%CA%8Cn.%C9%AA%CA%83.m%C9%99nt%2F"},{"id":"lv_6_176","topic":"Business and Humanities Studies","word":"recall","pos":"(v)","ipa":"/rɪˈkɑːl/","defVi":"nhớ lại, hồi tưởng","defEn":"to remember something from the past","examples":["I cannot [recall] the exact date of the meeting. (=Dịch: Tôi không thể nhớ lại ngày chính xác của cuộc họp.)","Old photographs help him [recall] his childhood memories. (=Dịch: Những bức ảnh cũ giúp ông ấy nhớ lại những kỷ niệm thời thơ ấu.)","She could easily [recall] the details of the conversation. (=Dịch: Cô ấy có thể dễ dàng nhớ lại các chi tiết của cuộc trò chuyện.)"],"ukAudio":"/ai_services/tts3/?q=recall&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=recall&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%C9%91%CB%90l%2F"},{"id":"lv_6_177","topic":"Business and Humanities Studies","word":"recruit","pos":"(n)","ipa":"/rɪˈkruːt/","defVi":"thành viên mới, tân binh","defEn":"a person who has recently joined an organization, company, or the armed forces","examples":["Each new [recruit] must complete a two-week training program. (=Dịch: Mỗi nhân viên mới đều phải hoàn thành một chương trình đào tạo kéo dài hai tuần.)","The military [recruit] struggled during the first few days of physical training. (=Dịch: Người tân binh đã gặp nhiều khó khăn trong những ngày đầu huấn luyện thể lực.)","The team welcomed a talented [recruit] with strong analytical skills. (=Dịch: Nhóm đã chào đón một thành viên mới tài năng với kỹ năng phân tích tốt.)"],"ukAudio":"/ai_services/tts3/?q=recruit&lang=en-GB&ipa=%2Fr%C9%AA%CB%88kru%CB%90t%2F","usAudio":"/ai_services/tts3/?q=recruit&lang=en-US&ipa=%2Fr%C9%AA%CB%88kru%CB%90t%2F"},{"id":"lv_6_178","topic":"Business and Humanities Studies","word":"reform","pos":"(n)","ipa":"/rɪˈfɔrm/","defVi":"sự cải cách, sự đổi mới","defEn":"an improvement or change for the better, especially in a system or law","examples":["The government introduced an educational [reform] to improve school facilities. (=Dịch: Chính phủ đã đưa ra một cuộc cải cách giáo dục nhằm cải thiện cơ sở vật chất trường học.)","Economic [reform] has helped many small businesses thrive in the region. (=Dịch: Cải cách kinh tế đã giúp nhiều doanh nghiệp nhỏ phát triển mạnh mẽ trong khu vực.)","There is an urgent need for tax [reform] in our country. (=Dịch: Đất nước chúng ta đang có nhu cầu cấp thiết về việc cải cách thuế.)"],"ukAudio":"/ai_services/tts3/?q=reform&lang=en-GB&ipa=%2Fr%C9%AA%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=reform&lang=en-US&ipa=%2Fr%C9%AA%CB%88f%C9%94rm%2F"},{"id":"lv_6_179","topic":"Business and Humanities Studies","word":"regulatory","pos":"(adj)","ipa":"/ˈreɡ.jə.lə.tɔːr.i/","defVi":"thuộc về quy định, mang tính quản lý","defEn":"relating to the control or management of an activity by official rules","examples":["The company had to meet strict [regulatory] standards before launching the product. (=Dịch: Công ty phải đáp ứng các tiêu chuẩn quy định nghiêm ngặt trước khi ra mắt sản phẩm.)","Government [regulatory] agencies monitor financial institutions closely. (=Dịch: Các cơ quan quản lý của chính phủ giám sát chặt chẽ các tổ chức tài chính.)","Recent changes in the [regulatory] framework affected international trade. (=Dịch: Những thay đổi gần đây trong khung pháp lý đã ảnh hưởng đến thương mại quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=regulatory&lang=en-GB&ipa=%2F%CB%88re%C9%A1.j%C9%99.l%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=regulatory&lang=en-US&ipa=%2F%CB%88re%C9%A1.j%C9%99.l%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_6_180","topic":"Business and Humanities Studies","word":"relevance","pos":"(n)","ipa":"/ˈrel.ə.vəns/","defVi":"sự liên quan, tính thích hợp","defEn":"the state of being closely connected or appropriate to the matter at hand","examples":["The professor questioned the [relevance] of that data to the main research topic. (=Dịch: Giáo sư đã đặt câu hỏi về mức độ liên quan của dữ liệu đó đối với đề tài nghiên cứu chính.)","Ancient philosophies still hold strong [relevance] to our lives today. (=Dịch: Các triết lý cổ đại vẫn có sự gắn kết sâu sắc với cuộc sống của chúng ta ngày nay.)","Candidates should ensure the direct [relevance] of their skills to the job description. (=Dịch: Các ứng viên nên đảm bảo kỹ năng của mình có sự phù hợp trực tiếp với mô tả công việc.)"],"ukAudio":"/ai_services/tts3/?q=relevance&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=relevance&lang=en-US&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F"},{"id":"lv_6_181","topic":"Business and Humanities Studies","word":"respondent","pos":"(n)","ipa":"/rɪˈspɑːn.dənt/","defVi":"người trả lời (khảo sát, phỏng vấn)","defEn":"a person who answers questions, especially in a survey or questionnaire","examples":["Over sixty percent of each [respondent] agreed with the proposed policy. (=Dịch: Hơn sáu mươi phần trăm số người trả lời đã đồng ý với chính sách được đề xuất.)","Each [respondent] was asked to complete an online questionnaire. (=Dịch: Mỗi người trả lời đều được yêu cầu hoàn thành một bảng câu hỏi trực tuyến.)","The researcher guaranteed that every [respondent] would remain anonymous. (=Dịch: Nhà nghiên cứu đảm bảo rằng danh tính của mọi người trả lời sẽ được giữ kín.)"],"ukAudio":"/ai_services/tts3/?q=respondent&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=respondent&lang=en-US&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F"},{"id":"lv_6_182","topic":"Business and Humanities Studies","word":"retention","pos":"(n)","ipa":"/rɪˈten.ʃən/","defVi":"sự duy trì, sự giữ lại, khả năng ghi nhớ","defEn":"the continued possession, use, or control of something; the ability to remember information","examples":["Visual aids can significantly improve the [retention] of complex information. (=Dịch: Các phương tiện trực quan có thể cải thiện đáng kể khả năng ghi nhớ thông tin phức tạp.)","The company implemented new benefits to improve employee [retention]. (=Dịch: Công ty đã áp dụng các phúc lợi mới để cải thiện việc giữ chân nhân viên.)","Good soil structure enhances water [retention] during dry seasons. (=Dịch: Cấu trúc đất tốt giúp tăng cường khả năng giữ nước trong mùa khô.)"],"ukAudio":"/ai_services/tts3/?q=retention&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ten.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=retention&lang=en-US&ipa=%2Fr%C9%AA%CB%88ten.%CA%83%C9%99n%2F"},{"id":"lv_6_183","topic":"Business and Humanities Studies","word":"retirement","pos":"(n)","ipa":"/rɪˈtaɪr.mənt/","defVi":"sự nghỉ hưu, thời gian sau khi nghỉ hưu","defEn":"the act of leaving one's job and stopping work, usually because of reaching a certain age","examples":["Many people look forward to a peaceful [retirement] after decades of hard work. (=Dịch: Nhiều người mong đợi một cuộc sống nghỉ hưu yên bình sau nhiều thập kỷ làm việc vất vả.)","He decided to take early [retirement] due to health issues. (=Dịch: Ông ấy quyết định nghỉ hưu sớm vì lý do sức khỏe.)","She joined a local gardening club soon after her [retirement]. (=Dịch: Bà ấy đã tham gia một câu lạc bộ làm vườn tại địa phương ngay sau khi nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retirement&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AAr.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=retirement&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AAr.m%C9%99nt%2F"},{"id":"lv_6_184","topic":"Business and Humanities Studies","word":"retrieval","pos":"(n)","ipa":"/rɪˈtriː.vəl/","defVi":"sự truy xuất, việc lấy lại","defEn":"the process of finding and getting something back, especially stored information","examples":["The new software allows for faster data [retrieval]. (=Dịch: Phần mềm mới cho phép truy xuất dữ liệu nhanh hơn.)","Effective information [retrieval] is essential for modern search engines. (=Dịch: Việc truy xuất thông tin hiệu quả là điều cốt yếu đối với các công cụ tìm kiếm hiện đại.)","The divers assisted in the [retrieval] of the sunken treasure. (=Dịch: Các thợ lặn đã hỗ trợ việc thu hồi kho báu bị chìm.)"],"ukAudio":"/ai_services/tts3/?q=retrieval&lang=en-GB&ipa=%2Fr%C9%AA%CB%88tri%CB%90.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=retrieval&lang=en-US&ipa=%2Fr%C9%AA%CB%88tri%CB%90.v%C9%99l%2F"},{"id":"lv_6_185","topic":"Business and Humanities Studies","word":"retrieve","pos":"(v)","ipa":"/rɪˈtriv/","defVi":"lấy lại, khôi phục hoặc tìm lại","defEn":"to find and bring something back from a place","examples":["The dog was trained to [retrieve] fallen birds for the hunter. (=Dịch: Chú chó được huấn luyện để nhặt những con chim bị bắn rơi về cho người thợ săn.)","It took several hours to [retrieve] the lost data from the damaged hard drive. (=Dịch: Mất vài giờ để khôi phục lại dữ liệu bị mất từ ổ cứng bị hỏng.)","She went back to the classroom to [retrieve] her forgotten jacket. (=Dịch: Cô ấy quay lại lớp học để lấy chiếc áo khoác bị bỏ quên.)"],"ukAudio":"/ai_services/tts3/?q=retrieve&lang=en-GB&ipa=%2Fr%C9%AA%CB%88triv%2F","usAudio":"/ai_services/tts3/?q=retrieve&lang=en-US&ipa=%2Fr%C9%AA%CB%88triv%2F"},{"id":"lv_6_186","topic":"Business and Humanities Studies","word":"reward","pos":"(n)","ipa":"/rɪˈwɔːrd/","defVi":"phần thưởng","defEn":"something given or received in return for good work, effort, or behavior","examples":["She received a cash [reward] for finding the lost wallet. (=Dịch: Cô ấy đã nhận được một phần thưởng tiền mặt vì tìm thấy chiếc ví bị mất.)","Hard work often brings its own [reward] in the long run. (=Dịch: Sự chăm chỉ thường mang lại phần thưởng xứng đáng về lâu dài.)","The company offers travel vouchers as a [reward] for outstanding employees. (=Dịch: Công ty tặng phiếu du lịch như một phần thưởng dành cho những nhân viên xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=reward&lang=en-GB&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=reward&lang=en-US&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90rd%2F"},{"id":"lv_6_187","topic":"Business and Humanities Studies","word":"robbery","pos":"(n)","ipa":"/ˈrɑː.bɚ.i/","defVi":"vụ cướp, tội cướp đoạt tài sản","defEn":"the crime of stealing money or goods from a person or place using violence or threats","examples":["Police are investigating an armed [robbery] that occurred downtown last night. (=Dịch: Cảnh sát đang điều tra một vụ cướp có vũ trang xảy ra ở trung tâm thành phố đêm qua.)","The bank [robbery] was planned with extreme precision. (=Dịch: Vụ cướp ngân hàng đã được lên kế hoạch vô cùng tỉ mỉ.)","He was sentenced to five years in prison for street [robbery]. (=Dịch: Anh ta bị kết án năm năm tù vì tội cướp giật trên đường phố.)"],"ukAudio":"/ai_services/tts3/?q=robbery&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.b%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=robbery&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.b%C9%9A.i%2F"},{"id":"lv_6_188","topic":"Business and Humanities Studies","word":"saving","pos":"(n)","ipa":"/ˈseɪ.vɪŋ/","defVi":"khoản tiết kiệm, sự tiết kiệm","defEn":"money preserved for future use or an economy of an amount of something","examples":["Using public transport offers a significant [saving] on fuel costs. (=Dịch: Sử dụng phương tiện công cộng giúp tiết kiệm đáng kể chi phí nhiên liệu.)","She invested her entire life [saving] into starting a new business. (=Dịch: Cô đã đầu tư toàn bộ khoản tiền tiết kiệm cả đời của mình để khởi nghiệp kinh doanh.)","The new technology will lead to a considerable [saving] of energy. (=Dịch: Công nghệ mới này sẽ đem lại sự tiết kiệm năng lượng đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=saving&lang=en-GB&ipa=%2F%CB%88se%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=saving&lang=en-US&ipa=%2F%CB%88se%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_6_189","topic":"Business and Humanities Studies","word":"scenario","pos":"(n)","ipa":"/səˈnɛr.i.oʊ/","defVi":"kịch bản, tình huống có thể xảy ra","defEn":"a description of possible actions or events in the future","examples":["In the worst-case [scenario], the company could lose half of its revenue. (=Dịch: Trong kịch bản tồi tệ nhất, công ty có thể mất một nửa doanh thu.)","The training program prepares pilots for every possible emergency [scenario]. (=Dịch: Chương trình huấn luyện chuẩn bị cho các phi công ứng phó với mọi tình huống khẩn cấp có thể xảy ra.)","Economic experts have outlined several possible recovery [scenarios] for next year. (=Dịch: Các chuyên gia kinh tế đã vạch ra một vài kịch bản phục hồi khả thi cho năm tới.)"],"ukAudio":"/ai_services/tts3/?q=scenario&lang=en-GB&ipa=%2Fs%C9%99%CB%88n%C9%9Br.i.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=scenario&lang=en-US&ipa=%2Fs%C9%99%CB%88n%C9%9Br.i.o%CA%8A%2F"},{"id":"lv_6_190","topic":"Business and Humanities Studies","word":"schizophrenia","pos":"(n)","ipa":"/ˌskɪt.səˈfriː.ni.ə/","defVi":"bệnh tâm thần phân liệt","defEn":"a serious mental disorder that affects how a person thinks, feels, and behaves","examples":["Doctors diagnosed the patient with [schizophrenia] after observing symptoms of hallucinations. (=Dịch: Các bác sĩ chẩn đoán bệnh nhân mắc chứng tâm thần phân liệt sau khi quan sát các triệu chứng ảo giác.)","Medication and therapy can help manage the symptoms of [schizophrenia] effectively. (=Dịch: Thuốc và trị liệu có thể giúp kiểm soát các triệu chứng của bệnh tâm thần phân liệt một cách hiệu quả.)","Public education is necessary to reduce the social stigma surrounding [schizophrenia]. (=Dịch: Giáo dục cộng đồng là cần thiết để giảm bớt định kiến xã hội xung quanh bệnh tâm thần phân liệt.)"],"ukAudio":"/ai_services/tts3/?q=schizophrenia&lang=en-GB&ipa=%2F%CB%8Csk%C9%AAt.s%C9%99%CB%88fri%CB%90.ni.%C9%99%2F","usAudio":"/ai_services/tts3/?q=schizophrenia&lang=en-US&ipa=%2F%CB%8Csk%C9%AAt.s%C9%99%CB%88fri%CB%90.ni.%C9%99%2F"},{"id":"lv_6_191","topic":"Business and Humanities Studies","word":"secure","pos":"(adj)","ipa":"/səˈkjʊr/","defVi":"an toàn, chắc chắn, bảo đảm","defEn":"safe from danger, harm, or the risk of failure","examples":["Make sure you create a [secure] password for all your online accounts. (=Dịch: Hãy đảm bảo rằng bạn tạo một mật khẩu an toàn cho tất cả các tài khoản trực tuyến của mình.)","Children feel more [secure] when they have a consistent daily routine. (=Dịch: Trẻ em cảm thấy an tâm hơn khi có một thời gian biểu hàng ngày ổn định.)","The bank keeps confidential documents in a highly [secure] vault. (=Dịch: Ngân hàng lưu giữ các tài liệu mật trong một căn hầm có độ an toàn cao.)"],"ukAudio":"/ai_services/tts3/?q=secure&lang=en-GB&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=secure&lang=en-US&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F"},{"id":"lv_6_192","topic":"Business and Humanities Studies","word":"semantic","pos":"(adj)","ipa":"/sɪˈmæn.tɪk/","defVi":"thuộc về ngữ nghĩa","defEn":"connected with the meanings of words and language","examples":["The debate turned into a purely [semantic] argument about the definition of the term. (=Dịch: Cuộc tranh luận đã biến thành một cuộc tranh cãi thuần túy về ngữ nghĩa liên quan đến định nghĩa của thuật ngữ.)","Language models use [semantic] analysis to understand the context of a sentence. (=Dịch: Các mô hình ngôn ngữ sử dụng phân tích ngữ nghĩa để hiểu ngữ cảnh của một câu.)","Damage to certain areas of the brain can impair [semantic] memory. (=Dịch: Tổn thương ở một số vùng não nhất định có thể làm suy giảm trí nhớ ngữ nghĩa.)"],"ukAudio":"/ai_services/tts3/?q=semantic&lang=en-GB&ipa=%2Fs%C9%AA%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=semantic&lang=en-US&ipa=%2Fs%C9%AA%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_6_193","topic":"Business and Humanities Studies","word":"seriously","pos":"(adv)","ipa":"/ˈsɪr.i.əs.li/","defVi":"một cách nghiêm túc, trầm trọng","defEn":"in a solemn, grave, or sincere manner; to a severe extent","examples":["You need to take your exam preparation more [seriously]. (=Dịch: Bạn cần nghiêm túc hơn với việc chuẩn bị cho kỳ thi của mình.)","Two passengers were [seriously] injured in the car accident. (=Dịch: Hai hành khách đã bị thương nặng trong vụ tai nạn ô tô.)","I am [seriously] considering applying for a master's degree abroad. (=Dịch: Tôi đang nghiêm túc cân nhắc việc nộp hồ sơ học thạc sĩ ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=seriously&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=seriously&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F"},{"id":"lv_6_194","topic":"Business and Humanities Studies","word":"shy","pos":"(adj)","ipa":"/ʃaɪ/","defVi":"nhút nhát, e thẹn","defEn":"nervous and uncomfortable about meeting and talking to other people","examples":["He was too [shy] to ask the teacher for help after class. (=Dịch: Cậu ấy quá nhút nhát để xin giáo viên giúp đỡ sau giờ học.)","The little girl gave a [shy] smile when introduced to our guests. (=Dịch: Cô bé nở một nụ cười e thẹn khi được giới thiệu với các vị khách của chúng tôi.)","Public speaking can be terrifying for someone who is naturally [shy]. (=Dịch: Nói trước công chúng có thể rất đáng sợ đối với một người có bản tính nhút nhát.)"],"ukAudio":"/ai_services/tts3/?q=shy&lang=en-GB&ipa=%2F%CA%83a%C9%AA%2F","usAudio":"/ai_services/tts3/?q=shy&lang=en-US&ipa=%2F%CA%83a%C9%AA%2F"},{"id":"lv_6_195","topic":"Business and Humanities Studies","word":"sibling","pos":"(n)","ipa":"/ˈsɪb.lɪŋ/","defVi":"anh chị em ruột","defEn":"a brother or sister","examples":["She gets along very well with her younger [sibling]. (=Dịch: Cô ấy rất hòa thuận với em ruột của mình.)","[Sibling] rivalry is quite common in families with multiple children. (=Dịch: Sự ganh đua giữa anh chị em khá phổ biến trong các gia đình có nhiều con.)","He grew up as an only child without any [sibling] to play with. (=Dịch: Anh lớn lên là con một mà không có anh chị em nào để chơi cùng.)"],"ukAudio":"/ai_services/tts3/?q=sibling&lang=en-GB&ipa=%2F%CB%88s%C9%AAb.l%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sibling&lang=en-US&ipa=%2F%CB%88s%C9%AAb.l%C9%AA%C5%8B%2F"},{"id":"lv_6_196","topic":"Business and Humanities Studies","word":"skilled","pos":"(adj)","ipa":"/skɪld/","defVi":"lành nghề, có tay nghề cao","defEn":"having the knowledge, training, or ability to do something well","examples":["The hospital is in urgent need of [skilled] nurses and doctors. (=Dịch: Bệnh viện đang có nhu cầu cấp thiết về các bác sĩ và y tá có tay nghề cao.)","He is a [skilled] carpenter who can build beautiful custom furniture. (=Dịch: Anh ấy là một thợ mộc lành nghề có thể đóng những món đồ nội thất đặt riêng tuyệt đẹp.)","The country relies on [skilled] workers to drive its economic growth. (=Dịch: Đất nước này dựa vào lực lượng lao động có tay nghề để thúc đẩy tăng trưởng kinh tế.)"],"ukAudio":"/ai_services/tts3/?q=skilled&lang=en-GB&ipa=%2Fsk%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=skilled&lang=en-US&ipa=%2Fsk%C9%AAld%2F"},{"id":"lv_6_197","topic":"Business and Humanities Studies","word":"software","pos":"(n)","ipa":"/ˈsɔːft.wer/","defVi":"phần mềm máy tính","defEn":"the programs and operating information used by a computer","examples":["You need to update your antivirus [software] regularly to protect your computer. (=Dịch: Bạn cần cập nhật phần mềm diệt virus thường xuyên để bảo vệ máy tính của mình.)","The company develops educational [software] for young children. (=Dịch: Công ty này phát triển phần mềm giáo dục cho trẻ nhỏ.)","A glitch in the accounting [software] caused a delay in processing payments. (=Dịch: Một lỗi trong phần mềm kế toán đã làm chậm quá trình xử lý các khoản thanh toán.)"],"ukAudio":"/ai_services/tts3/?q=software&lang=en-GB&ipa=%2F%CB%88s%C9%94%CB%90ft.wer%2F","usAudio":"/ai_services/tts3/?q=software&lang=en-US&ipa=%2F%CB%88s%C9%94%CB%90ft.wer%2F"},{"id":"lv_6_198","topic":"Business and Humanities Studies","word":"solitude","pos":"(n)","ipa":"/ˈsɑː.lə.tuːd/","defVi":"sự thanh tịnh khi ở một mình, cảnh thanh vắng","defEn":"the state or situation of being alone, especially when pleasant and peaceful","examples":["He went for a long walk in the forest to enjoy the peace and [solitude]. (=Dịch: Anh ấy đi dạo thật lâu trong rừng để tận hưởng sự yên bình và thanh tịnh một mình.)","Writers often seek [solitude] so they can focus on their creative work. (=Dịch: Các nhà văn thường tìm kiếm sự tĩnh lặng một mình để có thể tập trung vào công việc sáng tạo.)","After weeks of non-stop socializing, she welcomed a weekend of complete [solitude]. (=Dịch: Sau nhiều tuần giao lưu không ngừng nghỉ, cô rất hoan nghênh một ngày cuối tuần hoàn toàn ở một mình.)"],"ukAudio":"/ai_services/tts3/?q=solitude&lang=en-GB&ipa=%2F%CB%88s%C9%91%CB%90.l%C9%99.tu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=solitude&lang=en-US&ipa=%2F%CB%88s%C9%91%CB%90.l%C9%99.tu%CB%90d%2F"},{"id":"lv_6_199","topic":"Business and Humanities Studies","word":"sourced","pos":"(v)","ipa":"/sɔːrst/","defVi":"thu mua từ, lấy nguồn từ","defEn":"obtained or supplied something from a particular place or manufacturer","examples":["The restaurant proudly serves ingredients [sourced] from local organic farms. (=Dịch: Nhà hàng tự hào phục vụ các nguyên liệu được thu mua từ các nông trại hữu cơ địa phương.)","All the timber for this furniture was [sourced] sustainably. (=Dịch: Toàn bộ gỗ cho đồ nội thất này đều được khai thác từ nguồn bền vững.)","The manufacturer [sourced] electronic parts from several international suppliers. (=Dịch: Nhà sản xuất đã nhập linh kiện điện tử từ nhiều nhà cung cấp quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=sourced&lang=en-GB&ipa=%2Fs%C9%94%CB%90rst%2F","usAudio":"/ai_services/tts3/?q=sourced&lang=en-US&ipa=%2Fs%C9%94%CB%90rst%2F"},{"id":"lv_6_200","topic":"Business and Humanities Studies","word":"span","pos":"(v)","ipa":"/spæn/","defVi":"kéo dài qua, trải rộng khắp","defEn":"to extend across a period of time or physical distance","examples":["His successful career in education [span]ned more than four decades. (=Dịch: Sự nghiệp thành công của ông trong ngành giáo dục đã kéo dài hơn bốn thập kỷ.)","The magnificent bridge [span]s the wide river connecting two provinces. (=Dịch: Cây cầu tráng lệ bắc ngang qua con sông rộng lớn nối liền hai tỉnh.)","Her research projects [span] multiple disciplines, including physics and biology. (=Dịch: Các dự án nghiên cứu của cô ấy trải rộng trên nhiều lĩnh vực, bao gồm cả vật lý và sinh học.)"],"ukAudio":"/ai_services/tts3/?q=span&lang=en-GB&ipa=%2Fsp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=span&lang=en-US&ipa=%2Fsp%C3%A6n%2F"},{"id":"lv_6_201","topic":"Business and Humanities Studies","word":"sportspeople","pos":"(n)","ipa":"/ˈspɔrtsˌpi.pəl/","defVi":"các vận động viên, người chơi thể thao","defEn":"people who play sport, especially professionally","examples":["Professional [sportspeople] must maintain a strict diet and training routine. (=Dịch: Các vận động viên chuyên nghiệp phải duy trì một chế độ ăn uống và tập luyện nghiêm ngặt.)","Many famous [sportspeople] earn significant money from commercial endorsements. (=Dịch: Nhiều vận động viên nổi tiếng kiếm được số tiền lớn từ các hợp đồng quảng cáo thương mại.)","The ceremony honored the country's most successful [sportspeople] of the year. (=Dịch: Buổi lễ đã vinh danh những người chơi thể thao thành công nhất trong năm của đất nước.)"],"ukAudio":"/ai_services/tts3/?q=sportspeople&lang=en-GB&ipa=%2F%CB%88sp%C9%94rts%CB%8Cpi.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sportspeople&lang=en-US&ipa=%2F%CB%88sp%C9%94rts%CB%8Cpi.p%C9%99l%2F"},{"id":"lv_6_202","topic":"Business and Humanities Studies","word":"statistical","pos":"(adj)","ipa":"/stəˈtɪs.tɪ.kəl/","defVi":"thuộc về thống kê","defEn":"relating to the collection, analysis, and interpretation of numerical data","examples":["The researcher provided strong [statistical] evidence to support his theory. (=Dịch: Nhà nghiên cứu đã cung cấp bằng chứng thống kê vững chắc để ủng hộ lý thuyết của mình.)","There is no [statistical] difference in performance between the two groups. (=Dịch: Không có sự khác biệt mang tính thống kê về hiệu suất giữa hai nhóm.)","She used [statistical] software to analyze the survey results. (=Dịch: Cô ấy đã sử dụng phần mềm thống kê để phân tích kết quả khảo sát.)"],"ukAudio":"/ai_services/tts3/?q=statistical&lang=en-GB&ipa=%2Fst%C9%99%CB%88t%C9%AAs.t%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=statistical&lang=en-US&ipa=%2Fst%C9%99%CB%88t%C9%AAs.t%C9%AA.k%C9%99l%2F"},{"id":"lv_6_203","topic":"Business and Humanities Studies","word":"status","pos":"(n)","ipa":"/ˈsteɪ.təs/","defVi":"địa vị, vị thế, tình trạng","defEn":"the legal, social, or professional position of someone or something","examples":["He worked hard to improve his social [status] in the community. (=Dịch: Anh ấy đã làm việc chăm chỉ để nâng cao vị thế xã hội của mình trong cộng đồng.)","You can check the [status] of your application online at any time. (=Dịch: Bạn có thể kiểm tra tình trạng hồ sơ ứng tuyển của mình trực tuyến bất cứ lúc nào.)","The building was granted historical [status] by the government. (=Dịch: Tòa nhà đã được chính phủ cấp tư cách di tích lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=status&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.t%C9%99s%2F","usAudio":"/ai_services/tts3/?q=status&lang=en-US&ipa=%2F%CB%88ste%C9%AA.t%C9%99s%2F"},{"id":"lv_6_204","topic":"Business and Humanities Studies","word":"stranger","pos":"(n)","ipa":"/ˈstreɪn.dʒɚ/","defVi":"người lạ","defEn":"a person whom you do not know","examples":["Children are often taught not to talk to a [stranger]. (=Dịch: Trẻ em thường được dạy không nên nói chuyện với người lạ.)","A kind [stranger] helped me find my way to the train station. (=Dịch: Một người lạ tốt bụng đã giúp tôi tìm đường đến ga xe lửa.)","I felt like a [stranger] in the new city until I made some friends. (=Dịch: Tôi cảm thấy như một người xa lạ ở thành phố mới cho đến khi kết bạn được với vài người.)"],"ukAudio":"/ai_services/tts3/?q=stranger&lang=en-GB&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=stranger&lang=en-US&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_6_205","topic":"Business and Humanities Studies","word":"strengthen","pos":"(v)","ipa":"/ˈstreŋk.θən/","defVi":"củng cố, tăng cường, làm mạnh thêm","defEn":"to make or become stronger, more effective, or more resilient","examples":["Regular physical exercise helps to [strengthen] your heart and muscles. (=Dịch: Tập thể dục đều đặn giúp tăng cường sức khỏe tim mạch và cơ bắp.)","The two nations signed an agreement to [strengthen] bilateral trade relations. (=Dịch: Hai quốc gia đã ký một thỏa thuận nhằm củng cố quan hệ thương mại song phương.)","New evidence was presented to [strengthen] the lawyer's argument in court. (=Dịch: Bằng chứng mới đã được đưa ra để củng cố lập luận của luật sư trước tòa.)"],"ukAudio":"/ai_services/tts3/?q=strengthen&lang=en-GB&ipa=%2F%CB%88stre%C5%8Bk.%CE%B8%C9%99n%2F","usAudio":"/ai_services/tts3/?q=strengthen&lang=en-US&ipa=%2F%CB%88stre%C5%8Bk.%CE%B8%C9%99n%2F"},{"id":"lv_6_206","topic":"Business and Humanities Studies","word":"strike","pos":"(n)","ipa":"/straɪk/","defVi":"cuộc đình công, bãi công","defEn":"a refusal to work organized by a body of employees as a form of protest","examples":["Train services were completely disrupted due to a rail workers' [strike]. (=Dịch: Các dịch vụ tàu hỏa đã bị gián đoạn hoàn toàn do cuộc đình công của công nhân đường sắt.)","The union decided to call a [strike] after negotiations broke down. (=Dịch: Công đoàn đã quyết định kêu gọi bãi công sau khi các cuộc đàm phán đổ vỡ.)","Teachers went on [strike] to demand better pay and working conditions. (=Dịch: Các giáo viên đã tiến hành đình công để yêu cầu mức lương và điều kiện làm việc tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=strike&lang=en-GB&ipa=%2Fstra%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=strike&lang=en-US&ipa=%2Fstra%C9%AAk%2F"},{"id":"lv_6_207","topic":"Business and Humanities Studies","word":"string","pos":"(n)","ipa":"/strɪŋ/","defVi":"dây, sợi dây; dây đàn","defEn":"a thin piece of cord or rope used for tying, fastening, or pulling things","examples":["He tied the cardboard box securely with a piece of [string]. (=Dịch: Anh ấy đã dùng một sợi dây để buộc chặt chiếc hộp các-tông lại.)","One [string] on his guitar snapped during the live concert. (=Dịch: Một dây trên cây đàn ghi-ta của anh ấy đã bị đứt trong buổi hòa nhạc trực tiếp.)","Children used colorful [string] to make friendship bracelets. (=Dịch: Lũ trẻ đã dùng những sợi dây nhiều màu sắc để làm vòng tay tình bạn.)"],"ukAudio":"/ai_services/tts3/?q=string&lang=en-GB&ipa=%2Fstr%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=string&lang=en-US&ipa=%2Fstr%C9%AA%C5%8B%2F"},{"id":"lv_6_208","topic":"Business and Humanities Studies","word":"subsequent","pos":"(adj)","ipa":"/ˈsʌb.sɪ.kwənt/","defVi":"xảy ra sau đó, tiếp theo","defEn":"happening or coming after something else","examples":["The initial report was brief, but [subsequent] studies provided more detail. (=Dịch: Báo cáo ban đầu khá ngắn gọn, nhưng các nghiên cứu tiếp theo đã cung cấp thêm chi tiết.)","Her first novel was a flop, but [subsequent] books were bestsellers. (=Dịch: Cuốn tiểu thuyết đầu tay của cô ấy thất bại, nhưng các cuốn sách sau đó lại bán rất chạy.)","The mistake was discovered in [subsequent] tests before the product launched. (=Dịch: Sai sót đã được phát hiện trong các bài kiểm tra tiếp theo trước khi sản phẩm ra mắt.)"],"ukAudio":"/ai_services/tts3/?q=subsequent&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.s%C9%AA.kw%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=subsequent&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.s%C9%AA.kw%C9%99nt%2F"},{"id":"lv_6_209","topic":"Business and Humanities Studies","word":"successfully","pos":"(adv)","ipa":"/səkˈsɛs.fə.li/","defVi":"một cách thành công, thuận lợi","defEn":"in a way that achieves the desired result","examples":["The team [successfully] launched the new application last week. (=Dịch: Đội ngũ đã ra mắt thành công ứng dụng mới vào tuần trước.)","She [successfully] completed her master's degree in economics. (=Dịch: Cô ấy đã hoàn thành xuất sắc bằng thạc sĩ kinh tế.)","The doctor [successfully] treated the rare medical condition. (=Dịch: Bác sĩ đã điều trị thành công căn bệnh hiếm gặp.)"],"ukAudio":"/ai_services/tts3/?q=successfully&lang=en-GB&ipa=%2Fs%C9%99k%CB%88s%C9%9Bs.f%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=successfully&lang=en-US&ipa=%2Fs%C9%99k%CB%88s%C9%9Bs.f%C9%99.li%2F"},{"id":"lv_6_210","topic":"Business and Humanities Studies","word":"sum","pos":"(n)","ipa":"/sʌm/","defVi":"số tiền; tổng số","defEn":"an amount of money; the total amount resulting from adding numbers together","examples":["She donated a large [sum] of money to the local animal shelter. (=Dịch: Cô ấy đã quyên góp một khoản tiền lớn cho trạm cứu hộ động vật địa phương.)","The [sum] of two and three is five. (=Dịch: Tổng của hai và ba là năm.)","The total [sum] required for the project exceeded their budget. (=Dịch: Tổng số tiền cần cho dự án đã vượt quá ngân sách của họ.)"],"ukAudio":"/ai_services/tts3/?q=sum&lang=en-GB&ipa=%2Fs%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=sum&lang=en-US&ipa=%2Fs%CA%8Cm%2F"},{"id":"lv_6_211","topic":"Business and Humanities Studies","word":"tackle","pos":"(v)","ipa":"/ˈtæk.əl/","defVi":"giải quyết, xử lý","defEn":"to make an organized effort to deal with a difficult problem or task","examples":["The local government is launching new initiatives to [tackle] air pollution. (=Dịch: Chính quyền địa phương đang triển khai các sáng kiến mới để giải quyết tình trạng ô nhiễm không khí.)","We must work together to [tackle] the root causes of poverty. (=Dịch: Chúng ta phải hợp tác cùng nhau để giải quyết những nguyên nhân gốc rễ của đói nghèo.)","The engineer spent the entire afternoon trying to [tackle] the software glitch. (=Dịch: Kỹ sư đã dành cả buổi chiều để cố gắng xử lý sự cố phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=tackle&lang=en-GB&ipa=%2F%CB%88t%C3%A6k.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tackle&lang=en-US&ipa=%2F%CB%88t%C3%A6k.%C9%99l%2F"},{"id":"lv_6_212","topic":"Business and Humanities Studies","word":"tanker","pos":"(n)","ipa":"/ˈtæŋ.kɚ/","defVi":"tàu chở dầu, xe bồn","defEn":"a large ship, truck, or plane designed to carry large quantities of liquid or gas","examples":["An oil [tanker] ran aground near the coast, causing a major spill. (=Dịch: Một chiếc tàu chở dầu bị mắc cạn gần bờ biển, gây ra một vụ tràn dầu lớn.)","A milk [tanker] arrives at the dairy farm every morning to collect milk. (=Dịch: Một chiếc xe bồn chở sữa đến trang trại bò sữa vào mỗi buổi sáng để thu gom sữa.)","Firefighters used a water [tanker] to help extinguish the forest blaze. (=Dịch: Lực lượng cứu hỏa đã sử dụng một xe bồn chở nước để giúp dập tắt đám cháy rừng.)"],"ukAudio":"/ai_services/tts3/?q=tanker&lang=en-GB&ipa=%2F%CB%88t%C3%A6%C5%8B.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tanker&lang=en-US&ipa=%2F%CB%88t%C3%A6%C5%8B.k%C9%9A%2F"},{"id":"lv_6_213","topic":"Business and Humanities Studies","word":"teamwork","pos":"(n)","ipa":"/ˈtiːm.wɜːrk/","defVi":"làm việc nhóm, sự phối hợp đồng đội","defEn":"the combined action of a group, especially when effective and efficient","examples":["Successful project delivery depends on close communication and [teamwork]. (=Dịch: Việc bàn giao dự án thành công phụ thuộc vào sự giao tiếp chặt chẽ và tinh thần làm việc nhóm.)","Playing sports at school teaches children the true value of [teamwork]. (=Dịch: Chơi thể thao ở trường dạy cho trẻ em giá trị thực sự của tinh thần đồng đội.)","The rescue mission required outstanding [teamwork] from all emergency services. (=Dịch: Nhiệm vụ cứu hộ đòi hỏi sự phối hợp đồng đội xuất sắc từ tất cả các lực lượng khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=teamwork&lang=en-GB&ipa=%2F%CB%88ti%CB%90m.w%C9%9C%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=teamwork&lang=en-US&ipa=%2F%CB%88ti%CB%90m.w%C9%9C%CB%90rk%2F"},{"id":"lv_6_214","topic":"Business and Humanities Studies","word":"tech","pos":"(n)","ipa":"/tɛk/","defVi":"công nghệ","defEn":"short for technology, referring to scientific knowledge and electronic devices used in practical ways","examples":["Many young graduates aspire to work in the fast-growing [tech] industry. (=Dịch: Nhiều sinh viên mới tốt nghiệp khao khát được làm việc trong ngành công nghệ đang phát triển nhanh chóng.)","Modern educational institutions are integrating advanced [tech] into classrooms. (=Dịch: Các cơ sở giáo dục hiện đại đang tích hợp công nghệ tiên tiến vào lớp học.)","The city has become a hub for promising [tech] startups. (=Dịch: Thành phố đã trở thành một trung tâm cho các công ty khởi nghiệp công nghệ đầy triển vọng.)"],"ukAudio":"/ai_services/tts3/?q=tech&lang=en-GB&ipa=%2Ft%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=tech&lang=en-US&ipa=%2Ft%C9%9Bk%2F"},{"id":"lv_6_215","topic":"Business and Humanities Studies","word":"technological","pos":"(adj)","ipa":"/ˌtɛk.nəˈlɑ.dʒɪ.kəl/","defVi":"thuộc về công nghệ, kỹ thuật","defEn":"relating to or using scientific knowledge and technology","examples":["Recent [technological] advancements have completely transformed the healthcare industry. (=Dịch: Những tiến bộ công nghệ gần đây đã thay đổi hoàn toàn ngành chăm sóc sức khỏe.)","The company invests heavily in [technological] research and development. (=Dịch: Công ty đầu tư mạnh vào nghiên cứu và phát triển công nghệ.)","Rapid [technological] change requires workers to learn new digital skills constantly. (=Dịch: Sự thay đổi công nghệ nhanh chóng đòi hỏi người lao động phải liên tục học các kỹ năng số mới.)"],"ukAudio":"/ai_services/tts3/?q=technological&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Bk.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=technological&lang=en-US&ipa=%2F%CB%8Ct%C9%9Bk.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_6_216","topic":"Business and Humanities Studies","word":"tendency","pos":"(n)","ipa":"/ˈten.dən.si/","defVi":"xu hướng, khuynh hướng","defEn":"an inclination toward a particular characteristic, behavior, or trend","examples":["He has a [tendency] to procrastinate when faced with difficult tasks. (=Dịch: Anh ấy có xu hướng trì hoãn khi phải đối mặt với những nhiệm vụ khó khăn.)","There is a growing [tendency] among young consumers to shop online. (=Dịch: Ngày càng có xu hướng rõ rệt trong giới người tiêu dùng trẻ là mua sắm trực tuyến.)","The economy shows a clear [tendency] toward steady growth this quarter. (=Dịch: Nền kinh tế thể hiện một khuynh hướng tăng trưởng ổn định rõ rệt trong quý này.)"],"ukAudio":"/ai_services/tts3/?q=tendency&lang=en-GB&ipa=%2F%CB%88ten.d%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=tendency&lang=en-US&ipa=%2F%CB%88ten.d%C9%99n.si%2F"},{"id":"lv_6_217","topic":"Business and Humanities Studies","word":"trait","pos":"(n)","ipa":"/treɪt/","defVi":"nét tính cách, đặc điểm","defEn":"a particular quality in your personality or physical appearance","examples":["Curiosity is a personality [trait] shared by many successful scientists. (=Dịch: Tính tò mò là một nét tính cách chung của nhiều nhà khoa học thành công.)","Eye color is a physical [trait] inherited from parents. (=Dịch: Màu mắt là một đặc điểm thể chất được di truyền từ cha mẹ.)","Creativity is an important [trait] for individuals working in the arts. (=Dịch: Sáng tạo là một đặc điểm quan trọng đối với những người làm việc trong ngành nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=trait&lang=en-GB&ipa=%2Ftre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=trait&lang=en-US&ipa=%2Ftre%C9%AAt%2F"},{"id":"lv_6_218","topic":"Business and Humanities Studies","word":"transactional","pos":"(adj)","ipa":"/trænˈzæk.ʃən.əl/","defVi":"mang tính giao dịch, vụ lợi","defEn":"relating to the conducting of business, an exchange, or a practical interaction","examples":["Their business relationship remained purely [transactional] without any personal connection. (=Dịch: Mối quan hệ kinh doanh của họ hoàn toàn chỉ mang tính giao dịch mà không có sự gắn kết cá nhân nào.)","Modern banking apps are designed to handle high volumes of [transactional] data securely. (=Dịch: Các ứng dụng ngân hàng hiện đại được thiết kế để xử lý khối lượng lớn dữ liệu giao dịch một cách an toàn.)","A purely [transactional] approach to management may harm long-term employee loyalty. (=Dịch: Cách tiếp cận quản lý chỉ thuần mang tính trao đổi vụ lợi có thể làm tổn hại đến lòng trung thành lâu dài của nhân viên.)"],"ukAudio":"/ai_services/tts3/?q=transactional&lang=en-GB&ipa=%2Ftr%C3%A6n%CB%88z%C3%A6k.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=transactional&lang=en-US&ipa=%2Ftr%C3%A6n%CB%88z%C3%A6k.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_219","topic":"Business and Humanities Studies","word":"transformational","pos":"(adj)","ipa":"/ˌtræns.fɚˈmeɪ.ʃən.əl/","defVi":"mang tính chuyển đổi sâu sắc, mang tính cải cách","defEn":"causing a major, fundamental change in someone or something","examples":["The introduction of smartphones has had a [transformational] effect on modern communication. (=Dịch: Sự ra đời của điện thoại thông minh đã mang lại tác động biến đổi sâu sắc đối với giao tiếp hiện đại.)","She showed strong [transformational] leadership during the company's restructuring. (=Dịch: Cô ấy đã thể hiện khả năng lãnh đạo mang tính cải cách mạnh mẽ trong suốt quá trình tái cơ cấu công ty.)","Access to higher education can be a truly [transformational] experience for young people. (=Dịch: Cơ hội tiếp cận giáo dục đại học có thể là một trải nghiệm biến đổi sâu sắc thực sự đối với người trẻ.)"],"ukAudio":"/ai_services/tts3/?q=transformational&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=transformational&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_220","topic":"Business and Humanities Studies","word":"truly","pos":"(adv)","ipa":"/ˈtru.li/","defVi":"thực sự, đích thực","defEn":"in a truthful, sincere, or genuine manner; completely","examples":["I am [truly] grateful for all the support you have given me. (=Dịch: Tôi thực sự biết ơn vì tất cả sự hỗ trợ mà bạn đã dành cho tôi.)","It was a [truly] remarkable achievement for such a young player. (=Dịch: Đó thực sự là một thành tích đáng nể đối với một cầu thủ trẻ như vậy.)","She wants to know what he [truly] thinks about the proposal. (=Dịch: Cô ấy muốn biết anh ấy thực sự nghĩ gì về đề xuất này.)"],"ukAudio":"/ai_services/tts3/?q=truly&lang=en-GB&ipa=%2F%CB%88tru.li%2F","usAudio":"/ai_services/tts3/?q=truly&lang=en-US&ipa=%2F%CB%88tru.li%2F"},{"id":"lv_6_221","topic":"Business and Humanities Studies","word":"tunnel","pos":"(n)","ipa":"/ˈtʌn.əl/","defVi":"đường hầm","defEn":"a long passage dug underground or through a mountain for vehicles or trains","examples":["The railway [tunnel] through the mountain shortened travel time by two hours. (=Dịch: Đường hầm đường sắt xuyên núi đã rút ngắn thời gian di chuyển đi hai giờ.)","Drivers must turn on their headlights before entering the underwater [tunnel]. (=Dịch: Các tài xế phải bật đèn pha trước khi đi vào đường hầm dưới nước.)","Engineers worked for years to dig the underground metro [tunnel]. (=Dịch: Các kỹ sư đã làm việc trong nhiều năm để đào đường hầm tàu điện ngầm dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=tunnel&lang=en-GB&ipa=%2F%CB%88t%CA%8Cn.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tunnel&lang=en-US&ipa=%2F%CB%88t%CA%8Cn.%C9%99l%2F"},{"id":"lv_6_222","topic":"Business and Humanities Studies","word":"turnover","pos":"(n)","ipa":"/ˈtɝːnˌoʊ.vɚ/","defVi":"doanh số, doanh thu","defEn":"the amount of money taken in by a business over a period, or the rate at which staff leave and are replaced","examples":["The firm reported an annual [turnover] of over ten million dollars. (=Dịch: Công ty đã báo cáo doanh thu hàng năm hơn mười triệu đô la.)","High staff [turnover] can severely disrupt a company's daily operations. (=Dịch: Tỷ lệ luân chuyển nhân viên cao có thể làm gián đoạn nghiêm trọng hoạt động hàng ngày của công ty.)","Improving customer loyalty helped boost the store's weekly [turnover]. (=Dịch: Việc nâng cao lòng trung thành của khách hàng đã giúp tăng doanh số hàng tuần của cửa hàng.)"],"ukAudio":"/ai_services/tts3/?q=turnover&lang=en-GB&ipa=%2F%CB%88t%C9%9D%CB%90n%CB%8Co%CA%8A.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=turnover&lang=en-US&ipa=%2F%CB%88t%C9%9D%CB%90n%CB%8Co%CA%8A.v%C9%9A%2F"},{"id":"lv_6_223","topic":"Business and Humanities Studies","word":"typically","pos":"(adv)","ipa":"/ˈtɪ.pɪ.kli/","defVi":"thông thường, điển hình","defEn":"usually, or in a way that is characteristic of someone or something","examples":["Classes [typically] begin at eight o'clock in the morning. (=Dịch: Các lớp học thông thường bắt đầu vào lúc tám giờ sáng.)","Symptoms of the flu [typically] include fever and fatigue. (=Dịch: Các triệu chứng của bệnh cúm điển hình bao gồm sốt và mệt mỏi.)","He [typically] spends his weekends working in the garden. (=Dịch: Anh ấy thường dành những ngày cuối tuần để làm vườn.)"],"ukAudio":"/ai_services/tts3/?q=typically&lang=en-GB&ipa=%2F%CB%88t%C9%AA.p%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=typically&lang=en-US&ipa=%2F%CB%88t%C9%AA.p%C9%AA.kli%2F"},{"id":"lv_6_224","topic":"Business and Humanities Studies","word":"unaware","pos":"(adj)","ipa":"/ˌʌn.əˈwɛr/","defVi":"không nhận thức được, không hay biết","defEn":"not knowing or noticing something","examples":["He was completely [unaware] of the danger around the corner. (=Dịch: Anh ấy hoàn toàn không hay biết gì về mối nguy hiểm ở ngay góc đường.)","Many residents were [unaware] that the water supply had been cut off. (=Dịch: Nhiều cư dân đã không biết rằng nguồn cấp nước đã bị cắt.)","She seemed [unaware] of how much her comments had hurt him. (=Dịch: Cô ấy dường như không nhận ra những lời nhận xét của mình đã làm tổn thương anh ấy nhiều đến mức nào.)"],"ukAudio":"/ai_services/tts3/?q=unaware&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=unaware&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88w%C9%9Br%2F"},{"id":"lv_6_225","topic":"Business and Humanities Studies","word":"uncertainty","pos":"(n)","ipa":"/ʌnˈsɝː.tən.ti/","defVi":"sự không chắc chắn, sự bấp bênh","defEn":"a state of being unsure or not able to be relied on","examples":["The sudden change in economic policy has created widespread market [uncertainty]. (=Dịch: Sự thay đổi đột ngột trong chính sách kinh tế đã tạo ra tình trạng bất định lan rộng trên thị trường.)","Living with constant financial [uncertainty] can lead to severe stress. (=Dịch: Sống trong tình trạng bất an về tài chính liên tục có thể dẫn đến căng thẳng nghiêm trọng.)","There is still considerable [uncertainty] surrounding the date of the election. (=Dịch: Vẫn còn sự không chắc chắn đáng kể xung quanh ngày diễn ra cuộc bầu cử.)"],"ukAudio":"/ai_services/tts3/?q=uncertainty&lang=en-GB&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F","usAudio":"/ai_services/tts3/?q=uncertainty&lang=en-US&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F"},{"id":"lv_6_226","topic":"Business and Humanities Studies","word":"underestimate","pos":"(v)","ipa":"/ˌʌn.dɚˈes.tə.meɪt/","defVi":"đánh giá thấp, coi nhẹ","defEn":"to estimate something to be smaller, less important, or easier than it actually is","examples":["You should never [underestimate] the importance of thorough preparation. (=Dịch: Bạn không bao giờ nên đánh giá thấp tầm quan trọng của việc chuẩn bị kỹ lưỡng.)","The company tended to [underestimate] the strength of its main competitor. (=Dịch: Công ty có xu hướng coi nhẹ sức mạnh của đối thủ cạnh tranh chính.)","Hikers often [underestimate] how quickly weather conditions can change in the mountains. (=Dịch: Những người đi bộ đường dài thường đánh giá thấp tốc độ thay đổi thời tiết trên núi.)"],"ukAudio":"/ai_services/tts3/?q=underestimate&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88es.t%C9%99.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=underestimate&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88es.t%C9%99.me%C9%AAt%2F"},{"id":"lv_6_227","topic":"Business and Humanities Studies","word":"universal","pos":"(adj)","ipa":"/ˌjuː.nəˈvɝː.səl/","defVi":"phổ quát, toàn cầu","defEn":"existing everywhere or involving, affecting, or done by all people","examples":["Music is often described as a [universal] language that connects all cultures. (=Dịch: Âm nhạc thường được mô tả như một ngôn ngữ phổ quát kết nối mọi nền văn hóa.)","The organization advocates for [universal] access to clean drinking water. (=Dịch: Tổ chức này vận động cho quyền tiếp cận phổ cập nguồn nước sạch.)","Smiling is a [universal] expression of friendliness across different societies. (=Dịch: Nụ cười là một biểu hiện thân thiện mang tính phổ quát ở các xã hội khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=universal&lang=en-GB&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=universal&lang=en-US&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F"},{"id":"lv_6_228","topic":"Business and Humanities Studies","word":"unnecessary","pos":"(adj)","ipa":"/ʌnˈnɛs.əˌsɛr.i/","defVi":"không cần thiết, thừa thãi","defEn":"not needed or more than is needed","examples":["Buying a second car is completely [unnecessary] for our family. (=Dịch: Mua chiếc xe hơi thứ hai là hoàn toàn không cần thiết đối với gia đình chúng tôi.)","The doctor advised him to avoid [unnecessary] stress to recover faster. (=Dịch: Bác sĩ khuyên anh ấy nên tránh những căng thẳng không cần thiết để hồi phục nhanh hơn.)","Using excessive plastic packaging causes [unnecessary] harm to the environment. (=Dịch: Việc sử dụng quá nhiều bao bì nhựa gây ra tác hại không cần thiết cho môi trường.)"],"ukAudio":"/ai_services/tts3/?q=unnecessary&lang=en-GB&ipa=%2F%CA%8Cn%CB%88n%C9%9Bs.%C9%99%CB%8Cs%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=unnecessary&lang=en-US&ipa=%2F%CA%8Cn%CB%88n%C9%9Bs.%C9%99%CB%8Cs%C9%9Br.i%2F"},{"id":"lv_6_229","topic":"Business and Humanities Studies","word":"unwanted","pos":"(adj)","ipa":"/ʌnˈwɑːn.tɪd/","defVi":"không mong muốn, không cần thiết","defEn":"not desired, needed, or welcome","examples":["She donated her [unwanted] clothes to a local charity. (=Dịch: Cô ấy đã quyên góp quần áo không dùng đến cho một tổ chức từ thiện địa phương.)","Installing ad-blocking software can help prevent [unwanted] pop-ups. (=Dịch: Cài đặt phần mềm chặn quảng cáo có thể giúp ngăn chặn các cửa sổ bật lên không mong muốn.)","The new policy received an [unwanted] amount of negative publicity. (=Dịch: Chính sách mới đã thu hút một lượng lớn sự chú ý tiêu cực không mong muốn từ dư luận.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_6_230","topic":"Business and Humanities Studies","word":"unwilling","pos":"(adj)","ipa":"/ʌnˈwɪl.ɪŋ/","defVi":"không sẵn lòng, miễn cưỡng","defEn":"not ready, eager, or prepared to do something","examples":["He was [unwilling] to admit that he had made a serious mistake. (=Dịch: Anh ấy đã không sẵn lòng thừa nhận rằng mình đã phạm một sai lầm nghiêm trọng.)","Many workers are [unwilling] to relocate to another city for work. (=Dịch: Nhiều người lao động không muốn chuyển đến một thành phố khác để làm việc.)","She seemed [unwilling] to participate in the group discussion. (=Dịch: Cô ấy dường như miễn cưỡng tham gia vào cuộc thảo luận nhóm.)"],"ukAudio":"/ai_services/tts3/?q=unwilling&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=unwilling&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F"},{"id":"lv_6_231","topic":"Business and Humanities Studies","word":"upset","pos":"(adj)","ipa":"/ʌpˈsɛt/","defVi":"buồn bã, thất vọng hoặc lo lắng","defEn":"unhappy, disappointed, or worried because something unpleasant has happened","examples":["She was deeply [upset] when she heard the bad news about her exam. (=Dịch: Cô ấy vô cùng buồn bã khi nghe tin xấu về kỳ thi của mình.)","There is no need to get [upset] over such a minor mistake. (=Dịch: Không cần phải bực mình vì một lỗi nhỏ như vậy đâu.)","The customer was [upset] about the poor service at the restaurant. (=Dịch: Vị khách hàng rất bức xúc về chất lượng phục vụ kém tại nhà hàng.)"],"ukAudio":"/ai_services/tts3/?q=upset&lang=en-GB&ipa=%2F%CA%8Cp%CB%88s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=upset&lang=en-US&ipa=%2F%CA%8Cp%CB%88s%C9%9Bt%2F"},{"id":"lv_6_232","topic":"Business and Humanities Studies","word":"variable","pos":"(n)","ipa":"/ˈver.i.ə.bəl/","defVi":"biến số, yếu tố có thể thay đổi","defEn":"a factor, trait, or condition that can exist in differing amounts or types in an experiment","examples":["Temperature is an important [variable] to control during the science experiment. (=Dịch: Nhiệt độ là một biến số quan trọng cần kiểm soát trong suốt thí nghiệm khoa học.)","Researchers must account for more than one [variable] when analyzing the survey data. (=Dịch: Các nhà nghiên cứu phải tính đến nhiều hơn một biến số khi phân tích dữ liệu khảo sát.)","The independent [variable] in this study is the amount of sunlight the plants receive. (=Dịch: Biến số độc lập trong nghiên cứu này là lượng ánh sáng mặt trời mà cây trồng nhận được.)"],"ukAudio":"/ai_services/tts3/?q=variable&lang=en-GB&ipa=%2F%CB%88ver.i.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=variable&lang=en-US&ipa=%2F%CB%88ver.i.%C9%99.b%C9%99l%2F"},{"id":"lv_6_233","topic":"Business and Humanities Studies","word":"version","pos":"(n)","ipa":"/ˈvɜːr.ʒən/","defVi":"phiên bản","defEn":"a particular form of something that differs in some way from an earlier form or other forms","examples":["You should install the latest [version] of the software to fix the security bug. (=Dịch: Bạn nên cài đặt phiên bản phần mềm mới nhất để vá lỗi bảo mật.)","Her [version] of the story differed greatly from what the witness described. (=Dịch: Lời kể của cô ấy về câu chuyện khác rất nhiều so với những gì nhân chứng miêu tả.)","The film director decided to release an extended [version] for the fans. (=Dịch: Đạo diễn bộ phim đã quyết định phát hành một phiên bản mở rộng dành cho người hâm mộ.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_6_234","topic":"Business and Humanities Studies","word":"victim","pos":"(n)","ipa":"/ˈvɪk.tɪm/","defVi":"nạn nhân","defEn":"a person harmed, injured, or killed as a result of a crime, accident, or event","examples":["The rescue team worked tirelessly to save the [victim] trapped under the rubble. (=Dịch: Đội cứu hộ đã làm việc không mệt mỏi để cứu nạn nhân bị mắc kẹt dưới đống đổ nát.)","She was a [victim] of online fraud and lost a significant amount of money. (=Dịch: Cô ấy là nạn nhân của một vụ lừa đảo trực tuyến và đã mất một số tiền lớn.)","The charity provides counseling and legal aid to any [victim] of domestic violence. (=Dịch: Tổ chức từ thiện cung cấp tư vấn tâm lý và hỗ trợ pháp lý cho bất kỳ nạn nhân nào của bạo lực gia đình.)"],"ukAudio":"/ai_services/tts3/?q=victim&lang=en-GB&ipa=%2F%CB%88v%C9%AAk.t%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=victim&lang=en-US&ipa=%2F%CB%88v%C9%AAk.t%C9%AAm%2F"},{"id":"lv_6_235","topic":"Business and Humanities Studies","word":"violinist","pos":"(n)","ipa":"/ˌvaɪ.əˈlɪn.ɪst/","defVi":"nghệ sĩ vĩ cầm, người chơi đàn violin","defEn":"a person who plays the violin","examples":["The talented [violinist] performed a breathtaking solo during the concert. (=Dịch: Nghệ sĩ vĩ cầm tài năng đã trình diễn một bản độc tấu ngoạn mục trong buổi hòa nhạc.)","She practiced for hours every day to become a professional [violinist]. (=Dịch: Cô ấy luyện tập hàng giờ mỗi ngày để trở thành một nghệ sĩ vĩ cầm chuyên nghiệp.)","The orchestra is holding auditions to hire a new lead [violinist]. (=Dịch: Dàn nhạc đang tổ chức các buổi thử giọng để tuyển một nghệ sĩ vĩ cầm trưởng mới.)"],"ukAudio":"/ai_services/tts3/?q=violinist&lang=en-GB&ipa=%2F%CB%8Cva%C9%AA.%C9%99%CB%88l%C9%AAn.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=violinist&lang=en-US&ipa=%2F%CB%8Cva%C9%AA.%C9%99%CB%88l%C9%AAn.%C9%AAst%2F"},{"id":"lv_6_236","topic":"Business and Humanities Studies","word":"vision","pos":"(n)","ipa":"/ˈvɪʒ.ən/","defVi":"tầm nhìn, thị giác","defEn":"the ability to imagine how something could develop in the future, or the ability to see","examples":["The leader shared his ambitious [vision] for the city's future. (=Dịch: Vị lãnh đạo đã chia sẻ tầm nhìn đầy tham vọng của mình về tương lai của thành phố.)","Poor lighting can affect your [vision] when reading at night. (=Dịch: Ánh sáng yếu có thể ảnh hưởng đến thị lực của bạn khi đọc sách vào ban đêm.)","She had a clear [vision] of how her business should expand. (=Dịch: Cô ấy có một định hướng rõ ràng về cách mở rộng doanh nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=vision&lang=en-GB&ipa=%2F%CB%88v%C9%AA%CA%92.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vision&lang=en-US&ipa=%2F%CB%88v%C9%AA%CA%92.%C9%99n%2F"},{"id":"lv_6_237","topic":"Business and Humanities Studies","word":"wheelchair","pos":"(n)","ipa":"/ˈwiːl.tʃer/","defVi":"xe lăn","defEn":"a chair with wheels used by people who cannot walk due to illness or disability","examples":["The new library has ramps installed for visitors who use a [wheelchair]. (=Dịch: Thư viện mới đã lắp đặt các đường dốc dành cho khách đến thăm sử dụng xe lăn.)","He remained active in sports despite being confined to a [wheelchair]. (=Dịch: Anh ấy vẫn tích cực chơi thể thao dù phải ngồi xe lăn.)","Modern buildings should always provide adequate [wheelchair] access. (=Dịch: Các tòa nhà hiện đại phải luôn cung cấp lối đi phù hợp cho xe lăn.)"],"ukAudio":"/ai_services/tts3/?q=wheelchair&lang=en-GB&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F","usAudio":"/ai_services/tts3/?q=wheelchair&lang=en-US&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F"},{"id":"lv_6_238","topic":"Business and Humanities Studies","word":"workforce","pos":"(n)","ipa":"/ˈwɜːrk.fɔːrs/","defVi":"lực lượng lao động, đội ngũ nhân sự","defEn":"the total number of people who are available to work or employed in a country or company","examples":["Women now make up nearly half of the country's total [workforce]. (=Dịch: Phụ nữ hiện chiếm gần một nửa tổng lực lượng lao động của cả nước.)","The company decided to reduce its [workforce] to cut operational costs. (=Dịch: Công ty đã quyết định cắt giảm nhân sự để giảm thiểu chi phí vận hành.)","Rapid technological advances require a highly skilled and adaptable [workforce]. (=Dịch: Những tiến bộ công nghệ nhanh chóng đòi hỏi một lực lượng lao động có tay nghề cao và thích ứng tốt.)"],"ukAudio":"/ai_services/tts3/?q=workforce&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90rk.f%C9%94%CB%90rs%2F","usAudio":"/ai_services/tts3/?q=workforce&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90rk.f%C9%94%CB%90rs%2F"},{"id":"lv_6_239","topic":"Business and Humanities Studies","word":"workplace","pos":"(n)","ipa":"/ˈwɝːk.pleɪs/","defVi":"nơi làm việc, môi trường công sở","defEn":"a building, office, or area where people do their jobs","examples":["Safety regulations must be strictly enforced in every industrial [workplace]. (=Dịch: Các quy định an toàn phải được thực thi nghiêm ngặt tại mọi nơi làm việc công nghiệp.)","A supportive [workplace] culture can significantly boost employee morale. (=Dịch: Một văn hóa môi trường công sở mang tính hỗ trợ có thể nâng cao đáng kể tinh thần của nhân viên.)","Flexibility has become a major factor in modern [workplace] design. (=Dịch: Tính linh hoạt đã trở thành một yếu tố quan trọng trong thiết kế nơi làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=workplace&lang=en-GB&ipa=%2F%CB%88w%C9%9D%CB%90k.ple%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=workplace&lang=en-US&ipa=%2F%CB%88w%C9%9D%CB%90k.ple%C9%AAs%2F"},{"id":"lv_6_240","topic":"Business and Humanities Studies","word":"worthwhile","pos":"(adj)","ipa":"/ˌwɝːθˈwaɪl/","defVi":"đáng giá, bõ công","defEn":"useful, important, or good enough to spend time, money, or effort on","examples":["Volunteering in the local community is a very [worthwhile] activity. (=Dịch: Làm tình nguyện trong cộng đồng địa phương là một hoạt động rất đáng giá.)","It was a long journey, but the experience made it [worthwhile]. (=Dịch: Đó là một chuyến đi dài, nhưng trải nghiệm đã khiến nó hoàn toàn bõ công.)","She felt that learning a second language was a truly [worthwhile] investment. (=Dịch: Cô ấy cảm thấy việc học ngôn ngữ thứ hai là một sự đầu tư thực sự xứng đáng.)"],"ukAudio":"/ai_services/tts3/?q=worthwhile&lang=en-GB&ipa=%2F%CB%8Cw%C9%9D%CB%90%CE%B8%CB%88wa%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=worthwhile&lang=en-US&ipa=%2F%CB%8Cw%C9%9D%CB%90%CE%B8%CB%88wa%C9%AAl%2F"},{"id":"lv_7_0","topic":"Education and Learning","word":"accompany","pos":"(v)","ipa":"/əˈkʌm.pə.ni/","defVi":"đi cùng, đồng hành, đi kèm với","defEn":"to go somewhere with someone as a companion, or to happen together with something","examples":["Children under twelve must be [accompany]ed by an adult at the pool. (=Dịch: Trẻ em dưới mười hai tuổi phải có người lớn đi cùng tại hồ bơi.)","Fever is often [accompany]ed by a sore throat and headache. (=Dịch: Sốt thường đi kèm với đau họng và nhức đầu.)","He offered to [accompany] her to the train station late at night. (=Dịch: Anh ấy đã đề nghị đi cùng cô ấy ra ga tàu vào đêm muộn.)"],"ukAudio":"/ai_services/tts3/?q=accompany&lang=en-GB&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=accompany&lang=en-US&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F"},{"id":"lv_7_1","topic":"Education and Learning","word":"admission","pos":"(n)","ipa":"/ədˈmɪʃ.ən/","defVi":"sự nhận vào, sự tuyển sinh, quyền vào cửa","defEn":"the permission or right to enter a place or become a member of an institution","examples":["She received an offer of [admission] from her dream university. (=Dịch: Cô ấy đã nhận được giấy báo trúng tuyển từ trường đại học mơ ước của mình.)","The museum offers free [admission] on the first Sunday of every month. (=Dịch: Bảo tàng miễn phí vé vào cửa vào ngày chủ nhật đầu tiên của mỗi tháng.)","The hospital arranged the immediate [admission] of the injured patient. (=Dịch: Bệnh viện đã sắp xếp việc tiếp nhận nhập viện ngay lập tức cho bệnh nhân bị thương.)"],"ukAudio":"/ai_services/tts3/?q=admission&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=admission&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_7_2","topic":"Education and Learning","word":"admit","pos":"(v)","ipa":"/ədˈmɪt/","defVi":"thừa nhận, nhận vào","defEn":"to agree that something is true, or to allow someone to enter","examples":["He had to [admit] that he made a serious mistake. (=Dịch: Anh ấy đã phải thừa nhận rằng mình đã phạm một sai lầm nghiêm trọng.)","She was thrilled to be [admit]ted to the top university in the country. (=Dịch: Cô ấy rất vui mừng khi được nhận vào trường đại học hàng đầu trong nước.)","Only ticket holders will be [admit]ted into the stadium. (=Dịch: Chỉ những người có vé mới được vào sân vận động.)"],"ukAudio":"/ai_services/tts3/?q=admit&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=admit&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAt%2F"},{"id":"lv_7_3","topic":"Education and Learning","word":"allocate","pos":"(v)","ipa":"/ˈæl.ə.keɪt/","defVi":"phân bổ, cấp phát","defEn":"to distribute resources or duties for a particular purpose","examples":["The government plans to [allocate] more funds to public healthcare. (=Dịch: Chính phủ dự định phân bổ thêm ngân sách cho y tế công cộng.)","Each team member was asked to [allocate] two hours a day to the new project. (=Dịch: Mỗi thành viên trong nhóm được yêu cầu dành ra hai giờ mỗi ngày cho dự án mới.)","The city council will [allocate] land for building affordable housing. (=Dịch: Hội đồng thành phố sẽ cấp đất để xây dựng nhà ở giá rẻ.)"],"ukAudio":"/ai_services/tts3/?q=allocate&lang=en-GB&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=allocate&lang=en-US&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F"},{"id":"lv_7_4","topic":"Education and Learning","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"có hoài bão, đầy tham vọng","defEn":"having a strong desire to achieve success, power, or wealth","examples":["She is an [ambitious] student who aims to get a scholarship abroad. (=Dịch: Cô ấy là một học sinh đầy hoài bão với mục tiêu giành học bổng du học.)","The company announced an [ambitious] plan to open ten new stores this year. (=Dịch: Công ty đã công bố một kế hoạch đầy tham vọng nhằm mở mười cửa hàng mới trong năm nay.)","He set an [ambitious] target for his daily running routine. (=Dịch: Anh ấy đã đặt ra một mục tiêu đầy tham vọng cho thói quen chạy bộ hàng ngày của mình.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_7_5","topic":"Education and Learning","word":"anymore","pos":"(adv)","ipa":"/ˌɛn.iˈmɔr/","defVi":"nữa (dùng trong câu phủ định hoặc nghi vấn để chỉ việc không còn tiếp diễn)","defEn":"no longer or not now as in the past","examples":["She does not live in this neighborhood [anymore]. (=Dịch: Cô ấy không còn sống ở khu phố này nữa.)","I cannot tolerate this noisy environment [anymore]. (=Dịch: Tôi không thể chịu đựng môi trường ồn ào này thêm nữa.)","Do you go jogging in the park [anymore]? (=Dịch: Bạn còn chạy bộ trong công viên nữa không?)"],"ukAudio":"/ai_services/tts3/?q=anymore&lang=en-GB&ipa=%2F%CB%8C%C9%9Bn.i%CB%88m%C9%94r%2F","usAudio":"/ai_services/tts3/?q=anymore&lang=en-US&ipa=%2F%CB%8C%C9%9Bn.i%CB%88m%C9%94r%2F"},{"id":"lv_7_6","topic":"Education and Learning","word":"assess","pos":"(v)","ipa":"/əˈses/","defVi":"đánh giá, định giá","defEn":"to judge or evaluate the amount, value, quality, or importance of something","examples":["The committee will [assess] the environmental impact of the new highway. (=Dịch: Ủy ban sẽ đánh giá tác động môi trường của tuyến đường cao tốc mới.)","Exams are commonly used to [assess] students' understanding of the subject. (=Dịch: Các kỳ thi thường được sử dụng để đánh giá mức độ hiểu biết của học sinh về môn học.)","Experts were sent to [assess] the total damage caused by the earthquake. (=Dịch: Các chuyên gia đã được cử đến để đánh giá toàn bộ thiệt hại do trận động đất gây ra.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88ses%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88ses%2F"},{"id":"lv_7_7","topic":"Education and Learning","word":"audio","pos":"(adj)","ipa":"/ˈɑː.di.oʊ/","defVi":"thuộc về âm thanh","defEn":"connected with sound or the recording and broadcasting of sound","examples":["The teacher used [audio] recordings to help students practice their listening skills. (=Dịch: Giáo viên đã sử dụng các bản ghi âm để giúp học sinh luyện kỹ năng nghe.)","High-quality [audio] equipment is essential for producing professional podcasts. (=Dịch: Thiết bị âm thanh chất lượng cao là điều cần thiết để sản xuất các podcast chuyên nghiệp.)","She plugged her headphones into the [audio] jack of her laptop. (=Dịch: Cô ấy cắm tai nghe vào giắc cắm âm thanh trên máy tính xách tay của mình.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F"},{"id":"lv_7_8","topic":"Education and Learning","word":"balloon","pos":"(n)","ipa":"/bəˈlun/","defVi":"bong bóng, quả bóng bay","defEn":"a small rubber bag that is filled with air or gas and used as a toy or decoration","examples":["The children played happily with a red [balloon] in the park. (=Dịch: Lũ trẻ chơi đùa vui vẻ với một quả bóng bay màu đỏ trong công viên.)","We bought colorful [balloon] decorations for the birthday party. (=Dịch: Chúng tôi đã mua đồ trang trí bong bóng nhiều màu sắc cho bữa tiệc sinh nhật.)","He watched the [balloon] float higher and higher into the sky. (=Dịch: Cậu bé nhìn quả bóng bay bay ngày càng cao lên bầu trời.)"],"ukAudio":"/ai_services/tts3/?q=balloon&lang=en-GB&ipa=%2Fb%C9%99%CB%88lun%2F","usAudio":"/ai_services/tts3/?q=balloon&lang=en-US&ipa=%2Fb%C9%99%CB%88lun%2F"},{"id":"lv_7_9","topic":"Education and Learning","word":"bat","pos":"(n)","ipa":"/bæt/","defVi":"con dơi; gậy đánh bóng","defEn":"a flying nocturnal mammal, or a wooden stick used in sports","examples":["A small [bat] flew out of the dark cave at sunset. (=Dịch: Một con dơi nhỏ bay ra khỏi hang tối vào lúc hoàng hôn.)","He swung the baseball [bat] with all his strength and hit a home run. (=Dịch: Anh ấy vung cây gậy bóng chày bằng tất cả sức mạnh và đánh một cú home run.)","Fruit [bat] species play a vital role in pollinating many plants. (=Dịch: Các loài dơi ăn quả đóng một vai trò quan trọng trong việc thụ phấn cho nhiều loài thực vật.)"],"ukAudio":"/ai_services/tts3/?q=bat&lang=en-GB&ipa=%2Fb%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=bat&lang=en-US&ipa=%2Fb%C3%A6t%2F"},{"id":"lv_7_10","topic":"Education and Learning","word":"behalf","pos":"(n)","ipa":"/bɪˈhæf/","defVi":"sự đại diện, thay mặt","defEn":"as a representative of someone, or for the benefit of someone","examples":["The lawyer spoke on [behalf] of her client in court. (=Dịch: Luật sư đã thay mặt cho thân chủ của mình phát biểu tại tòa.)","She accepted the award on [behalf] of the entire research team. (=Dịch: Cô ấy đã nhận giải thưởng thay mặt cho toàn bộ nhóm nghiên cứu.)","He campaigned tirelessly on [behalf] of homeless people in the city. (=Dịch: Anh ấy đã vận động không mệt mỏi vì quyền lợi của những người vô gia cư trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=behalf&lang=en-GB&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=behalf&lang=en-US&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F"},{"id":"lv_7_11","topic":"Education and Learning","word":"bother","pos":"(v)","ipa":"/ˈbɑː.ðɚ/","defVi":"Làm phiền, bận tâm, bận lòng.","defEn":"To make an effort to do something, or to cause someone mild annoyance or trouble.","examples":["I am sorry to [bother] you, but could you help me with this form? (=Dịch: Tôi xin lỗi vì đã làm phiền bạn, nhưng bạn có thể giúp tôi điền vào biểu mẫu này được không?)","He did not even [bother] to read the instructions before starting the test. (=Dịch: Cậu ấy thậm chí còn chẳng buồn đọc hướng dẫn trước khi bắt đầu bài kiểm tra.)","The loud construction noise outside began to [bother] the students during class. (=Dịch: Tiếng ồn xây dựng lớn bên ngoài bắt đầu làm phiền các học sinh trong suốt giờ học.)"],"ukAudio":"/ai_services/tts3/?q=bother&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F","usAudio":"/ai_services/tts3/?q=bother&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F"},{"id":"lv_7_12","topic":"Education and Learning","word":"breath","pos":"(n)","ipa":"/brɛθ/","defVi":"hơi thở","defEn":"the air that you take into and send out of your lungs","examples":["Take a deep [breath] before you start giving the presentation. (=Dịch: Hãy hít một hơi thật sâu trước khi bạn bắt đầu thuyết trình.)","He was completely out of [breath] after running up the stairs. (=Dịch: Anh ấy hoàn toàn hụt hơi sau khi chạy lên cầu thang.)","You can see your [breath] in the freezing winter air. (=Dịch: Bạn có thể nhìn thấy hơi thở của mình trong không khí giá lạnh mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=breath&lang=en-GB&ipa=%2Fbr%C9%9B%CE%B8%2F","usAudio":"/ai_services/tts3/?q=breath&lang=en-US&ipa=%2Fbr%C9%9B%CE%B8%2F"},{"id":"lv_7_13","topic":"Education and Learning","word":"breathe","pos":"(v)","ipa":"/ˈbrið/","defVi":"thở, hít thở","defEn":"to take air into your lungs and let it out again","examples":["Doctors advise people to [breathe] deeply whenever they feel stressed. (=Dịch: Bác sĩ khuyên mọi người nên hít thở sâu bất cứ khi nào cảm thấy căng thẳng.)","It was difficult to [breathe] at the top of the mountain due to the thin air. (=Dịch: Rất khó để thở trên đỉnh núi do không khí loãng.)","Patients with asthma often struggle to [breathe] during sudden weather changes. (=Dịch: Bệnh nhân hen suyễn thường gặp khó khăn khi thở trong những đợt thay đổi thời tiết đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2F%CB%88bri%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2F%CB%88bri%C3%B0%2F"},{"id":"lv_7_14","topic":"Education and Learning","word":"bullet","pos":"(n)","ipa":"/ˈbʊl.ɪt/","defVi":"viên đạn, dấu đầu dòng","defEn":"a small metal projectile fired from a gun; a small symbol used in text formatting","examples":["The soldier managed to dodge a stray [bullet] during the skirmish. (=Dịch: Người lính đã né được một viên đạn lạc trong trận giao tranh.)","Use a [bullet] point for each main idea in your presentation slide. (=Dịch: Hãy dùng một dấu đầu dòng cho mỗi ý chính trong trang trình bày của bạn.)","Police found a [bullet] casing at the crime scene. (=Dịch: Cảnh sát đã tìm thấy một vỏ đạn tại hiện trường vụ án.)"],"ukAudio":"/ai_services/tts3/?q=bullet&lang=en-GB&ipa=%2F%CB%88b%CA%8Al.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bullet&lang=en-US&ipa=%2F%CB%88b%CA%8Al.%C9%AAt%2F"},{"id":"lv_7_15","topic":"Education and Learning","word":"calm","pos":"(adj)","ipa":"/kɑːm/","defVi":"bình tĩnh, điềm tĩnh, êm ả","defEn":"peaceful, quiet, and not showing anger, worry, or excitement","examples":["It is important to stay [calm] during an unexpected emergency. (=Dịch: Việc giữ bình tĩnh trong trường hợp khẩn cấp bất ngờ là rất quan trọng.)","The sea was unusually [calm] in the early morning. (=Dịch: Biển sáng sớm hôm nay phẳng lặng lạ thường.)","Her [calm] voice helped reassure the frightened child. (=Dịch: Giọng nói điềm tĩnh của cô ấy đã giúp trấn an đứa trẻ đang sợ hãi.)"],"ukAudio":"/ai_services/tts3/?q=calm&lang=en-GB&ipa=%2Fk%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=calm&lang=en-US&ipa=%2Fk%C9%91%CB%90m%2F"},{"id":"lv_7_16","topic":"Education and Learning","word":"campus","pos":"(n)","ipa":"/ˈkæm.pəs/","defVi":"Khuôn viên trường học","defEn":"The grounds and buildings of a university, college, or school","examples":["The main university [campus] is located near the city center. (=Dịch: Khuôn viên chính của trường đại học nằm gần trung tâm thành phố.)","First-year students are encouraged to live on [campus] to make new friends. (=Dịch: Sinh viên năm nhất được khuyến khích sống trong khuôn viên trường để kết bạn mới.)","Several modern sports facilities were recently built on the new [campus]. (=Dịch: Một số cơ sở thể thao hiện đại gần đây đã được xây dựng trong khuôn viên trường mới.)"],"ukAudio":"/ai_services/tts3/?q=campus&lang=en-GB&ipa=%2F%CB%88k%C3%A6m.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=campus&lang=en-US&ipa=%2F%CB%88k%C3%A6m.p%C9%99s%2F"},{"id":"lv_7_17","topic":"Education and Learning","word":"cardboard","pos":"(n)","ipa":"/ˈkɑrd.bɔrd/","defVi":"bìa cứng, các-tông","defEn":"stiff, thick paper used for making boxes and packaging","examples":["We packed all our old books into a large [cardboard] box. (=Dịch: Chúng tôi đã đóng gói tất cả sách cũ của mình vào một chiếc hộp các-tông lớn.)","Children often enjoy making creative toys out of recycled [cardboard]. (=Dịch: Trẻ em thường thích làm đồ chơi sáng tạo từ bìa các-tông tái chế.)","The fragile items were protected by several layers of [cardboard]. (=Dịch: Những món đồ dễ vỡ được bảo vệ bởi nhiều lớp bìa cứng.)"],"ukAudio":"/ai_services/tts3/?q=cardboard&lang=en-GB&ipa=%2F%CB%88k%C9%91rd.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=cardboard&lang=en-US&ipa=%2F%CB%88k%C9%91rd.b%C9%94rd%2F"},{"id":"lv_7_18","topic":"Education and Learning","word":"chapter","pos":"(n)","ipa":"/ˈtʃæp.tɚ/","defVi":"chương (sách)","defEn":"one of the main sections into which a book is divided","examples":["I am reading the final [chapter] of this novel. (=Dịch: Tôi đang đọc chương cuối cùng của cuốn tiểu thuyết này.)","The teacher assigned [chapter] four for tonight's homework. (=Dịch: Giáo viên đã giao chương bốn làm bài tập về nhà tối nay.)","Graduating from university marked a new [chapter] in her life. (=Dịch: Tốt nghiệp đại học đã đánh dấu một chương mới trong cuộc đời cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=chapter&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6p.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chapter&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6p.t%C9%9A%2F"},{"id":"lv_7_19","topic":"Education and Learning","word":"checking","pos":"(n)","ipa":"/ˈtʃek.ɪŋ/","defVi":"việc kiểm tra, rà soát","defEn":"the act of examining something to ensure its correctness, safety, or quality","examples":["Regular [checking] of the equipment ensures the safety of the workers. (=Dịch: Việc kiểm tra thiết bị định kỳ đảm bảo an toàn cho công nhân.)","After thorough [checking], the auditor found no errors in the financial report. (=Dịch: Sau khi rà soát kỹ lưỡng, kiểm toán viên không tìm thấy sai sót nào trong báo cáo tài chính.)","The security staff is responsible for the [checking] of all visitors' luggage. (=Dịch: Nhân viên an ninh chịu trách nhiệm kiểm tra hành lý của tất cả du khách.)"],"ukAudio":"/ai_services/tts3/?q=checking&lang=en-GB&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=checking&lang=en-US&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F"},{"id":"lv_7_20","topic":"Education and Learning","word":"childcare","pos":"(n)","ipa":"/ˈtʃaɪld.ker/","defVi":"việc trông nom, chăm sóc trẻ em","defEn":"the care of children, especially by a day-care center or babysitter while parents are at work","examples":["High [childcare] costs prevent many parents from returning to full-time work. (=Dịch: Chi phí chăm sóc trẻ cao khiến nhiều bậc cha mẹ không thể quay lại làm việc toàn thời gian.)","The company provides free [childcare] facilities for its employees. (=Dịch: Công ty cung cấp cơ sở trông trẻ miễn phí cho nhân viên của mình.)","She is looking for a reliable [childcare] provider near her home. (=Dịch: Cô ấy đang tìm kiếm một nơi gửi trẻ đáng tin cậy gần nhà.)"],"ukAudio":"/ai_services/tts3/?q=childcare&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.ker%2F","usAudio":"/ai_services/tts3/?q=childcare&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.ker%2F"},{"id":"lv_7_21","topic":"Education and Learning","word":"chronological","pos":"(adj)","ipa":"/ˌkrɑ.nəˈlɑ.dʒɪ.kəl/","defVi":"theo trình tự thời gian","defEn":"arranged in the order in which events happened","examples":["The museum displays historical artifacts in strict [chronological] order. (=Dịch: Bảo tàng trưng bày các hiện vật lịch sử theo đúng trình tự thời gian.)","Please list your previous work experience in [chronological] sequence on your resume. (=Dịch: Vui lòng liệt kê kinh nghiệm làm việc trước đây của bạn theo thứ tự thời gian trong hồ sơ xin việc.)","The biographer recounted the artist's life through a clear [chronological] narrative. (=Dịch: Người viết tiểu sử đã kể lại cuộc đời của người nghệ sĩ thông qua một mạch dẫn chuyện theo thời gian rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=chronological&lang=en-GB&ipa=%2F%CB%8Ckr%C9%91.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=chronological&lang=en-US&ipa=%2F%CB%8Ckr%C9%91.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_7_22","topic":"Education and Learning","word":"clarity","pos":"(n)","ipa":"/ˈklær.ə.t̬i/","defVi":"sự rõ ràng, tính minh bạch","defEn":"the quality of being clear and easy to understand or see","examples":["The teacher explained the complex math topic with great [clarity]. (=Dịch: Giáo viên đã giải thích chủ đề toán học phức tạp một cách rất rõ ràng.)","Writing with [clarity] helps readers follow your main argument easily. (=Dịch: Viết một cách rõ ràng giúp người đọc dễ dàng theo dõi luận điểm chính của bạn.)","The water in the mountain lake is famous for its incredible [clarity]. (=Dịch: Nước trong hồ trên núi nổi tiếng với độ trong vắt đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=clarity&lang=en-GB&ipa=%2F%CB%88kl%C3%A6r.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=clarity&lang=en-US&ipa=%2F%CB%88kl%C3%A6r.%C9%99.t%CC%ACi%2F"},{"id":"lv_7_23","topic":"Education and Learning","word":"classmate","pos":"(n)","ipa":"/ˈklæs.meɪt/","defVi":"Bạn cùng lớp.","defEn":"A person who is in the same class as you at school or college.","examples":["She collaborated with her [classmate] on the biology project. (=Dịch: Cô ấy đã hợp tác với bạn cùng lớp trong dự án sinh học.)","I met an old [classmate] while shopping at the supermarket yesterday. (=Dịch: Hôm qua tôi tình cờ gặp một người bạn học cũ khi đang mua sắm ở siêu thị.)","He asked his [classmate] to lend him some lecture notes. (=Dịch: Cậu ấy đã nhờ bạn cùng lớp cho mượn một số ghi chép bài giảng.)"],"ukAudio":"/ai_services/tts3/?q=classmate&lang=en-GB&ipa=%2F%CB%88kl%C3%A6s.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=classmate&lang=en-US&ipa=%2F%CB%88kl%C3%A6s.me%C9%AAt%2F"},{"id":"lv_7_24","topic":"Education and Learning","word":"confused","pos":"(adj)","ipa":"/kənˈfjuzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to understand clearly or think properly","examples":["The instructions were unclear, so many students felt [confused]. (=Dịch: Hướng dẫn không rõ ràng nên nhiều học sinh cảm thấy bối rối.)","She looked completely [confused] when asked about the missing files. (=Dịch: Cô ấy trông hoàn toàn hoang mang khi được hỏi về các tập tin bị mất.)","I am [confused] about which university course I should choose. (=Dịch: Tôi đang phân vân không biết nên chọn khóa học đại học nào.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fjuzd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fjuzd%2F"},{"id":"lv_7_25","topic":"Education and Learning","word":"confusing","pos":"(adj)","ipa":"/kənˈfju.zɪŋ/","defVi":"gây bối rối, khó hiểu","defEn":"difficult to understand; not clear","examples":["The instructions on the box were very [confusing] for the beginners. (=Dịch: Hướng dẫn trên vỏ hộp rất khó hiểu đối với người mới bắt đầu.)","I found the ending of the movie rather [confusing]. (=Dịch: Tôi thấy cái kết của bộ phim khá khó hiểu.)","The city has a [confusing] network of one-way streets. (=Dịch: Thành phố có một mạng lưới đường một chiều gây rối mắt.)"],"ukAudio":"/ai_services/tts3/?q=confusing&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=confusing&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju.z%C9%AA%C5%8B%2F"},{"id":"lv_7_26","topic":"Education and Learning","word":"congratulation","pos":"(n)","ipa":"/kənˌɡrætʃ.əˈleɪ.ʃən/","defVi":"lời chúc mừng, sự chúc mừng","defEn":"an expression of praise for someone's success or good luck","examples":["She sent a message of [congratulation] to the winning team. (=Dịch: Cô ấy đã gửi một thông điệp chúc mừng đến đội chiến thắng.)","He offered his sincere [congratulation] on her promotion. (=Dịch: Anh ấy gửi lời chúc mừng chân thành về việc cô được thăng chức.)","A letter of [congratulation] was delivered to the award recipient. (=Dịch: Một lá thư chúc mừng đã được chuyển đến người nhận giải thưởng.)"],"ukAudio":"/ai_services/tts3/?q=congratulation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congratulation&lang=en-US&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_27","topic":"Education and Learning","word":"convenor","pos":"(n)","ipa":"/kənˈvi.nɚ/","defVi":"người triệu tập, người chủ trì cuộc họp","defEn":"a person who arranges and chairs meetings of a committee or group","examples":["The [convenor] opened the committee meeting by introducing the agenda. (=Dịch: Người triệu tập đã mở đầu cuộc họp ủy ban bằng cách giới thiệu chương trình nghị sự.)","Please send your discussion topics to the conference [convenor] before Friday. (=Dịch: Vui lòng gửi các chủ đề thảo luận của bạn cho người triệu tập hội nghị trước thứ Sáu.)","As the study group [convenor], she ensured everyone had a chance to speak. (=Dịch: Với tư cách là người chủ trì nhóm học tập, cô ấy đảm bảo mọi người đều có cơ hội phát biểu.)"],"ukAudio":"/ai_services/tts3/?q=convenor&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=convenor&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi.n%C9%9A%2F"},{"id":"lv_7_28","topic":"Education and Learning","word":"counselling","pos":"(n)","ipa":"/ˈkaʊn.səl.ɪŋ/","defVi":"sự tư vấn, sự tham vấn tâm lý","defEn":"professional guidance and support to help people resolve personal or psychological problems","examples":["The university offers free student [counselling] for those experiencing stress. (=Dịch: Trường đại học cung cấp dịch vụ tư vấn sinh viên miễn phí cho những ai đang bị căng thẳng.)","She decided to seek marriage [counselling] to work through their communication issues. (=Dịch: Cô ấy quyết định tìm đến tư vấn hôn nhân để giải quyết các vấn đề giao tiếp giữa hai người.)","Grief [counselling] helped him cope with the sudden loss of his father. (=Dịch: Dịch vụ tư vấn tâm lý sau mất mát đã giúp anh ấy vượt qua sự ra đi đột ngột của người cha.)"],"ukAudio":"/ai_services/tts3/?q=counselling&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.s%C9%99l.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=counselling&lang=en-US&ipa=%2F%CB%88ka%CA%8An.s%C9%99l.%C9%AA%C5%8B%2F"},{"id":"lv_7_29","topic":"Education and Learning","word":"coursework","pos":"(n)","ipa":"/ˈkɔrs.wɝːk/","defVi":"bài tập trong khóa học, bài tập quá trình","defEn":"work done by students as part of their studies, contributing towards their final grade","examples":["Her final grade depends on both exam results and continuous [coursework]. (=Dịch: Điểm tổng kết của cô ấy phụ thuộc vào cả kết quả thi và các bài tập trong suốt khóa học.)","Students spent the weekend finishing their history [coursework] assignments. (=Dịch: Các sinh viên đã dành cả cuối tuần để hoàn thành bài tập môn lịch sử.)","Managing your time well is essential when dealing with heavy [coursework]. (=Dịch: Quản lý thời gian tốt là điều cần thiết khi phải xử lý khối lượng bài tập khóa học lớn.)"],"ukAudio":"/ai_services/tts3/?q=coursework&lang=en-GB&ipa=%2F%CB%88k%C9%94rs.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=coursework&lang=en-US&ipa=%2F%CB%88k%C9%94rs.w%C9%9D%CB%90k%2F"},{"id":"lv_7_30","topic":"Education and Learning","word":"cricket","pos":"(n)","ipa":"/ˈkrɪk.ɪt/","defVi":"môn bóng gậy (cricket); con dế","defEn":"an outdoor game played with bats, a ball, and wickets by two teams of eleven players","examples":["Many people in England and Australia love playing [cricket]. (=Dịch: Nhiều người ở Anh và Úc rất thích chơi môn bóng gậy.)","The sound of a [cricket] chirping kept him awake all night. (=Dịch: Tiếng dế kêu rỉ rả đã khiến anh ấy mất ngủ cả đêm.)","Our school has recently formed a new [cricket] team. (=Dịch: Trường chúng tôi gần đây đã thành lập một đội cricket mới.)"],"ukAudio":"/ai_services/tts3/?q=cricket&lang=en-GB&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=cricket&lang=en-US&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F"},{"id":"lv_7_31","topic":"Education and Learning","word":"crisis","pos":"(n)","ipa":"/ˈkraɪ.sɪs/","defVi":"cuộc khủng hoảng","defEn":"a time of great danger, difficulty, or uncertainty","examples":["The government is trying to resolve the current economic [crisis]. (=Dịch: Chính phủ đang nỗ lực giải quyết cuộc khủng hoảng kinh tế hiện nay.)","She managed to stay calm throughout the family [crisis]. (=Dịch: Cô ấy đã cố gắng giữ bình tĩnh trong suốt biến cố của gia đình.)","Climate change is leading to an environmental [crisis] across the globe. (=Dịch: Biến đổi khí hậu đang dẫn đến một cuộc khủng hoảng môi trường trên toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=crisis&lang=en-GB&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=crisis&lang=en-US&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F"},{"id":"lv_7_32","topic":"Education and Learning","word":"criterion","pos":"(n)","ipa":"/kraɪˈtɪr.i.ən/","defVi":"tiêu chí, chuẩn mực","defEn":"a standard by which something is judged or decided","examples":["Academic ability is not the only [criterion] for university admission. (=Dịch: Năng lực học thuật không phải là tiêu chí duy nhất để xét tuyển đại học.)","Price was the main [criterion] we considered when choosing a hotel. (=Dịch: Giá cả là tiêu chí chính mà chúng tôi cân nhắc khi chọn khách sạn.)","Each candidate must meet the minimum [criterion] to qualify. (=Dịch: Mỗi ứng viên phải đáp ứng tiêu chí tối thiểu để đủ điều kiện.)"],"ukAudio":"/ai_services/tts3/?q=criterion&lang=en-GB&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=criterion&lang=en-US&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F"},{"id":"lv_7_33","topic":"Education and Learning","word":"critical","pos":"(adj)","ipa":"/ˈkrɪt̬.ɪ.kəl/","defVi":"Then chốt, quan trọng; có tính phản biện, chỉ trích","defEn":"Extremely important or involving the objective analysis and evaluation of an issue","examples":["Developing [critical] thinking skills is essential for academic success. (=Dịch: Phát triển các kỹ năng tư duy phản biện là điều thiết yếu để đạt được thành công trong học tập.)","The doctor stated that the patient was in a [critical] condition. (=Dịch: Bác sĩ tuyên bố rằng bệnh nhân đang trong tình trạng nguy kịch.)","Timely communication plays a [critical] role in effective project management. (=Dịch: Giao tiếp kịp thời đóng một vai trò then chốt trong việc quản lý dự án hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=critical&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=critical&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F"},{"id":"lv_7_34","topic":"Education and Learning","word":"crystal","pos":"(n)","ipa":"/ˈkrɪs.təl/","defVi":"pha lê, tinh thể","defEn":"a clear, transparent mineral or piece of high-quality glass","examples":["The chandelier was made of hundreds of sparkling [crystal] pieces. (=Dịch: Chiếc đèn chùm được làm từ hàng trăm mảnh pha lê lấp lánh.)","Scientists studied the structure of the ice [crystal] under a microscope. (=Dịch: Các nhà khoa học đã nghiên cứu cấu trúc của tinh thể băng dưới kính hiển vi.)","She keeps a small quartz [crystal] on her study desk for decoration. (=Dịch: Cô ấy để một viên tinh thể thạch anh nhỏ trên bàn học để trang trí.)"],"ukAudio":"/ai_services/tts3/?q=crystal&lang=en-GB&ipa=%2F%CB%88kr%C9%AAs.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=crystal&lang=en-US&ipa=%2F%CB%88kr%C9%AAs.t%C9%99l%2F"},{"id":"lv_7_35","topic":"Education and Learning","word":"cursive","pos":"(adj)","ipa":"/ˈkɝː.sɪv/","defVi":"viết chữ thảo, chữ viết hoa/nối nét","defEn":"written with the characters joined together in a flowing style","examples":["Young children are taught how to write in [cursive] at elementary school. (=Dịch: Trẻ nhỏ được dạy cách viết chữ thảo ở trường tiểu học.)","His signature is written in an elegant [cursive] script. (=Dịch: Chữ ký của anh ấy được viết bằng nét chữ thảo rất thanh lịch.)","It is sometimes difficult to read old historical documents written in [cursive]. (=Dịch: Đôi khi rất khó để đọc các tài liệu lịch sử cổ được viết bằng chữ thảo.)"],"ukAudio":"/ai_services/tts3/?q=cursive&lang=en-GB&ipa=%2F%CB%88k%C9%9D%CB%90.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cursive&lang=en-US&ipa=%2F%CB%88k%C9%9D%CB%90.s%C9%AAv%2F"},{"id":"lv_7_36","topic":"Education and Learning","word":"cushion","pos":"(n)","ipa":"/ˈkʊʃ.ən/","defVi":"gối đệm, vật đệm lót; lớp đệm bảo vệ","defEn":"a soft bag filled with soft material, used to make a seat more comfortable; something that softens an impact","examples":["She placed a comfortable [cushion] behind her back while working at her desk. (=Dịch: Cô ấy đặt một chiếc gối tựa êm ái sau lưng khi làm việc tại bàn.)","Emergency savings can act as a financial [cushion] against unexpected expenses. (=Dịch: Các khoản tiết kiệm khẩn cấp có thể đóng vai trò như một lớp đệm tài chính trước các chi phí bất ngờ.)","He bought several colorful [cushion]s to decorate the living room sofa. (=Dịch: Anh ấy đã mua vài chiếc gối đệm nhiều màu sắc để trang trí cho ghế sofa phòng khách.)"],"ukAudio":"/ai_services/tts3/?q=cushion&lang=en-GB&ipa=%2F%CB%88k%CA%8A%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cushion&lang=en-US&ipa=%2F%CB%88k%CA%8A%CA%83.%C9%99n%2F"},{"id":"lv_7_37","topic":"Education and Learning","word":"dairy","pos":"(n)","ipa":"/ˈder.i/","defVi":"sản phẩm từ sữa; nơi sản xuất bơ sữa","defEn":"foods produced from milk, or a place where milk and milk products are processed","examples":["He cannot eat cheese or other [dairy] products because of his allergy. (=Dịch: Anh ấy không thể ăn phô mai hoặc các sản phẩm từ sữa khác vì bị dị ứng.)","Our family visited a local [dairy] farm during the weekend. (=Dịch: Gia đình chúng tôi đã đến thăm một trang trại bò sữa địa phương vào cuối tuần.)","The doctor advised her to reduce her daily intake of [dairy]. (=Dịch: Bác sĩ khuyên cô nên giảm lượng sản phẩm từ sữa tiêu thụ hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=dairy&lang=en-GB&ipa=%2F%CB%88der.i%2F","usAudio":"/ai_services/tts3/?q=dairy&lang=en-US&ipa=%2F%CB%88der.i%2F"},{"id":"lv_7_38","topic":"Education and Learning","word":"danish","pos":"(adj)","ipa":"/ˈdeɪ.nɪʃ/","defVi":"thuộc về Đan Mạch","defEn":"relating to Denmark, its people, or its language","examples":["She loves modern [danish] furniture design for its simplicity and elegance. (=Dịch: Cô ấy rất thích phong cách thiết kế nội thất Đan Mạch hiện đại vì sự đơn giản và thanh lịch.)","We enjoyed learning about traditional [danish] folklore during our trip to Copenhagen. (=Dịch: Chúng tôi rất thích tìm hiểu về văn hóa dân gian Đan Mạch truyền thống trong chuyến đi đến Copenhagen.)","The bakery is famous for its delicious [danish] pastries and fresh bread. (=Dịch: Tiệm bánh nổi tiếng với những chiếc bánh ngọt kiểu Đan Mạch thơm ngon và bánh mì tươi.)"],"ukAudio":"/ai_services/tts3/?q=danish&lang=en-GB&ipa=%2F%CB%88de%C9%AA.n%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=danish&lang=en-US&ipa=%2F%CB%88de%C9%AA.n%C9%AA%CA%83%2F"},{"id":"lv_7_39","topic":"Education and Learning","word":"denmark","pos":"(n)","ipa":"/ˈdɛn.mɑrk/","defVi":"Đan Mạch (quốc gia ở Bắc Âu)","defEn":"A Nordic country in Northern Europe whose capital is Copenhagen","examples":["Many international students choose to study in [denmark] due to its high living standards. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Đan Mạch nhờ tiêu chuẩn sống cao tại đây.)","Cycling is one of the most popular modes of transport throughout [denmark]. (=Dịch: Đi xe đạp là một trong những phương tiện giao thông phổ biến nhất trên khắp Đan Mạch.)","She spent two weeks traveling across [denmark] during her summer vacation. (=Dịch: Cô ấy đã dành hai tuần đi du lịch khắp Đan Mạch trong kỳ nghỉ hè của mình.)"],"ukAudio":"/ai_services/tts3/?q=denmark&lang=en-GB&ipa=%2F%CB%88d%C9%9Bn.m%C9%91rk%2F","usAudio":"/ai_services/tts3/?q=denmark&lang=en-US&ipa=%2F%CB%88d%C9%9Bn.m%C9%91rk%2F"},{"id":"lv_7_40","topic":"Education and Learning","word":"detailed","pos":"(adj)","ipa":"/dɪˈteɪld/","defVi":"chi tiết, tỉ mỉ","defEn":"giving a lot of information with many facts and points","examples":["The architect presented a [detailed] plan for the new library building. (=Dịch: Kiến trúc sư đã trình bày một bản kế hoạch chi tiết cho tòa nhà thư viện mới.)","You should provide a [detailed] description of the incident in your report. (=Dịch: Bạn nên cung cấp một bản mô tả chi tiết về sự việc trong báo cáo của mình.)","The researcher carried out a [detailed] analysis of the survey results. (=Dịch: Nhà nghiên cứu đã tiến hành một phân tích chi tiết về kết quả khảo sát.)"],"ukAudio":"/ai_services/tts3/?q=detailed&lang=en-GB&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=detailed&lang=en-US&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F"},{"id":"lv_7_41","topic":"Education and Learning","word":"dietary","pos":"(adj)","ipa":"/ˈdaɪ.ə.ter.i/","defVi":"thuộc chế độ ăn uống, ăn kiêng","defEn":"connected with the food that a person or animal regularly eats","examples":["You should inform the caterer about any special [dietary] requirements before the party. (=Dịch: Bạn nên thông báo cho bên cung cấp tiệc về bất kỳ yêu cầu ăn uống đặc biệt nào trước bữa tiệc.)","Doctors recommend making gradual [dietary] changes to lower cholesterol levels. (=Dịch: Các bác sĩ khuyên nên thay đổi dần dần chế độ ăn uống để hạ lượng cholesterol.)","Adequate [dietary] fiber is essential for maintaining a healthy digestive system. (=Dịch: Cung cấp đủ chất xơ trong chế độ ăn là điều cần thiết để duy trì hệ tiêu hóa khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=dietary&lang=en-GB&ipa=%2F%CB%88da%C9%AA.%C9%99.ter.i%2F","usAudio":"/ai_services/tts3/?q=dietary&lang=en-US&ipa=%2F%CB%88da%C9%AA.%C9%99.ter.i%2F"},{"id":"lv_7_42","topic":"Education and Learning","word":"diploma","pos":"(n)","ipa":"/dɪˈploʊ.mə/","defVi":"bằng cấp, chứng chỉ tốt nghiệp","defEn":"an official document issued by an educational institution showing that someone has successfully completed a course of study","examples":["After four years of hard work, she proudly received her high school [diploma]. (=Dịch: Sau bốn năm nỗ lực, cô ấy đã tự hào nhận được tấm bằng tốt nghiệp trung học của mình.)","You must submit a copy of your university [diploma] with the job application. (=Dịch: Bạn phải nộp một bản sao bằng tốt nghiệp đại học cùng với đơn xin việc.)","He enrolled in an online course to earn a [diploma] in digital marketing. (=Dịch: Anh ấy đã đăng ký một khóa học trực tuyến để lấy chứng chỉ về tiếp thị kỹ thuật số.)"],"ukAudio":"/ai_services/tts3/?q=diploma&lang=en-GB&ipa=%2Fd%C9%AA%CB%88plo%CA%8A.m%C9%99%2F","usAudio":"/ai_services/tts3/?q=diploma&lang=en-US&ipa=%2Fd%C9%AA%CB%88plo%CA%8A.m%C9%99%2F"},{"id":"lv_7_43","topic":"Education and Learning","word":"disadvantage","pos":"(n)","ipa":"/ˌdɪs.ədˈvæn.t̬ɪdʒ/","defVi":"Bất lợi, điểm yếu, nhược điểm.","defEn":"An unfavorable circumstance or condition that reduces the chances of success.","examples":["One major [disadvantage] of living in the countryside is the lack of public transport. (=Dịch: Một bất lợi lớn của việc sống ở nông thôn là sự thiếu thốn phương tiện giao thông công cộng.)","Job seekers without computer skills are at a serious [disadvantage]. (=Dịch: Những người tìm việc không có kỹ năng tin học sẽ gặp bất lợi nghiêm trọng.)","The team overcame their [disadvantage] and won the match. (=Dịch: Đội bóng đã vượt qua thế bất lợi của mình và giành chiến thắng trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=disadvantage&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=disadvantage&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_7_44","topic":"Education and Learning","word":"dissertation","pos":"(n)","ipa":"/ˌdɪs.ɚˈteɪ.ʃən/","defVi":"luận văn, luận án tốt nghiệp","defEn":"a long piece of academic writing based on original research, usually for a university degree","examples":["She is currently writing her doctoral [dissertation] on renewable energy. (=Dịch: Cô ấy hiện đang viết luận án tiến sĩ về năng lượng tái tạo.)","The deadline to submit the master's [dissertation] is next Monday. (=Dịch: Hạn chót nộp luận văn thạc sĩ là vào thứ Hai tới.)","He spent months in the library gathering data for his [dissertation]. (=Dịch: Anh ấy đã dành nhiều tháng trong thư viện để thu thập dữ liệu cho luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=dissertation&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=dissertation&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_45","topic":"Education and Learning","word":"documentary","pos":"(adj)","ipa":"/ˌdɑk.jəˈmɛn.t̬ɚ.i/","defVi":"mang tính tài liệu, có tính chứng thực bằng văn bản","defEn":"consisting of or based on official documents, records, or factual accounts","examples":["The historian provided solid [documentary] evidence to support his theory. (=Dịch: Nhà sử học đã cung cấp bằng chứng tư liệu vững chắc để ủng hộ lý thuyết của mình.)","Researchers gathered [documentary] proof of the property ownership from the city archive. (=Dịch: Các nhà nghiên cứu đã thu thập bằng chứng bằng văn bản về quyền sở hữu tài sản từ kho lưu trữ của thành phố.)","The court examined all the [documentary] records before delivering the final verdict. (=Dịch: Tòa án đã xem xét tất cả các hồ sơ tài liệu trước khi đưa ra phán quyết cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=documentary&lang=en-GB&ipa=%2F%CB%8Cd%C9%91k.j%C9%99%CB%88m%C9%9Bn.t%CC%AC%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=documentary&lang=en-US&ipa=%2F%CB%8Cd%C9%91k.j%C9%99%CB%88m%C9%9Bn.t%CC%AC%C9%9A.i%2F"},{"id":"lv_7_46","topic":"Education and Learning","word":"drill","pos":"(n)","ipa":"/drɪl/","defVi":"bài luyện tập, cuộc diễn tập","defEn":"an activity that practices a particular skill through frequent repetition, or a safety exercise","examples":["The school conducts a fire [drill] at the beginning of every term. (=Dịch: Trường học tổ chức một cuộc diễn tập phòng cháy chữa cháy vào đầu mỗi học kỳ.)","Grammar [drill]s help beginner students master basic sentence structures. (=Dịch: Các bài luyện ngữ pháp lặp đi lặp lại giúp học viên mới bắt đầu nắm vững các cấu trúc câu cơ bản.)","The military squad went through intensive tactical [drill]s yesterday. (=Dịch: Đội quân sự đã trải qua các cuộc huấn luyện chiến thuật chuyên sâu ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=drill&lang=en-GB&ipa=%2Fdr%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=drill&lang=en-US&ipa=%2Fdr%C9%AAl%2F"},{"id":"lv_7_47","topic":"Education and Learning","word":"edit","pos":"(v)","ipa":"/ˈed.ɪt/","defVi":"chỉnh sửa, biên tập","defEn":"to prepare text or media for publication by correcting errors or making improvements","examples":["You should carefully [edit] your essay before submitting it to the professor. (=Dịch: Bạn nên cẩn thận chỉnh sửa bài luận của mình trước khi nộp cho giáo sư.)","He spent the entire weekend trying to [edit] the video footage. (=Dịch: Anh ấy đã dành cả ngày cuối tuần để cố gắng chỉnh sửa đoạn phim.)","The journalist was asked to [edit] the article to fit the front page. (=Dịch: Nhà báo được yêu cầu biên tập lại bài viết sao cho vừa trang bìa.)"],"ukAudio":"/ai_services/tts3/?q=edit&lang=en-GB&ipa=%2F%CB%88ed.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=edit&lang=en-US&ipa=%2F%CB%88ed.%C9%AAt%2F"},{"id":"lv_7_48","topic":"Education and Learning","word":"educational","pos":"(adj)","ipa":"/ˌedʒ.əˈkeɪ.ʃən.əl/","defVi":"mang tính giáo dục, thuộc về giáo dục","defEn":"providing useful knowledge or relating to the process of education","examples":["The museum offers many [educational] activities for young children. (=Dịch: Bảo tàng cung cấp nhiều hoạt động mang tính giáo dục cho trẻ nhỏ.)","Watching documentaries can be a deeply [educational] experience. (=Dịch: Xem phim tài liệu có thể là một trải nghiệm mang lại nhiều kiến thức bổ ích.)","The government announced major reforms to the [educational] system. (=Dịch: Chính phủ đã công bố những cải cách lớn đối với hệ thống giáo dục.)"],"ukAudio":"/ai_services/tts3/?q=educational&lang=en-GB&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=educational&lang=en-US&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_7_49","topic":"Education and Learning","word":"eligible","pos":"(adj)","ipa":"/ˈel.ɪ.dʒə.bəl/","defVi":"đủ điều kiện, đủ tư cách","defEn":"having the necessary qualities or satisfying the conditions to do or receive something","examples":["Only full-time students are [eligible] to apply for this scholarship. (=Dịch: Chỉ sinh viên chính quy mới đủ điều kiện nộp đơn xin học bổng này.)","He is [eligible] for retirement benefits after working thirty years at the company. (=Dịch: Ông ấy đủ điều kiện nhận trợ cấp hưu trí sau ba mươi năm làm việc tại công ty.)","Citizens over the age of eighteen are [eligible] to vote in the national election. (=Dịch: Công dân trên mười tám tuổi có đủ tư cách tham gia bỏ phiếu trong cuộc bầu cử quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=eligible&lang=en-GB&ipa=%2F%CB%88el.%C9%AA.d%CA%92%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=eligible&lang=en-US&ipa=%2F%CB%88el.%C9%AA.d%CA%92%C9%99.b%C9%99l%2F"},{"id":"lv_7_50","topic":"Education and Learning","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký học","defEn":"to officially register as a member or student in a course or institution","examples":["You need to [enroll] in the course before the end of this week. (=Dịch: Bạn cần phải đăng ký khóa học trước cuối tuần này.)","More than five hundred students [enroll] at the college each year. (=Dịch: Hơn năm trăm sinh viên ghi danh vào trường đại học mỗi năm.)","She decided to [enroll] her son in an online coding class. (=Dịch: Cô ấy quyết định đăng ký cho con trai mình vào một lớp học lập trình trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_7_51","topic":"Education and Learning","word":"enthusiastic","pos":"(adj)","ipa":"/ɪnˌθuː.ziˈæs.tɪk/","defVi":"nhiệt tình, hăng hái","defEn":"feeling or showing a lot of excitement and interest about something","examples":["The students were very [enthusiastic] about the upcoming science fair. (=Dịch: Các học sinh rất hào hứng với hội chợ khoa học sắp tới.)","She received an [enthusiastic] welcome from her colleagues on her first day. (=Dịch: Cô ấy đã nhận được sự chào đón nồng nhiệt từ các đồng nghiệp vào ngày đầu tiên đi làm.)","He is an [enthusiastic] supporter of renewable energy initiatives. (=Dịch: Anh ấy là một người ủng hộ nhiệt tình cho các sáng kiến năng lượng tái tạo.)"],"ukAudio":"/ai_services/tts3/?q=enthusiastic&lang=en-GB&ipa=%2F%C9%AAn%CB%8C%CE%B8u%CB%90.zi%CB%88%C3%A6s.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=enthusiastic&lang=en-US&ipa=%2F%C9%AAn%CB%8C%CE%B8u%CB%90.zi%CB%88%C3%A6s.t%C9%AAk%2F"},{"id":"lv_7_52","topic":"Education and Learning","word":"evaluation","pos":"(n)","ipa":"/ɪˌvæl.juˈeɪ.ʃən/","defVi":"sự đánh giá, thẩm định","defEn":"the process of judging the quality, value, or importance of something","examples":["The teacher conducted a careful [evaluation] of each student's project. (=Dịch: Giáo viên đã tiến hành đánh giá cẩn thận dự án của từng học sinh.)","Employees receive a performance [evaluation] at the end of every year. (=Dịch: Nhân viên nhận được một bản đánh giá hiệu suất làm việc vào cuối mỗi năm.)","The medical trial is still under scientific [evaluation]. (=Dịch: Thử nghiệm y khoa vẫn đang trong quá trình đánh giá khoa học.)"],"ukAudio":"/ai_services/tts3/?q=evaluation&lang=en-GB&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evaluation&lang=en-US&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_53","topic":"Education and Learning","word":"excuse","pos":"(n)","ipa":"/ɪkˈskjus/","defVi":"lời bào chữa, cớ, lý do","defEn":"a reason given to explain or justify a fault, mistake, or absence","examples":["He always makes up an [excuse] for arriving late to meetings. (=Dịch: Anh ấy luôn bịa ra một lý do để biện minh cho việc đến họp muộn.)","Tiredness is no [excuse] for being rude to customers. (=Dịch: Sự mệt mỏi không phải là cái cớ để bất lịch sự với khách hàng.)","She needed a valid [excuse] to leave the party early. (=Dịch: Cô ấy cần một lý do chính đáng để rời khỏi bữa tiệc sớm.)"],"ukAudio":"/ai_services/tts3/?q=excuse&lang=en-GB&ipa=%2F%C9%AAk%CB%88skjus%2F","usAudio":"/ai_services/tts3/?q=excuse&lang=en-US&ipa=%2F%C9%AAk%CB%88skjus%2F"},{"id":"lv_7_54","topic":"Education and Learning","word":"extension","pos":"(n)","ipa":"/ɪkˈsten.ʃən/","defVi":"sự gia hạn, phần kéo dài","defEn":"an extra period of time allowed to complete an activity or meet a deadline","examples":["The student requested an [extension] on her assignment due to illness. (=Dịch: Nữ sinh đã xin gia hạn bài tập vì bị ốm.)","The company was granted a two-month [extension] to complete the construction project. (=Dịch: Công ty đã được cấp thêm hai tháng gia hạn để hoàn thành dự án xây dựng.)","If you need to reach him, please dial [extension] 402. (=Dịch: Nếu bạn cần liên hệ với anh ấy, vui lòng bấm số máy lẻ 402.)"],"ukAudio":"/ai_services/tts3/?q=extension&lang=en-GB&ipa=%2F%C9%AAk%CB%88sten.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=extension&lang=en-US&ipa=%2F%C9%AAk%CB%88sten.%CA%83%C9%99n%2F"},{"id":"lv_7_55","topic":"Education and Learning","word":"external","pos":"(adj)","ipa":"/ɪkˈstɝː.nəl/","defVi":"bên ngoài, ngoại lai","defEn":"connected with or located on the outside of something","examples":["The company hired an [external] consultant to review its finances. (=Dịch: Công ty đã thuê một chuyên gia tư vấn bên ngoài để kiểm toán tài chính.)","This medicine is for [external] use only and should not be swallowed. (=Dịch: Thuốc này chỉ dùng ngoài da và không được nuốt.)","The building suffered minor damage to its [external] walls. (=Dịch: Tòa nhà bị hư hại nhẹ ở các bức tường bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_7_56","topic":"Education and Learning","word":"faculty","pos":"(n)","ipa":"/ˈfæk.əl.t̬i/","defVi":"giảng viên toàn trường, khoa (trong trường đại học)","defEn":"the teaching staff of a university or college; a group of departments in a university","examples":["She joined the university [faculty] as a professor of history. (=Dịch: Cô ấy đã gia nhập đội ngũ giảng viên đại học với tư cách là giáo sư lịch sử.)","The meeting was attended by both students and [faculty] members. (=Dịch: Cuộc họp có sự tham dự của cả sinh viên và các thành viên ban giảng huấn.)","He is studying in the [faculty] of law. (=Dịch: Anh ấy đang học tại khoa luật.)"],"ukAudio":"/ai_services/tts3/?q=faculty&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.%C9%99l.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=faculty&lang=en-US&ipa=%2F%CB%88f%C3%A6k.%C9%99l.t%CC%ACi%2F"},{"id":"lv_7_57","topic":"Education and Learning","word":"failure","pos":"(n)","ipa":"/ˈfeɪl.jɚ/","defVi":"sự thất bại, sự hỏng hóc","defEn":"a lack of success in doing something; a situation where something stops working","examples":["Learning from [failure] is an essential part of personal growth. (=Dịch: Học hỏi từ thất bại là một phần thiết yếu của sự trưởng thành cá nhân.)","The sudden power [failure] left the entire city in darkness. (=Dịch: Sự cố mất điện đột ngột đã khiến toàn bộ thành phố chìm trong bóng tối.)","The business ended in financial [failure] after just two years. (=Dịch: Doanh nghiệp đã kết thúc trong thất bại tài chính chỉ sau hai năm.)"],"ukAudio":"/ai_services/tts3/?q=failure&lang=en-GB&ipa=%2F%CB%88fe%C9%AAl.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=failure&lang=en-US&ipa=%2F%CB%88fe%C9%AAl.j%C9%9A%2F"},{"id":"lv_7_58","topic":"Education and Learning","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập","defEn":"to bend something over on itself so that one part covers another","examples":["Please [fold] the letter and put it inside the envelope. (=Dịch: Làm ơn hãy gấp lá thư lại và cho vào bên trong phong bì.)","He helped his mother [fold] the clean laundry. (=Dịch: Cậu ấy đã giúp mẹ mình gấp quần áo sạch.)","She showed the children how to [fold] paper into origami birds. (=Dịch: Cô ấy đã hướng dẫn những đứa trẻ cách gấp giấy thành những con chim origami.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_7_59","topic":"Education and Learning","word":"frustrate","pos":"(v)","ipa":"/ˈfrʌs.treɪt/","defVi":"Làm bực bội, làm nản lòng, cản trở","defEn":"To make someone feel annoyed or upset because they cannot achieve something","examples":["Complex grammar rules often [frustrate] beginner language learners. (=Dịch: Các quy tắc ngữ pháp phức tạp thường làm cho người mới học ngoại ngữ nản lòng.)","Technical delays will [frustrate] users trying to submit their applications online. (=Dịch: Sự chậm trễ kỹ thuật sẽ khiến những người dùng đang cố nộp đơn trực tuyến cảm thấy bực bội.)","Frequent bad weather continues to [frustrate] rescue efforts in the mountains. (=Dịch: Thời tiết xấu kéo dài tiếp tục cản trở những nỗ lực cứu hộ ở vùng núi.)"],"ukAudio":"/ai_services/tts3/?q=frustrate&lang=en-GB&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=frustrate&lang=en-US&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AAt%2F"},{"id":"lv_7_60","topic":"Education and Learning","word":"frustrating","pos":"(adj)","ipa":"/ˈfrʌs.treɪ.tɪŋ/","defVi":"gây ức chế, bực bội, nản lòng","defEn":"making someone feel annoyed, impatient, or discouraged","examples":["It is very [frustrating] when the internet connection keeps dropping during a meeting. (=Dịch: Rất bực mình khi kết nối mạng cứ liên tục bị ngắt trong cuộc họp.)","Waiting in long queues at the airport can be an extremely [frustrating] experience. (=Dịch: Xếp hàng dài chờ đợi ở sân bay có thể là một trải nghiệm vô cùng khó chịu.)","Trying to learn a complex software without guidance is quite [frustrating]. (=Dịch: Cố gắng học một phần mềm phức tạp mà không có hướng dẫn khá là nản lòng.)"],"ukAudio":"/ai_services/tts3/?q=frustrating&lang=en-GB&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=frustrating&lang=en-US&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_7_61","topic":"Education and Learning","word":"genre","pos":"(n)","ipa":"/ˈʒɑːn.rə/","defVi":"thể loại (nghệ thuật, văn học, âm nhạc)","defEn":"a particular style or category of art, music, or literature","examples":["Science fiction is a popular literary [genre] among young readers. (=Dịch: Khoa học viễn tưởng là một thể loại văn học được nhiều độc giả trẻ yêu thích.)","The director is famous for experimenting with different film [genre]s. (=Dịch: Vị đạo diễn này nổi tiếng với việc thử nghiệm các thể loại phim khác nhau.)","Jazz is a distinct musical [genre] that originated in the United States. (=Dịch: Jazz là một thể loại âm nhạc đặc sắc có nguồn gốc từ Hoa Kỳ.)"],"ukAudio":"/ai_services/tts3/?q=genre&lang=en-GB&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F","usAudio":"/ai_services/tts3/?q=genre&lang=en-US&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F"},{"id":"lv_7_62","topic":"Education and Learning","word":"grade","pos":"(n)","ipa":"/ɡreɪd/","defVi":"điểm số, cấp lớp","defEn":"a mark indicating a student's level of achievement in a test or course","examples":["She studied all weekend to get a high [grade] on her math exam. (=Dịch: Cô ấy đã học suốt cuối tuần để đạt điểm cao trong kỳ thi toán.)","Students with the best [grade] averages will receive academic awards. (=Dịch: Những học sinh có điểm trung bình cao nhất sẽ nhận được các giải thưởng học thuật.)","Her parents were delighted with her final report card [grade]. (=Dịch: Bố mẹ cô ấy rất vui mừng với điểm số trong phiếu báo cáo cuối kỳ của cô.)"],"ukAudio":"/ai_services/tts3/?q=grade&lang=en-GB&ipa=%2F%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=grade&lang=en-US&ipa=%2F%C9%A1re%C9%AAd%2F"},{"id":"lv_7_63","topic":"Education and Learning","word":"graduate","pos":"(v)","ipa":"/ˈɡrædʒ.u.eɪt/","defVi":"tốt nghiệp","defEn":"to successfully complete a degree or course of study at a university or school","examples":["She will [graduate] from university with a degree in computer science next year. (=Dịch: Cô ấy sẽ tốt nghiệp đại học với tấm bằng khoa học máy tính vào năm tới.)","Many students hope to find a good job as soon as they [graduate]. (=Dịch: Nhiều sinh viên hy vọng tìm được việc làm tốt ngay sau khi họ tốt nghiệp.)","He worked hard to [graduate] at the top of his high school class. (=Dịch: Anh ấy đã chăm chỉ học tập để tốt nghiệp với vị trí thủ khoa lớp cấp ba.)"],"ukAudio":"/ai_services/tts3/?q=graduate&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=graduate&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.e%C9%AAt%2F"},{"id":"lv_7_64","topic":"Education and Learning","word":"graph","pos":"(n)","ipa":"/ɡræf/","defVi":"đồ thị, biểu đồ","defEn":"a diagram showing the relationship between two or more sets of numbers or measurements","examples":["The line [graph] illustrates the changes in population over ten years. (=Dịch: Biểu đồ đường minh họa những thay đổi về dân số qua mười năm.)","Please analyze the data presented in this [graph]. (=Dịch: Vui lòng phân tích dữ liệu được trình bày trong biểu đồ này.)","The sales figures are clearly summarized in the [graph] below. (=Dịch: Số liệu bán hàng được tóm tắt rõ ràng trong biểu đồ bên dưới.)"],"ukAudio":"/ai_services/tts3/?q=graph&lang=en-GB&ipa=%2F%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=graph&lang=en-US&ipa=%2F%C9%A1r%C3%A6f%2F"},{"id":"lv_7_65","topic":"Education and Learning","word":"graphic","pos":"(adj)","ipa":"/ˈɡræf.ɪk/","defVi":"thuộc đồ họa, trực quan; sinh động, rõ ràng","defEn":"connected with drawings, design, or visual images; also describing something in very clear detail","examples":["She works as a [graphic] designer for a major advertising agency. (=Dịch: Cô ấy làm việc với tư cách là một nhà thiết kế đồ họa cho một công ty quảng cáo lớn.)","The documentary provided a [graphic] account of the effects of climate change. (=Dịch: Bộ phim tài liệu đã cung cấp một bản mô tả chi tiết và sống động về những tác động của biến đổi khí hậu.)","The software provides a user-friendly [graphic] interface. (=Dịch: Phần mềm cung cấp một giao diện đồ họa thân thiện với người dùng.)"],"ukAudio":"/ai_services/tts3/?q=graphic&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=graphic&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F"},{"id":"lv_7_66","topic":"Education and Learning","word":"guidance","pos":"(n)","ipa":"/ˈɡaɪ.dəns/","defVi":"sự hướng dẫn, sự chỉ dẫn","defEn":"help or advice given to someone, especially by someone with more knowledge or experience","examples":["Students often seek career [guidance] from their academic advisors. (=Dịch: Sinh viên thường tìm kiếm sự định hướng nghề nghiệp từ các cố vấn học tập của họ.)","Under the coach's [guidance], the young team improved significantly. (=Dịch: Dưới sự chỉ dẫn của huấn luyện viên, đội bóng trẻ đã tiến bộ rõ rệt.)","The booklet offers useful [guidance] on how to manage personal finances. (=Dịch: Cuốn sổ tay cung cấp những hướng dẫn hữu ích về cách quản lý tài chính cá nhân.)"],"ukAudio":"/ai_services/tts3/?q=guidance&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AA.d%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=guidance&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AA.d%C9%99ns%2F"},{"id":"lv_7_67","topic":"Education and Learning","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay, bài giảng in sẵn","defEn":"a document or summary given to people attending a class, lecture, or meeting","examples":["The teacher distributed a useful [handout] containing key vocabulary for the test. (=Dịch: Giáo viên đã phát một tài liệu phát tay hữu ích chứa các từ vựng quan trọng cho bài kiểm tra.)","Please refer to page two of the [handout] for detailed statistics. (=Dịch: Vui lòng tham khảo trang hai của tài liệu phát tay để biết số liệu thống kê chi tiết.)","Instead of relying on a government [handout], he preferred finding a steady job. (=Dịch: Thay vì trông chờ vào tiền trợ cấp cứu trợ của chính phủ, anh ấy thích tìm một công việc ổn định hơn.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_7_68","topic":"Education and Learning","word":"handwriting","pos":"(n)","ipa":"/ˈhændˌraɪ.t̬ɪŋ/","defVi":"chữ viết tay, nét chữ","defEn":"writing done by hand with a pen or pencil, or a person's particular style of writing","examples":["The teacher struggled to read his messy [handwriting] on the test paper. (=Dịch: Giáo viên đã phải rất vất vả mới đọc được chữ viết tay cẩu thả của anh ấy trong bài kiểm tra.)","Practicing calligraphy every day helped improve her English [handwriting]. (=Dịch: Luyện thư pháp mỗi ngày đã giúp cải thiện nét chữ viết tay tiếng Anh của cô ấy.)","The signature on the contract matched the suspect's [handwriting] perfectly. (=Dịch: Chữ ký trên hợp đồng hoàn toàn trùng khớp với nét chữ của kẻ tình nghi.)"],"ukAudio":"/ai_services/tts3/?q=handwriting&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd%CB%8Cra%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=handwriting&lang=en-US&ipa=%2F%CB%88h%C3%A6nd%CB%8Cra%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_7_69","topic":"Education and Learning","word":"having","pos":"(v)","ipa":"/ˈhæ.vɪŋ/","defVi":"đang có, sở hữu, trải qua","defEn":"present participle of 'have', meaning possessing, experiencing, or holding something","examples":["They are [having] a great time on their holiday in Italy. (=Dịch: Họ đang có một khoảng thời gian tuyệt vời trong kỳ nghỉ tại Ý.)","She apologized for not [having] enough time to finish the report. (=Dịch: Cô ấy xin lỗi vì không có đủ thời gian để hoàn thành bản báo cáo.)","After [having] breakfast, he went straight to the library. (=Dịch: Sau khi ăn sáng xong, anh ấy đi thẳng đến thư viện.)"],"ukAudio":"/ai_services/tts3/?q=having&lang=en-GB&ipa=%2F%CB%88h%C3%A6.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=having&lang=en-US&ipa=%2F%CB%88h%C3%A6.v%C9%AA%C5%8B%2F"},{"id":"lv_7_70","topic":"Education and Learning","word":"heading","pos":"(n)","ipa":"/ˈhed.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a line of text serving to indicate what the passage below is about; a title","examples":["Please write your full name under the main [heading] on the first page. (=Dịch: Vui lòng viết họ tên đầy đủ của bạn dưới phần tiêu đề chính ở trang đầu tiên.)","You can organize your essay clearly by using a sub [heading] for each section. (=Dịch: Bạn có thể sắp xếp bài luận mạch lạc bằng cách sử dụng tiêu đề phụ cho mỗi phần.)","The article was published under the [heading] of climate solutions. (=Dịch: Bài báo được xuất bản dưới tiêu đề về các giải pháp khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F"},{"id":"lv_7_71","topic":"Education and Learning","word":"helmet","pos":"(n)","ipa":"/ˈhɛl.mət/","defVi":"mũ bảo hiểm","defEn":"a hard or padded protective hat worn to protect the head","examples":["Cyclists should always wear a [helmet] to protect their heads. (=Dịch: Người đi xe đạp nên luôn đội mũ bảo hiểm để bảo vệ đầu.)","Construction workers are required to put on a hard [helmet] on site. (=Dịch: Công nhân xây dựng bắt buộc phải đội mũ bảo hiểm cứng tại công trường.)","He fastened the strap of his [helmet] before starting the motorbike. (=Dịch: Anh ấy cài quai mũ bảo hiểm trước khi nổ máy xe máy.)"],"ukAudio":"/ai_services/tts3/?q=helmet&lang=en-GB&ipa=%2F%CB%88h%C9%9Bl.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=helmet&lang=en-US&ipa=%2F%CB%88h%C9%9Bl.m%C9%99t%2F"},{"id":"lv_7_72","topic":"Education and Learning","word":"imagination","pos":"(n)","ipa":"/ɪˌmædʒ.əˈneɪ.ʃən/","defVi":"Trí tưởng tượng, khả năng sáng tạo","defEn":"The ability of the mind to form new ideas, images, or concepts","examples":["Creative writing exercises help stimulate children's [imagination]. (=Dịch: Các bài tập viết sáng tạo giúp kích thích trí tưởng tượng của trẻ em.)","It takes a lot of [imagination] to design innovative architectural structures. (=Dịch: Cần rất nhiều trí tưởng tượng để thiết kế ra những công trình kiến trúc đổi mới sáng tạo.)","The strange sounds outside were merely a product of his vivid [imagination]. (=Dịch: Những âm thanh lạ bên ngoài chỉ đơn thuần là sản phẩm từ trí tưởng tượng phong phú của anh ấy.)"],"ukAudio":"/ai_services/tts3/?q=imagination&lang=en-GB&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=imagination&lang=en-US&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_73","topic":"Education and Learning","word":"impression","pos":"(n)","ipa":"/ɪmˈprɛʃ.ən/","defVi":"ấn tượng","defEn":"an idea, feeling, or opinion about someone or something formed without conscious thought","examples":["Wearing formal clothes helps you make a positive first [impression] at an interview. (=Dịch: Mặc trang phục lịch sự giúp bạn tạo ấn tượng đầu tiên tốt đẹp tại buổi phỏng vấn.)","His speech left a lasting [impression] on everyone in the audience. (=Dịch: Bài phát biểu của anh ấy đã để lại ấn tượng sâu đậm trong lòng tất cả khán giả.)","I got the [impression] that he was not very interested in the project. (=Dịch: Tôi có cảm giác rằng anh ấy không mấy hào hứng với dự án này.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_7_74","topic":"Education and Learning","word":"incentive","pos":"(n)","ipa":"/ɪnˈsen.t̬ɪv/","defVi":"sự khích lệ, động lực, phần thưởng khuyến khích","defEn":"something that encourages a person to do something or to work harder","examples":["The company offers a financial [incentive] to employees who reach their sales targets. (=Dịch: Công ty đưa ra khoản thưởng khuyến khích tài chính cho những nhân viên đạt chỉ tiêu bán hàng.)","Tax cuts can provide an [incentive] for businesses to invest in green technology. (=Dịch: Việc giảm thuế có thể tạo động lực cho các doanh nghiệp đầu tư vào công nghệ xanh.)","There is little [incentive] for graduates to stay in rural areas without good jobs. (=Dịch: Có rất ít động lực để sinh viên mới tốt nghiệp ở lại vùng nông thôn nếu không có việc làm tốt.)"],"ukAudio":"/ai_services/tts3/?q=incentive&lang=en-GB&ipa=%2F%C9%AAn%CB%88sen.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=incentive&lang=en-US&ipa=%2F%C9%AAn%CB%88sen.t%CC%AC%C9%AAv%2F"},{"id":"lv_7_75","topic":"Education and Learning","word":"index","pos":"(n)","ipa":"/ˈɪn.deks/","defVi":"mục lục, chỉ số","defEn":"an alphabetical list of names or subjects with references to the places where they occur","examples":["Look up the term in the [index] at the back of the textbook. (=Dịch: Hãy tra cứu thuật ngữ này trong phần mục lục ở cuối sách giáo khoa.)","The consumer price [index] rose sharply over the past quarter. (=Dịch: Chỉ số giá tiêu dùng đã tăng mạnh trong quý vừa qua.)","This card [index] contains records of all library books. (=Dịch: Hộp phiếu mục lục này chứa thông tin lưu trữ của tất cả sách trong thư viện.)"],"ukAudio":"/ai_services/tts3/?q=index&lang=en-GB&ipa=%2F%CB%88%C9%AAn.deks%2F","usAudio":"/ai_services/tts3/?q=index&lang=en-US&ipa=%2F%CB%88%C9%AAn.deks%2F"},{"id":"lv_7_76","topic":"Education and Learning","word":"individually","pos":"(adv)","ipa":"/ˌɪn.dəˈvɪ.dʒu.ə.li/","defVi":"riêng lẻ, từng người một","defEn":"separately, one by one, rather than together","examples":["The teacher spoke to the students [individually] about their progress. (=Dịch: Giáo viên đã nói chuyện riêng với từng học sinh về sự tiến bộ của họ.)","Each gift was wrapped [individually] in colorful paper. (=Dịch: Mỗi món quà đều được gói riêng trong giấy nhiều màu sắc.)","The team members performed well [individually], but struggled to collaborate. (=Dịch: Các thành viên trong nhóm thể hiện tốt khi làm việc độc lập, nhưng lại gặp khó khăn khi phối hợp cùng nhau.)"],"ukAudio":"/ai_services/tts3/?q=individually&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.d%C9%99%CB%88v%C9%AA.d%CA%92u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=individually&lang=en-US&ipa=%2F%CB%8C%C9%AAn.d%C9%99%CB%88v%C9%AA.d%CA%92u.%C9%99.li%2F"},{"id":"lv_7_77","topic":"Education and Learning","word":"initial","pos":"(adj)","ipa":"/ɪˈnɪʃ.əl/","defVi":"ban đầu, đầu tiên","defEn":"happening at the beginning; first","examples":["My [initial] reaction to the proposal was quite skeptical. (=Dịch: Phản ứng ban đầu của tôi đối với đề xuất là khá hoài nghi.)","The company struggled during the [initial] phase of the project. (=Dịch: Công ty đã gặp nhiều khó khăn trong giai đoạn đầu của dự án.)","They managed to recover their [initial] investment within six months. (=Dịch: Họ đã xoay xở để thu hồi vốn đầu tư ban đầu trong vòng sáu tháng.)"],"ukAudio":"/ai_services/tts3/?q=initial&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=initial&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_7_78","topic":"Education and Learning","word":"initially","pos":"(adv)","ipa":"/ɪˈnɪʃ.ə.li/","defVi":"ban đầu, thoạt đầu","defEn":"at the beginning or at first","examples":["[Initially], the project seemed simple, but it soon became complicated. (=Dịch: Ban đầu, dự án có vẻ đơn giản, nhưng nó sớm trở nên phức tạp.)","He was [initially] reluctant to move to another city for work. (=Dịch: Thoạt đầu, anh ấy ngần ngại chuyển sang thành phố khác để làm việc.)","The company was [initially] founded as a small family business. (=Dịch: Công ty ban đầu được thành lập như một doanh nghiệp gia đình nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=initially&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=initially&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.li%2F"},{"id":"lv_7_79","topic":"Education and Learning","word":"install","pos":"(v)","ipa":"/ɪnˈstɑːl/","defVi":"cài đặt, lắp đặt","defEn":"to put a piece of equipment or software in place so that it is ready to use","examples":["The technician arrived early to [install] the new air conditioning unit. (=Dịch: Kỹ thuật viên đã đến sớm để lắp đặt máy điều hòa mới.)","You need to [install] the latest security update on your laptop. (=Dịch: Bạn cần cài đặt bản cập nhật bảo mật mới nhất trên máy tính xách tay của mình.)","The school decided to [install] solar panels to reduce electricity costs. (=Dịch: Nhà trường đã quyết định lắp đặt các tấm pin năng lượng mặt trời để giảm chi phí điện.)"],"ukAudio":"/ai_services/tts3/?q=install&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=install&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_7_80","topic":"Education and Learning","word":"intensive","pos":"(adj)","ipa":"/ɪnˈten.sɪv/","defVi":"chuyên sâu, cấp tốc","defEn":"involving a lot of effort, energy, or attention in a short time","examples":["She enrolled in an [intensive] language course before moving abroad. (=Dịch: Cô ấy đã đăng ký một khóa học ngôn ngữ cấp tốc trước khi ra nước ngoài.)","The patient required several weeks of [intensive] care. (=Dịch: Bệnh nhân cần được chăm sóc đặc biệt chuyên sâu trong vài tuần.)","Modern agriculture often relies on [intensive] farming methods. (=Dịch: Nông nghiệp hiện đại thường dựa vào các phương pháp canh tác thâm canh.)"],"ukAudio":"/ai_services/tts3/?q=intensive&lang=en-GB&ipa=%2F%C9%AAn%CB%88ten.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=intensive&lang=en-US&ipa=%2F%C9%AAn%CB%88ten.s%C9%AAv%2F"},{"id":"lv_7_81","topic":"Education and Learning","word":"interfere","pos":"(v)","ipa":"/ˌɪn.t̬ɚˈfɪr/","defVi":"Can thiệp, can dự, cản trở.","defEn":"To involve oneself in a matter without right or invitation; to hinder or obstruct.","examples":["Parents should not unduly [interfere] in their adult children's life choices. (=Dịch: Cha mẹ không nên can thiệp quá mức vào những lựa chọn cuộc sống của con cái khi đã trưởng thành.)","Poor weather conditions could [interfere] with the satellite signal. (=Dịch: Điều kiện thời tiết xấu có thể gây cản trở tín hiệu vệ tinh.)","Please do not [interfere] while the technicians are working on the system. (=Dịch: Xin đừng can thiệp trong khi các kỹ thuật viên đang xử lý hệ thống.)"],"ukAudio":"/ai_services/tts3/?q=interfere&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=interfere&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F"},{"id":"lv_7_82","topic":"Education and Learning","word":"interruption","pos":"(n)","ipa":"/ˌɪn.təˈrʌp.ʃən/","defVi":"sự gián đoạn, sự ngắt lời","defEn":"an act of stopping something from continuing or someone from speaking","examples":["He worked for three hours without a single [interruption]. (=Dịch: Anh ấy đã làm việc suốt ba tiếng đồng hồ mà không hề bị gián đoạn lần nào.)","Please allow me to finish my presentation without any [interruption]. (=Dịch: Xin hãy để tôi hoàn thành bài thuyết trình mà không ngắt lời.)","The storm caused a temporary [interruption] in the power supply. (=Dịch: Cơn bão đã gây ra sự gián đoạn tạm thời nguồn cung cấp điện.)"],"ukAudio":"/ai_services/tts3/?q=interruption&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88r%CA%8Cp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interruption&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88r%CA%8Cp.%CA%83%C9%99n%2F"},{"id":"lv_7_83","topic":"Education and Learning","word":"jar","pos":"(n)","ipa":"/dʒɑːr/","defVi":"lọ, hũ, bình","defEn":"a cylindrical glass or pottery container with a wide mouth","examples":["She stored homemade strawberry jam in a glass [jar]. (=Dịch: Cô ấy đựng mứt dâu tự làm trong một chiếc lọ thủy tinh.)","He couldn't open the tight lid of the pickle [jar]. (=Dịch: Anh ấy không thể mở được chiếc nắp quá chặt của hũ dưa muối.)","There is a [jar] of freshly picked flowers on the dining table. (=Dịch: Có một bình hoa mới hái trên bàn ăn.)"],"ukAudio":"/ai_services/tts3/?q=jar&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=jar&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90r%2F"},{"id":"lv_7_84","topic":"Education and Learning","word":"jet","pos":"(n)","ipa":"/dʒet/","defVi":"máy bay phản lực; tia nước/khí","defEn":"an aircraft powered by jet engines that travels at high speeds","examples":["The business executive travels across the country in a private [jet]. (=Dịch: Vị giám đốc điều hành đi khắp đất nước bằng một chiếc máy bay phản lực riêng.)","A powerful [jet] of water was used to clean the muddy sidewalk. (=Dịch: Một tia nước cực mạnh đã được sử dụng để rửa sạch vỉa hè đầy bùn đất.)","We watched the military [jet] fly across the sky at incredible speed. (=Dịch: Chúng tôi ngắm nhìn chiếc máy bay phản lực quân sự bay qua bầu trời với tốc độ đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=jet&lang=en-GB&ipa=%2Fd%CA%92et%2F","usAudio":"/ai_services/tts3/?q=jet&lang=en-US&ipa=%2Fd%CA%92et%2F"},{"id":"lv_7_85","topic":"Education and Learning","word":"journal","pos":"(n)","ipa":"/ˈdʒɝː.nəl/","defVi":"tạp chí chuyên ngành; nhật ký","defEn":"a serious magazine or publication that deals with a particular subject or academic discipline","examples":["His research paper was published in a prestigious medical [journal]. (=Dịch: Bài báo nghiên cứu của anh ấy đã được xuất bản trên một tạp chí y khoa danh tiếng.)","Students are encouraged to read an academic [journal] every week. (=Dịch: Sinh viên được khuyến khích đọc một tạp chí học thuật mỗi tuần.)","She kept a personal [journal] during her travels across Asia. (=Dịch: Cô ấy đã viết nhật ký cá nhân trong suốt chuyến du lịch khắp châu Á.)"],"ukAudio":"/ai_services/tts3/?q=journal&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=journal&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_7_86","topic":"Education and Learning","word":"keyboard","pos":"(n)","ipa":"/ˈkiˌbɔrd/","defVi":"bàn phím (máy tính hoặc nhạc cụ)","defEn":"a set of keys on a computer or musical instrument used for typing or playing music","examples":["He spilled his morning coffee all over the computer [keyboard]. (=Dịch: Anh ấy làm đổ cà phê sáng lên khắp bàn phím máy tính.)","Learning to play the electronic [keyboard] requires regular practice. (=Dịch: Học chơi đàn phím điện tử đòi hỏi phải luyện tập thường xuyên.)","She cleaned the dust between the keys of her mechanical [keyboard]. (=Dịch: Cô ấy lau sạch bụi bẩn bám giữa các phím trên chiếc bàn phím cơ của mình.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki%CB%8Cb%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki%CB%8Cb%C9%94rd%2F"},{"id":"lv_7_87","topic":"Education and Learning","word":"lecturer","pos":"(n)","ipa":"/ˈlek.tʃər.ər/","defVi":"giảng viên đại học","defEn":"a person who teaches at a college or university","examples":["The [lecturer] explained the complex theory with great clarity. (=Dịch: Giảng viên đã giải thích lý thuyết phức tạp một cách rất rõ ràng.)","Students can make an appointment to speak with their [lecturer]. (=Dịch: Sinh viên có thể đặt lịch hẹn để trao đổi với giảng viên của mình.)","He worked as a senior [lecturer] in history for over twenty years. (=Dịch: Ông ấy đã làm việc với tư cách là một giảng viên cao cấp môn lịch sử trong hơn hai mươi năm.)"],"ukAudio":"/ai_services/tts3/?q=lecturer&lang=en-GB&ipa=%2F%CB%88lek.t%CA%83%C9%99r.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=lecturer&lang=en-US&ipa=%2F%CB%88lek.t%CA%83%C9%99r.%C9%99r%2F"},{"id":"lv_7_88","topic":"Education and Learning","word":"licence","pos":"(n)","ipa":"/ˈlaɪ.səns/","defVi":"giấy phép, bằng lái","defEn":"an official document that gives legal permission to do, own, or use something","examples":["You must hold a valid driver's [licence] to rent a car here. (=Dịch: Bạn phải có bằng lái xe hợp lệ mới được thuê xe ô tô ở đây.)","The restaurant lost its [licence] after failing the health inspection. (=Dịch: Nhà hàng đã bị tước giấy phép sau khi không vượt qua đợt kiểm tra vệ sinh.)","The company obtained a [licence] to import foreign medical equipment. (=Dịch: Công ty đã xin được giấy phép nhập khẩu thiết bị y tế nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=licence&lang=en-GB&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=licence&lang=en-US&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F"},{"id":"lv_7_89","topic":"Education and Learning","word":"literacy","pos":"(n)","ipa":"/ˈlɪt.ər.ə.si/","defVi":"khả năng biết chữ, trình độ đọc viết","defEn":"the ability to read and write","examples":["The government launched a nationwide campaign to promote adult [literacy]. (=Dịch: Chính phủ đã phát động một chiến dịch toàn quốc nhằm nâng cao tỷ lệ biết chữ ở người lớn.)","Digital [literacy] is becoming an essential skill in modern workplaces. (=Dịch: Kỹ năng sử dụng công nghệ số đang trở thành một kỹ năng thiết yếu tại các nơi làm việc hiện đại.)","Improving financial [literacy] helps young adults manage their money better. (=Dịch: Cải thiện hiểu biết về tài chính giúp những người trẻ quản lý tiền bạc tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=literacy&lang=en-GB&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99.si%2F","usAudio":"/ai_services/tts3/?q=literacy&lang=en-US&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99.si%2F"},{"id":"lv_7_90","topic":"Education and Learning","word":"literate","pos":"(adj)","ipa":"/ˈlɪt.ər.ət/","defVi":"Biết đọc biết viết; có học vấn.","defEn":"Able to read and write.","examples":["The government launched a program to ensure that all citizens become [literate]. (=Dịch: Chính phủ đã phát động một chương trình nhằm đảm bảo tất cả công dân đều biết chữ.)","In today's digital age, it is essential to be computer [literate]. (=Dịch: Trong thời đại số ngày nay, việc có kiến thức tin học cơ bản là vô cùng cần thiết.)","Only a small percentage of the rural population was [literate] a century ago. (=Dịch: Một thế kỷ trước, chỉ có một tỷ lệ nhỏ người dân nông thôn biết đọc biết viết.)"],"ukAudio":"/ai_services/tts3/?q=literate&lang=en-GB&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=literate&lang=en-US&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99t%2F"},{"id":"lv_7_91","topic":"Education and Learning","word":"literature","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.tʃɚ/","defVi":"văn học, tài liệu chuyên ngành","defEn":"written artistic works such as novels, plays, and poetry, or written material on a specific subject","examples":["She has a deep passion for modern English [literature]. (=Dịch: Cô ấy có một niềm đam mê sâu sắc với văn học Anh hiện đại.)","Students are required to review the existing scientific [literature] before starting the project. (=Dịch: Sinh viên được yêu cầu xem lại các tài liệu khoa học hiện có trước khi bắt đầu dự án.)","Classical [literature] plays an important role in understanding historical cultures. (=Dịch: Văn học cổ điển đóng vai trò quan trọng trong việc thấu hiểu các nền văn hóa lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=literature&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=literature&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F"},{"id":"lv_7_92","topic":"Education and Learning","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"vật nuôi, gia súc","defEn":"animals kept on a farm, such as cows, sheep, and pigs","examples":["The farmer raises [livestock] to produce organic milk and meat. (=Dịch: Người nông dân nuôi gia súc để sản xuất sữa và thịt hữu cơ.)","Severe droughts pose a great threat to local [livestock]. (=Dịch: Hạn hán nghiêm trọng gây ra mối đe dọa lớn đối với đàn gia súc địa phương.)","They built strong fences to protect their [livestock] from wild predators. (=Dịch: Họ dựng hàng rào kiên cố để bảo vệ đàn vật nuôi khỏi thú ăn thịt hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_7_93","topic":"Education and Learning","word":"loan","pos":"(n)","ipa":"/loʊn/","defVi":"khoản vay, tiền vay","defEn":"a sum of money that is borrowed and is expected to be paid back with interest","examples":["They took out a bank [loan] to buy their first apartment. (=Dịch: Họ đã vay một khoản ngân hàng để mua căn hộ đầu tiên.)","The interest rate on his student [loan] increased significantly this year. (=Dịch: Lãi suất cho khoản vay sinh viên của anh ấy đã tăng đáng kể trong năm nay.)","The small business struggled to secure a government [loan] during the crisis. (=Dịch: Doanh nghiệp nhỏ đã phải chật vật để có được một khoản vay của chính phủ trong thời kỳ khủng hoảng.)"],"ukAudio":"/ai_services/tts3/?q=loan&lang=en-GB&ipa=%2Flo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=loan&lang=en-US&ipa=%2Flo%CA%8An%2F"},{"id":"lv_7_94","topic":"Education and Learning","word":"manual","pos":"(adj)","ipa":"/ˈmæn.ju.əl/","defVi":"bằng tay, thủ công","defEn":"done with the hands or requiring physical effort rather than automatic machines","examples":["Many farmers in the region still rely on [manual] labor to harvest crops. (=Dịch: Nhiều nông dân trong vùng vẫn dựa vào lao động chân tay để thu hoạch mùa màng.)","The car has a [manual] gearbox instead of an automatic transmission. (=Dịch: Chiếc xe này có hộp số sàn (thủ công) thay vì hộp số tự động.)","Data entry used to be a [manual] process before software was introduced. (=Dịch: Việc nhập dữ liệu từng là quy trình thủ công trước khi phần mềm được đưa vào sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=manual&lang=en-GB&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=manual&lang=en-US&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F"},{"id":"lv_7_95","topic":"Education and Learning","word":"marching","pos":"(n)","ipa":"/ˈmɑr.tʃɪŋ/","defVi":"sự diễu hành, việc hành quân","defEn":"the act of walking with regular, steady, and rhythmic steps like soldiers","examples":["The sound of soldiers [marching] could be heard from far away. (=Dịch: Tiếng bước chân hành quân của những người lính có thể nghe thấy từ đằng xa.)","The school band spent weeks practicing their [marching] formation for the parade. (=Dịch: Ban nhạc của trường đã dành nhiều tuần để luyện tập đội hình diễu hành cho buổi lễ.)","Crowds cheered as the performers began [marching] down the main street. (=Dịch: Đám đông reo hò khi các nghệ sĩ biểu diễn bắt đầu diễu hành xuống con phố chính.)"],"ukAudio":"/ai_services/tts3/?q=marching&lang=en-GB&ipa=%2F%CB%88m%C9%91r.t%CA%83%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=marching&lang=en-US&ipa=%2F%CB%88m%C9%91r.t%CA%83%C9%AA%C5%8B%2F"},{"id":"lv_7_96","topic":"Education and Learning","word":"math","pos":"(n)","ipa":"/mæθ/","defVi":"môn toán, toán học","defEn":"the study of numbers, shapes, and patterns; short for mathematics","examples":["She has always excelled in [math] and science subjects. (=Dịch: Cô ấy luôn xuất sắc ở các môn toán và khoa học.)","I need to study hard for my upcoming [math] exam. (=Dịch: Tôi cần phải học tập chăm chỉ cho kỳ thi toán sắp tới.)","Solving complex [math] puzzles helps improve critical thinking skills. (=Dịch: Giải các câu đố toán học phức tạp giúp cải thiện kỹ năng tư duy phản biện.)"],"ukAudio":"/ai_services/tts3/?q=math&lang=en-GB&ipa=%2Fm%C3%A6%CE%B8%2F","usAudio":"/ai_services/tts3/?q=math&lang=en-US&ipa=%2Fm%C3%A6%CE%B8%2F"},{"id":"lv_7_97","topic":"Education and Learning","word":"mature","pos":"(adj)","ipa":"/məˈtʃʊr/","defVi":"trưởng thành, chín chắn","defEn":"behaving in a sensible and responsible way like an adult, or fully grown","examples":["She is very [mature] for her age and handles problems calmly. (=Dịch: Cô ấy rất chín chắn so với lứa tuổi của mình và xử lý các vấn đề một cách bình tĩnh.)","It takes several years for these trees to become fully [mature]. (=Dịch: Phải mất vài năm để những cái cây này phát triển hoàn toàn.)","We need a [mature] discussion about the future of our company. (=Dịch: Chúng ta cần một cuộc thảo luận nghiêm túc và thấu đáo về tương lai của công ty.)"],"ukAudio":"/ai_services/tts3/?q=mature&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=mature&lang=en-US&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F"},{"id":"lv_7_98","topic":"Education and Learning","word":"mechanical","pos":"(adj)","ipa":"/məˈkæn.ɪ.kəl/","defVi":"thuộc về cơ khí, máy móc","defEn":"relating to machines or engines, or operated by a machine","examples":["The flight was delayed due to a minor [mechanical] problem. (=Dịch: Chuyến bay đã bị hoãn do một sự cố cơ khí nhỏ.)","He decided to study [mechanical] engineering at university. (=Dịch: Anh ấy quyết định theo học ngành kỹ thuật cơ khí tại trường đại học.)","An antique clock relies on a purely [mechanical] system to keep time. (=Dịch: Một chiếc đồng hồ cổ dựa hoàn toàn vào hệ thống cơ học để chạy đúng giờ.)"],"ukAudio":"/ai_services/tts3/?q=mechanical&lang=en-GB&ipa=%2Fm%C9%99%CB%88k%C3%A6n.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=mechanical&lang=en-US&ipa=%2Fm%C9%99%CB%88k%C3%A6n.%C9%AA.k%C9%99l%2F"},{"id":"lv_7_99","topic":"Education and Learning","word":"medication","pos":"(n)","ipa":"/ˌmɛd.əˈkeɪ.ʃən/","defVi":"thuốc điều trị, dược phẩm","defEn":"a drug or other form of medicine that you take to treat an illness","examples":["The doctor prescribed some [medication] to relieve her back pain. (=Dịch: Bác sĩ đã kê một số loại thuốc để giảm đau lưng cho cô ấy.)","You should avoid driving while taking this allergy [medication]. (=Dịch: Bạn nên tránh lái xe khi đang dùng loại thuốc dị ứng này.)","He has been on regular [medication] for high blood pressure for five years. (=Dịch: Ông ấy đã uống thuốc điều trị huyết áp cao đều đặn trong suốt năm năm qua.)"],"ukAudio":"/ai_services/tts3/?q=medication&lang=en-GB&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=medication&lang=en-US&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_100","topic":"Education and Learning","word":"modular","pos":"(adj)","ipa":"/ˈmɑː.dʒə.lər/","defVi":"dạng mô-đun, lắp ghép","defEn":"made up of separate parts or units that can be combined in different ways","examples":["The company produces modern [modular] furniture that is easy to assemble. (=Dịch: Công ty sản xuất đồ nội thất dạng mô-đun hiện đại rất dễ lắp ráp.)","The degree program offers a flexible [modular] structure for students. (=Dịch: Chương trình cấp bằng cung cấp cấu trúc học phần linh hoạt cho sinh viên.)","They constructed a [modular] home in just a few weeks. (=Dịch: Họ đã xây dựng một ngôi nhà lắp ghép chỉ trong vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=modular&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.d%CA%92%C9%99.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=modular&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.d%CA%92%C9%99.l%C9%99r%2F"},{"id":"lv_7_101","topic":"Education and Learning","word":"motor","pos":"(n)","ipa":"/ˈmoʊ.tər/","defVi":"động cơ, mô-tơ","defEn":"a device that converts electrical energy or fuel into mechanical motion","examples":["The electric [motor] in the fan needs to be replaced. (=Dịch: Mô-tơ điện trong chiếc quạt cần phải được thay thế.)","He repaired the boat's [motor] before heading out to sea. (=Dịch: Anh ấy đã sửa động cơ của chiếc thuyền trước khi ra khơi.)","Electric cars use a powerful battery to drive the [motor]. (=Dịch: Xe ô tô điện sử dụng một bộ pin mạnh mẽ để vận hành động cơ.)"],"ukAudio":"/ai_services/tts3/?q=motor&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=motor&lang=en-US&ipa=%2F%CB%88mo%CA%8A.t%C9%99r%2F"},{"id":"lv_7_102","topic":"Education and Learning","word":"nanotechnology","pos":"(n)","ipa":"/ˌnæn.oʊ.tekˈnɑː.lə.dʒi/","defVi":"Công nghệ nano.","defEn":"The science and engineering of manipulating materials at the atomic or molecular scale.","examples":["Recent breakthroughs in [nanotechnology] have improved medical diagnostic tools. (=Dịch: Những đột phá gần đây trong công nghệ nano đã cải thiện các công cụ chẩn đoán y tế.)","Scientists believe that [nanotechnology] could revolutionize clean energy production. (=Dịch: Các nhà khoa học tin rằng công nghệ nano có thể cách mạng hóa quá trình sản xuất năng lượng sạch.)","The university offers a specialized master's degree in [nanotechnology]. (=Dịch: Trường đại học cung cấp chương trình thạc sĩ chuyên ngành về công nghệ nano.)"],"ukAudio":"/ai_services/tts3/?q=nanotechnology&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6n.o%CA%8A.tek%CB%88n%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=nanotechnology&lang=en-US&ipa=%2F%CB%8Cn%C3%A6n.o%CA%8A.tek%CB%88n%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_103","topic":"Education and Learning","word":"oral","pos":"(adj)","ipa":"/ˈɔːr.əl/","defVi":"bằng lời nói, bằng miệng, thuộc về răng miệng","defEn":"spoken rather than written, or relating to the mouth","examples":["Students must pass an [oral] examination in French before graduating. (=Dịch: Học sinh phải vượt qua một kỳ thi vấn đáp tiếng Pháp trước khi tốt nghiệp.)","Good [oral] hygiene helps prevent tooth decay and gum disease. (=Dịch: Vệ sinh răng miệng tốt giúp ngăn ngừa sâu răng và bệnh về nướu.)","Ancient stories were passed down through generations by [oral] tradition. (=Dịch: Những câu chuyện cổ xưa đã được truyền qua nhiều thế hệ bằng truyền thống truyền miệng.)"],"ukAudio":"/ai_services/tts3/?q=oral&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=oral&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F"},{"id":"lv_7_104","topic":"Education and Learning","word":"origami","pos":"(n)","ipa":"/ˌɔːr.əˈɡɑː.mi/","defVi":"Nghệ thuật gấp giấy Origami.","defEn":"The traditional Japanese art of paper folding.","examples":["Children can develop patience and dexterity by practicing [origami]. (=Dịch: Trẻ em có thể rèn luyện tính kiên nhẫn và sự khéo léo bằng cách thực hành gấp giấy origami.)","She created a beautiful crane out of square paper using [origami] techniques. (=Dịch: Cô ấy đã gấp một con hạc tuyệt đẹp từ tờ giấy vuông bằng các kỹ thuật origami.)","The art museum is hosting an exhibition dedicated to contemporary [origami]. (=Dịch: Bảo tàng nghệ thuật đang tổ chức một buổi triển lãm dành riêng cho nghệ thuật origami đương đại.)"],"ukAudio":"/ai_services/tts3/?q=origami&lang=en-GB&ipa=%2F%CB%8C%C9%94%CB%90r.%C9%99%CB%88%C9%A1%C9%91%CB%90.mi%2F","usAudio":"/ai_services/tts3/?q=origami&lang=en-US&ipa=%2F%CB%8C%C9%94%CB%90r.%C9%99%CB%88%C9%A1%C9%91%CB%90.mi%2F"},{"id":"lv_7_105","topic":"Education and Learning","word":"overhead","pos":"(adj)","ipa":"/ˈoʊ.vɚ.hɛd/","defVi":"ở trên đầu, trên cao","defEn":"located or operating above your head, in the sky or ceiling","examples":["Please place your carry-on luggage in the [overhead] compartment. (=Dịch: Vui lòng để hành lý xách tay của bạn vào khoang hành lý phía trên đầu.)","Strong winds damaged several [overhead] power cables last night. (=Dịch: Gió mạnh đã làm hư hại một số đường dây điện trên cao vào đêm qua.)","The room was brightly lit by large [overhead] lights. (=Dịch: Căn phòng được chiếu sáng rực rỡ bởi những chiếc đèn trần lớn trên cao.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%88o%CA%8A.v%C9%9A.h%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%88o%CA%8A.v%C9%9A.h%C9%9Bd%2F"},{"id":"lv_7_106","topic":"Education and Learning","word":"oxford","pos":"(n)","ipa":"/ˈɑːks.fɚd/","defVi":"thành phố Oxford (Anh) hoặc kiểu giày da buộc dây Oxford","defEn":"a famous university city in England, or a type of classic laced leather shoe","examples":["She was accepted into the University of [oxford] to study history. (=Dịch: Cô ấy đã được nhận vào Đại học Oxford để theo học ngành lịch sử.)","He wore a pair of polished black [oxford] shoes to the interview. (=Dịch: Anh ấy đã đi một đôi giày da buộc dây Oxford màu đen sáng bóng đến buổi phỏng vấn.)","Many tourists visit [oxford] to admire its historic architecture. (=Dịch: Nhiều khách du lịch đến thăm Oxford để chiêm ngưỡng kiến trúc lịch sử của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=oxford&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=oxford&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%9Ad%2F"},{"id":"lv_7_107","topic":"Education and Learning","word":"paperclip","pos":"(n)","ipa":"/ˈpeɪ.pɚ.klɪp/","defVi":"cái kẹp giấy","defEn":"a small piece of bent wire or plastic used for holding sheets of paper together","examples":["Use a [paperclip] to keep these documents neatly organized. (=Dịch: Hãy sử dụng một cái kẹp giấy để giữ cho những tài liệu này được sắp xếp gọn gàng.)","I searched my desk drawer for a [paperclip] but could not find one. (=Dịch: Tôi đã tìm trong ngăn kéo bàn một chiếc kẹp giấy nhưng không thấy cái nào.)","She attached the receipt to the invoice with a metal [paperclip]. (=Dịch: Cô ấy đã đính kèm biên lai vào hóa đơn bằng một chiếc kẹp giấy kim loại.)"],"ukAudio":"/ai_services/tts3/?q=paperclip&lang=en-GB&ipa=%2F%CB%88pe%C9%AA.p%C9%9A.kl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=paperclip&lang=en-US&ipa=%2F%CB%88pe%C9%AA.p%C9%9A.kl%C9%AAp%2F"},{"id":"lv_7_108","topic":"Education and Learning","word":"parade","pos":"(n)","ipa":"/pəˈreɪd/","defVi":"cuộc diễu hành, duyệt binh","defEn":"a public procession, especially one celebrating a special day or event","examples":["Thousands of people lined the streets to watch the annual holiday [parade]. (=Dịch: Hàng ngàn người đã đứng dọc các con phố để xem cuộc diễu hành ngày lễ thường niên.)","The marching band practiced every day before the big [parade]. (=Dịch: Đoàn nhạc diễu hành đã tập luyện mỗi ngày trước buổi diễu hành lớn.)","Local military units took part in the victory [parade]. (=Dịch: Các đơn vị quân đội địa phương đã tham gia vào cuộc diễu binh chiến thắng.)"],"ukAudio":"/ai_services/tts3/?q=parade&lang=en-GB&ipa=%2Fp%C9%99%CB%88re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=parade&lang=en-US&ipa=%2Fp%C9%99%CB%88re%C9%AAd%2F"},{"id":"lv_7_109","topic":"Education and Learning","word":"pause","pos":"(n)","ipa":"/ˈpɔz/","defVi":"sự tạm dừng, khoảng lặng","defEn":"a short period in which something stops before starting again","examples":["There was a brief [pause] in the conversation before she answered the question. (=Dịch: Có một khoảng lặng ngắn trong cuộc trò chuyện trước khi cô ấy trả lời câu hỏi.)","The speaker made a dramatic [pause] to let the message sink in. (=Dịch: Diễn giả đã có một khoảng ngắt giọng đầy kịch tính để thông điệp thực sự thấm thía.)","We took a quick [pause] during the hike to drink some water and rest. (=Dịch: Chúng tôi đã tạm dừng một lúc trong chuyến đi bộ đường dài để uống nước và nghỉ ngơi.)"],"ukAudio":"/ai_services/tts3/?q=pause&lang=en-GB&ipa=%2F%CB%88p%C9%94z%2F","usAudio":"/ai_services/tts3/?q=pause&lang=en-US&ipa=%2F%CB%88p%C9%94z%2F"},{"id":"lv_7_110","topic":"Education and Learning","word":"periodical","pos":"(n)","ipa":"/ˌpɪr.iˈɑ.dɪ.kəl/","defVi":"tạp chí xuất bản định kỳ, ấn phẩm định kỳ","defEn":"a magazine or newspaper published at regular intervals","examples":["The university library subscribes to various academic [periodical] publications. (=Dịch: Thư viện trường đại học đặt mua nhiều ấn phẩm tạp chí học thuật định kỳ khác nhau.)","Researchers often submit their scientific findings to a peer-reviewed [periodical]. (=Dịch: Các nhà nghiên cứu thường gửi các phát hiện khoa học của họ tới một tạp chí định kỳ có bình duyệt.)","She spent the afternoon browsing through an old medical [periodical]. (=Dịch: Cô ấy dành cả buổi chiều để lướt xem một tờ tạp chí y khoa định kỳ cũ.)"],"ukAudio":"/ai_services/tts3/?q=periodical&lang=en-GB&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91.d%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=periodical&lang=en-US&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91.d%C9%AA.k%C9%99l%2F"},{"id":"lv_7_111","topic":"Education and Learning","word":"photocopy","pos":"(v)","ipa":"/ˈfoʊ.t̬oʊˌkɑː.pi/","defVi":"Sao chụp, photocopy tài liệu.","defEn":"To make a photographic copy of a document or image.","examples":["Could you please [photocopy] these ten pages for the meeting? (=Dịch: Bạn có thể vui lòng sao chụp mười trang này cho cuộc họp được không?)","The assistant was asked to [photocopy] all the signed contracts. (=Dịch: Người trợ lý được yêu cầu photocopy tất cả các hợp đồng đã ký.)","Students are reminded not to [photocopy] copyrighted textbooks without permission. (=Dịch: Học sinh được nhắc nhở không được sao chụp giáo trình có bản quyền mà không có sự cho phép.)"],"ukAudio":"/ai_services/tts3/?q=photocopy&lang=en-GB&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi%2F","usAudio":"/ai_services/tts3/?q=photocopy&lang=en-US&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi%2F"},{"id":"lv_7_112","topic":"Education and Learning","word":"physically","pos":"(adv)","ipa":"/ˈfɪz.ɪ.kli/","defVi":"về mặt thể chất, theo cách hữu hình","defEn":"in a way that relates to the body rather than the mind","examples":["Athletes must stay [physically] fit through daily training. (=Dịch: Các vận động viên phải duy trì thể lực tốt thông qua việc rèn luyện hàng ngày.)","He felt [physically] exhausted after running the marathon. (=Dịch: Anh ấy cảm thấy kiệt sức về mặt thể xác sau khi chạy xong cự ly marathon.)","The two documents are [physically] stored in different filing cabinets. (=Dịch: Hai tài liệu này được lưu trữ vật lý trong các tủ hồ sơ khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=physically&lang=en-GB&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=physically&lang=en-US&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F"},{"id":"lv_7_113","topic":"Education and Learning","word":"pity","pos":"(n)","ipa":"/ˈpɪt.i/","defVi":"sự tiếc nuối, điều đáng tiếc; lòng thương hại","defEn":"a feeling of sorrow and compassion, or a cause for regret","examples":["It is a great [pity] that you cannot join us for dinner tonight. (=Dịch: Thật là một điều đáng tiếc khi bạn không thể tham gia bữa tối cùng chúng tôi tối nay.)","She looked at the stray dog with deep [pity] and offered it food. (=Dịch: Cô ấy nhìn chú chó hoang với lòng thương cảm sâu sắc và cho nó thức ăn.)","What a [pity] that the outdoor concert was canceled due to rain. (=Dịch: Thật tiếc làm sao khi buổi hòa nhạc ngoài trời bị hủy vì trời mưa.)"],"ukAudio":"/ai_services/tts3/?q=pity&lang=en-GB&ipa=%2F%CB%88p%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=pity&lang=en-US&ipa=%2F%CB%88p%C9%AAt.i%2F"},{"id":"lv_7_114","topic":"Education and Learning","word":"playwright","pos":"(n)","ipa":"/ˈpleɪ.raɪt/","defVi":"nhà soạn kịch, nhà viết kịch","defEn":"a person who writes plays for the stage or theater","examples":["William Shakespeare is widely regarded as the greatest English [playwright]. (=Dịch: William Shakespeare được coi rộng rãi là nhà soạn kịch vĩ đại nhất của nước Anh.)","The young [playwright] won an award for her debut theatrical production. (=Dịch: Nữ nhà biên kịch trẻ đã giành được giải thưởng cho tác phẩm sân khấu đầu tay của mình.)","The [playwright] spent months researching historical events for his new drama. (=Dịch: Nhà viết kịch đã dành nhiều tháng nghiên cứu các sự kiện lịch sử cho vở kịch mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=playwright&lang=en-GB&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=playwright&lang=en-US&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F"},{"id":"lv_7_115","topic":"Education and Learning","word":"politic","pos":"(adj)","ipa":"/ˈpɑ.lə.tɪk/","defVi":"khôn ngoan, thận trọng, sáng suốt","defEn":"sensible, wise, and showing good judgment in a particular situation","examples":["It seemed [politic] to keep quiet and avoid causing an argument. (=Dịch: Giữ im lặng và tránh gây ra tranh cãi có vẻ là điều khôn ngoan.)","She made a [politic] decision to consult her manager before proceeding. (=Dịch: Cô ấy đã đưa ra một quyết định sáng suốt khi tham khảo ý kiến của quản lý trước khi tiếp tục.)","Under such tense circumstances, a [politic] response is essential. (=Dịch: Trong hoàn cảnh căng thẳng như vậy, một phản ứng thận trọng là điều cần thiết.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91.l%C9%99.t%C9%AAk%2F"},{"id":"lv_7_116","topic":"Education and Learning","word":"postal","pos":"(adj)","ipa":"/ˈpoʊs.təl/","defVi":"thuộc về bưu điện, bưu chính","defEn":"connected with the post or the system for delivering mail","examples":["You need to enter your correct [postal] code when placing an online order. (=Dịch: Bạn cần nhập đúng mã bưu chính khi đặt hàng trực tuyến.)","The national [postal] service announced an increase in stamp prices. (=Dịch: Dịch vụ bưu chính quốc gia đã thông báo tăng giá tem.)","Citizens were encouraged to cast their votes using the [postal] system. (=Dịch: Người dân được khuyến khích bỏ phiếu thông qua hệ thống bưu điện.)"],"ukAudio":"/ai_services/tts3/?q=postal&lang=en-GB&ipa=%2F%CB%88po%CA%8As.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=postal&lang=en-US&ipa=%2F%CB%88po%CA%8As.t%C9%99l%2F"},{"id":"lv_7_117","topic":"Education and Learning","word":"postgraduate","pos":"(n)","ipa":"/ˌpoʊstˈɡrædʒ.u.ət/","defVi":"nghiên cứu sinh, học viên cao học","defEn":"a student who has completed a bachelor's degree and is studying for a higher qualification","examples":["Many [postgraduate] students work as teaching assistants at the university. (=Dịch: Nhiều học viên sau đại học làm trợ giảng tại trường đại học.)","The scholarship is exclusively available to full-time [postgraduate] researchers. (=Dịch: Học bổng này chỉ dành riêng cho các nhà nghiên cứu sau đại học toàn thời gian.)","As a [postgraduate], she spent most of her time conducting laboratory experiments. (=Dịch: Là một học viên cao học, cô ấy dành phần lớn thời gian để tiến hành các thí nghiệm trong phòng thí nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=postgraduate&lang=en-GB&ipa=%2F%CB%8Cpo%CA%8Ast%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=postgraduate&lang=en-US&ipa=%2F%CB%8Cpo%CA%8Ast%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F"},{"id":"lv_7_118","topic":"Education and Learning","word":"preparation","pos":"(n)","ipa":"/ˌprɛ.pəˈreɪ.ʃən/","defVi":"sự chuẩn bị","defEn":"the act or process of getting ready for something","examples":["Careful [preparation] is the key to passing the IELTS exam. (=Dịch: Sự chuẩn bị kỹ lưỡng là chìa khóa để vượt qua kỳ thi IELTS.)","The team spent months in [preparation] for the international tournament. (=Dịch: Cả đội đã dành nhiều tháng chuẩn bị cho giải đấu quốc tế.)","Food [preparation] should follow strict hygiene guidelines. (=Dịch: Việc chuẩn bị thức ăn nên tuân thủ các nguyên tắc vệ sinh nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=preparation&lang=en-GB&ipa=%2F%CB%8Cpr%C9%9B.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=preparation&lang=en-US&ipa=%2F%CB%8Cpr%C9%9B.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_119","topic":"Education and Learning","word":"prince","pos":"(n)","ipa":"/prɪns/","defVi":"hoàng tử","defEn":"a son or male relative of a king or queen","examples":["The young [prince] was educated at the best universities in the country. (=Dịch: Vị hoàng tử trẻ đã được học tập tại những trường đại học danh tiếng nhất cả nước.)","In the fairy tale, a charming [prince] saves the kingdom from danger. (=Dịch: Trong câu chuyện cổ tích, một hoàng tử hào hoa đã cứu vương quốc thoát khỏi hiểm nguy.)","The [prince] will represent the royal family at the upcoming international summit. (=Dịch: Hoàng tử sẽ đại diện cho hoàng gia tại hội nghị thượng đỉnh quốc tế sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=prince&lang=en-GB&ipa=%2Fpr%C9%AAns%2F","usAudio":"/ai_services/tts3/?q=prince&lang=en-US&ipa=%2Fpr%C9%AAns%2F"},{"id":"lv_7_120","topic":"Education and Learning","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a basic truth, rule, or belief that guides behavior and decision-making","examples":["He refused to accept the bribe because it went against his personal [principle]s. (=Dịch: Anh ấy từ chối nhận hối lộ vì điều đó đi ngược lại với các nguyên tắc cá nhân của mình.)","The machine operates on the [principle] of electromagnetic induction. (=Dịch: Cỗ máy này hoạt động dựa trên nguyên lý cảm ứng điện từ.)","Adhering to the [principle] of fairness is essential for any legal system. (=Dịch: Tuân thủ nguyên tắc công bằng là điều cốt yếu đối với bất kỳ hệ thống pháp luật nào.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_7_121","topic":"Education and Learning","word":"projector","pos":"(n)","ipa":"/prəˈdʒek.tər/","defVi":"máy chiếu","defEn":"a device that projects images, videos, or slides onto a screen or wall","examples":["The teacher turned on the [projector] to show the slides. (=Dịch: Giáo viên đã bật máy chiếu để trình chiếu các trang bài giảng.)","We bought a mini [projector] to watch movies in our bedroom. (=Dịch: Chúng tôi đã mua một chiếc máy chiếu mini để xem phim trong phòng ngủ.)","The meeting was delayed because the [projector] broke down. (=Dịch: Cuộc họp bị hoãn lại vì máy chiếu bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=projector&lang=en-GB&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=projector&lang=en-US&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F"},{"id":"lv_7_122","topic":"Education and Learning","word":"proud","pos":"(adj)","ipa":"/praʊd/","defVi":"tự hào, hãnh diện","defEn":"feeling deep pleasure or satisfaction as a result of one's own achievements or qualities, or those of someone with whom one is associated","examples":["Her parents were extremely [proud] when she graduated with honors. (=Dịch: Bố mẹ cô ấy đã vô cùng tự hào khi cô tốt nghiệp loại xuất sắc.)","He felt [proud] of his team after they won the championship match. (=Dịch: Anh ấy cảm thấy tự hào về đội của mình sau khi họ giành chiến thắng trong trận chung kết.)","She is too [proud] to ask for financial help from others. (=Dịch: Cô ấy quá kiêu hãnh để đi nhờ cậy sự giúp đỡ tài chính từ người khác.)"],"ukAudio":"/ai_services/tts3/?q=proud&lang=en-GB&ipa=%2Fpra%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=proud&lang=en-US&ipa=%2Fpra%CA%8Ad%2F"},{"id":"lv_7_123","topic":"Education and Learning","word":"qualified","pos":"(adj)","ipa":"/ˈkwɑː.lə.faɪd/","defVi":"Đủ điều kiện, có đủ trình độ chuyên môn.","defEn":"Having the necessary knowledge, skill, or qualifications to do a particular job.","examples":["She is fully [qualified] to teach English at the university level. (=Dịch: Cô ấy có đầy đủ trình độ chuyên môn để giảng dạy tiếng Anh ở bậc đại học.)","The company struggles to find [qualified] engineers with practical experience. (=Dịch: Công ty đang gặp khó khăn trong việc tìm kiếm các kỹ sư có chuyên môn và kinh nghiệm thực tế.)","Only [qualified] applicants will be invited for an in-person interview. (=Dịch: Chỉ những ứng viên đủ tiêu chuẩn mới được mời đến phỏng vấn trực tiếp.)"],"ukAudio":"/ai_services/tts3/?q=qualified&lang=en-GB&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=qualified&lang=en-US&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F"},{"id":"lv_7_124","topic":"Education and Learning","word":"queue","pos":"(v)","ipa":"/kjuː/","defVi":"xếp hàng","defEn":"to stand in a line waiting for something","examples":["Hundreds of fans had to [queue] for hours to buy concert tickets. (=Dịch: Hàng trăm người hâm mộ đã phải xếp hàng nhiều giờ để mua vé xem ca nhạc.)","Passengers should [queue] patiently at the boarding gate. (=Dịch: Hành khách nên kiên nhẫn xếp hàng tại cổng lên máy bay.)","We had to [queue] up outside the popular restaurant before getting a table. (=Dịch: Chúng tôi đã phải xếp hàng bên ngoài nhà hàng nổi tiếng trước khi có bàn.)"],"ukAudio":"/ai_services/tts3/?q=queue&lang=en-GB&ipa=%2Fkju%CB%90%2F","usAudio":"/ai_services/tts3/?q=queue&lang=en-US&ipa=%2Fkju%CB%90%2F"},{"id":"lv_7_125","topic":"Education and Learning","word":"recall","pos":"(v)","ipa":"/rɪˈkɔl/","defVi":"Gợi nhớ lại, nhớ lại","defEn":"To remember something or bring a fact or situation back into one's mind","examples":["I can clearly [recall] the first day I entered university. (=Dịch: Tôi có thể nhớ rất rõ ngày đầu tiên mình bước chân vào trường đại học.)","She struggled to [recall] the name of the author during the exam. (=Dịch: Cô ấy đã rất chật vật để nhớ lại tên của tác giả trong suốt kỳ thi.)","The witness could not [recall] the exact time of the accident. (=Dịch: Nhân chứng không thể nhớ lại thời điểm chính xác của vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=recall&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%C9%94l%2F","usAudio":"/ai_services/tts3/?q=recall&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%C9%94l%2F"},{"id":"lv_7_126","topic":"Education and Learning","word":"refectory","pos":"(n)","ipa":"/rɪˈfɛk.tə.ri/","defVi":"phòng ăn tập thể, nhà ăn (trong trường học, tu viện)","defEn":"a large room used for communal meals in a school, college, or monastery","examples":["Students usually gather in the university [refectory] at lunchtime. (=Dịch: Sinh viên thường tụ tập ở nhà ăn của trường đại học vào giờ ăn trưa.)","The campus [refectory] offers a variety of affordable hot meals. (=Dịch: Nhà ăn của trường cung cấp nhiều bữa ăn nóng sốt với giá cả phải chăng.)","Renovations were made to expand the seating capacity of the old [refectory]. (=Dịch: Việc cải tạo đã được tiến hành để mở rộng sức chứa chỗ ngồi của nhà ăn cũ.)"],"ukAudio":"/ai_services/tts3/?q=refectory&lang=en-GB&ipa=%2Fr%C9%AA%CB%88f%C9%9Bk.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=refectory&lang=en-US&ipa=%2Fr%C9%AA%CB%88f%C9%9Bk.t%C9%99.ri%2F"},{"id":"lv_7_127","topic":"Education and Learning","word":"register","pos":"(n)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"Sổ sách, danh sách chính thức, sổ điểm danh.","defEn":"An official list, record book, or database containing names or details.","examples":["The teacher called the names from the attendance [register] at the start of the lesson. (=Dịch: Giáo viên đã gọi tên theo sổ điểm danh vào đầu tiết học.)","The government keeps an official [register] of all licensed businesses. (=Dịch: Chính phủ lưu giữ một danh bạ chính thức về tất cả các doanh nghiệp được cấp phép.)","Guests are required to sign the hotel [register] upon arrival. (=Dịch: Khách lưu trú được yêu cầu ký vào sổ đăng ký của khách sạn khi đến nơi.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_7_128","topic":"Education and Learning","word":"registration","pos":"(n)","ipa":"/ˌredʒ.əˈstreɪ.ʃən/","defVi":"sự đăng ký, việc vào sổ","defEn":"the act of recording a name or details on an official list","examples":["Course [registration] opens online early on Monday morning. (=Dịch: Cổng đăng ký khóa học sẽ mở trực tuyến vào sáng sớm thứ Hai.)","Please show your ID card at the reception desk to complete your conference [registration]. (=Dịch: Vui lòng xuất trình thẻ căn cước tại bàn tiếp tân để hoàn tất việc đăng ký tham dự hội nghị.)","The fee for vehicle [registration] varies depending on the engine size. (=Dịch: Phí đăng ký xe thay đổi tùy thuộc vào dung tích xi-lanh.)"],"ukAudio":"/ai_services/tts3/?q=registration&lang=en-GB&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=registration&lang=en-US&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_129","topic":"Education and Learning","word":"rehearsal","pos":"(n)","ipa":"/rɪˈhɜːr.səl/","defVi":"buổi diễn tập, sự luyện tập","defEn":"a practice session for a play, concert, or other performance","examples":["The actors had their final [rehearsal] before opening night. (=Dịch: Các diễn viên đã có buổi tổng duyệt cuối cùng trước đêm công diễn.)","She missed the choir [rehearsal] because of a sudden illness. (=Dịch: Cô ấy đã bỏ lỡ buổi tập của dàn hợp xướng vì bị ốm đột ngột.)","We need more [rehearsal] time to perfect our dance routine. (=Dịch: Chúng tôi cần thêm thời gian tập luyện để hoàn thiện bài nhảy. phẩm.)"],"ukAudio":"/ai_services/tts3/?q=rehearsal&lang=en-GB&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90r.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rehearsal&lang=en-US&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90r.s%C9%99l%2F"},{"id":"lv_7_130","topic":"Education and Learning","word":"rehearse","pos":"(v)","ipa":"/rɪˈhɜːrs/","defVi":"diễn tập, tập dượt, tổng duyệt","defEn":"to practice a play, piece of music, or speech in preparation for a public performance","examples":["The actors need to [rehearse] their lines several times before opening night. (=Dịch: Các diễn viên cần phải tập dượt lời thoại của mình nhiều lần trước đêm công diễn.)","The orchestra gathered early in the morning to [rehearse] the symphony. (=Dịch: Dàn nhạc đã tập hợp từ sáng sớm để diễn tập bản giao hưởng.)","She spent hours standing in front of the mirror to [rehearse] her presentation. (=Dịch: Cô ấy đã dành hàng giờ đứng trước gương để tập dượt bài thuyết trình của mình.)"],"ukAudio":"/ai_services/tts3/?q=rehearse&lang=en-GB&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90rs%2F","usAudio":"/ai_services/tts3/?q=rehearse&lang=en-US&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90rs%2F"},{"id":"lv_7_131","topic":"Education and Learning","word":"relief","pos":"(n)","ipa":"/rɪˈliːf/","defVi":"sự nhẹ nhõm, sự khuây khỏa","defEn":"a feeling of happiness that something unpleasant has stopped or not happened","examples":["It was a huge [relief] to hear that everyone survived the accident. (=Dịch: Thật là một sự nhẹ nhõm lớn khi biết rằng tất cả mọi người đều sống sót sau vụ tai nạn.)","She breathed a sigh of [relief] when the exam was finally over. (=Dịch: Cô ấy thở phào nhẹ nhõm khi kỳ thi cuối cùng cũng kết thúc.)","The organization provided disaster [relief] to the flood victims. (=Dịch: Tổ chức này đã cung cấp viện trợ cứu trợ thiên tai cho các nạn nhân lũ lụt.)"],"ukAudio":"/ai_services/tts3/?q=relief&lang=en-GB&ipa=%2Fr%C9%AA%CB%88li%CB%90f%2F","usAudio":"/ai_services/tts3/?q=relief&lang=en-US&ipa=%2Fr%C9%AA%CB%88li%CB%90f%2F"},{"id":"lv_7_132","topic":"Education and Learning","word":"remind","pos":"(v)","ipa":"/rɪˈmaɪnd/","defVi":"nhắc nhở, gợi nhớ","defEn":"to help someone remember something or cause someone to think of something","examples":["Please [remind] me to call the doctor tomorrow morning. (=Dịch: Làm ơn nhắc tôi gọi điện cho bác sĩ vào sáng mai nhé.)","This song always [remind]s me of my university years. (=Dịch: Bài hát này luôn gợi nhớ cho tôi về những năm tháng đại học.)","The teacher had to [remind] the students about the deadline for the project. (=Dịch: Giáo viên đã phải nhắc nhở học sinh về hạn chót của dự án.)"],"ukAudio":"/ai_services/tts3/?q=remind&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=remind&lang=en-US&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F"},{"id":"lv_7_133","topic":"Education and Learning","word":"renew","pos":"(v)","ipa":"/rɪˈnu/","defVi":"gia hạn, làm mới lại","defEn":"to extend the period of validity of something, or make something new and fresh again","examples":["I need to go to the library to [renew] my borrowed books. (=Dịch: Tôi cần đến thư viện để gia hạn những cuốn sách đã mượn.)","He decided to [renew] his passport before traveling abroad. (=Dịch: Anh ấy quyết định làm mới hộ chiếu trước khi đi du lịch nước ngoài.)","The spring rain helped to [renew] the dry grass in the garden. (=Dịch: Cơn mưa mùa xuân đã giúp hồi sinh bãi cỏ khô cằn trong vườn.)"],"ukAudio":"/ai_services/tts3/?q=renew&lang=en-GB&ipa=%2Fr%C9%AA%CB%88nu%2F","usAudio":"/ai_services/tts3/?q=renew&lang=en-US&ipa=%2Fr%C9%AA%CB%88nu%2F"},{"id":"lv_7_134","topic":"Education and Learning","word":"restrict","pos":"(v)","ipa":"/rɪˈstrɪkt/","defVi":"hạn chế, giới hạn","defEn":"to put a limit on someone or something; to keep within bounds","examples":["The doctor advised him to [restrict] his daily sugar intake. (=Dịch: Bác sĩ khuyên anh ấy nên hạn chế lượng đường nạp vào cơ thể mỗi ngày.)","New traffic laws aim to [restrict] heavy trucks from entering the city center. (=Dịch: Luật giao thông mới nhằm hạn chế xe tải nặng đi vào trung tâm thành phố.)","Budget constraints will severely [restrict] the scope of our research project. (=Dịch: Những hạn chế về ngân sách sẽ giới hạn đáng kể phạm vi dự án nghiên cứu của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=restrict&lang=en-GB&ipa=%2Fr%C9%AA%CB%88str%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=restrict&lang=en-US&ipa=%2Fr%C9%AA%CB%88str%C9%AAkt%2F"},{"id":"lv_7_135","topic":"Education and Learning","word":"revise","pos":"(v)","ipa":"/rɪˈvaɪz/","defVi":"sửa đổi, xem lại, ôn tập","defEn":"to re-examine and make changes to a text or plan; to review material previously learned","examples":["The author had to [revise] several chapters before the book could be published. (=Dịch: Tác giả đã phải sửa đổi vài chương trước khi cuốn sách có thể được xuất bản.)","Students should [revise] their lecture notes every evening. (=Dịch: Sinh viên nên ôn tập lại các ghi chép bài giảng vào mỗi buổi tối.)","The committee decided to [revise] the company policies regarding remote work. (=Dịch: Ủy ban đã quyết định sửa đổi các chính sách của công ty liên quan đến làm việc từ xa.)"],"ukAudio":"/ai_services/tts3/?q=revise&lang=en-GB&ipa=%2Fr%C9%AA%CB%88va%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=revise&lang=en-US&ipa=%2Fr%C9%AA%CB%88va%C9%AAz%2F"},{"id":"lv_7_136","topic":"Education and Learning","word":"revision","pos":"(n)","ipa":"/rɪˈvɪʒ.ən/","defVi":"sự ôn tập, sự xem lại hoặc chỉnh sửa","defEn":"the process of changing, improving, or reviewing something such as a text or study material","examples":["He spent the whole weekend doing [revision] for his final exams. (=Dịch: Anh ấy đã dành cả ngày cuối tuần để ôn tập cho các bài thi cuối kỳ.)","The author made several major [revision]s to the second edition of the book. (=Dịch: Tác giả đã thực hiện vài chỉnh sửa lớn cho lần xuất bản thứ hai của cuốn sách.)","Careful [revision] of your essay can help you avoid simple grammatical mistakes. (=Dịch: Việc đọc và sửa lại bài luận cẩn thận có thể giúp bạn tránh các lỗi ngữ pháp đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=revision&lang=en-GB&ipa=%2Fr%C9%AA%CB%88v%C9%AA%CA%92.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=revision&lang=en-US&ipa=%2Fr%C9%AA%CB%88v%C9%AA%CA%92.%C9%99n%2F"},{"id":"lv_7_137","topic":"Education and Learning","word":"rhythm","pos":"(n)","ipa":"/ˈrɪð.əm/","defVi":"nhịp điệu, tiết tấu","defEn":"a regular repeated pattern of sounds, movements, or events","examples":["The dancers moved gracefully to the steady [rhythm] of the drums. (=Dịch: Các vũ công di chuyển uyển chuyển theo nhịp điệu đều đặn của tiếng trống.)","It took him a few weeks to get used to the fast [rhythm] of city life. (=Dịch: Anh ấy mất vài tuần để làm quen với nhịp sống hối hả của thành thị.)","Regular exercise can help restore the natural [rhythm] of your sleep cycle. (=Dịch: Tập thể dục đều đặn có thể giúp khôi phục nhịp sinh học tự nhiên của chu kỳ giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=rhythm&lang=en-GB&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=rhythm&lang=en-US&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F"},{"id":"lv_7_138","topic":"Education and Learning","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ɚ/","defVi":"cao su; cục tẩy","defEn":"a strong, elastic material made from the juice of a tropical plant or chemicals; also an eraser","examples":["The soles of these running shoes are made of durable [rubber]. (=Dịch: Đế của đôi giày chạy này được làm bằng cao su bền chắc.)","Can I borrow your [rubber] to fix a mistake in my drawing? (=Dịch: Tôi có thể mượn cục tẩy của bạn để sửa lỗi vẽ này không?)","The country is one of the world's leading exporters of natural [rubber]. (=Dịch: Quốc gia này là một trong những nước xuất khẩu cao su tự nhiên hàng đầu thế giới.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F"},{"id":"lv_7_139","topic":"Education and Learning","word":"sandy","pos":"(adj)","ipa":"/ˈsæn.di/","defVi":"nhiều cát, có tính cát","defEn":"covered with or containing a large amount of sand","examples":["We enjoyed walking barefoot along the warm, [sandy] beach. (=Dịch: Chúng tôi thích đi chân trần dọc theo bãi biển đầy cát ấm áp.)","Certain desert plants grow exceptionally well in dry, [sandy] soil. (=Dịch: Một số loài thực vật sa mạc phát triển đặc biệt tốt trong đất cát khô cằn.)","The children built giant castles on the [sandy] shore. (=Dịch: Những đứa trẻ đã xây những lâu đài khổng lồ trên bờ cát.)"],"ukAudio":"/ai_services/tts3/?q=sandy&lang=en-GB&ipa=%2F%CB%88s%C3%A6n.di%2F","usAudio":"/ai_services/tts3/?q=sandy&lang=en-US&ipa=%2F%CB%88s%C3%A6n.di%2F"},{"id":"lv_7_140","topic":"Education and Learning","word":"scandinavian","pos":"(adj)","ipa":"/ˌskæn.dəˈneɪ.vi.ən/","defVi":"thuộc về vùng Scandinavia (Bắc Âu)","defEn":"relating to Scandinavia, its people, languages, or culture","examples":["Many homeowners admire [scandinavian] interior design for its simplicity and light. (=Dịch: Nhiều chủ nhà yêu thích phong cách thiết kế nội thất Scandinavia vì sự tối giản và tràn ngập ánh sáng.)","The study compared social welfare policies across several [scandinavian] countries. (=Dịch: Nghiên cứu đã so sánh các chính sách phúc lợi xã hội giữa một số quốc gia vùng Bắc Âu.)","She is deeply interested in [scandinavian] mythology and folklore. (=Dịch: Cô ấy rất quan tâm đến thần thoại và văn hóa dân gian Scandinavia.)"],"ukAudio":"/ai_services/tts3/?q=scandinavian&lang=en-GB&ipa=%2F%CB%8Csk%C3%A6n.d%C9%99%CB%88ne%C9%AA.vi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=scandinavian&lang=en-US&ipa=%2F%CB%8Csk%C3%A6n.d%C9%99%CB%88ne%C9%AA.vi.%C9%99n%2F"},{"id":"lv_7_141","topic":"Education and Learning","word":"secondary","pos":"(adj)","ipa":"/ˈsek.ənˌder.i/","defVi":"thứ yếu, phụ; thuộc bậc trung học","defEn":"coming after what is primary or most important; relating to education for children aged roughly 11 to 18","examples":["Cost is a [secondary] consideration compared to safety. (=Dịch: Chi phí chỉ là yếu tố phụ so với sự an toàn.)","She is currently teaching at a local [secondary] school. (=Dịch: Cô ấy hiện đang giảng dạy tại một trường trung học cơ sở địa phương.)","The doctor treated the primary disease before addressing the [secondary] symptoms. (=Dịch: Bác sĩ đã điều trị căn bệnh chính trước khi giải quyết các triệu chứng thứ cấp.)"],"ukAudio":"/ai_services/tts3/?q=secondary&lang=en-GB&ipa=%2F%CB%88sek.%C9%99n%CB%8Cder.i%2F","usAudio":"/ai_services/tts3/?q=secondary&lang=en-US&ipa=%2F%CB%88sek.%C9%99n%CB%8Cder.i%2F"},{"id":"lv_7_142","topic":"Education and Learning","word":"seek","pos":"(v)","ipa":"/sik/","defVi":"tìm kiếm, mưu cầu","defEn":"to look for something or try to obtain it","examples":["Graduates often [seek] advice from career counselors. (=Dịch: Sinh viên mới tốt nghiệp thường tìm kiếm lời khuyên từ các chuyên viên tư vấn nghề nghiệp.)","The company is actively trying to [seek] new investment opportunities. (=Dịch: Công ty đang tích cực tìm kiếm các cơ hội đầu tư mới.)","You should [seek] medical attention if the symptoms persist. (=Dịch: Bạn nên tìm kiếm sự chăm sóc y tế nếu các triệu chứng vẫn kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsik%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsik%2F"},{"id":"lv_7_143","topic":"Education and Learning","word":"semester","pos":"(n)","ipa":"/səˈmɛs.tɚ/","defVi":"học kỳ","defEn":"one of the two periods that the school or college year is divided into","examples":["She decided to study abroad during the spring [semester]. (=Dịch: Cô ấy quyết định đi du học trong học kỳ mùa xuân.)","Our final exams will take place at the end of this [semester]. (=Dịch: Các kỳ thi cuối kỳ của chúng tôi sẽ diễn ra vào cuối học kỳ này.)","He managed to improve his grades significantly in the second [semester]. (=Dịch: Cậu ấy đã cải thiện điểm số đáng kể trong học kỳ thứ hai.)"],"ukAudio":"/ai_services/tts3/?q=semester&lang=en-GB&ipa=%2Fs%C9%99%CB%88m%C9%9Bs.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=semester&lang=en-US&ipa=%2Fs%C9%99%CB%88m%C9%9Bs.t%C9%9A%2F"},{"id":"lv_7_144","topic":"Education and Learning","word":"seminar","pos":"(n)","ipa":"/ˈsɛm.əˌnɑr/","defVi":"Hội thảo, buổi thảo luận chuyên đề","defEn":"A class at a university or college in which a small group discusses a specific topic","examples":["Students are required to attend a weekly [seminar] on environmental policy. (=Dịch: Sinh viên bắt buộc phải tham dự một buổi hội thảo hàng tuần về chính sách môi trường.)","Professor Davis led an engaging [seminar] about modern literature yesterday. (=Dịch: Hôm qua Giáo sư Davis đã dẫn dắt một buổi thảo luận chuyên đề hấp dẫn về văn học hiện đại.)","Active participation in the [seminar] will help you gain better course grades. (=Dịch: Tích cực tham gia vào buổi hội thảo sẽ giúp bạn đạt điểm học phần tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88s%C9%9Bm.%C9%99%CB%8Cn%C9%91r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88s%C9%9Bm.%C9%99%CB%8Cn%C9%91r%2F"},{"id":"lv_7_145","topic":"Education and Learning","word":"shock","pos":"(n)","ipa":"/ʃɑːk/","defVi":"sự cú sốc, sự kinh ngạc hoặc bàng hoàng","defEn":"a sudden upsetting or surprising event or experience","examples":["The sudden news of his resignation came as a complete [shock] to everyone. (=Dịch: Tin tức đột ngột về việc anh ấy từ chức hoàn toàn là một cú sốc đối với mọi người.)","She was in [shock] after witnessing the severe traffic accident. (=Dịch: Cô ấy đã bị sốc sau khi chứng kiến vụ tai nạn giao thông nghiêm trọng.)","The unexpected price increase caused a major [shock] in the financial market. (=Dịch: Việc tăng giá bất ngờ đã gây ra một cú sốc lớn trên thị trường tài chính.)"],"ukAudio":"/ai_services/tts3/?q=shock&lang=en-GB&ipa=%2F%CA%83%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=shock&lang=en-US&ipa=%2F%CA%83%C9%91%CB%90k%2F"},{"id":"lv_7_146","topic":"Education and Learning","word":"silence","pos":"(n)","ipa":"/ˈsaɪ.ləns/","defVi":"sự im lặng, sự tĩnh lặng","defEn":"the complete absence of sound or noise","examples":["A sudden [silence] fell over the room when the speaker walked onto the stage. (=Dịch: Một sự im lặng đột ngột bao trùm cả căn phòng khi diễn giả bước lên sân khấu.)","The library is a great place to study because of the total [silence]. (=Dịch: Thư viện là một nơi tuyệt vời để học tập nhờ vào sự yên tĩnh tuyệt đối.)","The audience observed a minute of [silence] to honor the victims. (=Dịch: Khán giả đã dành một phút mặc niệm để tưởng nhớ các nạn nhân.)"],"ukAudio":"/ai_services/tts3/?q=silence&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.l%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=silence&lang=en-US&ipa=%2F%CB%88sa%C9%AA.l%C9%99ns%2F"},{"id":"lv_7_147","topic":"Education and Learning","word":"snap","pos":"(v)","ipa":"/snæp/","defVi":"gãy tách, bẻ gãy đột ngột; chộp lấy","defEn":"to break suddenly with a sharp cracking sound, or to move quickly and abruptly","examples":["The branch began to [snap] under the heavy weight of the snow. (=Dịch: Cành cây bắt đầu gãy tách dưới sức nặng của tuyết.)","He tried to [snap] a quick photo before the train departed. (=Dịch: Anh ấy cố chụp nhanh một bức ảnh trước khi tàu rời ga.)","Tired and stressed, she finally began to [snap] at her colleagues. (=Dịch: Mệt mỏi và căng thẳng, cuối cùng cô ấy bắt đầu gắt gỏng với đồng nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=snap&lang=en-GB&ipa=%2Fsn%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=snap&lang=en-US&ipa=%2Fsn%C3%A6p%2F"},{"id":"lv_7_148","topic":"Education and Learning","word":"sociology","pos":"(n)","ipa":"/ˌsoʊ.siˈɑː.lə.dʒi/","defVi":"xã hội học","defEn":"the scientific study of society, human social relationships, and institutions","examples":["She decided to major in [sociology] at university to understand community behavior. (=Dịch: Cô ấy quyết định học chuyên ngành xã hội học tại trường đại học để hiểu về hành vi cộng đồng.)","The professor published several influential papers on urban [sociology]. (=Dịch: Vị giáo sư đã xuất bản một số bài báo có tầm ảnh hưởng về xã hội học đô thị.)","Students in the [sociology] class conducted a survey on local living standards. (=Dịch: Các sinh viên trong lớp xã hội học đã thực hiện một cuộc khảo sát về mức sống địa phương.)"],"ukAudio":"/ai_services/tts3/?q=sociology&lang=en-GB&ipa=%2F%CB%8Cso%CA%8A.si%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=sociology&lang=en-US&ipa=%2F%CB%8Cso%CA%8A.si%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_149","topic":"Education and Learning","word":"software","pos":"(n)","ipa":"/ˈsɑːft.wɛr/","defVi":"phần mềm máy tính","defEn":"the programs and other operating information used by a computer","examples":["The company developed new [software] to enhance cybersecurity. (=Dịch: Công ty đã phát triển phần mềm mới nhằm nâng cao an ninh mạng.)","You need to update your antivirus [software] regularly. (=Dịch: Bạn cần cập nhật phần mềm diệt vi-rút của mình thường xuyên.)","This graphic design [software] is very popular among creative professionals. (=Dịch: Phần mềm thiết kế đồ họa này rất phổ biến đối với các chuyên gia sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=software&lang=en-GB&ipa=%2F%CB%88s%C9%91%CB%90ft.w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=software&lang=en-US&ipa=%2F%CB%88s%C9%91%CB%90ft.w%C9%9Br%2F"},{"id":"lv_7_150","topic":"Education and Learning","word":"spatial","pos":"(adj)","ipa":"/ˈspeɪ.ʃəl/","defVi":"thuộc về không gian","defEn":"relating to the position, area, and size of things in space","examples":["Architects need to have excellent [spatial] awareness when designing buildings. (=Dịch: Các kiến trúc sư cần có khả năng nhận thức không gian tuyệt vời khi thiết kế các tòa nhà.)","The test measures both verbal and [spatial] reasoning abilities. (=Dịch: Bài kiểm tra đo lường cả khả năng suy luận ngôn ngữ lẫn không gian.)","Video games can help children develop better [spatial] skills. (=Dịch: Trò chơi điện tử có thể giúp trẻ em phát triển các kỹ năng không gian tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=spatial&lang=en-GB&ipa=%2F%CB%88spe%C9%AA.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spatial&lang=en-US&ipa=%2F%CB%88spe%C9%AA.%CA%83%C9%99l%2F"},{"id":"lv_7_151","topic":"Education and Learning","word":"specialised","pos":"(adj)","ipa":"/ˈspeʃ.ə.laɪzd/","defVi":"chuyên dụng, chuyên môn hóa","defEn":"designed for or relating to a particular purpose, activity, or area of knowledge","examples":["This lab requires [specialised] equipment to conduct precise chemical tests. (=Dịch: Phòng thí nghiệm này yêu cầu thiết bị chuyên dụng để thực hiện các xét nghiệm hóa học chính xác.)","The doctor gave her [specialised] medical advice regarding her rare condition. (=Dịch: Bác sĩ đã đưa ra cho cô ấy lời khuyên y tế chuyên sâu về tình trạng bệnh hiếm gặp của mình.)","He took several [specialised] training courses to advance his technical career. (=Dịch: Anh ấy đã tham gia nhiều khóa đào tạo chuyên ngành để phát triển sự nghiệp kỹ thuật của mình.)"],"ukAudio":"/ai_services/tts3/?q=specialised&lang=en-GB&ipa=%2F%CB%88spe%CA%83.%C9%99.la%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=specialised&lang=en-US&ipa=%2F%CB%88spe%CA%83.%C9%99.la%C9%AAzd%2F"},{"id":"lv_7_152","topic":"Education and Learning","word":"spectator","pos":"(n)","ipa":"/ˈspɛk.teɪ.tər/","defVi":"khán giả (theo dõi sự kiện, trận đấu ngoài trời/thể thao)","defEn":"a person who watches a show, game, or other event","examples":["Over fifty thousand [spectator]s gathered at the stadium for the football final. (=Dịch: Hơn năm mươi ngàn khán giả đã tập trung tại sân vận động cho trận chung kết bóng đá.)","An excited [spectator] ran onto the pitch during the tennis match. (=Dịch: Một khán giả quá khích đã chạy vào sân trong suốt trận đấu quần vợt.)","She preferred being a [spectator] rather than participating in competitive sports. (=Dịch: Cô ấy thích làm khán giả hơn là tham gia vào các môn thể thao thi đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectator&lang=en-GB&ipa=%2F%CB%88sp%C9%9Bk.te%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=spectator&lang=en-US&ipa=%2F%CB%88sp%C9%9Bk.te%C9%AA.t%C9%99r%2F"},{"id":"lv_7_153","topic":"Education and Learning","word":"spin","pos":"(v)","ipa":"/spɪn/","defVi":"quay tròn, xoay tròn","defEn":"to turn around quickly and repeatedly","examples":["The dancer began to [spin] gracefully across the stage. (=Dịch: Vũ công bắt đầu xoay tròn một cách uyển chuyển trên sân khấu.)","If you [spin] around too fast, you might feel dizzy. (=Dịch: Nếu bạn quay tròn quá nhanh, bạn có thể cảm thấy chóng mặt.)","The washing machine started to [spin] the clothes dry. (=Dịch: Máy giặt bắt đầu vắt khô quần áo.)"],"ukAudio":"/ai_services/tts3/?q=spin&lang=en-GB&ipa=%2Fsp%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spin&lang=en-US&ipa=%2Fsp%C9%AAn%2F"},{"id":"lv_7_154","topic":"Education and Learning","word":"spite","pos":"(n)","ipa":"/spaɪt/","defVi":"sự ác ý, lòng hằn học","defEn":"a desire to hurt, annoy, or offend someone","examples":["He refused to invite her out of pure [spite]. (=Dịch: Anh ấy từ chối mời cô ấy chỉ vì lòng ác ý đơn thuần.)","She hid his keys just for [spite]. (=Dịch: Cô ấy giấu chìa khóa của anh ta chỉ để chọc tức.)","In [spite] of the heavy rain, they decided to go camping. (=Dịch: Mặc dù trời mưa to, họ vẫn quyết định đi cắm trại.)"],"ukAudio":"/ai_services/tts3/?q=spite&lang=en-GB&ipa=%2Fspa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=spite&lang=en-US&ipa=%2Fspa%C9%AAt%2F"},{"id":"lv_7_155","topic":"Education and Learning","word":"sponsor","pos":"(v)","ipa":"/ˈspɑn.sɚ/","defVi":"tài trợ, bảo trợ","defEn":"to support a person, organization, or event by providing money or other help","examples":["A local bank agreed to [sponsor] the youth sports tournament. (=Dịch: Một ngân hàng địa phương đã đồng ý tài trợ cho giải đấu thể thao thanh thiếu niên.)","Many large companies [sponsor] scientific research at the university. (=Dịch: Nhiều công ty lớn tài trợ cho các nghiên cứu khoa học tại trường đại học.)","They are looking for international partners to [sponsor] the cultural festival. (=Dịch: Họ đang tìm kiếm các đối tác quốc tế để tài trợ cho lễ hội văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=sponsor&lang=en-GB&ipa=%2F%CB%88sp%C9%91n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sponsor&lang=en-US&ipa=%2F%CB%88sp%C9%91n.s%C9%9A%2F"},{"id":"lv_7_156","topic":"Education and Learning","word":"sporting","pos":"(adj)","ipa":"/ˈspɔːr.tɪŋ/","defVi":"liên quan đến thể thao, mang tính thể thao","defEn":"connected with or used for sports","examples":["The Olympic Games is the biggest international [sporting] event in the world. (=Dịch: Thế vận hội Olympic là sự kiện thể thao quốc tế lớn nhất trên thế giới.)","The school recently invested in modern [sporting] facilities for students. (=Dịch: Nhà trường gần đây đã đầu tư vào cơ sở vật chất thể thao hiện đại cho học sinh.)","She comes from a very [sporting] family where everyone plays tennis. (=Dịch: Cô ấy xuất thân từ một gia đình rất yêu thể thao, nơi ai cũng chơi quần vợt.)"],"ukAudio":"/ai_services/tts3/?q=sporting&lang=en-GB&ipa=%2F%CB%88sp%C9%94%CB%90r.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sporting&lang=en-US&ipa=%2F%CB%88sp%C9%94%CB%90r.t%C9%AA%C5%8B%2F"},{"id":"lv_7_157","topic":"Education and Learning","word":"structured","pos":"(adj)","ipa":"/ˈstrʌk.tʃɚd/","defVi":"Có cấu trúc rõ ràng, có tổ chức, bài bản","defEn":"Organized in a clear, systematic, or planned way","examples":["The course offers a well [structured] approach to learning academic writing. (=Dịch: Khóa học cung cấp một phương pháp có cấu trúc bài bản để học viết học thuật.)","Children often thrive in a highly [structured] classroom environment. (=Dịch: Trẻ em thường phát triển tốt trong một môi trường lớp học có tổ chức kỷ luật chặt chẽ.)","The interview followed a [structured] format with predefined questions. (=Dịch: Buổi phỏng vấn tuân theo một định dạng có cấu trúc với các câu hỏi được định trước.)"],"ukAudio":"/ai_services/tts3/?q=structured&lang=en-GB&ipa=%2F%CB%88str%CA%8Ck.t%CA%83%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=structured&lang=en-US&ipa=%2F%CB%88str%CA%8Ck.t%CA%83%C9%9Ad%2F"},{"id":"lv_7_158","topic":"Education and Learning","word":"supervise","pos":"(v)","ipa":"/ˈsu.pər.vaɪz/","defVi":"giám sát, quản lý","defEn":"to watch and direct someone or something to make sure work is done correctly","examples":["A senior manager was appointed to [supervise] the construction project. (=Dịch: Một người quản lý cấp cao đã được chỉ định để giám sát dự án xây dựng.)","Teachers must [supervise] students closely during laboratory experiments. (=Dịch: Giáo viên phải giám sát học sinh chặt chẽ trong các buổi thực hành thí nghiệm.)","She was asked to [supervise] the new interns during their first week. (=Dịch: Cô ấy được yêu cầu giám sát các thực tập sinh mới trong tuần đầu tiên của họ.)"],"ukAudio":"/ai_services/tts3/?q=supervise&lang=en-GB&ipa=%2F%CB%88su.p%C9%99r.va%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=supervise&lang=en-US&ipa=%2F%CB%88su.p%C9%99r.va%C9%AAz%2F"},{"id":"lv_7_159","topic":"Education and Learning","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng / phụ lục","defEn":"something added to complete a thing, make up for a deficiency, or extend it","examples":["Many athletes take a daily vitamin [supplement] to improve their performance. (=Dịch: Nhiều vận động viên uống bổ sung vitamin hàng ngày để cải thiện thành tích của họ.)","The Sunday newspaper includes a special travel [supplement] this week. (=Dịch: Báo ra ngày Chủ nhật tuần này có thêm một phụ lục du lịch đặc biệt.)","She worked a second job as a [supplement] to her regular income. (=Dịch: Cô ấy đã làm thêm công việc thứ hai để bổ sung cho thu nhập thường kỳ của mình.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_7_160","topic":"Education and Learning","word":"supportive","pos":"(adj)","ipa":"/səˈpɔːr.t̬ɪv/","defVi":"ủng hộ, luôn khích lệ và giúp đỡ","defEn":"providing encouragement, help, or emotional support to someone","examples":["Her family was extremely [supportive] when she decided to change her career path. (=Dịch: Gia đình đã rất ủng hộ khi cô ấy quyết định thay đổi con đường sự nghiệp.)","A [supportive] work environment can significantly reduce employee stress. (=Dịch: Một môi trường làm việc luôn hỗ trợ nhau có thể giảm đáng kể sự căng thẳng của nhân viên.)","He thanked his friends for being so [supportive] during his difficult times. (=Dịch: Anh ấy cảm ơn bạn bè vì đã luôn ở bên giúp đỡ trong suốt những thời điểm khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=supportive&lang=en-GB&ipa=%2Fs%C9%99%CB%88p%C9%94%CB%90r.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=supportive&lang=en-US&ipa=%2Fs%C9%99%CB%88p%C9%94%CB%90r.t%CC%AC%C9%AAv%2F"},{"id":"lv_7_161","topic":"Education and Learning","word":"swedish","pos":"(adj)","ipa":"/ˈswi.dɪʃ/","defVi":"thuộc về Thụy Điển hoặc tiếng Thụy Điển","defEn":"relating to Sweden, its people, or its language","examples":["The company is famous for selling affordable [swedish] furniture worldwide. (=Dịch: Công ty này nổi tiếng với việc bán đồ nội thất Thụy Điển giá cả phải chăng trên toàn thế giới.)","He is learning the [swedish] language before moving to Stockholm for his studies. (=Dịch: Anh ấy đang học tiếng Thụy Điển trước khi chuyển đến Stockholm để du học.)","Traditional [swedish] cuisine often features fresh fish and root vegetables. (=Dịch: Ẩm thực Thụy Điển truyền thống thường có cá tươi và các loại củ.)"],"ukAudio":"/ai_services/tts3/?q=swedish&lang=en-GB&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=swedish&lang=en-US&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F"},{"id":"lv_7_162","topic":"Education and Learning","word":"tame","pos":"(adj)","ipa":"/ˈteɪm/","defVi":"đã thuần hóa, ngoan ngoãn","defEn":"not wild or dangerous because of being trained to live with people","examples":["The birds in the city park are remarkably [tame] and will eat from your hand. (=Dịch: Những chú chim trong công viên thành phố rất dạn người và sẽ ăn trực tiếp từ tay bạn.)","After years of living on the farm, the deer became completely [tame]. (=Dịch: Sau nhiều năm sống trong nông trại, chú hươu đã trở nên hoàn toàn thuần tính.)","Critics found the action movie rather [tame] compared to its thrilling prequel. (=Dịch: Các nhà phê bình thấy bộ phim hành động này khá tẻ nhạt khi so sánh với phần trước đầy kịch tính.)"],"ukAudio":"/ai_services/tts3/?q=tame&lang=en-GB&ipa=%2F%CB%88te%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=tame&lang=en-US&ipa=%2F%CB%88te%C9%AAm%2F"},{"id":"lv_7_163","topic":"Education and Learning","word":"terminology","pos":"(n)","ipa":"/ˌtɜr.məˈnɑ.lə.dʒi/","defVi":"thuật ngữ, hệ thống thuật ngữ chuyên môn","defEn":"the special words or expressions used in relation to a particular subject or job","examples":["Medical [terminology] can be difficult for ordinary patients to understand. (=Dịch: Thuật ngữ y khoa có thể khó hiểu đối với những bệnh nhân bình thường.)","The lecturer explained the scientific [terminology] before starting the experiment. (=Dịch: Giảng viên đã giải thích các thuật ngữ khoa học trước khi bắt đầu thí nghiệm.)","You should avoid using too much technical [terminology] in your IELTS essay. (=Dịch: Bạn nên tránh sử dụng quá nhiều thuật ngữ kỹ thuật trong bài luận IELTS của mình.)"],"ukAudio":"/ai_services/tts3/?q=terminology&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Cr.m%C9%99%CB%88n%C9%91.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=terminology&lang=en-US&ipa=%2F%CB%8Ct%C9%9Cr.m%C9%99%CB%88n%C9%91.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_164","topic":"Education and Learning","word":"terribly","pos":"(adv)","ipa":"/ˈter.ə.bli/","defVi":"vô cùng, rất nhiều","defEn":"very much; extremely","examples":["I am [terribly] sorry for keeping you waiting for so long. (=Dịch: Tôi vô cùng xin lỗi vì đã để bạn phải đợi lâu như vậy.)","She was [terribly] nervous before giving her presentation to the class. (=Dịch: Cô ấy đã cực kỳ lo lắng trước khi thuyết trình trước cả lớp.)","The weather was [terribly] cold during our winter trip. (=Dịch: Thời tiết vô cùng lạnh giá trong chuyến đi mùa đông của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=terribly&lang=en-GB&ipa=%2F%CB%88ter.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=terribly&lang=en-US&ipa=%2F%CB%88ter.%C9%99.bli%2F"},{"id":"lv_7_165","topic":"Education and Learning","word":"testing","pos":"(n)","ipa":"/ˈtɛs.tɪŋ/","defVi":"sự kiểm tra, thử nghiệm","defEn":"the activity of examining something to find out how well it works or if it is safe","examples":["The new drug is currently undergoing clinical [testing] on human volunteers. (=Dịch: Loại thuốc mới hiện đang trải qua quá trình thử nghiệm lâm sàng trên các tình nguyện viên.)","Extensive safety [testing] is required before any vehicle is approved for sale. (=Dịch: Việc kiểm tra an toàn toàn diện là bắt buộc trước khi bất kỳ phương tiện nào được phép bán ra.)","Software [testing] helps identify bugs before the official release date. (=Dịch: Việc kiểm thử phần mềm giúp phát hiện các lỗi trước ngày phát hành chính thức.)"],"ukAudio":"/ai_services/tts3/?q=testing&lang=en-GB&ipa=%2F%CB%88t%C9%9Bs.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=testing&lang=en-US&ipa=%2F%CB%88t%C9%9Bs.t%C9%AA%C5%8B%2F"},{"id":"lv_7_166","topic":"Education and Learning","word":"textbook","pos":"(n)","ipa":"/ˈtɛkst.bʊk/","defVi":"sách giáo khoa, giáo trình","defEn":"a book that contains detailed information about a subject for study in schools or colleges","examples":["Students are required to buy the latest biology [textbook] for this course. (=Dịch: Sinh viên được yêu cầu mua cuốn giáo trình sinh học mới nhất cho khóa học này.)","She opened her history [textbook] to revise for the upcoming exam. (=Dịch: Cô ấy mở sách giáo khoa lịch sử ra để ôn tập cho kỳ thi sắp tới.)","His response was a [textbook] example of professional communication. (=Dịch: Câu trả lời của anh ấy là một ví dụ điển hình mang tính sách vở về kỹ năng giao tiếp chuyên nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=textbook&lang=en-GB&ipa=%2F%CB%88t%C9%9Bkst.b%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=textbook&lang=en-US&ipa=%2F%CB%88t%C9%9Bkst.b%CA%8Ak%2F"},{"id":"lv_7_167","topic":"Education and Learning","word":"tone","pos":"(n)","ipa":"/toʊn/","defVi":"giọng điệu, sắc thái, tông giọng","defEn":"the general mood, feeling, or attitude expressed in speech or writing","examples":["Try to keep a polite [tone] when responding to customer complaints. (=Dịch: Hãy cố gắng giữ giọng điệu lịch sự khi phản hồi các khiếu nại của khách hàng.)","The professor used a serious [tone] to discuss the importance of academic honesty. (=Dịch: Giáo sư đã sử dụng một tông giọng nghiêm túc để thảo luận về tầm quan trọng của sự trung thực trong học thuật.)","The article set an optimistic [tone] regarding future economic growth. (=Dịch: Bài báo đã tạo ra một sắc thái lạc quan về sự tăng trưởng kinh tế trong tương lai.)"],"ukAudio":"/ai_services/tts3/?q=tone&lang=en-GB&ipa=%2Fto%CA%8An%2F","usAudio":"/ai_services/tts3/?q=tone&lang=en-US&ipa=%2Fto%CA%8An%2F"},{"id":"lv_7_168","topic":"Education and Learning","word":"tough","pos":"(adj)","ipa":"/tʌf/","defVi":"khó khăn, cam go; cứng rắn, bền bỉ","defEn":"difficult to do, deal with, or overcome; strong and durable","examples":["The committee had to make some [tough] decisions about budget cuts. (=Dịch: Ủy ban đã phải đưa ra một số quyết định khó khăn về việc cắt giảm ngân sách.)","He showed that he was [tough] enough to handle the pressure of the competition. (=Dịch: Anh ấy đã chứng minh rằng mình đủ kiên cường để chịu được áp lực của cuộc thi.)","Hiking across the rugged mountains proved to be a [tough] challenge for the group. (=Dịch: Chuyến đi bộ qua những ngọn núi gồ ghề hóa ra là một thử thách cam go đối với cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=tough&lang=en-GB&ipa=%2Ft%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=tough&lang=en-US&ipa=%2Ft%CA%8Cf%2F"},{"id":"lv_7_169","topic":"Education and Learning","word":"tutorial","pos":"(n)","ipa":"/tuːˈtɔr.i.əl/","defVi":"Buổi học phụ đạo, buổi thảo luận nhóm nhỏ với giảng viên","defEn":"A period of study with a tutor involving one student or a very small group","examples":["I booked an individual [tutorial] to discuss my research proposal with the supervisor. (=Dịch: Tôi đã đặt một buổi học riêng với người hướng dẫn để thảo luận về đề cương nghiên cứu của mình.)","The weekly [tutorial] gives students a chance to ask detailed questions. (=Dịch: Buổi phụ đạo hàng tuần mang đến cho sinh viên cơ hội đặt ra những câu hỏi chi tiết.)","You can watch an online video [tutorial] to learn basic programming skills. (=Dịch: Bạn có thể xem một video hướng dẫn trực tuyến để học các kỹ năng lập trình cơ bản.)"],"ukAudio":"/ai_services/tts3/?q=tutorial&lang=en-GB&ipa=%2Ftu%CB%90%CB%88t%C9%94r.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tutorial&lang=en-US&ipa=%2Ftu%CB%90%CB%88t%C9%94r.i.%C9%99l%2F"},{"id":"lv_7_170","topic":"Education and Learning","word":"ultimate","pos":"(adj)","ipa":"/ˈʌl.tə.mət/","defVi":"cuối cùng, tối thượng, cốt yếu","defEn":"final, highest, or most important; happening at the end of a long process","examples":["Her [ultimate] goal is to establish her own environmental research foundation. (=Dịch: Mục tiêu cuối cùng của cô ấy là thành lập quỹ nghiên cứu môi trường của riêng mình.)","The president holds the [ultimate] responsibility for the government's decisions. (=Dịch: Tổng thống nắm giữ trách nhiệm tối cao đối với các quyết định của chính phủ.)","Finding a cure for the disease remains the [ultimate] aim of the scientists. (=Dịch: Tìm ra phương pháp chữa khỏi căn bệnh vẫn là mục tiêu quan trọng nhất của các nhà khoa học.)"],"ukAudio":"/ai_services/tts3/?q=ultimate&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=ultimate&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F"},{"id":"lv_7_171","topic":"Education and Learning","word":"uncertainty","pos":"(n)","ipa":"/ʌnˈsɝː.tən.ti/","defVi":"sự không chắc chắn, tình trạng bất định","defEn":"a state of not being definite or clear","examples":["Economic [uncertainty] has caused many people to delay buying a home. (=Dịch: Sự bất ổn kinh tế đã khiến nhiều người trì hoãn việc mua nhà.)","There is still some [uncertainty] about the exact date of the exam. (=Dịch: Vẫn còn một vài sự không chắc chắn về ngày thi chính xác.)","Living with so much [uncertainty] can be very stressful. (=Dịch: Sống trong quá nhiều sự bất định có thể gây ra rất nhiều căng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=uncertainty&lang=en-GB&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F","usAudio":"/ai_services/tts3/?q=uncertainty&lang=en-US&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F"},{"id":"lv_7_172","topic":"Education and Learning","word":"undergraduate","pos":"(n)","ipa":"/ˌʌn.dərˈɡrædʒ.u.ət/","defVi":"sinh viên chưa tốt nghiệp, sinh viên đại học (chưa có bằng cử nhân)","defEn":"a university student who has not yet completed their first degree (bachelor's)","examples":["The scholarship is open to any full-time [undergraduate] studying science. (=Dịch: Học bổng dành cho bất kỳ sinh viên đại học chính quy nào đang theo học ngành khoa học.)","As an [undergraduate], she participated actively in student government. (=Dịch: Khi còn là sinh viên đại học, cô đã tích cực tham gia vào ban đại diện sinh viên.)","The university offers research opportunities even at the [undergraduate] level. (=Dịch: Trường đại học mang lại các cơ hội nghiên cứu ngay cả ở bậc đại học.)"],"ukAudio":"/ai_services/tts3/?q=undergraduate&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=undergraduate&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F"},{"id":"lv_7_173","topic":"Education and Learning","word":"unfair","pos":"(adj)","ipa":"/ʌnˈfɛr/","defVi":"bất công, không công bằng","defEn":"not treating people equally or according to the rules of justice","examples":["Many employees felt that the promotion process was completely [unfair]. (=Dịch: Nhiều nhân viên cảm thấy rằng quy trình thăng chức hoàn toàn không công bằng.)","It is [unfair] to judge someone without knowing the full context of their actions. (=Dịch: Thật bất công khi phán xét ai đó mà không biết rõ toàn bộ bối cảnh hành động của họ.)","The team complained about an [unfair] referee decision during the match. (=Dịch: Đội bóng đã phàn nàn về một quyết định thiếu công bằng của trọng tài trong trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=unfair&lang=en-GB&ipa=%2F%CA%8Cn%CB%88f%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=unfair&lang=en-US&ipa=%2F%CA%8Cn%CB%88f%C9%9Br%2F"},{"id":"lv_7_174","topic":"Education and Learning","word":"unfamiliar","pos":"(adj)","ipa":"/ˌʌn.fəˈmɪl.jɚ/","defVi":"xa lạ, không quen thuộc","defEn":"not known or recognized; strange","examples":["He felt nervous driving in an [unfamiliar] city at night. (=Dịch: Anh ấy cảm thấy lo lắng khi lái xe ở một thành phố xa lạ vào ban đêm.)","The text was full of [unfamiliar] technical terms. (=Dịch: Đoạn văn bản chứa đầy những thuật ngữ kỹ thuật xa lạ.)","She had to adapt quickly to [unfamiliar] working conditions. (=Dịch: Cô ấy đã phải thích nghi nhanh chóng với điều kiện làm việc mới mẻ.)"],"ukAudio":"/ai_services/tts3/?q=unfamiliar&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.f%C9%99%CB%88m%C9%AAl.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=unfamiliar&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.f%C9%99%CB%88m%C9%AAl.j%C9%9A%2F"},{"id":"lv_7_175","topic":"Education and Learning","word":"unpaid","pos":"(adj)","ipa":"/ˌʌnˈpeɪd/","defVi":"không được trả lương, chưa thanh toán","defEn":"done without receiving pay, or not yet paid","examples":["She decided to take three months of [unpaid] leave to care for her mother. (=Dịch: Cô ấy quyết định nghỉ phép không lương ba tháng để chăm sóc mẹ.)","There are several [unpaid] bills sitting on his desk. (=Dịch: Có vài hóa đơn chưa thanh toán đang nằm trên bàn làm việc của anh ấy.)","Many students gain experience by doing [unpaid] internships. (=Dịch: Nhiều sinh viên tích lũy kinh nghiệm bằng cách tham gia các kỳ thực tập không lương.)"],"ukAudio":"/ai_services/tts3/?q=unpaid&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn%CB%88pe%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unpaid&lang=en-US&ipa=%2F%CB%8C%CA%8Cn%CB%88pe%C9%AAd%2F"},{"id":"lv_7_176","topic":"Education and Learning","word":"update","pos":"(n)","ipa":"/ˈʌp.deɪt/","defVi":"thông tin cập nhật, bản cập nhật","defEn":"the latest information about a situation, or a new version of software","examples":["The manager gave us an [update] on the progress of the project. (=Dịch: Người quản lý đã cung cấp cho chúng tôi thông tin cập nhật về tiến độ dự án.)","Make sure you install the latest security [update] on your phone. (=Dịch: Hãy chắc chắn rằng bạn đã cài đặt bản cập nhật bảo mật mới nhất trên điện thoại của mình.)","Stay tuned for weather [update]s throughout the evening. (=Dịch: Hãy đón xem các bản tin cập nhật thời tiết trong suốt buổi tối.)"],"ukAudio":"/ai_services/tts3/?q=update&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=update&lang=en-US&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F"},{"id":"lv_7_177","topic":"Education and Learning","word":"verb","pos":"(n)","ipa":"/vɜrb/","defVi":"động từ","defEn":"a word that describes an action, condition, or experience","examples":["Every complete English sentence must contain at least one [verb]. (=Dịch: Mỗi câu tiếng Anh hoàn chỉnh phải chứa ít nhất một động từ.)","Irregular [verb] forms can be challenging for beginners to memorize. (=Dịch: Các dạng động từ bất quy tắc có thể là thử thách ghi nhớ đối với người mới bắt đầu.)","Can you identify the main [verb] in this complex sentence? (=Dịch: Bạn có thể xác định động từ chính trong câu phức này không?)"],"ukAudio":"/ai_services/tts3/?q=verb&lang=en-GB&ipa=%2Fv%C9%9Crb%2F","usAudio":"/ai_services/tts3/?q=verb&lang=en-US&ipa=%2Fv%C9%9Crb%2F"},{"id":"lv_7_178","topic":"Education and Learning","word":"version","pos":"(n)","ipa":"/ˈvɝː.ʒən/","defVi":"phiên bản","defEn":"a particular form of something that differs slightly from others","examples":["You should install the latest [version] of the software for better security. (=Dịch: Bạn nên cài đặt phiên bản mới nhất của phần mềm để bảo mật tốt hơn.)","His [version] of the events differed greatly from what actually happened. (=Dịch: Phiên bản lời kể của anh ấy về các sự việc khác rất nhiều so với những gì thực sự đã xảy ra.)","The movie is a modern [version] of a classic fairy tale. (=Dịch: Bộ phim là một phiên bản hiện đại của một câu chuyện cổ tích kinh điển.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_7_179","topic":"Education and Learning","word":"vet","pos":"(n)","ipa":"/vɛt/","defVi":"bác sĩ thú y","defEn":"a doctor who treats animals","examples":["We took our injured dog to the [vet] immediately. (=Dịch: Chúng tôi đã đưa chú chó bị thương đến bác sĩ thú y ngay lập tức.)","She has wanted to become a [vet] ever since she was a little girl. (=Dịch: Cô ấy đã muốn trở thành một bác sĩ thú y kể từ khi còn là một cô bé.)","The [vet] prescribed some medicine for the cat's ear infection. (=Dịch: Bác sĩ thú y đã kê đơn thuốc điều trị nhiễm trùng tai cho con mèo.)"],"ukAudio":"/ai_services/tts3/?q=vet&lang=en-GB&ipa=%2Fv%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=vet&lang=en-US&ipa=%2Fv%C9%9Bt%2F"},{"id":"lv_7_180","topic":"Education and Learning","word":"vocabulary","pos":"(n)","ipa":"/voʊˈkæb.jəˌlɛr.i/","defVi":"Vốn từ vựng, từ ngữ","defEn":"All the words known or used by a person, or in a particular language","examples":["Reading academic articles regularly will help expand your [vocabulary]. (=Dịch: Đọc các bài báo học thuật thường xuyên sẽ giúp mở rộng vốn từ vựng của bạn.)","The test evaluates your command of English [vocabulary] and grammar. (=Dịch: Bài kiểm tra đánh giá khả năng nắm vững ngữ pháp và từ vựng tiếng Anh của bạn.)","Medical students must learn a large amount of specialized [vocabulary]. (=Dịch: Sinh viên y khoa phải học một lượng lớn từ vựng chuyên ngành.)"],"ukAudio":"/ai_services/tts3/?q=vocabulary&lang=en-GB&ipa=%2Fvo%CA%8A%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=vocabulary&lang=en-US&ipa=%2Fvo%CA%8A%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F"},{"id":"lv_7_181","topic":"Education and Learning","word":"weakness","pos":"(n)","ipa":"/ˈwik.nəs/","defVi":"điểm yếu, nhược điểm","defEn":"a particular part of someone's character or ability that is not strong; a lack of strength","examples":["She was asked about her greatest [weakness] during the job interview. (=Dịch: Cô ấy đã được hỏi về điểm yếu lớn nhất của mình trong buổi phỏng vấn xin việc.)","Chocolate is my biggest [weakness] when I try to diet. (=Dịch: Sô-cô-la là điểm yếu lớn nhất của tôi mỗi khi cố gắng ăn kiêng.)","The report highlighted several [weaknesses] in the company's security system. (=Dịch: Bản báo cáo đã nêu bật một số điểm yếu trong hệ thống an ninh của công ty.)"],"ukAudio":"/ai_services/tts3/?q=weakness&lang=en-GB&ipa=%2F%CB%88wik.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=weakness&lang=en-US&ipa=%2F%CB%88wik.n%C9%99s%2F"},{"id":"lv_7_182","topic":"Education and Learning","word":"zone","pos":"(n)","ipa":"/ˈzoʊn/","defVi":"khu vực, phân khu","defEn":"an area or region that has a particular feature or purpose","examples":["The city created a pedestrian [zone] where cars are not allowed. (=Dịch: Thành phố đã tạo ra một khu vực dành cho người đi bộ, nơi các phương tiện ô tô không được phép đi vào.)","Smoking is strictly prohibited in this designated non-smoking [zone]. (=Dịch: Hút thuốc bị nghiêm cấm trong khu vực không hút thuốc đã được quy định này.)","The government declared the flooded region a disaster [zone]. (=Dịch: Chính phủ đã tuyên bố khu vực ngập lụt là một vùng thảm họa.)"],"ukAudio":"/ai_services/tts3/?q=zone&lang=en-GB&ipa=%2F%CB%88zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=zone&lang=en-US&ipa=%2F%CB%88zo%CA%8An%2F"},{"id":"lv_8_0","topic":"Food and Health","word":"absorb","pos":"(v)","ipa":"/əbˈzɔːrb/","defVi":"hấp thụ, thấm hút","defEn":"to take in liquid, gas, or heat gradually from the space or surface around","examples":["Plants [absorb] nutrients and water from the soil through their roots. (=Dịch: Cây cối hấp thụ chất dinh dưỡng và nước từ đất thông qua rễ.)","Use a dry sponge to [absorb] the spilled juice on the table. (=Dịch: Dùng một miếng bọt biển khô để thấm nước trái cây bị đổ trên bàn.)","Black clothing tends to [absorb] more heat from sunlight than white clothing. (=Dịch: Quần áo màu đen có xu hướng hấp thụ nhiều nhiệt từ ánh nắng mặt trời hơn quần áo màu trắng.)"],"ukAudio":"/ai_services/tts3/?q=absorb&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=absorb&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F"},{"id":"lv_8_1","topic":"Food and Health","word":"acid","pos":"(n)","ipa":"/ˈæs.ɪd/","defVi":"axit","defEn":"a chemical substance with a pH of less than 7 that reacts with bases","examples":["Citrus fruits contain citric [acid], which gives them a sour taste. (=Dịch: Trái cây họ cam quýt có chứa axit xitric, tạo cho chúng có vị chua.)","Stomach [acid] plays a crucial role in breaking down food during digestion. (=Dịch: Axit trong dạ dày đóng một vai trò quan trọng trong việc phân hủy thức ăn khi tiêu hóa.)","You should wear protective gloves when handling concentrated [acid]. (=Dịch: Bạn nên đeo găng tay bảo hộ khi xử lý axit đậm đặc.)"],"ukAudio":"/ai_services/tts3/?q=acid&lang=en-GB&ipa=%2F%CB%88%C3%A6s.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=acid&lang=en-US&ipa=%2F%CB%88%C3%A6s.%C9%AAd%2F"},{"id":"lv_8_2","topic":"Food and Health","word":"additive","pos":"(n)","ipa":"/ˈæd.ə.t̬ɪv/","defVi":"chất phụ gia","defEn":"a substance added in small amounts to something else to improve or preserve it","examples":["Many consumers prefer organic food that contains no synthetic food [additive]. (=Dịch: Nhiều người tiêu dùng ưa chuộng thực phẩm hữu cơ không chứa phụ gia thực phẩm tổng hợp.)","The company uses a special chemical [additive] to enhance the durability of its paint. (=Dịch: Công ty sử dụng một loại phụ gia hóa học đặc biệt để nâng cao độ bền của sơn.)","A fuel [additive] can help clean engine deposits and improve mileage. (=Dịch: Chất phụ gia nhiên liệu có thể giúp làm sạch cặn động cơ và cải thiện hiệu suất tiêu hao nhiên liệu.)"],"ukAudio":"/ai_services/tts3/?q=additive&lang=en-GB&ipa=%2F%CB%88%C3%A6d.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=additive&lang=en-US&ipa=%2F%CB%88%C3%A6d.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_8_3","topic":"Food and Health","word":"aerobic","pos":"(adj)","ipa":"/eˈroʊ.bɪk/","defVi":"(thuộc) hiếu khí, thể dục nhịp điệu","defEn":"involving or improving the body's use of oxygen through exercise.","examples":["Swimming and cycling are great forms of [aerobic] exercise. (=Dịch: Bơi lội và đạp xe là những hình thức tập thể dục hiếu khí tuyệt vời.)","Regular [aerobic] activity strengthens the heart and lungs. (=Dịch: Hoạt động hiếu khí thường xuyên giúp tăng cường sức khỏe tim và phổi.)","She attends an [aerobic] dance class three times a week. (=Dịch: Cô ấy tham gia lớp học nhảy aerobic ba lần một tuần.)"],"ukAudio":"/ai_services/tts3/?q=aerobic&lang=en-GB&ipa=%2Fe%CB%88ro%CA%8A.b%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=aerobic&lang=en-US&ipa=%2Fe%CB%88ro%CA%8A.b%C9%AAk%2F"},{"id":"lv_8_4","topic":"Food and Health","word":"ambassador","pos":"(n)","ipa":"/æmˈbæs.ə.dɚ/","defVi":"đại sứ","defEn":"an official representative of a country residing in another country","examples":["The French [ambassador] met with government officials to discuss trade agreements. (=Dịch: Đại sứ Pháp đã gặp các quan chức chính phủ để thảo luận về các hiệp định thương mại.)","She was appointed as a goodwill [ambassador] for the global charity. (=Dịch: Cô được bổ nhiệm làm đại sứ thiện chí cho tổ chức từ thiện toàn cầu.)","The new [ambassador] presented his credentials to the president yesterday. (=Dịch: Vị tân đại sứ đã trình quốc thư lên tổng thống vào ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=ambassador&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C3%A6s.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ambassador&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C3%A6s.%C9%99.d%C9%9A%2F"},{"id":"lv_8_5","topic":"Food and Health","word":"artificial","pos":"(adj)","ipa":"/ˌɑːr.t̬əˈfɪʃ.əl/","defVi":"nhân tạo","defEn":"made or produced by humans rather than occurring naturally.","examples":["This beverage contains no [artificial] colors or flavors. (=Dịch: Đồ uống này không chứa phẩm màu hoặc hương liệu nhân tạo.)","The match was played on a field with [artificial] grass. (=Dịch: Trận đấu được diễn ra trên sân cỏ nhân tạo.)","Scientists are developing [artificial] organs to save patients. (=Dịch: Các nhà khoa học đang phát triển các cơ quan nhân tạo để cứu sống bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=artificial&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.t%CC%AC%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=artificial&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.t%CC%AC%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_8_6","topic":"Food and Health","word":"avocado","pos":"(n)","ipa":"/ˌæv.əˈkɑː.doʊ/","defVi":"quả bơ","defEn":"a tropical fruit with green skin, soft oily flesh, and a large seed.","examples":["She smashed an [avocado] on whole-grain toast for breakfast. (=Dịch: Cô ấy nghiền một quả bơ lên bánh mì nguyên cám cho bữa sáng.)","An [avocado] is rich in healthy fats and essential nutrients. (=Dịch: Quả bơ rất giàu chất béo lành mạnh và các chất dinh dưỡng thiết yếu.)","He added fresh slices of [avocado] to his chicken salad. (=Dịch: Anh ấy đã thêm vài lát bơ tươi vào món salad gà của mình.)"],"ukAudio":"/ai_services/tts3/?q=avocado&lang=en-GB&ipa=%2F%CB%8C%C3%A6v.%C9%99%CB%88k%C9%91%CB%90.do%CA%8A%2F","usAudio":"/ai_services/tts3/?q=avocado&lang=en-US&ipa=%2F%CB%8C%C3%A6v.%C9%99%CB%88k%C9%91%CB%90.do%CA%8A%2F"},{"id":"lv_8_7","topic":"Food and Health","word":"balanced","pos":"(adj)","ipa":"/ˈbæl.ənst/","defVi":"cân bằng, cân đối","defEn":"containing a healthy mixture of different types of things.","examples":["A [balanced] diet is essential for maintaining good physical health. (=Dịch: Một chế độ ăn uống cân bằng là điều cần thiết để duy trì sức khỏe thể chất tốt.)","She tries to lead a [balanced] life between work and family. (=Dịch: Cô ấy cố gắng duy trì một cuộc sống cân bằng giữa công việc và gia đình.)","The report provided a fair and [balanced] view of the issue. (=Dịch: Bản báo cáo đã đưa ra một cái nhìn công bằng và cân bằng về vấn đề này.)"],"ukAudio":"/ai_services/tts3/?q=balanced&lang=en-GB&ipa=%2F%CB%88b%C3%A6l.%C9%99nst%2F","usAudio":"/ai_services/tts3/?q=balanced&lang=en-US&ipa=%2F%CB%88b%C3%A6l.%C9%99nst%2F"},{"id":"lv_8_8","topic":"Food and Health","word":"bark","pos":"(n)","ipa":"/bɑrk/","defVi":"vỏ cây","defEn":"the tough outer covering of the trunk and branches of a tree","examples":["Cinnamon is a spice made from the inner [bark] of certain trees. (=Dịch: Quế là một loại gia vị được làm từ lớp vỏ bên trong của một số loài cây.)","The rough [bark] protects the tree from harsh weather and insects. (=Dịch: Lớp vỏ cây sần sùi bảo vệ cây khỏi thời tiết khắc nghiệt và côn trùng.)","Indigenous people used birch [bark] to construct lightweight canoes. (=Dịch: Người bản địa đã sử dụng vỏ cây bạch dương để đóng những chiếc thuyền nan nhẹ.)"],"ukAudio":"/ai_services/tts3/?q=bark&lang=en-GB&ipa=%2Fb%C9%91rk%2F","usAudio":"/ai_services/tts3/?q=bark&lang=en-US&ipa=%2Fb%C9%91rk%2F"},{"id":"lv_8_9","topic":"Food and Health","word":"beneficial","pos":"(adj)","ipa":"/ˌben.əˈfɪʃ.l/","defVi":"có lợi, có ích","defEn":"having a good or helpful effect on someone or something","examples":["Regular aerobic exercise is extremely [beneficial] for cardiovascular health. (=Dịch: Tập thể dục nhịp điệu thường xuyên cực kỳ có lợi cho sức khỏe tim mạch.)","Good communication skills are [beneficial] in any professional career. (=Dịch: Kỹ năng giao tiếp tốt rất có ích trong bất kỳ sự nghiệp chuyên môn nào.)","The new tax policy will be [beneficial] to small business owners. (=Dịch: Chính sách thuế mới sẽ có lợi cho các chủ doanh nghiệp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=beneficial&lang=en-GB&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.l%2F","usAudio":"/ai_services/tts3/?q=beneficial&lang=en-US&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.l%2F"},{"id":"lv_8_10","topic":"Food and Health","word":"brand","pos":"(n)","ipa":"/brænd/","defVi":"thương hiệu, nhãn hiệu","defEn":"a type of product made by a particular company under a particular name","examples":["This luxury fashion [brand] is famous for its leather handbags. (=Dịch: Thương hiệu thời trang cao cấp này nổi tiếng với những chiếc túi xách da.)","Consumers often trust a well-known [brand] more than an unfamiliar one. (=Dịch: Người tiêu dùng thường tin tưởng một thương hiệu nổi tiếng hơn một thương hiệu xa lạ.)","The company spent millions of dollars to build a strong [brand] image. (=Dịch: Công ty đã chi hàng triệu đô la để xây dựng một hình ảnh thương hiệu vững mạnh.)"],"ukAudio":"/ai_services/tts3/?q=brand&lang=en-GB&ipa=%2Fbr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=brand&lang=en-US&ipa=%2Fbr%C3%A6nd%2F"},{"id":"lv_8_11","topic":"Food and Health","word":"bulb","pos":"(n)","ipa":"/bʌlb/","defVi":"bóng đèn","defEn":"a glass device that produces light from electricity","examples":["He stood on a chair to replace the burned-out light [bulb]. (=Dịch: Anh ấy đứng lên một chiếc ghế để thay bóng đèn đã bị cháy.)","Using an energy-saving LED [bulb] helps lower household electricity bills. (=Dịch: Sử dụng bóng đèn LED tiết kiệm năng lượng giúp giảm hóa đơn tiền điện sinh hoạt.)","The lamp needs a forty-watt [bulb] to illuminate the entire desk. (=Dịch: Chiếc đèn bàn cần một bóng đèn 40 oát để chiếu sáng toàn bộ bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=bulb&lang=en-GB&ipa=%2Fb%CA%8Clb%2F","usAudio":"/ai_services/tts3/?q=bulb&lang=en-US&ipa=%2Fb%CA%8Clb%2F"},{"id":"lv_8_12","topic":"Food and Health","word":"cage","pos":"(n)","ipa":"/keɪdʒ/","defVi":"lồng, chuồng","defEn":"a structure of bars or wires in which birds or animals are kept","examples":["The parrot sat quietly on a wooden perch inside its metal [cage]. (=Dịch: Con vẹt ngồi yên lặng trên một thanh gỗ bên trong chiếc lồng kim loại.)","Animal welfare activists campaigned against keeping wild animals in a small [cage]. (=Dịch: Các nhà hoạt động vì quyền động vật đã vận động chống lại việc nhốt động vật hoang dã trong chuồng nhỏ.)","The zoo keeper carefully cleaned the lion's [cage] every morning. (=Dịch: Người quản thú cẩn thận dọn dẹp chuồng sư tử vào mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=cage&lang=en-GB&ipa=%2Fke%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=cage&lang=en-US&ipa=%2Fke%C9%AAd%CA%92%2F"},{"id":"lv_8_13","topic":"Food and Health","word":"calorie","pos":"(n)","ipa":"/ˈkæl.ɚ.i/","defVi":"calo (đơn vị đo năng lượng)","defEn":"a unit used to measure the energy value of food.","examples":["You can reduce your daily [calorie] intake by avoiding sugary drinks. (=Dịch: Bạn có thể giảm lượng calo nạp vào hàng ngày bằng cách tránh đồ uống có đường.)","Running burns more [calorie] units than walking at a casual pace. (=Dịch: Chạy bộ đốt cháy nhiều calo hơn là đi bộ với tốc độ bình thường.)","Food labels show the total [calorie] count per serving. (=Dịch: Nhãn thực phẩm hiển thị tổng lượng calo trên mỗi khẩu phần ăn.)"],"ukAudio":"/ai_services/tts3/?q=calorie&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=calorie&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%9A.i%2F"},{"id":"lv_8_14","topic":"Food and Health","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"nước Ca-na-đa (Canada)","defEn":"a large country in northern North America.","examples":["Many international students choose to study in [Canada] each year. (=Dịch: Nhiều du học sinh quốc tế chọn học tập tại Canada mỗi năm.)","Winter in [Canada] can be extremely cold with heavy snowfall. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá với tuyết rơi dày đặc.)","She traveled across [Canada] by train to enjoy the scenery. (=Dịch: Cô ấy đã đi du lịch xuyên Canada bằng tàu hỏa để thưởng ngoạn phong cảnh.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_8_15","topic":"Food and Health","word":"cap","pos":"(n)","ipa":"/kæp/","defVi":"mũ lưỡi trai, giới hạn","defEn":"A soft, flat hat with a curved part at the front, or a limit placed on something.","examples":["He wore a baseball [cap] to shield his eyes from the harsh sunlight. (=Dịch: Anh ấy đội một chiếc mũ lưỡi trai để che mắt khỏi ánh nắng chói chang.)","The government placed a strict [cap] on greenhouse gas emissions. (=Dịch: Chính phủ đã áp đặt một mức trần giới hạn nghiêm ngặt đối với lượng khí thải nhà kính.)","Don't forget to put the [cap] back on the bottle to prevent spills. (=Dịch: Đừng quên đậy nắp chai lại để tránh bị đổ.)"],"ukAudio":"/ai_services/tts3/?q=cap&lang=en-GB&ipa=%2Fk%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=cap&lang=en-US&ipa=%2Fk%C3%A6p%2F"},{"id":"lv_8_16","topic":"Food and Health","word":"carbohydrate","pos":"(n)","ipa":"/ˌkɑːr.boʊˈhaɪ.dreɪt/","defVi":"chất bột đường, tinh bột","defEn":"A substance in foods such as bread, rice, and potatoes that provides the body with heat and energy.","examples":["Athletes often consume foods rich in [carbohydrate] before running a marathon. (=Dịch: Các vận động viên thường tiêu thụ thực phẩm giàu tinh bột trước khi chạy marathon.)","Reducing your refined [carbohydrate] intake can help regulate blood sugar levels. (=Dịch: Giảm lượng tinh bột tinh chế có thể giúp điều hòa lượng đường trong máu.)","Rice, pasta, and potatoes are primary sources of [carbohydrate] in many diets. (=Dịch: Gạo, mì ống và khoai tây là những nguồn cung cấp carbohydrate chính trong nhiều chế độ ăn.)"],"ukAudio":"/ai_services/tts3/?q=carbohydrate&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90r.bo%CA%8A%CB%88ha%C9%AA.dre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=carbohydrate&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90r.bo%CA%8A%CB%88ha%C9%AA.dre%C9%AAt%2F"},{"id":"lv_8_17","topic":"Food and Health","word":"cereal","pos":"(n)","ipa":"/ˈsɪr.i.əl/","defVi":"ngũ cốc","defEn":"a grain used for food, or a breakfast food made from processed grains","examples":["He usually has a bowl of [cereal] with milk for breakfast. (=Dịch: Anh ấy thường ăn một bát ngũ cốc với sữa cho bữa sáng.)","Wheat and rice are among the most widely grown [cereal] crops in the world. (=Dịch: Lúa mì và lúa gạo là một trong những loại cây ngũ cốc được trồng rộng rãi nhất trên thế giới.)","Children often prefer sweetened [cereal] over plain oatmeal. (=Dịch: Trẻ em thường thích ngũ cốc có đường hơn yến mạch nguyên chất.)"],"ukAudio":"/ai_services/tts3/?q=cereal&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cereal&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F"},{"id":"lv_8_18","topic":"Food and Health","word":"chamber","pos":"(n)","ipa":"/ˈtʃeɪm.bɚ/","defVi":"phòng lớn, viện (nghị viện), hoặc khoang/buồng chứa","defEn":"a large room used for official meetings, or an enclosed space or cavity in a machine or organism","examples":["The senators gathered inside the council [chamber] to cast their final votes. (=Dịch: Các thượng nghị sĩ đã tập trung bên trong phòng hội đồng để bỏ những lá phiếu cuối cùng.)","Blood flows through each [chamber] of the heart in a specific sequence. (=Dịch: Máu chảy qua từng ngăn của tim theo một trình tự nhất định.)","Archaeologists discovered a hidden burial [chamber] deep within the ancient tomb. (=Dịch: Các nhà khảo cổ đã phát hiện một gian phòng chôn cất bí mật sâu bên trong lăng mộ cổ.)"],"ukAudio":"/ai_services/tts3/?q=chamber&lang=en-GB&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chamber&lang=en-US&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F"},{"id":"lv_8_19","topic":"Food and Health","word":"commercially","pos":"(adv)","ipa":"/kəˈmɝː.ʃəl.i/","defVi":"về mặt thương mại, trên quy mô thương mại","defEn":"in a way that relates to business, trade, or the making of a profit","examples":["The new drug will soon be [commercially] available in local pharmacies. (=Dịch: Loại thuốc mới sẽ sớm được bán trên thị trường tại các hiệu thuốc địa phương.)","Although critically acclaimed, the movie was not [commercially] successful. (=Dịch: Dù được giới phê bình đánh giá cao, bộ phim lại không thành công về mặt thương mại.)","The company decided to produce the solar panels [commercially] to reduce costs. (=Dịch: Công ty đã quyết định sản xuất các tấm pin mặt trời trên quy mô thương mại để giảm chi phí.)"],"ukAudio":"/ai_services/tts3/?q=commercially&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%9D%CB%90.%CA%83%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=commercially&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%9D%CB%90.%CA%83%C9%99l.i%2F"},{"id":"lv_8_20","topic":"Food and Health","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or company that tries to do better than others in a contest or business","examples":["The company lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty đã hạ giá để luôn dẫn trước đối thủ cạnh tranh chính của mình.)","Each [competitor] in the marathon was given a tracking chip. (=Dịch: Mỗi đấu thủ trong cuộc chạy marathon đều được gắn một con chip theo dõi.)","They analyzed how their [competitor] was marketing the new smartphone. (=Dịch: Họ đã phân tích cách đối thủ cạnh tranh tiếp thị chiếc điện thoại thông minh mới.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_8_21","topic":"Food and Health","word":"consumer","pos":"(n)","ipa":"/kənˈsuː.mɚ/","defVi":"người tiêu dùng","defEn":"a person who purchases goods and services for personal use","examples":["Rising fuel prices directly impact [consumer] spending across the country. (=Dịch: Giá nhiên liệu tăng ảnh hưởng trực tiếp đến mức chi tiêu của người tiêu dùng trên toàn quốc.)","The agency works to protect [consumer] rights against deceptive advertising. (=Dịch: Cơ quan này hoạt động nhằm bảo vệ quyền lợi người tiêu dùng trước các quảng cáo lừa đảo.)","Modern [consumer] habits have shifted significantly toward online shopping. (=Dịch: Thói quen của người tiêu dùng hiện đại đã chuyển dịch đáng kể sang mua sắm trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=consumer&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A%2F","usAudio":"/ai_services/tts3/?q=consumer&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A%2F"},{"id":"lv_8_22","topic":"Food and Health","word":"crisp","pos":"(n)","ipa":"/krɪsp/","defVi":"lát chiên giòn, miếng khoai tây chiên giòn","defEn":"a thin, dry, and crunchy slice of food, especially a potato chip","examples":["She grabbed a potato [crisp] from the bowl on the table. (=Dịch: Cô ấy lấy một miếng khoai tây chiên giòn từ cái bát trên bàn.)","Each [crisp] was seasoned evenly with sea salt and black pepper. (=Dịch: Mỗi lát khoai tây giòn đều được nêm đều với muối biển và tiêu đen.)","I prefer eating a vegetable [crisp] instead of regular fried snacks. (=Dịch: Tôi thích ăn một lát rau củ sấy giòn hơn là các món ăn vặt chiên thông thường.)"],"ukAudio":"/ai_services/tts3/?q=crisp&lang=en-GB&ipa=%2Fkr%C9%AAsp%2F","usAudio":"/ai_services/tts3/?q=crisp&lang=en-US&ipa=%2Fkr%C9%AAsp%2F"},{"id":"lv_8_23","topic":"Food and Health","word":"detect","pos":"(v)","ipa":"/dɪˈtɛkt/","defVi":"phát hiện, nhận ra, dò ra","defEn":"to discover or notice the presence of something, especially something difficult to see or hear","examples":["The medical test can [detect] the disease in its early stages. (=Dịch: Xét nghiệm y tế có thể phát hiện bệnh ở giai đoạn đầu.)","Smoke alarms are designed to [detect] fires before they spread. (=Dịch: Thiết bị báo khói được thiết kế để phát hiện đám cháy trước khi chúng lan rộng.)","Scientists used special instruments to [detect] tiny sound waves. (=Dịch: Các nhà khoa học đã sử dụng các dụng cụ đặc biệt để phát hiện các sóng âm thanh nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=detect&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=detect&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9Bkt%2F"},{"id":"lv_8_24","topic":"Food and Health","word":"drill","pos":"(n)","ipa":"/drɪl/","defVi":"máy khoan, mũi khoan; hoặc bài tập rèn luyện/diễn tập","defEn":"a tool or machine with a rotating cutting tip used for making holes, or an intensive training exercise","examples":["He used an electric [drill] to fix the bookshelf securely to the wall. (=Dịch: Anh ấy đã dùng một chiếc máy khoan điện để cố định giá sách vào tường một cách chắc chắn.)","The school conducts a mandatory fire [drill] at the beginning of each semester. (=Dịch: Trường học tổ chức một buổi diễn tập phòng cháy chữa cháy bắt buộc vào đầu mỗi học kỳ.)","The dentist picked up the high-speed [drill] to treat the patient's cavity. (=Dịch: Nha sĩ đã cầm chiếc máy khoan tốc độ cao để điều trị lỗ sâu răng cho bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=drill&lang=en-GB&ipa=%2Fdr%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=drill&lang=en-US&ipa=%2Fdr%C9%AAl%2F"},{"id":"lv_8_25","topic":"Food and Health","word":"equal","pos":"(adj)","ipa":"/ˈiː.kwəl/","defVi":"bình đẳng, ngang bằng, như nhau","defEn":"the same in size, amount, value, or status.","examples":["Both candidates have an [equal] chance of winning the election. (=Dịch: Cả hai ứng cử viên đều có cơ hội chiến thắng như nhau trong cuộc bầu cử.)","Men and women should receive [equal] pay for doing the same job. (=Dịch: Nam và nữ nên nhận mức lương bình đẳng khi làm cùng một công việc.)","Please divide the cake into six [equal] pieces. (=Dịch: Làm ơn hãy chia chiếc bánh thành sáu phần bằng nhau.)"],"ukAudio":"/ai_services/tts3/?q=equal&lang=en-GB&ipa=%2F%CB%88i%CB%90.kw%C9%99l%2F","usAudio":"/ai_services/tts3/?q=equal&lang=en-US&ipa=%2F%CB%88i%CB%90.kw%C9%99l%2F"},{"id":"lv_8_26","topic":"Food and Health","word":"ethical","pos":"(adj)","ipa":"/ˈeθ.ɪ.kəl/","defVi":"thuộc về đạo đức, hợp luân thường đạo lý","defEn":"relating to moral principles or conforming to accepted standards of right and wrong","examples":["The company introduced strict [ethical] guidelines to prevent unfair trade practices. (=Dịch: Công ty đã đưa ra các nguyên tắc đạo đức nghiêm ngặt nhằm ngăn chặn các hành vi thương mại không công bằng.)","Many people choose a plant-based diet for [ethical] reasons regarding animal welfare. (=Dịch: Nhiều người chọn chế độ ăn thuần thực vật vì lý do đạo đức liên quan đến quyền lợi động vật.)","Scientists face difficult [ethical] questions when conducting genetic research on humans. (=Dịch: Các nhà khoa học phải đối mặt với những câu hỏi đạo đức khó khăn khi tiến hành nghiên cứu di truyền trên người.)"],"ukAudio":"/ai_services/tts3/?q=ethical&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=ethical&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F"},{"id":"lv_8_27","topic":"Food and Health","word":"evaporate","pos":"(v)","ipa":"/ɪˈvæp.ə.reɪt/","defVi":"bốc hơi, bay hơi; tan biến","defEn":"to change from a liquid into a gas or vapor; to disappear completely","examples":["Puddles on the pavement quickly [evaporate] under the blazing afternoon sun. (=Dịch: Những vũng nước trên vỉa hè nhanh chóng bốc hơi dưới ánh nắng chói chang của buổi chiều.)","All of his initial confidence began to [evaporate] as the interview started. (=Dịch: Tất cả sự tự tin ban đầu của anh ấy bắt đầu tan biến khi buổi phỏng vấn bắt đầu.)","Boiling water will slowly [evaporate] if left uncovered on the stove. (=Dịch: Nước sôi sẽ từ từ bay hơi nếu để mở nắp trên bếp.)"],"ukAudio":"/ai_services/tts3/?q=evaporate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaporate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F"},{"id":"lv_8_28","topic":"Food and Health","word":"fashionable","pos":"(adj)","ipa":"/ˈfæʃ.ə.nə.bəl/","defVi":"hợp thời trang, thịnh hành","defEn":"Popular at a particular time, especially in clothes, style, or behavior.","examples":["She wore a [fashionable] dress to the annual company banquet. (=Dịch: Cô ấy đã mặc một chiếc váy rất hợp thời trang đến bữa tiệc thường niên của công ty.)","It has become [fashionable] to adopt a plant-based diet among young professionals. (=Dịch: Áp dụng chế độ ăn thuần thực vật đã trở nên thịnh hành trong giới trẻ đi làm.)","The city center is full of [fashionable] cafes and boutiques. (=Dịch: Trung tâm thành phố có rất nhiều quán cà phê và cửa hàng thời thượng.)"],"ukAudio":"/ai_services/tts3/?q=fashionable&lang=en-GB&ipa=%2F%CB%88f%C3%A6%CA%83.%C9%99.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fashionable&lang=en-US&ipa=%2F%CB%88f%C3%A6%CA%83.%C9%99.n%C9%99.b%C9%99l%2F"},{"id":"lv_8_29","topic":"Food and Health","word":"fifth","pos":"(adj)","ipa":"/fɪfθ/","defVi":"thứ năm (trong thứ tự)","defEn":"coming immediately after the fourth in order or position","examples":["She celebrated her [fifth] anniversary as manager of the marketing department. (=Dịch: Cô ấy đã kỷ niệm năm thứ năm làm việc với tư cách là người quản lý bộ phận tiếp thị.)","Our team finished in [fifth] place during the national science competition. (=Dịch: Đội của chúng tôi đã về đích ở vị trí thứ năm trong cuộc thi khoa học toàn quốc.)","His office is located on the [fifth] floor of the administrative building. (=Dịch: Văn phòng của ông ấy nằm ở tầng năm của tòa nhà hành chính.)"],"ukAudio":"/ai_services/tts3/?q=fifth&lang=en-GB&ipa=%2Ff%C9%AAf%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fifth&lang=en-US&ipa=%2Ff%C9%AAf%CE%B8%2F"},{"id":"lv_8_30","topic":"Food and Health","word":"flag","pos":"(n)","ipa":"/flæɡ/","defVi":"lá cờ, cờ hiệu","defEn":"a piece of cloth with a distinctive design used as a symbol, banner, or signaling device","examples":["The national [flag] was raised high at sunrise in front of the government building. (=Dịch: Quốc kỳ đã được kéo lên cao lúc bình minh trước tòa nhà chính phủ.)","Athletes proudly carried their country's [flag] during the opening ceremony. (=Dịch: Các vận động viên tự hào mang theo lá cờ của đất nước mình trong lễ khai mạc.)","A yellow [flag] on the beach warns swimmers of dangerous water conditions. (=Dịch: Lá cờ màu vàng trên bãi biển cảnh báo người bơi về điều kiện sóng nước nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=flag&lang=en-GB&ipa=%2Ffl%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=flag&lang=en-US&ipa=%2Ffl%C3%A6%C9%A1%2F"},{"id":"lv_8_31","topic":"Food and Health","word":"flavour","pos":"(n)","ipa":"/ˈfleɪ.vɚ/","defVi":"hương vị, mùi vị","defEn":"the distinctive taste of a food or drink, often combined with its smell","examples":["Adding fresh basil gives the homemade tomato sauce a delightful [flavour]. (=Dịch: Thêm húng quế tươi mang lại cho món sốt cà chua tự làm một hương vị thơm ngon tuyệt vời.)","The ice cream shop offers over twenty different [flavour] varieties including matcha and mint. (=Dịch: Quán kem cung cấp hơn hai mươi loại hương vị khác nhau bao gồm cả matcha và bạc hà.)","Slow cooking helps to lock in all the natural [flavour] of the meat and vegetables. (=Dịch: Nấu chậm giúp giữ lại toàn bộ hương vị tự nhiên của thịt và rau củ.)"],"ukAudio":"/ai_services/tts3/?q=flavour&lang=en-GB&ipa=%2F%CB%88fle%C9%AA.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=flavour&lang=en-US&ipa=%2F%CB%88fle%C9%AA.v%C9%9A%2F"},{"id":"lv_8_32","topic":"Food and Health","word":"genetic","pos":"(adj)","ipa":"/dʒəˈnet̬.ɪk/","defVi":"thuộc di truyền, thuộc gen","defEn":"Relating to the biological process of passing characteristics from parents to their children through genes.","examples":["Scientists are studying the [genetic] factors that cause certain diseases. (=Dịch: Các nhà khoa học đang nghiên cứu các yếu tố di truyền gây ra một số bệnh nhất định.)","Eye color is a [genetic] trait passed down from parents to offspring. (=Dịch: Màu mắt là một đặc điểm di truyền được truyền từ cha mẹ sang con cái.)","The research team made a breakthrough in identifying the [genetic] code of the rare plant. (=Dịch: Nhóm nghiên cứu đã tạo ra bước đột phá trong việc xác định mã di truyền của loài thực vật quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=genetic&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=genetic&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F"},{"id":"lv_8_33","topic":"Food and Health","word":"ghost","pos":"(n)","ipa":"/ɡoʊst/","defVi":"con ma, bóng ma, linh hồn","defEn":"the spirit of a dead person that a living person believes they can see or hear","examples":["The children told scary stories about a [ghost] living in the old house. (=Dịch: Lũ trẻ đã kể những câu chuyện đáng sợ về một con ma sống trong ngôi nhà cổ.)","Visitors claim that the ancient castle is haunted by the [ghost] of a king. (=Dịch: Du khách khẳng định rằng lâu đài cổ kính bị ám bởi bóng ma của một vị vua.)","He looked as pale as if he had just seen a [ghost]. (=Dịch: Anh ấy trông tái nhợt như thể vừa nhìn thấy một bóng ma.)"],"ukAudio":"/ai_services/tts3/?q=ghost&lang=en-GB&ipa=%2F%C9%A1o%CA%8Ast%2F","usAudio":"/ai_services/tts3/?q=ghost&lang=en-US&ipa=%2F%C9%A1o%CA%8Ast%2F"},{"id":"lv_8_34","topic":"Food and Health","word":"heated","pos":"(adj)","ipa":"/ˈhiː.t̬ɪd/","defVi":"được đun nóng; (cuộc tranh luận) sôi nổi, nảy lửa, gay gắt","defEn":"made warm or hot; (of an argument or discussion) full of anger and strong emotion","examples":["The committee engaged in a [heated] debate over how to allocate the annual budget. (=Dịch: Ủy ban đã tham gia vào một cuộc tranh luận gay gắt về cách phân bổ ngân sách hàng năm.)","The luxury hotel features an outdoor [heated] pool that guests can use during the winter. (=Dịch: Khách sạn sang trọng này có một bể bơi nước nóng ngoài trời mà du khách có thể sử dụng vào mùa đông.)","What began as a calm conversation quickly turned into a [heated] exchange between the rivals. (=Dịch: Những gì bắt đầu như một cuộc trò chuyện êm đẹp đã nhanh chóng biến thành màn đôi co nảy lửa giữa hai đối thủ.)"],"ukAudio":"/ai_services/tts3/?q=heated&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=heated&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AAd%2F"},{"id":"lv_8_35","topic":"Food and Health","word":"hormone","pos":"(n)","ipa":"/ˈhɔːr.moʊn/","defVi":"nội tiết tố, hoóc-môn","defEn":"a chemical substance produced in the body that controls certain processes","examples":["Insulin is an essential [hormone] that regulates blood sugar levels. (=Dịch: Insulin là một hoóc-môn thiết yếu giúp điều hòa lượng đường trong máu.)","Adrenaline is a [hormone] released when a person experiences fear or excitement. (=Dịch: Adrenaline là một nội tiết tố được tiết ra khi một người cảm thấy sợ hãi hoặc phấn khích.)","An imbalance of any [hormone] can affect your mood and energy. (=Dịch: Sự mất cân bằng của bất kỳ hoóc-môn nào cũng có thể ảnh hưởng đến tâm trạng và năng lượng của bạn.)"],"ukAudio":"/ai_services/tts3/?q=hormone&lang=en-GB&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=hormone&lang=en-US&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F"},{"id":"lv_8_36","topic":"Food and Health","word":"importantly","pos":"(adv)","ipa":"/ɪmˈpɔːr.tənt.li/","defVi":"quan trọng là, một cách quan trọng","defEn":"used to emphasize a significant point or fact","examples":["The new system is faster and, more [importantly], much more secure. (=Dịch: Hệ thống mới nhanh hơn và quan trọng hơn là bảo mật hơn nhiều.)","She has the required skills and, most [importantly], a great attitude. (=Dịch: Cô ấy có những kỹ năng cần thiết và quan trọng nhất là một thái độ tuyệt vời.)","Eating well and, [importantly], exercising regularly will keep you healthy. (=Dịch: Ăn uống đầy đủ và quan trọng là tập thể dục thường xuyên sẽ giúp bạn khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=importantly&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F","usAudio":"/ai_services/tts3/?q=importantly&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F"},{"id":"lv_8_37","topic":"Food and Health","word":"incorrect","pos":"(adj)","ipa":"/ˌɪn.kəˈrɛkt/","defVi":"sai, không chính xác","defEn":"not true or accurate; having mistakes","examples":["The report contained some [incorrect] statistics that need to be fixed. (=Dịch: Báo cáo có chứa một số số liệu thống kê không chính xác cần phải sửa lại.)","He gave an [incorrect] answer during the job interview. (=Dịch: Anh ấy đã đưa ra một câu trả lời sai trong buổi phỏng vấn xin việc.)","The system showed an error message due to an [incorrect] password. (=Dịch: Hệ thống đã hiển thị thông báo lỗi do mật khẩu không đúng.)"],"ukAudio":"/ai_services/tts3/?q=incorrect&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=incorrect&lang=en-US&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F"},{"id":"lv_8_38","topic":"Food and Health","word":"influencer","pos":"(n)","ipa":"/ˈɪn.flu.ən.sɚ/","defVi":"người có sức ảnh hưởng (trên mạng xã hội)","defEn":"a person who has the power to affect the purchasing decisions or opinions of others on social media","examples":["The brand partnered with a popular fashion [influencer] to promote their new line. (=Dịch: Thương hiệu đã hợp tác với một người có sức ảnh hưởng nổi tiếng về thời trang để quảng bá dòng sản phẩm mới của họ.)","Many young people aspire to become a social media [influencer]. (=Dịch: Nhiều người trẻ khao khát trở thành một người có sức ảnh hưởng trên mạng xã hội.)","She works as a travel [influencer] and shares videos from around the world. (=Dịch: Cô ấy làm công việc của một người có ảnh hưởng trong lĩnh vực du lịch và chia sẻ các video từ khắp nơi trên thế giới.)"],"ukAudio":"/ai_services/tts3/?q=influencer&lang=en-GB&ipa=%2F%CB%88%C9%AAn.flu.%C9%99n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=influencer&lang=en-US&ipa=%2F%CB%88%C9%AAn.flu.%C9%99n.s%C9%9A%2F"},{"id":"lv_8_39","topic":"Food and Health","word":"ingredient","pos":"(n)","ipa":"/ɪnˈɡriː.di.ənt/","defVi":"nguyên liệu, thành phần","defEn":"one of the foods or substances that are used to make a particular dish","examples":["Fresh basil is a key [ingredient] in making authentic pesto sauce. (=Dịch: Húng quế tươi là một nguyên liệu chính để làm sốt pesto chuẩn vị.)","Always check the [ingredient] list on the label before buying packaged foods. (=Dịch: Luôn kiểm tra danh sách thành phần trên nhãn trước khi mua thực phẩm đóng gói.)","Hard work and dedication are essential [ingredient] elements for achieving success. (=Dịch: Chăm chỉ và tận tụy là những yếu tố thành phần thiết yếu để đạt được thành công.)"],"ukAudio":"/ai_services/tts3/?q=ingredient&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=ingredient&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F"},{"id":"lv_8_40","topic":"Food and Health","word":"intake","pos":"(n)","ipa":"/ˈɪn.teɪk/","defVi":"lượng hấp thụ, lượng nạp vào","defEn":"The amount of a particular substance that you eat, drink, or breathe in.","examples":["Doctors advise reducing your daily salt [intake] to maintain healthy blood pressure. (=Dịch: Các bác sĩ khuyên bạn nên giảm lượng muối nạp vào hàng ngày để duy trì huyết áp ổn định.)","A high fluid [intake] is essential when exercising in hot weather. (=Dịch: Việc nạp nhiều chất lỏng là rất cần thiết khi tập luyện trong thời tiết nóng bức.)","The nutritionist evaluated my total calorie [intake] over the past week. (=Dịch: Chuyên gia dinh dưỡng đã đánh giá tổng lượng calo nạp vào của tôi trong tuần qua.)"],"ukAudio":"/ai_services/tts3/?q=intake&lang=en-GB&ipa=%2F%CB%88%C9%AAn.te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=intake&lang=en-US&ipa=%2F%CB%88%C9%AAn.te%C9%AAk%2F"},{"id":"lv_8_41","topic":"Food and Health","word":"intense","pos":"(adj)","ipa":"/ɪnˈtɛns/","defVi":"mãnh liệt, dữ dội, gay gắt","defEn":"very great in strength, degree, or emotion","examples":["The athletes trained under [intense] heat before the competition. (=Dịch: Các vận động viên đã tập luyện dưới cái nóng gay gắt trước thềm cuộc thi.)","There is [intense] competition among tech companies to attract top talent. (=Dịch: Có sự cạnh tranh khốc liệt giữa các công ty công nghệ để thu hút nhân tài hàng đầu.)","He felt [intense] pain in his shoulder after lifting the heavy box. (=Dịch: Anh ấy cảm thấy đau nhói ở vai sau khi nâng chiếc hộp nặng.)"],"ukAudio":"/ai_services/tts3/?q=intense&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=intense&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bns%2F"},{"id":"lv_8_42","topic":"Food and Health","word":"isolation","pos":"(n)","ipa":"/ˌaɪ.səˈleɪ.ʃən/","defVi":"sự cô lập, sự cách ly","defEn":"the state of being separate or alone from others","examples":["Working from home can sometimes cause feelings of loneliness and [isolation]. (=Dịch: Làm việc tại nhà đôi khi có thể gây ra cảm giác cô đơn và bị cô lập.)","The patient was placed in strict [isolation] to prevent the virus from spreading. (=Dịch: Bệnh nhân đã được đưa vào diện cách ly nghiêm ngặt để ngăn chặn virus lây lan.)","The village lived in complete geographical [isolation] during the winter months. (=Dịch: Ngôi làng sống trong sự cô lập hoàn toàn về mặt địa lý trong những tháng mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=isolation&lang=en-GB&ipa=%2F%CB%8Ca%C9%AA.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=isolation&lang=en-US&ipa=%2F%CB%8Ca%C9%AA.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_8_43","topic":"Food and Health","word":"japan","pos":"(n)","ipa":"/dʒəˈpæn/","defVi":"nước Nhật Bản","defEn":"an island country in East Asia, known for its culture and technology","examples":["Many tourists travel to [japan] in spring to see cherry blossoms. (=Dịch: Nhiều du khách đến Nhật Bản vào mùa xuân để ngắm hoa anh đào.)","She studied advanced robotics at a top university in [japan]. (=Dịch: Cô ấy đã theo học ngành robot tiên tiến tại một trường đại học hàng đầu ở Nhật Bản.)","Public transportation in [japan] is famous for its punctuality. (=Dịch: Giao thông công cộng ở Nhật Bản nổi tiếng vì sự đúng giờ.)"],"ukAudio":"/ai_services/tts3/?q=japan&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88p%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=japan&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88p%C3%A6n%2F"},{"id":"lv_8_44","topic":"Food and Health","word":"japanese","pos":"(adj)","ipa":"/ˌdʒæp.əˈniz/","defVi":"(thuộc) Nhật Bản, người Nhật hoặc tiếng Nhật","defEn":"relating to Japan, its people, language, or culture","examples":["She has a keen interest in traditional [Japanese] art and architecture. (=Dịch: Cô ấy rất quan tâm đến nghệ thuật và kiến trúc truyền thống của Nhật Bản.)","Many people enjoy eating [Japanese] food such as sushi and ramen. (=Dịch: Nhiều người thích ăn các món ăn Nhật Bản như sushi và mì ramen.)","He is currently studying the [Japanese] language at university. (=Dịch: Hiện anh ấy đang theo học tiếng Nhật tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=japanese&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C3%A6p.%C9%99%CB%88niz%2F","usAudio":"/ai_services/tts3/?q=japanese&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C3%A6p.%C9%99%CB%88niz%2F"},{"id":"lv_8_45","topic":"Food and Health","word":"journal","pos":"(n)","ipa":"/ˈdʒɝ.nəl/","defVi":"tạp chí chuyên ngành, tập san","defEn":"a newspaper or magazine that deals with a particular subject or professional activity","examples":["The scientific [journal] published the groundbreaking research on climate change. (=Dịch: Tạp chí khoa học đã công bố nghiên cứu mang tính đột phá về biến đổi khí hậu.)","He submitted his article to a peer-reviewed medical [journal]. (=Dịch: Anh ấy đã nộp bài báo của mình cho một tạp chí y khoa có bình duyệt.)","University students frequently consult academic [journals] for their thesis work. (=Dịch: Sinh viên đại học thường xuyên tham khảo các tạp chí học thuật cho luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=journal&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=journal&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D.n%C9%99l%2F"},{"id":"lv_8_46","topic":"Food and Health","word":"keratin","pos":"(n)","ipa":"/ˈker.ə.t̬ɪn/","defVi":"chất sừng, keratin","defEn":"a tough protein that forms the main component of hair, nails, and outer skin","examples":["Using hair products with [keratin] can help repair damaged strands. (=Dịch: Sử dụng các sản phẩm chăm sóc tóc có chứa keratin có thể giúp phục hồi những sợi tóc hư tổn.)","Human nails and hair are primarily composed of [keratin]. (=Dịch: Móng tay và tóc của con người chủ yếu được cấu tạo từ chất sừng.)","The outer layer of skin contains [keratin] to protect the body from moisture loss. (=Dịch: Lớp ngoài của da chứa keratin để bảo vệ cơ thể khỏi bị mất nước.)"],"ukAudio":"/ai_services/tts3/?q=keratin&lang=en-GB&ipa=%2F%CB%88ker.%C9%99.t%CC%AC%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=keratin&lang=en-US&ipa=%2F%CB%88ker.%C9%99.t%CC%AC%C9%AAn%2F"},{"id":"lv_8_47","topic":"Food and Health","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water turns from a [liquid] into ice at zero degrees Celsius. (=Dịch: Nước chuyển từ thể lỏng sang băng ở không độ C.)","You should drink plenty of [liquid] when you have a high fever. (=Dịch: Bạn nên uống nhiều chất lỏng khi bị sốt cao.)","Keep hazardous chemical [liquid] away from young children. (=Dịch: Để chất lỏng hóa chất nguy hiểm tránh xa tầm tay trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_8_48","topic":"Food and Health","word":"literacy","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.si/","defVi":"sự biết chữ, trình độ hiểu biết","defEn":"the ability to read and write, or knowledge in a particular subject","examples":["The government launched a campaign to improve adult [literacy] in rural areas. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao tỷ lệ biết chữ ở người lớn tại các vùng nông thôn.)","Financial [literacy] is an essential skill for managing personal savings. (=Dịch: Hiểu biết về tài chính là một kỹ năng thiết yếu để quản lý tiền tiết kiệm cá nhân.)","Digital [literacy] has become necessary for finding good jobs today. (=Dịch: Hiểu biết về công nghệ số đã trở nên cần thiết để tìm kiếm việc làm tốt hiện nay.)"],"ukAudio":"/ai_services/tts3/?q=literacy&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.si%2F","usAudio":"/ai_services/tts3/?q=literacy&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.si%2F"},{"id":"lv_8_49","topic":"Food and Health","word":"litre","pos":"(n)","ipa":"/ˈli.t̬ɚ/","defVi":"lít (đơn vị đo thể tích)","defEn":"a metric unit of capacity, equal to 1,000 cubic centimeters","examples":["Doctors recommend drinking at least two [litres] of water every day. (=Dịch: Các bác sĩ khuyên nên uống ít nhất hai lít nước mỗi ngày.)","The car's fuel tank can hold up to fifty [litres] of gasoline. (=Dịch: Bình xăng của xe có thể chứa tới năm mươi lít xăng.)","She poured a [litre] of milk into the large mixing bowl. (=Dịch: Cô ấy đổ một lít sữa vào chiếc bát trộn lớn.)"],"ukAudio":"/ai_services/tts3/?q=litre&lang=en-GB&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litre&lang=en-US&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F"},{"id":"lv_8_50","topic":"Food and Health","word":"lower","pos":"(v)","ipa":"/ˈloʊ.ər/","defVi":"làm giảm, hạ thấp","defEn":"To reduce something in amount, degree, or value.","examples":["Regular physical exercise can help [lower] your cholesterol levels. (=Dịch: Tập thể dục thường xuyên có thể giúp làm giảm mức cholesterol của bạn.)","The government decided to [lower] taxes to stimulate economic growth. (=Dịch: Chính phủ đã quyết định hạ thuế nhằm thúc đẩy tăng trưởng kinh tế.)","You should [lower] your voice when speaking in the library. (=Dịch: Bạn nên hạ nhỏ giọng khi nói chuyện trong thư viện.)"],"ukAudio":"/ai_services/tts3/?q=lower&lang=en-GB&ipa=%2F%CB%88lo%CA%8A.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=lower&lang=en-US&ipa=%2F%CB%88lo%CA%8A.%C9%99r%2F"},{"id":"lv_8_51","topic":"Food and Health","word":"maple","pos":"(n)","ipa":"/ˈmeɪ.pəl/","defVi":"cây phong","defEn":"a tree grown in northern regions that typically has lobed leaves and produces syrup","examples":["The leaves of the [maple] tree turn bright red and orange in autumn. (=Dịch: Lá cây phong chuyển sang màu đỏ và cam rực rỡ vào mùa thu.)","A red [maple] leaf is featured on the national flag of Canada. (=Dịch: Một chiếc lá phong đỏ được thể hiện trên quốc kỳ của Canada.)","The dining table was made of solid [maple] wood. (=Dịch: Bàn ăn được làm bằng gỗ phong nguyên khối.)"],"ukAudio":"/ai_services/tts3/?q=maple&lang=en-GB&ipa=%2F%CB%88me%C9%AA.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=maple&lang=en-US&ipa=%2F%CB%88me%C9%AA.p%C9%99l%2F"},{"id":"lv_8_52","topic":"Food and Health","word":"monosodium glutamate","pos":"(n)","ipa":"/ˌmɑː.noʊˌsoʊ.di.əm ˈɡluː.t̬ə.meɪt/","defVi":"mì chính, bột ngọt (bột điều vị)","defEn":"a white crystalline substance used as a flavor enhancer in cooking (MSG)","examples":["Some people believe that [monosodium glutamate] causes headaches, although evidence is mixed. (=Dịch: Một số người tin rằng mì chính gây đau đầu, mặc dù các bằng chứng còn trái chiều.)","The chef added a pinch of [monosodium glutamate] to enhance the savory flavor of the soup. (=Dịch: Đầu bếp đã thêm một nhúm mì chính để tăng thêm hương vị đậm đà cho món súp.)","Packaged snack foods often contain [monosodium glutamate] to improve taste. (=Dịch: Thực phẩm ăn liền đóng gói thường chứa bột ngọt để cải thiện mùi vị.)"],"ukAudio":"/ai_services/tts3/?q=monosodium+glutamate&lang=en-GB&ipa=%2F%CB%8Cm%C9%91%CB%90.no%CA%8A%CB%8Cso%CA%8A.di.%C9%99m+%CB%88%C9%A1lu%CB%90.t%CC%AC%C9%99.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=monosodium+glutamate&lang=en-US&ipa=%2F%CB%8Cm%C9%91%CB%90.no%CA%8A%CB%8Cso%CA%8A.di.%C9%99m+%CB%88%C9%A1lu%CB%90.t%CC%AC%C9%99.me%C9%AAt%2F"},{"id":"lv_8_53","topic":"Food and Health","word":"motivation","pos":"(n)","ipa":"/ˌmoʊ.t̬əˈveɪ.ʃən/","defVi":"động lực","defEn":"the reason or desire that makes someone want to do something","examples":["High salaries can serve as strong [motivation] for employees to work harder. (=Dịch: Mức lương cao có thể là động lực mạnh mẽ để nhân viên làm việc chăm chỉ hơn.)","She lost the [motivation] to study after failing the exam twice. (=Dịch: Cô ấy mất động lực học tập sau khi trượt kỳ thi hai lần.)","Setting clear goals provides the [motivation] needed to achieve success. (=Dịch: Việc đặt ra mục tiêu rõ ràng sẽ cung cấp động lực cần thiết để đạt được thành công.)"],"ukAudio":"/ai_services/tts3/?q=motivation&lang=en-GB&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motivation&lang=en-US&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_8_54","topic":"Food and Health","word":"norway","pos":"(n)","ipa":"/ˈnɔːr.weɪ/","defVi":"Na Uy","defEn":"a Scandinavian country in Northern Europe known for its fjords and mountains","examples":["Many tourists travel to [Norway] to see the spectacular northern lights. (=Dịch: Nhiều du khách đến Na Uy để ngắm hiện tượng cực quang ngoạn mục.)","Salmon farming is a major export industry in [Norway]. (=Dịch: Nuôi cá hồi là một ngành xuất khẩu lớn ở Na Uy.)","She spent two weeks hiking along the famous fjords of [Norway]. (=Dịch: Cô ấy đã dành hai tuần đi bộ dọc theo những vịnh hẹp nổi tiếng của Na Uy.)"],"ukAudio":"/ai_services/tts3/?q=norway&lang=en-GB&ipa=%2F%CB%88n%C9%94%CB%90r.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=norway&lang=en-US&ipa=%2F%CB%88n%C9%94%CB%90r.we%C9%AA%2F"},{"id":"lv_8_55","topic":"Food and Health","word":"norwegian","pos":"(adj)","ipa":"/nɔːrˈwiː.dʒən/","defVi":"(thuộc) Na Uy, người Na Uy, tiếng Na Uy","defEn":"relating to Norway, its people, or its language","examples":["She loves exploring the dramatic landscapes of the [Norwegian] fjords. (=Dịch: Cô ấy thích khám phá những cảnh quan ấn tượng của các vịnh hẹp Na Uy.)","The company recently hired a [Norwegian] architect to design the headquarters. (=Dịch: Công ty gần đây đã thuê một kiến trúc sư người Na Uy để thiết kế trụ sở chính.)","He is studying [Norwegian] literature at the university. (=Dịch: Anh ấy đang nghiên cứu văn học Na Uy tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=norwegian&lang=en-GB&ipa=%2Fn%C9%94%CB%90r%CB%88wi%CB%90.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=norwegian&lang=en-US&ipa=%2Fn%C9%94%CB%90r%CB%88wi%CB%90.d%CA%92%C9%99n%2F"},{"id":"lv_8_56","topic":"Food and Health","word":"nutrient","pos":"(n)","ipa":"/ˈnuː.tri.ənt/","defVi":"chất dinh dưỡng","defEn":"A substance that plants or animals need in order to live and grow.","examples":["Fresh fruits and vegetables are packed with every essential [nutrient]. (=Dịch: Rau củ và trái cây tươi chứa đầy đủ mọi chất dinh dưỡng thiết yếu.)","Overcooking vegetables can destroy a vital [nutrient] like vitamin C. (=Dịch: Nấu rau củ quá chín có thể làm mất đi các chất dinh dưỡng quan trọng như vitamin C.)","Plants absorb water and [nutrient] compounds directly from the soil. (=Dịch: Cây cối hấp thụ nước và các hợp chất dinh dưỡng trực tiếp từ đất.)"],"ukAudio":"/ai_services/tts3/?q=nutrient&lang=en-GB&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=nutrient&lang=en-US&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F"},{"id":"lv_8_57","topic":"Food and Health","word":"nutritional","pos":"(adj)","ipa":"/nuːˈtrɪ.ʃən.l/","defVi":"thuộc về dinh dưỡng","defEn":"relating to the substances in food that help you stay healthy and grow","examples":["It is important to check the [nutritional] value on food labels. (=Dịch: Việc kiểm tra giá trị dinh dưỡng trên nhãn thực phẩm là rất quan trọng.)","Children need a diet with high [nutritional] quality for healthy growth. (=Dịch: Trẻ em cần một chế độ ăn có chất lượng dinh dưỡng cao để phát triển khỏe mạnh.)","Fast food often lacks essential [nutritional] elements. (=Dịch: Thức ăn nhanh thường thiếu các yếu tố dinh dưỡng thiết yếu.)"],"ukAudio":"/ai_services/tts3/?q=nutritional&lang=en-GB&ipa=%2Fnu%CB%90%CB%88tr%C9%AA.%CA%83%C9%99n.l%2F","usAudio":"/ai_services/tts3/?q=nutritional&lang=en-US&ipa=%2Fnu%CB%90%CB%88tr%C9%AA.%CA%83%C9%99n.l%2F"},{"id":"lv_8_58","topic":"Food and Health","word":"obesity","pos":"(n)","ipa":"/oʊˈbiː.sə.t̬i/","defVi":"bệnh béo phì, tình trạng béo phì","defEn":"the condition of being extremely overweight in a way that is dangerous for health","examples":["Childhood [obesity] is becoming a serious public health issue worldwide. (=Dịch: Béo phì ở trẻ em đang trở thành một vấn đề sức khỏe cộng đồng nghiêm trọng trên toàn thế giới.)","Regular exercise and a balanced diet can help prevent [obesity]. (=Dịch: Tập thể dục thường xuyên và chế độ ăn cân bằng có thể giúp ngăn ngừa béo phì.)","The government launched a campaign to raise awareness about the risks of [obesity]. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao nhận thức về những nguy cơ của bệnh béo phì.)"],"ukAudio":"/ai_services/tts3/?q=obesity&lang=en-GB&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=obesity&lang=en-US&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_8_59","topic":"Food and Health","word":"package","pos":"(n)","ipa":"/ˈpæk.ɪdʒ/","defVi":"bưu kiện, gói hàng; gói (dịch vụ, sản phẩm)","defEn":"an object or collection of objects wrapped in paper or packed in a box","examples":["The delivery driver left a large [package] on the front porch. (=Dịch: Tài xế giao hàng đã để lại một gói hàng lớn ở hiên trước.)","The hotel offers an attractive vacation [package] for families. (=Dịch: Khách sạn cung cấp một gói kỳ nghỉ hấp dẫn dành cho các gia đình.)","Please handle this fragile [package] with extra care. (=Dịch: Xin vui lòng xử lý gói hàng dễ vỡ này một cách thật cẩn thận.)"],"ukAudio":"/ai_services/tts3/?q=package&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=package&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F"},{"id":"lv_8_60","topic":"Food and Health","word":"packaging","pos":"(n)","ipa":"/ˈpæk.ɪ.dʒɪŋ/","defVi":"bao bì, quy cách đóng gói","defEn":"materials used to wrap or protect goods for sale or transport","examples":["Eco-friendly [packaging] helps companies reduce plastic waste significantly. (=Dịch: Bao bì thân thiện với môi trường giúp các công ty giảm thiểu đáng kể rác thải nhựa.)","The attractive [packaging] caught the customer's attention immediately. (=Dịch: Bao bì bắt mắt đã ngay lập tức thu hút sự chú ý của khách hàng.)","Excessive [packaging] should be avoided to protect the environment. (=Dịch: Nên tránh việc đóng gói quá mức để bảo vệ môi trường.)"],"ukAudio":"/ai_services/tts3/?q=packaging&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=packaging&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_8_61","topic":"Food and Health","word":"pan","pos":"(n)","ipa":"/pæn/","defVi":"chảo","defEn":"a flat metal container with a handle, used for cooking food in","examples":["Heat some oil in a frying [pan] over medium heat. (=Dịch: Đun nóng một ít dầu trong chảo rán trên lửa vừa.)","He forgot the [pan] on the stove and burnt the vegetables. (=Dịch: Anh ấy để quên chiếc chảo trên bếp và làm cháy rau củ.)","Make sure to clean the non-stick [pan] with a soft sponge. (=Dịch: Hãy nhớ rửa chiếc chảo chống dính bằng một miếng bọt biển mềm.)"],"ukAudio":"/ai_services/tts3/?q=pan&lang=en-GB&ipa=%2Fp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=pan&lang=en-US&ipa=%2Fp%C3%A6n%2F"},{"id":"lv_8_62","topic":"Food and Health","word":"paste","pos":"(n)","ipa":"/peɪst/","defVi":"hỗn hợp sệt, bột nhão, hồ dán","defEn":"a thick, soft, moist substance made by mixing crushed ingredients or chemicals","examples":["Grind the garlic and ginger into a smooth [paste]. (=Dịch: Nghiền tỏi và gừng thành một hỗn hợp nhuyễn mịn.)","Apply a small amount of whitening [paste] to your teeth. (=Dịch: Thoa một lượng nhỏ kem làm trắng lên răng của bạn.)","The recipe requires two tablespoons of tomato [paste]. (=Dịch: Công thức nấu ăn yêu cầu hai thìa canh sốt cà chua đặc sệt.)"],"ukAudio":"/ai_services/tts3/?q=paste&lang=en-GB&ipa=%2Fpe%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=paste&lang=en-US&ipa=%2Fpe%C9%AAst%2F"},{"id":"lv_8_63","topic":"Food and Health","word":"percentage","pos":"(n)","ipa":"/pɚˈsɛn.tɪdʒ/","defVi":"tỷ lệ phần trăm","defEn":"an amount, number, or rate considered as a part of every 100","examples":["A high [percentage] of students passed the final exam with top marks. (=Dịch: Một tỷ lệ phần trăm lớn học sinh đã vượt qua kỳ thi cuối kỳ với điểm số cao.)","The chart shows the [percentage] of household income spent on food. (=Dịch: Biểu đồ thể hiện tỷ lệ phần trăm thu nhập hộ gia đình dành cho thực phẩm.)","Only a small [percentage] of the budget was allocated to advertising. (=Dịch: Chỉ một tỷ lệ phần trăm nhỏ trong ngân sách được phân bổ cho quảng cáo.)"],"ukAudio":"/ai_services/tts3/?q=percentage&lang=en-GB&ipa=%2Fp%C9%9A%CB%88s%C9%9Bn.t%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=percentage&lang=en-US&ipa=%2Fp%C9%9A%CB%88s%C9%9Bn.t%C9%AAd%CA%92%2F"},{"id":"lv_8_64","topic":"Food and Health","word":"pizza","pos":"(n)","ipa":"/ˈpiːt.sə/","defVi":"bánh pizza","defEn":"a flat, round bread base topped with cheese, tomato sauce, and other ingredients","examples":["We ordered a large cheese [pizza] for dinner. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza phô mai cỡ lớn cho bữa tối.)","Making homemade [pizza] is a fun activity for children. (=Dịch: Tự làm pizza tại nhà là một hoạt động thú vị cho trẻ em.)","He loves to top his [pizza] with mushrooms and olives. (=Dịch: Anh ấy thích rắc thêm nấm và ô liu lên trên chiếc pizza của mình.)"],"ukAudio":"/ai_services/tts3/?q=pizza&lang=en-GB&ipa=%2F%CB%88pi%CB%90t.s%C9%99%2F","usAudio":"/ai_services/tts3/?q=pizza&lang=en-US&ipa=%2F%CB%88pi%CB%90t.s%C9%99%2F"},{"id":"lv_8_65","topic":"Food and Health","word":"popularity","pos":"(n)","ipa":"/ˌpɑː.pjəˈler.ə.t̬i/","defVi":"sự phổ biến, sự ưa chuộng","defEn":"the state or condition of being liked, admired, or supported by many people","examples":["The sudden [popularity] of electric scooters has caused traffic issues in urban areas. (=Dịch: Sự phổ biến bất ngờ của xe trượt điện đã gây ra các vấn đề giao thông ở các khu vực đô thị.)","The band gained huge [popularity] after releasing their first studio album. (=Dịch: Ban nhạc đã đạt được sự yêu mến nồng nhiệt sau khi phát hành album phòng thu đầu tay.)","Social media platforms constantly compete for [popularity] among young users. (=Dịch: Các nền tảng mạng xã hội liên tục cạnh tranh để giành được sự ưa chuộng từ người dùng trẻ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=popularity&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=popularity&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F"},{"id":"lv_8_66","topic":"Food and Health","word":"pour","pos":"(v)","ipa":"/pɔːr/","defVi":"rót, đổ","defEn":"to make a liquid or other substance flow steadily out of a container","examples":["Please [pour] some fresh milk into my coffee cup. (=Dịch: Xin vui lòng rót một ít sữa tươi vào tách cà phê của tôi.)","Dark clouds gathered, and heavy rain began to [pour] down. (=Dịch: Mây đen kéo đến và mưa lớn bắt đầu trút xuống.)","Carefully [pour] the mixture into the baking pan before placing it in the oven. (=Dịch: Cẩn thận đổ hỗn hợp vào khuôn nướng trước khi cho vào lò.)"],"ukAudio":"/ai_services/tts3/?q=pour&lang=en-GB&ipa=%2Fp%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=pour&lang=en-US&ipa=%2Fp%C9%94%CB%90r%2F"},{"id":"lv_8_67","topic":"Food and Health","word":"producer","pos":"(n)","ipa":"/prəˈduː.sɚ/","defVi":"nhà sản xuất","defEn":"a person or company that makes goods, or someone who oversees the making of a film, play, or record","examples":["Vietnam is a major coffee [producer] in the global market. (=Dịch: Việt Nam là một nhà sản xuất cà phê lớn trên thị trường toàn cầu.)","The film [producer] secured the funding needed to start shooting the movie. (=Dịch: Nhà sản xuất phim đã đảm bảo được nguồn kinh phí cần thiết để bắt đầu bấm máy.)","Local [producers] are encouraged to sell their organic vegetables at the market. (=Dịch: Các nhà sản xuất địa phương được khuyến khích bán rau hữu cơ của họ tại chợ.)"],"ukAudio":"/ai_services/tts3/?q=producer&lang=en-GB&ipa=%2Fpr%C9%99%CB%88du%CB%90.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=producer&lang=en-US&ipa=%2Fpr%C9%99%CB%88du%CB%90.s%C9%9A%2F"},{"id":"lv_8_68","topic":"Food and Health","word":"protein","pos":"(n)","ipa":"/ˈproʊ.tiːn/","defVi":"chất đạm, protein","defEn":"A substance found in meat, eggs, and beans that is necessary for the body to grow and repair itself.","examples":["Eggs and chicken breast are excellent sources of lean [protein]. (=Dịch: Trứng và ức gà là nguồn cung cấp chất đạm nạc tuyệt vời.)","Bodybuilders need a significant amount of [protein] to build muscle mass. (=Dịch: Những người tập thể hình cần một lượng lớn protein để phát triển cơ bắp.)","Beans and lentils provide essential [protein] for individuals following a vegetarian diet. (=Dịch: Đậu và đậu lăng cung cấp nguồn chất đạm thiết yếu cho những người theo chế độ ăn chay.)"],"ukAudio":"/ai_services/tts3/?q=protein&lang=en-GB&ipa=%2F%CB%88pro%CA%8A.ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=protein&lang=en-US&ipa=%2F%CB%88pro%CA%8A.ti%CB%90n%2F"},{"id":"lv_8_69","topic":"Food and Health","word":"reuse","pos":"(v)","ipa":"/ˌriːˈjuːz/","defVi":"tái sử dụng","defEn":"to use something again instead of throwing it away","examples":["You can [reuse] glass jars to store spices and herbs. (=Dịch: Bạn có thể tái sử dụng các lọ thủy tinh để đựng gia vị và thảo mộc.)","The school encourages students to [reuse] plastic bottles for craft projects. (=Dịch: Trường học khuyến khích học sinh tái sử dụng chai nhựa cho các dự án thủ công.)","We should [reuse] shopping bags to reduce plastic waste. (=Dịch: Chúng ta nên tái sử dụng túi mua sắm để giảm rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=reuse&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88ju%CB%90z%2F","usAudio":"/ai_services/tts3/?q=reuse&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88ju%CB%90z%2F"},{"id":"lv_8_70","topic":"Food and Health","word":"sap","pos":"(n)","ipa":"/sæp/","defVi":"nhựa cây","defEn":"the liquid that carries food and water through plants and trees","examples":["Maple syrup is made by boiling down the clear [sap] of maple trees. (=Dịch: Siro phong được làm bằng cách đun cạn nhựa trong suốt của cây phong.)","In spring, the [sap] begins to rise in the branches as new leaves grow. (=Dịch: Vào mùa xuân, nhựa cây bắt đầu dâng lên trong các cành khi lá mới mọc.)","Sticky [sap] dripped onto the car from the pine tree above. (=Dịch: Nhựa cây dính nhớp đã nhỏ xuống xe từ cây thông phía trên.)"],"ukAudio":"/ai_services/tts3/?q=sap&lang=en-GB&ipa=%2Fs%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=sap&lang=en-US&ipa=%2Fs%C3%A6p%2F"},{"id":"lv_8_71","topic":"Food and Health","word":"seafood","pos":"(n)","ipa":"/ˈsiːˌfuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, such as fish and shellfish","examples":["Coastal cities are famous for their fresh and delicious [seafood]. (=Dịch: Các thành phố ven biển nổi tiếng với nguồn hải sản tươi ngon.)","He cannot eat crab because he is allergic to [seafood]. (=Dịch: Anh ấy không thể ăn cua vì bị dị ứng với hải sản.)","The local restaurant serves a wide variety of grilled [seafood]. (=Dịch: Nhà hàng địa phương phục vụ nhiều loại hải sản nướng đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90%CB%8Cfu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90%CB%8Cfu%CB%90d%2F"},{"id":"lv_8_72","topic":"Food and Health","word":"sensor","pos":"(n)","ipa":"/ˈsɛn.sɚ/","defVi":"cảm biến, thiết bị cảm ứng","defEn":"a device that detects and responds to physical changes such as light, heat, or movement","examples":["The automated doors open when a motion [sensor] detects someone approaching. (=Dịch: Cửa tự động sẽ mở ra khi cảm biến chuyển động nhận diện có người đang tiến lại gần.)","Modern smartphones use an optical [sensor] to adjust screen brightness. (=Dịch: Điện thoại thông minh hiện đại sử dụng cảm biến quang học để điều chỉnh độ sáng màn hình.)","The security system is triggered whenever an infrared [sensor] is activated. (=Dịch: Hệ thống an ninh sẽ được kích hoạt bất cứ khi nào cảm biến hồng ngoại nhận tín hiệu.)"],"ukAudio":"/ai_services/tts3/?q=sensor&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sensor&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.s%C9%9A%2F"},{"id":"lv_8_73","topic":"Food and Health","word":"shaft","pos":"(n)","ipa":"/ʃæft/","defVi":"trục (máy móc); đường hầm/giếng đứng (mỏ, thang máy)","defEn":"a long, narrow vertical or sloping passage, or a rotating rod in an engine","examples":["The rescue team descended into the mine [shaft] to look for survivors. (=Dịch: Đội cứu hộ đã đi xuống giếng mỏ để tìm kiếm những người sống sót.)","A broken drive [shaft] caused the car to stop suddenly on the highway. (=Dịch: Trục truyền động bị gãy khiến chiếc xe đột ngột dừng lại trên đường cao tốc.)","A [shaft] of sunlight broke through the dark storm clouds. (=Dịch: Một tia nắng mặt trời đã xuyên qua những đám mây bão đen kịt.)"],"ukAudio":"/ai_services/tts3/?q=shaft&lang=en-GB&ipa=%2F%CA%83%C3%A6ft%2F","usAudio":"/ai_services/tts3/?q=shaft&lang=en-US&ipa=%2F%CA%83%C3%A6ft%2F"},{"id":"lv_8_74","topic":"Food and Health","word":"signal","pos":"(n)","ipa":"/ˈsɪɡ.nəl/","defVi":"tín hiệu, dấu hiệu","defEn":"an action, sound, or light used to give information or convey an instruction","examples":["A red traffic [signal] indicates that all approaching vehicles must stop. (=Dịch: Đèn tín hiệu giao thông màu đỏ báo hiệu rằng tất cả các phương tiện đang tới đều phải dừng lại.)","The strong economic data was a positive [signal] for potential investors. (=Dịch: Dữ liệu kinh tế khởi sắc là một tín hiệu tích cực đối với các nhà đầu tư tiềm năng.)","My phone cannot detect any network [signal] inside this underground tunnel. (=Dịch: Điện thoại của tôi không thể bắt được bất kỳ tín hiệu mạng nào bên trong đường hầm này.)"],"ukAudio":"/ai_services/tts3/?q=signal&lang=en-GB&ipa=%2F%CB%88s%C9%AA%C9%A1.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=signal&lang=en-US&ipa=%2F%CB%88s%C9%AA%C9%A1.n%C9%99l%2F"},{"id":"lv_8_75","topic":"Food and Health","word":"sodium","pos":"(n)","ipa":"/ˈsoʊ.di.əm/","defVi":"natri","defEn":"a soft, silver-white chemical element found especially in salt","examples":["A diet high in [sodium] can lead to high blood pressure. (=Dịch: Chế độ ăn nhiều natri có thể dẫn đến bệnh cao huyết áp.)","Doctors advise reducing your daily intake of [sodium] to protect your heart. (=Dịch: Các bác sĩ khuyên nên giảm lượng natri nạp vào hàng ngày để bảo vệ tim mạch.)","The nutrition label shows how much [sodium] each serving contains. (=Dịch: Nhãn dinh dưỡng cho biết lượng natri chứa trong mỗi khẩu phần ăn.)"],"ukAudio":"/ai_services/tts3/?q=sodium&lang=en-GB&ipa=%2F%CB%88so%CA%8A.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=sodium&lang=en-US&ipa=%2F%CB%88so%CA%8A.di.%C9%99m%2F"},{"id":"lv_8_76","topic":"Food and Health","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị (từ thực vật)","defEn":"a substance made from plants used to add flavor to food.","examples":["Cinnamon is a popular [spice] used in baking. (=Dịch: Quế là một loại gia vị phổ biến được sử dụng trong làm bánh.)","Adding too much [spice] can overpower the taste of the soup. (=Dịch: Cho quá nhiều gia vị có thể làm lấn át hương vị của món súp.)","The local market sells a wide variety of fresh [spice] options. (=Dịch: Khu chợ địa phương bán rất nhiều loại gia vị tươi đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_8_77","topic":"Food and Health","word":"steam","pos":"(n)","ipa":"/stim/","defVi":"hơi nước","defEn":"the hot gas that is produced when water boils","examples":["Clouds of [steam] rose from the hot springs in the morning chill. (=Dịch: Những làn hơi nước bốc lên từ suối nước nóng trong cái lạnh buổi sáng.)","The old train was powered by a massive [steam] engine. (=Dịch: Đoàn tàu cũ được vận hành bằng một động cơ hơi nước khổng lồ.)","Be careful when opening the pot because the hot [steam] can burn you. (=Dịch: Hãy cẩn thận khi mở nắp nồi vì hơi nước nóng có thể làm bạn bị bỏng.)"],"ukAudio":"/ai_services/tts3/?q=steam&lang=en-GB&ipa=%2Fstim%2F","usAudio":"/ai_services/tts3/?q=steam&lang=en-US&ipa=%2Fstim%2F"},{"id":"lv_8_78","topic":"Food and Health","word":"strand","pos":"(v)","ipa":"/strænd/","defVi":"làm mắc kẹt, làm cho rơi vào thế bơ vơ","defEn":"to leave someone in a difficult situation or place without the means to move or leave","examples":["A severe blizzard threatened to [strand] hundreds of drivers on the highway. (=Dịch: Trận bão tuyết dữ dội có nguy cơ làm hàng trăm tài xế mắc kẹt trên đường cao tốc.)","The cancelled flight will [strand] passengers at the airport overnight. (=Dịch: Chuyến bay bị hủy sẽ khiến các hành khách phải kẹt lại ở sân bay qua đêm.)","Rising floodwaters can easily [strand] residents in low-lying villages. (=Dịch: Nước lũ dâng cao có thể dễ dàng cô lập và làm mắc kẹt người dân ở các ngôi làng trũng thấp.)"],"ukAudio":"/ai_services/tts3/?q=strand&lang=en-GB&ipa=%2Fstr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=strand&lang=en-US&ipa=%2Fstr%C3%A6nd%2F"},{"id":"lv_8_79","topic":"Food and Health","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng bổ sung","defEn":"something added to make up for a lack or extend an existing thing","examples":["The doctor advised her to take a daily vitamin D [supplement]. (=Dịch: Bác sĩ khuyên cô nên bổ sung vitamin D hàng ngày.)","He takes a protein [supplement] after each workout session to build muscle. (=Dịch: Anh ấy dùng thực phẩm bổ sung protein sau mỗi buổi tập để phát triển cơ bắp.)","The travel guide includes a map [supplement] at the back. (=Dịch: Cuốn sách hướng dẫn du lịch bao gồm một phần bản đồ bổ sung ở phía sau.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_8_80","topic":"Food and Health","word":"swedish","pos":"(adj)","ipa":"/ˈswi.dɪʃ/","defVi":"thuộc Thụy Điển","defEn":"relating to Sweden, its people, or its language","examples":["The minimalist furniture was designed by a famous [Swedish] architect. (=Dịch: Món đồ nội thất tối giản được thiết kế bởi một kiến trúc sư người Thụy Điển nổi tiếng.)","She is learning the [Swedish] language before moving to Stockholm. (=Dịch: Cô ấy đang học tiếng Thụy Điển trước khi chuyển đến Stockholm.)","The restaurant specializes in traditional [Swedish] meatballs and pastries. (=Dịch: Nhà hàng chuyên phục vụ món thịt viên và bánh ngọt truyền thống của Thụy Điển.)"],"ukAudio":"/ai_services/tts3/?q=swedish&lang=en-GB&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=swedish&lang=en-US&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F"},{"id":"lv_8_81","topic":"Food and Health","word":"sweetener","pos":"(n)","ipa":"/ˈswiːt.nɚ/","defVi":"chất làm ngọt, đường nhân tạo","defEn":"a substance added to food or drink to make it taste sweet","examples":["Artificial [sweetener] is commonly used in diet soft drinks. (=Dịch: Chất làm ngọt nhân tạo thường được sử dụng trong các loại nước ngọt ăn kiêng.)","Honey is a popular natural [sweetener] used in baking. (=Dịch: Mật ong là một chất làm ngọt tự nhiên phổ biến được dùng trong làm bánh.)","She prefers using a low-calorie [sweetener] in her morning coffee. (=Dịch: Cô ấy thích sử dụng chất làm ngọt ít calo trong cà phê buổi sáng của mình.)"],"ukAudio":"/ai_services/tts3/?q=sweetener&lang=en-GB&ipa=%2F%CB%88swi%CB%90t.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sweetener&lang=en-US&ipa=%2F%CB%88swi%CB%90t.n%C9%9A%2F"},{"id":"lv_8_82","topic":"Food and Health","word":"syrup","pos":"(n)","ipa":"/ˈsɪr.əp/","defVi":"xi-rô, nước đường đặc","defEn":"a thick, sweet liquid made by dissolving sugar in water, often flavored or used as medicine","examples":["He poured sweet maple [syrup] over his morning pancakes. (=Dịch: Anh ấy rưới xi-rô cây phong ngọt ngào lên những chiếc bánh kếp buổi sáng.)","The doctor prescribed a cough [syrup] to soothe her sore throat. (=Dịch: Bác sĩ đã kê một loại si-rô ho để làm dịu cơn đau họng của cô ấy.)","This dessert is soaked in a fragrant lemon [syrup]. (=Dịch: Món tráng miệng này được ngâm trong một lớp xi-rô chanh thơm ngát.)"],"ukAudio":"/ai_services/tts3/?q=syrup&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.%C9%99p%2F","usAudio":"/ai_services/tts3/?q=syrup&lang=en-US&ipa=%2F%CB%88s%C9%AAr.%C9%99p%2F"},{"id":"lv_8_83","topic":"Food and Health","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.əˌweɪ/","defVi":"đồ ăn mang về, quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else","examples":["We decided to order a Chinese [takeaway] for dinner tonight. (=Dịch: Chúng tôi quyết định gọi đồ ăn Trung Quốc mang về cho bữa tối nay.)","There is a very popular pizza [takeaway] near our campus. (=Dịch: Có một tiệm bánh pizza mang về rất nổi tiếng gần khuôn viên trường chúng tôi.)","Frequent consumption of [takeaway] food can be expensive and unhealthy. (=Dịch: Thường xuyên ăn đồ mang về có thể tốn kém và không tốt cho sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F"},{"id":"lv_8_84","topic":"Food and Health","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, khóa vòi","defEn":"a device that controls the flow of liquid or gas from a pipe","examples":["Do not forget to turn off the [tap] while brushing your teeth. (=Dịch: Đừng quên khóa vòi nước trong khi đánh răng.)","Water was dripping slowly from the kitchen [tap]. (=Dịch: Nước đang nhỏ giọt từ từ từ vòi rửa trong bếp.)","Is it safe to drink water straight from the [tap] here? (=Dịch: Uống nước trực tiếp từ vòi ở đây có an toàn không?)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_8_85","topic":"Food and Health","word":"therapy","pos":"(n)","ipa":"/ˈθer.ə.pi/","defVi":"liệu pháp, phương pháp trị liệu","defEn":"a treatment that helps someone feel better or grow stronger, especially after an illness or injury","examples":["Physical [therapy] helped him walk again after the terrible accident. (=Dịch: Vật lý trị liệu đã giúp anh ấy đi lại được sau vụ tai nạn kinh hoàng.)","Many people find music [therapy] effective for reducing stress. (=Dịch: Nhiều người thấy liệu pháp âm nhạc hiệu quả trong việc giảm căng thẳng.)","She goes to speech [therapy] twice a week to improve her pronunciation. (=Dịch: Cô ấy đi trị liệu ngôn ngữ hai lần một tuần để cải thiện khả năng phát âm.)"],"ukAudio":"/ai_services/tts3/?q=therapy&lang=en-GB&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F","usAudio":"/ai_services/tts3/?q=therapy&lang=en-US&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F"},{"id":"lv_8_86","topic":"Food and Health","word":"tonne","pos":"(n)","ipa":"/tʌn/","defVi":"tấn (đơn vị đo khối lượng","defEn":"1.000 kg)\n=a metric unit of mass equal to 1,000 kilograms","examples":["The factory produces more than one [tonne] of recycled paper every single day. (=Dịch: Nhà máy sản xuất hơn một tấn giấy tái chế mỗi ngày.)","The cargo ship carried several thousand [tonne] shipments of iron ore across the ocean. (=Dịch: Tàu chở hàng đã vận chuyển hàng ngàn tấn quặng sắt qua đại dương.)","Farmers harvested nearly five [tonne] yields of wheat per hectare this season. (=Dịch: Nông dân đã thu hoạch được sản lượng gần năm tấn lúa mì trên mỗi hecta trong mùa vụ này.)"],"ukAudio":"/ai_services/tts3/?q=tonne&lang=en-GB&ipa=%2Ft%CA%8Cn%2F","usAudio":"/ai_services/tts3/?q=tonne&lang=en-US&ipa=%2Ft%CA%8Cn%2F"},{"id":"lv_8_87","topic":"Food and Health","word":"toxin","pos":"(n)","ipa":"/ˈtɑːk.sɪn/","defVi":"độc tố (chất độc sinh học)","defEn":"a poisonous substance, especially one produced by a living organism","examples":["Certain species of mushrooms contain a deadly [toxin] that can cause severe liver failure. (=Dịch: Một số loài nấm chứa độc tố chết người có thể gây suy gan nghiêm trọng.)","The liver plays a vital role in filtering harmful [toxin] elements from the bloodstream. (=Dịch: Gan đóng vai trò quan trọng trong việc lọc các độc tố có hại ra khỏi máu.)","Bacteria in contaminated food can release a dangerous [toxin] leading to acute illness. (=Dịch: Vi khuẩn trong thực phẩm bị ô nhiễm có thể tiết ra độc tố nguy hiểm dẫn đến bệnh cấp tính.)"],"ukAudio":"/ai_services/tts3/?q=toxin&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=toxin&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F"},{"id":"lv_8_88","topic":"Food and Health","word":"trunk","pos":"(n)","ipa":"/trʌŋk/","defVi":"thân cây; hòm/rương lớn; cốp xe ô tô","defEn":"the main wooden stem of a tree, a large storage box, or the enclosed luggage compartment of a car","examples":["The thick [trunk] of the centuries-old oak tree provided shade for the entire garden. (=Dịch: Thân cây sồi hàng trăm năm tuổi to lớn che bóng mát cho cả khu vườn.)","She loaded all her heavy suitcases into the [trunk] of the taxi before heading to the airport. (=Dịch: Cô ấy xếp tất cả vali nặng vào cốp xe taxi trước khi ra sân bay.)","An elephant uses its versatile [trunk] to drink water and pick up food. (=Dịch: Một con voi sử dụng chiếc vòi đa năng của mình để uống nước và nhặt thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=trunk&lang=en-GB&ipa=%2Ftr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=trunk&lang=en-US&ipa=%2Ftr%CA%8C%C5%8Bk%2F"},{"id":"lv_8_89","topic":"Food and Health","word":"tube","pos":"(n)","ipa":"/tub/","defVi":"ống dẫn, tuýp","defEn":"a long, hollow cylinder used for carrying fluids or gases","examples":["Water flows through a metal [tube] into the cooling tank. (=Dịch: Nước chảy qua một ống kim loại vào bể làm mát.)","She bought a small [tube] of sunscreen at the pharmacy. (=Dịch: Cô ấy đã mua một tuýp kem chống nắng nhỏ ở hiệu thuốc.)","The technician replaced the damaged plastic [tube] inside the machine. (=Dịch: Kỹ thuật viên đã thay thế chiếc ống nhựa bị hỏng bên trong cỗ máy.)"],"ukAudio":"/ai_services/tts3/?q=tube&lang=en-GB&ipa=%2Ftub%2F","usAudio":"/ai_services/tts3/?q=tube&lang=en-US&ipa=%2Ftub%2F"},{"id":"lv_8_90","topic":"Food and Health","word":"unaware","pos":"(adj)","ipa":"/ˌʌn.əˈwer/","defVi":"không nhận biết, không hay biết","defEn":"Not knowing or noticing something that is happening.","examples":["Many people remain completely [unaware] of the dangers of excessive sugar consumption. (=Dịch: Nhiều người vẫn hoàn toàn không nhận thức được sự nguy hiểm của việc tiêu thụ quá nhiều đường.)","She seemed [unaware] that everyone in the room was listening to her conversation. (=Dịch: Cô ấy dường như không hay biết rằng mọi người trong phòng đều đang lắng nghe cuộc trò chuyện của mình.)","The driver was [unaware] of the flat tire until another motorist signaled him. (=Dịch: Người tài xế không biết xe bị xẹp lốp cho đến khi một người đi đường khác ra hiệu.)"],"ukAudio":"/ai_services/tts3/?q=unaware&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88wer%2F","usAudio":"/ai_services/tts3/?q=unaware&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88wer%2F"},{"id":"lv_8_91","topic":"Food and Health","word":"unhealthy","pos":"(adj)","ipa":"/ʌnˈhel.θi/","defVi":"không lành mạnh, có hại cho sức khỏe","defEn":"Harmful to your health or not having good health.","examples":["Eating too much fast food is an [unhealthy] habit that can lead to obesity. (=Dịch: Ăn quá nhiều đồ ăn nhanh là một thói quen không lành mạnh có thể dẫn đến béo phì.)","He made a full recovery after suffering from an [unhealthy] sleep schedule for months. (=Dịch: Anh ấy đã hồi phục hoàn toàn sau nhiều tháng có lịch trình ngủ thiếu lành mạnh.)","High levels of pollution create an [unhealthy] living environment in big cities. (=Dịch: Mức độ ô nhiễm cao tạo ra một môi trường sống có hại cho sức khỏe ở các thành phố lớn.)"],"ukAudio":"/ai_services/tts3/?q=unhealthy&lang=en-GB&ipa=%2F%CA%8Cn%CB%88hel.%CE%B8i%2F","usAudio":"/ai_services/tts3/?q=unhealthy&lang=en-US&ipa=%2F%CA%8Cn%CB%88hel.%CE%B8i%2F"},{"id":"lv_8_92","topic":"Food and Health","word":"unnecessary","pos":"(adj)","ipa":"/ʌnˈnes.ə.ser.i/","defVi":"không cần thiết, thừa thãi","defEn":"not needed or more than is needed.","examples":["Avoid making [unnecessary] purchases when you are saving money. (=Dịch: Hãy tránh mua sắm những thứ không cần thiết khi bạn đang tiết kiệm tiền.)","The flight delay caused [unnecessary] stress for all travelers. (=Dịch: Chuyến bay bị hoãn đã gây ra sự căng thẳng không đáng có cho tất cả các hành khách.)","He deleted [unnecessary] files to free up computer storage. (=Dịch: Anh ấy đã xóa các tệp không cần thiết để giải phóng dung lượng máy tính.)"],"ukAudio":"/ai_services/tts3/?q=unnecessary&lang=en-GB&ipa=%2F%CA%8Cn%CB%88nes.%C9%99.ser.i%2F","usAudio":"/ai_services/tts3/?q=unnecessary&lang=en-US&ipa=%2F%CA%8Cn%CB%88nes.%C9%99.ser.i%2F"},{"id":"lv_8_93","topic":"Food and Health","word":"upsetting","pos":"(adj)","ipa":"/ʌpˈset̬.ɪŋ/","defVi":"gây buồn phiền, đau lòng, làm khó chịu","defEn":"making someone feel worried, unhappy, or distressed","examples":["Watching the news about the natural disaster was deeply [upsetting]. (=Dịch: Xem tin tức về thảm họa thiên nhiên khiến mọi người vô cùng đau lòng.)","It was very [upsetting] for him to hear that his best friend was moving away. (=Dịch: Thật là buồn phiền đối với anh ấy khi nghe tin người bạn thân nhất của mình chuyển đi nơi khác.)","The documentary contains [upsetting] scenes of animal cruelty. (=Dịch: Bộ phim tài liệu chứa những cảnh quay đau lòng về sự tàn ác đối với động vật.)"],"ukAudio":"/ai_services/tts3/?q=upsetting&lang=en-GB&ipa=%2F%CA%8Cp%CB%88set%CC%AC.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=upsetting&lang=en-US&ipa=%2F%CA%8Cp%CB%88set%CC%AC.%C9%AA%C5%8B%2F"},{"id":"lv_8_94","topic":"Food and Health","word":"vitamin","pos":"(n)","ipa":"/ˈvaɪ.t̬ə.mɪn/","defVi":"vi-ta-min","defEn":"a natural substance found in food that is essential for normal growth and health","examples":["Oranges are extremely rich in [vitamin] C. (=Dịch: Cam rất giàu vi-ta-min C.)","The doctor recommended that she take a daily [vitamin] supplement. (=Dịch: Bác sĩ khuyên cô ấy nên uống viên bổ sung vi-ta-min mỗi ngày.)","A severe [vitamin] deficiency can lead to serious health issues. (=Dịch: Tình trạng thiếu hụt vi-ta-min nghiêm trọng có thể dẫn đến các vấn đề sức khỏe nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=vitamin&lang=en-GB&ipa=%2F%CB%88va%C9%AA.t%CC%AC%C9%99.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=vitamin&lang=en-US&ipa=%2F%CB%88va%C9%AA.t%CC%AC%C9%99.m%C9%AAn%2F"},{"id":"lv_8_95","topic":"Food and Health","word":"warmth","pos":"(n)","ipa":"/wɔːrmθ/","defVi":"sự ấm áp, hơi ấm; sự niềm nở","defEn":"the state of being moderately hot; a feeling of friendliness and affection","examples":["She sat near the fireplace to feel the soothing [warmth] of the fire. (=Dịch: Cô ấy ngồi gần lò sưởi để cảm nhận hơi ấm dễ chịu từ ngọn lửa.)","The local community welcomed the refugees with genuine [warmth] and kindness. (=Dịch: Cộng đồng địa phương đã đón tiếp những người tị nạn với sự nồng hậu và lòng tốt chân thành.)","The morning sun provided enough [warmth] to melt the light layer of frost. (=Dịch: Ánh nắng buổi sớm đem lại đủ hơi ấm để làm tan lớp sương giá mỏng.)"],"ukAudio":"/ai_services/tts3/?q=warmth&lang=en-GB&ipa=%2Fw%C9%94%CB%90rm%CE%B8%2F","usAudio":"/ai_services/tts3/?q=warmth&lang=en-US&ipa=%2Fw%C9%94%CB%90rm%CE%B8%2F"},{"id":"lv_8_96","topic":"Food and Health","word":"weigh","pos":"(v)","ipa":"/weɪ/","defVi":"cân, cân nhắc","defEn":"to measure how heavy someone or something is, or to consider carefully","examples":["The nurse asked the patient to step on the scale to [weigh] him. (=Dịch: Y tá đã yêu cầu bệnh nhân bước lên bàn cân để cân trọng lượng.)","You should [weigh] all the ingredients accurately before baking the cake. (=Dịch: Bạn nên cân chính xác tất cả nguyên liệu trước khi nướng bánh.)","The committee needs to [weigh] the pros and cons before making a decision. (=Dịch: Ủy ban cần cân nhắc những ưu và nhược điểm trước khi đưa ra quyết định.)"],"ukAudio":"/ai_services/tts3/?q=weigh&lang=en-GB&ipa=%2Fwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weigh&lang=en-US&ipa=%2Fwe%C9%AA%2F"},{"id":"lv_8_97","topic":"Food and Health","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪdˌsprɛd/","defVi":"lan rộng, phổ biến khắp nơi","defEn":"existing or happening in many places or among many people","examples":["The new environmental policy received [widespread] support from the public. (=Dịch: Chính sách môi trường mới đã nhận được sự ủng hộ rộng rãi từ công chúng.)","The sudden power outage caused [widespread] disruption across the entire city. (=Dịch: Sự cố mất điện đột ngột đã gây ra tình trạng gián đoạn trên diện rộng khắp toàn thành phố.)","Deforestation remains a [widespread] concern in many tropical regions. (=Dịch: Nạn phá rừng vẫn là một mối lo ngại phổ biến ở nhiều khu vực nhiệt đới.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F"},{"id":"lv_8_98","topic":"Food and Health","word":"workout","pos":"(n)","ipa":"/ˈwɜːr.kaʊt/","defVi":"buổi tập luyện thể dục","defEn":"a period of physical exercise or training.","examples":["He does a daily morning [workout] to stay in shape. (=Dịch: Anh ấy tập thể dục mỗi sáng để giữ dáng.)","Drinking water after an intense [workout] is very important. (=Dịch: Uống nước sau một buổi tập luyện cường độ cao là rất quan trọng.)","She enjoys a 30-minute cardio [workout] at the gym. (=Dịch: Cô ấy thích một buổi tập cardio 30 phút tại phòng gym.)"],"ukAudio":"/ai_services/tts3/?q=workout&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90r.ka%CA%8At%2F","usAudio":"/ai_services/tts3/?q=workout&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90r.ka%CA%8At%2F"},{"id":"lv_9_0","topic":"Technology and Natural Sciences","word":"activate","pos":"(v)","ipa":"/ˈæk.tə.veɪt/","defVi":"kích hoạt, làm hoạt động","defEn":"to make something start working or functioning","examples":["You need to click the link in your email to [activate] your new account. (=Dịch: Bạn cần nhấp vào liên kết trong email để kích hoạt tài khoản mới của mình.)","Motion sensors automatically [activate] the outdoor lights when someone approaches. (=Dịch: Cảm biến chuyển động sẽ tự động kích hoạt đèn ngoài trời khi có người đến gần.)","The emergency system will [activate] an alarm as soon as smoke is detected. (=Dịch: Hệ thống khẩn cấp sẽ kích hoạt chuông báo động ngay khi phát hiện có khói.)"],"ukAudio":"/ai_services/tts3/?q=activate&lang=en-GB&ipa=%2F%CB%88%C3%A6k.t%C9%99.ve%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=activate&lang=en-US&ipa=%2F%CB%88%C3%A6k.t%C9%99.ve%C9%AAt%2F"},{"id":"lv_9_1","topic":"Technology and Natural Sciences","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"áp dụng, thông qua, nhận nuôi","defEn":"to choose to follow or use a particular idea, method, plan, or style","examples":["Many schools decided to [adopt] digital textbooks to reduce paper waste. (=Dịch: Nhiều trường học đã quyết định áp dụng sách giáo khoa kỹ thuật số để giảm bớt rác thải giấy.)","The couple chose to [adopt] a child from an overseas orphanage. (=Dịch: Cặp vợ chồng đã chọn nhận nuôi một đứa trẻ từ một trại trẻ mồ côi ở nước ngoài.)","Organizations must [adopt] new marketing strategies to remain competitive in the market. (=Dịch: Các tổ chức phải áp dụng các chiến lược tiếp thị mới để duy trì tính cạnh tranh trên thị trường.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_9_2","topic":"Technology and Natural Sciences","word":"aerial","pos":"(adj)","ipa":"/ˈer.i.əl/","defVi":"trên không, trên trời","defEn":"existing, happening, or operating in the air","examples":["The drone captured stunning [aerial] views of the coastline. (=Dịch: Máy bay không người lái đã chụp được những góc nhìn trên không tuyệt đẹp của đường bờ biển.)","Firefighters used [aerial] water drops to combat the wildfire. (=Dịch: Lính cứu hỏa đã sử dụng trực thăng thả nước từ trên không để dập tắt đám cháy rừng.)","We enjoyed an [aerial] tour of the city in a helicopter. (=Dịch: Chúng tôi rất thích chuyến tham quan thành phố từ trên không bằng trực thăng.)"],"ukAudio":"/ai_services/tts3/?q=aerial&lang=en-GB&ipa=%2F%CB%88er.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aerial&lang=en-US&ipa=%2F%CB%88er.i.%C9%99l%2F"},{"id":"lv_9_3","topic":"Technology and Natural Sciences","word":"allergic","pos":"(adj)","ipa":"/əˈlɝː.dʒɪk/","defVi":"dị ứng","defEn":"having a strong, bad medical reaction to a particular substance","examples":["She is severely [allergic] to peanuts and must carry medicine everywhere. (=Dịch: Cô ấy bị dị ứng nặng với đậu phộng và phải mang theo thuốc đi khắp nơi.)","Many people are [allergic] to cat hair and start sneezing immediately. (=Dịch: Nhiều người bị dị ứng với lông mèo và bắt đầu hắt hơi ngay lập tức.)","He discovered that he was [allergic] to penicillin after a hospital visit. (=Dịch: Anh ấy phát hiện ra mình bị dị ứng với penicillin sau một lần đến bệnh viện.)"],"ukAudio":"/ai_services/tts3/?q=allergic&lang=en-GB&ipa=%2F%C9%99%CB%88l%C9%9D%CB%90.d%CA%92%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=allergic&lang=en-US&ipa=%2F%C9%99%CB%88l%C9%9D%CB%90.d%CA%92%C9%AAk%2F"},{"id":"lv_9_4","topic":"Technology and Natural Sciences","word":"appliance","pos":"(n)","ipa":"/əˈplaɪ.əns/","defVi":"thiết bị, đồ gia dụng","defEn":"a machine or device, especially an electrical one used in the home","examples":["Modern kitchens are equipped with various energy-saving [appliance] models. (=Dịch: Các căn bếp hiện đại được trang bị nhiều mẫu thiết bị tiết kiệm năng lượng.)","Always unplug the household [appliance] before trying to repair it. (=Dịch: Luôn rút phích cắm thiết bị gia dụng trước khi cố gắng sửa chữa nó.)","The store sells a wide range of kitchen [appliance] products. (=Dịch: Cửa hàng bán rất nhiều sản phẩm đồ gia dụng nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=appliance&lang=en-GB&ipa=%2F%C9%99%CB%88pla%C9%AA.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=appliance&lang=en-US&ipa=%2F%C9%99%CB%88pla%C9%AA.%C9%99ns%2F"},{"id":"lv_9_5","topic":"Technology and Natural Sciences","word":"arid","pos":"(adj)","ipa":"/ˈær.ɪd/","defVi":"khô cằn, hạn hán","defEn":"having very little or no rain; extremely dry","examples":["Few plants can survive in such an [arid] climate without irrigation. (=Dịch: Rất ít loài thực vật có thể sống sót trong khí hậu khô cằn như vậy nếu không có tưới tiêu.)","The desert is an [arid] landscape with extreme temperatures. (=Dịch: Sa mạc là một cảnh quan khô cằn với nhiệt độ vô cùng khắc nghiệt.)","Farmers struggle to grow crops in the region's [arid] soil. (=Dịch: Nông dân phải chật vật trồng trọt trên đất đai khô cằn của khu vực này.)"],"ukAudio":"/ai_services/tts3/?q=arid&lang=en-GB&ipa=%2F%CB%88%C3%A6r.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=arid&lang=en-US&ipa=%2F%CB%88%C3%A6r.%C9%AAd%2F"},{"id":"lv_9_6","topic":"Technology and Natural Sciences","word":"association","pos":"(n)","ipa":"/əˌsoʊ.siˈeɪ.ʃn/","defVi":"hiệp hội, sự liên kết / mối liên hệ","defEn":"an organized group of people with a shared purpose, or a mental connection between ideas","examples":["She joined the local medical [association] to meet other doctors. (=Dịch: Cô ấy đã tham gia hiệp hội y khoa địa phương để gặp gỡ các bác sĩ khác.)","The word has a strong positive [association] in the minds of consumers. (=Dịch: Từ này có một mối liên hệ tích cực mạnh mẽ trong tâm trí người tiêu dùng.)","The university works in close [association] with research institutes. (=Dịch: Trường đại học làm việc trong sự liên kết chặt chẽ với các viện nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=association&lang=en-GB&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83n%2F","usAudio":"/ai_services/tts3/?q=association&lang=en-US&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83n%2F"},{"id":"lv_9_7","topic":"Technology and Natural Sciences","word":"atom","pos":"(n)","ipa":"/ˈæ.t̬əm/","defVi":"nguyên tử","defEn":"the smallest basic unit of a chemical element","examples":["A water molecule is made of two hydrogen [atoms] and one oxygen atom. (=Dịch: Một phân tử nước được tạo thành từ hai nguyên tử hydro và một nguyên tử oxy.)","Scientists study the structure of the [atom] to understand matter. (=Dịch: Các nhà khoa học nghiên cứu cấu trúc của nguyên tử để hiểu về vật chất.)","Splitting the [atom] can release a huge amount of energy. (=Dịch: Việc phân tách nguyên tử có thể giải phóng một lượng năng lượng khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=atom&lang=en-GB&ipa=%2F%CB%88%C3%A6.t%CC%AC%C9%99m%2F","usAudio":"/ai_services/tts3/?q=atom&lang=en-US&ipa=%2F%CB%88%C3%A6.t%CC%AC%C9%99m%2F"},{"id":"lv_9_8","topic":"Technology and Natural Sciences","word":"beetroot","pos":"(n)","ipa":"/ˈbit.rut/","defVi":"củ dền","defEn":"a plant with a round dark red root that is eaten as a vegetable","examples":["Fresh [beetroot] can be sliced and added to healthy salads. (=Dịch: Củ dền tươi có thể được cắt lát và thêm vào các món salad tốt cho sức khỏe.)","Drinking [beetroot] juice is believed to lower blood pressure. (=Dịch: Uống nước ép củ dền được cho là giúp hạ huyết áp.)","The natural dye from [beetroot] gives the soup a rich red color. (=Dịch: Phẩm màu tự nhiên từ củ dền tạo cho món súp một màu đỏ đậm đà.)"],"ukAudio":"/ai_services/tts3/?q=beetroot&lang=en-GB&ipa=%2F%CB%88bit.rut%2F","usAudio":"/ai_services/tts3/?q=beetroot&lang=en-US&ipa=%2F%CB%88bit.rut%2F"},{"id":"lv_9_9","topic":"Technology and Natural Sciences","word":"capability","pos":"(n)","ipa":"/ˌkeɪ.pəˈbɪl.ə.t̬i/","defVi":"khả năng, năng lực","defEn":"the ability or power to do something","examples":["The new software has the [capability] to process large amounts of data quickly. (=Dịch: Phần mềm mới có khả năng xử lý lượng lớn dữ liệu một cách nhanh chóng.)","She demonstrated remarkable leadership [capability] during the crisis. (=Dịch: Cô ấy đã thể hiện năng lực lãnh đạo xuất sắc trong suốt cuộc khủng hoảng.)","The smartphone's camera [capability] is better than that of many older models. (=Dịch: Khả năng của camera trên chiếc điện thoại thông minh này tốt hơn nhiều dòng máy cũ.)"],"ukAudio":"/ai_services/tts3/?q=capability&lang=en-GB&ipa=%2F%CB%8Cke%C9%AA.p%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=capability&lang=en-US&ipa=%2F%CB%8Cke%C9%AA.p%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_9_10","topic":"Technology and Natural Sciences","word":"carbon","pos":"(n)","ipa":"/ˈkɑːr.bən/","defVi":"cacbon","defEn":"a chemical element that is found in all living things, coal, and diamonds","examples":["Diamonds and graphite are both pure forms of [carbon]. (=Dịch: Kim cương và than chì đều là các dạng tinh khiết của cacbon.)","Companies are trying to reduce their [carbon] footprint to protect nature. (=Dịch: Các công ty đang nỗ lực giảm dấu chân cacbon để bảo vệ thiên nhiên.)","All known life on Earth is based on [carbon] chemistry. (=Dịch: Mọi sự sống được biết đến trên Trái Đất đều dựa trên hóa học cacbon.)"],"ukAudio":"/ai_services/tts3/?q=carbon&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.b%C9%99n%2F","usAudio":"/ai_services/tts3/?q=carbon&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.b%C9%99n%2F"},{"id":"lv_9_11","topic":"Technology and Natural Sciences","word":"carbon dioxide","pos":"(n)","ipa":"/ˌkɑːr.bən daɪˈɑːk.saɪd/","defVi":"khí cacbonic, khí CO2","defEn":"a gas that is produced when people or animals breathe out, or when carbon is burned","examples":["Trees absorb [carbon dioxide] and release oxygen into the atmosphere. (=Dịch: Cây xanh hấp thụ khí cacbonic và thải oxy vào bầu khí quyển.)","Burning fossil fuels increases the level of [carbon dioxide] in the air. (=Dịch: Đốt nhiên liệu hóa thạch làm tăng nồng độ khí CO2 trong không khí.)","Excessive [carbon dioxide] emissions contribute significantly to global warming. (=Dịch: Lượng khí thải cacbonic quá mức đóng góp đáng kể vào sự nóng lên toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=carbon+dioxide&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90r.b%C9%99n+da%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=carbon+dioxide&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90r.b%C9%99n+da%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F"},{"id":"lv_9_12","topic":"Technology and Natural Sciences","word":"census","pos":"(n)","ipa":"/ˈsɛn.səs/","defVi":"cuộc điều tra dân số","defEn":"an official count of the population and collection of demographic information","examples":["The government conducts a national [census] every ten years. (=Dịch: Chính phủ tiến hành một cuộc điều tra dân số quốc gia mười năm một lần.)","According to the latest [census], the city's population has increased dramatically. (=Dịch: Theo cuộc điều tra dân số gần nhất, dân số của thành phố đã tăng lên đáng kể.)","All households are required by law to complete the [census] form. (=Dịch: Tất cả các hộ gia đình theo luật đều phải hoàn thành phiếu điều tra dân số.)"],"ukAudio":"/ai_services/tts3/?q=census&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.s%C9%99s%2F","usAudio":"/ai_services/tts3/?q=census&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.s%C9%99s%2F"},{"id":"lv_9_13","topic":"Technology and Natural Sciences","word":"chamber","pos":"(n)","ipa":"/ˈtʃeɪm.bɚ/","defVi":"phòng lớn, buồng, khoang kín","defEn":"a room used for a special purpose or an enclosed space in a machine or body","examples":["The council members gathered in the council [chamber] for the debate. (=Dịch: Các thành viên hội đồng đã tập trung tại phòng họp hội đồng để thảo luận.)","The patient was placed in a hyperbaric oxygen [chamber] to speed up recovery. (=Dịch: Bệnh nhân được đưa vào buồng oxy cao áp để đẩy nhanh quá trình hồi phục.)","Archaeologists discovered an ancient burial [chamber] deep inside the pyramid. (=Dịch: Các nhà khảo cổ học đã phát hiện một hầm mộ cổ sâu bên trong kim tự tháp.)"],"ukAudio":"/ai_services/tts3/?q=chamber&lang=en-GB&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chamber&lang=en-US&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F"},{"id":"lv_9_14","topic":"Technology and Natural Sciences","word":"charcoal","pos":"(n)","ipa":"/ˈtʃɑːr.koʊl/","defVi":"than củi, than hoa","defEn":"a hard black substance made by burning wood slowly, used as fuel or for drawing","examples":["We used [charcoal] to light the grill for our outdoor barbecue. (=Dịch: Chúng tôi đã dùng than củi để đốt lò nướng cho bữa tiệc thịt nướng ngoài trời.)","The artist drew a beautiful portrait using black [charcoal]. (=Dịch: Người họa sĩ đã vẽ một bức chân dung tuyệt đẹp bằng than vẽ.)","Activated [charcoal] is often used in water filters to remove impurities. (=Dịch: Than hoạt tính thường được sử dụng trong các bộ lọc nước để loại bỏ tạp chất.)"],"ukAudio":"/ai_services/tts3/?q=charcoal&lang=en-GB&ipa=%2F%CB%88t%CA%83%C9%91%CB%90r.ko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=charcoal&lang=en-US&ipa=%2F%CB%88t%CA%83%C9%91%CB%90r.ko%CA%8Al%2F"},{"id":"lv_9_15","topic":"Technology and Natural Sciences","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or business that is trying to do better than others","examples":["The company lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty đã giảm giá để đi trước đối thủ cạnh tranh chính của mình.)","Each [competitor] in the marathon was given a race number and water bottle. (=Dịch: Mỗi thí sinh trong cuộc đua marathon đều được cấp một số báo danh và chai nước.)","Technological innovation allows small firms to challenge a larger [competitor]. (=Dịch: Đổi mới công nghệ cho phép các công ty nhỏ cạnh tranh với đối thủ lớn hơn.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_9_16","topic":"Technology and Natural Sciences","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwens/","defVi":"hậu quả, hệ quả","defEn":"a result or effect of an action or condition","examples":["Rising sea levels are a direct [consequence] of global warming. (=Dịch: Mực nước biển dâng cao là hệ quả trực tiếp của hiện tượng ấm lên toàn cầu.)","He had to face the [consequence] of missing the final exam. (=Dịch: Cậu ấy phải đối mặt với hậu quả của việc bỏ lỡ kỳ thi cuối kỳ.)","Poor diet choices can have a serious [consequence] for long-term health. (=Dịch: Lựa chọn chế độ ăn uống kém có thể dẫn đến hậu quả nghiêm trọng cho sức khỏe lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kwens%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kwens%2F"},{"id":"lv_9_17","topic":"Technology and Natural Sciences","word":"cotton","pos":"(n)","ipa":"/ˈkɑː.tn/","defVi":"bông, vải cotton","defEn":"a soft white natural fiber grown on plants, used to make cloth","examples":["This shirt is made of one hundred percent organic [cotton]. (=Dịch: Chiếc áo sơ mi này được làm từ một trăm phần trăm bông hữu cơ.)","Farmers in this region have grown [cotton] for generations. (=Dịch: Nông dân ở vùng này đã trồng bông qua nhiều thế hệ.)","Clothes made from [cotton] are comfortable and breathable in hot weather. (=Dịch: Quần áo làm từ vải cotton rất thoải mái và thoáng mát trong thời tiết nóng.)"],"ukAudio":"/ai_services/tts3/?q=cotton&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.tn%2F","usAudio":"/ai_services/tts3/?q=cotton&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.tn%2F"},{"id":"lv_9_18","topic":"Technology and Natural Sciences","word":"decoration","pos":"(n)","ipa":"/ˌdek.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang trí","defEn":"the activity of making something look more attractive, or an object used for this","examples":["They put up colorful [decoration] for the holiday festival. (=Dịch: Họ đã treo đồ trang trí đầy màu sắc cho lễ hội ngày lễ.)","The interior [decoration] of the café creates a cozy atmosphere. (=Dịch: Cách trang trí nội thất của quán cà phê tạo nên một không gian ấm cúng.)","Handmade paper lanterns were used as [decoration] in the garden. (=Dịch: Những chiếc lồng đèn giấy thủ công đã được dùng làm đồ trang trí trong vườn.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_19","topic":"Technology and Natural Sciences","word":"detergent","pos":"(n)","ipa":"/dɪˈtɝː.dʒənt/","defVi":"chất tẩy rửa, bột giặt / nước giặt","defEn":"a chemical substance in liquid or powder form used for washing and cleaning","examples":["You should use a gentle laundry [detergent] when washing delicate silk garments. (=Dịch: Bạn nên sử dụng loại nước giặt dịu nhẹ khi giặt quần áo lụa mỏng manh.)","Eco-friendly [detergent] brands are gaining popularity among modern consumers. (=Dịch: Các thương hiệu chất tẩy rửa thân thiện với môi trường đang ngày càng được người tiêu dùng hiện đại ưa chuộng.)","A small capful of liquid [detergent] is enough to clean this entire load of dishes. (=Dịch: Một nắp nhỏ nước rửa bát là đủ để làm sạch toàn bộ số bát đĩa này.)"],"ukAudio":"/ai_services/tts3/?q=detergent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9D%CB%90.d%CA%92%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=detergent&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9D%CB%90.d%CA%92%C9%99nt%2F"},{"id":"lv_9_20","topic":"Technology and Natural Sciences","word":"dishwasher","pos":"(n)","ipa":"/ˈdɪʃˌwɑː.ʃɚ/","defVi":"máy rửa bát","defEn":"an electric machine used for washing dishes automatically","examples":["Loading the [dishwasher] properly helps ensure everything gets clean. (=Dịch: Xếp đồ vào máy rửa bát đúng cách giúp đảm bảo mọi thứ đều được rửa sạch.)","Our new [dishwasher] is extremely quiet and energy-efficient. (=Dịch: Chiếc máy rửa bát mới của chúng tôi cực kỳ êm ái và tiết kiệm điện năng.)","She prefers using the [dishwasher] over washing plates by hand. (=Dịch: Cô ấy thích dùng máy rửa bát hơn là tự rửa đĩa bằng tay.)"],"ukAudio":"/ai_services/tts3/?q=dishwasher&lang=en-GB&ipa=%2F%CB%88d%C9%AA%CA%83%CB%8Cw%C9%91%CB%90.%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=dishwasher&lang=en-US&ipa=%2F%CB%88d%C9%AA%CA%83%CB%8Cw%C9%91%CB%90.%CA%83%C9%9A%2F"},{"id":"lv_9_21","topic":"Technology and Natural Sciences","word":"drought","pos":"(n)","ipa":"/draʊt/","defVi":"hạn hán","defEn":"a long period of time when there is little or no rain","examples":["The severe [drought] destroyed most of the crops in the region. (=Dịch: Đợt hạn hán nghiêm trọng đã phá hủy phần lớn mùa màng trong khu vực.)","Farmers are struggling to survive during the prolonged [drought]. (=Dịch: Nông dân đang chật vật mưu sinh trong suốt đợt hạn hán kéo dài.)","Climate change has led to more frequent occurrences of [drought]. (=Dịch: Biến đổi khí hậu đã dẫn đến sự xuất hiện thường xuyên hơn của hạn hán.)"],"ukAudio":"/ai_services/tts3/?q=drought&lang=en-GB&ipa=%2Fdra%CA%8At%2F","usAudio":"/ai_services/tts3/?q=drought&lang=en-US&ipa=%2Fdra%CA%8At%2F"},{"id":"lv_9_22","topic":"Technology and Natural Sciences","word":"dye","pos":"(n)","ipa":"/daɪ/","defVi":"thuốc nhuộm, chất nhuộm màu","defEn":"a substance used to change the color of clothes, hair, or other materials","examples":["She used a natural plant [dye] to color the cotton fabric. (=Dịch: Cô ấy đã sử dụng thuốc nhuộm thực vật tự nhiên để nhuộm màu cho vải cotton.)","The bright red [dye] began to fade after several washes. (=Dịch: Chất nhuộm màu đỏ tươi bắt đầu phai dần sau vài lần giặt.)","Some artificial food [dyes] have been banned due to health concerns. (=Dịch: Một số loại phẩm màu nhân tạo đã bị cấm vì những lo ngại về sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=dye&lang=en-GB&ipa=%2Fda%C9%AA%2F","usAudio":"/ai_services/tts3/?q=dye&lang=en-US&ipa=%2Fda%C9%AA%2F"},{"id":"lv_9_23","topic":"Technology and Natural Sciences","word":"economical","pos":"(adj)","ipa":"/ˌiː.kəˈnɑː.mɪ.kəl/","defVi":"tiết kiệm, kinh tế","defEn":"providing good value or using money, resources, or time carefully","examples":["Small cars are usually more [economical] to run than large ones. (=Dịch: Xe ô tô nhỏ thường tiết kiệm chi phí vận hành hơn xe lớn.)","She found an [economical] way to heat her home during the winter. (=Dịch: Cô ấy đã tìm ra một cách tiết kiệm để sưởi ấm ngôi nhà vào mùa đông.)","Buying in bulk is often a more [economical] choice for large families. (=Dịch: Mua số lượng lớn thường là lựa chọn tiết kiệm hơn cho các gia đình đông người.)"],"ukAudio":"/ai_services/tts3/?q=economical&lang=en-GB&ipa=%2F%CB%8Ci%CB%90.k%C9%99%CB%88n%C9%91%CB%90.m%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=economical&lang=en-US&ipa=%2F%CB%8Ci%CB%90.k%C9%99%CB%88n%C9%91%CB%90.m%C9%AA.k%C9%99l%2F"},{"id":"lv_9_24","topic":"Technology and Natural Sciences","word":"entire","pos":"(adj)","ipa":"/ɪnˈtaɪ.ɚ/","defVi":"toàn bộ, toàn vẹn","defEn":"including everything, everyone, or every part; whole","examples":["He spent the [entire] afternoon reading a novel in the library. (=Dịch: Anh ấy đã dành toàn bộ buổi chiều để đọc một cuốn tiểu thuyết trong thư viện.)","The [entire] staff attended the mandatory training session on workplace safety. (=Dịch: Toàn bộ nhân viên đã tham dự buổi đào tạo bắt buộc về an toàn lao động.)","A sudden power outage left the [entire] neighborhood in complete darkness. (=Dịch: Sự cố mất điện đột ngột đã khiến toàn bộ khu phố chìm trong bóng tối hoàn toàn.)"],"ukAudio":"/ai_services/tts3/?q=entire&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=entire&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_9_25","topic":"Technology and Natural Sciences","word":"fabric","pos":"(n)","ipa":"/ˈfæb.rɪk/","defVi":"vải, sợi vải","defEn":"cloth or material produced by weaving or knitting","examples":["Cotton is a natural [fabric] that is comfortable to wear in summer. (=Dịch: Bông là loại vải tự nhiên mang lại cảm giác thoải mái khi mặc vào mùa hè.)","This waterproof [fabric] is ideal for making outdoor jackets. (=Dịch: Loại vải chống thấm nước này rất lý tưởng để may áo khoác ngoài trời.)","The delicate [fabric] must be washed by hand to avoid damage. (=Dịch: Loại vải mỏng manh này phải được giặt bằng tay để tránh hư hại.)"],"ukAudio":"/ai_services/tts3/?q=fabric&lang=en-GB&ipa=%2F%CB%88f%C3%A6b.r%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=fabric&lang=en-US&ipa=%2F%CB%88f%C3%A6b.r%C9%AAk%2F"},{"id":"lv_9_26","topic":"Technology and Natural Sciences","word":"famine","pos":"(n)","ipa":"/ˈfæm.ɪn/","defVi":"nạn đói","defEn":"an extreme shortage of food that causes widespread hunger","examples":["The war resulted in widespread [famine] across the nation. (=Dịch: Chiến tranh đã dẫn đến nạn đói lan rộng khắp cả nước.)","International aid was sent to prevent a catastrophic [famine]. (=Dịch: Viện trợ quốc tế đã được gửi đến nhằm ngăn chặn một nạn đói thảm khốc.)","Thousands of people suffered from malnutrition during the great [famine]. (=Dịch: Hàng nghìn người đã bị suy dinh dưỡng trong suốt nạn đói lớn.)"],"ukAudio":"/ai_services/tts3/?q=famine&lang=en-GB&ipa=%2F%CB%88f%C3%A6m.%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=famine&lang=en-US&ipa=%2F%CB%88f%C3%A6m.%C9%AAn%2F"},{"id":"lv_9_27","topic":"Technology and Natural Sciences","word":"fence","pos":"(n)","ipa":"/fɛns/","defVi":"hàng rào","defEn":"a barrier that surrounds an area of land to keep people or animals in or out","examples":["They built a wooden [fence] around their garden to keep animals out. (=Dịch: Họ đã dựng một hàng rào gỗ quanh vườn để ngăn động vật vào.)","The dog jumped over the low [fence] and ran into the street. (=Dịch: Con chó nhảy qua hàng rào thấp và chạy ra đường.)","A tall metal [fence] separates the two properties. (=Dịch: Một hàng rào kim loại cao ngăn cách giữa hai khu đất.)"],"ukAudio":"/ai_services/tts3/?q=fence&lang=en-GB&ipa=%2Ff%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=fence&lang=en-US&ipa=%2Ff%C9%9Bns%2F"},{"id":"lv_9_28","topic":"Technology and Natural Sciences","word":"fibre","pos":"(n)","ipa":"/ˈfaɪ.bɚ/","defVi":"sợi, chất xơ","defEn":"a thin thread of natural or artificial material, or the parts of food that cannot be digested","examples":["Eating food that is high in [fibre] helps maintain a healthy digestion. (=Dịch: Ăn thực phẩm giàu chất xơ giúp duy trì hệ tiêu hóa khỏe mạnh.)","Nylon is a strong synthetic [fibre] used to produce clothing and ropes. (=Dịch: Nilon là một loại sợi tổng hợp bền chắc được dùng để sản xuất quần áo và dây thừng.)","Optic [fibre] cables allow internet data to travel at high speeds. (=Dịch: Cáp sợi quang cho phép dữ liệu internet truyền đi với tốc độ cao.)"],"ukAudio":"/ai_services/tts3/?q=fibre&lang=en-GB&ipa=%2F%CB%88fa%C9%AA.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=fibre&lang=en-US&ipa=%2F%CB%88fa%C9%AA.b%C9%9A%2F"},{"id":"lv_9_29","topic":"Technology and Natural Sciences","word":"float","pos":"(v)","ipa":"/floʊt/","defVi":"nổi, trôi bồng bềnh","defEn":"to stay on the surface of a liquid and not sink","examples":["Wood will naturally [float] on water because it is less dense. (=Dịch: Gỗ sẽ tự nhiên nổi trên mặt nước vì có khối lượng riêng nhỏ hơn.)","Bright red balloons began to [float] up into the sky. (=Dịch: Những quả bóng bay màu đỏ tươi bắt đầu trôi bồng bềnh lên bầu trời.)","She learned how to [float] on her back during swimming lessons. (=Dịch: Cô ấy đã học cách thả nổi ngửa người trong các buổi học bơi.)"],"ukAudio":"/ai_services/tts3/?q=float&lang=en-GB&ipa=%2Fflo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=float&lang=en-US&ipa=%2Fflo%CA%8At%2F"},{"id":"lv_9_30","topic":"Technology and Natural Sciences","word":"freeze","pos":"(v)","ipa":"/friz/","defVi":"đóng băng, đông cứng","defEn":"to turn into ice or become hard because of extreme cold","examples":["Water will [freeze] at zero degrees Celsius. (=Dịch: Nước sẽ đóng băng ở nhiệt độ không độ C.)","You can [freeze] the leftover food to preserve it for next week. (=Dịch: Bạn có thể đông lạnh thức ăn thừa để bảo quản cho tuần tới.)","The lake began to [freeze] as temperatures dropped drastically. (=Dịch: Mặt hồ bắt đầu đóng băng khi nhiệt độ giảm mạnh.)"],"ukAudio":"/ai_services/tts3/?q=freeze&lang=en-GB&ipa=%2Ffriz%2F","usAudio":"/ai_services/tts3/?q=freeze&lang=en-US&ipa=%2Ffriz%2F"},{"id":"lv_9_31","topic":"Technology and Natural Sciences","word":"generation","pos":"(n)","ipa":"/ˌdʒɛn.əˈreɪ.ʃən/","defVi":"thế hệ","defEn":"all the people of about the same age within a society","examples":["The older [generation] often has different views on technology than the youth. (=Dịch: Thế hệ lớn tuổi thường có quan điểm về công nghệ khác với giới trẻ.)","This family recipe has been passed down from [generation] to generation. (=Dịch: Công thức nấu ăn của gia đình này đã được truyền từ thế hệ này sang thế hệ khác.)","They are fighting to preserve the environment for the next [generation]. (=Dịch: Họ đang đấu tranh để bảo vệ môi trường cho thế hệ tương lai.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_32","topic":"Technology and Natural Sciences","word":"geographer","pos":"(n)","ipa":"/dʒiˈɑː.ɡrə.fər/","defVi":"nhà địa lý học","defEn":"a scientist who studies the Earth's physical features and human population","examples":["The [geographer] created detailed maps of the newly discovered island. (=Dịch: Nhà địa lý học đã tạo ra những bản đồ chi tiết về hòn đảo mới được phát hiện.)","As a [geographer], she studies how urban areas expand over time. (=Dịch: Là một nhà địa lý học, cô ấy nghiên cứu cách các khu vực đô thị mở rộng theo thời gian.)","The team of [geographer] experts analyzed the effects of soil erosion. (=Dịch: Đội ngũ các chuyên gia địa lý đã phân tích tác động của xói mòn đất.)"],"ukAudio":"/ai_services/tts3/?q=geographer&lang=en-GB&ipa=%2Fd%CA%92i%CB%88%C9%91%CB%90.%C9%A1r%C9%99.f%C9%99r%2F","usAudio":"/ai_services/tts3/?q=geographer&lang=en-US&ipa=%2Fd%CA%92i%CB%88%C9%91%CB%90.%C9%A1r%C9%99.f%C9%99r%2F"},{"id":"lv_9_33","topic":"Technology and Natural Sciences","word":"heading","pos":"(n)","ipa":"/ˈhɛd.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a title at the top of a page, chapter, or section of a text","examples":["You should write a clear [heading] for each paragraph in your essay. (=Dịch: Bạn nên viết một tiêu đề rõ ràng cho từng đoạn văn trong bài luận của mình.)","The main [heading] was printed in bold letters at the top of the report. (=Dịch: Tiêu đề chính được in đậm ở đầu bản báo cáo.)","Subsections under the same [heading] provide more detailed explanations. (=Dịch: Các phần phụ dưới cùng một tiêu đề cung cấp những lời giải thích chi tiết hơn.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88h%C9%9Bd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88h%C9%9Bd.%C9%AA%C5%8B%2F"},{"id":"lv_9_34","topic":"Technology and Natural Sciences","word":"hectare","pos":"(n)","ipa":"/ˈhek.tɛr/","defVi":"héc-ta (đơn vị đo diện tích bằng 10.000 mét vuông)","defEn":"a unit of measurement for land equal to 10,000 square meters","examples":["The farm covers an area of about fifty [hectares]. (=Dịch: Trang trại trải rộng trên diện tích khoảng năm mươi héc-ta.)","Thousands of [hectares] of forest were destroyed by the wildfire. (=Dịch: Hàng nghìn héc-ta rừng đã bị thiêu rụi bởi trận cháy rừng.)","They bought a [hectare] of land to build a new community center. (=Dịch: Họ đã mua một héc-ta đất để xây dựng một trung tâm cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=hectare&lang=en-GB&ipa=%2F%CB%88hek.t%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=hectare&lang=en-US&ipa=%2F%CB%88hek.t%C9%9Br%2F"},{"id":"lv_9_35","topic":"Technology and Natural Sciences","word":"honest","pos":"(adj)","ipa":"/ˈɑː.nɪst/","defVi":"thành thật, trung thực","defEn":"telling the truth and not cheating or lying","examples":["Please give me your [honest] opinion about this design. (=Dịch: Xin vui lòng cho tôi biết ý kiến trung thực của bạn về thiết kế này.)","He is an [honest] businessman who treats all his clients fairly. (=Dịch: Ông ấy là một doanh nhân trung thực, luôn đối xử công bằng với tất cả khách hàng của mình.)","To be completely [honest], I did not enjoy the movie very much. (=Dịch: Thành thật mà nói, tôi không thích bộ phim đó cho lắm.)"],"ukAudio":"/ai_services/tts3/?q=honest&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=honest&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F"},{"id":"lv_9_36","topic":"Technology and Natural Sciences","word":"icehouse","pos":"(n)","ipa":"/ˈaɪs.haʊs/","defVi":"nhà chứa băng, hầm giữ băng tuyết","defEn":"a building or structure used for storing ice before modern refrigeration was invented","examples":["In the nineteenth century, every large estate had an [icehouse] to preserve food. (=Dịch: Vào thế kỷ 19, mỗi dinh thự lớn đều có một hầm giữ băng để bảo quản thực phẩm.)","Workers carried large blocks of ice from the river directly to the [icehouse]. (=Dịch: Các công nhân đã vận chuyển những tảng băng lớn từ sông thẳng đến nhà chứa băng.)","The old [icehouse] was built deep underground to keep the temperature cold. (=Dịch: Hầm chứa băng cũ được xây sâu dưới lòng đất để duy trì nhiệt độ lạnh.)"],"ukAudio":"/ai_services/tts3/?q=icehouse&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=icehouse&lang=en-US&ipa=%2F%CB%88a%C9%AAs.ha%CA%8As%2F"},{"id":"lv_9_37","topic":"Technology and Natural Sciences","word":"importantly","pos":"(adv)","ipa":"/ɪmˈpɔːr.tənt.li/","defVi":"quan trọng là, một cách quan trọng","defEn":"used to emphasize a point that is of great significance","examples":["More [importantly], we must ensure the safety of all participants. (=Dịch: Quan trọng hơn, chúng ta phải đảm bảo an toàn cho tất cả những người tham gia.)","The project finished on schedule and, most [importantly], within budget. (=Dịch: Dự án đã hoàn thành đúng tiến độ và quan trọng nhất là trong phạm vi ngân sách.)","She gained valuable experience and, [importantly], made lasting friendships. (=Dịch: Cô ấy đã tích lũy được kinh nghiệm quý báu và quan trọng là xây dựng được những tình bạn lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=importantly&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F","usAudio":"/ai_services/tts3/?q=importantly&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F"},{"id":"lv_9_38","topic":"Technology and Natural Sciences","word":"innovative","pos":"(adj)","ipa":"/ˈɪn.ə.veɪ.t̬ɪv/","defVi":"đổi mới, mang tính sáng tạo","defEn":"introducing new ideas or methods","examples":["The startup developed an [innovative] solution for plastic waste management. (=Dịch: Công ty khởi nghiệp đã phát triển một giải pháp sáng tạo để quản lý rác thải nhựa.)","She won an award for her [innovative] teaching techniques. (=Dịch: Cô ấy đã giành giải thưởng nhờ các phương pháp giảng dạy đổi mới của mình.)","Engineers are designing [innovative] cars powered entirely by hydrogen. (=Dịch: Các kỹ sư đang thiết kế những chiếc xe hơi mang tính đổi mới chạy hoàn toàn bằng hydro.)"],"ukAudio":"/ai_services/tts3/?q=innovative&lang=en-GB&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=innovative&lang=en-US&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%CC%AC%C9%AAv%2F"},{"id":"lv_9_39","topic":"Technology and Natural Sciences","word":"insert","pos":"(v)","ipa":"/ɪnˈsɝːt/","defVi":"chèn, đưa vào, lồng vào","defEn":"to put something into something else","examples":["Please [insert] your card into the machine and enter your PIN. (=Dịch: Vui lòng đưa thẻ của bạn vào máy và nhập mã PIN.)","You can [insert] images and charts directly into your presentation slides. (=Dịch: Bạn có thể chèn hình ảnh và biểu đồ trực tiếp vào các trang trình chiếu của mình.)","The doctor will [insert] a small tube to help drain the fluid. (=Dịch: Bác sĩ sẽ đưa một ống nhỏ vào để giúp dẫn lưu chất lỏng.)"],"ukAudio":"/ai_services/tts3/?q=insert&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%9D%CB%90t%2F","usAudio":"/ai_services/tts3/?q=insert&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%9D%CB%90t%2F"},{"id":"lv_9_40","topic":"Technology and Natural Sciences","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, nghiên cứu kỹ lưỡng","defEn":"an official examination or inquiry into something, such as a crime or problem","examples":["The police launched a thorough [investigation] into the cause of the fire. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về nguyên nhân của vụ hỏa hoạn.)","The scientific [investigation] revealed unexpected results about the disease. (=Dịch: Cuộc nghiên cứu khoa học đã tiết lộ những kết quả bất ngờ về căn bệnh này.)","The journalist conducted an independent [investigation] into local government corruption. (=Dịch: Nhà báo đã thực hiện một cuộc điều tra độc lập về nạn tham nhũng tại chính quyền địa phương.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_41","topic":"Technology and Natural Sciences","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water turns into a clear [liquid] when ice melts at room temperature. (=Dịch: Nước chuyển thành chất lỏng trong suốt khi đá tan ở nhiệt độ phòng.)","Airport security regulations restrict passengers from carrying large bottles of [liquid]. (=Dịch: Quy định an ninh sân bay hạn chế hành khách mang theo các chai chất lỏng lớn.)","The chemist carefully poured the blue [liquid] into a glass beaker. (=Dịch: Nhà hóa học cẩn thận đổ chất lỏng màu xanh vào một cốc thủy tinh thí nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_9_42","topic":"Technology and Natural Sciences","word":"meteorological","pos":"(adj)","ipa":"/ˌmiː.ti.ə.rəˈlɑː.dʒɪ.kəl/","defVi":"(thuộc) khí tượng học","defEn":"relating to the weather and atmospheric conditions","examples":["The [meteorological] office issued a severe storm warning yesterday. (=Dịch: Cơ quan khí tượng đã phát đi cảnh báo bão lớn vào ngày hôm qua.)","Scientists use [meteorological] data to predict global weather patterns. (=Dịch: Các nhà khoa học sử dụng dữ liệu khí tượng để dự đoán các hình thái thời tiết toàn cầu.)","Advanced [meteorological] instruments help track the path of typhoons. (=Dịch: Các thiết bị khí tượng tiên tiến giúp theo dõi đường đi của những cơn bão lớn.)"],"ukAudio":"/ai_services/tts3/?q=meteorological&lang=en-GB&ipa=%2F%CB%8Cmi%CB%90.ti.%C9%99.r%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=meteorological&lang=en-US&ipa=%2F%CB%8Cmi%CB%90.ti.%C9%99.r%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_9_43","topic":"Technology and Natural Sciences","word":"military","pos":"(adj)","ipa":"/ˈmɪl.əˌtɛr.i/","defVi":"thuộc về quân đội, quân sự","defEn":"relating to the armed forces or soldiers","examples":["He decided to pursue a [military] career after graduating from high school. (=Dịch: Anh ấy quyết định theo đuổi sự nghiệp quân sự sau khi tốt nghiệp trung học.)","The government increased its [military] spending this year. (=Dịch: Chính phủ đã tăng chi tiêu quân sự trong năm nay.)","They were wearing traditional [military] uniforms during the parade. (=Dịch: Họ mặc quân phục truyền thống trong suốt buổi diễu binh.)"],"ukAudio":"/ai_services/tts3/?q=military&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Ct%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=military&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Ct%C9%9Br.i%2F"},{"id":"lv_9_44","topic":"Technology and Natural Sciences","word":"monitor","pos":"(v)","ipa":"/ˈmɑː.nə.t̬ɚ/","defVi":"theo dõi, giám sát","defEn":"to observe and check the progress or quality of something over time","examples":["Doctors will carefully [monitor] the patient's heart rate after surgery. (=Dịch: Các bác sĩ sẽ theo dõi cẩn thận nhịp tim của bệnh nhân sau phẫu thuật.)","Scientists use satellites to [monitor] climate changes across the globe. (=Dịch: Các nhà khoa học sử dụng vệ tinh để giám sát những biến đổi khí hậu trên toàn cầu.)","The government set up cameras to [monitor] traffic on the main bridge. (=Dịch: Chính quyền đã lắp đặt camera để theo dõi tình hình giao thông trên cây cầu chính.)"],"ukAudio":"/ai_services/tts3/?q=monitor&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=monitor&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_9_45","topic":"Technology and Natural Sciences","word":"nylon","pos":"(n)","ipa":"/ˈnaɪ.lɑːn/","defVi":"ni-lông, sợi tổng hợp ni-lông","defEn":"a strong, lightweight, synthetic material used for making clothes, ropes, and other items","examples":["Climbing ropes are usually made of strong [nylon] fibers to ensure safety. (=Dịch: Dây leo núi thường được làm từ sợi ni-lông chắc chắn để đảm bảo an toàn.)","The lightweight jacket is crafted from waterproof [nylon] to protect hikers from rain. (=Dịch: Chiếc áo khoác nhẹ được làm từ ni-lông chống thấm nước để bảo vệ người đi bộ đường dài khỏi mưa.)","Toothbrush bristles were originally made from animal hair before [nylon] was invented. (=Dịch: Lông bàn chải đánh răng ban đầu được làm từ lông động vật trước khi ni-lông được phát minh.)"],"ukAudio":"/ai_services/tts3/?q=nylon&lang=en-GB&ipa=%2F%CB%88na%C9%AA.l%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=nylon&lang=en-US&ipa=%2F%CB%88na%C9%AA.l%C9%91%CB%90n%2F"},{"id":"lv_9_46","topic":"Technology and Natural Sciences","word":"operational","pos":"(adj)","ipa":"/ˌɑː.pəˈreɪ.ʃən.əl/","defVi":"sẵn sàng hoạt động, thuộc về vận hành","defEn":"ready to be used, functioning, or relating to the operation of something","examples":["The new railway line will become fully [operational] next month. (=Dịch: Tuyến đường sắt mới sẽ bắt đầu đi vào hoạt động hoàn toàn vào tháng tới.)","The company reduced its [operational] costs by automating several tasks. (=Dịch: Công ty đã giảm chi phí vận hành bằng cách tự động hóa một số nhiệm vụ.)","All security systems are currently [operational] and monitoring the building. (=Dịch: Tất cả hệ thống an ninh hiện đang hoạt động và giám sát tòa nhà.)"],"ukAudio":"/ai_services/tts3/?q=operational&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=operational&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_9_47","topic":"Technology and Natural Sciences","word":"operator","pos":"(n)","ipa":"/ˈɑː.pə.reɪ.t̬ɚ/","defVi":"người vận hành, nhân viên trực tổng đài","defEn":"a person who operates a machine, system, or business","examples":["The crane [operator] lifted the heavy steel beam onto the roof. (=Dịch: Người vận hành cần cẩu đã nâng thanh dầm thép nặng lên mái nhà.)","Please dial zero to speak directly with the telephone [operator]. (=Dịch: Vui lòng bấm số 0 để nói chuyện trực tiếp với nhân viên trực tổng đài.)","The tour [operator] organized all transportation and hotel bookings for our trip. (=Dịch: Đơn vị điều hành tour đã sắp xếp toàn bộ phương tiện đi lại và đặt phòng khách sạn cho chuyến đi của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=operator&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99.re%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=operator&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99.re%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_9_48","topic":"Technology and Natural Sciences","word":"orbit","pos":"(n)","ipa":"/ˈɔːr.bɪt/","defVi":"quỹ đạo","defEn":"the curved path that a planet, moon, or spacecraft follows around another object","examples":["The Earth takes about one year to complete its [orbit] around the sun. (=Dịch: Trái Đất mất khoảng một năm để hoàn thành một vòng quỹ đạo quanh mặt trời.)","The space station is currently in low Earth [orbit]. (=Dịch: Trạm vũ trụ hiện đang ở trên quỹ đạo tầm thấp của Trái Đất.)","Debris in [orbit] poses a serious threat to working spacecraft. (=Dịch: Các mảnh rác trên quỹ đạo tạo ra mối đe dọa nghiêm trọng đối với các tàu vũ trụ đang hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=orbit&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.b%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=orbit&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.b%C9%AAt%2F"},{"id":"lv_9_49","topic":"Technology and Natural Sciences","word":"ozone","pos":"(n)","ipa":"/ˈoʊ.zoʊn/","defVi":"khí ô-dôn","defEn":"a form of oxygen that is harmful at ground level but protects the Earth in the upper atmosphere","examples":["The [ozone] layer protects living organisms from harmful ultraviolet radiation. (=Dịch: Tầng ô-dôn bảo vệ các sinh vật sống khỏi bức xạ cực tím có hại.)","Chemical pollutants have caused serious damage to the [ozone] layer. (=Dịch: Các chất ô nhiễm hóa học đã gây tổn hại nghiêm trọng đến tầng ô-dôn.)","High levels of ground-level [ozone] can cause respiratory problems in humans. (=Dịch: Hàm lượng ô-dôn ở tầng mặt đất cao có thể gây ra các vấn đề về đường hô hấp ở người.)"],"ukAudio":"/ai_services/tts3/?q=ozone&lang=en-GB&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=ozone&lang=en-US&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F"},{"id":"lv_9_50","topic":"Technology and Natural Sciences","word":"particle","pos":"(n)","ipa":"/ˈpɑːr.t̬ɪ.kəl/","defVi":"hạt, phân tử, mảnh nhỏ","defEn":"a very small piece of matter or substance","examples":["Air filters can trap harmful dust [particles] inside your home. (=Dịch: Bộ lọc không khí có thể giữ lại các hạt bụi có hại trong nhà của bạn.)","Scientists study subatomic [particles] to understand the laws of physics. (=Dịch: Các nhà khoa học nghiên cứu các hạt hạ nguyên tử để hiểu các quy luật vật lý.)","There is not a single [particle] of truth in what he said. (=Dịch: Không có lấy một chút sự thật nào trong những gì anh ta nói.)"],"ukAudio":"/ai_services/tts3/?q=particle&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=particle&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F"},{"id":"lv_9_51","topic":"Technology and Natural Sciences","word":"perspective","pos":"(n)","ipa":"/pɚˈspek.tɪv/","defVi":"góc nhìn, quan điểm","defEn":"a particular way of viewing or thinking about something","examples":["Traveling abroad gave her a whole new [perspective] on life. (=Dịch: Đi du lịch nước ngoài đã mang lại cho cô ấy một góc nhìn hoàn toàn mới về cuộc sống.)","We must consider the problem from the customer's [perspective]. (=Dịch: Chúng ta phải xem xét vấn đề từ quan điểm của khách hàng.)","Talking to a mentor helped put his worries into [perspective]. (=Dịch: Nói chuyện với người cố vấn đã giúp anh ấy nhìn nhận lại những lo lắng của mình một cách đúng đắn.)"],"ukAudio":"/ai_services/tts3/?q=perspective&lang=en-GB&ipa=%2Fp%C9%9A%CB%88spek.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=perspective&lang=en-US&ipa=%2Fp%C9%9A%CB%88spek.t%C9%AAv%2F"},{"id":"lv_9_52","topic":"Technology and Natural Sciences","word":"phase","pos":"(n)","ipa":"/feɪz/","defVi":"giai đoạn, thời kỳ","defEn":"a distinct period or stage in a process of development or change","examples":["The construction project is now entering its final [phase]. (=Dịch: Dự án xây dựng hiện đang bước vào giai đoạn cuối cùng.)","Children often go through a difficult [phase] during their teenage years. (=Dịch: Trẻ em thường trải qua một giai đoạn khó khăn trong những năm tháng tuổi vị thành niên.)","The research will be conducted in three separate [phases]. (=Dịch: Nghiên cứu sẽ được tiến hành theo ba giai đoạn riêng biệt.)"],"ukAudio":"/ai_services/tts3/?q=phase&lang=en-GB&ipa=%2Ffe%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=phase&lang=en-US&ipa=%2Ffe%C9%AAz%2F"},{"id":"lv_9_53","topic":"Technology and Natural Sciences","word":"pit","pos":"(n)","ipa":"/ˈpɪt/","defVi":"hố sâu, hầm","defEn":"a large deep hole in the ground","examples":["The workers dug a deep [pit] to lay the foundation of the house. (=Dịch: Các công nhân đã đào một cái hố sâu để đặt móng nhà.)","Be careful not to fall into the gravel [pit]. (=Dịch: Hãy cẩn thận kẻo rơi vào hố sỏi.)","Coal was extracted from the open [pit] mine. (=Dịch: Than đá đã được khai thác từ mỏ lộ thiên.)"],"ukAudio":"/ai_services/tts3/?q=pit&lang=en-GB&ipa=%2F%CB%88p%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pit&lang=en-US&ipa=%2F%CB%88p%C9%AAt%2F"},{"id":"lv_9_54","topic":"Technology and Natural Sciences","word":"plain","pos":"(adj)","ipa":"/pleɪn/","defVi":"đơn giản, mộc mạc, không cầu kỳ","defEn":"simple and not decorated or complicated","examples":["She preferred to wear a [plain] white shirt for the interview. (=Dịch: Cô ấy thích mặc một chiếc áo sơ mi trắng trơn cho buổi phỏng vấn.)","The instructions were written in [plain] language so everyone could understand. (=Dịch: Các hướng dẫn được viết bằng ngôn ngữ đơn giản để mọi người đều có thể hiểu.)","The room was furnished with [plain] wooden tables and chairs. (=Dịch: Căn phòng được trang bị bàn ghế gỗ mộc mạc.)"],"ukAudio":"/ai_services/tts3/?q=plain&lang=en-GB&ipa=%2Fple%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=plain&lang=en-US&ipa=%2Fple%C9%AAn%2F"},{"id":"lv_9_55","topic":"Technology and Natural Sciences","word":"prediction","pos":"(n)","ipa":"/prɪˈdɪk.ʃən/","defVi":"sự dự đoán, lời tiên đoán","defEn":"a statement about what you think will happen in the future","examples":["Scientists made an accurate [prediction] about the path of the incoming hurricane. (=Dịch: Các nhà khoa học đã đưa ra dự đoán chính xác về đường đi của cơn bão sắp tới.)","His pessimistic [prediction] regarding the company's financial growth turned out to be false. (=Dịch: Dự đoán bi quan của anh ấy về sự tăng trưởng tài chính của công ty hóa ra lại sai.)","Technological advancements make weather [prediction] much more reliable than before. (=Dịch: Những tiến bộ công nghệ làm cho việc dự báo thời tiết trở nên đáng tin cậy hơn nhiều so với trước đây.)"],"ukAudio":"/ai_services/tts3/?q=prediction&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88d%C9%AAk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=prediction&lang=en-US&ipa=%2Fpr%C9%AA%CB%88d%C9%AAk.%CA%83%C9%99n%2F"},{"id":"lv_9_56","topic":"Technology and Natural Sciences","word":"proposal","pos":"(n)","ipa":"/prəˈpoʊ.zəl/","defVi":"đề xuất, bản đề án","defEn":"a formal plan or suggestion presented to others for consideration","examples":["The committee rejected the budget [proposal] submitted by the manager. (=Dịch: Ủy ban đã bác bỏ đề xuất ngân sách do người quản lý đệ trình.)","She wrote a detailed research [proposal] to apply for the grant. (=Dịch: Cô ấy đã viết một đề cương nghiên cứu chi tiết để xin tài trợ.)","The government announced a new [proposal] to improve public transport. (=Dịch: Chính phủ đã công bố một đề xuất mới nhằm cải thiện giao thông công cộng.)"],"ukAudio":"/ai_services/tts3/?q=proposal&lang=en-GB&ipa=%2Fpr%C9%99%CB%88po%CA%8A.z%C9%99l%2F","usAudio":"/ai_services/tts3/?q=proposal&lang=en-US&ipa=%2Fpr%C9%99%CB%88po%CA%8A.z%C9%99l%2F"},{"id":"lv_9_57","topic":"Technology and Natural Sciences","word":"pump","pos":"(v)","ipa":"/pʌmp/","defVi":"bơm, hút (chất lỏng hoặc khí)","defEn":"to force liquid or gas to move in a particular direction using a mechanical device","examples":["Firefighters had to [pump] water from a nearby lake to extinguish the blaze. (=Dịch: Lính cứu hỏa đã phải bơm nước từ một hồ gần đó để dập tắt đám cháy.)","The heart works continuously to [pump] blood throughout the human body. (=Dịch: Trái tim hoạt động liên tục để bơm máu đi khắp cơ thể con người.)","They used a special machine to [pump] the flooded water out of the basement. (=Dịch: Họ đã dùng một chiếc máy đặc biệt để bơm nước ngập ra khỏi tầng hầm.)"],"ukAudio":"/ai_services/tts3/?q=pump&lang=en-GB&ipa=%2Fp%CA%8Cmp%2F","usAudio":"/ai_services/tts3/?q=pump&lang=en-US&ipa=%2Fp%CA%8Cmp%2F"},{"id":"lv_9_58","topic":"Technology and Natural Sciences","word":"rebuild","pos":"(v)","ipa":"/ˌri.ˈbɪld/","defVi":"xây dựng lại, tái thiết","defEn":"to build something again after it has been damaged or destroyed","examples":["The government plans to [rebuild] the bridge after the flood. (=Dịch: Chính phủ có kế hoạch xây dựng lại cây cầu sau trận lũ lụt.)","It took many years for the city to [rebuild] its economy. (=Dịch: Phải mất nhiều năm thành phố mới tái thiết được nền kinh tế.)","They are trying to [rebuild] trust after a long period of conflict. (=Dịch: Họ đang cố gắng gầy dựng lại lòng tin sau một thời gian dài mâu thuẫn.)"],"ukAudio":"/ai_services/tts3/?q=rebuild&lang=en-GB&ipa=%2F%CB%8Cri.%CB%88b%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=rebuild&lang=en-US&ipa=%2F%CB%8Cri.%CB%88b%C9%AAld%2F"},{"id":"lv_9_59","topic":"Technology and Natural Sciences","word":"refrigerate","pos":"(v)","ipa":"/rɪˈfrɪdʒ.ə.reɪt/","defVi":"bảo quản lạnh, giữ lạnh trong tủ lạnh","defEn":"to keep food or liquid cold so that it stays fresh","examples":["You should [refrigerate] the milk after opening to keep it fresh. (=Dịch: Bạn nên bảo quản sữa trong tủ lạnh sau khi mở nắp để giữ sữa được tươi.)","Some medicines must be [refrigerated] to maintain their effectiveness. (=Dịch: Một số loại thuốc phải được giữ lạnh để duy trì hiệu quả.)","Do not forget to [refrigerate] any leftover food within two hours. (=Dịch: Đừng quên cất thức ăn thừa vào tủ lạnh trong vòng hai giờ.)"],"ukAudio":"/ai_services/tts3/?q=refrigerate&lang=en-GB&ipa=%2Fr%C9%AA%CB%88fr%C9%AAd%CA%92.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=refrigerate&lang=en-US&ipa=%2Fr%C9%AA%CB%88fr%C9%AAd%CA%92.%C9%99.re%C9%AAt%2F"},{"id":"lv_9_60","topic":"Technology and Natural Sciences","word":"refrigeration","pos":"(n)","ipa":"/rɪˌfrɪdʒ.əˈreɪ.ʃən/","defVi":"sự làm lạnh, sự ướp lạnh, bảo quản lạnh","defEn":"the process of keeping food or other items cold to preserve them","examples":["Fresh meat must be kept under proper [refrigeration] to prevent spoilage. (=Dịch: Thịt tươi phải được bảo quản lạnh đúng cách để tránh bị hư hỏng.)","The development of modern [refrigeration] revolutionized the food industry. (=Dịch: Sự phát triển của kỹ thuật làm lạnh hiện đại đã cách mạng hóa ngành công nghiệp thực phẩm.)","Certain vaccines lose their effectiveness without continuous [refrigeration]. (=Dịch: Một số loại vắc-xin sẽ mất tác dụng nếu không được bảo quản lạnh liên tục.)"],"ukAudio":"/ai_services/tts3/?q=refrigeration&lang=en-GB&ipa=%2Fr%C9%AA%CB%8Cfr%C9%AAd%CA%92.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=refrigeration&lang=en-US&ipa=%2Fr%C9%AA%CB%8Cfr%C9%AAd%CA%92.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_61","topic":"Technology and Natural Sciences","word":"replicate","pos":"(v)","ipa":"/ˈrep.lɪ.keɪt/","defVi":"tái tạo, sao chép, làm lại y hệt","defEn":"to copy, repeat, or reproduce something exactly","examples":["Other researchers tried to [replicate] the laboratory experiment to confirm the results. (=Dịch: Các nhà nghiên cứu khác đã cố gắng tái tạo lại thí nghiệm trong phòng thí nghiệm để xác nhận kết quả.)","It is difficult to [replicate] the success of such a unique product. (=Dịch: Rất khó để lặp lại sự thành công của một sản phẩm độc đáo như vậy.)","The software allows users to [replicate] 3D designs with extreme accuracy. (=Dịch: Phần mềm này cho phép người dùng sao chép các thiết kế 3D với độ chính xác cực cao.)"],"ukAudio":"/ai_services/tts3/?q=replicate&lang=en-GB&ipa=%2F%CB%88rep.l%C9%AA.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=replicate&lang=en-US&ipa=%2F%CB%88rep.l%C9%AA.ke%C9%AAt%2F"},{"id":"lv_9_62","topic":"Technology and Natural Sciences","word":"rescue","pos":"(n)","ipa":"/ˈres.kjuː/","defVi":"cuộc giải cứu, sự cứu hộ","defEn":"an act of saving someone or something from danger or harm","examples":["The coastguard carried out a daring sea [rescue] during the storm. (=Dịch: Lực lượng bảo vệ bờ biển đã thực hiện một cuộc cứu hộ trên biển đầy táo bạo trong cơn bão.)","Firefighters arrived just in time to assist with the [rescue] of the trapped residents. (=Dịch: Lính cứu hỏa đã đến kịp thời để hỗ trợ giải cứu những cư dân bị mắc kẹt.)","The animal [rescue] team helped find homes for hundreds of stray dogs. (=Dịch: Đội cứu hộ động vật đã giúp tìm nhà cho hàng trăm chú chó vô gia cư.)"],"ukAudio":"/ai_services/tts3/?q=rescue&lang=en-GB&ipa=%2F%CB%88res.kju%CB%90%2F","usAudio":"/ai_services/tts3/?q=rescue&lang=en-US&ipa=%2F%CB%88res.kju%CB%90%2F"},{"id":"lv_9_63","topic":"Technology and Natural Sciences","word":"rid","pos":"(v)","ipa":"/rɪd/","defVi":"loại bỏ, tống khứ, giải thoát","defEn":"to make someone or something free from an unwanted person or thing","examples":["They used special chemicals to [rid] the house of insects. (=Dịch: Họ đã dùng hóa chất đặc biệt để loại bỏ côn trùng ra khỏi nhà.)","He wanted to [rid] himself of all his old debts before buying a car. (=Dịch: Anh ấy muốn thanh toán hết nợ cũ trước khi mua một chiếc xe hơi.)","Regular exercise can help [rid] your body of stress and tension. (=Dịch: Tập thể dục thường xuyên có thể giúp cơ thể bạn giải tỏa căng thẳng và áp lực.)"],"ukAudio":"/ai_services/tts3/?q=rid&lang=en-GB&ipa=%2Fr%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rid&lang=en-US&ipa=%2Fr%C9%AAd%2F"},{"id":"lv_9_64","topic":"Technology and Natural Sciences","word":"robot","pos":"(n)","ipa":"/ˈroʊ.bɑːt/","defVi":"người máy, rô-bốt","defEn":"a machine controlled by a computer that can perform tasks automatically","examples":["The car factory uses an advanced [robot] to assemble engine parts. (=Dịch: Nhà máy ô tô sử dụng một người máy tiên tiến để lắp ráp các bộ phận động cơ.)","Scientists designed a small [robot] capable of exploring deep underwater caves. (=Dịch: Các nhà khoa học đã thiết kế một rô-bốt nhỏ có khả năng khám phá các hang động sâu dưới nước.)","This household [robot] can vacuum the floor and clean the windows. (=Dịch: Rô-bốt gia dụng này có thể hút bụi sàn nhà và lau cửa sổ.)"],"ukAudio":"/ai_services/tts3/?q=robot&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=robot&lang=en-US&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F"},{"id":"lv_9_65","topic":"Technology and Natural Sciences","word":"robotic","pos":"(adj)","ipa":"/roʊˈbɑː.tɪk/","defVi":"thuộc về người máy, tự động hóa","defEn":"connected with or produced by robots","examples":["Surgeons now use [robotic] arms to perform precise operations. (=Dịch: Các bác sĩ phẫu thuật hiện sử dụng cánh tay rô-bốt để thực hiện các ca mổ chính xác.)","The company invested heavily in [robotic] technology to boost productivity. (=Dịch: Công ty đã đầu tư mạnh vào công nghệ tự động hóa rô-bốt để nâng cao năng suất.)","He spoke in a cold, [robotic] tone that lacked any emotion. (=Dịch: Anh ấy nói với giọng điệu lạnh lùng, như người máy và thiếu cảm xúc.)"],"ukAudio":"/ai_services/tts3/?q=robotic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88b%C9%91%CB%90.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=robotic&lang=en-US&ipa=%2Fro%CA%8A%CB%88b%C9%91%CB%90.t%C9%AAk%2F"},{"id":"lv_9_66","topic":"Technology and Natural Sciences","word":"safely","pos":"(adv)","ipa":"/ˈseɪf.li/","defVi":"một cách an toàn","defEn":"in a way that is not dangerous or likely to cause harm","examples":["The pilot landed the airplane [safely] despite the heavy storm. (=Dịch: Phi công đã hạ cánh máy bay an toàn bất chấp cơn bão lớn.)","Please make sure your seatbelt is fastened [safely]. (=Dịch: Vui lòng đảm bảo rằng dây an toàn của bạn đã được cài chặt an toàn.)","The hikers arrived [safely] at the mountain base before dark. (=Dịch: Những người đi bộ đường dài đã đến chân núi an toàn trước khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=safely&lang=en-GB&ipa=%2F%CB%88se%C9%AAf.li%2F","usAudio":"/ai_services/tts3/?q=safely&lang=en-US&ipa=%2F%CB%88se%C9%AAf.li%2F"},{"id":"lv_9_67","topic":"Technology and Natural Sciences","word":"satellite","pos":"(n)","ipa":"/ˈsæt̬.əl.aɪt/","defVi":"vệ tinh","defEn":"an electronic device sent into space to gather information or transmit communications","examples":["Weather forecasters rely on [satellite] images to track incoming storms. (=Dịch: Các nhà dự báo thời tiết dựa vào hình ảnh vệ tinh để theo dõi những cơn bão sắp tới.)","The new telecommunications [satellite] was launched into space yesterday. (=Dịch: Vệ tinh viễn thông mới đã được phóng vào không gian ngày hôm qua.)","GPS navigation systems depend on a network of orbiting [satellites]. (=Dịch: Hệ thống định vị GPS phụ thuộc vào một mạng lưới các vệ tinh quay quanh quỹ đạo.)"],"ukAudio":"/ai_services/tts3/?q=satellite&lang=en-GB&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99l.a%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=satellite&lang=en-US&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99l.a%C9%AAt%2F"},{"id":"lv_9_68","topic":"Technology and Natural Sciences","word":"solar","pos":"(adj)","ipa":"/ˈsoʊ.lɚ/","defVi":"(thuộc) mặt trời, năng lượng mặt trời","defEn":"relating to or coming from the sun","examples":["Many households are installing [solar] panels to reduce electricity bills. (=Dịch: Nhiều hộ gia đình đang lắp đặt các tấm pin mặt trời để giảm hóa đơn tiền điện.)","The Earth is the third planet from the sun in our [solar] system. (=Dịch: Trái Đất là hành tinh thứ ba tính từ mặt trời trong hệ mặt trời của chúng ta.)","The company invests heavily in [solar] energy research. (=Dịch: Công ty đầu tư mạnh vào nghiên cứu năng lượng mặt trời.)"],"ukAudio":"/ai_services/tts3/?q=solar&lang=en-GB&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=solar&lang=en-US&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F"},{"id":"lv_9_69","topic":"Technology and Natural Sciences","word":"sustainable","pos":"(adj)","ipa":"/səˈsteɪ.nə.bəl/","defVi":"bền vững, thân thiện với môi trường","defEn":"able to be maintained over time without harming the environment","examples":["We need to adopt more [sustainable] farming practices to protect the soil. (=Dịch: Chúng ta cần áp dụng các phương pháp canh tác bền vững hơn để bảo vệ đất đai.)","The company is committed to using [sustainable] packaging materials. (=Dịch: Công ty cam kết sử dụng các vật liệu đóng gói bền vững.)","Cycling is a [sustainable] form of urban transportation. (=Dịch: Đi xe đạp là một hình thức giao thông đô thị bền vững.)"],"ukAudio":"/ai_services/tts3/?q=sustainable&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sustainable&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F"},{"id":"lv_9_70","topic":"Technology and Natural Sciences","word":"textile","pos":"(n)","ipa":"/ˈtɛks.taɪl/","defVi":"vải dệt, hàng dệt may","defEn":"any type of cloth or woven fabric","examples":["The country's economy relies heavily on the export of [textile] products. (=Dịch: Nền kinh tế của đất nước phụ thuộc rất lớn vào việc xuất khẩu các sản phẩm dệt may.)","Workers in the [textile] factory operate modern weaving machines every day. (=Dịch: Công nhân trong nhà máy dệt vận hành máy dệt hiện đại mỗi ngày.)","Museum visitors admired the intricate patterns of ancient Egyptian [textile] relics. (=Dịch: Khách tham quan bảo tàng đã chiêm ngưỡng những hoa văn tinh xảo của các di vật dệt may Ai Cập cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=textile&lang=en-GB&ipa=%2F%CB%88t%C9%9Bks.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=textile&lang=en-US&ipa=%2F%CB%88t%C9%9Bks.ta%C9%AAl%2F"},{"id":"lv_9_71","topic":"Technology and Natural Sciences","word":"tribal","pos":"(adj)","ipa":"/ˈtraɪ.bəl/","defVi":"thuộc bộ lạc, bộ tộc","defEn":"relating to a tribe or a group of people sharing common ancestors, customs, and traditions","examples":["The anthropologists spent two years studying [tribal] customs in remote rainforests. (=Dịch: Các nhà nhân chủng học đã dành hai năm để nghiên cứu các phong tục bộ lạc ở những khu rừng nhiệt đới xa xôi.)","Traditional [tribal] music was played during the village's annual harvest festival. (=Dịch: Âm nhạc bộ tộc truyền thống đã được biểu diễn trong lễ hội thu hoạch hàng năm của ngôi làng.)","The elders act as leaders and make important decisions for the [tribal] community. (=Dịch: Các bô lão đóng vai trò là những người lãnh đạo và đưa ra các quyết định quan trọng cho cộng đồng bộ lạc.)"],"ukAudio":"/ai_services/tts3/?q=tribal&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tribal&lang=en-US&ipa=%2F%CB%88tra%C9%AA.b%C9%99l%2F"},{"id":"lv_9_72","topic":"Technology and Natural Sciences","word":"unwilling","pos":"(adj)","ipa":"/ʌnˈwɪl.ɪŋ/","defVi":"không sẵn lòng, miễn cưỡng","defEn":"not wanting to do something and refusing to do it","examples":["He was [unwilling] to admit that he had made a mistake. (=Dịch: Anh ấy không sẵn lòng thừa nhận rằng mình đã phạm sai lầm.)","Many employees were [unwilling] to work overtime without extra pay. (=Dịch: Nhiều nhân viên miễn cưỡng làm thêm giờ mà không có phụ cấp.)","She seemed [unwilling] to share any details about her personal life. (=Dịch: Cô ấy dường như không muốn chia sẻ bất kỳ chi tiết nào về cuộc sống cá nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=unwilling&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=unwilling&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F"},{"id":"lv_9_73","topic":"Technology and Natural Sciences","word":"wool","pos":"(n)","ipa":"/wʊl/","defVi":"len, sợi len hoặc lông cừu","defEn":"the soft, thick hair that grows on the bodies of sheep and some other animals, used to make cloth or yarn","examples":["She knitted a warm sweater made of pure [wool] for her grandfather. (=Dịch: Cô ấy đã đan một chiếc áo len ấm áp bằng len nguyên chất cho ông của mình.)","Australia is known worldwide for its massive production of high-quality sheep [wool]. (=Dịch: Úc nổi tiếng khắp thế giới về sản lượng lông cừu chất lượng cao dồi dào.)","These blankets are blended with [wool] and synthetic fibers to keep costs low. (=Dịch: Những chiếc chăn này được pha trộn giữa len và sợi tổng hợp để giữ giá thành ở mức thấp.)"],"ukAudio":"/ai_services/tts3/?q=wool&lang=en-GB&ipa=%2Fw%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=wool&lang=en-US&ipa=%2Fw%CA%8Al%2F"}]}},{"id":"listening_u5_1","title":"Chủ đề 1/10: Daily Life and Social Activities","actTitle":"Từ vựng chủ đề: Daily Life and Social Activities (344 từ)","problem":{"pType":"topic_flashcards","topic":"Daily Life and Social Activities","count":344,"words":[{"id":"lv_0_0","topic":"Daily Life and Social Activities","word":"accompany","pos":"(v)","ipa":"/əˈkʌm.pə.ni/","defVi":"đi cùng, hộ tống, đồng hành","defEn":"to go somewhere with someone as a companion or guide","examples":["Children must be [accompanied] by an adult at the swimming pool. (=Dịch: Trẻ em phải có người lớn đi kèm khi ở hồ bơi.)","He offered to [accompany] her to the train station. (=Dịch: Anh ấy đã đề nghị đi cùng cô ấy ra ga tàu.)","A mild fever often [accompanies] the common cold. (=Dịch: Sốt nhẹ thường đi kèm với bệnh cảm lạnh thông thường.)"],"ukAudio":"/ai_services/tts3/?q=accompany&lang=en-GB&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=accompany&lang=en-US&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F"},{"id":"lv_0_1","topic":"Daily Life and Social Activities","word":"advanced","pos":"(adj)","ipa":"/ədˈvænst/","defVi":"nâng cao, tiên tiến","defEn":"at a higher, more difficult, or modern level","examples":["This course is designed for [advanced] learners of English. (=Dịch: Khóa học này được thiết kế dành cho người học tiếng Anh ở trình độ nâng cao.)","Scientists are using [advanced] technology to predict weather patterns. (=Dịch: Các nhà khoa học đang sử dụng công nghệ tiên tiến để dự đoán các hình thái thời tiết.)","The country has an [advanced] public healthcare system. (=Dịch: Quốc gia này có một hệ thống y tế công cộng tiên tiến.)"],"ukAudio":"/ai_services/tts3/?q=advanced&lang=en-GB&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F","usAudio":"/ai_services/tts3/?q=advanced&lang=en-US&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F"},{"id":"lv_0_2","topic":"Daily Life and Social Activities","word":"amazed","pos":"(adj)","ipa":"/əˈmeɪzd/","defVi":"kinh ngạc, vô cùng ngạc nhiên","defEn":"extremely surprised or impressed by something","examples":["I was [amazed] at how quickly the children learned the new language. (=Dịch: Tôi đã rất kinh ngạc trước việc lũ trẻ học ngôn ngữ mới nhanh đến thế.)","Visitors were [amazed] by the beauty of the ancient temple. (=Dịch: Du khách đã vô cùng kinh ngạc trước vẻ đẹp của ngôi đền cổ.)","She was [amazed] to discover that she had won first prize. (=Dịch: Cô ấy đã rất ngạc nhiên khi biết mình đạt giải nhất.)"],"ukAudio":"/ai_services/tts3/?q=amazed&lang=en-GB&ipa=%2F%C9%99%CB%88me%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=amazed&lang=en-US&ipa=%2F%C9%99%CB%88me%C9%AAzd%2F"},{"id":"lv_0_3","topic":"Daily Life and Social Activities","word":"ambition","pos":"(n)","ipa":"/æmˈbɪʃ.ən/","defVi":"tham vọng, hoài bão","defEn":"a strong desire to achieve success, power, or a specific goal","examples":["Her lifelong [ambition] is to become a successful doctor. (=Dịch: Hoài bão cả đời của cô ấy là trở thành một bác sĩ thành đạt.)","He lacks the [ambition] needed to reach the top of his profession. (=Dịch: Anh ấy thiếu tham vọng cần thiết để vươn tới đỉnh cao trong nghề nghiệp của mình.)","The company has clear [ambitions] to expand into international markets. (=Dịch: Công ty có những tham vọng rõ ràng nhằm mở rộng ra các thị trường quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=ambition&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=ambition&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_0_4","topic":"Daily Life and Social Activities","word":"antique","pos":"(n)","ipa":"/ænˈtiːk/","defVi":"đồ cổ","defEn":"an object that is old and often valuable because of its age or quality","examples":["This wooden table is a valuable [antique] from the nineteenth century. (=Dịch: Chiếc bàn gỗ này là một món đồ cổ có giá trị từ thế kỷ 19.)","She loves spending her weekends browsing [antique] shops. (=Dịch: Cô ấy thích dành những ngày cuối tuần để dạo xem các cửa hàng đồ cổ.)","The museum displays rare [antiques] collected from all over the world. (=Dịch: Bảo tàng trưng bày các cổ vật quý hiếm được sưu tầm từ khắp nơi trên thế giới.)"],"ukAudio":"/ai_services/tts3/?q=antique&lang=en-GB&ipa=%2F%C3%A6n%CB%88ti%CB%90k%2F","usAudio":"/ai_services/tts3/?q=antique&lang=en-US&ipa=%2F%C3%A6n%CB%88ti%CB%90k%2F"},{"id":"lv_0_5","topic":"Daily Life and Social Activities","word":"anymore","pos":"(adv)","ipa":"/ˌen.iˈmɔːr/","defVi":"nữa, không còn nữa","defEn":"any longer; used in negative statements to show that a situation has ended","examples":["He does not live in that city [anymore]. (=Dịch: Anh ấy không còn sống ở thành phố đó nữa.)","They rarely talk to each other [anymore]. (=Dịch: Họ hiếm khi nói chuyện với nhau nữa.)","I don't think we need this old equipment [anymore]. (=Dịch: Tôi không nghĩ chúng ta còn cần thiết bị cũ này nữa.)"],"ukAudio":"/ai_services/tts3/?q=anymore&lang=en-GB&ipa=%2F%CB%8Cen.i%CB%88m%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=anymore&lang=en-US&ipa=%2F%CB%8Cen.i%CB%88m%C9%94%CB%90r%2F"},{"id":"lv_0_6","topic":"Daily Life and Social Activities","word":"applicant","pos":"(n)","ipa":"/ˈæp.lɪ.kənt/","defVi":"người nộp đơn, ứng viên","defEn":"a person who formally applies for something, especially a job or a place at a university","examples":["There were more than fifty [applicants] for the marketing position. (=Dịch: Đã có hơn 50 ứng viên ứng tuyển vào vị trí tiếp thị.)","Successful [applicants] will be contacted within two weeks. (=Dịch: Những ứng viên trúng tuyển sẽ được liên hệ trong vòng hai tuần.)","Each [applicant] must submit a resume and two letters of recommendation. (=Dịch: Mỗi ứng viên phải nộp một sơ yếu lý lịch và hai thư giới thiệu.)"],"ukAudio":"/ai_services/tts3/?q=applicant&lang=en-GB&ipa=%2F%CB%88%C3%A6p.l%C9%AA.k%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=applicant&lang=en-US&ipa=%2F%CB%88%C3%A6p.l%C9%AA.k%C9%99nt%2F"},{"id":"lv_0_7","topic":"Daily Life and Social Activities","word":"appointment","pos":"(n)","ipa":"/əˈpɔɪnt.mənt/","defVi":"cuộc hẹn, lịch hẹn","defEn":"an arrangement to see someone at a specific time and place","examples":["I made an [appointment] with my doctor for tomorrow morning. (=Dịch: Tôi đã đặt lịch hẹn với bác sĩ vào sáng mai.)","She had to cancel her dental [appointment] due to a meeting. (=Dịch: Cô ấy đã phải hủy cuộc hẹn khám răng vì một cuộc họp.)","Please arrive on time for your visa [appointment]. (=Dịch: Vui lòng đến đúng giờ cho cuộc hẹn xin thị thực của bạn.)"],"ukAudio":"/ai_services/tts3/?q=appointment&lang=en-GB&ipa=%2F%C9%99%CB%88p%C9%94%C9%AAnt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=appointment&lang=en-US&ipa=%2F%C9%99%CB%88p%C9%94%C9%AAnt.m%C9%99nt%2F"},{"id":"lv_0_8","topic":"Daily Life and Social Activities","word":"aquarium","pos":"(n)","ipa":"/əˈkwer.i.əm/","defVi":"bể nuôi cá, thủy cung","defEn":"a glass tank or a building where fish and other water animals are kept for study or display","examples":["We took the children to the city [aquarium] to see the sharks. (=Dịch: Chúng tôi đã đưa lũ trẻ đến thủy cung thành phố để ngắm cá mập.)","He keeps several colorful tropical fish in his home [aquarium]. (=Dịch: Anh ấy nuôi vài chú cá nhiệt đới sặc sỡ trong bể cá tại nhà.)","The new [aquarium] features marine life from coral reefs around the world. (=Dịch: Thủy cung mới trưng bày các loài sinh vật biển từ các rạn san hô trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=aquarium&lang=en-GB&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=aquarium&lang=en-US&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F"},{"id":"lv_0_9","topic":"Daily Life and Social Activities","word":"asthma","pos":"(n)","ipa":"/ˈæz.mə/","defVi":"bệnh hen suyễn","defEn":"a chronic medical condition that causes difficulty in breathing","examples":["Cold weather can often trigger a severe [asthma] attack. (=Dịch: Thời tiết lạnh thường có thể gây ra một cơn hen suyễn nghiêm trọng.)","He always carries an inhaler because he suffers from [asthma]. (=Dịch: Anh ấy luôn mang theo ống hít vì bị bệnh hen suyễn.)","Air pollution is known to worsen symptoms of childhood [asthma]. (=Dịch: Ô nhiễm không khí được biết là làm trầm trọng thêm các triệu chứng hen suyễn ở trẻ em.)"],"ukAudio":"/ai_services/tts3/?q=asthma&lang=en-GB&ipa=%2F%CB%88%C3%A6z.m%C9%99%2F","usAudio":"/ai_services/tts3/?q=asthma&lang=en-US&ipa=%2F%CB%88%C3%A6z.m%C9%99%2F"},{"id":"lv_0_10","topic":"Daily Life and Social Activities","word":"attic","pos":"(n)","ipa":"/ˈæt̬.ɪk/","defVi":"gác xép, tầng áp mái","defEn":"a room or space just below the roof of a house","examples":["We found a box of old photographs stored in the [attic]. (=Dịch: Chúng tôi tìm thấy một hộp ảnh cũ được cất trên gác mái.)","She decided to convert the dusty [attic] into a quiet study room. (=Dịch: Cô ấy quyết định cải tạo căn gác mái đầy bụi thành một phòng học yên tĩnh.)","During the storm, we could hear the rain pounding above the [attic]. (=Dịch: Trong suốt cơn bão, chúng tôi có thể nghe thấy tiếng mưa trút xuống ngay trên gác mái.)"],"ukAudio":"/ai_services/tts3/?q=attic&lang=en-GB&ipa=%2F%CB%88%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=attic&lang=en-US&ipa=%2F%CB%88%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_0_11","topic":"Daily Life and Social Activities","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"điểm thu hút, điểm tham quan; sức hấp dẫn","defEn":"an interesting or lively place to visit, or a feature that makes something appealing","examples":["The Eiffel Tower is a major tourist [attraction] in Paris. (=Dịch: Tháp Eiffel là một điểm thu hút khách du lịch lớn ở Paris.)","Low cost of living is one of the main [attraction]s of moving to this city. (=Dịch: Chi phí sinh hoạt thấp là một trong những điểm hấp dẫn chính khi chuyển đến thành phố này.)","The museum added a new interactive [attraction] for young children. (=Dịch: Bảo tàng đã bổ sung một điểm trải nghiệm tương tác mới dành cho trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_0_12","topic":"Daily Life and Social Activities","word":"avenue","pos":"(n)","ipa":"/ˈæv.ə.nuː/","defVi":"đại lộ; con đường, hướng tiếp cận","defEn":"a wide street in a town or city, or a possible way of achieving something","examples":["Trees were planted on both sides of the broad [avenue]. (=Dịch: Cây xanh được trồng ở cả hai bên của đại lộ rộng lớn.)","Scientists are exploring every possible [avenue] of research to find a cure. (=Dịch: Các nhà khoa học đang khám phá mọi hướng nghiên cứu có thể để tìm ra phương pháp chữa trị.)","The luxury hotel is located on Fifth [Avenue]. (=Dịch: Khách sạn sang trọng này tọa lạc trên Đại lộ số 5.)"],"ukAudio":"/ai_services/tts3/?q=avenue&lang=en-GB&ipa=%2F%CB%88%C3%A6v.%C9%99.nu%CB%90%2F","usAudio":"/ai_services/tts3/?q=avenue&lang=en-US&ipa=%2F%CB%88%C3%A6v.%C9%99.nu%CB%90%2F"},{"id":"lv_0_13","topic":"Daily Life and Social Activities","word":"backpack","pos":"(n)","ipa":"/ˈbæk.pæk/","defVi":"ba lô","defEn":"a bag with shoulder straps that allows it to be carried on one's back","examples":["He packed a few clothes and a water bottle into his [backpack]. (=Dịch: Anh ấy xếp vài bộ quần áo và một chai nước vào ba lô của mình.)","Carrying a heavy [backpack] every day can cause back pain for students. (=Dịch: Đeo ba lô nặng mỗi ngày có thể gây đau lưng cho học sinh.)","She zipped up her [backpack] and headed for the train station. (=Dịch: Cô ấy kéo khóa ba lô lại rồi hướng về phía nhà ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=backpack&lang=en-GB&ipa=%2F%CB%88b%C3%A6k.p%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=backpack&lang=en-US&ipa=%2F%CB%88b%C3%A6k.p%C3%A6k%2F"},{"id":"lv_0_14","topic":"Daily Life and Social Activities","word":"backpacker","pos":"(n)","ipa":"/ˈbækˌpæk.ɚ/","defVi":"khách du lịch bụi, dân phượt","defEn":"a person who travels cheaply carrying their belongings in a backpack","examples":["The hostel is extremely popular among young [backpacker]s from Europe. (=Dịch: Nhà nghỉ giá rẻ này cực kỳ phổ biến đối với những bạn trẻ đi du lịch bụi đến từ châu Âu.)","As a budget [backpacker], he prefers cooking his own meals to save money. (=Dịch: Là một người đi du lịch bụi tiết kiệm, anh ấy thích tự nấu ăn để tiết kiệm chi phí.)","Many [backpacker]s visit Southeast Asia for its rich culture and low costs. (=Dịch: Nhiều khách du lịch bụi ghé thăm Đông Nam Á vì nền văn hóa phong phú và chi phí rẻ.)"],"ukAudio":"/ai_services/tts3/?q=backpacker&lang=en-GB&ipa=%2F%CB%88b%C3%A6k%CB%8Cp%C3%A6k.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=backpacker&lang=en-US&ipa=%2F%CB%88b%C3%A6k%CB%8Cp%C3%A6k.%C9%9A%2F"},{"id":"lv_0_15","topic":"Daily Life and Social Activities","word":"badminton","pos":"(n)","ipa":"/ˈbæd.mɪn.tən/","defVi":"môn cầu lông","defEn":"a racquet sport played using shuttles across a net","examples":["They usually play [badminton] in the park on weekend mornings. (=Dịch: Họ thường chơi cầu lông trong công viên vào các buổi sáng cuối tuần.)","You need quick reflexes and good agility to excel at [badminton]. (=Dịch: Bạn cần có phản xạ nhanh và sự nhanh nhẹn tốt để chơi xuất sắc môn cầu lông.)","She bought a new pair of shoes designed specifically for [badminton]. (=Dịch: Cô ấy đã mua một đôi giày mới được thiết kế dành riêng cho môn cầu lông.)"],"ukAudio":"/ai_services/tts3/?q=badminton&lang=en-GB&ipa=%2F%CB%88b%C3%A6d.m%C9%AAn.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=badminton&lang=en-US&ipa=%2F%CB%88b%C3%A6d.m%C9%AAn.t%C9%99n%2F"},{"id":"lv_0_16","topic":"Daily Life and Social Activities","word":"balcony","pos":"(n)","ipa":"/ˈbæl.kə.ni/","defVi":"ban công","defEn":"a platform enclosed by a railing projecting from the wall of a building","examples":["We enjoyed having our morning coffee on the hotel [balcony]. (=Dịch: Chúng tôi rất thích thưởng thức cà phê buổi sáng ngoài ban công khách sạn.)","She filled her small apartment [balcony] with colorful flowers and potted plants. (=Dịch: Cô ấy lấp đầy ban công căn hộ nhỏ của mình bằng những bông hoa rực rỡ và các chậu cây cảnh.)","From the [balcony], you can see a breathtaking view of the ocean. (=Dịch: Từ ban công, bạn có thể chiêm ngưỡng khung cảnh tuyệt đẹp của đại dương.)"],"ukAudio":"/ai_services/tts3/?q=balcony&lang=en-GB&ipa=%2F%CB%88b%C3%A6l.k%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=balcony&lang=en-US&ipa=%2F%CB%88b%C3%A6l.k%C9%99.ni%2F"},{"id":"lv_0_17","topic":"Daily Life and Social Activities","word":"ballet","pos":"(n)","ipa":"/bæˈleɪ/","defVi":"múa ba lê","defEn":"a classical artistic dance form characterized by precise and graceful movements","examples":["She has been taking [ballet] lessons since she was five years old. (=Dịch: Cô ấy đã học múa ba lê từ khi mới năm tuổi.)","The theater is hosting a famous Russian [ballet] performance tonight. (=Dịch: Tối nay nhà hát tổ chức một buổi biểu diễn múa ba lê Nga nổi tiếng.)","Professional [ballet] dancers require tremendous discipline and physical strength. (=Dịch: Các vũ công ba lê chuyên nghiệp đòi hỏi tính kỷ luật cao và thể lực phi thường.)"],"ukAudio":"/ai_services/tts3/?q=ballet&lang=en-GB&ipa=%2Fb%C3%A6%CB%88le%C9%AA%2F","usAudio":"/ai_services/tts3/?q=ballet&lang=en-US&ipa=%2Fb%C3%A6%CB%88le%C9%AA%2F"},{"id":"lv_0_18","topic":"Daily Life and Social Activities","word":"balloon","pos":"(n)","ipa":"/bəˈluːn/","defVi":"bóng bay, khinh khí cầu","defEn":"a flexible bag inflated with air or gas, used as a toy or decoration","examples":["They decorated the party room with colorful [balloon]s and streamers. (=Dịch: Họ trang trí phòng tiệc bằng những quả bóng bay rực rỡ sắc màu và dây kim tuyến.)","The child cried when his helium [balloon] floated up into the sky. (=Dịch: Đứa trẻ òa khóc khi quả bóng bay khí heli của mình bay vút lên bầu trời.)","Taking a hot-air [balloon] ride over the valley was an unforgettable experience. (=Dịch: Đi khinh khí cầu ngắm nhìn thung lũng là một trải nghiệm khó quên.)"],"ukAudio":"/ai_services/tts3/?q=balloon&lang=en-GB&ipa=%2Fb%C9%99%CB%88lu%CB%90n%2F","usAudio":"/ai_services/tts3/?q=balloon&lang=en-US&ipa=%2Fb%C9%99%CB%88lu%CB%90n%2F"},{"id":"lv_0_19","topic":"Daily Life and Social Activities","word":"bamboo","pos":"(n)","ipa":"/bæmˈbu/","defVi":"cây tre, nứa","defEn":"a tall tropical grass with hard, hollow stems used for building or making things","examples":["Pandas feed almost entirely on [bamboo]. (=Dịch: Gấu trúc gần như chỉ ăn [tre].)","The local builders used [bamboo] to construct the scaffolding. (=Dịch: Những người thợ xây địa phương đã sử dụng [tre] để dựng giàn giáo.)","This cutting board is made from eco-friendly [bamboo]. (=Dịch: Chiếc thớt này được làm từ [tre] thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=bamboo&lang=en-GB&ipa=%2Fb%C3%A6m%CB%88bu%2F","usAudio":"/ai_services/tts3/?q=bamboo&lang=en-US&ipa=%2Fb%C3%A6m%CB%88bu%2F"},{"id":"lv_0_20","topic":"Daily Life and Social Activities","word":"barbecue","pos":"(n)","ipa":"/ˈbɑr.bə.kju/","defVi":"tiệc nướng ngoài trời, món thịt nướng","defEn":"an outdoor meal or party where food is cooked over an open fire or grill","examples":["We are having a [barbecue] in the backyard this Saturday. (=Dịch: Chúng tôi sẽ tổ chức một bữa tiệc [thịt nướng] ở sân sau vào thứ Bảy này.)","He grilled some chicken and sausages on the [barbecue]. (=Dịch: Anh ấy đã nướng một ít thịt gà và xúc xích trên [bếp nướng].)","They served delicious pork ribs with homemade [barbecue] sauce. (=Dịch: Họ phục vụ món sườn heo thơm ngon với sốt [thịt nướng] tự làm.)"],"ukAudio":"/ai_services/tts3/?q=barbecue&lang=en-GB&ipa=%2F%CB%88b%C9%91r.b%C9%99.kju%2F","usAudio":"/ai_services/tts3/?q=barbecue&lang=en-US&ipa=%2F%CB%88b%C9%91r.b%C9%99.kju%2F"},{"id":"lv_0_21","topic":"Daily Life and Social Activities","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a part of the coast where the land curves inward to form a wide opening","examples":["The hotel room has a magnificent view of the [bay]. (=Dịch: Phòng khách sạn có tầm nhìn tuyệt đẹp ra [vịnh].)","Several fishing boats were anchored safely in the [bay]. (=Dịch: Một vài chiếc thuyền đánh cá đã neo đậu an toàn trong [vịnh].)","Ha Long [Bay] is one of the most famous tourist attractions in Vietnam. (=Dịch: [Vịnh] Hạ Long là một trong những điểm du lịch nổi tiếng nhất ở Việt Nam.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_0_22","topic":"Daily Life and Social Activities","word":"bedsit","pos":"(n)","ipa":"/ˈbed.sɪt/","defVi":"phòng trọ khép kín (vừa làm phòng khách, phòng ngủ)","defEn":"a rented room used for both living and sleeping, usually with shared bathroom facilities","examples":["As a university student, he lived in a small [bedsit] near the campus. (=Dịch: Khi còn là sinh viên đại học, anh ấy sống trong một [căn phòng trọ khép kín] nhỏ gần khuôn viên trường.)","Renting a [bedsit] is a budget-friendly option for young professionals. (=Dịch: Thuê một [căn phòng trọ nhỏ] là một lựa chọn tiết kiệm chi phí cho những người trẻ mới đi làm.)","Her tiny [bedsit] only had space for a single bed and a desk. (=Dịch: [Căn phòng trọ] nhỏ bé của cô chỉ có đủ chỗ cho một chiếc giường đơn và một chiếc bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=bedsit&lang=en-GB&ipa=%2F%CB%88bed.s%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bedsit&lang=en-US&ipa=%2F%CB%88bed.s%C9%AAt%2F"},{"id":"lv_0_23","topic":"Daily Life and Social Activities","word":"behalf","pos":"(n)","ipa":"/bɪˈhæf/","defVi":"sự thay mặt, đại diện","defEn":"as a representative of someone, or in the interest of someone","examples":["I am writing this email on [behalf] of the marketing department. (=Dịch: Tôi viết email này thay [mặt] bộ phận tiếp thị.)","The lawyer spoke on [behalf] of his client in court. (=Dịch: Luật sư đã thay [mặt] thân chủ của mình phát biểu trước tòa.)","She accepted the award on [behalf] of the entire research team. (=Dịch: Cô ấy đã nhận giải thưởng thay [mặt] toàn bộ nhóm nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=behalf&lang=en-GB&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=behalf&lang=en-US&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F"},{"id":"lv_0_24","topic":"Daily Life and Social Activities","word":"belonging","pos":"(n)","ipa":"/bɪˈlɔŋ.ɪŋ/","defVi":"đồ dùng cá nhân; cảm giác thuộc về","defEn":"a person's movable possession; the state of being part of a group or place","examples":["Please check your seat to make sure you have left no personal [belonging] behind. (=Dịch: Vui lòng kiểm tra chỗ ngồi để đảm bảo bạn không để quên bất kỳ [đồ dùng] cá nhân nào.)","Schools should foster a strong sense of [belonging] among students. (=Dịch: Các trường học nên bồi đắp [cảm giác thuộc về] mạnh mẽ cho học sinh.)","Every single [belonging] was packed carefully into cardboard boxes. (=Dịch: Từng món [đồ đạc] đều được đóng gói cẩn thận vào các thùng carton.)"],"ukAudio":"/ai_services/tts3/?q=belonging&lang=en-GB&ipa=%2Fb%C9%AA%CB%88l%C9%94%C5%8B.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=belonging&lang=en-US&ipa=%2Fb%C9%AA%CB%88l%C9%94%C5%8B.%C9%AA%C5%8B%2F"},{"id":"lv_0_25","topic":"Daily Life and Social Activities","word":"bent","pos":"(adj)","ipa":"/bent/","defVi":"bị cong, gập lại; kiên quyết làm gì","defEn":"curved or no longer straight; having an inclination toward something","examples":["The bicycle wheel was badly [bent] after the collision. (=Dịch: Bánh xe đạp bị [cong] nặng sau vụ va chạm.)","He sat for hours with a [bent] back, working on his computer. (=Dịch: Anh ấy ngồi hàng giờ với chiếc lưng [còng] để làm việc trên máy tính.)","She seems [bent] on finishing the project before the weekend. (=Dịch: Cô ấy có vẻ [quyết tâm] hoàn thành dự án trước cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=bent&lang=en-GB&ipa=%2Fbent%2F","usAudio":"/ai_services/tts3/?q=bent&lang=en-US&ipa=%2Fbent%2F"},{"id":"lv_0_26","topic":"Daily Life and Social Activities","word":"bet","pos":"(v)","ipa":"/bet/","defVi":"đánh cược, cá cược; dám chắc","defEn":"to risk money on the result of an event or competition; to feel sure about something","examples":["He lost a lot of money when he decided to [bet] on horse racing. (=Dịch: Anh ấy đã mất rất nhiều tiền khi quyết định [cá cược] vào môn đua ngựa.)","I [bet] that it will rain before the afternoon is over. (=Dịch: Tôi [cá] rằng trời sẽ mưa trước khi buổi chiều kết thúc.)","Never [bet] more than you can afford to lose. (=Dịch: Đừng bao giờ [đặt cược] nhiều hơn số tiền bạn có thể chấp nhận mất.)"],"ukAudio":"/ai_services/tts3/?q=bet&lang=en-GB&ipa=%2Fbet%2F","usAudio":"/ai_services/tts3/?q=bet&lang=en-US&ipa=%2Fbet%2F"},{"id":"lv_0_27","topic":"Daily Life and Social Activities","word":"blanket","pos":"(n)","ipa":"/ˈblæŋ.kɪt/","defVi":"chiếc chăn, mền","defEn":"a thick, warm cover made of wool or cloth used on a bed","examples":["She pulled the wool [blanket] over her shoulders to stay warm. (=Dịch: Cô kéo chiếc [chăn] len qua vai để giữ ấm.)","A thick [blanket] of snow covered the entire village overnight. (=Dịch: Một [lớp] tuyết dày đã bao phủ toàn bộ ngôi làng chỉ sau một đêm.)","The flight attendant gave each passenger a pillow and a [blanket]. (=Dịch: Tiếp viên hàng không đã phát cho mỗi hành khách một chiếc gối và một chiếc [chăn].)"],"ukAudio":"/ai_services/tts3/?q=blanket&lang=en-GB&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=blanket&lang=en-US&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F"},{"id":"lv_0_28","topic":"Daily Life and Social Activities","word":"blind","pos":"(adj)","ipa":"/blaɪnd/","defVi":"mù, khiếm thị; mù quáng","defEn":"unable to see; not noticing or realizing something clearly","examples":["Guide dogs are specially trained to assist [blind] people. (=Dịch: Chó dẫn đường được huấn luyện đặc biệt để hỗ trợ người [khiếm thị].)","He was completely [blind] to the risks involved in the investment. (=Dịch: Anh ấy hoàn toàn [mù quáng] trước những rủi ro đi kèm với khoản đầu tư.)","The sudden flash of bright light made her momentarily [blind]. (=Dịch: Ánh sáng chói lóa đột ngột khiến cô ấy tạm thời bị [lóa mắt/mù tạm thời].)"],"ukAudio":"/ai_services/tts3/?q=blind&lang=en-GB&ipa=%2Fbla%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=blind&lang=en-US&ipa=%2Fbla%C9%AAnd%2F"},{"id":"lv_0_29","topic":"Daily Life and Social Activities","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, nhà sách","defEn":"a shop that sells books","examples":["I spent the entire afternoon browsing in a small second-hand [bookshop]. (=Dịch: Tôi đã dành cả buổi chiều để dạo xem sách trong một hiệu sách cũ nhỏ.)","The local [bookshop] is hosting a signing event with a famous author this weekend. (=Dịch: Hiệu sách địa phương sẽ tổ chức một buổi ký tặng sách với một tác giả nổi tiếng vào cuối tuần này.)","You can order academic textbooks directly from the university [bookshop]. (=Dịch: Bạn có thể đặt mua giáo trình học thuật trực tiếp từ hiệu sách của trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_0_30","topic":"Daily Life and Social Activities","word":"botanical","pos":"(adj)","ipa":"/bəˈtæn.ɪ.kəl/","defVi":"(thuộc) thực vật học","defEn":"connected with the scientific study of plants","examples":["The city is famous for its extensive [botanical] gardens filled with rare flowers. (=Dịch: Thành phố này nổi tiếng với các vườn bách thảo rộng lớn tràn ngập các loài hoa quý hiếm.)","Researchers collected various [botanical] specimens during their expedition in the rainforest. (=Dịch: Các nhà nghiên cứu đã thu thập nhiều mẫu thực vật khác nhau trong chuyến thám hiểm rừng nhiệt đới.)","This skincare cream contains natural [botanical] extracts that soothe the skin. (=Dịch: Loại kem dưỡng da này chứa các chiết xuất thực vật tự nhiên giúp làm dịu da.)"],"ukAudio":"/ai_services/tts3/?q=botanical&lang=en-GB&ipa=%2Fb%C9%99%CB%88t%C3%A6n.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=botanical&lang=en-US&ipa=%2Fb%C9%99%CB%88t%C3%A6n.%C9%AA.k%C9%99l%2F"},{"id":"lv_0_31","topic":"Daily Life and Social Activities","word":"bother","pos":"(v)","ipa":"/ˈbɑː.ðɚ/","defVi":"làm phiền, bận tâm, quấy rầy","defEn":"to annoy, worry, or cause trouble to someone","examples":["I am sorry to [bother] you, but could you help me carry these heavy boxes? (=Dịch: Xin lỗi vì đã làm phiền bạn, nhưng bạn có thể giúp tôi khiêng những chiếc hộp nặng này được không?)","Loud traffic noises from the street do not seem to [bother] him at all. (=Dịch: Tiếng ồn giao thông lớn từ đường phố dường như không làm phiền anh ấy chút nào.)","She did not even [bother] to reply to my email after I sent it twice. (=Dịch: Cô ấy thậm chí còn chẳng buồn trả lời email sau khi tôi đã gửi tới hai lần.)"],"ukAudio":"/ai_services/tts3/?q=bother&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F","usAudio":"/ai_services/tts3/?q=bother&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F"},{"id":"lv_0_32","topic":"Daily Life and Social Activities","word":"bow","pos":"(v)","ipa":"/baʊ/","defVi":"cúi đầu, cúi chào","defEn":"to bend your head or body forward as a sign of respect or greeting","examples":["In Japan, it is customary to [bow] politely when greeting someone for the first time. (=Dịch: Ở Nhật Bản, cúi chào một cách lịch sự khi chào hỏi ai đó lần đầu tiên là một phong tục.)","The actors came onto the stage together to [bow] to the applauding audience. (=Dịch: Các diễn viên cùng nhau bước lên sân khấu để cúi chào khán giả đang vỗ tay tán thưởng.)","He had to [bow] his head slightly to avoid hitting the low ceiling doorway. (=Dịch: Anh ấy phải hơi cúi đầu xuống để tránh va vào khung cửa trần thấp.)"],"ukAudio":"/ai_services/tts3/?q=bow&lang=en-GB&ipa=%2Fba%CA%8A%2F","usAudio":"/ai_services/tts3/?q=bow&lang=en-US&ipa=%2Fba%CA%8A%2F"},{"id":"lv_0_33","topic":"Daily Life and Social Activities","word":"brochure","pos":"(n)","ipa":"/broʊˈʃʊr/","defVi":"sách/tờ rơi quảng cáo, tài liệu giới thiệu","defEn":"a small booklet containing pictures and information about a product or service","examples":["We picked up a travel [brochure] at the tourism office to plan our holiday itinerary. (=Dịch: Chúng tôi đã lấy một cuốn cẩm nang du lịch tại văn phòng du lịch để lên lịch trình cho kỳ nghỉ.)","The company published a detailed [brochure] highlighting its latest line of software. (=Dịch: Công ty đã phát hành một cuốn tài liệu quảng cáo chi tiết nêu bật dòng phần mềm mới nhất của mình.)","Prospective students can read the college [brochure] to learn more about available courses. (=Dịch: Các sinh viên tương lai có thể đọc tài liệu giới thiệu của trường đại học để tìm hiểu thêm về các khóa học hiện có.)"],"ukAudio":"/ai_services/tts3/?q=brochure&lang=en-GB&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=brochure&lang=en-US&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_0_34","topic":"Daily Life and Social Activities","word":"buffet","pos":"(n)","ipa":"/bəˈfeɪ/","defVi":"tiệc buffet, bữa ăn tự chọn","defEn":"a meal where people serve themselves from a table containing different dishes","examples":["The hotel offers a complimentary breakfast [buffet] with a wide selection of hot dishes. (=Dịch: Khách sạn phục vụ bữa sáng tự chọn miễn phí với nhiều lựa chọn món nóng phong phú.)","Guests enjoyed the seafood [buffet] at the wedding reception last night. (=Dịch: Khách mời đã thưởng thức tiệc tự chọn hải sản tại tiệc cưới tối qua.)","We decided to eat at an all-you-can-eat barbecue [buffet] for our celebration dinner. (=Dịch: Chúng tôi quyết định ăn tại một bữa tiệc nướng tự chọn không giới hạn cho bữa tối liên hoan.)"],"ukAudio":"/ai_services/tts3/?q=buffet&lang=en-GB&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=buffet&lang=en-US&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F"},{"id":"lv_0_35","topic":"Daily Life and Social Activities","word":"bulb","pos":"(n)","ipa":"/bʌlb/","defVi":"bóng đèn","defEn":"a glass object that produces light when electricity passes through it","examples":["The light [bulb] in the kitchen burned out and needs to be replaced immediately. (=Dịch: Bóng đèn trong bếp đã bị cháy và cần được thay thế ngay lập tức.)","Switching to energy-efficient LED [bulb] options can significantly reduce your electricity bill. (=Dịch: Chuyển sang các lựa chọn bóng đèn LED tiết kiệm năng lượng có thể giúp giảm đáng kể hóa đơn tiền điện của bạn.)","She adjusted the desk lamp and screwed in a softer, warmer [bulb] for reading. (=Dịch: Cô ấy đã điều chỉnh đèn bàn và vặn vào một bóng đèn có ánh sáng dịu hơn, ấm áp hơn để đọc sách.)"],"ukAudio":"/ai_services/tts3/?q=bulb&lang=en-GB&ipa=%2Fb%CA%8Clb%2F","usAudio":"/ai_services/tts3/?q=bulb&lang=en-US&ipa=%2Fb%CA%8Clb%2F"},{"id":"lv_0_36","topic":"Daily Life and Social Activities","word":"bush","pos":"(n)","ipa":"/bʊʃ/","defVi":"bụi cây, bụi rậm","defEn":"a plant with many woody stems growing from near the ground; a shrub","examples":["A small rabbit quickly darted into the thick green [bush] to hide from the dog. (=Dịch: Một con thỏ nhỏ nhanh chóng lao vào bụi cây xanh rậm rạp để trốn con chó.)","My father spent the whole morning pruning the rose [bush] in the front yard. (=Dịch: Bố tôi đã dành cả buổi sáng để cắt tỉa bụi hoa hồng ở sân trước.)","They planted a row of flowering [bush] varieties along the garden fence. (=Dịch: Họ đã trồng một hàng các loại cây bụi có hoa dọc theo hàng rào khu vườn.)"],"ukAudio":"/ai_services/tts3/?q=bush&lang=en-GB&ipa=%2Fb%CA%8A%CA%83%2F","usAudio":"/ai_services/tts3/?q=bush&lang=en-US&ipa=%2Fb%CA%8A%CA%83%2F"},{"id":"lv_0_37","topic":"Daily Life and Social Activities","word":"cabinet","pos":"(n)","ipa":"/ˈkæb.ə.nət/","defVi":"tủ đựng đồ; nội các chính phủ","defEn":"a piece of furniture with shelves or drawers, or a group of senior government ministers","examples":["Please put the clean plates back into the kitchen [cabinet] above the sink. (=Dịch: Vui lòng xếp đĩa sạch trở lại vào tủ bếp phía trên bồn rửa.)","The Prime Minister met with his [cabinet] to discuss urgent economic reforms. (=Dịch: Thủ tướng đã họp với nội các của mình để thảo luận về các cải cách kinh tế cấp bách.)","We store all our medical supplies and first-aid kits inside the bathroom [cabinet]. (=Dịch: Chúng tôi cất giữ toàn bộ vật tư y tế và bộ sơ cứu bên trong tủ phòng tắm.)"],"ukAudio":"/ai_services/tts3/?q=cabinet&lang=en-GB&ipa=%2F%CB%88k%C3%A6b.%C9%99.n%C9%99t%2F","usAudio":"/ai_services/tts3/?q=cabinet&lang=en-US&ipa=%2F%CB%88k%C3%A6b.%C9%99.n%C9%99t%2F"},{"id":"lv_0_38","topic":"Daily Life and Social Activities","word":"calendar","pos":"(n)","ipa":"/ˈkæl.ən.dɚ/","defVi":"lịch, cuốn lịch","defEn":"a chart or system showing the days, weeks, and months of a particular year","examples":["I marked the exam date on my wall [calendar] so I would not forget it. (=Dịch: Tôi đã đánh dấu ngày thi trên lịch treo tường để không bị quên.)","You can sync your digital [calendar] across your phone, tablet, and laptop. (=Dịch: Bạn có thể đồng bộ hóa lịch kỹ thuật số trên điện thoại, máy tính bảng và máy tính xách tay của mình.)","The academic [calendar] indicates that the spring semester starts in early February. (=Dịch: Lịch học cho biết học kỳ mùa xuân sẽ bắt đầu vào đầu tháng Hai.)"],"ukAudio":"/ai_services/tts3/?q=calendar&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=calendar&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F"},{"id":"lv_0_39","topic":"Daily Life and Social Activities","word":"caller","pos":"(n)","ipa":"/ˈkɑː.lɚ/","defVi":"người gọi điện thoại","defEn":"a person who makes a telephone call","examples":["The receptionist asked the [caller] to hold the line for a moment. (=Dịch: Nhân viên lễ tân đã yêu cầu người gọi giữ máy một lát.)","An anonymous [caller] reported the traffic accident to the police. (=Dịch: Một người gọi nặc danh đã trình báo vụ tai nạn giao thông cho cảnh sát.)","The radio host answered questions from the first [caller] of the morning. (=Dịch: Người dẫn chương trình phát thanh đã trả lời các câu hỏi từ người gọi đầu tiên trong buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=caller&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=caller&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%9A%2F"},{"id":"lv_0_40","topic":"Daily Life and Social Activities","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"nước Canada","defEn":"a large country located in the northern part of North America","examples":["Many international students choose to study in [Canada] each year. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Canada mỗi năm.)","Winter in [Canada] can be extremely cold with heavy snowfall. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá với tuyết rơi dày.)","She traveled across [Canada] by train to admire the natural scenery. (=Dịch: Cô ấy đã đi du lịch xuyên Canada bằng tàu hỏa để chiêm ngưỡng phong cảnh thiên nhiên.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_0_41","topic":"Daily Life and Social Activities","word":"cancel","pos":"(v)","ipa":"/ˈkæn.səl/","defVi":"hủy bỏ","defEn":"to decide that an organized event or activity will not happen","examples":["The airline had to [cancel] all flights due to the severe storm. (=Dịch: Hãng hàng không đã phải hủy tất cả các chuyến bay do cơn bão nghiêm trọng.)","They decided to [cancel] the outdoor concert because of heavy rain. (=Dịch: Họ quyết định hủy buổi hòa nhạc ngoài trời vì trời mưa lớn.)","You can [cancel] your subscription anytime without extra fees. (=Dịch: Bạn có thể hủy gói đăng ký của mình bất cứ lúc nào mà không phải trả thêm phí.)"],"ukAudio":"/ai_services/tts3/?q=cancel&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cancel&lang=en-US&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F"},{"id":"lv_0_42","topic":"Daily Life and Social Activities","word":"cancellation","pos":"(n)","ipa":"/ˌkæn.səˈleɪ.ʃən/","defVi":"sự hủy bỏ","defEn":"a decision or statement that an event or service will not take place","examples":["The sudden [cancellation] of the meeting surprised everyone in the office. (=Dịch: Việc hủy cuộc họp đột ngột khiến mọi người trong văn phòng đều bất ngờ.)","Hotel guests may incur a fee for a late [cancellation]. (=Dịch: Khách lưu trú tại khách sạn có thể phải chịu phí nếu hủy phòng muộn.)","Flight [cancellation] rates increased dramatically during the winter blizzard. (=Dịch: Tỷ lệ hủy chuyến bay đã tăng mạnh trong trận bão tuyết mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=cancellation&lang=en-GB&ipa=%2F%CB%8Ck%C3%A6n.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cancellation&lang=en-US&ipa=%2F%CB%8Ck%C3%A6n.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_43","topic":"Daily Life and Social Activities","word":"cardboard","pos":"(n)","ipa":"/ˈkɑːrd.bɔːrd/","defVi":"bìa các-tông","defEn":"thick, stiff paper used especially for making boxes","examples":["We packed all the heavy books into large [cardboard] boxes. (=Dịch: Chúng tôi đã đóng gói tất cả sách nặng vào các thùng bìa các tông lớn.)","The children built a toy castle out of recycled [cardboard]. (=Dịch: Những đứa trẻ đã dựng một lâu đài đồ chơi từ bìa các tông tái chế.)","You should flatten the [cardboard] before putting it in the recycling bin. (=Dịch: Bạn nên làm phẳng bìa các tông trước khi bỏ vào thùng rác tái chế.)"],"ukAudio":"/ai_services/tts3/?q=cardboard&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90rd.b%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=cardboard&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90rd.b%C9%94%CB%90rd%2F"},{"id":"lv_0_44","topic":"Daily Life and Social Activities","word":"carer","pos":"(n)","ipa":"/ˈker.ɚ/","defVi":"người chăm sóc","defEn":"someone who looks after a person who is young, old, or sick","examples":["She works as a full-time [carer] for her elderly grandmother. (=Dịch: Cô ấy làm người chăm sóc toàn thời gian cho người bà cao tuổi của mình.)","The local council offers support programs for every unpaid [carer]. (=Dịch: Hội đồng địa phương cung cấp các chương trình hỗ trợ cho mọi người chăm sóc không nhận thù lao.)","Being a primary [carer] can be physically and emotionally demanding. (=Dịch: Làm người chăm sóc chính có thể rất vất vả cả về thể chất lẫn tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=carer&lang=en-GB&ipa=%2F%CB%88ker.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=carer&lang=en-US&ipa=%2F%CB%88ker.%C9%9A%2F"},{"id":"lv_0_45","topic":"Daily Life and Social Activities","word":"caretaker","pos":"(n)","ipa":"/ˈkerˌteɪ.kɚ/","defVi":"người trông nom, người quản gia","defEn":"a person employed to take care of a building or piece of land","examples":["The school [caretaker] arrived early in the morning to unlock the gates. (=Dịch: Bác bảo vệ trường đã đến từ sáng sớm để mở cổng.)","They hired a [caretaker] to look after the holiday villa during the winter. (=Dịch: Họ đã thuê một người trông nom để chăm sóc căn biệt thự nghỉ dưỡng trong suốt mùa đông.)","The [caretaker] is responsible for routine maintenance and minor repairs. (=Dịch: Người quản lý chịu trách nhiệm bảo trì định kỳ và sửa chữa nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=caretaker&lang=en-GB&ipa=%2F%CB%88ker%CB%8Cte%C9%AA.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=caretaker&lang=en-US&ipa=%2F%CB%88ker%CB%8Cte%C9%AA.k%C9%9A%2F"},{"id":"lv_0_46","topic":"Daily Life and Social Activities","word":"caring","pos":"(adj)","ipa":"/ˈker.ɪŋ/","defVi":"chu đáo, giàu lòng quan tâm","defEn":"displaying kindness, concern, and empathy for others","examples":["He is a deeply [caring] person who always helps those in need. (=Dịch: Anh ấy là một người rất giàu lòng quan tâm, luôn giúp đỡ những ai gặp khó khăn.)","The nurses provided a [caring] environment for all the patients. (=Dịch: Các y tá đã mang lại một môi trường chăm sóc chu đáo cho tất cả bệnh nhân.)","Children thrive best in a supportive and [caring] family atmosphere. (=Dịch: Trẻ em phát triển tốt nhất trong bầu không khí gia đình tràn đầy yêu thương và luôn hỗ trợ lẫn nhau.)"],"ukAudio":"/ai_services/tts3/?q=caring&lang=en-GB&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=caring&lang=en-US&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F"},{"id":"lv_0_47","topic":"Daily Life and Social Activities","word":"carve","pos":"(v)","ipa":"/kɑːrv/","defVi":"khắc, chạm, tạc","defEn":"to make objects or designs by cutting wood, stone, or other hard materials","examples":["The artist used a sharp chisel to [carve] a wooden statue. (=Dịch: Nghệ sĩ đã sử dụng một chiếc đục sắc bén để chạm khắc bức tượng gỗ.)","They decided to [carve] their initials onto the old tree trunk. (=Dịch: Họ quyết định khắc tên viết tắt của mình lên thân cây già.)","He learned how to [carve] a roasted turkey for the holiday dinner. (=Dịch: Anh ấy đã học cách xẻ thịt gà tây nướng cho bữa tối ngày lễ.)"],"ukAudio":"/ai_services/tts3/?q=carve&lang=en-GB&ipa=%2Fk%C9%91%CB%90rv%2F","usAudio":"/ai_services/tts3/?q=carve&lang=en-US&ipa=%2Fk%C9%91%CB%90rv%2F"},{"id":"lv_0_48","topic":"Daily Life and Social Activities","word":"cathedral","pos":"(n)","ipa":"/kəˈθiː.drəl/","defVi":"nhà thờ lớn, thánh đường","defEn":"the principal Christian church of a diocese, associated with a bishop","examples":["The ancient [cathedral] attracts thousands of tourists every summer. (=Dịch: Nhà thờ chính tòa cổ kính thu hút hàng ngàn du khách vào mỗi mùa hè.)","Beautiful stained glass windows adorn the walls of the Gothic [cathedral]. (=Dịch: Những ô cửa kính màu tuyệt đẹp tô điểm cho các bức tường của nhà thờ chính tòa phong cách Gothic.)","We climbed to the top of the [cathedral] tower for a panoramic view of the city. (=Dịch: Chúng tôi đã leo lên đỉnh tháp nhà thờ chính tòa để ngắm nhìn toàn cảnh thành phố.)"],"ukAudio":"/ai_services/tts3/?q=cathedral&lang=en-GB&ipa=%2Fk%C9%99%CB%88%CE%B8i%CB%90.dr%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cathedral&lang=en-US&ipa=%2Fk%C9%99%CB%88%CE%B8i%CB%90.dr%C9%99l%2F"},{"id":"lv_0_49","topic":"Daily Life and Social Activities","word":"centimetre","pos":"(n)","ipa":"/ˈsɛn.tɪˌmi.t̬ɚ/","defVi":"xăng-ti-mét (cm)","defEn":"a metric unit of length equal to one hundredth of a meter","examples":["The plant grew about one [centimetre] every week. (=Dịch: Cái cây đã phát triển thêm khoảng một centimet mỗi tuần.)","You should leave a margin of two [centimetres] on each side of the page. (=Dịch: Bạn nên chừa lề hai centimet ở mỗi bên của trang giấy.)","The rainfall measured only a few [centimetres] during the dry season. (=Dịch: Lượng mưa chỉ đo được vài centimet trong suốt mùa khô.)"],"ukAudio":"/ai_services/tts3/?q=centimetre&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.t%C9%AA%CB%8Cmi.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=centimetre&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.t%C9%AA%CB%8Cmi.t%CC%AC%C9%9A%2F"},{"id":"lv_0_50","topic":"Daily Life and Social Activities","word":"ceremony","pos":"(n)","ipa":"/ˈsɛr.əˌmoʊ.ni/","defVi":"nghi thức, nghi lễ, buổi lễ","defEn":"a formal event held on a special occasion, often with traditional rituals","examples":["The opening [ceremony] of the Olympic Games was truly magnificent. (=Dịch: Lễ khai mạc Thế vận hội Olympic thực sự rất tráng lệ.)","They decided to have a simple wedding [ceremony] with close friends. (=Dịch: Họ quyết định tổ chức một lễ cưới đơn giản cùng với những người bạn thân thiết.)","The graduation [ceremony] will take place in the main auditorium tomorrow. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại khán phòng chính vào ngày mai.)"],"ukAudio":"/ai_services/tts3/?q=ceremony&lang=en-GB&ipa=%2F%CB%88s%C9%9Br.%C9%99%CB%8Cmo%CA%8A.ni%2F","usAudio":"/ai_services/tts3/?q=ceremony&lang=en-US&ipa=%2F%CB%88s%C9%9Br.%C9%99%CB%8Cmo%CA%8A.ni%2F"},{"id":"lv_0_51","topic":"Daily Life and Social Activities","word":"certificate","pos":"(n)","ipa":"/sɚˈtɪf.ə.kət/","defVi":"chứng chỉ, giấy chứng nhận","defEn":"an official document that proves a fact, qualification, or achievement","examples":["She received a [certificate] of completion after finishing the language course. (=Dịch: Cô ấy đã nhận được chứng chỉ hoàn thành sau khi kết thúc khóa học ngôn ngữ.)","You must present your birth [certificate] when applying for a passport. (=Dịch: Bạn phải xuất trình giấy khai sinh khi nộp đơn xin cấp hộ chiếu.)","He framed his teaching [certificate] and hung it in his office. (=Dịch: Anh ấy đã đóng khung chứng chỉ giảng dạy của mình và treo nó trong văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=certificate&lang=en-GB&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F","usAudio":"/ai_services/tts3/?q=certificate&lang=en-US&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F"},{"id":"lv_0_52","topic":"Daily Life and Social Activities","word":"champion","pos":"(n)","ipa":"/ˈtʃæm.pi.ən/","defVi":"nhà vô địch, quán quân","defEn":"a person, animal, or team that has won a competition","examples":["She became the youngest world chess [champion] in history. (=Dịch: Cô ấy đã trở thành nhà vô địch cờ vua thế giới trẻ tuổi nhất trong lịch sử.)","The defending [champion] was defeated in the final round of the tournament. (=Dịch: Nhà đương kim vô địch đã bị đánh bại ở vòng chung kết của giải đấu.)","Our local basketball team aims to be the league [champion] this season. (=Dịch: Đội bóng rổ địa phương của chúng tôi đặt mục tiêu trở thành nhà vô địch giải đấu mùa này.)"],"ukAudio":"/ai_services/tts3/?q=champion&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6m.pi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=champion&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6m.pi.%C9%99n%2F"},{"id":"lv_0_53","topic":"Daily Life and Social Activities","word":"cheque","pos":"(n)","ipa":"/tʃɛk/","defVi":"tấm séc, chi phiếu","defEn":"a printed document that orders a bank to pay a specific amount of money from someone's account","examples":["He wrote a [cheque] to pay for the monthly rent. (=Dịch: Anh ấy đã viết một tấm séc để trả tiền thuê nhà hàng tháng.)","The store does not accept payment by [cheque] anymore. (=Dịch: Cửa hàng không còn chấp nhận thanh toán bằng séc nữa.)","She deposited the salary [cheque] into her savings account this morning. (=Dịch: Cô ấy đã gửi tấm séc tiền lương vào tài khoản tiết kiệm của mình sáng nay.)"],"ukAudio":"/ai_services/tts3/?q=cheque&lang=en-GB&ipa=%2Ft%CA%83%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=cheque&lang=en-US&ipa=%2Ft%CA%83%C9%9Bk%2F"},{"id":"lv_0_54","topic":"Daily Life and Social Activities","word":"chervil","pos":"(n)","ipa":"/ˈtʃɝ.vɪl/","defVi":"ngò tây Pháp, rau mùi tây Pháp (chervil)","defEn":"an herb with delicate leaves similar to parsley, used in cooking for its mild flavor","examples":["The chef sprinkled freshly chopped [chervil] over the fish dish. (=Dịch: Đầu bếp đã rắc rau mùi tây Pháp băm nhỏ tươi lên món cá.)","You can substitute parsley if you cannot find [chervil] at the grocery store. (=Dịch: Bạn có thể dùng ngò tây thay thế nếu không tìm thấy rau mùi tây Pháp ở cửa hàng tạp hóa.)","This traditional French soup is flavored with tarragon and [chervil]. (=Dịch: Món súp truyền thống của Pháp này được tăng hương vị với ngải thơm và rau mùi tây Pháp.)"],"ukAudio":"/ai_services/tts3/?q=chervil&lang=en-GB&ipa=%2F%CB%88t%CA%83%C9%9D.v%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=chervil&lang=en-US&ipa=%2F%CB%88t%CA%83%C9%9D.v%C9%AAl%2F"},{"id":"lv_0_55","topic":"Daily Life and Social Activities","word":"chest","pos":"(n)","ipa":"/tʃɛst/","defVi":"ngực (cơ thể); rương, hòm (đựng đồ)","defEn":"the front part of the body between the neck and the stomach; or a large, strong box for storage","examples":["He experienced a sudden pain in his [chest] after running up the stairs. (=Dịch: Anh ấy cảm thấy đau ngực đột ngột sau khi chạy lên cầu thang.)","The old wooden [chest] in the attic was filled with vintage photographs. (=Dịch: Chiếc rương gỗ cũ trên gác mái chứa đầy những bức ảnh cổ điển.)","Divers discovered a treasure [chest] lying on the seabed. (=Dịch: Các thợ lặn đã phát hiện một rương kho báu nằm dưới đáy biển.)"],"ukAudio":"/ai_services/tts3/?q=chest&lang=en-GB&ipa=%2Ft%CA%83%C9%9Bst%2F","usAudio":"/ai_services/tts3/?q=chest&lang=en-US&ipa=%2Ft%CA%83%C9%9Bst%2F"},{"id":"lv_0_56","topic":"Daily Life and Social Activities","word":"childcare","pos":"(n)","ipa":"/ˈtʃaɪld.kɛr/","defVi":"việc chăm sóc trẻ em, dịch vụ trông trẻ","defEn":"the care and supervision of young children, especially while parents are working","examples":["High costs of [childcare] make it difficult for many mothers to return to work. (=Dịch: Chi phí chăm sóc trẻ cao khiến nhiều người mẹ gặp khó khăn khi quay trở lại làm việc.)","The company offers on-site [childcare] facilities for its employees. (=Dịch: Công ty cung cấp các cơ sở trông giữ trẻ tại chỗ cho nhân viên của mình.)","Finding reliable [childcare] is a major challenge for working parents. (=Dịch: Tìm kiếm dịch vụ chăm sóc trẻ đáng tin cậy là một thách thức lớn đối với các bậc cha mẹ đi làm.)"],"ukAudio":"/ai_services/tts3/?q=childcare&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.k%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=childcare&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.k%C9%9Br%2F"},{"id":"lv_0_57","topic":"Daily Life and Social Activities","word":"china","pos":"(n)","ipa":"/ˈtʃaɪ.nə/","defVi":"đồ sứ, bát đĩa bằng sứ","defEn":"delicate cups, plates, and dishes made of high-quality white clay (porcelain)","examples":["She only uses the fine [china] when hosting formal dinner parties. (=Dịch: Cô ấy chỉ sử dụng đồ sứ cao cấp khi tổ chức các bữa tiệc tối trang trọng.)","Be very careful not to drop that antique [china] tea cup. (=Dịch: Hãy thật cẩn thận để không làm rơi chiếc tách trà bằng sứ cổ đó.)","The museum displays a rare collection of imperial [china] from centuries ago. (=Dịch: Bảo tàng trưng bày một bộ sưu tập đồ sứ hoàng gia quý hiếm từ nhiều thế kỷ trước.)"],"ukAudio":"/ai_services/tts3/?q=china&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=china&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F"},{"id":"lv_0_58","topic":"Daily Life and Social Activities","word":"chord","pos":"(n)","ipa":"/kɔːrd/","defVi":"hợp âm","defEn":"a combination of three or more musical notes played at the same time","examples":["He learned how to play a basic guitar [chord] during his first music lesson. (=Dịch: Anh ấy đã học cách chơi một hợp âm guitar cơ bản trong buổi học nhạc đầu tiên của mình.)","The song ends with a resonant minor [chord] on the piano. (=Dịch: Bài hát kết thúc bằng một hợp âm thứ vang vọng trên đàn piano.)","Practicing [chord] transitions will improve your rhythm and speed on the keyboard. (=Dịch: Việc luyện tập chuyển hợp âm sẽ cải thiện nhịp điệu và tốc độ của bạn trên phím đàn.)"],"ukAudio":"/ai_services/tts3/?q=chord&lang=en-GB&ipa=%2Fk%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=chord&lang=en-US&ipa=%2Fk%C9%94%CB%90rd%2F"},{"id":"lv_0_59","topic":"Daily Life and Social Activities","word":"circular","pos":"(adj)","ipa":"/ˈsɝ.kjə.lɚ/","defVi":"có hình tròn; vòng tròn, luẩn quẩn","defEn":"having the form of a circle; round, or moving in a circle","examples":["The guests gathered around a large [circular] table for dinner. (=Dịch: Các vị khách quây quần quanh một chiếc bàn tròn lớn để dùng bữa tối.)","The bus follows a [circular] route around the city center. (=Dịch: Xe buýt chạy theo một tuyến đường vòng quanh trung tâm thành phố.)","His argument was [circular] and failed to prove any real point. (=Dịch: Lập luận của anh ấy luẩn quẩn và không chứng minh được quan điểm thực sự nào.)"],"ukAudio":"/ai_services/tts3/?q=circular&lang=en-GB&ipa=%2F%CB%88s%C9%9D.kj%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=circular&lang=en-US&ipa=%2F%CB%88s%C9%9D.kj%C9%99.l%C9%9A%2F"},{"id":"lv_0_60","topic":"Daily Life and Social Activities","word":"cleaner","pos":"(n)","ipa":"/ˈkli.nɚ/","defVi":"người quét dọn; chất tẩy rửa","defEn":"a person whose job is to clean rooms or buildings, or a substance used for cleaning","examples":["The office [cleaner] empties the bins every evening. (=Dịch: Nhân viên vệ sinh văn phòng đổ các thùng rác vào mỗi buổi tối.)","You should use a special glass [cleaner] to remove those smudges. (=Dịch: Bạn nên sử dụng nước lau kính chuyên dụng để làm sạch những vết mờ đó.)","She works as a part-time [cleaner] at the local hospital. (=Dịch: Cô ấy làm công việc dọn dẹp bán thời gian tại bệnh viện địa phương.)"],"ukAudio":"/ai_services/tts3/?q=cleaner&lang=en-GB&ipa=%2F%CB%88kli.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cleaner&lang=en-US&ipa=%2F%CB%88kli.n%C9%9A%2F"},{"id":"lv_0_61","topic":"Daily Life and Social Activities","word":"clinic","pos":"(n)","ipa":"/ˈklɪn.ɪk/","defVi":"phòng khám","defEn":"a place where people receive medical treatment or advice","examples":["She made an appointment at the local dental [clinic]. (=Dịch: Cô ấy đã đặt lịch hẹn tại phòng khám nha khoa địa phương.)","The health [clinic] offers free vaccinations for young children. (=Dịch: Phòng khám y tế cung cấp vắc-xin miễn phí cho trẻ nhỏ.)","He had to visit the [clinic] for a routine check-up. (=Dịch: Anh ấy phải đến phòng khám để kiểm tra sức khỏe định kỳ.)"],"ukAudio":"/ai_services/tts3/?q=clinic&lang=en-GB&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=clinic&lang=en-US&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F"},{"id":"lv_0_62","topic":"Daily Life and Social Activities","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng giữ đồ (áo khoác, túi xách)","defEn":"a room where coats, bags, and hats can be left temporarily","examples":["Please leave your heavy winter coat in the [cloakroom] before entering the theater. (=Dịch: Vui lòng để lại áo khoác mùa đông dày của bạn ở phòng giữ đồ trước khi vào nhà hát.)","The attendant in the [cloakroom] gave me a numbered ticket. (=Dịch: Người phục vụ ở phòng giữ đồ đã đưa cho tôi một chiếc vé có đánh số.)","They set up a temporary [cloakroom] near the entrance of the exhibition hall. (=Dịch: Họ đã dựng một phòng giữ đồ tạm thời gần lối vào của sảnh triển lãm.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_0_63","topic":"Daily Life and Social Activities","word":"clubhouse","pos":"(n)","ipa":"/ˈklʌb.haʊs/","defVi":"nhà câu lạc bộ (nơi sinh hoạt chung)","defEn":"a building used by members of a club for meetings or social activities","examples":["The golfers met in the [clubhouse] for lunch after their match. (=Dịch: Các tay gôn đã gặp nhau tại nhà sinh hoạt câu lạc bộ để ăn trưa sau trận đấu.)","Members can relax and enjoy drinks on the [clubhouse] terrace. (=Dịch: Các hội viên có thể thư giãn và thưởng thức đồ uống trên sân thượng của nhà câu lạc bộ.)","The team celebrated their championship victory at the sports [clubhouse]. (=Dịch: Đội đã ăn mừng chiến thắng chức vô địch tại nhà câu lạc bộ thể thao.)"],"ukAudio":"/ai_services/tts3/?q=clubhouse&lang=en-GB&ipa=%2F%CB%88kl%CA%8Cb.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=clubhouse&lang=en-US&ipa=%2F%CB%88kl%CA%8Cb.ha%CA%8As%2F"},{"id":"lv_0_64","topic":"Daily Life and Social Activities","word":"collector","pos":"(n)","ipa":"/kəˈlek.tɚ/","defVi":"nhà sưu tầm; người thu (tiền, vé)","defEn":"a person who collects particular objects as a hobby or for an organization","examples":["He is a passionate stamp [collector] who owns rare specimens from all over the world. (=Dịch: Ông là một người đam mê sưu tập tem, sở hữu những mẫu tem quý hiếm từ khắp nơi trên thế giới.)","An antique [collector] bought the old painting at an auction. (=Dịch: Một nhà sưu tập đồ cổ đã mua bức tranh cũ trong một buổi đấu giá.)","The tax [collector] visited the shop to check their financial records. (=Dịch: Nhân viên thu thuế đã đến cửa hàng để kiểm tra sổ sách tài chính của họ.)"],"ukAudio":"/ai_services/tts3/?q=collector&lang=en-GB&ipa=%2Fk%C9%99%CB%88lek.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=collector&lang=en-US&ipa=%2Fk%C9%99%CB%88lek.t%C9%9A%2F"},{"id":"lv_0_65","topic":"Daily Life and Social Activities","word":"commitment","pos":"(n)","ipa":"/kəˈmɪt.mənt/","defVi":"sự cam kết, sự tận tụy","defEn":"a promise or firm decision to do something, or devotion to a cause","examples":["He showed great [commitment] to his studies and passed with high marks. (=Dịch: Anh ấy đã thể hiện sự tận tâm to lớn cho việc học và đỗ đạt với điểm số cao.)","The company made a long-term [commitment] to reduce carbon emissions. (=Dịch: Công ty đã đưa ra một cam kết dài hạn nhằm giảm lượng khí thải carbon.)","A successful relationship requires mutual trust and strong [commitment]. (=Dịch: Một mối quan hệ thành công đòi hỏi sự tin tưởng lẫn nhau và sự gắn kết bền chặt.)"],"ukAudio":"/ai_services/tts3/?q=commitment&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=commitment&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F"},{"id":"lv_0_66","topic":"Daily Life and Social Activities","word":"committee","pos":"(n)","ipa":"/kəˈmɪt.i/","defVi":"ủy ban, ban tổ chức","defEn":"a group of people chosen to make decisions or deal with a particular task","examples":["The planning [committee] will meet next Monday to discuss the budget. (=Dịch: Ủy ban kế hoạch sẽ họp vào thứ Hai tới để thảo luận về ngân sách.)","She was elected as the chairperson of the organizing [committee]. (=Dịch: Cô ấy đã được bầu làm chủ tịch của ban tổ chức.)","The government formed a special [committee] to investigate environmental pollution. (=Dịch: Chính phủ đã thành lập một ủy ban đặc biệt để điều tra về tình trạng ô nhiễm môi trường.)"],"ukAudio":"/ai_services/tts3/?q=committee&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=committee&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F"},{"id":"lv_0_67","topic":"Daily Life and Social Activities","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"lời phàn nàn, sự khiếu nại","defEn":"a statement that something is wrong or not satisfactory","examples":["The hotel received a formal [complaint] about the noisy air conditioning. (=Dịch: Khách sạn đã nhận được một lời khiếu nại chính thức về chiếc máy điều hòa gây ồn.)","She filed an official [complaint] with the airline regarding her damaged luggage. (=Dịch: Cô ấy đã nộp đơn khiếu nại chính thức tới hãng hàng không liên quan đến hành lý bị hư hại của mình.)","Our team has resolved every customer [complaint] within twenty-four hours. (=Dịch: Đội ngũ của chúng tôi đã giải quyết mọi khiếu nại của khách hàng trong vòng hai mươi tư giờ.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_0_68","topic":"Daily Life and Social Activities","word":"composition","pos":"(n)","ipa":"/ˌkɑːm.pəˈzɪʃ.ən/","defVi":"thành phần cấu tạo; bài văn; bản nhạc","defEn":"the parts or elements that make up something, a piece of writing, or a musical work","examples":["Scientists analyzed the chemical [composition] of the soil sample. (=Dịch: Các nhà khoa học đã phân tích thành phần hóa học của mẫu đất.)","The students were asked to write a short [composition] about their hometown. (=Dịch: Các học sinh được yêu cầu viết một bài luận ngắn về quê hương của mình.)","The pianist performed an original [composition] during the concert. (=Dịch: Nghệ sĩ dương cầm đã biểu diễn một bản nhạc tự sáng tác trong buổi hòa nhạc.)"],"ukAudio":"/ai_services/tts3/?q=composition&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=composition&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_0_69","topic":"Daily Life and Social Activities","word":"conditioning","pos":"(n)","ipa":"/kənˈdɪʃ.ən.ɪŋ/","defVi":"sự rèn luyện thể lực; sự điều hòa (không khí)","defEn":"the process of training or modifying behavior, or the act of keeping something in a good state","examples":["Physical [conditioning] is an essential part of an athlete's daily routine. (=Dịch: Rèn luyện thể lực là một phần thiết yếu trong lịch trình hàng ngày của vận động viên.)","Air [conditioning] makes the hot summer days much more bearable. (=Dịch: Hệ thống điều hòa không khí giúp những ngày hè nóng nực trở nên dễ chịu hơn nhiều.)","Psychologists study how social [conditioning] influences human behavior. (=Dịch: Các nhà tâm lý học nghiên cứu cách mà sự định hình của xã hội ảnh hưởng đến hành vi của con người.)"],"ukAudio":"/ai_services/tts3/?q=conditioning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=conditioning&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_0_70","topic":"Daily Life and Social Activities","word":"congratulation","pos":"(n)","ipa":"/kənˌɡrætʃ.əˈleɪ.ʃən/","defVi":"lời chúc mừng","defEn":"an expression of praise or good wishes for someone's success or achievement","examples":["I sent her a message of [congratulation] after she passed her driving test. (=Dịch: Tôi đã gửi cho cô ấy một tin nhắn chúc mừng sau khi cô ấy vượt qua kỳ thi sát hạch lái xe.)","The headmaster offered his warmest [congratulation] to the graduating students. (=Dịch: Hiệu trưởng đã gửi lời chúc mừng nồng nhiệt nhất tới các học sinh tốt nghiệp.)","They received many cards of [congratulation] on their wedding day. (=Dịch: Họ đã nhận được rất nhiều thiệp chúc mừng vào ngày cưới của mình.)"],"ukAudio":"/ai_services/tts3/?q=congratulation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congratulation&lang=en-US&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_71","topic":"Daily Life and Social Activities","word":"continuous","pos":"(adj)","ipa":"/kənˈtɪn.ju.əs/","defVi":"liên tục, không ngừng nghỉ","defEn":"happening or existing without any interruption or pause","examples":["The brain needs a [continuous] supply of blood and oxygen to function properly. (=Dịch: Não bộ cần được cung cấp máu và oxy liên tục để hoạt động bình thường.)","She suffered from [continuous] back pain throughout the flight. (=Dịch: Cô ấy đã phải chịu đựng cơn đau lưng liên tục trong suốt chuyến bay.)","The factory operates on a [continuous] production cycle without stopping at night. (=Dịch: Nhà máy hoạt động theo một chu kỳ sản xuất liên tục mà không dừng lại vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=continuous&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=continuous&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F"},{"id":"lv_0_72","topic":"Daily Life and Social Activities","word":"contract","pos":"(n)","ipa":"/ˈkɑːn.trækt/","defVi":"hợp đồng","defEn":"an official, legal agreement between two or more people or organizations","examples":["Please read the terms carefully before you sign the employment [contract]. (=Dịch: Vui lòng đọc kỹ các điều khoản trước khi bạn ký hợp đồng lao động.)","The company decided to renew the rental [contract] for another year. (=Dịch: Công ty đã quyết định gia hạn hợp đồng thuê thêm một năm.)","He breached the [contract] by sharing confidential information with competitors. (=Dịch: Anh ấy đã vi phạm hợp đồng khi chia sẻ thông tin mật với các đối thủ cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=contract&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=contract&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F"},{"id":"lv_0_73","topic":"Daily Life and Social Activities","word":"convenient","pos":"(adj)","ipa":"/kənˈviːn.jənt/","defVi":"tiện lợi, thuận tiện","defEn":"useful, easy, or suitable for a particular purpose without causing problems","examples":["The new apartment is in a very [convenient] location near the subway station. (=Dịch: Căn hộ mới nằm ở một vị trí rất thuận tiện gần ga tàu điện ngầm.)","Online banking makes it [convenient] to pay bills from home. (=Dịch: Ngân hàng trực tuyến giúp việc thanh toán các hóa đơn tại nhà trở nên thuận tiện.)","Is Friday afternoon [convenient] for our team meeting? (=Dịch: Chiều thứ Sáu có thuận tiện cho cuộc họp nhóm của chúng ta không?)"],"ukAudio":"/ai_services/tts3/?q=convenient&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=convenient&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F"},{"id":"lv_0_74","topic":"Daily Life and Social Activities","word":"cookery","pos":"(n)","ipa":"/ˈkʊk.ɚ.i/","defVi":"nghệ thuật nấu nướng, việc làm bếp","defEn":"the art, skill, or practice of preparing and cooking food","examples":["She enrolled in an Italian [cookery] course to learn how to make fresh pasta. (=Dịch: Cô ấy đã đăng ký một khóa học nấu ăn Ý để học cách làm mì ống tươi.)","His passion for [cookery] began when he helped his grandmother in the kitchen. (=Dịch: Niềm đam mê nấu nướng của anh ấy bắt đầu khi anh giúp bà của mình trong bếp.)","The bookstore has a large section dedicated to books on healthy [cookery]. (=Dịch: Hiệu sách có một khu vực lớn dành riêng cho những cuốn sách về nấu ăn lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=cookery&lang=en-GB&ipa=%2F%CB%88k%CA%8Ak.%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=cookery&lang=en-US&ipa=%2F%CB%88k%CA%8Ak.%C9%9A.i%2F"},{"id":"lv_0_75","topic":"Daily Life and Social Activities","word":"coordinator","pos":"(n)","ipa":"/koʊˈɔːr.dən.eɪ.t̬ɚ/","defVi":"người điều phối","defEn":"someone whose job is to organize the various parts of an activity or event","examples":["She works as a project [coordinator] for an international charity organization. (=Dịch: Cô ấy làm việc với tư cách là người điều phối dự án cho một tổ chức từ thiện quốc tế.)","If you have any questions about the schedule, please contact the event [coordinator]. (=Dịch: Nếu bạn có bất kỳ câu hỏi nào về lịch trình, vui lòng liên hệ với người điều phối sự kiện.)","The volunteer [coordinator] assigned tasks to each newcomer on the team. (=Dịch: Người điều phối tình nguyện viên đã phân công nhiệm vụ cho từng người mới gia nhập nhóm.)"],"ukAudio":"/ai_services/tts3/?q=coordinator&lang=en-GB&ipa=%2Fko%CA%8A%CB%88%C9%94%CB%90r.d%C9%99n.e%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=coordinator&lang=en-US&ipa=%2Fko%CA%8A%CB%88%C9%94%CB%90r.d%C9%99n.e%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_0_76","topic":"Daily Life and Social Activities","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục (biểu diễn, hóa trang)","defEn":"a set of clothes worn by someone in a play, film, or for a particular occasion","examples":["The actors wore traditional Victorian [costume] during the historical drama. (=Dịch: Các diễn viên đã mặc trang phục thời Victoria truyền thống trong suốt vở kịch lịch sử.)","He won first prize at the Halloween party for his scary monster [costume]. (=Dịch: Anh ấy đã giành giải nhất tại bữa tiệc Halloween nhờ bộ trang phục quái vật đáng sợ của mình.)","The museum displays dancers in colorful folk [costume] from different regions. (=Dịch: Bảo tàng trưng bày các vũ công trong trang phục dân gian rực rỡ sắc màu từ các vùng miền khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_0_77","topic":"Daily Life and Social Activities","word":"cot","pos":"(n)","ipa":"/kɑːt/","defVi":"cũi (cho em bé), giường gấp di động","defEn":"a small bed with high barred sides for a baby or young child, or a narrow portable bed","examples":["The baby fell asleep peacefully in his [cot] after drinking milk. (=Dịch: Em bé đã ngủ thiếp đi một cách ngoan ngoãn trong cũi sau khi uống sữa.)","We set up a folding [cot] in the living room for our weekend guest. (=Dịch: Chúng tôi đã dựng một chiếc giường xếp trong phòng khách cho vị khách ở lại vào cuối tuần.)","Make sure the sides of the [cot] are raised to prevent the baby from falling out. (=Dịch: Hãy đảm bảo các thành cũi đã được nâng lên để tránh em bé bị ngã ra ngoài.)"],"ukAudio":"/ai_services/tts3/?q=cot&lang=en-GB&ipa=%2Fk%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=cot&lang=en-US&ipa=%2Fk%C9%91%CB%90t%2F"},{"id":"lv_0_78","topic":"Daily Life and Social Activities","word":"court","pos":"(n)","ipa":"/kɔːrt/","defVi":"tòa án; sân bóng (quần vợt, bóng rổ)","defEn":"a place where legal cases are heard, or an area marked out for ball games","examples":["The witness was asked to appear in [court] to give evidence tomorrow. (=Dịch: Nhân chứng đã được yêu cầu có mặt tại tòa án để cung cấp lời khai vào ngày mai.)","They booked a tennis [court] for two hours on Saturday morning. (=Dịch: Họ đã đặt một sân tennis trong hai giờ vào sáng thứ Bảy.)","The judge entered the [court] and everyone stood up respectfully. (=Dịch: Thẩm phán bước vào phòng xử án và mọi người đều đứng dậy một cách tôn kính.)"],"ukAudio":"/ai_services/tts3/?q=court&lang=en-GB&ipa=%2Fk%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=court&lang=en-US&ipa=%2Fk%C9%94%CB%90rt%2F"},{"id":"lv_0_79","topic":"Daily Life and Social Activities","word":"crack","pos":"(n)","ipa":"/kræk/","defVi":"vết nứt, khe hở","defEn":"a narrow line or space on the surface of something where it has broken","examples":["There is a visible [crack] across the windshield that needs to be repaired. (=Dịch: Có một vết nứt rõ thấy trên kính chắn gió cần phải được sửa chữa.)","Water started seeping into the basement through a tiny [crack] in the foundation. (=Dịch: Nước bắt đầu thấm vào tầng hầm qua một vết nứt nhỏ trên nền móng.)","The earthquake caused a large [crack] to appear down the middle of the road. (=Dịch: Trận động đất đã khiến một vết nứt lớn xuất hiện dọc giữa lòng đường.)"],"ukAudio":"/ai_services/tts3/?q=crack&lang=en-GB&ipa=%2Fkr%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=crack&lang=en-US&ipa=%2Fkr%C3%A6k%2F"},{"id":"lv_0_80","topic":"Daily Life and Social Activities","word":"crew","pos":"(n)","ipa":"/kruː/","defVi":"phi hành đoàn, thủy thủ đoàn, đội ngũ nhân viên","defEn":"a group of people who work together, especially all the people working on a ship or aircraft","examples":["The captain ordered the [crew] to prepare the ship for departure. (=Dịch: Thuyền trưởng đã ra lệnh cho thủy thủ đoàn chuẩn bị để tàu khởi hành.)","The flight [crew] demonstrated the safety procedures before takeoff. (=Dịch: Phi hành đoàn đã hướng dẫn các quy trình an toàn trước khi máy bay cất cánh.)","A film [crew] arrived in the town to shoot a new television series. (=Dịch: Một đoàn làm phim đã đến thị trấn để quay một bộ phim truyền hình nhiều tập mới.)"],"ukAudio":"/ai_services/tts3/?q=crew&lang=en-GB&ipa=%2Fkru%CB%90%2F","usAudio":"/ai_services/tts3/?q=crew&lang=en-US&ipa=%2Fkru%CB%90%2F"},{"id":"lv_0_81","topic":"Daily Life and Social Activities","word":"curry","pos":"(n)","ipa":"/ˈkɜːr.i/","defVi":"món cà ri","defEn":"a dish of meat, vegetables, etc., cooked in an Indian-style sauce of strong spices","examples":["We decided to have chicken [curry] with rice for dinner. (=Dịch: Chúng tôi quyết định ăn cà ri gà với cơm cho bữa tối.)","This Indian restaurant is famous for its spicy lamb [curry]. (=Dịch: Nhà hàng Ấn Độ này nổi tiếng với món cà ri cừu cay.)","She added a spoonful of [curry] powder to flavor the soup. (=Dịch: Cô ấy đã thêm một thìa bột cà ri để tạo hương vị cho món súp.)"],"ukAudio":"/ai_services/tts3/?q=curry&lang=en-GB&ipa=%2F%CB%88k%C9%9C%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=curry&lang=en-US&ipa=%2F%CB%88k%C9%9C%CB%90r.i%2F"},{"id":"lv_0_82","topic":"Daily Life and Social Activities","word":"curtain","pos":"(n)","ipa":"/ˈkɜːr.tn/","defVi":"rèm cửa, màn cửa","defEn":"a piece of cloth hung to cover a window","examples":["She drew the [curtain] to block out the morning sunlight. (=Dịch: Cô ấy kéo rèm lại để ngăn ánh nắng buổi sáng.)","The living room looks much brighter with the new lace [curtains]. (=Dịch: Phòng khách trông sáng sủa hơn nhiều với những tấm rèm ren mới.)","A heavy velvet [curtain] separated the dining area from the kitchen. (=Dịch: Một tấm rèm nhung dày đã ngăn cách khu vực ăn uống với nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=curtain&lang=en-GB&ipa=%2F%CB%88k%C9%9C%CB%90r.tn%2F","usAudio":"/ai_services/tts3/?q=curtain&lang=en-US&ipa=%2F%CB%88k%C9%9C%CB%90r.tn%2F"},{"id":"lv_0_83","topic":"Daily Life and Social Activities","word":"decorate","pos":"(v)","ipa":"/ˈdek.ə.reɪt/","defVi":"trang trí, trang hoàng","defEn":"to make something look more attractive by adding items or paint to it","examples":["The family gathered together to [decorate] the Christmas tree. (=Dịch: Cả gia đình quây quần bên nhau để trang trí cây thông Noel.)","They plan to [decorate] the bedroom with light blue wallpaper. (=Dịch: Họ dự định trang trí phòng ngủ bằng giấy dán tường màu xanh nhạt.)","Fresh flowers were used to [decorate] the tables for the wedding. (=Dịch: Hoa tươi đã được sử dụng để trang trí các bàn tiệc cho đám cưới.)"],"ukAudio":"/ai_services/tts3/?q=decorate&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=decorate&lang=en-US&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F"},{"id":"lv_0_84","topic":"Daily Life and Social Activities","word":"decoration","pos":"(n)","ipa":"/ˌdek.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang trí","defEn":"an object or pattern used to make something look more attractive","examples":["We took down the party [decorations] the day after the celebration. (=Dịch: Chúng tôi đã tháo dỡ đồ trang trí bữa tiệc vào ngày hôm sau lễ kỷ niệm.)","Handmade paper lanterns served as beautiful wall [decorations]. (=Dịch: Những chiếc đèn lồng giấy thủ công được dùng làm đồ trang trí tường rất đẹp.)","The cake was topped with sugar flowers for [decoration]. (=Dịch: Chiếc bánh được phủ những bông hoa đường để trang trí.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_85","topic":"Daily Life and Social Activities","word":"deliver","pos":"(v)","ipa":"/dɪˈlɪv.ɚ/","defVi":"giao hàng, vận chuyển, phân phát","defEn":"to take goods, letters, or packages to people's houses or workplaces","examples":["The courier promised to [deliver] the parcel by noon. (=Dịch: Người chuyển phát nhanh đã hứa sẽ giao bưu kiện trước buổi trưa.)","Many local restaurants now [deliver] hot meals straight to your door. (=Dịch: Nhiều nhà hàng địa phương hiện nay giao những bữa ăn nóng hổi đến tận cửa nhà bạn.)","The mail carrier visits our neighborhood daily to [deliver] letters. (=Dịch: Người đưa thư ghé qua khu phố của chúng tôi hàng ngày để phát thư.)"],"ukAudio":"/ai_services/tts3/?q=deliver&lang=en-GB&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=deliver&lang=en-US&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F"},{"id":"lv_0_86","topic":"Daily Life and Social Activities","word":"depart","pos":"(v)","ipa":"/dɪˈpɑːrt/","defVi":"khởi hành, rời đi","defEn":"to leave a place, especially at the start of a journey","examples":["The train is scheduled to [depart] from platform three at 10:00 AM. (=Dịch: Chuyến tàu dự kiến sẽ khởi hành từ sân ga số ba lúc 10:00 sáng.)","Tourists usually [depart] early in the morning to avoid the heat. (=Dịch: Khách du lịch thường khởi hành vào sáng sớm để tránh cái nóng.)","The flight will [depart] as soon as all passengers are boarded. (=Dịch: Chuyến bay sẽ khởi hành ngay khi tất cả hành khách đã lên máy bay.)"],"ukAudio":"/ai_services/tts3/?q=depart&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=depart&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90rt%2F"},{"id":"lv_0_87","topic":"Daily Life and Social Activities","word":"departure","pos":"(n)","ipa":"/dɪˈpɑːr.tʃɚ/","defVi":"sự khởi hành, sự rời đi","defEn":"the act of leaving a place, especially to begin a trip","examples":["Please check the screen for your flight's estimated time of [departure]. (=Dịch: Vui lòng kiểm tra màn hình để biết giờ khởi hành dự kiến của chuyến bay.)","Passengers gathered in the [departure] lounge waiting to board the plane. (=Dịch: Hành khách tập trung tại phòng chờ khởi hành để đợi lên máy bay.)","Her sudden [departure] from the company surprised all of her colleagues. (=Dịch: Sự rời đi đột ngột của cô ấy khỏi công ty đã làm tất cả các đồng nghiệp ngạc nhiên.)"],"ukAudio":"/ai_services/tts3/?q=departure&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90r.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=departure&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%91%CB%90r.t%CA%83%C9%9A%2F"},{"id":"lv_0_88","topic":"Daily Life and Social Activities","word":"dependent","pos":"(adj)","ipa":"/dɪˈpen.dənt/","defVi":"phụ thuộc, dựa dẫm","defEn":"needing the support or help of someone or something else to survive or succeed","examples":["Young children are completely [dependent] on their parents for care. (=Dịch: Trẻ nhỏ hoàn toàn phụ thuộc vào cha mẹ để được chăm sóc.)","The country's economy is heavily [dependent] on oil exports. (=Dịch: Nền kinh tế của quốc gia này phụ thuộc rất nhiều vào xuất khẩu dầu mỏ.)","Success in this project is [dependent] upon everyone's cooperation. (=Dịch: Sự thành công của dự án này phụ thuộc vào sự hợp tác của tất cả mọi người.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F"},{"id":"lv_0_89","topic":"Daily Life and Social Activities","word":"dessert","pos":"(n)","ipa":"/dɪˈzɜːrt/","defVi":"món tráng miệng","defEn":"sweet food eaten at the end of a meal","examples":["We ordered chocolate cake and vanilla ice cream for [dessert]. (=Dịch: Chúng tôi đã gọi bánh sô-cô-la và kem vani làm món tráng miệng.)","Fresh fruit is a healthy option for [dessert] after a heavy dinner. (=Dịch: Trái cây tươi là một lựa chọn lành mạnh cho món tráng miệng sau một bữa tối no nê.)","The chef prepared a special strawberry tart for the evening [dessert]. (=Dịch: Bếp trưởng đã chuẩn bị một chiếc bánh tart dâu tây đặc biệt cho món tráng miệng buổi tối.)"],"ukAudio":"/ai_services/tts3/?q=dessert&lang=en-GB&ipa=%2Fd%C9%AA%CB%88z%C9%9C%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=dessert&lang=en-US&ipa=%2Fd%C9%AA%CB%88z%C9%9C%CB%90rt%2F"},{"id":"lv_0_90","topic":"Daily Life and Social Activities","word":"devote","pos":"(v)","ipa":"/dɪˈvoʊt/","defVi":"cống hiến, dành hết tâm huyết","defEn":"to give an amount of time, attention, or effort to a particular purpose or person","examples":["She decided to [devote] her career to helping underprivileged children. (=Dịch: Cô ấy quyết định cống hiến sự nghiệp của mình để giúp đỡ trẻ em có hoàn cảnh khó khăn.)","He wants to [devote] more time to his family after retirement. (=Dịch: Ông ấy muốn dành nhiều thời gian hơn cho gia đình sau khi nghỉ hưu.)","The scientist will [devote] the next few years to cancer research. (=Dịch: Nhà khoa học sẽ dành vài năm tới để cống hiến cho việc nghiên cứu ung thư.)"],"ukAudio":"/ai_services/tts3/?q=devote&lang=en-GB&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=devote&lang=en-US&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F"},{"id":"lv_0_91","topic":"Daily Life and Social Activities","word":"dining","pos":"(n)","ipa":"/ˈdaɪ.nɪŋ/","defVi":"Việc ăn uống, dùng bữa","defEn":"The activity of eating a meal, especially in a formal or restaurant setting.","examples":["Fine [dining] restaurants usually require customers to reserve a table in advance. (=Dịch: Các nhà hàng cao cấp thường yêu cầu thực khách phải đặt bàn trước.)","The hotel features an outdoor [dining] area with a beautiful ocean view. (=Dịch: Khách sạn có khu vực ăn uống ngoài trời với tầm nhìn tuyệt đẹp ra biển.)","They gathered in the formal [dining] room to celebrate their anniversary. (=Dịch: Họ quây quần trong phòng ăn trang trọng để kỷ niệm ngày cưới của mình.)"],"ukAudio":"/ai_services/tts3/?q=dining&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dining&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_0_92","topic":"Daily Life and Social Activities","word":"disabled","pos":"(adj)","ipa":"/dɪsˈeɪ.bəld/","defVi":"Khuyết tật, tàn tật","defEn":"Having a physical or mental condition that limits movements, senses, or activities.","examples":["The building was renovated to provide better access for [disabled] visitors. (=Dịch: Tòa nhà đã được cải tạo để người khuyết tật có thể tiếp cận thuận tiện hơn.)","Special parking spaces are reserved near the entrance for [disabled] drivers. (=Dịch: Các vị trí đỗ xe đặc biệt gần lối vào được dành riêng cho các tài xế khuyết tật.)","Charities work hard to create equal job opportunities for [disabled] people. (=Dịch: Các tổ chức từ thiện nỗ lực hết mình để tạo ra cơ hội việc làm bình đẳng cho người khuyết tật.)"],"ukAudio":"/ai_services/tts3/?q=disabled&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88e%C9%AA.b%C9%99ld%2F","usAudio":"/ai_services/tts3/?q=disabled&lang=en-US&ipa=%2Fd%C9%AAs%CB%88e%C9%AA.b%C9%99ld%2F"},{"id":"lv_0_93","topic":"Daily Life and Social Activities","word":"disco","pos":"(n)","ipa":"/ˈdɪs.koʊ/","defVi":"Vũ trường, sàn nhảy disco","defEn":"A club or event where people dance to recorded pop or dance music.","examples":["The local youth club hosts a [disco] every Friday evening. (=Dịch: Câu lạc bộ thanh niên địa phương tổ chức một đêm nhạc disco vào mỗi tối thứ Sáu.)","She wore a shiny retro outfit to the 1980s themed [disco]. (=Dịch: Cô ấy đã mặc một bộ trang phục cổ điển lấp lánh đến vũ hội disco mang phong cách thập niên 1980.)","The loud music from the hotel [disco] kept some guests awake at night. (=Dịch: Âm nhạc ồn ào từ sàn nhảy disco của khách sạn đã khiến một số du khách mất ngủ vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=disco&lang=en-GB&ipa=%2F%CB%88d%C9%AAs.ko%CA%8A%2F","usAudio":"/ai_services/tts3/?q=disco&lang=en-US&ipa=%2F%CB%88d%C9%AAs.ko%CA%8A%2F"},{"id":"lv_0_94","topic":"Daily Life and Social Activities","word":"disk","pos":"(n)","ipa":"/dɪsk/","defVi":"Đĩa từ, đĩa máy tính, vật hình đĩa","defEn":"A flat, thin circular object, especially one used for storing computer data.","examples":["Make sure you save a backup copy of your project onto an external [disk]. (=Dịch: Hãy đảm bảo bạn đã lưu một bản sao lưu dự án của mình vào ổ đĩa ngoài.)","The computer cannot read the data because the hard [disk] is corrupted. (=Dịch: Máy tính không thể đọc dữ liệu vì ổ đĩa cứng đã bị hỏng.)","He threw the plastic [disk] across the park for his dog to catch. (=Dịch: Anh ấy ném chiếc đĩa nhựa qua công viên để chú chó của mình bắt lấy.)"],"ukAudio":"/ai_services/tts3/?q=disk&lang=en-GB&ipa=%2Fd%C9%AAsk%2F","usAudio":"/ai_services/tts3/?q=disk&lang=en-US&ipa=%2Fd%C9%AAsk%2F"},{"id":"lv_0_95","topic":"Daily Life and Social Activities","word":"dissatisfied","pos":"(adj)","ipa":"/dɪsˈsæt̬.əs.faɪd/","defVi":"Không hài lòng, bất mãn","defEn":"Not pleased, content, or happy with something.","examples":["Many customers were [dissatisfied] with the poor quality of customer service. (=Dịch: Nhiều khách hàng đã không hài lòng với chất lượng dịch vụ chăm sóc khách hàng kém.)","If you are [dissatisfied] with your purchase, you can request a full refund. (=Dịch: Nếu không hài lòng với sản phẩm đã mua, bạn có thể yêu cầu hoàn tiền toàn bộ.)","The manager held a meeting to address concerns raised by [dissatisfied] employees. (=Dịch: Người quản lý đã tổ chức một cuộc họp để giải quyết những mối bận tâm từ các nhân viên không hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=dissatisfied&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=dissatisfied&lang=en-US&ipa=%2Fd%C9%AAs%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F"},{"id":"lv_0_96","topic":"Daily Life and Social Activities","word":"dock","pos":"(n)","ipa":"/dɑːk/","defVi":"Bến tàu, bến cảng","defEn":"An area of water in a port where ships load, unload, or are repaired.","examples":["The cargo ship remained at the [dock] while workers unloaded the containers. (=Dịch: Tàu chở hàng vẫn neo tại bến tàu trong khi các công nhân dỡ các thùng công-ten-nơ.)","We walked down to the wooden [dock] to watch the sunrise over the bay. (=Dịch: Chúng tôi đi bộ xuống bến tàu bằng gỗ để ngắm bình minh trên vịnh.)","The damaged vessel was towed into the dry [dock] for urgent repairs. (=Dịch: Con tàu bị hư hỏng đã được lai dắt vào ụ cạn để sửa chữa khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=dock&lang=en-GB&ipa=%2Fd%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=dock&lang=en-US&ipa=%2Fd%C9%91%CB%90k%2F"},{"id":"lv_0_97","topic":"Daily Life and Social Activities","word":"dolphin","pos":"(n)","ipa":"/ˈdɑːl.fɪn/","defVi":"Cá heo","defEn":"An intelligent sea mammal that has a sleek body and a curved snout.","examples":["A friendly [dolphin] swam alongside our tour boat for several minutes. (=Dịch: Một chú cá heo thân thiện đã bơi dọc theo thuyền tham quan của chúng tôi trong vài phút.)","Marine biologists are studying how each [dolphin] communicates using distinct clicks. (=Dịch: Các nhà sinh vật biển đang nghiên cứu cách mỗi con cá heo giao tiếp bằng những tiếng lách cách riêng biệt.)","Watching a [dolphin] leap out of the ocean was the highlight of the trip. (=Dịch: Được ngắm nhìn một chú cá heo nhảy vọt lên khỏi mặt biển là điểm nhấn đáng nhớ nhất của chuyến đi.)"],"ukAudio":"/ai_services/tts3/?q=dolphin&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=dolphin&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F"},{"id":"lv_0_98","topic":"Daily Life and Social Activities","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"Quyên góp, hiến tặng","defEn":"To give money, goods, or time to help a person, charity, or organization.","examples":["Local businesses decided to [donate] funds to rebuild the community playground. (=Dịch: Các doanh nghiệp địa phương đã quyết định quyên góp kinh phí để xây dựng lại sân chơi cộng đồng.)","Many citizens regularly [donate] blood at the neighborhood medical clinic. (=Dịch: Nhiều người dân thường xuyên hiến máu tại trạm y tế khu phố.)","She decided to [donate] her old winter coats to a local homeless shelter. (=Dịch: Cô ấy quyết định quyên góp những chiếc áo khoác mùa đông cũ của mình cho một mái ấm người vô gia cư tại địa phương.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_0_99","topic":"Daily Life and Social Activities","word":"dormitory","pos":"(n)","ipa":"/ˈdɔːr.mə.tɔːr.i/","defVi":"Ký túc xá","defEn":"A large building at a college or university where students live.","examples":["Living in a university [dormitory] helps first-year students make new friends quickly. (=Dịch: Sống trong ký túc xá đại học giúp các sinh viên năm nhất nhanh chóng kết bạn mới.)","The campus [dormitory] offers shared kitchens and quiet study lounges on every floor. (=Dịch: Ký túc xá trong khuôn viên trường cung cấp bếp dùng chung và các phòng tự học yên tĩnh ở mỗi tầng.)","She moved out of the [dormitory] into a private apartment during her senior year. (=Dịch: Cô ấy đã chuyển ra khỏi ký túc xá đến sống tại một căn hộ riêng trong năm cuối đại học.)"],"ukAudio":"/ai_services/tts3/?q=dormitory&lang=en-GB&ipa=%2F%CB%88d%C9%94%CB%90r.m%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=dormitory&lang=en-US&ipa=%2F%CB%88d%C9%94%CB%90r.m%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_0_100","topic":"Daily Life and Social Activities","word":"downtown","pos":"(n)","ipa":"/ˌdaʊnˈtaʊn/","defVi":"Khu trung tâm thành phố","defEn":"The central commercial and business district of a city.","examples":["Traffic in [downtown] becomes extremely heavy during weekday rush hours. (=Dịch: Giao thông ở khu trung tâm thành phố trở nên cực kỳ đông đúc vào các giờ cao điểm ngày trong tuần.)","They spent the afternoon exploring art galleries and boutique shops in [downtown]. (=Dịch: Họ đã dành cả buổi chiều để khám phá các phòng trưng bày nghệ thuật và các cửa hàng thời trang ở trung tâm thành phố.)","The new subway line makes traveling between the suburbs and [downtown] much faster. (=Dịch: Tuyến tàu điện ngầm mới giúp việc đi lại giữa vùng ngoại ô và khu trung tâm thành phố nhanh hơn rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=downtown&lang=en-GB&ipa=%2F%CB%8Cda%CA%8An%CB%88ta%CA%8An%2F","usAudio":"/ai_services/tts3/?q=downtown&lang=en-US&ipa=%2F%CB%8Cda%CA%8An%CB%88ta%CA%8An%2F"},{"id":"lv_0_101","topic":"Daily Life and Social Activities","word":"duck","pos":"(n)","ipa":"/dʌk/","defVi":"con vịt","defEn":"a common water bird with short legs, webbed feet, and a broad flat beak","examples":["A mother [duck] was swimming across the pond with her ducklings. (=Dịch: Một con vịt mẹ đang bơi qua ao cùng đàn vịt con.)","The children enjoyed feeding the [duck] near the lake. (=Dịch: Lũ trẻ thích thú cho vịt ăn ở gần hồ.)","Roasted [duck] is a very popular dish in many Asian countries. (=Dịch: Vịt quay là một món ăn rất phổ biến ở nhiều quốc gia châu Á.)"],"ukAudio":"/ai_services/tts3/?q=duck&lang=en-GB&ipa=%2Fd%CA%8Ck%2F","usAudio":"/ai_services/tts3/?q=duck&lang=en-US&ipa=%2Fd%CA%8Ck%2F"},{"id":"lv_0_102","topic":"Daily Life and Social Activities","word":"duty","pos":"(n)","ipa":"/ˈdu.ti/","defVi":"bổn phận, trách nhiệm, nhiệm vụ","defEn":"a moral or legal obligation, or a task that is part of a person's job","examples":["It is every citizen's [duty] to vote in the national elections. (=Dịch: Bỏ phiếu trong các cuộc bầu cử quốc gia là nghĩa vụ của mỗi công dân.)","His main [duty] at the hotel was welcoming international guests. (=Dịch: Nhiệm vụ chính của anh ấy tại khách sạn là chào đón các vị khách quốc tế.)","Doctors feel a strong sense of [duty] toward their patients. (=Dịch: Các bác sĩ luôn có tinh thần trách nhiệm cao đối với bệnh nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=duty&lang=en-GB&ipa=%2F%CB%88du.ti%2F","usAudio":"/ai_services/tts3/?q=duty&lang=en-US&ipa=%2F%CB%88du.ti%2F"},{"id":"lv_0_103","topic":"Daily Life and Social Activities","word":"elderly","pos":"(adj)","ipa":"/ˈɛl.dɚ.li/","defVi":"cao tuổi, lớn tuổi","defEn":"a polite word used to describe someone who is old","examples":["The young boy offered his seat on the bus to an [elderly] woman. (=Dịch: Cậu bé đã nhường chỗ trên xe buýt cho một cụ bà.)","The government is improving healthcare services for [elderly] citizens. (=Dịch: Chính phủ đang cải thiện các dịch vụ chăm sóc sức khỏe cho người cao tuổi.)","Many [elderly] people enjoy gardening as a relaxing hobby. (=Dịch: Nhiều người cao tuổi thích làm vườn như một sở thích giúp thư giãn.)"],"ukAudio":"/ai_services/tts3/?q=elderly&lang=en-GB&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F","usAudio":"/ai_services/tts3/?q=elderly&lang=en-US&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F"},{"id":"lv_0_104","topic":"Daily Life and Social Activities","word":"emergency","pos":"(n)","ipa":"/ɪˈmɝː.dʒən.si/","defVi":"tình trạng khẩn cấp, trường hợp khẩn cấp","defEn":"a sudden, unexpected situation requiring immediate action","examples":["Dial 911 immediately in case of a medical [emergency]. (=Dịch: Hãy gọi 911 ngay lập tức trong trường hợp khẩn cấp về y tế.)","The pilot declared an [emergency] and landed the plane safely. (=Dịch: Phi công đã thông báo tình trạng khẩn cấp và hạ cánh máy bay an toàn.)","Every public building must have clearly marked exits for an [emergency]. (=Dịch: Mọi tòa nhà công cộng đều phải có lối thoát hiểm được đánh dấu rõ ràng phòng khi khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=emergency&lang=en-GB&ipa=%2F%C9%AA%CB%88m%C9%9D%CB%90.d%CA%92%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=emergency&lang=en-US&ipa=%2F%C9%AA%CB%88m%C9%9D%CB%90.d%CA%92%C9%99n.si%2F"},{"id":"lv_0_105","topic":"Daily Life and Social Activities","word":"enquiry","pos":"(n)","ipa":"/ɪnˈkwaɪ.ri/","defVi":"sự hỏi thăm, câu hỏi thắc mắc, cuộc điều tra","defEn":"an act of asking for information, or an official investigation","examples":["We received an [enquiry] from a client about our new software. (=Dịch: Chúng tôi đã nhận được yêu cầu giải đáp thông tin từ một khách hàng về phần mềm mới của mình.)","Please make your [enquiry] at the front desk upon arrival. (=Dịch: Vui lòng hỏi thông tin tại quầy lễ tân ngay khi bạn đến.)","The committee launched a formal [enquiry] into the cause of the accident. (=Dịch: Ủy ban đã tiến hành một cuộc điều tra chính thức về nguyên nhân của vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=enquiry&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.ri%2F","usAudio":"/ai_services/tts3/?q=enquiry&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.ri%2F"},{"id":"lv_0_106","topic":"Daily Life and Social Activities","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký tham gia","defEn":"to officially register as a member or student in a course or organization","examples":["She decided to [enroll] in an intensive English preparation course. (=Dịch: Cô ấy quyết định đăng ký một khóa học luyện thi tiếng Anh cấp tốc.)","You must [enroll] before Friday if you want a guaranteed spot. (=Dịch: Bạn phải đăng ký trước thứ Sáu nếu muốn đảm bảo giữ được một chỗ.)","Thousands of students [enroll] at this university every autumn. (=Dịch: Hàng ngàn sinh viên nhập học vào trường đại học này vào mỗi mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_0_107","topic":"Daily Life and Social Activities","word":"entitle","pos":"(v)","ipa":"/ɪnˈtaɪ.t̬əl/","defVi":"trao quyền, cho phép, cho hưởng quyền lợi","defEn":"to give someone the official right to have or do something","examples":["This discount coupon does not [entitle] you to free delivery. (=Dịch: Phiếu giảm giá này không cho phép bạn nhận giao hàng miễn phí.)","Full-time employees are [entitle]d to four weeks of paid leave. (=Dịch: Nhân viên toàn thời gian được quyền hưởng bốn tuần nghỉ phép có lương.)","Holding this membership will [entitle] you to special VIP lounge access. (=Dịch: Việc sở hữu thẻ thành viên này sẽ cho phép bạn sử dụng phòng chờ VIP đặc biệt.)"],"ukAudio":"/ai_services/tts3/?q=entitle&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=entitle&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.t%CC%AC%C9%99l%2F"},{"id":"lv_0_108","topic":"Daily Life and Social Activities","word":"equip","pos":"(v)","ipa":"/ɪˈkwɪp/","defVi":"trang bị, cung cấp đồ dùng/kỹ năng cần thiết","defEn":"to provide someone or something with the necessary tools, skills, or features","examples":["The school aims to [equip] every science classroom with new microscopes. (=Dịch: Nhà trường đặt mục tiêu trang bị kính hiển vi mới cho mọi phòng học khoa học.)","Higher education should [equip] students for future career challenges. (=Dịch: Giáo dục bậc cao nên trang bị cho sinh viên hành trang trước những thử thách nghề nghiệp trong tương lai.)","Hikers need to [equip] themselves with suitable gear before climbing the mountain. (=Dịch: Người đi bộ đường dài cần tự trang bị đồ dùng thích hợp trước khi leo núi.)"],"ukAudio":"/ai_services/tts3/?q=equip&lang=en-GB&ipa=%2F%C9%AA%CB%88kw%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=equip&lang=en-US&ipa=%2F%C9%AA%CB%88kw%C9%AAp%2F"},{"id":"lv_0_109","topic":"Daily Life and Social Activities","word":"estate","pos":"(n)","ipa":"/ɪˈsteɪt/","defVi":"khu đất lớn, bất động sản, di sản","defEn":"a large area of land, or all the money and property owned by a person","examples":["The wealthy family owns a vast country [estate] surrounded by forests. (=Dịch: Gia đình giàu có này sở hữu một khu dinh cơ rộng lớn ở vùng quê được bao quanh bởi rừng cây.)","He decided to leave his entire [estate] to a local charity. (=Dịch: Ông quyết định để lại toàn bộ gia tài của mình cho một tổ chức từ thiện địa phương.)","A new housing [estate] is being built on the edge of the city. (=Dịch: Một khu dân cư mới đang được xây dựng ở vùng ven thành phố.)"],"ukAudio":"/ai_services/tts3/?q=estate&lang=en-GB&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=estate&lang=en-US&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F"},{"id":"lv_0_110","topic":"Daily Life and Social Activities","word":"exchange","pos":"(n)","ipa":"/ɪksˈtʃeɪndʒ/","defVi":"sự trao đổi, giao dịch, chuyến giao lưu","defEn":"an act of giving something and receiving something else in return, or a short conversation","examples":["The two universities agreed on a student [exchange] program. (=Dịch: Hai trường đại học đã nhất trí về một chương trình trao đổi sinh viên.)","There was a brief [exchange] of ideas during the team meeting. (=Dịch: Đã có một cuộc trao đổi ý kiến ngắn gọn trong suốt buổi họp nhóm.)","Always check the currency [exchange] rate before converting your money. (=Dịch: Hãy luôn kiểm tra tỷ giá hối đoái trước khi đổi tiền.)"],"ukAudio":"/ai_services/tts3/?q=exchange&lang=en-GB&ipa=%2F%C9%AAks%CB%88t%CA%83e%C9%AAnd%CA%92%2F","usAudio":"/ai_services/tts3/?q=exchange&lang=en-US&ipa=%2F%C9%AAks%CB%88t%CA%83e%C9%AAnd%CA%92%2F"},{"id":"lv_0_111","topic":"Daily Life and Social Activities","word":"excursion","pos":"(n)","ipa":"/ɪkˈskɝː.ʒən/","defVi":"chuyến đi chơi ngắn, chuyến dã ngoại","defEn":"a short trip or journey made for pleasure or study","examples":["The class went on an all-day [excursion] to the natural history museum. (=Dịch: Cả lớp đã có một chuyến tham quan kéo dài cả ngày đến bảo tàng lịch sử tự nhiên.)","The resort arranges a boat [excursion] to nearby coral reefs every morning. (=Dịch: Khu nghỉ dưỡng tổ chức một chuyến du ngoạn bằng thuyền đến các rạn san hô gần đó vào mỗi buổi sáng.)","We planned a weekend [excursion] to the mountains to escape the heat. (=Dịch: Chúng tôi đã lên kế hoạch cho một chuyến dã ngoại cuối tuần lên vùng núi để tránh nóng.)"],"ukAudio":"/ai_services/tts3/?q=excursion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sk%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excursion&lang=en-US&ipa=%2F%C9%AAk%CB%88sk%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_0_112","topic":"Daily Life and Social Activities","word":"excuse","pos":"(n)","ipa":"/ɪkˈskjus/","defVi":"lý do, cớ, lời biện hộ","defEn":"a reason given to explain or justify a fault, mistake, or absence","examples":["He made up an [excuse] for arriving late to the lecture. (=Dịch: Anh ấy đã bịa ra một cái cớ vì đến buổi giảng muộn.)","Tiredness is no [excuse] for being careless with your work. (=Dịch: Sự mệt mỏi không phải là lý do để bất cẩn trong công việc.)","She offered a polite [excuse] and left the dinner party early. (=Dịch: Cô ấy đã đưa ra một lời cáo lỗi lịch sự và rời bữa tiệc tối sớm.)"],"ukAudio":"/ai_services/tts3/?q=excuse&lang=en-GB&ipa=%2F%C9%AAk%CB%88skjus%2F","usAudio":"/ai_services/tts3/?q=excuse&lang=en-US&ipa=%2F%C9%AAk%CB%88skjus%2F"},{"id":"lv_0_113","topic":"Daily Life and Social Activities","word":"fare","pos":"(n)","ipa":"/fɛr/","defVi":"tiền xe, tiền vé (tàu, xe, máy bay)","defEn":"the money that you pay to travel by bus, train, taxi, or plane","examples":["The bus [fare] has increased significantly over the past year. (=Dịch: Giá vé xe buýt đã tăng đáng kể trong năm qua.)","Children under five can travel at half [fare] on local trains. (=Dịch: Trẻ em dưới năm tuổi có thể đi các tuyến tàu địa phương với nửa giá vé.)","She did not have enough cash to pay the taxi [fare]. (=Dịch: Cô ấy không có đủ tiền mặt để trả cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ff%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ff%C9%9Br%2F"},{"id":"lv_0_114","topic":"Daily Life and Social Activities","word":"fence","pos":"(n)","ipa":"/fɛns/","defVi":"hàng rào","defEn":"a structure made of wood or wire that surrounds an area of land","examples":["The neighbors built a tall wooden [fence] between their gardens. (=Dịch: Những người hàng xóm đã dựng một hàng rào gỗ cao giữa các khu vườn của họ.)","The dog easily jumped over the low [fence] to chase the ball. (=Dịch: Con chó dễ dàng nhảy qua hàng rào thấp để đuổi theo quả bóng.)","Security guards patrol along the perimeter [fence] every night. (=Dịch: Các nhân viên an ninh tuần tra dọc theo hàng rào bao quanh mỗi đêm.)"],"ukAudio":"/ai_services/tts3/?q=fence&lang=en-GB&ipa=%2Ff%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=fence&lang=en-US&ipa=%2Ff%C9%9Bns%2F"},{"id":"lv_0_115","topic":"Daily Life and Social Activities","word":"finishing","pos":"(n)","ipa":"/ˈfɪn.ɪ.ʃɪŋ/","defVi":"sự hoàn thiện, giai đoạn hoàn tất","defEn":"the act of completing something, or a final treatment applied to a surface","examples":["The painters are putting the [finishing] touches on the new gallery. (=Dịch: Những người thợ sơn đang hoàn thiện các chi tiết cuối cùng cho phòng trưng bày mới.)","Good wood [finishing] protects the furniture from moisture damage. (=Dịch: Lớp phủ hoàn thiện gỗ tốt giúp bảo vệ đồ nội thất khỏi hư hại do ẩm mốc.)","She took pride in [finishing] the difficult assignment on time. (=Dịch: Cô ấy tự hào vì đã hoàn thành bài tập khó đúng hạn.)"],"ukAudio":"/ai_services/tts3/?q=finishing&lang=en-GB&ipa=%2F%CB%88f%C9%AAn.%C9%AA.%CA%83%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=finishing&lang=en-US&ipa=%2F%CB%88f%C9%AAn.%C9%AA.%CA%83%C9%AA%C5%8B%2F"},{"id":"lv_0_116","topic":"Daily Life and Social Activities","word":"firework","pos":"(n)","ipa":"/ˈfaɪr.wɜrk/","defVi":"pháo hoa","defEn":"a small device containing chemicals that explodes with bright lights and loud noises for entertainment","examples":["Crowds gathered along the riverbank to watch the spectacular [firework] display. (=Dịch: Đám đông tụ tập dọc bờ sông để xem màn trình diễn pháo hoa ngoạn mục.)","A single [firework] lit up the dark night sky. (=Dịch: Một quả pháo hoa duy nhất đã thắp sáng bầu trời đêm tăm tối.)","Setting off a [firework] without a permit is illegal in the city. (=Dịch: Bắn pháo hoa không có giấy phép là hành vi bất hợp pháp trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=firework&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%C9%9Crk%2F","usAudio":"/ai_services/tts3/?q=firework&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%C9%9Crk%2F"},{"id":"lv_0_117","topic":"Daily Life and Social Activities","word":"flute","pos":"(n)","ipa":"/flut/","defVi":"cây sáo, ống sáo","defEn":"a high-pitched musical instrument played by blowing across a hole near one end","examples":["She has been playing the [flute] in the school orchestra for three years. (=Dịch: Cô ấy đã chơi sáo trong dàn nhạc của trường được ba năm.)","The gentle melody of the [flute] created a peaceful atmosphere. (=Dịch: Giai điệu êm dịu của tiếng sáo đã tạo nên một bầu không khí yên bình.)","He bought a silver [flute] to replace his old student model. (=Dịch: Anh ấy đã mua một cây sáo bạc để thay thế cho cây sáo tập cũ của mình.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflut%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflut%2F"},{"id":"lv_0_118","topic":"Daily Life and Social Activities","word":"folder","pos":"(n)","ipa":"/ˈfoʊl.dɚ/","defVi":"thư mục, bìa kẹp hồ sơ","defEn":"a cardboard or plastic cover used for keeping loose papers together, or a digital directory","examples":["Please place the signed contract into the blue [folder]. (=Dịch: Vui lòng đặt hợp đồng đã ký vào bìa hồ sơ màu xanh dương.)","You should create a separate [folder] on your computer for each subject. (=Dịch: Bạn nên tạo một thư mục riêng trên máy tính cho từng môn học.)","She handed the interviewer a [folder] containing her certificates. (=Dịch: Cô ấy đã đưa cho người phỏng vấn một tập hồ sơ chứa các chứng chỉ của mình.)"],"ukAudio":"/ai_services/tts3/?q=folder&lang=en-GB&ipa=%2F%CB%88fo%CA%8Al.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=folder&lang=en-US&ipa=%2F%CB%88fo%CA%8Al.d%C9%9A%2F"},{"id":"lv_0_119","topic":"Daily Life and Social Activities","word":"foothill","pos":"(n)","ipa":"/ˈfʊt.hɪl/","defVi":"đồi thấp chân núi, vùng chân núi","defEn":"a low hill at the base of a mountain or mountain range","examples":["The small village is nestled in the [foothill] area near the Alps. (=Dịch: Ngôi làng nhỏ nằm nép mình ở khu vực chân đồi gần dãy Alps.)","Hikers often camp on a gentle [foothill] before attempting the main peak. (=Dịch: Những người đi bộ đường dài thường cắm trại trên một sườn đồi thoai thoải ở chân núi trước khi thử sức với đỉnh núi chính.)","Vineyards thrive on the sunny slopes of the [foothill]. (=Dịch: Các vườn nho phát triển mạnh trên những sườn đồi đầy nắng ở chân núi.)"],"ukAudio":"/ai_services/tts3/?q=foothill&lang=en-GB&ipa=%2F%CB%88f%CA%8At.h%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=foothill&lang=en-US&ipa=%2F%CB%88f%CA%8At.h%C9%AAl%2F"},{"id":"lv_0_120","topic":"Daily Life and Social Activities","word":"footpath","pos":"(n)","ipa":"/ˈfʊt.pæθ/","defVi":"đường mòn đi bộ, lối đi bộ","defEn":"a narrow path designed for people to walk on, especially in the countryside","examples":["Follow this [footpath] through the woods to reach the lake. (=Dịch: Hãy đi theo lối đi bộ này xuyên qua khu rừng để đến bờ hồ.)","The council decided to pave the muddy [footpath] near the school. (=Dịch: Hội đồng đã quyết định lát đường cho lối đi bộ lầy lội gần trường học.)","We enjoyed a quiet stroll along the coastal [footpath]. (=Dịch: Chúng tôi đã có một buổi đi dạo yên bình dọc theo con đường mòn ven biển.)"],"ukAudio":"/ai_services/tts3/?q=footpath&lang=en-GB&ipa=%2F%CB%88f%CA%8At.p%C3%A6%CE%B8%2F","usAudio":"/ai_services/tts3/?q=footpath&lang=en-US&ipa=%2F%CB%88f%CA%8At.p%C3%A6%CE%B8%2F"},{"id":"lv_0_121","topic":"Daily Life and Social Activities","word":"format","pos":"(n)","ipa":"/ˈfɔr.mæt/","defVi":"định dạng, khuôn dạng, cấu trúc","defEn":"the general way in which something is arranged, organized, or produced","examples":["The exam [format] has changed to include more multiple-choice questions. (=Dịch: Định dạng bài thi đã thay đổi để bao gồm nhiều câu hỏi trắc nghiệm hơn.)","Please submit your final report in PDF [format]. (=Dịch: Vui lòng nộp báo cáo cuối cùng của bạn dưới định dạng PDF.)","The new TV show follows an interactive [format] that engages the audience. (=Dịch: Chương trình truyền hình mới áp dụng định dạng tương tác nhằm thu hút khán giả.)"],"ukAudio":"/ai_services/tts3/?q=format&lang=en-GB&ipa=%2F%CB%88f%C9%94r.m%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=format&lang=en-US&ipa=%2F%CB%88f%C9%94r.m%C3%A6t%2F"},{"id":"lv_0_122","topic":"Daily Life and Social Activities","word":"forth","pos":"(adv)","ipa":"/fɔrθ/","defVi":"về phía trước, ra phía trước","defEn":"out into notice or view; forwards in time, place, or order","examples":["The committee decided to bring [forth] several new proposals during the meeting. (=Dịch: Ủy ban đã quyết định đưa ra một số đề xuất mới trong cuộc họp.)","He paced back and [forth] across the room while waiting for the test results. (=Dịch: Anh ấy đi đi lại lại khắp căn phòng trong khi chờ đợi kết quả xét nghiệm.)","From that day [forth], she promised to practice English for an hour each morning. (=Dịch: Kể từ ngày đó trở đi, cô ấy đã hứa sẽ luyện tập tiếng Anh một tiếng vào mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=forth&lang=en-GB&ipa=%2Ff%C9%94r%CE%B8%2F","usAudio":"/ai_services/tts3/?q=forth&lang=en-US&ipa=%2Ff%C9%94r%CE%B8%2F"},{"id":"lv_0_123","topic":"Daily Life and Social Activities","word":"fragile","pos":"(adj)","ipa":"/ˈfræ.dʒəl/","defVi":"dễ vỡ, mỏng manh","defEn":"easily broken, damaged, or destroyed","examples":["Please handle the package carefully because it contains [fragile] glassware. (=Dịch: Xin hãy xử lý gói hàng cẩn thận vì bên trong chứa đồ thủy tinh dễ vỡ.)","The country's economic recovery remains very [fragile] after the crisis. (=Dịch: Sự phục hồi kinh tế của đất nước vẫn còn rất mong manh sau cuộc khủng hoảng.)","Pollution poses a serious threat to this [fragile] marine ecosystem. (=Dịch: Ô nhiễm đặt ra một mối đe dọa nghiêm trọng đối với hệ sinh thái biển mong manh này.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6.d%CA%92%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6.d%CA%92%C9%99l%2F"},{"id":"lv_0_124","topic":"Daily Life and Social Activities","word":"frame","pos":"(n)","ipa":"/freɪm/","defVi":"khung, sườn","defEn":"a rigid structure that surrounds or supports something","examples":["He placed the family photograph inside a simple wooden [frame]. (=Dịch: Anh ấy đặt bức ảnh gia đình vào bên trong một khung gỗ đơn giản.)","The bicycle has a lightweight steel [frame] that makes it easy to carry. (=Dịch: Chiếc xe đạp có khung thép nhẹ giúp dễ dàng mang vác.)","Regular exercise helps build a strong muscular [frame]. (=Dịch: Tập thể dục thường xuyên giúp xây dựng một vóc dáng cơ bắp khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=frame&lang=en-GB&ipa=%2Ffre%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=frame&lang=en-US&ipa=%2Ffre%C9%AAm%2F"},{"id":"lv_0_125","topic":"Daily Life and Social Activities","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ, nguồn tiền","defEn":"an amount of money saved or made available for a particular purpose","examples":["The university established a scholarship [fund] for disadvantaged students. (=Dịch: Trường đại học đã thành lập một quỹ học bổng dành cho các sinh viên có hoàn cảnh khó khăn.)","They ran out of money because their travel [fund] was depleted. (=Dịch: Họ đã hết tiền vì quỹ du lịch của họ bị cạn kiệt.)","The local government allocated a special [fund] to improve road safety. (=Dịch: Chính quyền địa phương đã phân bổ một quỹ đặc biệt để cải thiện an toàn đường bộ.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_0_126","topic":"Daily Life and Social Activities","word":"fundraise","pos":"(v)","ipa":"/ˈfʌndˌreɪz/","defVi":"gây quỹ","defEn":"to collect money for a particular cause, project, or charity","examples":["The students organized a bake sale to [fundraise] for the local animal shelter. (=Dịch: Các học sinh đã tổ chức một buổi bán bánh để gây quỹ cho trạm cứu hộ động vật địa phương.)","Non-profit organizations often [fundraise] through online donation campaigns. (=Dịch: Các tổ chức phi lợi nhuận thường gây quỹ thông qua các chiến dịch quyên góp trực tuyến.)","The charity plans to [fundraise] for clean water projects in rural villages. (=Dịch: Tổ chức từ thiện lên kế hoạch gây quỹ cho các dự án nước sạch ở các làng quê nông thôn.)"],"ukAudio":"/ai_services/tts3/?q=fundraise&lang=en-GB&ipa=%2F%CB%88f%CA%8Cnd%CB%8Cre%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=fundraise&lang=en-US&ipa=%2F%CB%88f%CA%8Cnd%CB%8Cre%C9%AAz%2F"},{"id":"lv_0_127","topic":"Daily Life and Social Activities","word":"garage","pos":"(n)","ipa":"/ɡəˈrɑːʒ/","defVi":"nhà để xe, gara sửa xe","defEn":"a building or indoor space used for keeping or repairing motor vehicles","examples":["He parked his car in the [garage] to protect it from the heavy rain. (=Dịch: Anh ấy đã đỗ xe trong nhà để xe để bảo vệ nó khỏi cơn mưa lớn.)","I need to take my car to the local [garage] for an oil change. (=Dịch: Tôi cần mang xe đến xưởng sửa xe địa phương để thay dầu.)","They converted their old [garage] into a cozy home office. (=Dịch: Họ đã cải tạo nhà để xe cũ của mình thành một văn phòng làm việc ấm cúng tại nhà.)"],"ukAudio":"/ai_services/tts3/?q=garage&lang=en-GB&ipa=%2F%C9%A1%C9%99%CB%88r%C9%91%CB%90%CA%92%2F","usAudio":"/ai_services/tts3/?q=garage&lang=en-US&ipa=%2F%C9%A1%C9%99%CB%88r%C9%91%CB%90%CA%92%2F"},{"id":"lv_0_128","topic":"Daily Life and Social Activities","word":"gardening","pos":"(n)","ipa":"/ˈɡɑːr.dən.ɪŋ/","defVi":"việc làm vườn","defEn":"the activity of growing and taking care of plants in a garden","examples":["Many retirees take up [gardening] as a relaxing outdoor hobby. (=Dịch: Nhiều người về hưu bắt đầu làm vườn như một sở thích thư giãn ngoài trời.)","She bought some new tools to help with the weekend [gardening]. (=Dịch: Cô ấy đã mua một số dụng cụ mới để phục vụ việc làm vườn vào cuối tuần.)","Community [gardening] helps neighbors connect while growing fresh vegetables. (=Dịch: Việc làm vườn cộng đồng giúp những người hàng xóm gắn kết trong khi cùng trồng rau sạch.)"],"ukAudio":"/ai_services/tts3/?q=gardening&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=gardening&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_0_129","topic":"Daily Life and Social Activities","word":"gear","pos":"(n)","ipa":"/ɡɪr/","defVi":"bánh răng; đồ dùng, dụng cụ","defEn":"a toothed wheel in a machine, or equipment used for a specific activity","examples":["Make sure you shift into the correct [gear] when driving uphill. (=Dịch: Hãy chắc chắn rằng bạn chuyển sang đúng số khi lái xe lên dốc.)","Don't forget to pack all your camping [gear] before we leave tomorrow. (=Dịch: Đừng quên đóng gói toàn bộ đồ dùng cắm trại của bạn trước khi chúng ta khởi hành vào ngày mai.)","A broken [gear] caused the entire clock mechanism to stop working. (=Dịch: Một bánh răng bị gãy đã khiến toàn bộ cơ chế đồng hồ ngừng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=gear&lang=en-GB&ipa=%2F%C9%A1%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=gear&lang=en-US&ipa=%2F%C9%A1%C9%AAr%2F"},{"id":"lv_0_130","topic":"Daily Life and Social Activities","word":"generous","pos":"(adj)","ipa":"/ˈdʒen.ər.əs/","defVi":"hào phóng, rộng lượng","defEn":"willing to give money, help, or kindness freely to others","examples":["It was very [generous] of him to pay for everyone's dinner. (=Dịch: Anh ấy thật hào phóng khi trả tiền cho bữa tối của mọi người.)","The museum received a [generous] donation from an anonymous sponsor. (=Dịch: Bảo tàng đã nhận được một khoản quyên góp hậu hĩnh từ một nhà tài trợ ẩn danh.)","The restaurant is famous for serving unusually [generous] portions of food. (=Dịch: Nhà hàng này nổi tiếng với việc phục vụ những phần ăn nhiều khác thường.)"],"ukAudio":"/ai_services/tts3/?q=generous&lang=en-GB&ipa=%2F%CB%88d%CA%92en.%C9%99r.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=generous&lang=en-US&ipa=%2F%CB%88d%CA%92en.%C9%99r.%C9%99s%2F"},{"id":"lv_0_131","topic":"Daily Life and Social Activities","word":"glove","pos":"(n)","ipa":"/ɡlʌv/","defVi":"găng tay, bao tay","defEn":"a piece of clothing worn on the hand with separate parts for each finger","examples":["She wore a thick woolen [glove] on each hand to stay warm in the snow. (=Dịch: Cô ấy đeo một chiếc găng tay len dày trên mỗi bàn tay để giữ ấm trong tuyết.)","The surgeon put on a sterile rubber [glove] before starting the operation. (=Dịch: Bác sĩ phẫu thuật đã đeo găng tay cao su vô trùng trước khi bắt đầu ca mổ.)","He dropped his baseball [glove] on the grass after the practice match. (=Dịch: Anh ấy đã làm rơi găng tay bóng chày của mình trên bãi cỏ sau trận đấu tập.)"],"ukAudio":"/ai_services/tts3/?q=glove&lang=en-GB&ipa=%2F%C9%A1l%CA%8Cv%2F","usAudio":"/ai_services/tts3/?q=glove&lang=en-US&ipa=%2F%C9%A1l%CA%8Cv%2F"},{"id":"lv_0_132","topic":"Daily Life and Social Activities","word":"goodness","pos":"(n)","ipa":"/ˈɡʊd.nəs/","defVi":"lòng tốt, sự nhân từ","defEn":"the quality of being good, kind, or honest","examples":["She always believes in the basic [goodness] of human nature. (=Dịch: Cô luôn tin vào bản tính lương thiện vốn có của con người.)","He showed immense [goodness] by helping the homeless family find shelter. (=Dịch: Anh ấy đã thể hiện lòng tốt bao la khi giúp đỡ gia đình vô gia cư tìm nơi trú ẩn.)","We appreciated the [goodness] and generosity of our neighbors. (=Dịch: Chúng tôi rất trân trọng lòng tốt và sự hào phóng của những người hàng xóm.)"],"ukAudio":"/ai_services/tts3/?q=goodness&lang=en-GB&ipa=%2F%CB%88%C9%A1%CA%8Ad.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=goodness&lang=en-US&ipa=%2F%CB%88%C9%A1%CA%8Ad.n%C9%99s%2F"},{"id":"lv_0_133","topic":"Daily Life and Social Activities","word":"granary","pos":"(n)","ipa":"/ˈɡræn.ə.ri/","defVi":"kho thóc, vựa lúa","defEn":"a building used for storing harvested grain","examples":["The farm has a large wooden [granary] to store wheat for the winter. (=Dịch: Trang trại có một kho thóc lớn bằng gỗ để tích trữ lúa mì cho mùa đông.)","Rats were found nesting inside the old [granary]. (=Dịch: Chuột được phát hiện đang làm tổ bên trong vựa lúa cũ.)","This fertile region is considered the primary [granary] of the country. (=Dịch: Vùng đất màu mỡ này được coi là vựa lúa chính của cả nước.)"],"ukAudio":"/ai_services/tts3/?q=granary&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6n.%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=granary&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6n.%C9%99.ri%2F"},{"id":"lv_0_134","topic":"Daily Life and Social Activities","word":"grand","pos":"(adj)","ipa":"/ɡrænd/","defVi":"hoành tráng, hùng vĩ, vĩ đại","defEn":"large, impressive, and magnificent in appearance or scale","examples":["The hotel features a [grand] entrance with crystal chandeliers. (=Dịch: Khách sạn có lối vào tráng lệ với những chùm đèn pha lê.)","They have [grand] plans to expand their business globally. (=Dịch: Họ có những kế hoạch to lớn nhằm mở rộng hoạt động kinh doanh trên toàn cầu.)","We were amazed by the [grand] view of the snow-capped mountains. (=Dịch: Chúng tôi đã vô cùng kinh ngạc trước khung cảnh hùng vĩ của những ngọn núi phủ đầy tuyết.)"],"ukAudio":"/ai_services/tts3/?q=grand&lang=en-GB&ipa=%2F%C9%A1r%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=grand&lang=en-US&ipa=%2F%C9%A1r%C3%A6nd%2F"},{"id":"lv_0_135","topic":"Daily Life and Social Activities","word":"grateful","pos":"(adj)","ipa":"/ˈɡreɪt.fəl/","defVi":"biết ơn, cảm kích","defEn":"feeling or showing thanks for something pleasing or helpful","examples":["I am deeply [grateful] for all the support you gave me during the exam. (=Dịch: Tôi vô cùng biết ơn tất cả sự hỗ trợ mà bạn đã dành cho tôi trong suốt kỳ thi.)","She was [grateful] to have a warm place to stay during the blizzard. (=Dịch: Cô ấy rất biết ơn vì có một nơi ấm áp để ở trong suốt trận bão tuyết.)","The rescue team received many [grateful] letters from the survivors. (=Dịch: Đội cứu hộ đã nhận được nhiều lá thư bày tỏ lòng biết ơn từ những người sống sót.)"],"ukAudio":"/ai_services/tts3/?q=grateful&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=grateful&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F"},{"id":"lv_0_136","topic":"Daily Life and Social Activities","word":"greek","pos":"(n)","ipa":"/ɡrik/","defVi":"tiếng Hy Lạp, người Hy Lạp","defEn":"the language of Greece, or a person born in Greece","examples":["He is studying ancient [Greek] literature at university. (=Dịch: Anh ấy đang theo học văn học Hy Lạp cổ đại tại trường đại học.)","Many medical terms are derived from ancient [Greek]. (=Dịch: Nhiều thuật ngữ y khoa có nguồn gốc từ tiếng Hy Lạp cổ.)","She met a friendly [Greek] while traveling in Athens. (=Dịch: Cô ấy đã gặp một người Hy Lạp thân thiện khi đi du lịch ở Athens.)"],"ukAudio":"/ai_services/tts3/?q=greek&lang=en-GB&ipa=%2F%C9%A1rik%2F","usAudio":"/ai_services/tts3/?q=greek&lang=en-US&ipa=%2F%C9%A1rik%2F"},{"id":"lv_0_137","topic":"Daily Life and Social Activities","word":"guarantee","pos":"(n)","ipa":"/ˌɡær.ənˈti/","defVi":"sự bảo hành, cam kết, bảo đảm","defEn":"a formal promise that certain conditions will be fulfilled or a product will be repaired","examples":["The television comes with a two-year [guarantee] against defects. (=Dịch: Chiếc ti vi đi kèm với chế độ bảo hành hai năm đối với các lỗi kỹ thuật.)","There is no [guarantee] that the weather will be sunny tomorrow. (=Dịch: Không có gì đảm bảo rằng ngày mai thời tiết sẽ nắng ráo.)","The shop offers a money-back [guarantee] if customers are not satisfied. (=Dịch: Cửa hàng đưa ra cam kết hoàn tiền nếu khách hàng không hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=guarantee&lang=en-GB&ipa=%2F%CB%8C%C9%A1%C3%A6r.%C9%99n%CB%88ti%2F","usAudio":"/ai_services/tts3/?q=guarantee&lang=en-US&ipa=%2F%CB%8C%C9%A1%C3%A6r.%C9%99n%CB%88ti%2F"},{"id":"lv_0_138","topic":"Daily Life and Social Activities","word":"guidebook","pos":"(n)","ipa":"/ˈɡaɪd.bʊk/","defVi":"sách hướng dẫn du lịch","defEn":"a book of information about a place, designed for tourists","examples":["I bought a travel [guidebook] before my trip to Japan. (=Dịch: Tôi đã mua một cuốn sách hướng dẫn du lịch trước chuyến đi Nhật Bản.)","The [guidebook] recommends several affordable restaurants in the old town. (=Dịch: Cuốn sách hướng dẫn gợi ý một số nhà hàng giá cả phải chăng trong khu phố cổ.)","You can find a detailed map of the museum inside this [guidebook]. (=Dịch: Bạn có thể tìm thấy bản đồ chi tiết của bảo tàng bên trong cuốn sách hướng dẫn này.)"],"ukAudio":"/ai_services/tts3/?q=guidebook&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AAd.b%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=guidebook&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AAd.b%CA%8Ak%2F"},{"id":"lv_0_139","topic":"Daily Life and Social Activities","word":"gum","pos":"(n)","ipa":"/ɡʌm/","defVi":"kẹo cao su, chất gôm, nướu răng","defEn":"a sticky substance from trees, or chewing gum, or the tissue around teeth","examples":["He chewed a piece of mint [gum] to freshen his breath. (=Dịch: Anh ấy đã nhai một thanh kẹo cao su bạc hà để thơm miệng.)","Please do not stick your used [gum] under the classroom desks. (=Dịch: Xin vui lòng không dán bã kẹo cao su đã dùng xuống dưới gầm bàn học.)","Her dentist noticed mild bleeding along her [gum] line. (=Dịch: Nha sĩ của cô ấy nhận thấy có hiện tượng chảy máu nhẹ dọc theo viền nướu.)"],"ukAudio":"/ai_services/tts3/?q=gum&lang=en-GB&ipa=%2F%C9%A1%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=gum&lang=en-US&ipa=%2F%C9%A1%CA%8Cm%2F"},{"id":"lv_0_140","topic":"Daily Life and Social Activities","word":"hairdresser","pos":"(n)","ipa":"/ˈherˌdres.ɚ/","defVi":"thợ làm tóc, thợ cắt tóc","defEn":"a person whose job is to cut and style people's hair","examples":["She booked an appointment with her favorite [hairdresser] before the wedding. (=Dịch: Cô ấy đã đặt lịch hẹn với người thợ làm tóc yêu thích của mình trước đám cưới.)","The [hairdresser] suggested a modern hairstyle that suited his face. (=Dịch: Người thợ làm tóc đã gợi ý một kiểu tóc hiện đại phù hợp với khuôn mặt của anh ấy.)","He worked as an apprentice [hairdresser] for three years before opening a salon. (=Dịch: Anh ấy đã làm thợ làm tóc học việc trong ba năm trước khi mở tiệm riêng.)"],"ukAudio":"/ai_services/tts3/?q=hairdresser&lang=en-GB&ipa=%2F%CB%88her%CB%8Cdres.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hairdresser&lang=en-US&ipa=%2F%CB%88her%CB%8Cdres.%C9%9A%2F"},{"id":"lv_0_141","topic":"Daily Life and Social Activities","word":"halfway","pos":"(adv)","ipa":"/ˌhæfˈweɪ/","defVi":"nửa đường, được một nửa, giữa chừng","defEn":"at or to a point midway between two places, points, or times","examples":["We stopped to rest when we were [halfway] up the mountain. (=Dịch: Chúng tôi dừng lại nghỉ ngơi khi đã đi được nửa đường lên núi.)","The battery died when the movie was only [halfway] finished. (=Dịch: Pin đã hết khi bộ phim mới chỉ chiếu được một nửa.)","She agreed to meet me [halfway] in negotiating the final price. (=Dịch: Cô ấy đã đồng ý nhượng bộ để đi đến thỏa hiệp với tôi khi đàm phán mức giá cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=halfway&lang=en-GB&ipa=%2F%CB%8Ch%C3%A6f%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=halfway&lang=en-US&ipa=%2F%CB%8Ch%C3%A6f%CB%88we%C9%AA%2F"},{"id":"lv_0_142","topic":"Daily Life and Social Activities","word":"handbag","pos":"(n)","ipa":"/ˈhænd.bæɡ/","defVi":"túi xách tay","defEn":"a small bag used especially by women to carry personal items like money and keys","examples":["She realized she had left her [handbag] on the bus. (=Dịch: Cô ấy nhận ra mình đã để quên túi xách trên xe buýt.)","He bought a leather [handbag] as a birthday present for his mother. (=Dịch: Anh ấy đã mua một chiếc túi xách da làm quà sinh nhật cho mẹ mình.)","Please do not leave your [handbag] unattended in the waiting area. (=Dịch: Xin vui lòng không để túi xách của bạn ở khu vực chờ mà không có người trông coi.)"],"ukAudio":"/ai_services/tts3/?q=handbag&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=handbag&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F"},{"id":"lv_0_143","topic":"Daily Life and Social Activities","word":"hang","pos":"(v)","ipa":"/hæŋ/","defVi":"treo, móc","defEn":"to fasten or attach something at the top so that the lower part is free","examples":["You can [hang] your coat behind the door. (=Dịch: Bạn có thể treo áo khoác của mình ở phía sau cánh cửa.)","They decided to [hang] several family photographs in the hallway. (=Dịch: Họ quyết định treo vài bức ảnh gia đình ở hành lang.)","The curtains [hang] loosely from the metal rod. (=Dịch: Rèm cửa rủ xuống nhẹ nhàng từ thanh treo kim loại.)"],"ukAudio":"/ai_services/tts3/?q=hang&lang=en-GB&ipa=%2Fh%C3%A6%C5%8B%2F","usAudio":"/ai_services/tts3/?q=hang&lang=en-US&ipa=%2Fh%C3%A6%C5%8B%2F"},{"id":"lv_0_144","topic":"Daily Life and Social Activities","word":"hardback","pos":"(n)","ipa":"/ˈhɑːrd.bæk/","defVi":"sách bìa cứng","defEn":"a book that has a stiff, solid cover rather than a flexible paper one","examples":["The novel was initially released only in [hardback]. (=Dịch: Cuốn tiểu thuyết ban đầu chỉ được phát hành dưới dạng sách bìa cứng.)","I prefer to buy a [hardback] because it lasts much longer. (=Dịch: Tôi thích mua sách bìa cứng hơn vì nó dùng được lâu hơn nhiều.)","The library keeps a rare [hardback] edition of the encyclopedia. (=Dịch: Thư viện lưu giữ một ấn bản bìa cứng hiếm có của bộ bách khoa toàn thư.)"],"ukAudio":"/ai_services/tts3/?q=hardback&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90rd.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=hardback&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90rd.b%C3%A6k%2F"},{"id":"lv_0_145","topic":"Daily Life and Social Activities","word":"heading","pos":"(n)","ipa":"/ˈhed.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a line of text serving to indicate what a passage or section is about","examples":["Each chapter in the textbook starts with a clear [heading]. (=Dịch: Mỗi chương trong sách giáo khoa đều bắt đầu bằng một tiêu đề rõ ràng.)","You should match each paragraph with the correct [heading] in the reading test. (=Dịch: Bạn nên nối từng đoạn văn với tiêu đề chính xác trong bài thi đọc.)","Make sure to write your name under the main [heading] of the form. (=Dịch: Hãy chắc chắn rằng bạn đã viết tên của mình dưới tiêu đề chính của biểu mẫu.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F"},{"id":"lv_0_146","topic":"Daily Life and Social Activities","word":"heater","pos":"(n)","ipa":"/ˈhiː.t̬ɚ/","defVi":"máy sưởi, lò sưởi","defEn":"an apparatus or machine used to supply heat or warm a room","examples":["We turned on the electric [heater] because the bedroom was freezing. (=Dịch: Chúng tôi đã bật máy sưởi điện vì phòng ngủ lạnh cóng.)","The water [heater] broke down, so we had to take cold showers. (=Dịch: Bình nóng lạnh bị hỏng nên chúng tôi phải tắm nước lạnh.)","Do not place any clothes directly on top of the portable [heater]. (=Dịch: Không đặt bất kỳ quần áo nào trực tiếp lên trên máy sưởi di động.)"],"ukAudio":"/ai_services/tts3/?q=heater&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=heater&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_0_147","topic":"Daily Life and Social Activities","word":"heating","pos":"(n)","ipa":"/ˈhiː.t̬ɪŋ/","defVi":"hệ thống sưởi, sự sưởi ấm","defEn":"a system or method used for keeping a building or room warm","examples":["Central [heating] keeps the entire apartment warm throughout the winter. (=Dịch: Hệ thống sưởi trung tâm giữ cho toàn bộ căn hộ ấm áp suốt mùa đông.)","The cost of [heating] has increased significantly this year. (=Dịch: Chi phí sưởi ấm đã tăng lên đáng kể trong năm nay.)","Our office [heating] was turned off during the weekend maintenance. (=Dịch: Hệ thống sưởi của văn phòng chúng tôi đã bị tắt trong đợt bảo trì cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=heating&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heating&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_148","topic":"Daily Life and Social Activities","word":"highlight","pos":"(n)","ipa":"/ˈhaɪ.laɪt/","defVi":"điểm nổi bật, nét đặc sắc","defEn":"the best, most exciting, or most important part of an event or period","examples":["The fireworks display was the [highlight] of the festival. (=Dịch: Màn trình diễn pháo hoa là điểm nhấn nổi bật của lễ hội.)","Visiting the ancient castle was the [highlight] of our European trip. (=Dịch: Chuyến tham quan lâu đài cổ kính là điểm nhấn đáng nhớ trong chuyến đi châu Âu của chúng tôi.)","The coach showed a video [highlight] of the team's best goals. (=Dịch: Huấn luyện viên đã cho xem một video tổng hợp những bàn thắng đẹp nhất của toàn đội.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F"},{"id":"lv_0_149","topic":"Daily Life and Social Activities","word":"hive","pos":"(n)","ipa":"/haɪv/","defVi":"tổ ong, thùng nuôi ong","defEn":"a structure in which bees live and make honey","examples":["Thousands of worker bees returned to the [hive] before sunset. (=Dịch: Hàng ngàn chú ong thợ đã quay trở về tổ trước khi mặt trời lặn.)","The beekeeper carefully inspected each wooden [hive] in the yard. (=Dịch: Người nuôi ong cẩn thận kiểm tra từng tổ ong bằng gỗ trong sân.)","During peak hours, the busy kitchen was a [hive] of activity. (=Dịch: Vào những giờ cao điểm, căn bếp bận rộn là một nơi vô cùng tấp nập và nhộn nhịp.)"],"ukAudio":"/ai_services/tts3/?q=hive&lang=en-GB&ipa=%2Fha%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=hive&lang=en-US&ipa=%2Fha%C9%AAv%2F"},{"id":"lv_0_150","topic":"Daily Life and Social Activities","word":"holland","pos":"(n)","ipa":"/ˈhɑː.lənd/","defVi":"Hà Lan","defEn":"a common informal name for the Netherlands, a country in northwestern Europe","examples":["Tulips and windmills are famous symbols of [Holland]. (=Dịch: Hoa tulip và cối xay gió là những biểu tượng nổi tiếng của Hà Lan.)","She spent a semester studying international law in [Holland]. (=Dịch: Cô ấy đã dành một học kỳ để theo học ngành luật quốc tế tại Hà Lan.)","Cycling is one of the most popular forms of transport in [Holland]. (=Dịch: Đi xe đạp là một trong những phương tiện di chuyển phổ biến nhất ở Hà Lan.)"],"ukAudio":"/ai_services/tts3/?q=holland&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=holland&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90.l%C9%99nd%2F"},{"id":"lv_0_151","topic":"Daily Life and Social Activities","word":"homestay","pos":"(n)","ipa":"/ˈhoʊm.steɪ/","defVi":"hình thức ở trọ cùng gia đình bản xứ (homestay)","defEn":"an arrangement where a student or tourist stays with a local family","examples":["Living in a [homestay] helped him improve his English speaking skills rapidly. (=Dịch: Việc sống cùng gia đình bản xứ đã giúp anh ấy cải thiện kỹ năng nói tiếng Anh một cách nhanh chóng.)","The agency arranged a cozy [homestay] near the university campus. (=Dịch: Công ty đã sắp xếp một nơi ở cùng gia đình bản xứ ấm cúng gần khuôn viên trường đại học.)","Many international students prefer a [homestay] to learn about the local culture. (=Dịch: Nhiều du học sinh thích ở cùng gia đình bản xứ để tìm hiểu về văn hóa địa phương.)"],"ukAudio":"/ai_services/tts3/?q=homestay&lang=en-GB&ipa=%2F%CB%88ho%CA%8Am.ste%C9%AA%2F","usAudio":"/ai_services/tts3/?q=homestay&lang=en-US&ipa=%2F%CB%88ho%CA%8Am.ste%C9%AA%2F"},{"id":"lv_0_152","topic":"Daily Life and Social Activities","word":"honest","pos":"(adj)","ipa":"/ˈɑː.nɪst/","defVi":"trung thực, thành thật","defEn":"telling the truth and not lying, cheating, or stealing","examples":["To be completely [honest], I did not really enjoy the movie. (=Dịch: Thành thật mà nói, tôi thực sự không thích bộ phim cho lắm.)","She is known as an [honest] and hardworking employee. (=Dịch: Cô ấy được biết đến là một nhân viên trung thực và chăm chỉ.)","He gave an [honest] answer when the teacher questioned him. (=Dịch: Cậu ấy đã đưa ra câu trả lời thành thật khi giáo viên gặng hỏi.)"],"ukAudio":"/ai_services/tts3/?q=honest&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=honest&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F"},{"id":"lv_0_153","topic":"Daily Life and Social Activities","word":"hostel","pos":"(n)","ipa":"/ˈhɑː.stəl/","defVi":"nhà trọ du lịch, ký túc xá giá rẻ","defEn":"an inexpensive lodging facility, especially for young travelers and backpackers","examples":["We stayed at a youth [hostel] near the train station to save money. (=Dịch: Chúng tôi đã ở tại một nhà nghỉ thanh niên gần nhà ga để tiết kiệm chi phí.)","The [hostel] provides clean shared dorms and a communal kitchen. (=Dịch: Nhà nghỉ cung cấp các phòng ngủ tập thể sạch sẽ và một gian bếp chung.)","Solo backpackers often choose a [hostel] to meet other travelers. (=Dịch: Những người du lịch bụi một mình thường chọn nhà nghỉ giá rẻ để gặp gỡ các du khách khác.)"],"ukAudio":"/ai_services/tts3/?q=hostel&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=hostel&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90.st%C9%99l%2F"},{"id":"lv_0_154","topic":"Daily Life and Social Activities","word":"hugely","pos":"(adv)","ipa":"/ˈhjuːdʒ.li/","defVi":"vô cùng, cực kỳ","defEn":"to a very great degree; extremely","examples":["The new smartphone model has become [hugely] popular among teenagers. (=Dịch: Mẫu điện thoại thông minh mới đã trở nên cực kỳ phổ biến trong giới thanh thiếu niên.)","Her first novel was [hugely] successful around the world. (=Dịch: Cuốn tiểu thuyết đầu tay của cô đã thành công vang dội trên toàn thế giới.)","Renewable energy is a [hugely] important topic in modern science. (=Dịch: Năng lượng tái tạo là một chủ đề vô cùng quan trọng trong khoa học hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=hugely&lang=en-GB&ipa=%2F%CB%88hju%CB%90d%CA%92.li%2F","usAudio":"/ai_services/tts3/?q=hugely&lang=en-US&ipa=%2F%CB%88hju%CB%90d%CA%92.li%2F"},{"id":"lv_0_155","topic":"Daily Life and Social Activities","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.t̬ɚ/","defVi":"thợ săn, kẻ săn mồi","defEn":"a person or animal that searches for and kills wild animals for food or sport","examples":["The ancient [hunter] used a bow and arrow to catch food. (=Dịch: Người thợ săn cổ đại đã sử dụng cung tên để săn bắt thức ăn.)","Owls are skilled nocturnal [hunter] species that search for mice at night. (=Dịch: Cú mèo là loài săn mồi ban đêm điêu luyện chuyên tìm kiếm chuột vào ban đêm.)","A local [hunter] guided the research team through the dense forest. (=Dịch: Một thợ săn địa phương đã dẫn đường cho nhóm nghiên cứu băng qua khu rừng rậm rạp.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%CC%AC%C9%9A%2F"},{"id":"lv_0_156","topic":"Daily Life and Social Activities","word":"hut","pos":"(n)","ipa":"/hʌt/","defVi":"túp lều, nhà gỗ nhỏ","defEn":"a small, simple building, usually consisting of only one room","examples":["The fishermen built a wooden [hut] near the shore to store their nets. (=Dịch: Các ngư dân đã dựng một túp lều gỗ gần bờ để cất giữ lưới.)","We took shelter from the sudden storm inside an old mountain [hut]. (=Dịch: Chúng tôi đã trú cơn bão bất ngờ bên trong một túp lều cũ trên núi.)","The isolated [hut] had no electricity or running water. (=Dịch: Túp lều biệt lập không có điện hay nước máy.)"],"ukAudio":"/ai_services/tts3/?q=hut&lang=en-GB&ipa=%2Fh%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=hut&lang=en-US&ipa=%2Fh%CA%8Ct%2F"},{"id":"lv_0_157","topic":"Daily Life and Social Activities","word":"identity","pos":"(n)","ipa":"/aɪˈden.t̬ə.t̬i/","defVi":"danh tính, bản sắc","defEn":"who a person is, or the qualities of a person or group that make them different from others","examples":["You must show proof of your [identity] before boarding the flight. (=Dịch: Bạn phải xuất trình giấy tờ chứng minh danh tính trước khi lên chuyến bay.)","Language plays a vital role in preserving cultural [identity]. (=Dịch: Ngôn ngữ đóng vai trò thiết yếu trong việc bảo tồn bản sắc văn hóa.)","The criminal used a fake name to conceal his real [identity]. (=Dịch: Tên tội phạm đã sử dụng một cái tên giả để che giấu danh tính thực sự của mình.)"],"ukAudio":"/ai_services/tts3/?q=identity&lang=en-GB&ipa=%2Fa%C9%AA%CB%88den.t%CC%AC%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=identity&lang=en-US&ipa=%2Fa%C9%AA%CB%88den.t%CC%AC%C9%99.t%CC%ACi%2F"},{"id":"lv_0_158","topic":"Daily Life and Social Activities","word":"incident","pos":"(n)","ipa":"/ˈɪn.sə.dənt/","defVi":"sự cố, biến cố, vụ việc","defEn":"an event, especially one that is unusual, important, or violent","examples":["The police are investigating a serious [incident] that occurred downtown. (=Dịch: Cảnh sát đang điều tra một vụ việc nghiêm trọng xảy ra ở trung tâm thành phố.)","Fortunately, the flight landed safely without any [incident]. (=Dịch: May mắn thay, chuyến bay đã hạ cánh an toàn mà không xảy ra bất kỳ sự cố nào.)","She described the minor traffic [incident] to her insurance company. (=Dịch: Cô ấy đã miêu tả sự cố giao thông nhỏ với công ty bảo hiểm của mình.)"],"ukAudio":"/ai_services/tts3/?q=incident&lang=en-GB&ipa=%2F%CB%88%C9%AAn.s%C9%99.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=incident&lang=en-US&ipa=%2F%CB%88%C9%AAn.s%C9%99.d%C9%99nt%2F"},{"id":"lv_0_159","topic":"Daily Life and Social Activities","word":"indicator","pos":"(n)","ipa":"/ˈɪn.də.keɪ.t̬ɚ/","defVi":"chỉ số, dấu hiệu, thiết bị báo hiệu","defEn":"a sign, fact, or measure that shows the state or level of something","examples":["Consumer spending is an important [indicator] of economic health. (=Dịch: Chi tiêu của người tiêu dùng là một chỉ số quan trọng về sức khỏe của nền kinh tế.)","High employee turnover can be a clear [indicator] of poor management. (=Dịch: Tỷ lệ luân chuyển nhân viên cao có thể là một dấu hiệu rõ ràng của việc quản lý kém cỏi.)","The battery [indicator] on my laptop started flashing red. (=Dịch: Đèn báo pin trên máy tính xách tay của tôi bắt đầu nhấp nháy đỏ.)"],"ukAudio":"/ai_services/tts3/?q=indicator&lang=en-GB&ipa=%2F%CB%88%C9%AAn.d%C9%99.ke%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=indicator&lang=en-US&ipa=%2F%CB%88%C9%AAn.d%C9%99.ke%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_0_160","topic":"Daily Life and Social Activities","word":"ingredient","pos":"(n)","ipa":"/ɪnˈɡriː.di.ənt/","defVi":"nguyên liệu, thành phần","defEn":"one of the foods or substances that are combined to make a particular dish or product","examples":["Fresh garlic is an essential [ingredient] in Italian cuisine. (=Dịch: Tỏi tươi là một nguyên liệu thiết yếu trong ẩm thực Ý.)","Always check the [ingredient] list on skincare products for allergens. (=Dịch: Hãy luôn kiểm tra danh sách thành phần trên các sản phẩm chăm sóc da để xem có chất gây dị ứng hay không.)","Trust is the key [ingredient] for a lasting friendship. (=Dịch: Sự tin tưởng là yếu tố then chốt cho một tình bạn lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=ingredient&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=ingredient&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F"},{"id":"lv_0_161","topic":"Daily Life and Social Activities","word":"institution","pos":"(n)","ipa":"/ˌɪn.stəˈtuː.ʃən/","defVi":"tổ chức, cơ quan, thể chế","defEn":"a large and important organization, such as a university or bank","examples":["Harvard University is a world-renowned educational [institution]. (=Dịch: Đại học Harvard là một tổ chức giáo dục nổi tiếng thế giới.)","The central bank is an independent financial [institution]. (=Dịch: Ngân hàng trung ương là một định chế tài chính độc lập.)","Marriage is viewed as a sacred social [institution] in many cultures. (=Dịch: Hôn nhân được coi là một thể chế xã hội thiêng liêng trong nhiều nền văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=institution&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88tu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=institution&lang=en-US&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88tu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_0_162","topic":"Daily Life and Social Activities","word":"interior","pos":"(adj)","ipa":"/ɪnˈtɪr.i.ɚ/","defVi":"bên trong, nội thất","defEn":"inside or situated on the inside; inner","examples":["The [interior] walls of the house were painted soft white. (=Dịch: Các bức tường bên trong ngôi nhà được sơn màu trắng dịu nhẹ.)","She hired an [interior] designer to decorate her new apartment. (=Dịch: Cô ấy đã thuê một nhà thiết kế nội thất để trang trí căn hộ mới của mình.)","The car has a luxurious leather [interior] finish. (=Dịch: Chiếc xe có phần hoàn thiện nội thất bọc da sang trọng.)"],"ukAudio":"/ai_services/tts3/?q=interior&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%AAr.i.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=interior&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%AAr.i.%C9%9A%2F"},{"id":"lv_0_163","topic":"Daily Life and Social Activities","word":"jar","pos":"(n)","ipa":"/dʒɑːr/","defVi":"hũ, lọ (thường bằng thủy tinh, miệng rộng)","defEn":"a glass container with a wide opening, used for storing food or liquids","examples":["She opened a [jar] of strawberry jam to spread on her toast. (=Dịch: Cô ấy đã mở một lọ mứt dâu tây để phết lên bánh mì nướng của mình.)","He keeps all his spare coins in a large glass [jar]. (=Dịch: Anh ấy giữ tất cả tiền xu lẻ của mình trong một chiếc hũ thủy tinh lớn.)","The pickles are preserved tightly in a sealed [jar]. (=Dịch: Dưa muối được bảo quản cẩn thận trong một chiếc lọ đậy kín.)"],"ukAudio":"/ai_services/tts3/?q=jar&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=jar&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90r%2F"},{"id":"lv_0_164","topic":"Daily Life and Social Activities","word":"joint","pos":"(adj)","ipa":"/dʒɔɪnt/","defVi":"chung, cùng nhau, liên kết","defEn":"shared, held, or made by two or more people together","examples":["The two countries launched a [joint] effort to protect the rainforest. (=Dịch: Hai quốc gia đã phát động một nỗ lực chung nhằm bảo vệ rừng nhiệt đới.)","They opened a [joint] bank account after getting married. (=Dịch: Họ đã mở một tài khoản ngân hàng chung sau khi kết hôn.)","The report was a [joint] publication by several leading universities. (=Dịch: Báo cáo này là một ấn phẩm chung của một số trường đại học hàng đầu.)"],"ukAudio":"/ai_services/tts3/?q=joint&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=joint&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AAnt%2F"},{"id":"lv_0_165","topic":"Daily Life and Social Activities","word":"jot","pos":"(v)","ipa":"/dʒɑːt/","defVi":"ghi chép nhanh, ghi vội","defEn":"to write something down quickly and briefly","examples":["Let me [jot] down your phone number before I forget it. (=Dịch: Để tôi ghi nhanh số điện thoại của bạn lại trước khi tôi quên mất.)","The reporter paused to [jot] a few notes in his pad. (=Dịch: Người phóng viên dừng lại để ghi vội vài dòng ghi chú vào cuốn sổ của mình.)","She managed to [jot] down the license plate number of the car. (=Dịch: Cô ấy đã kịp ghi lại biển số của chiếc xe ô tô.)"],"ukAudio":"/ai_services/tts3/?q=jot&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=jot&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90t%2F"},{"id":"lv_0_166","topic":"Daily Life and Social Activities","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba/ngã tư, điểm nối","defEn":"a place where two or more roads, railway lines, or rivers meet","examples":["Turn left at the next [junction] to reach the highway. (=Dịch: Hãy rẽ trái ở nút giao tiếp theo để đi vào đường cao tốc.)","The town developed rapidly because it was located at a major railway [junction]. (=Dịch: Thị trấn phát triển nhanh chóng vì nằm tại một nút giao đường sắt lớn.)","Traffic was held up due to an accident at the busy [junction]. (=Dịch: Giao thông bị đình trệ do một vụ tai nạn tại nút giao thông đông đúc.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_0_167","topic":"Daily Life and Social Activities","word":"junior","pos":"(adj)","ipa":"/ˈdʒuːn.jɚ/","defVi":"cấp dưới, ít kinh nghiệm hơn, sơ cấp","defEn":"having a lower rank or less experience than others in an organization","examples":["She started her career as a [junior] designer at a local firm. (=Dịch: Cô ấy bắt đầu sự nghiệp với tư cách là một nhà thiết kế sơ cấp tại một công ty địa phương.)","The company offers special training programs for [junior] staff members. (=Dịch: Công ty cung cấp các chương trình đào tạo đặc biệt dành cho các nhân viên mới vào nghề.)","He was promoted to project manager after working as a [junior] developer for two years. (=Dịch: Anh ấy đã được thăng chức lên quản lý dự án sau hai năm làm việc ở vị trí lập trình viên sơ cấp.)"],"ukAudio":"/ai_services/tts3/?q=junior&lang=en-GB&ipa=%2F%CB%88d%CA%92u%CB%90n.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=junior&lang=en-US&ipa=%2F%CB%88d%CA%92u%CB%90n.j%C9%9A%2F"},{"id":"lv_0_168","topic":"Daily Life and Social Activities","word":"kangaroo","pos":"(n)","ipa":"/ˌkæŋ.ɡəˈruː/","defVi":"con chuột túi (chuột túi Úc)","defEn":"a large Australian animal that moves by jumping on its strong back legs and carries its young in a pouch","examples":["A [kangaroo] can leap great distances with its powerful hind legs. (=Dịch: Chuột túi có thể nhảy những khoảng cách rất xa nhờ đôi chân sau khỏe mạnh.)","The mother [kangaroo] carried her baby in her warm pouch. (=Dịch: Chuột túi mẹ mang con của mình trong chiếc túi ấm áp.)","Tourists often visit the national park hoping to see a wild [kangaroo]. (=Dịch: Khách du lịch thường ghé thăm vườn quốc gia với hy vọng nhìn thấy một con chuột túi hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=kangaroo&lang=en-GB&ipa=%2F%CB%8Ck%C3%A6%C5%8B.%C9%A1%C9%99%CB%88ru%CB%90%2F","usAudio":"/ai_services/tts3/?q=kangaroo&lang=en-US&ipa=%2F%CB%8Ck%C3%A6%C5%8B.%C9%A1%C9%99%CB%88ru%CB%90%2F"},{"id":"lv_0_169","topic":"Daily Life and Social Activities","word":"keyboard","pos":"(n)","ipa":"/ˈkiː.bɔːrd/","defVi":"bàn phím (máy tính, nhạc cụ)","defEn":"a set of keys on a computer, typewriter, or musical instrument","examples":["He spilled coffee on his computer [keyboard] and broke several keys. (=Dịch: Anh ấy đã làm đổ cà phê lên bàn phím máy tính và làm hỏng một vài phím bấm.)","She practiced playing chords on the electronic [keyboard] every evening. (=Dịch: Cô ấy luyện tập đánh các hợp âm trên đàn phím điện tử vào mỗi buổi tối.)","A wireless [keyboard] makes it easier to work comfortably at a desk. (=Dịch: Một chiếc bàn phím không dây giúp làm việc thoải mái hơn tại bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki%CB%90.b%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki%CB%90.b%C9%94%CB%90rd%2F"},{"id":"lv_0_170","topic":"Daily Life and Social Activities","word":"kick","pos":"(v)","ipa":"/kɪk/","defVi":"đá (bằng chân)","defEn":"to hit someone or something with your foot","examples":["The striker managed to [kick] the ball past the goalkeeper into the net. (=Dịch: Tiền đạo đã sút được bóng qua người thủ môn vào lưới.)","She tried to [kick] the door open because her hands were full. (=Dịch: Cô ấy đã cố đá mở cửa vì hai tay đang mang đầy đồ.)","Children love to splash and [kick] their legs while swimming. (=Dịch: Trẻ em rất thích vỗ nước và đập chân khi bơi.)"],"ukAudio":"/ai_services/tts3/?q=kick&lang=en-GB&ipa=%2Fk%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=kick&lang=en-US&ipa=%2Fk%C9%AAk%2F"},{"id":"lv_0_171","topic":"Daily Life and Social Activities","word":"kit","pos":"(n)","ipa":"/kɪt/","defVi":"bộ dụng cụ, bộ đồ nghề, trang bị","defEn":"a set of tools, clothes, or equipment needed for a particular activity","examples":["Every driver should carry a first-aid [kit] in their vehicle. (=Dịch: Mỗi tài xế nên mang theo một bộ dụng cụ sơ cứu trên xe của mình.)","He bought a tool [kit] to help assemble the new furniture. (=Dịch: Anh ấy đã mua một bộ dụng cụ để giúp lắp ráp đồ nội thất mới.)","The emergency survival [kit] contains water, rations, and a flashlight. (=Dịch: Bộ dụng cụ sinh tồn khẩn cấp bao gồm nước uống, khẩu phần ăn và đèn pin.)"],"ukAudio":"/ai_services/tts3/?q=kit&lang=en-GB&ipa=%2Fk%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=kit&lang=en-US&ipa=%2Fk%C9%AAt%2F"},{"id":"lv_0_172","topic":"Daily Life and Social Activities","word":"latin","pos":"(adj)","ipa":"/ˈlæt.n̩/","defVi":"(thuộc) tiếng La-tinh; (thuộc) vùng/văn hóa Mỹ La-tinh","defEn":"relating to the ancient language of Rome, or to people and cultures influenced by romance languages","examples":["Many modern medical terms are derived from [Latin] words. (=Dịch: Nhiều thuật ngữ y khoa hiện đại có nguồn gốc từ các từ tiếng Latinh.)","The festival celebrates the rich traditions of [Latin] music and dance. (=Dịch: Lễ hội tôn vinh những truyền thống phong phú của âm nhạc và vũ điệu Latinh.)","Most European languages are written using the [Latin] alphabet. (=Dịch: Hầu hết các ngôn ngữ châu Âu đều được viết bằng bảng chữ cái Latinh.)"],"ukAudio":"/ai_services/tts3/?q=latin&lang=en-GB&ipa=%2F%CB%88l%C3%A6t.n%CC%A9%2F","usAudio":"/ai_services/tts3/?q=latin&lang=en-US&ipa=%2F%CB%88l%C3%A6t.n%CC%A9%2F"},{"id":"lv_0_173","topic":"Daily Life and Social Activities","word":"leaflet","pos":"(n)","ipa":"/ˈlif.lət/","defVi":"tờ rơi, tờ quảng cáo gấp","defEn":"a printed sheet of paper containing information or advertising, usually distributed free","examples":["Volunteers handed out an informational [leaflet] to pedestrians on the street. (=Dịch: Các tình nguyện viên đã phát tờ rơi thông tin cho người đi bộ trên đường phố.)","I picked up a [leaflet] about local tourist attractions at the hotel lobby. (=Dịch: Tôi đã lấy một tờ rơi về các điểm du lịch địa phương tại sảnh khách sạn.)","The health clinic designed a colorful [leaflet] to promote healthy eating habits. (=Dịch: Phòng khám y tế đã thiết kế một tờ rơi nhiều màu sắc để quảng bá thói quen ăn uống lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=leaflet&lang=en-GB&ipa=%2F%CB%88lif.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=leaflet&lang=en-US&ipa=%2F%CB%88lif.l%C9%99t%2F"},{"id":"lv_0_174","topic":"Daily Life and Social Activities","word":"lifeboat","pos":"(n)","ipa":"/ˈlaɪf.boʊt/","defVi":"thuyền cứu sinh","defEn":"a specially constructed boat used for rescuing people in danger at sea","examples":["The ship's crew lowered the [lifeboat] into the water during the safety drill. (=Dịch: Thủy thủ đoàn đã hạ xuồng cứu sinh xuống nước trong buổi diễn tập an toàn.)","Everyone on the sinking vessel managed to get into a [lifeboat] safely. (=Dịch: Mọi người trên con tàu đang chìm đều đã lên được xuồng cứu sinh một cách an toàn.)","Modern cruise ships are equipped with more than enough [lifeboat] capacity for all passengers. (=Dịch: Các tàu du lịch hiện đại được trang bị sức chứa xuồng cứu sinh nhiều hơn mức cần thiết cho toàn bộ hành khách.)"],"ukAudio":"/ai_services/tts3/?q=lifeboat&lang=en-GB&ipa=%2F%CB%88la%C9%AAf.bo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=lifeboat&lang=en-US&ipa=%2F%CB%88la%C9%AAf.bo%CA%8At%2F"},{"id":"lv_0_175","topic":"Daily Life and Social Activities","word":"litre","pos":"(n)","ipa":"/ˈli.t̬ɚ/","defVi":"lít (đơn vị đo thể tích)","defEn":"a metric unit of volume equal to 1,000 cubic centimeters or about 1.76 pints","examples":["Adults are generally advised to drink around two [litre] measures of water every day. (=Dịch: Người lớn thường được khuyên nên uống khoảng hai lít nước mỗi ngày.)","She bought a one [litre] bottle of olive oil from the supermarket. (=Dịch: Cô ấy đã mua một chai dầu ô liu một lít từ siêu thị.)","The car's fuel tank can hold up to fifty [litre] units of gasoline. (=Dịch: Bình xăng của chiếc ô tô có thể chứa tới năm mươi lít xăng.)"],"ukAudio":"/ai_services/tts3/?q=litre&lang=en-GB&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litre&lang=en-US&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F"},{"id":"lv_0_176","topic":"Daily Life and Social Activities","word":"litter","pos":"(v)","ipa":"/ˈlɪt̬.ɚ/","defVi":"xả rác bừa bãi","defEn":"to leave pieces of trash lying around in a public place","examples":["Signs in the national park warn visitors not to [litter] on the trails. (=Dịch: Các biển báo trong công viên quốc gia cảnh báo du khách không được xả rác trên các con đường mòn.)","People who [litter] in public areas may face heavy monetary fines. (=Dịch: Những người xả rác ở các khu vực công cộng có thể phải đối mặt với mức phạt tiền nặng.)","Students were reminded not to [litter] the school playground with snack wrappers. (=Dịch: Học sinh được nhắc nhở không vứt rác vỏ đồ ăn vặt bừa bãi ra sân trường.)"],"ukAudio":"/ai_services/tts3/?q=litter&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litter&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F"},{"id":"lv_0_177","topic":"Daily Life and Social Activities","word":"locker","pos":"(n)","ipa":"/ˈlɑ.kɚ/","defVi":"tủ có khóa, tủ để đồ cá nhân","defEn":"a small lockable cupboard or compartment used for storing personal belongings","examples":["Students keep their heavy textbooks in a personal [locker] at school. (=Dịch: Học sinh cất những cuốn sách giáo khoa nặng trong tủ đồ cá nhân ở trường.)","Please put your valuables inside the gym [locker] before entering the pool. (=Dịch: Vui lòng cất đồ có giá trị vào tủ khóa của phòng tập trước khi vào hồ bơi.)","He forgot the combination code to open his metal [locker]. (=Dịch: Anh ấy đã quên mã số kết hợp để mở tủ khóa kim loại của mình.)"],"ukAudio":"/ai_services/tts3/?q=locker&lang=en-GB&ipa=%2F%CB%88l%C9%91.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=locker&lang=en-US&ipa=%2F%CB%88l%C9%91.k%C9%9A%2F"},{"id":"lv_0_178","topic":"Daily Life and Social Activities","word":"lodge","pos":"(v)","ipa":"/lɑdʒ/","defVi":"ở trọ, trọ lại","defEn":"to stay somewhere temporarily, especially by paying for rent or accommodation","examples":["During his internship abroad, he had to [lodge] with a local host family. (=Dịch: Trong thời gian thực tập ở nước ngoài, anh ấy phải ở trọ cùng một gia đình người bản xứ.)","Many university students prefer to [lodge] near campus to save commute time. (=Dịch: Nhiều sinh viên đại học thích trọ gần khuôn viên trường để tiết kiệm thời gian đi lại.)","The traveling researchers will [lodge] at a small guesthouse in the village. (=Dịch: Các nhà nghiên cứu đi công tác sẽ lưu trú tại một nhà khách nhỏ trong làng.)"],"ukAudio":"/ai_services/tts3/?q=lodge&lang=en-GB&ipa=%2Fl%C9%91d%CA%92%2F","usAudio":"/ai_services/tts3/?q=lodge&lang=en-US&ipa=%2Fl%C9%91d%CA%92%2F"},{"id":"lv_0_179","topic":"Daily Life and Social Activities","word":"loss","pos":"(n)","ipa":"/lɔs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state or fact of no longer having something, or a financial deficit","examples":["The company suffered a major financial [loss] during the economic crisis. (=Dịch: Công ty đã phải chịu tổn thất tài chính lớn trong cuộc khủng hoảng kinh tế.)","Regular exercise can help prevent the [loss] of muscle mass as you age. (=Dịch: Tập thể dục thường xuyên có thể giúp ngăn ngừa sự suy giảm khối lượng cơ bắp khi bạn già đi.)","She felt a deep sense of [loss] when her childhood pet passed away. (=Dịch: Cô cảm thấy một sự mất mát sâu sắc khi con thú cưng gắn bó từ thời thơ ấu qua đời.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94s%2F"},{"id":"lv_0_180","topic":"Daily Life and Social Activities","word":"lunchtime","pos":"(n)","ipa":"/ˈlʌntʃ.taɪm/","defVi":"giờ ăn trưa, buổi trưa","defEn":"the time in the middle of the day when people usually eat lunch","examples":["The office cafeteria is always crowded around [lunchtime]. (=Dịch: Căng tin văn phòng luôn đông đúc vào khoảng giờ ăn trưa.)","I usually take a brisk twenty-minute walk during my [lunchtime] break. (=Dịch: Tôi thường đi bộ nhanh hai mươi phút trong giờ nghỉ trưa.)","Let us discuss the new project over [lunchtime] today. (=Dịch: Chúng ta hãy cùng thảo luận về dự án mới trong bữa trưa hôm nay.)"],"ukAudio":"/ai_services/tts3/?q=lunchtime&lang=en-GB&ipa=%2F%CB%88l%CA%8Cnt%CA%83.ta%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=lunchtime&lang=en-US&ipa=%2F%CB%88l%CA%8Cnt%CA%83.ta%C9%AAm%2F"},{"id":"lv_0_181","topic":"Daily Life and Social Activities","word":"magic","pos":"(adj)","ipa":"/ˈmædʒ.ɪk/","defVi":"kỳ diệu, ma thuật, huyền bí","defEn":"having special mysterious powers, or producing delightful and wonderful effects","examples":["The children listened eagerly to the fairy tale about a [magic] carpet. (=Dịch: Lũ trẻ háo hức lắng nghe câu chuyện cổ tích về một tấm thảm thần kỳ.)","Watching the sunset over the quiet ocean was a truly [magic] experience. (=Dịch: Ngắm hoàng hôn trên đại dương tĩnh lặng là một trải nghiệm thực sự kỳ diệu.)","There is no [magic] solution to learning a foreign language overnight. (=Dịch: Không có giải pháp thần kỳ nào để học một ngoại ngữ chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_0_182","topic":"Daily Life and Social Activities","word":"maker","pos":"(n)","ipa":"/ˈmeɪ.kɚ/","defVi":"người sản xuất, nhà chế tạo","defEn":"a person, company, or thing that produces or creates something","examples":["The smartphone [maker] announced its latest model at the tech conference. (=Dịch: Nhà sản xuất điện thoại thông minh đã công bố mẫu mới nhất của mình tại hội nghị công nghệ.)","He is a skilled violin [maker] known for exceptional craftsmanship. (=Dịch: Ông là một thợ làm đàn vĩ cầm lành nghề, nổi tiếng với tay nghề thủ công xuất sắc.)","The car [maker] recalled thousands of vehicles due to a software defect. (=Dịch: Hãng sản xuất ô tô đã triệu hồi hàng nghìn phương tiện do lỗi phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=maker&lang=en-GB&ipa=%2F%CB%88me%C9%AA.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=maker&lang=en-US&ipa=%2F%CB%88me%C9%AA.k%C9%9A%2F"},{"id":"lv_0_183","topic":"Daily Life and Social Activities","word":"manual","pos":"(adj)","ipa":"/ˈmæn.ju.əl/","defVi":"thủ công, bằng tay","defEn":"done with the hands rather than by a machine","examples":["Many farmers in the region still rely on [manual] labor to harvest crops. (=Dịch: Nhiều nông dân trong khu vực vẫn dựa vào lao động chân tay để thu hoạch mùa màng.)","The car has a [manual] transmission instead of an automatic one. (=Dịch: Chiếc xe này có hộp số sàn thay vì hộp số tự động.)","Sorting these documents requires careful [manual] checking. (=Dịch: Việc phân loại các tài liệu này đòi hỏi phải kiểm tra thủ công cẩn thận.)"],"ukAudio":"/ai_services/tts3/?q=manual&lang=en-GB&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=manual&lang=en-US&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F"},{"id":"lv_0_184","topic":"Daily Life and Social Activities","word":"marathon","pos":"(n)","ipa":"/ˈmær.ə.θɑːn/","defVi":"cuộc chạy ma-ra-tông, cuộc đua việt dã","defEn":"a long-distance running race of 42.195 kilometers (26.2 miles)","examples":["She trained diligently for six months to finish her first [marathon]. (=Dịch: Cô ấy đã chăm chỉ luyện tập trong sáu tháng để hoàn thành cuộc chạy marathon đầu tiên của mình.)","Thousands of international runners participate in the annual city [marathon]. (=Dịch: Hàng ngàn chân chạy quốc tế tham gia vào giải marathon thường niên của thành phố.)","Running a full [marathon] requires tremendous mental and physical stamina. (=Dịch: Chạy trọn vẹn một cự ly marathon đòi hỏi sức bền to lớn cả về thể chất lẫn tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=marathon&lang=en-GB&ipa=%2F%CB%88m%C3%A6r.%C9%99.%CE%B8%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=marathon&lang=en-US&ipa=%2F%CB%88m%C3%A6r.%C9%99.%CE%B8%C9%91%CB%90n%2F"},{"id":"lv_0_185","topic":"Daily Life and Social Activities","word":"marvellous","pos":"(adj)","ipa":"/ˈmɑːr.vəl.əs/","defVi":"tuyệt vời, kỳ diệu","defEn":"extremely good, wonderful, or extraordinary","examples":["We had a [marvellous] time exploring the ancient ruins during our vacation. (=Dịch: Chúng tôi đã có một khoảng thời gian tuyệt vời để khám phá những tàn tích cổ xưa trong kỳ nghỉ của mình.)","The violinist gave a [marvellous] performance that captivated the audience. (=Dịch: Nghệ sĩ vĩ cầm đã có một màn trình diễn tuyệt vời làm say đắm khán giả.)","She made a [marvellous] recovery after the major surgery. (=Dịch: Cô ấy đã hồi phục một cách kỳ diệu sau ca đại phẫu.)"],"ukAudio":"/ai_services/tts3/?q=marvellous&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90r.v%C9%99l.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=marvellous&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90r.v%C9%99l.%C9%99s%2F"},{"id":"lv_0_186","topic":"Daily Life and Social Activities","word":"mature","pos":"(adj)","ipa":"/məˈtʃʊr/","defVi":"trưởng trưởng, chín chắn","defEn":"fully developed physically or behaving in a sensible, adult way","examples":["He is very [mature] for his age and handles responsibility well. (=Dịch: Cậu ấy rất chín chắn so với tuổi của mình và đảm đương tốt trách nhiệm.)","The cheese needs to be stored in a cool place until it becomes [mature]. (=Dịch: Phô mai cần được bảo quản ở nơi thoáng mát cho đến khi đạt độ chín muồi.)","After a [mature] consideration, they decided to invest in the project. (=Dịch: Sau khi cân nhắc kỹ lưỡng, họ đã quyết định đầu tư vào dự án.)"],"ukAudio":"/ai_services/tts3/?q=mature&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=mature&lang=en-US&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F"},{"id":"lv_0_187","topic":"Daily Life and Social Activities","word":"mayor","pos":"(n)","ipa":"/ˈmeɪ.ər/","defVi":"thị trưởng","defEn":"the elected head of a city or town government","examples":["The newly elected [mayor] promised to improve public transportation. (=Dịch: Thị trưởng mới đắc cử đã hứa sẽ cải thiện giao thông công cộng.)","Citizens gathered at the town hall to voice their concerns to the [mayor]. (=Dịch: Người dân đã tập hợp tại tòa thị chính để bày tỏ những mối quan ngại của họ với thị trưởng.)","The [mayor] attended the opening ceremony of the new community center. (=Dịch: Thị trưởng đã tham dự lễ khánh thành trung tâm cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=mayor&lang=en-GB&ipa=%2F%CB%88me%C9%AA.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=mayor&lang=en-US&ipa=%2F%CB%88me%C9%AA.%C9%99r%2F"},{"id":"lv_0_188","topic":"Daily Life and Social Activities","word":"medal","pos":"(n)","ipa":"/ˈmed.əl/","defVi":"huy chương","defEn":"a small metal disc given as a reward for a brave action or sports achievement","examples":["The athlete won a gold [medal] in the 100-meter sprint. (=Dịch: Vận động viên đã giành được huy chương vàng ở nội dung chạy nước rút 100 mét.)","He was awarded a [medal] of honor for his bravery during the rescue operation. (=Dịch: Anh ấy đã được trao tặng huy chương danh dự vì sự dũng cảm trong chiến dịch cứu hộ.)","She proudly displayed each [medal] she had earned on the wall. (=Dịch: Cô tự hào trưng bày từng tấm huy chương mình đã đạt được lên tường.)"],"ukAudio":"/ai_services/tts3/?q=medal&lang=en-GB&ipa=%2F%CB%88med.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=medal&lang=en-US&ipa=%2F%CB%88med.%C9%99l%2F"},{"id":"lv_0_189","topic":"Daily Life and Social Activities","word":"medication","pos":"(n)","ipa":"/ˌmed.əˈkeɪ.ʃən/","defVi":"thuốc men, dược phẩm","defEn":"a substance used to treat an illness or medical condition","examples":["The doctor prescribed a new [medication] to lower his blood pressure. (=Dịch: Bác sĩ đã kê một loại thuốc mới để hạ huyết áp cho ông ấy.)","You should always check the side effects before taking any [medication]. (=Dịch: Bạn nên luôn kiểm tra các tác dụng phụ trước khi dùng bất kỳ loại thuốc nào.)","She is currently on daily [medication] for her allergies. (=Dịch: Hiện tại cô ấy đang phải uống thuốc hàng ngày để trị dị ứng.)"],"ukAudio":"/ai_services/tts3/?q=medication&lang=en-GB&ipa=%2F%CB%8Cmed.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=medication&lang=en-US&ipa=%2F%CB%8Cmed.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_190","topic":"Daily Life and Social Activities","word":"metallic","pos":"(adj)","ipa":"/məˈtæl.ɪk/","defVi":"bằng kim loại, có ánh kim","defEn":"made of metal, or having the appearance or sound of metal","examples":["The sports car was painted in a shiny [metallic] blue finish. (=Dịch: Chiếc xe thể thao được sơn lớp màu xanh dương ánh kim bóng bẩy.)","There was a loud [metallic] sound when the gate slammed shut. (=Dịch: Có một tiếng kim loại lớn vang lên khi cánh cổng đóng sầm lại.)","The robot had a cold, [metallic] frame designed for heavy lifting. (=Dịch: Con robot có bộ khung kim loại lạnh lẽo được thiết kế để nâng vật nặng.)"],"ukAudio":"/ai_services/tts3/?q=metallic&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%C3%A6l.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=metallic&lang=en-US&ipa=%2Fm%C9%99%CB%88t%C3%A6l.%C9%AAk%2F"},{"id":"lv_0_191","topic":"Daily Life and Social Activities","word":"microphone","pos":"(n)","ipa":"/ˈmaɪ.krə.foʊn/","defVi":"micrô","defEn":"an electronic device used to record or amplify sound","examples":["Please speak directly into the [microphone] so everyone can hear you clearly. (=Dịch: Xin vui lòng nói trực tiếp vào micrô để mọi người có thể nghe rõ bạn.)","The singer adjusted the [microphone] stand before starting her song. (=Dịch: Nữ ca sĩ đã điều chỉnh chân đế micrô trước khi bắt đầu bài hát của mình.)","A wireless [microphone] gives the presenter more freedom to move around. (=Dịch: Micrô không dây giúp người thuyết trình thoải mái di chuyển hơn.)"],"ukAudio":"/ai_services/tts3/?q=microphone&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kr%C9%99.fo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=microphone&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kr%C9%99.fo%CA%8An%2F"},{"id":"lv_0_192","topic":"Daily Life and Social Activities","word":"mid","pos":"(adj)","ipa":"/mɪd/","defVi":"ở giữa, trung kỳ","defEn":"located in the middle or middle part of something","examples":["The team experienced a sudden slump in [mid] season. (=Dịch: Đội bóng đã trải qua một đợt sa sút phong độ bất ngờ vào giữa mùa giải.)","She was born in the [mid] 1990s and grew up with modern technology. (=Dịch: Cô sinh vào giữa những năm 1990 và lớn lên cùng với công nghệ hiện đại.)","We planned a trip for [mid] July when the weather is warmest. (=Dịch: Chúng tôi đã lên kế hoạch cho một chuyến đi vào giữa tháng Bảy khi thời tiết ấm áp nhất.)"],"ukAudio":"/ai_services/tts3/?q=mid&lang=en-GB&ipa=%2Fm%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=mid&lang=en-US&ipa=%2Fm%C9%AAd%2F"},{"id":"lv_0_193","topic":"Daily Life and Social Activities","word":"midday","pos":"(n)","ipa":"/ˌmɪdˈdeɪ/","defVi":"buổi trưa, giữa trưa","defEn":"the middle of the day; twelve o'clock or noon","examples":["The sun is at its highest point in the sky at [midday]. (=Dịch: Mặt trời ở vị trí cao nhất trên bầu trời vào lúc giữa trưa.)","Workers usually take a short break around [midday] for lunch. (=Dịch: Các công nhân thường nghỉ giải lao một chút vào khoảng giữa trưa để ăn trưa.)","It is best to avoid outdoor exercise during the intense [midday] heat. (=Dịch: Tốt nhất là nên tránh tập thể dục ngoài trời dưới cái nóng gay gắt lúc giữa trưa.)"],"ukAudio":"/ai_services/tts3/?q=midday&lang=en-GB&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=midday&lang=en-US&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F"},{"id":"lv_0_194","topic":"Daily Life and Social Activities","word":"minibus","pos":"(n)","ipa":"/ˈmɪn.i.bʌs/","defVi":"xe buýt nhỏ","defEn":"a small bus that usually carries about 8 to 30 people","examples":["We rented a [minibus] to take the whole family to the beach. (=Dịch: Chúng tôi đã thuê một chiếc xe buýt nhỏ để đưa cả gia đình đi biển.)","The hotel provides a free [minibus] service to the airport. (=Dịch: Khách sạn cung cấp dịch vụ xe buýt nhỏ miễn phí đến sân bay.)","The local sports team traveled to the match in a [minibus]. (=Dịch: Đội thể thao địa phương đã di chuyển đến trận đấu bằng xe buýt nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=minibus&lang=en-GB&ipa=%2F%CB%88m%C9%AAn.i.b%CA%8Cs%2F","usAudio":"/ai_services/tts3/?q=minibus&lang=en-US&ipa=%2F%CB%88m%C9%AAn.i.b%CA%8Cs%2F"},{"id":"lv_0_195","topic":"Daily Life and Social Activities","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai mỏ, sự khai thác khoáng sản","defEn":"the process or industry of obtaining coal or other minerals from a mine","examples":["The local economy relies heavily on coal [mining]. (=Dịch: Nền kinh tế địa phương phụ thuộc rất nhiều vào ngành khai thác than.)","Environmental groups are concerned about the effects of gold [mining]. (=Dịch: Các nhóm môi trường đang lo ngại về những tác động của việc khai thác vàng.)","New safety regulations were introduced to reduce [mining] accidents. (=Dịch: Các quy định an toàn mới đã được ban hành nhằm giảm thiểu các vụ tai nạn khai thác mỏ.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_0_196","topic":"Daily Life and Social Activities","word":"mode","pos":"(n)","ipa":"/moʊd/","defVi":"chế độ, phương thức","defEn":"a particular way or manner in which something is done or happens","examples":["Cycling is an eco-friendly [mode] of transport in the city. (=Dịch: Đi xe đạp là một phương thức di chuyển thân thiện với môi trường trong thành phố.)","You should switch your mobile phone to silent [mode] during the lecture. (=Dịch: Bạn nên chuyển điện thoại di động sang chế độ im lặng trong suốt bài giảng.)","The company changed its [mode] of operation after the pandemic. (=Dịch: Công ty đã thay đổi phương thức hoạt động sau đại dịch.)"],"ukAudio":"/ai_services/tts3/?q=mode&lang=en-GB&ipa=%2Fmo%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=mode&lang=en-US&ipa=%2Fmo%CA%8Ad%2F"},{"id":"lv_0_197","topic":"Daily Life and Social Activities","word":"monthly","pos":"(adj)","ipa":"/ˈmʌnθ.li/","defVi":"hàng tháng","defEn":"happening, produced, or paid once every month","examples":["The team holds a [monthly] meeting to discuss their progress. (=Dịch: Nhóm tổ chức một cuộc họp hàng tháng để thảo luận về tiến độ của họ.)","She pays a [monthly] subscription fee for the music app. (=Dịch: Cô ấy trả phí thuê bao hàng tháng cho ứng dụng nghe nhạc.)","The magazine is published as a [monthly] issue. (=Dịch: Tạp chí này được xuất bản dưới dạng ấn bản hàng tháng.)"],"ukAudio":"/ai_services/tts3/?q=monthly&lang=en-GB&ipa=%2F%CB%88m%CA%8Cn%CE%B8.li%2F","usAudio":"/ai_services/tts3/?q=monthly&lang=en-US&ipa=%2F%CB%88m%CA%8Cn%CE%B8.li%2F"},{"id":"lv_0_198","topic":"Daily Life and Social Activities","word":"monument","pos":"(n)","ipa":"/ˈmɑːn.jə.mənt/","defVi":"đài tưởng niệm, tượng đài, di tích","defEn":"a structure erected to commemorate a person or important event","examples":["A large stone [monument] was built in honor of the soldiers. (=Dịch: Một đài tưởng niệm lớn bằng đá đã được xây dựng để vinh danh những người lính.)","The ancient temple is protected as a national [monument]. (=Dịch: Ngôi đền cổ này được bảo tồn như một di tích quốc gia.)","Tourists gathered around the historic [monument] to take photos. (=Dịch: Khách du lịch tụ tập quanh di tích lịch sử để chụp ảnh.)"],"ukAudio":"/ai_services/tts3/?q=monument&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90n.j%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=monument&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90n.j%C9%99.m%C9%99nt%2F"},{"id":"lv_0_199","topic":"Daily Life and Social Activities","word":"motivating","pos":"(adj)","ipa":"/ˈmoʊ.t̬ə.veɪ.t̬ɪŋ/","defVi":"có tính khích lệ, tạo động lực","defEn":"making you feel enthusiastic and eager to do something","examples":["Her speech was incredibly [motivating] for all the new students. (=Dịch: Bài phát biểu của cô ấy đã truyền rất nhiều động lực cho tất cả các tân sinh viên.)","A supportive teacher creates a [motivating] learning environment. (=Dịch: Một giáo viên luôn hỗ trợ sẽ tạo ra một môi trường học tập giàu động lực.)","Setting small goals can be very [motivating] during a difficult project. (=Dịch: Việc đặt ra những mục tiêu nhỏ có thể tạo động lực rất lớn trong suốt một dự án khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=motivating&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.t%CC%AC%C9%99.ve%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=motivating&lang=en-US&ipa=%2F%CB%88mo%CA%8A.t%CC%AC%C9%99.ve%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_200","topic":"Daily Life and Social Activities","word":"mount","pos":"(n)","ipa":"/maʊnt/","defVi":"ngọn núi, đỉnh núi","defEn":"a mountain or hill, often used as part of a proper name","examples":["[Mount] Everest is the highest mountain above sea level in the world. (=Dịch: Đỉnh Everest là ngọn núi cao nhất thế giới so với mực nước biển.)","They decided to climb [Mount] Fuji during their trip to Japan. (=Dịch: Họ quyết định leo Núi Phú Sĩ trong chuyến đi đến Nhật Bản.)","The summit of the [mount] was covered with thick snow. (=Dịch: Đỉnh núi bị bao phủ bởi tuyết dày.)"],"ukAudio":"/ai_services/tts3/?q=mount&lang=en-GB&ipa=%2Fma%CA%8Ant%2F","usAudio":"/ai_services/tts3/?q=mount&lang=en-US&ipa=%2Fma%CA%8Ant%2F"},{"id":"lv_0_201","topic":"Daily Life and Social Activities","word":"mountainside","pos":"(n)","ipa":"/ˈmaʊn.tən.saɪd/","defVi":"sườn núi","defEn":"the side or slope of a mountain","examples":["Small villages are scattered across the green [mountainside]. (=Dịch: Những ngôi làng nhỏ nằm rải rác khắp sườn núi xanh tươi.)","Heavy rain caused a landslide on the steep [mountainside]. (=Dịch: Mưa lớn đã gây ra lở đất trên sườn núi dốc.)","They built a cozy wooden cabin high up on the [mountainside]. (=Dịch: Họ đã xây một căn nhà gỗ ấm cúng ở tít trên sườn núi.)"],"ukAudio":"/ai_services/tts3/?q=mountainside&lang=en-GB&ipa=%2F%CB%88ma%CA%8An.t%C9%99n.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=mountainside&lang=en-US&ipa=%2F%CB%88ma%CA%8An.t%C9%99n.sa%C9%AAd%2F"},{"id":"lv_0_202","topic":"Daily Life and Social Activities","word":"mr.","pos":"(n)","ipa":"/ˈmɪs.tɚ/","defVi":"ông, ngài (danh xưng cho nam giới)","defEn":"a title used before the surname or full name of a man","examples":["[Mr.] Johnson will lead the meeting this afternoon. (=Dịch: Ông Johnson sẽ chủ trì cuộc họp chiều nay.)","Please address your letter to [Mr.] Davis in the marketing department. (=Dịch: Vui lòng ghi người nhận thư là ông Davis ở phòng tiếp thị.)","The receptionist asked [Mr.] Brown to sign his name in the guest book. (=Dịch: Nhân viên lễ tân đã đề nghị ông Brown ký tên vào sổ khách lưu trú.)"],"ukAudio":"/ai_services/tts3/?q=mr.&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mr.&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A%2F"},{"id":"lv_0_203","topic":"Daily Life and Social Activities","word":"ms.","pos":"(n)","ipa":"/mɪz/","defVi":"cô, bà (danh xưng cho nữ giới, không phân biệt đã kết hôn hay chưa)","defEn":"a title used before the surname or full name of a woman, regardless of marital status","examples":["[Ms.] Lee was recently promoted to head of the department. (=Dịch: Cô Lee gần đây đã được thăng chức lên vị trí trưởng phòng.)","Can I leave a message for [Ms.] Taylor while she is away? (=Dịch: Tôi có thể để lại lời nhắn cho cô Taylor trong lúc cô ấy đi vắng được không?)","The award was presented to [Ms.] Green for her outstanding research. (=Dịch: Giải thưởng đã được trao tặng cho cô Green vì công trình nghiên cứu xuất sắc của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=ms.&lang=en-GB&ipa=%2Fm%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=ms.&lang=en-US&ipa=%2Fm%C9%AAz%2F"},{"id":"lv_0_204","topic":"Daily Life and Social Activities","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tə.ri/","defVi":"điều bí ẩn, điều huyền bí","defEn":"something strange or not known that cannot be explained or understood","examples":["The exact cause of the plane crash remains a [mystery]. (=Dịch: Nguyên nhân chính xác của vụ tai nạn máy bay vẫn còn là một bí ẩn.)","He loves reading detective novels and solving a good [mystery]. (=Dịch: Anh ấy thích đọc tiểu thuyết trinh thám và giải mã những bí ẩn thú vị.)","How the ancient monument was constructed is still shrouded in [mystery]. (=Dịch: Cách thức xây dựng tượng đài cổ kính này vẫn còn bị bao phủ trong bức màn bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%99.ri%2F"},{"id":"lv_0_205","topic":"Daily Life and Social Activities","word":"nationality","pos":"(n)","ipa":"/ˌnæʃ.əˈnæl.ə.t̬i/","defVi":"quốc tịch","defEn":"the state of belonging to a particular nation by origin, birth, or naturalization","examples":["Please state your name, date of birth, and [nationality] on the visa form. (=Dịch: Vui lòng ghi rõ họ tên, ngày sinh và quốc tịch của bạn trên mẫu đơn xin thị thực.)","The international school welcomes students of many different [nationalities]. (=Dịch: Trường quốc tế này chào đón học sinh thuộc nhiều quốc tịch khác nhau.)","She holds dual [nationality] because her parents come from two different countries. (=Dịch: Cô ấy mang hai quốc tịch vì bố mẹ cô đến từ hai quốc gia khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=nationality&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=nationality&lang=en-US&ipa=%2F%CB%8Cn%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_0_206","topic":"Daily Life and Social Activities","word":"nineteen","pos":"(n)","ipa":"/ˌnaɪnˈtiːn/","defVi":"số mười chín","defEn":"the number 19","examples":["She will celebrate her [nineteen]th birthday next week. (=Dịch: Cô ấy sẽ tổ chức sinh nhật lần thứ mười chín vào tuần tới.)","There are [nineteen] students enrolled in the advanced English class. (=Dịch: Có mười chín học viên đăng ký vào lớp tiếng Anh nâng cao.)","The bus route number [nineteen] goes directly to the university campus. (=Dịch: Tuyến xe buýt số mười chín đi thẳng đến khuôn viên trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=nineteen&lang=en-GB&ipa=%2F%CB%8Cna%C9%AAn%CB%88ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=nineteen&lang=en-US&ipa=%2F%CB%8Cna%C9%AAn%CB%88ti%CB%90n%2F"},{"id":"lv_0_207","topic":"Daily Life and Social Activities","word":"ninety","pos":"(n)","ipa":"/ˈnaɪn.ti/","defVi":"số chín mươi","defEn":"the number 90","examples":["My grandfather lived an active life until he was almost [ninety]. (=Dịch: Ông tôi đã sống một cuộc sống năng động cho đến khi gần chín mươi tuổi.)","Over [ninety] percent of the surveyed applicants passed the test. (=Dịch: Hơn chín mươi phần trăm các ứng viên được khảo sát đã vượt qua bài kiểm tra.)","The speed limit on this highway is [ninety] kilometers per hour. (=Dịch: Tốc độ giới hạn trên đường cao tốc này là chín mươi kilomet một giờ.)"],"ukAudio":"/ai_services/tts3/?q=ninety&lang=en-GB&ipa=%2F%CB%88na%C9%AAn.ti%2F","usAudio":"/ai_services/tts3/?q=ninety&lang=en-US&ipa=%2F%CB%88na%C9%AAn.ti%2F"},{"id":"lv_0_208","topic":"Daily Life and Social Activities","word":"occupation","pos":"(n)","ipa":"/ˌɑː.kjəˈpeɪ.ʃən/","defVi":"nghề nghiệp, công việc","defEn":"a person's regular work, profession, or job","examples":["Please write down your current [occupation] and employer on the application form. (=Dịch: Vui lòng ghi nghề nghiệp hiện tại và tên người sử dụng lao động vào mẫu đơn đăng ký.)","Teaching is a demanding [occupation] that requires patience and dedication. (=Dịch: Dạy học là một nghề nghiệp đòi hỏi nhiều nỗ lực, cần có sự kiên nhẫn và lòng tận tụy.)","He decided to change his [occupation] after working in finance for a decade. (=Dịch: Anh ấy quyết định thay đổi nghề nghiệp sau khi làm việc trong lĩnh vực tài chính suốt một thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=occupation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.kj%C9%99%CB%88pe%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=occupation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.kj%C9%99%CB%88pe%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_209","topic":"Daily Life and Social Activities","word":"opt","pos":"(v)","ipa":"/ɑːpt/","defVi":"lựa chọn, quyết định chọn","defEn":"to make a choice or decision from a range of possibilities","examples":["Many young professionals [opt] to rent rather than buy an apartment. (=Dịch: Nhiều chuyên gia trẻ tuổi chọn thuê nhà hơn là mua một căn hộ.)","Instead of flying, they decided to [opt] for a scenic train journey. (=Dịch: Thay vì đi máy bay, họ quyết định chọn một chuyến đi bằng tàu hỏa ngắm cảnh.)","Students can [opt] out of the sports program if they have medical reasons. (=Dịch: Học sinh có thể chọn không tham gia chương trình thể thao nếu có lý do y tế.)"],"ukAudio":"/ai_services/tts3/?q=opt&lang=en-GB&ipa=%2F%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=opt&lang=en-US&ipa=%2F%C9%91%CB%90pt%2F"},{"id":"lv_0_210","topic":"Daily Life and Social Activities","word":"optional","pos":"(adj)","ipa":"/ˈɑːp.ʃən.əl/","defVi":"tùy chọn, không bắt buộc","defEn":"available to be chosen but not mandatory or compulsory","examples":["Attendance at the introductory workshop is purely [optional]. (=Dịch: Việc tham dự hội thảo giới thiệu là hoàn toàn tùy chọn.)","The software includes several [optional] features that you can install later. (=Dịch: Phần mềm này bao gồm một số tính năng tùy chọn mà bạn có thể cài đặt sau.)","Foreign language study was [optional] for science students at the university. (=Dịch: Việc học ngoại ngữ là tự chọn đối với các sinh viên ngành khoa học tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=optional&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90p.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=optional&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90p.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_0_211","topic":"Daily Life and Social Activities","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians who play various instruments together, usually led by a conductor","examples":["She plays the violin in the city's youth [orchestra]. (=Dịch: Cô ấy chơi violin trong dàn nhạc thanh thiếu niên của thành phố.)","The [orchestra] gave a magnificent performance of Beethoven's Fifth Symphony. (=Dịch: Dàn nhạc đã có một buổi biểu diễn tuyệt vời bản Giao hưởng số 5 của Beethoven.)","Conducting a world-class [orchestra] requires immense skill and musicality. (=Dịch: Việc chỉ huy một dàn nhạc đẳng cấp thế giới đòi hỏi kỹ năng và cảm thụ âm nhạc vô cùng to lớn.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_0_212","topic":"Daily Life and Social Activities","word":"organiser","pos":"(n)","ipa":"/ˈɔːr.ɡə.naɪ.zɚ/","defVi":"người tổ chức, ban tổ chức","defEn":"a person or organization responsible for planning and coordinating an event or activity","examples":["The event [organiser] announced changes to the schedule due to heavy rain. (=Dịch: Ban tổ chức sự kiện đã thông báo những thay đổi về lịch trình do mưa lớn.)","She is a skilled conference [organiser] who manages large international gatherings. (=Dịch: Cô ấy là một nhà tổ chức hội nghị lành nghề, chuyên điều hành các cuộc họp quốc tế lớn.)","Please contact the festival [organiser] if you wish to set up a food stall. (=Dịch: Vui lòng liên hệ với nhà tổ chức lễ hội nếu bạn muốn mở một quầy bán đồ ăn.)"],"ukAudio":"/ai_services/tts3/?q=organiser&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99.na%C9%AA.z%C9%9A%2F","usAudio":"/ai_services/tts3/?q=organiser&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99.na%C9%AA.z%C9%9A%2F"},{"id":"lv_0_213","topic":"Daily Life and Social Activities","word":"origin","pos":"(n)","ipa":"/ˈɔːr.ə.dʒɪn/","defVi":"nguồn gốc, căn nguyên","defEn":"the point, place, or source where something begins or comes from","examples":["Scientists are still investigating the evolutionary [origin] of the species. (=Dịch: Các nhà khoa học vẫn đang nghiên cứu nguồn gốc tiến hóa của loài này.)","The customs official asked about the country of [origin] of the imported goods. (=Dịch: Viên chức hải quan đã hỏi về quốc gia xuất xứ của hàng hóa nhập khẩu.)","The phrase has its [origin] in an ancient Greek fable. (=Dịch: Cụm từ này có nguồn gốc từ một câu chuyện ngụ ngôn Hy Lạp cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=origin&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=origin&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F"},{"id":"lv_0_214","topic":"Daily Life and Social Activities","word":"outdoor","pos":"(adj)","ipa":"/ˈaʊt.dɔr/","defVi":"ngoài trời","defEn":"happening, located, or used outside rather than in a building","examples":["They enjoy [outdoor] activities like hiking and camping during the summer. (=Dịch: Họ thích các hoạt động ngoài trời như đi bộ đường dài và cắm trại vào mùa hè.)","The hotel features a large [outdoor] swimming pool for guests. (=Dịch: Khách sạn có một hồ bơi lớn ngoài trời dành cho du khách.)","Wearing sunscreen is essential when doing [outdoor] sports. (=Dịch: Bôi kem chống nắng là điều cần thiết khi chơi các môn thể thao ngoài trời.)"],"ukAudio":"/ai_services/tts3/?q=outdoor&lang=en-GB&ipa=%2F%CB%88a%CA%8At.d%C9%94r%2F","usAudio":"/ai_services/tts3/?q=outdoor&lang=en-US&ipa=%2F%CB%88a%CA%8At.d%C9%94r%2F"},{"id":"lv_0_215","topic":"Daily Life and Social Activities","word":"package","pos":"(n)","ipa":"/ˈpæk.ɪdʒ/","defVi":"gói dịch vụ, gói ưu đãi","defEn":"a set of related services or products offered together as a single unit","examples":["The travel agency offers an attractive holiday [package] with flights included. (=Dịch: Công ty lữ hành cung cấp một gói kỳ nghỉ hấp dẫn đã bao gồm vé máy bay.)","We selected an internet [package] that provides unlimited high-speed data. (=Dịch: Chúng tôi đã chọn một gói cước internet cung cấp dữ liệu tốc độ cao không giới hạn.)","The hotel created a special wedding [package] for couples on a budget. (=Dịch: Khách sạn đã thiết kế một gói tiệc cưới đặc biệt dành cho các cặp đôi có ngân sách hạn hẹp.)"],"ukAudio":"/ai_services/tts3/?q=package&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=package&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F"},{"id":"lv_0_216","topic":"Daily Life and Social Activities","word":"pathway","pos":"(n)","ipa":"/ˈpæθ.weɪ/","defVi":"lối đi, đường mòn","defEn":"a track or path that people can walk along","examples":["A stone [pathway] leads from the garden gate to the front door. (=Dịch: Một lối đi bằng đá dẫn từ cổng vườn vào đến cửa trước.)","Education is often seen as a [pathway] to success and financial stability. (=Dịch: Giáo dục thường được xem là con đường dẫn đến thành công và sự ổn định tài chính.)","We walked along the coastal [pathway] to admire the sunset. (=Dịch: Chúng tôi đã đi dạo dọc theo con đường ven biển để ngắm hoàng hôn.)"],"ukAudio":"/ai_services/tts3/?q=pathway&lang=en-GB&ipa=%2F%CB%88p%C3%A6%CE%B8.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=pathway&lang=en-US&ipa=%2F%CB%88p%C3%A6%CE%B8.we%C9%AA%2F"},{"id":"lv_0_217","topic":"Daily Life and Social Activities","word":"payment","pos":"(n)","ipa":"/ˈpeɪ.mənt/","defVi":"khoản thanh toán, sự chi trả","defEn":"an amount of money paid, or the act of paying","examples":["You can make your [payment] by credit card or cash. (=Dịch: Bạn có thể thanh toán bằng thẻ tín dụng hoặc tiền mặt.)","The company demands immediate [payment] for the delivered goods. (=Dịch: Công ty yêu cầu thanh toán ngay lập tức cho số hàng đã giao.)","She set up automatic monthly [payment] for her electricity bill. (=Dịch: Cô ấy đã thiết lập thanh toán tự động hàng tháng cho hóa đơn tiền điện.)"],"ukAudio":"/ai_services/tts3/?q=payment&lang=en-GB&ipa=%2F%CB%88pe%C9%AA.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=payment&lang=en-US&ipa=%2F%CB%88pe%C9%AA.m%C9%99nt%2F"},{"id":"lv_0_218","topic":"Daily Life and Social Activities","word":"peak","pos":"(n)","ipa":"/pik/","defVi":"đỉnh núi, thời điểm đỉnh cao","defEn":"the pointed top of a mountain, or the highest point of something","examples":["The climbers finally reached the snow-covered [peak] at noon. (=Dịch: Những người leo núi cuối cùng đã lên tới đỉnh núi phủ tuyết trắng vào buổi trưa.)","Traffic congestion usually reaches its [peak] around five in the afternoon. (=Dịch: Tình trạng tắc nghẽn giao thông thường đạt đỉnh điểm vào khoảng năm giờ chiều.)","The artist created his best paintings during the [peak] of his career. (=Dịch: Họa sĩ đã sáng tác những bức tranh đẹp nhất của mình trong thời kỳ đỉnh cao của sự nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=peak&lang=en-GB&ipa=%2Fpik%2F","usAudio":"/ai_services/tts3/?q=peak&lang=en-US&ipa=%2Fpik%2F"},{"id":"lv_0_219","topic":"Daily Life and Social Activities","word":"permit","pos":"(v)","ipa":"/pɚˈmɪt/","defVi":"cho phép","defEn":"to allow something to happen or allow someone to do something","examples":["The museum does not [permit] visitors to take photos inside. (=Dịch: Bảo tàng không cho phép khách tham quan chụp ảnh bên trong.)","We will have a picnic tomorrow if the weather will [permit]. (=Dịch: Chúng tôi sẽ đi dã ngoại vào ngày mai nếu thời tiết cho phép.)","Her busy schedule did not [permit] her to attend the workshop. (=Dịch: Lịch trình bận rộn không cho phép cô ấy tham dự buổi hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=permit&lang=en-GB&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=permit&lang=en-US&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F"},{"id":"lv_0_220","topic":"Daily Life and Social Activities","word":"photography","pos":"(n)","ipa":"/fəˈtɑː.ɡrə.fi/","defVi":"nhiếp ảnh, nghề chụp ảnh","defEn":"the activity or job of taking photographs or filming","examples":["She took a course in digital [photography] to improve her camera skills. (=Dịch: Cô ấy đã tham gia một khóa học nhiếp ảnh kỹ thuật số để nâng cao kỹ năng chụp ảnh.)","Wildlife [photography] requires a great deal of patience and specialized equipment. (=Dịch: Nhiếp ảnh động vật hoang dã đòi hỏi rất nhiều sự kiên nhẫn và thiết bị chuyên dụng.)","His passion for landscape [photography] inspired him to travel around the world. (=Dịch: Niềm đam mê nhiếp ảnh phong cảnh đã thôi thúc anh ấy đi du lịch vòng quanh thế giới.)"],"ukAudio":"/ai_services/tts3/?q=photography&lang=en-GB&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=photography&lang=en-US&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_0_221","topic":"Daily Life and Social Activities","word":"picnic","pos":"(n)","ipa":"/ˈpɪk.nɪk/","defVi":"chuyến dã ngoại, bữa ăn ngoài trời","defEn":"an occasion when a packed meal is eaten outdoors","examples":["We decided to have a [picnic] by the lake on Sunday afternoon. (=Dịch: Chúng tôi quyết định tổ chức một buổi dã ngoại bên hồ vào chiều Chủ nhật.)","She packed sandwiches, fruit, and lemonade into the [picnic] basket. (=Dịch: Cô ấy xếp bánh mì kẹp, trái cây và nước chanh vào giỏ dã ngoại.)","Families often gather in the central park for an enjoyable weekend [picnic]. (=Dịch: Các gia đình thường tụ họp tại công viên trung tâm để có một buổi dã ngoại cuối tuần thú vị.)"],"ukAudio":"/ai_services/tts3/?q=picnic&lang=en-GB&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=picnic&lang=en-US&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F"},{"id":"lv_0_222","topic":"Daily Life and Social Activities","word":"pile","pos":"(n)","ipa":"/paɪl/","defVi":"chồng, đống","defEn":"a mass of things lying one on top of another","examples":["There is a tall [pile] of dirty dishes in the kitchen sink. (=Dịch: Có một chồng bát đĩa bẩn chất cao trong bồn rửa chén.)","He sorted through a [pile] of old documents looking for his passport. (=Dịch: Anh ấy đã lục tìm trong một đống tài liệu cũ để tìm hộ chiếu của mình.)","The gardener raked the dry leaves into a neat [pile]. (=Dịch: Người làm vườn đã cào lá khô lại thành một đống gọn gàng.)"],"ukAudio":"/ai_services/tts3/?q=pile&lang=en-GB&ipa=%2Fpa%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=pile&lang=en-US&ipa=%2Fpa%C9%AAl%2F"},{"id":"lv_0_223","topic":"Daily Life and Social Activities","word":"pleasure","pos":"(n)","ipa":"/ˈpleʒ.ɚ/","defVi":"niềm vui thích, sự hân hạnh","defEn":"a feeling of happy satisfaction and enjoyment","examples":["Reading historical novels gives her a great deal of [pleasure]. (=Dịch: Đọc tiểu thuyết lịch sử mang lại cho cô ấy rất nhiều niềm vui.)","It was a true [pleasure] to meet your family last night. (=Dịch: Thật là một niềm vui lớn khi được gặp gia đình bạn vào tối qua.)","He travels abroad for both business and [pleasure]. (=Dịch: Anh ấy đi nước ngoài cho cả mục đích công việc lẫn giải trí.)"],"ukAudio":"/ai_services/tts3/?q=pleasure&lang=en-GB&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=pleasure&lang=en-US&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F"},{"id":"lv_0_224","topic":"Daily Life and Social Activities","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, thận trọng","defEn":"wise, sensible, and showing good judgment in a particular situation","examples":["It was not considered [politic] to bring up the sensitive topic during the meeting. (=Dịch: Việc đề cập đến chủ đề nhạy cảm trong cuộc họp được cho là không khôn ngoan.)","He thought it [politic] to remain silent while his manager was speaking. (=Dịch: Anh ấy nghĩ rằng giữ im lặng trong khi người quản lý đang nói là điều khôn khéo.)","Adopting a calm tone was a [politic] move to prevent further argument. (=Dịch: Dùng giọng điệu bình tĩnh là một bước đi khôn khéo để ngăn chặn những tranh cãi tiếp theo.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_0_225","topic":"Daily Life and Social Activities","word":"portion","pos":"(n)","ipa":"/ˈpɔːr.ʃən/","defVi":"phần, khẩu phần","defEn":"a part of something larger, especially an amount of food served for one person","examples":["A large [portion] of the budget was allocated to scientific research. (=Dịch: Một phần lớn ngân sách đã được phân bổ cho nghiên cứu khoa học.)","The restaurant serves very generous [portions] of pasta. (=Dịch: Nhà hàng phục vụ các phần mì Ý rất đầy đặn.)","Only a small [portion] of the students passed the advanced test. (=Dịch: Chỉ một phần nhỏ học sinh vượt qua bài kiểm tra nâng cao.)"],"ukAudio":"/ai_services/tts3/?q=portion&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=portion&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F"},{"id":"lv_0_226","topic":"Daily Life and Social Activities","word":"postcode","pos":"(n)","ipa":"/ˈpoʊst.koʊd/","defVi":"mã bưu điện, mã bưu chính","defEn":"a group of letters and numbers added to a postal address to help sort mail","examples":["Please remember to write your [postcode] clearly on the envelope. (=Dịch: Xin hãy nhớ ghi mã bưu chính của bạn thật rõ ràng trên phong bì.)","I could not complete the checkout form without entering a valid [postcode]. (=Dịch: Tôi không thể hoàn tất biểu mẫu thanh toán nếu không nhập mã bưu chính hợp lệ.)","The courier used the [postcode] to locate our building quickly. (=Dịch: Người giao hàng đã sử dụng mã bưu chính để xác định vị trí tòa nhà của chúng tôi một cách nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=postcode&lang=en-GB&ipa=%2F%CB%88po%CA%8Ast.ko%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=postcode&lang=en-US&ipa=%2F%CB%88po%CA%8Ast.ko%CA%8Ad%2F"},{"id":"lv_0_227","topic":"Daily Life and Social Activities","word":"powder","pos":"(n)","ipa":"/ˈpaʊ.dər/","defVi":"bột, phấn","defEn":"a dry substance made of very fine, small particles","examples":["Mix the cocoa [powder] with warm milk until smooth. (=Dịch: Trộn bột ca cao với sữa ấm cho đến khi mịn.)","She applied a light layer of [powder] to her face. (=Dịch: Cô ấy thoa một lớp phấn nhẹ lên mặt.)","The medicine is available in both tablet and [powder] form. (=Dịch: Thuốc này có sẵn ở cả dạng viên nén và dạng bột.)"],"ukAudio":"/ai_services/tts3/?q=powder&lang=en-GB&ipa=%2F%CB%88pa%CA%8A.d%C9%99r%2F","usAudio":"/ai_services/tts3/?q=powder&lang=en-US&ipa=%2F%CB%88pa%CA%8A.d%C9%99r%2F"},{"id":"lv_0_228","topic":"Daily Life and Social Activities","word":"preferable","pos":"(adj)","ipa":"/ˈpref.ər.ə.bəl/","defVi":"thích hợp hơn, đáng chuộng hơn","defEn":"more suitable, desirable, or acceptable","examples":["Taking the train is [preferable] to driving in heavy traffic. (=Dịch: Đi tàu hỏa thích hợp hơn so với việc lái xe khi giao thông đông đúc.)","A quiet study environment is [preferable] for deep concentration. (=Dịch: Một môi trường học tập yên tĩnh sẽ tốt hơn cho việc tập trung sâu.)","Having some work experience is [preferable] but not essential for this job. (=Dịch: Có một chút kinh nghiệm làm việc là điều đáng mong muốn nhưng không bắt buộc đối với công việc này.)"],"ukAudio":"/ai_services/tts3/?q=preferable&lang=en-GB&ipa=%2F%CB%88pref.%C9%99r.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=preferable&lang=en-US&ipa=%2F%CB%88pref.%C9%99r.%C9%99.b%C9%99l%2F"},{"id":"lv_0_229","topic":"Daily Life and Social Activities","word":"preference","pos":"(n)","ipa":"/ˈpref.ər.əns/","defVi":"sở thích, sự ưa chuộng, sự ưu tiên","defEn":"a greater liking for one alternative over another","examples":["Do you have any dietary [preference], such as vegetarian food? (=Dịch: Bạn có yêu cầu ăn uống đặc biệt nào không, chẳng hạn như đồ ăn chay?)","Parents often have a strong [preference] for smaller class sizes. (=Dịch: Các bậc phụ huynh thường có xu hướng ưa chuộng các lớp học có quy mô nhỏ hơn.)","Candidates with previous teaching experience will be given [preference]. (=Dịch: Các ứng viên có kinh nghiệm giảng dạy trước đó sẽ được ưu tiên.)"],"ukAudio":"/ai_services/tts3/?q=preference&lang=en-GB&ipa=%2F%CB%88pref.%C9%99r.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=preference&lang=en-US&ipa=%2F%CB%88pref.%C9%99r.%C9%99ns%2F"},{"id":"lv_0_230","topic":"Daily Life and Social Activities","word":"preferred","pos":"(adj)","ipa":"/prɪˈfɜːrd/","defVi":"được ưa chuộng hơn, ưu tiên","defEn":"liked better or chosen over others","examples":["Online banking has become the [preferred] method of payment for many people. (=Dịch: Ngân hàng trực tuyến đã trở thành phương thức thanh toán được ưa chuộng của nhiều người.)","Please state your [preferred] date of arrival on the application form. (=Dịch: Vui lòng ghi rõ ngày đến mong muốn của bạn trên mẫu đơn đăng ký.)","Tea is his [preferred] morning beverage instead of coffee. (=Dịch: Trà là thức uống buổi sáng ưa thích của anh ấy thay vì cà phê.)"],"ukAudio":"/ai_services/tts3/?q=preferred&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88f%C9%9C%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=preferred&lang=en-US&ipa=%2Fpr%C9%AA%CB%88f%C9%9C%CB%90rd%2F"},{"id":"lv_0_231","topic":"Daily Life and Social Activities","word":"premier","pos":"(adj)","ipa":"/prɪˈmɪr/","defVi":"hàng đầu, quan trọng nhất","defEn":"best, most important, or first in position","examples":["The university is regarded as the country's [premier] research institution. (=Dịch: Trường đại học này được coi là viện nghiên cứu hàng đầu của đất nước.)","The hotel offers [premier] services to its VIP guests. (=Dịch: Khách sạn cung cấp các dịch vụ cao cấp nhất cho các khách hàng VIP.)","The city is hosting the [premier] cultural event of the year. (=Dịch: Thành phố đang đăng cai tổ chức sự kiện văn hóa hàng đầu trong năm.)"],"ukAudio":"/ai_services/tts3/?q=premier&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88m%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=premier&lang=en-US&ipa=%2Fpr%C9%AA%CB%88m%C9%AAr%2F"},{"id":"lv_0_232","topic":"Daily Life and Social Activities","word":"presume","pos":"(v)","ipa":"/prɪˈzuːm/","defVi":"cho là, coi như là, đoán chừng","defEn":"to believe something to be true based on probability rather than proof","examples":["I [presume] that you have already completed the reading assignment. (=Dịch: Tôi cho rằng bạn đã hoàn thành bài tập đọc rồi.)","In law, a person is [presumed] innocent until proven guilty. (=Dịch: Theo luật, một người được coi là vô tội cho đến khi bị chứng minh là có tội.)","Since he was absent, we [presumed] he was sick. (=Dịch: Vì anh ấy vắng mặt, chúng tôi đoán là anh ấy bị ốm.)"],"ukAudio":"/ai_services/tts3/?q=presume&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88zu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=presume&lang=en-US&ipa=%2Fpr%C9%AA%CB%88zu%CB%90m%2F"},{"id":"lv_0_233","topic":"Daily Life and Social Activities","word":"projector","pos":"(n)","ipa":"/prəˈdʒek.tər/","defVi":"máy chiếu","defEn":"a device that projects rays of light or images onto a screen","examples":["The teacher turned on the [projector] to display the slides. (=Dịch: Giáo viên đã bật máy chiếu để hiển thị các trang trình chiếu.)","We need a high-resolution [projector] for the conference room. (=Dịch: Chúng tôi cần một máy chiếu có độ phân giải cao cho phòng hội nghị.)","The presentation was delayed because the [projector] stopped working. (=Dịch: Buổi thuyết trình bị trì hoãn vì máy chiếu ngừng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=projector&lang=en-GB&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=projector&lang=en-US&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F"},{"id":"lv_0_234","topic":"Daily Life and Social Activities","word":"purchase","pos":"(v)","ipa":"/ˈpɝː.tʃəs/","defVi":"mua sắm, mua vào","defEn":"to buy something","examples":["You can [purchase] museum tickets online to avoid long queues. (=Dịch: Bạn có thể mua vé bảo tàng trực tuyến để tránh phải xếp hàng dài.)","She decided to [purchase] a new laptop for her university courses. (=Dịch: Cô ấy quyết định mua một chiếc máy tính xách tay mới cho các khóa học đại học của mình.)","The school plans to [purchase] new laboratory equipment next term. (=Dịch: Nhà trường dự định mua sắm các thiết bị phòng thí nghiệm mới vào học kỳ tới.)"],"ukAudio":"/ai_services/tts3/?q=purchase&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.t%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=purchase&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.t%CA%83%C9%99s%2F"},{"id":"lv_0_235","topic":"Daily Life and Social Activities","word":"qualified","pos":"(adj)","ipa":"/ˈkwɑː.lə.faɪd/","defVi":"đủ điều kiện, có đủ trình độ chuyên môn","defEn":"having the necessary skills, knowledge, or experience to do a particular job or activity","examples":["She is fully [qualified] to teach English to international students. (=Dịch: Cô ấy có đầy đủ trình độ chuyên môn để dạy tiếng Anh cho sinh viên quốc tế.)","Only [qualified] candidates will be invited for an interview. (=Dịch: Chỉ những ứng viên đủ điều kiện mới được mời tham gia phỏng vấn.)","He is well [qualified] for the position of project manager. (=Dịch: Anh ấy hoàn toàn đủ năng lực cho vị trí quản lý dự án.)"],"ukAudio":"/ai_services/tts3/?q=qualified&lang=en-GB&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=qualified&lang=en-US&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F"},{"id":"lv_0_236","topic":"Daily Life and Social Activities","word":"quiz","pos":"(n)","ipa":"/kwɪz/","defVi":"bài kiểm tra ngắn, câu đố","defEn":"a short or informal test of knowledge","examples":["We have a short vocabulary [quiz] at the beginning of each class. (=Dịch: Chúng tôi có một bài kiểm tra ngắn về từ vựng vào đầu mỗi buổi học.)","The team won first place in the pub [quiz] last night. (=Dịch: Đội đã giành giải nhất trong trò chơi đố vui tại quán rượu tối qua.)","She took an online [quiz] to determine her learning style. (=Dịch: Cô ấy đã làm một bài trắc nghiệm trực tuyến để xác định phong cách học tập của mình.)"],"ukAudio":"/ai_services/tts3/?q=quiz&lang=en-GB&ipa=%2Fkw%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=quiz&lang=en-US&ipa=%2Fkw%C9%AAz%2F"},{"id":"lv_0_237","topic":"Daily Life and Social Activities","word":"quote","pos":"(n)","ipa":"/kwoʊt/","defVi":"báo giá, lời trích dẫn","defEn":"a statement of how much a job or service will cost, or a repetition of someone's words","examples":["We asked several contractors for a [quote] before renovating the kitchen. (=Dịch: Chúng tôi đã xin bảng báo giá từ vài nhà thầu trước khi sửa sang lại nhà bếp.)","The article opened with a famous [quote] from Shakespeare. (=Dịch: Bài viết mở đầu bằng một câu trích dẫn nổi tiếng của Shakespeare.)","She requested a free [quote] for her car insurance policy. (=Dịch: Cô ấy đã yêu cầu một bảng báo giá miễn phí cho hợp đồng bảo hiểm xe hơi của mình.)"],"ukAudio":"/ai_services/tts3/?q=quote&lang=en-GB&ipa=%2Fkwo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=quote&lang=en-US&ipa=%2Fkwo%CA%8At%2F"},{"id":"lv_0_238","topic":"Daily Life and Social Activities","word":"radiator","pos":"(n)","ipa":"/ˈreɪ.di.eɪ.tər/","defVi":"bộ tản nhiệt, lò sưởi","defEn":"a device used for heating a room or for cooling an engine","examples":["He placed his wet gloves on the [radiator] to dry. (=Dịch: Anh ấy đặt đôi găng tay ướt lên bộ tản nhiệt để sấy khô.)","The car broke down because the [radiator] was leaking coolant. (=Dịch: Chiếc xe bị hỏng vì két làm mát bị rò rỉ dung dịch tản nhiệt.)","Make sure to bleed the [radiator] if the room feels cold. (=Dịch: Hãy nhớ xả khí lò sưởi nếu cảm thấy phòng bị lạnh.)"],"ukAudio":"/ai_services/tts3/?q=radiator&lang=en-GB&ipa=%2F%CB%88re%C9%AA.di.e%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=radiator&lang=en-US&ipa=%2F%CB%88re%C9%AA.di.e%C9%AA.t%C9%99r%2F"},{"id":"lv_0_239","topic":"Daily Life and Social Activities","word":"reasonable","pos":"(adj)","ipa":"/ˈriː.zən.ə.bəl/","defVi":"hợp lý, phải chăng","defEn":"fair, practical, and sensible; not too expensive","examples":["The hotel offers quality service at a very [reasonable] price. (=Dịch: Khách sạn cung cấp dịch vụ chất lượng với mức giá rất hợp lý.)","It is [reasonable] to assume that the project will take several months to finish. (=Dịch: Thật hợp lý khi cho rằng dự án sẽ mất vài tháng để hoàn thành.)","She made a [reasonable] suggestion that everyone quickly agreed with. (=Dịch: Cô ấy đã đưa ra một đề xuất hợp lý mà mọi người nhanh chóng đồng ý.)"],"ukAudio":"/ai_services/tts3/?q=reasonable&lang=en-GB&ipa=%2F%CB%88ri%CB%90.z%C9%99n.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=reasonable&lang=en-US&ipa=%2F%CB%88ri%CB%90.z%C9%99n.%C9%99.b%C9%99l%2F"},{"id":"lv_0_240","topic":"Daily Life and Social Activities","word":"reassure","pos":"(v)","ipa":"/ˌriː.əˈʃʊr/","defVi":"trấn an, làm yên lòng","defEn":"to say or do something to remove someone's doubts or fears","examples":["The doctor tried to [reassure] the worried parents about their child's recovery. (=Dịch: Bác sĩ đã cố gắng trấn an các bậc phụ huynh đang lo lắng về sự hồi phục của con họ.)","She called home to [reassure] her family that she had arrived safely. (=Dịch: Cô ấy gọi điện về nhà để trấn an gia đình rằng mình đã đến nơi an toàn.)","The manager spoke to the team to [reassure] them about job security. (=Dịch: Người quản lý đã nói chuyện với cả nhóm để trấn an họ về sự ổn định của công việc.)"],"ukAudio":"/ai_services/tts3/?q=reassure&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.%C9%99%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=reassure&lang=en-US&ipa=%2F%CB%8Cri%CB%90.%C9%99%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_0_241","topic":"Daily Life and Social Activities","word":"recreational","pos":"(adj)","ipa":"/ˌrek.riˈeɪ.ʃən.əl/","defVi":"thuộc về giải trí, tiêu khiển","defEn":"connected with ways of enjoying yourself when you are not working","examples":["The city has invested heavily in creating new [recreational] areas for families. (=Dịch: Thành phố đã đầu tư mạnh mẽ vào việc tạo ra các khu vực giải trí mới cho các gia đình.)","Cycling in the park is one of his favorite [recreational] activities. (=Dịch: Đạp xe trong công viên là một trong những hoạt động giải trí yêu thích của anh ấy.)","The local community center provides various [recreational] facilities for teenagers. (=Dịch: Trung tâm cộng đồng địa phương cung cấp nhiều cơ sở vật chất giải trí khác nhau cho thanh thiếu niên.)"],"ukAudio":"/ai_services/tts3/?q=recreational&lang=en-GB&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=recreational&lang=en-US&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_0_242","topic":"Daily Life and Social Activities","word":"register","pos":"(n)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"sổ đăng ký, sổ ghi danh","defEn":"an official list or book for keeping records","examples":["The teacher checked the attendance [register] at the start of the lesson. (=Dịch: Giáo viên đã kiểm tra sổ điểm danh vào đầu buổi học.)","Guests are required to sign the [register] upon arriving at the hotel. (=Dịch: Khách được yêu cầu ký vào sổ đăng ký khi đến khách sạn.)","The company keeps an updated [register] of all its shareholders. (=Dịch: Công ty lưu giữ một sổ danh sách cập nhật của tất cả các cổ đông.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_0_243","topic":"Daily Life and Social Activities","word":"relative","pos":"(n)","ipa":"/ˈrel.ə.t̬ɪv/","defVi":"người thân, họ hàng","defEn":"a member of your family","examples":["She went to spend the summer holiday with a close [relative] in Canada. (=Dịch: Cô ấy đã đến trải qua kỳ nghỉ hè với một người họ hàng thân thiết ở Canada.)","Almost every [relative] gathered together for the family reunion. (=Dịch: Hầu như mọi người họ hàng đều tụ họp lại trong buổi sum họp gia đình.)","He invited both friends and [relatives] to his graduation ceremony. (=Dịch: Anh ấy đã mời cả bạn bè và người thân đến dự lễ tốt nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=relative&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=relative&lang=en-US&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_0_244","topic":"Daily Life and Social Activities","word":"relay","pos":"(v)","ipa":"/ˈriː.leɪ/","defVi":"chuyển tiếp, truyền đạt lại","defEn":"to receive and pass on information, news, or a message to someone else","examples":["I will [relay] your message to the director as soon as he returns. (=Dịch: Tôi sẽ chuyển lời nhắn của bạn đến giám đốc ngay khi ông ấy quay lại.)","Satellites are used to [relay] television signals around the world. (=Dịch: Các vệ tinh được sử dụng để truyền phát tín hiệu truyền hình đi khắp thế giới.)","The assistant was asked to [relay] the meeting notes to the rest of the team. (=Dịch: Trợ lý được yêu cầu chuyển các ghi chép cuộc họp cho những người còn lại trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=relay&lang=en-GB&ipa=%2F%CB%88ri%CB%90.le%C9%AA%2F","usAudio":"/ai_services/tts3/?q=relay&lang=en-US&ipa=%2F%CB%88ri%CB%90.le%C9%AA%2F"},{"id":"lv_0_245","topic":"Daily Life and Social Activities","word":"remind","pos":"(v)","ipa":"/rɪˈmaɪnd/","defVi":"nhắc nhở","defEn":"to make someone remember somebody or something","examples":["Please [remind] me to submit the assignment before midnight. (=Dịch: Làm ơn nhắc tôi nộp bài tập trước nửa đêm nhé.)","His laugh always seems to [remind] me of his grandfather. (=Dịch: Điệu cười của anh ấy dường như luôn gợi cho tôi nhớ đến ông của anh ấy.)","The alarm on her phone was set to [remind] her of the doctor's appointment. (=Dịch: Chuông báo trên điện thoại của cô ấy được đặt để nhắc cô về cuộc hẹn với bác sĩ.)"],"ukAudio":"/ai_services/tts3/?q=remind&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=remind&lang=en-US&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F"},{"id":"lv_0_246","topic":"Daily Life and Social Activities","word":"rental","pos":"(adj)","ipa":"/ˈren.t̬əl/","defVi":"cho thuê, thuê","defEn":"relating to the act of paying money to use something temporarily","examples":["We picked up our [rental] car directly outside the airport terminal. (=Dịch: Chúng tôi đã nhận chiếc xe thuê ngay bên ngoài nhà ga sân bay.)","The rising prices in the [rental] market make it hard for students to find housing. (=Dịch: Giá cả leo thang trên thị trường cho thuê khiến sinh viên khó tìm được nhà ở.)","They decided to stay in a cozy [rental] cabin in the mountains. (=Dịch: Họ quyết định ở trong một căn cabin thuê ấm cúng trên núi.)"],"ukAudio":"/ai_services/tts3/?q=rental&lang=en-GB&ipa=%2F%CB%88ren.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rental&lang=en-US&ipa=%2F%CB%88ren.t%CC%AC%C9%99l%2F"},{"id":"lv_0_247","topic":"Daily Life and Social Activities","word":"representative","pos":"(n)","ipa":"/ˌrep.rɪˈzen.t̬ə.t̬ɪv/","defVi":"người đại diện","defEn":"a person who is chosen to speak or act on behalf of an organization or group","examples":["A company [representative] will meet you at the entrance to guide you. (=Dịch: Một đại diện của công ty sẽ đón bạn ở lối vào để hướng dẫn bạn.)","She was elected as the student [representative] on the university council. (=Dịch: Cô ấy được bầu làm đại diện sinh viên trong hội đồng trường đại học.)","Please contact our customer service [representative] if you have any questions. (=Dịch: Vui lòng liên hệ với đại diện dịch vụ khách hàng của chúng tôi nếu bạn có bất kỳ câu hỏi nào.)"],"ukAudio":"/ai_services/tts3/?q=representative&lang=en-GB&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=representative&lang=en-US&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_0_248","topic":"Daily Life and Social Activities","word":"reservation","pos":"(n)","ipa":"/ˌrez.ɚˈveɪ.ʃən/","defVi":"sự đặt chỗ trước, sự giữ chỗ","defEn":"an arrangement to have something, such as a table or a room, kept for your use","examples":["I would like to make a dinner [reservation] for four people at seven o'clock. (=Dịch: Tôi muốn đặt bàn ăn tối cho bốn người lúc bảy giờ.)","We could not find a table because we forgot to make a [reservation] in advance. (=Dịch: Chúng tôi không tìm được bàn vì đã quên đặt chỗ trước.)","The hotel sent an email to confirm our room [reservation] for next weekend. (=Dịch: Khách sạn đã gửi email xác nhận việc đặt phòng của chúng tôi cho cuối tuần tới.)"],"ukAudio":"/ai_services/tts3/?q=reservation&lang=en-GB&ipa=%2F%CB%8Crez.%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reservation&lang=en-US&ipa=%2F%CB%8Crez.%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_0_249","topic":"Daily Life and Social Activities","word":"reset","pos":"(v)","ipa":"/ˌriːˈsɛt/","defVi":"đặt lại, cài đặt lại","defEn":"to set something again or change it back to its original state","examples":["You need to [reset] your password after logging in for the first time. (=Dịch: Bạn cần đặt lại mật khẩu sau khi đăng nhập lần đầu tiên.)","If the router stops working, try to [reset] it by pressing the small button on the back. (=Dịch: Nếu bộ định tuyến ngừng hoạt động, hãy thử đặt lại bằng cách nhấn nút nhỏ ở phía sau.)","He decided to take a short vacation to [reset] his mind after months of hard work. (=Dịch: Anh ấy quyết định đi nghỉ ngắn ngày để làm mới lại tâm trí sau nhiều tháng làm việc chăm chỉ.)"],"ukAudio":"/ai_services/tts3/?q=reset&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=reset&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88s%C9%9Bt%2F"},{"id":"lv_0_250","topic":"Daily Life and Social Activities","word":"residential","pos":"(adj)","ipa":"/ˌrɛz.əˈdɛn.ʃəl/","defVi":"thuộc khu dân cư, dùng để ở","defEn":"relating to an area where people live rather than where businesses or factories are located","examples":["The city council plans to build a new park in the [residential] area. (=Dịch: Hội đồng thành phố có kế hoạch xây dựng một công viên mới trong khu dân cư.)","Strict speed limits are enforced on [residential] streets to protect children. (=Dịch: Các giới hạn tốc độ nghiêm ngặt được thực thi trên các con đường khu dân cư để bảo vệ trẻ em.)","The university provides [residential] accommodation for all first-year students. (=Dịch: Trường đại học cung cấp chỗ ở nội trú cho tất cả sinh viên năm nhất.)"],"ukAudio":"/ai_services/tts3/?q=residential&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bz.%C9%99%CB%88d%C9%9Bn.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=residential&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bz.%C9%99%CB%88d%C9%9Bn.%CA%83%C9%99l%2F"},{"id":"lv_0_251","topic":"Daily Life and Social Activities","word":"restricted","pos":"(adj)","ipa":"/rɪˈstrɪk.tɪd/","defVi":"bị hạn chế, giới hạn","defEn":"limited, controlled, or allowed only to certain people","examples":["Access to the server room is strictly [restricted] to authorized personnel only. (=Dịch: Quyền truy cập vào phòng máy chủ bị hạn chế nghiêm ngặt, chỉ dành riêng cho nhân viên được ủy quyền.)","She has to follow a [restricted] diet due to her food allergies. (=Dịch: Cô ấy phải tuân theo một chế độ ăn kiêng hạn chế do bị dị ứng thực phẩm.)","They were operating in a [restricted] space, which made the construction work difficult. (=Dịch: Họ phải làm việc trong một không gian hạn chế, điều này khiến công việc xây dựng gặp nhiều khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=restricted&lang=en-GB&ipa=%2Fr%C9%AA%CB%88str%C9%AAk.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=restricted&lang=en-US&ipa=%2Fr%C9%AA%CB%88str%C9%AAk.t%C9%AAd%2F"},{"id":"lv_0_252","topic":"Daily Life and Social Activities","word":"retire","pos":"(v)","ipa":"/rɪˈtaɪ.ɚ/","defVi":"nghỉ hưu, về hưu","defEn":"to stop working permanently, usually because of reaching a certain age","examples":["He plans to [retire] at the age of sixty-five and travel around the world. (=Dịch: Ông dự định nghỉ hưu ở tuổi sáu mươi lăm và đi du lịch vòng quanh thế giới.)","Many professional athletes [retire] in their early thirties due to physical injuries. (=Dịch: Nhiều vận động viên chuyên nghiệp giải nghệ ở độ tuổi đầu ba mươi do chấn thương thể chất.)","After teaching for forty years, Professor Davis decided it was time to [retire]. (=Dịch: Sau bốn mươi năm giảng dạy, Giáo sư Davis quyết định đã đến lúc phải nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retire&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=retire&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_0_253","topic":"Daily Life and Social Activities","word":"retirement","pos":"(n)","ipa":"/rɪˈtaɪ.ɚ.mənt/","defVi":"sự nghỉ hưu, thời kỳ nghỉ hưu","defEn":"the period in someone's life after they have stopped working, or the act of stopping work","examples":["She has been saving money for her [retirement] since she started her first job. (=Dịch: Cô ấy đã tiết kiệm tiền cho việc nghỉ hưu của mình kể từ khi bắt đầu công việc đầu tiên.)","His colleagues threw a big farewell party to celebrate his [retirement]. (=Dịch: Các đồng nghiệp của ông đã tổ chức một bữa tiệc chia tay lớn để chúc mừng ngày ông nghỉ hưu.)","Many people take up new hobbies such as gardening during [retirement]. (=Dịch: Nhiều người bắt đầu những sở thích mới như làm vườn trong thời gian nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retirement&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=retirement&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA.%C9%9A.m%C9%99nt%2F"},{"id":"lv_0_254","topic":"Daily Life and Social Activities","word":"rid","pos":"(adj)","ipa":"/rɪd/","defVi":"thoát khỏi, tống khứ được, giải thoát khỏi","defEn":"free from an unwanted person, thing, or situation (commonly used in 'get rid of' or 'be rid of')","examples":["We need to get [rid] of these old newspapers to clear some space. (=Dịch: Chúng ta cần loại bỏ những tờ báo cũ này để dọn chỗ trống.)","She was finally [rid] of her bad cold after taking the prescribed medicine. (=Dịch: Cô ấy cuối cùng cũng khỏi hẳn trận cảm lạnh nặng sau khi uống thuốc theo đơn.)","The government is introducing new policies to be [rid] of corruption in public services. (=Dịch: Chính phủ đang ban hành các chính sách mới để xóa bỏ nạn tham nhũng trong các dịch vụ công.)"],"ukAudio":"/ai_services/tts3/?q=rid&lang=en-GB&ipa=%2Fr%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rid&lang=en-US&ipa=%2Fr%C9%AAd%2F"},{"id":"lv_0_255","topic":"Daily Life and Social Activities","word":"robot","pos":"(n)","ipa":"/ˈroʊ.bɑːt/","defVi":"người máy, rô-bốt","defEn":"a machine that can perform complex tasks automatically or through programmed instructions","examples":["The factory uses an advanced [robot] to assemble car parts quickly and accurately. (=Dịch: Nhà máy sử dụng một robot tiên tiến để lắp ráp các bộ phận xe hơi một cách nhanh chóng và chính xác.)","Scientists are developing a humanoid [robot] capable of assisting elderly people at home. (=Dịch: Các nhà khoa học đang phát triển một robot hình người có khả năng hỗ trợ người cao tuổi tại nhà.)","A cleaning [robot] vacuumed the entire living room floor while we were away. (=Dịch: Một robot hút bụi đã dọn dẹp toàn bộ sàn phòng khách trong khi chúng tôi đi vắng.)"],"ukAudio":"/ai_services/tts3/?q=robot&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=robot&lang=en-US&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F"},{"id":"lv_0_256","topic":"Daily Life and Social Activities","word":"rope","pos":"(n)","ipa":"/roʊp/","defVi":"dây thừng, dây cáp","defEn":"a strong, thick cord made by twisting together strands of hemp, nylon, or other materials","examples":["The climber secured the heavy [rope] to the rock before descending. (=Dịch: Người leo núi đã buộc chặt sợi dây thừng nặng vào tảng đá trước khi xuống núi.)","They tied the boat to the dock with a thick [rope]. (=Dịch: Họ đã buộc con thuyền vào bến tàu bằng một sợi dây thừng dày.)","Skipping [rope] is an effective exercise to improve cardiovascular health. (=Dịch: Nhảy dây là một bài tập hiệu quả để cải thiện sức khỏe tim mạch.)"],"ukAudio":"/ai_services/tts3/?q=rope&lang=en-GB&ipa=%2Fro%CA%8Ap%2F","usAudio":"/ai_services/tts3/?q=rope&lang=en-US&ipa=%2Fro%CA%8Ap%2F"},{"id":"lv_0_257","topic":"Daily Life and Social Activities","word":"roughly","pos":"(adv)","ipa":"/ˈrʌf.li/","defVi":"xấp xỉ, khoảng chừng, đại khái","defEn":"approximately; not completely accurately or precisely","examples":["The journey from the airport to the city center takes [roughly] forty-five minutes. (=Dịch: Hành trình từ sân bay đến trung tâm thành phố mất khoảng bốn mươi lăm phút.)","He earns [roughly] two thousand dollars a month from his freelance design work. (=Dịch: Anh ấy kiếm được khoảng hai nghìn đô la mỗi tháng từ công việc thiết kế tự do của mình.)","The total cost of the project was [roughly] estimated before the final budget was approved. (=Dịch: Tổng chi phí của dự án đã được ước tính sơ bộ trước khi ngân sách cuối cùng được phê duyệt.)"],"ukAudio":"/ai_services/tts3/?q=roughly&lang=en-GB&ipa=%2F%CB%88r%CA%8Cf.li%2F","usAudio":"/ai_services/tts3/?q=roughly&lang=en-US&ipa=%2F%CB%88r%CA%8Cf.li%2F"},{"id":"lv_0_258","topic":"Daily Life and Social Activities","word":"rush","pos":"(n)","ipa":"/rʌʃ/","defVi":"sự vội vã, sự gấp rút; dòng người/xe đổ xô","defEn":"a situation in which you must hurry, or a sudden rapid movement","examples":["I am in a huge [rush] this morning because my alarm clock did not go off. (=Dịch: Sáng nay tôi đang rất vội vì đồng hồ báo thức không reo.)","Avoid traveling during the morning [rush] hour if you want to prevent delays. (=Dịch: Hãy tránh đi lại vào giờ cao điểm buổi sáng nếu bạn muốn tránh bị chậm trễ.)","There was an unexpected [rush] for concert tickets as soon as the website opened. (=Dịch: Đã có một làn sóng đổ xô mua vé hòa nhạc bất ngờ ngay khi trang web mở bán.)"],"ukAudio":"/ai_services/tts3/?q=rush&lang=en-GB&ipa=%2Fr%CA%8C%CA%83%2F","usAudio":"/ai_services/tts3/?q=rush&lang=en-US&ipa=%2Fr%CA%8C%CA%83%2F"},{"id":"lv_0_259","topic":"Daily Life and Social Activities","word":"rust","pos":"(v)","ipa":"/rʌst/","defVi":"bị gỉ, gỉ sét","defEn":"to become covered with a reddish-brown substance because of moisture and air","examples":["Metal tools will [rust] if you leave them outside in the rain. (=Dịch: Dụng cụ bằng kim loại sẽ bị rỉ sét nếu bạn để chúng ngoài trời mưa.)","The old iron gate began to [rust] after years of neglect. (=Dịch: Cánh cổng sắt cũ bắt đầu rỉ sét sau nhiều năm không được bảo dưỡng.)","Apply a protective coating to prevent the bicycle frame from [rusting]. (=Dịch: Hãy phủ một lớp bảo vệ để tránh cho khung xe đạp bị rỉ sét.)"],"ukAudio":"/ai_services/tts3/?q=rust&lang=en-GB&ipa=%2Fr%CA%8Cst%2F","usAudio":"/ai_services/tts3/?q=rust&lang=en-US&ipa=%2Fr%CA%8Cst%2F"},{"id":"lv_0_260","topic":"Daily Life and Social Activities","word":"sailor","pos":"(n)","ipa":"/ˈseɪ.lɚ/","defVi":"thủy thủ","defEn":"a person who works on a ship as a member of the crew","examples":["The experienced [sailor] steered the ship safely through the storm. (=Dịch: Người thủy thủ giàu kinh nghiệm đã điều khiển con tàu vượt qua cơn bão một cách an toàn.)","He spent five years working as a [sailor] on a cargo vessel. (=Dịch: Anh ấy đã dành năm năm làm thủy thủ trên một con tàu chở hàng.)","Many young [sailors] joined the navy to travel the world. (=Dịch: Nhiều thủy thủ trẻ đã gia nhập hải quân để được chu du khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=sailor&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sailor&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9A%2F"},{"id":"lv_0_261","topic":"Daily Life and Social Activities","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance made of very small pieces of crushed rock found on beaches and in deserts","examples":["Children love building castles out of wet [sand] on the beach. (=Dịch: Trẻ em rất thích xây lâu đài bằng cát ướt trên bãi biển.)","The strong wind blew fine [sand] across the desert road. (=Dịch: Cơn gió mạnh đã thổi cát mịn bay qua con đường trên sa mạc.)","We shook the [sand] out of our shoes before entering the hotel. (=Dịch: Chúng tôi đã giũ sạch cát khỏi giày trước khi bước vào khách sạn.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_0_262","topic":"Daily Life and Social Activities","word":"sandal","pos":"(n)","ipa":"/ˈsæn.dl/","defVi":"dép quai hậu, xăng-đan","defEn":"a light shoe consisting of a bottom sole held onto the foot by straps","examples":["She bought a new pair of leather [sandals] for her summer vacation. (=Dịch: Cô ấy đã mua một đôi dép xăng đan bằng da mới cho kỳ nghỉ hè của mình.)","Wearing [sandals] is ideal for walking along the sunny beach. (=Dịch: Đi dép xăng đan rất lý tưởng để dạo bước dọc bãi biển đầy nắng.)","He took off his [sandals] before entering the traditional Japanese house. (=Dịch: Anh ấy đã cởi dép xăng đan ra trước khi bước vào ngôi nhà truyền thống của Nhật Bản.)"],"ukAudio":"/ai_services/tts3/?q=sandal&lang=en-GB&ipa=%2F%CB%88s%C3%A6n.dl%2F","usAudio":"/ai_services/tts3/?q=sandal&lang=en-US&ipa=%2F%CB%88s%C3%A6n.dl%2F"},{"id":"lv_0_263","topic":"Daily Life and Social Activities","word":"satisfaction","pos":"(n)","ipa":"/ˌsæt̬.ɪsˈfæk.ʃən/","defVi":"sự hài lòng, sự thỏa mãn","defEn":"a pleasant feeling of fulfillment when your desires or needs are met","examples":["Customer [satisfaction] is the top priority for our support team. (=Dịch: Sự hài lòng của khách hàng là ưu tiên hàng đầu của đội ngũ hỗ trợ chúng tôi.)","She gained deep personal [satisfaction] from volunteering at the shelter. (=Dịch: Cô ấy cảm nhận được sự thỏa nguyện sâu sắc khi làm tình nguyện viên tại khu tạm trú.)","We asked guests to complete a short [satisfaction] survey after their stay. (=Dịch: Chúng tôi đã nhờ du khách hoàn thành một khảo sát ngắn về mức độ hài lòng sau kỳ lưu trú của họ.)"],"ukAudio":"/ai_services/tts3/?q=satisfaction&lang=en-GB&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%AAs%CB%88f%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=satisfaction&lang=en-US&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%AAs%CB%88f%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_0_264","topic":"Daily Life and Social Activities","word":"satisfied","pos":"(adj)","ipa":"/ˈsæt̬.əs.faɪd/","defVi":"hài lòng, thỏa mãn","defEn":"pleased because you have got what you wanted or needed","examples":["The manager was highly [satisfied] with the team's project results. (=Dịch: Người quản lý rất hài lòng với kết quả dự án của cả nhóm.)","Customer service aims to ensure every client leaves [satisfied]. (=Dịch: Dịch vụ khách hàng hướng tới mục tiêu đảm bảo mọi khách hàng đều rời đi trong sự hài lòng.)","She felt [satisfied] after finishing a delicious home-cooked meal. (=Dịch: Cô ấy cảm thấy thỏa mãn sau khi thưởng thức xong một bữa cơm nhà nấu ngon miệng.)"],"ukAudio":"/ai_services/tts3/?q=satisfied&lang=en-GB&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=satisfied&lang=en-US&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99s.fa%C9%AAd%2F"},{"id":"lv_0_265","topic":"Daily Life and Social Activities","word":"scan","pos":"(v)","ipa":"/skæn/","defVi":"quét, rà soát (dữ liệu hoặc tài liệu)","defEn":"to look at all parts of something carefully, or to pass light over something to create a digital image","examples":["Please [scan] the document and email the PDF file to me. (=Dịch: Vui lòng quét tài liệu và gửi tệp PDF qua email cho tôi.)","The security guard [scanned] the crowd to spot any suspicious activity. (=Dịch: Nhân viên an ninh đã quan sát kỹ đám đông để phát hiện bất kỳ hoạt động đáng ngờ nào.)","You can [scan] the QR code with your smartphone to view the menu. (=Dịch: Bạn có thể quét mã QR bằng điện thoại thông minh để xem thực đơn.)"],"ukAudio":"/ai_services/tts3/?q=scan&lang=en-GB&ipa=%2Fsk%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=scan&lang=en-US&ipa=%2Fsk%C3%A6n%2F"},{"id":"lv_0_266","topic":"Daily Life and Social Activities","word":"scenery","pos":"(n)","ipa":"/ˈsiː.nɚ.i/","defVi":"phong cảnh, cảnh quan thiên nhiên","defEn":"the natural features of a landscape, such as mountains, forests, or rivers","examples":["We stopped our car at the mountain peak to admire the stunning [scenery]. (=Dịch: Chúng tôi dừng xe tại đỉnh núi để chiêm ngưỡng phong cảnh tuyệt đẹp.)","The train journey offers picturesque [scenery] throughout the countryside. (=Dịch: Chuyến đi bằng tàu hỏa mang đến khung cảnh miền quê đẹp như tranh vẽ.)","Tourists love visiting this national park because of its untouched [scenery]. (=Dịch: Khách du lịch thích ghé thăm công viên quốc gia này nhờ phong cảnh hoang sơ của nó.)"],"ukAudio":"/ai_services/tts3/?q=scenery&lang=en-GB&ipa=%2F%CB%88si%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=scenery&lang=en-US&ipa=%2F%CB%88si%CB%90.n%C9%9A.i%2F"},{"id":"lv_0_267","topic":"Daily Life and Social Activities","word":"seafood","pos":"(n)","ipa":"/ˈsiː.fuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, especially fish and shellfish","examples":["This coastal city is famous for its fresh and delicious [seafood]. (=Dịch: Thành phố ven biển này nổi tiếng với nguồn hải sản tươi ngon.)","He cannot eat [seafood] because he is allergic to shrimp and crab. (=Dịch: Anh ấy không thể ăn hải sản vì bị dị ứng với tôm và cua.)","We ordered a large platter of grilled [seafood] at the restaurant. (=Dịch: Chúng tôi đã gọi một đĩa hải sản nướng lớn tại nhà hàng.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F"},{"id":"lv_0_268","topic":"Daily Life and Social Activities","word":"seasonal","pos":"(adj)","ipa":"/ˈsiː.zən.əl/","defVi":"theo mùa, có tính thời vụ","defEn":"happening only during a particular season of the year","examples":["Eating [seasonal] fruit is often cheaper and better for the environment. (=Dịch: Ăn trái cây theo mùa thường rẻ hơn và tốt hơn cho môi trường.)","The hotel hires extra [seasonal] workers during the summer peak. (=Dịch: Khách sạn thuê thêm lao động thời vụ trong mùa hè cao điểm.)","Many people suffer from [seasonal] allergies when flowers bloom in spring. (=Dịch: Nhiều người bị dị ứng thời tiết theo mùa khi hoa nở vào mùa xuân.)"],"ukAudio":"/ai_services/tts3/?q=seasonal&lang=en-GB&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=seasonal&lang=en-US&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99l%2F"},{"id":"lv_0_269","topic":"Daily Life and Social Activities","word":"seating","pos":"(n)","ipa":"/ˈsiː.t̬ɪŋ/","defVi":"chỗ ngồi, sự sắp xếp chỗ ngồi","defEn":"the seats provided in a particular place, or the arrangement of seats","examples":["The new stadium provides comfortable [seating] for over fifty thousand fans. (=Dịch: Sân vận động mới có chỗ ngồi thoải mái cho hơn năm mươi nghìn người hâm mộ.)","Please check the [seating] chart to find your assigned table. (=Dịch: Vui lòng kiểm tra sơ đồ chỗ ngồi để tìm đúng bàn đã được chỉ định của bạn.)","The cafe has both indoor and outdoor [seating] areas for customers. (=Dịch: Quán cà phê có cả khu vực chỗ ngồi trong nhà và ngoài trời cho khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=seating&lang=en-GB&ipa=%2F%CB%88si%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=seating&lang=en-US&ipa=%2F%CB%88si%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_0_270","topic":"Daily Life and Social Activities","word":"seaweed","pos":"(n)","ipa":"/ˈsiː.wiːd/","defVi":"rong biển, tảo biển","defEn":"a plant that grows in the sea or on rocks at the edge of the sea","examples":["The beach was covered with dried [seaweed] after the storm. (=Dịch: Bãi biển phủ đầy [rong biển] khô sau cơn bão.)","Many Asian cuisines use [seaweed] as a nutritious ingredient in soups and salads. (=Dịch: Nhiều nền ẩm thực châu Á sử dụng [rong biển] như một nguyên liệu bổ dưỡng trong các món súp và salad.)","Scientists are exploring how [seaweed] can be used as an eco-friendly biofuel. (=Dịch: Các nhà khoa học đang nghiên cứu cách [rong biển] có thể được sử dụng làm nhiên liệu sinh học thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=seaweed&lang=en-GB&ipa=%2F%CB%88si%CB%90.wi%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seaweed&lang=en-US&ipa=%2F%CB%88si%CB%90.wi%CB%90d%2F"},{"id":"lv_0_271","topic":"Daily Life and Social Activities","word":"secondary","pos":"(adj)","ipa":"/ˈsek.ən.der.i/","defVi":"thứ yếu, phụ","defEn":"less important than something else; coming after what is primary","examples":["Cost is a [secondary] consideration compared to passenger safety. (=Dịch: Chi phí là một yếu tố [phụ] cần cân nhắc so với sự an toàn của hành khách.)","The medication was effective, but it caused some minor [secondary] effects. (=Dịch: Thuốc có hiệu quả, nhưng nó gây ra một số tác dụng [phụ] nhỏ.)","His main goal was to gain experience, while earning money was only a [secondary] motive. (=Dịch: Mục tiêu chính của anh ấy là tích lũy kinh nghiệm, trong khi kiếm tiền chỉ là động cơ [thứ yếu].)"],"ukAudio":"/ai_services/tts3/?q=secondary&lang=en-GB&ipa=%2F%CB%88sek.%C9%99n.der.i%2F","usAudio":"/ai_services/tts3/?q=secondary&lang=en-US&ipa=%2F%CB%88sek.%C9%99n.der.i%2F"},{"id":"lv_0_272","topic":"Daily Life and Social Activities","word":"separately","pos":"(adv)","ipa":"/ˈsep.rət.li/","defVi":"riêng rẽ, tách biệt, riêng biệt","defEn":"as a separate unit; not together with other people or things","examples":["The two topics will be discussed [separately] during the seminar. (=Dịch: Hai chủ đề sẽ được thảo luận [riêng biệt] trong buổi hội thảo.)","Please pack the fragile glassware [separately] from the heavy books. (=Dịch: Vui lòng đóng gói đồ thủy tinh dễ vỡ [riêng biệt] với những cuốn sách nặng.)","Although they work at the same company, they travel to the office [separately]. (=Dịch: Mặc dù làm việc cùng một công ty, họ đi đến văn phòng [riêng lẻ].)"],"ukAudio":"/ai_services/tts3/?q=separately&lang=en-GB&ipa=%2F%CB%88sep.r%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=separately&lang=en-US&ipa=%2F%CB%88sep.r%C9%99t.li%2F"},{"id":"lv_0_273","topic":"Daily Life and Social Activities","word":"seventh","pos":"(adj)","ipa":"/ˈsev.ənθ/","defVi":"thứ bảy","defEn":"constituting number seven in a sequence","examples":["She celebrated her [seventh] birthday with a small family party. (=Dịch: Cô bé đã tổ chức sinh nhật [thứ bảy] của mình bằng một bữa tiệc gia đình nhỏ.)","He lives on the [seventh] floor of a modern apartment building. (=Dịch: Anh ấy sống ở tầng [bảy] của một tòa nhà chung cư hiện đại.)","This marks the [seventh] time the team has won the national championship. (=Dịch: Điều này đánh dấu lần [thứ bảy] đội tuyển giành chức vô địch quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=seventh&lang=en-GB&ipa=%2F%CB%88sev.%C9%99n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=seventh&lang=en-US&ipa=%2F%CB%88sev.%C9%99n%CE%B8%2F"},{"id":"lv_0_274","topic":"Daily Life and Social Activities","word":"shipping","pos":"(n)","ipa":"/ˈʃɪp.ɪŋ/","defVi":"việc vận chuyển hàng hóa, giao hàng","defEn":"the act or business of transporting goods from one place to another","examples":["The company offers free [shipping] on all orders over fifty dollars. (=Dịch: Công ty cung cấp dịch vụ [vận chuyển] miễn phí cho tất cả các đơn hàng trên 50 đô la.)","Severe weather conditions caused major delays in international [shipping]. (=Dịch: Điều kiện thời tiết khắc nghiệt đã gây ra sự chậm trễ lớn trong hoạt động [vận chuyển] quốc tế.)","The city's port is a vital hub for global maritime [shipping]. (=Dịch: Cảng của thành phố là một trung tâm quan trọng cho hoạt động [vận tải biển] toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=shipping&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=shipping&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F"},{"id":"lv_0_275","topic":"Daily Life and Social Activities","word":"shore","pos":"(n)","ipa":"/ʃɔːr/","defVi":"bờ biển, bờ hồ","defEn":"the land along the edge of a sea, lake, or wide river","examples":["They took a peaceful walk along the [shore] at sunset. (=Dịch: Họ đã đi dạo yên bình dọc theo [bờ biển] lúc hoàng hôn.)","The boat drifted away from the [shore] into deeper water. (=Dịch: Chiếc thuyền trôi dạt ra xa khỏi [bờ] vào vùng nước sâu hơn.)","Many rare seabirds build their nests along the rocky [shore]. (=Dịch: Nhiều loài chim biển quý hiếm xây tổ dọc theo [bờ] đá.)"],"ukAudio":"/ai_services/tts3/?q=shore&lang=en-GB&ipa=%2F%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=shore&lang=en-US&ipa=%2F%CA%83%C9%94%CB%90r%2F"},{"id":"lv_0_276","topic":"Daily Life and Social Activities","word":"shuttle","pos":"(n)","ipa":"/ˈʃʌt̬.əl/","defVi":"xe buýt/tàu trung chuyển tuyến ngắn","defEn":"a vehicle that travels regularly between two places","examples":["A complimentary [shuttle] runs between the hotel and the airport every thirty minutes. (=Dịch: Một chuyến [xe đưa đón] miễn phí chạy giữa khách sạn và sân bay cứ ba mươi phút một chuyến.)","We took the campus [shuttle] to get to the science building on time. (=Dịch: Chúng tôi đã đi [xe đưa đón] của khuôn viên trường để đến tòa nhà khoa học đúng giờ.)","The city introduced an electric [shuttle] to reduce traffic in the downtown area. (=Dịch: Thành phố đã giới thiệu một tuyến [xe buýt đưa đón] chạy bằng điện để giảm bớt lưu lượng giao thông ở khu vực trung tâm thành phố.)"],"ukAudio":"/ai_services/tts3/?q=shuttle&lang=en-GB&ipa=%2F%CB%88%CA%83%CA%8Ct%CC%AC.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=shuttle&lang=en-US&ipa=%2F%CB%88%CA%83%CA%8Ct%CC%AC.%C9%99l%2F"},{"id":"lv_0_277","topic":"Daily Life and Social Activities","word":"sighted","pos":"(adj)","ipa":"/ˈsaɪ.t̬ɪd/","defVi":"sáng mắt, có thị lực","defEn":"having the ability to see; not blind","examples":["The museum offers guided tours tailored for both blind and [sighted] visitors. (=Dịch: Bảo tàng cung cấp các chuyến tham quan có hướng dẫn viên được thiết kế riêng cho cả khách khiếm thị và khách [sáng mắt].)","A [sighted] volunteer assisted the visually impaired athlete during the race. (=Dịch: Một tình nguyện viên [sáng mắt] đã hỗ trợ vận động viên khiếm thị trong suốt cuộc đua.)","Software designers must consider how [sighted] users interact differently with screen layouts. (=Dịch: Các nhà thiết kế phần mềm phải xem xét cách người dùng [sáng mắt] tương tác khác nhau với bố cục màn hình.)"],"ukAudio":"/ai_services/tts3/?q=sighted&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=sighted&lang=en-US&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AAd%2F"},{"id":"lv_0_278","topic":"Daily Life and Social Activities","word":"smoothly","pos":"(adv)","ipa":"/ˈsmuːð.li/","defVi":"một cách trôi chảy, suôn sẻ, êm ả","defEn":"without any sudden changes, interruption, or difficulty","examples":["The transition to the new software system went very [smoothly]. (=Dịch: Quá trình chuyển đổi sang hệ thống phần mềm mới diễn ra rất [suôn sẻ].)","The train accelerated [smoothly] as it departed from the station. (=Dịch: Đoàn tàu tăng tốc [êm ả] khi rời khỏi nhà ga.)","If everything runs [smoothly], the renovation project will be finished by Friday. (=Dịch: Nếu mọi việc diễn ra [thuận lợi], dự án cải tạo sẽ hoàn thành trước thứ Sáu.)"],"ukAudio":"/ai_services/tts3/?q=smoothly&lang=en-GB&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F","usAudio":"/ai_services/tts3/?q=smoothly&lang=en-US&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F"},{"id":"lv_0_279","topic":"Daily Life and Social Activities","word":"socialise","pos":"(v)","ipa":"/ˈsoʊ.ʃə.laɪz/","defVi":"giao lưu, hòa nhập xã hội, kết bạn","defEn":"to spend time with other people for pleasure in a friendly way","examples":["University provides plenty of opportunities to [socialise] with people from diverse backgrounds. (=Dịch: Trường đại học mang lại nhiều cơ hội để [giao lưu] với những người đến từ các nền văn hóa khác nhau.)","He prefers to stay home on weekends rather than [socialise] with large groups. (=Dịch: Anh ấy thích ở nhà vào cuối tuần hơn là [giao lưu] với những nhóm đông người.)","Joining a sports club is a great way for newcomers to [socialise] and make friends. (=Dịch: Tham gia một câu lạc bộ thể thao là một cách tuyệt vời để những người mới đến có thể [giao lưu] và kết bạn.)"],"ukAudio":"/ai_services/tts3/?q=socialise&lang=en-GB&ipa=%2F%CB%88so%CA%8A.%CA%83%C9%99.la%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=socialise&lang=en-US&ipa=%2F%CB%88so%CA%8A.%CA%83%C9%99.la%C9%AAz%2F"},{"id":"lv_0_280","topic":"Daily Life and Social Activities","word":"spa","pos":"(n)","ipa":"/spɑː/","defVi":"khu nghỉ dưỡng suối khoáng, trung tâm chăm sóc sức khỏe và làm đẹp (spa)","defEn":"a place where people go to relax, improve their health, or receive beauty treatments","examples":["She spent the entire weekend relaxing at a luxury [spa]. (=Dịch: Cô ấy đã dành trọn cả cuối tuần để thư giãn tại một khu spa sang trọng.)","The hotel features a heated indoor pool and a modern [spa] center. (=Dịch: Khách sạn có hồ bơi nước nóng trong nhà và một trung tâm spa hiện đại.)","Many people visit this town for its natural [spa] waters. (=Dịch: Nhiều người ghé thăm thị trấn này vì nguồn nước khoáng tự nhiên của nó.)"],"ukAudio":"/ai_services/tts3/?q=spa&lang=en-GB&ipa=%2Fsp%C9%91%CB%90%2F","usAudio":"/ai_services/tts3/?q=spa&lang=en-US&ipa=%2Fsp%C9%91%CB%90%2F"},{"id":"lv_0_281","topic":"Daily Life and Social Activities","word":"spain","pos":"(n)","ipa":"/speɪn/","defVi":"nước Tây Ban Nha","defEn":"a country in southwestern Europe on the Iberian Peninsula","examples":["They are planning a two-week holiday in [Spain] this summer. (=Dịch: Họ đang lên kế hoạch cho một kỳ nghỉ kéo dài hai tuần tại Tây Ban Nha vào mùa hè này.)","[Spain] is famous for its rich history, delicious food, and sunny beaches. (=Dịch: Tây Ban Nha nổi tiếng với lịch sử phong phú, ẩm thực thơm ngon và những bãi biển đầy nắng.)","Many international students choose to study abroad in [Spain]. (=Dịch: Nhiều du học sinh quốc tế chọn đi du học ở Tây Ban Nha.)"],"ukAudio":"/ai_services/tts3/?q=spain&lang=en-GB&ipa=%2Fspe%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spain&lang=en-US&ipa=%2Fspe%C9%AAn%2F"},{"id":"lv_0_282","topic":"Daily Life and Social Activities","word":"spanish","pos":"(adj)","ipa":"/ˈspæn.ɪʃ/","defVi":"(thuộc) Tây Ban Nha, tiếng Tây Ban Nha","defEn":"connected with Spain, its people, or its language","examples":["She enjoys listening to traditional [Spanish] guitar music. (=Dịch: Cô ấy thích nghe nhạc guitar truyền thống của Tây Ban Nha.)","Tapas is a widely known [Spanish] style of serving small savory dishes. (=Dịch: Tapas là một phong cách phục vụ các món mặn nhỏ nổi tiếng rộng rãi của Tây Ban Nha.)","He is currently enrolled in a beginner [Spanish] language course. (=Dịch: Anh ấy hiện đang theo học một khóa học tiếng Tây Ban Nha dành cho người mới bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=spanish&lang=en-GB&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=spanish&lang=en-US&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F"},{"id":"lv_0_283","topic":"Daily Life and Social Activities","word":"spare","pos":"(adj)","ipa":"/sper/","defVi":"dự phòng, thừa, rảnh rỗi","defEn":"kept in addition to what is normally needed, available for use if needed","examples":["Always keep a [spare] key in case you lock yourself out. (=Dịch: Hãy luôn giữ một chiếc chìa khóa dự phòng phòng trường hợp bạn tự nhốt mình ở bên ngoài.)","He likes to read historical novels in his [spare] time. (=Dịch: Anh ấy thích đọc tiểu thuyết lịch sử vào thời gian rảnh rỗi.)","We have a [spare] bedroom upstairs for visiting guests. (=Dịch: Chúng tôi có một phòng ngủ dự phòng ở tầng trên dành cho khách đến thăm.)"],"ukAudio":"/ai_services/tts3/?q=spare&lang=en-GB&ipa=%2Fsper%2F","usAudio":"/ai_services/tts3/?q=spare&lang=en-US&ipa=%2Fsper%2F"},{"id":"lv_0_284","topic":"Daily Life and Social Activities","word":"spectacular","pos":"(adj)","ipa":"/spekˈtæk.jə.lɚ/","defVi":"ngoạn mục, hùng vĩ, đẹp mắt","defEn":"very impressive, beautiful, or striking to see","examples":["The mountaintop offers a [spectacular] view of the entire valley. (=Dịch: Đỉnh núi mang lại tầm nhìn ngoạn mục ra toàn bộ thung lũng.)","The opening ceremony ended with a [spectacular] fireworks display. (=Dịch: Lễ khai mạc đã kết thúc bằng một màn trình diễn pháo hoa ngoạn mục.)","The team achieved a [spectacular] victory in the final minutes of the match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_0_285","topic":"Daily Life and Social Activities","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị, hương liệu","defEn":"a substance made from plants used to give special flavor and aroma to food","examples":["Cinnamon is a popular [spice] used in both sweet and savory dishes. (=Dịch: Quế là một loại gia vị phổ biến được sử dụng trong cả các món ngọt lẫn món mặn.)","The chef added a pinch of exotic [spice] to enhance the flavor of the soup. (=Dịch: Đầu bếp đã thêm một nhúm gia vị ngoại lai để làm tăng hương vị của món súp.)","The historic trade of silk and [spice] connected Asia with Europe. (=Dịch: Con đường thương mại tơ lụa và gia vị trong lịch sử đã kết nối châu Á với châu Âu.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_0_286","topic":"Daily Life and Social Activities","word":"split","pos":"(v)","ipa":"/splɪt/","defVi":"chia ra, tách rời, phân chia","defEn":"to divide or break into two or more parts","examples":["The teacher asked the students to [split] into small discussion groups. (=Dịch: Giáo viên đã yêu cầu học sinh chia thành các nhóm thảo luận nhỏ.)","They decided to [split] the dinner bill evenly between them. (=Dịch: Họ quyết định chia đều hóa đơn bữa tối cho nhau.)","A deep disagreement threatened to [split] the political party apart. (=Dịch: Một sự bất đồng sâu sắc đã đe dọa chia rẽ đảng chính trị này.)"],"ukAudio":"/ai_services/tts3/?q=split&lang=en-GB&ipa=%2Fspl%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=split&lang=en-US&ipa=%2Fspl%C9%AAt%2F"},{"id":"lv_0_287","topic":"Daily Life and Social Activities","word":"sponsor","pos":"(v)","ipa":"/ˈspɑːn.sɚ/","defVi":"tài trợ, bảo trợ","defEn":"to support an event, person, or organization financially, often for advertising","examples":["Several local businesses agreed to [sponsor] the charity marathon. (=Dịch: Một số doanh nghiệp địa phương đã đồng ý tài trợ cho cuộc thi chạy marathon từ thiện.)","The tech company will [sponsor] the annual scientific conference. (=Dịch: Công ty công nghệ sẽ tài trợ cho hội nghị khoa học thường niên.)","Her company offered to [sponsor] her postgraduate degree in business. (=Dịch: Công ty của cô ấy đã đề nghị tài trợ cho bằng sau đại học về kinh doanh của cô.)"],"ukAudio":"/ai_services/tts3/?q=sponsor&lang=en-GB&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sponsor&lang=en-US&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A%2F"},{"id":"lv_0_288","topic":"Daily Life and Social Activities","word":"sponsorship","pos":"(n)","ipa":"/ˈspɑːn.sɚ.ʃɪp/","defVi":"sự tài trợ, tiền tài trợ","defEn":"financial support given by an organization or person for an activity or event","examples":["The sports event could not take place without corporate [sponsorship]. (=Dịch: Sự kiện thể thao không thể diễn ra nếu không có sự tài trợ của doanh nghiệp.)","The athlete signed a lucrative [sponsorship] deal with a major sportswear brand. (=Dịch: Vận động viên này đã ký một hợp đồng tài trợ béo bở với một thương hiệu đồ thể thao lớn.)","The exhibition relies heavily on government [sponsorship] and private donations. (=Dịch: Triển lãm phụ thuộc rất nhiều vào sự tài trợ của chính phủ và các khoản quyên góp tư nhân.)"],"ukAudio":"/ai_services/tts3/?q=sponsorship&lang=en-GB&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=sponsorship&lang=en-US&ipa=%2F%CB%88sp%C9%91%CB%90n.s%C9%9A.%CA%83%C9%AAp%2F"},{"id":"lv_0_289","topic":"Daily Life and Social Activities","word":"steep","pos":"(adj)","ipa":"/stiːp/","defVi":"dốc, đứng; (giá cả) tăng vọt","defEn":"rising or falling sharply, not gradually","examples":["It was difficult to climb the [steep] hill in the hot weather. (=Dịch: Thật khó để leo lên ngọn đồi dốc đứng trong thời tiết nóng bức.)","The company faced a [steep] decline in sales during the crisis. (=Dịch: Công ty phải đối mặt với sự sụt giảm mạnh về doanh số trong suốt cuộc khủng hoảng.)","Consumers complained about the [steep] increase in electricity prices. (=Dịch: Người tiêu dùng đã phàn nàn về mức tăng quá cao của giá điện.)"],"ukAudio":"/ai_services/tts3/?q=steep&lang=en-GB&ipa=%2Fsti%CB%90p%2F","usAudio":"/ai_services/tts3/?q=steep&lang=en-US&ipa=%2Fsti%CB%90p%2F"},{"id":"lv_0_290","topic":"Daily Life and Social Activities","word":"stove","pos":"(n)","ipa":"/stoʊv/","defVi":"bếp nấu (thường có lò nướng đi kèm)","defEn":"a large piece of kitchen equipment used for cooking food, with burners on top and an oven underneath","examples":["She placed a kettle of water on the [stove] to make tea. (=Dịch: Cô ấy đặt một ấm nước lên bếp để pha trà.)","Don't forget to turn off the [stove] before leaving the kitchen. (=Dịch: Đừng quên tắt bếp trước khi rời khỏi nhà bếp.)","They bought a modern gas [stove] for their newly renovated apartment. (=Dịch: Họ đã mua một chiếc bếp gas hiện đại cho căn hộ mới cải tạo của mình.)"],"ukAudio":"/ai_services/tts3/?q=stove&lang=en-GB&ipa=%2Fsto%CA%8Av%2F","usAudio":"/ai_services/tts3/?q=stove&lang=en-US&ipa=%2Fsto%CA%8Av%2F"},{"id":"lv_0_291","topic":"Daily Life and Social Activities","word":"straightaway","pos":"(adv)","ipa":"/ˌstreɪt.əˈweɪ/","defVi":"ngay lập tức, không chậm trễ","defEn":"without delay; immediately","examples":["When the alarm sounded, the students evacuated the building [straightaway]. (=Dịch: Khi chuông báo động vang lên, các học sinh đã sơ tán khỏi tòa nhà ngay lập tức.)","I knew [straightaway] that something was wrong with the computer. (=Dịch: Tôi nhận ra ngay lập tức rằng có điều gì đó không ổn với chiếc máy tính.)","If you feel unwell, you should see a doctor [straightaway]. (=Dịch: Nếu bạn cảm thấy không khỏe, bạn nên đi khám bác sĩ ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=straightaway&lang=en-GB&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=straightaway&lang=en-US&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F"},{"id":"lv_0_292","topic":"Daily Life and Social Activities","word":"strength","pos":"(n)","ipa":"/strɛŋkθ/","defVi":"sức mạnh, thể lực, độ bền","defEn":"the state or quality of being physically strong, powerful, or durable","examples":["He exercises every morning to build his muscle [strength]. (=Dịch: Anh ấy tập thể dục mỗi sáng để tăng cường sức mạnh cơ bắp.)","Her inner [strength] helped her overcome the difficult times. (=Dịch: Sức mạnh nội tâm đã giúp cô ấy vượt qua những khoảng thời gian khó khăn.)","Engineers tested the [strength] of the bridge before opening it to traffic. (=Dịch: Các kỹ sư đã kiểm tra độ chịu lực của cây cầu trước khi cho phép lưu thông.)"],"ukAudio":"/ai_services/tts3/?q=strength&lang=en-GB&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F","usAudio":"/ai_services/tts3/?q=strength&lang=en-US&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F"},{"id":"lv_0_293","topic":"Daily Life and Social Activities","word":"strip","pos":"(v)","ipa":"/strɪp/","defVi":"lột bỏ, cởi bỏ, tước đi","defEn":"to remove a layer, covering, or clothes from someone or something","examples":["The painters will [strip] the old wallpaper before painting the room. (=Dịch: Những người thợ sơn sẽ bóc lớp giấy dán tường cũ trước khi sơn căn phòng.)","Strong winds can [strip] leaves off the trees during autumn. (=Dịch: Những cơn gió mạnh có thể cuốn sạch lá trên cây vào mùa thu.)","The athlete was [stripped] of his medal after failing the drug test. (=Dịch: Vận động viên đã bị tước huy chương sau khi không vượt qua buổi kiểm tra chất kích thích.)"],"ukAudio":"/ai_services/tts3/?q=strip&lang=en-GB&ipa=%2Fstr%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=strip&lang=en-US&ipa=%2Fstr%C9%AAp%2F"},{"id":"lv_0_294","topic":"Daily Life and Social Activities","word":"studio","pos":"(n)","ipa":"/ˈstuː.diˌoʊ/","defVi":"phòng thu, xưởng vẽ, studio","defEn":"a room or building where an artist, photographer, or musician works","examples":["The band spent three months recording their new album in the [studio]. (=Dịch: Ban nhạc đã dành ba tháng để thu âm album mới của họ trong phòng thu.)","She rented a small [studio] in the city to practice her painting. (=Dịch: Cô ấy đã thuê một xưởng vẽ nhỏ trong thành phố để luyện tập vẽ tranh.)","The photographer set up bright lights across the photography [studio]. (=Dịch: Nhiếp ảnh gia đã lắp đặt đèn sáng khắp studio chụp ảnh.)"],"ukAudio":"/ai_services/tts3/?q=studio&lang=en-GB&ipa=%2F%CB%88stu%CB%90.di%CB%8Co%CA%8A%2F","usAudio":"/ai_services/tts3/?q=studio&lang=en-US&ipa=%2F%CB%88stu%CB%90.di%CB%8Co%CA%8A%2F"},{"id":"lv_0_295","topic":"Daily Life and Social Activities","word":"suburb","pos":"(n)","ipa":"/ˈsʌb.ɜːrb/","defVi":"khu vực ngoại ô, vùng ven đô","defEn":"an area where people live outside the center of a city","examples":["Many families prefer to live in a quiet [suburb] with good schools. (=Dịch: Nhiều gia đình thích sống ở một vùng ngoại ô yên tĩnh với các trường học tốt.)","He commutes daily from the [suburb] to his office downtown. (=Dịch: Hàng ngày anh ấy đi lại từ vùng ngoại ô đến văn phòng ở trung tâm thành phố.)","The peaceful [suburb] has developed rapidly over the past decade. (=Dịch: Vùng ngoại ô yên bình đã phát triển nhanh chóng trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=suburb&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.%C9%9C%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=suburb&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.%C9%9C%CB%90rb%2F"},{"id":"lv_0_296","topic":"Daily Life and Social Activities","word":"suitcase","pos":"(n)","ipa":"/ˈsuːt.keɪs/","defVi":"vali du lịch","defEn":"a rectangular case with a handle, used for carrying clothes and personal items when traveling","examples":["She packed her [suitcase] the night before the flight. (=Dịch: Cô ấy đã thu dọn vali vào đêm trước chuyến bay.)","The airline lost his [suitcase] during his trip to Paris. (=Dịch: Hãng hàng không đã làm mất vali của anh ấy trong chuyến đi đến Paris.)","He struggled to lift the heavy [suitcase] into the overhead bin. (=Dịch: Anh ấy đã chật vật nhấc chiếc vali nặng lên ngăn hành lý phía trên.)"],"ukAudio":"/ai_services/tts3/?q=suitcase&lang=en-GB&ipa=%2F%CB%88su%CB%90t.ke%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=suitcase&lang=en-US&ipa=%2F%CB%88su%CB%90t.ke%C9%AAs%2F"},{"id":"lv_0_297","topic":"Daily Life and Social Activities","word":"suite","pos":"(n)","ipa":"/swiːt/","defVi":"phòng dãy, phòng cao cấp khép kín (trong khách sạn)","defEn":"a set of connected rooms, especially in a hotel","examples":["They booked the bridal [suite] for their honeymoon. (=Dịch: Họ đã đặt phòng tân hôn cho tuần trăng mật của mình.)","The luxury hotel features an executive [suite] with a sea view. (=Dịch: Khách sạn sang trọng có một phòng suite cao cấp hướng biển.)","The company rented an office [suite] on the top floor of the skyscraper. (=Dịch: Công ty đã thuê một dãy văn phòng ở tầng cao nhất của tòa nhà chọc trời.)"],"ukAudio":"/ai_services/tts3/?q=suite&lang=en-GB&ipa=%2Fswi%CB%90t%2F","usAudio":"/ai_services/tts3/?q=suite&lang=en-US&ipa=%2Fswi%CB%90t%2F"},{"id":"lv_0_298","topic":"Daily Life and Social Activities","word":"sum","pos":"(n)","ipa":"/sʌm/","defVi":"tổng số, khoản tiền","defEn":"an amount of money, or the total number resulting from adding two or more numbers together","examples":["She donated a large [sum] of money to the local charity. (=Dịch: Cô ấy đã quyên góp một khoản tiền lớn cho tổ chức từ thiện địa phương.)","The [sum] of five and seven is twelve. (=Dịch: Tổng của năm và bảy là mười hai.)","The final [sum] of damages caused by the storm was enormous. (=Dịch: Tổng thiệt hại cuối cùng do cơn bão gây ra là rất lớn.)"],"ukAudio":"/ai_services/tts3/?q=sum&lang=en-GB&ipa=%2Fs%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=sum&lang=en-US&ipa=%2Fs%CA%8Cm%2F"},{"id":"lv_0_299","topic":"Daily Life and Social Activities","word":"sunset","pos":"(n)","ipa":"/ˈsʌn.sɛt/","defVi":"hoàng hôn, cảnh mặt trời lặn","defEn":"the time in the evening when the sun disappears below the horizon, or the colors in the sky at this time","examples":["We walked along the beach to watch the beautiful [sunset]. (=Dịch: Chúng tôi đi dạo dọc bãi biển để ngắm cảnh hoàng hôn tuyệt đẹp.)","The sky turned deep orange and purple during the [sunset]. (=Dịch: Bầu trời chuyển sang màu cam đậm và tím lúc hoàng hôn.)","The fishermen returned to the harbor just before [sunset]. (=Dịch: Các ngư dân đã trở về bến cảng ngay trước lúc hoàng hôn.)"],"ukAudio":"/ai_services/tts3/?q=sunset&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=sunset&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.s%C9%9Bt%2F"},{"id":"lv_0_300","topic":"Daily Life and Social Activities","word":"supervise","pos":"(v)","ipa":"/ˈsu·pərˌvaɪz/","defVi":"giám sát, quản lý","defEn":"to watch over and direct someone or something to ensure tasks are done correctly","examples":["A senior manager will [supervise] the new interns during their training period. (=Dịch: Một quản lý cấp cao sẽ giám sát các thực tập sinh mới trong suốt thời gian đào tạo của họ.)","Teachers need to [supervise] children closely when they play near the swimming pool. (=Dịch: Giáo viên cần giám sát trẻ em chặt chẽ khi các em chơi gần hồ bơi.)","He was hired to [supervise] the construction of the new office building. (=Dịch: Anh ấy được thuê để giám sát việc xây dựng tòa nhà văn phòng mới.)"],"ukAudio":"/ai_services/tts3/?q=supervise&lang=en-GB&ipa=%2F%CB%88su%C2%B7p%C9%99r%CB%8Cva%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=supervise&lang=en-US&ipa=%2F%CB%88su%C2%B7p%C9%99r%CB%8Cva%C9%AAz%2F"},{"id":"lv_0_301","topic":"Daily Life and Social Activities","word":"surname","pos":"(n)","ipa":"/ˈsɜrˌneɪm/","defVi":"họ (tên họ)","defEn":"the name that a person shares with other members of their family; a last name","examples":["Please write your first name followed by your [surname] on the application form. (=Dịch: Vui lòng viết tên rồi đến họ của bạn vào đơn đăng ký.)","Nguyen is the most common [surname] in Vietnam. (=Dịch: Nguyễn là họ phổ biến nhất ở Việt Nam.)","She decided to keep her maiden [surname] even after getting married. (=Dịch: Cô ấy quyết định giữ lại họ thời con gái của mình ngay cả sau khi kết hôn.)"],"ukAudio":"/ai_services/tts3/?q=surname&lang=en-GB&ipa=%2F%CB%88s%C9%9Cr%CB%8Cne%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=surname&lang=en-US&ipa=%2F%CB%88s%C9%9Cr%CB%8Cne%C9%AAm%2F"},{"id":"lv_0_302","topic":"Daily Life and Social Activities","word":"suspicious","pos":"(adj)","ipa":"/səˈspɪʃ.əs/","defVi":"khả nghi, đáng ngờ; hoài nghi","defEn":"feeling or causing a feeling that something is wrong, dishonest, or illegal","examples":["The security guard noticed a [suspicious] man walking around the parking lot. (=Dịch: Nhân viên bảo vệ nhận thấy một người đàn ông khả nghi đang đi quanh bãi đỗ xe.)","The police became [suspicious] when the suspect changed his story several times. (=Dịch: Cảnh sát bắt đầu nghi ngờ khi nghi phạm thay đổi lời khai nhiều lần.)","Do not click on any [suspicious] links in emails from unknown senders. (=Dịch: Đừng nhấp vào bất kỳ liên kết đáng ngờ nào trong các email gửi từ người lạ.)"],"ukAudio":"/ai_services/tts3/?q=suspicious&lang=en-GB&ipa=%2Fs%C9%99%CB%88sp%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=suspicious&lang=en-US&ipa=%2Fs%C9%99%CB%88sp%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_0_303","topic":"Daily Life and Social Activities","word":"swimmer","pos":"(n)","ipa":"/ˈswɪm.ər/","defVi":"người bơi lội, vận động viên bơi lội","defEn":"a person who swims, especially for sport or recreation","examples":["She is a talented [swimmer] who has won several national medals. (=Dịch: Cô ấy là một vận động viên bơi lội tài năng đã giành được nhiều huy chương cấp quốc gia.)","Even a strong [swimmer] can get into trouble in rough ocean waves. (=Dịch: Ngay cả một người bơi giỏi cũng có thể gặp rắc rối giữa những con sóng biển dữ dội.)","The lifeguard warned the [swimmer] not to go too far from the shore. (=Dịch: Nhân viên cứu hộ đã cảnh báo người bơi không nên ra quá xa bờ.)"],"ukAudio":"/ai_services/tts3/?q=swimmer&lang=en-GB&ipa=%2F%CB%88sw%C9%AAm.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=swimmer&lang=en-US&ipa=%2F%CB%88sw%C9%AAm.%C9%99r%2F"},{"id":"lv_0_304","topic":"Daily Life and Social Activities","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.əˌweɪ/","defVi":"đồ ăn mang về; quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else, or the shop that sells it","examples":["We were too tired to cook dinner, so we ordered a Chinese [takeaway]. (=Dịch: Chúng tôi quá mệt để nấu bữa tối, vì vậy chúng tôi đã gọi đồ ăn Trung Quốc mang về.)","There is a great pizza [takeaway] just around the corner from our apartment. (=Dịch: Có một quán pizza mang về rất ngon ngay góc phố cạnh căn hộ của chúng tôi.)","She picked up a coffee [takeaway] on her way to the morning lecture. (=Dịch: Cô ấy đã mua một ly cà phê mang đi trên đường đến buổi giảng sáng.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F"},{"id":"lv_0_305","topic":"Daily Life and Social Activities","word":"tank","pos":"(n)","ipa":"/tæŋk/","defVi":"xe tăng","defEn":"a heavy armored military vehicle that moves on tracks and carries large guns","examples":["The military deployed a [tank] to guard the entrance of the army base. (=Dịch: Quân đội đã triển khai một chiếc xe tăng để canh gác lối vào căn cứ quân sự.)","Several museums display a restored [tank] from the Second World War. (=Dịch: Một số viện bảo tàng trưng bày một chiếc xe tăng được phục chế từ Chiến tranh Thế giới thứ hai.)","The soldiers were trained to operate the modern [tank] in harsh desert conditions. (=Dịch: Các binh sĩ đã được huấn luyện để vận hành chiếc xe tăng hiện đại trong điều kiện sa mạc khắc nghiệt.)"],"ukAudio":"/ai_services/tts3/?q=tank&lang=en-GB&ipa=%2Ft%C3%A6%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=tank&lang=en-US&ipa=%2Ft%C3%A6%C5%8Bk%2F"},{"id":"lv_0_306","topic":"Daily Life and Social Activities","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, van khóa","defEn":"a device that controls the flow of liquid or gas from a pipe or container","examples":["Remember to turn off the [tap] while brushing your teeth to save water. (=Dịch: Hãy nhớ khóa vòi nước trong khi đánh răng để tiết kiệm nước.)","Water was dripping slowly from the leaky kitchen [tap]. (=Dịch: Nước nhỏ từng giọt chầm chậm từ chiếc vòi bếp bị rò rỉ.)","You should not drink water straight from the [tap] in this region. (=Dịch: Bạn không nên uống nước trực tiếp từ vòi ở khu vực này.)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_0_307","topic":"Daily Life and Social Activities","word":"temple","pos":"(n)","ipa":"/ˈtɛm.pəl/","defVi":"ngôi đền, ngôi chùa, miếu","defEn":"a building used for the worship of a god or gods in some religions","examples":["Thousands of tourists visit the ancient Buddhist [temple] every year. (=Dịch: Hàng nghìn du khách ghé thăm ngôi chùa Phật giáo cổ kính này mỗi năm.)","Visitors are asked to remove their shoes before entering the sacred [temple]. (=Dịch: Du khách được yêu cầu cởi giày trước khi bước vào ngôi đền linh thiêng.)","The stone carvings on the [temple] walls date back to the tenth century. (=Dịch: Những hình chạm khắc bằng đá trên tường đền có từ thế kỷ thứ mười.)"],"ukAudio":"/ai_services/tts3/?q=temple&lang=en-GB&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=temple&lang=en-US&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F"},{"id":"lv_0_308","topic":"Daily Life and Social Activities","word":"terrace","pos":"(n)","ipa":"/ˈtɛr.əs/","defVi":"sân hiên, sân thượng","defEn":"a flat outdoor area next to a building or on a roof, used for relaxing or dining","examples":["We enjoyed having our breakfast out on the sunny hotel [terrace]. (=Dịch: Chúng tôi rất thích dùng bữa sáng ngoài sân hiên đầy nắng của khách sạn.)","The rooftop [terrace] offers a panoramic view of the entire city skyline. (=Dịch: Sân thượng mang lại tầm nhìn toàn cảnh ra đường chân trời của toàn thành phố.)","They placed several potted plants and comfortable chairs on their apartment [terrace]. (=Dịch: Họ đặt vài chậu cây và những chiếc ghế êm ái trên sân hiên căn hộ của mình.)"],"ukAudio":"/ai_services/tts3/?q=terrace&lang=en-GB&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=terrace&lang=en-US&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F"},{"id":"lv_0_309","topic":"Daily Life and Social Activities","word":"tester","pos":"(n)","ipa":"/ˈtɛs.tər/","defVi":"người kiểm thử, người thử nghiệm","defEn":"a person whose job is to check whether a product, software, or system works properly","examples":["The software [tester] discovered a serious bug before the game was released. (=Dịch: Người kiểm thử phần mềm đã phát hiện ra một lỗi nghiêm trọng trước khi trò chơi được phát hành.)","Companies often hire a cosmetic [tester] to evaluate the safety of new beauty products. (=Dịch: Các công ty thường thuê người thử nghiệm mỹ phẩm để đánh giá độ an toàn của các sản phẩm làm đẹp mới.)","As a beta [tester], his role is to give detailed feedback on the app user experience. (=Dịch: Với tư cách là người thử nghiệm bản beta, vai trò của anh ấy là đưa ra phản hồi chi tiết về trải nghiệm người dùng của ứng dụng.)"],"ukAudio":"/ai_services/tts3/?q=tester&lang=en-GB&ipa=%2F%CB%88t%C9%9Bs.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tester&lang=en-US&ipa=%2F%CB%88t%C9%9Bs.t%C9%99r%2F"},{"id":"lv_0_310","topic":"Daily Life and Social Activities","word":"theft","pos":"(n)","ipa":"/θɛft/","defVi":"hành vi trộm cắp, tội trộm cắp","defEn":"the act or crime of stealing someone's property","examples":["The store installed security cameras to prevent [theft]. (=Dịch: Cửa hàng đã lắp đặt các camera an ninh để ngăn chặn nạn trộm cắp.)","He reported the [theft] of his car to the police immediately. (=Dịch: Anh ấy đã báo cáo vụ mất trộm xe ô tô của mình cho cảnh sát ngay lập tức.)","Identity [theft] has become a major problem in the digital age. (=Dịch: Đánh cắp danh tính đã trở thành một vấn đề lớn trong thời đại kỹ thuật số.)"],"ukAudio":"/ai_services/tts3/?q=theft&lang=en-GB&ipa=%2F%CE%B8%C9%9Bft%2F","usAudio":"/ai_services/tts3/?q=theft&lang=en-US&ipa=%2F%CE%B8%C9%9Bft%2F"},{"id":"lv_0_311","topic":"Daily Life and Social Activities","word":"thorough","pos":"(adj)","ipa":"/ˈθɜːr.oʊ/","defVi":"kỹ lưỡng, cẩn thận, toàn diện","defEn":"complete and with great attention to every detail","examples":["The police conducted a [thorough] investigation into the accident. (=Dịch: Cảnh sát đã tiến hành một cuộc điều tra kỹ lưỡng về vụ tai nạn.)","You should do a [thorough] check of your essay before submitting it. (=Dịch: Bạn nên kiểm tra cẩn thận bài luận của mình trước khi nộp.)","She has a [thorough] understanding of the local market. (=Dịch: Cô ấy có sự hiểu biết sâu sắc về thị trường địa phương.)"],"ukAudio":"/ai_services/tts3/?q=thorough&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9C%CB%90r.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=thorough&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9C%CB%90r.o%CA%8A%2F"},{"id":"lv_0_312","topic":"Daily Life and Social Activities","word":"thumb","pos":"(n)","ipa":"/θʌm/","defVi":"ngón tay cái","defEn":"the short, thick finger on the side of each human hand","examples":["She accidentally hit her [thumb] with a hammer. (=Dịch: Cô ấy vô tình đập búa vào ngón tay cái của mình.)","He gave me a [thumb] up to show his approval. (=Dịch: Anh ấy đã giơ ngón tay cái lên để thể hiện sự đồng thuận của mình.)","Babies often soothe themselves by sucking their [thumb]. (=Dịch: Trẻ sơ sinh thường tự trấn an bằng cách mút ngón tay cái.)"],"ukAudio":"/ai_services/tts3/?q=thumb&lang=en-GB&ipa=%2F%CE%B8%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=thumb&lang=en-US&ipa=%2F%CE%B8%CA%8Cm%2F"},{"id":"lv_0_313","topic":"Daily Life and Social Activities","word":"tiger","pos":"(n)","ipa":"/ˈtaɪ.ɡɚ/","defVi":"con hổ","defEn":"a large wild cat that has yellow-orange fur with black stripes","examples":["The Bengal [tiger] is an endangered species in Asia. (=Dịch: Hổ Bengal là một loài có nguy cơ tuyệt chủng ở châu Á.)","We saw a majestic [tiger] resting under the shade of a tree. (=Dịch: Chúng tôi đã nhìn thấy một con hổ oai vệ đang nghỉ ngơi dưới bóng cây.)","Poaching poses a severe threat to wild [tiger] populations. (=Dịch: Nạn săn trộm gây ra mối đe dọa nghiêm trọng đối với các quần thể hổ hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=tiger&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tiger&lang=en-US&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%9A%2F"},{"id":"lv_0_314","topic":"Daily Life and Social Activities","word":"toddler","pos":"(n)","ipa":"/ˈtɑːd.lɚ/","defVi":"trẻ tập đi (từ 1 đến 3 tuổi)","defEn":"a young child who has only recently learned to walk, typically between one and three years old","examples":["The [toddler] took his first steps across the living room. (=Dịch: Đứa trẻ mới biết đi đã chập chững những bước đầu tiên qua phòng khách.)","Parents need to childproof their home once their baby becomes a [toddler]. (=Dịch: Các bậc cha mẹ cần tạo môi trường an toàn cho trẻ trong nhà khi con mình bước vào độ tuổi biết đi.)","She works at a daycare center taking care of active [toddler] groups. (=Dịch: Cô ấy làm việc tại một trung tâm giữ trẻ, chăm sóc các nhóm trẻ mới biết đi hiếu động.)"],"ukAudio":"/ai_services/tts3/?q=toddler&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90d.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=toddler&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90d.l%C9%9A%2F"},{"id":"lv_0_315","topic":"Daily Life and Social Activities","word":"trail","pos":"(n)","ipa":"/treɪl/","defVi":"đường mòn, dấu vết","defEn":"a path through the countryside or a forest, or a series of marks left behind","examples":["They followed a narrow [trail] through the dense forest. (=Dịch: Họ đi theo một con đường mòn hẹp xuyên qua khu rừng rậm rạp.)","The storm left a [trail] of destruction across the coastal town. (=Dịch: Cơn bão đã để lại một vệt tàn phá dài khắp thị trấn ven biển.)","The dog easily tracked the scent [trail] of the missing child. (=Dịch: Chú chó đã dễ dàng lần theo dấu vết mùi hương của đứa trẻ mất tích.)"],"ukAudio":"/ai_services/tts3/?q=trail&lang=en-GB&ipa=%2Ftre%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=trail&lang=en-US&ipa=%2Ftre%C9%AAl%2F"},{"id":"lv_0_316","topic":"Daily Life and Social Activities","word":"trap","pos":"(n)","ipa":"/træp/","defVi":"cái bẫy, cạm bẫy","defEn":"a device or clever plan designed to catch or trick animals or people","examples":["The hunters set a [trap] in the woods to catch rabbits. (=Dịch: Những người thợ săn đã đặt một cái bẫy trong rừng để bắt thỏ.)","He realized too late that he had fallen into a clever [trap]. (=Dịch: Anh ấy nhận ra quá muộn rằng mình đã rơi vào một cái bẫy tinh vi.)","Many consumers fall into the debt [trap] due to high credit card interest. (=Dịch: Nhiều người tiêu dùng rơi vào bẫy nợ nần do lãi suất thẻ tín dụng cao.)"],"ukAudio":"/ai_services/tts3/?q=trap&lang=en-GB&ipa=%2Ftr%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=trap&lang=en-US&ipa=%2Ftr%C3%A6p%2F"},{"id":"lv_0_317","topic":"Daily Life and Social Activities","word":"treasure","pos":"(n)","ipa":"/ˈtreʒ.ɚ/","defVi":"kho báu, của quý, vật quý giá","defEn":"a collection of valuable things such as gold, silver, or jewels, or a highly valued object","examples":["Divers discovered sunken [treasure] in the ancient shipwreck. (=Dịch: Các thợ lặn đã phát hiện ra kho báu bị chìm trong xác con tàu cổ.)","The national museum houses many priceless art [treasure] items. (=Dịch: Bảo tàng quốc gia lưu giữ nhiều hiện vật kho báu nghệ thuật vô giá.)","Historical documents are considered a national [treasure] by historians. (=Dịch: Các tài liệu lịch sử được các nhà sử học coi là báu vật quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=treasure&lang=en-GB&ipa=%2F%CB%88tre%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=treasure&lang=en-US&ipa=%2F%CB%88tre%CA%92.%C9%9A%2F"},{"id":"lv_0_318","topic":"Daily Life and Social Activities","word":"trek","pos":"(n)","ipa":"/trɛk/","defVi":"chuyến đi bộ đường dài vất vả, hành trình gian nan","defEn":"a long, difficult journey, especially one made on foot across rough terrain","examples":["They organized a week-long [trek] through the Himalayan mountains. (=Dịch: Họ đã tổ chức một chuyến đi bộ đường dài kéo dài một tuần qua dãy núi Himalaya.)","Walking to the remote village was an exhausting [trek] in the heat. (=Dịch: Đi bộ đến ngôi làng hẻo lánh là một chuyến đi dài kiệt sức dưới trời nắng nóng.)","He prepared for the difficult [trek] by doing regular endurance training. (=Dịch: Anh ấy đã chuẩn bị cho chuyến đi bộ dài đầy gian nan bằng cách thường xuyên rèn luyện sức bền.)"],"ukAudio":"/ai_services/tts3/?q=trek&lang=en-GB&ipa=%2Ftr%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=trek&lang=en-US&ipa=%2Ftr%C9%9Bk%2F"},{"id":"lv_0_319","topic":"Daily Life and Social Activities","word":"trial","pos":"(n)","ipa":"/ˈtraɪ.əl/","defVi":"phiên tòa xét xử, sự thử nghiệm","defEn":"a formal examination of evidence in court, or a test of performance or quality","examples":["The murder suspect will face [trial] next month. (=Dịch: Nghi phạm giết người sẽ phải hầu tòa vào tháng tới.)","The new cancer drug is currently undergoing clinical [trial] phases. (=Dịch: Loại thuốc điều trị ung thư mới hiện đang trải qua các giai đoạn thử nghiệm lâm sàng.)","The company offered a 30-day free [trial] for its new software. (=Dịch: Công ty đã cung cấp bản dùng thử miễn phí trong 30 ngày cho phần mềm mới của họ.)"],"ukAudio":"/ai_services/tts3/?q=trial&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=trial&lang=en-US&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F"},{"id":"lv_0_320","topic":"Daily Life and Social Activities","word":"tune","pos":"(v)","ipa":"/tuːn/","defVi":"lên dây (đàn), chỉnh âm, điều chỉnh","defEn":"to adjust a musical instrument so that it produces the correct notes, or to adjust a device for better reception or performance","examples":["He spent ten minutes trying to [tune] his acoustic guitar before the concert. (=Dịch: Anh ấy đã dành mười phút để cố gắng chỉnh dây cây đàn guitar acoustic của mình trước buổi hòa nhạc.)","The mechanic will [tune] the engine to improve fuel efficiency. (=Dịch: Người thợ máy sẽ tinh chỉnh động cơ để cải thiện hiệu quả sử dụng nhiên liệu.)","Make sure to [tune] the radio to the local news station. (=Dịch: Hãy chắc chắn rằng bạn đã dò đài radio sang kênh tin tức địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tune&lang=en-GB&ipa=%2Ftu%CB%90n%2F","usAudio":"/ai_services/tts3/?q=tune&lang=en-US&ipa=%2Ftu%CB%90n%2F"},{"id":"lv_0_321","topic":"Daily Life and Social Activities","word":"twelfth","pos":"(adj)","ipa":"/twɛlfθ/","defVi":"thứ mười hai","defEn":"coming next after the eleventh; being number twelve in a sequence","examples":["She celebrated her [twelfth] birthday with a family picnic in the park. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ mười hai của mình bằng một buổi dã ngoại cùng gia đình trong công viên.)","Our office is located on the [twelfth] floor of the commercial building. (=Dịch: Văn phòng của chúng tôi nằm ở tầng mười hai của tòa nhà thương mại.)","December is the [twelfth] and final month of the calendar year. (=Dịch: Tháng Mười Hai là tháng thứ mười hai và cũng là tháng cuối cùng của năm dương lịch.)"],"ukAudio":"/ai_services/tts3/?q=twelfth&lang=en-GB&ipa=%2Ftw%C9%9Blf%CE%B8%2F","usAudio":"/ai_services/tts3/?q=twelfth&lang=en-US&ipa=%2Ftw%C9%9Blf%CE%B8%2F"},{"id":"lv_0_322","topic":"Daily Life and Social Activities","word":"ultimate","pos":"(adj)","ipa":"/ˈʌl.tə.mət/","defVi":"tối hậu, cuối cùng, đỉnh cao","defEn":"happening or coming at the end of a process; final or greatest","examples":["His [ultimate] goal is to start his own software development company. (=Dịch: Mục tiêu cuối cùng của anh ấy là thành lập công ty phát triển phần mềm của riêng mình.)","Climbing Mount Everest remains the [ultimate] challenge for many mountaineers. (=Dịch: Leo đỉnh Everest vẫn là thử thách tột cùng đối với nhiều nhà leo núi.)","The [ultimate] decision rests with the board of directors. (=Dịch: Quyết định cuối cùng thuộc về hội đồng quản trị.)"],"ukAudio":"/ai_services/tts3/?q=ultimate&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=ultimate&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F"},{"id":"lv_0_323","topic":"Daily Life and Social Activities","word":"undergo","pos":"(v)","ipa":"/ˌʌn.dɚˈɡoʊ/","defVi":"trải qua, chịu đựng","defEn":"to experience or suffer something, especially a change, process, or medical procedure","examples":["The historic building will [undergo] extensive renovations next spring. (=Dịch: Tòa nhà lịch sử này sẽ trải qua những đợt trùng tu toàn diện vào mùa xuân tới.)","Patients must [undergo] several medical tests before receiving the surgery. (=Dịch: Bệnh nhân phải trải qua một số xét nghiệm y tế trước khi tiến hành phẫu thuật.)","The company had to [undergo] major restructuring to avoid bankruptcy. (=Dịch: Công ty đã phải trải qua một cuộc tái cấu trúc lớn để tránh phá sản.)"],"ukAudio":"/ai_services/tts3/?q=undergo&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=undergo&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88%C9%A1o%CA%8A%2F"},{"id":"lv_0_324","topic":"Daily Life and Social Activities","word":"unwanted","pos":"(adj)","ipa":"/ʌnˈwɑːn.tɪd/","defVi":"không mong muốn, thừa thãi","defEn":"not desired, needed, or requested","examples":["You can donate [unwanted] clothes to local charity organizations. (=Dịch: Bạn có thể quyên góp quần áo không dùng đến cho các tổ chức từ thiện địa phương.)","The email filter helps block [unwanted] advertisements and spam. (=Dịch: Bộ lọc email giúp chặn các quảng cáo và thư rác không mong muốn.)","She tried to ignore the [unwanted] advice from her distant relatives. (=Dịch: Cô ấy đã cố gắng phớt lờ những lời khuyên không mong muốn từ những người họ hàng xa.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_0_325","topic":"Daily Life and Social Activities","word":"vacancy","pos":"(n)","ipa":"/ˈveɪ.kən.si/","defVi":"vị trí tuyển dụng, chỗ trống","defEn":"a job or position that is available, or an unoccupied room in a hotel","examples":["The company advertised a [vacancy] for an experienced marketing manager. (=Dịch: Công ty đã đăng thông báo tuyển dụng cho một vị trí trống là trưởng phòng tiếp thị giàu kinh nghiệm.)","The motel had a 'No [vacancy]' sign hanging outside the front desk. (=Dịch: Nhà nghỉ treo biển 'Hết phòng' bên ngoài quầy lễ tân.)","We hope to fill the job [vacancy] before the start of next month. (=Dịch: Chúng tôi hy vọng sẽ tuyển được người cho vị trí việc làm còn trống trước đầu tháng tới.)"],"ukAudio":"/ai_services/tts3/?q=vacancy&lang=en-GB&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=vacancy&lang=en-US&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F"},{"id":"lv_0_326","topic":"Daily Life and Social Activities","word":"valid","pos":"(adj)","ipa":"/ˈvæl.ɪd/","defVi":"hợp lệ, có hiệu lực, có cơ sở","defEn":"based on truth, logic, or fact; legally or officially acceptable","examples":["You must present a [valid] passport before boarding the international flight. (=Dịch: Bạn phải xuất trình hộ chiếu hợp lệ trước khi lên chuyến bay quốc tế.)","She raised a [valid] point during the debate about public transport costs. (=Dịch: Cô ấy đã đưa ra một quan điểm xác đáng trong cuộc tranh luận về chi phí giao thông công cộng.)","This discount coupon is only [valid] until the end of the week. (=Dịch: Phiếu giảm giá này chỉ có hiệu lực cho đến cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=valid&lang=en-GB&ipa=%2F%CB%88v%C3%A6l.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=valid&lang=en-US&ipa=%2F%CB%88v%C3%A6l.%C9%AAd%2F"},{"id":"lv_0_327","topic":"Daily Life and Social Activities","word":"vegetarian","pos":"(adj)","ipa":"/ˌvɛdʒ.əˈtɛr.i.ən/","defVi":"chay, ăn chay","defEn":"consisting entirely of plant-based foods, containing no meat or fish","examples":["The restaurant provides a rich [vegetarian] menu for non-meat eaters. (=Dịch: Nhà hàng cung cấp một thực đơn chay phong phú cho những người không ăn thịt.)","She decided to follow a strict [vegetarian] diet for health reasons. (=Dịch: Cô ấy quyết định theo đuổi chế độ ăn chay nghiêm ngặt vì lý do sức khỏe.)","We ordered a delicious [vegetarian] pizza topped with mushrooms and olives. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza chay thơm ngon phủ nấm và ô liu.)"],"ukAudio":"/ai_services/tts3/?q=vegetarian&lang=en-GB&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetarian&lang=en-US&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F"},{"id":"lv_0_328","topic":"Daily Life and Social Activities","word":"venue","pos":"(n)","ipa":"/ˈvɛn.juː/","defVi":"địa điểm tổ chức (sự kiện, hội nghị, biểu diễn)","defEn":"the place where a public event, meeting, or concert takes place","examples":["The new convention center is an ideal [venue] for international conferences. (=Dịch: Trung tâm hội nghị mới là một địa điểm lý tưởng cho các hội nghị quốc tế.)","They are still searching for a suitable wedding [venue] with a nice garden. (=Dịch: Họ vẫn đang tìm kiếm một địa điểm tổ chức đám cưới thích hợp có khu vườn đẹp.)","The stadium was chosen as the [venue] for the upcoming championship match. (=Dịch: Sân vận động đã được chọn làm địa điểm tổ chức trận chung kết sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=venue&lang=en-GB&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F","usAudio":"/ai_services/tts3/?q=venue&lang=en-US&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F"},{"id":"lv_0_329","topic":"Daily Life and Social Activities","word":"verdict","pos":"(n)","ipa":"/ˈvɝː.dɪkt/","defVi":"phán quyết, lời tuyên án, kết luận","defEn":"an official decision made by a jury in court, or an opinion formed after careful consideration","examples":["The jury reached a unanimous [verdict] of guilty after four hours of deliberation. (=Dịch: Bồi thẩm đoàn đã đưa ra phán quyết nhất trí có tội sau bốn giờ nghị án.)","Critics delivered a favorable [verdict] on the director's latest film. (=Dịch: Các nhà phê bình đã đưa ra nhận định ưu ái cho bộ phim mới nhất của đạo diễn.)","The public eagerly awaited the court's final [verdict] on the corruption case. (=Dịch: Công chúng háo hức chờ đợi phán quyết cuối cùng của tòa án về vụ án tham nhũng.)"],"ukAudio":"/ai_services/tts3/?q=verdict&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.d%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=verdict&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.d%C9%AAkt%2F"},{"id":"lv_0_330","topic":"Daily Life and Social Activities","word":"visible","pos":"(adj)","ipa":"/ˈvɪz.ə.bəl/","defVi":"có thể nhìn thấy được, rõ ràng","defEn":"able to be seen or easily noticed","examples":["The stars were clearly [visible] in the night sky. (=Dịch: Những ngôi sao có thể nhìn thấy rõ ràng trên bầu trời đêm.)","There has been a [visible] improvement in her spoken English. (=Dịch: Đã có một sự tiến bộ rõ rệt trong khả năng nói tiếng Anh của cô ấy.)","He wore a brightly colored jacket so he would be [visible] to drivers. (=Dịch: Anh ấy mặc một chiếc áo khoác có màu sắc rực rỡ để các tài xế có thể nhìn thấy mình.)"],"ukAudio":"/ai_services/tts3/?q=visible&lang=en-GB&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=visible&lang=en-US&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F"},{"id":"lv_0_331","topic":"Daily Life and Social Activities","word":"vote","pos":"(n)","ipa":"/voʊt/","defVi":"lá phiếu, sự bỏ phiếu","defEn":"a formal choice made by an individual in an election or meeting","examples":["Every citizen has the right to cast a [vote] in the election. (=Dịch: Mọi công dân đều có quyền bỏ phiếu trong cuộc bầu cử.)","The proposal was passed by a majority [vote]. (=Dịch: Đề xuất đã được thông qua nhờ đa số phiếu bầu.)","The committee decided to take a [vote] on the new policy. (=Dịch: Ủy ban đã quyết định tiến hành bỏ phiếu về chính sách mới.)"],"ukAudio":"/ai_services/tts3/?q=vote&lang=en-GB&ipa=%2Fvo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=vote&lang=en-US&ipa=%2Fvo%CA%8At%2F"},{"id":"lv_0_332","topic":"Daily Life and Social Activities","word":"waitress","pos":"(n)","ipa":"/ˈweɪ.trəs/","defVi":"nữ bồi bàn, nữ phục vụ","defEn":"a woman whose job is to serve food and drinks to customers in a restaurant","examples":["The [waitress] brought us our drinks and took our food order. (=Dịch: Người phục vụ nữ đã mang đồ uống cho chúng tôi và ghi lại các món ăn được gọi.)","She worked as a [waitress] during college to pay for tuition. (=Dịch: Cô ấy đã làm phục vụ bàn trong thời gian học đại học để chi trả học phí.)","We left a generous tip for our friendly [waitress]. (=Dịch: Chúng tôi đã để lại một khoản tiền boa hậu hĩnh cho cô phục vụ thân thiện.)"],"ukAudio":"/ai_services/tts3/?q=waitress&lang=en-GB&ipa=%2F%CB%88we%C9%AA.tr%C9%99s%2F","usAudio":"/ai_services/tts3/?q=waitress&lang=en-US&ipa=%2F%CB%88we%C9%AA.tr%C9%99s%2F"},{"id":"lv_0_333","topic":"Daily Life and Social Activities","word":"walker","pos":"(n)","ipa":"/ˈwɑː.kɚ/","defVi":"người đi bộ; khung tập đi","defEn":"a person who walks, or a frame designed to assist someone in walking","examples":["The national park is very popular with every keen [walker]. (=Dịch: Công viên quốc gia này rất được những người đam mê đi bộ yêu thích.)","After his hip surgery, he needed a [walker] to move around. (=Dịch: Sau ca phẫu thuật khớp hông, ông ấy cần một khung tập đi để di chuyển.)","Drivers must always remain alert and yield to any [walker] at the crosswalk. (=Dịch: Người lái xe phải luôn tỉnh táo và nhường đường cho bất kỳ người đi bộ nào tại vạch qua đường.)"],"ukAudio":"/ai_services/tts3/?q=walker&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=walker&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.k%C9%9A%2F"},{"id":"lv_0_334","topic":"Daily Life and Social Activities","word":"wallet","pos":"(n)","ipa":"/ˈwɑː.lɪt/","defVi":"ví tiền (thường là ví nam, ví gập)","defEn":"a small, flat folding case used for carrying money and plastic cards","examples":["He realized that he had left his [wallet] at home. (=Dịch: Anh ấy nhận ra rằng mình đã để quên ví ở nhà.)","She kept a family photo inside her leather [wallet]. (=Dịch: Cô ấy giữ một bức ảnh gia đình bên trong chiếc ví da của mình.)","A kind stranger found my lost [wallet] and returned it. (=Dịch: Một người lạ tốt bụng đã tìm thấy chiếc ví bị mất của tôi và trả lại.)"],"ukAudio":"/ai_services/tts3/?q=wallet&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.l%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=wallet&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.l%C9%AAt%2F"},{"id":"lv_0_335","topic":"Daily Life and Social Activities","word":"warden","pos":"(n)","ipa":"/ˈwɔːr.dən/","defVi":"người giám sát, người coi sóc, quản lý","defEn":"an official who is responsible for supervising a particular place or enforcing regulations","examples":["The park [warden] warned the hikers about recent bear sightings. (=Dịch: Người quản lý công viên đã cảnh báo những người đi bộ đường dài về việc gần đây có người nhìn thấy gấu.)","The traffic [warden] issued a ticket for illegal parking. (=Dịch: Nhân viên kiểm soát giao thông đã phạt một vé vì lỗi đỗ xe trái phép.)","Each residential hall has a [warden] to look after the students' safety. (=Dịch: Mỗi khu ký túc xá đều có một người quản lý để đảm bảo an toàn cho sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=warden&lang=en-GB&ipa=%2F%CB%88w%C9%94%CB%90r.d%C9%99n%2F","usAudio":"/ai_services/tts3/?q=warden&lang=en-US&ipa=%2F%CB%88w%C9%94%CB%90r.d%C9%99n%2F"},{"id":"lv_0_336","topic":"Daily Life and Social Activities","word":"watercolour","pos":"(n)","ipa":"/ˈwɑː.t̬ɚˌkʌl.ɚ/","defVi":"tranh màu nước, màu nước","defEn":"a type of paint mixed with water, or a picture painted with this medium","examples":["She created a delicate landscape painting using [watercolour]. (=Dịch: Cô ấy đã tạo ra một bức tranh phong cảnh tinh tế bằng màu nước.)","The museum exhibited a rare collection of Victorian [watercolour] paintings. (=Dịch: Bảo tàng đã trưng bày một bộ sưu tập tranh màu nước thời Victoria quý hiếm.)","Learning how to paint in [watercolour] requires a great deal of patience. (=Dịch: Học cách vẽ bằng màu nước đòi hỏi sự kiên nhẫn rất lớn.)"],"ukAudio":"/ai_services/tts3/?q=watercolour&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A%CB%8Ck%CA%8Cl.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=watercolour&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A%CB%8Ck%CA%8Cl.%C9%9A%2F"},{"id":"lv_0_337","topic":"Daily Life and Social Activities","word":"waterfall","pos":"(n)","ipa":"/ˈwɑː.t̬ɚ.fɑːl/","defVi":"thác nước","defEn":"a cascade of water falling from a height, formed when a stream flows over a precipice","examples":["The tourists gathered to take photos of the majestic [waterfall]. (=Dịch: Các du khách tụ tập để chụp ảnh thác nước hùng vĩ.)","You can hear the roaring sound of the [waterfall] from a mile away. (=Dịch: Bạn có thể nghe thấy tiếng gầm vang của thác nước từ cách xa một dặm.)","A small wooden bridge was built right above the natural [waterfall]. (=Dịch: Một cây cầu gỗ nhỏ đã được xây dựng ngay phía trên thác nước tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=waterfall&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.f%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=waterfall&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.f%C9%91%CB%90l%2F"},{"id":"lv_0_338","topic":"Daily Life and Social Activities","word":"waterproof","pos":"(adj)","ipa":"/ˈwɑː.t̬ɚ.pruːf/","defVi":"chống thấm nước","defEn":"not allowing water to pass through","examples":["Make sure to pack a [waterproof] jacket in case it rains during the hike. (=Dịch: Hãy chắc chắn mang theo một chiếc áo khoác chống nước phòng trường hợp trời mưa trong chuyến đi bộ đường dài.)","This modern smartwatch is completely [waterproof] up to fifty meters. (=Dịch: Chiếc đồng hồ thông minh hiện đại này có khả năng chống nước hoàn toàn ở độ sâu lên đến 50 mét.)","We used a heavy [waterproof] tarp to protect our camping gear. (=Dịch: Chúng tôi đã dùng một tấm bạt chống nước dày để bảo vệ đồ cắm trại của mình.)"],"ukAudio":"/ai_services/tts3/?q=waterproof&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.pru%CB%90f%2F","usAudio":"/ai_services/tts3/?q=waterproof&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90.t%CC%AC%C9%9A.pru%CB%90f%2F"},{"id":"lv_0_339","topic":"Daily Life and Social Activities","word":"weekday","pos":"(n)","ipa":"/ˈwiːk.deɪ/","defVi":"ngày trong tuần (từ thứ Hai đến thứ Sáu)","defEn":"any day of the week except Saturday and Sunday","examples":["The library is much less crowded on a [weekday] morning. (=Dịch: Thư viện vắng người hơn nhiều vào buổi sáng các ngày trong tuần.)","She usually commutes to the office by train every [weekday]. (=Dịch: Cô ấy thường đi làm bằng tàu hỏa vào mỗi ngày trong tuần.)","The hotel charges lower room rates during the [weekday] than on weekends. (=Dịch: Khách sạn tính giá phòng vào ngày trong tuần thấp hơn so với cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=weekday&lang=en-GB&ipa=%2F%CB%88wi%CB%90k.de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weekday&lang=en-US&ipa=%2F%CB%88wi%CB%90k.de%C9%AA%2F"},{"id":"lv_0_340","topic":"Daily Life and Social Activities","word":"weekly","pos":"(adj)","ipa":"/ˈwik.li/","defVi":"hàng tuần","defEn":"happening, done, or published once every week","examples":["We hold a [weekly] staff meeting every Monday morning. (=Dịch: Chúng tôi tổ chức một cuộc họp nhân viên hàng tuần vào mỗi sáng thứ Hai.)","He writes a column for a [weekly] magazine. (=Dịch: Anh ấy viết một chuyên mục cho một tạp chí hàng tuần.)","The school charges a [weekly] fee for after-school activities. (=Dịch: Trường thu một khoản phí hàng tuần cho các hoạt động sau giờ học.)"],"ukAudio":"/ai_services/tts3/?q=weekly&lang=en-GB&ipa=%2F%CB%88wik.li%2F","usAudio":"/ai_services/tts3/?q=weekly&lang=en-US&ipa=%2F%CB%88wik.li%2F"},{"id":"lv_0_341","topic":"Daily Life and Social Activities","word":"willow","pos":"(n)","ipa":"/ˈwɪl.oʊ/","defVi":"cây liễu","defEn":"a tree with long, thin branches and narrow leaves that often grows near water","examples":["A weeping [willow] stood gracefully near the edge of the pond. (=Dịch: Một cây liễu rủ đứng duyên dáng gần bờ ao.)","The birds built their nest among the branches of an old [willow]. (=Dịch: Những chú chim đã làm tổ giữa các cành của một cây liễu già.)","We sat in the cool shade of a [willow] to escape the midday heat. (=Dịch: Chúng tôi ngồi dưới bóng râm mát rượi của một cây liễu để tránh cái nóng ban trưa.)"],"ukAudio":"/ai_services/tts3/?q=willow&lang=en-GB&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=willow&lang=en-US&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F"},{"id":"lv_0_342","topic":"Daily Life and Social Activities","word":"yoga","pos":"(n)","ipa":"/ˈjoʊ.ɡə/","defVi":"bộ môn yoga","defEn":"a set of physical exercises and breathing techniques used for relaxation and health","examples":["She practices [yoga] every morning to reduce stress and stay flexible. (=Dịch: Cô ấy tập yoga mỗi sáng để giảm căng thẳng và duy trì sự dẻo dai.)","The community center offers [yoga] classes for beginners. (=Dịch: Trung tâm cộng đồng mở các lớp học yoga dành cho người mới bắt đầu.)","Many doctors recommend [yoga] as a gentle form of exercise. (=Dịch: Nhiều bác sĩ khuyên nên tập yoga như một hình thức thể dục nhẹ nhàng.)"],"ukAudio":"/ai_services/tts3/?q=yoga&lang=en-GB&ipa=%2F%CB%88jo%CA%8A.%C9%A1%C9%99%2F","usAudio":"/ai_services/tts3/?q=yoga&lang=en-US&ipa=%2F%CB%88jo%CA%8A.%C9%A1%C9%99%2F"},{"id":"lv_0_343","topic":"Daily Life and Social Activities","word":"youth","pos":"(n)","ipa":"/juθ/","defVi":"tuổi trẻ, thời thanh xuân; giới trẻ","defEn":"the time of life when a person is young, especially the period between childhood and adulthood","examples":["He spent most of his [youth] traveling around the world. (=Dịch: Anh ấy đã dành phần lớn thời tuổi trẻ của mình để đi du lịch khắp thế giới.)","The program aims to inspire local [youth] to pursue higher education. (=Dịch: Chương trình nhằm truyền cảm hứng cho giới trẻ địa phương theo đuổi con đường học vấn cao hơn.)","She maintained her energy and optimism well beyond her [youth]. (=Dịch: Bà vẫn duy trì được năng lượng và sự lạc quan của mình ngay cả khi thời tuổi trẻ đã qua đi rất lâu.)"],"ukAudio":"/ai_services/tts3/?q=youth&lang=en-GB&ipa=%2Fju%CE%B8%2F","usAudio":"/ai_services/tts3/?q=youth&lang=en-US&ipa=%2Fju%CE%B8%2F"}]},"rawTopic":"Daily Life and Social Activities"},{"id":"listening_u5_2","title":"Chủ đề 2/10: Job Seeking and Work","actTitle":"Từ vựng chủ đề: Job Seeking and Work (108 từ)","problem":{"pType":"topic_flashcards","topic":"Job Seeking and Work","count":108,"words":[{"id":"lv_1_0","topic":"Job Seeking and Work","word":"acquisition","pos":"(n)","ipa":"/ˌæk.wəˈzɪʃ.ən/","defVi":"sự mua lại (công ty), sự tiếp thu hoặc tích lũy","defEn":"the act of getting something, or buying another company","examples":["Language [acquisition] is much easier for young children than for adults. (=Dịch: Việc tiếp thu ngôn ngữ đối với trẻ nhỏ dễ dàng hơn nhiều so với người lớn.)","The tech giant announced the [acquisition] of a smaller startup yesterday. (=Dịch: Gã khổng lồ công nghệ đã công bố thương vụ mua lại một công ty khởi nghiệp nhỏ hơn vào ngày hôm qua.)","The museum's latest [acquisition] is a rare painting from the nineteenth century. (=Dịch: Hiện vật mới nhất mà bảo tàng mua lại được là một bức tranh hiếm từ thế kỷ mười chín.)"],"ukAudio":"/ai_services/tts3/?q=acquisition&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.w%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=acquisition&lang=en-US&ipa=%2F%CB%8C%C3%A6k.w%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_1","topic":"Job Seeking and Work","word":"admin","pos":"(n)","ipa":"/ˈæd.mɪn/","defVi":"công việc hành chính, ban quản trị/nhân viên hành chính","defEn":"administrative work, or the person or department responsible for managing it","examples":["I spent the entire morning dealing with paperwork and routine [admin]. (=Dịch: Tôi đã dành cả buổi sáng để giải quyết giấy tờ và công việc hành chính thường ngày.)","If you cannot log into your account, please contact the system [admin]. (=Dịch: Nếu bạn không thể đăng nhập vào tài khoản của mình, vui lòng liên hệ với quản trị viên hệ thống.)","The company hired a new assistant to help reduce the heavy [admin] workload. (=Dịch: Công ty đã thuê một trợ lý mới để giúp giảm bớt khối lượng công việc hành chính nặng nề.)"],"ukAudio":"/ai_services/tts3/?q=admin&lang=en-GB&ipa=%2F%CB%88%C3%A6d.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=admin&lang=en-US&ipa=%2F%CB%88%C3%A6d.m%C9%AAn%2F"},{"id":"lv_1_2","topic":"Job Seeking and Work","word":"administration","pos":"(n)","ipa":"/ədˌmɪn.əˈstreɪ.ʃən/","defVi":"sự quản lý, bộ máy hành chính","defEn":"the management and organization of a business, institution, or government","examples":["She has spent many years working in university [administration]. (=Dịch: Cô ấy đã dành nhiều năm làm việc trong bộ phận quản trị của trường đại học.)","The new [administration] announced major tax reforms today. (=Dịch: Chính quyền mới đã công bố các cải cách thuế quan trọng vào ngày hôm nay.)","Inefficient [administration] led to massive delays in processing applications. (=Dịch: Công tác quản lý kém hiệu quả đã dẫn đến sự chậm trễ nghiêm trọng trong việc xử lý hồ sơ.)"],"ukAudio":"/ai_services/tts3/?q=administration&lang=en-GB&ipa=%2F%C9%99d%CB%8Cm%C9%AAn.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=administration&lang=en-US&ipa=%2F%C9%99d%CB%8Cm%C9%AAn.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_3","topic":"Job Seeking and Work","word":"administrative","pos":"(adj)","ipa":"/ədˈmɪn.ə.strə.tɪv/","defVi":"thuộc về hành chính, quản trị","defEn":"relating to the arrangement and management of an organization or business","examples":["The university is cutting down on its [administrative] costs. (=Dịch: Trường đại học đang cắt giảm các chi phí hành chính.)","She manages all the [administrative] duties for the department. (=Dịch: Cô ấy quản lý tất cả các nhiệm vụ hành chính cho bộ phận.)","He spent the morning dealing with routine [administrative] paperwork. (=Dịch: Anh ấy đã dành cả buổi sáng để xử lý các thủ tục giấy tờ hành chính thường nhật.)"],"ukAudio":"/ai_services/tts3/?q=administrative&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.str%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=administrative&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.str%C9%99.t%C9%AAv%2F"},{"id":"lv_1_4","topic":"Job Seeking and Work","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"tham vọng, giàu hoài bão","defEn":"having a strong desire to be successful, powerful, or rich","examples":["The firm announced an [ambitious] plan to cut carbon emissions by half within five years. (=Dịch: Công ty đã công bố một kế hoạch đầy tham vọng nhằm cắt giảm một nửa lượng khí thải carbon trong vòng 5 năm.)","He is an [ambitious] young lawyer who hopes to become a partner at the firm soon. (=Dịch: Anh ấy là một luật sư trẻ đầy tham vọng, người hy vọng sẽ sớm trở thành thành viên góp vốn của công ty luật.)","Setting [ambitious] goals can inspire team members to push beyond their ordinary limits. (=Dịch: Việc đặt ra những mục tiêu đầy tham vọng có thể truyền cảm hứng cho các thành viên trong nhóm vượt qua những giới hạn thông thường.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_1_5","topic":"Job Seeking and Work","word":"applicant","pos":"(n)","ipa":"/ˈæp.lə.kənt/","defVi":"ứng viên, người nộp đơn","defEn":"a person who officially applies for a job, place at university, or legal status","examples":["Each [applicant] must submit a detailed CV and two reference letters. (=Dịch: Mỗi ứng viên phải nộp một bản CV chi tiết và hai thư giới thiệu.)","The company chose the best [applicant] after several rounds of interviews. (=Dịch: Công ty đã chọn ứng viên xuất sắc nhất sau nhiều vòng phỏng vấn.)","The scholarship is open to any [applicant] with excellent academic records. (=Dịch: Học bổng này dành cho bất kỳ ứng viên nào có thành tích học tập xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=applicant&lang=en-GB&ipa=%2F%CB%88%C3%A6p.l%C9%99.k%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=applicant&lang=en-US&ipa=%2F%CB%88%C3%A6p.l%C9%99.k%C9%99nt%2F"},{"id":"lv_1_6","topic":"Job Seeking and Work","word":"apprentice","pos":"(n)","ipa":"/əˈpren.tɪs/","defVi":"người học việc, thực tập sinh nghề","defEn":"a person who learns a job or skill by working under a skilled employer for a fixed period","examples":["He started working as an [apprentice] electrician at the age of eighteen. (=Dịch: Anh ấy bắt đầu làm thợ điện học việc vào năm mười tám tuổi.)","The master craftsman shared his traditional techniques with each [apprentice]. (=Dịch: Người thợ thủ công bậc thầy đã chia sẻ các kỹ thuật truyền thống của mình với từng người học việc.)","She joined the company through a modern [apprentice] scheme. (=Dịch: Cô ấy gia nhập công ty thông qua một chương trình học nghề hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=apprentice&lang=en-GB&ipa=%2F%C9%99%CB%88pren.t%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=apprentice&lang=en-US&ipa=%2F%C9%99%CB%88pren.t%C9%AAs%2F"},{"id":"lv_1_7","topic":"Job Seeking and Work","word":"apprenticeship","pos":"(n)","ipa":"/əˈpren.tɪs.ʃɪp/","defVi":"thời gian học nghề, sự học việc","defEn":"a period of time working for an employer to learn a practical skill or trade","examples":["He completed a three-year [apprenticeship] with an experienced master electrician. (=Dịch: Anh ấy đã hoàn thành chương trình học nghề kéo dài ba năm với một thợ điện bậc thầy giàu kinh nghiệm.)","Many young people choose an [apprenticeship] rather than attending university. (=Dịch: Nhiều người trẻ chọn học nghề thay vì vào đại học.)","The vocational program offers paid [apprenticeship] opportunities in the culinary industry. (=Dịch: Chương trình dạy nghề mang lại các cơ hội học việc có hưởng lương trong ngành ẩm thực.)"],"ukAudio":"/ai_services/tts3/?q=apprenticeship&lang=en-GB&ipa=%2F%C9%99%CB%88pren.t%C9%AAs.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=apprenticeship&lang=en-US&ipa=%2F%C9%99%CB%88pren.t%C9%AAs.%CA%83%C9%AAp%2F"},{"id":"lv_1_8","topic":"Job Seeking and Work","word":"artistic","pos":"(adj)","ipa":"/ɑːrˈtɪs.tɪk/","defVi":"thuộc nghệ thuật, có khiếu nghệ thuật","defEn":"relating to art or having natural skill in creating art","examples":["She showed great [artistic] talent from a very young age. (=Dịch: Cô ấy đã bộc lộ tài năng nghệ thuật tuyệt vời từ khi còn rất nhỏ.)","The director has a distinct [artistic] vision that makes his movies unique. (=Dịch: Đạo diễn có một tầm nhìn nghệ thuật khác biệt khiến các bộ phim của ông trở nên độc đáo.)","Students are encouraged to express their [artistic] creativity through painting and sculpture. (=Dịch: Học sinh được khuyến khích thể hiện sự sáng tạo nghệ thuật của mình thông qua hội họa và điêu khắc.)"],"ukAudio":"/ai_services/tts3/?q=artistic&lang=en-GB&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=artistic&lang=en-US&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F"},{"id":"lv_1_9","topic":"Job Seeking and Work","word":"assign","pos":"(v)","ipa":"/əˈsaɪn/","defVi":"phân công, giao phó, chỉ định","defEn":"to give someone a particular job, task, or duty","examples":["The teacher will [assign] a different reading project to each group. (=Dịch: Giáo viên sẽ giao một dự án đọc khác nhau cho mỗi nhóm.)","Management decided to [assign] the new project to their most experienced engineer. (=Dịch: Ban quản lý đã quyết định giao dự án mới cho kỹ sư giàu kinh nghiệm nhất của họ.)","Each volunteer was [assign]ed a specific role during the community event. (=Dịch: Mỗi tình nguyện viên được phân công một vai trò cụ thể trong suốt sự kiện cộng đồng.)"],"ukAudio":"/ai_services/tts3/?q=assign&lang=en-GB&ipa=%2F%C9%99%CB%88sa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=assign&lang=en-US&ipa=%2F%C9%99%CB%88sa%C9%AAn%2F"},{"id":"lv_1_10","topic":"Job Seeking and Work","word":"auditorium","pos":"(n)","ipa":"/ˌɑː.dəˈtɔːr.i.əm/","defVi":"khán phòng, hội trường","defEn":"a large room or building used for meetings, concerts, or lectures","examples":["The university [auditorium] was packed with students for the guest lecture. (=Dịch: Hội trường của trường đại học chật kín sinh viên đến nghe bài giảng của khách mời.)","The school musical will be performed in the main [auditorium] tonight. (=Dịch: Vở nhạc kịch của trường sẽ được biểu diễn tại khán phòng chính vào tối nay.)","Please proceed to the [auditorium] for the opening ceremony. (=Dịch: Xin vui lòng di chuyển đến khán phòng để tham dự lễ khai mạc.)"],"ukAudio":"/ai_services/tts3/?q=auditorium&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=auditorium&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F"},{"id":"lv_1_11","topic":"Job Seeking and Work","word":"backstage","pos":"(adv)","ipa":"/ˌbækˈsteɪdʒ/","defVi":"ở hậu trường, ở phía sau sân khấu","defEn":"in the area behind the stage in a theater, not visible to the audience","examples":["The actors waited nervously [backstage] before their cues to enter. (=Dịch: Các diễn viên hồi hộp chờ đợi ở hậu trường trước khi đến lượt bước ra sân khấu.)","Only authorized crew members are allowed to go [backstage]. (=Dịch: Chỉ những thành viên có thẩm quyền trong đoàn mới được phép vào hậu trường.)","She worked [backstage] managing the lighting and sound equipment during the show. (=Dịch: Cô ấy làm việc ở hậu trường để quản lý thiết bị âm thanh và ánh sáng trong suốt buổi biểu diễn.)"],"ukAudio":"/ai_services/tts3/?q=backstage&lang=en-GB&ipa=%2F%CB%8Cb%C3%A6k%CB%88ste%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=backstage&lang=en-US&ipa=%2F%CB%8Cb%C3%A6k%CB%88ste%C9%AAd%CA%92%2F"},{"id":"lv_1_12","topic":"Job Seeking and Work","word":"bakery","pos":"(n)","ipa":"/ˈbeɪ.kə.ri/","defVi":"tiệm bánh, lò bánh mì","defEn":"a place where bread, cakes, and other baked goods are made or sold","examples":["The sweet smell of fresh bread led us straight to the local [bakery]. (=Dịch: Mùi thơm ngọt ngào của bánh mì mới nướng đã dẫn chúng tôi đến thẳng tiệm bánh địa phương.)","She works early morning shifts at a family-owned [bakery]. (=Dịch: Cô ấy làm ca sáng sớm tại một tiệm bánh của gia đình.)","They bought a box of chocolate pastries from the corner [bakery]. (=Dịch: Họ đã mua một hộp bánh ngọt sô-cô-la từ tiệm bánh ở góc phố.)"],"ukAudio":"/ai_services/tts3/?q=bakery&lang=en-GB&ipa=%2F%CB%88be%C9%AA.k%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=bakery&lang=en-US&ipa=%2F%CB%88be%C9%AA.k%C9%99.ri%2F"},{"id":"lv_1_13","topic":"Job Seeking and Work","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh, gian/khoang riêng biệt","defEn":"a body of water partially enclosed by land, or a designated alcove/compartment","examples":["The fishing boats returned safely to the quiet [bay] before the storm hit. (=Dịch: Các thuyền đánh cá đã quay trở lại vịnh yên tĩnh an toàn trước khi cơn bão đổ bộ.)","Our hotel room offered a stunning view over the entire [bay]. (=Dịch: Phòng khách sạn của chúng tôi có tầm nhìn tuyệt đẹp ra toàn bộ vịnh.)","The mechanic drove the car into the service [bay] for an oil change. (=Dịch: Người thợ máy đã lái xe vào khoang bảo dưỡng để thay dầu.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_1_14","topic":"Job Seeking and Work","word":"boardroom","pos":"(n)","ipa":"/ˈbɔːrd.ruːm/","defVi":"phòng họp ban giám đốc, phòng họp hội đồng quản trị","defEn":"a room where the directors of a company hold their official meetings","examples":["The executives met in the [boardroom] to discuss the annual financial report. (=Dịch: Các giám đốc điều hành đã họp trong phòng họp hội đồng quản trị để thảo luận về báo cáo tài chính hàng năm.)","He gave a convincing presentation to the investors inside the [boardroom]. (=Dịch: Anh ấy đã có một bài thuyết trình đầy thuyết phục trước các nhà đầu tư bên trong phòng họp ban giám đốc.)","Important strategic decisions are usually made behind the closed doors of the [boardroom]. (=Dịch: Những quyết định chiến lược quan trọng thường được đưa ra sau những cánh cửa đóng kín của phòng họp hội đồng quản trị.)"],"ukAudio":"/ai_services/tts3/?q=boardroom&lang=en-GB&ipa=%2F%CB%88b%C9%94%CB%90rd.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=boardroom&lang=en-US&ipa=%2F%CB%88b%C9%94%CB%90rd.ru%CB%90m%2F"},{"id":"lv_1_15","topic":"Job Seeking and Work","word":"booklet","pos":"(n)","ipa":"/ˈbʊk.lət/","defVi":"cuốn sách nhỏ, tập tài liệu mỏng","defEn":"a small, thin book with paper covers that contains information about a specific topic","examples":["The tourist center distributes a free [booklet] featuring local attractions. (=Dịch: Trung tâm du lịch phát miễn phí một cuốn sách nhỏ giới thiệu các điểm tham quan địa phương.)","Read the instruction [booklet] carefully before operating the device. (=Dịch: Hãy đọc kỹ cuốn sách hướng dẫn nhỏ trước khi vận hành thiết bị.)","The university prepared an informative [booklet] for incoming students. (=Dịch: Trường đại học đã chuẩn bị một cuốn sổ tay nhiều thông tin bổ ích cho tân sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=booklet&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=booklet&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.l%C9%99t%2F"},{"id":"lv_1_16","topic":"Job Seeking and Work","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, nhà sách","defEn":"a shop that sells books","examples":["He spent hours browsing through old novels in the secondhand [bookshop]. (=Dịch: Anh ấy đã dành hàng giờ lướt xem những cuốn tiểu thuyết cũ trong hiệu sách cũ.)","A new independent [bookshop] just opened near the university campus. (=Dịch: Một hiệu sách độc lập mới vừa mở gần khuôn viên trường đại học.)","You can purchase the recommended course material at the campus [bookshop]. (=Dịch: Bạn có thể mua tài liệu học tập được khuyến nghị tại hiệu sách của trường.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_1_17","topic":"Job Seeking and Work","word":"brochure","pos":"(n)","ipa":"/broʊˈʃʊr/","defVi":"tờ gấp giới thiệu, tập tài liệu quảng cáo","defEn":"a small booklet containing pictures and information about a product or service","examples":["The travel agency handed out a colorful [brochure] about tours in Europe. (=Dịch: Công ty du lịch đã phát một cuốn tài liệu quảng cáo đầy màu sắc về các chuyến du lịch ở châu Âu.)","You can find full details of the university courses in this [brochure]. (=Dịch: Bạn có thể tìm thấy thông tin chi tiết đầy đủ về các khóa học đại học trong cuốn tài liệu giới thiệu này.)","We picked up a museum [brochure] at the entrance desk. (=Dịch: Chúng tôi đã lấy một cuốn tài liệu giới thiệu bảo tàng ở quầy lối vào.)"],"ukAudio":"/ai_services/tts3/?q=brochure&lang=en-GB&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=brochure&lang=en-US&ipa=%2Fbro%CA%8A%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_1_18","topic":"Job Seeking and Work","word":"buffet","pos":"(n)","ipa":"/bəˈfeɪ/","defVi":"bữa ăn tự chọn, tiệc đứng (buffet)","defEn":"a meal where people serve themselves from a table containing various dishes","examples":["The hotel offers a breakfast [buffet] with both hot and cold options. (=Dịch: Khách sạn phục vụ tiệc buffet bữa sáng với cả các món nóng và lạnh.)","We decided to have a seafood [buffet] for our anniversary dinner. (=Dịch: Chúng tôi quyết định ăn tiệc buffet hải sản cho bữa tối kỷ niệm ngày cưới.)","Guests can choose whatever they like from the dessert [buffet]. (=Dịch: Khách có thể chọn bất kỳ món nào họ thích từ quầy buffet tráng miệng.)"],"ukAudio":"/ai_services/tts3/?q=buffet&lang=en-GB&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=buffet&lang=en-US&ipa=%2Fb%C9%99%CB%88fe%C9%AA%2F"},{"id":"lv_1_19","topic":"Job Seeking and Work","word":"buyer","pos":"(n)","ipa":"/ˈbaɪ.ər/","defVi":"người mua hàng, nhân viên thu mua","defEn":"a person who buys goods or services, or someone employed by a company to choose and purchase stock","examples":["The real estate agent finally found a serious [buyer] for the luxury villa. (=Dịch: Môi giới bất động sản cuối cùng đã tìm được một người mua nghiêm túc cho căn biệt thự sang trọng.)","She works as a fashion [buyer] for a major department store chain. (=Dịch: Cô ấy làm nhân viên thu mua thời trang cho một chuỗi cửa hàng bách hóa lớn.)","Potential [buyer] interest increased significantly after the price was reduced. (=Dịch: Sự quan tâm của người mua tiềm năng đã tăng lên đáng kể sau khi giá được giảm.)"],"ukAudio":"/ai_services/tts3/?q=buyer&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=buyer&lang=en-US&ipa=%2F%CB%88ba%C9%AA.%C9%99r%2F"},{"id":"lv_1_20","topic":"Job Seeking and Work","word":"cancel","pos":"(v)","ipa":"/ˈkæn.səl/","defVi":"hủy bỏ","defEn":"to decide that an organized event or agreement will not happen","examples":["They had to [cancel] the flight due to severe weather conditions. (=Dịch: Họ đã phải hủy chuyến bay do điều kiện thời tiết khắc nghiệt.)","You can [cancel] your subscription at any time without extra fees. (=Dịch: Bạn có thể hủy gói đăng ký bất cứ lúc nào mà không mất thêm phí.)","The school decided to [cancel] all outdoor sports events for the day. (=Dịch: Nhà trường quyết định hủy toàn bộ các sự kiện thể thao ngoài trời trong ngày.)"],"ukAudio":"/ai_services/tts3/?q=cancel&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cancel&lang=en-US&ipa=%2F%CB%88k%C3%A6n.s%C9%99l%2F"},{"id":"lv_1_21","topic":"Job Seeking and Work","word":"candidate","pos":"(n)","ipa":"/ˈkæn.də.dət/","defVi":"ứng viên, người dự tuyển","defEn":"a person who applies for a job or competes in an election","examples":["She was considered the most qualified [candidate] for the marketing manager position. (=Dịch: Cô ấy được xem là ứng viên có đủ năng lực nhất cho vị trí trưởng phòng tiếp thị.)","Each [candidate] must undergo two rounds of interviews before being hired. (=Dịch: Mỗi ứng viên phải trải qua hai vòng phỏng vấn trước khi được tuyển dụng.)","The political [candidate] gave a compelling speech to win over undecided voters. (=Dịch: Ứng cử viên chính trị đã có một bài phát biểu thuyết phục để thu hút những cử tri còn chưa quyết định.)"],"ukAudio":"/ai_services/tts3/?q=candidate&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.d%C9%99.d%C9%99t%2F","usAudio":"/ai_services/tts3/?q=candidate&lang=en-US&ipa=%2F%CB%88k%C3%A6n.d%C9%99.d%C9%99t%2F"},{"id":"lv_1_22","topic":"Job Seeking and Work","word":"casual","pos":"(adj)","ipa":"/ˈkæʒ.u.əl/","defVi":"bình thường, thoải mái, không trang trọng","defEn":"relaxed, informal, or not planned in advance","examples":["Employees are permitted to wear [casual] clothes on Fridays. (=Dịch: Nhân viên được phép mặc trang phục thường ngày vào các ngày thứ Sáu.)","We had a [casual] conversation over coffee about our weekend plans. (=Dịch: Chúng tôi đã có một cuộc trò chuyện thoải mái bên tách cà phê về các kế hoạch cuối tuần.)","He made a [casual] remark that unexpectedly inspired a whole new project. (=Dịch: Anh ấy đã đưa ra một lời nhận xét bâng quơ nhưng lại bất ngờ truyền cảm hứng cho cả một dự án hoàn toàn mới.)"],"ukAudio":"/ai_services/tts3/?q=casual&lang=en-GB&ipa=%2F%CB%88k%C3%A6%CA%92.u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=casual&lang=en-US&ipa=%2F%CB%88k%C3%A6%CA%92.u.%C9%99l%2F"},{"id":"lv_1_23","topic":"Job Seeking and Work","word":"cautious","pos":"(adj)","ipa":"/ˈkɑː.ʃəs/","defVi":"thận trọng, cẩn trọng","defEn":"careful to avoid potential problems or dangers","examples":["Investors are advised to be [cautious] when trading in volatile stock markets. (=Dịch: Các nhà đầu tư được khuyên nên thận trọng khi giao dịch trên các thị trường chứng khoán nhiều biến động.)","He took a [cautious] approach and verified every single piece of data before publishing. (=Dịch: Anh ấy đã áp dụng một cách tiếp cận thận trọng và xác minh từng dữ liệu một trước khi công bố.)","The driver was extremely [cautious] on the icy mountain roads. (=Dịch: Người tài xế đã cực kỳ cẩn thận khi lái xe trên những con đường núi đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=cautious&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=cautious&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.%CA%83%C9%99s%2F"},{"id":"lv_1_24","topic":"Job Seeking and Work","word":"certificate","pos":"(n)","ipa":"/sɚˈtɪf.ə.kət/","defVi":"chứng chỉ, giấy chứng nhận","defEn":"an official document that states facts or achievements","examples":["She received a [certificate] in project management after completing the course. (=Dịch: Cô ấy đã nhận được chứng chỉ quản lý dự án sau khi hoàn thành khóa học.)","You must present a medical [certificate] to explain your absence. (=Dịch: Bạn phải xuất trình giấy chứng nhận y tế để giải thích cho sự vắng mặt của mình.)","The school issues a graduation [certificate] to all qualifying students. (=Dịch: Nhà trường cấp giấy chứng nhận tốt nghiệp cho tất cả học sinh đủ điều kiện.)"],"ukAudio":"/ai_services/tts3/?q=certificate&lang=en-GB&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F","usAudio":"/ai_services/tts3/?q=certificate&lang=en-US&ipa=%2Fs%C9%9A%CB%88t%C9%AAf.%C9%99.k%C9%99t%2F"},{"id":"lv_1_25","topic":"Job Seeking and Work","word":"checking","pos":"(n)","ipa":"/ˈtʃek.ɪŋ/","defVi":"việc kiểm tra, sự rà soát, đối chiếu","defEn":"the act of inspecting, examining, or verifying something","examples":["Careful [checking] of the financial documents helped reveal the error. (=Dịch: Việc kiểm tra cẩn thận các tài liệu tài chính đã giúp phát hiện ra sai sót.)","The airport instituted stricter security [checking] during the holiday season. (=Dịch: Sân bay đã áp dụng quy trình kiểm tra an ninh nghiêm ngặt hơn trong mùa nghỉ lễ.)","Routine [checking] of the machinery prevents unexpected breakdowns. (=Dịch: Việc kiểm tra máy móc định kỳ giúp ngăn ngừa những sự cố hỏng hóc bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=checking&lang=en-GB&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=checking&lang=en-US&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F"},{"id":"lv_1_26","topic":"Job Seeking and Work","word":"clerical","pos":"(adj)","ipa":"/ˈkler.ɪ.kəl/","defVi":"thuộc công việc văn phòng, hành chính","defEn":"relating to office work such as typing, filing, and record-keeping","examples":["She applied for a [clerical] position at a local law firm. (=Dịch: Cô ấy đã nộp đơn ứng tuyển vào một vị trí văn phòng tại một công ty luật địa phương.)","A minor [clerical] error caused a significant delay in the shipment. (=Dịch: Một lỗi hành chính nhỏ đã gây ra sự chậm trễ đáng kể cho chuyến hàng.)","He spent his first year doing routine [clerical] tasks. (=Dịch: Anh ấy đã dành năm đầu tiên để làm những công việc văn phòng thường nhật.)"],"ukAudio":"/ai_services/tts3/?q=clerical&lang=en-GB&ipa=%2F%CB%88kler.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=clerical&lang=en-US&ipa=%2F%CB%88kler.%C9%AA.k%C9%99l%2F"},{"id":"lv_1_27","topic":"Job Seeking and Work","word":"commitment","pos":"(n)","ipa":"/kəˈmɪt.mənt/","defVi":"sự cam kết, sự tận tụy, trách nhiệm","defEn":"a promise or firm decision to do something, or loyalty and dedication to a cause","examples":["The company demonstrated its [commitment] to quality by improving safety standards. (=Dịch: Công ty đã thể hiện cam kết về chất lượng bằng cách cải thiện các tiêu chuẩn an toàn.)","Balancing family life and work [commitment] can be challenging for many parents. (=Dịch: Cân bằng giữa cuộc sống gia đình và trách nhiệm công việc có thể là một thử thách đối với nhiều bậc cha mẹ.)","Learning a musical instrument requires a serious long-term [commitment]. (=Dịch: Học một nhạc cụ đòi hỏi sự gắn bó và nỗ lực nghiêm túc lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=commitment&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=commitment&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.m%C9%99nt%2F"},{"id":"lv_1_28","topic":"Job Seeking and Work","word":"confusion","pos":"(n)","ipa":"/kənˈfjuː.ʒən/","defVi":"sự bối rối, sự nhầm lẫn, tình trạng hỗn loạn","defEn":"a state of not understanding something clearly or a situation that is disorderly","examples":["There was some [confusion] about the exact time of the meeting. (=Dịch: Đã có một sự nhầm lẫn về thời gian chính xác của cuộc họp.)","His instructions caused great [confusion] among the new workers. (=Dịch: Các hướng dẫn của anh ấy đã gây ra sự bối rối lớn cho những công nhân mới.)","The sudden power outage led to [confusion] in the shopping mall. (=Dịch: Sự cố mất điện đột ngột đã dẫn đến tình trạng hỗn loạn trong trung tâm thương mại.)"],"ukAudio":"/ai_services/tts3/?q=confusion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=confusion&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_1_29","topic":"Job Seeking and Work","word":"contract","pos":"(n)","ipa":"/ˈkɑːn.trækt/","defVi":"hợp đồng, giao kèo","defEn":"a legal written agreement between two or more people or organizations","examples":["Please read the terms carefully before signing the employment [contract]. (=Dịch: Vui lòng đọc kỹ các điều khoản trước khi ký hợp đồng lao động.)","The company won a major [contract] to build a new bridge. (=Dịch: Công ty đã giành được một hợp đồng lớn để xây dựng một cây cầu mới.)","Breaking the [contract] early will result in financial penalties. (=Dịch: Việc phá vỡ hợp đồng sớm sẽ dẫn đến các khoản phạt tài chính.)"],"ukAudio":"/ai_services/tts3/?q=contract&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=contract&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.tr%C3%A6kt%2F"},{"id":"lv_1_30","topic":"Job Seeking and Work","word":"cooler","pos":"(n)","ipa":"/ˈkuː.lɚ/","defVi":"thùng giữ lạnh, thiết bị làm mát","defEn":"an insulated container or device used to keep things, especially food or drinks, cold","examples":["We packed several bottles of water and sandwiches in the [cooler] for our picnic. (=Dịch: Chúng tôi đã đóng gói vài chai nước và bánh mì kẹp vào thùng giữ nhiệt cho chuyến dã ngoại.)","Don't forget to put fresh ice in the [cooler] before we head to the beach. (=Dịch: Đừng quên cho thêm đá mới vào thùng giữ nhiệt trước khi chúng ta ra bãi biển.)","The workers gathered around the water [cooler] to chat during their break. (=Dịch: Các công nhân tụ tập quanh bình nước nóng lạnh để trò chuyện trong giờ giải lao.)"],"ukAudio":"/ai_services/tts3/?q=cooler&lang=en-GB&ipa=%2F%CB%88ku%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cooler&lang=en-US&ipa=%2F%CB%88ku%CB%90.l%C9%9A%2F"},{"id":"lv_1_31","topic":"Job Seeking and Work","word":"corridor","pos":"(n)","ipa":"/ˈkɔːr.ə.dɚ/","defVi":"hành lang","defEn":"a long narrow passage in a building with doors leading into rooms","examples":["His office is located at the very end of the second-floor [corridor]. (=Dịch: Văn phòng của ông ấy nằm ở tận cuối hành lang tầng hai.)","Students are reminded not to run in the school [corridor]. (=Dịch: Học sinh được nhắc nhở không chạy nhảy trong hành lang trường học.)","The hotel [corridor] was quiet and lined with soft carpeting. (=Dịch: Hành lang khách sạn rất yên tĩnh và được trải thảm mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=corridor&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=corridor&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F"},{"id":"lv_1_32","topic":"Job Seeking and Work","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục, đồ hóa trang","defEn":"a set of clothes worn by an actor or for a special occasion or party","examples":["The actors wore elaborate period [costumes] for the historical drama. (=Dịch: Các diễn viên đã mặc những bộ trang phục cổ trang công phu cho bộ phim lịch sử.)","He won the first prize for the best Halloween [costume] at the party. (=Dịch: Anh ấy đã giành giải nhất cho bộ trang phục Halloween đẹp nhất tại bữa tiệc.)","The designer spent months researching traditional [costumes] for the dance performance. (=Dịch: Nhà thiết kế đã dành nhiều tháng nghiên cứu các trang phục truyền thống cho buổi biểu diễn múa.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_1_33","topic":"Job Seeking and Work","word":"counter","pos":"(n)","ipa":"/ˈkaʊn.tər/","defVi":"quầy thu ngân, quầy phục vụ, mặt bàn bếp","defEn":"a flat surface over which business is conducted, such as in a bank, shop, or kitchen","examples":["Please leave your keys on the reception [counter] when you check out. (=Dịch: Vui lòng để lại chìa khóa trên quầy lễ tân khi bạn trả phòng.)","The bakery displayed fresh bread behind the glass [counter]. (=Dịch: Tiệm bánh trưng bày bánh mì tươi phía sau quầy kính.)","Wipe down the kitchen [counter] thoroughly after preparing food. (=Dịch: Hãy lau chùi kỹ mặt bàn bếp sau khi chuẩn bị thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=counter&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=counter&lang=en-US&ipa=%2F%CB%88ka%CA%8An.t%C9%99r%2F"},{"id":"lv_1_34","topic":"Job Seeking and Work","word":"courtyard","pos":"(n)","ipa":"/ˈkɔːrt.jɑːrd/","defVi":"sân trong, khoảng sân có tường hoặc nhà bao quanh","defEn":"an open area of ground surrounded by walls or buildings","examples":["The hotel has a charming central [courtyard] filled with flowers and fountains. (=Dịch: Khách sạn có một khoảng sân trung tâm quyến rũ ngập tràn hoa và đài phun nước.)","Students often sit in the [courtyard] to study and enjoy the fresh air. (=Dịch: Sinh viên thường ngồi ở sân trong để học bài và tận hưởng không khí trong lành.)","The ancient palace was built around a spacious stone [courtyard]. (=Dịch: Cung điện cổ kính được xây dựng xung quanh một khoảng sân đá rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=courtyard&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=courtyard&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F"},{"id":"lv_1_35","topic":"Job Seeking and Work","word":"disposal","pos":"(n)","ipa":"/dɪˈspoʊ.zəl/","defVi":"sự vứt bỏ, sự xử lý","defEn":"the act of getting rid of something","examples":["The safe [disposal] of chemical waste is crucial for the environment. (=Dịch: Việc xử lý an toàn chất thải hóa học là vô cùng quan trọng đối với môi trường.)","A car was put at our [disposal] during the business trip. (=Dịch: Một chiếc xe hơi đã được bố trí sẵn cho chúng tôi sử dụng trong suốt chuyến công tác.)","The city introduced new rules for domestic rubbish [disposal]. (=Dịch: Thành phố đã ban hành các quy định mới về việc xử lý rác thải sinh hoạt.)"],"ukAudio":"/ai_services/tts3/?q=disposal&lang=en-GB&ipa=%2Fd%C9%AA%CB%88spo%CA%8A.z%C9%99l%2F","usAudio":"/ai_services/tts3/?q=disposal&lang=en-US&ipa=%2Fd%C9%AA%CB%88spo%CA%8A.z%C9%99l%2F"},{"id":"lv_1_36","topic":"Job Seeking and Work","word":"diversity","pos":"(n)","ipa":"/daɪˈvɝː.sə.t̬i/","defVi":"sự đa dạng, sự phong phú","defEn":"the state of having many different types, ideas, or people included","examples":["Cultural [diversity] enriches society by introducing new perspectives and traditions. (=Dịch: Sự đa dạng văn hóa làm phong phú xã hội bằng cách mang lại những góc nhìn và truyền thống mới.)","The university promotes [diversity] by admitting students from various backgrounds. (=Dịch: Trường đại học thúc đẩy sự đa dạng bằng cách tiếp nhận sinh viên từ nhiều hoàn cảnh khác nhau.)","The rainforest is famous for its rich biological [diversity]. (=Dịch: Rừng mưa nhiệt đới nổi tiếng với sự đa dạng sinh học phong phú.)"],"ukAudio":"/ai_services/tts3/?q=diversity&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=diversity&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_1_37","topic":"Job Seeking and Work","word":"dramatic","pos":"(adj)","ipa":"/drəˈmæt̬.ɪk/","defVi":"đột ngột, đáng kể, kịch tính","defEn":"sudden, very great, and often surprising","examples":["There was a [dramatic] increase in sales last month. (=Dịch: Doanh số tháng trước đã tăng lên một cách đáng kể.)","The new policy brought about a [dramatic] change in the company's culture. (=Dịch: Chính sách mới đã mang lại một sự thay đổi sâu sắc trong văn hóa của công ty.)","She gave a [dramatic] sigh to show her disappointment. (=Dịch: Cô ấy thở dài một cách đầy kịch tính để thể hiện sự thất vọng của mình.)"],"ukAudio":"/ai_services/tts3/?q=dramatic&lang=en-GB&ipa=%2Fdr%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dramatic&lang=en-US&ipa=%2Fdr%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_1_38","topic":"Job Seeking and Work","word":"duty","pos":"(n)","ipa":"/ˈduː.t̬i/","defVi":"bổn phận, trách nhiệm, nhiệm vụ","defEn":"a moral or legal obligation; a task that is part of a person's job","examples":["Every citizen has a civic [duty] to vote in the national elections. (=Dịch: Mỗi công dân đều có nghĩa vụ công dân là đi bỏ phiếu trong các cuộc bầu cử quốc gia.)","Taking care of customer complaints is part of his daily [duty]. (=Dịch: Giải quyết các khiếu nại của khách hàng là một phần trong nhiệm vụ hằng ngày của anh ấy.)","Doctors feel a strong sense of [duty] toward their patients. (=Dịch: Các bác sĩ cảm nhận được tinh thần trách nhiệm sâu sắc đối với bệnh nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=duty&lang=en-GB&ipa=%2F%CB%88du%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=duty&lang=en-US&ipa=%2F%CB%88du%CB%90.t%CC%ACi%2F"},{"id":"lv_1_39","topic":"Job Seeking and Work","word":"enquire","pos":"(v)","ipa":"/ɪnˈkwaɪ.ɚ/","defVi":"hỏi thăm, dò hỏi","defEn":"to ask for information about something","examples":["I called the hotel to [enquire] about room availability for the weekend. (=Dịch: Tôi đã gọi điện đến khách sạn để hỏi về tình trạng phòng trống vào cuối tuần.)","She stopped at the reception desk to [enquire] the way to the conference hall. (=Dịch: Cô ấy dừng lại ở quầy lễ tân để hỏi đường đến hội trường.)","Prospective students often [enquire] about tuition fees and scholarship options. (=Dịch: Các sinh viên tương lai thường hỏi về học phí và các chương trình học bổng.)"],"ukAudio":"/ai_services/tts3/?q=enquire&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=enquire&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%9A%2F"},{"id":"lv_1_40","topic":"Job Seeking and Work","word":"enquiry","pos":"(n)","ipa":"/ɪnˈkwaɪ.ə.ri/","defVi":"sự yêu cầu thông tin, câu hỏi thắc mắc hoặc cuộc điều tra","defEn":"an act of asking for information or an official investigation","examples":["I sent an email [enquiry] to the hotel regarding their room rates. (=Dịch: Tôi đã gửi một email thắc mắc đến khách sạn để hỏi về giá phòng của họ.)","The customer service desk handles every [enquiry] quickly and politely. (=Dịch: Bàn dịch vụ khách hàng giải quyết mọi thắc mắc một cách nhanh chóng và lịch sự.)","The government launched a formal [enquiry] into the causes of the train crash. (=Dịch: Chính phủ đã mở một cuộc điều tra chính thức về nguyên nhân của vụ tai nạn tàu hỏa.)"],"ukAudio":"/ai_services/tts3/?q=enquiry&lang=en-GB&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=enquiry&lang=en-US&ipa=%2F%C9%AAn%CB%88kwa%C9%AA.%C9%99.ri%2F"},{"id":"lv_1_41","topic":"Job Seeking and Work","word":"exit","pos":"(v)","ipa":"/ˈɛɡ.zɪt/","defVi":"rời khỏi, đi ra khỏi","defEn":"to go out of or leave a place or situation","examples":["Passengers should [exit] the bus through the rear door. (=Dịch: Hành khách nên xuống xe buýt bằng cửa sau.)","Please do not [exit] the building until the fire drill is over. (=Dịch: Vui lòng không rời khỏi tòa nhà cho đến khi buổi diễn tập phòng cháy chữa cháy kết thúc.)","The speaker chose to [exit] the stage immediately after answering the final question. (=Dịch: Diễn giả đã quyết định rời khỏi sân khấu ngay sau khi trả lời câu hỏi cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=exit&lang=en-GB&ipa=%2F%CB%88%C9%9B%C9%A1.z%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exit&lang=en-US&ipa=%2F%CB%88%C9%9B%C9%A1.z%C9%AAt%2F"},{"id":"lv_1_42","topic":"Job Seeking and Work","word":"foyer","pos":"(n)","ipa":"/ˈfɔɪ.ɚ/","defVi":"tiền sảnh, sảnh chờ","defEn":"a large open area near the entrance inside a building, such as a hotel or theater","examples":["We arranged to meet our friends in the theater [foyer] before the show. (=Dịch: Chúng tôi đã hẹn gặp bạn bè ở sảnh nhà hát trước giờ biểu diễn.)","The hotel [foyer] was decorated with modern art and large plants. (=Dịch: Sảnh khách sạn được trang trí bằng các tác phẩm nghệ thuật hiện đại và những chậu cây lớn.)","Guests waited in the spacious [foyer] until the conference hall doors opened. (=Dịch: Các vị khách đã chờ ở sảnh lớn rộng rãi cho đến khi cửa phòng hội nghị mở ra.)"],"ukAudio":"/ai_services/tts3/?q=foyer&lang=en-GB&ipa=%2F%CB%88f%C9%94%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=foyer&lang=en-US&ipa=%2F%CB%88f%C9%94%C9%AA.%C9%9A%2F"},{"id":"lv_1_43","topic":"Job Seeking and Work","word":"gender","pos":"(n)","ipa":"/ˈdʒen.dɚ/","defVi":"giới tính","defEn":"the state of being male or female, especially when considered in relation to social and cultural factors","examples":["The survey includes questions about age, [gender], and occupation. (=Dịch: Cuộc khảo sát bao gồm các câu hỏi về độ tuổi, giới tính và nghề nghiệp.)","Efforts are being made to eliminate the [gender] pay gap. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm xóa bỏ khoảng cách chênh lệch tiền lương theo giới tính.)","She conducts research on [gender] equality in the workplace. (=Dịch: Cô ấy tiến hành nghiên cứu về bình đẳng giới tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=gender&lang=en-GB&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gender&lang=en-US&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F"},{"id":"lv_1_44","topic":"Job Seeking and Work","word":"heavily","pos":"(adv)","ipa":"/ˈhev.ə.li/","defVi":"nặng nề, một cách nghiêm trọng hoặc với số lượng lớn","defEn":"to a great degree; in large amounts or with a lot of weight/force","examples":["It was raining [heavily], so we decided to stay indoors. (=Dịch: Trời mưa rất to, vì vậy chúng tôi quyết định ở trong nhà.)","The company relies [heavily] on digital marketing to attract new clients. (=Dịch: Công ty phụ thuộc rất nhiều vào tiếp thị kỹ thuật số để thu hút khách hàng mới.)","She sighed [heavily] before delivering the disappointing news. (=Dịch: Cô ấy thở dài nặng nề trước khi thông báo tin tức đáng thất vọng.)"],"ukAudio":"/ai_services/tts3/?q=heavily&lang=en-GB&ipa=%2F%CB%88hev.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=heavily&lang=en-US&ipa=%2F%CB%88hev.%C9%99.li%2F"},{"id":"lv_1_45","topic":"Job Seeking and Work","word":"hr","pos":"(n)","ipa":"/ˌeɪtʃˈɑːr/","defVi":"bộ phận nhân sự, ngành nhân sự","defEn":"the department in an organization dealing with hiring, training, and employee welfare","examples":["You need to submit your leave request to [HR] by the end of the week. (=Dịch: Bạn cần gửi đơn xin nghỉ phép đến phòng nhân sự trước cuối tuần này.)","The [HR] manager will conduct the first round of job interviews tomorrow. (=Dịch: Trưởng phòng nhân sự sẽ tiến hành vòng phỏng vấn xin việc đầu tiên vào ngày mai.)","She decided to pursue a career in [HR] because she enjoys working with people. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp trong ngành nhân sự vì thích làm việc với con người.)"],"ukAudio":"/ai_services/tts3/?q=hr&lang=en-GB&ipa=%2F%CB%8Ce%C9%AAt%CA%83%CB%88%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=hr&lang=en-US&ipa=%2F%CB%8Ce%C9%AAt%CA%83%CB%88%C9%91%CB%90r%2F"},{"id":"lv_1_46","topic":"Job Seeking and Work","word":"immediate","pos":"(adj)","ipa":"/ɪˈmiː.di.ət/","defVi":"ngay lập tức, trực tiếp, trước mắt","defEn":"happening or done without delay; nearest in time, relationship, or space","examples":["The patient requires [immediate] medical attention after the accident. (=Dịch: Bệnh nhân cần được chăm sóc y tế ngay lập tức sau vụ tai nạn.)","Our [immediate] goal is to finish the project before the deadline. (=Dịch: Mục tiêu trước mắt của chúng tôi là hoàn thành dự án trước thời hạn.)","The decision had an [immediate] effect on the stock market. (=Dịch: Quyết định này đã có tác động ngay lập tức lên thị trường chứng khoán.)"],"ukAudio":"/ai_services/tts3/?q=immediate&lang=en-GB&ipa=%2F%C9%AA%CB%88mi%CB%90.di.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=immediate&lang=en-US&ipa=%2F%C9%AA%CB%88mi%CB%90.di.%C9%99t%2F"},{"id":"lv_1_47","topic":"Job Seeking and Work","word":"incentive","pos":"(n)","ipa":"/ɪnˈsɛn.tɪv/","defVi":"sự khích lệ, động lực, phần thưởng khuyến khích","defEn":"something that encourages a person to do something or work harder","examples":["The company offers a cash [incentive] for employees who reach their sales targets. (=Dịch: Công ty đưa ra một khoản tiền thưởng khích lệ cho những nhân viên đạt chỉ tiêu doanh số.)","Tax cuts provide an [incentive] for local businesses to invest in new equipment. (=Dịch: Việc cắt giảm thuế tạo động lực cho các doanh nghiệp địa phương đầu tư vào trang thiết bị mới.)","There is little [incentive] for students to study hard if the tests are too easy. (=Dịch: Học sinh có rất ít động lực để học chăm chỉ nếu các bài kiểm tra quá dễ.)"],"ukAudio":"/ai_services/tts3/?q=incentive&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%9Bn.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=incentive&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%9Bn.t%C9%AAv%2F"},{"id":"lv_1_48","topic":"Job Seeking and Work","word":"inclusion","pos":"(n)","ipa":"/ɪnˈkluː.ʒən/","defVi":"sự hòa nhập, sự bao gồm, sự tính cả vào","defEn":"the practice of including people from all backgrounds, or the act of adding something into a group","examples":["The school promotes social [inclusion] for children with special needs. (=Dịch: Nhà trường thúc đẩy sự hòa nhập xã hội cho trẻ em có nhu cầu đặc biệt.)","His [inclusion] in the national football squad surprised many fans. (=Dịch: Việc anh ấy có tên trong danh sách đội tuyển bóng đá quốc gia đã khiến nhiều người hâm mộ bất ngờ.)","Diversity and [inclusion] policies have become essential in modern workplaces. (=Dịch: Các chính sách về đa dạng và hòa nhập đã trở nên thiết yếu tại các nơi làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=inclusion&lang=en-GB&ipa=%2F%C9%AAn%CB%88klu%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=inclusion&lang=en-US&ipa=%2F%C9%AAn%CB%88klu%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_1_49","topic":"Job Seeking and Work","word":"indigenous","pos":"(adj)","ipa":"/ɪnˈdɪdʒ.ə.nəs/","defVi":"bản địa, bản xứ","defEn":"originating or occurring naturally in a particular place; native","examples":["The kangaroo is [indigenous] to Australia. (=Dịch: Chuột túi là loài bản địa của Úc.)","Researchers are working to preserve [indigenous] languages and traditions. (=Dịch: Các nhà nghiên cứu đang nỗ lực bảo tồn các ngôn ngữ và truyền thống bản địa.)","This plant is [indigenous] to tropical rainforests and cannot survive cold winters. (=Dịch: Loài cây này có nguồn gốc bản địa từ các khu rừng mưa nhiệt đới và không thể sống sót qua mùa đông lạnh giá.)"],"ukAudio":"/ai_services/tts3/?q=indigenous&lang=en-GB&ipa=%2F%C9%AAn%CB%88d%C9%AAd%CA%92.%C9%99.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=indigenous&lang=en-US&ipa=%2F%C9%AAn%CB%88d%C9%AAd%CA%92.%C9%99.n%C9%99s%2F"},{"id":"lv_1_50","topic":"Job Seeking and Work","word":"install","pos":"(v)","ipa":"/ɪnˈstɑːl/","defVi":"lắp đặt, cài đặt","defEn":"to put a piece of equipment or software in place so that it is ready for use","examples":["A technician came to [install] the new air conditioner yesterday. (=Dịch: Hôm qua một kỹ thuật viên đã đến để lắp đặt chiếc máy điều hòa mới.)","You need to [install] the latest software updates to keep your phone secure. (=Dịch: Bạn cần cài đặt các bản cập nhật phần mềm mới nhất để giữ an toàn cho điện thoại của mình.)","The city plans to [install] more solar-powered streetlights this year. (=Dịch: Thành phố có kế hoạch lắp đặt thêm đèn đường chạy bằng năng lượng mặt trời trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=install&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=install&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_1_51","topic":"Job Seeking and Work","word":"interfere","pos":"(v)","ipa":"/ˌɪn.t̬ɚˈfɪr/","defVi":"can thiệp, can dự, làm phiền","defEn":"to get involved in a situation where you are not wanted or needed","examples":["Noise from the construction site began to [interfere] with our studies. (=Dịch: Tiếng ồn từ công trường xây dựng bắt đầu gây ảnh hưởng đến việc học của chúng tôi.)","Parents should support their children but not [interfere] in all their choices. (=Dịch: Cha mẹ nên hỗ trợ con cái nhưng không nên can thiệp vào mọi lựa chọn của chúng.)","Strong emotions can sometimes [interfere] with rational decision-making. (=Dịch: Những cảm xúc mãnh liệt đôi khi có thể cản trở việc đưa ra quyết định hợp lý.)"],"ukAudio":"/ai_services/tts3/?q=interfere&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=interfere&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F"},{"id":"lv_1_52","topic":"Job Seeking and Work","word":"internal","pos":"(adj)","ipa":"/ɪnˈtɜːr.nəl/","defVi":"nội bộ, bên trong","defEn":"located inside something, or happening within an organization or country","examples":["The company conducted an [internal] audit to evaluate its accounting practices. (=Dịch: Công ty đã tiến hành một cuộc kiểm toán nội bộ để đánh giá các hoạt động kế toán của mình.)","Regular exercise helps protect your [internal] organs from various diseases. (=Dịch: Tập thể dục thường xuyên giúp bảo vệ các cơ quan nội tạng của bạn khỏi nhiều bệnh tật.)","Management resolved the dispute through an [internal] discussion. (=Dịch: Ban quản lý đã giải quyết tranh chấp thông qua một cuộc thảo luận nội bộ.)"],"ukAudio":"/ai_services/tts3/?q=internal&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9C%CB%90r.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=internal&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9C%CB%90r.n%C9%99l%2F"},{"id":"lv_1_53","topic":"Job Seeking and Work","word":"interpersonal","pos":"(adj)","ipa":"/ˌɪn.t̬ɚˈpɝː.sən.əl/","defVi":"giữa các cá nhân, giao tiếp ứng xử","defEn":"connected with relationships between people","examples":["Strong [interpersonal] skills are essential for effective team leaders. (=Dịch: Kỹ năng giao tiếp ứng xử tốt là điều cần thiết đối với những người lãnh đạo nhóm hiệu quả.)","The course helps students improve their [interpersonal] communication. (=Dịch: Khóa học giúp sinh viên cải thiện khả năng giao tiếp giữa các cá nhân.)","Workplace conflicts often stem from poor [interpersonal] dynamics. (=Dịch: Các mâu thuẫn tại nơi làm việc thường bắt nguồn từ mối quan hệ tương tác kém giữa các cá nhân.)"],"ukAudio":"/ai_services/tts3/?q=interpersonal&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88p%C9%9D%CB%90.s%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=interpersonal&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88p%C9%9D%CB%90.s%C9%99n.%C9%99l%2F"},{"id":"lv_1_54","topic":"Job Seeking and Work","word":"investment","pos":"(n)","ipa":"/ɪnˈvest.mənt/","defVi":"sự đầu tư, khoản đầu tư","defEn":"the act of putting money, effort, or time into something to gain a profit or benefit","examples":["Buying a home is often the largest financial [investment] a family will make. (=Dịch: Mua nhà thường là khoản đầu tư tài chính lớn nhất mà một gia đình thực hiện.)","The government announced a major [investment] in renewable energy infrastructure. (=Dịch: Chính phủ đã công bố một khoản đầu tư lớn vào cơ sở hạ tầng năng lượng tái tạo.)","Learning a foreign language requires a substantial [investment] of time and effort. (=Dịch: Học một ngoại ngữ đòi hỏi sự đầu tư đáng kể về thời gian và công sức.)"],"ukAudio":"/ai_services/tts3/?q=investment&lang=en-GB&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=investment&lang=en-US&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F"},{"id":"lv_1_55","topic":"Job Seeking and Work","word":"joy","pos":"(n)","ipa":"/dʒɔɪ/","defVi":"niềm vui, sự vui mừng","defEn":"a feeling of great happiness or pleasure","examples":["The children jumped for [joy] when they heard the good news. (=Dịch: Lũ trẻ nhảy cẫng lên vì vui sướng khi nghe được tin tốt lành.)","Gardening brings immense [joy] and relaxation to many retirees. (=Dịch: Làm vườn mang lại niềm vui vô bờ bến và sự thư giãn cho nhiều người về hưu.)","His success was a source of great [joy] to his entire family. (=Dịch: Thành công của anh ấy là nguồn vui lớn cho cả gia đình.)"],"ukAudio":"/ai_services/tts3/?q=joy&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AA%2F","usAudio":"/ai_services/tts3/?q=joy&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AA%2F"},{"id":"lv_1_56","topic":"Job Seeking and Work","word":"latin","pos":"(adj)","ipa":"/ˈlæt.n/","defVi":"thuộc tiếng La-tinh, thuộc văn hóa La-tinh","defEn":"relating to the ancient Latin language, ancient Rome, or Latin America","examples":["Many scientific names for animals and plants are derived from [Latin] roots. (=Dịch: Nhiều tên khoa học của động thực vật bắt nguồn từ các gốc từ tiếng La-tinh.)","The festival celebrates the vibrant traditions of [Latin] music and dance. (=Dịch: Lễ hội tôn vinh những truyền thống sôi động của âm nhạc và vũ điệu Mỹ La-tinh.)","Students of law often encounter [Latin] phrases in legal documents. (=Dịch: Sinh viên ngành luật thường bắt gặp các cụm từ tiếng La-tinh trong các văn bản pháp lý.)"],"ukAudio":"/ai_services/tts3/?q=latin&lang=en-GB&ipa=%2F%CB%88l%C3%A6t.n%2F","usAudio":"/ai_services/tts3/?q=latin&lang=en-US&ipa=%2F%CB%88l%C3%A6t.n%2F"},{"id":"lv_1_57","topic":"Job Seeking and Work","word":"layout","pos":"(n)","ipa":"/ˈleɪ.aʊt/","defVi":"bố cục, sơ đồ mặt bằng, sự sắp xếp","defEn":"the way in which the parts of something are arranged or organized","examples":["The store changed its [layout] to encourage customers to browse more items. (=Dịch: Cửa hàng đã thay đổi cách bố trí để khuyến khích khách hàng xem nhiều mặt hàng hơn.)","I like the clear [layout] of this website because it is easy to navigate. (=Dịch: Tôi thích bố cục rõ ràng của trang web này vì nó rất dễ điều hướng.)","The architect presented the new office [layout] to the management team. (=Dịch: Kiến trúc sư đã trình bày bản bố trí văn phòng mới cho ban quản lý.)"],"ukAudio":"/ai_services/tts3/?q=layout&lang=en-GB&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=layout&lang=en-US&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F"},{"id":"lv_1_58","topic":"Job Seeking and Work","word":"leaflet","pos":"(n)","ipa":"/ˈliːf.lət/","defVi":"tờ rơi, tờ gấp quảng cáo","defEn":"a printed sheet of paper containing information or advertising, usually distributed free","examples":["Volunteers handed out a [leaflet] about environmental protection to passersby. (=Dịch: Các tình nguyện viên đã phát tờ rơi về bảo vệ môi trường cho người qua đường.)","I picked up a travel [leaflet] at the tourist information center. (=Dịch: Tôi đã lấy một tờ rơi du lịch tại trung tâm thông tin du khách.)","The medical [leaflet] explains the possible side effects of the drug. (=Dịch: Tờ hướng dẫn y tế giải thích các tác dụng phụ có thể xảy ra của thuốc.)"],"ukAudio":"/ai_services/tts3/?q=leaflet&lang=en-GB&ipa=%2F%CB%88li%CB%90f.l%C9%99t%2F","usAudio":"/ai_services/tts3/?q=leaflet&lang=en-US&ipa=%2F%CB%88li%CB%90f.l%C9%99t%2F"},{"id":"lv_1_59","topic":"Job Seeking and Work","word":"licence","pos":"(n)","ipa":"/ˈlaɪ.səns/","defVi":"giấy phép, bằng lái","defEn":"an official document giving permission to do, use, or own something","examples":["You need a valid [licence] to drive a car in this country. (=Dịch: Bạn cần có giấy phép lái xe hợp lệ để lái ô tô ở quốc gia này.)","The restaurant lost its [licence] to serve alcohol after breaking the rules. (=Dịch: Nhà hàng đã bị tước giấy phép phục vụ đồ uống có cồn sau khi vi phạm các quy định.)","He applied for a software [licence] to use the program legally. (=Dịch: Anh ấy đã đăng ký mua bản quyền phần mềm để sử dụng chương trình một cách hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=licence&lang=en-GB&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=licence&lang=en-US&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F"},{"id":"lv_1_60","topic":"Job Seeking and Work","word":"lounge","pos":"(n)","ipa":"/laʊndʒ/","defVi":"phòng chờ, phòng sinh hoạt chung","defEn":"a comfortable room in a house, hotel, or airport used for sitting and relaxing","examples":["Business-class passengers can relax and enjoy free snacks in the airport [lounge]. (=Dịch: Hành khách hạng thương gia có thể thư giãn và thưởng thức đồ ăn nhẹ miễn phí trong phòng chờ sân bay.)","The family gathered in the cozy [lounge] to watch television after dinner. (=Dịch: Gia đình quây quần trong phòng khách ấm cúng để xem tivi sau bữa tối.)","The hotel has a quiet cocktail [lounge] on the top floor. (=Dịch: Khách sạn có một quầy bar phục vụ cocktail yên tĩnh trên tầng cao nhất.)"],"ukAudio":"/ai_services/tts3/?q=lounge&lang=en-GB&ipa=%2Fla%CA%8And%CA%92%2F","usAudio":"/ai_services/tts3/?q=lounge&lang=en-US&ipa=%2Fla%CA%8And%CA%92%2F"},{"id":"lv_1_61","topic":"Job Seeking and Work","word":"machinery","pos":"(n)","ipa":"/məˈʃiː.nɚ.i/","defVi":"máy móc, thiết bị cơ khí","defEn":"machines as a whole, especially large machines used in industry or agriculture","examples":["The factory invested in modern [machinery] to increase production speed. (=Dịch: Nhà máy đã đầu tư vào máy móc hiện đại để tăng tốc độ sản xuất.)","Workers must wear protective helmets when operating heavy [machinery]. (=Dịch: Công nhân phải đội mũ bảo hộ khi vận hành máy móc hạng nặng.)","Regular maintenance prevents the farm [machinery] from breaking down unexpectedly. (=Dịch: Bảo trì định kỳ giúp máy móc nông nghiệp không bị hỏng hóc bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=machinery&lang=en-GB&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=machinery&lang=en-US&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F"},{"id":"lv_1_62","topic":"Job Seeking and Work","word":"magician","pos":"(n)","ipa":"/məˈdʒɪʃ.ən/","defVi":"ảo thuật gia","defEn":"a person who performs magic tricks for entertainment","examples":["The [magician] pulled a white rabbit out of his empty hat. (=Dịch: Ảo thuật gia đã kéo một con thỏ trắng ra khỏi chiếc mũ trống rỗng của mình.)","They hired a talented [magician] to entertain the children at the birthday party. (=Dịch: Họ đã thuê một ảo thuật gia tài năng để biểu diễn giúp vui cho các bạn nhỏ trong bữa tiệc sinh nhật.)","The audience watched in awe as the [magician] seemed to disappear into thin air. (=Dịch: Khán giả kinh ngạc theo dõi khi ảo thuật gia dường như biến mất vào hư không.)"],"ukAudio":"/ai_services/tts3/?q=magician&lang=en-GB&ipa=%2Fm%C9%99%CB%88d%CA%92%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=magician&lang=en-US&ipa=%2Fm%C9%99%CB%88d%CA%92%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_63","topic":"Job Seeking and Work","word":"mentor","pos":"(n)","ipa":"/ˈmen.tɔːr/","defVi":"người cố vấn, người hướng dẫn","defEn":"an experienced and trusted person who advises and guides someone younger or less experienced","examples":["My former professor acted as a valuable [mentor] throughout my early academic career. (=Dịch: Giáo sư cũ của tôi đã đóng vai trò là một người cố vấn quý báu trong suốt giai đoạn đầu sự nghiệp học thuật của tôi.)","The company established a scheme to pair every new graduate with a senior [mentor]. (=Dịch: Công ty đã thiết lập một chương trình ghép đôi mỗi sinh viên mới tốt nghiệp với một người hướng dẫn giàu kinh nghiệm.)","She credits her [mentor] with teaching her how to negotiate contracts effectively. (=Dịch: Cô ấy biết ơn người cố vấn vì đã dạy cô cách đàm phán hợp đồng một cách hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=mentor&lang=en-GB&ipa=%2F%CB%88men.t%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=mentor&lang=en-US&ipa=%2F%CB%88men.t%C9%94%CB%90r%2F"},{"id":"lv_1_64","topic":"Job Seeking and Work","word":"midday","pos":"(n)","ipa":"/ˌmɪdˈdeɪ/","defVi":"buổi trưa, giữa trưa","defEn":"the middle of the day; twelve o'clock in the afternoon","examples":["The sun is usually at its hottest around [midday]. (=Dịch: Mặt trời thường gay gắt nhất vào khoảng giữa trưa.)","We decided to take a break and have our lunch at [midday]. (=Dịch: Chúng tôi quyết định nghỉ ngơi và ăn trưa vào buổi trưa.)","The delivery is scheduled to arrive before [midday] tomorrow. (=Dịch: Hàng dự kiến sẽ được giao đến trước buổi trưa ngày mai.)"],"ukAudio":"/ai_services/tts3/?q=midday&lang=en-GB&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F","usAudio":"/ai_services/tts3/?q=midday&lang=en-US&ipa=%2F%CB%8Cm%C9%AAd%CB%88de%C9%AA%2F"},{"id":"lv_1_65","topic":"Job Seeking and Work","word":"orientation","pos":"(n)","ipa":"/ˌɔːr.i.enˈteɪ.ʃən/","defVi":"buổi định hướng, chương trình tập huấn ban đầu","defEn":"a training or introduction session for new employees or students","examples":["All new recruits are required to attend the company [orientation] on Monday morning. (=Dịch: Tất cả nhân viên mới được yêu cầu tham gia buổi định hướng của công ty vào sáng thứ Hai.)","The university organised a campus tour as part of the student [orientation] week. (=Dịch: Trường đại học đã tổ chức một chuyến tham quan khuôn viên trường như một phần của tuần lễ định hướng sinh viên.)","The [orientation] helped her understand the workplace culture and safety procedures. (=Dịch: Buổi định hướng đã giúp cô ấy hiểu rõ văn hóa nơi làm việc và các quy trình an toàn.)"],"ukAudio":"/ai_services/tts3/?q=orientation&lang=en-GB&ipa=%2F%CB%8C%C9%94%CB%90r.i.en%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=orientation&lang=en-US&ipa=%2F%CB%8C%C9%94%CB%90r.i.en%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_66","topic":"Job Seeking and Work","word":"outcome","pos":"(n)","ipa":"/ˈaʊt.kʌm/","defVi":"kết quả, hậu quả","defEn":"the final result or effect of an action, process, or situation","examples":["We are still waiting for the final [outcome] of the election. (=Dịch: Chúng tôi vẫn đang chờ kết quả cuối cùng của cuộc bầu cử.)","Regular exercise and a balanced diet will produce a positive health [outcome]. (=Dịch: Tập thể dục thường xuyên và chế độ ăn uống cân bằng sẽ mang lại kết quả sức khỏe tích cực.)","The negotiations ended with a successful [outcome] for both companies. (=Dịch: Các cuộc đàm phán đã kết thúc với kết quả thành công cho cả hai công ty.)"],"ukAudio":"/ai_services/tts3/?q=outcome&lang=en-GB&ipa=%2F%CB%88a%CA%8At.k%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=outcome&lang=en-US&ipa=%2F%CB%88a%CA%8At.k%CA%8Cm%2F"},{"id":"lv_1_67","topic":"Job Seeking and Work","word":"outdated","pos":"(adj)","ipa":"/ˌaʊtˈdeɪ.t̬ɪd/","defVi":"lỗi thời, lạc hậu","defEn":"no longer fashionable, useful, or modern","examples":["These computer systems are [outdated] and need to be replaced soon. (=Dịch: Những hệ thống máy tính này đã lỗi thời và cần sớm được thay thế.)","The company's marketing strategy relies on [outdated] information. (=Dịch: Chiến lược tiếp thị của công ty đang dựa trên những thông tin lỗi thời.)","His views on gender roles are completely [outdated]. (=Dịch: Quan điểm của ông ấy về vai trò giới tính hoàn toàn cổ hủ.)"],"ukAudio":"/ai_services/tts3/?q=outdated&lang=en-GB&ipa=%2F%CB%8Ca%CA%8At%CB%88de%C9%AA.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=outdated&lang=en-US&ipa=%2F%CB%8Ca%CA%8At%CB%88de%C9%AA.t%CC%AC%C9%AAd%2F"},{"id":"lv_1_68","topic":"Job Seeking and Work","word":"overtime","pos":"(n)","ipa":"/ˈoʊ.vɚ.taɪm/","defVi":"sự làm thêm giờ, tiền làm thêm giờ","defEn":"time that you spend working beyond your normal working hours","examples":["Employees receive extra pay for working [overtime] on weekends. (=Dịch: Nhân viên nhận được thêm tiền lương khi làm thêm giờ vào các ngày cuối tuần.)","He put in many hours of [overtime] to finish the project before the deadline. (=Dịch: Anh ấy đã làm thêm nhiều giờ để hoàn thành dự án trước thời hạn.)","The factory ban on [overtime] reduced workers' monthly earnings. (=Dịch: Lệnh cấm làm thêm giờ của nhà máy đã làm giảm thu nhập hằng tháng của công nhân.)"],"ukAudio":"/ai_services/tts3/?q=overtime&lang=en-GB&ipa=%2F%CB%88o%CA%8A.v%C9%9A.ta%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=overtime&lang=en-US&ipa=%2F%CB%88o%CA%8A.v%C9%9A.ta%C9%AAm%2F"},{"id":"lv_1_69","topic":"Job Seeking and Work","word":"permit","pos":"(v)","ipa":"/pɚˈmɪt/","defVi":"cho phép","defEn":"to allow something to happen or give permission for something","examples":["The park does not [permit] visitors to bring dogs onto the beach. (=Dịch: Công viên không cho phép du khách dắt chó vào bãi biển.)","If weather conditions [permit], the outdoor concert will start at seven o'clock. (=Dịch: Nếu điều kiện thời tiết cho phép, buổi hòa nhạc ngoài trời sẽ bắt đầu lúc bảy giờ.)","The museum rules do not [permit] flash photography inside the galleries. (=Dịch: Quy định của bảo tàng không cho phép chụp ảnh có đèn flash bên trong các phòng trưng bày.)"],"ukAudio":"/ai_services/tts3/?q=permit&lang=en-GB&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=permit&lang=en-US&ipa=%2Fp%C9%9A%CB%88m%C9%AAt%2F"},{"id":"lv_1_70","topic":"Job Seeking and Work","word":"personnel","pos":"(n)","ipa":"/ˌpɜːr.səˈnel/","defVi":"nhân sự, đội ngũ nhân viên","defEn":"the people who work for an organization, business, or the armed forces","examples":["All sales [personnel] are required to attend the customer service workshop. (=Dịch: Tất cả nhân viên bán hàng đều phải tham gia buổi hội thảo về dịch vụ khách hàng.)","The director contacted the [personnel] department to post a new job vacancy. (=Dịch: Giám đốc đã liên hệ với phòng nhân sự để đăng tin tuyển dụng vị trí mới.)","Only authorized military [personnel] may enter this secure area. (=Dịch: Chỉ những quân nhân được ủy quyền mới có thể đi vào khu vực an ninh này.)"],"ukAudio":"/ai_services/tts3/?q=personnel&lang=en-GB&ipa=%2F%CB%8Cp%C9%9C%CB%90r.s%C9%99%CB%88nel%2F","usAudio":"/ai_services/tts3/?q=personnel&lang=en-US&ipa=%2F%CB%8Cp%C9%9C%CB%90r.s%C9%99%CB%88nel%2F"},{"id":"lv_1_71","topic":"Job Seeking and Work","word":"physically","pos":"(adv)","ipa":"/ˈfɪz.ɪ.kli/","defVi":"về mặt thể chất, theo cách hữu hình","defEn":"in a way that relates to the body or real, concrete objects","examples":["Regular exercise helps students stay [physically] healthy and energetic. (=Dịch: Tập thể dục thường xuyên giúp học sinh giữ được sức khỏe thể chất tốt và tràn đầy năng lượng.)","He was [physically] exhausted after running the full marathon. (=Dịch: Anh ấy đã kiệt sức về mặt thể lực sau khi chạy hết quãng đường marathon.)","The store does not [physically] stock the item, but it can be ordered online. (=Dịch: Cửa hàng không có sẵn mặt hàng này tại chỗ, nhưng bạn có thể đặt mua trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=physically&lang=en-GB&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=physically&lang=en-US&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F"},{"id":"lv_1_72","topic":"Job Seeking and Work","word":"portion","pos":"(n)","ipa":"/ˈpɔːr.ʃən/","defVi":"phần, khẩu phần","defEn":"a part or share of a whole amount","examples":["A large [portion] of the budget is spent on public health. (=Dịch: Một phần lớn ngân sách được chi cho y tế công cộng.)","The restaurant serves a generous [portion] of pasta with every meal. (=Dịch: Nhà hàng phục vụ một khẩu phần mì Ý rất hào phóng trong mỗi bữa ăn.)","Only a small [portion] of applicants were invited to the interview. (=Dịch: Chỉ một phần nhỏ các ứng viên được mời tham gia phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=portion&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=portion&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.%CA%83%C9%99n%2F"},{"id":"lv_1_73","topic":"Job Seeking and Work","word":"portuguese","pos":"(adj)","ipa":"/ˌpɔːr.tʃəˈɡiːz/","defVi":"thuộc về Bồ Đào Nha, tiếng Bồ Đào Nha hoặc người Bồ Đào Nha","defEn":"relating to Portugal, its people, or its language","examples":["We enjoyed traditional [Portuguese] cuisine during our vacation in Lisbon. (=Dịch: Chúng tôi đã thưởng thức ẩm thực Bồ Đào Nha truyền thống trong kỳ nghỉ ở Lisbon.)","Many historical documents from the colonial era were written in the [Portuguese] language. (=Dịch: Nhiều tài liệu lịch sử từ thời thuộc địa được viết bằng tiếng Bồ Đào Nha.)","He is studying the impact of [Portuguese] architecture on coastal cities in Asia. (=Dịch: Anh ấy đang nghiên cứu tác động của kiến trúc Bồ Đào Nha đối với các thành phố ven biển ở châu Á.)"],"ukAudio":"/ai_services/tts3/?q=portuguese&lang=en-GB&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1i%CB%90z%2F","usAudio":"/ai_services/tts3/?q=portuguese&lang=en-US&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1i%CB%90z%2F"},{"id":"lv_1_74","topic":"Job Seeking and Work","word":"premise","pos":"(n)","ipa":"/ˈprem.ɪs/","defVi":"tiền đề, giả định cơ sở","defEn":"a statement or idea that is accepted as true and forms the basis for an argument","examples":["The entire scientific theory is built on a false [premise]. (=Dịch: Toàn bộ lý thuyết khoa học này được xây dựng trên một tiền đề sai lầm.)","His argument starts from the basic [premise] that education should be free for all. (=Dịch: Lập luận của anh ấy bắt đầu từ tiền đề cơ bản rằng giáo dục nên miễn phí cho tất cả mọi người.)","If we accept your [premise], then the logical conclusion is undeniable. (=Dịch: Nếu chúng ta chấp nhận tiền đề của bạn, thì kết luận hợp logic là không thể chối cãi.)"],"ukAudio":"/ai_services/tts3/?q=premise&lang=en-GB&ipa=%2F%CB%88prem.%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=premise&lang=en-US&ipa=%2F%CB%88prem.%C9%AAs%2F"},{"id":"lv_1_75","topic":"Job Seeking and Work","word":"profit","pos":"(n)","ipa":"/ˈprɑː.fɪt/","defVi":"lợi nhuận, tiền lãi","defEn":"money gained in business activities after paying all costs and expenses","examples":["The startup turned a modest [profit] during its second year of operation. (=Dịch: Công ty khởi nghiệp đã đạt được một khoản lợi nhuận khiêm tốn trong năm hoạt động thứ hai.)","They sold the renovated property at a significant [profit]. (=Dịch: Họ đã bán bất động sản sau khi cải tạo với một khoản lợi nhuận đáng kể.)","A portion of the annual [profit] is reinvested into research and development. (=Dịch: Một phần lợi nhuận hàng năm được tái đầu tư vào nghiên cứu và phát triển.)"],"ukAudio":"/ai_services/tts3/?q=profit&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=profit&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F"},{"id":"lv_1_76","topic":"Job Seeking and Work","word":"psychology","pos":"(n)","ipa":"/saɪˈkɑː.lə.dʒi/","defVi":"tâm lý học","defEn":"the scientific study of the human mind and behavior","examples":["She decided to major in [psychology] to better understand human behavior. (=Dịch: Cô ấy quyết định học chuyên ngành tâm lý học để hiểu rõ hơn về hành vi của con người.)","Educational [psychology] plays a crucial role in designing effective teaching methods. (=Dịch: Tâm lý học giáo dục đóng vai trò quan trọng trong việc thiết kế các phương pháp giảng dạy hiệu quả.)","Understanding consumer [psychology] helps companies create more persuasive advertisements. (=Dịch: Hiểu được tâm lý người tiêu dùng giúp các công ty tạo ra những quảng cáo có sức thuyết phục hơn.)"],"ukAudio":"/ai_services/tts3/?q=psychology&lang=en-GB&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=psychology&lang=en-US&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_1_77","topic":"Job Seeking and Work","word":"receptionist","pos":"(n)","ipa":"/rɪˈsep.ʃən.ɪst/","defVi":"nhân viên lễ tân","defEn":"a person whose job is to greet visitors and answer phone calls in an office or hotel","examples":["The [receptionist] greeted the guests warmly and asked them to sign the visitor log. (=Dịch: Nhân viên lễ tân niềm nở chào đón khách và đề nghị họ ký vào sổ khách đến thăm.)","Please leave your room key with the hotel [receptionist] before checking out. (=Dịch: Vui lòng gửi lại chìa khóa phòng cho lễ tân khách sạn trước khi làm thủ tục trả phòng.)","The clinic is looking for a bilingual [receptionist] to manage patient appointments. (=Dịch: Phòng khám đang tìm kiếm một nhân viên tiếp tân song ngữ để quản lý lịch hẹn của bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=receptionist&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sep.%CA%83%C9%99n.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=receptionist&lang=en-US&ipa=%2Fr%C9%AA%CB%88sep.%CA%83%C9%99n.%C9%AAst%2F"},{"id":"lv_1_78","topic":"Job Seeking and Work","word":"recover","pos":"(v)","ipa":"/rɪˈkʌv.ɚ/","defVi":"hồi phục, bình phục","defEn":"to get well again after being sick, hurt, or experiencing a difficult situation","examples":["It took her several weeks to [recover] from the flu. (=Dịch: Cô ấy đã mất vài tuần để hồi phục sau trận cảm cúm.)","The economy is beginning to [recover] after the recession. (=Dịch: Nền kinh tế đang bắt đầu phục hồi sau cuộc suy thoái.)","He needs time to [recover] his strength after the surgery. (=Dịch: Anh ấy cần thời gian để phục hồi thể lực sau ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=recover&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=recover&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%9A%2F"},{"id":"lv_1_79","topic":"Job Seeking and Work","word":"recruitment","pos":"(n)","ipa":"/rɪˈkrut.mənt/","defVi":"sự tuyển dụng, quá trình tuyển dụng","defEn":"the process of finding and hiring new people to join a company or organization","examples":["The company launched a new [recruitment] drive to attract young graduates. (=Dịch: Công ty đã phát động một đợt tuyển dụng mới nhằm thu hút các sinh viên mới tốt nghiệp.)","She works as a consultant in a large [recruitment] agency. (=Dịch: Cô ấy làm việc với vai trò là chuyên viên tư vấn tại một công ty tuyển dụng lớn.)","The military is facing difficulties with staff [recruitment] this year. (=Dịch: Quân đội đang đối mặt với nhiều khó khăn trong việc tuyển dụng nhân sự trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=recruitment&lang=en-GB&ipa=%2Fr%C9%AA%CB%88krut.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=recruitment&lang=en-US&ipa=%2Fr%C9%AA%CB%88krut.m%C9%99nt%2F"},{"id":"lv_1_80","topic":"Job Seeking and Work","word":"referee","pos":"(n)","ipa":"/ˌref.əˈriː/","defVi":"người giới thiệu, người bảo lãnh (trong hồ sơ xin việc)","defEn":"a person who provides information about your character or abilities for a job or course application","examples":["You need to provide the names and contact details of two academic [referees]. (=Dịch: Bạn cần cung cấp tên và thông tin liên lạc của hai người tham chiếu học thuật.)","My former manager agreed to act as a [referee] for my job application. (=Dịch: Người quản lý cũ của tôi đã đồng ý làm người tham chiếu cho hồ sơ xin việc của tôi.)","The company contacted each [referee] to verify the candidate's work history. (=Dịch: Công ty đã liên hệ với từng người tham chiếu để xác minh lịch sử làm việc của ứng viên.)"],"ukAudio":"/ai_services/tts3/?q=referee&lang=en-GB&ipa=%2F%CB%8Cref.%C9%99%CB%88ri%CB%90%2F","usAudio":"/ai_services/tts3/?q=referee&lang=en-US&ipa=%2F%CB%8Cref.%C9%99%CB%88ri%CB%90%2F"},{"id":"lv_1_81","topic":"Job Seeking and Work","word":"refurbishment","pos":"(n)","ipa":"/riːˈfɝː.bɪʃ.mənt/","defVi":"sự tân trang, sự nâng cấp cải tạo","defEn":"the act of renovating, redecorating, or restoring a building or room","examples":["The library will remain closed for two weeks during the [refurbishment]. (=Dịch: Thư viện sẽ tiếp tục đóng cửa trong hai tuần trong thời gian tân trang.)","The hotel underwent a major [refurbishment] to attract more international tourists. (=Dịch: Khách sạn đã trải qua một đợt nâng cấp lớn để thu hút thêm khách du lịch quốc tế.)","After months of [refurbishment], the old theater reopened with modern facilities. (=Dịch: Sau nhiều tháng tu sửa, nhà hát cũ đã mở cửa trở lại với các cơ sở vật chất hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=refurbishment&lang=en-GB&ipa=%2Fri%CB%90%CB%88f%C9%9D%CB%90.b%C9%AA%CA%83.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=refurbishment&lang=en-US&ipa=%2Fri%CB%90%CB%88f%C9%9D%CB%90.b%C9%AA%CA%83.m%C9%99nt%2F"},{"id":"lv_1_82","topic":"Job Seeking and Work","word":"register","pos":"(v)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"đăng ký, ghi danh","defEn":"to officially record a name or information on a list","examples":["Students must [register] for their exams before the end of the week. (=Dịch: Học sinh phải đăng ký dự thi trước cuối tuần này.)","You can [register] a new business online in just a few minutes. (=Dịch: Bạn có thể đăng ký doanh nghiệp mới trực tuyến chỉ trong vài phút.)","Don't forget to [register] your luggage at the check-in desk. (=Dịch: Đừng quên gửi ký gửi hành lý của bạn tại quầy làm thủ tục.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_1_83","topic":"Job Seeking and Work","word":"registration","pos":"(n)","ipa":"/ˌredʒ.əˈstreɪ.ʃən/","defVi":"sự đăng ký, việc vào sổ","defEn":"the act of recording a name or information on an official list","examples":["Course [registration] must be completed before the end of the week. (=Dịch: Việc đăng ký khóa học phải được hoàn thành trước cuối tuần này.)","Please show your vehicle [registration] documents to the officer. (=Dịch: Vui lòng xuất trình giấy tờ đăng ký xe của bạn cho viên chức kiểm tra.)","Online [registration] for the marathon opens tomorrow morning. (=Dịch: Cổng đăng ký trực tuyến cho giải chạy marathon sẽ mở vào sáng mai.)"],"ukAudio":"/ai_services/tts3/?q=registration&lang=en-GB&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=registration&lang=en-US&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_1_84","topic":"Job Seeking and Work","word":"satisfaction","pos":"(n)","ipa":"/ˌsæt̬.əsˈfæk.ʃən/","defVi":"sự hài lòng, sự thỏa mãn","defEn":"a pleasant feeling of contentment when you have achieved or received what you wanted","examples":["Customer [satisfaction] is the main priority of our company. (=Dịch: Sự hài lòng của khách hàng là ưu tiên hàng đầu của công ty chúng tôi.)","She gets immense job [satisfaction] from helping people in need. (=Dịch: Cô ấy cảm nhận được sự thỏa mãn to lớn trong công việc từ việc giúp đỡ những người gặp khó khăn.)","He looked at his completed painting with a sense of [satisfaction]. (=Dịch: Anh ấy nhìn vào bức tranh đã hoàn thành của mình với một cảm giác hài lòng.)"],"ukAudio":"/ai_services/tts3/?q=satisfaction&lang=en-GB&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%99s%CB%88f%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=satisfaction&lang=en-US&ipa=%2F%CB%8Cs%C3%A6t%CC%AC.%C9%99s%CB%88f%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_1_85","topic":"Job Seeking and Work","word":"shortly","pos":"(adv)","ipa":"/ˈʃɔːrt.li/","defVi":"chẳng bao lâu, sớm, ngay sau đó","defEn":"in a short time; soon","examples":["The train for Manchester will be arriving [shortly]. (=Dịch: Chuyến tàu đi Manchester sẽ đến trong chốc lát nữa.)","He graduated from university and [shortly] afterward landed his dream job. (=Dịch: Anh ấy tốt nghiệp đại học và không lâu sau đó đã có được công việc mơ ước.)","The doctor will be with you [shortly], so please take a seat in the waiting room. (=Dịch: Bác sĩ sẽ đến khám cho bạn ngay, vì vậy xin vui lòng ngồi chờ ở phòng đợi.)"],"ukAudio":"/ai_services/tts3/?q=shortly&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%94%CB%90rt.li%2F","usAudio":"/ai_services/tts3/?q=shortly&lang=en-US&ipa=%2F%CB%88%CA%83%C9%94%CB%90rt.li%2F"},{"id":"lv_1_86","topic":"Job Seeking and Work","word":"slicer","pos":"(n)","ipa":"/ˈslaɪ.sɚ/","defVi":"máy cắt lát, dụng cụ thái lát","defEn":"a machine or tool used for cutting food into thin pieces","examples":["The butcher used an electric meat [slicer] to prepare the ham. (=Dịch: Người bán thịt đã sử dụng máy thái thịt chạy điện để chuẩn bị phần giăm bông.)","Be careful when cleaning the blade of the vegetable [slicer]. (=Dịch: Hãy cẩn thận khi vệ sinh lưỡi dao của dụng cụ cắt gọt rau củ.)","A high-quality bread [slicer] will give you perfectly even pieces. (=Dịch: Một chiếc máy cắt bánh mì chất lượng cao sẽ giúp bạn có được những lát bánh đều đẹp hoàn hảo.)"],"ukAudio":"/ai_services/tts3/?q=slicer&lang=en-GB&ipa=%2F%CB%88sla%C9%AA.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=slicer&lang=en-US&ipa=%2F%CB%88sla%C9%AA.s%C9%9A%2F"},{"id":"lv_1_87","topic":"Job Seeking and Work","word":"spanish","pos":"(adj)","ipa":"/ˈspæn.ɪʃ/","defVi":"(thuộc) Tây Ban Nha, tiếng Tây Ban Nha","defEn":"relating to Spain, its people, or its language","examples":["We had dinner at a traditional [Spanish] restaurant last night. (=Dịch: Chúng tôi đã ăn tối tại một nhà hàng Tây Ban Nha truyền thống vào tối qua.)","He is fluent in both English and [Spanish]. (=Dịch: Anh ấy thông thạo cả tiếng Anh lẫn tiếng Tây Ban Nha.)","The gallery features many famous [Spanish] paintings. (=Dịch: Phòng trưng bày giới thiệu nhiều bức tranh Tây Ban Nha nổi tiếng.)"],"ukAudio":"/ai_services/tts3/?q=spanish&lang=en-GB&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=spanish&lang=en-US&ipa=%2F%CB%88sp%C3%A6n.%C9%AA%CA%83%2F"},{"id":"lv_1_88","topic":"Job Seeking and Work","word":"spreadsheet","pos":"(n)","ipa":"/ˈsprɛd.ʃiːt/","defVi":"bảng tính điện tử","defEn":"a computer program or document arranged in a grid of rows and columns, used for calculations","examples":["She entered all the monthly expenses into an Excel [spreadsheet]. (=Dịch: Cô ấy đã nhập tất cả các khoản chi tiêu hàng tháng vào một bảng tính Excel.)","The accountant used a complex [spreadsheet] to calculate company profits. (=Dịch: Kế toán đã sử dụng một bảng tính phức tạp để tính toán lợi nhuận của công ty.)","You can organize customer contact information neatly using a simple [spreadsheet]. (=Dịch: Bạn có thể sắp xếp thông tin liên hệ của khách hàng một cách ngăn nắp bằng một bảng tính đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=spreadsheet&lang=en-GB&ipa=%2F%CB%88spr%C9%9Bd.%CA%83i%CB%90t%2F","usAudio":"/ai_services/tts3/?q=spreadsheet&lang=en-US&ipa=%2F%CB%88spr%C9%9Bd.%CA%83i%CB%90t%2F"},{"id":"lv_1_89","topic":"Job Seeking and Work","word":"staffroom","pos":"(n)","ipa":"/ˈstæf.rum/","defVi":"phòng nghỉ của nhân viên, phòng giáo viên","defEn":"a room in a school or office where employees can relax or work","examples":["Teachers usually gather in the [staffroom] during break times. (=Dịch: Các giáo viên thường tụ họp trong phòng nghỉ giáo viên vào giờ giải lao.)","The memo was pinned on the noticeboard in the [staffroom]. (=Dịch: Bản thông báo đã được ghim trên bảng tin trong phòng giáo viên.)","There is a coffee machine and a microwave in the [staffroom]. (=Dịch: Có một máy pha cà phê và một lò vi sóng trong phòng giáo viên.)"],"ukAudio":"/ai_services/tts3/?q=staffroom&lang=en-GB&ipa=%2F%CB%88st%C3%A6f.rum%2F","usAudio":"/ai_services/tts3/?q=staffroom&lang=en-US&ipa=%2F%CB%88st%C3%A6f.rum%2F"},{"id":"lv_1_90","topic":"Job Seeking and Work","word":"storeroom","pos":"(n)","ipa":"/ˈstɔːr.ruːm/","defVi":"phòng chứa đồ, kho chứa","defEn":"a room used for storing items, supplies, or goods","examples":["Extra chairs and tables are kept in the basement [storeroom]. (=Dịch: Bàn và ghế dự phòng được cất giữ trong phòng kho dưới tầng hầm.)","The manager went into the [storeroom] to check the inventory. (=Dịch: Người quản lý đã vào nhà kho để kiểm tra hàng tồn kho.)","We cleaned out the [storeroom] to make space for new equipment. (=Dịch: Chúng tôi đã dọn sạch nhà kho để lấy chỗ chứa thiết bị mới.)"],"ukAudio":"/ai_services/tts3/?q=storeroom&lang=en-GB&ipa=%2F%CB%88st%C9%94%CB%90r.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=storeroom&lang=en-US&ipa=%2F%CB%88st%C9%94%CB%90r.ru%CB%90m%2F"},{"id":"lv_1_91","topic":"Job Seeking and Work","word":"straightaway","pos":"(adv)","ipa":"/ˌstreɪt.əˈweɪ/","defVi":"ngay lập tức, lập tức","defEn":"without delay; immediately","examples":["When she heard the alarm, she called the police [straightaway]. (=Dịch: Khi nghe thấy tiếng chuông báo động, cô ấy đã gọi cảnh sát ngay lập tức.)","If you notice any symptoms, consult a doctor [straightaway]. (=Dịch: Nếu bạn nhận thấy bất kỳ triệu chứng nào, hãy đến khám bác sĩ ngay lập tức.)","I will send you the confirmation email [straightaway]. (=Dịch: Tôi sẽ gửi cho bạn email xác nhận ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=straightaway&lang=en-GB&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=straightaway&lang=en-US&ipa=%2F%CB%8Cstre%C9%AAt.%C9%99%CB%88we%C9%AA%2F"},{"id":"lv_1_92","topic":"Job Seeking and Work","word":"strike","pos":"(n)","ipa":"/straɪk/","defVi":"cuộc đình công, bãi công","defEn":"a refusal to work organized by a body of employees as a form of protest","examples":["Train drivers have voted to go on [strike] next Monday. (=Dịch: Các lái tàu đã bỏ phiếu quyết định đình công vào thứ Hai tới.)","The factory workers called a [strike] over unfair pay. (=Dịch: Các công nhân nhà máy đã kêu gọi một cuộc đình công vì vấn đề trả lương không công bằng.)","The national transport [strike] caused massive traffic disruptions. (=Dịch: Cuộc đình công ngành giao thông vận tải toàn quốc đã gây ra tình trạng gián đoạn giao thông nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=strike&lang=en-GB&ipa=%2Fstra%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=strike&lang=en-US&ipa=%2Fstra%C9%AAk%2F"},{"id":"lv_1_93","topic":"Job Seeking and Work","word":"supervisor","pos":"(n)","ipa":"/ˈsuː.pər.vaɪ.zər/","defVi":"người giám sát, cấp trên trực tiếp","defEn":"a person who manages or oversees other people or activities in a workplace","examples":["If you encounter any technical issues, please notify your [supervisor] immediately. (=Dịch: Nếu bạn gặp bất kỳ sự cố kỹ thuật nào, vui lòng thông báo ngay cho người giám sát của bạn.)","Her [supervisor] provided helpful feedback on the draft report. (=Dịch: Người giám sát của cô ấy đã đưa ra những nhận xét hữu ích về bản dự thảo báo cáo.)","He meets with his research [supervisor] once a week to discuss his progress. (=Dịch: Anh ấy gặp người hướng dẫn nghiên cứu của mình mỗi tuần một lần để thảo luận về tiến độ.)"],"ukAudio":"/ai_services/tts3/?q=supervisor&lang=en-GB&ipa=%2F%CB%88su%CB%90.p%C9%99r.va%C9%AA.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=supervisor&lang=en-US&ipa=%2F%CB%88su%CB%90.p%C9%99r.va%C9%AA.z%C9%99r%2F"},{"id":"lv_1_94","topic":"Job Seeking and Work","word":"sushi","pos":"(n)","ipa":"/ˈsuː.ʃi/","defVi":"món sushi","defEn":"a Japanese dish of cold cooked rice flavored with vinegar, typically garnished with raw seafood and vegetables","examples":["We decided to order fresh [sushi] for dinner tonight. (=Dịch: Chúng tôi quyết định gọi món sushi tươi ngon cho bữa tối nay.)","Learning how to roll [sushi] properly requires patience and practice. (=Dịch: Học cách cuộn sushi đúng chuẩn đòi hỏi sự kiên nhẫn và luyện tập.)","The restaurant is famous for its authentic Japanese [sushi] and sashimi. (=Dịch: Nhà hàng này nổi tiếng với các món sushi và sashimi Nhật Bản chuẩn vị.)"],"ukAudio":"/ai_services/tts3/?q=sushi&lang=en-GB&ipa=%2F%CB%88su%CB%90.%CA%83i%2F","usAudio":"/ai_services/tts3/?q=sushi&lang=en-US&ipa=%2F%CB%88su%CB%90.%CA%83i%2F"},{"id":"lv_1_95","topic":"Job Seeking and Work","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.ə.weɪ/","defVi":"đồ ăn mang về, quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else; a shop that sells such food","examples":["We were too tired to cook, so we picked up a Chinese [takeaway]. (=Dịch: Chúng tôi quá mệt để nấu nướng, vì vậy chúng tôi đã mua đồ ăn Trung Quốc mang về.)","The street is lined with pizza parlors and burger [takeaway] shops. (=Dịch: Con phố có rất nhiều tiệm bánh pizza và cửa hàng bán burger mang về.)","Ordering a [takeaway] on Friday nights has become a family tradition. (=Dịch: Gọi đồ ăn mang về vào tối thứ Sáu đã trở thành một truyền thống của gia đình.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99.we%C9%AA%2F"},{"id":"lv_1_96","topic":"Job Seeking and Work","word":"tax","pos":"(n)","ipa":"/tæks/","defVi":"thuế","defEn":"money paid to the government based on your income or the cost of goods","examples":["The government plans to increase the [tax] on sugary drinks. (=Dịch: Chính phủ có kế hoạch tăng thuế đối với đồ uống có đường.)","Citizens are required by law to pay their income [tax] on time. (=Dịch: Công dân theo luật định phải nộp thuế thu nhập đúng hạn.)","The price of the item includes all local sales [tax]. (=Dịch: Giá của mặt hàng đã bao gồm tất cả các khoản thuế bán hàng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tax&lang=en-GB&ipa=%2Ft%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=tax&lang=en-US&ipa=%2Ft%C3%A6ks%2F"},{"id":"lv_1_97","topic":"Job Seeking and Work","word":"teamwork","pos":"(n)","ipa":"/ˈtiːm.wɝːk/","defVi":"làm việc nhóm, sự phối hợp đồng đội","defEn":"the activity of working together effectively in a group to achieve a goal","examples":["Successful project completion requires effective communication and strong [teamwork]. (=Dịch: Việc hoàn thành dự án thành công đòi hỏi khả năng giao tiếp hiệu quả và tinh thần làm việc nhóm vững chắc.)","The coach praised the players for their outstanding [teamwork] during the final match. (=Dịch: Huấn luyện viên đã khen ngợi các cầu thủ vì tinh thần đồng đội xuất sắc trong trận chung kết.)","Employers often look for candidates with excellent [teamwork] skills. (=Dịch: Các nhà tuyển dụng thường tìm kiếm những ứng viên có kỹ năng làm việc nhóm xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=teamwork&lang=en-GB&ipa=%2F%CB%88ti%CB%90m.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=teamwork&lang=en-US&ipa=%2F%CB%88ti%CB%90m.w%C9%9D%CB%90k%2F"},{"id":"lv_1_98","topic":"Job Seeking and Work","word":"technician","pos":"(n)","ipa":"/tekˈnɪʃ.ən/","defVi":"kỹ thuật viên","defEn":"a worker trained with special skills or knowledge in practical arts or sciences","examples":["A laboratory [technician] analyzed the blood samples carefully. (=Dịch: Một kỹ thuật viên phòng thí nghiệm đã phân tích các mẫu máu một cách cẩn thận.)","We called a [technician] to fix the heating system. (=Dịch: Chúng tôi đã gọi một kỹ thuật viên đến để sửa hệ thống sưởi.)","The IT [technician] helped recover all the deleted files. (=Dịch: Kỹ thuật viên công nghệ thông tin đã giúp khôi phục tất cả các tệp tin bị xóa.)"],"ukAudio":"/ai_services/tts3/?q=technician&lang=en-GB&ipa=%2Ftek%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=technician&lang=en-US&ipa=%2Ftek%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_1_99","topic":"Job Seeking and Work","word":"telecom","pos":"(n)","ipa":"/ˈtel.ə.kɑːm/","defVi":"viễn thông, ngành viễn thông","defEn":"the industry or technology of communicating over a distance by phone, cable, or satellite","examples":["She has invested in several leading [telecom] companies. (=Dịch: Cô ấy đã đầu tư vào một số công ty viễn thông hàng đầu.)","The government is upgrading the national [telecom] infrastructure. (=Dịch: Chính phủ đang nâng cấp cơ sở hạ tầng viễn thông quốc gia.)","Competition in the mobile [telecom] market has driven prices down. (=Dịch: Sự cạnh tranh trên thị trường viễn thông di động đã kéo giá cước giảm xuống.)"],"ukAudio":"/ai_services/tts3/?q=telecom&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.k%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=telecom&lang=en-US&ipa=%2F%CB%88tel.%C9%99.k%C9%91%CB%90m%2F"},{"id":"lv_1_100","topic":"Job Seeking and Work","word":"temporary","pos":"(adj)","ipa":"/ˈtem.pə.rer.i/","defVi":"tạm thời, nhất thời","defEn":"lasting or intended to last for only a limited period of time","examples":["The museum was closed for [temporary] repairs. (=Dịch: Bảo tàng đã đóng cửa để sửa chữa tạm thời.)","They hired [temporary] staff to cope with the holiday rush. (=Dịch: Họ đã thuê nhân viên tạm thời để giải quyết đợt cao điểm trong kỳ nghỉ lễ.)","This solution is only [temporary] until we find a permanent fix. (=Dịch: Giải pháp này chỉ mang tính tạm thời cho đến khi chúng tôi tìm ra cách khắc phục lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=temporary&lang=en-GB&ipa=%2F%CB%88tem.p%C9%99.rer.i%2F","usAudio":"/ai_services/tts3/?q=temporary&lang=en-US&ipa=%2F%CB%88tem.p%C9%99.rer.i%2F"},{"id":"lv_1_101","topic":"Job Seeking and Work","word":"trousers","pos":"(n)","ipa":"/ˈtraʊ.zɚz/","defVi":"quần dài","defEn":"a piece of clothing worn on the lower part of the body, covering each leg separately","examples":["He wore a pair of dark [trousers] and a white shirt to the interview. (=Dịch: Anh ấy mặc một chiếc quần tây tối màu và áo sơ mi trắng đến buổi phỏng vấn.)","These wool [trousers] are perfect for cold winter days. (=Dịch: Chiếc quần tây bằng len này rất hoàn hảo cho những ngày mùa đông lạnh giá.)","She asked the tailor to shorten her new [trousers]. (=Dịch: Cô ấy đã nhờ thợ may cắt ngắn chiếc quần dài mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=trousers&lang=en-GB&ipa=%2F%CB%88tra%CA%8A.z%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=trousers&lang=en-US&ipa=%2F%CB%88tra%CA%8A.z%C9%9Az%2F"},{"id":"lv_1_102","topic":"Job Seeking and Work","word":"unemployed","pos":"(adj)","ipa":"/ˌʌn.ɪmˈplɔɪd/","defVi":"thất nghiệp","defEn":"without a paid job but available to work","examples":["Many recent graduates find themselves [unemployed] due to a competitive job market. (=Dịch: Nhiều sinh viên mới tốt nghiệp rơi vào cảnh thất nghiệp do thị trường việc làm đầy tính cạnh tranh.)","The government provides financial support to [unemployed] citizens while they seek work. (=Dịch: Chính phủ hỗ trợ tài chính cho các công dân thất nghiệp trong thời gian họ tìm việc làm.)","He has been [unemployed] for six months after the factory closed down. (=Dịch: Anh ấy đã thất nghiệp suốt sáu tháng sau khi nhà máy đóng cửa.)"],"ukAudio":"/ai_services/tts3/?q=unemployed&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unemployed&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AAd%2F"},{"id":"lv_1_103","topic":"Job Seeking and Work","word":"update","pos":"(n)","ipa":"/ˈʌp.deɪt/","defVi":"bản cập nhật, thông tin mới nhất","defEn":"the latest information or a new version of something","examples":["The manager gave us a brief [update] on the progress of the project. (=Dịch: Người quản lý đã cung cấp cho chúng tôi thông tin cập nhật ngắn gọn về tiến độ của dự án.)","Make sure you install the latest software [update] to protect your computer. (=Dịch: Hãy chắc chắn rằng bạn đã cài đặt bản cập nhật phần mềm mới nhất để bảo vệ máy tính của mình.)","We are waiting for an official [update] from the local authorities about the weather. (=Dịch: Chúng tôi đang chờ thông tin cập nhật chính thức từ chính quyền địa phương về tình hình thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=update&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=update&lang=en-US&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F"},{"id":"lv_1_104","topic":"Job Seeking and Work","word":"vacancy","pos":"(n)","ipa":"/ˈveɪ.kən.si/","defVi":"vị trí tuyển dụng, chỗ trống (trong công việc hoặc phòng ở)","defEn":"a job or position that is currently available to be filled","examples":["The company recently posted a job [vacancy] for an experienced accountant. (=Dịch: Công ty gần đây đã đăng tuyển một vị trí còn trống cho một kế toán viên giàu kinh nghiệm.)","Due to rapid business expansion, there is a new [vacancy] in our sales department. (=Dịch: Do sự mở rộng kinh doanh nhanh chóng, phòng kinh doanh của chúng tôi đang có một vị trí tuyển dụng mới.)","The hotel had no [vacancy] left during the peak summer holiday. (=Dịch: Khách sạn không còn phòng trống nào trong kỳ nghỉ hè cao điểm.)"],"ukAudio":"/ai_services/tts3/?q=vacancy&lang=en-GB&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=vacancy&lang=en-US&ipa=%2F%CB%88ve%C9%AA.k%C9%99n.si%2F"},{"id":"lv_1_105","topic":"Job Seeking and Work","word":"weekly","pos":"(adj)","ipa":"/ˈwiːk.li/","defVi":"hàng tuần, mỗi tuần một lần","defEn":"happening, done, or published once a week","examples":["Our team holds a [weekly] meeting every Monday morning. (=Dịch: Nhóm chúng tôi tổ chức một cuộc họp hàng tuần vào mỗi sáng thứ Hai.)","The local newspaper publishes a [weekly] sports report. (=Dịch: Tờ báo địa phương xuất bản một bản tin thể thao hàng tuần.)","She receives a [weekly] allowance from her parents for food and travel. (=Dịch: Cô ấy nhận được tiền tiêu vặt hàng tuần từ bố mẹ để chi trả cho ăn uống và đi lại.)"],"ukAudio":"/ai_services/tts3/?q=weekly&lang=en-GB&ipa=%2F%CB%88wi%CB%90k.li%2F","usAudio":"/ai_services/tts3/?q=weekly&lang=en-US&ipa=%2F%CB%88wi%CB%90k.li%2F"},{"id":"lv_1_106","topic":"Job Seeking and Work","word":"wipe","pos":"(v)","ipa":"/waɪp/","defVi":"lau, chùi, xóa sạch","defEn":"to clean or dry something by rubbing a cloth or towel over its surface","examples":["Please [wipe] the kitchen table after finishing your dinner. (=Dịch: Vui lòng lau bàn bếp sau khi ăn tối xong.)","He used a soft cloth to [wipe] the dust off the computer screen. (=Dịch: Anh ấy đã dùng một chiếc khăn mềm để lau sạch bụi trên màn hình máy tính.)","She had to [wipe] away her tears before walking into the interview room. (=Dịch: Cô ấy phải gạt đi những giọt nước mắt trước khi bước vào phòng phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=wipe&lang=en-GB&ipa=%2Fwa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=wipe&lang=en-US&ipa=%2Fwa%C9%AAp%2F"},{"id":"lv_1_107","topic":"Job Seeking and Work","word":"workplace","pos":"(n)","ipa":"/ˈwɜːrk.pleɪs/","defVi":"nơi làm việc, môi trường công sở","defEn":"a building or place where people work","examples":["Modern technology enables employees to collaborate without being in the same physical [workplace]. (=Dịch: Công nghệ hiện đại cho phép nhân viên cộng tác mà không cần phải ở cùng một nơi làm việc cụ thể.)","Companies must establish strict safety standards to prevent accidents in the [workplace]. (=Dịch: Các công ty phải thiết lập các tiêu chuẩn an toàn nghiêm ngặt để ngăn ngừa tai nạn tại nơi làm việc.)","A supportive [workplace] environment can significantly boost staff morale and productivity. (=Dịch: Một môi trường làm việc mang tính hỗ trợ có thể nâng cao đáng kể tinh thần và năng suất của nhân viên.)"],"ukAudio":"/ai_services/tts3/?q=workplace&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90rk.ple%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=workplace&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90rk.ple%C9%AAs%2F"}]},"rawTopic":"Job Seeking and Work"},{"id":"listening_u5_3","title":"Chủ đề 3/10: Tourism and Visits","actTitle":"Từ vựng chủ đề: Tourism and Visits (151 từ)","problem":{"pType":"topic_flashcards","topic":"Tourism and Visits","count":151,"words":[{"id":"lv_2_0","topic":"Tourism and Visits","word":"alley","pos":"(n)","ipa":"/ˈæl.i/","defVi":"con hẻm, ngõ nhỏ","defEn":"a narrow passageway between buildings","examples":["The cat slipped into a dark [alley] behind the restaurant. (=Dịch: Con mèo lẻn vào một con hẻm tối phía sau nhà hàng.)","There is a charming little coffee shop hidden in this [alley]. (=Dịch: Có một quán cà phê nhỏ xinh xắn ẩn mình trong con hẻm này.)","Tourists were advised not to walk down the deserted [alley] at night. (=Dịch: Khách du lịch được khuyên không nên đi vào con hẻm vắng vẻ vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=alley&lang=en-GB&ipa=%2F%CB%88%C3%A6l.i%2F","usAudio":"/ai_services/tts3/?q=alley&lang=en-US&ipa=%2F%CB%88%C3%A6l.i%2F"},{"id":"lv_2_1","topic":"Tourism and Visits","word":"approx","pos":"(adj)","ipa":"/əˈprɑːks/","defVi":"xấp xỉ, khoảng chừng (viết tắt của approximate)","defEn":"short form for approximate; roughly correct or close to the actual number","examples":["The [approx] cost of the flight is around three hundred dollars. (=Dịch: Chi phí xấp xỉ của chuyến bay là khoảng ba trăm đô la.)","Please write down the [approx] arrival time on the registration form. (=Dịch: Vui lòng ghi lại thời gian đến ước tính vào mẫu đăng ký.)","The table shows the [approx] number of visitors each month. (=Dịch: Bảng hiển thị số lượng khách tham quan ước tính mỗi tháng.)"],"ukAudio":"/ai_services/tts3/?q=approx&lang=en-GB&ipa=%2F%C9%99%CB%88pr%C9%91%CB%90ks%2F","usAudio":"/ai_services/tts3/?q=approx&lang=en-US&ipa=%2F%C9%99%CB%88pr%C9%91%CB%90ks%2F"},{"id":"lv_2_2","topic":"Tourism and Visits","word":"aquarium","pos":"(n)","ipa":"/əˈkwer.i.əm/","defVi":"thủy cung, bể cá","defEn":"a building or large glass container where fish and other water creatures are kept and displayed","examples":["The children were excited to visit the city [aquarium] to see sharks. (=Dịch: Những đứa trẻ rất hào hứng khi được đến thăm thủy cung thành phố để ngắm cá mập.)","He keeps several colorful tropical fish in a small [aquarium] in his living room. (=Dịch: Anh ấy nuôi vài con cá nhiệt đới sặc sỡ trong một bể cá nhỏ ở phòng khách.)","The public [aquarium] plays a vital role in marine education and conservation. (=Dịch: Thủy cung công cộng đóng vai trò thiết yếu trong việc giáo dục và bảo tồn sinh vật biển.)"],"ukAudio":"/ai_services/tts3/?q=aquarium&lang=en-GB&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=aquarium&lang=en-US&ipa=%2F%C9%99%CB%88kwer.i.%C9%99m%2F"},{"id":"lv_2_3","topic":"Tourism and Visits","word":"arrow","pos":"(n)","ipa":"/ˈer.oʊ/","defVi":"mũi tên","defEn":"a thin straight weapon shot from a bow, or a symbol used to show direction","examples":["Follow the green [arrow] on the floor to find the exit. (=Dịch: Hãy đi theo mũi tên màu xanh lá cây trên sàn để tìm lối ra.)","The archer placed an [arrow] on the bowstring and aimed carefully. (=Dịch: Người bắn cung đặt một mũi tên lên dây cung và nhắm cẩn thận.)","A red [arrow] indicated that traffic was not allowed to turn right. (=Dịch: Mũi tên màu đỏ chỉ ra rằng các phương tiện giao thông không được phép rẽ phải.)"],"ukAudio":"/ai_services/tts3/?q=arrow&lang=en-GB&ipa=%2F%CB%88er.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=arrow&lang=en-US&ipa=%2F%CB%88er.o%CA%8A%2F"},{"id":"lv_2_4","topic":"Tourism and Visits","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"điểm thu hút, điểm tham quan hấp dẫn","defEn":"an interesting or enjoyable place or feature that draws people to visit","examples":["The ancient temple is the main tourist [attraction] in this town. (=Dịch: Ngôi đền cổ kính là điểm thu hút khách du lịch chính tại thị trấn này.)","Theme parks offer a wide variety of rides and [attractions] for families. (=Dịch: Các công viên giải trí cung cấp nhiều trò chơi và điểm tham quan đa dạng cho các gia đình.)","The historical museum has become a popular [attraction] for students. (=Dịch: Bảo tàng lịch sử đã trở thành một điểm đến phổ biến đối với học sinh, sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_2_5","topic":"Tourism and Visits","word":"audio","pos":"(adj)","ipa":"/ˈɑː.di.oʊ/","defVi":"(thuộc) âm thanh","defEn":"connected with recorded sound or the transmission of sound","examples":["Students can listen to the [audio] recording to practice their listening skills. (=Dịch: Học sinh có thể nghe đoạn ghi âm để luyện tập kỹ năng nghe của mình.)","The museum provides a free [audio] tour in several languages. (=Dịch: Bảo tàng cung cấp tour thuyết minh bằng âm thanh miễn phí bằng nhiều thứ tiếng.)","The video had clear pictures, but the [audio] quality was quite poor. (=Dịch: Video có hình ảnh rõ nét, nhưng chất lượng âm thanh lại khá kém.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F"},{"id":"lv_2_6","topic":"Tourism and Visits","word":"barn","pos":"(n)","ipa":"/bɑːrn/","defVi":"chuồng trại, kho thóc","defEn":"a large farm building used for storing crops or keeping animals","examples":["The farmer gathered the cows and led them into the [barn] for the night. (=Dịch: Người nông dân lùa đàn bò lại và dẫn chúng vào chuồng để qua đêm.)","They converted the old wooden [barn] into a modern event venue. (=Dịch: Họ đã cải tạo nhà kho bằng gỗ cũ thành một địa điểm tổ chức sự kiện hiện đại.)","Piles of dry hay were neatly stacked inside the [barn]. (=Dịch: Những đống cỏ khô được xếp ngay ngắn bên trong nhà kho.)"],"ukAudio":"/ai_services/tts3/?q=barn&lang=en-GB&ipa=%2Fb%C9%91%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=barn&lang=en-US&ipa=%2Fb%C9%91%CB%90rn%2F"},{"id":"lv_2_7","topic":"Tourism and Visits","word":"basket","pos":"(n)","ipa":"/ˈbæs.kɪt/","defVi":"cái rổ, cái giỏ","defEn":"a container made of woven strips of cane, wire, or plastic, often used for carrying things","examples":["She filled her woven [basket] with fresh apples picked from the orchard. (=Dịch: Cô chất đầy chiếc giỏ đan bằng những quả táo tươi hái từ vườn cây ăn quả.)","Don't forget to put dirty clothes into the laundry [basket]. (=Dịch: Đừng quên cho quần áo bẩn vào giỏ đựng đồ giặt.)","The delivery cyclist carried a metal [basket] attached to the front handlebars. (=Dịch: Người đi xe đạp giao hàng mang theo một chiếc giỏ kim loại gắn vào ghi-đông phía trước.)"],"ukAudio":"/ai_services/tts3/?q=basket&lang=en-GB&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=basket&lang=en-US&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F"},{"id":"lv_2_8","topic":"Tourism and Visits","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a part of the coast where the land curves inward to form an open body of water","examples":["Several fishing boats were anchored peacefully in the sheltered [bay]. (=Dịch: Vài chiếc thuyền đánh cá đang neo đậu yên bình trong vùng vịnh kín gió.)","The resort hotel offers stunning panoramic views across the [bay]. (=Dịch: Khách sạn nghỉ dưỡng có tầm nhìn toàn cảnh tuyệt đẹp ra khắp vịnh.)","We went sailing around the [bay] on a sunny afternoon. (=Dịch: Chúng tôi đã đi chèo thuyền buồm quanh vịnh vào một buổi chiều đầy nắng.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_2_9","topic":"Tourism and Visits","word":"bc","pos":"(adv)","ipa":"/ˌbiː ˈsiː/","defVi":"trước Công nguyên (TCN)","defEn":"used after a date to refer to the years before the birth of Jesus Christ (Before Christ)","examples":["The great pyramid was built around 2560 [BC]. (=Dịch: Đại kim tự tháp được xây dựng vào khoảng năm 2560 trước Công nguyên.)","The ancient civilization flourished during the fifth century [BC]. (=Dịch: Nền văn minh cổ đại đã phát triển rực rỡ trong thế kỷ thứ năm trước Công nguyên.)","Historians believe the city was founded in 753 [BC]. (=Dịch: Các nhà sử học tin rằng thành phố được thành lập vào năm 753 trước Công nguyên.)"],"ukAudio":"/ai_services/tts3/?q=bc&lang=en-GB&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F","usAudio":"/ai_services/tts3/?q=bc&lang=en-US&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F"},{"id":"lv_2_10","topic":"Tourism and Visits","word":"biking","pos":"(n)","ipa":"/ˈbaɪ.kɪŋ/","defVi":"hoạt động đi xe đạp","defEn":"the activity of riding a bicycle for pleasure, sport, or transport","examples":["Mountain [biking] has become a very popular outdoor sport among teenagers. (=Dịch: Đạp xe leo núi đã trở thành một môn thể thao ngoài trời rất phổ biến trong giới thanh thiếu niên.)","She goes [biking] along the river every weekend to stay in shape. (=Dịch: Cô ấy đạp xe dọc bờ sông vào mỗi cuối tuần để giữ gìn vóc dáng.)","The city added more lanes to encourage [biking] instead of driving cars. (=Dịch: Thành phố đã bổ sung thêm nhiều làn đường để khuyến khích việc đi xe đạp thay vì lái xe ô tô.)"],"ukAudio":"/ai_services/tts3/?q=biking&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.k%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=biking&lang=en-US&ipa=%2F%CB%88ba%C9%AA.k%C9%AA%C5%8B%2F"},{"id":"lv_2_11","topic":"Tourism and Visits","word":"bow","pos":"(n)","ipa":"/boʊ/","defVi":"cung tên hoặc nơ (trang trí)","defEn":"a weapon for shooting arrows, or a knot tied with loops used for decoration","examples":["He pulled the string of the [bow] and aimed carefully at the target. (=Dịch: Anh ấy kéo dây cung và nhắm cẩn thận vào mục tiêu.)","She wore a bright red [bow] in her hair for the birthday party. (=Dịch: Cô ấy cài một chiếc nơ màu đỏ tươi trên tóc để dự tiệc sinh nhật.)","The gift box was decorated with a large golden [bow]. (=Dịch: Hộp quà được trang trí bằng một chiếc nơ lớn màu vàng kim.)"],"ukAudio":"/ai_services/tts3/?q=bow&lang=en-GB&ipa=%2Fbo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=bow&lang=en-US&ipa=%2Fbo%CA%8A%2F"},{"id":"lv_2_12","topic":"Tourism and Visits","word":"campsite","pos":"(n)","ipa":"/ˈkæmp.saɪt/","defVi":"địa điểm cắm trại, khu cắm trại","defEn":"a piece of land where people can set up tents or park caravans for camping","examples":["We arrived at the [campsite] just before the sun began to set. (=Dịch: Chúng tôi đến khu cắm trại ngay trước khi mặt trời bắt đầu lặn.)","The [campsite] provides clean running water and basic cooking facilities. (=Dịch: Khu cắm trại cung cấp nước máy sạch và các tiện nghi nấu nướng cơ bản.)","You need to book your spot at the [campsite] weeks in advance during summer. (=Dịch: Bạn cần phải đặt chỗ tại khu cắm trại trước nhiều tuần vào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=campsite&lang=en-GB&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=campsite&lang=en-US&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F"},{"id":"lv_2_13","topic":"Tourism and Visits","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"Canada (quốc gia ở Bắc Mỹ)","defEn":"a large country located in the northern part of North America","examples":["Many international students choose to study in [Canada] for its high-quality education. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Canada vì nền giáo dục chất lượng cao của đất nước này.)","Winters in [Canada] can be extremely cold and snowy. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá và nhiều tuyết.)","He decided to immigrate to [Canada] with his family last year. (=Dịch: Anh ấy đã quyết định cùng gia đình nhập cư sang Canada vào năm ngoái.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_2_14","topic":"Tourism and Visits","word":"cart","pos":"(n)","ipa":"/kɑːrt/","defVi":"xe đẩy hàng, xe kéo","defEn":"a small vehicle with wheels that is pulled or pushed by a person, animal, or machine","examples":["She filled her shopping [cart] with fresh fruits and vegetables. (=Dịch: Cô ấy chất đầy trái cây và rau củ tươi vào xe đẩy mua sắm của mình.)","The farmer used a wooden [cart] pulled by a horse to transport hay. (=Dịch: Người nông dân đã dùng một chiếc xe kéo bằng gỗ do ngựa kéo để vận chuyển cỏ khô.)","Hotel staff loaded our luggage onto a luggage [cart] and brought it to our room. (=Dịch: Nhân viên khách sạn đã xếp hành lý của chúng tôi lên xe đẩy hành lý và mang lên phòng cho chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=cart&lang=en-GB&ipa=%2Fk%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=cart&lang=en-US&ipa=%2Fk%C9%91%CB%90rt%2F"},{"id":"lv_2_15","topic":"Tourism and Visits","word":"cave","pos":"(n)","ipa":"/keɪv/","defVi":"hang, hang động","defEn":"a large natural hole in the side of a cliff, hill, or under the ground","examples":["The hikers found shelter in a dry [cave] when the heavy rain started. (=Dịch: Những người đi bộ đường dài đã tìm nơi trú ẩn trong một hang động khô ráo khi cơn mưa lớn bắt đầu đổ xuống.)","Scientists discovered ancient paintings on the walls of the [cave]. (=Dịch: Các nhà khoa học đã phát hiện ra những bức tranh cổ trên vách hang động.)","Bears often hibernate inside a dark [cave] during the cold winter months. (=Dịch: Gấu thường ngủ đông bên trong một hang động tối tăm suốt những tháng mùa đông lạnh giá.)"],"ukAudio":"/ai_services/tts3/?q=cave&lang=en-GB&ipa=%2Fke%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cave&lang=en-US&ipa=%2Fke%C9%AAv%2F"},{"id":"lv_2_16","topic":"Tourism and Visits","word":"cliff","pos":"(n)","ipa":"/klɪf/","defVi":"vách đá dốc, vách núi","defEn":"a high area of rock with a very steep side, often near the sea","examples":["They stood on the edge of the high [cliff] looking out over the ocean. (=Dịch: Họ đứng trên mép của vách đá cao và phóng tầm mắt nhìn ra đại dương.)","Warning signs were placed near the [cliff] to prevent tourists from falling. (=Dịch: Các biển cảnh báo đã được đặt gần vách đá để ngăn du khách bị trượt chân ngã.)","Seabirds build their nests safely on the narrow ledges of the [cliff]. (=Dịch: Các loài chim biển làm tổ an toàn trên những gờ hẹp của vách đá.)"],"ukAudio":"/ai_services/tts3/?q=cliff&lang=en-GB&ipa=%2Fkl%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=cliff&lang=en-US&ipa=%2Fkl%C9%AAf%2F"},{"id":"lv_2_17","topic":"Tourism and Visits","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng gửi áo khoác và hành lý","defEn":"a room in a public building where people can leave their coats and bags","examples":["Please leave your heavy coats and backpacks in the [cloakroom] before entering the gallery. (=Dịch: Vui lòng để lại áo khoác dày và ba lô trong phòng giữ đồ trước khi vào phòng trưng bày.)","The theater attendant gave her a ticket after taking her coat at the [cloakroom]. (=Dịch: Nhân viên nhà hát đã đưa cho cô ấy một chiếc vé sau khi nhận áo khoác của cô ở phòng giữ đồ.)","There was a long line at the [cloakroom] after the concert ended. (=Dịch: Có một hàng dài người chờ ở phòng giữ đồ sau khi buổi hòa nhạc kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_2_18","topic":"Tourism and Visits","word":"cloth","pos":"(n)","ipa":"/klɔːθ/","defVi":"vải, mảnh vải (để lau chùi hoặc may mặc)","defEn":"material made by weaving cotton, wool, or other fibers, used for making clothes or covers","examples":["She used a damp [cloth] to wipe the dust off the wooden table. (=Dịch: Cô ấy dùng một chiếc khăn ẩm để lau sạch bụi bám trên bàn gỗ.)","This expensive [cloth] is made from pure natural silk. (=Dịch: Loại vải đắt tiền này được làm từ lụa tự nhiên nguyên chất.)","He wrapped the fragile glass vase in a soft piece of [cloth]. (=Dịch: Anh ấy đã bọc chiếc bình thủy tinh dễ vỡ trong một mảnh vải mềm.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F"},{"id":"lv_2_19","topic":"Tourism and Visits","word":"coastline","pos":"(n)","ipa":"/ˈkoʊst.laɪn/","defVi":"đường bờ biển","defEn":"the boundary where the land meets the sea or ocean","examples":["Vietnam has a long [coastline] with many beautiful sandy beaches. (=Dịch: Việt Nam có đường bờ biển dài với nhiều bãi biển cát trắng tuyệt đẹp.)","Severe storms have caused significant erosion along the southern [coastline]. (=Dịch: Những cơn bão dữ dội đã gây ra sự xói mòn nghiêm trọng dọc theo đường bờ biển phía nam.)","We drove along the scenic [coastline] and enjoyed the stunning ocean views. (=Dịch: Chúng tôi đã lái xe dọc theo đường bờ biển tuyệt đẹp và thưởng ngoạn khung cảnh đại dương tuyệt trần.)"],"ukAudio":"/ai_services/tts3/?q=coastline&lang=en-GB&ipa=%2F%CB%88ko%CA%8Ast.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coastline&lang=en-US&ipa=%2F%CB%88ko%CA%8Ast.la%C9%AAn%2F"},{"id":"lv_2_20","topic":"Tourism and Visits","word":"commentary","pos":"(n)","ipa":"/ˈkɑː.mən.ter.i/","defVi":"lời bình luận, tường thuật trực tiếp","defEn":"a spoken or written description and analysis of an event or topic as it happens","examples":["The sports journalist provided live [commentary] during the final match. (=Dịch: Nhà báo thể thao đã bình luận trực tiếp trong suốt trận chung kết.)","Her political [commentary] is published weekly in the local newspaper. (=Dịch: Bài bình luận chính trị của bà được xuất bản hàng tuần trên tờ báo địa phương.)","The museum audio guide offers detailed [commentary] on each art piece. (=Dịch: Thiết bị thuyết minh tự động của bảo tàng cung cấp lời bình giải chi tiết về từng tác phẩm nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=commentary&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F","usAudio":"/ai_services/tts3/?q=commentary&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F"},{"id":"lv_2_21","topic":"Tourism and Visits","word":"compass","pos":"(n)","ipa":"/ˈkʌm.pəs/","defVi":"la bàn","defEn":"an instrument containing a magnetized pointer that shows the direction of magnetic north","examples":["Hikers should always carry a map and a [compass] when exploring remote trails. (=Dịch: Người đi bộ đường dài nên luôn mang theo bản đồ và la bàn khi khám phá những con đường mòn hẻo lánh.)","The sailor checked the ship's [compass] to make sure they were heading north. (=Dịch: Người thủy thủ đã kiểm tra la bàn của tàu để đảm bảo họ đang đi về hướng bắc.)","He used a [compass] to navigate through the dense forest. (=Dịch: Anh ấy đã dùng la bàn để định hướng băng qua khu rừng rậm rạp.)"],"ukAudio":"/ai_services/tts3/?q=compass&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=compass&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F"},{"id":"lv_2_22","topic":"Tourism and Visits","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or company that competes against others","examples":["Each [competitor] in the marathon trained hard for several months. (=Dịch: Mỗi vận động viên trong cuộc chạy marathon đều đã tập luyện chăm chỉ trong nhiều tháng.)","The tech firm lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty công nghệ đã hạ giá để duy trì vị thế dẫn trước đối thủ cạnh tranh chính của mình.)","Judges evaluated every [competitor] based on creativity and technique. (=Dịch: Ban giám khảo đã đánh giá từng thí sinh dựa trên tính sáng tạo và kỹ thuật.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_2_23","topic":"Tourism and Visits","word":"conservatory","pos":"(n)","ipa":"/kənˈsɝː.və.tɔːr.i/","defVi":"nhà kính trồng cây; nhạc viện","defEn":"a glass room used to grow plants, or a school specializing in music and the arts","examples":["They enjoyed their morning coffee sitting in the sunny [conservatory]. (=Dịch: Họ thưởng thức cà phê buổi sáng khi ngồi trong nhà kính ngập tràn ánh nắng.)","She studied classical violin at a prestigious music [conservatory]. (=Dịch: Cô ấy đã theo học vĩ cầm cổ điển tại một nhạc viện danh tiếng.)","The botanical garden built a large [conservatory] to protect tropical plants. (=Dịch: Vườn bách thảo đã xây dựng một nhà kính lớn để bảo vệ các loài thực vật nhiệt đới.)"],"ukAudio":"/ai_services/tts3/?q=conservatory&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%9D%CB%90.v%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=conservatory&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%9D%CB%90.v%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_2_24","topic":"Tourism and Visits","word":"costume","pos":"(n)","ipa":"/ˈkɑːs.tuːm/","defVi":"trang phục (biểu diễn, hóa trang hoặc truyền thống)","defEn":"a set of clothes worn by an actor or for a particular occasion or historical period","examples":["The actors spent hours putting on their makeup and [costume] before the play began. (=Dịch: Các diễn viên đã dành hàng giờ để trang điểm và mặc trang phục trước khi vở kịch bắt đầu.)","Children wore a colorful [costume] for the annual Halloween parade. (=Dịch: Trẻ em đã mặc trang phục rực rỡ sắc màu cho buổi diễu hành Halloween thường niên.)","The museum displays traditional folk [costume] from various regions. (=Dịch: Bảo tàng trưng bày trang phục dân gian truyền thống từ nhiều vùng miền khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90s.tu%CB%90m%2F"},{"id":"lv_2_25","topic":"Tourism and Visits","word":"county","pos":"(n)","ipa":"/ˈkaʊn.t̬i/","defVi":"quận, hạt, tỉnh (đơn vị hành chính)","defEn":"a territorial division of a country or state for administrative purposes","examples":["He was elected as the sheriff of the entire [county]. (=Dịch: Ông được bầu làm cảnh sát trưởng của toàn bộ hạt.)","The [county] council decided to fund the construction of a new library. (=Dịch: Hội đồng hạt đã quyết định cấp kinh phí xây dựng một thư viện mới.)","Many rural schools in this [county] share resources to save money. (=Dịch: Nhiều trường học nông thôn ở hạt này chia sẻ tài nguyên để tiết kiệm chi phí.)"],"ukAudio":"/ai_services/tts3/?q=county&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=county&lang=en-US&ipa=%2F%CB%88ka%CA%8An.t%CC%ACi%2F"},{"id":"lv_2_26","topic":"Tourism and Visits","word":"creature","pos":"(n)","ipa":"/ˈkriː.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"a living being, especially an animal rather than a human or plant","examples":["Deep-sea divers discovered a strange [creature] near the ocean floor. (=Dịch: Những thợ lặn biển sâu đã phát hiện ra một sinh vật kỳ lạ gần đáy đại dương.)","The rainforest is home to many rare [creature] species. (=Dịch: Rừng mưa nhiệt đới là nơi sinh sống của nhiều loài sinh vật quý hiếm.)","Nighttime brings out every nocturnal [creature] in the forest. (=Dịch: Màn đêm đánh thức mọi sinh vật sống về đêm trong khu rừng.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_2_27","topic":"Tourism and Visits","word":"crocodile","pos":"(n)","ipa":"/ˈkrɑː.kə.daɪl/","defVi":"cá sấu","defEn":"a large predatory reptile with a long snout and powerful jaws that lives in tropical wetlands","examples":["A large [crocodile] basked silently in the sun beside the riverbank. (=Dịch: Một con cá sấu lớn lặng lẽ sưởi nắng bên bờ sông.)","Tourists took a boat trip to watch the wild [crocodile] hunt in the marsh. (=Dịch: Khách du lịch đã đi thuyền để quan sát cá sấu hoang dã săn mồi trong đầm lầy.)","Warning signs were placed near the lake to keep people away from any [crocodile]. (=Dịch: Các biển cảnh báo đã được đặt gần hồ để nhắc nhở mọi người tránh xa cá sấu.)"],"ukAudio":"/ai_services/tts3/?q=crocodile&lang=en-GB&ipa=%2F%CB%88kr%C9%91%CB%90.k%C9%99.da%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=crocodile&lang=en-US&ipa=%2F%CB%88kr%C9%91%CB%90.k%C9%99.da%C9%AAl%2F"},{"id":"lv_2_28","topic":"Tourism and Visits","word":"cruise","pos":"(n)","ipa":"/kruːz/","defVi":"chuyến du ngoạn bằng tàu thủy, chuyến du thuyền","defEn":"a vacation trip on a ship or boat that visits several places","examples":["They booked a two-week Caribbean [cruise] to celebrate their anniversary. (=Dịch: Họ đã đặt một chuyến du ngoạn Caribe bằng du thuyền kéo dài hai tuần để kỷ niệm ngày cưới.)","The evening river [cruise] offered beautiful views of the illuminated city skyline. (=Dịch: Chuyến du ngoạn trên sông vào buổi tối mang lại tầm nhìn tuyệt đẹp ngắm toàn cảnh thành phố rực rỡ ánh đèn.)","Passengers enjoyed gourmet meals and live entertainment during the luxury [cruise]. (=Dịch: Hành khách đã thưởng thức những bữa ăn hảo hạng và các chương trình giải trí trực tiếp trong suốt chuyến hải trình sang trọng.)"],"ukAudio":"/ai_services/tts3/?q=cruise&lang=en-GB&ipa=%2Fkru%CB%90z%2F","usAudio":"/ai_services/tts3/?q=cruise&lang=en-US&ipa=%2Fkru%CB%90z%2F"},{"id":"lv_2_29","topic":"Tourism and Visits","word":"dairy","pos":"(n)","ipa":"/ˈder.i/","defVi":"sản phẩm từ sữa; nông trại chế biến sữa","defEn":"food made from milk, or a farm and building where milk and milk products are produced","examples":["People with lactose intolerance must avoid consuming too much [dairy]. (=Dịch: Những người không dung nạp lactose phải tránh tiêu thụ quá nhiều sản phẩm từ sữa.)","The local [dairy] delivers fresh milk and butter to grocery stores every morning. (=Dịch: Cơ sở sản xuất sữa địa phương giao sữa tươi và bơ đến các cửa hàng tạp hóa vào mỗi buổi sáng.)","Cheese and yogurt are rich sources of calcium found in the [dairy] aisle. (=Dịch: Phô mai và sữa chua là những nguồn giàu canxi có thể tìm thấy ở quầy hàng bơ sữa.)"],"ukAudio":"/ai_services/tts3/?q=dairy&lang=en-GB&ipa=%2F%CB%88der.i%2F","usAudio":"/ai_services/tts3/?q=dairy&lang=en-US&ipa=%2F%CB%88der.i%2F"},{"id":"lv_2_30","topic":"Tourism and Visits","word":"daylight","pos":"(n)","ipa":"/ˈdeɪ.laɪt/","defVi":"ánh sáng ban ngày, ban ngày","defEn":"the natural light that comes from the sun during the daytime","examples":["We should try to finish the hike while there is still [daylight]. (=Dịch: Chúng ta nên cố gắng hoàn thành chuyến đi bộ đường dài khi trời vẫn còn ánh sáng ban ngày.)","The artist prefers painting in natural [daylight] rather than under lamps. (=Dịch: Họa sĩ thích vẽ tranh dưới ánh sáng tự nhiên ban ngày hơn là dưới ánh đèn.)","The thieves committed the robbery in broad [daylight]. (=Dịch: Những tên trộm đã thực hiện vụ cướp ngay giữa ban ngày.)"],"ukAudio":"/ai_services/tts3/?q=daylight&lang=en-GB&ipa=%2F%CB%88de%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=daylight&lang=en-US&ipa=%2F%CB%88de%C9%AA.la%C9%AAt%2F"},{"id":"lv_2_31","topic":"Tourism and Visits","word":"destination","pos":"(n)","ipa":"/ˌdes.təˈneɪ.ʃən/","defVi":"điểm đến, đích đến","defEn":"the place where someone or something is going","examples":["Paris is one of the most popular tourist [destination]s in the world. (=Dịch: Paris là một trong những điểm đến du lịch nổi tiếng nhất trên thế giới.)","After six hours of driving, we finally reached our [destination]. (=Dịch: Sau sáu giờ lái xe, cuối cùng chúng tôi cũng đã đến được điểm đến của mình.)","The package took over a week to arrive at its final [destination]. (=Dịch: Gói hàng đã mất hơn một tuần để tới được điểm đến cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=destination&lang=en-GB&ipa=%2F%CB%8Cdes.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destination&lang=en-US&ipa=%2F%CB%8Cdes.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_2_32","topic":"Tourism and Visits","word":"dining","pos":"(n)","ipa":"/ˈdaɪ.nɪŋ/","defVi":"việc ăn uống, dùng bữa","defEn":"the act of eating a meal, especially dinner in a restaurant or formal setting","examples":["The resort offers a variety of fine [dining] options for its guests. (=Dịch: Khu nghỉ dưỡng cung cấp nhiều lựa chọn ẩm thực cao cấp cho du khách.)","We gathered around the large [dining] table for Sunday lunch. (=Dịch: Chúng tôi quây quần quanh bàn ăn lớn cho bữa trưa Chủ nhật.)","Outdoor [dining] has become very popular during the summer months. (=Dịch: Ăn uống ngoài trời đã trở nên rất phổ biến trong những tháng mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=dining&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dining&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_2_33","topic":"Tourism and Visits","word":"dinosaur","pos":"(n)","ipa":"/ˈdaɪ.nə.sɔːr/","defVi":"khủng long","defEn":"a large reptile that lived millions of years ago and is now extinct","examples":["Children love visiting the museum to see the giant [dinosaur] fossils. (=Dịch: Trẻ em rất thích đến bảo tàng để ngắm nhìn những hóa thạch khủng long khổng lồ.)","Scientists believe a huge asteroid caused the extinction of the [dinosaur]s. (=Dịch: Các nhà khoa học tin rằng một tiểu hành tinh khổng lồ đã khiến loài khủng long bị tuyệt chủng.)","He is reading a fascinating book about carnivorous [dinosaur] species. (=Dịch: Cậu ấy đang đọc một cuốn sách hấp dẫn về các loài khủng long ăn thịt.)"],"ukAudio":"/ai_services/tts3/?q=dinosaur&lang=en-GB&ipa=%2F%CB%88da%C9%AA.n%C9%99.s%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=dinosaur&lang=en-US&ipa=%2F%CB%88da%C9%AA.n%C9%99.s%C9%94%CB%90r%2F"},{"id":"lv_2_34","topic":"Tourism and Visits","word":"eagle","pos":"(n)","ipa":"/ˈiː.ɡəl/","defVi":"chim đại bàng","defEn":"a large bird of prey with a sharp beak and powerful eyesight","examples":["A golden [eagle] soared gracefully high above the mountain peaks. (=Dịch: Một con đại bàng vàng bay lượn duyên dáng trên đỉnh núi cao.)","The bald [eagle] is an official national symbol of the United States. (=Dịch: Đại bàng đầu trắng là biểu tượng quốc gia chính thức của Hoa Kỳ.)","Using its keen vision, the [eagle] spotted a fish swimming near the surface. (=Dịch: Nhờ thị lực nhạy bén, con đại bàng đã phát hiện ra một con cá đang bơi gần mặt nước.)"],"ukAudio":"/ai_services/tts3/?q=eagle&lang=en-GB&ipa=%2F%CB%88i%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=eagle&lang=en-US&ipa=%2F%CB%88i%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_2_35","topic":"Tourism and Visits","word":"educational","pos":"(adj)","ipa":"/ˌedʒ.əˈkeɪ.ʃən.əl/","defVi":"mang tính giáo dục, thuộc về giáo dục","defEn":"providing useful knowledge or connected with the process of teaching and learning","examples":["Documentaries can be both entertaining and highly [educational]. (=Dịch: Phim tài liệu có thể vừa mang tính giải trí vừa có tính giáo dục cao.)","The school organized an [educational] trip to the science centre. (=Dịch: Trường học đã tổ chức một chuyến đi học tập trải nghiệm tới trung tâm khoa học.)","Many mobile apps are designed to support early [educational] development in children. (=Dịch: Nhiều ứng dụng di động được thiết kế nhằm hỗ trợ sự phát triển giáo dục sớm ở trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=educational&lang=en-GB&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=educational&lang=en-US&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_2_36","topic":"Tourism and Visits","word":"enlarge","pos":"(v)","ipa":"/ɪnˈlɑːrdʒ/","defVi":"mở rộng, phóng to","defEn":"to make something bigger or to become bigger","examples":["The company plans to [enlarge] its headquarters to accommodate new employees. (=Dịch: Công ty có kế hoạch mở rộng trụ sở chính để tiếp nhận thêm nhân viên mới.)","Can you [enlarge] this photograph so we can frame it on the wall? (=Dịch: Bạn có thể phóng to bức ảnh này để chúng tôi đóng khung treo lên tường không?)","Reading widely helps to [enlarge] your vocabulary significantly. (=Dịch: Đọc sách nhiều giúp mở rộng vốn từ vựng của bạn một cách đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=enlarge&lang=en-GB&ipa=%2F%C9%AAn%CB%88l%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=enlarge&lang=en-US&ipa=%2F%C9%AAn%CB%88l%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_2_37","topic":"Tourism and Visits","word":"estate","pos":"(n)","ipa":"/ɪˈsteɪt/","defVi":"bất động sản, khu đất rộng, di sản","defEn":"a large area of land in the country, usually with a large house, or all the property owned by someone","examples":["The wealthy family owns a massive country [estate] in England. (=Dịch: Gia đình giàu có này sở hữu một điền trang rộng lớn ở vùng nông thôn nước Anh.)","After his grandfather passed away, he inherited a substantial real [estate] portfolio. (=Dịch: Sau khi ông qua đời, anh ấy đã thừa kế một danh mục bất động sản đáng kể.)","The city is developing a new industrial [estate] on the outskirts. (=Dịch: Thành phố đang phát triển một khu công nghiệp mới ở vùng ngoại ô.)"],"ukAudio":"/ai_services/tts3/?q=estate&lang=en-GB&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=estate&lang=en-US&ipa=%2F%C9%AA%CB%88ste%C9%AAt%2F"},{"id":"lv_2_38","topic":"Tourism and Visits","word":"excursion","pos":"(n)","ipa":"/ɪkˈskɜːr.ʒən/","defVi":"chuyến du ngoạn, chuyến đi chơi ngắn ngày","defEn":"a short journey or trip made for pleasure or leisure","examples":["We went on an all-day boat [excursion] to explore the nearby islands. (=Dịch: Chúng tôi đã tham gia một chuyến du ngoạn bằng thuyền cả ngày để khám phá các hòn đảo lân cận.)","The hotel concierge helped us book a guided [excursion] into the rainforest. (=Dịch: Nhân viên hỗ trợ khách hàng của khách sạn đã giúp chúng tôi đặt một chuyến tham quan có hướng dẫn viên vào rừng nhiệt đới.)","The students enjoyed a weekend [excursion] to the historical museum. (=Dịch: Các học sinh rất hào hứng với chuyến dã ngoại cuối tuần đến bảo tàng lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=excursion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sk%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excursion&lang=en-US&ipa=%2F%C9%AAk%CB%88sk%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_2_39","topic":"Tourism and Visits","word":"exhibit","pos":"(n)","ipa":"/ɪɡˈzɪb.ɪt/","defVi":"vật trưng bày, hiện vật triển lãm","defEn":"an object or a collection of items shown publicly in an exhibition or museum","examples":["The ancient gold crown is the most valuable [exhibit] in the gallery. (=Dịch: Chiếc vương miện vàng cổ là hiện vật có giá trị nhất trong phòng trưng bày.)","Visitors are not allowed to touch any delicate [exhibit] inside the museum. (=Dịch: Khách tham quan không được phép chạm vào bất kỳ hiện vật dễ vỡ nào bên trong bảo tàng.)","The new science [exhibit] features several interactive computer stations. (=Dịch: Khu trưng bày khoa học mới có một số trạm máy tính tương tác.)"],"ukAudio":"/ai_services/tts3/?q=exhibit&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exhibit&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F"},{"id":"lv_2_40","topic":"Tourism and Visits","word":"experimental","pos":"(adj)","ipa":"/ɪkˌsper.əˈmen.t̬əl/","defVi":"mang tính thử nghiệm, thực nghiệm","defEn":"based on new ideas or methods and not yet proven or tested","examples":["The scientists are testing an [experimental] drug to cure the disease. (=Dịch: Các nhà khoa học đang thử nghiệm một loại thuốc thử nghiệm để chữa căn bệnh này.)","The school introduced an [experimental] teaching method to improve student engagement. (=Dịch: Nhà trường đã giới thiệu một phương pháp giảng dạy mang tính thử nghiệm để nâng cao mức độ gắn kết của học sinh.)","His latest album features a lot of [experimental] music. (=Dịch: Album mới nhất của anh ấy có rất nhiều bản nhạc mang tính thể nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=experimental&lang=en-GB&ipa=%2F%C9%AAk%CB%8Csper.%C9%99%CB%88men.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=experimental&lang=en-US&ipa=%2F%C9%AAk%CB%8Csper.%C9%99%CB%88men.t%CC%AC%C9%99l%2F"},{"id":"lv_2_41","topic":"Tourism and Visits","word":"fare","pos":"(n)","ipa":"/fer/","defVi":"tiền vé, giá cước (xe buýt, tàu hỏa, taxi, máy bay)","defEn":"the money that you pay to travel by bus, plane, taxi, or train","examples":["Bus [fare] in the city has increased significantly this year. (=Dịch: Giá vé xe buýt trong thành phố đã tăng đáng kể trong năm nay.)","Passengers must pay the exact [fare] when boarding the tram. (=Dịch: Hành khách phải trả đúng số tiền vé khi lên xe điện.)","She didn't have enough cash on her to pay the taxi [fare]. (=Dịch: Cô ấy không mang theo đủ tiền mặt để trả tiền cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ffer%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ffer%2F"},{"id":"lv_2_42","topic":"Tourism and Visits","word":"farmland","pos":"(n)","ipa":"/ˈfɑːrm.lænd/","defVi":"đất nông nghiệp, đất canh tác","defEn":"land that is used for farming or suitable for growing crops","examples":["Much of the fertile [farmland] was destroyed by the severe flood. (=Dịch: Phần lớn diện tích đất nông nghiệp màu mỡ đã bị tàn phá bởi trận lũ lụt nghiêm trọng.)","Urban expansion is rapidly turning [farmland] into housing estates. (=Dịch: Sự mở rộng đô thị đang nhanh chóng biến đất nông nghiệp thành các khu dân cư.)","The government introduced policies to protect valuable [farmland] from pollution. (=Dịch: Chính phủ đã ban hành các chính sách nhằm bảo vệ đất nông nghiệp có giá trị khỏi tình trạng ô nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=farmland&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90rm.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=farmland&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90rm.l%C3%A6nd%2F"},{"id":"lv_2_43","topic":"Tourism and Visits","word":"farmyard","pos":"(n)","ipa":"/ˈfɑːrm.jɑːrd/","defVi":"sân nông trại, khu đất quanh các chuồng trại","defEn":"an area of land surrounded by farm buildings","examples":["Chickens and ducks were roaming freely around the [farmyard]. (=Dịch: Gà và vịt đang đi lại tự do xung quanh sân nông trại.)","The old tractor was parked near the shed in the [farmyard]. (=Dịch: Chiếc máy kéo cũ được đỗ gần nhà kho trong sân nông trại.)","Children enjoyed feeding the animals in the open [farmyard]. (=Dịch: Trẻ em rất thích thú khi được cho động vật ăn ở khu sân nông trại ngoài trời.)"],"ukAudio":"/ai_services/tts3/?q=farmyard&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90rm.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=farmyard&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90rm.j%C9%91%CB%90rd%2F"},{"id":"lv_2_44","topic":"Tourism and Visits","word":"ferry","pos":"(n)","ipa":"/ˈfer.i/","defVi":"phà, tàu chở khách qua sông/biển","defEn":"a boat or ship that carries people, vehicles, or goods across an area of water","examples":["We took a [ferry] across the river to reach the island. (=Dịch: Chúng tôi đã đi phà qua sông để đến hòn đảo.)","The car [ferry] operates every thirty minutes during peak hours. (=Dịch: Phà chở ô tô hoạt động cứ ba mươi phút một chuyến trong giờ cao điểm.)","Due to stormy weather, all [ferry] services have been cancelled today. (=Dịch: Do thời tiết giông bão, tất cả các dịch vụ phà đều bị hủy vào ngày hôm nay.)"],"ukAudio":"/ai_services/tts3/?q=ferry&lang=en-GB&ipa=%2F%CB%88fer.i%2F","usAudio":"/ai_services/tts3/?q=ferry&lang=en-US&ipa=%2F%CB%88fer.i%2F"},{"id":"lv_2_45","topic":"Tourism and Visits","word":"firewood","pos":"(n)","ipa":"/ˈfaɪr.wʊd/","defVi":"củi (để đun nấu, sưởi ấm)","defEn":"wood that has been prepared or gathered to be burned for heat or cooking","examples":["They went into the forest to gather dry [firewood] for the campfire. (=Dịch: Họ đã vào rừng để lượm củi khô cho lửa trại.)","The cabin was heated entirely by a stove burning [firewood]. (=Dịch: Căn nhà gỗ được sưởi ấm hoàn toàn bằng một chiếc lò đốt củi.)","We need to store enough [firewood] before the cold winter begins. (=Dịch: Chúng ta cần tích trữ đủ củi trước khi mùa đông giá lạnh bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=firewood&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=firewood&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%CA%8Ad%2F"},{"id":"lv_2_46","topic":"Tourism and Visits","word":"fort","pos":"(n)","ipa":"/fɔːrt/","defVi":"pháo đài, công sự phòng thủ","defEn":"a strong building or group of buildings used by military forces for defence","examples":["The ancient [fort] was built on top of a hill to guard against invaders. (=Dịch: Pháo đài cổ kính được xây dựng trên đỉnh đồi để canh phòng những kẻ xâm lược.)","Tourists can explore the historical ruins of the seaside [fort]. (=Dịch: Du khách có thể khám phá những tàn tích lịch sử của pháo đài ven biển.)","Soldiers defended the stone [fort] during the long siege. (=Dịch: Các binh sĩ đã bảo vệ pháo đài bằng đá trong suốt cuộc bao vây kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=fort&lang=en-GB&ipa=%2Ff%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=fort&lang=en-US&ipa=%2Ff%C9%94%CB%90rt%2F"},{"id":"lv_2_47","topic":"Tourism and Visits","word":"found","pos":"(v)","ipa":"/faʊnd/","defVi":"thành lập, sáng lập, xây dựng","defEn":"to establish, start, or set up an organization, company, or institution","examples":["She decided to [found] a charity to support homeless children. (=Dịch: Cô ấy quyết định thành lập một tổ chức từ thiện để hỗ trợ trẻ em vô gia cư.)","The university was [found]ed more than two hundred years ago. (=Dịch: Trường đại học đã được thành lập cách đây hơn hai trăm năm.)","Two young entrepreneurs [found]ed the technology startup in a small garage. (=Dịch: Hai doanh nhân trẻ đã sáng lập công ty khởi nghiệp công nghệ này trong một ga-ra nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=found&lang=en-GB&ipa=%2Ffa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=found&lang=en-US&ipa=%2Ffa%CA%8And%2F"},{"id":"lv_2_48","topic":"Tourism and Visits","word":"fountain","pos":"(n)","ipa":"/ˈfaʊn.tən/","defVi":"đài phun nước, vòi nước uống","defEn":"a structure that sends a stream of water into the air, often decorative or used for drinking","examples":["People like to sit near the decorative [fountain] in the town square. (=Dịch: Mọi người thích ngồi gần đài phun nước trang trí ở quảng trường thị trấn.)","He drank cold water from the drinking [fountain] after running. (=Dịch: Anh ấy đã uống nước mát từ vòi nước uống công cộng sau khi chạy bộ.)","Coins are often tossed into the park [fountain] for good luck. (=Dịch: Mọi người thường ném đồng xu vào đài phun nước trong công viên để cầu may.)"],"ukAudio":"/ai_services/tts3/?q=fountain&lang=en-GB&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fountain&lang=en-US&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F"},{"id":"lv_2_49","topic":"Tourism and Visits","word":"fragile","pos":"(adj)","ipa":"/ˈfrædʒ.əl/","defVi":"dễ vỡ, mỏng manh, yếu ớt","defEn":"easily broken, damaged, or harmed; delicate","examples":["Please be careful with that box because it contains [fragile] glassware. (=Dịch: Xin hãy cẩn thận với chiếc hộp đó vì nó chứa đồ thủy tinh dễ vỡ.)","The region's [fragile] ecosystem is threatened by climate change. (=Dịch: Hệ sinh thái mong manh của khu vực đang bị đe dọa bởi biến đổi khí hậu.)","The patient is still in a [fragile] condition after the surgery. (=Dịch: Bệnh nhân vẫn đang trong tình trạng yếu ớt sau ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F"},{"id":"lv_2_50","topic":"Tourism and Visits","word":"lighthouse","pos":"(n)","ipa":"/ˈlaɪt.haʊs/","defVi":"ngọn hải đăng","defEn":"a tower with a bright light at the top to guide ships at sea","examples":["The old [lighthouse] warns ships of dangerous rocks near the shore. (=Dịch: Ngọn hải đăng cũ cảnh báo các tàu thuyền về những bãi đá nguy hiểm gần bờ.)","We climbed to the top of the [lighthouse] to enjoy the panoramic ocean view. (=Dịch: Chúng tôi đã leo lên đỉnh ngọn hải đăng để ngắm nhìn toàn cảnh đại dương.)","Historically, [lighthouse] keepers lived in isolated conditions for months. (=Dịch: Trong lịch sử, những người gác hải đăng từng sống trong điều kiện cô lập suốt nhiều tháng.)"],"ukAudio":"/ai_services/tts3/?q=lighthouse&lang=en-GB&ipa=%2F%CB%88la%C9%AAt.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=lighthouse&lang=en-US&ipa=%2F%CB%88la%C9%AAt.ha%CA%8As%2F"},{"id":"lv_2_51","topic":"Tourism and Visits","word":"litter","pos":"(n)","ipa":"/ˈlɪt̬.ɚ/","defVi":"rác rưởi (vứt bừa bãi nơi công cộng)","defEn":"small pieces of rubbish left scattered in a public place","examples":["Volunteers gathered on the beach to pick up plastic [litter]. (=Dịch: Các tình nguyện viên đã tập trung trên bãi biển để nhặt rác thải nhựa.)","There are heavy fines for dropping [litter] in the national park. (=Dịch: Có các mức phạt nặng đối với hành vi vứt rác bừa bãi trong vườn quốc gia.)","The streets were filled with [litter] after the music festival ended. (=Dịch: Đường phố ngập tràn rác sau khi lễ hội âm nhạc kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=litter&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litter&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A%2F"},{"id":"lv_2_52","topic":"Tourism and Visits","word":"lunchbox","pos":"(n)","ipa":"/ˈlʌntʃ.bɑːks/","defVi":"hộp đựng cơm trưa","defEn":"a container used for carrying a meal, typically to school or work","examples":["She packed a sandwich and some fresh fruit into her [lunchbox]. (=Dịch: Cô ấy đã xếp một chiếc bánh sandwich và một ít trái cây tươi vào hộp cơm trưa của mình.)","The boy accidentally left his colorful [lunchbox] on the school bus. (=Dịch: Cậu bé đã vô tình để quên chiếc hộp đựng cơm trưa sặc sỡ trên xe buýt trường học.)","Using a reusable [lunchbox] helps reduce daily plastic waste. (=Dịch: Sử dụng hộp cơm trưa tái sử dụng giúp giảm thiểu lượng rác thải nhựa hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=lunchbox&lang=en-GB&ipa=%2F%CB%88l%CA%8Cnt%CA%83.b%C9%91%CB%90ks%2F","usAudio":"/ai_services/tts3/?q=lunchbox&lang=en-US&ipa=%2F%CB%88l%CA%8Cnt%CA%83.b%C9%91%CB%90ks%2F"},{"id":"lv_2_53","topic":"Tourism and Visits","word":"magic","pos":"(adj)","ipa":"/ˈmædʒ.ɪk/","defVi":"kỳ diệu, ma thuật, huyền diệu","defEn":"having special or supernatural powers, or producing surprising results","examples":["The children believed that the old forest had [magic] powers. (=Dịch: Lũ trẻ tin rằng khu rừng già có sức mạnh ma thuật.)","He touched the door with a [magic] wand in the story. (=Dịch: Trong câu chuyện, anh ấy đã chạm vào cánh cửa bằng một chiếc đũa thần.)","Watching the sunset over the mountains was a truly [magic] moment. (=Dịch: Ngắm hoàng hôn buông xuống trên những ngọn núi thực sự là một khoảnh khắc kỳ diệu.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_2_54","topic":"Tourism and Visits","word":"magnificent","pos":"(adj)","ipa":"/mæɡˈnɪf.ə.sənt/","defVi":"tráng lệ, nguy nga, tuyệt mỹ","defEn":"extremely attractive, impressive, and grand","examples":["The palace has a [magnificent] ballroom decorated with gold. (=Dịch: Cung điện có một phòng khiêu vũ tráng lệ được trang trí bằng vàng.)","We had a [magnificent] view of the city from the rooftop terrace. (=Dịch: Chúng tôi có một tầm nhìn tuyệt đẹp bao quát thành phố từ sân thượng.)","The orchestra gave a [magnificent] performance that earned a standing ovation. (=Dịch: Dàn nhạc đã mang đến một buổi biểu diễn tuyệt vời và nhận được sự hoan nghênh nhiệt liệt từ khán giả.)"],"ukAudio":"/ai_services/tts3/?q=magnificent&lang=en-GB&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.s%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=magnificent&lang=en-US&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.s%C9%99nt%2F"},{"id":"lv_2_55","topic":"Tourism and Visits","word":"marsh","pos":"(n)","ipa":"/mɑːrʃ/","defVi":"đầm lầy","defEn":"an area of low, wet land that is often flooded","examples":["Many species of rare birds build their nests in the salt [marsh]. (=Dịch: Nhiều loài chim quý hiếm làm tổ ở vùng đầm lầy nước mặn.)","They built a wooden boardwalk to allow visitors to cross the [marsh] safely. (=Dịch: Họ đã xây một lối đi lót ván gỗ để du khách có thể băng qua đầm lầy một cách an toàn.)","The [marsh] plays a crucial role in filtering water and preventing floods. (=Dịch: Vùng đầm lầy đóng vai trò quan trọng trong việc lọc nước và ngăn ngừa lũ lụt.)"],"ukAudio":"/ai_services/tts3/?q=marsh&lang=en-GB&ipa=%2Fm%C9%91%CB%90r%CA%83%2F","usAudio":"/ai_services/tts3/?q=marsh&lang=en-US&ipa=%2Fm%C9%91%CB%90r%CA%83%2F"},{"id":"lv_2_56","topic":"Tourism and Visits","word":"mayor","pos":"(n)","ipa":"/ˈmeɪ.ɚ/","defVi":"thị trưởng","defEn":"the elected leader of the government in a town or city","examples":["The [mayor] announced a new plan to improve public transportation. (=Dịch: Thị trưởng đã công bố một kế hoạch mới nhằm cải thiện hệ thống giao thông công cộng.)","Citizens gathered at the town hall to voice their concerns to the [mayor]. (=Dịch: Người dân đã tập trung tại tòa thị chính để bày tỏ những mối bận tâm của họ với thị trưởng.)","She served as the city's first female [mayor] for two terms. (=Dịch: Bà đã giữ chức nữ thị trưởng đầu tiên của thành phố trong hai nhiệm kỳ.)"],"ukAudio":"/ai_services/tts3/?q=mayor&lang=en-GB&ipa=%2F%CB%88me%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mayor&lang=en-US&ipa=%2F%CB%88me%C9%AA.%C9%9A%2F"},{"id":"lv_2_57","topic":"Tourism and Visits","word":"maze","pos":"(n)","ipa":"/meɪz/","defVi":"mê cung","defEn":"a complicated system of paths in which it is difficult to find the way out","examples":["The tourists got lost in the [maze] of narrow streets in the old town. (=Dịch: Các du khách đã bị lạc trong mê cung của những con phố hẹp ở khu phố cổ.)","Children love running through the hedge [maze] in the royal garden. (=Dịch: Trẻ em rất thích chạy nhảy qua mê cung hàng rào cây trong khu vườn hoàng gia.)","Navigating the legal system felt like trying to solve a complicated [maze]. (=Dịch: Tìm hiểu và xoay xở trong hệ thống pháp lý mang lại cảm giác như đang cố giải một mê cung phức tạp.)"],"ukAudio":"/ai_services/tts3/?q=maze&lang=en-GB&ipa=%2Fme%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=maze&lang=en-US&ipa=%2Fme%C9%AAz%2F"},{"id":"lv_2_58","topic":"Tourism and Visits","word":"mill","pos":"(n)","ipa":"/mɪl/","defVi":"nhà máy, cối xay, xưởng nghiền","defEn":"a building equipped with machinery for grinding grain into flour or for manufacturing goods","examples":["The traditional water [mill] was used to grind wheat into flour. (=Dịch: Cối xay nước truyền thống từng được sử dụng để xay lúa mì thành bột.)","Many local workers found employment at the nearby textile [mill]. (=Dịch: Nhiều lao động địa phương đã tìm được việc làm tại nhà máy dệt gần đó.)","The old paper [mill] by the river has been converted into a museum. (=Dịch: Nhà máy giấy cũ bên bờ sông đã được cải tạo thành một bảo tàng.)"],"ukAudio":"/ai_services/tts3/?q=mill&lang=en-GB&ipa=%2Fm%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=mill&lang=en-US&ipa=%2Fm%C9%AAl%2F"},{"id":"lv_2_59","topic":"Tourism and Visits","word":"mulberry","pos":"(n)","ipa":"/ˈmʌl.ber.i/","defVi":"cây dâu tằm, quả dâu tằm","defEn":"a small, sweet dark purple or white fruit, or the tree on which it grows","examples":["Silkworms feed exclusively on the fresh leaves of the [mulberry] tree. (=Dịch: Tằm chỉ ăn duy nhất lá tươi của cây dâu tằm.)","She made delicious homemade jam from ripe [mulberry] fruits. (=Dịch: Cô ấy đã làm món mứt tự làm thơm ngon từ những quả dâu tằm chín.)","We sat in the shade of a large [mulberry] tree in the backyard. (=Dịch: Chúng tôi ngồi dưới bóng râm của một cây dâu tằm lớn ở sân sau.)"],"ukAudio":"/ai_services/tts3/?q=mulberry&lang=en-GB&ipa=%2F%CB%88m%CA%8Cl.ber.i%2F","usAudio":"/ai_services/tts3/?q=mulberry&lang=en-US&ipa=%2F%CB%88m%CA%8Cl.ber.i%2F"},{"id":"lv_2_60","topic":"Tourism and Visits","word":"operator","pos":"(n)","ipa":"/ˈɑː.pəˌreɪ.t̬ɚ/","defVi":"người vận hành, nhân viên trực tổng đài, hoặc nhà mạng/nhà điều hành","defEn":"a person who operates equipment or a machine, or a company that runs a business","examples":["Please hold the line while I connect you to the switchboard [operator]. (=Dịch: Xin vui lòng giữ máy trong khi tôi kết nối bạn với nhân viên tổng đài.)","A skilled crane [operator] is needed for this high-rise construction project. (=Dịch: Cần một người vận hành cần cẩu lành nghề cho dự án xây dựng nhà cao tầng này.)","The local tour [operator] organized a wonderful hiking trip in the mountains. (=Dịch: Công ty lữ hành địa phương đã tổ chức một chuyến đi bộ đường dài tuyệt vời trên núi.)"],"ukAudio":"/ai_services/tts3/?q=operator&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99%CB%8Cre%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=operator&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99%CB%8Cre%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_2_61","topic":"Tourism and Visits","word":"organic","pos":"(adj)","ipa":"/ɔːrˈɡæn.ɪk/","defVi":"hữu cơ","defEn":"produced or grown without using artificial chemicals or pesticides","examples":["Many consumers are willing to pay extra for fresh [organic] vegetables. (=Dịch: Nhiều người tiêu dùng sẵn sàng trả thêm tiền cho các loại rau hữu cơ tươi ngon.)","The farm transitioned to [organic] methods to protect the surrounding soil. (=Dịch: Trang trại đã chuyển đổi sang các phương pháp hữu cơ để bảo vệ đất đai xung quanh.)","Her bakery specializes in making bread from [organic] grains. (=Dịch: Tiệm bánh của cô ấy chuyên làm bánh mì từ các loại ngũ cốc hữu cơ.)"],"ukAudio":"/ai_services/tts3/?q=organic&lang=en-GB&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=organic&lang=en-US&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F"},{"id":"lv_2_62","topic":"Tourism and Visits","word":"outdoor","pos":"(adj)","ipa":"/ˈaʊtˌdɔːr/","defVi":"ngoài trời","defEn":"used, happening, or existing in the open air rather than inside a building","examples":["Camping and kayaking are popular [outdoor] activities during the summer. (=Dịch: Cắm trại và chèo thuyền kayak là những hoạt động ngoài trời phổ biến trong mùa hè.)","The restaurant has a lovely [outdoor] patio where guests can dine in nice weather. (=Dịch: Nhà hàng có một khoảng sân ngoài trời xinh xắn, nơi thực khách có thể dùng bữa khi thời tiết đẹp.)","She bought sturdy [outdoor] furniture for her backyard garden. (=Dịch: Cô ấy đã mua đồ nội thất ngoài trời chắc chắn cho khu vườn sau nhà của mình.)"],"ukAudio":"/ai_services/tts3/?q=outdoor&lang=en-GB&ipa=%2F%CB%88a%CA%8At%CB%8Cd%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=outdoor&lang=en-US&ipa=%2F%CB%88a%CA%8At%CB%8Cd%C9%94%CB%90r%2F"},{"id":"lv_2_63","topic":"Tourism and Visits","word":"parkland","pos":"(n)","ipa":"/ˈpɑːrk.lænd/","defVi":"vùng đất công viên, đất cây xanh","defEn":"open land with grass and trees, often surrounding a large house or reserved for recreation","examples":["The city preserved acres of green [parkland] for public recreation. (=Dịch: Thành phố đã bảo tồn nhiều mẫu đất công viên xanh cho mục đích giải trí công cộng.)","Ancient trees scatter across the rolling [parkland] behind the estate. (=Dịch: Những cây cổ thụ nằm rải rác trên vùng đất công viên thoai thoải phía sau khu dinh thự.)","Residents often jog through the scenic [parkland] in the early morning. (=Dịch: Cư dân thường chạy bộ qua khu công viên tuyệt đẹp vào sáng sớm.)"],"ukAudio":"/ai_services/tts3/?q=parkland&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90rk.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=parkland&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90rk.l%C3%A6nd%2F"},{"id":"lv_2_64","topic":"Tourism and Visits","word":"parliament","pos":"(n)","ipa":"/ˈpɑːr.lə.mənt/","defVi":"nghị viện, quốc hội","defEn":"the group of elected politicians who make the laws for a country","examples":["The government passed a new healthcare bill in [parliament] yesterday. (=Dịch: Hôm qua chính phủ đã thông qua một dự luật chăm sóc sức khỏe mới tại nghị viện.)","Members of [parliament] debated the economic policy for several hours. (=Dịch: Các thành viên nghị viện đã tranh luận về chính sách kinh tế trong nhiều giờ liền.)","The prime minister dissolved [parliament] to call for an early election. (=Dịch: Thủ tướng đã giải tán nghị viện để kêu gọi một cuộc bầu cử sớm.)"],"ukAudio":"/ai_services/tts3/?q=parliament&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=parliament&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.l%C9%99.m%C9%99nt%2F"},{"id":"lv_2_65","topic":"Tourism and Visits","word":"pear","pos":"(n)","ipa":"/per/","defVi":"quả lê","defEn":"a sweet, juicy fruit with a narrow top and rounded bottom","examples":["He picked a ripe [pear] straight from the tree in the orchard. (=Dịch: Anh ấy đã hái một quả lê chín mọng ngay từ trên cây trong vườn.)","She added sliced [pear] and walnuts to the autumn salad. (=Dịch: Cô ấy đã thêm lê cắt lát và quả óc chó vào món salad mùa thu.)","The dessert featured a poached [pear] served with vanilla cream. (=Dịch: Món tráng miệng nổi bật với món lê hầm ăn kèm cùng kem vani.)"],"ukAudio":"/ai_services/tts3/?q=pear&lang=en-GB&ipa=%2Fper%2F","usAudio":"/ai_services/tts3/?q=pear&lang=en-US&ipa=%2Fper%2F"},{"id":"lv_2_66","topic":"Tourism and Visits","word":"penguin","pos":"(n)","ipa":"/ˈpeŋ.ɡwɪn/","defVi":"chim cánh cụt","defEn":"a black and white flightless sea bird living mainly in cold southern regions","examples":["The emperor [penguin] can survive in the freezing temperatures of Antarctica. (=Dịch: Chim cánh cụt hoàng đế có thể sống sót trong nhiệt độ băng giá ở Nam Cực.)","Children loved watching the [penguin] colony swim and dive at the aquarium. (=Dịch: Trẻ em rất thích ngắm nhìn đàn chim cánh cụt bơi và lặn tại thủy cung.)","A baby [penguin] is covered in soft gray down feathers when it hatches. (=Dịch: Một chú chim cánh cụt non được bao phủ bởi lớp lông tơ màu xám mềm mại khi mới nở.)"],"ukAudio":"/ai_services/tts3/?q=penguin&lang=en-GB&ipa=%2F%CB%88pe%C5%8B.%C9%A1w%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=penguin&lang=en-US&ipa=%2F%CB%88pe%C5%8B.%C9%A1w%C9%AAn%2F"},{"id":"lv_2_67","topic":"Tourism and Visits","word":"perfectly","pos":"(adv)","ipa":"/ˈpɝː.fɪkt.li/","defVi":"hoàn hảo, hoàn toàn","defEn":"in a way that is completely without mistakes, or entirely and fully","examples":["The new suit fits him [perfectly] without needing any alterations. (=Dịch: Bộ vest mới vừa vặn với anh ấy một cách hoàn hảo mà không cần phải chỉnh sửa gì.)","It is [perfectly] normal to feel nervous before a major exam. (=Dịch: Cảm thấy lo lắng trước một kỳ thi quan trọng là điều hoàn toàn bình thường.)","She executed the complex gymnastics routine [perfectly] and won the gold medal. (=Dịch: Cô ấy đã thực hiện bài thi thể dục dụng cụ phức tạp một cách hoàn hảo và giành được huy chương vàng.)"],"ukAudio":"/ai_services/tts3/?q=perfectly&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.f%C9%AAkt.li%2F","usAudio":"/ai_services/tts3/?q=perfectly&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.f%C9%AAkt.li%2F"},{"id":"lv_2_68","topic":"Tourism and Visits","word":"petition","pos":"(n)","ipa":"/pəˈtɪʃ.ən/","defVi":"đơn kiến nghị, thỉnh nguyện thư","defEn":"a formal written request signed by many people asking an authority to take action","examples":["Neighbors started a [petition] demanding a new traffic light at the intersection. (=Dịch: Những người hàng xóm đã bắt đầu một bản kiến nghị yêu cầu lắp đèn giao thông mới tại ngã tư.)","Over ten thousand citizens signed the online [petition] to ban single-use plastics. (=Dịch: Hơn mười nghìn công dân đã ký vào bản kiến nghị trực tuyến để cấm đồ nhựa dùng một lần.)","The environmental group submitted the [petition] to the city council. (=Dịch: Nhóm bảo vệ môi trường đã đệ trình bản kiến nghị lên hội đồng thành phố.)"],"ukAudio":"/ai_services/tts3/?q=petition&lang=en-GB&ipa=%2Fp%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=petition&lang=en-US&ipa=%2Fp%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_2_69","topic":"Tourism and Visits","word":"photography","pos":"(n)","ipa":"/fəˈtɑː.ɡrə.fi/","defVi":"nhiếp ảnh, nghề chụp ảnh","defEn":"the art, process, or activity of taking and producing photographs","examples":["Landscape [photography] requires both patience and a good eye for lighting. (=Dịch: Nhiếp ảnh phong cảnh đòi hỏi cả sự kiên nhẫn lẫn con mắt tinh tường về ánh sáng.)","She decided to pursue a professional career in fashion [photography]. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp chuyên nghiệp trong ngành nhiếp ảnh thời trang.)","He took up wildlife [photography] as a relaxing weekend hobby. (=Dịch: Anh ấy bắt đầu chụp ảnh động vật hoang dã như một sở thích thư giãn vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=photography&lang=en-GB&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=photography&lang=en-US&ipa=%2Ff%C9%99%CB%88t%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_2_70","topic":"Tourism and Visits","word":"picnic","pos":"(n)","ipa":"/ˈpɪk.nɪk/","defVi":"chuyến dã ngoại, buổi cắm trại ăn ngoài trời","defEn":"an occasion when you eat a meal outside, especially in the countryside or a park","examples":["We decided to have a [picnic] by the lake on Sunday. (=Dịch: Chúng tôi đã quyết định đi dã ngoại bên bờ hồ vào Chủ nhật.)","Don't forget to pack some sandwiches for the family [picnic]. (=Dịch: Đừng quên mang theo vài chiếc bánh mì kẹp cho chuyến dã ngoại của gia đình.)","The sunny weather was perfect for an afternoon [picnic] in the park. (=Dịch: Thời tiết nắng ráo rất hoàn hảo cho một buổi dã ngoại buổi chiều trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=picnic&lang=en-GB&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=picnic&lang=en-US&ipa=%2F%CB%88p%C9%AAk.n%C9%AAk%2F"},{"id":"lv_2_71","topic":"Tourism and Visits","word":"pine","pos":"(n)","ipa":"/paɪn/","defVi":"cây thông","defEn":"an evergreen tree that produces cones and has thin, needle-shaped leaves","examples":["The mountain slopes were covered with tall [pine] trees. (=Dịch: Các sườn núi được bao phủ bởi những cây thông cao vút.)","The air smelled fresh with the scent of [pine] needles. (=Dịch: Không khí thật trong lành với mùi hương của lá thông.)","They built a rustic cabin out of solid [pine] wood. (=Dịch: Họ đã xây dựng một căn cabin mộc mạc từ gỗ thông nguyên khối.)"],"ukAudio":"/ai_services/tts3/?q=pine&lang=en-GB&ipa=%2Fpa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=pine&lang=en-US&ipa=%2Fpa%C9%AAn%2F"},{"id":"lv_2_72","topic":"Tourism and Visits","word":"pitch","pos":"(n)","ipa":"/pɪtʃ/","defVi":"sân thi đấu thể thao (bóng đá, bóng bầu dục, v.v.)","defEn":"an outdoor marked area of ground used for playing a sports game","examples":["The players ran onto the football [pitch] with high spirits. (=Dịch: Các cầu thủ chạy ra sân bóng đá với tinh thần dâng cao.)","Heavy rain made the rugby [pitch] too muddy to play on. (=Dịch: Mưa lớn đã làm cho sân bóng bầu dục trở nên quá lầy lội để có thể thi đấu.)","The school invested money to upgrade its artificial turf [pitch]. (=Dịch: Trường học đã đầu tư tiền để nâng cấp sân cỏ nhân tạo.)"],"ukAudio":"/ai_services/tts3/?q=pitch&lang=en-GB&ipa=%2Fp%C9%AAt%CA%83%2F","usAudio":"/ai_services/tts3/?q=pitch&lang=en-US&ipa=%2Fp%C9%AAt%CA%83%2F"},{"id":"lv_2_73","topic":"Tourism and Visits","word":"playwright","pos":"(n)","ipa":"/ˈpleɪ.raɪt/","defVi":"nhà soạn kịch, nhà viết kịch","defEn":"a person who writes plays for the theater","examples":["William Shakespeare is arguably the most famous [playwright] in history. (=Dịch: William Shakespeare có thể coi là nhà viết kịch nổi tiếng nhất trong lịch sử.)","The young [playwright] won an award for her debut production. (=Dịch: Nữ nhà soạn kịch trẻ tuổi đã giành được một giải thưởng cho tác phẩm đầu tay của mình.)","The local theater company is looking for works by emerging [playwright]s. (=Dịch: Đoàn kịch địa phương đang tìm kiếm các tác phẩm của những nhà viết kịch mới nổi.)"],"ukAudio":"/ai_services/tts3/?q=playwright&lang=en-GB&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=playwright&lang=en-US&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F"},{"id":"lv_2_74","topic":"Tourism and Visits","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, thận trọng, thức thời","defEn":"wise and showing good judgment, especially in political or business matters","examples":["It seemed [politic] to keep his opinions to himself during the heated meeting. (=Dịch: Việc giữ kín ý kiến của mình trong suốt cuộc họp gay gắt dường như là điều khôn ngoan.)","She thought it would not be [politic] to ask for a pay raise right now. (=Dịch: Cô ấy nghĩ rằng việc yêu cầu tăng lương vào lúc này sẽ không phải là một quyết định khôn ngoan.)","The company made a [politic] decision to delay the product launch. (=Dịch: Công ty đã đưa ra một quyết định thận trọng là trì hoãn việc ra mắt sản phẩm.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_2_75","topic":"Tourism and Visits","word":"popularity","pos":"(n)","ipa":"/ˌpɑː.pjəˈler.ə.t̬i/","defVi":"sự phổ biến, sự ưa chuộng, tính đại chúng","defEn":"the state of being liked, enjoyed, or supported by a lot of people","examples":["The singer enjoyed immense [popularity] throughout the 1990s. (=Dịch: Người ca sĩ này đã có được sự yêu mến nồng nhiệt trong suốt những năm 1990.)","The [popularity] of cycling has increased significantly in urban areas. (=Dịch: Sự phổ biến của việc đi xe đạp đã gia tăng đáng kể ở các khu vực thành thị.)","Social media played a crucial role in boosting the brand's [popularity]. (=Dịch: Mạng xã hội đã đóng một vai trò quan trọng trong việc thúc đẩy mức độ phổ biến của thương hiệu.)"],"ukAudio":"/ai_services/tts3/?q=popularity&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=popularity&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F"},{"id":"lv_2_76","topic":"Tourism and Visits","word":"queue","pos":"(v)","ipa":"/kjuː/","defVi":"xếp hàng chờ đợi","defEn":"to wait in a line of people, vehicles, or items","examples":["Hundreds of fans [queue] outside the stadium to buy tickets. (=Dịch: Hàng trăm người hâm mộ xếp hàng bên ngoài sân vận động để mua vé.)","Passengers had to [queue] patiently at the airport security check. (=Dịch: Các hành khách đã phải kiên nhẫn xếp hàng tại khu vực kiểm tra an ninh sân bay.)","We had to [queue] for over an hour just to get into the exhibition. (=Dịch: Chúng tôi đã phải xếp hàng hơn một tiếng đồng hồ chỉ để vào được buổi triển lãm.)"],"ukAudio":"/ai_services/tts3/?q=queue&lang=en-GB&ipa=%2Fkju%CB%90%2F","usAudio":"/ai_services/tts3/?q=queue&lang=en-US&ipa=%2Fkju%CB%90%2F"},{"id":"lv_2_77","topic":"Tourism and Visits","word":"quiz","pos":"(n)","ipa":"/kwɪz/","defVi":"bài kiểm tra ngắn, câu đố kiểm tra kiến thức","defEn":"a short or informal test of knowledge or a game based on answering questions","examples":["The teacher gave us a surprise vocabulary [quiz] this morning. (=Dịch: Giáo viên đã cho chúng tôi một bài kiểm tra nhanh từ vựng bất ngờ vào sáng nay.)","We joined the weekly pub [quiz] with some university friends. (=Dịch: Chúng tôi đã tham gia buổi đố vui hàng tuần ở quán rượu cùng một vài người bạn đại học.)","Take this online [quiz] to find out your learning style. (=Dịch: Hãy làm bài trắc nghiệm trực tuyến này để tìm ra phong cách học tập của bạn.)"],"ukAudio":"/ai_services/tts3/?q=quiz&lang=en-GB&ipa=%2Fkw%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=quiz&lang=en-US&ipa=%2Fkw%C9%AAz%2F"},{"id":"lv_2_78","topic":"Tourism and Visits","word":"rabbit","pos":"(n)","ipa":"/ˈræb.ɪt/","defVi":"con thỏ","defEn":"a small furry animal with long ears and a short tail that lives in burrows","examples":["A wild [rabbit] hopped across the grass and disappeared into the bushes. (=Dịch: Một con thỏ hoang nhảy qua bãi cỏ rồi biến mất vào bụi rậm.)","She keeps a pet [rabbit] in a large wooden hutch in the garden. (=Dịch: Cô ấy nuôi một chú thỏ cưng trong một chiếc chuồng gỗ lớn ở ngoài vườn.)","Carrots and leafy greens are healthy food options for a [rabbit]. (=Dịch: Cà rốt và các loại rau xanh là những lựa chọn thức ăn lành mạnh cho thỏ.)"],"ukAudio":"/ai_services/tts3/?q=rabbit&lang=en-GB&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rabbit&lang=en-US&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F"},{"id":"lv_2_79","topic":"Tourism and Visits","word":"ranger","pos":"(n)","ipa":"/ˈreɪn.dʒɚ/","defVi":"kiểm lâm, nhân viên quản lý vườn quốc gia","defEn":"a person whose job is to protect and manage a forest, park, or wildlife area","examples":["The park [ranger] guided tourists through the nature trail safely. (=Dịch: Nhân viên kiểm lâm công viên đã hướng dẫn du khách đi qua đường mòn thiên nhiên một cách an toàn.)","A dedicated forest [ranger] works hard to prevent illegal logging. (=Dịch: Một kiểm lâm viên tận tụy luôn nỗ lực hết mình để ngăn chặn việc khai thác gỗ trái phép.)","The [ranger] warned visitors not to feed the wild animals. (=Dịch: Người kiểm lâm đã cảnh báo du khách không được cho động vật hoang dã ăn.)"],"ukAudio":"/ai_services/tts3/?q=ranger&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ranger&lang=en-US&ipa=%2F%CB%88re%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_2_80","topic":"Tourism and Visits","word":"raw","pos":"(adj)","ipa":"/rɑː/","defVi":"sống (chưa nấu chín), thô (chưa qua chế biến)","defEn":"not cooked, or in a natural state without being processed","examples":["Some people prefer to eat [raw] vegetables to preserve their nutrients. (=Dịch: Một số người thích ăn rau sống để giữ lại các chất dinh dưỡng của chúng.)","The factory imports [raw] materials from several neighboring countries. (=Dịch: Nhà máy nhập khẩu nguyên liệu thô từ một số quốc gia láng giềng.)","The cold, [raw] wind made everyone shiver as they waited for the bus. (=Dịch: Cơn gió lạnh buốt khiến mọi người run rẩy trong lúc đứng chờ xe buýt.)"],"ukAudio":"/ai_services/tts3/?q=raw&lang=en-GB&ipa=%2Fr%C9%91%CB%90%2F","usAudio":"/ai_services/tts3/?q=raw&lang=en-US&ipa=%2Fr%C9%91%CB%90%2F"},{"id":"lv_2_81","topic":"Tourism and Visits","word":"referee","pos":"(n)","ipa":"/ˌrɛf.əˈri/","defVi":"trọng tài","defEn":"an official who controls a sports match and ensures players follow the rules","examples":["The [referee] blew his whistle and awarded a penalty to the home team. (=Dịch: Trọng tài đã thổi còi và cho đội chủ nhà hưởng một quả phạt đền.)","Players must respect the decision made by the [referee] during the game. (=Dịch: Các cầu thủ phải tôn trọng quyết định của trọng tài trong suốt trận đấu.)","She is training hard to become a certified football [referee]. (=Dịch: Cô ấy đang nỗ lực tập luyện để trở thành một trọng tài bóng đá được cấp chứng chỉ.)"],"ukAudio":"/ai_services/tts3/?q=referee&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bf.%C9%99%CB%88ri%2F","usAudio":"/ai_services/tts3/?q=referee&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bf.%C9%99%CB%88ri%2F"},{"id":"lv_2_82","topic":"Tourism and Visits","word":"reptile","pos":"(n)","ipa":"/ˈrɛp.taɪl/","defVi":"loài bò sát","defEn":"a cold-blooded animal with scaly skin that lays eggs, such as a snake or lizard","examples":["A crocodile is a large [reptile] that lives in rivers and swamps. (=Dịch: Cá sấu là một loài bò sát lớn sống ở các con sông và đầm lầy.)","Unlike mammals, almost every [reptile] lays eggs with tough shells. (=Dịch: Không giống như động vật có vú, hầu hết các loài bò sát đều đẻ trứng có vỏ cứng.)","The zoo has a dedicated section for each rare [reptile] species. (=Dịch: Sở thú có một khu vực riêng biệt dành cho từng loài bò sát quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=reptile&lang=en-GB&ipa=%2F%CB%88r%C9%9Bp.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=reptile&lang=en-US&ipa=%2F%CB%88r%C9%9Bp.ta%C9%AAl%2F"},{"id":"lv_2_83","topic":"Tourism and Visits","word":"rhythm","pos":"(n)","ipa":"/ˈrɪð.əm/","defVi":"nhịp điệu, tiết tấu","defEn":"a strong, regular, repeated pattern of movement or sound","examples":["She tapped her foot to the lively [rhythm] of the music. (=Dịch: Cô ấy nhịp chân theo giai điệu sống động của bản nhạc.)","It took a few weeks to adjust to the daily [rhythm] of university life. (=Dịch: Phải mất vài tuần để thích nghi với nhịp sống hằng ngày của đời sinh viên.)","The steady [rhythm] of rainfall helped him fall asleep quickly. (=Dịch: Tiếng mưa rơi đều đặn đã giúp anh nhanh chóng chìm vào giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=rhythm&lang=en-GB&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=rhythm&lang=en-US&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F"},{"id":"lv_2_84","topic":"Tourism and Visits","word":"ridge","pos":"(n)","ipa":"/rɪdʒ/","defVi":"sống núi, chỏm núi, gờ nổi","defEn":"a long, narrow raised part along a mountain, hill, or surface","examples":["The hikers walked along the narrow [ridge] of the mountain. (=Dịch: Những người đi bộ đường dài bước dọc theo sống núi hẹp.)","We could see the entire valley clearly from the top of the [ridge]. (=Dịch: Chúng tôi có thể nhìn thấy rõ toàn bộ thung lũng từ trên đỉnh sống núi.)","A high-pressure [ridge] brought dry and sunny weather to the region. (=Dịch: Một dải áp cao đã mang lại thời tiết khô ráo và đầy nắng cho khu vực.)"],"ukAudio":"/ai_services/tts3/?q=ridge&lang=en-GB&ipa=%2Fr%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=ridge&lang=en-US&ipa=%2Fr%C9%AAd%CA%92%2F"},{"id":"lv_2_85","topic":"Tourism and Visits","word":"riverside","pos":"(n)","ipa":"/ˈrɪv.ɚˌsaɪd/","defVi":"bờ sông, ven sông","defEn":"the ground along the edge of a river","examples":["They decided to have a picnic on the grassy [riverside]. (=Dịch: Họ quyết định tổ chức một buổi dã ngoại trên bờ sông đầy cỏ.)","Many tourists enjoy walking along the scenic [riverside] in the evening. (=Dịch: Nhiều du khách thích đi dạo dọc bờ sông thơ mộng vào buổi tối.)","The city built a new promenade along the [riverside] to attract visitors. (=Dịch: Thành phố đã xây dựng một lối đi dạo mới dọc bờ sông để thu hút du khách.)"],"ukAudio":"/ai_services/tts3/?q=riverside&lang=en-GB&ipa=%2F%CB%88r%C9%AAv.%C9%9A%CB%8Csa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=riverside&lang=en-US&ipa=%2F%CB%88r%C9%AAv.%C9%9A%CB%8Csa%C9%AAd%2F"},{"id":"lv_2_86","topic":"Tourism and Visits","word":"roll","pos":"(v)","ipa":"/roʊl/","defVi":"lăn, cuộn lại","defEn":"to move by turning over and over, or to form into a tube or ball","examples":["The children laughed as they watched the ball [roll] down the hill. (=Dịch: Lũ trẻ bật cười khi nhìn quả bóng lăn xuống đồi.)","You should [roll] the dough into a smooth circle before baking. (=Dịch: Bạn nên cán bột thành một hình tròn mịn trước khi nướng.)","Tears began to [roll] down her cheeks when she heard the good news. (=Dịch: Nước mắt bắt đầu lăn dài trên má khi cô nghe được tin vui.)"],"ukAudio":"/ai_services/tts3/?q=roll&lang=en-GB&ipa=%2Fro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=roll&lang=en-US&ipa=%2Fro%CA%8Al%2F"},{"id":"lv_2_87","topic":"Tourism and Visits","word":"romantic","pos":"(adj)","ipa":"/roʊˈmæn.tɪk/","defVi":"lãng mạn","defEn":"connected with or expressive of love, idealized beauty, or passion","examples":["They celebrated their anniversary with a [romantic] dinner by candlelight. (=Dịch: Họ đã kỷ niệm ngày cưới bằng một bữa tối lãng mạn dưới ánh nến.)","Paris is often considered one of the most [romantic] cities in the world. (=Dịch: Paris thường được coi là một trong những thành phố lãng mạn nhất thế giới.)","He wrote a [romantic] poem to express his deep feelings for her. (=Dịch: Anh ấy đã viết một bài thơ lãng mạn để bày tỏ tình cảm sâu sắc của mình dành cho cô.)"],"ukAudio":"/ai_services/tts3/?q=romantic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=romantic&lang=en-US&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_2_88","topic":"Tourism and Visits","word":"rome","pos":"(n)","ipa":"/roʊm/","defVi":"thành phố Rome, thủ đô nước Ý","defEn":"the capital city of Italy, famous for its ancient history and architecture","examples":["Millions of travelers visit [Rome] each year to explore its ancient ruins. (=Dịch: Hàng triệu du khách đến thăm Rome mỗi năm để khám phá những tàn tích cổ xưa nơi đây.)","The Colosseum is one of the most famous landmarks in [Rome]. (=Dịch: Đấu trường Colosseum là một trong những địa danh nổi tiếng nhất ở Rome.)","Her dream has always been to study classical architecture in [Rome]. (=Dịch: Ước mơ của cô luôn là được theo học ngành kiến trúc cổ điển tại Rome.)"],"ukAudio":"/ai_services/tts3/?q=rome&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=rome&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_2_89","topic":"Tourism and Visits","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, thô ráp, dữ dội","defEn":"having an uneven or irregular surface; not smooth or gentle","examples":["His hands were [rough] and calloused from years of manual labor. (=Dịch: Đôi bàn tay ông thô ráp và chai sạn sau nhiều năm lao động chân tay.)","The boat struggled to navigate through the [rough] sea during the storm. (=Dịch: Con thuyền chật vật di chuyển qua vùng biển động dữ dội trong cơn bão.)","She made a [rough] sketch of the landscape before starting the painting. (=Dịch: Cô ấy đã phác thảo sơ bộ phong cảnh trước khi bắt đầu vẽ tranh.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_2_90","topic":"Tourism and Visits","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a line of people or things placed side by side","examples":["We had great seats in the front [row] of the cinema. (=Dịch: Chúng tôi đã có những chỗ ngồi tuyệt vời ở hàng ghế đầu của rạp chiếu phim.)","A [row] of trees was planted along the road to provide shade. (=Dịch: Một hàng cây đã được trồng dọc theo con đường để tạo bóng mát.)","The teacher asked the students to stand in a straight [row]. (=Dịch: Giáo viên yêu cầu các học sinh đứng thành một hàng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_2_91","topic":"Tourism and Visits","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"hoàng gia, thuộc về hoàng gia","defEn":"connected with or belonging to a king, queen, or their family","examples":["The [royal] family attended the annual charity event together. (=Dịch: Gia đình hoàng gia đã cùng nhau tham dự sự kiện từ thiện thường niên.)","They received a [royal] welcome when they arrived in the historic city. (=Dịch: Họ đã nhận được sự đón tiếp nồng hậu như bậc vương giả khi đặt chân đến thành phố lịch sử này.)","The museum displays many treasures from the ancient [royal] palace. (=Dịch: Bảo tàng trưng bày nhiều báu vật từ cung điện hoàng gia cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_2_92","topic":"Tourism and Visits","word":"ruler","pos":"(n)","ipa":"/ˈru.lɚ/","defVi":"người cai trị, nhà lãnh đạo","defEn":"a person who has the official power to govern a country or area","examples":["The ancient [ruler] was known for his wisdom and fairness. (=Dịch: Vị quân chủ thời cổ đại được biết đến nhờ sự thông thái và tính công bằng của mình.)","Many laws were changed during the reign of the new [ruler]. (=Dịch: Nhiều đạo luật đã bị thay đổi dưới triều đại của nhà cai trị mới.)","The military [ruler] faced strong opposition from the citizens. (=Dịch: Nhà cai trị quân sự vấp phải sự phản đối gay gắt từ người dân.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru.l%C9%9A%2F"},{"id":"lv_2_93","topic":"Tourism and Visits","word":"russia","pos":"(n)","ipa":"/ˈrʌʃ.ə/","defVi":"nước Nga","defEn":"a large country spanning Eastern Europe and Northern Asia","examples":["[Russia] is the largest country in the world by land area. (=Dịch: Nước Nga là quốc gia có diện tích đất liền lớn nhất trên thế giới.)","She spent two years studying literature in [Russia]. (=Dịch: Cô ấy đã dành hai năm học văn học tại Nga.)","The climate in northern [Russia] is extremely cold during winter. (=Dịch: Khí hậu ở miền bắc nước Nga vô cùng lạnh giá vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=russia&lang=en-GB&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F","usAudio":"/ai_services/tts3/?q=russia&lang=en-US&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F"},{"id":"lv_2_94","topic":"Tourism and Visits","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ","defEn":"people who work as members of the crew on a ship or boat","examples":["The [sailors] worked hard to navigate the ship through the stormy sea. (=Dịch: Các thủy thủ đã làm việc cật lực để điều khiển con tàu vượt qua vùng biển giông bão.)","A group of experienced [sailors] repaired the sails before departure. (=Dịch: Một nhóm thủy thủ giàu kinh nghiệm đã sửa chữa các cánh buồm trước khi khởi hành.)","Ancient [sailors] used the stars in the night sky to guide their journeys. (=Dịch: Các thủy thủ thời cổ đại từng dùng các vì sao trên bầu trời đêm để dẫn đường cho những chuyến hành trình của họ.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_2_95","topic":"Tourism and Visits","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance consisting of very small grains of rock found on beaches and in deserts","examples":["Children love playing in the warm [sand] on the beach. (=Dịch: Trẻ em rất thích chơi trên bãi cát ấm áp ở bờ biển.)","The wind blew [sand] into our eyes as we walked across the desert. (=Dịch: Gió đã thổi cát vào mắt chúng tôi khi chúng tôi đi bộ qua sa mạc.)","He shook the loose [sand] out of his shoes before entering the house. (=Dịch: Anh ấy đã giũ sạch cát bám trong giày trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_2_96","topic":"Tourism and Visits","word":"scarecrow","pos":"(n)","ipa":"/ˈsker.kroʊ/","defVi":"bù nhìn (đuổi chim)","defEn":"a figure made of clothes stuffed with straw, set up in a field to frighten birds away","examples":["The farmer placed a [scarecrow] in the middle of the cornfield. (=Dịch: Người nông dân đặt một con bù nhìn ở giữa cánh đồng ngô.)","Birds quickly realized that the old [scarecrow] could not harm them. (=Dịch: Loài chim nhanh chóng nhận ra rằng con bù nhìn rơm cũ kỹ đó không thể làm hại chúng.)","The children dressed up an old coat and hat to make a [scarecrow]. (=Dịch: Lũ trẻ đã mặc một chiếc áo khoác cũ và đội mũ lên để làm thành một con bù nhìn.)"],"ukAudio":"/ai_services/tts3/?q=scarecrow&lang=en-GB&ipa=%2F%CB%88sker.kro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=scarecrow&lang=en-US&ipa=%2F%CB%88sker.kro%CA%8A%2F"},{"id":"lv_2_97","topic":"Tourism and Visits","word":"scenery","pos":"(n)","ipa":"/ˈsi.nə.ri/","defVi":"phong cảnh, cảnh quan","defEn":"the natural features of a landscape, especially when attractive to look at","examples":["The train journey offers breathtaking views of the mountain [scenery]. (=Dịch: Hành trình bằng tàu hỏa mang lại tầm nhìn tuyệt đẹp ra phong cảnh núi non.)","Many tourists visit this island to enjoy its peaceful coastal [scenery]. (=Dịch: Nhiều du khách ghé thăm hòn đảo này để tận hưởng cảnh quan miền duyên hải yên bình.)","We stopped the car several times to take photos of the stunning [scenery]. (=Dịch: Chúng tôi đã dừng xe lại nhiều lần để chụp ảnh phong cảnh tuyệt đẹp này.)"],"ukAudio":"/ai_services/tts3/?q=scenery&lang=en-GB&ipa=%2F%CB%88si.n%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=scenery&lang=en-US&ipa=%2F%CB%88si.n%C9%99.ri%2F"},{"id":"lv_2_98","topic":"Tourism and Visits","word":"scholar","pos":"(n)","ipa":"/ˈskɑ.lɚ/","defVi":"học giả","defEn":"a person who has studied a subject in great depth and knows a lot about it","examples":["The distinguished [scholar] published several books on ancient history. (=Dịch: Học giả lỗi lạc đã xuất bản một vài cuốn sách về lịch sử cổ đại.)","She is widely respected as a leading [scholar] in modern linguistics. (=Dịch: Bà ấy được tôn trọng rộng rãi như một học giả hàng đầu về ngôn ngữ học hiện đại.)","The library holds many rare manuscripts that attract research [scholar]s from abroad. (=Dịch: Thư viện lưu giữ nhiều bản thảo quý hiếm thu hút các học giả nghiên cứu từ nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=scholar&lang=en-GB&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=scholar&lang=en-US&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F"},{"id":"lv_2_99","topic":"Tourism and Visits","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"khoa học, mang tính khoa học","defEn":"relating to science or based on the methods used in science","examples":["Researchers need solid [scientific] evidence to support their theory. (=Dịch: Các nhà nghiên cứu cần những bằng chứng khoa học vững chắc để chứng minh cho giả thuyết của mình.)","The discovery was considered a major [scientific] breakthrough. (=Dịch: Phát hiện này được coi là một bước đột phá khoa học lớn.)","The experiment was carried out under strict [scientific] conditions. (=Dịch: Thí nghiệm đã được tiến hành dưới những điều kiện khoa học nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_2_100","topic":"Tourism and Visits","word":"script","pos":"(n)","ipa":"/skrɪpt/","defVi":"kịch bản","defEn":"the written text of a play, movie, or broadcast","examples":["The director made several changes to the original [script]. (=Dịch: Đạo diễn đã thực hiện một số thay đổi đối với kịch bản gốc.)","Actors must spend hours memorizing their lines from the [script]. (=Dịch: Các diễn viên phải dành hàng giờ để ghi nhớ lời thoại từ kịch bản.)","She submitted her film [script] to several production companies. (=Dịch: Cô ấy đã gửi kịch bản phim của mình tới một vài công ty sản xuất.)"],"ukAudio":"/ai_services/tts3/?q=script&lang=en-GB&ipa=%2Fskr%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=script&lang=en-US&ipa=%2Fskr%C9%AApt%2F"},{"id":"lv_2_101","topic":"Tourism and Visits","word":"seal","pos":"(n)","ipa":"/siːl/","defVi":"hải cẩu, chó biển","defEn":"a sea animal with smooth fur and flippers that lives in cold regions","examples":["We watched a [seal] basking in the sun on the rocky shore. (=Dịch: Chúng tôi đã ngắm nhìn một con hải cẩu đang phơi nắng trên bờ đá.)","The polar bear relies on the [seal] as its primary source of food. (=Dịch: Gấu bắc cực dựa vào hải cẩu như nguồn thức ăn chính của chúng.)","A baby [seal] has a thick white coat to keep warm in freezing temperatures. (=Dịch: Một con hải cẩu con có một lớp lông dày màu trắng để giữ ấm trong nhiệt độ đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=seal&lang=en-GB&ipa=%2Fsi%CB%90l%2F","usAudio":"/ai_services/tts3/?q=seal&lang=en-US&ipa=%2Fsi%CB%90l%2F"},{"id":"lv_2_102","topic":"Tourism and Visits","word":"seating","pos":"(n)","ipa":"/ˈsiː.tɪŋ/","defVi":"chỗ ngồi, sự sắp xếp chỗ ngồi","defEn":"the seats provided in a place, or the arrangement of seats","examples":["The new auditorium offers comfortable [seating] for over a thousand people. (=Dịch: Khán phòng mới mang lại chỗ ngồi thoải mái cho hơn một nghìn người.)","Outdoor [seating] is available during the warm summer months. (=Dịch: Chỗ ngồi ngoài trời luôn sẵn có trong suốt những tháng mùa hè ấm áp.)","The wedding planner carefully organized the [seating] plan for the reception. (=Dịch: Người lên kế hoạch đám cưới đã cẩn thận sắp xếp sơ đồ chỗ ngồi cho buổi tiệc chiêu đãi.)"],"ukAudio":"/ai_services/tts3/?q=seating&lang=en-GB&ipa=%2F%CB%88si%CB%90.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=seating&lang=en-US&ipa=%2F%CB%88si%CB%90.t%C9%AA%C5%8B%2F"},{"id":"lv_2_103","topic":"Tourism and Visits","word":"seek","pos":"(v)","ipa":"/siːk/","defVi":"tìm kiếm, mưu cầu","defEn":"to look for or try to obtain something","examples":["Graduates often [seek] advice from career counselors before applying for jobs. (=Dịch: Sinh viên mới tốt nghiệp thường tìm kiếm lời khuyên từ các chuyên gia tư vấn nghề nghiệp trước khi nộp đơn xin việc.)","The government is trying to [seek] new solutions to reduce traffic congestion. (=Dịch: Chính phủ đang nỗ lực tìm kiếm các giải pháp mới nhằm giảm thiểu tình trạng ùn tắc giao thông.)","Many immigrants [seek] better economic opportunities in foreign countries. (=Dịch: Nhiều người nhập cư tìm kiếm những cơ hội kinh tế tốt hơn ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsi%CB%90k%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsi%CB%90k%2F"},{"id":"lv_2_104","topic":"Tourism and Visits","word":"seminar","pos":"(n)","ipa":"/ˈsem.əˌnɑːr/","defVi":"hội thảo chuyên đề, buổi hội thảo","defEn":"a meeting or class for discussion and learning on a particular topic","examples":["I attended an informative [seminar] on modern business leadership. (=Dịch: Tôi đã tham dự một buổi hội thảo hữu ích về khả năng lãnh đạo doanh nghiệp hiện đại.)","The professor required all graduate students to participate in the weekly [seminar]. (=Dịch: Giáo sư yêu cầu tất cả học viên cao học phải tham gia buổi hội thảo chuyên đề hằng tuần.)","The university is hosting a three-day [seminar] on climate change. (=Dịch: Trường đại học đang tổ chức một hội thảo kéo dài ba ngày về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88sem.%C9%99%CB%8Cn%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88sem.%C9%99%CB%8Cn%C9%91%CB%90r%2F"},{"id":"lv_2_105","topic":"Tourism and Visits","word":"serpent","pos":"(n)","ipa":"/ˈsɜːr.pənt/","defVi":"con rắn (thường dùng trong văn học hoặc thần thoại)","defEn":"a snake, especially a large or poisonous one, often used in literary contexts","examples":["In ancient mythology, the [serpent] is often a symbol of wisdom and danger. (=Dịch: Trong thần thoại cổ đại, mãng xà thường là biểu tượng của sự thông thái và hiểm nguy.)","The statue depicted a warrior wrestling with a giant [serpent]. (=Dịch: Bức tượng miêu tả một chiến binh đang vật lộn với một con mãng xà khổng lồ.)","The fairy tale warned travelers about a venomous [serpent] guarding the treasure. (=Dịch: Câu chuyện cổ tích đã cảnh báo những người lữ hành về một con rắn độc đang canh giữ kho báu.)"],"ukAudio":"/ai_services/tts3/?q=serpent&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.p%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=serpent&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.p%C9%99nt%2F"},{"id":"lv_2_106","topic":"Tourism and Visits","word":"servant","pos":"(n)","ipa":"/ˈsɜːr.vənt/","defVi":"người hầu, người giúp việc","defEn":"a person employed in another person's house, doing domestic work","examples":["In the nineteenth century, wealthy families often employed a domestic [servant]. (=Dịch: Vào thế kỷ XIX, các gia đình giàu có thường thuê người hầu trong nhà.)","The loyal [servant] worked for the same household for more than thirty years. (=Dịch: Người đầy tớ trung thành đã phục vụ cho cùng một gia đình trong hơn ba mươi năm.)","He dedicated his life to politics and saw himself as a public [servant]. (=Dịch: Ông đã cống hiến cả cuộc đời cho chính trị và coi mình là một công bộc của nhân dân.)"],"ukAudio":"/ai_services/tts3/?q=servant&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.v%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=servant&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.v%C9%99nt%2F"},{"id":"lv_2_107","topic":"Tourism and Visits","word":"setback","pos":"(n)","ipa":"/ˈset.bæk/","defVi":"trở ngại, bước lùi","defEn":"a problem that delays or prevents progress","examples":["The unexpected injury was a major [setback] to her athletic career. (=Dịch: Chấn thương bất ngờ là một trở ngại lớn đối với sự nghiệp thể thao của cô ấy.)","Despite the financial [setback], the company managed to launch the product on time. (=Dịch: Bất chấp khó khăn tài chính, công ty vẫn xoay xở để ra mắt sản phẩm đúng hạn.)","Losing the contract was only a temporary [setback] for the startup. (=Dịch: Việc mất hợp đồng chỉ là một trở ngại tạm thời đối với công ty khởi nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=setback&lang=en-GB&ipa=%2F%CB%88set.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=setback&lang=en-US&ipa=%2F%CB%88set.b%C3%A6k%2F"},{"id":"lv_2_108","topic":"Tourism and Visits","word":"settler","pos":"(n)","ipa":"/ˈset.lər/","defVi":"người định cư, người khai hoang","defEn":"a person who moves with a group of others to live in a new country or area","examples":["The early [settler] community faced harsh winters and scarce resources. (=Dịch: Cộng đồng người đi khai hoang thời kỳ đầu đã phải đối mặt với những mùa đông khắc nghiệt và nguồn tài nguyên khan hiếm.)","Each [settler] was granted a piece of land to build a home and farm. (=Dịch: Mỗi người định cư đều được cấp một mảnh đất để xây nhà và làm trang trại.)","Historians study how the first European [settler] groups interacted with indigenous tribes. (=Dịch: Các nhà sử học nghiên cứu cách các nhóm người châu Âu đầu tiên đến định cư đã tương tác với các bộ lạc bản địa.)"],"ukAudio":"/ai_services/tts3/?q=settler&lang=en-GB&ipa=%2F%CB%88set.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=settler&lang=en-US&ipa=%2F%CB%88set.l%C9%99r%2F"},{"id":"lv_2_109","topic":"Tourism and Visits","word":"sew","pos":"(v)","ipa":"/soʊ/","defVi":"may, khâu","defEn":"to join or attach things together using a needle and thread","examples":["My grandmother taught me how to [sew] a button onto a shirt. (=Dịch: Bà tôi đã dạy tôi cách khâu một chiếc cúc vào áo sơ mi.)","She loves to [sew] her own clothes instead of buying them from stores. (=Dịch: Cô ấy thích tự may quần áo cho mình thay vì mua từ các cửa hàng.)","The tailor used durable thread to [sew] the torn seams of the jacket. (=Dịch: Người thợ may đã dùng chỉ bền để khâu lại các đường may bị rách của chiếc áo khoác.)"],"ukAudio":"/ai_services/tts3/?q=sew&lang=en-GB&ipa=%2Fso%CA%8A%2F","usAudio":"/ai_services/tts3/?q=sew&lang=en-US&ipa=%2Fso%CA%8A%2F"},{"id":"lv_2_110","topic":"Tourism and Visits","word":"sex","pos":"(n)","ipa":"/sɛks/","defVi":"giới tính (về mặt sinh học)","defEn":"the biological state of being male or female","examples":["Please indicate your [sex] and date of birth on the application form. (=Dịch: Vui lòng ghi rõ giới tính và ngày sinh của bạn trên mẫu đơn đăng ký.)","Discrimination on the basis of [sex] is strictly prohibited in the workplace. (=Dịch: Phân biệt đối xử dựa trên giới tính bị nghiêm cấm tại nơi làm việc.)","The research studied differences in behavior related to [sex] and age. (=Dịch: Nghiên cứu đã xem xét những khác biệt trong hành vi liên quan đến giới tính và độ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=sex&lang=en-GB&ipa=%2Fs%C9%9Bks%2F","usAudio":"/ai_services/tts3/?q=sex&lang=en-US&ipa=%2Fs%C9%9Bks%2F"},{"id":"lv_2_111","topic":"Tourism and Visits","word":"shed","pos":"(n)","ipa":"/ʃɛd/","defVi":"nhà kho nhỏ, lán để đồ","defEn":"a small, simple building used for storing tools or sheltering animals","examples":["He keeps all of his gardening equipment in a wooden [shed] behind the house. (=Dịch: Anh ấy cất giữ toàn bộ dụng cụ làm vườn của mình trong một cái lán bằng gỗ phía sau nhà.)","They converted the old tool [shed] into a cozy outdoor workshop. (=Dịch: Họ đã cải tạo nhà kho chứa dụng cụ cũ thành một xưởng làm việc ngoài trời ấm cúng.)","The bicycle was stored safely in the backyard [shed] during the winter. (=Dịch: Chiếc xe đạp đã được cất giữ an toàn trong nhà kho sau vườn suốt mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=shed&lang=en-GB&ipa=%2F%CA%83%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=shed&lang=en-US&ipa=%2F%CA%83%C9%9Bd%2F"},{"id":"lv_2_112","topic":"Tourism and Visits","word":"situate","pos":"(v)","ipa":"/ˈsɪtʃ.u.eɪt/","defVi":"đặt ở vị trí, định vị","defEn":"to place or locate something in a specific position or context","examples":["The developers decided to [situate] the new hotel near the coast. (=Dịch: Các nhà phát triển đã quyết định đặt khách sạn mới ở gần bờ biển.)","The author tries to [situate] the historical events within their social background. (=Dịch: Tác giả cố gắng đặt các sự kiện lịch sử vào trong bối cảnh xã hội của chúng.)","It is important to [situate] the school within easy reach of public transport. (=Dịch: Việc đặt trường học ở nơi thuận tiện tiếp cận các phương tiện giao thông công cộng là rất quan trọng.)"],"ukAudio":"/ai_services/tts3/?q=situate&lang=en-GB&ipa=%2F%CB%88s%C9%AAt%CA%83.u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=situate&lang=en-US&ipa=%2F%CB%88s%C9%AAt%CA%83.u.e%C9%AAt%2F"},{"id":"lv_2_113","topic":"Tourism and Visits","word":"solar","pos":"(adj)","ipa":"/ˈsoʊ.lɚ/","defVi":"thuộc về năng lượng mặt trời, thái dương","defEn":"connected with or using the energy of the sun","examples":["Many homeowners are installing [solar] panels to reduce electricity costs. (=Dịch: Nhiều chủ nhà đang lắp đặt các tấm pin mặt trời để giảm chi phí tiền điện.)","Investing in [solar] energy is crucial for a sustainable future. (=Dịch: Đầu tư vào năng lượng mặt trời là rất quan trọng cho một tương lai bền vững.)","The planet Earth is the third planet from the sun in our [solar] system. (=Dịch: Trái đất là hành tinh thứ ba tính từ mặt trời trong hệ mặt trời của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=solar&lang=en-GB&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=solar&lang=en-US&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F"},{"id":"lv_2_114","topic":"Tourism and Visits","word":"souvenir","pos":"(n)","ipa":"/ˌsuː.vəˈnɪr/","defVi":"quà lưu niệm, vật kỷ niệm","defEn":"something kept or bought as a reminder of a place, person, or event","examples":["She bought a handmade postcard as a [souvenir] of her trip to Paris. (=Dịch: Cô ấy đã mua một tấm bưu thiếp thủ công làm quà lưu niệm cho chuyến đi Paris của mình.)","The small gift shop sells a variety of local [souvenir] items. (=Dịch: Cửa hàng quà tặng nhỏ bán nhiều món đồ lưu niệm địa phương đa dạng.)","I kept the concert ticket stub as a [souvenir] of that wonderful night. (=Dịch: Tôi đã giữ lại cuống vé buổi hòa nhạc làm kỷ niệm cho đêm tuyệt vời đó.)"],"ukAudio":"/ai_services/tts3/?q=souvenir&lang=en-GB&ipa=%2F%CB%8Csu%CB%90.v%C9%99%CB%88n%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=souvenir&lang=en-US&ipa=%2F%CB%8Csu%CB%90.v%C9%99%CB%88n%C9%AAr%2F"},{"id":"lv_2_115","topic":"Tourism and Visits","word":"specialised","pos":"(adj)","ipa":"/ˈspɛʃ.ə.laɪzd/","defVi":"chuyên dụng, chuyên môn hóa","defEn":"trained, designed, or developed for a particular purpose or area of knowledge","examples":["Performing this complex surgery requires [specialised] medical equipment. (=Dịch: Việc thực hiện ca phẫu thuật phức tạp này đòi hỏi các thiết bị y tế chuyên dụng.)","She sought advice from a lawyer with [specialised] knowledge in intellectual property. (=Dịch: Cô ấy đã tìm kiếm lời khuyên từ một luật sư có kiến thức chuyên môn sâu về sở hữu trí tuệ.)","The company offers [specialised] training programs for new engineers. (=Dịch: Công ty cung cấp các chương trình đào tạo chuyên biệt cho các kỹ sư mới.)"],"ukAudio":"/ai_services/tts3/?q=specialised&lang=en-GB&ipa=%2F%CB%88sp%C9%9B%CA%83.%C9%99.la%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=specialised&lang=en-US&ipa=%2F%CB%88sp%C9%9B%CA%83.%C9%99.la%C9%AAzd%2F"},{"id":"lv_2_116","topic":"Tourism and Visits","word":"spectacular","pos":"(adj)","ipa":"/spɛkˈtæk.jə.lɚ/","defVi":"hùng vĩ, ngoạn mục, ấn tượng","defEn":"extremely impressive, grand, or striking to see","examples":["The mountaintop offers a [spectacular] view of the entire valley. (=Dịch: Đỉnh núi mang lại một khung cảnh ngoạn mục của toàn bộ thung lũng.)","The festival ended with a [spectacular] fireworks display over the lake. (=Dịch: Lễ hội đã kết thúc với một màn trình diễn pháo hoa ngoạn mục trên hồ.)","The team achieved a [spectacular] victory in the final minutes of the match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fsp%C9%9Bk%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fsp%C9%9Bk%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_2_117","topic":"Tourism and Visits","word":"splash","pos":"(n)","ipa":"/splæʃ/","defVi":"tiếng nước bắn, vết bắn nước","defEn":"the sound or movement of liquid scattering when hit by an object","examples":["We heard a loud [splash] when the children jumped into the pool. (=Dịch: Chúng tôi nghe thấy một tiếng nước bắn lớn khi lũ trẻ nhảy xuống hồ bơi.)","The passing car made a large [splash] of muddy water on the sidewalk. (=Dịch: Chiếc xe chạy qua đã làm bắn một vệt nước bùn lớn lên vỉa hè.)","A [splash] of lemon juice will enhance the fresh flavor of the salad. (=Dịch: Một vài giọt nước cốt chanh sẽ làm tăng hương vị tươi ngon của món salad.)"],"ukAudio":"/ai_services/tts3/?q=splash&lang=en-GB&ipa=%2Fspl%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=splash&lang=en-US&ipa=%2Fspl%C3%A6%CA%83%2F"},{"id":"lv_2_118","topic":"Tourism and Visits","word":"stable","pos":"(n)","ipa":"/ˈsteɪ.bəl/","defVi":"chuồng ngựa","defEn":"a building where domestic animals, especially horses, are kept and fed","examples":["The farmer led the racehorses into the [stable] before the storm began. (=Dịch: Người nông dân đã dẫn những con ngựa đua vào chuồng trước khi cơn bão bắt đầu.)","She spent the morning cleaning out each [stable] at the equestrian center. (=Dịch: Cô ấy đã dành cả buổi sáng để dọn dẹp từng ô chuồng tại trung tâm cưỡi ngựa.)","There were ten horses resting quietly inside the wooden [stable]. (=Dịch: Có mười con ngựa đang nghỉ ngơi yên tĩnh bên trong chuồng ngựa bằng gỗ.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_2_119","topic":"Tourism and Visits","word":"stadium","pos":"(n)","ipa":"/ˈsteɪ.di.əm/","defVi":"sân vận động","defEn":"a large sports ground surrounded by tiers of seats for spectators","examples":["Thousands of excited fans gathered inside the [stadium] for the championship match. (=Dịch: Hàng ngàn người hâm mộ cuồng nhiệt đã tụ tập bên trong sân vận động để theo dõi trận chung kết.)","The rock band will perform live at the national [stadium] next month. (=Dịch: Ban nhạc rock sẽ biểu diễn trực tiếp tại sân vận động quốc gia vào tháng tới.)","The city invested millions of dollars to build a modern sports [stadium]. (=Dịch: Thành phố đã đầu tư hàng triệu đô la để xây dựng một sân vận động thể thao hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=stadium&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stadium&lang=en-US&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F"},{"id":"lv_2_120","topic":"Tourism and Visits","word":"staircase","pos":"(n)","ipa":"/ˈster.keɪs/","defVi":"cầu thang","defEn":"a set of stairs inside a building, including its supporting structure","examples":["We walked up the spiral [staircase] to reach the top floor. (=Dịch: Chúng tôi bước lên chiếc cầu thang xoắn ốc để lên tầng trên cùng.)","The grand [staircase] in the hotel lobby impressed all the guests. (=Dịch: Chiếc cầu thang tráng lệ ở sảnh khách sạn đã gây ấn tượng với tất cả các vị khách.)","She carefully descended the wooden [staircase] in the dark. (=Dịch: Cô ấy cẩn thận bước xuống chiếc cầu thang gỗ trong bóng tối.)"],"ukAudio":"/ai_services/tts3/?q=staircase&lang=en-GB&ipa=%2F%CB%88ster.ke%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=staircase&lang=en-US&ipa=%2F%CB%88ster.ke%C9%AAs%2F"},{"id":"lv_2_121","topic":"Tourism and Visits","word":"stall","pos":"(n)","ipa":"/stɔːl/","defVi":"quầy hàng, sạp hàng","defEn":"a large table or small open-fronted shop from which goods are sold in a market","examples":["She bought fresh fruits from a market [stall]. (=Dịch: Cô ấy đã mua trái cây tươi từ một quầy hàng ở chợ.)","The street food [stall] attracts hundreds of customers every evening. (=Dịch: Quầy ẩm thực đường phố thu hút hàng trăm thực khách mỗi tối.)","He decided to set up a book [stall] near the university. (=Dịch: Anh ấy quyết định dựng một quầy sách gần trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=stall&lang=en-GB&ipa=%2Fst%C9%94%CB%90l%2F","usAudio":"/ai_services/tts3/?q=stall&lang=en-US&ipa=%2Fst%C9%94%CB%90l%2F"},{"id":"lv_2_122","topic":"Tourism and Visits","word":"steam","pos":"(n)","ipa":"/stiːm/","defVi":"hơi nước","defEn":"the hot gas that is produced when water boils","examples":["White [steam] rose from the boiling kettle. (=Dịch: Hơi nước trắng bốc lên từ chiếc ấm đang sôi.)","The bathroom mirror was covered in thick [steam]. (=Dịch: Gương trong phòng tắm bị bao phủ bởi một lớp hơi nước dày đặc.)","The factory uses [steam] power to generate electricity. (=Dịch: Nhà máy sử dụng năng lượng hơi nước để phát điện.)"],"ukAudio":"/ai_services/tts3/?q=steam&lang=en-GB&ipa=%2Fsti%CB%90m%2F","usAudio":"/ai_services/tts3/?q=steam&lang=en-US&ipa=%2Fsti%CB%90m%2F"},{"id":"lv_2_123","topic":"Tourism and Visits","word":"stunning","pos":"(adj)","ipa":"/ˈstʌn.ɪŋ/","defVi":"tuyệt đẹp, lộng lẫy, ấn tượng sâu sắc","defEn":"extremely impressive, beautiful, or attractive","examples":["The hotel room offers a [stunning] view of the ocean. (=Dịch: Phòng khách sạn có tầm nhìn tuyệt đẹp hướng ra đại dương.)","She looked absolutely [stunning] in her wedding dress. (=Dịch: Cô ấy trông vô cùng lộng lẫy trong chiếc váy cưới.)","The team achieved a [stunning] victory in the final match. (=Dịch: Đội bóng đã giành được một chiến thắng ngoạn mục trong trận chung kết.)"],"ukAudio":"/ai_services/tts3/?q=stunning&lang=en-GB&ipa=%2F%CB%88st%CA%8Cn.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=stunning&lang=en-US&ipa=%2F%CB%88st%CA%8Cn.%C9%AA%C5%8B%2F"},{"id":"lv_2_124","topic":"Tourism and Visits","word":"summit","pos":"(n)","ipa":"/ˈsʌm.ɪt/","defVi":"đỉnh núi; hội nghị thượng đỉnh","defEn":"the highest point of a mountain; or an official meeting between heads of government","examples":["The climbers finally reached the [summit] after hours of hiking. (=Dịch: Những người leo núi cuối cùng đã lên tới đỉnh núi sau nhiều giờ đi bộ đường dài.)","World leaders gathered in Geneva for an economic [summit]. (=Dịch: Các nhà lãnh đạo thế giới đã tập trung tại Geneva để tham dự một hội nghị thượng đỉnh về kinh tế.)","Thick clouds hid the mountain [summit] from view. (=Dịch: Những đám mây dày đặc đã che khuất đỉnh núi khỏi tầm nhìn.)"],"ukAudio":"/ai_services/tts3/?q=summit&lang=en-GB&ipa=%2F%CB%88s%CA%8Cm.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=summit&lang=en-US&ipa=%2F%CB%88s%CA%8Cm.%C9%AAt%2F"},{"id":"lv_2_125","topic":"Tourism and Visits","word":"sunny","pos":"(adj)","ipa":"/ˈsʌn.i/","defVi":"có nắng, ngập tràn ánh nắng","defEn":"bright with sunlight; receiving a lot of direct light from the sun","examples":["We enjoyed a picnic in the park on a warm, [sunny] day. (=Dịch: Chúng tôi đã tận hưởng một buổi dã ngoại trong công viên vào một ngày ấm áp và đầy nắng.)","The living room is very bright and [sunny] in the morning. (=Dịch: Phòng khách rất sáng sủa và ngập tràn ánh nắng vào buổi sáng.)","They planned their holiday to a [sunny] coastal town. (=Dịch: Họ đã lên kế hoạch cho kỳ nghỉ của mình đến một thị trấn ven biển đầy nắng.)"],"ukAudio":"/ai_services/tts3/?q=sunny&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.i%2F","usAudio":"/ai_services/tts3/?q=sunny&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.i%2F"},{"id":"lv_2_126","topic":"Tourism and Visits","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng bổ sung","defEn":"something added to complete a thing, make up for a deficiency, or extend an existing item","examples":["He takes a daily vitamin [supplement] to boost his immune system. (=Dịch: Anh ấy uống thực phẩm bổ sung vitamin hằng ngày để tăng cường hệ miễn dịch.)","The weekend newspaper includes a colorful travel [supplement]. (=Dịch: Tờ báo cuối tuần bao gồm một phụ trương du lịch đầy màu sắc.)","Calcium is an important nutritional [supplement] for older adults. (=Dịch: Canxi là một chất bổ sung dinh dưỡng quan trọng cho người lớn tuổi.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_2_127","topic":"Tourism and Visits","word":"surf","pos":"(v)","ipa":"/sɜːrf/","defVi":"lướt sóng; lướt web","defEn":"to ride on waves while standing on a special board; or to look through information on the internet","examples":["Many tourists visit this beach to [surf] the giant waves. (=Dịch: Nhiều du khách ghé thăm bãi biển này để lướt những con sóng khổng lồ.)","He often spends his free time [surfing] the internet for news. (=Dịch: Anh ấy thường dành thời gian rảnh để lướt mạng xem tin tức.)","She learned how to [surf] during her summer vacation in Hawaii. (=Dịch: Cô ấy đã học lướt sóng trong kỳ nghỉ hè ở Hawaii.)"],"ukAudio":"/ai_services/tts3/?q=surf&lang=en-GB&ipa=%2Fs%C9%9C%CB%90rf%2F","usAudio":"/ai_services/tts3/?q=surf&lang=en-US&ipa=%2Fs%C9%9C%CB%90rf%2F"},{"id":"lv_2_128","topic":"Tourism and Visits","word":"tape","pos":"(n)","ipa":"/teɪp/","defVi":"băng dính; băng từ (ghi âm, ghi hình)","defEn":"a long, narrow strip of sticky material used to hold things together, or a magnetic strip used for recording","examples":["She used adhesive [tape] to seal the cardboard box. (=Dịch: Cô ấy đã dùng băng dính để dán kín chiếc hộp các-tông.)","My grandfather still listens to music on an old cassette [tape]. (=Dịch: Ông tôi vẫn nghe nhạc bằng một cuộn băng cát-xét cũ.)","The police marked the crime scene with yellow warning [tape]. (=Dịch: Cảnh sát đã khoanh vùng hiện trường vụ án bằng băng cảnh báo màu vàng.)"],"ukAudio":"/ai_services/tts3/?q=tape&lang=en-GB&ipa=%2Fte%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=tape&lang=en-US&ipa=%2Fte%C9%AAp%2F"},{"id":"lv_2_129","topic":"Tourism and Visits","word":"telegraph","pos":"(n)","ipa":"/ˈtel.ə.ɡræf/","defVi":"điện báo, máy điện báo","defEn":"an early system or device used for sending messages along wires over long distances","examples":["The invention of the [telegraph] revolutionized long-distance communication. (=Dịch: Phát minh ra máy điện báo đã cách mạng hóa phương thức liên lạc đường dài.)","Before telephones were common, urgent news was sent by [telegraph]. (=Dịch: Trước khi điện thoại trở nên phổ biến, tin tức khẩn cấp được gửi bằng điện báo.)","The operator decoded the incoming message from the electric [telegraph]. (=Dịch: Người điện báo viên đã giải mã tin nhắn nhận được từ máy điện báo.)"],"ukAudio":"/ai_services/tts3/?q=telegraph&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=telegraph&lang=en-US&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F"},{"id":"lv_2_130","topic":"Tourism and Visits","word":"temporarily","pos":"(adv)","ipa":"/ˌtɛm.pəˈrɛr.ə.li/","defVi":"tạm thời","defEn":"for a limited time only and not permanently","examples":["The library will be [temporarily] closed for renovations next week. (=Dịch: Thư viện sẽ tạm thời đóng cửa để cải tạo vào tuần tới.)","She is [temporarily] staying with her aunt until she finds an apartment. (=Dịch: Cô ấy đang tạm thời ở cùng dì của mình cho đến khi tìm được một căn hộ.)","The website is [temporarily] unavailable due to technical issues. (=Dịch: Trang web tạm thời không thể truy cập do các sự cố kỹ thuật.)"],"ukAudio":"/ai_services/tts3/?q=temporarily&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Bm.p%C9%99%CB%88r%C9%9Br.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=temporarily&lang=en-US&ipa=%2F%CB%8Ct%C9%9Bm.p%C9%99%CB%88r%C9%9Br.%C9%99.li%2F"},{"id":"lv_2_131","topic":"Tourism and Visits","word":"terrace","pos":"(n)","ipa":"/ˈtɛr.əs/","defVi":"sân thượng, sân hiên","defEn":"a flat outdoor area next to a building or on a roof, used for relaxing","examples":["We had breakfast outside on the hotel [terrace] overlooking the ocean. (=Dịch: Chúng tôi đã ăn sáng ngoài trời trên sân hiên khách sạn nhìn ra đại dương.)","The restaurant has a rooftop [terrace] with a wonderful view of the city. (=Dịch: Nhà hàng có sân thượng với tầm nhìn tuyệt đẹp ra thành phố.)","Potted plants and comfortable chairs decorated the spacious [terrace]. (=Dịch: Những chậu cây và những chiếc ghế thoải mái tô điểm cho khoảng sân hiên rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=terrace&lang=en-GB&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=terrace&lang=en-US&ipa=%2F%CB%88t%C9%9Br.%C9%99s%2F"},{"id":"lv_2_132","topic":"Tourism and Visits","word":"tractor","pos":"(n)","ipa":"/ˈtræk.tɚ/","defVi":"máy kéo","defEn":"a powerful vehicle with large tires used on farms to pull heavy equipment","examples":["The farmer used a [tractor] to plow the vast cornfields. (=Dịch: Người nông dân đã dùng một chiếc máy kéo để cày những cánh đồng ngô rộng lớn.)","A broken [tractor] was parked near the entrance of the barn. (=Dịch: Một chiếc máy kéo bị hỏng đỗ gần lối vào của nhà kho.)","Modern [tractor] models are equipped with GPS technology for precise farming. (=Dịch: Các mẫu máy kéo hiện đại được trang bị công nghệ GPS để canh tác chuẩn xác.)"],"ukAudio":"/ai_services/tts3/?q=tractor&lang=en-GB&ipa=%2F%CB%88tr%C3%A6k.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tractor&lang=en-US&ipa=%2F%CB%88tr%C3%A6k.t%C9%9A%2F"},{"id":"lv_2_133","topic":"Tourism and Visits","word":"tram","pos":"(n)","ipa":"/træm/","defVi":"xe điện (chạy trên đường ray)","defEn":"an electric vehicle that moves along rails in the streets of a city","examples":["Taking the [tram] is the fastest way to get across the downtown area. (=Dịch: Đi xe điện là cách nhanh nhất để di chuyển qua khu vực trung tâm thành phố.)","She waited at the stop for the next [tram] to arrive. (=Dịch: Cô ấy đã đợi ở trạm chờ chuyến xe điện tiếp theo đến.)","Many European cities still rely heavily on the [tram] for public transport. (=Dịch: Nhiều thành phố châu Âu vẫn phụ thuộc rất nhiều vào xe điện cho giao thông công cộng.)"],"ukAudio":"/ai_services/tts3/?q=tram&lang=en-GB&ipa=%2Ftr%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=tram&lang=en-US&ipa=%2Ftr%C3%A6m%2F"},{"id":"lv_2_134","topic":"Tourism and Visits","word":"trek","pos":"(n)","ipa":"/trɛk/","defVi":"chuyến đi bộ đường dài, hành trình vất vả","defEn":"a long, difficult journey, usually made on foot","examples":["They organized a week-long [trek] through the Himalayan mountains. (=Dịch: Họ đã tổ chức một chuyến đi bộ đường dài kéo dài một tuần qua dãy núi Himalaya.)","The walk back home in the heavy snow felt like a difficult [trek]. (=Dịch: Quãng đường đi bộ về nhà trong tuyết dày cảm giác như một chuyến đi đầy gian nan.)","Proper footwear is essential for a safe [trek] across rugged terrain. (=Dịch: Giày dép phù hợp là điều thiết yếu cho một chuyến đi bộ an toàn qua địa hình gồ ghề.)"],"ukAudio":"/ai_services/tts3/?q=trek&lang=en-GB&ipa=%2Ftr%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=trek&lang=en-US&ipa=%2Ftr%C9%9Bk%2F"},{"id":"lv_2_135","topic":"Tourism and Visits","word":"tuition","pos":"(n)","ipa":"/tuˈɪʃ.ən/","defVi":"học phí","defEn":"money that you pay for being taught, especially at a college or university","examples":["The university announced an increase in [tuition] for the upcoming academic year. (=Dịch: Trường đại học đã thông báo tăng học phí cho năm học sắp tới.)","She received a full scholarship that covered all of her college [tuition]. (=Dịch: Cô ấy đã nhận được học bổng toàn phần chi trả toàn bộ học phí đại học.)","Many students work part-time jobs to help pay for their [tuition] and living expenses. (=Dịch: Nhiều sinh viên làm công việc bán thời gian để trang trải học phí và chi phí sinh hoạt.)"],"ukAudio":"/ai_services/tts3/?q=tuition&lang=en-GB&ipa=%2Ftu%CB%88%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=tuition&lang=en-US&ipa=%2Ftu%CB%88%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_2_136","topic":"Tourism and Visits","word":"turtle","pos":"(n)","ipa":"/ˈtɝ.t̬əl/","defVi":"con rùa","defEn":"a reptile with a hard, round shell that moves slowly and lives on land or in water","examples":["We saw a sea [turtle] swimming gracefully near the coral reef. (=Dịch: Chúng tôi đã nhìn thấy một con rùa biển bơi lội duyên dáng gần rạn san hô.)","The baby [turtle] crawled across the sand toward the ocean waves. (=Dịch: Con rùa con bò qua bãi cát về phía những con sóng biển.)","A [turtle] can retract its head and legs into its shell when threatened. (=Dịch: Một con rùa có thể rụt đầu và chân vào mai khi bị đe dọa.)"],"ukAudio":"/ai_services/tts3/?q=turtle&lang=en-GB&ipa=%2F%CB%88t%C9%9D.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=turtle&lang=en-US&ipa=%2F%CB%88t%C9%9D.t%CC%AC%C9%99l%2F"},{"id":"lv_2_137","topic":"Tourism and Visits","word":"unsure","pos":"(adj)","ipa":"/ʌnˈʃʊr/","defVi":"không chắc chắn, lưỡng lự","defEn":"not feeling certain, confident, or definite about something","examples":["I am still [unsure] about which university course to choose. (=Dịch: Tôi vẫn chưa chắc chắn về việc nên chọn khóa học đại học nào.)","He gave an [unsure] smile because he did not understand the joke. (=Dịch: Anh ấy nở một nụ cười ngập ngừng vì không hiểu câu chuyện đùa.)","If you are [unsure] of the instructions, please ask the teacher for help. (=Dịch: Nếu bạn chưa rõ các chỉ dẫn, hãy nhờ giáo viên giúp đỡ.)"],"ukAudio":"/ai_services/tts3/?q=unsure&lang=en-GB&ipa=%2F%CA%8Cn%CB%88%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=unsure&lang=en-US&ipa=%2F%CA%8Cn%CB%88%CA%83%CA%8Ar%2F"},{"id":"lv_2_138","topic":"Tourism and Visits","word":"upper","pos":"(adj)","ipa":"/ˈʌp.ɚ/","defVi":"ở phía trên, tầng trên","defEn":"located higher up or in a top position","examples":["The bedrooms are located on the [upper] floor of the house. (=Dịch: Các phòng ngủ nằm ở tầng trên của ngôi nhà.)","He had an injury to his [upper] arm during the tennis match. (=Dịch: Anh ấy đã bị chấn thương ở phần bắp tay trên trong trận đấu quần vợt.)","The [upper] levels of management attended the annual business summit. (=Dịch: Các cấp quản lý cấp cao đã tham dự hội nghị thượng đỉnh kinh doanh thường niên.)"],"ukAudio":"/ai_services/tts3/?q=upper&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=upper&lang=en-US&ipa=%2F%CB%88%CA%8Cp.%C9%9A%2F"},{"id":"lv_2_139","topic":"Tourism and Visits","word":"vegetarian","pos":"(adj)","ipa":"/ˌvɛdʒ.əˈtɛr.i.ən/","defVi":"ăn chay, (món) chay","defEn":"relating to a diet or meals that do not contain any meat or fish","examples":["The café offers a wide variety of delicious [vegetarian] options. (=Dịch: Quán cà phê có nhiều lựa chọn món chay ngon miệng.)","She follows a strict [vegetarian] lifestyle for ethical and environmental reasons. (=Dịch: Cô ấy theo đuổi lối sống ăn chay nghiêm ngặt vì các lý do đạo đức và môi trường.)","We ordered a [vegetarian] pizza topped with mushrooms, peppers, and olives. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza chay phủ nấm, ớt chuông và ô liu.)"],"ukAudio":"/ai_services/tts3/?q=vegetarian&lang=en-GB&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetarian&lang=en-US&ipa=%2F%CB%8Cv%C9%9Bd%CA%92.%C9%99%CB%88t%C9%9Br.i.%C9%99n%2F"},{"id":"lv_2_140","topic":"Tourism and Visits","word":"vip","pos":"(n)","ipa":"/ˌviː.aɪˈpiː/","defVi":"khách VIP, nhân vật rất quan trọng","defEn":"a very important person who receives special treatment and privileges","examples":["The hotel provides a private lounge for each [VIP] guest. (=Dịch: Khách sạn cung cấp một phòng chờ riêng cho mỗi khách VIP.)","Security was tightened around the concert hall before the [VIP] arrived. (=Dịch: An ninh đã được thắt chặt quanh hội trường hòa nhạc trước khi khách VIP đến.)","Ticket holders for the [VIP] section had access to backstage passes. (=Dịch: Những người sở hữu vé khu vực VIP được cấp thẻ vào khu vực hậu trường.)"],"ukAudio":"/ai_services/tts3/?q=vip&lang=en-GB&ipa=%2F%CB%8Cvi%CB%90.a%C9%AA%CB%88pi%CB%90%2F","usAudio":"/ai_services/tts3/?q=vip&lang=en-US&ipa=%2F%CB%8Cvi%CB%90.a%C9%AA%CB%88pi%CB%90%2F"},{"id":"lv_2_141","topic":"Tourism and Visits","word":"wagon","pos":"(n)","ipa":"/ˈwæɡ.ən/","defVi":"xe ngựa kéo, xe goòng, xe bò","defEn":"a heavy four-wheeled vehicle pulled by horses or oxen, used for carrying heavy loads","examples":["The pioneers crossed the plains in a wooden [wagon]. (=Dịch: Những người khai hoang đã băng qua các đồng bằng trên một chiếc xe ngựa kéo bằng gỗ.)","Farmers used a [wagon] to transport sacks of grain to the local mill. (=Dịch: Nông dân đã dùng xe kéo để vận chuyển các bao ngũ cốc đến cối xay địa phương.)","A broken wheel brought the heavy [wagon] to a sudden halt. (=Dịch: Một chiếc bánh xe bị gãy đã khiến chiếc xe kéo nặng nề đột ngột dừng lại.)"],"ukAudio":"/ai_services/tts3/?q=wagon&lang=en-GB&ipa=%2F%CB%88w%C3%A6%C9%A1.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=wagon&lang=en-US&ipa=%2F%CB%88w%C3%A6%C9%A1.%C9%99n%2F"},{"id":"lv_2_142","topic":"Tourism and Visits","word":"wander","pos":"(v)","ipa":"/ˈwɑːn.dɚ/","defVi":"đi lang thang, tản bộ","defEn":"to walk or move around without a clear purpose or direction","examples":["Tourists often [wander] through the narrow streets of the old quarter. (=Dịch: Khách du lịch thường đi lang thang qua những con phố hẹp của khu phố cổ.)","The lost child began to [wander] aimlessly across the park. (=Dịch: Đứa trẻ bị lạc bắt đầu đi lang thang không mục đích khắp công viên.)","He likes to [wander] into the bookstore during his lunch break. (=Dịch: Anh ấy thích tản bộ vào hiệu sách trong giờ nghỉ trưa.)"],"ukAudio":"/ai_services/tts3/?q=wander&lang=en-GB&ipa=%2F%CB%88w%C9%91%CB%90n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=wander&lang=en-US&ipa=%2F%CB%88w%C9%91%CB%90n.d%C9%9A%2F"},{"id":"lv_2_143","topic":"Tourism and Visits","word":"wetland","pos":"(n)","ipa":"/ˈwet.lənd/","defVi":"vùng đất ngập nước","defEn":"an area of land that is naturally saturated with water, such as a swamp or marsh","examples":["The coastal [wetland] provides a safe breeding ground for many rare birds. (=Dịch: Vùng đất ngập nước ven biển cung cấp nơi sinh sản an toàn cho nhiều loài chim quý hiếm.)","Environmentalists campaigned hard to protect the local [wetland] from commercial development. (=Dịch: Các nhà môi trường học đã vận động mạnh mẽ để bảo vệ vùng đất ngập nước địa phương khỏi sự phát triển thương mại.)","A guided boat tour took us deep into the mysterious [wetland]. (=Dịch: Một chuyến tham quan bằng thuyền có hướng dẫn viên đã đưa chúng tôi vào sâu bên trong vùng đất ngập nước đầy bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=wetland&lang=en-GB&ipa=%2F%CB%88wet.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=wetland&lang=en-US&ipa=%2F%CB%88wet.l%C9%99nd%2F"},{"id":"lv_2_144","topic":"Tourism and Visits","word":"wetsuit","pos":"(n)","ipa":"/ˈwet.suːt/","defVi":"bộ đồ lặn (giữ nhiệt)","defEn":"a tight-fitting rubber suit worn by divers and surfers to keep warm in cold water","examples":["He put on a thick [wetsuit] before diving into the chilly ocean. (=Dịch: Anh ấy mặc một bộ đồ lặn dày trước khi lặn xuống đại dương lạnh giá.)","Surfers hang their [wetsuit] gear to dry immediately after leaving the beach. (=Dịch: Những người lướt sóng treo bộ đồ lặn của họ lên cho khô ngay sau khi rời bãi biển.)","A properly fitted [wetsuit] prevents body heat from escaping in cold water. (=Dịch: Một bộ đồ lặn vừa vặn sẽ ngăn nhiệt lượng cơ thể thoát ra ngoài khi ở trong nước lạnh.)"],"ukAudio":"/ai_services/tts3/?q=wetsuit&lang=en-GB&ipa=%2F%CB%88wet.su%CB%90t%2F","usAudio":"/ai_services/tts3/?q=wetsuit&lang=en-US&ipa=%2F%CB%88wet.su%CB%90t%2F"},{"id":"lv_2_145","topic":"Tourism and Visits","word":"whale","pos":"(n)","ipa":"/ˈweɪl/","defVi":"cá voi","defEn":"a very large marine mammal that breathes air through a blowhole on top of its head","examples":["We were lucky enough to see a blue [whale] breach the surface of the sea. (=Dịch: Chúng tôi đã đủ may mắn khi nhìn thấy một con cá voi xanh nhô lên khỏi mặt biển.)","Many international treaties were signed to protect the endangered [whale] species. (=Dịch: Nhiều hiệp ước quốc tế đã được ký kết để bảo vệ các loài cá voi có nguy cơ tuyệt chủng.)","The guide pointed out a migrating [whale] swimming near our boat. (=Dịch: Người hướng dẫn viên đã chỉ cho chúng tôi một con cá voi đang di cư bơi gần thuyền.)"],"ukAudio":"/ai_services/tts3/?q=whale&lang=en-GB&ipa=%2F%CB%88we%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=whale&lang=en-US&ipa=%2F%CB%88we%C9%AAl%2F"},{"id":"lv_2_146","topic":"Tourism and Visits","word":"willow","pos":"(n)","ipa":"/ˈwɪl.oʊ/","defVi":"cây liễu","defEn":"a tree with long, flexible branches and narrow leaves that often grows near water","examples":["A weeping [willow] swayed gently over the edge of the riverbank. (=Dịch: Một cây liễu rủ đung đưa nhẹ nhàng bên mép bờ sông.)","The artist sketched the graceful shape of a [willow] in his notebook. (=Dịch: Người họa sĩ đã phác thảo hình dáng duyên dáng của một cây liễu vào cuốn sổ tay của mình.)","We sat under the shade of a large [willow] to escape the summer heat. (=Dịch: Chúng tôi ngồi dưới bóng mát của một cây liễu lớn để tránh cái nóng mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=willow&lang=en-GB&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=willow&lang=en-US&ipa=%2F%CB%88w%C9%AAl.o%CA%8A%2F"},{"id":"lv_2_147","topic":"Tourism and Visits","word":"wooded","pos":"(adj)","ipa":"/ˈwʊd.ɪd/","defVi":"rậm rạp cây cối, có nhiều cây cối","defEn":"covered with growing trees or woods","examples":["The cabin was hidden deep in a dense, [wooded] valley. (=Dịch: Ngôi nhà gỗ nhỏ nằm ẩn sâu trong một thung lũng rậm rạp nhiều cây cối.)","Hikers followed a narrow trail that led up the [wooded] hillside. (=Dịch: Những người đi bộ đường dài đi theo một con đường mòn hẹp dẫn lên sườn đồi phủ đầy cây cối.)","Wildlife thrives in the vast [wooded] areas surrounding the mountain range. (=Dịch: Động vật hoang dã phát triển mạnh mẽ tại các khu vực nhiều cây cối rộng lớn bao quanh dãy núi.)"],"ukAudio":"/ai_services/tts3/?q=wooded&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=wooded&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F"},{"id":"lv_2_148","topic":"Tourism and Visits","word":"woodland","pos":"(n)","ipa":"/ˈwʊd.lənd/","defVi":"vùng đất rừng, vùng rừng cây","defEn":"land covered with trees, usually smaller in extent than a forest","examples":["A pleasant trail winds through the ancient [woodland]. (=Dịch: Một con đường mòn êm đềm uốn lượn qua khu rừng cổ thụ.)","Conservationists work tirelessly to preserve the native [woodland] habitat. (=Dịch: Các nhà bảo tồn làm việc không biết mệt mỏi để bảo vệ môi trường sống của vùng rừng cây bản địa.)","Deer and wild foxes often seek shelter in the nearby [woodland]. (=Dịch: Hươu và cáo hoang thường tìm nơi trú ẩn trong khu rừng gần đó.)"],"ukAudio":"/ai_services/tts3/?q=woodland&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=woodland&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.l%C9%99nd%2F"},{"id":"lv_2_149","topic":"Tourism and Visits","word":"yard","pos":"(n)","ipa":"/ˈjɑːrd/","defVi":"sân, bãi đất","defEn":"an area of land adjacent to a building, often grassy and enclosed","examples":["The children spent the afternoon playing soccer in the front [yard]. (=Dịch: Lũ trẻ đã dành cả buổi chiều để chơi bóng đá ở sân trước.)","She planted colorful flowers and fresh herbs in her back [yard]. (=Dịch: Cô ấy trồng những bông hoa rực rỡ sắc màu và các loại rau thơm tươi tốt ở sân sau.)","A tall wooden fence surrounds the entire [yard] for privacy. (=Dịch: Một hàng rào gỗ cao bao quanh toàn bộ sân để đảm bảo sự riêng tư.)"],"ukAudio":"/ai_services/tts3/?q=yard&lang=en-GB&ipa=%2F%CB%88j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=yard&lang=en-US&ipa=%2F%CB%88j%C9%91%CB%90rd%2F"},{"id":"lv_2_150","topic":"Tourism and Visits","word":"zoo","pos":"(n)","ipa":"/zu/","defVi":"sở thú, vườn bách thú","defEn":"a place where wild animals are kept in enclosures for public display, conservation, and study","examples":["The children were excited to visit the city [zoo] to see the pandas. (=Dịch: Những đứa trẻ rất hào hứng khi đến thăm sở thú thành phố để xem gấu trúc.)","Modern [zoos] play a vital role in the conservation of endangered species. (=Dịch: Các sở thú hiện đại đóng một vai trò quan trọng trong việc bảo tồn các loài có nguy cơ tuyệt chủng.)","Many people argue that keeping wild animals in a [zoo] limits their natural behavior. (=Dịch: Nhiều người cho rằng việc nuôi nhốt động vật hoang dã trong sở thú làm hạn chế tập tính tự nhiên của chúng.)"],"ukAudio":"/ai_services/tts3/?q=zoo&lang=en-GB&ipa=%2Fzu%2F","usAudio":"/ai_services/tts3/?q=zoo&lang=en-US&ipa=%2Fzu%2F"}]},"rawTopic":"Tourism and Visits"},{"id":"listening_u5_4","title":"Chủ đề 4/10: Urban Planning and Infrastructure Construction","actTitle":"Từ vựng chủ đề: Urban Planning and Infrastructure Construction (119 từ)","problem":{"pType":"topic_flashcards","topic":"Urban Planning and Infrastructure Construction","count":119,"words":[{"id":"lv_3_0","topic":"Urban Planning and Infrastructure Construction","word":"acoustic","pos":"(adj)","ipa":"/əˈkuː.stɪk/","defVi":"(thuộc) âm học, cách âm, âm thanh mộc","defEn":"relating to sound or the sense of hearing; designed to control sound","examples":["The concert hall was praised for its excellent [acoustic] qualities. (=Dịch: Phòng hòa nhạc được ca ngợi vì chất lượng âm học tuyệt vời.)","He prefers playing an [acoustic] guitar rather than an electric one. (=Dịch: Anh ấy thích chơi đàn ghi-ta mộc hơn là ghi-ta điện.)","They installed special [acoustic] panels on the walls to block outside noise. (=Dịch: Họ đã lắp đặt các tấm cách âm đặc biệt trên tường để ngăn tiếng ồn bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=acoustic&lang=en-GB&ipa=%2F%C9%99%CB%88ku%CB%90.st%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=acoustic&lang=en-US&ipa=%2F%C9%99%CB%88ku%CB%90.st%C9%AAk%2F"},{"id":"lv_3_1","topic":"Urban Planning and Infrastructure Construction","word":"agenda","pos":"(n)","ipa":"/əˈdʒen.də/","defVi":"chương trình nghị sự, lịch trình làm việc","defEn":"a list of matters or topics to be discussed at a meeting","examples":["Environmental protection is top on the committee's [agenda]. (=Dịch: Bảo vệ môi trường là ưu tiên hàng đầu trong chương trình nghị sự của ủy ban.)","We have several important points on our [agenda] today. (=Dịch: Chúng ta có một vài nội dung quan trọng trong chương trình nghị sự hôm nay.)","What is the next item on the meeting [agenda]? (=Dịch: Mục tiếp theo trong chương trình nghị sự của cuộc họp là gì?)"],"ukAudio":"/ai_services/tts3/?q=agenda&lang=en-GB&ipa=%2F%C9%99%CB%88d%CA%92en.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=agenda&lang=en-US&ipa=%2F%C9%99%CB%88d%CA%92en.d%C9%99%2F"},{"id":"lv_3_2","topic":"Urban Planning and Infrastructure Construction","word":"agreement","pos":"(n)","ipa":"/əˈɡriː.mənt/","defVi":"sự đồng ý, thỏa thuận, hợp đồng","defEn":"a decision or arrangement that is shared and accepted by two or more people or groups","examples":["Both companies finally signed a trade [agreement] yesterday. (=Dịch: Cả hai công ty cuối cùng đã ký một thỏa thuận thương mại vào ngày hôm qua.)","They reached an [agreement] on how to divide the project tasks. (=Dịch: Họ đã đạt được thỏa thuận về cách phân chia các nhiệm vụ trong dự án.)","We are all in [agreement] that further research is required. (=Dịch: Tất cả chúng tôi đều đồng tình rằng cần phải nghiên cứu thêm.)"],"ukAudio":"/ai_services/tts3/?q=agreement&lang=en-GB&ipa=%2F%C9%99%CB%88%C9%A1ri%CB%90.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=agreement&lang=en-US&ipa=%2F%C9%99%CB%88%C9%A1ri%CB%90.m%C9%99nt%2F"},{"id":"lv_3_3","topic":"Urban Planning and Infrastructure Construction","word":"asia","pos":"(n)","ipa":"/ˈeɪ.ʒə/","defVi":"Châu Á","defEn":"the largest continent in the world, located mainly in the eastern and northern hemispheres","examples":["Many fast-growing economies are located in [Asia]. (=Dịch: Nhiều nền kinh tế tăng trưởng nhanh nằm ở châu Á.)","He spent two years traveling across Southeast [Asia]. (=Dịch: Anh ấy đã dành hai năm đi du lịch khắp Đông Nam Á.)","The cultural diversity in [Asia] attracts millions of tourists each year. (=Dịch: Sự đa dạng văn hóa ở châu Á thu hút hàng triệu khách du lịch mỗi năm.)"],"ukAudio":"/ai_services/tts3/?q=asia&lang=en-GB&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99%2F","usAudio":"/ai_services/tts3/?q=asia&lang=en-US&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99%2F"},{"id":"lv_3_4","topic":"Urban Planning and Infrastructure Construction","word":"auditorium","pos":"(n)","ipa":"/ˌɑː.dəˈtɔːr.i.əm/","defVi":"hội trường, thính phòng","defEn":"a large room or building used for public gatherings, speeches, or stage performances","examples":["The graduation ceremony will take place in the school [auditorium]. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại hội trường của trường.)","Hundreds of spectators gathered in the [auditorium] for the concert. (=Dịch: Hàng trăm khán giả đã tập trung tại khán phòng để tham dự buổi hòa nhạc.)","The university renovated its main [auditorium] to improve acoustics. (=Dịch: Trường đại học đã cải tạo hội trường chính để cải thiện chất lượng âm học.)"],"ukAudio":"/ai_services/tts3/?q=auditorium&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=auditorium&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.d%C9%99%CB%88t%C9%94%CB%90r.i.%C9%99m%2F"},{"id":"lv_3_5","topic":"Urban Planning and Infrastructure Construction","word":"barge","pos":"(n)","ipa":"/bɑːrdʒ/","defVi":"sà lan, thuyền đáy bằng chở hàng","defEn":"a large flat-bottomed boat used for carrying heavy freight on canals and rivers","examples":["A heavy [barge] slowly transported coal down the river. (=Dịch: Một chiếc sà lan nặng nề từ từ chở than xuôi dòng sông.)","They converted an old canal [barge] into a floating cafe. (=Dịch: Họ đã cải tạo một chiếc sà lan cũ trên kênh đào thành một quán cà phê nổi.)","The cargo [barge] was loaded with building materials for the project. (=Dịch: Chiếc sà lan chở hàng đã được chất đầy vật liệu xây dựng cho dự án.)"],"ukAudio":"/ai_services/tts3/?q=barge&lang=en-GB&ipa=%2Fb%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=barge&lang=en-US&ipa=%2Fb%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_3_6","topic":"Urban Planning and Infrastructure Construction","word":"billion","pos":"(n)","ipa":"/ˈbɪl.jən/","defVi":"tỷ (1.000.000.000)","defEn":"the number 1,000,000,000 (one thousand million)","examples":["The company invested over one [billion] dollars in renewable energy. (=Dịch: Công ty đã đầu tư hơn một tỷ đô la vào năng lượng tái tạo.)","The world's population has now surpassed eight [billion] people. (=Dịch: Dân số thế giới hiện đã vượt qua mức tám tỷ người.)","Scientists estimate that the galaxy contains [billions] of stars. (=Dịch: Các nhà khoa học ước tính rằng thiên hà chứa hàng tỷ ngôi sao.)"],"ukAudio":"/ai_services/tts3/?q=billion&lang=en-GB&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=billion&lang=en-US&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F"},{"id":"lv_3_7","topic":"Urban Planning and Infrastructure Construction","word":"briefly","pos":"(adv)","ipa":"/ˈbriːf.li/","defVi":"ngắn gọn, thoáng qua, trong thời gian ngắn","defEn":"for a short time; using only a few words","examples":["The director spoke [briefly] about the future goals of the organization. (=Dịch: Giám đốc đã nói ngắn gọn về các mục tiêu tương lai của tổ chức.)","They stopped [briefly] in Paris before continuing their journey to Rome. (=Dịch: Họ đã dừng lại một lát ở Paris trước khi tiếp tục hành trình đến Rome.)","Please explain [briefly] why you are suitable for this position. (=Dịch: Xin vui lòng giải thích ngắn gọn lý do tại sao bạn phù hợp với vị trí này.)"],"ukAudio":"/ai_services/tts3/?q=briefly&lang=en-GB&ipa=%2F%CB%88bri%CB%90f.li%2F","usAudio":"/ai_services/tts3/?q=briefly&lang=en-US&ipa=%2F%CB%88bri%CB%90f.li%2F"},{"id":"lv_3_8","topic":"Urban Planning and Infrastructure Construction","word":"canal","pos":"(n)","ipa":"/kəˈnæl/","defVi":"kênh, kênh đào (nhân tạo)","defEn":"an artificial waterway built for boats to travel along or for irrigation","examples":["The Panama [Canal] is a vital route for international maritime trade. (=Dịch: Kênh đào Panama là tuyến đường huyết mạch cho thương mại hàng hải quốc tế.)","Tourists enjoy taking boat trips along the city's historic [canals]. (=Dịch: Khách du lịch thích đi thuyền dọc theo các con kênh lịch sử của thành phố.)","The farmers built an irrigation [canal] to supply water to their fields. (=Dịch: Các nông dân đã xây dựng một kênh thủy lợi để cung cấp nước cho đồng ruộng của họ.)"],"ukAudio":"/ai_services/tts3/?q=canal&lang=en-GB&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=canal&lang=en-US&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_3_9","topic":"Urban Planning and Infrastructure Construction","word":"canteen","pos":"(n)","ipa":"/kænˈtiːn/","defVi":"căng tin, nhà ăn tập thể","defEn":"a place in a school, office, or factory where meals are served to people","examples":["Students usually gather in the school [canteen] during lunch break. (=Dịch: Học sinh thường tụ tập ở căng tin trường học trong giờ nghỉ trưa.)","The factory [canteen] provides free hot meals for all workers. (=Dịch: Căng tin của nhà máy cung cấp các bữa ăn nóng sốt miễn phí cho tất cả công nhân.)","We bought sandwiches and drinks from the office [canteen]. (=Dịch: Chúng tôi đã mua bánh mì kẹp và đồ uống từ căng tin văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=canteen&lang=en-GB&ipa=%2Fk%C3%A6n%CB%88ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=canteen&lang=en-US&ipa=%2Fk%C3%A6n%CB%88ti%CB%90n%2F"},{"id":"lv_3_10","topic":"Urban Planning and Infrastructure Construction","word":"capacity","pos":"(n)","ipa":"/kəˈpæs.ə.t̬i/","defVi":"sức chứa, dung tích, năng lực","defEn":"the total amount that something can contain or produce","examples":["The new stadium has a seating [capacity] of over fifty thousand fans. (=Dịch: Sân vận động mới có sức chứa hơn năm mươi nghìn người hâm mộ.)","The factory is currently operating at full [capacity]. (=Dịch: Nhà máy hiện đang hoạt động hết công suất.)","She has an extraordinary [capacity] for remembering names and faces. (=Dịch: Cô ấy có một khả năng phi thường trong việc ghi nhớ tên và khuôn mặt.)"],"ukAudio":"/ai_services/tts3/?q=capacity&lang=en-GB&ipa=%2Fk%C9%99%CB%88p%C3%A6s.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=capacity&lang=en-US&ipa=%2Fk%C9%99%CB%88p%C3%A6s.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_11","topic":"Urban Planning and Infrastructure Construction","word":"channel","pos":"(n)","ipa":"/ˈtʃæn.əl/","defVi":"kênh truyền hình, phát thanh hoặc kênh thông tin/phân phối","defEn":"a television or radio station, or a method or system used for communication or distribution","examples":["He switched the [channel] to watch the evening news. (=Dịch: Anh ấy đã chuyển kênh để xem bản tin thời sự buổi tối.)","Social media has become an effective marketing [channel] for small businesses. (=Dịch: Mạng xã hội đã trở thành một kênh tiếp thị hiệu quả cho các doanh nghiệp nhỏ.)","The complaint should be submitted through the official [channel]. (=Dịch: Đơn khiếu nại nên được gửi thông qua kênh chính thức.)"],"ukAudio":"/ai_services/tts3/?q=channel&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=channel&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6n.%C9%99l%2F"},{"id":"lv_3_12","topic":"Urban Planning and Infrastructure Construction","word":"clinic","pos":"(n)","ipa":"/ˈklɪn.ɪk/","defVi":"phòng khám, trạm y tế","defEn":"a building or part of a hospital where people go for medical treatment or advice","examples":["She went to a local [clinic] to get her blood pressure checked. (=Dịch: Cô ấy đã đến một phòng khám địa phương để kiểm tra huyết áp.)","The dental [clinic] is open six days a week. (=Dịch: Phòng khám nha khoa mở cửa sáu ngày một tuần.)","Voluntary doctors opened a free health [clinic] for low-income families. (=Dịch: Các bác sĩ tình nguyện đã mở một phòng khám sức khỏe miễn phí cho các gia đình có thu nhập thấp.)"],"ukAudio":"/ai_services/tts3/?q=clinic&lang=en-GB&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=clinic&lang=en-US&ipa=%2F%CB%88kl%C9%AAn.%C9%AAk%2F"},{"id":"lv_3_13","topic":"Urban Planning and Infrastructure Construction","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stl/","defVi":"thuộc vùng biển, duyên hải, ven biển","defEn":"located on or near a coast","examples":["Global warming poses a severe threat to many [coastal] cities. (=Dịch: Hiện tượng nóng lên toàn cầu đặt ra mối đe dọa nghiêm trọng đối với nhiều thành phố ven biển.)","They decided to take a scenic drive along the [coastal] road. (=Dịch: Họ quyết định lái xe ngắm cảnh dọc theo con đường ven biển.)","Fishing is the primary source of income for this small [coastal] community. (=Dịch: Đánh bắt cá là nguồn thu nhập chính của cộng đồng ven biển nhỏ bé này.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.stl%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.stl%2F"},{"id":"lv_3_14","topic":"Urban Planning and Infrastructure Construction","word":"collate","pos":"(v)","ipa":"/kəˈleɪt/","defVi":"thu thập và đối chiếu, sắp xếp dữ liệu","defEn":"to collect and arrange information in a careful and logical order","examples":["The team spent weeks to [collate] data from various global surveys. (=Dịch: Nhóm đã dành nhiều tuần để đối chiếu và tổng hợp dữ liệu từ các cuộc khảo sát toàn cầu khác nhau.)","She needs to [collate] all the student reports before the meeting. (=Dịch: Cô ấy cần đối chiếu và sắp xếp tất cả các báo cáo của học sinh trước cuộc họp.)","Software tools make it much easier to [collate] research findings. (=Dịch: Các công cụ phần mềm giúp việc tổng hợp và đối chiếu các kết quả nghiên cứu trở nên dễ dàng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=collate&lang=en-GB&ipa=%2Fk%C9%99%CB%88le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=collate&lang=en-US&ipa=%2Fk%C9%99%CB%88le%C9%AAt%2F"},{"id":"lv_3_15","topic":"Urban Planning and Infrastructure Construction","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"ủy ban; tiền hoa hồng","defEn":"a formal group of people entrusted by a government to do a particular task; an amount of money paid for a sale","examples":["The government set up an independent [commission] to investigate the safety issue. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vấn đề an toàn.)","Sales agents earn a generous [commission] on every property they sell. (=Dịch: Các đại lý bán hàng kiếm được một khoản hoa hồng hậu hĩnh trên mỗi bất động sản mà họ bán được.)","The cultural [commission] approved funding for the new community art project. (=Dịch: Ủy ban văn hóa đã phê duyệt kinh phí cho dự án nghệ thuật cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_3_16","topic":"Urban Planning and Infrastructure Construction","word":"committee","pos":"(n)","ipa":"/kəˈmɪt.i/","defVi":"ủy ban, hội đồng","defEn":"a group of people chosen to represent a larger group or make decisions","examples":["The school formed a [committee] to organize the annual charity event. (=Dịch: Trường học đã thành lập một ủy ban để tổ chức sự kiện từ thiện thường niên.)","She was appointed as the head of the finance [committee]. (=Dịch: Cô ấy đã được bổ nhiệm làm người đứng đầu ủy ban tài chính.)","The government [committee] will submit its report next month. (=Dịch: Ủy ban của chính phủ sẽ đệ trình báo cáo vào tháng tới.)"],"ukAudio":"/ai_services/tts3/?q=committee&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=committee&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt.i%2F"},{"id":"lv_3_17","topic":"Urban Planning and Infrastructure Construction","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"lời phàn nàn, sự khiếu nại","defEn":"a statement that something is unsatisfactory or unacceptable","examples":["The hotel manager received a formal [complaint] about the noisy air conditioner. (=Dịch: Quản lý khách sạn đã nhận được một lời khiếu nại chính thức về chiếc máy điều hòa gây ồn.)","She made a [complaint] to customer service regarding the late delivery. (=Dịch: Cô ấy đã gửi khiếu nại đến bộ phận chăm sóc khách hàng về việc giao hàng chậm trễ.)","The company took steps to resolve the [complaint] as quickly as possible. (=Dịch: Công ty đã thực hiện các biện pháp để giải quyết khiếu nại nhanh nhất có thể.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_3_18","topic":"Urban Planning and Infrastructure Construction","word":"concrete","pos":"(adj)","ipa":"/ˈkɑːn.kriːt/","defVi":"cụ thể, rõ ràng, xác thực","defEn":"based on facts or actual things, rather than thoughts or ideas","examples":["We need [concrete] evidence before we can make any formal accusation. (=Dịch: Chúng ta cần bằng chứng cụ thể trước khi có thể đưa ra bất kỳ lời cáo buộc chính thức nào.)","The manager asked the team for [concrete] proposals to improve sales. (=Dịch: Người quản lý đã yêu cầu toàn đội đưa ra những đề xuất cụ thể để cải thiện doanh số bán hàng.)","The research lacks [concrete] data to support its main hypothesis. (=Dịch: Nghiên cứu còn thiếu dữ liệu cụ thể để chứng minh cho giả thuyết chính của mình.)"],"ukAudio":"/ai_services/tts3/?q=concrete&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F","usAudio":"/ai_services/tts3/?q=concrete&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F"},{"id":"lv_3_19","topic":"Urban Planning and Infrastructure Construction","word":"congestion","pos":"(n)","ipa":"/kənˈdʒes.tʃən/","defVi":"sự tắc nghẽn, sự ùn tắc","defEn":"the state of being extremely crowded or blocked, especially with traffic","examples":["The new bypass road was built to reduce traffic [congestion] in the city center. (=Dịch: Tuyến đường tránh mới được xây dựng nhằm giảm ùn tắc giao thông ở trung tâm thành phố.)","Heavy [congestion] during rush hours often leads to long delays for commuters. (=Dịch: Tình trạng tắc nghẽn nghiêm trọng trong giờ cao điểm thường dẫn đến sự chậm trễ kéo dài cho người đi làm.)","Improving public transport networks is essential to alleviate urban road [congestion]. (=Dịch: Cải thiện mạng lưới giao thông công cộng là điều cần thiết để giảm bớt tình trạng ùn tắc giao thông đường bộ đô thị.)"],"ukAudio":"/ai_services/tts3/?q=congestion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%CA%92es.t%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congestion&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%CA%92es.t%CA%83%C9%99n%2F"},{"id":"lv_3_20","topic":"Urban Planning and Infrastructure Construction","word":"consultation","pos":"(n)","ipa":"/ˌkɑːn.səlˈteɪ.ʃən/","defVi":"sự hội đàm, sự tham vấn, cuộc tư vấn","defEn":"a meeting to discuss something, or the process of discussing something with someone to get advice","examples":["The doctor charges a high fee for a private [consultation]. (=Dịch: Bác sĩ thu phí cao cho một buổi tư vấn riêng.)","The decision was made after thorough [consultation] with local residents. (=Dịch: Quyết định được đưa ra sau khi tham vấn kỹ lưỡng với cư dân địa phương.)","We need to hold a [consultation] with legal experts before signing the contract. (=Dịch: Chúng tôi cần tiến hành tham vấn với các chuyên gia pháp lý trước khi ký hợp đồng.)"],"ukAudio":"/ai_services/tts3/?q=consultation&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90n.s%C9%99l%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consultation&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90n.s%C9%99l%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_21","topic":"Urban Planning and Infrastructure Construction","word":"convert","pos":"(v)","ipa":"/kənˈvɜrt/","defVi":"chuyển đổi, biến đổi","defEn":"to change something from one form, state, or use into another","examples":["The old warehouse was [convert]ed into modern residential apartments. (=Dịch: Nhà kho cũ đã được chuyển đổi thành các căn hộ dân cư hiện đại.)","Solar panels [convert] sunlight directly into usable electrical energy. (=Dịch: Các tấm pin mặt trời chuyển đổi trực tiếp ánh sáng mặt trời thành điện năng có thể sử dụng.)","They plan to [convert] the spare bedroom into a quiet study area. (=Dịch: Họ dự định cải tạo phòng ngủ phụ thành một khu vực học tập yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=convert&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9Crt%2F","usAudio":"/ai_services/tts3/?q=convert&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9Crt%2F"},{"id":"lv_3_22","topic":"Urban Planning and Infrastructure Construction","word":"councillor","pos":"(n)","ipa":"/ˈkaʊn.sə.lɚ/","defVi":"ủy viên hội đồng, nghị viên địa phương","defEn":"an elected member of a local government council","examples":["The local [councillor] promised to address the problem of traffic congestion. (=Dịch: Ủy viên hội đồng địa phương đã hứa sẽ giải quyết vấn đề ùn tắc giao thông.)","Residents met with their city [councillor] to voice concerns about the new development. (=Dịch: Các cư dân đã gặp ủy viên hội đồng thành phố của họ để bày tỏ mối lo ngại về dự án phát triển mới.)","She has served as a parish [councillor] for more than ten years. (=Dịch: Bà ấy đã phục vụ với tư cách là ủy viên hội đồng giáo xứ trong hơn mười năm.)"],"ukAudio":"/ai_services/tts3/?q=councillor&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.s%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=councillor&lang=en-US&ipa=%2F%CB%88ka%CA%8An.s%C9%99.l%C9%9A%2F"},{"id":"lv_3_23","topic":"Urban Planning and Infrastructure Construction","word":"cricket","pos":"(n)","ipa":"/ˈkrɪk.ɪt/","defVi":"môn bóng gậy (cricket)","defEn":"an open-air game played on grass with bats, a ball, and wickets by two teams of eleven players","examples":["He has been playing [cricket] for the local club since he was ten. (=Dịch: Anh ấy đã chơi môn cricket cho câu lạc bộ địa phương từ khi mười tuổi.)","The national team won the international [cricket] tournament. (=Dịch: Đội tuyển quốc gia đã giành chiến thắng tại giải đấu cricket quốc tế.)","Many people in England enjoy watching a match of [cricket] on weekends. (=Dịch: Nhiều người ở Anh thích xem một trận đấu cricket vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=cricket&lang=en-GB&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=cricket&lang=en-US&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F"},{"id":"lv_3_24","topic":"Urban Planning and Infrastructure Construction","word":"critic","pos":"(n)","ipa":"/ˈkrɪt̬.ɪk/","defVi":"nhà phê bình, người chỉ trích","defEn":"a person who expresses opinions or judgments about art, literature, or people's actions","examples":["The movie received rave reviews from almost every film [critic]. (=Dịch: Bộ phim đã nhận được nhiều lời khen ngợi nhiệt liệt từ hầu hết các nhà phê bình điện ảnh.)","He has always been an outspoken [critic] of the current political policy. (=Dịch: Ông ấy luôn là một người thẳng thắn chỉ trích chính sách chính trị hiện tại.)","The food [critic] wrote a detailed evaluation of the new restaurant. (=Dịch: Nhà phê bình ẩm thực đã viết một bài đánh giá chi tiết về nhà hàng mới.)"],"ukAudio":"/ai_services/tts3/?q=critic&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=critic&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AAk%2F"},{"id":"lv_3_25","topic":"Urban Planning and Infrastructure Construction","word":"croft","pos":"(n)","ipa":"/krɑːft/","defVi":"trang trại nhỏ (thường ở vùng nông thôn Scotland)","defEn":"a very small farm, especially one in Scotland, typically with a rented house and land","examples":["His grandparents lived on a remote [croft] in the Scottish Highlands. (=Dịch: Ông bà của anh ấy sống tại một trang trại nhỏ hẻo lánh ở vùng Cao nguyên Scotland.)","Traditional life on a [croft] involves raising a few sheep and growing vegetables. (=Dịch: Cuộc sống truyền thống tại một trang trại nhỏ bao gồm việc nuôi vài con cừu và trồng rau củ.)","The government provided grants to modernize the old [croft]. (=Dịch: Chính phủ đã cung cấp các khoản trợ cấp để hiện đại hóa trang trại nhỏ cũ kỹ.)"],"ukAudio":"/ai_services/tts3/?q=croft&lang=en-GB&ipa=%2Fkr%C9%91%CB%90ft%2F","usAudio":"/ai_services/tts3/?q=croft&lang=en-US&ipa=%2Fkr%C9%91%CB%90ft%2F"},{"id":"lv_3_26","topic":"Urban Planning and Infrastructure Construction","word":"curve","pos":"(n)","ipa":"/kɝːv/","defVi":"đường cong, khúc cua","defEn":"a line or surface that bends continuously without forming angles","examples":["Drivers must slow down before entering the sharp [curve] in the road. (=Dịch: Người lái xe phải giảm tốc độ trước khi đi vào khúc cua gấp trên đường.)","The modern building is famous for the sweeping [curve] of its glass roof. (=Dịch: Tòa nhà hiện đại này nổi tiếng với đường cong uốn lượn mềm mại của mái kính.)","The graph shows an upward [curve] in renewable energy production over the decade. (=Dịch: Biểu đồ cho thấy một đường cong đi lên về sản lượng năng lượng tái tạo trong suốt thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=curve&lang=en-GB&ipa=%2Fk%C9%9D%CB%90v%2F","usAudio":"/ai_services/tts3/?q=curve&lang=en-US&ipa=%2Fk%C9%9D%CB%90v%2F"},{"id":"lv_3_27","topic":"Urban Planning and Infrastructure Construction","word":"damaging","pos":"(adj)","ipa":"/ˈdæm.ɪ.dʒɪŋ/","defVi":"gây tổn hại, có hại, tai hại","defEn":"causing harm, injury, or impairment","examples":["Smoking cigarettes has a extremely [damaging] effect on your lungs. (=Dịch: Hút thuốc lá gây ra tác hại cực kỳ nghiêm trọng đối với phổi của bạn.)","The scandal had a very [damaging] impact on the politician's career. (=Dịch: Vụ bê bối đã gây ra ảnh hưởng vô cùng tai hại đến sự nghiệp của vị chính trị gia.)","Air pollution produces [damaging] consequences for the ecosystem. (=Dịch: Ô nhiễm không khí tạo ra những hậu quả gây hại cho hệ sinh thái.)"],"ukAudio":"/ai_services/tts3/?q=damaging&lang=en-GB&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=damaging&lang=en-US&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_3_28","topic":"Urban Planning and Infrastructure Construction","word":"decibel","pos":"(n)","ipa":"/ˈdes.ə.bəl/","defVi":"đề-xi-ben (đơn vị đo độ lớn âm thanh)","defEn":"a unit used to measure the intensity or loudness of sound","examples":["The sound of normal human conversation is usually around sixty [decibel]s. (=Dịch: Âm thanh của một cuộc trò chuyện bình thường của con người thường vào khoảng sáu mươi đề-xi-ben.)","City regulations prohibit construction noise exceeding eighty [decibel]s at night. (=Dịch: Các quy định của thành phố cấm tiếng ồn xây dựng vượt quá tám mươi đề-xi-ben vào ban đêm.)","Exposure to sounds over eighty-five [decibel]s for prolonged periods can cause hearing loss. (=Dịch: Việc tiếp xúc với âm thanh trên tám mươi lăm đề-xi-ben trong thời gian dài có thể gây suy giảm thính lực.)"],"ukAudio":"/ai_services/tts3/?q=decibel&lang=en-GB&ipa=%2F%CB%88des.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=decibel&lang=en-US&ipa=%2F%CB%88des.%C9%99.b%C9%99l%2F"},{"id":"lv_3_29","topic":"Urban Planning and Infrastructure Construction","word":"declare","pos":"(v)","ipa":"/dɪˈkler/","defVi":"tuyên bố, công bố, khai báo","defEn":"to announce something clearly, firmly, or officially","examples":["The government decided to [declare] a state of emergency. (=Dịch: Chính phủ đã quyết định ban bố tình trạng khẩn cấp.)","You must [declare] any taxable goods at the customs counter. (=Dịch: Bạn phải khai báo bất kỳ hàng hóa chịu thuế nào tại quầy hải quan.)","The referee will [declare] the official winner after the match. (=Dịch: Trọng tài sẽ tuyên bố người chiến thắng chính thức sau trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=declare&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kler%2F","usAudio":"/ai_services/tts3/?q=declare&lang=en-US&ipa=%2Fd%C9%AA%CB%88kler%2F"},{"id":"lv_3_30","topic":"Urban Planning and Infrastructure Construction","word":"discharge","pos":"(v)","ipa":"/dɪsˈtʃɑːrdʒ/","defVi":"xả ra, thải ra, phóng thích","defEn":"to release or send out a liquid, gas, or other substance","examples":["Factories should not [discharge] toxic chemicals into the river. (=Dịch: Các nhà máy không được xả hóa chất độc hại ra sông.)","The patient was well enough to be [discharge]d from the hospital today. (=Dịch: Bệnh nhân đã đủ khỏe để được xuất viện vào ngày hôm nay.)","The volcano continued to [discharge] huge clouds of ash and smoke. (=Dịch: Ngọn núi lửa tiếp tục phun ra những đám mây tro bụi và khói khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=discharge&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88t%CA%83%C9%91%CB%90rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=discharge&lang=en-US&ipa=%2Fd%C9%AAs%CB%88t%CA%83%C9%91%CB%90rd%CA%92%2F"},{"id":"lv_3_31","topic":"Urban Planning and Infrastructure Construction","word":"dispose","pos":"(v)","ipa":"/dɪˈspoʊz/","defVi":"xử lý, vứt bỏ","defEn":"to get rid of something that is no longer wanted or needed","examples":["Factories must properly [dispose] of toxic waste to prevent river pollution. (=Dịch: Các nhà máy phải xử lý chất thải độc hại đúng cách để ngăn ngừa ô nhiễm sông ngòi.)","Please [dispose] of your litter in the bins provided. (=Dịch: Vui lòng bỏ rác của bạn vào các thùng rác được cung cấp sẵn.)","The company is looking for a safe way to [dispose] of old electronic equipment. (=Dịch: Công ty đang tìm kiếm một phương pháp an toàn để thải bỏ các thiết bị điện tử cũ.)"],"ukAudio":"/ai_services/tts3/?q=dispose&lang=en-GB&ipa=%2Fd%C9%AA%CB%88spo%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=dispose&lang=en-US&ipa=%2Fd%C9%AA%CB%88spo%CA%8Az%2F"},{"id":"lv_3_32","topic":"Urban Planning and Infrastructure Construction","word":"disuse","pos":"(n)","ipa":"/dɪsˈjuːs/","defVi":"sự không còn được sử dụng, tình trạng bỏ hoang/ngưng dùng","defEn":"the state of no longer being used","examples":["The old railway track has fallen into [disuse] over the past decade. (=Dịch: Tuyến đường sắt cũ đã bị bỏ hoang không còn sử dụng trong suốt một thập kỷ qua.)","Many traditional crafts are in danger of falling into [disuse]. (=Dịch: Nhiều nghề thủ công truyền thống đang đứng trước nguy cơ bị mai một.)","The factory machinery was sold after years of [disuse]. (=Dịch: Máy móc trong nhà máy đã được bán sau nhiều năm không sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=disuse&lang=en-GB&ipa=%2Fd%C9%AAs%CB%88ju%CB%90s%2F","usAudio":"/ai_services/tts3/?q=disuse&lang=en-US&ipa=%2Fd%C9%AAs%CB%88ju%CB%90s%2F"},{"id":"lv_3_33","topic":"Urban Planning and Infrastructure Construction","word":"drainage","pos":"(n)","ipa":"/ˈdreɪ.nɪdʒ/","defVi":"hệ thống thoát nước, sự thoát nước","defEn":"the system or process by which water or other liquids are drained from a place","examples":["Poor [drainage] in the city center often leads to severe flooding during heavy rain. (=Dịch: Hệ thống thoát nước kém ở trung tâm thành phố thường dẫn đến ngập lụt nghiêm trọng khi trời mưa to.)","The farmer improved the [drainage] of his fields to prevent crop damage. (=Dịch: Người nông dân đã cải thiện hệ thống thoát nước cho các cánh đồng của mình để ngăn ngừa thiệt hại cho cây trồng.)","The local council invested millions of dollars in modernizing the town's [drainage] network. (=Dịch: Hội đồng địa phương đã đầu tư hàng triệu đô la vào việc hiện đại hóa mạng lưới thoát nước của thị trấn.)"],"ukAudio":"/ai_services/tts3/?q=drainage&lang=en-GB&ipa=%2F%CB%88dre%C9%AA.n%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=drainage&lang=en-US&ipa=%2F%CB%88dre%C9%AA.n%C9%AAd%CA%92%2F"},{"id":"lv_3_34","topic":"Urban Planning and Infrastructure Construction","word":"dweller","pos":"(n)","ipa":"/ˈdwel.ər/","defVi":"cư dân, người cư ngụ","defEn":"a person or animal that lives in a particular place","examples":["An urban [dweller] often experiences higher levels of noise and pollution than someone living in the countryside. (=Dịch: Một cư dân đô thị thường phải chịu mức độ tiếng ồn và ô nhiễm cao hơn so với người sống ở vùng nông thôn.)","The traditional cave [dweller]s adapted remarkably well to the harsh desert environment. (=Dịch: Những người sống trong hang động truyền thống đã thích nghi rất tốt với môi trường sa mạc khắc nghiệt.)","Local authorities are consulting city [dweller]s about the new green park project. (=Dịch: Chính quyền địa phương đang tham vấn ý kiến của cư dân thành phố về dự án công viên xanh mới.)"],"ukAudio":"/ai_services/tts3/?q=dweller&lang=en-GB&ipa=%2F%CB%88dwel.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=dweller&lang=en-US&ipa=%2F%CB%88dwel.%C9%99r%2F"},{"id":"lv_3_35","topic":"Urban Planning and Infrastructure Construction","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, tạo điều kiện, giúp có thể","defEn":"to make it possible for someone to do something or for something to happen","examples":["Modern technology will [enable] remote workers to collaborate more effectively across borders. (=Dịch: Công nghệ hiện đại sẽ cho phép những người làm việc từ xa cộng tác hiệu quả hơn xuyên biên giới.)","The scholarship helped [enable] her to pursue higher education abroad without financial stress. (=Dịch: Học bổng đã giúp cô có điều kiện theo học bậc đại học ở nước ngoài mà không phải chịu áp lực tài chính.)","Regular exercise and a balanced diet [enable] individuals to maintain high energy levels. (=Dịch: Tập thể dục thường xuyên và một chế độ ăn uống cân bằng giúp các cá nhân duy trì mức năng lượng cao.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_3_36","topic":"Urban Planning and Infrastructure Construction","word":"enlarge","pos":"(v)","ipa":"/ɪnˈlɑrdʒ/","defVi":"mở rộng, phóng to","defEn":"to make something bigger or to become bigger","examples":["The city council plans to [enlarge] the local playground. (=Dịch: Hội đồng thành phố có kế hoạch mở rộng sân chơi địa phương.)","Could you please [enlarge] this photograph for the exhibition? (=Dịch: Bạn có thể vui lòng phóng to bức ảnh này cho buổi triển lãm không?)","The company decided to [enlarge] its product range to attract more customers. (=Dịch: Công ty đã quyết định mở rộng danh mục sản phẩm để thu hút thêm nhiều khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=enlarge&lang=en-GB&ipa=%2F%C9%AAn%CB%88l%C9%91rd%CA%92%2F","usAudio":"/ai_services/tts3/?q=enlarge&lang=en-US&ipa=%2F%C9%AAn%CB%88l%C9%91rd%CA%92%2F"},{"id":"lv_3_37","topic":"Urban Planning and Infrastructure Construction","word":"environmentally","pos":"(adv)","ipa":"/ɪnˌvaɪ.rənˈmen.t̬əl.i/","defVi":"về mặt môi trường","defEn":"in a way that relates to the natural world or the environment","examples":["The company is trying to produce more [environmentally] friendly packaging. (=Dịch: Công ty đang cố gắng sản xuất bao bì thân thiện hơn với môi trường.)","Using public transport is [environmentally] better than driving a personal car. (=Dịch: Sử dụng phương tiện giao thông công cộng tốt hơn cho môi trường so với việc lái xe ô tô cá nhân.)","We need to find [environmentally] sustainable ways to generate energy. (=Dịch: Chúng ta cần tìm ra những phương pháp tạo ra năng lượng bền vững về mặt môi trường.)"],"ukAudio":"/ai_services/tts3/?q=environmentally&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cva%C9%AA.r%C9%99n%CB%88men.t%CC%AC%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=environmentally&lang=en-US&ipa=%2F%C9%AAn%CB%8Cva%C9%AA.r%C9%99n%CB%88men.t%CC%AC%C9%99l.i%2F"},{"id":"lv_3_38","topic":"Urban Planning and Infrastructure Construction","word":"essentially","pos":"(adv)","ipa":"/ɪˈsen.ʃəl.i/","defVi":"về cơ bản, cốt yếu","defEn":"used when stating the most basic and important facts about something","examples":["The two proposals are [essentially] the same in terms of cost. (=Dịch: Hai đề xuất về cơ bản là giống nhau về mặt chi phí.)","What he said was [essentially] true, despite a few minor mistakes. (=Dịch: Những gì anh ấy nói về cơ bản là đúng, dù có một vài lỗi nhỏ.)","The internet is [essentially] a vast network connecting computers worldwide. (=Dịch: Internet về cơ bản là một mạng lưới rộng lớn kết nối các máy tính trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=essentially&lang=en-GB&ipa=%2F%C9%AA%CB%88sen.%CA%83%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=essentially&lang=en-US&ipa=%2F%C9%AA%CB%88sen.%CA%83%C9%99l.i%2F"},{"id":"lv_3_39","topic":"Urban Planning and Infrastructure Construction","word":"evaluation","pos":"(n)","ipa":"/ɪˌvæl.juˈeɪ.ʃən/","defVi":"sự đánh giá, sự thẩm định","defEn":"the process of judging or calculating the quality, importance, or value of something","examples":["The company conducts a performance [evaluation] for every employee once a year. (=Dịch: Công ty tiến hành đánh giá hiệu suất cho mỗi nhân viên một năm một lần.)","A careful [evaluation] of the risks is necessary before investing. (=Dịch: Việc đánh giá cẩn thận các rủi ro là cần thiết trước khi đầu tư.)","The teacher's final [evaluation] will determine whether students pass the course. (=Dịch: Đánh giá cuối cùng của giáo viên sẽ quyết định xem học sinh có vượt qua khóa học hay không.)"],"ukAudio":"/ai_services/tts3/?q=evaluation&lang=en-GB&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evaluation&lang=en-US&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_40","topic":"Urban Planning and Infrastructure Construction","word":"extend","pos":"(v)","ipa":"/ɪkˈstend/","defVi":"mở rộng, kéo dài","defEn":"to make something larger, longer, or to stretch out","examples":["The school agreed to [extend] the deadline for the final project. (=Dịch: Nhà trường đã đồng ý gia hạn thời hạn cho dự án cuối khóa.)","The railway line will soon [extend] to the neighboring town. (=Dịch: Tuyến đường sắt sẽ sớm được mở rộng đến thị trấn lân cận.)","They decided to [extend] their kitchen to create more dining space. (=Dịch: Họ quyết định mở rộng phòng bếp để có thêm không gian ăn uống.)"],"ukAudio":"/ai_services/tts3/?q=extend&lang=en-GB&ipa=%2F%C9%AAk%CB%88stend%2F","usAudio":"/ai_services/tts3/?q=extend&lang=en-US&ipa=%2F%C9%AAk%CB%88stend%2F"},{"id":"lv_3_41","topic":"Urban Planning and Infrastructure Construction","word":"faculty","pos":"(n)","ipa":"/ˈfæk.əl.ti/","defVi":"giảng viên (toàn thể cán bộ giảng dạy); khoa (đại học); khả năng","defEn":"all the teachers or academic staff in a university or college; an inherent mental or physical ability","examples":["She joined the university's law [faculty] as a senior lecturer. (=Dịch: Cô ấy đã gia nhập khoa luật của trường đại học với tư cách là giảng viên cao cấp.)","The [faculty] voted unanimously in favor of the new curriculum. (=Dịch: Toàn thể giảng viên đã bỏ phiếu nhất trí ủng hộ chương trình giảng dạy mới.)","Even in his nineties, he maintained full use of his mental [faculty] skills. (=Dịch: Ngay cả khi đã ngoài chín mươi tuổi, ông ấy vẫn duy trì trọn vẹn năng lực trí tuệ của mình.)"],"ukAudio":"/ai_services/tts3/?q=faculty&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.%C9%99l.ti%2F","usAudio":"/ai_services/tts3/?q=faculty&lang=en-US&ipa=%2F%CB%88f%C3%A6k.%C9%99l.ti%2F"},{"id":"lv_3_42","topic":"Urban Planning and Infrastructure Construction","word":"fare","pos":"(n)","ipa":"/fer/","defVi":"tiền vé, tiền cước (xe buýt, taxi, máy bay)","defEn":"the money that you pay to travel by bus, plane, taxi, etc.","examples":["Bus [fare] has increased significantly over the past two years. (=Dịch: Giá vé xe buýt đã tăng đáng kể trong hai năm qua.)","Children under five can travel at half [fare]. (=Dịch: Trẻ em dưới năm tuổi có thể đi lại với giá nửa vé.)","She did not have enough cash to pay the taxi [fare]. (=Dịch: Cô ấy không có đủ tiền mặt để trả tiền cước taxi.)"],"ukAudio":"/ai_services/tts3/?q=fare&lang=en-GB&ipa=%2Ffer%2F","usAudio":"/ai_services/tts3/?q=fare&lang=en-US&ipa=%2Ffer%2F"},{"id":"lv_3_43","topic":"Urban Planning and Infrastructure Construction","word":"flooding","pos":"(n)","ipa":"/ˈflʌd.ɪŋ/","defVi":"tình trạng ngập lụt, lũ lụt","defEn":"an overflow of a large amount of water beyond its normal limits","examples":["Heavy rainfall caused severe [flooding] across the low-lying parts of town. (=Dịch: Mưa lớn đã gây ra ngập lụt nghiêm trọng trên khắp các khu vực trũng thấp của thị trấn.)","The new drainage system was designed to reduce the risk of flash [flooding]. (=Dịch: Hệ thống thoát nước mới được thiết kế để giảm thiểu nguy cơ lũ quét.)","Many homes suffered significant structural damage due to seasonal [flooding]. (=Dịch: Nhiều ngôi nhà đã phải chịu thiệt hại nghiêm trọng về cấu trúc do tình trạng ngập lụt theo mùa.)"],"ukAudio":"/ai_services/tts3/?q=flooding&lang=en-GB&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=flooding&lang=en-US&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F"},{"id":"lv_3_44","topic":"Urban Planning and Infrastructure Construction","word":"fountain","pos":"(n)","ipa":"/ˈfaʊn.tən/","defVi":"đài phun nước","defEn":"a structure that sends water up into the air, often used as a decoration in a park or square","examples":["Tourists often gather around the ancient stone [fountain] in the central square to take photos. (=Dịch: Khách du lịch thường tụ tập quanh đài phun nước bằng đá cổ kính ở quảng trường trung tâm để chụp ảnh.)","The hotel lobby features an impressive water [fountain] that creates a relaxing atmosphere. (=Dịch: Sảnh khách sạn có một đài phun nước ấn tượng tạo nên một bầu không khí thư thái.)","Children enjoyed tossing coins into the park's [fountain] to make wishes. (=Dịch: Trẻ em rất thích ném những đồng xu vào đài phun nước của công viên để ước nguyện.)"],"ukAudio":"/ai_services/tts3/?q=fountain&lang=en-GB&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fountain&lang=en-US&ipa=%2F%CB%88fa%CA%8An.t%C9%99n%2F"},{"id":"lv_3_45","topic":"Urban Planning and Infrastructure Construction","word":"foyer","pos":"(n)","ipa":"/ˈfɔɪ.eɪ/","defVi":"tiền sảnh, sảnh chờ","defEn":"a large open area just inside the entrance of a public building such as a theatre or hotel","examples":["Guests gathered in the hotel [foyer] before the conference began. (=Dịch: Khách mời đã tập trung tại tiền sảnh khách sạn trước khi hội nghị bắt đầu.)","We arranged to meet our friends in the theatre [foyer]. (=Dịch: Chúng tôi hẹn gặp bạn bè ở tiền sảnh nhà hát.)","The modern building features a spacious glass [foyer]. (=Dịch: Tòa nhà hiện đại có một tiền sảnh bằng kính rộng rãi.)"],"ukAudio":"/ai_services/tts3/?q=foyer&lang=en-GB&ipa=%2F%CB%88f%C9%94%C9%AA.e%C9%AA%2F","usAudio":"/ai_services/tts3/?q=foyer&lang=en-US&ipa=%2F%CB%88f%C9%94%C9%AA.e%C9%AA%2F"},{"id":"lv_3_46","topic":"Urban Planning and Infrastructure Construction","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ tiền tệ, nguồn tài chính","defEn":"an amount of money collected or saved for a particular purpose","examples":["The school established a special [fund] to help low-income students. (=Dịch: Nhà trường đã thành lập một quỹ đặc biệt để giúp đỡ các học sinh có thu nhập thấp.)","We do not have enough [funds] to complete the construction project. (=Dịch: Chúng tôi không có đủ kinh phí để hoàn thành dự án xây dựng.)","He decided to invest his savings into an index [fund]. (=Dịch: Anh ấy quyết định đầu tư tiền tiết kiệm của mình vào một quỹ chỉ số.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_3_47","topic":"Urban Planning and Infrastructure Construction","word":"gps","pos":"(n)","ipa":"/ˌdʒiː.piːˈes/","defVi":"hệ thống định vị toàn cầu (GPS)","defEn":"a system that uses radio signals from satellites to show the exact position of something on Earth","examples":["Modern smartphones come equipped with built-in [GPS] technology. (=Dịch: Điện thoại thông minh hiện đại được trang bị công nghệ GPS tích hợp.)","We used our car's [GPS] to find the quickest route to the hotel. (=Dịch: Chúng tôi đã sử dụng định vị GPS trên xe ô tô để tìm tuyến đường nhanh nhất đến khách sạn.)","The delivery driver lost his way because the [GPS] signal was weak in the mountains. (=Dịch: Người tài xế giao hàng đã bị lạc đường vì tín hiệu GPS yếu ở vùng núi.)"],"ukAudio":"/ai_services/tts3/?q=gps&lang=en-GB&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88es%2F","usAudio":"/ai_services/tts3/?q=gps&lang=en-US&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88es%2F"},{"id":"lv_3_48","topic":"Urban Planning and Infrastructure Construction","word":"grand","pos":"(adj)","ipa":"/ɡrænd/","defVi":"hoành tráng, uy nghi, tráng lệ","defEn":"impressive and large or important","examples":["They held the wedding reception in a [grand] ballroom. (=Dịch: Họ đã tổ chức tiệc cưới trong một phòng khiêu vũ nguy nga tráng lệ.)","The architect unveiled a [grand] plan for the city's new waterfront. (=Dịch: Kiến trúc sư đã công bố một kế hoạch quy mô lớn cho khu bờ sông mới của thành phố.)","She had a [grand] view of the mountains from her hotel balcony. (=Dịch: Cô ấy có một tầm nhìn tuyệt đẹp hướng ra những ngọn núi từ ban công khách sạn của mình.)"],"ukAudio":"/ai_services/tts3/?q=grand&lang=en-GB&ipa=%2F%C9%A1r%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=grand&lang=en-US&ipa=%2F%C9%A1r%C3%A6nd%2F"},{"id":"lv_3_49","topic":"Urban Planning and Infrastructure Construction","word":"grateful","pos":"(adj)","ipa":"/ˈɡreɪt.fəl/","defVi":"biết ơn, cảm kích","defEn":"feeling or showing appreciation for kindness or help received","examples":["I am deeply [grateful] for all the support you have given me. (=Dịch: Tôi vô cùng biết ơn tất cả sự hỗ trợ mà bạn đã dành cho tôi.)","She was [grateful] that everyone arrived safely after the storm. (=Dịch: Cô ấy rất biết ơn vì mọi người đều đến nơi an toàn sau cơn bão.)","He sent a [grateful] letter of thanks to the rescue team. (=Dịch: Anh ấy đã gửi một lá thư tri ân đến đội cứu hộ.)"],"ukAudio":"/ai_services/tts3/?q=grateful&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=grateful&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.f%C9%99l%2F"},{"id":"lv_3_50","topic":"Urban Planning and Infrastructure Construction","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay, tờ rơi tài liệu","defEn":"a printed piece of paper containing information, given free to people attending a class, meeting, or event","examples":["The lecturer distributed a two-page [handout] at the beginning of the seminar. (=Dịch: Giảng viên đã phát một tài liệu dài hai trang vào đầu buổi hội thảo.)","Please refer to the [handout] for detailed instructions on the assignment. (=Dịch: Vui lòng tham khảo tài liệu phát tay để biết hướng dẫn chi tiết về bài tập.)","She made copies of the presentation slides to use as [handouts] for the audience. (=Dịch: Cô ấy đã in các slide thuyết trình để làm tài liệu phát cho người tham dự.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_3_51","topic":"Urban Planning and Infrastructure Construction","word":"highway","pos":"(n)","ipa":"/ˈhaɪ.weɪ/","defVi":"xa lộ, đường cao tốc","defEn":"a main public road that connects major towns or cities","examples":["The government is building a new [highway] to reduce travel time between the two major cities. (=Dịch: Chính phủ đang xây dựng một đường cao tốc mới nhằm giảm thời gian di chuyển giữa hai thành phố lớn.)","Heavy traffic was reported on the [highway] due to a minor collision this morning. (=Dịch: Tình trạng giao thông đông đúc đã được ghi nhận trên đường cao tốc do một vụ va chạm nhỏ vào sáng nay.)","Speed limits are strictly enforced along this section of the [highway]. (=Dịch: Giới hạn tốc độ được thực thi nghiêm ngặt dọc theo đoạn đường cao tốc này.)"],"ukAudio":"/ai_services/tts3/?q=highway&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=highway&lang=en-US&ipa=%2F%CB%88ha%C9%AA.we%C9%AA%2F"},{"id":"lv_3_52","topic":"Urban Planning and Infrastructure Construction","word":"housing","pos":"(n)","ipa":"/ˈhaʊ.zɪŋ/","defVi":"nhà ở, nơi cư trú","defEn":"buildings or structures in which people live","examples":["The government is investing heavily in affordable [housing] for low-income families. (=Dịch: Chính phủ đang đầu tư mạnh vào nhà ở vừa túi tiền cho các gia đình có thu nhập thấp.)","A serious shortage of [housing] has driven up rent prices across the capital. (=Dịch: Tình trạng thiếu hụt nhà ở nghiêm trọng đã đẩy giá thuê nhà lên cao trên khắp thủ đô.)","The university provides student [housing] near the main campus. (=Dịch: Trường đại học cung cấp chỗ ở cho sinh viên gần khuôn viên chính.)"],"ukAudio":"/ai_services/tts3/?q=housing&lang=en-GB&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=housing&lang=en-US&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F"},{"id":"lv_3_53","topic":"Urban Planning and Infrastructure Construction","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"cuộc tìm kiếm, sự lùng sục","defEn":"an organized search or pursuit for something or someone","examples":["The police launched an intensive [hunt] for the missing artifacts. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm gắt gao các cổ vật bị mất tích.)","Finding affordable housing has become a difficult [hunt] for young graduates. (=Dịch: Tìm kiếm nhà ở giá cả phải chăng đã trở thành một cuộc săn lùng khó khăn đối với những sinh viên mới tốt nghiệp.)","The company is currently on the [hunt] for a creative marketing manager. (=Dịch: Công ty hiện đang ráo riết tìm kiếm một trưởng phòng tiếp thị sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_3_54","topic":"Urban Planning and Infrastructure Construction","word":"impression","pos":"(n)","ipa":"/ɪmˈpreʃ.ən/","defVi":"ấn tượng, cảm giác","defEn":"an idea, feeling, or opinion about someone or something formed without much thought or on little evidence","examples":["Dressing professionally helps you make a positive first [impression] at an interview. (=Dịch: Ăn mặc chuyên nghiệp giúp bạn tạo được ấn tượng đầu tiên tích cực tại buổi phỏng vấn.)","Her performance left a lasting [impression] on the judges. (=Dịch: Màn trình diễn của cô ấy đã để lại ấn tượng sâu đậm trong lòng ban giám khảo.)","I got the [impression] that he was not really interested in the project. (=Dịch: Tôi có cảm tưởng rằng anh ấy không thực sự hứng thú với dự án.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pre%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pre%CA%83.%C9%99n%2F"},{"id":"lv_3_55","topic":"Urban Planning and Infrastructure Construction","word":"inhabitant","pos":"(n)","ipa":"/ɪnˈhæb.ə.tənt/","defVi":"cư dân, người cư ngụ","defEn":"a person or animal that lives in a particular place","examples":["The small island has fewer than five thousand [inhabitants]. (=Dịch: Hòn đảo nhỏ này có chưa đến năm nghìn cư dân.)","Local [inhabitants] expressed serious concerns about the new highway project. (=Dịch: Cư dân địa phương đã bày tỏ những mối quan ngại sâu sắc về dự án đường cao tốc mới.)","The ancient cave once provided shelter to prehistoric [inhabitants]. (=Dịch: Hang động cổ xưa từng là nơi trú ẩn của những cư dân thời tiền sử.)"],"ukAudio":"/ai_services/tts3/?q=inhabitant&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=inhabitant&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F"},{"id":"lv_3_56","topic":"Urban Planning and Infrastructure Construction","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, sâu trong đất liền","defEn":"situated in the interior of a country or region, rather than on the coast","examples":["The storm weakened as it moved toward [inland] areas. (=Dịch: Cơn bão đã suy yếu khi di chuyển vào các khu vực sâu trong đất liền.)","They prefer living in [inland] towns rather than crowded coastal cities. (=Dịch: Họ thích sống ở các thị trấn trong đất liền hơn là các thành phố ven biển đông đúc.)","The government is investing heavily in [inland] water transport. (=Dịch: Chính phủ đang đầu tư mạnh mẽ vào giao thông đường thủy nội địa.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_3_57","topic":"Urban Planning and Infrastructure Construction","word":"instal","pos":"(v)","ipa":"/ɪnˈstɔl/","defVi":"lắp đặt, cài đặt","defEn":"to put equipment or software in place so that it is ready for use","examples":["Technicians will [instal] a modern air conditioning unit tomorrow. (=Dịch: Các kỹ thuật viên sẽ lắp đặt một dàn máy điều hòa hiện đại vào ngày mai.)","The local council plans to [instal] more surveillance cameras to enhance public safety. (=Dịch: Hội đồng địa phương dự định lắp đặt thêm các camera giám sát để nâng cao an toàn công cộng.)","You need to [instal] the latest security patch to protect your computer from malware. (=Dịch: Bạn cần cài đặt bản vá bảo mật mới nhất để bảo vệ máy tính khỏi phần mềm độc hại.)"],"ukAudio":"/ai_services/tts3/?q=instal&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%94l%2F","usAudio":"/ai_services/tts3/?q=instal&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%94l%2F"},{"id":"lv_3_58","topic":"Urban Planning and Infrastructure Construction","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba, ngã tư, chỗ giao nhau","defEn":"a place where things, especially roads or railways, meet and cross","examples":["Turn left when you reach the next major highway [junction]. (=Dịch: Hãy rẽ trái khi bạn đến nút giao đường cao tốc lớn tiếp theo.)","Heavy traffic frequently causes delays at this busy road [junction]. (=Dịch: Giao thông đông đúc thường xuyên gây ra tình trạng ùn tắc tại nút giao thông đông đúc này.)","The town developed rapidly around a vital railway [junction]. (=Dịch: Thị trấn đã phát triển nhanh chóng xung quanh một nút giao đường sắt trọng yếu.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_3_59","topic":"Urban Planning and Infrastructure Construction","word":"lane","pos":"(n)","ipa":"/leɪn/","defVi":"làn đường, con hẻm, đường nhỏ","defEn":"a narrow road in the countryside, or a marked strip of road for a single line of vehicles","examples":["The local government created a dedicated bus [lane] to reduce traffic congestion. (=Dịch: Chính quyền địa phương đã tạo một làn đường dành riêng cho xe buýt để giảm ùn tắc giao thông.)","We walked down a quiet country [lane] surrounded by green trees. (=Dịch: Chúng tôi đi dạo trên một con đường quê yên tĩnh rợp bóng cây xanh.)","Stay in your [lane] when driving through the highway tunnel. (=Dịch: Hãy đi đúng làn đường của bạn khi lái xe qua hầm đường cao tốc.)"],"ukAudio":"/ai_services/tts3/?q=lane&lang=en-GB&ipa=%2Fle%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=lane&lang=en-US&ipa=%2Fle%C9%AAn%2F"},{"id":"lv_3_60","topic":"Urban Planning and Infrastructure Construction","word":"layout","pos":"(n)","ipa":"/ˈleɪ.aʊt/","defVi":"bố cục, cách trình bày, sơ đồ mặt bằng","defEn":"the way in which the parts of something are arranged or designed","examples":["The designer improved the page [layout] to make the article easier to read. (=Dịch: Nhà thiết kế đã cải thiện bố cục trang để giúp bài viết dễ đọc hơn.)","We are planning to change the [layout] of our office to create more open space. (=Dịch: Chúng tôi đang lên kế hoạch thay đổi cách bố trí văn phòng để tạo ra nhiều không gian mở hơn.)","The map shows the general [layout] of the university campus. (=Dịch: Bản đồ hiển thị bố cục chung của khuôn viên trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=layout&lang=en-GB&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=layout&lang=en-US&ipa=%2F%CB%88le%C9%AA.a%CA%8At%2F"},{"id":"lv_3_61","topic":"Urban Planning and Infrastructure Construction","word":"magnificent","pos":"(adj)","ipa":"/mæɡˈnɪf.ə.snt/","defVi":"tráng lệ, lộng lẫy, nguy nga","defEn":"extremely beautiful, elaborate, or impressive","examples":["The view from the top of the mountain was [magnificent]. (=Dịch: Khung cảnh nhìn từ đỉnh núi thật tráng lệ.)","She wore a [magnificent] dress to the annual gala. (=Dịch: Cô ấy đã mặc một chiếc váy lộng lẫy đến buổi dạ tiệc thường niên.)","The ancient palace is famous for its [magnificent] architecture. (=Dịch: Cung điện cổ kính này nổi tiếng với kiến trúc tráng lệ.)"],"ukAudio":"/ai_services/tts3/?q=magnificent&lang=en-GB&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.snt%2F","usAudio":"/ai_services/tts3/?q=magnificent&lang=en-US&ipa=%2Fm%C3%A6%C9%A1%CB%88n%C9%AAf.%C9%99.snt%2F"},{"id":"lv_3_62","topic":"Urban Planning and Infrastructure Construction","word":"minority","pos":"(n)","ipa":"/maɪˈnɔːr.ə.t̬i/","defVi":"thiểu số, phần ít; dân tộc thiểu số","defEn":"a smaller part of a group, especially a number that is less than half of the whole","examples":["Only a small [minority] of students disagreed with the new policy. (=Dịch: Chỉ một thiểu số nhỏ học sinh không đồng ý với chính sách mới.)","The government introduced special programs to support ethnic [minority] groups. (=Dịch: Chính phủ đã đưa ra các chương trình đặc biệt để hỗ trợ các nhóm dân tộc thiểu số.)","His opinion was held by only a [minority] in the committee. (=Dịch: Ý kiến của ông ấy chỉ được một số ít người trong ủy ban tán thành.)"],"ukAudio":"/ai_services/tts3/?q=minority&lang=en-GB&ipa=%2Fma%C9%AA%CB%88n%C9%94%CB%90r.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=minority&lang=en-US&ipa=%2Fma%C9%AA%CB%88n%C9%94%CB%90r.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_63","topic":"Urban Planning and Infrastructure Construction","word":"minster","pos":"(n)","ipa":"/ˈmɪn.stɚ/","defVi":"nhà thờ lớn, tu viện giáo đường","defEn":"a large or important church, often historically attached to a monastery","examples":["York [Minster] is renowned for its magnificent stained glass windows and Gothic architecture. (=Dịch: Nhà thờ lớn York Minster nổi tiếng với những ô cửa kính màu tuyệt mỹ và kiến trúc Gothic.)","Thousands of worshippers gathered at the historic [minster] for the special holiday service. (=Dịch: Hàng ngàn tín đồ đã tập trung tại nhà thờ lớn lịch sử để tham dự buổi lễ đặc biệt nhân dịp ngày lễ.)","The ancient stone walls of the [minster] have stood for more than eight centuries. (=Dịch: Những bức tường đá cổ kính của nhà thờ lớn đã đứng vững qua hơn tám thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=minster&lang=en-GB&ipa=%2F%CB%88m%C9%AAn.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=minster&lang=en-US&ipa=%2F%CB%88m%C9%AAn.st%C9%9A%2F"},{"id":"lv_3_64","topic":"Urban Planning and Infrastructure Construction","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tɚ.i/","defVi":"điều bí ẩn, sự huyền bí","defEn":"something that is difficult or impossible to understand or explain","examples":["The exact origin of the ancient monument remains a [mystery]. (=Dịch: Nguồn gốc chính xác của tượng đài cổ xưa này vẫn còn là một điều bí ẩn.)","Detectives are trying to solve the [mystery] behind the missing jewels. (=Dịch: Các thám tử đang cố gắng giải mã bí ẩn đằng sau số trang sức bị mất tích.)","She loves reading [mystery] novels in her spare time. (=Dịch: Cô ấy rất thích đọc tiểu thuyết trinh thám ly kỳ vào thời gian rảnh rỗi.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F"},{"id":"lv_3_65","topic":"Urban Planning and Infrastructure Construction","word":"neighbouring","pos":"(adj)","ipa":"/ˈneɪ.bər.ɪŋ/","defVi":"lân cận, láng giềng","defEn":"located near or next to something","examples":["Many students commute from [neighbouring] towns to attend the university. (=Dịch: Nhiều sinh viên đi lại từ các thị trấn lân cận để theo học tại trường đại học.)","Smoke from the wildfire spread across [neighbouring] countries. (=Dịch: Khói từ trận cháy rừng đã lan sang các quốc gia láng giềng.)","We visited a [neighbouring] village during our trip to the countryside. (=Dịch: Chúng tôi đã đến thăm một ngôi làng lân cận trong chuyến đi về vùng nông thôn.)"],"ukAudio":"/ai_services/tts3/?q=neighbouring&lang=en-GB&ipa=%2F%CB%88ne%C9%AA.b%C9%99r.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=neighbouring&lang=en-US&ipa=%2F%CB%88ne%C9%AA.b%C9%99r.%C9%AA%C5%8B%2F"},{"id":"lv_3_66","topic":"Urban Planning and Infrastructure Construction","word":"opt","pos":"(v)","ipa":"/ɑːpt/","defVi":"lựa chọn, quyết định chọn","defEn":"to make a choice or decision from a range of possibilities","examples":["Many young professionals [opt] to rent apartments rather than buy houses. (=Dịch: Nhiều người trẻ có chuyên môn chọn thuê căn hộ thay vì mua nhà.)","She decided to [opt] for an online course due to her busy schedule. (=Dịch: Cô ấy quyết định chọn một khóa học trực tuyến do lịch trình bận rộn.)","Customers can [opt] out of receiving promotional emails at any time. (=Dịch: Khách hàng có thể từ chối nhận email quảng cáo bất cứ lúc nào.)"],"ukAudio":"/ai_services/tts3/?q=opt&lang=en-GB&ipa=%2F%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=opt&lang=en-US&ipa=%2F%C9%91%CB%90pt%2F"},{"id":"lv_3_67","topic":"Urban Planning and Infrastructure Construction","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians playing different instruments together, usually led by a conductor","examples":["The symphony [orchestra] delivered a mesmerizing performance of Beethoven's Ninth Symphony. (=Dịch: Dàn nhạc giao hưởng đã mang đến một màn trình diễn đầy mê hoặc bản Giao hưởng số 9 của Beethoven.)","She has been playing the violin in a youth [orchestra] since she was ten years old. (=Dịch: Cô ấy đã chơi vĩ cầm trong một dàn nhạc trẻ từ khi mới mười tuổi.)","The conductor guided the [orchestra] through the complex musical passages with remarkable precision. (=Dịch: Nhạc trưởng đã dẫn dắt dàn nhạc vượt qua các đoạn nhạc phức tạp với độ chính xác đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_3_68","topic":"Urban Planning and Infrastructure Construction","word":"outskirts","pos":"(n)","ipa":"/ˈaʊt.skɜːrts/","defVi":"vùng ngoại ô, rìa thành phố","defEn":"the outer parts of a town or city, furthest from the center","examples":["They bought a quiet house on the [outskirts] of the city. (=Dịch: Họ đã mua một ngôi nhà yên tĩnh ở ngoại ô thành phố.)","A new shopping mall is being built on the [outskirts] of town. (=Dịch: Một trung tâm mua sắm mới đang được xây dựng ở vùng ven thị trấn.)","Commuting from the [outskirts] to downtown takes about forty minutes by train. (=Dịch: Đi lại từ vùng ngoại ô vào trung tâm thành phố mất khoảng bốn mươi phút bằng tàu hỏa.)"],"ukAudio":"/ai_services/tts3/?q=outskirts&lang=en-GB&ipa=%2F%CB%88a%CA%8At.sk%C9%9C%CB%90rts%2F","usAudio":"/ai_services/tts3/?q=outskirts&lang=en-US&ipa=%2F%CB%88a%CA%8At.sk%C9%9C%CB%90rts%2F"},{"id":"lv_3_69","topic":"Urban Planning and Infrastructure Construction","word":"overhead","pos":"(adj)","ipa":"/ˌoʊ.vɚˈhed/","defVi":"ở trên cao, trên đầu","defEn":"located, operating, or passing above one's head or high above the ground","examples":["Passengers were requested to stow their carry-on bags in the [overhead] compartments. (=Dịch: Hành khách được yêu cầu cất hành lý xách tay vào các ngăn để đồ phía trên đầu.)","Strong winds caused damage to [overhead] power lines, leaving parts of the neighborhood in darkness. (=Dịch: Gió mạnh đã gây hư hại cho các đường dây điện trên cao, khiến nhiều khu vực trong khu dân cư chìm trong bóng tối.)","The city plans to construct an [overhead] railway to alleviate ground-level traffic congestion. (=Dịch: Thành phố lên kế hoạch xây dựng một tuyến đường sắt trên cao nhằm giảm bớt tình trạng ùn tắc giao thông mặt đất.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%9A%CB%88hed%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%9A%CB%88hed%2F"},{"id":"lv_3_70","topic":"Urban Planning and Infrastructure Construction","word":"pad","pos":"(n)","ipa":"/pæd/","defVi":"miếng đệm, tấm lót","defEn":"a piece of soft or thick material used to protect something or give comfort","examples":["He wore a knee [pad] to prevent injuries while skateboarding. (=Dịch: Cậu ấy đã đeo miếng đệm bảo vệ đầu gối để tránh bị thương khi trượt ván.)","She wrote down the phone number on a small memo [pad]. (=Dịch: Cô ấy đã ghi số điện thoại vào một cuốn sổ ghi chú nhỏ.)","Place a protective [pad] under the hot pot to protect the table. (=Dịch: Hãy đặt một miếng lót bên dưới nồi nóng để bảo vệ mặt bàn.)"],"ukAudio":"/ai_services/tts3/?q=pad&lang=en-GB&ipa=%2Fp%C3%A6d%2F","usAudio":"/ai_services/tts3/?q=pad&lang=en-US&ipa=%2Fp%C3%A6d%2F"},{"id":"lv_3_71","topic":"Urban Planning and Infrastructure Construction","word":"palm","pos":"(n)","ipa":"/pɑːm/","defVi":"cây cọ, cây dừa","defEn":"a tall tropical tree with large leaves at the top and no branches","examples":["We rested under the shade of a tall [palm] tree. (=Dịch: Chúng tôi nghỉ ngơi dưới bóng râm của một cây cọ cao lớn.)","The tropical island is lined with beautiful coconut [palm] trees. (=Dịch: Hòn đảo nhiệt đới rợp bóng những hàng dừa tuyệt đẹp.)","She collected fallen leaves from the [palm] to make a roof. (=Dịch: Cô ấy nhặt những chiếc lá cọ rụng để lợp mái nhà.)"],"ukAudio":"/ai_services/tts3/?q=palm&lang=en-GB&ipa=%2Fp%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=palm&lang=en-US&ipa=%2Fp%C9%91%CB%90m%2F"},{"id":"lv_3_72","topic":"Urban Planning and Infrastructure Construction","word":"panel","pos":"(n)","ipa":"/ˈpæn.əl/","defVi":"ban chuyên gia, hội đồng giám khảo / bảng điều khiển","defEn":"a small group of people chosen to give advice, make decisions, or discuss something","examples":["A [panel] of experts was invited to discuss the impact of climate change. (=Dịch: Một hội đồng chuyên gia đã được mời để thảo luận về tác động của biến đổi khí hậu.)","The interview [panel] asked several challenging questions. (=Dịch: Hội đồng phỏng vấn đã đặt ra một số câu hỏi đầy thử thách.)","He pressed a red button on the control [panel] to stop the machine. (=Dịch: Anh ấy đã nhấn một nút màu đỏ trên bảng điều khiển để dừng máy.)"],"ukAudio":"/ai_services/tts3/?q=panel&lang=en-GB&ipa=%2F%CB%88p%C3%A6n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=panel&lang=en-US&ipa=%2F%CB%88p%C3%A6n.%C9%99l%2F"},{"id":"lv_3_73","topic":"Urban Planning and Infrastructure Construction","word":"parcel","pos":"(n)","ipa":"/ˈpɑːr.səl/","defVi":"bưu kiện, gói hàng","defEn":"an object or collection of objects wrapped in paper, especially so that it can be sent by post","examples":["The delivery driver left a large [parcel] at the front door. (=Dịch: Người giao hàng đã để lại một bưu kiện lớn ở cửa trước.)","She went to the post office to collect an international [parcel]. (=Dịch: Cô ấy đã đến bưu điện để nhận một bưu kiện quốc tế.)","Make sure you wrap the [parcel] securely before sending it. (=Dịch: Hãy chắc chắn rằng bạn gói bưu kiện cẩn thận trước khi gửi.)"],"ukAudio":"/ai_services/tts3/?q=parcel&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=parcel&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.s%C9%99l%2F"},{"id":"lv_3_74","topic":"Urban Planning and Infrastructure Construction","word":"pavement","pos":"(n)","ipa":"/ˈpeɪv.mənt/","defVi":"vỉa hè, lề đường đi bộ","defEn":"a paved path for pedestrians at the side of a road; a sidewalk","examples":["Pedestrians should walk on the [pavement] to stay safe from traffic. (=Dịch: Người đi bộ nên đi trên vỉa hè để giữ an toàn khỏi các phương tiện giao thông.)","The cafe placed several small tables and chairs outside on the [pavement]. (=Dịch: Quán cà phê đã đặt vài bộ bàn ghế nhỏ bên ngoài trên vỉa hè.)","He tripped over an uneven section of the [pavement] and dropped his keys. (=Dịch: Anh ấy vấp phải một đoạn vỉa hè không bằng phẳng và làm rơi chìa khóa.)"],"ukAudio":"/ai_services/tts3/?q=pavement&lang=en-GB&ipa=%2F%CB%88pe%C9%AAv.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=pavement&lang=en-US&ipa=%2F%CB%88pe%C9%AAv.m%C9%99nt%2F"},{"id":"lv_3_75","topic":"Urban Planning and Infrastructure Construction","word":"pedestrian","pos":"(n)","ipa":"/pəˈdɛs.tri.ən/","defVi":"người đi bộ","defEn":"a person who is walking rather than traveling in a vehicle","examples":["Drivers must slow down and yield to any [pedestrian] at the crossing. (=Dịch: Người lái xe phải giảm tốc độ và nhường đường cho bất kỳ người đi bộ nào tại vạch sang đường.)","The city center has been turned into a safe [pedestrian] zone. (=Dịch: Trung tâm thành phố đã được chuyển đổi thành khu phố đi bộ an toàn.)","A [pedestrian] was injured in the traffic accident yesterday. (=Dịch: Một người đi bộ đã bị thương trong vụ tai nạn giao thông ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=pedestrian&lang=en-GB&ipa=%2Fp%C9%99%CB%88d%C9%9Bs.tri.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=pedestrian&lang=en-US&ipa=%2Fp%C9%99%CB%88d%C9%9Bs.tri.%C9%99n%2F"},{"id":"lv_3_76","topic":"Urban Planning and Infrastructure Construction","word":"periodical","pos":"(n)","ipa":"/ˌpɪr.iˈɑː.dɪ.kəl/","defVi":"tạp chí xuất bản định kỳ","defEn":"a magazine or journal that is published at regular intervals, such as weekly or monthly","examples":["The university library subscribes to a wide range of academic [periodicals]. (=Dịch: Thư viện trường đại học đặt mua dài hạn rất nhiều ấn phẩm định kỳ học thuật.)","She found an insightful article about climate change in a scientific [periodical]. (=Dịch: Cô ấy đã tìm thấy một bài viết sâu sắc về biến đổi khí hậu trên một ấn phẩm khoa học định kỳ.)","His research was cited in several leading medical [periodicals]. (=Dịch: Nghiên cứu của ông đã được trích dẫn trên một số tập san y khoa định kỳ hàng đầu.)"],"ukAudio":"/ai_services/tts3/?q=periodical&lang=en-GB&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91%CB%90.d%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=periodical&lang=en-US&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91%CB%90.d%C9%AA.k%C9%99l%2F"},{"id":"lv_3_77","topic":"Urban Planning and Infrastructure Construction","word":"photocopier","pos":"(n)","ipa":"/ˈfoʊ.t̬oʊˌkɑː.pi.ɚ/","defVi":"máy photocopy, máy sao chụp tài liệu","defEn":"a machine that makes photographic copies of documents","examples":["The office [photocopier] ran out of paper right before the meeting. (=Dịch: Máy photocopy của văn phòng đã hết giấy ngay trước cuộc họp.)","She used the [photocopier] to print out thirty copies of the study guide. (=Dịch: Cô ấy đã sử dụng máy photocopy để in ra ba mươi bản tài liệu học tập.)","The technician was called in to fix the jammed [photocopier]. (=Dịch: Kỹ thuật viên đã được gọi đến để sửa chiếc máy photocopy bị kẹt giấy.)"],"ukAudio":"/ai_services/tts3/?q=photocopier&lang=en-GB&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=photocopier&lang=en-US&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi.%C9%9A%2F"},{"id":"lv_3_78","topic":"Urban Planning and Infrastructure Construction","word":"pitch","pos":"(n)","ipa":"/pɪtʃ/","defVi":"sân thể thao; cao độ âm thanh","defEn":"an area of ground marked out for playing a sports game, or the highness or lowness of a sound","examples":["The players ran onto the football [pitch] with high spirits. (=Dịch: Các cầu thủ chạy ra sân bóng đá với tinh thần phấn khởi.)","She has perfect [pitch] and can identify any musical note instantly. (=Dịch: Cô ấy có khả năng cảm âm hoàn hảo và có thể nhận biết bất kỳ nốt nhạc nào ngay lập tức.)","The heavy rain turned the cricket [pitch] into mud. (=Dịch: Cơn mưa lớn đã biến sân criket thành một bãi bùn lầy.)"],"ukAudio":"/ai_services/tts3/?q=pitch&lang=en-GB&ipa=%2Fp%C9%AAt%CA%83%2F","usAudio":"/ai_services/tts3/?q=pitch&lang=en-US&ipa=%2Fp%C9%AAt%CA%83%2F"},{"id":"lv_3_79","topic":"Urban Planning and Infrastructure Construction","word":"planner","pos":"(n)","ipa":"/ˈplæn.ɚ/","defVi":"người lập kế hoạch, nhà quy hoạch","defEn":"a person who makes plans, especially regarding urban development or events","examples":["The urban [planner] proposed building more green spaces around the city center. (=Dịch: Nhà quy hoạch đô thị đã đề xuất xây dựng thêm nhiều không gian xanh xung quanh trung tâm thành phố.)","Hiring an experienced wedding [planner] helped them avoid a lot of stress. (=Dịch: Việc thuê một người lập kế hoạch đám cưới giàu kinh nghiệm đã giúp họ tránh được rất nhiều căng thẳng.)","City [planner]s are trying to find effective solutions to ease daily traffic congestion. (=Dịch: Các nhà quy hoạch thành phố đang cố gắng tìm ra những giải pháp hiệu quả để giảm bớt tình trạng ùn tắc giao thông hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=planner&lang=en-GB&ipa=%2F%CB%88pl%C3%A6n.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=planner&lang=en-US&ipa=%2F%CB%88pl%C3%A6n.%C9%9A%2F"},{"id":"lv_3_80","topic":"Urban Planning and Infrastructure Construction","word":"poverty","pos":"(n)","ipa":"/ˈpɑː.vɚ.t̬i/","defVi":"sự nghèo đói, cảnh bần cùng","defEn":"the state of being extremely poor and lacking the means for basic needs","examples":["Education is widely seen as the key to escaping [poverty]. (=Dịch: Giáo dục được xem rộng rãi là chìa khóa để thoát nghèo.)","Many families in the region are living in extreme [poverty]. (=Dịch: Nhiều gia đình trong khu vực đang sống trong cảnh nghèo đói cùng cực.)","The charity aims to reduce urban [poverty] through job training. (=Dịch: Tổ chức từ thiện nhằm mục đích giảm nghèo đô thị thông qua việc đào tạo nghề.)"],"ukAudio":"/ai_services/tts3/?q=poverty&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=poverty&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F"},{"id":"lv_3_81","topic":"Urban Planning and Infrastructure Construction","word":"premise","pos":"(n)","ipa":"/ˈprem.ɪs/","defVi":"tiền đề, giả thuyết cơ sở","defEn":"an underlying assumption or idea on which an argument or theory is based","examples":["The entire theory is based on a false [premise]. (=Dịch: Toàn bộ lý thuyết đều dựa trên một tiền đề sai lầm.)","His argument relies on the [premise] that people always act rationally. (=Dịch: Lập luận của anh ấy dựa trên tiền đề rằng con người luôn hành động có lý trí.)","The experiment was designed to test the basic [premise] of the study. (=Dịch: Thí nghiệm được thiết kế để kiểm chứng tiền đề cơ bản của nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=premise&lang=en-GB&ipa=%2F%CB%88prem.%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=premise&lang=en-US&ipa=%2F%CB%88prem.%C9%AAs%2F"},{"id":"lv_3_82","topic":"Urban Planning and Infrastructure Construction","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a basic idea, rule, or moral belief that influences the way you behave or how things work","examples":["He refused to lie because it was against his personal [principle]. (=Dịch: Anh ấy từ chối nói dối vì điều đó đi ngược lại nguyên tắc cá nhân của mình.)","Students learn the basic [principle] of physics in high school. (=Dịch: Học sinh học các nguyên lý cơ bản của vật lý ở trường trung học phổ thông.)","Our organization is built upon the [principle] of equality for all. (=Dịch: Tổ chức của chúng tôi được xây dựng dựa trên nguyên tắc bình đẳng cho tất cả mọi người.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_3_83","topic":"Urban Planning and Infrastructure Construction","word":"pupil","pos":"(n)","ipa":"/ˈpjuː.pəl/","defVi":"học sinh (tiểu học/trung học); đồng tử (con ngươi)","defEn":"a student in school, especially a young child; also the round black opening in the center of the eye","examples":["The primary school has around four hundred [pupils]. (=Dịch: Trường tiểu học này có khoảng bốn trăm học sinh.)","The teacher encouraged every [pupil] to participate in the classroom discussion. (=Dịch: Giáo viên đã khuyến khích từng học sinh tham gia vào cuộc thảo luận trong lớp.)","His [pupils] dilated when the room suddenly went dark. (=Dịch: Đồng tử của anh ấy giãn ra khi căn phòng đột ngột tối sầm lại.)"],"ukAudio":"/ai_services/tts3/?q=pupil&lang=en-GB&ipa=%2F%CB%88pju%CB%90.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=pupil&lang=en-US&ipa=%2F%CB%88pju%CB%90.p%C9%99l%2F"},{"id":"lv_3_84","topic":"Urban Planning and Infrastructure Construction","word":"purchase","pos":"(v)","ipa":"/ˈpɜr.tʃəs/","defVi":"mua, sắm","defEn":"to buy something","examples":["She decided to [purchase] a new laptop for her university studies. (=Dịch: Cô ấy quyết định mua một chiếc máy tính xách tay mới để phục vụ cho việc học đại học.)","Tickets must be [purchased] at least two weeks in advance. (=Dịch: Vé phải được mua trước ít nhất hai tuần.)","He wants to [purchase] a property near the coast. (=Dịch: Anh ấy muốn mua một bất động sản gần bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=purchase&lang=en-GB&ipa=%2F%CB%88p%C9%9Cr.t%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=purchase&lang=en-US&ipa=%2F%CB%88p%C9%9Cr.t%CA%83%C9%99s%2F"},{"id":"lv_3_85","topic":"Urban Planning and Infrastructure Construction","word":"quarry","pos":"(n)","ipa":"/ˈkwɔːr.i/","defVi":"mỏ đá, nơi khai thác đá","defEn":"a large open pit from which stone, slate, or other materials are extracted","examples":["Limestone from the local [quarry] was used to construct many historic buildings in the area. (=Dịch: Đá vôi từ mỏ đá địa phương đã được sử dụng để xây dựng nhiều công trình lịch sử trong khu vực.)","Safety regulations were tightened at the slate [quarry] following an accidental rockslide. (=Dịch: Các quy định an toàn đã được thắt chặt tại mỏ khai thác đá phiến sau một vụ sạt lở đá tình cờ xảy ra.)","The abandoned [quarry] was transformed into a nature reserve with a deep artificial lake. (=Dịch: Mỏ đá bị bỏ hoang đã được chuyển đổi thành một khu bảo tồn thiên nhiên với một hồ nước nhân tạo sâu.)"],"ukAudio":"/ai_services/tts3/?q=quarry&lang=en-GB&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=quarry&lang=en-US&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F"},{"id":"lv_3_86","topic":"Urban Planning and Infrastructure Construction","word":"ramp","pos":"(n)","ipa":"/ræmp/","defVi":"đường dốc, lối dốc thoai thoải","defEn":"a slope or inclined surface joining two different levels","examples":["The building has a wheelchair [ramp] at the main entrance. (=Dịch: Tòa nhà có lối đi dốc dành cho xe lăn ở cổng chính.)","Cars slowed down as they approached the exit [ramp] of the highway. (=Dịch: Ô tô đã giảm tốc độ khi tiến lại gần đường dốc lối ra của đường cao tốc.)","Skaters love performing tricks on the wooden [ramp] in the park. (=Dịch: Những người trượt ván rất thích biểu diễn kỹ xảo trên đường dốc bằng gỗ trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=ramp&lang=en-GB&ipa=%2Fr%C3%A6mp%2F","usAudio":"/ai_services/tts3/?q=ramp&lang=en-US&ipa=%2Fr%C3%A6mp%2F"},{"id":"lv_3_87","topic":"Urban Planning and Infrastructure Construction","word":"reality","pos":"(n)","ipa":"/riˈæl.ə.t̬i/","defVi":"thực tế, hiện thực","defEn":"the state of things as they actually exist, rather than as they may be imagined","examples":["The harsh [reality] is that we do not have enough funds to finish the project. (=Dịch: Thực tế phũ phàng là chúng tôi không có đủ kinh phí để hoàn thành dự án.)","His childhood dream of becoming an astronaut finally became a [reality]. (=Dịch: Ước mơ thời thơ ấu trở thành phi hành gia của anh ấy cuối cùng đã trở thành hiện thực.)","Virtual reality allows users to experience situations that feel close to [reality]. (=Dịch: Thực tế ảo cho phép người dùng trải nghiệm những tình huống mang lại cảm giác chân thực như đời thực.)"],"ukAudio":"/ai_services/tts3/?q=reality&lang=en-GB&ipa=%2Fri%CB%88%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=reality&lang=en-US&ipa=%2Fri%CB%88%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_88","topic":"Urban Planning and Infrastructure Construction","word":"reclaim","pos":"(v)","ipa":"/rɪˈkleɪm/","defVi":"khai hoang, cải tạo, tái chế","defEn":"to recover or make usable land or materials that were previously unused, degraded, or waste","examples":["The government initiated a project to [reclaim] degraded marshland for agriculture. (=Dịch: Chính phủ đã khởi xướng một dự án cải tạo vùng đất ngập nước bị suy thoái để phục vụ nông nghiệp.)","The factory uses modern methods to [reclaim] valuable metals from industrial waste. (=Dịch: Nhà máy sử dụng các phương pháp hiện đại để thu hồi các kim loại quý từ chất thải công nghiệp.)","Efforts were made to [reclaim] the abandoned quarry and transform it into a public park. (=Dịch: Nhiều nỗ lực đã được thực hiện nhằm phục hồi mỏ đá bị bỏ hoang và biến nó thành một công viên công cộng.)"],"ukAudio":"/ai_services/tts3/?q=reclaim&lang=en-GB&ipa=%2Fr%C9%AA%CB%88kle%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=reclaim&lang=en-US&ipa=%2Fr%C9%AA%CB%88kle%C9%AAm%2F"},{"id":"lv_3_89","topic":"Urban Planning and Infrastructure Construction","word":"recreation","pos":"(n)","ipa":"/ˌrek.riˈeɪ.ʃən/","defVi":"sự giải trí, trò tiêu khiển","defEn":"activity done for enjoyment when one is not working","examples":["Swimming and cycling are popular forms of [recreation] for families. (=Dịch: Bơi lội và đạp xe là những hình thức giải trí phổ biến của các gia đình.)","The community center offers a variety of sports facilities for [recreation]. (=Dịch: Trung tâm cộng đồng cung cấp nhiều cơ sở vật chất thể thao phục vụ cho việc giải trí.)","He enjoys outdoor [recreation] such as hiking and camping on weekends. (=Dịch: Anh ấy thích các hoạt động giải trí ngoài trời như đi bộ đường dài và cắm trại vào cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=recreation&lang=en-GB&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=recreation&lang=en-US&ipa=%2F%CB%8Crek.ri%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_90","topic":"Urban Planning and Infrastructure Construction","word":"redevelopment","pos":"(n)","ipa":"/ˌriː.dɪˈvel.əp.mənt/","defVi":"sự tái quy hoạch, việc cải tạo và xây dựng lại","defEn":"the process of improving or rebuilding an area, often with new buildings","examples":["The city announced an ambitious [redevelopment] plan for the old industrial zone. (=Dịch: Thành phố đã công bố một kế hoạch tái phát triển đầy tham vọng cho khu công nghiệp cũ.)","Urban [redevelopment] has transformed this rundown neighborhood into a popular tourist spot. (=Dịch: Tái phát triển đô thị đã biến khu phố xuống cấp này thành một điểm thu hút khách du lịch nổi tiếng.)","Residents expressed concerns about rising housing costs following the [redevelopment] of the district. (=Dịch: Cư dân bày tỏ lo ngại về chi phí nhà ở tăng cao sau khi tái phát triển quận.)"],"ukAudio":"/ai_services/tts3/?q=redevelopment&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.d%C9%AA%CB%88vel.%C9%99p.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=redevelopment&lang=en-US&ipa=%2F%CB%8Cri%CB%90.d%C9%AA%CB%88vel.%C9%99p.m%C9%99nt%2F"},{"id":"lv_3_91","topic":"Urban Planning and Infrastructure Construction","word":"reed","pos":"(n)","ipa":"/riːd/","defVi":"cây sậy, lau sậy","defEn":"a tall, slender plant that grows in or near water, having hollow stalks","examples":["Water birds often build their nests among the dense [reeds] along the riverbank. (=Dịch: Các loài chim nước thường làm tổ giữa những bụi sậy rậm rạp dọc theo bờ sông.)","In ancient times, paper was made from papyrus [reeds]. (=Dịch: Thời cổ đại, giấy được làm từ cây sậy papyrus.)","The wind gently rustled through the dry [reeds] by the lake. (=Dịch: Gió thổi xào xạc nhẹ qua những rặng sậy khô bên hồ.)"],"ukAudio":"/ai_services/tts3/?q=reed&lang=en-GB&ipa=%2Fri%CB%90d%2F","usAudio":"/ai_services/tts3/?q=reed&lang=en-US&ipa=%2Fri%CB%90d%2F"},{"id":"lv_3_92","topic":"Urban Planning and Infrastructure Construction","word":"relaxing","pos":"(adj)","ipa":"/rɪˈlæk.sɪŋ/","defVi":"thư giãn, mang lại cảm giác thoải mái","defEn":"making someone feel calm, peaceful, and free from stress","examples":["Listening to soft instrumental music is a very [relaxing] way to end a busy day. (=Dịch: Nghe nhạc không lời nhẹ nhàng là một cách rất thư giãn để kết thúc một ngày bận rộn.)","They spent a [relaxing] weekend at a quiet cabin near the lake. (=Dịch: Họ đã trải qua một ngày cuối tuần thư thái tại một căn nhà gỗ yên tĩnh gần hồ.)","The hotel spa provides a [relaxing] atmosphere with warm lighting and gentle scents. (=Dịch: Khu spa của khách sạn mang lại một không gian thư thái với ánh sáng ấm áp và hương thơm dịu nhẹ.)"],"ukAudio":"/ai_services/tts3/?q=relaxing&lang=en-GB&ipa=%2Fr%C9%AA%CB%88l%C3%A6k.s%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=relaxing&lang=en-US&ipa=%2Fr%C9%AA%CB%88l%C3%A6k.s%C9%AA%C5%8B%2F"},{"id":"lv_3_93","topic":"Urban Planning and Infrastructure Construction","word":"reopen","pos":"(v)","ipa":"/riˈoʊ.pən/","defVi":"mở cửa lại, tái hoạt động","defEn":"to open again after being closed for a period of time","examples":["The museum plans to [reopen] to the public next month. (=Dịch: Bảo tàng có kế hoạch mở cửa trở lại cho công chúng vào tháng tới.)","The police decided to [reopen] the investigation after finding new clues. (=Dịch: Cảnh sát đã quyết định mở lại cuộc điều tra sau khi tìm thấy những manh mối mới.)","Local shops are preparing to [reopen] following the renovation. (=Dịch: Các cửa hàng địa phương đang chuẩn bị mở cửa trở lại sau khi tu sửa.)"],"ukAudio":"/ai_services/tts3/?q=reopen&lang=en-GB&ipa=%2Fri%CB%88o%CA%8A.p%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reopen&lang=en-US&ipa=%2Fri%CB%88o%CA%8A.p%C9%99n%2F"},{"id":"lv_3_94","topic":"Urban Planning and Infrastructure Construction","word":"representative","pos":"(n)","ipa":"/ˌrep.rɪˈzen.t̬ə.t̬ɪv/","defVi":"người đại diện, đại biểu","defEn":"a person chosen or elected to speak or act on behalf of others","examples":["A customer service [representative] will answer your call shortly. (=Dịch: Đại diện dịch vụ khách hàng sẽ trả lời cuộc gọi của bạn trong giây lát.)","Each student group elected a [representative] to attend the council meeting. (=Dịch: Mỗi nhóm sinh viên đã bầu ra một đại diện để tham dự cuộc họp hội đồng.)","She spoke to the company [representative] to negotiate the terms of the contract. (=Dịch: Cô ấy đã nói chuyện với đại diện công ty để đàm phán các điều khoản của hợp đồng.)"],"ukAudio":"/ai_services/tts3/?q=representative&lang=en-GB&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=representative&lang=en-US&ipa=%2F%CB%8Crep.r%C9%AA%CB%88zen.t%CC%AC%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_3_95","topic":"Urban Planning and Infrastructure Construction","word":"residential","pos":"(adj)","ipa":"/ˌrez.əˈden.ʃəl/","defVi":"(thuộc) khu dân cư, để ở","defEn":"suitable for or containing homes rather than businesses or industries","examples":["The speed limit is lower in [residential] areas to protect pedestrians. (=Dịch: Giới hạn tốc độ thấp hơn ở các khu dân cư để bảo vệ người đi bộ.)","They moved away from the noisy commercial center to a quiet [residential] suburb. (=Dịch: Họ đã chuyển từ khu trung tâm thương mại ồn ào đến một vùng ngoại ô dân cư yên tĩnh.)","Many [residential] buildings were constructed during the recent economic boom. (=Dịch: Nhiều tòa nhà dân cư đã được xây dựng trong thời kỳ bùng nổ kinh tế gần đây.)"],"ukAudio":"/ai_services/tts3/?q=residential&lang=en-GB&ipa=%2F%CB%8Crez.%C9%99%CB%88den.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=residential&lang=en-US&ipa=%2F%CB%8Crez.%C9%99%CB%88den.%CA%83%C9%99l%2F"},{"id":"lv_3_96","topic":"Urban Planning and Infrastructure Construction","word":"respondent","pos":"(n)","ipa":"/rɪˈspɑːn.dənt/","defVi":"người trả lời (khảo sát, phỏng vấn)","defEn":"a person who answers questions, especially in a survey or study","examples":["Over sixty percent of [respondents] agreed with the proposed changes. (=Dịch: Hơn sáu mươi phần trăm số người được khảo sát đồng ý với những thay đổi được đề xuất.)","Each [respondent] was asked to complete a brief questionnaire online. (=Dịch: Mỗi người tham gia khảo sát được yêu cầu hoàn thành một bảng câu hỏi ngắn trực tuyến.)","The researchers interviewed more than one thousand [respondents] across the country. (=Dịch: Các nhà nghiên cứu đã phỏng vấn hơn một nghìn người tham gia khảo sát trên khắp cả nước.)"],"ukAudio":"/ai_services/tts3/?q=respondent&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=respondent&lang=en-US&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F"},{"id":"lv_3_97","topic":"Urban Planning and Infrastructure Construction","word":"riverside","pos":"(n)","ipa":"/ˈrɪv.ɚ.saɪd/","defVi":"bờ sông, ven sông","defEn":"the area of land situated along the edge of a river","examples":["We enjoyed a long evening walk along the peaceful [riverside]. (=Dịch: Chúng tôi rất thích đi dạo vào buổi tối dọc theo bờ sông yên bình.)","The city constructed a scenic cycling track on the northern [riverside]. (=Dịch: Thành phố đã xây dựng một đường đạp xe ngắm cảnh ở bờ sông phía bắc.)","Many popular restaurants are located on the [riverside], offering beautiful water views. (=Dịch: Nhiều nhà hàng nổi tiếng tọa lạc bên bờ sông, mang đến tầm nhìn tuyệt đẹp ra mặt nước.)"],"ukAudio":"/ai_services/tts3/?q=riverside&lang=en-GB&ipa=%2F%CB%88r%C9%AAv.%C9%9A.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=riverside&lang=en-US&ipa=%2F%CB%88r%C9%AAv.%C9%9A.sa%C9%AAd%2F"},{"id":"lv_3_98","topic":"Urban Planning and Infrastructure Construction","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a neat line of people, objects, or seats arranged side by side or one behind another","examples":["The students were asked to sit quietly in a single [row]. (=Dịch: Các học sinh được yêu cầu ngồi trật tự thành một hàng duy nhất.)","A long [row] of solar panels was installed along the edge of the farm. (=Dịch: Một dãy dài các tấm pin mặt trời đã được lắp đặt dọc theo rìa trang trại.)","She planted a [row] of rose bushes in front of her house. (=Dịch: Cô ấy đã trồng một hàng bụi hoa hồng trước nhà.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_3_99","topic":"Urban Planning and Infrastructure Construction","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"thuộc hoàng gia, hoàng tộc","defEn":"relating to a king or queen","examples":["The [royal] family attended the annual charity event together. (=Dịch: Hoàng gia đã cùng nhau tham dự sự kiện từ thiện thường niên.)","Visitors are allowed to explore parts of the historic [royal] palace. (=Dịch: Du khách được phép khám phá một số khu vực của cung điện hoàng gia mang tính lịch sử.)","The museum displays a rare collection of ancient [royal] jewels. (=Dịch: Bảo tàng trưng bày một bộ sưu tập trang sức hoàng gia cổ đại quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_3_100","topic":"Urban Planning and Infrastructure Construction","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ɚ/","defVi":"cao su","defEn":"an elastic substance made from the juice of tropical trees or synthesized chemically","examples":["Car tires are made of durable synthetic [rubber]. (=Dịch: Lốp ô tô được làm từ cao su tổng hợp có độ bền cao.)","The boots are waterproof because they are lined with [rubber]. (=Dịch: Đôi ủng có khả năng chống nước vì chúng được lót bằng cao su.)","She used a soft [rubber] ball to exercise her hand muscles. (=Dịch: Cô ấy đã dùng một quả bóng cao su mềm để luyện tập cơ tay.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F"},{"id":"lv_3_101","topic":"Urban Planning and Infrastructure Construction","word":"secure","pos":"(adj)","ipa":"/səˈkjʊr/","defVi":"an toàn, chắc chắn, kiên cố","defEn":"safe from danger, harm, or the risk of failure","examples":["Online shoppers must ensure they are using a [secure] connection before entering payment details. (=Dịch: Người mua sắm trực tuyến phải đảm bảo họ đang sử dụng một kết nối an toàn trước khi nhập thông tin thanh toán.)","The documents were kept in a [secure] safe in the manager's private office. (=Dịch: Các tài liệu được lưu giữ trong một chiếc két sắt an toàn tại văn phòng riêng của người quản lý.)","She finally found a [secure] job that provided stable income and health benefits. (=Dịch: Cuối cùng cô ấy cũng tìm được một công việc ổn định mang lại thu nhập vững chắc và các chế độ bảo hiểm y tế.)"],"ukAudio":"/ai_services/tts3/?q=secure&lang=en-GB&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=secure&lang=en-US&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F"},{"id":"lv_3_102","topic":"Urban Planning and Infrastructure Construction","word":"silent","pos":"(adj)","ipa":"/ˈsaɪ.lənt/","defVi":"yên lặng, im lặng","defEn":"making no sound or completely quiet","examples":["The library remained completely [silent] throughout the morning. (=Dịch: Thư viện hoàn toàn yên tĩnh trong suốt cả buổi sáng.)","He decided to keep [silent] during the intense debate. (=Dịch: Anh ấy quyết định giữ im lặng trong suốt cuộc tranh luận căng thẳng.)","Students were asked to observe a minute of [silent] reflection. (=Dịch: Các học sinh được yêu cầu dành một phút mặc niệm trong tĩnh lặng.)"],"ukAudio":"/ai_services/tts3/?q=silent&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.l%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=silent&lang=en-US&ipa=%2F%CB%88sa%C9%AA.l%C9%99nt%2F"},{"id":"lv_3_103","topic":"Urban Planning and Infrastructure Construction","word":"skateboard","pos":"(n)","ipa":"/ˈskeɪt.bɔrd/","defVi":"ván trượt","defEn":"a short narrow board with small wheels attached underneath, used for riding on","examples":["He rode his [skateboard] to school every morning. (=Dịch: Cậu ấy trượt ván đến trường mỗi sáng.)","The city recently built a new park for teenagers who ride a [skateboard]. (=Dịch: Thành phố gần đây đã xây dựng một công viên mới dành cho thanh thiếu niên chơi ván trượt.)","She bought a colorful [skateboard] as a birthday gift for her brother. (=Dịch: Cô ấy đã mua một chiếc ván trượt đầy màu sắc làm quà sinh nhật cho anh trai mình.)"],"ukAudio":"/ai_services/tts3/?q=skateboard&lang=en-GB&ipa=%2F%CB%88ske%C9%AAt.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=skateboard&lang=en-US&ipa=%2F%CB%88ske%C9%AAt.b%C9%94rd%2F"},{"id":"lv_3_104","topic":"Urban Planning and Infrastructure Construction","word":"statue","pos":"(n)","ipa":"/ˈstæ.tʃu/","defVi":"tượng, bức tượng","defEn":"a three-dimensional work of art sculpted or cast in stone, metal, or wood, representing a person or animal","examples":["A bronze [statue] of the famous poet was erected in the central square. (=Dịch: Một bức tượng đồng của nhà thơ nổi tiếng đã được dựng lên ở quảng trường trung tâm.)","Tourists gathered around the ancient marble [statue] to take photographs. (=Dịch: Khách du lịch tập trung quanh bức tượng cẩm thạch cổ kính để chụp ảnh.)","The city unveiled a new [statue] honoring frontline healthcare workers. (=Dịch: Thành phố đã khánh thành một bức tượng mới nhằm tôn vinh các nhân viên y tế tuyến đầu.)"],"ukAudio":"/ai_services/tts3/?q=statue&lang=en-GB&ipa=%2F%CB%88st%C3%A6.t%CA%83u%2F","usAudio":"/ai_services/tts3/?q=statue&lang=en-US&ipa=%2F%CB%88st%C3%A6.t%CA%83u%2F"},{"id":"lv_3_105","topic":"Urban Planning and Infrastructure Construction","word":"storey","pos":"(n)","ipa":"/ˈstɔːr.i/","defVi":"tầng (của tòa nhà)","defEn":"a level or floor of a building","examples":["They live in a modern apartment on the twentieth [storey]. (=Dịch: Họ sống trong một căn hộ hiện đại ở tầng hai mươi.)","The developer plans to construct a multi-[storey] car park near the station. (=Dịch: Chủ đầu tư có kế hoạch xây dựng một bãi đỗ xe nhiều tầng gần nhà ga.)","The traditional house only has one [storey]. (=Dịch: Ngôi nhà truyền thống này chỉ có một tầng.)"],"ukAudio":"/ai_services/tts3/?q=storey&lang=en-GB&ipa=%2F%CB%88st%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=storey&lang=en-US&ipa=%2F%CB%88st%C9%94%CB%90r.i%2F"},{"id":"lv_3_106","topic":"Urban Planning and Infrastructure Construction","word":"suburb","pos":"(n)","ipa":"/ˈsʌb.ɜrb/","defVi":"vùng ngoại ô, vùng ngoại thành","defEn":"a residential area located outside the center of a large city","examples":["Many families move to a peaceful [suburb] to enjoy more open space and cleaner air. (=Dịch: Nhiều gia đình chuyển đến một vùng ngoại ô yên bình để tận hưởng không gian thoáng đãng hơn và không khí trong lành hơn.)","The newly built railway line connects the quiet [suburb] directly to downtown. (=Dịch: Tuyến đường sắt mới xây kết nối trực tiếp khu ngoại ô yên tĩnh với khu trung tâm thành phố.)","Property prices in this northern [suburb] have risen sharply over the past decade. (=Dịch: Giá bất động sản ở vùng ngoại ô phía bắc này đã tăng mạnh trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=suburb&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.%C9%9Crb%2F","usAudio":"/ai_services/tts3/?q=suburb&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.%C9%9Crb%2F"},{"id":"lv_3_107","topic":"Urban Planning and Infrastructure Construction","word":"symbolic","pos":"(adj)","ipa":"/sɪmˈbɑː.lɪk/","defVi":"mang tính biểu tượng, tượng trưng","defEn":"serving as a symbol; representing something deeper or meaningful","examples":["The dove is widely recognized as a [symbolic] figure of peace. (=Dịch: Chim bồ câu được công nhận rộng rãi là một hình tượng tượng trưng cho hòa bình.)","Giving flowers on Valentine's Day has a strong [symbolic] meaning. (=Dịch: Việc tặng hoa vào ngày lễ Tình nhân mang một ý nghĩa biểu tượng sâu sắc.)","The lighting of the Olympic flame is a purely [symbolic] gesture. (=Dịch: Việc thắp sáng ngọn đuốc Olympic hoàn toàn là một cử chỉ mang tính biểu tượng.)"],"ukAudio":"/ai_services/tts3/?q=symbolic&lang=en-GB&ipa=%2Fs%C9%AAm%CB%88b%C9%91%CB%90.l%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=symbolic&lang=en-US&ipa=%2Fs%C9%AAm%CB%88b%C9%91%CB%90.l%C9%AAk%2F"},{"id":"lv_3_108","topic":"Urban Planning and Infrastructure Construction","word":"tile","pos":"(n)","ipa":"/taɪl/","defVi":"gạch lát, gạch ốp, ngói","defEn":"a flat piece of baked clay, stone, or ceramic used for covering roofs, floors, or walls","examples":["They decided to replace the old bathroom [tiles] with modern ceramic ones. (=Dịch: Họ quyết định thay thế gạch phòng tắm cũ bằng loại gạch gốm hiện đại.)","Strong winds blew several roof [tiles] off during the storm. (=Dịch: Gió mạnh đã thổi bay vài viên ngói lợp mái trong cơn bão.)","The kitchen floor is covered with polished white [tiles]. (=Dịch: Sàn nhà bếp được lát bằng những viên gạch trắng sáng bóng.)"],"ukAudio":"/ai_services/tts3/?q=tile&lang=en-GB&ipa=%2Fta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=tile&lang=en-US&ipa=%2Fta%C9%AAl%2F"},{"id":"lv_3_109","topic":"Urban Planning and Infrastructure Construction","word":"transform","pos":"(v)","ipa":"/trænsˈfɔrm/","defVi":"biến đổi, thay đổi diện mạo","defEn":"to change the form, appearance, or character of something completely","examples":["The new park has [transformed] the abandoned industrial zone into a vibrant public area. (=Dịch: Công viên mới đã biến khu công nghiệp bị bỏ hoang thành một khu vực công cộng sôi động.)","Online learning has the potential to [transform] modern education. (=Dịch: Học trực tuyến có tiềm năng làm thay đổi nền giáo dục hiện đại.)","A fresh coat of paint will [transform] the look of the old living room. (=Dịch: Một lớp sơn mới sẽ làm thay đổi hoàn toàn diện mạo của phòng khách cũ.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F"},{"id":"lv_3_110","topic":"Urban Planning and Infrastructure Construction","word":"transformation","pos":"(n)","ipa":"/ˌtræns.fɚˈmeɪ.ʃən/","defVi":"sự biến đổi, sự chuyển đổi hoàn toàn","defEn":"a complete change in the appearance or character of something","examples":["The city underwent a dramatic [transformation] over the last decade. (=Dịch: Thành phố đã trải qua một sự chuyển mình mạnh mẽ trong thập kỷ qua.)","Digital technology has led to a rapid [transformation] in education. (=Dịch: Công nghệ số đã dẫn đến một sự chuyển biến nhanh chóng trong giáo dục.)","Her fitness journey resulted in an impressive physical [transformation]. (=Dịch: Hành trình tập luyện rèn luyện thể chất của cô ấy đã mang lại một sự thay đổi ngoạn mục về vóc dáng.)"],"ukAudio":"/ai_services/tts3/?q=transformation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=transformation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_3_111","topic":"Urban Planning and Infrastructure Construction","word":"tropical","pos":"(adj)","ipa":"/ˈtrɑː.pɪ.kəl/","defVi":"nhiệt đới","defEn":"connected with the warmest areas of the world near the equator","examples":["The island is famous for its lush [tropical] rainforests. (=Dịch: Hòn đảo này nổi tiếng với những khu rừng mưa nhiệt đới tươi tốt.)","They enjoy eating sweet [tropical] fruits such as mangoes and papayas. (=Dịch: Họ thích ăn các loại trái cây nhiệt đới ngọt ngào như xoài và đu đủ.)","A sudden [tropical] storm caused minor flooding along the coast. (=Dịch: Một cơn bão nhiệt đới bất ngờ đã gây ra ngập lụt nhẹ dọc bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=tropical&lang=en-GB&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tropical&lang=en-US&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F"},{"id":"lv_3_112","topic":"Urban Planning and Infrastructure Construction","word":"uncomfortable","pos":"(adj)","ipa":"/ʌnˈkʌmf.tə.bəl/","defVi":"không thoải mái, khó chịu, ngượng ngùng","defEn":"causing or feeling a lack of physical comfort, ease, or relaxation","examples":["The old wooden chair was extremely [uncomfortable] to sit on. (=Dịch: Chiếc ghế gỗ cũ ngồi cực kỳ khó chịu.)","There was an [uncomfortable] silence when she asked the sensitive question. (=Dịch: Bầu không khí im lặng đầy gượng gạo bao trùm khi cô ấy đặt ra câu hỏi nhạy cảm.)","Wearing wet shoes all day made him feel very [uncomfortable]. (=Dịch: Việc đi giày ướt cả ngày khiến anh ấy cảm thấy rất khó chịu.)"],"ukAudio":"/ai_services/tts3/?q=uncomfortable&lang=en-GB&ipa=%2F%CA%8Cn%CB%88k%CA%8Cmf.t%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=uncomfortable&lang=en-US&ipa=%2F%CA%8Cn%CB%88k%CA%8Cmf.t%C9%99.b%C9%99l%2F"},{"id":"lv_3_113","topic":"Urban Planning and Infrastructure Construction","word":"union","pos":"(n)","ipa":"/ˈjuːn.jən/","defVi":"công đoàn, liên đoàn, sự kết hợp","defEn":"an organization of workers formed to protect their rights and interests","examples":["The trade [union] negotiated better working hours for the factory staff. (=Dịch: Công đoàn thương mại đã đàm phán để có giờ làm việc tốt hơn cho các nhân viên nhà máy.)","Joining a labor [union] gives employees a stronger collective voice. (=Dịch: Tham gia một công đoàn lao động mang lại cho nhân viên tiếng nói tập thể mạnh mẽ hơn.)","Several European countries formed a political and economic [union]. (=Dịch: Một số quốc gia châu Âu đã thành lập một liên minh chính trị và kinh tế.)"],"ukAudio":"/ai_services/tts3/?q=union&lang=en-GB&ipa=%2F%CB%88ju%CB%90n.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=union&lang=en-US&ipa=%2F%CB%88ju%CB%90n.j%C9%99n%2F"},{"id":"lv_3_114","topic":"Urban Planning and Infrastructure Construction","word":"unsafe","pos":"(adj)","ipa":"/ʌnˈseɪf/","defVi":"không an toàn, nguy hiểm","defEn":"likely to cause harm or danger","examples":["It is completely [unsafe] to walk on the frozen lake in spring. (=Dịch: Đi bộ trên mặt hồ đóng băng vào mùa xuân là hoàn toàn không an toàn.)","The building was declared [unsafe] after the earthquake. (=Dịch: Tòa nhà bị tuyên bố là không an toàn sau trận động đất.)","Driving in extreme weather conditions is extremely [unsafe]. (=Dịch: Lái xe trong điều kiện thời tiết khắc nghiệt là cực kỳ mất an toàn.)"],"ukAudio":"/ai_services/tts3/?q=unsafe&lang=en-GB&ipa=%2F%CA%8Cn%CB%88se%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=unsafe&lang=en-US&ipa=%2F%CA%8Cn%CB%88se%C9%AAf%2F"},{"id":"lv_3_115","topic":"Urban Planning and Infrastructure Construction","word":"virtual","pos":"(adj)","ipa":"/ˈvɝː.tʃu.əl/","defVi":"ảo, thực tế ảo","defEn":"created by computer software and appearing to exist in real life","examples":["The company held a [virtual] meeting with clients from across the globe. (=Dịch: Công ty đã tổ chức một cuộc họp trực tuyến với các khách hàng từ khắp nơi trên thế giới.)","Students wore headsets to enter a [virtual] science laboratory. (=Dịch: Học sinh đã đeo tai nghe thực tế ảo để bước vào một phòng thí nghiệm khoa học ảo.)","Many museums now offer engaging [virtual] tours on their websites. (=Dịch: Nhiều bảo tàng hiện cung cấp các chuyến tham quan ảo hấp dẫn trên trang web của họ.)"],"ukAudio":"/ai_services/tts3/?q=virtual&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=virtual&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.t%CA%83u.%C9%99l%2F"},{"id":"lv_3_116","topic":"Urban Planning and Infrastructure Construction","word":"visibility","pos":"(n)","ipa":"/ˌvɪz.əˈbɪl.ə.t̬i/","defVi":"tầm nhìn, độ nhìn rõ","defEn":"the distance that can be seen clearly in particular weather conditions","examples":["Thick fog reduced [visibility] to less than fifty meters. (=Dịch: Sương mù dày đặc làm giảm tầm nhìn xuống dưới năm mươi mét.)","Poor [visibility] caused several flights to be delayed this morning. (=Dịch: Tầm nhìn kém đã khiến một số chuyến bay bị hoãn vào sáng nay.)","Cyclists should wear bright clothing to improve their [visibility] at night. (=Dịch: Người đi xe đạp nên mặc quần áo sáng màu để tăng khả năng nhận diện vào ban đêm.)"],"ukAudio":"/ai_services/tts3/?q=visibility&lang=en-GB&ipa=%2F%CB%8Cv%C9%AAz.%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=visibility&lang=en-US&ipa=%2F%CB%8Cv%C9%AAz.%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_3_117","topic":"Urban Planning and Infrastructure Construction","word":"wheelchair","pos":"(n)","ipa":"/ˈwiːl.tʃer/","defVi":"xe lăn","defEn":"a chair with wheels, used by people who cannot walk due to illness or injury","examples":["The museum recently installed ramps to ensure easy access for visitors in a [wheelchair]. (=Dịch: Bảo tàng gần đây đã lắp đặt các đường dốc nhằm đảm bảo lối đi lại dễ dàng cho khách tham quan ngồi xe lăn.)","After his sports injury, he had to use a [wheelchair] for several months. (=Dịch: Sau chấn thương thể thao, anh ấy đã phải sử dụng xe lăn trong vài tháng.)","Electric [wheelchair] models offer greater independence for individuals with mobility challenges. (=Dịch: Các mẫu xe lăn điện mang lại sự độc lập hơn cho những người gặp khó khăn trong việc vận động.)"],"ukAudio":"/ai_services/tts3/?q=wheelchair&lang=en-GB&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F","usAudio":"/ai_services/tts3/?q=wheelchair&lang=en-US&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F"},{"id":"lv_3_118","topic":"Urban Planning and Infrastructure Construction","word":"widen","pos":"(v)","ipa":"/ˈwaɪ.dən/","defVi":"mở rộng, nới rộng","defEn":"to become wider, or to make something wider or broader","examples":["The local council plans to [widen] the main road to reduce traffic jams. (=Dịch: Hội đồng địa phương có kế hoạch mở rộng con đường chính để giảm thiểu ùn tắc giao thông.)","Reading books regularly can help you [widen] your general knowledge. (=Dịch: Đọc sách thường xuyên có thể giúp bạn mở rộng kiến thức chung của mình.)","The gap between rich and poor continues to [widen] in many countries. (=Dịch: Khoảng cách giàu nghèo tiếp tục nới rộng ở nhiều quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=widen&lang=en-GB&ipa=%2F%CB%88wa%C9%AA.d%C9%99n%2F","usAudio":"/ai_services/tts3/?q=widen&lang=en-US&ipa=%2F%CB%88wa%C9%AA.d%C9%99n%2F"}]},"rawTopic":"Urban Planning and Infrastructure Construction"},{"id":"listening_u5_5","title":"Chủ đề 5/10: Cultural and Historical Exchange","actTitle":"Từ vựng chủ đề: Cultural and Historical Exchange (435 từ)","problem":{"pType":"topic_flashcards","topic":"Cultural and Historical Exchange","count":435,"words":[{"id":"lv_4_0","topic":"Cultural and Historical Exchange","word":"aboriginal","pos":"(adj)","ipa":"/ˌæb.əˈrɪdʒ.ən.əl/","defVi":"thuộc về thổ dân, bản địa nguyên thủy","defEn":"relating to the original people or things that have existed in a place from the earliest known times","examples":["The museum exhibits ancient tools and pottery made by [aboriginal] tribes. (=Dịch: Bảo tàng trưng bày các công cụ và đồ gốm cổ xưa do các bộ lạc thổ dân tạo ra.)","They are working to preserve [aboriginal] languages before they disappear completely. (=Dịch: Họ đang nỗ lực bảo tồn các ngôn ngữ thổ dân trước khi chúng biến mất hoàn toàn.)","Traditional [aboriginal] rock art provides valuable insights into ancient history. (=Dịch: Nghệ thuật trên đá truyền thống của thổ dân cung cấp những hiểu biết quý giá về lịch sử cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=aboriginal&lang=en-GB&ipa=%2F%CB%8C%C3%A6b.%C9%99%CB%88r%C9%AAd%CA%92.%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aboriginal&lang=en-US&ipa=%2F%CB%8C%C3%A6b.%C9%99%CB%88r%C9%AAd%CA%92.%C9%99n.%C9%99l%2F"},{"id":"lv_4_1","topic":"Cultural and Historical Exchange","word":"academy","pos":"(n)","ipa":"/əˈkæd.ə.mi/","defVi":"học viện, viện hàn lâm","defEn":"an institution or school designed for specialized training, education, or research","examples":["He applied for admission to the prestigious military [academy] after finishing high school. (=Dịch: Anh ấy đã nộp đơn xin nhập học vào học viện quân sự danh giá sau khi học xong trung học.)","The national science [academy] recently published a major report on climate change. (=Dịch: Viện hàn lâm khoa học quốc gia gần đây đã công bố một báo cáo quan trọng về biến đổi khí hậu.)","She improved her tennis skills after joining a specialized sports [academy]. (=Dịch: Cô ấy đã nâng cao kỹ năng quần vợt của mình sau khi gia nhập một học viện thể thao chuyên biệt.)"],"ukAudio":"/ai_services/tts3/?q=academy&lang=en-GB&ipa=%2F%C9%99%CB%88k%C3%A6d.%C9%99.mi%2F","usAudio":"/ai_services/tts3/?q=academy&lang=en-US&ipa=%2F%C9%99%CB%88k%C3%A6d.%C9%99.mi%2F"},{"id":"lv_4_2","topic":"Cultural and Historical Exchange","word":"accountants","pos":"(n)","ipa":"/əˈkaʊn.tənts/","defVi":"kế toán viên","defEn":"professionals whose job is to keep and inspect financial records","examples":["Many large companies hire external [accountants] to audit their finances. (=Dịch: Nhiều công ty lớn thuê kế toán viên bên ngoài để kiểm toán tài chính của họ.)","The firm employs five certified [accountants] to manage corporate tax filings. (=Dịch: Công ty tuyển dụng năm kế toán viên có chứng chỉ để quản lý việc kê khai thuế doanh nghiệp.)","Experienced [accountants] are always in high demand across various industries. (=Dịch: Những kế toán viên giàu kinh nghiệm luôn được săn đón nhiều ở các ngành nghề khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=accountants&lang=en-GB&ipa=%2F%C9%99%CB%88ka%CA%8An.t%C9%99nts%2F","usAudio":"/ai_services/tts3/?q=accountants&lang=en-US&ipa=%2F%C9%99%CB%88ka%CA%8An.t%C9%99nts%2F"},{"id":"lv_4_3","topic":"Cultural and Historical Exchange","word":"adaptation","pos":"(n)","ipa":"/ˌæd.æpˈteɪ.ʃən/","defVi":"sự thích nghi; tác phẩm chuyển thể","defEn":"the process of changing to suit a new situation, or a film or book that has been changed from another work","examples":["The film is a faithful [adaptation] of the famous novel. (=Dịch: Bộ phim là một tác phẩm chuyển thể trung thành với cuốn tiểu thuyết nổi tiếng.)","Living in a colder climate requires some physical [adaptation]. (=Dịch: Sống ở nơi có khí hậu lạnh hơn đòi hỏi sự thích nghi nhất định về mặt thể chất.)","The species survived thanks to its rapid [adaptation] to environmental changes. (=Dịch: Loài này đã sống sót nhờ khả năng thích nghi nhanh chóng với những thay đổi của môi trường.)"],"ukAudio":"/ai_services/tts3/?q=adaptation&lang=en-GB&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=adaptation&lang=en-US&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_4","topic":"Cultural and Historical Exchange","word":"advanced","pos":"(adj)","ipa":"/ədˈvænst/","defVi":"tiên tiến, cao cấp, nâng cao","defEn":"highly developed, complex, or at a high level of progress","examples":["The hospital is equipped with [advanced] medical technology. (=Dịch: Bệnh viện được trang bị công nghệ y tế tiên tiến.)","Students need to pass a test before joining the [advanced] English class. (=Dịch: Học sinh cần phải vượt qua một bài kiểm tra trước khi tham gia lớp tiếng Anh nâng cao.)","Scientists are exploring [advanced] materials to make batteries last longer. (=Dịch: Các nhà khoa học đang nghiên cứu các vật liệu tiên tiến để giúp pin có tuổi thọ lâu hơn.)"],"ukAudio":"/ai_services/tts3/?q=advanced&lang=en-GB&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F","usAudio":"/ai_services/tts3/?q=advanced&lang=en-US&ipa=%2F%C9%99d%CB%88v%C3%A6nst%2F"},{"id":"lv_4_5","topic":"Cultural and Historical Exchange","word":"aerial","pos":"(adj)","ipa":"/ˈer.i.əl/","defVi":"trên không, từ trên cao","defEn":"existing, happening, or operating in the air; seen from above","examples":["The documentary showed breathtaking [aerial] views of the Amazon rainforest. (=Dịch: Bộ phim tài liệu đã cho thấy những khung cảnh ngoạn mục chụp từ trên không của rừng mưa nhiệt đới Amazon.)","Drones are increasingly used for [aerial] photography and mapping. (=Dịch: Máy bay không người lái ngày càng được sử dụng nhiều cho việc chụp ảnh và lập bản đồ từ trên cao.)","The army launched an [aerial] attack on the enemy stronghold. (=Dịch: Quân đội đã mở một cuộc không kích vào thành trì của đối phương.)"],"ukAudio":"/ai_services/tts3/?q=aerial&lang=en-GB&ipa=%2F%CB%88er.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aerial&lang=en-US&ipa=%2F%CB%88er.i.%C9%99l%2F"},{"id":"lv_4_6","topic":"Cultural and Historical Exchange","word":"alike","pos":"(adj)","ipa":"/əˈlaɪk/","defVi":"giống nhau, tương tự nhau","defEn":"similar to each other in appearance, character, or nature","examples":["The two sisters look so [alike] that people often confuse them. (=Dịch: Hai chị em trông giống nhau đến mức mọi người thường nhầm lẫn họ.)","Although they grew up together, their opinions on politics are not [alike]. (=Dịch: Mặc dù lớn lên cùng nhau, quan điểm của họ về chính trị lại không giống nhau.)","The houses on this street are built almost completely [alike]. (=Dịch: Những ngôi nhà trên con phố này được xây dựng gần như hoàn toàn giống nhau.)"],"ukAudio":"/ai_services/tts3/?q=alike&lang=en-GB&ipa=%2F%C9%99%CB%88la%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=alike&lang=en-US&ipa=%2F%C9%99%CB%88la%C9%AAk%2F"},{"id":"lv_4_7","topic":"Cultural and Historical Exchange","word":"alley","pos":"(n)","ipa":"/ˈæl.i/","defVi":"con hẻm, ngõ nhỏ","defEn":"a narrow road or path between buildings","examples":["The children were playing football in the narrow [alley]. (=Dịch: Lũ trẻ đang chơi bóng đá trong con hẻm nhỏ hẹp.)","He parked his bicycle in a dark [alley] behind the restaurant. (=Dịch: Anh ấy đã đỗ xe đạp trong một con ngõ tối phía sau nhà hàng.)","A small [alley] connects the two main shopping streets. (=Dịch: Một con hẻm nhỏ nối liền hai con phố mua sắm chính.)"],"ukAudio":"/ai_services/tts3/?q=alley&lang=en-GB&ipa=%2F%CB%88%C3%A6l.i%2F","usAudio":"/ai_services/tts3/?q=alley&lang=en-US&ipa=%2F%CB%88%C3%A6l.i%2F"},{"id":"lv_4_8","topic":"Cultural and Historical Exchange","word":"aloud","pos":"(adv)","ipa":"/əˈlaʊd/","defVi":"thành tiếng, to","defEn":"in a voice that other people can hear","examples":["The teacher asked the student to read the passage [aloud]. (=Dịch: Giáo viên đã yêu cầu học sinh đọc to đoạn văn.)","He laughed [aloud] when he heard the unexpected joke. (=Dịch: Anh ấy đã cười thành tiếng khi nghe câu chuyện đùa bất ngờ.)","She wondered [aloud] whether it would rain later in the afternoon. (=Dịch: Cô ấy thắc mắc thành lời rằng liệu chiều nay trời có mưa không.)"],"ukAudio":"/ai_services/tts3/?q=aloud&lang=en-GB&ipa=%2F%C9%99%CB%88la%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=aloud&lang=en-US&ipa=%2F%C9%99%CB%88la%CA%8Ad%2F"},{"id":"lv_4_9","topic":"Cultural and Historical Exchange","word":"altitude","pos":"(n)","ipa":"/ˈæl.tə.tuːd/","defVi":"độ cao so với mực nước biển","defEn":"the height of an object or point in relation to sea level or ground level","examples":["The plane was flying at an [altitude] of 10,000 meters. (=Dịch: Chiếc máy bay đang bay ở độ cao 10.000 mét.)","Some climbers suffer from breathing problems at high [altitude]. (=Dịch: Một số người leo núi gặp vấn đề về hô hấp ở độ cao lớn.)","Vegetation becomes sparse as the [altitude] increases. (=Dịch: Thảm thực vật trở nên thưa thớt khi độ cao tăng lên.)"],"ukAudio":"/ai_services/tts3/?q=altitude&lang=en-GB&ipa=%2F%CB%88%C3%A6l.t%C9%99.tu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=altitude&lang=en-US&ipa=%2F%CB%88%C3%A6l.t%C9%99.tu%CB%90d%2F"},{"id":"lv_4_10","topic":"Cultural and Historical Exchange","word":"alzheimer's disease","pos":"(n)","ipa":"/ˈɑːlts.haɪ.mɚz dɪˌziz/","defVi":"bệnh Alzheimer (chứng sa sút trí tuệ)","defEn":"a progressive brain disorder that slowly destroys memory and thinking skills","examples":["Early diagnosis of [Alzheimer's disease] can help patients manage symptoms more effectively. (=Dịch: Chẩn đoán sớm bệnh Alzheimer có thể giúp người bệnh kiểm soát các triệu chứng hiệu quả hơn.)","Scientists are conducting extensive research to find a cure for [Alzheimer's disease]. (=Dịch: Các nhà khoa học đang tiến hành nghiên cứu sâu rộng để tìm ra phương pháp chữa trị bệnh Alzheimer.)","Caring for a relative with [Alzheimer's disease] requires immense patience and emotional support. (=Dịch: Việc chăm sóc một người thân mắc bệnh Alzheimer đòi hỏi sự kiên nhẫn vô cùng lớn và sự hỗ trợ về mặt tinh thần.)"],"ukAudio":"/ai_services/tts3/?q=alzheimer%27s+disease&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90lts.ha%C9%AA.m%C9%9Az+d%C9%AA%CB%8Cziz%2F","usAudio":"/ai_services/tts3/?q=alzheimer%27s+disease&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90lts.ha%C9%AA.m%C9%9Az+d%C9%AA%CB%8Cziz%2F"},{"id":"lv_4_11","topic":"Cultural and Historical Exchange","word":"ancestor","pos":"(n)","ipa":"/ˈæn.ses.tɚ/","defVi":"tổ tiên","defEn":"a person related to you who lived a long time ago","examples":["Her [ancestor] came to America from Ireland in the nineteenth century. (=Dịch: Tổ tiên của cô ấy đã đến Mỹ từ Ireland vào thế kỷ 19.)","Many ancient cultures held ceremonies to honor every [ancestor] in their family line. (=Dịch: Nhiều nền văn hóa cổ đại đã tổ chức các nghi lễ để tôn vinh từng tổ tiên trong dòng dõi gia đình của họ.)","Scientists can trace the common [ancestor] of modern birds back to dinosaurs. (=Dịch: Các nhà khoa học có thể lần theo tổ tiên chung của các loài chim hiện đại bắt nguồn từ khủng long.)"],"ukAudio":"/ai_services/tts3/?q=ancestor&lang=en-GB&ipa=%2F%CB%88%C3%A6n.ses.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ancestor&lang=en-US&ipa=%2F%CB%88%C3%A6n.ses.t%C9%9A%2F"},{"id":"lv_4_12","topic":"Cultural and Historical Exchange","word":"angle","pos":"(n)","ipa":"/ˈæŋ.ɡəl/","defVi":"góc, góc độ","defEn":"the space between two intersecting lines, or a particular way of looking at something","examples":["The photographer took the picture from a low [angle]. (=Dịch: Nhiếp ảnh gia đã chụp bức ảnh từ một góc máy thấp.)","A square has four corners that meet at a right [angle]. (=Dịch: Hình vuông có bốn góc gặp nhau tạo thành góc vuông.)","Let's consider the problem from a different [angle]. (=Dịch: Chúng ta hãy xem xét vấn đề này từ một góc độ khác.)"],"ukAudio":"/ai_services/tts3/?q=angle&lang=en-GB&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=angle&lang=en-US&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F"},{"id":"lv_4_13","topic":"Cultural and Historical Exchange","word":"anxiety","pos":"(n)","ipa":"/æŋˈzaɪ.ə.ti/","defVi":"sự lo âu, mối lo ngại","defEn":"an uncomfortable feeling of nervousness or worry about something that might happen","examples":["Waiting for the exam results caused her a lot of [anxiety]. (=Dịch: Việc chờ đợi kết quả thi đã khiến cô ấy vô cùng lo lắng.)","Deep breathing exercises can help reduce stress and [anxiety]. (=Dịch: Các bài tập hít thở sâu có thể giúp giảm căng thẳng và lo âu.)","There is growing public [anxiety] over rising fuel prices. (=Dịch: Dư luận ngày càng lo ngại về tình trạng giá nhiên liệu tăng cao.)"],"ukAudio":"/ai_services/tts3/?q=anxiety&lang=en-GB&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.ti%2F","usAudio":"/ai_services/tts3/?q=anxiety&lang=en-US&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.ti%2F"},{"id":"lv_4_14","topic":"Cultural and Historical Exchange","word":"apron","pos":"(n)","ipa":"/ˈeɪ.prən/","defVi":"tạp dề","defEn":"a piece of clothing worn over the front of the body to keep clothes clean while cooking or working","examples":["She tied a cotton [apron] around her waist before preparing dinner. (=Dịch: Cô ấy buộc một chiếc tạp dề cotton quanh eo trước khi chuẩn bị bữa tối.)","The chef wore a clean white [apron] in the kitchen. (=Dịch: Người đầu bếp đeo một chiếc tạp dề trắng sạch sẽ trong bếp.)","He wiped his floury hands on his [apron] while baking bread. (=Dịch: Anh ấy lau đôi tay dính đầy bột vào tạp dề trong khi nướng bánh mì.)"],"ukAudio":"/ai_services/tts3/?q=apron&lang=en-GB&ipa=%2F%CB%88e%C9%AA.pr%C9%99n%2F","usAudio":"/ai_services/tts3/?q=apron&lang=en-US&ipa=%2F%CB%88e%C9%AA.pr%C9%99n%2F"},{"id":"lv_4_15","topic":"Cultural and Historical Exchange","word":"arab","pos":"(adj)","ipa":"/ˈær.əb/","defVi":"(thuộc) người Ả Rập hoặc các nước Ả Rập","defEn":"relating to the Arabic-speaking people or countries of the Middle East and North Africa","examples":["They are studying the history of the [Arab] world in the medieval era. (=Dịch: Họ đang nghiên cứu lịch sử của thế giới Ả Rập trong thời kỳ trung cổ.)","Traditional [Arab] hospitality is well known around the world. (=Dịch: Lòng hiếu khách truyền thống của người Ả Rập rất nổi tiếng trên toàn thế giới.)","Several [Arab] nations participated in the international trade conference. (=Dịch: Một số quốc gia Ả Rập đã tham gia hội nghị thương mại quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=arab&lang=en-GB&ipa=%2F%CB%88%C3%A6r.%C9%99b%2F","usAudio":"/ai_services/tts3/?q=arab&lang=en-US&ipa=%2F%CB%88%C3%A6r.%C9%99b%2F"},{"id":"lv_4_16","topic":"Cultural and Historical Exchange","word":"archaeologist","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒɪst/","defVi":"nhà khảo cổ học","defEn":"a scientist who studies human history by digging up old buildings and objects","examples":["The [archaeologist] discovered ancient pottery during the excavation. (=Dịch: Nhà khảo cổ học đã phát hiện ra đồ gốm cổ trong quá trình khai quật.)","A team of [archaeologist] specialists is exploring the lost city. (=Dịch: Một nhóm chuyên gia khảo cổ học đang khám phá thành phố bị lãng quên.)","The [archaeologist] carefully brushed dirt away from the fragile bone. (=Dịch: Nhà khảo cổ học cẩn thận quét sạch bụi đất khỏi khúc xương mỏng manh.)"],"ukAudio":"/ai_services/tts3/?q=archaeologist&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=archaeologist&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F"},{"id":"lv_4_17","topic":"Cultural and Historical Exchange","word":"archaeology","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒi/","defVi":"khảo cổ học","defEn":"the study of human history and prehistory through the excavation of sites and artifacts","examples":["She decided to study [archaeology] at university to uncover ancient civilizations. (=Dịch: Cô quyết định theo học ngành khảo cổ học tại trường đại học để khám phá các nền văn minh cổ đại.)","Recent advances in technology have revolutionized modern [archaeology]. (=Dịch: Những tiến bộ gần đây trong công nghệ đã tạo ra một cuộc cách mạng cho ngành khảo cổ học hiện đại.)","The team used aerial photography to assist their work in [archaeology]. (=Dịch: Nhóm nghiên cứu đã sử dụng kỹ thuật chụp ảnh từ trên không để hỗ trợ công việc khảo cổ học của họ.)"],"ukAudio":"/ai_services/tts3/?q=archaeology&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=archaeology&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_4_18","topic":"Cultural and Historical Exchange","word":"arena","pos":"(n)","ipa":"/əˈriː.nə/","defVi":"đấu trường, nhà thi đấu; vũ đài/lĩnh vực hoạt động","defEn":"a large enclosed area used for sports, concerts, or other public events; an area of activity","examples":["Thousands of fans gathered in the sports [arena] to watch the game. (=Dịch: Hàng nghìn người hâm mộ đã tụ tập tại nhà thi đấu thể thao để theo dõi trận đấu.)","The rock band will perform at a famous indoor [arena] tonight. (=Dịch: Ban nhạc rock sẽ biểu diễn tại một nhà thi đấu trong nhà nổi tiếng vào tối nay.)","He decided to enter the political [arena] after years in business. (=Dịch: Ông ấy quyết định bước vào chính trường sau nhiều năm làm kinh doanh.)"],"ukAudio":"/ai_services/tts3/?q=arena&lang=en-GB&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=arena&lang=en-US&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F"},{"id":"lv_4_19","topic":"Cultural and Historical Exchange","word":"artefact","pos":"(n)","ipa":"/ˈɑːr.t̬ə.fækt/","defVi":"cổ vật, đồ tạo tác","defEn":"an object made by a human being, typically of historical or cultural interest","examples":["The museum displays an ancient Egyptian [artefact] discovered in a tomb. (=Dịch: Bảo tàng trưng bày một cổ vật Ai Cập cổ đại được phát hiện trong một lăng mộ.)","Archaeologists carefully cleaned the ceramic [artefact] found at the dig site. (=Dịch: Các nhà khảo cổ học đã cẩn thận làm sạch món đồ tạo tác bằng gốm được tìm thấy tại địa điểm khai quật.)","Each bronze [artefact] provides valuable clues about how early humans lived. (=Dịch: Mỗi hiện vật bằng đồng đều cung cấp những manh mối quý giá về cách người tiền sử sinh sống.)"],"ukAudio":"/ai_services/tts3/?q=artefact&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90r.t%CC%AC%C9%99.f%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=artefact&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90r.t%CC%AC%C9%99.f%C3%A6kt%2F"},{"id":"lv_4_20","topic":"Cultural and Historical Exchange","word":"artistic","pos":"(adj)","ipa":"/ɑːrˈtɪs.tɪk/","defVi":"(thuộc) nghệ thuật; có khiếu thẩm mỹ","defEn":"connected with art or showing skill in creating art","examples":["She has exceptional [artistic] talent and loves painting landscapes. (=Dịch: Cô ấy có tài năng nghệ thuật đặc biệt và rất thích vẽ tranh phong cảnh.)","The movie was praised more for its [artistic] value than its commercial success. (=Dịch: Bộ phim được ca ngợi nhiều hơn về giá trị nghệ thuật hơn là thành công về mặt thương mại.)","He made an [artistic] decision to shoot the entire film in black and white. (=Dịch: Anh ấy đã đưa ra một quyết định mang tính nghệ thuật khi quay toàn bộ bộ phim bằng hai màu đen trắng.)"],"ukAudio":"/ai_services/tts3/?q=artistic&lang=en-GB&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=artistic&lang=en-US&ipa=%2F%C9%91%CB%90r%CB%88t%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_21","topic":"Cultural and Historical Exchange","word":"artwork","pos":"(n)","ipa":"/ˈɑːrt.wɜːrk/","defVi":"tác phẩm nghệ thuật","defEn":"paintings, sculptures, or other artistic objects created for exhibition or appreciation","examples":["The gallery exhibits original [artwork] by local contemporary artists. (=Dịch: Phòng trưng bày triển lãm các tác phẩm nghệ thuật nguyên bản của các nghệ sĩ đương đại địa phương.)","Direct sunlight can cause severe damage to delicate [artwork]. (=Dịch: Ánh nắng trực tiếp có thể gây hư hại nghiêm trọng cho các tác phẩm nghệ thuật tinh xảo.)","The school cafeteria was decorated with colorful student [artwork]. (=Dịch: Nhà ăn của trường được trang trí bằng các tác phẩm nghệ thuật đầy màu sắc của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=artwork&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90rt.w%C9%9C%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=artwork&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90rt.w%C9%9C%CB%90rk%2F"},{"id":"lv_4_22","topic":"Cultural and Historical Exchange","word":"ash","pos":"(n)","ipa":"/æʃ/","defVi":"tro, tàn tro","defEn":"the grey or black powder that remains after something has burned","examples":["The volcano erupted, covering the surrounding towns in thick [ash]. (=Dịch: Núi lửa phun trào, phủ một lớp tro dày đặc lên các thị trấn xung quanh.)","He cleared the cold [ash] from the fireplace before lighting a new fire. (=Dịch: Anh ấy đã dọn sạch tàn tro nguội khỏi lò sưởi trước khi nhóm ngọn lửa mới.)","The forest fire reduced hundreds of ancient trees to [ash]. (=Dịch: Vụ cháy rừng đã thiêu rụi hàng trăm cây cổ thụ thành tro bụi.)"],"ukAudio":"/ai_services/tts3/?q=ash&lang=en-GB&ipa=%2F%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=ash&lang=en-US&ipa=%2F%C3%A6%CA%83%2F"},{"id":"lv_4_23","topic":"Cultural and Historical Exchange","word":"association","pos":"(n)","ipa":"/əˌsoʊ.siˈeɪ.ʃən/","defVi":"hiệp hội, tổ chức; sự liên kết, mối liên tưởng","defEn":"an official group of people organized for a particular purpose; a connection between ideas","examples":["He joined the local football [association] to improve his refereeing skills. (=Dịch: Anh ấy đã tham gia hiệp hội bóng đá địa phương để nâng cao kỹ năng trọng tài của mình.)","The research showed a clear [association] between poor diet and heart disease. (=Dịch: Nghiên cứu đã chỉ ra mối liên hệ rõ ràng giữa chế độ ăn uống kém và bệnh tim.)","The medical [association] published new safety guidelines for hospitals. (=Dịch: Hiệp hội y khoa đã công bố các hướng dẫn an toàn mới cho các bệnh viện.)"],"ukAudio":"/ai_services/tts3/?q=association&lang=en-GB&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=association&lang=en-US&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_24","topic":"Cultural and Historical Exchange","word":"atmospheric","pos":"(adj)","ipa":"/ˌæt.məsˈfer.ɪk/","defVi":"mang lại bầu không khí đặc biệt (huyền ảo, ấm cúng); thuộc về khí quyển","defEn":"creating an exciting, mysterious, or pleasant mood; relating to the earth's atmosphere","examples":["The dimly lit restaurant created a very [atmospheric] dining experience. (=Dịch: Nhà hàng với ánh sáng mờ ảo đã tạo nên một trải nghiệm dùng bữa vô cùng giàu bầu không khí và ấn tượng.)","Scientists are studying [atmospheric] pollution to understand climate change better. (=Dịch: Các nhà khoa học đang nghiên cứu về ô nhiễm khí quyển để hiểu rõ hơn về biến đổi khí hậu.)","The old castle looked particularly [atmospheric] on a foggy autumn morning. (=Dịch: Tòa lâu đài cổ kính trông đặc biệt huyền ảo và lôi cuốn vào một buổi sáng mùa thu nhiều sương mù.)"],"ukAudio":"/ai_services/tts3/?q=atmospheric&lang=en-GB&ipa=%2F%CB%8C%C3%A6t.m%C9%99s%CB%88fer.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=atmospheric&lang=en-US&ipa=%2F%CB%8C%C3%A6t.m%C9%99s%CB%88fer.%C9%AAk%2F"},{"id":"lv_4_25","topic":"Cultural and Historical Exchange","word":"attraction","pos":"(n)","ipa":"/əˈtræk.ʃən/","defVi":"sức hút, sự hấp dẫn; điểm tham quan","defEn":"a feature or quality that makes something interesting or enjoyable, or a place people visit for pleasure","examples":["The ancient castle is the main tourist [attraction] in the region. (=Dịch: Tòa lâu đài cổ kính là điểm thu hút khách du lịch chính trong khu vực.)","The city offers many cultural [attractions] such as museums and art galleries. (=Dịch: Thành phố mang đến nhiều điểm đến văn hóa hấp dẫn như các viện bảo tàng và phòng trưng bày nghệ thuật.)","Part of the [attraction] of living in a small town is the peaceful atmosphere. (=Dịch: Một phần sức hút của việc sống ở một thị trấn nhỏ là bầu không khí yên bình.)"],"ukAudio":"/ai_services/tts3/?q=attraction&lang=en-GB&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=attraction&lang=en-US&ipa=%2F%C9%99%CB%88tr%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_4_26","topic":"Cultural and Historical Exchange","word":"audio","pos":"(n)","ipa":"/ˈɔ.di.oʊ/","defVi":"âm thanh, bản ghi âm","defEn":"sound that is recorded, transmitted, or reproduced","examples":["The video quality is excellent, but the [audio] is hard to hear. (=Dịch: Chất lượng video rất tuyệt vời, nhưng âm thanh thì khó nghe.)","Students can download the [audio] files to practice their listening skills. (=Dịch: Học sinh có thể tải xuống các tệp âm thanh để luyện tập kỹ năng nghe của mình.)","The podcast offers clear [audio] and engaging discussions on science. (=Dịch: Tập podcast này mang đến âm thanh rõ ràng và các cuộc thảo luận hấp dẫn về khoa học.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%94.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%94.di.o%CA%8A%2F"},{"id":"lv_4_27","topic":"Cultural and Historical Exchange","word":"axe","pos":"(n)","ipa":"/æks/","defVi":"cây rìu","defEn":"a heavy tool with a sharp metal blade used for chopping wood","examples":["He used a sharp [axe] to chop firewood for the cold winter night. (=Dịch: Anh ấy dùng một chiếc rìu sắc bén để bổ củi cho đêm mùa đông lạnh giá.)","The lumberjack carried a heavy [axe] on his shoulder into the forest. (=Dịch: Người tiều phu vác một chiếc rìu nặng trên vai bước vào rừng.)","The firefighter broke down the locked door using a sturdy [axe]. (=Dịch: Người lính cứu hỏa đã phá cánh cửa bị khóa bằng một chiếc rìu chắc chắn.)"],"ukAudio":"/ai_services/tts3/?q=axe&lang=en-GB&ipa=%2F%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=axe&lang=en-US&ipa=%2F%C3%A6ks%2F"},{"id":"lv_4_28","topic":"Cultural and Historical Exchange","word":"basement","pos":"(n)","ipa":"/ˈbeɪs.mənt/","defVi":"tầng hầm","defEn":"a room or floor of a building partly or entirely below ground level","examples":["We converted the [basement] into a home gym. (=Dịch: Chúng tôi đã cải tạo tầng hầm thành một phòng tập thể dục tại nhà.)","Heavy rain caused water to seep into the [basement]. (=Dịch: Mưa lớn đã khiến nước rò rỉ vào tầng hầm.)","The old books are stored in boxes down in the [basement]. (=Dịch: Những cuốn sách cũ được cất trong các thùng dưới tầng hầm.)"],"ukAudio":"/ai_services/tts3/?q=basement&lang=en-GB&ipa=%2F%CB%88be%C9%AAs.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=basement&lang=en-US&ipa=%2F%CB%88be%C9%AAs.m%C9%99nt%2F"},{"id":"lv_4_29","topic":"Cultural and Historical Exchange","word":"basket","pos":"(n)","ipa":"/ˈbæs.kɪt/","defVi":"cái giỏ, cái rổ","defEn":"a container made of woven material, plastic, or wire, used for carrying things","examples":["She placed freshly picked strawberries into a small wicker [basket]. (=Dịch: Cô ấy đặt những quả dâu tây mới hái vào một chiếc giỏ đan bằng liễu gai nhỏ.)","He put his dirty laundry into the [basket] in the bathroom. (=Dịch: Anh ấy cho quần áo bẩn vào giỏ trong phòng tắm.)","You can add items to your online shopping [basket] before checking out. (=Dịch: Bạn có thể thêm các món đồ vào giỏ mua hàng trực tuyến trước khi thanh toán.)"],"ukAudio":"/ai_services/tts3/?q=basket&lang=en-GB&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=basket&lang=en-US&ipa=%2F%CB%88b%C3%A6s.k%C9%AAt%2F"},{"id":"lv_4_30","topic":"Cultural and Historical Exchange","word":"bathing","pos":"(n)","ipa":"/ˈbeɪ.ðɪŋ/","defVi":"việc tắm rửa, sự bơi lội","defEn":"the act of washing the body or swimming in a body of water for pleasure","examples":["In ancient Rome, public [bathing] was an important social activity. (=Dịch: Ở La Mã cổ đại, việc tắm rửa công cộng là một hoạt động xã hội quan trọng.)","The lake is not safe for [bathing] because of strong underwater currents. (=Dịch: Hồ nước này không an toàn để tắm do có các dòng chảy ngầm mạnh.)","A warm [bathing] ritual before bedtime can help improve sleep quality. (=Dịch: Thói quen tắm nước ấm trước khi đi ngủ có thể giúp cải thiện chất lượng giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=bathing&lang=en-GB&ipa=%2F%CB%88be%C9%AA.%C3%B0%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=bathing&lang=en-US&ipa=%2F%CB%88be%C9%AA.%C3%B0%C9%AA%C5%8B%2F"},{"id":"lv_4_31","topic":"Cultural and Historical Exchange","word":"bc","pos":"(adv)","ipa":"/ˌbiː ˈsiː/","defVi":"trước Công nguyên (TCN)","defEn":"abbreviation for 'Before Christ', used to refer to dates before the approximate birth of Jesus Christ","examples":["The ancient temple was constructed around the fifth century [BC]. (=Dịch: Ngôi đền cổ được xây dựng vào khoảng thế kỷ thứ năm trước Công nguyên.)","Historians estimate that the city was founded in 753 [BC]. (=Dịch: Các nhà sử học ước tính rằng thành phố được thành lập vào năm 753 trước Công nguyên.)","Trade routes between the civilizations were already active by 2000 [BC]. (=Dịch: Các tuyến đường thương mại giữa các nền văn minh đã hoạt động tích cực vào năm 2000 trước Công nguyên.)"],"ukAudio":"/ai_services/tts3/?q=bc&lang=en-GB&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F","usAudio":"/ai_services/tts3/?q=bc&lang=en-US&ipa=%2F%CB%8Cbi%CB%90+%CB%88si%CB%90%2F"},{"id":"lv_4_32","topic":"Cultural and Historical Exchange","word":"belief","pos":"(n)","ipa":"/bɪˈlif/","defVi":"niềm tin, tín ngưỡng","defEn":"an acceptance that a statement is true or that something exists","examples":["His strong [belief] in justice motivated him to pursue a career in law. (=Dịch: Niềm tin mãnh liệt vào công lý đã thúc đẩy anh ấy theo đuổi sự nghiệp trong ngành luật.)","It is a widely held [belief] that a balanced diet leads to a healthier life. (=Dịch: Nhiều người tin rằng một chế độ ăn uống cân bằng sẽ mang lại một cuộc sống khỏe mạnh hơn.)","Different cultures have their own set of moral values and religious [belief]. (=Dịch: Các nền văn hóa khác nhau có những hệ giá trị đạo đức và đức tin tôn giáo riêng.)"],"ukAudio":"/ai_services/tts3/?q=belief&lang=en-GB&ipa=%2Fb%C9%AA%CB%88lif%2F","usAudio":"/ai_services/tts3/?q=belief&lang=en-US&ipa=%2Fb%C9%AA%CB%88lif%2F"},{"id":"lv_4_33","topic":"Cultural and Historical Exchange","word":"beneath","pos":"(prep)","ipa":"/bɪˈniːθ/","defVi":"ở bên dưới, dưới","defEn":"in or to a lower position than; directly under","examples":["The cat curled up and fell asleep [beneath] the kitchen table. (=Dịch: Con mèo cuộn tròn và ngủ thiếp đi bên dưới gầm bàn bếp.)","A vast network of tunnels lies [beneath] the bustling streets of the city. (=Dịch: Một mạng lưới đường hầm rộng lớn nằm bên dưới những con phố nhộn nhịp của thành phố.)","She hid the secret letter [beneath] a thick stack of old books. (=Dịch: Cô ấy đã giấu bức thư bí mật bên dưới một chồng sách cũ dày cộm.)"],"ukAudio":"/ai_services/tts3/?q=beneath&lang=en-GB&ipa=%2Fb%C9%AA%CB%88ni%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=beneath&lang=en-US&ipa=%2Fb%C9%AA%CB%88ni%CB%90%CE%B8%2F"},{"id":"lv_4_34","topic":"Cultural and Historical Exchange","word":"bet","pos":"(n)","ipa":"/bɛt/","defVi":"tiền cược, vụ cá cược","defEn":"an agreement to risk money on the unknown result of an event","examples":["He placed a ten-dollar [bet] on his favorite football team. (=Dịch: Anh ấy đã đặt cược mười đô la vào đội bóng đá yêu thích của mình.)","Winning the [bet] gave him enough money to pay for dinner. (=Dịch: Thắng cược đã giúp anh ấy có đủ tiền để trả cho bữa tối.)","They made a friendly [bet] on who could finish the race first. (=Dịch: Họ đã cá cược vui xem ai có thể về đích trước.)"],"ukAudio":"/ai_services/tts3/?q=bet&lang=en-GB&ipa=%2Fb%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=bet&lang=en-US&ipa=%2Fb%C9%9Bt%2F"},{"id":"lv_4_35","topic":"Cultural and Historical Exchange","word":"bicentennial","pos":"(n)","ipa":"/ˌbaɪ.sɛnˈtɛn.i.əl/","defVi":"lễ kỷ niệm hai trăm năm","defEn":"the two-hundredth anniversary of a significant event, or its celebration","examples":["The city planned a massive parade to mark its [bicentennial] celebration. (=Dịch: Thành phố đã lên kế hoạch cho một cuộc diễu hành lớn để đánh dấu lễ kỷ niệm 200 năm thành lập.)","A commemorative coin was issued for the nation's [bicentennial]. (=Dịch: Một đồng xu kỷ niệm đã được phát hành nhân dịp lễ kỷ niệm 200 năm của quốc gia.)","Historians gathered to discuss the historical milestones leading up to the [bicentennial]. (=Dịch: Các nhà sử học đã tập hợp để thảo luận về những cột mốc lịch sử dẫn đến lễ kỷ niệm 200 năm.)"],"ukAudio":"/ai_services/tts3/?q=bicentennial&lang=en-GB&ipa=%2F%CB%8Cba%C9%AA.s%C9%9Bn%CB%88t%C9%9Bn.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=bicentennial&lang=en-US&ipa=%2F%CB%8Cba%C9%AA.s%C9%9Bn%CB%88t%C9%9Bn.i.%C9%99l%2F"},{"id":"lv_4_36","topic":"Cultural and Historical Exchange","word":"bizarre","pos":"(adj)","ipa":"/bɪˈzɑːr/","defVi":"kỳ quái, kỳ lạ","defEn":"very strange or unusual","examples":["She wore a [bizarre] outfit to the party that made everyone stare. (=Dịch: Cô ấy đã mặc một bộ trang phục kỳ quặc đến bữa tiệc khiến mọi người phải nhìn chằm chằm.)","He had a [bizarre] dream about flying fish last night. (=Dịch: Đêm qua anh ấy đã có một giấc mơ kỳ lạ về những con cá biết bay.)","The police were baffled by the suspect's [bizarre] behavior during questioning. (=Dịch: Cảnh sát đã bối rối trước hành vi kỳ quặc của nghi phạm trong suốt quá trình thẩm vấn.)"],"ukAudio":"/ai_services/tts3/?q=bizarre&lang=en-GB&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=bizarre&lang=en-US&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F"},{"id":"lv_4_37","topic":"Cultural and Historical Exchange","word":"bleak","pos":"(adj)","ipa":"/bliːk/","defVi":"ảm đạm, hoang vắng, u ám","defEn":"cold, empty, and not welcoming; offering little or no hope","examples":["The winter landscape looked [bleak] and deserted under the grey clouds. (=Dịch: Khung cảnh mùa đông trông ảm đạm và hoang vắng dưới những đám mây xám xịt.)","The economic outlook for the upcoming year remains rather [bleak]. (=Dịch: Triển vọng kinh tế cho năm sắp tới vẫn còn khá ảm đạm.)","Without proper qualifications, his chances of finding a job are [bleak]. (=Dịch: Nếu không có trình độ chuyên môn phù hợp, cơ hội tìm việc của anh ấy là vô cùng mờ mịt.)"],"ukAudio":"/ai_services/tts3/?q=bleak&lang=en-GB&ipa=%2Fbli%CB%90k%2F","usAudio":"/ai_services/tts3/?q=bleak&lang=en-US&ipa=%2Fbli%CB%90k%2F"},{"id":"lv_4_38","topic":"Cultural and Historical Exchange","word":"bog","pos":"(n)","ipa":"/bɑːɡ/","defVi":"đầm lầy, bãi than bùn","defEn":"an area of soft, wet, muddy ground that is difficult to walk on","examples":["The rare bird species builds its nests in the remote wetlands of the peat [bog]. (=Dịch: Loài chim quý hiếm làm tổ ở những vùng đất ngập nước hẻo lánh của đầm lầy than bùn.)","Heavy machinery sank into the muddy [bog] and had to be pulled out with cables. (=Dịch: Máy móc hạng nặng bị chìm vào đầm lầy bùn lầy và phải được kéo ra bằng dây cáp.)","Scientists analyze ancient plant remains preserved in the acidic layers of the [bog]. (=Dịch: Các nhà khoa học phân tích tàn tích thực vật cổ đại được bảo tồn trong các lớp đất có tính axit của đầm lầy.)"],"ukAudio":"/ai_services/tts3/?q=bog&lang=en-GB&ipa=%2Fb%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=bog&lang=en-US&ipa=%2Fb%C9%91%CB%90%C9%A1%2F"},{"id":"lv_4_39","topic":"Cultural and Historical Exchange","word":"bookshop","pos":"(n)","ipa":"/ˈbʊk.ʃɑːp/","defVi":"hiệu sách, tiệm sách","defEn":"a shop that sells books","examples":["I spent hours browsing through old novels in the local [bookshop]. (=Dịch: Tôi đã dành hàng giờ để tìm đọc những cuốn tiểu thuyết cũ trong hiệu sách địa phương.)","The university [bookshop] offers a discount on required textbooks. (=Dịch: Hiệu sách của trường đại học giảm giá cho các sách giáo trình bắt buộc.)","A cozy [bookshop] recently opened around the corner from our school. (=Dịch: Một hiệu sách ấm cúng vừa mới mở ngay góc phố gần trường học của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=bookshop&lang=en-GB&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F","usAudio":"/ai_services/tts3/?q=bookshop&lang=en-US&ipa=%2F%CB%88b%CA%8Ak.%CA%83%C9%91%CB%90p%2F"},{"id":"lv_4_40","topic":"Cultural and Historical Exchange","word":"brazil","pos":"(n)","ipa":"/brəˈzɪl/","defVi":"nước Bra-xin (quốc gia ở Nam Mỹ)","defEn":"the largest country in South America, known for the Amazon Rainforest and vibrant culture","examples":["[Brazil] is the world's largest producer and exporter of coffee. (=Dịch: Brazil là quốc gia sản xuất và xuất khẩu cà phê lớn nhất thế giới.)","Thousands of tourists travel to [Brazil] every year to experience the Rio Carnival. (=Dịch: Hàng ngàn du khách đến Brazil mỗi năm để trải nghiệm Lễ hội hóa trang Rio Carnival.)","A large portion of the Amazon rainforest is located within [Brazil]. (=Dịch: Phần lớn rừng nhiệt đới Amazon nằm trong lãnh thổ Brazil.)"],"ukAudio":"/ai_services/tts3/?q=brazil&lang=en-GB&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=brazil&lang=en-US&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F"},{"id":"lv_4_41","topic":"Cultural and Historical Exchange","word":"breathe","pos":"(v)","ipa":"/brið/","defVi":"thở, hít thở","defEn":"to take air into the lungs and expel it again","examples":["It is important to [breathe] deeply when you feel stressed or anxious. (=Dịch: Điều quan trọng là phải hít thở sâu khi bạn cảm thấy căng thẳng hoặc lo âu.)","He could hardly [breathe] after running up five flights of stairs. (=Dịch: Anh ấy gần như không thể thở nổi sau khi chạy lên năm tầng cầu thang.)","The doctor told the patient to [breathe] normally during the examination. (=Dịch: Bác sĩ bảo bệnh nhân thở bình thường trong quá trình thăm khám.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2Fbri%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2Fbri%C3%B0%2F"},{"id":"lv_4_42","topic":"Cultural and Historical Exchange","word":"broadcaster","pos":"(n)","ipa":"/ˈbrɔd.kæs.tɚ/","defVi":"phát thanh viên, đài truyền hình/phát thanh","defEn":"a person or company that transmits radio or television programs","examples":["The national [broadcaster] announced changes to its evening schedule. (=Dịch: Đài truyền hình quốc gia đã thông báo những thay đổi đối với lịch phát sóng buổi tối.)","She started her career as a sports [broadcaster] for a local radio station. (=Dịch: Cô bắt đầu sự nghiệp của mình với tư cách là một phát thanh viên thể thao cho một đài phát thanh địa phương.)","Several international [broadcaster] organizations covered the global summit. (=Dịch: Một số tổ chức phát thanh truyền hình quốc tế đã đưa tin về hội nghị thượng đỉnh toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=broadcaster&lang=en-GB&ipa=%2F%CB%88br%C9%94d.k%C3%A6s.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=broadcaster&lang=en-US&ipa=%2F%CB%88br%C9%94d.k%C3%A6s.t%C9%9A%2F"},{"id":"lv_4_43","topic":"Cultural and Historical Exchange","word":"bury","pos":"(v)","ipa":"/ˈber.i/","defVi":"chôn cất, vùi lấp","defEn":"to place something in the ground and cover it with earth","examples":["Pirates used to [bury] their stolen treasure on remote islands. (=Dịch: Những tên cướp biển từng chôn giấu kho báu đánh cắp được trên các hòn đảo xa xôi.)","The winter storm managed to [bury] the entire town under two feet of snow. (=Dịch: Cơn bão mùa đông đã vùi lấp cả thị trấn dưới hai foot tuyết.)","When feeling stressed, she prefers to [bury] herself in work to stay focused. (=Dịch: Khi cảm thấy căng thẳng, cô ấy muốn vùi mình vào công việc để giữ sự tập trung.)"],"ukAudio":"/ai_services/tts3/?q=bury&lang=en-GB&ipa=%2F%CB%88ber.i%2F","usAudio":"/ai_services/tts3/?q=bury&lang=en-US&ipa=%2F%CB%88ber.i%2F"},{"id":"lv_4_44","topic":"Cultural and Historical Exchange","word":"bush","pos":"(n)","ipa":"/bʊʃ/","defVi":"bụi cây, bụi rậm","defEn":"a low, woody plant with many branches, smaller than a tree","examples":["The children were hiding behind a large rose [bush] in the backyard. (=Dịch: Lũ trẻ đang trốn sau một bụi hoa hồng lớn ở sân sau.)","He planted a flowering [bush] near the front gate to brighten the house. (=Dịch: Anh ấy đã trồng một bụi cây có hoa gần cổng trước để làm rạng rỡ ngôi nhà.)","A small bird suddenly flew out from the thorny [bush]. (=Dịch: Một chú chim nhỏ bất ngờ bay ra từ bụi cây đầy gai.)"],"ukAudio":"/ai_services/tts3/?q=bush&lang=en-GB&ipa=%2Fb%CA%8A%CA%83%2F","usAudio":"/ai_services/tts3/?q=bush&lang=en-US&ipa=%2Fb%CA%8A%CA%83%2F"},{"id":"lv_4_45","topic":"Cultural and Historical Exchange","word":"calendar","pos":"(n)","ipa":"/ˈkæl.ən.dɚ/","defVi":"lịch, cuốn lịch","defEn":"a chart or page showing the days, weeks, and months of a particular year","examples":["I marked the date of the interview on my [calendar]. (=Dịch: Tôi đã đánh dấu ngày phỏng vấn trên lịch của mình.)","The academic [calendar] lists all term dates and exam periods. (=Dịch: Lịch học tập liệt kê tất cả các ngày trong học kỳ và các kỳ thi.)","She hung a new wall [calendar] in her office. (=Dịch: Cô ấy đã treo một cuốn lịch tường mới trong văn phòng của mình.)"],"ukAudio":"/ai_services/tts3/?q=calendar&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=calendar&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%99n.d%C9%9A%2F"},{"id":"lv_4_46","topic":"Cultural and Historical Exchange","word":"calm","pos":"(adj)","ipa":"/kɑːm/","defVi":"bình tĩnh, êm đềm","defEn":"peaceful, quiet, and not worried or excited","examples":["Try to stay [calm] during an emergency situation. (=Dịch: Hãy cố gắng giữ bình tĩnh trong các tình huống khẩn cấp.)","The sea was completely [calm] without a single wave. (=Dịch: Biển hoàn toàn êm ả, không có lấy một gợn sóng.)","Her [calm] voice helped reassure the frightened child. (=Dịch: Giọng nói điềm tĩnh của cô đã giúp trấn an đứa trẻ đang sợ hãi.)"],"ukAudio":"/ai_services/tts3/?q=calm&lang=en-GB&ipa=%2Fk%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=calm&lang=en-US&ipa=%2Fk%C9%91%CB%90m%2F"},{"id":"lv_4_47","topic":"Cultural and Historical Exchange","word":"canal","pos":"(n)","ipa":"/kəˈnæl/","defVi":"kênh đào, con kênh","defEn":"an artificial waterway constructed for navigation or irrigation","examples":["The Panama [Canal] significantly reduces the travel time for international cargo ships. (=Dịch: Kênh đào Panama giúp giảm đáng kể thời gian di chuyển của các tàu chở hàng quốc tế.)","Tourists enjoy taking boat tours along the narrow [canals] of the historic city. (=Dịch: Khách du lịch thích thú tham gia các chuyến tham quan bằng thuyền dọc theo những con kênh hẹp của thành phố lịch sử.)","The government built an irrigation [canal] to supply water to dry farmland. (=Dịch: Chính phủ đã xây dựng một con kênh tưới tiêu để cung cấp nước cho vùng đất nông nghiệp khô cằn.)"],"ukAudio":"/ai_services/tts3/?q=canal&lang=en-GB&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=canal&lang=en-US&ipa=%2Fk%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_4_48","topic":"Cultural and Historical Exchange","word":"capitalism","pos":"(n)","ipa":"/ˈkæp.ə.t̬əl.ɪ.zəm/","defVi":"chủ nghĩa tư bản","defEn":"an economic system in which businesses and property are owned by private individuals rather than the state","examples":["Free market [capitalism] encourages competition among private enterprises. (=Dịch: Chủ nghĩa tư bản thị trường tự do khuyến khích sự cạnh tranh giữa các doanh nghiệp tư nhân.)","Critics argue that unchecked [capitalism] can widen the gap between rich and poor. (=Dịch: Các nhà phê bình lập luận rằng chủ nghĩa tư bản không được kiểm soát có thể nới rộng khoảng cách giàu nghèo.)","The Industrial Revolution accelerated the development of global [capitalism]. (=Dịch: Cách mạng Công nghiệp đã đẩy nhanh sự phát triển của chủ nghĩa tư bản toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=capitalism&lang=en-GB&ipa=%2F%CB%88k%C3%A6p.%C9%99.t%CC%AC%C9%99l.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=capitalism&lang=en-US&ipa=%2F%CB%88k%C3%A6p.%C9%99.t%CC%AC%C9%99l.%C9%AA.z%C9%99m%2F"},{"id":"lv_4_49","topic":"Cultural and Historical Exchange","word":"cargo","pos":"(n)","ipa":"/ˈkɑr.ɡoʊ/","defVi":"hàng hóa (chở bằng tàu thủy, máy bay hoặc xe tải)","defEn":"goods carried on a ship, aircraft, or motor vehicle","examples":["The plane was carrying tons of medical [cargo] to the disaster zone. (=Dịch: Chiếc máy bay đang chở hàng tấn hàng hóa y tế đến vùng xảy ra thảm họa.)","Dockworkers worked overnight to unload the container [cargo] from the ship. (=Dịch: Các công nhân cảng đã làm việc xuyên đêm để dỡ các công-ten-nơ hàng hóa khỏi tàu.)","Inspectors checked the ship’s [cargo] for illegal wildlife products. (=Dịch: Các thanh tra đã kiểm tra hàng hóa trên tàu để truy tìm các sản phẩm động vật hoang dã bất hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=cargo&lang=en-GB&ipa=%2F%CB%88k%C9%91r.%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=cargo&lang=en-US&ipa=%2F%CB%88k%C9%91r.%C9%A1o%CA%8A%2F"},{"id":"lv_4_50","topic":"Cultural and Historical Exchange","word":"caribbean","pos":"(n)","ipa":"/ˌkɛr.əˈbi.ən/","defVi":"vùng biển Ca-ri-bê","defEn":"a region consisting of the Caribbean Sea and its surrounding islands","examples":["Many tourists travel to the [Caribbean] for its warm climate and beaches. (=Dịch: Nhiều du khách đến vùng Caribe vì khí hậu ấm áp và các bãi biển đẹp.)","The cultural heritage of the [Caribbean] blends African, European, and Indigenous traditions. (=Dịch: Di sản văn hóa của vùng Caribe pha trộn giữa các truyền thống châu Phi, châu Âu và bản địa.)","Severe hurricanes often threaten island communities across the [Caribbean] each autumn. (=Dịch: Những cơn bão dữ dội thường đe dọa các cộng đồng trên đảo khắp vùng Caribe vào mỗi mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=caribbean&lang=en-GB&ipa=%2F%CB%8Ck%C9%9Br.%C9%99%CB%88bi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=caribbean&lang=en-US&ipa=%2F%CB%8Ck%C9%9Br.%C9%99%CB%88bi.%C9%99n%2F"},{"id":"lv_4_51","topic":"Cultural and Historical Exchange","word":"carnival","pos":"(n)","ipa":"/ˈkɑːr.nə.vəl/","defVi":"lễ hội hóa trang, ngày hội","defEn":"a public festival featuring music, dancing, and colorful costumes","examples":["Rio de Janeiro is world-famous for its annual vibrant [carnival]. (=Dịch: Rio de Janeiro nổi tiếng thế giới với lễ hội hóa trang rực rỡ thường niên.)","Children enjoyed dressing up in costumes for the school [carnival]. (=Dịch: Trẻ em thích thú mặc trang phục hóa trang cho ngày hội hóa trang của trường.)","Dancers practiced for months to prepare their routines for the street [carnival]. (=Dịch: Các vũ công đã luyện tập trong nhiều tháng để chuẩn bị cho các tiết mục biểu diễn tại lễ hội đường phố.)"],"ukAudio":"/ai_services/tts3/?q=carnival&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.n%C9%99.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=carnival&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.n%C9%99.v%C9%99l%2F"},{"id":"lv_4_52","topic":"Cultural and Historical Exchange","word":"carve","pos":"(v)","ipa":"/kɑːrv/","defVi":"khắc, chạm khắc, tạc","defEn":"to cut a hard material such as wood or stone into a specific shape","examples":["Local artisans [carve] beautiful statues from solid blocks of wood. (=Dịch: Các nghệ nhân địa phương chạm khắc những bức tượng tuyệt đẹp từ các khối gỗ nguyên khối.)","Tourists often [carve] their initials onto the historic wooden benches. (=Dịch: Khách du lịch thường khắc tên viết tắt của họ lên những chiếc ghế gỗ lịch sử.)","The chef will carefully [carve] the roasted turkey for dinner. (=Dịch: Bếp trưởng sẽ cẩn thận cắt thịt gà tây quay cho bữa tối.)"],"ukAudio":"/ai_services/tts3/?q=carve&lang=en-GB&ipa=%2Fk%C9%91%CB%90rv%2F","usAudio":"/ai_services/tts3/?q=carve&lang=en-US&ipa=%2Fk%C9%91%CB%90rv%2F"},{"id":"lv_4_53","topic":"Cultural and Historical Exchange","word":"carving","pos":"(n)","ipa":"/ˈkɑːr.vɪŋ/","defVi":"tác phẩm điêu khắc, họa tiết chạm khắc","defEn":"an object or design made by cutting away material from wood or stone","examples":["The museum displays an intricate wooden [carving] from the nineteenth century. (=Dịch: Bảo tàng trưng bày một tác phẩm chạm khắc gỗ tinh xảo từ thế kỷ thứ mười chín.)","Ancient stone [carvings] were discovered on the walls of the cave. (=Dịch: Những bức chạm khắc đá cổ đại đã được phát hiện trên các vách hang động.)","He bought a small jade [carving] as a souvenir during his trip. (=Dịch: Anh ấy đã mua một bức tượng ngọc điêu khắc nhỏ làm quà lưu niệm trong chuyến đi của mình.)"],"ukAudio":"/ai_services/tts3/?q=carving&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=carving&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.v%C9%AA%C5%8B%2F"},{"id":"lv_4_54","topic":"Cultural and Historical Exchange","word":"category","pos":"(n)","ipa":"/ˈkæt̬.ə.ɡɔːr.i/","defVi":"hạng, loại, danh mục","defEn":"a group of people or things that share similar characteristics","examples":["The books in the library are divided into different [category] sections. (=Dịch: Sách trong thư viện được chia thành các khu vực theo thể loại khác nhau.)","Her movie won the best picture [category] at the annual film awards. (=Dịch: Bộ phim của cô đã chiến thắng ở hạng mục phim hay nhất tại lễ trao giải điện ảnh thường niên.)","Applicants are placed into a specific [category] based on their work experience. (=Dịch: Các ứng viên được xếp vào một nhóm cụ thể dựa trên kinh nghiệm làm việc của họ.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_4_55","topic":"Cultural and Historical Exchange","word":"cattle","pos":"(n)","ipa":"/ˈkæt.əl/","defVi":"gia súc (bò, trâu)","defEn":"cows and bulls kept on a farm for their meat or milk","examples":["The farmer herds his [cattle] into the barn every evening. (=Dịch: Người nông dân lùa đàn gia súc của mình vào chuồng vào mỗi buổi tối.)","Dairy [cattle] require nutritious food to produce high quality milk. (=Dịch: Bò sữa đòi hỏi thức ăn giàu dinh dưỡng để sản xuất ra sữa chất lượng cao.)","A large herd of [cattle] was grazing quietly on the green hill. (=Dịch: Một đàn gia súc lớn đang gặm cỏ yên bình trên ngọn đồi xanh mướt.)"],"ukAudio":"/ai_services/tts3/?q=cattle&lang=en-GB&ipa=%2F%CB%88k%C3%A6t.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cattle&lang=en-US&ipa=%2F%CB%88k%C3%A6t.%C9%99l%2F"},{"id":"lv_4_56","topic":"Cultural and Historical Exchange","word":"cave","pos":"(n)","ipa":"/keɪv/","defVi":"hang động","defEn":"a large natural underground hole or hollow space in the side of a hill or cliff","examples":["The explorers discovered fascinating prehistoric wall paintings deep inside the dark [cave]. (=Dịch: Các nhà thám hiểm đã phát hiện ra những bức tranh tường tiền sử hấp dẫn nằm sâu bên trong hang động tối tăm.)","Hikers sought shelter inside a nearby [cave] when the heavy rainstorm suddenly began. (=Dịch: Những người đi bộ đường dài đã tìm nơi trú ẩn bên trong một hang động gần đó khi cơn bão mưa lớn bất ngờ ập đến.)","This coastal [cave] is only accessible by small boats during low tide. (=Dịch: Hang động ven biển này chỉ có thể tiếp cận bằng thuyền nhỏ khi thủy triều xuống.)"],"ukAudio":"/ai_services/tts3/?q=cave&lang=en-GB&ipa=%2Fke%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cave&lang=en-US&ipa=%2Fke%C9%AAv%2F"},{"id":"lv_4_57","topic":"Cultural and Historical Exchange","word":"celebration","pos":"(n)","ipa":"/ˌsɛl.əˈbreɪ.ʃən/","defVi":"sự kỷ niệm, lễ kỷ niệm, buổi tiệc mừng","defEn":"a special social event or gathering organized to mark an important occasion","examples":["The whole city joined in the [celebration] of the national holiday. (=Dịch: Cả thành phố đã cùng tham gia vào [lễ kỷ niệm] ngày quốc lễ.)","They held a big [celebration] for their parents' wedding anniversary. (=Dịch: Họ đã tổ chức một [bữa tiệc kỷ niệm] lớn nhân dịp kỷ niệm ngày cưới của cha mẹ.)","The football team organized a victory [celebration] after winning the cup. (=Dịch: Đội bóng đá đã tổ chức một [lễ ăn mừng] chiến thắng sau khi giành được cúp vô địch.)"],"ukAudio":"/ai_services/tts3/?q=celebration&lang=en-GB&ipa=%2F%CB%8Cs%C9%9Bl.%C9%99%CB%88bre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=celebration&lang=en-US&ipa=%2F%CB%8Cs%C9%9Bl.%C9%99%CB%88bre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_58","topic":"Cultural and Historical Exchange","word":"ceramic","pos":"(n)","ipa":"/səˈræm.ɪk/","defVi":"gốm sứ, đồ gốm","defEn":"a hard material made by shaping and baking clay at high temperatures","examples":["The museum exhibits a rare collection of ancient [ceramic] vases. (=Dịch: Bảo tàng trưng bày một bộ sưu tập bình gốm cổ quý hiếm.)","She bought a handmade [ceramic] mug at the local craft fair. (=Dịch: Cô ấy đã mua một chiếc cốc gốm thủ công tại hội chợ thủ công mỹ nghệ địa phương.)","Modern engineering uses [ceramic] materials because of their heat resistance. (=Dịch: Kỹ thuật hiện đại sử dụng vật liệu gốm vì khả năng chịu nhiệt của chúng.)"],"ukAudio":"/ai_services/tts3/?q=ceramic&lang=en-GB&ipa=%2Fs%C9%99%CB%88r%C3%A6m.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=ceramic&lang=en-US&ipa=%2Fs%C9%99%CB%88r%C3%A6m.%C9%AAk%2F"},{"id":"lv_4_59","topic":"Cultural and Historical Exchange","word":"cereal","pos":"(n)","ipa":"/ˈsɪr.i.əl/","defVi":"ngũ cốc","defEn":"a grain used for food, such as wheat, oats, or corn, or a breakfast food made from it","examples":["Many people eat a bowl of [cereal] with cold milk for breakfast. (=Dịch: Nhiều người ăn một bát ngũ cốc với sữa lạnh vào bữa sáng.)","Wheat and rice are the most widely grown [cereal] crops in the world. (=Dịch: Lúa mì và lúa gạo là những cây ngũ cốc được trồng rộng rãi nhất trên thế giới.)","He chose a whole-grain [cereal] to maintain a healthier diet. (=Dịch: Anh ấy đã chọn ngũ cốc nguyên hạt để duy trì một chế độ ăn uống lành mạnh hơn.)"],"ukAudio":"/ai_services/tts3/?q=cereal&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cereal&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F"},{"id":"lv_4_60","topic":"Cultural and Historical Exchange","word":"ceremony","pos":"(n)","ipa":"/ˈser.ə.moʊ.ni/","defVi":"nghi lễ, buổi lễ","defEn":"a formal public or religious event with traditional actions","examples":["The graduation [ceremony] will take place in the main hall. (=Dịch: Lễ tốt nghiệp sẽ diễn ra tại hội trường chính.)","They held a traditional wedding [ceremony] in the village. (=Dịch: Họ đã tổ chức một lễ cưới truyền thống ở trong làng.)","The opening [ceremony] of the Olympic Games was breathtaking. (=Dịch: Lễ khai mạc Thế vận hội Olympic thật ngoạn mục.)"],"ukAudio":"/ai_services/tts3/?q=ceremony&lang=en-GB&ipa=%2F%CB%88ser.%C9%99.mo%CA%8A.ni%2F","usAudio":"/ai_services/tts3/?q=ceremony&lang=en-US&ipa=%2F%CB%88ser.%C9%99.mo%CA%8A.ni%2F"},{"id":"lv_4_61","topic":"Cultural and Historical Exchange","word":"characteristic","pos":"(n)","ipa":"/ˌker.ək.təˈrɪs.tɪk/","defVi":"đặc điểm, đặc tính","defEn":"a feature or quality belonging typically to a person, place, or thing and serving to identify it","examples":["Curiosity is an important [characteristic] of a good researcher. (=Dịch: Sự tò mò là một đặc tính quan trọng của một nhà nghiên cứu giỏi.)","Large ears are a distinctive physical [characteristic] of African elephants. (=Dịch: Đôi tai lớn là một đặc điểm thể chất nổi bật của loài voi châu Phi.)","Adaptability is a key [characteristic] needed to thrive in modern workplaces. (=Dịch: Khả năng thích ứng là một đặc điểm then chốt cần có để phát triển trong môi trường làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=characteristic&lang=en-GB&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=characteristic&lang=en-US&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_62","topic":"Cultural and Historical Exchange","word":"chemist","pos":"(n)","ipa":"/ˈkɛm.ɪst/","defVi":"nhà hóa học","defEn":"a scientist who specializes in the study of chemistry","examples":["The research [chemist] developed a new compound to treat infections. (=Dịch: Nhà hóa học nghiên cứu đã phát triển một hợp chất mới để điều trị các bệnh nhiễm trùng.)","Marie Curie was a pioneering [chemist] and physicist who won two Nobel Prizes. (=Dịch: Marie Curie là một nhà hóa học và nhà vật lý tiên phong từng giành hai giải Nobel.)","Every [chemist] in the laboratory must follow strict safety procedures. (=Dịch: Mỗi nhà hóa học trong phòng thí nghiệm đều phải tuân thủ các quy trình an toàn nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=chemist&lang=en-GB&ipa=%2F%CB%88k%C9%9Bm.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=chemist&lang=en-US&ipa=%2F%CB%88k%C9%9Bm.%C9%AAst%2F"},{"id":"lv_4_63","topic":"Cultural and Historical Exchange","word":"chief","pos":"(adj)","ipa":"/tʃiːf/","defVi":"chính, chủ yếu","defEn":"most important; main","examples":["The [chief] reason for his success was his relentless hard work. (=Dịch: Lý do chính cho sự thành công của anh ấy là sự chăm chỉ không ngừng nghỉ.)","Safety is our [chief] concern during this outdoor expedition. (=Dịch: An toàn là mối quan tâm hàng đầu của chúng tôi trong suốt chuyến thám hiểm ngoài trời này.)","Pollution is one of the [chief] threats to marine life today. (=Dịch: Ô nhiễm là một trong những mối đe dọa chính đối với sinh vật biển hiện nay.)"],"ukAudio":"/ai_services/tts3/?q=chief&lang=en-GB&ipa=%2Ft%CA%83i%CB%90f%2F","usAudio":"/ai_services/tts3/?q=chief&lang=en-US&ipa=%2Ft%CA%83i%CB%90f%2F"},{"id":"lv_4_64","topic":"Cultural and Historical Exchange","word":"childhood","pos":"(n)","ipa":"/ˈtʃaɪld.hʊd/","defVi":"thời thơ ấu, tuổi thơ","defEn":"the time or period of being a child","examples":["She spent most of her [childhood] living in a peaceful coastal village. (=Dịch: Cô ấy đã dành phần lớn tuổi thơ của mình sống ở một ngôi làng ven biển yên bình.)","Playing board games with family is one of my fondest [childhood] memories. (=Dịch: Chơi trò chơi bàn cờ cùng gia đình là một trong những kỷ niệm thời thơ ấu đẹp nhất của tôi.)","Poor nutrition during early [childhood] can affect physical growth. (=Dịch: Dinh dưỡng kém trong thời thơ ấu có thể ảnh hưởng đến sự phát triển thể chất.)"],"ukAudio":"/ai_services/tts3/?q=childhood&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.h%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=childhood&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.h%CA%8Ad%2F"},{"id":"lv_4_65","topic":"Cultural and Historical Exchange","word":"china","pos":"(n)","ipa":"/ˈtʃaɪ.nə/","defVi":"Trung Quốc; đồ sứ","defEn":"a large country located in East Asia; (lowercase) cups, plates, and dishes made of porcelain","examples":["Export trade between Vietnam and [China] has grown significantly in recent years. (=Dịch: Hoạt động thương mại xuất khẩu giữa Việt Nam và Trung Quốc đã tăng trưởng đáng kể trong những năm gần đây.)","They decided to travel across [China] by high-speed train. (=Dịch: Họ quyết định đi du lịch xuyên Trung Quốc bằng tàu cao tốc.)","Many international students choose to study Mandarin in [China]. (=Dịch: Nhiều du học sinh quốc tế chọn học tiếng Quan Thoại tại Trung Quốc.)"],"ukAudio":"/ai_services/tts3/?q=china&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=china&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AA.n%C9%99%2F"},{"id":"lv_4_66","topic":"Cultural and Historical Exchange","word":"chinese","pos":"(adj)","ipa":"/ˌtʃaɪˈniːz/","defVi":"thuộc về Trung Quốc, người Trung Quốc hoặc tiếng Trung","defEn":"relating to China, its people, or its language","examples":["She has a deep interest in traditional [Chinese] painting and calligraphy. (=Dịch: Cô ấy có niềm đam mê sâu sắc với hội họa và thư pháp truyền thống Trung Quốc.)","Many students are learning the [Chinese] language for career opportunities. (=Dịch: Nhiều sinh viên đang học tiếng Trung Quốc để tìm kiếm cơ hội nghề nghiệp.)","We enjoyed a delicious meal at a local [Chinese] restaurant. (=Dịch: Chúng tôi đã thưởng thức một bữa ăn ngon miệng tại một nhà hàng Trung Hoa ở địa phương.)"],"ukAudio":"/ai_services/tts3/?q=chinese&lang=en-GB&ipa=%2F%CB%8Ct%CA%83a%C9%AA%CB%88ni%CB%90z%2F","usAudio":"/ai_services/tts3/?q=chinese&lang=en-US&ipa=%2F%CB%8Ct%CA%83a%C9%AA%CB%88ni%CB%90z%2F"},{"id":"lv_4_67","topic":"Cultural and Historical Exchange","word":"circular","pos":"(adj)","ipa":"/ˈsɜːr.kjə.lɚ/","defVi":"hình tròn, vòng quanh","defEn":"having the shape of a circle; round","examples":["The students sat in a [circular] arrangement around the teacher. (=Dịch: Các học sinh đã ngồi theo sự sắp xếp hình tròn xung quanh giáo viên.)","We took a [circular] route through the park and ended up where we started. (=Dịch: Chúng tôi đã đi theo một lộ trình vòng tròn qua công viên và kết thúc tại chính nơi chúng tôi đã bắt đầu.)","The room was illuminated by a large [circular] window on the ceiling. (=Dịch: Căn phòng được chiếu sáng bởi một cửa sổ tròn lớn trên trần nhà.)"],"ukAudio":"/ai_services/tts3/?q=circular&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.kj%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=circular&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.kj%C9%99.l%C9%9A%2F"},{"id":"lv_4_68","topic":"Cultural and Historical Exchange","word":"circus","pos":"(n)","ipa":"/ˈsɜːr.kəs/","defVi":"gánh xiếc, rạp xiếc","defEn":"a traveling show consisting of acrobats, clowns, and trained animals performing in an arena","examples":["The family bought tickets to see the [circus] during the weekend. (=Dịch: Gia đình đã mua vé đi xem xiếc vào cuối tuần.)","Acrobats performed daring stunts at the center of the [circus] tent. (=Dịch: Các nghệ sĩ nhào lộn đã biểu diễn những màn mạo hiểm ở trung tâm rạp xiếc.)","Many modern [circus] shows no longer use wild animals in their acts. (=Dịch: Nhiều chương trình xiếc hiện đại không còn sử dụng động vật hoang dã trong các tiết mục của họ.)"],"ukAudio":"/ai_services/tts3/?q=circus&lang=en-GB&ipa=%2F%CB%88s%C9%9C%CB%90r.k%C9%99s%2F","usAudio":"/ai_services/tts3/?q=circus&lang=en-US&ipa=%2F%CB%88s%C9%9C%CB%90r.k%C9%99s%2F"},{"id":"lv_4_69","topic":"Cultural and Historical Exchange","word":"civilisation","pos":"(n)","ipa":"/ˌsɪv.ə.ləˈzeɪ.ʃən/","defVi":"nền văn minh","defEn":"a human society with its own developed culture, government, and way of life","examples":["Ancient Egyptian [civilisation] flourished along the banks of the Nile River. (=Dịch: Nền văn minh Ai Cập cổ đại đã phát triển hưng thịnh dọc theo hai bờ sông Nile.)","Many historians believe that writing is a cornerstone of modern [civilisation]. (=Dịch: Nhiều nhà sử học tin rằng chữ viết là nền tảng của nền văn minh hiện đại.)","The museum exhibits artifacts from the ancient Maya [civilisation]. (=Dịch: Bảo tàng trưng bày các hiện vật từ nền văn minh Maya cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=civilisation&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAv.%C9%99.l%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=civilisation&lang=en-US&ipa=%2F%CB%8Cs%C9%AAv.%C9%99.l%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_70","topic":"Cultural and Historical Exchange","word":"clay","pos":"(n)","ipa":"/kleɪ/","defVi":"đất sét","defEn":"a heavy, sticky earth that can be moulded when wet and baked hard","examples":["The children enjoyed shaping figures out of soft [clay]. (=Dịch: Lũ trẻ rất thích thú nặn các hình thù từ đất sét mềm.)","Bricks are typically made from dried and baked [clay]. (=Dịch: Gạch thường được làm từ đất sét phơi khô và nung nóng.)","The soil in this garden has too much [clay] for vegetables to grow easily. (=Dịch: Đất trong khu vườn này có quá nhiều đất sét khiến rau củ khó phát triển dễ dàng.)"],"ukAudio":"/ai_services/tts3/?q=clay&lang=en-GB&ipa=%2Fkle%C9%AA%2F","usAudio":"/ai_services/tts3/?q=clay&lang=en-US&ipa=%2Fkle%C9%AA%2F"},{"id":"lv_4_71","topic":"Cultural and Historical Exchange","word":"cleanliness","pos":"(n)","ipa":"/ˈklɛn.li.nəs/","defVi":"sự sạch sẽ, tính sạch sẽ","defEn":"the state or habit of keeping oneself and one's surroundings clean","examples":["The hospital places great importance on strict standards of [cleanliness]. (=Dịch: Bệnh viện rất coi trọng các tiêu chuẩn nghiêm ngặt về sự sạch sẽ.)","Regular hand washing is essential for personal [cleanliness] and hygiene. (=Dịch: Rửa tay thường xuyên là điều cần thiết để giữ gìn vệ sinh và sự sạch sẽ của cá nhân.)","The restaurant received a high rating for the [cleanliness] of its kitchen. (=Dịch: Nhà hàng đã nhận được đánh giá cao về độ sạch sẽ của nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=cleanliness&lang=en-GB&ipa=%2F%CB%88kl%C9%9Bn.li.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=cleanliness&lang=en-US&ipa=%2F%CB%88kl%C9%9Bn.li.n%C9%99s%2F"},{"id":"lv_4_72","topic":"Cultural and Historical Exchange","word":"cleansing","pos":"(n)","ipa":"/ˈklɛn.zɪŋ/","defVi":"sự làm sạch, tẩy rửa","defEn":"the process of making something thoroughly clean or pure","examples":["Daily facial [cleansing] is essential for maintaining healthy and clear skin. (=Dịch: Làm sạch da mặt hàng ngày là điều cần thiết để duy trì làn da khỏe mạnh và sáng mịn.)","The retreat focuses on the spiritual [cleansing] of the mind and body. (=Dịch: Khóa tu tập trung vào việc thanh lọc tâm trí và cơ thể về mặt tâm linh.)","Use a gentle lotion for the deep [cleansing] of sensitive skin. (=Dịch: Hãy sử dụng một loại sữa dưỡng dịu nhẹ để làm sạch sâu cho da nhạy cảm.)"],"ukAudio":"/ai_services/tts3/?q=cleansing&lang=en-GB&ipa=%2F%CB%88kl%C9%9Bn.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=cleansing&lang=en-US&ipa=%2F%CB%88kl%C9%9Bn.z%C9%AA%C5%8B%2F"},{"id":"lv_4_73","topic":"Cultural and Historical Exchange","word":"clip","pos":"(n)","ipa":"/klɪp/","defVi":"cái kẹp; đoạn phim ngắn","defEn":"a small device used to hold things together; a short extract from a film or recording","examples":["Use a paper [clip] to keep these printed documents together. (=Dịch: Hãy dùng kẹp giấy để giữ những tài liệu in này lại với nhau.)","The teacher showed a short video [clip] to illustrate the historical event. (=Dịch: Giáo viên đã chiếu một đoạn video ngắn để minh họa cho sự kiện lịch sử.)","She secured her loose hair with a plastic [clip] before washing her face. (=Dịch: Cô ấy dùng một chiếc kẹp nhựa để cố định phần tóc xõa trước khi rửa mặt.)"],"ukAudio":"/ai_services/tts3/?q=clip&lang=en-GB&ipa=%2Fkl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=clip&lang=en-US&ipa=%2Fkl%C9%AAp%2F"},{"id":"lv_4_74","topic":"Cultural and Historical Exchange","word":"cloakroom","pos":"(n)","ipa":"/ˈkloʊk.ruːm/","defVi":"phòng gửi áo mũ, phòng giữ đồ","defEn":"a room where coats, hats, and luggage can be left temporarily","examples":["Please leave your heavy coats in the [cloakroom] near the main entrance. (=Dịch: Vui lòng để áo khoác dày của bạn ở phòng gửi đồ gần lối vào chính.)","I collected my umbrella and jacket from the theatre [cloakroom] after the show. (=Dịch: Tôi đã lấy lại ô và áo khoác từ phòng gửi đồ của nhà hát sau buổi biểu diễn.)","The attendant at the [cloakroom] handed each guest a numbered ticket. (=Dịch: Nhân viên tại phòng giữ đồ đã trao cho mỗi vị khách một chiếc vé có đánh số.)"],"ukAudio":"/ai_services/tts3/?q=cloakroom&lang=en-GB&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F","usAudio":"/ai_services/tts3/?q=cloakroom&lang=en-US&ipa=%2F%CB%88klo%CA%8Ak.ru%CB%90m%2F"},{"id":"lv_4_75","topic":"Cultural and Historical Exchange","word":"cloth","pos":"(n)","ipa":"/klɔːθ/","defVi":"vải, mảnh vải lau","defEn":"woven fabric made from cotton, wool, or other fibres, used for making clothes or covering things","examples":["She bought several metres of cotton [cloth] to make curtains. (=Dịch: Cô ấy đã mua vài mét vải cotton để may rèm cửa.)","Use a damp [cloth] to wipe the dust off the wooden table. (=Dịch: Hãy dùng một chiếc khăn ẩm để lau sạch bụi trên bàn gỗ.)","Wool is a natural [cloth] suitable for winter garments. (=Dịch: Len là một loại vải tự nhiên thích hợp cho các trang phục mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CB%90%CE%B8%2F"},{"id":"lv_4_76","topic":"Cultural and Historical Exchange","word":"coal","pos":"(n)","ipa":"/ˈkoʊl/","defVi":"than đá","defEn":"a hard black rock that is dug from the earth and burned to produce heat or electricity","examples":["The power station burns [coal] to generate electricity for the region. (=Dịch: Nhà máy điện đốt than đá để sản xuất điện cho khu vực.)","Miners worked deep underground to extract [coal]. (=Dịch: Các thợ mỏ đã làm việc sâu dưới lòng đất để khai thác than đá.)","Many countries are trying to reduce their reliance on [coal] because of pollution. (=Dịch: Nhiều quốc gia đang cố gắng giảm bớt sự phụ thuộc vào than đá do vấn đề ô nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=coal&lang=en-GB&ipa=%2F%CB%88ko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=coal&lang=en-US&ipa=%2F%CB%88ko%CA%8Al%2F"},{"id":"lv_4_77","topic":"Cultural and Historical Exchange","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stəl/","defVi":"thuộc vùng ven biển, duyên hải","defEn":"located on or near a coast","examples":["Many [coastal] towns depend heavily on fishing and tourism for income. (=Dịch: Nhiều thị trấn ven biển phụ thuộc rất nhiều vào nghề đánh cá và du lịch để kiếm thu nhập.)","The [coastal] road offers breathtaking views of the ocean. (=Dịch: Tuyến đường ven biển mang lại tầm nhìn tuyệt đẹp ra đại dương.)","Rising sea levels pose a serious threat to low-lying [coastal] areas. (=Dịch: Mực nước biển dâng cao đặt ra mối đe dọa nghiêm trọng đối với các khu vực ven biển trũng thấp.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F"},{"id":"lv_4_78","topic":"Cultural and Historical Exchange","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑːɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with mental processes of understanding, learning, and remembering","examples":["Regular physical exercise helps improve [cognitive] function in older adults. (=Dịch: Tập thể dục thường xuyên giúp cải thiện chức năng nhận thức ở người cao tuổi.)","Puzzles and memory games can stimulate children's [cognitive] development. (=Dịch: Các câu đố và trò chơi rèn luyện trí nhớ có thể kích thích sự phát triển nhận thức của trẻ em.)","The researchers studied the [cognitive] processes involved in learning a foreign language. (=Dịch: Các nhà nghiên cứu đã tìm hiểu các quá trình nhận thức liên quan đến việc học một ngoại ngữ.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_4_79","topic":"Cultural and Historical Exchange","word":"coin","pos":"(n)","ipa":"/kɔɪn/","defVi":"đồng xu, tiền kim loại","defEn":"a small, flat, usually round piece of metal used as money","examples":["He inserted a gold [coin] into the vending machine to buy a drink. (=Dịch: Anh ấy đã nhét một đồng xu vàng vào máy bán hàng tự động để mua đồ uống.)","She flipped a [coin] to decide who would start the game first. (=Dịch: Cô ấy đã tung một đồng xu để quyết định ai sẽ bắt đầu trò chơi trước.)","The metal detector found an ancient Roman [coin] buried in the field. (=Dịch: Máy dò kim loại đã tìm thấy một đồng xu La Mã cổ đại bị chôn vùi trên cánh đồng.)"],"ukAudio":"/ai_services/tts3/?q=coin&lang=en-GB&ipa=%2Fk%C9%94%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coin&lang=en-US&ipa=%2Fk%C9%94%C9%AAn%2F"},{"id":"lv_4_80","topic":"Cultural and Historical Exchange","word":"coincide","pos":"(v)","ipa":"/ˌkoʊ.ɪnˈsaɪd/","defVi":"trùng hợp, diễn ra đồng thời","defEn":"to happen at the same time as something else","examples":["The festival is planned to [coincide] with the city's annual holiday. (=Dịch: Lễ hội được lên kế hoạch trùng với ngày nghỉ lễ hàng năm của thành phố.)","Unfortunately, my business trip will [coincide] with my sister's wedding. (=Dịch: Thật không may, chuyến công tác của tôi sẽ trùng với đám cưới của em gái tôi.)","Her research findings [coincide] closely with results from previous studies. (=Dịch: Các kết quả nghiên cứu của cô ấy rất trùng khớp với kết quả từ các nghiên cứu trước đây.)"],"ukAudio":"/ai_services/tts3/?q=coincide&lang=en-GB&ipa=%2F%CB%8Cko%CA%8A.%C9%AAn%CB%88sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=coincide&lang=en-US&ipa=%2F%CB%8Cko%CA%8A.%C9%AAn%CB%88sa%C9%AAd%2F"},{"id":"lv_4_81","topic":"Cultural and Historical Exchange","word":"colonisation","pos":"(n)","ipa":"/ˌkɑː.lə.nəˈzeɪ.ʃən/","defVi":"sự thuộc địa hóa, sự khai phá thuộc địa","defEn":"the act or process of establishing control over a foreign territory and settling people there","examples":["The [colonisation] of the region caused dramatic changes to the indigenous population. (=Dịch: Sự xâm chiếm thuộc địa của khu vực này đã gây ra những thay đổi sâu sắc đối với người dân bản địa.)","Scientists are researching the possibilities and challenges of space [colonisation]. (=Dịch: Các nhà khoa học đang nghiên cứu các khả năng và thách thức của việc định cư ngoài không gian.)","Many African nations gained independence after decades of European [colonisation]. (=Dịch: Nhiều quốc gia châu Phi đã giành được độc lập sau nhiều thập kỷ bị châu Âu đô hộ.)"],"ukAudio":"/ai_services/tts3/?q=colonisation&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90.l%C9%99.n%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=colonisation&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90.l%C9%99.n%C9%99%CB%88ze%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_82","topic":"Cultural and Historical Exchange","word":"colony","pos":"(n)","ipa":"/ˈkɑː.lə.ni/","defVi":"thuộc địa","defEn":"a country or area controlled by another, more powerful country","examples":["The nation was once a British [colony] before gaining independence. (=Dịch: Quốc gia này từng là thuộc địa của Anh trước khi giành được độc lập.)","European powers established more than one [colony] across the continent. (=Dịch: Các cường quốc châu Âu đã thành lập nhiều thuộc địa trên khắp lục địa.)","Life in the newly formed [colony] was harsh and demanding. (=Dịch: Cuộc sống ở vùng thuộc địa mới thành lập rất khắc nghiệt và gian khổ.)"],"ukAudio":"/ai_services/tts3/?q=colony&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=colony&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F"},{"id":"lv_4_83","topic":"Cultural and Historical Exchange","word":"colourful","pos":"(adj)","ipa":"/ˈkʌl.ɚ.fəl/","defVi":"sặc sỡ, nhiều màu sắc, đa dạng sinh động","defEn":"having bright colors or a lot of different colors; interesting and lively","examples":["The garden was filled with [colourful] flowers blooming under the warm sun. (=Dịch: Khu vườn tràn ngập những bông hoa rực rỡ sắc màu nở rộ dưới ánh nắng ấm áp.)","The traditional festival featured a lively parade with [colourful] costumes. (=Dịch: Lễ hội truyền thống có một cuộc diễu hành sôi động với những bộ trang phục đầy màu sắc.)","The author led a [colourful] life full of exciting adventures around the world. (=Dịch: Tác giả đã có một cuộc đời muôn màu muôn vẻ với đầy những chuyến phiêu lưu kỳ thú khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=colourful&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.%C9%9A.f%C9%99l%2F","usAudio":"/ai_services/tts3/?q=colourful&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.%C9%9A.f%C9%99l%2F"},{"id":"lv_4_84","topic":"Cultural and Historical Exchange","word":"commentary","pos":"(n)","ipa":"/ˈkɑː.mən.ter.i/","defVi":"bài bình luận, lời tường thuật","defEn":"a spoken or written description and analysis of an event or topic","examples":["The live sports [commentary] made the football match much more exciting to watch. (=Dịch: Lời bình luận thể thao trực tiếp đã làm cho trận bóng đá trở nên hào hứng hơn nhiều khi theo dõi.)","The book provides an insightful [commentary] on contemporary social issues. (=Dịch: Cuốn sách đưa ra lời bình luận sâu sắc về các vấn đề xã hội đương đại.)","He gave a running [commentary] on the political developments during the news broadcast. (=Dịch: Anh ấy đã đưa ra lời bình luận liên tục về các diễn biến chính trị trong suốt buổi phát sóng tin tức.)"],"ukAudio":"/ai_services/tts3/?q=commentary&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F","usAudio":"/ai_services/tts3/?q=commentary&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.ter.i%2F"},{"id":"lv_4_85","topic":"Cultural and Historical Exchange","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"ủy ban, hội đồng; khoản tiền hoa hồng","defEn":"a formal group of people entrusted by an authority to perform a specific duty or investigation","examples":["The government set up an independent [commission] to investigate the railway accident. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vụ tai nạn đường sắt.)","The real estate agent earned a five percent [commission] on the property sale. (=Dịch: Người môi giới bất động sản đã kiếm được khoản hoa hồng 5% từ việc bán bất động sản.)","A special [commission] was appointed to review the national education curriculum. (=Dịch: Một ủy ban đặc biệt đã được chỉ định để xem xét lại chương trình giáo dục quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_86","topic":"Cultural and Historical Exchange","word":"compose","pos":"(v)","ipa":"/kəmˈpoʊz/","defVi":"sáng tác, soạn thảo","defEn":"to create a piece of music, art, or written work","examples":["The musician took several months to [compose] his first symphony. (=Dịch: Nhạc sĩ đã mất vài tháng để sáng tác bản giao hưởng đầu tiên của mình.)","She sat quietly by the window to [compose] a heartfelt apology letter. (=Dịch: Cô ngồi lặng lẽ bên cửa sổ để viết một bức thư xin lỗi chân thành.)","Different ethnic groups [compose] the rich cultural fabric of the nation. (=Dịch: Các nhóm dân tộc khác nhau cấu thành nên bức tranh văn hóa phong phú của quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=compose&lang=en-GB&ipa=%2Fk%C9%99m%CB%88po%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=compose&lang=en-US&ipa=%2Fk%C9%99m%CB%88po%CA%8Az%2F"},{"id":"lv_4_87","topic":"Cultural and Historical Exchange","word":"composer","pos":"(n)","ipa":"/kəmˈpoʊ.zər/","defVi":"nhà soạn nhạc, nhạc sĩ","defEn":"a person who writes music, especially as a professional","examples":["Mozart is widely regarded as one of the greatest [composer] figures in classical music. (=Dịch: Mozart được nhiều người coi là một trong những nhà soạn nhạc vĩ đại nhất trong nền âm nhạc cổ điển.)","The film [composer] created a dramatic soundtrack that enhanced every scene. (=Dịch: Nhà soạn nhạc phim đã tạo ra một bản nhạc nền đầy kịch tính làm nổi bật từng phân cảnh.)","She aspires to become a successful [composer] of orchestral symphonies. (=Dịch: Cô ấy khao khát trở thành một nhà soạn nhạc thành công cho các bản giao hưởng của dàn nhạc.)"],"ukAudio":"/ai_services/tts3/?q=composer&lang=en-GB&ipa=%2Fk%C9%99m%CB%88po%CA%8A.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=composer&lang=en-US&ipa=%2Fk%C9%99m%CB%88po%CA%8A.z%C9%99r%2F"},{"id":"lv_4_88","topic":"Cultural and Historical Exchange","word":"composition","pos":"(n)","ipa":"/ˌkɑːm.pəˈzɪʃ.ən/","defVi":"tác phẩm nghệ thuật hoặc âm nhạc; sự cấu thành","defEn":"a work of music, art, or literature, or the way in which something is made up","examples":["Mozart wrote this musical [composition] when he was only ten years old. (=Dịch: Mozart đã sáng tác tác phẩm âm nhạc này khi ông mới chỉ mười tuổi.)","The chemical [composition] of the soil determines which crops will grow best. (=Dịch: Thành phần hóa học của đất quyết định loại cây trồng nào sẽ phát triển tốt nhất.)","The teacher praised her for the well-structured [composition] she submitted. (=Dịch: Giáo viên đã khen ngợi cô ấy vì bài luận có cấu trúc chặt chẽ mà cô đã nộp.)"],"ukAudio":"/ai_services/tts3/?q=composition&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=composition&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.p%C9%99%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_89","topic":"Cultural and Historical Exchange","word":"concrete","pos":"(adj)","ipa":"/ˈkɑːn.kriːt/","defVi":"cụ thể, thực tế","defEn":"clear, real, and based on facts rather than general ideas","examples":["The committee asked for [concrete] proposals instead of vague ideas. (=Dịch: Ủy ban đã yêu cầu các đề xuất cụ thể thay vì những ý tưởng mơ hồ.)","Scientists need [concrete] proof to support their hypothesis. (=Dịch: Các nhà khoa học cần bằng chứng cụ thể để chứng minh cho giả thuyết của họ.)","They have not yet established any [concrete] plans for the holiday. (=Dịch: Họ vẫn chưa lập bất kỳ kế hoạch cụ thể nào cho kỳ nghỉ.)"],"ukAudio":"/ai_services/tts3/?q=concrete&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F","usAudio":"/ai_services/tts3/?q=concrete&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.kri%CB%90t%2F"},{"id":"lv_4_90","topic":"Cultural and Historical Exchange","word":"conscious","pos":"(adj)","ipa":"/ˈkɑːn.ʃəs/","defVi":"tỉnh táo, có ý thức, nhận biết được","defEn":"awake and aware of one's surroundings and thoughts; intentional","examples":["The patient remained fully [conscious] throughout the entire medical procedure. (=Dịch: Bệnh nhân vẫn hoàn toàn tỉnh táo trong suốt toàn bộ quá trình phẫu thuật.)","Many consumers are making a [conscious] effort to reduce plastic waste. (=Dịch: Nhiều người tiêu dùng đang có ý thức nỗ lực giảm thiểu rác thải nhựa.)","He is very [conscious] of how his decisions might affect the team. (=Dịch: Anh ấy rất ý thức được việc các quyết định của mình có thể ảnh hưởng như thế nào đến cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=conscious&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.%CA%83%C9%99s%2F","usAudio":"/ai_services/tts3/?q=conscious&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.%CA%83%C9%99s%2F"},{"id":"lv_4_91","topic":"Cultural and Historical Exchange","word":"consumerism","pos":"(n)","ipa":"/kənˈsuː.mɚ.ɪ.zəm/","defVi":"chủ nghĩa tiêu dùng","defEn":"the belief that buying and using a lot of goods is desirable and good for the economy","examples":["Modern [consumerism] often encourages people to purchase items they do not really need. (=Dịch: Chủ nghĩa tiêu dùng hiện đại thường khuyến khích mọi người mua những món đồ mà họ không thực sự cần.)","Environmentalists warn that excessive [consumerism] is depleting natural resources. (=Dịch: Các nhà bảo vệ môi trường cảnh báo rằng chủ nghĩa tiêu dùng quá mức đang làm cạn kiệt tài nguyên thiên nhiên.)","The rise of online shopping has fueled global [consumerism] significantly. (=Dịch: Sự phát triển của mua sắm trực tuyến đã thúc đẩy đáng kể chủ nghĩa tiêu dùng toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=consumerism&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=consumerism&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A.%C9%AA.z%C9%99m%2F"},{"id":"lv_4_92","topic":"Cultural and Historical Exchange","word":"consumption","pos":"(n)","ipa":"/kənˈsʌmp.ʃən/","defVi":"sự tiêu thụ, lượng tiêu dùng","defEn":"the act of using up resources, energy, food, or materials","examples":["Reducing fuel [consumption] is essential for cutting down carbon emissions. (=Dịch: Việc giảm lượng tiêu thụ nhiên liệu là rất cần thiết để cắt giảm lượng khí thải carbon.)","The doctor advised him to limit his daily sugar [consumption]. (=Dịch: Bác sĩ khuyên anh ấy nên hạn chế lượng đường tiêu thụ hàng ngày.)","Industrial [consumption] of water has increased significantly over the past decade. (=Dịch: Mức tiêu thụ nước trong công nghiệp đã tăng đáng kể trong thập kỷ qua.)"],"ukAudio":"/ai_services/tts3/?q=consumption&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consumption&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_4_93","topic":"Cultural and Historical Exchange","word":"convenient","pos":"(adj)","ipa":"/kənˈviːn.jənt/","defVi":"tiện lợi, thuận tiện","defEn":"fitting in well with a person's needs, activities, and plans; easy to use or access","examples":["Online shopping is extremely [convenient] for people with busy work schedules. (=Dịch: Mua sắm trực tuyến cực kỳ tiện lợi cho những người có lịch làm việc bận rộn.)","The hotel is located in a very [convenient] place near the central station. (=Dịch: Khách sạn nằm ở một vị trí rất thuận tiện gần nhà ga trung tâm.)","Please let me know a [convenient] time for our next meeting. (=Dịch: Vui lòng cho tôi biết thời gian thuận tiện cho cuộc họp tiếp theo của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=convenient&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=convenient&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi%CB%90n.j%C9%99nt%2F"},{"id":"lv_4_94","topic":"Cultural and Historical Exchange","word":"copper","pos":"(n)","ipa":"/ˈkɑ.pər/","defVi":"đồng (kim loại)","defEn":"a soft, reddish-brown metallic chemical element that conducts heat and electricity well","examples":["Electrical wires are commonly made of [copper] because it conducts electricity well. (=Dịch: Dây điện thường được làm bằng [đồng] vì nó dẫn điện tốt.)","The ancient statue was crafted from pure [copper]. (=Dịch: Bức tượng cổ được chế tác từ [đồng] nguyên chất.)","Prices of [copper] rose sharply due to high industrial demand. (=Dịch: Giá [đồng] tăng mạnh do nhu cầu công nghiệp cao.)"],"ukAudio":"/ai_services/tts3/?q=copper&lang=en-GB&ipa=%2F%CB%88k%C9%91.p%C9%99r%2F","usAudio":"/ai_services/tts3/?q=copper&lang=en-US&ipa=%2F%CB%88k%C9%91.p%C9%99r%2F"},{"id":"lv_4_95","topic":"Cultural and Historical Exchange","word":"corridor","pos":"(n)","ipa":"/ˈkɔːr.ə.dɚ/","defVi":"hành lang","defEn":"a long narrow passage in a building, with doors leading into rooms","examples":["His office is right at the end of the [corridor]. (=Dịch: Văn phòng của anh ấy nằm ngay ở cuối hành lang.)","Students are not allowed to run in the school [corridor]. (=Dịch: Học sinh không được phép chạy ở hành lang trường học.)","The hotel has a dimly lit [corridor] on the fifth floor. (=Dịch: Khách sạn có một hành lang ánh sáng lờ mờ ở tầng năm.)"],"ukAudio":"/ai_services/tts3/?q=corridor&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=corridor&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90r.%C9%99.d%C9%9A%2F"},{"id":"lv_4_96","topic":"Cultural and Historical Exchange","word":"costume","pos":"(n)","ipa":"/ˈkɑ.stum/","defVi":"trang phục hóa trang, y phục","defEn":"a set of clothes worn by an actor or someone dressing up for a special occasion","examples":["The children spent weeks designing their own [costume] for Halloween. (=Dịch: Lũ trẻ đã dành nhiều tuần để tự thiết kế trang phục hóa trang cho lễ Halloween.)","Each actor wore a traditional [costume] suited to the historical drama. (=Dịch: Mỗi diễn viên đều mặc một bộ trang phục truyền thống phù hợp với vở kịch lịch sử.)","She won first prize at the party for wearing the most creative [costume]. (=Dịch: Cô ấy đã giành giải nhất tại bữa tiệc nhờ mặc bộ trang phục sáng tạo nhất.)"],"ukAudio":"/ai_services/tts3/?q=costume&lang=en-GB&ipa=%2F%CB%88k%C9%91.stum%2F","usAudio":"/ai_services/tts3/?q=costume&lang=en-US&ipa=%2F%CB%88k%C9%91.stum%2F"},{"id":"lv_4_97","topic":"Cultural and Historical Exchange","word":"court","pos":"(n)","ipa":"/kɔːrt/","defVi":"tòa án, phiên tòa","defEn":"a place where legal trials take place and justice is administered","examples":["The witness was asked to appear in [court] to give evidence. (=Dịch: Nhân chứng được yêu cầu xuất hiện tại tòa án để cung cấp bằng chứng.)","The supreme [court] delivered its final decision on the case yesterday. (=Dịch: Tòa án tối cao đã đưa ra phán quyết cuối cùng về vụ án vào ngày hôm qua.)","Lawyers presented their arguments before the judge in open [court]. (=Dịch: Các luật sư đã trình bày lập luận của mình trước thẩm phán tại phiên tòa công khai.)"],"ukAudio":"/ai_services/tts3/?q=court&lang=en-GB&ipa=%2Fk%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=court&lang=en-US&ipa=%2Fk%C9%94%CB%90rt%2F"},{"id":"lv_4_98","topic":"Cultural and Historical Exchange","word":"creation","pos":"(n)","ipa":"/kriˈeɪ.ʃən/","defVi":"sự sáng tạo, tác phẩm sáng tạo, sự tạo ra","defEn":"the act of making something new, or something that has been made","examples":["The chef proudly presented his latest culinary [creation] to the guests. (=Dịch: Bếp trưởng tự hào giới thiệu sáng tạo ẩm thực mới nhất của mình tới các thực khách.)","The government announced the [creation] of thousands of new jobs in the tech sector. (=Dịch: Chính phủ đã công bố việc tạo ra hàng nghìn việc làm mới trong lĩnh vực công nghệ.)","Art encourages the [creation] of original ideas and self-expression. (=Dịch: Nghệ thuật khuyến khích việc tạo ra những ý tưởng độc đáo và thể hiện bản thân.)"],"ukAudio":"/ai_services/tts3/?q=creation&lang=en-GB&ipa=%2Fkri%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=creation&lang=en-US&ipa=%2Fkri%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_99","topic":"Cultural and Historical Exchange","word":"creature","pos":"(n)","ipa":"/ˈkriː.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"any living thing that is not a plant, especially an animal","examples":["The ocean depths are home to many bizarre and undiscovered [creature] types. (=Dịch: Độ sâu của đại dương là nơi cư trú của nhiều loài sinh vật kỳ lạ và chưa từng được khám phá.)","A nocturnal [creature] hunts for food during the night and sleeps by day. (=Dịch: Một sinh vật sống về đêm thường săn mồi vào ban đêm và ngủ vào ban ngày.)","Every living [creature] plays an essential role in maintaining the ecosystem. (=Dịch: Mọi sinh vật sống đều đóng một vai trò thiết yếu trong việc duy trì hệ sinh thái.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_4_100","topic":"Cultural and Historical Exchange","word":"criticism","pos":"(n)","ipa":"/ˈkrɪt̬.ə.sɪz.əm/","defVi":"sự chỉ trích, lời phê bình","defEn":"the expression of disapproval of someone or something based on perceived faults or mistakes","examples":["The government faced severe [criticism] for its handling of the economic crisis. (=Dịch: Chính phủ đã phải đối mặt với sự chỉ trích gay gắt vì cách xử lý cuộc khủng hoảng kinh tế.)","Constructive [criticism] can help students improve their writing skills. (=Dịch: Sự phê bình mang tính xây dựng có thể giúp học sinh cải thiện kỹ năng viết của mình.)","She found it difficult to accept any [criticism] of her artwork. (=Dịch: Cô cảm thấy khó chấp nhận bất kỳ lời chỉ trích nào về tác phẩm nghệ thuật của mình.)"],"ukAudio":"/ai_services/tts3/?q=criticism&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%99.s%C9%AAz.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=criticism&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%99.s%C9%AAz.%C9%99m%2F"},{"id":"lv_4_101","topic":"Cultural and Historical Exchange","word":"cultivation","pos":"(n)","ipa":"/ˌkʌl.təˈveɪ.ʃən/","defVi":"sự canh tác, trồng trọt; sự trau dồi, bồi dưỡng","defEn":"the preparation and use of land for growing crops, or the development of a skill or quality","examples":["The fertile valley is ideal for the [cultivation] of rice and vegetables. (=Dịch: Thung lũng màu mỡ này rất lý tưởng cho việc canh tác lúa và rau màu.)","Successful leadership requires the continuous [cultivation] of communication skills. (=Dịch: Sự lãnh đạo thành công đòi hỏi việc không ngừng trau dồi các kỹ năng giao tiếp.)","Intensive land [cultivation] can lead to severe soil erosion over time. (=Dịch: Việc canh tác đất đai quá mức có thể dẫn đến xói mòn đất nghiêm trọng theo thời gian.)"],"ukAudio":"/ai_services/tts3/?q=cultivation&lang=en-GB&ipa=%2F%CB%8Ck%CA%8Cl.t%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cultivation&lang=en-US&ipa=%2F%CB%8Ck%CA%8Cl.t%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_102","topic":"Cultural and Historical Exchange","word":"cultural","pos":"(adj)","ipa":"/ˈkʌl.tʃɚ.əl/","defVi":"thuộc về văn hóa","defEn":"relating to the habits, traditions, and beliefs of a society","examples":["The festival is a celebration of our rich [cultural] heritage. (=Dịch: Lễ hội là một sự tôn vinh di sản văn hóa phong phú của chúng tôi.)","Students should learn to respect [cultural] differences. (=Dịch: Học sinh nên học cách tôn trọng những khác biệt về văn hóa.)","The city offers a wide variety of [cultural] activities for tourists. (=Dịch: Thành phố mang đến nhiều hoạt động văn hóa phong phú cho du khách.)"],"ukAudio":"/ai_services/tts3/?q=cultural&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cultural&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F"},{"id":"lv_4_103","topic":"Cultural and Historical Exchange","word":"cutlery","pos":"(n)","ipa":"/ˈkʌt.lə.ri/","defVi":"bộ dao dĩa, đồ dùng ăn uống (dao, nĩa, thìa)","defEn":"knives, forks, and spoons used for eating or serving food","examples":["She placed polished silver [cutlery] on the dining table. (=Dịch: Cô ấy đặt [dao nĩa] bằng bạc đã được đánh bóng lên bàn ăn.)","The restaurant provides wooden [cutlery] for takeout meals. (=Dịch: Nhà hàng cung cấp [dao muỗng nĩa] bằng gỗ cho các bữa ăn mang đi.)","Don't forget to pack some disposable [cutlery] for our picnic. (=Dịch: Đừng quên mang theo một ít [dao muỗng nĩa] dùng một lần cho chuyến dã ngoại của chúng ta.)"],"ukAudio":"/ai_services/tts3/?q=cutlery&lang=en-GB&ipa=%2F%CB%88k%CA%8Ct.l%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=cutlery&lang=en-US&ipa=%2F%CB%88k%CA%8Ct.l%C9%99.ri%2F"},{"id":"lv_4_104","topic":"Cultural and Historical Exchange","word":"cylinder","pos":"(n)","ipa":"/ˈsɪl.ɪn.dɚ/","defVi":"hình trụ; bình khí hình trụ, xi-lanh","defEn":"a solid geometric shape or container with straight parallel sides and a circular top and base","examples":["The gas was stored safely inside a pressurized steel [cylinder]. (=Dịch: Khí gas được lưu trữ an toàn bên trong một bình trụ bằng thép chịu áp suất.)","In geometry class, students learned how to calculate the volume of a [cylinder]. (=Dịch: Trong giờ học hình học, học sinh đã học cách tính thể tích của một hình trụ.)","The engine is powered by four pistons moving smoothly inside each [cylinder]. (=Dịch: Động cơ vận hành nhờ bốn pít-tông chuyển động êm ái bên trong mỗi xi-lanh.)"],"ukAudio":"/ai_services/tts3/?q=cylinder&lang=en-GB&ipa=%2F%CB%88s%C9%AAl.%C9%AAn.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=cylinder&lang=en-US&ipa=%2F%CB%88s%C9%AAl.%C9%AAn.d%C9%9A%2F"},{"id":"lv_4_105","topic":"Cultural and Historical Exchange","word":"decade","pos":"(n)","ipa":"/ˈdɛk.eɪd/","defVi":"thập kỷ (10 năm)","defEn":"a period of ten consecutive years","examples":["Economic growth slowed down considerably over the past [decade]. (=Dịch: Tăng trưởng kinh tế đã chậm lại đáng kể trong thập kỷ qua.)","Technology has transformed our daily lives over the last [decade]. (=Dịch: Công nghệ đã làm thay đổi cuộc sống hàng ngày của chúng ta trong thập kỷ vừa qua.)","She spent more than a [decade] working as a primary school teacher. (=Dịch: Cô ấy đã dành hơn một thập kỷ làm giáo viên tiểu học.)"],"ukAudio":"/ai_services/tts3/?q=decade&lang=en-GB&ipa=%2F%CB%88d%C9%9Bk.e%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=decade&lang=en-US&ipa=%2F%CB%88d%C9%9Bk.e%C9%AAd%2F"},{"id":"lv_4_106","topic":"Cultural and Historical Exchange","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"suy giảm; từ chối","defEn":"to gradually become smaller, fewer, or less; to politely refuse an offer","examples":["Tourist numbers began to [decline] during the rainy season. (=Dịch: Lượng khách du lịch bắt đầu suy giảm trong suốt mùa mưa.)","He decided to [decline] the job offer because the commute was too long. (=Dịch: Anh ấy đã quyết định từ chối lời mời làm việc vì quãng đường đi làm quá xa.)","Air quality can [decline] rapidly if factories do not follow environmental regulations. (=Dịch: Chất lượng không khí có thể suy giảm nhanh chóng nếu các nhà máy không tuân thủ các quy định về môi trường.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_4_107","topic":"Cultural and Historical Exchange","word":"decorate","pos":"(v)","ipa":"/ˈdek.ə.reɪt/","defVi":"trang trí, tô điểm","defEn":"to add things to an object or place to make it look more attractive","examples":["They decided to [decorate] the living room with fresh flowers. (=Dịch: Họ quyết định trang trí phòng khách bằng hoa tươi.)","Children love to [decorate] the Christmas tree every December. (=Dịch: Trẻ em thích trang trí cây thông Giáng sinh vào mỗi tháng Mười Hai.)","The bakery allows customers to [decorate] their own cakes. (=Dịch: Tiệm bánh cho phép khách hàng tự trang trí bánh ngọt của riêng mình.)"],"ukAudio":"/ai_services/tts3/?q=decorate&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=decorate&lang=en-US&ipa=%2F%CB%88dek.%C9%99.re%C9%AAt%2F"},{"id":"lv_4_108","topic":"Cultural and Historical Exchange","word":"decoration","pos":"(n)","ipa":"/ˌdɛk.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang hoàng","defEn":"an object or detail added to something to make it look more attractive","examples":["They put up colorful lighting as part of the party [decoration]. (=Dịch: Họ đã giăng đèn nhiều màu sắc như một phần của việc trang trí bữa tiệc.)","Handmade wooden crafts serve as elegant [decoration] in modern homes. (=Dịch: Đồ thủ công bằng gỗ tự làm đóng vai trò là vật trang trí trang nhã trong những ngôi nhà hiện đại.)","The cake [decoration] took the baker several hours to complete. (=Dịch: Việc trang trí chiếc bánh đã khiến người thợ làm bánh mất vài giờ để hoàn thành.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bk.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bk.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_109","topic":"Cultural and Historical Exchange","word":"decorative","pos":"(adj)","ipa":"/ˈdek.ə.rə.t̬ɪv/","defVi":"mang tính trang trí, dùng để làm đẹp","defEn":"made to look attractive rather than for practical use","examples":["The mirror has an elaborate [decorative] frame made of carved wood. (=Dịch: Chiếc gương có phần khung trang trí tinh xảo làm bằng gỗ chạm khắc.)","Plants are often used for [decorative] purposes in modern offices. (=Dịch: Cây xanh thường được dùng cho mục đích trang trí trong các văn phòng hiện đại.)","She placed several [decorative] cushions on the sofa to brighten up the room. (=Dịch: Cô ấy đặt vài chiếc gối trang trí trên ghế sofa để làm bừng sáng căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=decorative&lang=en-GB&ipa=%2F%CB%88dek.%C9%99.r%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=decorative&lang=en-US&ipa=%2F%CB%88dek.%C9%99.r%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_4_110","topic":"Cultural and Historical Exchange","word":"definition","pos":"(n)","ipa":"/ˌdɛf.əˈnɪʃ.ən/","defVi":"định nghĩa, lời giải thích ý nghĩa","defEn":"an explanation of the exact meaning of a word, phrase, or concept","examples":["You can look up the exact [definition] of the word in a dictionary. (=Dịch: Bạn có thể tra cứu [định nghĩa] chính xác của từ này trong từ điển.)","The legal [definition] of fraud can vary from country to country. (=Dịch: [Định nghĩa] pháp lý về tội lừa đảo có thể khác nhau tùy theo từng quốc gia.)","His clear [definition] of the problem helped the team find a solution. (=Dịch: [Sự xác định] rõ ràng của anh ấy về vấn đề đã giúp cả nhóm tìm ra giải pháp.)"],"ukAudio":"/ai_services/tts3/?q=definition&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=definition&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_111","topic":"Cultural and Historical Exchange","word":"deliver","pos":"(v)","ipa":"/dɪˈlɪv.ɚ/","defVi":"giao hàng; phát biểu","defEn":"to take goods, letters, or packages to a person or place; to give a speech","examples":["The courier will [deliver] your parcel before five o'clock. (=Dịch: Nhân viên chuyển phát sẽ giao bưu kiện của bạn trước năm giờ.)","The professor is scheduled to [deliver] a lecture on climate change tomorrow. (=Dịch: Giáo sư dự kiến sẽ có một bài giảng về biến đổi khí hậu vào ngày mai.)","Our company strives to [deliver] exceptional service to all clients. (=Dịch: Công ty chúng tôi luôn nỗ lực mang lại dịch vụ xuất sắc cho tất cả khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=deliver&lang=en-GB&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=deliver&lang=en-US&ipa=%2Fd%C9%AA%CB%88l%C9%AAv.%C9%9A%2F"},{"id":"lv_4_112","topic":"Cultural and Historical Exchange","word":"demonstration","pos":"(n)","ipa":"/ˌdɛm.ənˈstreɪ.ʃən/","defVi":"sự trình diễn, sự thị phạm","defEn":"an act of showing how something works, is done, or is used","examples":["The chef gave a practical [demonstration] of how to prepare the traditional dish. (=Dịch: Bếp trưởng đã thực hiện một buổi trình diễn thực tế về cách chế biến món ăn truyền thống.)","We watched an interesting [demonstration] of the new software in the workshop. (=Dịch: Chúng tôi đã xem một buổi minh họa thú vị về phần mềm mới trong hội thảo.)","The teacher used a simple laboratory [demonstration] to explain chemical reactions. (=Dịch: Giáo viên đã sử dụng một thí nghiệm biểu diễn đơn giản trong phòng thí nghiệm để giải thích các phản ứng hóa học.)"],"ukAudio":"/ai_services/tts3/?q=demonstration&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99n%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=demonstration&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99n%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_113","topic":"Cultural and Historical Exchange","word":"depict","pos":"(v)","ipa":"/dɪˈpɪkt/","defVi":"miêu tả, khắc họa","defEn":"to represent or show something in a picture, painting, or story","examples":["The murals on the wall [depict] the daily life of ancient citizens. (=Dịch: Các bức tranh tường miêu tả cuộc sống hàng ngày của những cư dân thời cổ đại.)","Documentaries often [depict] the harsh realities of wildlife survival. (=Dịch: Phim tài liệu thường khắc họa những thực tế khắc nghiệt về sự sinh tồn của động vật hoang dã.)","The novel manages to [depict] the complex emotions of the main character accurately. (=Dịch: Cuốn tiểu thuyết đã khắc họa thành công và chính xác những cảm xúc phức tạp của nhân vật chính.)"],"ukAudio":"/ai_services/tts3/?q=depict&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=depict&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%AAkt%2F"},{"id":"lv_4_114","topic":"Cultural and Historical Exchange","word":"depression","pos":"(n)","ipa":"/dɪˈprɛʃ.ən/","defVi":"chứng trầm cảm","defEn":"a mental health condition characterized by severe, persistent feelings of sadness and hopelessness","examples":["Regular exercise and therapy can help alleviate symptoms of clinical [depression]. (=Dịch: Tập thể dục đều đặn và trị liệu có thể giúp làm giảm các triệu chứng của bệnh trầm cảm lâm sàng.)","She fell into a deep [depression] after losing her long-term job. (=Dịch: Cô ấy rơi vào trạng thái trầm cảm sâu sắc sau khi mất công việc gắn bó lâu năm.)","Public awareness campaigns aim to reduce the stigma surrounding teenage [depression]. (=Dịch: Các chiến dịch nâng cao nhận thức cộng đồng nhằm giảm bớt sự kỳ thị xung quanh chứng trầm cảm ở tuổi vị thành niên.)"],"ukAudio":"/ai_services/tts3/?q=depression&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=depression&lang=en-US&ipa=%2Fd%C9%AA%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_4_115","topic":"Cultural and Historical Exchange","word":"destruction","pos":"(n)","ipa":"/dɪˈstrʌk.ʃən/","defVi":"sự phá hủy, sự tàn phá","defEn":"the act or process of destroying something, or the state of being destroyed","examples":["The storm caused widespread [destruction] across the coastal villages. (=Dịch: Cơn bão đã gây ra sự [tàn phá] trên diện rộng khắp các ngôi làng ven biển.)","The [destruction] of rainforests threatens many endangered species. (=Dịch: Sự [phá hủy] các khu rừng nhiệt đới đe dọa nhiều loài có nguy cơ tuyệt chủng.)","Weapons of mass [destruction] pose a serious threat to world peace. (=Dịch: Vũ khí [hủy diệt] hàng loạt là mối đe dọa nghiêm trọng đối với hòa bình thế giới.)"],"ukAudio":"/ai_services/tts3/?q=destruction&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destruction&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_4_116","topic":"Cultural and Historical Exchange","word":"digitalise","pos":"(v)","ipa":"/ˈdɪdʒ.ə.t̬əl.aɪz/","defVi":"số hóa","defEn":"to convert information or documents into a format that computers can process","examples":["The national library aims to [digitalise] all historical manuscripts for public access. (=Dịch: Thư viện quốc gia đặt mục tiêu số hóa tất cả các bản thảo lịch sử để công chúng có thể tiếp cận.)","Many hospitals are trying to [digitalise] patient records to improve efficiency. (=Dịch: Nhiều bệnh viện đang cố gắng số hóa hồ sơ bệnh nhân để nâng cao hiệu quả.)","Small businesses must [digitalise] their payment systems to stay competitive. (=Dịch: Các doanh nghiệp nhỏ phải số hóa hệ thống thanh toán của mình để duy trì tính cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=digitalise&lang=en-GB&ipa=%2F%CB%88d%C9%AAd%CA%92.%C9%99.t%CC%AC%C9%99l.a%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=digitalise&lang=en-US&ipa=%2F%CB%88d%C9%AAd%CA%92.%C9%99.t%CC%AC%C9%99l.a%C9%AAz%2F"},{"id":"lv_4_117","topic":"Cultural and Historical Exchange","word":"disappoint","pos":"(v)","ipa":"/ˌdɪs.əˈpɔɪnt/","defVi":"làm thất vọng","defEn":"to fail to satisfy someone's hopes or expectations","examples":["I am sorry to [disappoint] you, but the tickets are already sold out. (=Dịch: Tôi rất tiếc phải làm bạn thất vọng, nhưng vé đã được bán hết rồi.)","The team worked hard because they did not want to [disappoint] their coach. (=Dịch: Cả đội đã nỗ lực hết mình vì không muốn làm huấn luyện viên của họ thất vọng.)","The final results of the experiment may [disappoint] some researchers. (=Dịch: Kết quả cuối cùng của thí nghiệm có thể khiến một số nhà nghiên cứu thất vọng.)"],"ukAudio":"/ai_services/tts3/?q=disappoint&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%94%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=disappoint&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%94%C9%AAnt%2F"},{"id":"lv_4_118","topic":"Cultural and Historical Exchange","word":"distribution","pos":"(n)","ipa":"/ˌdɪs.trəˈbjuː.ʃən/","defVi":"sự phân phối, sự phân bố","defEn":"the way in which something is spread over an area, or the delivery of goods to various places","examples":["The unequal [distribution] of wealth remains a major global challenge. (=Dịch: Sự phân bổ của cải không đồng đều vẫn là một thách thức lớn trên toàn cầu.)","The company improved its supply chain to ensure faster [distribution] of medical supplies. (=Dịch: Công ty đã cải thiện chuỗi cung ứng của mình để đảm bảo việc phân phối vật tư y tế nhanh hơn.)","Scientists are studying the geographic [distribution] of endangered plant species. (=Dịch: Các nhà khoa học đang nghiên cứu sự phân bố địa lý của các loài thực vật có nguy cơ tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=distribution&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%99%CB%88bju%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=distribution&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%99%CB%88bju%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_119","topic":"Cultural and Historical Exchange","word":"disturbing","pos":"(adj)","ipa":"/dɪˈstɝː.bɪŋ/","defVi":"gây lo ngại, làm phiền lòng","defEn":"making you feel worried, upset, or shocked","examples":["The news report contained some very [disturbing] images. (=Dịch: Bản tin chứa một số hình ảnh rất đáng lo ngại.)","There has been a [disturbing] increase in youth crime recently. (=Dịch: Gần đây có sự gia tăng đáng lo ngại về tội phạm vị thành niên.)","She found the quiet atmosphere in the empty house quite [disturbing]. (=Dịch: Cô cảm thấy bầu không khí tĩnh mịch trong ngôi nhà trống trải khá bất an.)"],"ukAudio":"/ai_services/tts3/?q=disturbing&lang=en-GB&ipa=%2Fd%C9%AA%CB%88st%C9%9D%CB%90.b%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=disturbing&lang=en-US&ipa=%2Fd%C9%AA%CB%88st%C9%9D%CB%90.b%C9%AA%C5%8B%2F"},{"id":"lv_4_120","topic":"Cultural and Historical Exchange","word":"diver","pos":"(n)","ipa":"/ˈdaɪ.vɚ/","defVi":"thợ lặn, người lặn","defEn":"a person who swims underwater using special breathing equipment","examples":["An experienced [diver] explored the deep coral reefs off the coast. (=Dịch: Một thợ lặn giàu kinh nghiệm đã khám phá những rạn san hô sâu ngoài khơi bờ biển.)","The rescue team sent a [diver] to search for the submerged vehicle. (=Dịch: Đội cứu hộ đã cử một thợ lặn đến để tìm kiếm chiếc xe bị chìm.)","Each [diver] must check their oxygen tank carefully before going underwater. (=Dịch: Mỗi thợ lặn phải kiểm tra kỹ bình dưỡng khí của mình trước khi lặn xuống nước.)"],"ukAudio":"/ai_services/tts3/?q=diver&lang=en-GB&ipa=%2F%CB%88da%C9%AA.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=diver&lang=en-US&ipa=%2F%CB%88da%C9%AA.v%C9%9A%2F"},{"id":"lv_4_121","topic":"Cultural and Historical Exchange","word":"diverse","pos":"(adj)","ipa":"/daɪˈvɝːs/","defVi":"đa dạng, phong phú","defEn":"including many different types of people or things","examples":["The university has a culturally [diverse] student body. (=Dịch: Trường đại học có một cộng đồng sinh viên đa dạng về văn hóa.)","She has very [diverse] interests, ranging from music to astronomy. (=Dịch: Cô có những sở thích rất đa dạng, từ âm nhạc cho đến thiên văn học.)","The rainforest is home to an extraordinarily [diverse] range of wildlife. (=Dịch: Rừng nhiệt đới là nơi sinh sống của một hệ động thực vật hoang dã vô cùng phong phú và đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=diverse&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90s%2F","usAudio":"/ai_services/tts3/?q=diverse&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9D%CB%90s%2F"},{"id":"lv_4_122","topic":"Cultural and Historical Exchange","word":"documentary","pos":"(adj)","ipa":"/ˌdɑː.kjəˈmen.tər.i/","defVi":"mang tính tài liệu, dựa trên tư liệu thực tế","defEn":"consisting of or based on official documents and factual records","examples":["The lawyer presented strong [documentary] evidence to support his client's claim. (=Dịch: Luật sư đã đưa ra bằng chứng bằng văn bản thuyết phục để chứng minh cho khiếu nại của thân chủ mình.)","Historians rely on [documentary] records to reconstruct past events accurately. (=Dịch: Các nhà sử học dựa vào các tư liệu thành văn để tái hiện chính xác các sự kiện trong quá khứ.)","She is preparing a [documentary] report on the impacts of climate change. (=Dịch: Cô ấy đang chuẩn bị một bản báo cáo tư liệu về những tác động của biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=documentary&lang=en-GB&ipa=%2F%CB%8Cd%C9%91%CB%90.kj%C9%99%CB%88men.t%C9%99r.i%2F","usAudio":"/ai_services/tts3/?q=documentary&lang=en-US&ipa=%2F%CB%8Cd%C9%91%CB%90.kj%C9%99%CB%88men.t%C9%99r.i%2F"},{"id":"lv_4_123","topic":"Cultural and Historical Exchange","word":"dominate","pos":"(v)","ipa":"/ˈdɑː.məˌneɪt/","defVi":"thống trị, chi phối","defEn":"to have control, power, or a very strong influence over someone or something","examples":["A few large corporations [dominate] the global smartphone market. (=Dịch: Một vài tập đoàn lớn đang thống trị thị trường điện thoại thông minh toàn cầu.)","Discussions about the economy tended to [dominate] the annual meeting. (=Dịch: Các cuộc thảo luận về kinh tế có xu hướng chiếm ưu thế trong cuộc họp thường niên.)","The mountain peak continues to [dominate] the surrounding landscape. (=Dịch: Đỉnh núi vẫn sừng sững bao quát cảnh quan xung quanh.)"],"ukAudio":"/ai_services/tts3/?q=dominate&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99%CB%8Cne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=dominate&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99%CB%8Cne%C9%AAt%2F"},{"id":"lv_4_124","topic":"Cultural and Historical Exchange","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"quyên góp, ủng hộ, hiến tặng","defEn":"to give money, goods, or services to help a person or organization","examples":["Wealthy individuals frequently [donate] large sums to charitable foundations. (=Dịch: Những người giàu có thường xuyên quyên góp những khoản tiền lớn cho các quỹ từ thiện.)","Citizens gathered at the clinic to [donate] blood for disaster victims. (=Dịch: Người dân đã tập trung tại phòng khám để hiến máu cho các nạn nhân của thảm họa.)","She plans to [donate] her old textbooks to the local community library. (=Dịch: Cô ấy dự định tặng các sách giáo khoa cũ của mình cho thư viện cộng đồng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_4_125","topic":"Cultural and Historical Exchange","word":"drain","pos":"(v)","ipa":"/dreɪn/","defVi":"thoát nước, rút cạn, làm kiệt quệ","defEn":"to remove liquid from something, or to use up resources gradually until empty","examples":["You need to [drain] the cooked pasta thoroughly before adding the tomato sauce. (=Dịch: Bạn cần để ráo nước món mì ống đã nấu chín trước khi thêm sốt cà chua.)","Huge medical expenses can quickly [drain] a family's savings. (=Dịch: Chi phí y tế khổng lồ có thể nhanh chóng làm cạn kiệt tiền tiết kiệm của một gia đình.)","Workers dug a series of trenches to [drain] floodwaters from the residential area. (=Dịch: Các công nhân đã đào một loạt mương để thoát nước lũ khỏi khu dân cư.)"],"ukAudio":"/ai_services/tts3/?q=drain&lang=en-GB&ipa=%2Fdre%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=drain&lang=en-US&ipa=%2Fdre%C9%AAn%2F"},{"id":"lv_4_126","topic":"Cultural and Historical Exchange","word":"drum","pos":"(n)","ipa":"/drʌm/","defVi":"cái trống; thùng phuy","defEn":"a musical instrument played by hitting with sticks or hands, or a large cylindrical container","examples":["The steady beat of the [drum] echoed across the entire stadium. (=Dịch: Tiếng trống đập đều đặn vang vọng khắp cả sân vận động.)","The factory stored hazardous chemicals in a large metal [drum]. (=Dịch: Nhà máy đã chứa các hóa chất nguy hiểm trong một chiếc thùng phuy kim loại lớn.)","She learned to play the traditional African [drum] during her cultural trip. (=Dịch: Cô ấy đã học chơi chiếc trống truyền thống của châu Phi trong chuyến đi trải nghiệm văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=drum&lang=en-GB&ipa=%2Fdr%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=drum&lang=en-US&ipa=%2Fdr%CA%8Cm%2F"},{"id":"lv_4_127","topic":"Cultural and Historical Exchange","word":"drunk","pos":"(n)","ipa":"/drʌŋk/","defVi":"kẻ say rượu, người nghiện rượu","defEn":"a person who is intoxicated or who frequently drinks too much alcohol","examples":["The police officer helped the harmless [drunk] find his way home. (=Dịch: Viên cảnh sát đã giúp người say rượu vô hại tìm đường về nhà.)","A noisy [drunk] was causing a disturbance outside the restaurant. (=Dịch: Một kẻ say rượu ồn ào đã gây mất trật tự bên ngoài nhà hàng.)","The shelter provides warm beds for homeless [drunks] during winter nights. (=Dịch: Nhà tạm trú cung cấp giường ấm cho những người say xỉn vô gia cư trong những đêm mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=drunk&lang=en-GB&ipa=%2Fdr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=drunk&lang=en-US&ipa=%2Fdr%CA%8C%C5%8Bk%2F"},{"id":"lv_4_128","topic":"Cultural and Historical Exchange","word":"dutch","pos":"(adj)","ipa":"/dʌtʃ/","defVi":"(thuộc) Hà Lan, người Hà Lan hoặc tiếng Hà Lan","defEn":"relating to the Netherlands, its people, or its language","examples":["We rented bicycles to explore the traditional [Dutch] countryside. (=Dịch: Chúng tôi đã thuê xe đạp để khám phá vùng nông thôn truyền thống của Hà Lan.)","She is currently learning [Dutch] before moving to Amsterdam for work. (=Dịch: Cô ấy hiện đang học tiếng Hà Lan trước khi chuyển đến Amsterdam để làm việc.)","The museum features a rare collection of seventeenth-century [Dutch] paintings. (=Dịch: Bảo tàng trưng bày một bộ sưu tập tranh Hà Lan thế kỷ XVII quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=dutch&lang=en-GB&ipa=%2Fd%CA%8Ct%CA%83%2F","usAudio":"/ai_services/tts3/?q=dutch&lang=en-US&ipa=%2Fd%CA%8Ct%CA%83%2F"},{"id":"lv_4_129","topic":"Cultural and Historical Exchange","word":"dwelling","pos":"(n)","ipa":"/ˈdwel.ɪŋ/","defVi":"chỗ ở, nơi cư ngụ, nhà ở","defEn":"a house, flat, or other place of residence","examples":["Archaeologists discovered the remains of an ancient cave [dwelling]. (=Dịch: Các nhà khảo cổ học đã phát hiện ra tàn tích của một nơi cư trú trong hang động cổ xưa.)","The city council plans to build more affordable [dwelling] units for low-income families. (=Dịch: Hội đồng thành phố lên kế hoạch xây dựng thêm nhiều căn nhà ở giá cả phải chăng cho các gia đình có thu nhập thấp.)","Many traditional wooden [dwelling] structures were damaged during the severe storm. (=Dịch: Nhiều công trình nhà ở bằng gỗ truyền thống đã bị hư hại trong cơn bão dữ dội.)"],"ukAudio":"/ai_services/tts3/?q=dwelling&lang=en-GB&ipa=%2F%CB%88dwel.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=dwelling&lang=en-US&ipa=%2F%CB%88dwel.%C9%AA%C5%8B%2F"},{"id":"lv_4_130","topic":"Cultural and Historical Exchange","word":"dynamic","pos":"(adj)","ipa":"/daɪˈnæm.ɪk/","defVi":"năng động, sôi nổi, biến đổi liên tục","defEn":"full of energy, enthusiasm, and new ideas; constantly changing","examples":["She is a [dynamic] speaker who easily captivates the entire audience. (=Dịch: Cô ấy là một diễn giả đầy năng động, người dễ dàng lôi cuốn toàn bộ khán giả.)","The technology sector is a fast-paced and [dynamic] industry. (=Dịch: Lĩnh vực công nghệ là một ngành công nghiệp có nhịp độ nhanh và đầy năng động.)","We need to adapt our strategy to survive in this [dynamic] market. (=Dịch: Chúng ta cần phải điều chỉnh chiến lược của mình để tồn tại trong thị trường biến động không ngừng này.)"],"ukAudio":"/ai_services/tts3/?q=dynamic&lang=en-GB&ipa=%2Fda%C9%AA%CB%88n%C3%A6m.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dynamic&lang=en-US&ipa=%2Fda%C9%AA%CB%88n%C3%A6m.%C9%AAk%2F"},{"id":"lv_4_131","topic":"Cultural and Historical Exchange","word":"edit","pos":"(v)","ipa":"/ˈɛd.ɪt/","defVi":"chỉnh sửa, biên tập","defEn":"to make changes to a text, film, or audio recording to correct mistakes or prepare it for publication","examples":["You should carefully [edit] your essay before submitting it to the professor. (=Dịch: Bạn nên cẩn thận chỉnh sửa bài luận của mình trước khi nộp cho giáo sư.)","It took them several weeks to [edit] the documentary film. (=Dịch: Họ đã mất vài tuần để biên tập bộ phim tài liệu.)","The publisher asked the author to [edit] the final chapter to improve its flow. (=Dịch: Nhà xuất bản đã yêu cầu tác giả chỉnh sửa chương cuối để bài viết được liền mạch hơn.)"],"ukAudio":"/ai_services/tts3/?q=edit&lang=en-GB&ipa=%2F%CB%88%C9%9Bd.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=edit&lang=en-US&ipa=%2F%CB%88%C9%9Bd.%C9%AAt%2F"},{"id":"lv_4_132","topic":"Cultural and Historical Exchange","word":"edition","pos":"(n)","ipa":"/ɪˈdɪʃ.ən/","defVi":"ấn bản, phiên bản","defEn":"a particular form or version of a published text or broadcast","examples":["I bought the latest [edition] of the English dictionary. (=Dịch: Tôi đã mua ấn bản mới nhất của cuốn từ điển tiếng Anh.)","The author signed a limited [edition] of her new novel. (=Dịch: Tác giả đã ký tặng một ấn bản giới hạn cho cuốn tiểu thuyết mới của cô ấy.)","This morning's [edition] of the newspaper featured an article on climate change. (=Dịch: Ấn bản sáng nay của tờ báo có một bài viết về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=edition&lang=en-GB&ipa=%2F%C9%AA%CB%88d%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=edition&lang=en-US&ipa=%2F%C9%AA%CB%88d%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_133","topic":"Cultural and Historical Exchange","word":"egypt","pos":"(n)","ipa":"/ˈiː.dʒɪpt/","defVi":"Ai Cập","defEn":"a country in northeastern Africa famous for its ancient pyramids and long history","examples":["Many tourists visit [Egypt] each year to see the Great Pyramids of Giza. (=Dịch: Nhiều du khách đến thăm Ai Cập mỗi năm để chiêm ngưỡng Đại kim tự tháp Giza.)","The Suez Canal in [Egypt] is one of the most vital shipping routes in the world. (=Dịch: Kênh đào Suez ở Ai Cập là một trong những tuyến đường vận tải biển quan trọng nhất trên thế giới.)","Archaeologists recently uncovered a new tomb in southern [Egypt]. (=Dịch: Các nhà khảo cổ học gần đây đã khai quật được một ngôi mộ mới ở miền nam Ai Cập.)"],"ukAudio":"/ai_services/tts3/?q=egypt&lang=en-GB&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=egypt&lang=en-US&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F"},{"id":"lv_4_134","topic":"Cultural and Historical Exchange","word":"eighteenth","pos":"(adj)","ipa":"/ˌeɪˈtiːnθ/","defVi":"thứ mười tám","defEn":"constituting number eighteen in a sequence; 18th","examples":["He celebrated his [eighteenth] birthday with a big gathering of friends. (=Dịch: Anh ấy đã kỷ niệm sinh nhật lần thứ mười tám của mình bằng một buổi tụ tập bạn bè lớn.)","The museum houses many rare paintings from the [eighteenth] century. (=Dịch: Bảo tàng lưu giữ nhiều bức tranh quý hiếm từ thế kỷ thứ mười tám.)","Our office is located on the [eighteenth] floor of the tower. (=Dịch: Văn phòng của chúng tôi nằm ở tầng thứ mười tám của tòa tháp.)"],"ukAudio":"/ai_services/tts3/?q=eighteenth&lang=en-GB&ipa=%2F%CB%8Ce%C9%AA%CB%88ti%CB%90n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=eighteenth&lang=en-US&ipa=%2F%CB%8Ce%C9%AA%CB%88ti%CB%90n%CE%B8%2F"},{"id":"lv_4_135","topic":"Cultural and Historical Exchange","word":"emotion","pos":"(n)","ipa":"/ɪˈmoʊ.ʃən/","defVi":"cảm xúc, sự xúc động","defEn":"a strong feeling deriving from one's circumstances, mood, or relationships","examples":["Music has the power to evoke deep [emotion] in the listener. (=Dịch: Âm nhạc có sức mạnh gợi lên cảm xúc sâu sắc nơi người nghe.)","He tried to hide his [emotion] during the farewell ceremony. (=Dịch: Anh ấy đã cố gắng che giấu cảm xúc của mình trong buổi lễ chia tay.)","Fear is a natural [emotion] that helps humans respond to danger. (=Dịch: Sợ hãi là một cảm xúc tự nhiên giúp con người phản ứng trước sự nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=emotion&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emotion&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_4_136","topic":"Cultural and Historical Exchange","word":"emotional","pos":"(adj)","ipa":"/ɪˈmoʊ.ʃən.əl/","defVi":"thuộc về cảm xúc, dễ xúc động","defEn":"relating to or showing strong feelings","examples":["Listening to music often provides good [emotional] support during difficult times. (=Dịch: Nghe nhạc thường mang lại sự hỗ trợ tinh thần tốt trong những thời điểm khó khăn.)","She gave an [emotional] speech when accepting the prestigious award. (=Dịch: Cô đã có một bài phát biểu đầy cảm xúc khi nhận giải thưởng danh giá.)","Children need a stable [emotional] environment to grow up healthy. (=Dịch: Trẻ em cần một môi trường cảm xúc ổn định để lớn lên khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=emotional&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=emotional&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_4_137","topic":"Cultural and Historical Exchange","word":"empire","pos":"(n)","ipa":"/ˈɛm.paɪ.ɚ/","defVi":"đế chế, đế quốc","defEn":"a large group of countries or regions ruled by a single leader or government","examples":["The Roman [empire] once stretched across much of Europe and North Africa. (=Dịch: Đế chế La Mã từng trải dài khắp phần lớn châu Âu và Bắc Phi.)","Historians study the factors that led to the collapse of the ancient [empire]. (=Dịch: Các nhà sử học nghiên cứu những yếu tố dẫn đến sự sụp đổ của đế chế cổ đại.)","He built a global business [empire] starting from a small family shop. (=Dịch: Ông đã xây dựng một đế chế kinh doanh toàn cầu bắt đầu từ một cửa hàng nhỏ của gia đình.)"],"ukAudio":"/ai_services/tts3/?q=empire&lang=en-GB&ipa=%2F%CB%88%C9%9Bm.pa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=empire&lang=en-US&ipa=%2F%CB%88%C9%9Bm.pa%C9%AA.%C9%9A%2F"},{"id":"lv_4_138","topic":"Cultural and Historical Exchange","word":"enemy","pos":"(n)","ipa":"/ˈɛn.ə.mi/","defVi":"kẻ thù, quân địch","defEn":"a person, group, or country that is hostile to another and opposes them actively","examples":["The two nations stopped fighting and agreed not to view each other as an [enemy]. (=Dịch: Hai quốc gia đã ngừng giao tranh và đồng ý không coi nhau là kẻ thù.)","Lack of sleep can be the greatest [enemy] of good academic performance. (=Dịch: Thiếu ngủ có thể là kẻ thù lớn nhất đối với kết quả học tập tốt.)","Soldiers defended their base against the approaching [enemy]. (=Dịch: Các binh sĩ đã bảo vệ căn cứ của họ trước kẻ thù đang tiến đến gần.)"],"ukAudio":"/ai_services/tts3/?q=enemy&lang=en-GB&ipa=%2F%CB%88%C9%9Bn.%C9%99.mi%2F","usAudio":"/ai_services/tts3/?q=enemy&lang=en-US&ipa=%2F%CB%88%C9%9Bn.%C9%99.mi%2F"},{"id":"lv_4_139","topic":"Cultural and Historical Exchange","word":"engraving","pos":"(n)","ipa":"/ɪnˈɡreɪ.vɪŋ/","defVi":"bản khắc, nghệ thuật chạm khắc","defEn":"a design or picture cut onto a hard surface, or the process of making such designs","examples":["The delicate [engraving] on the silver ring depicted two flying birds. (=Dịch: Hình chạm khắc tinh xảo trên chiếc nhẫn bạc mô tả hai chú chim đang bay.)","He collected 19th-century [engraving] prints depicting historical events. (=Dịch: Ông đã sưu tầm các bản in tranh khắc thế kỷ 19 mô tả các sự kiện lịch sử.)","Archaeologists found a prehistoric [engraving] on the cave wall. (=Dịch: Các nhà khảo cổ học đã tìm thấy một hình khắc thời tiền sử trên vách hang động.)"],"ukAudio":"/ai_services/tts3/?q=engraving&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1re%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=engraving&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1re%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_4_140","topic":"Cultural and Historical Exchange","word":"enormously","pos":"(adv)","ipa":"/ɪˈnɔːr.məs.li/","defVi":"vô cùng, cực kỳ, rất nhiều","defEn":"extremely; to a very large extent or degree","examples":["The new marketing campaign has [enormously] increased our sales. (=Dịch: Chiến dịch tiếp thị mới đã làm tăng doanh số bán hàng của chúng tôi một cách vô cùng to lớn.)","She enjoyed the international exchange program [enormously]. (=Dịch: Cô ấy đã vô cùng thích thú với chương trình trao đổi quốc tế.)","Technology has made communication [enormously] easier than before. (=Dịch: Công nghệ đã làm cho việc giao tiếp trở nên dễ dàng hơn trước rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=enormously&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=enormously&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F"},{"id":"lv_4_141","topic":"Cultural and Historical Exchange","word":"entire","pos":"(adj)","ipa":"/ɪnˈtaɪ.ɚ/","defVi":"toàn bộ, toàn thể, trọn vẹn","defEn":"including everything or everyone; whole and complete","examples":["He spent the [entire] afternoon cleaning and organizing his room. (=Dịch: Anh ấy đã dành toàn bộ buổi chiều để dọn dẹp và sắp xếp phòng của mình.)","The [entire] staff attended the annual safety training workshop. (=Dịch: Toàn bộ nhân viên đã tham dự hội thảo đào tạo an toàn thường niên.)","Severe storms knocked out power for the [entire] city. (=Dịch: Những cơn bão dữ dội đã làm mất điện toàn bộ thành phố.)"],"ukAudio":"/ai_services/tts3/?q=entire&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=entire&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_4_142","topic":"Cultural and Historical Exchange","word":"entrepreneur","pos":"(n)","ipa":"/ˌɑːn.trə.prəˈnʊr/","defVi":"doanh nhân, người khởi nghiệp","defEn":"a person who sets up a business, taking on financial risks in the hope of profit","examples":["The young [entrepreneur] secured funding for her innovative educational technology startup. (=Dịch: Nữ doanh nhân trẻ đã đảm bảo được nguồn vốn cho công ty khởi nghiệp công nghệ giáo dục đổi mới sáng tạo của mình.)","Every successful [entrepreneur] must be willing to learn from repeated failures. (=Dịch: Mọi doanh nhân thành đạt đều phải sẵn sàng học hỏi từ những thất bại lặp đi lặp lại.)","The university provides specialized workshops to help each aspiring [entrepreneur] develop practical skills. (=Dịch: Trường đại học cung cấp các buổi hội thảo chuyên đề để giúp mỗi doanh nhân đầy tham vọng phát triển các kỹ năng thực tế.)"],"ukAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%CA%8Ar%2F"},{"id":"lv_4_143","topic":"Cultural and Historical Exchange","word":"european","pos":"(adj)","ipa":"/ˌjʊr.əˈpiː.ən/","defVi":"thuộc về châu Âu","defEn":"belonging to or relating to the continent of Europe or its people","examples":["She decided to study [european] history during her semester abroad. (=Dịch: Cô ấy quyết định theo học lịch sử châu Âu trong học kỳ du học của mình.)","Many [european] countries have adopted strong environmental protection policies. (=Dịch: Nhiều quốc gia châu Âu đã áp dụng các chính sách bảo vệ môi trường nghiêm ngặt.)","The museum houses a remarkable collection of classical [european] paintings. (=Dịch: Bảo tàng lưu giữ một bộ sưu tập tranh cổ điển châu Âu đáng chú ý.)"],"ukAudio":"/ai_services/tts3/?q=european&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=european&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F"},{"id":"lv_4_144","topic":"Cultural and Historical Exchange","word":"europeans","pos":"(n)","ipa":"/ˌjʊr.əˈpiː.ənz/","defVi":"người châu Âu","defEn":"people who are native to or inhabitants of Europe","examples":["Many [europeans] speak more than two languages fluently. (=Dịch: Nhiều người châu Âu nói trôi chảy hơn hai ngôn ngữ.)","Early [europeans] traded goods such as silk and spices along ancient routes. (=Dịch: Những người châu Âu thời kỳ đầu đã buôn bán các hàng hóa như lụa và gia vị dọc theo các tuyến đường cổ đại.)","The survey compared dietary habits among Asians and [europeans]. (=Dịch: Cuộc khảo sát đã so sánh thói quen ăn uống giữa người châu Á và người châu Âu.)"],"ukAudio":"/ai_services/tts3/?q=europeans&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F","usAudio":"/ai_services/tts3/?q=europeans&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F"},{"id":"lv_4_145","topic":"Cultural and Historical Exchange","word":"evolution","pos":"(n)","ipa":"/ˌɛv.əˈluː.ʃən/","defVi":"sự tiến hóa, sự phát triển dần dần","defEn":"the gradual process of change and development over time, especially in living organisms","examples":["Darwin is best known for his theory of biological [evolution]. (=Dịch: Darwin nổi tiếng nhất với thuyết [tiến hóa] sinh học.)","The museum exhibits the [evolution] of mobile phones over the past decades. (=Dịch: Bảo tàng trưng bày [sự phát triển] của điện thoại di động qua các thập kỷ qua.)","Language undergoes a continuous [evolution] as new words emerge. (=Dịch: Ngôn ngữ trải qua một [quá trình biến đổi] liên tục khi các từ mới xuất hiện.)"],"ukAudio":"/ai_services/tts3/?q=evolution&lang=en-GB&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evolution&lang=en-US&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_146","topic":"Cultural and Historical Exchange","word":"evolve","pos":"(v)","ipa":"/ɪˈvɑːlv/","defVi":"tiến hóa, phát triển dần","defEn":"to develop gradually, especially from a simple to a more complex form","examples":["Scientists study how modern animals [evolve] over millions of years. (=Dịch: Các nhà khoa học nghiên cứu cách các loài động vật hiện đại tiến hóa qua hàng triệu năm.)","The company must [evolve] its business model to survive in the digital age. (=Dịch: Công ty phải phát triển mô hình kinh doanh của mình để tồn tại trong thời đại kỹ thuật số.)","Her initial idea began to [evolve] into a full-scale research project. (=Dịch: Ý tưởng ban đầu của cô ấy đã bắt đầu phát triển thành một dự án nghiên cứu toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=evolve&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F","usAudio":"/ai_services/tts3/?q=evolve&lang=en-US&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F"},{"id":"lv_4_147","topic":"Cultural and Historical Exchange","word":"excavation","pos":"(n)","ipa":"/ˌɛk.skəˈveɪ.ʃən/","defVi":"sự khai quật, hoạt động đào bới khảo cổ","defEn":"the process of digging in the ground to look for old objects or buildings","examples":["The archaeological [excavation] uncovered the ruins of an ancient temple. (=Dịch: Cuộc khai quật khảo cổ học đã phát hiện ra tàn tích của một ngôi đền cổ.)","Workers began the [excavation] for the new building's foundation yesterday. (=Dịch: Các công nhân đã bắt đầu việc đào móng cho tòa nhà mới vào ngày hôm qua.)","Several rare coins were found during the recent [excavation] near the river. (=Dịch: Một số đồng xu hiếm đã được tìm thấy trong cuộc khai quật gần đây ở cạnh bờ sông.)"],"ukAudio":"/ai_services/tts3/?q=excavation&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sk%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=excavation&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sk%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_148","topic":"Cultural and Historical Exchange","word":"exhibit","pos":"(n)","ipa":"/ɪɡˈzɪb.ɪt/","defVi":"hiện vật, vật trưng bày, cuộc triển lãm","defEn":"an object or collection of objects shown publicly in a museum or trade fair","examples":["The interactive science [exhibit] attracted thousands of curious visitors. (=Dịch: Khu triển lãm khoa học tương tác đã thu hút hàng ngàn du khách hiếu kỳ.)","Please do not touch any [exhibit] inside the historical hall. (=Dịch: Vui lòng không chạm vào bất kỳ hiện vật trưng bày nào bên trong sảnh lịch sử.)","The museum opened a new permanent [exhibit] dedicated to dinosaur fossils. (=Dịch: Bảo tàng đã mở một khu trưng bày thường trực mới dành riêng cho các hóa thạch khủng long.)"],"ukAudio":"/ai_services/tts3/?q=exhibit&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exhibit&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAb.%C9%AAt%2F"},{"id":"lv_4_149","topic":"Cultural and Historical Exchange","word":"exile","pos":"(n)","ipa":"/ˈɛɡ.zaɪl/","defVi":"sự lưu đày, tình trạng sống lưu vong","defEn":"a situation in which someone is forced to leave their country, often for political reasons","examples":["The political leader spent over ten years in [exile] before returning home safely. (=Dịch: Nhà lãnh đạo chính trị đã trải qua hơn mười năm sống lưu vong trước khi trở về quê hương an toàn.)","Many famous writers produced their greatest masterpieces while living in [exile]. (=Dịch: Nhiều nhà văn nổi tiếng đã sáng tác những kiệt tác vĩ đại nhất của mình khi sống lưu vong.)","He was forced into [exile] after opposing the policies of the government. (=Dịch: Ông buộc phải đi lưu vong sau khi phản đối các chính sách của chính phủ.)"],"ukAudio":"/ai_services/tts3/?q=exile&lang=en-GB&ipa=%2F%CB%88%C9%9B%C9%A1.za%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=exile&lang=en-US&ipa=%2F%CB%88%C9%9B%C9%A1.za%C9%AAl%2F"},{"id":"lv_4_150","topic":"Cultural and Historical Exchange","word":"exploit","pos":"(v)","ipa":"/ɪkˈsplɔɪt/","defVi":"khai thác; bóc lột","defEn":"to make use of something effectively, or to treat someone unfairly for one's own benefit","examples":["The company seeks to [exploit] renewable energy sources to reduce costs. (=Dịch: Công ty tìm cách khai thác các nguồn năng lượng tái tạo để giảm thiểu chi phí.)","Strict laws are needed to prevent employers from attempting to [exploit] workers. (=Dịch: Cần có các luật lệ nghiêm ngặt để ngăn chặn người sử dụng lao động có ý định bóc lột người lao động.)","Smart investors know how to [exploit] new market opportunities quickly. (=Dịch: Các nhà đầu tư thông minh biết cách tận dụng nhanh chóng các cơ hội thị trường mới.)"],"ukAudio":"/ai_services/tts3/?q=exploit&lang=en-GB&ipa=%2F%C9%AAk%CB%88spl%C9%94%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exploit&lang=en-US&ipa=%2F%C9%AAk%CB%88spl%C9%94%C9%AAt%2F"},{"id":"lv_4_151","topic":"Cultural and Historical Exchange","word":"external","pos":"(adj)","ipa":"/ɪkˈstɜr.nəl/","defVi":"ở bên ngoài, ngoại cảnh hoặc đối ngoại","defEn":"connected with or located on the outside of something","examples":["The [external] walls of the building need a fresh coat of paint. (=Dịch: Các bức tường bên ngoài của tòa nhà cần một lớp sơn mới.)","A company may hire an [external] consultant to evaluate its performance. (=Dịch: Một công ty có thể thuê một chuyên gia tư vấn bên ngoài để đánh giá hiệu quả hoạt động của mình.)","Students are sometimes evaluated by an [external] examiner. (=Dịch: Học sinh đôi khi được đánh giá bởi một giám khảo bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9Cr.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9Cr.n%C9%99l%2F"},{"id":"lv_4_152","topic":"Cultural and Historical Exchange","word":"fashionable","pos":"(adj)","ipa":"/ˈfæʃ.nə.bəl/","defVi":"hợp thời trang, sành điệu, theo xu hướng","defEn":"popular, stylish, and currently in fashion","examples":["She always wears [fashionable] clothes that catch everyone's attention. (=Dịch: Cô ấy luôn mặc những bộ quần áo thời thượng thu hút sự chú ý của mọi người.)","The downtown district is famous for its [fashionable] cafes and boutiques. (=Dịch: Khu vực trung tâm thành phố nổi tiếng với các quán cà phê và cửa hàng thời trang sành điệu.)","Eating organic food has become increasingly [fashionable] among young urbanites. (=Dịch: Ăn thực phẩm hữu cơ đang ngày càng trở thành xu hướng phổ biến trong giới trẻ thành thị.)"],"ukAudio":"/ai_services/tts3/?q=fashionable&lang=en-GB&ipa=%2F%CB%88f%C3%A6%CA%83.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fashionable&lang=en-US&ipa=%2F%CB%88f%C3%A6%CA%83.n%C9%99.b%C9%99l%2F"},{"id":"lv_4_153","topic":"Cultural and Historical Exchange","word":"feather","pos":"(n)","ipa":"/ˈfɛð.ɚ/","defVi":"lông vũ","defEn":"one of the soft, light things that grow from and cover a bird's skin","examples":["She found a beautiful blue [feather] on the forest path. (=Dịch: Cô ấy tìm thấy một chiếc lông vũ màu xanh tuyệt đẹp trên con đường trong rừng.)","Penguins have dense [feather] layers that keep them warm in freezing water. (=Dịch: Chim cánh cụt có các lớp lông vũ dày giúp giữ ấm cho chúng trong làn nước băng giá.)","The traditional pillow was filled with soft duck [feather] stuffing. (=Dịch: Chiếc gối truyền thống được nhồi bằng lông vịt mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=feather&lang=en-GB&ipa=%2F%CB%88f%C9%9B%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=feather&lang=en-US&ipa=%2F%CB%88f%C9%9B%C3%B0.%C9%9A%2F"},{"id":"lv_4_154","topic":"Cultural and Historical Exchange","word":"fieldwork","pos":"(n)","ipa":"/ˈfild.wɝk/","defVi":"công tác điền dã, nghiên cứu thực địa","defEn":"research or study done in the real world rather than in a classroom or laboratory","examples":["The biology students spent two weeks doing [fieldwork] in the rainforest. (=Dịch: Các sinh viên ngành sinh học đã dành hai tuần thực hiện nghiên cứu thực địa trong rừng nhiệt đới.)","Conducting [fieldwork] helped the researchers collect primary data directly from residents. (=Dịch: Việc tiến hành nghiên cứu thực địa đã giúp các nhà nghiên cứu thu thập dữ liệu sơ cấp trực tiếp từ người dân.)","Her doctoral dissertation relied heavily on anthropological [fieldwork]. (=Dịch: Luận án tiến sĩ của cô dựa nhiều vào nghiên cứu thực địa nhân chủng học.)"],"ukAudio":"/ai_services/tts3/?q=fieldwork&lang=en-GB&ipa=%2F%CB%88fild.w%C9%9Dk%2F","usAudio":"/ai_services/tts3/?q=fieldwork&lang=en-US&ipa=%2F%CB%88fild.w%C9%9Dk%2F"},{"id":"lv_4_155","topic":"Cultural and Historical Exchange","word":"fifteenth","pos":"(adj)","ipa":"/ˌfɪfˈtinθ/","defVi":"thứ mười lăm","defEn":"positioned in the place that corresponds to number fifteen","examples":["Today marks the [fifteenth] anniversary of the company's founding. (=Dịch: Hôm nay đánh dấu kỷ niệm lần thứ mười lăm ngày thành lập công ty.)","Her office is located on the [fifteenth] floor of the commercial tower. (=Dịch: Văn phòng của cô nằm ở tầng mười lăm của tòa tháp thương mại.)","He finished in [fifteenth] place out of hundreds of marathon runners. (=Dịch: Anh đã về đích ở vị trí thứ mười lăm trong số hàng trăm vận động viên chạy marathon.)"],"ukAudio":"/ai_services/tts3/?q=fifteenth&lang=en-GB&ipa=%2F%CB%8Cf%C9%AAf%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fifteenth&lang=en-US&ipa=%2F%CB%8Cf%C9%AAf%CB%88tin%CE%B8%2F"},{"id":"lv_4_156","topic":"Cultural and Historical Exchange","word":"firework","pos":"(n)","ipa":"/ˈfaɪr.wɝːk/","defVi":"pháo hoa","defEn":"a small device containing chemicals that burns or explodes to make loud noises and bright colorful lights in the sky","examples":["A spectacular [firework] lit up the night sky during the festival. (=Dịch: Một chùm pháo hoa ngoạn mục đã thắp sáng bầu trời đêm trong suốt lễ hội.)","Setting off a [firework] indoors is extremely dangerous and strictly prohibited. (=Dịch: Đốt pháo hoa trong nhà là cực kỳ nguy hiểm và bị nghiêm cấm hoàn toàn.)","The grand finale featured a massive [firework] that amazed the entire crowd. (=Dịch: Màn kết thúc hoành tráng nổi bật với chùm pháo hoa khổng lồ khiến toàn bộ đám đông kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=firework&lang=en-GB&ipa=%2F%CB%88fa%C9%AAr.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=firework&lang=en-US&ipa=%2F%CB%88fa%C9%AAr.w%C9%9D%CB%90k%2F"},{"id":"lv_4_157","topic":"Cultural and Historical Exchange","word":"flock","pos":"(v)","ipa":"/flɑːk/","defVi":"đổ xô, tụ tập đông đúc","defEn":"to gather or move together in large numbers","examples":["Thousands of tourists [flock] to the coastal town every summer. (=Dịch: Hàng ngàn du khách đổ xô về thị trấn ven biển vào mỗi mùa hè.)","Shoppers will [flock] to the mall during the annual clearance sale. (=Dịch: Người mua sắm sẽ đổ xô đến trung tâm thương mại trong đợt giảm giá xả kho hàng năm.)","Fans began to [flock] outside the stadium hours before the concert started. (=Dịch: Người hâm mộ bắt đầu tụ tập đông đảo bên ngoài sân vận động vài giờ trước khi buổi hòa nhạc bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=flock&lang=en-GB&ipa=%2Ffl%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=flock&lang=en-US&ipa=%2Ffl%C9%91%CB%90k%2F"},{"id":"lv_4_158","topic":"Cultural and Historical Exchange","word":"flute","pos":"(n)","ipa":"/fluːt/","defVi":"cây sáo, ống sáo","defEn":"a musical wind instrument played by blowing across a hole near one end","examples":["She has been practicing the [flute] since she was eight years old. (=Dịch: Cô ấy đã luyện tập thổi sáo từ khi mới tám tuổi.)","The orchestra features a solo performance by the principal [flute] player. (=Dịch: Dàn nhạc có một màn độc tấu của nghệ sĩ sáo chính.)","He carefully packed his silver [flute] into its velvet-lined case. (=Dịch: Anh ấy cẩn thận cất cây sáo bạc của mình vào chiếc hộp lót nhung.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflu%CB%90t%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflu%CB%90t%2F"},{"id":"lv_4_159","topic":"Cultural and Historical Exchange","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập lại","defEn":"to bend something flexible over on itself so that one part covers another","examples":["Please [fold] your clothes neatly before putting them into the suitcase. (=Dịch: Vui lòng gấp quần áo gọn gàng trước khi cho vào vali.)","He decided to [fold] the map and put it in his pocket. (=Dịch: Anh ấy quyết định gấp tấm bản đồ lại và cho vào túi.)","The young boy learned how to [fold] paper into complex origami shapes. (=Dịch: Cậu bé đã học cách gấp giấy thành các hình origami phức tạp.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_4_160","topic":"Cultural and Historical Exchange","word":"footbridge","pos":"(n)","ipa":"/ˈfʊt.brɪdʒ/","defVi":"cầu đi bộ","defEn":"a narrow bridge designed only for pedestrians","examples":["Pedestrians can safely cross the busy highway using the new [footbridge]. (=Dịch: Người đi bộ có thể băng qua đường cao tốc đông đúc một cách an toàn bằng cách sử dụng cầu đi bộ mới.)","A charming wooden [footbridge] spans the small stream in the park. (=Dịch: Một cây cầu đi bộ bằng gỗ duyên dáng bắc ngang qua con suối nhỏ trong công viên.)","The city plans to construct a covered [footbridge] near the train station. (=Dịch: Thành phố có kế hoạch xây dựng một cây cầu đi bộ có mái che gần nhà ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=footbridge&lang=en-GB&ipa=%2F%CB%88f%CA%8At.br%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=footbridge&lang=en-US&ipa=%2F%CB%88f%CA%8At.br%C9%AAd%CA%92%2F"},{"id":"lv_4_161","topic":"Cultural and Historical Exchange","word":"footprint","pos":"(n)","ipa":"/ˈfʊt.prɪnt/","defVi":"dấu chân; dấu ấn tác động môi trường","defEn":"a mark left by a foot or shoe, or the amount of impact something has on the environment","examples":["We followed a trail of fresh [footprints] in the snow until we reached the cabin. (=Dịch: Chúng tôi đã lần theo dấu vết của những dấu chân mới trên tuyết cho đến khi tới được căn nhà gỗ.)","Many companies are striving to reduce their environmental [footprint] by using renewable energy. (=Dịch: Nhiều công ty đang nỗ lực giảm thiểu tác động đến môi trường bằng cách sử dụng năng lượng tái tạo.)","The giant dinosaur left a deep [footprint] that fossilized over millions of years. (=Dịch: Con khủng long khổng lồ đã để lại một dấu chân sâu và hóa thạch qua hàng triệu năm.)"],"ukAudio":"/ai_services/tts3/?q=footprint&lang=en-GB&ipa=%2F%CB%88f%CA%8At.pr%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=footprint&lang=en-US&ipa=%2F%CB%88f%CA%8At.pr%C9%AAnt%2F"},{"id":"lv_4_162","topic":"Cultural and Historical Exchange","word":"forecast","pos":"(v)","ipa":"/ˈfɔrˌkæst/","defVi":"dự báo, dự đoán","defEn":"to predict what will happen in the future, especially regarding weather or business","examples":["Meteorologists [forecast] heavy snow for the northern regions this weekend. (=Dịch: Các nhà khí tượng học dự báo tuyết rơi dày ở các khu vực phía bắc vào cuối tuần này.)","Economists [forecast] a moderate growth rate for the coming quarter. (=Dịch: Các nhà kinh tế dự báo tốc độ tăng trưởng vừa phải cho quý tới.)","It is difficult to [forecast] how consumers will react to the new tax policy. (=Dịch: Rất khó để dự báo người tiêu dùng sẽ phản ứng như thế nào trước chính sách thuế mới.)"],"ukAudio":"/ai_services/tts3/?q=forecast&lang=en-GB&ipa=%2F%CB%88f%C9%94r%CB%8Ck%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=forecast&lang=en-US&ipa=%2F%CB%88f%C9%94r%CB%8Ck%C3%A6st%2F"},{"id":"lv_4_163","topic":"Cultural and Historical Exchange","word":"formation","pos":"(n)","ipa":"/fɔːrˈmeɪ.ʃən/","defVi":"sự hình thành, cấu trúc, đội hình","defEn":"the process of creating or developing something, or the way something is arranged","examples":["Geologists study the [formation] of mountain ranges over millions of years. (=Dịch: Các nhà địa chất nghiên cứu sự hình thành của các dãy núi qua hàng triệu năm.)","The aircraft flew in a triangular [formation] during the military airshow. (=Dịch: Những chiếc máy bay đã bay theo đội hình tam giác trong suốt buổi trình diễn hàng không quân sự.)","Good parenting plays a vital role in the [formation] of a child's character. (=Dịch: Cách nuôi dạy con tốt đóng vai trò quan trọng trong sự hình thành nhân cách của một đứa trẻ.)"],"ukAudio":"/ai_services/tts3/?q=formation&lang=en-GB&ipa=%2Ff%C9%94%CB%90r%CB%88me%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=formation&lang=en-US&ipa=%2Ff%C9%94%CB%90r%CB%88me%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_164","topic":"Cultural and Historical Exchange","word":"fortune","pos":"(n)","ipa":"/ˈfɔr.tʃən/","defVi":"tài sản lớn, gia tài","defEn":"a large amount of money or valuable possessions","examples":["He made a vast [fortune] by investing early in technology companies. (=Dịch: Anh ấy đã kiếm được một gia tài khổng lồ nhờ đầu tư sớm vào các công ty công nghệ.)","Buying a house in the city center costs a small [fortune] nowadays. (=Dịch: Mua một ngôi nhà ở trung tâm thành phố ngày nay tốn cả một gia tài.)","She inherited a massive [fortune] from her late grandfather. (=Dịch: Cô ấy đã thừa kế một khối tài sản khổng lồ từ người ông quá cố của mình.)"],"ukAudio":"/ai_services/tts3/?q=fortune&lang=en-GB&ipa=%2F%CB%88f%C9%94r.t%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=fortune&lang=en-US&ipa=%2F%CB%88f%C9%94r.t%CA%83%C9%99n%2F"},{"id":"lv_4_165","topic":"Cultural and Historical Exchange","word":"found","pos":"(v)","ipa":"/faʊnd/","defVi":"thành lập, sáng lập","defEn":"to establish an organization, institution, or company","examples":["The university was [found]ed by a group of local scholars in 1850. (=Dịch: Trường đại học được thành lập bởi một nhóm học giả địa phương vào năm 1850.)","They hope to [found] a non-profit organization to support underprivileged children. (=Dịch: Họ hy vọng sẽ thành lập một tổ chức phi lợi nhuận để hỗ trợ trẻ em có hoàn cảnh khó khăn.)","The settlers arrived in the valley and decided to [found] a new town. (=Dịch: Những người khai hoang đã đến thung lũng và quyết định thành lập một thị trấn mới.)"],"ukAudio":"/ai_services/tts3/?q=found&lang=en-GB&ipa=%2Ffa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=found&lang=en-US&ipa=%2Ffa%CA%8And%2F"},{"id":"lv_4_166","topic":"Cultural and Historical Exchange","word":"foundation","pos":"(n)","ipa":"/faʊnˈdeɪ.ʃən/","defVi":"nền tảng, móng nhà, quỹ tài trợ","defEn":"the basic structure, idea, or principle on which something is built or developed","examples":["Trust and communication are the [foundation] of any healthy relationship. (=Dịch: Sự tin tưởng và giao tiếp là nền tảng của bất kỳ mối quan hệ lành mạnh nào.)","The builders laid a solid concrete [foundation] for the new skyscraper. (=Dịch: Những người thợ xây đã đổ một nền móng bê tông vững chắc cho tòa nhà chọc trời mới.)","She established a charitable [foundation] to help underprivileged children. (=Dịch: Cô ấy đã thành lập một quỹ từ thiện để giúp đỡ những trẻ em có hoàn cảnh khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=foundation&lang=en-GB&ipa=%2Ffa%CA%8An%CB%88de%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=foundation&lang=en-US&ipa=%2Ffa%CA%8An%CB%88de%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_167","topic":"Cultural and Historical Exchange","word":"fourth","pos":"(adj)","ipa":"/fɔːrθ/","defVi":"thứ tư (trong chuỗi thứ tự)","defEn":"constituting number four in a sequence; 4th","examples":["This is the [fourth] time this month that the train has been delayed. (=Dịch: Đây là lần thứ tư trong tháng này chuyến tàu bị hoãn.)","She finished in [fourth] place in the international swimming competition. (=Dịch: Cô ấy về đích ở vị trí thứ tư trong cuộc thi bơi lội quốc tế.)","Our office is located on the [fourth] floor of the commercial building. (=Dịch: Văn phòng của chúng tôi nằm ở tầng bốn của tòa nhà thương mại.)"],"ukAudio":"/ai_services/tts3/?q=fourth&lang=en-GB&ipa=%2Ff%C9%94%CB%90r%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fourth&lang=en-US&ipa=%2Ff%C9%94%CB%90r%CE%B8%2F"},{"id":"lv_4_168","topic":"Cultural and Historical Exchange","word":"fragile","pos":"(adj)","ipa":"/ˈfrædʒ.əl/","defVi":"dễ vỡ, mỏng manh, yếu ớt","defEn":"easily broken, damaged, or harmed","examples":["Please handle the box with care because it contains [fragile] glassware. (=Dịch: Xin vui lòng nhẹ tay với chiếc hộp này vì bên trong chứa đồ thủy tinh dễ vỡ.)","The region's [fragile] ecosystem is under severe threat from pollution. (=Dịch: Hệ sinh thái mỏng manh của khu vực đang bị đe dọa nghiêm trọng bởi tình trạng ô nhiễm.)","The two countries signed a [fragile] peace agreement after months of talks. (=Dịch: Hai quốc gia đã ký một thỏa thuận hòa bình mong manh sau nhiều tháng đàm phán.)"],"ukAudio":"/ai_services/tts3/?q=fragile&lang=en-GB&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fragile&lang=en-US&ipa=%2F%CB%88fr%C3%A6d%CA%92.%C9%99l%2F"},{"id":"lv_4_169","topic":"Cultural and Historical Exchange","word":"frame","pos":"(n)","ipa":"/freɪm/","defVi":"khung (tranh, ảnh, cửa, nhà), sườn kết cấu","defEn":"a rigid structure that surrounds or supports something such as a picture, window, or building","examples":["She chose an elegant wooden [frame] for her family portrait. (=Dịch: Cô ấy đã chọn một chiếc khung gỗ trang nhã cho bức ảnh chân dung gia đình mình.)","The steel [frame] of the skyscraper was erected in just three months. (=Dịch: Khung thép của tòa nhà chọc trời đã được dựng lên chỉ trong vòng ba tháng.)","A broken bicycle [frame] made it impossible for him to continue the race. (=Dịch: Khung xe đạp bị gãy khiến anh ấy không thể tiếp tục cuộc đua.)"],"ukAudio":"/ai_services/tts3/?q=frame&lang=en-GB&ipa=%2Ffre%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=frame&lang=en-US&ipa=%2Ffre%C9%AAm%2F"},{"id":"lv_4_170","topic":"Cultural and Historical Exchange","word":"france","pos":"(n)","ipa":"/fræns/","defVi":"nước Pháp","defEn":"a country in Western Europe known for its art, cuisine, and history","examples":["Paris, the capital of [France], attracts millions of international travelers. (=Dịch: Paris, thủ đô của nước Pháp, thu hút hàng triệu du khách quốc tế.)","[France] is internationally renowned for its fashion, wine, and culinary culture. (=Dịch: Nước Pháp nổi tiếng quốc tế về thời trang, rượu vang và văn hóa ẩm thực.)","She spent a semester studying literature in [France]. (=Dịch: Cô ấy đã dành một học kỳ để theo học ngành văn học ở Pháp.)"],"ukAudio":"/ai_services/tts3/?q=france&lang=en-GB&ipa=%2Ffr%C3%A6ns%2F","usAudio":"/ai_services/tts3/?q=france&lang=en-US&ipa=%2Ffr%C3%A6ns%2F"},{"id":"lv_4_171","topic":"Cultural and Historical Exchange","word":"friendship","pos":"(n)","ipa":"/ˈfrɛnd.ʃɪp/","defVi":"tình bạn, tình hữu nghị","defEn":"a close and supportive relationship between friends","examples":["Their strong [friendship] developed during their first year of studying abroad. (=Dịch: Tình bạn bền chặt của họ đã phát triển trong suốt năm đầu tiên đi du học.)","True [friendship] requires mutual trust, open communication, and emotional support. (=Dịch: Tình bạn đích thực đòi hỏi sự tin tưởng lẫn nhau, giao tiếp cởi mở và hỗ trợ về mặt cảm xúc.)","The international exchange program aims to build lasting [friendship] between students of both nations. (=Dịch: Chương trình trao đổi quốc tế nhằm mục đích xây dựng tình bạn lâu dài giữa học sinh, sinh viên của cả hai quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=friendship&lang=en-GB&ipa=%2F%CB%88fr%C9%9Bnd.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=friendship&lang=en-US&ipa=%2F%CB%88fr%C9%9Bnd.%CA%83%C9%AAp%2F"},{"id":"lv_4_172","topic":"Cultural and Historical Exchange","word":"furnish","pos":"(v)","ipa":"/ˈfɜr.nɪʃ/","defVi":"trang bị nội thất, cung cấp","defEn":"to put furniture into a room or building, or to supply something needed","examples":["It will cost a lot of money to [furnish] the new apartment. (=Dịch: Sẽ tốn rất nhiều tiền để trang bị nội thất cho căn hộ mới.)","The company agreed to [furnish] all the necessary equipment for the project. (=Dịch: Công ty đã đồng ý cung cấp mọi thiết bị cần thiết cho dự án.)","They decided to [furnish] the guest room with modern wooden pieces. (=Dịch: Họ quyết định bài trí phòng khách bằng những món đồ gỗ hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=furnish&lang=en-GB&ipa=%2F%CB%88f%C9%9Cr.n%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=furnish&lang=en-US&ipa=%2F%CB%88f%C9%9Cr.n%C9%AA%CA%83%2F"},{"id":"lv_4_173","topic":"Cultural and Historical Exchange","word":"garment","pos":"(n)","ipa":"/ˈɡɑːr.mənt/","defVi":"quần áo, trang phục","defEn":"an item of clothing","examples":["The boutique specializes in silk [garment] designs for formal events. (=Dịch: Cửa hàng thời trang này chuyên về các thiết kế trang phục lụa cho các sự kiện trang trọng.)","Workers in the [garment] industry are demanding better working conditions. (=Dịch: Các công nhân trong ngành may mặc đang yêu cầu những điều kiện làm việc tốt hơn.)","Please handle this delicate [garment] with care to prevent any damage. (=Dịch: Xin vui lòng nhẹ tay với bộ quần áo mỏng manh này để tránh làm hỏng.)"],"ukAudio":"/ai_services/tts3/?q=garment&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=garment&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.m%C9%99nt%2F"},{"id":"lv_4_174","topic":"Cultural and Historical Exchange","word":"gatherer","pos":"(n)","ipa":"/ˈɡæð.ɚ.ɚ/","defVi":"người hái lượm, người thu gom","defEn":"a person who collects food, herbs, or other materials from the wild","examples":["Ancient humans lived as hunter-[gatherer] tribes before farming was developed. (=Dịch: Con người thời cổ đại sống thành các bộ lạc săn bắt - hái lượm trước khi nông nghiệp phát triển.)","The traditional [gatherer] knows exactly which wild mushrooms are safe to eat. (=Dịch: Người hái lượm truyền thống biết chính xác loại nấm dại nào an toàn để ăn.)","As a data [gatherer], his job was to collect feedback from consumers across the city. (=Dịch: Với vai trò là một người thu thập dữ liệu, công việc của anh ấy là thu thập phản hồi từ người tiêu dùng trên toàn thành phố.)"],"ukAudio":"/ai_services/tts3/?q=gatherer&lang=en-GB&ipa=%2F%CB%88%C9%A1%C3%A6%C3%B0.%C9%9A.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gatherer&lang=en-US&ipa=%2F%CB%88%C9%A1%C3%A6%C3%B0.%C9%9A.%C9%9A%2F"},{"id":"lv_4_175","topic":"Cultural and Historical Exchange","word":"generation","pos":"(n)","ipa":"/ˌdʒɛn.əˈreɪ.ʃən/","defVi":"thế hệ","defEn":"all of the people born and living at about the same time","examples":["The younger [generation] is very comfortable using modern digital devices. (=Dịch: Thế hệ trẻ rất thành thạo và thoải mái trong việc sử dụng các thiết bị kỹ thuật số hiện đại.)","Stories and traditions have been passed down from [generation] to generation. (=Dịch: Những câu chuyện và truyền thống đã được truyền từ thế hệ này sang thế hệ khác.)","This breakthrough will benefit future [generation]s for decades to come. (=Dịch: Bước đột phá này sẽ mang lại lợi ích cho các thế hệ tương lai trong nhiều thập kỷ tới.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_176","topic":"Cultural and Historical Exchange","word":"genre","pos":"(n)","ipa":"/ˈʒɑːn.rə/","defVi":"thể loại (nghệ thuật, âm nhạc, văn học)","defEn":"a particular style or category of art, music, or literature","examples":["Science fiction has always been my favorite literary [genre]. (=Dịch: Khoa học viễn tưởng luôn là thể loại văn học yêu thích của tôi.)","The director decided to experiment with a new film [genre] for his latest project. (=Dịch: Đạo diễn đã quyết định thử nghiệm một thể loại phim mới cho dự án mới nhất của mình.)","Jazz is a complex musical [genre] that originated in the United States. (=Dịch: Jazz là một thể loại âm nhạc phức tạp có nguồn gốc từ Hoa Kỳ.)"],"ukAudio":"/ai_services/tts3/?q=genre&lang=en-GB&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F","usAudio":"/ai_services/tts3/?q=genre&lang=en-US&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F"},{"id":"lv_4_177","topic":"Cultural and Historical Exchange","word":"german","pos":"(adj)","ipa":"/ˈdʒɝː.mən/","defVi":"(thuộc) nước Đức, người Đức hoặc tiếng Đức","defEn":"relating to Germany, its people, or its language","examples":["She has been studying the [German] language for two years. (=Dịch: Cô ấy đã học tiếng Đức được hai năm.)","Many consumers trust [German] engineering for its precision and durability. (=Dịch: Nhiều người tiêu dùng tin tưởng kỹ thuật của Đức nhờ độ chính xác và độ bền.)","We tried traditional [German] sausages during our trip to Berlin. (=Dịch: Chúng tôi đã thưởng thức món xúc xích Đức truyền thống trong chuyến đi đến Berlin.)"],"ukAudio":"/ai_services/tts3/?q=german&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=german&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99n%2F"},{"id":"lv_4_178","topic":"Cultural and Historical Exchange","word":"germany","pos":"(n)","ipa":"/ˈdʒɝː.mə.ni/","defVi":"nước Đức","defEn":"a country in Central Europe","examples":["Many international students choose to pursue engineering degrees in [Germany]. (=Dịch: Nhiều sinh viên quốc tế lựa chọn theo học các ngành kỹ thuật tại Đức.)","[Germany] is well known for its strong automotive industry and rich history. (=Dịch: Nước Đức rất nổi tiếng với ngành công nghiệp ô tô hùng mạnh và lịch sử phong phú.)","They traveled across [Germany] by train during their summer vacation. (=Dịch: Họ đã đi du lịch khắp nước Đức bằng tàu hỏa trong kỳ nghỉ hè của mình.)"],"ukAudio":"/ai_services/tts3/?q=germany&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=germany&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F"},{"id":"lv_4_179","topic":"Cultural and Historical Exchange","word":"gradually","pos":"(adv)","ipa":"/ˈɡrædʒ.u.ə.li/","defVi":"dần dần, từ từ","defEn":"slowly, over a period of time","examples":["The weather is [gradually] getting warmer as spring approaches. (=Dịch: Thời tiết đang dần ấm lên khi mùa xuân đến gần.)","His health [gradually] improved after following the doctor's advice. (=Dịch: Sức khỏe của anh ấy đã dần cải thiện sau khi làm theo lời khuyên của bác sĩ.)","She [gradually] adapted to the fast-paced lifestyle of the city. (=Dịch: Cô ấy đã dần thích nghi với nhịp sống hối hả của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=gradually&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=gradually&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F"},{"id":"lv_4_180","topic":"Cultural and Historical Exchange","word":"graduate","pos":"(v)","ipa":"/ˈɡræ.dʒu.eɪt/","defVi":"tốt nghiệp","defEn":"to complete a degree or course of study at a school, college, or university","examples":["She hopes to [graduate] from university with high honors next summer. (=Dịch: Cô ấy hy vọng sẽ tốt nghiệp đại học với tấm bằng loại ưu vào mùa hè tới.)","After they [graduate], many students choose to travel abroad. (=Dịch: Sau khi tốt nghiệp, nhiều sinh viên lựa chọn đi du lịch nước ngoài.)","He will [graduate] from medical school at the end of this year. (=Dịch: Anh ấy sẽ tốt nghiệp trường y vào cuối năm nay.)"],"ukAudio":"/ai_services/tts3/?q=graduate&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6.d%CA%92u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=graduate&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6.d%CA%92u.e%C9%AAt%2F"},{"id":"lv_4_181","topic":"Cultural and Historical Exchange","word":"grain","pos":"(n)","ipa":"/ɡreɪn/","defVi":"ngũ cốc, hạt thóc/gạo","defEn":"the seeds of crops such as wheat, rice, and corn used as food","examples":["Whole [grain] foods are an essential part of a balanced and healthy diet. (=Dịch: Thực phẩm từ ngũ cốc nguyên hạt là một phần thiết yếu của một chế độ ăn uống cân bằng và lành mạnh.)","The country exports large quantities of [grain] to international markets every year. (=Dịch: Đất nước này xuất khẩu một lượng lớn ngũ cốc sang các thị trường quốc tế mỗi năm.)","Poor weather conditions caused serious damage to the annual [grain] harvest. (=Dịch: Điều kiện thời tiết xấu đã gây thiệt hại nghiêm trọng cho vụ thu hoạch ngũ cốc hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=grain&lang=en-GB&ipa=%2F%C9%A1re%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=grain&lang=en-US&ipa=%2F%C9%A1re%C9%AAn%2F"},{"id":"lv_4_182","topic":"Cultural and Historical Exchange","word":"grazing","pos":"(v)","ipa":"/ˈɡreɪ.zɪŋ/","defVi":"gặm cỏ, chăn thả","defEn":"eating grass or other plants growing in a field (present participle of graze)","examples":["A herd of cows was peacefully [grazing] on the green hillside. (=Dịch: Một đàn bò đang gặm cỏ yên bình trên sườn đồi xanh ngát.)","Farmers restrict livestock from [grazing] too long in one meadow. (=Dịch: Nông dân hạn chế không cho gia súc gặm cỏ quá lâu trên một đồng cỏ.)","We saw several deer [grazing] near the edge of the forest. (=Dịch: Chúng tôi đã thấy vài con hươu đang gặm cỏ gần bìa rừng.)"],"ukAudio":"/ai_services/tts3/?q=grazing&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AA.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=grazing&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AA.z%C9%AA%C5%8B%2F"},{"id":"lv_4_183","topic":"Cultural and Historical Exchange","word":"greatly","pos":"(adv)","ipa":"/ˈɡreɪt.li/","defVi":"rất nhiều, vô cùng","defEn":"very much or to a large extent","examples":["His generous support [greatly] contributed to our team's victory. (=Dịch: Sự hỗ trợ hào phóng của anh ấy đã đóng góp rất lớn vào chiến thắng của đội chúng tôi.)","I [greatly] appreciate your assistance with this difficult task. (=Dịch: Tôi vô cùng trân trọng sự giúp đỡ của bạn đối với nhiệm vụ khó khăn này.)","The new regulations will [greatly] affect small businesses. (=Dịch: Các quy định mới sẽ ảnh hưởng rất lớn đến các doanh nghiệp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=greatly&lang=en-GB&ipa=%2F%CB%88%C9%A1re%C9%AAt.li%2F","usAudio":"/ai_services/tts3/?q=greatly&lang=en-US&ipa=%2F%CB%88%C9%A1re%C9%AAt.li%2F"},{"id":"lv_4_184","topic":"Cultural and Historical Exchange","word":"greece","pos":"(n)","ipa":"/ɡris/","defVi":"nước Hy Lạp","defEn":"a country in southeastern Europe known for its ancient history and islands","examples":["Millions of tourists visit [Greece] every year to see ancient monuments like the Parthenon. (=Dịch: Hàng triệu du khách ghé thăm Hy Lạp mỗi năm để chiêm ngưỡng các di tích cổ xưa như đền Parthenon.)","Philosophy and democracy have deep roots in ancient [Greece]. (=Dịch: Triết học và nền dân chủ có nguồn gốc sâu xa từ Hy Lạp cổ đại.)","They spent their honeymoon relaxing on the sunny islands of [Greece]. (=Dịch: Họ đã trải qua tuần trăng mật thư giãn trên những hòn đảo đầy nắng của Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greece&lang=en-GB&ipa=%2F%C9%A1ris%2F","usAudio":"/ai_services/tts3/?q=greece&lang=en-US&ipa=%2F%C9%A1ris%2F"},{"id":"lv_4_185","topic":"Cultural and Historical Exchange","word":"greek","pos":"(n)","ipa":"/ɡriːk/","defVi":"người Hy Lạp, tiếng Hy Lạp","defEn":"a person from Greece or the language spoken there","examples":["He is studying ancient [Greek] to better understand classical philosophy. (=Dịch: Anh ấy đang học tiếng Hy Lạp cổ đại để hiểu rõ hơn về triết học cổ điển.)","The restaurant is run by a native [Greek] who prepares authentic Mediterranean dishes. (=Dịch: Nhà hàng được điều hành bởi một người Hy Lạp bản xứ, người chuyên chuẩn bị các món ăn Địa Trung Hải đích thực.)","Many modern English scientific terms are derived from [Greek]. (=Dịch: Nhiều thuật ngữ khoa học tiếng Anh hiện đại có nguồn gốc từ tiếng Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greek&lang=en-GB&ipa=%2F%C9%A1ri%CB%90k%2F","usAudio":"/ai_services/tts3/?q=greek&lang=en-US&ipa=%2F%C9%A1ri%CB%90k%2F"},{"id":"lv_4_186","topic":"Cultural and Historical Exchange","word":"grind","pos":"(v)","ipa":"/ɡraɪnd/","defVi":"xay, nghiền nhỏ","defEn":"to break something into tiny pieces or powder by crushing it","examples":["She likes to [grind] fresh coffee beans every morning. (=Dịch: Cô ấy thích xay hạt cà phê tươi mỗi sáng.)","The machine is used to [grind] wheat into flour. (=Dịch: Cỗ máy này được sử dụng để nghiền lúa mì thành bột mì.)","People under severe stress often [grind] their teeth during sleep. (=Dịch: Những người bị căng thẳng nghiêm trọng thường nghiến răng khi ngủ.)"],"ukAudio":"/ai_services/tts3/?q=grind&lang=en-GB&ipa=%2F%C9%A1ra%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=grind&lang=en-US&ipa=%2F%C9%A1ra%C9%AAnd%2F"},{"id":"lv_4_187","topic":"Cultural and Historical Exchange","word":"guardian","pos":"(n)","ipa":"/ˈɡɑːr.di.ən/","defVi":"người giám hộ, người bảo hộ","defEn":"a person who protects someone or something, or has legal responsibility for a child","examples":["After the parents passed away, the aunt was appointed as legal [guardian]. (=Dịch: Sau khi cha mẹ qua đời, người dì đã được chỉ định làm người giám hộ hợp pháp.)","Lighthouses serve as a [guardian] for ships navigating dangerous coasts. (=Dịch: Những ngọn hải đăng đóng vai trò như người bảo vệ cho các con tàu định hướng qua các bờ biển nguy hiểm.)","The museum acts as a [guardian] of national cultural heritage. (=Dịch: Bảo tàng đóng vai trò là nơi gìn giữ di sản văn hóa quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=guardian&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.di.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=guardian&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.di.%C9%99n%2F"},{"id":"lv_4_188","topic":"Cultural and Historical Exchange","word":"handbag","pos":"(n)","ipa":"/ˈhænd.bæɡ/","defVi":"túi xách tay","defEn":"a small bag used especially by women for carrying personal items","examples":["She left her leather [handbag] on the back of the chair. (=Dịch: Cô ấy đã để chiếc túi xách da ở lưng ghế.)","He searched through his [handbag] to find his keys and wallet. (=Dịch: Anh ấy lục tìm trong túi xách của mình để tìm chìa khóa và ví tiền.)","She bought a designer [handbag] as a gift to celebrate her promotion. (=Dịch: Cô ấy đã mua một chiếc túi xách hàng hiệu làm quà để ăn mừng việc mình được thăng chức.)"],"ukAudio":"/ai_services/tts3/?q=handbag&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=handbag&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.b%C3%A6%C9%A1%2F"},{"id":"lv_4_189","topic":"Cultural and Historical Exchange","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay","defEn":"a document distributed to people, especially to students or meeting attendees","examples":["The teacher distributed a [handout] summarizing the main points of the lesson. (=Dịch: Giáo viên đã phát một tài liệu phát tay tóm tắt các điểm chính của bài học.)","Please refer to the [handout] for further details about the project. (=Dịch: Vui lòng tham khảo tài liệu phát tay để biết thêm chi tiết về dự án.)","He forgot to bring his [handout] to the presentation. (=Dịch: Anh ấy đã quên mang tài liệu phát tay của mình đến buổi thuyết trình.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_4_190","topic":"Cultural and Historical Exchange","word":"hang","pos":"(v)","ipa":"/hæŋ/","defVi":"treo, móc lên","defEn":"to fasten or attach something from above so that the lower part is free","examples":["They decided to [hang] family portraits along the hallway wall. (=Dịch: Họ quyết định treo những bức chân dung gia đình dọc theo bức tường hành lang.)","Please [hang] your coat on the rack near the entrance. (=Dịch: Vui lòng treo áo khoác của bạn lên giá gần lối vào.)","Heavy curtains [hang] across the large windows to block the sunlight. (=Dịch: Những tấm rèm dày rủ xuống qua các cửa sổ lớn để cản ánh nắng mặt trời.)"],"ukAudio":"/ai_services/tts3/?q=hang&lang=en-GB&ipa=%2Fh%C3%A6%C5%8B%2F","usAudio":"/ai_services/tts3/?q=hang&lang=en-US&ipa=%2Fh%C3%A6%C5%8B%2F"},{"id":"lv_4_191","topic":"Cultural and Historical Exchange","word":"happiness","pos":"(n)","ipa":"/ˈhæp.i.nəs/","defVi":"hạnh phúc, sự sung sướng","defEn":"the state of feeling satisfied, joyful, and content","examples":["True [happiness] often comes from meaningful relationships rather than material possessions. (=Dịch: Hạnh phúc thực sự thường đến từ những mối quan hệ ý nghĩa hơn là của cải vật chất.)","She found lasting [happiness] in helping underprivileged children in her community. (=Dịch: Cô đã tìm thấy niềm hạnh phúc lâu bền trong việc giúp đỡ những trẻ em có hoàn cảnh khó khăn trong cộng đồng của mình.)","The report measures national well-being based on health, education, and overall [happiness]. (=Dịch: Báo cáo đo lường mức độ thịnh vượng quốc gia dựa trên sức khỏe, giáo dục và mức độ hạnh phúc tổng thể.)"],"ukAudio":"/ai_services/tts3/?q=happiness&lang=en-GB&ipa=%2F%CB%88h%C3%A6p.i.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=happiness&lang=en-US&ipa=%2F%CB%88h%C3%A6p.i.n%C9%99s%2F"},{"id":"lv_4_192","topic":"Cultural and Historical Exchange","word":"harbour","pos":"(v)","ipa":"/ˈhɑr.bɚ/","defVi":"nuôi dưỡng (ý nghĩ, cảm xúc), che giấu, chứa chấp","defEn":"to keep a thought or feeling secretly, or to give shelter and protection to someone","examples":["It is unhealthy to [harbour] resentment against your colleagues. (=Dịch: Thật không tốt cho sức khỏe khi nuôi dưỡng sự oán hận đối với đồng nghiệp của bạn.)","The country was accused of trying to [harbour] known criminals. (=Dịch: Đất nước này bị cáo buộc cố tình chứa chấp những tên tội phạm khét tiếng.)","She continues to [harbour] doubts about the success of the new plan. (=Dịch: Cô ấy vẫn tiếp tục ôm ấp những mối nghi ngờ về sự thành công của kế hoạch mới.)"],"ukAudio":"/ai_services/tts3/?q=harbour&lang=en-GB&ipa=%2F%CB%88h%C9%91r.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=harbour&lang=en-US&ipa=%2F%CB%88h%C9%91r.b%C9%9A%2F"},{"id":"lv_4_193","topic":"Cultural and Historical Exchange","word":"heating","pos":"(n)","ipa":"/ˈhiː.t̬ɪŋ/","defVi":"hệ thống sưởi, việc sưởi ấm","defEn":"a system or equipment used to keep a building warm","examples":["They turned on the central [heating] as soon as the winter weather set in. (=Dịch: Họ đã bật hệ thống sưởi trung tâm ngay khi thời tiết mùa đông bắt đầu.)","Old buildings often lose energy because their [heating] systems are inefficient. (=Dịch: Các tòa nhà cũ thường bị thất thoát năng lượng do hệ thống sưởi hoạt động kém hiệu quả.)","The landlord promised to repair the broken [heating] unit before next week. (=Dịch: Chủ nhà đã hứa sẽ sửa chữa thiết bị sưởi bị hỏng trước tuần sau.)"],"ukAudio":"/ai_services/tts3/?q=heating&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heating&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_4_194","topic":"Cultural and Historical Exchange","word":"highlight","pos":"(n)","ipa":"/ˈhaɪ.laɪt/","defVi":"điểm nổi bật, nét đặc sắc nhất","defEn":"the best, most interesting, or most important part of something","examples":["Visiting the ancient castle was definitely the [highlight] of our summer trip. (=Dịch: Tham quan lâu đài cổ kính chắc chắn là điểm nhấn nổi bật trong chuyến đi mùa hè của chúng tôi.)","The keynote speech by the guest professor was the [highlight] of the academic conference. (=Dịch: Bài phát biểu quan trọng của giáo sư khách mời là điểm nổi bật nhất của hội nghị học thuật.)","The sports news showed a short video of the game's [highlight] moments. (=Dịch: Bản tin thể thao đã phát một đoạn video ngắn về những khoảnh khắc nổi bật nhất của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA.la%C9%AAt%2F"},{"id":"lv_4_195","topic":"Cultural and Historical Exchange","word":"housing","pos":"(n)","ipa":"/ˈhaʊ.zɪŋ/","defVi":"nhà ở, việc cung cấp chỗ ở","defEn":"buildings such as flats and houses that people live in","examples":["The government is investing heavily in affordable [housing] for low-income families. (=Dịch: Chính phủ đang đầu tư mạnh vào nhà ở giá phải chăng cho các gia đình có thu nhập thấp.)","Rapid urban growth has created a severe shortage of quality [housing] in the city. (=Dịch: Sự phát triển đô thị nhanh chóng đã tạo ra sự thiếu hụt nghiêm trọng về nhà ở chất lượng tại thành phố.)","University students often struggle to find safe and affordable [housing] near campus. (=Dịch: Sinh viên đại học thường chật vật tìm kiếm chỗ ở an toàn và giá cả phải chăng gần khuôn viên trường.)"],"ukAudio":"/ai_services/tts3/?q=housing&lang=en-GB&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=housing&lang=en-US&ipa=%2F%CB%88ha%CA%8A.z%C9%AA%C5%8B%2F"},{"id":"lv_4_196","topic":"Cultural and Historical Exchange","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"cuộc săn bắt, cuộc tìm kiếm","defEn":"an act of chasing wild animals for food or sport, or a search for someone or something","examples":["The police launched a massive [hunt] for the missing child. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm quy mô lớn đứa trẻ mất tích.)","Lions often coordinate during a [hunt] to catch fast prey. (=Dịch: Sư tử thường phối hợp trong cuộc săn để bắt những con mồi nhanh nhẹn.)","His apartment [hunt] in the city center took several weeks. (=Dịch: Công cuộc tìm kiếm căn hộ của anh ấy ở trung tâm thành phố đã mất vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_4_197","topic":"Cultural and Historical Exchange","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.tɚ/","defVi":"thợ săn, kẻ săn mồi","defEn":"a person or animal that chases and catches wild animals for food or sport","examples":["The ancient tribe relied on every [hunter] to provide meat for the village. (=Dịch: Bộ lạc cổ đại dựa vào từng thợ săn để cung cấp thịt cho cả làng.)","The snowy owl is a skilled [hunter] that can spot prey from great distances. (=Dịch: Cú tuyết là một kẻ săn mồi điêu luyện có thể phát hiện con mồi từ khoảng cách rất xa.)","A treasure [hunter] discovered ancient gold coins near the coast. (=Dịch: Một thợ săn kho báu đã phát hiện ra những đồng tiền vàng cổ gần bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F"},{"id":"lv_4_198","topic":"Cultural and Historical Exchange","word":"hut","pos":"(n)","ipa":"/hʌt/","defVi":"túp lều, chòi tạm","defEn":"a small, simple building, usually consisting of only one room","examples":["The fishermen built a small wooden [hut] by the river. (=Dịch: Những người ngư dân đã dựng một túp lều gỗ nhỏ bên bờ sông.)","They took shelter in a mountain [hut] during the heavy storm. (=Dịch: Họ đã trú ẩn trong một căn lều trên núi suốt cơn bão lớn.)","The beach is lined with simple straw [hut] structures for tourists. (=Dịch: Dọc bãi biển là những chòi lợp rơm đơn sơ dành cho khách du lịch.)"],"ukAudio":"/ai_services/tts3/?q=hut&lang=en-GB&ipa=%2Fh%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=hut&lang=en-US&ipa=%2Fh%CA%8Ct%2F"},{"id":"lv_4_199","topic":"Cultural and Historical Exchange","word":"illustration","pos":"(n)","ipa":"/ˌɪl.əˈstreɪ.ʃən/","defVi":"hình minh họa, tranh minh họa","defEn":"a picture, drawing, or diagram in a book or magazine used to explain or decorate text","examples":["The children's book contains a colorful [illustration] on every page. (=Dịch: Cuốn sách thiếu nhi có một hình minh họa đầy màu sắc trên mỗi trang.)","She provided a clear [illustration] to explain the complex concept. (=Dịch: Cô ấy đã đưa ra một ví dụ minh họa rõ ràng để giải thích khái niệm phức tạp đó.)","His digital [illustration] won first prize in the national art competition. (=Dịch: Tác phẩm minh họa kỹ thuật số của anh ấy đã giành giải nhất trong cuộc thi nghệ thuật quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=illustration&lang=en-GB&ipa=%2F%CB%8C%C9%AAl.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=illustration&lang=en-US&ipa=%2F%CB%8C%C9%AAl.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_200","topic":"Cultural and Historical Exchange","word":"imagination","pos":"(n)","ipa":"/ɪˌmædʒ.əˈneɪ.ʃən/","defVi":"trí tưởng tượng, sức tưởng tượng","defEn":"the ability to form new ideas, pictures, or concepts in your mind that are not real or present","examples":["Children often have a vivid [imagination] that helps them create wonderful stories. (=Dịch: Trẻ em thường có trí tưởng tượng phong phú giúp các em sáng tạo nên những câu chuyện tuyệt vời.)","Writing a fantasy novel requires a great deal of creativity and [imagination]. (=Dịch: Viết một cuốn tiểu thuyết giả tưởng đòi hỏi rất nhiều sự sáng tạo và trí tưởng tượng.)","The sound was so faint that she thought it was just a product of her [imagination]. (=Dịch: Âm thanh nhỏ đến mức cô ấy nghĩ đó chỉ là sản phẩm từ trí tưởng tượng của mình.)"],"ukAudio":"/ai_services/tts3/?q=imagination&lang=en-GB&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=imagination&lang=en-US&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_201","topic":"Cultural and Historical Exchange","word":"impression","pos":"(n)","ipa":"/ɪmˈprɛʃ.ən/","defVi":"ấn tượng, cảm tưởng","defEn":"an idea, feeling, or opinion formed about someone or something","examples":["Dressing professionally helps you make a positive first [impression] at a job interview. (=Dịch: Ăn mặc chuyên nghiệp giúp bạn tạo ấn tượng đầu tiên tích cực trong buổi phỏng vấn xin việc.)","I was under the [impression] that the submission deadline had been extended. (=Dịch: Tôi cứ có cảm giác rằng thời hạn nộp bài đã được gia hạn.)","The scenic beauty of the mountains left a lasting [impression] on all the travelers. (=Dịch: Vẻ đẹp tuyệt mỹ của núi non đã để lại ấn tượng sâu sắc trong lòng tất cả du khách.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_4_202","topic":"Cultural and Historical Exchange","word":"incredibly","pos":"(adv)","ipa":"/ɪnˈkrɛd.ə.bli/","defVi":"vô cùng, cực kỳ","defEn":"extremely; to a great degree","examples":["The exam was [incredibly] difficult, even for well-prepared students. (=Dịch: Bài thi cực kỳ khó, ngay cả đối với những học sinh đã chuẩn bị kỹ lưỡng.)","She performed [incredibly] well during her job interview. (=Dịch: Cô ấy đã thể hiện vô cùng xuất sắc trong buổi phỏng vấn xin việc.)","It is [incredibly] important to get enough sleep each night. (=Dịch: Việc ngủ đủ giấc mỗi đêm là vô cùng quan trọng.)"],"ukAudio":"/ai_services/tts3/?q=incredibly&lang=en-GB&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=incredibly&lang=en-US&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F"},{"id":"lv_4_203","topic":"Cultural and Historical Exchange","word":"influential","pos":"(adj)","ipa":"/ˌɪn.fluˈen.ʃəl/","defVi":"có tầm ảnh hưởng lớn","defEn":"having a lot of influence on people or events","examples":["She is one of the most [influential] writers of this century. (=Dịch: Bà là một trong những nhà văn có tầm ảnh hưởng nhất của thế kỷ này.)","His father played an [influential] role in his career choice. (=Dịch: Cha anh ấy đã đóng một vai trò có ảnh hưởng lớn trong việc lựa chọn nghề nghiệp của anh.)","Social media has become highly [influential] in modern politics. (=Dịch: Mạng xã hội đã trở nên có tầm ảnh hưởng sâu rộng trong nền chính trị hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=influential&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.flu%CB%88en.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=influential&lang=en-US&ipa=%2F%CB%8C%C9%AAn.flu%CB%88en.%CA%83%C9%99l%2F"},{"id":"lv_4_204","topic":"Cultural and Historical Exchange","word":"inhabitant","pos":"(n)","ipa":"/ɪnˈhæb.ə.tənt/","defVi":"cư dân, người cư trú","defEn":"a person or animal that lives permanently in a particular place","examples":["Every [inhabitant] of the small island knows their neighbors well. (=Dịch: Mỗi cư dân trên hòn đảo nhỏ đều biết rất rõ những người hàng xóm của mình.)","The city has over two million [inhabitant]s from diverse backgrounds. (=Dịch: Thành phố có hơn hai triệu cư dân đến từ nhiều nguồn gốc khác nhau.)","Deforestation threatens the survival of each forest [inhabitant]. (=Dịch: Nạn phá rừng đe dọa sự sống còn của từng sinh vật cư trú trong rừng.)"],"ukAudio":"/ai_services/tts3/?q=inhabitant&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=inhabitant&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%99.t%C9%99nt%2F"},{"id":"lv_4_205","topic":"Cultural and Historical Exchange","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, sâu trong đất liền","defEn":"situated in or relating to the interior part of a country, away from the coast","examples":["Many [inland] areas suffer from extreme temperature differences between day and night. (=Dịch: Nhiều khu vực sâu trong nội địa phải chịu sự chênh lệch nhiệt độ khắc nghiệt giữa ngày và đêm.)","The river provides an important [inland] waterway for transporting trade goods. (=Dịch: Con sông tạo nên một tuyến đường thủy nội địa quan trọng để vận chuyển hàng hóa thương mại.)","They moved to an [inland] town to escape coastal storms. (=Dịch: Họ đã chuyển đến một thị trấn trong đất liền để tránh các cơn bão vùng duyên hải.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_4_206","topic":"Cultural and Historical Exchange","word":"innovation","pos":"(n)","ipa":"/ˌɪn.əˈveɪ.ʃən/","defVi":"sự đổi mới, sáng kiến cải tiến","defEn":"the introduction of new ideas, methods, or things","examples":["Technological [innovation] continues to transform how people communicate. (=Dịch: Sự đổi mới công nghệ tiếp tục thay đổi cách con người giao tiếp.)","The company encourages [innovation] by giving employees time to work on personal projects. (=Dịch: Công ty khuyến khích sự đổi mới sáng tạo bằng cách cho nhân viên thời gian làm việc trên các dự án cá nhân.)","Recent [innovation] in solar energy has made renewable power much more affordable. (=Dịch: Những đổi mới gần đây trong lĩnh vực năng lượng mặt trời đã giúp năng lượng tái tạo có giá cả phải chăng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=innovation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=innovation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_207","topic":"Cultural and Historical Exchange","word":"innovative","pos":"(adj)","ipa":"/ˈɪn.ə.veɪ.tɪv/","defVi":"mang tính đổi mới, sáng tạo, tân tiến","defEn":"introducing new ideas, methods, or original ways of thinking","examples":["The company is famous for its [innovative] designs in consumer electronics. (=Dịch: Công ty nổi tiếng với các thiết kế mang tính đổi mới sáng tạo trong lĩnh vực điện tử tiêu dùng.)","Teachers are encouraged to use [innovative] methods in the classroom. (=Dịch: Các giáo viên được khuyến khích sử dụng các phương pháp đổi mới trong lớp học.)","She proposed an [innovative] solution to reduce plastic waste in the city. (=Dịch: Cô ấy đã đề xuất một giải pháp mang tính sáng tạo để giảm thiểu rác thải nhựa trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=innovative&lang=en-GB&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=innovative&lang=en-US&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%C9%AAv%2F"},{"id":"lv_4_208","topic":"Cultural and Historical Exchange","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự thấu hiểu sâu sắc, cái nhìn sâu sắc","defEn":"a clear, deep, and sometimes sudden understanding of a complicated problem or situation","examples":["The research provides valuable [insight] into consumer behavior. (=Dịch: Nghiên cứu cung cấp cái nhìn sâu sắc có giá trị về hành vi của người tiêu dùng.)","His personal experiences gave him a unique [insight] into the struggles of immigrants. (=Dịch: Những trải nghiệm cá nhân mang lại cho anh ấy sự thấu hiểu độc đáo về những khó khăn của người nhập cư.)","The book offers an interesting [insight] into traditional Japanese culture. (=Dịch: Cuốn sách đem đến một góc nhìn thú vị về văn hóa truyền thống Nhật Bản.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_4_209","topic":"Cultural and Historical Exchange","word":"inspiration","pos":"(n)","ipa":"/ˌɪn.spəˈreɪ.ʃən/","defVi":"nguồn cảm hứng, sự truyền cảm hứng","defEn":"a person, thing, or sudden feeling that gives you ideas to do or create something","examples":["Nature is always a great source of [inspiration] for artists. (=Dịch: Thiên nhiên luôn là nguồn cảm hứng tuyệt vời cho các nghệ sĩ.)","Her speech provided the [inspiration] needed to complete the project. (=Dịch: Bài phát biểu của cô ấy đã mang lại nguồn cảm hứng cần thiết để hoàn thành dự án.)","He looked around the room in search of [inspiration] for his next painting. (=Dịch: Anh ấy nhìn quanh phòng để tìm kiếm nguồn cảm hứng cho bức tranh tiếp theo của mình.)"],"ukAudio":"/ai_services/tts3/?q=inspiration&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.sp%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=inspiration&lang=en-US&ipa=%2F%CB%8C%C9%AAn.sp%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_210","topic":"Cultural and Historical Exchange","word":"inspire","pos":"(v)","ipa":"/ɪnˈspaɪr/","defVi":"truyền cảm hứng, khích lệ","defEn":"to fill someone with the urge or ability to do something creative or worthwhile","examples":["Her courage helped [inspire] many young women to pursue science careers. (=Dịch: Lòng dũng cảm của cô ấy đã giúp truyền cảm hứng cho nhiều phụ nữ trẻ theo đuổi sự nghiệp khoa học.)","A walk in the mountains can often [inspire] painters and poets. (=Dịch: Một chuyến đi dạo trên núi thường có thể khơi nguồn cảm hứng cho các họa sĩ và nhà thơ.)","The coach gave a powerful speech to [inspire] the team before the final match. (=Dịch: Huấn luyện viên đã có một bài phát biểu đầy nội lực để truyền cảm hứng cho toàn đội trước trận chung kết.)"],"ukAudio":"/ai_services/tts3/?q=inspire&lang=en-GB&ipa=%2F%C9%AAn%CB%88spa%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=inspire&lang=en-US&ipa=%2F%C9%AAn%CB%88spa%C9%AAr%2F"},{"id":"lv_4_211","topic":"Cultural and Historical Exchange","word":"installation","pos":"(n)","ipa":"/ˌɪn.stəˈleɪ.ʃən/","defVi":"sự lắp đặt; tác phẩm nghệ thuật sắp đặt","defEn":"the act of putting something in place so that it is ready for use, or a modern work of art","examples":["The technician completed the [installation] of the new air conditioning system. (=Dịch: Kỹ thuật viên đã hoàn thành việc lắp đặt hệ thống điều hòa không khí mới.)","The museum opened a fascinating interactive art [installation] yesterday. (=Dịch: Hôm qua, bảo tàng đã khai mạc một tác phẩm nghệ thuật sắp đặt tương tác đầy hấp dẫn.)","Please follow the on-screen instructions during software [installation]. (=Dịch: Vui lòng làm theo hướng dẫn trên màn hình trong quá trình cài đặt phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=installation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=installation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.st%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_212","topic":"Cultural and Historical Exchange","word":"intact","pos":"(adj)","ipa":"/ɪnˈtækt/","defVi":"nguyên vẹn, không bị hư hại","defEn":"complete and not damaged or changed","examples":["Remarkably, the ancient vase remained [intact] after the earthquake. (=Dịch: Thật đáng kinh ngạc, chiếc bình cổ vẫn còn nguyên vẹn sau trận động đất.)","Despite the heavy criticism, his reputation stayed [intact]. (=Dịch: Bất chấp những lời chỉ trích nặng nề, danh tiếng của ông vẫn không hề bị suy suyển.)","The package arrived with its original seal still [intact]. (=Dịch: Kiện hàng đã đến nơi với phần niêm phong ban đầu vẫn còn nguyên vẹn.)"],"ukAudio":"/ai_services/tts3/?q=intact&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=intact&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C3%A6kt%2F"},{"id":"lv_4_213","topic":"Cultural and Historical Exchange","word":"interpretation","pos":"(n)","ipa":"/ɪnˌtɝː.prəˈteɪ.ʃən/","defVi":"sự giải thích, sự diễn giải, cách hiểu","defEn":"an explanation or opinion of what something means","examples":["His [interpretation] of the poem differed greatly from the teacher's view. (=Dịch: Cách giải thích bài thơ của anh ấy khác xa với quan điểm của giáo viên.)","The ambiguous contract left too much room for [interpretation]. (=Dịch: Hợp đồng mơ hồ đã để lại quá nhiều chỗ cho những cách diễn giải khác nhau.)","Her unique [interpretation] of the musical piece earned a standing ovation. (=Dịch: Cách thể hiện độc đáo của cô ấy đối với tác phẩm âm nhạc đã nhận được sự tán thưởng nhiệt liệt từ khán phòng.)"],"ukAudio":"/ai_services/tts3/?q=interpretation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Ct%C9%9D%CB%90.pr%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interpretation&lang=en-US&ipa=%2F%C9%AAn%CB%8Ct%C9%9D%CB%90.pr%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_214","topic":"Cultural and Historical Exchange","word":"interviewee","pos":"(n)","ipa":"/ˌɪn.tɚ.vjuːˈiː/","defVi":"người được phỏng vấn, ứng viên phỏng vấn","defEn":"a person who answers questions in an interview","examples":["The [interviewee] answered all the technical questions with great confidence. (=Dịch: Người được phỏng vấn đã trả lời tất cả các câu hỏi chuyên môn với sự tự tin lớn.)","The researcher asked each [interviewee] about their daily commuting habits. (=Dịch: Nhà nghiên cứu đã hỏi từng người được phỏng vấn về thói quen đi lại hàng ngày của họ.)","A well-prepared [interviewee] usually asks thoughtful questions at the end of the meeting. (=Dịch: Một người được phỏng vấn chuẩn bị kỹ lưỡng thường đặt ra những câu hỏi sâu sắc ở cuối buổi gặp.)"],"ukAudio":"/ai_services/tts3/?q=interviewee&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%9A.vju%CB%90%CB%88i%CB%90%2F","usAudio":"/ai_services/tts3/?q=interviewee&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%9A.vju%CB%90%CB%88i%CB%90%2F"},{"id":"lv_4_215","topic":"Cultural and Historical Exchange","word":"introductory","pos":"(adj)","ipa":"/ˌɪn.trəˈdʌk.tə.ri/","defVi":"mở đầu, giới thiệu, sơ bộ","defEn":"serving as an introduction; basic or opening","examples":["Students must complete the [introductory] course before taking advanced seminars. (=Dịch: Sinh viên phải hoàn thành khóa học nhập môn trước khi tham gia các buổi hội thảo chuyên sâu.)","The speaker gave brief [introductory] remarks before starting the presentation. (=Dịch: Diễn giả đã có đôi lời phát biểu mở đầu ngắn gọn trước khi bắt đầu bài thuyết trình.)","The company offered an [introductory] discount for new subscribers. (=Dịch: Công ty đã đưa ra mức giảm giá ưu đãi ban đầu cho những người đăng ký mới.)"],"ukAudio":"/ai_services/tts3/?q=introductory&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.tr%C9%99%CB%88d%CA%8Ck.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=introductory&lang=en-US&ipa=%2F%CB%8C%C9%AAn.tr%C9%99%CB%88d%CA%8Ck.t%C9%99.ri%2F"},{"id":"lv_4_216","topic":"Cultural and Historical Exchange","word":"inventor","pos":"(n)","ipa":"/ɪnˈven.tɚ/","defVi":"nhà phát minh, người sáng chế","defEn":"a person who creates or designs something that has never existed before","examples":["Thomas Edison is widely known as a prolific [inventor]. (=Dịch: Thomas Edison được biết đến rộng rãi như một nhà phát minh năng suất.)","The young [inventor] received an award for designing an affordable water filter. (=Dịch: Nhà phát minh trẻ đã nhận được giải thưởng vì thiết kế một bộ lọc nước có giá cả phải chăng.)","Every successful [inventor] must be willing to learn from repeated failures. (=Dịch: Mọi nhà phát minh thành công đều phải sẵn sàng học hỏi từ những thất bại lặp đi lặp lại.)"],"ukAudio":"/ai_services/tts3/?q=inventor&lang=en-GB&ipa=%2F%C9%AAn%CB%88ven.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=inventor&lang=en-US&ipa=%2F%C9%AAn%CB%88ven.t%C9%9A%2F"},{"id":"lv_4_217","topic":"Cultural and Historical Exchange","word":"investment","pos":"(n)","ipa":"/ɪnˈvest.mənt/","defVi":"khoản đầu tư, sự đầu tư","defEn":"the act of putting money, effort, or time into something to get a profit or advantage","examples":["Buying a home is often the largest financial [investment] people make. (=Dịch: Mua nhà thường là khoản đầu tư tài chính lớn nhất mà mọi người thực hiện.)","The government increased its [investment] in renewable energy projects. (=Dịch: Chính phủ đã tăng cường đầu tư vào các dự án năng lượng tái tạo.)","Reading books regularly is a valuable [investment] in your personal growth. (=Dịch: Đọc sách thường xuyên là một sự đầu tư quý giá cho sự phát triển cá nhân của bạn.)"],"ukAudio":"/ai_services/tts3/?q=investment&lang=en-GB&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=investment&lang=en-US&ipa=%2F%C9%AAn%CB%88vest.m%C9%99nt%2F"},{"id":"lv_4_218","topic":"Cultural and Historical Exchange","word":"ireland","pos":"(n)","ipa":"/ˈaɪr.lənd/","defVi":"nước Ai-len, Ireland","defEn":"an island country in northwestern Europe known for its rich history and green landscapes","examples":["Many tourists travel to [Ireland] to experience its lively folk music and scenic countryside. (=Dịch: Nhiều du khách đến Ireland để trải nghiệm nền âm nhạc dân gian sôi động và vùng nông thôn tuyệt đẹp nơi đây.)","He decided to study computer science at a university in [Ireland]. (=Dịch: Anh ấy quyết định theo học ngành khoa học máy tính tại một trường đại học ở Ireland.)","The software company opened its European headquarters in [Ireland]. (=Dịch: Công ty phần mềm đã mở trụ sở châu Âu tại Ireland.)"],"ukAudio":"/ai_services/tts3/?q=ireland&lang=en-GB&ipa=%2F%CB%88a%C9%AAr.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=ireland&lang=en-US&ipa=%2F%CB%88a%C9%AAr.l%C9%99nd%2F"},{"id":"lv_4_219","topic":"Cultural and Historical Exchange","word":"irish","pos":"(adj)","ipa":"/ˈaɪ.rɪʃ/","defVi":"thuộc về Ai-len, người Ai-len hoặc tiếng Ai-len","defEn":"relating to Ireland, its people, language, or culture","examples":["We enjoyed listening to traditional [Irish] music at the pub. (=Dịch: Chúng tôi rất thích nghe nhạc truyền thống Ireland tại quán rượu.)","She is proud of her [Irish] heritage and family roots. (=Dịch: Cô ấy tự hào về di sản Ireland và cội nguồn gia đình của mình.)","The festival celebrates [Irish] literature and folklore every spring. (=Dịch: Lễ hội tôn vinh văn học và văn hóa dân gian Ireland vào mỗi mùa xuân.)"],"ukAudio":"/ai_services/tts3/?q=irish&lang=en-GB&ipa=%2F%CB%88a%C9%AA.r%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=irish&lang=en-US&ipa=%2F%CB%88a%C9%AA.r%C9%AA%CA%83%2F"},{"id":"lv_4_220","topic":"Cultural and Historical Exchange","word":"italy","pos":"(n)","ipa":"/ˈɪt̬.əl.i/","defVi":"nước Ý, Italy","defEn":"a country in southern Europe known for its history, art, and cuisine","examples":["Millions of visitors travel to [Italy] each year to explore historic monuments like the Colosseum. (=Dịch: Hàng triệu du khách đến Ý mỗi năm để khám phá các di tích lịch sử như Đấu trường La Mã.)","She developed a passion for cooking while living in [Italy]. (=Dịch: Cô ấy hình thành niềm đam mê nấu nướng khi sống ở Ý.)","Automakers in [Italy] are famous for producing world-class luxury sports cars. (=Dịch: Các nhà sản xuất ô tô ở Ý nổi tiếng với việc sản xuất ra những chiếc xe thể thao hạng sang đẳng cấp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=italy&lang=en-GB&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=italy&lang=en-US&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F"},{"id":"lv_4_221","topic":"Cultural and Historical Exchange","word":"jean","pos":"(n)","ipa":"/dʒiːn/","defVi":"vải bò, vải gin","defEn":"a durable twilled cotton cloth, commonly used to make casual trousers","examples":["A sturdy [jean] jacket is a timeless wardrobe staple for autumn. (=Dịch: Một chiếc áo khoác jean bền chắc là món đồ không bao giờ lỗi thời trong tủ đồ mùa thu.)","The factory specializes in producing high-quality [jean] fabric for export. (=Dịch: Nhà máy chuyên sản xuất vải jean chất lượng cao để xuất khẩu.)","He bought a stylish [jean] cap at the local street market. (=Dịch: Anh ấy đã mua một chiếc mũ jean sành điệu tại chợ đêm địa phương.)"],"ukAudio":"/ai_services/tts3/?q=jean&lang=en-GB&ipa=%2Fd%CA%92i%CB%90n%2F","usAudio":"/ai_services/tts3/?q=jean&lang=en-US&ipa=%2Fd%CA%92i%CB%90n%2F"},{"id":"lv_4_222","topic":"Cultural and Historical Exchange","word":"joy","pos":"(n)","ipa":"/dʒɔɪ/","defVi":"niềm vui, sự hân hoan","defEn":"a feeling of great happiness and pleasure","examples":["The birth of their first child brought immense [joy] to the entire family. (=Dịch: Sự ra đời của đứa con đầu lòng đã mang lại niềm vui vô bờ bến cho cả gia đình.)","She could not hide her [joy] when she received the scholarship offer. (=Dịch: Cô ấy không thể giấu được niềm vui sướng khi nhận được thông báo cấp học bổng.)","Gardening is a simple activity that brings him a lot of [joy]. (=Dịch: Làm vườn là một hoạt động đơn giản mang lại cho anh ấy rất nhiều niềm vui.)"],"ukAudio":"/ai_services/tts3/?q=joy&lang=en-GB&ipa=%2Fd%CA%92%C9%94%C9%AA%2F","usAudio":"/ai_services/tts3/?q=joy&lang=en-US&ipa=%2Fd%CA%92%C9%94%C9%AA%2F"},{"id":"lv_4_223","topic":"Cultural and Historical Exchange","word":"junction","pos":"(n)","ipa":"/ˈdʒʌŋk.ʃən/","defVi":"giao lộ, ngã ba, ngã tư","defEn":"a point where two or more roads, railway lines, or rivers meet","examples":["Drivers should slow down when approaching a busy road [junction]. (=Dịch: Các tài xế nên giảm tốc độ khi đến gần một nút giao thông đông đúc.)","The train stopped at the railway [junction] to switch tracks. (=Dịch: Đoàn tàu đã dừng lại ở nút giao đường sắt để chuyển đường ray.)","The new traffic lights at the dangerous [junction] helped reduce accidents significantly. (=Dịch: Hệ thống đèn giao thông mới tại nút giao nguy hiểm đã giúp giảm đáng kể tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=junction&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=junction&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8C%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_4_224","topic":"Cultural and Historical Exchange","word":"kiln","pos":"(n)","ipa":"/kɪln/","defVi":"lò nung","defEn":"a large oven used for baking bricks or clay to make pottery","examples":["The clay pots must dry completely before they go into the [kiln]. (=Dịch: Những chiếc nồi đất sét phải khô hoàn toàn trước khi được đưa vào lò nung.)","The traditional brick [kiln] produces thousands of bricks each day. (=Dịch: Lò gạch truyền thống sản xuất hàng nghìn viên gạch mỗi ngày.)","She carefully monitored the temperature of the pottery [kiln]. (=Dịch: Cô ấy cẩn thận theo dõi nhiệt độ của lò nung gốm.)"],"ukAudio":"/ai_services/tts3/?q=kiln&lang=en-GB&ipa=%2Fk%C9%AAln%2F","usAudio":"/ai_services/tts3/?q=kiln&lang=en-US&ipa=%2Fk%C9%AAln%2F"},{"id":"lv_4_225","topic":"Cultural and Historical Exchange","word":"kite","pos":"(n)","ipa":"/kaɪt/","defVi":"con diều","defEn":"a light frame covered with paper or cloth, flown in the wind at the end of a long string","examples":["Children love to fly a colorful [kite] in the park on breezy afternoons. (=Dịch: Trẻ em rất thích thả những cánh diều rực rỡ sắc màu trong công viên vào những buổi chiều lộng gió.)","He spent the weekend teaching his young daughter how to build a handmade [kite]. (=Dịch: Anh ấy đã dành cả cuối tuần để dạy cô con gái nhỏ cách tự làm một con diều thủ công.)","The strong gust of wind snapped the string of her [kite]. (=Dịch: Cơn gió giật mạnh đã làm đứt dây con diều của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=kite&lang=en-GB&ipa=%2Fka%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=kite&lang=en-US&ipa=%2Fka%C9%AAt%2F"},{"id":"lv_4_226","topic":"Cultural and Historical Exchange","word":"knit","pos":"(v)","ipa":"/nɪt/","defVi":"đan (len), dệt","defEn":"to make clothes or other items by interlocking loops of wool or yarn with needles","examples":["Her grandmother taught her how to [knit] a warm wool scarf. (=Dịch: Bà của cô đã dạy cô cách đan một chiếc khăn quàng len ấm áp.)","She likes to [knit] sweaters for her grandchildren during the winter. (=Dịch: Bà thích đan áo len cho các cháu của mình vào mùa đông.)","The club members gather every weekend to [knit] blankets for charity. (=Dịch: Các thành viên câu lạc bộ tụ họp vào mỗi cuối tuần để đan chăn làm từ thiện.)"],"ukAudio":"/ai_services/tts3/?q=knit&lang=en-GB&ipa=%2Fn%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=knit&lang=en-US&ipa=%2Fn%C9%AAt%2F"},{"id":"lv_4_227","topic":"Cultural and Historical Exchange","word":"knitting","pos":"(n)","ipa":"/ˈnɪt̬.ɪŋ/","defVi":"việc đan lát, đồ đan bằng len","defEn":"the craft or activity of making garments from yarn with needles, or the fabric produced","examples":["She finds that [knitting] scarves in the evening helps relieve daily stress. (=Dịch: Cô ấy thấy rằng việc đan khăn len vào buổi tối giúp giải tỏa căng thẳng hàng ngày.)","My grandmother always brings her [knitting] whenever she travels by train. (=Dịch: Bà tôi luôn mang theo đồ đan len mỗi khi bà đi tàu hỏa.)","The craft store sells many different tools and colorful yarns for [knitting]. (=Dịch: Cửa hàng thủ công bán nhiều dụng cụ khác nhau và các loại sợi rực rỡ để đan len.)"],"ukAudio":"/ai_services/tts3/?q=knitting&lang=en-GB&ipa=%2F%CB%88n%C9%AAt%CC%AC.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=knitting&lang=en-US&ipa=%2F%CB%88n%C9%AAt%CC%AC.%C9%AA%C5%8B%2F"},{"id":"lv_4_228","topic":"Cultural and Historical Exchange","word":"labyrinth","pos":"(n)","ipa":"/ˈlæb.ə.rɪnθ/","defVi":"mê cung","defEn":"a complicated network of winding passages or paths","examples":["We got lost in a [labyrinth] of narrow streets in the old town. (=Dịch: Chúng tôi bị lạc trong một mê cung các con phố hẹp ở khu phố cổ.)","According to legend, a monster lived at the center of the [labyrinth]. (=Dịch: Theo truyền thuyết, một con quái vật đã sống ở trung tâm của mê cung.)","The new regulations created a [labyrinth] of confusing paperwork. (=Dịch: Các quy định mới đã tạo ra một mê cung các thủ tục giấy tờ rắc rối.)"],"ukAudio":"/ai_services/tts3/?q=labyrinth&lang=en-GB&ipa=%2F%CB%88l%C3%A6b.%C9%99.r%C9%AAn%CE%B8%2F","usAudio":"/ai_services/tts3/?q=labyrinth&lang=en-US&ipa=%2F%CB%88l%C3%A6b.%C9%99.r%C9%AAn%CE%B8%2F"},{"id":"lv_4_229","topic":"Cultural and Historical Exchange","word":"ladder","pos":"(n)","ipa":"/ˈlæd.ɚ/","defVi":"cái thang","defEn":"a piece of equipment consisting of two upright bars connected by rungs, used for climbing","examples":["He climbed up the [ladder] to clean the leaves out of the roof gutter. (=Dịch: Anh ấy đã trèo lên thang để dọn sạch lá cây trong máng xối trên mái nhà.)","She worked hard for years to climb the corporate [ladder]. (=Dịch: Cô ấy đã làm việc chăm chỉ trong nhiều năm để thăng tiến trên nấc thang danh vọng của công ty.)","Please hold the base of the [ladder] firmly while I paint the ceiling. (=Dịch: Vui lòng giữ chắc chân thang trong khi tôi sơn trần nhà.)"],"ukAudio":"/ai_services/tts3/?q=ladder&lang=en-GB&ipa=%2F%CB%88l%C3%A6d.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ladder&lang=en-US&ipa=%2F%CB%88l%C3%A6d.%C9%9A%2F"},{"id":"lv_4_230","topic":"Cultural and Historical Exchange","word":"landing","pos":"(n)","ipa":"/ˈlæn.dɪŋ/","defVi":"sự hạ cánh; chiếu nghỉ (cầu thang)","defEn":"the act of bringing an aircraft or spacecraft down to the ground, or a level area at the top of a staircase","examples":["The pilot made a smooth [landing] despite the strong crosswinds. (=Dịch: Phi công đã hạ cánh êm ái bất chấp gió tạt ngang mạnh.)","She stood on the second-floor [landing] and called down to her brother. (=Dịch: Cô đứng trên chiếu nghỉ tầng hai và gọi với xuống cho em trai mình.)","The emergency [landing] on the river saved the lives of all passengers. (=Dịch: Vụ hạ cánh khẩn cấp xuống dòng sông đã cứu sống toàn bộ hành khách.)"],"ukAudio":"/ai_services/tts3/?q=landing&lang=en-GB&ipa=%2F%CB%88l%C3%A6n.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=landing&lang=en-US&ipa=%2F%CB%88l%C3%A6n.d%C9%AA%C5%8B%2F"},{"id":"lv_4_231","topic":"Cultural and Historical Exchange","word":"landlord","pos":"(n)","ipa":"/ˈlænd.lɔːrd/","defVi":"chủ nhà trọ; chủ đất","defEn":"a person who owns a building or land and rents it to other people","examples":["The tenant contacted the [landlord] to request urgent repairs on the roof. (=Dịch: Người thuê nhà đã liên hệ với chủ nhà để yêu cầu sửa chữa mái nhà khẩn cấp.)","Our [landlord] agreed not to increase the rent for the upcoming year. (=Dịch: Chủ nhà của chúng tôi đã đồng ý không tăng tiền thuê nhà trong năm tới.)","She has been a responsible [landlord] managing several rental properties. (=Dịch: Bà ấy là một chủ nhà có trách nhiệm trong việc quản lý nhiều bất động sản cho thuê.)"],"ukAudio":"/ai_services/tts3/?q=landlord&lang=en-GB&ipa=%2F%CB%88l%C3%A6nd.l%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=landlord&lang=en-US&ipa=%2F%CB%88l%C3%A6nd.l%C9%94%CB%90rd%2F"},{"id":"lv_4_232","topic":"Cultural and Historical Exchange","word":"largely","pos":"(adv)","ipa":"/ˈlɑːrdʒ.li/","defVi":"chủ yếu, phần lớn","defEn":"mostly, primarily, or to a great extent","examples":["The success of the campaign was [largely] due to good planning. (=Dịch: Thành công của chiến dịch phần lớn là nhờ vào việc lập kế hoạch tốt.)","His explanation was [largely] ignored by the audience. (=Dịch: Lời giải thích của anh ấy phần lớn đã bị khán giả phớt lờ.)","The town is [largely] inhabited by retired people. (=Dịch: Thị trấn này phần lớn là nơi sinh sống của những người đã nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=largely&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90rd%CA%92.li%2F","usAudio":"/ai_services/tts3/?q=largely&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90rd%CA%92.li%2F"},{"id":"lv_4_233","topic":"Cultural and Historical Exchange","word":"lasting","pos":"(adj)","ipa":"/ˈlæs.tɪŋ/","defVi":"bền vững, lâu dài, trường tồn","defEn":"continuing to exist for a very long time","examples":["The mentor's advice had a [lasting] impact on her career choices. (=Dịch: Lời khuyên của người cố vấn đã có tác động lâu dài đến những lựa chọn nghề nghiệp của cô ấy.)","They built a [lasting] friendship during their university years. (=Dịch: Họ đã xây dựng một tình bạn bền chặt lâu dài trong những năm tháng đại học.)","The treaty established a [lasting] peace between the two neighboring countries. (=Dịch: Hiệp ước đã thiết lập một nền hòa bình lâu dài giữa hai quốc gia láng giềng.)"],"ukAudio":"/ai_services/tts3/?q=lasting&lang=en-GB&ipa=%2F%CB%88l%C3%A6s.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lasting&lang=en-US&ipa=%2F%CB%88l%C3%A6s.t%C9%AA%C5%8B%2F"},{"id":"lv_4_234","topic":"Cultural and Historical Exchange","word":"leather","pos":"(n)","ipa":"/ˈleð.ɚ/","defVi":"da thuộc, chất liệu da","defEn":"material made from animal skin by tanning or a similar process","examples":["She bought a durable jacket made of genuine [leather]. (=Dịch: Cô ấy đã mua một chiếc áo khoác bền được làm từ da thật.)","The luxury car features comfortable seats upholstered in black [leather]. (=Dịch: Chiếc xe sang trọng có những chiếc ghế êm ái được bọc bằng da màu đen.)","Traditional shoemakers still prefer using natural [leather] for handmade boots. (=Dịch: Những người thợ đóng giày truyền thống vẫn thích sử dụng da tự nhiên cho những đôi bốt thủ công.)"],"ukAudio":"/ai_services/tts3/?q=leather&lang=en-GB&ipa=%2F%CB%88le%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=leather&lang=en-US&ipa=%2F%CB%88le%C3%B0.%C9%9A%2F"},{"id":"lv_4_235","topic":"Cultural and Historical Exchange","word":"librarian","pos":"(n)","ipa":"/laɪˈbrer.i.ən/","defVi":"thủ thư, người quản lý thư viện","defEn":"a person who works in or is in charge of a library","examples":["The [librarian] helped the student find academic journals for his research paper. (=Dịch: Người thủ thư đã giúp sinh viên tìm các tạp chí học thuật cho bài nghiên cứu của mình.)","You can ask the [librarian] to reserve the book if it is currently checked out. (=Dịch: Bạn có thể nhờ thủ thư giữ sách giúp nếu cuốn sách hiện đã được mượn.)","She decided to train as a [librarian] because of her deep passion for reading. (=Dịch: Cô quyết định theo học để trở thành thủ thư vì niềm đam mê đọc sách sâu sắc của mình.)"],"ukAudio":"/ai_services/tts3/?q=librarian&lang=en-GB&ipa=%2Fla%C9%AA%CB%88brer.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=librarian&lang=en-US&ipa=%2Fla%C9%AA%CB%88brer.i.%C9%99n%2F"},{"id":"lv_4_236","topic":"Cultural and Historical Exchange","word":"linen","pos":"(n)","ipa":"/ˈlɪn.ɪn/","defVi":"vải lanh","defEn":"a strong, light cloth made from the fibers of the flax plant","examples":["He wore a light [linen] shirt to keep cool in the humid tropical climate. (=Dịch: Anh ấy mặc một chiếc áo sơ mi vải lanh nhẹ để giữ mát trong khí hậu nhiệt đới ẩm ướt.)","The hotel is known for using high-quality [linen] on all of its beds. (=Dịch: Khách sạn nổi tiếng với việc sử dụng đồ vải lanh chất lượng cao trên tất cả các giường ngủ của mình.)","Pure [linen] tends to wrinkle easily, but it remains a popular choice for summer fashion. (=Dịch: Vải lanh nguyên chất có xu hướng dễ bị nhăn, nhưng nó vẫn là một lựa chọn phổ biến cho thời trang mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=linen&lang=en-GB&ipa=%2F%CB%88l%C9%AAn.%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=linen&lang=en-US&ipa=%2F%CB%88l%C9%AAn.%C9%AAn%2F"},{"id":"lv_4_237","topic":"Cultural and Historical Exchange","word":"lining","pos":"(n)","ipa":"/ˈlaɪ.nɪŋ/","defVi":"lớp lót, vải lót","defEn":"a layer of material covering the inside surface of clothing, bags, or other items","examples":["The winter coat has a warm silk [lining] that keeps out the cold. (=Dịch: Chiếc áo khoác mùa đông có lớp lót lụa ấm áp giúp cản cái lạnh.)","She tore the [lining] of her handbag when looking for her keys. (=Dịch: Cô ấy đã làm rách lớp lót bên trong túi xách khi tìm chìa khóa.)","The stomach [lining] protects the body from strong digestive acids. (=Dịch: Lớp niêm mạc dạ dày bảo vệ cơ thể khỏi các axit tiêu hóa mạnh.)"],"ukAudio":"/ai_services/tts3/?q=lining&lang=en-GB&ipa=%2F%CB%88la%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lining&lang=en-US&ipa=%2F%CB%88la%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_4_238","topic":"Cultural and Historical Exchange","word":"literature","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.tʃɚ/","defVi":"văn học, tác phẩm văn chương","defEn":"written artistic works such as novels, plays, and poetry","examples":["Reading classical [literature] helps improve your vocabulary and critical thinking skills. (=Dịch: Đọc văn học cổ điển giúp nâng cao vốn từ vựng và kỹ năng tư duy phản biện của bạn.)","She has a profound passion for nineteenth-century French [literature]. (=Dịch: Cô có niềm đam mê sâu sắc với văn học Pháp thế kỷ XIX.)","The academic conference focused on contemporary post-war [literature]. (=Dịch: Hội nghị học thuật tập trung vào nền văn học hậu chiến đương đại.)"],"ukAudio":"/ai_services/tts3/?q=literature&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=literature&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F"},{"id":"lv_4_239","topic":"Cultural and Historical Exchange","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"gia súc","defEn":"animals such as cows, sheep, and pigs kept on a farm","examples":["The farmer raises [livestock] to produce milk and meat for the local market. (=Dịch: Người nông dân nuôi gia súc để sản xuất sữa và thịt cho thị trường địa phương.)","Severe drought has made it difficult to find enough water and food for the [livestock]. (=Dịch: Hạn hán nghiêm trọng đã khiến việc tìm đủ nước và thức ăn cho gia súc trở nên khó khăn.)","Vaccinating [livestock] regularly helps prevent the spread of infectious diseases. (=Dịch: Tiêm phòng cho gia súc thường xuyên giúp ngăn ngừa sự lây lan của các bệnh truyền nhiễm.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_4_240","topic":"Cultural and Historical Exchange","word":"logic","pos":"(n)","ipa":"/ˈlɑː.dʒɪk/","defVi":"sự hợp lý, tính logic, lý lẽ","defEn":"a sensible way of thinking or explaining based on good judgment","examples":["There is no clear [logic] behind the company's decision to cut the training budget. (=Dịch: Không có lập luận hợp lý rõ ràng nào đằng sau quyết định cắt giảm ngân sách đào tạo của công ty.)","Her argument was structured with remarkable clarity and [logic]. (=Dịch: Lập luận của cô được xây dựng với sự rõ ràng và tính logic đáng kinh ngạc.)","Computer programming requires a strong grasp of mathematical [logic]. (=Dịch: Lập trình máy tính đòi hỏi sự nắm vững về logic toán học.)"],"ukAudio":"/ai_services/tts3/?q=logic&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=logic&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AAk%2F"},{"id":"lv_4_241","topic":"Cultural and Historical Exchange","word":"lord","pos":"(n)","ipa":"/lɔːrd/","defVi":"lãnh chúa, quý tộc","defEn":"a man of noble rank or high authority in a traditional society","examples":["In medieval times, the local [lord] ruled over vast areas of agricultural land. (=Dịch: Vào thời trung cổ, lãnh chúa địa phương cai trị những vùng đất nông nghiệp rộng lớn.)","The villagers paid taxes directly to the feudal [lord]. (=Dịch: Dân làng nộp thuế trực tiếp cho lãnh chúa phong kiến.)","The castle served as the official residence of the powerful [lord]. (=Dịch: Lâu đài từng là nơi ở chính thức của vị lãnh chúa quyền lực.)"],"ukAudio":"/ai_services/tts3/?q=lord&lang=en-GB&ipa=%2Fl%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=lord&lang=en-US&ipa=%2Fl%C9%94%CB%90rd%2F"},{"id":"lv_4_242","topic":"Cultural and Historical Exchange","word":"lounge","pos":"(n)","ipa":"/laʊndʒ/","defVi":"phòng chờ, sảnh nghỉ ngơi","defEn":"a public room in a hotel, airport, or club equipped with comfortable seating for waiting or relaxing","examples":["We decided to wait for our flight in the airport [lounge]. (=Dịch: Chúng tôi quyết định ngồi chờ chuyến bay của mình trong phòng chờ sân bay.)","Guests can enjoy afternoon tea in the hotel's spacious [lounge]. (=Dịch: Du khách có thể thưởng thức trà chiều trong phòng chờ rộng rãi của khách sạn.)","The departure [lounge] was crowded with holiday travelers. (=Dịch: Phòng chờ khởi hành đông nghịt những du khách đi nghỉ dưỡng.)"],"ukAudio":"/ai_services/tts3/?q=lounge&lang=en-GB&ipa=%2Fla%CA%8And%CA%92%2F","usAudio":"/ai_services/tts3/?q=lounge&lang=en-US&ipa=%2Fla%CA%8And%CA%92%2F"},{"id":"lv_4_243","topic":"Cultural and Historical Exchange","word":"luxury","pos":"(n)","ipa":"/ˈlʌk.ʃɚ.i/","defVi":"sự xa xỉ, đồ xa xỉ","defEn":"great comfort, expensive quality, or something enjoyable that is not essential","examples":["Living in a five-star hotel for a month was an unaffordable [luxury] for the student. (=Dịch: Sống trong một khách sạn năm sao suốt một tháng là một điều xa xỉ không thể chi trả nổi đối với cậu sinh viên.)","They spent the weekend relaxing in absolute [luxury] at a secluded mountain resort. (=Dịch: Họ đã dành cả cuối tuần để thư giãn trong sự xa hoa tuyệt đối tại một khu nghỉ dưỡng hẻo lánh trên núi.)","Clean drinking water should be a basic human right rather than a rare [luxury]. (=Dịch: Nước uống sạch phải là một quyền cơ bản của con người hơn là một thứ xa xỉ hiếm có.)"],"ukAudio":"/ai_services/tts3/?q=luxury&lang=en-GB&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=luxury&lang=en-US&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%9A.i%2F"},{"id":"lv_4_244","topic":"Cultural and Historical Exchange","word":"magic","pos":"(n)","ipa":"/ˈmædʒ.ɪk/","defVi":"phép thuật, ảo thuật","defEn":"the use of supernatural powers to create illusions or make impossible things happen","examples":["The children watched in wonder as the entertainer performed [magic] tricks. (=Dịch: Những đứa trẻ ngắm nhìn trong sự kinh ngạc khi người biểu diễn thực hiện các màn ảo thuật.)","In fairy tales, heroes often defeat villains with ancient [magic]. (=Dịch: Trong truyện cổ tích, các anh hùng thường đánh bại nhân vật phản diện bằng ma thuật cổ xưa.)","The sunset over the ocean had a special kind of [magic]. (=Dịch: Hoàng hôn trên đại dương mang một vẻ ma mị và kỳ diệu rất đặc biệt.)"],"ukAudio":"/ai_services/tts3/?q=magic&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=magic&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AAk%2F"},{"id":"lv_4_245","topic":"Cultural and Historical Exchange","word":"magical","pos":"(adj)","ipa":"/ˈmædʒ.ɪ.kəl/","defVi":"kỳ diệu, huyền diệu, thuộc ma thuật","defEn":"produced by or relating to magic; wonderfully special or enchanting","examples":["Watching the northern lights was a truly [magical] experience. (=Dịch: Ngắm nhìn cực quang là một trải nghiệm thực sự kỳ diệu.)","The fairy tale describes a [magical] kingdom hidden deep in the forest. (=Dịch: Câu chuyện cổ tích miêu tả một vương quốc kỳ diệu ẩn sâu trong rừng.)","There is no [magical] solution to solving global poverty overnight. (=Dịch: Không có giải pháp thần kỳ nào để xóa bỏ nghèo đói toàn cầu chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=magical&lang=en-GB&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=magical&lang=en-US&ipa=%2F%CB%88m%C3%A6d%CA%92.%C9%AA.k%C9%99l%2F"},{"id":"lv_4_246","topic":"Cultural and Historical Exchange","word":"mangroves","pos":"(n)","ipa":"/ˈmæŋ.ɡroʊvz/","defVi":"rừng ngập mặn; cây đước","defEn":"tropical trees or shrubs that grow in coastal saline or brackish water","examples":["Coastal [mangroves] act as natural barriers that protect shores from storm surges. (=Dịch: Rừng ngập mặn ven biển đóng vai trò như những rào cản tự nhiên bảo vệ bờ biển khỏi nước dâng do bão.)","Many species of fish rely on [mangroves] as a safe breeding ground. (=Dịch: Nhiều loài cá dựa vào rừng ngập mặn như một nơi sinh sản an toàn.)","The conservation group works to restore degraded [mangroves] in the delta. (=Dịch: Nhóm bảo tồn nỗ lực phục hồi các khu rừng ngập mặn bị suy thoái ở vùng đồng bằng châu thổ.)"],"ukAudio":"/ai_services/tts3/?q=mangroves&lang=en-GB&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Avz%2F","usAudio":"/ai_services/tts3/?q=mangroves&lang=en-US&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Avz%2F"},{"id":"lv_4_247","topic":"Cultural and Historical Exchange","word":"mask","pos":"(n)","ipa":"/mæsk/","defVi":"mặt nạ, khẩu trang","defEn":"a covering worn over all or part of the face for protection, disguise, or performance","examples":["The surgeon wore a protective [mask] throughout the entire operation. (=Dịch: Bác sĩ phẫu thuật đã đeo khẩu trang bảo hộ trong suốt toàn bộ ca mổ.)","Children painted their own colorful [mask] for the Halloween parade. (=Dịch: Trẻ em đã tự vẽ những chiếc mặt nạ đầy màu sắc cho cuộc diễu hành Halloween.)","He tried to hide his true feelings behind a [mask] of polite indifference. (=Dịch: Anh ta cố gắng che giấu cảm xúc thật của mình đằng sau vỏ bọc của sự thờ ơ lịch sự.)"],"ukAudio":"/ai_services/tts3/?q=mask&lang=en-GB&ipa=%2Fm%C3%A6sk%2F","usAudio":"/ai_services/tts3/?q=mask&lang=en-US&ipa=%2Fm%C3%A6sk%2F"},{"id":"lv_4_248","topic":"Cultural and Historical Exchange","word":"maze","pos":"(n)","ipa":"/meɪz/","defVi":"mê cung","defEn":"a complicated network of paths or passages in which it is difficult to find the way","examples":["We got lost in the garden [maze] for almost an hour. (=Dịch: Chúng tôi đã bị lạc trong mê cung cây trong vườn suốt gần một tiếng đồng hồ.)","The old town is a [maze] of narrow cobbled streets. (=Dịch: Khu phố cổ là một mê cung gồm những con đường lát đá cuội chật hẹp.)","Navigating the legal system felt like walking through an endless [maze]. (=Dịch: Việc tìm hiểu và làm việc với hệ thống pháp lý mang lại cảm giác như đang đi qua một mê cung bất tận.)"],"ukAudio":"/ai_services/tts3/?q=maze&lang=en-GB&ipa=%2Fme%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=maze&lang=en-US&ipa=%2Fme%C9%AAz%2F"},{"id":"lv_4_249","topic":"Cultural and Historical Exchange","word":"memorable","pos":"(adj)","ipa":"/ˈmɛm.ər.ə.bəl/","defVi":"đáng nhớ, khó quên","defEn":"worth remembering or easily remembered because of being special or unusual","examples":["Our trip to the mountains was a truly [memorable] experience. (=Dịch: Chuyến đi lên núi của chúng tôi thực sự là một trải nghiệm đáng nhớ.)","The actor gave a [memorable] performance in his final stage play. (=Dịch: Nam diễn viên đã có một màn trình diễn đáng nhớ trong vở kịch sân khấu cuối cùng của mình.)","She shared some [memorable] stories from her years working abroad. (=Dịch: Cô ấy đã chia sẻ một số câu chuyện đáng nhớ từ những năm tháng làm việc ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=memorable&lang=en-GB&ipa=%2F%CB%88m%C9%9Bm.%C9%99r.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=memorable&lang=en-US&ipa=%2F%CB%88m%C9%9Bm.%C9%99r.%C9%99.b%C9%99l%2F"},{"id":"lv_4_250","topic":"Cultural and Historical Exchange","word":"messy","pos":"(adj)","ipa":"/ˈmɛs.i/","defVi":"bừa bộn, lộn xộn","defEn":"dirty, untidy, or disordered","examples":["His desk was [messy], covered with piles of old documents. (=Dịch: Bàn làm việc của anh ấy rất bừa bộn, phủ đầy những chồng tài liệu cũ.)","Cooking with young children can be a fun but [messy] activity. (=Dịch: Nấu ăn cùng trẻ nhỏ có thể là một hoạt động vui vẻ nhưng lại khá lộn xộn.)","The divorce turned into a long and [messy] legal battle. (=Dịch: Vụ ly hôn đã biến thành một cuộc chiến pháp lý kéo dài và đầy rắc rối.)"],"ukAudio":"/ai_services/tts3/?q=messy&lang=en-GB&ipa=%2F%CB%88m%C9%9Bs.i%2F","usAudio":"/ai_services/tts3/?q=messy&lang=en-US&ipa=%2F%CB%88m%C9%9Bs.i%2F"},{"id":"lv_4_251","topic":"Cultural and Historical Exchange","word":"methodology","pos":"(n)","ipa":"/ˌmeθ.əˈdɑː.lə.dʒi/","defVi":"phương pháp luận, hệ phương pháp nghiên cứu","defEn":"a system of methods and principles used in a particular area of study or activity","examples":["The researchers explained their [methodology] in the introductory chapter. (=Dịch: Các nhà nghiên cứu đã giải thích phương pháp luận của họ trong chương mở đầu.)","Using an appropriate [methodology] is essential for gathering accurate scientific data. (=Dịch: Việc sử dụng phương pháp luận phù hợp là điều cần thiết để thu thập dữ liệu khoa học chính xác.)","She adjusted her research [methodology] after receiving feedback from her supervisor. (=Dịch: Cô ấy đã điều chỉnh phương pháp nghiên cứu của mình sau khi nhận được phản hồi từ người hướng dẫn.)"],"ukAudio":"/ai_services/tts3/?q=methodology&lang=en-GB&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=methodology&lang=en-US&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_4_252","topic":"Cultural and Historical Exchange","word":"migrate","pos":"(v)","ipa":"/ˈmaɪ.ɡreɪt/","defVi":"di cư, di trú","defEn":"to move from one region or habitat to another, especially according to the seasons","examples":["Thousands of swallows [migrate] south every autumn to escape the cold weather. (=Dịch: Hàng ngàn con chim én di cư về phương nam mỗi độ thu về để tránh thời tiết lạnh giá.)","Many young people [migrate] to metropolitan areas in search of employment opportunities. (=Dịch: Nhiều người trẻ di cư đến các vùng đô thị lớn để tìm kiếm cơ hội việc làm.)","Certain fish species [migrate] upstream to lay their eggs in freshwater rivers. (=Dịch: Một số loài cá nhất định di cư ngược dòng để đẻ trứng trong các con sông nước ngọt.)"],"ukAudio":"/ai_services/tts3/?q=migrate&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=migrate&lang=en-US&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F"},{"id":"lv_4_253","topic":"Cultural and Historical Exchange","word":"migration","pos":"(n)","ipa":"/maɪˈɡreɪ.ʃən/","defVi":"sự di cư, sự chuyển dịch","defEn":"the seasonal movement of animals or the relocation of people from one place to another","examples":["The annual [migration] of wildebeests across the savannah attracts many tourists. (=Dịch: Cuộc di cư hàng năm của linh dương đầu bò qua thảo nguyên thu hút rất nhiều khách du lịch.)","Economic hardship led to a mass [migration] from rural areas to urban centers. (=Dịch: Khó khăn kinh tế đã dẫn đến một cuộc di cư hàng loạt từ các vùng nông thôn đến các trung tâm thành thị.)","Scientists track bird [migration] patterns using satellite transmitters. (=Dịch: Các nhà khoa học theo dõi các mô hình di cư của loài chim bằng máy phát tín hiệu vệ tinh.)"],"ukAudio":"/ai_services/tts3/?q=migration&lang=en-GB&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=migration&lang=en-US&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_254","topic":"Cultural and Historical Exchange","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai khoáng, sự khai thác mỏ","defEn":"the industry or activity of digging coal or other valuable minerals out of the ground","examples":["The local economy heavily depends on coal [mining] for employment. (=Dịch: Nền kinh tế địa phương phụ thuộc rất lớn vào ngành khai thác than để tạo việc làm.)","Strict environmental regulations have been introduced to reduce pollution caused by [mining]. (=Dịch: Các quy định nghiêm ngặt về môi trường đã được ban hành nhằm giảm thiểu ô nhiễm do hoạt động khai mỏ gây ra.)","Advancements in technology have improved worker safety in deep-sea [mining]. (=Dịch: Những tiến bộ trong công nghệ đã cải thiện độ an toàn cho người lao động trong hoạt động khai thác dưới biển sâu.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_4_255","topic":"Cultural and Historical Exchange","word":"mixture","pos":"(n)","ipa":"/ˈmɪks.tʃɚ/","defVi":"hỗn hợp, sự pha trộn","defEn":"a combination of different things, substances, or qualities","examples":["Pour the cake [mixture] into a greased baking tin. (=Dịch: Đổ hỗn hợp làm bánh vào khuôn nướng đã được thoa dầu.)","The city has an interesting [mixture] of old and modern architecture. (=Dịch: Thành phố có sự pha trộn thú vị giữa kiến trúc cổ kính và hiện đại.)","She felt a [mixture] of excitement and nervousness before the interview. (=Dịch: Cô cảm thấy vừa phấn khích vừa hồi hộp trước buổi phỏng vấn.)"],"ukAudio":"/ai_services/tts3/?q=mixture&lang=en-GB&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mixture&lang=en-US&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F"},{"id":"lv_4_256","topic":"Cultural and Historical Exchange","word":"motion","pos":"(n)","ipa":"/ˈmoʊ.ʃən/","defVi":"sự chuyển động; kiến nghị (trong cuộc họp)","defEn":"the act or process of moving, or a formal proposal made in a meeting","examples":["The sensor detects any sudden [motion] inside the secure room. (=Dịch: Cảm biến phát hiện bất kỳ chuyển động đột ngột nào bên trong căn phòng an ninh.)","The gentle rocking [motion] of the boat made the passengers feel sleepy. (=Dịch: Sự đong đưa nhẹ nhàng của con thuyền khiến các hành khách cảm thấy buồn ngủ.)","The board members voted unanimously in favor of the proposed [motion]. (=Dịch: Các thành viên hội đồng quản trị đã bỏ phiếu nhất trí ủng hộ kiến nghị được đề xuất.)"],"ukAudio":"/ai_services/tts3/?q=motion&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motion&lang=en-US&ipa=%2F%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_4_257","topic":"Cultural and Historical Exchange","word":"mould","pos":"(v)","ipa":"/moʊld/","defVi":"đúc, nặn, nhào nặn, định hình","defEn":"to shape a soft material into a specific form, or to influence someone's character","examples":["The artist used warm clay to [mould] a delicate vase. (=Dịch: Người nghệ sĩ đã dùng đất sét ấm để nặn một chiếc bình tinh xảo.)","Good teachers help [mould] the minds and values of young children. (=Dịch: Những người thầy giỏi giúp uốn nắn tâm trí và những giá trị của trẻ nhỏ.)","Chocolatiers pour melted chocolate into trays to [mould] different shapes. (=Dịch: Những người làm sô-cô-la đổ sô-cô-la tan chảy vào khay để tạo thành các hình dạng khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=mould&lang=en-GB&ipa=%2Fmo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=mould&lang=en-US&ipa=%2Fmo%CA%8Ald%2F"},{"id":"lv_4_258","topic":"Cultural and Historical Exchange","word":"mud","pos":"(n)","ipa":"/mʌd/","defVi":"bùn, bùn đất","defEn":"wet, soft, and sticky earth or soil","examples":["The car wheels got stuck in the thick [mud] on the dirt road. (=Dịch: Bánh xe ô tô bị mắc kẹt trong lớp bùn đặc trên con đường đất.)","Children love playing in the [mud] after heavy rainfall. (=Dịch: Trẻ em rất thích chơi đùa trong bùn sau cơn mưa lớn.)","He wiped the [mud] off his boots before entering the house. (=Dịch: Anh ấy lau sạch bùn khỏi đôi ủng trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=mud&lang=en-GB&ipa=%2Fm%CA%8Cd%2F","usAudio":"/ai_services/tts3/?q=mud&lang=en-US&ipa=%2Fm%CA%8Cd%2F"},{"id":"lv_4_259","topic":"Cultural and Historical Exchange","word":"multiple","pos":"(adj)","ipa":"/ˈmʌl.tə.pəl/","defVi":"nhiều, đa dạng","defEn":"involving or consisting of many parts, elements, or individuals","examples":["The victim suffered [multiple] injuries and was rushed to the hospital. (=Dịch: Nạn nhân phải chịu nhiều chấn thương và đã được đưa đi cấp cứu ngay lập tức.)","The test consists of [multiple] choice questions and a short essay. (=Dịch: Bài kiểm tra bao gồm các câu hỏi trắc nghiệm và một bài luận ngắn.)","She cited [multiple] reasons for leaving her previous job. (=Dịch: Cô ấy đã nêu ra nhiều lý do cho việc rời bỏ công việc trước đây.)"],"ukAudio":"/ai_services/tts3/?q=multiple&lang=en-GB&ipa=%2F%CB%88m%CA%8Cl.t%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=multiple&lang=en-US&ipa=%2F%CB%88m%CA%8Cl.t%C9%99.p%C9%99l%2F"},{"id":"lv_4_260","topic":"Cultural and Historical Exchange","word":"mystery","pos":"(n)","ipa":"/ˈmɪs.tɚ.i/","defVi":"điều bí ẩn, sự bí ẩn","defEn":"something that is difficult or impossible to understand or explain","examples":["The disappearance of the ancient civilization remains a total [mystery]. (=Dịch: Sự biến mất của nền văn minh cổ đại vẫn là một bí ẩn hoàn toàn.)","Detectives are trying to unravel the [mystery] behind the missing artwork. (=Dịch: Các thám tử đang cố gắng làm sáng tỏ bí ẩn đằng sau tác phẩm nghệ thuật bị mất tích.)","His sudden decision to resign was a complete [mystery] to all his colleagues. (=Dịch: Quyết định từ chức đột ngột của anh ấy là một điều hoàn toàn khó hiểu đối với tất cả đồng nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=mystery&lang=en-GB&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=mystery&lang=en-US&ipa=%2F%CB%88m%C9%AAs.t%C9%9A.i%2F"},{"id":"lv_4_261","topic":"Cultural and Historical Exchange","word":"needle","pos":"(v)","ipa":"/ˈni.dəl/","defVi":"chọc ghẹo, khích bác, chọc tức","defEn":"to deliberately annoy or tease someone to provoke a reaction","examples":["His older brother likes to [needle] him about his messy room. (=Dịch: Anh trai cậu ấy rất thích chọc ghẹo cậu về căn phòng bừa bộn.)","Reporters continued to [needle] the politician until he lost his temper. (=Dịch: Các phóng viên liên tục châm chọc chính trị gia cho đến khi ông mất bình tĩnh.)","Try not to let your classmates [needle] you into making a poor decision. (=Dịch: Cố gắng đừng để bạn cùng lớp khiêu khích khiến bạn đưa ra quyết định sai lầm.)"],"ukAudio":"/ai_services/tts3/?q=needle&lang=en-GB&ipa=%2F%CB%88ni.d%C9%99l%2F","usAudio":"/ai_services/tts3/?q=needle&lang=en-US&ipa=%2F%CB%88ni.d%C9%99l%2F"},{"id":"lv_4_262","topic":"Cultural and Historical Exchange","word":"new zealand","pos":"(n)","ipa":"/ˌnuː ˈziː.lənd/","defVi":"nước Niu Di-lân, New Zealand","defEn":"an island country in the southwestern Pacific Ocean known for its natural beauty and wildlife","examples":["Many outdoor enthusiasts travel to [New Zealand] to hike through its majestic mountains. (=Dịch: Nhiều người đam mê các hoạt động ngoài trời đến New Zealand để đi bộ leo núi qua những dãy núi hùng vĩ.)","Dairy farming is one of the most vital export industries in [New Zealand]. (=Dịch: Chăn nuôi bò sữa là một trong những ngành xuất khẩu quan trọng nhất ở New Zealand.)","Famous fantasy films were shot entirely on location across [New Zealand]. (=Dịch: Những bộ phim giả tưởng nổi tiếng đã được quay hoàn toàn tại các địa điểm thực tế trên khắp New Zealand.)"],"ukAudio":"/ai_services/tts3/?q=new+zealand&lang=en-GB&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=new+zealand&lang=en-US&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F"},{"id":"lv_4_263","topic":"Cultural and Historical Exchange","word":"nineteenth","pos":"(adj)","ipa":"/ˌnaɪn.ˈtinθ/","defVi":"thứ mười chín","defEn":"constituting number nineteen in a sequence; coming after the eighteenth","examples":["Many social changes took place during the [nineteenth] century. (=Dịch: Nhiều thay đổi xã hội đã diễn ra trong suốt thế kỷ thứ mười chín.)","Today is her [nineteenth] birthday, and she is having a small party. (=Dịch: Hôm nay là sinh nhật lần thứ mười chín của cô ấy, và cô ấy đang tổ chức một bữa tiệc nhỏ.)","He finished in [nineteenth] place out of more than fifty runners. (=Dịch: Anh ấy về đích ở vị trí thứ mười chín trong tổng số hơn năm mươi người chạy.)"],"ukAudio":"/ai_services/tts3/?q=nineteenth&lang=en-GB&ipa=%2F%CB%8Cna%C9%AAn.%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=nineteenth&lang=en-US&ipa=%2F%CB%8Cna%C9%AAn.%CB%88tin%CE%B8%2F"},{"id":"lv_4_264","topic":"Cultural and Historical Exchange","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, lời nhận xét","defEn":"the act of watching somebody or something carefully, or a remark based on what is noticed","examples":["The scientist spent years making detailed [observation] of bird migration patterns. (=Dịch: Nhà khoa học đã dành nhiều năm thực hiện việc quan sát chi tiết về các mô hình di cư của loài chim.)","She made an insightful [observation] about the current economic situation. (=Dịch: Cô ấy đã đưa ra một nhận xét sâu sắc về tình hình kinh tế hiện nay.)","The patient was kept in the hospital overnight for close [observation]. (=Dịch: Bệnh nhân được giữ lại bệnh viện qua đêm để theo dõi chặt chẽ.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_265","topic":"Cultural and Historical Exchange","word":"obstacle","pos":"(n)","ipa":"/ˈɑːb.stə.kəl/","defVi":"trở ngại, chướng ngại vật","defEn":"something that makes it difficult for you to achieve something","examples":["Lack of funding proved to be a major [obstacle] to completing the project. (=Dịch: Sự thiếu hụt kinh phí hóa ra là một trở ngại lớn đối với việc hoàn thành dự án.)","She had to overcome many an [obstacle] before reaching her career goals. (=Dịch: Cô ấy đã phải vượt qua muôn vàn trở ngại trước khi đạt được các mục tiêu nghề nghiệp của mình.)","Language differences can sometimes act as an [obstacle] to effective communication. (=Dịch: Sự khác biệt về ngôn ngữ đôi khi có thể trở thành rào cản đối với việc giao tiếp hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=obstacle&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90b.st%C9%99.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=obstacle&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90b.st%C9%99.k%C9%99l%2F"},{"id":"lv_4_266","topic":"Cultural and Historical Exchange","word":"olympic","pos":"(adj)","ipa":"/oʊˈlɪm.pɪk/","defVi":"thuộc về Thế vận hội Olympic","defEn":"relating to the ancient or modern Olympic Games","examples":["Winning an [Olympic] gold medal was the dream of her life. (=Dịch: Giành được huy chương vàng Olympic là ước mơ cả đời của cô ấy.)","The city built a new [Olympic] stadium for the upcoming games. (=Dịch: Thành phố đã xây dựng một sân vận động Olympic mới cho kỳ thế vận hội sắp tới.)","He trained rigorously to meet the strict [Olympic] qualifying standards. (=Dịch: Anh ấy đã tập luyện nghiêm ngặt để đáp ứng các tiêu chuẩn vòng loại Olympic khắt khe.)"],"ukAudio":"/ai_services/tts3/?q=olympic&lang=en-GB&ipa=%2Fo%CA%8A%CB%88l%C9%AAm.p%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=olympic&lang=en-US&ipa=%2Fo%CA%8A%CB%88l%C9%AAm.p%C9%AAk%2F"},{"id":"lv_4_267","topic":"Cultural and Historical Exchange","word":"onwards","pos":"(adv)","ipa":"/ˈɑːn.wɚdz/","defVi":"trở đi, về phía trước","defEn":"continuing forward in space or time from a particular point","examples":["From the age of eighteen [onwards], she lived independently. (=Dịch: Kể từ năm mười tám tuổi trở đi, cô ấy đã sống tự lập.)","The project moved [onwards] despite several technical difficulties. (=Dịch: Dự án vẫn tiếp tục tiến triển bất chấp một số khó khăn về mặt kỹ thuật.)","The exhibition is open daily from ten in the morning [onwards]. (=Dịch: Triển lãm mở cửa hàng ngày từ mười giờ sáng trở đi.)"],"ukAudio":"/ai_services/tts3/?q=onwards&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90n.w%C9%9Adz%2F","usAudio":"/ai_services/tts3/?q=onwards&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90n.w%C9%9Adz%2F"},{"id":"lv_4_268","topic":"Cultural and Historical Exchange","word":"opera","pos":"(n)","ipa":"/ˈɑː.prə/","defVi":"vở nhạc kịch opera, ca kịch","defEn":"a musical play in which most of the words are sung rather than spoken","examples":["We bought front-row tickets to watch a famous Italian [opera]. (=Dịch: Chúng tôi đã mua vé hàng ghế đầu để xem một vở opera nổi tiếng của Ý.)","She has trained for years to become a professional [opera] singer. (=Dịch: Cô ấy đã rèn luyện nhiều năm để trở thành một ca sĩ opera chuyên nghiệp.)","The city's grand [opera] house was built more than a century ago. (=Dịch: Nhà hát opera tráng lệ của thành phố được xây dựng cách đây hơn một thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=opera&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.pr%C9%99%2F","usAudio":"/ai_services/tts3/?q=opera&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.pr%C9%99%2F"},{"id":"lv_4_269","topic":"Cultural and Historical Exchange","word":"optimistic","pos":"(adj)","ipa":"/ˌɑːp.təˈmɪs.tɪk/","defVi":"lạc quan","defEn":"expecting good things to happen or something to be successful","examples":["He remains [optimistic] about the future of the company. (=Dịch: Anh ấy vẫn lạc quan về tương lai của công ty.)","Despite the difficulties, she maintains an [optimistic] attitude. (=Dịch: Bất chấp những khó khăn, cô ấy vẫn duy trì một thái độ lạc quan.)","Experts are [optimistic] that the economy will recover next year. (=Dịch: Các chuyên gia rất lạc quan rằng nền kinh tế sẽ phục hồi vào năm tới.)"],"ukAudio":"/ai_services/tts3/?q=optimistic&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90p.t%C9%99%CB%88m%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=optimistic&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90p.t%C9%99%CB%88m%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_270","topic":"Cultural and Historical Exchange","word":"orchestra","pos":"(n)","ipa":"/ˈɔːr.kə.strə/","defVi":"dàn nhạc giao hưởng","defEn":"a large group of musicians playing many different instruments together and led by a conductor","examples":["The symphony [orchestra] performed a masterpiece by Beethoven last night. (=Dịch: Dàn nhạc giao hưởng đã biểu diễn một kiệt tác của Beethoven vào tối qua.)","He plays the violin in a prestigious youth [orchestra]. (=Dịch: Cậu ấy chơi vĩ cầm trong một dàn nhạc trẻ danh tiếng.)","The conductor raised his baton and the entire [orchestra] went silent. (=Dịch: Nhạc trưởng giơ đũa chỉ huy lên và toàn bộ dàn nhạc liền im lặng.)"],"ukAudio":"/ai_services/tts3/?q=orchestra&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F","usAudio":"/ai_services/tts3/?q=orchestra&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.k%C9%99.str%C9%99%2F"},{"id":"lv_4_271","topic":"Cultural and Historical Exchange","word":"orchestral","pos":"(adj)","ipa":"/ɔrˈkɛs.trəl/","defVi":"thuộc về dàn nhạc giao hưởng","defEn":"composed for, performed by, or relating to an orchestra","examples":["The concert featured a magnificent [orchestral] performance by local musicians. (=Dịch: Buổi hòa nhạc có một màn trình diễn dàn nhạc tuyệt vời của các nhạc sĩ địa phương.)","She has composed several [orchestral] pieces for film soundtracks. (=Dịch: Cô ấy đã sáng tác một số tác phẩm cho dàn nhạc phục vụ nhạc phim.)","The conductor is rehearsing the new [orchestral] score with the team. (=Dịch: Nhạc trưởng đang tập dượt tổng phổ dàn nhạc mới cùng với cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=orchestral&lang=en-GB&ipa=%2F%C9%94r%CB%88k%C9%9Bs.tr%C9%99l%2F","usAudio":"/ai_services/tts3/?q=orchestral&lang=en-US&ipa=%2F%C9%94r%CB%88k%C9%9Bs.tr%C9%99l%2F"},{"id":"lv_4_272","topic":"Cultural and Historical Exchange","word":"origin","pos":"(n)","ipa":"/ˈɔːr.ə.dʒɪn/","defVi":"nguồn gốc, căn nguyên","defEn":"the point or place where something begins or comes from","examples":["Scientists are studying the [origin] of the universe. (=Dịch: Các nhà khoa học đang nghiên cứu nguồn gốc của vũ trụ.)","The word has its [origin] in ancient Latin. (=Dịch: Từ này có nguồn gốc từ tiếng Latinh cổ.)","She never forgot the humble [origin] of her family. (=Dịch: Cô ấy chưa bao giờ quên xuất thân khiêm tốn của gia đình mình.)"],"ukAudio":"/ai_services/tts3/?q=origin&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=origin&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99.d%CA%92%C9%AAn%2F"},{"id":"lv_4_273","topic":"Cultural and Historical Exchange","word":"outcome","pos":"(n)","ipa":"/ˈaʊtˌkʌm/","defVi":"kết quả, hậu quả","defEn":"the final result of an activity, process, or meeting","examples":["The [outcome] of the election will shape the country's economic policies. (=Dịch: Kết quả của cuộc bầu cử sẽ định hình các chính sách kinh tế của đất nước.)","Doctors are cautiously optimistic about the [outcome] of the surgery. (=Dịch: Các bác sĩ tỏ ra lạc quan một cách thận trọng về kết quả của ca phẫu thuật.)","Several factors can influence the final [outcome] of this research project. (=Dịch: Một số yếu tố có thể ảnh hưởng đến kết quả cuối cùng của dự án nghiên cứu này.)"],"ukAudio":"/ai_services/tts3/?q=outcome&lang=en-GB&ipa=%2F%CB%88a%CA%8At%CB%8Ck%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=outcome&lang=en-US&ipa=%2F%CB%88a%CA%8At%CB%8Ck%CA%8Cm%2F"},{"id":"lv_4_274","topic":"Cultural and Historical Exchange","word":"pacific","pos":"(n)","ipa":"/pəˈsɪf.ɪk/","defVi":"Thái Bình Dương","defEn":"the largest of the world's oceans, lying between America to the east and Asia and Australia to the west","examples":["Several island nations are scattered across the vast [Pacific] Ocean. (=Dịch: Một số quốc đảo nằm rải rác trên khắp Thái Bình Dương rộng lớn.)","They embarked on a cruise across the South [Pacific]. (=Dịch: Họ đã bắt đầu chuyến du ngoạn trên biển băng qua vùng Nam Thái Bình Dương.)","Marine biologists are studying rare deep-sea species found in the North [Pacific]. (=Dịch: Các nhà sinh vật biển đang nghiên cứu các loài sinh vật biển sâu quý hiếm được tìm thấy ở Bắc Thái Bình Dương.)"],"ukAudio":"/ai_services/tts3/?q=pacific&lang=en-GB&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=pacific&lang=en-US&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F"},{"id":"lv_4_275","topic":"Cultural and Historical Exchange","word":"perfume","pos":"(n)","ipa":"/ˈpɝː.fjuːm/","defVi":"nước hoa, hương thơm","defEn":"a liquid with a pleasant smell that people spray on their skin or clothes","examples":["She sprayed a floral [perfume] onto her wrists before heading out to the party. (=Dịch: Cô ấy đã xịt một chút nước hoa hương hoa cỏ lên cổ tay trước khi ra ngoài dự tiệc.)","The delicate [perfume] of blooming roses filled the entire garden. (=Dịch: Hương thơm thoang thoảng của hoa hồng nở rộ tràn ngập khắp cả khu vườn.)","France is world-renowned for producing some of the most expensive [perfume] brands. (=Dịch: Nước Pháp nổi tiếng thế giới về việc sản xuất một số thương hiệu nước hoa đắt đỏ nhất.)"],"ukAudio":"/ai_services/tts3/?q=perfume&lang=en-GB&ipa=%2F%CB%88p%C9%9D%CB%90.fju%CB%90m%2F","usAudio":"/ai_services/tts3/?q=perfume&lang=en-US&ipa=%2F%CB%88p%C9%9D%CB%90.fju%CB%90m%2F"},{"id":"lv_4_276","topic":"Cultural and Historical Exchange","word":"phenomenon","pos":"(n)","ipa":"/fəˈnɑː.məˌnɑːn/","defVi":"hiện tượng","defEn":"a fact or event in nature or society, especially one that is not fully understood","examples":["Global warming is a complex environmental [phenomenon] that affects the entire planet. (=Dịch: Sự nóng lên toàn cầu là một hiện tượng môi trường phức tạp ảnh hưởng đến toàn bộ hành tinh.)","Scientists gathered to observe the rare celestial [phenomenon]. (=Dịch: Các nhà khoa học đã tập hợp lại để quan sát hiện tượng thiên văn hiếm gặp này.)","The rapid growth of online learning has become a global [phenomenon]. (=Dịch: Sự phát triển nhanh chóng của hình thức học trực tuyến đã trở thành một hiện tượng toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=phenomenon&lang=en-GB&ipa=%2Ff%C9%99%CB%88n%C9%91%CB%90.m%C9%99%CB%8Cn%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=phenomenon&lang=en-US&ipa=%2Ff%C9%99%CB%88n%C9%91%CB%90.m%C9%99%CB%8Cn%C9%91%CB%90n%2F"},{"id":"lv_4_277","topic":"Cultural and Historical Exchange","word":"philosopher","pos":"(n)","ipa":"/fəˈlɑː.sə.fɚ/","defVi":"nhà triết học, triết gia","defEn":"a person who studies or writes about the fundamental questions of life and existence","examples":["Socrates was an influential Greek [philosopher] whose teachings shaped Western thought. (=Dịch: Socrates là một triết gia Hy Lạp có tầm ảnh hưởng lớn, người mà những lời dạy của ông đã định hình nên tư tưởng phương Tây.)","A modern [philosopher] often analyzes the moral implications of artificial intelligence. (=Dịch: Một triết gia hiện đại thường phân tích các tác động về mặt đạo đức của trí tuệ nhân tạo.)","He is widely regarded as a brilliant [philosopher] of science and ethics. (=Dịch: Ông được nhiều người coi là một nhà triết học lỗi lạc về khoa học và đạo đức học.)"],"ukAudio":"/ai_services/tts3/?q=philosopher&lang=en-GB&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.f%C9%9A%2F","usAudio":"/ai_services/tts3/?q=philosopher&lang=en-US&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.f%C9%9A%2F"},{"id":"lv_4_278","topic":"Cultural and Historical Exchange","word":"philosophy","pos":"(n)","ipa":"/fəˈlɑː.sə.fi/","defVi":"triết học, triết lý","defEn":"the study of the fundamental nature of knowledge, reality, and existence","examples":["She decided to major in [philosophy] because she loved debating ethical questions. (=Dịch: Cô ấy quyết định theo học chuyên ngành triết học vì cô ấy thích tranh luận về các câu hỏi đạo đức.)","The company's [philosophy] focuses on sustainability and customer satisfaction. (=Dịch: Triết lý của công ty tập trung vào tính bền vững và sự hài lòng của khách hàng.)","Eastern [philosophy] often emphasizes harmony between human beings and the natural world. (=Dịch: Triết học phương Đông thường nhấn mạnh sự hòa hợp giữa con người và thế giới tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=philosophy&lang=en-GB&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=philosophy&lang=en-US&ipa=%2Ff%C9%99%CB%88l%C9%91%CB%90.s%C9%99.fi%2F"},{"id":"lv_4_279","topic":"Cultural and Historical Exchange","word":"physician","pos":"(n)","ipa":"/fɪˈzɪʃ.ən/","defVi":"bác sĩ (thường là bác sĩ nội khoa hoặc điều trị y tế)","defEn":"a medical doctor, especially one who specializes in diagnosis and medical treatment rather than surgery","examples":["She consulted a [physician] after experiencing persistent headaches. (=Dịch: Cô ấy đã đến khám bác sĩ sau khi bị đau đầu dai dẳng.)","The hospital employs several experienced [physicians] in its cardiology department. (=Dịch: Bệnh viện tuyển dụng nhiều bác sĩ giàu kinh nghiệm trong khoa tim mạch.)","Always follow the advice of a qualified [physician] before taking new medication. (=Dịch: Hãy luôn làm theo lời khuyên của bác sĩ có chuyên môn trước khi dùng thuốc mới.)"],"ukAudio":"/ai_services/tts3/?q=physician&lang=en-GB&ipa=%2Ff%C9%AA%CB%88z%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=physician&lang=en-US&ipa=%2Ff%C9%AA%CB%88z%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_280","topic":"Cultural and Historical Exchange","word":"pianist","pos":"(n)","ipa":"/ˈpiː.ə.nɪst/","defVi":"nghệ sĩ dương cầm, người chơi đàn piano","defEn":"a person who plays the piano, especially skillfully or professionally","examples":["The talented [pianist] received a standing ovation after performing the concerto. (=Dịch: Nghệ sĩ dương cầm tài năng đã nhận được tràng pháo tay nhiệt liệt sau khi biểu diễn bản hòa tấu.)","She hopes to become a concert [pianist] after graduating from the music academy. (=Dịch: Cô ấy hy vọng trở thành một nghệ sĩ dương cầm biểu diễn hòa nhạc sau khi tốt nghiệp học viện âm nhạc.)","A jazz [pianist] was hired to entertain guests during the dinner party. (=Dịch: Một nghệ sĩ dương cầm nhạc jazz đã được thuê để biểu diễn phục vụ khách trong bữa tiệc tối.)"],"ukAudio":"/ai_services/tts3/?q=pianist&lang=en-GB&ipa=%2F%CB%88pi%CB%90.%C9%99.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=pianist&lang=en-US&ipa=%2F%CB%88pi%CB%90.%C9%99.n%C9%AAst%2F"},{"id":"lv_4_281","topic":"Cultural and Historical Exchange","word":"pit","pos":"(n)","ipa":"/pɪt/","defVi":"hố sâu, hầm than hoặc mỏ khoáng sản","defEn":"a large deep hole in the ground, or a place where minerals are mined","examples":["The workers dug a deep [pit] to lay the foundation for the new building. (=Dịch: Các công nhân đã đào một cái hố sâu để đặt móng cho tòa nhà mới.)","Many men in the town used to work down in the coal [pit]. (=Dịch: Nhiều người đàn ông trong thị trấn từng làm việc dưới hầm mỏ than.)","Be careful not to fall into the gravel [pit] near the construction site. (=Dịch: Hãy cẩn thận kẻo ngã vào hố sỏi gần công trường xây dựng.)"],"ukAudio":"/ai_services/tts3/?q=pit&lang=en-GB&ipa=%2Fp%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pit&lang=en-US&ipa=%2Fp%C9%AAt%2F"},{"id":"lv_4_282","topic":"Cultural and Historical Exchange","word":"plantation","pos":"(n)","ipa":"/plænˈteɪ.ʃən/","defVi":"đồn điền, trang trại lớn","defEn":"a large area of land on which crops such as tea, coffee, or rubber are grown","examples":["Many local workers are employed on the vast tea [plantation]. (=Dịch: Nhiều lao động địa phương được thuê làm việc tại đồn điền chè rộng lớn.)","The company owns a large rubber [plantation] in the southern region. (=Dịch: Công ty sở hữu một đồn điền cao su lớn ở khu vực phía nam.)","They took a guided tour through an old coffee [plantation] during their vacation. (=Dịch: Họ đã tham gia một chuyến tham quan có hướng dẫn viên qua một đồn điền cà phê lâu đời trong kỳ nghỉ của mình.)"],"ukAudio":"/ai_services/tts3/?q=plantation&lang=en-GB&ipa=%2Fpl%C3%A6n%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=plantation&lang=en-US&ipa=%2Fpl%C3%A6n%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_283","topic":"Cultural and Historical Exchange","word":"plot","pos":"(n)","ipa":"/plɑːt/","defVi":"cốt truyện; mảnh đất","defEn":"the series of events forming the main story of a book, film, or play","examples":["The novel has an intricate [plot] filled with unexpected twists. (=Dịch: Cuốn tiểu thuyết có một cốt truyện phức tạp với đầy những nút thắt bất ngờ.)","They purchased a small [plot] of land to build their dream house. (=Dịch: Họ đã mua một mảnh đất nhỏ để xây dựng ngôi nhà mơ ước của mình.)","Critics praised the movie for its engaging characters and solid [plot]. (=Dịch: Các nhà phê bình đã khen ngợi bộ phim vì các nhân vật lôi cuốn và cốt truyện chặt chẽ.)"],"ukAudio":"/ai_services/tts3/?q=plot&lang=en-GB&ipa=%2Fpl%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=plot&lang=en-US&ipa=%2Fpl%C9%91%CB%90t%2F"},{"id":"lv_4_284","topic":"Cultural and Historical Exchange","word":"plough","pos":"(v)","ipa":"/plaʊ/","defVi":"cày xới, cày ruộng","defEn":"to dig and turn over soil with a large farming tool before planting seeds","examples":["Farmers usually [plough] their fields in early spring before planting crops. (=Dịch: Nông dân thường cày ruộng vào đầu mùa xuân trước khi gieo trồng mùa màng.)","The tractor was used to [plough] the rocky hillside efficiently. (=Dịch: Máy kéo được sử dụng để cày xới sườn đồi nhiều đá một cách hiệu quả.)","They had to [plough] through the thick snow to clear the main road. (=Dịch: Họ đã phải ủi qua lớp tuyết dày để khai thông con đường chính.)"],"ukAudio":"/ai_services/tts3/?q=plough&lang=en-GB&ipa=%2Fpla%CA%8A%2F","usAudio":"/ai_services/tts3/?q=plough&lang=en-US&ipa=%2Fpla%CA%8A%2F"},{"id":"lv_4_285","topic":"Cultural and Historical Exchange","word":"polish","pos":"(v)","ipa":"/ˈpɑ.lɪʃ/","defVi":"đánh bóng, trau chuốt, hoàn thiện","defEn":"to make something smooth and shiny, or to improve and refine it","examples":["You should [polish] your leather shoes before going to the interview. (=Dịch: Bạn nên đánh bóng giày da trước khi đi phỏng vấn.)","The student spent the weekend trying to [polish] her essay. (=Dịch: Nữ sinh đã dành cả cuối tuần để cố gắng trau chuốt bài luận của mình.)","He practiced speaking every day to [polish] his presentation skills. (=Dịch: Anh ấy luyện nói mỗi ngày để mài giũa kỹ năng thuyết trình của mình.)"],"ukAudio":"/ai_services/tts3/?q=polish&lang=en-GB&ipa=%2F%CB%88p%C9%91.l%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=polish&lang=en-US&ipa=%2F%CB%88p%C9%91.l%C9%AA%CA%83%2F"},{"id":"lv_4_286","topic":"Cultural and Historical Exchange","word":"polished","pos":"(adj)","ipa":"/ˈpɑː.lɪʃt/","defVi":"sáng bóng, trau chuốt, điêu luyện","defEn":"having a smooth, shiny surface from rubbing; refined and well-rehearsed","examples":["She wore elegant shoes that walked across the [polished] wooden floor. (=Dịch: Cô ấy đi đôi giày thanh lịch bước qua sàn gỗ sáng bóng.)","The candidate delivered a very [polished] and confident speech. (=Dịch: Ứng viên đã có một bài phát biểu rất trau chuốt và đầy tự tin.)","His [polished] manners made a great impression on the guests. (=Dịch: Cách cư xử lịch thiệp của anh ấy đã để lại ấn tượng tuyệt vời cho các vị khách.)"],"ukAudio":"/ai_services/tts3/?q=polished&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%AA%CA%83t%2F","usAudio":"/ai_services/tts3/?q=polished&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%AA%CA%83t%2F"},{"id":"lv_4_287","topic":"Cultural and Historical Exchange","word":"politician","pos":"(n)","ipa":"/ˌpɑː.ləˈtɪʃ.ən/","defVi":"chính trị gia","defEn":"a person who is professionally involved in politics, especially as an elected official","examples":["The local [politician] promised to improve public transport during her campaign. (=Dịch: Chính trị gia địa phương đã hứa sẽ cải thiện giao thông công cộng trong chiến dịch tranh cử của bà.)","Many young people feel that [politicians] do not represent their interests. (=Dịch: Nhiều người trẻ cảm thấy rằng các chính trị gia không đại diện cho lợi ích của họ.)","The [politician] gave an inspiring speech about environmental conservation. (=Dịch: Chính trị gia đã có một bài phát biểu đầy cảm hứng về việc bảo tồn môi trường.)"],"ukAudio":"/ai_services/tts3/?q=politician&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.l%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=politician&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.l%C9%99%CB%88t%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_288","topic":"Cultural and Historical Exchange","word":"porcelain","pos":"(n)","ipa":"/ˈpɔːr.sə.lɪn/","defVi":"đồ sứ, chất liệu sứ","defEn":"a hard, white, translucent ceramic material made by heating clay at high temperatures","examples":["The museum displays an exquisite collection of ancient Chinese [porcelain]. (=Dịch: Bảo tàng trưng bày một bộ sưu tập đồ sứ Trung Quốc cổ đại tuyệt đẹp.)","She carefully handled the delicate [porcelain] teacup to avoid chipping it. (=Dịch: Cô cẩn thận cầm tách trà bằng sứ mỏng manh để tránh làm sứt mẻ.)","High-quality [porcelain] is known for its durability and smooth finish. (=Dịch: Đồ sứ chất lượng cao nổi tiếng về độ bền và bề mặt nhẵn mịn.)"],"ukAudio":"/ai_services/tts3/?q=porcelain&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.s%C9%99.l%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=porcelain&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.s%C9%99.l%C9%AAn%2F"},{"id":"lv_4_289","topic":"Cultural and Historical Exchange","word":"port","pos":"(n)","ipa":"/pɔːrt/","defVi":"cảng, thành phố cảng","defEn":"a town or city with a harbor where ships load and unload goods or passengers","examples":["The cargo vessel finally arrived at the busy commercial [port] after a long voyage. (=Dịch: Tàu chở hàng cuối cùng đã cập cảng thương mại sầm uất sau một chuyến hải trình dài.)","Exporting goods through the international [port] helps boost the regional economy. (=Dịch: Việc xuất khẩu hàng hóa qua cảng quốc tế giúp thúc đẩy nền kinh tế khu vực.)","Fishermen returned to the safe [port] before the heavy storm hit the coast. (=Dịch: Các ngư dân đã quay trở lại cảng an toàn trước khi cơn bão lớn đổ bộ vào bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=port&lang=en-GB&ipa=%2Fp%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=port&lang=en-US&ipa=%2Fp%C9%94%CB%90rt%2F"},{"id":"lv_4_290","topic":"Cultural and Historical Exchange","word":"portrait","pos":"(n)","ipa":"/ˈpɔːr.trət/","defVi":"bức chân dung","defEn":"a painting, drawing, or photograph of a person, especially showing the face","examples":["The gallery displayed a famous [portrait] of the queen. (=Dịch: Phòng trưng bày đã trưng bày một bức chân dung nổi tiếng của nữ hoàng.)","He commissioned an artist to paint a family [portrait]. (=Dịch: Anh ấy đã thuê một họa sĩ vẽ một bức chân dung gia đình.)","The biography provides an accurate [portrait] of the president's life. (=Dịch: Cuốn tiểu sử khắc họa một bức chân dung chính xác về cuộc đời của tổng thống.)"],"ukAudio":"/ai_services/tts3/?q=portrait&lang=en-GB&ipa=%2F%CB%88p%C9%94%CB%90r.tr%C9%99t%2F","usAudio":"/ai_services/tts3/?q=portrait&lang=en-US&ipa=%2F%CB%88p%C9%94%CB%90r.tr%C9%99t%2F"},{"id":"lv_4_291","topic":"Cultural and Historical Exchange","word":"pot","pos":"(n)","ipa":"/pɑːt/","defVi":"nồi, xoong, chậu (cây)","defEn":"a deep, round container used for cooking, holding liquids, or growing plants","examples":["She put a large [pot] of soup on the stove to simmer for dinner. (=Dịch: Cô ấy đặt một nồi súp lớn lên bếp để ninh nhỏ lửa cho bữa tối.)","He transplanted the small herb into a ceramic [pot] on the windowsill. (=Dịch: Anh ấy đã chuyển cây thảo mộc nhỏ vào một chiếc chậu gốm trên bậu cửa sổ.)","Archaeologists discovered an ancient clay [pot] buried deep beneath the ruins. (=Dịch: Các nhà khảo cổ học đã phát hiện ra một chiếc bình đất sét cổ được chôn sâu bên dưới đống tàn tích.)"],"ukAudio":"/ai_services/tts3/?q=pot&lang=en-GB&ipa=%2Fp%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=pot&lang=en-US&ipa=%2Fp%C9%91%CB%90t%2F"},{"id":"lv_4_292","topic":"Cultural and Historical Exchange","word":"potter","pos":"(n)","ipa":"/ˈpɑː.t̬ɚ/","defVi":"thợ làm gốm","defEn":"a person who makes pottery dishes, pots, and other objects out of clay","examples":["The skilled [potter] shaped the wet clay into an elegant vase. (=Dịch: Người thợ gốm lành nghề đã nặn đất sét ướt thành một chiếc bình thanh lịch.)","Visitors can watch the local [potter] at work in the artisan village. (=Dịch: Du khách có thể xem người thợ gốm địa phương làm việc trong làng nghề thủ công.)","She bought a handmade ceramic mug directly from the [potter]. (=Dịch: Cô ấy đã mua một chiếc cốc gốm thủ công trực tiếp từ người thợ gốm.)"],"ukAudio":"/ai_services/tts3/?q=potter&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=potter&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_4_293","topic":"Cultural and Historical Exchange","word":"pottery","pos":"(n)","ipa":"/ˈpɑː.t̬ɚ.i/","defVi":"đồ gốm, nghề gốm","defEn":"objects such as plates and cups made out of clay and baked in an oven","examples":["Archaeologists discovered pieces of ancient [pottery] at the site. (=Dịch: Các nhà khảo cổ học đã phát hiện ra những mảnh đồ gốm cổ tại địa điểm này.)","She enjoys making handmade [pottery] in her spare time. (=Dịch: Cô ấy thích làm đồ gốm thủ công vào thời gian rảnh.)","The museum has a magnificent collection of Greek [pottery]. (=Dịch: Bảo tàng có một bộ sưu tập đồ gốm Hy Lạp tuyệt đẹp.)"],"ukAudio":"/ai_services/tts3/?q=pottery&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=pottery&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.t%CC%AC%C9%9A.i%2F"},{"id":"lv_4_294","topic":"Cultural and Historical Exchange","word":"pour","pos":"(v)","ipa":"/pɔr/","defVi":"rót, đổ, trút nước","defEn":"to cause liquid to flow continuously out of a container","examples":["Please [pour] some fresh water into my glass. (=Dịch: Xin vui lòng rót một ít nước sạch vào ly của tôi.)","Dark clouds gathered overhead and rain began to [pour] down heavily. (=Dịch: Mây đen kéo đến trên đầu và mưa bắt đầu trút xuống xối xả.)","Carefully [pour] the mixture into the baking dish and put it in the oven. (=Dịch: Hãy cẩn thận đổ hỗn hợp vào khuôn nướng rồi cho vào lò.)"],"ukAudio":"/ai_services/tts3/?q=pour&lang=en-GB&ipa=%2Fp%C9%94r%2F","usAudio":"/ai_services/tts3/?q=pour&lang=en-US&ipa=%2Fp%C9%94r%2F"},{"id":"lv_4_295","topic":"Cultural and Historical Exchange","word":"poverty","pos":"(n)","ipa":"/ˈpɑː.vɚ.t̬i/","defVi":"sự nghèo khó, cảnh bần cùng","defEn":"the state of being extremely poor and lacking basic necessities","examples":["Many families in the region are living in extreme [poverty]. (=Dịch: Nhiều gia đình trong khu vực đang sống trong cảnh nghèo đói cùng cực.)","Education is widely considered a key tool to escape [poverty]. (=Dịch: Giáo dục được coi rộng rãi là công cụ then chốt để thoát nghèo.)","The government launched several programs to reduce child [poverty]. (=Dịch: Chính phủ đã khởi xướng một số chương trình nhằm giảm tỷ lệ nghèo ở trẻ em.)"],"ukAudio":"/ai_services/tts3/?q=poverty&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=poverty&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.v%C9%9A.t%CC%ACi%2F"},{"id":"lv_4_296","topic":"Cultural and Historical Exchange","word":"precise","pos":"(adj)","ipa":"/prɪˈsaɪs/","defVi":"chính xác, tỉ mỉ","defEn":"exact, accurate, and clear in every detail","examples":["The scientist recorded the [precise] measurements of the chemical solution. (=Dịch: Nhà khoa học đã ghi lại các phép đo chính xác của dung dịch hóa chất.)","Please give me [precise] instructions so that I do not make any mistakes. (=Dịch: Xin hãy cho tôi hướng dẫn chính xác để tôi không mắc phải bất kỳ sai sót nào.)","The satellite is capable of determining a vehicle's [precise] location. (=Dịch: Vệ tinh có khả năng xác định vị trí chính xác của một phương tiện.)"],"ukAudio":"/ai_services/tts3/?q=precise&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=precise&lang=en-US&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F"},{"id":"lv_4_297","topic":"Cultural and Historical Exchange","word":"prehistoric","pos":"(adj)","ipa":"/ˌpriː.hɪˈstɔːr.ɪk/","defVi":"tiền sử","defEn":"relating to the period of time before written records existed","examples":["Archaeologists found ancient tools in the [prehistoric] cave. (=Dịch: Các nhà khảo cổ học đã tìm thấy các công cụ cổ xưa trong hang động tiền sử.)","Dinosaurs are among the most famous [prehistoric] creatures. (=Dịch: Khủng long nằm trong số những sinh vật tiền sử nổi tiếng nhất.)","The museum exhibits several [prehistoric] rock paintings. (=Dịch: Bảo tàng trưng bày một số bức tranh đá thời tiền sử.)"],"ukAudio":"/ai_services/tts3/?q=prehistoric&lang=en-GB&ipa=%2F%CB%8Cpri%CB%90.h%C9%AA%CB%88st%C9%94%CB%90r.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=prehistoric&lang=en-US&ipa=%2F%CB%8Cpri%CB%90.h%C9%AA%CB%88st%C9%94%CB%90r.%C9%AAk%2F"},{"id":"lv_4_298","topic":"Cultural and Historical Exchange","word":"preparation","pos":"(n)","ipa":"/ˌprep.əˈreɪ.ʃən/","defVi":"sự chuẩn bị, công tác chuẩn bị","defEn":"the act or process of getting ready for something that will happen","examples":["Thorough [preparation] is essential for achieving a high score on the IELTS exam. (=Dịch: Sự chuẩn bị kỹ lưỡng là điều cần thiết để đạt điểm cao trong kỳ thi IELTS.)","They spent several months in [preparation] for the international conference. (=Dịch: Họ đã dành vài tháng để chuẩn bị cho hội nghị quốc tế.)","Careful food [preparation] helps prevent serious health risks. (=Dịch: Việc chuẩn bị thực phẩm cẩn thận giúp ngăn ngừa các rủi ro sức khỏe nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=preparation&lang=en-GB&ipa=%2F%CB%8Cprep.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=preparation&lang=en-US&ipa=%2F%CB%8Cprep.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_299","topic":"Cultural and Historical Exchange","word":"preserve","pos":"(v)","ipa":"/prɪˈzɜrv/","defVi":"bảo tồn, gìn giữ","defEn":"to keep something in its original state or in good condition","examples":["We must take urgent action to [preserve] historic architecture in the city center. (=Dịch: Chúng ta phải hành động khẩn cấp để bảo tồn kiến trúc lịch sử ở trung tâm thành phố.)","The government introduced strict laws to [preserve] endangered wildlife habitats. (=Dịch: Chính phủ đã ban hành các luật lệ nghiêm ngặt để bảo tồn môi trường sống của động vật hoang dã có nguy cơ tuyệt chủng.)","Traditional methods are still used to [preserve] fish during the winter months. (=Dịch: Các phương pháp truyền thống vẫn được sử dụng để bảo quản cá trong những tháng mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=preserve&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88z%C9%9Crv%2F","usAudio":"/ai_services/tts3/?q=preserve&lang=en-US&ipa=%2Fpr%C9%AA%CB%88z%C9%9Crv%2F"},{"id":"lv_4_300","topic":"Cultural and Historical Exchange","word":"priest","pos":"(n)","ipa":"/priːst/","defVi":"linh mục, thầy tế, giáo sĩ","defEn":"a person authorized to perform religious sacred rites, especially in Christian traditions","examples":["The parish [priest] delivered an inspiring sermon to the congregation. (=Dịch: Linh mục giáo xứ đã thuyết giảng một bài giảng đầy cảm hứng cho các giáo dân.)","The couple asked the local [priest] to bless their marriage. (=Dịch: Cặp đôi đã nhờ vị linh mục địa phương ban phước cho cuộc hôn nhân của họ.)","In ancient civilizations, a high [priest] held immense political power. (=Dịch: Trong các nền văn minh cổ đại, một vị thượng tế nắm giữ quyền lực chính trị to lớn.)"],"ukAudio":"/ai_services/tts3/?q=priest&lang=en-GB&ipa=%2Fpri%CB%90st%2F","usAudio":"/ai_services/tts3/?q=priest&lang=en-US&ipa=%2Fpri%CB%90st%2F"},{"id":"lv_4_301","topic":"Cultural and Historical Exchange","word":"primarily","pos":"(adv)","ipa":"/praɪˈmer.ə.li/","defVi":"chủ yếu, phần lớn","defEn":"mainly; for the most part","examples":["The charity organization focuses [primarily] on helping disadvantaged children. (=Dịch: Tổ chức từ thiện này chủ yếu tập trung vào việc giúp đỡ trẻ em có hoàn cảnh khó khăn.)","This course is designed [primarily] for beginners with no prior knowledge. (=Dịch: Khóa học này được thiết kế chủ yếu dành cho người mới bắt đầu chưa có kiến thức trước đó.)","The company's success is [primarily] due to its innovative products. (=Dịch: Thành công của công ty phần lớn nhờ vào các sản phẩm mang tính đổi mới sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=primarily&lang=en-GB&ipa=%2Fpra%C9%AA%CB%88mer.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=primarily&lang=en-US&ipa=%2Fpra%C9%AA%CB%88mer.%C9%99.li%2F"},{"id":"lv_4_302","topic":"Cultural and Historical Exchange","word":"prince","pos":"(n)","ipa":"/prɪns/","defVi":"hoàng tử","defEn":"a male member of a royal family, especially the son or grandson of a king or queen","examples":["The young [prince] was educated to prepare him for his future royal duties. (=Dịch: Vị hoàng tử trẻ đã được giáo dục để chuẩn bị cho những trọng trách hoàng gia trong tương lai.)","In the fairy tale, the [prince] searched the kingdom for the owner of the glass slipper. (=Dịch: Trong câu chuyện cổ tích, hoàng tử đã tìm kiếm khắp vương quốc chủ nhân của chiếc giày thủy tinh.)","The crown [prince] attended the international summit on behalf of the monarch. (=Dịch: Thái tử đã tham dự hội nghị thượng đỉnh quốc tế thay mặt cho quốc vương.)"],"ukAudio":"/ai_services/tts3/?q=prince&lang=en-GB&ipa=%2Fpr%C9%AAns%2F","usAudio":"/ai_services/tts3/?q=prince&lang=en-US&ipa=%2Fpr%C9%AAns%2F"},{"id":"lv_4_303","topic":"Cultural and Historical Exchange","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a fundamental truth, moral rule, or belief that guides behavior and decision-making","examples":["Refusing to accept bribes was a core [principle] that he upheld throughout his career. (=Dịch: Từ chối nhận hối lộ là nguyên tắc cốt lõi mà ông luôn giữ vững trong suốt sự nghiệp của mình.)","The machine operates on the same basic [principle] as an internal combustion engine. (=Dịch: Cỗ máy này hoạt động dựa trên cùng nguyên lý cơ bản như động cơ đốt trong.)","She made a decision based on [principle] rather than financial gain. (=Dịch: Cô ấy đã đưa ra quyết định dựa trên nguyên tắc đạo đức thay vì lợi ích tài chính.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_4_304","topic":"Cultural and Historical Exchange","word":"profession","pos":"(n)","ipa":"/prəˈfeʃ.ən/","defVi":"nghề nghiệp, chuyên môn","defEn":"a type of job that requires special training or a high level of education","examples":["Teaching is a challenging but very rewarding [profession]. (=Dịch: Dạy học là một nghề đầy thử thách nhưng rất đáng tự hào và ý nghĩa.)","He entered the legal [profession] after graduating from law school. (=Dịch: Anh ấy bước chân vào ngành luật sau khi tốt nghiệp trường luật.)","Members of the medical [profession] often work long and irregular hours. (=Dịch: Những người làm trong ngành y thường làm việc nhiều giờ và không cố định.)"],"ukAudio":"/ai_services/tts3/?q=profession&lang=en-GB&ipa=%2Fpr%C9%99%CB%88fe%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=profession&lang=en-US&ipa=%2Fpr%C9%99%CB%88fe%CA%83.%C9%99n%2F"},{"id":"lv_4_305","topic":"Cultural and Historical Exchange","word":"prominent","pos":"(adj)","ipa":"/ˈprɑː.mə.nənt/","defVi":"nổi bật, lỗi lạc, xuất chúng","defEn":"very well known, important, or easily noticed","examples":["He played a [prominent] role in negotiating the peace agreement. (=Dịch: Ông đã đóng một vai trò nổi bật trong việc đàm phán thỏa thuận hòa bình.)","The company hired a [prominent] scientist to lead the research. (=Dịch: Công ty đã thuê một nhà khoa học lỗi lạc để dẫn dắt công trình nghiên cứu.)","Her name was displayed in a [prominent] position on the poster. (=Dịch: Tên của cô được hiển thị ở một vị trí nổi bật trên tấm áp phích.)"],"ukAudio":"/ai_services/tts3/?q=prominent&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.m%C9%99.n%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=prominent&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.m%C9%99.n%C9%99nt%2F"},{"id":"lv_4_306","topic":"Cultural and Historical Exchange","word":"proud","pos":"(adj)","ipa":"/praʊd/","defVi":"tự hào, hãnh diện","defEn":"feeling deep pleasure or satisfaction as a result of one's own or someone else's achievements","examples":["Her parents were extremely [proud] of her academic achievements at university. (=Dịch: Cha mẹ cô vô cùng tự hào về những thành tích học tập của cô ở trường đại học.)","He felt [proud] to represent his country at the global environmental summit. (=Dịch: Anh cảm thấy tự hào khi được đại diện cho đất nước mình tại hội nghị thượng đỉnh về môi trường toàn cầu.)","The city is [proud] of its rich cultural history and diverse traditions. (=Dịch: Thành phố này tự hào về lịch sử văn hóa phong phú và các truyền thống đa dạng của mình.)"],"ukAudio":"/ai_services/tts3/?q=proud&lang=en-GB&ipa=%2Fpra%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=proud&lang=en-US&ipa=%2Fpra%CA%8Ad%2F"},{"id":"lv_4_307","topic":"Cultural and Historical Exchange","word":"publication","pos":"(n)","ipa":"/ˌpʌb.ləˈkeɪ.ʃən/","defVi":"ấn phẩm, sự xuất bản","defEn":"the act of making information, books, or magazines available to the public, or the printed item itself","examples":["Her latest [publication] discusses the long-term impact of climate change on agriculture. (=Dịch: Ấn phẩm mới nhất của bà thảo luận về tác động lâu dài của biến đổi khí hậu đối với nông nghiệp.)","The novel quickly became a bestseller within a month of its [publication]. (=Dịch: Cuốn tiểu thuyết đã nhanh chóng trở thành sách bán chạy nhất trong vòng một tháng kể từ ngày xuất bản.)","Academic journals often require peer review before approving an article for [publication]. (=Dịch: Các tạp chí học thuật thường yêu cầu phản biện đồng cấp trước khi phê duyệt bài viết để xuất bản.)"],"ukAudio":"/ai_services/tts3/?q=publication&lang=en-GB&ipa=%2F%CB%8Cp%CA%8Cb.l%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=publication&lang=en-US&ipa=%2F%CB%8Cp%CA%8Cb.l%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_308","topic":"Cultural and Historical Exchange","word":"publicise","pos":"(v)","ipa":"/ˈpʌb.ləˌsaɪz/","defVi":"quảng bá, công khai","defEn":"to make information about something generally known to the public","examples":["The university used social media to [publicise] the upcoming science fair. (=Dịch: Trường đại học đã sử dụng mạng xã hội để quảng bá cho hội chợ khoa học sắp tới.)","Authors often travel to different cities to [publicise] their new books. (=Dịch: Các tác giả thường đi đến các thành phố khác nhau để quảng bá cho cuốn sách mới của họ.)","The charity campaign was heavily [publicised] on local television. (=Dịch: Chiến dịch từ thiện đã được quảng bá rầm rộ trên truyền hình địa phương.)"],"ukAudio":"/ai_services/tts3/?q=publicise&lang=en-GB&ipa=%2F%CB%88p%CA%8Cb.l%C9%99%CB%8Csa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=publicise&lang=en-US&ipa=%2F%CB%88p%CA%8Cb.l%C9%99%CB%8Csa%C9%AAz%2F"},{"id":"lv_4_309","topic":"Cultural and Historical Exchange","word":"puppeteer","pos":"(n)","ipa":"/ˌpʌp.əˈtɪr/","defVi":"nghệ sĩ múa rối, người điều khiển con rối","defEn":"a person who operates puppets in theatrical performances or shows","examples":["The talented [puppeteer] used hidden strings to bring the wooden figures to life. (=Dịch: Nghệ sĩ múa rối tài ba đã dùng những sợi dây ẩn để thổi hồn vào các hình nhân bằng gỗ.)","After years of training, he became a master [puppeteer] at the traditional theater. (=Dịch: Sau nhiều năm rèn luyện, anh đã trở thành một nghệ nhân múa rối bậc thầy tại nhà hát truyền thống.)","Children watched in amazement as the [puppeteer] changed voices for different characters. (=Dịch: Bọn trẻ kinh ngạc dõi theo khi người điều khiển con rối thay đổi giọng nói cho các nhân vật khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=puppeteer&lang=en-GB&ipa=%2F%CB%8Cp%CA%8Cp.%C9%99%CB%88t%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=puppeteer&lang=en-US&ipa=%2F%CB%8Cp%CA%8Cp.%C9%99%CB%88t%C9%AAr%2F"},{"id":"lv_4_310","topic":"Cultural and Historical Exchange","word":"puppets","pos":"(n)","ipa":"/ˈpʌp.ɪts/","defVi":"những con rối","defEn":"models of people or animals manipulated by hands, rods, or strings to entertain an audience","examples":["The museum exhibits traditional shadow [puppets] collected from various Asian countries. (=Dịch: Bảo tàng trưng bày những con rối bóng truyền thống được sưu tầm từ nhiều quốc gia châu Á.)","Hand [puppets] are often used by teachers to make storytelling more engaging for children. (=Dịch: Rối tay thường được các giáo viên sử dụng để làm cho việc kể chuyện trở nên hấp dẫn hơn đối với trẻ em.)","Intricate wooden [puppets] performed an ancient folklore story on the stage. (=Dịch: Những con rối gỗ tinh xảo đã biểu diễn một câu chuyện dân gian cổ xưa trên sân khấu.)"],"ukAudio":"/ai_services/tts3/?q=puppets&lang=en-GB&ipa=%2F%CB%88p%CA%8Cp.%C9%AAts%2F","usAudio":"/ai_services/tts3/?q=puppets&lang=en-US&ipa=%2F%CB%88p%CA%8Cp.%C9%AAts%2F"},{"id":"lv_4_311","topic":"Cultural and Historical Exchange","word":"puzzle","pos":"(n)","ipa":"/ˈpʌz.əl/","defVi":"câu đố, trò chơi giải đố, điều bí ẩn","defEn":"a game, toy, or problem designed to test ingenuity or knowledge","examples":["Completing a crossword [puzzle] is a good way to improve your vocabulary. (=Dịch: Giải một câu đố ô chữ là một cách tốt để cải thiện vốn từ vựng của bạn.)","The disappearance of the ancient civilization remains an unsolved [puzzle]. (=Dịch: Sự biến mất của nền văn minh cổ đại vẫn là một bí ẩn chưa có lời giải.)","The children spent the rainy afternoon putting together a 500-piece jigsaw [puzzle]. (=Dịch: Lũ trẻ đã dành buổi chiều mưa để ghép một bức tranh xếp hình 500 mảnh.)"],"ukAudio":"/ai_services/tts3/?q=puzzle&lang=en-GB&ipa=%2F%CB%88p%CA%8Cz.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=puzzle&lang=en-US&ipa=%2F%CB%88p%CA%8Cz.%C9%99l%2F"},{"id":"lv_4_312","topic":"Cultural and Historical Exchange","word":"qualification","pos":"(n)","ipa":"/ˌkwɑː.lə.fəˈkeɪ.ʃən/","defVi":"bằng cấp, chứng chỉ, trình độ chuyên môn","defEn":"an official record showing that you have finished a training course or have the necessary skills","examples":["An academic [qualification] is essential for applying to this research position. (=Dịch: Bằng cấp học thuật là điều kiện thiết yếu để ứng tuyển vào vị trí nghiên cứu này.)","She gained a teaching [qualification] after two years of study. (=Dịch: Cô ấy đã đạt được chứng chỉ giảng dạy sau hai năm học tập.)","Practical experience is often valued just as much as a formal [qualification]. (=Dịch: Kinh nghiệm thực tế thường được coi trọng không kém gì một bằng cấp chính quy.)"],"ukAudio":"/ai_services/tts3/?q=qualification&lang=en-GB&ipa=%2F%CB%8Ckw%C9%91%CB%90.l%C9%99.f%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=qualification&lang=en-US&ipa=%2F%CB%8Ckw%C9%91%CB%90.l%C9%99.f%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_313","topic":"Cultural and Historical Exchange","word":"quarry","pos":"(n)","ipa":"/ˈkwɔːr.i/","defVi":"mỏ đá, nơi khai thác đá","defEn":"a large deep pit from which stone, slate, or other materials are extracted","examples":["The granite used to build the cathedral was sourced from a local [quarry]. (=Dịch: Đá granit dùng để xây dựng nhà thờ chính tòa được lấy từ một mỏ đá địa phương.)","Heavy machinery operated continuously at the limestone [quarry]. (=Dịch: Máy móc hạng nặng hoạt động liên tục tại mỏ đá vôi.)","The abandoned marble [quarry] has now turned into a deep lake. (=Dịch: Mỏ đá cẩm thạch bị bỏ hoang giờ đã biến thành một cái hồ sâu.)"],"ukAudio":"/ai_services/tts3/?q=quarry&lang=en-GB&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=quarry&lang=en-US&ipa=%2F%CB%88kw%C9%94%CB%90r.i%2F"},{"id":"lv_4_314","topic":"Cultural and Historical Exchange","word":"rabbit","pos":"(n)","ipa":"/ˈræb.ɪt/","defVi":"con thỏ","defEn":"a small burrowing mammal with long ears, long hind legs, and a short fluffy tail","examples":["A wild [rabbit] darted across the open meadow into the safety of the bushes. (=Dịch: Một con thỏ rừng phóng vụt qua đồng cỏ rộng mở vào nơi an toàn trong bụi rậm.)","She keeps a pet [rabbit] in a spacious cage in her backyard. (=Dịch: Cô ấy nuôi một con thỏ cưng trong chiếc lồng rộng rãi ở sân sau.)","The farmer built a sturdy fence to protect his vegetable garden from [rabbit] damage. (=Dịch: Người nông dân đã dựng một hàng rào chắc chắn để bảo vệ vườn rau của mình khỏi sự phá hoại của thỏ.)"],"ukAudio":"/ai_services/tts3/?q=rabbit&lang=en-GB&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rabbit&lang=en-US&ipa=%2F%CB%88r%C3%A6b.%C9%AAt%2F"},{"id":"lv_4_315","topic":"Cultural and Historical Exchange","word":"raft","pos":"(n)","ipa":"/ræft/","defVi":"chiếc bè, phao bè","defEn":"a flat floating structure used for transportation on water","examples":["They built a wooden [raft] to cross the river. (=Dịch: Họ đã đóng một chiếc bè gỗ để qua sông.)","The survivors drifted on a life [raft] for several days. (=Dịch: Những người sống sót đã trôi dạt trên một chiếc bè cứu sinh suốt vài ngày.)","We went on an exciting [raft] trip down the rapids. (=Dịch: Chúng tôi đã có một chuyến đi bè vượt ghềnh thác đầy hào hứng.)"],"ukAudio":"/ai_services/tts3/?q=raft&lang=en-GB&ipa=%2Fr%C3%A6ft%2F","usAudio":"/ai_services/tts3/?q=raft&lang=en-US&ipa=%2Fr%C3%A6ft%2F"},{"id":"lv_4_316","topic":"Cultural and Historical Exchange","word":"rainbow","pos":"(n)","ipa":"/ˈreɪn.boʊ/","defVi":"cầu vồng","defEn":"a curved band of different colors that appears in the sky when the sun shines through rain","examples":["A beautiful [rainbow] appeared across the sky after the storm passed. (=Dịch: Một chiếc cầu vồng tuyệt đẹp xuất hiện trên bầu trời sau khi cơn bão đi qua.)","She wore a bright dress with all the colors of the [rainbow]. (=Dịch: Cô ấy mặc một chiếc váy rực rỡ với đủ mọi sắc màu của cầu vồng.)","Sunlight refracted through the prism created an artificial [rainbow] on the wall. (=Dịch: Ánh nắng mặt trời khúc xạ qua lăng kính đã tạo nên một chiếc cầu vồng nhân tạo trên tường.)"],"ukAudio":"/ai_services/tts3/?q=rainbow&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=rainbow&lang=en-US&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F"},{"id":"lv_4_317","topic":"Cultural and Historical Exchange","word":"rationale","pos":"(n)","ipa":"/ˌræʃ.əˈnæl/","defVi":"lý do căn bản, cơ sở lý luận","defEn":"the underlying reasons or explanation for a particular action, belief, or decision","examples":["The director explained the economic [rationale] behind the company restructuring. (=Dịch: Giám đốc đã giải thích cơ sở lý luận kinh tế đằng sau việc tái cơ cấu công ty.)","What is the [rationale] for changing the school curriculum this year? (=Dịch: Lý do căn bản cho việc thay đổi chương trình giảng dạy của trường trong năm nay là gì?)","Students must provide a clear [rationale] for their choice of dissertation topic. (=Dịch: Sinh viên phải đưa ra lý do xác đáng cho sự lựa chọn đề tài luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=rationale&lang=en-GB&ipa=%2F%CB%8Cr%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l%2F","usAudio":"/ai_services/tts3/?q=rationale&lang=en-US&ipa=%2F%CB%8Cr%C3%A6%CA%83.%C9%99%CB%88n%C3%A6l%2F"},{"id":"lv_4_318","topic":"Cultural and Historical Exchange","word":"readily","pos":"(adv)","ipa":"/ˈrɛd.əl.i/","defVi":"sẵn sàng, dễ dàng","defEn":"willingly, quickly, or without difficulty","examples":["Fresh drinking water is [readily] available in all hotel rooms. (=Dịch: Nước uống sạch luôn có sẵn trong tất cả các phòng khách sạn.)","She [readily] agreed to help organize the charity event. (=Dịch: Cô ấy đã sẵn lòng đồng ý giúp tổ chức sự kiện từ thiện.)","The software is [readily] adaptable to different business needs. (=Dịch: Phần mềm này dễ dàng thích ứng với các nhu cầu kinh doanh khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=readily&lang=en-GB&ipa=%2F%CB%88r%C9%9Bd.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=readily&lang=en-US&ipa=%2F%CB%88r%C9%9Bd.%C9%99l.i%2F"},{"id":"lv_4_319","topic":"Cultural and Historical Exchange","word":"rectangular","pos":"(adj)","ipa":"/rɛkˈtæŋ.ɡjə.lɚ/","defVi":"có hình chữ nhật","defEn":"having the shape of a rectangle with four straight sides and four right angles","examples":["The dining room features a large [rectangular] wooden table. (=Dịch: Phòng ăn có một chiếc bàn gỗ lớn hình chữ nhật.)","They placed a [rectangular] rug in the center of the living room. (=Dịch: Họ đã đặt một tấm thảm hình chữ nhật ở giữa phòng khách.)","The swimming pool is [rectangular] and measures twenty-five meters in length. (=Dịch: Hồ bơi có hình chữ nhật và có chiều dài hai mươi lăm mét.)"],"ukAudio":"/ai_services/tts3/?q=rectangular&lang=en-GB&ipa=%2Fr%C9%9Bk%CB%88t%C3%A6%C5%8B.%C9%A1j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rectangular&lang=en-US&ipa=%2Fr%C9%9Bk%CB%88t%C3%A6%C5%8B.%C9%A1j%C9%99.l%C9%9A%2F"},{"id":"lv_4_320","topic":"Cultural and Historical Exchange","word":"reed","pos":"(n)","ipa":"/riːd/","defVi":"cây sậy","defEn":"a tall, slender plant with hollow stems that grows in wet ground or near water","examples":["Frogs hid among the tall [reed] plants along the edge of the pond. (=Dịch: Những con ếch ẩn nấp giữa các bụi cây sậy cao dọc theo bờ ao.)","Traditional weavers used dried [reed] fibers to make durable baskets. (=Dịch: Những người thợ dệt truyền thống đã sử dụng sợi sậy khô để làm ra những chiếc giỏ bền chắc.)","The wind made a soft whistling sound as it blew through the [reed] bed. (=Dịch: Gió tạo ra âm thanh vi vu êm dịu khi thổi qua rặng sậy.)"],"ukAudio":"/ai_services/tts3/?q=reed&lang=en-GB&ipa=%2Fri%CB%90d%2F","usAudio":"/ai_services/tts3/?q=reed&lang=en-US&ipa=%2Fri%CB%90d%2F"},{"id":"lv_4_321","topic":"Cultural and Historical Exchange","word":"reel","pos":"(n)","ipa":"/ril/","defVi":"cuộn, ống cuộn, guồng quay","defEn":"a round object around which wire, thread, or film is wound","examples":["He attached a new line to the fishing [reel] before heading to the lake. (=Dịch: Anh ấy đã gắn một sợi dây cước mới vào cuộn dây câu trước khi đi ra hồ.)","The museum preserved an old [reel] of film showing city life in the 1920s. (=Dịch: Bảo tàng đã lưu giữ một cuộn phim cũ ghi lại cuộc sống thành thị vào những năm 1920.)","She wound the remaining yarn neatly back onto the [reel]. (=Dịch: Cô ấy đã quấn gọn gàng phần len còn lại trở lại vào ống cuộn.)"],"ukAudio":"/ai_services/tts3/?q=reel&lang=en-GB&ipa=%2Fril%2F","usAudio":"/ai_services/tts3/?q=reel&lang=en-US&ipa=%2Fril%2F"},{"id":"lv_4_322","topic":"Cultural and Historical Exchange","word":"relative","pos":"(n)","ipa":"/ˈrel.ə.t̬ɪv/","defVi":"người thân, họ hàng","defEn":"a person who is related to another by blood or marriage","examples":["She traveled across the country to visit an elderly [relative] in the hospital. (=Dịch: Cô ấy đã đi dọc khắp đất nước để đến thăm một người họ hàng lớn tuổi đang nằm viện.)","The holiday season is a great time to gather and celebrate with every close [relative]. (=Dịch: Mùa lễ hội là khoảng thời gian tuyệt vời để sum họp và ăn mừng cùng tất cả những người họ hàng thân thiết.)","He found an old photograph of a distant [relative] who served in the war. (=Dịch: Anh ấy tìm thấy một bức ảnh cũ của một người họ hàng xa từng phục vụ trong quân ngũ thời chiến.)"],"ukAudio":"/ai_services/tts3/?q=relative&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=relative&lang=en-US&ipa=%2F%CB%88rel.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_4_323","topic":"Cultural and Historical Exchange","word":"remoteness","pos":"(n)","ipa":"/rɪˈmoʊt.nəs/","defVi":"sự xa xôi, hẻo lánh","defEn":"the state of being far away in distance or isolated from other places and people","examples":["The [remoteness] of the mountain village made it difficult to access basic healthcare. (=Dịch: Sự hẻo lánh của ngôi làng miền núi khiến việc tiếp cận dịch vụ chăm sóc sức khỏe cơ bản trở nên khó khăn.)","He enjoyed the [remoteness] of the cabin because it offered complete peace and quiet. (=Dịch: Anh ấy thích sự biệt lập của căn cabin vì nó mang lại sự yên tĩnh và thanh bình tuyệt đối.)","Due to the island's [remoteness], supplies are delivered only once a month. (=Dịch: Do sự xa xôi hẻo lánh của hòn đảo, nhu yếu phẩm chỉ được giao mỗi tháng một lần.)"],"ukAudio":"/ai_services/tts3/?q=remoteness&lang=en-GB&ipa=%2Fr%C9%AA%CB%88mo%CA%8At.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=remoteness&lang=en-US&ipa=%2Fr%C9%AA%CB%88mo%CA%8At.n%C9%99s%2F"},{"id":"lv_4_324","topic":"Cultural and Historical Exchange","word":"resemble","pos":"(v)","ipa":"/rɪˈzɛm.bəl/","defVi":"giống, tương tự","defEn":"to look like or be similar to someone or something else","examples":["She [resembles] her mother in both appearance and character. (=Dịch: Cô ấy giống mẹ cả về ngoại hình lẫn tính cách.)","The modern building does not [resemble] the traditional architecture around it. (=Dịch: Tòa nhà hiện đại không hề giống với kiến trúc truyền thống xung quanh nó.)","Some extinct reptiles closely [resemble] modern birds. (=Dịch: Một số loài bò sát đã tuyệt chủng có nét rất giống với các loài chim hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=resemble&lang=en-GB&ipa=%2Fr%C9%AA%CB%88z%C9%9Bm.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=resemble&lang=en-US&ipa=%2Fr%C9%AA%CB%88z%C9%9Bm.b%C9%99l%2F"},{"id":"lv_4_325","topic":"Cultural and Historical Exchange","word":"restore","pos":"(v)","ipa":"/rɪˈstɔr/","defVi":"phục hồi, khôi phục, trùng tu","defEn":"to return something to its earlier good condition, or to bring something back","examples":["The museum hired experts to [restore] the damaged antique painting. (=Dịch: Bảo tàng đã thuê các chuyên gia để phục chế bức tranh cổ bị hư hại.)","The government aims to [restore] public trust through open communication. (=Dịch: Chính phủ đặt mục tiêu khôi phục niềm tin của công chúng thông qua giao tiếp cởi mở.)","Engineers worked overnight to [restore] electricity to the city. (=Dịch: Các kỹ sư đã làm việc thấu đêm để khôi phục nguồn điện cho thành phố.)"],"ukAudio":"/ai_services/tts3/?q=restore&lang=en-GB&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F","usAudio":"/ai_services/tts3/?q=restore&lang=en-US&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F"},{"id":"lv_4_326","topic":"Cultural and Historical Exchange","word":"retailing","pos":"(n)","ipa":"/ˈriː.teɪ.lɪŋ/","defVi":"ngành bán lẻ, hoạt động bán lẻ","defEn":"the business of selling goods directly to the public in stores or online","examples":["The rise of e-commerce has dramatically transformed the world of [retailing]. (=Dịch: Sự trỗi dậy của thương mại điện tử đã biến đổi sâu sắc thế giới bán lẻ.)","She gained valuable experience in [retailing] after managing a clothing boutique for three years. (=Dịch: Cô ấy đã tích lũy được kinh nghiệm quý báu trong ngành bán lẻ sau khi quản lý một cửa hàng thời trang trong ba năm.)","Technological innovations in [retailing] allow customers to pay without waiting in line. (=Dịch: Những đổi mới công nghệ trong ngành bán lẻ cho phép khách hàng thanh toán mà không cần phải xếp hàng chờ đợi.)"],"ukAudio":"/ai_services/tts3/?q=retailing&lang=en-GB&ipa=%2F%CB%88ri%CB%90.te%C9%AA.l%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=retailing&lang=en-US&ipa=%2F%CB%88ri%CB%90.te%C9%AA.l%C9%AA%C5%8B%2F"},{"id":"lv_4_327","topic":"Cultural and Historical Exchange","word":"retire","pos":"(v)","ipa":"/rɪˈtaɪər/","defVi":"nghỉ hưu, về hưu","defEn":"to leave one's job and stop working, usually because of having reached a particular age","examples":["He plans to [retire] next year after forty years of teaching. (=Dịch: Ông dự định sẽ nghỉ hưu vào năm tới sau 40 năm giảng dạy.)","Many workers worry that they will not have enough savings when they [retire]. (=Dịch: Nhiều người lao động lo lắng rằng họ sẽ không có đủ tiền tiết kiệm khi về hưu.)","She chose to [retire] early to spend more time traveling with her family. (=Dịch: Bà đã chọn nghỉ hưu sớm để dành nhiều thời gian hơn đi du lịch cùng gia đình.)"],"ukAudio":"/ai_services/tts3/?q=retire&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AA%C9%99r%2F","usAudio":"/ai_services/tts3/?q=retire&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AA%C9%99r%2F"},{"id":"lv_4_328","topic":"Cultural and Historical Exchange","word":"revival","pos":"(n)","ipa":"/rɪˈvaɪ.vəl/","defVi":"sự hồi sinh, sự phục hưng","defEn":"an improvement in the condition, strength, or popularity of something","examples":["The city has experienced a cultural [revival] with the opening of several art galleries. (=Dịch: Thành phố đã trải qua sự hồi sinh văn hóa với việc mở cửa một vài phòng trưng bày nghệ thuật.)","Traditional handicrafts are enjoying a remarkable [revival] among young people. (=Dịch: Các nghề thủ công truyền thống đang đón nhận sự hồi sinh đáng kể trong giới trẻ.)","Economic reforms led to the [revival] of the local tourism industry. (=Dịch: Những cải cách kinh tế đã dẫn đến sự phục hồi của ngành du lịch địa phương.)"],"ukAudio":"/ai_services/tts3/?q=revival&lang=en-GB&ipa=%2Fr%C9%AA%CB%88va%C9%AA.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=revival&lang=en-US&ipa=%2Fr%C9%AA%CB%88va%C9%AA.v%C9%99l%2F"},{"id":"lv_4_329","topic":"Cultural and Historical Exchange","word":"revolution","pos":"(n)","ipa":"/ˌrev.əˈluː.ʃən/","defVi":"cuộc cách mạng, sự thay đổi bước ngoặt","defEn":"a forcible overthrow of a government or a major, sudden change in ideas or methods","examples":["The industrial [revolution] transformed manufacturing and everyday life. (=Dịch: Cuộc cách mạng công nghiệp đã làm thay đổi nền sản xuất và đời sống hàng ngày.)","The digital [revolution] has changed the way people communicate globally. (=Dịch: Cuộc cách mạng kỹ thuật số đã thay đổi cách mọi người giao tiếp trên toàn cầu.)","The country underwent a political [revolution] that ended decades of authoritarian rule. (=Dịch: Đất nước đã trải qua một cuộc cách mạng chính trị chấm dứt nhiều thập kỷ cai trị độc tài.)"],"ukAudio":"/ai_services/tts3/?q=revolution&lang=en-GB&ipa=%2F%CB%8Crev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=revolution&lang=en-US&ipa=%2F%CB%8Crev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99n%2F"},{"id":"lv_4_330","topic":"Cultural and Historical Exchange","word":"rewarding","pos":"(adj)","ipa":"/rɪˈwɔːr.dɪŋ/","defVi":"bổ ích, đáng giá, đem lại cảm giác thỏa mãn","defEn":"providing satisfaction, pleasure, or a feeling of worth","examples":["Teaching underprivileged children is a challenging but deeply [rewarding] job. (=Dịch: Dạy học cho trẻ em có hoàn cảnh khó khăn là một công việc đầy thử thách nhưng mang lại nhiều ý nghĩa sâu sắc.)","Volunteering at the animal shelter proved to be a [rewarding] experience for him. (=Dịch: Tham gia tình nguyện tại trạm cứu hộ động vật hóa ra lại là một trải nghiệm rất bổ ích đối với anh ấy.)","She found it [rewarding] to see her project come to life. (=Dịch: Cô cảm thấy thật xứng đáng khi được nhìn thấy dự án của mình đi vào đời thực.)"],"ukAudio":"/ai_services/tts3/?q=rewarding&lang=en-GB&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90r.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=rewarding&lang=en-US&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90r.d%C9%AA%C5%8B%2F"},{"id":"lv_4_331","topic":"Cultural and Historical Exchange","word":"rival","pos":"(n)","ipa":"/ˈraɪ.vəl/","defVi":"đối thủ, đối thủ cạnh tranh","defEn":"a person, team, or organization competing with another for the same objective","examples":["The two companies have been fierce [rival]s in the smartphone market for years. (=Dịch: Hai công ty này đã là những đối thủ khốc liệt trên thị trường điện thoại thông minh trong nhiều năm.)","He defeated his main [rival] in the final round of the tennis tournament. (=Dịch: Anh ấy đã đánh bại đối thủ chính của mình trong trận chung kết của giải đấu quần vợt.)","The new restaurant quickly became a serious [rival] to existing local diners. (=Dịch: Nhà hàng mới nhanh chóng trở thành một đối thủ đáng gờm đối với các quán ăn địa phương hiện có.)"],"ukAudio":"/ai_services/tts3/?q=rival&lang=en-GB&ipa=%2F%CB%88ra%C9%AA.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rival&lang=en-US&ipa=%2F%CB%88ra%C9%AA.v%C9%99l%2F"},{"id":"lv_4_332","topic":"Cultural and Historical Exchange","word":"rocket","pos":"(n)","ipa":"/ˈrɑː.kɪt/","defVi":"tên lửa, phi thuyền","defEn":"a vehicle or device propelled into space or through the air by the thrust of burning gases","examples":["The space agency launched a powerful [rocket] into orbit yesterday morning. (=Dịch: Cơ quan vũ trụ đã phóng một tên lửa mạnh mẽ vào quỹ đạo sáng hôm qua.)","Engineers are designing a reusable [rocket] to reduce the cost of space exploration. (=Dịch: Các kỹ sư đang thiết kế một tên lửa có thể tái sử dụng để giảm chi phí thám hiểm không gian.)","The [rocket] carried communication satellites into outer space. (=Dịch: Tên lửa đã mang các vệ tinh liên lạc vào không gian vũ trụ.)"],"ukAudio":"/ai_services/tts3/?q=rocket&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=rocket&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.k%C9%AAt%2F"},{"id":"lv_4_333","topic":"Cultural and Historical Exchange","word":"roman","pos":"(n)","ipa":"/ˈroʊ.mən/","defVi":"người La Mã (hoặc người thành Roma)","defEn":"a person born or living in ancient Rome or modern Rome","examples":["The ancient [Romans] built extensive networks of roads and aqueducts across Europe. (=Dịch: Người La Mã cổ đại đã xây dựng mạng lưới đường sá và cầu dẫn nước rộng khắp châu Âu.)","She is studying the daily life and laws of the [Romans] in her history class. (=Dịch: Cô ấy đang nghiên cứu về đời sống hàng ngày và luật pháp của người La Mã trong lớp học lịch sử.)","Many modern legal systems were heavily influenced by the early [Romans]. (=Dịch: Nhiều hệ thống pháp luật hiện đại chịu ảnh hưởng sâu sắc từ người La Mã thời kỳ đầu.)"],"ukAudio":"/ai_services/tts3/?q=roman&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=roman&lang=en-US&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F"},{"id":"lv_4_334","topic":"Cultural and Historical Exchange","word":"romantic","pos":"(adj)","ipa":"/roʊˈmæn.tɪk/","defVi":"lãng mạn, nên thơ","defEn":"relating to love, passion, or an idealized view of life","examples":["They had a [romantic] dinner at an elegant restaurant by the river. (=Dịch: Họ đã có một bữa tối lãng mạn tại một nhà hàng thanh lịch bên bờ sông.)","He often writes [romantic] poetry to express his deep feelings. (=Dịch: Anh ấy thường làm thơ lãng mạn để bày tỏ những cảm xúc sâu sắc của mình.)","She had a [romantic] notion of what living on a farm would be like. (=Dịch: Cô ấy từng có một suy nghĩ lãng mạn về cuộc sống ở một trang trại.)"],"ukAudio":"/ai_services/tts3/?q=romantic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=romantic&lang=en-US&ipa=%2Fro%CA%8A%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_4_335","topic":"Cultural and Historical Exchange","word":"rome","pos":"(n)","ipa":"/roʊm/","defVi":"thành phố Rome (thủ đô nước Ý)","defEn":"the capital city of Italy, famous for its ancient history and architecture","examples":["Millions of tourists travel to [Rome] every year to see the Colosseum. (=Dịch: Hàng triệu du khách đến Rome mỗi năm để chiêm ngưỡng đấu trường La Mã Colosseum.)","She studied art history for a semester in [Rome]. (=Dịch: Cô ấy đã học lịch sử nghệ thuật trong một học kỳ tại Rome.)","There is an old proverb saying that all roads lead to [Rome]. (=Dịch: Có một câu tục ngữ cổ nói rằng mọi con đường đều dẫn đến thành Rome.)"],"ukAudio":"/ai_services/tts3/?q=rome&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=rome&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_4_336","topic":"Cultural and Historical Exchange","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, thô ráp; dữ dội, gian nan","defEn":"not smooth, even, or gentle","examples":["The wooden table had a [rough] surface that needed sanding. (=Dịch: Chiếc bàn gỗ có bề mặt thô ráp cần phải được chà nhám.)","The ferry ride was delayed because the sea was extremely [rough]. (=Dịch: Chuyến phà bị hoãn vì biển động dữ dội.)","He wrote a [rough] draft of the essay before submitting the final version. (=Dịch: Anh ấy đã viết một bản thảo sơ bộ của bài luận trước khi nộp bản chính thức.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_4_337","topic":"Cultural and Historical Exchange","word":"row","pos":"(n)","ipa":"/roʊ/","defVi":"hàng, dãy","defEn":"a line of people, animals, or things arranged side by side","examples":["We had great seats in the front [row] of the cinema. (=Dịch: Chúng tôi đã có những chỗ ngồi tuyệt vời ở hàng ghế đầu của rạp chiếu phim.)","A [row] of blooming rose bushes stood along the fence. (=Dịch: Một hàng bụi hoa hồng đang nở rộ nằm dọc theo hàng rào.)","The teacher asked the children to stand in a straight [row]. (=Dịch: Giáo viên yêu cầu lũ trẻ đứng thành một hàng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=row&lang=en-GB&ipa=%2Fro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=row&lang=en-US&ipa=%2Fro%CA%8A%2F"},{"id":"lv_4_338","topic":"Cultural and Historical Exchange","word":"royal","pos":"(adj)","ipa":"/ˈrɔɪ.əl/","defVi":"thuộc hoàng gia, hoàng tộc","defEn":"connected with or belonging to a king or queen","examples":["The [royal] family attended the annual charity ceremony. (=Dịch: Hoàng gia đã tham dự buổi lễ từ thiện thường niên.)","Thousands of visitors come to tour the [royal] palace every year. (=Dịch: Hàng nghìn du khách đến tham quan cung điện hoàng gia mỗi năm.)","She received a [royal] invitation to the banquet in London. (=Dịch: Cô đã nhận được một lời mời từ hoàng gia đến dự buổi yến tiệc ở Luân Đôn.)"],"ukAudio":"/ai_services/tts3/?q=royal&lang=en-GB&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=royal&lang=en-US&ipa=%2F%CB%88r%C9%94%C9%AA.%C9%99l%2F"},{"id":"lv_4_339","topic":"Cultural and Historical Exchange","word":"ruler","pos":"(n)","ipa":"/ˈruː.lɚ/","defVi":"người cai trị, bậc quân vương","defEn":"a person who holds supreme power and governs a country or empire","examples":["The wise [ruler] instituted legal reforms that benefited both merchants and peasants. (=Dịch: Nhà cai trị anh minh đã ban hành các cải cách pháp lý mang lại lợi ích cho cả thương nhân lẫn nông dân.)","Many historical monuments were erected to celebrate the victories of the ancient [ruler]. (=Dịch: Nhiều di tích lịch sử đã được dựng lên để tôn vinh những chiến thắng của vị quân vương cổ đại.)","Public discontent grew after the tyrannical [ruler] imposed exorbitant new taxes. (=Dịch: Sự bất mãn trong dân chúng ngày càng gia tăng sau khi kẻ cai trị bạo ngược áp đặt những mức thuế mới cắt cổ.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F"},{"id":"lv_4_340","topic":"Cultural and Historical Exchange","word":"russia","pos":"(n)","ipa":"/ˈrʌʃ.ə/","defVi":"nước Nga","defEn":"the largest country in the world, spanning Eastern Europe and Northern Asia","examples":["Winter temperatures in [Russia] can drop well below freezing. (=Dịch: Nhiệt độ mùa đông ở Nga có thể giảm xuống dưới mức đóng băng rất nhiều.)","He is planning a journey across [Russia] on the Trans-Siberian Railway. (=Dịch: Anh ấy đang lên kế hoạch cho một chuyến hành trình xuyên nước Nga trên tuyến Đường sắt xuyên Sibir.)","Natural gas and oil are major export products of [Russia]. (=Dịch: Khí tự nhiên và dầu mỏ là các mặt hàng xuất khẩu chính của Nga.)"],"ukAudio":"/ai_services/tts3/?q=russia&lang=en-GB&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F","usAudio":"/ai_services/tts3/?q=russia&lang=en-US&ipa=%2F%CB%88r%CA%8C%CA%83.%C9%99%2F"},{"id":"lv_4_341","topic":"Cultural and Historical Exchange","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ, những người đi biển","defEn":"people who work as members of the crew of a ship or boat","examples":["The experienced [sailors] secured the ship's cargo before the severe storm hit. (=Dịch: Những thủy thủ giàu kinh nghiệm đã chằng buộc hàng hóa của con tàu cẩn thận trước khi cơn bão dữ dội ập đến.)","Ancient [sailors] relied heavily on the stars and ocean currents to navigate long voyages. (=Dịch: Các thủy thủ thời cổ đại dựa rất nhiều vào các vì sao và hải lưu để định hướng cho những hải trình dài.)","After months at sea, the weary [sailors] rejoiced at the sight of the coastline. (=Dịch: Sau nhiều tháng lênh đênh trên biển, những người thủy thủ mệt mỏi đã vui mừng khôn xiết khi nhìn thấy đường bờ biển.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_4_342","topic":"Cultural and Historical Exchange","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a loose granular substance formed from eroded rocks, commonly found on beaches and deserts","examples":["We walked barefoot on the warm [sand] along the shore. (=Dịch: Chúng tôi đi chân trần trên bãi cát ấm dọc bờ biển.)","Strong winds blew the fine [sand] into our eyes and faces. (=Dịch: Gió mạnh thổi cát mịn vào mắt và mặt chúng tôi.)","The children built a large castle out of wet [sand]. (=Dịch: Những đứa trẻ đã xây một lâu đài lớn bằng cát ướt.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_4_343","topic":"Cultural and Historical Exchange","word":"scholar","pos":"(n)","ipa":"/ˈskɑ.lɚ/","defVi":"học giả, nhà nghiên cứu","defEn":"a person who is highly educated and has studied a subject in depth","examples":["She is a respected [scholar] in the field of ancient history. (=Dịch: Bà là một học giả được kính trọng trong lĩnh vực lịch sử cổ đại.)","The university invited a visiting [scholar] to give a lecture series. (=Dịch: Trường đại học đã mời một học giả thỉnh giảng đến thuyết giảng một chuỗi bài giảng.)","Many [scholars] have debated the true meaning of the manuscript. (=Dịch: Nhiều học giả đã tranh luận về ý nghĩa thực sự của bản thảo này.)"],"ukAudio":"/ai_services/tts3/?q=scholar&lang=en-GB&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=scholar&lang=en-US&ipa=%2F%CB%88sk%C9%91.l%C9%9A%2F"},{"id":"lv_4_344","topic":"Cultural and Historical Exchange","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"thuộc về khoa học, có tính khoa học","defEn":"relating to science or using the methods of science","examples":["There is no [scientific] evidence to support this claim. (=Dịch: Không có bằng chứng khoa học nào để chứng minh cho lời khẳng định này.)","The team published their findings in a prestigious [scientific] journal. (=Dịch: Nhóm đã công bố các phát hiện của họ trên một tạp chí khoa học uy tín.)","We must adopt a strictly [scientific] approach to solve this problem. (=Dịch: Chúng ta phải áp dụng một phương pháp tiếp cận hoàn toàn khoa học để giải quyết vấn đề này.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_4_345","topic":"Cultural and Historical Exchange","word":"script","pos":"(n)","ipa":"/skrɪpt/","defVi":"kịch bản","defEn":"the written text of a play, film, or broadcast","examples":["The actors spent several weeks memorizing their lines from the [script]. (=Dịch: Các diễn viên đã dành vài tuần để học thuộc lời thoại từ kịch bản.)","The director decided to make a few changes to the original [script]. (=Dịch: Đạo diễn đã quyết định thực hiện một vài thay đổi đối với kịch bản gốc.)","She wrote an impressive [script] for her first short film. (=Dịch: Cô ấy đã viết một kịch bản ấn tượng cho bộ phim ngắn đầu tay của mình.)"],"ukAudio":"/ai_services/tts3/?q=script&lang=en-GB&ipa=%2Fskr%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=script&lang=en-US&ipa=%2Fskr%C9%AApt%2F"},{"id":"lv_4_346","topic":"Cultural and Historical Exchange","word":"seek","pos":"(v)","ipa":"/siːk/","defVi":"tìm kiếm, mưu cầu","defEn":"to attempt to find, obtain, or achieve something","examples":["Many young graduates move abroad to [seek] better career opportunities. (=Dịch: Nhiều sinh viên mới tốt nghiệp ra nước ngoài để tìm kiếm những cơ hội nghề nghiệp tốt hơn.)","Patients are advised to [seek] medical advice as soon as symptoms appear. (=Dịch: Bệnh nhân được khuyên nên tìm kiếm lời khuyên y tế ngay khi các triệu chứng xuất hiện.)","Scientists continue to [seek] sustainable alternatives to fossil fuels. (=Dịch: Các nhà khoa học tiếp tục tìm kiếm những giải pháp thay thế bền vững cho nhiên liệu hóa thạch.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsi%CB%90k%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsi%CB%90k%2F"},{"id":"lv_4_347","topic":"Cultural and Historical Exchange","word":"seminar","pos":"(n)","ipa":"/ˈsɛm.ə.nɑr/","defVi":"hội thảo, buổi chuyên đề","defEn":"a meeting or class for discussion or training on a particular topic","examples":["I attended a useful [seminar] on digital marketing strategies yesterday. (=Dịch: Hôm qua tôi đã tham dự một buổi hội thảo hữu ích về các chiến lược tiếp thị kỹ thuật số.)","Students are required to participate actively during each weekly [seminar]. (=Dịch: Sinh viên được yêu cầu tham gia tích cực trong mỗi buổi hội thảo chuyên đề hàng tuần.)","The company organized a safety [seminar] for all its new employees. (=Dịch: Công ty đã tổ chức một buổi hội thảo về an toàn cho tất cả nhân viên mới.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88s%C9%9Bm.%C9%99.n%C9%91r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88s%C9%9Bm.%C9%99.n%C9%91r%2F"},{"id":"lv_4_348","topic":"Cultural and Historical Exchange","word":"serpent","pos":"(n)","ipa":"/ˈsɝ.pənt/","defVi":"con rắn (thường dùng trong văn học hoặc thần thoại)","defEn":"a snake, especially a large or dangerous one, often used in literary or mythological contexts","examples":["In ancient myths, the [serpent] is often a symbol of wisdom and deception. (=Dịch: Trong các câu chuyện thần thoại cổ xưa, loài rắn thường là biểu tượng của sự khôn ngoan và lừa dối.)","A giant sea [serpent] was said to guard the entrance to the underwater cave. (=Dịch: Một con rắn biển khổng lồ được cho là đã canh giữ lối vào của hang động dưới nước.)","The warrior skillfully defended himself against the venomous [serpent]. (=Dịch: Người chiến binh đã khéo léo tự vệ trước con mãng xà có độc.)"],"ukAudio":"/ai_services/tts3/?q=serpent&lang=en-GB&ipa=%2F%CB%88s%C9%9D.p%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=serpent&lang=en-US&ipa=%2F%CB%88s%C9%9D.p%C9%99nt%2F"},{"id":"lv_4_349","topic":"Cultural and Historical Exchange","word":"setback","pos":"(n)","ipa":"/ˈset.bæk/","defVi":"sự trở ngại, bước lùi, khó khăn bất ngờ","defEn":"a problem or difficulty that delays progress or stops a plan from succeeding","examples":["The unexpected supply chain disruption was a major [setback] for the construction project. (=Dịch: Sự gián đoạn chuỗi cung ứng bất ngờ là một trở ngại lớn đối với dự án xây dựng.)","Despite an initial [setback], the research team managed to finish the report on time. (=Dịch: Bất chấp trở ngại ban đầu, nhóm nghiên cứu đã xoay xở hoàn thành báo cáo đúng hạn.)","A shoulder injury proved to be a serious [setback] to her athletic career. (=Dịch: Một chấn thương vai đã trở thành bước thụt lùi nghiêm trọng đối với sự nghiệp thể thao của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=setback&lang=en-GB&ipa=%2F%CB%88set.b%C3%A6k%2F","usAudio":"/ai_services/tts3/?q=setback&lang=en-US&ipa=%2F%CB%88set.b%C3%A6k%2F"},{"id":"lv_4_350","topic":"Cultural and Historical Exchange","word":"settlement","pos":"(n)","ipa":"/ˈset̬.əl.mənt/","defVi":"khu định cư, điểm định cư","defEn":"a place where people come to live and build homes","examples":["The small [settlement] eventually grew into a thriving city. (=Dịch: Khu định cư nhỏ bé cuối cùng đã phát triển thành một thành phố phồn vinh.)","Explorers discovered the ruins of an ancient [settlement] near the river. (=Dịch: Các nhà thám hiểm đã phát hiện ra tàn tích của một khu định cư cổ xưa gần con sông.)","The government provided basic infrastructure for the new [settlement]. (=Dịch: Chính phủ đã cung cấp cơ sở hạ tầng cơ bản cho khu định cư mới.)"],"ukAudio":"/ai_services/tts3/?q=settlement&lang=en-GB&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=settlement&lang=en-US&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F"},{"id":"lv_4_351","topic":"Cultural and Historical Exchange","word":"settler","pos":"(n)","ipa":"/ˈsɛt.lɚ/","defVi":"người khai hoang, người định cư","defEn":"a person who moves with a group to live in a new country or area","examples":["Early [settlers] faced harsh winters and food shortages in the new territory. (=Dịch: Những người đi khai hoang thời kỳ đầu đã phải đối mặt với mùa đông khắc nghiệt và tình trạng thiếu thốn lương thực ở vùng đất mới.)","The museum showcases tools used by European [settlers] in the 18th century. (=Dịch: Bảo tàng trưng bày các công cụ được những người định cư châu Âu sử dụng vào thế kỷ 18.)","Each [settler] was granted a piece of land to farm and build a home. (=Dịch: Mỗi người định cư được cấp một mảnh đất để canh tác và xây dựng nhà cửa.)"],"ukAudio":"/ai_services/tts3/?q=settler&lang=en-GB&ipa=%2F%CB%88s%C9%9Bt.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=settler&lang=en-US&ipa=%2F%CB%88s%C9%9Bt.l%C9%9A%2F"},{"id":"lv_4_352","topic":"Cultural and Historical Exchange","word":"seventeenth","pos":"(adj)","ipa":"/ˌsev.ənˈtiːnθ/","defVi":"thứ mười bảy","defEn":"coming next after the sixteenth in order or time","examples":["The museum exhibits paintings from the [seventeenth] century. (=Dịch: Bảo tàng trưng bày các bức tranh từ thế kỷ thứ mười bảy.)","Today is her [seventeenth] birthday, and she is having a party. (=Dịch: Hôm nay là sinh nhật thứ mười bảy của cô ấy, và cô ấy đang tổ chức một bữa tiệc.)","He finished in [seventeenth] place out of fifty runners. (=Dịch: Anh ấy về đích ở vị trí thứ mười bảy trong tổng số năm mươi vận động viên chạy.)"],"ukAudio":"/ai_services/tts3/?q=seventeenth&lang=en-GB&ipa=%2F%CB%8Csev.%C9%99n%CB%88ti%CB%90n%CE%B8%2F","usAudio":"/ai_services/tts3/?q=seventeenth&lang=en-US&ipa=%2F%CB%8Csev.%C9%99n%CB%88ti%CB%90n%CE%B8%2F"},{"id":"lv_4_353","topic":"Cultural and Historical Exchange","word":"sew","pos":"(v)","ipa":"/soʊ/","defVi":"may, khâu","defEn":"to join or attach things together using a needle and thread","examples":["My grandmother taught me how to [sew] buttons onto shirts. (=Dịch: Bà tôi đã dạy tôi cách khâu cúc vào áo sơ mi.)","She plans to [sew] her own dress for the graduation ceremony. (=Dịch: Cô ấy dự định tự may váy cho buổi lễ tốt nghiệp của mình.)","He used thick thread to [sew] the torn leather strap of his backpack. (=Dịch: Anh ấy đã dùng chỉ dày để khâu lại dây đeo bằng da bị rách của chiếc ba lô.)"],"ukAudio":"/ai_services/tts3/?q=sew&lang=en-GB&ipa=%2Fso%CA%8A%2F","usAudio":"/ai_services/tts3/?q=sew&lang=en-US&ipa=%2Fso%CA%8A%2F"},{"id":"lv_4_354","topic":"Cultural and Historical Exchange","word":"sex","pos":"(n)","ipa":"/sɛks/","defVi":"giới tính (sinh học)","defEn":"the state of being either male or female, typically based on biological characteristics","examples":["Please state your age and [sex] on the application form. (=Dịch: Vui lòng ghi rõ độ tuổi và [giới tính] của bạn trên mẫu đơn đăng ký.)","The study analyzes how educational outcomes vary by [sex]. (=Dịch: Nghiên cứu phân tích kết quả giáo dục khác nhau như thế nào theo [giới tính].)","Discrimination based on [sex] is strictly prohibited in the workplace. (=Dịch: Phân biệt đối xử dựa trên [giới tính] bị nghiêm cấm tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=sex&lang=en-GB&ipa=%2Fs%C9%9Bks%2F","usAudio":"/ai_services/tts3/?q=sex&lang=en-US&ipa=%2Fs%C9%9Bks%2F"},{"id":"lv_4_355","topic":"Cultural and Historical Exchange","word":"sheepmarket","pos":"(n)","ipa":"/ˈʃipˌmɑr.kɪt/","defVi":"chợ cừu","defEn":"a marketplace where sheep are bought and sold","examples":["Farmers gathered at the local [sheepmarket] early in the morning to trade livestock. (=Dịch: Những người nông dân đã tập trung tại chợ cừu địa phương từ sáng sớm để buôn bán gia súc.)","The town's old [sheepmarket] has been transformed into a bustling tourist square. (=Dịch: Chợ cừu cũ của thị trấn đã được chuyển đổi thành một quảng trường du lịch nhộn nhịp.)","Prices at the annual [sheepmarket] fluctuated due to changes in wool demand. (=Dịch: Giá cả tại phiên chợ cừu thường niên đã biến động do những thay đổi về nhu cầu đối với len.)"],"ukAudio":"/ai_services/tts3/?q=sheepmarket&lang=en-GB&ipa=%2F%CB%88%CA%83ip%CB%8Cm%C9%91r.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=sheepmarket&lang=en-US&ipa=%2F%CB%88%CA%83ip%CB%8Cm%C9%91r.k%C9%AAt%2F"},{"id":"lv_4_356","topic":"Cultural and Historical Exchange","word":"shell","pos":"(n)","ipa":"/ʃel/","defVi":"vỏ (vỏ ốc, vỏ trứng, vỏ sò...)","defEn":"the hard outer covering of an animal, egg, or nut","examples":["Children love collecting every colorful [shell] they find on the beach. (=Dịch: Trẻ em rất thích nhặt từng vỏ sò nhiều màu sắc mà chúng tìm thấy trên bãi biển.)","A turtle can pull its head and legs inside its protective [shell]. (=Dịch: Rùa có thể rụt đầu và chân vào bên trong chiếc mai bảo vệ của nó.)","Crack the egg [shell] gently against the side of the bowl. (=Dịch: Hãy đập nhẹ vỏ trứng vào thành bát.)"],"ukAudio":"/ai_services/tts3/?q=shell&lang=en-GB&ipa=%2F%CA%83el%2F","usAudio":"/ai_services/tts3/?q=shell&lang=en-US&ipa=%2F%CA%83el%2F"},{"id":"lv_4_357","topic":"Cultural and Historical Exchange","word":"shepherd","pos":"(n)","ipa":"/ˈʃɛp.ɚd/","defVi":"người chăn cừu","defEn":"a person whose job is to take care of sheep","examples":["The [shepherd] used trained dogs to guide the flock across the hills. (=Dịch: Người chăn cừu đã sử dụng những chú chó được huấn luyện để dẫn đàn cừu băng qua các ngọn đồi.)","During the storm, the lonely [shepherd] sheltered his animals inside a barn. (=Dịch: Trong suốt cơn bão, người chăn cừu cô độc đã che chở cho đàn gia súc của mình bên trong một chuồng trại.)","Life as a traditional [shepherd] requires endurance and patience in remote landscapes. (=Dịch: Cuộc sống của một người chăn cừu truyền thống đòi hỏi sự bền bỉ và lòng kiên nhẫn giữa những vùng đất xa xôi hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=shepherd&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%9Bp.%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=shepherd&lang=en-US&ipa=%2F%CB%88%CA%83%C9%9Bp.%C9%9Ad%2F"},{"id":"lv_4_358","topic":"Cultural and Historical Exchange","word":"shortage","pos":"(n)","ipa":"/ˈʃɔːr.t̬ɪdʒ/","defVi":"sự thiếu hụt, tình trạng khan hiếm","defEn":"a state in which there is not enough of something that is needed","examples":["The prolonged drought caused a severe [shortage] of drinking water across the region. (=Dịch: Đợt hạn hán kéo dài đã gây ra tình trạng thiếu hụt nước uống trầm trọng trên toàn khu vực.)","Hospitals are currently facing an acute [shortage] of qualified nursing staff. (=Dịch: Các bệnh viện hiện đang đối mặt với tình trạng thiếu hụt cấp tính đội ngũ điều dưỡng viên có trình độ chuyên môn.)","Disruptions in global supply chains have led to a worldwide [shortage] of electronic components. (=Dịch: Sự gián đoạn trong chuỗi cung ứng toàn cầu đã dẫn đến tình trạng thiếu hụt linh kiện điện tử trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=shortage&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%94%CB%90r.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=shortage&lang=en-US&ipa=%2F%CB%88%CA%83%C9%94%CB%90r.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_4_359","topic":"Cultural and Historical Exchange","word":"sightseeing","pos":"(n)","ipa":"/ˈsaɪt.siː.ɪŋ/","defVi":"sự tham quan, ngắm cảnh","defEn":"the activity of visiting interesting and famous places as a tourist","examples":["We did a lot of [sightseeing] during our trip to Paris. (=Dịch: Chúng tôi đã đi ngắm cảnh rất nhiều trong chuyến du lịch tới Paris.)","They booked a guided bus tour for a full day of [sightseeing]. (=Dịch: Họ đã đặt một chuyến tham quan bằng xe buýt có hướng dẫn viên để ngắm cảnh trọn vẹn cả ngày.)","Local markets are great spots to combine shopping with [sightseeing]. (=Dịch: Các khu chợ địa phương là những địa điểm tuyệt vời để kết hợp mua sắm với ngắm cảnh.)"],"ukAudio":"/ai_services/tts3/?q=sightseeing&lang=en-GB&ipa=%2F%CB%88sa%C9%AAt.si%CB%90.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sightseeing&lang=en-US&ipa=%2F%CB%88sa%C9%AAt.si%CB%90.%C9%AA%C5%8B%2F"},{"id":"lv_4_360","topic":"Cultural and Historical Exchange","word":"sixteenth","pos":"(adj)","ipa":"/ˌsɪksˈtinθ/","defVi":"thứ mười sáu","defEn":"coming next after the fifteenth in order or position","examples":["She celebrated her [sixteenth] birthday with a small gathering of close friends. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ mười sáu cùng một buổi tụ họp nhỏ với những người bạn thân.)","This historic church was originally built in the [sixteenth] century. (=Dịch: Nhà thờ lịch sử này ban đầu được xây dựng vào thế kỷ thứ mười sáu.)","He finished in [sixteenth] place in the international marathon competition. (=Dịch: Anh ấy về đích ở vị trí thứ mười sáu trong cuộc thi marathon quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=sixteenth&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAks%CB%88tin%CE%B8%2F","usAudio":"/ai_services/tts3/?q=sixteenth&lang=en-US&ipa=%2F%CB%8Cs%C9%AAks%CB%88tin%CE%B8%2F"},{"id":"lv_4_361","topic":"Cultural and Historical Exchange","word":"skating","pos":"(n)","ipa":"/ˈskeɪ.tɪŋ/","defVi":"môn trượt băng, trượt patin","defEn":"the sport or activity of moving on ice or hard surfaces using special footwear with blades or wheels","examples":["Ice [skating] is a popular winter pastime in cold countries. (=Dịch: Trượt băng là một trò tiêu khiển mùa đông phổ biến ở các nước xứ lạnh.)","She took up roller [skating] to improve her balance and fitness. (=Dịch: Cô ấy bắt đầu chơi trượt patin để cải thiện khả năng giữ thăng bằng và thể lực.)","The frozen lake provided a natural rink for afternoon [skating]. (=Dịch: Mặt hồ đóng băng đã trở thành một sân trượt tự nhiên cho hoạt động trượt băng vào buổi chiều.)"],"ukAudio":"/ai_services/tts3/?q=skating&lang=en-GB&ipa=%2F%CB%88ske%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=skating&lang=en-US&ipa=%2F%CB%88ske%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_4_362","topic":"Cultural and Historical Exchange","word":"skilled","pos":"(adj)","ipa":"/skɪld/","defVi":"lành nghề, có kỹ năng chuyên môn","defEn":"having the knowledge, training, or ability to do something well","examples":["The factory is looking to recruit more [skilled] workers for the production line. (=Dịch: Nhà máy đang tìm cách tuyển dụng thêm nhiều công nhân lành nghề cho dây chuyền sản xuất.)","A [skilled] negotiator can resolve disputes peacefully and efficiently. (=Dịch: Một nhà đàm phán lành nghề có thể giải quyết các tranh chấp một cách hòa bình và hiệu quả.)","Creating handmade pottery requires a very [skilled] touch. (=Dịch: Làm đồ gốm thủ công đòi hỏi một bàn tay rất khéo léo.)"],"ukAudio":"/ai_services/tts3/?q=skilled&lang=en-GB&ipa=%2Fsk%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=skilled&lang=en-US&ipa=%2Fsk%C9%AAld%2F"},{"id":"lv_4_363","topic":"Cultural and Historical Exchange","word":"soda","pos":"(n)","ipa":"/ˈsoʊ.də/","defVi":"nước ngọt có ga","defEn":"a sweet carbonated soft drink","examples":["Drinking too much sugary [soda] can lead to dental problems. (=Dịch: Uống quá nhiều nước ngọt có ga chứa đường có thể dẫn đến các vấn đề về răng miệng.)","He ordered a slice of pizza and a can of [soda]. (=Dịch: Anh ấy đã gọi một miếng bánh pizza và một lon nước ngọt có ga.)","The restaurant replaced regular [soda] with fresh juice options. (=Dịch: Nhà hàng đã thay thế nước ngọt có ga thông thường bằng các lựa chọn nước ép tươi.)"],"ukAudio":"/ai_services/tts3/?q=soda&lang=en-GB&ipa=%2F%CB%88so%CA%8A.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=soda&lang=en-US&ipa=%2F%CB%88so%CA%8A.d%C9%99%2F"},{"id":"lv_4_364","topic":"Cultural and Historical Exchange","word":"somewhat","pos":"(adv)","ipa":"/ˈsʌm.wʌt/","defVi":"hơi, có phần, một chút","defEn":"to some degree; a little","examples":["The test results were [somewhat] surprising to the researchers. (=Dịch: Kết quả kiểm tra có phần bất ngờ đối với các nhà nghiên cứu.)","Her condition has improved [somewhat] since yesterday. (=Dịch: Tình trạng của cô ấy đã cải thiện đôi chút kể từ hôm qua.)","I felt [somewhat] tired after walking around the museum all morning. (=Dịch: Tôi cảm thấy hơi mệt sau khi đi bộ quanh bảo tàng suốt cả buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=somewhat&lang=en-GB&ipa=%2F%CB%88s%CA%8Cm.w%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=somewhat&lang=en-US&ipa=%2F%CB%88s%CA%8Cm.w%CA%8Ct%2F"},{"id":"lv_4_365","topic":"Cultural and Historical Exchange","word":"southern","pos":"(adj)","ipa":"/ˈsʌð.ərn/","defVi":"thuộc về phương nam, ở phía nam","defEn":"located in or connected with the south","examples":["The [southern] part of the country enjoys a much warmer climate. (=Dịch: Khu vực phía nam của đất nước có khí hậu ấm áp hơn nhiều.)","Many migratory birds travel to the [southern] hemisphere during winter. (=Dịch: Nhiều loài chim di cư bay đến bán cầu nam trong suốt mùa đông.)","They spent their summer vacation exploring charming [southern] coastal towns. (=Dịch: Họ đã dành kỳ nghỉ hè để khám phá các thị trấn ven biển phía nam đầy quyến rũ.)"],"ukAudio":"/ai_services/tts3/?q=southern&lang=en-GB&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%99rn%2F","usAudio":"/ai_services/tts3/?q=southern&lang=en-US&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%99rn%2F"},{"id":"lv_4_366","topic":"Cultural and Historical Exchange","word":"spectacular","pos":"(adj)","ipa":"/spekˈtæk.jə.lɚ/","defVi":"ngoạn mục, hùng vĩ, đẹp mắt","defEn":"very impressive, exciting, or visually striking","examples":["The resort offers a [spectacular] view of the snow-capped mountains. (=Dịch: Khu nghỉ dưỡng mang lại một khung cảnh ngoạn mục của những ngọn núi phủ đầy tuyết.)","The opening ceremony ended with a [spectacular] fireworks display. (=Dịch: Lễ khai mạc đã kết thúc bằng một màn trình diễn pháo hoa ngoạn mục.)","The team made a [spectacular] comeback in the final minutes of the match. (=Dịch: Đội bóng đã có một cuộc lội ngược dòng ngoạn mục trong những phút cuối cùng của trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectacular&lang=en-GB&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=spectacular&lang=en-US&ipa=%2Fspek%CB%88t%C3%A6k.j%C9%99.l%C9%9A%2F"},{"id":"lv_4_367","topic":"Cultural and Historical Exchange","word":"spin","pos":"(v)","ipa":"/spɪn/","defVi":"xoay tròn, quay, kéo sợi","defEn":"to turn round and round quickly, or to make thread by twisting fibers","examples":["The ice skater began to [spin] rapidly on one foot during her routine. (=Dịch: Vận động viên trượt băng bắt đầu xoay tròn nhanh chóng trên một chân trong bài biểu diễn của mình.)","In ancient times, people used simple wheels to [spin] wool into yarn. (=Dịch: Thời cổ đại, con người dùng những bánh xe đơn giản để kéo len thành sợi.)","The washing machine will [spin] the clothes dry before the cycle ends. (=Dịch: Máy giặt sẽ vắt khô quần áo trước khi chu trình kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=spin&lang=en-GB&ipa=%2Fsp%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spin&lang=en-US&ipa=%2Fsp%C9%AAn%2F"},{"id":"lv_4_368","topic":"Cultural and Historical Exchange","word":"spiral","pos":"(n)","ipa":"/ˈspaɪ.rəl/","defVi":"hình xoắn ốc, đường xoắn ốc","defEn":"a winding shape or curve that curves around a central point while moving further away or closer","examples":["The architect designed a stunning [spiral] staircase in the center of the lobby. (=Dịch: Kiến trúc sư đã thiết kế một cầu thang xoắn ốc tuyệt đẹp ở vị trí trung tâm sảnh chờ.)","A snail's shell features a distinctive geometric [spiral] pattern. (=Dịch: Vỏ của ốc sên có họa tiết hình xoắn ốc hình học rất đặc trưng.)","The rising smoke formed a slow [spiral] in the quiet air of the room. (=Dịch: Làn khói bốc lên tạo thành một vòng xoắn ốc chậm rãi trong bầu không khí tĩnh lặng của căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=spiral&lang=en-GB&ipa=%2F%CB%88spa%C9%AA.r%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spiral&lang=en-US&ipa=%2F%CB%88spa%C9%AA.r%C9%99l%2F"},{"id":"lv_4_369","topic":"Cultural and Historical Exchange","word":"spiritual","pos":"(adj)","ipa":"/ˈspɪr.ɪ.tʃu.əl/","defVi":"thuộc về tâm linh, tinh thần","defEn":"relating to deep feelings and beliefs, especially religious or inner personal values","examples":["Yoga helps people improve both their physical and [spiritual] well-being. (=Dịch: Yoga giúp con người cải thiện cả sức khỏe thể chất lẫn tinh thần.)","The ancient temple is regarded as an important [spiritual] center for the community. (=Dịch: Ngôi đền cổ kính được coi là một trung tâm tâm linh quan trọng đối với cộng đồng.)","Music often provides a deep [spiritual] connection for many listeners. (=Dịch: Âm nhạc thường mang lại sự kết nối tâm linh sâu sắc cho nhiều người nghe.)"],"ukAudio":"/ai_services/tts3/?q=spiritual&lang=en-GB&ipa=%2F%CB%88sp%C9%AAr.%C9%AA.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spiritual&lang=en-US&ipa=%2F%CB%88sp%C9%AAr.%C9%AA.t%CA%83u.%C9%99l%2F"},{"id":"lv_4_370","topic":"Cultural and Historical Exchange","word":"spy","pos":"(n)","ipa":"/spaɪ/","defVi":"điệp viên, gián điệp","defEn":"a person employed to obtain secret information about an enemy or competitor","examples":["The government arrested a foreign [spy] who was collecting military secrets. (=Dịch: Chính phủ đã bắt giữ một điệp viên nước ngoài đang thu thập các bí mật quân sự.)","He worked as a double [spy] during the war, passing false information to both sides. (=Dịch: Ông từng làm gián điệp hai mang trong thời chiến, tuồn thông tin giả cho cả hai phía.)","The novelist wrote a gripping story about a secret [spy] mission in Berlin. (=Dịch: Tiểu thuyết gia đã viết một câu chuyện hấp dẫn về một nhiệm vụ gián điệp bí mật tại Berlin.)"],"ukAudio":"/ai_services/tts3/?q=spy&lang=en-GB&ipa=%2Fspa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=spy&lang=en-US&ipa=%2Fspa%C9%AA%2F"},{"id":"lv_4_371","topic":"Cultural and Historical Exchange","word":"stable","pos":"(n)","ipa":"/ˈsteɪ.bəl/","defVi":"chuồng ngựa","defEn":"a building in which horses or other domestic animals are kept and fed","examples":["The farmer led the tired horse back into the [stable] after a long day. (=Dịch: Người nông dân dắt con ngựa mệt mỏi trở lại chuồng ngựa sau một ngày dài.)","They cleaned out the [stable] and put down fresh straw for the animals. (=Dịch: Họ dọn sạch chuồng ngựa và rải rơm mới cho đàn vật nuôi.)","The riding school has a large [stable] that can house over twenty horses. (=Dịch: Trường dạy cưỡi ngựa có một chuồng ngựa lớn có thể chứa hơn hai mươi con ngựa.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_4_372","topic":"Cultural and Historical Exchange","word":"stadium","pos":"(n)","ipa":"/ˈsteɪ.di.əm/","defVi":"sân vận động","defEn":"a large closed area of land with rows of seats around it, used for sports events and concerts","examples":["Thousands of excited fans gathered inside the [stadium] for the match. (=Dịch: Hàng ngàn người hâm mộ hào hứng đã tập trung bên trong sân vận động để theo dõi trận đấu.)","The city invested millions of dollars to build a modern [stadium]. (=Dịch: Thành phố đã đầu tư hàng triệu đô la để xây dựng một sân vận động hiện đại.)","Famous musicians often choose a large [stadium] for their world tours. (=Dịch: Các nghệ sĩ âm nhạc nổi tiếng thường chọn sân vận động lớn cho các chuyến lưu diễn vòng quanh thế giới của họ.)"],"ukAudio":"/ai_services/tts3/?q=stadium&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stadium&lang=en-US&ipa=%2F%CB%88ste%C9%AA.di.%C9%99m%2F"},{"id":"lv_4_373","topic":"Cultural and Historical Exchange","word":"statue","pos":"(n)","ipa":"/ˈstæ.tʃuː/","defVi":"bức tượng, pho tượng","defEn":"a three-dimensional figure of a person, animal, or object made of stone, metal, or other materials","examples":["A large bronze [statue] was erected in the city center to honor the national hero. (=Dịch: Một bức tượng đồng lớn đã được dựng lên ở trung tâm thành phố để vinh danh vị anh hùng dân tộc.)","Tourists gathered in the square to take pictures of the historic marble [statue]. (=Dịch: Khách du lịch tụ tập tại quảng trường để chụp ảnh bức tượng đá cẩm thạch lịch sử.)","The museum displays a remarkable ancient [statue] that dates back over two thousand years. (=Dịch: Bảo tàng trưng bày một bức tượng cổ đáng chú ý có niên đại hơn hai nghìn năm trước.)"],"ukAudio":"/ai_services/tts3/?q=statue&lang=en-GB&ipa=%2F%CB%88st%C3%A6.t%CA%83u%CB%90%2F","usAudio":"/ai_services/tts3/?q=statue&lang=en-US&ipa=%2F%CB%88st%C3%A6.t%CA%83u%CB%90%2F"},{"id":"lv_4_374","topic":"Cultural and Historical Exchange","word":"steel","pos":"(n)","ipa":"/stil/","defVi":"thép","defEn":"a strong, hard metal made of iron and carbon","examples":["The bridge is supported by massive [steel] beams. (=Dịch: Cây cầu được nâng đỡ bởi những thanh dầm thép khổng lồ.)","Demand for [steel] increased rapidly during the construction boom. (=Dịch: Nhu cầu về thép đã tăng nhanh chóng trong thời kỳ bùng nổ xây dựng.)","Modern skyscrapers are constructed using reinforced [steel]. (=Dịch: Các tòa nhà chọc trời hiện đại được xây dựng bằng thép gia cường.)"],"ukAudio":"/ai_services/tts3/?q=steel&lang=en-GB&ipa=%2Fstil%2F","usAudio":"/ai_services/tts3/?q=steel&lang=en-US&ipa=%2Fstil%2F"},{"id":"lv_4_375","topic":"Cultural and Historical Exchange","word":"stoic","pos":"(n)","ipa":"/ˈstoʊ.ɪk/","defVi":"người kiên cường, người khắc kỷ","defEn":"a person who can endure pain or hardship without showing their feelings or complaining","examples":["Even during the medical crisis, he remained a true [stoic] and never complained. (=Dịch: Ngay cả trong cơn khủng hoảng sức khỏe, anh ấy vẫn là một người khắc kỷ thực thụ và không bao giờ than phiền.)","She acted like a [stoic] despite hearing the terrible news about her business. (=Dịch: Cô ấy vẫn giữ vẻ bình thản dù nghe tin khủng khiếp về công việc kinh doanh của mình.)","As a devoted [stoic], the soldier bore his physical injuries in silence. (=Dịch: Là một người kiên cường theo chủ nghĩa khắc kỷ, người lính đã âm thầm chịu đựng những vết thương thể xác.)"],"ukAudio":"/ai_services/tts3/?q=stoic&lang=en-GB&ipa=%2F%CB%88sto%CA%8A.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=stoic&lang=en-US&ipa=%2F%CB%88sto%CA%8A.%C9%AAk%2F"},{"id":"lv_4_376","topic":"Cultural and Historical Exchange","word":"stoicism","pos":"(n)","ipa":"/ˈstoʊ.ə.sɪ.zəm/","defVi":"chủ nghĩa khắc kỷ, sự kiên nhẫn chịu đựng","defEn":"the endurance of pain or hardship without a display of feelings and without complaint","examples":["Ancient Greek [stoicism] teaches people to focus only on what they can control. (=Dịch: Chủ nghĩa khắc kỷ Hy Lạp cổ đại dạy con người chỉ nên tập trung vào những gì họ có thể kiểm soát.)","She faced every family misfortune with remarkable calm and [stoicism]. (=Dịch: Cô ấy đối mặt với mọi bất hạnh của gia đình với sự bình tĩnh và lòng kiên định đáng kinh ngạc.)","Many modern leaders study [stoicism] to manage stress in high-pressure situations. (=Dịch: Nhiều nhà lãnh đạo hiện đại học tập chủ nghĩa khắc kỷ để quản lý sự căng thẳng trong các tình huống chịu nhiều áp lực.)"],"ukAudio":"/ai_services/tts3/?q=stoicism&lang=en-GB&ipa=%2F%CB%88sto%CA%8A.%C9%99.s%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=stoicism&lang=en-US&ipa=%2F%CB%88sto%CA%8A.%C9%99.s%C9%AA.z%C9%99m%2F"},{"id":"lv_4_377","topic":"Cultural and Historical Exchange","word":"stream","pos":"(n)","ipa":"/strim/","defVi":"con suối, dòng suối","defEn":"a small, narrow river of continuous flowing water","examples":["A clear [stream] flows through the middle of the village. (=Dịch: Một con suối trong vắt chảy qua giữa ngôi làng.)","We sat by the [stream] and listened to the gentle sound of water. (=Dịch: Chúng tôi ngồi bên dòng suối và lắng nghe tiếng nước chảy êm đềm.)","The mountain [stream] provides fresh drinking water for local residents. (=Dịch: Con suối trên núi cung cấp nước uống sạch cho người dân địa phương.)"],"ukAudio":"/ai_services/tts3/?q=stream&lang=en-GB&ipa=%2Fstrim%2F","usAudio":"/ai_services/tts3/?q=stream&lang=en-US&ipa=%2Fstrim%2F"},{"id":"lv_4_378","topic":"Cultural and Historical Exchange","word":"strength","pos":"(n)","ipa":"/strɛŋkθ/","defVi":"sức mạnh, thể lực","defEn":"the physical power and energy that makes someone strong","examples":["Weight training is an effective method to build overall physical [strength]. (=Dịch: Tập tạ là một phương pháp hiệu quả để xây dựng sức mạnh thể chất toàn diện.)","She barely had the [strength] to get out of bed after running the marathon. (=Dịch: Cô ấy gần như không còn sức lực để rời khỏi giường sau khi chạy marathon.)","The team drew [strength] from the loud support of their home crowd. (=Dịch: Đội tuyển đã được tiếp thêm sức mạnh từ sự cổ vũ cuồng nhiệt của khán giả nhà.)"],"ukAudio":"/ai_services/tts3/?q=strength&lang=en-GB&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F","usAudio":"/ai_services/tts3/?q=strength&lang=en-US&ipa=%2Fstr%C9%9B%C5%8Bk%CE%B8%2F"},{"id":"lv_4_379","topic":"Cultural and Historical Exchange","word":"substance","pos":"(n)","ipa":"/ˈsʌb.stəns/","defVi":"chất, vật chất","defEn":"a particular kind of matter with uniform properties","examples":["The laboratory test revealed a dangerous chemical [substance] in the water. (=Dịch: Xét nghiệm trong phòng thí nghiệm đã phát hiện ra một chất hóa học nguy hiểm trong nước.)","Rubber is a flexible [substance] used in making tires. (=Dịch: Cao su là một chất có tính đàn hồi được sử dụng để sản xuất lốp xe.)","Scientists discovered an unknown [substance] on the surface of the meteorite. (=Dịch: Các nhà khoa học đã phát hiện ra một chất chưa xác định trên bề mặt của thiên thạch.)"],"ukAudio":"/ai_services/tts3/?q=substance&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=substance&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F"},{"id":"lv_4_380","topic":"Cultural and Historical Exchange","word":"sufficient","pos":"(adj)","ipa":"/səˈfɪʃ.ənt/","defVi":"đủ, đầy đủ","defEn":"enough for a particular purpose; as much as is needed","examples":["We need [sufficient] evidence before we can make a final decision. (=Dịch: Chúng tôi cần đầy đủ bằng chứng trước khi có thể đưa ra quyết định cuối cùng.)","Make sure you get [sufficient] sleep before the exam. (=Dịch: Hãy đảm bảo rằng bạn ngủ đủ giấc trước kỳ thi.)","The salary is [sufficient] to cover all her living expenses. (=Dịch: Mức lương này đủ để chi trả mọi chi phí sinh hoạt của cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=sufficient&lang=en-GB&ipa=%2Fs%C9%99%CB%88f%C9%AA%CA%83.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=sufficient&lang=en-US&ipa=%2Fs%C9%99%CB%88f%C9%AA%CA%83.%C9%99nt%2F"},{"id":"lv_4_381","topic":"Cultural and Historical Exchange","word":"superior","pos":"(adj)","ipa":"/suːˈpɪr.i.ɚ/","defVi":"vượt trội, cao cấp hơn; cấp trên","defEn":"better in quality than someone or something else; higher in rank","examples":["This model is [superior] to the older version in terms of battery life. (=Dịch: Mẫu này vượt trội hơn phiên bản cũ về thời lượng pin.)","He always behaves as if he has a [superior] knowledge of the subject. (=Dịch: Anh ấy luôn cư xử như thể mình có hiểu biết siêu việt về chủ đề này.)","She reported the incident directly to her [superior] officer. (=Dịch: Cô ấy đã báo cáo sự việc trực tiếp cho cấp trên của mình.)"],"ukAudio":"/ai_services/tts3/?q=superior&lang=en-GB&ipa=%2Fsu%CB%90%CB%88p%C9%AAr.i.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=superior&lang=en-US&ipa=%2Fsu%CB%90%CB%88p%C9%AAr.i.%C9%9A%2F"},{"id":"lv_4_382","topic":"Cultural and Historical Exchange","word":"survive","pos":"(v)","ipa":"/sərˈvaɪv/","defVi":"sống sót, tồn tại qua khó khăn","defEn":"to continue to live or exist, especially through hardship or danger","examples":["Few plants can [survive] in the extreme cold of the Arctic desert. (=Dịch: Rất ít loài thực vật có thể sống sót trong cái lạnh khắc nghiệt của hoang mạc Bắc Cực.)","Miraculously, all passengers managed to [survive] the severe train crash. (=Dịch: Thật kỳ diệu, tất cả các hành khách đều sống sót sau vụ tai nạn tàu hỏa nghiêm trọng.)","Small businesses struggle to [survive] during unexpected economic downturns. (=Dịch: Các doanh nghiệp nhỏ phải vật lộn để tồn tại trong những giai đoạn suy thoái kinh tế bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=survive&lang=en-GB&ipa=%2Fs%C9%99r%CB%88va%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=survive&lang=en-US&ipa=%2Fs%C9%99r%CB%88va%C9%AAv%2F"},{"id":"lv_4_383","topic":"Cultural and Historical Exchange","word":"surviving","pos":"(adj)","ipa":"/sərˈvaɪ.vɪŋ/","defVi":"sống sót, còn tồn tại","defEn":"continuing to live or exist after a dangerous event or long period","examples":["The [surviving] passengers were quickly taken to the nearest hospital. (=Dịch: Những hành khách sống sót đã nhanh chóng được đưa đến bệnh viện gần nhất.)","It is one of the few [surviving] examples of medieval architecture in the city. (=Dịch: Đây là một trong số ít những công trình kiến trúc thời trung cổ còn sót lại trong thành phố.)","The museum displays artifacts from the only [surviving] manuscript of the epic poem. (=Dịch: Bảo tàng trưng bày các hiện vật từ bản thảo duy nhất còn sót lại của thiên sử thi.)"],"ukAudio":"/ai_services/tts3/?q=surviving&lang=en-GB&ipa=%2Fs%C9%99r%CB%88va%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=surviving&lang=en-US&ipa=%2Fs%C9%99r%CB%88va%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_4_384","topic":"Cultural and Historical Exchange","word":"sustain","pos":"(v)","ipa":"/səˈsteɪn/","defVi":"duy trì, chống đỡ, nuôi dưỡng","defEn":"to cause or allow something to continue for a period of time","examples":["The company struggled to [sustain] its rapid growth during the economic crisis. (=Dịch: Công ty đã phải vật lộn để duy trì sự tăng trưởng nhanh chóng trong cuộc khủng hoảng kinh tế.)","The earth produces enough food to [sustain] the entire global population. (=Dịch: Trái Đất sản xuất đủ lương thực để nuôi sống toàn bộ dân số toàn cầu.)","These ancient stone pillars cannot [sustain] the heavy weight of the new roof. (=Dịch: Những cây cột đá cổ này không thể chống đỡ được sức nặng của phần mái mới.)"],"ukAudio":"/ai_services/tts3/?q=sustain&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=sustain&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AAn%2F"},{"id":"lv_4_385","topic":"Cultural and Historical Exchange","word":"swiss","pos":"(adj)","ipa":"/swɪs/","defVi":"thuộc về Thụy Sĩ, người Thụy Sĩ","defEn":"relating to Switzerland or its people","examples":["She bought a high-quality [Swiss] watch during her vacation in Geneva. (=Dịch: Cô ấy đã mua một chiếc đồng hồ Thụy Sĩ chất lượng cao trong kỳ nghỉ ở Geneva.)","The recipe calls for authentic [Swiss] cheese to give it a rich flavor. (=Dịch: Công thức yêu cầu phô mai Thụy Sĩ chính hiệu để tạo nên hương vị béo ngậy đậm đà.)","We spent a week hiking through the breathtaking [Swiss] Alps. (=Dịch: Chúng tôi đã dành một tuần đi bộ đường dài qua dãy Alps hùng vĩ của Thụy Sĩ.)"],"ukAudio":"/ai_services/tts3/?q=swiss&lang=en-GB&ipa=%2Fsw%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=swiss&lang=en-US&ipa=%2Fsw%C9%AAs%2F"},{"id":"lv_4_386","topic":"Cultural and Historical Exchange","word":"sydney","pos":"(n)","ipa":"/ˈsɪd.ni/","defVi":"thành phố Sydney (Úc)","defEn":"the largest city in Australia, famous for its Opera House and harbor","examples":["She decided to move to [Sydney] to pursue her university studies. (=Dịch: Cô ấy quyết định chuyển đến Sydney để theo đuổi việc học đại học.)","The flight from Tokyo to [Sydney] takes around nine hours. (=Dịch: Chuyến bay từ Tokyo đến Sydney mất khoảng chín tiếng.)","Many tourists visit [Sydney] every year to see the famous Opera House. (=Dịch: Nhiều du khách đến thăm Sydney hàng năm để chiêm ngưỡng Nhà hát Opera nổi tiếng.)"],"ukAudio":"/ai_services/tts3/?q=sydney&lang=en-GB&ipa=%2F%CB%88s%C9%AAd.ni%2F","usAudio":"/ai_services/tts3/?q=sydney&lang=en-US&ipa=%2F%CB%88s%C9%AAd.ni%2F"},{"id":"lv_4_387","topic":"Cultural and Historical Exchange","word":"symphony","pos":"(n)","ipa":"/ˈsɪm.fə.ni/","defVi":"bản nhạc giao hưởng","defEn":"a long, elaborate musical composition usually in four movements for a full orchestra","examples":["The orchestra performed Beethoven's Ninth [symphony] with tremendous energy. (=Dịch: Dàn nhạc đã biểu diễn bản giao hưởng số 9 của Beethoven với nguồn năng lượng vô cùng mạnh mẽ.)","Attending a live [symphony] concert is an unforgettable experience for music lovers. (=Dịch: Tham dự một buổi hòa nhạc giao hưởng trực tiếp là một trải nghiệm khó quên đối với những người yêu âm nhạc.)","He spent years composing a grand [symphony] dedicated to his homeland. (=Dịch: Ông đã dành nhiều năm để sáng tác một bản giao hưởng hoành tráng dành tặng cho quê hương mình.)"],"ukAudio":"/ai_services/tts3/?q=symphony&lang=en-GB&ipa=%2F%CB%88s%C9%AAm.f%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=symphony&lang=en-US&ipa=%2F%CB%88s%C9%AAm.f%C9%99.ni%2F"},{"id":"lv_4_388","topic":"Cultural and Historical Exchange","word":"tailor","pos":"(n)","ipa":"/ˈteɪ.lər/","defVi":"thợ may (đặc biệt là may âu phục)","defEn":"a person whose job is making, repairing, or altering clothes, especially suits and coats","examples":["He went to a local [tailor] to get his wedding suit made. (=Dịch: Anh ấy đã đến một [thợ may] địa phương để may bộ âu phục cưới của mình.)","The [tailor] carefully measured my waist and shoulders. (=Dịch: Người [thợ may] cẩn thận đo vòng eo và vai của tôi.)","If these trousers are too long, a [tailor] can easily shorten them. (=Dịch: Nếu chiếc quần này quá dài, một người [thợ may] có thể dễ dàng cắt ngắn nó.)"],"ukAudio":"/ai_services/tts3/?q=tailor&lang=en-GB&ipa=%2F%CB%88te%C9%AA.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tailor&lang=en-US&ipa=%2F%CB%88te%C9%AA.l%C9%99r%2F"},{"id":"lv_4_389","topic":"Cultural and Historical Exchange","word":"tax","pos":"(n)","ipa":"/tæks/","defVi":"thuế, tiền thuế","defEn":"money that you have to pay to the government based on your income or cost of goods","examples":["The government decided to raise the [tax] on sugary drinks. (=Dịch: Chính phủ đã quyết định tăng thuế đối với đồ uống có đường.)","Citizens must file their income [tax] returns before the deadline. (=Dịch: Công dân phải nộp tờ khai thuế thu nhập trước thời hạn.)","The price displayed on the menu includes all local [tax] charges. (=Dịch: Giá niêm yết trên thực đơn đã bao gồm tất cả các khoản thuế địa phương.)"],"ukAudio":"/ai_services/tts3/?q=tax&lang=en-GB&ipa=%2Ft%C3%A6ks%2F","usAudio":"/ai_services/tts3/?q=tax&lang=en-US&ipa=%2Ft%C3%A6ks%2F"},{"id":"lv_4_390","topic":"Cultural and Historical Exchange","word":"technician","pos":"(n)","ipa":"/tɛkˈnɪʃ.ən/","defVi":"kỹ thuật viên, thợ kỹ thuật","defEn":"a person skilled in the practical techniques of a specific science, trade, or craft","examples":["A laboratory [technician] analyzed the blood samples. (=Dịch: Một [kỹ thuật viên] phòng thí nghiệm đã phân tích các mẫu máu.)","We called an IT [technician] to fix the server issue. (=Dịch: Chúng tôi đã gọi một [kỹ thuật viên] công nghệ thông tin đến để khắc phục sự cố máy chủ.)","The aircraft was thoroughly inspected by a certified [technician]. (=Dịch: Chiếc máy bay đã được kiểm tra kỹ lưỡng bởi một [kỹ thuật viên] có chứng chỉ.)"],"ukAudio":"/ai_services/tts3/?q=technician&lang=en-GB&ipa=%2Ft%C9%9Bk%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=technician&lang=en-US&ipa=%2Ft%C9%9Bk%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_4_391","topic":"Cultural and Historical Exchange","word":"technological","pos":"(adj)","ipa":"/ˌtek.nəˈlɑː.dʒɪ.kəl/","defVi":"thuộc về công nghệ, kỹ thuật","defEn":"relating to or using scientific knowledge and machinery in industry or daily life","examples":["Recent [technological] advancements have transformed the way people communicate. (=Dịch: Những tiến bộ công nghệ gần đây đã làm thay đổi cách thức con người giao tiếp.)","The company invested heavily in [technological] innovations to improve productivity. (=Dịch: Công ty đã đầu tư mạnh mẽ vào các đổi mới công nghệ nhằm nâng cao năng suất.)","Automation is one of the biggest [technological] changes in modern manufacturing. (=Dịch: Tự động hóa là một trong những thay đổi công nghệ lớn nhất trong ngành sản xuất hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=technological&lang=en-GB&ipa=%2F%CB%8Ctek.n%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=technological&lang=en-US&ipa=%2F%CB%8Ctek.n%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_4_392","topic":"Cultural and Historical Exchange","word":"telegraph","pos":"(n)","ipa":"/ˈtel.ə.ɡræf/","defVi":"điện báo, máy điện báo","defEn":"an early communication system that transmitted electrical signals over wires","examples":["The invention of the [telegraph] revolutionized long-distance communication in the 19th century. (=Dịch: Phát minh ra máy điện báo đã cách mạng hóa việc liên lạc đường dài vào thế kỷ 19.)","News of the victory was sent quickly across the country by [telegraph]. (=Dịch: Tin tức về chiến thắng đã được truyền đi nhanh chóng khắp cả nước bằng điện báo.)","Before the telephone became common, people relied heavily on the [telegraph]. (=Dịch: Trước khi điện thoại trở nên phổ biến, mọi người phụ thuộc rất nhiều vào điện báo.)"],"ukAudio":"/ai_services/tts3/?q=telegraph&lang=en-GB&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=telegraph&lang=en-US&ipa=%2F%CB%88tel.%C9%99.%C9%A1r%C3%A6f%2F"},{"id":"lv_4_393","topic":"Cultural and Historical Exchange","word":"temple","pos":"(n)","ipa":"/ˈtɛm.pəl/","defVi":"ngôi đền, ngôi chùa","defEn":"a building used for religious worship, especially in religions other than Christianity","examples":["Many pilgrims travel to the ancient [temple] to pray every spring. (=Dịch: Nhiều người hành hương đến ngôi đền cổ để cầu nguyện vào mỗi mùa xuân.)","The Buddhist [temple] is situated high on a misty mountain. (=Dịch: Ngôi chùa Phật giáo nằm ở vị trí cao trên một ngọn núi mù sương.)","Tourists must remove their shoes before entering the sacred [temple]. (=Dịch: Du khách phải cởi giày trước khi bước vào ngôi đền linh thiêng.)"],"ukAudio":"/ai_services/tts3/?q=temple&lang=en-GB&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=temple&lang=en-US&ipa=%2F%CB%88t%C9%9Bm.p%C9%99l%2F"},{"id":"lv_4_394","topic":"Cultural and Historical Exchange","word":"tension","pos":"(n)","ipa":"/ˈtɛn.ʃən/","defVi":"sự căng thẳng, tình trạng đối đầu","defEn":"a feeling of nervousness, lack of trust, or strain between people or groups","examples":["Diplomatic talks helped reduce political [tension] between the two neighboring countries. (=Dịch: Các cuộc đàm phán ngoại giao đã giúp giảm bớt căng thẳng chính trị giữa hai quốc gia láng giềng.)","You could feel the growing [tension] in the room as the deadline approached. (=Dịch: Bạn có thể cảm nhận được sự căng thẳng ngày càng tăng trong phòng khi thời hạn chót đang đến gần.)","Regular exercise and meditation can effectively relieve physical [tension] caused by daily stress. (=Dịch: Tập thể dục thường xuyên và thiền định có thể giải tỏa hiệu quả sự căng cơ do căng thẳng hàng ngày gây ra.)"],"ukAudio":"/ai_services/tts3/?q=tension&lang=en-GB&ipa=%2F%CB%88t%C9%9Bn.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=tension&lang=en-US&ipa=%2F%CB%88t%C9%9Bn.%CA%83%C9%99n%2F"},{"id":"lv_4_395","topic":"Cultural and Historical Exchange","word":"textile","pos":"(n)","ipa":"/ˈtek.staɪl/","defVi":"vải dệt, hàng dệt may","defEn":"any type of cloth or woven fabric","examples":["The region is famous for its traditional [textile] industry. (=Dịch: Khu vực này nổi tiếng với ngành dệt may truyền thống.)","Natural fibres are commonly used to produce high-quality [textile] goods. (=Dịch: Sợi tự nhiên thường được sử dụng để sản xuất các mặt hàng dệt may chất lượng cao.)","The museum exhibits ancient [textile] patterns from different cultures. (=Dịch: Bảo tàng trưng bày các hoa văn dệt may cổ xưa từ nhiều nền văn hóa khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=textile&lang=en-GB&ipa=%2F%CB%88tek.sta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=textile&lang=en-US&ipa=%2F%CB%88tek.sta%C9%AAl%2F"},{"id":"lv_4_396","topic":"Cultural and Historical Exchange","word":"therapy","pos":"(n)","ipa":"/ˈθer.ə.pi/","defVi":"liệu pháp, sự điều trị","defEn":"treatment intended to relieve or heal a disorder or illness","examples":["Physical [therapy] helped the athlete recover from a severe knee injury. (=Dịch: Vật lý trị liệu đã giúp vận động viên hồi phục sau chấn thương đầu gối nghiêm trọng.)","She attends weekly cognitive behavioral [therapy] sessions to manage stress. (=Dịch: Cô ấy tham gia các buổi trị liệu hành vi nhận thức hàng tuần để kiểm soát sự căng thẳng.)","Art [therapy] is often used to help children express their feelings. (=Dịch: Trị liệu nghệ thuật thường được sử dụng để giúp trẻ em bộc lộ cảm xúc của mình.)"],"ukAudio":"/ai_services/tts3/?q=therapy&lang=en-GB&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F","usAudio":"/ai_services/tts3/?q=therapy&lang=en-US&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F"},{"id":"lv_4_397","topic":"Cultural and Historical Exchange","word":"thermometer","pos":"(n)","ipa":"/θərˈmɑː.mə.t̬ɚ/","defVi":"nhiệt kế","defEn":"an instrument used for measuring temperature","examples":["The nurse used a digital [thermometer] to check the child's fever. (=Dịch: Y tá đã dùng một chiếc nhiệt kế điện tử để kiểm tra cơn sốt của đứa trẻ.)","Check the outdoor [thermometer] before deciding what clothes to wear. (=Dịch: Hãy kiểm tra nhiệt kế ngoài trời trước khi quyết định nên mặc quần áo gì.)","The laboratory [thermometer] showed a sudden rise in temperature. (=Dịch: Nhiệt kế trong phòng thí nghiệm cho thấy nhiệt độ tăng đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=thermometer&lang=en-GB&ipa=%2F%CE%B8%C9%99r%CB%88m%C9%91%CB%90.m%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=thermometer&lang=en-US&ipa=%2F%CE%B8%C9%99r%CB%88m%C9%91%CB%90.m%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_4_398","topic":"Cultural and Historical Exchange","word":"thumb","pos":"(n)","ipa":"/θʌm/","defVi":"ngón tay cái","defEn":"the short, thick first digit of the human hand, set apart from the other four fingers","examples":["He accidentally hit his [thumb] with the hammer while fixing the shelf. (=Dịch: Anh ấy vô tình đập búa vào ngón tay cái khi đang sửa cái kệ.)","She gave me a [thumb] up to signal that everything was going well. (=Dịch: Cô ấy giơ ngón tay cái lên với tôi để ra hiệu rằng mọi chuyện đang diễn ra tốt đẹp.)","The baby fell asleep while sucking its [thumb]. (=Dịch: Đứa bé ngủ thiếp đi trong khi đang mút ngón tay cái.)"],"ukAudio":"/ai_services/tts3/?q=thumb&lang=en-GB&ipa=%2F%CE%B8%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=thumb&lang=en-US&ipa=%2F%CE%B8%CA%8Cm%2F"},{"id":"lv_4_399","topic":"Cultural and Historical Exchange","word":"tiger","pos":"(n)","ipa":"/ˈtaɪ.ɡər/","defVi":"con hổ","defEn":"a large wild cat that has yellow-orange fur with black stripes","examples":["The Bengal [tiger] is one of the most magnificent wild animals. (=Dịch: [Hổ] Bengal là một trong những loài động vật hoang dã tráng lệ nhất.)","Conservationists are working hard to protect the endangered Siberian [tiger]. (=Dịch: Các nhà bảo tồn đang nỗ lực hết mình để bảo vệ loài [hổ] Siberia có nguy cơ tuyệt chủng.)","We saw a [tiger] resting in the shade at the wildlife park. (=Dịch: Chúng tôi đã nhìn thấy một con [hổ] đang nghỉ ngơi dưới bóng râm tại công viên động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=tiger&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%99r%2F","usAudio":"/ai_services/tts3/?q=tiger&lang=en-US&ipa=%2F%CB%88ta%C9%AA.%C9%A1%C9%99r%2F"},{"id":"lv_4_400","topic":"Cultural and Historical Exchange","word":"timeline","pos":"(n)","ipa":"/ˈtaɪm.laɪn/","defVi":"mốc thời gian, dòng thời gian, tiến độ","defEn":"a graphical representation of a period of time on which important events are marked","examples":["The textbook includes a historical [timeline] of the major wars. (=Dịch: Sách giáo khoa bao gồm một dòng thời gian lịch sử về các cuộc chiến tranh lớn.)","The project manager established a strict [timeline] for completing the tasks. (=Dịch: Người quản lý dự án đã thiết lập một mốc thời gian nghiêm ngặt để hoàn thành các nhiệm vụ.)","We need to review the [timeline] to ensure we do not miss the launch date. (=Dịch: Chúng ta cần xem lại tiến độ thời gian để đảm bảo không bỏ lỡ ngày ra mắt.)"],"ukAudio":"/ai_services/tts3/?q=timeline&lang=en-GB&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=timeline&lang=en-US&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F"},{"id":"lv_4_401","topic":"Cultural and Historical Exchange","word":"tin","pos":"(n)","ipa":"/tɪn/","defVi":"thiếc; hộp thiếc, lon","defEn":"a soft, silvery metal, or a metal container used for storing food","examples":["He opened a [tin] of baked beans for a quick dinner. (=Dịch: Anh ấy đã mở một hộp đậu nướng cho bữa tối nhanh gọn.)","Bronze is an alloy mainly composed of copper and [tin]. (=Dịch: Đồng điếu là một hợp kim chủ yếu bao gồm đồng và thiếc.)","Keep the biscuits in an airtight [tin] to keep them crisp. (=Dịch: Hãy giữ bánh quy trong hộp thiếc kín khí để giữ cho bánh luôn giòn.)"],"ukAudio":"/ai_services/tts3/?q=tin&lang=en-GB&ipa=%2Ft%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=tin&lang=en-US&ipa=%2Ft%C9%AAn%2F"},{"id":"lv_4_402","topic":"Cultural and Historical Exchange","word":"trace","pos":"(v)","ipa":"/treɪs/","defVi":"dò tìm, truy vết, lần theo dấu vết","defEn":"to find or discover someone or something by investigation or following clues","examples":["Detectives managed to [trace] the origin of the mysterious phone call. (=Dịch: Các thám tử đã lần ra được nguồn gốc của cuộc gọi bí ẩn.)","Historians can [trace] the tradition back to ancient civilizations. (=Dịch: Các nhà sử học có thể truy nguyên truyền thống này về tận các nền văn minh cổ đại.)","Health officials worked quickly to [trace] anyone who had been in contact with the patient. (=Dịch: Các quan chức y tế đã nhanh chóng làm việc để truy vết bất kỳ ai từng tiếp xúc với bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=trace&lang=en-GB&ipa=%2Ftre%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=trace&lang=en-US&ipa=%2Ftre%C9%AAs%2F"},{"id":"lv_4_403","topic":"Cultural and Historical Exchange","word":"trade","pos":"(v)","ipa":"/treɪd/","defVi":"buôn bán, giao thương, trao đổi","defEn":"to buy and sell goods or services","examples":["The two countries agreed to [trade] agricultural products with each other. (=Dịch: Hai quốc gia đã đồng ý buôn bán các sản phẩm nông nghiệp với nhau.)","Many merchants gathered at the port to [trade] spices and silk. (=Dịch: Nhiều thương nhân đã tụ tập tại cảng để buôn bán gia vị và lụa.)","Investors [trade] shares on the stock exchange every weekday. (=Dịch: Các nhà đầu tư giao dịch cổ phiếu trên sàn chứng khoán vào tất cả các ngày trong tuần.)"],"ukAudio":"/ai_services/tts3/?q=trade&lang=en-GB&ipa=%2Ftre%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=trade&lang=en-US&ipa=%2Ftre%C9%AAd%2F"},{"id":"lv_4_404","topic":"Cultural and Historical Exchange","word":"tragedy","pos":"(n)","ipa":"/ˈtrædʒ.ə.di/","defVi":"bi kịch, thảm kịch","defEn":"an event causing great sadness, suffering, or loss of life","examples":["The sudden collapse of the bridge was a terrible human [tragedy]. (=Dịch: Sự sụp đổ đột ngột của cây cầu là một thảm kịch kinh hoàng đối với con người.)","Emergency services responded quickly to prevent further [tragedy] after the fire. (=Dịch: Các dịch vụ cứu hộ khẩn cấp đã phản ứng nhanh chóng để ngăn ngừa thêm thảm kịch sau vụ hỏa hoạn.)","Shakespeare's play Romeo and Juliet is one of the most famous examples of a [tragedy]. (=Dịch: Vở kịch Romeo và Juliet của Shakespeare là một trong những ví dụ nổi tiếng nhất về một vở bi kịch.)"],"ukAudio":"/ai_services/tts3/?q=tragedy&lang=en-GB&ipa=%2F%CB%88tr%C3%A6d%CA%92.%C9%99.di%2F","usAudio":"/ai_services/tts3/?q=tragedy&lang=en-US&ipa=%2F%CB%88tr%C3%A6d%CA%92.%C9%99.di%2F"},{"id":"lv_4_405","topic":"Cultural and Historical Exchange","word":"transform","pos":"(v)","ipa":"/trænsˈfɔrm/","defVi":"biến đổi, thay đổi hoàn toàn","defEn":"to change the form, appearance, or character of something completely","examples":["Online education has the power to [transform] traditional learning methods. (=Dịch: Giáo dục trực tuyến có khả năng làm thay đổi các phương pháp học tập truyền thống.)","A fresh coat of paint can easily [transform] a dull room into a lively space. (=Dịch: Một lớp sơn mới có thể dễ dàng biến một căn phòng ảm đạm thành một không gian tràn đầy sức sống.)","The new mayor plans to [transform] the abandoned warehouse into a public park. (=Dịch: Thị trưởng mới dự định biến nhà kho bỏ hoang thành một công viên công cộng.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94rm%2F"},{"id":"lv_4_406","topic":"Cultural and Historical Exchange","word":"translate","pos":"(v)","ipa":"/trænzˈleɪt/","defVi":"dịch, phiên dịch","defEn":"to express words or text in a different language","examples":["She helped [translate] the official documents into Vietnamese. (=Dịch: Cô ấy đã giúp dịch các tài liệu chính thức sang tiếng Việt.)","A good application can [translate] spoken sentences in real time. (=Dịch: Một ứng dụng tốt có thể dịch các câu nói theo thời gian thực.)","His academic success did not [translate] into practical career achievements. (=Dịch: Thành công trong học tập của anh ấy đã không chuyển hóa thành những thành tựu sự nghiệp thực tế.)"],"ukAudio":"/ai_services/tts3/?q=translate&lang=en-GB&ipa=%2Ftr%C3%A6nz%CB%88le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=translate&lang=en-US&ipa=%2Ftr%C3%A6nz%CB%88le%C9%AAt%2F"},{"id":"lv_4_407","topic":"Cultural and Historical Exchange","word":"translation","pos":"(n)","ipa":"/trænsˈleɪ.ʃən/","defVi":"sự dịch thuật; bản dịch","defEn":"the process of changing written or spoken words into another language, or the text produced","examples":["The English [translation] of the French novel became an international bestseller. (=Dịch: Bản dịch tiếng Anh của cuốn tiểu thuyết tiếng Pháp đã trở thành một tác phẩm bán chạy trên toàn thế giới.)","Literal [translation] does not always capture the true meaning of an idiom. (=Dịch: Việc dịch theo nghĩa đen không phải lúc nào cũng truyền tải được ý nghĩa thực sự của một thành ngữ.)","She works in machine [translation] to improve automated language tools. (=Dịch: Cô ấy làm việc trong lĩnh vực dịch máy để cải thiện các công cụ ngôn ngữ tự động.)"],"ukAudio":"/ai_services/tts3/?q=translation&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=translation&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_408","topic":"Cultural and Historical Exchange","word":"transportation","pos":"(n)","ipa":"/ˌtræn.spɚˈteɪ.ʃən/","defVi":"giao thông, phương tiện vận tải, sự vận chuyển","defEn":"a system or method for carrying passengers or goods from one place to another","examples":["Public [transportation] in this city is cheap and reliable. (=Dịch: Phương tiện giao thông công cộng ở thành phố này vừa rẻ lại vừa đáng tin cậy.)","The company arranged the [transportation] of the heavy machinery by train. (=Dịch: Công ty đã sắp xếp việc vận chuyển máy móc hạng nặng bằng tàu hỏa.)","Cycling is an eco-friendly mode of [transportation]. (=Dịch: Đi xe đạp là một phương thức di chuyển thân thiện với môi trường.)"],"ukAudio":"/ai_services/tts3/?q=transportation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6n.sp%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=transportation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6n.sp%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_4_409","topic":"Cultural and Historical Exchange","word":"tremendous","pos":"(adj)","ipa":"/trəˈmen.dəs/","defVi":"to lớn, ghê gớm, phi thường","defEn":"extremely large in amount, scale, or intensity","examples":["The project has made [tremendous] progress over the last two weeks. (=Dịch: Dự án đã đạt được tiến bộ to lớn trong hai tuần qua.)","She felt a [tremendous] sense of relief after passing all her final exams. (=Dịch: Cô cảm thấy nhẹ nhõm vô cùng sau khi vượt qua tất cả các kỳ thi cuối kỳ.)","The charity event was a [tremendous] success, raising thousands of dollars. (=Dịch: Sự kiện từ thiện đã thành công rực rỡ, quyên góp được hàng ngàn đô la.)"],"ukAudio":"/ai_services/tts3/?q=tremendous&lang=en-GB&ipa=%2Ftr%C9%99%CB%88men.d%C9%99s%2F","usAudio":"/ai_services/tts3/?q=tremendous&lang=en-US&ipa=%2Ftr%C9%99%CB%88men.d%C9%99s%2F"},{"id":"lv_4_410","topic":"Cultural and Historical Exchange","word":"tribe","pos":"(n)","ipa":"/traɪb/","defVi":"bộ tộc, bộ lạc","defEn":"a group of people of the same race with the same language and customs","examples":["The remote [tribe] has lived in the rainforest for centuries. (=Dịch: Bộ lạc xa xôi này đã sống trong rừng nhiệt đới qua nhiều thế kỷ.)","Anthropologists visited the island to study the local [tribe]. (=Dịch: Các nhà nhân chủng học đã đến thăm hòn đảo để nghiên cứu bộ lạc địa phương.)","Members of the [tribe] gathered to celebrate the annual festival. (=Dịch: Các thành viên của bộ lạc đã tụ họp để ăn mừng lễ hội thường niên.)"],"ukAudio":"/ai_services/tts3/?q=tribe&lang=en-GB&ipa=%2Ftra%C9%AAb%2F","usAudio":"/ai_services/tts3/?q=tribe&lang=en-US&ipa=%2Ftra%C9%AAb%2F"},{"id":"lv_4_411","topic":"Cultural and Historical Exchange","word":"trunk","pos":"(n)","ipa":"/trʌŋk/","defVi":"thân cây; cốp xe ô tô; vòi voi","defEn":"the main thick stem of a tree, or the luggage compartment of a car, or an elephant's long nose","examples":["The thick [trunk] of the ancient oak tree provided shade for the entire garden. (=Dịch: Thân cây to lớn của cây sồi cổ thụ tỏa bóng mát cho toàn bộ khu vườn.)","We packed all the camping gear into the [trunk] of the car before setting off. (=Dịch: Chúng tôi xếp toàn bộ dụng cụ cắm trại vào cốp xe ô tô trước khi khởi hành.)","An elephant uses its powerful [trunk] to drink water and pick up objects. (=Dịch: Con voi sử dụng chiếc vòi đầy sức mạnh của mình để uống nước và nhặt đồ vật.)"],"ukAudio":"/ai_services/tts3/?q=trunk&lang=en-GB&ipa=%2Ftr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=trunk&lang=en-US&ipa=%2Ftr%CA%8C%C5%8Bk%2F"},{"id":"lv_4_412","topic":"Cultural and Historical Exchange","word":"turf","pos":"(n)","ipa":"/tɝːf/","defVi":"lớp đất có cỏ, thảm cỏ tự nhiên/nhân tạo; địa bàn","defEn":"a surface layer of soil with grass growing on it, or an area considered as someone's territory","examples":["The stadium groundskeeper laid new [turf] on the football pitch. (=Dịch: Người chăm sóc sân cỏ của sân vận động đã trải thảm cỏ mới trên sân bóng đá.)","Local street gangs fought fiercely to protect their [turf]. (=Dịch: Các băng đảng đường phố địa phương đã ẩu đả dữ dội để bảo vệ địa bàn của mình.)","Children love running barefoot on the soft green [turf]. (=Dịch: Trẻ em rất thích chạy chân trần trên thảm cỏ xanh mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=turf&lang=en-GB&ipa=%2Ft%C9%9D%CB%90f%2F","usAudio":"/ai_services/tts3/?q=turf&lang=en-US&ipa=%2Ft%C9%9D%CB%90f%2F"},{"id":"lv_4_413","topic":"Cultural and Historical Exchange","word":"twist","pos":"(v)","ipa":"/twɪst/","defVi":"xoắn, vặn, làm méo mó","defEn":"to turn or bend something out of its normal shape or direction","examples":["Be careful not to [twist] your ankle when running on uneven ground. (=Dịch: Hãy cẩn thận kẻo bị trẹo mắt cá chân khi chạy trên địa hình gồ ghề.)","You need to [twist] the bottle cap clockwise to close it securely. (=Dịch: Bạn cần vặn nắp chai theo chiều kim đồng hồ để đóng chặt nó.)","Critics claimed the reporter tried to [twist] the truth to create controversy. (=Dịch: Các nhà phê bình cho rằng phóng viên đã cố tình bóp méo sự thật để tạo tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=twist&lang=en-GB&ipa=%2Ftw%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=twist&lang=en-US&ipa=%2Ftw%C9%AAst%2F"},{"id":"lv_4_414","topic":"Cultural and Historical Exchange","word":"uncover","pos":"(v)","ipa":"/ʌnˈkʌv.ɚ/","defVi":"khám phá, hé lộ, phanh phui","defEn":"to discover or make known something that was previously hidden or secret","examples":["Journalists worked hard to [uncover] the truth behind the political scandal. (=Dịch: Các nhà báo đã nỗ lực làm việc để vạch trần sự thật đằng sau vụ bê bối chính trị.)","Archaeologists managed to [uncover] ancient pottery at the dig site. (=Dịch: Các nhà khảo cổ học đã tìm thấy đồ gốm cổ tại địa điểm khai quật.)","The audit helped the company [uncover] significant financial irregularities. (=Dịch: Cuộc kiểm toán đã giúp công ty phát hiện ra những sai phạm tài chính nghiêm trọng.)"],"ukAudio":"/ai_services/tts3/?q=uncover&lang=en-GB&ipa=%2F%CA%8Cn%CB%88k%CA%8Cv.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=uncover&lang=en-US&ipa=%2F%CA%8Cn%CB%88k%CA%8Cv.%C9%9A%2F"},{"id":"lv_4_415","topic":"Cultural and Historical Exchange","word":"understandable","pos":"(adj)","ipa":"/ˌʌn.dɚˈstæn.də.bəl/","defVi":"có thể hiểu được, hợp lý, dễ cảm thông","defEn":"easy to understand or natural and acceptable under the circumstances","examples":["Her anxiety before the job interview was completely [understandable]. (=Dịch: Sự lo lắng của cô ấy trước buổi phỏng vấn xin việc là hoàn toàn có thể hiểu được.)","It is [understandable] that parents worry about the safety of their children online. (=Dịch: Việc các bậc phụ huynh lo lắng về sự an toàn của con cái trên mạng là điều dễ hiểu.)","He made an [understandable] mistake given the lack of clear instructions. (=Dịch: Anh ấy đã mắc phải một sai lầm có thể thông cảm được do thiếu những hướng dẫn rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=understandable&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=understandable&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F"},{"id":"lv_4_416","topic":"Cultural and Historical Exchange","word":"undertake","pos":"(v)","ipa":"/ˌʌn.dərˈteɪk/","defVi":"đảm nhận, thực hiện","defEn":"to commit oneself to and begin a task, project, or responsibility","examples":["The university will [undertake] a comprehensive study on renewable energy. (=Dịch: Trường đại học sẽ tiến hành một nghiên cứu toàn diện về năng lượng tái tạo.)","No one was willing to [undertake] such a risky financial assignment. (=Dịch: Không ai sẵn lòng đảm nhận một nhiệm vụ tài chính đầy rủi ro như vậy.)","The company agreed to [undertake] full responsibility for the construction delays. (=Dịch: Công ty đã đồng ý nhận toàn bộ trách nhiệm về sự chậm trễ trong việc thi công.)"],"ukAudio":"/ai_services/tts3/?q=undertake&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=undertake&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88te%C9%AAk%2F"},{"id":"lv_4_417","topic":"Cultural and Historical Exchange","word":"unemployment","pos":"(n)","ipa":"/ˌʌn.ɪmˈplɔɪ.mənt/","defVi":"sự thất nghiệp, nạn thất nghiệp","defEn":"the state of not having a job, or the number of people without work","examples":["The government is trying to reduce [unemployment] by creating new job programs. (=Dịch: Chính phủ đang cố gắng giảm tình trạng thất nghiệp bằng cách tạo ra các chương trình việc làm mới.)","High [unemployment] among young graduates is a major economic issue. (=Dịch: Tỷ lệ thất nghiệp cao ở những sinh viên trẻ mới tốt nghiệp là một vấn đề kinh tế lớn.)","Many workers struggled to pay their bills during periods of prolonged [unemployment]. (=Dịch: Nhiều người lao động đã phải chật vật chi trả các hóa đơn trong những giai đoạn thất nghiệp kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=unemployment&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AA.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=unemployment&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%AAm%CB%88pl%C9%94%C9%AA.m%C9%99nt%2F"},{"id":"lv_4_418","topic":"Cultural and Historical Exchange","word":"universal","pos":"(adj)","ipa":"/ˌjuː.nəˈvɝː.səl/","defVi":"phổ quát, toàn cầu, phổ biến","defEn":"existing everywhere or involving everyone in the world","examples":["Music is often described as a [universal] language that connects all cultures. (=Dịch: Âm nhạc thường được mô tả là một ngôn ngữ phổ quát kết nối mọi nền văn hóa.)","Access to clean water should be recognized as a [universal] human right. (=Dịch: Việc tiếp cận nước sạch nên được công nhận là một quyền phổ quát của con người.)","The new policy received [universal] approval from the entire committee. (=Dịch: Chính sách mới đã nhận được sự đồng thuận tuyệt đối từ toàn bộ ủy ban.)"],"ukAudio":"/ai_services/tts3/?q=universal&lang=en-GB&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=universal&lang=en-US&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F"},{"id":"lv_4_419","topic":"Cultural and Historical Exchange","word":"unrealistic","pos":"(adj)","ipa":"/ˌʌn.ri.əˈlɪs.tɪk/","defVi":"phi thực tế, không thực tế","defEn":"not sensible or based on reality; impossible to achieve","examples":["Setting an [unrealistic] deadline will only cause unnecessary stress for the team. (=Dịch: Việc đặt ra một thời hạn không thực tế sẽ chỉ gây ra căng thẳng không cần thiết cho cả nhóm.)","Expecting to master a new language in a month is totally [unrealistic]. (=Dịch: Kỳ vọng thành thạo một ngôn ngữ mới trong một tháng là hoàn toàn phi thực tế.)","The movie was criticized for its [unrealistic] plot and weak characters. (=Dịch: Bộ phim bị chỉ trích vì cốt truyện phi thực tế và các nhân vật mờ nhạt.)"],"ukAudio":"/ai_services/tts3/?q=unrealistic&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.ri.%C9%99%CB%88l%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=unrealistic&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.ri.%C9%99%CB%88l%C9%AAs.t%C9%AAk%2F"},{"id":"lv_4_420","topic":"Cultural and Historical Exchange","word":"vast","pos":"(adj)","ipa":"/væst/","defVi":"rộng lớn, bao la","defEn":"extremely big in size, amount, or extent","examples":["The Sahara is a [vast] desert stretching across northern Africa. (=Dịch: Sahara là một sa mạc rộng lớn trải dài khắp Bắc Phi.)","A [vast] majority of employees supported the new policy. (=Dịch: Phần lớn đại đa số nhân viên đều ủng hộ chính sách mới.)","The project will require a [vast] amount of financial resources. (=Dịch: Dự án sẽ đòi hỏi một lượng tài chính khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=vast&lang=en-GB&ipa=%2Fv%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=vast&lang=en-US&ipa=%2Fv%C3%A6st%2F"},{"id":"lv_4_421","topic":"Cultural and Historical Exchange","word":"venue","pos":"(n)","ipa":"/ˈvɛn.juː/","defVi":"địa điểm tổ chức (sự kiện, hội nghị, biểu diễn)","defEn":"the place where an event or activity takes place","examples":["The hotel is an ideal [venue] for international conferences and business meetings. (=Dịch: Khách sạn là một địa điểm lý tưởng cho các hội nghị quốc tế và các cuộc họp kinh doanh.)","Organizers had to change the concert [venue] due to unexpected weather conditions. (=Dịch: Ban tổ chức đã phải thay đổi địa điểm tổ chức buổi hòa nhạc do điều kiện thời tiết bất ngờ.)","The stadium was chosen as the main [venue] for the upcoming sports tournament. (=Dịch: Sân vận động đã được chọn làm địa điểm chính cho giải đấu thể thao sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=venue&lang=en-GB&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F","usAudio":"/ai_services/tts3/?q=venue&lang=en-US&ipa=%2F%CB%88v%C9%9Bn.ju%CB%90%2F"},{"id":"lv_4_422","topic":"Cultural and Historical Exchange","word":"version","pos":"(n)","ipa":"/ˈvɝː.ʒən/","defVi":"phiên bản, bản phát hành, lời kể","defEn":"a particular form of something that differs slightly from other forms of it","examples":["The developers released an updated [version] of the software to fix minor security bugs. (=Dịch: Các nhà phát triển đã phát hành một phiên bản cập nhật của phần mềm để sửa các lỗi bảo mật nhỏ.)","Her [version] of the incident differed completely from what the other witnesses reported. (=Dịch: Lời kể của cô ấy về vụ việc hoàn toàn khác so với những gì các nhân chứng khác đã báo cáo.)","I prefer reading the original [version] of the novel rather than its translated adaptation. (=Dịch: Tôi thích đọc phiên bản gốc của cuốn tiểu thuyết hơn là bản chuyển thể đã được dịch thuật.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_4_423","topic":"Cultural and Historical Exchange","word":"visible","pos":"(adj)","ipa":"/ˈvɪz.ə.bəl/","defVi":"có thể nhìn thấy được, rõ ràng","defEn":"able to be seen or easily noticed","examples":["The stars were clearly [visible] in the clear night sky. (=Dịch: Những ngôi sao có thể nhìn thấy rõ ràng trên bầu trời đêm quang đãng.)","There has been a [visible] improvement in her spoken English skills. (=Dịch: Đã có sự tiến bộ rõ rệt trong kỹ năng nói tiếng Anh của cô ấy.)","Keep the emergency exit sign [visible] at all times for safety. (=Dịch: Hãy luôn giữ cho biển báo lối thoát hiểm dễ nhìn thấy để đảm bảo an toàn.)"],"ukAudio":"/ai_services/tts3/?q=visible&lang=en-GB&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=visible&lang=en-US&ipa=%2F%CB%88v%C9%AAz.%C9%99.b%C9%99l%2F"},{"id":"lv_4_424","topic":"Cultural and Historical Exchange","word":"vocabulary","pos":"(n)","ipa":"/vəˈkæb.jəˌlɛr.i/","defVi":"từ vựng, vốn từ","defEn":"all the words known and used by a particular person or in a specific language","examples":["Reading English novels regularly helps expand your active [vocabulary]. (=Dịch: Đọc tiểu thuyết tiếng Anh thường xuyên giúp mở rộng vốn từ vựng chủ động của bạn.)","The exam tests both grammar and advanced academic [vocabulary]. (=Dịch: Kỳ thi kiểm tra cả ngữ pháp và vốn từ vựng học thuật nâng cao.)","Children rapidly acquire new [vocabulary] by listening to stories and conversations. (=Dịch: Trẻ em tiếp thu từ vựng mới rất nhanh bằng cách lắng nghe các câu chuyện và cuộc trò chuyện.)"],"ukAudio":"/ai_services/tts3/?q=vocabulary&lang=en-GB&ipa=%2Fv%C9%99%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=vocabulary&lang=en-US&ipa=%2Fv%C9%99%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F"},{"id":"lv_4_425","topic":"Cultural and Historical Exchange","word":"volcanic","pos":"(adj)","ipa":"/vɑːlˈkæn.ɪk/","defVi":"thuộc về núi lửa, do núi lửa tạo ra","defEn":"caused by, connected with, or produced by a volcano","examples":["The island is covered in fertile [volcanic] soil that is great for farming. (=Dịch: Hòn đảo được bao phủ bởi lớp đất núi lửa màu mỡ rất thích hợp cho việc trồng trọt.)","Scientists observed increased [volcanic] activity in the mountain range. (=Dịch: Các nhà khoa học đã quan sát thấy hoạt động núi lửa gia tăng ở dãy núi này.)","The beach is famous for its unique [volcanic] black sand. (=Dịch: Bãi biển này nổi tiếng với bãi cát đen núi lửa độc đáo.)"],"ukAudio":"/ai_services/tts3/?q=volcanic&lang=en-GB&ipa=%2Fv%C9%91%CB%90l%CB%88k%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=volcanic&lang=en-US&ipa=%2Fv%C9%91%CB%90l%CB%88k%C3%A6n.%C9%AAk%2F"},{"id":"lv_4_426","topic":"Cultural and Historical Exchange","word":"voyage","pos":"(n)","ipa":"/ˈvɔɪ.ɪdʒ/","defVi":"chuyến đi dài (thường bằng đường biển hoặc vũ trụ)","defEn":"a long journey, especially by sea or in space","examples":["The Titanic sank on its maiden [voyage] across the Atlantic. (=Dịch: Tàu Titanic đã bị chìm trong chuyến hải trình đầu tiên băng qua Đại Tây Dương.)","Scientists are planning a historic [voyage] to Mars. (=Dịch: Các nhà khoa học đang lên kế hoạch cho một chuyến du hành mang tính lịch sử tới Sao Hỏa.)","The ancient sailors kept a detailed diary during their long [voyage]. (=Dịch: Các thủy thủ thời xưa đã ghi chép nhật ký chi tiết trong suốt chuyến hải trình dài ngày của họ.)"],"ukAudio":"/ai_services/tts3/?q=voyage&lang=en-GB&ipa=%2F%CB%88v%C9%94%C9%AA.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=voyage&lang=en-US&ipa=%2F%CB%88v%C9%94%C9%AA.%C9%AAd%CA%92%2F"},{"id":"lv_4_427","topic":"Cultural and Historical Exchange","word":"wealth","pos":"(n)","ipa":"/welθ/","defVi":"sự giàu có, của cải; sự phong phú","defEn":"a large amount of money, property, or valuable possessions; a large quantity of something","examples":["He used his considerable [wealth] to establish educational charities worldwide. (=Dịch: Ông đã sử dụng khối tài sản đáng kể của mình để thành lập các tổ chức từ thiện giáo dục trên toàn thế giới.)","The internet provides a [wealth] of information on virtually every topic. (=Dịch: Internet cung cấp một lượng thông tin vô cùng phong phú về hầu như mọi chủ đề.)","Good health is considered greater than material [wealth] by many cultures. (=Dịch: Sức khỏe tốt được nhiều nền văn hóa coi trọng hơn của cải vật chất.)"],"ukAudio":"/ai_services/tts3/?q=wealth&lang=en-GB&ipa=%2Fwel%CE%B8%2F","usAudio":"/ai_services/tts3/?q=wealth&lang=en-US&ipa=%2Fwel%CE%B8%2F"},{"id":"lv_4_428","topic":"Cultural and Historical Exchange","word":"wearer","pos":"(n)","ipa":"/ˈwɛr.ɚ/","defVi":"người mặc, người mang, người đeo (trang phục, phụ kiện)","defEn":"a person who wears a particular piece of clothing, accessory, or device","examples":["The helmet is designed to protect the [wearer] from head injuries. (=Dịch: Mũ bảo hiểm được thiết kế để bảo vệ người đội khỏi các chấn thương đầu.)","Smart watches can track the vital health signs of the [wearer] in real time. (=Dịch: Đồng hồ thông minh có thể theo dõi các chỉ số sinh tồn của người đeo theo thời gian thực.)","This lightweight jacket keeps the [wearer] warm without adding bulky weight. (=Dịch: Chiếc áo khoác nhẹ này giữ ấm cho người mặc mà không gây nặng nề hay cồng kềnh.)"],"ukAudio":"/ai_services/tts3/?q=wearer&lang=en-GB&ipa=%2F%CB%88w%C9%9Br.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=wearer&lang=en-US&ipa=%2F%CB%88w%C9%9Br.%C9%9A%2F"},{"id":"lv_4_429","topic":"Cultural and Historical Exchange","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪd.spred/","defVi":"lan rộng, phổ biến, diện rộng","defEn":"existing or happening in many places or among many people","examples":["The government is trying to stop the [widespread] use of illegal chemicals. (=Dịch: Chính phủ đang nỗ lực ngăn chặn việc sử dụng rộng rãi các hóa chất bất hợp pháp.)","Heavy storms caused [widespread] damage across the northern provinces. (=Dịch: Những trận bão lớn đã gây ra thiệt hại trên diện rộng khắp các tỉnh phía bắc.)","There is [widespread] agreement that renewable energy should be expanded. (=Dịch: Có sự đồng thuận rộng rãi rằng năng lượng tái tạo nên được mở rộng.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd.spred%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd.spred%2F"},{"id":"lv_4_430","topic":"Cultural and Historical Exchange","word":"winding","pos":"(adj)","ipa":"/ˈwaɪn.dɪŋ/","defVi":"uốn khúc, quanh co, ngoằn ngoèo","defEn":"having a lot of curves, bends, or turns rather than being straight","examples":["They drove slowly along the narrow, [winding] mountain road. (=Dịch: Họ lái xe chầm chậm dọc theo con đường núi hẹp và quanh co.)","The river follows a [winding] path through the valley. (=Dịch: Dòng sông uốn lượn theo một lộ trình quanh co qua thung lũng.)","A [winding] staircase led up to the top of the tower. (=Dịch: Một cầu thang xoắn ốc dẫn lên đỉnh tháp.)"],"ukAudio":"/ai_services/tts3/?q=winding&lang=en-GB&ipa=%2F%CB%88wa%C9%AAn.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=winding&lang=en-US&ipa=%2F%CB%88wa%C9%AAn.d%C9%AA%C5%8B%2F"},{"id":"lv_4_431","topic":"Cultural and Historical Exchange","word":"wing","pos":"(n)","ipa":"/wɪŋ/","defVi":"cánh (chim, máy bay)","defEn":"one of the parts of a bird, insect, or airplane used for flying","examples":["The injured bird could not fly because of a broken [wing]. (=Dịch: Con chim bị thương không thể bay vì bị gãy cánh.)","Passengers sitting near the plane's [wing] had an obstructed view. (=Dịch: Hành khách ngồi gần cánh máy bay bị hạn chế tầm nhìn.)","Butterflies use their colorful [wing] patterns to frighten predators. (=Dịch: Bướm sử dụng các hoa văn rực rỡ trên cánh để đe dọa những kẻ săn mồi.)"],"ukAudio":"/ai_services/tts3/?q=wing&lang=en-GB&ipa=%2Fw%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=wing&lang=en-US&ipa=%2Fw%C9%AA%C5%8B%2F"},{"id":"lv_4_432","topic":"Cultural and Historical Exchange","word":"wise","pos":"(adj)","ipa":"/waɪz/","defVi":"khôn ngoan, sáng suốt, thông thái","defEn":"having or showing good judgment, experience, and knowledge","examples":["It is always [wise] to save some money for unexpected emergencies. (=Dịch: Tiết kiệm một khoản tiền cho những trường hợp khẩn cấp bất ngờ luôn là điều khôn ngoan.)","She sought advice from a [wise] mentor before making a career change. (=Dịch: Cô đã tìm kiếm lời khuyên từ một người cố vấn thông thái trước khi chuyển đổi nghề nghiệp.)","Investing early in education is a very [wise] long-term decision. (=Dịch: Đầu tư sớm vào giáo dục là một quyết định dài hạn rất sáng suốt.)"],"ukAudio":"/ai_services/tts3/?q=wise&lang=en-GB&ipa=%2Fwa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=wise&lang=en-US&ipa=%2Fwa%C9%AAz%2F"},{"id":"lv_4_433","topic":"Cultural and Historical Exchange","word":"wool","pos":"(n)","ipa":"/wʊl/","defVi":"len, lông cừu","defEn":"the soft, thick hair that grows on the bodies of sheep and some other animals","examples":["This sweater is knitted from pure merino [wool]. (=Dịch: Chiếc áo len này được đan từ len merino nguyên chất.)","Australia is one of the world's leading exporters of raw [wool]. (=Dịch: Úc là một trong những quốc gia xuất khẩu len thô hàng đầu thế giới.)","She prefers wearing [wool] socks to keep her feet warm in winter. (=Dịch: Cô ấy thích đi tất len để giữ ấm chân vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=wool&lang=en-GB&ipa=%2Fw%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=wool&lang=en-US&ipa=%2Fw%CA%8Al%2F"},{"id":"lv_4_434","topic":"Cultural and Historical Exchange","word":"yarn","pos":"(n)","ipa":"/jɑːrn/","defVi":"sợi len, sợi dệt; câu chuyện dài","defEn":"spun thread used for knitting, weaving, or sewing; or a long, entertaining story","examples":["She bought several balls of soft wool [yarn] to knit a winter scarf. (=Dịch: Cô ấy đã mua vài cuộn len mềm để đan một chiếc khăn quàng cổ mùa đông.)","The old sailor loved to spin a fascinating [yarn] about his sea adventures. (=Dịch: Người thủy thủ già rất thích kể một câu chuyện ly kỳ về những chuyến phiêu lưu trên biển của mình.)","Traditional weavers dye the cotton [yarn] using natural plant extracts. (=Dịch: Những người thợ dệt truyền thống nhuộm sợi bông bằng chiết xuất thực vật tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=yarn&lang=en-GB&ipa=%2Fj%C9%91%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=yarn&lang=en-US&ipa=%2Fj%C9%91%CB%90rn%2F"}]},"rawTopic":"Cultural and Historical Exchange"},{"id":"listening_u5_6","title":"Chủ đề 6/10: Nature and Environmental Protection","actTitle":"Từ vựng chủ đề: Nature and Environmental Protection (422 từ)","problem":{"pType":"topic_flashcards","topic":"Nature and Environmental Protection","count":422,"words":[{"id":"lv_5_0","topic":"Nature and Environmental Protection","word":"absorb","pos":"(v)","ipa":"/əbˈzɔːrb/","defVi":"hấp thụ, thấm hút","defEn":"to take in liquid, gas, heat, or energy gradually from the space around","examples":["Plants [absorb] carbon dioxide and release oxygen during photosynthesis. (=Dịch: Thực vật hấp thụ khí cacbonic và giải phóng khí oxy trong quá trình quang hợp.)","A dry sponge will quickly [absorb] any spilled water on the table. (=Dịch: Một miếng bọt biển khô sẽ nhanh chóng hút sạch nước tràn trên bàn.)","Dark surfaces tend to [absorb] more heat from sunlight than light-colored ones. (=Dịch: Các bề mặt sẫm màu có xu hướng hấp thụ nhiều nhiệt từ ánh nắng mặt trời hơn các bề mặt sáng màu.)"],"ukAudio":"/ai_services/tts3/?q=absorb&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=absorb&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F"},{"id":"lv_5_1","topic":"Nature and Environmental Protection","word":"accidental","pos":"(adj)","ipa":"/ˌæk.səˈden.t̬əl/","defVi":"tình cờ, ngẫu nhiên, bất ngờ","defEn":"happening by chance rather than by intention or design","examples":["The fire was determined to be purely [accidental] and caused by an electrical fault. (=Dịch: Vụ hỏa hoạn được xác định là hoàn toàn do ngẫu nhiên và bắt nguồn từ sự cố điện.)","The discovery of penicillin was an [accidental] breakthrough in modern medicine. (=Dịch: Việc phát hiện ra penicillin là một bước đột phá tình cờ trong y học hiện đại.)","Please forgive my [accidental] deletion of your important computer files. (=Dịch: Xin hãy tha thứ cho việc tôi vô tình xóa các tệp máy tính quan trọng của bạn.)"],"ukAudio":"/ai_services/tts3/?q=accidental&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88den.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=accidental&lang=en-US&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88den.t%CC%AC%C9%99l%2F"},{"id":"lv_5_2","topic":"Nature and Environmental Protection","word":"accidentally","pos":"(adv)","ipa":"/ˌæk.səˈdɛn.t̬ə.li/","defVi":"tình cờ, vô tình","defEn":"by chance or without intention","examples":["I [accidentally] deleted the file from my laptop. (=Dịch: Tôi đã vô tình xóa tập tin đó khỏi máy tính xách tay của mình.)","She [accidentally] bumped into an old friend at the supermarket. (=Dịch: Cô ấy tình cờ chạm mặt một người bạn cũ tại siêu thị.)","The glass fell and broke when he [accidentally] knocked the table. (=Dịch: Chiếc ly rơi và vỡ khi anh ấy vô tình va vào bàn.)"],"ukAudio":"/ai_services/tts3/?q=accidentally&lang=en-GB&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88d%C9%9Bn.t%CC%AC%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=accidentally&lang=en-US&ipa=%2F%CB%8C%C3%A6k.s%C9%99%CB%88d%C9%9Bn.t%CC%AC%C9%99.li%2F"},{"id":"lv_5_3","topic":"Nature and Environmental Protection","word":"accurately","pos":"(adv)","ipa":"/ˈæk.jɚ.ət.li/","defVi":"một cách chính xác","defEn":"in a way that is correct, exact, and without any mistakes","examples":["The weather forecast [accurately] predicted the heavy rainfall. (=Dịch: Dự báo thời tiết đã dự đoán chính xác lượng mưa lớn.)","It is difficult to [accurately] calculate the total cost of the project. (=Dịch: Rất khó để tính toán chính xác tổng chi phí của dự án.)","Sensors were installed to [accurately] measure temperature changes. (=Dịch: Các cảm biến đã được lắp đặt để đo lường chính xác sự thay đổi nhiệt độ.)"],"ukAudio":"/ai_services/tts3/?q=accurately&lang=en-GB&ipa=%2F%CB%88%C3%A6k.j%C9%9A.%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=accurately&lang=en-US&ipa=%2F%CB%88%C3%A6k.j%C9%9A.%C9%99t.li%2F"},{"id":"lv_5_4","topic":"Nature and Environmental Protection","word":"adaptation","pos":"(n)","ipa":"/ˌæd.æpˈteɪ.ʃən/","defVi":"Sự thích nghi; tác phẩm chuyển thể.","defEn":"A change that helps an organism survive, or a modified version of a book or play.","examples":["Thick fur is an evolutionary [adaptation] that helps polar bears survive the cold. (=Dịch: Bộ lông dày là một sự thích nghi tiến hóa giúp gấu bắc cực sống sót qua giá lạnh.)","The movie is a modern [adaptation] of a classic novel. (=Dịch: Bộ phim là một tác phẩm chuyển thể hiện đại từ một cuốn tiểu thuyết kinh điển.)","Successful business [adaptation] is essential in a changing market. (=Dịch: Sự thích nghi kinh doanh thành công là điều cần thiết trong một thị trường đang thay đổi.)"],"ukAudio":"/ai_services/tts3/?q=adaptation&lang=en-GB&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=adaptation&lang=en-US&ipa=%2F%CB%8C%C3%A6d.%C3%A6p%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_5","topic":"Nature and Environmental Protection","word":"additive","pos":"(n)","ipa":"/ˈæd.ə.tɪv/","defVi":"Chất phụ gia.","defEn":"A substance added to something in small amounts to improve or preserve it.","examples":["Some people try to avoid buying foods that contain any artificial [additive]. (=Dịch: Một số người cố gắng tránh mua các loại thực phẩm có chứa bất kỳ chất phụ gia nhân tạo nào.)","The mechanic put a special [additive] into the engine oil to improve performance. (=Dịch: Người thợ máy đã cho một chất phụ gia đặc biệt vào dầu động cơ để cải thiện hiệu suất.)","Salt has been used as a natural food [additive] for centuries. (=Dịch: Muối đã được sử dụng như một chất phụ gia thực phẩm tự nhiên trong nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=additive&lang=en-GB&ipa=%2F%CB%88%C3%A6d.%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=additive&lang=en-US&ipa=%2F%CB%88%C3%A6d.%C9%99.t%C9%AAv%2F"},{"id":"lv_5_6","topic":"Nature and Environmental Protection","word":"administrative","pos":"(adj)","ipa":"/ədˈmɪn.ə.streɪ.tɪv/","defVi":"Thuộc về hành chính, quản trị.","defEn":"Relating to the management and organization of an institution or business.","examples":["She handles all the [administrative] tasks in the school office. (=Dịch: Cô ấy xử lý tất cả các công việc hành chính trong văn phòng trường học.)","The company reorganized its [administrative] structure to reduce costs. (=Dịch: Công ty đã tái cấu trúc bộ máy hành chính để cắt giảm chi phí.)","He spent hours completing the necessary [administrative] paperwork. (=Dịch: Anh ấy đã dành hàng giờ để hoàn thành các thủ tục giấy tờ hành chính cần thiết.)"],"ukAudio":"/ai_services/tts3/?q=administrative&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=administrative&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%C9%AAv%2F"},{"id":"lv_5_7","topic":"Nature and Environmental Protection","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"nhận nuôi hoặc áp dụng, tiếp nhận","defEn":"to legally take another person's child into your own family, or to start using a particular idea or method","examples":["The local council decided to [adopt] a new policy on recycling. (=Dịch: Hội đồng địa phương đã quyết định áp dụng một chính sách mới về tái chế.)","After years of waiting, the couple was finally able to [adopt] a child. (=Dịch: Sau nhiều năm chờ đợi, cặp vợ chồng cuối cùng cũng có thể nhận nuôi một đứa trẻ.)","Many schools now [adopt] modern technology in daily teaching. (=Dịch: Nhiều trường học hiện nay áp dụng công nghệ hiện đại vào việc giảng dạy hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_5_8","topic":"Nature and Environmental Protection","word":"african","pos":"(adj)","ipa":"/ˈæf.rɪ.kən/","defVi":"Thuộc về châu Phi, người châu Phi.","defEn":"Belonging or relating to Africa, its people, or its culture.","examples":["She enjoys listening to traditional [african] music and drumming. (=Dịch: Cô ấy thích nghe nhạc truyền thống và tiếng trống của châu Phi.)","The safari tour offered a rare chance to see [african] wildlife up close. (=Dịch: Chuyến tham quan dã ngoại mang lại cơ hội hiếm có để ngắm nhìn động vật hoang dã châu Phi ở cự ly gần.)","Many [african] nations are investing heavily in renewable energy. (=Dịch: Nhiều quốc gia châu Phi đang đầu tư mạnh mẽ vào năng lượng tái tạo.)"],"ukAudio":"/ai_services/tts3/?q=african&lang=en-GB&ipa=%2F%CB%88%C3%A6f.r%C9%AA.k%C9%99n%2F","usAudio":"/ai_services/tts3/?q=african&lang=en-US&ipa=%2F%CB%88%C3%A6f.r%C9%AA.k%C9%99n%2F"},{"id":"lv_5_9","topic":"Nature and Environmental Protection","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"tham vọng, đầy hoài bão","defEn":"having a strong desire for success, power, or achievement","examples":["The government launched an [ambitious] project to improve public transport. (=Dịch: Chính phủ đã phát động một dự án đầy tham vọng nhằm cải thiện giao thông công cộng.)","She is an [ambitious] young lawyer who hopes to make partner soon. (=Dịch: Cô ấy là một luật sư trẻ đầy tham vọng và hy vọng sớm trở thành thành viên góp vốn.)","His plans for the new business seemed overly [ambitious] given the budget. (=Dịch: Kế hoạch kinh doanh mới của anh ấy có vẻ quá tham vọng xét về ngân sách hiện có.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_5_10","topic":"Nature and Environmental Protection","word":"angle","pos":"(n)","ipa":"/ˈæŋ.ɡəl/","defVi":"góc, góc độ, quan điểm","defEn":"the space between two intersecting lines, or a particular way of looking at something","examples":["The photographer took the picture from a low [angle] to make the building look taller. (=Dịch: Nhiếp ảnh gia chụp bức ảnh từ góc thấp để làm cho tòa nhà trông cao hơn.)","We need to consider this problem from every possible [angle]. (=Dịch: Chúng ta cần xem xét vấn đề này từ mọi góc độ có thể.)","The journalist tried to find a fresh [angle] for her news story. (=Dịch: Nữ nhà báo đã cố gắng tìm một góc nhìn mới cho bài báo của mình.)"],"ukAudio":"/ai_services/tts3/?q=angle&lang=en-GB&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=angle&lang=en-US&ipa=%2F%CB%88%C3%A6%C5%8B.%C9%A1%C9%99l%2F"},{"id":"lv_5_11","topic":"Nature and Environmental Protection","word":"antarctic","pos":"(adj)","ipa":"/ænˈtɑːrk.tɪk/","defVi":"thuộc Nam Cực","defEn":"relating to the region around the South Pole","examples":["Scientists are studying climate change through [antarctic] ice cores. (=Dịch: Các nhà khoa học đang nghiên cứu biến đổi khí hậu thông qua các lõi băng Nam Cực.)","Penguins have adapted well to the harsh [antarctic] environment. (=Dịch: Chim cánh cụt đã thích nghi tốt với môi trường Nam Cực khắc nghiệt.)","The research team organized an [antarctic] expedition last summer. (=Dịch: Đội nghiên cứu đã tổ chức một chuyến thám hiểm Nam Cực vào mùa hè năm ngoái.)"],"ukAudio":"/ai_services/tts3/?q=antarctic&lang=en-GB&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=antarctic&lang=en-US&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AAk%2F"},{"id":"lv_5_12","topic":"Nature and Environmental Protection","word":"antarctica","pos":"(n)","ipa":"/ænˈtɑːrk.tɪ.kə/","defVi":"Châu Nam Cực","defEn":"the continent surrounding the South Pole, almost entirely covered with ice","examples":["Scientific research teams travel to [antarctica] to study climate change. (=Dịch: Các đội nghiên cứu khoa học tới Châu Nam Cực để nghiên cứu về biến đổi khí hậu.)","Extreme weather conditions make [antarctica] one of the most inhospitable places on Earth. (=Dịch: Điều kiện thời tiết khắc nghiệt khiến Châu Nam Cực trở thành một trong những nơi khó sống nhất trên Trái Đất.)","Emperor penguins are well adapted to survive the freezing winters of [antarctica]. (=Dịch: Chim cánh cụt hoàng đế thích nghi rất tốt để sống sót qua mùa đông băng giá ở Châu Nam Cực.)"],"ukAudio":"/ai_services/tts3/?q=antarctica&lang=en-GB&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AA.k%C9%99%2F","usAudio":"/ai_services/tts3/?q=antarctica&lang=en-US&ipa=%2F%C3%A6n%CB%88t%C9%91%CB%90rk.t%C9%AA.k%C9%99%2F"},{"id":"lv_5_13","topic":"Nature and Environmental Protection","word":"archaeology","pos":"(n)","ipa":"/ˌɑːr.kiˈɑː.lə.dʒi/","defVi":"Khảo cổ học","defEn":"The study of human history and prehistory through the excavation of sites and the analysis of artifacts","examples":["She decided to study [archaeology] because of her fascination with ancient Egypt. (=Dịch: Cô ấy quyết định học khảo cổ học vì niềm đam mê với Ai Cập cổ đại.)","Recent advances in [archaeology] have helped discover hidden ruins beneath the jungle. (=Dịch: Những tiến bộ gần đây trong khảo cổ học đã giúp phát hiện ra các tàn tích ẩn sâu dưới rừng rậm.)","The museum has an extensive collection of artifacts related to biblical [archaeology]. (=Dịch: Bảo tàng có một bộ sưu tập phong phú các hiện vật liên quan đến khảo cổ học kinh thánh.)"],"ukAudio":"/ai_services/tts3/?q=archaeology&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=archaeology&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.ki%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_5_14","topic":"Nature and Environmental Protection","word":"arctic","pos":"(adj)","ipa":"/ˈɑːrk.tɪk/","defVi":"(thuộc) Bắc Cực; giá rét, cực lạnh","defEn":"relating to the regions around the North Pole; extremely cold","examples":["Many species have adapted uniquely to the harsh conditions of the [arctic] environment. (=Dịch: Nhiều loài đã thích nghi độc đáo với các điều kiện khắc nghiệt của môi trường Bắc Cực.)","The expedition team had to endure fierce [arctic] winds and freezing temperatures. (=Dịch: Đội thám hiểm đã phải chịu đựng những cơn gió Bắc Cực dữ dội và nhiệt độ đóng băng.)","Melting [arctic] ice is one of the most alarming indicators of climate change. (=Dịch: Băng Bắc Cực tan chảy là một trong những chỉ báo đáng báo động nhất về biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=arctic&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90rk.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=arctic&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90rk.t%C9%AAk%2F"},{"id":"lv_5_15","topic":"Nature and Environmental Protection","word":"ash","pos":"(n)","ipa":"/æʃ/","defVi":"tro, tàn tro","defEn":"the soft grey powder that remains after something has burned","examples":["Volcanic [ash] covered the surrounding villages after the eruption. (=Dịch: Tro núi lửa đã bao phủ các ngôi làng xung quanh sau vụ phun trào.)","He tapped the cigarette [ash] into the tray on the table. (=Dịch: Anh ấy gõ tàn thuốc lá vào chiếc gạt tàn trên bàn.)","The forest fire left behind nothing but piles of black [ash]. (=Dịch: Vụ cháy rừng không để lại gì ngoài những đống tro đen.)"],"ukAudio":"/ai_services/tts3/?q=ash&lang=en-GB&ipa=%2F%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=ash&lang=en-US&ipa=%2F%C3%A6%CA%83%2F"},{"id":"lv_5_16","topic":"Nature and Environmental Protection","word":"ashore","pos":"(adv)","ipa":"/əˈʃɔːr/","defVi":"lên bờ, vào bờ","defEn":"towards or onto the land from an area of water","examples":["The rescued sailors finally stepped [ashore] after three days lost at sea. (=Dịch: Những thủy thủ được giải cứu cuối cùng đã bước lên bờ sau ba ngày lạc trên biển.)","Strong waves washed several unusual sea creatures [ashore] overnight. (=Dịch: Những con sóng mạnh đã cuốn trôi vài sinh vật biển kỳ lạ vào bờ qua đêm.)","The shipwreck survivors managed to swim [ashore] before darkness fell. (=Dịch: Những người sống sót sau vụ đắm tàu đã cố gắng bơi vào bờ trước khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=ashore&lang=en-GB&ipa=%2F%C9%99%CB%88%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=ashore&lang=en-US&ipa=%2F%C9%99%CB%88%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_17","topic":"Nature and Environmental Protection","word":"asian","pos":"(adj)","ipa":"/ˈeɪ.ʒən/","defVi":"thuộc châu Á, người châu Á","defEn":"belonging to or relating to Asia or its people","examples":["Many [asian] countries have experienced rapid economic growth in recent decades. (=Dịch: Nhiều quốc gia châu Á đã trải qua sự tăng trưởng kinh tế nhanh chóng trong những thập kỷ gần đây.)","She enjoys cooking various types of traditional [asian] cuisine. (=Dịch: Cô ấy thích nấu nhiều loại ẩm thực truyền thống châu Á.)","The university offers courses on modern [asian] history and literature. (=Dịch: Trường đại học cung cấp các khóa học về lịch sử và văn học châu Á hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=asian&lang=en-GB&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=asian&lang=en-US&ipa=%2F%CB%88e%C9%AA.%CA%92%C9%99n%2F"},{"id":"lv_5_18","topic":"Nature and Environmental Protection","word":"asiatic","pos":"(adj)","ipa":"/ˌeɪ.ʒiˈæt̬.ɪk/","defVi":"thuộc châu Á (thường dùng trong sinh học, lịch sử)","defEn":"of or relating to Asia, especially used in biological or historical contexts","examples":["The [asiatic] black bear is native to the forests of East Asia. (=Dịch: Gấu đen châu Á có nguồn gốc từ các khu rừng ở Đông Á.)","Several rare [asiatic] plant species are preserved in the botanical garden. (=Dịch: Một số loài thực vật châu Á quý hiếm được bảo tồn trong vườn thực vật.)","Scholars discussed the ancient [asiatic] trade routes during the symposium. (=Dịch: Các học giả đã thảo luận về các tuyến đường thương mại cổ đại ở châu Á trong buổi hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=asiatic&lang=en-GB&ipa=%2F%CB%8Ce%C9%AA.%CA%92i%CB%88%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=asiatic&lang=en-US&ipa=%2F%CB%8Ce%C9%AA.%CA%92i%CB%88%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_5_19","topic":"Nature and Environmental Protection","word":"assess","pos":"(v)","ipa":"/əˈsɛs/","defVi":"đánh giá, thẩm định","defEn":"to judge or evaluate the quality, value, or importance of something","examples":["The teacher will [assess] the students based on their final presentations. (=Dịch: Giáo viên sẽ đánh giá học sinh dựa trên bài thuyết trình cuối kỳ của họ.)","Insurance agents arrived to [assess] the flood damage to the property. (=Dịch: Các nhân viên bảo hiểm đã đến để đánh giá thiệt hại do lũ lụt gây ra cho tài sản.)","We need to carefully [assess] the potential risks before launching the product. (=Dịch: Chúng ta cần đánh giá cẩn thận các rủi ro tiềm ẩn trước khi tung sản phẩm ra thị trường.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F"},{"id":"lv_5_20","topic":"Nature and Environmental Protection","word":"assumption","pos":"(n)","ipa":"/əˈsʌmp.ʃən/","defVi":"giả định, sự cho là đúng","defEn":"something that you accept as true without having proof","examples":["His conclusion was based on the false [assumption] that prices would drop. (=Dịch: Kết luận của anh ấy dựa trên giả định sai lầm rằng giá cả sẽ giảm.)","It is a common [assumption] that older people are less adaptable to technology. (=Dịch: Có một giả định phổ biến rằng người lớn tuổi ít thích nghi với công nghệ hơn.)","We are working on the [assumption] that the project will receive funding. (=Dịch: Chúng tôi đang làm việc dựa trên giả định rằng dự án sẽ nhận được tài trợ.)"],"ukAudio":"/ai_services/tts3/?q=assumption&lang=en-GB&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=assumption&lang=en-US&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_5_21","topic":"Nature and Environmental Protection","word":"athlete","pos":"(n)","ipa":"/ˈæθ.liːt/","defVi":"vận động viên","defEn":"a person who is trained in or good at sports and physical exercise","examples":["The young [athlete] trained for years to qualify for the Olympic Games. (=Dịch: Vận động viên trẻ đã luyện tập nhiều năm để đủ điều kiện tham dự Thế vận hội.)","Good nutrition and sufficient rest are essential for every professional [athlete]. (=Dịch: Dinh dưỡng tốt và nghỉ ngơi đầy đủ là điều cần thiết đối với mọi vận động viên chuyên nghiệp.)","She was named the top student [athlete] of her university. (=Dịch: Cô ấy được vinh danh là sinh viên vận động viên xuất sắc nhất của trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=athlete&lang=en-GB&ipa=%2F%CB%88%C3%A6%CE%B8.li%CB%90t%2F","usAudio":"/ai_services/tts3/?q=athlete&lang=en-US&ipa=%2F%CB%88%C3%A6%CE%B8.li%CB%90t%2F"},{"id":"lv_5_22","topic":"Nature and Environmental Protection","word":"atlas","pos":"(n)","ipa":"/ˈæt.ləs/","defVi":"tập bản đồ","defEn":"a book of maps","examples":["The teacher asked the students to find the capital on the world [atlas]. (=Dịch: Giáo viên yêu cầu học sinh tìm thủ đô trên tập bản đồ thế giới.)","She bought an updated road [atlas] before embarking on her cross-country trip. (=Dịch: Cô ấy đã mua một tập bản đồ đường bộ cập nhật trước khi bắt đầu chuyến đi xuyên quốc gia.)","This historical [atlas] illustrates the border changes throughout the centuries. (=Dịch: Tập bản đồ lịch sử này minh họa những thay đổi biên giới qua nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=atlas&lang=en-GB&ipa=%2F%CB%88%C3%A6t.l%C9%99s%2F","usAudio":"/ai_services/tts3/?q=atlas&lang=en-US&ipa=%2F%CB%88%C3%A6t.l%C9%99s%2F"},{"id":"lv_5_23","topic":"Nature and Environmental Protection","word":"attach","pos":"(v)","ipa":"/əˈtætʃ/","defVi":"đính kèm, gắn vào, dán vào","defEn":"to join, fasten, or connect one thing to another","examples":["Please [attach] your resume to the email before sending it. (=Dịch: Vui lòng đính kèm sơ yếu lý lịch của bạn vào email trước khi gửi.)","You need to [attach] a label to each piece of luggage. (=Dịch: Bạn cần dán một chiếc nhãn vào từng kiện hành lý.)","They decided to [attach] the solar panel securely to the roof. (=Dịch: Họ quyết định gắn tấm pin năng lượng mặt trời một cách chắc chắn lên mái nhà.)"],"ukAudio":"/ai_services/tts3/?q=attach&lang=en-GB&ipa=%2F%C9%99%CB%88t%C3%A6t%CA%83%2F","usAudio":"/ai_services/tts3/?q=attach&lang=en-US&ipa=%2F%C9%99%CB%88t%C3%A6t%CA%83%2F"},{"id":"lv_5_24","topic":"Nature and Environmental Protection","word":"autonomous","pos":"(adj)","ipa":"/ɔːˈtɑː.nə.məs/","defVi":"tự trị, tự chủ","defEn":"able to govern itself or act independently","examples":["The region became an [autonomous] province with its own legal system. (=Dịch: Khu vực này đã trở thành một tỉnh tự trị với hệ thống pháp luật riêng.)","Many tech companies are investing heavily in [autonomous] vehicles. (=Dịch: Nhiều công ty công nghệ đang đầu tư mạnh mẽ vào các phương tiện tự hành.)","Students are encouraged to become more [autonomous] in their learning. (=Dịch: Học sinh được khuyến khích trở nên chủ động và tự lập hơn trong học tập.)"],"ukAudio":"/ai_services/tts3/?q=autonomous&lang=en-GB&ipa=%2F%C9%94%CB%90%CB%88t%C9%91%CB%90.n%C9%99.m%C9%99s%2F","usAudio":"/ai_services/tts3/?q=autonomous&lang=en-US&ipa=%2F%C9%94%CB%90%CB%88t%C9%91%CB%90.n%C9%99.m%C9%99s%2F"},{"id":"lv_5_25","topic":"Nature and Environmental Protection","word":"ban","pos":"(v)","ipa":"/bæn/","defVi":"cấm, ngăn cấm","defEn":"to officially forbid or prohibit something","examples":["Many countries have decided to [ban] single-use plastic bags. (=Dịch: Nhiều quốc gia đã quyết định cấm túi ni lông sử dụng một lần.)","The school decided to [ban] smartphones during class hours. (=Dịch: Nhà trường quyết định cấm điện thoại thông minh trong giờ học.)","The athlete was [banned] from competing for two years due to doping. (=Dịch: Vận động viên bị cấm thi đấu hai năm do sử dụng chất kích thích.)"],"ukAudio":"/ai_services/tts3/?q=ban&lang=en-GB&ipa=%2Fb%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=ban&lang=en-US&ipa=%2Fb%C3%A6n%2F"},{"id":"lv_5_26","topic":"Nature and Environmental Protection","word":"bark","pos":"(n)","ipa":"/bɑːrk/","defVi":"vỏ cây","defEn":"the tough outer covering of the trunk and branches of a tree","examples":["The rough [bark] of the oak tree protected it from harsh weather. (=Dịch: Lớp vỏ sần sùi của cây sồi đã bảo vệ nó khỏi thời tiết khắc nghiệt.)","Ancient people used tree [bark] to make paper and medicine. (=Dịch: Người cổ đại đã sử dụng vỏ cây để làm giấy và thuốc.)","Insects can often be found hiding beneath the [bark]. (=Dịch: Côn trùng thường được tìm thấy ẩn nấp dưới lớp vỏ cây.)"],"ukAudio":"/ai_services/tts3/?q=bark&lang=en-GB&ipa=%2Fb%C9%91%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=bark&lang=en-US&ipa=%2Fb%C9%91%CB%90rk%2F"},{"id":"lv_5_27","topic":"Nature and Environmental Protection","word":"bay","pos":"(n)","ipa":"/beɪ/","defVi":"vịnh","defEn":"a large area of water that is partially surrounded by land","examples":["Several fishing boats were anchored safely inside the [bay]. (=Dịch: Một vài chiếc thuyền đánh cá đã neo đậu an toàn bên trong vịnh.)","The hotel offers a stunning view of the blue [bay]. (=Dịch: Khách sạn mang đến tầm nhìn tuyệt đẹp ra vịnh biển trong xanh.)","Many species of marine birds breed around the quiet [bay]. (=Dịch: Nhiều loài chim biển sinh sản quanh vùng vịnh yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=bay&lang=en-GB&ipa=%2Fbe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=bay&lang=en-US&ipa=%2Fbe%C9%AA%2F"},{"id":"lv_5_28","topic":"Nature and Environmental Protection","word":"beauty","pos":"(n)","ipa":"/ˈbjuː.t̬i/","defVi":"vẻ đẹp, nét đẹp","defEn":"the quality of being pleasing, especially to look at","examples":["The natural [beauty] of the mountains attracted many tourists. (=Dịch: Vẻ đẹp tự nhiên của những ngọn núi đã thu hút rất nhiều khách du lịch.)","She appreciated the [beauty] of classical music from a young age. (=Dịch: Cô ấy đã biết thưởng thức vẻ đẹp của âm nhạc cổ điển từ khi còn nhỏ.)","The [beauty] of this plan is its absolute simplicity. (=Dịch: Điểm hay của kế hoạch này chính là sự đơn giản tuyệt đối của nó.)"],"ukAudio":"/ai_services/tts3/?q=beauty&lang=en-GB&ipa=%2F%CB%88bju%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=beauty&lang=en-US&ipa=%2F%CB%88bju%CB%90.t%CC%ACi%2F"},{"id":"lv_5_29","topic":"Nature and Environmental Protection","word":"beetle","pos":"(n)","ipa":"/ˈbi.t̬əl/","defVi":"bọ cánh cứng","defEn":"an insect with hard front wings that cover and protect its soft flying wings","examples":["The bright green [beetle] crawled slowly across the fallen oak leaves. (=Dịch: Con bọ cánh cứng màu xanh lá sáng bò chầm chậm qua những chiếc lá sồi rụng.)","Certain species of [beetle] can cause severe damage to commercial pine forests. (=Dịch: Một số loài bọ cánh cứng nhất định có thể gây ra thiệt hại nghiêm trọng cho các cánh rừng thông thương mại.)","The young boy kept a harmless stag [beetle] in a glass jar to observe it. (=Dịch: Cậu bé nuôi một con bọ kẹp kìm vô hại trong lọ thủy tinh để quan sát.)"],"ukAudio":"/ai_services/tts3/?q=beetle&lang=en-GB&ipa=%2F%CB%88bi.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=beetle&lang=en-US&ipa=%2F%CB%88bi.t%CC%AC%C9%99l%2F"},{"id":"lv_5_30","topic":"Nature and Environmental Protection","word":"bell","pos":"(n)","ipa":"/bel/","defVi":"cái chuông","defEn":"a hollow metal object that makes a ringing sound when struck","examples":["The church [bell] rang across the quiet village every Sunday morning. (=Dịch: Tiếng chuông nhà thờ vang vọng khắp ngôi làng yên tĩnh vào mỗi sáng Chủ nhật.)","Students packed their bags as soon as they heard the school [bell]. (=Dịch: Học sinh thu dọn cặp sách ngay khi nghe thấy tiếng chuông trường học reo.)","He pressed the front door [bell] and waited for someone to answer. (=Dịch: Anh ấy bấm chuông cửa trước và đợi người ra mở.)"],"ukAudio":"/ai_services/tts3/?q=bell&lang=en-GB&ipa=%2Fbel%2F","usAudio":"/ai_services/tts3/?q=bell&lang=en-US&ipa=%2Fbel%2F"},{"id":"lv_5_31","topic":"Nature and Environmental Protection","word":"billion","pos":"(n)","ipa":"/ˈbɪl.jən/","defVi":"tỷ (1.000.000.000)","defEn":"the number 1,000,000,000","examples":["The world population has exceeded eight [billion] people. (=Dịch: Dân số thế giới đã vượt quá tám tỷ người.)","The government plans to spend a [billion] dollars on infrastructure. (=Dịch: Chính phủ dự kiến chi một tỷ đô la cho cơ sở hạ tầng.)","Scientists estimate that the galaxy contains over one hundred [billion] stars. (=Dịch: Các nhà khoa học ước tính rằng thiên hà chứa hơn một trăm tỷ ngôi sao.)"],"ukAudio":"/ai_services/tts3/?q=billion&lang=en-GB&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F","usAudio":"/ai_services/tts3/?q=billion&lang=en-US&ipa=%2F%CB%88b%C9%AAl.j%C9%99n%2F"},{"id":"lv_5_32","topic":"Nature and Environmental Protection","word":"biodiversity","pos":"(n)","ipa":"/ˌbaɪ.oʊ.daɪˈvɜr.sə.t̬i/","defVi":"sự đa dạng sinh học","defEn":"the variety of plant and animal life in a particular habitat or in the world","examples":["Deforestation in the Amazon poses a serious threat to global [biodiversity]. (=Dịch: Nạn phá rừng ở Amazon đặt ra mối đe dọa nghiêm trọng đối với sự đa dạng sinh học toàn cầu.)","National parks are established to preserve the rich [biodiversity] of the region. (=Dịch: Các vườn quốc gia được thành lập để bảo tồn sự đa dạng sinh học phong phú của khu vực.)","The loss of marine [biodiversity] directly affects the livelihood of coastal communities. (=Dịch: Sự suy giảm đa dạng sinh học biển ảnh hưởng trực tiếp đến sinh kế của các cộng đồng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=biodiversity&lang=en-GB&ipa=%2F%CB%8Cba%C9%AA.o%CA%8A.da%C9%AA%CB%88v%C9%9Cr.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=biodiversity&lang=en-US&ipa=%2F%CB%8Cba%C9%AA.o%CA%8A.da%C9%AA%CB%88v%C9%9Cr.s%C9%99.t%CC%ACi%2F"},{"id":"lv_5_33","topic":"Nature and Environmental Protection","word":"biofuel","pos":"(n)","ipa":"/ˈbaɪ.oʊˌfjuː.əl/","defVi":"Nhiên liệu sinh học","defEn":"Fuel produced directly or indirectly from organic material such as plants and animal waste","examples":["Many countries are investing in [biofuel] to reduce their dependence on fossil fuels. (=Dịch: Nhiều quốc gia đang đầu tư vào nhiên liệu sinh học để giảm sự phụ thuộc vào nhiên liệu hóa thạch.)","Using [biofuel] can significantly lower greenhouse gas emissions from vehicles. (=Dịch: Sử dụng nhiên liệu sinh học có thể làm giảm đáng kể lượng khí thải nhà kính từ các phương tiện giao thông.)","The factory uses corn-based [biofuel] to power some of its heavy machinery. (=Dịch: Nhà máy sử dụng nhiên liệu sinh học làm từ ngô để vận hành một số máy móc hạng nặng.)"],"ukAudio":"/ai_services/tts3/?q=biofuel&lang=en-GB&ipa=%2F%CB%88ba%C9%AA.o%CA%8A%CB%8Cfju%CB%90.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=biofuel&lang=en-US&ipa=%2F%CB%88ba%C9%AA.o%CA%8A%CB%8Cfju%CB%90.%C9%99l%2F"},{"id":"lv_5_34","topic":"Nature and Environmental Protection","word":"biologist","pos":"(n)","ipa":"/baɪˈɑː.lə.dʒɪst/","defVi":"nhà sinh học","defEn":"a scientist who studies living organisms and life processes","examples":["The marine [biologist] studied the behavior of coral reefs in warm waters. (=Dịch: Nhà sinh học biển đã nghiên cứu tập tính của các rạn san hô ở vùng nước ấm.)","A team of [biologists] discovered a new species of frog in the rainforest. (=Dịch: Một nhóm các nhà sinh học đã phát hiện ra một loài ếch mới trong rừng nhiệt đới.)","As a [biologist], she is passionate about wildlife conservation. (=Dịch: Là một nhà sinh học, cô ấy rất tâm huyết với việc bảo tồn động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=biologist&lang=en-GB&ipa=%2Fba%C9%AA%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=biologist&lang=en-US&ipa=%2Fba%C9%AA%CB%88%C9%91%CB%90.l%C9%99.d%CA%92%C9%AAst%2F"},{"id":"lv_5_35","topic":"Nature and Environmental Protection","word":"bizarre","pos":"(adj)","ipa":"/bɪˈzɑːr/","defVi":"kỳ quái, kỳ lạ","defEn":"very strange or unusual","examples":["The movie had a [bizarre] plot that confused most of the audience. (=Dịch: Bộ phim có một cốt truyện kỳ quái khiến hầu hết khán giả bối rối.)","She had a [bizarre] dream about flying fish last night. (=Dịch: Đêm qua cô ấy đã có một giấc mơ kỳ lạ về những con cá bay.)","He showed up to the formal party wearing [bizarre] clothes. (=Dịch: Anh ấy xuất hiện tại bữa tiệc trang trọng với bộ trang phục kỳ quặc.)"],"ukAudio":"/ai_services/tts3/?q=bizarre&lang=en-GB&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=bizarre&lang=en-US&ipa=%2Fb%C9%AA%CB%88z%C9%91%CB%90r%2F"},{"id":"lv_5_36","topic":"Nature and Environmental Protection","word":"blackbird","pos":"(n)","ipa":"/ˈblæk.bɝːd/","defVi":"chim hoét đen (chim sáo đá đen)","defEn":"a common bird, of which the male has black feathers and a bright yellow beak","examples":["A male [blackbird] was singing sweetly from the top of the oak tree. (=Dịch: Một chú chim hoét đen trống đang hót véo von trên ngọn cây sồi.)","We watched a [blackbird] search for worms on the damp lawn. (=Dịch: Chúng tôi nhìn một con chim hoét đen đang tìm giun trên bãi cỏ ẩm ướt.)","The [blackbird] built its nest in the thick bushes near the garden wall. (=Dịch: Con chim hoét đen đã làm tổ trong bụi rậm gần bức tường vườn.)"],"ukAudio":"/ai_services/tts3/?q=blackbird&lang=en-GB&ipa=%2F%CB%88bl%C3%A6k.b%C9%9D%CB%90d%2F","usAudio":"/ai_services/tts3/?q=blackbird&lang=en-US&ipa=%2F%CB%88bl%C3%A6k.b%C9%9D%CB%90d%2F"},{"id":"lv_5_37","topic":"Nature and Environmental Protection","word":"boost","pos":"(n)","ipa":"/bust/","defVi":"Sự gia tăng, sự thúc đẩy, sự nâng cao.","defEn":"An increase or improvement, or an act that helps something improve.","examples":["The tax cuts provided a significant [boost] to the economy. (=Dịch: Việc cắt giảm thuế đã đem lại sự thúc đẩy đáng kể cho nền kinh tế.)","Winning the competition gave her confidence a huge [boost]. (=Dịch: Chiến thắng trong cuộc thi đã gia tăng sự tự tin cho cô ấy rất nhiều.)","A warm cup of coffee gives me the morning [boost] I need. (=Dịch: Một tách cà phê nóng cho tôi nguồn năng lượng cần thiết vào buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=boost&lang=en-GB&ipa=%2Fbust%2F","usAudio":"/ai_services/tts3/?q=boost&lang=en-US&ipa=%2Fbust%2F"},{"id":"lv_5_38","topic":"Nature and Environmental Protection","word":"bottled","pos":"(adj)","ipa":"/ˈbɑː.təld/","defVi":"được đóng chai","defEn":"stored and sold in bottles","examples":["Tourists are advised to drink [bottled] water to avoid stomach illnesses. (=Dịch: Khách du lịch được khuyên nên uống nước đóng chai để tránh các bệnh về đường tiêu hóa.)","The company produces high-quality [bottled] olive oil for export. (=Dịch: Công ty sản xuất dầu ô liu đóng chai chất lượng cao để xuất khẩu.)","Reducing the consumption of [bottled] beverages helps cut down on plastic waste. (=Dịch: Giảm tiêu thụ đồ uống đóng chai giúp cắt giảm rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=bottled&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.t%C9%99ld%2F","usAudio":"/ai_services/tts3/?q=bottled&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.t%C9%99ld%2F"},{"id":"lv_5_39","topic":"Nature and Environmental Protection","word":"brazil","pos":"(n)","ipa":"/brəˈzɪl/","defVi":"Nước Brasil (Bra-xin)","defEn":"A large country in South America, officially known as the Federative Republic of Brazil","examples":["The Amazon rainforest covers a substantial part of [brazil]. (=Dịch: Rừng mưa Amazon bao phủ một phần đáng kể của nước Brasil.)","Coffee production is a major contributor to the economy of [brazil]. (=Dịch: Sản xuất cà phê là một ngành đóng góp lớn cho nền kinh tế Brasil.)","Many tourists travel to [brazil] every year to experience the vibrant Carnival festival. (=Dịch: Nhiều du khách đến Brasil hàng năm để trải nghiệm lễ hội Carnival sôi động.)"],"ukAudio":"/ai_services/tts3/?q=brazil&lang=en-GB&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=brazil&lang=en-US&ipa=%2Fbr%C9%99%CB%88z%C9%AAl%2F"},{"id":"lv_5_40","topic":"Nature and Environmental Protection","word":"breakwater","pos":"(n)","ipa":"/ˈbreɪkˌwɔː.t̬ɚ/","defVi":"đê chắn sóng","defEn":"a strong barrier built into the sea to protect a coast or harbor from the force of waves","examples":["The harbor is protected from rough seas by a concrete [breakwater]. (=Dịch: Bến cảng được bảo vệ khỏi biển động nhờ một con đê chắn sóng bằng bê tông.)","Fishermen often stand along the [breakwater] to catch fish. (=Dịch: Các ngư dân thường đứng dọc theo đê chắn sóng để câu cá.)","The city council decided to repair the damaged [breakwater] before the storm season. (=Dịch: Hội đồng thành phố đã quyết định sửa chữa đoạn đê chắn sóng bị hư hỏng trước mùa bão.)"],"ukAudio":"/ai_services/tts3/?q=breakwater&lang=en-GB&ipa=%2F%CB%88bre%C9%AAk%CB%8Cw%C9%94%CB%90.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=breakwater&lang=en-US&ipa=%2F%CB%88bre%C9%AAk%CB%8Cw%C9%94%CB%90.t%CC%AC%C9%9A%2F"},{"id":"lv_5_41","topic":"Nature and Environmental Protection","word":"breathe","pos":"(v)","ipa":"/briːð/","defVi":"thở, hít thở","defEn":"to take air into the lungs and expel it","examples":["Take a deep breath and try to [breathe] slowly to stay calm. (=Dịch: Hãy hít một hơi thật sâu và cố gắng thở chậm lại để giữ bình tĩnh.)","It was difficult to [breathe] at high altitudes due to the thin air. (=Dịch: Rất khó để thở ở độ cao lớn do không khí loãng.)","The doctor listened carefully as the patient began to [breathe] in and out. (=Dịch: Bác sĩ lắng nghe chăm chú khi bệnh nhân bắt đầu hít vào và thở ra.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2Fbri%CB%90%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2Fbri%CB%90%C3%B0%2F"},{"id":"lv_5_42","topic":"Nature and Environmental Protection","word":"bucket","pos":"(n)","ipa":"/ˈbʌk.ɪt/","defVi":"cái xô, thùng","defEn":"an open container with a handle, used for carrying liquids or other materials","examples":["He filled the plastic [bucket] with warm water to wash the car. (=Dịch: Anh ấy đổ đầy nước ấm vào chiếc xô nhựa để rửa xe.)","Children were playing on the beach with a [bucket] and spade. (=Dịch: Lũ trẻ đang chơi đùa trên bãi biển với một chiếc xô và cái xẻng.)","We placed a large [bucket] under the leaking pipe to catch the drips. (=Dịch: Chúng tôi đặt một chiếc xô lớn dưới đường ống bị rò rỉ để hứng nước nhỏ giọt.)"],"ukAudio":"/ai_services/tts3/?q=bucket&lang=en-GB&ipa=%2F%CB%88b%CA%8Ck.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bucket&lang=en-US&ipa=%2F%CB%88b%CA%8Ck.%C9%AAt%2F"},{"id":"lv_5_43","topic":"Nature and Environmental Protection","word":"bury","pos":"(v)","ipa":"/ˈber.i/","defVi":"Chôn cất, chôn vùi, che giấu","defEn":"To place a dead body or an object in the ground and cover it with earth.","examples":["Pirates used to [bury] their gold treasure on remote islands. (=Dịch: Những tên cướp biển từng chôn giấu kho báu vàng của chúng trên các hòn đảo xa xôi.)","The family gathered to [bury] their beloved grandfather. (=Dịch: Gia đình đã tụ họp để chôn cất người ông kính yêu của họ.)","A heavy avalanche threatened to [bury] the small mountain village. (=Dịch: Một trận lở tuyết dữ dội đe dọa chôn vùi ngôi làng nhỏ trên núi.)"],"ukAudio":"/ai_services/tts3/?q=bury&lang=en-GB&ipa=%2F%CB%88ber.i%2F","usAudio":"/ai_services/tts3/?q=bury&lang=en-US&ipa=%2F%CB%88ber.i%2F"},{"id":"lv_5_44","topic":"Nature and Environmental Protection","word":"butterfly","pos":"(n)","ipa":"/ˈbʌt̬.ɚ.flaɪ/","defVi":"Con bướm","defEn":"An insect with four large, typically brightly colored wings that develops from a caterpillar","examples":["A colorful [butterfly] landed gently on the blooming rose. (=Dịch: Một con bướm rực rỡ sắc màu nhẹ nhàng đậu lên bông hoa hồng đang nở.)","Children in the garden enjoyed watching the [butterfly] flutter from flower to flower. (=Dịch: Những đứa trẻ trong vườn thích thú ngắm nhìn chú bướm dập dờn từ bông hoa này sang bông hoa khác.)","The caterpillar undergoes a complete transformation before emerging as a [butterfly]. (=Dịch: Sâu bướm trải qua một quá trình biến thái hoàn toàn trước khi trở thành một con bướm.)"],"ukAudio":"/ai_services/tts3/?q=butterfly&lang=en-GB&ipa=%2F%CB%88b%CA%8Ct%CC%AC.%C9%9A.fla%C9%AA%2F","usAudio":"/ai_services/tts3/?q=butterfly&lang=en-US&ipa=%2F%CB%88b%CA%8Ct%CC%AC.%C9%9A.fla%C9%AA%2F"},{"id":"lv_5_45","topic":"Nature and Environmental Protection","word":"cage","pos":"(n)","ipa":"/keɪdʒ/","defVi":"lồng, chuồng","defEn":"a structure of bars or wires in which birds or other animals are kept","examples":["The parrot flew around inside its large [cage]. (=Dịch: Con vẹt bay lượn xung quanh bên trong chiếc lồng lớn của nó.)","Zookeepers cleaned the lion's [cage] early in the morning. (=Dịch: Các nhân viên vườn thú đã dọn dẹp chuồng sư tử từ sáng sớm.)","He felt trapped in his office cubicle, like a bird in a [cage]. (=Dịch: Anh cảm thấy bị mắc kẹt trong góc làm việc của mình, như một chú chim trong lồng.)"],"ukAudio":"/ai_services/tts3/?q=cage&lang=en-GB&ipa=%2Fke%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=cage&lang=en-US&ipa=%2Fke%C9%AAd%CA%92%2F"},{"id":"lv_5_46","topic":"Nature and Environmental Protection","word":"cane","pos":"(n)","ipa":"/keɪn/","defVi":"cây mía, cây gậy chống","defEn":"the hollow stem of tall grasses like sugar cane, or a stick used to assist walking","examples":["Sugar [cane] is grown extensively in tropical climates for sugar production. (=Dịch: Cây mía được trồng rộng rãi ở các vùng khí hậu nhiệt đới để sản xuất đường.)","The elderly gentleman walked slowly down the street with the help of a wooden [cane]. (=Dịch: Cụ ông bước đi chậm rãi trên phố với sự trợ giúp của một chiếc gậy chống bằng gỗ.)","Furniture made from woven [cane] has become very popular again. (=Dịch: Đồ nội thất làm từ mây tre đan đã trở nên rất phổ biến trở lại.)"],"ukAudio":"/ai_services/tts3/?q=cane&lang=en-GB&ipa=%2Fke%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=cane&lang=en-US&ipa=%2Fke%C9%AAn%2F"},{"id":"lv_5_47","topic":"Nature and Environmental Protection","word":"canola","pos":"(n)","ipa":"/kəˈnoʊ.lə/","defVi":"Cây hạt cải dầu (dùng ép dầu)","defEn":"A type of oilseed rape plant grown for its edible oil and animal feed","examples":["The golden fields of [canola] look breathtaking during early summer. (=Dịch: Những cánh đồng hạt cải dầu vàng rực trông đẹp ngoạn mục vào đầu mùa hè.)","She prefers to cook with [canola] oil because it is low in saturated fat. (=Dịch: Cô ấy thích nấu ăn bằng dầu hạt cải vì nó chứa ít chất béo bão hòa.)","Canada is one of the world's largest producers and exporters of [canola]. (=Dịch: Canada là một trong những quốc gia sản xuất và xuất khẩu hạt cải dầu lớn nhất thế giới.)"],"ukAudio":"/ai_services/tts3/?q=canola&lang=en-GB&ipa=%2Fk%C9%99%CB%88no%CA%8A.l%C9%99%2F","usAudio":"/ai_services/tts3/?q=canola&lang=en-US&ipa=%2Fk%C9%99%CB%88no%CA%8A.l%C9%99%2F"},{"id":"lv_5_48","topic":"Nature and Environmental Protection","word":"cap","pos":"(n)","ipa":"/kæp/","defVi":"mũ lưỡi trai; nắp đậy","defEn":"a soft, flat hat with a curved peak at the front, or a protective lid/cover","examples":["He wore a baseball [cap] to shield his eyes from the strong sunlight. (=Dịch: Anh ấy đội một chiếc mũ lưỡi trai để che mắt khỏi ánh nắng gắt.)","Make sure you screw the [cap] tightly back onto the bottle. (=Dịch: Hãy chắc chắn rằng bạn đã vặn chặt nắp trở lại chai.)","The government introduced a [cap] on university tuition fees this year. (=Dịch: Chính phủ đã đưa ra mức trần giới hạn về học phí đại học trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=cap&lang=en-GB&ipa=%2Fk%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=cap&lang=en-US&ipa=%2Fk%C3%A6p%2F"},{"id":"lv_5_49","topic":"Nature and Environmental Protection","word":"cargo","pos":"(n)","ipa":"/ˈkɑːr.ɡoʊ/","defVi":"hàng hóa (chở trên tàu bè, máy bay, xe tải)","defEn":"goods carried on a ship, aircraft, or motor vehicle","examples":["The container ship was carrying valuable [cargo] across the Pacific Ocean. (=Dịch: Tàu container đang chở hàng hóa có giá trị băng qua Thái Bình Dương.)","Workers carefully unloaded the fragile [cargo] from the plane. (=Dịch: Các công nhân đã cẩn thận dỡ kiện hàng dễ vỡ khỏi máy bay.)","The truck lost its [cargo] of timber during the accident. (=Dịch: Chiếc xe tải bị rơi toàn bộ số hàng gỗ trong vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=cargo&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.%C9%A1o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=cargo&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.%C9%A1o%CA%8A%2F"},{"id":"lv_5_50","topic":"Nature and Environmental Protection","word":"category","pos":"(n)","ipa":"/ˈkæt̬.ə.ɡɔːr.i/","defVi":"Hạng mục, loại, danh mục","defEn":"A group of people or things that are similar and have the same features.","examples":["The books in the library are organized by [category]. (=Dịch: Sách trong thư viện được sắp xếp theo từng thể loại.)","She won an award in the best young artist [category]. (=Dịch: Cô ấy đã giành được giải thưởng ở hạng mục nghệ sĩ trẻ xuất sắc nhất.)","These expenses fall under the general [category] of travel costs. (=Dịch: Những khoản chi này thuộc danh mục chi phí đi lại nói chung.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_5_51","topic":"Nature and Environmental Protection","word":"cattle","pos":"(n)","ipa":"/ˈkæt̬.əl/","defVi":"gia súc, đàn bò","defEn":"large domesticated animals with horns and hoofs, kept for meat or milk (cows and bulls)","examples":["The farmer raises dairy [cattle] to supply fresh milk to the local town. (=Dịch: Người nông dân nuôi bò sữa để cung cấp sữa tươi cho thị trấn địa phương.)","Large herds of [cattle] graze peacefully in the open pasture. (=Dịch: Những đàn gia súc lớn thong thả gặm cỏ trên đồng cỏ rộng mở.)","Deforestation in the area is mainly driven by the need for [cattle] ranches. (=Dịch: Nạn phá rừng ở khu vực này chủ yếu do nhu cầu mở rộng các trang trại chăn nuôi gia súc.)"],"ukAudio":"/ai_services/tts3/?q=cattle&lang=en-GB&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cattle&lang=en-US&ipa=%2F%CB%88k%C3%A6t%CC%AC.%C9%99l%2F"},{"id":"lv_5_52","topic":"Nature and Environmental Protection","word":"census","pos":"(n)","ipa":"/ˈsen.səs/","defVi":"cuộc điều tra dân số","defEn":"an official count or survey of a population, typically recording various details of individuals","examples":["The government conducts a national [census] every ten years. (=Dịch: Chính phủ tiến hành một cuộc điều tra dân số toàn quốc mười năm một lần.)","According to the latest [census], the city's population has doubled. (=Dịch: Theo cuộc điều tra dân số mới nhất, dân số thành phố đã tăng gấp đôi.)","The [census] data helps urban planners allocate public resources effectively. (=Dịch: Dữ liệu điều tra dân số giúp các nhà quy hoạch đô thị phân bổ nguồn lực công hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=census&lang=en-GB&ipa=%2F%CB%88sen.s%C9%99s%2F","usAudio":"/ai_services/tts3/?q=census&lang=en-US&ipa=%2F%CB%88sen.s%C9%99s%2F"},{"id":"lv_5_53","topic":"Nature and Environmental Protection","word":"centimetre","pos":"(n)","ipa":"/ˈsɛn.təˌmi.tər/","defVi":"xăng-ti-mét (đơn vị đo chiều dài)","defEn":"a metric unit of length equal to one hundredth of a metre","examples":["The seedling grew nearly one [centimetre] overnight. (=Dịch: Cây con đã phát triển thêm gần một xăng-ti-mét chỉ sau một đêm.)","Please cut the fabric five [centimetres] longer than the measurement. (=Dịch: Vui lòng cắt mảnh vải dài hơn kích thước đo năm xăng-ti-mét.)","The water level rose by several [centimetres] after the heavy downpour. (=Dịch: Mực nước đã dâng lên vài xăng-ti-mét sau trận mưa rào lớn.)"],"ukAudio":"/ai_services/tts3/?q=centimetre&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.t%C9%99%CB%8Cmi.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=centimetre&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.t%C9%99%CB%8Cmi.t%C9%99r%2F"},{"id":"lv_5_54","topic":"Nature and Environmental Protection","word":"classify","pos":"(v)","ipa":"/ˈklæs.ə.faɪ/","defVi":"phân loại, xếp loại","defEn":"to arrange people or things into groups based on shared qualities or characteristics","examples":["Biologists [classify] living organisms into different species and kingdoms. (=Dịch: Các nhà sinh học phân loại các sinh vật sống thành các loài và giới khác nhau.)","Librarians use a specialized system to [classify] thousands of new books. (=Dịch: Các thủ thư sử dụng một hệ thống chuyên dụng để phân loại hàng nghìn cuốn sách mới.)","The government decided to [classify] the official report as top secret. (=Dịch: Chính phủ đã quyết định phân loại báo cáo chính thức này là tuyệt mật.)"],"ukAudio":"/ai_services/tts3/?q=classify&lang=en-GB&ipa=%2F%CB%88kl%C3%A6s.%C9%99.fa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=classify&lang=en-US&ipa=%2F%CB%88kl%C3%A6s.%C9%99.fa%C9%AA%2F"},{"id":"lv_5_55","topic":"Nature and Environmental Protection","word":"claw","pos":"(n)","ipa":"/klɔː/","defVi":"móng vuốt (của động vật, chim), càng (cua, tôm)","defEn":"a sharp curved pointed nail on the foot of an animal or bird","examples":["The eagle used its sharp [claw] to catch a fish from the river. (=Dịch: Con đại bàng đã sử dụng chiếc móng vuốt sắc nhọn của mình để bắt một con cá dưới sông.)","The cat sharpened every [claw] against the wooden furniture in the living room. (=Dịch: Con mèo cào từng chiếc móng vuốt sắc lẹm vào đồ nội thất bằng gỗ trong phòng khách.)","Crabs can defend themselves against predators by pinching with a powerful [claw]. (=Dịch: Cua có thể tự vệ trước những kẻ săn mồi bằng cách kẹp bằng chiếc càng khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=claw&lang=en-GB&ipa=%2Fkl%C9%94%CB%90%2F","usAudio":"/ai_services/tts3/?q=claw&lang=en-US&ipa=%2Fkl%C9%94%CB%90%2F"},{"id":"lv_5_56","topic":"Nature and Environmental Protection","word":"cliff","pos":"(n)","ipa":"/klɪf/","defVi":"vách đá dốc","defEn":"a high, steep area of rock or earth, especially at the edge of the sea","examples":["The lighthouse stands on the edge of a dangerous [cliff]. (=Dịch: Ngọn hải đăng đứng trên rìa của một vách đá nguy hiểm.)","They stood on the [cliff] and watched the waves crash below. (=Dịch: Họ đứng trên vách đá và ngắm những con sóng vỗ bên dưới.)","Nesting seabirds often build their homes on steep [cliff] faces. (=Dịch: Những loài chim biển làm tổ thường xây tổ trên các mặt vách đá dốc.)"],"ukAudio":"/ai_services/tts3/?q=cliff&lang=en-GB&ipa=%2Fkl%C9%AAf%2F","usAudio":"/ai_services/tts3/?q=cliff&lang=en-US&ipa=%2Fkl%C9%AAf%2F"},{"id":"lv_5_57","topic":"Nature and Environmental Protection","word":"clip","pos":"(n)","ipa":"/klɪp/","defVi":"cái kẹp; đoạn phim/ghi âm ngắn","defEn":"a small device used to hold things together, or a short extract from a film or recording","examples":["She used a paper [clip] to keep the receipts organized. (=Dịch: Cô ấy đã dùng một chiếc kẹp giấy để sắp xếp các hóa đơn gọn gàng.)","The teacher showed a short video [clip] about marine life. (=Dịch: Giáo viên đã chiếu một đoạn video ngắn về sinh vật biển.)","He secured the microphone to his shirt with a small [clip]. (=Dịch: Anh ấy cố định chiếc micrô vào áo bằng một chiếc kẹp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=clip&lang=en-GB&ipa=%2Fkl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=clip&lang=en-US&ipa=%2Fkl%C9%AAp%2F"},{"id":"lv_5_58","topic":"Nature and Environmental Protection","word":"cloth","pos":"(n)","ipa":"/klɔθ/","defVi":"vải, khăn lau","defEn":"material made by weaving cotton, wool, or other fibres, used for making clothes or cleaning","examples":["He grabbed a damp [cloth] to clean the kitchen counter. (=Dịch: Anh ấy lấy một miếng vải ẩm để lau quầy bếp.)","The shirt is made from high-quality cotton [cloth]. (=Dịch: Chiếc áo sơ mi này được làm từ vải cotton chất lượng cao.)","Wrap the delicate vase in a soft [cloth] before packing it. (=Dịch: Hãy bọc chiếc bình hoa dễ vỡ trong một tấm vải mềm trước khi đóng gói.)"],"ukAudio":"/ai_services/tts3/?q=cloth&lang=en-GB&ipa=%2Fkl%C9%94%CE%B8%2F","usAudio":"/ai_services/tts3/?q=cloth&lang=en-US&ipa=%2Fkl%C9%94%CE%B8%2F"},{"id":"lv_5_59","topic":"Nature and Environmental Protection","word":"coal","pos":"(n)","ipa":"/koʊl/","defVi":"Than đá","defEn":"A hard, black mineral extracted from the earth and burned as fuel to generate heat or electricity","examples":["The power station burns tonnes of [coal] every day to generate electricity. (=Dịch: Nhà máy điện đốt hàng tấn than đá mỗi ngày để phát điện.)","Miners spend long hours underground extracting [coal] from deep seams. (=Dịch: Các công nhân mỏ dành nhiều giờ dưới lòng đất để khai thác than đá từ các vỉa sâu.)","Renewable energy sources are gradually replacing [coal] around the world. (=Dịch: Các nguồn năng lượng tái tạo đang dần thay thế than đá trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=coal&lang=en-GB&ipa=%2Fko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=coal&lang=en-US&ipa=%2Fko%CA%8Al%2F"},{"id":"lv_5_60","topic":"Nature and Environmental Protection","word":"coastal","pos":"(adj)","ipa":"/ˈkoʊ.stəl/","defVi":"thuộc miền ven biển, duyên hải","defEn":"located on or near a coast","examples":["Rising sea levels pose a severe danger to [coastal] communities. (=Dịch: Mực nước biển dâng cao gây ra mối nguy hiểm nghiêm trọng cho các cộng đồng ven biển.)","We enjoyed driving along the scenic [coastal] road. (=Dịch: Chúng tôi rất thích lái xe dọc theo con đường ven biển tuyệt đẹp.)","Fishing is the primary source of income for many [coastal] villages. (=Dịch: Đánh bắt cá là nguồn thu nhập chính của nhiều làng chài ven biển.)"],"ukAudio":"/ai_services/tts3/?q=coastal&lang=en-GB&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F","usAudio":"/ai_services/tts3/?q=coastal&lang=en-US&ipa=%2F%CB%88ko%CA%8A.st%C9%99l%2F"},{"id":"lv_5_61","topic":"Nature and Environmental Protection","word":"cod","pos":"(n)","ipa":"/kɑːd/","defVi":"cá tuyết","defEn":"a large sea fish that is commonly eaten as food","examples":["Traditional fish and chips are often made with Atlantic [cod]. (=Dịch: Món cá và khoai tây chiên truyền thống thường được làm từ cá tuyết Đại Tây Dương.)","Strict quotas were introduced to protect the declining [cod] population. (=Dịch: Các hạn ngạch nghiêm ngặt đã được áp dụng nhằm bảo vệ quần thể cá tuyết đang suy giảm.)","The local fishermen caught several large [cod] during their trip. (=Dịch: Các ngư dân địa phương đã bắt được một vài con cá tuyết lớn trong chuyến đi của họ.)"],"ukAudio":"/ai_services/tts3/?q=cod&lang=en-GB&ipa=%2Fk%C9%91%CB%90d%2F","usAudio":"/ai_services/tts3/?q=cod&lang=en-US&ipa=%2Fk%C9%91%CB%90d%2F"},{"id":"lv_5_62","topic":"Nature and Environmental Protection","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑːɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with mental processes of understanding, learning, and remembering","examples":["Reading regularly helps to enhance children's [cognitive] development. (=Dịch: Đọc sách thường xuyên giúp tăng cường sự phát triển nhận thức của trẻ em.)","Scientists study how sleep deprivation affects [cognitive] functions. (=Dịch: Các nhà khoa học nghiên cứu xem việc thiếu ngủ ảnh hưởng như thế nào đến các chức năng nhận thức.)","Puzzles and memory games are great for maintaining [cognitive] abilities in old age. (=Dịch: Trò chơi giải đố và ghi nhớ rất tuyệt vời để duy trì khả năng nhận thức ở tuổi già.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_5_63","topic":"Nature and Environmental Protection","word":"coin","pos":"(n)","ipa":"/kɔɪn/","defVi":"đồng xu, tiền kim loại","defEn":"a small, flat, usually round piece of metal used as money","examples":["She inserted a shiny [coin] into the vending machine to buy a drink. (=Dịch: Cô ấy nhét một đồng xu sáng bóng vào máy bán hàng tự động để mua nước uống.)","He flipped a [coin] to decide who would start the game. (=Dịch: Anh ấy đã tung một đồng xu để quyết định xem ai sẽ bắt đầu trò chơi.)","My grandfather gave me a rare silver [coin] for my collection. (=Dịch: Ông tôi đã tặng tôi một đồng xu bạc hiếm cho bộ sưu tập của tôi.)"],"ukAudio":"/ai_services/tts3/?q=coin&lang=en-GB&ipa=%2Fk%C9%94%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=coin&lang=en-US&ipa=%2Fk%C9%94%C9%AAn%2F"},{"id":"lv_5_64","topic":"Nature and Environmental Protection","word":"colony","pos":"(n)","ipa":"/ˈkɑː.lə.ni/","defVi":"thuộc địa; bầy đàn (động vật sống thành đàn)","defEn":"a country controlled by another country, or a group of animals living together","examples":["Hong Kong used to be a British [colony] before 1997. (=Dịch: Hồng Kông từng là một thuộc địa của Anh trước năm 1997.)","Scientists observed a large [colony] of penguins on the icy shore. (=Dịch: Các nhà khoa học đã quan sát một bầy chim cánh cụt lớn trên bờ biển phủ băng.)","Ants live together in an organized underground [colony]. (=Dịch: Kiến sống cùng nhau trong một tổ kiến có tổ chức dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=colony&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=colony&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.l%C9%99.ni%2F"},{"id":"lv_5_65","topic":"Nature and Environmental Protection","word":"commission","pos":"(n)","ipa":"/kəˈmɪʃ.ən/","defVi":"hội đồng/ủy ban; tiền hoa hồng","defEn":"an official group appointed to perform a task, or a payment given to an agent for a service","examples":["The government formed an independent [commission] to investigate the transportation accident. (=Dịch: Chính phủ đã thành lập một ủy ban độc lập để điều tra vụ tai nạn giao thông.)","Real estate agents typically earn a percentage-based [commission] on every property sold. (=Dịch: Các đại lý bất động sản thường kiếm được tiền hoa hồng dựa trên tỷ lệ phần trăm của mỗi bất động sản bán được.)","The artist received a prestigious [commission] to paint a portrait for the city hall. (=Dịch: Người nghệ sĩ đã nhận được một đơn đặt hàng danh giá để vẽ một bức chân dung cho tòa thị chính.)"],"ukAudio":"/ai_services/tts3/?q=commission&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=commission&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_66","topic":"Nature and Environmental Protection","word":"commonly","pos":"(adv)","ipa":"/ˈkɑː.mən.li/","defVi":"thường thường, phổ biến","defEn":"very often, frequently, or by most people","examples":["This type of mushroom is [commonly] found in damp forests. (=Dịch: Loại nấm này thường được tìm thấy trong các khu rừng ẩm ướt.)","The disease is [commonly] known as the flu. (=Dịch: Căn bệnh này thường được gọi phổ biến là bệnh cúm.)","Plastic bottles are [commonly] used for packaging soft drinks. (=Dịch: Chai nhựa thường được sử dụng rộng rãi để đóng gói nước giải khát.)"],"ukAudio":"/ai_services/tts3/?q=commonly&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.li%2F","usAudio":"/ai_services/tts3/?q=commonly&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.m%C9%99n.li%2F"},{"id":"lv_5_67","topic":"Nature and Environmental Protection","word":"compass","pos":"(n)","ipa":"/ˈkʌm.pəs/","defVi":"la bàn","defEn":"an instrument that shows direction, having a needle that always points north","examples":["Hikers should always carry a map and a [compass] in the wilderness. (=Dịch: Những người đi bộ đường dài nên luôn mang theo bản đồ và la bàn khi vào nơi hoang dã.)","The needle of the [compass] points directly toward magnetic north. (=Dịch: Kim la bàn luôn chỉ thẳng về phía bắc từ trường.)","Without a reliable [compass], it is easy to get lost in the dense forest. (=Dịch: Nếu không có một chiếc la bàn đáng tin cậy, bạn rất dễ bị lạc trong khu rừng rậm.)"],"ukAudio":"/ai_services/tts3/?q=compass&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=compass&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.p%C9%99s%2F"},{"id":"lv_5_68","topic":"Nature and Environmental Protection","word":"compost","pos":"(n)","ipa":"/ˈkɑːm.poʊst/","defVi":"phân ủ hữu cơ","defEn":"decayed organic material used as a fertilizer for growing plants","examples":["Adding [compost] to sandy soil helps it retain moisture and essential nutrients. (=Dịch: Thêm phân ủ hữu cơ vào đất cát giúp đất giữ ẩm và các chất dinh dưỡng thiết yếu.)","She collects fruit peels and coffee grounds in her garden to make organic [compost]. (=Dịch: Cô ấy thu gom vỏ trái cây và bã cà phê trong vườn để làm phân ủ hữu cơ.)","Using rich [compost] reduces the need for synthetic chemical fertilizers on farms. (=Dịch: Sử dụng phân ủ giàu dưỡng chất giúp giảm nhu cầu dùng phân bón hóa học tổng hợp trong các trang trại.)"],"ukAudio":"/ai_services/tts3/?q=compost&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90m.po%CA%8Ast%2F","usAudio":"/ai_services/tts3/?q=compost&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90m.po%CA%8Ast%2F"},{"id":"lv_5_69","topic":"Nature and Environmental Protection","word":"comprehensive","pos":"(adj)","ipa":"/ˌkɑːm.prɪ.ˈhen.sɪv/","defVi":"toàn diện, bao quát","defEn":"including all, or almost all, the items or details that are involved","examples":["The school offers a [comprehensive] course covering all four language skills. (=Dịch: Ngôi trường cung cấp một khóa học toàn diện bao gồm cả bốn kỹ năng ngôn ngữ.)","The government conducted a [comprehensive] study on climate change. (=Dịch: Chính phủ đã tiến hành một nghiên cứu toàn diện về biến đổi khí hậu.)","We need a [comprehensive] plan to solve the city's traffic congestion. (=Dịch: Chúng ta cần một kế hoạch toàn diện để giải quyết tình trạng ùn tắc giao thông của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=comprehensive&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.pr%C9%AA.%CB%88hen.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=comprehensive&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.pr%C9%AA.%CB%88hen.s%C9%AAv%2F"},{"id":"lv_5_70","topic":"Nature and Environmental Protection","word":"comprise","pos":"(v)","ipa":"/kəmˈpraɪz/","defVi":"bao gồm, gồm có","defEn":"to have things or people as parts or members; to consist of","examples":["The advisory panel will [comprise] experts from diverse academic backgrounds. (=Dịch: Hội đồng cố vấn sẽ bao gồm các chuyên gia từ nhiều nền tảng học thuật khác nhau.)","Older adults and young children [comprise] the majority of the population in this village. (=Dịch: Người lớn tuổi và trẻ nhỏ chiếm phần lớn dân số ở ngôi làng này.)","The newly developed syllabus will [comprise] ten comprehensive study modules. (=Dịch: Giáo trình mới được xây dựng sẽ bao gồm mười học phần nghiên cứu toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=comprise&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pra%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=comprise&lang=en-US&ipa=%2Fk%C9%99m%CB%88pra%C9%AAz%2F"},{"id":"lv_5_71","topic":"Nature and Environmental Protection","word":"conclude","pos":"(v)","ipa":"/kənˈkluːd/","defVi":"kết luận; kết thúc","defEn":"to reach a decision or opinion after considering all the facts; to bring something to an end","examples":["Based on the survey data, we can [conclude] that public support has risen. (=Dịch: Dựa vào dữ liệu khảo sát, chúng ta có thể kết luận rằng sự ủng hộ của công chúng đã tăng lên.)","The keynote speaker will [conclude] his presentation with a short question session. (=Dịch: Diễn giả chính sẽ kết thúc bài thuyết trình của mình bằng một phần hỏi đáp ngắn.)","Investigators were able to [conclude] the inquiry after discovering new evidence. (=Dịch: Các điều tra viên đã có thể kết thúc cuộc điều tra sau khi phát hiện ra bằng chứng mới.)"],"ukAudio":"/ai_services/tts3/?q=conclude&lang=en-GB&ipa=%2Fk%C9%99n%CB%88klu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=conclude&lang=en-US&ipa=%2Fk%C9%99n%CB%88klu%CB%90d%2F"},{"id":"lv_5_72","topic":"Nature and Environmental Protection","word":"confused","pos":"(adj)","ipa":"/kənˈfjuzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to understand something clearly or think sensibly","examples":["I was deeply [confused] by the complicated instructions. (=Dịch: Tôi đã rất bối rối trước những lời hướng dẫn phức tạp.)","The student looked [confused] during the difficult lecture. (=Dịch: Người sinh viên trông có vẻ lúng túng trong suốt bài giảng khó.)","If you feel [confused] about the new rules, please ask your supervisor. (=Dịch: Nếu bạn cảm thấy hoang mang về các quy định mới, hãy hỏi người giám sát của bạn.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fjuzd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fjuzd%2F"},{"id":"lv_5_73","topic":"Nature and Environmental Protection","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwəns/","defVi":"hậu quả, kết quả","defEn":"a result or effect of an action or situation, typically one that is unwelcome or unpleasant","examples":["Global warming is a direct [consequence] of excessive greenhouse gas emissions. (=Dịch: Sự nóng lên toàn cầu là hậu quả trực tiếp của việc phát thải khí nhà kính quá mức.)","He had to face the [consequence] of making such a hasty decision. (=Dịch: Anh ấy phải đối mặt với hậu quả của việc đưa ra một quyết định vội vàng như vậy.)","Failing to study properly will have a serious [consequence] on your grades. (=Dịch: Không học hành đàng hoàng sẽ gây ra hậu quả nghiêm trọng đến điểm số của bạn.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F"},{"id":"lv_5_74","topic":"Nature and Environmental Protection","word":"consistent","pos":"(adj)","ipa":"/kənˈsɪs.tənt/","defVi":"nhất quán, kiên định, đồng đều","defEn":"always behaving or happening in a similar, especially positive, way","examples":["She has shown a [consistent] improvement in her English test scores. (=Dịch: Cô ấy đã thể hiện sự tiến bộ đều đặn trong điểm số bài thi tiếng Anh.)","His statements were not [consistent] with the facts. (=Dịch: Những lời tuyên bố của anh ấy không nhất quán với sự thật.)","To achieve success, you need to put in [consistent] effort every day. (=Dịch: Để đạt được thành công, bạn cần nỗ lực bền bỉ mỗi ngày.)"],"ukAudio":"/ai_services/tts3/?q=consistent&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%AAs.t%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=consistent&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%AAs.t%C9%99nt%2F"},{"id":"lv_5_75","topic":"Nature and Environmental Protection","word":"consume","pos":"(v)","ipa":"/kənˈsuːm/","defVi":"tiêu thụ, sử dụng","defEn":"to eat, drink, or use up resources, energy, or time","examples":["Electric vehicles [consume] far less energy compared to traditional petrol cars. (=Dịch: Xe điện tiêu thụ ít năng lượng hơn nhiều so với xe chạy xăng truyền thống.)","Athletes should [consume] plenty of water and carbohydrates before a marathon. (=Dịch: Vận động viên nên tiêu thụ nhiều nước và tinh bột trước khi chạy marathon.)","The enormous forest fire threatened to [consume] several mountain villages. (=Dịch: Trận cháy rừng khủng khiếp đe dọa thiêu rụi vài ngôi làng miền núi.)"],"ukAudio":"/ai_services/tts3/?q=consume&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F","usAudio":"/ai_services/tts3/?q=consume&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F"},{"id":"lv_5_76","topic":"Nature and Environmental Protection","word":"consumption","pos":"(n)","ipa":"/kənˈsʌmp.ʃən/","defVi":"sự tiêu thụ, mức tiêu dùng","defEn":"the act of using up resources, goods, or energy","examples":["The doctor advised him to reduce his daily sugar [consumption]. (=Dịch: Bác sĩ khuyên anh ấy nên giảm lượng tiêu thụ đường hàng ngày.)","Rapid economic growth usually leads to higher energy [consumption]. (=Dịch: Tăng trưởng kinh tế nhanh chóng thường dẫn đến mức tiêu thụ năng lượng cao hơn.)","Public campaigns aim to minimize the excessive [consumption] of single-use plastics. (=Dịch: Các chiến dịch cộng đồng nhằm giảm thiểu việc tiêu thụ quá mức các sản phẩm nhựa dùng một lần.)"],"ukAudio":"/ai_services/tts3/?q=consumption&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consumption&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_5_77","topic":"Nature and Environmental Protection","word":"contaminate","pos":"(v)","ipa":"/kənˈtæm.ə.neɪt/","defVi":"làm bẩn, làm ô nhiễm","defEn":"to make something less pure or poisonous by adding a substance to it","examples":["Industrial waste can easily [contaminate] local drinking water supplies. (=Dịch: Chất thải công nghiệp có thể dễ dàng làm ô nhiễm nguồn nước sinh hoạt của địa phương.)","Pesticides run off into rivers and [contaminate] the natural habitats of fish. (=Dịch: Thuốc trừ sâu trôi xuống các dòng sông và làm ô nhiễm môi trường sống tự nhiên của cá.)","Be careful not to [contaminate] the sterile instruments before the operation. (=Dịch: Hãy cẩn thận để không làm nhiễm khuẩn các dụng cụ vô trùng trước ca phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=contaminate&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C3%A6m.%C9%99.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=contaminate&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C3%A6m.%C9%99.ne%C9%AAt%2F"},{"id":"lv_5_78","topic":"Nature and Environmental Protection","word":"conversion","pos":"(n)","ipa":"/kənˈvɜːr.ʒən/","defVi":"sự chuyển đổi","defEn":"the process of changing from one system, use, or method to another","examples":["The [conversion] of solar energy into electricity is becoming more efficient. (=Dịch: Sự chuyển đổi năng lượng mặt trời thành điện năng đang ngày càng trở nên hiệu quả hơn.)","The company managed the [conversion] from paper records to digital files smoothly. (=Dịch: Công ty đã xử lý việc chuyển đổi từ hồ sơ giấy sang tệp kỹ thuật số một cách suôn sẻ.)","Urban planners approved the [conversion] of the warehouse into modern apartments. (=Dịch: Các nhà quy hoạch đô thị đã chấp thuận việc chuyển đổi nhà kho thành các căn hộ hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=conversion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=conversion&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_5_79","topic":"Nature and Environmental Protection","word":"convinced","pos":"(adj)","ipa":"/kənˈvɪnst/","defVi":"Bị thuyết phục; tin chắc; chắc chắn.","defEn":"Completely certain about something or believing that something is true.","examples":["Scientists are [convinced] that human activity contributes to global warming. (=Dịch: Các nhà khoa học tin chắc rằng hoạt động của con người góp phần gây ra sự nóng lên toàn cầu.)","She remained [convinced] that she had made the right decision for her career. (=Dịch: Cô ấy vẫn tin chắc rằng mình đã đưa ra quyết định đúng đắn cho sự nghiệp của mình.)","The jury was not entirely [convinced] by the witness's testimony. (=Dịch: Bồi thẩm đoàn không hoàn toàn bị thuyết phục bởi lời khai của nhân chứng.)"],"ukAudio":"/ai_services/tts3/?q=convinced&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%AAnst%2F","usAudio":"/ai_services/tts3/?q=convinced&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%AAnst%2F"},{"id":"lv_5_80","topic":"Nature and Environmental Protection","word":"cooler","pos":"(n)","ipa":"/ˈku.lər/","defVi":"thùng giữ nhiệt, thùng đá","defEn":"an insulated container used for keeping food or drinks cold","examples":["We packed some cold drinks and sandwiches in the [cooler] before heading to the beach. (=Dịch: Chúng tôi đã xếp một số đồ uống lạnh và bánh mì kẹp vào thùng đá trước khi đi biển.)","Please put the remaining ice cream back into the [cooler] so it will not melt. (=Dịch: Làm ơn cất chỗ kem còn lại vào thùng giữ nhiệt để kem không bị chảy.)","The portable [cooler] kept the medical supplies at a safe temperature during transport. (=Dịch: Thùng giữ nhiệt di động đã bảo quản các vật tư y tế ở nhiệt độ an toàn trong suốt quá trình vận chuyển.)"],"ukAudio":"/ai_services/tts3/?q=cooler&lang=en-GB&ipa=%2F%CB%88ku.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=cooler&lang=en-US&ipa=%2F%CB%88ku.l%C9%99r%2F"},{"id":"lv_5_81","topic":"Nature and Environmental Protection","word":"corn","pos":"(n)","ipa":"/kɔːrn/","defVi":"ngô, bắp","defEn":"a tall plant that produces large yellow grains on a cob, used as food","examples":["Farmers harvested tons of sweet [corn] this autumn. (=Dịch: Những người nông dân đã thu hoạch hàng tấn ngô ngọt vào mùa thu này.)","Popcorn is made by heating dried kernels of [corn]. (=Dịch: Bắp rang bơ được làm bằng cách đun nóng các hạt ngô khô.)","Many processed foods contain syrup derived from [corn]. (=Dịch: Nhiều thực phẩm chế biến sẵn chứa si-rô chiết xuất từ ngô.)"],"ukAudio":"/ai_services/tts3/?q=corn&lang=en-GB&ipa=%2Fk%C9%94%CB%90rn%2F","usAudio":"/ai_services/tts3/?q=corn&lang=en-US&ipa=%2Fk%C9%94%CB%90rn%2F"},{"id":"lv_5_82","topic":"Nature and Environmental Protection","word":"courtyard","pos":"(n)","ipa":"/ˈkɔːrt.jɑːrd/","defVi":"sân trong, khuôn viên","defEn":"an open area surrounded by buildings or walls","examples":["The hotel features a peaceful [courtyard] with a small fountain in the center. (=Dịch: Khách sạn có một khoảng sân trong yên tĩnh với một đài phun nước nhỏ ở trung tâm.)","Students often gather in the central [courtyard] during lunch breaks. (=Dịch: Học sinh thường tụ tập ở sân trong trung tâm trong giờ nghỉ trưa.)","Tall walls sheltered the private [courtyard] from strong winds. (=Dịch: Những bức tường cao đã che chắn cho sân trong riêng tư khỏi những cơn gió mạnh.)"],"ukAudio":"/ai_services/tts3/?q=courtyard&lang=en-GB&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=courtyard&lang=en-US&ipa=%2F%CB%88k%C9%94%CB%90rt.j%C9%91%CB%90rd%2F"},{"id":"lv_5_83","topic":"Nature and Environmental Protection","word":"creature","pos":"(n)","ipa":"/ˈkri.tʃɚ/","defVi":"sinh vật, loài vật","defEn":"any living thing that can move independently, especially an animal","examples":["The ocean depths are home to many bizarre [creatures]. (=Dịch: Đáy đại dương sâu thẳm là nơi cư ngụ của nhiều sinh vật kỳ dị.)","Every living [creature] plays an important role in the ecosystem. (=Dịch: Mỗi sinh vật sống đều đóng một vai trò quan trọng trong hệ sinh thái.)","Scientists discovered a nocturnal [creature] that only hunts at night. (=Dịch: Các nhà khoa học đã phát hiện ra một sinh vật sống về đêm chỉ đi săn khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=creature&lang=en-GB&ipa=%2F%CB%88kri.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=creature&lang=en-US&ipa=%2F%CB%88kri.t%CA%83%C9%9A%2F"},{"id":"lv_5_84","topic":"Nature and Environmental Protection","word":"crisis","pos":"(n)","ipa":"/ˈkraɪ.sɪs/","defVi":"cuộc khủng hoảng","defEn":"a time of intense difficulty, trouble, or danger requiring urgent action","examples":["The government introduced emergency measures to deal with the worsening energy [crisis]. (=Dịch: Chính phủ đã đưa ra các biện pháp khẩn cấp để đối phó với cuộc khủng hoảng năng lượng ngày càng trầm trọng.)","Effective leadership is vital when guiding an organization through an unexpected financial [crisis]. (=Dịch: Sự lãnh đạo hiệu quả là điều tối quan trọng khi dẫn dắt một tổ chức vượt qua cuộc khủng hoảng tài chính bất ngờ.)","The sudden flood created a severe humanitarian [crisis] across the coastal region. (=Dịch: Trận lũ lụt đột ngột đã tạo ra một cuộc khủng hoảng nhân đạo nghiêm trọng trên khắp vùng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=crisis&lang=en-GB&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=crisis&lang=en-US&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F"},{"id":"lv_5_85","topic":"Nature and Environmental Protection","word":"crow","pos":"(n)","ipa":"/kroʊ/","defVi":"con quạ","defEn":"a large, shiny black bird with a harsh cry","examples":["A black [crow] landed on the fence and looked around. (=Dịch: Một con quạ đen đậu trên hàng rào và nhìn quanh.)","Researchers found that the [crow] is capable of solving complex puzzles. (=Dịch: Các nhà nghiên cứu phát hiện ra rằng loài quạ có khả năng giải các câu đố phức tạp.)","The loud call of a [crow] echoed through the quiet forest. (=Dịch: Tiếng kêu lớn của một con quạ vang vọng khắp khu rừng yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=crow&lang=en-GB&ipa=%2Fkro%CA%8A%2F","usAudio":"/ai_services/tts3/?q=crow&lang=en-US&ipa=%2Fkro%CA%8A%2F"},{"id":"lv_5_86","topic":"Nature and Environmental Protection","word":"crucial","pos":"(adj)","ipa":"/ˈkru.ʃəl/","defVi":"mang tính quyết định, cực kỳ quan trọng","defEn":"extremely important or necessary","examples":["Regular exercise plays a [crucial] role in maintaining overall physical health. (=Dịch: Tập thể dục thường xuyên đóng một vai trò cực kỳ quan trọng trong việc duy trì sức khỏe thể chất toàn diện.)","Effective communication is [crucial] for resolving workplace conflicts peacefully. (=Dịch: Giao tiếp hiệu quả là điều cốt yếu để giải quyết các mâu thuẫn nơi làm việc một cách hòa bình.)","The government made a [crucial] decision to cut carbon emissions this year. (=Dịch: Chính phủ đã đưa ra một quyết định mang tính quyết định nhằm cắt giảm lượng khí thải carbon trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=crucial&lang=en-GB&ipa=%2F%CB%88kru.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=crucial&lang=en-US&ipa=%2F%CB%88kru.%CA%83%C9%99l%2F"},{"id":"lv_5_87","topic":"Nature and Environmental Protection","word":"crush","pos":"(v)","ipa":"/krʌʃ/","defVi":"Nghiền nát, đè bẹp, ép vụn","defEn":"To press something so hard that it gets broken, damaged, or flat.","examples":["You need to [crush] the garlic cloves before adding them to the sauce. (=Dịch: Bạn cần đập dập các tép tỏi trước khi cho vào nước sốt.)","The heavy falling branch managed to [crush] the parked car. (=Dịch: Cành cây lớn rơi xuống đã đè bẹp chiếc xe hơi đang đỗ.)","Machines are used to [crush] rocks into fine gravel for road construction. (=Dịch: Máy móc được sử dụng để nghiền đá thành sỏi mịn phục vụ cho việc làm đường.)"],"ukAudio":"/ai_services/tts3/?q=crush&lang=en-GB&ipa=%2Fkr%CA%8C%CA%83%2F","usAudio":"/ai_services/tts3/?q=crush&lang=en-US&ipa=%2Fkr%CA%8C%CA%83%2F"},{"id":"lv_5_88","topic":"Nature and Environmental Protection","word":"cryptobiosis","pos":"(n)","ipa":"/ˌkrɪp.toʊ.baɪˈoʊ.sɪs/","defVi":"hiện tượng tiềm sinh (trạng thái đình chỉ hoạt động sống ở sinh vật)","defEn":"a state of extreme inactivity in an organism in response to adverse environmental conditions","examples":["Tardigrades can enter a state of [cryptobiosis] to survive extreme cold and radiation. (=Dịch: Gấu nước có thể bước vào trạng thái tiềm sinh để sống sót qua cái lạnh khắc nghiệt và bức xạ.)","During [cryptobiosis], an organism's metabolic activity slows down almost completely. (=Dịch: Trong trạng thái tiềm sinh, hoạt động trao đổi chất của sinh vật chậm lại gần như hoàn toàn.)","Scientists study [cryptobiosis] to understand how life might endure in outer space. (=Dịch: Các nhà khoa học nghiên cứu hiện tượng tiềm sinh để hiểu cách sự sống có thể tồn tại ngoài không gian.)"],"ukAudio":"/ai_services/tts3/?q=cryptobiosis&lang=en-GB&ipa=%2F%CB%8Ckr%C9%AAp.to%CA%8A.ba%C9%AA%CB%88o%CA%8A.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=cryptobiosis&lang=en-US&ipa=%2F%CB%8Ckr%C9%AAp.to%CA%8A.ba%C9%AA%CB%88o%CA%8A.s%C9%AAs%2F"},{"id":"lv_5_89","topic":"Nature and Environmental Protection","word":"damaging","pos":"(adj)","ipa":"/ˈdæm.ɪ.dʒɪŋ/","defVi":"Gây hại, gây tổn hại, có hại.","defEn":"Causing harm, injury, or loss of value.","examples":["Smoking has many [damaging] effects on human health. (=Dịch: Hút thuốc gây ra nhiều ảnh hưởng có hại đối với sức khỏe con người.)","The scandal had a very [damaging] impact on his political career. (=Dịch: Vụ bê bối đã để lại tác động rất tai hại đến sự nghiệp chính trị của ông ấy.)","UV radiation can be extremely [damaging] to uncovered skin. (=Dịch: Bức xạ tia cực tím có thể gây tổn hại nghiêm trọng cho da không được che chắn.)"],"ukAudio":"/ai_services/tts3/?q=damaging&lang=en-GB&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=damaging&lang=en-US&ipa=%2F%CB%88d%C3%A6m.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_5_90","topic":"Nature and Environmental Protection","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"Giảm sút, suy giảm; từ chối khéo.","defEn":"To decrease in number, amount, or quality; or to politely refuse.","examples":["Profits began to [decline] sharply during the economic crisis. (=Dịch: Lợi nhuận bắt đầu suy giảm mạnh trong thời kỳ khủng hoảng kinh tế.)","I had to politely [decline] their kind invitation to dinner. (=Dịch: Tôi đã phải lịch sự từ chối lời mời ăn tối tử tế của họ.)","Air quality can [decline] when industrial emissions increase. (=Dịch: Chất lượng không khí có thể giảm sút khi lượng khí thải công nghiệp gia tăng.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_5_91","topic":"Nature and Environmental Protection","word":"deer","pos":"(n)","ipa":"/dɪr/","defVi":"con hươu, con nai","defEn":"a hoofed grazing animal with long legs, the males of which usually have branched horns (antlers)","examples":["A herd of [deer] was seen grazing peacefully in the meadow. (=Dịch: Một đàn hươu được nhìn thấy đang gặm cỏ yên bình trên đồng cỏ.)","Drivers should be cautious because a [deer] might suddenly jump onto the road. (=Dịch: Tài xế nên cẩn thận vì hươu có thể bất ngờ nhảy ra đường.)","The young [deer] quickly hid behind the bushes when it sensed danger. (=Dịch: Chú nai con nhanh chóng trốn sau bụi cây khi cảm nhận được nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=deer&lang=en-GB&ipa=%2Fd%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=deer&lang=en-US&ipa=%2Fd%C9%AAr%2F"},{"id":"lv_5_92","topic":"Nature and Environmental Protection","word":"dependent","pos":"(adj)","ipa":"/dɪˈpen.dənt/","defVi":"phụ thuộc, lệ thuộc","defEn":"needing someone or something for support, help, or survival; determined by something else","examples":["Newborn babies are completely [dependent] on their parents for care. (=Dịch: Trẻ sơ sinh hoàn toàn phụ thuộc vào cha mẹ để được chăm sóc.)","The success of the crops is heavily [dependent] on the weather. (=Dịch: Sự thành công của mùa màng phụ thuộc rất nhiều vào thời tiết.)","Many developing nations are still [dependent] on foreign aid. (=Dịch: Nhiều quốc gia đang phát triển vẫn còn phụ thuộc vào viện trợ nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88pen.d%C9%99nt%2F"},{"id":"lv_5_93","topic":"Nature and Environmental Protection","word":"derive","pos":"(v)","ipa":"/dɪˈraɪv/","defVi":"bắt nguồn từ, nhận được từ","defEn":"to get something from a particular source, or to originate from it","examples":["Many English words [derive] from Latin and ancient Greek. (=Dịch: Nhiều từ tiếng Anh bắt nguồn từ tiếng La-tinh và tiếng Hy Lạp cổ đại.)","She hopes to [derive] great satisfaction from her new career in teaching. (=Dịch: Cô ấy hy vọng sẽ nhận được sự hài lòng lớn từ sự nghiệp giảng dạy mới của mình.)","The company can [derive] valuable insights from customer feedback data. (=Dịch: Công ty có thể thu thập được những hiểu biết giá trị từ dữ liệu phản hồi của khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=derive&lang=en-GB&ipa=%2Fd%C9%AA%CB%88ra%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=derive&lang=en-US&ipa=%2Fd%C9%AA%CB%88ra%C9%AAv%2F"},{"id":"lv_5_94","topic":"Nature and Environmental Protection","word":"destination","pos":"(n)","ipa":"/ˌdɛs.təˈneɪ.ʃən/","defVi":"Điểm đến, nơi đến.","defEn":"The place to which someone or something is going or being sent.","examples":["Paris is one of the most popular tourist [destination]s in the world. (=Dịch: Paris là một trong những điểm đến du lịch nổi tiếng nhất trên thế giới.)","We finally arrived at our [destination] after a long flight. (=Dịch: Cuối cùng chúng tôi cũng đến được nơi sau một chuyến bay dài.)","The package will reach its final [destination] by tomorrow morning. (=Dịch: Kiện hàng sẽ đến điểm giao cuối cùng trước sáng mai.)"],"ukAudio":"/ai_services/tts3/?q=destination&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bs.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destination&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bs.t%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_95","topic":"Nature and Environmental Protection","word":"destruction","pos":"(n)","ipa":"/dɪˈstrʌk.ʃən/","defVi":"sự tàn phá, sự phá hủy","defEn":"the act or process of damaging something so badly that it no longer exists or cannot be repaired","examples":["The earthquake caused widespread [destruction] throughout the city. (=Dịch: Trận động đất đã gây ra sự tàn phá trên diện rộng khắp thành phố.)","Deforestation leads to the rapid [destruction] of natural wildlife habitats. (=Dịch: Nạn phá rừng dẫn đến sự phá hủy nhanh chóng môi trường sống tự nhiên của động vật hoang dã.)","Many historical buildings were saved from total [destruction] during the war. (=Dịch: Nhiều tòa nhà lịch sử đã được cứu khỏi sự phá hủy hoàn toàn trong chiến tranh.)"],"ukAudio":"/ai_services/tts3/?q=destruction&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=destruction&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_5_96","topic":"Nature and Environmental Protection","word":"detailed","pos":"(adj)","ipa":"/dɪˈteɪld/","defVi":"chi tiết, tỉ mỉ","defEn":"giving a lot of information with many specific facts or aspects","examples":["The architect presented a [detailed] plan for the new library. (=Dịch: Kiến trúc sư đã trình bày một bản kế hoạch chi tiết cho thư viện mới.)","She gave a [detailed] account of what happened during the meeting. (=Dịch: Cô ấy đã kể lại chi tiết những gì đã xảy ra trong cuộc họp.)","Students need to follow the [detailed] instructions on the exam paper. (=Dịch: Học sinh cần tuân theo các hướng dẫn chi tiết trên đề thi.)"],"ukAudio":"/ai_services/tts3/?q=detailed&lang=en-GB&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=detailed&lang=en-US&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F"},{"id":"lv_5_97","topic":"Nature and Environmental Protection","word":"detect","pos":"(v)","ipa":"/dɪˈtekt/","defVi":"phát hiện, dò tìm ra","defEn":"to notice, discover, or identify the presence of something","examples":["Trained rescue dogs can [detect] survivors trapped beneath collapsed buildings. (=Dịch: Chó cứu hộ được huấn luyện có thể phát hiện những người sống sót bị mắc kẹt dưới các tòa nhà sụp đổ.)","Regular medical screenings help doctors [detect] serious diseases early. (=Dịch: Khám sức khỏe định kỳ giúp các bác sĩ phát hiện sớm các bệnh hiểm nghèo.)","The sensitive sensor failed to [detect] any smoke in the corridor. (=Dịch: Cảm biến nhạy bén đã không phát hiện thấy bất kỳ dấu hiệu khói nào trong hành lang.)"],"ukAudio":"/ai_services/tts3/?q=detect&lang=en-GB&ipa=%2Fd%C9%AA%CB%88tekt%2F","usAudio":"/ai_services/tts3/?q=detect&lang=en-US&ipa=%2Fd%C9%AA%CB%88tekt%2F"},{"id":"lv_5_98","topic":"Nature and Environmental Protection","word":"devastating","pos":"(adj)","ipa":"/ˈdɛv.əˌsteɪ.tɪŋ/","defVi":"tàn phá, hủy diệt, gây sốc nặng nề","defEn":"causing severe shock, distress, or immense damage","examples":["The earthquake had a [devastating] impact on the local infrastructure. (=Dịch: Trận động đất đã gây ra tác động tàn phá nặng nề đối với cơ sở hạ tầng địa phương.)","Losing his job was a [devastating] blow to his family's finances. (=Dịch: Mất việc là một cú sốc tàn khốc đối với tài chính của gia đình anh ấy.)","The flood had [devastating] effects on the agricultural sector. (=Dịch: Trận lũ lụt đã gây ra những hậu quả mang tính hủy diệt đối với ngành nông nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=devastating&lang=en-GB&ipa=%2F%CB%88d%C9%9Bv.%C9%99%CB%8Cste%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=devastating&lang=en-US&ipa=%2F%CB%88d%C9%9Bv.%C9%99%CB%8Cste%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_5_99","topic":"Nature and Environmental Protection","word":"diagram","pos":"(n)","ipa":"/ˈdaɪ.ə.ɡræm/","defVi":"sơ đồ, biểu đồ minh họa","defEn":"a simple drawing that explains how something works or shows the relationship between parts","examples":["The teacher drew a [diagram] on the board to explain the water cycle. (=Dịch: Giáo viên đã vẽ một sơ đồ lên bảng để giải thích vòng tuần hoàn của nước.)","Please refer to the [diagram] on page 12 for assembly instructions. (=Dịch: Vui lòng tham khảo sơ đồ ở trang 12 để biết hướng dẫn lắp ráp.)","This simple [diagram] illustrates how blood flows through the heart. (=Dịch: Sơ đồ đơn giản này minh họa cách máu lưu thông qua tim.)"],"ukAudio":"/ai_services/tts3/?q=diagram&lang=en-GB&ipa=%2F%CB%88da%C9%AA.%C9%99.%C9%A1r%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=diagram&lang=en-US&ipa=%2F%CB%88da%C9%AA.%C9%99.%C9%A1r%C3%A6m%2F"},{"id":"lv_5_100","topic":"Nature and Environmental Protection","word":"digestive","pos":"(adj)","ipa":"/daɪˈdʒes.tɪv/","defVi":"(thuộc) tiêu hóa","defEn":"relating to the digestion of food","examples":["Eating plenty of fiber supports a healthy [digestive] system. (=Dịch: Ăn nhiều chất xơ giúp hỗ trợ một hệ tiêu hóa khỏe mạnh.)","Certain spices can ease mild [digestive] problems after heavy meals. (=Dịch: Một số loại gia vị có thể làm giảm các vấn đề tiêu hóa nhẹ sau những bữa ăn nhiều dầu mỡ.)","Stomach acid plays a vital role in the human [digestive] process. (=Dịch: Axit dạ dày đóng một vai trò thiết yếu trong quá trình tiêu hóa của con người.)"],"ukAudio":"/ai_services/tts3/?q=digestive&lang=en-GB&ipa=%2Fda%C9%AA%CB%88d%CA%92es.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=digestive&lang=en-US&ipa=%2Fda%C9%AA%CB%88d%CA%92es.t%C9%AAv%2F"},{"id":"lv_5_101","topic":"Nature and Environmental Protection","word":"dioxide","pos":"(n)","ipa":"/daɪˈɑːk.saɪd/","defVi":"Điôxít (hợp chất oxit chứa hai nguyên tử oxy)","defEn":"An oxide containing two atoms of oxygen in each molecule","examples":["Plants absorb carbon [dioxide] from the atmosphere to perform photosynthesis. (=Dịch: Thực vật hấp thụ khí carbon điôxít từ khí quyển để tiến hành quang hợp.)","Sulfur [dioxide] emitted from industrial factories is a primary cause of acid rain. (=Dịch: Lưu huỳnh điôxít thải ra từ các nhà máy công nghiệp là nguyên nhân chính gây ra mưa axit.)","High levels of nitrogen [dioxide] can worsen respiratory problems in city residents. (=Dịch: Nồng độ nitơ điôxít cao có thể làm trầm trọng thêm các vấn đề về hô hấp ở cư dân thành phố.)"],"ukAudio":"/ai_services/tts3/?q=dioxide&lang=en-GB&ipa=%2Fda%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=dioxide&lang=en-US&ipa=%2Fda%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F"},{"id":"lv_5_102","topic":"Nature and Environmental Protection","word":"disappearance","pos":"(n)","ipa":"/ˌdɪs.əˈpɪr.əns/","defVi":"sự biến mất, sự mất tích","defEn":"the act or state of someone or something stopping being visible or existing","examples":["The sudden [disappearance] of the rare bird species puzzled local scientists. (=Dịch: Sự biến mất đột ngột của loài chim quý hiếm đã làm bối rối các nhà khoa học địa phương.)","Police are investigating the mysterious [disappearance] of a valuable painting from the gallery. (=Dịch: Cảnh sát đang điều tra sự biến mất bí ẩn của một bức tranh có giá trị khỏi phòng trưng bày.)","Deforestation has led to the [disappearance] of vast areas of natural habitat. (=Dịch: Nạn phá rừng đã dẫn đến sự biến mất của những vùng môi trường sống tự nhiên rộng lớn.)"],"ukAudio":"/ai_services/tts3/?q=disappearance&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%AAr.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=disappearance&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99%CB%88p%C9%AAr.%C9%99ns%2F"},{"id":"lv_5_103","topic":"Nature and Environmental Protection","word":"distribute","pos":"(v)","ipa":"/dɪˈstrɪb.jut/","defVi":"phân phát, phân phối, rải rác","defEn":"to give something out to several people, or to spread something over an area","examples":["Volunteers helped [distribute] food and water to the flood victims. (=Dịch: Các tình nguyện viên đã giúp phân phát thức ăn và nước uống cho các nạn nhân lũ lụt.)","The company plans to [distribute] its products to international markets next year. (=Dịch: Công ty dự định phân phối sản phẩm của mình sang các thị trường quốc tế vào năm tới.)","The teacher will [distribute] the test papers once everyone is seated. (=Dịch: Giáo viên sẽ phát đề thi khi mọi người đã ổn định chỗ ngồi.)"],"ukAudio":"/ai_services/tts3/?q=distribute&lang=en-GB&ipa=%2Fd%C9%AA%CB%88str%C9%AAb.jut%2F","usAudio":"/ai_services/tts3/?q=distribute&lang=en-US&ipa=%2Fd%C9%AA%CB%88str%C9%AAb.jut%2F"},{"id":"lv_5_104","topic":"Nature and Environmental Protection","word":"distribution","pos":"(n)","ipa":"/ˌdɪs.trɪˈbju.ʃən/","defVi":"sự phân phối, sự phân bổ","defEn":"the way in which something is spread or shared over an area or among a group of people","examples":["The unequal [distribution] of wealth remains a major issue in many developing nations. (=Dịch: Sự phân bổ của cải không đồng đều vẫn là một vấn đề lớn ở nhiều quốc gia đang phát triển.)","The company established an efficient network for the [distribution] of medical supplies. (=Dịch: Công ty đã thiết lập một mạng lưới hiệu quả để phân phối các vật tư y tế.)","Scientists mapped the geographic [distribution] of native plant species across the region. (=Dịch: Các nhà khoa học đã lập bản đồ phân bố địa lý của các loài thực vật bản địa trên khắp khu vực.)"],"ukAudio":"/ai_services/tts3/?q=distribution&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%AA%CB%88bju.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=distribution&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.tr%C9%AA%CB%88bju.%CA%83%C9%99n%2F"},{"id":"lv_5_105","topic":"Nature and Environmental Protection","word":"diversity","pos":"(n)","ipa":"/daɪˈvɜːr.sə.t̬i/","defVi":"sự đa dạng, tính phong phú","defEn":"the state of having many different types, people, or things","examples":["Cultural [diversity] enriches society by introducing new perspectives and traditions. (=Dịch: Sự đa dạng văn hóa làm phong phú xã hội bằng cách mang lại những góc nhìn và truyền thống mới.)","The national park is famous for its rich biological [diversity]. (=Dịch: Vườn quốc gia này nổi tiếng với sự đa dạng sinh học phong phú.)","The company is committed to promoting [diversity] and inclusion in the workplace. (=Dịch: Công ty cam kết thúc đẩy sự đa dạng và hòa nhập tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=diversity&lang=en-GB&ipa=%2Fda%C9%AA%CB%88v%C9%9C%CB%90r.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=diversity&lang=en-US&ipa=%2Fda%C9%AA%CB%88v%C9%9C%CB%90r.s%C9%99.t%CC%ACi%2F"},{"id":"lv_5_106","topic":"Nature and Environmental Protection","word":"dna","pos":"(n)","ipa":"/ˌdiː.enˈeɪ/","defVi":"ADN (axit đêôxiribônucleic, vật chất di truyền)","defEn":"the chemical at the center of cells that carries genetic information","examples":["Police collected [DNA] samples from the crime scene to identify the suspect. (=Dịch: Cảnh sát đã thu thập các mẫu ADN từ hiện trường vụ án để nhận diện nghi phạm.)","Modern tests can analyze your [DNA] to reveal your family origins. (=Dịch: Các xét nghiệm hiện đại có thể phân tích ADN của bạn để tiết lộ nguồn gốc dòng dõi gia đình.)","Scientists are studying how damage to [DNA] can lead to various diseases. (=Dịch: Các nhà khoa học đang nghiên cứu xem sự tổn thương của ADN có thể dẫn đến các bệnh khác nhau như thế nào.)"],"ukAudio":"/ai_services/tts3/?q=dna&lang=en-GB&ipa=%2F%CB%8Cdi%CB%90.en%CB%88e%C9%AA%2F","usAudio":"/ai_services/tts3/?q=dna&lang=en-US&ipa=%2F%CB%8Cdi%CB%90.en%CB%88e%C9%AA%2F"},{"id":"lv_5_107","topic":"Nature and Environmental Protection","word":"dolphin","pos":"(n)","ipa":"/ˈdɑːl.fɪn/","defVi":"cá heo","defEn":"a highly intelligent marine mammal that has a curved beak and a dorsal fin","examples":["We saw a playful [dolphin] jumping out of the water alongside our boat. (=Dịch: Chúng tôi nhìn thấy một chú cá heo tinh nghịch nhảy khỏi mặt nước bên cạnh thuyền của mình.)","The [dolphin] communicates with other members of its pod using complex whistle sounds. (=Dịch: Cá heo giao tiếp với các thành viên khác trong đàn bằng những âm thanh huýt sáo phức tạp.)","Scientists consider the [dolphin] to be one of the smartest creatures on Earth. (=Dịch: Các nhà khoa học coi cá heo là một trong những sinh vật thông minh nhất trên Trái Đất.)"],"ukAudio":"/ai_services/tts3/?q=dolphin&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=dolphin&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90l.f%C9%AAn%2F"},{"id":"lv_5_108","topic":"Nature and Environmental Protection","word":"dramatic","pos":"(adj)","ipa":"/drə.ˈmæt̬.ɪk/","defVi":"Đột ngột, kịch tính, ấn tượng hoặc rõ rệt","defEn":"Sudden, very great, and often surprising; related to drama or theater.","examples":["There has been a [dramatic] increase in the price of fuel this year. (=Dịch: Đã có một sự gia tăng rõ rệt về giá nhiên liệu trong năm nay.)","Her speech had a [dramatic] effect on the entire audience. (=Dịch: Bài phát biểu của cô ấy đã tạo ra một hiệu ứng đầy ấn tượng đối với toàn bộ khán giả.)","The movie ended with a [dramatic] confrontation on the rooftop. (=Dịch: Bộ phim kết thúc bằng một cuộc đối đầu đầy kịch tính trên sân thượng.)"],"ukAudio":"/ai_services/tts3/?q=dramatic&lang=en-GB&ipa=%2Fdr%C9%99.%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=dramatic&lang=en-US&ipa=%2Fdr%C9%99.%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_5_109","topic":"Nature and Environmental Protection","word":"drone","pos":"(n)","ipa":"/droʊn/","defVi":"máy bay không người lái","defEn":"an aircraft without a pilot that is controlled remotely or by onboard computers","examples":["The photographer used a [drone] to capture aerial views of the coastline. (=Dịch: Nhiếp ảnh gia đã sử dụng một chiếc máy bay không người lái để chụp quang cảnh bờ biển từ trên cao.)","Farmers are now deploying [drone] technology to monitor crop health efficiently. (=Dịch: Nông dân hiện đang triển khai công nghệ máy bay không người lái để theo dõi sức khỏe cây trồng một cách hiệu quả.)","The military deployed a [drone] for surveillance in remote areas. (=Dịch: Quân đội đã triển khai một máy bay không người lái để do thám ở các khu vực hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=drone&lang=en-GB&ipa=%2Fdro%CA%8An%2F","usAudio":"/ai_services/tts3/?q=drone&lang=en-US&ipa=%2Fdro%CA%8An%2F"},{"id":"lv_5_110","topic":"Nature and Environmental Protection","word":"drought","pos":"(n)","ipa":"/draʊt/","defVi":"hạn hán, tình trạng khô hạn kéo dài","defEn":"a long period of time when there is little or no rain, causing shortages of water","examples":["The prolonged [drought] caused rivers and reservoirs to completely dry up. (=Dịch: Đợt hạn hán kéo dài khiến các dòng sông và hồ chứa nước khô cạn hoàn toàn.)","Crops failed across the region due to an unprecedented summer [drought]. (=Dịch: Mùa màng thất bát trên toàn khu vực do một đợt hạn hán mùa hè chưa từng có.)","Residents were urged to conserve water as the severe [drought] showed no sign of ending. (=Dịch: Người dân được khuyến cáo tiết kiệm nước vì đợt hạn hán gay gắt chưa có dấu hiệu chấm dứt.)"],"ukAudio":"/ai_services/tts3/?q=drought&lang=en-GB&ipa=%2Fdra%CA%8At%2F","usAudio":"/ai_services/tts3/?q=drought&lang=en-US&ipa=%2Fdra%CA%8At%2F"},{"id":"lv_5_111","topic":"Nature and Environmental Protection","word":"dutch","pos":"(adj)","ipa":"/dʌtʃ/","defVi":"(thuộc) Hà Lan, người Hà Lan hoặc tiếng Hà Lan","defEn":"relating to the Netherlands, its people, or its language","examples":["Many tourists admire the classic [Dutch] architecture and picturesque canals of Amsterdam. (=Dịch: Nhiều du khách chiêm ngưỡng kiến trúc Hà Lan cổ điển và những con kênh đẹp như tranh vẽ của Amsterdam.)","The museum holds an impressive collection of seventeenth-century [Dutch] paintings. (=Dịch: Bảo tàng lưu giữ một bộ sưu tập ấn tượng gồm các bức tranh Hà Lan từ thế kỷ XVII.)","She studied [Dutch] engineering techniques for managing flood risks and building dikes. (=Dịch: Cô ấy đã nghiên cứu các kỹ thuật kỹ thuật của Hà Lan để quản lý rủi ro lũ lụt và xây dựng đê điều.)"],"ukAudio":"/ai_services/tts3/?q=dutch&lang=en-GB&ipa=%2Fd%CA%8Ct%CA%83%2F","usAudio":"/ai_services/tts3/?q=dutch&lang=en-US&ipa=%2Fd%CA%8Ct%CA%83%2F"},{"id":"lv_5_112","topic":"Nature and Environmental Protection","word":"earthworm","pos":"(n)","ipa":"/ˈɜːrθ.wɜːrm/","defVi":"con giun đất","defEn":"a long, thin creature with no bones that lives in the soil and helps improve it","examples":["The gardener noticed that the soil was rich because it was full of [earthworm] activity. (=Dịch: Người làm vườn nhận thấy đất rất màu mỡ vì có rất nhiều hoạt động của giun đất.)","An [earthworm] helps aerate the ground by burrowing through the soil. (=Dịch: Giun đất giúp làm tơi xốp đất bằng cách đào hang dưới lòng đất.)","After the heavy rain, many an [earthworm] crawled onto the wet pavement. (=Dịch: Sau cơn mưa lớn, nhiều con giun đất đã bò lên vỉa hè ẩm ướt.)"],"ukAudio":"/ai_services/tts3/?q=earthworm&lang=en-GB&ipa=%2F%CB%88%C9%9C%CB%90r%CE%B8.w%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=earthworm&lang=en-US&ipa=%2F%CB%88%C9%9C%CB%90r%CE%B8.w%C9%9C%CB%90rm%2F"},{"id":"lv_5_113","topic":"Nature and Environmental Protection","word":"eastern","pos":"(adj)","ipa":"/ˈis.tɚn/","defVi":"phía đông, thuộc về phương đông","defEn":"located in or facing toward the east, or characteristic of the east","examples":["The storm caused severe flooding along the [eastern] coast of the country. (=Dịch: Cơn bão đã gây ra lũ lụt nghiêm trọng dọc bờ biển phía đông của đất nước.)","Traditional [eastern] medicine often emphasizes a holistic approach to overall wellness. (=Dịch: Y học phương đông truyền thống thường nhấn mạnh phương pháp tiếp cận toàn diện đối với sức khỏe tổng thể.)","They decided to spend their summer vacation exploring ancient ruins in the [eastern] province. (=Dịch: Họ quyết định dành kỳ nghỉ hè để khám phá các tàn tích cổ xưa ở tỉnh phía đông.)"],"ukAudio":"/ai_services/tts3/?q=eastern&lang=en-GB&ipa=%2F%CB%88is.t%C9%9An%2F","usAudio":"/ai_services/tts3/?q=eastern&lang=en-US&ipa=%2F%CB%88is.t%C9%9An%2F"},{"id":"lv_5_114","topic":"Nature and Environmental Protection","word":"echo","pos":"(n)","ipa":"/ˈɛk.oʊ/","defVi":"tiếng vang, âm vang","defEn":"a sound that is heard again when sound waves bounce back from a surface","examples":["Her footsteps created a distinct [echo] in the vast, empty corridor. (=Dịch: Tiếng bước chân của cô ấy tạo ra âm vang rõ rệt trong hành lang rộng lớn và trống trải.)","The cavern was so large that every shout produced a long, haunting [echo]. (=Dịch: Hang động lớn đến mức mỗi tiếng hét đều tạo ra một tiếng vang dài và ám ảnh.)","The speaker's passionate words found a strong [echo] among the younger audience. (=Dịch: Những lời nói đầy nhiệt huyết của diễn giả đã tạo được sự đồng cảm mạnh mẽ trong lòng các khán giả trẻ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=echo&lang=en-GB&ipa=%2F%CB%88%C9%9Bk.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=echo&lang=en-US&ipa=%2F%CB%88%C9%9Bk.o%CA%8A%2F"},{"id":"lv_5_115","topic":"Nature and Environmental Protection","word":"ecosystem","pos":"(n)","ipa":"/ˈi.koʊˌsɪs.təm/","defVi":"hệ sinh thái","defEn":"all the living organisms in an area and the physical environment with which they interact","examples":["Pollution has caused severe damage to the delicate marine [ecosystem]. (=Dịch: Ô nhiễm đã gây ra thiệt hại nghiêm trọng cho hệ sinh thái biển mong manh.)","Every single species has a specific function within its natural [ecosystem]. (=Dịch: Mỗi loài sinh vật đều có một chức năng nhất định trong hệ sinh thái tự nhiên của nó.)","Deforestation poses an enormous threat to the local forest [ecosystem]. (=Dịch: Nạn phá rừng gây ra mối đe dọa to lớn đối với hệ sinh thái rừng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=ecosystem&lang=en-GB&ipa=%2F%CB%88i.ko%CA%8A%CB%8Cs%C9%AAs.t%C9%99m%2F","usAudio":"/ai_services/tts3/?q=ecosystem&lang=en-US&ipa=%2F%CB%88i.ko%CA%8A%CB%8Cs%C9%AAs.t%C9%99m%2F"},{"id":"lv_5_116","topic":"Nature and Environmental Protection","word":"edible","pos":"(adj)","ipa":"/ˈed.ə.bəl/","defVi":"có thể ăn được (không độc)","defEn":"suitable or safe for people to eat","examples":["Some wild mushrooms are [edible], but many others are extremely toxic. (=Dịch: Một số loại nấm dại có thể ăn được, nhưng nhiều loại khác lại vô cùng độc hại.)","The pastry chef decorated the wedding cake with delicate [edible] flowers. (=Dịch: Đầu bếp bánh ngọt đã trang trí chiếc bánh cưới bằng những bông hoa ăn được tinh tế.)","Researchers are developing [edible] packaging to reduce plastic waste. (=Dịch: Các nhà nghiên cứu đang phát triển bao bì ăn được để giảm thiểu rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=edible&lang=en-GB&ipa=%2F%CB%88ed.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=edible&lang=en-US&ipa=%2F%CB%88ed.%C9%99.b%C9%99l%2F"},{"id":"lv_5_117","topic":"Nature and Environmental Protection","word":"egypt","pos":"(n)","ipa":"/ˈiː.dʒɪpt/","defVi":"Ai Cập","defEn":"a country in northeastern Africa famous for its ancient civilization and monuments","examples":["Millions of tourists visit [Egypt] every year to see the ancient pyramids. (=Dịch: Hàng triệu du khách đến thăm Ai Cập mỗi năm để chiêm ngưỡng các kim tự tháp cổ đại.)","The Nile River has supported agriculture in [Egypt] for thousands of years. (=Dịch: Sông Nile đã nuôi dưỡng nền nông nghiệp ở Ai Cập suốt hàng ngàn năm qua.)","Historians study [Egypt] to understand the origins of early writing and engineering. (=Dịch: Các nhà sử học nghiên cứu Ai Cập để hiểu về nguồn gốc của chữ viết và kỹ thuật thời kỳ đầu.)"],"ukAudio":"/ai_services/tts3/?q=egypt&lang=en-GB&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F","usAudio":"/ai_services/tts3/?q=egypt&lang=en-US&ipa=%2F%CB%88i%CB%90.d%CA%92%C9%AApt%2F"},{"id":"lv_5_118","topic":"Nature and Environmental Protection","word":"emission","pos":"(n)","ipa":"/ɪˈmɪʃ.ən/","defVi":"sự phát thải, khí thải","defEn":"the production and discharge of something, especially gas or radiation","examples":["The rapid increase in carbon [emission] contributes heavily to global warming. (=Dịch: Sự gia tăng nhanh chóng của lượng phát thải carbon góp phần lớn vào sự nóng lên toàn cầu.)","Strict laws were introduced to regulate vehicle exhaust [emission] in big cities. (=Dịch: Các luật lệ nghiêm ngặt đã được ban hành để kiểm soát khí thải từ phương tiện giao thông ở các thành phố lớn.)","Industrial [emission] must be treated properly before being released into the atmosphere. (=Dịch: Khí thải công nghiệp phải được xử lý đúng cách trước khi thải ra ngoài khí quyển.)"],"ukAudio":"/ai_services/tts3/?q=emission&lang=en-GB&ipa=%2F%C9%AA%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emission&lang=en-US&ipa=%2F%C9%AA%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_119","topic":"Nature and Environmental Protection","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, giúp cho, tạo điều kiện","defEn":"to give someone or something the ability, authority, or means to do something","examples":["Scholarships [enable] talented students from low-income families to attend university. (=Dịch: Học bổng giúp các sinh viên tài năng có hoàn cảnh khó khăn có thể theo học đại học.)","Technological advances [enable] scientists to collect data more efficiently. (=Dịch: Những tiến bộ công nghệ cho phép các nhà khoa học thu thập dữ liệu hiệu quả hơn.)","The new highway will [enable] faster travel between the two cities. (=Dịch: Tuyến đường cao tốc mới sẽ tạo điều kiện cho việc di chuyển nhanh hơn giữa hai thành phố.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_5_120","topic":"Nature and Environmental Protection","word":"endangered","pos":"(adj)","ipa":"/ɪnˈdeɪn.dʒərd/","defVi":"có nguy cơ tuyệt chủng, bị đe dọa","defEn":"in danger of being harmed, lost, or becoming extinct","examples":["The giant panda was once classified as an [endangered] species. (=Dịch: Gấu trúc khổng lồ từng bị xếp vào nhóm loài có nguy cơ tuyệt chủng.)","Deforestation has put many native animals on the [endangered] list. (=Dịch: Nạn phá rừng đã khiến nhiều loài động vật bản địa bị đưa vào danh sách nguy cấp.)","Conservationists work tirelessly to protect [endangered] habitats worldwide. (=Dịch: Các nhà bảo tồn làm việc không mệt mỏi để bảo vệ các môi trường sống bị đe dọa trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=endangered&lang=en-GB&ipa=%2F%C9%AAn%CB%88de%C9%AAn.d%CA%92%C9%99rd%2F","usAudio":"/ai_services/tts3/?q=endangered&lang=en-US&ipa=%2F%C9%AAn%CB%88de%C9%AAn.d%CA%92%C9%99rd%2F"},{"id":"lv_5_121","topic":"Nature and Environmental Protection","word":"enormously","pos":"(adv)","ipa":"/ɪˈnɔːr.məs.li/","defVi":"vô cùng, hết sức","defEn":"to a very great degree; extremely","examples":["Online learning has helped students [enormously] during the pandemic. (=Dịch: Học trực tuyến đã giúp ích vô cùng nhiều cho học sinh trong thời gian đại dịch.)","The cost of living has increased [enormously] in the capital city. (=Dịch: Chi phí sinh hoạt đã tăng lên rất nhiều ở thành phố thủ đô.)","Her public speaking skills improved [enormously] after the workshop. (=Dịch: Kỹ năng nói trước công chúng của cô ấy đã tiến bộ vượt bậc sau hội thảo.)"],"ukAudio":"/ai_services/tts3/?q=enormously&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=enormously&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%94%CB%90r.m%C9%99s.li%2F"},{"id":"lv_5_122","topic":"Nature and Environmental Protection","word":"erosion","pos":"(n)","ipa":"/ɪˈroʊ.ʒən/","defVi":"sự xói mòn, sự bào mòn","defEn":"the gradual wearing away of rock or soil by the action of water, wind, or ice","examples":["Planting trees along riverbanks helps prevent soil [erosion]. (=Dịch: Trồng cây dọc theo bờ sông giúp ngăn ngừa xói mòn đất.)","Coastal [erosion] threatens many homes along the cliff edge. (=Dịch: Xói mòn bờ biển đang đe dọa nhiều ngôi nhà dọc theo mép vách đá.)","Wind and rain caused severe [erosion] to the ancient stone monument. (=Dịch: Gió và mưa đã gây ra sự bào mòn nghiêm trọng cho đài tưởng niệm bằng đá cổ kính.)"],"ukAudio":"/ai_services/tts3/?q=erosion&lang=en-GB&ipa=%2F%C9%AA%CB%88ro%CA%8A.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=erosion&lang=en-US&ipa=%2F%C9%AA%CB%88ro%CA%8A.%CA%92%C9%99n%2F"},{"id":"lv_5_123","topic":"Nature and Environmental Protection","word":"eruption","pos":"(n)","ipa":"/ɪˈrʌp.ʃən/","defVi":"sự phun trào (núi lửa), sự bùng nổ","defEn":"an act or instance of bursting forth, especially of a volcano","examples":["The sudden volcanic [eruption] forced thousands of residents to evacuate. (=Dịch: Vụ phun trào núi lửa bất ngờ đã buộc hàng ngàn cư dân phải sơ tán.)","Scientists monitor seismic activity to predict the next [eruption]. (=Dịch: Các nhà khoa học theo dõi hoạt động địa chấn để dự đoán đợt phun trào tiếp theo.)","The match ended with an [eruption] of cheers from the excited crowd. (=Dịch: Trận đấu kết thúc trong sự bùng nổ tiếng reo hò từ đám đông phấn khích.)"],"ukAudio":"/ai_services/tts3/?q=eruption&lang=en-GB&ipa=%2F%C9%AA%CB%88r%CA%8Cp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=eruption&lang=en-US&ipa=%2F%C9%AA%CB%88r%CA%8Cp.%CA%83%C9%99n%2F"},{"id":"lv_5_124","topic":"Nature and Environmental Protection","word":"ethanol","pos":"(n)","ipa":"/ˈeθ.ə.nɑːl/","defVi":"cồn ethanol, cồn etylic","defEn":"a type of alcohol often used as a biofuel or solvent","examples":["Many countries blend [ethanol] with gasoline to reduce greenhouse gas emissions. (=Dịch: Nhiều quốc gia pha trộn ethanol với xăng để giảm lượng khí thải nhà kính.)","The fuel contains ten percent [ethanol] derived from fermented corn. (=Dịch: Nhiên liệu này chứa mười phần trăm ethanol có nguồn gốc từ ngô lên men.)","Scientists are researching more sustainable ways to produce [ethanol] from agricultural waste. (=Dịch: Các nhà khoa học đang nghiên cứu những phương pháp bền vững hơn để sản xuất ethanol từ chất thải nông nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=ethanol&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%99.n%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=ethanol&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%99.n%C9%91%CB%90l%2F"},{"id":"lv_5_125","topic":"Nature and Environmental Protection","word":"european","pos":"(adj)","ipa":"/ˌjʊr.əˈpiː.ən/","defVi":"thuộc về châu Âu","defEn":"relating to the continent of Europe or its people","examples":["She has a strong interest in studying [European] history and art. (=Dịch: Cô ấy rất quan tâm đến việc nghiên cứu lịch sử và nghệ thuật châu Âu.)","Several [European] cities have introduced strict emission regulations for cars. (=Dịch: Một số thành phố châu Âu đã đưa ra các quy định nghiêm ngặt về khí thải đối với ô tô.)","The treaty aimed to strengthen cooperation among different [European] nations. (=Dịch: Hiệp ước nhằm tăng cường sự hợp tác giữa các quốc gia châu Âu khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=european&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=european&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99n%2F"},{"id":"lv_5_126","topic":"Nature and Environmental Protection","word":"europeans","pos":"(n)","ipa":"/ˌjʊr.əˈpiː.ənz/","defVi":"người châu Âu","defEn":"people who come from or live in Europe","examples":["Many [Europeans] travel to warmer countries during the winter months. (=Dịch: Nhiều người châu Âu đi du lịch đến các quốc gia ấm áp hơn trong những tháng mùa đông.)","Historically, [Europeans] established extensive trade networks across the globe. (=Dịch: Trong lịch sử, người châu Âu đã thiết lập các mạng lưới thương mại rộng lớn trên toàn cầu.)","Surveys show that [Europeans] place a high value on public healthcare systems. (=Dịch: Các cuộc khảo sát cho thấy người châu Âu rất coi trọng hệ thống chăm sóc sức khỏe cộng đồng.)"],"ukAudio":"/ai_services/tts3/?q=europeans&lang=en-GB&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F","usAudio":"/ai_services/tts3/?q=europeans&lang=en-US&ipa=%2F%CB%8Cj%CA%8Ar.%C9%99%CB%88pi%CB%90.%C9%99nz%2F"},{"id":"lv_5_127","topic":"Nature and Environmental Protection","word":"evaporate","pos":"(v)","ipa":"/ɪˈvæp.ə.reɪt/","defVi":"bốc hơi, bay hơi","defEn":"to change from a liquid into gas or vapor; to disappear gradually","examples":["Puddles on the road begin to [evaporate] quickly once the sun comes out. (=Dịch: Những vũng nước trên đường bắt đầu bốc hơi nhanh chóng khi mặt trời ló rạng.)","Heat will cause the water in the pan to [evaporate] completely. (=Dịch: Nhiệt độ sẽ làm cho nước trong chảo bay hơi hoàn toàn.)","All his fears seemed to [evaporate] when he saw his family waiting for him. (=Dịch: Mọi nỗi sợ hãi của anh dường như tan biến khi anh thấy gia đình đang đợi mình.)"],"ukAudio":"/ai_services/tts3/?q=evaporate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaporate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F"},{"id":"lv_5_128","topic":"Nature and Environmental Protection","word":"evolutionary","pos":"(adj)","ipa":"/ˌev.əˈluː.ʃəˌner.i/","defVi":"thuộc về tiến hóa, mang tính tiến hóa","defEn":"relating to the gradual development of plants, animals, or ideas over time","examples":["Scientists study fossils to understand the [evolutionary] history of birds. (=Dịch: Các nhà khoa học nghiên cứu hóa thạch để hiểu rõ lịch sử tiến hóa của loài chim.)","The species developed sharp claws as an [evolutionary] adaptation for hunting. (=Dịch: Loài này đã phát triển móng vuốt sắc nhọn như một sự thích nghi tiến hóa để săn mồi.)","His theory explains the [evolutionary] changes in human behavior over centuries. (=Dịch: Lý thuyết của ông giải thích những thay đổi tiến hóa trong hành vi con người qua nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=evolutionary&lang=en-GB&ipa=%2F%CB%8Cev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99%CB%8Cner.i%2F","usAudio":"/ai_services/tts3/?q=evolutionary&lang=en-US&ipa=%2F%CB%8Cev.%C9%99%CB%88lu%CB%90.%CA%83%C9%99%CB%8Cner.i%2F"},{"id":"lv_5_129","topic":"Nature and Environmental Protection","word":"examination","pos":"(n)","ipa":"/ɪɡˌzæm.əˈneɪ.ʃən/","defVi":"sự kiểm tra, sự xem xét kỹ lưỡng; kỳ thi","defEn":"a detailed inspection, study, or test of knowledge or ability","examples":["A thorough medical [examination] revealed no serious underlying health problems. (=Dịch: Một cuộc kiểm tra y tế kỹ lưỡng cho thấy không có vấn đề sức khỏe tiềm ẩn nghiêm trọng nào.)","Candidates must prepare thoroughly before taking the final entrance [examination]. (=Dịch: Các thí sinh phải chuẩn bị kỹ lưỡng trước khi tham gia kỳ thi tuyển sinh cuối cùng.)","Close [examination] of the forensic evidence provided vital clues for the detectives. (=Dịch: Sự xem xét kỹ lưỡng bằng chứng pháp y đã cung cấp những manh mối quan trọng cho các thám tử.)"],"ukAudio":"/ai_services/tts3/?q=examination&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%8Cz%C3%A6m.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=examination&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%8Cz%C3%A6m.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_130","topic":"Nature and Environmental Protection","word":"existence","pos":"(n)","ipa":"/ɪɡˈzɪs.təns/","defVi":"sự tồn tại, sự hiện diện","defEn":"the state or fact of living or being real","examples":["Many scientists believe in the [existence] of water on other planets. (=Dịch: Nhiều nhà khoa học tin vào sự tồn tại của nước trên các hành tinh khác.)","Pollution poses a serious threat to the continued [existence] of marine wildlife. (=Dịch: Ô nhiễm đe dọa nghiêm trọng đến sự tồn tại lâu dài của động vật hoang dã biển.)","The ancient monument has been in [existence] for more than two thousand years. (=Dịch: Di tích cổ này đã tồn tại hơn hai nghìn năm.)"],"ukAudio":"/ai_services/tts3/?q=existence&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAs.t%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=existence&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%AAs.t%C9%99ns%2F"},{"id":"lv_5_131","topic":"Nature and Environmental Protection","word":"expansion","pos":"(n)","ipa":"/ɪkˈspæn.ʃən/","defVi":"sự mở rộng, sự bành trướng, sự phát triển","defEn":"the act of becoming larger or spreading out in size, area, or volume","examples":["The company announced the [expansion] of its retail network into Asia. (=Dịch: Công ty đã công bố việc mở rộng mạng lưới bán lẻ sang châu Á.)","Rapid urban [expansion] can lead to severe environmental problems. (=Dịch: Sự mở rộng đô thị nhanh chóng có thể dẫn đến các vấn đề môi trường nghiêm trọng.)","Thermal [expansion] causes metal rails to lengthen in hot weather. (=Dịch: Sự giãn nở vì nhiệt làm cho đường ray kim loại dài ra trong thời tiết nóng.)"],"ukAudio":"/ai_services/tts3/?q=expansion&lang=en-GB&ipa=%2F%C9%AAk%CB%88sp%C3%A6n.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expansion&lang=en-US&ipa=%2F%C9%AAk%CB%88sp%C3%A6n.%CA%83%C9%99n%2F"},{"id":"lv_5_132","topic":"Nature and Environmental Protection","word":"expedition","pos":"(n)","ipa":"/ˌɛk.spəˈdɪʃ.ən/","defVi":"cuộc thám hiểm, chuyến khảo sát","defEn":"an organized journey made for a particular purpose, especially exploration or scientific research","examples":["The scientists launched an [expedition] to explore the uncharted rainforest. (=Dịch: Các nhà khoa học đã phát động một cuộc thám hiểm để khám phá khu rừng nhiệt đới chưa được lập bản đồ.)","He documented his Arctic [expedition] through a series of photographs. (=Dịch: Anh ấy đã ghi lại chuyến thám hiểm Bắc Cực của mình qua một loạt các bức ảnh.)","The team packed specialized gear for their upcoming climbing [expedition]. (=Dịch: Cả đội đã đóng gói các thiết bị chuyên dụng cho chuyến thám hiểm leo núi sắp tới của họ.)"],"ukAudio":"/ai_services/tts3/?q=expedition&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%99%CB%88d%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expedition&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%99%CB%88d%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_5_133","topic":"Nature and Environmental Protection","word":"exploit","pos":"(v)","ipa":"/ɪk.ˈsplɔɪt/","defVi":"khai thác, tận dụng","defEn":"to use something fully in order to get an advantage or profit","examples":["The company aims to [exploit] renewable energy sources like wind and solar power. (=Dịch: Công ty đặt mục tiêu khai thác các nguồn năng lượng tái tạo như năng lượng gió và mặt trời.)","It is unethical to [exploit] vulnerable workers for cheap labor. (=Dịch: Bóc lột những người lao động yếu thế để có nhân công giá rẻ là hành vi phi đạo đức.)","The software developer found a way to [exploit] the system's security loophole. (=Dịch: Nhà phát triển phần mềm đã tìm ra cách khai thác lỗ hổng bảo mật của hệ thống.)"],"ukAudio":"/ai_services/tts3/?q=exploit&lang=en-GB&ipa=%2F%C9%AAk.%CB%88spl%C9%94%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=exploit&lang=en-US&ipa=%2F%C9%AAk.%CB%88spl%C9%94%C9%AAt%2F"},{"id":"lv_5_134","topic":"Nature and Environmental Protection","word":"exploration","pos":"(n)","ipa":"/ˌek.spləˈreɪ.ʃən/","defVi":"sự thám hiểm, sự thăm dò, sự khám phá","defEn":"the action of traveling through an unfamiliar area in order to learn about it","examples":["Space [exploration] requires significant financial investment and advanced technology. (=Dịch: Thám hiểm không gian đòi hỏi sự đầu tư tài chính lớn cùng công nghệ tiên tiến.)","The deep-sea [exploration] team discovered several new marine species. (=Dịch: Đội thám hiểm biển sâu đã phát hiện ra một số loài sinh vật biển mới.)","Oil [exploration] in the arctic region remains highly controversial. (=Dịch: Hoạt động thăm dò dầu khí ở vùng Bắc Cực vẫn còn gây nhiều tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=exploration&lang=en-GB&ipa=%2F%CB%8Cek.spl%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=exploration&lang=en-US&ipa=%2F%CB%8Cek.spl%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_135","topic":"Nature and Environmental Protection","word":"explorer","pos":"(n)","ipa":"/ɪkˈsplɔːr.ɚ/","defVi":"nhà thám hiểm","defEn":"a person who travels to unfamiliar places in order to discover new things","examples":["The brave [explorer] ventured deep into the uncharted regions of the Amazon rainforest. (=Dịch: Nhà thám hiểm dũng cảm đã dấn thân sâu vào những vùng chưa được khám phá của rừng nhiệt đới Amazon.)","Every modern [explorer] relies on advanced satellite navigation and survival gear. (=Dịch: Mỗi nhà thám hiểm hiện đại đều dựa vào hệ thống định vị vệ tinh tiên tiến và thiết bị sinh tồn.)","The museum displays journals written by an Arctic [explorer] during his expeditions. (=Dịch: Bảo tàng trưng bày các cuốn nhật ký được viết bởi một nhà thám hiểm Bắc Cực trong các chuyến hành trình của ông.)"],"ukAudio":"/ai_services/tts3/?q=explorer&lang=en-GB&ipa=%2F%C9%AAk%CB%88spl%C9%94%CB%90r.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=explorer&lang=en-US&ipa=%2F%C9%AAk%CB%88spl%C9%94%CB%90r.%C9%9A%2F"},{"id":"lv_5_136","topic":"Nature and Environmental Protection","word":"expose","pos":"(v)","ipa":"/ɪkˈspoʊz/","defVi":"phơi bày, để lộ, tiếp xúc với","defEn":"to leave something uncovered or unprotected, especially to something harmful","examples":["Do not [expose] your skin to direct sunlight for extended periods. (=Dịch: Đừng phơi da dưới ánh nắng trực tiếp trong thời gian dài.)","The documentary aimed to [expose] corruption within the local government. (=Dịch: Bộ phim tài liệu nhằm mục đích vạch trần nạn tham nhũng trong chính quyền địa phương.)","Living abroad will [expose] students to diverse cultures and traditions. (=Dịch: Sống ở nước ngoài sẽ giúp sinh viên tiếp xúc với các nền văn hóa và truyền thống đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=expose&lang=en-GB&ipa=%2F%C9%AAk%CB%88spo%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=expose&lang=en-US&ipa=%2F%C9%AAk%CB%88spo%CA%8Az%2F"},{"id":"lv_5_137","topic":"Nature and Environmental Protection","word":"extensive","pos":"(adj)","ipa":"/ɪkˈsten.sɪv/","defVi":"sâu rộng, quy mô lớn, bao quát","defEn":"covering a large area; having a wide scope or range","examples":["The storm caused [extensive] damage to the coastal town. (=Dịch: Cơn bão đã gây ra thiệt hại trên diện rộng cho thị trấn ven biển.)","She has [extensive] knowledge of international copyright law. (=Dịch: Cô ấy có kiến thức sâu rộng về luật bản quyền quốc tế.)","The building underwent [extensive] renovations before reopening. (=Dịch: Tòa nhà đã trải qua quá trình cải tạo quy mô lớn trước khi mở cửa trở lại.)"],"ukAudio":"/ai_services/tts3/?q=extensive&lang=en-GB&ipa=%2F%C9%AAk%CB%88sten.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=extensive&lang=en-US&ipa=%2F%C9%AAk%CB%88sten.s%C9%AAv%2F"},{"id":"lv_5_138","topic":"Nature and Environmental Protection","word":"extinct","pos":"(adj)","ipa":"/ɪkˈstɪŋkt/","defVi":"tuyệt chủng","defEn":"no longer existing or living anywhere in the world","examples":["Dinosaurs became [extinct] millions of years ago. (=Dịch: Khủng long đã tuyệt chủng hàng triệu năm trước.)","Deforestation threatens to drive several rare amphibians [extinct]. (=Dịch: Nạn phá rừng đe dọa đẩy một số loài lưỡng cư quý hiếm vào cảnh tuyệt chủng.)","Conservationists are working tirelessly to prevent the tiger from becoming [extinct]. (=Dịch: Các nhà bảo tồn đang nỗ lực không ngừng nghỉ để ngăn loài hổ khỏi bị tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=extinct&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bkt%2F","usAudio":"/ai_services/tts3/?q=extinct&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bkt%2F"},{"id":"lv_5_139","topic":"Nature and Environmental Protection","word":"extinction","pos":"(n)","ipa":"/ɪkˈstɪŋk.ʃən/","defVi":"sự tuyệt chủng","defEn":"the state or situation that results when a species no longer has any living members","examples":["Poaching and habitat loss have driven several rhino species close to [extinction]. (=Dịch: Nạn săn trộm và mất môi trường sống đã đẩy một số loài tê giác đến bờ vực tuyệt chủng.)","Scientists fear that climate change could trigger a mass [extinction] event. (=Dịch: Các nhà khoa học lo ngại rằng biến đổi khí hậu có thể châm ngòi cho một sự kiện tuyệt chủng hàng loạt.)","Conservation programs aim to save endangered sea turtles from total [extinction]. (=Dịch: Các chương trình bảo tồn nhằm cứu các loài rùa biển có nguy cơ tuyệt chủng khỏi sự tuyệt chủng hoàn toàn.)"],"ukAudio":"/ai_services/tts3/?q=extinction&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=extinction&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%AA%C5%8Bk.%CA%83%C9%99n%2F"},{"id":"lv_5_140","topic":"Nature and Environmental Protection","word":"extract","pos":"(v)","ipa":"/ɪkˈstrækt/","defVi":"chiết xuất, rút ra, khai thác","defEn":"to remove or obtain a substance from something by a special method","examples":["Specialists use modern techniques to [extract] essential oils from fresh flowers. (=Dịch: Các chuyên gia sử dụng các kỹ thuật hiện đại để chiết xuất tinh dầu từ hoa tươi.)","The mining corporation plans to [extract] valuable minerals from the mountain range. (=Dịch: Tập đoàn khai thác mỏ có kế hoạch khai thác các khoáng sản quý giá từ dãy núi.)","Researchers hope to [extract] useful data from the completed survey responses. (=Dịch: Các nhà nghiên cứu hy vọng sẽ trích xuất được dữ liệu hữu ích từ các câu trả lời khảo sát đã hoàn thành.)"],"ukAudio":"/ai_services/tts3/?q=extract&lang=en-GB&ipa=%2F%C9%AAk%CB%88str%C3%A6kt%2F","usAudio":"/ai_services/tts3/?q=extract&lang=en-US&ipa=%2F%C9%AAk%CB%88str%C3%A6kt%2F"},{"id":"lv_5_141","topic":"Nature and Environmental Protection","word":"facial","pos":"(adj)","ipa":"/ˈfeɪ.ʃəl/","defVi":"thuộc về khuôn mặt","defEn":"connected with or located on a person's face","examples":["Modern smartphones use [facial] recognition to unlock the screen. (=Dịch: Điện thoại thông minh hiện đại sử dụng tính năng nhận diện khuôn mặt để mở khóa màn hình.)","His subtle [facial] expressions showed that he was not fully convinced. (=Dịch: Những biểu cảm khuôn mặt tinh tế của anh ấy cho thấy anh chưa hoàn toàn bị thuyết phục.)","She visited the spa yesterday for a relaxing [facial] treatment. (=Dịch: Hôm qua cô ấy đã đến spa để thực hiện một liệu trình chăm sóc da mặt thư giãn.)"],"ukAudio":"/ai_services/tts3/?q=facial&lang=en-GB&ipa=%2F%CB%88fe%C9%AA.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=facial&lang=en-US&ipa=%2F%CB%88fe%C9%AA.%CA%83%C9%99l%2F"},{"id":"lv_5_142","topic":"Nature and Environmental Protection","word":"feather","pos":"(n)","ipa":"/ˈfeð.ɚ/","defVi":"lông vũ, lông chim","defEn":"one of the soft, light structures that grow from a bird's skin and form its plumage","examples":["She picked up a beautiful peacock [feather] from the forest floor. (=Dịch: Cô ấy nhặt được một chiếc lông công xinh đẹp từ nền rừng.)","Each [feather] helps keep the bird warm and enables it to fly smoothly. (=Dịch: Mỗi chiếc lông vũ giúp giữ ấm cho chim và giúp nó bay lượn êm ái.)","The pillow was stuffed with soft duck [feather] down. (=Dịch: Chiếc gối được nhồi bằng lông tơ vịt mềm mại.)"],"ukAudio":"/ai_services/tts3/?q=feather&lang=en-GB&ipa=%2F%CB%88fe%C3%B0.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=feather&lang=en-US&ipa=%2F%CB%88fe%C3%B0.%C9%9A%2F"},{"id":"lv_5_143","topic":"Nature and Environmental Protection","word":"fertile","pos":"(adj)","ipa":"/ˈfɜːr.təl/","defVi":"màu mỡ, phì nhiêu; có khả năng sinh sản","defEn":"able to produce good crops or plants, or capable of producing offspring","examples":["The river valley has extremely [fertile] soil that supports agriculture. (=Dịch: Thung lũng ven sông có đất đai vô cùng màu mỡ hỗ trợ canh tác nông nghiệp.)","A warm climate and [fertile] ground allow farmers to harvest multiple crops a year. (=Dịch: Khí hậu ấm áp và đất đai màu mỡ cho phép nông dân thu hoạch nhiều vụ mùa mỗi năm.)","Scientists are researching how to keep farmland [fertile] without excessive chemical use. (=Dịch: Các nhà khoa học đang nghiên cứu cách giữ cho đất trồng trọt luôn màu mỡ mà không cần lạm dụng hóa chất.)"],"ukAudio":"/ai_services/tts3/?q=fertile&lang=en-GB&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fertile&lang=en-US&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l%2F"},{"id":"lv_5_144","topic":"Nature and Environmental Protection","word":"fertiliser","pos":"(n)","ipa":"/ˈfɜːr.təl.aɪ.zər/","defVi":"phân bón","defEn":"a natural or chemical substance added to soil to help plants grow","examples":["Farmers use chemical [fertiliser] to increase their crop yields. (=Dịch: Nông dân sử dụng phân bón hóa học để tăng năng suất cây trồng.)","Excessive use of [fertiliser] can contaminate local water sources. (=Dịch: Việc sử dụng phân bón quá mức có thể làm ô nhiễm các nguồn nước địa phương.)","Organic compost serves as an excellent natural [fertiliser]. (=Dịch: Phân hữu cơ ủ mục đóng vai trò như một loại phân bón tự nhiên tuyệt vời.)"],"ukAudio":"/ai_services/tts3/?q=fertiliser&lang=en-GB&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l.a%C9%AA.z%C9%99r%2F","usAudio":"/ai_services/tts3/?q=fertiliser&lang=en-US&ipa=%2F%CB%88f%C9%9C%CB%90r.t%C9%99l.a%C9%AA.z%C9%99r%2F"},{"id":"lv_5_145","topic":"Nature and Environmental Protection","word":"fig","pos":"(n)","ipa":"/fɪɡ/","defVi":"quả sung ngọt, quả vả","defEn":"a soft, sweet fruit with many small seeds, often eaten fresh or dried","examples":["Fresh [fig] pairs exceptionally well with goat cheese and honey. (=Dịch: Quả sung ngọt tươi kết hợp rất tuyệt vời với phô mai dê và mật ong.)","They planted a [fig] tree in the sunniest corner of their backyard. (=Dịch: Họ đã trồng một cây sung ngọt ở góc nhiều nắng nhất trong sân sau.)","Dried [fig] slices make a healthy and convenient snack during long hikes. (=Dịch: Những lát sung ngọt sấy khô là món ăn nhẹ lành mạnh và tiện lợi trong các chuyến đi bộ dài.)"],"ukAudio":"/ai_services/tts3/?q=fig&lang=en-GB&ipa=%2Ff%C9%AA%C9%A1%2F","usAudio":"/ai_services/tts3/?q=fig&lang=en-US&ipa=%2Ff%C9%AA%C9%A1%2F"},{"id":"lv_5_146","topic":"Nature and Environmental Protection","word":"fin","pos":"(n)","ipa":"/fɪn/","defVi":"vây cá","defEn":"a thin, flat part that sticks out from the body of a fish, used for swimming and balance","examples":["The shark cut through the water with its dorsal [fin] clearly visible above the surface. (=Dịch: Con cá mập rẽ nước bơi với vây lưng lộ rõ trên mặt nước.)","A fish uses its [fin] to steer and maintain balance while swimming. (=Dịch: Cá sử dụng vây để chuyển hướng và giữ thăng bằng khi bơi.)","Scuba divers wear a swim [fin] on each foot to move through the water more easily. (=Dịch: Thợ lặn đeo vây bơi ở mỗi bàn chân để di chuyển dưới nước dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=fin&lang=en-GB&ipa=%2Ff%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=fin&lang=en-US&ipa=%2Ff%C9%AAn%2F"},{"id":"lv_5_147","topic":"Nature and Environmental Protection","word":"firm","pos":"(n)","ipa":"/fɜːrm/","defVi":"công ty, hãng","defEn":"a business organization or company, especially one providing professional services","examples":["She recently joined a prestigious law [firm] in downtown Chicago. (=Dịch: Gần đây cô ấy đã gia nhập một công ty luật danh tiếng ở trung tâm thành phố Chicago.)","The architectural [firm] designed several award-winning public libraries. (=Dịch: Công ty kiến trúc đã thiết kế một số thư viện công cộng từng đạt giải thưởng.)","He spent ten years working for an international accounting [firm]. (=Dịch: Anh ấy đã dành mười năm làm việc cho một công ty kiểm toán quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=firm&lang=en-GB&ipa=%2Ff%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=firm&lang=en-US&ipa=%2Ff%C9%9C%CB%90rm%2F"},{"id":"lv_5_148","topic":"Nature and Environmental Protection","word":"flooding","pos":"(n)","ipa":"/ˈflʌd.ɪŋ/","defVi":"nạn ngập lụt, tình trạng ngập úng","defEn":"a situation in which an area becomes covered with water, usually after heavy rain","examples":["Poor drainage systems often cause severe [flooding] in the city during storms. (=Dịch: Hệ thống thoát nước kém thường gây ngập lụt nghiêm trọng trong thành phố vào mùa bão.)","The low-lying coastal areas are extremely vulnerable to seasonal [flooding]. (=Dịch: Các vùng ven biển trũng thấp rất dễ bị tổn thương trước tình trạng ngập lụt theo mùa.)","Authorities issued warnings about flash [flooding] after continuous torrential rain. (=Dịch: Chính quyền đã phát đi cảnh báo về lũ quét sau những đợt mưa xối xả kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=flooding&lang=en-GB&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=flooding&lang=en-US&ipa=%2F%CB%88fl%CA%8Cd.%C9%AA%C5%8B%2F"},{"id":"lv_5_149","topic":"Nature and Environmental Protection","word":"fluid","pos":"(adj)","ipa":"/ˈflu.ɪd/","defVi":"linh hoạt, uyển chuyển; dễ thay đổi","defEn":"smooth, continuous, and easy; or likely to change easily","examples":["The dancer's movements were remarkably [fluid] and graceful. (=Dịch: Những động tác của vũ công vô cùng uyển chuyển và duyên dáng.)","The political situation in the region remains highly [fluid]. (=Dịch: Tình hình chính trị trong khu vực vẫn còn biến động rất nhiều.)","He switched between languages with [fluid] ease during the meeting. (=Dịch: Anh ấy chuyển đổi giữa các ngôn ngữ một cách trôi chảy và dễ dàng trong cuộc họp.)"],"ukAudio":"/ai_services/tts3/?q=fluid&lang=en-GB&ipa=%2F%CB%88flu.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=fluid&lang=en-US&ipa=%2F%CB%88flu.%C9%AAd%2F"},{"id":"lv_5_150","topic":"Nature and Environmental Protection","word":"fog","pos":"(n)","ipa":"/fɑːɡ/","defVi":"sương mù","defEn":"a thick cloud of tiny water droplets suspended in the air near the earth's surface that reduces visibility","examples":["The morning [fog] made it difficult for drivers to see more than a few meters ahead. (=Dịch: Lớp sương mù buổi sáng khiến các tài xế khó nhìn xa hơn vài mét.)","Flights were delayed because dense [fog] covered the airport runway. (=Dịch: Các chuyến bay bị hoãn vì sương mù dày đặc bao phủ đường băng sân bay.)","By midday, the sun came out and the [fog] began to clear. (=Dịch: Đến trưa, mặt trời ló dạng và sương mù bắt đầu tan dần.)"],"ukAudio":"/ai_services/tts3/?q=fog&lang=en-GB&ipa=%2Ff%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=fog&lang=en-US&ipa=%2Ff%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_151","topic":"Nature and Environmental Protection","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập lại","defEn":"to bend one part of something over another part so that it becomes smaller or neater","examples":["Please help me [fold] the clean laundry and put it into the drawer. (=Dịch: Làm ơn giúp tôi gấp quần áo sạch và cất vào ngăn kéo nhé.)","She took a piece of paper and began to [fold] it into an origami bird. (=Dịch: Cô ấy lấy một mảnh giấy và bắt đầu gấp nó thành một con chim origami.)","You should [fold] the map carefully before putting it back into your bag. (=Dịch: Bạn nên gấp tấm bản đồ lại cẩn thận trước khi cất nó vào túi.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_5_152","topic":"Nature and Environmental Protection","word":"footwear","pos":"(n)","ipa":"/ˈfʊt.wɛr/","defVi":"Giày dép, đồ đi chân.","defEn":"Things that people wear on their feet, such as shoes, boots, and sandals.","examples":["You should wear appropriate [footwear] when hiking in the mountains. (=Dịch: Bạn nên mang giày dép phù hợp khi đi bộ đường dài trên núi.)","The store offers a wide selection of sports [footwear]. (=Dịch: Cửa hàng cung cấp nhiều lựa chọn về các loại giày dép thể thao.)","Comfortable [footwear] is essential for people who stand all day. (=Dịch: Giày dép thoải mái là điều thiết yếu đối với những người phải đứng cả ngày.)"],"ukAudio":"/ai_services/tts3/?q=footwear&lang=en-GB&ipa=%2F%CB%88f%CA%8At.w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=footwear&lang=en-US&ipa=%2F%CB%88f%CA%8At.w%C9%9Br%2F"},{"id":"lv_5_153","topic":"Nature and Environmental Protection","word":"fossil","pos":"(n)","ipa":"/ˈfɑː.səl/","defVi":"hóa thạch","defEn":"the preserved remains or traces of an ancient plant or animal embedded in rock","examples":["The museum display featured a remarkably intact dinosaur [fossil]. (=Dịch: Khu trưng bày của bảo tàng có một mẫu hóa thạch khủng long còn nguyên vẹn đáng kinh ngạc.)","Geologists discovered a marine [fossil] high up in the mountain range. (=Dịch: Các nhà địa chất đã phát hiện ra một hóa thạch sinh vật biển ở tít trên dãy núi cao.)","Burning [fossil] fuels contributes significantly to global greenhouse gas emissions. (=Dịch: Việc đốt nhiên liệu hóa thạch đóng góp đáng kể vào lượng khí thải nhà kính toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=fossil&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fossil&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90.s%C9%99l%2F"},{"id":"lv_5_154","topic":"Nature and Environmental Protection","word":"freeze","pos":"(v)","ipa":"/friːz/","defVi":"Đóng băng; làm đông lạnh.","defEn":"To turn into ice or a solid state as a result of extreme cold.","examples":["Water will [freeze] and expand when the temperature drops to zero degrees Celsius. (=Dịch: Nước sẽ đóng băng và giãn nở khi nhiệt độ giảm xuống không độ C.)","You can [freeze] leftover soup to enjoy at a later date. (=Dịch: Bạn có thể đông lạnh phần súp còn thừa để thưởng thức sau này.)","The lake began to [freeze] as soon as the severe cold snap arrived. (=Dịch: Mặt hồ bắt đầu đóng băng ngay khi đợt rét đậm ập đến.)"],"ukAudio":"/ai_services/tts3/?q=freeze&lang=en-GB&ipa=%2Ffri%CB%90z%2F","usAudio":"/ai_services/tts3/?q=freeze&lang=en-US&ipa=%2Ffri%CB%90z%2F"},{"id":"lv_5_155","topic":"Nature and Environmental Protection","word":"frequency","pos":"(n)","ipa":"/ˈfri.kwən.si/","defVi":"tần suất, tần số","defEn":"the rate at which something happens or is repeated over a particular period","examples":["The [frequency] of natural disasters has increased in recent years. (=Dịch: Tần suất xảy ra các thảm họa thiên nhiên đã gia tăng trong những năm gần đây.)","You should adjust the [frequency] of your workouts based on your fitness level. (=Dịch: Bạn nên điều chỉnh tần suất tập luyện dựa trên thể lực của mình.)","The radio station operates on a very high [frequency]. (=Dịch: Trạm phát thanh hoạt động ở một tần số rất cao.)"],"ukAudio":"/ai_services/tts3/?q=frequency&lang=en-GB&ipa=%2F%CB%88fri.kw%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=frequency&lang=en-US&ipa=%2F%CB%88fri.kw%C9%99n.si%2F"},{"id":"lv_5_156","topic":"Nature and Environmental Protection","word":"frequent","pos":"(adj)","ipa":"/ˈfriː.kwənt/","defVi":"thường xuyên, hay xảy ra","defEn":"happening often or repeating at short intervals","examples":["He is a [frequent] traveler on international flights for business. (=Dịch: Anh ấy là hành khách thường xuyên trên các chuyến bay quốc tế phục vụ công việc.)","The coastal region experiences [frequent] storms during the autumn months. (=Dịch: Khu vực ven biển thường xuyên hứng chịu bão trong những tháng mùa thu.)","Making [frequent] mistakes is a completely normal part of learning a new skill. (=Dịch: Mắc lỗi thường xuyên là một phần hoàn toàn bình thường khi học một kỹ năng mới.)"],"ukAudio":"/ai_services/tts3/?q=frequent&lang=en-GB&ipa=%2F%CB%88fri%CB%90.kw%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=frequent&lang=en-US&ipa=%2F%CB%88fri%CB%90.kw%C9%99nt%2F"},{"id":"lv_5_157","topic":"Nature and Environmental Protection","word":"frighten","pos":"(v)","ipa":"/ˈfraɪ.tən/","defVi":"làm hoảng sợ, dọa dẫm","defEn":"to make someone feel afraid or shocked","examples":["Sudden loud noises can easily [frighten] young children. (=Dịch: Những tiếng động lớn bất ngờ có thể dễ dàng làm trẻ nhỏ hoảng sợ.)","The dark forest did not [frighten] the brave explorer. (=Dịch: Khu rừng tăm tối không hề làm nhà thám hiểm dũng cảm sợ hãi.)","They tried to [frighten] away the birds with a scarecrow. (=Dịch: Họ đã cố gắng xua đuổi lũ chim bằng một con bù nhìn.)"],"ukAudio":"/ai_services/tts3/?q=frighten&lang=en-GB&ipa=%2F%CB%88fra%C9%AA.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=frighten&lang=en-US&ipa=%2F%CB%88fra%C9%AA.t%C9%99n%2F"},{"id":"lv_5_158","topic":"Nature and Environmental Protection","word":"gardener","pos":"(n)","ipa":"/ˈɡɑːr.dən.ɚ/","defVi":"người làm vườn","defEn":"a person who tends, cultivates, and cares for a garden","examples":["The [gardener] pruned the rose bushes to encourage new spring blooms. (=Dịch: Người làm vườn đã cắt tỉa các bụi hoa hồng để kích thích hoa nở vào mùa xuân.)","She hired a skilled [gardener] to design a sustainable landscape. (=Dịch: Cô ấy đã thuê một người làm vườn có tay nghề để thiết kế cảnh quan bền vững.)","An experienced [gardener] knows exactly when to plant each type of vegetable. (=Dịch: Một người làm vườn giàu kinh nghiệm biết chính xác khi nào nên gieo trồng từng loại rau củ.)"],"ukAudio":"/ai_services/tts3/?q=gardener&lang=en-GB&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gardener&lang=en-US&ipa=%2F%CB%88%C9%A1%C9%91%CB%90r.d%C9%99n.%C9%9A%2F"},{"id":"lv_5_159","topic":"Nature and Environmental Protection","word":"gene","pos":"(n)","ipa":"/dʒiːn/","defVi":"gen (đơn vị di truyền)","defEn":"a basic unit of heredity made of DNA that determines particular traits","examples":["Scientists identified the specific [gene] responsible for drought resistance in crops. (=Dịch: Các nhà khoa học đã xác định được gen cụ thể quy định khả năng chịu hạn ở cây trồng.)","Children inherit each [gene] from a combination of both biological parents. (=Dịch: Trẻ em thừa hưởng mỗi gen từ sự kết hợp của cả cha lẫn mẹ ruột.)","Advances in [gene] editing offer new possibilities for curing inherited disorders. (=Dịch: Những tiến bộ trong chỉnh sửa gen mở ra những tiềm năng mới để chữa các rối loạn di truyền.)"],"ukAudio":"/ai_services/tts3/?q=gene&lang=en-GB&ipa=%2Fd%CA%92i%CB%90n%2F","usAudio":"/ai_services/tts3/?q=gene&lang=en-US&ipa=%2Fd%CA%92i%CB%90n%2F"},{"id":"lv_5_160","topic":"Nature and Environmental Protection","word":"genetic","pos":"(adj)","ipa":"/dʒəˈnet̬.ɪk/","defVi":"(thuộc) di truyền, gen","defEn":"connected with genes or genetics, the study of heredity","examples":["Scientists are studying the [genetic] factors that influence human longevity. (=Dịch: Các nhà khoa học đang nghiên cứu các yếu tố di truyền ảnh hưởng đến tuổi thọ của con người.)","Some diseases are caused by a [genetic] defect passed down through generations. (=Dịch: Một số bệnh tật bị gây ra bởi khiếm khuyết di truyền truyền qua nhiều thế hệ.)","The crops have undergone [genetic] modification to resist pests. (=Dịch: Cây trồng đã được biến đổi di truyền để kháng sâu bệnh.)"],"ukAudio":"/ai_services/tts3/?q=genetic&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=genetic&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F"},{"id":"lv_5_161","topic":"Nature and Environmental Protection","word":"germany","pos":"(n)","ipa":"/ˈdʒɝː.mə.ni/","defVi":"nước Đức, Cộng hòa Liên bang Đức","defEn":"a major country in Central Europe known for its engineering and culture","examples":["Many international students choose to study engineering in [germany]. (=Dịch: Nhiều sinh viên quốc tế chọn học ngành kỹ thuật tại nước Đức.)","Renewable energy adoption has expanded rapidly across [germany] over the last decade. (=Dịch: Việc áp dụng năng lượng tái tạo đã mở rộng nhanh chóng trên khắp nước Đức trong thập kỷ qua.)","The automotive sector plays a vital role in the national economy of [germany]. (=Dịch: Ngành công nghiệp ô tô đóng vai trò sống còn trong nền kinh tế quốc dân của Đức.)"],"ukAudio":"/ai_services/tts3/?q=germany&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=germany&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.m%C9%99.ni%2F"},{"id":"lv_5_162","topic":"Nature and Environmental Protection","word":"germinate","pos":"(v)","ipa":"/ˈdʒɜːr.mə.neɪt/","defVi":"nảy mầm, nảy sinh","defEn":"to start growing or to develop into a plant from a seed","examples":["Seeds require adequate moisture and warmth in order to [germinate] properly. (=Dịch: Hạt giống cần đủ độ ẩm và độ ấm để có thể nảy mầm một cách thuận lợi.)","The tomato seeds took nearly two weeks to [germinate] in the greenhouse. (=Dịch: Hạt giống cà chua mất gần hai tuần để nảy mầm trong nhà kính.)","An innovative idea can [germinate] in the mind during a casual discussion. (=Dịch: Một ý tưởng sáng tạo có thể nảy sinh trong tâm trí khi đang trò chuyện bình thường.)"],"ukAudio":"/ai_services/tts3/?q=germinate&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=germinate&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99.ne%C9%AAt%2F"},{"id":"lv_5_163","topic":"Nature and Environmental Protection","word":"germination","pos":"(n)","ipa":"/ˌdʒɜːr.məˈneɪ.ʃən/","defVi":"sự nảy mầm","defEn":"the development of a plant from a seed or spore after a period of dormancy","examples":["Moisture and warmth are two essential factors for seed [germination]. (=Dịch: Độ ẩm và hơi ấm là hai yếu tố thiết yếu cho sự nảy mầm của hạt giống.)","The scientist observed the rate of [germination] under different light conditions. (=Dịch: Nhà khoa học đã quan sát tỷ lệ nảy mầm dưới các điều kiện ánh sáng khác nhau.)","Cold temperatures can significantly delay the [germination] of crops. (=Dịch: Nhiệt độ lạnh có thể làm chậm đáng kể quá trình nảy mầm của cây trồng.)"],"ukAudio":"/ai_services/tts3/?q=germination&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9C%CB%90r.m%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=germination&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9C%CB%90r.m%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_164","topic":"Nature and Environmental Protection","word":"gps","pos":"(n)","ipa":"/ˌdʒiː.piːˈɛs/","defVi":"hệ thống định vị toàn cầu (GPS)","defEn":"a satellite-based navigation system used to determine geographic location","examples":["The delivery driver relied on [gps] to navigate the unfamiliar city streets. (=Dịch: Người tài xế giao hàng đã dựa vào GPS để tìm đường qua những con phố xa lạ.)","Most modern smartphones come equipped with a built-in [gps] receiver. (=Dịch: Hầu hết các điện thoại thông minh hiện đại đều được trang bị bộ thu GPS tích hợp.)","Hikers should carry a printed map in case their [gps] runs out of battery. (=Dịch: Những người đi bộ đường dài nên mang theo bản đồ in đề phòng thiết bị GPS hết pin.)"],"ukAudio":"/ai_services/tts3/?q=gps&lang=en-GB&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=gps&lang=en-US&ipa=%2F%CB%8Cd%CA%92i%CB%90.pi%CB%90%CB%88%C9%9Bs%2F"},{"id":"lv_5_165","topic":"Nature and Environmental Protection","word":"gradually","pos":"(adv)","ipa":"/ˈɡrædʒ.u.ə.li/","defVi":"dần dần, từ từ","defEn":"slowly over a period of time or in small stages","examples":["His English speaking skills [gradually] improved after months of practice. (=Dịch: Kỹ năng nói tiếng Anh của anh ấy dần dần tiến bộ sau nhiều tháng luyện tập.)","The weather [gradually] became warmer as spring approached. (=Dịch: Thời tiết dần ấm lên khi mùa xuân đến gần.)","Patients are advised to [gradually] return to their normal daily routines. (=Dịch: Bệnh nhân được khuyên nên dần dần quay trở lại thói quen sinh hoạt hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=gradually&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=gradually&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99.li%2F"},{"id":"lv_5_166","topic":"Nature and Environmental Protection","word":"greece","pos":"(n)","ipa":"/ɡriːs/","defVi":"nước Hy Lạp","defEn":"a country in southeastern Europe renowned for its ancient civilization and islands","examples":["Millions of tourists visit [greece] each summer to explore ancient historical ruins. (=Dịch: Hàng triệu du khách đến thăm Hy Lạp mỗi mùa hè để khám phá các tàn tích lịch sử cổ đại.)","Olive oil is a staple agricultural export of [greece]. (=Dịch: Dầu ô liu là một mặt hàng nông sản xuất khẩu chủ lực của Hy Lạp.)","Classical philosophy and early democratic ideas trace their origins to [greece]. (=Dịch: Triết học cổ điển và những tư tưởng dân chủ sơ khai bắt nguồn từ Hy Lạp.)"],"ukAudio":"/ai_services/tts3/?q=greece&lang=en-GB&ipa=%2F%C9%A1ri%CB%90s%2F","usAudio":"/ai_services/tts3/?q=greece&lang=en-US&ipa=%2F%C9%A1ri%CB%90s%2F"},{"id":"lv_5_167","topic":"Nature and Environmental Protection","word":"greenhouse","pos":"(n)","ipa":"/ˈɡrin.haʊs/","defVi":"nhà kính (trồng cây)","defEn":"a glass or transparent plastic building used for growing plants that need warmth and protection","examples":["They grow tomatoes and cucumbers in a large [greenhouse] behind the house. (=Dịch: Họ trồng cà chua và dưa chuột trong một nhà kính lớn phía sau nhà.)","The botanic garden features a tropical [greenhouse] filled with rare orchids. (=Dịch: Vườn bách thảo có một nhà kính nhiệt đới chứa đầy những loài lan quý hiếm.)","Scientists use a temperature-controlled [greenhouse] for their agricultural experiments. (=Dịch: Các nhà khoa học sử dụng một nhà kính kiểm soát nhiệt độ cho các thí nghiệm nông nghiệp của họ.)"],"ukAudio":"/ai_services/tts3/?q=greenhouse&lang=en-GB&ipa=%2F%CB%88%C9%A1rin.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=greenhouse&lang=en-US&ipa=%2F%CB%88%C9%A1rin.ha%CA%8As%2F"},{"id":"lv_5_168","topic":"Nature and Environmental Protection","word":"grip","pos":"(v)","ipa":"/ɡrɪp/","defVi":"nắm chặt, bám chặt, thu hút","defEn":"to hold something tightly; to hold someone's attention completely","examples":["She had to [grip] the handrail firmly as the train accelerated suddenly. (=Dịch: Cô ấy phải bám chặt vào tay vịn khi đoàn tàu đột ngột tăng tốc.)","The thrilling mystery novel managed to [grip] readers from the very first page. (=Dịch: Cuốn tiểu thuyết trinh thám ly kỳ đã thu hút độc giả ngay từ trang đầu tiên.)","Fear seemed to [grip] the entire town during the mysterious outbreak. (=Dịch: Nỗi sợ hãi dường như bao trùm cả thị trấn trong đợt bùng phát bí ẩn.)"],"ukAudio":"/ai_services/tts3/?q=grip&lang=en-GB&ipa=%2F%C9%A1r%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=grip&lang=en-US&ipa=%2F%C9%A1r%C9%AAp%2F"},{"id":"lv_5_169","topic":"Nature and Environmental Protection","word":"habitat","pos":"(n)","ipa":"/ˈhæb.ə.tæt/","defVi":"môi trường sống tự nhiên","defEn":"the natural home or environment of an animal, plant, or organism","examples":["Urban expansion is rapidly destroying the natural [habitat] of many wildlife species. (=Dịch: Sự mở rộng đô thị đang nhanh chóng phá hủy môi trường sống tự nhiên của nhiều loài động vật hoang dã.)","Polar bears depend on sea ice as their primary hunting [habitat]. (=Dịch: Gấu bắc cực phụ thuộc vào băng biển như môi trường săn mồi chính của chúng.)","The wetland provides a critical breeding [habitat] for migratory birds. (=Dịch: Vùng đất ngập nước cung cấp môi trường sinh sản quan trọng cho các loài chim di cư.)"],"ukAudio":"/ai_services/tts3/?q=habitat&lang=en-GB&ipa=%2F%CB%88h%C3%A6b.%C9%99.t%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=habitat&lang=en-US&ipa=%2F%CB%88h%C3%A6b.%C9%99.t%C3%A6t%2F"},{"id":"lv_5_170","topic":"Nature and Environmental Protection","word":"harvest","pos":"(n)","ipa":"/ˈhɑːr.vɪst/","defVi":"mùa thu hoạch, vụ mùa, sản lượng thu hoạch","defEn":"the season or process of gathering crops, or the quantity of crops collected","examples":["Farmers are celebrating a bumper [harvest] of wheat this year. (=Dịch: Những người nông dân đang ăn mừng một vụ mùa lúa mì bội thu trong năm nay.)","The olive [harvest] typically takes place in late autumn. (=Dịch: Mùa thu hoạch ô liu thường diễn ra vào cuối mùa thu.)","Drought caused severe damage to the annual rice [harvest]. (=Dịch: Hạn hán đã gây thiệt hại nghiêm trọng cho sản lượng lúa hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=harvest&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90r.v%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=harvest&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90r.v%C9%AAst%2F"},{"id":"lv_5_171","topic":"Nature and Environmental Protection","word":"hawk","pos":"(n)","ipa":"/hɔːk/","defVi":"chim ưng, chim diều hâu","defEn":"a bird of prey with broad rounded wings and a long tail, known for keen eyesight","examples":["A [hawk] circled high in the sky, searching for prey. (=Dịch: Một con chim ưng lượn vòng trên trời cao để tìm kiếm con mồi.)","The [hawk] swooped down swiftly to catch a small mouse in the field. (=Dịch: Con diều hâu lao vút xuống để bắt một con chuột nhỏ trên cánh đồng.)","With vision like a [hawk], the guard noticed the intrusion immediately. (=Dịch: Với tầm nhìn sắc bén như chim ưng, người bảo vệ đã phát hiện ra sự xâm nhập ngay lập tức.)"],"ukAudio":"/ai_services/tts3/?q=hawk&lang=en-GB&ipa=%2Fh%C9%94%CB%90k%2F","usAudio":"/ai_services/tts3/?q=hawk&lang=en-US&ipa=%2Fh%C9%94%CB%90k%2F"},{"id":"lv_5_172","topic":"Nature and Environmental Protection","word":"haze","pos":"(n)","ipa":"/heɪz/","defVi":"màn sương mờ, bụi mù, khói mù","defEn":"a thin mist or smoke in the air that makes it hard to see clearly","examples":["The morning sun slowly emerged through the thick [haze]. (=Dịch: Mặt trời buổi sáng từ từ hiện ra qua màn sương mù dày đặc.)","A [haze] of pollution hung over the city during the summer. (=Dịch: Một màn khói bụi ô nhiễm bao trùm lấy thành phố trong suốt mùa hè.)","He looked at the distant mountains veiled in blue [haze]. (=Dịch: Anh ấy nhìn về phía những ngọn núi xa xa bị che phủ bởi làn sương lam.)"],"ukAudio":"/ai_services/tts3/?q=haze&lang=en-GB&ipa=%2Fhe%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=haze&lang=en-US&ipa=%2Fhe%C9%AAz%2F"},{"id":"lv_5_173","topic":"Nature and Environmental Protection","word":"hedgehog","pos":"(n)","ipa":"/ˈhedʒ.hɑːɡ/","defVi":"con nhím (nhím gai nhỏ)","defEn":"a small nocturnal mammal covered with stiff, sharp spines","examples":["A small [hedgehog] curled into a prickly ball when the dog approached. (=Dịch: Một con nhím nhỏ cuộn tròn thành một quả cầu đầy gai khi con chó đến gần.)","The wildlife rescue center released a healthy [hedgehog] back into the woods. (=Dịch: Trung tâm cứu hộ động vật hoang dã đã thả một con nhím khỏe mạnh trở lại khu rừng.)","We often see a [hedgehog] foraging for insects in our garden at dusk. (=Dịch: Chúng tôi thường thấy một con nhím tìm kiếm côn trùng trong vườn nhà vào lúc chập tối.)"],"ukAudio":"/ai_services/tts3/?q=hedgehog&lang=en-GB&ipa=%2F%CB%88hed%CA%92.h%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=hedgehog&lang=en-US&ipa=%2F%CB%88hed%CA%92.h%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_174","topic":"Nature and Environmental Protection","word":"heel","pos":"(n)","ipa":"/hil/","defVi":"gót chân, gót giày","defEn":"the back part of the human foot below the ankle, or the back part of a shoe","examples":["She rubbed her sore [heel] after walking in new shoes all day. (=Dịch: Cô ấy xoa gót chân đau nhức sau khi đi lại cả ngày bằng đôi giày mới.)","The [heel] of her boot broke as she stepped off the curb. (=Dịch: Gót chiếc ủng của cô ấy bị gãy khi bước xuống lề đường.)","Apply gentle pressure to the [heel] to help relieve muscle tension. (=Dịch: Ấn nhẹ vào phần gót chân để giúp giảm căng cơ.)"],"ukAudio":"/ai_services/tts3/?q=heel&lang=en-GB&ipa=%2Fhil%2F","usAudio":"/ai_services/tts3/?q=heel&lang=en-US&ipa=%2Fhil%2F"},{"id":"lv_5_175","topic":"Nature and Environmental Protection","word":"hibernate","pos":"(v)","ipa":"/ˈhaɪ.bɚ.neɪt/","defVi":"ngủ đông","defEn":"to spend the winter in a dormant, sleep-like state to conserve energy","examples":["Bears eat heavily during the autumn so they can safely [hibernate] through the harsh winter. (=Dịch: Gấu ăn rất nhiều vào mùa thu để chúng có thể ngủ đông an toàn qua mùa đông khắc nghiệt.)","Some species of frogs [hibernate] by burying themselves deep in the mud under frozen lakes. (=Dịch: Một số loài ếch ngủ đông bằng cách tự vùi mình sâu trong bùn dưới các hồ nước đóng băng.)","Animals that [hibernate] experience a drastic drop in body temperature and metabolic rate. (=Dịch: Những động vật ngủ đông sẽ trải qua sự sụt giảm mạnh về thân nhiệt và tốc độ trao đổi chất.)"],"ukAudio":"/ai_services/tts3/?q=hibernate&lang=en-GB&ipa=%2F%CB%88ha%C9%AA.b%C9%9A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=hibernate&lang=en-US&ipa=%2F%CB%88ha%C9%AA.b%C9%9A.ne%C9%AAt%2F"},{"id":"lv_5_176","topic":"Nature and Environmental Protection","word":"hibernation","pos":"(n)","ipa":"/ˌhaɪ.bɚˈneɪ.ʃən/","defVi":"sự ngủ đông, giấc ngủ đông","defEn":"a state of deep sleep that some animals enter during the winter to save energy","examples":["Bears store up fat before entering their winter [hibernation]. (=Dịch: Gấu tích tụ mỡ trước khi bước vào kỳ ngủ đông.)","During [hibernation], an animal's body temperature and heart rate drop significantly. (=Dịch: Trong suốt thời gian ngủ đông, thân nhiệt và nhịp tim của động vật giảm đi đáng kể.)","The hedgehog wakes up from [hibernation] when spring arrives. (=Dịch: Con nhím thức dậy sau giấc ngủ đông khi mùa xuân đến.)"],"ukAudio":"/ai_services/tts3/?q=hibernation&lang=en-GB&ipa=%2F%CB%8Cha%C9%AA.b%C9%9A%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=hibernation&lang=en-US&ipa=%2F%CB%8Cha%C9%AA.b%C9%9A%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_177","topic":"Nature and Environmental Protection","word":"hook","pos":"(n)","ipa":"/hʊk/","defVi":"móc, cái móc; lưỡi câu","defEn":"a curved piece of metal, plastic, or other material used for catching, holding, or hanging things","examples":["Hang your coat on the [hook] behind the door. (=Dịch: Treo áo khoác của bạn lên chiếc móc đằng sau cánh cửa.)","He baited the [hook] with a small worm to catch fish. (=Dịch: Anh ấy gắn mồi là một con giun nhỏ vào lưỡi câu để bắt cá.)","The picture frame fell off the wall because the [hook] was loose. (=Dịch: Khung tranh bị rơi khỏi tường vì chiếc móc bị lỏng.)"],"ukAudio":"/ai_services/tts3/?q=hook&lang=en-GB&ipa=%2Fh%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=hook&lang=en-US&ipa=%2Fh%CA%8Ak%2F"},{"id":"lv_5_178","topic":"Nature and Environmental Protection","word":"hormone","pos":"(n)","ipa":"/ˈhɔːr.moʊn/","defVi":"hoóc-môn, nội tiết tố","defEn":"a chemical substance produced in the body that controls the activity of certain cells or organs","examples":["Insulin is an essential [hormone] that regulates blood sugar levels. (=Dịch: Insulin là một hoóc-môn thiết yếu giúp điều hòa lượng đường trong máu.)","Adrenaline is a [hormone] released by the body during times of extreme stress. (=Dịch: Adrenaline là một hoóc-môn được cơ thể giải phóng trong những thời điểm cực kỳ căng thẳng.)","Changes in [hormone] levels can greatly affect a person's mood and sleep patterns. (=Dịch: Sự thay đổi về nồng độ hoóc-môn có thể ảnh hưởng lớn đến tâm trạng và giấc ngủ của một người.)"],"ukAudio":"/ai_services/tts3/?q=hormone&lang=en-GB&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=hormone&lang=en-US&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F"},{"id":"lv_5_179","topic":"Nature and Environmental Protection","word":"hotspot","pos":"(n)","ipa":"/ˈhɑːt.spɑːt/","defVi":"điểm nóng; điểm phát sóng Wi-Fi","defEn":"a place with a lot of activity, danger, or biodiversity, or a public location with Wi-Fi access","examples":["The tropical rainforest is a global [hotspot] for biodiversity. (=Dịch: Rừng mưa nhiệt đới là một điểm nóng toàn cầu về đa dạng sinh học.)","The cafe offers a free Wi-Fi [hotspot] for all customers. (=Dịch: Quán cà phê cung cấp điểm phát Wi-Fi miễn phí cho tất cả khách hàng.)","Police increased patrols around the crime [hotspot] in the downtown area. (=Dịch: Cảnh sát đã tăng cường tuần tra quanh điểm nóng tội phạm ở khu trung tâm.)"],"ukAudio":"/ai_services/tts3/?q=hotspot&lang=en-GB&ipa=%2F%CB%88h%C9%91%CB%90t.sp%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=hotspot&lang=en-US&ipa=%2F%CB%88h%C9%91%CB%90t.sp%C9%91%CB%90t%2F"},{"id":"lv_5_180","topic":"Nature and Environmental Protection","word":"household","pos":"(n)","ipa":"/ˈhaʊs.hoʊld/","defVi":"hộ gia đình","defEn":"a group of people, often a family, who live together in the same home","examples":["Many families try to reduce their monthly [household] expenses during difficult times. (=Dịch: Nhiều gia đình cố gắng cắt giảm chi tiêu hộ gia đình hàng tháng trong thời kỳ khó khăn.)","The government census collects data from every [household] across the country. (=Dịch: Cuộc điều tra dân số của chính phủ thu thập dữ liệu từ mọi hộ gia đình trên toàn quốc.)","Sharing [household] chores fairly can prevent arguments among roommates. (=Dịch: Chia sẻ việc nhà một cách công bằng có thể ngăn ngừa các cuộc tranh cãi giữa những người bạn cùng phòng.)"],"ukAudio":"/ai_services/tts3/?q=household&lang=en-GB&ipa=%2F%CB%88ha%CA%8As.ho%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=household&lang=en-US&ipa=%2F%CB%88ha%CA%8As.ho%CA%8Ald%2F"},{"id":"lv_5_181","topic":"Nature and Environmental Protection","word":"humid","pos":"(adj)","ipa":"/ˈhju.mɪd/","defVi":"ẩm ướt, ẩm thấp","defEn":"having a high level of moisture or water vapor in the air","examples":["Tropical rainforests are typically hot and [humid] throughout the year. (=Dịch: Các khu rừng mưa nhiệt đới thường nóng và ẩm ướt quanh năm.)","The weather became uncomfortably [humid] right before the storm. (=Dịch: Thời tiết trở nên ẩm thấp khó chịu ngay trước cơn bão.)","She found it hard to breathe in such a [humid] climate. (=Dịch: Cô thấy khó thở trong một khí hậu ẩm ướt đến như vậy.)"],"ukAudio":"/ai_services/tts3/?q=humid&lang=en-GB&ipa=%2F%CB%88hju.m%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=humid&lang=en-US&ipa=%2F%CB%88hju.m%C9%AAd%2F"},{"id":"lv_5_182","topic":"Nature and Environmental Protection","word":"hunger","pos":"(n)","ipa":"/ˈhʌŋ.ɡɚ/","defVi":"cơn đói, nạn đói; sự khao khát","defEn":"the feeling of needing food, or the state of not having enough food to eat","examples":["International aid organizations are working tirelessly to eliminate [hunger] in poor regions. (=Dịch: Các tổ chức viện trợ quốc tế đang nỗ lực không ngừng nghỉ để xóa bỏ nạn đói ở các vùng nghèo khó.)","After hiking for five hours, we were overcome by intense [hunger]. (=Dịch: Sau năm giờ đi bộ đường dài, chúng tôi bị lấn át bởi cơn đói cồn cào.)","The young scientist had a relentless [hunger] for new knowledge and discovery. (=Dịch: Nhà khoa học trẻ tuổi luôn có một sự khao khát không ngừng đối với kiến thức và khám phá mới.)"],"ukAudio":"/ai_services/tts3/?q=hunger&lang=en-GB&ipa=%2F%CB%88h%CA%8C%C5%8B.%C9%A1%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunger&lang=en-US&ipa=%2F%CB%88h%CA%8C%C5%8B.%C9%A1%C9%9A%2F"},{"id":"lv_5_183","topic":"Nature and Environmental Protection","word":"hunt","pos":"(n)","ipa":"/hʌnt/","defVi":"Cuộc đi săn; sự tìm kiếm ráo riết.","defEn":"An act of chasing wild animals for food or sport, or an intensive search for something.","examples":["The lion returned empty-handed after a long and exhausting [hunt]. (=Dịch: Con sư tử trở về trắng tay sau một cuộc đi săn dài và mệt mỏi.)","The police have launched a massive [hunt] for the escaped criminal. (=Dịch: Cảnh sát đã phát động một cuộc tìm kiếm quy mô lớn đối với tên tội phạm vượt ngục.)","Her [hunt] for an affordable apartment in the city took several weeks. (=Dịch: Cuộc tìm kiếm một căn hộ giá cả phải chăng trong thành phố của cô ấy đã mất vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=hunt&lang=en-GB&ipa=%2Fh%CA%8Cnt%2F","usAudio":"/ai_services/tts3/?q=hunt&lang=en-US&ipa=%2Fh%CA%8Cnt%2F"},{"id":"lv_5_184","topic":"Nature and Environmental Protection","word":"hunter","pos":"(n)","ipa":"/ˈhʌn.tɚ/","defVi":"Người thợ săn; kẻ săn mồi.","defEn":"A person or animal that searches for and kills wild animals for food or sport.","examples":["The experienced [hunter] tracked the deer through the dense forest. (=Dịch: Người thợ săn giàu kinh nghiệm đã lần theo dấu con hươu qua khu rừng rậm rạp.)","Owls are efficient nocturnal [hunter] species that feed on small rodents. (=Dịch: Cú là loài động vật săn mồi ban đêm rất hiệu quả, ăn các loài gặm nhấm nhỏ.)","Local laws require every [hunter] to carry a valid hunting permit. (=Dịch: Luật pháp địa phương yêu cầu mọi thợ săn phải mang theo giấy phép săn bắn hợp lệ.)"],"ukAudio":"/ai_services/tts3/?q=hunter&lang=en-GB&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=hunter&lang=en-US&ipa=%2F%CB%88h%CA%8Cn.t%C9%9A%2F"},{"id":"lv_5_185","topic":"Nature and Environmental Protection","word":"iceland","pos":"(n)","ipa":"/ˈaɪs.lənd/","defVi":"Băng Đảo (Iceland - một đảo quốc ở Bắc Đại Tây Dương).","defEn":"An island country in the North Atlantic Ocean known for its volcanic landscape and glaciers.","examples":["Tourism in [iceland] has grown rapidly due to its breathtaking natural wonders. (=Dịch: Du lịch ở Iceland đã phát triển nhanh chóng nhờ vào các kỳ quan thiên nhiên ngoạn mục.)","Many researchers visit [iceland] to study geothermal energy and active volcanoes. (=Dịch: Nhiều nhà nghiên cứu đến Iceland để nghiên cứu về năng lượng địa nhiệt và các núi lửa đang hoạt động.)","We were lucky enough to see the Northern Lights during our winter trip to [iceland]. (=Dịch: Chúng tôi đã đủ may mắn để nhìn thấy hiện tượng cực quang trong chuyến đi mùa đông tới Iceland.)"],"ukAudio":"/ai_services/tts3/?q=iceland&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=iceland&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F"},{"id":"lv_5_186","topic":"Nature and Environmental Protection","word":"ideally","pos":"(adv)","ipa":"/aɪˈdiː.ə.li/","defVi":"Lý tưởng nhất là; một cách hoàn hảo.","defEn":"In an ideal or perfect way; according to what is best.","examples":["[ideally], students should spend at least two hours reviewing their lessons each day. (=Dịch: Lý tưởng nhất là học sinh nên dành ít nhất hai giờ để ôn bài mỗi ngày.)","The new apartment is [ideally] located near the city center and public transport. (=Dịch: Căn hộ mới có vị trí vô cùng lý tưởng gần trung tâm thành phố và phương tiện công cộng.)","[ideally], the project should be completed before the end of this quarter. (=Dịch: Về mặt lý tưởng, dự án này nên được hoàn thành trước khi quý này kết thúc.)"],"ukAudio":"/ai_services/tts3/?q=ideally&lang=en-GB&ipa=%2Fa%C9%AA%CB%88di%CB%90.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=ideally&lang=en-US&ipa=%2Fa%C9%AA%CB%88di%CB%90.%C9%99.li%2F"},{"id":"lv_5_187","topic":"Nature and Environmental Protection","word":"illegal","pos":"(adj)","ipa":"/ɪˈliː.ɡəl/","defVi":"Bất hợp pháp; phạm pháp.","defEn":"Not allowed by the law; against official rules.","examples":["It is [illegal] to drive a motor vehicle without a valid license. (=Dịch: Lái xe cơ giới mà không có bằng lái hợp lệ là phạm pháp.)","The government is cracking down on the [illegal] trade of wild animals. (=Dịch: Chính phủ đang trấn áp hoạt động buôn bán động vật hoang dã bất hợp pháp.)","Downloading copyrighted content without permission is considered [illegal]. (=Dịch: Tải nội dung có bản quyền mà không xin phép bị coi là bất hợp pháp.)"],"ukAudio":"/ai_services/tts3/?q=illegal&lang=en-GB&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=illegal&lang=en-US&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_5_188","topic":"Nature and Environmental Protection","word":"import","pos":"(v)","ipa":"/ɪmˈpɔːrt/","defVi":"Nhập khẩu; nhập hàng.","defEn":"To bring goods or services into a country from abroad to sell.","examples":["The country has to [import] a large amount of crude oil every year. (=Dịch: Quốc gia này phải nhập khẩu một lượng lớn dầu thô mỗi năm.)","They plan to [import] high-tech agricultural machinery from Germany. (=Dịch: Họ dự định nhập khẩu máy móc nông nghiệp công nghệ cao từ Đức.)","Supermarkets frequently [import] tropical fruits during the winter season. (=Dịch: Các siêu thị thường xuyên nhập khẩu trái cây nhiệt đới vào mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=import&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=import&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90rt%2F"},{"id":"lv_5_189","topic":"Nature and Environmental Protection","word":"incorrect","pos":"(adj)","ipa":"/ˌɪn.kəˈrɛkt/","defVi":"sai, không chính xác","defEn":"not right or accurate; containing errors","examples":["Several answers on his exam were marked as [incorrect]. (=Dịch: Một số câu trả lời trong bài kiểm tra của anh ấy bị đánh dấu là không chính xác.)","The article provided [incorrect] information about the total cost of the project. (=Dịch: Bài báo đã cung cấp thông tin không đúng về tổng chi phí của dự án.)","It is [incorrect] to assume that all students learn at the same pace. (=Dịch: Thật sai lầm khi cho rằng tất cả học sinh đều tiếp thu với tốc độ như nhau.)"],"ukAudio":"/ai_services/tts3/?q=incorrect&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=incorrect&lang=en-US&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F"},{"id":"lv_5_190","topic":"Nature and Environmental Protection","word":"incredibly","pos":"(adv)","ipa":"/ɪnˈkrɛd.ə.bli/","defVi":"Vô cùng, cực kỳ, không thể tin được.","defEn":"Extremely; to a very great degree.","examples":["The final exam was [incredibly] difficult for most students. (=Dịch: Bài thi cuối kỳ cực kỳ khó đối với hầu hết học sinh.)","She solved the complicated puzzle [incredibly] fast. (=Dịch: Cô ấy đã giải câu đố phức tạp nhanh một cách khó tin.)","The team worked [incredibly] hard to finish the project on time. (=Dịch: Cả nhóm đã làm việc vô cùng chăm chỉ để hoàn thành dự án đúng hạn.)"],"ukAudio":"/ai_services/tts3/?q=incredibly&lang=en-GB&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=incredibly&lang=en-US&ipa=%2F%C9%AAn%CB%88kr%C9%9Bd.%C9%99.bli%2F"},{"id":"lv_5_191","topic":"Nature and Environmental Protection","word":"ingest","pos":"(v)","ipa":"/ɪnˈdʒɛst/","defVi":"ăn vào, nuốt vào, tiêu thụ","defEn":"to take food, drink, or another substance into your body by swallowing it","examples":["Marine animals often [ingest] plastic waste by mistake. (=Dịch: Động vật biển thường vô tình nuốt phải rác thải nhựa.)","You should not [ingest] this medicine on an empty stomach. (=Dịch: Bạn không nên uống loại thuốc này khi bụng đói.)","Some plants produce toxins that are dangerous to [ingest]. (=Dịch: Một số loài thực vật sản sinh độc tố nguy hiểm nếu ăn phải.)"],"ukAudio":"/ai_services/tts3/?q=ingest&lang=en-GB&ipa=%2F%C9%AAn%CB%88d%CA%92%C9%9Bst%2F","usAudio":"/ai_services/tts3/?q=ingest&lang=en-US&ipa=%2F%C9%AAn%CB%88d%CA%92%C9%9Bst%2F"},{"id":"lv_5_192","topic":"Nature and Environmental Protection","word":"inhabit","pos":"(v)","ipa":"/ɪnˈhæb.ɪt/","defVi":"sinh sống, cư trú tại một nơi","defEn":"to live in or occupy a particular place","examples":["Many rare bird species [inhabit] this remote rainforest. (=Dịch: Nhiều loài chim quý hiếm sinh sống trong khu rừng mưa hẻo lánh này.)","Polar bears [inhabit] the freezing regions of the Arctic. (=Dịch: Gấu bắc cực cư trú tại những vùng băng giá của Bắc Cực.)","Humans have managed to [inhabit] almost every corner of the earth. (=Dịch: Con người đã cố gắng sinh sống ở hầu hết mọi ngóc ngách trên Trái Đất.)"],"ukAudio":"/ai_services/tts3/?q=inhabit&lang=en-GB&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=inhabit&lang=en-US&ipa=%2F%C9%AAn%CB%88h%C3%A6b.%C9%AAt%2F"},{"id":"lv_5_193","topic":"Nature and Environmental Protection","word":"inland","pos":"(adj)","ipa":"/ˈɪn.lənd/","defVi":"nội địa, nằm sâu trong đất liền","defEn":"situated in or relating to the interior part of a country rather than the coast","examples":["The town is located in an [inland] region far from the ocean. (=Dịch: Thị trấn nằm ở một vùng nội địa cách xa đại dương.)","Many [inland] lakes suffer from water shortages during the dry summer months. (=Dịch: Nhiều hồ nội địa bị thiếu nước trong những tháng hè khô hạn.)","The government is improving [inland] transport networks to boost trade. (=Dịch: Chính phủ đang cải thiện mạng lưới giao thông nội địa để thúc đẩy thương mại.)"],"ukAudio":"/ai_services/tts3/?q=inland&lang=en-GB&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=inland&lang=en-US&ipa=%2F%CB%88%C9%AAn.l%C9%99nd%2F"},{"id":"lv_5_194","topic":"Nature and Environmental Protection","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự hiểu biết sâu sắc, cái nhìn thấu suốt","defEn":"a clear, deep, and sometimes sudden understanding of a complicated problem or situation","examples":["The study provides valuable [insight] into customer behavior. (=Dịch: Nghiên cứu này cung cấp cái nhìn sâu sắc có giá trị về hành vi của khách hàng.)","Her experiences abroad gave her a unique [insight] into different cultures. (=Dịch: Những trải nghiệm ở nước ngoài đã mang lại cho cô ấy một góc nhìn sâu sắc độc đáo về các nền văn hóa khác nhau.)","The documentary offers an interesting [insight] into the life of wild animals. (=Dịch: Bộ phim tài liệu mang lại một góc nhìn thú vị về đời sống của các loài động vật hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_5_195","topic":"Nature and Environmental Protection","word":"instal","pos":"(v)","ipa":"/ɪn.ˈstɑːl/","defVi":"Cài đặt, lắp đặt","defEn":"To put a piece of equipment, system, or software into place and make it ready to use.","examples":["The technician arrived early to [instal] the new air conditioning unit. (=Dịch: Kỹ thuật viên đã đến sớm để lắp đặt thiết bị điều hòa mới.)","You must [instal] the latest security update to protect your computer. (=Dịch: Bạn phải cài đặt bản cập nhật bảo mật mới nhất để bảo vệ máy tính của mình.)","The school decided to [instal] solar panels on the roof to save energy. (=Dịch: Nhà trường quyết định lắp đặt các tấm pin năng lượng mặt trời trên mái nhà để tiết kiệm điện năng.)"],"ukAudio":"/ai_services/tts3/?q=instal&lang=en-GB&ipa=%2F%C9%AAn.%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=instal&lang=en-US&ipa=%2F%C9%AAn.%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_5_196","topic":"Nature and Environmental Protection","word":"institute","pos":"(n)","ipa":"/ˈɪn.stə.tut/","defVi":"viện, học viện, tổ chức nghiên cứu","defEn":"an organization founded for a specific purpose, such as education, research, or science","examples":["She works as a senior researcher at the scientific [institute]. (=Dịch: Cô ấy làm việc với tư cách là nhà nghiên cứu cao cấp tại viện khoa học.)","The [institute] offers various specialized training courses for engineers. (=Dịch: Viện này cung cấp nhiều khóa đào tạo chuyên sâu cho các kỹ sư.)","Funding for the research [institute] was increased this year. (=Dịch: Kinh phí dành cho viện nghiên cứu đã được tăng lên trong năm nay.)"],"ukAudio":"/ai_services/tts3/?q=institute&lang=en-GB&ipa=%2F%CB%88%C9%AAn.st%C9%99.tut%2F","usAudio":"/ai_services/tts3/?q=institute&lang=en-US&ipa=%2F%CB%88%C9%AAn.st%C9%99.tut%2F"},{"id":"lv_5_197","topic":"Nature and Environmental Protection","word":"integrate","pos":"(v)","ipa":"/ˈɪn.tə.ɡreɪt/","defVi":"tích hợp, hòa nhập","defEn":"to combine two or more things so that they work together effectively","examples":["It can take time for new immigrants to [integrate] into a different culture. (=Dịch: Có thể mất thời gian để những người nhập cư mới hòa nhập vào một nền văn hóa khác.)","Teachers try to [integrate] modern technology into their daily lessons. (=Dịch: Giáo viên cố gắng tích hợp công nghệ hiện đại vào các bài học hàng ngày của họ.)","The new software will [integrate] smoothly with our existing database. (=Dịch: Phần mềm mới sẽ tích hợp mượt mà với cơ sở dữ liệu hiện có của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=integrate&lang=en-GB&ipa=%2F%CB%88%C9%AAn.t%C9%99.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=integrate&lang=en-US&ipa=%2F%CB%88%C9%AAn.t%C9%99.%C9%A1re%C9%AAt%2F"},{"id":"lv_5_198","topic":"Nature and Environmental Protection","word":"intelligence","pos":"(n)","ipa":"/ɪnˈtɛl.ə.dʒəns/","defVi":"trí thông minh, trí tuệ; tin tức tình báo","defEn":"the ability to learn, understand, and think logically, or secret information gathered about an enemy","examples":["Dolphins are well known for their high level of [intelligence]. (=Dịch: Cá heo nổi tiếng vì mức độ thông minh cao.)","The government gathered secret [intelligence] before making a move. (=Dịch: Chính phủ đã thu thập tin tức tình báo bí mật trước khi hành động.)","Advances in artificial [intelligence] are transforming many industries. (=Dịch: Những tiến bộ trong trí tuệ nhân tạo đang làm thay đổi nhiều ngành công nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=intelligence&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=intelligence&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F"},{"id":"lv_5_199","topic":"Nature and Environmental Protection","word":"invasive","pos":"(adj)","ipa":"/ɪnˈveɪ.sɪv/","defVi":"xâm lấn, có tính xâm hại","defEn":"tending to spread aggressively, especially of non-native species causing ecological damage","examples":["The [invasive] weed spread rapidly and threatened native plant species. (=Dịch: Loài cỏ dại xâm lấn lan rộng nhanh chóng và đe dọa các loài thực vật bản địa.)","Scientists are studying ways to control [invasive] carp in local rivers. (=Dịch: Các nhà khoa học đang nghiên cứu các cách để kiểm soát loài cá chép xâm lấn ở các con sông địa phương.)","Doctors recommended a non-[invasive] treatment instead of surgery. (=Dịch: Các bác sĩ đã khuyến nghị một phương pháp điều trị không xâm lấn thay vì phẫu thuật.)"],"ukAudio":"/ai_services/tts3/?q=invasive&lang=en-GB&ipa=%2F%C9%AAn%CB%88ve%C9%AA.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=invasive&lang=en-US&ipa=%2F%C9%AAn%CB%88ve%C9%AA.s%C9%AAv%2F"},{"id":"lv_5_200","topic":"Nature and Environmental Protection","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, sự nghiên cứu làm rõ","defEn":"an official examination or inquiry into a crime, problem, or statement","examples":["The police launched a thorough [investigation] into the robbery. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về vụ trộm.)","A formal [investigation] revealed several safety violations at the factory. (=Dịch: Một cuộc điều tra chính thức đã chỉ ra một số vi phạm an toàn tại nhà máy.)","The committee is carrying out an [investigation] to find the cause of the accident. (=Dịch: Ủy ban đang tiến hành một cuộc điều tra để tìm ra nguyên nhân của tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_201","topic":"Nature and Environmental Protection","word":"laboratory","pos":"(n)","ipa":"/ˈlæb.rə.tɔːr.i/","defVi":"phòng thí nghiệm","defEn":"a room or building equipped for scientific experiments, research, or testing","examples":["Students must wear protective goggles whenever they work inside the chemistry [laboratory]. (=Dịch: Học sinh phải đeo kính bảo hộ bất cứ khi nào làm việc trong phòng thí nghiệm hóa học.)","The medical [laboratory] is processing hundreds of blood tests every day. (=Dịch: Phòng xét nghiệm y tế đang xử lý hàng trăm mẫu xét nghiệm máu mỗi ngày.)","Cutting-edge vaccines are developed inside this high-security research [laboratory]. (=Dịch: Các loại vắc-xin tiên tiến được phát triển bên trong phòng thí nghiệm nghiên cứu có độ bảo mật cao này.)"],"ukAudio":"/ai_services/tts3/?q=laboratory&lang=en-GB&ipa=%2F%CB%88l%C3%A6b.r%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=laboratory&lang=en-US&ipa=%2F%CB%88l%C3%A6b.r%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_5_202","topic":"Nature and Environmental Protection","word":"lagoon","pos":"(n)","ipa":"/ləˈɡuːn/","defVi":"đầm phá, vùng nước nông ven biển","defEn":"a body of shallow water separated from the sea by a reef or sandbar","examples":["Tourists love swimming in the calm, clear waters of the tropical [lagoon]. (=Dịch: Khách du lịch thích bơi trong làn nước trong vắt và êm đềm của đầm phá nhiệt đới.)","A coral reef protects the shallow [lagoon] from powerful ocean waves. (=Dịch: Một rạn san hô bảo vệ vùng đầm phá nông khỏi những con sóng biển dữ dội.)","Rare bird species nest along the shores of the coastal [lagoon]. (=Dịch: Các loài chim quý hiếm làm tổ dọc theo bờ của đầm phá ven biển.)"],"ukAudio":"/ai_services/tts3/?q=lagoon&lang=en-GB&ipa=%2Fl%C9%99%CB%88%C9%A1u%CB%90n%2F","usAudio":"/ai_services/tts3/?q=lagoon&lang=en-US&ipa=%2Fl%C9%99%CB%88%C9%A1u%CB%90n%2F"},{"id":"lv_5_203","topic":"Nature and Environmental Protection","word":"landfill","pos":"(n)","ipa":"/ˈlænd.fɪl/","defVi":"bãi chôn lấp rác","defEn":"a designated site for the disposal of waste materials by burial","examples":["Tons of plastic waste end up in the city [landfill] every single day. (=Dịch: Hàng tấn rác thải nhựa bị đưa vào bãi chôn lấp rác của thành phố mỗi ngày.)","Decomposing organic matter in a [landfill] produces large amounts of methane gas. (=Dịch: Chất hữu cơ phân hủy trong bãi chôn lấp tạo ra một lượng lớn khí mê-tan.)","Local authorities are trying to divert household waste away from the overflowing [landfill]. (=Dịch: Chính quyền địa phương đang cố gắng chuyển hướng rác thải sinh hoạt khỏi bãi chôn lấp đang quá tải.)"],"ukAudio":"/ai_services/tts3/?q=landfill&lang=en-GB&ipa=%2F%CB%88l%C3%A6nd.f%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=landfill&lang=en-US&ipa=%2F%CB%88l%C3%A6nd.f%C9%AAl%2F"},{"id":"lv_5_204","topic":"Nature and Environmental Protection","word":"larvae","pos":"(n)","ipa":"/ˈlɑr.vi/","defVi":"ấu trùng (số nhiều)","defEn":"the active immature forms of insects, especially before pupating into adults","examples":["Mosquito [larvae] thrive in stagnant water such as ponds and puddles. (=Dịch: Ấu trùng muỗi sinh sôi phát triển mạnh trong nước tù đọng như ao và vũng nước.)","Scientists studied how these [larvae] transform into adult beetles. (=Dịch: Các nhà khoa học đã nghiên cứu cách những ấu trùng này biến đổi thành bọ cánh cứng trưởng thành.)","The fish feed primarily on aquatic [larvae] and small insects. (=Dịch: Loài cá này chủ yếu ăn ấu trùng sống dưới nước và côn trùng nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=larvae&lang=en-GB&ipa=%2F%CB%88l%C9%91r.vi%2F","usAudio":"/ai_services/tts3/?q=larvae&lang=en-US&ipa=%2F%CB%88l%C9%91r.vi%2F"},{"id":"lv_5_205","topic":"Nature and Environmental Protection","word":"leather","pos":"(n)","ipa":"/ˈleð.ər/","defVi":"da thuộc (chất liệu làm đồ dùng)","defEn":"animal skin that has been treated to make shoes, bags, or clothes","examples":["He bought a jacket made of genuine [leather]. (=Dịch: Anh ấy đã mua một chiếc áo khoác làm bằng da thật.)","The car seats are covered in soft black [leather]. (=Dịch: Những chiếc ghế ô tô được bọc bằng da mềm màu đen.)","Many companies now use synthetic materials instead of real [leather]. (=Dịch: Nhiều công ty hiện nay sử dụng vật liệu tổng hợp thay vì da thật.)"],"ukAudio":"/ai_services/tts3/?q=leather&lang=en-GB&ipa=%2F%CB%88le%C3%B0.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=leather&lang=en-US&ipa=%2F%CB%88le%C3%B0.%C9%99r%2F"},{"id":"lv_5_206","topic":"Nature and Environmental Protection","word":"lime","pos":"(n)","ipa":"/laɪm/","defVi":"quả chanh ta (vỏ xanh); vôi sống","defEn":"a small, sour, green citrus fruit, or a white chemical substance derived from limestone","examples":["She squeezed fresh [lime] juice over the grilled fish to add flavor. (=Dịch: Cô ấy vắt nước cốt chanh tươi lên món cá nướng để tăng thêm hương vị.)","Farmers often add [lime] to acidic soil to improve crop growth. (=Dịch: Nông dân thường bón thêm vôi vào đất chua để cải thiện sự phát triển của cây trồng.)","A slice of [lime] was served on the rim of the glass. (=Dịch: Một lát chanh đã được gắn trên miệng ly nước.)"],"ukAudio":"/ai_services/tts3/?q=lime&lang=en-GB&ipa=%2Fla%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=lime&lang=en-US&ipa=%2Fla%C9%AAm%2F"},{"id":"lv_5_207","topic":"Nature and Environmental Protection","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water is the most common [liquid] on Earth. (=Dịch: Nước là chất lỏng phổ biến nhất trên Trái Đất.)","Be careful not to spill that hot [liquid] on yourself. (=Dịch: Hãy cẩn thận kẻo làm đổ chất lỏng nóng đó lên người.)","You should drink plenty of [liquids] when you have a fever. (=Dịch: Bạn nên uống nhiều nước khi bị sốt.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_5_208","topic":"Nature and Environmental Protection","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"gia súc, vật nuôi nông trại","defEn":"animals such as cows, sheep, and pigs that are kept on a farm","examples":["Raising [livestock] requires a tremendous amount of freshwater and feed grain. (=Dịch: Chăn nuôi gia súc đòi hỏi một lượng lớn nước ngọt và ngũ cốc làm thức ăn.)","The sudden snowstorm posed a great danger to the grazing [livestock]. (=Dịch: Trận bão tuyết bất ngờ đã gây nguy hiểm lớn cho đàn gia súc đang gặm cỏ.)","Local farmers depend entirely on their [livestock] for meat, milk, and income. (=Dịch: Những người nông dân địa phương phụ thuộc hoàn toàn vào đàn gia súc của họ để lấy thịt, sữa và thu nhập.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_5_209","topic":"Nature and Environmental Protection","word":"lizard","pos":"(n)","ipa":"/ˈlɪz.ɚd/","defVi":"con thằn lằn","defEn":"a reptile with a long body and tail, four legs, and rough skin","examples":["A small [lizard] was sunbathing on the warm rock. (=Dịch: Một con thằn lằn nhỏ đang phơi nắng trên tảng đá ấm.)","Some types of [lizards] can change color to hide from predators. (=Dịch: Một số loài thằn lằn có thể đổi màu để ẩn nấp khỏi kẻ săn mồi.)","The desert [lizard] is well adapted to survive without much water. (=Dịch: Loài thằn lằn sa mạc thích nghi rất tốt để sống sót mà không cần nhiều nước.)"],"ukAudio":"/ai_services/tts3/?q=lizard&lang=en-GB&ipa=%2F%CB%88l%C9%AAz.%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=lizard&lang=en-US&ipa=%2F%CB%88l%C9%AAz.%C9%9Ad%2F"},{"id":"lv_5_210","topic":"Nature and Environmental Protection","word":"log","pos":"(v)","ipa":"/lɑːɡ/","defVi":"ghi chép lại; khai thác gỗ","defEn":"to record information officially, or to cut down trees for wood","examples":["Scientists carefully [log] all temperature changes during the experiment. (=Dịch: Các nhà khoa học cẩn thận ghi chép lại mọi sự thay đổi nhiệt độ trong quá trình thí nghiệm.)","Companies are not allowed to [log] trees in this protected forest. (=Dịch: Các công ty không được phép khai thác gỗ trong khu rừng được bảo vệ này.)","Users need to [log] their daily activities in the fitness app. (=Dịch: Người dùng cần ghi lại các hoạt động hằng ngày của mình vào ứng dụng rèn luyện sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=log&lang=en-GB&ipa=%2Fl%C9%91%CB%90%C9%A1%2F","usAudio":"/ai_services/tts3/?q=log&lang=en-US&ipa=%2Fl%C9%91%CB%90%C9%A1%2F"},{"id":"lv_5_211","topic":"Nature and Environmental Protection","word":"logical","pos":"(adj)","ipa":"/ˈlɑː.dʒɪ.kəl/","defVi":"hợp lý, lô-gích","defEn":"reasonable and based on clear, sound thinking","examples":["It seems [logical] to save money for emergencies rather than spending it all. (=Dịch: Có vẻ hợp lý khi tiết kiệm tiền cho những trường hợp khẩn cấp hơn là tiêu hết.)","She organized her essay in a clear and [logical] structure. (=Dịch: Cô ấy đã sắp xếp bài luận của mình theo một cấu trúc rõ ràng và hợp lý.)","The next [logical] step in his career was to apply for a managerial position. (=Dịch: Bước đi hợp lý tiếp theo trong sự nghiệp của anh ấy là ứng tuyển vào một vị trí quản lý.)"],"ukAudio":"/ai_services/tts3/?q=logical&lang=en-GB&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=logical&lang=en-US&ipa=%2F%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_5_212","topic":"Nature and Environmental Protection","word":"loss","pos":"(n)","ipa":"/lɔs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state of no longer having something, or a disadvantage caused by losing it","examples":["The company suffered a significant financial [loss] this quarter. (=Dịch: Công ty đã phải chịu một khoản tổn thất tài chính đáng kể trong quý này.)","Regular exercise helps prevent muscle [loss] as you age. (=Dịch: Tập thể dục thường xuyên giúp ngăn ngừa tình trạng mất cơ khi bạn già đi.)","He expressed deep sympathy for their [loss] after the tragedy. (=Dịch: Anh ấy đã bày tỏ sự cảm thông sâu sắc trước sự mất mát của họ sau thảm kịch.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94s%2F"},{"id":"lv_5_213","topic":"Nature and Environmental Protection","word":"lung","pos":"(n)","ipa":"/lʌŋ/","defVi":"phổi","defEn":"either of the two organs in the chest with which people and some animals breathe","examples":["Smoking can cause severe and irreversible damage to the [lung] tissue. (=Dịch: Hút thuốc có thể gây tổn thương nghiêm trọng và không thể hồi phục đối với mô phổi.)","She took a deep breath, filling her [lung] capacity completely before diving. (=Dịch: Cô ấy hít một hơi thật sâu, nạp đầy dung tích phổi trước khi lặn.)","Doctors monitored the patient's [lung] function after the infection. (=Dịch: Các bác sĩ đã theo dõi chức năng phổi của bệnh nhân sau đợt nhiễm trùng.)"],"ukAudio":"/ai_services/tts3/?q=lung&lang=en-GB&ipa=%2Fl%CA%8C%C5%8B%2F","usAudio":"/ai_services/tts3/?q=lung&lang=en-US&ipa=%2Fl%CA%8C%C5%8B%2F"},{"id":"lv_5_214","topic":"Nature and Environmental Protection","word":"machinery","pos":"(n)","ipa":"/məˈʃiː.nɚ.i/","defVi":"máy móc, thiết bị","defEn":"machines as a whole, or the working parts of a machine","examples":["The factory invested heavily in modern agricultural [machinery]. (=Dịch: Nhà máy đã đầu tư mạnh mẽ vào máy móc nông nghiệp hiện đại.)","Workers must wear safety gear when operating heavy [machinery]. (=Dịch: Công nhân phải mặc đồ bảo hộ khi vận hành máy móc hạng nặng.)","A technician was called to repair the broken [machinery]. (=Dịch: Một kỹ thuật viên đã được gọi đến để sửa chữa hệ thống máy móc bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=machinery&lang=en-GB&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=machinery&lang=en-US&ipa=%2Fm%C9%99%CB%88%CA%83i%CB%90.n%C9%9A.i%2F"},{"id":"lv_5_215","topic":"Nature and Environmental Protection","word":"mainland","pos":"(n)","ipa":"/ˈmeɪn.lænd/","defVi":"đất liền, lục địa","defEn":"the primary landmass of a country or continent, as distinguished from nearby islands","examples":["Ferries carry tourists from the small island to the [mainland] every hour. (=Dịch: Phà chở khách du lịch từ hòn đảo nhỏ vào đất liền mỗi giờ một chuyến.)","Prices for goods are usually cheaper on the [mainland] than on remote islands. (=Dịch: Giá hàng hóa ở đất liền thường rẻ hơn so với trên các hòn đảo xa xôi.)","The bridge connects the offshore community directly to the [mainland]. (=Dịch: Cây cầu kết nối cộng đồng ngoài đảo trực tiếp với đất liền.)"],"ukAudio":"/ai_services/tts3/?q=mainland&lang=en-GB&ipa=%2F%CB%88me%C9%AAn.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=mainland&lang=en-US&ipa=%2F%CB%88me%C9%AAn.l%C3%A6nd%2F"},{"id":"lv_5_216","topic":"Nature and Environmental Protection","word":"mammal","pos":"(n)","ipa":"/ˈmæm.əl/","defVi":"động vật có vú, thú","defEn":"any animal of which the female feeds her young on milk from her own body","examples":["The blue whale is recognized as the largest [mammal] on Earth. (=Dịch: Cá voi xanh được công nhận là loài động vật có vú lớn nhất trên Trái Đất.)","Unlike reptiles, every [mammal] is warm-blooded and typically gives birth to live young. (=Dịch: Không giống như bò sát, mọi loài động vật có vú đều là động vật máu nóng và thường đẻ con non.)","Bats are unique because they are the only [mammal] capable of true flight. (=Dịch: Loài dơi rất độc đáo vì chúng là loài động vật có vú duy nhất có khả năng bay thực sự.)"],"ukAudio":"/ai_services/tts3/?q=mammal&lang=en-GB&ipa=%2F%CB%88m%C3%A6m.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=mammal&lang=en-US&ipa=%2F%CB%88m%C3%A6m.%C9%99l%2F"},{"id":"lv_5_217","topic":"Nature and Environmental Protection","word":"mammoth","pos":"(n)","ipa":"/ˈmæm.əθ/","defVi":"voi ma mút","defEn":"a large, extinct elephant-like mammal with long curved tusks and hairy coat","examples":["The woolly [mammoth] lived during the Ice Age and roamed the northern plains. (=Dịch: Voi ma mút lông xoăn đã sống vào Kỷ Băng hà và lang thang khắp các đồng bằng phía bắc.)","Researchers discovered a well-preserved [mammoth] tusk buried in the permafrost. (=Dịch: Các nhà nghiên cứu đã phát hiện một chiếc ngà voi ma mút được bảo quản tốt bị vùi trong tầng đất đóng băng vĩnh cửu.)","Early humans hunted the [mammoth] for food, fur, and bones. (=Dịch: Người tiền sử đã săn bắt voi ma mút để lấy thức ăn, lông và xương.)"],"ukAudio":"/ai_services/tts3/?q=mammoth&lang=en-GB&ipa=%2F%CB%88m%C3%A6m.%C9%99%CE%B8%2F","usAudio":"/ai_services/tts3/?q=mammoth&lang=en-US&ipa=%2F%CB%88m%C3%A6m.%C9%99%CE%B8%2F"},{"id":"lv_5_218","topic":"Nature and Environmental Protection","word":"mane","pos":"(n)","ipa":"/meɪn/","defVi":"bờm (ngựa, sư tử), mái tóc dày","defEn":"the long, thick hair growing on the neck of a horse, lion, or other animal","examples":["The male lion has a magnificent dark [mane] around its neck. (=Dịch: Con sư tử đực có một chiếc bờm sẫm màu tuyệt đẹp quanh cổ.)","She brushed the horse's tangled [mane] until it was smooth. (=Dịch: Cô ấy đã chải chiếc bờm rối của con ngựa cho đến khi nó suôn mượt.)","The wind blew her thick [mane] of hair across her face. (=Dịch: Gió thổi mái tóc dày bồng bềnh của cô che ngang khuôn mặt.)"],"ukAudio":"/ai_services/tts3/?q=mane&lang=en-GB&ipa=%2Fme%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=mane&lang=en-US&ipa=%2Fme%C9%AAn%2F"},{"id":"lv_5_219","topic":"Nature and Environmental Protection","word":"mangrove","pos":"(n)","ipa":"/ˈmæŋ.ɡroʊv/","defVi":"cây đước; rừng ngập mặn","defEn":"a tropical tree or forest growing in wet mud near coasts or along tidal rivers","examples":["The [mangrove] forest acts as a natural barrier against sea storms. (=Dịch: Rừng ngập mặn đóng vai trò như một bức tường chắn tự nhiên chống lại bão biển.)","Many rare bird species nest in the thick [mangrove] swamps. (=Dịch: Nhiều loài chim quý hiếm làm tổ trong những đầm lầy ngập mặn rậm rạp.)","Conserving [mangroves] is vital for maintaining coastal biodiversity. (=Dịch: Bảo tồn rừng ngập mặn là điều sống còn để duy trì đa dạng sinh học ven biển.)"],"ukAudio":"/ai_services/tts3/?q=mangrove&lang=en-GB&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Av%2F","usAudio":"/ai_services/tts3/?q=mangrove&lang=en-US&ipa=%2F%CB%88m%C3%A6%C5%8B.%C9%A1ro%CA%8Av%2F"},{"id":"lv_5_220","topic":"Nature and Environmental Protection","word":"marine","pos":"(adj)","ipa":"/məˈriːn/","defVi":"thuộc về biển, đại dương hoặc sinh vật biển","defEn":"connected with the sea and the creatures that live there","examples":["Plastic pollution poses a serious threat to [marine] life. (=Dịch: Ô nhiễm rác thải nhựa gây ra mối đe dọa nghiêm trọng đối với sinh vật biển.)","She decided to study [marine] biology at university to explore coral reefs. (=Dịch: Cô quyết định học ngành sinh học biển tại trường đại học để khám phá các rạn san hô.)","Governments are creating [marine] reserves to protect endangered ocean species. (=Dịch: Các chính phủ đang thành lập các khu bảo tồn biển để bảo vệ các loài sinh vật biển có nguy cơ tuyệt chủng.)"],"ukAudio":"/ai_services/tts3/?q=marine&lang=en-GB&ipa=%2Fm%C9%99%CB%88ri%CB%90n%2F","usAudio":"/ai_services/tts3/?q=marine&lang=en-US&ipa=%2Fm%C9%99%CB%88ri%CB%90n%2F"},{"id":"lv_5_221","topic":"Nature and Environmental Protection","word":"massive","pos":"(adj)","ipa":"/ˈmæs.ɪv/","defVi":"to lớn, khổng lồ, trên diện rộng","defEn":"exceptionally large, heavy, or severe in scale","examples":["The earthquake caused [massive] destruction across the coastal region. (=Dịch: Trận động đất đã gây ra sự tàn phá khủng khiếp trên khắp vùng ven biển.)","The team undertook a [massive] research project that lasted five years. (=Dịch: Nhóm nghiên cứu đã đảm nhận một dự án nghiên cứu quy mô lớn kéo dài suốt 5 năm.)","A [massive] boulder blocked the entrance to the mountain pass. (=Dịch: Một tảng đá khổng lồ đã chặn mất lối vào đèo núi.)"],"ukAudio":"/ai_services/tts3/?q=massive&lang=en-GB&ipa=%2F%CB%88m%C3%A6s.%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=massive&lang=en-US&ipa=%2F%CB%88m%C3%A6s.%C9%AAv%2F"},{"id":"lv_5_222","topic":"Nature and Environmental Protection","word":"mediterranean","pos":"(n)","ipa":"/ˌmɛd.ə.təˈreɪ.ni.ən/","defVi":"Địa Trung Hải, vùng Địa Trung Hải","defEn":"the large sea between southern Europe and northern Africa, or its surrounding region","examples":["They spent their summer vacation sailing across the [mediterranean]. (=Dịch: Họ đã dành kỳ nghỉ hè để đi thuyền buồm dọc theo Địa Trung Hải.)","The climate of the [mediterranean] is characterized by hot, dry summers and mild winters. (=Dịch: Khí hậu của vùng Địa Trung Hải có đặc trưng là mùa hè nóng, khô và mùa đông ôn hòa.)","Many ancient civilizations flourished around the shores of the [mediterranean]. (=Dịch: Nhiều nền văn minh cổ đại đã phát triển hưng thịnh quanh bờ Địa Trung Hải.)"],"ukAudio":"/ai_services/tts3/?q=mediterranean&lang=en-GB&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99.t%C9%99%CB%88re%C9%AA.ni.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=mediterranean&lang=en-US&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99.t%C9%99%CB%88re%C9%AA.ni.%C9%99n%2F"},{"id":"lv_5_223","topic":"Nature and Environmental Protection","word":"mercury","pos":"(n)","ipa":"/ˈmɝː.kjə.ri/","defVi":"thủy ngân","defEn":"a toxic, heavy, silvery-white metallic element that is liquid at room temperature","examples":["Old thermometers often contain liquid [mercury] inside glass tubes. (=Dịch: Nhiệt kế kiểu cũ thường chứa thủy ngân dạng lỏng bên trong ống thủy tinh.)","High levels of [mercury] in seafood can pose serious health risks. (=Dịch: Hàm lượng thủy ngân cao trong hải sản có thể gây ra những nguy cơ sức khỏe nghiêm trọng.)","Industrial waste must be treated to prevent [mercury] from contaminating rivers. (=Dịch: Chất thải công nghiệp cần được xử lý để ngăn chặn thủy ngân làm ô nhiễm các dòng sông.)"],"ukAudio":"/ai_services/tts3/?q=mercury&lang=en-GB&ipa=%2F%CB%88m%C9%9D%CB%90.kj%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=mercury&lang=en-US&ipa=%2F%CB%88m%C9%9D%CB%90.kj%C9%99.ri%2F"},{"id":"lv_5_224","topic":"Nature and Environmental Protection","word":"meshing","pos":"(v)","ipa":"/ˈmɛʃ.ɪŋ/","defVi":"ăn khớp, kết hợp hài hòa","defEn":"engaging or fitting together closely and smoothly","examples":["The gears are smoothly [meshing] together to keep the machine running. (=Dịch: Các bánh răng đang ăn khớp nhịp nhàng với nhau để giữ cho cỗ máy hoạt động.)","She excels at [meshing] creative ideas with practical business strategies. (=Dịch: Cô ấy rất giỏi trong việc kết hợp hài hòa các ý tưởng sáng tạo với chiến lược kinh doanh thực tế.)","The two departments are successfully [meshing] their resources for the new project. (=Dịch: Hai phòng ban đang kết hợp thành công các nguồn lực cho dự án mới.)"],"ukAudio":"/ai_services/tts3/?q=meshing&lang=en-GB&ipa=%2F%CB%88m%C9%9B%CA%83.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=meshing&lang=en-US&ipa=%2F%CB%88m%C9%9B%CA%83.%C9%AA%C5%8B%2F"},{"id":"lv_5_225","topic":"Nature and Environmental Protection","word":"microbe","pos":"(n)","ipa":"/ˈmaɪ.kroʊb/","defVi":"vi trùng, vi sinh vật","defEn":"an extremely small living thing that can only be seen with a microscope, especially one causing disease","examples":["Soil contains millions of [microbe] species that help plants absorb nutrients. (=Dịch: Đất chứa hàng triệu loài vi sinh vật giúp cây cối hấp thụ chất dinh dưỡng.)","The new disinfectant is highly effective at killing every harmful [microbe]. (=Dịch: Chất khử trùng mới rất hiệu quả trong việc tiêu diệt mọi loại vi trùng có hại.)","Researchers discovered a novel [microbe] living deep beneath the ocean floor. (=Dịch: Các nhà nghiên cứu đã phát hiện một loại vi sinh vật mới sống sâu dưới đáy đại dương.)"],"ukAudio":"/ai_services/tts3/?q=microbe&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kro%CA%8Ab%2F","usAudio":"/ai_services/tts3/?q=microbe&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kro%CA%8Ab%2F"},{"id":"lv_5_226","topic":"Nature and Environmental Protection","word":"microplastic","pos":"(n)","ipa":"/ˈmaɪ.kroʊˌplæs.tɪk/","defVi":"hạt vi nhựa","defEn":"an extremely small piece of plastic debris found in the environment","examples":["Scientists found [microplastic] particles in the stomach of marine animals. (=Dịch: Các nhà khoa học đã tìm thấy các hạt vi nhựa trong dạ dày của các loài sinh vật biển.)","Synthetic clothing releases thousands of [microplastic] fibers during each wash. (=Dịch: Quần áo từ sợi tổng hợp thải ra hàng nghìn sợi vi nhựa sau mỗi lần giặt.)","Reducing plastic consumption is crucial to limiting [microplastic] pollution. (=Dịch: Cắt giảm tiêu thụ nhựa là điều quan trọng để hạn chế ô nhiễm vi nhựa.)"],"ukAudio":"/ai_services/tts3/?q=microplastic&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.kro%CA%8A%CB%8Cpl%C3%A6s.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=microplastic&lang=en-US&ipa=%2F%CB%88ma%C9%AA.kro%CA%8A%CB%8Cpl%C3%A6s.t%C9%AAk%2F"},{"id":"lv_5_227","topic":"Nature and Environmental Protection","word":"microscopic","pos":"(adj)","ipa":"/ˌmaɪ.krəˈskɑː.pɪk/","defVi":"kính hiển vi mới thấy được, siêu nhỏ","defEn":"so small that it can only be seen with a microscope","examples":["Bacteria are [microscopic] organisms that live on nearly every surface. (=Dịch: Vi khuẩn là những sinh vật siêu nhỏ sống trên hầu như mọi bề mặt.)","The engineer detected a [microscopic] crack in the metal turbine. (=Dịch: Kỹ sư đã phát hiện ra một vết nứt siêu nhỏ trong tuabin kim loại.)","Phytoplankton are [microscopic] plants floating in ocean waters. (=Dịch: Thực vật phù du là những loài thực vật kích thước hiển vi trôi nổi trong nước biển.)"],"ukAudio":"/ai_services/tts3/?q=microscopic&lang=en-GB&ipa=%2F%CB%8Cma%C9%AA.kr%C9%99%CB%88sk%C9%91%CB%90.p%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=microscopic&lang=en-US&ipa=%2F%CB%8Cma%C9%AA.kr%C9%99%CB%88sk%C9%91%CB%90.p%C9%AAk%2F"},{"id":"lv_5_228","topic":"Nature and Environmental Protection","word":"migrate","pos":"(v)","ipa":"/ˈmaɪ.ɡreɪt/","defVi":"Di cư, di trú","defEn":"To move from one region or habitat to another, especially according to the seasons","examples":["Many birds [migrate] south to warmer climates during the winter. (=Dịch: Nhiều loài chim di cư về phía nam đến những vùng khí hậu ấm hơn trong suốt mùa đông.)","Thousands of farm workers [migrate] to cities in search of seasonal employment. (=Dịch: Hàng nghìn lao động nông nghiệp di cư đến các thành phố để tìm kiếm việc làm thời vụ.)","Whales [migrate] great distances across the ocean to reach their feeding grounds. (=Dịch: Cá voi di cư qua những quãng đường rất dài trên đại dương để đến các bãi kiếm ăn.)"],"ukAudio":"/ai_services/tts3/?q=migrate&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=migrate&lang=en-US&ipa=%2F%CB%88ma%C9%AA.%C9%A1re%C9%AAt%2F"},{"id":"lv_5_229","topic":"Nature and Environmental Protection","word":"migration","pos":"(n)","ipa":"/maɪˈɡreɪ.ʃən/","defVi":"sự di cư, tập tính di trú","defEn":"the seasonal movement of animals or birds from one region to another","examples":["The annual [migration] of wildebeests across the Serengeti is a breathtaking spectacle. (=Dịch: Cuộc di cư hàng năm của linh dương đầu bò qua Serengeti là một cảnh tượng ngoạn mục.)","Rising temperatures are altering the timing of bird [migration] across North America. (=Dịch: Nhiệt độ tăng cao đang làm thay đổi thời gian di cư của các loài chim trên khắp Bắc Mỹ.)","Whales travel thousands of miles during their seasonal [migration] to warmer waters. (=Dịch: Cá voi di chuyển hàng nghìn dặm trong chuyến di cư theo mùa đến những vùng nước ấm hơn.)"],"ukAudio":"/ai_services/tts3/?q=migration&lang=en-GB&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=migration&lang=en-US&ipa=%2Fma%C9%AA%CB%88%C9%A1re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_230","topic":"Nature and Environmental Protection","word":"military","pos":"(adj)","ipa":"/ˈmɪl.əˌter.i/","defVi":"thuộc về quân đội, quân sự","defEn":"relating to the armed forces or soldiers of a country","examples":["The country increased its [military] spending to strengthen border defense. (=Dịch: Quốc gia này đã tăng chi tiêu quân sự để củng cố phòng thủ biên giới.)","He completed two years of mandatory [military] service after university. (=Dịch: Anh ấy đã hoàn thành hai năm nghĩa vụ quân sự bắt buộc sau khi tốt nghiệp đại học.)","Drones are increasingly used for reconnaissance in modern [military] operations. (=Dịch: Máy bay không người lái ngày càng được sử dụng nhiều cho hoạt động do thám trong các chiến dịch quân sự hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=military&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Cter.i%2F","usAudio":"/ai_services/tts3/?q=military&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Cter.i%2F"},{"id":"lv_5_231","topic":"Nature and Environmental Protection","word":"millimetre","pos":"(n)","ipa":"/ˈmɪl.ə.ˌmi.t̬ər/","defVi":"mi-li-mét (mm)","defEn":"a unit of length equal to one thousandth of a meter","examples":["The metal component was manufactured with an error margin of less than one [millimetre]. (=Dịch: Linh kiện kim loại được sản xuất với mức dung sai nhỏ hơn một mi-li-mét.)","The tiny ant measured only three [millimetre]s in total body length. (=Dịch: Con kiến bé xíu chỉ có chiều dài cơ thể tổng cộng là ba mi-li-mét.)","The heavy rainfall added twenty [millimetre]s of water to the reservoir overnight. (=Dịch: Trận mưa lớn đã làm mực nước hồ chứa tăng thêm hai mươi mi-li-mét chỉ sau một đêm.)"],"ukAudio":"/ai_services/tts3/?q=millimetre&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99.%CB%8Cmi.t%CC%AC%C9%99r%2F","usAudio":"/ai_services/tts3/?q=millimetre&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99.%CB%8Cmi.t%CC%AC%C9%99r%2F"},{"id":"lv_5_232","topic":"Nature and Environmental Protection","word":"miner","pos":"(n)","ipa":"/ˈmaɪ.nɚ/","defVi":"thợ mỏ","defEn":"a person who works underground extracting coal, minerals, or precious metals","examples":["The rescue team worked tirelessly to save the trapped [miner] after the cave-in. (=Dịch: Đội cứu hộ đã làm việc không mệt mỏi để cứu người thợ mỏ bị mắc kẹt sau vụ sập hầm.)","A gold [miner] must endure harsh physical conditions every day. (=Dịch: Một người thợ mỏ vàng phải chịu đựng những điều kiện thể chất khắc nghiệt mỗi ngày.)","His grandfather was a coal [miner] who spent forty years underground. (=Dịch: Ông của anh ấy từng là một thợ mỏ than đã dành bốn mươi năm làm việc dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=miner&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=miner&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%9A%2F"},{"id":"lv_5_233","topic":"Nature and Environmental Protection","word":"mining","pos":"(n)","ipa":"/ˈmaɪ.nɪŋ/","defVi":"ngành khai khoáng, hoạt động khai thác mỏ","defEn":"the process or industry of extracting coal or other minerals from the earth","examples":["The economy of the region depends heavily on copper [mining]. (=Dịch: Nền kinh tế của khu vực này phụ thuộc nhiều vào việc khai thác đồng.)","Environmentalists are concerned about the impact of deep-sea [mining] on marine life. (=Dịch: Các nhà bảo vệ môi trường lo ngại về tác động của việc khai thác mỏ dưới biển sâu đối với sinh vật biển.)","New regulations were introduced to make the [mining] industry safer for workers. (=Dịch: Các quy định mới đã được ban hành nhằm giúp ngành khai khoáng an toàn hơn cho người lao động.)"],"ukAudio":"/ai_services/tts3/?q=mining&lang=en-GB&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=mining&lang=en-US&ipa=%2F%CB%88ma%C9%AA.n%C9%AA%C5%8B%2F"},{"id":"lv_5_234","topic":"Nature and Environmental Protection","word":"mixture","pos":"(n)","ipa":"/ˈmɪks.tʃɚ/","defVi":"Hỗn hợp, sự pha trộn.","defEn":"A substance made by combining two or more different things together.","examples":["Add the eggs to the flour [mixture] and stir gently until smooth. (=Dịch: Cho trứng vào hỗn hợp bột mì và khuấy nhẹ cho đến khi mịn.)","Her feelings about leaving her hometown were a complex [mixture] of excitement and fear. (=Dịch: Cảm xúc của cô khi rời quê hương là một sự pha trộn phức tạp giữa phấn khích và sợ hãi.)","Air is a [mixture] of gases including nitrogen and oxygen. (=Dịch: Không khí là một hỗn hợp các chất khí bao gồm nitơ và oxy.)"],"ukAudio":"/ai_services/tts3/?q=mixture&lang=en-GB&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=mixture&lang=en-US&ipa=%2F%CB%88m%C9%AAks.t%CA%83%C9%9A%2F"},{"id":"lv_5_235","topic":"Nature and Environmental Protection","word":"moist","pos":"(adj)","ipa":"/mɔɪst/","defVi":"Ẩm ướt, ẩm nhẹ.","defEn":"Slightly wet, often in a pleasant or desirable way.","examples":["The cake was delicious and delightfully [moist]. (=Dịch: Chiếc bánh rất ngon và có độ ẩm xốp vừa phải.)","Keep the soil [moist] but not completely soaked. (=Dịch: Hãy giữ cho đất ẩm nhưng không bị sũng nước hoàn toàn.)","She used a cream to keep her skin soft and [moist]. (=Dịch: Cô ấy đã sử dụng kem dưỡng để giữ cho làn da mềm mại và đủ ẩm.)"],"ukAudio":"/ai_services/tts3/?q=moist&lang=en-GB&ipa=%2Fm%C9%94%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=moist&lang=en-US&ipa=%2Fm%C9%94%C9%AAst%2F"},{"id":"lv_5_236","topic":"Nature and Environmental Protection","word":"monitor","pos":"(v)","ipa":"/ˈmɑː.nɪ.tər/","defVi":"giám sát, theo dõi","defEn":"to watch and check something carefully over a period of time","examples":["Doctors will [monitor] the patient's heart rate throughout the surgery. (=Dịch: Các bác sĩ sẽ theo dõi nhịp tim của bệnh nhân trong suốt ca phẫu thuật.)","Environmental agencies [monitor] air quality in major cities daily. (=Dịch: Các cơ quan môi trường giám sát chất lượng không khí ở các thành phố lớn hàng ngày.)","Teachers use regular quizzes to [monitor] their students' progress. (=Dịch: Giáo viên sử dụng các bài kiểm tra thường xuyên để theo dõi tiến độ của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=monitor&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=monitor&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%AA.t%C9%99r%2F"},{"id":"lv_5_237","topic":"Nature and Environmental Protection","word":"moss","pos":"(n)","ipa":"/mɔːs/","defVi":"rêu","defEn":"a very small, soft green plant that grows on damp soil, rocks, or trees","examples":["Green [moss] covered the northern side of the ancient stone wall. (=Dịch: Rêu xanh bao phủ mặt phía bắc của bức tường đá cổ kính.)","The damp forest floor was carpeted with thick, soft [moss]. (=Dịch: Mặt đất rừng ẩm ướt được trải một lớp thảm rêu dày và mềm mại.)","Certain types of [moss] are useful indicators of air pollution levels. (=Dịch: Một số loại rêu là chỉ dấu hữu ích về mức độ ô nhiễm không khí.)"],"ukAudio":"/ai_services/tts3/?q=moss&lang=en-GB&ipa=%2Fm%C9%94%CB%90s%2F","usAudio":"/ai_services/tts3/?q=moss&lang=en-US&ipa=%2Fm%C9%94%CB%90s%2F"},{"id":"lv_5_238","topic":"Nature and Environmental Protection","word":"mud","pos":"(n)","ipa":"/mʌd/","defVi":"bùn, sình lầy","defEn":"wet, soft, and sticky earth or soil","examples":["The heavy rain turned the dirt path into thick [mud]. (=Dịch: Cơn mưa lớn đã biến con đường đất thành bùn lầy đặc quánh.)","Her boots were caked with [mud] after hiking through the swamp. (=Dịch: Đôi ủng của cô ấy bị đóng đầy bùn sau khi đi bộ qua đầm lầy.)","Children love playing in the [mud] after a summer shower. (=Dịch: Trẻ em rất thích chơi trong bùn sau cơn mưa rào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=mud&lang=en-GB&ipa=%2Fm%CA%8Cd%2F","usAudio":"/ai_services/tts3/?q=mud&lang=en-US&ipa=%2Fm%CA%8Cd%2F"},{"id":"lv_5_239","topic":"Nature and Environmental Protection","word":"naturalist","pos":"(n)","ipa":"/ˈnætʃ.ɚ.ə.lɪst/","defVi":"nhà tự nhiên học","defEn":"an expert in or student of natural history, especially plants and animals","examples":["Charles Darwin was a famous [naturalist] who developed the theory of evolution. (=Dịch: Charles Darwin là một nhà tự nhiên học nổi tiếng, người đã phát triển thuyết tiến hóa.)","The [naturalist] documented several rare bird species in the rainforest. (=Dịch: Nhà tự nhiên học đã ghi chép lại một số loài chim quý hiếm trong rừng nhiệt đới.)","As a passionate [naturalist], she spent years studying local insect behaviors. (=Dịch: Là một nhà tự nhiên học đầy nhiệt huyết, cô đã dành nhiều năm để nghiên cứu tập tính của côn trùng địa phương.)"],"ukAudio":"/ai_services/tts3/?q=naturalist&lang=en-GB&ipa=%2F%CB%88n%C3%A6t%CA%83.%C9%9A.%C9%99.l%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=naturalist&lang=en-US&ipa=%2F%CB%88n%C3%A6t%CA%83.%C9%9A.%C9%99.l%C9%AAst%2F"},{"id":"lv_5_240","topic":"Nature and Environmental Protection","word":"navigation","pos":"(n)","ipa":"/ˌnæv.əˈɡeɪ.ʃən/","defVi":"sự định hướng, điều hướng, hàng hải","defEn":"the act or science of finding the way to a destination","examples":["Modern cars are often equipped with satellite [navigation] systems. (=Dịch: Xe ô tô hiện đại thường được trang bị hệ thống định vị vệ tinh.)","Early sailors relied on the stars for [navigation] across the open sea. (=Dịch: Các thủy thủ thời xưa dựa vào các vì sao để định hướng trên biển rộng.)","Clear [navigation] makes a website much easier for users to explore. (=Dịch: Hệ thống điều hướng rõ ràng giúp người dùng khám phá trang web dễ dàng hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=navigation&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6v.%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=navigation&lang=en-US&ipa=%2F%CB%8Cn%C3%A6v.%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_241","topic":"Nature and Environmental Protection","word":"nesting","pos":"(n)","ipa":"/ˈnɛs.tɪŋ/","defVi":"Sự làm tổ, sự đẻ trứng tại tổ","defEn":"The activity of building or occupying a nest, especially by birds or sea turtles, to lay eggs","examples":["Spring is the main [nesting] season for most local bird species. (=Dịch: Mùa xuân là mùa làm tổ chính của hầu hết các loài chim địa phương.)","The coastal area was closed to tourists to protect the sea turtles' [nesting] sites. (=Dịch: Khu vực ven biển đã bị đóng cửa đối với du khách để bảo vệ các địa điểm làm tổ của rùa biển.)","Researchers monitored the [nesting] habits of eagles using hidden cameras. (=Dịch: Các nhà nghiên cứu đã theo dõi tập tính làm tổ của đại bàng bằng máy quay giấu kín.)"],"ukAudio":"/ai_services/tts3/?q=nesting&lang=en-GB&ipa=%2F%CB%88n%C9%9Bs.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=nesting&lang=en-US&ipa=%2F%CB%88n%C9%9Bs.t%C9%AA%C5%8B%2F"},{"id":"lv_5_242","topic":"Nature and Environmental Protection","word":"net","pos":"(n)","ipa":"/nɛt/","defVi":"lưới, mạng lưới","defEn":"a material made of crossed threads or wires with evenly spaced openings","examples":["The fisherman cast his [net] into the calm morning waters. (=Dịch: Người đánh cá quăng tấm lưới của mình xuống làn nước êm ả buổi sáng.)","The tennis ball hit the top of the [net] and bounced back onto our side. (=Dịch: Quả bóng tennis đập vào mép trên của lưới rồi nảy ngược lại phần sân của chúng tôi.)","Gardeners use protective [net] to keep birds away from ripening berries. (=Dịch: Những người làm vườn sử dụng lưới bảo vệ để ngăn chim chóc tiếp cận quả mọng đang chín.)"],"ukAudio":"/ai_services/tts3/?q=net&lang=en-GB&ipa=%2Fn%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=net&lang=en-US&ipa=%2Fn%C9%9Bt%2F"},{"id":"lv_5_243","topic":"Nature and Environmental Protection","word":"new zealand","pos":"(n)","ipa":"/ˌnuː ˈziː.lənd/","defVi":"nước New Zealand (Tân Tây Lan)","defEn":"an island country in the southwestern Pacific Ocean","examples":["Many tourists visit [New zealand] to explore its stunning fjords and mountains. (=Dịch: Nhiều du khách đến thăm New Zealand để khám phá những vịnh hẹp và dãy núi tuyệt đẹp.)","Agriculture and tourism are key sectors of the economy in [New zealand]. (=Dịch: Nông nghiệp và du lịch là những ngành kinh tế then chốt ở New Zealand.)","The indigenous Maori culture plays a vital role in modern [New zealand]. (=Dịch: Văn hóa bản địa Maori đóng một vai trò quan trọng ở New Zealand ngày nay.)"],"ukAudio":"/ai_services/tts3/?q=new+zealand&lang=en-GB&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=new+zealand&lang=en-US&ipa=%2F%CB%8Cnu%CB%90+%CB%88zi%CB%90.l%C9%99nd%2F"},{"id":"lv_5_244","topic":"Nature and Environmental Protection","word":"nuclear","pos":"(adj)","ipa":"/ˈnuː.kli.ɚ/","defVi":"(thuộc) hạt nhân, nguyên tử","defEn":"relating to the nucleus of an atom, or using energy produced by splitting atoms","examples":["Several countries rely on [nuclear] power to generate electricity without carbon emissions. (=Dịch: Một số quốc gia dựa vào năng lượng hạt nhân để sản xuất điện mà không phát thải carbon.)","The government signed a treaty aimed at preventing the proliferation of [nuclear] weapons. (=Dịch: Chính phủ đã ký một hiệp ước nhằm ngăn chặn sự phổ biến vũ khí hạt nhân.)","Scientists are researching safer methods for disposing of [nuclear] waste. (=Dịch: Các nhà khoa học đang nghiên cứu các phương pháp an toàn hơn để xử lý chất thải hạt nhân.)"],"ukAudio":"/ai_services/tts3/?q=nuclear&lang=en-GB&ipa=%2F%CB%88nu%CB%90.kli.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=nuclear&lang=en-US&ipa=%2F%CB%88nu%CB%90.kli.%C9%9A%2F"},{"id":"lv_5_245","topic":"Nature and Environmental Protection","word":"nutrient","pos":"(n)","ipa":"/ˈnuː.tri.ənt/","defVi":"chất dinh dưỡng, dưỡng chất","defEn":"a substance that plants or animals need in order to live, grow, and stay healthy","examples":["Vegetables are rich in vitamins, minerals, and other essential [nutrient] sources. (=Dịch: Rau củ rất giàu vitamin, khoáng chất và các nguồn dưỡng chất thiết yếu khác.)","Fertile soil provides every necessary [nutrient] for crop cultivation. (=Dịch: Đất màu mỡ cung cấp mọi chất dinh dưỡng cần thiết cho việc trồng trọt.)","A deficiency in a single vital [nutrient] can cause significant health problems. (=Dịch: Sự thiếu hụt một dưỡng chất quan trọng duy nhất cũng có thể gây ra những vấn đề sức khỏe đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=nutrient&lang=en-GB&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=nutrient&lang=en-US&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F"},{"id":"lv_5_246","topic":"Nature and Environmental Protection","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, theo dõi","defEn":"the act of watching somebody or something carefully to gain information","examples":["The researcher spent months in the jungle doing field [observation]. (=Dịch: Nhà nghiên cứu đã dành nhiều tháng trong rừng sâu để thực hiện việc quan sát thực địa.)","The doctor kept the patient under close [observation] overnight. (=Dịch: Bác sĩ đã giữ bệnh nhân lại để theo dõi sát sao qua đêm.)","Her keen [observation] helped solve the mystery quickly. (=Dịch: Khả năng quan sát nhạy bén của cô ấy đã giúp giải quyết điều bí ẩn một cách nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_247","topic":"Nature and Environmental Protection","word":"observer","pos":"(n)","ipa":"/əbˈzɝː.vɚ/","defVi":"người quan sát, quan sát viên","defEn":"a person who watches or notices something, especially for an official or scientific purpose","examples":["An independent [observer] was invited to monitor the national election. (=Dịch: Một quan sát viên độc lập đã được mời đến để giám sát cuộc bầu cử quốc gia.)","To a casual [observer], the two paintings might look identical. (=Dịch: Đối với một người quan sát bình thường, hai bức tranh có thể trông giống hệt nhau.)","The trained [observer] noted subtle changes in the animal's behavior. (=Dịch: Người quan sát có chuyên môn đã ghi nhận những thay đổi tinh tế trong hành vi của con vật.)"],"ukAudio":"/ai_services/tts3/?q=observer&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%9D%CB%90.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=observer&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%9D%CB%90.v%C9%9A%2F"},{"id":"lv_5_248","topic":"Nature and Environmental Protection","word":"onshore","pos":"(adj)","ipa":"/ˈɑːn.ʃɔːr/","defVi":"trên bờ, trên đất liền; hướng vào bờ","defEn":"located, occurring, or moving on land rather than at sea","examples":["The government is investing heavily in [onshore] wind farms. (=Dịch: Chính phủ đang đầu tư mạnh vào các trang trại điện gió trên bờ liền.)","An [onshore] breeze brought cool air to the coastal town. (=Dịch: Một làn gió thổi vào bờ mang lại không khí mát mẻ cho thị trấn ven biển.)","The company decided to shift to [onshore] oil drilling operations. (=Dịch: Công ty đã quyết định chuyển sang các hoạt động khoan dầu trên đất liền.)"],"ukAudio":"/ai_services/tts3/?q=onshore&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90n.%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=onshore&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90n.%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_249","topic":"Nature and Environmental Protection","word":"organ","pos":"(n)","ipa":"/ˈɔr.ɡən/","defVi":"cơ quan, bộ phận cơ thể","defEn":"a part of the body that performs a specific vital function","examples":["The heart is a vital [organ] that pumps blood throughout the body. (=Dịch: Tim là một cơ quan quan trọng bơm máu đi khắp cơ thể.)","Excessive alcohol consumption can damage your internal [organ] systems. (=Dịch: Uống quá nhiều rượu bia có thể gây tổn hại cho các hệ cơ quan nội tạng của bạn.)","The skin is actually the largest [organ] of the human body. (=Dịch: Da thực chất là cơ quan lớn nhất của cơ thể con người.)"],"ukAudio":"/ai_services/tts3/?q=organ&lang=en-GB&ipa=%2F%CB%88%C9%94r.%C9%A1%C9%99n%2F","usAudio":"/ai_services/tts3/?q=organ&lang=en-US&ipa=%2F%CB%88%C9%94r.%C9%A1%C9%99n%2F"},{"id":"lv_5_250","topic":"Nature and Environmental Protection","word":"organic","pos":"(adj)","ipa":"/ɔːrˈɡæn.ɪk/","defVi":"hữu cơ, không dùng phân bón hóa học","defEn":"produced without using artificial chemicals or pesticides","examples":["Many supermarkets now offer a wide range of [organic] vegetables. (=Dịch: Nhiều siêu thị hiện nay cung cấp đa dạng các loại rau hữu cơ.)","The farm transitioned to [organic] agriculture five years ago. (=Dịch: Trang trại đã chuyển đổi sang nền nông nghiệp hữu cơ cách đây 5 năm.)","Consumers are often willing to pay more for certified [organic] food. (=Dịch: Người tiêu dùng thường sẵn sàng trả nhiều tiền hơn cho thực phẩm hữu cơ đã được chứng nhận.)"],"ukAudio":"/ai_services/tts3/?q=organic&lang=en-GB&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=organic&lang=en-US&ipa=%2F%C9%94%CB%90r%CB%88%C9%A1%C3%A6n.%C9%AAk%2F"},{"id":"lv_5_251","topic":"Nature and Environmental Protection","word":"organism","pos":"(n)","ipa":"/ˈɔːr.ɡən.ɪ.zəm/","defVi":"sinh vật, cơ thể sống","defEn":"an individual animal, plant, or single-celled life form","examples":["A coral reef is home to thousands of different [organism] species. (=Dịch: Rạn san hô là nơi sinh sống của hàng ngàn loài sinh vật khác nhau.)","Bacteria are tiny [organism] forms that can survive in extreme environments. (=Dịch: Vi khuẩn là các dạng sinh vật nhỏ bé có thể sống sót trong những môi trường khắc nghiệt.)","Every living [organism] requires water to survive and function properly. (=Dịch: Mọi sinh vật sống đều cần nước để tồn tại và hoạt động bình thường.)"],"ukAudio":"/ai_services/tts3/?q=organism&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99n.%C9%AA.z%C9%99m%2F","usAudio":"/ai_services/tts3/?q=organism&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%A1%C9%99n.%C9%AA.z%C9%99m%2F"},{"id":"lv_5_252","topic":"Nature and Environmental Protection","word":"overpopulation","pos":"(n)","ipa":"/ˌoʊ.vərˌpɑː.pjəˈleɪ.ʃən/","defVi":"tình trạng bùng nổ dân số, quá tải dân số","defEn":"a situation where too many people or animals live in a place with insufficient resources","examples":["Many urban planners believe that [overpopulation] is the root cause of traffic congestion. (=Dịch: Nhiều nhà quy hoạch đô thị tin rằng quá tải dân số là nguyên nhân gốc rễ của tình trạng ùn tắc giao thông.)","The government is trying to tackle [overpopulation] by encouraging families to move to smaller towns. (=Dịch: Chính phủ đang cố gắng giải quyết tình trạng quá tải dân số bằng cách khuyến khích các gia đình chuyển đến các thị trấn nhỏ hơn.)","Severe [overpopulation] puts immense pressure on natural resources such as water and arable land. (=Dịch: Sự bùng nổ dân số nghiêm trọng tạo áp lực to lớn lên các tài nguyên thiên nhiên như nước và đất canh tác.)"],"ukAudio":"/ai_services/tts3/?q=overpopulation&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=overpopulation&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_253","topic":"Nature and Environmental Protection","word":"oxford","pos":"(n)","ipa":"/ˈɑːks.fərd/","defVi":"thành phố Oxford (Anh); kiểu giày Oxford buộc dây","defEn":"a city in England famous for its prestigious university, or a type of leather shoe","examples":["She was accepted to study history at [Oxford] University. (=Dịch: Cô ấy đã được nhận vào học ngành lịch sử tại Đại học Oxford.)","He wore polished [oxford] shoes to his job interview. (=Dịch: Anh ấy đã mang một đôi giày oxford bóng loáng đến buổi phỏng vấn xin việc.)","Many historic buildings attract tourists to the city of [Oxford]. (=Dịch: Nhiều công trình lịch sử thu hút khách du lịch đến thành phố Oxford.)"],"ukAudio":"/ai_services/tts3/?q=oxford&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%99rd%2F","usAudio":"/ai_services/tts3/?q=oxford&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%99rd%2F"},{"id":"lv_5_254","topic":"Nature and Environmental Protection","word":"oxygen","pos":"(n)","ipa":"/ˈɑːk.sə.dʒən/","defVi":"khí ô-xy","defEn":"a chemical element that is a colorless, odorless gas essential for most living organisms","examples":["Trees absorb carbon dioxide and release [oxygen] into the atmosphere. (=Dịch: Cây cối hấp thụ khí carbon dioxide và giải phóng khí ô-xy vào khí quyển.)","Divers must monitor their [oxygen] tanks closely while exploring deep waters. (=Dịch: Thợ lặn phải theo dõi sát sao bình dưỡng khí ô-xy của họ khi khám phá các vùng nước sâu.)","A decrease in [oxygen] levels in lakes can lead to massive fish deaths. (=Dịch: Sự suy giảm nồng độ ô-xy trong các hồ nước có thể dẫn đến việc cá chết hàng loạt.)"],"ukAudio":"/ai_services/tts3/?q=oxygen&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90k.s%C9%99.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=oxygen&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90k.s%C9%99.d%CA%92%C9%99n%2F"},{"id":"lv_5_255","topic":"Nature and Environmental Protection","word":"ozone","pos":"(n)","ipa":"/ˈoʊ.zoʊn/","defVi":"khí ô-dôn (tầng ô-dôn)","defEn":"a form of oxygen that forms a layer in the atmosphere protecting the Earth from ultraviolet radiation","examples":["The [ozone] layer shields living organisms from harmful ultraviolet radiation. (=Dịch: Tầng ô-dôn che chắn cho các sinh vật sống khỏi bức xạ cực tím độc hại.)","Damage to the [ozone] layer has led to an increase in skin cancer rates. (=Dịch: Sự suy giảm tầng ô-dôn đã dẫn đến sự gia tăng tỷ lệ mắc bệnh ung thư da.)","International agreements have helped reduce emissions that destroy [ozone]. (=Dịch: Các hiệp định quốc tế đã giúp giảm lượng khí thải phá hủy tầng ô-dôn.)"],"ukAudio":"/ai_services/tts3/?q=ozone&lang=en-GB&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=ozone&lang=en-US&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F"},{"id":"lv_5_256","topic":"Nature and Environmental Protection","word":"pacific","pos":"(adj)","ipa":"/pəˈsɪf.ɪk/","defVi":"Hòa bình, thanh bình, yên ổn.","defEn":"Peaceful in character or intent.","examples":["The two nations reached a [pacific] solution to the border conflict. (=Dịch: Hai quốc gia đã đạt được một giải pháp hòa bình cho cuộc xung đột biên giới.)","He was praised for his [pacific] temperament during tense debates. (=Dịch: Ông ấy được khen ngợi vì thái độ điềm đạm, chuộng hòa bình trong các cuộc tranh luận căng thẳng.)","They sought to establish [pacific] relations with their neighboring countries. (=Dịch: Họ tìm cách thiết lập mối quan hệ hòa bình với các nước láng giềng.)"],"ukAudio":"/ai_services/tts3/?q=pacific&lang=en-GB&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=pacific&lang=en-US&ipa=%2Fp%C9%99%CB%88s%C9%AAf.%C9%AAk%2F"},{"id":"lv_5_257","topic":"Nature and Environmental Protection","word":"packaging","pos":"(n)","ipa":"/ˈpæk.ɪ.dʒɪŋ/","defVi":"bao bì, sự đóng gói","defEn":"the materials used to wrap and protect goods sold in stores","examples":["The company switched to eco-friendly [packaging] to minimize plastic waste. (=Dịch: Công ty đã chuyển sang bao bì thân thiện với môi trường để giảm thiểu rác thải nhựa.)","Attractive [packaging] often plays a key role in influencing consumer choices. (=Dịch: Bao bì bắt mắt thường đóng vai trò quan trọng trong việc tác động đến lựa chọn của người tiêu dùng.)","All product details and nutritional facts are printed clearly on the [packaging]. (=Dịch: Tất cả thông tin chi tiết về sản phẩm và thành phần dinh dưỡng đều được in rõ ràng trên bao bì.)"],"ukAudio":"/ai_services/tts3/?q=packaging&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=packaging&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_5_258","topic":"Nature and Environmental Protection","word":"parasite","pos":"(n)","ipa":"/ˈper.ə.saɪt/","defVi":"ký sinh trùng, sinh vật ký sinh","defEn":"an organism that lives on or in a host and gets its food from or at the expense of its host","examples":["Fleas and ticks are common [parasite] species that live on mammals. (=Dịch: Bọ chét và ve là những loài ký sinh trùng phổ biến sống trên động vật có vú.)","The internal [parasite] caused severe abdominal pain in the host animal. (=Dịch: Loài ký sinh trùng đường ruột đã gây ra đau bụng dữ dội ở vật chủ.)","Clean drinking water prevents the spread of waterborne [parasite] infections. (=Dịch: Nguồn nước uống sạch giúp ngăn chặn sự lây lan của các bệnh nhiễm trùng do ký sinh trùng truyền qua nước.)"],"ukAudio":"/ai_services/tts3/?q=parasite&lang=en-GB&ipa=%2F%CB%88per.%C9%99.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=parasite&lang=en-US&ipa=%2F%CB%88per.%C9%99.sa%C9%AAt%2F"},{"id":"lv_5_259","topic":"Nature and Environmental Protection","word":"particle","pos":"(n)","ipa":"/ˈpɑːr.t̬ɪ.kəl/","defVi":"hạt, vi hạt","defEn":"a minute portion of matter","examples":["Air filters are designed to remove dust [particle] from indoor environments. (=Dịch: Máy lọc không khí được thiết kế để loại bỏ các hạt bụi khỏi môi trường trong nhà.)","Scientists study subatomic [particle] interactions in massive accelerators. (=Dịch: Các nhà khoa học nghiên cứu sự tương tác của các hạt hạ nguyên tử trong những máy gia tốc khổng lồ.)","There was not a single [particle] of evidence to support his wild theory. (=Dịch: Không hề có một mảy may bằng chứng nào hỗ trợ cho giả thuyết kỳ quặc của anh ta.)"],"ukAudio":"/ai_services/tts3/?q=particle&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=particle&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F"},{"id":"lv_5_260","topic":"Nature and Environmental Protection","word":"patch","pos":"(n)","ipa":"/pætʃ/","defVi":"mảnh đất nhỏ, miếng vá","defEn":"a small piece of land differing from the area around it, or material used to cover a hole","examples":["He grows organic vegetables in a small [patch] behind his cottage. (=Dịch: Anh ấy trồng rau hữu cơ trên một mảnh đất nhỏ phía sau ngôi nhà tranh của mình.)","The jacket had a leather [patch] sewn over the worn elbow area. (=Dịch: Chiếc áo khoác có một miếng vá bằng da được may đè lên phần khuỷu tay đã sờn.)","Drivers must slow down when approaching this icy [patch] on the mountain road. (=Dịch: Các tài xế phải giảm tốc độ khi đi đến đoạn đường đóng băng này trên đèo núi.)"],"ukAudio":"/ai_services/tts3/?q=patch&lang=en-GB&ipa=%2Fp%C3%A6t%CA%83%2F","usAudio":"/ai_services/tts3/?q=patch&lang=en-US&ipa=%2Fp%C3%A6t%CA%83%2F"},{"id":"lv_5_261","topic":"Nature and Environmental Protection","word":"peanut","pos":"(n)","ipa":"/ˈpi.nʌt/","defVi":"củ lạc, đậu phộng","defEn":"an oval nut with a thin shell that grows underground and can be eaten","examples":["He has a severe allergy to [peanut] butter. (=Dịch: Anh ấy bị dị ứng nghiêm trọng với bơ đậu phộng.)","A small [peanut] dropped from the table onto the floor. (=Dịch: Một hạt đậu phộng nhỏ đã rơi từ trên bàn xuống sàn nhà.)","She bought a bag of roasted [peanut] snacks at the market. (=Dịch: Cô ấy đã mua một túi đồ ăn vặt từ hạt lạc rang ở chợ.)"],"ukAudio":"/ai_services/tts3/?q=peanut&lang=en-GB&ipa=%2F%CB%88pi.n%CA%8Ct%2F","usAudio":"/ai_services/tts3/?q=peanut&lang=en-US&ipa=%2F%CB%88pi.n%CA%8Ct%2F"},{"id":"lv_5_262","topic":"Nature and Environmental Protection","word":"pellet","pos":"(n)","ipa":"/ˈpel.ɪt/","defVi":"viên nhỏ, viên nén","defEn":"a small, rounded, compressed mass of a substance","examples":["Farmers feed their livestock with nutritious food [pellet] every morning. (=Dịch: Nông dân cho gia súc ăn những viên thức ăn bổ dưỡng vào mỗi buổi sáng.)","Wood [pellet] fuel is becoming a popular alternative for home heating. (=Dịch: Nhiên liệu viên nén gỗ đang trở thành một giải pháp thay thế phổ biến cho việc sưởi ấm gia đình.)","The plastic [pellet] must be melted down before being molded into new products. (=Dịch: Hạt nhựa cần được nấu chảy trước khi đúc thành các sản phẩm mới.)"],"ukAudio":"/ai_services/tts3/?q=pellet&lang=en-GB&ipa=%2F%CB%88pel.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pellet&lang=en-US&ipa=%2F%CB%88pel.%C9%AAt%2F"},{"id":"lv_5_263","topic":"Nature and Environmental Protection","word":"percentage","pos":"(n)","ipa":"/pər.ˈsɛn.t̬ɪdʒ/","defVi":"tỷ lệ phần trăm","defEn":"an amount expressed as a fraction of 100, or a proportion of a whole","examples":["A high [percentage] of students passed the final examination with excellent grades. (=Dịch: Một tỷ lệ phần trăm cao các sinh viên đã vượt qua kỳ thi cuối khóa với điểm số xuất sắc.)","The [percentage] of renewable energy used in the country has increased dramatically. (=Dịch: Tỷ lệ phần trăm năng lượng tái tạo được sử dụng ở quốc gia này đã tăng lên đáng kể.)","Only a small [percentage] of the surveyed customers reported issues with the product. (=Dịch: Chỉ một tỷ lệ phần trăm nhỏ khách hàng được khảo sát phản ánh về vấn đề của sản phẩm.)"],"ukAudio":"/ai_services/tts3/?q=percentage&lang=en-GB&ipa=%2Fp%C9%99r.%CB%88s%C9%9Bn.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=percentage&lang=en-US&ipa=%2Fp%C9%99r.%CB%88s%C9%9Bn.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_5_264","topic":"Nature and Environmental Protection","word":"perch","pos":"(n)","ipa":"/pɜrtʃ/","defVi":"chỗ đậu (của chim), cá peca (cá vược nước ngọt)","defEn":"a high place or branch where a bird rests, or a type of freshwater fish","examples":["The eagle scanned the valley from its high [perch] on the cliff edge. (=Dịch: Con đại bàng quan sát thung lũng từ chỗ đậu cao trên mép vách đá.)","He spent the quiet afternoon by the lake fishing for [perch] and trout. (=Dịch: Anh ấy đã dành cả buổi chiều yên ả bên hồ để câu cá peca và cá hồi.)","A small songbird flew down from its [perch] to catch a flying insect. (=Dịch: Một con chim hót nhỏ sà xuống từ cành đậu để bắt một con côn trùng đang bay.)"],"ukAudio":"/ai_services/tts3/?q=perch&lang=en-GB&ipa=%2Fp%C9%9Crt%CA%83%2F","usAudio":"/ai_services/tts3/?q=perch&lang=en-US&ipa=%2Fp%C9%9Crt%CA%83%2F"},{"id":"lv_5_265","topic":"Nature and Environmental Protection","word":"pigeon","pos":"(n)","ipa":"/ˈpɪ.dʒən/","defVi":"chim bồ câu","defEn":"a grey bird that is common in cities and often feeds in public squares","examples":["A wild [pigeon] landed on the windowsill this morning. (=Dịch: Một con chim bồ câu hoang dã đã đậu trên bậu cửa sổ sáng nay.)","Feeding a city [pigeon] in the square is prohibited by local laws. (=Dịch: Việc cho chim bồ câu thành phố ăn ở quảng trường bị luật pháp địa phương nghiêm cấm.)","She took a photograph of a white [pigeon] resting in the park. (=Dịch: Cô ấy đã chụp ảnh một con chim bồ câu trắng đang nghỉ ngơi trong công viên.)"],"ukAudio":"/ai_services/tts3/?q=pigeon&lang=en-GB&ipa=%2F%CB%88p%C9%AA.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=pigeon&lang=en-US&ipa=%2F%CB%88p%C9%AA.d%CA%92%C9%99n%2F"},{"id":"lv_5_266","topic":"Nature and Environmental Protection","word":"pipe","pos":"(n)","ipa":"/paɪp/","defVi":"Ống dẫn (nước, khí...), đường ống.","defEn":"A tube through which liquids or gases can flow.","examples":["Water leaked from a broken [pipe] in the basement. (=Dịch: Nước rò rỉ từ một đường ống vỡ trong tầng hầm.)","Workers are installing a new gas [pipe] along the street. (=Dịch: Công nhân đang lắp đặt một đường ống dẫn khí mới dọc theo con phố.)","Cold weather caused the water [pipe] to freeze and burst. (=Dịch: Thời tiết lạnh giá làm đường ống nước bị đóng băng và vỡ tung.)"],"ukAudio":"/ai_services/tts3/?q=pipe&lang=en-GB&ipa=%2Fpa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=pipe&lang=en-US&ipa=%2Fpa%C9%AAp%2F"},{"id":"lv_5_267","topic":"Nature and Environmental Protection","word":"poacher","pos":"(n)","ipa":"/ˈpoʊ.tʃər/","defVi":"kẻ săn trộm động vật hoang dã","defEn":"a person who illegally catches or kills wild animals, birds, or fish","examples":["Park rangers managed to catch the dangerous [poacher] at midnight. (=Dịch: Các nhân viên kiểm lâm đã bắt được kẻ săn trộm nguy hiểm vào lúc nửa đêm.)","A heavily armed [poacher] was spotted near the nature reserve. (=Dịch: Một kẻ săn trộm vũ trang hạng nặng đã bị phát hiện gần khu bảo tồn thiên nhiên.)","Strict penalties are enforced to deter every [poacher] in the national park. (=Dịch: Các hình phạt nghiêm khắc được thực thi nhằm ngăn chặn mọi kẻ săn trộm trong công viên quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=poacher&lang=en-GB&ipa=%2F%CB%88po%CA%8A.t%CA%83%C9%99r%2F","usAudio":"/ai_services/tts3/?q=poacher&lang=en-US&ipa=%2F%CB%88po%CA%8A.t%CA%83%C9%99r%2F"},{"id":"lv_5_268","topic":"Nature and Environmental Protection","word":"poison","pos":"(n)","ipa":"/ˈpɔɪ.zən/","defVi":"chất độc, thuốc độc","defEn":"a substance that can cause illness or death if swallowed or absorbed","examples":["The dart frog produces a deadly [poison] on the surface of its skin. (=Dịch: Loài ếch phi tiêu tiết ra một chất độc chết người trên bề mặt da của nó.)","Always keep household chemicals and rat [poison] out of reach of children. (=Dịch: Luôn để hóa chất gia dụng và thuốc chuột xa tầm tay trẻ em.)","Rumors and jealousy acted like slow [poison] on their friendship. (=Dịch: Những lời đồn đại và sự đố kỵ đã tác động như chất độc ngấm dần vào tình bạn của họ.)"],"ukAudio":"/ai_services/tts3/?q=poison&lang=en-GB&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99n%2F","usAudio":"/ai_services/tts3/?q=poison&lang=en-US&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99n%2F"},{"id":"lv_5_269","topic":"Nature and Environmental Protection","word":"poisonous","pos":"(adj)","ipa":"/ˈpɔɪ.zə.nəs/","defVi":"có độc, độc hại","defEn":"capable of causing death or illness if taken into the body","examples":["Never eat wild mushrooms because some kinds are extremely [poisonous]. (=Dịch: Đừng bao giờ ăn nấm dại vì một số loại cực kỳ độc.)","The hikers were warned about a [poisonous] snake living in the grass. (=Dịch: Những người đi bộ đường dài đã được cảnh báo về một loài rắn độc sống trong bụi cỏ.)","The factory accidentally released [poisonous] gas into the local atmosphere. (=Dịch: Nhà máy đã vô tình thải khí độc vào bầu không khí địa phương.)"],"ukAudio":"/ai_services/tts3/?q=poisonous&lang=en-GB&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=poisonous&lang=en-US&ipa=%2F%CB%88p%C9%94%C9%AA.z%C9%99.n%C9%99s%2F"},{"id":"lv_5_270","topic":"Nature and Environmental Protection","word":"polar","pos":"(adj)","ipa":"/ˈpoʊ.lər/","defVi":"(thuộc) vùng cực, địa cực","defEn":"relating to the North or South Pole and the cold regions around them","examples":["Rising temperatures threaten the natural habitat of the [polar] bear. (=Dịch: Nhiệt độ tăng đe dọa môi trường sống tự nhiên của loài gấu bắc cực.)","Explorers faced harsh blizzards during their dangerous [polar] expedition. (=Dịch: Các nhà thám hiểm đã đối mặt với những trận bão tuyết khắc nghiệt trong chuyến thám hiểm vùng cực đầy nguy hiểm.)","Melting ice caps are a major concern in the fragile [polar] ecosystem. (=Dịch: Băng tan ở các chỏm băng là mối lo ngại lớn đối với hệ sinh thái vùng cực mỏng manh.)"],"ukAudio":"/ai_services/tts3/?q=polar&lang=en-GB&ipa=%2F%CB%88po%CA%8A.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=polar&lang=en-US&ipa=%2F%CB%88po%CA%8A.l%C9%99r%2F"},{"id":"lv_5_271","topic":"Nature and Environmental Protection","word":"pole","pos":"(n)","ipa":"/poʊl/","defVi":"cực (Bắc cực hoặc Nam cực của Trái Đất)","defEn":"either of the two points at the northern and southern ends of the Earth's axis of rotation","examples":["Explorers faced extreme dangers while racing to reach the South [pole]. (=Dịch: Các nhà thám hiểm đã phải đối mặt với những hiểm nguy tột cùng khi chạy đua để tới được Nam Cực.)","The magnetic [pole] of the Earth slowly shifts position over long periods of time. (=Dịch: Cực từ của Trái Đất từ từ dịch chuyển vị trí qua những khoảng thời gian dài.)","Temperatures near either [pole] rarely rise above freezing even during the summer. (=Dịch: Nhiệt độ gần hai cực hiếm khi tăng lên trên mức đóng băng ngay cả vào mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=pole&lang=en-GB&ipa=%2Fpo%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=pole&lang=en-US&ipa=%2Fpo%CA%8Al%2F"},{"id":"lv_5_272","topic":"Nature and Environmental Protection","word":"portuguese","pos":"(adj)","ipa":"/ˌpɔːr.tʃəˈɡiz/","defVi":"(thuộc) Bồ Đào Nha, người Bồ Đào Nha hoặc tiếng Bồ Đào Nha","defEn":"relating to Portugal, its people, or its language","examples":["We enjoyed traditional [portuguese] custard tarts at the bakery. (=Dịch: Chúng tôi đã thưởng thức món bánh trứng nướng truyền thống của Bồ Đào Nha tại tiệm bánh.)","He is studying the [portuguese] language before moving to Lisbon. (=Dịch: Anh ấy đang học tiếng Bồ Đào Nha trước khi chuyển đến Lisbon.)","Many historic buildings in the city reflect ancient [portuguese] architecture. (=Dịch: Nhiều tòa nhà lịch sử trong thành phố phản ánh kiến trúc Bồ Đào Nha cổ kính.)"],"ukAudio":"/ai_services/tts3/?q=portuguese&lang=en-GB&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1iz%2F","usAudio":"/ai_services/tts3/?q=portuguese&lang=en-US&ipa=%2F%CB%8Cp%C9%94%CB%90r.t%CA%83%C9%99%CB%88%C9%A1iz%2F"},{"id":"lv_5_273","topic":"Nature and Environmental Protection","word":"precise","pos":"(adj)","ipa":"/prɪˈsaɪs/","defVi":"chính xác, rõ ràng","defEn":"exact, accurate, and careful about details","examples":["The scientist recorded the [precise] measurements of the chemical reaction. (=Dịch: Nhà khoa học đã ghi lại các phép đo chính xác của phản ứng hóa học.)","Can you tell me the [precise] location of the hotel? (=Dịch: Bạn có thể cho tôi biết vị trí chính xác của khách sạn không?)","He gave [precise] directions on how to reach the remote village. (=Dịch: Anh ấy đã chỉ đường một cách chính xác để đến ngôi làng hẻo lánh.)"],"ukAudio":"/ai_services/tts3/?q=precise&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=precise&lang=en-US&ipa=%2Fpr%C9%AA%CB%88sa%C9%AAs%2F"},{"id":"lv_5_274","topic":"Nature and Environmental Protection","word":"predator","pos":"(n)","ipa":"/ˈpred.ə.t̬ɚ/","defVi":"động vật ăn thịt, loài săn mồi","defEn":"an animal that hunts, kills, and eats other animals for food","examples":["The lion is an apex [predator] with no natural enemies in its ecosystem. (=Dịch: Sư tử là một loài săn mồi đầu bảng không có kẻ thù tự nhiên trong hệ sinh thái của nó.)","Hawks use their sharp vision to spot small rodents from high above, acting as an effective [predator]. (=Dịch: Chim ưng sử dụng thị lực sắc bén để phát hiện các loài gặm nhấm nhỏ từ trên cao, đóng vai trò như một kẻ săn mồi hiệu quả.)","Removing a top [predator] from an environment can cause prey populations to explode. (=Dịch: Việc loại bỏ một loài săn mồi đỉnh cao khỏi môi trường có thể khiến số lượng con mồi bùng nổ.)"],"ukAudio":"/ai_services/tts3/?q=predator&lang=en-GB&ipa=%2F%CB%88pred.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=predator&lang=en-US&ipa=%2F%CB%88pred.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_5_275","topic":"Nature and Environmental Protection","word":"prehistoric","pos":"(adj)","ipa":"/ˌpri.hɪˈstɔr.ɪk/","defVi":"thuộc về thời tiền sử","defEn":"belonging to the period before written records existed","examples":["Archaeologists discovered several [prehistoric] tools inside the ancient cave. (=Dịch: Các nhà khảo cổ học đã phát hiện một số công cụ thời tiền sử bên trong hang động cổ xưa.)","Many [prehistoric] creatures became extinct long before humans appeared. (=Dịch: Nhiều sinh vật thời tiền sử đã tuyệt chủng từ rất lâu trước khi loài người xuất hiện.)","The museum exhibits remarkable paintings made by [prehistoric] humans. (=Dịch: Bảo tàng trưng bày những bức tranh đáng kinh ngạc do con người thời tiền sử vẽ.)"],"ukAudio":"/ai_services/tts3/?q=prehistoric&lang=en-GB&ipa=%2F%CB%8Cpri.h%C9%AA%CB%88st%C9%94r.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=prehistoric&lang=en-US&ipa=%2F%CB%8Cpri.h%C9%AA%CB%88st%C9%94r.%C9%AAk%2F"},{"id":"lv_5_276","topic":"Nature and Environmental Protection","word":"preserve","pos":"(v)","ipa":"/prɪ.ˈzɝːv/","defVi":"bảo tồn, giữ gìn","defEn":"to keep something in its original state or in good condition","examples":["Efforts are being made to [preserve] ancient monuments for future generations. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm bảo tồn các di tích cổ cho các thế hệ tương lai.)","We must protect rainforests to [preserve] biological diversity. (=Dịch: Chúng ta phải bảo vệ rừng nhiệt đới để bảo tồn sự đa dạng sinh học.)","Adding salt is a traditional method used to [preserve] meat and fish. (=Dịch: Thêm muối là một phương pháp truyền thống được sử dụng để bảo quản thịt và cá.)"],"ukAudio":"/ai_services/tts3/?q=preserve&lang=en-GB&ipa=%2Fpr%C9%AA.%CB%88z%C9%9D%CB%90v%2F","usAudio":"/ai_services/tts3/?q=preserve&lang=en-US&ipa=%2Fpr%C9%AA.%CB%88z%C9%9D%CB%90v%2F"},{"id":"lv_5_277","topic":"Nature and Environmental Protection","word":"prey","pos":"(n)","ipa":"/preɪ/","defVi":"con mồi","defEn":"an animal that is hunted and killed by another animal for food","examples":["The zebra used camouflage and speed to escape from the lion, avoiding becoming easy [prey]. (=Dịch: Ngựa vằn đã sử dụng khả năng ngụy trang và tốc độ để thoát khỏi sư tử, tránh trở thành con mồi dễ dãi.)","Owls hunt small mammals such as mice and voles as their primary [prey]. (=Dịch: Cú săn các loài thú nhỏ như chuột nhắt và chuột đồng làm con mồi chính của chúng.)","In cold winters, food shortages make it harder for carnivores to find sufficient [prey]. (=Dịch: Vào những mùa đông lạnh giá, tình trạng khan hiếm thức ăn khiến các loài ăn thịt khó tìm đủ con mồi hơn.)"],"ukAudio":"/ai_services/tts3/?q=prey&lang=en-GB&ipa=%2Fpre%C9%AA%2F","usAudio":"/ai_services/tts3/?q=prey&lang=en-US&ipa=%2Fpre%C9%AA%2F"},{"id":"lv_5_278","topic":"Nature and Environmental Protection","word":"profound","pos":"(adj)","ipa":"/prəˈfaʊnd/","defVi":"sâu sắc, uyên thâm, sâu rộng","defEn":"having deep insight, or having an extremely great and lasting effect","examples":["The invention of the internet has had a [profound] impact on modern communication. (=Dịch: Phát minh về mạng internet đã có một tác động sâu sắc đến giao tiếp hiện đại.)","The philosopher offered a [profound] insight into the nature of human happiness. (=Dịch: Nhà triết học đã đưa ra một góc nhìn sâu sắc về bản chất của hạnh phúc con người.)","Her mother's passing caused her a sense of [profound] sadness that lasted for months. (=Dịch: Sự ra đi của mẹ cô đã mang lại cho cô một nỗi buồn sâu sắc kéo dài suốt nhiều tháng.)"],"ukAudio":"/ai_services/tts3/?q=profound&lang=en-GB&ipa=%2Fpr%C9%99%CB%88fa%CA%8And%2F","usAudio":"/ai_services/tts3/?q=profound&lang=en-US&ipa=%2Fpr%C9%99%CB%88fa%CA%8And%2F"},{"id":"lv_5_279","topic":"Nature and Environmental Protection","word":"province","pos":"(n)","ipa":"/ˈprɑ.vəns/","defVi":"tỉnh, đơn vị hành chính cấp tỉnh","defEn":"a principal administrative division of a country or territory","examples":["He grew up in a rural [province] in the northern part of the country. (=Dịch: Anh ấy lớn lên ở một tỉnh nông thôn phía bắc đất nước.)","The government allocated extra funding to build schools in that [province]. (=Dịch: Chính phủ đã phân bổ thêm kinh phí để xây dựng trường học tại tỉnh đó.)","Tourism has become the main source of income for this coastal [province]. (=Dịch: Du lịch đã trở thành nguồn thu nhập chính cho tỉnh ven biển này.)"],"ukAudio":"/ai_services/tts3/?q=province&lang=en-GB&ipa=%2F%CB%88pr%C9%91.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=province&lang=en-US&ipa=%2F%CB%88pr%C9%91.v%C9%99ns%2F"},{"id":"lv_5_280","topic":"Nature and Environmental Protection","word":"pulp","pos":"(n)","ipa":"/pʌlp/","defVi":"bột giấy; thịt quả/phần thịt mềm","defEn":"a soft, wet mass of crushed material, especially wood used to make paper or the soft part of fruit","examples":["Wood [pulp] is the primary raw material used in paper manufacturing. (=Dịch: Bột gỗ là nguyên liệu thô chủ yếu được dùng trong sản xuất giấy.)","She prefers orange juice without any [pulp]. (=Dịch: Cô ấy thích nước cam không có tép/thịt quả.)","Recycled paper is soaked in water to turn it back into [pulp]. (=Dịch: Giấy tái chế được ngâm trong nước để biến trở lại thành bột giấy.)"],"ukAudio":"/ai_services/tts3/?q=pulp&lang=en-GB&ipa=%2Fp%CA%8Clp%2F","usAudio":"/ai_services/tts3/?q=pulp&lang=en-US&ipa=%2Fp%CA%8Clp%2F"},{"id":"lv_5_281","topic":"Nature and Environmental Protection","word":"rainbow","pos":"(n)","ipa":"/ˈreɪn.boʊ/","defVi":"cầu vồng","defEn":"a curved band of different colors that appears in the sky when sun shines through rain","examples":["A stunning [rainbow] appeared in the sky right after the rain stopped. (=Dịch: Một chiếc cầu vồng tuyệt đẹp đã xuất hiện trên bầu trời ngay sau khi tạnh mưa.)","Children love drawing a colorful [rainbow] with crayons. (=Dịch: Trẻ em rất thích vẽ cầu vồng rực rỡ sắc màu bằng bút sáp.)","The waterfall created a misty spray that formed a faint [rainbow]. (=Dịch: Thác nước tạo ra một làn sương mù hình thành nên một chiếc cầu vồng mờ ảo.)"],"ukAudio":"/ai_services/tts3/?q=rainbow&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F","usAudio":"/ai_services/tts3/?q=rainbow&lang=en-US&ipa=%2F%CB%88re%C9%AAn.bo%CA%8A%2F"},{"id":"lv_5_282","topic":"Nature and Environmental Protection","word":"rainforest","pos":"(n)","ipa":"/ˈreɪn.fɔːr.ɪst/","defVi":"rừng mưa nhiệt đới","defEn":"a thick forest in a tropical region with heavy annual rainfall","examples":["The Amazon [rainforest] produces a significant portion of the world's oxygen. (=Dịch: Rừng mưa nhiệt đới Amazon sản xuất một phần đáng kể lượng oxy của thế giới.)","Many rare medicinal plants can only be found in the dense [rainforest]. (=Dịch: Nhiều loại cây dược liệu quý hiếm chỉ có thể được tìm thấy trong rừng mưa nhiệt đới rậm rạp.)","Efforts are being made to protect the tropical [rainforest] from illegal logging. (=Dịch: Nhiều nỗ lực đang được thực hiện nhằm bảo vệ rừng mưa nhiệt đới khỏi nạn khai thác gỗ trái phép.)"],"ukAudio":"/ai_services/tts3/?q=rainforest&lang=en-GB&ipa=%2F%CB%88re%C9%AAn.f%C9%94%CB%90r.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=rainforest&lang=en-US&ipa=%2F%CB%88re%C9%AAn.f%C9%94%CB%90r.%C9%AAst%2F"},{"id":"lv_5_283","topic":"Nature and Environmental Protection","word":"rapid","pos":"(adj)","ipa":"/ˈræp.ɪd/","defVi":"nhanh chóng, mau lẹ","defEn":"happening very quickly or moving at great speed","examples":["The country experienced [rapid] economic growth over the last decade. (=Dịch: Đất nước đã trải qua sự tăng trưởng kinh tế nhanh chóng trong thập kỷ qua.)","Scientists are concerned about the [rapid] melting of polar ice caps. (=Dịch: Các nhà khoa học lo ngại về sự tan chảy nhanh chóng của các chỏm băng ở cực.)","She made a [rapid] recovery after receiving the new medication. (=Dịch: Cô ấy đã hồi phục nhanh chóng sau khi dùng loại thuốc mới.)"],"ukAudio":"/ai_services/tts3/?q=rapid&lang=en-GB&ipa=%2F%CB%88r%C3%A6p.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rapid&lang=en-US&ipa=%2F%CB%88r%C3%A6p.%C9%AAd%2F"},{"id":"lv_5_284","topic":"Nature and Environmental Protection","word":"rat","pos":"(n)","ipa":"/ræt/","defVi":"chuột cống, chuột lớn","defEn":"a rodent that resembles a large mouse with a long tail","examples":["The health inspector warned that the dirty basement might attract a [rat]. (=Dịch: Thanh tra y tế đã cảnh báo rằng tầng hầm bẩn thỉu có thể thu hút chuột.)","Scientists used a laboratory [rat] to conduct research on the new medicine. (=Dịch: Các nhà khoa học đã sử dụng chuột thí nghiệm để tiến hành nghiên cứu về loại thuốc mới.)","The old warehouse was infested with more than one giant [rat]. (=Dịch: Nhà kho cũ bị quấy phá bởi nhiều con chuột cống khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=rat&lang=en-GB&ipa=%2Fr%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=rat&lang=en-US&ipa=%2Fr%C3%A6t%2F"},{"id":"lv_5_285","topic":"Nature and Environmental Protection","word":"rattan","pos":"(n)","ipa":"/ræˈtæn/","defVi":"cây mây, mây tre đan","defEn":"the thin, pliable stems of a palm used to make furniture and baskets","examples":["She bought a set of stylish [rattan] chairs for her garden patio. (=Dịch: Cô ấy đã mua một bộ ghế mây rất phong cách cho hiên vườn của mình.)","Local artisans weave durable baskets out of natural [rattan]. (=Dịch: Các nghệ nhân địa phương đan những chiếc giỏ bền chắc từ sợi mây tự nhiên.)","The eco-friendly cafe is decorated with beautiful handmade [rattan] lamps. (=Dịch: Quán cà phê thân thiện với môi trường được trang trí bằng những chiếc đèn mây thủ công tuyệt đẹp.)"],"ukAudio":"/ai_services/tts3/?q=rattan&lang=en-GB&ipa=%2Fr%C3%A6%CB%88t%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=rattan&lang=en-US&ipa=%2Fr%C3%A6%CB%88t%C3%A6n%2F"},{"id":"lv_5_286","topic":"Nature and Environmental Protection","word":"raw","pos":"(adj)","ipa":"/rɔ/","defVi":"sống (chưa nấu chín), thô (chưa qua chế biến)","defEn":"not cooked or not processed into finished goods","examples":["Eating [raw] seafood can sometimes increase the risk of food poisoning. (=Dịch: Ăn hải sản sống đôi khi có thể làm tăng nguy cơ ngộ độc thực phẩm.)","The factory imports [raw] materials such as timber and cotton from abroad. (=Dịch: Nhà máy nhập khẩu các nguyên liệu thô như gỗ và bông từ nước ngoài.)","The researcher analyzed the [raw] data before compiling the final report. (=Dịch: Nhà nghiên cứu đã phân tích dữ liệu thô trước khi biên soạn báo cáo cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=raw&lang=en-GB&ipa=%2Fr%C9%94%2F","usAudio":"/ai_services/tts3/?q=raw&lang=en-US&ipa=%2Fr%C9%94%2F"},{"id":"lv_5_287","topic":"Nature and Environmental Protection","word":"rear","pos":"(v)","ipa":"/rɪr/","defVi":"nuôi dưỡng, chăm sóc, chăn nuôi","defEn":"to care for young animals or children until they are fully grown","examples":["Many local farmers [rear] sheep and cattle for meat and wool. (=Dịch: Nhiều nông dân địa phương nuôi cừu và gia súc để lấy thịt và len.)","It takes great dedication and patience to [rear] children in a busy modern city. (=Dịch: Cần có sự tận tâm và kiên nhẫn to lớn để nuôi dạy con cái trong một thành phố hiện đại bận rộn.)","Both parent birds work tirelessly together to [rear] their chicks until they can fly. (=Dịch: Cả chim bố và chim mẹ đều làm việc không biết mệt mỏi cùng nhau để nuôi nấng những chú chim non cho đến khi chúng biết bay.)"],"ukAudio":"/ai_services/tts3/?q=rear&lang=en-GB&ipa=%2Fr%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=rear&lang=en-US&ipa=%2Fr%C9%AAr%2F"},{"id":"lv_5_288","topic":"Nature and Environmental Protection","word":"recovery","pos":"(n)","ipa":"/rɪˈkʌv.ər.i/","defVi":"sự hồi phục, sự phục hồi","defEn":"the process of returning to normal health, strength, or economic condition","examples":["Doctors were pleased with his steady [recovery] after surgery. (=Dịch: Các bác sĩ hài lòng với sự hồi phục ổn định của anh ấy sau ca phẫu thuật.)","The government launched new policies to support economic [recovery]. (=Dịch: Chính phủ đã đưa ra các chính sách mới nhằm hỗ trợ phục hồi kinh tế.)","The [recovery] of stolen artwork took several years of investigation. (=Dịch: Việc tìm lại các tác phẩm nghệ thuật bị đánh cắp đã mất nhiều năm điều tra.)"],"ukAudio":"/ai_services/tts3/?q=recovery&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%99r.i%2F","usAudio":"/ai_services/tts3/?q=recovery&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%CA%8Cv.%C9%99r.i%2F"},{"id":"lv_5_289","topic":"Nature and Environmental Protection","word":"recycling","pos":"(n)","ipa":"/ˌriːˈsaɪ.klɪŋ/","defVi":"hoạt động tái chế, việc tái chế","defEn":"the process of collecting and converting waste materials into new reusable objects","examples":["Effective [recycling] programs can significantly reduce the amount of industrial waste. (=Dịch: Các chương trình tái chế hiệu quả có thể làm giảm đáng kể lượng rác thải công nghiệp.)","Many schools encourage students to participate in paper and bottle [recycling]. (=Dịch: Nhiều trường học khuyến khích học sinh tham gia tái chế giấy và chai lọ.)","Advancements in [recycling] technology make it easier to process complex electronic waste. (=Dịch: Những tiến bộ trong công nghệ tái chế giúp việc xử lý rác thải điện tử phức tạp trở nên dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=recycling&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88sa%C9%AA.kl%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=recycling&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88sa%C9%AA.kl%C9%AA%C5%8B%2F"},{"id":"lv_5_290","topic":"Nature and Environmental Protection","word":"redstart","pos":"(n)","ipa":"/ˈred.stɑːrt/","defVi":"chim đuôi đỏ","defEn":"a small songbird with a reddish-brown tail","examples":["Birdwatchers were excited to spot a common [redstart] in the garden. (=Dịch: Những người ngắm chim rất hào hứng khi phát hiện một con chim đuôi đỏ thông thường trong vườn.)","The male [redstart] has distinctive bright plumage compared to the female. (=Dịch: Chim đuôi đỏ đực có bộ lông sặc sỡ đặc trưng so với con cái.)","A [redstart] often twitches its tail while searching for insects. (=Dịch: Một con chim đuôi đỏ thường giật giật chiếc đuôi trong khi tìm kiếm côn trùng.)"],"ukAudio":"/ai_services/tts3/?q=redstart&lang=en-GB&ipa=%2F%CB%88red.st%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=redstart&lang=en-US&ipa=%2F%CB%88red.st%C9%91%CB%90rt%2F"},{"id":"lv_5_291","topic":"Nature and Environmental Protection","word":"reforest","pos":"(v)","ipa":"/riː.ˈfɔːr.ɪst/","defVi":"tái trồng rừng, trồng rừng lại","defEn":"to plant new trees in an area where there used to be a forest","examples":["The charity launched a campaign to [reforest] the barren hillsides. (=Dịch: Tổ chức từ thiện đã phát động một chiến dịch tái trồng rừng trên các sườn đồi cằn cỗi.)","Volunteers gathered on weekends to [reforest] land damaged by wildfires. (=Dịch: Các tình nguyện viên tập trung vào cuối tuần để trồng lại rừng trên vùng đất bị tàn phá bởi cháy rừng.)","The government provides financial incentives for farmers who [reforest] unused land. (=Dịch: Chính phủ cung cấp các ưu đãi tài chính cho những người nông dân tái trồng rừng trên đất không sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=reforest&lang=en-GB&ipa=%2Fri%CB%90.%CB%88f%C9%94%CB%90r.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=reforest&lang=en-US&ipa=%2Fri%CB%90.%CB%88f%C9%94%CB%90r.%C9%AAst%2F"},{"id":"lv_5_292","topic":"Nature and Environmental Protection","word":"reforestation","pos":"(n)","ipa":"/ˌriː.fɔːr.əˈsteɪ.ʃən/","defVi":"hoạt động tái trồng rừng, phủ xanh đất trống","defEn":"the act of planting new trees in an area where a forest used to exist","examples":["Large-scale [reforestation] projects can help slow down the rate of global warming. (=Dịch: Các dự án tái trồng rừng quy mô lớn có thể giúp làm chậm tốc độ nóng lên toàn cầu.)","The local community organized a [reforestation] campaign after the devastating wildfire. (=Dịch: Cộng đồng địa phương đã tổ chức một chiến dịch trồng rừng sau vụ cháy rừng tàn khốc.)","Through [reforestation], many endangered animal species have regained their natural habitats. (=Dịch: Thông qua việc tái trồng rừng, nhiều loài động vật có nguy cơ tuyệt chủng đã lấy lại được môi trường sống tự nhiên.)"],"ukAudio":"/ai_services/tts3/?q=reforestation&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.f%C9%94%CB%90r.%C9%99%CB%88ste%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reforestation&lang=en-US&ipa=%2F%CB%8Cri%CB%90.f%C9%94%CB%90r.%C9%99%CB%88ste%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_293","topic":"Nature and Environmental Protection","word":"regulate","pos":"(v)","ipa":"/ˈreɡ.jə.leɪt/","defVi":"điều hòa, kiểm soát, quy định","defEn":"to control or maintain the rate, speed, or quality of a process; to control by rules","examples":["The thermostat is used to [regulate] the room temperature. (=Dịch: Bộ điều nhiệt được sử dụng để điều hòa nhiệt độ trong phòng.)","Strict laws are needed to [regulate] the financial market. (=Dịch: Cần có các điều luật nghiêm ngặt để kiểm soát thị trường tài chính.)","Hormones help [regulate] appetite and sleep patterns in the human body. (=Dịch: Nội tiết tố giúp điều hòa cảm giác thèm ăn và giấc ngủ trong cơ thể con người.)"],"ukAudio":"/ai_services/tts3/?q=regulate&lang=en-GB&ipa=%2F%CB%88re%C9%A1.j%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=regulate&lang=en-US&ipa=%2F%CB%88re%C9%A1.j%C9%99.le%C9%AAt%2F"},{"id":"lv_5_294","topic":"Nature and Environmental Protection","word":"relevance","pos":"(n)","ipa":"/ˈrel.ə.vəns/","defVi":"sự liên quan, tính thích đáng","defEn":"the degree to which something is related or useful to what is happening or being discussed","examples":["The essay lost marks because some paragraphs lacked [relevance] to the topic. (=Dịch: Bài luận bị mất điểm vì một số đoạn văn thiếu sự liên quan đến chủ đề.)","Her practical experience has direct [relevance] to this new project. (=Dịch: Kinh nghiệm thực tế của cô ấy có liên quan trực tiếp đến dự án mới này.)","Scholars continue to debate the [relevance] of ancient philosophy today. (=Dịch: Các học giả vẫn tiếp tục tranh luận về tính thích đáng của triết học cổ đại ngày nay.)"],"ukAudio":"/ai_services/tts3/?q=relevance&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=relevance&lang=en-US&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F"},{"id":"lv_5_295","topic":"Nature and Environmental Protection","word":"remarkable","pos":"(adj)","ipa":"/rɪ.ˈmɑːr.kə.bəl/","defVi":"Đáng chú ý, xuất sắc, phi thường","defEn":"Unusual or special and therefore surprising and worth mentioning.","examples":["The young pianist showed [remarkable] talent at an early age. (=Dịch: Nghệ sĩ dương cầm trẻ tuổi đã thể hiện tài năng xuất chúng ngay từ khi còn nhỏ.)","The city made a [remarkable] recovery after the natural disaster. (=Dịch: Thành phố đã phục hồi một cách đáng kinh ngạc sau thảm họa thiên nhiên.)","It is [remarkable] how much progress she made in just two months. (=Dịch: Thật đáng kinh ngạc về sự tiến bộ mà cô ấy đạt được chỉ trong hai tháng.)"],"ukAudio":"/ai_services/tts3/?q=remarkable&lang=en-GB&ipa=%2Fr%C9%AA.%CB%88m%C9%91%CB%90r.k%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=remarkable&lang=en-US&ipa=%2Fr%C9%AA.%CB%88m%C9%91%CB%90r.k%C9%99.b%C9%99l%2F"},{"id":"lv_5_296","topic":"Nature and Environmental Protection","word":"renewable","pos":"(adj)","ipa":"/rɪˈnu.ə.bəl/","defVi":"tái tạo được, có thể tái tạo","defEn":"capable of being naturally replaced or replenished and not depleted by use","examples":["The country is investing heavily in [renewable] energy such as wind and solar power. (=Dịch: Quốc gia này đang đầu tư mạnh mẽ vào năng lượng tái tạo như năng lượng gió và mặt trời.)","Switching to [renewable] resources helps reduce our dependence on fossil fuels. (=Dịch: Chuyển sang các nguồn tài nguyên tái tạo giúp giảm sự phụ thuộc của chúng ta vào nhiên liệu hóa thạch.)","Wood is considered a [renewable] material if forests are managed sustainably. (=Dịch: Gỗ được coi là vật liệu có thể tái tạo nếu các khu rừng được quản lý một cách bền vững.)"],"ukAudio":"/ai_services/tts3/?q=renewable&lang=en-GB&ipa=%2Fr%C9%AA%CB%88nu.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=renewable&lang=en-US&ipa=%2Fr%C9%AA%CB%88nu.%C9%99.b%C9%99l%2F"},{"id":"lv_5_297","topic":"Nature and Environmental Protection","word":"reproduction","pos":"(n)","ipa":"/ˌriː.prəˈdʌk.ʃən/","defVi":"sự sinh sản; sự sao chép, bản sao","defEn":"the process by which animals and plants produce offspring, or a copy of something","examples":["Temperature plays an important role in the [reproduction] of many fish species. (=Dịch: Nhiệt độ đóng vai trò quan trọng trong quá trình sinh sản của nhiều loài cá.)","This painting is not the original artwork but a high-quality [reproduction]. (=Dịch: Bức tranh này không phải là bản gốc mà là một bản sao chép chất lượng cao.)","The museum prohibited the [reproduction] of ancient manuscripts without permission. (=Dịch: Bảo tàng cấm việc sao chép các bản thảo cổ mà không có sự cho phép.)"],"ukAudio":"/ai_services/tts3/?q=reproduction&lang=en-GB&ipa=%2F%CB%8Cri%CB%90.pr%C9%99%CB%88d%CA%8Ck.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=reproduction&lang=en-US&ipa=%2F%CB%8Cri%CB%90.pr%C9%99%CB%88d%CA%8Ck.%CA%83%C9%99n%2F"},{"id":"lv_5_298","topic":"Nature and Environmental Protection","word":"reptile","pos":"(n)","ipa":"/ˈrep.taɪl/","defVi":"loài bò sát","defEn":"a cold-blooded animal with scaly skin that lays eggs, such as a snake or lizard","examples":["A snake is a typical [reptile] that relies on the sun to regulate its body temperature. (=Dịch: Rắn là một loài bò sát điển hình phụ thuộc vào ánh nắng mặt trời để điều hòa thân nhiệt.)","The zoo has an impressive indoor exhibit dedicated to [reptile] species from the rainforest. (=Dịch: Sở thú có một khu trưng bày trong nhà rất ấn tượng dành riêng cho các loài bò sát đến từ rừng nhiệt đới.)","Crocodiles are among the oldest surviving [reptile] groups on the planet. (=Dịch: Cá sấu là một trong những nhóm bò sát cổ xưa nhất còn tồn tại trên hành tinh.)"],"ukAudio":"/ai_services/tts3/?q=reptile&lang=en-GB&ipa=%2F%CB%88rep.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=reptile&lang=en-US&ipa=%2F%CB%88rep.ta%C9%AAl%2F"},{"id":"lv_5_299","topic":"Nature and Environmental Protection","word":"reservoir","pos":"(n)","ipa":"/ˈrɛz.ər.vwɑːr/","defVi":"hồ chứa nước","defEn":"a natural or artificial lake used as a source of water supply","examples":["The city's main [reservoir] is running low due to the prolonged drought. (=Dịch: Hồ chứa nước chính của thành phố đang cạn kiệt do hạn hán kéo dài.)","They built a massive [reservoir] to provide drinking water for local communities. (=Dịch: Họ đã xây dựng một hồ chứa nước lớn để cung cấp nước uống cho các cộng đồng địa phương.)","Water is pumped from the [reservoir] directly to the treatment plant. (=Dịch: Nước được bơm từ hồ chứa trực tiếp đến nhà máy xử lý.)"],"ukAudio":"/ai_services/tts3/?q=reservoir&lang=en-GB&ipa=%2F%CB%88r%C9%9Bz.%C9%99r.vw%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=reservoir&lang=en-US&ipa=%2F%CB%88r%C9%9Bz.%C9%99r.vw%C9%91%CB%90r%2F"},{"id":"lv_5_300","topic":"Nature and Environmental Protection","word":"resilience","pos":"(n)","ipa":"/rɪˈzɪl.jəns/","defVi":"khả năng phục hồi, sự kiên cường","defEn":"the capacity to recover quickly from difficulties or adapt to tough conditions","examples":["The local community demonstrated incredible [resilience] following the catastrophic earthquake. (=Dịch: Cộng đồng địa phương đã thể hiện khả năng phục hồi đáng kinh ngạc sau trận động đất thảm khốc.)","Psychologists study how emotional [resilience] helps individuals manage workplace stress effectively. (=Dịch: Các nhà tâm lý học nghiên cứu cách sự kiên cường về mặt cảm xúc giúp các cá nhân kiểm soát căng thẳng tại nơi làm việc một cách hiệu quả.)","Developing economic [resilience] is essential for nations vulnerable to global market fluctuations. (=Dịch: Xây dựng khả năng phục hồi kinh tế là điều cần thiết đối với các quốc gia dễ bị ảnh hưởng bởi những biến động của thị trường toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=resilience&lang=en-GB&ipa=%2Fr%C9%AA%CB%88z%C9%AAl.j%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=resilience&lang=en-US&ipa=%2Fr%C9%AA%CB%88z%C9%AAl.j%C9%99ns%2F"},{"id":"lv_5_301","topic":"Nature and Environmental Protection","word":"respiratory","pos":"(adj)","ipa":"/ˈres.pər.əˌtɔr.i/","defVi":"thuộc về hệ hô hấp, hô hấp","defEn":"relating to the act or process of breathing","examples":["Air pollution can trigger severe [respiratory] problems in young children and the elderly. (=Dịch: Ô nhiễm không khí có thể gây ra các vấn đề hô hấp nghiêm trọng ở trẻ nhỏ và người cao tuổi.)","The lungs are the most vital organs in the human [respiratory] system. (=Dịch: Phổi là cơ quan quan trọng nhất trong hệ hô hấp của con người.)","He wore a protective mask to prevent contracting any infectious [respiratory] illness. (=Dịch: Anh ấy đã đeo khẩu trang bảo hộ để tránh mắc bất kỳ bệnh hô hấp truyền nhiễm nào.)"],"ukAudio":"/ai_services/tts3/?q=respiratory&lang=en-GB&ipa=%2F%CB%88res.p%C9%99r.%C9%99%CB%8Ct%C9%94r.i%2F","usAudio":"/ai_services/tts3/?q=respiratory&lang=en-US&ipa=%2F%CB%88res.p%C9%99r.%C9%99%CB%8Ct%C9%94r.i%2F"},{"id":"lv_5_302","topic":"Nature and Environmental Protection","word":"restoration","pos":"(n)","ipa":"/ˌrɛs.təˈreɪ.ʃən/","defVi":"sự phục hồi, trùng tu","defEn":"the process of returning something to its former owner, place, or condition","examples":["The historic building underwent an extensive [restoration] last year. (=Dịch: Tòa nhà lịch sử đã trải qua một đợt trùng tu quy mô lớn vào năm ngoái.)","Environmentalists are working on the [restoration] of native wetlands. (=Dịch: Các nhà bảo vệ môi trường đang nỗ lực phục hồi các vùng đất ngập nước bản địa.)","The museum celebrated the successful [restoration] of the ancient painting. (=Dịch: Bảo tàng đã ăn mừng sự phục chế thành công của bức tranh cổ.)"],"ukAudio":"/ai_services/tts3/?q=restoration&lang=en-GB&ipa=%2F%CB%8Cr%C9%9Bs.t%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=restoration&lang=en-US&ipa=%2F%CB%8Cr%C9%9Bs.t%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_303","topic":"Nature and Environmental Protection","word":"restore","pos":"(v)","ipa":"/rɪˈstɔr/","defVi":"khôi phục, phục hồi","defEn":"to bring something back to an earlier good condition or position","examples":["The government is trying to [restore] public confidence in the economy. (=Dịch: Chính phủ đang cố gắng khôi phục niềm tin của công chúng vào nền kinh tế.)","Experts worked for months to [restore] the ancient painting. (=Dịch: Các chuyên gia đã làm việc nhiều tháng để phục chế bức tranh cổ.)","A good night's sleep will help [restore] your energy. (=Dịch: Một giấc ngủ ngon sẽ giúp bạn phục hồi năng lượng.)"],"ukAudio":"/ai_services/tts3/?q=restore&lang=en-GB&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F","usAudio":"/ai_services/tts3/?q=restore&lang=en-US&ipa=%2Fr%C9%AA%CB%88st%C9%94r%2F"},{"id":"lv_5_304","topic":"Nature and Environmental Protection","word":"ripe","pos":"(adj)","ipa":"/raɪp/","defVi":"chín (trái cây, hoa màu)","defEn":"(of fruit or crops) fully grown and ready to be eaten or harvested","examples":["These bananas are not [ripe] yet, so they taste quite bitter. (=Dịch: Những quả chuối này vẫn chưa chín nên có vị khá chát.)","The sweet aroma of [ripe] peaches filled the entire kitchen. (=Dịch: Mùi thơm ngọt ngào của những quả đào chín lan tỏa khắp căn bếp.)","Farmers wait until the wheat is [ripe] before starting the harvest. (=Dịch: Người nông dân đợi cho đến khi lúa mì chín trước khi bắt đầu thu hoạch.)"],"ukAudio":"/ai_services/tts3/?q=ripe&lang=en-GB&ipa=%2Fra%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=ripe&lang=en-US&ipa=%2Fra%C9%AAp%2F"},{"id":"lv_5_305","topic":"Nature and Environmental Protection","word":"roam","pos":"(v)","ipa":"/roʊm/","defVi":"đi lang thang, đi rông","defEn":"to move about or travel with no clear purpose or direction","examples":["Wild animals [roam] freely in the national park. (=Dịch: Động vật hoang dã tự do đi lại trong công viên quốc gia.)","We spent the afternoon simply wanting to [roam] the streets of the old town. (=Dịch: Chúng tôi dành cả buổi chiều chỉ để đi lang thang trên các con phố của khu phố cổ.)","His mind began to [roam] during the long and boring lecture. (=Dịch: Tâm trí anh ấy bắt đầu lơ đễnh trong suốt bài giảng dài và nhàm chán.)"],"ukAudio":"/ai_services/tts3/?q=roam&lang=en-GB&ipa=%2Fro%CA%8Am%2F","usAudio":"/ai_services/tts3/?q=roam&lang=en-US&ipa=%2Fro%CA%8Am%2F"},{"id":"lv_5_306","topic":"Nature and Environmental Protection","word":"rocky","pos":"(adj)","ipa":"/ˈrɑː.ki/","defVi":"nhiều đá, gập ghềnh, bấp bênh","defEn":"consisting of or covered with rocks; difficult and full of problems","examples":["They hiked up a steep and [rocky] path to reach the mountain peak. (=Dịch: Họ đi bộ men theo một con đường dốc và nhiều sỏi đá để lên tới đỉnh núi.)","The ship navigated carefully around the [rocky] coastline. (=Dịch: Con tàu cẩn thận điều hướng quanh bờ biển nhiều đá ngầm.)","The peace negotiations got off to a [rocky] start due to disagreements. (=Dịch: Các cuộc đàm phán hòa bình đã có một khởi đầu gập ghềnh do những bất đồng.)"],"ukAudio":"/ai_services/tts3/?q=rocky&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.ki%2F","usAudio":"/ai_services/tts3/?q=rocky&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.ki%2F"},{"id":"lv_5_307","topic":"Nature and Environmental Protection","word":"roll","pos":"(n)","ipa":"/roʊl/","defVi":"cuộn, ổ bánh mì nhỏ","defEn":"a cylinder formed by winding flexible material, or a small portion of baked bread","examples":["She bought a [roll] of wrapping paper to prepare gifts for the holiday. (=Dịch: Cô ấy đã mua một cuộn giấy gói để chuẩn bị quà cho kỳ nghỉ lễ.)","He ordered a warm buttered [roll] to accompany his bowl of soup. (=Dịch: Anh ấy đã gọi một ổ bánh mì nhỏ phết bơ nóng hổi để ăn kèm với bát súp của mình.)","The worker unpacked a heavy [roll] of carpet to install in the living room. (=Dịch: Người thợ mở một cuộn thảm trải sàn nặng để lắp đặt trong phòng khách.)"],"ukAudio":"/ai_services/tts3/?q=roll&lang=en-GB&ipa=%2Fro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=roll&lang=en-US&ipa=%2Fro%CA%8Al%2F"},{"id":"lv_5_308","topic":"Nature and Environmental Protection","word":"roman","pos":"(adj)","ipa":"/ˈroʊ.mən/","defVi":"(thuộc) La Mã cổ đại","defEn":"relating to ancient Rome, its people, or its empire","examples":["The museum displays many ancient [roman] coins found across Europe. (=Dịch: Bảo tàng trưng bày nhiều đồng tiền La Mã cổ đại được tìm thấy khắp châu Âu.)","Tourists love visiting the ruins of the old [roman] amphitheater. (=Dịch: Khách du lịch rất thích tham quan tàn tích của giảng đường La Mã cổ kính.)","Historians study the rise and fall of the [roman] Empire in great detail. (=Dịch: Các nhà sử học nghiên cứu rất chi tiết về sự hưng thịnh và suy tàn của Đế chế La Mã.)"],"ukAudio":"/ai_services/tts3/?q=roman&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=roman&lang=en-US&ipa=%2F%CB%88ro%CA%8A.m%C9%99n%2F"},{"id":"lv_5_309","topic":"Nature and Environmental Protection","word":"rood","pos":"(n)","ipa":"/rud/","defVi":"Cây thánh giá lớn; đơn vị đo diện tích đất cũ (khoảng 1/4 mẫu Anh).","defEn":"A crucifix, especially a large one placed above the entrance to the chancel of a medieval church; also an old unit of land area.","examples":["An ancient stone [rood] stood prominently inside the old cathedral. (=Dịch: Một cây thánh giá bằng đá cổ đứng sừng sững bên trong nhà thờ lớn cũ.)","The historic church retains a beautifully carved wooden [rood]. (=Dịch: Ngôi nhà thờ lịch sử vẫn giữ lại một cây thánh giá bằng gỗ được chạm khắc tinh xảo.)","The farmer sold half a [rood] of his family property to pay debts. (=Dịch: Người nông dân đã bán nửa rood đất của gia đình để trả nợ.)"],"ukAudio":"/ai_services/tts3/?q=rood&lang=en-GB&ipa=%2Frud%2F","usAudio":"/ai_services/tts3/?q=rood&lang=en-US&ipa=%2Frud%2F"},{"id":"lv_5_310","topic":"Nature and Environmental Protection","word":"rough","pos":"(adj)","ipa":"/rʌf/","defVi":"gồ ghề, ráp, thô ráp, sơ bộ","defEn":"not smooth, level, or polished; not exact or detailed","examples":["His hands were [rough] and calloused from years of manual labor. (=Dịch: Đôi bàn tay anh ấy thô ráp và chai sạn vì nhiều năm lao động chân tay.)","She quickly sketched a [rough] draft of the proposed architecture. (=Dịch: Cô ấy nhanh chóng phác thảo một bản vẽ sơ bộ về công trình được đề xuất.)","The small fishing boat struggled in the [rough] open seas. (=Dịch: Chiếc thuyền đánh cá nhỏ phải vật lộn giữa vùng biển động sóng lớn.)"],"ukAudio":"/ai_services/tts3/?q=rough&lang=en-GB&ipa=%2Fr%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=rough&lang=en-US&ipa=%2Fr%CA%8Cf%2F"},{"id":"lv_5_311","topic":"Nature and Environmental Protection","word":"rounded","pos":"(adj)","ipa":"/ˈraʊn.dɪd/","defVi":"tròn trịa, toàn diện","defEn":"curving and smooth; well-balanced and complete","examples":["The river stones had smooth, [rounded] edges shaped by rushing water. (=Dịch: Những viên đá dưới sông có các cạnh nhẵn bóng, tròn trịa do dòng nước chảy siết tạo nên.)","A well-[rounded] education includes both academic study and practical skills. (=Dịch: Một nền giáo dục toàn diện bao gồm cả việc học lý thuyết lẫn các kỹ năng thực tế.)","The modern building features elegant, [rounded] corners on every floor. (=Dịch: Tòa nhà hiện đại có các góc bo tròn thanh lịch ở mọi tầng.)"],"ukAudio":"/ai_services/tts3/?q=rounded&lang=en-GB&ipa=%2F%CB%88ra%CA%8An.d%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rounded&lang=en-US&ipa=%2F%CB%88ra%CA%8An.d%C9%AAd%2F"},{"id":"lv_5_312","topic":"Nature and Environmental Protection","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ər/","defVi":"cao su","defEn":"a tough, elastic substance made from the juice of certain tropical trees or synthetically","examples":["Car tires are primarily manufactured from natural and synthetic [rubber]. (=Dịch: Lốp xe ô tô chủ yếu được sản xuất từ cao su tự nhiên và cao su tổng hợp.)","The boots are made of waterproof [rubber] to keep your feet dry in the rain. (=Dịch: Đôi ủng được làm từ cao su chống thấm nước để giữ cho chân bạn luôn khô ráo trong mưa.)","The soles of these sports shoes provide good traction on slippery [rubber] mats. (=Dịch: Đế của những đôi giày thể thao này tạo độ bám tốt trên các tấm thảm cao su trơn trượt.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%99r%2F"},{"id":"lv_5_313","topic":"Nature and Environmental Protection","word":"ruler","pos":"(n)","ipa":"/ˈruː.lɚ/","defVi":"Người cai trị; cây thước kẻ.","defEn":"A person who governs a country; or a straight strip used to measure distance or draw straight lines.","examples":["The ancient kingdom flourished under the guidance of a wise [ruler]. (=Dịch: Vương quốc cổ đại đã hưng thịnh dưới sự dẫn dắt của một vị quân vương sáng suốt.)","Please use a [ruler] and a sharp pencil to draw straight lines. (=Dịch: Làm ơn hãy dùng một chiếc thước kẻ và một cây bút chì sắc để kẻ các đường thẳng.)","Historians describe him as a cruel [ruler] who showed no mercy to his subjects. (=Dịch: Các nhà sử học miêu tả ông ta là một kẻ cai trị tàn bạo, không hề thương xót thần dân của mình.)"],"ukAudio":"/ai_services/tts3/?q=ruler&lang=en-GB&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ruler&lang=en-US&ipa=%2F%CB%88ru%CB%90.l%C9%9A%2F"},{"id":"lv_5_314","topic":"Nature and Environmental Protection","word":"sailors","pos":"(n)","ipa":"/ˈseɪ.lɚz/","defVi":"các thủy thủ, người đi biển","defEn":"people who work as members of the crew of a ship or boat","examples":["The brave [sailors] guided the ship safely through the violent storm. (=Dịch: Những thủy thủ dũng cảm đã điều khiển con tàu vượt qua cơn bão dữ dội một cách an toàn.)","In the past, [sailors] used the positions of the stars to navigate at night. (=Dịch: Trong quá khứ, các thủy thủ đã sử dụng vị trí của các vì sao để định hướng vào ban đêm.)","Many young [sailors] spend months away from their families while at sea. (=Dịch: Nhiều thủy thủ trẻ phải xa gia đình nhiều tháng liền khi đi biển.)"],"ukAudio":"/ai_services/tts3/?q=sailors&lang=en-GB&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=sailors&lang=en-US&ipa=%2F%CB%88se%C9%AA.l%C9%9Az%2F"},{"id":"lv_5_315","topic":"Nature and Environmental Protection","word":"salmon","pos":"(n)","ipa":"/ˈsæm.ən/","defVi":"cá hồi","defEn":"a large fish with pinkish flesh that lives in the ocean but swims up rivers to reproduce","examples":["Grilled [salmon] served with vegetables is a very nutritious meal. (=Dịch: Cá hồi nướng ăn kèm với rau củ là một bữa ăn rất bổ dưỡng.)","During the breeding season, wild [salmon] swim upstream against strong currents. (=Dịch: Vào mùa sinh sản, cá hồi hoang dã bơi ngược dòng nước chảy xiết.)","Bears rely heavily on [salmon] as their primary food source in autumn. (=Dịch: Gấu phụ thuộc rất nhiều vào cá hồi như một nguồn thức ăn chính vào mùa thu.)"],"ukAudio":"/ai_services/tts3/?q=salmon&lang=en-GB&ipa=%2F%CB%88s%C3%A6m.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=salmon&lang=en-US&ipa=%2F%CB%88s%C3%A6m.%C9%99n%2F"},{"id":"lv_5_316","topic":"Nature and Environmental Protection","word":"sanctuary","pos":"(n)","ipa":"/ˈsæŋk.tʃuˌɛr.i/","defVi":"khu bảo tồn thiên nhiên; nơi trú ẩn an toàn","defEn":"a protected area where animals or birds can live safely","examples":["The island was declared a wildlife [sanctuary] to protect endangered sea turtles. (=Dịch: Hòn đảo đã được công nhận là một khu bảo tồn động vật hoang dã để bảo vệ loài rùa biển có nguy cơ tuyệt chủng.)","Injured birds are nursed back to health at this local [sanctuary]. (=Dịch: Những con chim bị thương được chăm sóc hồi phục sức khỏe tại khu bảo tồn địa phương này.)","The library provided a quiet [sanctuary] away from the noisy city streets. (=Dịch: Thư viện mang lại một nơi trú ẩn yên tĩnh tách biệt khỏi những con phố ồn ào của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=sanctuary&lang=en-GB&ipa=%2F%CB%88s%C3%A6%C5%8Bk.t%CA%83u%CB%8C%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=sanctuary&lang=en-US&ipa=%2F%CB%88s%C3%A6%C5%8Bk.t%CA%83u%CB%8C%C9%9Br.i%2F"},{"id":"lv_5_317","topic":"Nature and Environmental Protection","word":"sand","pos":"(n)","ipa":"/sænd/","defVi":"cát","defEn":"a substance consisting of very small grains of rock found on beaches and in deserts","examples":["The children enjoyed building tall castles in the soft [sand]. (=Dịch: Bọn trẻ rất thích xây những tòa lâu đài cao trên bãi cát mềm.)","Strong winds blew fine desert [sand] directly across the highway. (=Dịch: Gió mạnh đã thổi cát mịn từ sa mạc bay ngang qua đường cao tốc.)","Walking barefoot on the warm [sand] helps you relax your mind. (=Dịch: Đi chân trần trên cát ấm giúp bạn thư giãn tâm trí.)"],"ukAudio":"/ai_services/tts3/?q=sand&lang=en-GB&ipa=%2Fs%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=sand&lang=en-US&ipa=%2Fs%C3%A6nd%2F"},{"id":"lv_5_318","topic":"Nature and Environmental Protection","word":"scan","pos":"(v)","ipa":"/skæn/","defVi":"đọc lướt tìm thông tin, quét (bằng máy móc)","defEn":"to look through text quickly to find specific information, or to examine something with a machine","examples":["You should [scan] the text to find the answers to the questions. (=Dịch: Bạn nên đọc lướt văn bản để tìm câu trả lời cho các câu hỏi.)","The doctor used an ultrasound machine to [scan] the patient's abdomen. (=Dịch: Bác sĩ đã dùng máy siêu âm để quét vùng bụng của bệnh nhân.)","Security officers [scan] all luggage before passengers board the plane. (=Dịch: Nhân viên an ninh quét toàn bộ hành lý trước khi hành khách lên máy bay.)"],"ukAudio":"/ai_services/tts3/?q=scan&lang=en-GB&ipa=%2Fsk%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=scan&lang=en-US&ipa=%2Fsk%C3%A6n%2F"},{"id":"lv_5_319","topic":"Nature and Environmental Protection","word":"scientific","pos":"(adj)","ipa":"/ˌsaɪ.ənˈtɪf.ɪk/","defVi":"(thuộc) khoa học, mang tính khoa học","defEn":"relating to science, or using the organized methods and principles of science","examples":["Researchers need solid [scientific] evidence before publishing their results. (=Dịch: Các nhà nghiên cứu cần có bằng chứng khoa học vững chắc trước khi công bố kết quả của họ.)","The discovery of penicillin was a major [scientific] breakthrough in medicine. (=Dịch: Việc phát hiện ra penicillin là một bước đột phá khoa học lớn trong y học.)","We should apply a strict [scientific] approach to solving environmental problems. (=Dịch: Chúng ta nên áp dụng một phương pháp khoa học nghiêm ngặt để giải quyết các vấn đề môi trường.)"],"ukAudio":"/ai_services/tts3/?q=scientific&lang=en-GB&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=scientific&lang=en-US&ipa=%2F%CB%8Csa%C9%AA.%C9%99n%CB%88t%C9%AAf.%C9%AAk%2F"},{"id":"lv_5_320","topic":"Nature and Environmental Protection","word":"seabed","pos":"(n)","ipa":"/ˈsiː.bed/","defVi":"đáy biển","defEn":"the solid ground at the bottom of the ocean or sea","examples":["Divers explored the [seabed] in search of ancient shipwrecks. (=Dịch: Các thợ lặn đã khám phá đáy biển để tìm kiếm những xác tàu đắm cổ xưa.)","The pipeline lies deep beneath the [seabed] to prevent damage. (=Dịch: Đường ống nằm sâu dưới đáy biển để tránh hư hỏng.)","Many unique marine species live on the rocky [seabed]. (=Dịch: Nhiều loài sinh vật biển độc đáo sống trên đáy biển đầy đá.)"],"ukAudio":"/ai_services/tts3/?q=seabed&lang=en-GB&ipa=%2F%CB%88si%CB%90.bed%2F","usAudio":"/ai_services/tts3/?q=seabed&lang=en-US&ipa=%2F%CB%88si%CB%90.bed%2F"},{"id":"lv_5_321","topic":"Nature and Environmental Protection","word":"seafood","pos":"(n)","ipa":"/ˈsiː.fuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, such as fish and shellfish","examples":["The coastal restaurant is famous for serving fresh [seafood]. (=Dịch: Nhà hàng ven biển nổi tiếng với việc phục vụ hải sản tươi sống.)","Overfishing poses a serious threat to global [seafood] supplies. (=Dịch: Đánh bắt quá mức đặt ra mối đe dọa nghiêm trọng đối với nguồn cung hải sản toàn cầu.)","Some people are allergic to different varieties of [seafood]. (=Dịch: Một số người bị dị ứng với các loại hải sản khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90.fu%CB%90d%2F"},{"id":"lv_5_322","topic":"Nature and Environmental Protection","word":"seasonally","pos":"(adv)","ipa":"/ˈsiː.zən.ə.li/","defVi":"theo mùa, theo thời vụ","defEn":"in a way that relates to, depends on, or varies with a particular season","examples":["Prices of fresh fruits fluctuate [seasonally] depending on harvests. (=Dịch: Giá trái cây tươi biến động theo mùa tùy thuộc vào các vụ thu hoạch.)","Many birds migrate [seasonally] to avoid harsh winter climates. (=Dịch: Nhiều loài chim di cư theo mùa để tránh thời tiết mùa đông khắc nghiệt.)","The hotel only hires [seasonally] during the peak summer period. (=Dịch: Khách sạn chỉ tuyển dụng nhân viên thời vụ trong suốt đợt cao điểm mùa hè.)"],"ukAudio":"/ai_services/tts3/?q=seasonally&lang=en-GB&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=seasonally&lang=en-US&ipa=%2F%CB%88si%CB%90.z%C9%99n.%C9%99.li%2F"},{"id":"lv_5_323","topic":"Nature and Environmental Protection","word":"segment","pos":"(n)","ipa":"/ˈsɛɡ.mənt/","defVi":"phân đoạn, mảng, phần","defEn":"one of the distinct parts into which something is divided or can be separated","examples":["The final [segment] of the documentary focuses on wildlife conservation efforts. (=Dịch: Phần cuối của bộ phim tài liệu tập trung vào các nỗ lực bảo tồn động vật hoang dã.)","This technology firm dominates a large [segment] of the domestic smartphone market. (=Dịch: Công ty công nghệ này thống trị một phân khúc lớn của thị trường điện thoại thông minh nội địa.)","She carefully peeled an orange and shared each juicy [segment] with her child. (=Dịch: Cô ấy cẩn thận bóc một quả cam và chia từng múi mọng nước cho con mình.)"],"ukAudio":"/ai_services/tts3/?q=segment&lang=en-GB&ipa=%2F%CB%88s%C9%9B%C9%A1.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=segment&lang=en-US&ipa=%2F%CB%88s%C9%9B%C9%A1.m%C9%99nt%2F"},{"id":"lv_5_324","topic":"Nature and Environmental Protection","word":"sensor","pos":"(n)","ipa":"/ˈsen.sər/","defVi":"cảm biến, thiết bị cảm ứng","defEn":"a device that discovers and reacts to changes in light, heat, or movement","examples":["The automatic doors open when a motion [sensor] detects someone approaching. (=Dịch: Cửa tự động mở ra khi cảm biến chuyển động phát hiện có người đang tiến lại gần.)","The smoke [sensor] triggered the fire alarm in the building. (=Dịch: Cảm biến khói đã kích hoạt chuông báo cháy trong tòa nhà.)","Modern smartphones use a light [sensor] to adjust screen brightness automatically. (=Dịch: Điện thoại thông minh hiện đại sử dụng cảm biến ánh sáng để tự động điều chỉnh độ sáng màn hình.)"],"ukAudio":"/ai_services/tts3/?q=sensor&lang=en-GB&ipa=%2F%CB%88sen.s%C9%99r%2F","usAudio":"/ai_services/tts3/?q=sensor&lang=en-US&ipa=%2F%CB%88sen.s%C9%99r%2F"},{"id":"lv_5_325","topic":"Nature and Environmental Protection","word":"seriously","pos":"(adv)","ipa":"/ˈsɪr.i.əs.li/","defVi":"nghiêm túc, trầm trọng, nghiêm trọng","defEn":"in a severe manner, or in a way that is not joking","examples":["The driver was [seriously] injured in the car accident. (=Dịch: Người tài xế đã bị thương nặng trong vụ tai nạn xe hơi.)","You should take your studies more [seriously] if you want to pass. (=Dịch: Bạn nên nghiêm túc hơn với việc học nếu muốn thi đỗ.)","Are you [seriously] thinking about quitting your job? (=Dịch: Có thật sự là bạn đang nghĩ đến việc nghỉ việc không?)"],"ukAudio":"/ai_services/tts3/?q=seriously&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=seriously&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F"},{"id":"lv_5_326","topic":"Nature and Environmental Protection","word":"settlement","pos":"(n)","ipa":"/ˈset̬.əl.mənt/","defVi":"sự dàn xếp, thỏa thuận; khu định cư","defEn":"an official agreement that finishes an argument, or a place where people live","examples":["The union reached a wage [settlement] with the company management. (=Dịch: Công đoàn đã đạt được thỏa thuận tiền lương với ban quản lý công ty.)","Archaeologists discovered an ancient [settlement] near the riverbank. (=Dịch: Các nhà khảo cổ học đã phát hiện một khu định cư cổ gần bờ sông.)","The dispute was resolved through an out-of-court [settlement]. (=Dịch: Tranh chấp đã được giải quyết thông qua thỏa thuận ngoài tòa án.)"],"ukAudio":"/ai_services/tts3/?q=settlement&lang=en-GB&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=settlement&lang=en-US&ipa=%2F%CB%88set%CC%AC.%C9%99l.m%C9%99nt%2F"},{"id":"lv_5_327","topic":"Nature and Environmental Protection","word":"severe","pos":"(adj)","ipa":"/sɪˈvɪr/","defVi":"nghiêm trọng, khốc liệt, dữ dội","defEn":"causing very great pain, difficulty, or damage; extremely bad or serious","examples":["The region suffered from a [severe] drought that lasted for months. (=Dịch: Khu vực này đã phải hứng chịu một đợt hạn hán nghiêm trọng kéo dài nhiều tháng.)","He was rushed to the hospital with [severe] chest pains. (=Dịch: Anh ấy đã được đưa gấp tới bệnh viện vì những cơn đau ngực dữ dội.)","The storm caused [severe] damage to coastal buildings and infrastructure. (=Dịch: Cơn bão đã gây ra thiệt hại nghiêm trọng cho các công trình và cơ sở hạ tầng ven biển.)"],"ukAudio":"/ai_services/tts3/?q=severe&lang=en-GB&ipa=%2Fs%C9%AA%CB%88v%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=severe&lang=en-US&ipa=%2Fs%C9%AA%CB%88v%C9%AAr%2F"},{"id":"lv_5_328","topic":"Nature and Environmental Protection","word":"shark","pos":"(n)","ipa":"/ʃɑːrk/","defVi":"cá mập","defEn":"a large fish with sharp teeth and a fin on its back that lives in the ocean","examples":["The great white [shark] is one of the most feared predators in the ocean. (=Dịch: Cá mập trắng lớn là một trong những kẻ săn mồi đáng sợ nhất ở đại dương.)","Swimmers were warned to leave the water after a [shark] was spotted near the shore. (=Dịch: Những người đi bơi được cảnh báo rời khỏi mặt nước sau khi một con cá mập bị phát hiện gần bờ.)","Many species of [shark] are currently threatened by overfishing. (=Dịch: Nhiều loài cá mập hiện đang bị đe dọa bởi nạn đánh bắt quá mức.)"],"ukAudio":"/ai_services/tts3/?q=shark&lang=en-GB&ipa=%2F%CA%83%C9%91%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=shark&lang=en-US&ipa=%2F%CA%83%C9%91%CB%90rk%2F"},{"id":"lv_5_329","topic":"Nature and Environmental Protection","word":"shell","pos":"(n)","ipa":"/ʃel/","defVi":"vỏ (ốc, sò, trứng, hạt)","defEn":"the hard outer covering of an animal, an egg, or a nut","examples":["The crab hides inside its hard [shell] to protect itself from predators. (=Dịch: Con cua ẩn nấp bên trong lớp vỏ cứng của mình để tự bảo vệ khỏi những kẻ săn mồi.)","Children love collecting colorful [shell] pieces along the seashore. (=Dịch: Trẻ em rất thích nhặt những mảnh vỏ sò nhiều màu sắc dọc theo bờ biển.)","Be careful not to drop bits of egg [shell] into the mixing bowl. (=Dịch: Hãy cẩn thận đừng để các mảnh vỏ trứng rơi vào tô trộn.)"],"ukAudio":"/ai_services/tts3/?q=shell&lang=en-GB&ipa=%2F%CA%83el%2F","usAudio":"/ai_services/tts3/?q=shell&lang=en-US&ipa=%2F%CA%83el%2F"},{"id":"lv_5_330","topic":"Nature and Environmental Protection","word":"shipping","pos":"(n)","ipa":"/ˈʃɪp.ɪŋ/","defVi":"việc vận chuyển hàng hóa, ngành hàng hải","defEn":"the activity of transporting goods by sea or other transport methods","examples":["The website offers free [shipping] on orders over fifty dollars. (=Dịch: Trang web miễn phí vận chuyển cho các đơn hàng trên năm mươi đô la.)","International [shipping] may take up to three weeks due to customs. (=Dịch: Vận chuyển quốc tế có thể mất tới ba tuần do thủ tục hải quan.)","The country relies heavily on maritime [shipping] for its exports. (=Dịch: Quốc gia này phụ thuộc rất nhiều vào ngành vận tải biển đối với hàng xuất khẩu.)"],"ukAudio":"/ai_services/tts3/?q=shipping&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=shipping&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.%C9%AA%C5%8B%2F"},{"id":"lv_5_331","topic":"Nature and Environmental Protection","word":"shipwreck","pos":"(n)","ipa":"/ˈʃɪp.rek/","defVi":"vụ đắm tàu; xác tàu đắm","defEn":"the destruction of a ship at sea by sinking or breaking up, or the remains of a destroyed ship","examples":["Archaeologists discovered an ancient [shipwreck] off the coast of Greece. (=Dịch: Các nhà khảo cổ học đã phát hiện ra một xác tàu đắm cổ ngoài khơi Hy Lạp.)","Only three sailors survived the tragic [shipwreck]. (=Dịch: Chỉ có ba thủy thủ sống sót sau vụ đắm tàu bi thảm.)","Coral now covers the rusted metal of the old [shipwreck]. (=Dịch: San hô hiện bao phủ phần kim loại rỉ sét của xác tàu đắm cũ.)"],"ukAudio":"/ai_services/tts3/?q=shipwreck&lang=en-GB&ipa=%2F%CB%88%CA%83%C9%AAp.rek%2F","usAudio":"/ai_services/tts3/?q=shipwreck&lang=en-US&ipa=%2F%CB%88%CA%83%C9%AAp.rek%2F"},{"id":"lv_5_332","topic":"Nature and Environmental Protection","word":"shore","pos":"(n)","ipa":"/ʃɔːr/","defVi":"bờ (biển, hồ lớn)","defEn":"the land along the edge of a sea, lake, or wide river","examples":["We walked along the sandy [shore] collecting shells at sunset. (=Dịch: Chúng tôi đi dạo dọc theo bờ biển đầy cát để nhặt vỏ sò lúc hoàng hôn.)","The fishing boat safely returned to the [shore] before the storm hit. (=Dịch: Chiếc thuyền đánh cá đã an toàn trở về bờ trước khi cơn bão ập đến.)","Waves were gently crashing against the rocky [shore]. (=Dịch: Những con sóng vỗ nhẹ vào bờ đá.)"],"ukAudio":"/ai_services/tts3/?q=shore&lang=en-GB&ipa=%2F%CA%83%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=shore&lang=en-US&ipa=%2F%CA%83%C9%94%CB%90r%2F"},{"id":"lv_5_333","topic":"Nature and Environmental Protection","word":"sighting","pos":"(n)","ipa":"/ˈsaɪ.t̬ɪŋ/","defVi":"sự trông thấy, sự phát hiện (vật hiếm hoặc lạ)","defEn":"an occasion on which someone sees something rare, unusual, or elusive","examples":["The rare bird [sighting] attracted hundreds of birdwatchers to the nature reserve. (=Dịch: Sự phát hiện loài chim quý hiếm đã thu hút hàng trăm người ngắm chim đến khu bảo tồn thiên nhiên.)","There has been another [sighting] of a leopard near the rural village. (=Dịch: Lại có thêm một lần người ta nhìn thấy báo đốm xuất hiện gần ngôi làng nông thôn.)","Scientists confirmed the first official [sighting] of the deep-sea squid in these waters. (=Dịch: Các nhà khoa học đã xác nhận lần đầu tiên chính thức nhìn thấy loài mực biển sâu ở vùng biển này.)"],"ukAudio":"/ai_services/tts3/?q=sighting&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sighting&lang=en-US&ipa=%2F%CB%88sa%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_5_334","topic":"Nature and Environmental Protection","word":"silt","pos":"(n)","ipa":"/sɪlt/","defVi":"phù sa, bùn cát mịn","defEn":"fine sand, clay, or other material carried by running water and deposited as a sediment","examples":["The river mouth was blocked by a large accumulation of [silt]. (=Dịch: Cửa sông đã bị tắc nghẽn bởi một lượng lớn phù sa tích tụ.)","Floods leave behind rich [silt] that makes the farmland fertile. (=Dịch: Lũ lụt để lại lớp phù sa màu mỡ giúp đất canh tác tươi tốt.)","The harbor needs regular dredging to clear out the [silt]. (=Dịch: Cảng cần được nạo vét thường xuyên để dọn sạch bùn cát.)"],"ukAudio":"/ai_services/tts3/?q=silt&lang=en-GB&ipa=%2Fs%C9%AAlt%2F","usAudio":"/ai_services/tts3/?q=silt&lang=en-US&ipa=%2Fs%C9%AAlt%2F"},{"id":"lv_5_335","topic":"Nature and Environmental Protection","word":"sixteen","pos":"(n)","ipa":"/ˌsɪks.ˈtin/","defVi":"Số mười sáu","defEn":"The number equivalent to the sum of ten and six; 16.","examples":["A group of [sixteen] students participated in the science competition. (=Dịch: Một nhóm gồm mười sáu học sinh đã tham gia cuộc thi khoa học.)","She will celebrate her [sixteen]th birthday next week. (=Dịch: Cô ấy sẽ tổ chức sinh nhật lần thứ mười sáu vào tuần tới.)","The recipe requires [sixteen] ounces of fresh milk. (=Dịch: Công thức nấu ăn này yêu cầu mười sáu ounce sữa tươi.)"],"ukAudio":"/ai_services/tts3/?q=sixteen&lang=en-GB&ipa=%2F%CB%8Cs%C9%AAks.%CB%88tin%2F","usAudio":"/ai_services/tts3/?q=sixteen&lang=en-US&ipa=%2F%CB%8Cs%C9%AAks.%CB%88tin%2F"},{"id":"lv_5_336","topic":"Nature and Environmental Protection","word":"sleepy","pos":"(adj)","ipa":"/ˈsliː.pi/","defVi":"buồn ngủ, ngái ngủ; (nơi chốn) yên tĩnh, vắng lặng","defEn":"feeling tired and ready to go to sleep; quiet and not active","examples":["I always feel warm and [sleepy] after a large meal. (=Dịch: Tôi luôn cảm thấy ấm áp và buồn ngủ sau một bữa ăn no.)","They decided to spend their holiday in a [sleepy] fishing village. (=Dịch: Họ quyết định dành kỳ nghỉ của mình tại một ngôi làng chài thanh bình, yên ả.)","The baby rubbed her [sleepy] eyes and began to yawn. (=Dịch: Đứa bé dụi đôi mắt ngái ngủ và bắt đầu ngáp.)"],"ukAudio":"/ai_services/tts3/?q=sleepy&lang=en-GB&ipa=%2F%CB%88sli%CB%90.pi%2F","usAudio":"/ai_services/tts3/?q=sleepy&lang=en-US&ipa=%2F%CB%88sli%CB%90.pi%2F"},{"id":"lv_5_337","topic":"Nature and Environmental Protection","word":"slope","pos":"(n)","ipa":"/sloʊp/","defVi":"dốc, sườn dốc","defEn":"a surface that lies at an angle to the horizontal so that some points on it are higher than others","examples":["Skiers enjoyed racing down the snowy [slope]. (=Dịch: Những người trượt tuyết thích thú lao xuống sườn dốc phủ đầy tuyết.)","The house was built on a steep [slope] overlooking the valley. (=Dịch: Ngôi nhà được xây dựng trên một sườn dốc đứng nhìn ra thung lũng.)","Heavy rain caused soil to slide down the mountain [slope]. (=Dịch: Mưa lớn khiến đất sạt lở xuống sườn núi.)"],"ukAudio":"/ai_services/tts3/?q=slope&lang=en-GB&ipa=%2Fslo%CA%8Ap%2F","usAudio":"/ai_services/tts3/?q=slope&lang=en-US&ipa=%2Fslo%CA%8Ap%2F"},{"id":"lv_5_338","topic":"Nature and Environmental Protection","word":"smoothly","pos":"(adv)","ipa":"/ˈsmuːð.li/","defVi":"một cách suôn sẻ, êm ả, trôi chảy","defEn":"without problems, interruptions, or sudden changes","examples":["The transition to the new system went very [smoothly]. (=Dịch: Quá trình chuyển đổi sang hệ thống mới diễn ra rất suôn sẻ.)","The ship sailed [smoothly] across the calm sea. (=Dịch: Con tàu lướt êm ả trên mặt biển tĩnh lặng.)","The meeting ran [smoothly] and finished ahead of schedule. (=Dịch: Cuộc họp diễn ra thuận lợi và kết thúc sớm hơn dự kiến.)"],"ukAudio":"/ai_services/tts3/?q=smoothly&lang=en-GB&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F","usAudio":"/ai_services/tts3/?q=smoothly&lang=en-US&ipa=%2F%CB%88smu%CB%90%C3%B0.li%2F"},{"id":"lv_5_339","topic":"Nature and Environmental Protection","word":"sourced","pos":"(adj)","ipa":"/sɔːrst/","defVi":"có nguồn gốc từ, được lấy từ (nguồn cụ thể)","defEn":"obtained or supplied from a particular place, provider, or method","examples":["The restaurant is proud of using only locally [sourced] ingredients in its dishes. (=Dịch: Nhà hàng tự hào về việc chỉ sử dụng các nguyên liệu có nguồn gốc địa phương trong các món ăn của mình.)","Ethically [sourced] coffee has become increasingly popular among conscious consumers. (=Dịch: Cà phê có nguồn gốc hợp đạo đức ngày càng trở nên phổ biến đối với những người tiêu dùng có ý thức.)","All timber used in the building was sustainably [sourced] from managed forests. (=Dịch: Tất cả gỗ được sử dụng trong tòa nhà đều được lấy từ nguồn rừng được quản lý bền vững.)"],"ukAudio":"/ai_services/tts3/?q=sourced&lang=en-GB&ipa=%2Fs%C9%94%CB%90rst%2F","usAudio":"/ai_services/tts3/?q=sourced&lang=en-US&ipa=%2Fs%C9%94%CB%90rst%2F"},{"id":"lv_5_340","topic":"Nature and Environmental Protection","word":"southern","pos":"(adj)","ipa":"/ˈsʌð.ɚn/","defVi":"(thuộc) phương nam, ở phía nam","defEn":"located in, coming from, or characteristic of the south","examples":["Many birds migrate to the [southern] regions during the winter. (=Dịch: Nhiều loài chim di cư đến các vùng phía nam vào mùa đông.)","We spent two weeks traveling along the [southern] coast of Italy. (=Dịch: Chúng tôi đã dành hai tuần du lịch dọc theo bờ biển phía nam nước Ý.)","She speaks with a distinct [southern] accent. (=Dịch: Cô ấy nói bằng chất giọng miền nam rất đặc trưng.)"],"ukAudio":"/ai_services/tts3/?q=southern&lang=en-GB&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%9An%2F","usAudio":"/ai_services/tts3/?q=southern&lang=en-US&ipa=%2F%CB%88s%CA%8C%C3%B0.%C9%9An%2F"},{"id":"lv_5_341","topic":"Nature and Environmental Protection","word":"spear","pos":"(n)","ipa":"/spɪr/","defVi":"ngọn giáo, cây thương","defEn":"a weapon with a long shaft and a pointed tip, used for thrusting or throwing","examples":["Ancient hunters used a sharpened [spear] to catch large animals. (=Dịch: Những người thợ săn cổ đại đã sử dụng một ngọn giáo sắc nhọn để bắt các loài thú lớn.)","The museum displays an iron [spear] dating back to the Bronze Age. (=Dịch: Bảo tàng trưng bày một ngọn giáo sắt có từ thời kỳ đồ đồng.)","He threw the [spear] with great precision during the athletics competition. (=Dịch: Anh ấy đã ném ngọn giáo với độ chính xác cao trong cuộc thi điền kinh.)"],"ukAudio":"/ai_services/tts3/?q=spear&lang=en-GB&ipa=%2Fsp%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=spear&lang=en-US&ipa=%2Fsp%C9%AAr%2F"},{"id":"lv_5_342","topic":"Nature and Environmental Protection","word":"specimen","pos":"(n)","ipa":"/ˈspes.ə.mən/","defVi":"mẫu vật, mẫu thử","defEn":"a single example of something, especially an animal or plant, collected for scientific study","examples":["The museum displays a well-preserved [specimen] of a prehistoric bird. (=Dịch: Bảo tàng trưng bày một mẫu vật được bảo quản tốt của một loài chim tiền sử.)","The doctor asked the patient to provide a urine [specimen] for analysis. (=Dịch: Bác sĩ đã yêu cầu bệnh nhân cung cấp một mẫu nước tiểu để phân tích.)","Botanists collected a rare flower [specimen] during their rainforest expedition. (=Dịch: Các nhà thực vật học đã thu thập một mẫu hoa hiếm trong chuyến thám hiểm rừng nhiệt đới của họ.)"],"ukAudio":"/ai_services/tts3/?q=specimen&lang=en-GB&ipa=%2F%CB%88spes.%C9%99.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=specimen&lang=en-US&ipa=%2F%CB%88spes.%C9%99.m%C9%99n%2F"},{"id":"lv_5_343","topic":"Nature and Environmental Protection","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị (có nguồn gốc thực vật)","defEn":"a substance made from plants used to flavor food, such as cinnamon or pepper","examples":["Cinnamon is a fragrant [spice] commonly added to warm autumn drinks. (=Dịch: Quế là một loại gia vị thơm thường được thêm vào các loại đồ uống ấm áp mùa thu.)","Indian cuisine is celebrated worldwide for its rich blend of each traditional [spice]. (=Dịch: Ẩm thực Ấn Độ nổi tiếng trên toàn thế giới nhờ sự kết hợp phong phú của từng loại gia vị truyền thống.)","Adding fresh herbs and [spice] can elevate a simple vegetable soup. (=Dịch: Thêm thảo mộc tươi và gia vị có thể nâng tầm một món súp rau củ đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_5_344","topic":"Nature and Environmental Protection","word":"spirit","pos":"(n)","ipa":"/ˈspɪr.ɪt/","defVi":"tinh thần, tâm hồn, linh hồn","defEn":"the attitude, mood, or general character of a person or group; also the non-physical part of a person","examples":["Despite the difficulties, the team showed great fighting [spirit]. (=Dịch: Bất chấp những khó khăn, toàn đội đã thể hiện tinh thần thi đấu tuyệt vời.)","Volunteers worked together in a true [spirit] of cooperation. (=Dịch: Các tình nguyện viên đã cùng nhau làm việc trên tinh thần hợp tác thực sự.)","The festival captured the vibrant cultural [spirit] of the city. (=Dịch: Lễ hội đã thể hiện được nét tinh thần văn hóa sôi động của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=spirit&lang=en-GB&ipa=%2F%CB%88sp%C9%AAr.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=spirit&lang=en-US&ipa=%2F%CB%88sp%C9%AAr.%C9%AAt%2F"},{"id":"lv_5_345","topic":"Nature and Environmental Protection","word":"splash","pos":"(n)","ipa":"/splæʃ/","defVi":"tiếng nước bắn; giọt nước bắn, tia nước","defEn":"the sound made by something hitting liquid, or a small amount of liquid that falls on something","examples":["We heard a loud [splash] as the boy jumped into the swimming pool. (=Dịch: Chúng tôi nghe thấy một tiếng tõm lớn khi cậu bé nhảy xuống hồ bơi.)","A [splash] of mud stained her clean white trousers. (=Dịch: Một vệt bùn bắn đã làm bẩn chiếc quần trắng sạch sẽ của cô ấy.)","He added a [splash] of milk to his morning coffee. (=Dịch: Anh ấy thêm một chút sữa vào tách cà phê buổi sáng của mình.)"],"ukAudio":"/ai_services/tts3/?q=splash&lang=en-GB&ipa=%2Fspl%C3%A6%CA%83%2F","usAudio":"/ai_services/tts3/?q=splash&lang=en-US&ipa=%2Fspl%C3%A6%CA%83%2F"},{"id":"lv_5_346","topic":"Nature and Environmental Protection","word":"split","pos":"(v)","ipa":"/splɪt/","defVi":"chia nhỏ, tách ra, chẻ ra","defEn":"to divide or break into parts, especially along a line","examples":["The teacher decided to [split] the class into small study groups. (=Dịch: Giáo viên quyết định chia lớp thành các nhóm học tập nhỏ.)","The heavy branch began to [split] under the weight of the snow. (=Dịch: Cành cây nặng trĩu bắt đầu nứt toác dưới sức nặng của tuyết.)","We agreed to [split] the restaurant bill equally among all four of us. (=Dịch: Chúng tôi đồng ý chia đều hóa đơn nhà hàng cho cả bốn người.)"],"ukAudio":"/ai_services/tts3/?q=split&lang=en-GB&ipa=%2Fspl%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=split&lang=en-US&ipa=%2Fspl%C9%AAt%2F"},{"id":"lv_5_347","topic":"Nature and Environmental Protection","word":"squirrel","pos":"(n)","ipa":"/ˈskwɜːr.əl/","defVi":"con sóc","defEn":"a small animal with a bushy tail that climbs trees and eats nuts","examples":["A gray [squirrel] buried acorns beneath the oak tree for winter. (=Dịch: Một con sóc xám đã chôn những quả sồi dưới gốc cây sồi để chuẩn bị cho mùa đông.)","We watched a tiny [squirrel] leap effortlessly between the high branches. (=Dịch: Chúng tôi quan sát một chú sóc nhỏ nhảy thoăn thoắt giữa các cành cây cao.)","The curious [squirrel] approached our park bench in search of food. (=Dịch: Chú sóc tò mò tiến lại gần băng ghế công viên của chúng tôi để tìm kiếm thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=squirrel&lang=en-GB&ipa=%2F%CB%88skw%C9%9C%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=squirrel&lang=en-US&ipa=%2F%CB%88skw%C9%9C%CB%90r.%C9%99l%2F"},{"id":"lv_5_348","topic":"Nature and Environmental Protection","word":"stability","pos":"(n)","ipa":"/stəˈbɪl.ə.t̬i/","defVi":"sự ổn định, tính bền vững","defEn":"the state of being steady and not likely to change or fail","examples":["Political [stability] is crucial for encouraging foreign investment. (=Dịch: Sự ổn định chính trị là yếu tố then chốt để khuyến khích đầu tư nước ngoài.)","The doctor confirmed that the patient's condition had reached [stability]. (=Dịch: Bác sĩ xác nhận rằng tình trạng của bệnh nhân đã đạt mức ổn định.)","This exercise helps improve core strength and overall body [stability]. (=Dịch: Bài tập này giúp tăng cường sức mạnh cốt lõi và sự ổn định tổng thể của cơ thể.)"],"ukAudio":"/ai_services/tts3/?q=stability&lang=en-GB&ipa=%2Fst%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=stability&lang=en-US&ipa=%2Fst%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_5_349","topic":"Nature and Environmental Protection","word":"stable","pos":"(adj)","ipa":"/ˈsteɪ.bəl/","defVi":"ổn định, vững chắc","defEn":"not likely to change, fail, or move suddenly; firmly fixed","examples":["The patient remains in a [stable] condition following the emergency surgery. (=Dịch: Bệnh nhân vẫn duy trì tình trạng ổn định sau ca phẫu thuật khẩn cấp.)","A [stable] economy is essential for attracting long-term foreign direct investment. (=Dịch: Một nền kinh tế ổn định là điều cốt yếu để thu hút vốn đầu tư trực tiếp nước ngoài dài hạn.)","Make sure the ladder is placed on a [stable] surface before climbing up. (=Dịch: Hãy chắc chắn rằng chiếc thang được đặt trên một bề mặt vững chắc trước khi trèo lên.)"],"ukAudio":"/ai_services/tts3/?q=stable&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=stable&lang=en-US&ipa=%2F%CB%88ste%C9%AA.b%C9%99l%2F"},{"id":"lv_5_350","topic":"Nature and Environmental Protection","word":"status","pos":"(n)","ipa":"/ˈsteɪ.t̬əs/","defVi":"địa vị, vị thế; tình trạng","defEn":"an official position, social rank, or current condition of a situation","examples":["The committee checked the current [status] of the construction project. (=Dịch: Ủy ban đã kiểm tra tình trạng hiện tại của dự án xây dựng.)","She gained higher social [status] after receiving the prestigious award. (=Dịch: Cô ấy đã đạt được vị thế xã hội cao hơn sau khi nhận giải thưởng danh giá.)","You can track the delivery [status] of your package online. (=Dịch: Bạn có thể theo dõi tình trạng giao kiện hàng của mình trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=status&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.t%CC%AC%C9%99s%2F","usAudio":"/ai_services/tts3/?q=status&lang=en-US&ipa=%2F%CB%88ste%C9%AA.t%CC%AC%C9%99s%2F"},{"id":"lv_5_351","topic":"Nature and Environmental Protection","word":"stork","pos":"(n)","ipa":"/stɔːrk/","defVi":"con cò, con hạc","defEn":"a large bird with long legs, a long neck, and a long beak, often living near water","examples":["A white [stork] built its large nest on top of the old chimney. (=Dịch: Một con cò trắng đã xây chiếc tổ lớn trên đỉnh ống khói cũ.)","In European folklore, the [stork] is believed to bring newborn babies to parents. (=Dịch: Trong văn hóa dân gian châu Âu, loài cò được tin là mang những đứa trẻ sơ sinh đến cho cha mẹ.)","We observed a majestic [stork] wading patiently through the shallow wetland. (=Dịch: Chúng tôi quan sát một con cò uy nghi đang kiên nhẫn lội qua vùng đất ngập nước nông.)"],"ukAudio":"/ai_services/tts3/?q=stork&lang=en-GB&ipa=%2Fst%C9%94%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=stork&lang=en-US&ipa=%2Fst%C9%94%CB%90rk%2F"},{"id":"lv_5_352","topic":"Nature and Environmental Protection","word":"strand","pos":"(v)","ipa":"/strænd/","defVi":"làm mắc cạn, làm cho mắc kẹt","defEn":"to leave someone or something in a difficult situation without the means to move or leave","examples":["A sudden snowstorm can [strand] travelers at the airport for days. (=Dịch: Một trận bão tuyết bất ngờ có thể làm du khách mắc kẹt tại sân bay nhiều ngày.)","Low tide may [strand] boats on the mudflats until morning. (=Dịch: Thủy triều xuống có thể làm các con thuyền mắc cạn trên bãi bùn cho đến sáng.)","The cancellation of trains [stranded] thousands of daily commuters. (=Dịch: Việc hủy các chuyến tàu đã khiến hàng ngàn người đi làm hàng ngày bị mắc kẹt.)"],"ukAudio":"/ai_services/tts3/?q=strand&lang=en-GB&ipa=%2Fstr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=strand&lang=en-US&ipa=%2Fstr%C3%A6nd%2F"},{"id":"lv_5_353","topic":"Nature and Environmental Protection","word":"stranding","pos":"(n)","ipa":"/ˈstræn.dɪŋ/","defVi":"sự mắc cạn, sự trôi dạt vào bờ","defEn":"an event in which marine animals or boats become stuck on land and unable to move","examples":["Scientists are investigating the mass [stranding] of whales along the coast. (=Dịch: Các nhà khoa học đang điều tra vụ mắc cạn hàng loạt của cá voi dọc theo bờ biển.)","The sudden snowstorm caused the [stranding] of hundreds of travelers at the airport. (=Dịch: Cơn bão tuyết bất ngờ đã khiến hàng trăm du khách bị mắc kẹt tại sân bay.)","Volunteers worked quickly to prevent the [stranding] of injured sea turtles. (=Dịch: Các tình nguyện viên đã làm việc nhanh chóng để ngăn chặn những chú rùa biển bị thương khỏi mắc cạn.)"],"ukAudio":"/ai_services/tts3/?q=stranding&lang=en-GB&ipa=%2F%CB%88str%C3%A6n.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=stranding&lang=en-US&ipa=%2F%CB%88str%C3%A6n.d%C9%AA%C5%8B%2F"},{"id":"lv_5_354","topic":"Nature and Environmental Protection","word":"stranger","pos":"(n)","ipa":"/ˈstreɪn.dʒɚ/","defVi":"người lạ","defEn":"a person whom one does not know or with whom one is not familiar","examples":["Children are often taught not to talk to a [stranger] in public places. (=Dịch: Trẻ em thường được dạy không nên nói chuyện với người lạ ở nơi công cộng.)","When she moved to the new city, she felt like a complete [stranger]. (=Dịch: Khi chuyển đến thành phố mới, cô cảm thấy mình như một người hoàn toàn xa lạ.)","A kind [stranger] helped me find my way back to the train station. (=Dịch: Một người lạ tốt bụng đã giúp tôi tìm đường trở lại ga xe lửa.)"],"ukAudio":"/ai_services/tts3/?q=stranger&lang=en-GB&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=stranger&lang=en-US&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_5_355","topic":"Nature and Environmental Protection","word":"stream","pos":"(n)","ipa":"/striːm/","defVi":"dòng suối, con suối","defEn":"a small, narrow river of water","examples":["We sat by a clear mountain [stream] to have our picnic lunch. (=Dịch: Chúng tôi ngồi bên một dòng suối núi trong vắt để ăn bữa trưa dã ngoại.)","The children enjoyed catching small fish in the shallow [stream]. (=Dịch: Lũ trẻ rất thích bắt những con cá nhỏ trong con suối nông.)","A gentle [stream] flows through the middle of the quiet village. (=Dịch: Một dòng suối êm đềm chảy qua giữa ngôi làng yên tĩnh.)"],"ukAudio":"/ai_services/tts3/?q=stream&lang=en-GB&ipa=%2Fstri%CB%90m%2F","usAudio":"/ai_services/tts3/?q=stream&lang=en-US&ipa=%2Fstri%CB%90m%2F"},{"id":"lv_5_356","topic":"Nature and Environmental Protection","word":"string","pos":"(n)","ipa":"/strɪŋ/","defVi":"sợi dây, sợi chỉ mảnh","defEn":"thin cord or thread used for tying, hanging, or fastening things","examples":["He tied the parcel securely with a long piece of durable [string]. (=Dịch: Anh ấy buộc chặt bưu kiện bằng một đoạn dây dù bền và dài.)","The musician replaced a broken [string] on his classical guitar. (=Dịch: Người nhạc sĩ đã thay một sợi dây bị đứt trên cây đàn guitar cổ điển của mình.)","She used colorful [string] to hang the party decorations along the wall. (=Dịch: Cô ấy dùng dây nhiều màu sắc để treo đồ trang trí tiệc dọc theo bức tường.)"],"ukAudio":"/ai_services/tts3/?q=string&lang=en-GB&ipa=%2Fstr%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=string&lang=en-US&ipa=%2Fstr%C9%AA%C5%8B%2F"},{"id":"lv_5_357","topic":"Nature and Environmental Protection","word":"strip","pos":"(v)","ipa":"/strɪp/","defVi":"lột, bóc bỏ; tước đoạt","defEn":"to remove the outer layer or covering from something, or to take something away","examples":["In autumn, the strong winds [strip] the leaves from the trees. (=Dịch: Vào mùa thu, những cơn gió mạnh cuốn sạch lá khỏi cây cối.)","The athlete was [stripped] of his medal after failing the drug test. (=Dịch: Vận động viên đã bị tước huy chương sau khi không qua được buổi kiểm tra chất kích thích.)","Volunteers helped [strip] the old wallpaper before repainting the room. (=Dịch: Các tình nguyện viên đã giúp bóc lớp giấy dán tường cũ trước khi sơn lại căn phòng.)"],"ukAudio":"/ai_services/tts3/?q=strip&lang=en-GB&ipa=%2Fstr%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=strip&lang=en-US&ipa=%2Fstr%C9%AAp%2F"},{"id":"lv_5_358","topic":"Nature and Environmental Protection","word":"sub","pos":"(n)","ipa":"/sʌb/","defVi":"Tàu ngầm hoặc cầu thủ dự bị.","defEn":"A submarine or a substitute player in a sports team.","examples":["The coach decided to bring on a [sub] in the second half of the match. (=Dịch: Huấn luyện viên quyết định tung một cầu thủ dự bị vào sân ở hiệp hai của trận đấu.)","The military operates a nuclear-powered [sub] for deep-sea defense. (=Dịch: Quân đội vận hành một chiếc tàu ngầm chạy bằng năng lượng hạt nhân để phòng thủ dưới biển sâu.)","He worked as a [sub] teacher when the regular instructor fell ill. (=Dịch: Anh ấy đã làm giáo viên dạy thay khi người hướng dẫn chính bị ốm.)"],"ukAudio":"/ai_services/tts3/?q=sub&lang=en-GB&ipa=%2Fs%CA%8Cb%2F","usAudio":"/ai_services/tts3/?q=sub&lang=en-US&ipa=%2Fs%CA%8Cb%2F"},{"id":"lv_5_359","topic":"Nature and Environmental Protection","word":"substance","pos":"(n)","ipa":"/ˈsʌb.stəns/","defVi":"chất, vật chất","defEn":"a particular type of solid, liquid, or gas that has specific physical properties","examples":["The laboratory is analyzing an unknown chemical [substance] found in the river. (=Dịch: Phòng thí nghiệm đang phân tích một chất hóa học lạ được tìm thấy dưới sông.)","Rubber is an elastic [substance] used to manufacture car tires. (=Dịch: Cao su là một chất có tính đàn hồi được dùng để sản xuất lốp xe ô tô.)","The spilled [substance] quickly dissolved when water was added. (=Dịch: Chất bị đổ ra đã nhanh chóng hòa tan khi nước được thêm vào.)"],"ukAudio":"/ai_services/tts3/?q=substance&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=substance&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.st%C9%99ns%2F"},{"id":"lv_5_360","topic":"Nature and Environmental Protection","word":"sufficient","pos":"(adj)","ipa":"/sə.ˈfɪʃ.ənt/","defVi":"Đủ, đáp ứng đủ yêu cầu","defEn":"Enough for a particular purpose; as much as is needed.","examples":["Make sure you drink [sufficient] water during the long marathon. (=Dịch: Hãy đảm bảo rằng bạn uống đủ nước trong suốt cuộc chạy marathon dài.)","There was not [sufficient] evidence to prove the suspect's guilt. (=Dịch: Không có đủ bằng chứng để chứng minh tội trạng của nghi phạm.)","One bowl of soup is [sufficient] for a light lunch. (=Dịch: Một bát súp là đủ cho một bữa trưa nhẹ nhàng.)"],"ukAudio":"/ai_services/tts3/?q=sufficient&lang=en-GB&ipa=%2Fs%C9%99.%CB%88f%C9%AA%CA%83.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=sufficient&lang=en-US&ipa=%2Fs%C9%99.%CB%88f%C9%AA%CA%83.%C9%99nt%2F"},{"id":"lv_5_361","topic":"Nature and Environmental Protection","word":"sunlight","pos":"(n)","ipa":"/ˈsʌn.laɪt/","defVi":"ánh sáng mặt trời, ánh nắng","defEn":"the light that comes from the sun","examples":["Plants need plenty of [sunlight] and water to grow properly. (=Dịch: Cây cối cần nhiều ánh nắng mặt trời và nước để phát triển tốt.)","The room was flooded with warm [sunlight] early in the morning. (=Dịch: Căn phòng tràn ngập ánh nắng ấm áp vào sáng sớm.)","You should wear sunscreen to protect your skin from intense [sunlight]. (=Dịch: Bạn nên thoa kem chống nắng để bảo vệ da khỏi ánh nắng gay gắt.)"],"ukAudio":"/ai_services/tts3/?q=sunlight&lang=en-GB&ipa=%2F%CB%88s%CA%8Cn.la%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=sunlight&lang=en-US&ipa=%2F%CB%88s%CA%8Cn.la%C9%AAt%2F"},{"id":"lv_5_362","topic":"Nature and Environmental Protection","word":"survive","pos":"(v)","ipa":"/sɚˈvaɪv/","defVi":"sống sót, tồn tại qua nghịch cảnh","defEn":"to continue to live or exist, especially through difficult conditions","examples":["Desert plants have special adaptations that help them [survive] without rain. (=Dịch: Cây sa mạc có những đặc tính thích nghi đặc biệt giúp chúng sinh tồn mà không cần mưa.)","Only a few passengers managed to [survive] the severe shipwreck. (=Dịch: Chỉ có một vài hành khách may mắn sống sót sau vụ đắm tàu kinh hoàng.)","Local businesses must adapt quickly to [survive] in a competitive market. (=Dịch: Các doanh nghiệp địa phương phải nhanh chóng thích ứng để tồn tại trong thị trường cạnh tranh.)"],"ukAudio":"/ai_services/tts3/?q=survive&lang=en-GB&ipa=%2Fs%C9%9A%CB%88va%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=survive&lang=en-US&ipa=%2Fs%C9%9A%CB%88va%C9%AAv%2F"},{"id":"lv_5_363","topic":"Nature and Environmental Protection","word":"sustainable","pos":"(adj)","ipa":"/səˈsteɪ.nə.bəl/","defVi":"bền vững (không gây hại đến môi trường hoặc tài nguyên)","defEn":"able to continue over a period of time without causing damage to the environment","examples":["The company is investing heavily in [sustainable] energy solutions like solar and wind power. (=Dịch: Công ty đang đầu tư mạnh vào các giải pháp năng lượng bền vững như điện mặt trời và năng lượng gió.)","Farmers are encouraged to adopt more [sustainable] practices to protect the soil quality. (=Dịch: Nông dân được khuyến khích áp dụng các phương pháp bền vững hơn để bảo vệ chất lượng đất.)","Tourism needs to be [sustainable] so that local ecosystems are not permanently damaged. (=Dịch: Du lịch cần phải bền vững để hệ sinh thái địa phương không bị hủy hoại lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=sustainable&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sustainable&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F"},{"id":"lv_5_364","topic":"Nature and Environmental Protection","word":"swimmer","pos":"(n)","ipa":"/ˈswɪm.ɚ/","defVi":"Người bơi lội, kình ngư.","defEn":"A person who swims, especially as a sport or recreation.","examples":["She is a talented [swimmer] who has won several national championships. (=Dịch: Cô ấy là một kình ngư tài năng từng giành được nhiều chức vô địch quốc gia.)","Lifeguards warned every [swimmer] to stay close to the shore. (=Dịch: Các nhân viên cứu hộ đã cảnh báo mọi người bơi phải ở gần bờ.)","Regular practice helped him become a much faster [swimmer]. (=Dịch: Luyện tập đều đặn đã giúp anh ấy trở thành một người bơi nhanh hơn rất nhiều.)"],"ukAudio":"/ai_services/tts3/?q=swimmer&lang=en-GB&ipa=%2F%CB%88sw%C9%AAm.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=swimmer&lang=en-US&ipa=%2F%CB%88sw%C9%AAm.%C9%9A%2F"},{"id":"lv_5_365","topic":"Nature and Environmental Protection","word":"sydney","pos":"(n)","ipa":"/ˈsɪd.ni/","defVi":"Sydney (thành phố lớn nhất của Úc).","defEn":"The largest city in Australia, famous for its Opera House and harbor.","examples":["Many tourists visit [sydney] to see the iconic Opera House. (=Dịch: Nhiều khách du lịch đến thăm Sydney để chiêm ngưỡng nhà hát Opera mang tính biểu tượng.)","She decided to study abroad at a university located in [sydney]. (=Dịch: Cô quyết định đi du học tại một trường đại học nằm ở Sydney.)","The international flight landed safely at the airport in [sydney]. (=Dịch: Chuyến bay quốc tế đã hạ cánh an toàn tại sân bay ở Sydney.)"],"ukAudio":"/ai_services/tts3/?q=sydney&lang=en-GB&ipa=%2F%CB%88s%C9%AAd.ni%2F","usAudio":"/ai_services/tts3/?q=sydney&lang=en-US&ipa=%2F%CB%88s%C9%AAd.ni%2F"},{"id":"lv_5_366","topic":"Nature and Environmental Protection","word":"tail","pos":"(n)","ipa":"/teɪl/","defVi":"đuôi (động vật, đồ vật)","defEn":"the part that sticks out at the back end of an animal's body","examples":["The dog wagged its [tail] happily when its owner came home. (=Dịch: Con chó vẫy đuôi vui mừng khi chủ của nó về nhà.)","The airplane's [tail] was damaged during the emergency landing. (=Dịch: Phần đuôi của máy bay đã bị hư hại trong quá trình hạ cánh khẩn cấp.)","A long [tail] of traffic formed behind the broken-down truck. (=Dịch: Một hàng dài xe cộ nối đuôi nhau đã hình thành phía sau chiếc xe tải bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=tail&lang=en-GB&ipa=%2Fte%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=tail&lang=en-US&ipa=%2Fte%C9%AAl%2F"},{"id":"lv_5_367","topic":"Nature and Environmental Protection","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, khóa van","defEn":"a device used to control the flow of liquid or gas from a pipe","examples":["Don't forget to turn off the [tap] while brushing your teeth to save water. (=Dịch: Đừng quên tắt vòi nước trong khi đánh răng để tiết kiệm nước.)","The kitchen [tap] has been leaking continuously since yesterday morning. (=Dịch: Vòi nước trong bếp đã bị rò rỉ liên tục từ sáng hôm qua.)","Filtered drinking water is available directly from this special [tap]. (=Dịch: Nước uống đã qua lọc có sẵn trực tiếp từ chiếc vòi nước đặc biệt này.)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_5_368","topic":"Nature and Environmental Protection","word":"tardigrade","pos":"(n)","ipa":"/ˈtɑːr.də.ɡreɪd/","defVi":"Bọ gấu nước (sinh vật vi mô có khả năng sống sót phi thường).","defEn":"A microscopic animal capable of surviving extreme conditions, also called a water bear.","examples":["Scientists study the [tardigrade] because it can survive in extreme temperatures. (=Dịch: Các nhà khoa học nghiên cứu bọ gấu nước vì nó có thể sống sót trong nhiệt độ khắc nghiệt.)","A [tardigrade] can withstand the vacuum and radiation of outer space. (=Dịch: Một con bọ gấu nước có thể chịu được môi trường chân không và bức xạ ngoài không gian.)","Under a microscope, the tiny [tardigrade] looks like an eight-legged bear. (=Dịch: Dưới kính hiển vi, sinh vật bọ gấu nước nhỏ bé trông giống như một con gấu tám chân.)"],"ukAudio":"/ai_services/tts3/?q=tardigrade&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90r.d%C9%99.%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=tardigrade&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90r.d%C9%99.%C9%A1re%C9%AAd%2F"},{"id":"lv_5_369","topic":"Nature and Environmental Protection","word":"territory","pos":"(n)","ipa":"/ˈter.ə.tɔːr.i/","defVi":"lãnh thổ, địa bàn","defEn":"an area of land under the jurisdiction of a ruler or state, or defended by an animal","examples":["The pack of wolves defended its hunting [territory] against rival packs. (=Dịch: Đàn sói đã bảo vệ lãnh thổ săn mồi của mình trước các đàn đối thủ.)","The company expanded its business into foreign [territory] last year. (=Dịch: Công ty đã mở rộng hoạt động kinh doanh sang thị trường nước ngoài vào năm ngoái.)","The disputed [territory] has been a source of conflict for decades. (=Dịch: Vùng lãnh thổ tranh chấp đã là nguồn cơn xung đột trong nhiều thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=territory&lang=en-GB&ipa=%2F%CB%88ter.%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=territory&lang=en-US&ipa=%2F%CB%88ter.%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_5_370","topic":"Nature and Environmental Protection","word":"testing","pos":"(n)","ipa":"/ˈtes.tɪŋ/","defVi":"sự thử nghiệm, kiểm tra","defEn":"the process of checking the quality, performance, or reliability of something","examples":["The new software underwent rigorous [testing] before its official launch. (=Dịch: Phần mềm mới đã trải qua quá trình kiểm tra nghiêm ngặt trước khi ra mắt chính thức.)","Medical [testing] is crucial to ensure that the new vaccine is safe for public use. (=Dịch: Việc thử nghiệm y tế là rất quan trọng để đảm bảo rằng loại vắc-xin mới an toàn cho cộng đồng.)","Laboratory [testing] confirmed the presence of minerals in the water sample. (=Dịch: Việc kiểm nghiệm trong phòng thí nghiệm đã xác nhận sự hiện diện của các khoáng chất trong mẫu nước.)"],"ukAudio":"/ai_services/tts3/?q=testing&lang=en-GB&ipa=%2F%CB%88tes.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=testing&lang=en-US&ipa=%2F%CB%88tes.t%C9%AA%C5%8B%2F"},{"id":"lv_5_371","topic":"Nature and Environmental Protection","word":"texture","pos":"(n)","ipa":"/ˈtɛks.tʃɚ/","defVi":"kết cấu, cảm giác bề mặt (của vật liệu, thức ăn)","defEn":"the feel, appearance, or consistency of a surface or a substance","examples":["The smooth [texture] of the silk fabric feels very comfortable against the skin. (=Dịch: Kết cấu mịn màng của vải lụa tạo cảm giác rất thoải mái trên da.)","Adding nuts gives this homemade bread a crunchy [texture]. (=Dịch: Việc thêm các loại hạt mang lại cho chiếc bánh mì tự làm này một kết cấu giòn rụm.)","The artist used heavy brushstrokes to create a rough [texture] on the canvas. (=Dịch: Họa sĩ đã sử dụng những nét cọ đậm để tạo nên kết cấu gồ ghề trên tấm toan.)"],"ukAudio":"/ai_services/tts3/?q=texture&lang=en-GB&ipa=%2F%CB%88t%C9%9Bks.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=texture&lang=en-US&ipa=%2F%CB%88t%C9%9Bks.t%CA%83%C9%9A%2F"},{"id":"lv_5_372","topic":"Nature and Environmental Protection","word":"thailand","pos":"(n)","ipa":"/ˈtaɪ.lænd/","defVi":"Thái Lan (quốc gia ở Đông Nam Á).","defEn":"A country in Southeast Asia known for its tropical beaches, temples, and cuisine.","examples":["Millions of travelers visit [thailand] every year for its rich culture and beaches. (=Dịch: Hàng triệu du khách đến thăm Thái Lan mỗi năm vì nền văn hóa phong phú và các bãi biển đẹp.)","Street food is an essential part of daily life across [thailand]. (=Dịch: Ẩm thực đường phố là một phần thiết yếu trong đời sống thường nhật trên khắp Thái Lan.)","Her family planned a summer vacation to the northern mountains of [thailand]. (=Dịch: Gia đình cô đã lên kế hoạch cho kỳ nghỉ hè tới vùng núi phía bắc Thái Lan.)"],"ukAudio":"/ai_services/tts3/?q=thailand&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.l%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=thailand&lang=en-US&ipa=%2F%CB%88ta%C9%AA.l%C3%A6nd%2F"},{"id":"lv_5_373","topic":"Nature and Environmental Protection","word":"thermal","pos":"(adj)","ipa":"/ˈθɝː.məl/","defVi":"Thuộc về nhiệt, giữ nhiệt","defEn":"Connected with heat or designed to retain heat.","examples":["The hikers wore [thermal] underwear to protect themselves from the freezing cold. (=Dịch: Những người đi bộ đường dài đã mặc đồ lót giữ nhiệt để bảo vệ mình khỏi cái lạnh cóng.)","Iceland is famous for its natural [thermal] springs. (=Dịch: Iceland nổi tiếng với các suối nước nóng tự nhiên.)","Engineers are developing new ways to capture [thermal] energy. (=Dịch: Các kỹ sư đang phát triển những phương pháp mới để thu giữ nhiệt năng.)"],"ukAudio":"/ai_services/tts3/?q=thermal&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9D%CB%90.m%C9%99l%2F","usAudio":"/ai_services/tts3/?q=thermal&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9D%CB%90.m%C9%99l%2F"},{"id":"lv_5_374","topic":"Nature and Environmental Protection","word":"thirdly","pos":"(adv)","ipa":"/ˈθɜrd.li/","defVi":"thứ ba là, điểm thứ ba là","defEn":"used to introduce the third point in a list or argument","examples":["First, we need more staff; secondly, better equipment; and [thirdly], a larger budget. (=Dịch: Thứ nhất, chúng ta cần thêm nhân lực; thứ hai, trang thiết bị tốt hơn; và thứ ba là một ngân sách lớn hơn.)","[Thirdly], the report highlights the growing environmental impact of urban expansion. (=Dịch: Thứ ba là báo cáo nhấn mạnh tác động môi trường ngày càng tăng của việc mở rộng đô thị.)","And [thirdly], we must ensure that all safety regulations are strictly followed. (=Dịch: Và thứ ba là chúng ta phải đảm bảo rằng mọi quy định an toàn đều được tuân thủ nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=thirdly&lang=en-GB&ipa=%2F%CB%88%CE%B8%C9%9Crd.li%2F","usAudio":"/ai_services/tts3/?q=thirdly&lang=en-US&ipa=%2F%CB%88%CE%B8%C9%9Crd.li%2F"},{"id":"lv_5_375","topic":"Nature and Environmental Protection","word":"threaten","pos":"(v)","ipa":"/ˈθrɛ.tən/","defVi":"đe dọa, uy hiếp","defEn":"to state an intention to harm someone or to be likely to cause damage to something","examples":["Pollution continues to [threaten] the survival of marine life. (=Dịch: Ô nhiễm tiếp tục đe dọa sự sống còn của sinh vật biển.)","Dark clouds gathered overhead and began to [threaten] rain. (=Dịch: Mây đen kéo đến vần vũ và đe dọa sẽ đổ mưa.)","The robber attempted to [threaten] the cashier with a weapon. (=Dịch: Kẻ cướp đã cố gắng đe dọa nhân viên thu ngân bằng vũ khí.)"],"ukAudio":"/ai_services/tts3/?q=threaten&lang=en-GB&ipa=%2F%CB%88%CE%B8r%C9%9B.t%C9%99n%2F","usAudio":"/ai_services/tts3/?q=threaten&lang=en-US&ipa=%2F%CB%88%CE%B8r%C9%9B.t%C9%99n%2F"},{"id":"lv_5_376","topic":"Nature and Environmental Protection","word":"thrive","pos":"(v)","ipa":"/θraɪv/","defVi":"phát triển mạnh, thịnh vượng, lớn nhanh","defEn":"to grow, develop, or be successful","examples":["Many species of plants [thrive] in tropical climates. (=Dịch: Nhiều loài thực vật phát triển mạnh ở vùng khí hậu nhiệt đới.)","The local tourism industry began to [thrive] after the new airport opened. (=Dịch: Ngành du lịch địa phương bắt đầu phát triển hưng thịnh sau khi sân bay mới mở cửa.)","Children [thrive] when they receive love and support from their families. (=Dịch: Trẻ em lớn khôn và phát triển tốt khi nhận được tình yêu thương và sự ủng hộ từ gia đình.)"],"ukAudio":"/ai_services/tts3/?q=thrive&lang=en-GB&ipa=%2F%CE%B8ra%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=thrive&lang=en-US&ipa=%2F%CE%B8ra%C9%AAv%2F"},{"id":"lv_5_377","topic":"Nature and Environmental Protection","word":"tidal","pos":"(adj)","ipa":"/ˈtaɪ.dəl/","defVi":"thuộc về thủy triều, chịu ảnh hưởng của triều cường","defEn":"relating to or affected by the regular rise and fall of the sea level","examples":["The coastal road was temporarily closed due to high [tidal] waves. (=Dịch: Tuyến đường ven biển đã tạm thời bị đóng do sóng thủy triều dâng cao.)","Engineers are exploring renewable energy generated by [tidal] currents. (=Dịch: Các kỹ sư đang nghiên cứu năng lượng tái tạo được tạo ra từ các dòng thủy triều.)","The estuary contains vast [tidal] mudflats that attract migratory birds. (=Dịch: Vùng cửa sông có những bãi bồi ven triều rộng lớn thu hút các loài chim di cư.)"],"ukAudio":"/ai_services/tts3/?q=tidal&lang=en-GB&ipa=%2F%CB%88ta%C9%AA.d%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tidal&lang=en-US&ipa=%2F%CB%88ta%C9%AA.d%C9%99l%2F"},{"id":"lv_5_378","topic":"Nature and Environmental Protection","word":"tide","pos":"(n)","ipa":"/taɪd/","defVi":"thủy triều, con nước","defEn":"the regular rise and fall in the level of the sea caused by the gravitational pull of the moon and sun","examples":["We had to wait for high [tide] before sailing our boat out of the bay. (=Dịch: Chúng tôi phải đợi thủy triều lên trước khi chèo thuyền ra khỏi vịnh.)","At low [tide], children enjoy exploring the rock pools along the beach. (=Dịch: Khi thủy triều xuống, trẻ em thích thú khám phá các vũng nước quanh bãi đá ven biển.)","The rising [tide] quickly washed away their sandcastles. (=Dịch: Thủy triều dâng cao nhanh chóng cuốn trôi những lâu đài cát của họ.)"],"ukAudio":"/ai_services/tts3/?q=tide&lang=en-GB&ipa=%2Fta%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=tide&lang=en-US&ipa=%2Fta%C9%AAd%2F"},{"id":"lv_5_379","topic":"Nature and Environmental Protection","word":"timeline","pos":"(n)","ipa":"/ˈtaɪm.laɪn/","defVi":"dòng thời gian, tiến độ thời gian","defEn":"a visual representation or schedule showing the order in which events happen","examples":["The project manager created a clear [timeline] to track our daily progress. (=Dịch: Quản lý dự án đã tạo ra một tiến độ thời gian rõ ràng để theo dõi tiến độ hàng ngày của chúng tôi.)","The history textbook includes a detailed [timeline] of World War II. (=Dịch: Sách giáo khoa lịch sử bao gồm một dòng thời gian chi tiết về Thế chiến thứ hai.)","We need to adjust the construction [timeline] due to unexpected weather delays. (=Dịch: Chúng tôi cần điều chỉnh tiến độ thi công do sự chậm trễ ngoài dự kiến bởi thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=timeline&lang=en-GB&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=timeline&lang=en-US&ipa=%2F%CB%88ta%C9%AAm.la%C9%AAn%2F"},{"id":"lv_5_380","topic":"Nature and Environmental Protection","word":"tongue","pos":"(n)","ipa":"/tʌŋ/","defVi":"lưỡi; ngôn ngữ","defEn":"the soft, moveable organ in the mouth used for tasting and speaking, or a language","examples":["He burned his [tongue] because the soup was too hot. (=Dịch: Anh ấy bị bỏng lưỡi vì món súp quá nóng.)","Spanish is her native [tongue], but she also speaks fluent English. (=Dịch: Tiếng Tây Ban Nha là tiếng mẹ đẻ của cô ấy, nhưng cô ấy cũng nói tiếng Anh rất lưu loát.)","The doctor asked the patient to stick out his [tongue]. (=Dịch: Bác sĩ đã yêu cầu bệnh nhân thè lưỡi ra.)"],"ukAudio":"/ai_services/tts3/?q=tongue&lang=en-GB&ipa=%2Ft%CA%8C%C5%8B%2F","usAudio":"/ai_services/tts3/?q=tongue&lang=en-US&ipa=%2Ft%CA%8C%C5%8B%2F"},{"id":"lv_5_381","topic":"Nature and Environmental Protection","word":"topsoil","pos":"(n)","ipa":"/ˈtɑːp.sɔɪl/","defVi":"lớp đất mặt, tầng đất canh tác","defEn":"the upper, outermost layer of soil, usually containing organic matter and nutrients","examples":["Heavy rainfall washed away the fertile [topsoil] on the hillside farms. (=Dịch: Mưa lớn đã cuốn trôi lớp đất mặt màu mỡ trên các nông trại sườn đồi.)","It takes hundreds of years for nature to form a single inch of rich [topsoil]. (=Dịch: Tự nhiên phải mất hàng trăm năm để tạo ra một inch lớp đất mặt giàu dinh dưỡng.)","Farmers use cover crops to prevent [topsoil] erosion during windy seasons. (=Dịch: Người nông dân trồng cây che phủ đất để ngăn chặn xói mòn lớp đất mặt trong mùa gió.)"],"ukAudio":"/ai_services/tts3/?q=topsoil&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90p.s%C9%94%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=topsoil&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90p.s%C9%94%C9%AAl%2F"},{"id":"lv_5_382","topic":"Nature and Environmental Protection","word":"toxic","pos":"(adj)","ipa":"/ˈtɑk.sɪk/","defVi":"độc hại, có chứa chất độc","defEn":"containing poisonous substances that can cause harm or death","examples":["The factory was fined for dumping [toxic] chemical waste into the river. (=Dịch: Nhà máy đã bị phạt vì xả chất thải hóa học độc hại xuống sông.)","Wearing protective masks prevents workers from inhaling [toxic] fumes. (=Dịch: Đeo khẩu trang bảo hộ giúp công nhân tránh hít phải khói độc.)","Certain household cleaning products can be [toxic] if swallowed by pets. (=Dịch: Một số sản phẩm tẩy rửa gia dụng có thể gây độc nếu vật nuôi nuốt phải.)"],"ukAudio":"/ai_services/tts3/?q=toxic&lang=en-GB&ipa=%2F%CB%88t%C9%91k.s%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=toxic&lang=en-US&ipa=%2F%CB%88t%C9%91k.s%C9%AAk%2F"},{"id":"lv_5_383","topic":"Nature and Environmental Protection","word":"toxin","pos":"(n)","ipa":"/ˈtɑːk.sɪn/","defVi":"độc tố, chất độc sinh học","defEn":"a poisonous substance, especially one produced by bacteria or living organisms","examples":["Certain species of snake produce a powerful [toxin] to paralyze their prey. (=Dịch: Một số loài rắn sản sinh ra một loại độc tố mạnh để làm tê liệt con mồi.)","Drinking plenty of water helps the body flush out harmful [toxin] substances. (=Dịch: Uống nhiều nước giúp cơ thể đào thải các chất độc tố có hại.)","The biological [toxin] found in the contaminated food caused severe illness. (=Dịch: Độc tố sinh học được tìm thấy trong thực phẩm ôi thiu đã gây ra bệnh nặng.)"],"ukAudio":"/ai_services/tts3/?q=toxin&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=toxin&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F"},{"id":"lv_5_384","topic":"Nature and Environmental Protection","word":"transform","pos":"(v)","ipa":"/trænsˈfɔːrm/","defVi":"biến đổi, thay đổi hoàn toàn","defEn":"to completely change the appearance, form, or character of something","examples":["New public transport systems can [transform] the entire city. (=Dịch: Các hệ thống giao thông công cộng mới có thể biến đổi toàn bộ thành phố.)","The internet continues to [transform] the way people communicate. (=Dịch: Internet tiếp tục làm thay đổi hoàn toàn cách mọi người giao tiếp.)","A coat of fresh paint will [transform] this old bedroom completely. (=Dịch: Một lớp sơn mới sẽ làm thay đổi hoàn toàn căn phòng ngủ cũ kỹ này.)"],"ukAudio":"/ai_services/tts3/?q=transform&lang=en-GB&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=transform&lang=en-US&ipa=%2Ftr%C3%A6ns%CB%88f%C9%94%CB%90rm%2F"},{"id":"lv_5_385","topic":"Nature and Environmental Protection","word":"translocation","pos":"(n)","ipa":"/ˌtrænz.loʊˈkeɪ.ʃən/","defVi":"sự di dời, sự chuyển vị (đặc biệt là động thực vật)","defEn":"the process of moving something, especially wild animals or plants, to a new location","examples":["The conservation team organised the [translocation] of ten rhinos to a safer habitat. (=Dịch: Nhóm bảo tồn đã tổ chức việc di dời mười cá thể tê giác đến một môi trường sống an toàn hơn.)","Successful [translocation] depends heavily on whether the new area has sufficient food sources. (=Dịch: Sự di dời thành công phụ thuộc rất nhiều vào việc khu vực mới có đủ nguồn thức ăn hay không.)","Biologists monitored the species closely after its [translocation] to the national park. (=Dịch: Các nhà sinh vật học đã theo dõi chặt chẽ loài này sau khi nó được chuyển vị vào vườn quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=translocation&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6nz.lo%CA%8A%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=translocation&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6nz.lo%CA%8A%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_386","topic":"Nature and Environmental Protection","word":"treaty","pos":"(n)","ipa":"/ˈtriː.t̬i/","defVi":"hiệp ước, hiệp định","defEn":"a formal, legally binding agreement concluded between countries","examples":["The two nations signed a peace [treaty] to end the decade-long conflict. (=Dịch: Hai quốc gia đã ký một hiệp ước hòa bình để chấm dứt cuộc xung đột kéo dài cả thập kỷ.)","Environmental groups urged leaders to ratify the international climate [treaty]. (=Dịch: Các nhóm môi trường đã thúc giục các nhà lãnh đạo phê chuẩn hiệp ước khí hậu quốc tế.)","Under the terms of the [treaty], trade barriers between the countries were reduced. (=Dịch: Theo các điều khoản của hiệp ước, các rào cản thương mại giữa các nước đã được giảm bớt.)"],"ukAudio":"/ai_services/tts3/?q=treaty&lang=en-GB&ipa=%2F%CB%88tri%CB%90.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=treaty&lang=en-US&ipa=%2F%CB%88tri%CB%90.t%CC%ACi%2F"},{"id":"lv_5_387","topic":"Nature and Environmental Protection","word":"trial","pos":"(n)","ipa":"/ˈtraɪ.əl/","defVi":"sự thử nghiệm, cuộc thử nghiệm","defEn":"a test of the performance, qualities, or suitability of someone or something","examples":["The new drug is currently undergoing a clinical [trial] to ensure its safety. (=Dịch: Loại thuốc mới hiện đang trải qua một cuộc thử nghiệm lâm sàng để đảm bảo tính an toàn.)","Customers can download software for a free thirty-day [trial]. (=Dịch: Khách hàng có thể tải phần mềm để dùng thử miễn phí trong ba mươi ngày.)","They learned the most effective technique through a process of [trial] and error. (=Dịch: Họ đã học được kỹ thuật hiệu quả nhất thông qua quá trình thử và sai.)"],"ukAudio":"/ai_services/tts3/?q=trial&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=trial&lang=en-US&ipa=%2F%CB%88tra%C9%AA.%C9%99l%2F"},{"id":"lv_5_388","topic":"Nature and Environmental Protection","word":"tropical","pos":"(adj)","ipa":"/ˈtrɑː.pɪ.kəl/","defVi":"thuộc nhiệt đới","defEn":"relating to or typical of the warm and humid regions near the equator","examples":["Many exotic fruits thrive in a warm [tropical] climate. (=Dịch: Nhiều loại trái cây độc lạ phát triển mạnh ở vùng khí hậu nhiệt đới ấm áp.)","They spent their holiday relaxing on a beautiful [tropical] island. (=Dịch: Họ đã dành kỳ nghỉ để thư giãn trên một hòn đảo nhiệt đới xinh đẹp.)","The region is frequently hit by destructive [tropical] storms. (=Dịch: Khu vực này thường xuyên bị tấn công bởi những cơn bão nhiệt đới có sức tàn phá lớn.)"],"ukAudio":"/ai_services/tts3/?q=tropical&lang=en-GB&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tropical&lang=en-US&ipa=%2F%CB%88tr%C9%91%CB%90.p%C9%AA.k%C9%99l%2F"},{"id":"lv_5_389","topic":"Nature and Environmental Protection","word":"trucks","pos":"(n)","ipa":"/trʌks/","defVi":"xe tải (dạng số nhiều)","defEn":"large, heavy motor vehicles used for transporting goods","examples":["Heavy [trucks] are prohibited from entering the city centre during peak hours. (=Dịch: Xe tải hạng nặng bị cấm đi vào trung tâm thành phố trong giờ cao điểm.)","A fleet of [trucks] delivered the construction materials to the building site. (=Dịch: Một đội xe tải đã vận chuyển các vật liệu xây dựng đến công trường.)","Many transport companies are switching to electric [trucks] to reduce emissions. (=Dịch: Nhiều công ty vận tải đang chuyển sang dùng xe tải điện để giảm thiểu lượng khí thải.)"],"ukAudio":"/ai_services/tts3/?q=trucks&lang=en-GB&ipa=%2Ftr%CA%8Cks%2F","usAudio":"/ai_services/tts3/?q=trucks&lang=en-US&ipa=%2Ftr%CA%8Cks%2F"},{"id":"lv_5_390","topic":"Nature and Environmental Protection","word":"tun","pos":"(n)","ipa":"/tʌn/","defVi":"Thùng lớn (thường dùng để ủ bia hoặc chứa rượu).","defEn":"A large cask or barrel used especially for holding beer, wine, or other liquids.","examples":["The traditional brewery stored hundreds of gallons of ale in a massive wooden [tun]. (=Dịch: Nhà máy bia truyền thống đã lưu trữ hàng trăm gallon bia trong một chiếc thùng gỗ khổng lồ.)","Workers carefully cleaned the mash [tun] before starting the next brewing cycle. (=Dịch: Các công nhân đã cẩn thận vệ sinh thùng ngâm mạch nha trước khi bắt đầu chu kỳ nấu bia tiếp theo.)","The historical cellar still contains an ancient oak [tun] from the eighteenth century. (=Dịch: Hầm rượu lịch sử vẫn còn chứa một thùng gỗ sồi cổ từ thế kỷ thứ mười tám.)"],"ukAudio":"/ai_services/tts3/?q=tun&lang=en-GB&ipa=%2Ft%CA%8Cn%2F","usAudio":"/ai_services/tts3/?q=tun&lang=en-US&ipa=%2Ft%CA%8Cn%2F"},{"id":"lv_5_391","topic":"Nature and Environmental Protection","word":"turbine","pos":"(n)","ipa":"/ˈtɜr.baɪn/","defVi":"tuabin","defEn":"a machine with rotating blades that produces power from the movement of air, water, or steam","examples":["A modern wind [turbine] can generate enough electricity for hundreds of homes. (=Dịch: Một tuabin gió hiện đại có thể tạo ra đủ điện cho hàng trăm hộ gia đình.)","Water rushes through the dam to turn the massive [turbine]. (=Dịch: Nước chảy xiết qua đập để làm quay tuabin khổng lồ.)","Engineers are developing a more efficient gas [turbine] for aircraft. (=Dịch: Các kỹ sư đang phát triển một loại tuabin khí hiệu quả hơn cho máy bay.)"],"ukAudio":"/ai_services/tts3/?q=turbine&lang=en-GB&ipa=%2F%CB%88t%C9%9Cr.ba%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=turbine&lang=en-US&ipa=%2F%CB%88t%C9%9Cr.ba%C9%AAn%2F"},{"id":"lv_5_392","topic":"Nature and Environmental Protection","word":"turtle","pos":"(n)","ipa":"/ˈtɜːr.t̬əl/","defVi":"con rùa, rùa biển","defEn":"a reptile with a hard round shell that lives mostly in water","examples":["A sea [turtle] laid her eggs on the sandy beach at night. (=Dịch: Một con rùa biển đã đẻ trứng trên bãi cát vào ban đêm.)","The plastic waste in the ocean poses a serious threat to every [turtle]. (=Dịch: Rác thải nhựa trong đại dương là mối đe dọa nghiêm trọng đối với mọi loài rùa.)","We watched a giant [turtle] swimming slowly near the coral reef. (=Dịch: Chúng tôi đã ngắm nhìn một con rùa khổng lồ bơi chậm rãi gần rạn san hô.)"],"ukAudio":"/ai_services/tts3/?q=turtle&lang=en-GB&ipa=%2F%CB%88t%C9%9C%CB%90r.t%CC%AC%C9%99l%2F","usAudio":"/ai_services/tts3/?q=turtle&lang=en-US&ipa=%2F%CB%88t%C9%9C%CB%90r.t%CC%AC%C9%99l%2F"},{"id":"lv_5_393","topic":"Nature and Environmental Protection","word":"tusk","pos":"(n)","ipa":"/tʌsk/","defVi":"ngà voi, răng nanh dài của động vật","defEn":"a very long, pointed tooth that sticks out of the mouth of animals like elephants or walruses","examples":["The elephant used its massive [tusk] to dig for roots. (=Dịch: Con voi đã dùng chiếc ngà to lớn của nó để đào rễ cây.)","An old walrus broke its left [tusk] against the sharp ice. (=Dịch: Một con hải mã già đã làm gãy chiếc ngà bên trái vào tảng băng sắc nhọn.)","Scientists examined a prehistoric mammoth [tusk] discovered in the frozen mud. (=Dịch: Các nhà khoa học đã kiểm tra một chiếc ngà voi ma mút tiền sử được phát hiện trong bùn đóng băng.)"],"ukAudio":"/ai_services/tts3/?q=tusk&lang=en-GB&ipa=%2Ft%CA%8Csk%2F","usAudio":"/ai_services/tts3/?q=tusk&lang=en-US&ipa=%2Ft%CA%8Csk%2F"},{"id":"lv_5_394","topic":"Nature and Environmental Protection","word":"twentieth","pos":"(adj)","ipa":"/ˈtwɛn.ti.əθ/","defVi":"thứ hai mươi","defEn":"constituting number twenty in a sequence; coming after nineteenth","examples":["She celebrated her [twentieth] birthday with close family and friends. (=Dịch: Cô ấy đã tổ chức sinh nhật lần thứ hai mươi cùng gia đình và bạn bè thân thiết.)","The museum features art from the early [twentieth] century. (=Dịch: Bảo tàng trưng bày nghệ thuật từ đầu thế kỷ hai mươi.)","He finished in [twentieth] place out of more than one hundred runners. (=Dịch: Anh ấy về đích ở vị trí thứ hai mươi trong số hơn một trăm vận động viên chạy bộ.)"],"ukAudio":"/ai_services/tts3/?q=twentieth&lang=en-GB&ipa=%2F%CB%88tw%C9%9Bn.ti.%C9%99%CE%B8%2F","usAudio":"/ai_services/tts3/?q=twentieth&lang=en-US&ipa=%2F%CB%88tw%C9%9Bn.ti.%C9%99%CE%B8%2F"},{"id":"lv_5_395","topic":"Nature and Environmental Protection","word":"ultimately","pos":"(adv)","ipa":"/ˈʌl.tə.mət.li/","defVi":"cuối cùng, xét cho cùng","defEn":"in the end, after a process or series of events","examples":["The long and difficult negotiations [ultimately] led to a historic trade agreement. (=Dịch: Các cuộc đàm phán kéo dài và khó khăn cuối cùng đã dẫn đến một hiệp định thương mại lịch sử.)","Parents are [ultimately] responsible for their children's safety and well-being. (=Dịch: Xét cho cùng, cha mẹ là những người chịu trách nhiệm cho sự an toàn và hạnh phúc của con cái họ.)","The success of any business [ultimately] depends on customer satisfaction. (=Dịch: Sự thành công của bất kỳ doanh nghiệp nào cuối cùng cũng phụ thuộc vào sự hài lòng của khách hàng.)"],"ukAudio":"/ai_services/tts3/?q=ultimately&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t.li%2F","usAudio":"/ai_services/tts3/?q=ultimately&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t.li%2F"},{"id":"lv_5_396","topic":"Nature and Environmental Protection","word":"understandable","pos":"(adj)","ipa":"/ˌʌn.dɚˈstæn.də.bəl/","defVi":"dễ hiểu, có thể thông cảm được","defEn":"easy to comprehend or reasonable under the circumstances","examples":["His anger was completely [understandable] given the unfair treatment he received. (=Dịch: Sự tức giận của anh ấy là hoàn toàn có thể hiểu được nếu xét đến sự đối xử bất công mà anh ấy phải nhận.)","The professor presented complex theories in simple, [understandable] language. (=Dịch: Giáo sư đã trình bày các lý thuyết phức tạp bằng ngôn ngữ đơn giản, dễ hiểu.)","It is [understandable] that you feel nervous before a major presentation. (=Dịch: Việc bạn cảm thấy lo lắng trước một buổi thuyết trình quan trọng là điều dễ hiểu.)"],"ukAudio":"/ai_services/tts3/?q=understandable&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=understandable&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88st%C3%A6n.d%C9%99.b%C9%99l%2F"},{"id":"lv_5_397","topic":"Nature and Environmental Protection","word":"undertake","pos":"(v)","ipa":"/ˌʌn.dɚˈteɪk/","defVi":"đảm nhận, thực hiện, cam kết","defEn":"to commit oneself to and begin an enterprise or responsibility","examples":["The company will [undertake] a major research project next month. (=Dịch: Công ty sẽ thực hiện một dự án nghiên cứu lớn vào tháng tới.)","She was willing to [undertake] the responsibility of leading the team. (=Dịch: Cô ấy sẵn sàng đảm nhận trách nhiệm lãnh đạo đội ngũ.)","Doctors had to [undertake] a complex surgical procedure to save the patient. (=Dịch: Các bác sĩ đã phải thực hiện một ca phẫu thuật phức tạp để cứu bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=undertake&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=undertake&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88te%C9%AAk%2F"},{"id":"lv_5_398","topic":"Nature and Environmental Protection","word":"unknown","pos":"(adj)","ipa":"/ˌʌn.ˈnoʊn/","defVi":"Không rõ, chưa được biết đến, vô danh","defEn":"Not known, familiar, or identified.","examples":["The author of the mysterious manuscript remains [unknown]. (=Dịch: Tác giả của bản thảo bí ẩn vẫn chưa được biết đến.)","They decided to explore an [unknown] island in the Pacific. (=Dịch: Họ quyết định khám phá một hòn đảo chưa ai biết tới ở Thái Bình Dương.)","For reasons [unknown], the flight was delayed for three hours. (=Dịch: Vì những lý do không rõ, chuyến bay đã bị hoãn ba tiếng đồng hồ.)"],"ukAudio":"/ai_services/tts3/?q=unknown&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%CB%88no%CA%8An%2F","usAudio":"/ai_services/tts3/?q=unknown&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%CB%88no%CA%8An%2F"},{"id":"lv_5_399","topic":"Nature and Environmental Protection","word":"unpleasant","pos":"(adj)","ipa":"/ʌnˈplɛz.ənt/","defVi":"khó chịu, không vừa ý","defEn":"not enjoyable, attractive, or friendly; causing discomfort","examples":["An [unpleasant] smell was coming from the old refrigerator in the basement. (=Dịch: Một mùi khó chịu bốc ra từ chiếc tủ lạnh cũ dưới tầng hầm.)","He had an [unpleasant] argument with his colleague during the staff meeting. (=Dịch: Anh ấy đã có một cuộc tranh cãi khó chịu với đồng nghiệp trong cuộc họp nhân viên.)","Cold rain made the outdoor walking tour a rather [unpleasant] experience. (=Dịch: Cơn mưa lạnh đã khiến chuyến tham quan đi bộ ngoài trời trở thành một trải nghiệm khá khó chịu.)"],"ukAudio":"/ai_services/tts3/?q=unpleasant&lang=en-GB&ipa=%2F%CA%8Cn%CB%88pl%C9%9Bz.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=unpleasant&lang=en-US&ipa=%2F%CA%8Cn%CB%88pl%C9%9Bz.%C9%99nt%2F"},{"id":"lv_5_400","topic":"Nature and Environmental Protection","word":"unwanted","pos":"(adj)","ipa":"/ʌn.ˈwɑːn.tɪd/","defVi":"không mong muốn, thừa thãi","defEn":"not desired or needed","examples":["You can donate [unwanted] clothes to local charities. (=Dịch: Bạn có thể quyên góp quần áo không dùng đến cho các tổ chức từ thiện địa phương.)","The new filter helps block [unwanted] emails and spam. (=Dịch: Bộ lọc mới giúp chặn các email không mong muốn và thư rác.)","Noise pollution is an [unwanted] side effect of rapid urbanization. (=Dịch: Ô nhiễm tiếng ồn là một tác dụng phụ không mong muốn của quá trình đô thị hóa nhanh chóng.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn.%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn.%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_5_401","topic":"Nature and Environmental Protection","word":"vast","pos":"(adj)","ipa":"/væst/","defVi":"rộng lớn, bao la, khổng lồ","defEn":"extremely large in area, size, or amount","examples":["The Sahara Desert covers a [vast] area of northern Africa. (=Dịch: Sa mạc Sahara bao phủ một vùng diện tích rộng lớn ở Bắc Phi.)","A [vast] majority of students supported the new university policy. (=Dịch: Đại đa số sinh viên đã ủng hộ chính sách mới của trường đại học.)","He accumulated a [vast] amount of knowledge through years of reading. (=Dịch: Anh ấy đã tích lũy một lượng kiến thức khổng lồ qua nhiều năm đọc sách.)"],"ukAudio":"/ai_services/tts3/?q=vast&lang=en-GB&ipa=%2Fv%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=vast&lang=en-US&ipa=%2Fv%C3%A6st%2F"},{"id":"lv_5_402","topic":"Nature and Environmental Protection","word":"vegetation","pos":"(n)","ipa":"/ˌvedʒ.əˈteɪ.ʃən/","defVi":"thảm thực vật, cây cỏ","defEn":"plants in general, or the plants found in a particular area","examples":["Dense tropical [vegetation] covers the lower slopes of the mountain. (=Dịch: Thảm thực vật nhiệt đới rậm rạp bao phủ sườn dưới của ngọn núi.)","The desert has very little [vegetation] because of the severe lack of water. (=Dịch: Sa mạc có rất ít thực vật do tình trạng thiếu nước trầm trọng.)","Fires destroyed large areas of native [vegetation] across the national park. (=Dịch: Các vụ cháy đã phá hủy những vùng thảm thực vật bản địa rộng lớn trên khắp vườn quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=vegetation&lang=en-GB&ipa=%2F%CB%8Cved%CA%92.%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vegetation&lang=en-US&ipa=%2F%CB%8Cved%CA%92.%C9%99%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_5_403","topic":"Nature and Environmental Protection","word":"vessel","pos":"(n)","ipa":"/ˈves.əl/","defVi":"tàu thuyền lớn; bình đựng chất lỏng","defEn":"a large boat or ship; or a container designed to hold liquids","examples":["A large cargo [vessel] entered the harbor this morning. (=Dịch: Một chiếc tàu chở hàng lớn đã tiến vào cảng sáng nay.)","Blood [vessels] transport oxygen throughout the human body. (=Dịch: Các mạch máu vận chuyển oxy đi khắp cơ thể con người.)","The ancient ceramic [vessel] was displayed in the museum. (=Dịch: Bình gốm cổ đã được trưng bày trong viện bảo tàng.)"],"ukAudio":"/ai_services/tts3/?q=vessel&lang=en-GB&ipa=%2F%CB%88ves.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vessel&lang=en-US&ipa=%2F%CB%88ves.%C9%99l%2F"},{"id":"lv_5_404","topic":"Nature and Environmental Protection","word":"vet","pos":"(n)","ipa":"/vɛt/","defVi":"bác sĩ thú y","defEn":"a person qualified to treat diseased or injured animals; veterinarian","examples":["We took our sick dog to the [vet] for a checkup. (=Dịch: Chúng tôi đã đưa chú chó bị ốm đến bác sĩ thú y để kiểm tra.)","The [vet] prescribed antibiotics to treat the cat's infection. (=Dịch: Bác sĩ thú y đã kê đơn thuốc kháng sinh để điều trị nhiễm trùng cho con mèo.)","She has wanted to become a [vet] since she was a little girl. (=Dịch: Cô ấy đã muốn trở thành bác sĩ thú y từ khi còn là một cô bé.)"],"ukAudio":"/ai_services/tts3/?q=vet&lang=en-GB&ipa=%2Fv%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=vet&lang=en-US&ipa=%2Fv%C9%9Bt%2F"},{"id":"lv_5_405","topic":"Nature and Environmental Protection","word":"vital","pos":"(adj)","ipa":"/ˈvaɪ.təl/","defVi":"tối quan trọng, có tính sống còn","defEn":"necessary for success, life, or continued existence; extremely important","examples":["Regular exercise plays a [vital] role in maintaining good health. (=Dịch: Tập thể dục đều đặn đóng một vai trò tối quan trọng trong việc duy trì sức khỏe tốt.)","The paramedics checked the patient's [vital] signs immediately. (=Dịch: Các nhân viên y tế đã kiểm tra các dấu hiệu sinh tồn của bệnh nhân ngay lập tức.)","International cooperation is [vital] for tackling climate change. (=Dịch: Hợp tác quốc tế là yếu tố then chốt để giải quyết vấn đề biến đổi khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=vital&lang=en-GB&ipa=%2F%CB%88va%C9%AA.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vital&lang=en-US&ipa=%2F%CB%88va%C9%AA.t%C9%99l%2F"},{"id":"lv_5_406","topic":"Nature and Environmental Protection","word":"volcanic","pos":"(adj)","ipa":"/vɑːl.ˈkæn.ɪk/","defVi":"thuộc về núi lửa","defEn":"caused by, connected with, or produced by a volcano","examples":["The island was formed millions of years ago by [volcanic] activity. (=Dịch: Hòn đảo này được hình thành hàng triệu năm trước bởi hoạt động của núi lửa.)","Farmers benefit from the rich [volcanic] soil around the mountain. (=Dịch: Nông dân được hưởng lợi từ đất núi lửa màu mỡ xung quanh ngọn núi.)","Scientists closely monitor the [volcanic] crater for any signs of eruption. (=Dịch: Các nhà khoa học theo dõi chặt chẽ miệng núi lửa để phát hiện bất kỳ dấu hiệu phun trào nào.)"],"ukAudio":"/ai_services/tts3/?q=volcanic&lang=en-GB&ipa=%2Fv%C9%91%CB%90l.%CB%88k%C3%A6n.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=volcanic&lang=en-US&ipa=%2Fv%C9%91%CB%90l.%CB%88k%C3%A6n.%C9%AAk%2F"},{"id":"lv_5_407","topic":"Nature and Environmental Protection","word":"volcano","pos":"(n)","ipa":"/vɑlˈkeɪ.noʊ/","defVi":"núi lửa","defEn":"a mountain or hill with an opening through which lava, rock fragments, and gas erupt","examples":["The dormant [volcano] has not erupted for hundreds of years. (=Dịch: Ngọn núi lửa không hoạt động này đã không phun trào suốt hàng trăm năm qua.)","Tourists gathered safely to watch the active [volcano] emit smoke. (=Dịch: Du khách đã tụ tập an toàn để ngắm ngọn núi lửa đang hoạt động nhả khói.)","Ash from the [volcano] forced several international airports to close. (=Dịch: Tro bụi từ ngọn núi lửa đã buộc một số sân bay quốc tế phải đóng cửa.)"],"ukAudio":"/ai_services/tts3/?q=volcano&lang=en-GB&ipa=%2Fv%C9%91l%CB%88ke%C9%AA.no%CA%8A%2F","usAudio":"/ai_services/tts3/?q=volcano&lang=en-US&ipa=%2Fv%C9%91l%CB%88ke%C9%AA.no%CA%8A%2F"},{"id":"lv_5_408","topic":"Nature and Environmental Protection","word":"vulnerable","pos":"(adj)","ipa":"/ˈvʌl.nɚ.ə.bəl/","defVi":"dễ bị tổn thương, dễ gặp nguy hiểm","defEn":"susceptible to physical or emotional attack or harm","examples":["Young children and the elderly are particularly [vulnerable] to the flu virus. (=Dịch: Trẻ nhỏ và người cao tuổi đặc biệt dễ bị tổn thương bởi virus cúm.)","Coastal communities are increasingly [vulnerable] to rising sea levels. (=Dịch: Các cộng đồng ven biển ngày càng dễ bị ảnh hưởng trước tình trạng mực nước biển dâng cao.)","The company's computer network was [vulnerable] to cyberattacks. (=Dịch: Mạng máy tính của công ty rất dễ bị tấn công mạng.)"],"ukAudio":"/ai_services/tts3/?q=vulnerable&lang=en-GB&ipa=%2F%CB%88v%CA%8Cl.n%C9%9A.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=vulnerable&lang=en-US&ipa=%2F%CB%88v%CA%8Cl.n%C9%9A.%C9%99.b%C9%99l%2F"},{"id":"lv_5_409","topic":"Nature and Environmental Protection","word":"weigh","pos":"(v)","ipa":"/weɪ/","defVi":"cân (trọng lượng), cân nhắc","defEn":"to measure how heavy someone or something is, or to carefully consider something","examples":["The nurse will [weigh] the baby at each check-up. (=Dịch: Y tá sẽ cân em bé vào mỗi lần khám sức khỏe.)","You need to [weigh] the pros and cons before making a career change. (=Dịch: Bạn cần cân nhắc những mặt lợi và hại trước khi chuyển đổi nghề nghiệp.)","The packed suitcase cannot [weigh] more than twenty kilograms. (=Dịch: Chiếc vali đã đóng gói không được nặng quá hai mươi kilôgam.)"],"ukAudio":"/ai_services/tts3/?q=weigh&lang=en-GB&ipa=%2Fwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weigh&lang=en-US&ipa=%2Fwe%C9%AA%2F"},{"id":"lv_5_410","topic":"Nature and Environmental Protection","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪdˌsprɛd/","defVi":"lan rộng, phổ biến","defEn":"existing or happening over a large area or among many people","examples":["The new tax policy caused [widespread] public protest across the country. (=Dịch: Chính sách thuế mới đã gây ra sự phản đối rộng khắp của công chúng trên cả nước.)","Mobile phones have gained [widespread] acceptance as essential daily tools. (=Dịch: Điện thoại di động đã được chấp nhận rộng rãi như những công cụ thiết yếu hàng ngày.)","Deforestation leads to [widespread] loss of biodiversity. (=Dịch: Nạn phá rừng dẫn đến sự mất mát đa dạng sinh học trên diện rộng.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F"},{"id":"lv_5_411","topic":"Nature and Environmental Protection","word":"windy","pos":"(adj)","ipa":"/ˈwɪn.di/","defVi":"lộng gió, nhiều gió","defEn":"marked by strong or high winds","examples":["It was a cold and [windy] afternoon by the seaside. (=Dịch: Đó là một buổi chiều lạnh và nhiều gió bên bờ biển.)","Don't forget to wear a jacket because the weather forecast says it will be [windy]. (=Dịch: Đừng quên mặc áo khoác vì dự báo thời tiết nói trời sẽ nhiều gió.)","The plane landed safely despite the extremely [windy] conditions. (=Dịch: Chiếc máy bay đã hạ cánh an toàn bất chấp điều kiện gió thổi cực mạnh.)"],"ukAudio":"/ai_services/tts3/?q=windy&lang=en-GB&ipa=%2F%CB%88w%C9%AAn.di%2F","usAudio":"/ai_services/tts3/?q=windy&lang=en-US&ipa=%2F%CB%88w%C9%AAn.di%2F"},{"id":"lv_5_412","topic":"Nature and Environmental Protection","word":"wing","pos":"(n)","ipa":"/wɪŋ/","defVi":"Cánh (loài vật hoặc máy bay)","defEn":"One of the parts of the body that a bird, insect, or bat uses for flying, or a similar structure on an aircraft","examples":["The injured bird could not fly because its left [wing] was broken. (=Dịch: Con chim bị thương không thể bay vì cánh trái của nó bị gãy.)","The airplane tipped slightly to the right, dipping one [wing] toward the sea. (=Dịch: Chiếc máy bay hơi nghiêng sang phải, chúi một bên cánh về phía biển.)","A butterfly's [wing] is covered in microscopic scales that create vibrant colors. (=Dịch: Cánh bướm được bao phủ bởi những chiếc vảy siêu nhỏ tạo nên màu sắc rực rỡ.)"],"ukAudio":"/ai_services/tts3/?q=wing&lang=en-GB&ipa=%2Fw%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=wing&lang=en-US&ipa=%2Fw%C9%AA%C5%8B%2F"},{"id":"lv_5_413","topic":"Nature and Environmental Protection","word":"wipe","pos":"(v)","ipa":"/waɪp/","defVi":"lau, chùi","defEn":"to clean or dry something by moving a cloth or hand over it","examples":["Please [wipe] the table after you finish eating. (=Dịch: Làm ơn lau bàn sau khi bạn ăn xong.)","She used a handkerchief to [wipe] her tears. (=Dịch: Cô ấy dùng khăn tay để lau nước mắt.)","Don't forget to [wipe] your feet before entering the house. (=Dịch: Đừng quên chùi chân trước khi bước vào nhà.)"],"ukAudio":"/ai_services/tts3/?q=wipe&lang=en-GB&ipa=%2Fwa%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=wipe&lang=en-US&ipa=%2Fwa%C9%AAp%2F"},{"id":"lv_5_414","topic":"Nature and Environmental Protection","word":"wire","pos":"(n)","ipa":"/waɪər/","defVi":"dây kim loại, dây điện","defEn":"a thin, flexible thread of metal used to carry electricity or fasten things","examples":["Be careful not to touch that exposed electrical [wire]. (=Dịch: Hãy cẩn thận đừng chạm vào sợi dây điện bị hở đó.)","The fence was made of strong steel [wire]. (=Dịch: Hàng rào được làm bằng dây thép chắc chắn.)","He used a piece of [wire] to hang the picture on the wall. (=Dịch: Anh ấy đã dùng một đoạn dây kim loại để treo bức tranh lên tường.)"],"ukAudio":"/ai_services/tts3/?q=wire&lang=en-GB&ipa=%2Fwa%C9%AA%C9%99r%2F","usAudio":"/ai_services/tts3/?q=wire&lang=en-US&ipa=%2Fwa%C9%AA%C9%99r%2F"},{"id":"lv_5_415","topic":"Nature and Environmental Protection","word":"wooded","pos":"(adj)","ipa":"/ˈwʊd.ɪd/","defVi":"có nhiều cây cối, rậm rạp cây rừng","defEn":"covered with growing trees or woods","examples":["They decided to go for a peaceful hike along the [wooded] trail. (=Dịch: Họ quyết định đi bộ đường dài yên tĩnh dọc theo con đường mòn rợp bóng cây rừng.)","The cabin was hidden deep in a [wooded] valley. (=Dịch: Túp lều được ẩn sâu trong một thung lũng rậm rạp cây cối.)","Many rare bird species find shelter in these [wooded] hills. (=Dịch: Nhiều loài chim quý hiếm tìm nơi trú ẩn trong những ngọn đồi nhiều cây cối này.)"],"ukAudio":"/ai_services/tts3/?q=wooded&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=wooded&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.%C9%AAd%2F"},{"id":"lv_5_416","topic":"Nature and Environmental Protection","word":"woodwork","pos":"(n)","ipa":"/ˈwʊd.wɜrk/","defVi":"đồ gỗ, công việc mộc","defEn":"the parts of a building or room made of wood, or the activity of making items from wood","examples":["The old house features beautiful handcrafted [woodwork]. (=Dịch: Ngôi nhà cổ có các chi tiết đồ gỗ thủ công tuyệt đẹp.)","He decided to take an evening class to learn [woodwork]. (=Dịch: Anh ấy quyết định tham gia một lớp học buổi tối để học làm mộc.)","We need to repaint the [woodwork] around the window frames. (=Dịch: Chúng tôi cần sơn lại phần khung gỗ quanh các cửa sổ.)"],"ukAudio":"/ai_services/tts3/?q=woodwork&lang=en-GB&ipa=%2F%CB%88w%CA%8Ad.w%C9%9Crk%2F","usAudio":"/ai_services/tts3/?q=woodwork&lang=en-US&ipa=%2F%CB%88w%CA%8Ad.w%C9%9Crk%2F"},{"id":"lv_5_417","topic":"Nature and Environmental Protection","word":"woolly","pos":"(adj)","ipa":"/ˈwʊl.i/","defVi":"làm bằng len, có lông như len; mơ hồ (ý nghĩ)","defEn":"made of or resembling wool; vague or unclear in thinking","examples":["She wore a warm [woolly] scarf to protect herself from the winter cold. (=Dịch: Cô ấy đã quàng một chiếc khăn len ấm áp để bảo vệ mình khỏi cái lạnh mùa đông.)","The sheep had thick, [woolly] coats after a season on the pasture. (=Dịch: Những con cừu có bộ lông len dày sau một mùa trên đồng cỏ.)","His argument was too [woolly] to convince the examination panel. (=Dịch: Lập luận của anh ấy quá mơ hồ để có thể thuyết phục được hội đồng chấm thi.)"],"ukAudio":"/ai_services/tts3/?q=woolly&lang=en-GB&ipa=%2F%CB%88w%CA%8Al.i%2F","usAudio":"/ai_services/tts3/?q=woolly&lang=en-US&ipa=%2F%CB%88w%CA%8Al.i%2F"},{"id":"lv_5_418","topic":"Nature and Environmental Protection","word":"worm","pos":"(n)","ipa":"/wɜːrm/","defVi":"con giun, sâu","defEn":"a small animal with a long, soft body and no legs, often living underground","examples":["Birds often look for a [worm] in the grass after the rain. (=Dịch: Chim thường tìm giun trong bãi cỏ sau cơn mưa.)","The gardener noticed a [worm] wriggling through the rich soil. (=Dịch: Người làm vườn nhận thấy một con giun đang ngoe nguẩy trong lớp đất màu mỡ.)","Fishermen frequently use a [worm] as bait to catch freshwater fish. (=Dịch: Những người câu cá thường dùng giun làm mồi để bắt cá nước ngọt.)"],"ukAudio":"/ai_services/tts3/?q=worm&lang=en-GB&ipa=%2Fw%C9%9C%CB%90rm%2F","usAudio":"/ai_services/tts3/?q=worm&lang=en-US&ipa=%2Fw%C9%9C%CB%90rm%2F"},{"id":"lv_5_419","topic":"Nature and Environmental Protection","word":"yam","pos":"(n)","ipa":"/jæm/","defVi":"củ khoai mỡ, củ từ hoặc khoai lang","defEn":"an edible starchy root of a climbing plant, often similar to a sweet potato","examples":["Roasted [yam] is a popular side dish in many traditional autumn meals. (=Dịch: Khoai mỡ nướng là một món ăn kèm phổ biến trong nhiều bữa ăn mùa thu truyền thống.)","The farmer harvested a large crop of [yam] before the rainy season began. (=Dịch: Người nông dân đã thu hoạch một vụ mùa củ từ lớn trước khi mùa mưa bắt đầu.)","She made a delicious dessert using mashed [yam] and coconut milk. (=Dịch: Cô ấy đã làm một món tráng miệng thơm ngon bằng khoai mỡ nghiền và nước cốt dừa.)"],"ukAudio":"/ai_services/tts3/?q=yam&lang=en-GB&ipa=%2Fj%C3%A6m%2F","usAudio":"/ai_services/tts3/?q=yam&lang=en-US&ipa=%2Fj%C3%A6m%2F"},{"id":"lv_5_420","topic":"Nature and Environmental Protection","word":"zero","pos":"(n)","ipa":"/ˈzɪr.oʊ/","defVi":"số không, không có gì","defEn":"the number 0, or an amount that is none at all","examples":["The temperature dropped to [zero] degrees last night. (=Dịch: Nhiệt độ đã giảm xuống mức không độ vào đêm qua.)","He started the business with [zero] experience in sales. (=Dịch: Anh ấy bắt đầu công việc kinh doanh với con số không về kinh nghiệm bán hàng.)","Our chances of winning the game are close to [zero]. (=Dịch: Cơ hội chiến thắng trận đấu của chúng tôi gần như bằng không.)"],"ukAudio":"/ai_services/tts3/?q=zero&lang=en-GB&ipa=%2F%CB%88z%C9%AAr.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=zero&lang=en-US&ipa=%2F%CB%88z%C9%AAr.o%CA%8A%2F"},{"id":"lv_5_421","topic":"Nature and Environmental Protection","word":"zone","pos":"(n)","ipa":"/zoʊn/","defVi":"khu vực, vành đai, vùng","defEn":"an area with particular characteristics or purpose","examples":["Drivers must slow down when entering a school [zone]. (=Dịch: Các tài xế phải giảm tốc độ khi đi vào khu vực trường học.)","The city created a pedestrian [zone] in the historic center. (=Dịch: Thành phố đã tạo ra một phố đi bộ ở trung tâm lịch sử.)","Plants grow differently depending on their climate [zone]. (=Dịch: Cây cối phát triển khác nhau tùy thuộc vào đới khí hậu của chúng.)"],"ukAudio":"/ai_services/tts3/?q=zone&lang=en-GB&ipa=%2Fzo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=zone&lang=en-US&ipa=%2Fzo%CA%8An%2F"}]},"rawTopic":"Nature and Environmental Protection"},{"id":"listening_u5_7","title":"Chủ đề 7/10: Business and Humanities Studies","actTitle":"Từ vựng chủ đề: Business and Humanities Studies (241 từ)","problem":{"pType":"topic_flashcards","topic":"Business and Humanities Studies","count":241,"words":[{"id":"lv_6_0","topic":"Business and Humanities Studies","word":"absence","pos":"(n)","ipa":"/ˈæb.səns/","defVi":"sự vắng mặt, sự thiếu vắng","defEn":"the state of being away from a place or not existing","examples":["Repeated [absence] from classes will negatively affect your final grade. (=Dịch: Việc vắng mặt nhiều lần trong các buổi học sẽ ảnh hưởng xấu đến điểm số cuối kỳ của bạn.)","In the [absence] of more evidence, the police could not proceed with the case. (=Dịch: Do thiếu bằng chứng, cảnh sát đã không thể tiếp tục vụ án.)","Her long [absence] made her realize how much she missed her family. (=Dịch: Sự xa cách lâu ngày khiến cô nhận ra mình nhớ gia đình đến nhường nào.)"],"ukAudio":"/ai_services/tts3/?q=absence&lang=en-GB&ipa=%2F%CB%88%C3%A6b.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=absence&lang=en-US&ipa=%2F%CB%88%C3%A6b.s%C9%99ns%2F"},{"id":"lv_6_1","topic":"Business and Humanities Studies","word":"acquire","pos":"(v)","ipa":"/əˈkwaɪ.ɚ/","defVi":"đạt được, thu được, mua lại","defEn":"to gain, get, or obtain something through effort or purchase","examples":["Living abroad helped her [acquire] fluent English skills. (=Dịch: Sống ở nước ngoài đã giúp cô ấy tiếp thu được khả năng tiếng Anh lưu loát.)","The tech giant plans to [acquire] a promising startup. (=Dịch: Tập đoàn công nghệ lớn dự định mua lại một công ty khởi nghiệp đầy triển vọng.)","It takes patience to [acquire] in-depth knowledge of finance. (=Dịch: Cần có sự kiên nhẫn để tích lũy kiến thức sâu rộng về tài chính.)"],"ukAudio":"/ai_services/tts3/?q=acquire&lang=en-GB&ipa=%2F%C9%99%CB%88kwa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=acquire&lang=en-US&ipa=%2F%C9%99%CB%88kwa%C9%AA.%C9%9A%2F"},{"id":"lv_6_2","topic":"Business and Humanities Studies","word":"administrator","pos":"(n)","ipa":"/ədˈmɪn.ə.streɪ.t̬ɚ/","defVi":"quản trị viên, người quản lý","defEn":"a person whose job is to manage and organize the work of a company or organization","examples":["The school [administrator] introduced several new policies this semester. (=Dịch: Người quản lý trường học đã đưa ra một số chính sách mới trong học kỳ này.)","Please contact the system [administrator] if you cannot log into your account. (=Dịch: Vui lòng liên hệ với quản trị viên hệ thống nếu bạn không thể đăng nhập vào tài khoản của mình.)","She has worked as a hospital [administrator] for over a decade. (=Dịch: Cô ấy đã làm việc với tư cách là người quản lý bệnh viện trong hơn một thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=administrator&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=administrator&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAn.%C9%99.stre%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_6_3","topic":"Business and Humanities Studies","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"chấp nhận, áp dụng, thông qua (kế hoạch/phương pháp)","defEn":"to choose to follow or use a particular idea, method, or policy","examples":["Many schools plan to [adopt] modern technology in their classrooms next year. (=Dịch: Nhiều trường học dự định áp dụng công nghệ hiện đại vào lớp học vào năm tới.)","The government decided to [adopt] stricter environmental regulations. (=Dịch: Chính phủ đã quyết định thông qua các quy định môi trường nghiêm ngặt hơn.)","You should [adopt] a healthier diet to improve your overall wellbeing. (=Dịch: Bạn nên áp dụng một chế độ ăn uống lành mạnh hơn để nâng cao sức khỏe toàn diện.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_6_4","topic":"Business and Humanities Studies","word":"affair","pos":"(n)","ipa":"/əˈfer/","defVi":"sự việc, công việc, vấn đề","defEn":"an event, situation, or matter of public or personal concern","examples":["The Ministry of Foreign Affairs deals with international diplomatic relations. (=Dịch: Bộ Ngoại giao xử lý các mối quan hệ ngoại giao quốc tế.)","The wedding was a lavish [affair] attended by hundreds of guests. (=Dịch: Lễ cưới là một sự kiện xa hoa với sự tham dự của hàng trăm khách mời.)","She prefers to keep her private life a personal [affair]. (=Dịch: Cô ấy thích giữ đời sống riêng tư là chuyện cá nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=affair&lang=en-GB&ipa=%2F%C9%99%CB%88fer%2F","usAudio":"/ai_services/tts3/?q=affair&lang=en-US&ipa=%2F%C9%99%CB%88fer%2F"},{"id":"lv_6_5","topic":"Business and Humanities Studies","word":"allocate","pos":"(v)","ipa":"/ˈæl.ə.keɪt/","defVi":"phân bổ, phân chia (ngân sách, nguồn lực)","defEn":"to officially give something to someone, or to decide that something will be used for a specific purpose","examples":["The local government decided to [allocate] more funds to public healthcare. (=Dịch: Chính quyền địa phương đã quyết định phân bổ thêm kinh phí cho y tế công cộng.)","Project managers must carefully [allocate] resources to ensure deadlines are met. (=Dịch: Các nhà quản lý dự án phải phân bổ nguồn lực một cách cẩn thận để đảm bảo đúng tiến độ.)","We need to [allocate] specific duties to each team member before starting the campaign. (=Dịch: Chúng ta cần phân công nhiệm vụ cụ thể cho từng thành viên trong nhóm trước khi bắt đầu chiến dịch.)"],"ukAudio":"/ai_services/tts3/?q=allocate&lang=en-GB&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=allocate&lang=en-US&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F"},{"id":"lv_6_6","topic":"Business and Humanities Studies","word":"ant","pos":"(n)","ipa":"/ænt/","defVi":"con kiến","defEn":"a small insect that lives in highly organized social colonies","examples":["A tiny [ant] can carry objects many times heavier than its own body. (=Dịch: Một con kiến nhỏ bé có thể vác những vật nặng gấp nhiều lần cơ thể nó.)","We noticed a trail of [ant]s marching toward the spilled sugar on the table. (=Dịch: Chúng tôi nhận thấy một hàng kiến đang bò về phía chỗ đường bị đổ trên bàn.)","The behavior of an [ant] colony is often studied by biologists to understand teamwork. (=Dịch: Hành vi của một đàn kiến thường được các nhà sinh vật học nghiên cứu để hiểu về sự làm việc nhóm.)"],"ukAudio":"/ai_services/tts3/?q=ant&lang=en-GB&ipa=%2F%C3%A6nt%2F","usAudio":"/ai_services/tts3/?q=ant&lang=en-US&ipa=%2F%C3%A6nt%2F"},{"id":"lv_6_7","topic":"Business and Humanities Studies","word":"anxiety","pos":"(n)","ipa":"/æŋˈzaɪ.ə.t̬i/","defVi":"sự lo âu, nỗi lo lắng","defEn":"a feeling of worry, nervousness, or unease about something","examples":["Many students suffer from acute [anxiety] before taking major exams. (=Dịch: Nhiều học sinh phải chịu đựng nỗi lo âu tột độ trước khi bước vào các kỳ thi lớn.)","Regular exercise is an effective way to reduce stress and [anxiety]. (=Dịch: Tập thể dục thường xuyên là một cách hiệu quả để giảm bớt căng thẳng và lo lắng.)","Her [anxiety] grew as the deadline for the final project approached. (=Dịch: Nỗi lo của cô ấy ngày càng tăng khi hạn chót nộp dự án cuối kỳ đến gần.)"],"ukAudio":"/ai_services/tts3/?q=anxiety&lang=en-GB&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=anxiety&lang=en-US&ipa=%2F%C3%A6%C5%8B%CB%88za%C9%AA.%C9%99.t%CC%ACi%2F"},{"id":"lv_6_8","topic":"Business and Humanities Studies","word":"ape","pos":"(n)","ipa":"/eɪp/","defVi":"loài vượn, loài linh trưởng không đuôi","defEn":"a large primate without a tail, such as a chimpanzee, gorilla, or orangutan","examples":["The chimpanzee is considered one of the most intelligent species of [ape]. (=Dịch: Tinh tinh được coi là một trong những loài vượn thông minh nhất.)","Scientists study the behavior of the [ape] to learn more about human evolution. (=Dịch: Các nhà khoa học nghiên cứu hành vi của loài vượn để tìm hiểu thêm về sự tiến hóa của loài người.)","The sanctuary provides a safe natural habitat for rescued [ape]s. (=Dịch: Khu bảo tồn cung cấp một môi trường sống tự nhiên an toàn cho những cá thể vượn được giải cứu.)"],"ukAudio":"/ai_services/tts3/?q=ape&lang=en-GB&ipa=%2Fe%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=ape&lang=en-US&ipa=%2Fe%C9%AAp%2F"},{"id":"lv_6_9","topic":"Business and Humanities Studies","word":"arena","pos":"(n)","ipa":"/əˈriː.nə/","defVi":"đấu trường, vũ đài","defEn":"a level area surrounded by seating, used for sports or entertainment, or a sphere of activity","examples":["Thousands of fans gathered at the sports [arena] to watch the final match. (=Dịch: Hàng ngàn người hâm mộ đã tập trung tại nhà thi đấu thể thao để xem trận chung kết.)","She is preparing to enter the political [arena] in the upcoming election. (=Dịch: Cô ấy đang chuẩn bị bước vào vũ đài chính trị trong cuộc bầu cử sắp tới.)","The new indoor [arena] will host international music concerts. (=Dịch: Nhà thi đấu trong nhà mới sẽ là nơi tổ chức các buổi hòa nhạc quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=arena&lang=en-GB&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F","usAudio":"/ai_services/tts3/?q=arena&lang=en-US&ipa=%2F%C9%99%CB%88ri%CB%90.n%C9%99%2F"},{"id":"lv_6_10","topic":"Business and Humanities Studies","word":"arise","pos":"(v)","ipa":"/əˈraɪz/","defVi":"nảy sinh, phát sinh","defEn":"to happen or begin to exist, especially a problem or situation","examples":["Unexpected problems can [arise] during the early stages of a project. (=Dịch: Những vấn đề bất ngờ có thể phát sinh trong các giai đoạn đầu của một dự án.)","New opportunities often [arise] when you step outside your comfort zone. (=Dịch: Những cơ hội mới thường xuất hiện khi bạn bước ra khỏi vùng an toàn của mình.)","Disputes may [arise] if the terms of the contract are not clear. (=Dịch: Tranh chấp có thể nảy sinh nếu các điều khoản của hợp đồng không rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=arise&lang=en-GB&ipa=%2F%C9%99%CB%88ra%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=arise&lang=en-US&ipa=%2F%C9%99%CB%88ra%C9%AAz%2F"},{"id":"lv_6_11","topic":"Business and Humanities Studies","word":"assess","pos":"(v)","ipa":"/əˈsɛs/","defVi":"đánh giá, định mức","defEn":"to judge or decide the amount, value, quality, or importance of something","examples":["The committee will [assess] the environmental impact of the new highway project. (=Dịch: Ủy ban sẽ đánh giá tác động môi trường của dự án đường cao tốc mới.)","Teachers use regular tests to [assess] students' progress throughout the semester. (=Dịch: Giáo viên sử dụng các bài kiểm tra định kỳ để đánh giá sự tiến bộ của học sinh trong suốt học kỳ.)","It is difficult to [assess] the true cost of the damage caused by the flood. (=Dịch: Rất khó để đánh giá thiệt hại thực tế do trận lũ lụt gây ra.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%9Bs%2F"},{"id":"lv_6_12","topic":"Business and Humanities Studies","word":"assist","pos":"(v)","ipa":"/əˈsɪst/","defVi":"giúp đỡ, hỗ trợ","defEn":"to help someone to do something","examples":["The teacher will [assist] students who are struggling with math. (=Dịch: Giáo viên sẽ giúp đỡ những học sinh đang gặp khó khăn với môn toán.)","Smart software can [assist] doctors in diagnosing rare diseases. (=Dịch: Phần mềm thông minh có thể hỗ trợ các bác sĩ trong việc chẩn đoán các căn bệnh hiếm gặp.)","Volunteers arrived at the scene to [assist] with the rescue operation. (=Dịch: Các tình nguyện viên đã đến hiện trường để hỗ trợ công tác cứu hộ.)"],"ukAudio":"/ai_services/tts3/?q=assist&lang=en-GB&ipa=%2F%C9%99%CB%88s%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=assist&lang=en-US&ipa=%2F%C9%99%CB%88s%C9%AAst%2F"},{"id":"lv_6_13","topic":"Business and Humanities Studies","word":"assumption","pos":"(n)","ipa":"/əˈsʌmp.ʃən/","defVi":"giả định, sự suy đoán","defEn":"something that you accept as true without having proof","examples":["His business plan was based on the false [assumption] that prices would stay low. (=Dịch: Kế hoạch kinh doanh của anh ấy dựa trên giả định sai lầm rằng giá cả sẽ duy trì ở mức thấp.)","We should not make any [assumptions] before reviewing all the evidence. (=Dịch: Chúng ta không nên đưa ra bất kỳ giả định nào trước khi xem xét mọi bằng chứng.)","The research challenges the traditional [assumption] about how memory works. (=Dịch: Nghiên cứu này thách thức giả định truyền thống về cách hoạt động của trí nhớ.)"],"ukAudio":"/ai_services/tts3/?q=assumption&lang=en-GB&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=assumption&lang=en-US&ipa=%2F%C9%99%CB%88s%CA%8Cmp.%CA%83%C9%99n%2F"},{"id":"lv_6_14","topic":"Business and Humanities Studies","word":"autism","pos":"(n)","ipa":"/ˈɔˌtɪz.əm/","defVi":"chứng tự kỷ","defEn":"a brain condition that affects how a person communicates and interacts with others","examples":["Children with [autism] often find social interaction challenging. (=Dịch: Trẻ mắc chứng tự kỷ thường cảm thấy việc tương tác xã hội là một thử thách.)","Early diagnosis of [autism] can significantly improve a child's development. (=Dịch: Việc chẩn đoán sớm chứng tự kỷ có thể cải thiện đáng kể sự phát triển của trẻ.)","The charity aims to raise awareness about [autism] in schools. (=Dịch: Tổ chức từ thiện nhằm nâng cao nhận thức về chứng tự kỷ trong các trường học.)"],"ukAudio":"/ai_services/tts3/?q=autism&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%8Ct%C9%AAz.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=autism&lang=en-US&ipa=%2F%CB%88%C9%94%CB%8Ct%C9%AAz.%C9%99m%2F"},{"id":"lv_6_15","topic":"Business and Humanities Studies","word":"belief","pos":"(n)","ipa":"/bɪˈlif/","defVi":"niềm tin, tín ngưỡng","defEn":"an acceptance that something exists or is true, especially without proof","examples":["It is a common [belief] that eating healthy food improves mental health. (=Dịch: Mọi người thường có niềm tin rằng ăn uống lành mạnh sẽ cải thiện sức khỏe tinh thần.)","His religious [belief] guides all his moral decisions in life. (=Dịch: Tín ngưỡng tôn giáo dẫn đường cho mọi quyết định đạo đức của anh ấy trong cuộc sống.)","She has a firm [belief] in her ability to succeed despite the odds. (=Dịch: Cô ấy có niềm tin vững chắc vào khả năng thành công của mình bất chấp mọi khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=belief&lang=en-GB&ipa=%2Fb%C9%AA%CB%88lif%2F","usAudio":"/ai_services/tts3/?q=belief&lang=en-US&ipa=%2Fb%C9%AA%CB%88lif%2F"},{"id":"lv_6_16","topic":"Business and Humanities Studies","word":"beneficial","pos":"(adj)","ipa":"/ˌben.əˈfɪʃ.əl/","defVi":"có lợi, hữu ích","defEn":"having a good or helpful effect on someone or something","examples":["Regular physical activity is highly [beneficial] for cardiovascular health. (=Dịch: Hoạt động thể chất thường xuyên rất có lợi cho sức khỏe tim mạch.)","The trade agreement proved [beneficial] to both participating nations. (=Dịch: Hiệp định thương mại đã chứng minh là có lợi cho cả hai quốc gia tham gia.)","Learning a second language is [beneficial] for cognitive development. (=Dịch: Học ngôn ngữ thứ hai rất hữu ích cho sự phát triển nhận thức.)"],"ukAudio":"/ai_services/tts3/?q=beneficial&lang=en-GB&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=beneficial&lang=en-US&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_6_17","topic":"Business and Humanities Studies","word":"blame","pos":"(v)","ipa":"/bleɪm/","defVi":"đổ lỗi, khiển trách, quy trách nhiệm","defEn":"to hold someone or something responsible for a fault or wrong action","examples":["Don't [blame] him for a mistake he did not make. (=Dịch: Đừng đổ lỗi cho anh ấy về một sai lầm mà anh ấy không phạm phải.)","Many scientists [blame] human activity for the rapid climate change. (=Dịch: Nhiều nhà khoa học quy trách nhiệm cho hoạt động của con người về sự biến đổi khí hậu nhanh chóng.)","She refused to [blame] others when the project failed. (=Dịch: Cô ấy từ chối đổ lỗi cho người khác khi dự án thất bại.)"],"ukAudio":"/ai_services/tts3/?q=blame&lang=en-GB&ipa=%2Fble%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=blame&lang=en-US&ipa=%2Fble%C9%AAm%2F"},{"id":"lv_6_18","topic":"Business and Humanities Studies","word":"blanket","pos":"(n)","ipa":"/ˈblæŋ.kɪt/","defVi":"chăn, mền","defEn":"a large piece of warm fabric used as a covering on a bed","examples":["She wrapped a warm [blanket] around her shoulders because the room was cold. (=Dịch: Cô ấy quàng một chiếc chăn ấm qua vai vì căn phòng rất lạnh.)","A thick [blanket] of snow covered the entire village overnight. (=Dịch: Một lớp tuyết dày đã bao phủ toàn bộ ngôi làng qua đêm.)","We spread a picnic [blanket] on the grass and enjoyed our lunch. (=Dịch: Chúng tôi trải một tấm thảm dã ngoại trên bãi cỏ và thưởng thức bữa trưa.)"],"ukAudio":"/ai_services/tts3/?q=blanket&lang=en-GB&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=blanket&lang=en-US&ipa=%2F%CB%88bl%C3%A6%C5%8B.k%C9%AAt%2F"},{"id":"lv_6_19","topic":"Business and Humanities Studies","word":"brand","pos":"(n)","ipa":"/brænd/","defVi":"thương hiệu, nhãn hàng","defEn":"a type of product made by a particular company under a particular name","examples":["Apple is one of the most recognizable [brand] names in the world. (=Dịch: Apple là một trong những tên thương hiệu dễ nhận biết nhất trên thế giới.)","Consumers often stay loyal to a trusted [brand] despite price increases. (=Dịch: Người tiêu dùng thường trung thành với một thương hiệu đáng tin cậy dù giá có tăng.)","The company is launching a new [brand] of organic skincare products. (=Dịch: Công ty đang ra mắt một dòng nhãn hàng mỹ phẩm hữu cơ mới.)"],"ukAudio":"/ai_services/tts3/?q=brand&lang=en-GB&ipa=%2Fbr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=brand&lang=en-US&ipa=%2Fbr%C3%A6nd%2F"},{"id":"lv_6_20","topic":"Business and Humanities Studies","word":"calculate","pos":"(v)","ipa":"/ˈkæl.kjə.leɪt/","defVi":"tính toán, dự liệu","defEn":"to determine something mathematically or evaluate an outcome carefully","examples":["You can use this online tool to [calculate] your monthly mortgage payments. (=Dịch: Bạn có thể sử dụng công cụ trực tuyến này để tính toán các khoản thanh toán thế chấp hàng tháng của mình.)","Scientists are trying to [calculate] the exact trajectory of the asteroid. (=Dịch: Các nhà khoa học đang cố gắng tính toán quỹ đạo chính xác của tiểu hành tinh.)","The manager took time to [calculate] the potential risks before approving the project. (=Dịch: Người quản lý đã dành thời gian để tính toán những rủi ro tiềm ẩn trước khi phê duyệt dự án.)"],"ukAudio":"/ai_services/tts3/?q=calculate&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.kj%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=calculate&lang=en-US&ipa=%2F%CB%88k%C3%A6l.kj%C9%99.le%C9%AAt%2F"},{"id":"lv_6_21","topic":"Business and Humanities Studies","word":"campsite","pos":"(n)","ipa":"/ˈkæmp.saɪt/","defVi":"khu cắm trại, địa điểm cắm trại","defEn":"a piece of land where people on holiday can pitch a tent or park a camper","examples":["We found a peaceful [campsite] near the edge of the lake. (=Dịch: Chúng tôi tìm thấy một địa điểm cắm trại yên bình gần bờ hồ.)","The [campsite] offers basic facilities such as running water and showers. (=Dịch: Khu cắm trại cung cấp các tiện nghi cơ bản như nước máy và phòng tắm vòi sen.)","You need to book your spot at the [campsite] several months in advance. (=Dịch: Bạn cần phải đặt chỗ tại khu cắm trại trước vài tháng.)"],"ukAudio":"/ai_services/tts3/?q=campsite&lang=en-GB&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=campsite&lang=en-US&ipa=%2F%CB%88k%C3%A6mp.sa%C9%AAt%2F"},{"id":"lv_6_22","topic":"Business and Humanities Studies","word":"caring","pos":"(adj)","ipa":"/ˈker.ɪŋ/","defVi":"chu đáo, giàu lòng quan tâm chăm sóc","defEn":"kind, affectionate, and showing concern for the needs of others","examples":["She is a [caring] teacher who always pays attention to her students' feelings. (=Dịch: Cô ấy là một giáo viên chu đáo, luôn để ý đến cảm xúc của học sinh.)","The elderly woman was grateful for her [caring] neighbors. (=Dịch: Bà cụ rất biết ơn những người hàng xóm biết quan tâm giúp đỡ của mình.)","Working in healthcare requires a patient and [caring] attitude. (=Dịch: Làm việc trong ngành y tế đòi hỏi một thái độ kiên nhẫn và giàu tình thương.)"],"ukAudio":"/ai_services/tts3/?q=caring&lang=en-GB&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=caring&lang=en-US&ipa=%2F%CB%88ker.%C9%AA%C5%8B%2F"},{"id":"lv_6_23","topic":"Business and Humanities Studies","word":"category","pos":"(n)","ipa":"/ˈkæ.t̬ə.ɡɔːr.i/","defVi":"hạng, loại, nhóm","defEn":"a class or division of people or things having particular shared characteristics","examples":["The competition is divided into three age [category] groups. (=Dịch: Cuộc thi được chia thành ba nhóm theo hạng tuổi.)","Books in the library are arranged neatly by [category]. (=Dịch: Sách trong thư viện được sắp xếp ngăn nắp theo từng thể loại.)","This documentary falls into the [category] of environmental science. (=Dịch: Bộ phim tài liệu này thuộc thể loại khoa học môi trường.)"],"ukAudio":"/ai_services/tts3/?q=category&lang=en-GB&ipa=%2F%CB%88k%C3%A6.t%CC%AC%C9%99.%C9%A1%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=category&lang=en-US&ipa=%2F%CB%88k%C3%A6.t%CC%AC%C9%99.%C9%A1%C9%94%CB%90r.i%2F"},{"id":"lv_6_24","topic":"Business and Humanities Studies","word":"cell","pos":"(n)","ipa":"/sɛl/","defVi":"tế bào","defEn":"the smallest basic unit of a plant or animal","examples":["The microscope allowed the students to see a single plant [cell] clearly. (=Dịch: Kính hiển vi đã cho phép học sinh nhìn thấy rõ một tế bào thực vật đơn lẻ.)","Cancer occurs when an abnormal [cell] begins to divide uncontrollably. (=Dịch: Ung thư xảy ra khi một tế bào bất thường bắt đầu phân chia mất kiểm soát.)","Red blood [cell] production takes place mainly inside the bone marrow. (=Dịch: Quá trình sản sinh tế bào hồng cầu diễn ra chủ yếu bên trong tủy xương.)"],"ukAudio":"/ai_services/tts3/?q=cell&lang=en-GB&ipa=%2Fs%C9%9Bl%2F","usAudio":"/ai_services/tts3/?q=cell&lang=en-US&ipa=%2Fs%C9%9Bl%2F"},{"id":"lv_6_25","topic":"Business and Humanities Studies","word":"ceo","pos":"(n)","ipa":"/ˌsiː.iːˈoʊ/","defVi":"tổng giám đốc điều hành","defEn":"the highest-ranking person in a company or other institution","examples":["The [CEO] announced a major restructuring plan during the annual meeting. (=Dịch: Tổng giám đốc điều hành đã công bố kế hoạch tái cấu trúc lớn trong cuộc họp thường niên.)","She worked her way up through the ranks to become the company's first female [CEO]. (=Dịch: Cô đã nỗ lực thăng tiến qua nhiều vị trí để trở thành nữ tổng giám đốc điều hành đầu tiên của công ty.)","Investors questioned the [CEO] about falling profits in the latest quarter. (=Dịch: Các nhà đầu tư đã chất vấn tổng giám đốc điều hành về sự sụt giảm lợi nhuận trong quý gần nhất.)"],"ukAudio":"/ai_services/tts3/?q=ceo&lang=en-GB&ipa=%2F%CB%8Csi%CB%90.i%CB%90%CB%88o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=ceo&lang=en-US&ipa=%2F%CB%8Csi%CB%90.i%CB%90%CB%88o%CA%8A%2F"},{"id":"lv_6_26","topic":"Business and Humanities Studies","word":"characteristic","pos":"(n)","ipa":"/ˌker.ək.təˈrɪs.tɪk/","defVi":"đặc điểm, nét đặc trưng","defEn":"a typical feature or quality that someone or something has","examples":["Patience is an essential [characteristic] of a good teacher. (=Dịch: Kiên nhẫn là một đặc điểm thiết yếu của một giáo viên giỏi.)","A common [characteristic] of this disease is extreme fatigue. (=Dịch: Một đặc điểm chung của căn bệnh này là tình trạng mệt mỏi cùng cực.)","Each region has its own architectural [characteristic] that reflects its heritage. (=Dịch: Mỗi vùng miền đều có nét đặc trưng kiến trúc riêng phản ánh di sản của nơi đó.)"],"ukAudio":"/ai_services/tts3/?q=characteristic&lang=en-GB&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=characteristic&lang=en-US&ipa=%2F%CB%8Cker.%C9%99k.t%C9%99%CB%88r%C9%AAs.t%C9%AAk%2F"},{"id":"lv_6_27","topic":"Business and Humanities Studies","word":"chief","pos":"(adj)","ipa":"/tʃiːf/","defVi":"chính, chủ yếu, quan trọng nhất","defEn":"most important or main","examples":["Unemployment was the [chief] topic of discussion at the economic summit. (=Dịch: Thất nghiệp là chủ đề thảo luận chính tại hội nghị thượng đỉnh kinh tế.)","The [chief] cause of air pollution in the city is heavy traffic. (=Dịch: Nguyên nhân chủ yếu gây ô nhiễm không khí trong thành phố là lưu lượng giao thông đông đúc.)","Her [chief] responsibility is to oversee daily operations in the factory. (=Dịch: Trách nhiệm chính của cô ấy là giám sát các hoạt động hàng ngày trong nhà máy.)"],"ukAudio":"/ai_services/tts3/?q=chief&lang=en-GB&ipa=%2Ft%CA%83i%CB%90f%2F","usAudio":"/ai_services/tts3/?q=chief&lang=en-US&ipa=%2Ft%CA%83i%CB%90f%2F"},{"id":"lv_6_28","topic":"Business and Humanities Studies","word":"cognitive","pos":"(adj)","ipa":"/ˈkɑɡ.nə.tɪv/","defVi":"thuộc về nhận thức","defEn":"connected with thinking, understanding, and mental processes","examples":["Puzzles and games can help maintain good [cognitive] function in older adults. (=Dịch: Các câu đố và trò chơi có thể giúp duy trì chức năng nhận thức tốt ở người lớn tuổi.)","Reading regularly contributes significantly to a child's [cognitive] development. (=Dịch: Đọc sách thường xuyên đóng góp đáng kể vào sự phát triển nhận thức của trẻ.)","The test measures various [cognitive] skills such as memory and attention. (=Dịch: Bài kiểm tra đo lường các kỹ năng nhận thức khác nhau như trí nhớ và sự chú ý.)"],"ukAudio":"/ai_services/tts3/?q=cognitive&lang=en-GB&ipa=%2F%CB%88k%C9%91%C9%A1.n%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cognitive&lang=en-US&ipa=%2F%CB%88k%C9%91%C9%A1.n%C9%99.t%C9%AAv%2F"},{"id":"lv_6_29","topic":"Business and Humanities Studies","word":"collaboration","pos":"(n)","ipa":"/kəˌlæb.əˈreɪ.ʃən/","defVi":"sự cộng tác, sự hợp tác","defEn":"the act of working together with other people or organizations to produce something","examples":["The project was successful thanks to close [collaboration] between both teams. (=Dịch: Dự án đã thành công nhờ vào sự hợp tác chặt chẽ giữa hai đội ngũ.)","The new song is a creative [collaboration] between two famous musicians. (=Dịch: Bài hát mới là một sự cộng tác sáng tạo giữa hai nhạc sĩ nổi tiếng.)","International [collaboration] is essential to solve global environmental issues. (=Dịch: Sự hợp tác quốc tế là rất cần thiết để giải quyết các vấn đề môi trường toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=collaboration&lang=en-GB&ipa=%2Fk%C9%99%CB%8Cl%C3%A6b.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=collaboration&lang=en-US&ipa=%2Fk%C9%99%CB%8Cl%C3%A6b.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_30","topic":"Business and Humanities Studies","word":"combination","pos":"(n)","ipa":"/ˌkɑːm.bəˈneɪ.ʃən/","defVi":"sự kết hợp, sự phối hợp","defEn":"the result of joining two or more things together","examples":["The dish is a delightful [combination] of sweet and spicy flavours. (=Dịch: Món ăn này là một sự kết hợp thú vị giữa hương vị ngọt và cay.)","Success in learning requires a [combination] of hard work and good strategies. (=Dịch: Thành công trong học tập đòi hỏi sự kết hợp giữa nỗ lực chăm chỉ và chiến lược tốt.)","He forgot the secret [combination] needed to open the safe. (=Dịch: Anh ấy đã quên mất mã số kết hợp bí mật để mở chiếc két sắt.)"],"ukAudio":"/ai_services/tts3/?q=combination&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90m.b%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=combination&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90m.b%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_31","topic":"Business and Humanities Studies","word":"comfort","pos":"(n)","ipa":"/ˈkʌm.fɚt/","defVi":"sự thoải mái, sự an ủi, tiện nghi","defEn":"a state of physical ease and freedom from pain or anxiety","examples":["The modern hotel offers both luxury and [comfort] to its guests. (=Dịch: Khách sạn hiện đại này mang lại cả sự sang trọng lẫn thoải mái cho du khách.)","She found great [comfort] in talking to her closest friend during hard times. (=Dịch: Cô ấy tìm thấy sự an ủi lớn khi tâm sự với người bạn thân nhất trong những lúc khó khăn.)","Traveling in first class provides a much higher level of [comfort]. (=Dịch: Đi du lịch ở khoang hạng nhất mang lại mức độ tiện nghi cao hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=comfort&lang=en-GB&ipa=%2F%CB%88k%CA%8Cm.f%C9%9At%2F","usAudio":"/ai_services/tts3/?q=comfort&lang=en-US&ipa=%2F%CB%88k%CA%8Cm.f%C9%9At%2F"},{"id":"lv_6_32","topic":"Business and Humanities Studies","word":"command","pos":"(n)","ipa":"/kəˈmænd/","defVi":"mệnh lệnh, chỉ thị","defEn":"an authoritative order or directive given to someone","examples":["The soldiers waited patiently for the general's next [command]. (=Dịch: Các binh sĩ kiên nhẫn chờ đợi mệnh lệnh tiếp theo của vị tướng.)","He gave a clear [command] to stop all construction work immediately. (=Dịch: Ông ấy đã đưa ra một mệnh lệnh rõ ràng yêu cầu dừng ngay lập tức mọi công việc xây dựng.)","The dog obeys every [command] given by its trainer. (=Dịch: Chú chó tuân theo mọi mệnh lệnh do người huấn luyện đưa ra.)"],"ukAudio":"/ai_services/tts3/?q=command&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=command&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C3%A6nd%2F"},{"id":"lv_6_33","topic":"Business and Humanities Studies","word":"commit","pos":"(v)","ipa":"/kəˈmɪt/","defVi":"cam kết, gắn bó hoặc cống hiến","defEn":"to promise or dedicate oneself to a particular course of action or relationship","examples":["The company decided to [commit] more resources to scientific research. (=Dịch: Công ty đã quyết định cam kết dành nhiều nguồn lực hơn cho nghiên cứu khoa học.)","He was not ready to [commit] to a long-term contract. (=Dịch: Anh ấy chưa sẵn sàng cam kết với một hợp đồng dài hạn.)","Both countries agreed to [commit] to reducing carbon emissions. (=Dịch: Cả hai quốc gia đã đồng ý cam kết cắt giảm lượng khí thải carbon.)"],"ukAudio":"/ai_services/tts3/?q=commit&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=commit&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%AAt%2F"},{"id":"lv_6_34","topic":"Business and Humanities Studies","word":"comparison","pos":"(n)","ipa":"/kəmˈpær.ə.sən/","defVi":"sự so sánh","defEn":"the act of considering the similarities and differences between two or more things","examples":["A [comparison] between the two smartphones shows only minor differences. (=Dịch: Một sự so sánh giữa hai chiếc điện thoại thông minh cho thấy chỉ có những khác biệt nhỏ.)","In [comparison] with last year, this semester's test scores have improved. (=Dịch: So với năm ngoái, điểm kiểm tra của học kỳ này đã được cải thiện.)","The report makes a detailed [comparison] of healthcare systems worldwide. (=Dịch: Báo cáo đưa ra một sự so sánh chi tiết về các hệ thống y tế trên toàn thế giới.)"],"ukAudio":"/ai_services/tts3/?q=comparison&lang=en-GB&ipa=%2Fk%C9%99m%CB%88p%C3%A6r.%C9%99.s%C9%99n%2F","usAudio":"/ai_services/tts3/?q=comparison&lang=en-US&ipa=%2Fk%C9%99m%CB%88p%C3%A6r.%C9%99.s%C9%99n%2F"},{"id":"lv_6_35","topic":"Business and Humanities Studies","word":"complaint","pos":"(n)","ipa":"/kəmˈpleɪnt/","defVi":"Lời phàn nàn, sự khiếu nại","defEn":"A statement that something is wrong or not satisfactory.","examples":["The customer filed a formal [complaint] about the poor service. (=Dịch: Khách hàng đã nộp đơn khiếu nại chính thức về chất lượng dịch vụ kém.)","Noise from nearby construction is a common [complaint] among residents. (=Dịch: Tiếng ồn từ công trình xây dựng gần đó là một lời phàn nàn phổ biến của các cư dân.)","Our goal is to resolve every client [complaint] within twenty-four hours. (=Dịch: Mục tiêu của chúng tôi là giải quyết mọi khiếu nại của khách hàng trong vòng hai mươi bốn giờ.)"],"ukAudio":"/ai_services/tts3/?q=complaint&lang=en-GB&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F","usAudio":"/ai_services/tts3/?q=complaint&lang=en-US&ipa=%2Fk%C9%99m%CB%88ple%C9%AAnt%2F"},{"id":"lv_6_36","topic":"Business and Humanities Studies","word":"concerning","pos":"(prep)","ipa":"/kənˈsɜr.nɪŋ/","defVi":"về, liên quan đến","defEn":"about or related to a particular subject","examples":["I received an email [concerning] the new company policy. (=Dịch: Tôi đã nhận được một email liên quan đến chính sách mới của công ty.)","He asked several questions [concerning] the safety of the medication. (=Dịch: Anh ấy đã hỏi vài câu hỏi liên quan đến độ an toàn của loại thuốc này.)","The committee held a meeting [concerning] the rising cost of living. (=Dịch: Ủy ban đã tổ chức một cuộc họp về vấn đề chi phí sinh hoạt ngày càng tăng.)"],"ukAudio":"/ai_services/tts3/?q=concerning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88s%C9%9Cr.n%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=concerning&lang=en-US&ipa=%2Fk%C9%99n%CB%88s%C9%9Cr.n%C9%AA%C5%8B%2F"},{"id":"lv_6_37","topic":"Business and Humanities Studies","word":"conclude","pos":"(v)","ipa":"/kənˈklud/","defVi":"kết luận, suy ra","defEn":"to decide or believe something after considering all the facts","examples":["Researchers [conclude] that regular exercise can improve mental health. (=Dịch: Các nhà nghiên cứu kết luận rằng tập thể dục thường xuyên có thể cải thiện sức khỏe tinh thần.)","The meeting will [conclude] with a speech by the director. (=Dịch: Cuộc họp sẽ kết thúc bằng một bài phát biểu của giám đốc.)","From the evidence presented, we can [conclude] that the project was a success. (=Dịch: Từ những bằng chứng được đưa ra, chúng ta có thể kết luận rằng dự án đã thành công.)"],"ukAudio":"/ai_services/tts3/?q=conclude&lang=en-GB&ipa=%2Fk%C9%99n%CB%88klud%2F","usAudio":"/ai_services/tts3/?q=conclude&lang=en-US&ipa=%2Fk%C9%99n%CB%88klud%2F"},{"id":"lv_6_38","topic":"Business and Humanities Studies","word":"conditioning","pos":"(n)","ipa":"/kənˈdɪʃ.ən.ɪŋ/","defVi":"sự rèn luyện, sự điều hòa, sự tạo phản xạ","defEn":"the process of training or adapting someone or something to behave in a certain way or be in a certain state","examples":["Physical [conditioning] is an essential part of an athlete's daily routine. (=Dịch: Rèn luyện thể lực là một phần thiết yếu trong thói quen hàng ngày của một vận động viên.)","Social [conditioning] often influences our preferences and choices. (=Dịch: Khuôn mẫu từ xã hội thường ảnh hưởng đến sở thích và lựa chọn của chúng ta.)","The team improved its stamina through rigorous aerobic [conditioning]. (=Dịch: Đội đã nâng cao thể lực bền bỉ thông qua quá trình rèn luyện hiếu khí nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=conditioning&lang=en-GB&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=conditioning&lang=en-US&ipa=%2Fk%C9%99n%CB%88d%C9%AA%CA%83.%C9%99n.%C9%AA%C5%8B%2F"},{"id":"lv_6_39","topic":"Business and Humanities Studies","word":"conflict","pos":"(n)","ipa":"/ˈkɑːn.flɪkt/","defVi":"sự xung đột, mâu thuẫn","defEn":"an active disagreement, struggle, or clash between people with opposing ideas or interests","examples":["The manager resolved the internal [conflict] between the two departments. (=Dịch: Người quản lý đã giải quyết mâu thuẫn nội bộ giữa hai phòng ban.)","Armed [conflict] has forced thousands of families to leave their homes. (=Dịch: Xung đột vũ trang đã buộc hàng ngàn gia đình phải rời bỏ nhà cửa.)","There is an obvious [conflict] of interest in this business transaction. (=Dịch: Có một sự xung đột lợi ích rõ ràng trong giao dịch kinh doanh này.)"],"ukAudio":"/ai_services/tts3/?q=conflict&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.fl%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=conflict&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.fl%C9%AAkt%2F"},{"id":"lv_6_40","topic":"Business and Humanities Studies","word":"confused","pos":"(adj)","ipa":"/kənˈfjuːzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to think clearly or understand something properly","examples":["I got [confused] by the complex instructions on the exam paper. (=Dịch: Tôi cảm thấy bối rối trước những chỉ dẫn phức tạp trên đề thi.)","The tourist looked [confused] while trying to read the city map. (=Dịch: Người khách du lịch trông có vẻ hoang mang khi cố gắng đọc tấm bản đồ thành phố.)","Her sudden change of plans left everyone feeling [confused]. (=Dịch: Việc cô ấy đột ngột thay đổi kế hoạch đã khiến mọi người cảm thấy bối rối.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90zd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90zd%2F"},{"id":"lv_6_41","topic":"Business and Humanities Studies","word":"confusion","pos":"(n)","ipa":"/kənˈfjuː.ʒən/","defVi":"sự bối rối, sự hoang mang, sự hỗn loạn","defEn":"a state of not being clear, or a situation where things are disorganized and bewildering","examples":["There was some [confusion] about the exact time of the meeting. (=Dịch: Đã có một chút nhầm lẫn về thời gian chính xác của cuộc họp.)","The sudden change in policy caused widespread [confusion] among employees. (=Dịch: Sự thay đổi chính sách đột ngột đã gây ra sự hoang mang trên diện rộng trong nhân viên.)","His vague explanation only added to the passenger's [confusion]. (=Dịch: Lời giải thích mơ hồ của anh ấy chỉ làm tăng thêm sự bối rối của hành khách.)"],"ukAudio":"/ai_services/tts3/?q=confusion&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=confusion&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_6_42","topic":"Business and Humanities Studies","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwəns/","defVi":"hậu quả, hệ quả","defEn":"a result or effect of an action or condition","examples":["Global warming is a direct [consequence] of excessive carbon emissions. (=Dịch: Sự nóng lên toàn cầu là một hệ quả trực tiếp của việc phát thải carbon quá mức.)","He had to face the [consequence] of his careless driving. (=Dịch: Anh ấy đã phải đối mặt với hậu quả từ việc lái xe bất cẩn của mình.)","Failing to prepare adequately may have a serious [consequence] for your exam. (=Dịch: Việc không chuẩn bị chu đáo có thể mang lại hậu quả nghiêm trọng cho kỳ thi của bạn.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kw%C9%99ns%2F"},{"id":"lv_6_43","topic":"Business and Humanities Studies","word":"consolidation","pos":"(n)","ipa":"/kənˌsɑː.lɪˈdeɪ.ʃən/","defVi":"sự củng cố, sự hợp nhất","defEn":"the process of combining several things into a single, more effective or stronger whole","examples":["The merger led to the [consolidation] of several smaller regional offices. (=Dịch: Vụ sáp nhập đã dẫn đến sự hợp nhất của nhiều văn phòng nhỏ trong khu vực.)","The company focuses on the [consolidation] of its market position. (=Dịch: Công ty tập trung vào việc củng cố vị thế của mình trên thị trường.)","Debt [consolidation] can help individuals manage multiple loans more easily. (=Dịch: Hợp nhất nợ có thể giúp các cá nhân quản lý nhiều khoản vay dễ dàng hơn.)"],"ukAudio":"/ai_services/tts3/?q=consolidation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8Cs%C9%91%CB%90.l%C9%AA%CB%88de%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=consolidation&lang=en-US&ipa=%2Fk%C9%99n%CB%8Cs%C9%91%CB%90.l%C9%AA%CB%88de%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_44","topic":"Business and Humanities Studies","word":"consume","pos":"(v)","ipa":"/kənˈsuːm/","defVi":"tiêu thụ, tiêu dùng, ăn uống","defEn":"to use up a resource, or to eat or drink something","examples":["Modern vehicles [consume] less fuel compared to older models. (=Dịch: Các phương tiện hiện đại tiêu thụ ít nhiên liệu hơn so với các mẫu cũ.)","People are advised not to [consume] too much sugary food. (=Dịch: Mọi người được khuyên không nên tiêu thụ quá nhiều đồ ăn ngọt.)","The fire threatened to [consume] the entire forest within hours. (=Dịch: Ngọn lửa đe dọa sẽ thiêu rụi toàn bộ khu rừng trong vòng vài giờ.)"],"ukAudio":"/ai_services/tts3/?q=consume&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F","usAudio":"/ai_services/tts3/?q=consume&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90m%2F"},{"id":"lv_6_45","topic":"Business and Humanities Studies","word":"consumer","pos":"(n)","ipa":"/kənˈsu.mɚ/","defVi":"Người tiêu dùng","defEn":"A person who buys goods or uses services.","examples":["Advertising has a powerful influence on [consumer] behavior. (=Dịch: Quảng cáo có ảnh hưởng mạnh mẽ đến hành vi của người tiêu dùng.)","Many [consumer] groups are demanding safer and healthier food products. (=Dịch: Nhiều nhóm người tiêu dùng đang yêu cầu các sản phẩm thực phẩm an toàn và lành mạnh hơn.)","The company tries to satisfy the modern [consumer] by offering online support. (=Dịch: Công ty cố gắng làm hài lòng người tiêu dùng hiện đại bằng cách cung cấp hỗ trợ trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=consumer&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su.m%C9%9A%2F","usAudio":"/ai_services/tts3/?q=consumer&lang=en-US&ipa=%2Fk%C9%99n%CB%88su.m%C9%9A%2F"},{"id":"lv_6_46","topic":"Business and Humanities Studies","word":"continuous","pos":"(adj)","ipa":"/kənˈtɪn.ju.əs/","defVi":"Liên tục, không ngừng","defEn":"Happening or existing without stopping or being interrupted.","examples":["The brain needs a [continuous] supply of blood and oxygen. (=Dịch: Bộ não cần được cung cấp máu và oxy liên tục.)","After three days of [continuous] rain, the river began to overflow. (=Dịch: Sau ba ngày mưa liên tục, con sông bắt đầu tràn bờ.)","Lifelong learning requires [continuous] effort and curiosity. (=Dịch: Học tập suốt đời đòi hỏi sự nỗ lực và tò mò không ngừng.)"],"ukAudio":"/ai_services/tts3/?q=continuous&lang=en-GB&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=continuous&lang=en-US&ipa=%2Fk%C9%99n%CB%88t%C9%AAn.ju.%C9%99s%2F"},{"id":"lv_6_47","topic":"Business and Humanities Studies","word":"conventional","pos":"(adj)","ipa":"/kənˈvɛn.ʃən.əl/","defVi":"Truyền thống, thông thường theo tập quán","defEn":"Following accepted customs, traditions, or standard practices.","examples":["Organic farming uses fewer chemicals than [conventional] agriculture. (=Dịch: Nông nghiệp hữu cơ sử dụng ít hóa chất hơn so với nông nghiệp truyền thống.)","She preferred alternative medicine to [conventional] treatments. (=Dịch: Cô ấy thích các phương pháp y học thay thế hơn là các phương pháp điều trị thông thường.)","His [conventional] views on education often clashed with modern teaching methods. (=Dịch: Quan điểm truyền thống của ông về giáo dục thường xung đột với các phương pháp giảng dạy hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=conventional&lang=en-GB&ipa=%2Fk%C9%99n%CB%88v%C9%9Bn.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=conventional&lang=en-US&ipa=%2Fk%C9%99n%CB%88v%C9%9Bn.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_48","topic":"Business and Humanities Studies","word":"corporate","pos":"(adj)","ipa":"/ˈkɔr.pɚ.ət/","defVi":"Thuộc về doanh nghiệp, công ty","defEn":"Relating to a large company or business organization.","examples":["She has spent over a decade working in the [corporate] world. (=Dịch: Cô ấy đã dành hơn một thập kỷ làm việc trong giới doanh nghiệp.)","The airline introduced a new [corporate] logo to attract younger clients. (=Dịch: Hãng hàng không đã giới thiệu một logo công ty mới để thu hút khách hàng trẻ tuổi hơn.)","Many businesses are trying to improve their [corporate] social responsibility. (=Dịch: Nhiều doanh nghiệp đang cố gắng cải thiện trách nhiệm xã hội của doanh nghiệp mình.)"],"ukAudio":"/ai_services/tts3/?q=corporate&lang=en-GB&ipa=%2F%CB%88k%C9%94r.p%C9%9A.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=corporate&lang=en-US&ipa=%2F%CB%88k%C9%94r.p%C9%9A.%C9%99t%2F"},{"id":"lv_6_49","topic":"Business and Humanities Studies","word":"craftsman","pos":"(n)","ipa":"/ˈkræfts.mən/","defVi":"Thợ thủ công, nghệ nhân","defEn":"A person who is skilled in a particular craft or manual art.","examples":["The wooden table was hand-carved by a local [craftsman]. (=Dịch: Chiếc bàn gỗ được chạm khắc thủ công bởi một nghệ nhân địa phương.)","Every master [craftsman] spends years perfecting their delicate techniques. (=Dịch: Mỗi người thợ thủ công bậc thầy đều dành nhiều năm để hoàn thiện các kỹ thuật tinh xảo của mình.)","He admired the dedication that the [craftsman] showed in repairing antique watches. (=Dịch: Anh ngưỡng mộ sự tận tụy mà người thợ thủ công thể hiện khi sửa chữa những chiếc đồng hồ cổ.)"],"ukAudio":"/ai_services/tts3/?q=craftsman&lang=en-GB&ipa=%2F%CB%88kr%C3%A6fts.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=craftsman&lang=en-US&ipa=%2F%CB%88kr%C3%A6fts.m%C9%99n%2F"},{"id":"lv_6_50","topic":"Business and Humanities Studies","word":"criterion","pos":"(n)","ipa":"/kraɪˈtɪr.i.ən/","defVi":"tiêu chí, chuẩn mực","defEn":"a standard by which something may be judged or decided","examples":["Academic achievement is not the sole [criterion] for college admission. (=Dịch: Thành tích học tập không phải là tiêu chí duy nhất để xét tuyển đại học.)","Cost-effectiveness was the primary [criterion] used to select the vendor. (=Dịch: Hiệu quả chi phí là tiêu chí chính được sử dụng để lựa chọn nhà cung cấp.)","Safety should be the most important [criterion] when designing vehicles. (=Dịch: An toàn phải là tiêu chuẩn quan trọng nhất khi thiết kế các phương tiện giao thông.)"],"ukAudio":"/ai_services/tts3/?q=criterion&lang=en-GB&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=criterion&lang=en-US&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F"},{"id":"lv_6_51","topic":"Business and Humanities Studies","word":"critical","pos":"(adj)","ipa":"/ˈkrɪt̬.ɪ.kəl/","defVi":"quan trọng, then chốt; chỉ trích","defEn":"extremely important or expressing serious disapproval","examples":["Water conservation plays a [critical] role in protecting the environment. (=Dịch: Bảo tồn nguồn nước đóng một vai trò then chốt trong việc bảo vệ môi trường.)","The director was highly [critical] of the actor's performance. (=Dịch: Đạo diễn đã chỉ trích rất gay gắt màn trình diễn của diễn viên.)","University students are encouraged to develop strong [critical] thinking skills. (=Dịch: Sinh viên đại học được khuyến khích phát triển kỹ năng tư duy phản biện tốt.)"],"ukAudio":"/ai_services/tts3/?q=critical&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=critical&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F"},{"id":"lv_6_52","topic":"Business and Humanities Studies","word":"cultural","pos":"(adj)","ipa":"/ˈkʌl.tʃɚ.əl/","defVi":"thuộc về văn hóa","defEn":"relating to the habits, traditions, and beliefs of a society","examples":["Traveling abroad exposes people to different [cultural] traditions. (=Dịch: Du lịch nước ngoài giúp mọi người tiếp cận với những truyền thống văn hóa khác nhau.)","The city hosts an annual [cultural] festival celebrating local arts and music. (=Dịch: Thành phố tổ chức một lễ hội văn hóa thường niên tôn vinh nghệ thuật và âm nhạc địa phương.)","Language plays a vital role in preserving a nation's [cultural] identity. (=Dịch: Ngôn ngữ đóng một vai trò quan trọng trong việc gìn giữ bản sắc văn hóa của một quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=cultural&lang=en-GB&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cultural&lang=en-US&ipa=%2F%CB%88k%CA%8Cl.t%CA%83%C9%9A.%C9%99l%2F"},{"id":"lv_6_53","topic":"Business and Humanities Studies","word":"decline","pos":"(v)","ipa":"/dɪˈklaɪn/","defVi":"suy giảm; từ chối","defEn":"to become smaller, fewer, or less; or to politely refuse an offer or invitation","examples":["Car sales began to [decline] sharply during the economic downturn. (=Dịch: Doanh số bán ô tô bắt đầu sụt giảm mạnh trong thời kỳ suy thoái kinh tế.)","I had to [decline] the job offer because the commute was too long. (=Dịch: Tôi đã phải từ chối lời mời làm việc vì quãng đường đi làm quá xa.)","Her health started to [decline] as she grew older. (=Dịch: Sức khỏe của bà ấy bắt đầu suy giảm khi tuổi tác ngày càng cao.)"],"ukAudio":"/ai_services/tts3/?q=decline&lang=en-GB&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=decline&lang=en-US&ipa=%2Fd%C9%AA%CB%88kla%C9%AAn%2F"},{"id":"lv_6_54","topic":"Business and Humanities Studies","word":"define","pos":"(v)","ipa":"/dɪˈfaɪn/","defVi":"định nghĩa, xác định","defEn":"to explain the exact meaning of a word or idea","examples":["It is difficult to [define] the concept of happiness simply. (=Dịch: Rất khó để định nghĩa khái niệm hạnh phúc một cách đơn giản.)","Dictionaries [define] words and provide examples of how they are used. (=Dịch: Từ điển định nghĩa các từ và cung cấp các ví dụ về cách sử dụng chúng.)","The contract will clearly [define] the responsibilities of each team member. (=Dịch: Hợp đồng sẽ xác định rõ ràng trách nhiệm của từng thành viên trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=define&lang=en-GB&ipa=%2Fd%C9%AA%CB%88fa%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=define&lang=en-US&ipa=%2Fd%C9%AA%CB%88fa%C9%AAn%2F"},{"id":"lv_6_55","topic":"Business and Humanities Studies","word":"definition","pos":"(n)","ipa":"/ˌdɛf.əˈnɪʃ.ən/","defVi":"Định nghĩa, sự giải thích rõ ràng","defEn":"An explanation of the exact meaning of a word or phrase.","examples":["You can look up the exact [definition] of unfamiliar words in a dictionary. (=Dịch: Bạn có thể tra cứu định nghĩa chính xác của những từ xa lạ trong từ điển.)","The legal [definition] of property varies from country to country. (=Dịch: Định nghĩa pháp lý về tài sản có sự khác nhau giữa các quốc gia.)","His [definition] of success focuses on happiness rather than wealth. (=Dịch: Định nghĩa về thành công của anh ấy tập trung vào hạnh phúc hơn là sự giàu có.)"],"ukAudio":"/ai_services/tts3/?q=definition&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=definition&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bf.%C9%99%CB%88n%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_6_56","topic":"Business and Humanities Studies","word":"dementia","pos":"(n)","ipa":"/dɪˈmen.ʃə/","defVi":"chứng suy giảm trí nhớ, bệnh sa sút trí tuệ","defEn":"a progressive mental disorder characterized by memory loss, confusion, and impaired reasoning","examples":["The hospital provides specialized care for elderly patients suffering from [dementia]. (=Dịch: Bệnh viện cung cấp dịch vụ chăm sóc chuyên biệt cho những bệnh nhân cao tuổi mắc chứng sa sút trí tuệ.)","Regular mental exercises may help lower the risk of developing [dementia] in later life. (=Dịch: Các bài tập trí não thường xuyên có thể giúp giảm nguy cơ mắc chứng suy giảm trí nhớ khi về già.)","Caring for a family member with advanced [dementia] can be emotionally exhausting. (=Dịch: Chăm sóc một thành viên trong gia đình mắc chứng sa sút trí tuệ giai đoạn nặng có thể gây kiệt quệ về mặt cảm xúc.)"],"ukAudio":"/ai_services/tts3/?q=dementia&lang=en-GB&ipa=%2Fd%C9%AA%CB%88men.%CA%83%C9%99%2F","usAudio":"/ai_services/tts3/?q=dementia&lang=en-US&ipa=%2Fd%C9%AA%CB%88men.%CA%83%C9%99%2F"},{"id":"lv_6_57","topic":"Business and Humanities Studies","word":"democratic","pos":"(adj)","ipa":"/ˌdɛm.əˈkræt̬.ɪk/","defVi":"Dân chủ","defEn":"Based on the principle that all people have equal rights to participate in governance.","examples":["Free and fair elections are the foundation of any [democratic] society. (=Dịch: Các cuộc bầu cử tự do và công bằng là nền tảng của bất kỳ xã hội dân chủ nào.)","The manager adopted a [democratic] leadership style by consulting his team. (=Dịch: Người quản lý đã áp dụng phong cách lãnh đạo dân chủ bằng cách tham khảo ý kiến của nhóm mình.)","Citizens should actively engage in the [democratic] process to make their voices heard. (=Dịch: Công dân nên tích cực tham gia vào tiến trình dân chủ để tiếng nói của họ được lắng nghe.)"],"ukAudio":"/ai_services/tts3/?q=democratic&lang=en-GB&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99%CB%88kr%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=democratic&lang=en-US&ipa=%2F%CB%8Cd%C9%9Bm.%C9%99%CB%88kr%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_6_58","topic":"Business and Humanities Studies","word":"dependent","pos":"(adj)","ipa":"/dɪˈpɛn.dənt/","defVi":"phụ thuộc, lệ thuộc","defEn":"needing the support of something or someone else to survive or succeed","examples":["Many young adults are still financially [dependent] on their parents. (=Dịch: Nhiều người trẻ tuổi vẫn phụ thuộc tài chính vào cha mẹ của họ.)","The economy of this coastal town is largely [dependent] on tourism. (=Dịch: Nền kinh tế của thị trấn ven biển này phần lớn phụ thuộc vào du lịch.)","The success of the crops is [dependent] on the weather conditions. (=Dịch: Sự thành công của mùa màng phụ thuộc vào điều kiện thời tiết.)"],"ukAudio":"/ai_services/tts3/?q=dependent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88p%C9%9Bn.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dependent&lang=en-US&ipa=%2Fd%C9%AA%CB%88p%C9%9Bn.d%C9%99nt%2F"},{"id":"lv_6_59","topic":"Business and Humanities Studies","word":"depression","pos":"(n)","ipa":"/dɪˈpreʃ.ən/","defVi":"chứng trầm cảm; sự suy thoái kinh tế","defEn":"a mental health condition marked by severe sadness, or a period of severe economic decline","examples":["Regular physical exercise can help reduce symptoms of [depression]. (=Dịch: Tập thể dục thường xuyên có thể giúp giảm các triệu chứng trầm cảm.)","The global economy suffered a major [depression] in the 1930s. (=Dịch: Nền kinh tế toàn cầu đã trải qua một cuộc đại suy thoái lớn vào những năm 1930.)","Talking openly with a therapist can provide relief from clinical [depression]. (=Dịch: Trò chuyện cởi mở với chuyên gia trị liệu có thể giúp thuyên giảm chứng trầm cảm lâm sàng.)"],"ukAudio":"/ai_services/tts3/?q=depression&lang=en-GB&ipa=%2Fd%C9%AA%CB%88pre%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=depression&lang=en-US&ipa=%2Fd%C9%AA%CB%88pre%CA%83.%C9%99n%2F"},{"id":"lv_6_60","topic":"Business and Humanities Studies","word":"determine","pos":"(v)","ipa":"/dɪˈtɜːr.mɪn/","defVi":"xác định, quyết định","defEn":"to discover the facts about something or to decide something firmly","examples":["Scientists are conducting experiments to [determine] the exact age of the fossil. (=Dịch: Các nhà khoa học đang tiến hành các thí nghiệm để xác định tuổi chính xác của hóa thạch.)","Your exam results will largely [determine] which university you can attend. (=Dịch: Kết quả thi của bạn sẽ quyết định phần lớn trường đại học mà bạn có thể theo học.)","Officials are trying to [determine] the cause of the sudden power outage. (=Dịch: Các giới chức đang nỗ lực xác định nguyên nhân gây ra sự cố mất điện đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=determine&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9C%CB%90r.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=determine&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9C%CB%90r.m%C9%AAn%2F"},{"id":"lv_6_61","topic":"Business and Humanities Studies","word":"devote","pos":"(v)","ipa":"/dɪˈvoʊt/","defVi":"cống hiến, dành hết (thời gian, tâm huyết) cho","defEn":"to give all or a large part of one's time or resources to a person, activity, or cause","examples":["She decided to [devote] her entire career to cancer research. (=Dịch: Cô ấy quyết định cống hiến toàn bộ sự nghiệp của mình cho việc nghiên cứu bệnh ung thư.)","Parents often [devote] a tremendous amount of energy to raising their children. (=Dịch: Cha mẹ thường dành rất nhiều năng lượng cho việc nuôi dạy con cái.)","He plans to [devote] more time to community service after retirement. (=Dịch: Ông dự định dành nhiều thời gian hơn cho công tác phục vụ cộng đồng sau khi nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=devote&lang=en-GB&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=devote&lang=en-US&ipa=%2Fd%C9%AA%CB%88vo%CA%8At%2F"},{"id":"lv_6_62","topic":"Business and Humanities Studies","word":"disadvantage","pos":"(n)","ipa":"/ˌdɪs.ədˈvæn.t̬ɪdʒ/","defVi":"nhược điểm, bất lợi","defEn":"an unfavorable condition or circumstance that reduces the chances of success","examples":["One major [disadvantage] of remote work is the lack of face-to-face interaction. (=Dịch: Một bất lợi lớn của việc làm việc từ xa là thiếu sự tương tác trực tiếp.)","Candidates without relevant experience are at a serious [disadvantage]. (=Dịch: Những ứng viên không có kinh nghiệm liên quan sẽ chịu bất lợi nghiêm trọng.)","We must weigh the benefits against every potential [disadvantage] before investing. (=Dịch: Chúng ta phải cân nhắc các lợi ích so với mọi nhược điểm tiềm ẩn trước khi đầu tư.)"],"ukAudio":"/ai_services/tts3/?q=disadvantage&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=disadvantage&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_6_63","topic":"Business and Humanities Studies","word":"dominant","pos":"(adj)","ipa":"/ˈdɑː.mə.nənt/","defVi":"Thống trị, chiếm ưu thế vượt trội","defEn":"More important, strong, or noticeable than anything else of the same type.","examples":["English has become the [dominant] language in global business. (=Dịch: Tiếng Anh đã trở thành ngôn ngữ thống trị trong kinh doanh toàn cầu.)","The tech giant maintains a [dominant] position in the smartphone market. (=Dịch: Gã khổng lồ công nghệ duy trì vị thế thống trị trên thị trường điện thoại thông minh.)","Geneticists study how [dominant] genes are inherited by offspring. (=Dịch: Các nhà di truyền học nghiên cứu cách các gen trội được di truyền sang thế hệ sau.)"],"ukAudio":"/ai_services/tts3/?q=dominant&lang=en-GB&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99.n%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=dominant&lang=en-US&ipa=%2F%CB%88d%C9%91%CB%90.m%C9%99.n%C9%99nt%2F"},{"id":"lv_6_64","topic":"Business and Humanities Studies","word":"donate","pos":"(v)","ipa":"/ˈdoʊ.neɪt/","defVi":"quyên góp, hiến tặng, ủng hộ","defEn":"to give money, goods, or time to help a person or organization","examples":["Many wealthy individuals [donate] large sums of money to medical research. (=Dịch: Nhiều cá nhân giàu có quyên góp số tiền lớn cho nghiên cứu y học.)","Local residents decided to [donate] warm clothes to earthquake victims. (=Dịch: Cư dân địa phương đã quyết định ủng hộ quần áo ấm cho các nạn nhân động đất.)","He volunteered to [donate] blood during the national health campaign. (=Dịch: Anh ấy đã tình nguyện hiến máu trong chiến dịch y tế quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=donate&lang=en-GB&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=donate&lang=en-US&ipa=%2F%CB%88do%CA%8A.ne%C9%AAt%2F"},{"id":"lv_6_65","topic":"Business and Humanities Studies","word":"duplicate","pos":"(v)","ipa":"/ˈduː.plɪ.keɪt/","defVi":"sao chép, nhân bản, lặp lại","defEn":"to make an exact copy of something, or repeat something","examples":["Researchers tried to [duplicate] the original experiment to confirm the findings. (=Dịch: Các nhà nghiên cứu đã cố gắng lặp lại thí nghiệm ban đầu để xác nhận các phát hiện.)","You can easily [duplicate] this document by scanning it onto your computer. (=Dịch: Bạn có thể dễ dàng sao chép tài liệu này bằng cách quét nó vào máy tính.)","The software allows users to [duplicate] project files with a single click. (=Dịch: Phần mềm cho phép người dùng nhân bản các tệp dự án chỉ với một cú nhấp chuột.)"],"ukAudio":"/ai_services/tts3/?q=duplicate&lang=en-GB&ipa=%2F%CB%88du%CB%90.pl%C9%AA.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=duplicate&lang=en-US&ipa=%2F%CB%88du%CB%90.pl%C9%AA.ke%C9%AAt%2F"},{"id":"lv_6_66","topic":"Business and Humanities Studies","word":"eager","pos":"(adj)","ipa":"/ˈi.ɡər/","defVi":"háo hức, tha thiết, hăm hở","defEn":"strongly wanting to do or have something","examples":["The students were [eager] to start their summer vacation. (=Dịch: Các học sinh rất háo hức bắt đầu kỳ nghỉ hè.)","He is always [eager] to learn new professional skills. (=Dịch: Anh ấy luôn hăm hở học hỏi những kỹ năng chuyên môn mới.)","The crowd was [eager] for the concert to begin. (=Dịch: Đám đông vô cùng sốt ruột mong buổi hòa nhạc bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=eager&lang=en-GB&ipa=%2F%CB%88i.%C9%A1%C9%99r%2F","usAudio":"/ai_services/tts3/?q=eager&lang=en-US&ipa=%2F%CB%88i.%C9%A1%C9%99r%2F"},{"id":"lv_6_67","topic":"Business and Humanities Studies","word":"elderly","pos":"(adj)","ipa":"/ˈɛl.dɚ.li/","defVi":"cao tuổi, lớn tuổi","defEn":"used as a polite word for old, usually describing people","examples":["The government is improving healthcare services for [elderly] citizens. (=Dịch: Chính phủ đang cải thiện các dịch vụ chăm sóc sức khỏe cho những công dân cao tuổi.)","A kind volunteer helped the [elderly] woman carry her groceries. (=Dịch: Một tình nguyện viên tốt bụng đã giúp người phụ nữ lớn tuổi xách đồ mua sắm.)","Many [elderly] residents enjoy walking in the park every morning. (=Dịch: Nhiều cư dân lớn tuổi thích đi dạo trong công viên mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=elderly&lang=en-GB&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F","usAudio":"/ai_services/tts3/?q=elderly&lang=en-US&ipa=%2F%CB%88%C9%9Bl.d%C9%9A.li%2F"},{"id":"lv_6_68","topic":"Business and Humanities Studies","word":"emotion","pos":"(n)","ipa":"/ɪˈmoʊ.ʃən/","defVi":"cảm xúc","defEn":"a strong feeling such as love, fear, or anger","examples":["He struggled to control his [emotion] during the farewell speech. (=Dịch: Anh ấy đã rất cố gắng kìm nén cảm xúc trong bài phát biểu chia tay.)","Music can evoke a wide range of human [emotion]. (=Dịch: Âm nhạc có thể gợi lên rất nhiều cung bậc cảm xúc của con người.)","Making important decisions based purely on [emotion] can lead to regrets. (=Dịch: Đưa ra các quyết định quan trọng chỉ dựa vào cảm xúc có thể dẫn đến hối tiếc.)"],"ukAudio":"/ai_services/tts3/?q=emotion&lang=en-GB&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=emotion&lang=en-US&ipa=%2F%C9%AA%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_6_69","topic":"Business and Humanities Studies","word":"emphasis","pos":"(n)","ipa":"/ˈem.fə.sɪs/","defVi":"sự nhấn mạnh, tầm quan trọng","defEn":"special importance, value, or attention given to something","examples":["The school puts a strong [emphasis] on science and mathematics. (=Dịch: Ngôi trường đặt sự nhấn mạnh lớn vào khoa học và toán học.)","He spoke with great [emphasis] on the need for immediate action. (=Dịch: Ông ấy đã nói với sự nhấn mạnh lớn về sự cần thiết của hành động ngay lập tức.)","There is an increasing [emphasis] on renewable energy in government policy. (=Dịch: Ngày càng có sự chú trọng nhiều hơn vào năng lượng tái tạo trong chính sách của chính phủ.)"],"ukAudio":"/ai_services/tts3/?q=emphasis&lang=en-GB&ipa=%2F%CB%88em.f%C9%99.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=emphasis&lang=en-US&ipa=%2F%CB%88em.f%C9%99.s%C9%AAs%2F"},{"id":"lv_6_70","topic":"Business and Humanities Studies","word":"emphasise","pos":"(v)","ipa":"/ˈɛm.fə.saɪz/","defVi":"nhấn mạnh, làm nổi bật","defEn":"to give special importance or attention to something","examples":["The lecturer wanted to [emphasise] the importance of original research. (=Dịch: Giảng viên muốn nhấn mạnh tầm quan trọng của việc nghiên cứu độc lập.)","You should [emphasise] your practical experience during the job interview. (=Dịch: Bạn nên nhấn mạnh kinh nghiệm thực tế của mình trong buổi phỏng vấn xin việc.)","Nutritionists repeatedly [emphasise] that breakfast is the most vital meal of the day. (=Dịch: Các chuyên gia dinh dưỡng liên tục nhấn mạnh rằng bữa sáng là bữa ăn quan trọng nhất trong ngày.)"],"ukAudio":"/ai_services/tts3/?q=emphasise&lang=en-GB&ipa=%2F%CB%88%C9%9Bm.f%C9%99.sa%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=emphasise&lang=en-US&ipa=%2F%CB%88%C9%9Bm.f%C9%99.sa%C9%AAz%2F"},{"id":"lv_6_71","topic":"Business and Humanities Studies","word":"enable","pos":"(v)","ipa":"/ɪˈneɪ.bəl/","defVi":"cho phép, tạo điều kiện thuận lợi, giúp có thể","defEn":"to make it possible for someone to do something, or for something to happen","examples":["Online courses [enable] people to study flexible hours from home. (=Dịch: Các khóa học trực tuyến cho phép mọi người học theo thời gian linh hoạt tại nhà.)","The new scholarship will [enable] talented students to attend university. (=Dịch: Học bổng mới sẽ tạo điều kiện cho các sinh viên tài năng theo học đại học.)","Smart technology can [enable] homes to use energy much more efficiently. (=Dịch: Công nghệ thông minh có thể giúp các ngôi nhà sử dụng năng lượng hiệu quả hơn nhiều.)"],"ukAudio":"/ai_services/tts3/?q=enable&lang=en-GB&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=enable&lang=en-US&ipa=%2F%C9%AA%CB%88ne%C9%AA.b%C9%99l%2F"},{"id":"lv_6_72","topic":"Business and Humanities Studies","word":"encode","pos":"(v)","ipa":"/ɪnˈkoʊd/","defVi":"mã hóa","defEn":"to convert information into a particular code or digital format","examples":["Scientists found a way to [encode] large amounts of data onto DNA strands. (=Dịch: Các nhà khoa học đã tìm ra cách mã hóa lượng dữ liệu lớn vào các chuỗi DNA.)","The software is designed to [encode] video files into a smaller size. (=Dịch: Phần mềm được thiết kế để mã hóa các tệp video sang kích thước nhỏ hơn.)","Our brains automatically [encode] sensory memories during daily experiences. (=Dịch: Bộ não của chúng ta tự động mã hóa ký ức giác quan trong các trải nghiệm hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=encode&lang=en-GB&ipa=%2F%C9%AAn%CB%88ko%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=encode&lang=en-US&ipa=%2F%C9%AAn%CB%88ko%CA%8Ad%2F"},{"id":"lv_6_73","topic":"Business and Humanities Studies","word":"encoding","pos":"(n)","ipa":"/ɪnˈkoʊ.dɪŋ/","defVi":"sự mã hóa","defEn":"the process of putting information into a special code or format","examples":["Data [encoding] ensures that sensitive information remains secure during transmission. (=Dịch: Việc mã hóa dữ liệu đảm bảo thông tin nhạy cảm vẫn an toàn trong quá trình truyền tải.)","The software supports the [encoding] of high-definition video files. (=Dịch: Phần mềm này hỗ trợ việc mã hóa các tệp video độ nét cao.)","Memory formation begins with the [encoding] of sensory information in the brain. (=Dịch: Sự hình thành trí nhớ bắt đầu bằng quá trình mã hóa thông tin cảm giác trong não bộ.)"],"ukAudio":"/ai_services/tts3/?q=encoding&lang=en-GB&ipa=%2F%C9%AAn%CB%88ko%CA%8A.d%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=encoding&lang=en-US&ipa=%2F%C9%AAn%CB%88ko%CA%8A.d%C9%AA%C5%8B%2F"},{"id":"lv_6_74","topic":"Business and Humanities Studies","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký nhập học","defEn":"to officially register or join a school, course, or group","examples":["She decided to [enroll] in an online coding course to boost her career. (=Dịch: Cô ấy quyết định đăng ký một khóa học lập trình trực tuyến để phát triển sự nghiệp.)","Parents must [enroll] their children before the end of this month. (=Dịch: Phụ huynh phải ghi danh cho con em mình trước cuối tháng này.)","Over five hundred students [enroll] at this university every semester. (=Dịch: Hơn năm trăm sinh viên nhập học tại trường đại học này mỗi học kỳ.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_6_75","topic":"Business and Humanities Studies","word":"entrepreneur","pos":"(n)","ipa":"/ˌɑːn.trə.prəˈnɝ/","defVi":"doanh nhân, người khởi nghiệp","defEn":"a person who starts a business and takes financial risks in the hope of profit","examples":["The young [entrepreneur] secured funding for her innovative tech startup. (=Dịch: Nữ doanh nhân trẻ đã nhận được vốn đầu tư cho công ty khởi nghiệp công nghệ sáng tạo của mình.)","Being a successful [entrepreneur] requires persistence and creativity. (=Dịch: Trở thành một doanh nhân thành công đòi hỏi sự kiên trì và sáng tạo.)","Many an [entrepreneur] faces significant challenges during the first year of business. (=Dịch: Nhiều doanh nhân phải đối mặt với những thử thách lớn trong năm đầu kinh doanh.)"],"ukAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%C9%9D%2F","usAudio":"/ai_services/tts3/?q=entrepreneur&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90n.tr%C9%99.pr%C9%99%CB%88n%C9%9D%2F"},{"id":"lv_6_76","topic":"Business and Humanities Studies","word":"episodic","pos":"(adj)","ipa":"/ˌɛp.əˈsɑː.dɪk/","defVi":"từng hồi, gián đoạn, xảy ra theo đợt","defEn":"happening only sometimes and not regularly; or composed of separate episodes","examples":["His interest in foreign languages was rather [episodic] and rarely lasted long. (=Dịch: Sự quan tâm của anh ấy đối với ngoại ngữ khá gián đoạn và hiếm khi kéo dài lâu.)","The patient suffered from [episodic] bouts of severe chest pain. (=Dịch: Bệnh nhân đã phải chịu đựng những cơn đau ngực dữ dội xảy ra theo từng đợt.)","The novel has an [episodic] structure where each chapter tells a distinct tale. (=Dịch: Cuốn tiểu thuyết có cấu trúc từng phần, trong đó mỗi chương kể một câu chuyện riêng biệt.)"],"ukAudio":"/ai_services/tts3/?q=episodic&lang=en-GB&ipa=%2F%CB%8C%C9%9Bp.%C9%99%CB%88s%C9%91%CB%90.d%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=episodic&lang=en-US&ipa=%2F%CB%8C%C9%9Bp.%C9%99%CB%88s%C9%91%CB%90.d%C9%AAk%2F"},{"id":"lv_6_77","topic":"Business and Humanities Studies","word":"equal","pos":"(adj)","ipa":"/ˈi.kwəl/","defVi":"bình đẳng, ngang bằng","defEn":"the same in size, amount, degree, or value","examples":["All citizens should have [equal] rights and opportunities. (=Dịch: Mọi công dân đều nên có quyền lợi và cơ hội bình đẳng.)","Divide the cake into six [equal] parts so everyone gets a slice. (=Dịch: Hãy chia chiếc bánh thành sáu phần bằng nhau để ai cũng có một phần.)","Both candidates are of [equal] ability and experience. (=Dịch: Cả hai ứng viên đều có năng lực và kinh nghiệm ngang nhau.)"],"ukAudio":"/ai_services/tts3/?q=equal&lang=en-GB&ipa=%2F%CB%88i.kw%C9%99l%2F","usAudio":"/ai_services/tts3/?q=equal&lang=en-US&ipa=%2F%CB%88i.kw%C9%99l%2F"},{"id":"lv_6_78","topic":"Business and Humanities Studies","word":"esteem","pos":"(n)","ipa":"/ɪˈstim/","defVi":"sự kính trọng, lòng quý trọng","defEn":"respect and admiration for someone or something","examples":["She is held in high [esteem] by her colleagues. (=Dịch: Cô ấy được các đồng nghiệp vô cùng kính trọng.)","Building self-[esteem] is crucial for personal development. (=Dịch: Xây dựng lòng tự trọng là điều rất quan trọng cho sự phát triển cá nhân.)","The professor won the [esteem] of all his students. (=Dịch: Vị giáo sư đã nhận được sự kính phục của tất cả sinh viên.)"],"ukAudio":"/ai_services/tts3/?q=esteem&lang=en-GB&ipa=%2F%C9%AA%CB%88stim%2F","usAudio":"/ai_services/tts3/?q=esteem&lang=en-US&ipa=%2F%C9%AA%CB%88stim%2F"},{"id":"lv_6_79","topic":"Business and Humanities Studies","word":"ethical","pos":"(adj)","ipa":"/ˈeθ.ɪ.kəl/","defVi":"thuộc về đạo đức, hợp luân thường đạo lý","defEn":"relating to beliefs about what is morally right and wrong","examples":["Consumers are increasingly demanding products made through [ethical] practices. (=Dịch: Người tiêu dùng ngày càng đòi hỏi các sản phẩm được sản xuất bằng các phương thức hợp đạo đức.)","The doctor was praised for his high [ethical] standards. (=Dịch: Vị bác sĩ đã được ca ngợi vì những tiêu chuẩn đạo đức cao của mình.)","Is it [ethical] to test cosmetic products on animals? (=Dịch: Liệu việc thử nghiệm mỹ phẩm trên động vật có hợp đạo đức hay không?)"],"ukAudio":"/ai_services/tts3/?q=ethical&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=ethical&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F"},{"id":"lv_6_80","topic":"Business and Humanities Studies","word":"ethnographic","pos":"(adj)","ipa":"/ˌeθ.nəˈɡræf.ɪk/","defVi":"thuộc dân tộc học","defEn":"relating to the scientific study and description of people and cultures","examples":["The anthropologist conducted extensive [ethnographic] fieldwork in rural villages. (=Dịch: Nhà nhân chủng học đã tiến hành nghiên cứu thực địa dân tộc học sâu rộng tại các ngôi làng nông thôn.)","This museum houses a vast collection of [ethnographic] artifacts. (=Dịch: Bảo tàng này lưu giữ một bộ sưu tập phong phú các hiện vật dân tộc học.)","Her dissertation used an [ethnographic] approach to explore local traditions. (=Dịch: Luận án của cô ấy đã sử dụng phương pháp tiếp cận dân tộc học để tìm hiểu các truyền thống địa phương.)"],"ukAudio":"/ai_services/tts3/?q=ethnographic&lang=en-GB&ipa=%2F%CB%8Ce%CE%B8.n%C9%99%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=ethnographic&lang=en-US&ipa=%2F%CB%8Ce%CE%B8.n%C9%99%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F"},{"id":"lv_6_81","topic":"Business and Humanities Studies","word":"ethnography","pos":"(n)","ipa":"/ɛθˈnɑː.ɡrə.fi/","defVi":"dân tộc học, phương pháp nghiên cứu dân tộc ký","defEn":"the scientific study and detailed description of individual human cultures","examples":["The researcher spent two years doing [ethnography] in a remote mountain village. (=Dịch: Nhà nghiên cứu đã dành hai năm để thực hiện nghiên cứu dân tộc ký tại một ngôi làng miền núi xa xôi.)","Her course in [ethnography] taught students how to conduct field interviews. (=Dịch: Khóa học dân tộc học của cô đã dạy sinh viên cách tiến hành phỏng vấn thực địa.)","Visual [ethnography] uses photography and video to document daily cultural practices. (=Dịch: Dân tộc ký thị giác sử dụng nhiếp ảnh và video để ghi lại các tập quán văn hóa hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=ethnography&lang=en-GB&ipa=%2F%C9%9B%CE%B8%CB%88n%C9%91%CB%90.%C9%A1r%C9%99.fi%2F","usAudio":"/ai_services/tts3/?q=ethnography&lang=en-US&ipa=%2F%C9%9B%CE%B8%CB%88n%C9%91%CB%90.%C9%A1r%C9%99.fi%2F"},{"id":"lv_6_82","topic":"Business and Humanities Studies","word":"evaluate","pos":"(v)","ipa":"/ɪˈvæl.ju.eɪt/","defVi":"đánh giá, định giá","defEn":"to form an opinion of the amount, value, or quality of something after careful thought","examples":["The doctor needs to [evaluate] the patient's condition before recommending surgery. (=Dịch: Bác sĩ cần đánh giá tình trạng của bệnh nhân trước khi đề xuất phẫu thuật.)","Companies often [evaluate] candidate performance during probation periods. (=Dịch: Các công ty thường đánh giá năng lực làm việc của ứng viên trong thời gian thử việc.)","We must carefully [evaluate] all available options before making a final decision. (=Dịch: Chúng ta phải đánh giá cẩn thận mọi lựa chọn sẵn có trước khi đưa ra quyết định cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=evaluate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6l.ju.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaluate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6l.ju.e%C9%AAt%2F"},{"id":"lv_6_83","topic":"Business and Humanities Studies","word":"evolutionary","pos":"(adj)","ipa":"/ˌɛv.əˈluː.ʃə.ner.i/","defVi":"mang tính tiến hóa, thuộc về tiến hóa","defEn":"relating to the gradual development and change of living things or ideas","examples":["Scientists study fossils to understand the [evolutionary] history of birds. (=Dịch: Các nhà khoa học nghiên cứu hóa thạch để hiểu được lịch sử tiến hóa của loài chim.)","The human brain has undergone significant [evolutionary] changes over millions of years. (=Dịch: Bộ não con người đã trải qua những thay đổi tiến hóa đáng kể qua hàng triệu năm.)","Technology undergoes an [evolutionary] process similar to biological adaptation. (=Dịch: Công nghệ trải qua một quá trình mang tính tiến hóa tương tự như sự thích nghi sinh học.)"],"ukAudio":"/ai_services/tts3/?q=evolutionary&lang=en-GB&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99.ner.i%2F","usAudio":"/ai_services/tts3/?q=evolutionary&lang=en-US&ipa=%2F%CB%8C%C9%9Bv.%C9%99%CB%88lu%CB%90.%CA%83%C9%99.ner.i%2F"},{"id":"lv_6_84","topic":"Business and Humanities Studies","word":"evolve","pos":"(v)","ipa":"/ɪˈvɑːlv/","defVi":"tiến hóa, phát triển dần dần","defEn":"to develop gradually, especially from a simple to a more complex form","examples":["The company needs to [evolve] its marketing strategy to attract younger customers. (=Dịch: Công ty cần phát triển chiến lược tiếp thị để thu hút khách hàng trẻ tuổi hơn.)","Scientists believe that birds did [evolve] from dinosaurs over millions of years. (=Dịch: Các nhà khoa học tin rằng loài chim đã tiến hóa từ khủng long qua hàng triệu năm.)","Online learning tools continue to [evolve] rapidly alongside technological advancements. (=Dịch: Các công cụ học tập trực tuyến tiếp tục phát triển nhanh chóng cùng với những tiến bộ công nghệ.)"],"ukAudio":"/ai_services/tts3/?q=evolve&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F","usAudio":"/ai_services/tts3/?q=evolve&lang=en-US&ipa=%2F%C9%AA%CB%88v%C9%91%CB%90lv%2F"},{"id":"lv_6_85","topic":"Business and Humanities Studies","word":"excellence","pos":"(n)","ipa":"/ˈek.sə.ləns/","defVi":"sự xuất sắc, sự ưu tú","defEn":"the quality of being outstanding or extremely good","examples":["The university is widely recognized for its academic [excellence]. (=Dịch: Trường đại học được công nhận rộng rãi nhờ sự xuất sắc trong học thuật.)","She was given an award for [excellence] in customer service. (=Dịch: Cô ấy đã được trao giải thưởng vì sự xuất sắc trong dịch vụ khách hàng.)","Our team always strives for [excellence] in every project. (=Dịch: Đội ngũ của chúng tôi luôn nỗ lực hướng tới sự hoàn hảo trong mọi dự án.)"],"ukAudio":"/ai_services/tts3/?q=excellence&lang=en-GB&ipa=%2F%CB%88ek.s%C9%99.l%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=excellence&lang=en-US&ipa=%2F%CB%88ek.s%C9%99.l%C9%99ns%2F"},{"id":"lv_6_86","topic":"Business and Humanities Studies","word":"executive","pos":"(n)","ipa":"/ɪɡˈzɛk.jə.tɪv/","defVi":"nhà điều hành, ủy viên ban quản trị","defEn":"a person who has a senior management position in a business or organization","examples":["The chief [executive] announced a new strategy to expand into international markets. (=Dịch: Vị giám đốc điều hành đã công bố một chiến lược mới để mở rộng sang các thị trường quốc tế.)","She worked hard for years before becoming a senior [executive] at the firm. (=Dịch: Cô ấy đã làm việc chăm chỉ nhiều năm trước khi trở thành một nhà điều hành cấp cao tại công ty.)","Company [executive] members met yesterday to discuss the annual budget. (=Dịch: Các thành viên ban điều hành công ty đã họp ngày hôm qua để thảo luận về ngân sách hàng năm.)"],"ukAudio":"/ai_services/tts3/?q=executive&lang=en-GB&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%9Bk.j%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=executive&lang=en-US&ipa=%2F%C9%AA%C9%A1%CB%88z%C9%9Bk.j%C9%99.t%C9%AAv%2F"},{"id":"lv_6_87","topic":"Business and Humanities Studies","word":"expectation","pos":"(n)","ipa":"/ˌɛk.spɛkˈteɪ.ʃən/","defVi":"kỳ vọng, sự mong đợi","defEn":"a belief that something will happen or that someone should achieve something","examples":["The final product completely exceeded our [expectations]. (=Dịch: Sản phẩm cuối cùng đã hoàn toàn vượt qua kỳ vọng của chúng tôi.)","Parents often place high academic [expectations] on their children. (=Dịch: Các bậc cha mẹ thường đặt nhiều kỳ vọng học tập cao vào con cái.)","There is widespread public [expectation] that inflation will drop soon. (=Dịch: Công chúng đang có sự kỳ vọng rộng rãi rằng lạm phát sẽ sớm giảm.)"],"ukAudio":"/ai_services/tts3/?q=expectation&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9Bk%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=expectation&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9Bk%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_88","topic":"Business and Humanities Studies","word":"expertise","pos":"(n)","ipa":"/ˌɛk.spɚˈtiz/","defVi":"chuyên môn, kiến thức chuyên sâu","defEn":"expert skill or knowledge in a particular field","examples":["We need to hire an external consultant with technical [expertise]. (=Dịch: Chúng ta cần thuê một chuyên gia tư vấn bên ngoài có chuyên môn kỹ thuật.)","She shared her [expertise] in digital marketing with the new interns. (=Dịch: Cô đã chia sẻ kiến thức chuyên môn về tiếp thị kỹ thuật số của mình cho các thực tập sinh mới.)","His [expertise] in financial management helped the company avoid bankruptcy. (=Dịch: Chuyên môn quản lý tài chính của anh ấy đã giúp công ty tránh khỏi bờ vực phá sản.)"],"ukAudio":"/ai_services/tts3/?q=expertise&lang=en-GB&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9A%CB%88tiz%2F","usAudio":"/ai_services/tts3/?q=expertise&lang=en-US&ipa=%2F%CB%8C%C9%9Bk.sp%C9%9A%CB%88tiz%2F"},{"id":"lv_6_89","topic":"Business and Humanities Studies","word":"explosion","pos":"(n)","ipa":"/ɪkˈsploʊ.ʒən/","defVi":"vụ nổ, sự bùng nổ","defEn":"a violent burst with a loud noise, or a sudden, rapid increase","examples":["The gas [explosion] caused severe damage to several nearby buildings. (=Dịch: Vụ nổ khí gas đã gây thiệt hại nghiêm trọng cho nhiều tòa nhà lân cận.)","The last decade saw an [explosion] in the use of smartphones worldwide. (=Dịch: Thập kỷ vừa qua đã chứng kiến một sự bùng nổ trong việc sử dụng điện thoại thông minh trên toàn thế giới.)","Firefighters responded quickly to contain the fire following the [explosion]. (=Dịch: Lực lượng cứu hỏa đã phản ứng nhanh chóng để khống chế đám cháy sau vụ nổ.)"],"ukAudio":"/ai_services/tts3/?q=explosion&lang=en-GB&ipa=%2F%C9%AAk%CB%88splo%CA%8A.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=explosion&lang=en-US&ipa=%2F%C9%AAk%CB%88splo%CA%8A.%CA%92%C9%99n%2F"},{"id":"lv_6_90","topic":"Business and Humanities Studies","word":"extend","pos":"(v)","ipa":"/ɪkˈstend/","defVi":"kéo dài, mở rộng, gia hạn","defEn":"to make something longer, larger, or last for a greater period of time","examples":["The teacher agreed to [extend] the deadline for the final essay by three days. (=Dịch: Giáo viên đã đồng ý gia hạn thời hạn nộp bài luận cuối kỳ thêm ba ngày.)","The company plans to [extend] its railway network to rural areas. (=Dịch: Công ty dự định mở rộng mạng lưới đường sắt đến các vùng nông thôn.)","She decided to [extend] her holiday in Paris for another week. (=Dịch: Cô ấy quyết định kéo dài kỳ nghỉ tại Paris thêm một tuần nữa.)"],"ukAudio":"/ai_services/tts3/?q=extend&lang=en-GB&ipa=%2F%C9%AAk%CB%88stend%2F","usAudio":"/ai_services/tts3/?q=extend&lang=en-US&ipa=%2F%C9%AAk%CB%88stend%2F"},{"id":"lv_6_91","topic":"Business and Humanities Studies","word":"external","pos":"(adj)","ipa":"/ɪkˈstɝː.nəl/","defVi":"bên ngoài, ngoại lai","defEn":"connected with or situated on the outside of something","examples":["The company hired an [external] consultant to evaluate its marketing strategy. (=Dịch: Công ty đã thuê một chuyên gia tư vấn bên ngoài để đánh giá chiến lược tiếp thị của mình.)","The [external] walls of the museum were painted bright white. (=Dịch: Những bức tường bên ngoài của bảo tàng đã được sơn màu trắng sáng.)","Students are evaluated by an [external] examiner at the end of the semester. (=Dịch: Sinh viên được đánh giá bởi một giám khảo bên ngoài vào cuối học kỳ.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_6_92","topic":"Business and Humanities Studies","word":"factual","pos":"(adj)","ipa":"/ˈfæk.tʃu.əl/","defVi":"dựa trên sự thật, thực tế","defEn":"using or consisting of real facts and information rather than opinions","examples":["The documentary provides a [factual] account of the historic event. (=Dịch: Bộ phim tài liệu cung cấp một lời tường thuật dựa trên sự thật về sự kiện lịch sử.)","Please ensure that your essay contains only [factual] information. (=Dịch: Vui lòng đảm bảo rằng bài luận của bạn chỉ chứa thông tin thực tế.)","The report was criticized for several [factual] errors. (=Dịch: Báo cáo bị chỉ trích vì có một số lỗi sai về mặt sự thật.)"],"ukAudio":"/ai_services/tts3/?q=factual&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=factual&lang=en-US&ipa=%2F%CB%88f%C3%A6k.t%CA%83u.%C9%99l%2F"},{"id":"lv_6_93","topic":"Business and Humanities Studies","word":"fluent","pos":"(adj)","ipa":"/ˈflu.ənt/","defVi":"trôi chảy, lưu loát","defEn":"able to speak or write a language easily and accurately","examples":["She is [fluent] in English and Spanish. (=Dịch: Cô ấy nói tiếng Anh và tiếng Tây Ban Nha rất trôi chảy.)","He wants to become a [fluent] speaker before studying abroad. (=Dịch: Anh ấy muốn nói năng lưu loát trước khi đi du học.)","With regular practice, you will develop [fluent] conversation skills. (=Dịch: Nhờ luyện tập thường xuyên, bạn sẽ phát triển được kỹ năng giao tiếp trôi chảy.)"],"ukAudio":"/ai_services/tts3/?q=fluent&lang=en-GB&ipa=%2F%CB%88flu.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=fluent&lang=en-US&ipa=%2F%CB%88flu.%C9%99nt%2F"},{"id":"lv_6_94","topic":"Business and Humanities Studies","word":"flute","pos":"(n)","ipa":"/fluːt/","defVi":"cây sáo","defEn":"a musical wind instrument played by blowing across a hole near one end","examples":["She has been playing the [flute] in the school orchestra for three years. (=Dịch: Cô ấy đã chơi sáo trong dàn nhạc của trường được ba năm.)","The gentle melody of the [flute] filled the concert hall. (=Dịch: Giai điệu nhẹ nhàng của cây sáo vang vọng khắp khán phòng hòa nhạc.)","He bought a silver [flute] as a birthday present for his daughter. (=Dịch: Ông ấy đã mua một cây sáo bằng bạc làm quà sinh nhật cho con gái mình.)"],"ukAudio":"/ai_services/tts3/?q=flute&lang=en-GB&ipa=%2Fflu%CB%90t%2F","usAudio":"/ai_services/tts3/?q=flute&lang=en-US&ipa=%2Fflu%CB%90t%2F"},{"id":"lv_6_95","topic":"Business and Humanities Studies","word":"follower","pos":"(n)","ipa":"/ˈfɑː.loʊ.ər/","defVi":"người theo dõi, tín đồ","defEn":"a person who supports, admires, or subscribes to someone or something","examples":["She gained more than one million [follower] accounts within a single week. (=Dịch: Cô ấy đã có thêm hơn một triệu tài khoản người theo dõi chỉ trong vòng một tuần.)","A great leader inspires trust and dedication in every [follower]. (=Dịch: Một nhà lãnh đạo tuyệt vời khơi dậy sự tin tưởng và cống hiến ở mỗi người đi theo.)","He has been a loyal [follower] of this philosophical school for decades. (=Dịch: Ông ấy đã là một môn đồ trung thành của trường phái triết học này suốt nhiều thập kỷ.)"],"ukAudio":"/ai_services/tts3/?q=follower&lang=en-GB&ipa=%2F%CB%88f%C9%91%CB%90.lo%CA%8A.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=follower&lang=en-US&ipa=%2F%CB%88f%C9%91%CB%90.lo%CA%8A.%C9%99r%2F"},{"id":"lv_6_96","topic":"Business and Humanities Studies","word":"fraud","pos":"(n)","ipa":"/frɑːd/","defVi":"sự lừa đảo, hành vi gian lận","defEn":"the crime of deceiving someone to gain money or other benefits illegally","examples":["He was arrested and convicted of credit card [fraud]. (=Dịch: Anh ta đã bị bắt và kết án vì hành vi gian lận thẻ tín dụng.)","Banks invest heavily in security systems to prevent online [fraud]. (=Dịch: Các ngân hàng đầu tư mạnh vào các hệ thống bảo mật để ngăn chặn lừa đảo trực tuyến.)","The audit uncovered widespread financial [fraud] within the organization. (=Dịch: Cuộc kiểm toán đã phát hiện ra hành vi gian lận tài chính lan rộng trong tổ chức.)"],"ukAudio":"/ai_services/tts3/?q=fraud&lang=en-GB&ipa=%2Ffr%C9%91%CB%90d%2F","usAudio":"/ai_services/tts3/?q=fraud&lang=en-US&ipa=%2Ffr%C9%91%CB%90d%2F"},{"id":"lv_6_97","topic":"Business and Humanities Studies","word":"freedom","pos":"(n)","ipa":"/ˈfriː.dəm/","defVi":"sự tự do, quyền tự do","defEn":"the power or right to act, speak, or think without restraint or control","examples":["Every citizen deserves the basic [freedom] to express their opinions. (=Dịch: Mọi công dân đều xứng đáng có được quyền tự do cơ bản để bày tỏ ý kiến của mình.)","Working as a freelancer gives him greater creative [freedom]. (=Dịch: Làm việc tự do mang lại cho anh ấy nhiều sự tự do sáng tạo hơn.)","The treaty ensured political [freedom] and stability for the smaller nation. (=Dịch: Hiệp ước đã đảm bảo sự tự do chính trị và ổn định cho quốc gia nhỏ hơn.)"],"ukAudio":"/ai_services/tts3/?q=freedom&lang=en-GB&ipa=%2F%CB%88fri%CB%90.d%C9%99m%2F","usAudio":"/ai_services/tts3/?q=freedom&lang=en-US&ipa=%2F%CB%88fri%CB%90.d%C9%99m%2F"},{"id":"lv_6_98","topic":"Business and Humanities Studies","word":"frequency","pos":"(n)","ipa":"/ˈfriː.kwən.si/","defVi":"tần suất, tần số","defEn":"the rate at which something happens or is repeated over a particular period","examples":["The [frequency] of extreme weather events has increased in recent years. (=Dịch: Tần suất xảy ra các hiện tượng thời tiết cực đoan đã tăng lên trong những năm gần đây.)","Bus services run with greater [frequency] during morning rush hours. (=Dịch: Các tuyến xe buýt chạy với tần suất dày hơn vào giờ cao điểm buổi sáng.)","Scientists adjusted the radio [frequency] to improve signal reception. (=Dịch: Các nhà khoa học đã điều chỉnh tần số vô tuyến để cải thiện khả năng thu tín hiệu.)"],"ukAudio":"/ai_services/tts3/?q=frequency&lang=en-GB&ipa=%2F%CB%88fri%CB%90.kw%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=frequency&lang=en-US&ipa=%2F%CB%88fri%CB%90.kw%C9%99n.si%2F"},{"id":"lv_6_99","topic":"Business and Humanities Studies","word":"friendship","pos":"(n)","ipa":"/ˈfrend.ʃɪp/","defVi":"tình bạn, tình hữu nghị","defEn":"a relationship between people who are friends","examples":["Their [friendship] has lasted for more than twenty years despite the long distance. (=Dịch: Tình bạn của họ đã kéo dài hơn hai mươi năm bất chấp khoảng cách xa xôi.)","Trust and mutual respect are essential foundations of a lasting [friendship]. (=Dịch: Sự tin tưởng và tôn trọng lẫn nhau là những nền tảng thiết yếu của một tình bạn bền lâu.)","The two countries signed an agreement to strengthen their bilateral [friendship]. (=Dịch: Hai quốc gia đã ký một hiệp định nhằm thắt chặt mối quan hệ hữu nghị song phương.)"],"ukAudio":"/ai_services/tts3/?q=friendship&lang=en-GB&ipa=%2F%CB%88frend.%CA%83%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=friendship&lang=en-US&ipa=%2F%CB%88frend.%CA%83%C9%AAp%2F"},{"id":"lv_6_100","topic":"Business and Humanities Studies","word":"fulfil","pos":"(v)","ipa":"/fʊlˈfɪl/","defVi":"hoàn thành, đáp ứng hoặc thực hiện","defEn":"to achieve, satisfy, or do something that is promised, expected, or required","examples":["He worked tirelessly to [fulfil] his childhood dream of becoming a pilot. (=Dịch: Anh ấy đã làm việc không mệt mỏi để thực hiện ước mơ thuở nhỏ là trở thành phi công.)","The company must [fulfil] all legal requirements before launching the product. (=Dịch: Công ty phải đáp ứng mọi yêu cầu pháp lý trước khi tung sản phẩm ra thị trường.)","She failed to [fulfil] the expectations of her demanding supervisor. (=Dịch: Cô ấy đã không đáp ứng được kỳ vọng của người giám sát khó tính của mình.)"],"ukAudio":"/ai_services/tts3/?q=fulfil&lang=en-GB&ipa=%2Ff%CA%8Al%CB%88f%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=fulfil&lang=en-US&ipa=%2Ff%CA%8Al%CB%88f%C9%AAl%2F"},{"id":"lv_6_101","topic":"Business and Humanities Studies","word":"fund","pos":"(n)","ipa":"/fʌnd/","defVi":"quỹ, nguồn tiền","defEn":"an amount of money collected or saved for a particular purpose","examples":["The charity set up a special [fund] to help disaster victims. (=Dịch: Tổ chức từ thiện đã thành lập một quỹ đặc biệt để giúp đỡ các nạn nhân thiên tai.)","They are organizing an event to raise money for the research [fund]. (=Dịch: Họ đang tổ chức một sự kiện để gây quỹ cho hoạt động nghiên cứu.)","The university has an emergency [fund] for students facing financial hardship. (=Dịch: Trường đại học có một quỹ khẩn cấp dành cho những sinh viên gặp khó khăn về tài chính.)"],"ukAudio":"/ai_services/tts3/?q=fund&lang=en-GB&ipa=%2Ff%CA%8Cnd%2F","usAudio":"/ai_services/tts3/?q=fund&lang=en-US&ipa=%2Ff%CA%8Cnd%2F"},{"id":"lv_6_102","topic":"Business and Humanities Studies","word":"gender","pos":"(n)","ipa":"/ˈdʒen.dɚ/","defVi":"giới tính","defEn":"the state of being male, female, or another identity, typically used with reference to social and cultural differences","examples":["The organization aims to promote [gender] equality in the workplace. (=Dịch: Tổ chức nhằm mục đích thúc đẩy bình đẳng giới tại nơi làm việc.)","Many companies are working to close the [gender] pay gap. (=Dịch: Nhiều công ty đang nỗ lực thu hẹp khoảng cách thu nhập theo giới tính.)","Applicants are asked to fill in their name, age, and [gender]. (=Dịch: Các ứng viên được yêu cầu điền tên, tuổi và giới tính của họ.)"],"ukAudio":"/ai_services/tts3/?q=gender&lang=en-GB&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=gender&lang=en-US&ipa=%2F%CB%88d%CA%92en.d%C9%9A%2F"},{"id":"lv_6_103","topic":"Business and Humanities Studies","word":"generation","pos":"(n)","ipa":"/ˌdʒen.əˈreɪ.ʃən/","defVi":"thế hệ, thế hệ con người","defEn":"all of the people born and living at about the same time","examples":["The younger [generation] is generally much more comfortable with digital technology. (=Dịch: Thế hệ trẻ nhìn chung quen thuộc và thoải mái hơn nhiều với công nghệ số.)","Stories and traditions have been passed down from one [generation] to the next. (=Dịch: Những câu chuyện và truyền thống đã được truyền từ thế hệ này sang thế hệ khác.)","We must protect the environment to ensure a viable future for the next [generation]. (=Dịch: Chúng ta phải bảo vệ môi trường để đảm bảo một tương lai bền vững cho thế hệ sau.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92en.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92en.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_104","topic":"Business and Humanities Studies","word":"geology","pos":"(n)","ipa":"/dʒiˈɑ.lə.dʒi/","defVi":"địa chất học","defEn":"the scientific study of the earth's structure, rocks, and history","examples":["The students went on a field trip to study the local [geology]. (=Dịch: Các sinh viên đã có một chuyến đi thực tế để nghiên cứu địa chất địa phương.)","Her interest in rocks led her to study [geology] at university. (=Dịch: Sự yêu thích các loại đá đã dẫn dắt cô theo học ngành địa chất học tại trường đại học.)","The [geology] of the region indicates ancient volcanic activity. (=Dịch: Địa chất của khu vực này cho thấy hoạt động núi lửa thời cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=geology&lang=en-GB&ipa=%2Fd%CA%92i%CB%88%C9%91.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=geology&lang=en-US&ipa=%2Fd%CA%92i%CB%88%C9%91.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_105","topic":"Business and Humanities Studies","word":"german","pos":"(adj)","ipa":"/ˈdʒɜːr.mən/","defVi":"(thuộc) nước Đức, người Đức, tiếng Đức","defEn":"relating to Germany, its people, or its language","examples":["The museum is hosting an exhibition of modern [German] art this month. (=Dịch: Bảo tàng đang tổ chức một triển lãm nghệ thuật Đức hiện đại trong tháng này.)","Many international students choose to enroll in a [German] university. (=Dịch: Nhiều sinh viên quốc tế lựa chọn đăng ký học tại một trường đại học của Đức.)","She has been studying the [German] language for more than three years. (=Dịch: Cô ấy đã học tiếng Đức được hơn ba năm.)"],"ukAudio":"/ai_services/tts3/?q=german&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99n%2F","usAudio":"/ai_services/tts3/?q=german&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9C%CB%90r.m%C9%99n%2F"},{"id":"lv_6_106","topic":"Business and Humanities Studies","word":"grade","pos":"(n)","ipa":"/ɡreɪd/","defVi":"điểm số, cấp lớp hoặc thứ bậc","defEn":"a score showing the quality of a student's work, or a school year level","examples":["She worked very hard to get a good [grade] on her final exam. (=Dịch: Cô ấy đã học tập rất chăm chỉ để đạt điểm cao trong kỳ thi cuối kỳ.)","My younger brother is currently in the fifth [grade]. (=Dịch: Em trai tôi hiện đang học lớp năm.)","This store sells meat of the highest [grade]. (=Dịch: Cửa hàng này bán loại thịt có phẩm cấp cao nhất.)"],"ukAudio":"/ai_services/tts3/?q=grade&lang=en-GB&ipa=%2F%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=grade&lang=en-US&ipa=%2F%C9%A1re%C9%AAd%2F"},{"id":"lv_6_107","topic":"Business and Humanities Studies","word":"graph","pos":"(n)","ipa":"/ɡræf/","defVi":"biểu đồ, đồ thị","defEn":"a diagram that shows the relationship between two or more sets of numbers or measurements","examples":["The line [graph] clearly illustrates the rise in global temperatures over the last century. (=Dịch: Biểu đồ đường thể hiện rõ sự gia tăng nhiệt độ toàn cầu trong thế kỷ qua.)","Candidates in the IELTS exam are often asked to describe a [graph]. (=Dịch: Thí sinh trong kỳ thi IELTS thường được yêu cầu miêu tả một biểu đồ.)","According to the [graph], sales peaked in the fourth quarter. (=Dịch: Theo biểu đồ, doanh số đạt đỉnh vào quý bốn.)"],"ukAudio":"/ai_services/tts3/?q=graph&lang=en-GB&ipa=%2F%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=graph&lang=en-US&ipa=%2F%C9%A1r%C3%A6f%2F"},{"id":"lv_6_108","topic":"Business and Humanities Studies","word":"guideline","pos":"(n)","ipa":"/ˈɡaɪd.laɪn/","defVi":"hướng dẫn, nguyên tắc chỉ đạo","defEn":"a general rule, principle, or piece of advice","examples":["The government issued a new [guideline] on healthy eating. (=Dịch: Chính phủ đã ban hành một hướng dẫn mới về việc ăn uống lành mạnh.)","Make sure you follow the formatting [guideline] when writing your essay. (=Dịch: Hãy chắc chắn rằng bạn tuân theo hướng dẫn định dạng khi viết bài luận.)","The safety [guideline] helps reduce workplace accidents. (=Dịch: Nguyên tắc an toàn giúp giảm thiểu tai nạn tại nơi làm việc.)"],"ukAudio":"/ai_services/tts3/?q=guideline&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AAd.la%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=guideline&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AAd.la%C9%AAn%2F"},{"id":"lv_6_109","topic":"Business and Humanities Studies","word":"gymnastics","pos":"(n)","ipa":"/dʒɪmˈnæs.tɪks/","defVi":"môn thể dục dụng cụ","defEn":"a sport involving exercises that require balance, strength, and flexibility","examples":["She has been practicing [gymnastics] since she was five years old. (=Dịch: Cô ấy đã tập luyện thể dục dụng cụ từ khi mới năm tuổi.)","The [gymnastics] competition attracted athletes from all over the world. (=Dịch: Cuộc thi thể dục dụng cụ đã thu hút các vận động viên từ khắp nơi trên thế giới.)","Doing [gymnastics] helps improve core strength and body coordination. (=Dịch: Tập thể dục dụng cụ giúp cải thiện sức mạnh cơ lõi và sự phối hợp của cơ thể.)"],"ukAudio":"/ai_services/tts3/?q=gymnastics&lang=en-GB&ipa=%2Fd%CA%92%C9%AAm%CB%88n%C3%A6s.t%C9%AAks%2F","usAudio":"/ai_services/tts3/?q=gymnastics&lang=en-US&ipa=%2Fd%CA%92%C9%AAm%CB%88n%C3%A6s.t%C9%AAks%2F"},{"id":"lv_6_110","topic":"Business and Humanities Studies","word":"handed","pos":"(adj)","ipa":"/ˈhæn.dɪd/","defVi":"thuận tay (kết hợp trong từ ghép như left-handed)","defEn":"having or using hands of a particular kind, especially using one hand more naturally than the other","examples":["He is left-[handed] and finds some scissors difficult to use. (=Dịch: Cậu ấy thuận tay trái và thấy một số loại kéo khá khó dùng.)","A two-[handed] backhand can give tennis players more power. (=Dịch: Cú đánh trái tay bằng hai tay có thể mang lại nhiều lực hơn cho các vận động viên quần vợt.)","The tool is designed for right-[handed] workers only. (=Dịch: Dụng cụ này chỉ được thiết kế dành riêng cho những người lao động thuận tay phải.)"],"ukAudio":"/ai_services/tts3/?q=handed&lang=en-GB&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=handed&lang=en-US&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd%2F"},{"id":"lv_6_111","topic":"Business and Humanities Studies","word":"handedness","pos":"(n)","ipa":"/ˈhæn.dɪd.nəs/","defVi":"thuận tay (tay phải hoặc tay trái)","defEn":"the tendency to use one hand rather than the other more naturally and skillfully","examples":["Genetic factors play a major role in determining a person's [handedness]. (=Dịch: Các yếu tố di truyền đóng vai trò quan trọng trong việc xác định độ thuận tay của một người.)","Researchers observed the [handedness] of chimpanzees during tool use experiments. (=Dịch: Các nhà nghiên cứu đã quan sát sự thuận tay của tinh tinh trong các thí nghiệm sử dụng công cụ.)","The school provides special scissors for students regardless of their [handedness]. (=Dịch: Trường cung cấp kéo đặc biệt cho học sinh bất kể các em thuận tay nào.)"],"ukAudio":"/ai_services/tts3/?q=handedness&lang=en-GB&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=handedness&lang=en-US&ipa=%2F%CB%88h%C3%A6n.d%C9%AAd.n%C9%99s%2F"},{"id":"lv_6_112","topic":"Business and Humanities Studies","word":"highlight","pos":"(n)","ipa":"/ˈhaɪˌlaɪt/","defVi":"điểm nổi bật, phần đặc sắc nhất","defEn":"the most interesting, memorable, or important part of something","examples":["The boat tour along the coast was the [highlight] of our summer trip. (=Dịch: Chuyến tham quan bằng thuyền dọc bờ biển là điểm nổi bật nhất trong chuyến du lịch mùa hè của chúng tôi.)","The final goal was the main [highlight] of the entire football match. (=Dịch: Bàn thắng cuối cùng là khoảnh khắc ấn tượng nhất của toàn bộ trận bóng đá.)","Meeting the author was an unexpected [highlight] of the book fair. (=Dịch: Gặp gỡ tác giả là một điểm nhấn bất ngờ tại hội chợ sách.)"],"ukAudio":"/ai_services/tts3/?q=highlight&lang=en-GB&ipa=%2F%CB%88ha%C9%AA%CB%8Cla%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=highlight&lang=en-US&ipa=%2F%CB%88ha%C9%AA%CB%8Cla%C9%AAt%2F"},{"id":"lv_6_113","topic":"Business and Humanities Studies","word":"hypothesis","pos":"(n)","ipa":"/haɪˈpɑː.θə.sɪs/","defVi":"giả thuyết","defEn":"an idea or explanation that is suggested and tested through study and experimentation","examples":["The results of the test supported their initial [hypothesis]. (=Dịch: Kết quả của cuộc thử nghiệm đã ủng hộ giả thuyết ban đầu của họ.)","A good scientist always seeks evidence to prove or disprove a [hypothesis]. (=Dịch: Một nhà khoa học giỏi luôn tìm kiếm bằng chứng để chứng minh hoặc bác bỏ một giả thuyết.)","She formulated a 새로운 [hypothesis] based on the unexpected findings. (=Dịch: Cô ấy đã đưa ra một giả thuyết mới dựa trên những phát hiện bất ngờ.)"],"ukAudio":"/ai_services/tts3/?q=hypothesis&lang=en-GB&ipa=%2Fha%C9%AA%CB%88p%C9%91%CB%90.%CE%B8%C9%99.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=hypothesis&lang=en-US&ipa=%2Fha%C9%AA%CB%88p%C9%91%CB%90.%CE%B8%C9%99.s%C9%AAs%2F"},{"id":"lv_6_114","topic":"Business and Humanities Studies","word":"iceland","pos":"(n)","ipa":"/ˈaɪs.lənd/","defVi":"nước Băng Đảo, quốc gia Ai-xơ-len","defEn":"an island country in the North Atlantic Ocean known for its natural landscapes","examples":["Many tourists visit [iceland] to see the stunning northern lights. (=Dịch: Nhiều du khách đến thăm Băng Đảo để ngắm hiện tượng cực quang tuyệt đẹp.)","Volcanoes and glaciers are common geological features of [iceland]. (=Dịch: Núi lửa và sông băng là những đặc điểm địa chất phổ biến của Băng Đảo.)","She booked a trip to explore the natural hot springs in [iceland]. (=Dịch: Cô ấy đã đặt một chuyến đi để khám phá các suối nước nóng tự nhiên ở Băng Đảo.)"],"ukAudio":"/ai_services/tts3/?q=iceland&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F","usAudio":"/ai_services/tts3/?q=iceland&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99nd%2F"},{"id":"lv_6_115","topic":"Business and Humanities Studies","word":"icelanders","pos":"(n)","ipa":"/ˈaɪs.lən.dɚz/","defVi":"người Băng Đảo, người Ai-xơ-len","defEn":"the people who are native to or live in Iceland","examples":["Most [icelanders] speak fluent English in addition to their native language. (=Dịch: Hầu hết người Băng Đảo nói tiếng Anh trôi chảy bên cạnh tiếng mẹ đẻ của họ.)","Fishing has always played a vital role in the daily life of [icelanders]. (=Dịch: Đánh bắt cá luôn đóng một vai trò quan trọng trong đời sống hàng ngày của người Băng Đảo.)","Many [icelanders] enjoy reading books during the long winter nights. (=Dịch: Nhiều người Băng Đảo thích đọc sách trong những đêm mùa đông dài.)"],"ukAudio":"/ai_services/tts3/?q=icelanders&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.l%C9%99n.d%C9%9Az%2F","usAudio":"/ai_services/tts3/?q=icelanders&lang=en-US&ipa=%2F%CB%88a%C9%AAs.l%C9%99n.d%C9%9Az%2F"},{"id":"lv_6_116","topic":"Business and Humanities Studies","word":"icelandic","pos":"(adj)","ipa":"/aɪsˈlæn.dɪk/","defVi":"thuộc về Ai-xơ-len (Băng Đảo)","defEn":"connected with Iceland, its people, or its language","examples":["We enjoyed traditional [icelandic] food during our holiday. (=Dịch: Chúng tôi đã thưởng thức các món ăn truyền thống của Ai-xơ-len trong suốt kỳ nghỉ.)","The [icelandic] landscape is famous for its volcanoes and glaciers. (=Dịch: Cảnh quan Ai-xơ-len nổi tiếng với những ngọn núi lửa và sông băng.)","Learning the [icelandic] language can be quite challenging for beginners. (=Dịch: Học tiếng Ai-xơ-len có thể khá thử thách đối với người mới bắt đầu.)"],"ukAudio":"/ai_services/tts3/?q=icelandic&lang=en-GB&ipa=%2Fa%C9%AAs%CB%88l%C3%A6n.d%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=icelandic&lang=en-US&ipa=%2Fa%C9%AAs%CB%88l%C3%A6n.d%C9%AAk%2F"},{"id":"lv_6_117","topic":"Business and Humanities Studies","word":"illegal","pos":"(adj)","ipa":"/ɪˈliː.ɡəl/","defVi":"bất hợp pháp, phạm pháp","defEn":"forbidden by law or against established rules","examples":["It is [illegal] to drive a car without a valid license. (=Dịch: Lái xe ô tô mà không có bằng lái hợp lệ là hành vi bất hợp pháp.)","The government took strict measures against [illegal] logging. (=Dịch: Chính phủ đã thực hiện các biện pháp nghiêm ngặt để chống lại nạn khai thác gỗ trái phép.)","Downloading copyrighted material without permission is [illegal]. (=Dịch: Tải xuống các tài liệu có bản quyền khi chưa được phép là phạm pháp.)"],"ukAudio":"/ai_services/tts3/?q=illegal&lang=en-GB&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F","usAudio":"/ai_services/tts3/?q=illegal&lang=en-US&ipa=%2F%C9%AA%CB%88li%CB%90.%C9%A1%C9%99l%2F"},{"id":"lv_6_118","topic":"Business and Humanities Studies","word":"impair","pos":"(v)","ipa":"/ɪmˈper/","defVi":"làm suy giảm, làm tổn hại, làm yếu đi","defEn":"to weaken, damage, or reduce the quality or strength of something","examples":["Lack of adequate sleep can severely [impair] your ability to concentrate. (=Dịch: Thiếu ngủ đủ giấc có thể làm suy giảm nghiêm trọng khả năng tập trung của bạn.)","Loud noises over prolonged periods may [impair] hearing permanently. (=Dịch: Tiếng ồn lớn trong thời gian dài có thể làm tổn hại thính giác vĩnh viễn.)","Alcohol consumption can [impair] a driver's reflexes and judgment. (=Dịch: Uống rượu bia có thể làm suy giảm phản xạ và khả năng phán đoán của người lái xe.)"],"ukAudio":"/ai_services/tts3/?q=impair&lang=en-GB&ipa=%2F%C9%AAm%CB%88per%2F","usAudio":"/ai_services/tts3/?q=impair&lang=en-US&ipa=%2F%C9%AAm%CB%88per%2F"},{"id":"lv_6_119","topic":"Business and Humanities Studies","word":"impose","pos":"(v)","ipa":"/ɪmˈpoʊz/","defVi":"áp đặt, đánh thuế, áp dụng","defEn":"to officially force a rule, tax, or punishment to be obeyed or accepted","examples":["The city council decided to [impose] a fine on illegal parking. (=Dịch: Hội đồng thành phố đã quyết định áp dụng mức phạt đối với hành vi đỗ xe trái phép.)","Parents should not [impose] their own career choices on their children. (=Dịch: Cha mẹ không nên áp đặt lựa chọn nghề nghiệp của mình lên con cái.)","The government may [impose] higher tariffs on imported goods. (=Dịch: Chính phủ có thể sẽ áp mức thuế quan cao hơn đối với hàng hóa nhập khẩu.)"],"ukAudio":"/ai_services/tts3/?q=impose&lang=en-GB&ipa=%2F%C9%AAm%CB%88po%CA%8Az%2F","usAudio":"/ai_services/tts3/?q=impose&lang=en-US&ipa=%2F%C9%AAm%CB%88po%CA%8Az%2F"},{"id":"lv_6_120","topic":"Business and Humanities Studies","word":"inaccurate","pos":"(adj)","ipa":"/ɪnˈæk.jər.ət/","defVi":"không chính xác, sai lệch","defEn":"not correct or not completely exact","examples":["The initial weather forecast turned out to be completely [inaccurate]. (=Dịch: Dự báo thời tiết ban đầu hóa ra hoàn toàn không chính xác.)","Using outdated data led to an [inaccurate] conclusion. (=Dịch: Việc sử dụng dữ liệu lỗi thời đã dẫn đến một kết luận thiếu chính xác.)","The article was retracted because it contained [inaccurate] statistics. (=Dịch: Bài báo đã bị rút lại vì nó chứa các số liệu thống kê sai lệch.)"],"ukAudio":"/ai_services/tts3/?q=inaccurate&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C3%A6k.j%C9%99r.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=inaccurate&lang=en-US&ipa=%2F%C9%AAn%CB%88%C3%A6k.j%C9%99r.%C9%99t%2F"},{"id":"lv_6_121","topic":"Business and Humanities Studies","word":"inclusive","pos":"(adj)","ipa":"/ɪnˈkluː.sɪv/","defVi":"bao quát, mang tính hòa nhập, bao hàm toàn diện","defEn":"deliberately including all types of people, things, or opinions","examples":["The school strives to create an [inclusive] environment for students with disabilities. (=Dịch: Nhà trường nỗ lực tạo ra một môi trường hòa nhập cho học sinh khuyết tật.)","The resort offers an [inclusive] package that covers all meals and activities. (=Dịch: Khu nghỉ dưỡng cung cấp gói trọn gói bao gồm tất cả các bữa ăn và hoạt động.)","We need more [inclusive] policies that consider the needs of minority groups. (=Dịch: Chúng ta cần nhiều chính sách mang tính bao hàm hơn để tính đến nhu cầu của các nhóm thiểu số.)"],"ukAudio":"/ai_services/tts3/?q=inclusive&lang=en-GB&ipa=%2F%C9%AAn%CB%88klu%CB%90.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=inclusive&lang=en-US&ipa=%2F%C9%AAn%CB%88klu%CB%90.s%C9%AAv%2F"},{"id":"lv_6_122","topic":"Business and Humanities Studies","word":"independence","pos":"(n)","ipa":"/ˌɪn.dɪˈpɛn.dəns/","defVi":"Sự độc lập, tự chủ","defEn":"The state of being free from outside control or influence.","examples":["The nation celebrated fifty years of [independence] with grand parades. (=Dịch: Quốc gia này đã kỷ niệm 50 năm ngày giành độc lập bằng các cuộc diễu hành lớn.)","Going to university teaches young adults financial and personal [independence]. (=Dịch: Vào đại học dạy cho những người trẻ tuổi sự độc lập về tài chính và cá nhân.)","She values her professional [independence] and prefers working as a freelancer. (=Dịch: Cô ấy coi trọng sự độc lập trong công việc và thích làm nghề tự do hơn.)"],"ukAudio":"/ai_services/tts3/?q=independence&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.d%C9%AA%CB%88p%C9%9Bn.d%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=independence&lang=en-US&ipa=%2F%CB%8C%C9%AAn.d%C9%AA%CB%88p%C9%9Bn.d%C9%99ns%2F"},{"id":"lv_6_123","topic":"Business and Humanities Studies","word":"initial","pos":"(adj)","ipa":"/ɪˈnɪʃ.əl/","defVi":"ban đầu, đầu tiên","defEn":"happening at the beginning; first","examples":["Our [initial] plan was to travel by train, but we decided to fly instead. (=Dịch: Kế hoạch ban đầu của chúng tôi là đi bằng tàu hỏa, nhưng sau đó chúng tôi quyết định đi máy bay.)","The company's [initial] investment proved to be highly profitable. (=Dịch: Khoản đầu tư ban đầu của công ty đã chứng minh là mang lại lợi nhuận rất cao.)","After overcoming the [initial] difficulties, she began to enjoy her new job. (=Dịch: Sau khi vượt qua những khó khăn ban đầu, cô ấy bắt đầu thấy yêu thích công việc mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=initial&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=initial&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_6_124","topic":"Business and Humanities Studies","word":"initiative","pos":"(n)","ipa":"/ɪˈnɪʃ.ə.tɪv/","defVi":"sáng kiến, chương trình hành động mới","defEn":"a new plan or process designed to solve a problem or achieve a goal","examples":["The government launched an educational [initiative] to promote digital literacy. (=Dịch: Chính phủ đã đưa ra một sáng kiến giáo dục nhằm nâng cao hiểu biết về công nghệ số.)","Employees are encouraged to take the [initiative] and suggest improvements. (=Dịch: Nhân viên được khuyến khích chủ động đưa ra các đề xuất cải tiến.)","This recycling [initiative] has helped reduce neighborhood waste significantly. (=Dịch: Sáng kiến tái chế này đã giúp giảm lượng rác thải trong khu dân cư một cách đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=initiative&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=initiative&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.t%C9%AAv%2F"},{"id":"lv_6_125","topic":"Business and Humanities Studies","word":"innovation","pos":"(n)","ipa":"/ˌɪn.əˈveɪ.ʃən/","defVi":"sự đổi mới, sáng kiến mới","defEn":"a new idea, method, or product; the introduction of something new","examples":["Technological [innovation] has transformed the way we communicate. (=Dịch: Sự đổi mới công nghệ đã thay đổi cách chúng ta giao tiếp.)","The company encourages employee [innovation] through monthly brainstorming sessions. (=Dịch: Công ty khuyến khích sự đổi mới của nhân viên thông qua các buổi họp lên ý tưởng hàng tháng.)","This smart device is the latest [innovation] in healthcare monitoring. (=Dịch: Thiết bị thông minh này là sáng kiến mới nhất trong việc theo dõi sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=innovation&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=innovation&lang=en-US&ipa=%2F%CB%8C%C9%AAn.%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_126","topic":"Business and Humanities Studies","word":"insight","pos":"(n)","ipa":"/ˈɪn.saɪt/","defVi":"sự hiểu biết sâu sắc, cái nhìn sâu sắc","defEn":"a deep and clear understanding of a complicated problem or situation","examples":["The study provides valuable [insight] into the causes of climate change. (=Dịch: Nghiên cứu này cung cấp cái nhìn sâu sắc và có giá trị về nguyên nhân của biến đổi khí hậu.)","Her extensive experience gave her unique [insight] into customer behavior. (=Dịch: Kinh nghiệm dày dặn đã mang lại cho cô cái nhìn sâu sắc độc đáo về hành vi của khách hàng.)","The lecture offered fresh [insight] on modern economic challenges. (=Dịch: Bài giảng đã mang đến những góc nhìn mới mẻ về các thách thức kinh tế hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=insight&lang=en-GB&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=insight&lang=en-US&ipa=%2F%CB%88%C9%AAn.sa%C9%AAt%2F"},{"id":"lv_6_127","topic":"Business and Humanities Studies","word":"insist","pos":"(v)","ipa":"/ɪnˈsɪst/","defVi":"khăng khăng, nằng nặc đòi hoặc khẳng định chắc chắn","defEn":"to demand something forcefully or maintain a statement firmly","examples":["My parents [insist] that I finish my homework before watching TV. (=Dịch: Bố mẹ tôi khăng khăng bắt tôi phải làm xong bài tập trước khi xem tivi.)","He continued to [insist] on his innocence despite the evidence. (=Dịch: Anh ta tiếp tục khẳng định mình vô tội bất chấp các bằng chứng.)","They [insist] that all visitors must wear a security badge. (=Dịch: Họ nhất quyết yêu cầu mọi khách tham quan phải đeo thẻ an ninh.)"],"ukAudio":"/ai_services/tts3/?q=insist&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=insist&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%AAst%2F"},{"id":"lv_6_128","topic":"Business and Humanities Studies","word":"inspire","pos":"(v)","ipa":"/ɪnˈspaɪ.ɚ/","defVi":"truyền cảm hứng, khuyến khích","defEn":"to give someone the motivation or enthusiasm to do something","examples":["Her speech will [inspire] many young students to study science. (=Dịch: Bài phát biểu của cô ấy sẽ truyền cảm hứng cho nhiều học sinh trẻ theo đuổi ngành khoa học.)","The beauty of the mountains can [inspire] great art. (=Dịch: Vẻ đẹp của những ngọn núi có thể truyền cảm hứng cho các tác phẩm nghệ thuật tuyệt vời.)","His success continues to [inspire] people around the world. (=Dịch: Thành công của anh ấy tiếp tục truyền cảm hứng cho mọi người trên khắp thế giới.)"],"ukAudio":"/ai_services/tts3/?q=inspire&lang=en-GB&ipa=%2F%C9%AAn%CB%88spa%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=inspire&lang=en-US&ipa=%2F%C9%AAn%CB%88spa%C9%AA.%C9%9A%2F"},{"id":"lv_6_129","topic":"Business and Humanities Studies","word":"instant","pos":"(adj)","ipa":"/ˈɪn.stənt/","defVi":"tức thì, ngay lập tức","defEn":"happening immediately or made quickly","examples":["The new social media campaign became an [instant] success. (=Dịch: Chiến dịch truyền thông mạng xã hội mới đã trở thành một thành công ngay lập tức.)","Many busy workers rely on [instant] coffee to start their mornings. (=Dịch: Nhiều nhân viên bận rộn dựa vào cà phê hòa tan để bắt đầu buổi sáng của họ.)","Mobile apps provide users with [instant] access to news updates. (=Dịch: Các ứng dụng di động cung cấp cho người dùng quyền truy cập tin tức cập nhật tức thì.)"],"ukAudio":"/ai_services/tts3/?q=instant&lang=en-GB&ipa=%2F%CB%88%C9%AAn.st%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=instant&lang=en-US&ipa=%2F%CB%88%C9%AAn.st%C9%99nt%2F"},{"id":"lv_6_130","topic":"Business and Humanities Studies","word":"intellectual","pos":"(adj)","ipa":"/ˌɪn.təˈlɛk.tʃu.əl/","defVi":"thuộc về trí tuệ, có tri thức","defEn":"relating to the ability to think logically and understand complex ideas","examples":["Chess is a game that requires significant [intellectual] effort and focus. (=Dịch: Cờ vua là một trò chơi đòi hỏi sự nỗ lực trí tuệ và mức độ tập trung đáng kể.)","University provides a stimulating [intellectual] environment for research. (=Dịch: Trường đại học mang lại một môi trường học thuật trí tuệ đầy tính kích thích cho việc nghiên cứu.)","She enjoys engaging in deep [intellectual] discussions with her colleagues. (=Dịch: Cô ấy thích tham gia vào các cuộc thảo luận học thuật mang tính trí tuệ sâu sắc với đồng nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=intellectual&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88l%C9%9Bk.t%CA%83u.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=intellectual&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88l%C9%9Bk.t%CA%83u.%C9%99l%2F"},{"id":"lv_6_131","topic":"Business and Humanities Studies","word":"intelligence","pos":"(n)","ipa":"/ɪnˈtɛl.ə.dʒəns/","defVi":"trí thông minh, sự thông minh","defEn":"the ability to learn, understand, and make judgments or have opinions","examples":["Emotional [intelligence] is just as important as academic ability in the workplace. (=Dịch: Trí tuệ cảm xúc cũng quan trọng không kém gì năng lực học thuật tại nơi làm việc.)","Scientists are studying whether certain animals possess high [intelligence]. (=Dịch: Các nhà khoa học đang nghiên cứu xem liệu một số loài động vật có sở hữu trí thông minh cao hay không.)","The rapid development of artificial [intelligence] is reshaping modern industries. (=Dịch: Sự phát triển nhanh chóng của trí tuệ nhân tạo đang tái định hình các ngành công nghiệp hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=intelligence&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=intelligence&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bl.%C9%99.d%CA%92%C9%99ns%2F"},{"id":"lv_6_132","topic":"Business and Humanities Studies","word":"interaction","pos":"(n)","ipa":"/ˌɪn.tərˈæk.ʃən/","defVi":"sự tương tác, sự giao tiếp","defEn":"communication or direct involvement with someone or something","examples":["Social [interaction] is essential for a child's psychological development. (=Dịch: Tương tác xã hội rất cần thiết cho sự phát triển tâm lý của trẻ em.)","The classroom activities encourage active [interaction] between students. (=Dịch: Các hoạt động trong lớp học khuyến khích sự tương tác tích cực giữa các học sinh.)","Scientists study the complex [interaction] between humans and the environment. (=Dịch: Các nhà khoa học nghiên cứu sự tương tác phức tạp giữa con người và môi trường.)"],"ukAudio":"/ai_services/tts3/?q=interaction&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99r%CB%88%C3%A6k.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interaction&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99r%CB%88%C3%A6k.%CA%83%C9%99n%2F"},{"id":"lv_6_133","topic":"Business and Humanities Studies","word":"interviewee","pos":"(n)","ipa":"/ˌɪn.tər.vjuːˈiː/","defVi":"người được phỏng vấn","defEn":"a person who answers questions in an interview","examples":["The [interviewee] answered every question with confidence and clarity. (=Dịch: Người được phỏng vấn đã trả lời mọi câu hỏi một cách tự tin và rõ ràng.)","Each [interviewee] was given fifteen minutes to present their portfolio. (=Dịch: Mỗi ứng viên phỏng vấn được dành 15 phút để trình bày hồ sơ năng lực của mình.)","The researcher recorded the audio of each [interviewee] with their permission. (=Dịch: Nhà nghiên cứu đã ghi âm từng người được phỏng vấn với sự cho phép của họ.)"],"ukAudio":"/ai_services/tts3/?q=interviewee&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99r.vju%CB%90%CB%88i%CB%90%2F","usAudio":"/ai_services/tts3/?q=interviewee&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99r.vju%CB%90%CB%88i%CB%90%2F"},{"id":"lv_6_134","topic":"Business and Humanities Studies","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, sự khảo sát kỹ lưỡng","defEn":"an official examination of the facts about a situation, crime, etc.","examples":["The police launched a thorough [investigation] into the cause of the fire. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về nguyên nhân của vụ hỏa hoạn.)","An internal [investigation] revealed widespread financial misconduct. (=Dịch: Một cuộc điều tra nội bộ đã vạch trần sai phạm tài chính trên diện rộng.)","The incident is currently under [investigation] by federal authorities. (=Dịch: Sự việc hiện đang được các cơ quan chức năng liên bang điều tra.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_135","topic":"Business and Humanities Studies","word":"isolate","pos":"(v)","ipa":"/ˈaɪ.sə.leɪt/","defVi":"cô lập, cách ly, tách rời","defEn":"to separate someone or something from other people or things","examples":["Doctors decided to [isolate] the patient to prevent the disease from spreading. (=Dịch: Các bác sĩ quyết định cách ly bệnh nhân để ngăn căn bệnh lây lan.)","Scientists managed to [isolate] the specific gene responsible for the condition. (=Dịch: Các nhà khoa học đã tách riêng được loại gen chịu trách nhiệm gây ra tình trạng này.)","Heavy snowfall can easily [isolate] mountain villages from the rest of the country. (=Dịch: Tuyết rơi dày có thể dễ dàng cô lập các ngôi làng trên núi khỏi phần còn lại của đất nước.)"],"ukAudio":"/ai_services/tts3/?q=isolate&lang=en-GB&ipa=%2F%CB%88a%C9%AA.s%C9%99.le%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=isolate&lang=en-US&ipa=%2F%CB%88a%C9%AA.s%C9%99.le%C9%AAt%2F"},{"id":"lv_6_136","topic":"Business and Humanities Studies","word":"italy","pos":"(n)","ipa":"/ˈɪt̬.əl.i/","defVi":"nước Ý, nước I-ta-li-a","defEn":"a country in southern Europe known for its rich history, culture, and cuisine","examples":["Many tourists visit [Italy] every year to see ancient Roman architecture. (=Dịch: Nhiều du khách đến thăm nước Ý hàng năm để chiêm ngưỡng kiến trúc La Mã cổ đại.)","She spent her summer studying art history in [Italy]. (=Dịch: Cô ấy đã dành mùa hè của mình để học lịch sử nghệ thuật ở Ý.)","[Italy] is famous worldwide for its delicious food, fashion, and art. (=Dịch: Ý nổi tiếng trên toàn thế giới về ẩm thực ngon, thời trang và nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=italy&lang=en-GB&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=italy&lang=en-US&ipa=%2F%CB%88%C9%AAt%CC%AC.%C9%99l.i%2F"},{"id":"lv_6_137","topic":"Business and Humanities Studies","word":"justify","pos":"(v)","ipa":"/ˈdʒʌs.tə.faɪ/","defVi":"biện minh, chứng minh là hợp lý hoặc đúng đắn","defEn":"to show or prove that something is reasonable, necessary, or right","examples":["The manager had to [justify] the extra expenses to the director. (=Dịch: Người quản lý đã phải giải trình các khoản chi phí phát sinh trước giám đốc.)","Nothing can [justify] such rude behavior toward customers. (=Dịch: Không gì có thể biện minh cho hành vi thô lỗ như vậy đối với khách hàng.)","You must [justify] your conclusions with concrete data in your essay. (=Dịch: Bạn phải chứng minh các kết luận của mình bằng dữ liệu cụ thể trong bài luận.)"],"ukAudio":"/ai_services/tts3/?q=justify&lang=en-GB&ipa=%2F%CB%88d%CA%92%CA%8Cs.t%C9%99.fa%C9%AA%2F","usAudio":"/ai_services/tts3/?q=justify&lang=en-US&ipa=%2F%CB%88d%CA%92%CA%8Cs.t%C9%99.fa%C9%AA%2F"},{"id":"lv_6_138","topic":"Business and Humanities Studies","word":"kart","pos":"(n)","ipa":"/kɑːrt/","defVi":"xe đua mini (xe go-kart)","defEn":"a small, open motor vehicle with four wheels, used mainly for racing","examples":["He spent his weekend driving a go-[kart] with his friends at the track. (=Dịch: Anh ấy đã dành kỳ nghỉ cuối tuần lái xe đua mini cùng bạn bè trên đường đua.)","Many professional Formula One drivers started their racing careers in a [kart]. (=Dịch: Nhiều tay đua Công thức 1 chuyên nghiệp đã bắt đầu sự nghiệp đua xe của mình bằng xe đua mini.)","Safety helmets and gloves are required before you get into the [kart]. (=Dịch: Mũ bảo hiểm và găng tay an toàn là bắt buộc trước khi bạn bước vào xe đua mini.)"],"ukAudio":"/ai_services/tts3/?q=kart&lang=en-GB&ipa=%2Fk%C9%91%CB%90rt%2F","usAudio":"/ai_services/tts3/?q=kart&lang=en-US&ipa=%2Fk%C9%91%CB%90rt%2F"},{"id":"lv_6_139","topic":"Business and Humanities Studies","word":"keyboard","pos":"(n)","ipa":"/ˈki.bɔrd/","defVi":"bàn phím (máy tính hoặc nhạc cụ)","defEn":"a set of keys on a computer or musical instrument used for typing or playing music","examples":["She wiped the dust off her computer [keyboard] before starting work. (=Dịch: Cô ấy lau sạch bụi trên bàn phím máy tính trước khi bắt đầu làm việc.)","He learned to play the electric [keyboard] when he was ten years old. (=Dịch: Anh ấy đã học chơi đàn phím điện tử khi mới mười tuổi.)","A mechanical [keyboard] can improve typing speed and comfort. (=Dịch: Một chiếc bàn phím cơ có thể cải thiện tốc độ và sự thoải mái khi gõ phím.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki.b%C9%94rd%2F"},{"id":"lv_6_140","topic":"Business and Humanities Studies","word":"laterality","pos":"(n)","ipa":"/ˌlæt̬.əˈræl.ə.t̬i/","defVi":"tính thuận một bên (như thuận tay phải hoặc trái)","defEn":"the preference for using one side of the body, such as being right- or left-handed","examples":["Handedness is the most common form of human [laterality]. (=Dịch: Sự thuận tay là hình thức phổ biến nhất của tính thuận một bên ở con người.)","The study investigated brain [laterality] and language processing. (=Dịch: Nghiên cứu đã điều tra tính chuyên biệt bán cầu não và quá trình xử lý ngôn ngữ.)","Researchers measured [laterality] in animals to understand brain development. (=Dịch: Các nhà nghiên cứu đã đo lường tính thuận một bên ở động vật để hiểu về sự phát triển của não bộ.)"],"ukAudio":"/ai_services/tts3/?q=laterality&lang=en-GB&ipa=%2F%CB%8Cl%C3%A6t%CC%AC.%C9%99%CB%88r%C3%A6l.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=laterality&lang=en-US&ipa=%2F%CB%8Cl%C3%A6t%CC%AC.%C9%99%CB%88r%C3%A6l.%C9%99.t%CC%ACi%2F"},{"id":"lv_6_141","topic":"Business and Humanities Studies","word":"lifespan","pos":"(n)","ipa":"/ˈlaɪf.spæn/","defVi":"tuổi thọ, vòng đời","defEn":"the length of time for which a person or animal lives or a thing functions","examples":["Medical advances have significantly increased the human [lifespan]. (=Dịch: Những tiến bộ y học đã làm tăng đáng kể tuổi thọ của con người.)","Proper maintenance can extend the [lifespan] of your car engine. (=Dịch: Bảo dưỡng đúng cách có thể kéo dài tuổi thọ động cơ ô tô của bạn.)","Some species of tortoises have an average [lifespan] of over a century. (=Dịch: Một số loài rùa cạn có tuổi thọ trung bình trên một thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=lifespan&lang=en-GB&ipa=%2F%CB%88la%C9%AAf.sp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=lifespan&lang=en-US&ipa=%2F%CB%88la%C9%AAf.sp%C3%A6n%2F"},{"id":"lv_6_142","topic":"Business and Humanities Studies","word":"loneliness","pos":"(n)","ipa":"/ˈloʊn.li.nəs/","defVi":"sự cô đơn, nỗi cô quạnh","defEn":"a feeling of sadness because one has no friends or company","examples":["Elderly people who live alone often suffer from severe [loneliness]. (=Dịch: Người cao tuổi sống một mình thường phải chịu đựng sự cô đơn sâu sắc.)","Moving to a new city can trigger feelings of isolation and [loneliness]. (=Dịch: Chuyển đến một thành phố mới có thể gây ra cảm giác bị cô lập và cô đơn.)","She took up painting as a creative way to cope with [loneliness]. (=Dịch: Cô ấy bắt đầu vẽ tranh như một cách sáng tạo để đối phó với nỗi cô đơn.)"],"ukAudio":"/ai_services/tts3/?q=loneliness&lang=en-GB&ipa=%2F%CB%88lo%CA%8An.li.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=loneliness&lang=en-US&ipa=%2F%CB%88lo%CA%8An.li.n%C9%99s%2F"},{"id":"lv_6_143","topic":"Business and Humanities Studies","word":"lonely","pos":"(adj)","ipa":"/ˈloʊn.li/","defVi":"cô đơn, lẻ loi, quạnh quẽ","defEn":"sad because one has no friends or company","examples":["Moving to a foreign city made him feel isolated and [lonely] at first. (=Dịch: Việc chuyển đến một thành phố xa lạ ban đầu khiến anh cảm thấy bị cô lập và cô đơn.)","Volunteers visit [lonely] seniors in nursing homes to offer companionship. (=Dịch: Các tình nguyện viên đến thăm những người già cô đơn trong viện dưỡng lão để bầu bạn cùng họ.)","The lighthouse stood on a [lonely] stretch of the rocky coastline. (=Dịch: Ngọn hải đăng đứng sừng sững trên một dải bờ biển đá quạnh quẽ.)"],"ukAudio":"/ai_services/tts3/?q=lonely&lang=en-GB&ipa=%2F%CB%88lo%CA%8An.li%2F","usAudio":"/ai_services/tts3/?q=lonely&lang=en-US&ipa=%2F%CB%88lo%CA%8An.li%2F"},{"id":"lv_6_144","topic":"Business and Humanities Studies","word":"loss","pos":"(n)","ipa":"/lɔːs/","defVi":"sự mất mát, tổn thất, thua lỗ","defEn":"the state of no longer having something or having less of it","examples":["The company reported a massive financial [loss] in the final quarter. (=Dịch: Công ty đã báo cáo một khoản thua lỗ tài chính khổng lồ trong quý cuối cùng.)","Diet and exercise are effective strategies for sustainable weight [loss]. (=Dịch: Chế độ ăn uống và tập thể dục là những chiến lược hiệu quả để giảm cân bền vững.)","Deforestation leads to an irreversible [loss] of biodiversity. (=Dịch: Nạn phá rừng dẫn đến sự mất mát không thể khắc phục của đa dạng sinh học.)"],"ukAudio":"/ai_services/tts3/?q=loss&lang=en-GB&ipa=%2Fl%C9%94%CB%90s%2F","usAudio":"/ai_services/tts3/?q=loss&lang=en-US&ipa=%2Fl%C9%94%CB%90s%2F"},{"id":"lv_6_145","topic":"Business and Humanities Studies","word":"luxury","pos":"(n)","ipa":"/ˈlʌk.ʃə.ri/","defVi":"sự xa xỉ, sang trọng hoặc hàng xa xỉ phẩm","defEn":"great comfort and extravagant living, or something expensive and not essential","examples":["They stayed in a five-star hotel and enjoyed the ultimate [luxury]. (=Dịch: Họ đã ở tại một khách sạn năm sao và tận hưởng sự xa hoa bậc nhất.)","During the economic crisis, dining out became an unaffordable [luxury] for many. (=Dịch: Trong cuộc khủng hoảng kinh tế, đi ăn ngoài đã trở thành một sự xa xỉ khó với tới đối với nhiều người.)","The brand is internationally known for designing high-end [luxury] goods. (=Dịch: Thương hiệu này nổi tiếng quốc tế với việc thiết kế các mặt hàng xa xỉ cao cấp.)"],"ukAudio":"/ai_services/tts3/?q=luxury&lang=en-GB&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=luxury&lang=en-US&ipa=%2F%CB%88l%CA%8Ck.%CA%83%C9%99.ri%2F"},{"id":"lv_6_146","topic":"Business and Humanities Studies","word":"mentally","pos":"(adv)","ipa":"/ˈmɛn.tə.li/","defVi":"về mặt tinh thần, về mặt tâm trí","defEn":"in a way that relates to the mind or mental processes","examples":["Athletes must prepare [mentally] as well as physically for the race. (=Dịch: Các vận động viên phải chuẩn bị cả về tinh thần lẫn thể chất cho cuộc đua.)","Solving complex puzzles helps keep people [mentally] sharp. (=Dịch: Giải các câu đố phức tạp giúp giữ cho đầu óc con người luôn minh mẫn.)","She felt [mentally] exhausted after a long day of negotiations. (=Dịch: Cô ấy cảm thấy kiệt sức về mặt tinh thần sau một ngày dài đàm phán.)"],"ukAudio":"/ai_services/tts3/?q=mentally&lang=en-GB&ipa=%2F%CB%88m%C9%9Bn.t%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=mentally&lang=en-US&ipa=%2F%CB%88m%C9%9Bn.t%C9%99.li%2F"},{"id":"lv_6_147","topic":"Business and Humanities Studies","word":"methodology","pos":"(n)","ipa":"/ˌmeθ.əˈdɑː.lə.dʒi/","defVi":"phương pháp luận, phương pháp nghiên cứu","defEn":"a system of methods and principles used in a particular discipline or study","examples":["The research paper clearly outlines the [methodology] used to gather data. (=Dịch: Bài báo nghiên cứu trình bày rõ ràng phương pháp luận được dùng để thu thập dữ liệu.)","We adopted a new [methodology] to improve the efficiency of our project. (=Dịch: Chúng tôi đã áp dụng một phương pháp nghiên cứu mới để nâng cao hiệu quả của dự án.)","Critics questioned the [methodology] behind the controversial survey. (=Dịch: Các nhà phê bình đã đặt câu hỏi về phương pháp luận đằng sau cuộc khảo sát gây tranh cãi.)"],"ukAudio":"/ai_services/tts3/?q=methodology&lang=en-GB&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=methodology&lang=en-US&ipa=%2F%CB%8Cme%CE%B8.%C9%99%CB%88d%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_148","topic":"Business and Humanities Studies","word":"motivation","pos":"(n)","ipa":"/ˌmoʊ.t̬əˈveɪ.ʃən/","defVi":"động lực","defEn":"the reason or desire that drives someone to act or achieve a goal","examples":["Financial reward is not the only [motivation] for employees to work hard. (=Dịch: Phần thưởng tài chính không phải là động lực duy nhất để nhân viên làm việc chăm chỉ.)","She lost the [motivation] to study after failing the midterm exam. (=Dịch: Cô ấy đã mất động lực học tập sau khi thi trượt kỳ thi giữa kỳ.)","Setting clear goals can boost your daily [motivation] and productivity. (=Dịch: Đặt ra các mục tiêu rõ ràng có thể thúc đẩy động lực và năng suất hàng ngày của bạn.)"],"ukAudio":"/ai_services/tts3/?q=motivation&lang=en-GB&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motivation&lang=en-US&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_149","topic":"Business and Humanities Studies","word":"networking","pos":"(n)","ipa":"/ˈnet.wɜːr.kɪŋ/","defVi":"hoạt động kết nối, xây dựng mạng lưới quan hệ","defEn":"the activity of meeting people who might be useful to know for your career or business","examples":["Attending industry conferences is a great way to improve your [networking] skills. (=Dịch: Tham dự các hội nghị ngành là một cách tuyệt vời để cải thiện kỹ năng kết nối quan hệ của bạn.)","Professional [networking] helped him secure a high-paying job abroad. (=Dịch: Việc mở rộng mạng lưới quan hệ nghề nghiệp đã giúp anh ấy có được một công việc lương cao ở nước ngoài.)","Social media platforms have revolutionized business [networking] in recent years. (=Dịch: Các nền tảng mạng xã hội đã cách mạng hóa việc xây dựng mạng lưới kinh doanh trong những năm gần đây.)"],"ukAudio":"/ai_services/tts3/?q=networking&lang=en-GB&ipa=%2F%CB%88net.w%C9%9C%CB%90r.k%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=networking&lang=en-US&ipa=%2F%CB%88net.w%C9%9C%CB%90r.k%C9%AA%C5%8B%2F"},{"id":"lv_6_150","topic":"Business and Humanities Studies","word":"nursing","pos":"(n)","ipa":"/ˈnɜr.sɪŋ/","defVi":"ngành điều dưỡng, nghề y tá","defEn":"the profession or practice of caring for sick or injured people","examples":["She decided to pursue a career in [nursing] after volunteering at a hospital. (=Dịch: Cô ấy quyết định theo đuổi sự nghiệp trong ngành điều dưỡng sau khi làm tình nguyện tại một bệnh viện.)","The university offers a four-year degree in [nursing]. (=Dịch: Trường đại học cung cấp chương trình cấp bằng bốn năm về ngành điều dưỡng.)","Good [nursing] care is essential for a patient's quick recovery. (=Dịch: Sự chăm sóc điều dưỡng tốt là rất cần thiết cho sự hồi phục nhanh chóng của bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=nursing&lang=en-GB&ipa=%2F%CB%88n%C9%9Cr.s%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=nursing&lang=en-US&ipa=%2F%CB%88n%C9%9Cr.s%C9%AA%C5%8B%2F"},{"id":"lv_6_151","topic":"Business and Humanities Studies","word":"nurture","pos":"(v)","ipa":"/ˈnɝː.tʃɚ/","defVi":"nuôi dưỡng, bồi dưỡng","defEn":"to care for and encourage the growth or development of someone or something","examples":["Parents strive to [nurture] a love of reading in their young children. (=Dịch: Các bậc cha mẹ nỗ lực nuôi dưỡng niềm yêu thích đọc sách ở con nhỏ.)","The program was designed to [nurture] new musical talent across the nation. (=Dịch: Chương trình được thiết kế để bồi dưỡng những tài năng âm nhạc mới trên toàn quốc.)","Good managers know how to [nurture] positive relationships among team members. (=Dịch: Những người quản lý giỏi biết cách nuôi dưỡng các mối quan hệ tích cực giữa các thành viên trong nhóm.)"],"ukAudio":"/ai_services/tts3/?q=nurture&lang=en-GB&ipa=%2F%CB%88n%C9%9D%CB%90.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=nurture&lang=en-US&ipa=%2F%CB%88n%C9%9D%CB%90.t%CA%83%C9%9A%2F"},{"id":"lv_6_152","topic":"Business and Humanities Studies","word":"obesity","pos":"(n)","ipa":"/oʊˈbiː.sə.t̬i/","defVi":"bệnh béo phì, tình trạng béo phì","defEn":"the state of being extremely overweight in a way that is dangerous for health","examples":["Childhood [obesity] has become a major public health concern globally. (=Dịch: Béo phì ở trẻ em đã trở thành một mối lo ngại lớn về sức khỏe cộng đồng trên toàn cầu.)","A balanced diet and daily exercise can help prevent [obesity]. (=Dịch: Chế độ ăn uống cân bằng và tập thể dục hàng ngày có thể giúp ngăn ngừa béo phì.)","The government launched a campaign to raise awareness about the risks of [obesity]. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao nhận thức về những nguy cơ của bệnh béo phì.)"],"ukAudio":"/ai_services/tts3/?q=obesity&lang=en-GB&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=obesity&lang=en-US&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_6_153","topic":"Business and Humanities Studies","word":"observation","pos":"(n)","ipa":"/ˌɑːb.zɚˈveɪ.ʃən/","defVi":"sự quan sát, theo dõi","defEn":"the act of watching something carefully, especially to learn more about it","examples":["The doctor kept the patient under close [observation] overnight. (=Dịch: Bác sĩ đã giữ bệnh nhân lại để theo dõi chặt chẽ qua đêm.)","Scientific discoveries often begin with a simple [observation] in the natural world. (=Dịch: Các phát hiện khoa học thường bắt đầu bằng một quan sát đơn giản trong thế giới tự nhiên.)","Her keen powers of [observation] helped her notice subtle clues at the scene. (=Dịch: Khả năng quan sát nhạy bén đã giúp cô nhận ra những manh mối tinh tế tại hiện trường.)"],"ukAudio":"/ai_services/tts3/?q=observation&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=observation&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90b.z%C9%9A%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_6_154","topic":"Business and Humanities Studies","word":"opener","pos":"(n)","ipa":"/ˈoʊ.pən.ər/","defVi":"dụng cụ mở (chai, hộp); trận/vở diễn mở màn","defEn":"a device used for opening tins, bottles, or other containers; an initial event","examples":["Could you please pass me the bottle [opener] from the kitchen counter? (=Dịch: Bạn có thể làm ơn đưa giúp tôi cái mở nắp chai từ kệ bếp được không?)","The team won their season [opener] by two goals. (=Dịch: Đội bóng đã giành chiến thắng trong trận đấu mở màn mùa giải với cách biệt hai bàn.)","She used a can [opener] to prepare the soup for dinner. (=Dịch: Cô ấy đã dùng đồ khui đồ hộp để chuẩn bị món súp cho bữa tối.)"],"ukAudio":"/ai_services/tts3/?q=opener&lang=en-GB&ipa=%2F%CB%88o%CA%8A.p%C9%99n.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=opener&lang=en-US&ipa=%2F%CB%88o%CA%8A.p%C9%99n.%C9%99r%2F"},{"id":"lv_6_155","topic":"Business and Humanities Studies","word":"operational","pos":"(adj)","ipa":"/ˌɑː.pəˈreɪ.ʃən.əl/","defVi":"sẵn sàng hoạt động, đang vận hành; thuộc về vận hành","defEn":"ready to be used, working properly, or relating to the functioning of an organization","examples":["The new airport terminal will become fully [operational] next month. (=Dịch: Nhà ga sân bay mới sẽ đi vào hoạt động đầy đủ vào tháng tới.)","The company managed to reduce its [operational] costs by adopting new software. (=Dịch: Công ty đã cắt giảm được chi phí vận hành bằng cách áp dụng phần mềm mới.)","All emergency systems are currently tested and fully [operational]. (=Dịch: Tất cả các hệ thống khẩn cấp hiện đã được kiểm tra và hoàn toàn sẵn sàng hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=operational&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=operational&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_156","topic":"Business and Humanities Studies","word":"oral","pos":"(adj)","ipa":"/ˈɔːr.əl/","defVi":"bằng lời nói, truyền miệng; thuộc về miệng","defEn":"spoken rather than written; relating to the mouth","examples":["Students must pass an [oral] examination in French before graduating. (=Dịch: Sinh viên phải vượt qua kỳ thi vấn đáp tiếng Pháp trước khi tốt nghiệp.)","Good [oral] hygiene helps prevent tooth decay and gum disease. (=Dịch: Vệ sinh răng miệng tốt giúp ngăn ngừa sâu răng và bệnh về nướu.)","The story was preserved through [oral] tradition for centuries. (=Dịch: Câu chuyện đã được lưu truyền qua truyền thống truyền miệng suốt nhiều thế kỷ.)"],"ukAudio":"/ai_services/tts3/?q=oral&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=oral&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F"},{"id":"lv_6_157","topic":"Business and Humanities Studies","word":"orient","pos":"(v)","ipa":"/ˈɔr.iˌɛnt/","defVi":"định hướng, hướng dẫn làm quen","defEn":"to direct someone or something toward a particular goal, idea, or direction","examples":["The training program aims to [orient] new employees to the company's work culture. (=Dịch: Chương trình đào tạo nhằm mục đích định hướng cho các nhân viên mới về văn hóa làm việc của công ty.)","It took him a few minutes to [orient] himself after stepping out of the subway station. (=Dịch: Anh ấy mất vài phút để định hướng phương hướng sau khi bước ra khỏi ga tàu điện ngầm.)","The course is designed to [orient] students toward practical career skills. (=Dịch: Khóa học được thiết kế để hướng sinh viên tới các kỹ năng nghề nghiệp thực tế.)"],"ukAudio":"/ai_services/tts3/?q=orient&lang=en-GB&ipa=%2F%CB%88%C9%94r.i%CB%8C%C9%9Bnt%2F","usAudio":"/ai_services/tts3/?q=orient&lang=en-US&ipa=%2F%CB%88%C9%94r.i%CB%8C%C9%9Bnt%2F"},{"id":"lv_6_158","topic":"Business and Humanities Studies","word":"overhead","pos":"(adj)","ipa":"/ˌoʊ.vərˈhed/","defVi":"ở trên đầu, trên cao","defEn":"located, positioned, or operating above one's head","examples":["Passengers placed their luggage in the [overhead] compartment. (=Dịch: Hành khách đã đặt hành lý của họ vào khoang chứa đồ phía trên đầu.)","A flock of birds flew across the [overhead] sky. (=Dịch: Một đàn chim bay ngang qua bầu trời phía trên cao.)","The city plans to replace [overhead] power cables with underground systems. (=Dịch: Thành phố có kế hoạch thay thế hệ thống cáp điện trên cao bằng mạng lưới ngầm.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%88hed%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%8Co%CA%8A.v%C9%99r%CB%88hed%2F"},{"id":"lv_6_159","topic":"Business and Humanities Studies","word":"pedal","pos":"(n)","ipa":"/ˈpɛd.əl/","defVi":"bàn đạp (xe đạp, xe hơi, đàn piano)","defEn":"a foot-operated lever used to control or propel a vehicle or machine","examples":["Press the brake [pedal] firmly to stop the car safely. (=Dịch: Hãy đạp mạnh bàn đạp phanh để dừng xe an toàn.)","His foot slipped off the bicycle [pedal] while riding uphill. (=Dịch: Chân của cậu ấy bị trượt khỏi bàn đạp xe đạp khi đang lên dốc.)","The pianist skillfully used the sustain [pedal] during the performance. (=Dịch: Nghệ sĩ dương cầm đã sử dụng bàn đạp vang một cách điêu luyện trong suốt buổi biểu diễn.)"],"ukAudio":"/ai_services/tts3/?q=pedal&lang=en-GB&ipa=%2F%CB%88p%C9%9Bd.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=pedal&lang=en-US&ipa=%2F%CB%88p%C9%9Bd.%C9%99l%2F"},{"id":"lv_6_160","topic":"Business and Humanities Studies","word":"pioneer","pos":"(n)","ipa":"/ˌpaɪ.əˈnɪr/","defVi":"người tiên phong, người mở đường","defEn":"a person who is one of the first to develop an area, idea, or activity","examples":["Marie Curie was a [pioneer] in the field of radioactivity research. (=Dịch: Marie Curie là người tiên phong trong lĩnh vực nghiên cứu phóng xạ.)","The company is considered a [pioneer] of renewable energy solutions. (=Dịch: Công ty được coi là đơn vị tiên phong về các giải pháp năng lượng tái tạo.)","Early aviation [pioneer] figures paved the way for modern travel. (=Dịch: Những nhân vật tiên phong trong ngành hàng không thời kỳ đầu đã mở đường cho ngành du lịch hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=pioneer&lang=en-GB&ipa=%2F%CB%8Cpa%C9%AA.%C9%99%CB%88n%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=pioneer&lang=en-US&ipa=%2F%CB%8Cpa%C9%AA.%C9%99%CB%88n%C9%AAr%2F"},{"id":"lv_6_161","topic":"Business and Humanities Studies","word":"pleasure","pos":"(n)","ipa":"/ˈpleʒ.ɚ/","defVi":"sự thích thú, niềm vui thích, hân hạnh","defEn":"a feeling of happy satisfaction and enjoyment","examples":["Reading fiction books gives her a great deal of [pleasure]. (=Dịch: Đọc tiểu thuyết mang lại cho cô ấy rất nhiều niềm vui thích.)","It was an absolute [pleasure] to meet your family today. (=Dịch: Thật là một niềm vinh hạnh tuyệt đối khi được gặp gia đình bạn hôm nay.)","He plays the guitar purely for his own [pleasure]. (=Dịch: Anh ấy chơi đàn ghi-ta hoàn toàn chỉ để thỏa mãn niềm vui của riêng mình.)"],"ukAudio":"/ai_services/tts3/?q=pleasure&lang=en-GB&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=pleasure&lang=en-US&ipa=%2F%CB%88ple%CA%92.%C9%9A%2F"},{"id":"lv_6_162","topic":"Business and Humanities Studies","word":"podcast","pos":"(n)","ipa":"/ˈpɑːd.kæst/","defVi":"tập tin âm thanh kỹ thuật số, chương trình phát thanh số","defEn":"a digital audio recording made available on the internet for downloading or streaming","examples":["I usually listen to an educational [podcast] on my way to work. (=Dịch: Tôi thường nghe một chương trình phát thanh giáo dục trên đường đi làm.)","She decided to start her own [podcast] about modern literature. (=Dịch: Cô ấy quyết định bắt đầu chương trình podcast của riêng mình về văn học hiện đại.)","This weekly [podcast] covers the latest scientific discoveries. (=Dịch: Chương trình phát thanh hàng tuần này đưa tin về những phát hiện khoa học mới nhất.)"],"ukAudio":"/ai_services/tts3/?q=podcast&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90d.k%C3%A6st%2F","usAudio":"/ai_services/tts3/?q=podcast&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90d.k%C3%A6st%2F"},{"id":"lv_6_163","topic":"Business and Humanities Studies","word":"politic","pos":"(adj)","ipa":"/ˈpɑː.lə.tɪk/","defVi":"khôn ngoan, sáng suốt, thận trọng","defEn":"showing good judgment, wise, and prudent in practical matters","examples":["It seemed [politic] to remain silent during the heated debate. (=Dịch: Giữ im lặng trong cuộc tranh luận gay gắt dường như là điều khôn ngoan.)","She decided that a [politic] apology would resolve the conflict quickly. (=Dịch: Cô ấy quyết định rằng một lời xin lỗi khôn khéo sẽ nhanh chóng giải quyết xung đột.)","In business negotiations, a [politic] response is often better than a blunt refusal. (=Dịch: Trong các cuộc đàm phán kinh doanh, một phản hồi thận trọng thường tốt hơn là lời từ chối thẳng thừng.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90.l%C9%99.t%C9%AAk%2F"},{"id":"lv_6_164","topic":"Business and Humanities Studies","word":"poorly","pos":"(adv)","ipa":"/ˈpʊr.li/","defVi":"kém cỏi, tồi tàn, không tốt","defEn":"badly, inadequately, or to an unsatisfactory standard","examples":["The old bridge was [poorly] maintained and needed urgent repairs. (=Dịch: Cây cầu cũ được bảo trì kém và cần được sửa chữa khẩn cấp.)","She performed [poorly] on the exam due to lack of sleep. (=Dịch: Cô ấy làm bài thi kém do bị thiếu ngủ.)","The room was [poorly] lit, making it hard to read anything. (=Dịch: Căn phòng thiếu ánh sáng, khiến việc đọc sách trở nên khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=poorly&lang=en-GB&ipa=%2F%CB%88p%CA%8Ar.li%2F","usAudio":"/ai_services/tts3/?q=poorly&lang=en-US&ipa=%2F%CB%88p%CA%8Ar.li%2F"},{"id":"lv_6_165","topic":"Business and Humanities Studies","word":"preference","pos":"(n)","ipa":"/ˈprɛf.ɚ.əns/","defVi":"sở thích, sự ưu tiên","defEn":"a greater liking for one alternative over another","examples":["Consumers have a strong [preference] for organic and eco-friendly products. (=Dịch: Người tiêu dùng có sự ưu tiên mạnh mẽ đối với các sản phẩm hữu cơ và thân thiện với môi trường.)","Please state your dietary [preference] when registering for the conference. (=Dịch: Vui lòng nêu rõ sở thích ăn uống của bạn khi đăng ký tham dự hội nghị.)","He expressed a [preference] for working remotely rather than in the office. (=Dịch: Anh ấy bày tỏ sự thích làm việc từ xa hơn là làm tại văn phòng.)"],"ukAudio":"/ai_services/tts3/?q=preference&lang=en-GB&ipa=%2F%CB%88pr%C9%9Bf.%C9%9A.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=preference&lang=en-US&ipa=%2F%CB%88pr%C9%9Bf.%C9%9A.%C9%99ns%2F"},{"id":"lv_6_166","topic":"Business and Humanities Studies","word":"prevention","pos":"(n)","ipa":"/prɪˈven.ʃən/","defVi":"sự phòng ngừa, sự ngăn chặn","defEn":"the act of stopping something bad or dangerous from happening","examples":["Crime [prevention] is one of the main responsibilities of the local police. (=Dịch: Phòng chống tội phạm là một trong những trách nhiệm chính của cảnh sát địa phương.)","The government launched a public campaign on fire [prevention] during the dry season. (=Dịch: Chính phủ đã phát động một chiến dịch tuyên truyền về phòng cháy trong mùa khô.)","Proper diet and exercise are key elements in disease [prevention]. (=Dịch: Chế độ ăn uống hợp lý và tập thể dục là những yếu tố then chốt trong việc phòng ngừa bệnh tật.)"],"ukAudio":"/ai_services/tts3/?q=prevention&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88ven.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=prevention&lang=en-US&ipa=%2Fpr%C9%AA%CB%88ven.%CA%83%C9%99n%2F"},{"id":"lv_6_167","topic":"Business and Humanities Studies","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a fundamental truth, law, or moral rule that guides behavior","examples":["She refused to lie because it went against her moral [principle]. (=Dịch: Cô ấy từ chối nói dối vì điều đó đi ngược lại nguyên tắc đạo đức của mình.)","The machine operates on a very simple physical [principle]. (=Dịch: Cỗ máy hoạt động dựa trên một nguyên lý vật lý rất đơn giản.)","Equality is a core [principle] of any democratic society. (=Dịch: Bình đẳng là nguyên tắc cốt lõi của bất kỳ xã hội dân chủ nào.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_6_168","topic":"Business and Humanities Studies","word":"problematic","pos":"(adj)","ipa":"/ˌprɑː.bləˈmæt̬.ɪk/","defVi":"nan giải, phức tạp, nhiều vấn đề","defEn":"full of difficulties, problems, or uncertainties","examples":["Implementing the new tax policy turned out to be extremely [problematic]. (=Dịch: Việc thực thi chính sách thuế mới hóa ra lại cực kỳ nan giải.)","The lack of reliable public transport makes commuting [problematic] for residents. (=Dịch: Việc thiếu phương tiện giao thông công cộng đáng tin cậy khiến việc đi lại của cư dân gặp nhiều khó khăn.)","His aggressive behavior during meetings became increasingly [problematic]. (=Dịch: Hành vi gây hấn của anh ta trong các cuộc họp ngày càng trở nên có vấn đề.)"],"ukAudio":"/ai_services/tts3/?q=problematic&lang=en-GB&ipa=%2F%CB%8Cpr%C9%91%CB%90.bl%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=problematic&lang=en-US&ipa=%2F%CB%8Cpr%C9%91%CB%90.bl%C9%99%CB%88m%C3%A6t%CC%AC.%C9%AAk%2F"},{"id":"lv_6_169","topic":"Business and Humanities Studies","word":"profit","pos":"(n)","ipa":"/ˈprɑː.fɪt/","defVi":"lợi nhuận","defEn":"money that is earned in business after paying the costs of producing and selling goods and services","examples":["The company made a healthy [profit] in its first year of operation. (=Dịch: Công ty đã đạt mức lợi nhuận khả quan trong năm đầu hoạt động.)","They decided to sell the property for a substantial [profit]. (=Dịch: Họ quyết định bán bất động sản đó để kiếm một khoản lợi nhuận đáng kể.)","A drop in sales led to a sharp decrease in net [profit]. (=Dịch: Sự sụt giảm doanh số đã dẫn đến việc lợi nhuận ròng giảm mạnh. Giang)"],"ukAudio":"/ai_services/tts3/?q=profit&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=profit&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AAt%2F"},{"id":"lv_6_170","topic":"Business and Humanities Studies","word":"profitable","pos":"(adj)","ipa":"/ˈprɑː.fɪ.t̬ə.bəl/","defVi":"có lãi, sinh lời, có lợi","defEn":"yielding financial gain or beneficial results","examples":["The company developed a new and highly [profitable] product line. (=Dịch: Công ty đã phát triển một dòng sản phẩm mới và mang lại lợi nhuận rất cao.)","Online advertising proved to be a [profitable] strategy for small businesses. (=Dịch: Quảng cáo trực tuyến đã được chứng minh là một chiến lược sinh lời cho các doanh nghiệp nhỏ.)","They had a [profitable] discussion about improving workplace efficiency. (=Dịch: Họ đã có một cuộc thảo luận hữu ích về việc cải thiện hiệu quả làm việc.)"],"ukAudio":"/ai_services/tts3/?q=profitable&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AA.t%CC%AC%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=profitable&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.f%C9%AA.t%CC%AC%C9%99.b%C9%99l%2F"},{"id":"lv_6_171","topic":"Business and Humanities Studies","word":"promotion","pos":"(n)","ipa":"/prəˈmoʊ.ʃən/","defVi":"sự thăng tiến, sự xúc tiến / khuyến mãi","defEn":"a move to a higher position or rank; an activity to boost sales","examples":["Her hard work earned her a well-deserved [promotion] at work. (=Dịch: Sự chăm chỉ đã mang lại cho cô ấy một đợt thăng chức rất xứng đáng tại nơi làm việc.)","The supermarket is running a special [promotion] on dairy products. (=Dịch: Siêu thị đang có chương trình khuyến mãi đặc biệt cho các sản phẩm từ sữa.)","The campaign aims at the [promotion] of healthy eating habits. (=Dịch: Chiến dịch nhằm mục đích thúc đẩy thói quen ăn uống lành mạnh.)"],"ukAudio":"/ai_services/tts3/?q=promotion&lang=en-GB&ipa=%2Fpr%C9%99%CB%88mo%CA%8A.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=promotion&lang=en-US&ipa=%2Fpr%C9%99%CB%88mo%CA%8A.%CA%83%C9%99n%2F"},{"id":"lv_6_172","topic":"Business and Humanities Studies","word":"prompt","pos":"(adj)","ipa":"/prɑːmpt/","defVi":"nhanh chóng, kịp thời","defEn":"done quickly and without delay","examples":["Thank you for your [prompt] reply to my email. (=Dịch: Cảm ơn bạn đã phản hồi thư điện tử của tôi một cách nhanh chóng.)","A [prompt] action is required to solve the water shortage. (=Dịch: Cần có hành động kịp thời để giải quyết tình trạng thiếu nước.)","The staff provided [prompt] service to all the guests. (=Dịch: Nhân viên đã phục vụ nhanh chóng cho tất cả các vị khách.)"],"ukAudio":"/ai_services/tts3/?q=prompt&lang=en-GB&ipa=%2Fpr%C9%91%CB%90mpt%2F","usAudio":"/ai_services/tts3/?q=prompt&lang=en-US&ipa=%2Fpr%C9%91%CB%90mpt%2F"},{"id":"lv_6_173","topic":"Business and Humanities Studies","word":"prospect","pos":"(n)","ipa":"/ˈprɑː.spekt/","defVi":"triển vọng, khả năng trong tương lai","defEn":"the possibility or likelihood of some future event occurring","examples":["Graduating with honors will improve your job [prospect]s significantly. (=Dịch: Tốt nghiệp loại giỏi sẽ cải thiện đáng kể triển vọng việc làm của bạn.)","The [prospect] of a long holiday excited all the employees. (=Dịch: Viễn cảnh về một kỳ nghỉ dài khiến tất cả nhân viên vô cùng hào hứng.)","There is little [prospect] of the weather improving before the weekend. (=Dịch: Có rất ít khả năng thời tiết sẽ cải thiện trước cuối tuần.)"],"ukAudio":"/ai_services/tts3/?q=prospect&lang=en-GB&ipa=%2F%CB%88pr%C9%91%CB%90.spekt%2F","usAudio":"/ai_services/tts3/?q=prospect&lang=en-US&ipa=%2F%CB%88pr%C9%91%CB%90.spekt%2F"},{"id":"lv_6_174","topic":"Business and Humanities Studies","word":"psychology","pos":"(n)","ipa":"/saɪˈkɑː.lə.dʒi/","defVi":"tâm lý học, tâm lý","defEn":"the scientific study of the human mind and behavior","examples":["She decided to study [psychology] to better understand why people make certain choices. (=Dịch: Cô ấy quyết định học tâm lý học để hiểu rõ hơn lý do tại sao mọi người đưa ra những lựa chọn nhất định.)","Advertisers often use consumer [psychology] to design effective marketing campaigns. (=Dịch: Các nhà quảng cáo thường vận dụng tâm lý người tiêu dùng để thiết kế các chiến dịch tiếp thị hiệu quả.)","Educational [psychology] helps teachers adapt their methods to different student needs. (=Dịch: Tâm lý học giáo dục giúp giáo viên điều chỉnh phương pháp phù hợp với các nhu cầu khác nhau của học sinh.)"],"ukAudio":"/ai_services/tts3/?q=psychology&lang=en-GB&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=psychology&lang=en-US&ipa=%2Fsa%C9%AA%CB%88k%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_6_175","topic":"Business and Humanities Studies","word":"punishment","pos":"(n)","ipa":"/ˈpʌn.ɪʃ.mənt/","defVi":"sự trừng phạt, hình phạt","defEn":"a penalty imposed on someone for committing an offense or crime","examples":["The judge handed down a strict [punishment] for the serious offense. (=Dịch: Vị thẩm phán đã đưa ra hình phạt nghiêm khắc cho hành vi phạm tội nghiêm trọng.)","Corporal [punishment] is banned in modern educational institutions. (=Dịch: Hình phạt thể xác đã bị cấm trong các cơ sở giáo dục hiện đại.)","He had to clean the classroom as a [punishment] for being late. (=Dịch: Cậu bé phải dọn dẹp phòng học như một hình phạt cho việc đi muộn.)"],"ukAudio":"/ai_services/tts3/?q=punishment&lang=en-GB&ipa=%2F%CB%88p%CA%8Cn.%C9%AA%CA%83.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=punishment&lang=en-US&ipa=%2F%CB%88p%CA%8Cn.%C9%AA%CA%83.m%C9%99nt%2F"},{"id":"lv_6_176","topic":"Business and Humanities Studies","word":"recall","pos":"(v)","ipa":"/rɪˈkɑːl/","defVi":"nhớ lại, hồi tưởng","defEn":"to remember something from the past","examples":["I cannot [recall] the exact date of the meeting. (=Dịch: Tôi không thể nhớ lại ngày chính xác của cuộc họp.)","Old photographs help him [recall] his childhood memories. (=Dịch: Những bức ảnh cũ giúp ông ấy nhớ lại những kỷ niệm thời thơ ấu.)","She could easily [recall] the details of the conversation. (=Dịch: Cô ấy có thể dễ dàng nhớ lại các chi tiết của cuộc trò chuyện.)"],"ukAudio":"/ai_services/tts3/?q=recall&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=recall&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%C9%91%CB%90l%2F"},{"id":"lv_6_177","topic":"Business and Humanities Studies","word":"recruit","pos":"(n)","ipa":"/rɪˈkruːt/","defVi":"thành viên mới, tân binh","defEn":"a person who has recently joined an organization, company, or the armed forces","examples":["Each new [recruit] must complete a two-week training program. (=Dịch: Mỗi nhân viên mới đều phải hoàn thành một chương trình đào tạo kéo dài hai tuần.)","The military [recruit] struggled during the first few days of physical training. (=Dịch: Người tân binh đã gặp nhiều khó khăn trong những ngày đầu huấn luyện thể lực.)","The team welcomed a talented [recruit] with strong analytical skills. (=Dịch: Nhóm đã chào đón một thành viên mới tài năng với kỹ năng phân tích tốt.)"],"ukAudio":"/ai_services/tts3/?q=recruit&lang=en-GB&ipa=%2Fr%C9%AA%CB%88kru%CB%90t%2F","usAudio":"/ai_services/tts3/?q=recruit&lang=en-US&ipa=%2Fr%C9%AA%CB%88kru%CB%90t%2F"},{"id":"lv_6_178","topic":"Business and Humanities Studies","word":"reform","pos":"(n)","ipa":"/rɪˈfɔrm/","defVi":"sự cải cách, sự đổi mới","defEn":"an improvement or change for the better, especially in a system or law","examples":["The government introduced an educational [reform] to improve school facilities. (=Dịch: Chính phủ đã đưa ra một cuộc cải cách giáo dục nhằm cải thiện cơ sở vật chất trường học.)","Economic [reform] has helped many small businesses thrive in the region. (=Dịch: Cải cách kinh tế đã giúp nhiều doanh nghiệp nhỏ phát triển mạnh mẽ trong khu vực.)","There is an urgent need for tax [reform] in our country. (=Dịch: Đất nước chúng ta đang có nhu cầu cấp thiết về việc cải cách thuế.)"],"ukAudio":"/ai_services/tts3/?q=reform&lang=en-GB&ipa=%2Fr%C9%AA%CB%88f%C9%94rm%2F","usAudio":"/ai_services/tts3/?q=reform&lang=en-US&ipa=%2Fr%C9%AA%CB%88f%C9%94rm%2F"},{"id":"lv_6_179","topic":"Business and Humanities Studies","word":"regulatory","pos":"(adj)","ipa":"/ˈreɡ.jə.lə.tɔːr.i/","defVi":"thuộc về quy định, mang tính quản lý","defEn":"relating to the control or management of an activity by official rules","examples":["The company had to meet strict [regulatory] standards before launching the product. (=Dịch: Công ty phải đáp ứng các tiêu chuẩn quy định nghiêm ngặt trước khi ra mắt sản phẩm.)","Government [regulatory] agencies monitor financial institutions closely. (=Dịch: Các cơ quan quản lý của chính phủ giám sát chặt chẽ các tổ chức tài chính.)","Recent changes in the [regulatory] framework affected international trade. (=Dịch: Những thay đổi gần đây trong khung pháp lý đã ảnh hưởng đến thương mại quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=regulatory&lang=en-GB&ipa=%2F%CB%88re%C9%A1.j%C9%99.l%C9%99.t%C9%94%CB%90r.i%2F","usAudio":"/ai_services/tts3/?q=regulatory&lang=en-US&ipa=%2F%CB%88re%C9%A1.j%C9%99.l%C9%99.t%C9%94%CB%90r.i%2F"},{"id":"lv_6_180","topic":"Business and Humanities Studies","word":"relevance","pos":"(n)","ipa":"/ˈrel.ə.vəns/","defVi":"sự liên quan, tính thích hợp","defEn":"the state of being closely connected or appropriate to the matter at hand","examples":["The professor questioned the [relevance] of that data to the main research topic. (=Dịch: Giáo sư đã đặt câu hỏi về mức độ liên quan của dữ liệu đó đối với đề tài nghiên cứu chính.)","Ancient philosophies still hold strong [relevance] to our lives today. (=Dịch: Các triết lý cổ đại vẫn có sự gắn kết sâu sắc với cuộc sống của chúng ta ngày nay.)","Candidates should ensure the direct [relevance] of their skills to the job description. (=Dịch: Các ứng viên nên đảm bảo kỹ năng của mình có sự phù hợp trực tiếp với mô tả công việc.)"],"ukAudio":"/ai_services/tts3/?q=relevance&lang=en-GB&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=relevance&lang=en-US&ipa=%2F%CB%88rel.%C9%99.v%C9%99ns%2F"},{"id":"lv_6_181","topic":"Business and Humanities Studies","word":"respondent","pos":"(n)","ipa":"/rɪˈspɑːn.dənt/","defVi":"người trả lời (khảo sát, phỏng vấn)","defEn":"a person who answers questions, especially in a survey or questionnaire","examples":["Over sixty percent of each [respondent] agreed with the proposed policy. (=Dịch: Hơn sáu mươi phần trăm số người trả lời đã đồng ý với chính sách được đề xuất.)","Each [respondent] was asked to complete an online questionnaire. (=Dịch: Mỗi người trả lời đều được yêu cầu hoàn thành một bảng câu hỏi trực tuyến.)","The researcher guaranteed that every [respondent] would remain anonymous. (=Dịch: Nhà nghiên cứu đảm bảo rằng danh tính của mọi người trả lời sẽ được giữ kín.)"],"ukAudio":"/ai_services/tts3/?q=respondent&lang=en-GB&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=respondent&lang=en-US&ipa=%2Fr%C9%AA%CB%88sp%C9%91%CB%90n.d%C9%99nt%2F"},{"id":"lv_6_182","topic":"Business and Humanities Studies","word":"retention","pos":"(n)","ipa":"/rɪˈten.ʃən/","defVi":"sự duy trì, sự giữ lại, khả năng ghi nhớ","defEn":"the continued possession, use, or control of something; the ability to remember information","examples":["Visual aids can significantly improve the [retention] of complex information. (=Dịch: Các phương tiện trực quan có thể cải thiện đáng kể khả năng ghi nhớ thông tin phức tạp.)","The company implemented new benefits to improve employee [retention]. (=Dịch: Công ty đã áp dụng các phúc lợi mới để cải thiện việc giữ chân nhân viên.)","Good soil structure enhances water [retention] during dry seasons. (=Dịch: Cấu trúc đất tốt giúp tăng cường khả năng giữ nước trong mùa khô.)"],"ukAudio":"/ai_services/tts3/?q=retention&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ten.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=retention&lang=en-US&ipa=%2Fr%C9%AA%CB%88ten.%CA%83%C9%99n%2F"},{"id":"lv_6_183","topic":"Business and Humanities Studies","word":"retirement","pos":"(n)","ipa":"/rɪˈtaɪr.mənt/","defVi":"sự nghỉ hưu, thời gian sau khi nghỉ hưu","defEn":"the act of leaving one's job and stopping work, usually because of reaching a certain age","examples":["Many people look forward to a peaceful [retirement] after decades of hard work. (=Dịch: Nhiều người mong đợi một cuộc sống nghỉ hưu yên bình sau nhiều thập kỷ làm việc vất vả.)","He decided to take early [retirement] due to health issues. (=Dịch: Ông ấy quyết định nghỉ hưu sớm vì lý do sức khỏe.)","She joined a local gardening club soon after her [retirement]. (=Dịch: Bà ấy đã tham gia một câu lạc bộ làm vườn tại địa phương ngay sau khi nghỉ hưu.)"],"ukAudio":"/ai_services/tts3/?q=retirement&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ta%C9%AAr.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=retirement&lang=en-US&ipa=%2Fr%C9%AA%CB%88ta%C9%AAr.m%C9%99nt%2F"},{"id":"lv_6_184","topic":"Business and Humanities Studies","word":"retrieval","pos":"(n)","ipa":"/rɪˈtriː.vəl/","defVi":"sự truy xuất, việc lấy lại","defEn":"the process of finding and getting something back, especially stored information","examples":["The new software allows for faster data [retrieval]. (=Dịch: Phần mềm mới cho phép truy xuất dữ liệu nhanh hơn.)","Effective information [retrieval] is essential for modern search engines. (=Dịch: Việc truy xuất thông tin hiệu quả là điều cốt yếu đối với các công cụ tìm kiếm hiện đại.)","The divers assisted in the [retrieval] of the sunken treasure. (=Dịch: Các thợ lặn đã hỗ trợ việc thu hồi kho báu bị chìm.)"],"ukAudio":"/ai_services/tts3/?q=retrieval&lang=en-GB&ipa=%2Fr%C9%AA%CB%88tri%CB%90.v%C9%99l%2F","usAudio":"/ai_services/tts3/?q=retrieval&lang=en-US&ipa=%2Fr%C9%AA%CB%88tri%CB%90.v%C9%99l%2F"},{"id":"lv_6_185","topic":"Business and Humanities Studies","word":"retrieve","pos":"(v)","ipa":"/rɪˈtriv/","defVi":"lấy lại, khôi phục hoặc tìm lại","defEn":"to find and bring something back from a place","examples":["The dog was trained to [retrieve] fallen birds for the hunter. (=Dịch: Chú chó được huấn luyện để nhặt những con chim bị bắn rơi về cho người thợ săn.)","It took several hours to [retrieve] the lost data from the damaged hard drive. (=Dịch: Mất vài giờ để khôi phục lại dữ liệu bị mất từ ổ cứng bị hỏng.)","She went back to the classroom to [retrieve] her forgotten jacket. (=Dịch: Cô ấy quay lại lớp học để lấy chiếc áo khoác bị bỏ quên.)"],"ukAudio":"/ai_services/tts3/?q=retrieve&lang=en-GB&ipa=%2Fr%C9%AA%CB%88triv%2F","usAudio":"/ai_services/tts3/?q=retrieve&lang=en-US&ipa=%2Fr%C9%AA%CB%88triv%2F"},{"id":"lv_6_186","topic":"Business and Humanities Studies","word":"reward","pos":"(n)","ipa":"/rɪˈwɔːrd/","defVi":"phần thưởng","defEn":"something given or received in return for good work, effort, or behavior","examples":["She received a cash [reward] for finding the lost wallet. (=Dịch: Cô ấy đã nhận được một phần thưởng tiền mặt vì tìm thấy chiếc ví bị mất.)","Hard work often brings its own [reward] in the long run. (=Dịch: Sự chăm chỉ thường mang lại phần thưởng xứng đáng về lâu dài.)","The company offers travel vouchers as a [reward] for outstanding employees. (=Dịch: Công ty tặng phiếu du lịch như một phần thưởng dành cho những nhân viên xuất sắc.)"],"ukAudio":"/ai_services/tts3/?q=reward&lang=en-GB&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90rd%2F","usAudio":"/ai_services/tts3/?q=reward&lang=en-US&ipa=%2Fr%C9%AA%CB%88w%C9%94%CB%90rd%2F"},{"id":"lv_6_187","topic":"Business and Humanities Studies","word":"robbery","pos":"(n)","ipa":"/ˈrɑː.bɚ.i/","defVi":"vụ cướp, tội cướp đoạt tài sản","defEn":"the crime of stealing money or goods from a person or place using violence or threats","examples":["Police are investigating an armed [robbery] that occurred downtown last night. (=Dịch: Cảnh sát đang điều tra một vụ cướp có vũ trang xảy ra ở trung tâm thành phố đêm qua.)","The bank [robbery] was planned with extreme precision. (=Dịch: Vụ cướp ngân hàng đã được lên kế hoạch vô cùng tỉ mỉ.)","He was sentenced to five years in prison for street [robbery]. (=Dịch: Anh ta bị kết án năm năm tù vì tội cướp giật trên đường phố.)"],"ukAudio":"/ai_services/tts3/?q=robbery&lang=en-GB&ipa=%2F%CB%88r%C9%91%CB%90.b%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=robbery&lang=en-US&ipa=%2F%CB%88r%C9%91%CB%90.b%C9%9A.i%2F"},{"id":"lv_6_188","topic":"Business and Humanities Studies","word":"saving","pos":"(n)","ipa":"/ˈseɪ.vɪŋ/","defVi":"khoản tiết kiệm, sự tiết kiệm","defEn":"money preserved for future use or an economy of an amount of something","examples":["Using public transport offers a significant [saving] on fuel costs. (=Dịch: Sử dụng phương tiện công cộng giúp tiết kiệm đáng kể chi phí nhiên liệu.)","She invested her entire life [saving] into starting a new business. (=Dịch: Cô đã đầu tư toàn bộ khoản tiền tiết kiệm cả đời của mình để khởi nghiệp kinh doanh.)","The new technology will lead to a considerable [saving] of energy. (=Dịch: Công nghệ mới này sẽ đem lại sự tiết kiệm năng lượng đáng kể.)"],"ukAudio":"/ai_services/tts3/?q=saving&lang=en-GB&ipa=%2F%CB%88se%C9%AA.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=saving&lang=en-US&ipa=%2F%CB%88se%C9%AA.v%C9%AA%C5%8B%2F"},{"id":"lv_6_189","topic":"Business and Humanities Studies","word":"scenario","pos":"(n)","ipa":"/səˈnɛr.i.oʊ/","defVi":"kịch bản, tình huống có thể xảy ra","defEn":"a description of possible actions or events in the future","examples":["In the worst-case [scenario], the company could lose half of its revenue. (=Dịch: Trong kịch bản tồi tệ nhất, công ty có thể mất một nửa doanh thu.)","The training program prepares pilots for every possible emergency [scenario]. (=Dịch: Chương trình huấn luyện chuẩn bị cho các phi công ứng phó với mọi tình huống khẩn cấp có thể xảy ra.)","Economic experts have outlined several possible recovery [scenarios] for next year. (=Dịch: Các chuyên gia kinh tế đã vạch ra một vài kịch bản phục hồi khả thi cho năm tới.)"],"ukAudio":"/ai_services/tts3/?q=scenario&lang=en-GB&ipa=%2Fs%C9%99%CB%88n%C9%9Br.i.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=scenario&lang=en-US&ipa=%2Fs%C9%99%CB%88n%C9%9Br.i.o%CA%8A%2F"},{"id":"lv_6_190","topic":"Business and Humanities Studies","word":"schizophrenia","pos":"(n)","ipa":"/ˌskɪt.səˈfriː.ni.ə/","defVi":"bệnh tâm thần phân liệt","defEn":"a serious mental disorder that affects how a person thinks, feels, and behaves","examples":["Doctors diagnosed the patient with [schizophrenia] after observing symptoms of hallucinations. (=Dịch: Các bác sĩ chẩn đoán bệnh nhân mắc chứng tâm thần phân liệt sau khi quan sát các triệu chứng ảo giác.)","Medication and therapy can help manage the symptoms of [schizophrenia] effectively. (=Dịch: Thuốc và trị liệu có thể giúp kiểm soát các triệu chứng của bệnh tâm thần phân liệt một cách hiệu quả.)","Public education is necessary to reduce the social stigma surrounding [schizophrenia]. (=Dịch: Giáo dục cộng đồng là cần thiết để giảm bớt định kiến xã hội xung quanh bệnh tâm thần phân liệt.)"],"ukAudio":"/ai_services/tts3/?q=schizophrenia&lang=en-GB&ipa=%2F%CB%8Csk%C9%AAt.s%C9%99%CB%88fri%CB%90.ni.%C9%99%2F","usAudio":"/ai_services/tts3/?q=schizophrenia&lang=en-US&ipa=%2F%CB%8Csk%C9%AAt.s%C9%99%CB%88fri%CB%90.ni.%C9%99%2F"},{"id":"lv_6_191","topic":"Business and Humanities Studies","word":"secure","pos":"(adj)","ipa":"/səˈkjʊr/","defVi":"an toàn, chắc chắn, bảo đảm","defEn":"safe from danger, harm, or the risk of failure","examples":["Make sure you create a [secure] password for all your online accounts. (=Dịch: Hãy đảm bảo rằng bạn tạo một mật khẩu an toàn cho tất cả các tài khoản trực tuyến của mình.)","Children feel more [secure] when they have a consistent daily routine. (=Dịch: Trẻ em cảm thấy an tâm hơn khi có một thời gian biểu hàng ngày ổn định.)","The bank keeps confidential documents in a highly [secure] vault. (=Dịch: Ngân hàng lưu giữ các tài liệu mật trong một căn hầm có độ an toàn cao.)"],"ukAudio":"/ai_services/tts3/?q=secure&lang=en-GB&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=secure&lang=en-US&ipa=%2Fs%C9%99%CB%88kj%CA%8Ar%2F"},{"id":"lv_6_192","topic":"Business and Humanities Studies","word":"semantic","pos":"(adj)","ipa":"/sɪˈmæn.tɪk/","defVi":"thuộc về ngữ nghĩa","defEn":"connected with the meanings of words and language","examples":["The debate turned into a purely [semantic] argument about the definition of the term. (=Dịch: Cuộc tranh luận đã biến thành một cuộc tranh cãi thuần túy về ngữ nghĩa liên quan đến định nghĩa của thuật ngữ.)","Language models use [semantic] analysis to understand the context of a sentence. (=Dịch: Các mô hình ngôn ngữ sử dụng phân tích ngữ nghĩa để hiểu ngữ cảnh của một câu.)","Damage to certain areas of the brain can impair [semantic] memory. (=Dịch: Tổn thương ở một số vùng não nhất định có thể làm suy giảm trí nhớ ngữ nghĩa.)"],"ukAudio":"/ai_services/tts3/?q=semantic&lang=en-GB&ipa=%2Fs%C9%AA%CB%88m%C3%A6n.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=semantic&lang=en-US&ipa=%2Fs%C9%AA%CB%88m%C3%A6n.t%C9%AAk%2F"},{"id":"lv_6_193","topic":"Business and Humanities Studies","word":"seriously","pos":"(adv)","ipa":"/ˈsɪr.i.əs.li/","defVi":"một cách nghiêm túc, trầm trọng","defEn":"in a solemn, grave, or sincere manner; to a severe extent","examples":["You need to take your exam preparation more [seriously]. (=Dịch: Bạn cần nghiêm túc hơn với việc chuẩn bị cho kỳ thi của mình.)","Two passengers were [seriously] injured in the car accident. (=Dịch: Hai hành khách đã bị thương nặng trong vụ tai nạn ô tô.)","I am [seriously] considering applying for a master's degree abroad. (=Dịch: Tôi đang nghiêm túc cân nhắc việc nộp hồ sơ học thạc sĩ ở nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=seriously&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F","usAudio":"/ai_services/tts3/?q=seriously&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99s.li%2F"},{"id":"lv_6_194","topic":"Business and Humanities Studies","word":"shy","pos":"(adj)","ipa":"/ʃaɪ/","defVi":"nhút nhát, e thẹn","defEn":"nervous and uncomfortable about meeting and talking to other people","examples":["He was too [shy] to ask the teacher for help after class. (=Dịch: Cậu ấy quá nhút nhát để xin giáo viên giúp đỡ sau giờ học.)","The little girl gave a [shy] smile when introduced to our guests. (=Dịch: Cô bé nở một nụ cười e thẹn khi được giới thiệu với các vị khách của chúng tôi.)","Public speaking can be terrifying for someone who is naturally [shy]. (=Dịch: Nói trước công chúng có thể rất đáng sợ đối với một người có bản tính nhút nhát.)"],"ukAudio":"/ai_services/tts3/?q=shy&lang=en-GB&ipa=%2F%CA%83a%C9%AA%2F","usAudio":"/ai_services/tts3/?q=shy&lang=en-US&ipa=%2F%CA%83a%C9%AA%2F"},{"id":"lv_6_195","topic":"Business and Humanities Studies","word":"sibling","pos":"(n)","ipa":"/ˈsɪb.lɪŋ/","defVi":"anh chị em ruột","defEn":"a brother or sister","examples":["She gets along very well with her younger [sibling]. (=Dịch: Cô ấy rất hòa thuận với em ruột của mình.)","[Sibling] rivalry is quite common in families with multiple children. (=Dịch: Sự ganh đua giữa anh chị em khá phổ biến trong các gia đình có nhiều con.)","He grew up as an only child without any [sibling] to play with. (=Dịch: Anh lớn lên là con một mà không có anh chị em nào để chơi cùng.)"],"ukAudio":"/ai_services/tts3/?q=sibling&lang=en-GB&ipa=%2F%CB%88s%C9%AAb.l%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sibling&lang=en-US&ipa=%2F%CB%88s%C9%AAb.l%C9%AA%C5%8B%2F"},{"id":"lv_6_196","topic":"Business and Humanities Studies","word":"skilled","pos":"(adj)","ipa":"/skɪld/","defVi":"lành nghề, có tay nghề cao","defEn":"having the knowledge, training, or ability to do something well","examples":["The hospital is in urgent need of [skilled] nurses and doctors. (=Dịch: Bệnh viện đang có nhu cầu cấp thiết về các bác sĩ và y tá có tay nghề cao.)","He is a [skilled] carpenter who can build beautiful custom furniture. (=Dịch: Anh ấy là một thợ mộc lành nghề có thể đóng những món đồ nội thất đặt riêng tuyệt đẹp.)","The country relies on [skilled] workers to drive its economic growth. (=Dịch: Đất nước này dựa vào lực lượng lao động có tay nghề để thúc đẩy tăng trưởng kinh tế.)"],"ukAudio":"/ai_services/tts3/?q=skilled&lang=en-GB&ipa=%2Fsk%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=skilled&lang=en-US&ipa=%2Fsk%C9%AAld%2F"},{"id":"lv_6_197","topic":"Business and Humanities Studies","word":"software","pos":"(n)","ipa":"/ˈsɔːft.wer/","defVi":"phần mềm máy tính","defEn":"the programs and operating information used by a computer","examples":["You need to update your antivirus [software] regularly to protect your computer. (=Dịch: Bạn cần cập nhật phần mềm diệt virus thường xuyên để bảo vệ máy tính của mình.)","The company develops educational [software] for young children. (=Dịch: Công ty này phát triển phần mềm giáo dục cho trẻ nhỏ.)","A glitch in the accounting [software] caused a delay in processing payments. (=Dịch: Một lỗi trong phần mềm kế toán đã làm chậm quá trình xử lý các khoản thanh toán.)"],"ukAudio":"/ai_services/tts3/?q=software&lang=en-GB&ipa=%2F%CB%88s%C9%94%CB%90ft.wer%2F","usAudio":"/ai_services/tts3/?q=software&lang=en-US&ipa=%2F%CB%88s%C9%94%CB%90ft.wer%2F"},{"id":"lv_6_198","topic":"Business and Humanities Studies","word":"solitude","pos":"(n)","ipa":"/ˈsɑː.lə.tuːd/","defVi":"sự thanh tịnh khi ở một mình, cảnh thanh vắng","defEn":"the state or situation of being alone, especially when pleasant and peaceful","examples":["He went for a long walk in the forest to enjoy the peace and [solitude]. (=Dịch: Anh ấy đi dạo thật lâu trong rừng để tận hưởng sự yên bình và thanh tịnh một mình.)","Writers often seek [solitude] so they can focus on their creative work. (=Dịch: Các nhà văn thường tìm kiếm sự tĩnh lặng một mình để có thể tập trung vào công việc sáng tạo.)","After weeks of non-stop socializing, she welcomed a weekend of complete [solitude]. (=Dịch: Sau nhiều tuần giao lưu không ngừng nghỉ, cô rất hoan nghênh một ngày cuối tuần hoàn toàn ở một mình.)"],"ukAudio":"/ai_services/tts3/?q=solitude&lang=en-GB&ipa=%2F%CB%88s%C9%91%CB%90.l%C9%99.tu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=solitude&lang=en-US&ipa=%2F%CB%88s%C9%91%CB%90.l%C9%99.tu%CB%90d%2F"},{"id":"lv_6_199","topic":"Business and Humanities Studies","word":"sourced","pos":"(v)","ipa":"/sɔːrst/","defVi":"thu mua từ, lấy nguồn từ","defEn":"obtained or supplied something from a particular place or manufacturer","examples":["The restaurant proudly serves ingredients [sourced] from local organic farms. (=Dịch: Nhà hàng tự hào phục vụ các nguyên liệu được thu mua từ các nông trại hữu cơ địa phương.)","All the timber for this furniture was [sourced] sustainably. (=Dịch: Toàn bộ gỗ cho đồ nội thất này đều được khai thác từ nguồn bền vững.)","The manufacturer [sourced] electronic parts from several international suppliers. (=Dịch: Nhà sản xuất đã nhập linh kiện điện tử từ nhiều nhà cung cấp quốc tế.)"],"ukAudio":"/ai_services/tts3/?q=sourced&lang=en-GB&ipa=%2Fs%C9%94%CB%90rst%2F","usAudio":"/ai_services/tts3/?q=sourced&lang=en-US&ipa=%2Fs%C9%94%CB%90rst%2F"},{"id":"lv_6_200","topic":"Business and Humanities Studies","word":"span","pos":"(v)","ipa":"/spæn/","defVi":"kéo dài qua, trải rộng khắp","defEn":"to extend across a period of time or physical distance","examples":["His successful career in education [span]ned more than four decades. (=Dịch: Sự nghiệp thành công của ông trong ngành giáo dục đã kéo dài hơn bốn thập kỷ.)","The magnificent bridge [span]s the wide river connecting two provinces. (=Dịch: Cây cầu tráng lệ bắc ngang qua con sông rộng lớn nối liền hai tỉnh.)","Her research projects [span] multiple disciplines, including physics and biology. (=Dịch: Các dự án nghiên cứu của cô ấy trải rộng trên nhiều lĩnh vực, bao gồm cả vật lý và sinh học.)"],"ukAudio":"/ai_services/tts3/?q=span&lang=en-GB&ipa=%2Fsp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=span&lang=en-US&ipa=%2Fsp%C3%A6n%2F"},{"id":"lv_6_201","topic":"Business and Humanities Studies","word":"sportspeople","pos":"(n)","ipa":"/ˈspɔrtsˌpi.pəl/","defVi":"các vận động viên, người chơi thể thao","defEn":"people who play sport, especially professionally","examples":["Professional [sportspeople] must maintain a strict diet and training routine. (=Dịch: Các vận động viên chuyên nghiệp phải duy trì một chế độ ăn uống và tập luyện nghiêm ngặt.)","Many famous [sportspeople] earn significant money from commercial endorsements. (=Dịch: Nhiều vận động viên nổi tiếng kiếm được số tiền lớn từ các hợp đồng quảng cáo thương mại.)","The ceremony honored the country's most successful [sportspeople] of the year. (=Dịch: Buổi lễ đã vinh danh những người chơi thể thao thành công nhất trong năm của đất nước.)"],"ukAudio":"/ai_services/tts3/?q=sportspeople&lang=en-GB&ipa=%2F%CB%88sp%C9%94rts%CB%8Cpi.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sportspeople&lang=en-US&ipa=%2F%CB%88sp%C9%94rts%CB%8Cpi.p%C9%99l%2F"},{"id":"lv_6_202","topic":"Business and Humanities Studies","word":"statistical","pos":"(adj)","ipa":"/stəˈtɪs.tɪ.kəl/","defVi":"thuộc về thống kê","defEn":"relating to the collection, analysis, and interpretation of numerical data","examples":["The researcher provided strong [statistical] evidence to support his theory. (=Dịch: Nhà nghiên cứu đã cung cấp bằng chứng thống kê vững chắc để ủng hộ lý thuyết của mình.)","There is no [statistical] difference in performance between the two groups. (=Dịch: Không có sự khác biệt mang tính thống kê về hiệu suất giữa hai nhóm.)","She used [statistical] software to analyze the survey results. (=Dịch: Cô ấy đã sử dụng phần mềm thống kê để phân tích kết quả khảo sát.)"],"ukAudio":"/ai_services/tts3/?q=statistical&lang=en-GB&ipa=%2Fst%C9%99%CB%88t%C9%AAs.t%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=statistical&lang=en-US&ipa=%2Fst%C9%99%CB%88t%C9%AAs.t%C9%AA.k%C9%99l%2F"},{"id":"lv_6_203","topic":"Business and Humanities Studies","word":"status","pos":"(n)","ipa":"/ˈsteɪ.təs/","defVi":"địa vị, vị thế, tình trạng","defEn":"the legal, social, or professional position of someone or something","examples":["He worked hard to improve his social [status] in the community. (=Dịch: Anh ấy đã làm việc chăm chỉ để nâng cao vị thế xã hội của mình trong cộng đồng.)","You can check the [status] of your application online at any time. (=Dịch: Bạn có thể kiểm tra tình trạng hồ sơ ứng tuyển của mình trực tuyến bất cứ lúc nào.)","The building was granted historical [status] by the government. (=Dịch: Tòa nhà đã được chính phủ cấp tư cách di tích lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=status&lang=en-GB&ipa=%2F%CB%88ste%C9%AA.t%C9%99s%2F","usAudio":"/ai_services/tts3/?q=status&lang=en-US&ipa=%2F%CB%88ste%C9%AA.t%C9%99s%2F"},{"id":"lv_6_204","topic":"Business and Humanities Studies","word":"stranger","pos":"(n)","ipa":"/ˈstreɪn.dʒɚ/","defVi":"người lạ","defEn":"a person whom you do not know","examples":["Children are often taught not to talk to a [stranger]. (=Dịch: Trẻ em thường được dạy không nên nói chuyện với người lạ.)","A kind [stranger] helped me find my way to the train station. (=Dịch: Một người lạ tốt bụng đã giúp tôi tìm đường đến ga xe lửa.)","I felt like a [stranger] in the new city until I made some friends. (=Dịch: Tôi cảm thấy như một người xa lạ ở thành phố mới cho đến khi kết bạn được với vài người.)"],"ukAudio":"/ai_services/tts3/?q=stranger&lang=en-GB&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F","usAudio":"/ai_services/tts3/?q=stranger&lang=en-US&ipa=%2F%CB%88stre%C9%AAn.d%CA%92%C9%9A%2F"},{"id":"lv_6_205","topic":"Business and Humanities Studies","word":"strengthen","pos":"(v)","ipa":"/ˈstreŋk.θən/","defVi":"củng cố, tăng cường, làm mạnh thêm","defEn":"to make or become stronger, more effective, or more resilient","examples":["Regular physical exercise helps to [strengthen] your heart and muscles. (=Dịch: Tập thể dục đều đặn giúp tăng cường sức khỏe tim mạch và cơ bắp.)","The two nations signed an agreement to [strengthen] bilateral trade relations. (=Dịch: Hai quốc gia đã ký một thỏa thuận nhằm củng cố quan hệ thương mại song phương.)","New evidence was presented to [strengthen] the lawyer's argument in court. (=Dịch: Bằng chứng mới đã được đưa ra để củng cố lập luận của luật sư trước tòa.)"],"ukAudio":"/ai_services/tts3/?q=strengthen&lang=en-GB&ipa=%2F%CB%88stre%C5%8Bk.%CE%B8%C9%99n%2F","usAudio":"/ai_services/tts3/?q=strengthen&lang=en-US&ipa=%2F%CB%88stre%C5%8Bk.%CE%B8%C9%99n%2F"},{"id":"lv_6_206","topic":"Business and Humanities Studies","word":"strike","pos":"(n)","ipa":"/straɪk/","defVi":"cuộc đình công, bãi công","defEn":"a refusal to work organized by a body of employees as a form of protest","examples":["Train services were completely disrupted due to a rail workers' [strike]. (=Dịch: Các dịch vụ tàu hỏa đã bị gián đoạn hoàn toàn do cuộc đình công của công nhân đường sắt.)","The union decided to call a [strike] after negotiations broke down. (=Dịch: Công đoàn đã quyết định kêu gọi bãi công sau khi các cuộc đàm phán đổ vỡ.)","Teachers went on [strike] to demand better pay and working conditions. (=Dịch: Các giáo viên đã tiến hành đình công để yêu cầu mức lương và điều kiện làm việc tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=strike&lang=en-GB&ipa=%2Fstra%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=strike&lang=en-US&ipa=%2Fstra%C9%AAk%2F"},{"id":"lv_6_207","topic":"Business and Humanities Studies","word":"string","pos":"(n)","ipa":"/strɪŋ/","defVi":"dây, sợi dây; dây đàn","defEn":"a thin piece of cord or rope used for tying, fastening, or pulling things","examples":["He tied the cardboard box securely with a piece of [string]. (=Dịch: Anh ấy đã dùng một sợi dây để buộc chặt chiếc hộp các-tông lại.)","One [string] on his guitar snapped during the live concert. (=Dịch: Một dây trên cây đàn ghi-ta của anh ấy đã bị đứt trong buổi hòa nhạc trực tiếp.)","Children used colorful [string] to make friendship bracelets. (=Dịch: Lũ trẻ đã dùng những sợi dây nhiều màu sắc để làm vòng tay tình bạn.)"],"ukAudio":"/ai_services/tts3/?q=string&lang=en-GB&ipa=%2Fstr%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=string&lang=en-US&ipa=%2Fstr%C9%AA%C5%8B%2F"},{"id":"lv_6_208","topic":"Business and Humanities Studies","word":"subsequent","pos":"(adj)","ipa":"/ˈsʌb.sɪ.kwənt/","defVi":"xảy ra sau đó, tiếp theo","defEn":"happening or coming after something else","examples":["The initial report was brief, but [subsequent] studies provided more detail. (=Dịch: Báo cáo ban đầu khá ngắn gọn, nhưng các nghiên cứu tiếp theo đã cung cấp thêm chi tiết.)","Her first novel was a flop, but [subsequent] books were bestsellers. (=Dịch: Cuốn tiểu thuyết đầu tay của cô ấy thất bại, nhưng các cuốn sách sau đó lại bán rất chạy.)","The mistake was discovered in [subsequent] tests before the product launched. (=Dịch: Sai sót đã được phát hiện trong các bài kiểm tra tiếp theo trước khi sản phẩm ra mắt.)"],"ukAudio":"/ai_services/tts3/?q=subsequent&lang=en-GB&ipa=%2F%CB%88s%CA%8Cb.s%C9%AA.kw%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=subsequent&lang=en-US&ipa=%2F%CB%88s%CA%8Cb.s%C9%AA.kw%C9%99nt%2F"},{"id":"lv_6_209","topic":"Business and Humanities Studies","word":"successfully","pos":"(adv)","ipa":"/səkˈsɛs.fə.li/","defVi":"một cách thành công, thuận lợi","defEn":"in a way that achieves the desired result","examples":["The team [successfully] launched the new application last week. (=Dịch: Đội ngũ đã ra mắt thành công ứng dụng mới vào tuần trước.)","She [successfully] completed her master's degree in economics. (=Dịch: Cô ấy đã hoàn thành xuất sắc bằng thạc sĩ kinh tế.)","The doctor [successfully] treated the rare medical condition. (=Dịch: Bác sĩ đã điều trị thành công căn bệnh hiếm gặp.)"],"ukAudio":"/ai_services/tts3/?q=successfully&lang=en-GB&ipa=%2Fs%C9%99k%CB%88s%C9%9Bs.f%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=successfully&lang=en-US&ipa=%2Fs%C9%99k%CB%88s%C9%9Bs.f%C9%99.li%2F"},{"id":"lv_6_210","topic":"Business and Humanities Studies","word":"sum","pos":"(n)","ipa":"/sʌm/","defVi":"số tiền; tổng số","defEn":"an amount of money; the total amount resulting from adding numbers together","examples":["She donated a large [sum] of money to the local animal shelter. (=Dịch: Cô ấy đã quyên góp một khoản tiền lớn cho trạm cứu hộ động vật địa phương.)","The [sum] of two and three is five. (=Dịch: Tổng của hai và ba là năm.)","The total [sum] required for the project exceeded their budget. (=Dịch: Tổng số tiền cần cho dự án đã vượt quá ngân sách của họ.)"],"ukAudio":"/ai_services/tts3/?q=sum&lang=en-GB&ipa=%2Fs%CA%8Cm%2F","usAudio":"/ai_services/tts3/?q=sum&lang=en-US&ipa=%2Fs%CA%8Cm%2F"},{"id":"lv_6_211","topic":"Business and Humanities Studies","word":"tackle","pos":"(v)","ipa":"/ˈtæk.əl/","defVi":"giải quyết, xử lý","defEn":"to make an organized effort to deal with a difficult problem or task","examples":["The local government is launching new initiatives to [tackle] air pollution. (=Dịch: Chính quyền địa phương đang triển khai các sáng kiến mới để giải quyết tình trạng ô nhiễm không khí.)","We must work together to [tackle] the root causes of poverty. (=Dịch: Chúng ta phải hợp tác cùng nhau để giải quyết những nguyên nhân gốc rễ của đói nghèo.)","The engineer spent the entire afternoon trying to [tackle] the software glitch. (=Dịch: Kỹ sư đã dành cả buổi chiều để cố gắng xử lý sự cố phần mềm.)"],"ukAudio":"/ai_services/tts3/?q=tackle&lang=en-GB&ipa=%2F%CB%88t%C3%A6k.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tackle&lang=en-US&ipa=%2F%CB%88t%C3%A6k.%C9%99l%2F"},{"id":"lv_6_212","topic":"Business and Humanities Studies","word":"tanker","pos":"(n)","ipa":"/ˈtæŋ.kɚ/","defVi":"tàu chở dầu, xe bồn","defEn":"a large ship, truck, or plane designed to carry large quantities of liquid or gas","examples":["An oil [tanker] ran aground near the coast, causing a major spill. (=Dịch: Một chiếc tàu chở dầu bị mắc cạn gần bờ biển, gây ra một vụ tràn dầu lớn.)","A milk [tanker] arrives at the dairy farm every morning to collect milk. (=Dịch: Một chiếc xe bồn chở sữa đến trang trại bò sữa vào mỗi buổi sáng để thu gom sữa.)","Firefighters used a water [tanker] to help extinguish the forest blaze. (=Dịch: Lực lượng cứu hỏa đã sử dụng một xe bồn chở nước để giúp dập tắt đám cháy rừng.)"],"ukAudio":"/ai_services/tts3/?q=tanker&lang=en-GB&ipa=%2F%CB%88t%C3%A6%C5%8B.k%C9%9A%2F","usAudio":"/ai_services/tts3/?q=tanker&lang=en-US&ipa=%2F%CB%88t%C3%A6%C5%8B.k%C9%9A%2F"},{"id":"lv_6_213","topic":"Business and Humanities Studies","word":"teamwork","pos":"(n)","ipa":"/ˈtiːm.wɜːrk/","defVi":"làm việc nhóm, sự phối hợp đồng đội","defEn":"the combined action of a group, especially when effective and efficient","examples":["Successful project delivery depends on close communication and [teamwork]. (=Dịch: Việc bàn giao dự án thành công phụ thuộc vào sự giao tiếp chặt chẽ và tinh thần làm việc nhóm.)","Playing sports at school teaches children the true value of [teamwork]. (=Dịch: Chơi thể thao ở trường dạy cho trẻ em giá trị thực sự của tinh thần đồng đội.)","The rescue mission required outstanding [teamwork] from all emergency services. (=Dịch: Nhiệm vụ cứu hộ đòi hỏi sự phối hợp đồng đội xuất sắc từ tất cả các lực lượng khẩn cấp.)"],"ukAudio":"/ai_services/tts3/?q=teamwork&lang=en-GB&ipa=%2F%CB%88ti%CB%90m.w%C9%9C%CB%90rk%2F","usAudio":"/ai_services/tts3/?q=teamwork&lang=en-US&ipa=%2F%CB%88ti%CB%90m.w%C9%9C%CB%90rk%2F"},{"id":"lv_6_214","topic":"Business and Humanities Studies","word":"tech","pos":"(n)","ipa":"/tɛk/","defVi":"công nghệ","defEn":"short for technology, referring to scientific knowledge and electronic devices used in practical ways","examples":["Many young graduates aspire to work in the fast-growing [tech] industry. (=Dịch: Nhiều sinh viên mới tốt nghiệp khao khát được làm việc trong ngành công nghệ đang phát triển nhanh chóng.)","Modern educational institutions are integrating advanced [tech] into classrooms. (=Dịch: Các cơ sở giáo dục hiện đại đang tích hợp công nghệ tiên tiến vào lớp học.)","The city has become a hub for promising [tech] startups. (=Dịch: Thành phố đã trở thành một trung tâm cho các công ty khởi nghiệp công nghệ đầy triển vọng.)"],"ukAudio":"/ai_services/tts3/?q=tech&lang=en-GB&ipa=%2Ft%C9%9Bk%2F","usAudio":"/ai_services/tts3/?q=tech&lang=en-US&ipa=%2Ft%C9%9Bk%2F"},{"id":"lv_6_215","topic":"Business and Humanities Studies","word":"technological","pos":"(adj)","ipa":"/ˌtɛk.nəˈlɑ.dʒɪ.kəl/","defVi":"thuộc về công nghệ, kỹ thuật","defEn":"relating to or using scientific knowledge and technology","examples":["Recent [technological] advancements have completely transformed the healthcare industry. (=Dịch: Những tiến bộ công nghệ gần đây đã thay đổi hoàn toàn ngành chăm sóc sức khỏe.)","The company invests heavily in [technological] research and development. (=Dịch: Công ty đầu tư mạnh vào nghiên cứu và phát triển công nghệ.)","Rapid [technological] change requires workers to learn new digital skills constantly. (=Dịch: Sự thay đổi công nghệ nhanh chóng đòi hỏi người lao động phải liên tục học các kỹ năng số mới.)"],"ukAudio":"/ai_services/tts3/?q=technological&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Bk.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=technological&lang=en-US&ipa=%2F%CB%8Ct%C9%9Bk.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_6_216","topic":"Business and Humanities Studies","word":"tendency","pos":"(n)","ipa":"/ˈten.dən.si/","defVi":"xu hướng, khuynh hướng","defEn":"an inclination toward a particular characteristic, behavior, or trend","examples":["He has a [tendency] to procrastinate when faced with difficult tasks. (=Dịch: Anh ấy có xu hướng trì hoãn khi phải đối mặt với những nhiệm vụ khó khăn.)","There is a growing [tendency] among young consumers to shop online. (=Dịch: Ngày càng có xu hướng rõ rệt trong giới người tiêu dùng trẻ là mua sắm trực tuyến.)","The economy shows a clear [tendency] toward steady growth this quarter. (=Dịch: Nền kinh tế thể hiện một khuynh hướng tăng trưởng ổn định rõ rệt trong quý này.)"],"ukAudio":"/ai_services/tts3/?q=tendency&lang=en-GB&ipa=%2F%CB%88ten.d%C9%99n.si%2F","usAudio":"/ai_services/tts3/?q=tendency&lang=en-US&ipa=%2F%CB%88ten.d%C9%99n.si%2F"},{"id":"lv_6_217","topic":"Business and Humanities Studies","word":"trait","pos":"(n)","ipa":"/treɪt/","defVi":"nét tính cách, đặc điểm","defEn":"a particular quality in your personality or physical appearance","examples":["Curiosity is a personality [trait] shared by many successful scientists. (=Dịch: Tính tò mò là một nét tính cách chung của nhiều nhà khoa học thành công.)","Eye color is a physical [trait] inherited from parents. (=Dịch: Màu mắt là một đặc điểm thể chất được di truyền từ cha mẹ.)","Creativity is an important [trait] for individuals working in the arts. (=Dịch: Sáng tạo là một đặc điểm quan trọng đối với những người làm việc trong ngành nghệ thuật.)"],"ukAudio":"/ai_services/tts3/?q=trait&lang=en-GB&ipa=%2Ftre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=trait&lang=en-US&ipa=%2Ftre%C9%AAt%2F"},{"id":"lv_6_218","topic":"Business and Humanities Studies","word":"transactional","pos":"(adj)","ipa":"/trænˈzæk.ʃən.əl/","defVi":"mang tính giao dịch, vụ lợi","defEn":"relating to the conducting of business, an exchange, or a practical interaction","examples":["Their business relationship remained purely [transactional] without any personal connection. (=Dịch: Mối quan hệ kinh doanh của họ hoàn toàn chỉ mang tính giao dịch mà không có sự gắn kết cá nhân nào.)","Modern banking apps are designed to handle high volumes of [transactional] data securely. (=Dịch: Các ứng dụng ngân hàng hiện đại được thiết kế để xử lý khối lượng lớn dữ liệu giao dịch một cách an toàn.)","A purely [transactional] approach to management may harm long-term employee loyalty. (=Dịch: Cách tiếp cận quản lý chỉ thuần mang tính trao đổi vụ lợi có thể làm tổn hại đến lòng trung thành lâu dài của nhân viên.)"],"ukAudio":"/ai_services/tts3/?q=transactional&lang=en-GB&ipa=%2Ftr%C3%A6n%CB%88z%C3%A6k.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=transactional&lang=en-US&ipa=%2Ftr%C3%A6n%CB%88z%C3%A6k.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_219","topic":"Business and Humanities Studies","word":"transformational","pos":"(adj)","ipa":"/ˌtræns.fɚˈmeɪ.ʃən.əl/","defVi":"mang tính chuyển đổi sâu sắc, mang tính cải cách","defEn":"causing a major, fundamental change in someone or something","examples":["The introduction of smartphones has had a [transformational] effect on modern communication. (=Dịch: Sự ra đời của điện thoại thông minh đã mang lại tác động biến đổi sâu sắc đối với giao tiếp hiện đại.)","She showed strong [transformational] leadership during the company's restructuring. (=Dịch: Cô ấy đã thể hiện khả năng lãnh đạo mang tính cải cách mạnh mẽ trong suốt quá trình tái cơ cấu công ty.)","Access to higher education can be a truly [transformational] experience for young people. (=Dịch: Cơ hội tiếp cận giáo dục đại học có thể là một trải nghiệm biến đổi sâu sắc thực sự đối với người trẻ.)"],"ukAudio":"/ai_services/tts3/?q=transformational&lang=en-GB&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=transformational&lang=en-US&ipa=%2F%CB%8Ctr%C3%A6ns.f%C9%9A%CB%88me%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_6_220","topic":"Business and Humanities Studies","word":"truly","pos":"(adv)","ipa":"/ˈtru.li/","defVi":"thực sự, đích thực","defEn":"in a truthful, sincere, or genuine manner; completely","examples":["I am [truly] grateful for all the support you have given me. (=Dịch: Tôi thực sự biết ơn vì tất cả sự hỗ trợ mà bạn đã dành cho tôi.)","It was a [truly] remarkable achievement for such a young player. (=Dịch: Đó thực sự là một thành tích đáng nể đối với một cầu thủ trẻ như vậy.)","She wants to know what he [truly] thinks about the proposal. (=Dịch: Cô ấy muốn biết anh ấy thực sự nghĩ gì về đề xuất này.)"],"ukAudio":"/ai_services/tts3/?q=truly&lang=en-GB&ipa=%2F%CB%88tru.li%2F","usAudio":"/ai_services/tts3/?q=truly&lang=en-US&ipa=%2F%CB%88tru.li%2F"},{"id":"lv_6_221","topic":"Business and Humanities Studies","word":"tunnel","pos":"(n)","ipa":"/ˈtʌn.əl/","defVi":"đường hầm","defEn":"a long passage dug underground or through a mountain for vehicles or trains","examples":["The railway [tunnel] through the mountain shortened travel time by two hours. (=Dịch: Đường hầm đường sắt xuyên núi đã rút ngắn thời gian di chuyển đi hai giờ.)","Drivers must turn on their headlights before entering the underwater [tunnel]. (=Dịch: Các tài xế phải bật đèn pha trước khi đi vào đường hầm dưới nước.)","Engineers worked for years to dig the underground metro [tunnel]. (=Dịch: Các kỹ sư đã làm việc trong nhiều năm để đào đường hầm tàu điện ngầm dưới lòng đất.)"],"ukAudio":"/ai_services/tts3/?q=tunnel&lang=en-GB&ipa=%2F%CB%88t%CA%8Cn.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tunnel&lang=en-US&ipa=%2F%CB%88t%CA%8Cn.%C9%99l%2F"},{"id":"lv_6_222","topic":"Business and Humanities Studies","word":"turnover","pos":"(n)","ipa":"/ˈtɝːnˌoʊ.vɚ/","defVi":"doanh số, doanh thu","defEn":"the amount of money taken in by a business over a period, or the rate at which staff leave and are replaced","examples":["The firm reported an annual [turnover] of over ten million dollars. (=Dịch: Công ty đã báo cáo doanh thu hàng năm hơn mười triệu đô la.)","High staff [turnover] can severely disrupt a company's daily operations. (=Dịch: Tỷ lệ luân chuyển nhân viên cao có thể làm gián đoạn nghiêm trọng hoạt động hàng ngày của công ty.)","Improving customer loyalty helped boost the store's weekly [turnover]. (=Dịch: Việc nâng cao lòng trung thành của khách hàng đã giúp tăng doanh số hàng tuần của cửa hàng.)"],"ukAudio":"/ai_services/tts3/?q=turnover&lang=en-GB&ipa=%2F%CB%88t%C9%9D%CB%90n%CB%8Co%CA%8A.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=turnover&lang=en-US&ipa=%2F%CB%88t%C9%9D%CB%90n%CB%8Co%CA%8A.v%C9%9A%2F"},{"id":"lv_6_223","topic":"Business and Humanities Studies","word":"typically","pos":"(adv)","ipa":"/ˈtɪ.pɪ.kli/","defVi":"thông thường, điển hình","defEn":"usually, or in a way that is characteristic of someone or something","examples":["Classes [typically] begin at eight o'clock in the morning. (=Dịch: Các lớp học thông thường bắt đầu vào lúc tám giờ sáng.)","Symptoms of the flu [typically] include fever and fatigue. (=Dịch: Các triệu chứng của bệnh cúm điển hình bao gồm sốt và mệt mỏi.)","He [typically] spends his weekends working in the garden. (=Dịch: Anh ấy thường dành những ngày cuối tuần để làm vườn.)"],"ukAudio":"/ai_services/tts3/?q=typically&lang=en-GB&ipa=%2F%CB%88t%C9%AA.p%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=typically&lang=en-US&ipa=%2F%CB%88t%C9%AA.p%C9%AA.kli%2F"},{"id":"lv_6_224","topic":"Business and Humanities Studies","word":"unaware","pos":"(adj)","ipa":"/ˌʌn.əˈwɛr/","defVi":"không nhận thức được, không hay biết","defEn":"not knowing or noticing something","examples":["He was completely [unaware] of the danger around the corner. (=Dịch: Anh ấy hoàn toàn không hay biết gì về mối nguy hiểm ở ngay góc đường.)","Many residents were [unaware] that the water supply had been cut off. (=Dịch: Nhiều cư dân đã không biết rằng nguồn cấp nước đã bị cắt.)","She seemed [unaware] of how much her comments had hurt him. (=Dịch: Cô ấy dường như không nhận ra những lời nhận xét của mình đã làm tổn thương anh ấy nhiều đến mức nào.)"],"ukAudio":"/ai_services/tts3/?q=unaware&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=unaware&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88w%C9%9Br%2F"},{"id":"lv_6_225","topic":"Business and Humanities Studies","word":"uncertainty","pos":"(n)","ipa":"/ʌnˈsɝː.tən.ti/","defVi":"sự không chắc chắn, sự bấp bênh","defEn":"a state of being unsure or not able to be relied on","examples":["The sudden change in economic policy has created widespread market [uncertainty]. (=Dịch: Sự thay đổi đột ngột trong chính sách kinh tế đã tạo ra tình trạng bất định lan rộng trên thị trường.)","Living with constant financial [uncertainty] can lead to severe stress. (=Dịch: Sống trong tình trạng bất an về tài chính liên tục có thể dẫn đến căng thẳng nghiêm trọng.)","There is still considerable [uncertainty] surrounding the date of the election. (=Dịch: Vẫn còn sự không chắc chắn đáng kể xung quanh ngày diễn ra cuộc bầu cử.)"],"ukAudio":"/ai_services/tts3/?q=uncertainty&lang=en-GB&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F","usAudio":"/ai_services/tts3/?q=uncertainty&lang=en-US&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F"},{"id":"lv_6_226","topic":"Business and Humanities Studies","word":"underestimate","pos":"(v)","ipa":"/ˌʌn.dɚˈes.tə.meɪt/","defVi":"đánh giá thấp, coi nhẹ","defEn":"to estimate something to be smaller, less important, or easier than it actually is","examples":["You should never [underestimate] the importance of thorough preparation. (=Dịch: Bạn không bao giờ nên đánh giá thấp tầm quan trọng của việc chuẩn bị kỹ lưỡng.)","The company tended to [underestimate] the strength of its main competitor. (=Dịch: Công ty có xu hướng coi nhẹ sức mạnh của đối thủ cạnh tranh chính.)","Hikers often [underestimate] how quickly weather conditions can change in the mountains. (=Dịch: Những người đi bộ đường dài thường đánh giá thấp tốc độ thay đổi thời tiết trên núi.)"],"ukAudio":"/ai_services/tts3/?q=underestimate&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88es.t%C9%99.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=underestimate&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%9A%CB%88es.t%C9%99.me%C9%AAt%2F"},{"id":"lv_6_227","topic":"Business and Humanities Studies","word":"universal","pos":"(adj)","ipa":"/ˌjuː.nəˈvɝː.səl/","defVi":"phổ quát, toàn cầu","defEn":"existing everywhere or involving, affecting, or done by all people","examples":["Music is often described as a [universal] language that connects all cultures. (=Dịch: Âm nhạc thường được mô tả như một ngôn ngữ phổ quát kết nối mọi nền văn hóa.)","The organization advocates for [universal] access to clean drinking water. (=Dịch: Tổ chức này vận động cho quyền tiếp cận phổ cập nguồn nước sạch.)","Smiling is a [universal] expression of friendliness across different societies. (=Dịch: Nụ cười là một biểu hiện thân thiện mang tính phổ quát ở các xã hội khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=universal&lang=en-GB&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=universal&lang=en-US&ipa=%2F%CB%8Cju%CB%90.n%C9%99%CB%88v%C9%9D%CB%90.s%C9%99l%2F"},{"id":"lv_6_228","topic":"Business and Humanities Studies","word":"unnecessary","pos":"(adj)","ipa":"/ʌnˈnɛs.əˌsɛr.i/","defVi":"không cần thiết, thừa thãi","defEn":"not needed or more than is needed","examples":["Buying a second car is completely [unnecessary] for our family. (=Dịch: Mua chiếc xe hơi thứ hai là hoàn toàn không cần thiết đối với gia đình chúng tôi.)","The doctor advised him to avoid [unnecessary] stress to recover faster. (=Dịch: Bác sĩ khuyên anh ấy nên tránh những căng thẳng không cần thiết để hồi phục nhanh hơn.)","Using excessive plastic packaging causes [unnecessary] harm to the environment. (=Dịch: Việc sử dụng quá nhiều bao bì nhựa gây ra tác hại không cần thiết cho môi trường.)"],"ukAudio":"/ai_services/tts3/?q=unnecessary&lang=en-GB&ipa=%2F%CA%8Cn%CB%88n%C9%9Bs.%C9%99%CB%8Cs%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=unnecessary&lang=en-US&ipa=%2F%CA%8Cn%CB%88n%C9%9Bs.%C9%99%CB%8Cs%C9%9Br.i%2F"},{"id":"lv_6_229","topic":"Business and Humanities Studies","word":"unwanted","pos":"(adj)","ipa":"/ʌnˈwɑːn.tɪd/","defVi":"không mong muốn, không cần thiết","defEn":"not desired, needed, or welcome","examples":["She donated her [unwanted] clothes to a local charity. (=Dịch: Cô ấy đã quyên góp quần áo không dùng đến cho một tổ chức từ thiện địa phương.)","Installing ad-blocking software can help prevent [unwanted] pop-ups. (=Dịch: Cài đặt phần mềm chặn quảng cáo có thể giúp ngăn chặn các cửa sổ bật lên không mong muốn.)","The new policy received an [unwanted] amount of negative publicity. (=Dịch: Chính sách mới đã thu hút một lượng lớn sự chú ý tiêu cực không mong muốn từ dư luận.)"],"ukAudio":"/ai_services/tts3/?q=unwanted&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unwanted&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%91%CB%90n.t%C9%AAd%2F"},{"id":"lv_6_230","topic":"Business and Humanities Studies","word":"unwilling","pos":"(adj)","ipa":"/ʌnˈwɪl.ɪŋ/","defVi":"không sẵn lòng, miễn cưỡng","defEn":"not ready, eager, or prepared to do something","examples":["He was [unwilling] to admit that he had made a serious mistake. (=Dịch: Anh ấy đã không sẵn lòng thừa nhận rằng mình đã phạm một sai lầm nghiêm trọng.)","Many workers are [unwilling] to relocate to another city for work. (=Dịch: Nhiều người lao động không muốn chuyển đến một thành phố khác để làm việc.)","She seemed [unwilling] to participate in the group discussion. (=Dịch: Cô ấy dường như miễn cưỡng tham gia vào cuộc thảo luận nhóm.)"],"ukAudio":"/ai_services/tts3/?q=unwilling&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=unwilling&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F"},{"id":"lv_6_231","topic":"Business and Humanities Studies","word":"upset","pos":"(adj)","ipa":"/ʌpˈsɛt/","defVi":"buồn bã, thất vọng hoặc lo lắng","defEn":"unhappy, disappointed, or worried because something unpleasant has happened","examples":["She was deeply [upset] when she heard the bad news about her exam. (=Dịch: Cô ấy vô cùng buồn bã khi nghe tin xấu về kỳ thi của mình.)","There is no need to get [upset] over such a minor mistake. (=Dịch: Không cần phải bực mình vì một lỗi nhỏ như vậy đâu.)","The customer was [upset] about the poor service at the restaurant. (=Dịch: Vị khách hàng rất bức xúc về chất lượng phục vụ kém tại nhà hàng.)"],"ukAudio":"/ai_services/tts3/?q=upset&lang=en-GB&ipa=%2F%CA%8Cp%CB%88s%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=upset&lang=en-US&ipa=%2F%CA%8Cp%CB%88s%C9%9Bt%2F"},{"id":"lv_6_232","topic":"Business and Humanities Studies","word":"variable","pos":"(n)","ipa":"/ˈver.i.ə.bəl/","defVi":"biến số, yếu tố có thể thay đổi","defEn":"a factor, trait, or condition that can exist in differing amounts or types in an experiment","examples":["Temperature is an important [variable] to control during the science experiment. (=Dịch: Nhiệt độ là một biến số quan trọng cần kiểm soát trong suốt thí nghiệm khoa học.)","Researchers must account for more than one [variable] when analyzing the survey data. (=Dịch: Các nhà nghiên cứu phải tính đến nhiều hơn một biến số khi phân tích dữ liệu khảo sát.)","The independent [variable] in this study is the amount of sunlight the plants receive. (=Dịch: Biến số độc lập trong nghiên cứu này là lượng ánh sáng mặt trời mà cây trồng nhận được.)"],"ukAudio":"/ai_services/tts3/?q=variable&lang=en-GB&ipa=%2F%CB%88ver.i.%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=variable&lang=en-US&ipa=%2F%CB%88ver.i.%C9%99.b%C9%99l%2F"},{"id":"lv_6_233","topic":"Business and Humanities Studies","word":"version","pos":"(n)","ipa":"/ˈvɜːr.ʒən/","defVi":"phiên bản","defEn":"a particular form of something that differs in some way from an earlier form or other forms","examples":["You should install the latest [version] of the software to fix the security bug. (=Dịch: Bạn nên cài đặt phiên bản phần mềm mới nhất để vá lỗi bảo mật.)","Her [version] of the story differed greatly from what the witness described. (=Dịch: Lời kể của cô ấy về câu chuyện khác rất nhiều so với những gì nhân chứng miêu tả.)","The film director decided to release an extended [version] for the fans. (=Dịch: Đạo diễn bộ phim đã quyết định phát hành một phiên bản mở rộng dành cho người hâm mộ.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9C%CB%90r.%CA%92%C9%99n%2F"},{"id":"lv_6_234","topic":"Business and Humanities Studies","word":"victim","pos":"(n)","ipa":"/ˈvɪk.tɪm/","defVi":"nạn nhân","defEn":"a person harmed, injured, or killed as a result of a crime, accident, or event","examples":["The rescue team worked tirelessly to save the [victim] trapped under the rubble. (=Dịch: Đội cứu hộ đã làm việc không mệt mỏi để cứu nạn nhân bị mắc kẹt dưới đống đổ nát.)","She was a [victim] of online fraud and lost a significant amount of money. (=Dịch: Cô ấy là nạn nhân của một vụ lừa đảo trực tuyến và đã mất một số tiền lớn.)","The charity provides counseling and legal aid to any [victim] of domestic violence. (=Dịch: Tổ chức từ thiện cung cấp tư vấn tâm lý và hỗ trợ pháp lý cho bất kỳ nạn nhân nào của bạo lực gia đình.)"],"ukAudio":"/ai_services/tts3/?q=victim&lang=en-GB&ipa=%2F%CB%88v%C9%AAk.t%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=victim&lang=en-US&ipa=%2F%CB%88v%C9%AAk.t%C9%AAm%2F"},{"id":"lv_6_235","topic":"Business and Humanities Studies","word":"violinist","pos":"(n)","ipa":"/ˌvaɪ.əˈlɪn.ɪst/","defVi":"nghệ sĩ vĩ cầm, người chơi đàn violin","defEn":"a person who plays the violin","examples":["The talented [violinist] performed a breathtaking solo during the concert. (=Dịch: Nghệ sĩ vĩ cầm tài năng đã trình diễn một bản độc tấu ngoạn mục trong buổi hòa nhạc.)","She practiced for hours every day to become a professional [violinist]. (=Dịch: Cô ấy luyện tập hàng giờ mỗi ngày để trở thành một nghệ sĩ vĩ cầm chuyên nghiệp.)","The orchestra is holding auditions to hire a new lead [violinist]. (=Dịch: Dàn nhạc đang tổ chức các buổi thử giọng để tuyển một nghệ sĩ vĩ cầm trưởng mới.)"],"ukAudio":"/ai_services/tts3/?q=violinist&lang=en-GB&ipa=%2F%CB%8Cva%C9%AA.%C9%99%CB%88l%C9%AAn.%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=violinist&lang=en-US&ipa=%2F%CB%8Cva%C9%AA.%C9%99%CB%88l%C9%AAn.%C9%AAst%2F"},{"id":"lv_6_236","topic":"Business and Humanities Studies","word":"vision","pos":"(n)","ipa":"/ˈvɪʒ.ən/","defVi":"tầm nhìn, thị giác","defEn":"the ability to imagine how something could develop in the future, or the ability to see","examples":["The leader shared his ambitious [vision] for the city's future. (=Dịch: Vị lãnh đạo đã chia sẻ tầm nhìn đầy tham vọng của mình về tương lai của thành phố.)","Poor lighting can affect your [vision] when reading at night. (=Dịch: Ánh sáng yếu có thể ảnh hưởng đến thị lực của bạn khi đọc sách vào ban đêm.)","She had a clear [vision] of how her business should expand. (=Dịch: Cô ấy có một định hướng rõ ràng về cách mở rộng doanh nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=vision&lang=en-GB&ipa=%2F%CB%88v%C9%AA%CA%92.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=vision&lang=en-US&ipa=%2F%CB%88v%C9%AA%CA%92.%C9%99n%2F"},{"id":"lv_6_237","topic":"Business and Humanities Studies","word":"wheelchair","pos":"(n)","ipa":"/ˈwiːl.tʃer/","defVi":"xe lăn","defEn":"a chair with wheels used by people who cannot walk due to illness or disability","examples":["The new library has ramps installed for visitors who use a [wheelchair]. (=Dịch: Thư viện mới đã lắp đặt các đường dốc dành cho khách đến thăm sử dụng xe lăn.)","He remained active in sports despite being confined to a [wheelchair]. (=Dịch: Anh ấy vẫn tích cực chơi thể thao dù phải ngồi xe lăn.)","Modern buildings should always provide adequate [wheelchair] access. (=Dịch: Các tòa nhà hiện đại phải luôn cung cấp lối đi phù hợp cho xe lăn.)"],"ukAudio":"/ai_services/tts3/?q=wheelchair&lang=en-GB&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F","usAudio":"/ai_services/tts3/?q=wheelchair&lang=en-US&ipa=%2F%CB%88wi%CB%90l.t%CA%83er%2F"},{"id":"lv_6_238","topic":"Business and Humanities Studies","word":"workforce","pos":"(n)","ipa":"/ˈwɜːrk.fɔːrs/","defVi":"lực lượng lao động, đội ngũ nhân sự","defEn":"the total number of people who are available to work or employed in a country or company","examples":["Women now make up nearly half of the country's total [workforce]. (=Dịch: Phụ nữ hiện chiếm gần một nửa tổng lực lượng lao động của cả nước.)","The company decided to reduce its [workforce] to cut operational costs. (=Dịch: Công ty đã quyết định cắt giảm nhân sự để giảm thiểu chi phí vận hành.)","Rapid technological advances require a highly skilled and adaptable [workforce]. (=Dịch: Những tiến bộ công nghệ nhanh chóng đòi hỏi một lực lượng lao động có tay nghề cao và thích ứng tốt.)"],"ukAudio":"/ai_services/tts3/?q=workforce&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90rk.f%C9%94%CB%90rs%2F","usAudio":"/ai_services/tts3/?q=workforce&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90rk.f%C9%94%CB%90rs%2F"},{"id":"lv_6_239","topic":"Business and Humanities Studies","word":"workplace","pos":"(n)","ipa":"/ˈwɝːk.pleɪs/","defVi":"nơi làm việc, môi trường công sở","defEn":"a building, office, or area where people do their jobs","examples":["Safety regulations must be strictly enforced in every industrial [workplace]. (=Dịch: Các quy định an toàn phải được thực thi nghiêm ngặt tại mọi nơi làm việc công nghiệp.)","A supportive [workplace] culture can significantly boost employee morale. (=Dịch: Một văn hóa môi trường công sở mang tính hỗ trợ có thể nâng cao đáng kể tinh thần của nhân viên.)","Flexibility has become a major factor in modern [workplace] design. (=Dịch: Tính linh hoạt đã trở thành một yếu tố quan trọng trong thiết kế nơi làm việc hiện đại.)"],"ukAudio":"/ai_services/tts3/?q=workplace&lang=en-GB&ipa=%2F%CB%88w%C9%9D%CB%90k.ple%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=workplace&lang=en-US&ipa=%2F%CB%88w%C9%9D%CB%90k.ple%C9%AAs%2F"},{"id":"lv_6_240","topic":"Business and Humanities Studies","word":"worthwhile","pos":"(adj)","ipa":"/ˌwɝːθˈwaɪl/","defVi":"đáng giá, bõ công","defEn":"useful, important, or good enough to spend time, money, or effort on","examples":["Volunteering in the local community is a very [worthwhile] activity. (=Dịch: Làm tình nguyện trong cộng đồng địa phương là một hoạt động rất đáng giá.)","It was a long journey, but the experience made it [worthwhile]. (=Dịch: Đó là một chuyến đi dài, nhưng trải nghiệm đã khiến nó hoàn toàn bõ công.)","She felt that learning a second language was a truly [worthwhile] investment. (=Dịch: Cô ấy cảm thấy việc học ngôn ngữ thứ hai là một sự đầu tư thực sự xứng đáng.)"],"ukAudio":"/ai_services/tts3/?q=worthwhile&lang=en-GB&ipa=%2F%CB%8Cw%C9%9D%CB%90%CE%B8%CB%88wa%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=worthwhile&lang=en-US&ipa=%2F%CB%8Cw%C9%9D%CB%90%CE%B8%CB%88wa%C9%AAl%2F"}]},"rawTopic":"Business and Humanities Studies"},{"id":"listening_u5_8","title":"Chủ đề 8/10: Education and Learning","actTitle":"Từ vựng chủ đề: Education and Learning (183 từ)","problem":{"pType":"topic_flashcards","topic":"Education and Learning","count":183,"words":[{"id":"lv_7_0","topic":"Education and Learning","word":"accompany","pos":"(v)","ipa":"/əˈkʌm.pə.ni/","defVi":"đi cùng, đồng hành, đi kèm với","defEn":"to go somewhere with someone as a companion, or to happen together with something","examples":["Children under twelve must be [accompany]ed by an adult at the pool. (=Dịch: Trẻ em dưới mười hai tuổi phải có người lớn đi cùng tại hồ bơi.)","Fever is often [accompany]ed by a sore throat and headache. (=Dịch: Sốt thường đi kèm với đau họng và nhức đầu.)","He offered to [accompany] her to the train station late at night. (=Dịch: Anh ấy đã đề nghị đi cùng cô ấy ra ga tàu vào đêm muộn.)"],"ukAudio":"/ai_services/tts3/?q=accompany&lang=en-GB&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F","usAudio":"/ai_services/tts3/?q=accompany&lang=en-US&ipa=%2F%C9%99%CB%88k%CA%8Cm.p%C9%99.ni%2F"},{"id":"lv_7_1","topic":"Education and Learning","word":"admission","pos":"(n)","ipa":"/ədˈmɪʃ.ən/","defVi":"sự nhận vào, sự tuyển sinh, quyền vào cửa","defEn":"the permission or right to enter a place or become a member of an institution","examples":["She received an offer of [admission] from her dream university. (=Dịch: Cô ấy đã nhận được giấy báo trúng tuyển từ trường đại học mơ ước của mình.)","The museum offers free [admission] on the first Sunday of every month. (=Dịch: Bảo tàng miễn phí vé vào cửa vào ngày chủ nhật đầu tiên của mỗi tháng.)","The hospital arranged the immediate [admission] of the injured patient. (=Dịch: Bệnh viện đã sắp xếp việc tiếp nhận nhập viện ngay lập tức cho bệnh nhân bị thương.)"],"ukAudio":"/ai_services/tts3/?q=admission&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AA%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=admission&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AA%CA%83.%C9%99n%2F"},{"id":"lv_7_2","topic":"Education and Learning","word":"admit","pos":"(v)","ipa":"/ədˈmɪt/","defVi":"thừa nhận, nhận vào","defEn":"to agree that something is true, or to allow someone to enter","examples":["He had to [admit] that he made a serious mistake. (=Dịch: Anh ấy đã phải thừa nhận rằng mình đã phạm một sai lầm nghiêm trọng.)","She was thrilled to be [admit]ted to the top university in the country. (=Dịch: Cô ấy rất vui mừng khi được nhận vào trường đại học hàng đầu trong nước.)","Only ticket holders will be [admit]ted into the stadium. (=Dịch: Chỉ những người có vé mới được vào sân vận động.)"],"ukAudio":"/ai_services/tts3/?q=admit&lang=en-GB&ipa=%2F%C9%99d%CB%88m%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=admit&lang=en-US&ipa=%2F%C9%99d%CB%88m%C9%AAt%2F"},{"id":"lv_7_3","topic":"Education and Learning","word":"allocate","pos":"(v)","ipa":"/ˈæl.ə.keɪt/","defVi":"phân bổ, cấp phát","defEn":"to distribute resources or duties for a particular purpose","examples":["The government plans to [allocate] more funds to public healthcare. (=Dịch: Chính phủ dự định phân bổ thêm ngân sách cho y tế công cộng.)","Each team member was asked to [allocate] two hours a day to the new project. (=Dịch: Mỗi thành viên trong nhóm được yêu cầu dành ra hai giờ mỗi ngày cho dự án mới.)","The city council will [allocate] land for building affordable housing. (=Dịch: Hội đồng thành phố sẽ cấp đất để xây dựng nhà ở giá rẻ.)"],"ukAudio":"/ai_services/tts3/?q=allocate&lang=en-GB&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=allocate&lang=en-US&ipa=%2F%CB%88%C3%A6l.%C9%99.ke%C9%AAt%2F"},{"id":"lv_7_4","topic":"Education and Learning","word":"ambitious","pos":"(adj)","ipa":"/æmˈbɪʃ.əs/","defVi":"có hoài bão, đầy tham vọng","defEn":"having a strong desire to achieve success, power, or wealth","examples":["She is an [ambitious] student who aims to get a scholarship abroad. (=Dịch: Cô ấy là một học sinh đầy hoài bão với mục tiêu giành học bổng du học.)","The company announced an [ambitious] plan to open ten new stores this year. (=Dịch: Công ty đã công bố một kế hoạch đầy tham vọng nhằm mở mười cửa hàng mới trong năm nay.)","He set an [ambitious] target for his daily running routine. (=Dịch: Anh ấy đã đặt ra một mục tiêu đầy tham vọng cho thói quen chạy bộ hàng ngày của mình.)"],"ukAudio":"/ai_services/tts3/?q=ambitious&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F","usAudio":"/ai_services/tts3/?q=ambitious&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C9%AA%CA%83.%C9%99s%2F"},{"id":"lv_7_5","topic":"Education and Learning","word":"anymore","pos":"(adv)","ipa":"/ˌɛn.iˈmɔr/","defVi":"nữa (dùng trong câu phủ định hoặc nghi vấn để chỉ việc không còn tiếp diễn)","defEn":"no longer or not now as in the past","examples":["She does not live in this neighborhood [anymore]. (=Dịch: Cô ấy không còn sống ở khu phố này nữa.)","I cannot tolerate this noisy environment [anymore]. (=Dịch: Tôi không thể chịu đựng môi trường ồn ào này thêm nữa.)","Do you go jogging in the park [anymore]? (=Dịch: Bạn còn chạy bộ trong công viên nữa không?)"],"ukAudio":"/ai_services/tts3/?q=anymore&lang=en-GB&ipa=%2F%CB%8C%C9%9Bn.i%CB%88m%C9%94r%2F","usAudio":"/ai_services/tts3/?q=anymore&lang=en-US&ipa=%2F%CB%8C%C9%9Bn.i%CB%88m%C9%94r%2F"},{"id":"lv_7_6","topic":"Education and Learning","word":"assess","pos":"(v)","ipa":"/əˈses/","defVi":"đánh giá, định giá","defEn":"to judge or evaluate the amount, value, quality, or importance of something","examples":["The committee will [assess] the environmental impact of the new highway. (=Dịch: Ủy ban sẽ đánh giá tác động môi trường của tuyến đường cao tốc mới.)","Exams are commonly used to [assess] students' understanding of the subject. (=Dịch: Các kỳ thi thường được sử dụng để đánh giá mức độ hiểu biết của học sinh về môn học.)","Experts were sent to [assess] the total damage caused by the earthquake. (=Dịch: Các chuyên gia đã được cử đến để đánh giá toàn bộ thiệt hại do trận động đất gây ra.)"],"ukAudio":"/ai_services/tts3/?q=assess&lang=en-GB&ipa=%2F%C9%99%CB%88ses%2F","usAudio":"/ai_services/tts3/?q=assess&lang=en-US&ipa=%2F%C9%99%CB%88ses%2F"},{"id":"lv_7_7","topic":"Education and Learning","word":"audio","pos":"(adj)","ipa":"/ˈɑː.di.oʊ/","defVi":"thuộc về âm thanh","defEn":"connected with sound or the recording and broadcasting of sound","examples":["The teacher used [audio] recordings to help students practice their listening skills. (=Dịch: Giáo viên đã sử dụng các bản ghi âm để giúp học sinh luyện kỹ năng nghe.)","High-quality [audio] equipment is essential for producing professional podcasts. (=Dịch: Thiết bị âm thanh chất lượng cao là điều cần thiết để sản xuất các podcast chuyên nghiệp.)","She plugged her headphones into the [audio] jack of her laptop. (=Dịch: Cô ấy cắm tai nghe vào giắc cắm âm thanh trên máy tính xách tay của mình.)"],"ukAudio":"/ai_services/tts3/?q=audio&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F","usAudio":"/ai_services/tts3/?q=audio&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.di.o%CA%8A%2F"},{"id":"lv_7_8","topic":"Education and Learning","word":"balloon","pos":"(n)","ipa":"/bəˈlun/","defVi":"bong bóng, quả bóng bay","defEn":"a small rubber bag that is filled with air or gas and used as a toy or decoration","examples":["The children played happily with a red [balloon] in the park. (=Dịch: Lũ trẻ chơi đùa vui vẻ với một quả bóng bay màu đỏ trong công viên.)","We bought colorful [balloon] decorations for the birthday party. (=Dịch: Chúng tôi đã mua đồ trang trí bong bóng nhiều màu sắc cho bữa tiệc sinh nhật.)","He watched the [balloon] float higher and higher into the sky. (=Dịch: Cậu bé nhìn quả bóng bay bay ngày càng cao lên bầu trời.)"],"ukAudio":"/ai_services/tts3/?q=balloon&lang=en-GB&ipa=%2Fb%C9%99%CB%88lun%2F","usAudio":"/ai_services/tts3/?q=balloon&lang=en-US&ipa=%2Fb%C9%99%CB%88lun%2F"},{"id":"lv_7_9","topic":"Education and Learning","word":"bat","pos":"(n)","ipa":"/bæt/","defVi":"con dơi; gậy đánh bóng","defEn":"a flying nocturnal mammal, or a wooden stick used in sports","examples":["A small [bat] flew out of the dark cave at sunset. (=Dịch: Một con dơi nhỏ bay ra khỏi hang tối vào lúc hoàng hôn.)","He swung the baseball [bat] with all his strength and hit a home run. (=Dịch: Anh ấy vung cây gậy bóng chày bằng tất cả sức mạnh và đánh một cú home run.)","Fruit [bat] species play a vital role in pollinating many plants. (=Dịch: Các loài dơi ăn quả đóng một vai trò quan trọng trong việc thụ phấn cho nhiều loài thực vật.)"],"ukAudio":"/ai_services/tts3/?q=bat&lang=en-GB&ipa=%2Fb%C3%A6t%2F","usAudio":"/ai_services/tts3/?q=bat&lang=en-US&ipa=%2Fb%C3%A6t%2F"},{"id":"lv_7_10","topic":"Education and Learning","word":"behalf","pos":"(n)","ipa":"/bɪˈhæf/","defVi":"sự đại diện, thay mặt","defEn":"as a representative of someone, or for the benefit of someone","examples":["The lawyer spoke on [behalf] of her client in court. (=Dịch: Luật sư đã thay mặt cho thân chủ của mình phát biểu tại tòa.)","She accepted the award on [behalf] of the entire research team. (=Dịch: Cô ấy đã nhận giải thưởng thay mặt cho toàn bộ nhóm nghiên cứu.)","He campaigned tirelessly on [behalf] of homeless people in the city. (=Dịch: Anh ấy đã vận động không mệt mỏi vì quyền lợi của những người vô gia cư trong thành phố.)"],"ukAudio":"/ai_services/tts3/?q=behalf&lang=en-GB&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=behalf&lang=en-US&ipa=%2Fb%C9%AA%CB%88h%C3%A6f%2F"},{"id":"lv_7_11","topic":"Education and Learning","word":"bother","pos":"(v)","ipa":"/ˈbɑː.ðɚ/","defVi":"Làm phiền, bận tâm, bận lòng.","defEn":"To make an effort to do something, or to cause someone mild annoyance or trouble.","examples":["I am sorry to [bother] you, but could you help me with this form? (=Dịch: Tôi xin lỗi vì đã làm phiền bạn, nhưng bạn có thể giúp tôi điền vào biểu mẫu này được không?)","He did not even [bother] to read the instructions before starting the test. (=Dịch: Cậu ấy thậm chí còn chẳng buồn đọc hướng dẫn trước khi bắt đầu bài kiểm tra.)","The loud construction noise outside began to [bother] the students during class. (=Dịch: Tiếng ồn xây dựng lớn bên ngoài bắt đầu làm phiền các học sinh trong suốt giờ học.)"],"ukAudio":"/ai_services/tts3/?q=bother&lang=en-GB&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F","usAudio":"/ai_services/tts3/?q=bother&lang=en-US&ipa=%2F%CB%88b%C9%91%CB%90.%C3%B0%C9%9A%2F"},{"id":"lv_7_12","topic":"Education and Learning","word":"breath","pos":"(n)","ipa":"/brɛθ/","defVi":"hơi thở","defEn":"the air that you take into and send out of your lungs","examples":["Take a deep [breath] before you start giving the presentation. (=Dịch: Hãy hít một hơi thật sâu trước khi bạn bắt đầu thuyết trình.)","He was completely out of [breath] after running up the stairs. (=Dịch: Anh ấy hoàn toàn hụt hơi sau khi chạy lên cầu thang.)","You can see your [breath] in the freezing winter air. (=Dịch: Bạn có thể nhìn thấy hơi thở của mình trong không khí giá lạnh mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=breath&lang=en-GB&ipa=%2Fbr%C9%9B%CE%B8%2F","usAudio":"/ai_services/tts3/?q=breath&lang=en-US&ipa=%2Fbr%C9%9B%CE%B8%2F"},{"id":"lv_7_13","topic":"Education and Learning","word":"breathe","pos":"(v)","ipa":"/ˈbrið/","defVi":"thở, hít thở","defEn":"to take air into your lungs and let it out again","examples":["Doctors advise people to [breathe] deeply whenever they feel stressed. (=Dịch: Bác sĩ khuyên mọi người nên hít thở sâu bất cứ khi nào cảm thấy căng thẳng.)","It was difficult to [breathe] at the top of the mountain due to the thin air. (=Dịch: Rất khó để thở trên đỉnh núi do không khí loãng.)","Patients with asthma often struggle to [breathe] during sudden weather changes. (=Dịch: Bệnh nhân hen suyễn thường gặp khó khăn khi thở trong những đợt thay đổi thời tiết đột ngột.)"],"ukAudio":"/ai_services/tts3/?q=breathe&lang=en-GB&ipa=%2F%CB%88bri%C3%B0%2F","usAudio":"/ai_services/tts3/?q=breathe&lang=en-US&ipa=%2F%CB%88bri%C3%B0%2F"},{"id":"lv_7_14","topic":"Education and Learning","word":"bullet","pos":"(n)","ipa":"/ˈbʊl.ɪt/","defVi":"viên đạn, dấu đầu dòng","defEn":"a small metal projectile fired from a gun; a small symbol used in text formatting","examples":["The soldier managed to dodge a stray [bullet] during the skirmish. (=Dịch: Người lính đã né được một viên đạn lạc trong trận giao tranh.)","Use a [bullet] point for each main idea in your presentation slide. (=Dịch: Hãy dùng một dấu đầu dòng cho mỗi ý chính trong trang trình bày của bạn.)","Police found a [bullet] casing at the crime scene. (=Dịch: Cảnh sát đã tìm thấy một vỏ đạn tại hiện trường vụ án.)"],"ukAudio":"/ai_services/tts3/?q=bullet&lang=en-GB&ipa=%2F%CB%88b%CA%8Al.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=bullet&lang=en-US&ipa=%2F%CB%88b%CA%8Al.%C9%AAt%2F"},{"id":"lv_7_15","topic":"Education and Learning","word":"calm","pos":"(adj)","ipa":"/kɑːm/","defVi":"bình tĩnh, điềm tĩnh, êm ả","defEn":"peaceful, quiet, and not showing anger, worry, or excitement","examples":["It is important to stay [calm] during an unexpected emergency. (=Dịch: Việc giữ bình tĩnh trong trường hợp khẩn cấp bất ngờ là rất quan trọng.)","The sea was unusually [calm] in the early morning. (=Dịch: Biển sáng sớm hôm nay phẳng lặng lạ thường.)","Her [calm] voice helped reassure the frightened child. (=Dịch: Giọng nói điềm tĩnh của cô ấy đã giúp trấn an đứa trẻ đang sợ hãi.)"],"ukAudio":"/ai_services/tts3/?q=calm&lang=en-GB&ipa=%2Fk%C9%91%CB%90m%2F","usAudio":"/ai_services/tts3/?q=calm&lang=en-US&ipa=%2Fk%C9%91%CB%90m%2F"},{"id":"lv_7_16","topic":"Education and Learning","word":"campus","pos":"(n)","ipa":"/ˈkæm.pəs/","defVi":"Khuôn viên trường học","defEn":"The grounds and buildings of a university, college, or school","examples":["The main university [campus] is located near the city center. (=Dịch: Khuôn viên chính của trường đại học nằm gần trung tâm thành phố.)","First-year students are encouraged to live on [campus] to make new friends. (=Dịch: Sinh viên năm nhất được khuyến khích sống trong khuôn viên trường để kết bạn mới.)","Several modern sports facilities were recently built on the new [campus]. (=Dịch: Một số cơ sở thể thao hiện đại gần đây đã được xây dựng trong khuôn viên trường mới.)"],"ukAudio":"/ai_services/tts3/?q=campus&lang=en-GB&ipa=%2F%CB%88k%C3%A6m.p%C9%99s%2F","usAudio":"/ai_services/tts3/?q=campus&lang=en-US&ipa=%2F%CB%88k%C3%A6m.p%C9%99s%2F"},{"id":"lv_7_17","topic":"Education and Learning","word":"cardboard","pos":"(n)","ipa":"/ˈkɑrd.bɔrd/","defVi":"bìa cứng, các-tông","defEn":"stiff, thick paper used for making boxes and packaging","examples":["We packed all our old books into a large [cardboard] box. (=Dịch: Chúng tôi đã đóng gói tất cả sách cũ của mình vào một chiếc hộp các-tông lớn.)","Children often enjoy making creative toys out of recycled [cardboard]. (=Dịch: Trẻ em thường thích làm đồ chơi sáng tạo từ bìa các-tông tái chế.)","The fragile items were protected by several layers of [cardboard]. (=Dịch: Những món đồ dễ vỡ được bảo vệ bởi nhiều lớp bìa cứng.)"],"ukAudio":"/ai_services/tts3/?q=cardboard&lang=en-GB&ipa=%2F%CB%88k%C9%91rd.b%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=cardboard&lang=en-US&ipa=%2F%CB%88k%C9%91rd.b%C9%94rd%2F"},{"id":"lv_7_18","topic":"Education and Learning","word":"chapter","pos":"(n)","ipa":"/ˈtʃæp.tɚ/","defVi":"chương (sách)","defEn":"one of the main sections into which a book is divided","examples":["I am reading the final [chapter] of this novel. (=Dịch: Tôi đang đọc chương cuối cùng của cuốn tiểu thuyết này.)","The teacher assigned [chapter] four for tonight's homework. (=Dịch: Giáo viên đã giao chương bốn làm bài tập về nhà tối nay.)","Graduating from university marked a new [chapter] in her life. (=Dịch: Tốt nghiệp đại học đã đánh dấu một chương mới trong cuộc đời cô ấy.)"],"ukAudio":"/ai_services/tts3/?q=chapter&lang=en-GB&ipa=%2F%CB%88t%CA%83%C3%A6p.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chapter&lang=en-US&ipa=%2F%CB%88t%CA%83%C3%A6p.t%C9%9A%2F"},{"id":"lv_7_19","topic":"Education and Learning","word":"checking","pos":"(n)","ipa":"/ˈtʃek.ɪŋ/","defVi":"việc kiểm tra, rà soát","defEn":"the act of examining something to ensure its correctness, safety, or quality","examples":["Regular [checking] of the equipment ensures the safety of the workers. (=Dịch: Việc kiểm tra thiết bị định kỳ đảm bảo an toàn cho công nhân.)","After thorough [checking], the auditor found no errors in the financial report. (=Dịch: Sau khi rà soát kỹ lưỡng, kiểm toán viên không tìm thấy sai sót nào trong báo cáo tài chính.)","The security staff is responsible for the [checking] of all visitors' luggage. (=Dịch: Nhân viên an ninh chịu trách nhiệm kiểm tra hành lý của tất cả du khách.)"],"ukAudio":"/ai_services/tts3/?q=checking&lang=en-GB&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=checking&lang=en-US&ipa=%2F%CB%88t%CA%83ek.%C9%AA%C5%8B%2F"},{"id":"lv_7_20","topic":"Education and Learning","word":"childcare","pos":"(n)","ipa":"/ˈtʃaɪld.ker/","defVi":"việc trông nom, chăm sóc trẻ em","defEn":"the care of children, especially by a day-care center or babysitter while parents are at work","examples":["High [childcare] costs prevent many parents from returning to full-time work. (=Dịch: Chi phí chăm sóc trẻ cao khiến nhiều bậc cha mẹ không thể quay lại làm việc toàn thời gian.)","The company provides free [childcare] facilities for its employees. (=Dịch: Công ty cung cấp cơ sở trông trẻ miễn phí cho nhân viên của mình.)","She is looking for a reliable [childcare] provider near her home. (=Dịch: Cô ấy đang tìm kiếm một nơi gửi trẻ đáng tin cậy gần nhà.)"],"ukAudio":"/ai_services/tts3/?q=childcare&lang=en-GB&ipa=%2F%CB%88t%CA%83a%C9%AAld.ker%2F","usAudio":"/ai_services/tts3/?q=childcare&lang=en-US&ipa=%2F%CB%88t%CA%83a%C9%AAld.ker%2F"},{"id":"lv_7_21","topic":"Education and Learning","word":"chronological","pos":"(adj)","ipa":"/ˌkrɑ.nəˈlɑ.dʒɪ.kəl/","defVi":"theo trình tự thời gian","defEn":"arranged in the order in which events happened","examples":["The museum displays historical artifacts in strict [chronological] order. (=Dịch: Bảo tàng trưng bày các hiện vật lịch sử theo đúng trình tự thời gian.)","Please list your previous work experience in [chronological] sequence on your resume. (=Dịch: Vui lòng liệt kê kinh nghiệm làm việc trước đây của bạn theo thứ tự thời gian trong hồ sơ xin việc.)","The biographer recounted the artist's life through a clear [chronological] narrative. (=Dịch: Người viết tiểu sử đã kể lại cuộc đời của người nghệ sĩ thông qua một mạch dẫn chuyện theo thời gian rõ ràng.)"],"ukAudio":"/ai_services/tts3/?q=chronological&lang=en-GB&ipa=%2F%CB%8Ckr%C9%91.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=chronological&lang=en-US&ipa=%2F%CB%8Ckr%C9%91.n%C9%99%CB%88l%C9%91.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_7_22","topic":"Education and Learning","word":"clarity","pos":"(n)","ipa":"/ˈklær.ə.t̬i/","defVi":"sự rõ ràng, tính minh bạch","defEn":"the quality of being clear and easy to understand or see","examples":["The teacher explained the complex math topic with great [clarity]. (=Dịch: Giáo viên đã giải thích chủ đề toán học phức tạp một cách rất rõ ràng.)","Writing with [clarity] helps readers follow your main argument easily. (=Dịch: Viết một cách rõ ràng giúp người đọc dễ dàng theo dõi luận điểm chính của bạn.)","The water in the mountain lake is famous for its incredible [clarity]. (=Dịch: Nước trong hồ trên núi nổi tiếng với độ trong vắt đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=clarity&lang=en-GB&ipa=%2F%CB%88kl%C3%A6r.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=clarity&lang=en-US&ipa=%2F%CB%88kl%C3%A6r.%C9%99.t%CC%ACi%2F"},{"id":"lv_7_23","topic":"Education and Learning","word":"classmate","pos":"(n)","ipa":"/ˈklæs.meɪt/","defVi":"Bạn cùng lớp.","defEn":"A person who is in the same class as you at school or college.","examples":["She collaborated with her [classmate] on the biology project. (=Dịch: Cô ấy đã hợp tác với bạn cùng lớp trong dự án sinh học.)","I met an old [classmate] while shopping at the supermarket yesterday. (=Dịch: Hôm qua tôi tình cờ gặp một người bạn học cũ khi đang mua sắm ở siêu thị.)","He asked his [classmate] to lend him some lecture notes. (=Dịch: Cậu ấy đã nhờ bạn cùng lớp cho mượn một số ghi chép bài giảng.)"],"ukAudio":"/ai_services/tts3/?q=classmate&lang=en-GB&ipa=%2F%CB%88kl%C3%A6s.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=classmate&lang=en-US&ipa=%2F%CB%88kl%C3%A6s.me%C9%AAt%2F"},{"id":"lv_7_24","topic":"Education and Learning","word":"confused","pos":"(adj)","ipa":"/kənˈfjuzd/","defVi":"bối rối, hoang mang, lúng túng","defEn":"unable to understand clearly or think properly","examples":["The instructions were unclear, so many students felt [confused]. (=Dịch: Hướng dẫn không rõ ràng nên nhiều học sinh cảm thấy bối rối.)","She looked completely [confused] when asked about the missing files. (=Dịch: Cô ấy trông hoàn toàn hoang mang khi được hỏi về các tập tin bị mất.)","I am [confused] about which university course I should choose. (=Dịch: Tôi đang phân vân không biết nên chọn khóa học đại học nào.)"],"ukAudio":"/ai_services/tts3/?q=confused&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fjuzd%2F","usAudio":"/ai_services/tts3/?q=confused&lang=en-US&ipa=%2Fk%C9%99n%CB%88fjuzd%2F"},{"id":"lv_7_25","topic":"Education and Learning","word":"confusing","pos":"(adj)","ipa":"/kənˈfju.zɪŋ/","defVi":"gây bối rối, khó hiểu","defEn":"difficult to understand; not clear","examples":["The instructions on the box were very [confusing] for the beginners. (=Dịch: Hướng dẫn trên vỏ hộp rất khó hiểu đối với người mới bắt đầu.)","I found the ending of the movie rather [confusing]. (=Dịch: Tôi thấy cái kết của bộ phim khá khó hiểu.)","The city has a [confusing] network of one-way streets. (=Dịch: Thành phố có một mạng lưới đường một chiều gây rối mắt.)"],"ukAudio":"/ai_services/tts3/?q=confusing&lang=en-GB&ipa=%2Fk%C9%99n%CB%88fju.z%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=confusing&lang=en-US&ipa=%2Fk%C9%99n%CB%88fju.z%C9%AA%C5%8B%2F"},{"id":"lv_7_26","topic":"Education and Learning","word":"congratulation","pos":"(n)","ipa":"/kənˌɡrætʃ.əˈleɪ.ʃən/","defVi":"lời chúc mừng, sự chúc mừng","defEn":"an expression of praise for someone's success or good luck","examples":["She sent a message of [congratulation] to the winning team. (=Dịch: Cô ấy đã gửi một thông điệp chúc mừng đến đội chiến thắng.)","He offered his sincere [congratulation] on her promotion. (=Dịch: Anh ấy gửi lời chúc mừng chân thành về việc cô được thăng chức.)","A letter of [congratulation] was delivered to the award recipient. (=Dịch: Một lá thư chúc mừng đã được chuyển đến người nhận giải thưởng.)"],"ukAudio":"/ai_services/tts3/?q=congratulation&lang=en-GB&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=congratulation&lang=en-US&ipa=%2Fk%C9%99n%CB%8C%C9%A1r%C3%A6t%CA%83.%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_27","topic":"Education and Learning","word":"convenor","pos":"(n)","ipa":"/kənˈvi.nɚ/","defVi":"người triệu tập, người chủ trì cuộc họp","defEn":"a person who arranges and chairs meetings of a committee or group","examples":["The [convenor] opened the committee meeting by introducing the agenda. (=Dịch: Người triệu tập đã mở đầu cuộc họp ủy ban bằng cách giới thiệu chương trình nghị sự.)","Please send your discussion topics to the conference [convenor] before Friday. (=Dịch: Vui lòng gửi các chủ đề thảo luận của bạn cho người triệu tập hội nghị trước thứ Sáu.)","As the study group [convenor], she ensured everyone had a chance to speak. (=Dịch: Với tư cách là người chủ trì nhóm học tập, cô ấy đảm bảo mọi người đều có cơ hội phát biểu.)"],"ukAudio":"/ai_services/tts3/?q=convenor&lang=en-GB&ipa=%2Fk%C9%99n%CB%88vi.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=convenor&lang=en-US&ipa=%2Fk%C9%99n%CB%88vi.n%C9%9A%2F"},{"id":"lv_7_28","topic":"Education and Learning","word":"counselling","pos":"(n)","ipa":"/ˈkaʊn.səl.ɪŋ/","defVi":"sự tư vấn, sự tham vấn tâm lý","defEn":"professional guidance and support to help people resolve personal or psychological problems","examples":["The university offers free student [counselling] for those experiencing stress. (=Dịch: Trường đại học cung cấp dịch vụ tư vấn sinh viên miễn phí cho những ai đang bị căng thẳng.)","She decided to seek marriage [counselling] to work through their communication issues. (=Dịch: Cô ấy quyết định tìm đến tư vấn hôn nhân để giải quyết các vấn đề giao tiếp giữa hai người.)","Grief [counselling] helped him cope with the sudden loss of his father. (=Dịch: Dịch vụ tư vấn tâm lý sau mất mát đã giúp anh ấy vượt qua sự ra đi đột ngột của người cha.)"],"ukAudio":"/ai_services/tts3/?q=counselling&lang=en-GB&ipa=%2F%CB%88ka%CA%8An.s%C9%99l.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=counselling&lang=en-US&ipa=%2F%CB%88ka%CA%8An.s%C9%99l.%C9%AA%C5%8B%2F"},{"id":"lv_7_29","topic":"Education and Learning","word":"coursework","pos":"(n)","ipa":"/ˈkɔrs.wɝːk/","defVi":"bài tập trong khóa học, bài tập quá trình","defEn":"work done by students as part of their studies, contributing towards their final grade","examples":["Her final grade depends on both exam results and continuous [coursework]. (=Dịch: Điểm tổng kết của cô ấy phụ thuộc vào cả kết quả thi và các bài tập trong suốt khóa học.)","Students spent the weekend finishing their history [coursework] assignments. (=Dịch: Các sinh viên đã dành cả cuối tuần để hoàn thành bài tập môn lịch sử.)","Managing your time well is essential when dealing with heavy [coursework]. (=Dịch: Quản lý thời gian tốt là điều cần thiết khi phải xử lý khối lượng bài tập khóa học lớn.)"],"ukAudio":"/ai_services/tts3/?q=coursework&lang=en-GB&ipa=%2F%CB%88k%C9%94rs.w%C9%9D%CB%90k%2F","usAudio":"/ai_services/tts3/?q=coursework&lang=en-US&ipa=%2F%CB%88k%C9%94rs.w%C9%9D%CB%90k%2F"},{"id":"lv_7_30","topic":"Education and Learning","word":"cricket","pos":"(n)","ipa":"/ˈkrɪk.ɪt/","defVi":"môn bóng gậy (cricket); con dế","defEn":"an outdoor game played with bats, a ball, and wickets by two teams of eleven players","examples":["Many people in England and Australia love playing [cricket]. (=Dịch: Nhiều người ở Anh và Úc rất thích chơi môn bóng gậy.)","The sound of a [cricket] chirping kept him awake all night. (=Dịch: Tiếng dế kêu rỉ rả đã khiến anh ấy mất ngủ cả đêm.)","Our school has recently formed a new [cricket] team. (=Dịch: Trường chúng tôi gần đây đã thành lập một đội cricket mới.)"],"ukAudio":"/ai_services/tts3/?q=cricket&lang=en-GB&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=cricket&lang=en-US&ipa=%2F%CB%88kr%C9%AAk.%C9%AAt%2F"},{"id":"lv_7_31","topic":"Education and Learning","word":"crisis","pos":"(n)","ipa":"/ˈkraɪ.sɪs/","defVi":"cuộc khủng hoảng","defEn":"a time of great danger, difficulty, or uncertainty","examples":["The government is trying to resolve the current economic [crisis]. (=Dịch: Chính phủ đang nỗ lực giải quyết cuộc khủng hoảng kinh tế hiện nay.)","She managed to stay calm throughout the family [crisis]. (=Dịch: Cô ấy đã cố gắng giữ bình tĩnh trong suốt biến cố của gia đình.)","Climate change is leading to an environmental [crisis] across the globe. (=Dịch: Biến đổi khí hậu đang dẫn đến một cuộc khủng hoảng môi trường trên toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=crisis&lang=en-GB&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=crisis&lang=en-US&ipa=%2F%CB%88kra%C9%AA.s%C9%AAs%2F"},{"id":"lv_7_32","topic":"Education and Learning","word":"criterion","pos":"(n)","ipa":"/kraɪˈtɪr.i.ən/","defVi":"tiêu chí, chuẩn mực","defEn":"a standard by which something is judged or decided","examples":["Academic ability is not the only [criterion] for university admission. (=Dịch: Năng lực học thuật không phải là tiêu chí duy nhất để xét tuyển đại học.)","Price was the main [criterion] we considered when choosing a hotel. (=Dịch: Giá cả là tiêu chí chính mà chúng tôi cân nhắc khi chọn khách sạn.)","Each candidate must meet the minimum [criterion] to qualify. (=Dịch: Mỗi ứng viên phải đáp ứng tiêu chí tối thiểu để đủ điều kiện.)"],"ukAudio":"/ai_services/tts3/?q=criterion&lang=en-GB&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=criterion&lang=en-US&ipa=%2Fkra%C9%AA%CB%88t%C9%AAr.i.%C9%99n%2F"},{"id":"lv_7_33","topic":"Education and Learning","word":"critical","pos":"(adj)","ipa":"/ˈkrɪt̬.ɪ.kəl/","defVi":"Then chốt, quan trọng; có tính phản biện, chỉ trích","defEn":"Extremely important or involving the objective analysis and evaluation of an issue","examples":["Developing [critical] thinking skills is essential for academic success. (=Dịch: Phát triển các kỹ năng tư duy phản biện là điều thiết yếu để đạt được thành công trong học tập.)","The doctor stated that the patient was in a [critical] condition. (=Dịch: Bác sĩ tuyên bố rằng bệnh nhân đang trong tình trạng nguy kịch.)","Timely communication plays a [critical] role in effective project management. (=Dịch: Giao tiếp kịp thời đóng một vai trò then chốt trong việc quản lý dự án hiệu quả.)"],"ukAudio":"/ai_services/tts3/?q=critical&lang=en-GB&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=critical&lang=en-US&ipa=%2F%CB%88kr%C9%AAt%CC%AC.%C9%AA.k%C9%99l%2F"},{"id":"lv_7_34","topic":"Education and Learning","word":"crystal","pos":"(n)","ipa":"/ˈkrɪs.təl/","defVi":"pha lê, tinh thể","defEn":"a clear, transparent mineral or piece of high-quality glass","examples":["The chandelier was made of hundreds of sparkling [crystal] pieces. (=Dịch: Chiếc đèn chùm được làm từ hàng trăm mảnh pha lê lấp lánh.)","Scientists studied the structure of the ice [crystal] under a microscope. (=Dịch: Các nhà khoa học đã nghiên cứu cấu trúc của tinh thể băng dưới kính hiển vi.)","She keeps a small quartz [crystal] on her study desk for decoration. (=Dịch: Cô ấy để một viên tinh thể thạch anh nhỏ trên bàn học để trang trí.)"],"ukAudio":"/ai_services/tts3/?q=crystal&lang=en-GB&ipa=%2F%CB%88kr%C9%AAs.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=crystal&lang=en-US&ipa=%2F%CB%88kr%C9%AAs.t%C9%99l%2F"},{"id":"lv_7_35","topic":"Education and Learning","word":"cursive","pos":"(adj)","ipa":"/ˈkɝː.sɪv/","defVi":"viết chữ thảo, chữ viết hoa/nối nét","defEn":"written with the characters joined together in a flowing style","examples":["Young children are taught how to write in [cursive] at elementary school. (=Dịch: Trẻ nhỏ được dạy cách viết chữ thảo ở trường tiểu học.)","His signature is written in an elegant [cursive] script. (=Dịch: Chữ ký của anh ấy được viết bằng nét chữ thảo rất thanh lịch.)","It is sometimes difficult to read old historical documents written in [cursive]. (=Dịch: Đôi khi rất khó để đọc các tài liệu lịch sử cổ được viết bằng chữ thảo.)"],"ukAudio":"/ai_services/tts3/?q=cursive&lang=en-GB&ipa=%2F%CB%88k%C9%9D%CB%90.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=cursive&lang=en-US&ipa=%2F%CB%88k%C9%9D%CB%90.s%C9%AAv%2F"},{"id":"lv_7_36","topic":"Education and Learning","word":"cushion","pos":"(n)","ipa":"/ˈkʊʃ.ən/","defVi":"gối đệm, vật đệm lót; lớp đệm bảo vệ","defEn":"a soft bag filled with soft material, used to make a seat more comfortable; something that softens an impact","examples":["She placed a comfortable [cushion] behind her back while working at her desk. (=Dịch: Cô ấy đặt một chiếc gối tựa êm ái sau lưng khi làm việc tại bàn.)","Emergency savings can act as a financial [cushion] against unexpected expenses. (=Dịch: Các khoản tiết kiệm khẩn cấp có thể đóng vai trò như một lớp đệm tài chính trước các chi phí bất ngờ.)","He bought several colorful [cushion]s to decorate the living room sofa. (=Dịch: Anh ấy đã mua vài chiếc gối đệm nhiều màu sắc để trang trí cho ghế sofa phòng khách.)"],"ukAudio":"/ai_services/tts3/?q=cushion&lang=en-GB&ipa=%2F%CB%88k%CA%8A%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=cushion&lang=en-US&ipa=%2F%CB%88k%CA%8A%CA%83.%C9%99n%2F"},{"id":"lv_7_37","topic":"Education and Learning","word":"dairy","pos":"(n)","ipa":"/ˈder.i/","defVi":"sản phẩm từ sữa; nơi sản xuất bơ sữa","defEn":"foods produced from milk, or a place where milk and milk products are processed","examples":["He cannot eat cheese or other [dairy] products because of his allergy. (=Dịch: Anh ấy không thể ăn phô mai hoặc các sản phẩm từ sữa khác vì bị dị ứng.)","Our family visited a local [dairy] farm during the weekend. (=Dịch: Gia đình chúng tôi đã đến thăm một trang trại bò sữa địa phương vào cuối tuần.)","The doctor advised her to reduce her daily intake of [dairy]. (=Dịch: Bác sĩ khuyên cô nên giảm lượng sản phẩm từ sữa tiêu thụ hàng ngày.)"],"ukAudio":"/ai_services/tts3/?q=dairy&lang=en-GB&ipa=%2F%CB%88der.i%2F","usAudio":"/ai_services/tts3/?q=dairy&lang=en-US&ipa=%2F%CB%88der.i%2F"},{"id":"lv_7_38","topic":"Education and Learning","word":"danish","pos":"(adj)","ipa":"/ˈdeɪ.nɪʃ/","defVi":"thuộc về Đan Mạch","defEn":"relating to Denmark, its people, or its language","examples":["She loves modern [danish] furniture design for its simplicity and elegance. (=Dịch: Cô ấy rất thích phong cách thiết kế nội thất Đan Mạch hiện đại vì sự đơn giản và thanh lịch.)","We enjoyed learning about traditional [danish] folklore during our trip to Copenhagen. (=Dịch: Chúng tôi rất thích tìm hiểu về văn hóa dân gian Đan Mạch truyền thống trong chuyến đi đến Copenhagen.)","The bakery is famous for its delicious [danish] pastries and fresh bread. (=Dịch: Tiệm bánh nổi tiếng với những chiếc bánh ngọt kiểu Đan Mạch thơm ngon và bánh mì tươi.)"],"ukAudio":"/ai_services/tts3/?q=danish&lang=en-GB&ipa=%2F%CB%88de%C9%AA.n%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=danish&lang=en-US&ipa=%2F%CB%88de%C9%AA.n%C9%AA%CA%83%2F"},{"id":"lv_7_39","topic":"Education and Learning","word":"denmark","pos":"(n)","ipa":"/ˈdɛn.mɑrk/","defVi":"Đan Mạch (quốc gia ở Bắc Âu)","defEn":"A Nordic country in Northern Europe whose capital is Copenhagen","examples":["Many international students choose to study in [denmark] due to its high living standards. (=Dịch: Nhiều sinh viên quốc tế chọn học tập tại Đan Mạch nhờ tiêu chuẩn sống cao tại đây.)","Cycling is one of the most popular modes of transport throughout [denmark]. (=Dịch: Đi xe đạp là một trong những phương tiện giao thông phổ biến nhất trên khắp Đan Mạch.)","She spent two weeks traveling across [denmark] during her summer vacation. (=Dịch: Cô ấy đã dành hai tuần đi du lịch khắp Đan Mạch trong kỳ nghỉ hè của mình.)"],"ukAudio":"/ai_services/tts3/?q=denmark&lang=en-GB&ipa=%2F%CB%88d%C9%9Bn.m%C9%91rk%2F","usAudio":"/ai_services/tts3/?q=denmark&lang=en-US&ipa=%2F%CB%88d%C9%9Bn.m%C9%91rk%2F"},{"id":"lv_7_40","topic":"Education and Learning","word":"detailed","pos":"(adj)","ipa":"/dɪˈteɪld/","defVi":"chi tiết, tỉ mỉ","defEn":"giving a lot of information with many facts and points","examples":["The architect presented a [detailed] plan for the new library building. (=Dịch: Kiến trúc sư đã trình bày một bản kế hoạch chi tiết cho tòa nhà thư viện mới.)","You should provide a [detailed] description of the incident in your report. (=Dịch: Bạn nên cung cấp một bản mô tả chi tiết về sự việc trong báo cáo của mình.)","The researcher carried out a [detailed] analysis of the survey results. (=Dịch: Nhà nghiên cứu đã tiến hành một phân tích chi tiết về kết quả khảo sát.)"],"ukAudio":"/ai_services/tts3/?q=detailed&lang=en-GB&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=detailed&lang=en-US&ipa=%2Fd%C9%AA%CB%88te%C9%AAld%2F"},{"id":"lv_7_41","topic":"Education and Learning","word":"dietary","pos":"(adj)","ipa":"/ˈdaɪ.ə.ter.i/","defVi":"thuộc chế độ ăn uống, ăn kiêng","defEn":"connected with the food that a person or animal regularly eats","examples":["You should inform the caterer about any special [dietary] requirements before the party. (=Dịch: Bạn nên thông báo cho bên cung cấp tiệc về bất kỳ yêu cầu ăn uống đặc biệt nào trước bữa tiệc.)","Doctors recommend making gradual [dietary] changes to lower cholesterol levels. (=Dịch: Các bác sĩ khuyên nên thay đổi dần dần chế độ ăn uống để hạ lượng cholesterol.)","Adequate [dietary] fiber is essential for maintaining a healthy digestive system. (=Dịch: Cung cấp đủ chất xơ trong chế độ ăn là điều cần thiết để duy trì hệ tiêu hóa khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=dietary&lang=en-GB&ipa=%2F%CB%88da%C9%AA.%C9%99.ter.i%2F","usAudio":"/ai_services/tts3/?q=dietary&lang=en-US&ipa=%2F%CB%88da%C9%AA.%C9%99.ter.i%2F"},{"id":"lv_7_42","topic":"Education and Learning","word":"diploma","pos":"(n)","ipa":"/dɪˈploʊ.mə/","defVi":"bằng cấp, chứng chỉ tốt nghiệp","defEn":"an official document issued by an educational institution showing that someone has successfully completed a course of study","examples":["After four years of hard work, she proudly received her high school [diploma]. (=Dịch: Sau bốn năm nỗ lực, cô ấy đã tự hào nhận được tấm bằng tốt nghiệp trung học của mình.)","You must submit a copy of your university [diploma] with the job application. (=Dịch: Bạn phải nộp một bản sao bằng tốt nghiệp đại học cùng với đơn xin việc.)","He enrolled in an online course to earn a [diploma] in digital marketing. (=Dịch: Anh ấy đã đăng ký một khóa học trực tuyến để lấy chứng chỉ về tiếp thị kỹ thuật số.)"],"ukAudio":"/ai_services/tts3/?q=diploma&lang=en-GB&ipa=%2Fd%C9%AA%CB%88plo%CA%8A.m%C9%99%2F","usAudio":"/ai_services/tts3/?q=diploma&lang=en-US&ipa=%2Fd%C9%AA%CB%88plo%CA%8A.m%C9%99%2F"},{"id":"lv_7_43","topic":"Education and Learning","word":"disadvantage","pos":"(n)","ipa":"/ˌdɪs.ədˈvæn.t̬ɪdʒ/","defVi":"Bất lợi, điểm yếu, nhược điểm.","defEn":"An unfavorable circumstance or condition that reduces the chances of success.","examples":["One major [disadvantage] of living in the countryside is the lack of public transport. (=Dịch: Một bất lợi lớn của việc sống ở nông thôn là sự thiếu thốn phương tiện giao thông công cộng.)","Job seekers without computer skills are at a serious [disadvantage]. (=Dịch: Những người tìm việc không có kỹ năng tin học sẽ gặp bất lợi nghiêm trọng.)","The team overcame their [disadvantage] and won the match. (=Dịch: Đội bóng đã vượt qua thế bất lợi của mình và giành chiến thắng trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=disadvantage&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=disadvantage&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%99d%CB%88v%C3%A6n.t%CC%AC%C9%AAd%CA%92%2F"},{"id":"lv_7_44","topic":"Education and Learning","word":"dissertation","pos":"(n)","ipa":"/ˌdɪs.ɚˈteɪ.ʃən/","defVi":"luận văn, luận án tốt nghiệp","defEn":"a long piece of academic writing based on original research, usually for a university degree","examples":["She is currently writing her doctoral [dissertation] on renewable energy. (=Dịch: Cô ấy hiện đang viết luận án tiến sĩ về năng lượng tái tạo.)","The deadline to submit the master's [dissertation] is next Monday. (=Dịch: Hạn chót nộp luận văn thạc sĩ là vào thứ Hai tới.)","He spent months in the library gathering data for his [dissertation]. (=Dịch: Anh ấy đã dành nhiều tháng trong thư viện để thu thập dữ liệu cho luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=dissertation&lang=en-GB&ipa=%2F%CB%8Cd%C9%AAs.%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=dissertation&lang=en-US&ipa=%2F%CB%8Cd%C9%AAs.%C9%9A%CB%88te%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_45","topic":"Education and Learning","word":"documentary","pos":"(adj)","ipa":"/ˌdɑk.jəˈmɛn.t̬ɚ.i/","defVi":"mang tính tài liệu, có tính chứng thực bằng văn bản","defEn":"consisting of or based on official documents, records, or factual accounts","examples":["The historian provided solid [documentary] evidence to support his theory. (=Dịch: Nhà sử học đã cung cấp bằng chứng tư liệu vững chắc để ủng hộ lý thuyết của mình.)","Researchers gathered [documentary] proof of the property ownership from the city archive. (=Dịch: Các nhà nghiên cứu đã thu thập bằng chứng bằng văn bản về quyền sở hữu tài sản từ kho lưu trữ của thành phố.)","The court examined all the [documentary] records before delivering the final verdict. (=Dịch: Tòa án đã xem xét tất cả các hồ sơ tài liệu trước khi đưa ra phán quyết cuối cùng.)"],"ukAudio":"/ai_services/tts3/?q=documentary&lang=en-GB&ipa=%2F%CB%8Cd%C9%91k.j%C9%99%CB%88m%C9%9Bn.t%CC%AC%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=documentary&lang=en-US&ipa=%2F%CB%8Cd%C9%91k.j%C9%99%CB%88m%C9%9Bn.t%CC%AC%C9%9A.i%2F"},{"id":"lv_7_46","topic":"Education and Learning","word":"drill","pos":"(n)","ipa":"/drɪl/","defVi":"bài luyện tập, cuộc diễn tập","defEn":"an activity that practices a particular skill through frequent repetition, or a safety exercise","examples":["The school conducts a fire [drill] at the beginning of every term. (=Dịch: Trường học tổ chức một cuộc diễn tập phòng cháy chữa cháy vào đầu mỗi học kỳ.)","Grammar [drill]s help beginner students master basic sentence structures. (=Dịch: Các bài luyện ngữ pháp lặp đi lặp lại giúp học viên mới bắt đầu nắm vững các cấu trúc câu cơ bản.)","The military squad went through intensive tactical [drill]s yesterday. (=Dịch: Đội quân sự đã trải qua các cuộc huấn luyện chiến thuật chuyên sâu ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=drill&lang=en-GB&ipa=%2Fdr%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=drill&lang=en-US&ipa=%2Fdr%C9%AAl%2F"},{"id":"lv_7_47","topic":"Education and Learning","word":"edit","pos":"(v)","ipa":"/ˈed.ɪt/","defVi":"chỉnh sửa, biên tập","defEn":"to prepare text or media for publication by correcting errors or making improvements","examples":["You should carefully [edit] your essay before submitting it to the professor. (=Dịch: Bạn nên cẩn thận chỉnh sửa bài luận của mình trước khi nộp cho giáo sư.)","He spent the entire weekend trying to [edit] the video footage. (=Dịch: Anh ấy đã dành cả ngày cuối tuần để cố gắng chỉnh sửa đoạn phim.)","The journalist was asked to [edit] the article to fit the front page. (=Dịch: Nhà báo được yêu cầu biên tập lại bài viết sao cho vừa trang bìa.)"],"ukAudio":"/ai_services/tts3/?q=edit&lang=en-GB&ipa=%2F%CB%88ed.%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=edit&lang=en-US&ipa=%2F%CB%88ed.%C9%AAt%2F"},{"id":"lv_7_48","topic":"Education and Learning","word":"educational","pos":"(adj)","ipa":"/ˌedʒ.əˈkeɪ.ʃən.əl/","defVi":"mang tính giáo dục, thuộc về giáo dục","defEn":"providing useful knowledge or relating to the process of education","examples":["The museum offers many [educational] activities for young children. (=Dịch: Bảo tàng cung cấp nhiều hoạt động mang tính giáo dục cho trẻ nhỏ.)","Watching documentaries can be a deeply [educational] experience. (=Dịch: Xem phim tài liệu có thể là một trải nghiệm mang lại nhiều kiến thức bổ ích.)","The government announced major reforms to the [educational] system. (=Dịch: Chính phủ đã công bố những cải cách lớn đối với hệ thống giáo dục.)"],"ukAudio":"/ai_services/tts3/?q=educational&lang=en-GB&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=educational&lang=en-US&ipa=%2F%CB%8Ced%CA%92.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_7_49","topic":"Education and Learning","word":"eligible","pos":"(adj)","ipa":"/ˈel.ɪ.dʒə.bəl/","defVi":"đủ điều kiện, đủ tư cách","defEn":"having the necessary qualities or satisfying the conditions to do or receive something","examples":["Only full-time students are [eligible] to apply for this scholarship. (=Dịch: Chỉ sinh viên chính quy mới đủ điều kiện nộp đơn xin học bổng này.)","He is [eligible] for retirement benefits after working thirty years at the company. (=Dịch: Ông ấy đủ điều kiện nhận trợ cấp hưu trí sau ba mươi năm làm việc tại công ty.)","Citizens over the age of eighteen are [eligible] to vote in the national election. (=Dịch: Công dân trên mười tám tuổi có đủ tư cách tham gia bỏ phiếu trong cuộc bầu cử quốc gia.)"],"ukAudio":"/ai_services/tts3/?q=eligible&lang=en-GB&ipa=%2F%CB%88el.%C9%AA.d%CA%92%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=eligible&lang=en-US&ipa=%2F%CB%88el.%C9%AA.d%CA%92%C9%99.b%C9%99l%2F"},{"id":"lv_7_50","topic":"Education and Learning","word":"enroll","pos":"(v)","ipa":"/ɪnˈroʊl/","defVi":"ghi danh, đăng ký học","defEn":"to officially register as a member or student in a course or institution","examples":["You need to [enroll] in the course before the end of this week. (=Dịch: Bạn cần phải đăng ký khóa học trước cuối tuần này.)","More than five hundred students [enroll] at the college each year. (=Dịch: Hơn năm trăm sinh viên ghi danh vào trường đại học mỗi năm.)","She decided to [enroll] her son in an online coding class. (=Dịch: Cô ấy quyết định đăng ký cho con trai mình vào một lớp học lập trình trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=enroll&lang=en-GB&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=enroll&lang=en-US&ipa=%2F%C9%AAn%CB%88ro%CA%8Al%2F"},{"id":"lv_7_51","topic":"Education and Learning","word":"enthusiastic","pos":"(adj)","ipa":"/ɪnˌθuː.ziˈæs.tɪk/","defVi":"nhiệt tình, hăng hái","defEn":"feeling or showing a lot of excitement and interest about something","examples":["The students were very [enthusiastic] about the upcoming science fair. (=Dịch: Các học sinh rất hào hứng với hội chợ khoa học sắp tới.)","She received an [enthusiastic] welcome from her colleagues on her first day. (=Dịch: Cô ấy đã nhận được sự chào đón nồng nhiệt từ các đồng nghiệp vào ngày đầu tiên đi làm.)","He is an [enthusiastic] supporter of renewable energy initiatives. (=Dịch: Anh ấy là một người ủng hộ nhiệt tình cho các sáng kiến năng lượng tái tạo.)"],"ukAudio":"/ai_services/tts3/?q=enthusiastic&lang=en-GB&ipa=%2F%C9%AAn%CB%8C%CE%B8u%CB%90.zi%CB%88%C3%A6s.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=enthusiastic&lang=en-US&ipa=%2F%C9%AAn%CB%8C%CE%B8u%CB%90.zi%CB%88%C3%A6s.t%C9%AAk%2F"},{"id":"lv_7_52","topic":"Education and Learning","word":"evaluation","pos":"(n)","ipa":"/ɪˌvæl.juˈeɪ.ʃən/","defVi":"sự đánh giá, thẩm định","defEn":"the process of judging the quality, value, or importance of something","examples":["The teacher conducted a careful [evaluation] of each student's project. (=Dịch: Giáo viên đã tiến hành đánh giá cẩn thận dự án của từng học sinh.)","Employees receive a performance [evaluation] at the end of every year. (=Dịch: Nhân viên nhận được một bản đánh giá hiệu suất làm việc vào cuối mỗi năm.)","The medical trial is still under scientific [evaluation]. (=Dịch: Thử nghiệm y khoa vẫn đang trong quá trình đánh giá khoa học.)"],"ukAudio":"/ai_services/tts3/?q=evaluation&lang=en-GB&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=evaluation&lang=en-US&ipa=%2F%C9%AA%CB%8Cv%C3%A6l.ju%CB%88e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_53","topic":"Education and Learning","word":"excuse","pos":"(n)","ipa":"/ɪkˈskjus/","defVi":"lời bào chữa, cớ, lý do","defEn":"a reason given to explain or justify a fault, mistake, or absence","examples":["He always makes up an [excuse] for arriving late to meetings. (=Dịch: Anh ấy luôn bịa ra một lý do để biện minh cho việc đến họp muộn.)","Tiredness is no [excuse] for being rude to customers. (=Dịch: Sự mệt mỏi không phải là cái cớ để bất lịch sự với khách hàng.)","She needed a valid [excuse] to leave the party early. (=Dịch: Cô ấy cần một lý do chính đáng để rời khỏi bữa tiệc sớm.)"],"ukAudio":"/ai_services/tts3/?q=excuse&lang=en-GB&ipa=%2F%C9%AAk%CB%88skjus%2F","usAudio":"/ai_services/tts3/?q=excuse&lang=en-US&ipa=%2F%C9%AAk%CB%88skjus%2F"},{"id":"lv_7_54","topic":"Education and Learning","word":"extension","pos":"(n)","ipa":"/ɪkˈsten.ʃən/","defVi":"sự gia hạn, phần kéo dài","defEn":"an extra period of time allowed to complete an activity or meet a deadline","examples":["The student requested an [extension] on her assignment due to illness. (=Dịch: Nữ sinh đã xin gia hạn bài tập vì bị ốm.)","The company was granted a two-month [extension] to complete the construction project. (=Dịch: Công ty đã được cấp thêm hai tháng gia hạn để hoàn thành dự án xây dựng.)","If you need to reach him, please dial [extension] 402. (=Dịch: Nếu bạn cần liên hệ với anh ấy, vui lòng bấm số máy lẻ 402.)"],"ukAudio":"/ai_services/tts3/?q=extension&lang=en-GB&ipa=%2F%C9%AAk%CB%88sten.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=extension&lang=en-US&ipa=%2F%C9%AAk%CB%88sten.%CA%83%C9%99n%2F"},{"id":"lv_7_55","topic":"Education and Learning","word":"external","pos":"(adj)","ipa":"/ɪkˈstɝː.nəl/","defVi":"bên ngoài, ngoại lai","defEn":"connected with or located on the outside of something","examples":["The company hired an [external] consultant to review its finances. (=Dịch: Công ty đã thuê một chuyên gia tư vấn bên ngoài để kiểm toán tài chính.)","This medicine is for [external] use only and should not be swallowed. (=Dịch: Thuốc này chỉ dùng ngoài da và không được nuốt.)","The building suffered minor damage to its [external] walls. (=Dịch: Tòa nhà bị hư hại nhẹ ở các bức tường bên ngoài.)"],"ukAudio":"/ai_services/tts3/?q=external&lang=en-GB&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=external&lang=en-US&ipa=%2F%C9%AAk%CB%88st%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_7_56","topic":"Education and Learning","word":"faculty","pos":"(n)","ipa":"/ˈfæk.əl.t̬i/","defVi":"giảng viên toàn trường, khoa (trong trường đại học)","defEn":"the teaching staff of a university or college; a group of departments in a university","examples":["She joined the university [faculty] as a professor of history. (=Dịch: Cô ấy đã gia nhập đội ngũ giảng viên đại học với tư cách là giáo sư lịch sử.)","The meeting was attended by both students and [faculty] members. (=Dịch: Cuộc họp có sự tham dự của cả sinh viên và các thành viên ban giảng huấn.)","He is studying in the [faculty] of law. (=Dịch: Anh ấy đang học tại khoa luật.)"],"ukAudio":"/ai_services/tts3/?q=faculty&lang=en-GB&ipa=%2F%CB%88f%C3%A6k.%C9%99l.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=faculty&lang=en-US&ipa=%2F%CB%88f%C3%A6k.%C9%99l.t%CC%ACi%2F"},{"id":"lv_7_57","topic":"Education and Learning","word":"failure","pos":"(n)","ipa":"/ˈfeɪl.jɚ/","defVi":"sự thất bại, sự hỏng hóc","defEn":"a lack of success in doing something; a situation where something stops working","examples":["Learning from [failure] is an essential part of personal growth. (=Dịch: Học hỏi từ thất bại là một phần thiết yếu của sự trưởng thành cá nhân.)","The sudden power [failure] left the entire city in darkness. (=Dịch: Sự cố mất điện đột ngột đã khiến toàn bộ thành phố chìm trong bóng tối.)","The business ended in financial [failure] after just two years. (=Dịch: Doanh nghiệp đã kết thúc trong thất bại tài chính chỉ sau hai năm.)"],"ukAudio":"/ai_services/tts3/?q=failure&lang=en-GB&ipa=%2F%CB%88fe%C9%AAl.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=failure&lang=en-US&ipa=%2F%CB%88fe%C9%AAl.j%C9%9A%2F"},{"id":"lv_7_58","topic":"Education and Learning","word":"fold","pos":"(v)","ipa":"/foʊld/","defVi":"gấp, gập","defEn":"to bend something over on itself so that one part covers another","examples":["Please [fold] the letter and put it inside the envelope. (=Dịch: Làm ơn hãy gấp lá thư lại và cho vào bên trong phong bì.)","He helped his mother [fold] the clean laundry. (=Dịch: Cậu ấy đã giúp mẹ mình gấp quần áo sạch.)","She showed the children how to [fold] paper into origami birds. (=Dịch: Cô ấy đã hướng dẫn những đứa trẻ cách gấp giấy thành những con chim origami.)"],"ukAudio":"/ai_services/tts3/?q=fold&lang=en-GB&ipa=%2Ffo%CA%8Ald%2F","usAudio":"/ai_services/tts3/?q=fold&lang=en-US&ipa=%2Ffo%CA%8Ald%2F"},{"id":"lv_7_59","topic":"Education and Learning","word":"frustrate","pos":"(v)","ipa":"/ˈfrʌs.treɪt/","defVi":"Làm bực bội, làm nản lòng, cản trở","defEn":"To make someone feel annoyed or upset because they cannot achieve something","examples":["Complex grammar rules often [frustrate] beginner language learners. (=Dịch: Các quy tắc ngữ pháp phức tạp thường làm cho người mới học ngoại ngữ nản lòng.)","Technical delays will [frustrate] users trying to submit their applications online. (=Dịch: Sự chậm trễ kỹ thuật sẽ khiến những người dùng đang cố nộp đơn trực tuyến cảm thấy bực bội.)","Frequent bad weather continues to [frustrate] rescue efforts in the mountains. (=Dịch: Thời tiết xấu kéo dài tiếp tục cản trở những nỗ lực cứu hộ ở vùng núi.)"],"ukAudio":"/ai_services/tts3/?q=frustrate&lang=en-GB&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=frustrate&lang=en-US&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AAt%2F"},{"id":"lv_7_60","topic":"Education and Learning","word":"frustrating","pos":"(adj)","ipa":"/ˈfrʌs.treɪ.tɪŋ/","defVi":"gây ức chế, bực bội, nản lòng","defEn":"making someone feel annoyed, impatient, or discouraged","examples":["It is very [frustrating] when the internet connection keeps dropping during a meeting. (=Dịch: Rất bực mình khi kết nối mạng cứ liên tục bị ngắt trong cuộc họp.)","Waiting in long queues at the airport can be an extremely [frustrating] experience. (=Dịch: Xếp hàng dài chờ đợi ở sân bay có thể là một trải nghiệm vô cùng khó chịu.)","Trying to learn a complex software without guidance is quite [frustrating]. (=Dịch: Cố gắng học một phần mềm phức tạp mà không có hướng dẫn khá là nản lòng.)"],"ukAudio":"/ai_services/tts3/?q=frustrating&lang=en-GB&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AA.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=frustrating&lang=en-US&ipa=%2F%CB%88fr%CA%8Cs.tre%C9%AA.t%C9%AA%C5%8B%2F"},{"id":"lv_7_61","topic":"Education and Learning","word":"genre","pos":"(n)","ipa":"/ˈʒɑːn.rə/","defVi":"thể loại (nghệ thuật, văn học, âm nhạc)","defEn":"a particular style or category of art, music, or literature","examples":["Science fiction is a popular literary [genre] among young readers. (=Dịch: Khoa học viễn tưởng là một thể loại văn học được nhiều độc giả trẻ yêu thích.)","The director is famous for experimenting with different film [genre]s. (=Dịch: Vị đạo diễn này nổi tiếng với việc thử nghiệm các thể loại phim khác nhau.)","Jazz is a distinct musical [genre] that originated in the United States. (=Dịch: Jazz là một thể loại âm nhạc đặc sắc có nguồn gốc từ Hoa Kỳ.)"],"ukAudio":"/ai_services/tts3/?q=genre&lang=en-GB&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F","usAudio":"/ai_services/tts3/?q=genre&lang=en-US&ipa=%2F%CB%88%CA%92%C9%91%CB%90n.r%C9%99%2F"},{"id":"lv_7_62","topic":"Education and Learning","word":"grade","pos":"(n)","ipa":"/ɡreɪd/","defVi":"điểm số, cấp lớp","defEn":"a mark indicating a student's level of achievement in a test or course","examples":["She studied all weekend to get a high [grade] on her math exam. (=Dịch: Cô ấy đã học suốt cuối tuần để đạt điểm cao trong kỳ thi toán.)","Students with the best [grade] averages will receive academic awards. (=Dịch: Những học sinh có điểm trung bình cao nhất sẽ nhận được các giải thưởng học thuật.)","Her parents were delighted with her final report card [grade]. (=Dịch: Bố mẹ cô ấy rất vui mừng với điểm số trong phiếu báo cáo cuối kỳ của cô.)"],"ukAudio":"/ai_services/tts3/?q=grade&lang=en-GB&ipa=%2F%C9%A1re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=grade&lang=en-US&ipa=%2F%C9%A1re%C9%AAd%2F"},{"id":"lv_7_63","topic":"Education and Learning","word":"graduate","pos":"(v)","ipa":"/ˈɡrædʒ.u.eɪt/","defVi":"tốt nghiệp","defEn":"to successfully complete a degree or course of study at a university or school","examples":["She will [graduate] from university with a degree in computer science next year. (=Dịch: Cô ấy sẽ tốt nghiệp đại học với tấm bằng khoa học máy tính vào năm tới.)","Many students hope to find a good job as soon as they [graduate]. (=Dịch: Nhiều sinh viên hy vọng tìm được việc làm tốt ngay sau khi họ tốt nghiệp.)","He worked hard to [graduate] at the top of his high school class. (=Dịch: Anh ấy đã chăm chỉ học tập để tốt nghiệp với vị trí thủ khoa lớp cấp ba.)"],"ukAudio":"/ai_services/tts3/?q=graduate&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.e%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=graduate&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6d%CA%92.u.e%C9%AAt%2F"},{"id":"lv_7_64","topic":"Education and Learning","word":"graph","pos":"(n)","ipa":"/ɡræf/","defVi":"đồ thị, biểu đồ","defEn":"a diagram showing the relationship between two or more sets of numbers or measurements","examples":["The line [graph] illustrates the changes in population over ten years. (=Dịch: Biểu đồ đường minh họa những thay đổi về dân số qua mười năm.)","Please analyze the data presented in this [graph]. (=Dịch: Vui lòng phân tích dữ liệu được trình bày trong biểu đồ này.)","The sales figures are clearly summarized in the [graph] below. (=Dịch: Số liệu bán hàng được tóm tắt rõ ràng trong biểu đồ bên dưới.)"],"ukAudio":"/ai_services/tts3/?q=graph&lang=en-GB&ipa=%2F%C9%A1r%C3%A6f%2F","usAudio":"/ai_services/tts3/?q=graph&lang=en-US&ipa=%2F%C9%A1r%C3%A6f%2F"},{"id":"lv_7_65","topic":"Education and Learning","word":"graphic","pos":"(adj)","ipa":"/ˈɡræf.ɪk/","defVi":"thuộc đồ họa, trực quan; sinh động, rõ ràng","defEn":"connected with drawings, design, or visual images; also describing something in very clear detail","examples":["She works as a [graphic] designer for a major advertising agency. (=Dịch: Cô ấy làm việc với tư cách là một nhà thiết kế đồ họa cho một công ty quảng cáo lớn.)","The documentary provided a [graphic] account of the effects of climate change. (=Dịch: Bộ phim tài liệu đã cung cấp một bản mô tả chi tiết và sống động về những tác động của biến đổi khí hậu.)","The software provides a user-friendly [graphic] interface. (=Dịch: Phần mềm cung cấp một giao diện đồ họa thân thiện với người dùng.)"],"ukAudio":"/ai_services/tts3/?q=graphic&lang=en-GB&ipa=%2F%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=graphic&lang=en-US&ipa=%2F%CB%88%C9%A1r%C3%A6f.%C9%AAk%2F"},{"id":"lv_7_66","topic":"Education and Learning","word":"guidance","pos":"(n)","ipa":"/ˈɡaɪ.dəns/","defVi":"sự hướng dẫn, sự chỉ dẫn","defEn":"help or advice given to someone, especially by someone with more knowledge or experience","examples":["Students often seek career [guidance] from their academic advisors. (=Dịch: Sinh viên thường tìm kiếm sự định hướng nghề nghiệp từ các cố vấn học tập của họ.)","Under the coach's [guidance], the young team improved significantly. (=Dịch: Dưới sự chỉ dẫn của huấn luyện viên, đội bóng trẻ đã tiến bộ rõ rệt.)","The booklet offers useful [guidance] on how to manage personal finances. (=Dịch: Cuốn sổ tay cung cấp những hướng dẫn hữu ích về cách quản lý tài chính cá nhân.)"],"ukAudio":"/ai_services/tts3/?q=guidance&lang=en-GB&ipa=%2F%CB%88%C9%A1a%C9%AA.d%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=guidance&lang=en-US&ipa=%2F%CB%88%C9%A1a%C9%AA.d%C9%99ns%2F"},{"id":"lv_7_67","topic":"Education and Learning","word":"handout","pos":"(n)","ipa":"/ˈhænd.aʊt/","defVi":"tài liệu phát tay, bài giảng in sẵn","defEn":"a document or summary given to people attending a class, lecture, or meeting","examples":["The teacher distributed a useful [handout] containing key vocabulary for the test. (=Dịch: Giáo viên đã phát một tài liệu phát tay hữu ích chứa các từ vựng quan trọng cho bài kiểm tra.)","Please refer to page two of the [handout] for detailed statistics. (=Dịch: Vui lòng tham khảo trang hai của tài liệu phát tay để biết số liệu thống kê chi tiết.)","Instead of relying on a government [handout], he preferred finding a steady job. (=Dịch: Thay vì trông chờ vào tiền trợ cấp cứu trợ của chính phủ, anh ấy thích tìm một công việc ổn định hơn.)"],"ukAudio":"/ai_services/tts3/?q=handout&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F","usAudio":"/ai_services/tts3/?q=handout&lang=en-US&ipa=%2F%CB%88h%C3%A6nd.a%CA%8At%2F"},{"id":"lv_7_68","topic":"Education and Learning","word":"handwriting","pos":"(n)","ipa":"/ˈhændˌraɪ.t̬ɪŋ/","defVi":"chữ viết tay, nét chữ","defEn":"writing done by hand with a pen or pencil, or a person's particular style of writing","examples":["The teacher struggled to read his messy [handwriting] on the test paper. (=Dịch: Giáo viên đã phải rất vất vả mới đọc được chữ viết tay cẩu thả của anh ấy trong bài kiểm tra.)","Practicing calligraphy every day helped improve her English [handwriting]. (=Dịch: Luyện thư pháp mỗi ngày đã giúp cải thiện nét chữ viết tay tiếng Anh của cô ấy.)","The signature on the contract matched the suspect's [handwriting] perfectly. (=Dịch: Chữ ký trên hợp đồng hoàn toàn trùng khớp với nét chữ của kẻ tình nghi.)"],"ukAudio":"/ai_services/tts3/?q=handwriting&lang=en-GB&ipa=%2F%CB%88h%C3%A6nd%CB%8Cra%C9%AA.t%CC%AC%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=handwriting&lang=en-US&ipa=%2F%CB%88h%C3%A6nd%CB%8Cra%C9%AA.t%CC%AC%C9%AA%C5%8B%2F"},{"id":"lv_7_69","topic":"Education and Learning","word":"having","pos":"(v)","ipa":"/ˈhæ.vɪŋ/","defVi":"đang có, sở hữu, trải qua","defEn":"present participle of 'have', meaning possessing, experiencing, or holding something","examples":["They are [having] a great time on their holiday in Italy. (=Dịch: Họ đang có một khoảng thời gian tuyệt vời trong kỳ nghỉ tại Ý.)","She apologized for not [having] enough time to finish the report. (=Dịch: Cô ấy xin lỗi vì không có đủ thời gian để hoàn thành bản báo cáo.)","After [having] breakfast, he went straight to the library. (=Dịch: Sau khi ăn sáng xong, anh ấy đi thẳng đến thư viện.)"],"ukAudio":"/ai_services/tts3/?q=having&lang=en-GB&ipa=%2F%CB%88h%C3%A6.v%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=having&lang=en-US&ipa=%2F%CB%88h%C3%A6.v%C9%AA%C5%8B%2F"},{"id":"lv_7_70","topic":"Education and Learning","word":"heading","pos":"(n)","ipa":"/ˈhed.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a line of text serving to indicate what the passage below is about; a title","examples":["Please write your full name under the main [heading] on the first page. (=Dịch: Vui lòng viết họ tên đầy đủ của bạn dưới phần tiêu đề chính ở trang đầu tiên.)","You can organize your essay clearly by using a sub [heading] for each section. (=Dịch: Bạn có thể sắp xếp bài luận mạch lạc bằng cách sử dụng tiêu đề phụ cho mỗi phần.)","The article was published under the [heading] of climate solutions. (=Dịch: Bài báo được xuất bản dưới tiêu đề về các giải pháp khí hậu.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88hed.%C9%AA%C5%8B%2F"},{"id":"lv_7_71","topic":"Education and Learning","word":"helmet","pos":"(n)","ipa":"/ˈhɛl.mət/","defVi":"mũ bảo hiểm","defEn":"a hard or padded protective hat worn to protect the head","examples":["Cyclists should always wear a [helmet] to protect their heads. (=Dịch: Người đi xe đạp nên luôn đội mũ bảo hiểm để bảo vệ đầu.)","Construction workers are required to put on a hard [helmet] on site. (=Dịch: Công nhân xây dựng bắt buộc phải đội mũ bảo hiểm cứng tại công trường.)","He fastened the strap of his [helmet] before starting the motorbike. (=Dịch: Anh ấy cài quai mũ bảo hiểm trước khi nổ máy xe máy.)"],"ukAudio":"/ai_services/tts3/?q=helmet&lang=en-GB&ipa=%2F%CB%88h%C9%9Bl.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=helmet&lang=en-US&ipa=%2F%CB%88h%C9%9Bl.m%C9%99t%2F"},{"id":"lv_7_72","topic":"Education and Learning","word":"imagination","pos":"(n)","ipa":"/ɪˌmædʒ.əˈneɪ.ʃən/","defVi":"Trí tưởng tượng, khả năng sáng tạo","defEn":"The ability of the mind to form new ideas, images, or concepts","examples":["Creative writing exercises help stimulate children's [imagination]. (=Dịch: Các bài tập viết sáng tạo giúp kích thích trí tưởng tượng của trẻ em.)","It takes a lot of [imagination] to design innovative architectural structures. (=Dịch: Cần rất nhiều trí tưởng tượng để thiết kế ra những công trình kiến trúc đổi mới sáng tạo.)","The strange sounds outside were merely a product of his vivid [imagination]. (=Dịch: Những âm thanh lạ bên ngoài chỉ đơn thuần là sản phẩm từ trí tưởng tượng phong phú của anh ấy.)"],"ukAudio":"/ai_services/tts3/?q=imagination&lang=en-GB&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=imagination&lang=en-US&ipa=%2F%C9%AA%CB%8Cm%C3%A6d%CA%92.%C9%99%CB%88ne%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_73","topic":"Education and Learning","word":"impression","pos":"(n)","ipa":"/ɪmˈprɛʃ.ən/","defVi":"ấn tượng","defEn":"an idea, feeling, or opinion about someone or something formed without conscious thought","examples":["Wearing formal clothes helps you make a positive first [impression] at an interview. (=Dịch: Mặc trang phục lịch sự giúp bạn tạo ấn tượng đầu tiên tốt đẹp tại buổi phỏng vấn.)","His speech left a lasting [impression] on everyone in the audience. (=Dịch: Bài phát biểu của anh ấy đã để lại ấn tượng sâu đậm trong lòng tất cả khán giả.)","I got the [impression] that he was not very interested in the project. (=Dịch: Tôi có cảm giác rằng anh ấy không mấy hào hứng với dự án này.)"],"ukAudio":"/ai_services/tts3/?q=impression&lang=en-GB&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=impression&lang=en-US&ipa=%2F%C9%AAm%CB%88pr%C9%9B%CA%83.%C9%99n%2F"},{"id":"lv_7_74","topic":"Education and Learning","word":"incentive","pos":"(n)","ipa":"/ɪnˈsen.t̬ɪv/","defVi":"sự khích lệ, động lực, phần thưởng khuyến khích","defEn":"something that encourages a person to do something or to work harder","examples":["The company offers a financial [incentive] to employees who reach their sales targets. (=Dịch: Công ty đưa ra khoản thưởng khuyến khích tài chính cho những nhân viên đạt chỉ tiêu bán hàng.)","Tax cuts can provide an [incentive] for businesses to invest in green technology. (=Dịch: Việc giảm thuế có thể tạo động lực cho các doanh nghiệp đầu tư vào công nghệ xanh.)","There is little [incentive] for graduates to stay in rural areas without good jobs. (=Dịch: Có rất ít động lực để sinh viên mới tốt nghiệp ở lại vùng nông thôn nếu không có việc làm tốt.)"],"ukAudio":"/ai_services/tts3/?q=incentive&lang=en-GB&ipa=%2F%C9%AAn%CB%88sen.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=incentive&lang=en-US&ipa=%2F%C9%AAn%CB%88sen.t%CC%AC%C9%AAv%2F"},{"id":"lv_7_75","topic":"Education and Learning","word":"index","pos":"(n)","ipa":"/ˈɪn.deks/","defVi":"mục lục, chỉ số","defEn":"an alphabetical list of names or subjects with references to the places where they occur","examples":["Look up the term in the [index] at the back of the textbook. (=Dịch: Hãy tra cứu thuật ngữ này trong phần mục lục ở cuối sách giáo khoa.)","The consumer price [index] rose sharply over the past quarter. (=Dịch: Chỉ số giá tiêu dùng đã tăng mạnh trong quý vừa qua.)","This card [index] contains records of all library books. (=Dịch: Hộp phiếu mục lục này chứa thông tin lưu trữ của tất cả sách trong thư viện.)"],"ukAudio":"/ai_services/tts3/?q=index&lang=en-GB&ipa=%2F%CB%88%C9%AAn.deks%2F","usAudio":"/ai_services/tts3/?q=index&lang=en-US&ipa=%2F%CB%88%C9%AAn.deks%2F"},{"id":"lv_7_76","topic":"Education and Learning","word":"individually","pos":"(adv)","ipa":"/ˌɪn.dəˈvɪ.dʒu.ə.li/","defVi":"riêng lẻ, từng người một","defEn":"separately, one by one, rather than together","examples":["The teacher spoke to the students [individually] about their progress. (=Dịch: Giáo viên đã nói chuyện riêng với từng học sinh về sự tiến bộ của họ.)","Each gift was wrapped [individually] in colorful paper. (=Dịch: Mỗi món quà đều được gói riêng trong giấy nhiều màu sắc.)","The team members performed well [individually], but struggled to collaborate. (=Dịch: Các thành viên trong nhóm thể hiện tốt khi làm việc độc lập, nhưng lại gặp khó khăn khi phối hợp cùng nhau.)"],"ukAudio":"/ai_services/tts3/?q=individually&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.d%C9%99%CB%88v%C9%AA.d%CA%92u.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=individually&lang=en-US&ipa=%2F%CB%8C%C9%AAn.d%C9%99%CB%88v%C9%AA.d%CA%92u.%C9%99.li%2F"},{"id":"lv_7_77","topic":"Education and Learning","word":"initial","pos":"(adj)","ipa":"/ɪˈnɪʃ.əl/","defVi":"ban đầu, đầu tiên","defEn":"happening at the beginning; first","examples":["My [initial] reaction to the proposal was quite skeptical. (=Dịch: Phản ứng ban đầu của tôi đối với đề xuất là khá hoài nghi.)","The company struggled during the [initial] phase of the project. (=Dịch: Công ty đã gặp nhiều khó khăn trong giai đoạn đầu của dự án.)","They managed to recover their [initial] investment within six months. (=Dịch: Họ đã xoay xở để thu hồi vốn đầu tư ban đầu trong vòng sáu tháng.)"],"ukAudio":"/ai_services/tts3/?q=initial&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=initial&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_7_78","topic":"Education and Learning","word":"initially","pos":"(adv)","ipa":"/ɪˈnɪʃ.ə.li/","defVi":"ban đầu, thoạt đầu","defEn":"at the beginning or at first","examples":["[Initially], the project seemed simple, but it soon became complicated. (=Dịch: Ban đầu, dự án có vẻ đơn giản, nhưng nó sớm trở nên phức tạp.)","He was [initially] reluctant to move to another city for work. (=Dịch: Thoạt đầu, anh ấy ngần ngại chuyển sang thành phố khác để làm việc.)","The company was [initially] founded as a small family business. (=Dịch: Công ty ban đầu được thành lập như một doanh nghiệp gia đình nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=initially&lang=en-GB&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.li%2F","usAudio":"/ai_services/tts3/?q=initially&lang=en-US&ipa=%2F%C9%AA%CB%88n%C9%AA%CA%83.%C9%99.li%2F"},{"id":"lv_7_79","topic":"Education and Learning","word":"install","pos":"(v)","ipa":"/ɪnˈstɑːl/","defVi":"cài đặt, lắp đặt","defEn":"to put a piece of equipment or software in place so that it is ready to use","examples":["The technician arrived early to [install] the new air conditioning unit. (=Dịch: Kỹ thuật viên đã đến sớm để lắp đặt máy điều hòa mới.)","You need to [install] the latest security update on your laptop. (=Dịch: Bạn cần cài đặt bản cập nhật bảo mật mới nhất trên máy tính xách tay của mình.)","The school decided to [install] solar panels to reduce electricity costs. (=Dịch: Nhà trường đã quyết định lắp đặt các tấm pin năng lượng mặt trời để giảm chi phí điện.)"],"ukAudio":"/ai_services/tts3/?q=install&lang=en-GB&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F","usAudio":"/ai_services/tts3/?q=install&lang=en-US&ipa=%2F%C9%AAn%CB%88st%C9%91%CB%90l%2F"},{"id":"lv_7_80","topic":"Education and Learning","word":"intensive","pos":"(adj)","ipa":"/ɪnˈten.sɪv/","defVi":"chuyên sâu, cấp tốc","defEn":"involving a lot of effort, energy, or attention in a short time","examples":["She enrolled in an [intensive] language course before moving abroad. (=Dịch: Cô ấy đã đăng ký một khóa học ngôn ngữ cấp tốc trước khi ra nước ngoài.)","The patient required several weeks of [intensive] care. (=Dịch: Bệnh nhân cần được chăm sóc đặc biệt chuyên sâu trong vài tuần.)","Modern agriculture often relies on [intensive] farming methods. (=Dịch: Nông nghiệp hiện đại thường dựa vào các phương pháp canh tác thâm canh.)"],"ukAudio":"/ai_services/tts3/?q=intensive&lang=en-GB&ipa=%2F%C9%AAn%CB%88ten.s%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=intensive&lang=en-US&ipa=%2F%C9%AAn%CB%88ten.s%C9%AAv%2F"},{"id":"lv_7_81","topic":"Education and Learning","word":"interfere","pos":"(v)","ipa":"/ˌɪn.t̬ɚˈfɪr/","defVi":"Can thiệp, can dự, cản trở.","defEn":"To involve oneself in a matter without right or invitation; to hinder or obstruct.","examples":["Parents should not unduly [interfere] in their adult children's life choices. (=Dịch: Cha mẹ không nên can thiệp quá mức vào những lựa chọn cuộc sống của con cái khi đã trưởng thành.)","Poor weather conditions could [interfere] with the satellite signal. (=Dịch: Điều kiện thời tiết xấu có thể gây cản trở tín hiệu vệ tinh.)","Please do not [interfere] while the technicians are working on the system. (=Dịch: Xin đừng can thiệp trong khi các kỹ thuật viên đang xử lý hệ thống.)"],"ukAudio":"/ai_services/tts3/?q=interfere&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F","usAudio":"/ai_services/tts3/?q=interfere&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%CC%AC%C9%9A%CB%88f%C9%AAr%2F"},{"id":"lv_7_82","topic":"Education and Learning","word":"interruption","pos":"(n)","ipa":"/ˌɪn.təˈrʌp.ʃən/","defVi":"sự gián đoạn, sự ngắt lời","defEn":"an act of stopping something from continuing or someone from speaking","examples":["He worked for three hours without a single [interruption]. (=Dịch: Anh ấy đã làm việc suốt ba tiếng đồng hồ mà không hề bị gián đoạn lần nào.)","Please allow me to finish my presentation without any [interruption]. (=Dịch: Xin hãy để tôi hoàn thành bài thuyết trình mà không ngắt lời.)","The storm caused a temporary [interruption] in the power supply. (=Dịch: Cơn bão đã gây ra sự gián đoạn tạm thời nguồn cung cấp điện.)"],"ukAudio":"/ai_services/tts3/?q=interruption&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88r%CA%8Cp.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=interruption&lang=en-US&ipa=%2F%CB%8C%C9%AAn.t%C9%99%CB%88r%CA%8Cp.%CA%83%C9%99n%2F"},{"id":"lv_7_83","topic":"Education and Learning","word":"jar","pos":"(n)","ipa":"/dʒɑːr/","defVi":"lọ, hũ, bình","defEn":"a cylindrical glass or pottery container with a wide mouth","examples":["She stored homemade strawberry jam in a glass [jar]. (=Dịch: Cô ấy đựng mứt dâu tự làm trong một chiếc lọ thủy tinh.)","He couldn't open the tight lid of the pickle [jar]. (=Dịch: Anh ấy không thể mở được chiếc nắp quá chặt của hũ dưa muối.)","There is a [jar] of freshly picked flowers on the dining table. (=Dịch: Có một bình hoa mới hái trên bàn ăn.)"],"ukAudio":"/ai_services/tts3/?q=jar&lang=en-GB&ipa=%2Fd%CA%92%C9%91%CB%90r%2F","usAudio":"/ai_services/tts3/?q=jar&lang=en-US&ipa=%2Fd%CA%92%C9%91%CB%90r%2F"},{"id":"lv_7_84","topic":"Education and Learning","word":"jet","pos":"(n)","ipa":"/dʒet/","defVi":"máy bay phản lực; tia nước/khí","defEn":"an aircraft powered by jet engines that travels at high speeds","examples":["The business executive travels across the country in a private [jet]. (=Dịch: Vị giám đốc điều hành đi khắp đất nước bằng một chiếc máy bay phản lực riêng.)","A powerful [jet] of water was used to clean the muddy sidewalk. (=Dịch: Một tia nước cực mạnh đã được sử dụng để rửa sạch vỉa hè đầy bùn đất.)","We watched the military [jet] fly across the sky at incredible speed. (=Dịch: Chúng tôi ngắm nhìn chiếc máy bay phản lực quân sự bay qua bầu trời với tốc độ đáng kinh ngạc.)"],"ukAudio":"/ai_services/tts3/?q=jet&lang=en-GB&ipa=%2Fd%CA%92et%2F","usAudio":"/ai_services/tts3/?q=jet&lang=en-US&ipa=%2Fd%CA%92et%2F"},{"id":"lv_7_85","topic":"Education and Learning","word":"journal","pos":"(n)","ipa":"/ˈdʒɝː.nəl/","defVi":"tạp chí chuyên ngành; nhật ký","defEn":"a serious magazine or publication that deals with a particular subject or academic discipline","examples":["His research paper was published in a prestigious medical [journal]. (=Dịch: Bài báo nghiên cứu của anh ấy đã được xuất bản trên một tạp chí y khoa danh tiếng.)","Students are encouraged to read an academic [journal] every week. (=Dịch: Sinh viên được khuyến khích đọc một tạp chí học thuật mỗi tuần.)","She kept a personal [journal] during her travels across Asia. (=Dịch: Cô ấy đã viết nhật ký cá nhân trong suốt chuyến du lịch khắp châu Á.)"],"ukAudio":"/ai_services/tts3/?q=journal&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=journal&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D%CB%90.n%C9%99l%2F"},{"id":"lv_7_86","topic":"Education and Learning","word":"keyboard","pos":"(n)","ipa":"/ˈkiˌbɔrd/","defVi":"bàn phím (máy tính hoặc nhạc cụ)","defEn":"a set of keys on a computer or musical instrument used for typing or playing music","examples":["He spilled his morning coffee all over the computer [keyboard]. (=Dịch: Anh ấy làm đổ cà phê sáng lên khắp bàn phím máy tính.)","Learning to play the electronic [keyboard] requires regular practice. (=Dịch: Học chơi đàn phím điện tử đòi hỏi phải luyện tập thường xuyên.)","She cleaned the dust between the keys of her mechanical [keyboard]. (=Dịch: Cô ấy lau sạch bụi bẩn bám giữa các phím trên chiếc bàn phím cơ của mình.)"],"ukAudio":"/ai_services/tts3/?q=keyboard&lang=en-GB&ipa=%2F%CB%88ki%CB%8Cb%C9%94rd%2F","usAudio":"/ai_services/tts3/?q=keyboard&lang=en-US&ipa=%2F%CB%88ki%CB%8Cb%C9%94rd%2F"},{"id":"lv_7_87","topic":"Education and Learning","word":"lecturer","pos":"(n)","ipa":"/ˈlek.tʃər.ər/","defVi":"giảng viên đại học","defEn":"a person who teaches at a college or university","examples":["The [lecturer] explained the complex theory with great clarity. (=Dịch: Giảng viên đã giải thích lý thuyết phức tạp một cách rất rõ ràng.)","Students can make an appointment to speak with their [lecturer]. (=Dịch: Sinh viên có thể đặt lịch hẹn để trao đổi với giảng viên của mình.)","He worked as a senior [lecturer] in history for over twenty years. (=Dịch: Ông ấy đã làm việc với tư cách là một giảng viên cao cấp môn lịch sử trong hơn hai mươi năm.)"],"ukAudio":"/ai_services/tts3/?q=lecturer&lang=en-GB&ipa=%2F%CB%88lek.t%CA%83%C9%99r.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=lecturer&lang=en-US&ipa=%2F%CB%88lek.t%CA%83%C9%99r.%C9%99r%2F"},{"id":"lv_7_88","topic":"Education and Learning","word":"licence","pos":"(n)","ipa":"/ˈlaɪ.səns/","defVi":"giấy phép, bằng lái","defEn":"an official document that gives legal permission to do, own, or use something","examples":["You must hold a valid driver's [licence] to rent a car here. (=Dịch: Bạn phải có bằng lái xe hợp lệ mới được thuê xe ô tô ở đây.)","The restaurant lost its [licence] after failing the health inspection. (=Dịch: Nhà hàng đã bị tước giấy phép sau khi không vượt qua đợt kiểm tra vệ sinh.)","The company obtained a [licence] to import foreign medical equipment. (=Dịch: Công ty đã xin được giấy phép nhập khẩu thiết bị y tế nước ngoài.)"],"ukAudio":"/ai_services/tts3/?q=licence&lang=en-GB&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=licence&lang=en-US&ipa=%2F%CB%88la%C9%AA.s%C9%99ns%2F"},{"id":"lv_7_89","topic":"Education and Learning","word":"literacy","pos":"(n)","ipa":"/ˈlɪt.ər.ə.si/","defVi":"khả năng biết chữ, trình độ đọc viết","defEn":"the ability to read and write","examples":["The government launched a nationwide campaign to promote adult [literacy]. (=Dịch: Chính phủ đã phát động một chiến dịch toàn quốc nhằm nâng cao tỷ lệ biết chữ ở người lớn.)","Digital [literacy] is becoming an essential skill in modern workplaces. (=Dịch: Kỹ năng sử dụng công nghệ số đang trở thành một kỹ năng thiết yếu tại các nơi làm việc hiện đại.)","Improving financial [literacy] helps young adults manage their money better. (=Dịch: Cải thiện hiểu biết về tài chính giúp những người trẻ quản lý tiền bạc tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=literacy&lang=en-GB&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99.si%2F","usAudio":"/ai_services/tts3/?q=literacy&lang=en-US&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99.si%2F"},{"id":"lv_7_90","topic":"Education and Learning","word":"literate","pos":"(adj)","ipa":"/ˈlɪt.ər.ət/","defVi":"Biết đọc biết viết; có học vấn.","defEn":"Able to read and write.","examples":["The government launched a program to ensure that all citizens become [literate]. (=Dịch: Chính phủ đã phát động một chương trình nhằm đảm bảo tất cả công dân đều biết chữ.)","In today's digital age, it is essential to be computer [literate]. (=Dịch: Trong thời đại số ngày nay, việc có kiến thức tin học cơ bản là vô cùng cần thiết.)","Only a small percentage of the rural population was [literate] a century ago. (=Dịch: Một thế kỷ trước, chỉ có một tỷ lệ nhỏ người dân nông thôn biết đọc biết viết.)"],"ukAudio":"/ai_services/tts3/?q=literate&lang=en-GB&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=literate&lang=en-US&ipa=%2F%CB%88l%C9%AAt.%C9%99r.%C9%99t%2F"},{"id":"lv_7_91","topic":"Education and Learning","word":"literature","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.tʃɚ/","defVi":"văn học, tài liệu chuyên ngành","defEn":"written artistic works such as novels, plays, and poetry, or written material on a specific subject","examples":["She has a deep passion for modern English [literature]. (=Dịch: Cô ấy có một niềm đam mê sâu sắc với văn học Anh hiện đại.)","Students are required to review the existing scientific [literature] before starting the project. (=Dịch: Sinh viên được yêu cầu xem lại các tài liệu khoa học hiện có trước khi bắt đầu dự án.)","Classical [literature] plays an important role in understanding historical cultures. (=Dịch: Văn học cổ điển đóng vai trò quan trọng trong việc thấu hiểu các nền văn hóa lịch sử.)"],"ukAudio":"/ai_services/tts3/?q=literature&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=literature&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.t%CA%83%C9%9A%2F"},{"id":"lv_7_92","topic":"Education and Learning","word":"livestock","pos":"(n)","ipa":"/ˈlaɪv.stɑːk/","defVi":"vật nuôi, gia súc","defEn":"animals kept on a farm, such as cows, sheep, and pigs","examples":["The farmer raises [livestock] to produce organic milk and meat. (=Dịch: Người nông dân nuôi gia súc để sản xuất sữa và thịt hữu cơ.)","Severe droughts pose a great threat to local [livestock]. (=Dịch: Hạn hán nghiêm trọng gây ra mối đe dọa lớn đối với đàn gia súc địa phương.)","They built strong fences to protect their [livestock] from wild predators. (=Dịch: Họ dựng hàng rào kiên cố để bảo vệ đàn vật nuôi khỏi thú ăn thịt hoang dã.)"],"ukAudio":"/ai_services/tts3/?q=livestock&lang=en-GB&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=livestock&lang=en-US&ipa=%2F%CB%88la%C9%AAv.st%C9%91%CB%90k%2F"},{"id":"lv_7_93","topic":"Education and Learning","word":"loan","pos":"(n)","ipa":"/loʊn/","defVi":"khoản vay, tiền vay","defEn":"a sum of money that is borrowed and is expected to be paid back with interest","examples":["They took out a bank [loan] to buy their first apartment. (=Dịch: Họ đã vay một khoản ngân hàng để mua căn hộ đầu tiên.)","The interest rate on his student [loan] increased significantly this year. (=Dịch: Lãi suất cho khoản vay sinh viên của anh ấy đã tăng đáng kể trong năm nay.)","The small business struggled to secure a government [loan] during the crisis. (=Dịch: Doanh nghiệp nhỏ đã phải chật vật để có được một khoản vay của chính phủ trong thời kỳ khủng hoảng.)"],"ukAudio":"/ai_services/tts3/?q=loan&lang=en-GB&ipa=%2Flo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=loan&lang=en-US&ipa=%2Flo%CA%8An%2F"},{"id":"lv_7_94","topic":"Education and Learning","word":"manual","pos":"(adj)","ipa":"/ˈmæn.ju.əl/","defVi":"bằng tay, thủ công","defEn":"done with the hands or requiring physical effort rather than automatic machines","examples":["Many farmers in the region still rely on [manual] labor to harvest crops. (=Dịch: Nhiều nông dân trong vùng vẫn dựa vào lao động chân tay để thu hoạch mùa màng.)","The car has a [manual] gearbox instead of an automatic transmission. (=Dịch: Chiếc xe này có hộp số sàn (thủ công) thay vì hộp số tự động.)","Data entry used to be a [manual] process before software was introduced. (=Dịch: Việc nhập dữ liệu từng là quy trình thủ công trước khi phần mềm được đưa vào sử dụng.)"],"ukAudio":"/ai_services/tts3/?q=manual&lang=en-GB&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=manual&lang=en-US&ipa=%2F%CB%88m%C3%A6n.ju.%C9%99l%2F"},{"id":"lv_7_95","topic":"Education and Learning","word":"marching","pos":"(n)","ipa":"/ˈmɑr.tʃɪŋ/","defVi":"sự diễu hành, việc hành quân","defEn":"the act of walking with regular, steady, and rhythmic steps like soldiers","examples":["The sound of soldiers [marching] could be heard from far away. (=Dịch: Tiếng bước chân hành quân của những người lính có thể nghe thấy từ đằng xa.)","The school band spent weeks practicing their [marching] formation for the parade. (=Dịch: Ban nhạc của trường đã dành nhiều tuần để luyện tập đội hình diễu hành cho buổi lễ.)","Crowds cheered as the performers began [marching] down the main street. (=Dịch: Đám đông reo hò khi các nghệ sĩ biểu diễn bắt đầu diễu hành xuống con phố chính.)"],"ukAudio":"/ai_services/tts3/?q=marching&lang=en-GB&ipa=%2F%CB%88m%C9%91r.t%CA%83%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=marching&lang=en-US&ipa=%2F%CB%88m%C9%91r.t%CA%83%C9%AA%C5%8B%2F"},{"id":"lv_7_96","topic":"Education and Learning","word":"math","pos":"(n)","ipa":"/mæθ/","defVi":"môn toán, toán học","defEn":"the study of numbers, shapes, and patterns; short for mathematics","examples":["She has always excelled in [math] and science subjects. (=Dịch: Cô ấy luôn xuất sắc ở các môn toán và khoa học.)","I need to study hard for my upcoming [math] exam. (=Dịch: Tôi cần phải học tập chăm chỉ cho kỳ thi toán sắp tới.)","Solving complex [math] puzzles helps improve critical thinking skills. (=Dịch: Giải các câu đố toán học phức tạp giúp cải thiện kỹ năng tư duy phản biện.)"],"ukAudio":"/ai_services/tts3/?q=math&lang=en-GB&ipa=%2Fm%C3%A6%CE%B8%2F","usAudio":"/ai_services/tts3/?q=math&lang=en-US&ipa=%2Fm%C3%A6%CE%B8%2F"},{"id":"lv_7_97","topic":"Education and Learning","word":"mature","pos":"(adj)","ipa":"/məˈtʃʊr/","defVi":"trưởng thành, chín chắn","defEn":"behaving in a sensible and responsible way like an adult, or fully grown","examples":["She is very [mature] for her age and handles problems calmly. (=Dịch: Cô ấy rất chín chắn so với lứa tuổi của mình và xử lý các vấn đề một cách bình tĩnh.)","It takes several years for these trees to become fully [mature]. (=Dịch: Phải mất vài năm để những cái cây này phát triển hoàn toàn.)","We need a [mature] discussion about the future of our company. (=Dịch: Chúng ta cần một cuộc thảo luận nghiêm túc và thấu đáo về tương lai của công ty.)"],"ukAudio":"/ai_services/tts3/?q=mature&lang=en-GB&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F","usAudio":"/ai_services/tts3/?q=mature&lang=en-US&ipa=%2Fm%C9%99%CB%88t%CA%83%CA%8Ar%2F"},{"id":"lv_7_98","topic":"Education and Learning","word":"mechanical","pos":"(adj)","ipa":"/məˈkæn.ɪ.kəl/","defVi":"thuộc về cơ khí, máy móc","defEn":"relating to machines or engines, or operated by a machine","examples":["The flight was delayed due to a minor [mechanical] problem. (=Dịch: Chuyến bay đã bị hoãn do một sự cố cơ khí nhỏ.)","He decided to study [mechanical] engineering at university. (=Dịch: Anh ấy quyết định theo học ngành kỹ thuật cơ khí tại trường đại học.)","An antique clock relies on a purely [mechanical] system to keep time. (=Dịch: Một chiếc đồng hồ cổ dựa hoàn toàn vào hệ thống cơ học để chạy đúng giờ.)"],"ukAudio":"/ai_services/tts3/?q=mechanical&lang=en-GB&ipa=%2Fm%C9%99%CB%88k%C3%A6n.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=mechanical&lang=en-US&ipa=%2Fm%C9%99%CB%88k%C3%A6n.%C9%AA.k%C9%99l%2F"},{"id":"lv_7_99","topic":"Education and Learning","word":"medication","pos":"(n)","ipa":"/ˌmɛd.əˈkeɪ.ʃən/","defVi":"thuốc điều trị, dược phẩm","defEn":"a drug or other form of medicine that you take to treat an illness","examples":["The doctor prescribed some [medication] to relieve her back pain. (=Dịch: Bác sĩ đã kê một số loại thuốc để giảm đau lưng cho cô ấy.)","You should avoid driving while taking this allergy [medication]. (=Dịch: Bạn nên tránh lái xe khi đang dùng loại thuốc dị ứng này.)","He has been on regular [medication] for high blood pressure for five years. (=Dịch: Ông ấy đã uống thuốc điều trị huyết áp cao đều đặn trong suốt năm năm qua.)"],"ukAudio":"/ai_services/tts3/?q=medication&lang=en-GB&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=medication&lang=en-US&ipa=%2F%CB%8Cm%C9%9Bd.%C9%99%CB%88ke%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_100","topic":"Education and Learning","word":"modular","pos":"(adj)","ipa":"/ˈmɑː.dʒə.lər/","defVi":"dạng mô-đun, lắp ghép","defEn":"made up of separate parts or units that can be combined in different ways","examples":["The company produces modern [modular] furniture that is easy to assemble. (=Dịch: Công ty sản xuất đồ nội thất dạng mô-đun hiện đại rất dễ lắp ráp.)","The degree program offers a flexible [modular] structure for students. (=Dịch: Chương trình cấp bằng cung cấp cấu trúc học phần linh hoạt cho sinh viên.)","They constructed a [modular] home in just a few weeks. (=Dịch: Họ đã xây dựng một ngôi nhà lắp ghép chỉ trong vài tuần.)"],"ukAudio":"/ai_services/tts3/?q=modular&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.d%CA%92%C9%99.l%C9%99r%2F","usAudio":"/ai_services/tts3/?q=modular&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.d%CA%92%C9%99.l%C9%99r%2F"},{"id":"lv_7_101","topic":"Education and Learning","word":"motor","pos":"(n)","ipa":"/ˈmoʊ.tər/","defVi":"động cơ, mô-tơ","defEn":"a device that converts electrical energy or fuel into mechanical motion","examples":["The electric [motor] in the fan needs to be replaced. (=Dịch: Mô-tơ điện trong chiếc quạt cần phải được thay thế.)","He repaired the boat's [motor] before heading out to sea. (=Dịch: Anh ấy đã sửa động cơ của chiếc thuyền trước khi ra khơi.)","Electric cars use a powerful battery to drive the [motor]. (=Dịch: Xe ô tô điện sử dụng một bộ pin mạnh mẽ để vận hành động cơ.)"],"ukAudio":"/ai_services/tts3/?q=motor&lang=en-GB&ipa=%2F%CB%88mo%CA%8A.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=motor&lang=en-US&ipa=%2F%CB%88mo%CA%8A.t%C9%99r%2F"},{"id":"lv_7_102","topic":"Education and Learning","word":"nanotechnology","pos":"(n)","ipa":"/ˌnæn.oʊ.tekˈnɑː.lə.dʒi/","defVi":"Công nghệ nano.","defEn":"The science and engineering of manipulating materials at the atomic or molecular scale.","examples":["Recent breakthroughs in [nanotechnology] have improved medical diagnostic tools. (=Dịch: Những đột phá gần đây trong công nghệ nano đã cải thiện các công cụ chẩn đoán y tế.)","Scientists believe that [nanotechnology] could revolutionize clean energy production. (=Dịch: Các nhà khoa học tin rằng công nghệ nano có thể cách mạng hóa quá trình sản xuất năng lượng sạch.)","The university offers a specialized master's degree in [nanotechnology]. (=Dịch: Trường đại học cung cấp chương trình thạc sĩ chuyên ngành về công nghệ nano.)"],"ukAudio":"/ai_services/tts3/?q=nanotechnology&lang=en-GB&ipa=%2F%CB%8Cn%C3%A6n.o%CA%8A.tek%CB%88n%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=nanotechnology&lang=en-US&ipa=%2F%CB%8Cn%C3%A6n.o%CA%8A.tek%CB%88n%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_103","topic":"Education and Learning","word":"oral","pos":"(adj)","ipa":"/ˈɔːr.əl/","defVi":"bằng lời nói, bằng miệng, thuộc về răng miệng","defEn":"spoken rather than written, or relating to the mouth","examples":["Students must pass an [oral] examination in French before graduating. (=Dịch: Học sinh phải vượt qua một kỳ thi vấn đáp tiếng Pháp trước khi tốt nghiệp.)","Good [oral] hygiene helps prevent tooth decay and gum disease. (=Dịch: Vệ sinh răng miệng tốt giúp ngăn ngừa sâu răng và bệnh về nướu.)","Ancient stories were passed down through generations by [oral] tradition. (=Dịch: Những câu chuyện cổ xưa đã được truyền qua nhiều thế hệ bằng truyền thống truyền miệng.)"],"ukAudio":"/ai_services/tts3/?q=oral&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=oral&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.%C9%99l%2F"},{"id":"lv_7_104","topic":"Education and Learning","word":"origami","pos":"(n)","ipa":"/ˌɔːr.əˈɡɑː.mi/","defVi":"Nghệ thuật gấp giấy Origami.","defEn":"The traditional Japanese art of paper folding.","examples":["Children can develop patience and dexterity by practicing [origami]. (=Dịch: Trẻ em có thể rèn luyện tính kiên nhẫn và sự khéo léo bằng cách thực hành gấp giấy origami.)","She created a beautiful crane out of square paper using [origami] techniques. (=Dịch: Cô ấy đã gấp một con hạc tuyệt đẹp từ tờ giấy vuông bằng các kỹ thuật origami.)","The art museum is hosting an exhibition dedicated to contemporary [origami]. (=Dịch: Bảo tàng nghệ thuật đang tổ chức một buổi triển lãm dành riêng cho nghệ thuật origami đương đại.)"],"ukAudio":"/ai_services/tts3/?q=origami&lang=en-GB&ipa=%2F%CB%8C%C9%94%CB%90r.%C9%99%CB%88%C9%A1%C9%91%CB%90.mi%2F","usAudio":"/ai_services/tts3/?q=origami&lang=en-US&ipa=%2F%CB%8C%C9%94%CB%90r.%C9%99%CB%88%C9%A1%C9%91%CB%90.mi%2F"},{"id":"lv_7_105","topic":"Education and Learning","word":"overhead","pos":"(adj)","ipa":"/ˈoʊ.vɚ.hɛd/","defVi":"ở trên đầu, trên cao","defEn":"located or operating above your head, in the sky or ceiling","examples":["Please place your carry-on luggage in the [overhead] compartment. (=Dịch: Vui lòng để hành lý xách tay của bạn vào khoang hành lý phía trên đầu.)","Strong winds damaged several [overhead] power cables last night. (=Dịch: Gió mạnh đã làm hư hại một số đường dây điện trên cao vào đêm qua.)","The room was brightly lit by large [overhead] lights. (=Dịch: Căn phòng được chiếu sáng rực rỡ bởi những chiếc đèn trần lớn trên cao.)"],"ukAudio":"/ai_services/tts3/?q=overhead&lang=en-GB&ipa=%2F%CB%88o%CA%8A.v%C9%9A.h%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=overhead&lang=en-US&ipa=%2F%CB%88o%CA%8A.v%C9%9A.h%C9%9Bd%2F"},{"id":"lv_7_106","topic":"Education and Learning","word":"oxford","pos":"(n)","ipa":"/ˈɑːks.fɚd/","defVi":"thành phố Oxford (Anh) hoặc kiểu giày da buộc dây Oxford","defEn":"a famous university city in England, or a type of classic laced leather shoe","examples":["She was accepted into the University of [oxford] to study history. (=Dịch: Cô ấy đã được nhận vào Đại học Oxford để theo học ngành lịch sử.)","He wore a pair of polished black [oxford] shoes to the interview. (=Dịch: Anh ấy đã đi một đôi giày da buộc dây Oxford màu đen sáng bóng đến buổi phỏng vấn.)","Many tourists visit [oxford] to admire its historic architecture. (=Dịch: Nhiều khách du lịch đến thăm Oxford để chiêm ngưỡng kiến trúc lịch sử của thành phố.)"],"ukAudio":"/ai_services/tts3/?q=oxford&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=oxford&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90ks.f%C9%9Ad%2F"},{"id":"lv_7_107","topic":"Education and Learning","word":"paperclip","pos":"(n)","ipa":"/ˈpeɪ.pɚ.klɪp/","defVi":"cái kẹp giấy","defEn":"a small piece of bent wire or plastic used for holding sheets of paper together","examples":["Use a [paperclip] to keep these documents neatly organized. (=Dịch: Hãy sử dụng một cái kẹp giấy để giữ cho những tài liệu này được sắp xếp gọn gàng.)","I searched my desk drawer for a [paperclip] but could not find one. (=Dịch: Tôi đã tìm trong ngăn kéo bàn một chiếc kẹp giấy nhưng không thấy cái nào.)","She attached the receipt to the invoice with a metal [paperclip]. (=Dịch: Cô ấy đã đính kèm biên lai vào hóa đơn bằng một chiếc kẹp giấy kim loại.)"],"ukAudio":"/ai_services/tts3/?q=paperclip&lang=en-GB&ipa=%2F%CB%88pe%C9%AA.p%C9%9A.kl%C9%AAp%2F","usAudio":"/ai_services/tts3/?q=paperclip&lang=en-US&ipa=%2F%CB%88pe%C9%AA.p%C9%9A.kl%C9%AAp%2F"},{"id":"lv_7_108","topic":"Education and Learning","word":"parade","pos":"(n)","ipa":"/pəˈreɪd/","defVi":"cuộc diễu hành, duyệt binh","defEn":"a public procession, especially one celebrating a special day or event","examples":["Thousands of people lined the streets to watch the annual holiday [parade]. (=Dịch: Hàng ngàn người đã đứng dọc các con phố để xem cuộc diễu hành ngày lễ thường niên.)","The marching band practiced every day before the big [parade]. (=Dịch: Đoàn nhạc diễu hành đã tập luyện mỗi ngày trước buổi diễu hành lớn.)","Local military units took part in the victory [parade]. (=Dịch: Các đơn vị quân đội địa phương đã tham gia vào cuộc diễu binh chiến thắng.)"],"ukAudio":"/ai_services/tts3/?q=parade&lang=en-GB&ipa=%2Fp%C9%99%CB%88re%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=parade&lang=en-US&ipa=%2Fp%C9%99%CB%88re%C9%AAd%2F"},{"id":"lv_7_109","topic":"Education and Learning","word":"pause","pos":"(n)","ipa":"/ˈpɔz/","defVi":"sự tạm dừng, khoảng lặng","defEn":"a short period in which something stops before starting again","examples":["There was a brief [pause] in the conversation before she answered the question. (=Dịch: Có một khoảng lặng ngắn trong cuộc trò chuyện trước khi cô ấy trả lời câu hỏi.)","The speaker made a dramatic [pause] to let the message sink in. (=Dịch: Diễn giả đã có một khoảng ngắt giọng đầy kịch tính để thông điệp thực sự thấm thía.)","We took a quick [pause] during the hike to drink some water and rest. (=Dịch: Chúng tôi đã tạm dừng một lúc trong chuyến đi bộ đường dài để uống nước và nghỉ ngơi.)"],"ukAudio":"/ai_services/tts3/?q=pause&lang=en-GB&ipa=%2F%CB%88p%C9%94z%2F","usAudio":"/ai_services/tts3/?q=pause&lang=en-US&ipa=%2F%CB%88p%C9%94z%2F"},{"id":"lv_7_110","topic":"Education and Learning","word":"periodical","pos":"(n)","ipa":"/ˌpɪr.iˈɑ.dɪ.kəl/","defVi":"tạp chí xuất bản định kỳ, ấn phẩm định kỳ","defEn":"a magazine or newspaper published at regular intervals","examples":["The university library subscribes to various academic [periodical] publications. (=Dịch: Thư viện trường đại học đặt mua nhiều ấn phẩm tạp chí học thuật định kỳ khác nhau.)","Researchers often submit their scientific findings to a peer-reviewed [periodical]. (=Dịch: Các nhà nghiên cứu thường gửi các phát hiện khoa học của họ tới một tạp chí định kỳ có bình duyệt.)","She spent the afternoon browsing through an old medical [periodical]. (=Dịch: Cô ấy dành cả buổi chiều để lướt xem một tờ tạp chí y khoa định kỳ cũ.)"],"ukAudio":"/ai_services/tts3/?q=periodical&lang=en-GB&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91.d%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=periodical&lang=en-US&ipa=%2F%CB%8Cp%C9%AAr.i%CB%88%C9%91.d%C9%AA.k%C9%99l%2F"},{"id":"lv_7_111","topic":"Education and Learning","word":"photocopy","pos":"(v)","ipa":"/ˈfoʊ.t̬oʊˌkɑː.pi/","defVi":"Sao chụp, photocopy tài liệu.","defEn":"To make a photographic copy of a document or image.","examples":["Could you please [photocopy] these ten pages for the meeting? (=Dịch: Bạn có thể vui lòng sao chụp mười trang này cho cuộc họp được không?)","The assistant was asked to [photocopy] all the signed contracts. (=Dịch: Người trợ lý được yêu cầu photocopy tất cả các hợp đồng đã ký.)","Students are reminded not to [photocopy] copyrighted textbooks without permission. (=Dịch: Học sinh được nhắc nhở không được sao chụp giáo trình có bản quyền mà không có sự cho phép.)"],"ukAudio":"/ai_services/tts3/?q=photocopy&lang=en-GB&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi%2F","usAudio":"/ai_services/tts3/?q=photocopy&lang=en-US&ipa=%2F%CB%88fo%CA%8A.t%CC%ACo%CA%8A%CB%8Ck%C9%91%CB%90.pi%2F"},{"id":"lv_7_112","topic":"Education and Learning","word":"physically","pos":"(adv)","ipa":"/ˈfɪz.ɪ.kli/","defVi":"về mặt thể chất, theo cách hữu hình","defEn":"in a way that relates to the body rather than the mind","examples":["Athletes must stay [physically] fit through daily training. (=Dịch: Các vận động viên phải duy trì thể lực tốt thông qua việc rèn luyện hàng ngày.)","He felt [physically] exhausted after running the marathon. (=Dịch: Anh ấy cảm thấy kiệt sức về mặt thể xác sau khi chạy xong cự ly marathon.)","The two documents are [physically] stored in different filing cabinets. (=Dịch: Hai tài liệu này được lưu trữ vật lý trong các tủ hồ sơ khác nhau.)"],"ukAudio":"/ai_services/tts3/?q=physically&lang=en-GB&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F","usAudio":"/ai_services/tts3/?q=physically&lang=en-US&ipa=%2F%CB%88f%C9%AAz.%C9%AA.kli%2F"},{"id":"lv_7_113","topic":"Education and Learning","word":"pity","pos":"(n)","ipa":"/ˈpɪt.i/","defVi":"sự tiếc nuối, điều đáng tiếc; lòng thương hại","defEn":"a feeling of sorrow and compassion, or a cause for regret","examples":["It is a great [pity] that you cannot join us for dinner tonight. (=Dịch: Thật là một điều đáng tiếc khi bạn không thể tham gia bữa tối cùng chúng tôi tối nay.)","She looked at the stray dog with deep [pity] and offered it food. (=Dịch: Cô ấy nhìn chú chó hoang với lòng thương cảm sâu sắc và cho nó thức ăn.)","What a [pity] that the outdoor concert was canceled due to rain. (=Dịch: Thật tiếc làm sao khi buổi hòa nhạc ngoài trời bị hủy vì trời mưa.)"],"ukAudio":"/ai_services/tts3/?q=pity&lang=en-GB&ipa=%2F%CB%88p%C9%AAt.i%2F","usAudio":"/ai_services/tts3/?q=pity&lang=en-US&ipa=%2F%CB%88p%C9%AAt.i%2F"},{"id":"lv_7_114","topic":"Education and Learning","word":"playwright","pos":"(n)","ipa":"/ˈpleɪ.raɪt/","defVi":"nhà soạn kịch, nhà viết kịch","defEn":"a person who writes plays for the stage or theater","examples":["William Shakespeare is widely regarded as the greatest English [playwright]. (=Dịch: William Shakespeare được coi rộng rãi là nhà soạn kịch vĩ đại nhất của nước Anh.)","The young [playwright] won an award for her debut theatrical production. (=Dịch: Nữ nhà biên kịch trẻ đã giành được giải thưởng cho tác phẩm sân khấu đầu tay của mình.)","The [playwright] spent months researching historical events for his new drama. (=Dịch: Nhà viết kịch đã dành nhiều tháng nghiên cứu các sự kiện lịch sử cho vở kịch mới của mình.)"],"ukAudio":"/ai_services/tts3/?q=playwright&lang=en-GB&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=playwright&lang=en-US&ipa=%2F%CB%88ple%C9%AA.ra%C9%AAt%2F"},{"id":"lv_7_115","topic":"Education and Learning","word":"politic","pos":"(adj)","ipa":"/ˈpɑ.lə.tɪk/","defVi":"khôn ngoan, thận trọng, sáng suốt","defEn":"sensible, wise, and showing good judgment in a particular situation","examples":["It seemed [politic] to keep quiet and avoid causing an argument. (=Dịch: Giữ im lặng và tránh gây ra tranh cãi có vẻ là điều khôn ngoan.)","She made a [politic] decision to consult her manager before proceeding. (=Dịch: Cô ấy đã đưa ra một quyết định sáng suốt khi tham khảo ý kiến của quản lý trước khi tiếp tục.)","Under such tense circumstances, a [politic] response is essential. (=Dịch: Trong hoàn cảnh căng thẳng như vậy, một phản ứng thận trọng là điều cần thiết.)"],"ukAudio":"/ai_services/tts3/?q=politic&lang=en-GB&ipa=%2F%CB%88p%C9%91.l%C9%99.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=politic&lang=en-US&ipa=%2F%CB%88p%C9%91.l%C9%99.t%C9%AAk%2F"},{"id":"lv_7_116","topic":"Education and Learning","word":"postal","pos":"(adj)","ipa":"/ˈpoʊs.təl/","defVi":"thuộc về bưu điện, bưu chính","defEn":"connected with the post or the system for delivering mail","examples":["You need to enter your correct [postal] code when placing an online order. (=Dịch: Bạn cần nhập đúng mã bưu chính khi đặt hàng trực tuyến.)","The national [postal] service announced an increase in stamp prices. (=Dịch: Dịch vụ bưu chính quốc gia đã thông báo tăng giá tem.)","Citizens were encouraged to cast their votes using the [postal] system. (=Dịch: Người dân được khuyến khích bỏ phiếu thông qua hệ thống bưu điện.)"],"ukAudio":"/ai_services/tts3/?q=postal&lang=en-GB&ipa=%2F%CB%88po%CA%8As.t%C9%99l%2F","usAudio":"/ai_services/tts3/?q=postal&lang=en-US&ipa=%2F%CB%88po%CA%8As.t%C9%99l%2F"},{"id":"lv_7_117","topic":"Education and Learning","word":"postgraduate","pos":"(n)","ipa":"/ˌpoʊstˈɡrædʒ.u.ət/","defVi":"nghiên cứu sinh, học viên cao học","defEn":"a student who has completed a bachelor's degree and is studying for a higher qualification","examples":["Many [postgraduate] students work as teaching assistants at the university. (=Dịch: Nhiều học viên sau đại học làm trợ giảng tại trường đại học.)","The scholarship is exclusively available to full-time [postgraduate] researchers. (=Dịch: Học bổng này chỉ dành riêng cho các nhà nghiên cứu sau đại học toàn thời gian.)","As a [postgraduate], she spent most of her time conducting laboratory experiments. (=Dịch: Là một học viên cao học, cô ấy dành phần lớn thời gian để tiến hành các thí nghiệm trong phòng thí nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=postgraduate&lang=en-GB&ipa=%2F%CB%8Cpo%CA%8Ast%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=postgraduate&lang=en-US&ipa=%2F%CB%8Cpo%CA%8Ast%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F"},{"id":"lv_7_118","topic":"Education and Learning","word":"preparation","pos":"(n)","ipa":"/ˌprɛ.pəˈreɪ.ʃən/","defVi":"sự chuẩn bị","defEn":"the act or process of getting ready for something","examples":["Careful [preparation] is the key to passing the IELTS exam. (=Dịch: Sự chuẩn bị kỹ lưỡng là chìa khóa để vượt qua kỳ thi IELTS.)","The team spent months in [preparation] for the international tournament. (=Dịch: Cả đội đã dành nhiều tháng chuẩn bị cho giải đấu quốc tế.)","Food [preparation] should follow strict hygiene guidelines. (=Dịch: Việc chuẩn bị thức ăn nên tuân thủ các nguyên tắc vệ sinh nghiêm ngặt.)"],"ukAudio":"/ai_services/tts3/?q=preparation&lang=en-GB&ipa=%2F%CB%8Cpr%C9%9B.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=preparation&lang=en-US&ipa=%2F%CB%8Cpr%C9%9B.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_119","topic":"Education and Learning","word":"prince","pos":"(n)","ipa":"/prɪns/","defVi":"hoàng tử","defEn":"a son or male relative of a king or queen","examples":["The young [prince] was educated at the best universities in the country. (=Dịch: Vị hoàng tử trẻ đã được học tập tại những trường đại học danh tiếng nhất cả nước.)","In the fairy tale, a charming [prince] saves the kingdom from danger. (=Dịch: Trong câu chuyện cổ tích, một hoàng tử hào hoa đã cứu vương quốc thoát khỏi hiểm nguy.)","The [prince] will represent the royal family at the upcoming international summit. (=Dịch: Hoàng tử sẽ đại diện cho hoàng gia tại hội nghị thượng đỉnh quốc tế sắp tới.)"],"ukAudio":"/ai_services/tts3/?q=prince&lang=en-GB&ipa=%2Fpr%C9%AAns%2F","usAudio":"/ai_services/tts3/?q=prince&lang=en-US&ipa=%2Fpr%C9%AAns%2F"},{"id":"lv_7_120","topic":"Education and Learning","word":"principle","pos":"(n)","ipa":"/ˈprɪn.sə.pəl/","defVi":"nguyên tắc, nguyên lý","defEn":"a basic truth, rule, or belief that guides behavior and decision-making","examples":["He refused to accept the bribe because it went against his personal [principle]s. (=Dịch: Anh ấy từ chối nhận hối lộ vì điều đó đi ngược lại với các nguyên tắc cá nhân của mình.)","The machine operates on the [principle] of electromagnetic induction. (=Dịch: Cỗ máy này hoạt động dựa trên nguyên lý cảm ứng điện từ.)","Adhering to the [principle] of fairness is essential for any legal system. (=Dịch: Tuân thủ nguyên tắc công bằng là điều cốt yếu đối với bất kỳ hệ thống pháp luật nào.)"],"ukAudio":"/ai_services/tts3/?q=principle&lang=en-GB&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=principle&lang=en-US&ipa=%2F%CB%88pr%C9%AAn.s%C9%99.p%C9%99l%2F"},{"id":"lv_7_121","topic":"Education and Learning","word":"projector","pos":"(n)","ipa":"/prəˈdʒek.tər/","defVi":"máy chiếu","defEn":"a device that projects images, videos, or slides onto a screen or wall","examples":["The teacher turned on the [projector] to show the slides. (=Dịch: Giáo viên đã bật máy chiếu để trình chiếu các trang bài giảng.)","We bought a mini [projector] to watch movies in our bedroom. (=Dịch: Chúng tôi đã mua một chiếc máy chiếu mini để xem phim trong phòng ngủ.)","The meeting was delayed because the [projector] broke down. (=Dịch: Cuộc họp bị hoãn lại vì máy chiếu bị hỏng.)"],"ukAudio":"/ai_services/tts3/?q=projector&lang=en-GB&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=projector&lang=en-US&ipa=%2Fpr%C9%99%CB%88d%CA%92ek.t%C9%99r%2F"},{"id":"lv_7_122","topic":"Education and Learning","word":"proud","pos":"(adj)","ipa":"/praʊd/","defVi":"tự hào, hãnh diện","defEn":"feeling deep pleasure or satisfaction as a result of one's own achievements or qualities, or those of someone with whom one is associated","examples":["Her parents were extremely [proud] when she graduated with honors. (=Dịch: Bố mẹ cô ấy đã vô cùng tự hào khi cô tốt nghiệp loại xuất sắc.)","He felt [proud] of his team after they won the championship match. (=Dịch: Anh ấy cảm thấy tự hào về đội của mình sau khi họ giành chiến thắng trong trận chung kết.)","She is too [proud] to ask for financial help from others. (=Dịch: Cô ấy quá kiêu hãnh để đi nhờ cậy sự giúp đỡ tài chính từ người khác.)"],"ukAudio":"/ai_services/tts3/?q=proud&lang=en-GB&ipa=%2Fpra%CA%8Ad%2F","usAudio":"/ai_services/tts3/?q=proud&lang=en-US&ipa=%2Fpra%CA%8Ad%2F"},{"id":"lv_7_123","topic":"Education and Learning","word":"qualified","pos":"(adj)","ipa":"/ˈkwɑː.lə.faɪd/","defVi":"Đủ điều kiện, có đủ trình độ chuyên môn.","defEn":"Having the necessary knowledge, skill, or qualifications to do a particular job.","examples":["She is fully [qualified] to teach English at the university level. (=Dịch: Cô ấy có đầy đủ trình độ chuyên môn để giảng dạy tiếng Anh ở bậc đại học.)","The company struggles to find [qualified] engineers with practical experience. (=Dịch: Công ty đang gặp khó khăn trong việc tìm kiếm các kỹ sư có chuyên môn và kinh nghiệm thực tế.)","Only [qualified] applicants will be invited for an in-person interview. (=Dịch: Chỉ những ứng viên đủ tiêu chuẩn mới được mời đến phỏng vấn trực tiếp.)"],"ukAudio":"/ai_services/tts3/?q=qualified&lang=en-GB&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=qualified&lang=en-US&ipa=%2F%CB%88kw%C9%91%CB%90.l%C9%99.fa%C9%AAd%2F"},{"id":"lv_7_124","topic":"Education and Learning","word":"queue","pos":"(v)","ipa":"/kjuː/","defVi":"xếp hàng","defEn":"to stand in a line waiting for something","examples":["Hundreds of fans had to [queue] for hours to buy concert tickets. (=Dịch: Hàng trăm người hâm mộ đã phải xếp hàng nhiều giờ để mua vé xem ca nhạc.)","Passengers should [queue] patiently at the boarding gate. (=Dịch: Hành khách nên kiên nhẫn xếp hàng tại cổng lên máy bay.)","We had to [queue] up outside the popular restaurant before getting a table. (=Dịch: Chúng tôi đã phải xếp hàng bên ngoài nhà hàng nổi tiếng trước khi có bàn.)"],"ukAudio":"/ai_services/tts3/?q=queue&lang=en-GB&ipa=%2Fkju%CB%90%2F","usAudio":"/ai_services/tts3/?q=queue&lang=en-US&ipa=%2Fkju%CB%90%2F"},{"id":"lv_7_125","topic":"Education and Learning","word":"recall","pos":"(v)","ipa":"/rɪˈkɔl/","defVi":"Gợi nhớ lại, nhớ lại","defEn":"To remember something or bring a fact or situation back into one's mind","examples":["I can clearly [recall] the first day I entered university. (=Dịch: Tôi có thể nhớ rất rõ ngày đầu tiên mình bước chân vào trường đại học.)","She struggled to [recall] the name of the author during the exam. (=Dịch: Cô ấy đã rất chật vật để nhớ lại tên của tác giả trong suốt kỳ thi.)","The witness could not [recall] the exact time of the accident. (=Dịch: Nhân chứng không thể nhớ lại thời điểm chính xác của vụ tai nạn.)"],"ukAudio":"/ai_services/tts3/?q=recall&lang=en-GB&ipa=%2Fr%C9%AA%CB%88k%C9%94l%2F","usAudio":"/ai_services/tts3/?q=recall&lang=en-US&ipa=%2Fr%C9%AA%CB%88k%C9%94l%2F"},{"id":"lv_7_126","topic":"Education and Learning","word":"refectory","pos":"(n)","ipa":"/rɪˈfɛk.tə.ri/","defVi":"phòng ăn tập thể, nhà ăn (trong trường học, tu viện)","defEn":"a large room used for communal meals in a school, college, or monastery","examples":["Students usually gather in the university [refectory] at lunchtime. (=Dịch: Sinh viên thường tụ tập ở nhà ăn của trường đại học vào giờ ăn trưa.)","The campus [refectory] offers a variety of affordable hot meals. (=Dịch: Nhà ăn của trường cung cấp nhiều bữa ăn nóng sốt với giá cả phải chăng.)","Renovations were made to expand the seating capacity of the old [refectory]. (=Dịch: Việc cải tạo đã được tiến hành để mở rộng sức chứa chỗ ngồi của nhà ăn cũ.)"],"ukAudio":"/ai_services/tts3/?q=refectory&lang=en-GB&ipa=%2Fr%C9%AA%CB%88f%C9%9Bk.t%C9%99.ri%2F","usAudio":"/ai_services/tts3/?q=refectory&lang=en-US&ipa=%2Fr%C9%AA%CB%88f%C9%9Bk.t%C9%99.ri%2F"},{"id":"lv_7_127","topic":"Education and Learning","word":"register","pos":"(n)","ipa":"/ˈredʒ.ə.stɚ/","defVi":"Sổ sách, danh sách chính thức, sổ điểm danh.","defEn":"An official list, record book, or database containing names or details.","examples":["The teacher called the names from the attendance [register] at the start of the lesson. (=Dịch: Giáo viên đã gọi tên theo sổ điểm danh vào đầu tiết học.)","The government keeps an official [register] of all licensed businesses. (=Dịch: Chính phủ lưu giữ một danh bạ chính thức về tất cả các doanh nghiệp được cấp phép.)","Guests are required to sign the hotel [register] upon arrival. (=Dịch: Khách lưu trú được yêu cầu ký vào sổ đăng ký của khách sạn khi đến nơi.)"],"ukAudio":"/ai_services/tts3/?q=register&lang=en-GB&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F","usAudio":"/ai_services/tts3/?q=register&lang=en-US&ipa=%2F%CB%88red%CA%92.%C9%99.st%C9%9A%2F"},{"id":"lv_7_128","topic":"Education and Learning","word":"registration","pos":"(n)","ipa":"/ˌredʒ.əˈstreɪ.ʃən/","defVi":"sự đăng ký, việc vào sổ","defEn":"the act of recording a name or details on an official list","examples":["Course [registration] opens online early on Monday morning. (=Dịch: Cổng đăng ký khóa học sẽ mở trực tuyến vào sáng sớm thứ Hai.)","Please show your ID card at the reception desk to complete your conference [registration]. (=Dịch: Vui lòng xuất trình thẻ căn cước tại bàn tiếp tân để hoàn tất việc đăng ký tham dự hội nghị.)","The fee for vehicle [registration] varies depending on the engine size. (=Dịch: Phí đăng ký xe thay đổi tùy thuộc vào dung tích xi-lanh.)"],"ukAudio":"/ai_services/tts3/?q=registration&lang=en-GB&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=registration&lang=en-US&ipa=%2F%CB%8Cred%CA%92.%C9%99%CB%88stre%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_7_129","topic":"Education and Learning","word":"rehearsal","pos":"(n)","ipa":"/rɪˈhɜːr.səl/","defVi":"buổi diễn tập, sự luyện tập","defEn":"a practice session for a play, concert, or other performance","examples":["The actors had their final [rehearsal] before opening night. (=Dịch: Các diễn viên đã có buổi tổng duyệt cuối cùng trước đêm công diễn.)","She missed the choir [rehearsal] because of a sudden illness. (=Dịch: Cô ấy đã bỏ lỡ buổi tập của dàn hợp xướng vì bị ốm đột ngột.)","We need more [rehearsal] time to perfect our dance routine. (=Dịch: Chúng tôi cần thêm thời gian tập luyện để hoàn thiện bài nhảy. phẩm.)"],"ukAudio":"/ai_services/tts3/?q=rehearsal&lang=en-GB&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90r.s%C9%99l%2F","usAudio":"/ai_services/tts3/?q=rehearsal&lang=en-US&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90r.s%C9%99l%2F"},{"id":"lv_7_130","topic":"Education and Learning","word":"rehearse","pos":"(v)","ipa":"/rɪˈhɜːrs/","defVi":"diễn tập, tập dượt, tổng duyệt","defEn":"to practice a play, piece of music, or speech in preparation for a public performance","examples":["The actors need to [rehearse] their lines several times before opening night. (=Dịch: Các diễn viên cần phải tập dượt lời thoại của mình nhiều lần trước đêm công diễn.)","The orchestra gathered early in the morning to [rehearse] the symphony. (=Dịch: Dàn nhạc đã tập hợp từ sáng sớm để diễn tập bản giao hưởng.)","She spent hours standing in front of the mirror to [rehearse] her presentation. (=Dịch: Cô ấy đã dành hàng giờ đứng trước gương để tập dượt bài thuyết trình của mình.)"],"ukAudio":"/ai_services/tts3/?q=rehearse&lang=en-GB&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90rs%2F","usAudio":"/ai_services/tts3/?q=rehearse&lang=en-US&ipa=%2Fr%C9%AA%CB%88h%C9%9C%CB%90rs%2F"},{"id":"lv_7_131","topic":"Education and Learning","word":"relief","pos":"(n)","ipa":"/rɪˈliːf/","defVi":"sự nhẹ nhõm, sự khuây khỏa","defEn":"a feeling of happiness that something unpleasant has stopped or not happened","examples":["It was a huge [relief] to hear that everyone survived the accident. (=Dịch: Thật là một sự nhẹ nhõm lớn khi biết rằng tất cả mọi người đều sống sót sau vụ tai nạn.)","She breathed a sigh of [relief] when the exam was finally over. (=Dịch: Cô ấy thở phào nhẹ nhõm khi kỳ thi cuối cùng cũng kết thúc.)","The organization provided disaster [relief] to the flood victims. (=Dịch: Tổ chức này đã cung cấp viện trợ cứu trợ thiên tai cho các nạn nhân lũ lụt.)"],"ukAudio":"/ai_services/tts3/?q=relief&lang=en-GB&ipa=%2Fr%C9%AA%CB%88li%CB%90f%2F","usAudio":"/ai_services/tts3/?q=relief&lang=en-US&ipa=%2Fr%C9%AA%CB%88li%CB%90f%2F"},{"id":"lv_7_132","topic":"Education and Learning","word":"remind","pos":"(v)","ipa":"/rɪˈmaɪnd/","defVi":"nhắc nhở, gợi nhớ","defEn":"to help someone remember something or cause someone to think of something","examples":["Please [remind] me to call the doctor tomorrow morning. (=Dịch: Làm ơn nhắc tôi gọi điện cho bác sĩ vào sáng mai nhé.)","This song always [remind]s me of my university years. (=Dịch: Bài hát này luôn gợi nhớ cho tôi về những năm tháng đại học.)","The teacher had to [remind] the students about the deadline for the project. (=Dịch: Giáo viên đã phải nhắc nhở học sinh về hạn chót của dự án.)"],"ukAudio":"/ai_services/tts3/?q=remind&lang=en-GB&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F","usAudio":"/ai_services/tts3/?q=remind&lang=en-US&ipa=%2Fr%C9%AA%CB%88ma%C9%AAnd%2F"},{"id":"lv_7_133","topic":"Education and Learning","word":"renew","pos":"(v)","ipa":"/rɪˈnu/","defVi":"gia hạn, làm mới lại","defEn":"to extend the period of validity of something, or make something new and fresh again","examples":["I need to go to the library to [renew] my borrowed books. (=Dịch: Tôi cần đến thư viện để gia hạn những cuốn sách đã mượn.)","He decided to [renew] his passport before traveling abroad. (=Dịch: Anh ấy quyết định làm mới hộ chiếu trước khi đi du lịch nước ngoài.)","The spring rain helped to [renew] the dry grass in the garden. (=Dịch: Cơn mưa mùa xuân đã giúp hồi sinh bãi cỏ khô cằn trong vườn.)"],"ukAudio":"/ai_services/tts3/?q=renew&lang=en-GB&ipa=%2Fr%C9%AA%CB%88nu%2F","usAudio":"/ai_services/tts3/?q=renew&lang=en-US&ipa=%2Fr%C9%AA%CB%88nu%2F"},{"id":"lv_7_134","topic":"Education and Learning","word":"restrict","pos":"(v)","ipa":"/rɪˈstrɪkt/","defVi":"hạn chế, giới hạn","defEn":"to put a limit on someone or something; to keep within bounds","examples":["The doctor advised him to [restrict] his daily sugar intake. (=Dịch: Bác sĩ khuyên anh ấy nên hạn chế lượng đường nạp vào cơ thể mỗi ngày.)","New traffic laws aim to [restrict] heavy trucks from entering the city center. (=Dịch: Luật giao thông mới nhằm hạn chế xe tải nặng đi vào trung tâm thành phố.)","Budget constraints will severely [restrict] the scope of our research project. (=Dịch: Những hạn chế về ngân sách sẽ giới hạn đáng kể phạm vi dự án nghiên cứu của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=restrict&lang=en-GB&ipa=%2Fr%C9%AA%CB%88str%C9%AAkt%2F","usAudio":"/ai_services/tts3/?q=restrict&lang=en-US&ipa=%2Fr%C9%AA%CB%88str%C9%AAkt%2F"},{"id":"lv_7_135","topic":"Education and Learning","word":"revise","pos":"(v)","ipa":"/rɪˈvaɪz/","defVi":"sửa đổi, xem lại, ôn tập","defEn":"to re-examine and make changes to a text or plan; to review material previously learned","examples":["The author had to [revise] several chapters before the book could be published. (=Dịch: Tác giả đã phải sửa đổi vài chương trước khi cuốn sách có thể được xuất bản.)","Students should [revise] their lecture notes every evening. (=Dịch: Sinh viên nên ôn tập lại các ghi chép bài giảng vào mỗi buổi tối.)","The committee decided to [revise] the company policies regarding remote work. (=Dịch: Ủy ban đã quyết định sửa đổi các chính sách của công ty liên quan đến làm việc từ xa.)"],"ukAudio":"/ai_services/tts3/?q=revise&lang=en-GB&ipa=%2Fr%C9%AA%CB%88va%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=revise&lang=en-US&ipa=%2Fr%C9%AA%CB%88va%C9%AAz%2F"},{"id":"lv_7_136","topic":"Education and Learning","word":"revision","pos":"(n)","ipa":"/rɪˈvɪʒ.ən/","defVi":"sự ôn tập, sự xem lại hoặc chỉnh sửa","defEn":"the process of changing, improving, or reviewing something such as a text or study material","examples":["He spent the whole weekend doing [revision] for his final exams. (=Dịch: Anh ấy đã dành cả ngày cuối tuần để ôn tập cho các bài thi cuối kỳ.)","The author made several major [revision]s to the second edition of the book. (=Dịch: Tác giả đã thực hiện vài chỉnh sửa lớn cho lần xuất bản thứ hai của cuốn sách.)","Careful [revision] of your essay can help you avoid simple grammatical mistakes. (=Dịch: Việc đọc và sửa lại bài luận cẩn thận có thể giúp bạn tránh các lỗi ngữ pháp đơn giản.)"],"ukAudio":"/ai_services/tts3/?q=revision&lang=en-GB&ipa=%2Fr%C9%AA%CB%88v%C9%AA%CA%92.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=revision&lang=en-US&ipa=%2Fr%C9%AA%CB%88v%C9%AA%CA%92.%C9%99n%2F"},{"id":"lv_7_137","topic":"Education and Learning","word":"rhythm","pos":"(n)","ipa":"/ˈrɪð.əm/","defVi":"nhịp điệu, tiết tấu","defEn":"a regular repeated pattern of sounds, movements, or events","examples":["The dancers moved gracefully to the steady [rhythm] of the drums. (=Dịch: Các vũ công di chuyển uyển chuyển theo nhịp điệu đều đặn của tiếng trống.)","It took him a few weeks to get used to the fast [rhythm] of city life. (=Dịch: Anh ấy mất vài tuần để làm quen với nhịp sống hối hả của thành thị.)","Regular exercise can help restore the natural [rhythm] of your sleep cycle. (=Dịch: Tập thể dục đều đặn có thể giúp khôi phục nhịp sinh học tự nhiên của chu kỳ giấc ngủ.)"],"ukAudio":"/ai_services/tts3/?q=rhythm&lang=en-GB&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=rhythm&lang=en-US&ipa=%2F%CB%88r%C9%AA%C3%B0.%C9%99m%2F"},{"id":"lv_7_138","topic":"Education and Learning","word":"rubber","pos":"(n)","ipa":"/ˈrʌb.ɚ/","defVi":"cao su; cục tẩy","defEn":"a strong, elastic material made from the juice of a tropical plant or chemicals; also an eraser","examples":["The soles of these running shoes are made of durable [rubber]. (=Dịch: Đế của đôi giày chạy này được làm bằng cao su bền chắc.)","Can I borrow your [rubber] to fix a mistake in my drawing? (=Dịch: Tôi có thể mượn cục tẩy của bạn để sửa lỗi vẽ này không?)","The country is one of the world's leading exporters of natural [rubber]. (=Dịch: Quốc gia này là một trong những nước xuất khẩu cao su tự nhiên hàng đầu thế giới.)"],"ukAudio":"/ai_services/tts3/?q=rubber&lang=en-GB&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=rubber&lang=en-US&ipa=%2F%CB%88r%CA%8Cb.%C9%9A%2F"},{"id":"lv_7_139","topic":"Education and Learning","word":"sandy","pos":"(adj)","ipa":"/ˈsæn.di/","defVi":"nhiều cát, có tính cát","defEn":"covered with or containing a large amount of sand","examples":["We enjoyed walking barefoot along the warm, [sandy] beach. (=Dịch: Chúng tôi thích đi chân trần dọc theo bãi biển đầy cát ấm áp.)","Certain desert plants grow exceptionally well in dry, [sandy] soil. (=Dịch: Một số loài thực vật sa mạc phát triển đặc biệt tốt trong đất cát khô cằn.)","The children built giant castles on the [sandy] shore. (=Dịch: Những đứa trẻ đã xây những lâu đài khổng lồ trên bờ cát.)"],"ukAudio":"/ai_services/tts3/?q=sandy&lang=en-GB&ipa=%2F%CB%88s%C3%A6n.di%2F","usAudio":"/ai_services/tts3/?q=sandy&lang=en-US&ipa=%2F%CB%88s%C3%A6n.di%2F"},{"id":"lv_7_140","topic":"Education and Learning","word":"scandinavian","pos":"(adj)","ipa":"/ˌskæn.dəˈneɪ.vi.ən/","defVi":"thuộc về vùng Scandinavia (Bắc Âu)","defEn":"relating to Scandinavia, its people, languages, or culture","examples":["Many homeowners admire [scandinavian] interior design for its simplicity and light. (=Dịch: Nhiều chủ nhà yêu thích phong cách thiết kế nội thất Scandinavia vì sự tối giản và tràn ngập ánh sáng.)","The study compared social welfare policies across several [scandinavian] countries. (=Dịch: Nghiên cứu đã so sánh các chính sách phúc lợi xã hội giữa một số quốc gia vùng Bắc Âu.)","She is deeply interested in [scandinavian] mythology and folklore. (=Dịch: Cô ấy rất quan tâm đến thần thoại và văn hóa dân gian Scandinavia.)"],"ukAudio":"/ai_services/tts3/?q=scandinavian&lang=en-GB&ipa=%2F%CB%8Csk%C3%A6n.d%C9%99%CB%88ne%C9%AA.vi.%C9%99n%2F","usAudio":"/ai_services/tts3/?q=scandinavian&lang=en-US&ipa=%2F%CB%8Csk%C3%A6n.d%C9%99%CB%88ne%C9%AA.vi.%C9%99n%2F"},{"id":"lv_7_141","topic":"Education and Learning","word":"secondary","pos":"(adj)","ipa":"/ˈsek.ənˌder.i/","defVi":"thứ yếu, phụ; thuộc bậc trung học","defEn":"coming after what is primary or most important; relating to education for children aged roughly 11 to 18","examples":["Cost is a [secondary] consideration compared to safety. (=Dịch: Chi phí chỉ là yếu tố phụ so với sự an toàn.)","She is currently teaching at a local [secondary] school. (=Dịch: Cô ấy hiện đang giảng dạy tại một trường trung học cơ sở địa phương.)","The doctor treated the primary disease before addressing the [secondary] symptoms. (=Dịch: Bác sĩ đã điều trị căn bệnh chính trước khi giải quyết các triệu chứng thứ cấp.)"],"ukAudio":"/ai_services/tts3/?q=secondary&lang=en-GB&ipa=%2F%CB%88sek.%C9%99n%CB%8Cder.i%2F","usAudio":"/ai_services/tts3/?q=secondary&lang=en-US&ipa=%2F%CB%88sek.%C9%99n%CB%8Cder.i%2F"},{"id":"lv_7_142","topic":"Education and Learning","word":"seek","pos":"(v)","ipa":"/sik/","defVi":"tìm kiếm, mưu cầu","defEn":"to look for something or try to obtain it","examples":["Graduates often [seek] advice from career counselors. (=Dịch: Sinh viên mới tốt nghiệp thường tìm kiếm lời khuyên từ các chuyên viên tư vấn nghề nghiệp.)","The company is actively trying to [seek] new investment opportunities. (=Dịch: Công ty đang tích cực tìm kiếm các cơ hội đầu tư mới.)","You should [seek] medical attention if the symptoms persist. (=Dịch: Bạn nên tìm kiếm sự chăm sóc y tế nếu các triệu chứng vẫn kéo dài.)"],"ukAudio":"/ai_services/tts3/?q=seek&lang=en-GB&ipa=%2Fsik%2F","usAudio":"/ai_services/tts3/?q=seek&lang=en-US&ipa=%2Fsik%2F"},{"id":"lv_7_143","topic":"Education and Learning","word":"semester","pos":"(n)","ipa":"/səˈmɛs.tɚ/","defVi":"học kỳ","defEn":"one of the two periods that the school or college year is divided into","examples":["She decided to study abroad during the spring [semester]. (=Dịch: Cô ấy quyết định đi du học trong học kỳ mùa xuân.)","Our final exams will take place at the end of this [semester]. (=Dịch: Các kỳ thi cuối kỳ của chúng tôi sẽ diễn ra vào cuối học kỳ này.)","He managed to improve his grades significantly in the second [semester]. (=Dịch: Cậu ấy đã cải thiện điểm số đáng kể trong học kỳ thứ hai.)"],"ukAudio":"/ai_services/tts3/?q=semester&lang=en-GB&ipa=%2Fs%C9%99%CB%88m%C9%9Bs.t%C9%9A%2F","usAudio":"/ai_services/tts3/?q=semester&lang=en-US&ipa=%2Fs%C9%99%CB%88m%C9%9Bs.t%C9%9A%2F"},{"id":"lv_7_144","topic":"Education and Learning","word":"seminar","pos":"(n)","ipa":"/ˈsɛm.əˌnɑr/","defVi":"Hội thảo, buổi thảo luận chuyên đề","defEn":"A class at a university or college in which a small group discusses a specific topic","examples":["Students are required to attend a weekly [seminar] on environmental policy. (=Dịch: Sinh viên bắt buộc phải tham dự một buổi hội thảo hàng tuần về chính sách môi trường.)","Professor Davis led an engaging [seminar] about modern literature yesterday. (=Dịch: Hôm qua Giáo sư Davis đã dẫn dắt một buổi thảo luận chuyên đề hấp dẫn về văn học hiện đại.)","Active participation in the [seminar] will help you gain better course grades. (=Dịch: Tích cực tham gia vào buổi hội thảo sẽ giúp bạn đạt điểm học phần tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=seminar&lang=en-GB&ipa=%2F%CB%88s%C9%9Bm.%C9%99%CB%8Cn%C9%91r%2F","usAudio":"/ai_services/tts3/?q=seminar&lang=en-US&ipa=%2F%CB%88s%C9%9Bm.%C9%99%CB%8Cn%C9%91r%2F"},{"id":"lv_7_145","topic":"Education and Learning","word":"shock","pos":"(n)","ipa":"/ʃɑːk/","defVi":"sự cú sốc, sự kinh ngạc hoặc bàng hoàng","defEn":"a sudden upsetting or surprising event or experience","examples":["The sudden news of his resignation came as a complete [shock] to everyone. (=Dịch: Tin tức đột ngột về việc anh ấy từ chức hoàn toàn là một cú sốc đối với mọi người.)","She was in [shock] after witnessing the severe traffic accident. (=Dịch: Cô ấy đã bị sốc sau khi chứng kiến vụ tai nạn giao thông nghiêm trọng.)","The unexpected price increase caused a major [shock] in the financial market. (=Dịch: Việc tăng giá bất ngờ đã gây ra một cú sốc lớn trên thị trường tài chính.)"],"ukAudio":"/ai_services/tts3/?q=shock&lang=en-GB&ipa=%2F%CA%83%C9%91%CB%90k%2F","usAudio":"/ai_services/tts3/?q=shock&lang=en-US&ipa=%2F%CA%83%C9%91%CB%90k%2F"},{"id":"lv_7_146","topic":"Education and Learning","word":"silence","pos":"(n)","ipa":"/ˈsaɪ.ləns/","defVi":"sự im lặng, sự tĩnh lặng","defEn":"the complete absence of sound or noise","examples":["A sudden [silence] fell over the room when the speaker walked onto the stage. (=Dịch: Một sự im lặng đột ngột bao trùm cả căn phòng khi diễn giả bước lên sân khấu.)","The library is a great place to study because of the total [silence]. (=Dịch: Thư viện là một nơi tuyệt vời để học tập nhờ vào sự yên tĩnh tuyệt đối.)","The audience observed a minute of [silence] to honor the victims. (=Dịch: Khán giả đã dành một phút mặc niệm để tưởng nhớ các nạn nhân.)"],"ukAudio":"/ai_services/tts3/?q=silence&lang=en-GB&ipa=%2F%CB%88sa%C9%AA.l%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=silence&lang=en-US&ipa=%2F%CB%88sa%C9%AA.l%C9%99ns%2F"},{"id":"lv_7_147","topic":"Education and Learning","word":"snap","pos":"(v)","ipa":"/snæp/","defVi":"gãy tách, bẻ gãy đột ngột; chộp lấy","defEn":"to break suddenly with a sharp cracking sound, or to move quickly and abruptly","examples":["The branch began to [snap] under the heavy weight of the snow. (=Dịch: Cành cây bắt đầu gãy tách dưới sức nặng của tuyết.)","He tried to [snap] a quick photo before the train departed. (=Dịch: Anh ấy cố chụp nhanh một bức ảnh trước khi tàu rời ga.)","Tired and stressed, she finally began to [snap] at her colleagues. (=Dịch: Mệt mỏi và căng thẳng, cuối cùng cô ấy bắt đầu gắt gỏng với đồng nghiệp của mình.)"],"ukAudio":"/ai_services/tts3/?q=snap&lang=en-GB&ipa=%2Fsn%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=snap&lang=en-US&ipa=%2Fsn%C3%A6p%2F"},{"id":"lv_7_148","topic":"Education and Learning","word":"sociology","pos":"(n)","ipa":"/ˌsoʊ.siˈɑː.lə.dʒi/","defVi":"xã hội học","defEn":"the scientific study of society, human social relationships, and institutions","examples":["She decided to major in [sociology] at university to understand community behavior. (=Dịch: Cô ấy quyết định học chuyên ngành xã hội học tại trường đại học để hiểu về hành vi cộng đồng.)","The professor published several influential papers on urban [sociology]. (=Dịch: Vị giáo sư đã xuất bản một số bài báo có tầm ảnh hưởng về xã hội học đô thị.)","Students in the [sociology] class conducted a survey on local living standards. (=Dịch: Các sinh viên trong lớp xã hội học đã thực hiện một cuộc khảo sát về mức sống địa phương.)"],"ukAudio":"/ai_services/tts3/?q=sociology&lang=en-GB&ipa=%2F%CB%8Cso%CA%8A.si%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=sociology&lang=en-US&ipa=%2F%CB%8Cso%CA%8A.si%CB%88%C9%91%CB%90.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_149","topic":"Education and Learning","word":"software","pos":"(n)","ipa":"/ˈsɑːft.wɛr/","defVi":"phần mềm máy tính","defEn":"the programs and other operating information used by a computer","examples":["The company developed new [software] to enhance cybersecurity. (=Dịch: Công ty đã phát triển phần mềm mới nhằm nâng cao an ninh mạng.)","You need to update your antivirus [software] regularly. (=Dịch: Bạn cần cập nhật phần mềm diệt vi-rút của mình thường xuyên.)","This graphic design [software] is very popular among creative professionals. (=Dịch: Phần mềm thiết kế đồ họa này rất phổ biến đối với các chuyên gia sáng tạo.)"],"ukAudio":"/ai_services/tts3/?q=software&lang=en-GB&ipa=%2F%CB%88s%C9%91%CB%90ft.w%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=software&lang=en-US&ipa=%2F%CB%88s%C9%91%CB%90ft.w%C9%9Br%2F"},{"id":"lv_7_150","topic":"Education and Learning","word":"spatial","pos":"(adj)","ipa":"/ˈspeɪ.ʃəl/","defVi":"thuộc về không gian","defEn":"relating to the position, area, and size of things in space","examples":["Architects need to have excellent [spatial] awareness when designing buildings. (=Dịch: Các kiến trúc sư cần có khả năng nhận thức không gian tuyệt vời khi thiết kế các tòa nhà.)","The test measures both verbal and [spatial] reasoning abilities. (=Dịch: Bài kiểm tra đo lường cả khả năng suy luận ngôn ngữ lẫn không gian.)","Video games can help children develop better [spatial] skills. (=Dịch: Trò chơi điện tử có thể giúp trẻ em phát triển các kỹ năng không gian tốt hơn.)"],"ukAudio":"/ai_services/tts3/?q=spatial&lang=en-GB&ipa=%2F%CB%88spe%C9%AA.%CA%83%C9%99l%2F","usAudio":"/ai_services/tts3/?q=spatial&lang=en-US&ipa=%2F%CB%88spe%C9%AA.%CA%83%C9%99l%2F"},{"id":"lv_7_151","topic":"Education and Learning","word":"specialised","pos":"(adj)","ipa":"/ˈspeʃ.ə.laɪzd/","defVi":"chuyên dụng, chuyên môn hóa","defEn":"designed for or relating to a particular purpose, activity, or area of knowledge","examples":["This lab requires [specialised] equipment to conduct precise chemical tests. (=Dịch: Phòng thí nghiệm này yêu cầu thiết bị chuyên dụng để thực hiện các xét nghiệm hóa học chính xác.)","The doctor gave her [specialised] medical advice regarding her rare condition. (=Dịch: Bác sĩ đã đưa ra cho cô ấy lời khuyên y tế chuyên sâu về tình trạng bệnh hiếm gặp của mình.)","He took several [specialised] training courses to advance his technical career. (=Dịch: Anh ấy đã tham gia nhiều khóa đào tạo chuyên ngành để phát triển sự nghiệp kỹ thuật của mình.)"],"ukAudio":"/ai_services/tts3/?q=specialised&lang=en-GB&ipa=%2F%CB%88spe%CA%83.%C9%99.la%C9%AAzd%2F","usAudio":"/ai_services/tts3/?q=specialised&lang=en-US&ipa=%2F%CB%88spe%CA%83.%C9%99.la%C9%AAzd%2F"},{"id":"lv_7_152","topic":"Education and Learning","word":"spectator","pos":"(n)","ipa":"/ˈspɛk.teɪ.tər/","defVi":"khán giả (theo dõi sự kiện, trận đấu ngoài trời/thể thao)","defEn":"a person who watches a show, game, or other event","examples":["Over fifty thousand [spectator]s gathered at the stadium for the football final. (=Dịch: Hơn năm mươi ngàn khán giả đã tập trung tại sân vận động cho trận chung kết bóng đá.)","An excited [spectator] ran onto the pitch during the tennis match. (=Dịch: Một khán giả quá khích đã chạy vào sân trong suốt trận đấu quần vợt.)","She preferred being a [spectator] rather than participating in competitive sports. (=Dịch: Cô ấy thích làm khán giả hơn là tham gia vào các môn thể thao thi đấu.)"],"ukAudio":"/ai_services/tts3/?q=spectator&lang=en-GB&ipa=%2F%CB%88sp%C9%9Bk.te%C9%AA.t%C9%99r%2F","usAudio":"/ai_services/tts3/?q=spectator&lang=en-US&ipa=%2F%CB%88sp%C9%9Bk.te%C9%AA.t%C9%99r%2F"},{"id":"lv_7_153","topic":"Education and Learning","word":"spin","pos":"(v)","ipa":"/spɪn/","defVi":"quay tròn, xoay tròn","defEn":"to turn around quickly and repeatedly","examples":["The dancer began to [spin] gracefully across the stage. (=Dịch: Vũ công bắt đầu xoay tròn một cách uyển chuyển trên sân khấu.)","If you [spin] around too fast, you might feel dizzy. (=Dịch: Nếu bạn quay tròn quá nhanh, bạn có thể cảm thấy chóng mặt.)","The washing machine started to [spin] the clothes dry. (=Dịch: Máy giặt bắt đầu vắt khô quần áo.)"],"ukAudio":"/ai_services/tts3/?q=spin&lang=en-GB&ipa=%2Fsp%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=spin&lang=en-US&ipa=%2Fsp%C9%AAn%2F"},{"id":"lv_7_154","topic":"Education and Learning","word":"spite","pos":"(n)","ipa":"/spaɪt/","defVi":"sự ác ý, lòng hằn học","defEn":"a desire to hurt, annoy, or offend someone","examples":["He refused to invite her out of pure [spite]. (=Dịch: Anh ấy từ chối mời cô ấy chỉ vì lòng ác ý đơn thuần.)","She hid his keys just for [spite]. (=Dịch: Cô ấy giấu chìa khóa của anh ta chỉ để chọc tức.)","In [spite] of the heavy rain, they decided to go camping. (=Dịch: Mặc dù trời mưa to, họ vẫn quyết định đi cắm trại.)"],"ukAudio":"/ai_services/tts3/?q=spite&lang=en-GB&ipa=%2Fspa%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=spite&lang=en-US&ipa=%2Fspa%C9%AAt%2F"},{"id":"lv_7_155","topic":"Education and Learning","word":"sponsor","pos":"(v)","ipa":"/ˈspɑn.sɚ/","defVi":"tài trợ, bảo trợ","defEn":"to support a person, organization, or event by providing money or other help","examples":["A local bank agreed to [sponsor] the youth sports tournament. (=Dịch: Một ngân hàng địa phương đã đồng ý tài trợ cho giải đấu thể thao thanh thiếu niên.)","Many large companies [sponsor] scientific research at the university. (=Dịch: Nhiều công ty lớn tài trợ cho các nghiên cứu khoa học tại trường đại học.)","They are looking for international partners to [sponsor] the cultural festival. (=Dịch: Họ đang tìm kiếm các đối tác quốc tế để tài trợ cho lễ hội văn hóa.)"],"ukAudio":"/ai_services/tts3/?q=sponsor&lang=en-GB&ipa=%2F%CB%88sp%C9%91n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sponsor&lang=en-US&ipa=%2F%CB%88sp%C9%91n.s%C9%9A%2F"},{"id":"lv_7_156","topic":"Education and Learning","word":"sporting","pos":"(adj)","ipa":"/ˈspɔːr.tɪŋ/","defVi":"liên quan đến thể thao, mang tính thể thao","defEn":"connected with or used for sports","examples":["The Olympic Games is the biggest international [sporting] event in the world. (=Dịch: Thế vận hội Olympic là sự kiện thể thao quốc tế lớn nhất trên thế giới.)","The school recently invested in modern [sporting] facilities for students. (=Dịch: Nhà trường gần đây đã đầu tư vào cơ sở vật chất thể thao hiện đại cho học sinh.)","She comes from a very [sporting] family where everyone plays tennis. (=Dịch: Cô ấy xuất thân từ một gia đình rất yêu thể thao, nơi ai cũng chơi quần vợt.)"],"ukAudio":"/ai_services/tts3/?q=sporting&lang=en-GB&ipa=%2F%CB%88sp%C9%94%CB%90r.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=sporting&lang=en-US&ipa=%2F%CB%88sp%C9%94%CB%90r.t%C9%AA%C5%8B%2F"},{"id":"lv_7_157","topic":"Education and Learning","word":"structured","pos":"(adj)","ipa":"/ˈstrʌk.tʃɚd/","defVi":"Có cấu trúc rõ ràng, có tổ chức, bài bản","defEn":"Organized in a clear, systematic, or planned way","examples":["The course offers a well [structured] approach to learning academic writing. (=Dịch: Khóa học cung cấp một phương pháp có cấu trúc bài bản để học viết học thuật.)","Children often thrive in a highly [structured] classroom environment. (=Dịch: Trẻ em thường phát triển tốt trong một môi trường lớp học có tổ chức kỷ luật chặt chẽ.)","The interview followed a [structured] format with predefined questions. (=Dịch: Buổi phỏng vấn tuân theo một định dạng có cấu trúc với các câu hỏi được định trước.)"],"ukAudio":"/ai_services/tts3/?q=structured&lang=en-GB&ipa=%2F%CB%88str%CA%8Ck.t%CA%83%C9%9Ad%2F","usAudio":"/ai_services/tts3/?q=structured&lang=en-US&ipa=%2F%CB%88str%CA%8Ck.t%CA%83%C9%9Ad%2F"},{"id":"lv_7_158","topic":"Education and Learning","word":"supervise","pos":"(v)","ipa":"/ˈsu.pər.vaɪz/","defVi":"giám sát, quản lý","defEn":"to watch and direct someone or something to make sure work is done correctly","examples":["A senior manager was appointed to [supervise] the construction project. (=Dịch: Một người quản lý cấp cao đã được chỉ định để giám sát dự án xây dựng.)","Teachers must [supervise] students closely during laboratory experiments. (=Dịch: Giáo viên phải giám sát học sinh chặt chẽ trong các buổi thực hành thí nghiệm.)","She was asked to [supervise] the new interns during their first week. (=Dịch: Cô ấy được yêu cầu giám sát các thực tập sinh mới trong tuần đầu tiên của họ.)"],"ukAudio":"/ai_services/tts3/?q=supervise&lang=en-GB&ipa=%2F%CB%88su.p%C9%99r.va%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=supervise&lang=en-US&ipa=%2F%CB%88su.p%C9%99r.va%C9%AAz%2F"},{"id":"lv_7_159","topic":"Education and Learning","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng / phụ lục","defEn":"something added to complete a thing, make up for a deficiency, or extend it","examples":["Many athletes take a daily vitamin [supplement] to improve their performance. (=Dịch: Nhiều vận động viên uống bổ sung vitamin hàng ngày để cải thiện thành tích của họ.)","The Sunday newspaper includes a special travel [supplement] this week. (=Dịch: Báo ra ngày Chủ nhật tuần này có thêm một phụ lục du lịch đặc biệt.)","She worked a second job as a [supplement] to her regular income. (=Dịch: Cô ấy đã làm thêm công việc thứ hai để bổ sung cho thu nhập thường kỳ của mình.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_7_160","topic":"Education and Learning","word":"supportive","pos":"(adj)","ipa":"/səˈpɔːr.t̬ɪv/","defVi":"ủng hộ, luôn khích lệ và giúp đỡ","defEn":"providing encouragement, help, or emotional support to someone","examples":["Her family was extremely [supportive] when she decided to change her career path. (=Dịch: Gia đình đã rất ủng hộ khi cô ấy quyết định thay đổi con đường sự nghiệp.)","A [supportive] work environment can significantly reduce employee stress. (=Dịch: Một môi trường làm việc luôn hỗ trợ nhau có thể giảm đáng kể sự căng thẳng của nhân viên.)","He thanked his friends for being so [supportive] during his difficult times. (=Dịch: Anh ấy cảm ơn bạn bè vì đã luôn ở bên giúp đỡ trong suốt những thời điểm khó khăn.)"],"ukAudio":"/ai_services/tts3/?q=supportive&lang=en-GB&ipa=%2Fs%C9%99%CB%88p%C9%94%CB%90r.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=supportive&lang=en-US&ipa=%2Fs%C9%99%CB%88p%C9%94%CB%90r.t%CC%AC%C9%AAv%2F"},{"id":"lv_7_161","topic":"Education and Learning","word":"swedish","pos":"(adj)","ipa":"/ˈswi.dɪʃ/","defVi":"thuộc về Thụy Điển hoặc tiếng Thụy Điển","defEn":"relating to Sweden, its people, or its language","examples":["The company is famous for selling affordable [swedish] furniture worldwide. (=Dịch: Công ty này nổi tiếng với việc bán đồ nội thất Thụy Điển giá cả phải chăng trên toàn thế giới.)","He is learning the [swedish] language before moving to Stockholm for his studies. (=Dịch: Anh ấy đang học tiếng Thụy Điển trước khi chuyển đến Stockholm để du học.)","Traditional [swedish] cuisine often features fresh fish and root vegetables. (=Dịch: Ẩm thực Thụy Điển truyền thống thường có cá tươi và các loại củ.)"],"ukAudio":"/ai_services/tts3/?q=swedish&lang=en-GB&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=swedish&lang=en-US&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F"},{"id":"lv_7_162","topic":"Education and Learning","word":"tame","pos":"(adj)","ipa":"/ˈteɪm/","defVi":"đã thuần hóa, ngoan ngoãn","defEn":"not wild or dangerous because of being trained to live with people","examples":["The birds in the city park are remarkably [tame] and will eat from your hand. (=Dịch: Những chú chim trong công viên thành phố rất dạn người và sẽ ăn trực tiếp từ tay bạn.)","After years of living on the farm, the deer became completely [tame]. (=Dịch: Sau nhiều năm sống trong nông trại, chú hươu đã trở nên hoàn toàn thuần tính.)","Critics found the action movie rather [tame] compared to its thrilling prequel. (=Dịch: Các nhà phê bình thấy bộ phim hành động này khá tẻ nhạt khi so sánh với phần trước đầy kịch tính.)"],"ukAudio":"/ai_services/tts3/?q=tame&lang=en-GB&ipa=%2F%CB%88te%C9%AAm%2F","usAudio":"/ai_services/tts3/?q=tame&lang=en-US&ipa=%2F%CB%88te%C9%AAm%2F"},{"id":"lv_7_163","topic":"Education and Learning","word":"terminology","pos":"(n)","ipa":"/ˌtɜr.məˈnɑ.lə.dʒi/","defVi":"thuật ngữ, hệ thống thuật ngữ chuyên môn","defEn":"the special words or expressions used in relation to a particular subject or job","examples":["Medical [terminology] can be difficult for ordinary patients to understand. (=Dịch: Thuật ngữ y khoa có thể khó hiểu đối với những bệnh nhân bình thường.)","The lecturer explained the scientific [terminology] before starting the experiment. (=Dịch: Giảng viên đã giải thích các thuật ngữ khoa học trước khi bắt đầu thí nghiệm.)","You should avoid using too much technical [terminology] in your IELTS essay. (=Dịch: Bạn nên tránh sử dụng quá nhiều thuật ngữ kỹ thuật trong bài luận IELTS của mình.)"],"ukAudio":"/ai_services/tts3/?q=terminology&lang=en-GB&ipa=%2F%CB%8Ct%C9%9Cr.m%C9%99%CB%88n%C9%91.l%C9%99.d%CA%92i%2F","usAudio":"/ai_services/tts3/?q=terminology&lang=en-US&ipa=%2F%CB%8Ct%C9%9Cr.m%C9%99%CB%88n%C9%91.l%C9%99.d%CA%92i%2F"},{"id":"lv_7_164","topic":"Education and Learning","word":"terribly","pos":"(adv)","ipa":"/ˈter.ə.bli/","defVi":"vô cùng, rất nhiều","defEn":"very much; extremely","examples":["I am [terribly] sorry for keeping you waiting for so long. (=Dịch: Tôi vô cùng xin lỗi vì đã để bạn phải đợi lâu như vậy.)","She was [terribly] nervous before giving her presentation to the class. (=Dịch: Cô ấy đã cực kỳ lo lắng trước khi thuyết trình trước cả lớp.)","The weather was [terribly] cold during our winter trip. (=Dịch: Thời tiết vô cùng lạnh giá trong chuyến đi mùa đông của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=terribly&lang=en-GB&ipa=%2F%CB%88ter.%C9%99.bli%2F","usAudio":"/ai_services/tts3/?q=terribly&lang=en-US&ipa=%2F%CB%88ter.%C9%99.bli%2F"},{"id":"lv_7_165","topic":"Education and Learning","word":"testing","pos":"(n)","ipa":"/ˈtɛs.tɪŋ/","defVi":"sự kiểm tra, thử nghiệm","defEn":"the activity of examining something to find out how well it works or if it is safe","examples":["The new drug is currently undergoing clinical [testing] on human volunteers. (=Dịch: Loại thuốc mới hiện đang trải qua quá trình thử nghiệm lâm sàng trên các tình nguyện viên.)","Extensive safety [testing] is required before any vehicle is approved for sale. (=Dịch: Việc kiểm tra an toàn toàn diện là bắt buộc trước khi bất kỳ phương tiện nào được phép bán ra.)","Software [testing] helps identify bugs before the official release date. (=Dịch: Việc kiểm thử phần mềm giúp phát hiện các lỗi trước ngày phát hành chính thức.)"],"ukAudio":"/ai_services/tts3/?q=testing&lang=en-GB&ipa=%2F%CB%88t%C9%9Bs.t%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=testing&lang=en-US&ipa=%2F%CB%88t%C9%9Bs.t%C9%AA%C5%8B%2F"},{"id":"lv_7_166","topic":"Education and Learning","word":"textbook","pos":"(n)","ipa":"/ˈtɛkst.bʊk/","defVi":"sách giáo khoa, giáo trình","defEn":"a book that contains detailed information about a subject for study in schools or colleges","examples":["Students are required to buy the latest biology [textbook] for this course. (=Dịch: Sinh viên được yêu cầu mua cuốn giáo trình sinh học mới nhất cho khóa học này.)","She opened her history [textbook] to revise for the upcoming exam. (=Dịch: Cô ấy mở sách giáo khoa lịch sử ra để ôn tập cho kỳ thi sắp tới.)","His response was a [textbook] example of professional communication. (=Dịch: Câu trả lời của anh ấy là một ví dụ điển hình mang tính sách vở về kỹ năng giao tiếp chuyên nghiệp.)"],"ukAudio":"/ai_services/tts3/?q=textbook&lang=en-GB&ipa=%2F%CB%88t%C9%9Bkst.b%CA%8Ak%2F","usAudio":"/ai_services/tts3/?q=textbook&lang=en-US&ipa=%2F%CB%88t%C9%9Bkst.b%CA%8Ak%2F"},{"id":"lv_7_167","topic":"Education and Learning","word":"tone","pos":"(n)","ipa":"/toʊn/","defVi":"giọng điệu, sắc thái, tông giọng","defEn":"the general mood, feeling, or attitude expressed in speech or writing","examples":["Try to keep a polite [tone] when responding to customer complaints. (=Dịch: Hãy cố gắng giữ giọng điệu lịch sự khi phản hồi các khiếu nại của khách hàng.)","The professor used a serious [tone] to discuss the importance of academic honesty. (=Dịch: Giáo sư đã sử dụng một tông giọng nghiêm túc để thảo luận về tầm quan trọng của sự trung thực trong học thuật.)","The article set an optimistic [tone] regarding future economic growth. (=Dịch: Bài báo đã tạo ra một sắc thái lạc quan về sự tăng trưởng kinh tế trong tương lai.)"],"ukAudio":"/ai_services/tts3/?q=tone&lang=en-GB&ipa=%2Fto%CA%8An%2F","usAudio":"/ai_services/tts3/?q=tone&lang=en-US&ipa=%2Fto%CA%8An%2F"},{"id":"lv_7_168","topic":"Education and Learning","word":"tough","pos":"(adj)","ipa":"/tʌf/","defVi":"khó khăn, cam go; cứng rắn, bền bỉ","defEn":"difficult to do, deal with, or overcome; strong and durable","examples":["The committee had to make some [tough] decisions about budget cuts. (=Dịch: Ủy ban đã phải đưa ra một số quyết định khó khăn về việc cắt giảm ngân sách.)","He showed that he was [tough] enough to handle the pressure of the competition. (=Dịch: Anh ấy đã chứng minh rằng mình đủ kiên cường để chịu được áp lực của cuộc thi.)","Hiking across the rugged mountains proved to be a [tough] challenge for the group. (=Dịch: Chuyến đi bộ qua những ngọn núi gồ ghề hóa ra là một thử thách cam go đối với cả nhóm.)"],"ukAudio":"/ai_services/tts3/?q=tough&lang=en-GB&ipa=%2Ft%CA%8Cf%2F","usAudio":"/ai_services/tts3/?q=tough&lang=en-US&ipa=%2Ft%CA%8Cf%2F"},{"id":"lv_7_169","topic":"Education and Learning","word":"tutorial","pos":"(n)","ipa":"/tuːˈtɔr.i.əl/","defVi":"Buổi học phụ đạo, buổi thảo luận nhóm nhỏ với giảng viên","defEn":"A period of study with a tutor involving one student or a very small group","examples":["I booked an individual [tutorial] to discuss my research proposal with the supervisor. (=Dịch: Tôi đã đặt một buổi học riêng với người hướng dẫn để thảo luận về đề cương nghiên cứu của mình.)","The weekly [tutorial] gives students a chance to ask detailed questions. (=Dịch: Buổi phụ đạo hàng tuần mang đến cho sinh viên cơ hội đặt ra những câu hỏi chi tiết.)","You can watch an online video [tutorial] to learn basic programming skills. (=Dịch: Bạn có thể xem một video hướng dẫn trực tuyến để học các kỹ năng lập trình cơ bản.)"],"ukAudio":"/ai_services/tts3/?q=tutorial&lang=en-GB&ipa=%2Ftu%CB%90%CB%88t%C9%94r.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tutorial&lang=en-US&ipa=%2Ftu%CB%90%CB%88t%C9%94r.i.%C9%99l%2F"},{"id":"lv_7_170","topic":"Education and Learning","word":"ultimate","pos":"(adj)","ipa":"/ˈʌl.tə.mət/","defVi":"cuối cùng, tối thượng, cốt yếu","defEn":"final, highest, or most important; happening at the end of a long process","examples":["Her [ultimate] goal is to establish her own environmental research foundation. (=Dịch: Mục tiêu cuối cùng của cô ấy là thành lập quỹ nghiên cứu môi trường của riêng mình.)","The president holds the [ultimate] responsibility for the government's decisions. (=Dịch: Tổng thống nắm giữ trách nhiệm tối cao đối với các quyết định của chính phủ.)","Finding a cure for the disease remains the [ultimate] aim of the scientists. (=Dịch: Tìm ra phương pháp chữa khỏi căn bệnh vẫn là mục tiêu quan trọng nhất của các nhà khoa học.)"],"ukAudio":"/ai_services/tts3/?q=ultimate&lang=en-GB&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F","usAudio":"/ai_services/tts3/?q=ultimate&lang=en-US&ipa=%2F%CB%88%CA%8Cl.t%C9%99.m%C9%99t%2F"},{"id":"lv_7_171","topic":"Education and Learning","word":"uncertainty","pos":"(n)","ipa":"/ʌnˈsɝː.tən.ti/","defVi":"sự không chắc chắn, tình trạng bất định","defEn":"a state of not being definite or clear","examples":["Economic [uncertainty] has caused many people to delay buying a home. (=Dịch: Sự bất ổn kinh tế đã khiến nhiều người trì hoãn việc mua nhà.)","There is still some [uncertainty] about the exact date of the exam. (=Dịch: Vẫn còn một vài sự không chắc chắn về ngày thi chính xác.)","Living with so much [uncertainty] can be very stressful. (=Dịch: Sống trong quá nhiều sự bất định có thể gây ra rất nhiều căng thẳng.)"],"ukAudio":"/ai_services/tts3/?q=uncertainty&lang=en-GB&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F","usAudio":"/ai_services/tts3/?q=uncertainty&lang=en-US&ipa=%2F%CA%8Cn%CB%88s%C9%9D%CB%90.t%C9%99n.ti%2F"},{"id":"lv_7_172","topic":"Education and Learning","word":"undergraduate","pos":"(n)","ipa":"/ˌʌn.dərˈɡrædʒ.u.ət/","defVi":"sinh viên chưa tốt nghiệp, sinh viên đại học (chưa có bằng cử nhân)","defEn":"a university student who has not yet completed their first degree (bachelor's)","examples":["The scholarship is open to any full-time [undergraduate] studying science. (=Dịch: Học bổng dành cho bất kỳ sinh viên đại học chính quy nào đang theo học ngành khoa học.)","As an [undergraduate], she participated actively in student government. (=Dịch: Khi còn là sinh viên đại học, cô đã tích cực tham gia vào ban đại diện sinh viên.)","The university offers research opportunities even at the [undergraduate] level. (=Dịch: Trường đại học mang lại các cơ hội nghiên cứu ngay cả ở bậc đại học.)"],"ukAudio":"/ai_services/tts3/?q=undergraduate&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F","usAudio":"/ai_services/tts3/?q=undergraduate&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.d%C9%99r%CB%88%C9%A1r%C3%A6d%CA%92.u.%C9%99t%2F"},{"id":"lv_7_173","topic":"Education and Learning","word":"unfair","pos":"(adj)","ipa":"/ʌnˈfɛr/","defVi":"bất công, không công bằng","defEn":"not treating people equally or according to the rules of justice","examples":["Many employees felt that the promotion process was completely [unfair]. (=Dịch: Nhiều nhân viên cảm thấy rằng quy trình thăng chức hoàn toàn không công bằng.)","It is [unfair] to judge someone without knowing the full context of their actions. (=Dịch: Thật bất công khi phán xét ai đó mà không biết rõ toàn bộ bối cảnh hành động của họ.)","The team complained about an [unfair] referee decision during the match. (=Dịch: Đội bóng đã phàn nàn về một quyết định thiếu công bằng của trọng tài trong trận đấu.)"],"ukAudio":"/ai_services/tts3/?q=unfair&lang=en-GB&ipa=%2F%CA%8Cn%CB%88f%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=unfair&lang=en-US&ipa=%2F%CA%8Cn%CB%88f%C9%9Br%2F"},{"id":"lv_7_174","topic":"Education and Learning","word":"unfamiliar","pos":"(adj)","ipa":"/ˌʌn.fəˈmɪl.jɚ/","defVi":"xa lạ, không quen thuộc","defEn":"not known or recognized; strange","examples":["He felt nervous driving in an [unfamiliar] city at night. (=Dịch: Anh ấy cảm thấy lo lắng khi lái xe ở một thành phố xa lạ vào ban đêm.)","The text was full of [unfamiliar] technical terms. (=Dịch: Đoạn văn bản chứa đầy những thuật ngữ kỹ thuật xa lạ.)","She had to adapt quickly to [unfamiliar] working conditions. (=Dịch: Cô ấy đã phải thích nghi nhanh chóng với điều kiện làm việc mới mẻ.)"],"ukAudio":"/ai_services/tts3/?q=unfamiliar&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.f%C9%99%CB%88m%C9%AAl.j%C9%9A%2F","usAudio":"/ai_services/tts3/?q=unfamiliar&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.f%C9%99%CB%88m%C9%AAl.j%C9%9A%2F"},{"id":"lv_7_175","topic":"Education and Learning","word":"unpaid","pos":"(adj)","ipa":"/ˌʌnˈpeɪd/","defVi":"không được trả lương, chưa thanh toán","defEn":"done without receiving pay, or not yet paid","examples":["She decided to take three months of [unpaid] leave to care for her mother. (=Dịch: Cô ấy quyết định nghỉ phép không lương ba tháng để chăm sóc mẹ.)","There are several [unpaid] bills sitting on his desk. (=Dịch: Có vài hóa đơn chưa thanh toán đang nằm trên bàn làm việc của anh ấy.)","Many students gain experience by doing [unpaid] internships. (=Dịch: Nhiều sinh viên tích lũy kinh nghiệm bằng cách tham gia các kỳ thực tập không lương.)"],"ukAudio":"/ai_services/tts3/?q=unpaid&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn%CB%88pe%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=unpaid&lang=en-US&ipa=%2F%CB%8C%CA%8Cn%CB%88pe%C9%AAd%2F"},{"id":"lv_7_176","topic":"Education and Learning","word":"update","pos":"(n)","ipa":"/ˈʌp.deɪt/","defVi":"thông tin cập nhật, bản cập nhật","defEn":"the latest information about a situation, or a new version of software","examples":["The manager gave us an [update] on the progress of the project. (=Dịch: Người quản lý đã cung cấp cho chúng tôi thông tin cập nhật về tiến độ dự án.)","Make sure you install the latest security [update] on your phone. (=Dịch: Hãy chắc chắn rằng bạn đã cài đặt bản cập nhật bảo mật mới nhất trên điện thoại của mình.)","Stay tuned for weather [update]s throughout the evening. (=Dịch: Hãy đón xem các bản tin cập nhật thời tiết trong suốt buổi tối.)"],"ukAudio":"/ai_services/tts3/?q=update&lang=en-GB&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=update&lang=en-US&ipa=%2F%CB%88%CA%8Cp.de%C9%AAt%2F"},{"id":"lv_7_177","topic":"Education and Learning","word":"verb","pos":"(n)","ipa":"/vɜrb/","defVi":"động từ","defEn":"a word that describes an action, condition, or experience","examples":["Every complete English sentence must contain at least one [verb]. (=Dịch: Mỗi câu tiếng Anh hoàn chỉnh phải chứa ít nhất một động từ.)","Irregular [verb] forms can be challenging for beginners to memorize. (=Dịch: Các dạng động từ bất quy tắc có thể là thử thách ghi nhớ đối với người mới bắt đầu.)","Can you identify the main [verb] in this complex sentence? (=Dịch: Bạn có thể xác định động từ chính trong câu phức này không?)"],"ukAudio":"/ai_services/tts3/?q=verb&lang=en-GB&ipa=%2Fv%C9%9Crb%2F","usAudio":"/ai_services/tts3/?q=verb&lang=en-US&ipa=%2Fv%C9%9Crb%2F"},{"id":"lv_7_178","topic":"Education and Learning","word":"version","pos":"(n)","ipa":"/ˈvɝː.ʒən/","defVi":"phiên bản","defEn":"a particular form of something that differs slightly from others","examples":["You should install the latest [version] of the software for better security. (=Dịch: Bạn nên cài đặt phiên bản mới nhất của phần mềm để bảo mật tốt hơn.)","His [version] of the events differed greatly from what actually happened. (=Dịch: Phiên bản lời kể của anh ấy về các sự việc khác rất nhiều so với những gì thực sự đã xảy ra.)","The movie is a modern [version] of a classic fairy tale. (=Dịch: Bộ phim là một phiên bản hiện đại của một câu chuyện cổ tích kinh điển.)"],"ukAudio":"/ai_services/tts3/?q=version&lang=en-GB&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=version&lang=en-US&ipa=%2F%CB%88v%C9%9D%CB%90.%CA%92%C9%99n%2F"},{"id":"lv_7_179","topic":"Education and Learning","word":"vet","pos":"(n)","ipa":"/vɛt/","defVi":"bác sĩ thú y","defEn":"a doctor who treats animals","examples":["We took our injured dog to the [vet] immediately. (=Dịch: Chúng tôi đã đưa chú chó bị thương đến bác sĩ thú y ngay lập tức.)","She has wanted to become a [vet] ever since she was a little girl. (=Dịch: Cô ấy đã muốn trở thành một bác sĩ thú y kể từ khi còn là một cô bé.)","The [vet] prescribed some medicine for the cat's ear infection. (=Dịch: Bác sĩ thú y đã kê đơn thuốc điều trị nhiễm trùng tai cho con mèo.)"],"ukAudio":"/ai_services/tts3/?q=vet&lang=en-GB&ipa=%2Fv%C9%9Bt%2F","usAudio":"/ai_services/tts3/?q=vet&lang=en-US&ipa=%2Fv%C9%9Bt%2F"},{"id":"lv_7_180","topic":"Education and Learning","word":"vocabulary","pos":"(n)","ipa":"/voʊˈkæb.jəˌlɛr.i/","defVi":"Vốn từ vựng, từ ngữ","defEn":"All the words known or used by a person, or in a particular language","examples":["Reading academic articles regularly will help expand your [vocabulary]. (=Dịch: Đọc các bài báo học thuật thường xuyên sẽ giúp mở rộng vốn từ vựng của bạn.)","The test evaluates your command of English [vocabulary] and grammar. (=Dịch: Bài kiểm tra đánh giá khả năng nắm vững ngữ pháp và từ vựng tiếng Anh của bạn.)","Medical students must learn a large amount of specialized [vocabulary]. (=Dịch: Sinh viên y khoa phải học một lượng lớn từ vựng chuyên ngành.)"],"ukAudio":"/ai_services/tts3/?q=vocabulary&lang=en-GB&ipa=%2Fvo%CA%8A%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=vocabulary&lang=en-US&ipa=%2Fvo%CA%8A%CB%88k%C3%A6b.j%C9%99%CB%8Cl%C9%9Br.i%2F"},{"id":"lv_7_181","topic":"Education and Learning","word":"weakness","pos":"(n)","ipa":"/ˈwik.nəs/","defVi":"điểm yếu, nhược điểm","defEn":"a particular part of someone's character or ability that is not strong; a lack of strength","examples":["She was asked about her greatest [weakness] during the job interview. (=Dịch: Cô ấy đã được hỏi về điểm yếu lớn nhất của mình trong buổi phỏng vấn xin việc.)","Chocolate is my biggest [weakness] when I try to diet. (=Dịch: Sô-cô-la là điểm yếu lớn nhất của tôi mỗi khi cố gắng ăn kiêng.)","The report highlighted several [weaknesses] in the company's security system. (=Dịch: Bản báo cáo đã nêu bật một số điểm yếu trong hệ thống an ninh của công ty.)"],"ukAudio":"/ai_services/tts3/?q=weakness&lang=en-GB&ipa=%2F%CB%88wik.n%C9%99s%2F","usAudio":"/ai_services/tts3/?q=weakness&lang=en-US&ipa=%2F%CB%88wik.n%C9%99s%2F"},{"id":"lv_7_182","topic":"Education and Learning","word":"zone","pos":"(n)","ipa":"/ˈzoʊn/","defVi":"khu vực, phân khu","defEn":"an area or region that has a particular feature or purpose","examples":["The city created a pedestrian [zone] where cars are not allowed. (=Dịch: Thành phố đã tạo ra một khu vực dành cho người đi bộ, nơi các phương tiện ô tô không được phép đi vào.)","Smoking is strictly prohibited in this designated non-smoking [zone]. (=Dịch: Hút thuốc bị nghiêm cấm trong khu vực không hút thuốc đã được quy định này.)","The government declared the flooded region a disaster [zone]. (=Dịch: Chính phủ đã tuyên bố khu vực ngập lụt là một vùng thảm họa.)"],"ukAudio":"/ai_services/tts3/?q=zone&lang=en-GB&ipa=%2F%CB%88zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=zone&lang=en-US&ipa=%2F%CB%88zo%CA%8An%2F"}]},"rawTopic":"Education and Learning"},{"id":"listening_u5_9","title":"Chủ đề 9/10: Food and Health","actTitle":"Từ vựng chủ đề: Food and Health (99 từ)","problem":{"pType":"topic_flashcards","topic":"Food and Health","count":99,"words":[{"id":"lv_8_0","topic":"Food and Health","word":"absorb","pos":"(v)","ipa":"/əbˈzɔːrb/","defVi":"hấp thụ, thấm hút","defEn":"to take in liquid, gas, or heat gradually from the space or surface around","examples":["Plants [absorb] nutrients and water from the soil through their roots. (=Dịch: Cây cối hấp thụ chất dinh dưỡng và nước từ đất thông qua rễ.)","Use a dry sponge to [absorb] the spilled juice on the table. (=Dịch: Dùng một miếng bọt biển khô để thấm nước trái cây bị đổ trên bàn.)","Black clothing tends to [absorb] more heat from sunlight than white clothing. (=Dịch: Quần áo màu đen có xu hướng hấp thụ nhiều nhiệt từ ánh nắng mặt trời hơn quần áo màu trắng.)"],"ukAudio":"/ai_services/tts3/?q=absorb&lang=en-GB&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F","usAudio":"/ai_services/tts3/?q=absorb&lang=en-US&ipa=%2F%C9%99b%CB%88z%C9%94%CB%90rb%2F"},{"id":"lv_8_1","topic":"Food and Health","word":"acid","pos":"(n)","ipa":"/ˈæs.ɪd/","defVi":"axit","defEn":"a chemical substance with a pH of less than 7 that reacts with bases","examples":["Citrus fruits contain citric [acid], which gives them a sour taste. (=Dịch: Trái cây họ cam quýt có chứa axit xitric, tạo cho chúng có vị chua.)","Stomach [acid] plays a crucial role in breaking down food during digestion. (=Dịch: Axit trong dạ dày đóng một vai trò quan trọng trong việc phân hủy thức ăn khi tiêu hóa.)","You should wear protective gloves when handling concentrated [acid]. (=Dịch: Bạn nên đeo găng tay bảo hộ khi xử lý axit đậm đặc.)"],"ukAudio":"/ai_services/tts3/?q=acid&lang=en-GB&ipa=%2F%CB%88%C3%A6s.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=acid&lang=en-US&ipa=%2F%CB%88%C3%A6s.%C9%AAd%2F"},{"id":"lv_8_2","topic":"Food and Health","word":"additive","pos":"(n)","ipa":"/ˈæd.ə.t̬ɪv/","defVi":"chất phụ gia","defEn":"a substance added in small amounts to something else to improve or preserve it","examples":["Many consumers prefer organic food that contains no synthetic food [additive]. (=Dịch: Nhiều người tiêu dùng ưa chuộng thực phẩm hữu cơ không chứa phụ gia thực phẩm tổng hợp.)","The company uses a special chemical [additive] to enhance the durability of its paint. (=Dịch: Công ty sử dụng một loại phụ gia hóa học đặc biệt để nâng cao độ bền của sơn.)","A fuel [additive] can help clean engine deposits and improve mileage. (=Dịch: Chất phụ gia nhiên liệu có thể giúp làm sạch cặn động cơ và cải thiện hiệu suất tiêu hao nhiên liệu.)"],"ukAudio":"/ai_services/tts3/?q=additive&lang=en-GB&ipa=%2F%CB%88%C3%A6d.%C9%99.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=additive&lang=en-US&ipa=%2F%CB%88%C3%A6d.%C9%99.t%CC%AC%C9%AAv%2F"},{"id":"lv_8_3","topic":"Food and Health","word":"aerobic","pos":"(adj)","ipa":"/eˈroʊ.bɪk/","defVi":"(thuộc) hiếu khí, thể dục nhịp điệu","defEn":"involving or improving the body's use of oxygen through exercise.","examples":["Swimming and cycling are great forms of [aerobic] exercise. (=Dịch: Bơi lội và đạp xe là những hình thức tập thể dục hiếu khí tuyệt vời.)","Regular [aerobic] activity strengthens the heart and lungs. (=Dịch: Hoạt động hiếu khí thường xuyên giúp tăng cường sức khỏe tim và phổi.)","She attends an [aerobic] dance class three times a week. (=Dịch: Cô ấy tham gia lớp học nhảy aerobic ba lần một tuần.)"],"ukAudio":"/ai_services/tts3/?q=aerobic&lang=en-GB&ipa=%2Fe%CB%88ro%CA%8A.b%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=aerobic&lang=en-US&ipa=%2Fe%CB%88ro%CA%8A.b%C9%AAk%2F"},{"id":"lv_8_4","topic":"Food and Health","word":"ambassador","pos":"(n)","ipa":"/æmˈbæs.ə.dɚ/","defVi":"đại sứ","defEn":"an official representative of a country residing in another country","examples":["The French [ambassador] met with government officials to discuss trade agreements. (=Dịch: Đại sứ Pháp đã gặp các quan chức chính phủ để thảo luận về các hiệp định thương mại.)","She was appointed as a goodwill [ambassador] for the global charity. (=Dịch: Cô được bổ nhiệm làm đại sứ thiện chí cho tổ chức từ thiện toàn cầu.)","The new [ambassador] presented his credentials to the president yesterday. (=Dịch: Vị tân đại sứ đã trình quốc thư lên tổng thống vào ngày hôm qua.)"],"ukAudio":"/ai_services/tts3/?q=ambassador&lang=en-GB&ipa=%2F%C3%A6m%CB%88b%C3%A6s.%C9%99.d%C9%9A%2F","usAudio":"/ai_services/tts3/?q=ambassador&lang=en-US&ipa=%2F%C3%A6m%CB%88b%C3%A6s.%C9%99.d%C9%9A%2F"},{"id":"lv_8_5","topic":"Food and Health","word":"artificial","pos":"(adj)","ipa":"/ˌɑːr.t̬əˈfɪʃ.əl/","defVi":"nhân tạo","defEn":"made or produced by humans rather than occurring naturally.","examples":["This beverage contains no [artificial] colors or flavors. (=Dịch: Đồ uống này không chứa phẩm màu hoặc hương liệu nhân tạo.)","The match was played on a field with [artificial] grass. (=Dịch: Trận đấu được diễn ra trên sân cỏ nhân tạo.)","Scientists are developing [artificial] organs to save patients. (=Dịch: Các nhà khoa học đang phát triển các cơ quan nhân tạo để cứu sống bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=artificial&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90r.t%CC%AC%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=artificial&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90r.t%CC%AC%C9%99%CB%88f%C9%AA%CA%83.%C9%99l%2F"},{"id":"lv_8_6","topic":"Food and Health","word":"avocado","pos":"(n)","ipa":"/ˌæv.əˈkɑː.doʊ/","defVi":"quả bơ","defEn":"a tropical fruit with green skin, soft oily flesh, and a large seed.","examples":["She smashed an [avocado] on whole-grain toast for breakfast. (=Dịch: Cô ấy nghiền một quả bơ lên bánh mì nguyên cám cho bữa sáng.)","An [avocado] is rich in healthy fats and essential nutrients. (=Dịch: Quả bơ rất giàu chất béo lành mạnh và các chất dinh dưỡng thiết yếu.)","He added fresh slices of [avocado] to his chicken salad. (=Dịch: Anh ấy đã thêm vài lát bơ tươi vào món salad gà của mình.)"],"ukAudio":"/ai_services/tts3/?q=avocado&lang=en-GB&ipa=%2F%CB%8C%C3%A6v.%C9%99%CB%88k%C9%91%CB%90.do%CA%8A%2F","usAudio":"/ai_services/tts3/?q=avocado&lang=en-US&ipa=%2F%CB%8C%C3%A6v.%C9%99%CB%88k%C9%91%CB%90.do%CA%8A%2F"},{"id":"lv_8_7","topic":"Food and Health","word":"balanced","pos":"(adj)","ipa":"/ˈbæl.ənst/","defVi":"cân bằng, cân đối","defEn":"containing a healthy mixture of different types of things.","examples":["A [balanced] diet is essential for maintaining good physical health. (=Dịch: Một chế độ ăn uống cân bằng là điều cần thiết để duy trì sức khỏe thể chất tốt.)","She tries to lead a [balanced] life between work and family. (=Dịch: Cô ấy cố gắng duy trì một cuộc sống cân bằng giữa công việc và gia đình.)","The report provided a fair and [balanced] view of the issue. (=Dịch: Bản báo cáo đã đưa ra một cái nhìn công bằng và cân bằng về vấn đề này.)"],"ukAudio":"/ai_services/tts3/?q=balanced&lang=en-GB&ipa=%2F%CB%88b%C3%A6l.%C9%99nst%2F","usAudio":"/ai_services/tts3/?q=balanced&lang=en-US&ipa=%2F%CB%88b%C3%A6l.%C9%99nst%2F"},{"id":"lv_8_8","topic":"Food and Health","word":"bark","pos":"(n)","ipa":"/bɑrk/","defVi":"vỏ cây","defEn":"the tough outer covering of the trunk and branches of a tree","examples":["Cinnamon is a spice made from the inner [bark] of certain trees. (=Dịch: Quế là một loại gia vị được làm từ lớp vỏ bên trong của một số loài cây.)","The rough [bark] protects the tree from harsh weather and insects. (=Dịch: Lớp vỏ cây sần sùi bảo vệ cây khỏi thời tiết khắc nghiệt và côn trùng.)","Indigenous people used birch [bark] to construct lightweight canoes. (=Dịch: Người bản địa đã sử dụng vỏ cây bạch dương để đóng những chiếc thuyền nan nhẹ.)"],"ukAudio":"/ai_services/tts3/?q=bark&lang=en-GB&ipa=%2Fb%C9%91rk%2F","usAudio":"/ai_services/tts3/?q=bark&lang=en-US&ipa=%2Fb%C9%91rk%2F"},{"id":"lv_8_9","topic":"Food and Health","word":"beneficial","pos":"(adj)","ipa":"/ˌben.əˈfɪʃ.l/","defVi":"có lợi, có ích","defEn":"having a good or helpful effect on someone or something","examples":["Regular aerobic exercise is extremely [beneficial] for cardiovascular health. (=Dịch: Tập thể dục nhịp điệu thường xuyên cực kỳ có lợi cho sức khỏe tim mạch.)","Good communication skills are [beneficial] in any professional career. (=Dịch: Kỹ năng giao tiếp tốt rất có ích trong bất kỳ sự nghiệp chuyên môn nào.)","The new tax policy will be [beneficial] to small business owners. (=Dịch: Chính sách thuế mới sẽ có lợi cho các chủ doanh nghiệp nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=beneficial&lang=en-GB&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.l%2F","usAudio":"/ai_services/tts3/?q=beneficial&lang=en-US&ipa=%2F%CB%8Cben.%C9%99%CB%88f%C9%AA%CA%83.l%2F"},{"id":"lv_8_10","topic":"Food and Health","word":"brand","pos":"(n)","ipa":"/brænd/","defVi":"thương hiệu, nhãn hiệu","defEn":"a type of product made by a particular company under a particular name","examples":["This luxury fashion [brand] is famous for its leather handbags. (=Dịch: Thương hiệu thời trang cao cấp này nổi tiếng với những chiếc túi xách da.)","Consumers often trust a well-known [brand] more than an unfamiliar one. (=Dịch: Người tiêu dùng thường tin tưởng một thương hiệu nổi tiếng hơn một thương hiệu xa lạ.)","The company spent millions of dollars to build a strong [brand] image. (=Dịch: Công ty đã chi hàng triệu đô la để xây dựng một hình ảnh thương hiệu vững mạnh.)"],"ukAudio":"/ai_services/tts3/?q=brand&lang=en-GB&ipa=%2Fbr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=brand&lang=en-US&ipa=%2Fbr%C3%A6nd%2F"},{"id":"lv_8_11","topic":"Food and Health","word":"bulb","pos":"(n)","ipa":"/bʌlb/","defVi":"bóng đèn","defEn":"a glass device that produces light from electricity","examples":["He stood on a chair to replace the burned-out light [bulb]. (=Dịch: Anh ấy đứng lên một chiếc ghế để thay bóng đèn đã bị cháy.)","Using an energy-saving LED [bulb] helps lower household electricity bills. (=Dịch: Sử dụng bóng đèn LED tiết kiệm năng lượng giúp giảm hóa đơn tiền điện sinh hoạt.)","The lamp needs a forty-watt [bulb] to illuminate the entire desk. (=Dịch: Chiếc đèn bàn cần một bóng đèn 40 oát để chiếu sáng toàn bộ bàn làm việc.)"],"ukAudio":"/ai_services/tts3/?q=bulb&lang=en-GB&ipa=%2Fb%CA%8Clb%2F","usAudio":"/ai_services/tts3/?q=bulb&lang=en-US&ipa=%2Fb%CA%8Clb%2F"},{"id":"lv_8_12","topic":"Food and Health","word":"cage","pos":"(n)","ipa":"/keɪdʒ/","defVi":"lồng, chuồng","defEn":"a structure of bars or wires in which birds or animals are kept","examples":["The parrot sat quietly on a wooden perch inside its metal [cage]. (=Dịch: Con vẹt ngồi yên lặng trên một thanh gỗ bên trong chiếc lồng kim loại.)","Animal welfare activists campaigned against keeping wild animals in a small [cage]. (=Dịch: Các nhà hoạt động vì quyền động vật đã vận động chống lại việc nhốt động vật hoang dã trong chuồng nhỏ.)","The zoo keeper carefully cleaned the lion's [cage] every morning. (=Dịch: Người quản thú cẩn thận dọn dẹp chuồng sư tử vào mỗi buổi sáng.)"],"ukAudio":"/ai_services/tts3/?q=cage&lang=en-GB&ipa=%2Fke%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=cage&lang=en-US&ipa=%2Fke%C9%AAd%CA%92%2F"},{"id":"lv_8_13","topic":"Food and Health","word":"calorie","pos":"(n)","ipa":"/ˈkæl.ɚ.i/","defVi":"calo (đơn vị đo năng lượng)","defEn":"a unit used to measure the energy value of food.","examples":["You can reduce your daily [calorie] intake by avoiding sugary drinks. (=Dịch: Bạn có thể giảm lượng calo nạp vào hàng ngày bằng cách tránh đồ uống có đường.)","Running burns more [calorie] units than walking at a casual pace. (=Dịch: Chạy bộ đốt cháy nhiều calo hơn là đi bộ với tốc độ bình thường.)","Food labels show the total [calorie] count per serving. (=Dịch: Nhãn thực phẩm hiển thị tổng lượng calo trên mỗi khẩu phần ăn.)"],"ukAudio":"/ai_services/tts3/?q=calorie&lang=en-GB&ipa=%2F%CB%88k%C3%A6l.%C9%9A.i%2F","usAudio":"/ai_services/tts3/?q=calorie&lang=en-US&ipa=%2F%CB%88k%C3%A6l.%C9%9A.i%2F"},{"id":"lv_8_14","topic":"Food and Health","word":"canada","pos":"(n)","ipa":"/ˈkæn.ə.də/","defVi":"nước Ca-na-đa (Canada)","defEn":"a large country in northern North America.","examples":["Many international students choose to study in [Canada] each year. (=Dịch: Nhiều du học sinh quốc tế chọn học tập tại Canada mỗi năm.)","Winter in [Canada] can be extremely cold with heavy snowfall. (=Dịch: Mùa đông ở Canada có thể vô cùng lạnh giá với tuyết rơi dày đặc.)","She traveled across [Canada] by train to enjoy the scenery. (=Dịch: Cô ấy đã đi du lịch xuyên Canada bằng tàu hỏa để thưởng ngoạn phong cảnh.)"],"ukAudio":"/ai_services/tts3/?q=canada&lang=en-GB&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F","usAudio":"/ai_services/tts3/?q=canada&lang=en-US&ipa=%2F%CB%88k%C3%A6n.%C9%99.d%C9%99%2F"},{"id":"lv_8_15","topic":"Food and Health","word":"cap","pos":"(n)","ipa":"/kæp/","defVi":"mũ lưỡi trai, giới hạn","defEn":"A soft, flat hat with a curved part at the front, or a limit placed on something.","examples":["He wore a baseball [cap] to shield his eyes from the harsh sunlight. (=Dịch: Anh ấy đội một chiếc mũ lưỡi trai để che mắt khỏi ánh nắng chói chang.)","The government placed a strict [cap] on greenhouse gas emissions. (=Dịch: Chính phủ đã áp đặt một mức trần giới hạn nghiêm ngặt đối với lượng khí thải nhà kính.)","Don't forget to put the [cap] back on the bottle to prevent spills. (=Dịch: Đừng quên đậy nắp chai lại để tránh bị đổ.)"],"ukAudio":"/ai_services/tts3/?q=cap&lang=en-GB&ipa=%2Fk%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=cap&lang=en-US&ipa=%2Fk%C3%A6p%2F"},{"id":"lv_8_16","topic":"Food and Health","word":"carbohydrate","pos":"(n)","ipa":"/ˌkɑːr.boʊˈhaɪ.dreɪt/","defVi":"chất bột đường, tinh bột","defEn":"A substance in foods such as bread, rice, and potatoes that provides the body with heat and energy.","examples":["Athletes often consume foods rich in [carbohydrate] before running a marathon. (=Dịch: Các vận động viên thường tiêu thụ thực phẩm giàu tinh bột trước khi chạy marathon.)","Reducing your refined [carbohydrate] intake can help regulate blood sugar levels. (=Dịch: Giảm lượng tinh bột tinh chế có thể giúp điều hòa lượng đường trong máu.)","Rice, pasta, and potatoes are primary sources of [carbohydrate] in many diets. (=Dịch: Gạo, mì ống và khoai tây là những nguồn cung cấp carbohydrate chính trong nhiều chế độ ăn.)"],"ukAudio":"/ai_services/tts3/?q=carbohydrate&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90r.bo%CA%8A%CB%88ha%C9%AA.dre%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=carbohydrate&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90r.bo%CA%8A%CB%88ha%C9%AA.dre%C9%AAt%2F"},{"id":"lv_8_17","topic":"Food and Health","word":"cereal","pos":"(n)","ipa":"/ˈsɪr.i.əl/","defVi":"ngũ cốc","defEn":"a grain used for food, or a breakfast food made from processed grains","examples":["He usually has a bowl of [cereal] with milk for breakfast. (=Dịch: Anh ấy thường ăn một bát ngũ cốc với sữa cho bữa sáng.)","Wheat and rice are among the most widely grown [cereal] crops in the world. (=Dịch: Lúa mì và lúa gạo là một trong những loại cây ngũ cốc được trồng rộng rãi nhất trên thế giới.)","Children often prefer sweetened [cereal] over plain oatmeal. (=Dịch: Trẻ em thường thích ngũ cốc có đường hơn yến mạch nguyên chất.)"],"ukAudio":"/ai_services/tts3/?q=cereal&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=cereal&lang=en-US&ipa=%2F%CB%88s%C9%AAr.i.%C9%99l%2F"},{"id":"lv_8_18","topic":"Food and Health","word":"chamber","pos":"(n)","ipa":"/ˈtʃeɪm.bɚ/","defVi":"phòng lớn, viện (nghị viện), hoặc khoang/buồng chứa","defEn":"a large room used for official meetings, or an enclosed space or cavity in a machine or organism","examples":["The senators gathered inside the council [chamber] to cast their final votes. (=Dịch: Các thượng nghị sĩ đã tập trung bên trong phòng hội đồng để bỏ những lá phiếu cuối cùng.)","Blood flows through each [chamber] of the heart in a specific sequence. (=Dịch: Máu chảy qua từng ngăn của tim theo một trình tự nhất định.)","Archaeologists discovered a hidden burial [chamber] deep within the ancient tomb. (=Dịch: Các nhà khảo cổ đã phát hiện một gian phòng chôn cất bí mật sâu bên trong lăng mộ cổ.)"],"ukAudio":"/ai_services/tts3/?q=chamber&lang=en-GB&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chamber&lang=en-US&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F"},{"id":"lv_8_19","topic":"Food and Health","word":"commercially","pos":"(adv)","ipa":"/kəˈmɝː.ʃəl.i/","defVi":"về mặt thương mại, trên quy mô thương mại","defEn":"in a way that relates to business, trade, or the making of a profit","examples":["The new drug will soon be [commercially] available in local pharmacies. (=Dịch: Loại thuốc mới sẽ sớm được bán trên thị trường tại các hiệu thuốc địa phương.)","Although critically acclaimed, the movie was not [commercially] successful. (=Dịch: Dù được giới phê bình đánh giá cao, bộ phim lại không thành công về mặt thương mại.)","The company decided to produce the solar panels [commercially] to reduce costs. (=Dịch: Công ty đã quyết định sản xuất các tấm pin mặt trời trên quy mô thương mại để giảm chi phí.)"],"ukAudio":"/ai_services/tts3/?q=commercially&lang=en-GB&ipa=%2Fk%C9%99%CB%88m%C9%9D%CB%90.%CA%83%C9%99l.i%2F","usAudio":"/ai_services/tts3/?q=commercially&lang=en-US&ipa=%2Fk%C9%99%CB%88m%C9%9D%CB%90.%CA%83%C9%99l.i%2F"},{"id":"lv_8_20","topic":"Food and Health","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or company that tries to do better than others in a contest or business","examples":["The company lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty đã hạ giá để luôn dẫn trước đối thủ cạnh tranh chính của mình.)","Each [competitor] in the marathon was given a tracking chip. (=Dịch: Mỗi đấu thủ trong cuộc chạy marathon đều được gắn một con chip theo dõi.)","They analyzed how their [competitor] was marketing the new smartphone. (=Dịch: Họ đã phân tích cách đối thủ cạnh tranh tiếp thị chiếc điện thoại thông minh mới.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_8_21","topic":"Food and Health","word":"consumer","pos":"(n)","ipa":"/kənˈsuː.mɚ/","defVi":"người tiêu dùng","defEn":"a person who purchases goods and services for personal use","examples":["Rising fuel prices directly impact [consumer] spending across the country. (=Dịch: Giá nhiên liệu tăng ảnh hưởng trực tiếp đến mức chi tiêu của người tiêu dùng trên toàn quốc.)","The agency works to protect [consumer] rights against deceptive advertising. (=Dịch: Cơ quan này hoạt động nhằm bảo vệ quyền lợi người tiêu dùng trước các quảng cáo lừa đảo.)","Modern [consumer] habits have shifted significantly toward online shopping. (=Dịch: Thói quen của người tiêu dùng hiện đại đã chuyển dịch đáng kể sang mua sắm trực tuyến.)"],"ukAudio":"/ai_services/tts3/?q=consumer&lang=en-GB&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A%2F","usAudio":"/ai_services/tts3/?q=consumer&lang=en-US&ipa=%2Fk%C9%99n%CB%88su%CB%90.m%C9%9A%2F"},{"id":"lv_8_22","topic":"Food and Health","word":"crisp","pos":"(n)","ipa":"/krɪsp/","defVi":"lát chiên giòn, miếng khoai tây chiên giòn","defEn":"a thin, dry, and crunchy slice of food, especially a potato chip","examples":["She grabbed a potato [crisp] from the bowl on the table. (=Dịch: Cô ấy lấy một miếng khoai tây chiên giòn từ cái bát trên bàn.)","Each [crisp] was seasoned evenly with sea salt and black pepper. (=Dịch: Mỗi lát khoai tây giòn đều được nêm đều với muối biển và tiêu đen.)","I prefer eating a vegetable [crisp] instead of regular fried snacks. (=Dịch: Tôi thích ăn một lát rau củ sấy giòn hơn là các món ăn vặt chiên thông thường.)"],"ukAudio":"/ai_services/tts3/?q=crisp&lang=en-GB&ipa=%2Fkr%C9%AAsp%2F","usAudio":"/ai_services/tts3/?q=crisp&lang=en-US&ipa=%2Fkr%C9%AAsp%2F"},{"id":"lv_8_23","topic":"Food and Health","word":"detect","pos":"(v)","ipa":"/dɪˈtɛkt/","defVi":"phát hiện, nhận ra, dò ra","defEn":"to discover or notice the presence of something, especially something difficult to see or hear","examples":["The medical test can [detect] the disease in its early stages. (=Dịch: Xét nghiệm y tế có thể phát hiện bệnh ở giai đoạn đầu.)","Smoke alarms are designed to [detect] fires before they spread. (=Dịch: Thiết bị báo khói được thiết kế để phát hiện đám cháy trước khi chúng lan rộng.)","Scientists used special instruments to [detect] tiny sound waves. (=Dịch: Các nhà khoa học đã sử dụng các dụng cụ đặc biệt để phát hiện các sóng âm thanh nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=detect&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=detect&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9Bkt%2F"},{"id":"lv_8_24","topic":"Food and Health","word":"drill","pos":"(n)","ipa":"/drɪl/","defVi":"máy khoan, mũi khoan; hoặc bài tập rèn luyện/diễn tập","defEn":"a tool or machine with a rotating cutting tip used for making holes, or an intensive training exercise","examples":["He used an electric [drill] to fix the bookshelf securely to the wall. (=Dịch: Anh ấy đã dùng một chiếc máy khoan điện để cố định giá sách vào tường một cách chắc chắn.)","The school conducts a mandatory fire [drill] at the beginning of each semester. (=Dịch: Trường học tổ chức một buổi diễn tập phòng cháy chữa cháy bắt buộc vào đầu mỗi học kỳ.)","The dentist picked up the high-speed [drill] to treat the patient's cavity. (=Dịch: Nha sĩ đã cầm chiếc máy khoan tốc độ cao để điều trị lỗ sâu răng cho bệnh nhân.)"],"ukAudio":"/ai_services/tts3/?q=drill&lang=en-GB&ipa=%2Fdr%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=drill&lang=en-US&ipa=%2Fdr%C9%AAl%2F"},{"id":"lv_8_25","topic":"Food and Health","word":"equal","pos":"(adj)","ipa":"/ˈiː.kwəl/","defVi":"bình đẳng, ngang bằng, như nhau","defEn":"the same in size, amount, value, or status.","examples":["Both candidates have an [equal] chance of winning the election. (=Dịch: Cả hai ứng cử viên đều có cơ hội chiến thắng như nhau trong cuộc bầu cử.)","Men and women should receive [equal] pay for doing the same job. (=Dịch: Nam và nữ nên nhận mức lương bình đẳng khi làm cùng một công việc.)","Please divide the cake into six [equal] pieces. (=Dịch: Làm ơn hãy chia chiếc bánh thành sáu phần bằng nhau.)"],"ukAudio":"/ai_services/tts3/?q=equal&lang=en-GB&ipa=%2F%CB%88i%CB%90.kw%C9%99l%2F","usAudio":"/ai_services/tts3/?q=equal&lang=en-US&ipa=%2F%CB%88i%CB%90.kw%C9%99l%2F"},{"id":"lv_8_26","topic":"Food and Health","word":"ethical","pos":"(adj)","ipa":"/ˈeθ.ɪ.kəl/","defVi":"thuộc về đạo đức, hợp luân thường đạo lý","defEn":"relating to moral principles or conforming to accepted standards of right and wrong","examples":["The company introduced strict [ethical] guidelines to prevent unfair trade practices. (=Dịch: Công ty đã đưa ra các nguyên tắc đạo đức nghiêm ngặt nhằm ngăn chặn các hành vi thương mại không công bằng.)","Many people choose a plant-based diet for [ethical] reasons regarding animal welfare. (=Dịch: Nhiều người chọn chế độ ăn thuần thực vật vì lý do đạo đức liên quan đến quyền lợi động vật.)","Scientists face difficult [ethical] questions when conducting genetic research on humans. (=Dịch: Các nhà khoa học phải đối mặt với những câu hỏi đạo đức khó khăn khi tiến hành nghiên cứu di truyền trên người.)"],"ukAudio":"/ai_services/tts3/?q=ethical&lang=en-GB&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=ethical&lang=en-US&ipa=%2F%CB%88e%CE%B8.%C9%AA.k%C9%99l%2F"},{"id":"lv_8_27","topic":"Food and Health","word":"evaporate","pos":"(v)","ipa":"/ɪˈvæp.ə.reɪt/","defVi":"bốc hơi, bay hơi; tan biến","defEn":"to change from a liquid into a gas or vapor; to disappear completely","examples":["Puddles on the pavement quickly [evaporate] under the blazing afternoon sun. (=Dịch: Những vũng nước trên vỉa hè nhanh chóng bốc hơi dưới ánh nắng chói chang của buổi chiều.)","All of his initial confidence began to [evaporate] as the interview started. (=Dịch: Tất cả sự tự tin ban đầu của anh ấy bắt đầu tan biến khi buổi phỏng vấn bắt đầu.)","Boiling water will slowly [evaporate] if left uncovered on the stove. (=Dịch: Nước sôi sẽ từ từ bay hơi nếu để mở nắp trên bếp.)"],"ukAudio":"/ai_services/tts3/?q=evaporate&lang=en-GB&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=evaporate&lang=en-US&ipa=%2F%C9%AA%CB%88v%C3%A6p.%C9%99.re%C9%AAt%2F"},{"id":"lv_8_28","topic":"Food and Health","word":"fashionable","pos":"(adj)","ipa":"/ˈfæʃ.ə.nə.bəl/","defVi":"hợp thời trang, thịnh hành","defEn":"Popular at a particular time, especially in clothes, style, or behavior.","examples":["She wore a [fashionable] dress to the annual company banquet. (=Dịch: Cô ấy đã mặc một chiếc váy rất hợp thời trang đến bữa tiệc thường niên của công ty.)","It has become [fashionable] to adopt a plant-based diet among young professionals. (=Dịch: Áp dụng chế độ ăn thuần thực vật đã trở nên thịnh hành trong giới trẻ đi làm.)","The city center is full of [fashionable] cafes and boutiques. (=Dịch: Trung tâm thành phố có rất nhiều quán cà phê và cửa hàng thời thượng.)"],"ukAudio":"/ai_services/tts3/?q=fashionable&lang=en-GB&ipa=%2F%CB%88f%C3%A6%CA%83.%C9%99.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=fashionable&lang=en-US&ipa=%2F%CB%88f%C3%A6%CA%83.%C9%99.n%C9%99.b%C9%99l%2F"},{"id":"lv_8_29","topic":"Food and Health","word":"fifth","pos":"(adj)","ipa":"/fɪfθ/","defVi":"thứ năm (trong thứ tự)","defEn":"coming immediately after the fourth in order or position","examples":["She celebrated her [fifth] anniversary as manager of the marketing department. (=Dịch: Cô ấy đã kỷ niệm năm thứ năm làm việc với tư cách là người quản lý bộ phận tiếp thị.)","Our team finished in [fifth] place during the national science competition. (=Dịch: Đội của chúng tôi đã về đích ở vị trí thứ năm trong cuộc thi khoa học toàn quốc.)","His office is located on the [fifth] floor of the administrative building. (=Dịch: Văn phòng của ông ấy nằm ở tầng năm của tòa nhà hành chính.)"],"ukAudio":"/ai_services/tts3/?q=fifth&lang=en-GB&ipa=%2Ff%C9%AAf%CE%B8%2F","usAudio":"/ai_services/tts3/?q=fifth&lang=en-US&ipa=%2Ff%C9%AAf%CE%B8%2F"},{"id":"lv_8_30","topic":"Food and Health","word":"flag","pos":"(n)","ipa":"/flæɡ/","defVi":"lá cờ, cờ hiệu","defEn":"a piece of cloth with a distinctive design used as a symbol, banner, or signaling device","examples":["The national [flag] was raised high at sunrise in front of the government building. (=Dịch: Quốc kỳ đã được kéo lên cao lúc bình minh trước tòa nhà chính phủ.)","Athletes proudly carried their country's [flag] during the opening ceremony. (=Dịch: Các vận động viên tự hào mang theo lá cờ của đất nước mình trong lễ khai mạc.)","A yellow [flag] on the beach warns swimmers of dangerous water conditions. (=Dịch: Lá cờ màu vàng trên bãi biển cảnh báo người bơi về điều kiện sóng nước nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=flag&lang=en-GB&ipa=%2Ffl%C3%A6%C9%A1%2F","usAudio":"/ai_services/tts3/?q=flag&lang=en-US&ipa=%2Ffl%C3%A6%C9%A1%2F"},{"id":"lv_8_31","topic":"Food and Health","word":"flavour","pos":"(n)","ipa":"/ˈfleɪ.vɚ/","defVi":"hương vị, mùi vị","defEn":"the distinctive taste of a food or drink, often combined with its smell","examples":["Adding fresh basil gives the homemade tomato sauce a delightful [flavour]. (=Dịch: Thêm húng quế tươi mang lại cho món sốt cà chua tự làm một hương vị thơm ngon tuyệt vời.)","The ice cream shop offers over twenty different [flavour] varieties including matcha and mint. (=Dịch: Quán kem cung cấp hơn hai mươi loại hương vị khác nhau bao gồm cả matcha và bạc hà.)","Slow cooking helps to lock in all the natural [flavour] of the meat and vegetables. (=Dịch: Nấu chậm giúp giữ lại toàn bộ hương vị tự nhiên của thịt và rau củ.)"],"ukAudio":"/ai_services/tts3/?q=flavour&lang=en-GB&ipa=%2F%CB%88fle%C9%AA.v%C9%9A%2F","usAudio":"/ai_services/tts3/?q=flavour&lang=en-US&ipa=%2F%CB%88fle%C9%AA.v%C9%9A%2F"},{"id":"lv_8_32","topic":"Food and Health","word":"genetic","pos":"(adj)","ipa":"/dʒəˈnet̬.ɪk/","defVi":"thuộc di truyền, thuộc gen","defEn":"Relating to the biological process of passing characteristics from parents to their children through genes.","examples":["Scientists are studying the [genetic] factors that cause certain diseases. (=Dịch: Các nhà khoa học đang nghiên cứu các yếu tố di truyền gây ra một số bệnh nhất định.)","Eye color is a [genetic] trait passed down from parents to offspring. (=Dịch: Màu mắt là một đặc điểm di truyền được truyền từ cha mẹ sang con cái.)","The research team made a breakthrough in identifying the [genetic] code of the rare plant. (=Dịch: Nhóm nghiên cứu đã tạo ra bước đột phá trong việc xác định mã di truyền của loài thực vật quý hiếm.)"],"ukAudio":"/ai_services/tts3/?q=genetic&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=genetic&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88net%CC%AC.%C9%AAk%2F"},{"id":"lv_8_33","topic":"Food and Health","word":"ghost","pos":"(n)","ipa":"/ɡoʊst/","defVi":"con ma, bóng ma, linh hồn","defEn":"the spirit of a dead person that a living person believes they can see or hear","examples":["The children told scary stories about a [ghost] living in the old house. (=Dịch: Lũ trẻ đã kể những câu chuyện đáng sợ về một con ma sống trong ngôi nhà cổ.)","Visitors claim that the ancient castle is haunted by the [ghost] of a king. (=Dịch: Du khách khẳng định rằng lâu đài cổ kính bị ám bởi bóng ma của một vị vua.)","He looked as pale as if he had just seen a [ghost]. (=Dịch: Anh ấy trông tái nhợt như thể vừa nhìn thấy một bóng ma.)"],"ukAudio":"/ai_services/tts3/?q=ghost&lang=en-GB&ipa=%2F%C9%A1o%CA%8Ast%2F","usAudio":"/ai_services/tts3/?q=ghost&lang=en-US&ipa=%2F%C9%A1o%CA%8Ast%2F"},{"id":"lv_8_34","topic":"Food and Health","word":"heated","pos":"(adj)","ipa":"/ˈhiː.t̬ɪd/","defVi":"được đun nóng; (cuộc tranh luận) sôi nổi, nảy lửa, gay gắt","defEn":"made warm or hot; (of an argument or discussion) full of anger and strong emotion","examples":["The committee engaged in a [heated] debate over how to allocate the annual budget. (=Dịch: Ủy ban đã tham gia vào một cuộc tranh luận gay gắt về cách phân bổ ngân sách hàng năm.)","The luxury hotel features an outdoor [heated] pool that guests can use during the winter. (=Dịch: Khách sạn sang trọng này có một bể bơi nước nóng ngoài trời mà du khách có thể sử dụng vào mùa đông.)","What began as a calm conversation quickly turned into a [heated] exchange between the rivals. (=Dịch: Những gì bắt đầu như một cuộc trò chuyện êm đẹp đã nhanh chóng biến thành màn đôi co nảy lửa giữa hai đối thủ.)"],"ukAudio":"/ai_services/tts3/?q=heated&lang=en-GB&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=heated&lang=en-US&ipa=%2F%CB%88hi%CB%90.t%CC%AC%C9%AAd%2F"},{"id":"lv_8_35","topic":"Food and Health","word":"hormone","pos":"(n)","ipa":"/ˈhɔːr.moʊn/","defVi":"nội tiết tố, hoóc-môn","defEn":"a chemical substance produced in the body that controls certain processes","examples":["Insulin is an essential [hormone] that regulates blood sugar levels. (=Dịch: Insulin là một hoóc-môn thiết yếu giúp điều hòa lượng đường trong máu.)","Adrenaline is a [hormone] released when a person experiences fear or excitement. (=Dịch: Adrenaline là một nội tiết tố được tiết ra khi một người cảm thấy sợ hãi hoặc phấn khích.)","An imbalance of any [hormone] can affect your mood and energy. (=Dịch: Sự mất cân bằng của bất kỳ hoóc-môn nào cũng có thể ảnh hưởng đến tâm trạng và năng lượng của bạn.)"],"ukAudio":"/ai_services/tts3/?q=hormone&lang=en-GB&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=hormone&lang=en-US&ipa=%2F%CB%88h%C9%94%CB%90r.mo%CA%8An%2F"},{"id":"lv_8_36","topic":"Food and Health","word":"importantly","pos":"(adv)","ipa":"/ɪmˈpɔːr.tənt.li/","defVi":"quan trọng là, một cách quan trọng","defEn":"used to emphasize a significant point or fact","examples":["The new system is faster and, more [importantly], much more secure. (=Dịch: Hệ thống mới nhanh hơn và quan trọng hơn là bảo mật hơn nhiều.)","She has the required skills and, most [importantly], a great attitude. (=Dịch: Cô ấy có những kỹ năng cần thiết và quan trọng nhất là một thái độ tuyệt vời.)","Eating well and, [importantly], exercising regularly will keep you healthy. (=Dịch: Ăn uống đầy đủ và quan trọng là tập thể dục thường xuyên sẽ giúp bạn khỏe mạnh.)"],"ukAudio":"/ai_services/tts3/?q=importantly&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F","usAudio":"/ai_services/tts3/?q=importantly&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F"},{"id":"lv_8_37","topic":"Food and Health","word":"incorrect","pos":"(adj)","ipa":"/ˌɪn.kəˈrɛkt/","defVi":"sai, không chính xác","defEn":"not true or accurate; having mistakes","examples":["The report contained some [incorrect] statistics that need to be fixed. (=Dịch: Báo cáo có chứa một số số liệu thống kê không chính xác cần phải sửa lại.)","He gave an [incorrect] answer during the job interview. (=Dịch: Anh ấy đã đưa ra một câu trả lời sai trong buổi phỏng vấn xin việc.)","The system showed an error message due to an [incorrect] password. (=Dịch: Hệ thống đã hiển thị thông báo lỗi do mật khẩu không đúng.)"],"ukAudio":"/ai_services/tts3/?q=incorrect&lang=en-GB&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F","usAudio":"/ai_services/tts3/?q=incorrect&lang=en-US&ipa=%2F%CB%8C%C9%AAn.k%C9%99%CB%88r%C9%9Bkt%2F"},{"id":"lv_8_38","topic":"Food and Health","word":"influencer","pos":"(n)","ipa":"/ˈɪn.flu.ən.sɚ/","defVi":"người có sức ảnh hưởng (trên mạng xã hội)","defEn":"a person who has the power to affect the purchasing decisions or opinions of others on social media","examples":["The brand partnered with a popular fashion [influencer] to promote their new line. (=Dịch: Thương hiệu đã hợp tác với một người có sức ảnh hưởng nổi tiếng về thời trang để quảng bá dòng sản phẩm mới của họ.)","Many young people aspire to become a social media [influencer]. (=Dịch: Nhiều người trẻ khao khát trở thành một người có sức ảnh hưởng trên mạng xã hội.)","She works as a travel [influencer] and shares videos from around the world. (=Dịch: Cô ấy làm công việc của một người có ảnh hưởng trong lĩnh vực du lịch và chia sẻ các video từ khắp nơi trên thế giới.)"],"ukAudio":"/ai_services/tts3/?q=influencer&lang=en-GB&ipa=%2F%CB%88%C9%AAn.flu.%C9%99n.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=influencer&lang=en-US&ipa=%2F%CB%88%C9%AAn.flu.%C9%99n.s%C9%9A%2F"},{"id":"lv_8_39","topic":"Food and Health","word":"ingredient","pos":"(n)","ipa":"/ɪnˈɡriː.di.ənt/","defVi":"nguyên liệu, thành phần","defEn":"one of the foods or substances that are used to make a particular dish","examples":["Fresh basil is a key [ingredient] in making authentic pesto sauce. (=Dịch: Húng quế tươi là một nguyên liệu chính để làm sốt pesto chuẩn vị.)","Always check the [ingredient] list on the label before buying packaged foods. (=Dịch: Luôn kiểm tra danh sách thành phần trên nhãn trước khi mua thực phẩm đóng gói.)","Hard work and dedication are essential [ingredient] elements for achieving success. (=Dịch: Chăm chỉ và tận tụy là những yếu tố thành phần thiết yếu để đạt được thành công.)"],"ukAudio":"/ai_services/tts3/?q=ingredient&lang=en-GB&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=ingredient&lang=en-US&ipa=%2F%C9%AAn%CB%88%C9%A1ri%CB%90.di.%C9%99nt%2F"},{"id":"lv_8_40","topic":"Food and Health","word":"intake","pos":"(n)","ipa":"/ˈɪn.teɪk/","defVi":"lượng hấp thụ, lượng nạp vào","defEn":"The amount of a particular substance that you eat, drink, or breathe in.","examples":["Doctors advise reducing your daily salt [intake] to maintain healthy blood pressure. (=Dịch: Các bác sĩ khuyên bạn nên giảm lượng muối nạp vào hàng ngày để duy trì huyết áp ổn định.)","A high fluid [intake] is essential when exercising in hot weather. (=Dịch: Việc nạp nhiều chất lỏng là rất cần thiết khi tập luyện trong thời tiết nóng bức.)","The nutritionist evaluated my total calorie [intake] over the past week. (=Dịch: Chuyên gia dinh dưỡng đã đánh giá tổng lượng calo nạp vào của tôi trong tuần qua.)"],"ukAudio":"/ai_services/tts3/?q=intake&lang=en-GB&ipa=%2F%CB%88%C9%AAn.te%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=intake&lang=en-US&ipa=%2F%CB%88%C9%AAn.te%C9%AAk%2F"},{"id":"lv_8_41","topic":"Food and Health","word":"intense","pos":"(adj)","ipa":"/ɪnˈtɛns/","defVi":"mãnh liệt, dữ dội, gay gắt","defEn":"very great in strength, degree, or emotion","examples":["The athletes trained under [intense] heat before the competition. (=Dịch: Các vận động viên đã tập luyện dưới cái nóng gay gắt trước thềm cuộc thi.)","There is [intense] competition among tech companies to attract top talent. (=Dịch: Có sự cạnh tranh khốc liệt giữa các công ty công nghệ để thu hút nhân tài hàng đầu.)","He felt [intense] pain in his shoulder after lifting the heavy box. (=Dịch: Anh ấy cảm thấy đau nhói ở vai sau khi nâng chiếc hộp nặng.)"],"ukAudio":"/ai_services/tts3/?q=intense&lang=en-GB&ipa=%2F%C9%AAn%CB%88t%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=intense&lang=en-US&ipa=%2F%C9%AAn%CB%88t%C9%9Bns%2F"},{"id":"lv_8_42","topic":"Food and Health","word":"isolation","pos":"(n)","ipa":"/ˌaɪ.səˈleɪ.ʃən/","defVi":"sự cô lập, sự cách ly","defEn":"the state of being separate or alone from others","examples":["Working from home can sometimes cause feelings of loneliness and [isolation]. (=Dịch: Làm việc tại nhà đôi khi có thể gây ra cảm giác cô đơn và bị cô lập.)","The patient was placed in strict [isolation] to prevent the virus from spreading. (=Dịch: Bệnh nhân đã được đưa vào diện cách ly nghiêm ngặt để ngăn chặn virus lây lan.)","The village lived in complete geographical [isolation] during the winter months. (=Dịch: Ngôi làng sống trong sự cô lập hoàn toàn về mặt địa lý trong những tháng mùa đông.)"],"ukAudio":"/ai_services/tts3/?q=isolation&lang=en-GB&ipa=%2F%CB%8Ca%C9%AA.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=isolation&lang=en-US&ipa=%2F%CB%8Ca%C9%AA.s%C9%99%CB%88le%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_8_43","topic":"Food and Health","word":"japan","pos":"(n)","ipa":"/dʒəˈpæn/","defVi":"nước Nhật Bản","defEn":"an island country in East Asia, known for its culture and technology","examples":["Many tourists travel to [japan] in spring to see cherry blossoms. (=Dịch: Nhiều du khách đến Nhật Bản vào mùa xuân để ngắm hoa anh đào.)","She studied advanced robotics at a top university in [japan]. (=Dịch: Cô ấy đã theo học ngành robot tiên tiến tại một trường đại học hàng đầu ở Nhật Bản.)","Public transportation in [japan] is famous for its punctuality. (=Dịch: Giao thông công cộng ở Nhật Bản nổi tiếng vì sự đúng giờ.)"],"ukAudio":"/ai_services/tts3/?q=japan&lang=en-GB&ipa=%2Fd%CA%92%C9%99%CB%88p%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=japan&lang=en-US&ipa=%2Fd%CA%92%C9%99%CB%88p%C3%A6n%2F"},{"id":"lv_8_44","topic":"Food and Health","word":"japanese","pos":"(adj)","ipa":"/ˌdʒæp.əˈniz/","defVi":"(thuộc) Nhật Bản, người Nhật hoặc tiếng Nhật","defEn":"relating to Japan, its people, language, or culture","examples":["She has a keen interest in traditional [Japanese] art and architecture. (=Dịch: Cô ấy rất quan tâm đến nghệ thuật và kiến trúc truyền thống của Nhật Bản.)","Many people enjoy eating [Japanese] food such as sushi and ramen. (=Dịch: Nhiều người thích ăn các món ăn Nhật Bản như sushi và mì ramen.)","He is currently studying the [Japanese] language at university. (=Dịch: Hiện anh ấy đang theo học tiếng Nhật tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=japanese&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C3%A6p.%C9%99%CB%88niz%2F","usAudio":"/ai_services/tts3/?q=japanese&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C3%A6p.%C9%99%CB%88niz%2F"},{"id":"lv_8_45","topic":"Food and Health","word":"journal","pos":"(n)","ipa":"/ˈdʒɝ.nəl/","defVi":"tạp chí chuyên ngành, tập san","defEn":"a newspaper or magazine that deals with a particular subject or professional activity","examples":["The scientific [journal] published the groundbreaking research on climate change. (=Dịch: Tạp chí khoa học đã công bố nghiên cứu mang tính đột phá về biến đổi khí hậu.)","He submitted his article to a peer-reviewed medical [journal]. (=Dịch: Anh ấy đã nộp bài báo của mình cho một tạp chí y khoa có bình duyệt.)","University students frequently consult academic [journals] for their thesis work. (=Dịch: Sinh viên đại học thường xuyên tham khảo các tạp chí học thuật cho luận văn của mình.)"],"ukAudio":"/ai_services/tts3/?q=journal&lang=en-GB&ipa=%2F%CB%88d%CA%92%C9%9D.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=journal&lang=en-US&ipa=%2F%CB%88d%CA%92%C9%9D.n%C9%99l%2F"},{"id":"lv_8_46","topic":"Food and Health","word":"keratin","pos":"(n)","ipa":"/ˈker.ə.t̬ɪn/","defVi":"chất sừng, keratin","defEn":"a tough protein that forms the main component of hair, nails, and outer skin","examples":["Using hair products with [keratin] can help repair damaged strands. (=Dịch: Sử dụng các sản phẩm chăm sóc tóc có chứa keratin có thể giúp phục hồi những sợi tóc hư tổn.)","Human nails and hair are primarily composed of [keratin]. (=Dịch: Móng tay và tóc của con người chủ yếu được cấu tạo từ chất sừng.)","The outer layer of skin contains [keratin] to protect the body from moisture loss. (=Dịch: Lớp ngoài của da chứa keratin để bảo vệ cơ thể khỏi bị mất nước.)"],"ukAudio":"/ai_services/tts3/?q=keratin&lang=en-GB&ipa=%2F%CB%88ker.%C9%99.t%CC%AC%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=keratin&lang=en-US&ipa=%2F%CB%88ker.%C9%99.t%CC%AC%C9%AAn%2F"},{"id":"lv_8_47","topic":"Food and Health","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water turns from a [liquid] into ice at zero degrees Celsius. (=Dịch: Nước chuyển từ thể lỏng sang băng ở không độ C.)","You should drink plenty of [liquid] when you have a high fever. (=Dịch: Bạn nên uống nhiều chất lỏng khi bị sốt cao.)","Keep hazardous chemical [liquid] away from young children. (=Dịch: Để chất lỏng hóa chất nguy hiểm tránh xa tầm tay trẻ nhỏ.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_8_48","topic":"Food and Health","word":"literacy","pos":"(n)","ipa":"/ˈlɪt̬.ɚ.ə.si/","defVi":"sự biết chữ, trình độ hiểu biết","defEn":"the ability to read and write, or knowledge in a particular subject","examples":["The government launched a campaign to improve adult [literacy] in rural areas. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao tỷ lệ biết chữ ở người lớn tại các vùng nông thôn.)","Financial [literacy] is an essential skill for managing personal savings. (=Dịch: Hiểu biết về tài chính là một kỹ năng thiết yếu để quản lý tiền tiết kiệm cá nhân.)","Digital [literacy] has become necessary for finding good jobs today. (=Dịch: Hiểu biết về công nghệ số đã trở nên cần thiết để tìm kiếm việc làm tốt hiện nay.)"],"ukAudio":"/ai_services/tts3/?q=literacy&lang=en-GB&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.si%2F","usAudio":"/ai_services/tts3/?q=literacy&lang=en-US&ipa=%2F%CB%88l%C9%AAt%CC%AC.%C9%9A.%C9%99.si%2F"},{"id":"lv_8_49","topic":"Food and Health","word":"litre","pos":"(n)","ipa":"/ˈli.t̬ɚ/","defVi":"lít (đơn vị đo thể tích)","defEn":"a metric unit of capacity, equal to 1,000 cubic centimeters","examples":["Doctors recommend drinking at least two [litres] of water every day. (=Dịch: Các bác sĩ khuyên nên uống ít nhất hai lít nước mỗi ngày.)","The car's fuel tank can hold up to fifty [litres] of gasoline. (=Dịch: Bình xăng của xe có thể chứa tới năm mươi lít xăng.)","She poured a [litre] of milk into the large mixing bowl. (=Dịch: Cô ấy đổ một lít sữa vào chiếc bát trộn lớn.)"],"ukAudio":"/ai_services/tts3/?q=litre&lang=en-GB&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=litre&lang=en-US&ipa=%2F%CB%88li.t%CC%AC%C9%9A%2F"},{"id":"lv_8_50","topic":"Food and Health","word":"lower","pos":"(v)","ipa":"/ˈloʊ.ər/","defVi":"làm giảm, hạ thấp","defEn":"To reduce something in amount, degree, or value.","examples":["Regular physical exercise can help [lower] your cholesterol levels. (=Dịch: Tập thể dục thường xuyên có thể giúp làm giảm mức cholesterol của bạn.)","The government decided to [lower] taxes to stimulate economic growth. (=Dịch: Chính phủ đã quyết định hạ thuế nhằm thúc đẩy tăng trưởng kinh tế.)","You should [lower] your voice when speaking in the library. (=Dịch: Bạn nên hạ nhỏ giọng khi nói chuyện trong thư viện.)"],"ukAudio":"/ai_services/tts3/?q=lower&lang=en-GB&ipa=%2F%CB%88lo%CA%8A.%C9%99r%2F","usAudio":"/ai_services/tts3/?q=lower&lang=en-US&ipa=%2F%CB%88lo%CA%8A.%C9%99r%2F"},{"id":"lv_8_51","topic":"Food and Health","word":"maple","pos":"(n)","ipa":"/ˈmeɪ.pəl/","defVi":"cây phong","defEn":"a tree grown in northern regions that typically has lobed leaves and produces syrup","examples":["The leaves of the [maple] tree turn bright red and orange in autumn. (=Dịch: Lá cây phong chuyển sang màu đỏ và cam rực rỡ vào mùa thu.)","A red [maple] leaf is featured on the national flag of Canada. (=Dịch: Một chiếc lá phong đỏ được thể hiện trên quốc kỳ của Canada.)","The dining table was made of solid [maple] wood. (=Dịch: Bàn ăn được làm bằng gỗ phong nguyên khối.)"],"ukAudio":"/ai_services/tts3/?q=maple&lang=en-GB&ipa=%2F%CB%88me%C9%AA.p%C9%99l%2F","usAudio":"/ai_services/tts3/?q=maple&lang=en-US&ipa=%2F%CB%88me%C9%AA.p%C9%99l%2F"},{"id":"lv_8_52","topic":"Food and Health","word":"monosodium glutamate","pos":"(n)","ipa":"/ˌmɑː.noʊˌsoʊ.di.əm ˈɡluː.t̬ə.meɪt/","defVi":"mì chính, bột ngọt (bột điều vị)","defEn":"a white crystalline substance used as a flavor enhancer in cooking (MSG)","examples":["Some people believe that [monosodium glutamate] causes headaches, although evidence is mixed. (=Dịch: Một số người tin rằng mì chính gây đau đầu, mặc dù các bằng chứng còn trái chiều.)","The chef added a pinch of [monosodium glutamate] to enhance the savory flavor of the soup. (=Dịch: Đầu bếp đã thêm một nhúm mì chính để tăng thêm hương vị đậm đà cho món súp.)","Packaged snack foods often contain [monosodium glutamate] to improve taste. (=Dịch: Thực phẩm ăn liền đóng gói thường chứa bột ngọt để cải thiện mùi vị.)"],"ukAudio":"/ai_services/tts3/?q=monosodium+glutamate&lang=en-GB&ipa=%2F%CB%8Cm%C9%91%CB%90.no%CA%8A%CB%8Cso%CA%8A.di.%C9%99m+%CB%88%C9%A1lu%CB%90.t%CC%AC%C9%99.me%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=monosodium+glutamate&lang=en-US&ipa=%2F%CB%8Cm%C9%91%CB%90.no%CA%8A%CB%8Cso%CA%8A.di.%C9%99m+%CB%88%C9%A1lu%CB%90.t%CC%AC%C9%99.me%C9%AAt%2F"},{"id":"lv_8_53","topic":"Food and Health","word":"motivation","pos":"(n)","ipa":"/ˌmoʊ.t̬əˈveɪ.ʃən/","defVi":"động lực","defEn":"the reason or desire that makes someone want to do something","examples":["High salaries can serve as strong [motivation] for employees to work harder. (=Dịch: Mức lương cao có thể là động lực mạnh mẽ để nhân viên làm việc chăm chỉ hơn.)","She lost the [motivation] to study after failing the exam twice. (=Dịch: Cô ấy mất động lực học tập sau khi trượt kỳ thi hai lần.)","Setting clear goals provides the [motivation] needed to achieve success. (=Dịch: Việc đặt ra mục tiêu rõ ràng sẽ cung cấp động lực cần thiết để đạt được thành công.)"],"ukAudio":"/ai_services/tts3/?q=motivation&lang=en-GB&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=motivation&lang=en-US&ipa=%2F%CB%8Cmo%CA%8A.t%CC%AC%C9%99%CB%88ve%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_8_54","topic":"Food and Health","word":"norway","pos":"(n)","ipa":"/ˈnɔːr.weɪ/","defVi":"Na Uy","defEn":"a Scandinavian country in Northern Europe known for its fjords and mountains","examples":["Many tourists travel to [Norway] to see the spectacular northern lights. (=Dịch: Nhiều du khách đến Na Uy để ngắm hiện tượng cực quang ngoạn mục.)","Salmon farming is a major export industry in [Norway]. (=Dịch: Nuôi cá hồi là một ngành xuất khẩu lớn ở Na Uy.)","She spent two weeks hiking along the famous fjords of [Norway]. (=Dịch: Cô ấy đã dành hai tuần đi bộ dọc theo những vịnh hẹp nổi tiếng của Na Uy.)"],"ukAudio":"/ai_services/tts3/?q=norway&lang=en-GB&ipa=%2F%CB%88n%C9%94%CB%90r.we%C9%AA%2F","usAudio":"/ai_services/tts3/?q=norway&lang=en-US&ipa=%2F%CB%88n%C9%94%CB%90r.we%C9%AA%2F"},{"id":"lv_8_55","topic":"Food and Health","word":"norwegian","pos":"(adj)","ipa":"/nɔːrˈwiː.dʒən/","defVi":"(thuộc) Na Uy, người Na Uy, tiếng Na Uy","defEn":"relating to Norway, its people, or its language","examples":["She loves exploring the dramatic landscapes of the [Norwegian] fjords. (=Dịch: Cô ấy thích khám phá những cảnh quan ấn tượng của các vịnh hẹp Na Uy.)","The company recently hired a [Norwegian] architect to design the headquarters. (=Dịch: Công ty gần đây đã thuê một kiến trúc sư người Na Uy để thiết kế trụ sở chính.)","He is studying [Norwegian] literature at the university. (=Dịch: Anh ấy đang nghiên cứu văn học Na Uy tại trường đại học.)"],"ukAudio":"/ai_services/tts3/?q=norwegian&lang=en-GB&ipa=%2Fn%C9%94%CB%90r%CB%88wi%CB%90.d%CA%92%C9%99n%2F","usAudio":"/ai_services/tts3/?q=norwegian&lang=en-US&ipa=%2Fn%C9%94%CB%90r%CB%88wi%CB%90.d%CA%92%C9%99n%2F"},{"id":"lv_8_56","topic":"Food and Health","word":"nutrient","pos":"(n)","ipa":"/ˈnuː.tri.ənt/","defVi":"chất dinh dưỡng","defEn":"A substance that plants or animals need in order to live and grow.","examples":["Fresh fruits and vegetables are packed with every essential [nutrient]. (=Dịch: Rau củ và trái cây tươi chứa đầy đủ mọi chất dinh dưỡng thiết yếu.)","Overcooking vegetables can destroy a vital [nutrient] like vitamin C. (=Dịch: Nấu rau củ quá chín có thể làm mất đi các chất dinh dưỡng quan trọng như vitamin C.)","Plants absorb water and [nutrient] compounds directly from the soil. (=Dịch: Cây cối hấp thụ nước và các hợp chất dinh dưỡng trực tiếp từ đất.)"],"ukAudio":"/ai_services/tts3/?q=nutrient&lang=en-GB&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=nutrient&lang=en-US&ipa=%2F%CB%88nu%CB%90.tri.%C9%99nt%2F"},{"id":"lv_8_57","topic":"Food and Health","word":"nutritional","pos":"(adj)","ipa":"/nuːˈtrɪ.ʃən.l/","defVi":"thuộc về dinh dưỡng","defEn":"relating to the substances in food that help you stay healthy and grow","examples":["It is important to check the [nutritional] value on food labels. (=Dịch: Việc kiểm tra giá trị dinh dưỡng trên nhãn thực phẩm là rất quan trọng.)","Children need a diet with high [nutritional] quality for healthy growth. (=Dịch: Trẻ em cần một chế độ ăn có chất lượng dinh dưỡng cao để phát triển khỏe mạnh.)","Fast food often lacks essential [nutritional] elements. (=Dịch: Thức ăn nhanh thường thiếu các yếu tố dinh dưỡng thiết yếu.)"],"ukAudio":"/ai_services/tts3/?q=nutritional&lang=en-GB&ipa=%2Fnu%CB%90%CB%88tr%C9%AA.%CA%83%C9%99n.l%2F","usAudio":"/ai_services/tts3/?q=nutritional&lang=en-US&ipa=%2Fnu%CB%90%CB%88tr%C9%AA.%CA%83%C9%99n.l%2F"},{"id":"lv_8_58","topic":"Food and Health","word":"obesity","pos":"(n)","ipa":"/oʊˈbiː.sə.t̬i/","defVi":"bệnh béo phì, tình trạng béo phì","defEn":"the condition of being extremely overweight in a way that is dangerous for health","examples":["Childhood [obesity] is becoming a serious public health issue worldwide. (=Dịch: Béo phì ở trẻ em đang trở thành một vấn đề sức khỏe cộng đồng nghiêm trọng trên toàn thế giới.)","Regular exercise and a balanced diet can help prevent [obesity]. (=Dịch: Tập thể dục thường xuyên và chế độ ăn cân bằng có thể giúp ngăn ngừa béo phì.)","The government launched a campaign to raise awareness about the risks of [obesity]. (=Dịch: Chính phủ đã phát động một chiến dịch nhằm nâng cao nhận thức về những nguy cơ của bệnh béo phì.)"],"ukAudio":"/ai_services/tts3/?q=obesity&lang=en-GB&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=obesity&lang=en-US&ipa=%2Fo%CA%8A%CB%88bi%CB%90.s%C9%99.t%CC%ACi%2F"},{"id":"lv_8_59","topic":"Food and Health","word":"package","pos":"(n)","ipa":"/ˈpæk.ɪdʒ/","defVi":"bưu kiện, gói hàng; gói (dịch vụ, sản phẩm)","defEn":"an object or collection of objects wrapped in paper or packed in a box","examples":["The delivery driver left a large [package] on the front porch. (=Dịch: Tài xế giao hàng đã để lại một gói hàng lớn ở hiên trước.)","The hotel offers an attractive vacation [package] for families. (=Dịch: Khách sạn cung cấp một gói kỳ nghỉ hấp dẫn dành cho các gia đình.)","Please handle this fragile [package] with extra care. (=Dịch: Xin vui lòng xử lý gói hàng dễ vỡ này một cách thật cẩn thận.)"],"ukAudio":"/ai_services/tts3/?q=package&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=package&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AAd%CA%92%2F"},{"id":"lv_8_60","topic":"Food and Health","word":"packaging","pos":"(n)","ipa":"/ˈpæk.ɪ.dʒɪŋ/","defVi":"bao bì, quy cách đóng gói","defEn":"materials used to wrap or protect goods for sale or transport","examples":["Eco-friendly [packaging] helps companies reduce plastic waste significantly. (=Dịch: Bao bì thân thiện với môi trường giúp các công ty giảm thiểu đáng kể rác thải nhựa.)","The attractive [packaging] caught the customer's attention immediately. (=Dịch: Bao bì bắt mắt đã ngay lập tức thu hút sự chú ý của khách hàng.)","Excessive [packaging] should be avoided to protect the environment. (=Dịch: Nên tránh việc đóng gói quá mức để bảo vệ môi trường.)"],"ukAudio":"/ai_services/tts3/?q=packaging&lang=en-GB&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=packaging&lang=en-US&ipa=%2F%CB%88p%C3%A6k.%C9%AA.d%CA%92%C9%AA%C5%8B%2F"},{"id":"lv_8_61","topic":"Food and Health","word":"pan","pos":"(n)","ipa":"/pæn/","defVi":"chảo","defEn":"a flat metal container with a handle, used for cooking food in","examples":["Heat some oil in a frying [pan] over medium heat. (=Dịch: Đun nóng một ít dầu trong chảo rán trên lửa vừa.)","He forgot the [pan] on the stove and burnt the vegetables. (=Dịch: Anh ấy để quên chiếc chảo trên bếp và làm cháy rau củ.)","Make sure to clean the non-stick [pan] with a soft sponge. (=Dịch: Hãy nhớ rửa chiếc chảo chống dính bằng một miếng bọt biển mềm.)"],"ukAudio":"/ai_services/tts3/?q=pan&lang=en-GB&ipa=%2Fp%C3%A6n%2F","usAudio":"/ai_services/tts3/?q=pan&lang=en-US&ipa=%2Fp%C3%A6n%2F"},{"id":"lv_8_62","topic":"Food and Health","word":"paste","pos":"(n)","ipa":"/peɪst/","defVi":"hỗn hợp sệt, bột nhão, hồ dán","defEn":"a thick, soft, moist substance made by mixing crushed ingredients or chemicals","examples":["Grind the garlic and ginger into a smooth [paste]. (=Dịch: Nghiền tỏi và gừng thành một hỗn hợp nhuyễn mịn.)","Apply a small amount of whitening [paste] to your teeth. (=Dịch: Thoa một lượng nhỏ kem làm trắng lên răng của bạn.)","The recipe requires two tablespoons of tomato [paste]. (=Dịch: Công thức nấu ăn yêu cầu hai thìa canh sốt cà chua đặc sệt.)"],"ukAudio":"/ai_services/tts3/?q=paste&lang=en-GB&ipa=%2Fpe%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=paste&lang=en-US&ipa=%2Fpe%C9%AAst%2F"},{"id":"lv_8_63","topic":"Food and Health","word":"percentage","pos":"(n)","ipa":"/pɚˈsɛn.tɪdʒ/","defVi":"tỷ lệ phần trăm","defEn":"an amount, number, or rate considered as a part of every 100","examples":["A high [percentage] of students passed the final exam with top marks. (=Dịch: Một tỷ lệ phần trăm lớn học sinh đã vượt qua kỳ thi cuối kỳ với điểm số cao.)","The chart shows the [percentage] of household income spent on food. (=Dịch: Biểu đồ thể hiện tỷ lệ phần trăm thu nhập hộ gia đình dành cho thực phẩm.)","Only a small [percentage] of the budget was allocated to advertising. (=Dịch: Chỉ một tỷ lệ phần trăm nhỏ trong ngân sách được phân bổ cho quảng cáo.)"],"ukAudio":"/ai_services/tts3/?q=percentage&lang=en-GB&ipa=%2Fp%C9%9A%CB%88s%C9%9Bn.t%C9%AAd%CA%92%2F","usAudio":"/ai_services/tts3/?q=percentage&lang=en-US&ipa=%2Fp%C9%9A%CB%88s%C9%9Bn.t%C9%AAd%CA%92%2F"},{"id":"lv_8_64","topic":"Food and Health","word":"pizza","pos":"(n)","ipa":"/ˈpiːt.sə/","defVi":"bánh pizza","defEn":"a flat, round bread base topped with cheese, tomato sauce, and other ingredients","examples":["We ordered a large cheese [pizza] for dinner. (=Dịch: Chúng tôi đã gọi một chiếc bánh pizza phô mai cỡ lớn cho bữa tối.)","Making homemade [pizza] is a fun activity for children. (=Dịch: Tự làm pizza tại nhà là một hoạt động thú vị cho trẻ em.)","He loves to top his [pizza] with mushrooms and olives. (=Dịch: Anh ấy thích rắc thêm nấm và ô liu lên trên chiếc pizza của mình.)"],"ukAudio":"/ai_services/tts3/?q=pizza&lang=en-GB&ipa=%2F%CB%88pi%CB%90t.s%C9%99%2F","usAudio":"/ai_services/tts3/?q=pizza&lang=en-US&ipa=%2F%CB%88pi%CB%90t.s%C9%99%2F"},{"id":"lv_8_65","topic":"Food and Health","word":"popularity","pos":"(n)","ipa":"/ˌpɑː.pjəˈler.ə.t̬i/","defVi":"sự phổ biến, sự ưa chuộng","defEn":"the state or condition of being liked, admired, or supported by many people","examples":["The sudden [popularity] of electric scooters has caused traffic issues in urban areas. (=Dịch: Sự phổ biến bất ngờ của xe trượt điện đã gây ra các vấn đề giao thông ở các khu vực đô thị.)","The band gained huge [popularity] after releasing their first studio album. (=Dịch: Ban nhạc đã đạt được sự yêu mến nồng nhiệt sau khi phát hành album phòng thu đầu tay.)","Social media platforms constantly compete for [popularity] among young users. (=Dịch: Các nền tảng mạng xã hội liên tục cạnh tranh để giành được sự ưa chuộng từ người dùng trẻ tuổi.)"],"ukAudio":"/ai_services/tts3/?q=popularity&lang=en-GB&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=popularity&lang=en-US&ipa=%2F%CB%8Cp%C9%91%CB%90.pj%C9%99%CB%88ler.%C9%99.t%CC%ACi%2F"},{"id":"lv_8_66","topic":"Food and Health","word":"pour","pos":"(v)","ipa":"/pɔːr/","defVi":"rót, đổ","defEn":"to make a liquid or other substance flow steadily out of a container","examples":["Please [pour] some fresh milk into my coffee cup. (=Dịch: Xin vui lòng rót một ít sữa tươi vào tách cà phê của tôi.)","Dark clouds gathered, and heavy rain began to [pour] down. (=Dịch: Mây đen kéo đến và mưa lớn bắt đầu trút xuống.)","Carefully [pour] the mixture into the baking pan before placing it in the oven. (=Dịch: Cẩn thận đổ hỗn hợp vào khuôn nướng trước khi cho vào lò.)"],"ukAudio":"/ai_services/tts3/?q=pour&lang=en-GB&ipa=%2Fp%C9%94%CB%90r%2F","usAudio":"/ai_services/tts3/?q=pour&lang=en-US&ipa=%2Fp%C9%94%CB%90r%2F"},{"id":"lv_8_67","topic":"Food and Health","word":"producer","pos":"(n)","ipa":"/prəˈduː.sɚ/","defVi":"nhà sản xuất","defEn":"a person or company that makes goods, or someone who oversees the making of a film, play, or record","examples":["Vietnam is a major coffee [producer] in the global market. (=Dịch: Việt Nam là một nhà sản xuất cà phê lớn trên thị trường toàn cầu.)","The film [producer] secured the funding needed to start shooting the movie. (=Dịch: Nhà sản xuất phim đã đảm bảo được nguồn kinh phí cần thiết để bắt đầu bấm máy.)","Local [producers] are encouraged to sell their organic vegetables at the market. (=Dịch: Các nhà sản xuất địa phương được khuyến khích bán rau hữu cơ của họ tại chợ.)"],"ukAudio":"/ai_services/tts3/?q=producer&lang=en-GB&ipa=%2Fpr%C9%99%CB%88du%CB%90.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=producer&lang=en-US&ipa=%2Fpr%C9%99%CB%88du%CB%90.s%C9%9A%2F"},{"id":"lv_8_68","topic":"Food and Health","word":"protein","pos":"(n)","ipa":"/ˈproʊ.tiːn/","defVi":"chất đạm, protein","defEn":"A substance found in meat, eggs, and beans that is necessary for the body to grow and repair itself.","examples":["Eggs and chicken breast are excellent sources of lean [protein]. (=Dịch: Trứng và ức gà là nguồn cung cấp chất đạm nạc tuyệt vời.)","Bodybuilders need a significant amount of [protein] to build muscle mass. (=Dịch: Những người tập thể hình cần một lượng lớn protein để phát triển cơ bắp.)","Beans and lentils provide essential [protein] for individuals following a vegetarian diet. (=Dịch: Đậu và đậu lăng cung cấp nguồn chất đạm thiết yếu cho những người theo chế độ ăn chay.)"],"ukAudio":"/ai_services/tts3/?q=protein&lang=en-GB&ipa=%2F%CB%88pro%CA%8A.ti%CB%90n%2F","usAudio":"/ai_services/tts3/?q=protein&lang=en-US&ipa=%2F%CB%88pro%CA%8A.ti%CB%90n%2F"},{"id":"lv_8_69","topic":"Food and Health","word":"reuse","pos":"(v)","ipa":"/ˌriːˈjuːz/","defVi":"tái sử dụng","defEn":"to use something again instead of throwing it away","examples":["You can [reuse] glass jars to store spices and herbs. (=Dịch: Bạn có thể tái sử dụng các lọ thủy tinh để đựng gia vị và thảo mộc.)","The school encourages students to [reuse] plastic bottles for craft projects. (=Dịch: Trường học khuyến khích học sinh tái sử dụng chai nhựa cho các dự án thủ công.)","We should [reuse] shopping bags to reduce plastic waste. (=Dịch: Chúng ta nên tái sử dụng túi mua sắm để giảm rác thải nhựa.)"],"ukAudio":"/ai_services/tts3/?q=reuse&lang=en-GB&ipa=%2F%CB%8Cri%CB%90%CB%88ju%CB%90z%2F","usAudio":"/ai_services/tts3/?q=reuse&lang=en-US&ipa=%2F%CB%8Cri%CB%90%CB%88ju%CB%90z%2F"},{"id":"lv_8_70","topic":"Food and Health","word":"sap","pos":"(n)","ipa":"/sæp/","defVi":"nhựa cây","defEn":"the liquid that carries food and water through plants and trees","examples":["Maple syrup is made by boiling down the clear [sap] of maple trees. (=Dịch: Siro phong được làm bằng cách đun cạn nhựa trong suốt của cây phong.)","In spring, the [sap] begins to rise in the branches as new leaves grow. (=Dịch: Vào mùa xuân, nhựa cây bắt đầu dâng lên trong các cành khi lá mới mọc.)","Sticky [sap] dripped onto the car from the pine tree above. (=Dịch: Nhựa cây dính nhớp đã nhỏ xuống xe từ cây thông phía trên.)"],"ukAudio":"/ai_services/tts3/?q=sap&lang=en-GB&ipa=%2Fs%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=sap&lang=en-US&ipa=%2Fs%C3%A6p%2F"},{"id":"lv_8_71","topic":"Food and Health","word":"seafood","pos":"(n)","ipa":"/ˈsiːˌfuːd/","defVi":"hải sản","defEn":"animals from the sea that can be eaten, such as fish and shellfish","examples":["Coastal cities are famous for their fresh and delicious [seafood]. (=Dịch: Các thành phố ven biển nổi tiếng với nguồn hải sản tươi ngon.)","He cannot eat crab because he is allergic to [seafood]. (=Dịch: Anh ấy không thể ăn cua vì bị dị ứng với hải sản.)","The local restaurant serves a wide variety of grilled [seafood]. (=Dịch: Nhà hàng địa phương phục vụ nhiều loại hải sản nướng đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=seafood&lang=en-GB&ipa=%2F%CB%88si%CB%90%CB%8Cfu%CB%90d%2F","usAudio":"/ai_services/tts3/?q=seafood&lang=en-US&ipa=%2F%CB%88si%CB%90%CB%8Cfu%CB%90d%2F"},{"id":"lv_8_72","topic":"Food and Health","word":"sensor","pos":"(n)","ipa":"/ˈsɛn.sɚ/","defVi":"cảm biến, thiết bị cảm ứng","defEn":"a device that detects and responds to physical changes such as light, heat, or movement","examples":["The automated doors open when a motion [sensor] detects someone approaching. (=Dịch: Cửa tự động sẽ mở ra khi cảm biến chuyển động nhận diện có người đang tiến lại gần.)","Modern smartphones use an optical [sensor] to adjust screen brightness. (=Dịch: Điện thoại thông minh hiện đại sử dụng cảm biến quang học để điều chỉnh độ sáng màn hình.)","The security system is triggered whenever an infrared [sensor] is activated. (=Dịch: Hệ thống an ninh sẽ được kích hoạt bất cứ khi nào cảm biến hồng ngoại nhận tín hiệu.)"],"ukAudio":"/ai_services/tts3/?q=sensor&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.s%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sensor&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.s%C9%9A%2F"},{"id":"lv_8_73","topic":"Food and Health","word":"shaft","pos":"(n)","ipa":"/ʃæft/","defVi":"trục (máy móc); đường hầm/giếng đứng (mỏ, thang máy)","defEn":"a long, narrow vertical or sloping passage, or a rotating rod in an engine","examples":["The rescue team descended into the mine [shaft] to look for survivors. (=Dịch: Đội cứu hộ đã đi xuống giếng mỏ để tìm kiếm những người sống sót.)","A broken drive [shaft] caused the car to stop suddenly on the highway. (=Dịch: Trục truyền động bị gãy khiến chiếc xe đột ngột dừng lại trên đường cao tốc.)","A [shaft] of sunlight broke through the dark storm clouds. (=Dịch: Một tia nắng mặt trời đã xuyên qua những đám mây bão đen kịt.)"],"ukAudio":"/ai_services/tts3/?q=shaft&lang=en-GB&ipa=%2F%CA%83%C3%A6ft%2F","usAudio":"/ai_services/tts3/?q=shaft&lang=en-US&ipa=%2F%CA%83%C3%A6ft%2F"},{"id":"lv_8_74","topic":"Food and Health","word":"signal","pos":"(n)","ipa":"/ˈsɪɡ.nəl/","defVi":"tín hiệu, dấu hiệu","defEn":"an action, sound, or light used to give information or convey an instruction","examples":["A red traffic [signal] indicates that all approaching vehicles must stop. (=Dịch: Đèn tín hiệu giao thông màu đỏ báo hiệu rằng tất cả các phương tiện đang tới đều phải dừng lại.)","The strong economic data was a positive [signal] for potential investors. (=Dịch: Dữ liệu kinh tế khởi sắc là một tín hiệu tích cực đối với các nhà đầu tư tiềm năng.)","My phone cannot detect any network [signal] inside this underground tunnel. (=Dịch: Điện thoại của tôi không thể bắt được bất kỳ tín hiệu mạng nào bên trong đường hầm này.)"],"ukAudio":"/ai_services/tts3/?q=signal&lang=en-GB&ipa=%2F%CB%88s%C9%AA%C9%A1.n%C9%99l%2F","usAudio":"/ai_services/tts3/?q=signal&lang=en-US&ipa=%2F%CB%88s%C9%AA%C9%A1.n%C9%99l%2F"},{"id":"lv_8_75","topic":"Food and Health","word":"sodium","pos":"(n)","ipa":"/ˈsoʊ.di.əm/","defVi":"natri","defEn":"a soft, silver-white chemical element found especially in salt","examples":["A diet high in [sodium] can lead to high blood pressure. (=Dịch: Chế độ ăn nhiều natri có thể dẫn đến bệnh cao huyết áp.)","Doctors advise reducing your daily intake of [sodium] to protect your heart. (=Dịch: Các bác sĩ khuyên nên giảm lượng natri nạp vào hàng ngày để bảo vệ tim mạch.)","The nutrition label shows how much [sodium] each serving contains. (=Dịch: Nhãn dinh dưỡng cho biết lượng natri chứa trong mỗi khẩu phần ăn.)"],"ukAudio":"/ai_services/tts3/?q=sodium&lang=en-GB&ipa=%2F%CB%88so%CA%8A.di.%C9%99m%2F","usAudio":"/ai_services/tts3/?q=sodium&lang=en-US&ipa=%2F%CB%88so%CA%8A.di.%C9%99m%2F"},{"id":"lv_8_76","topic":"Food and Health","word":"spice","pos":"(n)","ipa":"/spaɪs/","defVi":"gia vị (từ thực vật)","defEn":"a substance made from plants used to add flavor to food.","examples":["Cinnamon is a popular [spice] used in baking. (=Dịch: Quế là một loại gia vị phổ biến được sử dụng trong làm bánh.)","Adding too much [spice] can overpower the taste of the soup. (=Dịch: Cho quá nhiều gia vị có thể làm lấn át hương vị của món súp.)","The local market sells a wide variety of fresh [spice] options. (=Dịch: Khu chợ địa phương bán rất nhiều loại gia vị tươi đa dạng.)"],"ukAudio":"/ai_services/tts3/?q=spice&lang=en-GB&ipa=%2Fspa%C9%AAs%2F","usAudio":"/ai_services/tts3/?q=spice&lang=en-US&ipa=%2Fspa%C9%AAs%2F"},{"id":"lv_8_77","topic":"Food and Health","word":"steam","pos":"(n)","ipa":"/stim/","defVi":"hơi nước","defEn":"the hot gas that is produced when water boils","examples":["Clouds of [steam] rose from the hot springs in the morning chill. (=Dịch: Những làn hơi nước bốc lên từ suối nước nóng trong cái lạnh buổi sáng.)","The old train was powered by a massive [steam] engine. (=Dịch: Đoàn tàu cũ được vận hành bằng một động cơ hơi nước khổng lồ.)","Be careful when opening the pot because the hot [steam] can burn you. (=Dịch: Hãy cẩn thận khi mở nắp nồi vì hơi nước nóng có thể làm bạn bị bỏng.)"],"ukAudio":"/ai_services/tts3/?q=steam&lang=en-GB&ipa=%2Fstim%2F","usAudio":"/ai_services/tts3/?q=steam&lang=en-US&ipa=%2Fstim%2F"},{"id":"lv_8_78","topic":"Food and Health","word":"strand","pos":"(v)","ipa":"/strænd/","defVi":"làm mắc kẹt, làm cho rơi vào thế bơ vơ","defEn":"to leave someone in a difficult situation or place without the means to move or leave","examples":["A severe blizzard threatened to [strand] hundreds of drivers on the highway. (=Dịch: Trận bão tuyết dữ dội có nguy cơ làm hàng trăm tài xế mắc kẹt trên đường cao tốc.)","The cancelled flight will [strand] passengers at the airport overnight. (=Dịch: Chuyến bay bị hủy sẽ khiến các hành khách phải kẹt lại ở sân bay qua đêm.)","Rising floodwaters can easily [strand] residents in low-lying villages. (=Dịch: Nước lũ dâng cao có thể dễ dàng cô lập và làm mắc kẹt người dân ở các ngôi làng trũng thấp.)"],"ukAudio":"/ai_services/tts3/?q=strand&lang=en-GB&ipa=%2Fstr%C3%A6nd%2F","usAudio":"/ai_services/tts3/?q=strand&lang=en-US&ipa=%2Fstr%C3%A6nd%2F"},{"id":"lv_8_79","topic":"Food and Health","word":"supplement","pos":"(n)","ipa":"/ˈsʌp.lə.mənt/","defVi":"phần bổ sung, thực phẩm chức năng bổ sung","defEn":"something added to make up for a lack or extend an existing thing","examples":["The doctor advised her to take a daily vitamin D [supplement]. (=Dịch: Bác sĩ khuyên cô nên bổ sung vitamin D hàng ngày.)","He takes a protein [supplement] after each workout session to build muscle. (=Dịch: Anh ấy dùng thực phẩm bổ sung protein sau mỗi buổi tập để phát triển cơ bắp.)","The travel guide includes a map [supplement] at the back. (=Dịch: Cuốn sách hướng dẫn du lịch bao gồm một phần bản đồ bổ sung ở phía sau.)"],"ukAudio":"/ai_services/tts3/?q=supplement&lang=en-GB&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=supplement&lang=en-US&ipa=%2F%CB%88s%CA%8Cp.l%C9%99.m%C9%99nt%2F"},{"id":"lv_8_80","topic":"Food and Health","word":"swedish","pos":"(adj)","ipa":"/ˈswi.dɪʃ/","defVi":"thuộc Thụy Điển","defEn":"relating to Sweden, its people, or its language","examples":["The minimalist furniture was designed by a famous [Swedish] architect. (=Dịch: Món đồ nội thất tối giản được thiết kế bởi một kiến trúc sư người Thụy Điển nổi tiếng.)","She is learning the [Swedish] language before moving to Stockholm. (=Dịch: Cô ấy đang học tiếng Thụy Điển trước khi chuyển đến Stockholm.)","The restaurant specializes in traditional [Swedish] meatballs and pastries. (=Dịch: Nhà hàng chuyên phục vụ món thịt viên và bánh ngọt truyền thống của Thụy Điển.)"],"ukAudio":"/ai_services/tts3/?q=swedish&lang=en-GB&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F","usAudio":"/ai_services/tts3/?q=swedish&lang=en-US&ipa=%2F%CB%88swi.d%C9%AA%CA%83%2F"},{"id":"lv_8_81","topic":"Food and Health","word":"sweetener","pos":"(n)","ipa":"/ˈswiːt.nɚ/","defVi":"chất làm ngọt, đường nhân tạo","defEn":"a substance added to food or drink to make it taste sweet","examples":["Artificial [sweetener] is commonly used in diet soft drinks. (=Dịch: Chất làm ngọt nhân tạo thường được sử dụng trong các loại nước ngọt ăn kiêng.)","Honey is a popular natural [sweetener] used in baking. (=Dịch: Mật ong là một chất làm ngọt tự nhiên phổ biến được dùng trong làm bánh.)","She prefers using a low-calorie [sweetener] in her morning coffee. (=Dịch: Cô ấy thích sử dụng chất làm ngọt ít calo trong cà phê buổi sáng của mình.)"],"ukAudio":"/ai_services/tts3/?q=sweetener&lang=en-GB&ipa=%2F%CB%88swi%CB%90t.n%C9%9A%2F","usAudio":"/ai_services/tts3/?q=sweetener&lang=en-US&ipa=%2F%CB%88swi%CB%90t.n%C9%9A%2F"},{"id":"lv_8_82","topic":"Food and Health","word":"syrup","pos":"(n)","ipa":"/ˈsɪr.əp/","defVi":"xi-rô, nước đường đặc","defEn":"a thick, sweet liquid made by dissolving sugar in water, often flavored or used as medicine","examples":["He poured sweet maple [syrup] over his morning pancakes. (=Dịch: Anh ấy rưới xi-rô cây phong ngọt ngào lên những chiếc bánh kếp buổi sáng.)","The doctor prescribed a cough [syrup] to soothe her sore throat. (=Dịch: Bác sĩ đã kê một loại si-rô ho để làm dịu cơn đau họng của cô ấy.)","This dessert is soaked in a fragrant lemon [syrup]. (=Dịch: Món tráng miệng này được ngâm trong một lớp xi-rô chanh thơm ngát.)"],"ukAudio":"/ai_services/tts3/?q=syrup&lang=en-GB&ipa=%2F%CB%88s%C9%AAr.%C9%99p%2F","usAudio":"/ai_services/tts3/?q=syrup&lang=en-US&ipa=%2F%CB%88s%C9%AAr.%C9%99p%2F"},{"id":"lv_8_83","topic":"Food and Health","word":"takeaway","pos":"(n)","ipa":"/ˈteɪk.əˌweɪ/","defVi":"đồ ăn mang về, quán bán đồ ăn mang về","defEn":"a meal bought from a restaurant to be eaten somewhere else","examples":["We decided to order a Chinese [takeaway] for dinner tonight. (=Dịch: Chúng tôi quyết định gọi đồ ăn Trung Quốc mang về cho bữa tối nay.)","There is a very popular pizza [takeaway] near our campus. (=Dịch: Có một tiệm bánh pizza mang về rất nổi tiếng gần khuôn viên trường chúng tôi.)","Frequent consumption of [takeaway] food can be expensive and unhealthy. (=Dịch: Thường xuyên ăn đồ mang về có thể tốn kém và không tốt cho sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=takeaway&lang=en-GB&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=takeaway&lang=en-US&ipa=%2F%CB%88te%C9%AAk.%C9%99%CB%8Cwe%C9%AA%2F"},{"id":"lv_8_84","topic":"Food and Health","word":"tap","pos":"(n)","ipa":"/tæp/","defVi":"vòi nước, khóa vòi","defEn":"a device that controls the flow of liquid or gas from a pipe","examples":["Do not forget to turn off the [tap] while brushing your teeth. (=Dịch: Đừng quên khóa vòi nước trong khi đánh răng.)","Water was dripping slowly from the kitchen [tap]. (=Dịch: Nước đang nhỏ giọt từ từ từ vòi rửa trong bếp.)","Is it safe to drink water straight from the [tap] here? (=Dịch: Uống nước trực tiếp từ vòi ở đây có an toàn không?)"],"ukAudio":"/ai_services/tts3/?q=tap&lang=en-GB&ipa=%2Ft%C3%A6p%2F","usAudio":"/ai_services/tts3/?q=tap&lang=en-US&ipa=%2Ft%C3%A6p%2F"},{"id":"lv_8_85","topic":"Food and Health","word":"therapy","pos":"(n)","ipa":"/ˈθer.ə.pi/","defVi":"liệu pháp, phương pháp trị liệu","defEn":"a treatment that helps someone feel better or grow stronger, especially after an illness or injury","examples":["Physical [therapy] helped him walk again after the terrible accident. (=Dịch: Vật lý trị liệu đã giúp anh ấy đi lại được sau vụ tai nạn kinh hoàng.)","Many people find music [therapy] effective for reducing stress. (=Dịch: Nhiều người thấy liệu pháp âm nhạc hiệu quả trong việc giảm căng thẳng.)","She goes to speech [therapy] twice a week to improve her pronunciation. (=Dịch: Cô ấy đi trị liệu ngôn ngữ hai lần một tuần để cải thiện khả năng phát âm.)"],"ukAudio":"/ai_services/tts3/?q=therapy&lang=en-GB&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F","usAudio":"/ai_services/tts3/?q=therapy&lang=en-US&ipa=%2F%CB%88%CE%B8er.%C9%99.pi%2F"},{"id":"lv_8_86","topic":"Food and Health","word":"tonne","pos":"(n)","ipa":"/tʌn/","defVi":"tấn (đơn vị đo khối lượng","defEn":"1.000 kg)\n=a metric unit of mass equal to 1,000 kilograms","examples":["The factory produces more than one [tonne] of recycled paper every single day. (=Dịch: Nhà máy sản xuất hơn một tấn giấy tái chế mỗi ngày.)","The cargo ship carried several thousand [tonne] shipments of iron ore across the ocean. (=Dịch: Tàu chở hàng đã vận chuyển hàng ngàn tấn quặng sắt qua đại dương.)","Farmers harvested nearly five [tonne] yields of wheat per hectare this season. (=Dịch: Nông dân đã thu hoạch được sản lượng gần năm tấn lúa mì trên mỗi hecta trong mùa vụ này.)"],"ukAudio":"/ai_services/tts3/?q=tonne&lang=en-GB&ipa=%2Ft%CA%8Cn%2F","usAudio":"/ai_services/tts3/?q=tonne&lang=en-US&ipa=%2Ft%CA%8Cn%2F"},{"id":"lv_8_87","topic":"Food and Health","word":"toxin","pos":"(n)","ipa":"/ˈtɑːk.sɪn/","defVi":"độc tố (chất độc sinh học)","defEn":"a poisonous substance, especially one produced by a living organism","examples":["Certain species of mushrooms contain a deadly [toxin] that can cause severe liver failure. (=Dịch: Một số loài nấm chứa độc tố chết người có thể gây suy gan nghiêm trọng.)","The liver plays a vital role in filtering harmful [toxin] elements from the bloodstream. (=Dịch: Gan đóng vai trò quan trọng trong việc lọc các độc tố có hại ra khỏi máu.)","Bacteria in contaminated food can release a dangerous [toxin] leading to acute illness. (=Dịch: Vi khuẩn trong thực phẩm bị ô nhiễm có thể tiết ra độc tố nguy hiểm dẫn đến bệnh cấp tính.)"],"ukAudio":"/ai_services/tts3/?q=toxin&lang=en-GB&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=toxin&lang=en-US&ipa=%2F%CB%88t%C9%91%CB%90k.s%C9%AAn%2F"},{"id":"lv_8_88","topic":"Food and Health","word":"trunk","pos":"(n)","ipa":"/trʌŋk/","defVi":"thân cây; hòm/rương lớn; cốp xe ô tô","defEn":"the main wooden stem of a tree, a large storage box, or the enclosed luggage compartment of a car","examples":["The thick [trunk] of the centuries-old oak tree provided shade for the entire garden. (=Dịch: Thân cây sồi hàng trăm năm tuổi to lớn che bóng mát cho cả khu vườn.)","She loaded all her heavy suitcases into the [trunk] of the taxi before heading to the airport. (=Dịch: Cô ấy xếp tất cả vali nặng vào cốp xe taxi trước khi ra sân bay.)","An elephant uses its versatile [trunk] to drink water and pick up food. (=Dịch: Một con voi sử dụng chiếc vòi đa năng của mình để uống nước và nhặt thức ăn.)"],"ukAudio":"/ai_services/tts3/?q=trunk&lang=en-GB&ipa=%2Ftr%CA%8C%C5%8Bk%2F","usAudio":"/ai_services/tts3/?q=trunk&lang=en-US&ipa=%2Ftr%CA%8C%C5%8Bk%2F"},{"id":"lv_8_89","topic":"Food and Health","word":"tube","pos":"(n)","ipa":"/tub/","defVi":"ống dẫn, tuýp","defEn":"a long, hollow cylinder used for carrying fluids or gases","examples":["Water flows through a metal [tube] into the cooling tank. (=Dịch: Nước chảy qua một ống kim loại vào bể làm mát.)","She bought a small [tube] of sunscreen at the pharmacy. (=Dịch: Cô ấy đã mua một tuýp kem chống nắng nhỏ ở hiệu thuốc.)","The technician replaced the damaged plastic [tube] inside the machine. (=Dịch: Kỹ thuật viên đã thay thế chiếc ống nhựa bị hỏng bên trong cỗ máy.)"],"ukAudio":"/ai_services/tts3/?q=tube&lang=en-GB&ipa=%2Ftub%2F","usAudio":"/ai_services/tts3/?q=tube&lang=en-US&ipa=%2Ftub%2F"},{"id":"lv_8_90","topic":"Food and Health","word":"unaware","pos":"(adj)","ipa":"/ˌʌn.əˈwer/","defVi":"không nhận biết, không hay biết","defEn":"Not knowing or noticing something that is happening.","examples":["Many people remain completely [unaware] of the dangers of excessive sugar consumption. (=Dịch: Nhiều người vẫn hoàn toàn không nhận thức được sự nguy hiểm của việc tiêu thụ quá nhiều đường.)","She seemed [unaware] that everyone in the room was listening to her conversation. (=Dịch: Cô ấy dường như không hay biết rằng mọi người trong phòng đều đang lắng nghe cuộc trò chuyện của mình.)","The driver was [unaware] of the flat tire until another motorist signaled him. (=Dịch: Người tài xế không biết xe bị xẹp lốp cho đến khi một người đi đường khác ra hiệu.)"],"ukAudio":"/ai_services/tts3/?q=unaware&lang=en-GB&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88wer%2F","usAudio":"/ai_services/tts3/?q=unaware&lang=en-US&ipa=%2F%CB%8C%CA%8Cn.%C9%99%CB%88wer%2F"},{"id":"lv_8_91","topic":"Food and Health","word":"unhealthy","pos":"(adj)","ipa":"/ʌnˈhel.θi/","defVi":"không lành mạnh, có hại cho sức khỏe","defEn":"Harmful to your health or not having good health.","examples":["Eating too much fast food is an [unhealthy] habit that can lead to obesity. (=Dịch: Ăn quá nhiều đồ ăn nhanh là một thói quen không lành mạnh có thể dẫn đến béo phì.)","He made a full recovery after suffering from an [unhealthy] sleep schedule for months. (=Dịch: Anh ấy đã hồi phục hoàn toàn sau nhiều tháng có lịch trình ngủ thiếu lành mạnh.)","High levels of pollution create an [unhealthy] living environment in big cities. (=Dịch: Mức độ ô nhiễm cao tạo ra một môi trường sống có hại cho sức khỏe ở các thành phố lớn.)"],"ukAudio":"/ai_services/tts3/?q=unhealthy&lang=en-GB&ipa=%2F%CA%8Cn%CB%88hel.%CE%B8i%2F","usAudio":"/ai_services/tts3/?q=unhealthy&lang=en-US&ipa=%2F%CA%8Cn%CB%88hel.%CE%B8i%2F"},{"id":"lv_8_92","topic":"Food and Health","word":"unnecessary","pos":"(adj)","ipa":"/ʌnˈnes.ə.ser.i/","defVi":"không cần thiết, thừa thãi","defEn":"not needed or more than is needed.","examples":["Avoid making [unnecessary] purchases when you are saving money. (=Dịch: Hãy tránh mua sắm những thứ không cần thiết khi bạn đang tiết kiệm tiền.)","The flight delay caused [unnecessary] stress for all travelers. (=Dịch: Chuyến bay bị hoãn đã gây ra sự căng thẳng không đáng có cho tất cả các hành khách.)","He deleted [unnecessary] files to free up computer storage. (=Dịch: Anh ấy đã xóa các tệp không cần thiết để giải phóng dung lượng máy tính.)"],"ukAudio":"/ai_services/tts3/?q=unnecessary&lang=en-GB&ipa=%2F%CA%8Cn%CB%88nes.%C9%99.ser.i%2F","usAudio":"/ai_services/tts3/?q=unnecessary&lang=en-US&ipa=%2F%CA%8Cn%CB%88nes.%C9%99.ser.i%2F"},{"id":"lv_8_93","topic":"Food and Health","word":"upsetting","pos":"(adj)","ipa":"/ʌpˈset̬.ɪŋ/","defVi":"gây buồn phiền, đau lòng, làm khó chịu","defEn":"making someone feel worried, unhappy, or distressed","examples":["Watching the news about the natural disaster was deeply [upsetting]. (=Dịch: Xem tin tức về thảm họa thiên nhiên khiến mọi người vô cùng đau lòng.)","It was very [upsetting] for him to hear that his best friend was moving away. (=Dịch: Thật là buồn phiền đối với anh ấy khi nghe tin người bạn thân nhất của mình chuyển đi nơi khác.)","The documentary contains [upsetting] scenes of animal cruelty. (=Dịch: Bộ phim tài liệu chứa những cảnh quay đau lòng về sự tàn ác đối với động vật.)"],"ukAudio":"/ai_services/tts3/?q=upsetting&lang=en-GB&ipa=%2F%CA%8Cp%CB%88set%CC%AC.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=upsetting&lang=en-US&ipa=%2F%CA%8Cp%CB%88set%CC%AC.%C9%AA%C5%8B%2F"},{"id":"lv_8_94","topic":"Food and Health","word":"vitamin","pos":"(n)","ipa":"/ˈvaɪ.t̬ə.mɪn/","defVi":"vi-ta-min","defEn":"a natural substance found in food that is essential for normal growth and health","examples":["Oranges are extremely rich in [vitamin] C. (=Dịch: Cam rất giàu vi-ta-min C.)","The doctor recommended that she take a daily [vitamin] supplement. (=Dịch: Bác sĩ khuyên cô ấy nên uống viên bổ sung vi-ta-min mỗi ngày.)","A severe [vitamin] deficiency can lead to serious health issues. (=Dịch: Tình trạng thiếu hụt vi-ta-min nghiêm trọng có thể dẫn đến các vấn đề sức khỏe nguy hiểm.)"],"ukAudio":"/ai_services/tts3/?q=vitamin&lang=en-GB&ipa=%2F%CB%88va%C9%AA.t%CC%AC%C9%99.m%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=vitamin&lang=en-US&ipa=%2F%CB%88va%C9%AA.t%CC%AC%C9%99.m%C9%AAn%2F"},{"id":"lv_8_95","topic":"Food and Health","word":"warmth","pos":"(n)","ipa":"/wɔːrmθ/","defVi":"sự ấm áp, hơi ấm; sự niềm nở","defEn":"the state of being moderately hot; a feeling of friendliness and affection","examples":["She sat near the fireplace to feel the soothing [warmth] of the fire. (=Dịch: Cô ấy ngồi gần lò sưởi để cảm nhận hơi ấm dễ chịu từ ngọn lửa.)","The local community welcomed the refugees with genuine [warmth] and kindness. (=Dịch: Cộng đồng địa phương đã đón tiếp những người tị nạn với sự nồng hậu và lòng tốt chân thành.)","The morning sun provided enough [warmth] to melt the light layer of frost. (=Dịch: Ánh nắng buổi sớm đem lại đủ hơi ấm để làm tan lớp sương giá mỏng.)"],"ukAudio":"/ai_services/tts3/?q=warmth&lang=en-GB&ipa=%2Fw%C9%94%CB%90rm%CE%B8%2F","usAudio":"/ai_services/tts3/?q=warmth&lang=en-US&ipa=%2Fw%C9%94%CB%90rm%CE%B8%2F"},{"id":"lv_8_96","topic":"Food and Health","word":"weigh","pos":"(v)","ipa":"/weɪ/","defVi":"cân, cân nhắc","defEn":"to measure how heavy someone or something is, or to consider carefully","examples":["The nurse asked the patient to step on the scale to [weigh] him. (=Dịch: Y tá đã yêu cầu bệnh nhân bước lên bàn cân để cân trọng lượng.)","You should [weigh] all the ingredients accurately before baking the cake. (=Dịch: Bạn nên cân chính xác tất cả nguyên liệu trước khi nướng bánh.)","The committee needs to [weigh] the pros and cons before making a decision. (=Dịch: Ủy ban cần cân nhắc những ưu và nhược điểm trước khi đưa ra quyết định.)"],"ukAudio":"/ai_services/tts3/?q=weigh&lang=en-GB&ipa=%2Fwe%C9%AA%2F","usAudio":"/ai_services/tts3/?q=weigh&lang=en-US&ipa=%2Fwe%C9%AA%2F"},{"id":"lv_8_97","topic":"Food and Health","word":"widespread","pos":"(adj)","ipa":"/ˈwaɪdˌsprɛd/","defVi":"lan rộng, phổ biến khắp nơi","defEn":"existing or happening in many places or among many people","examples":["The new environmental policy received [widespread] support from the public. (=Dịch: Chính sách môi trường mới đã nhận được sự ủng hộ rộng rãi từ công chúng.)","The sudden power outage caused [widespread] disruption across the entire city. (=Dịch: Sự cố mất điện đột ngột đã gây ra tình trạng gián đoạn trên diện rộng khắp toàn thành phố.)","Deforestation remains a [widespread] concern in many tropical regions. (=Dịch: Nạn phá rừng vẫn là một mối lo ngại phổ biến ở nhiều khu vực nhiệt đới.)"],"ukAudio":"/ai_services/tts3/?q=widespread&lang=en-GB&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F","usAudio":"/ai_services/tts3/?q=widespread&lang=en-US&ipa=%2F%CB%88wa%C9%AAd%CB%8Cspr%C9%9Bd%2F"},{"id":"lv_8_98","topic":"Food and Health","word":"workout","pos":"(n)","ipa":"/ˈwɜːr.kaʊt/","defVi":"buổi tập luyện thể dục","defEn":"a period of physical exercise or training.","examples":["He does a daily morning [workout] to stay in shape. (=Dịch: Anh ấy tập thể dục mỗi sáng để giữ dáng.)","Drinking water after an intense [workout] is very important. (=Dịch: Uống nước sau một buổi tập luyện cường độ cao là rất quan trọng.)","She enjoys a 30-minute cardio [workout] at the gym. (=Dịch: Cô ấy thích một buổi tập cardio 30 phút tại phòng gym.)"],"ukAudio":"/ai_services/tts3/?q=workout&lang=en-GB&ipa=%2F%CB%88w%C9%9C%CB%90r.ka%CA%8At%2F","usAudio":"/ai_services/tts3/?q=workout&lang=en-US&ipa=%2F%CB%88w%C9%9C%CB%90r.ka%CA%8At%2F"}]},"rawTopic":"Food and Health"},{"id":"listening_u5_10","title":"Chủ đề 10/10: Technology and Natural Sciences","actTitle":"Từ vựng chủ đề: Technology and Natural Sciences (74 từ)","problem":{"pType":"topic_flashcards","topic":"Technology and Natural Sciences","count":74,"words":[{"id":"lv_9_0","topic":"Technology and Natural Sciences","word":"activate","pos":"(v)","ipa":"/ˈæk.tə.veɪt/","defVi":"kích hoạt, làm hoạt động","defEn":"to make something start working or functioning","examples":["You need to click the link in your email to [activate] your new account. (=Dịch: Bạn cần nhấp vào liên kết trong email để kích hoạt tài khoản mới của mình.)","Motion sensors automatically [activate] the outdoor lights when someone approaches. (=Dịch: Cảm biến chuyển động sẽ tự động kích hoạt đèn ngoài trời khi có người đến gần.)","The emergency system will [activate] an alarm as soon as smoke is detected. (=Dịch: Hệ thống khẩn cấp sẽ kích hoạt chuông báo động ngay khi phát hiện có khói.)"],"ukAudio":"/ai_services/tts3/?q=activate&lang=en-GB&ipa=%2F%CB%88%C3%A6k.t%C9%99.ve%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=activate&lang=en-US&ipa=%2F%CB%88%C3%A6k.t%C9%99.ve%C9%AAt%2F"},{"id":"lv_9_1","topic":"Technology and Natural Sciences","word":"adopt","pos":"(v)","ipa":"/əˈdɑːpt/","defVi":"áp dụng, thông qua, nhận nuôi","defEn":"to choose to follow or use a particular idea, method, plan, or style","examples":["Many schools decided to [adopt] digital textbooks to reduce paper waste. (=Dịch: Nhiều trường học đã quyết định áp dụng sách giáo khoa kỹ thuật số để giảm bớt rác thải giấy.)","The couple chose to [adopt] a child from an overseas orphanage. (=Dịch: Cặp vợ chồng đã chọn nhận nuôi một đứa trẻ từ một trại trẻ mồ côi ở nước ngoài.)","Organizations must [adopt] new marketing strategies to remain competitive in the market. (=Dịch: Các tổ chức phải áp dụng các chiến lược tiếp thị mới để duy trì tính cạnh tranh trên thị trường.)"],"ukAudio":"/ai_services/tts3/?q=adopt&lang=en-GB&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F","usAudio":"/ai_services/tts3/?q=adopt&lang=en-US&ipa=%2F%C9%99%CB%88d%C9%91%CB%90pt%2F"},{"id":"lv_9_2","topic":"Technology and Natural Sciences","word":"aerial","pos":"(adj)","ipa":"/ˈer.i.əl/","defVi":"trên không, trên trời","defEn":"existing, happening, or operating in the air","examples":["The drone captured stunning [aerial] views of the coastline. (=Dịch: Máy bay không người lái đã chụp được những góc nhìn trên không tuyệt đẹp của đường bờ biển.)","Firefighters used [aerial] water drops to combat the wildfire. (=Dịch: Lính cứu hỏa đã sử dụng trực thăng thả nước từ trên không để dập tắt đám cháy rừng.)","We enjoyed an [aerial] tour of the city in a helicopter. (=Dịch: Chúng tôi rất thích chuyến tham quan thành phố từ trên không bằng trực thăng.)"],"ukAudio":"/ai_services/tts3/?q=aerial&lang=en-GB&ipa=%2F%CB%88er.i.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=aerial&lang=en-US&ipa=%2F%CB%88er.i.%C9%99l%2F"},{"id":"lv_9_3","topic":"Technology and Natural Sciences","word":"allergic","pos":"(adj)","ipa":"/əˈlɝː.dʒɪk/","defVi":"dị ứng","defEn":"having a strong, bad medical reaction to a particular substance","examples":["She is severely [allergic] to peanuts and must carry medicine everywhere. (=Dịch: Cô ấy bị dị ứng nặng với đậu phộng và phải mang theo thuốc đi khắp nơi.)","Many people are [allergic] to cat hair and start sneezing immediately. (=Dịch: Nhiều người bị dị ứng với lông mèo và bắt đầu hắt hơi ngay lập tức.)","He discovered that he was [allergic] to penicillin after a hospital visit. (=Dịch: Anh ấy phát hiện ra mình bị dị ứng với penicillin sau một lần đến bệnh viện.)"],"ukAudio":"/ai_services/tts3/?q=allergic&lang=en-GB&ipa=%2F%C9%99%CB%88l%C9%9D%CB%90.d%CA%92%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=allergic&lang=en-US&ipa=%2F%C9%99%CB%88l%C9%9D%CB%90.d%CA%92%C9%AAk%2F"},{"id":"lv_9_4","topic":"Technology and Natural Sciences","word":"appliance","pos":"(n)","ipa":"/əˈplaɪ.əns/","defVi":"thiết bị, đồ gia dụng","defEn":"a machine or device, especially an electrical one used in the home","examples":["Modern kitchens are equipped with various energy-saving [appliance] models. (=Dịch: Các căn bếp hiện đại được trang bị nhiều mẫu thiết bị tiết kiệm năng lượng.)","Always unplug the household [appliance] before trying to repair it. (=Dịch: Luôn rút phích cắm thiết bị gia dụng trước khi cố gắng sửa chữa nó.)","The store sells a wide range of kitchen [appliance] products. (=Dịch: Cửa hàng bán rất nhiều sản phẩm đồ gia dụng nhà bếp.)"],"ukAudio":"/ai_services/tts3/?q=appliance&lang=en-GB&ipa=%2F%C9%99%CB%88pla%C9%AA.%C9%99ns%2F","usAudio":"/ai_services/tts3/?q=appliance&lang=en-US&ipa=%2F%C9%99%CB%88pla%C9%AA.%C9%99ns%2F"},{"id":"lv_9_5","topic":"Technology and Natural Sciences","word":"arid","pos":"(adj)","ipa":"/ˈær.ɪd/","defVi":"khô cằn, hạn hán","defEn":"having very little or no rain; extremely dry","examples":["Few plants can survive in such an [arid] climate without irrigation. (=Dịch: Rất ít loài thực vật có thể sống sót trong khí hậu khô cằn như vậy nếu không có tưới tiêu.)","The desert is an [arid] landscape with extreme temperatures. (=Dịch: Sa mạc là một cảnh quan khô cằn với nhiệt độ vô cùng khắc nghiệt.)","Farmers struggle to grow crops in the region's [arid] soil. (=Dịch: Nông dân phải chật vật trồng trọt trên đất đai khô cằn của khu vực này.)"],"ukAudio":"/ai_services/tts3/?q=arid&lang=en-GB&ipa=%2F%CB%88%C3%A6r.%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=arid&lang=en-US&ipa=%2F%CB%88%C3%A6r.%C9%AAd%2F"},{"id":"lv_9_6","topic":"Technology and Natural Sciences","word":"association","pos":"(n)","ipa":"/əˌsoʊ.siˈeɪ.ʃn/","defVi":"hiệp hội, sự liên kết / mối liên hệ","defEn":"an organized group of people with a shared purpose, or a mental connection between ideas","examples":["She joined the local medical [association] to meet other doctors. (=Dịch: Cô ấy đã tham gia hiệp hội y khoa địa phương để gặp gỡ các bác sĩ khác.)","The word has a strong positive [association] in the minds of consumers. (=Dịch: Từ này có một mối liên hệ tích cực mạnh mẽ trong tâm trí người tiêu dùng.)","The university works in close [association] with research institutes. (=Dịch: Trường đại học làm việc trong sự liên kết chặt chẽ với các viện nghiên cứu.)"],"ukAudio":"/ai_services/tts3/?q=association&lang=en-GB&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83n%2F","usAudio":"/ai_services/tts3/?q=association&lang=en-US&ipa=%2F%C9%99%CB%8Cso%CA%8A.si%CB%88e%C9%AA.%CA%83n%2F"},{"id":"lv_9_7","topic":"Technology and Natural Sciences","word":"atom","pos":"(n)","ipa":"/ˈæ.t̬əm/","defVi":"nguyên tử","defEn":"the smallest basic unit of a chemical element","examples":["A water molecule is made of two hydrogen [atoms] and one oxygen atom. (=Dịch: Một phân tử nước được tạo thành từ hai nguyên tử hydro và một nguyên tử oxy.)","Scientists study the structure of the [atom] to understand matter. (=Dịch: Các nhà khoa học nghiên cứu cấu trúc của nguyên tử để hiểu về vật chất.)","Splitting the [atom] can release a huge amount of energy. (=Dịch: Việc phân tách nguyên tử có thể giải phóng một lượng năng lượng khổng lồ.)"],"ukAudio":"/ai_services/tts3/?q=atom&lang=en-GB&ipa=%2F%CB%88%C3%A6.t%CC%AC%C9%99m%2F","usAudio":"/ai_services/tts3/?q=atom&lang=en-US&ipa=%2F%CB%88%C3%A6.t%CC%AC%C9%99m%2F"},{"id":"lv_9_8","topic":"Technology and Natural Sciences","word":"beetroot","pos":"(n)","ipa":"/ˈbit.rut/","defVi":"củ dền","defEn":"a plant with a round dark red root that is eaten as a vegetable","examples":["Fresh [beetroot] can be sliced and added to healthy salads. (=Dịch: Củ dền tươi có thể được cắt lát và thêm vào các món salad tốt cho sức khỏe.)","Drinking [beetroot] juice is believed to lower blood pressure. (=Dịch: Uống nước ép củ dền được cho là giúp hạ huyết áp.)","The natural dye from [beetroot] gives the soup a rich red color. (=Dịch: Phẩm màu tự nhiên từ củ dền tạo cho món súp một màu đỏ đậm đà.)"],"ukAudio":"/ai_services/tts3/?q=beetroot&lang=en-GB&ipa=%2F%CB%88bit.rut%2F","usAudio":"/ai_services/tts3/?q=beetroot&lang=en-US&ipa=%2F%CB%88bit.rut%2F"},{"id":"lv_9_9","topic":"Technology and Natural Sciences","word":"capability","pos":"(n)","ipa":"/ˌkeɪ.pəˈbɪl.ə.t̬i/","defVi":"khả năng, năng lực","defEn":"the ability or power to do something","examples":["The new software has the [capability] to process large amounts of data quickly. (=Dịch: Phần mềm mới có khả năng xử lý lượng lớn dữ liệu một cách nhanh chóng.)","She demonstrated remarkable leadership [capability] during the crisis. (=Dịch: Cô ấy đã thể hiện năng lực lãnh đạo xuất sắc trong suốt cuộc khủng hoảng.)","The smartphone's camera [capability] is better than that of many older models. (=Dịch: Khả năng của camera trên chiếc điện thoại thông minh này tốt hơn nhiều dòng máy cũ.)"],"ukAudio":"/ai_services/tts3/?q=capability&lang=en-GB&ipa=%2F%CB%8Cke%C9%AA.p%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F","usAudio":"/ai_services/tts3/?q=capability&lang=en-US&ipa=%2F%CB%8Cke%C9%AA.p%C9%99%CB%88b%C9%AAl.%C9%99.t%CC%ACi%2F"},{"id":"lv_9_10","topic":"Technology and Natural Sciences","word":"carbon","pos":"(n)","ipa":"/ˈkɑːr.bən/","defVi":"cacbon","defEn":"a chemical element that is found in all living things, coal, and diamonds","examples":["Diamonds and graphite are both pure forms of [carbon]. (=Dịch: Kim cương và than chì đều là các dạng tinh khiết của cacbon.)","Companies are trying to reduce their [carbon] footprint to protect nature. (=Dịch: Các công ty đang nỗ lực giảm dấu chân cacbon để bảo vệ thiên nhiên.)","All known life on Earth is based on [carbon] chemistry. (=Dịch: Mọi sự sống được biết đến trên Trái Đất đều dựa trên hóa học cacbon.)"],"ukAudio":"/ai_services/tts3/?q=carbon&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90r.b%C9%99n%2F","usAudio":"/ai_services/tts3/?q=carbon&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90r.b%C9%99n%2F"},{"id":"lv_9_11","topic":"Technology and Natural Sciences","word":"carbon dioxide","pos":"(n)","ipa":"/ˌkɑːr.bən daɪˈɑːk.saɪd/","defVi":"khí cacbonic, khí CO2","defEn":"a gas that is produced when people or animals breathe out, or when carbon is burned","examples":["Trees absorb [carbon dioxide] and release oxygen into the atmosphere. (=Dịch: Cây xanh hấp thụ khí cacbonic và thải oxy vào bầu khí quyển.)","Burning fossil fuels increases the level of [carbon dioxide] in the air. (=Dịch: Đốt nhiên liệu hóa thạch làm tăng nồng độ khí CO2 trong không khí.)","Excessive [carbon dioxide] emissions contribute significantly to global warming. (=Dịch: Lượng khí thải cacbonic quá mức đóng góp đáng kể vào sự nóng lên toàn cầu.)"],"ukAudio":"/ai_services/tts3/?q=carbon+dioxide&lang=en-GB&ipa=%2F%CB%8Ck%C9%91%CB%90r.b%C9%99n+da%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=carbon+dioxide&lang=en-US&ipa=%2F%CB%8Ck%C9%91%CB%90r.b%C9%99n+da%C9%AA%CB%88%C9%91%CB%90k.sa%C9%AAd%2F"},{"id":"lv_9_12","topic":"Technology and Natural Sciences","word":"census","pos":"(n)","ipa":"/ˈsɛn.səs/","defVi":"cuộc điều tra dân số","defEn":"an official count of the population and collection of demographic information","examples":["The government conducts a national [census] every ten years. (=Dịch: Chính phủ tiến hành một cuộc điều tra dân số quốc gia mười năm một lần.)","According to the latest [census], the city's population has increased dramatically. (=Dịch: Theo cuộc điều tra dân số gần nhất, dân số của thành phố đã tăng lên đáng kể.)","All households are required by law to complete the [census] form. (=Dịch: Tất cả các hộ gia đình theo luật đều phải hoàn thành phiếu điều tra dân số.)"],"ukAudio":"/ai_services/tts3/?q=census&lang=en-GB&ipa=%2F%CB%88s%C9%9Bn.s%C9%99s%2F","usAudio":"/ai_services/tts3/?q=census&lang=en-US&ipa=%2F%CB%88s%C9%9Bn.s%C9%99s%2F"},{"id":"lv_9_13","topic":"Technology and Natural Sciences","word":"chamber","pos":"(n)","ipa":"/ˈtʃeɪm.bɚ/","defVi":"phòng lớn, buồng, khoang kín","defEn":"a room used for a special purpose or an enclosed space in a machine or body","examples":["The council members gathered in the council [chamber] for the debate. (=Dịch: Các thành viên hội đồng đã tập trung tại phòng họp hội đồng để thảo luận.)","The patient was placed in a hyperbaric oxygen [chamber] to speed up recovery. (=Dịch: Bệnh nhân được đưa vào buồng oxy cao áp để đẩy nhanh quá trình hồi phục.)","Archaeologists discovered an ancient burial [chamber] deep inside the pyramid. (=Dịch: Các nhà khảo cổ học đã phát hiện một hầm mộ cổ sâu bên trong kim tự tháp.)"],"ukAudio":"/ai_services/tts3/?q=chamber&lang=en-GB&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=chamber&lang=en-US&ipa=%2F%CB%88t%CA%83e%C9%AAm.b%C9%9A%2F"},{"id":"lv_9_14","topic":"Technology and Natural Sciences","word":"charcoal","pos":"(n)","ipa":"/ˈtʃɑːr.koʊl/","defVi":"than củi, than hoa","defEn":"a hard black substance made by burning wood slowly, used as fuel or for drawing","examples":["We used [charcoal] to light the grill for our outdoor barbecue. (=Dịch: Chúng tôi đã dùng than củi để đốt lò nướng cho bữa tiệc thịt nướng ngoài trời.)","The artist drew a beautiful portrait using black [charcoal]. (=Dịch: Người họa sĩ đã vẽ một bức chân dung tuyệt đẹp bằng than vẽ.)","Activated [charcoal] is often used in water filters to remove impurities. (=Dịch: Than hoạt tính thường được sử dụng trong các bộ lọc nước để loại bỏ tạp chất.)"],"ukAudio":"/ai_services/tts3/?q=charcoal&lang=en-GB&ipa=%2F%CB%88t%CA%83%C9%91%CB%90r.ko%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=charcoal&lang=en-US&ipa=%2F%CB%88t%CA%83%C9%91%CB%90r.ko%CA%8Al%2F"},{"id":"lv_9_15","topic":"Technology and Natural Sciences","word":"competitor","pos":"(n)","ipa":"/kəmˈpet̬.ə.t̬ɚ/","defVi":"đối thủ cạnh tranh, người dự thi","defEn":"a person, team, or business that is trying to do better than others","examples":["The company lowered its prices to stay ahead of its main [competitor]. (=Dịch: Công ty đã giảm giá để đi trước đối thủ cạnh tranh chính của mình.)","Each [competitor] in the marathon was given a race number and water bottle. (=Dịch: Mỗi thí sinh trong cuộc đua marathon đều được cấp một số báo danh và chai nước.)","Technological innovation allows small firms to challenge a larger [competitor]. (=Dịch: Đổi mới công nghệ cho phép các công ty nhỏ cạnh tranh với đối thủ lớn hơn.)"],"ukAudio":"/ai_services/tts3/?q=competitor&lang=en-GB&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=competitor&lang=en-US&ipa=%2Fk%C9%99m%CB%88pet%CC%AC.%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_9_16","topic":"Technology and Natural Sciences","word":"consequence","pos":"(n)","ipa":"/ˈkɑːn.sə.kwens/","defVi":"hậu quả, hệ quả","defEn":"a result or effect of an action or condition","examples":["Rising sea levels are a direct [consequence] of global warming. (=Dịch: Mực nước biển dâng cao là hệ quả trực tiếp của hiện tượng ấm lên toàn cầu.)","He had to face the [consequence] of missing the final exam. (=Dịch: Cậu ấy phải đối mặt với hậu quả của việc bỏ lỡ kỳ thi cuối kỳ.)","Poor diet choices can have a serious [consequence] for long-term health. (=Dịch: Lựa chọn chế độ ăn uống kém có thể dẫn đến hậu quả nghiêm trọng cho sức khỏe lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=consequence&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kwens%2F","usAudio":"/ai_services/tts3/?q=consequence&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90n.s%C9%99.kwens%2F"},{"id":"lv_9_17","topic":"Technology and Natural Sciences","word":"cotton","pos":"(n)","ipa":"/ˈkɑː.tn/","defVi":"bông, vải cotton","defEn":"a soft white natural fiber grown on plants, used to make cloth","examples":["This shirt is made of one hundred percent organic [cotton]. (=Dịch: Chiếc áo sơ mi này được làm từ một trăm phần trăm bông hữu cơ.)","Farmers in this region have grown [cotton] for generations. (=Dịch: Nông dân ở vùng này đã trồng bông qua nhiều thế hệ.)","Clothes made from [cotton] are comfortable and breathable in hot weather. (=Dịch: Quần áo làm từ vải cotton rất thoải mái và thoáng mát trong thời tiết nóng.)"],"ukAudio":"/ai_services/tts3/?q=cotton&lang=en-GB&ipa=%2F%CB%88k%C9%91%CB%90.tn%2F","usAudio":"/ai_services/tts3/?q=cotton&lang=en-US&ipa=%2F%CB%88k%C9%91%CB%90.tn%2F"},{"id":"lv_9_18","topic":"Technology and Natural Sciences","word":"decoration","pos":"(n)","ipa":"/ˌdek.əˈreɪ.ʃən/","defVi":"đồ trang trí, sự trang trí","defEn":"the activity of making something look more attractive, or an object used for this","examples":["They put up colorful [decoration] for the holiday festival. (=Dịch: Họ đã treo đồ trang trí đầy màu sắc cho lễ hội ngày lễ.)","The interior [decoration] of the café creates a cozy atmosphere. (=Dịch: Cách trang trí nội thất của quán cà phê tạo nên một không gian ấm cúng.)","Handmade paper lanterns were used as [decoration] in the garden. (=Dịch: Những chiếc lồng đèn giấy thủ công đã được dùng làm đồ trang trí trong vườn.)"],"ukAudio":"/ai_services/tts3/?q=decoration&lang=en-GB&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=decoration&lang=en-US&ipa=%2F%CB%8Cdek.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_19","topic":"Technology and Natural Sciences","word":"detergent","pos":"(n)","ipa":"/dɪˈtɝː.dʒənt/","defVi":"chất tẩy rửa, bột giặt / nước giặt","defEn":"a chemical substance in liquid or powder form used for washing and cleaning","examples":["You should use a gentle laundry [detergent] when washing delicate silk garments. (=Dịch: Bạn nên sử dụng loại nước giặt dịu nhẹ khi giặt quần áo lụa mỏng manh.)","Eco-friendly [detergent] brands are gaining popularity among modern consumers. (=Dịch: Các thương hiệu chất tẩy rửa thân thiện với môi trường đang ngày càng được người tiêu dùng hiện đại ưa chuộng.)","A small capful of liquid [detergent] is enough to clean this entire load of dishes. (=Dịch: Một nắp nhỏ nước rửa bát là đủ để làm sạch toàn bộ số bát đĩa này.)"],"ukAudio":"/ai_services/tts3/?q=detergent&lang=en-GB&ipa=%2Fd%C9%AA%CB%88t%C9%9D%CB%90.d%CA%92%C9%99nt%2F","usAudio":"/ai_services/tts3/?q=detergent&lang=en-US&ipa=%2Fd%C9%AA%CB%88t%C9%9D%CB%90.d%CA%92%C9%99nt%2F"},{"id":"lv_9_20","topic":"Technology and Natural Sciences","word":"dishwasher","pos":"(n)","ipa":"/ˈdɪʃˌwɑː.ʃɚ/","defVi":"máy rửa bát","defEn":"an electric machine used for washing dishes automatically","examples":["Loading the [dishwasher] properly helps ensure everything gets clean. (=Dịch: Xếp đồ vào máy rửa bát đúng cách giúp đảm bảo mọi thứ đều được rửa sạch.)","Our new [dishwasher] is extremely quiet and energy-efficient. (=Dịch: Chiếc máy rửa bát mới của chúng tôi cực kỳ êm ái và tiết kiệm điện năng.)","She prefers using the [dishwasher] over washing plates by hand. (=Dịch: Cô ấy thích dùng máy rửa bát hơn là tự rửa đĩa bằng tay.)"],"ukAudio":"/ai_services/tts3/?q=dishwasher&lang=en-GB&ipa=%2F%CB%88d%C9%AA%CA%83%CB%8Cw%C9%91%CB%90.%CA%83%C9%9A%2F","usAudio":"/ai_services/tts3/?q=dishwasher&lang=en-US&ipa=%2F%CB%88d%C9%AA%CA%83%CB%8Cw%C9%91%CB%90.%CA%83%C9%9A%2F"},{"id":"lv_9_21","topic":"Technology and Natural Sciences","word":"drought","pos":"(n)","ipa":"/draʊt/","defVi":"hạn hán","defEn":"a long period of time when there is little or no rain","examples":["The severe [drought] destroyed most of the crops in the region. (=Dịch: Đợt hạn hán nghiêm trọng đã phá hủy phần lớn mùa màng trong khu vực.)","Farmers are struggling to survive during the prolonged [drought]. (=Dịch: Nông dân đang chật vật mưu sinh trong suốt đợt hạn hán kéo dài.)","Climate change has led to more frequent occurrences of [drought]. (=Dịch: Biến đổi khí hậu đã dẫn đến sự xuất hiện thường xuyên hơn của hạn hán.)"],"ukAudio":"/ai_services/tts3/?q=drought&lang=en-GB&ipa=%2Fdra%CA%8At%2F","usAudio":"/ai_services/tts3/?q=drought&lang=en-US&ipa=%2Fdra%CA%8At%2F"},{"id":"lv_9_22","topic":"Technology and Natural Sciences","word":"dye","pos":"(n)","ipa":"/daɪ/","defVi":"thuốc nhuộm, chất nhuộm màu","defEn":"a substance used to change the color of clothes, hair, or other materials","examples":["She used a natural plant [dye] to color the cotton fabric. (=Dịch: Cô ấy đã sử dụng thuốc nhuộm thực vật tự nhiên để nhuộm màu cho vải cotton.)","The bright red [dye] began to fade after several washes. (=Dịch: Chất nhuộm màu đỏ tươi bắt đầu phai dần sau vài lần giặt.)","Some artificial food [dyes] have been banned due to health concerns. (=Dịch: Một số loại phẩm màu nhân tạo đã bị cấm vì những lo ngại về sức khỏe.)"],"ukAudio":"/ai_services/tts3/?q=dye&lang=en-GB&ipa=%2Fda%C9%AA%2F","usAudio":"/ai_services/tts3/?q=dye&lang=en-US&ipa=%2Fda%C9%AA%2F"},{"id":"lv_9_23","topic":"Technology and Natural Sciences","word":"economical","pos":"(adj)","ipa":"/ˌiː.kəˈnɑː.mɪ.kəl/","defVi":"tiết kiệm, kinh tế","defEn":"providing good value or using money, resources, or time carefully","examples":["Small cars are usually more [economical] to run than large ones. (=Dịch: Xe ô tô nhỏ thường tiết kiệm chi phí vận hành hơn xe lớn.)","She found an [economical] way to heat her home during the winter. (=Dịch: Cô ấy đã tìm ra một cách tiết kiệm để sưởi ấm ngôi nhà vào mùa đông.)","Buying in bulk is often a more [economical] choice for large families. (=Dịch: Mua số lượng lớn thường là lựa chọn tiết kiệm hơn cho các gia đình đông người.)"],"ukAudio":"/ai_services/tts3/?q=economical&lang=en-GB&ipa=%2F%CB%8Ci%CB%90.k%C9%99%CB%88n%C9%91%CB%90.m%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=economical&lang=en-US&ipa=%2F%CB%8Ci%CB%90.k%C9%99%CB%88n%C9%91%CB%90.m%C9%AA.k%C9%99l%2F"},{"id":"lv_9_24","topic":"Technology and Natural Sciences","word":"entire","pos":"(adj)","ipa":"/ɪnˈtaɪ.ɚ/","defVi":"toàn bộ, toàn vẹn","defEn":"including everything, everyone, or every part; whole","examples":["He spent the [entire] afternoon reading a novel in the library. (=Dịch: Anh ấy đã dành toàn bộ buổi chiều để đọc một cuốn tiểu thuyết trong thư viện.)","The [entire] staff attended the mandatory training session on workplace safety. (=Dịch: Toàn bộ nhân viên đã tham dự buổi đào tạo bắt buộc về an toàn lao động.)","A sudden power outage left the [entire] neighborhood in complete darkness. (=Dịch: Sự cố mất điện đột ngột đã khiến toàn bộ khu phố chìm trong bóng tối hoàn toàn.)"],"ukAudio":"/ai_services/tts3/?q=entire&lang=en-GB&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F","usAudio":"/ai_services/tts3/?q=entire&lang=en-US&ipa=%2F%C9%AAn%CB%88ta%C9%AA.%C9%9A%2F"},{"id":"lv_9_25","topic":"Technology and Natural Sciences","word":"fabric","pos":"(n)","ipa":"/ˈfæb.rɪk/","defVi":"vải, sợi vải","defEn":"cloth or material produced by weaving or knitting","examples":["Cotton is a natural [fabric] that is comfortable to wear in summer. (=Dịch: Bông là loại vải tự nhiên mang lại cảm giác thoải mái khi mặc vào mùa hè.)","This waterproof [fabric] is ideal for making outdoor jackets. (=Dịch: Loại vải chống thấm nước này rất lý tưởng để may áo khoác ngoài trời.)","The delicate [fabric] must be washed by hand to avoid damage. (=Dịch: Loại vải mỏng manh này phải được giặt bằng tay để tránh hư hại.)"],"ukAudio":"/ai_services/tts3/?q=fabric&lang=en-GB&ipa=%2F%CB%88f%C3%A6b.r%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=fabric&lang=en-US&ipa=%2F%CB%88f%C3%A6b.r%C9%AAk%2F"},{"id":"lv_9_26","topic":"Technology and Natural Sciences","word":"famine","pos":"(n)","ipa":"/ˈfæm.ɪn/","defVi":"nạn đói","defEn":"an extreme shortage of food that causes widespread hunger","examples":["The war resulted in widespread [famine] across the nation. (=Dịch: Chiến tranh đã dẫn đến nạn đói lan rộng khắp cả nước.)","International aid was sent to prevent a catastrophic [famine]. (=Dịch: Viện trợ quốc tế đã được gửi đến nhằm ngăn chặn một nạn đói thảm khốc.)","Thousands of people suffered from malnutrition during the great [famine]. (=Dịch: Hàng nghìn người đã bị suy dinh dưỡng trong suốt nạn đói lớn.)"],"ukAudio":"/ai_services/tts3/?q=famine&lang=en-GB&ipa=%2F%CB%88f%C3%A6m.%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=famine&lang=en-US&ipa=%2F%CB%88f%C3%A6m.%C9%AAn%2F"},{"id":"lv_9_27","topic":"Technology and Natural Sciences","word":"fence","pos":"(n)","ipa":"/fɛns/","defVi":"hàng rào","defEn":"a barrier that surrounds an area of land to keep people or animals in or out","examples":["They built a wooden [fence] around their garden to keep animals out. (=Dịch: Họ đã dựng một hàng rào gỗ quanh vườn để ngăn động vật vào.)","The dog jumped over the low [fence] and ran into the street. (=Dịch: Con chó nhảy qua hàng rào thấp và chạy ra đường.)","A tall metal [fence] separates the two properties. (=Dịch: Một hàng rào kim loại cao ngăn cách giữa hai khu đất.)"],"ukAudio":"/ai_services/tts3/?q=fence&lang=en-GB&ipa=%2Ff%C9%9Bns%2F","usAudio":"/ai_services/tts3/?q=fence&lang=en-US&ipa=%2Ff%C9%9Bns%2F"},{"id":"lv_9_28","topic":"Technology and Natural Sciences","word":"fibre","pos":"(n)","ipa":"/ˈfaɪ.bɚ/","defVi":"sợi, chất xơ","defEn":"a thin thread of natural or artificial material, or the parts of food that cannot be digested","examples":["Eating food that is high in [fibre] helps maintain a healthy digestion. (=Dịch: Ăn thực phẩm giàu chất xơ giúp duy trì hệ tiêu hóa khỏe mạnh.)","Nylon is a strong synthetic [fibre] used to produce clothing and ropes. (=Dịch: Nilon là một loại sợi tổng hợp bền chắc được dùng để sản xuất quần áo và dây thừng.)","Optic [fibre] cables allow internet data to travel at high speeds. (=Dịch: Cáp sợi quang cho phép dữ liệu internet truyền đi với tốc độ cao.)"],"ukAudio":"/ai_services/tts3/?q=fibre&lang=en-GB&ipa=%2F%CB%88fa%C9%AA.b%C9%9A%2F","usAudio":"/ai_services/tts3/?q=fibre&lang=en-US&ipa=%2F%CB%88fa%C9%AA.b%C9%9A%2F"},{"id":"lv_9_29","topic":"Technology and Natural Sciences","word":"float","pos":"(v)","ipa":"/floʊt/","defVi":"nổi, trôi bồng bềnh","defEn":"to stay on the surface of a liquid and not sink","examples":["Wood will naturally [float] on water because it is less dense. (=Dịch: Gỗ sẽ tự nhiên nổi trên mặt nước vì có khối lượng riêng nhỏ hơn.)","Bright red balloons began to [float] up into the sky. (=Dịch: Những quả bóng bay màu đỏ tươi bắt đầu trôi bồng bềnh lên bầu trời.)","She learned how to [float] on her back during swimming lessons. (=Dịch: Cô ấy đã học cách thả nổi ngửa người trong các buổi học bơi.)"],"ukAudio":"/ai_services/tts3/?q=float&lang=en-GB&ipa=%2Fflo%CA%8At%2F","usAudio":"/ai_services/tts3/?q=float&lang=en-US&ipa=%2Fflo%CA%8At%2F"},{"id":"lv_9_30","topic":"Technology and Natural Sciences","word":"freeze","pos":"(v)","ipa":"/friz/","defVi":"đóng băng, đông cứng","defEn":"to turn into ice or become hard because of extreme cold","examples":["Water will [freeze] at zero degrees Celsius. (=Dịch: Nước sẽ đóng băng ở nhiệt độ không độ C.)","You can [freeze] the leftover food to preserve it for next week. (=Dịch: Bạn có thể đông lạnh thức ăn thừa để bảo quản cho tuần tới.)","The lake began to [freeze] as temperatures dropped drastically. (=Dịch: Mặt hồ bắt đầu đóng băng khi nhiệt độ giảm mạnh.)"],"ukAudio":"/ai_services/tts3/?q=freeze&lang=en-GB&ipa=%2Ffriz%2F","usAudio":"/ai_services/tts3/?q=freeze&lang=en-US&ipa=%2Ffriz%2F"},{"id":"lv_9_31","topic":"Technology and Natural Sciences","word":"generation","pos":"(n)","ipa":"/ˌdʒɛn.əˈreɪ.ʃən/","defVi":"thế hệ","defEn":"all the people of about the same age within a society","examples":["The older [generation] often has different views on technology than the youth. (=Dịch: Thế hệ lớn tuổi thường có quan điểm về công nghệ khác với giới trẻ.)","This family recipe has been passed down from [generation] to generation. (=Dịch: Công thức nấu ăn của gia đình này đã được truyền từ thế hệ này sang thế hệ khác.)","They are fighting to preserve the environment for the next [generation]. (=Dịch: Họ đang đấu tranh để bảo vệ môi trường cho thế hệ tương lai.)"],"ukAudio":"/ai_services/tts3/?q=generation&lang=en-GB&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=generation&lang=en-US&ipa=%2F%CB%8Cd%CA%92%C9%9Bn.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_32","topic":"Technology and Natural Sciences","word":"geographer","pos":"(n)","ipa":"/dʒiˈɑː.ɡrə.fər/","defVi":"nhà địa lý học","defEn":"a scientist who studies the Earth's physical features and human population","examples":["The [geographer] created detailed maps of the newly discovered island. (=Dịch: Nhà địa lý học đã tạo ra những bản đồ chi tiết về hòn đảo mới được phát hiện.)","As a [geographer], she studies how urban areas expand over time. (=Dịch: Là một nhà địa lý học, cô ấy nghiên cứu cách các khu vực đô thị mở rộng theo thời gian.)","The team of [geographer] experts analyzed the effects of soil erosion. (=Dịch: Đội ngũ các chuyên gia địa lý đã phân tích tác động của xói mòn đất.)"],"ukAudio":"/ai_services/tts3/?q=geographer&lang=en-GB&ipa=%2Fd%CA%92i%CB%88%C9%91%CB%90.%C9%A1r%C9%99.f%C9%99r%2F","usAudio":"/ai_services/tts3/?q=geographer&lang=en-US&ipa=%2Fd%CA%92i%CB%88%C9%91%CB%90.%C9%A1r%C9%99.f%C9%99r%2F"},{"id":"lv_9_33","topic":"Technology and Natural Sciences","word":"heading","pos":"(n)","ipa":"/ˈhɛd.ɪŋ/","defVi":"tiêu đề, đề mục","defEn":"a title at the top of a page, chapter, or section of a text","examples":["You should write a clear [heading] for each paragraph in your essay. (=Dịch: Bạn nên viết một tiêu đề rõ ràng cho từng đoạn văn trong bài luận của mình.)","The main [heading] was printed in bold letters at the top of the report. (=Dịch: Tiêu đề chính được in đậm ở đầu bản báo cáo.)","Subsections under the same [heading] provide more detailed explanations. (=Dịch: Các phần phụ dưới cùng một tiêu đề cung cấp những lời giải thích chi tiết hơn.)"],"ukAudio":"/ai_services/tts3/?q=heading&lang=en-GB&ipa=%2F%CB%88h%C9%9Bd.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=heading&lang=en-US&ipa=%2F%CB%88h%C9%9Bd.%C9%AA%C5%8B%2F"},{"id":"lv_9_34","topic":"Technology and Natural Sciences","word":"hectare","pos":"(n)","ipa":"/ˈhek.tɛr/","defVi":"héc-ta (đơn vị đo diện tích bằng 10.000 mét vuông)","defEn":"a unit of measurement for land equal to 10,000 square meters","examples":["The farm covers an area of about fifty [hectares]. (=Dịch: Trang trại trải rộng trên diện tích khoảng năm mươi héc-ta.)","Thousands of [hectares] of forest were destroyed by the wildfire. (=Dịch: Hàng nghìn héc-ta rừng đã bị thiêu rụi bởi trận cháy rừng.)","They bought a [hectare] of land to build a new community center. (=Dịch: Họ đã mua một héc-ta đất để xây dựng một trung tâm cộng đồng mới.)"],"ukAudio":"/ai_services/tts3/?q=hectare&lang=en-GB&ipa=%2F%CB%88hek.t%C9%9Br%2F","usAudio":"/ai_services/tts3/?q=hectare&lang=en-US&ipa=%2F%CB%88hek.t%C9%9Br%2F"},{"id":"lv_9_35","topic":"Technology and Natural Sciences","word":"honest","pos":"(adj)","ipa":"/ˈɑː.nɪst/","defVi":"thành thật, trung thực","defEn":"telling the truth and not cheating or lying","examples":["Please give me your [honest] opinion about this design. (=Dịch: Xin vui lòng cho tôi biết ý kiến trung thực của bạn về thiết kế này.)","He is an [honest] businessman who treats all his clients fairly. (=Dịch: Ông ấy là một doanh nhân trung thực, luôn đối xử công bằng với tất cả khách hàng của mình.)","To be completely [honest], I did not enjoy the movie very much. (=Dịch: Thành thật mà nói, tôi không thích bộ phim đó cho lắm.)"],"ukAudio":"/ai_services/tts3/?q=honest&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F","usAudio":"/ai_services/tts3/?q=honest&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.n%C9%AAst%2F"},{"id":"lv_9_36","topic":"Technology and Natural Sciences","word":"icehouse","pos":"(n)","ipa":"/ˈaɪs.haʊs/","defVi":"nhà chứa băng, hầm giữ băng tuyết","defEn":"a building or structure used for storing ice before modern refrigeration was invented","examples":["In the nineteenth century, every large estate had an [icehouse] to preserve food. (=Dịch: Vào thế kỷ 19, mỗi dinh thự lớn đều có một hầm giữ băng để bảo quản thực phẩm.)","Workers carried large blocks of ice from the river directly to the [icehouse]. (=Dịch: Các công nhân đã vận chuyển những tảng băng lớn từ sông thẳng đến nhà chứa băng.)","The old [icehouse] was built deep underground to keep the temperature cold. (=Dịch: Hầm chứa băng cũ được xây sâu dưới lòng đất để duy trì nhiệt độ lạnh.)"],"ukAudio":"/ai_services/tts3/?q=icehouse&lang=en-GB&ipa=%2F%CB%88a%C9%AAs.ha%CA%8As%2F","usAudio":"/ai_services/tts3/?q=icehouse&lang=en-US&ipa=%2F%CB%88a%C9%AAs.ha%CA%8As%2F"},{"id":"lv_9_37","topic":"Technology and Natural Sciences","word":"importantly","pos":"(adv)","ipa":"/ɪmˈpɔːr.tənt.li/","defVi":"quan trọng là, một cách quan trọng","defEn":"used to emphasize a point that is of great significance","examples":["More [importantly], we must ensure the safety of all participants. (=Dịch: Quan trọng hơn, chúng ta phải đảm bảo an toàn cho tất cả những người tham gia.)","The project finished on schedule and, most [importantly], within budget. (=Dịch: Dự án đã hoàn thành đúng tiến độ và quan trọng nhất là trong phạm vi ngân sách.)","She gained valuable experience and, [importantly], made lasting friendships. (=Dịch: Cô ấy đã tích lũy được kinh nghiệm quý báu và quan trọng là xây dựng được những tình bạn lâu dài.)"],"ukAudio":"/ai_services/tts3/?q=importantly&lang=en-GB&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F","usAudio":"/ai_services/tts3/?q=importantly&lang=en-US&ipa=%2F%C9%AAm%CB%88p%C9%94%CB%90r.t%C9%99nt.li%2F"},{"id":"lv_9_38","topic":"Technology and Natural Sciences","word":"innovative","pos":"(adj)","ipa":"/ˈɪn.ə.veɪ.t̬ɪv/","defVi":"đổi mới, mang tính sáng tạo","defEn":"introducing new ideas or methods","examples":["The startup developed an [innovative] solution for plastic waste management. (=Dịch: Công ty khởi nghiệp đã phát triển một giải pháp sáng tạo để quản lý rác thải nhựa.)","She won an award for her [innovative] teaching techniques. (=Dịch: Cô ấy đã giành giải thưởng nhờ các phương pháp giảng dạy đổi mới của mình.)","Engineers are designing [innovative] cars powered entirely by hydrogen. (=Dịch: Các kỹ sư đang thiết kế những chiếc xe hơi mang tính đổi mới chạy hoàn toàn bằng hydro.)"],"ukAudio":"/ai_services/tts3/?q=innovative&lang=en-GB&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%CC%AC%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=innovative&lang=en-US&ipa=%2F%CB%88%C9%AAn.%C9%99.ve%C9%AA.t%CC%AC%C9%AAv%2F"},{"id":"lv_9_39","topic":"Technology and Natural Sciences","word":"insert","pos":"(v)","ipa":"/ɪnˈsɝːt/","defVi":"chèn, đưa vào, lồng vào","defEn":"to put something into something else","examples":["Please [insert] your card into the machine and enter your PIN. (=Dịch: Vui lòng đưa thẻ của bạn vào máy và nhập mã PIN.)","You can [insert] images and charts directly into your presentation slides. (=Dịch: Bạn có thể chèn hình ảnh và biểu đồ trực tiếp vào các trang trình chiếu của mình.)","The doctor will [insert] a small tube to help drain the fluid. (=Dịch: Bác sĩ sẽ đưa một ống nhỏ vào để giúp dẫn lưu chất lỏng.)"],"ukAudio":"/ai_services/tts3/?q=insert&lang=en-GB&ipa=%2F%C9%AAn%CB%88s%C9%9D%CB%90t%2F","usAudio":"/ai_services/tts3/?q=insert&lang=en-US&ipa=%2F%C9%AAn%CB%88s%C9%9D%CB%90t%2F"},{"id":"lv_9_40","topic":"Technology and Natural Sciences","word":"investigation","pos":"(n)","ipa":"/ɪnˌvɛs.təˈɡeɪ.ʃən/","defVi":"cuộc điều tra, nghiên cứu kỹ lưỡng","defEn":"an official examination or inquiry into something, such as a crime or problem","examples":["The police launched a thorough [investigation] into the cause of the fire. (=Dịch: Cảnh sát đã mở một cuộc điều tra kỹ lưỡng về nguyên nhân của vụ hỏa hoạn.)","The scientific [investigation] revealed unexpected results about the disease. (=Dịch: Cuộc nghiên cứu khoa học đã tiết lộ những kết quả bất ngờ về căn bệnh này.)","The journalist conducted an independent [investigation] into local government corruption. (=Dịch: Nhà báo đã thực hiện một cuộc điều tra độc lập về nạn tham nhũng tại chính quyền địa phương.)"],"ukAudio":"/ai_services/tts3/?q=investigation&lang=en-GB&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=investigation&lang=en-US&ipa=%2F%C9%AAn%CB%8Cv%C9%9Bs.t%C9%99%CB%88%C9%A1e%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_41","topic":"Technology and Natural Sciences","word":"liquid","pos":"(n)","ipa":"/ˈlɪk.wɪd/","defVi":"chất lỏng","defEn":"a substance that flows freely and is neither a solid nor a gas","examples":["Water turns into a clear [liquid] when ice melts at room temperature. (=Dịch: Nước chuyển thành chất lỏng trong suốt khi đá tan ở nhiệt độ phòng.)","Airport security regulations restrict passengers from carrying large bottles of [liquid]. (=Dịch: Quy định an ninh sân bay hạn chế hành khách mang theo các chai chất lỏng lớn.)","The chemist carefully poured the blue [liquid] into a glass beaker. (=Dịch: Nhà hóa học cẩn thận đổ chất lỏng màu xanh vào một cốc thủy tinh thí nghiệm.)"],"ukAudio":"/ai_services/tts3/?q=liquid&lang=en-GB&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=liquid&lang=en-US&ipa=%2F%CB%88l%C9%AAk.w%C9%AAd%2F"},{"id":"lv_9_42","topic":"Technology and Natural Sciences","word":"meteorological","pos":"(adj)","ipa":"/ˌmiː.ti.ə.rəˈlɑː.dʒɪ.kəl/","defVi":"(thuộc) khí tượng học","defEn":"relating to the weather and atmospheric conditions","examples":["The [meteorological] office issued a severe storm warning yesterday. (=Dịch: Cơ quan khí tượng đã phát đi cảnh báo bão lớn vào ngày hôm qua.)","Scientists use [meteorological] data to predict global weather patterns. (=Dịch: Các nhà khoa học sử dụng dữ liệu khí tượng để dự đoán các hình thái thời tiết toàn cầu.)","Advanced [meteorological] instruments help track the path of typhoons. (=Dịch: Các thiết bị khí tượng tiên tiến giúp theo dõi đường đi của những cơn bão lớn.)"],"ukAudio":"/ai_services/tts3/?q=meteorological&lang=en-GB&ipa=%2F%CB%8Cmi%CB%90.ti.%C9%99.r%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=meteorological&lang=en-US&ipa=%2F%CB%8Cmi%CB%90.ti.%C9%99.r%C9%99%CB%88l%C9%91%CB%90.d%CA%92%C9%AA.k%C9%99l%2F"},{"id":"lv_9_43","topic":"Technology and Natural Sciences","word":"military","pos":"(adj)","ipa":"/ˈmɪl.əˌtɛr.i/","defVi":"thuộc về quân đội, quân sự","defEn":"relating to the armed forces or soldiers","examples":["He decided to pursue a [military] career after graduating from high school. (=Dịch: Anh ấy quyết định theo đuổi sự nghiệp quân sự sau khi tốt nghiệp trung học.)","The government increased its [military] spending this year. (=Dịch: Chính phủ đã tăng chi tiêu quân sự trong năm nay.)","They were wearing traditional [military] uniforms during the parade. (=Dịch: Họ mặc quân phục truyền thống trong suốt buổi diễu binh.)"],"ukAudio":"/ai_services/tts3/?q=military&lang=en-GB&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Ct%C9%9Br.i%2F","usAudio":"/ai_services/tts3/?q=military&lang=en-US&ipa=%2F%CB%88m%C9%AAl.%C9%99%CB%8Ct%C9%9Br.i%2F"},{"id":"lv_9_44","topic":"Technology and Natural Sciences","word":"monitor","pos":"(v)","ipa":"/ˈmɑː.nə.t̬ɚ/","defVi":"theo dõi, giám sát","defEn":"to observe and check the progress or quality of something over time","examples":["Doctors will carefully [monitor] the patient's heart rate after surgery. (=Dịch: Các bác sĩ sẽ theo dõi cẩn thận nhịp tim của bệnh nhân sau phẫu thuật.)","Scientists use satellites to [monitor] climate changes across the globe. (=Dịch: Các nhà khoa học sử dụng vệ tinh để giám sát những biến đổi khí hậu trên toàn cầu.)","The government set up cameras to [monitor] traffic on the main bridge. (=Dịch: Chính quyền đã lắp đặt camera để theo dõi tình hình giao thông trên cây cầu chính.)"],"ukAudio":"/ai_services/tts3/?q=monitor&lang=en-GB&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%99.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=monitor&lang=en-US&ipa=%2F%CB%88m%C9%91%CB%90.n%C9%99.t%CC%AC%C9%9A%2F"},{"id":"lv_9_45","topic":"Technology and Natural Sciences","word":"nylon","pos":"(n)","ipa":"/ˈnaɪ.lɑːn/","defVi":"ni-lông, sợi tổng hợp ni-lông","defEn":"a strong, lightweight, synthetic material used for making clothes, ropes, and other items","examples":["Climbing ropes are usually made of strong [nylon] fibers to ensure safety. (=Dịch: Dây leo núi thường được làm từ sợi ni-lông chắc chắn để đảm bảo an toàn.)","The lightweight jacket is crafted from waterproof [nylon] to protect hikers from rain. (=Dịch: Chiếc áo khoác nhẹ được làm từ ni-lông chống thấm nước để bảo vệ người đi bộ đường dài khỏi mưa.)","Toothbrush bristles were originally made from animal hair before [nylon] was invented. (=Dịch: Lông bàn chải đánh răng ban đầu được làm từ lông động vật trước khi ni-lông được phát minh.)"],"ukAudio":"/ai_services/tts3/?q=nylon&lang=en-GB&ipa=%2F%CB%88na%C9%AA.l%C9%91%CB%90n%2F","usAudio":"/ai_services/tts3/?q=nylon&lang=en-US&ipa=%2F%CB%88na%C9%AA.l%C9%91%CB%90n%2F"},{"id":"lv_9_46","topic":"Technology and Natural Sciences","word":"operational","pos":"(adj)","ipa":"/ˌɑː.pəˈreɪ.ʃən.əl/","defVi":"sẵn sàng hoạt động, thuộc về vận hành","defEn":"ready to be used, functioning, or relating to the operation of something","examples":["The new railway line will become fully [operational] next month. (=Dịch: Tuyến đường sắt mới sẽ bắt đầu đi vào hoạt động hoàn toàn vào tháng tới.)","The company reduced its [operational] costs by automating several tasks. (=Dịch: Công ty đã giảm chi phí vận hành bằng cách tự động hóa một số nhiệm vụ.)","All security systems are currently [operational] and monitoring the building. (=Dịch: Tất cả hệ thống an ninh hiện đang hoạt động và giám sát tòa nhà.)"],"ukAudio":"/ai_services/tts3/?q=operational&lang=en-GB&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F","usAudio":"/ai_services/tts3/?q=operational&lang=en-US&ipa=%2F%CB%8C%C9%91%CB%90.p%C9%99%CB%88re%C9%AA.%CA%83%C9%99n.%C9%99l%2F"},{"id":"lv_9_47","topic":"Technology and Natural Sciences","word":"operator","pos":"(n)","ipa":"/ˈɑː.pə.reɪ.t̬ɚ/","defVi":"người vận hành, nhân viên trực tổng đài","defEn":"a person who operates a machine, system, or business","examples":["The crane [operator] lifted the heavy steel beam onto the roof. (=Dịch: Người vận hành cần cẩu đã nâng thanh dầm thép nặng lên mái nhà.)","Please dial zero to speak directly with the telephone [operator]. (=Dịch: Vui lòng bấm số 0 để nói chuyện trực tiếp với nhân viên trực tổng đài.)","The tour [operator] organized all transportation and hotel bookings for our trip. (=Dịch: Đơn vị điều hành tour đã sắp xếp toàn bộ phương tiện đi lại và đặt phòng khách sạn cho chuyến đi của chúng tôi.)"],"ukAudio":"/ai_services/tts3/?q=operator&lang=en-GB&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99.re%C9%AA.t%CC%AC%C9%9A%2F","usAudio":"/ai_services/tts3/?q=operator&lang=en-US&ipa=%2F%CB%88%C9%91%CB%90.p%C9%99.re%C9%AA.t%CC%AC%C9%9A%2F"},{"id":"lv_9_48","topic":"Technology and Natural Sciences","word":"orbit","pos":"(n)","ipa":"/ˈɔːr.bɪt/","defVi":"quỹ đạo","defEn":"the curved path that a planet, moon, or spacecraft follows around another object","examples":["The Earth takes about one year to complete its [orbit] around the sun. (=Dịch: Trái Đất mất khoảng một năm để hoàn thành một vòng quỹ đạo quanh mặt trời.)","The space station is currently in low Earth [orbit]. (=Dịch: Trạm vũ trụ hiện đang ở trên quỹ đạo tầm thấp của Trái Đất.)","Debris in [orbit] poses a serious threat to working spacecraft. (=Dịch: Các mảnh rác trên quỹ đạo tạo ra mối đe dọa nghiêm trọng đối với các tàu vũ trụ đang hoạt động.)"],"ukAudio":"/ai_services/tts3/?q=orbit&lang=en-GB&ipa=%2F%CB%88%C9%94%CB%90r.b%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=orbit&lang=en-US&ipa=%2F%CB%88%C9%94%CB%90r.b%C9%AAt%2F"},{"id":"lv_9_49","topic":"Technology and Natural Sciences","word":"ozone","pos":"(n)","ipa":"/ˈoʊ.zoʊn/","defVi":"khí ô-dôn","defEn":"a form of oxygen that is harmful at ground level but protects the Earth in the upper atmosphere","examples":["The [ozone] layer protects living organisms from harmful ultraviolet radiation. (=Dịch: Tầng ô-dôn bảo vệ các sinh vật sống khỏi bức xạ cực tím có hại.)","Chemical pollutants have caused serious damage to the [ozone] layer. (=Dịch: Các chất ô nhiễm hóa học đã gây tổn hại nghiêm trọng đến tầng ô-dôn.)","High levels of ground-level [ozone] can cause respiratory problems in humans. (=Dịch: Hàm lượng ô-dôn ở tầng mặt đất cao có thể gây ra các vấn đề về đường hô hấp ở người.)"],"ukAudio":"/ai_services/tts3/?q=ozone&lang=en-GB&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F","usAudio":"/ai_services/tts3/?q=ozone&lang=en-US&ipa=%2F%CB%88o%CA%8A.zo%CA%8An%2F"},{"id":"lv_9_50","topic":"Technology and Natural Sciences","word":"particle","pos":"(n)","ipa":"/ˈpɑːr.t̬ɪ.kəl/","defVi":"hạt, phân tử, mảnh nhỏ","defEn":"a very small piece of matter or substance","examples":["Air filters can trap harmful dust [particles] inside your home. (=Dịch: Bộ lọc không khí có thể giữ lại các hạt bụi có hại trong nhà của bạn.)","Scientists study subatomic [particles] to understand the laws of physics. (=Dịch: Các nhà khoa học nghiên cứu các hạt hạ nguyên tử để hiểu các quy luật vật lý.)","There is not a single [particle] of truth in what he said. (=Dịch: Không có lấy một chút sự thật nào trong những gì anh ta nói.)"],"ukAudio":"/ai_services/tts3/?q=particle&lang=en-GB&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F","usAudio":"/ai_services/tts3/?q=particle&lang=en-US&ipa=%2F%CB%88p%C9%91%CB%90r.t%CC%AC%C9%AA.k%C9%99l%2F"},{"id":"lv_9_51","topic":"Technology and Natural Sciences","word":"perspective","pos":"(n)","ipa":"/pɚˈspek.tɪv/","defVi":"góc nhìn, quan điểm","defEn":"a particular way of viewing or thinking about something","examples":["Traveling abroad gave her a whole new [perspective] on life. (=Dịch: Đi du lịch nước ngoài đã mang lại cho cô ấy một góc nhìn hoàn toàn mới về cuộc sống.)","We must consider the problem from the customer's [perspective]. (=Dịch: Chúng ta phải xem xét vấn đề từ quan điểm của khách hàng.)","Talking to a mentor helped put his worries into [perspective]. (=Dịch: Nói chuyện với người cố vấn đã giúp anh ấy nhìn nhận lại những lo lắng của mình một cách đúng đắn.)"],"ukAudio":"/ai_services/tts3/?q=perspective&lang=en-GB&ipa=%2Fp%C9%9A%CB%88spek.t%C9%AAv%2F","usAudio":"/ai_services/tts3/?q=perspective&lang=en-US&ipa=%2Fp%C9%9A%CB%88spek.t%C9%AAv%2F"},{"id":"lv_9_52","topic":"Technology and Natural Sciences","word":"phase","pos":"(n)","ipa":"/feɪz/","defVi":"giai đoạn, thời kỳ","defEn":"a distinct period or stage in a process of development or change","examples":["The construction project is now entering its final [phase]. (=Dịch: Dự án xây dựng hiện đang bước vào giai đoạn cuối cùng.)","Children often go through a difficult [phase] during their teenage years. (=Dịch: Trẻ em thường trải qua một giai đoạn khó khăn trong những năm tháng tuổi vị thành niên.)","The research will be conducted in three separate [phases]. (=Dịch: Nghiên cứu sẽ được tiến hành theo ba giai đoạn riêng biệt.)"],"ukAudio":"/ai_services/tts3/?q=phase&lang=en-GB&ipa=%2Ffe%C9%AAz%2F","usAudio":"/ai_services/tts3/?q=phase&lang=en-US&ipa=%2Ffe%C9%AAz%2F"},{"id":"lv_9_53","topic":"Technology and Natural Sciences","word":"pit","pos":"(n)","ipa":"/ˈpɪt/","defVi":"hố sâu, hầm","defEn":"a large deep hole in the ground","examples":["The workers dug a deep [pit] to lay the foundation of the house. (=Dịch: Các công nhân đã đào một cái hố sâu để đặt móng nhà.)","Be careful not to fall into the gravel [pit]. (=Dịch: Hãy cẩn thận kẻo rơi vào hố sỏi.)","Coal was extracted from the open [pit] mine. (=Dịch: Than đá đã được khai thác từ mỏ lộ thiên.)"],"ukAudio":"/ai_services/tts3/?q=pit&lang=en-GB&ipa=%2F%CB%88p%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=pit&lang=en-US&ipa=%2F%CB%88p%C9%AAt%2F"},{"id":"lv_9_54","topic":"Technology and Natural Sciences","word":"plain","pos":"(adj)","ipa":"/pleɪn/","defVi":"đơn giản, mộc mạc, không cầu kỳ","defEn":"simple and not decorated or complicated","examples":["She preferred to wear a [plain] white shirt for the interview. (=Dịch: Cô ấy thích mặc một chiếc áo sơ mi trắng trơn cho buổi phỏng vấn.)","The instructions were written in [plain] language so everyone could understand. (=Dịch: Các hướng dẫn được viết bằng ngôn ngữ đơn giản để mọi người đều có thể hiểu.)","The room was furnished with [plain] wooden tables and chairs. (=Dịch: Căn phòng được trang bị bàn ghế gỗ mộc mạc.)"],"ukAudio":"/ai_services/tts3/?q=plain&lang=en-GB&ipa=%2Fple%C9%AAn%2F","usAudio":"/ai_services/tts3/?q=plain&lang=en-US&ipa=%2Fple%C9%AAn%2F"},{"id":"lv_9_55","topic":"Technology and Natural Sciences","word":"prediction","pos":"(n)","ipa":"/prɪˈdɪk.ʃən/","defVi":"sự dự đoán, lời tiên đoán","defEn":"a statement about what you think will happen in the future","examples":["Scientists made an accurate [prediction] about the path of the incoming hurricane. (=Dịch: Các nhà khoa học đã đưa ra dự đoán chính xác về đường đi của cơn bão sắp tới.)","His pessimistic [prediction] regarding the company's financial growth turned out to be false. (=Dịch: Dự đoán bi quan của anh ấy về sự tăng trưởng tài chính của công ty hóa ra lại sai.)","Technological advancements make weather [prediction] much more reliable than before. (=Dịch: Những tiến bộ công nghệ làm cho việc dự báo thời tiết trở nên đáng tin cậy hơn nhiều so với trước đây.)"],"ukAudio":"/ai_services/tts3/?q=prediction&lang=en-GB&ipa=%2Fpr%C9%AA%CB%88d%C9%AAk.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=prediction&lang=en-US&ipa=%2Fpr%C9%AA%CB%88d%C9%AAk.%CA%83%C9%99n%2F"},{"id":"lv_9_56","topic":"Technology and Natural Sciences","word":"proposal","pos":"(n)","ipa":"/prəˈpoʊ.zəl/","defVi":"đề xuất, bản đề án","defEn":"a formal plan or suggestion presented to others for consideration","examples":["The committee rejected the budget [proposal] submitted by the manager. (=Dịch: Ủy ban đã bác bỏ đề xuất ngân sách do người quản lý đệ trình.)","She wrote a detailed research [proposal] to apply for the grant. (=Dịch: Cô ấy đã viết một đề cương nghiên cứu chi tiết để xin tài trợ.)","The government announced a new [proposal] to improve public transport. (=Dịch: Chính phủ đã công bố một đề xuất mới nhằm cải thiện giao thông công cộng.)"],"ukAudio":"/ai_services/tts3/?q=proposal&lang=en-GB&ipa=%2Fpr%C9%99%CB%88po%CA%8A.z%C9%99l%2F","usAudio":"/ai_services/tts3/?q=proposal&lang=en-US&ipa=%2Fpr%C9%99%CB%88po%CA%8A.z%C9%99l%2F"},{"id":"lv_9_57","topic":"Technology and Natural Sciences","word":"pump","pos":"(v)","ipa":"/pʌmp/","defVi":"bơm, hút (chất lỏng hoặc khí)","defEn":"to force liquid or gas to move in a particular direction using a mechanical device","examples":["Firefighters had to [pump] water from a nearby lake to extinguish the blaze. (=Dịch: Lính cứu hỏa đã phải bơm nước từ một hồ gần đó để dập tắt đám cháy.)","The heart works continuously to [pump] blood throughout the human body. (=Dịch: Trái tim hoạt động liên tục để bơm máu đi khắp cơ thể con người.)","They used a special machine to [pump] the flooded water out of the basement. (=Dịch: Họ đã dùng một chiếc máy đặc biệt để bơm nước ngập ra khỏi tầng hầm.)"],"ukAudio":"/ai_services/tts3/?q=pump&lang=en-GB&ipa=%2Fp%CA%8Cmp%2F","usAudio":"/ai_services/tts3/?q=pump&lang=en-US&ipa=%2Fp%CA%8Cmp%2F"},{"id":"lv_9_58","topic":"Technology and Natural Sciences","word":"rebuild","pos":"(v)","ipa":"/ˌri.ˈbɪld/","defVi":"xây dựng lại, tái thiết","defEn":"to build something again after it has been damaged or destroyed","examples":["The government plans to [rebuild] the bridge after the flood. (=Dịch: Chính phủ có kế hoạch xây dựng lại cây cầu sau trận lũ lụt.)","It took many years for the city to [rebuild] its economy. (=Dịch: Phải mất nhiều năm thành phố mới tái thiết được nền kinh tế.)","They are trying to [rebuild] trust after a long period of conflict. (=Dịch: Họ đang cố gắng gầy dựng lại lòng tin sau một thời gian dài mâu thuẫn.)"],"ukAudio":"/ai_services/tts3/?q=rebuild&lang=en-GB&ipa=%2F%CB%8Cri.%CB%88b%C9%AAld%2F","usAudio":"/ai_services/tts3/?q=rebuild&lang=en-US&ipa=%2F%CB%8Cri.%CB%88b%C9%AAld%2F"},{"id":"lv_9_59","topic":"Technology and Natural Sciences","word":"refrigerate","pos":"(v)","ipa":"/rɪˈfrɪdʒ.ə.reɪt/","defVi":"bảo quản lạnh, giữ lạnh trong tủ lạnh","defEn":"to keep food or liquid cold so that it stays fresh","examples":["You should [refrigerate] the milk after opening to keep it fresh. (=Dịch: Bạn nên bảo quản sữa trong tủ lạnh sau khi mở nắp để giữ sữa được tươi.)","Some medicines must be [refrigerated] to maintain their effectiveness. (=Dịch: Một số loại thuốc phải được giữ lạnh để duy trì hiệu quả.)","Do not forget to [refrigerate] any leftover food within two hours. (=Dịch: Đừng quên cất thức ăn thừa vào tủ lạnh trong vòng hai giờ.)"],"ukAudio":"/ai_services/tts3/?q=refrigerate&lang=en-GB&ipa=%2Fr%C9%AA%CB%88fr%C9%AAd%CA%92.%C9%99.re%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=refrigerate&lang=en-US&ipa=%2Fr%C9%AA%CB%88fr%C9%AAd%CA%92.%C9%99.re%C9%AAt%2F"},{"id":"lv_9_60","topic":"Technology and Natural Sciences","word":"refrigeration","pos":"(n)","ipa":"/rɪˌfrɪdʒ.əˈreɪ.ʃən/","defVi":"sự làm lạnh, sự ướp lạnh, bảo quản lạnh","defEn":"the process of keeping food or other items cold to preserve them","examples":["Fresh meat must be kept under proper [refrigeration] to prevent spoilage. (=Dịch: Thịt tươi phải được bảo quản lạnh đúng cách để tránh bị hư hỏng.)","The development of modern [refrigeration] revolutionized the food industry. (=Dịch: Sự phát triển của kỹ thuật làm lạnh hiện đại đã cách mạng hóa ngành công nghiệp thực phẩm.)","Certain vaccines lose their effectiveness without continuous [refrigeration]. (=Dịch: Một số loại vắc-xin sẽ mất tác dụng nếu không được bảo quản lạnh liên tục.)"],"ukAudio":"/ai_services/tts3/?q=refrigeration&lang=en-GB&ipa=%2Fr%C9%AA%CB%8Cfr%C9%AAd%CA%92.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F","usAudio":"/ai_services/tts3/?q=refrigeration&lang=en-US&ipa=%2Fr%C9%AA%CB%8Cfr%C9%AAd%CA%92.%C9%99%CB%88re%C9%AA.%CA%83%C9%99n%2F"},{"id":"lv_9_61","topic":"Technology and Natural Sciences","word":"replicate","pos":"(v)","ipa":"/ˈrep.lɪ.keɪt/","defVi":"tái tạo, sao chép, làm lại y hệt","defEn":"to copy, repeat, or reproduce something exactly","examples":["Other researchers tried to [replicate] the laboratory experiment to confirm the results. (=Dịch: Các nhà nghiên cứu khác đã cố gắng tái tạo lại thí nghiệm trong phòng thí nghiệm để xác nhận kết quả.)","It is difficult to [replicate] the success of such a unique product. (=Dịch: Rất khó để lặp lại sự thành công của một sản phẩm độc đáo như vậy.)","The software allows users to [replicate] 3D designs with extreme accuracy. (=Dịch: Phần mềm này cho phép người dùng sao chép các thiết kế 3D với độ chính xác cực cao.)"],"ukAudio":"/ai_services/tts3/?q=replicate&lang=en-GB&ipa=%2F%CB%88rep.l%C9%AA.ke%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=replicate&lang=en-US&ipa=%2F%CB%88rep.l%C9%AA.ke%C9%AAt%2F"},{"id":"lv_9_62","topic":"Technology and Natural Sciences","word":"rescue","pos":"(n)","ipa":"/ˈres.kjuː/","defVi":"cuộc giải cứu, sự cứu hộ","defEn":"an act of saving someone or something from danger or harm","examples":["The coastguard carried out a daring sea [rescue] during the storm. (=Dịch: Lực lượng bảo vệ bờ biển đã thực hiện một cuộc cứu hộ trên biển đầy táo bạo trong cơn bão.)","Firefighters arrived just in time to assist with the [rescue] of the trapped residents. (=Dịch: Lính cứu hỏa đã đến kịp thời để hỗ trợ giải cứu những cư dân bị mắc kẹt.)","The animal [rescue] team helped find homes for hundreds of stray dogs. (=Dịch: Đội cứu hộ động vật đã giúp tìm nhà cho hàng trăm chú chó vô gia cư.)"],"ukAudio":"/ai_services/tts3/?q=rescue&lang=en-GB&ipa=%2F%CB%88res.kju%CB%90%2F","usAudio":"/ai_services/tts3/?q=rescue&lang=en-US&ipa=%2F%CB%88res.kju%CB%90%2F"},{"id":"lv_9_63","topic":"Technology and Natural Sciences","word":"rid","pos":"(v)","ipa":"/rɪd/","defVi":"loại bỏ, tống khứ, giải thoát","defEn":"to make someone or something free from an unwanted person or thing","examples":["They used special chemicals to [rid] the house of insects. (=Dịch: Họ đã dùng hóa chất đặc biệt để loại bỏ côn trùng ra khỏi nhà.)","He wanted to [rid] himself of all his old debts before buying a car. (=Dịch: Anh ấy muốn thanh toán hết nợ cũ trước khi mua một chiếc xe hơi.)","Regular exercise can help [rid] your body of stress and tension. (=Dịch: Tập thể dục thường xuyên có thể giúp cơ thể bạn giải tỏa căng thẳng và áp lực.)"],"ukAudio":"/ai_services/tts3/?q=rid&lang=en-GB&ipa=%2Fr%C9%AAd%2F","usAudio":"/ai_services/tts3/?q=rid&lang=en-US&ipa=%2Fr%C9%AAd%2F"},{"id":"lv_9_64","topic":"Technology and Natural Sciences","word":"robot","pos":"(n)","ipa":"/ˈroʊ.bɑːt/","defVi":"người máy, rô-bốt","defEn":"a machine controlled by a computer that can perform tasks automatically","examples":["The car factory uses an advanced [robot] to assemble engine parts. (=Dịch: Nhà máy ô tô sử dụng một người máy tiên tiến để lắp ráp các bộ phận động cơ.)","Scientists designed a small [robot] capable of exploring deep underwater caves. (=Dịch: Các nhà khoa học đã thiết kế một rô-bốt nhỏ có khả năng khám phá các hang động sâu dưới nước.)","This household [robot] can vacuum the floor and clean the windows. (=Dịch: Rô-bốt gia dụng này có thể hút bụi sàn nhà và lau cửa sổ.)"],"ukAudio":"/ai_services/tts3/?q=robot&lang=en-GB&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F","usAudio":"/ai_services/tts3/?q=robot&lang=en-US&ipa=%2F%CB%88ro%CA%8A.b%C9%91%CB%90t%2F"},{"id":"lv_9_65","topic":"Technology and Natural Sciences","word":"robotic","pos":"(adj)","ipa":"/roʊˈbɑː.tɪk/","defVi":"thuộc về người máy, tự động hóa","defEn":"connected with or produced by robots","examples":["Surgeons now use [robotic] arms to perform precise operations. (=Dịch: Các bác sĩ phẫu thuật hiện sử dụng cánh tay rô-bốt để thực hiện các ca mổ chính xác.)","The company invested heavily in [robotic] technology to boost productivity. (=Dịch: Công ty đã đầu tư mạnh vào công nghệ tự động hóa rô-bốt để nâng cao năng suất.)","He spoke in a cold, [robotic] tone that lacked any emotion. (=Dịch: Anh ấy nói với giọng điệu lạnh lùng, như người máy và thiếu cảm xúc.)"],"ukAudio":"/ai_services/tts3/?q=robotic&lang=en-GB&ipa=%2Fro%CA%8A%CB%88b%C9%91%CB%90.t%C9%AAk%2F","usAudio":"/ai_services/tts3/?q=robotic&lang=en-US&ipa=%2Fro%CA%8A%CB%88b%C9%91%CB%90.t%C9%AAk%2F"},{"id":"lv_9_66","topic":"Technology and Natural Sciences","word":"safely","pos":"(adv)","ipa":"/ˈseɪf.li/","defVi":"một cách an toàn","defEn":"in a way that is not dangerous or likely to cause harm","examples":["The pilot landed the airplane [safely] despite the heavy storm. (=Dịch: Phi công đã hạ cánh máy bay an toàn bất chấp cơn bão lớn.)","Please make sure your seatbelt is fastened [safely]. (=Dịch: Vui lòng đảm bảo rằng dây an toàn của bạn đã được cài chặt an toàn.)","The hikers arrived [safely] at the mountain base before dark. (=Dịch: Những người đi bộ đường dài đã đến chân núi an toàn trước khi trời tối.)"],"ukAudio":"/ai_services/tts3/?q=safely&lang=en-GB&ipa=%2F%CB%88se%C9%AAf.li%2F","usAudio":"/ai_services/tts3/?q=safely&lang=en-US&ipa=%2F%CB%88se%C9%AAf.li%2F"},{"id":"lv_9_67","topic":"Technology and Natural Sciences","word":"satellite","pos":"(n)","ipa":"/ˈsæt̬.əl.aɪt/","defVi":"vệ tinh","defEn":"an electronic device sent into space to gather information or transmit communications","examples":["Weather forecasters rely on [satellite] images to track incoming storms. (=Dịch: Các nhà dự báo thời tiết dựa vào hình ảnh vệ tinh để theo dõi những cơn bão sắp tới.)","The new telecommunications [satellite] was launched into space yesterday. (=Dịch: Vệ tinh viễn thông mới đã được phóng vào không gian ngày hôm qua.)","GPS navigation systems depend on a network of orbiting [satellites]. (=Dịch: Hệ thống định vị GPS phụ thuộc vào một mạng lưới các vệ tinh quay quanh quỹ đạo.)"],"ukAudio":"/ai_services/tts3/?q=satellite&lang=en-GB&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99l.a%C9%AAt%2F","usAudio":"/ai_services/tts3/?q=satellite&lang=en-US&ipa=%2F%CB%88s%C3%A6t%CC%AC.%C9%99l.a%C9%AAt%2F"},{"id":"lv_9_68","topic":"Technology and Natural Sciences","word":"solar","pos":"(adj)","ipa":"/ˈsoʊ.lɚ/","defVi":"(thuộc) mặt trời, năng lượng mặt trời","defEn":"relating to or coming from the sun","examples":["Many households are installing [solar] panels to reduce electricity bills. (=Dịch: Nhiều hộ gia đình đang lắp đặt các tấm pin mặt trời để giảm hóa đơn tiền điện.)","The Earth is the third planet from the sun in our [solar] system. (=Dịch: Trái Đất là hành tinh thứ ba tính từ mặt trời trong hệ mặt trời của chúng ta.)","The company invests heavily in [solar] energy research. (=Dịch: Công ty đầu tư mạnh vào nghiên cứu năng lượng mặt trời.)"],"ukAudio":"/ai_services/tts3/?q=solar&lang=en-GB&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F","usAudio":"/ai_services/tts3/?q=solar&lang=en-US&ipa=%2F%CB%88so%CA%8A.l%C9%9A%2F"},{"id":"lv_9_69","topic":"Technology and Natural Sciences","word":"sustainable","pos":"(adj)","ipa":"/səˈsteɪ.nə.bəl/","defVi":"bền vững, thân thiện với môi trường","defEn":"able to be maintained over time without harming the environment","examples":["We need to adopt more [sustainable] farming practices to protect the soil. (=Dịch: Chúng ta cần áp dụng các phương pháp canh tác bền vững hơn để bảo vệ đất đai.)","The company is committed to using [sustainable] packaging materials. (=Dịch: Công ty cam kết sử dụng các vật liệu đóng gói bền vững.)","Cycling is a [sustainable] form of urban transportation. (=Dịch: Đi xe đạp là một hình thức giao thông đô thị bền vững.)"],"ukAudio":"/ai_services/tts3/?q=sustainable&lang=en-GB&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=sustainable&lang=en-US&ipa=%2Fs%C9%99%CB%88ste%C9%AA.n%C9%99.b%C9%99l%2F"},{"id":"lv_9_70","topic":"Technology and Natural Sciences","word":"textile","pos":"(n)","ipa":"/ˈtɛks.taɪl/","defVi":"vải dệt, hàng dệt may","defEn":"any type of cloth or woven fabric","examples":["The country's economy relies heavily on the export of [textile] products. (=Dịch: Nền kinh tế của đất nước phụ thuộc rất lớn vào việc xuất khẩu các sản phẩm dệt may.)","Workers in the [textile] factory operate modern weaving machines every day. (=Dịch: Công nhân trong nhà máy dệt vận hành máy dệt hiện đại mỗi ngày.)","Museum visitors admired the intricate patterns of ancient Egyptian [textile] relics. (=Dịch: Khách tham quan bảo tàng đã chiêm ngưỡng những hoa văn tinh xảo của các di vật dệt may Ai Cập cổ đại.)"],"ukAudio":"/ai_services/tts3/?q=textile&lang=en-GB&ipa=%2F%CB%88t%C9%9Bks.ta%C9%AAl%2F","usAudio":"/ai_services/tts3/?q=textile&lang=en-US&ipa=%2F%CB%88t%C9%9Bks.ta%C9%AAl%2F"},{"id":"lv_9_71","topic":"Technology and Natural Sciences","word":"tribal","pos":"(adj)","ipa":"/ˈtraɪ.bəl/","defVi":"thuộc bộ lạc, bộ tộc","defEn":"relating to a tribe or a group of people sharing common ancestors, customs, and traditions","examples":["The anthropologists spent two years studying [tribal] customs in remote rainforests. (=Dịch: Các nhà nhân chủng học đã dành hai năm để nghiên cứu các phong tục bộ lạc ở những khu rừng nhiệt đới xa xôi.)","Traditional [tribal] music was played during the village's annual harvest festival. (=Dịch: Âm nhạc bộ tộc truyền thống đã được biểu diễn trong lễ hội thu hoạch hàng năm của ngôi làng.)","The elders act as leaders and make important decisions for the [tribal] community. (=Dịch: Các bô lão đóng vai trò là những người lãnh đạo và đưa ra các quyết định quan trọng cho cộng đồng bộ lạc.)"],"ukAudio":"/ai_services/tts3/?q=tribal&lang=en-GB&ipa=%2F%CB%88tra%C9%AA.b%C9%99l%2F","usAudio":"/ai_services/tts3/?q=tribal&lang=en-US&ipa=%2F%CB%88tra%C9%AA.b%C9%99l%2F"},{"id":"lv_9_72","topic":"Technology and Natural Sciences","word":"unwilling","pos":"(adj)","ipa":"/ʌnˈwɪl.ɪŋ/","defVi":"không sẵn lòng, miễn cưỡng","defEn":"not wanting to do something and refusing to do it","examples":["He was [unwilling] to admit that he had made a mistake. (=Dịch: Anh ấy không sẵn lòng thừa nhận rằng mình đã phạm sai lầm.)","Many employees were [unwilling] to work overtime without extra pay. (=Dịch: Nhiều nhân viên miễn cưỡng làm thêm giờ mà không có phụ cấp.)","She seemed [unwilling] to share any details about her personal life. (=Dịch: Cô ấy dường như không muốn chia sẻ bất kỳ chi tiết nào về cuộc sống cá nhân của mình.)"],"ukAudio":"/ai_services/tts3/?q=unwilling&lang=en-GB&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F","usAudio":"/ai_services/tts3/?q=unwilling&lang=en-US&ipa=%2F%CA%8Cn%CB%88w%C9%AAl.%C9%AA%C5%8B%2F"},{"id":"lv_9_73","topic":"Technology and Natural Sciences","word":"wool","pos":"(n)","ipa":"/wʊl/","defVi":"len, sợi len hoặc lông cừu","defEn":"the soft, thick hair that grows on the bodies of sheep and some other animals, used to make cloth or yarn","examples":["She knitted a warm sweater made of pure [wool] for her grandfather. (=Dịch: Cô ấy đã đan một chiếc áo len ấm áp bằng len nguyên chất cho ông của mình.)","Australia is known worldwide for its massive production of high-quality sheep [wool]. (=Dịch: Úc nổi tiếng khắp thế giới về sản lượng lông cừu chất lượng cao dồi dào.)","These blankets are blended with [wool] and synthetic fibers to keep costs low. (=Dịch: Những chiếc chăn này được pha trộn giữa len và sợi tổng hợp để giữ giá thành ở mức thấp.)"],"ukAudio":"/ai_services/tts3/?q=wool&lang=en-GB&ipa=%2Fw%CA%8Al%2F","usAudio":"/ai_services/tts3/?q=wool&lang=en-US&ipa=%2Fw%CA%8Al%2F"}]},"rawTopic":"Technology and Natural Sciences"}]};
